    Text = "Nhìn nhanh vào <Blue:góc dưới bên trái> của bộ chỉ lệnh! Chìa khóa bạc đã sẵn sàng, <Yellow:lệnh khóa> đã được kích hoạt."
  },
  AvgDialog_10141_Content_4 = {
    Text = "Giữ chặt chìa khóa bạc, hát mật văn… Thả ra <Yellow:lệnh khóa>, giành lấy nhiều không gian chiến thuật hơn cho tôi!"
  },
  AvgDialog_10142_Content_2 = {
    Text = "Đừng để phân tâm trong một nghi lễ quan trọng như vậy, <Yellow:Người Giữ Gìn>, người tiếp theo sẽ được trao chìa khóa bạc."
  },
  AvgDialog_10142_Content_3 = {
    Text = "Đặt mộ bia của chính mình, để chứng minh quyết tâm chúng ta đã <Yellow:đối đầu với rỗng rỗng> hiến dâng sức sống — đây không chỉ là truyền thống của Misaque, mà còn là dấu hiệu chúng ta kết thúc giai đoạn học tiền khoa và trở thành điều tra viên chính thức."
  },
  AvgDialog_10142_Content_4 = {
    Text = "Đã sẵn sàng rồi thì, hãy khắc tên của bạn lên bia mộ đi."
  },
  AvgDialog_116003_Content_1 = {
    Text = "Khi bức tranh của người rừng thuộc về bạn vỡ vụn, mọi thứ xung quanh cũng tan chảy trong sự méo mó."
  },
  AvgDialog_116003_Content_10 = {
    Text = "Nhưng tôi không mong điều này chỉ là một giấc mơ."
  },
  AvgDialog_116003_Content_11 = {
    Text = "Tôi muốn trở lại Mythag, muốn gặp lại họ."
  },
  AvgDialog_116003_Content_12 = {
    Text = "……câu trả lời như đã dự đoán."
  },
  AvgDialog_116003_Content_13 = {
    Text = "Nhưng lần này, sau khi bạn thể hiện quyết tâm của mình, tôi cuối cùng có thể yên tâm rồi."
  },
  AvgDialog_116003_Content_14 = {
    Text = "%player%, ý chí của bạn mạnh mẽ hơn tôi tưởng tượng, mạnh mẽ hơn… đủ để chống lại Hắn và sự hỗn loạn, điên loạn của thế giới này."
  },
  AvgDialog_116003_Content_15 = {
    Text = "Bạn lắc đầu, nhìn về phía Clementine trong giấc mơ sắp tan vỡ."
  },
  AvgDialog_116003_Content_16 = {
    Text = "Không, bạn đã sai, ý chí của một người cuối cùng cũng có giới hạn."
  },
  AvgDialog_116003_Content_17 = {
    Text = "Tôi có thể kiên trì đến bây giờ là nhờ vào mỗi người ủng hộ tôi ở Mythag."
  },
  AvgDialog_116003_Content_18 = {
    Text = "「Những người trong『 thế giới đó』 cùng nhau dựng lên giấc mơ đẹp này cho bạn, và bạn, quyết tâm trong thế giới này, biến giấc mơ này thành hiện thực.」"
  },
  AvgDialog_116003_Content_19 = {
    Text = "Nghe những lời của bạn, thấy vẻ mặt nghiêm túc của bạn, Clementine cười, lộ ra một nụ cười thư giãn."
  },
  AvgDialog_116003_Content_2 = {
    Text = "Bạn đã tự tay phá vỡ giấc mơ đẹp đẽ của mình."
  },
  AvgDialog_116003_Content_20 = {
    Text = "Đúng vậy, bạn còn \"họ\", còn Tawil... và tôi."
  },
  AvgDialog_116003_Content_21 = {
    Text = "Đúng vậy. Tôi chưa bao giờ đơn độc."
  },
  AvgDialog_116003_Content_22 = {
    Text = "Trong cảnh sắc không ngừng tan chảy, tiếng kêu vang lên, đó là câu trả lời cho lời nói của Tawil.\nCô ấy luôn ở đây."
  },
  AvgDialog_116003_Content_23 = {
    Text = "Vậy thì, bây giờ, %player%, giấc mơ đẹp của bạn thực sự đã kết thúc."
  },
  AvgDialog_116003_Content_24 = {
    Text = "Là một lời cảm ơn vì bạn đã hợp tác trong lần điều trị này, tôi đã tặng bạn một món quà nhỏ, hy vọng bạn thích."
  },
  AvgDialog_116003_Content_25 = {
    Text = "Cùng với lời nói cuối cùng của Clementine, giấc mơ hoàn toàn tan vỡ——"
  },
  AvgDialog_116003_Content_26 = {
    Text = "Bầu trời đen với mặt trời tối tăm xuất hiện trước mắt bạn, mang đến sương mù xám xịt, cùng với sự tàn khốc của thế giới này."
  },
  AvgDialog_116003_Content_27 = {
    Text = "Và lòng bàn tay của bạn, tĩnh lặng đặt một bức ảnh.\nMột bức ảnh chụp trong \"giấc mơ đẹp giả tạo\"， không nên tồn tại trong thực tế tàn khốc."
  },
  AvgDialog_116003_Content_28 = {
    Text = "Bờ biển, bóng chuyền, lễ hội, điều duy nhất khác với hồi ức là Ramona."
  },
  AvgDialog_116003_Content_29 = {
    Text = "Gương mặt quen thuộc mỉm cười tĩnh lặng, như thể đã vượt qua thời gian và không gian, nhìn vào bạn.\nDường như ngay trước mắt."
  },
  AvgDialog_116003_Content_3 = {
    Text = "Kể từ khi quyết định xây dựng giấc mơ này bằng sức mạnh của họ, tôi đã biết ngày này sẽ đến."
  },
  AvgDialog_116003_Content_30 = {
    Text = "<Small: Ramona……>"
  },
  AvgDialog_116003_Content_31 = {
    Text = "Bạn đặt tay lên bức ảnh, sự cảm động và nghi ngờ cùng trào dâng trong lòng."
  },
  AvgDialog_116003_Content_32 = {
    Text = "<Shake: Tại sao lại là Ramona……>"
  },
  AvgDialog_116003_Content_33 = {
    Text = "Nghi vấn của bạn không có đáp án.\nTrong thế giới đầy sương mù, chỉ có mặt trời đen lặng lẽ vẫn như xưa."
  },
  AvgDialog_116003_Content_34 = {
    Text = "Dù thế nào đi nữa......"
  },
  AvgDialog_116003_Content_35 = {
    Text = "Bạn đặt bức ảnh lên trước ngực, vị trí của trái tim, nhắm mắt lại."
  },
  AvgDialog_116003_Content_36 = {
    Text = "Dù thế nào đi nữa, tôi cũng không đơn độc."
  },
  AvgDialog_116003_Content_37 = {
    Text = "Sau đó, bạn mở mắt, nhìn về phía mặt trời màu đen treo cao, từng bước vững chắc tiến tới."
  },
  AvgDialog_116003_Content_38 = {
    Text = "Thế giới này vẫn đang sụp đổ, bị nhìn chằm chằm bởi nỗi kinh hoàng không thể mô tả, nguy hiểm cận kề, nhưng……"
  },
  AvgDialog_116003_Content_39 = {
    Text = "<Big:Cuối cùng bạn sẽ tìm ra cách để cứu nó>"
  },
  AvgDialog_116003_Content_4 = {
    Text = "Tôi chỉ không ngờ rằng nó lại đến nhanh như vậy, và cũng không ngờ bạn lại quyết tâm như thế."
  },
  AvgDialog_116003_Content_5 = {
    Text = "Thực ra... Tôi đã do dự, cũng đã trốn tránh. Khi ở bên bờ biển."
  },
  AvgDialog_116003_Content_6 = {
    Text = "Vậy tại sao không tiếp tục chìm đắm trong đó? Có phải nơi đây không đủ đẹp, không đủ hạnh phúc?"
  },
  AvgDialog_116003_Content_7 = {
    Text = "Bạn lặng lẽ, hồi tưởng về bức tranh của người cây của mình."
  },
  AvgDialog_116003_Content_8 = {
    Text = "Không thể phủ nhận, đây thực sự là một giấc mơ đẹp. Nhưng......"
  },
  AvgDialog_116003_Content_9 = {
    Text = "Dần dần, cảnh tượng trong đầu bạn không còn là hội họa, mà là thực sự là Mythag, thực sự là Búp bê, Ramona, Lotan và Ogier."
  },
  AvgDialog_117499_Content_1 = {
    Text = "<Shake:Quá nhiều……>"
  },
  AvgDialog_117499_Content_2 = {
    Text = "Dưới bầu trời ảm đạm, những cơn gió điên cuồng của đàn cá dường như không bao giờ ngừng lại. Bạn nhìn xung quanh, góc nào đó treo một chiếc thang kim loại rỉ sét, bạn cẩn thận leo lên nền tầng hai theo nó."
  },
  AvgDialog_117499_Content_3 = {
    Text = "Ở đây có thể tạm thời trú ẩn."
  },
  AvgDialog_117499_Content_4 = {
    Text = "Một khí tức kỳ quái cùng với âm thanh ma sát chói tai đã thu hút sự chú ý của bạn."
  },
  AvgDialog_117499_Content_5 = {
    Text = "Chờ một chút, bên kia là..."
  },
  AvgDialog_117500_Content_1 = {Text = "Xích"},
  AvgDialog_117500_Content_100 = {
    Text = "Murphy lắc đầu trong thất vọng, đôi mắt vô hồn rỗng tuếch tìm kiếm vị trí của bạn.\nCô hướng về bạn, môi mỏng kẹp chặt vì thiếu máu nứt nẻ, miễn cưỡng nở một nụ cười bi thảm."
  },
  AvgDialog_117500_Content_101 = {
    Text = "Bạn đã đến... tôi còn tưởng... tôi sẽ không bao giờ gặp lại bạn..."
  },
  AvgDialog_117500_Content_102 = {
    Text = "Thân tàu đột ngột nghiêng mạnh, nước muối lạnh ngắt ào ạt tràn vào khoang."
  },
  AvgDialog_117500_Content_103 = {
    Text = "Chuyện gì vậy ?!"
  },
  AvgDialog_117500_Content_104 = {
    Text = "Tàu va phải đá ngầm?"
  },
  AvgDialog_117500_Content_105 = {
    Text = "Không thể, thân tàu của tàu Palades rất nặng, ngay cả khi khoang tàu bị rạn nứt và rò rỉ nước, cũng không thể ngập đến tầng trên trong thời gian ngắn như vậy…"
  },
  AvgDialog_117500_Content_106 = {
    Text = "Trừ khi…"
  },
  AvgDialog_117500_Content_107 = {
    Text = "William chạy về phía cửa sổ, khung cảnh trước mắt như những ảo tưởng điên rồ nhất. Con tàu Paradis đang chìm với tốc độ không thể tin được."
  },
  AvgDialog_117500_Content_108 = {
    Text = "Như thể con cá voi khổng lồ đang kéo thuyền nhỏ, có một lực lượng khổng lồ không thể phản kháng, đang kéo tàu Paladise, không chút do dự rơi nhanh xuống đáy biển."
  },
  AvgDialog_117500_Content_109 = {Text = "À——"},
  AvgDialog_117500_Content_11 = {
    Text = "Bạn mở mắt ra lần nữa. Mềm mại, ấm áp, như đã từng quen thuộc."
  },
  AvgDialog_117500_Content_110 = {
    Text = "Dưới sự rung động mạnh mẽ, chuỗi xích xuyên thấu lòng bàn tay của Murphy bỗng đứt gãy."
  },
  AvgDialog_117500_Content_111 = {
    Text = "Bàn tay mềm mại ướt át chạm vào mu bàn tay bạn, cô ấy chịu đựng cơn đau của vết thương xuyên lòng bàn tay, nhẹ nhàng nắm lấy tay bạn, ánh mắt gặp nhau."
  },
  AvgDialog_117500_Content_112 = {
    Text = "Cô thỏ thẻ, lời nói thoát ra mang theo mùi hơi sắt, không biết do nước biển hay máu."
  },
  AvgDialog_117500_Content_113 = {
    Text = "Cứu tôi…… Nếu là bạn, chắc chắn có thể……"
  },
  AvgDialog_117500_Content_114 = {
    Text = "Những lời nói cuối cùng, cùng với nước biển ngập chìm khoang tàu, cũng chìm vào bóng tối."
  },
  AvgDialog_117500_Content_12 = {
    Text = "<Small:Xì, chúng ta thực sự phải chờ tên này tỉnh dậy sao?>"
  },
  AvgDialog_117500_Content_13 = {
    Text = "<Small:Goliath, không được nghi vấn mệnh lệnh của Mẹ Thần.>"
  },
  AvgDialog_117500_Content_14 = {
    Text = "<Small:Cẩn thận một chút, đại nhân Goliath, sáng nay, Mẹ Thần đã triệu tập công tước để khiển trách một hồi lâu……>"
  },
  AvgDialog_117500_Content_15 = {
    Text = "Âm thanh cãi vã với giọng nói thấp vang lên từ bên ngoài màn chắn."
  },
  AvgDialog_117500_Content_16 = {Text = "Ho, ho…"},
  AvgDialog_117500_Content_17 = {
    Text = "Bạn đã tỉnh dậy? Mọi người đang đợi bạn."
  },
  AvgDialog_117500_Content_18 = {
    Text = "Faros đã bắt đầu dệt màn che."
  },
  AvgDialog_117500_Content_19 = {
    Text = "Tôi…… lại được cứu lên rồi sao?"
  },
  AvgDialog_117500_Content_2 = {
    Text = "……Nhện?"
  },
  AvgDialog_117500_Content_20 = {
    Text = "Gã không chết trong đại nạn. Chúng tôi không có nghĩa vụ giải đáp tất cả nghi vấn của bạn."
  },
  AvgDialog_117500_Content_21 = {
    Text = "Theo lệnh của Thần Mẹ, Thủy thủ đã chờ đợi sự tỉnh dậy của bạn từ rất lâu."
  },
  AvgDialog_117500_Content_22 = {
    Text = "Đây là nước chanh đã được thần mẫu sai tôi vắt sẵn. Hãy uống hết với lòng biết ơn, con người."
  },
  AvgDialog_117500_Content_23 = {
    Text = "Nếu Ngài đã bình an vô sự, thì tôi sẽ trở lại vị trí dẫn đường thôi. Vương quốc Thần đang gọi tôi."
  },
  AvgDialog_117500_Content_25 = {
    Text = "……………"
  },
  AvgDialog_117500_Content_26 = {
    Text = "Đó là chuyện thật, hay là cơn ác mộng khi tôi bị nước nhấn chìm..."
  },
  AvgDialog_117500_Content_27 = {
    Text = "(Phải tìm cách xác minh một chút.)"
  },
  AvgDialog_117500_Content_28 = {
    Text = "Nếu tôi không nhớ nhầm, người mà tôi nhìn thấy cuối cùng..."
  },
  AvgDialog_117500_Content_29 = {
    Text = "Bạn đã đặt chân lên boong tàu."
  },
  AvgDialog_117500_Content_3 = {
    Text = "Một chú nhện nhỏ màu tím tối nhìn bạn với đôi mắt to. Khi thấy bạn tỉnh dậy, nó nhấc chân trước lên, chào bạn."
  },
  AvgDialog_117500_Content_30 = {
    Text = "<Shake:Này——anh William——>"
  },
  AvgDialog_117500_Content_31 = {
    Text = "<Shake:Đừng trốn tránh——tôi biết bạn ở đây——>"
  },
  AvgDialog_117500_Content_32 = {
    Text = "Chỉ có tiếng thủy triều yên tĩnh trên boong, tiếng gọi của bạn hòa vào sương mù buổi sáng."
  },
  AvgDialog_117500_Content_33 = {
    Text = "(Thôi, hóa ra chỉ là giấc mơ của tôi mà thôi...)"
  },
  AvgDialog_117500_Content_34 = {Text = "Ùa——!"},
  AvgDialog_117500_Content_35 = {
    Text = "Cánh cửa giấu kín dưới chân bạn bỗng mở ra, bạn rơi \"bịch\" vào một mảnh tối."
  },
  AvgDialog_117500_Content_36 = {
    Text = "Một đống rơm giảm thiểu lực tác động khi bạn rơi xuống."
  },
  AvgDialog_117500_Content_37 = {
    Text = "Lâu rồi không gặp, người giữ gìn."
  },
  AvgDialog_117500_Content_38 = {
    Text = "Bạn biết tôi…… bạn là tiền bối William từ thế giới trước đây……"
  },
  AvgDialog_117500_Content_39 = {
    Text = "William không để ý đến giọng điệu ngạc nhiên của bạn, trái lại vẻ mặt lại trở nên nặng nề."
  },
  AvgDialog_117500_Content_4 = {
    Text = "Từng lớp voan mỏng và vải nhung chồng chất lên boong tàu rỉ sét. Người phụ nữ cầm bánh xe quay mắt nhìn bạn chằm chằm."
  },
  AvgDialog_117500_Content_40 = {
    Text = "Tôi không nhớ đã từng dạy ngươi cách hành xử nổi bật như vậy trong sào huyệt của kẻ thù trong Mithag."
  },
  AvgDialog_117500_Content_41 = {
    Text = "Ngay cả viện trưởng Czort nổi tiếng với sự liều lĩnh, có lẽ cũng sẽ không ủng hộ lựa chọn của bạn."
  },
  AvgDialog_117500_Content_42 = {
    Text = "Hơi thở quen thuộc của tuyết tùng, dáng người ngay ngắn quen thuộc, giọng điệu nghiêm khắc quen thuộc."
  },
  AvgDialog_117500_Content_43 = {
    Text = "Học trưởng William..."
  },
  AvgDialog_117500_Content_44 = {
    Text = "Trước khi giải quyết vấn đề then chốt, tôi không định xuất hiện trước mặt bạn."
  },
  AvgDialog_117500_Content_45 = {
    Text = "Nhưng sự bất cẩn của bạn khiến tôi phải thay đổi chiến lược."
  },
  AvgDialog_117500_Content_46 = {
    Text = "Bạn có biết tôi luôn theo đuổi bạn không?"
  },
  AvgDialog_117500_Content_47 = {
    Text = "William không trả lời câu hỏi này, chỉ nhìn bạn bằng ánh mắt sắc bén như nói rằng \"Bạn nghĩ tôi là đồ ngốc à\"."
  },
  AvgDialog_117500_Content_48 = {
    Text = "Chúng tôi đã ở trên cùng một chiếc thuyền, khó mà tránh khỏi. Không bằng tôi nói rõ tình huống, để tránh những rắc rối không cần thiết."
  },
  AvgDialog_117500_Content_49 = {
    Text = "Trước đó, bạn có thể giúp tôi chia sẻ thông tin mà bạn nắm giữ không?"
  },
  AvgDialog_117500_Content_5 = {
    Text = "Lần này, cô ấy không thở dài, cũng không nói gì, chỉ im lặng."
  },
  AvgDialog_117500_Content_51 = {
    Text = "……………"
  },
  AvgDialog_117500_Content_52 = {
    Text = "Từ khi bị đúc thành não băng từ Búp bê, đến bị giam giữ trong nhà thương tâm thần của Clementine, rồi đến phong cảnh của thành phố chôn xác, cuối cùng là những \"cơn ác mộng\" trải nghiệm trên chiếc Parades."
  },
  AvgDialog_117500_Content_53 = {
    Text = "Bạn sẽ kể lại từng trải nghiệm của mình, William nghiêng đầu chăm chú lắng nghe, thỉnh thoảng gật đầu để chỉ thị rằng anh đang tập trung."
  },
  AvgDialog_117500_Content_54 = {
    Text = "Khi nhắc đến William thời thơ ấu mà bạn đã gặp, bạn do dự trong giây lát, nhưng William chỉ vẫy tay ra hiệu bạn tiếp tục."
  },
  AvgDialog_117500_Content_55 = {
    Text = "Thông tin bạn cung cấp rất hữu ích."
  },
  AvgDialog_117500_Content_56 = {
    Text = "William học trưởng, bây giờ có thể cho tôi biết bạn đang theo đuổi điều gì không?"
  },
  AvgDialog_117500_Content_57 = {
    Text = "William trầm tư một hồi lâu."
  },
  AvgDialog_117500_Content_58 = {
    Text = "Để tôi nghĩ xem tôi nên bắt đầu từ đâu."
  },
  AvgDialog_117500_Content_59 = {
    Text = "Kể từ khi rơi vào thế giới này, tôi đã luôn khám phá hai câu hỏi: Tại sao tôi lại rơi vào đây và làm thế nào để trở về thế giới ban đầu của mình?"
  },
  AvgDialog_117500_Content_6 = {
    Text = "Tại sao, tôi nhớ rõ ràng rằng mình đã bị bao vây bởi vô số Thủy thủ, rồi…"
  },
  AvgDialog_117500_Content_60 = {
    Text = "William trang trọng lấy ra một chiếc chìa khóa bạc quý giá từ ngực, ánh mắt anh lộ ra một chút hoài niệm."
  },
  AvgDialog_117500_Content_61 = {
    Text = "Chìa khóa bạc này là tôi tự tay phục hồi, đến từ người đồng nghiệp cũ Fingo... luôn có người nói rằng tôi là điều tra viên huyền thoại nhất của Mythag, nhưng với tôi đó chỉ là vì ông ấy qua đời trẻ."
  },
  AvgDialog_117500_Content_62 = {
    Text = "Cho đến khi rơi vào không gian này, tôi mới hiểu, anh ta chỉ là một người sớm nhìn thấy bản chất của thế giới, đã chiến đấu trên mặt trận tiền tuyến chống lại sự phân rã, như một người đi tiên phong."
  },
  AvgDialog_117500_Content_63 = {
    Text = "Anh ta đã truy lùng đến bí mật của sự kết nối giữa hai thế giới và để lại một manh mối quan trọng — một bức tượng ngà."
  },
  AvgDialog_117500_Content_64 = {
    Text = "Cũng như thường lệ, anh ấy luôn đi trước tôi một bước."
  },
  AvgDialog_117500_Content_65 = {
    Text = "Sắc mặt William đột nhiên trầm xuống, anh lắc đầu rồi thu lại chìa khóa bạc vào ngực."
  },
  AvgDialog_117500_Content_66 = {
    Text = "……Bạn có thấy cái tượng ngà trên tay Miryam hoặc Murphy không?"
  },
  AvgDialog_117500_Content_67 = {
    Text = "Bạn gật gật đầu."
  },
  AvgDialog_117500_Content_68 = {
    Text = "Nếu mọi thứ phát triển giống như lần trước, trên boong tàu ngay trên đầu chúng ta, Murphy đang sử dụng bức tượng này để tổ chức nghi lễ."
  },
  AvgDialog_117500_Content_69 = {
    Text = "Tượng khắc bằng ngà voi dường như có một mối liên hệ sâu sắc với bản chất của thế giới này."
  },
  AvgDialog_117500_Content_7 = {
    Text = "Bạn cảm nhận được cơ thể của mình. Mặc dù cơn đau ảo vẫn còn đó, nhưng bề mặt cơ thể bạn không để lại bất kỳ vết thương nào, trận chiến trước hôn mê dường như hoàn toàn không xảy ra."
  },
  AvgDialog_117500_Content_70 = {
    Text = "Vậy, để trở về, có lẽ chúng ta phải lấy được bức tượng ngà và thực hiện phân tích và nghiên cứu."
  },
  AvgDialog_117500_Content_71 = {
    Text = "Sau khi nghi lễ kết thúc, tượng ngà sẽ quay về phòng của Murphy…"
  },
  AvgDialog_117500_Content_72 = {
    Text = "Bên trong rất yên tĩnh, theo lý mà nói thì mọi người đều không ở bên trong……"
  },
  AvgDialog_117500_Content_73 = {
    Text = "Hãy cẩn thận, chúng ta cố gắng tránh những xung đột không cần thiết."
  },
  AvgDialog_117500_Content_74 = {
    Text = "Thôi nào, chúng ta hãy nhìn lén một cái."
  },
  AvgDialog_117500_Content_75 = {
    Text = "Bạn nhẹ nhàng đẩy cửa phòng."
  },
  AvgDialog_117500_Content_77 = {
    Text = "Luồng không khí lẫn mùi khó chịu chui vào mũi bạn, bạn nhận ra mình đã vô tình hít một hơi thật sâu."
  },
  AvgDialog_117500_Content_78 = {
    Text = "Có chuyện gì vậy?"
  },
  AvgDialog_117500_Content_79 = {Text = "Âm thanh."},
  AvgDialog_117500_Content_8 = {
    Text = "Đó là... cơn ác mộng sao?"
  },
  AvgDialog_117500_Content_80 = {
    Text = "Trong căn phòng yên tĩnh cuối cùng cũng vang lên âm thanh."
  },
  AvgDialog_117500_Content_81 = {
    Text = "Âm thanh của giọt nước."
  },
  AvgDialog_117500_Content_82 = {
    Text = "Tích tắc, tích tắc, âm thanh nước nhỏ giọt vào vũng nước nhỏ mới hình thành."
  },
  AvgDialog_117500_Content_83 = {
    Text = "Tám dây xích căng thẳng từ tay chân của Murphy nối dài, buộc chặt cô ấy lại.\nNgực của cô ấy bị khoét một lỗ lớn đầy máu."
  },
  AvgDialog_117500_Content_84 = {
    Text = "Máu chảy xuống vết thương đau đớn, nhỏ xuống một vũng máu đang dần hình thành, đó chính là nguồn gốc của âm thanh “tích tắc” vọng lại bên tai bạn."
  },
  AvgDialog_117500_Content_85 = {Text = "Murphy…!"},
  AvgDialog_117500_Content_86 = {
    Text = "Bạn đến quá muộn."
  },
  AvgDialog_117500_Content_87 = {
    Text = "Trái tim như bị một bàn tay vô hình nắm chặt, cơn đau quen thuộc, ngạt thở kèm theo các mảnh ký ức nhanh chóng đâm vào."
  },
  AvgDialog_117500_Content_88 = {
    Text = "Ánh sáng chói lóa làm đau mắt, khiến người ta không kìm được mà rơi lệ."
  },
  AvgDialog_117500_Content_89 = {
    Text = "Dòng lỏng đục chảy hết, đôi mắt cuối cùng cũng có thể hướng về cô gái lần nữa."
  },
  AvgDialog_117500_Content_9 = {
    Text = "Người phụ nữ gật đầu không âm thanh, hình bóng của cô tan biến trong làn sương mờ ảo."
  },
  AvgDialog_117500_Content_90 = {
    Text = "Lưỡi dao chìm sâu vào ngực, cô gái tắm mình trong ánh trăng mở mắt ra."
  },
  AvgDialog_117500_Content_91 = {
    Text = "Trăng tròn tượng trưng cho cái chết đang gần kề, nhưng gương mặt trẻ trung không hề tỏ ra sợ hãi."
  },
  AvgDialog_117500_Content_92 = {
    Text = "Tôi đã làm được… Tôi đã thật sự làm được!"
  },
  AvgDialog_117500_Content_93 = {
    Text = "Tôi……đã xuyên thủng……Ngài sẽ không bao giờ được sinh ra nữa……"
  },
  AvgDialog_117500_Content_94 = {
    Text = "Như vậy……"
  },
  AvgDialog_117500_Content_95 = {
    Text = "Tay nắm chặt chuôi dao buông thõng xuống, chất lỏng đỏ tươi, sánh đặc và đen ngòm từ lưỡi dao tuôn ra, len qua kẽ tay rồi tan vào đại dương."
  },
  AvgDialog_117500_Content_96 = {Text = "Ho, ho…"},
  AvgDialog_117500_Content_97 = {
    Text = "Bạn là... người trong giấc mơ..."
  },
  AvgDialog_117500_Content_98 = {
    Text = "Bạn đừng nói gì trước đã! Để tôi giúp bạn…"
  },
  AvgDialog_117500_Content_99 = {
    Text = "Bạn khẩn trương cố gắng nhưng không có kết quả, dây xích phát ra âm thanh thổn thức nhỏ nhẹ theo những cơn co thắt đau đớn của Murphy."
  },
  AvgDialog_117501_Content_10 = {
    Text = "Mẹ Thần sao lại hỏi như vậy?"
  },
  AvgDialog_117501_Content_11 = {
    Text = "Tối qua, tôi đã có một giấc mơ."
  },
  AvgDialog_117501_Content_12 = {
    Text = "Trong giấc mơ, tôi đã sử dụng cái dao nghi lễ đó......"
  },
  AvgDialog_117501_Content_13 = {
    Text = "Cô chỉ tay vào con dao găm mà Miryam luôn mang bên mình.\nLưỡi dao phát ánh sáng lung linh, tỏa ra ánh sáng ma quái như bị độc."
  },
  AvgDialog_117501_Content_14 = {
    Text = "Xuyên thấu ngực mình."
  },
  AvgDialog_117501_Content_15 = {
    Text = "\"Ngài sẽ không xuất hiện nữa...\""
  },
  AvgDialog_117501_Content_16 = {
    Text = "Murphy thì thầm, ngón tay nhẹ nhàng lướt qua vết sẹo đầy máu trên ngực."
  },
  AvgDialog_117501_Content_17 = {
    Text = "Đó là cơn ác mộng ảo ảnh."
  },
  AvgDialog_117501_Content_18 = {
    Text = "Miryam tiến lại gần, quỳ trước đầu gối của Murphy, nhẹ nhàng xoa lên mu bàn tay cô ấy để an ủi."
  },
  AvgDialog_117501_Content_19 = {
    Text = "Yên tâm đi, mong muốn của thủy thủ đã được hoàn thành, Ngài ấy tồn tại, Ngài ấy đã đến thế giới này."
  },
  AvgDialog_117501_Content_2 = {
    Text = "bisikan mimpi"
  },
  AvgDialog_117501_Content_20 = {
    Text = "Và bạn và tôi cuối cùng sẽ đến được vùng đất thần thánh vĩnh cửu, chia sẻ vinh quang thần thánh trước ngai vàng của Ngài."
  },
  AvgDialog_117501_Content_21 = {
    Text = "Lời nói của cô giống như lời cầu nguyện trước bàn thờ, tràn đầy sự tôn kính và thành kính."
  },
  AvgDialog_117501_Content_22 = {
    Text = "Nếu chúng ta không thể đến Vùng đất thần thánh thì sao? Ý tôi là nếu..."
  },
  AvgDialog_117501_Content_23 = {
    Text = "Miryam ngay lập tức cắt ngang câu hỏi do dự của Murphy."
  },
  AvgDialog_117501_Content_24 = {
    Text = "Trong lời tiên tri của Thần Vương không có thông tin như vậy.\nKhoảnh khắc liên kết tiếp theo sẽ vào ngày mai, máu của Ngài chắc chắn sẽ dẫn dắt chúng ta đến vùng đất hứa."
  },
  AvgDialog_117501_Content_25 = {
    Text = "Murphy nhíu mày."
  },
  AvgDialog_117501_Content_26 = {
    Text = "Tôi sẽ nghỉ ngơi một chút, Miryam, cậu cũng về nghỉ ngơi đi."
  },
  AvgDialog_117501_Content_27 = {
    Text = "Tôi sẽ cầu nguyện cho mẹ thần tới bình minh, cầu xin bà một giấc ngủ ngon suốt đêm."
  },
  AvgDialog_117501_Content_28 = {
    Text = "Murphy không trả lời, ánh mắt sâu thẳm theo dõi bóng lưng của Miryam cho đến khi âm thanh cánh cửa đóng lại phát ra."
  },
  AvgDialog_117501_Content_29 = {
    Text = "Cô ấy quay lưng lại với bàn thờ trong bóng tối, nhắm mắt cầu nguyện."
  },
  AvgDialog_117501_Content_3 = {
    Text = "Thần Mẹ quý giá, bạn lại đang nhìn vào ánh đèn ở đây."
  },
  AvgDialog_117501_Content_30 = {
    Text = "Ngày mai, ngày liên kết…"
  },
  AvgDialog_117501_Content_31 = {
    Text = "Vật kỳ quái được dâng lên bàn thờ không mang lại phản ứng nào cho bà, im lặng như hóa thạch dưới lớp băng.\nMurphy mở mắt với vẻ quyết tâm."
  },
  AvgDialog_117501_Content_32 = {
    Text = "Để tiếp tục giấc mơ này…"
  },
  AvgDialog_117501_Content_33 = {
    Text = "Cô duỗi cánh tay mảnh dẻ bị che phủ bởi lớp voan đen dày, giơ cao con dao nghi lễ lên——"
  },
  AvgDialog_117501_Content_34 = {
    Text = "Dưới ánh nến phản chiếu, bóng dao đâm mạnh vào cái nôi đang ngủ trên bàn thờ."
  },
  AvgDialog_117501_Content_35 = {
    Text = "Bụp bụp một tiếng, âm thanh chất thịt dính dính bị xuyên thấu vang lên.\nChất lỏng đen đặc dần dần lan rộng, ướt sũng trên chiếc nôi nhung với những ký tự Thủy thủ nổi bật."
  },
  AvgDialog_117501_Content_36 = {
    Text = "Một đêm nữa sắp sửa hạ xuống..."
  },
  AvgDialog_117501_Content_37 = {
    Text = "Cô thở phào như nhẹ nhõm, nhắm mắt lại, nhưng không phải là bóng tối vô tận mà là giấc mơ hôm qua."
  },
  AvgDialog_117501_Content_39 = {
    Text = "(Thời khắc xuyên thấu ngực, người xuất hiện bên cạnh tôi...)"
  },
  AvgDialog_117501_Content_4 = {
    Text = "Hãy nghỉ ngơi sớm thôi, mai là ngày liên kết, còn cần bạn dùng máu thánh chỉ cho thủy thủ con đường phía trước."
  },
  AvgDialog_117501_Content_40 = {
    Text = "(Có vẻ như chưa bao giờ gặp, nhưng lại có chút nhớ thương...)"
  },
  AvgDialog_117501_Content_41 = {
    Text = "……Nhện?"
  },
  AvgDialog_117501_Content_42 = {
    Text = "Một chú nhện nhỏ màu tím tối nhìn bạn với đôi mắt to trên cột buồm. Khi thấy bạn tỉnh dậy, nó nhấc chân trước lên, chào bạn."
  },
  AvgDialog_117501_Content_43 = {
    Text = "Trong giấc mơ, tôi dường như nghe thấy tiếng hát......"
  },
  AvgDialog_117501_Content_44 = {
    Text = "Mơ hồ, mềm mại, như giọng hát của một nàng tiên cá đang ngâm thơ, vòng quanh bên tai bạn không ngừng."
  },
  AvgDialog_117501_Content_45 = {
    Text = "Những người con bi thảm, định mệnh đã dệt nên những sợi chỉ, các bạn cuối cùng sẽ bước lên hành trình đã định sẵn."
  },
  AvgDialog_117501_Content_46 = {
    Text = "Và bạn, vị khách đến từ chiều không gian khác ——"
  },
  AvgDialog_117501_Content_47 = {
    Text = "Vào thời khắc liên kết của các vì sao, xin hãy ghi dấu kết thúc cho vòng lặp bi kịch."
  },
  AvgDialog_117501_Content_48 = {
    Text = "Cùng với một tiếng thở dài kéo dài, bóng ma của người phụ nữ biến mất không thấy."
  },
  AvgDialog_117501_Content_49 = {Text = "?！"},
  AvgDialog_117501_Content_5 = {
    Text = "Murphy chăm chú nhìn ngọn lửa nhảy múa trong đèn, khăn voan đen rung rinh theo chuyển động của cô, kéo dài thành những ảo ảnh như màn trên bức tường cabin tàu."
  },
  AvgDialog_117501_Content_50 = {
    Text = "Cảm giác hoảng sợ thoáng chốc tan biến, bạn mới bình tĩnh lại để quan sát môi trường xung quanh."
  },
  AvgDialog_117501_Content_51 = {
    Text = "Tôi…… đang ở đâu?"
  },
  AvgDialog_117501_Content_52 = {
    Text = "Chiếc đệm mềm mại. Không gian an toàn được che phủ bởi vải đen. Không khí thoang thoảng hương xạ hương và mùi hương của nhang trầm."
  },
  AvgDialog_117501_Content_53 = {
    Text = "Trước điều này...... tôi......"
  },
  AvgDialog_117501_Content_54 = {
    Text = "Doll! Có nhận được tín hiệu không? Doll?"
  },
  AvgDialog_117501_Content_55 = {
    Text = "Đừng la hét, bạn làm tôi nhiễu loạn tín hiệu giọng nói."
  },
  AvgDialog_117501_Content_56 = {
    Text = "Tôi đã đuổi kịp con tàu mà ngư dân nói rằng William đã lên! Nhưng nó đã trôi vào cơn bão!"
  },
  AvgDialog_117501_Content_57 = {
    Text = "Câu tiếp theo là…"
  },
  AvgDialog_117501_Content_58 = {
    Text = "Tôi sẽ đuổi theo vào trong!"
  },
  AvgDialog_117501_Content_59 = {
    Text = "Chỉ với chiếc thuyền đánh cá nhỏ này? Lao vào hố sâu của quần đảo Bermuda? Không sợ lật úp sao?"
  },
  AvgDialog_117501_Content_6 = {
    Text = "Miryam, bạn đã từng mơ chưa?"
  },
  AvgDialog_117501_Content_60 = {
    Text = "Không thể mất dấu vết nữa, đây là thông tin duy nhất thực sự hiệu quả mà chúng tôi đã gặp trong vài tháng qua!"
  },
  AvgDialog_117501_Content_61 = {
    Text = "Nguyện rằng chìa khóa bạc sẽ chỉ đường phía trước!"
  },
  AvgDialog_117501_Content_62 = {
    Text = "Không có câu \"Nguyện chìa khóa bạc dẫn đường cho chúng ta\" mà bạn lẽ ra phải nghe, thay vào đó là tiếng điện bị ngắt kết nối."
  },
  AvgDialog_117501_Content_63 = {
    Text = "Đang chờ đón bạn là những cơn sóng khổng lồ cao ngàn thước, và ngay sau đó, là bóng tối vô tận bị nuốt chửng—"
  },
  AvgDialog_117501_Content_64 = {
    Text = "Ba tháng trước, theo dấu vết của người đàn ông tóc vàng bí ẩn khởi hành từ cảng Innsmouth, bạn đã lần mò tìm kiếm William."
  },
  AvgDialog_117501_Content_65 = {
    Text = "Gần đây, bạn cuối cùng đã thấy cờ thuyền mà ngư dân mô tả trên mặt biển, nhưng đã bị cơn bão bất ngờ cướp đi hướng đi."
  },
  AvgDialog_117501_Content_66 = {
    Text = "Một lần nữa mở mắt ra, chính là cảnh tượng trước mắt."
  },
  AvgDialog_117501_Content_67 = {
    Text = "Bạn đã tỉnh dậy? Mọi người đang đợi bạn."
  },
  AvgDialog_117501_Content_68 = {
    Text = "Bức màn đen được nâng nhẹ nhàng, âm thanh nữ giới quen thuộc mà lạ lùng dội đến."
  },
  AvgDialog_117501_Content_69 = {
    Text = "Mọi người…? Ai…?"
  },
  AvgDialog_117501_Content_7 = {
    Text = "Đương nhiên là đã từng. Trong hàng triệu giấc mơ, Lemuria vĩ đại đã nổi lên từ hải vực, tái hiện dưới ánh nắng mặt trời."
  },
  AvgDialog_117501_Content_70 = {
    Text = "Bốn gương mặt quen thuộc kỳ quái vây quanh trước giường của bạn."
  },
  AvgDialog_117501_Content_71 = {
    Text = "Theo lệnh của Thần Mẹ, Thủy thủ đã chờ đợi sự tỉnh dậy của bạn từ rất lâu. Nào, hãy uống chén thuốc tốt mà Thần Mẹ đã chuẩn bị cho bạn."
  },
  AvgDialog_117501_Content_72 = {
    Text = "Caecus nâng lên một cốc thủy tinh được chạm khắc tinh xảo, chất lỏng vàng nhạt đục khiến người ta không yên lòng."
  },
  AvgDialog_117501_Content_73 = {
    Text = "Ở bên trong này là...?"
  },
  AvgDialog_117501_Content_74 = {
    Text = "Gã không chết trong đại nạn, thì đừng có hỏi đông hỏi tây nữa."
  },
  AvgDialog_117501_Content_75 = {
    Text = "Đã được thần mẫu sai tôi chuẩn bị sẵn. Uống đi với lòng biết ơn, con người."
  },
  AvgDialog_117501_Content_76 = {
    Text = "Trước ánh mắt mọi người, bạn cẩn thận hớp một ngụm."
  },
  AvgDialog_117501_Content_77 = {
    Text = "Bụp—Chua quá—! Đây có phải là nước chanh nguyên chất không?!"
  },
  AvgDialog_117501_Content_78 = {
    Text = "Bạn hai mặt nhăn nhó bật dậy, lông mày nhíu chặt."
  },
  AvgDialog_117501_Content_79 = {
    Text = "Nếu Ngài đã bình an vô sự, tôi muốn lên boong để nhận cảm ứng. Vương quốc Thần đang gọi tôi."
  },
  AvgDialog_117501_Content_8 = {
    Text = "Ánh sáng vĩnh cửu tỏa ra trên các vùng biển xa xôi, chỉ ra hướng đi mới cho bạn và tôi."
  },
  AvgDialog_117501_Content_80 = {
    Text = "(Thế giới này và tôi, nhất định có một bên đã điên rồi...)"
  },
  AvgDialog_117501_Content_81 = {
    Text = "Tạm thời hỏi một câu... nơi này là...?"
  },
  AvgDialog_117501_Content_82 = {
    Text = "Tàu du lịch Paradis, \"thiên đường\" trên biển duy nhất và quan trọng nhất của tín đồ Thủy thủ."
  },
  AvgDialog_117501_Content_83 = {
    Text = "Chúng tôi đang hướng tới vương quốc thần thánh vĩnh cửu, Lemuria."
  },
  AvgDialog_117501_Content_9 = {
    Text = "Miryam gần như trực giác đưa ra câu trả lời, trong những câu hỏi tiếp theo lộ ra vẻ nghi ngờ không thể che giấu."
  },
  AvgDialog_117502_Content_10 = {
    Text = "Trong ánh sáng cuối cùng trước khi tầm mắt rơi vào bóng tối tuyệt đối, bạn thấy một hình bóng vụt qua."
  },
  AvgDialog_117502_Content_11 = {
    Text = "Một mái tóc vàng rực rỡ, cánh tay cơ học tinh xảo phát sáng ánh kim loại."
  },
  AvgDialog_117502_Content_12 = {
    Text = "William... học trưởng..."
  },
  AvgDialog_117502_Content_2 = {
    Text = "……………"
  },
  AvgDialog_117502_Content_3 = {
    Text = "Bạn đã phải chiến đấu giữa những đàn cá hôi thối đó bao lâu?"
  },
  AvgDialog_117502_Content_4 = {
    Text = "Một giờ? Một ngày? Hay thời gian không thể đếm được?"
  },
  AvgDialog_117502_Content_5 = {
    Text = "(Lễ hội là thời gian các Thủy thủ tập trung hành động, thật là một quyết định sai lầm liều lĩnh khi xông vào lúc này.)"
  },
  AvgDialog_117502_Content_6 = {
    Text = "Cảm giác trơn trượt đã quen đến mức tê liệt, chất nhờn hôi thối không còn là vấn đề khiến mũi bạn bị nghẹt."
  },
  AvgDialog_117502_Content_7 = {
    Text = "(Nếu có thể quay lại một lần nữa... thật đáng tiếc...)"
  },
  AvgDialog_117502_Content_8 = {
    Text = "Bạn cố gắng nâng cao chìa khóa bạc, trung tâm rực rỡ ánh sáng thuở xưa đã bắt đầu run rẩy.\nBạn như sắp ngã, phun ra một ngụm máu."
  },
  AvgDialog_117502_Content_9 = {
    Text = "(Đã... đến giới hạn rồi... xin lỗi... không thể trốn thoát...)"
  },
  AvgDialog_117503_Content_1 = {
    Text = "Một lữ khách"
  },
  AvgDialog_117503_Content_10 = {
    Text = "Trái tim đột nhiên đánh lên những nhịp đập loạn xạ, bạn vô thức mở miệng, chỉ vì bạn đã biết đến chủ nhân sau lớp voan đen."
  },
  AvgDialog_117503_Content_100 = {
    Text = "Cá bơi phá vỡ sự giam cầm của mặt nước, vật lộn, co giật trong không khí dày đặc, liên tục đổ xuống bên cạnh bạn một cơn mưa tanh tưởi dính nhớp."
  },
  AvgDialog_117503_Content_101 = {
    Text = "Kèm theo âm thanh lạ khiến da đầu nổi da gà, thân thể nửa phân hủy vô ích nhảy lên trên boong, chỗ va chạm chảy ra chất nhờn thối rữa phát ra mùi hôi thối ngột ngạt."
  },
  AvgDialog_117503_Content_102 = {
    Text = "Các xúc tu mảnh mai mong manh xé toạc bụng trắng bệch, lại đang nửa bò đến tấn công bạn——"
  },
  AvgDialog_117503_Content_11 = {
    Text = "<Shake:Murphy……>"
  },
  AvgDialog_117503_Content_12 = {
    Text = "Khoảng trống giữa những lớp vải lộ ra làn da tái nhợt xanh xao của cô, trắng như xác chết phơi bày sắp tan rã."
  },
  AvgDialog_117503_Content_13 = {
    Text = "Hỗn láo! Ngươi dám gọi thẳng tên Thần Mẹ!"
  },
  AvgDialog_117503_Content_14 = {
    Text = "Không sao cả, Caecus, {Male=anh ấy,Female=cô ấy} là khách của Thiên Đàng, cũng sẽ tham gia vào hải trình vĩ đại của chúng ta."
  },
  AvgDialog_117503_Content_15 = {
    Text = "Năm đôi mắt nhìn chằm chằm vào bạn, khiến bạn muốn thốt ra lại hoàn toàn bị dồn vào bụng."
  },
  AvgDialog_117503_Content_16 = {
    Text = "……Murphy, tôi có thể trò chuyện riêng với bạn không?"
  },
  AvgDialog_117503_Content_18 = {
    Text = "……………"
  },
  AvgDialog_117503_Content_19 = {Text = "Muphí…"},
  AvgDialog_117503_Content_2 = {
    Text = "Cô gái nói chuyện với bạn đang ngồi yên ở cuối giường của bạn, lớp voan đen mờ ảo che khuất gương mặt cô ấy."
  },
  AvgDialog_117503_Content_20 = {
    Text = "Nếu bạn chưa tổ chức được ngôn ngữ, tôi có một câu hỏi muốn hỏi."
  },
  AvgDialog_117503_Content_21 = {
    Text = "Tại sao bạn lại đến tàu Paradise? Theo những gì tôi biết, để tiến gần tàu Paradise, bạn phải vượt qua cơn bão."
  },
  AvgDialog_117503_Content_22 = {
    Text = "Sẵn sàng mạo hiểm như vậy, chắc chắn bạn có điều gì đó cầu mong."
  },
  AvgDialog_117503_Content_23 = {
    Text = "Nói thế thì... các bạn đã từng thấy một người đàn ông cao hơn tôi nửa cái đầu, với mái tóc vàng chưa?"
  },
  AvgDialog_117503_Content_24 = {
    Text = "Murphy liếc nhìn bạn một cái, hừ ra một tiếng cười châm biếm."
  },
  AvgDialog_117503_Content_25 = {
    Text = "Theo chiều cao của bạn, chắc chắn trong số các thuyền viên có không ít người như vậy."
  },
  AvgDialog_117503_Content_26 = {
    Text = "Không, bạn chỉ cần nhìn một cái là nhận ra… Anh ấy có cánh tay cơ học đơn độc, trông rất điển trai, trên người có mùi hương nhẹ nhàng của tuyết tùng."
  },
  AvgDialog_117503_Content_27 = {
    Text = "……Vậy tôi có thể xác nhận, chưa thấy.\nNhững thuyền viên đó luôn tỏa ra một mùi tanh hôi của cá bẩn và hôi thối."
  },
  AvgDialog_117503_Content_28 = {
    Text = "Vậy, Murphy, còn một điều quan trọng nữa."
  },
  AvgDialog_117503_Content_29 = {Text = "Ừm?"},
  AvgDialog_117503_Content_3 = {
    Text = "(Giọng nói quen thuộc... ai vậy...)"
  },
  AvgDialog_117503_Content_30 = {
    Text = "Bạn có muốn trốn đi cùng tôi không?"
  },
  AvgDialog_117503_Content_31 = {Text = "Hả?!"},
  AvgDialog_117503_Content_32 = {
    Text = "Murphy bị sốc bởi lời nói của bạn, sau đó cơn giận bùng lên trên gương mặt cô.\nCô cố gắng kiềm chế cảm xúc, phát ra một tiếng cười chế nhạo."
  },
  AvgDialog_117503_Content_33 = {
    Text = "Chạy trốn, ý nghĩa là gì?"
  },
  AvgDialog_117503_Content_34 = {
    Text = "Theo nghĩa đen, chúng ta tìm cách rời khỏi con tàu này, thoát khỏi sự kiểm soát của thủy thủ."
  },
  AvgDialog_117503_Content_35 = {
    Text = "Tại sao tôi phải trốn chạy cùng bạn?"
  },
  AvgDialog_117503_Content_36 = {
    Text = "Bởi vì bạn không thích cuộc sống ở đây."
  },
  AvgDialog_117503_Content_37 = {
    Text = "Bạn không thích giáo lý hư cấu của Miryam, không thích sự tôn thờ giả dối của tín đồ, cũng không quan tâm đến những vinh quang ảo tưởng đó."
  },
  AvgDialog_117503_Content_38 = {
    Text = "Đầu của Murphy từ từ cúi xuống."
  },
  AvgDialog_117503_Content_39 = {
    Text = "Thấy cô ấy im lặng, bạn kịp thời đổ thêm dầu vào lửa."
  },
  AvgDialog_117503_Content_4 = {
    Text = "Bạn cố gắng đứng dậy với cánh tay đau nhức, cố gắng nắm bắt tình hình xung quanh."
  },
  AvgDialog_117503_Content_40 = {
    Text = "Trong thế giới khác, tôi đã thấy bạn, tôi đã quen bạn, chúng ta đã trải qua hoàn cảnh tương tự, và bạn cuối cùng đã thành công thoát khỏi cái hang động…"
  },
  AvgDialog_117503_Content_41 = {Text = "Hừ……"},
  AvgDialog_117503_Content_42 = {
    Text = "Sai rồi, sai rồi! Bạn đã sai rất nhiều!"
  },
  AvgDialog_117503_Content_43 = {
    Text = "Muphí……?"
  },
  AvgDialog_117503_Content_44 = {
    Text = "Phản ứng của Murphy hoàn toàn vượt xa dự đón của bạn, cô ấy bật cười khúc khích."
  },
  AvgDialog_117503_Content_45 = {
    Text = "Nụ cười dần dần trở nên điên loạn, cho đến khi trong phòng chỉ vang vọng tiếng cười phóng túng quá mức của cô ấy."
  },
  AvgDialog_117503_Content_46 = {
    Text = "Sau một hồi, cô ấy dường như cuối cùng đã cười mệt mỏi, tiếng cười ngừng lại đột ngột.\nCô ấy ngẩng đầu lên, nhìn bạn với ánh mắt hung dữ."
  },
  AvgDialog_117503_Content_47 = {
    Text = "Phôi thai của thần đang mang trong lồng ngực tôi, tôi vinh dự là mẹ của thần, được mọi người kính trọng, tại sao lại phải tuân theo các bạn phàm nhân mà \"trốn thoát\"?"
  },
  AvgDialog_117503_Content_48 = {
    Text = "Nhưng, đến khi thần linh ra đời, bạn sẽ chết đi..."
  },
  AvgDialog_117503_Content_49 = {
    Text = "Không cần phải chờ đợi nữa, kẻ ngu dốt."
  },
  AvgDialog_117503_Content_5 = {
    Text = "Đồ ngốc, đừng cử động lung tung."
  },
  AvgDialog_117503_Content_50 = {
    Text = "Murphy nâng lên một cái khăn bọc dị hình, phần nguyên bản là phần đầu của trẻ sơ sinh, kết tụ lại một đống huyết nhục màu xanh tím quen thuộc."
  },
  AvgDialog_117503_Content_51 = {
    Text = "Thánh nhi?!"
  },
  AvgDialog_117503_Content_52 = {
    Text = "Từ hình dáng, bạn nhận ra đó chính là dị thần mà nghi thức sinh ra con tàu Sonaniel đã cố gắng triệu hồi."
  },
  AvgDialog_117503_Content_53 = {
    Text = "Trong thế giới này, hài nhi thánh đã ra đời? Nhưng, sao nó lại...... nhỏ như vậy?!"
  },
  AvgDialog_117503_Content_54 = {
    Text = "Tại sao nó lại nhỏ như vậy... đó thật sự là câu hỏi buồn cười."
  },
  AvgDialog_117503_Content_55 = {
    Text = "Nếu nó cứ nhỏ như thế, nó sẽ không giống như trái bóng hydro được thổi phồng bởi sức mạnh khổng lồ, tham lam trích rút năng lượng từ mẹ, không ngừng lấp đầy, phình ra và áp lực trong ngực tôi..."
  },
  AvgDialog_117503_Content_56 = {
    Text = "Rồi tại khoảnh khắc mà mẹ tạng chết đi, sụp đổ, vụn vỡ, tro tàn......"
  },
  AvgDialog_117503_Content_57 = {
    Text = "Bạn đã thấy, đây chính là đứa bé thánh mà tôi đã sinh ra."
  },
  AvgDialog_117503_Content_58 = {
    Text = "Bạn gọi điều này… là Thần?"
  },
  AvgDialog_117503_Content_59 = {
    Text = "Vậy thì sao? Có ai thấy được hình dạng của thần mà Thủy thủ nói sinh ra không?"
  },
  AvgDialog_117503_Content_6 = {
    Text = "Cô gái lo âu đứng dậy, chiếc khăn che mặt đen tối không yên lặng lay động."
  },
  AvgDialog_117503_Content_60 = {
    Text = "Ai có thể khẳng định, rằng khối huyết nhục tanh tưởi trong tay chúng ta, không phải là \"Thần\" thật sự?"
  },
  AvgDialog_117503_Content_61 = {
    Text = "Âm thanh chất vấn như sấm sét, nổ vang trong tâm trí bạn."
  },
  AvgDialog_117503_Content_62 = {
    Text = "Tôi không phải là Murphy mà ngươi biết, tôi là Thần Mẹ của các Thủy Thủ, là người duy nhất tương thích với huyết thống của Ngài."
  },
  AvgDialog_117503_Content_63 = {
    Text = "Còn về bạn... đừng để tôi hối hận khi đưa bạn vào thiên đường.\nBây giờ, hãy để tôi yên tĩnh một chút, mang theo những suy nghĩ nực cười của bạn ra khỏi căn phòng này."
  },
  AvgDialog_117503_Content_64 = {
    Text = "Bạn đi lang thang trên chiếc Parades theo những ký ức xưa, những thủy thủ cá nhỏ bận rộn chạy qua lại, coi bạn như không khí."
  },
  AvgDialog_117503_Content_65 = {
    Text = "Cho đến khi bên cạnh phòng năng lượng, bạn thấy hai hình bóng quen thuộc."
  },
  AvgDialog_117503_Content_66 = {
    Text = "Cậu nhóc, hãy rộng rãi lên, lao tới đây!"
  },
  AvgDialog_117503_Content_67 = {Text = "Đúng!"},
  AvgDialog_117503_Content_68 = {Text = "Đinh!"},
  AvgDialog_117503_Content_69 = {
    Text = "Vẫn bị cản lại sao... thật là bực mình, nếu cứ tiếp diễn như này, không biết đến bao giờ mới giúp được đại nhân Goliath..."
  },
  AvgDialog_117503_Content_7 = {
    Text = "Tàu Paradis đã thấy nhiều bệnh nhân nhạy cảm với môi trường biển, trước khi thích nghi với \"thiên đường\", đừng có rung động linh hồn mạnh mẽ."
  },
  AvgDialog_117503_Content_70 = {
    Text = "Bình tĩnh lại, nhóc, vách tường cũng có tai. Nếu bị phát hiện, bạn và tôi đều không thoát được."
  },
  AvgDialog_117503_Content_71 = {
    Text = "Thưa Goliath, Ngài đã nói rằng, huyết thống của chúng ta đều xuất phát từ những kẻ mạnh, chúng ta nên không hề sợ hãi……"
  },
  AvgDialog_117503_Content_72 = {
    Text = "Thằng nhóc đáng ghét, ngay cả những kẻ mạnh mẽ cũng có lúc phải sống nhờ người khác. Trên con tàu này, chúng ta phải giả vờ nghe những lời điên rồ của những bà điên."
  },
  AvgDialog_117503_Content_73 = {
