  AvgDialog_118699_Content_1 = {
    Text = "Ước nguyện của chúng tôi"
  },
  AvgDialog_118699_Content_10 = {
    Text = "Cần sức mạnh linh hồn mạnh mẽ hơn nữa... Tôi hiểu rồi, tôi sẽ gửi thông báo đến tất cả thể thức tỉnh."
  },
  AvgDialog_118699_Content_11 = {
    Text = "Trên sân chơi lúc hoàng hôn, Ogier kết thúc một ngày luyện tập cố định, không có gì giảm so với trước đây."
  },
  AvgDialog_118699_Content_12 = {
    Text = "Hôm nay lại phá vỡ một chút kỷ lục trong quá khứ..."
  },
  AvgDialog_118699_Content_13 = {
    Text = "Lau mồ hôi chảy xuống, giáo dài nặng nề chạm đất, Ogier quay đầu nhìn lại, không còn bóng dáng người đã tặng cho mình lời động viên, chỉ còn lại bóng dáng cô độc kéo dài trên mặt đất."
  },
  AvgDialog_118699_Content_14 = {
    Text = "Đột kích của Lotan đã chém bay hai vũ khí thông thường của điều tra viên trong bóng mờ, kết thúc một trận chiến chỉ kéo dài một phút."
  },
  AvgDialog_118699_Content_15 = {
