  },
  AvgDialog_118699_Content_16 = {
    Text = "Còn chưa kịp để cô ấy rút kiếm chuẩn bị tiếp tục bắt nạt người, trước mặt hai tân sinh viên đã thở hổn hển và liên tục cầu xin tha."
