  AvgDialog_118699_Content_2 = {
    Text = "Thế giới Kadath\nHiện tại"
  },
  AvgDialog_118699_Content_20 = {
    Text = "Hoa văn xoắn ốc, hình kim cương, sóng nước, hoa nhỏ và hình động vật, Aigis ngày càng tạo ra nhiều kiểu dáng."
  },
  AvgDialog_118699_Content_21 = {
    Text = "Đại {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}, bạn thích loại gì đây…"
  },
  AvgDialog_118699_Content_22 = {
    Text = "Con chuột xám lanh lợi chui qua lỗ cửa, trung thành đặt một chiếc nhẫn sáng lấp lánh vào tay của bạn."
