  AvgDialog_118699_Content_23 = {
    Text = "Ừm, làm tốt lắm, Nâu."
  },
  AvgDialog_118699_Content_24 = {
    Text = "Chú chuột nhìn nhìn bạn mình chán nản ngáp một cái, vô tình ném chiếc nhẫn vào cái hộp gỗ mở bên cạnh, trong hộp chất đầy những \"bộ sưu tập\" rời rạc chồng chất lên nhau."
