  AvgDialog_118699_Content_25 = {
    Text = "Chít chít.."
  },
  AvgDialog_118699_Content_26 = {
    Text = "Người đó đã rất lâu không tới ký túc xá để tìm kiếm chiếc hộp báu vật của họ, ra lệnh cho ông lớn trả lại từng món một, nhưng tại sao sau đó, ông lớn vẫn buồn bã?"
  },
  AvgDialog_118699_Content_27 = {
    Text = "Cô gái ngoan ngoãn ngồi trước bàn làm việc, mở một cuốn sách chuyện khác."
  },
  AvgDialog_118699_Content_28 = {
    Text = "Góc bàn đã chất đống những cuốn sách trẻ em đã đọc xong, bên cạnh cô gái là cuốn sổ, ghi lại những ý tưởng câu chuyện mà cô nghĩ ra."
  },
  AvgDialog_118699_Content_29 = {
    Text = "Khi nghĩ đến điều hưng phấn, gương mặt bình lặng của cô gái nở ra một nụ cười nhẹ, đôi chân cô cũng bắt đầu nhẹ nhàng lắc lư dưới bàn."
  },
  AvgDialog_118699_Content_3 = {
    Text = "Đường hầm mờ mịt chưa hình thành bị sự xâm lấn đột ngột của nỗi sợ đánh bại, Ramona phát ra tiếng thở dài, dưới áp lực khẩn cấp từ thiết bị đã thu hồi lại ý thức."
  },
  AvgDialog_118699_Content_30 = {
    Text = "Câu chuyện này, mọi người nhất định sẽ thích..."
  },
  AvgDialog_118699_Content_31 = {
    Text = "Bút chì vang lên, ghi lại những ảo tưởng ngây thơ. Nhưng rất nhanh, cô gái dừng bút, thất thần nhìn ra ngoài cửa sổ."
  },
  AvgDialog_118699_Content_32 = {
    Text = "Nhưng, đại {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn} khi nào mới quay lại để dẫn Lily đi đóng phim nhỉ?"
