  AvgDialog_118701_Content_4 = {
    Text = "Tại sao lại phải cất công cụ đi? Thử lại một lần nữa, chắc chắn vẫn còn phương pháp kiểm tra mà chưa nghĩ tới…"
  },
  AvgDialog_118701_Content_40 = {
    Text = "Thế giới Kadath\nMười tháng sau lễ tang của Người giữ gìn\nVũng đen"
  },
  AvgDialog_118701_Content_41 = {
    Text = "Tiếng bước chân vang vọng xuyên qua những cánh cửa cách ly, bước vào làn nước nhớp nháp, mặt nước đen tối tĩnh lặng đã đón chào vị khách thứ hai của ngày hôm nay."
