  AvgDialog_118701_Content_48 = {
    Text = "Chân đốt màu hồng đứng bên cạnh Điêu khắc, cùng nhau nhìn về bóng người luôn trong giấc ngủ."
  },
  AvgDialog_118701_Content_49 = {
    Text = "Có nhiệm vụ đặc biệt nào cần tôi thực hiện không?"
