  AvgDialog_118701_Content_59 = {
    Text = "Doll mỉm cười, đưa báo cáo nghiên cứu vừa mới ra lò cho người đối diện."
  },
  AvgDialog_118701_Content_6 = {
    Text = "{Male=Anh,Female=Chị}Chỉ còn lại một cái xác ở đây, không có bất kỳ dao động sinh mệnh nào, ý thức của Người Giữ Gìn… có thể đã tan biến."
  },
  AvgDialog_118701_Content_60 = {
    Text = "Kể từ khi Daphne nói với chúng ta về tin tức của người giữ gìn, bộ phận nghiên cứu đã thử nghiệm tất cả các phương pháp công nghệ hiện có, không ngờ rằng đầu mối cuối cùng lại nằm ở thể thức tỉnh."
  },
  AvgDialog_118701_Content_61 = {
    Text = "Chúng tôi phát hiện rằng \"Thánh Tâm\" của Polux có thể thu hút sự tồn tại đó, ban đầu Nhà thờ ánh sáng đền thờ chế tạo \"Thánh Tâm\" nhằm tạo ra linh hồn thuần khiết và truyền bá máu thần."
  },
  AvgDialog_118701_Content_62 = {
    Text = "Cuối cùng, hy sinh thánh tử, triệu hồi cái gọi là tịnh độ."
  },
  AvgDialog_118701_Content_63 = {
    Text = "Trên thực tế, nguyên lý của nó chính là thu hút sự chú ý của người đó, từ đó truyền bá quá trình phân rã. Sau khi xử lý định hướng, \"Thánh Tâm\" rất có thể có khả năng chỉ dẫn vị trí của Người giữ gìn cho chúng ta."
  },
  AvgDialog_118701_Content_64 = {
    Text = "Nhà trường dự định gửi một ý thức có khả năng thao túng sức mạnh linh hồn đến không gian chiều, theo chỉ dẫn của \"Thánh Tâm\" để vượt qua chiều không gian và thiết lập kết nối giữa hai thế giới thông qua một đường hầm."
  },
  AvgDialog_118701_Content_65 = {
    Text = "Nếu mọi dữ liệu thử nghiệm tiến triển thuận lợi, không lâu sau một tháng, chúng ta có thể bắt đầu thử nghiệm."
  },
  AvgDialog_118701_Content_66 = {
    Text = "Nhiệm vụ tiếp theo của bạn sẽ thêm phần về rèn luyện sức mạnh linh hồn, hy vọng bạn... đừng quá chăm chỉ, kẻo làm tổn thương bộ não."
  },
  AvgDialog_118701_Content_67 = {
    Text = "Thế giới Kadath\nMột năm sau lễ tang của Người giữ gìn\nVũng đen"
  },
  AvgDialog_118701_Content_68 = {
    Text = "Chiếc máy tách tinh thần đang vận hành nhanh chóng phát ra cảnh báo đỏ không chịu nổi, người quan sát bên cạnh lập tức nhấn nút dừng."
  },
  AvgDialog_118701_Content_69 = {
    Text = "Cửa sập mở ra ngay lập tức, Ramona đã kiệt sức cử động một ngón tay, được các nhà nghiên cứu hai bên nhanh chóng đỡ ra ngoài."
  },
  AvgDialog_118701_Content_7 = {
    Text = "Bản án tàn nhẫn cuối cùng cũng từ mồm búp bê thốt ra, nhìn những giọt nước mắt chảy ra từ đôi mắt ngạc nhiên của Ramona, giáo sư quen với sự hy sinh cũng không đành mở mắt."
  },
  AvgDialog_118701_Content_70 = {
    Text = "Giữ chặt cô ấy, nhanh chóng bước vào trong chất lỏng làm mát tinh thần!"
  },
  AvgDialog_118701_Content_71 = {
    Text = "Nước trong hồ xanh nhạt ngập đến ngực, nhiệt độ trên người Ramona cuối cùng đã giảm xuống như một cơn sốt, đôi mắt từng lý trí giờ đây lại tỏ ra cuồng tín từ từ mở ra."
  },
  AvgDialog_118701_Content_72 = {
    Text = "Ngay cả khi ngày mai là ngày thử nghiệm chính thức đầu tiên, bạn cũng không thể mạo hiểm bằng cơ thể như vậy."
  },
  AvgDialog_118701_Content_73 = {
    Text = "Không sao đâu, tôi có thể chịu đựng……"
  },
  AvgDialog_118701_Content_74 = {
    Text = "Boris vừa từ một thiết bị bên cạnh bước ra cũng lặng lẽ đến bên cạnh hai người, cắt ngang những dặn dò thêm của Đô Lô."
  },
  AvgDialog_118701_Content_75 = {
    Text = "Tôi có thể hiểu nỗi đau khi mất đi người quan trọng, sự căm ghét bản thân vì sự bất lực…… đừng lo lắng, cô Ramona."
  },
  AvgDialog_118701_Content_76 = {
    Text = "Bây giờ \"Thánh tâm\" đã có thể cảm nhận được sự gọi mời từ ngọn đèn, tôi và Castor sẽ hết mình, cùng bạn tìm về ân nhân."
  },
  AvgDialog_118701_Content_8 = {
    Text = "Chuẩn bị tổ chức lễ tang cho <Yellow:%player%> đi, di thư đó... sẽ do {Male=anh ấy, Female=cô ấy} đọc nhé."
  },
  AvgDialog_118701_Content_9 = {
    Text = "Thế giới Kadath\nBa tháng sau tang lễ của Người Giữ Gìn"
