  AvgDialog_118702_Content_1 = {
    Text = "Thông điệp từ xa"
  },
  AvgDialog_118702_Content_10 = {
    Text = "Bạn vung tay như người mù, cố gắng bước từng bước như một người hành hương vượt nước, băng qua những bóng tối dày đặc."
  },
  AvgDialog_118702_Content_100 = {
    Text = "Ở đây không có nhiệt độ nóng bỏng, chỉ có bóng tối dày đặc vô tận. Khi xuyên qua phía trước, việc tiến lên và lùi lại bắt đầu mờ nhòa, như tồn tại cũng biến thành hư vô."
