  AvgDialog_118702_Content_101 = {
    Text = "Tiếp tục về phía trước, đừng quay đầu lại."
  },
  AvgDialog_118702_Content_102 = {
    Text = "Bạn tin tưởng vào âm thanh đó, cố gắng tĩnh tâm, tiếp tục bước đi, cho đến khi một làn sóng màu sắc khiến bạn choáng váng."
