  AvgDialog_118702_Content_104 = {
    Text = "Ngoài biển nguyên chất của Hoa thuỷ tiên, bạn lần đầu tiên đứng bên ngoài vũ trụ nhìn về thế giới."
  },
  AvgDialog_118702_Content_105 = {
    Text = "Như thể bước vào thế giới vi mô trong kính hiển vi, không gian chất dẻo, hàng ngàn đường sáng uốn lượn, những thể linh hồn hình thù kỳ quái, và những dải ngân hà phát sáng xa xăm……"
