  AvgDialog_118702_Content_106 = {
    Text = "Cùng với rìa thế giới không có hồi kết."
  },
  AvgDialog_118702_Content_107 = {
    Text = "Nếu không có đủ điểm neo tinh thần, trong không gian hỗn loạn và vô tận này sẽ nhanh chóng lạc lối, nhưng trong lòng bạn không có quá nhiều sự sợ hãi."
  },
  AvgDialog_118702_Content_108 = {
    Text = "Bạn đã sẵn sàng chưa? Khi bạn bắt đầu liên kết, tôi sẽ cố gắng gây ra một ít tiếng động để thu hút Ngài, phần còn lại, là trận chiến của bạn."
  },
  AvgDialog_118702_Content_109 = {
    Text = "Bạn nắm chặt chiếc chìa khóa bạc trước ngực, trang trọng và yêu thương kéo dài xúc giác tinh thần đến đóa hồng đang nở rộ trong tay."
  },
  AvgDialog_118702_Content_11 = {
    Text = "Cuối cùng... tôi đã tìm thấy bạn! Chúng ta @3... đi qua @2 đường hầm..."
  },
  AvgDialog_118702_Content_110 = {
    Text = "Hãy bắt đầu đi."
  },
  AvgDialog_118702_Content_111 = {
    Text = "Sự dao động sức mạnh linh hồn lớn lao vang dội trong không gian chiều, trong giới hạn cảm nhận của những xúc tu tinh thần của bạn, một vết nứt bất ngờ xuất hiện cắt qua không gian."
  },
  AvgDialog_118702_Content_112 = {
    Text = "Một đồng tử khổng lồ đột nhiên xuất hiện sau khe hở, như đôi mắt của một gã khổng lồ bỗng mở ra."
  },
  AvgDialog_118702_Content_12 = {
    Text = "Bạn không thể nhìn thấy hình bóng của cô ấy, chỉ có thể nghe thấy những âm thanh ngắt quãng. Người mà bạn quen thuộc cũng đang hồi hộp, kể về niềm vui của cuộc hội ngộ sau lâu ngày."
  },
  AvgDialog_118702_Content_13 = {
    Text = "Bạn có thể cảm thấy, giữa các bạn bị một sợi dây thực sự kéo dài, dường như chỉ cần theo sợi dây đó, bạn sẽ tìm thấy hướng trở về."
  },
  AvgDialog_118702_Content_14 = {
    Text = "Ngay khi bạn liên tục tiến về phía trước theo sự chỉ dẫn của sợi dây, một âm thanh vỡ vụn đột ngột vang lên, không gian rung chuyển mạnh mẽ."
  },
  AvgDialog_118702_Content_15 = {
    Text = "Có cái gì đang tấn công @2, thánh tâm không chịu nổi nữa rồi!"
  },
  AvgDialog_118702_Content_16 = {
    Text = "Ramona, hãy cắt đứt liên kết!"
