  AvgDialog_118702_Content_19 = {
    Text = "Tất cả ánh sáng đã biến mất. Từ một khoảng cách xa xôi, một thứ khổng lồ không biết quay đầu lại, dần dần biến mất vào hư vô hỗn loạn."
  },
  AvgDialog_118702_Content_2 = {
    Text = "Người giữ gìn @2..."
  },
  AvgDialog_118702_Content_20 = {Text = "!!!"},
  AvgDialog_118702_Content_21 = {
    Text = "Bạn bỗng ngồi bật dậy khỏi giường, xung quanh vẫn là căn phòng bị thiêu rụi của Búp bê, những bức tường gạch đỏ quen thuộc và mùi thuốc khử trùng nhẹ."
  },
  AvgDialog_118702_Content_22 = {
    Text = "Bạn hỏi tôi có chuyện gì? Tại sao lĩnh vực nghiên cứu của tôi lại mở rộng đến phân tích giấc mơ, những chuyện này bạn không nên đi tìm Clementine sao?"
  },
  AvgDialog_118702_Content_23 = {
    Text = "Nhưng bạn nói không sai, với sự đặc biệt của tinh thần bạn, tôi cũng có xu hướng nghĩ rằng đây không phải là ảo ảnh của bạn, hay chỉ là một giấc mơ đơn giản."
  },
  AvgDialog_118702_Content_24 = {
    Text = "Còn về bí mật của sự thật, không phải tôi đã nói với bạn trong giấc mơ đó rồi sao?"
  },
  AvgDialog_118702_Content_25 = {
    Text = "Một viên bạc mà bạn từng đánh cắp được búp bê·Juliette lấy ra, ném vào thiết bị thức tỉnh, trong tiếng rền rĩ của cơ khí, một làn sương tím bốc lên."
