  AvgDialog_118702_Content_27 = {
    Text = "Hoa thuỷ tiên! Tôi..."
  },
  AvgDialog_118702_Content_28 = {
    Text = "Suỵt, không cần phải nói, một thương nhân giỏi sẽ hiểu được mong muốn của khách hàng."
  },
  AvgDialog_118702_Content_29 = {
    Text = "Tôi thực sự đã gặp bạn bè của bạn."
  },
  AvgDialog_118702_Content_3 = {
    Text = "Bạn như bị che khuất bởi màn nhung lớn, những lớp vải dày nén chặt lên thân thể bạn, khiến bạn không thể thấy, không thể di chuyển."
  },
  AvgDialog_118702_Content_30 = {Text = "?！"},
  AvgDialog_118702_Content_31 = {
    Text = "Thấy biểu hiện sốc của bạn, Búp bê tan chảy đảo một cái mắt trắng."
  },
  AvgDialog_118702_Content_32 = {
    Text = "Tôi đã nghĩ rằng với trí tuệ của ngươi, chắc đủ để nghĩ ra mấu chốt sức mạnh của cô ấy."
  },
  AvgDialog_118702_Content_33 = {
    Text = "...Chìa khóa của sức mạnh?"
  },
  AvgDialog_118702_Content_34 = {
    Text = "Bạn nhớ lại đại dương xám đầy đầu người ấy."
  },
  AvgDialog_118702_Content_35 = {
    Text = "Không gian chiều? Bạn nói, Daffodil có thể xuyên qua các thế giới khác nhau... họ là cùng một người?"
  },
  AvgDialog_118702_Content_36 = {
    Text = "Sắp tới gần rồi, đứa trẻ thông minh, ở đây tôi và ở đó tôi thực sự là cùng một \"tồn tại\", nhưng bạn đã quên, chúng ta không phải là con người."
  },
  AvgDialog_118702_Content_37 = {
    Text = "Hoa thuỷ tiên cười tán thưởng, lật cổ tay lắc lắc cây điếu thuốc."
  },
  AvgDialog_118702_Content_38 = {
    Text = "Chúng tôi chỉ là những khuôn mặt nổi lên trên mặt biển, mà chính biển sương mù xám chảy giữa các chiều không gian mới là bản thể của chúng tôi."
  },
  AvgDialog_118702_Content_39 = {
    Text = "Vì vậy chúng tôi có thể liên kết linh hồn, nhưng không phải là cùng một \"người\"."
  },
  AvgDialog_118702_Content_4 = {
    Text = "Trong một giấc mơ hư vô đen tối, những âm thanh mờ ảo lan tỏa như sóng nước, thoắt cái đã biến mất."
  },
  AvgDialog_118702_Content_40 = {
    Text = "Nói cách khác, bạn có thể đi qua biển hàn gốc để đến những thế giới khác? Trong giấc mơ vừa rồi, Đô Lô bảo tôi đến tìm bạn, ý là bây giờ bạn có cách đưa tôi trở lại thế giới đó?"
