  AvgDialog_118702_Content_41 = {
    Text = "Đừng sốt ruột, tôi đã nói rồi, ngay cả tôi cũng không thể dễ dàng di chuyển giữa hai thế giới."
  },
  AvgDialog_118702_Content_42 = {
