  },
  AvgDialog_118702_Content_45 = {
    Text = "Bạn đột nhiên ngẩng đầu lên, đôi mắt sáng trở lại. Đổi lại bằng một tiếng cười nhẹ của Hoa thuỷ tiên và một tiếng cười khinh bỉ của Búp bê."
  },
  AvgDialog_118702_Content_46 = {
    Text = "Kể từ khi lần cuối chúng ta gặp nhau ở thế giới này, tôi đã kể cho họ nghe tin tức của bạn."
  },
  AvgDialog_118702_Content_47 = {
    Text = "Sau khi biết được tính đặc biệt của chiều không gian này, Búp bê luôn mang theo các nhà nghiên cứu của Mythag ngày đêm làm việc, cố gắng định vị thế giới này. Gần đây, họ đã tìm ra cách kết nối hai chiều không gian."
  },
  AvgDialog_118702_Content_48 = {
    Text = "Điều bạn vừa cảm nhận chính là kết quả thành công của sự liên kết họ."
  },
  AvgDialog_118702_Content_49 = {
    Text = "Vậy đó không phải là giấc mơ? Liên kết linh hồn đó có thật không?!"
