  AvgDialog_118703_Content_17 = {Text = "Cách"},
  AvgDialog_118703_Content_18 = {
    Text = "Một tiếng vỡ vụn ảo ảnh từ một viên pha lê truyền vào tai bạn, bạn thấy đường hầm chiều không gian như mạng nhện bị rạn nứt, cùng với Thân linh hồn La Monna bắt đầu nhấp nháy như một chiếc tivi cũ."
  },
  AvgDialog_118703_Content_19 = {
    Text = "<Big:<Shake:Ramona！！！>>"
  },
  AvgDialog_118703_Content_2 = {
    Text = "Chỉ còn... một chút nữa...!"
  },
  AvgDialog_118703_Content_20 = {
    Text = "Cơ thể đã mệt mỏi từ lâu dường như đã hồi phục trong nháy mắt. Bạn không còn bận tâm đến bất cứ điều gì khác, phi như gió đến bên cô ấy, run rẩy nắm lấy đôi tay ấy."
  },
  AvgDialog_118703_Content_21 = {
    Text = "Tôi, không có gì……"
  },
  AvgDialog_118703_Content_22 = {
    Text = "Đối tác của bạn vẫn như thường lệ mỉm cười, cô ấy nắm chặt tay bạn hơn, như thể không có gì xảy ra và tiếp tục với kế hoạch ban đầu."
  },
  AvgDialog_118703_Content_23 = {
    Text = "Bạn đã đánh bại Người đó, nào, đi với tôi, tôi sẽ đưa bạn trở về."
  },
  AvgDialog_118703_Content_24 = {
    Text = "Cô kéo bạn, giống như khi thực hiện nhiệm vụ như thường lệ.\nChỉ là, một âm thanh lý trí hơn gần như lạnh lùng vang lên."
  },
  AvgDialog_118703_Content_25 = {
    Text = "Ramona, đường hầm chiều không gian đã bị hắn phá vỡ, thân linh hồn của bạn không thể chịu đựng nổi gánh nặng duy trì đường hầm, nếu cứ tiếp tục như vậy, bạn chỉ có thể đi đến tình trạng chết não."
  },
  AvgDialog_118703_Content_26 = {
    Text = "Lần cứu trợ này đã...thất bại, bạn phải trở lại ngay, tôi sẽ khởi động chế độ gọi hồi của thiết bị tách rời, để linh hồn của bạn trở về thân thể."
  },
  AvgDialog_118703_Content_27 = {
    Text = "<Big:Tôi sẽ không đi！>"
  },
  AvgDialog_118703_Content_28 = {
    Text = "Bạn lần đầu tiên thấy người lúc nào cũng bình tĩnh đó kêu lên trong trạng thái không thể kiềm chế. Cô ấy dường như nhăn mũi một cái, rất nhanh đã hiện ra một nụ cười tự nhiên hơn với bạn."
  },
  AvgDialog_118703_Content_29 = {
    Text = "Tôi còn có thể, <Yellow:%player%>, gần đây tôi đã luyện tập rất nhiều, sức mạnh linh hồn của tôi đã tăng lên, Búp bê không hiểu giới hạn thực sự của tôi."
  },
  AvgDialog_118703_Content_3 = {
    Text = "Khi tinh thần của bạn đến gần sự kiệt quệ, ánh mắt của Thần cũng bắt đầu run rẩy vì sự suy yếu."
  },
  AvgDialog_118703_Content_30 = {
    Text = "Đừng bỏ cuộc, chúng ta hãy thử thêm một lần nữa, chỉ là thử xem, được không?"
  },
  AvgDialog_118703_Content_31 = {
    Text = "Cô đang cầu xin bạn."
  },
  AvgDialog_118703_Content_33 = {
    Text = "Bạn không thể nói thành lời."
  },
  AvgDialog_118703_Content_34 = {
    Text = "Sao phải đau đầu như vậy, chi bằng để tôi bắt giữ linh hồn của cô ấy vào thế giới này, cho vào thân thể búp bê do tôi tỉ mỉ chế tác, như vậy cô ấy sẽ có thể trở lại bên cạnh <Yellow:%player%>."
  },
  AvgDialog_118703_Content_35 = {
    Text = "Cô búp bê·Juliette, người đã xem kịch rất vui vẻ, cũng tham gia vào kênh truyền thông, phát ra tiếng cười thích thú."
  },
  AvgDialog_118703_Content_36 = {
    Text = "Lời nói vô lý. Bạn biết không phải ai cũng có thể tồn tại lâu dài trong trạng thái tinh thần tách rời khỏi thân thể như Người giữ gìn, nếu không thì chúng ta cũng không cần phải chịu đựng một cái đầu đầy màu hồng mỗi ngày."
  },
  AvgDialog_118703_Content_37 = {
    Text = "Không sao đâu, Ramona, lần tới, khi bạn đã nghỉ ngơi tốt rồi, tôi sẽ đợi bạn đến đón tôi."
  },
  AvgDialog_118703_Content_38 = {
    Text = "Bạn nhìn vào hình bóng trong suốt dường như sắp tan biến, mỉm cười nhẹ nhàng, ẩn giấu tất cả những khát khao về quê hương."
  },
  AvgDialog_118703_Content_39 = {
    Text = "Không đơn giản chút nào, \"con đường\" này đã bị ngài phát hiện, lần sau sử dụng, chỉ khiến cho sự chú ý ngày càng mạnh mẽ hơn."
  },
  AvgDialog_118703_Content_4 = {
    Text = "Đây là chiến trường của ý chí. Bạn như một con thú sắp chết, cố gắng hết sức mình, từ thế giới linh hồn khô cằn vắt ra chút sức mạnh cuối cùng."
  },
  AvgDialog_118703_Content_40 = {
    Text = "Đúc thủy·Búp bê không thương tiếc chọc thủng giấc mơ của bạn, còn đầu bên kia, Búp bê cũng chỉ im lặng."
  },
  AvgDialog_118703_Content_41 = {
    Text = "<Shake:Chúng ta đã đến đây rồi, lần này, ngay lúc này, tôi muốn đưa bạn trở về.>"
  },
  AvgDialog_118703_Content_42 = {
    Text = "Hai tay Ramona cũng bắt đầu run rẩy. Bạn từ từ hít một hơi, giả vờ thoải mái vỗ nhẹ vào tay cô."
  },
  AvgDialog_118703_Content_43 = {
    Text = "Ramona, bạn còn nhớ lần đầu tiên chúng ta gặp nhau không?"
  },
  AvgDialog_118703_Content_44 = {
    Text = "Ramona gật đầu, nhưng lại lắc đầu, dùng ánh mắt gần như cầu xin nhìn bạn. Bạn chỉ còn cách nhắm mắt, kiên quyết tiếp tục nói tiếp."
  },
  AvgDialog_118703_Content_45 = {
    Text = "Thật là một thảm họa khủng khiếp, sau vụ nổ lớn, tôi chỉ mơ hồ nhớ mọi thứ xung quanh đã biến thành đổ nát cùng với một tiếng nổ chói tai, khi mở mắt ra, tôi còn tưởng mình đã đến thiên đường."
  },
  AvgDialog_118703_Content_46 = {
    Text = "Ánh nắng chói mắt từ những viên gạch bị đào lên chiếu vào, sau đó là bàn tay bạn đưa ra trước mặt tôi."
  },
  AvgDialog_118703_Content_47 = {
    Text = "Lúc đó tôi đã tự hỏi, trang phục của thiên thần có kỳ lạ đến vậy không? Tại sao lại là bộ đồng phục cứng nhắc như vậy, không ngờ rằng nhanh chóng, bộ đồng phục như thế cũng đã mặc lên người tôi."
  },
  AvgDialog_118703_Content_48 = {
    Text = "Ramona còn muốn nói gì đó, nhưng bạn đã cắt ngang, bạn giống như một ông lão chìm đắm trong ký ức, lải nhải liên tục."
  },
  AvgDialog_118703_Content_49 = {
    Text = "Sau khi bạn đào tôi ra, tôi luôn coi bạn là một người tốt đẹp, nhưng khi đến Myhtag, tôi mới phát hiện mình đã bị lừa dối lớn."
  },
  AvgDialog_118703_Content_5 = {
    Text = "Bạn giơ chiếc chìa khóa bạc lên cao bằng đôi tay run rẩy."
  },
  AvgDialog_118703_Content_50 = {
    Text = "Khi mới bắt đầu đọc lớp dự bị, bạn nói bạn là đồng đội của tôi, sẽ giúp tôi giải quyết mọi vấn đề trong cuộc sống và học tập, tôi đã tin."
  },
  AvgDialog_118703_Content_51 = {
    Text = "Thực tế, bạn đã giải quyết vấn đề của tôi, dùng phương pháp từ nguồn gốc giải quyết vấn đề—<Shake:Giải quyết tôi>."
  },
  AvgDialog_118703_Content_52 = {
    Text = "Người bạn đồng hành được gọi là, thực ra là người giám sát lớn nhất, năm đó trong lớp dự bị, người quản lý tôi nghiêm khắc nhất chính là bạn."
  },
  AvgDialog_118703_Content_53 = {
    Text = "Không chỉ trong giờ học phải quản lý, sau giờ học viết bài tập cũng phải quản lý, có lúc sau khi tập thể dục, ngay cả một đĩa khoai tây chiên cũng không cho tôi ăn, thực sự quá đáng!"
  },
  AvgDialog_118703_Content_54 = {
    Text = "Biểu cảm im lặng và buồn bã của Ramona trong một khoảnh khắc đã bùng nổ, khóe miệng không thể không nhếch lên."
  },
  AvgDialog_118703_Content_55 = {
    Text = "Nhưng à, đồng đội thân yêu của tôi, người chăm sóc tôi nhất."
  },
  AvgDialog_118703_Content_56 = {
    Text = "Ngôn ngữ chung của Leo không thể nói, áp lực thi cử dẫn đến sụp đổ, bài tập không thể viết… tất cả những lúc buồn chán đều có thể tìm đến đối tác toàn năng."
  },
  AvgDialog_118703_Content_57 = {
    Text = "Còn nhớ lần đầu tiên tôi tận mắt thấy sinh viên hy sinh trong nhiệm vụ, đêm khuya trằn trọc không ngủ, đã lén gõ cửa phòng bạn."
  },
  AvgDialog_118703_Content_58 = {
    Text = "Rồi thì, bạn đã kéo tôi, chạy lên đỉnh tháp chuông, tôi theo sau bạn khó nhọc trèo lên mái nhà, chúng tôi ngồi bên nhau nhìn sao."
  },
  AvgDialog_118703_Content_59 = {
    Text = "Bạn và tôi đã trò chuyện rất lâu, nói rất nhiều điều. Đó là lần đầu tiên tôi biết, thì ra bạn cũng không biết mẹ của mình, hay tuổi thơ của mình trông như thế nào."
  },
  AvgDialog_118703_Content_6 = {
    Text = "Đến đây… là dừng lại!——"
  },
  AvgDialog_118703_Content_60 = {
    Text = "Trái tim tôi, luôn cảm thấy một chút cô đơn, một chút lúng túng, bỗng dưng rơi xuống như vậy."
  },
  AvgDialog_118703_Content_61 = {
    Text = "Tôi nghĩ, mặc dù tôi không có gia đình, nhưng có lẽ đây là người duy nhất trong thế giới hiện tại đối xử tốt với tôi như vậy, giống như là gia đình."
  },
  AvgDialog_118703_Content_62 = {
    Text = "Tôi thề với bạn, cam kết sẽ chăm chỉ làm bài tập, chăm chỉ lên lớp, chăm chỉ thực hiện nhiệm vụ."
  },
  AvgDialog_118703_Content_63 = {
    Text = "Từ đó trở đi, tôi đã xem Mythag như là ngôi nhà thực sự của mình, và qua từng nhiệm vụ, tôi đã gặp rất nhiều thể thức tỉnh, làm quen với từng người thân mới."
  },
  AvgDialog_118703_Content_65 = {
    Text = "Vậy, cảm ơn bạn, cảm ơn các bạn đã đến đón tôi, các thành viên trong gia đình của tôi."
  },
  AvgDialog_118703_Content_66 = {
    Text = "Tôi biết các bạn chắc chắn đã cố gắng rất lâu, đã tiêu tốn rất nhiều nỗ lực."
  },
  AvgDialog_118703_Content_67 = {
    Text = "Vậy thì hãy đi với tôi, tôi chắc chắn có thể đưa bạn trở về."
  },
  AvgDialog_118703_Content_68 = {
    Text = "Nhìn giọt nước mắt chảy xuống khóe mắt của Ramona, bạn vẫn mỉm cười, nhưng có một loại chất lỏng nóng bỏng cũng không kiểm soát được chảy qua gò má."
  },
  AvgDialog_118703_Content_69 = {
    Text = "Bạn nhìn thấy cô ấy, một hình bóng trở nên mờ ảo và lóe lên vì sức mạnh tinh thần đã đến giới hạn, nhẹ nhàng lắc đầu."
  },
  AvgDialog_118703_Content_7 = {
    Text = "Ánh sáng bạc rực rỡ nở rộ trong tay bạn, ánh sáng trắng bạc chiếu sáng toàn bộ chiều không gian ảo."
  },
  AvgDialog_118703_Content_70 = {
    Text = "Chỉ đến thế này thôi, Ramona."
  },
  AvgDialog_118703_Content_71 = {
    Text = "Không, không…"
  },
  AvgDialog_118703_Content_72 = {
    Text = "Ramona dường như đã cảm thấy điều gì đó từ trước, cô ấy cố gắng lắc đầu, dùng đôi tay mờ ảo nắm chặt lấy thân linh hồn của bạn."
  },
  AvgDialog_118703_Content_73 = {
    Text = "Tôi hứa với bạn, chắc chắn tôi sẽ trở về……"
  },
  AvgDialog_118703_Content_74 = {
    Text = "Tôi hứa với bạn, chúng ta nhất định sẽ gặp lại nhau."
  },
  AvgDialog_118703_Content_75 = {
    Text = "Bạn nhẹ nhàng rút tay ra khỏi lòng bàn tay quen thuộc đó, buông lỏng."
  },
  AvgDialog_118703_Content_76 = {
    Text = "Búp bê nhận được tín hiệu từ đầu bên kia, cảm giác thiết bị quen thuộc kéo dài vào tâm linh của Ramona, cô biết, cô sẽ rời đi."
  },
  AvgDialog_118703_Content_77 = {
    Text = "\"Chắc chắn\", \"Tuyệt đối\", giống như những gì bạn đã nói khi lần đầu bước vào Cửa... thực ra, chính bạn cũng không tin, phải không?"
  },
  AvgDialog_118703_Content_78 = {
    Text = "Bạn thật sự là một người tàn nhẫn……"
  },
  AvgDialog_118703_Content_79 = {
    Text = "Ramona, ta……"
  },
  AvgDialog_118703_Content_8 = {
    Text = "<Shake:Ủa@2@4@3！！！——>"
  },
  AvgDialog_118703_Content_80 = {
    Text = "Quy tắc của điều tra viên... Những gì đã hứa, thì phải thực hiện."
  },
  AvgDialog_118703_Content_81 = {
    Text = "Tôi tin bạn. Ngay cả khi bạn cũng không tin, ngay cả khi bạn lừa dối tôi vô số lần, tôi vẫn tin bạn."
  },
  AvgDialog_118703_Content_82 = {
    Text = "Trên gương mặt đan xen giữa nước mắt và nụ cười, học sinh của Ramona đang nhìn bạn, dường như muốn ghi nhớ rõ ràng khuôn mặt của bạn."
  },
  AvgDialog_118703_Content_83 = {
    Text = "Tại giây phút cuối cùng khi thể linh hồn được triệu hồi về thân thể, cô ấy đã hết sức vươn tay về phía bạn lần nữa."
  },
  AvgDialog_118703_Content_84 = {
    Text = "Giống như khoảnh khắc rất lâu trước đây dưới bầu trời đầy sao vào ban đêm, cô ấy giơ ngón út ra, nhẹ nhàng chạm vào đầu ngón tay bạn."
  },
  AvgDialog_118703_Content_85 = {
    Text = "Bạn nhất định sẽ làm được, phải không?"
  },
  AvgDialog_118703_Content_86 = {
    Text = "Không đợi được câu trả lời của bạn. Ngay lập tức, hình bóng ảo ảnh đó tan rã cùng với đường hầm chiều không gian, hóa thành những mảnh bay lơ lửng từ từ biến mất không để lại dấu vết."
  },
  AvgDialog_118703_Content_89 = {
    Text = "Hơi thở bình thường. Nhịp tim bình thường. Cường độ tinh thần thấp hơn mức cảnh báo... đang hồi phục."
  },
  AvgDialog_118703_Content_9 = {Text = "À——"},
  AvgDialog_118703_Content_90 = {
    Text = "Tâm linh có thể sống lại ngay cả khi bị vắt kiệt sức mạnh linh hồn như thế, thật là một sinh mạng vĩ đại cho cún con."
  },
  AvgDialog_118703_Content_91 = {
    Text = "Đã xem một vở kịch hay. Đáng tiếc không thấy các bạn triệu hồi thần linh hủy diệt thế giới này, kết thúc không đủ tuyệt vời."
  },
  AvgDialog_118703_Content_92 = {
    Text = "Yên tâm đi…… Tôi đã nói sẽ ngăn chặn Ngài ở chiều không gian khác. Lời hứa không thể thực hiện...... sẽ không có lần thứ hai nữa."
  },
  AvgDialog_118703_Content_93 = {
    Text = "Những lời này, hãy để dành nói cho cô ấy nghe khi trở về."
  },
  AvgDialog_118703_Content_94 = {
    Text = "Vốn dĩ đã cùng các bạn bước lên con đường này, tôi cũng muốn xem, bạn thực sự có thể đi được đến bước nào."
  },
  AvgDialog_118703_Content_95 = {
    Text = "Sau khi nghỉ ngơi, hãy tiếp tục lên đường, cún con."
  },
  AvgDialog_118703_Content_96 = {
    Text = "Bạn cảm nhận được hơi ấm còn sót lại ở đầu ngón tay, dần dần nắm chặt ngón tay út vừa mới nắm với nàng, mạnh mẽ ấn vào ngực."
  },
  AvgDialog_118703_Content_97 = {
    Text = "Hướng về không gian chiều không gian trống trải và cô đơn ấy, về phía hình bóng xa xưa đã biến mất, bạn nhẹ nhàng thì thầm, kể về lời hứa mà bạn chắc chắn sẽ thực hiện."
  },
  AvgDialog_118703_Content_98 = {
    Text = "Mặc dù bạn hiện tại không nghe thấy, nhưng…… tôi sẽ làm được. Hãy đợi tôi, Ramona!"
  },
  AvgDialog_118944_Content_1 = {
    Text = "Chặt rơi con cá người dị dạng cuối cùng, bạn chiến đấu lùi lại về phía cô gái ở góc tường."
  },
  AvgDialog_118944_Content_10 = {
    Text = "William cố gắng mở tấm ván dẫn đến khoang tàu, nhưng cho dù anh ta có sức lực như thế nào, tấm ván cũng không nhúc nhích."
  },
  AvgDialog_118944_Content_11 = {
    Text = "Không thể, cánh cửa đã bị khóa từ bên dưới!"
  },
  AvgDialog_118944_Content_12 = {
    Text = "Thân tàu phát ra tiếng rên rỉ ghê rợn, trong sóng lớn dồn dập, khó khăn và quyết liệt bắt đầu quay hướng, hướng tới một vùng biển tối tăm hơn, bão tố dày đặc hơn."
  },
  AvgDialog_118944_Content_13 = {
    Text = "Miryam dang rộng cánh tay, ôm lấy hướng đi hủy diệt, trên mặt hiện ra một nụ cười dịu dàng gần như của mẹ."
