  AvgDialog_118944_Content_21 = {
    Text = "Sự nổ tung của Phòng năng lượng."
  },
  AvgDialog_118944_Content_22 = {
    Text = "Lifesaver trong khoang tàu dưới đáy."
  },
  AvgDialog_118944_Content_23 = {
    Text = "Các điểm sáng liên kết, đan xen, kéo dài… cuối cùng hội tụ thành một lộ trình thoát hiểm rõ ràng và mạch lạc."
  },
  AvgDialog_118944_Content_24 = {
    Text = "William gật đầu."
  },
  AvgDialog_118944_Content_25 = {
    Text = "Một khi bạn đã có được câu trả lời, thì mục tiêu của vòng luân hồi lần này đã cơ bản hoàn thành, không cần phải tiếc nuối."
  },
  AvgDialog_118944_Content_26 = {
    Text = "Theo quy luật bạn đã mô tả, chiếc thuyền sắp bắt đầu chìm rồi."
  },
  AvgDialog_118944_Content_27 = {
    Text = "Bạn đã sẵn sàng chưa?"
  },
  AvgDialog_118944_Content_28 = {
    Text = "Thủy triều đã nuốt chửng ngực của các bạn, bạn nhẹ nhàng nắm lấy chiếc chìa khóa bạc ở ngực, thì thầm lời từ biệt."
