  AvgDialog_118944_Content_29 = {
    Text = "Chúng tôi sẽ gặp lại nhau ở vòng luân hồi tiếp theo."
  },
  AvgDialog_118944_Content_3 = {
    Text = "Cô giật mình bỗng dưng, ánh mắt mờ mịt khó khăn hội tụ vào mặt bạn."
  },
  AvgDialog_118944_Content_30 = {
    Text = "Nguyện Chìa Khóa Bạc soi sáng con đường phía trước."
  },
  AvgDialog_118944_Content_4 = {
    Text = "Không, không có ý nghĩa, tất cả đều là hư vô… Dù là tiến về phía trước hay lùi lại, đều…"
  },
  AvgDialog_118944_Content_5 = {
    Text = "Chỉ cần chưa đến phút cuối, đừng từ bỏ nỗ lực! Dù lần này có thất bại, tôi cũng sẽ lại nắm lấy tay bạn!"
  },
  AvgDialog_118944_Content_7 = {
    Text = "Murphy ngẩn ngơ nhìn bạn."
  },
  AvgDialog_118944_Content_8 = {
    Text = "Bạn nắm lấy cổ tay cô ấy, bằng một sức mạnh nhẹ nhàng nhưng không thể dễ dàng thoát khỏi, dẫn cô ấy ra khỏi góc tuyệt vọng đó."
  },
  AvgDialog_118944_Content_9 = {
    Text = "William học trưởng, có đường nào để trốn thoát không?"
