  AvgDialog_118945_Content_1 = {
    Text = "Nhỏ bé, bạn đã kiềm chế trong trận chiến rồi."
  },
  AvgDialog_118945_Content_10 = {
    Text = "Có một số người tạo ra ác nghiệp để tìm kiếm sự sống sót cho bản thân trong những ngày cuối."
  },
  AvgDialog_118945_Content_11 = {
    Text = "Có một số người dựa vào ý kiến cá nhân để chọn lọc người khác, nhằm xây dựng thế giới mới như họ mong muốn."
  },
  AvgDialog_118945_Content_12 = {
    Text = "Cũng có một số người chỉ đơn thuần vì niềm vui, lại có thể gây ra xáo trộn lớn, tạo ra vô số phiền phức."
  },
  AvgDialog_118945_Content_13 = {
    Text = "Bạn chờ đợi, bạn mong đợi câu trả lời của cô ấy. Bởi vì bạn đã thấy con đường cô đến trong giấc mơ xa xôi."
  },
  AvgDialog_118945_Content_14 = {
    Text = "Miryam điên loạn ngày nay, cũng từng là cô gái trong thiên tai, hy sinh mình vào nhiệm vụ của thầy tu để bảo vệ gia đình duy nhất còn lại."
  },
  AvgDialog_118945_Content_15 = {
    Text = "Miryam không trả lời trực tiếp câu hỏi của bạn. Cô ấy hợp lại hai bàn tay, cầu nguyện về phía đường chân trời xa xa."
  },
  AvgDialog_118945_Content_16 = {
    Text = "\"Người tôn kính, Chúa sẽ ban phước...\""
  },
  AvgDialog_118945_Content_17 = {
    Text = "\"Mọi ước nguyện, Đấng Tối Cao của ta sẽ đáp ứng.\""
  },
  AvgDialog_118945_Content_18 = {
    Text = "Dường như đã nhận được sự đồng ý của đại dương, cô ấy nửa mở đôi mắt tím đen thất thần."
  },
  AvgDialog_118945_Content_19 = {
    Text = "Tôi đến để phục hồi Vùng đất Thần Thánh, đến để ánh sáng vinh quang của Thần hiện diện trên thế giới."
  },
  AvgDialog_118945_Content_2 = {
    Text = "Đối với tôi, cuộc trò chuyện này với Miryam quan trọng hơn một chiến thắng."
  },
  AvgDialog_118945_Content_20 = {
    Text = "Vậy, khi Lemuria tái hiện trên thế gian, bạn mong muốn nhìn thấy một thế giới như thế nào?"
  },
  AvgDialog_118945_Content_21 = {
    Text = "\"Trong giấc mơ dài của Thần, chúng ta cùng nhau chia sẻ hòa bình và hạnh phúc vĩnh cửu.\""
  },
  AvgDialog_118945_Content_22 = {
    Text = "Thời hoàng kim của Lemuria tái hiện, như bạn đã được truyền thụ khi còn sống."
  },
  AvgDialog_118945_Content_23 = {
    Text = "Bạn chưa từng thấy một thời đại hưng thịnh như thế, bạn thật sự biết cách tạo ra nó sao?"
  },
  AvgDialog_118945_Content_24 = {
    Text = "\"Mệnh lệnh của Thần sẽ chỉ cho người tôn kính con đường dẫn đến Lemuria.\""
