  },
  AvgDialog_118951_Content_10 = {
    Text = "Hãy làm một việc gì đó không liên quan đến mẹ thần, giáo lý, hay nghi lễ."
  },
  AvgDialog_118951_Content_11 = {
    Text = "Tôi biết, mặc dù bây giờ bạn thường nói những điều đó, nhưng điều bạn thật lòng thích không phải là những thứ này."
  },
  AvgDialog_118951_Content_12 = {
    Text = "Đừng nói nhiều nữa, nhanh cầm cái này lên!"
  },
  AvgDialog_118951_Content_13 = {
    Text = "Đây, đây là gì?"
  },
  AvgDialog_118951_Content_14 = {
    Text = "Khuấy nhanh, theo một hướng!"
  },
  AvgDialog_118951_Content_16 = {
    Text = "Rồi, còn phải thêm bột mì! Bột nở! Một chút muối!"
  },
  AvgDialog_118951_Content_17 = {
    Text = "Học trưởng William đừng rảnh rỗi nữa? Đi giúp làm tan bơ đi!"
  },
  AvgDialog_118951_Content_18 = {
    Text = "……Được."
  },
  AvgDialog_118951_Content_19 = {
    Text = "William rời đi, kiên nhẫn đóng vai trò là người phụ giúp bối rối nhưng tận tâm trong nhà bếp."
  },
  AvgDialog_118951_Content_2 = {
    Text = "Hãy để anh William biểu diễn một phép thuật cho bạn nhé!"
  },
  AvgDialog_118951_Content_20 = {
    Text = "Cuối cùng, các bạn đã đưa bột đã trộn vào lò nướng."
  },
  AvgDialog_118951_Content_21 = {
    Text = "Murphy ngó chằm chằm vào lò nướng, ngẩn người mất hồn."
  },
  AvgDialog_118951_Content_22 = {
    Text = "Nhớ lại một số điều từ rất lâu trước đây..."
  },
  AvgDialog_118951_Content_23 = {Text = "Ừm?"},
  AvgDialog_118951_Content_24 = {
    Text = "Đó là khi tôi còn ở căn cứ Nam Cực. Tôi đã phát hiện ra một cái bàn thờ trong khe núi, trên đó có rất nhiều tượng đá nhỏ."
  },
  AvgDialog_118951_Content_25 = {
    Text = "Tôi đã để mẹ…… Miryam cho tôi một con dao nhỏ và một ít khúc gỗ, tôi muốn làm một số tác phẩm điêu khắc."
  },
  AvgDialog_118951_Content_26 = {
    Text = "Sau một thời gian dài, cô ấy chỉ đưa cho tôi một chiếc dao nhỏ chưa mở lưỡi, cô nói là lo lắng \"thân thể Thần Mẹ bị tổn thương\"."
  },
  AvgDialog_118951_Content_27 = {
    Text = "Tôi cảm thấy thân thể tôi dường như không thuộc về tôi, tất nhiên cũng không thuộc về cô ấy, chúng tôi như thể là một viên gạch của Vùng đất thần thánh nào đó, bị ngột ngạt ở vị trí của mình, không thể cử động."
  },
  AvgDialog_118951_Content_28 = {
    Text = "Tôi thấy một số tác phẩm điêu khắc gỗ ở đầu giường của bạn."
  },
  AvgDialog_118951_Content_29 = {
    Text = "Ừm, tôi đã âm thầm nhờ Goliath tìm cho một tảng đá dầu."
  },
  AvgDialog_118951_Content_3 = {
    Text = "Tất cả đều đã lấy về theo danh sách, bạn xác nhận lại một chút nhé."
  },
  AvgDialog_118951_Content_30 = {
    Text = "Tôi đã tiêu tốn rất nhiều sức lực, khó khăn mới làm cho lưỡi dao đủ sắc để cắt gỗ."
  },
  AvgDialog_118951_Content_31 = {
    Text = "Tôi đã điêu khắc trong nhiều ngày, cố gắng tái hiện những chi tiết mà tôi tưởng tượng."
  },
  AvgDialog_118951_Content_32 = {
    Text = "Khi tôi cuối cùng cảm thấy hài lòng, tôi đã tặng nó cho Miryam..."
  },
  AvgDialog_118951_Content_33 = {
    Text = "Bạn có biết cô ấy đã nói gì không?"
  },
  AvgDialog_118951_Content_34 = {
    Text = "Miryam... Cô ấy nói bạn khắc không tốt, xúc phạm thần thánh?"
  },
  AvgDialog_118951_Content_35 = {
    Text = "Bạn cố gắng hiểu tâm trạng của Miryam, cẩn thận đưa ra một dự đoán."
  },
  AvgDialog_118951_Content_36 = {Text = "Không."},
  AvgDialog_118951_Content_37 = {
    Text = "Cô ấy không thèm nhìn một cái, chỉ nói rằng nếu tôi thích bức tượng như vậy, cô ấy có thể ra lệnh, nhờ những thợ khắc tốt nhất ngày ngày khắc cho tôi."
  },
  AvgDialog_118951_Content_38 = {
    Text = "Murphy cười điên loạn, đau đớn khôn tả và chế nhạo trào ra từ nụ cười cứng ngắc."
  },
  AvgDialog_118951_Content_39 = {
    Text = "Tôi là đứa con của thần, cũng là cơ thể của thần, muốn gì, chỉ cần giơ tay lên là có thể sở hữu."
  },
  AvgDialog_118951_Content_4 = {
    Text = "William lần lượt mở ra vài túi lớn nhỏ ở ngực, ở lưng, ở cánh tay."
  },
  AvgDialog_118951_Content_40 = {
    Text = "Bởi vì tôi đã có mọi thứ, nên việc khắc một món đồ bằng gỗ như vậy, tất nhiên không đáng nhắc tới."
  },
  AvgDialog_118951_Content_41 = {
    Text = "Cô ấy cười, cười, không biết từ lúc nào, nước mắt lại chảy tràn xuống. Nước mắt bất ngờ đổ xuống, trượt nhanh theo má cô ấy vì cười điên cuồng."
  },
  AvgDialog_118951_Content_42 = {
    Text = "Tôi đã thấy tác phẩm bạn sắp đặt trên đầu giường, tay nghề của bạn khá tốt."
  },
  AvgDialog_118951_Content_43 = {
    Text = "Tốt xấu cũng không quan trọng..."
  },
  AvgDialog_118951_Content_44 = {
    Text = "Murphy, từ bây giờ trở đi, bạn muốn điêu khắc như thế nào thì điêu khắc."
  },
  AvgDialog_118951_Content_45 = {
    Text = "Rồi chúng ta cùng nhau làm bánh nhỏ, cùng nhau nghiên cứu về nghệ thuật hoa."
  },
  AvgDialog_118951_Content_46 = {
    Text = "Tôi sẽ tìm cách quay trở lại thế giới của mình, tôi sẽ giới thiệu người mà tôi biết là Murphy cho bạn, và các bạn có thể cùng nhau tự do làm mọi thứ mà mình muốn."
  },
  AvgDialog_118951_Content_47 = {
    Text = "Murphy lau nước mắt trên mặt, sau đó ngẩng đầu, cho bạn một nụ cười rạng rỡ chưa từng thấy."
  },
  AvgDialog_118951_Content_48 = {
    Text = "Được rồi, đều là những điều bạn đã hứa với tôi."
  },
  AvgDialog_118951_Content_49 = {
    Text = "Tuyệt đối, tuyệt đối không thể hẹn lởn nhé."
  },
  AvgDialog_118951_Content_5 = {
    Text = "Cảm ơn thần thuật vĩ đại William học trưởng đã đánh cắp nguyên liệu từ bếp cho chúng tôi."
  },
  AvgDialog_118951_Content_50 = {
    Text = "Đây là một câu chuyện không liên quan đến thần mẫu."
  },
  AvgDialog_118951_Content_51 = {
    Text = "Nhưng có vẻ như cô ấy chưa bao giờ vui vẻ đến thế trong đời."
  },
  AvgDialog_118951_Content_6 = {
    Text = "Có bột mì, trứng, chanh, mật ong, đường, bột nở, bơ."
  },
  AvgDialog_118951_Content_7 = {
    Text = "Vẫn khá đầy đủ! Túi áo của bộ đồng phục thủy thủ nhiều thật tốt."
  },
  AvgDialog_118951_Content_8 = {
    Text = "Tôi vẫn không hiểu…… tại sao?"
  },
  AvgDialog_118951_Content_9 = {
    Text = "Bạn không muốn thử tự tay nướng bánh mà bạn thường ăn sao?"
  },
  AvgDialog_118952_Content_1 = {
    Text = "Ngày sinh của Thần"
  },
  AvgDialog_118952_Content_10 = {
    Text = "Tôi cầu nguyện với thần linh để tìm ra câu trả lời."
  },
  AvgDialog_118952_Content_11 = {
    Text = "Tôi đã hỏi về tương lai của Vùng đất thần thánh, hỏi về mối liên kết giữa Ngài và tôi, hỏi về tất cả những điều tôi muốn biết và những điều Miryam cố gắng khám phá."
  },
  AvgDialog_118952_Content_12 = {
    Text = "Thần im lặng không nói gì."
  },
  AvgDialog_118952_Content_13 = {
    Text = "<color=#E6E6E6>Ngày thứ năm Thiên Chúa ra đời</color>"
  },
  AvgDialog_118952_Content_14 = {
    Text = "Miryam hỏi tôi về kết quả gặp thần."
  },
  AvgDialog_118952_Content_15 = {
    Text = "Trong lúc nóng vội, tôi đã bịa đặt một câu trả lời thần thánh, \"Vùng đất thần thánh sắp nổi lên\"."
  },
  AvgDialog_118952_Content_16 = {
    Text = "Cô liên tục hỏi lại về thời gian, tôi chỉ có thể đáp lại \"Giây phút chính xác của các vì sao\"."
  },
  AvgDialog_118952_Content_17 = {
    Text = "Miryam phấn khích đến điên cuồng, đó là vẻ mặt hạnh phúc mà tôi chưa từng thấy, khi tôi tặng cô ấy bức tượng gỗ không có, lúc tôi mang thai thánh thể cũng không có."
  },
  AvgDialog_118952_Content_18 = {
    Text = "<color=#E1E1E1>Ngày thứ sáu Thiên Chúa ra đời.</color>"
  },
  AvgDialog_118952_Content_19 = {
    Text = "Miryam hỏi về sự tồn tại của Lemuria, tôi chỉ có thể ứng phó một cách tạm bợ, vẻ mặt của cô ấy hoài nghi."
  },
  AvgDialog_118952_Content_2 = {
    Text = "Ngày đầu tiên của sự ra đời của Thần"
  },
  AvgDialog_118952_Content_20 = {
    Text = "Cô đã thấy Thần chưa chết, lời nói dối của tôi chưa chắc đã có hiệu lực."
  },
  AvgDialog_118952_Content_21 = {
    Text = "<Shake:Lạy Chúa, xin hãy cứu con, dù chỉ là một lời, hãy đáp lại lời cầu nguyện của con.>"
  },
  AvgDialog_118952_Content_22 = {
    Text = "<Red:Ngày thứ bảy thần ra đời>"
  },
  AvgDialog_118952_Content_23 = {
    Text = "Thần đã chết. Thần chưa bao giờ được sinh ra."
  },
  AvgDialog_118952_Content_24 = {
    Text = "Nằm trên ngực tôi chỉ là hình tượng giả tạo, một khối huyết nhục đã chết, bị nhầm gọi là<Yellow:「Thần」>."
  },
  AvgDialog_118952_Content_25 = {
    Text = "Miryam không yêu ai cả. Không quan tâm đến bất cứ ai."
  },
  AvgDialog_118952_Content_26 = {
    Text = "Sau khi nắm giữ quyền năng của Mẹ Thần, tôi đã đọc tất cả các ghi chép của Thủy thủ."
  },
  AvgDialog_118952_Content_27 = {
    Text = "Trong hàng ngàn năm, cứ mỗi sáu mươi năm, sẽ đến một khoảnh khắc chính vị của ngôi sao."
  },
  AvgDialog_118952_Content_28 = {
    Text = "Bị hy sinh, tôi không phải là người đầu tiên, cũng không phải là người cuối cùng."
  },
  AvgDialog_118952_Content_29 = {
    Text = "Muốn sống sót, muốn tồn tại..."
  },
  AvgDialog_118952_Content_3 = {
    Text = "Phôi thai của thần ra đời trong thân xác đã bị tàn phá."
  },
  AvgDialog_118952_Content_30 = {
    Text = "Phải giết gã đó..."
  },
  AvgDialog_118952_Content_31 = {
    Text = "Tôi yếu đuối, ngây thơ..."
  },
  AvgDialog_118952_Content_4 = {
    Text = "Tôi cảm thấy kiệt quệ vì linh hồn bị rút cạn, nhưng khuôn mặt của mọi người đều ngập tràn niềm vui cuồng nhiệt."
  },
  AvgDialog_118952_Content_5 = {
    Text = "<color=#F7F7F7>Ngày thứ hai Thiên Chúa ra đời</color>"
  },
  AvgDialog_118952_Content_6 = {
    Text = "Tôi làm phép rửa cho Thánh Thai. Ngài nhắm mắt, ngủ say trong chiếc nôi."
  },
  AvgDialog_118952_Content_7 = {
    Text = "<color=#F2F2F2>Ngày thứ ba Thiên Chúa ra đời</color>"
  },
  AvgDialog_118952_Content_8 = {
    Text = "Thánh thể vẫn chưa mở mắt. Rõ ràng tôi có thể cảm nhận được nhịp tim của anh ấy, giống như cái đập trước ngực tôi."
  },
  AvgDialog_118952_Content_9 = {
    Text = "<color=#F0F0F0>Ngày thứ tư Thiên Chúa ra đời</color>"
  },
  AvgDialog_118953_Content_1 = {
    Text = "Màn trời trên cao lắc lư, dao động, như một cơn bão nhỏ trong vũ trụ."
  },
  AvgDialog_118953_Content_10 = {
    Text = "Gió lộng, bầu trời u ám đầy mây đen bắt đầu thay đổi."
  },
  AvgDialog_118953_Content_11 = {
    Text = "Mặt trời trên trời…"
  },
  AvgDialog_118953_Content_12 = {
    Text = "Ánh sáng giả dối tắt dần, dưới bầu trời xa xăm, màn che đen tối che khuất trời đất nhẹ nhàng lay động theo nhịp thở."
  },
  AvgDialog_118953_Content_13 = {
    Text = "Đó là một mặt trời đen tối."
  },
  AvgDialog_118953_Content_2 = {
    Text = "Một làn gió thoảng qua vén tấm khăn đen mờ nhoè khuất mặt cô, dưới đó là đôi mắt đã khô héo vì nước mắt."
  },
  AvgDialog_118953_Content_3 = {
    Text = "Có khuyết điểm!"
  },
  AvgDialog_118953_Content_4 = {Text = "Ôi!"},
  AvgDialog_118953_Content_6 = {
    Text = "Trong khoảnh khắc màn trời rung động, lưỡi dao sắc như răng cưa lập tức chém vào khe nứt dao động đó."
  },
  AvgDialog_118953_Content_7 = {
    Text = "Bức tượng ngà bùng nổ một luồng ánh sáng trắng mạnh mẽ, như kháng cự quyết liệt."
  },
  AvgDialog_118953_Content_8 = {
    Text = "Sau vài giây, ánh sáng trắng đột ngột tắt, bức tượng ngà vỡ vụn, trong bán kính hai mươi cm rơi xuống một trận mưa mảnh vỡ trắng."
  },
  AvgDialog_118953_Content_9 = {
    Text = "Tất cả đã kết thúc……"
  },
  AvgDialog_118954_Content_1 = {
    Text = "Vòng luân hồi thời gian"
  },
  AvgDialog_118954_Content_10 = {
    Text = "Người Giữ Bí Mật……"
  },
  AvgDialog_118954_Content_11 = {Text = "Ramona!"},
  AvgDialog_118954_Content_12 = {
    Text = "Hãy bình tĩnh lại, hãy nghe tôi nói."
  },
  AvgDialog_118954_Content_13 = {
    Text = "Tôi đã trải qua không biết bao nhiêu lần nhảy thời gian, quay ngược luân hồi."
  },
  AvgDialog_118954_Content_14 = {
    Text = "Do đó, tôi rất chắc chắn rằng những gì xảy ra với bạn không phải là \"vòng quay thời gian\"."
  },
  AvgDialog_118954_Content_15 = {
    Text = "Thời gian bạn đã trải qua vẫn đang tự nhiên trôi qua."
  },
  AvgDialog_118954_Content_16 = {
    Text = "Không có\"Vòng lặp thời gian\"..."
  },
  AvgDialog_118954_Content_17 = {
    Text = "Vậy tôi gặp phải những hiện tượng kỳ quái mỗi khi tỉnh dậy, du thuyền chìm rồi lại khởi hành lại, cô gái đã chết hồi sinh mà không hề thương tổn..."
  },
  AvgDialog_118954_Content_18 = {
    Text = "Rốt cuộc là vì sao?"
  },
  AvgDialog_118954_Content_19 = {
    Text = "Tôi không thể trả lời bạn."
  },
  AvgDialog_118954_Content_2 = {
    Text = "Bạn nhận thấy mình đang mơ."
  },
  AvgDialog_118954_Content_20 = {
    Text = "Còn mặt trời trên bầu trời đó..."
  },
  AvgDialog_118954_Content_21 = {
    Text = "Ramona không nói nữa. Cô cũng không biết câu trả lời cho câu hỏi này."
  },
  AvgDialog_118954_Content_22 = {
    Text = "Mặt nước dần dần động đậy, bóng của cô ấy bắt đầu dao động từ mép, cuối cùng hóa thành những mảnh ký ức không thể nắm bắt, tản ra trong ánh sáng lấp lánh của sóng."
  },
  AvgDialog_118954_Content_23 = {
    Text = "Nóng bỏng. Đau đớn. Lưỡi lửa thiêu qua mọi inch da của bạn."
  },
  AvgDialog_118954_Content_24 = {
    Text = "Các đầu dây thần kinh co rút do đau nhức, do mất nước mà hóa than.\nBạn trở nên rất nhẹ, nhẹ tới mức hóa thành xương khô cháy đen."
  },
  AvgDialog_118954_Content_25 = {
    Text = "Bạn ho dữ dội."
  },
  AvgDialog_118954_Content_26 = {
    Text = "Đã tỉnh?"
  },
  AvgDialog_118954_Content_27 = {
    Text = "<Shake:……lần nữa……vòng lặp sao……>"
  },
  AvgDialog_118954_Content_28 = {
    Text = "Nếu cơ thể bạn đã phục hồi, tôi sẽ đi chuẩn bị nghi lễ."
  },
  AvgDialog_118954_Content_29 = {
    Text = "Đừng đi, đợi một chút, Murphy…"
  },
  AvgDialog_118954_Content_3 = {
    Text = "Giấc mơ là sự thể hiện cụ thể của khát vọng và nỗi sợ hãi trong tâm trí, Giấc mơ là những hòn đảo cô độc nổi lên trong không gian."
  },
  AvgDialog_118954_Content_30 = {
    Text = "Họ… mọi người đâu cả?"
  },
  AvgDialog_118954_Content_31 = {
    Text = "Murphy hít một hơi dài rồi thở ra thật dài."
  },
  AvgDialog_118954_Content_32 = {
    Text = "Mọi người đều có việc của riêng mình để bận rộn. Bạn hãy nghỉ ngơi ở đây cho tốt nhé."
  },
  AvgDialog_118954_Content_33 = {
    Text = "Khi đến thời điểm của chòm sao chính vị tiếp theo, con tàu này sẽ tới Lemuria, mọi thứ sẽ tốt đẹp hơn."
  },
  AvgDialog_118954_Content_34 = {
    Text = "Két một tiếng, cánh cửa khép lại.\nBạn bị bỏ lại một mình trong phòng khách."
  },
  AvgDialog_118954_Content_35 = {
    Text = "Không thể dừng lại, bạn phải hành động."
  },
  AvgDialog_118954_Content_36 = {
    Text = "Trải qua ba vòng luân hồi, bạn có kết luận gì không?"
  },
  AvgDialog_118954_Content_37 = {
    Text = "Nếu số lần luân hồi đã được xác định, thì thông tin quan trọng hơn nhiều so với sự thoát khỏi."
  },
  AvgDialog_118954_Content_38 = {
    Text = "Vòng lặp đầu tiên, tôi đã có cái nhìn sơ bộ về Thủy thủ; vòng lặp thứ ba mặc dù thất bại thảm hại, nhưng tôi đã cơ bản nắm được động thái của những người khác trên tàu."
  },
  AvgDialog_118954_Content_39 = {
    Text = "Ngược lại, thời gian cho vòng tái sinh thứ hai là lãng phí vô ích."
  },
  AvgDialog_118954_Content_4 = {
    Text = "Trong những giấc mơ hỗn mang từng mảng từng khối, vô số mũi nhọn đầy sắc màu đâm vào ngực bạn, phản chiếu những cái bóng của nhau như bọt."
  },
  AvgDialog_118954_Content_40 = {
    Text = "Việc khẩn cấp là thu thập thêm thông tin về con tàu Paladise và Thủy thủ."
  },
  AvgDialog_118954_Content_41 = {
    Text = "Mặc dù người bí ẩn đó đã gợi ý rằng bạn có tổng cộng sáu vòng luân hồi..."
  },
  AvgDialog_118954_Content_42 = {
    Text = "Nhưng bạn có nghĩ rằng, nếu bây giờ là vòng luân hồi cuối cùng, bạn có phải đã lãng phí một cơ hội không?"
  },
  AvgDialog_118954_Content_43 = {
    Text = "Nếu bây giờ chính là vòng luân hồi cuối cùng……"
  },
  AvgDialog_118954_Content_44 = {
    Text = "Bạn lắc đầu, đuổi bỏ mọi phỏng đoán không hay."
  },
  AvgDialog_118954_Content_45 = {
    Text = "Trong giấc mơ của chu kỳ hồi sinh này, Vòng lặp Ramona đã cung cấp cho tôi một thông tin: <Yellow: cô ấy có thể cảm nhận thời gian trên người tôi vẫn đang chảy theo thứ tự>."
  },
  AvgDialog_118954_Content_46 = {
    Text = "Và bạn cho biết bạn đã trải qua những sự kiện lặp lại……"
  },
  AvgDialog_118954_Content_47 = {Text = "!"},
  AvgDialog_118954_Content_48 = {
    Text = "Có vẻ anh William cũng đã nghĩ thông suốt."
  },
  AvgDialog_118954_Content_49 = {
    Text = "Đây không phải là\"vòng lặp thời gian\", mà là\"những điều giống nhau lặp lại\"..."
  },
  AvgDialog_118954_Content_5 = {
    Text = "Bạn cần một phương pháp để chấm dứt giấc mơ."
  },
  AvgDialog_118954_Content_50 = {
    Text = "Tại Mythag, tôi thường xuyên bị buộc phải rơi vào tình huống tương tự."
  },
  AvgDialog_118954_Content_51 = {
    Text = "\"Miền nhân tạo\"..."
  },
  AvgDialog_118954_Content_52 = {
    Text = "Đúng vậy, đây phần lớn là một \"miền nhân tạo\"."
  },
  AvgDialog_118954_Content_53 = {
    Text = "Miền nhân tạo chỉ là phương tiện chứa đựng thông tin, chúng ta thực sự có thể đang bị cuốn vào bão tố, xoay tròn giữa không trung."
  },
  AvgDialog_118954_Content_54 = {
    Text = "Miền nhân tạo này được hình thành như thế nào? Tại sao lãnh địa lại liên tục khởi động lại? Động lực kết thúc nó là gì?"
  },
  AvgDialog_118954_Content_55 = {
    Text = "Nếu không hiểu tất cả điều này, những nỗ lực của chúng ta trong lãnh địa chỉ là đang tự đâm vào tường mà thôi."
  },
  AvgDialog_118954_Content_56 = {
    Text = "Lý trí. Trong ba trăm năm qua, lý trí luôn giúp Mythag chống lại cơn điên loạn mang tên phân rã."
  },
  AvgDialog_118954_Content_57 = {
    Text = "Tin rằng anh William cũng đã nhận ra, những ngày gần đây, mặt trời mà chúng ta nhìn thấy không phải là mặt trời đen sau lớp sương mù, mà là mặt trời của thế giới bình thường thuần khiết."
  },
  AvgDialog_118954_Content_58 = {
    Text = "Thời gian sinh ra của Lãnh địa, diễn ra trước khi sương mù đen đến thế giới."
  },
  AvgDialog_118954_Content_6 = {
    Text = "Là người mang vận mệnh dệt vải, tôi phải giữ im lặng, không thể nói ra sự thật."
  },
  AvgDialog_118954_Content_60 = {
    Text = "Tôi đã nói sai điều gì sao? Tại sao lại nhìn chằm chằm vào tôi như vậy?"
  },
  AvgDialog_118954_Content_61 = {
    Text = "……Không, tôi chỉ vừa nghĩ đến lúc trước ở Mythag, khi đó ra ngoài thi hành nhiệm vụ, luôn có bạn và Ramona bên cạnh, giải phóng tối đa bộ não của tôi."
  },
  AvgDialog_118954_Content_62 = {
    Text = "Suy nghĩ là một phần không thể thiếu trong điều tra."
  },
  AvgDialog_118954_Content_63 = {
    Text = "Vậy, anh William, anh nghĩ rằng, ai là chủ nhân của Lãnh địa?"
  },
  AvgDialog_118954_Content_64 = {
    Text = "Theo nguyên lý hình thành của Lãnh địa và thông tin đã biết, tôi ước tính rằng Lãnh địa thuộc về Miryam hoặc Faros."
  },
  AvgDialog_118954_Content_65 = {
    Text = "<Yellow:「Hạt nhân」> của Lãnh địa là 「Nghi thức dẫn thần」，Theo dõi vị trí của Lemuria đáng lẽ nên là sự ám ảnh của Lãnh địa chủ."
  },
  AvgDialog_118954_Content_66 = {
    Text = "Theo hồ sơ điều tra của tàu Sonaniel, mục tiêu của Goliath là sức mạnh, nỗi ám ảnh của Kẻ khắc sét là huyết thống, chỉ có Miriam và Phalos hướng tới ánh sáng của thần quốc."
  },
  AvgDialog_118954_Content_67 = {
    Text = "Tiếp theo, xác định chủ nhân của lãnh địa, rồi sao nữa?"
  },
  AvgDialog_118954_Content_68 = {
    Text = "Khi chủ nhân của lãnh địa bắt đầu dao động về nguyên nhân hình thành lãnh địa, sẽ xuất hiện một vết nứt trong đó, và trong đó,\"Clades\" sẽ hiện ra."
  },
  AvgDialog_118954_Content_69 = {
    Text = "Tuy nhiên, vì đây là Miền nhân tạo, nên sự an toàn của cơ thể chúng ta có thể được đảm bảo."
  },
  AvgDialog_118954_Content_7 = {
    Text = "Do đó, tôi đã đưa bạn đến một người có thể mang lại sự khai sáng."
  },
  AvgDialog_118954_Content_70 = {
    Text = "Đừng chủ quan. Chưa nói đến lãnh địa nhân tạo hiện giờ vẫn chỉ dừng lại ở suy đoán của chúng ta..."
  },
  AvgDialog_118954_Content_71 = {
    Text = "Sau 306 năm lũ lụt, Điều tra viên Jude Bright đã bị gãy chân phải khi dẫm phải bẫy của Thợ săn sau khi vào Lãnh địa, khi trở về thực tại, chân phải của anh ấy cũng dần dần bị hoại tử."
  },
  AvgDialog_118954_Content_72 = {
    Text = "Cách mà Lãnh địa ảnh hưởng đến hiện thực hiện tại vẫn chưa thể khảo cứu, nhưng thận trọng thì luôn không sai."
  },
  AvgDialog_118954_Content_73 = {
    Text = "Hiểu rồi."
  },
  AvgDialog_118954_Content_74 = {
    Text = "Sau khi lễ nghi kết thúc, tôi sẽ đối phó với Miryam, Faros sẽ do bạn đảm nhiệm."
  },
  AvgDialog_118954_Content_75 = {
    Text = "Nguyện Chìa Khóa Bạc soi sáng con đường phía trước."
  },
  AvgDialog_118954_Content_76 = {
    Text = "Giai điệu quen thuộc khiến bạn ngẩn người trong giây lát, nhưng nhanh chóng lộ ra một nụ cười chân thành."
  },
  AvgDialog_118954_Content_77 = {
    Text = "Nguyện chìa khóa bạc dẫn đường cho chúng ta."
  },
  AvgDialog_118954_Content_78 = {
    Text = "Người phụ nữ hiểu biết cô đơn chiếm lĩnh một góc của phòng thuyền trưởng, ánh đèn trên đầu nhấp nháy hầu như không thể nhận thấy theo nhịp thở."
  },
  AvgDialog_118954_Content_79 = {
    Text = "Pharos……"
  },
  AvgDialog_118954_Content_8 = {
    Text = "Trong phản chiếu của sóng giấc mơ, xuất hiện một hình bóng đứng nghiêm."
  },
  AvgDialog_118954_Content_80 = {
    Text = "Khoảnh khắc mở miệng, bạn đột ngột ngừng lại. Bạn cố gắng nhớ lại các tài liệu liên quan đến Faros, bạn mới nhận ra rằng trong Mythag có rất ít ghi chép về cô ấy."
  },
  AvgDialog_118954_Content_81 = {
    Text = "Cô khao khát trở về Vùng đất thần thánh, dẫn dắt người hành khách vào con đường lạc lối."
  },
  AvgDialog_118954_Content_82 = {
    Text = "Ngoài ra, các hồ sơ khác đều là một trang trắng."
  },
  AvgDialog_118954_Content_83 = {
    Text = "Có chuyện gì vậy, nhìn biểu hiện của bạn, bạn có cảm thấy bối rối không?"
