  AvgDialog_118954_Content_9 = {
    Text = "Bóng hình dao động, vỡ nát rồi hội tụ, dần dần ổn định thành gương mặt lạnh lẽo quen thuộc trong ký ức của bạn."
  },
  AvgDialog_118955_Content_1 = {
    Text = "Người ngoài"
  },
  AvgDialog_118955_Content_10 = {Text = "William…"},
  AvgDialog_118955_Content_11 = {
    Text = "Nhưng bạn không nên dừng lại ở đây, những đêm ngày mà anh ấy đã đi qua ở đây, chỉ có bạn tìm thấy chủ nhân của Giấc mơ mới có thể chấm dứt mọi chuyện."
  },
  AvgDialog_118955_Content_12 = {
    Text = "Tại cuối chiếc thuyền, bạn đã gặp một cô gái trẻ."
  },
  AvgDialog_118955_Content_13 = {
    Text = "Vô số thủy thủ áo đen nằm ngã nghiêng bên cạnh cô, trong khi cô tĩnh lặng tựa vào bàn thờ, tay cầm một khối thịt thối rữa gây mùi đỏ như máu."
  },
  AvgDialog_118955_Content_14 = {Text = "Muphí…"},
  AvgDialog_118955_Content_15 = {
    Text = "Như bạn đã hứa, bạn đã đến."
  },
  AvgDialog_118955_Content_16 = {
    Text = "Chủ nhân của Giấc mơ là bạn."
