  AvgDialog_118955_Content_23 = {
    Text = "Kể từ khi đến Nam Cực, Murphy đã có một sự tự do kỳ quái."
  },
  AvgDialog_118955_Content_24 = {
    Text = "Cô có thể tự đi bất cứ đâu. Nhưng bất kể đến đâu, nhìn ra chỉ thấy cánh đồng tuyết trắng xóa."
  },
  AvgDialog_118955_Content_25 = {
    Text = "Đừng nói về con người, ngay cả dấu vết tồn tại của loài người cũng không có."
  },
  AvgDialog_118955_Content_26 = {
    Text = "Tôi…… bị lạc rồi sao?"
  },
  AvgDialog_118955_Content_27 = {
    Text = "Cô gái nhìn lại dấu chân đã đi qua. Trong cánh đồng tuyết mênh mông, một con đường gần như thẳng dẫn đến chốn không biết."
  },
  AvgDialog_118955_Content_28 = {
    Text = "Không quan tâm nữa, chỉ cần tiếp tục đi tới, nhất định sẽ đến một nơi nào đó."
  },
  AvgDialog_118955_Content_29 = {
    Text = "Cô gái kiểm tra lương thực mang theo, xác nhận khoảng cách xa nhất mà mình có thể đến với việc tiết kiệm trong thời gian tới."
  },
  AvgDialog_118955_Content_3 = {
    Text = "Bạn ho dữ dội, cố gắng đẩy lùi nước biển đã thấm vào phổi."
  },
  AvgDialog_118955_Content_30 = {
    Text = "Cố lên, Murphy. Đây là hành trình hướng tới tự do, đói bụng chẳng có gì là lớn cả."
  },
  AvgDialog_118955_Content_32 = {
    Text = "……………"
  },
  AvgDialog_118955_Content_33 = {
    Text = "Không thể, trong cơn gió tuyết thế này, không thể phân biệt được đường đi."
  },
  AvgDialog_118955_Content_34 = {
    Text = "Lương khô với nước tuyết thật sự rất khó nuốt."
  },
  AvgDialog_118955_Content_35 = {
    Text = "Đôi khi cô ấy trú ngụ trong hang tuyết, vẫn có thể nghe thấy tiếng hú của thú hoang. Cô chưa từng thấy, chỉ biết đó là một loại sói trắng."
  },
  AvgDialog_118955_Content_36 = {
    Text = "Cứu tôi với!"
  },
  AvgDialog_118955_Content_37 = {
    Text = "Murphy hoảng hốt chạy ra khỏi hang động. Đôi mắt xanh lấp lánh dừng lại trong hang động, không theo kịp bước chân của cô."
  },
  AvgDialog_118955_Content_38 = {
    Text = "Trong hoàn cảnh tuyệt vọng như vậy, tôi đã thấy một hàng dấu chân."
  },
  AvgDialog_118955_Content_39 = {
    Text = "Dấu chân của con người...!"
  },
  AvgDialog_118955_Content_4 = {
    Text = "Nhưng không thể ho nào ra được, phổi chỉ còn lại những dây thần kinh co giật và nỗi đau ảo giác khi chìm nước."
  },
  AvgDialog_118955_Content_40 = {
    Text = "Chỉ cần có người, thì có hy vọng. Tôi đã không do dự mà chạy theo."
