  AvgDialog_118955_Content_43 = {Text = "Ba dòng."},
  AvgDialog_118955_Content_44 = {
    Text = "Dấu chân ngày càng nhiều, nhưng chủ nhân của những dấu chân ấy mãi không thấy bóng dáng."
  },
  AvgDialog_118955_Content_45 = {
    Text = "Tôi quá mệt mỏi, cuối cùng đã ngất xỉu."
  },
  AvgDialog_118955_Content_46 = {
    Text = "Sau đó tôi mới biết, vì hai chân trái và phải dài ngắn khác nhau, mỗi người khi đi bộ không thể xác định phương hướng sẽ nhẹ nhàng nghiêng về một bên."
  },
  AvgDialog_118955_Content_47 = {
    Text = "Nói cách khác... lúc đó, quỹ đạo đi bộ của tôi là một vòng tròn."
  },
  AvgDialog_118955_Content_48 = {
    Text = "Dấu chân mang tên hy vọng mà tôi thấy, đến từ chính tôi trong quá khứ, dẫn đến vòng lặp vĩnh viễn không có điểm dừng."
  },
  AvgDialog_118955_Content_49 = {
    Text = "Vì chút lệch nhẹ, gần như không đáng kể...\nCuộc đời tôi luôn bị kiềm hãm bởi một vòng lặp quái đản."
