  AvgDialog_118955_Content_52 = {
    Text = "Nói cách khác…"
  },
  AvgDialog_118955_Content_53 = {
    Text = "Kể từ khi Goliath lần đầu tiên chuẩn bị nổi loạn, thời gian đã ngừng lại."
  },
  AvgDialog_118955_Content_54 = {
    Text = "Tất cả mọi người đều chìm vào giấc mơ, bắt đầu một giấc mơ tuần hoàn.\nChu kỳ của giấc mơ bắt đầu từ sự ra đời của thánh thai, đến khi du thuyền chìm."
  },
  AvgDialog_118955_Content_55 = {
    Text = "Chỉ cần Goliath chưa phất cờ nổi loạn, mọi thứ vẫn có thể an toàn như ban đầu."
