  AvgDialog_118957_Content_38 = {
    Text = "Hãy đi, trở về, quay về thế giới thuộc về bạn! Không cần lưu luyến thế giới đã chết này."
  },
  AvgDialog_118957_Content_39 = {
    Text = "Còn bạn thì sao, Murphy?"
  },
  AvgDialog_118957_Content_4 = {
    Text = "Theo quan điểm của tôi, Miryam và Faros hẳn sẽ tái khởi hành, khám phá những dấu vết của Lemuria."
  },
  AvgDialog_118957_Content_40 = {
    Text = "Bạn kiềm chế sự thôi thúc bước lên đường mờ và quay lại hỏi Murphy im lặng."
  },
  AvgDialog_118957_Content_41 = {
    Text = "Ai biết chứ? Thế giới này đã là một thế giới đã bị hủy diệt."
  },
  AvgDialog_118957_Content_42 = {
    Text = "Nhận lấy nó đi. Có thể ngày nào đó, bạn sẽ cảm nhận được bạc của tôi trong thế giới đó."
  },
  AvgDialog_118957_Content_43 = {
    Text = "Một viên ngọc máu kết thành viên đá rơi vào lòng bàn tay bạn, đến từ vết thương kỳ quái xuyên qua ngực cô ấy."
  },
  AvgDialog_118957_Content_44 = {
    Text = "Thời điểm đó, cái \"tôi\" mà bạn triệu hồi, không biết sẽ thuộc về thời kỳ nào."
  },
  AvgDialog_118957_Content_45 = {
    Text = "Nhưng hãy nhớ hình dáng hiện tại của tôi khi bạn gọi tôi..."
  },
  AvgDialog_118957_Content_46 = {
    Text = "Sự giáng sinh của Ngài đã là hư vô… hình người và mơ ước đều là hư vô…"
  },
  AvgDialog_118957_Content_47 = {
    Text = "Hãy gọi tôi là...\"<Yellow:Hoang Tưởng·Muphí>\" nhé!"
  },
  AvgDialog_118957_Content_48 = {
    Text = "Bạn di chuyển chậm rãi trên con đường vải mỏng, vô số suy nghĩ bay qua trong tâm trí."
  },
  AvgDialog_118957_Content_49 = {
    Text = "Hành trình chống lại quá trình phân rã, hai thế giới bị ác mộng đen quấn lấy, nhiều gương mặt tương đồng hoặc giống nhau chồng chéo lên nhau……"
  },
  AvgDialog_118957_Content_5 = {
    Text = "Goliath và Caecus có lẽ sẽ rời xa, ngay cả trong thế giới hướng hữu gái hoang này, họ vẫn có hành trình của riêng mình."
  },
  AvgDialog_118957_Content_50 = {
    Text = "Hai Búp bê..."
  },
  AvgDialog_118957_Content_51 = {
    Text = "Hai Clementine..."
