  AvgDialog_118957_Content_53 = {
    Text = "Cuối cùng dừng lại trên khuôn mặt mỉm cười của Ramona."
  },
  AvgDialog_118957_Content_54 = {
    Text = "Tôi…… có thể quay lại sao?"
  },
  AvgDialog_118957_Content_55 = {
    Text = "Một cách kỳ diệu, bạn phát hiện mình đã đứng gần mặt trời đen chỉ một cánh tay, nhưng lại không cảm thấy chút nhiệt độ nào."
  },
  AvgDialog_118957_Content_56 = {
    Text = "Hố sâu vô tận đó đã nuốt chửng mọi ánh sáng, đang chờ đợi để nuốt chửng bạn đến tận cùng."
  },
  AvgDialog_118957_Content_57 = {
    Text = "Ramona... bạn có đợi tôi sau điều này không?"
  },
  AvgDialog_118957_Content_58 = {
    Text = "Bạn nhắm mắt lại, nhẹ nhàng giơ ngón tay ra, chạm vào đoạn đường đen."
  },
  AvgDialog_118957_Content_59 = {
    Text = "Nếu có thể, hãy nắm tay tôi."
  },
  AvgDialog_118957_Content_6 = {
    Text = "Còn \"Murphy\" này..."
  },
  AvgDialog_118957_Content_60 = {
    Text = "Từ dưới chân của bạn, từ trong vô vàn giấc mơ sâu thẳm."
  },
  AvgDialog_118957_Content_61 = {
    Text = "Lấy mặt trời đen làm điểm khởi đầu, lớp lưới đen dần dần tan rã từng lớp."
  },
  AvgDialog_118957_Content_62 = {
    Text = "Bạn từ trên cao rơi xuống."
  },
  AvgDialog_118957_Content_63 = {
    Text = "<Yellow:Chìm vào xoáy nước mang tên 'Số phận'.>"
  },
  AvgDialog_118957_Content_64 = {
    Text = "Tôi trong giấc mơ sâu thẳm nhìn thấy số phận của cô gái đó."
  },
  AvgDialog_118957_Content_65 = {
    Text = "Thật tiếc, Yu ban đầu đã gửi cô ấy rời khỏi Lemuria, gửi bức tượng ngà vào giấc mơ của cô ấy, không phải để có kết cục như thế này."
  },
  AvgDialog_118957_Content_66 = {
    Text = "Có phải không nên cảm ơn những gì tôi đã liên kết ở đây sao?"
  },
  AvgDialog_118957_Content_67 = {
    Text = "Ánh sáng hy vọng của thế giới này đã sớm tắt ngúm, bạn chắc hẳn biết điều đó"
  },
  AvgDialog_118957_Content_68 = {
    Text = "Người phụ nữ tay nắm bánh xe không nói gì, chỉ để sợi chỉ trong tay kéo dài tới dưới bầu trời, giữa muôn vật."
  },
  AvgDialog_118957_Content_69 = {
    Text = "Chỉ cần còn một hạt giống."
  },
  AvgDialog_118957_Content_7 = {
    Text = "Tôi nghĩ, cô ấy chắc có một số điều muốn nói với bạn."
  },
  AvgDialog_118957_Content_70 = {
    Text = "Dù cho im lặng bao lâu, dù ở bất kỳ vùng đất nào, sớm muộn gì cũng sẽ nảy mầm."
  },
  AvgDialog_118957_Content_71 = {
    Text = "Còn về tôi..."
  },
  AvgDialog_118957_Content_72 = {
    Text = "Người phụ nữ nhìn xuống."
  },
  AvgDialog_118957_Content_73 = {
    Text = "Tôi không phải là người gieo hạt, không phải người nuôi dưỡng, cũng không phải người thu hoạch."
  },
  AvgDialog_118957_Content_74 = {
    Text = "Tôi chỉ đang kéo sợi dây treo, theo diện mạo thiên nhiên, vẽ nên người định mệnh."
  },
  AvgDialog_118957_Content_75 = {
    Text = "Tôi sẽ kéo sợi chỉ của bánh xe, để nó kéo ra đất phù hợp nhất."
  },
  AvgDialog_118957_Content_76 = {
    Text = "Tôi sẽ chờ đợi một cách yên lặng."
  },
  AvgDialog_118957_Content_8 = {
    Text = "Bạn đến rồi?"
  },
  AvgDialog_118957_Content_9 = {Text = "Ừm."},
  AvgDialog_118958_Content_1 = {
    Text = "Hạt nhân"
  },
  AvgDialog_118958_Content_10 = {
    Text = "Tôi từng liên minh với Goliath, nhưng bộ lạc chỉ biết đến chiến tranh và bạo lực rõ ràng không hiểu cách giữ hợp đồng, cũng không thể dẫn đến hành trình đến Lemuria."
  },
  AvgDialog_118958_Content_11 = {
    Text = "Thế nào? Chỉ cần bạn gật đầu đồng ý, tôi sẽ tiết lộ danh tính của chủ nhân lãnh địa cho bạn."
  },
  AvgDialog_118958_Content_12 = {
    Text = "Trái tim của cô gái như ngừng đập."
  },
  AvgDialog_118958_Content_13 = {
    Text = "Xin cho phép tôi từ chối."
  },
  AvgDialog_118958_Content_14 = {
    Text = "Tôi không thể vội vàng đáp ứng lấy mạng sống của ai đó khi không biết đối phương là ai."
  },
  AvgDialog_118958_Content_15 = {
    Text = "Hơn nữa, vì bạn đã đưa ra yêu cầu như vậy, rõ ràng chủ nhân của Lãnh địa không ở giữa bạn, Goliath và Caecus."
  },
  AvgDialog_118958_Content_16 = {
    Text = "Và bạn đã tiết lộ rằng quyền lực của giấc mơ liên quan đến bức tượng ngà."
  },
  AvgDialog_118958_Content_17 = {
    Text = "Vậy chỉ còn lại nghi phạm duy nhất, chính là cô ấy..."
  },
  AvgDialog_118958_Content_18 = {
    Text = "Khả năng lựa chọn chỗ ngồi ngắm cảnh của bạn thật sự đáng khen."
  },
  AvgDialog_118958_Content_19 = {
    Text = "Bạn siết chặt dây cáp, để cánh buồm trên cột che khuất hình dáng của bạn và William."
  },
  AvgDialog_118958_Content_2 = {
    Text = "<Shake:đập đập đập, đập đập đập.>"
  },
  AvgDialog_118958_Content_20 = {
    Text = "Lần hành lễ trước tôi đã chú ý, so với tàu Sonaniel, tàu Palades vẫn giữ được cấu trúc cột buồm khá cổ."
  },
  AvgDialog_118958_Content_21 = {
    Text = "Tương đương với một đài quan sát, có thể nhìn thấy tình hình tại hiện trường lễ dẫn đường."
  },
  AvgDialog_118958_Content_22 = {
    Text = "Khi lễ dẫn đường bắt đầu, Miryam sẽ chuyển giao bức tượng ngà cho Murphy, đây cũng là dịp duy nhất chúng ta có thể tiếp xúc với bức tượng ngà."
  },
  AvgDialog_118958_Content_23 = {
    Text = "Cướp đi bức tượng và phân tích, có lẽ chúng ta có thể nắm bắt được cách gỡ bỏ Lãnh địa."
  },
  AvgDialog_118958_Content_24 = {
    Text = "Suỵt, họ đến rồi."
  },
  AvgDialog_118958_Content_25 = {
    Text = "William gõ nhẹ vào vai bạn, ra dấu bảo bạn quay lại."
  },
  AvgDialog_118958_Content_26 = {
    Text = "Chú ý quan sát vị trí của Tượng ngà… Đây chính là sinh lực của chúng ta."
  },
  AvgDialog_118958_Content_27 = {
    Text = "Không khác chút nào với ký ức của bạn, buổi lễ dẫn đường diễn ra một cách có trật tự."
  },
  AvgDialog_118958_Content_28 = {
    Text = "Kính chào Thần Mẫu, xin hãy dẫn dắt dòng máu của Thần Vương, chỉ đường cho những Thủy thủ lạc lối, để chúng ta tìm thấy hướng đi của Lemuria."
  },
  AvgDialog_118958_Content_29 = {
    Text = "Murphy cắn môi, nhận lấy con dao phát sáng từ tay Miryam."
  },
  AvgDialog_118958_Content_3 = {
    Text = "Cô gái đang chạy trong hành lang."
  },
  AvgDialog_118958_Content_30 = {
    Text = "Cô ấy giơ cao dao — rồi lâu lắm cũng không đâm xuống."
  },
  AvgDialog_118958_Content_31 = {
    Text = "Mẹ Thần, Người không phải đã quyết định từ lâu rồi sao? Lemuria vẫn nằm dưới đáy Vực thẳm, chờ đợi sự hiện diện của Người."
  },
  AvgDialog_118958_Content_32 = {
    Text = "……Tôi sẽ..."
  },
  AvgDialog_118958_Content_33 = {
    Text = "Nửa câu sau bị nuốt trôi."
  },
  AvgDialog_118958_Content_34 = {
    Text = "Cô nâng bức tượng ngà bị ngâm trong máu, để cho con quái vật biến dạng đó hút trọn linh tính của mình."
  },
  AvgDialog_118958_Content_35 = {
    Text = "Dòng máu tràn trên mạn thuyền, chảy sang trái."
  },
  AvgDialog_118958_Content_36 = {
    Text = "Quay nhé! Ôi, người lái thuyền của biển cả, lắng nghe sấm truyền, lái sang trái!"
  },
  AvgDialog_118958_Content_37 = {
    Text = "Phản hồi lại cô ấy là một tiếng vỡ không khí sắc nhọn."
  },
  AvgDialog_118958_Content_38 = {
    Text = "Tôi nghĩ không cần đâu."
  },
  AvgDialog_118958_Content_39 = {
    Text = "Những mũi lao sắc nhọn như những nanh của cá mập lớn, đột ngột vươn ra từ bóng đêm đen, chính xác xuyên qua họng của người cầm lái."
  },
  AvgDialog_118958_Content_4 = {
    Text = "Khi đi qua phòng thuyền trưởng, âm thanh êm dịu vừa đúng chạm vào tai cô."
  },
  AvgDialog_118958_Content_40 = {
    Text = "Lưỡi dao khổng lồ nặng nề cắt qua boong tàu, gã khổng lồ bước ra từ bóng đêm, giẫm nát sọ người lái, phơi bày nụ cười tàn nhẫn về phía mụ phù thủy trước mặt."
  },
  AvgDialog_118958_Content_41 = {
    Text = "Phía sau anh ta, một bộ lạc người man rợ trong chiếc áo mưa màu xanh xám cầm trên tay vũ khí sắc bén, khao khát đợi chờ mệnh lệnh giết chóc."
  },
  AvgDialog_118958_Content_42 = {
    Text = "Goliath…… ngươi vẫn không chịu từ bỏ sao?"
  },
  AvgDialog_118958_Content_43 = {
    Text = "Tập hợp các thủy thủ, tạo ra hỗn loạn... cố gắng phá vỡ sự bình yên của thiên đường..."
  },
  AvgDialog_118958_Content_44 = {
    Text = "Thật tiếc, tôi không phải là một phần của sự bình yên này. Lần này, lần sau, lần kế tiếp... Những người Perishite sẽ không thể chấp nhận mãi mãi phải chịu đựng dưới người khác."
  },
  AvgDialog_118958_Content_45 = {
    Text = "Đến đây đi, những người Perishite!"
  },
  AvgDialog_118958_Content_46 = {
    Text = "Trong giọng nói ác độc, những bộ lạc mặc áo nhựa dầu cầm dao sắc xuất hiện dày đặc từ bóng tối."
  },
  AvgDialog_118958_Content_47 = {
    Text = "Tiếng gầm vang lên vì phấn khích mà run rẩy. Họ khát khao chờ đợi, chờ đợi khoảnh khắc tái hiện vinh quang, chờ đợi lệnh chinh phạt tất cả."
  },
  AvgDialog_118958_Content_48 = {
    Text = "<Big:Giết chúng đi！>"
  },
  AvgDialog_118958_Content_49 = {
    Text = "Bài ca chiến tranh hoang dã xé rách bầu trời đêm trên biển, bộ lạc man rợ kéo dây thừng với tốc độ khó có thể phản ứng, đổ vào đám đông trên boong tàu."
  },
  AvgDialog_118958_Content_5 = {
    Text = "Tôi biết ai là chủ nhân của lãnh địa, và cũng có thể dẫn dắt các bạn vượt qua biên giới của lãnh địa, trở về thế giới thực."
  },
  AvgDialog_118958_Content_50 = {
    Text = "Những người Perishite sống bằng cướp bóc ven biển như những con cá mập ngửi thấy mùi máu tươi, đói khát và hung hãn lao vào con mồi của họ, dùng dao cong như răng để cắn xé thân xác kẻ thù."
  },
  AvgDialog_118958_Content_51 = {
    Text = "Thưa Ngài, xin hãy lắng nghe lời cầu nguyện của tín đồ... xin hãy ban phước lành cho dân chúng của Ngài..."
  },
  AvgDialog_118958_Content_52 = {
    Text = "Miryam dang rộng cánh tay, ánh sáng u tối dần dần lan rộng ra."
  },
  AvgDialog_118958_Content_53 = {
    Text = "Những Thủy thủ mặc chiếc áo choàng đen kỳ lạ không phát ra âm thanh nào, giống như một bầy linh hồn đen tối thành kính, lặng lẽ tắm mình trong sự bảo vệ sâu thẳm, lặng lẽ đâm con dao vào ngực kẻ thù."
  },
  AvgDialog_118958_Content_54 = {
    Text = "Màu xanh xám và màu đen tím, hai quân đội rõ rệt đang chiến đấu sinh tử trong cơn địa ngục chuyển động này."
  },
  AvgDialog_118958_Content_55 = {
    Text = "Hãy giết chóc, tộc nhân của tôi... ngay tại đây, tái hiện vinh quang của Perishite!"
  },
  AvgDialog_118958_Content_56 = {
    Text = "Lưỡi dao khổng lồ chém xuống không thể ngăn cản, chặt đứt đầu của tín đồ Thủy thủ đang chắn trước mặt, dòng máu mặn chát phun ra đã nhuộm gần hết một bên mặt của Goliath thành đỏ tươi."
  },
  AvgDialog_118958_Content_57 = {
    Text = "Anh ta liếm máu trên mặt mình, dưới ánh chớp vung thanh đại đao trong tay, chém giết mỗi tín đồ cản đường mình."
  },
  AvgDialog_118958_Content_58 = {
    Text = "Máu vừa từ thân thể ấm áp chảy ra, ngay lập tức bị mưa lạ lùng pha loãng, hòa lẫn với nước biển, thành những dòng chảy đỏ tươi nhầy nhớt trên sàn tàu rung lắc dữ dội."
  },
  AvgDialog_118958_Content_59 = {
    Text = "<Shake:Thưa ngài, tôi đã nghe thấy lệnh của Ngài. Các tín đồ của Ngài, sẽ cùng Ngài trở lại Vùng đất thần thánh……>"
  },
  AvgDialog_118958_Content_6 = {
    Text = "Cô gái giả vờ bình tĩnh, giảm bước chân của mình."
  },
  AvgDialog_118958_Content_60 = {
    Text = "Nghi lễ, bão tố, chém giết……"
  },
  AvgDialog_118958_Content_61 = {
    Text = "Ngay chính giữa hỗn mang này, dưới bức tượng ngà không may ở mũi tàu, Miryam đứng vững, thì thầm thành kính trong cơn bão."
  },
  AvgDialog_118958_Content_62 = {
    Text = "Cô ấy không chú ý đến biển máu và núi thi thể xung quanh, dao găm lướt qua tai cô, sóng lớn rửa sạch cô hoàn toàn, cô cũng không cảm thấy gì."
  },
  AvgDialog_118958_Content_63 = {
    Text = "Nguyện rằng lời tiên tri của Ngài sẽ dẫn dắt chúng tôi, nguyện rằng thân xác của Ngài sẽ bao phủ chúng tôi."
  },
  AvgDialog_118958_Content_64 = {
    Text = "Miryam... Hãy từ bỏ đi! Chúng ta không thể đến được Lemuria!"
  },
  AvgDialog_118958_Content_65 = {
    Text = "Không… ngài đã hứa với tôi, ngài cũng đã nghe thấy lời thánh chỉ của ngài, đúng không?"
  },
  AvgDialog_118958_Content_66 = {
    Text = "Miryam thành kính nhìn về phía chân trời."
  },
  AvgDialog_118958_Content_67 = {
    Text = "Cơn bão là hơi thở của bạn, sấm sét là trống trận của bạn!"
  },
  AvgDialog_118958_Content_68 = {
    Text = "Hãy chỉ dẫn con chiên lạc lối này, <Big:đường đến vương quốc của Ngài!>"
  },
  AvgDialog_118958_Content_69 = {
    Text = "Một luồng chớp trắng xé rách màn trời, ngay lập tức chiếu sáng đôi mắt cuồng nhiệt và tôn kính của cô."
  },
  AvgDialog_118958_Content_7 = {
    Text = "Nhưng sự hỗ trợ của tôi là có điều kiện."
  },
  AvgDialog_118958_Content_70 = {
    Text = "Cô gái trong chiếc khăn đen lặng lẽ co rụt vào một góc mũi thuyền, ánh mắt trống rỗng vô vọng đối diện với chiến trường khốc liệt, như một con búp bê vứt lại trong đống rác."
  },
  AvgDialog_118958_Content_71 = {
    Text = "Đi, chúng ta xuống dưới!"
  },
  AvgDialog_118958_Content_72 = {
    Text = "Tôi chịu trách nhiệm lấy đi bức tượng ngà!"
  },
  AvgDialog_118958_Content_73 = {
    Text = "Tôi đi giải cứu Murphy trong lúc họ đang hỗn loạn!"
  },
  AvgDialog_118958_Content_8 = {
    Text = "Điều kiện của bạn là...?"
  },
  AvgDialog_118958_Content_9 = {
    Text = "Giết chết người nắm quyền của thâm cảnh, cướp lấy bức tượng ngà, chuyển giao quyền bính của thâm cảnh cho tôi."
  },
  AvgDialog_118959_Content_1 = {
    Text = "Tôi đã giết chết chính mình, cầm lên vương miện. Ngoài tự do ra, tôi đã đạt được mọi thứ tôi khao khát."
  },
  AvgDialog_118959_Content_10 = {
    Text = "Bởi vì bạn là khác biệt."
  },
  AvgDialog_118959_Content_11 = {
    Text = "Tôi và họ khác nhau ở điểm nào? Chúng đều chỉ là những vật tế lễ trong mắt bạn, đều chỉ là thức ăn cho đám thịt thối rữa này mà thôi."
  },
  AvgDialog_118959_Content_12 = {
    Text = "Murphy cầm lấy khối bẩn thỉu trong tay, máu tươi rơi xuống rả rích."
