  AvgDialog_118959_Content_14 = {
    Text = "Bởi vì……"
  },
  AvgDialog_118959_Content_15 = {
    Text = "Chúng tôi bên nhau, đã đi một chặng đường dài."
  },
  AvgDialog_118959_Content_16 = {
    Text = "Tôi nhớ ngày bạn vào ngực cấy ghép thánh thai, bạn đã nói muốn ăn Churros."
  },
  AvgDialog_118959_Content_17 = {
    Text = "Bạn bỗng nhận ra rằng, món ăn ngon không phù hợp để một mình thưởng thức, lại ngại ngùng chia sẻ cho tôi một nửa."
  },
  AvgDialog_118959_Content_18 = {
    Text = "Sau đó thánh thai bắt đầu phát triển, bạn sốt cao không ngừng, chúng tôi đã cố gắng hết sức để hạ sốt nhưng cuối cùng chỉ có thể đưa bạn đến hầm băng ở Nam Cực."
  },
  AvgDialog_118959_Content_19 = {
    Text = "Có thể làm chúng tôi phiền phức đủ đường."
  },
  AvgDialog_118959_Content_2 = {
    Text = "Nhưng người đã sinh ra đứa trẻ thánh thiện, lại không nhận được ân sủng của thần linh, không thể chỉ điểm con đường đến Lemuria..."
  },
  AvgDialog_118959_Content_20 = {
    Text = "Dù trong môi trường gian nan như vậy, bạn vẫn giữ trách nhiệm của mình như Thần mẫu."
  },
  AvgDialog_118959_Content_21 = {
    Text = "Hầu hết các thầy tu đều chịu đựng cái lạnh, bên bàn thờ ở Nam Cực, cùng nhau chờ đợi, cầu nguyện."
  },
  AvgDialog_118959_Content_22 = {
    Text = "Và bạn không phụ lòng mong đợi, trở thành cơ thể đầu tiên sinh ra thánh nhi."
  },
  AvgDialog_118959_Content_23 = {
    Text = "Chúng tôi đã cùng nhau, đạt tới khoảnh khắc đó."
  },
  AvgDialog_118959_Content_24 = {
    Text = "Chúng tôi sẽ cùng nhau, hướng tới vương quốc thần thánh vĩnh cửu."
  },
  AvgDialog_118959_Content_25 = {
    Text = "Miryam chậm rãi và kiên định tiến đến trước Murphy, cúi người."
  },
  AvgDialog_118959_Content_26 = {
    Text = "Bạn là Mẹ Thần tôn quý, tôi xin mãi mãi quỳ dưới chân bạn, dâng hiến sự sùng kính suốt đời của tôi cho bạn."
  },
  AvgDialog_118959_Content_27 = {
    Text = "Tôi sẵn lòng nhìn lên bạn với tư thế vĩnh cửu giống như đối đãi với vị \"thần\"."
  },
  AvgDialog_118959_Content_28 = {
    Text = "Murphy ngẩn ngơ nhìn Miryam."
  },
  AvgDialog_118959_Content_29 = {
    Text = "Miryam quỳ nửa người, nắm lấy mu bàn tay cô ấy, nhẹ nhàng hôn lên đó với lòng thành kính."
  },
  AvgDialog_118959_Content_3 = {
    Text = "Vậy bạn đã tạo ra giấc mơ không có hồi kết này……"
  },
  AvgDialog_118959_Content_30 = {
    Text = "Trở về bên tôi nhé, được không, \"Mẹ thần\"?"
  },
  AvgDialog_118959_Content_31 = {
    Text = "Murphy cúi đầu. Gió im bặt, trong những kẽ hở nhỏ bé của vũ trụ yên tĩnh không tiếng động."
  },
  AvgDialog_118959_Content_32 = {
    Text = "Tất cả câu chuyện của bạn đều có liên quan đến Thánh bào. Tất cả danh hiệu của bạn đều không thể tách rời Mẹ Thần."
  },
  AvgDialog_118959_Content_33 = {
    Text = "Bạn vẫn chưa hiểu… và bạn sẽ mãi mãi không hiểu…"
  },
  AvgDialog_118959_Content_34 = {
    Text = "Giữa các kẽ răng, vài câu từ thầm thì thoát ra."
  },
  AvgDialog_118959_Content_35 = {
    Text = "Chỉ biết cầu nguyện, nghi lễ, thần quốc, Lemuria, sự ra đời của thần linh..."
  },
  AvgDialog_118959_Content_36 = {
    Text = "Sẽ mãi mãi không hiểu."
  },
  AvgDialog_118959_Content_37 = {
    Text = "Tất cả những gì tôi đã làm, cái đích mà tôi gắng gượng đạt được, ảo giác mà tôi đang duy trì..."
  },
  AvgDialog_118959_Content_38 = {
    Text = "Chỉ muốn gọi bạn một tiếng với tư thế được bạn chân thành đối đãi..."
  },
  AvgDialog_118959_Content_39 = {Text = "Mẹ……"},
  AvgDialog_118959_Content_4 = {
    Text = "Nếu tôi không làm như thế, cô ấy nhất định sẽ tự tay lấy tim tôi ra..."
  },
  AvgDialog_118959_Content_40 = {
    Text = "Cơn gió dữ trên mặt biển che lấp đi những tiếng thì thầm đã mờ nhạt."
  },
  AvgDialog_118959_Content_41 = {
    Text = "Thật tiếc, thật tiếc."
  },
  AvgDialog_118959_Content_42 = {
    Text = "Murphy thu lại nước mắt."
  },
  AvgDialog_118959_Content_43 = {
    Text = "Mọi kỳ vọng của tôi về bạn chỉ là mê sảng, sự cân bằng duy trì bằng dối trá cũng chỉ là một ảo ảnh vĩnh hằng."
  },
  AvgDialog_118959_Content_44 = {
    Text = "Bạn sẽ không bao giờ là mẹ của tôi."
  },
  AvgDialog_118959_Content_45 = {
    Text = "Người mà bạn biết, Murphy, đã chết từ lâu rồi. Cái chết của cô ấy, đến cùng với sự ra đời của thần."
  },
  AvgDialog_118959_Content_46 = {
    Text = "Đứng ở đây là một thể thức tỉnh sinh ra từ tro tàn của sự sống và trí tuệ bạc..."
  },
  AvgDialog_118959_Content_47 = {
    Text = "Người mà đã hoán tỉnh tôi từ đống đổ nát... Không, liệu có thể coi đó là người không?"
  },
  AvgDialog_118959_Content_48 = {
    Text = "Người liên kết của tôi, ngay trước mắt các bạn."
  },
  AvgDialog_118959_Content_49 = {
    Text = "Cô ấy nhẹ nhàng mở chiếc khăn bọc, trên khuôn mặt cô, bạn bắt gặp một tình cảm kỳ lạ gần như đáng sợ mà bạn chưa từng thấy."
  },
  AvgDialog_118959_Content_5 = {
    Text = "Hy sinh tôi cho vị vua mà cô ấy tôn kính."
  },
  AvgDialog_118959_Content_50 = {
    Text = "Tôi đã mang nó đến thế giới này... nó cũng đã mang tôi đến thế giới này..."
  },
  AvgDialog_118959_Content_51 = {
    Text = "Số phận lệch hướng quấn lấy nhau, vòng lặp sai lệch không bao giờ dừng lại."
  },
  AvgDialog_118959_Content_52 = {
    Text = "Cha sinh ra con cái, con gái mang thai cha, cha lại hoán tỉnh con gái..."
  },
  AvgDialog_118959_Content_53 = {
    Text = "Không ai đến để cắt đứt sợi dây ràng buộc này, không ai đến để cản trở mối liên kết và hỗn loạn của huyết mạch vĩnh cửu."
  },
  AvgDialog_118959_Content_54 = {
    Text = "Bạn có nghĩ rằng bạn là người đầu tiên mắc kẹt trong vòng lặp không?"
  },
  AvgDialog_118959_Content_55 = {
    Text = "Trước đó, tôi đã bước vào vòng lặp vô số lần, và kết thúc mỗi vòng lặp đều là cơn ác mộng không thể nói thành lời."
  },
  AvgDialog_118959_Content_56 = {
    Text = "Bởi vì từ chối Lemuria, cái kết bị Goliath xuyên thấu ngực."
  },
  AvgDialog_118959_Content_57 = {
    Text = "Bị Goliath giam cầm bằng dây xích, cướp đi bức tượng ngà, cùng với toàn bộ con thuyền chìm xuống đáy biển."
  },
  AvgDialog_118959_Content_58 = {
    Text = "Còn trong giấc mơ, một bóng dáng gầy gò nhưng mạnh mẽ, mở ra một con đường chạy trốn cho tôi."
  },
  AvgDialog_118959_Content_59 = {
    Text = "Tôi luôn tin rằng, những điều đó không phải là kết cục thật sự.\nTôi đang chờ đợi kết cục thuộc về \"tôi này\"."
  },
  AvgDialog_118959_Content_6 = {
    Text = "Vậy bạn nói cô ấy luôn chờ đợi tôi… tôi không hiểu."
