  AvgDialog_118959_Content_60 = {
    Text = "Kết thúc thực sự, có thể đến rồi."
  },
  AvgDialog_118959_Content_61 = {
    Text = "Hãy để con tàu này lật đổ."
  },
  AvgDialog_118959_Content_62 = {
    Text = "Bức màn đen như tấm lụa tuôn xuống từ bầu trời, tựa như mặt trời vô hình che khuất và tách biệt thân thuyền với thế giới bên ngoài."
  },
  AvgDialog_118959_Content_63 = {
    Text = "Dòng nước vô biên tràn đến, chôn vùi toàn bộ con tàu Paradise vào vực thẳm tối tăm không ánh sáng."
  },
  AvgDialog_118959_Content_64 = {
    Text = "Một lần nữa, bạn lâm vào bóng tối vô tận."
  },
  AvgDialog_118959_Content_7 = {
    Text = "<Shake:Tại sao? Miryam, tại sao?>"
  },
  AvgDialog_118959_Content_8 = {
    Text = "Nếu tôi không phải là người mẹ thần thánh đủ tiêu chuẩn, vậy thì bạn chỉ cần như mọi khi từ bỏ tôi là được không?"
  },
  AvgDialog_118959_Content_9 = {
    Text = "<Red:Hãy bỏ mặc tôi… Cho tôi tự do…>"
