  AvgDialog_118960_Content_1 = {
    Text = "Vải voan vĩnh cửu"
  },
  AvgDialog_118960_Content_10 = {
    Text = "Không, tôi luôn có thể điều khiển mọi thứ trong giấc mơ, tôi có thể quyết định kết thúc và bắt đầu của vòng lặp, tôi…"
  },
  AvgDialog_118960_Content_11 = {
    Text = "Thần linh ban cho bạn quyền năng tạo ra giấc mơ, nhưng bạn lại mắc kẹt trong sự ám ảnh của chính mình, đã làm lãng phí thiện ý của Ngài."
