  AvgDialog_118960_Content_17 = {
    Text = "Hình tượng của Ngài… là…"
  },
  AvgDialog_118960_Content_18 = {
    Text = "Không có gì lạ khi tôi luôn cảm thấy thiếu một mảnh ghép trong câu trả lời hoàn chỉnh."
  },
  AvgDialog_118960_Content_19 = {
    Text = "%player%, bạn còn nhớ suy luận của chúng ta không? \n Thời gian ra đời của thâm cảnh, trước khi sự hòa tan nuốt chửng thế giới, mặt trời biến dị thành mặt trời đen."
  },
  AvgDialog_118960_Content_2 = {
    Text = "<Red:không nên kết thúc>"
  },
  AvgDialog_118960_Content_20 = {
    Text = "Và nghi lễ giáng sinh của thánh nhi, sự hiến tế và tái sinh của Muphí, rõ ràng xảy ra sau khi mặt trời đen ra đời."
  },
  AvgDialog_118960_Content_21 = {
    Text = "Nói cách khác, vào thời điểm đó, Muphí chỉ là một con người tràn đầy linh cảm, không đủ để xây dựng giấc mơ này."
  },
  AvgDialog_118960_Content_22 = {
    Text = "Trước đó, người nắm giữ quyền năng…… chắc hẳn là……"
  },
  AvgDialog_118960_Content_23 = {
    Text = "Vị thần vương của thế giới này đã sớm xuất hiện... không, không nên nói là đã không bao giờ chết."
  },
  AvgDialog_118960_Content_24 = {
    Text = "Bạn không thể đánh thức ý thức của Ngài, vì ý thức của Ngài vẫn còn trong giấc mơ dài lâu."
  },
  AvgDialog_118960_Content_25 = {
    Text = "Ngài không nỡ thấy bạn vì hy sinh mà chết, đặc biệt phân ra một tia sức mạnh, tạo cho bạn một giấc mơ trong giấc mơ."
  },
  AvgDialog_118960_Content_26 = {
    Text = "Thật tiếc, bạn yêu cầu quá nhiều... vì vậy giấc mơ không ngừng tan vỡ rồi khởi động lại, đó chính là bản chất của tàu Paradiso."
  },
  AvgDialog_118960_Content_27 = {
    Text = "Nó ra đời từ mong muốn của bạn, nhưng không phải là nô lệ của bạn..."
  },
  AvgDialog_118960_Content_28 = {
    Text = "<Yellow:Vậy bây giờ, Ngài sẽ thực hiện sứ mệnh mà người sáng tạo đã giao phó.>"
  },
  AvgDialog_118960_Content_29 = {
    Text = "Màn trời bắt đầu cuộn lại, vải đen che khuất tầm nhìn, thân thể khổng lồ như đỉnh núi vươn lên."
  },
  AvgDialog_118960_Content_3 = {Text = "?！"},
  AvgDialog_118960_Content_30 = {
    Text = "Điều đó không phải từ vực thẳm nổi lên, mà là \"ý chí\" chính phá vỡ thân xác chiều không gian."
  },
  AvgDialog_118960_Content_31 = {
    Text = "Dưới bầu trời ngột ngạt, cơ thể của Ngài lặng lẽ lộ ra: nhợt nhạt, mảnh mai, khớp gãy như xương thánh bị tra tấn đến dị dạng."
  },
  AvgDialog_118960_Content_32 = {
    Text = "<Big:<Shake:……!!!>>"
  },
  AvgDialog_118960_Content_33 = {Text = "Muphí…"},
  AvgDialog_118960_Content_34 = {
    Text = "Hình dáng khổng lồ đó rõ ràng là hình dáng của người thiếu nữ mà bạn quen thuộc."
  },
  AvgDialog_118960_Content_35 = {
    Text = "<Red:Giấc mơ...phải...tiếp tục...>"
  },
  AvgDialog_118960_Content_4 = {
    Text = "<Red:không thể kết thúc>"
  },
  AvgDialog_118960_Content_5 = {
    Text = "Bầu trời bắt đầu khâu lại, màng đen che khuất bầu trời, tập hợp thành bầu trời giả."
  },
  AvgDialog_118960_Content_6 = {
    Text = "Kẽo kẹt, bạn nghe thấy âm thanh của bánh xe quay trở lại."
  },
  AvgDialog_118960_Content_7 = {
    Text = "Tại sao? Tại sao? Tôi rõ ràng đã quyết định kết thúc giấc mơ này…"
  },
  AvgDialog_118960_Content_8 = {
    Text = "Bởi vì... mẹ thần kính yêu, chủ nhân của giấc mơ này vốn không phải là bạn."
  },
  AvgDialog_118960_Content_9 = {Text = "??!!"},
  AvgDialog_118961_Content_1 = {
    Text = "Sinh hư cấu"
  },
  AvgDialog_118961_Content_10 = {
    Text = "Có ngạc nhiên không? Con đường thoát duy nhất trên con tàu này vốn nằm trong tầm kiểm soát của tôi."
  },
  AvgDialog_118961_Content_11 = {
    Text = "Goliath bắt chặt Murphy, lưỡi kiếm khổng lồ đặt sát cổ cô.\nMáu tuôn từ cổ xuống, hòa vào vết sẹo không bao giờ lành trên ngực."
  },
  AvgDialog_118961_Content_12 = {Text = "Muphí!"},
  AvgDialog_118961_Content_13 = {
    Text = "Mẹ Thần!"
  },
  AvgDialog_118961_Content_14 = {
    Text = "Xin lỗi, tôi vẫn không yên lòng..."
  },
  AvgDialog_118961_Content_15 = {
    Text = "Không phải Miryam không muốn buông tha cô gái nhỏ này, mà chính cô gái nhỏ này đang ràng buộc Miryam."
  },
  AvgDialog_118961_Content_16 = {
    Text = "Chính là cô ấy không chịu, không muốn, không dám để Miryam biết sự thật."
  },
  AvgDialog_118961_Content_17 = {
    Text = "Sự thật bạn nói là gì?"
  },
  AvgDialog_118961_Content_18 = {
    Text = "Cô cũng không biết cái gọi là Lemuria ở đâu, cô chưa bao giờ thấy chân dung của Thần."
  },
  AvgDialog_118961_Content_19 = {
    Text = "Bởi vì cô ấy không biết, nên con tàu này chỉ có thể trôi nổi trên biển, cứ như vậy mãi trôi nổi."
  },
  AvgDialog_118961_Content_2 = {
    Text = "Vậy, vào lúc Thần đã giáng thế, tại sao bạn lại giữ chặt Murphy trong tay như vậy?"
  },
  AvgDialog_118961_Content_20 = {
    Text = "Tôi không biết cô bé này đã dùng lời lẽ gì để quyến rũ các ngươi."
  },
  AvgDialog_118961_Content_21 = {
    Text = "Một thuyền trưởng Thủy thủ, một người bí ẩn từ trên trời rơi xuống, bị một cô gái nhỏ chao đảo."
  },
  AvgDialog_118961_Content_22 = {
    Text = "Có phải bạn đã quên lúc cô ấy chạy trốn không?"
