  AvgDialog_118961_Content_23 = {Text = "Chạy."},
  AvgDialog_118961_Content_24 = {
    Text = "Cô gái đang chạy."
  },
  AvgDialog_118961_Content_25 = {
    Text = "Cô không biết điểm đến của cuộc hành trình, cũng không biết liệu có thể thoát khỏi tầm mắt của mẹ nuôi."
  },
  AvgDialog_118961_Content_26 = {
    Text = "<Shake:Hà, hà……>"
  },
  AvgDialog_118961_Content_27 = {
    Text = "Phía trước không có ai tiếp ứng cô ấy, phía sau âm thanh tiếng vỗ của chân vịt ngày càng dày đặc và kỳ quái."
  },
  AvgDialog_118961_Content_28 = {
    Text = "Tin tức về việc thánh nữ mất tích đã lan ra, Thủy thủ đang tập hợp đội ngũ."
  },
  AvgDialog_118961_Content_29 = {
    Text = "Chết tiệt, những kẻ phiền phức này."
  },
  AvgDialog_118961_Content_3 = {
    Text = "Âm thanh chất vấn của bạn vang vọng."
  },
  AvgDialog_118961_Content_30 = {
    Text = "Sau ánh sáng chói lọi, bóng hình áo tím tượng trưng cho thất bại của cô ấy xuất hiện từ từ…"
  },
  AvgDialog_118961_Content_32 = {
    Text = "Murphy trong thế giới này đã không thể thoát ra."
  },
  AvgDialog_118961_Content_33 = {
    Text = "Bởi vì người đã đưa cô vào Thủy thủ, lại bỗng dưng hối hận đưa cô ra..."
  },
  AvgDialog_118961_Content_34 = {
    Text = "Đã biến mất vĩnh viễn trong thảm họa phân rã do vụ nổ lớn đó."
  },
  AvgDialog_118961_Content_35 = {
    Text = "Cô bé này không phải tự nguyện trở thành thần mẫu, cũng giống như tôi không tự nguyện trở thành nô lệ của bạn."
  },
  AvgDialog_118961_Content_36 = {
    Text = "Tất cả chúng tôi đều vì... những điều mà chúng tôi mong muốn."
  },
  AvgDialog_118961_Content_37 = {
    Text = "<Shake:Không, tôi không muốn thứ gì cả.>Tôi…… không muốn gì cả."
  },
  AvgDialog_118961_Content_38 = {
    Text = "Bạn không muốn gì cả sao? Không, bạn muốn nhiều thứ hơn."
  },
  AvgDialog_118961_Content_39 = {
    Text = "Bạn vừa muốn tận hưởng cuộc sống ưu đãi của Thần Mẫu lại không muốn chịu trách nhiệm với tư cách là người dẫn dắt."
  },
  AvgDialog_118961_Content_4 = {
    Text = "Nắm chặt trong tay, ý của bạn là...?"
  },
  AvgDialog_118961_Content_40 = {
    Text = "Bạn sợ bị người khác bỏ rơi, nên bạn xem người khác như con rối trong cuộc sống của mình, là món đồ chơi để tổ chức tiệc trà giả."
  },
  AvgDialog_118961_Content_41 = {
    Text = "Cứ sau một khoảng thời gian, bạn sẽ xóa sạch ký ức của tất cả mọi người trên tàu, sau đó bắt đầu một vòng hồi sinh mới."
  },
  AvgDialog_118961_Content_42 = {
    Text = "Cô bé, để tôi nói với bạn: đừng tự phụ trí khôn, mọi thứ trong thế gian đều có giá phải trả."
  },
  AvgDialog_118961_Content_43 = {
    Text = "Bạn có phải nghĩ rằng sẽ không bao giờ có ai phát hiện ra mánh khóe nhỏ của bạn? Nghĩ rằng với bức tượng ngà đó, bạn sẽ trở nên vô hạn?"
  },
  AvgDialog_118961_Content_44 = {
    Text = "Murphy siết chặt bức Tượng ngà trong tay."
  },
  AvgDialog_118961_Content_45 = {
    Text = "Đừng ngốc nghếch, đứa trẻ ngốc."
  },
  AvgDialog_118961_Content_46 = {
    Text = "Bạn có nghĩ rằng tôi không biết hành động của bạn? Tôi chỉ là chưa chuẩn bị sẵn sàng cho cuộc đối đầu trực diện với bạn."
  },
  AvgDialog_118961_Content_47 = {
    Text = "Mỗi một vòng luân hồi, tôi đều thử cách để thay đổi cách cướp tàu. Đe dọa bạn, đe dọa Miryam, phá hủy phòng năng lượng..."
  },
  AvgDialog_118961_Content_48 = {
    Text = "Sau đó tôi nhận ra, chỉ cần cái điêu khắc ngà voi chết tiệt ấy còn đó, tôi không có không gian để chống lại bạn."
  },
  AvgDialog_118961_Content_49 = {
    Text = "Tiếng cười khinh bỉ của Goliath vang vọng trên boong tàu."
  },
  AvgDialog_118961_Content_5 = {
    Text = "Chắc chắn bạn đã tạo ra giấc mơ này, giam cầm Murphy trong giấc mơ luân hồi phải không?"
  },
  AvgDialog_118961_Content_50 = {
    Text = "Cho đến vài tháng trước, cuộc hành động thành phố mai táng bị phá hủy bởi cái nhỏ bé trước mặt này."
  },
  AvgDialog_118961_Content_51 = {
    Text = "Không truy thu đủ bạc, sức mạnh của bức tượng ngà đã mất đi, ký ức của thể thức tỉnh trên tàu đã sớm bị lung lay."
  },
  AvgDialog_118961_Content_52 = {
    Text = "Bạn nhớ tất cả mọi chuyện…… họ có nhớ tất cả mọi chuyện không?……"
  },
  AvgDialog_118961_Content_53 = {
    Text = "Vậy, William không nhớ mọi chuyện, là vì anh ấy đến từ một thế giới khác."
  },
  AvgDialog_118961_Content_54 = {
    Text = "Những người có linh tính khác, không khác gì tôi…… họ biết trời đất đảo lộn, thời gian và không gian quay ngược."
  },
  AvgDialog_118961_Content_55 = {
    Text = "<Small:<Shake:Tất cả những người bạn nói……bao gồm……cô ấy sao?>>"
  },
  AvgDialog_118961_Content_56 = {
    Text = "Murphy cúi đầu, giọng nói của cô nhẹ đến mức gần như không nghe thấy, ánh mắt cô giao động không ngừng, mỗi lần hướng về người phụ nữ bên cạnh, nhưng chưa chạm đến ánh mắt người đó đã ngay lập tức rút lại."
  },
  AvgDialog_118961_Content_57 = {
    Text = "Cô bé ngu ngốc này, tôi đang nói đến tất cả các thể thức tỉnh."
  },
  AvgDialog_118961_Content_58 = {
    Text = "Trong đó, đương nhiên cũng bao gồm người phụ nữ ngốc nghếch Miryam."
  },
  AvgDialog_118961_Content_59 = {
    Text = "Ý của bạn là.."
  },
  AvgDialog_118961_Content_6 = {
    Text = "Miryam cân nhắc chưa lên tiếng, âm thanh cười sằng sặc đầy uy lực từ phía sau bạn vang lên."
  },
  AvgDialog_118961_Content_60 = {
    Text = "Miryam nhớ rõ mọi chuyện xảy ra mỗi lần vòng lặp, cô ấy đã đợi bạn từ lần này qua lần khác."
  },
  AvgDialog_118961_Content_61 = {
    Text = "Tôi có thể kết nối với giấc mơ của gã ở bên đó, tôi đã chứng kiến kết cục của thế giới đó. Tôi đoán, Miriam cũng có thể làm như vậy."
  },
  AvgDialog_118961_Content_62 = {
    Text = "Nhưng trong tất cả các vòng luân hồi mà tôi biết, cô ấy không thực hiện bất kỳ nỗ lực nào, chỉ thụ động chờ đợi."
