  AvgDialog_118961_Content_66 = {
    Text = "<Shake:Tại sao? Tôi không hiểu tại sao?>"
  },
  AvgDialog_118961_Content_67 = {
    Text = "Đối với bạn, tôi không nên là một sản phẩm thất bại, một công cụ bị loại bỏ sao?"
