  AvgDialog_118961_Content_68 = {
    Text = "Bạn không phải nên từ bỏ tôi như đã từ bỏ họ sao?"
  },
  AvgDialog_118961_Content_7 = {
    Text = "Để tôi nói cho bạn biết nhé."
  },
  AvgDialog_118961_Content_8 = {
    Text = "<Shake:Bởi vì cô bé tên Murphy này là một kẻ lừa đảo.>"
  },
  AvgDialog_118961_Content_9 = {
    Text = "Người Perishite dẫn đầu đám đông phá thành một kẽ hở nhỏ, giữa kẽ hở một thủy thủ đẩy Murphy đang bối rối."
  },
  AvgDialog_118962_Content_1 = {
    Text = "Bạn đóng cửa buồng lái, cắm chốt lại, lắng nghe tiếng bước chân truy đuổi chuyển hướng sang một bên, rồi mới quay lại quan sát con con tin nhỏ của bạn."
  },
  AvgDialog_118962_Content_10 = {
    Text = "Nếu họ không thực hiện trách nhiệm của mình... thì sẽ ở đâu nhỉ?"
  },
  AvgDialog_118962_Content_11 = {
    Text = "Theo tính khí của Goliath, chắc hẳn không phải đi đánh bạc ở sòng bài ngầm đâu."
  },
  AvgDialog_118962_Content_12 = {
    Text = "Chắc chắn anh ta đang âm thầm vạch ra điều gì đó…"
