  AvgDialog_118962_Content_22 = {
    Text = "Dù là bạn hay bạn bè của bạn, kể từ khi lên tàu, tất cả thủy thủ đều đối xử với nhau rất lịch sự."
  },
  AvgDialog_118962_Content_23 = {
    Text = "Hai người lại báo đáp ân tình bằng sự phản bội, bắt cóc Thần Mẫu, khiến nghi thức định hướng quan trọng không thể tiến hành đúng hạn."
  },
  AvgDialog_118962_Content_24 = {
    Text = "Nếu bỏ lỡ khoảnh khắc chính vị của ngôi sao lần này, nguyện vọng vĩ đại của chúng ta sẽ phải chờ thêm tận sáu mươi lần vòng luân hồi của các vị sao."
  },
  AvgDialog_118962_Content_25 = {
    Text = "Chắc chắn có lý do phía sau, và tôi muốn nghe lý do của hai vị."
  },
  AvgDialog_118962_Content_26 = {
    Text = "Bởi vì vòng lặp mà người giữ gìn trải qua? Bởi vì cô gái đó từng là một phần của Mythag?"
  },
  AvgDialog_118962_Content_27 = {
    Text = "William vẫn chưa sắp xếp được ý nghĩ để trả lời, thì đột ngột từ phía sau phát ra tiếng động trơn ướt kinh tởm."
  },
  AvgDialog_118962_Content_28 = {
    Text = "Anh ta nhanh chóng quay lại — đồng tử co lại ngay lập tức. Một số ngư nhân đã như dòng nước bẩn đổ ập vào toàn bộ cửa sổ."
  },
  AvgDialog_118962_Content_29 = {
    Text = "Các chi thể biến dạng tranh nhau chen chúc vào trong phòng, chất lỏng hôi thối và dính nhầy như thác nước ào xuống, ngay lập tức làm ướt thảm thành một vùng đầm lầy trơn trượt."
  },
  AvgDialog_118962_Content_3 = {
    Text = "Cô không biết từ đâu lấy ra một cái gương nhỏ, tỉ mỉ chỉnh sửa những sợi tóc rối bên trán."
  },
  AvgDialog_118962_Content_30 = {
    Text = "Anh ta như một cái đinh, bị ghim chặt vào điểm chết nơi hai cơn sóng xấu sắp giao nhau."
  },
  AvgDialog_118962_Content_31 = {
    Text = "Làm thế nào mà lại làm được như vậy..."
  },
  AvgDialog_118962_Content_32 = {
    Text = "Cửa sổ tàu cách boong tàu hơn mười mét, người giữ gìn sau khi thoát ra cũng kịp thời cắt đứt sợi dây dài."
  },
  AvgDialog_118962_Content_33 = {
    Text = "Chúng vào bằng cách nào qua bức tường trơn, lặng lẽ lén lút từ cửa sổ?"
  },
  AvgDialog_118962_Content_34 = {
    Text = "Vùng đất thần thánh đã ban cho chúng tôi sức mạnh để chống lại thiên tai, những trở ngại nhỏ bé này tự nhiên không thể giam cầm thủy thủ."
  },
  AvgDialog_118962_Content_35 = {
    Text = "Sinh vật biển… có phải là cái đĩa ở chân không?"
  },
  AvgDialog_118962_Content_36 = {
    Text = "Ngoài các thủy thủ trú ngụ trên du thuyền, các sinh vật biển bao quanh toàn bộ thân tàu đều được triệu hồi bởi linh hồn của chủ nhân, nghe theo sự dẫn dắt của chúng tôi."
  },
  AvgDialog_118962_Content_37 = {
    Text = "Dẫu không phải theo cách này, bạn cũng nên biết rằng mình không thể dựa vào một căn phòng nhỏ bé để chống lại toàn bộ giáo hội Thủy thủ..."
  },
  AvgDialog_118962_Content_38 = {
    Text = "Điều tra viên của Mythag không thể nóng vội như vậy... Nói cho tôi biết, bạn còn biết gì khác không?"
  },
  AvgDialog_118962_Content_39 = {
    Text = "<Big:<Shake:Rầm rộ——>>"
