  AvgDialog_118962_Content_4 = {
    Text = "Cấu trúc mà bạn nói đến… ở đâu?"
  },
  AvgDialog_118962_Content_40 = {
    Text = "Một tiếng động lớn như kim loại bị xé rách đột ngột xé toạc bầu không khí, cùng với sự chấn động dữ dội, thân tàu dường như bị một bàn tay vô hình bất ngờ nắm chặt, quay mạnh!"
