  AvgDialog_118962_Content_46 = {
    Text = "Lại đến rồi..."
  },
  AvgDialog_118962_Content_47 = {
    Text = "Những cú rung động mãnh liệt liên tiếp bùng nổ."
  },
  AvgDialog_118962_Content_48 = {Text = "Muphí…"},
  AvgDialog_118962_Content_49 = {
    Text = "Tôi biết, bạn chắc chắn không thể không nhớ vị học trưởng nào đó của bạn, đúng không?"
  },
  AvgDialog_118962_Content_5 = {
    Text = "Ngay dưới ghế thuyền trưởng, đây này."
  },
  AvgDialog_118962_Content_50 = {
    Text = "Tôi hiểu cả rồi, một người một nói rằng tôi là người quan trọng nhất, nhưng đến lúc quyết định thì lại dễ dàng vứt bỏ tôi."
  },
  AvgDialog_118962_Content_51 = {Text = "Tôi……"},
  AvgDialog_118962_Content_52 = {
    Text = "Rồi rồi, chỉ là một số phàn nàn vô ích mà thôi. Tôi với bạn có quen biết gì chứ?"
  },
  AvgDialog_118962_Content_53 = {
    Text = "Hơn nữa, nếu phòng năng lượng phát nổ, khoang tàu dưới tầng chỉ sợ cũng sẽ bị ảnh hưởng."
  },
  AvgDialog_118962_Content_54 = {
    Text = "Đi nào, chúng ta không có lựa chọn thứ hai."
  },
  AvgDialog_118962_Content_6 = {
    Text = "Cô ấy đạp lên tấm kim loại dưới chân."
  },
  AvgDialog_118962_Content_7 = {
    Text = "Tuy nhiên, ở đây có chút kỳ lạ…"
  },
  AvgDialog_118962_Content_8 = {
    Text = "Thời điểm này trước đây, Goliath và Caecus lẽ ra nên canh giữ buồng lái."
  },
  AvgDialog_118962_Content_9 = {
    Text = "Những sinh linh dưới đáy biển trước lễ nghi sẽ rơi vào trạng thái kích động, chúng ta phải ngăn chặn những đàn cá điên rồ làm gián đoạn hướng đi của thuyền…"
  },
  AvgDialog_118963_Content_1 = {
    Text = "Ngày nghỉ của Thần Mẫu"
  },
  AvgDialog_118963_Content_10 = {
    Text = "Bạn đang nói rằng.."
  },
  AvgDialog_118963_Content_11 = {
    Text = "Đúng thế, bạn vẫn có thể làm thần mẫu của mình. Nhưng hôm nay là ngày nghỉ của thần mẫu."
  },
  AvgDialog_118963_Content_12 = {
    Text = "Bạn không hề thay đổi sắc mặt mà nói ra lời dối trá."
  },
  AvgDialog_118963_Content_13 = {
    Text = "Kỳ nghỉ của Mẹ Thần?"
  },
  AvgDialog_118963_Content_14 = {
    Text = "Đúng rồi, hôm nay, tôi được giao nhiệm vụ đưa bạn chơi trên thuyền một ngày."
  },
  AvgDialog_118963_Content_15 = {
    Text = "Sau khi lên tàu, bạn chưa từng trải nghiệm cuộc sống thật sự của một thủy thủ phải không?"
  },
  AvgDialog_118963_Content_16 = {
    Text = "Không thể từ chối, bạn đã \"mời\" Murphy ra khỏi phòng ngủ."
  },
  AvgDialog_118963_Content_17 = {
    Text = "Chúng tôi nhất định phải leo lên những nơi như vậy sao?"
  },
  AvgDialog_118963_Content_18 = {
    Text = "Nhanh lên, chỉ có ở đó tầm nhìn tốt, có thể quan sát tình hình của Thủy thủ đang tuần tra."
  },
  AvgDialog_118963_Content_19 = {
    Text = "Chậm một chút nữa thôi, sẽ bị người khác phát hiện ra mất!"
  },
  AvgDialog_118963_Content_2 = {
    Text = "Bạn mở mắt. Ánh nắng chói chang làm bạn đau mắt."
  },
  AvgDialog_118963_Content_20 = {
    Text = "Cái gì vậy, làm cho mọi thứ rối bời!"
  },
  AvgDialog_118963_Content_21 = {
    Text = "Dù nói như vậy, cô ấy vẫn ngoan ngoãn nắm tay bạn, bạn chỉ cần kéo nhẹ, và cô ấy đã lên được nền tảng."
  },
  AvgDialog_118963_Content_22 = {Text = "Phù—"},
  AvgDialog_118963_Content_23 = {
    Text = "Murphy đột nhiên cười thành tiếng."
  },
  AvgDialog_118963_Content_24 = {
    Text = "Cười gì vậy?"
  },
  AvgDialog_118963_Content_25 = {
    Text = "Bạn trông giống như một con khỉ khi trèo lên dây đai!"
  },
  AvgDialog_118963_Content_26 = {
    Text = "Bạn này, nếu không phải bây giờ phải giữ âm lượng, tôi chắc chắn sẽ đập một cái vào trán bạn..."
  },
  AvgDialog_118963_Content_27 = {
    Text = "Đừng cười! Bạn cũng không thể trốn được đâu!"
  },
  AvgDialog_118963_Content_28 = {
    Text = "Bạn nắm chặt tay Murphy, kéo cô ấy về bên cạnh bạn."
  },
  AvgDialog_118963_Content_29 = {
    Text = "Này, bạn dám sao!"
  },
  AvgDialog_118963_Content_3 = {
    Text = "Nhưng bạn không rời mắt đi."
  },
  AvgDialog_118963_Content_30 = {Text = "Suỵt!"},
  AvgDialog_118963_Content_31 = {
    Text = "Bạn nín thở, một đội thủy thủ mặc áo mưa rơm bẩn thỉu, loạng choạng đi qua boong tàu."
  },
  AvgDialog_118963_Content_32 = {
    Text = "Nhanh lên, tìm ra vị trí của Mẹ Thần! Chắc chắn bà ấy đang ở trên con tàu này!"
  },
  AvgDialog_118963_Content_33 = {
    Text = "Chúng tôi đang ở ngay trên đầu họ, họ hoàn toàn không nhìn thấy?"
  },
  AvgDialog_118963_Content_34 = {
    Text = "Từ xưa đến nay, tuần tra không bao giờ ngẩng đầu lên."
  },
  AvgDialog_118963_Content_35 = {
    Text = "Yên tâm, chỉ cần trốn ở đây, chắc chắn không ai có thể phát hiện ra chúng ta."
  },
  AvgDialog_118963_Content_36 = {
    Text = "Quack, nhìn lên trên, có người ở đó!"
  },
  AvgDialog_118963_Content_37 = {
    Text = "Bạn thật đúng là có cái miệng quạ quá chính xác!"
  },
  AvgDialog_118963_Content_38 = {
    Text = "Hãy kín đáo một chút, sau khi xóa sạch nhóm này, chúng ta lập tức lẻn vào phòng thuyền viên!"
  },
  AvgDialog_118963_Content_4 = {
    Text = "Xào xạc, xào xạc, âm thanh của con nhện bò như những sự khích lệ dịu dàng của mẹ."
  },
  AvgDialog_118963_Content_5 = {
    Text = "Không cần nhắc nhở tôi. Tôi biết, đây là vòng luân hồi cuối cùng."
  },
  AvgDialog_118963_Content_6 = {
    Text = "Bạn lau nước mắt chảy ra từ khóe mắt, quay về hướng có tiếng gọi sắp vang lên mà không quay lại xác nhận nguồn gốc của âm thanh."
  },
  AvgDialog_118963_Content_7 = {
    Text = "Bởi vì bạn biết, người phụ nữ ôm lấy khung dệt chắc chắn đang nhìn bạn bằng ánh mắt từ bi."
  },
  AvgDialog_118963_Content_8 = {
    Text = "Bạn còn đến đây làm gì? Con tàu đã khôi phục con đường của nó, đã không còn chỗ cho bạn ở đây."
  },
  AvgDialog_118963_Content_9 = {
    Text = "Không sao cả, bạn là thần mẹ của thủy thủ, cũng là thuyền trưởng của chiếc Paradis, chủ nhân của Thiên Đàng. Điều này không liên quan đến việc tôi muốn cho bạn một kỳ nghỉ."
  },
  AvgDialog_119922_Content_1 = {
    Text = "Chào mừng trở lại, đồng đội."
  },
  AvgDialog_119922_Content_10 = {
    Text = "Không sao đâu, chủ tôn, dù bạn chạy bao lâu, Ogier sẽ luôn bên cạnh bạn. Tôi chỉ hy vọng……"
  },
  AvgDialog_119922_Content_11 = {
    Text = "Kị sĩ trẻ tuổi nhìn bạn với ánh mắt nghiêm túc, trong đôi mắt anh ta đầy chân thành và một mong cầu tiềm ẩn dưới sự chân thành đó."
  },
  AvgDialog_119922_Content_12 = {
    Text = "Tôi chỉ hy vọng rằng... nếu chủ nhân còn chuẩn bị \"giải khuây\", rời đi lâu như vậy, hãy nhất định mang theo tôi. Ogier sẽ quyết tâm bảo vệ ngài."
  },
  AvgDialog_119922_Content_13 = {
    Text = "Hoặc tôi cũng có thể."
  },
  AvgDialog_119922_Content_14 = {
    Text = "Lotan cũng nhìn về phía bạn, đôi mắt thường ngày tỏa ra vẻ nổi bật tràn đầy trịnh trọng. Lúc này, trong đầu cô ấy thực sự không có thắng bại, cũng không có trận chiến, chỉ có sự quan tâm đến bạn."
  },
  AvgDialog_119922_Content_15 = {
    Text = "... Tôi biết sẽ như vậy. Hai bạn, đừng quên mục tiêu của buổi trà đàm này. Chúng ta đang ăn mừng \"Sự trở lại\" của %player%."
  },
  AvgDialog_119922_Content_16 = {
    Text = "Hy vọng lần này sau khi bạn \"trở về\", thì đừng rời đi nữa."
  },
  AvgDialog_119922_Content_17 = {
    Text = "Chỉ là một lần thư giãn thôi, đừng nói nghiêm trọng như vậy... mà tôi có phải đã quay về rồi sao?"
  },
  AvgDialog_119922_Content_18 = {
    Text = "Nghe thấy lời bạn, Búp bê nhìn về phía bạn. Cô ấy dường như muốn nói điều gì đó, nhưng cuối cùng chỉ thở dài nhẹ nhàng."
  },
  AvgDialog_119922_Content_19 = {
    Text = "Đúng vậy, bạn đã trở về, những người tìm kiếm hình bóng của bạn trong trường học nhưng chỉ có thể thất vọng, những người đứng lặng lẽ trước cửa phòng bạn nhưng không dám gõ cửa, cũng đã qua rồi."
  },
  AvgDialog_119922_Content_2 = {
    Text = "Không biết từ khi nào, quảng trường Mythag đã được chuẩn bị thành một buổi trà nhỏ, Ramona đứng bên bàn đầy bánh nướng, mứt và trà, mỉm cười vươn tay về phía bạn."
  },
  AvgDialog_119922_Content_20 = {
    Text = "%player%， tôi đã nói vô số lần và sẽ tiếp tục như vậy trong tương lai, sự tồn tại của bạn là vô cùng quan trọng."
  },
  AvgDialog_119922_Content_21 = {
    Text = "Dù là với thế giới này, hay với chúng ta. Vì vậy…"
  },
  AvgDialog_119922_Content_22 = {
    Text = "Bạn lặng lẽ chờ đợi Búp bê nói tiếp, nhưng Búp bê chỉ nhắm mắt lại, không nói thêm gì."
  },
  AvgDialog_119922_Content_23 = {
    Text = "Lúc này, đôi tay nhẹ nhàng nhưng kiên định phủ lên mu bàn tay bạn, đó là Ramona."
  },
  AvgDialog_119922_Content_24 = {
    Text = "Đối tác, tôi biết là với vai trò người giữ gìn, bạn đã gánh chịu nhiều áp lực, chúng tôi đều hiểu và thông cảm. Vì vậy, chúng tôi sẽ không yêu cầu quá nhiều."
  },
  AvgDialog_119922_Content_25 = {
    Text = "Tôi chỉ muốn bạn biết, dù bạn đi bao nhiêu lần, dù bạn đi bao lâu, khi bạn trở về, chúng tôi vẫn ở đây."
  },
  AvgDialog_119922_Content_26 = {
    Text = "Nói đến đây, giọng nói của cô gái dừng lại một chút, từ từ nở nụ cười với bạn."
  },
  AvgDialog_119922_Content_27 = {
    Text = "Một lần nữa chào mừng sự trở lại của bạn, đồng đội. Bây giờ, hãy tận hưởng buổi trà đàm đã chuẩn bị cho bạn nhé."
  },
  AvgDialog_119922_Content_28 = {
    Text = "Đúng vậy. Hôm nay không có kiểm tra, không có bài tập thêm. Nhiệm vụ duy nhất của bạn là hãy làm cho bản thân vui vẻ."
  },
  AvgDialog_119922_Content_29 = {
    Text = "Nếu bạn không bận tâm đến vấn đề sâu răng và lượng đường tiêu thụ quá mức, bạn có thể ăn hết những món tráng miệng này. Dù sao chúng cũng được chuẩn bị cho bạn."
  },
  AvgDialog_119922_Content_3 = {
    Text = "Không biết liệu tôi có vinh dự này hay không, mời bạn tham gia buổi trà tán gẫu mà chúng tôi chuẩn bị cho bạn?"
  },
  AvgDialog_119922_Content_30 = {
    Text = "Cũng không cần thiết……"
  },
  AvgDialog_119922_Content_31 = {
    Text = "Mặc dù nói như vậy, bạn vẫn thử miếng bánh bơ rắc đường. Hương vị cũng giống như bạn tưởng tượng, ngọt đến nỗi quá mức, nhưng không hề khó chịu."
  },
  AvgDialog_119922_Content_32 = {
    Text = "Bởi vì trong ánh nhìn quan tâm của mọi người, trái tim bạn đã nhận được sự thỏa mãn. Có lẽ, cuộc sống chính là trong những khoảng trống đắng cay của thực tại, nếm trải một miếng ngọt lay động lòng người."
  },
  AvgDialog_119922_Content_4 = {
    Text = "Bạn gật đầu, do đó, cô gái nhẹ nhàng nắm lấy tay bạn, dẫn bạn đến chiếc bàn hình tam giác đầy thức ăn, còn có những thể thức tỉnh đã chờ đợi bên bàn từ lâu."
  },
  AvgDialog_119922_Content_5 = {
    Text = "Theo tôi, đánh một trận không thú vị hơn hội trà chứ? Nhưng đúng là... lần này không giống như trước."
  },
  AvgDialog_119922_Content_6 = {
    Text = "Lần này, không liên quan đến thắng thua, không liên quan đến chiến đấu. Chỉ liên quan đến bạn."
  },
  AvgDialog_119922_Content_7 = {
    Text = "%player%， bạn là nhân vật chính tuyệt đối của buổi trà đàm này."
  },
  AvgDialog_119922_Content_8 = {
    Text = "Lotan nói, đẩy đĩa bánh cuộn bơ đường đến trước mặt bạn.\n Chỉ cần liếc nhìn, bạn đã biết nó có lượng calo khủng khiếp."
  },
  AvgDialog_119922_Content_9 = {
    Text = "Tôi cảm thấy... chỉ cần ăn vào một miếng, sẽ cần chạy một học kỳ để tiêu hóa..."
  },
  AvgDialog_119923_Content_1 = {
    Text = "Trong bãi bùn tinh thần đen tối, có một cơn đau chích thấu tận linh hồn, và những lời nói lạnh lẽo vang lên."
  },
  AvgDialog_119923_Content_10 = {
    Text = "Nhớ lại cảm giác bị mở hộp sọ, đầu bạn bỗng lùng bùng, để thoát khỏi cảm giác này, bạn tự giác chuyển chủ đề."
  },
  AvgDialog_119923_Content_11 = {
    Text = "Thế giới này... bây giờ tình hình thế nào?"
  },
  AvgDialog_119923_Content_12 = {
    Text = "Vẫn như cũ. Mỗi khoảnh khắc đều đang gần đỉnh của sự sụp đổ và hủy diệt. Nhưng ít nhất cũng có tin tốt, dành cho bạn."
  },
  AvgDialog_119923_Content_13 = {
    Text = "Nói xong, Búp bê·Đôr mở thiết bị liên lạc, rất nhanh, một hình dáng quen thuộc xuất hiện trước mắt bạn. Đó là thông điệp đã được ghi âm trước đó."
  },
  AvgDialog_119923_Content_14 = {
    Text = "Đúc thủy·Búp bê, nếu %player% thành công trở về, hoặc có bất kỳ tin tức nào, nhớ báo cho tôi. Hơn nữa, tôi nghĩ đề nghị trước đó về việc trồng gợi ý tâm lý rất hợp lý."
  },
  AvgDialog_119923_Content_15 = {
    Text = "Là một bác sĩ tâm lý chuyên nghiệp, tôi không thể quá thỏa hiệp với mong muốn của bệnh nhân trong việc để %player% ở lại lĩnh vực này..."
  },
  AvgDialog_119923_Content_16 = {
    Text = "Thông tin bị ngừng lại ở đây, bị tan chảy · Búp bê đóng lại. Cô nhẹ nhàng vỗ mặt bàn, ra hiệu bạn chuyển sự chú ý về phía cô."
  },
  AvgDialog_119923_Content_17 = {
    Text = "Những lời xã giao vô nghĩa có thể dừng lại ở đây. Tôi bỏ những thứ này ra, chỉ là để cho bạn thấy, trong khoảng thời gian bạn \"rời đi\", rốt cuộc đã bỏ lỡ những gì."
  },
  AvgDialog_119923_Content_18 = {
    Text = "Điều quan trọng nhất là, thí nghiệm của tôi vẫn chưa kết thúc..."
  },
  AvgDialog_119923_Content_19 = {
    Text = "Đúc thủy·Búp bê cầm dao phẫu thuật, tiến về phía bạn. Biểu cảm của cô rất bình tĩnh, nhưng lại chứa đựng một cơn điên cuồng."
  },
  AvgDialog_119923_Content_2 = {
    Text = "Bạn còn định giả ngủ đến bao giờ? Cún con yêu quý của tôi."
  },
  AvgDialog_119923_Content_20 = {
    Text = "Bạn, bạn định làm gì?"
  },
  AvgDialog_119923_Content_21 = {
    Text = "Dự định sẽ cố định tinh thần của bạn mãi mãi trong cái đầu này, trong cơ thể này. Như vậy, bạn sẽ không thể \"rời đi\" nữa."
  },
  AvgDialog_119923_Content_22 = {
    Text = "Bạn sợ hãi lùi lại một bước, nhưng nhanh chóng bình tĩnh lại, vì bạn nhớ ra còn việc chưa hoàn thành—"
  },
  AvgDialog_119923_Content_23 = {
    Text = "Đúc thủy·Búp bê, không cần như vậy. Chỉ cần thế giới này chưa trở lại bình thường, tôi sẽ không thực sự rời đi."
  },
  AvgDialog_119923_Content_24 = {
    Text = "Bóng dáng cầm dao phẫu thuật dừng lại, chỉ lặng lẽ nhìn bạn, có vẻ như đang đánh giá độ chân thật của lời bạn nói."
  },
  AvgDialog_119923_Content_25 = {
    Text = "Tôi nói nghiêm túc. Là một người giữ gìn, tôi sẽ không từ bỏ việc cứu thế giới này, vậy nên dù \"rời đi\" bao lâu, tôi sẽ luôn quay về."
  },
  AvgDialog_119923_Content_26 = {
    Text = "Đúc thủy·Búp bê đã bỏ dao phẫu thuật xuống. Nhân lúc cơ hội này, bạn đã chạm vào ngực mình.\nKhi ngón tay bạn chạm vào chiếc chìa khóa bạc quen thuộc, trái tim bạn mới thật sự bình yên."
  },
  AvgDialog_119923_Content_27 = {
    Text = "Hiện tại, tôi đã trở lại. Cuộc điều tra đã bị gián đoạn trước đây cũng có thể tiếp tục."
  },
  AvgDialog_119923_Content_28 = {
    Text = "Nói xong, bạn đi về phía cửa. Búp bê·Đôr nhìn bạn một cái, cũng theo sau."
  },
  AvgDialog_119923_Content_29 = {
    Text = "Có vẻ như bạn rất hiểu tầm quan trọng của sự tồn tại của mình đối với thế giới này."
  },
  AvgDialog_119923_Content_3 = {
    Text = "Đúc thủy·Búp bê?"
  },
  AvgDialog_119923_Content_30 = {
    Text = "Tất nhiên vì như Tawil đã nói, tôi là biến số của thế giới này, tương lai của thế giới này."
  },
  AvgDialog_119923_Content_31 = {
    Text = "Cùng với lời nói của bạn, cánh cửa phòng thí nghiệm từ từ mở ra. Không khí và ánh nắng từ bên ngoài từ từ đổ xuống bạn, như một sự chào đón im lặng, hoặc là một sự phản hồi."
  },
  AvgDialog_119923_Content_32 = {
    Text = "Thế giới này đang chờ đợi bạn, chờ đợi sự thay đổi mà bạn sắp mang đến, cùng tương lai mà bạn sắp tạo ra."
  },
  AvgDialog_119923_Content_4 = {
    Text = "Bạn đã nhận ra chủ nhân của âm thanh đó, từ từ mở mắt. Rất nhanh, bóng tối nhạt dần, ánh sáng hiện ra——"
  },
  AvgDialog_119923_Content_5 = {
    Text = "\"Rời bỏ\" cảm giác như thế nào về thế giới này?"
  },
  AvgDialog_119923_Content_6 = {
    Text = "Có thể, lần sau tôi nên giam giữ cả \"linh hồn\" của bạn, như vậy sẽ không cần tìm lại nữa."
  },
  AvgDialog_119923_Content_7 = {
    Text = "Đúc thủy·Búp bê híp mắt, lộ ra biểu cảm giống như cười mà không cười, từ từ vuốt ve con dao phẫu thuật đang lấp lánh lạnh lẽo trong tay."
  },
  AvgDialog_119923_Content_8 = {
    Text = "……Tôi sao lại ở đây?"
  },
  AvgDialog_119923_Content_9 = {
    Text = "Tất nhiên là vì \"Linh hồn\" của bạn đã rời khỏi, nên xác thịt đã mất đi công dụng, vì vậy tôi buộc phải tiến hành phẫu thuật lần nữa, để giữ lại \"Linh hồn\" của bạn."
  },
  AvgDialog_120290_Content_1 = {
    Text = "Xương mỹ nhân, nơi tiêu tán vàng"
  },
  AvgDialog_120290_Content_10 = {
    Text = "Cánh cửa mở ra, bạn rơi vào vòng tay của cô ấy. Cô ấy ôm bạn lên giường, chỉnh lại chăn cho gọn gàng, cúi xuống dùng trán chạm vào trán bạn, rồi kéo bạn lại gần dựa vào người cô ấy."
  },
  AvgDialog_120290_Content_11 = {
    Text = "Mẹ…? Mẹ!"
  },
  AvgDialog_120290_Content_12 = {
    Text = "Bố lâu không quan tâm đến con, trong nhà không có ai giúp con, cũng không có nước... Đầu con đau quá, cả người đều đau."
  },
  AvgDialog_120290_Content_13 = {
    Text = "……Cô con gái ngoan của mẹ, đừng khóc."
  },
  AvgDialog_120290_Content_14 = {
    Text = "Yên tâm, mọi thứ sẽ sớm ổn cả thôi, mẹ hứa với con."
  },
  AvgDialog_120290_Content_15 = {
    Text = "Bạn bị cuốn vào chiếc chăn ấm, mơ màng ngửi thấy mùi hương đó ngày càng trở nên nồng nàn, không còn giống như mùi hoa nhài thường thấy trên cơ thể mẹ nữa, mà giống như……"
  },
  AvgDialog_120290_Content_16 = {
    Text = "Giống như gì nhỉ… giống như trong những con hẻm chồng chất của thành phố biển, những bông hoa ngọc lan trắng lớn rơi xuống, ở góc vì nhiệt độ cao mà lên men, mùi hôi ngọt sâu sắc và dính dớp kỳ lạ."
  },
  AvgDialog_120290_Content_17 = {
    Text = "Mẹ ơi, mùi hương trên người bạn đã thay đổi sao, thật thơm, mà… mà cũng thật lạ."
  },
  AvgDialog_120290_Content_18 = {
    Text = "Giọng nói nhẹ nhàng không trả lời câu hỏi của bạn, theo từng cái vỗ về nhẹ nhàng của cô ấy, hương thơm ngày càng nồng nàn, gần như sắp hóa thành thực chất."
  },
  AvgDialog_120290_Content_19 = {
    Text = "Bạn muốn nhìn rõ khuôn mặt của cô ấy, nhưng chỉ có sương mù vô tận lan tỏa trước mắt, cuối cùng bao trùm lấy bạn."
  },
  AvgDialog_120290_Content_2 = {
    Text = "Làn sương mỏng manh mang theo hương nhài, quấn quýt quanh tứ chi, vô hình và ẩm ướt quấn lấy bạn."
  },
  AvgDialog_120290_Content_20 = {
    Text = "Ngủ đi, bé ngoan, ngủ đi, mẹ sẽ sớm trở lại bên con."
  },
  AvgDialog_120290_Content_21 = {
    Text = "……ta đã hứa với cô ấy rồi."
  },
  AvgDialog_120290_Content_22 = {
    Text = "Trong bóng tối, cơn khát vẫn như móng vuốt của mèo cào xé bạn, ngay sau đó, một loại chất lỏng ấm áp và dính dường như chảy vào họng từ mũi hoặc khóe miệng."
  },
  AvgDialog_120290_Content_23 = {
    Text = "Mí mắt của bạn ngày càng nặng, trong hương thơm và những tiếng thì thầm, dần dần hoàn toàn mất đi ý thức."
  },
  AvgDialog_120290_Content_24 = {
    Text = "……cho đến khi tiếng bước chân nhẹ nhàng tụ tập bên ngoài cửa, bạn bị tiếng nói chuyện đánh thức trong cơn đau nhức nặng nề."
  },
  AvgDialog_120290_Content_25 = {
    Text = "Ôi trời, cô tiểu thư này, mỗi ngày vừa mở mắt ra đã muốn uống trà, phiền chết đi được, thật sự tưởng mình vẫn là cô tiểu thư kiêu ngạo hồi còn sống à?"
  },
  AvgDialog_120290_Content_26 = {
    Text = "Cậu nói nhỏ chút đi!… Chủ tịch cũng không quan tâm đến cô con gái này, trong nhà có bao nhiêu người mẹ kế xinh đẹp? Cậu xem, hôm nay chẳng phải lại chạy ra đường Tứ Mã sao."
  },
  AvgDialog_120290_Content_27 = {
    Text = "Cô cứ xem đi, không mất bao nhiêu thời gian, trong phòng các bà cô đều có bụng, không thể thiếu tiểu thiếu gia tiểu tiểu thư sẽ ra ngoài…"
  },
  AvgDialog_120290_Content_28 = {
    Text = "……Thưa ngài?"
  },
  AvgDialog_120290_Content_29 = {
    Text = "Bạn ngẩng đầu lên, chiếc chậu đồng hơi bẩn trên giá gỗ, mơ hồ phản chiếu một gương mặt thanh tú của người phương Đông còn trẻ tuổi. Bạn ngơ ngác chớp mắt, cô bé nhỏ trong hình ảnh phản chiếu cũng chớp mắt."
  },
  AvgDialog_120290_Content_3 = {
    Text = "Cảm giác mệt mỏi sau cơn sốt khiến bạn không thể không áp sát vào làn sương đó…"
  },
  AvgDialog_120290_Content_30 = {
    Text = "Ý thức dần dần tỉnh táo, một số mảnh ký ức về thân phận nổi lên trong biển nhận thức của bạn."
  },
  AvgDialog_120290_Content_31 = {
    Text = "Lão gia, phương nào, bố……con đang ở nhà họ Hà, con là con gái của phương nào, con tên là……"
  },
  AvgDialog_120290_Content_32 = {
    Text = "Ôi, cậu sao có thể nằm trên đất chứ, thưa ngài thấy sẽ mắng tôi đấy."
  },
  AvgDialog_120290_Content_33 = {
    Text = "Cửa đột nhiên bị đẩy ra, suy nghĩ bị ngắt quãng, người đến vội vàng lao tới, không vui vẻ gì nâng bạn dậy."
  },
  AvgDialog_120290_Content_34 = {
    Text = "Vừa nãy rõ ràng, tôi làm sao lại ở trên mặt đất? Mẹ đâu rồi?"
  },
  AvgDialog_120290_Content_35 = {
    Text = "Mẹ? Tiểu thư, cô hãy nhớ rõ, bà đã rời đi hơn một tháng rồi."
  },
  AvgDialog_120290_Content_36 = {
    Text = "Cô ấy thốt lên, thấy bạn đứng ngẩn ra tại chỗ, trên mặt lại lộ ra vẻ không đành lòng."
  },
  AvgDialog_120290_Content_37 = {
    Text = "<Small:Cũng chỉ nhỏ bé như vậy, chắc cũng không biết đi là nghĩa gì đâu nhỉ.>"
  },
  AvgDialog_120290_Content_38 = {
    Text = "<LightGray:Đúng vậy, mẹ đã... hơn một tháng trước rồi…>"
  },
  AvgDialog_120290_Content_39 = {
    Text = "Lại mơ nữa hả, trời ạ. Nè, nước đã mang đến cho bạn rồi."
  },
  AvgDialog_120290_Content_4 = {
    Text = "Rồi thẳng một mạch ngã xuống sàn nhà."
  },
  AvgDialog_120290_Content_40 = {
    Text = "Nước… bạn đột ngột phát hiện ra mình đã không còn khát nữa, chất lỏng chảy vào lúc đó, cùng với hương thơm đi kèm."
  },
  AvgDialog_120290_Content_41 = {
    Text = "Vẫn còn lưu lại giữa răng và khoang mũi của bạn, hương thơm ngọt ngào gần như thối rữa, hương hoa ngọc lan trắng!\nBạn bỗng nhiên phản ứng lại, đột ngột lao ra ngoài."
  },
  AvgDialog_120290_Content_42 = {
    Text = "Này, này! Chạy đi đâu vậy! Thiếu nữ!"
  },
  AvgDialog_120290_Content_43 = {
    Text = "Ngày lễ hội phương Đông đã đến, đèn lồng sáng rực, đèn neon hiện đại hòa quyện với nhau, nhưng những người đáng lẽ phải trở về nhà sớm vào ngày này lại đang đổ xô về cùng một hướng."
  },
  AvgDialog_120290_Content_44 = {
    Text = "Không khí tràn ngập mùi phấn son, mùi dầu hỏa, mùi khói dầu từ quầy hàng ăn vặt và nhà hàng, cùng với mùi ngày càng nồng nặc của..."
  },
  AvgDialog_120290_Content_45 = {
    Text = "Mẹ ơi, là mùi của mẹ, không phải mơ, tôi không mơ!"
  },
  AvgDialog_120290_Content_46 = {
    Text = "Bạn đã tìm thấy, nguồn gốc của mùi tanh ngọt ngào vừa lạ lẫm, vừa mãnh liệt, vừa quen thuộc, vừa gần gũi, vừa dịu dàng."
  },
  AvgDialog_120290_Content_47 = {
    Text = "Biển hiệu của \"Tiệm Kim Khí\", treo xa xa trên cánh cửa lộng lẫy."
  },
  AvgDialog_120290_Content_48 = {
    Text = "Ông Hứa!"
  },
  AvgDialog_120290_Content_49 = {
    Text = "Dời ra, bạn đang cản đường tôi, ông Xu, nhìn bên kia kìa!"
