  },
  AvgDialog_120290_Content_52 = {
    Text = "Mọi người chen chúc nhau gần như sắp nhấn chìm bạn, sự cuồng nhiệt và lo lắng thoáng hiện lên trong ánh mắt họ, nhưng dường như không ảnh hưởng gì đến cô ấy."
  },
  AvgDialog_120290_Content_53 = {
