  AvgDialog_120291_Content_13 = {
    Text = "Cha vẫn như mọi khi được bao quanh bởi nhiều dì mà bạn không nhớ rõ mặt, những người phụ nữ trong biệt thự luôn đến rồi lại đi, người thì mập mạp, người thì gầy gò, sống động và đầy sức sống."
