  AvgDialog_120313_Content_23 = {
    Text = "Bạn không phải cũng đang cười sao…"
  },
  AvgDialog_120313_Content_24 = {
    Text = "Trong niềm hạnh phúc lớn lao, bạn không thể không nắm lấy tay cô ấy, muốn ngay lập tức trở về."
  },
  AvgDialog_120313_Content_25 = {Text = "!!!"},
  AvgDialog_120313_Content_26 = {
    Text = "Đột nhiên, bạn thấy đồng tử của cô ấy co lại, ngay lập tức, cô ấy lao tới bạn, đẩy bạn sang một bên một cách mạnh mẽ."
  },
  AvgDialog_120313_Content_27 = {
    Text = "Vào khoảnh khắc bị đánh bật ra, bạn thấy ở nơi trước đây vốn thuộc về bạn, một vết nứt chiều không gian mới, lại có một con mắt đang xoay chuyển mở ra nhìn về phía Ramona đứng nguyên tại chỗ."
  },
  AvgDialog_120313_Content_28 = {
    Text = "Trong một khoảnh khắc, vùng chất nhầy tối tăm đã nuốt chửng cô ấy."
  },
  AvgDialog_120313_Content_29 = {
    Text = "<Shake:<Big:Không!!!>>"
  },
  AvgDialog_120313_Content_3 = {
    Text = "Dưới áp lực của Ý chí tối cao, mọi thứ đều rất quen thuộc."
  },
  AvgDialog_120313_Content_4 = {
    Text = "Những con mắt trắng lớn trong chiều không gian khác lần lượt biến mất, tinh thần của bạn cũng dần dần cạn kiệt, thứ duy nhất nâng đỡ bạn chỉ còn lại bông hồng đỏ rực trong tay."
  },
  AvgDialog_120313_Content_5 = {
    Text = "Hụ... không thể ngã xuống, họ còn đang đợi tôi..."
