  AvgDialog_120313_Content_6 = {
    Text = "Trong một khoảnh khắc mơ màng, trái tim bạn bỗng nhiên bắt đầu đập mạnh, bạn quay lại theo linh cảm này."
  },
  AvgDialog_120313_Content_7 = {
    Text = "Như những ngôi sao băng băng qua, rồi như những tinh thể băng ngưng tụ, một đường hầm sáng như loạt ánh sáng kéo dài đi kèm với âm thanh kỳ diệu và không gian."
  },
  AvgDialog_120313_Content_8 = {
    Text = "Một âm thanh vang vọng trong ký ức hàng nghìn lần vượt qua không gian chiều xa xôi sau bạn, dưới sự liên kết của những xúc tu tinh thần vang lên trong đầu bạn."
  },
  AvgDialog_121232_Content_1 = {
