  AvgDialog_121232_Content_2 = {
    Text = "Sức mạnh thần thánh ào ạt trào ra… và có phần giống với người phụ nữ điên đó."
  },
  AvgDialog_121232_Content_3 = {
    Text = "Được rồi, nhóc ở bên kia, giờ hãy chuẩn bị chứng kiến sức mạnh của người Perishite vượt qua những lời chúc phúc!"
  },
  AvgDialog_121369_Content_1 = {
    Text = "Trong đại điện trống rỗng, chỉ có tiếng bước chân của bạn và Murphy vang vọng."
  },
  AvgDialog_121369_Content_10 = {
    Text = "Không kịp hiểu rõ tình huống, những xúc tu lạnh lẽo đã quấn quanh bắp chân bạn, sức mạnh khổng lồ ấn xuống khiến bạn phải quỳ xuống."
  },
  AvgDialog_121369_Content_11 = {
    Text = "Bạn cố gắng chống cự, nhưng độc tố liệt làm thẩm thấu vào thần kinh, khiến bạn không thể tiếp tục."
  },
  AvgDialog_121369_Content_12 = {
    Text = "Murphy, bạn đang làm gì?!"
