  },
  AvgDialog_121369_Content_18 = {
    Text = "Giọng nói của Murphy nghe như vẫn còn tức giận, xúc tu bạch tuộc lộp độp lo âu gõ vào chân bạn. Có vẻ như chỉ có thể dựa vào chính mình."
  },
  AvgDialog_121369_Content_19 = {
    Text = "Bạn mạnh mẽ chống lại sức mạnh của độc tố bị liệt, ngẩng đầu chạm vào gương mặt đỏ bừng của cô ấy."
  },
  AvgDialog_121369_Content_2 = {
    Text = "Từ lúc nãy, bạn vẫn không chịu nói gì."
  },
  AvgDialog_121369_Content_20 = {
    Text = "Murphy, bạn… có phải bị sức mạnh của Sông thiêng ảnh hưởng không?"
