  AvgDialog_121369_Content_21 = {
    Text = "Vô lý! Ta, Mẫu Thần, làm sao có thể bị ảnh hưởng bởi điều ngu ngốc này……"
  },
  AvgDialog_121369_Content_22 = {
    Text = "Xúc tu của vòng tròn xanh bò lên lưng bạn, nơi đi qua đều là một vùng ngứa ngáy."
  },
  AvgDialog_121369_Content_23 = {
