  AvgDialog_121369_Content_27 = {
    Text = "Như một món quà…"
  },
  AvgDialog_121369_Content_28 = {
    Text = "Âm thanh thở của cô ấy lởn vởn bên tai bạn. Sau đó là một nụ hôn nhẹ nhàng, mềm mại, hạ xuống trán bạn."
