  AvgDialog_121741_Content_4 = {
    Text = "Giúp tôi giành lại...số phận của tôi."
  },
  AvgDialog_121742_Content_1 = {
    Text = "Dây xích rung chuyển, quái vật sau màn rèm nhìn quanh con tàu, phát ra tiếng rú tuyệt vọng."
  },
  AvgDialog_121742_Content_10 = {
    Text = "Tạm biệt, \"Ngày hôm qua\" mong manh yếu đuối...!"
  },
  AvgDialog_121742_Content_2 = {
    Text = "Tôi hiểu...tôi đều hiểu...sự lưu luyến của bạn, thứ bạn không nỡ từ bỏ..."
  },
  AvgDialog_121742_Content_3 = {
    Text = "Nhưng tôi đã có quyết định."
  },
  AvgDialog_121742_Content_4 = {
    Text = "Murphy nhìn lại Ngài, một lúc sau, quyết tâm đã định hình, nở một nụ cười dịu dàng với bạn."
  },
  AvgDialog_121742_Content_5 = {
    Text = "Mời các bạn xem... trái tim trong lồng ngực của tôi..."
  },
  AvgDialog_121742_Content_6 = {
    Text = "Đến hôm nay, nó vẫn đang nhảy múa đầy sức sống."
  },
  AvgDialog_121742_Content_7 = {
    Text = "Như trong lễ dẫn đường, Murphy mở ngực mình ra."
  },
  AvgDialog_121742_Content_8 = {
    Text = "Để rời khỏi đây, để gặp lại bạn ở Mythag."
  },
  AvgDialog_121742_Content_9 = {
    Text = "Dòng máu linh tính từ ngực Murphy chảy xuống, những dây bạc nhạt bện vào nhau, cố chấp muốn xé toạc bầu trời trên trần nhà."
  },
  AvgDialog_121743_Content_1 = {
    Text = "Bạn không biết đã chiến đấu bao lâu, chỉ biết rằng đầu bạn bắt đầu chóng mặt, cánh tay nặng trĩu, con quái vật to lớn trắng trẻo nhưng không mệt mỏi vung vẩy cánh tay gãy lại tái sinh."
  },
  AvgDialog_121743_Content_10 = {
    Text = "Lời hứa của William như một bức tường vô hình dựng lên phía sau, niềm tin rèn luyện qua năm tháng khiến sức mạnh gần cạn kiệt trào ra từ sâu trong tuỷ sống."
  },
  AvgDialog_121743_Content_11 = {
    Text = "Đã hẹn rồi, chúng ta cùng nhau quay về."
  },
  AvgDialog_121743_Content_12 = {
    Text = "Nguyện Chìa Khóa Bạc soi sáng con đường phía trước."
  },
  AvgDialog_121743_Content_13 = {
    Text = "Nguyện chìa khóa bạc dẫn đường cho chúng ta."
  },
  AvgDialog_121743_Content_2 = {
    Text = "Mồ hôi trượt từ trán của bạn, làm mờ tầm nhìn của bạn, bạn thậm chí khó khăn để đưa tay lau đi."
  },
  AvgDialog_121743_Content_3 = {
    Text = "Đáng ghét..."
  },
  AvgDialog_121743_Content_4 = {
    Text = "%player%，kiên trì nhé."
  },
  AvgDialog_121743_Content_5 = {
    Text = "Áo choàng đỏ đen bay phấp phới trước mắt, cánh tay cơ học tinh vi giúp bạn chặn lại những xương sọ trắng bệch đang lao vào tấn công."
  },
  AvgDialog_121743_Content_6 = {
    Text = "Các chi dài ngoằn ngoèo lại một lần nữa giận dữ tấn công, nhưng lại bị một lần nữa chặn lại, mảnh vỡ rơi bên cạnh các bạn, kích lên một đám khói bay lên."
  },
  AvgDialog_121743_Content_7 = {Text = "William?"},
  AvgDialog_121743_Content_8 = {
    Text = "Tập trung lại, nhìn vào Ngài.\nGiao phần sau của bạn cho tôi."
  },
  AvgDialog_121743_Content_9 = {
    Text = "Trong thế giới mới...\ntôi sẽ tạm thay bạn làm nhiệm vụ của đối tác.\ncho đến ngày chúng ta cùng quay về Mythag."
  },
  AvgDialog_121744_Content_1 = {
    Text = "Quái vật gầm rú và khóc lớn, bức màn che đổ vỡ, thân thể Ngài nổi lên từ đáy hải vực."
  },
  AvgDialog_121744_Content_10 = {
    Text = "Không biết sử dụng sức mạnh khéo léo, giao phó số phận cho người khác, đó không phải là phong cách của Perishite."
  },
  AvgDialog_121744_Content_11 = {
    Text = "Người khổng lồ vung vũ khí, hướng đỉnh lưỡi kiếm về phía khối thịt lớn đang biến đổi."
  },
  AvgDialog_121744_Content_12 = {
    Text = "Vì vậy, đừng nói nhiều nữa, chuẩn bị chiến đấu đi!"
  },
  AvgDialog_121744_Content_13 = {
    Text = "Người chiến thắng, mới có tư cách sống tiếp."
  },
  AvgDialog_121744_Content_2 = {
    Text = "Tệ quá...! Ngài vẫn đang mở rộng!"
  },
  AvgDialog_121744_Content_3 = {
    Text = "Một tia chớp xé tan bóng đêm, lưỡi kiếm khát máu kèm theo ánh điện tím đen, giáng mạnh vào cánh tay mảnh khảnh trắng trẻo."
  },
  AvgDialog_121744_Content_4 = {
    Text = "...Miryam? Goliath? Tại sao các bạn lại xuất hiện ở đây?"
  },
  AvgDialog_121744_Content_5 = {
    Text = "Thánh mẫu đã quyết định, chúng tôi sẽ ngay lúc này đại diện thần mẫu cắt đứt \"Màn\" trọng đại này."
  },
  AvgDialog_121744_Content_6 = {
    Text = "Miriam……"
  },
  AvgDialog_121744_Content_7 = {
    Text = "Hãy yên tâm, Thần mẫu đại nhân. Dù sau này ngài dự định thế nào, Thủy thủ sẽ luôn là nền tảng vững chắc nhất phía sau ngài."
  },
  AvgDialog_121744_Content_8 = {
    Text = "Đừng lảm nhảm nữa, liệu chúng ta sẽ nhìn hai bạn nhỏ này đối kháng với gã ấy sao?"
  },
  AvgDialog_121744_Content_9 = {
    Text = "Tiếng nói quen thuộc đột ngột xuất hiện, ngắt lời Murphy. Đó là Goliath và Caecus."
  },
  AvgDialog_121745_Content_1 = {
    Text = "Quái vật đứng thẳng ngẩng cao đầu, từ sau màn tối \"nhìn chằm chằm\" tất cả các bạn."
  },
  AvgDialog_121745_Content_10 = {
    Text = "Mời bạn và \"Murphy\" đó... mãi mãi chôn vùi nơi sâu thẳm của biển cả vô tận nhé!"
  },
  AvgDialog_121745_Content_2 = {Text = "……!!!"},
  AvgDialog_121745_Content_3 = {
    Text = "Một liên kết vô hình nào đó thực sự xuyên thấu giữa cô ấy và Ngài, không thể tránh khỏi, khiến cô gái thấy được vết thương, tiếng vọng, và cả sự nghi ngờ của Ngài..."
  },
  AvgDialog_121745_Content_4 = {
    Text = "Như một đứa trẻ bị tổn thương, chất vấn mẹ mình về \"phản bội\"."
  },
  AvgDialog_121745_Content_5 = {
    Text = "Đừng nhìn tôi, đừng chất vấn tôi...tôi đã có quyết định. Đây là lần \"phản bội\" cuối cùng của tôi."
  },
  AvgDialog_121745_Content_6 = {
    Text = "Tôi lúc trước đã cầu nguyện với \"Thiên đường\", một giấc mơ \"ảo ảnh\" tôi khao khát từ khi còn nhỏ."
  },
  AvgDialog_121745_Content_7 = {
    Text = "Tôi nghĩ \"Quyền thế\" có thể đem \"Hạnh phúc\" cho tôi, nhưng thực ra đó chỉ là giấc mơ hư vô..."
  },
  AvgDialog_121745_Content_8 = {
    Text = "Murphy cúi nhìn và lau khô mắt mình. Cô ấy chùi nhẹ, kỹ càng, cho đến khi giọt nước mắt cuối cùng biến mất hoàn toàn, cô ấy ngẩng đầu lên nhìn đám \"bản thân\" khổng lồ."
  },
  AvgDialog_121745_Content_9 = {
    Text = "Tôi không cần thiên đường, không cần giấc mơ lừa dối bản thân. Không cần thêm nữa."
  },
  AvgDialog_121858_Content_1 = {
    Text = "Từ dưới chân Người, hàng ngàn quái vật tràn ra, và các bạn sẽ chém giết từng con một. \n Đạp lên hàng ngàn xác chết, các bạn đã đến dưới chân hình dáng khổng lồ."
  },
  AvgDialog_121858_Content_10 = {
    Text = "Lần này, tôi sẽ không cho phép bất kỳ ai phải hy sinh mạng sống để đổi lấy chiến thắng nữa."
  },
  AvgDialog_121858_Content_11 = {
    Text = "Chuẩn bị chiến đấu đi, màn che sẽ tàn lụi!"
  },
  AvgDialog_121858_Content_2 = {
    Text = "Đây chính là ý chí của tôi, ý chí của \"thiên đường\"..."
  },
  AvgDialog_121858_Content_3 = {
    Text = "\"Đứa trẻ\" từ trước đến nay không thuộc về \"người mẹ\", sau khi sinh ra, nó cũng đã hình thành \"mong muốn\" của riêng mình."
  },
  AvgDialog_121858_Content_4 = {
    Text = "<Red:Giấc mơ...phải...tiếp tục...>"
  },
  AvgDialog_121858_Content_5 = {
    Text = "Ngươi từng nói rằng, chỉ cần giết chết người kiểm soát giấc mơ, chuyển quyền bính cho ngươi..."
  },
  AvgDialog_121858_Content_6 = {
    Text = "Vâng. Bạn đã thực sự sẵn sàng chưa?"
