  AvgDialog_121858_Content_7 = {
    Text = "Không, cô ấy không cần phải hy sinh như vậy."
  },
  AvgDialog_121858_Content_8 = {
    Text = "……%player%!"
  },
  AvgDialog_121858_Content_9 = {
    Text = "\"hạt nhân\" của thâm cảnh, \"tai họa\" hiện ra, quy mô như thế này, tôi đã không nhớ mình đã chiến đấu bao nhiêu lần rồi."
  },
  AvgDialog_121859_Content_1 = {
    Text = "Lực lượng Ngài áp đặt trong bức màn... đang thay đổi..."
  },
  AvgDialog_121859_Content_2 = {
    Text = "Bị cắt bỏ, bị bỏ rơi…… Ngài đang không cam lòng, đang tức giận, đang than vãn……"
  },
  AvgDialog_121859_Content_3 = {
    Text = "Nỗi oán hận của Ngài sẽ đổ xuống thân thể các người…!"
  },
  AvgDialog_121864_Content_1 = {
    Text = "Có bất ngờ không? Bởi vì lời tiên tri đang gọi tôi, ở bên ngoài bức màn……"
  },
  AvgDialog_121865_Content_1 = {
    Text = "Dòng máu của tôi đang rạo rực, vực sâu đang cùng nhau hát mời gọi tôi!"
  },
  AvgDialog_121866_Content_1 = {
    Text = "Ôi thần linh từ xa, người hầu trung thành của ngài sẽ dâng lên ngài một chút sức lực nhỏ bé..."
  },
  AvgDialog_121867_Content_1 = {
    Text = "Người may mắn, hãy để bạn chứng kiến sức mạnh của người Phi-li-tin!"
  },
  AvgDialog_122640_Content_1 = {
    Text = "<Shake:ùm!——>"
  },
  AvgDialog_122640_Content_2 = {
    Text = "Ánh mắt điên cuồng khiến toàn bộ chiều không gian bắt đầu rung động, liên kết giữa Ramona và bạn bị hiện tượng tan biến che phủ, không còn dấu vết."
  },
  AvgDialog_122640_Content_3 = {
    Text = "Bạn hít sâu một hơi, cố gắng dồn nén cơn mất kiểm soát trong lòng do sự điên cuồng gây ra."
  },
  AvgDialog_122640_Content_4 = {
    Text = "Để những điều điên rồ này lại cho chính mình thôi...<Big:Tôi sẽ không để những điều điên rồ của bạn, làm tổn thương bất kỳ ai nữa!>"
  },
  AvgDialog_122641_Content_1 = {
    Text = "……@3!!……"
  },
  AvgDialog_122641_Content_2 = {
    Text = "Áp lực quen thuộc. Ánh mắt quen thuộc. Cơn đau quen thuộc gần như xé nát não bạn."
  },
  AvgDialog_122641_Content_3 = {
    Text = "Hô… Lại gặp nhau rồi, Tohuvabo, thần minh tối cao… Mặc dù anh không thể nghe thấy, nhưng tôi phải cảm ơn anh."
  },
  AvgDialog_122641_Content_4 = {
    Text = "Bạn đã để tôi chết một lần, trong cái chết này, tôi đã lĩnh hội được một chân lý..."
  },
  AvgDialog_122641_Content_5 = {
    Text = "Bạn nắm chặt chìa khóa bạc, nhìn thẳng vào ánh mắt của ý chí Ngài. Thậm chí ngay cả bản thân bạn cũng không nhận ra, khóe môi bạn đang nở một nụ cười."
  },
  AvgDialog_122641_Content_6 = {
    Text = "Bạn đã cho tôi biết rằng, trong giấc mơ vĩ đại của bạn, không có gì là không thể thay đổi, không có gì là không thể đánh bại."
  },
  AvgDialog_122641_Content_7 = {
    Text = "Để gặp lại nhau, chúng tôi đã chờ đợi rất lâu... Dù là bạn, cũng đừng hòng cản đường chúng tôi!"
  },
  AvgDialog_122642_Content_1 = {
    Text = "……@2……@2……@1@3……!!"
  },
  AvgDialog_122642_Content_2 = {
    Text = "Cú sốc mạnh mẽ khiến toàn bộ chiều không gian bắt đầu vỡ vụn. Bạn mở mắt đỏ ngầu, nhìn về phía con ngươi ngày càng gần với thực thể."
  },
  AvgDialog_122642_Content_3 = {
    Text = "Ý thức của bạn cũng đã đến giới hạn, Toghwa… Bây giờ, hãy tiếp tục ngủ ngon nhé!"
  },
  AvgDialog_122642_Content_4 = {
    Text = "Bạn đã khơi dậy tinh thần gần như kiệt quệ của mình, truyền vào chiếc chìa khóa bạc sức mạnh tinh thần cuối cùng."
  },
  AvgDialog_122642_Content_5 = {
    Text = "Bạn nắm chặt ánh sáng bạc như lưỡi dao, đâm về phía thần linh trước mặt—"
  },
  AvgDialog_122643_Content_1 = {
    Text = "<Big:<Shake:Ramona！！！>>"
  },
  AvgDialog_122643_Content_2 = {
    Text = "Hình dáng quen thuộc bị sự chú ý nuốt chửng, những câu chú ngữ cổ xưa, tà ác mờ mờ ẩn ẩn trong ánh mắt này."
  },
  AvgDialog_122643_Content_3 = {
    Text = "Những câu thần chú này đến đây là hết rồi…!"
  },
  AvgDialog_122644_Content_1 = {
    Text = "Thế giới trước mắt bạn sụp đổ và tái tạo, người thân yêu chết đi và sống lại trước mặt bạn. Ánh nhìn hỗn loạn đó mang tất cả sự hỗn độn của vũ trụ vào trong tâm trí bạn."
  },
  AvgDialog_122644_Content_2 = {
    Text = "Hỗn loạn, lộn xộn, bối rối… quyền lực của bạn mang đến vẫn là những thứ này."
  },
  AvgDialog_122644_Content_3 = {
    Text = "Ánh mắt của bạn chưa bao giờ làm tôi mơ hồ, Toghuvabo. Đã từng như vậy, hiện tại cũng vậy."
  },
  AvgDialog_122644_Content_4 = {
    Text = "Ánh sáng bạc lấp lánh. Giữa những ảo ảnh vô tận đó, bạn đã tìm thấy con đường để đối đầu với nó —"
  },
  AvgDialog_122645_Content_1 = {
    Text = "Trong chiều không gian xa xôi, một điểm sáng đang nhấp nháy nhẹ nhàng."
  },
  AvgDialog_122645_Content_2 = {
    Text = "Đó là...\"Trái tim thánh\" của Pollux?"
  },
  AvgDialog_122645_Content_3 = {
    Text = "Họ cũng đã bắt đầu tìm kiếm... hiện tại, họ chắc chắn cũng đang trong tình huống nguy hiểm."
  },
  AvgDialog_122645_Content_4 = {
    Text = "Tôi vẫn nhớ nỗi sợ hãi lần đầu tiên đối mặt với anh, Tohuvabo. Lần này, tôi sẽ không để họ phải chờ đợi lâu!"
  },
  AvgDialog_122646_Content_1 = {
    Text = "Cơn đau nhói mạnh tấn công từng xương tủy, từng tấc thịt của bạn. Bạn chịu đựng sự đau đớn thấu xương này, khó khăn lắm mới nở một nụ cười."
  },
  AvgDialog_122646_Content_2 = {
    Text = "Thần linh ngu ngốc, ngài không biết rằng, trong giấc mơ của ngài, có nhiều nỗi đau vượt xa khỏi thể xác…"
  },
  AvgDialog_122646_Content_3 = {
    Text = "Nỗi đau như vậy, tôi sẽ không để nó xuất hiện nữa!"
  },
  AvgDialog_122694_Content_1 = {
    Text = "Cánh cửa phòng ở đoạn giữa hành lang đã phủ đầy sương giá trắng, thậm chí có xu hướng lan rộng ra ngoài."
  },
  AvgDialog_122694_Content_10 = {
    Text = "Xin cậu đó, người giữ bí mật ơi, ôm tôi đi, một chút thôi, chỉ cần một chút ấm áp là được~ Tiên nữ sẽ nhớ ơn cậu mãi mãi."
  },
  AvgDialog_122694_Content_11 = {
    Text = "Đây là lần đầu tiên bạn thấy tên lừa đảo nhỏ trước mặt lộ ra vẻ mặt như vậy, nhưng sự cảnh giác còn sót lại vẫn khiến bạn thở ra hơi trắng, đứng yên tại chỗ vận động thân thể."
  },
  AvgDialog_122694_Content_12 = {
    Text = "Tôi đã thông báo cho ban quản lý trường rồi, họ sẽ đến giúp ngay thôi, cậu cứ đứng đây đừng đi đâu, đừng làm gì cả."
  },
  AvgDialog_122694_Content_13 = {
    Text = "Nhưng tôi đang khó chịu lắm, sức mạnh của dòng sông đó kéo tôi trở về nơi trắng bệch… lạnh lẽo… đáng sợ đó…"
  },
  AvgDialog_122694_Content_14 = {
    Text = "Không có dấu hiệu báo trước, nước mắt Caraboo rơi thẳng xuống, như thể cô thực sự đang chứng kiến điều gì đó đáng sợ."
  },
  AvgDialog_122694_Content_15 = {
    Text = "Có lẽ tôi không chờ được đến lúc có người giúp nữa rồi, người giữ bí mật ơi, xin lỗi vì trước giờ cứ nói dối cậu…"
  },
  AvgDialog_122694_Content_16 = {
    Text = "Tinh thể đang lan rộng ra từ cô làm tâm, trông cô yếu đuối và dễ vỡ, mắt đỏ hoe nhìn bạn, có vẻ như chực ngã bất cứ lúc nào."
  },
  AvgDialog_122694_Content_17 = {Text = "Caraboo!"},
  AvgDialog_122694_Content_18 = {
    Text = "Ngay trước khoảnh khắc cô ngã xuống, bạn cuối cùng vẫn lao tới đỡ lấy cô, nhưng giây tiếp theo, bạn đã hối hận rồi."
  },
  AvgDialog_122694_Content_19 = {
    Text = "Đôi cánh tay lạnh giá đó linh hoạt như loài sinh vật không xương sống, quấn chặt lấy bạn, hơi thở mang theo tinh thể tuyết bông liền ùa vào hõm cổ và vành tai bạn."
  },
  AvgDialog_122694_Content_2 = {
    Text = "Bạn cắn răng chịu đựng cái lạnh run rẩy đến mức suýt cắn phải lưỡi, rồi đẩy cửa phòng ký túc xá của Caraboo bước vào."
  },
  AvgDialog_122694_Content_20 = {
    Text = "Hí hí~ Ôi trời, đúng như dự đoán, %player% vẫn cứ mềm lòng như vậy."
  },
  AvgDialog_122694_Content_21 = {
    Text = "Phía sau cô ấy, có thứ gì đó mềm mại hơn mà lại lạnh lẽo, khép chặt và âm ấm nhấn chìm bạn vào từng lớp tuyết sâu."
  },
  AvgDialog_122694_Content_22 = {
    Text = "Bạn ú ớ vùng vẫy, trước khi hoàn toàn mất đi ý thức, nghe thấy tiếng cười khúc khích ranh mãnh thuần khiết ấy."
  },
  AvgDialog_122694_Content_23 = {
    Text = "Không sao đâu, tiên nữ ta sẽ rất, rất nhẹ nhàng với chú cừu non quan trọng nhất của ta đấy~"
  },
  AvgDialog_122694_Content_3 = {
    Text = "Caraboo, cậu lại làm trò gì vậy, khì, lạnh quá đi thôi. *run run"
  },
  AvgDialog_122694_Content_4 = {
    Text = "Thế nhưng cái bóng tinh nghịch ấy lại không xuất hiện theo kiểu lấp lánh quen thuộc như mọi khi để khoe trò tinh quái của mình với bạn."
  },
  AvgDialog_122694_Content_5 = {
    Text = "Trên khuôn mặt cô hiếm khi lộ ra một làn ửng hồng, thậm chí có thể gọi là, ừm, đáng thương."
  },
  AvgDialog_122694_Content_6 = {
    Text = "Người giữ bí mật ơi, phải làm sao đây~ Caraboo thấy kỳ lắm, người kỳ lắm, đầu óc cũng kỳ lắm."
  },
  AvgDialog_122694_Content_7 = {
    Text = "Caraboo lạnh lắm, suýt nữa là bị đóng băng chết ở đây rồi."
  },
  AvgDialog_122694_Content_8 = {
    Text = "Caraboo lại nóng lắm, nóng đến mức chân mềm nhũn, không bước nổi một bước."
  },
  AvgDialog_122694_Content_9 = {
    Text = "Cô cắn môi dưới, mắt ngấn lệ, dang rộng hai tay về phía bạn, tạo ra dáng điệu xin được ôm."
  },
  AvgDialog_122696_Content_1 = {
    Text = "Trong đại điện trống rỗng, chỉ có tiếng bước chân của bạn và Murphy vang vọng."
  },
  AvgDialog_122697_Content_1 = {
    Text = "Hôm nay trời tối hơn bình thường rất nhanh, và âm u, rõ ràng sắp mưa."
  },
  AvgDialog_122697_Content_10 = {
    Text = "Mộc Hạ ngẩng đầu lên, trên gương mặt nhuốm màu đỏ bất thường, lộ ra một nụ cười pha trộn giữa sự bối rối và cuồng nhiệt."
  },
  AvgDialog_122697_Content_11 = {
    Text = "Chiến đấu với tôi, ngay lập tức, lập tức!"
  },
  AvgDialog_122697_Content_13 = {
    Text = "Chưa kịp để bạn trả lời, cái rìu của Mộc Hạ đã lao đến, nhẹ nhàng và có chừng mực lướt qua gò má bạn, thổi lên một cơn gió lạnh."
  },
  AvgDialog_122697_Content_14 = {
    Text = "Cơn gió đó tự ý xộc vào cổ áo của bạn mà không cần sự cho phép, rồi tràn vào ngực bạn, khiến cơ thể bạn theo bản năng nổi da gà."
  },
  AvgDialog_122697_Content_15 = {
    Text = "Sao mà nói không hợp là đánh nhau rồi!?"
  },
  AvgDialog_122697_Content_16 = {
    Text = "Sự chất vấn của bạn đã bị cái rìu và chủ nhân của nó phớt lờ."
  },
  AvgDialog_122697_Content_17 = {
    Text = "<Shake:Mouchette?>"
  },
  AvgDialog_122697_Content_18 = {
    Text = "Mộc Hạ!?"
  },
  AvgDialog_122697_Content_19 = {
    Text = "Dưới sự truy hỏi liên tục của bạn, cái rìu cuối cùng cũng ngừng lại. Nó kề sát vai bạn, sâu sắc cắm vào tường."
  },
  AvgDialog_122697_Content_2 = {
    Text = "Để tránh số phận bị ướt, bạn vội vã chạy về ký túc xá, nhưng bị một bóng người chặn lại."
  },
  AvgDialog_122697_Content_20 = {
    Text = "Và chủ nhân của cái rìu, đang đứng trước mắt bạn, mặt đỏ bừng, nắm chặt tay, kéo mạnh cổ áo của bạn."
  },
  AvgDialog_122697_Content_21 = {
    Text = "<Shake:Đừng làm ồn... bây giờ tôi cảm thấy rất khó chịu, chỉ có chiến đấu với bạn mới khiến tôi cảm thấy dễ chịu hơn...>"
  },
  AvgDialog_122697_Content_22 = {
    Text = "Ngón tay nắm chặt cổ áo bạn tiếp tục siết chặt, từ màu da chuyển sang trắng bệch, biểu thị sự cứng đầu và không cam lòng của chủ nhân."
  },
  AvgDialog_122697_Content_23 = {
    Text = "Tôi ghét nhất là người khác áp đặt ý tưởng lên người khác..."
  },
  AvgDialog_122697_Content_24 = {
    Text = "Chỉ là sông thiêng liêng thôi, mà muốn ảnh hưởng đến tôi? <Shake: Không thể… coi thường tôi như vậy được.>"
  },
  AvgDialog_122697_Content_25 = {
    Text = "Mộc Hạ vừa nói vừa thở mạnh, nhằm giảm bớt ảnh hưởng của Thánh Hà lên cô, nhưng bạn có thể cảm nhận được sức nóng đang cuồn cuộn trong cơ thể cô, khao khát đang chảy tràn, và xung đột đang vật lộn."
  },
  AvgDialog_122697_Content_26 = {
    Text = "Nhận thấy cảm xúc của Mộc Hạ, bạn không khỏi thở dài, nắm lấy tay cô, dẫn dắt cô gái nắm chặt lại cán rìu."
  },
  AvgDialog_122697_Content_27 = {
    Text = "<Shake:bạn làm gì vậy?>"
  },
  AvgDialog_122697_Content_28 = {
    Text = "Không phải là muốn chiến đấu sao? Vậy thì chiến đấu đi."
  },
  AvgDialog_122697_Content_29 = {
    Text = "Dù bạn muốn chiến đấu theo cách nào, dù bạn muốn chiến đấu đến khi nào, tôi sẽ luôn đồng hành cùng bạn."
  },
  AvgDialog_122697_Content_3 = {
    Text = "Mộc Hạ? Có chuyện gì vậy?"
  },
  AvgDialog_122697_Content_31 = {
    Text = "Đôi mắt của cô gái đột ngột mở to, nhìn bạn với vẻ bất ngờ."
  },
  AvgDialog_122697_Content_32 = {
    Text = "Lúc này, cơn mưa đã được lên kế hoạch từ lâu cuối cùng cũng rơi xuống, những giọt mưa rơi trên mặt Mộc Hạ, trượt xuống cằm cô, rồi chui vào cổ áo của bạn, chảy xuống ngực bạn."
  },
  AvgDialog_122697_Content_33 = {
    Text = "Sau đó, là nhiều giọt mưa hơn, điên cuồng gõ vào mặt đất, vỗ về má bạn và cô gái, mang đến một chút cảm giác ngứa ngáy."
  },
  AvgDialog_122697_Content_34 = {
    Text = "<Shake:ha ha ha, tôi thích câu trả lời của bạn.>"
  },
  AvgDialog_122697_Content_35 = {
    Text = "Mọi chuyện bắt đầu trở nên có ý nghĩa, phải không?"
  },
  AvgDialog_122697_Content_36 = {
    Text = "Mộc Hạ nắm chặt cán rìu, rút lưỡi rìu ra khỏi tường, nhưng cô ấy không vung rìu nữa, mà nhìn thẳng vào bạn."
  },
  AvgDialog_122697_Content_37 = {
    Text = "Thông thường, tôi sẽ không đánh nhau tay không với người khác, nhưng đôi khi cũng phải thử những điều mới mẻ, đúng không?"
  },
  AvgDialog_122697_Content_38 = {
    Text = "Cuộc đời dài như vậy, một số điều thú vị, cần phải tự mình từ từ trải nghiệm."
  },
  AvgDialog_122697_Content_39 = {
    Text = "Mộc Hạ nói, từ từ đi về phía bạn. Còn cái rìu đó, cũng lặng lẽ dựa vào tường, chịu đựng sự rửa sạch ẩm ướt của thế giới."
  },
  AvgDialog_122697_Content_4 = {
    Text = "Mộc Hạ cúi đầu, không trả lời, bạn chỉ có thể từ những ngón tay nhợt nhạt vì nắm chặt cái rìu của cô ấy mà nhận ra tâm trạng không yên tĩnh của cô gái."
  },
  AvgDialog_122697_Content_5 = {
    Text = "<Shake:Mouchette!?>"
  },
  AvgDialog_122697_Content_6 = {
    Text = "Cuối cùng, cô gái đã lên tiếng, nhưng giọng nói lại mang theo một chút do dự và không chắc chắn."
  },
  AvgDialog_122697_Content_7 = {
    Text = "%player%, tôi, tôi cần sự giúp đỡ của bạn……"
  },
  AvgDialog_122697_Content_8 = {
    Text = "Giúp đỡ? Không vấn đề gì. Bạn cần gì?"
  },
  AvgDialog_122697_Content_9 = {
    Text = "<Shake:Tôi cần bạn……>"
  },
  AvgDialog_122700_Content_1 = {
    Text = "Chào mừng đến nhà hát của tôi. Ngài đến rất đúng giờ, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_122700_Content_10 = {
    Text = "Sinh sôi... Tái sinh... Chẳng lẽ cô cũng?!"
  },
  AvgDialog_122700_Content_11 = {
    Text = "Ơ, tôi chợt nhớ ra bài tập giáo sư Dole giao vẫn chưa làm xong... Hay là tôi cứ về trước..."
  },
  AvgDialog_122700_Content_12 = {
    Text = "Bạn quay người định rời đi, nhưng bước chân lại vô thức dẫn bạn tiếp tục tiến về phía trước, đến trước mặt Arachne."
  },
  AvgDialog_122700_Content_13 = {
    Text = "Là ảnh hưởng của Thánh Hà... cũng là sự dẫn dắt của vận mệnh. Đêm nay, là đêm chỉ thuộc về hai chúng ta."
  },
  AvgDialog_122700_Content_14 = {
    Text = "Một vở kịch định sẵn phải được diễn, cuối cùng cũng đợi được nhân vật chính mà số phận đã định."
  },
  AvgDialog_122700_Content_15 = {
    Text = "Hơi thở của Arachne đã áp sát bên tai bạn, ấm nóng và u huyền."
  },
  AvgDialog_122700_Content_16 = {
    Text = "Nụ cười của cô vẫn dịu dàng bình thản, nhưng trong đôi mắt sâu thẳm không đáy ấy, lấp lánh một ngọn lửa mà bạn chưa từng thấy, tựa như có thể nuốt chửng tất cả."
  },
  AvgDialog_122700_Content_17 = {
    Text = "Không, không được... Arachne... Tôi..."
  },
  AvgDialog_122700_Content_18 = {
    Text = "Không cần trốn tránh, %player%. Lưới vận mệnh đã dệt nên mọi khả năng, nó sẽ dẫn dắt ngài cùng tôi hoàn thành buổi diễn đêm nay."
  },
  AvgDialog_122700_Content_19 = {
    Text = "Mạng nhện vô hình trói buộc ngươi, cướp đi toàn bộ sức lực, nuốt chửng mọi ý chí phản kháng của ngươi."
  },
  AvgDialog_122700_Content_2 = {
    Text = "Bạn đẩy cánh cửa nặng nề của nhà hát, ánh trăng xuyên qua cửa sổ cao chiếu xiên xuống, sương đêm se lạnh cùng giọng nói dịu dàng của Arachne trong nhà hát khiến bạn bừng tỉnh."
  },
  AvgDialog_122700_Content_20 = {
    Text = "Sợi tơ vận mệnh đan dệt. Ngươi nhìn gương mặt dịu dàng cận kề trước mắt, tim đập dữ dội, hơi thở bỗng trở nên gấp gáp."
  },
  AvgDialog_122700_Content_21 = {
    Text = "Trong vận mệnh của ngươi, ngươi chưa bao giờ muốn trốn chạy. Ngươi khao khát, khao khát đến nơi này, khao khát hoàn thành vở diễn không có khán giả này."
  },
  AvgDialog_122700_Content_22 = {
    Text = "Ngươi……đã sửa đổi vận mệnh của ta sao?!"
  },
  AvgDialog_122700_Content_23 = {
    Text = "Tôi chưa bao giờ sửa đổi chúng, Thủ Mật Nhân{Male=先生,Female=小姐}. Tôi chỉ để vận mệnh của Người bước vào quỹ đạo mà nó lẽ ra phải đi."
  },
  AvgDialog_122700_Content_24 = {
    Text = "Arachne……ngươi……ngươi hoàn toàn có thể thay đổi hướng đi của vận mệnh, tránh khỏi ảnh hưởng của Thánh Hà……tại sao không làm vậy?"
  },
  AvgDialog_122700_Content_25 = {
    Text = "Tại sao phải làm vậy?"
  },
  AvgDialog_122700_Content_26 = {
    Text = "Đối với một kép hát đã thông thuộc kịch bản từ lâu, bất ngờ, chính là món quà quý giá nhất mà vận mệnh ban tặng……"
  },
  AvgDialog_122700_Content_27 = {
    Text = "Lời thì thầm dịu dàng của Arachne lay động bên tai ngươi. Nàng không còn bình thản và xa cách nữa, hơi thở nàng rung nhẹ, nụ cười nàng cận kề trong gang tấc."
  },
  AvgDialog_122700_Content_28 = {
    Text = "Vừa hay, tôi không hề kháng cự cái kết cục này……một kết cục mà không ai bị tổn thương."
  },
  AvgDialog_122700_Content_29 = {
    Text = "Mạng nhện kết bằng tơ lạnh lẽo, dẻo dai, mang theo độ dính khiến người ta nghẹt thở, siết chặt dần, ấn sâu vào vải áo, áp sát lên làn da ngươi."
  },
  AvgDialog_122700_Content_3 = {
    Text = "Khoan đã! Lẽ ra tôi đang ngủ ở ký túc xá mới đúng, sao lại đến đây được... Là cô điều khiển sao?"
  },
  AvgDialog_122700_Content_30 = {
    Text = "Khoảnh khắc tiếp theo, kìm chelicera kẹp chặt thân thể ngươi, xúc chi lạnh giá luồn vào khoang miệng ngươi, phong ấn lời kháng cự chưa kịp thốt ra."
  },
  AvgDialog_122700_Content_31 = {
    Text = "Sợi tơ bắt đầu kéo tứ chi ngươi — nhẹ nhàng, nhưng không thể cưỡng lại."
  },
  AvgDialog_122700_Content_32 = {
    Text = "Không cần lo lắng, Thủ Mật Nhân, cũng không cần kháng cự món quà của vận mệnh."
  },
  AvgDialog_122700_Content_33 = {
    Text = "Bởi vì……đây cũng chính là điều Người muốn làm, phải không?"
  },
  AvgDialog_122700_Content_34 = {
    Text = "……Đúng vậy, Arachne……đây là……điều ta muốn……"
  },
  AvgDialog_122700_Content_35 = {
    Text = "Tất nhiên, ngươi chưa bao giờ là con rối bị vận mệnh giật dây. Ngươi là Thủ Mật Nhân của Mysager, là người nắm giữ vận mệnh của chính mình."
  },
  AvgDialog_122700_Content_36 = {
    Text = "Tất cả những điều này chính là điều ngươi mong muốn. Là vận mệnh đang thuận theo ý chí của ngươi, là thân thể ngươi đang đáp lại tiếng gọi của ngươi……"
  },
  AvgDialog_122700_Content_37 = {
    Text = "Sợi tơ rung nhẹ, như vận mệnh gảy dây đàn, ngươi vuốt ve đốt chân nhện đung đưa nhẹ trong không trung, vuốt ve đôi tay mãi xoay guồng kéo sợi, vuốt ve gương mặt dịu dàng ấy."
  },
  AvgDialog_122700_Content_38 = {
    Text = "Gương mặt quen thuộc ấy, mang nét bi mẫn vĩnh hằng và sự tĩnh lặng như định mệnh, khẽ ửng lên sắc hồng mê đắm."
  },
  AvgDialog_122700_Content_39 = {
    Text = "Hãy cùng nhau đón nhận sự giáng lâm của định mệnh, Người Giữ Bí Mật{Male=先生,Female=小姐}."
  },
  AvgDialog_122700_Content_4 = {
