  },
  AvgDialog_123118_Content_57 = {
    Text = "Bóng lưng của Mộc Hạ lao nhanh về phía trước trong làn sương mù, bạn và Salvador nhìn nhau một cái, rồi đuổi theo."
  },
  AvgDialog_123118_Content_6 = {
    Text = "<Shake:Họ… là… gì?>"
  },
  AvgDialog_123118_Content_7 = {
    Text = "Mộc Hạ không thể không bịt tai, nhưng thật tiếc là điều đó vô ích."
  },
  AvgDialog_123118_Content_8 = {
    Text = "Nỗi đau và tuyệt vọng từ từ thẩm thấu vào thịt da, xương cốt của người nghe, thẳng đến linh hồn."
  },
  AvgDialog_123118_Content_9 = {
    Text = "Tôi có thể phân biệt rằng, linh hồn của họ... là người đã bị hiến tế trong nghi lễ lần trước."
  },
  AvgDialog_123119_Content_1 = {
    Text = "Giữa các chiều"
  },
  AvgDialog_123119_Content_10 = {
    Text = "Mộc Hạ nhún vai, giơ tay chỉ vào cánh cửa chiều không gian đang liên tục phun ra sương mù dày đặc, xâm thực thế giới này."
  },
  AvgDialog_123119_Content_100 = {
    Text = "Không, %player%, đợi một chút……"
  },
  AvgDialog_123119_Content_101 = {
    Text = "Mouchette muốn ngăn cản sự cứu trợ của bạn. Sau khi hiểu về trải nghiệm của \"bạn\", cô ấy đầy nghi hoặc và câu hỏi."
  },
  AvgDialog_123119_Content_102 = {
    Text = "Nhưng không còn thời gian nữa. Một cảm giác kéo từ linh hồn đang lôi kéo cô ấy, kiên quyết dẫn dắt cô rời khỏi thế giới kỳ lạ đầy những đốm sáng này."
  },
  AvgDialog_123119_Content_103 = {
    Text = "Và đốm sáng đã cho cô ấy sự khai sáng đó ở đó, không xa không gần, tỏa ra thiện ý dịu dàng và ấm áp, đang nói lời tạm biệt cuối cùng với cô."
  },
  AvgDialog_123119_Content_104 = {
    Text = "Hiển thị thông tin @4 cho @3 \"tôi\", bạn sẽ có thể @2 về nhà @1."
  },
  AvgDialog_123119_Content_105 = {
    Text = "@2, Tạm biệt, Mouchette, @2... phiên bản khác của \"tôi\"."
  },
  AvgDialog_123119_Content_106 = {
    Text = "Rất nhanh, tiếng vo ve vô hình bị bóp méo, tan biến, cuối cùng hoàn toàn biến mất, cùng với nó là thị giác, thính giác và các giác quan khác của Mộc Hạ."
  },
  AvgDialog_123119_Content_107 = {
    Text = "Khi Mộc Hạ một lần nữa phục hồi thị giác và thính giác, trở lại hiện thực, cô lại nhìn thấy hình bóng quen thuộc đó, người mà cô không thể hiểu được."
  },
  AvgDialog_123119_Content_108 = {
    Text = "Mùa hè, hãy rời khỏi đây, tôi và Salvador sẽ lo liệu sau."
  },
  AvgDialog_123119_Content_109 = {
    Text = "Sự xâm thực của \"cửa\" ngày càng sâu, tôi và sứ giả nhợt nhạt buộc phải chuẩn bị cho những điều tồi tệ nhất..."
  },
  AvgDialog_123119_Content_11 = {
    Text = "Vì vậy, tôi phải đi, chỉ có tôi mới có thể đi."
  },
  AvgDialog_123119_Content_111 = {
    Text = "Mạc Hạ? Cậu đang ngẩn người gì vậy? Mau rời khỏi đây."
  },
  AvgDialog_123119_Content_112 = {
    Text = "Nhìn vào bạn, sự tức giận, phẫn nộ, thương hại và nhiều cảm xúc khác đan xen trong lòng Mộc Hạ, khiến cô ấy không thể nói nên lời."
  },
  AvgDialog_123119_Content_113 = {
    Text = "Cuối cùng, cô ấy tức giận thở phào, nắm chặt tay, miễn cưỡng mở miệng:"
  },
  AvgDialog_123119_Content_114 = {
    Text = "Từ lần đầu gặp mặt, tôi đã nên biết, cậu chính là loại người nhiệt tình và thích can thiệp vào chuyện của người khác như \"Nhân Vật Chính\", là loại người mà tôi mãi mãi không thể hiểu nổi."
  },
  AvgDialog_123119_Content_115 = {
    Text = "Dù có qua 100 năm nữa, tôi cũng không thể hiểu được cách suy nghĩ của bạn. Vì vậy, tôi đã từ bỏ."
  },
  AvgDialog_123119_Content_116 = {Text = "Cái gì?"},
  AvgDialog_123119_Content_117 = {
    Text = "Tôi biết giá trị rung mà bạn nói, đây là cái khác @4@3……"
  },
  AvgDialog_123119_Content_118 = {
    Text = "Cảm giác đau nhói quen thuộc ập đến, khiến những lời nói của Mùa Hạ bị bóp méo và biến dạng. Sau khi cố gắng vài lần mà không thể nói ra sự thật về ánh sáng đó, Mùa Hạ đã từ bỏ."
  },
  AvgDialog_123119_Content_119 = {
    Text = "Cô gái thay lời bằng hành động, nắm chặt tay bạn, vẻ mặt kiên định vô cùng."
  },
  AvgDialog_123119_Content_12 = {
    Text = "Theo cách nói của các bạn, đó chính là... ồ, sự khôn ngoan trong việc sinh tồn dưới thế giới tàn khốc này."
  },
  AvgDialog_123119_Content_120 = {
    Text = "Tôi sẽ cùng bạn giải quyết rắc rối lớn này."
  },
  AvgDialog_123119_Content_121 = {
    Text = "Tôi, Mộc Hạ, tiền phong được chú ý của đoàn điều tra, sẽ không kết thúc trận chiến này với danh phận \"kẻ trốn lính\"."
  },
  AvgDialog_123119_Content_13 = {
    Text = "Nghe những gì Mùa Hè nói, bạn và Salvador không khỏi rơi vào im lặng, rồi cùng lúc lên tiếng —"
  },
  AvgDialog_123119_Content_14 = {
    Text = "Tôi không đồng ý, con à. Người phải hy sinh nên là tôi."
  },
  AvgDialog_123119_Content_15 = {
    Text = "Tôi đồng ý. Tôi hứa sẽ cứu bạn trở về, hoặc nhân cơ hội này đưa bạn về nhà, bất kể phải trả giá nào."
  },
  AvgDialog_123119_Content_16 = {
    Text = "Vào cùng một thời điểm phát biểu quan điểm hoàn toàn trái ngược, bạn và Salvador không khỏi nhìn nhau."
  },
  AvgDialog_123119_Content_17 = {
    Text = "%player%, tại sao bạn……"
  },
  AvgDialog_123119_Content_18 = {
    Text = "Vậy thì quyết định như thế, việc về nhà cứ để tôi lo, %player%."
  },
  AvgDialog_123119_Content_19 = {
    Text = "Mouchette cắt ngang cuộc trò chuyện của bạn và Salvador, trước khi các bạn kịp phản ứng, cô ấy đã tiến về phía cánh cửa không biết và bí ẩn."
  },
  AvgDialog_123119_Content_2 = {
    Text = "Mộc Hạ, cô đang nói, cô muốn bước vào cánh cửa chưa biết đó…?"
  },
  AvgDialog_123119_Content_20 = {
    Text = "Bạn nắm chặt chìa khóa bạc bằng một tay, tay kia kéo mạnh Salvador, chăm chú nhìn bóng dáng của Mộc Hạ, không dám chớp mắt."
  },
  AvgDialog_123119_Content_21 = {
    Text = "Salvador, nghe tôi nói, có lẽ... Mouchette là khác biệt."
  },
  AvgDialog_123119_Content_22 = {
    Text = "Đây là cánh cửa kết nối đến một chiều không gian khác, và Mộc Hạ, chính là từ chiều không gian đó, thậm chí còn được triệu hồi qua cùng một nghi thức."
  },
  AvgDialog_123119_Content_23 = {
    Text = "Nhưng… nếu…"
  },
  AvgDialog_123119_Content_24 = {
    Text = "Nếu có tình huống không đúng, tôi sẽ kích hoạt chìa khóa bạc, chuyển kết nối về phía mình."
  },
  AvgDialog_123119_Content_25 = {
    Text = "Salvador nhìn vào đôi mắt cố gắng giữ bình tĩnh của bạn, lại thấy bạn nắm chặt chìa khóa bạc, cuối cùng thở dài."
  },
  AvgDialog_123119_Content_26 = {
    Text = "Nếu đến lúc đó, xin hãy để tôi chia sẻ gánh nặng."
  },
  AvgDialog_123119_Content_27 = {
    Text = "Sứ giả nhợt nhạt, tôi tuyệt đối sẽ không để bạn gục ngã trước tôi."
  },
  AvgDialog_123119_Content_28 = {
    Text = "Phản ứng của bạn là một nụ cười hiểu biết."
  },
  AvgDialog_123119_Content_29 = {
    Text = "Trong khi đó, Mộ Hạ đang giơ tay lên, cố gắng chạm vào cánh cửa vô hình đó."
  },
  AvgDialog_123119_Content_3 = {
    Text = "Không chỉ bạn, mà ngay cả Salvador cũng ngẩn ra."
  },
  AvgDialog_123119_Content_30 = {
    Text = "<Shake:đây là……>"
  },
  AvgDialog_123119_Content_31 = {
    Text = "Vào khoảnh khắc Mộ Hạ chạm vào cánh cửa vô hình, nó lập tức phát ra ánh sáng mạnh mẽ như trước."
  },
  AvgDialog_123119_Content_32 = {
    Text = "Trong khi đó, bạn cũng đã kích hoạt chìa khóa bạc."
  },
  AvgDialog_123119_Content_33 = {
    Text = "Ánh sáng tỏa ra từ chìa khóa bạc hòa quyện với ánh sáng của cánh cửa vô hình, bầu trời đầy ánh bạc và máu như được dẫn dắt bởi một điều vô hình, sôi sục và dâng trào."
  },
  AvgDialog_123119_Content_34 = {
    Text = "Dưới sự kết hợp của hai bên, âm thanh vo ve chưa biết có khả năng xâm nhập linh hồn vang lên, hòa quyện với màn sương dày đặc vô tận, tấn công mọi thứ xung quanh, khiến tất cả mọi người có mặt rơi vào một trạng thái mê hoặc giữa linh hồn và thể xác..."
  },
  AvgDialog_123119_Content_35 = {
    Text = "Thế giới@2 mờ mịt, như@2@1 như sương mù dày đặc, @3, có điều gì@2 đang thai nghén trong hư vô@3 này."
  },
  AvgDialog_123119_Content_36 = {
    Text = "@1Chỉ là một giấc mơ vĩ đại của @4, điều bất ngờ ở @2 này, nó đang vật lộn, bò @2, tiến hóa, biến đổi @4 chủng tộc."
  },
  AvgDialog_123119_Content_37 = {
    Text = "Âm thanh tiếng sáo hỗn loạn, méo mó vang lên trong bóng tối, tàn phá ý chí của Mo Hạ, rõ ràng là âm thanh vui vẻ, nhưng cô lại mơ hồ nhìn thấy ý nghĩa đáng sợ bên trong."
  },
  AvgDialog_123119_Content_38 = {
    Text = "Con người, đây là cách tự xưng của @3. So với vũ trụ vô tận @1, @2 thật nhỏ bé, thoáng chốc đã biến mất."
  },
  AvgDialog_123119_Content_39 = {
    Text = "@3 không phải @3 không để lại, dòng dõi chảy @1 máu và bạc, @4 @2 dấu vết @1 chứng cứ."
  },
  AvgDialog_123119_Content_4 = {
    Text = "Đúng vậy. Tôi vào trong, giúp bạn điều tra cái sóng rung đó."
  },
  AvgDialog_123119_Content_40 = {
    Text = "Tiếng sáo hỗn loạn, méo mó càng lúc càng sắc bén và đáng sợ, như thể tra tấn linh hồn của Mocha. Cô không thể chịu đựng thêm nữa, đột ngột mở mắt ra."
  },
  AvgDialog_123119_Content_41 = {
    Text = "Sau khi mở mắt, Mộc Hạ không nghe thấy tiếng sáo, cũng không nhìn thấy nhạc công nào. Xung quanh thật kỳ lạ, chỉ có những mảng ánh sáng lớn bao quanh cô, giữ khoảng cách không gần không xa."
  },
  AvgDialog_123119_Content_42 = {
    Text = "Rất vui được gặp bạn, Mộc Hạ, \"tôi\" của tôi, người bạn."
  },
  AvgDialog_123119_Content_43 = {
    Text = "Ánh sáng phát ra tiếng vo ve, điều kỳ quái là, cô ấy hoàn toàn có thể hiểu được. \n Hoặc nói cách khác, cô ấy lúc này cũng chính là ánh sáng."
  },
  AvgDialog_123119_Content_44 = {
    Text = "Tôi đã hy sinh rồi sao? Hóa ra hy sinh là cảm giác như thế này à……"
  },
  AvgDialog_123119_Content_45 = {
    Text = "Không, bạn vẫn còn sống. Bạn chỉ bị tôi đưa đến đây. Trên người bạn có hơi thở của \"tôi\"."
  },
  AvgDialog_123119_Content_46 = {
    Text = "Nếu tôi không làm như vậy, bạn sẽ phải chịu đựng @4 vì chiều không gian thất bại, vì bạn đã bị @3."
  },
  AvgDialog_123119_Content_47 = {
    Text = "Mùa Hè không nghe thấy lời cuối cùng của ánh sáng, vì ngay khi âm tiết hỗn loạn vang lên, đầu cô đã đau dữ dội, như thể sắp nứt ra."
  },
  AvgDialog_123119_Content_48 = {
    Text = "<Shake:Dừng lại! Dừng lại! Nói cái gì mà tôi nghe được... Nếu cứ tiếp tục như thế này, đầu tôi sẽ nổ tung.>"
  },
  AvgDialog_123119_Content_49 = {
    Text = "Cô ấy dường như nghe thấy tiếng thở dài của ánh sáng, hoặc có thể không, vì vô số thông tin kỳ lạ tràn vào đầu óc của Mạch Hạ, thu hút toàn bộ sự chú ý của cô."
  },
  AvgDialog_123119_Content_5 = {
    Text = "Con à, con không hiểu được sự nguy hiểm bên trong, chấn thương từ chiều không gian tinh thần cũng sẽ ảnh hưởng đến thế giới thực, con sẽ..."
  },
  AvgDialog_123119_Content_50 = {
    Text = "Cái này là gì?"
  },
  AvgDialog_123119_Content_51 = {
    Text = "Những gì các bạn cần lúc này. Hãy trình bày cho \"tôi\",{Male=anh ấy,Female=cô ấy} sẽ hiểu."
  },
  AvgDialog_123119_Content_52 = {
    Text = "Cái gì tôi, của bạn, không hiểu——"
  },
  AvgDialog_123119_Content_53 = {
    Text = "Đợi một chút, bạn là……%player%?"
  },
  AvgDialog_123119_Content_54 = {
    Text = "Điều này không thể, tôi vừa thấy bạn tràn đầy sức sống, trông bạn hoàn toàn có thể sống thêm 100 năm nữa."
  },
  AvgDialog_123119_Content_55 = {
    Text = "Ánh sáng nhấp nháy, phát ra một tiếng cười nhẹ, Mộc Hạ không biết liệu điều này có thể gọi là \"cười\" hay không, vì nó không có niềm vui. Nói chính xác hơn, không có bất kỳ cảm xúc nào."
  },
  AvgDialog_123119_Content_56 = {
    Text = "Bạn có thể hiểu rằng đó là \"tôi\" của một chiều không gian khác, và tôi, bản thân thật sự của tôi ——"
  },
  AvgDialog_123119_Content_57 = {
    Text = "Cùng với lời nói của những đốm sáng, vô số thông tin lại tràn vào đầu óc của Mộc Hạ. Những thông tin này liên tục phân chia, kết hợp, hình thành nên những hình ảnh không ổn định."
  },
  AvgDialog_123119_Content_58 = {
    Text = "Ban đầu, những hình ảnh này rất trừu tượng và loang lổ, mờ nhạt không rõ, nhưng rất nhanh—"
  },
  AvgDialog_123119_Content_59 = {
    Text = "Những ánh sáng kỳ quái đó đã tụ lại thành một hình dáng, một hình dáng mà cô ấy quen thuộc."
  },
  AvgDialog_123119_Content_6 = {
    Text = "Chỉ có tôi là phù hợp ở đây. Mặc dù tôi có đầu óc đơn giản hơn một chút, nhưng không ngốc."
  },
  AvgDialog_123119_Content_60 = {
    Text = "Hình bóng quen thuộc đó tỉnh dậy trong một vụ nổ, ngơ ngác nhìn thế giới này."
  },
  AvgDialog_123119_Content_61 = {
    Text = "Nhiều năm sau, mọi người sẽ gọi vụ nổ này là \"Vụ nổ Akutê\"."
  },
  AvgDialog_123119_Content_62 = {
    Text = "Sau đó, {Male=anh ấy,Female=cô ấy} đã vào Misaque, nhận được chìa khóa bạc, trở thành \"Người Giữ Gìn\", bắt đầu cùng các đồng đội được gọi là \"thân thể được đánh thức\" thực hiện nhiệm vụ, điều tra thế giới kỳ quái và đáng sợ này."
  },
  AvgDialog_123119_Content_63 = {
    Text = "Giống như cô ấy và các điều tra viên, nhóm điều tra sương mù vậy."
  },
  AvgDialog_123119_Content_65 = {
    Text = "Nhớ về những người quen thuộc và quá khứ, Mạch Hạ thở dài hoài niệm. Còn về cuộc đời của %player%, vẫn đang tiếp diễn——"
  },
  AvgDialog_123119_Content_66 = {
    Text = "Cô nhìn thấy %player% đi qua thị trấn phủ đầy băng tuyết, trong viện dưỡng lão đầy bí mật, đối diện với chó săn xuyên không, chứng kiến sự vĩnh cửu của tình thân."
  },
  AvgDialog_123119_Content_67 = {
    Text = "Cũng đã theo chân %player% tham quan Tây Đài đầy hoa và thơ, lắng nghe tiếng thở dài của lửa, đau buồn trước sự tàn lụi của hoa hồng."
  },
  AvgDialog_123119_Content_68 = {
    Text = "Còn có con tàu ma trôi nổi trên biển. Niềm tin, thần thánh, hy sinh, cô ấy cùng %player% nhận thức được sự méo mó, tàn nhẫn và điên cuồng của thế giới này."
  },
  AvgDialog_123119_Content_69 = {
    Text = "Nhưng không có nơi nào nguy hiểm đến mức có thể đánh bại được %player% và đồng đội của {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_123119_Content_7 = {
    Text = "Mùa hè lên tiếng cắt ngang lời của Salvador, vẻ mặt nghiêm túc nhìn các bạn."
  },
  AvgDialog_123119_Content_70 = {
    Text = "Giống như ở thế giới đó, thảm họa sương mù, xác chết, cổ vật cũng không thể đánh bại cô và các điều tra viên, cũng không thể đánh bại đoàn điều tra sương mù."
  },
  AvgDialog_123119_Content_71 = {
    Text = "Thế này mới đúng!"
  },
  AvgDialog_123119_Content_72 = {
    Text = "Cũng không biết những cậu bé trong sương mù bây giờ thế nào rồi?"
  },
  AvgDialog_123119_Content_73 = {
    Text = "Ôi, thật sự tôi rất muốn uống một tách trà hạt phỉ Kava nóng hổi!"
  },
  AvgDialog_123119_Content_74 = {
    Text = "Mouchette cười. \n Cô ấy nghĩ rằng %player% sẽ mãi chiến đấu với những thân thể được đánh thức——"
  },
  AvgDialog_123119_Content_75 = {
    Text = "Đó là điều hiển nhiên, vì cô ấy chưa bao giờ nghĩ đến việc rời khỏi nhóm điều tra sương mù, những thân thể được đánh thức đó, đương nhiên cũng sẽ không muốn rời bỏ Người Giữ Gìn."
  },
  AvgDialog_123119_Content_76 = {
    Text = "Họ sẽ chiến đấu, chiến đấu, cho đến khi giải quyết những rắc rối của thế giới, hoặc bị thế giới giải quyết. \n Giống như trong tất cả các câu chuyện đã diễn ra."
  },
  AvgDialog_123119_Content_77 = {
    Text = "Nhưng thế giới này, còn tàn nhẫn hơn nhiều so với những gì Mộc Hạ tưởng tượng, còn tàn nhẫn hơn cả thế giới mà Mộc Hạ đang sống."
  },
  AvgDialog_123119_Content_78 = {
    Text = "<Shake:Sao lại như vậy!!>"
  },
  AvgDialog_123119_Content_79 = {
    Text = "Cho nên bạn…!?"
  },
  AvgDialog_123119_Content_8 = {
    Text = "Salvador, khả năng của bạn là nền tảng để chúng ta giữ an toàn trong sương mù dày đặc, còn %player%, rõ ràng, bạn và chìa khóa bạc của bạn cũng rất quan trọng."
  },
  AvgDialog_123119_Content_80 = {
    Text = "Cậu nhóc, tôi không nên mong đợi cậu sẽ từ bỏ việc cứu vớt thế giới nhàm chán này."
  },
  AvgDialog_123119_Content_81 = {
    Text = "Để cứu người khác, hy sinh như vậy…… chuyện như vậy……"
  },
  AvgDialog_123119_Content_82 = {
    Text = "Mùa hè không thể nói tiếp được nữa, vì dù là tức giận hay phẫn nộ, cũng đã không còn ích gì."
  },
  AvgDialog_123119_Content_83 = {
    Text = "%player% chắc chắn là bạn của cô ấy, Mộc Hạ, nhưng Mộc Hạ chỉ là một người qua đường trong thế giới này."
  },
  AvgDialog_123119_Content_84 = {
