  AvgDialog_123120_Content_102 = {
    Text = "Thảm họa sương mù, là một thảm họa có thể ảnh hưởng đến cả một thế giới."
  },
  AvgDialog_123120_Content_103 = {
    Text = "Phải bằng mọi giá, chấm dứt nghi thức này……<Shake:Salvador!>"
  },
  AvgDialog_123120_Content_104 = {
    Text = "Tôi ở đây. Tôi nhất định sẽ đảm bảo an toàn cho các bạn... cũng sẽ giúp những kẻ lạc lối này, đạt được sự cứu rỗi thực sự..."
  },
  AvgDialog_123120_Content_105 = {
    Text = "Sau đó, ánh sáng ấm áp dịu dàng đột ngột xuất hiện trên người Salvador, lan tỏa đến bên bạn và Mộc Hạ, ngăn chặn tổn thương từ thảm họa sương mù."
  },
  AvgDialog_123120_Content_106 = {
    Text = "Mộc Hạ, để đóng lại khe nứt không gian này, tiếp theo tôi cần đo lường và xác định dao động của chiều tâm linh, chiến đấu thì nhờ bạn nhé."
  },
  AvgDialog_123120_Content_107 = {
    Text = "Chiến đấu? Không vấn đề gì. Có tôi ở đây, chắc chắn sẽ không để bạn rụng một sợi lông nào!"
  },
  AvgDialog_123120_Content_108 = {
    Text = "Đã nén lại lâu như vậy, cuối cùng cũng có thể phát tiết một chút——"
  },
  AvgDialog_123120_Content_109 = {
    Text = "Mọi người từ trẻ đến già đều thích xem!\n<Big:Lấp lánh☆Vòi rồng——!!>"
  },
  AvgDialog_123120_Content_11 = {
    Text = "Salvador im lặng hít sâu một hơi, rồi thở ra một cách nặng nề."
  },
  AvgDialog_123120_Content_111 = {
    Text = "Một cái rìu bay ra, chém tan một chuỗi hình dáng trong sương mù, cũng tạo ra một con đường an toàn tạm thời cho bạn tiến gần đến cánh cửa bí ẩn đang không ngừng nuốt chửng sương mù dày đặc."
  },
  AvgDialog_123120_Content_112 = {
    Text = "Và bạn không ngừng thao tác các thiết bị đo lường, cố gắng bắt giữ các sóng rung động ở các chiều không gian khác nhau."
  },
  AvgDialog_123120_Content_113 = {
    Text = "Một phút, lặng lẽ trôi qua. \n Hai phút, lặng lẽ trôi qua."
  },
  AvgDialog_123120_Content_114 = {
    Text = "Rồi là ba phút, năm phút, mười phút……"
  },
  AvgDialog_123120_Content_115 = {
    Text = "Mồ hôi từ trán bạn rơi xuống, bạn chưa bao giờ cảm thấy thời gian dài như vậy."
  },
  AvgDialog_123120_Content_116 = {
    Text = "Còn bao lâu nữa? Tôi luôn cảm thấy những con quái vật này dường như đã mạnh lên, phải chém vài nhát mới có thể đánh tan…"
  },
  AvgDialog_123120_Content_117 = {
    Text = "Đó là biểu hiện của một chiều không gian khác đang cố gắng xâm nhập và tiêu thụ thế giới của chúng ta, đúng không, sứ giả nhợt nhạt?"
  },
  AvgDialog_123120_Content_118 = {
    Text = "Một giọt mồ hôi nữa rơi từ trán bạn, trong tâm trạng căng thẳng, bạn thậm chí quên cả việc gật đầu."
  },
  AvgDialog_123120_Content_119 = {
    Text = "Sóng rung… đang không ngừng thay đổi…"
  },
  AvgDialog_123120_Content_12 = {
    Text = "Không cần tìm nữa, linh mục White... chính là ở đây."
  },
  AvgDialog_123120_Content_120 = {
    Text = "Có thể là do sương mù tự thân, cũng có thể là bị các linh hồn mắc kẹt trong sương mù quấy nhiễu... Tôi cần thời gian để điều tra."
  },
  AvgDialog_123120_Content_121 = {
    Text = "Bạn ngẩng đầu nhìn bầu trời, lúc này bạn không còn thấy gì gọi là \"những vì sao\" nữa. \n Toàn bộ thế giới dường như chỉ còn lại sương mù dày đặc, cùng với cánh cửa chiều không gian liên tục phun ra sương mù."
  },
  AvgDialog_123120_Content_122 = {
    Text = "Nhưng chúng ta không còn thời gian nữa."
  },
  AvgDialog_123120_Content_123 = {
    Text = "……bạn nói đúng."
  },
  AvgDialog_123120_Content_124 = {
    Text = "Bạn cất giữ thiết bị đo, đưa tay nắm lấy chìa khóa bạc."
