  AvgDialog_123120_Content_126 = {
    Text = "Sứ giả nhợt nhạt, bạn có muốn kết nối…?"
  },
  AvgDialog_123120_Content_127 = {
    Text = "Salvador nhíu mày, nhìn bạn với vẻ không đồng tình. Còn bạn, chỉ im lặng."
  },
  AvgDialog_123120_Content_128 = {
    Text = "Này này, ở đây còn có một \"Khách từ thế giới khác\" nữa, có thể nói những điều tôi hiểu được không?"
  },
  AvgDialog_123120_Content_129 = {
    Text = "Ý nghĩa của %player% là…… kết nối cánh cửa chưa biết đó, để xác định sóng rung của chiều không gian."
  },
  AvgDialog_123120_Content_13 = {
    Text = "Đức Giám mục trên bàn thờ… chính là White."
