  AvgDialog_123120_Content_130 = {
    Text = "Cái gì? Đồ đó kỳ quái lắm, ai biết sẽ có kết quả gì, đừng có làm chuyện ngu ngốc nhé."
  },
  AvgDialog_123120_Content_131 = {
    Text = "Bạn nắm chặt chìa khóa bạc, sắc mặt nặng nề bước về phía cánh cửa ánh sáng vô hình. Vào thời điểm này, hành động còn quan trọng hơn lời nói."
  },
  AvgDialog_123120_Content_132 = {
    Text = "Thật sự phục những người nghĩ rằng thế giới nhàm chán này vẫn còn giá trị cứu rỗi…"
  },
  AvgDialog_123120_Content_133 = {
    Text = "Không ngờ, Mộc Hạ đã đưa tay chặn bạn lại. Cô ấy nhìn bạn với vẻ mặt phức tạp, dường như đang nhìn bạn, nhưng cũng như đang xuyên qua bạn, nhìn về phía người khác."
  },
  AvgDialog_123120_Content_134 = {
    Text = "Cuối cùng, mọi sự bối rối đều hóa thành nụ cười trên khuôn mặt, Mộc Hạ cố gắng làm cho giọng nói của mình nghe có vẻ thoải mái."
  },
  AvgDialog_123120_Content_135 = {
    Text = "Thôi được, ai bảo tôi là tiền phong được chú ý nhất của đoàn điều tra chứ, xông lên phía trước cũng là điều đương nhiên—"
  },
  AvgDialog_123120_Content_136 = {
    Text = "Vậy, hãy để tôi đi."
