  AvgDialog_123120_Content_137 = {
    Text = "Mộc Hạ nhìn bạn, vẻ mặt nghiêm túc và kiên định."
  },
  AvgDialog_123120_Content_138 = {
    Text = "Từ một góc của chiếc lồng giam, đây là lần đầu tiên cô ấy thể hiện biểu cảm nghiêm túc như vậy."
  },
  AvgDialog_123120_Content_14 = {
    Text = "Gì vậy!?"
  },
  AvgDialog_123120_Content_15 = {
    Text = "Trong sự kinh ngạc, bạn không khỏi quay đầu nhìn về phía White, thấy vị linh mục của Giáo hội Sinh mệnh trước đây, nay đã trở thành lãnh đạo tà giáo, đang phát biểu hùng hồn."
  },
  AvgDialog_123120_Content_16 = {
    Text = "Vào lúc này, chúng ta đã đưa ra lựa chọn với giá bạc và máu, và sẽ không bao giờ hối hận về điều đó."
  },
  AvgDialog_123120_Content_17 = {
    Text = "Để đến được \"Vương quốc yên tĩnh không tán mất\", để cứu rỗi chính mình trong thế giới đang cháy này——"
  },
  AvgDialog_123120_Content_18 = {
    Text = "Để đến được \"Vương quốc yên tĩnh không tán mất\", để cứu rỗi chính mình trong thế giới đang cháy này——"
  },
  AvgDialog_123120_Content_19 = {
    Text = "Mười mấy tín đồ của ánh sao bình minh đồng thanh tuyên thệ——"
  },
  AvgDialog_123120_Content_2 = {
    Text = "<Shake:Thế giới này đang bốc cháy, thế giới này đang sụp đổ, thế giới này định mệnh sẽ diệt vong.>"
  },
  AvgDialog_123120_Content_20 = {
    Text = "Mười mấy tín đồ của Hội Sao Bình minh đồng loạt giơ những con dao găm mạ bạc lên——"
  },
  AvgDialog_123120_Content_21 = {
    Text = "Dừng lại!"
  },
  AvgDialog_123120_Content_22 = {
    Text = "Trong tiếng thét của bạn, những con dao găm mạ bạc đồng thời đâm vào trái tim của những con vật hiến tế, cắm sâu vào, xoáy mạnh."
  },
  AvgDialog_123120_Content_23 = {
    Text = "Máu tươi chói mắt phun ra từ ngực của sinh vật hiến tế, nhuộm đỏ bàn thờ."
  },
  AvgDialog_123120_Content_24 = {
    Text = "Trong một mảnh máu đỏ, các bạn xuất hiện từ bóng tối ẩn mình, nhìn thẳng vào White, đối diện với nguồn gốc gây ra tất cả bi kịch này."
  },
  AvgDialog_123120_Content_25 = {
    Text = "Lại có những kẻ ngu dốt đến cản trở nghi lễ của Cha Trời?"
  },
  AvgDialog_123120_Content_26 = {
    Text = "Ha, khi thiên tai ập đến, các ngươi không hề động lòng, khi ta sắp dẫn dắt anh chị em của mình đạt được sự cứu rỗi, các ngươi lại muốn cản trở ta —"
  },
  AvgDialog_123120_Content_27 = {
    Text = "Lãnh đạo của hội Sao Sáng cười nhạo, nhìn về phía các bạn, sau đó đôi mắt của hắn đột nhiên mở to, đứng bất động tại chỗ."
  },
  AvgDialog_123120_Content_28 = {
    Text = "<Shake:Giám mục Salvador!?>"
  },
  AvgDialog_123120_Content_29 = {
    Text = "Sắc mặt của Salvador bao trùm bởi u ám, bạn nhận thấy dưới chiếc áo giáo chủ rộng thùng thình, thân hình cao lớn gầy gò của ông lại đang run rẩy nhẹ."
