  AvgDialog_126910_Content_1 = {
    Text = "Người chết thứ hai"
  },
  AvgDialog_126910_Content_10 = {
    Text = "Việc khẩn cấp hơn, chẳng phải là tìm ra hung thủ trong chúng ta sao?"
  },
  AvgDialog_126910_Content_11 = {
    Text = "Không, tôi không nghĩ vậy…… Chúng ta chỉ có ngần này người, nếu rơi vào tình trạng nghi ngờ lẫn nhau, chỉ làm cho tình hình trở nên tồi tệ hơn."
  },
  AvgDialog_126910_Content_12 = {
    Text = "Điều quan trọng hơn là đảm bảo an toàn cho những người còn lại. Chúng ta không bằng tất cả cùng ở lại trong toa xe số 2, thế nào?"
