  AvgDialog_126910_Content_14 = {
    Text = "Cây con đã đưa ra quyết định, tôi dĩ nhiên sẽ không phản đối."
  },
  AvgDialog_126910_Content_15 = {
    Text = "……Mỗi ba giờ, tôi cần một mình tìm một góc yên tĩnh để cầu nguyện."
  },
  AvgDialog_126910_Content_16 = {
