  AvgDialog_126910_Content_18 = {
    Text = "Chủ mà tôi phục vụ chỉ có một, đó chính là thần linh của Lemuria."
  },
  AvgDialog_126910_Content_19 = {
    Text = "Tuy nhiên, nếu bạn lại nói ra những lời xâm phạm, tôi không ngại thực hiện hình phạt của Chúa thay cho Ngài."
