  AvgDialog_126910_Content_21 = {
    Text = "Chúng tôi hiện tại không có bằng chứng để buộc tội bất kỳ ai, tinkerer... lúc đó, mọi người đều đã ngủ."
  },
  AvgDialog_126910_Content_22 = {
    Text = "Còn nữa, cái gọi là nội gián đó có thể chỉ là một trong những mưu kế của N, dụ dỗ chúng ta tự giết hại lẫn nhau theo ý đồ của hắn."
  },
  AvgDialog_126910_Content_23 = {
    Text = "Bạn làm sao có thể nói như vậy về người ta, ô ô ô, người ta thật lòng chân thành nhắc nhở các bạn đấy——"
