    Text = "Nốtira lau khô nước mắt, cố gắng lấy lại tinh thần, nở một nụ cười có phần khó coi."
  },
  AvgDialog_128699_Content_51 = {
    Text = "Thấy Nốtira không còn kháng cự, Mosk nhẹ nhàng, nhẹ nhàng kéo lấy móng vuốt của bạn, áp mặt lên đệm thịt của bạn."
  },
  AvgDialog_128699_Content_52 = {
    Text = "Đừng, sợ hãi."
  },
  AvgDialog_128699_Content_53 = {
    Text = "À……À! (Bạn sắp bỏ tôi sao……)"
  },
  AvgDialog_128699_Content_54 = {
    Text = "À!! À—— (Bạn sắp bỏ tôi sao!!)"
  },
  AvgDialog_128699_Content_55 = {
    Text = "Bạn bị bỏ vào vòng tay của Nốtira trong tiếng gào thét thê lương, ngay sau đó, Mosk không chút do dự quay người, lao về phía Vortex khi con tàu lại một lần nữa nghiêng ngả."
  },
  AvgDialog_128699_Content_56 = {
    Text = "……Pụt tọng."
  },
  AvgDialog_128699_Content_57 = {
    Text = "Như một con cá lặn vào đại dương của cô ấy."
  },
  AvgDialog_128699_Content_58 = {Text = "Mosk!!"},
  AvgDialog_128699_Content_59 = {
    Text = "Cơn bão che lấp tất cả tiếng kêu gào, những con sóng khổng lồ ập lên boong tàu, cuốn các bạn vào biển cả."
  },
  AvgDialog_128699_Content_6 = {
    Text = "Rầm————"
  },
  AvgDialog_128699_Content_60 = {
    Text = "Dưới mặt nước biển màu đen xanh, vô số sợi dây nhầy nhụa màu đen mở ra về phía Mosk, đôi tay của cô biến thành dòng chảy khổng lồ, nét mặt bình thản và an yên, sâu thẳm trong đôi mắt, dường như là trung tâm của cơn lốc."
  },
  AvgDialog_128699_Content_61 = {
    Text = "Mosk, Vortex. Mosk, vô lăng."
  },
  AvgDialog_128699_Content_62 = {
    Text = "Viên than nhỏ, Nốtira, ở đây, mãi mãi."
  },
  AvgDialog_128699_Content_63 = {
    Text = "Mosk cuối cùng không nhịn được nữa mà khóc thét lên, chỉ vào vị trí trái tim của mình."
  },
  AvgDialog_128699_Content_64 = {
    Text = "Cô ấy giơ tay lên, mang theo sức mạnh tàn phá hung bạo giống như cô ấy, nhưng lại là một cơn cuộn sóng vô cùng dịu dàng, đẩy các bạn ra xa theo hướng rời xa Vortex."
  },
  AvgDialog_128699_Content_65 = {
    Text = "Một chút, lại một chút, chất nhầy dính lên cơ thể của Mosk, trong chớp mắt đã bò đầy toàn thân Mosk."
  },
  AvgDialog_128699_Content_66 = {
    Text = "Vortex bắt đầu thu hẹp ngược chiều về trung tâm, cuốn theo những điều mà Ngài mong muốn, cô gái như bị vô số rong biển đen cuốn lấy, kéo xô, dần dần chìm xuống đáy biển u ám."
  },
  AvgDialog_128699_Content_68 = {
    Text = "Mọi thứ đã lắng xuống, bầu trời trong xanh như rửa, trên mặt biển yên tĩnh, những con thuyền lặng lẽ trôi nổi."
  },
  AvgDialog_128699_Content_69 = {
    Text = "Ơ, đây là đâu, tại sao tôi lại ở trên nước? Hức, ngột ngạt quá!"
  },
  AvgDialog_128699_Content_7 = {
    Text = "Cơn chấn động mạnh mẽ đã hất Nốtira bay ra, đập vào thùng gỗ đang lăn trên mặt đất."
  },
  AvgDialog_128699_Content_70 = {
    Text = "Bạn nhìn một cách kỳ lạ vào người mặc bộ quần áo kỳ quái, đang nổi trên mặt nước."
  },
  AvgDialog_128699_Content_71 = {
    Text = "(Tôi làm sao lại chạy đến đây, người đó là ai?)"
  },
  AvgDialog_128699_Content_72 = {
    Text = "Bộp bộp."
  },
  AvgDialog_128699_Content_73 = {
    Text = "Bộp bộp."
  },
  AvgDialog_128699_Content_74 = {
    Text = "(Đúng rồi, tôi là một con hải cẩu! Hải cẩu thì phải đi tìm vỏ sò. Vỏ sò, vỏ sò!)"
  },
  AvgDialog_128699_Content_75 = {
    Text = "Bạn vui vẻ lặn vào làn nước ấm áp, ngược hướng với con người đang khó khăn bơi về phía thuyền."
  },
  AvgDialog_128699_Content_76 = {
    Text = "Bạn không phát hiện ra mình đã hòa vào nước mắt trong biển cả."
  },
  AvgDialog_128699_Content_8 = {Text = "Ugh…"},
  AvgDialog_128699_Content_9 = {
    Text = "Nốtira chịu đựng cơn đau, loạng choạng đứng dậy, lao về phía bên cạnh Mosk."
  },
  AvgDialog_128700_Content_1 = {
    Text = "Gừ——Gừ——"
  },
  AvgDialog_128700_Content_10 = {
    Text = "Bạn là một con hải mã một tuổi rưỡi, đang kiếm ăn cùng với gã to xác mà bạn thích nhất."
  },
  AvgDialog_128700_Content_100 = {
    Text = "Nước bọt không thể kiểm soát mà tiết ra điên cuồng, trước sự cám dỗ của món ăn, bạn và Mosk gần như cùng lúc lao vào, cả hai cùng cắn vào cá nướng."
  },
  AvgDialog_128700_Content_101 = {
    Text = "Ngon——!"
  },
  AvgDialog_128700_Content_102 = {
    Text = "Ơ, à... Nốtira, tay?"
  },
  AvgDialog_128700_Content_103 = {
    Text = "Chỉ bị trật khớp thôi, tôi đã tự nối lại rồi, đối với một nhà phiêu lưu mà nói, không có gì to tát, cảm ơn thuốc của bạn!"
  },
  AvgDialog_128700_Content_104 = {
    Text = "<Small:(Mặc dù nó vừa đắng vừa mạnh, nhưng hiệu ứng thực sự rất tốt.)>"
  },
  AvgDialog_128700_Content_105 = {
    Text = "A hô! Vui vẻ, ôm……"
  },
  AvgDialog_128700_Content_106 = {
    Text = "Hê hê, Mosk, cẩn thận nhé."
  },
  AvgDialog_128700_Content_107 = {
    Text = "Ê? Ê! Đừng lo lắng, Mosk, nếu có lần sau, tôi sẽ hét lớn lên để nhắc bạn đau."
  },
  AvgDialog_128700_Content_108 = {Text = "Két!"},
  AvgDialog_128700_Content_11 = {
    Text = "(rong biển, cỏ biển, đá nhỏ……)"
  },
  AvgDialog_128700_Content_12 = {
    Text = "(Stone, dì của Stone, ông của Stone…?)"
  },
  AvgDialog_128700_Content_13 = {
    Text = "(Stone! Bảo cả gia đình bạn đừng đi quanh đây nữa!!)"
  },
  AvgDialog_128700_Content_14 = {
    Text = "<Shake:rầm rộ——>"
  },
  AvgDialog_128700_Content_15 = {
    Text = "(Không tốt……)"
  },
  AvgDialog_128700_Content_16 = {
    Text = "Mặt biển cuộn lên những vòng xoáy lớn, một hình dáng quen thuộc đang vác cái gì đó, lao nhanh về phía bạn"
  },
  AvgDialog_128700_Content_17 = {
    Text = "Viên than nhỏ! Thịt! Mosk, nhặt được"
  },
  AvgDialog_128700_Content_18 = {
    Text = "Vui vẻ, về nhà, cùng nhau"
  },
  AvgDialog_128700_Content_19 = {
    Text = "Chưa để bạn phản đối, cô gái lại một lần nữa vác bạn lên lưng, bơi về phía mặt nước như cá."
  },
  AvgDialog_128700_Content_2 = {
    Text = "<Shake:Ọc ọc…>"
  },
  AvgDialog_128700_Content_21 = {
    Text = "Ầm ầm——! Sau tia chớp, tiếng sấm lớn vang lên, những đám mây mưa nặng nề đã lâu nay xả nước vào đại dương."
  },
  AvgDialog_128700_Content_22 = {
    Text = "Bạn và Mosk đã trở về bên trong khoang tàu an toàn, nhìn nhau chằm chằm."
  },
  AvgDialog_128700_Content_23 = {
    Text = "Á? À, à! (Đây là thịt? Cái to này, trông giống bạn quá!)"
  },
  AvgDialog_128700_Content_24 = {
    Text = "Giống nhau?"
  },
  AvgDialog_128700_Content_25 = {
    Text = "Mosk nghiêng đầu, lộ ra biểu cảm bối rối đặc trưng của cô ấy, sau đó mới nghiêm túc cúi đầu nhìn vào \"thịt\" mà cô đã bỏ xuống đất."
  },
  AvgDialog_128700_Content_26 = {
    Text = "Phì——Ọe."
  },
  AvgDialog_128700_Content_27 = {
    Text = "Vừa rồi đã xảy ra chuyện gì, đầu tôi hình như vẫn đang ở trong nước, đây là đâu, tôi đã chết rồi sao?"
  },
  AvgDialog_128700_Content_28 = {
    Text = "Người lạ ho vài tiếng, nhổ ra một mồm nước biển."
  },
  AvgDialog_128700_Content_29 = {
    Text = "Bạn? Bạn! Giống Mosk"
  },
  AvgDialog_128700_Content_3 = {
    Text = "<Shake:gừ gừ gừ——>"
  },
  AvgDialog_128700_Content_30 = {Text = "Ơ…Ơ?"},
  AvgDialog_128700_Content_31 = {
    Text = "<LightGray:Có phải là quần thể nguyên thủy ở gần đây không? Kỳ lạ… Đây là đâu vậy?>"
  },
  AvgDialog_128700_Content_32 = {
    Text = "Bạn phát hiện ra rằng mặc dù đối phương rất cảnh giác, nhưng có vẻ không có ác ý. Vì vậy, bạn lén lút tiến lại gần hơn, chuẩn bị quan sát người mới đến này."
  },
  AvgDialog_128700_Content_33 = {
    Text = "Đây chắc hẳn là khoang của một con tàu, mặc dù nhìn có hơi cũ, nhưng về cơ bản vẫn rất hoàn chỉnh…"
  },
  AvgDialog_128700_Content_34 = {
    Text = "Đợi đã, đinh tán của công ty Nordril?! Bộ cảm biến mức nước, van trượt chính dạng vòng…"
  },
  AvgDialog_128700_Content_35 = {
    Text = "Tôi xem nào, nếu là như vậy……"
  },
  AvgDialog_128700_Content_36 = {
    Text = "Người lạ phấn khích lật tung cả khoang chứa đầy ắp, trong khi đó, Mosk đứng bên cạnh vui vẻ và tò mò chớp chớp mắt."
  },
  AvgDialog_128700_Content_37 = {
    Text = "Sáng lấp lánh, đẹp, Mosk, mang đến. Bạn, có thích không?"
  },
  AvgDialog_128700_Content_38 = {
    Text = "Mosk, miễn là có những thứ này, tôi có thể làm cho con tàu này hoạt động trở lại, bạn có thể đưa chúng cho tôi không?"
  },
  AvgDialog_128700_Content_39 = {
    Text = "Chờ khi trở về Aglo, tôi nhất định sẽ trả lại cho bạn nhiều hơn, đẹp hơn những thứ sáng lấp lánh."
  },
  AvgDialog_128700_Content_4 = {
    Text = "Bạn nằm ngửa trong nước biển ấm áp, thoải mái duỗi thẳng bốn chi ngắn, xoay một vòng hoàn hảo."
  },
  AvgDialog_128700_Content_40 = {
    Text = "Á——! (Không được! Bên trong còn có quả bóng xinh đẹp của tôi nữa!)"
  },
  AvgDialog_128700_Content_41 = {
    Text = "Bạn tức giận hét lên, muốn giành lại quả bóng nhỏ của mình, nhưng ánh mắt ngay lập tức bị Mosk thu hút."
  },
  AvgDialog_128700_Content_42 = {
    Text = "Suỵt, Mosk, cho bạn, vỏ."
  },
  AvgDialog_128700_Content_43 = {
    Text = "Mosk lén lút đưa cho bạn hai chiếc vỏ sò mà bạn đã nhìn từ lâu, rồi đẩy những bộ phận đó về phía người lạ, ra hiệu cho đối phương có thể đưa cho cô ấy."
  },
  AvgDialog_128700_Content_44 = {
    Text = "Bạn bè, thích, cho"
  },
  AvgDialog_128700_Content_45 = {
    Text = "Bạn không biết những thứ này làm sao có thể khiến người lạ phấn khích như vậy, rồi lại hạnh phúc đưa cái mũi nhỏ bé của mình chui vào hai chiếc vỏ sò đẹp đẽ mà trước đây Mosk hoàn toàn không muốn để bạn chạm vào."
  },
  AvgDialog_128700_Content_46 = {
    Text = "Tuyệt vời! Cảm ơn bạn……bạn bè."
  },
  AvgDialog_128700_Content_47 = {
    Text = "Bị cảm hóa bởi sự nồng nhiệt và thân thiện của Mosk, người lạ cuối cùng cũng thả lỏng một chút, nở nụ cười với các bạn."
  },
  AvgDialog_128700_Content_48 = {
    Text = "Đúng rồi, tên tôi là Nốtira."
  },
  AvgDialog_128700_Content_49 = {
    Text = "Tốt quá! Nốtira, Mosk, bạn bè, vui vẻ"
  },
  AvgDialog_128700_Content_5 = {
    Text = "(Đợi đã, tứ chi ngắn ngủn?)"
  },
  AvgDialog_128700_Content_50 = {
    Text = "Mosk hô hào, giang rộng hai tay, muốn cho người bạn mới quen một cái ôm thật lớn."
  },
  AvgDialog_128700_Content_51 = {
    Text = "Ái! (Tệ rồi... gã to xác...)"
  },
  AvgDialog_128700_Content_52 = {
    Text = "Bạn, ôm!"
  },
  AvgDialog_128700_Content_53 = {
    Text = "Chờ chút, Mosk... Ôi! Đau quá!"
  },
  AvgDialog_128700_Content_54 = {
    Text = "Luồng không khí trong không khí đột ngột tụ lại, dưới áp suất gió đột ngột tăng mạnh, phát ra âm thanh rắc rắc trong trẻo."
  },
  AvgDialog_128700_Content_55 = {Text = "A!"},
  AvgDialog_128700_Content_56 = {
    Text = "Mosk ngay lập tức tỉnh táo lại, vội vàng buông tay Nốtira, nhưng Nốtira đã đau đến mức mặt mày biến dạng, cánh tay rõ ràng đã vặn ở một góc độ không tự nhiên."
  },
  AvgDialog_128700_Content_57 = {
    Text = "Xin, xin lỗi…… tôi……"
  },
  AvgDialog_128700_Content_58 = {
    Text = "Bạn thấy Mosk bối rối, cố gắng cắn chặt quần của cô ấy, kéo về một hướng."
  },
  AvgDialog_128700_Content_59 = {
    Text = "À, à! (<Big: này!>)"
  },
  AvgDialog_128700_Content_6 = {
    Text = "<Shake:Lộp bộp lộp bộp.>"
  },
  AvgDialog_128700_Content_60 = {
    Text = "Ô ô, đúng rồi, cái này! Nốtira, uống"
  },
  AvgDialog_128700_Content_61 = {
    Text = "Đừng chạm vào tôi!"
  },
  AvgDialog_128700_Content_62 = {
    Text = "Nốtira vô thức vung tay đẩy tay Mosk ra, cả người dựa về phía sau."
  },
  AvgDialog_128700_Content_63 = {
    Text = "[@3 hỗn hợp]"
  },
  AvgDialog_128700_Content_64 = {
    Text = "Gulu gulu——lọ thuốc rơi xuống đất, lăn về phía chân Mosk."
  },
  AvgDialog_128700_Content_65 = {
    Text = "Cô gái vừa rồi còn đắc ý quên mình, nhạy bén nhận ra nỗi sợ hãi của đối phương, từ từ hạ tay xuống."
  },
  AvgDialog_128700_Content_67 = {
    Text = "Xin lỗi, nhưng mà... trên thuyền còn chỗ nào khác không, tôi có thể cần nghỉ ngơi một mình."
  },
  AvgDialog_128700_Content_68 = {
    Text = "Mosk im lặng một lúc, kéo đến chiếc chăn lớn nhất và mềm nhất trên tàu, trải xa trên mặt đất."
  },
  AvgDialog_128700_Content_69 = {
    Text = "Mosk, bất cẩn, Sức Mạnh Lớn, gây thương."
  },
  AvgDialog_128700_Content_7 = {
    Text = "Bộp bộp~"
  },
  AvgDialog_128700_Content_70 = {
    Text = "Mosk, xấu, xin lỗi. Nhà, ấm áp, Nốtira."
  },
  AvgDialog_128700_Content_71 = {
    Text = "Cơ thể bỗng dưng treo lơ lửng, Mosk như một báu vật, cẩn thận và có chút e dè đưa bạn về phía Nốtira."
  },
  AvgDialog_128700_Content_72 = {
    Text = "Ngoài kia, Mosk. Viên than nhỏ, ấm áp, Nốtira, ở đây."
  },
  AvgDialog_128700_Content_73 = {
    Text = "Cô ấy ngẩng cằm lên, chỉ ra bên ngoài, rồi chỉ vào chăn, kiên quyết đứng giữa Nốtira và cửa."
  },
  AvgDialog_128700_Content_74 = {
    Text = "... Thôi được, cảm ơn."
  },
  AvgDialog_128700_Content_75 = {
    Text = "À, à? (Êi, Êi, thằng lớn?)"
  },
  AvgDialog_128700_Content_77 = {
    Text = "Mưa không ngừng suốt đêm, nửa đêm, Nốtira đi đến cửa phòng, nhìn cô gái đang ngủ say trên boong tàu."
  },
  AvgDialog_128700_Content_78 = {
    Text = "Cô ấy cuộn mình thành một đống, trốn trong góc tàu để tránh gió mưa."
  },
  AvgDialog_128700_Content_79 = {
    Text = "……Ở nơi như vậy mà vẫn có thể ngủ say như vậy, thật giống như một con vật nhỏ……"
  },
  AvgDialog_128700_Content_8 = {
    Text = "(Đúng rồi, tôi là một con rái cá!)"
  },
  AvgDialog_128700_Content_80 = {
    Text = "Xin lỗi, tôi không nên đối xử với bạn như vậy, Mosk."
  },
  AvgDialog_128700_Content_81 = {
    Text = "Mosk thêm một chiếc chăn, cô ấy trong giấc mơ khẽ nhếch môi, chìm vào giấc mơ ngọt ngào hơn."
  },
  AvgDialog_128700_Content_82 = {Text = "Két!"},
  AvgDialog_128700_Content_83 = {
    Text = "Sáng hôm sau, sau cơn mưa là thời điểm tuyệt vời để đánh bắt cá. \n Bạn tự hào cắn chặt con cá lớn nhất hôm nay và ném về phía Mosk, nhưng mà……"
  },
  AvgDialog_128700_Content_84 = {Text = "Pập!"},
  AvgDialog_128700_Content_86 = {
    Text = "Mosk đón lấy con cá bằng mặt, từ buổi sáng đến giờ, sự ngây ngốc bắt đầu xuất hiện một vết nứt. Cô ấy nhìn bạn, khóe miệng cong xuống, sau đó, những giọt nước mắt lớn liên tục rơi xuống."
  },
  AvgDialog_128700_Content_87 = {
    Text = "Ư… Aaaa……"
  },
  AvgDialog_128700_Content_88 = {
    Text = "Ngay sau đó, cô ấy không màng gì nữa, chôn mặt hoàn toàn vào bụng bạn, bắt đầu khóc thét lên."
  },
  AvgDialog_128700_Content_89 = {
    Text = "Mosk, xấu!"
  },
  AvgDialog_128700_Content_9 = {
    Text = "Cái đầu nhỏ bé của bạn, chỉ có một chút xíu, vui vẻ nhớ lại tình hình hiện tại."
  },
  AvgDialog_128700_Content_90 = {
    Text = "À! À!! À! (<Big: Cẩn thận cái mũi của bạn!>)"
  },
  AvgDialog_128700_Content_91 = {
    Text = "Ư, biết nói, giống nhau, bạn, mãi mãi không… ư ư ư…"
  },
  AvgDialog_128700_Content_92 = {
    Text = "Mosk khóc đến nỗi không thở nổi, bạn cố gắng kéo bụng mình ra khỏi mặt cô ấy, nhưng cuối cùng chỉ có thể thở dài, để cô ấy tự do xoa những giọt nước mũi của mình."
  },
  AvgDialog_128700_Content_93 = {
    Text = "(Định nói cuối cùng cũng tìm được bạn có thể nói chuyện giống mình, nhưng cuối cùng lại làm hỏng mọi chuyện, nhưng gã to xác có thể tính là biết nói không nhỉ?)"
  },
  AvgDialog_128700_Content_94 = {
    Text = "(Ủa, đợi một chút, mùi thơm quá!)"
  },
  AvgDialog_128700_Content_96 = {
    Text = "Trong khoang, Nốtira dùng dây thép mảnh xuyên qua vài con cá biển, ngọn lửa đã làm cho bề mặt cá trở nên giòn cháy, mỡ cá nhỏ giọt xuống sàn, phát ra mùi hương đủ để kích thích bản năng động vật."
  },
  AvgDialog_128700_Content_97 = {
    Text = "Ừm, xin lỗi, tôi thấy các bạn có vẻ đều ăn cá sống, nên đã chế biến một chút... dù không có gia vị, thử nếm xem sao?"
  },
  AvgDialog_128700_Content_98 = {Text = "Á a!"},
  AvgDialog_128700_Content_99 = {Text = "Á a!"},
  AvgDialog_130451_Content_1 = {
    Text = "Đêm tối mịt mù, bạn vừa kết thúc một chuyến công tác bên ngoài, Thể thức tỉnh cùng thực hiện nhiệm vụ với bạn — tiểu kỵ sĩ đến từ thế giới khác, Phụ Thệ·Orci — đang lặng lẽ bước theo sau bạn."
  },
  AvgDialog_130451_Content_10 = {
    Text = "Đợi đã, xin đừng lại gần!"
  },
  AvgDialog_130451_Content_11 = {
    Text = "Lời chưa dứt, tầm nhìn của bạn bỗng chốc tối sầm lại."
  },
  AvgDialog_130451_Content_12 = {
    Text = "Những thứ vô hình vốn cộng sinh cùng Phụ Thệ·Orci bỗng nhiên ùa về phía bạn, bám lấy tứ chi, che khuất đôi mắt, quấn chặt lấy bạn, khiến bạn cảm thấy lạnh lẽo."
  },
  AvgDialog_130451_Content_13 = {Text = "Ogier!"},
  AvgDialog_130451_Content_14 = {
    Text = "Bạn lên tiếng kêu gọi, những thứ bùn đen ấy lại quấn chặt hơn, như thể đang vội vã giam cầm bạn hoàn toàn trong đó. Bạn giơ tay ra sức giật, chúng lại ngoan cố bao phủ trở lại như những dây leo."
  },
  AvgDialog_130451_Content_15 = {Text = "Ugh…"},
  AvgDialog_130451_Content_16 = {
    Text = "Giọng nói mờ nhạt và yếu ớt của thiếu niên vang lên đứt quãng, rõ ràng đang cố hết sức kìm nén điều gì đó."
  },
  AvgDialog_130451_Content_17 = {
    Text = "Orci? Bạn có nghe thấy tôi nói không?"
  },
  AvgDialog_130451_Content_18 = {
    Text = "Lực quấn chặt bạn khẽ rùng mình một cái, rồi lại siết chặt trở lại, như thể đang giằng co giữa hai ý chí."
  },
  AvgDialog_130451_Content_19 = {
    Text = "Vì sự bất tài của ta, vẫn để ngài bị thương. Giá như, ta có thể dùng cách tốt hơn để bảo vệ ngài……"
  },
  AvgDialog_130451_Content_2 = {
    Text = "Nhiệm vụ lần này không có gì khó khăn, là người giữ bí mật giàu kinh nghiệm, bạn và Phụ Thệ·Orci đã dễ dàng giải quyết tất cả kẻ thù. Tuy nhiên, do một phút sơ suất, bạn vẫn để lại một vết thương nhỏ trên cổ tay."
  },
  AvgDialog_130451_Content_20 = {
    Text = "Bạn chỉ có thể nghe thấy vài lời lẩm bẩm mơ hồ, như thể đang tự nói chuyện với bản thân."
  },
  AvgDialog_130451_Content_21 = {
    Text = "Những thứ bùn đen này tuy quấn chặt, nhưng không khiến bạn cảm thấy đau đớn hay nghẹt thở dù chỉ một chút. Bạn bỗng nhận ra, đây có lẽ không phải là muốn làm hại bạn, mà giống như muốn giấu bạn vào một nơi tuyệt đối an toàn, không cho bất cứ thứ gì lại gần."
  },
  AvgDialog_130451_Content_22 = {
    Text = "Không sao đâu, tôi không có chuyện gì cả, bạn không cần phải sợ."
  },
  AvgDialog_130451_Content_23 = {
    Text = "Lời bạn nói dường như có tác dụng. Lần này, lực của những thứ bùn đen ấy cuối cùng cũng dần dần lơi ra. Bạn nhân cơ hội kéo chúng ra."
  },
  AvgDialog_130451_Content_24 = {
    Text = "Bạn thấy Phụ Thệ·Orci cúi đầu xuống trong thất vọng, đôi mày khẽ nhíu lại, ánh mắt vẫn còn mơ hồ lạc lối, tựa như một bức tượng sám hối đang gánh chịu tội lỗi khổng lồ."
  },
  AvgDialog_130451_Content_25 = {
    Text = "Bạn có khỏe không?"
  },
  AvgDialog_130451_Content_26 = {
    Text = "Ta đã dùng sức mạnh mất kiểm soát như vậy với ngài……"
  },
  AvgDialog_130451_Content_27 = {
    Text = "Không được, ta phải để bản thân……tỉnh táo lại."
  },
  AvgDialog_130451_Content_28 = {
    Text = "Anh nhắm mắt thì thầm, biến đám bùn đen nhỏ đang xoáy quanh tay thành hình dạng một con dao găm, ánh trăng chiếu lên lưỡi dao lạnh lẽo đó, và mũi dao hướng về phía cánh tay còn lại của chính anh."
  },
  AvgDialog_130451_Content_29 = {
    Text = "Tuy nhiên, vật sắc nhọn đó chưa kịp hạ xuống, bạn đã kịp thời lao lên phía trước, ngăn chặn hành động của anh. Bạn chợt nhận ra, những thứ vô hình vừa còn quấn chặt lấy bạn, giờ đã hoàn toàn rút lui."
  },
  AvgDialog_130451_Content_3 = {
    Text = "Xung quanh yên tĩnh lạ thường, bạn mệt mỏi đến mức ý thức có phần mơ hồ, thì bỗng giật mình vì tiếng động vang lên phía sau."
  },
  AvgDialog_130451_Content_30 = {
    Text = "Chúa công……?"
  },
  AvgDialog_130451_Content_31 = {
    Text = "Bạn khom người xuống, nhẹ nhàng ôm lấy anh, vỗ về lưng anh."
  },
  AvgDialog_130451_Content_32 = {
    Text = "Anh không né tránh như thường lệ, mà đứng ngây ra tại chỗ, giữ nguyên tư thế được bạn ôm."
  },
  AvgDialog_130451_Content_33 = {
    Text = "Đừng quá vội vàng, hãy thư giãn, bạn thấy đó, Ngài đã bị bạn trấn áp thành công rồi. Nhưng mà, rốt cuộc đã xảy ra chuyện gì vậy?"
  },
  AvgDialog_130451_Content_34 = {
    Text = "Xin lỗi, chủ nhân. Không hiểu sao, hôm nay sự tồn tại ký sinh trên người ta bỗng dưng kích động bất thường, suy nghĩ của ta cũng trở nên rất hỗn loạn."
  },
  AvgDialog_130451_Content_35 = {
    Text = "Rõ ràng ngài đang ở bên cạnh ta, vậy mà Ngài không những không rút lui như thường lệ, mà còn hoạt động mạnh hơn……vì vậy ta mới muốn dùng cơn đau để bản thân bình tĩnh lại."
  },
  AvgDialog_130451_Content_36 = {
    Text = "Bạn ôm Orci, cảm nhận được nhiệt độ bất thường trên người anh, trong lòng đã có kết luận. Bạn không ngờ rằng, ảnh hưởng của Sông thiêng liêng lại trực tiếp can thiệp vào một sức mạnh khác trên người Orci."
  },
  AvgDialog_130451_Content_37 = {
    Text = "Đây không phải lỗi của bạn, mà là do ảnh hưởng của một số……thứ khác."
  },
  AvgDialog_130451_Content_38 = {
    Text = "Hơn nữa, dù đám bùn đen này có giam cầm ta một lúc, nhưng hoàn toàn không làm ta bị thương……chắc là vì bạn đang kiểm soát Ngài đúng không? Thật đáng khâm phục đấy."
  },
  AvgDialog_130451_Content_39 = {
    Text = "Sau một khoảng lặng ngắn, cuối cùng bạn cũng nghe thấy giọng nói trầm trầm của cậu thiếu niên."
  },
  AvgDialog_130451_Content_4 = {
    Text = "……Đủ rồi! Làm sao ta có thể đối với chủ quân——"
  },
  AvgDialog_130451_Content_40 = {
    Text = "……Cảm ơn ngài, lại để ngài phải an ủi ta rồi."
  },
  AvgDialog_130451_Content_41 = {
    Text = "Đã muộn rồi, xin hãy cho phép ta xử lý vết thương cho ngài trước, rồi hộ tống ngài về phòng nhé."
  },
  AvgDialog_130451_Content_5 = {
    Text = "Bạn biết rằng từ lâu nay, Phụ Thệ·Orci vẫn luôn đấu tranh với thứ vô hình bám trên người hắn, nhưng phản ứng của hắn hôm nay có vẻ kỳ lạ đến mức thái quá."
  },
  AvgDialog_130451_Content_6 = {
    Text = "Vì vậy, bạn quay người lại, bước về phía hắn."
  },
  AvgDialog_130451_Content_7 = {
    Text = "Orci? Bạn ổn không? Nó lại đang cố kiểm soát bạn sao?"
  },
  AvgDialog_130451_Content_8 = {Text = "!"},
  AvgDialog_130451_Content_9 = {
    Text = "Phụ Thệ·Orci đột ngột ngẩng cái đầu vốn đang chằm chằm nhìn mũi giày của mình lên, rồi run rẩy lùi lại một bước."
  },
  AvgDialog_130453_Content_1 = {
    Text = "Do sức mạnh đặc biệt vốn có của Saya, mọi người đều rất lo lắng về phản ứng có thể xảy ra khi cô ấy chịu ảnh hưởng của Thánh Hà."
  },
  AvgDialog_130453_Content_10 = {
    Text = "Tất cả quá khứ đã nhào nặn nên tôi của hiện tại, nhưng vẫn còn rất nhiều điều tôi chưa từng được học."
  },
  AvgDialog_130453_Content_11 = {
    Text = "\"Bản năng là sinh sản\" ư. Ôi……Thì ra vậy……"
  },
  AvgDialog_130453_Content_12 = {
    Text = "Cô ấy vừa nói vậy, vừa đưa cho bạn một chiếc gối tựa."
  },
  AvgDialog_130453_Content_13 = {
    Text = "Bạn thở phào nhẹ nhõm, cũng tựa vào chiếc gối như Saya."
  },
  AvgDialog_130453_Content_14 = {
    Text = "Thì ra là vậy, sau khi trải qua những chuyện đó, so với bản năng, lý trí chiếm ưu thế hơn sao……"
  },
  AvgDialog_130453_Content_15 = {
    Text = "<Small:Dù đã trở thành Thể Thức Tỉnh, Saya vẫn rất đặc biệt nhỉ……>"
  },
  AvgDialog_130453_Content_16 = {
    Text = "Nếu không phiền, chỗ của Saya có thể trở thành nơi trú ẩn của tôi được không!"
  },
  AvgDialog_130453_Content_17 = {
    Text = "Bạn đầy xúc động đề xuất với đối phương."
  },
  AvgDialog_130453_Content_18 = {
    Text = "Điều cấp bách nhất lúc này là, Người Giữ Gìn đáng thương của Misag cuối cùng cũng có một nơi trú ẩn an toàn đáng tin cậy."
  },
  AvgDialog_130453_Content_19 = {
    Text = "Hả? Dù không hiểu lắm……"
  },
  AvgDialog_130453_Content_2 = {
    Text = "Nhưng ngoài dự kiến, Saya chỉ bình tĩnh đứng bên cửa sổ, làn da trắng tuyết gần như trong suốt dường như muốn cách ly cô ấy sang một thế giới khác."
  },
  AvgDialog_130453_Content_20 = {
    Text = "Saya giả vờ khó xử nhíu mày, sau khi được thấy vẻ mặt thất vọng của bạn như ý muốn mới cười trở lại."
  },
  AvgDialog_130453_Content_21 = {
    Text = "Tất nhiên được, nhưng phải đổi bằng việc trả lời một câu hỏi đấy."
  },
  AvgDialog_130453_Content_22 = {
    Text = "Người mà cậu quan tâm nhất là ai vậy?"
  },
  AvgDialog_130453_Content_23 = {
    Text = "Như hai người bạn thân vô tư, hai người vui vẻ trò chuyện."
  },
  AvgDialog_130453_Content_24 = {
    Text = "Người mà tôi luôn nhớ đến……"
  },
  AvgDialog_130453_Content_25 = {
    Text = "Một bóng hình xuất hiện trong ý thức của bạn, bạn thư thái nhắm mắt lại, đồng thời dâng lên Lời chúc cho tương lai của Saya — nguyện sự tồn tại này có thể vượt qua dòng thời gian dài lâu."
  },
  AvgDialog_130453_Content_26 = {
    Text = "Sức mạnh của Thánh Hà như dòng thủy triều dịu dàng, lặng lẽ chảy qua giữa hai người."
  },
  AvgDialog_130453_Content_27 = {
    Text = "Tất cả đều tĩnh lặng như một bí ẩn."
  },
  AvgDialog_130453_Content_3 = {
    Text = "Xin chào, Người Giữ Bí Mật."
  },
  AvgDialog_130453_Content_4 = {
    Text = "Saya, bây giờ cậu có cảm thấy chỗ nào không thoải mái, hay có gì bất thường không?"
  },
  AvgDialog_130453_Content_5 = {
    Text = "Như cảm nhận được sự lo lắng của bạn, thiếu nữ nhẹ nhàng xoay một vòng."
  },
  AvgDialog_130453_Content_6 = {
    Text = "Không sốt cao, không nhịp tim nhanh bất thường, không hưng phấn vô cớ, không có gì cả."
  },
  AvgDialog_130453_Content_7 = {
    Text = "Đừng lo, dường như không có chuyện gì đặc biệt xảy ra với tôi."
  },
  AvgDialog_130453_Content_8 = {
    Text = "Bản năng của chủng tộc phu nhân Tethys là sinh sản, liệu chuyện như vậy cũng sẽ xảy ra với tôi sao?"
  },
  AvgDialog_130453_Content_9 = {
    Text = "Cô ấy ngồi xuống ở vị trí gần bạn hơn, tựa mình vào một chiếc đệm êm ái, nở nụ cười như một sinh vật nhỏ vô hại."
  },
  AvgDialog_130454_Content_1 = {
    Text = "Trong đại điện trống rỗng, chỉ có tiếng bước chân của bạn và Murphy vang vọng."
  },
  AvgDialog_13049_Content_1 = {
    Text = "Ogier ôm chặt vũ khí, cảnh giác với mọi động tĩnh xung quanh, trong mắt anh, bất kỳ tiếng động nào cũng có thể là quân địch mai phục."
  },
  AvgDialog_13049_Content_10 = {
    Text = "Tiếng nước? Chắc là đồng hồ nước bên kia."
  },
  AvgDialog_13049_Content_11 = {
    Text = "Hình như tiếng động từ bên ngoài vọng vào, để tôi ra xem!"
  },
  AvgDialog_13049_Content_12 = {
    Text = "Đừng vội! Chúng ta cùng đi!"
  },
  AvgDialog_13049_Content_13 = {
    Text = "Không kịp ngăn cản, Augier đã vác vũ khí lao ra trước cổng hành cung."
  },
  AvgDialog_13049_Content_14 = {
    Text = "Cái này là——?!"
  },
  AvgDialog_13049_Content_15 = {
    Text = "Địch tập kích!"
  },
  AvgDialog_13049_Content_2 = {
    Text = "Ngươi không tìm được lý do nào để an ủi anh ta, những dòng chữ trên hồ sơ Thể Thức Tỉnh từng đọc kỹ, hiện rõ trước mắt—"
  },
  AvgDialog_13049_Content_3 = {
    Text = "Thể Thức Tỉnh tự thuật: Ogier·Danske, kỵ sĩ công quốc @2\nHy sinh trong Đêm Vệ Quốc……"
  },
  AvgDialog_13049_Content_4 = {
    Text = "Thưa các hạ thị quan, ngài cũng hãy đến ngoại thành lánh nạn trước đi, ở đây… có chúng tôi là đủ rồi."
  },
  AvgDialog_13049_Content_5 = {
    Text = "Hai kỵ sĩ các ngươi, đến ô đầu và hoa lan còn phân biệt không nổi, lỡ đem thuốc độc cho công chúa uống thì sao?"
  },
  AvgDialog_13049_Content_6 = {
    Text = "Lời từ chối thẳng thắn ngược lại lại xoa dịu bầu không khí căng thẳng, Ogier đỏ mặt, kỵ sĩ hộ vệ nhịn cười, ngay cả sau cánh cửa cũng vọng ra tiếng cười khẽ nghẹn ngào."
  },
  AvgDialog_13049_Content_7 = {
    Text = "Ngươi không thể rời đi — bị mắc kẹt trong bí ẩn xoay quanh Ogier, rời đi bất cẩn không biết sẽ dẫn đến hậu quả gì."
  },
  AvgDialog_13049_Content_8 = {
    Text = "Tích tắc—"
  },
  AvgDialog_13049_Content_9 = {
    Text = "Các ngươi có nghe thấy tiếng gì không?"
  },
  AvgDialog_13050_Content_1 = {
    Text = "Cuối cùng cũng kết thúc trận chiến, bạn và Ogier ở lại dưới cầu thang dọn dẹp đại sảnh hành cung, còn kỵ sĩ hộ vệ thì đã sớm quay về canh trước phòng công chúa."
  },
  AvgDialog_13050_Content_10 = {
    Text = "Xào xạc……"
  },
  AvgDialog_13050_Content_11 = {
    Text = "Nhưng mà… bệnh dịch hóa thành quái vật, người thường lại không thể nhìn thấy?"
  },
  AvgDialog_13050_Content_12 = {
    Text = "Thật sự quá hoang đường, dù có để thi nhân cung đình truyền hát, e rằng cũng chẳng mấy ai tin."
  },
  AvgDialog_13050_Content_13 = {
    Text = "Ban đầu, tôi và phụ vương đều tưởng là phù thủy nước láng giềng giáng xuống lời nguyền, nhưng… chẳng bao lâu họ cũng truyền đến tin dịch bệnh hoành hành."
  },
  AvgDialog_13050_Content_14 = {
    Text = "Ngay cả tôi cũng…… khụ, khụ khụ……"
  },
  AvgDialog_13050_Content_15 = {
    Text = "Giữa lúc nói chuyện, tiếng ho vang lên sau cánh cửa, xé lòng xé ruột."
  },
  AvgDialog_13050_Content_16 = {
    Text = "Công chúa, Ngài đừng nói nữa, xin Ngài hãy về giường trước đã."
  },
  AvgDialog_13050_Content_17 = {
    Text = "Xào xạc……"
  },
  AvgDialog_13050_Content_18 = {
    Text = "Thị quan! Thị quan mau quay lại giúp! Công chúa——"
  },
  AvgDialog_13050_Content_19 = {Text = "Ugh!"},
  AvgDialog_13050_Content_2 = {
    Text = "Chiến đấu với kẻ thù vô hình thì đây là lần đầu tiên, đợi mọi chuyện kết thúc, chúng ta có thể tìm một thi nhân hát rong viết lại câu chuyện này, viết thành một bài ca thì sao?"
  },
  AvgDialog_13050_Content_20 = {
    Text = "Tiếng xương gãy vang lên giòn tan, thứ gì đó cứng rắn xé toạc các mô cơ liên kết chặt chẽ, chất lỏng đỏ tươi bắn tung tóe theo."
  },
  AvgDialog_13050_Content_21 = {
    Text = "Cái... gì...?"
  },
  AvgDialog_13050_Content_22 = {
    Text = "Hiệp sĩ Fernando!!!"
  },
  AvgDialog_13050_Content_23 = {
    Text = "Kỵ sĩ hộ vệ ho một tiếng, máu tươi lẫn với các mảnh thịt trào ra từ cổ họng. Anh trợn mắt kinh ngạc, vừa hoang mang vừa sợ hãi."
  },
  AvgDialog_13050_Content_3 = {
    Text = "Tên tôi đã nghĩ sẵn rồi, gọi là\"Đôi mắt của Danske, Thanh kiếm của Fernando\"!"
  },
  AvgDialog_13050_Content_4 = {
    Text = "Ogier bị nhắc tên liền ngẩng đầu nhìn kỵ sĩ hộ vệ, tay anh dính không ít dịch dung thực, muốn lau tay nhưng lại cảm thấy tiến thoái lưỡng nan, vô cùng lúng túng."
  },
  AvgDialog_13050_Content_5 = {
    Text = "Phải viết tên tôi vào bài ca sao? Ogier đâu có xứng đáng……"
  },
  AvgDialog_13050_Content_6 = {
    Text = "Hehe… Tôi và thị quan lẽ nào không được ghi tên sao?"
  },
  AvgDialog_13050_Content_7 = {
    Text = "Tất nhiên! Tất nhiên được! Tên của Ngài sẽ được viết ở câu đầu tiên của bài ca này!"
  },
  AvgDialog_13050_Content_8 = {
    Text = "Xào xạc……"
  },
  AvgDialog_13050_Content_9 = {
    Text = "@1Tổ khúc Công chúa……thế nào? Tôi có thiên phú làm thi nhân không?"
  },
  AvgDialog_13051_Content_1 = {
    Text = "Chuyện gì… chuyện gì đã xảy ra?"
  },
  AvgDialog_13051_Content_10 = {
    Text = "Hiệp sĩ Fernando…… tôi nhớ anh ấy là con trai duy nhất trong gia đình."
  },
  AvgDialog_13051_Content_11 = {
    Text = "Nếu tôi cảnh giác hơn một chút……"
  },
  AvgDialog_13051_Content_12 = {
    Text = "Đừng lấy cái chết của anh ấy để tự trách mình, những @1 quái vật đó xuất quỷ nhập thần, chúng ta đã cố hết sức rồi."
  },
  AvgDialog_13051_Content_13 = {
    Text = "Ogier lắc đầu, lời an ủi nhạt nhẽo của ngươi rõ ràng không thể an ủi được anh ta.\nLúc này, từ phía sau vọng lại tiếng gõ cửa nhẹ."
  },
  AvgDialog_13051_Content_14 = {
    Text = "Thị quan, ngươi hãy dẫn Ogier đi đi."
  },
  AvgDialog_13051_Content_15 = {Text = "Tại sao!"},
  AvgDialog_13051_Content_16 = {
    Text = "Ngài, ngài không cần thần nữa sao? Thần biết mình đã không cứu được ngài Fernando, nhưng……"
  },
  AvgDialog_13051_Content_17 = {
    Text = "Dịch bệnh mang đến tật bệnh, chiến tranh, đau khổ…… ngươi ở lại đây, chẳng qua là chuẩn bị thêm một bữa tiệc cho nó mà thôi."
  },
  AvgDialog_13051_Content_18 = {
    Text = "Giọng cô run rẩy, nhưng vẫn nói những lời đùa nghịch. Trước cái chết có thể ập đến bất cứ lúc nào, cô không hề lộ ra chút sợ hãi nào."
  },
  AvgDialog_13051_Content_19 = {
    Text = "Ta nghĩ… Các hạ Fernando cũng không muốn gặp lại ngươi sớm như vậy đâu, phải không?"
  },
  AvgDialog_13051_Content_2 = {
    Text = "Từ bên trong cửa vọng ra tiếng bước chân hư ảo, rồi then cửa trượt mở—"
  },
  AvgDialog_13051_Content_20 = {
    Text = "Nhưng… đây là……trách nhiệm của tôi……"
  },
  AvgDialog_13051_Content_21 = {
    Text = "Bây giờ…chỉ còn tôi…tôi sẽ kế thừa ý chí của các hạ Fernando……tôi phải kế thừa……"
  },
  AvgDialog_13051_Content_22 = {
    Text = "Từ bên trong cánh cửa vọng ra một tiếng thở dài bất lực, hồi lâu sau, công chúa cất tiếng nói với ngươi."
  },
  AvgDialog_13051_Content_23 = {
    Text = "Thị quan, hãy hứa với ta…khi giọng nói của ta hoàn toàn biến mất, nhất định phải đưa Augier đi, dù có phải đánh ngất cậu ấy, được không?"
  },
  AvgDialog_13051_Content_24 = {
    Text = "……Tuân theo nguyện vọng của người."
  },
  AvgDialog_13051_Content_25 = {
    Text = "Augier ôm chặt vũ khí, hai tay trắng bệch vì dùng sức, như thể cây thương trong lòng chính là người thân sống chết chưa rõ, là công chúa đang hấp hối, là Fernando đã mãi mãi ra đi."
  },
  AvgDialog_13051_Content_26 = {
    Text = "Cậu chằm chằm nhìn cổng hành cung, nhưng ý thức không biết từ lúc nào đã phiêu dạt đến nơi xa. Ngay cả khi cổng lớn bị đập mạnh, phát ra tiếng vang dữ dội, cũng không thể khiến cậu tỉnh lại."
  },
  AvgDialog_13051_Content_27 = {
    Text = "Augier? Augier?"
  },
  AvgDialog_13051_Content_28 = {
    Text = "Có người đến rồi."
  },
  AvgDialog_13051_Content_29 = {
    Text = "Có người……đến rồi? Các kỵ sĩ đã quay lại rồi sao!?"
  },
  AvgDialog_13051_Content_3 = {
    Text = "Đừng ra ngoài!"
  },
  AvgDialog_13051_Content_30 = {
    Text = "Cổng lớn bị húc tung, nhưng lá cờ tung bay trong gió không phải là màu sắc mà các ngươi mong đợi."
  },
  AvgDialog_13051_Content_4 = {
    Text = "Xin công chúa… đừng ra ngoài……"
  },
  AvgDialog_13051_Content_5 = {
    Text = "Ogier gắng sức đẩy thi thể kỵ sĩ Fernando ra khỏi cửa, rồi giật tấm rèm xuống, phủ lên vũng máu sắp chảy vào phòng qua khe cửa."
  },
  AvgDialog_13051_Content_6 = {
    Text = "Gai nhọn của dị biến thể xuyên thủng giáp ngực và da thịt, lồng ngực nát bét như vừa trải qua một vụ nổ, kỵ sĩ Fernando đã tắt thở trong đau đớn từ lâu."
  },
  AvgDialog_13051_Content_7 = {
    Text = "...Được."
  },
  AvgDialog_13051_Content_8 = {
    Text = "Phiền các ngươi, hãy cố gắng khâm liệm cho anh ấy."
  },
  AvgDialog_13051_Content_9 = {
    Text = "Ngươi và Ogier nhìn nhau, lặng lẽ dùng tấm thảm cuộn thi thể kỵ sĩ lại, rồi ngồi xuống sàn trước cửa phòng ngủ. Đau thương và lo âu lan tỏa trong không khí."
  },
  AvgDialog_13052_Content_1 = {
    Text = "Chuyện gì vậy? Địch ở đâu?"
  },
  AvgDialog_13052_Content_10 = {
    Text = "Thưa Thị quan các hạ, ngài cũng nhìn thấy sao?"
  },
  AvgDialog_13052_Content_11 = {
    Text = "Cậu gửi cho cậu ấy một ánh mắt trấn an, rồi tiếp tục giao thiệp với kỵ sĩ."
  },
  AvgDialog_13052_Content_12 = {
    Text = "Augier chưa bao giờ là đứa trẻ hay gây rối vô cớ, ngài là người cùng huấn luyện với cậu ấy, ngài hiểu rõ nhất, phải không?"
  },
  AvgDialog_13052_Content_13 = {
    Text = "Dù cậu nói vậy, nhưng tôi thực sự chẳng thấy gì……"
  },
  AvgDialog_13052_Content_14 = {
    Text = "…Khoan đã, thưa các hạ Fernando."
  },
  AvgDialog_13052_Content_15 = {
    Text = "Từ phía phòng ngủ vọng đến tiếng gõ cửa, giọng nữ yếu ớt ấy lại tập hợp tất cả mọi người trở về trước cửa."
  },
  AvgDialog_13052_Content_16 = {
    Text = "Họ nói không sai… Đó chính là kẻ thù vô hình đã gieo rắc bệnh dịch."
  },
  AvgDialog_13052_Content_17 = {
    Text = "Nếu công chúa đã nói vậy thì……"
  },
  AvgDialog_13052_Content_18 = {
    Text = "Kỵ sĩ hộ vệ nghiến răng, cầm vũ khí đứng bên cạnh các bạn."
  },
  AvgDialog_13052_Content_19 = {
    Text = "Xin hãy cho tôi biết phương vị của kẻ thù, tôi sẽ hết sức hỗ trợ chiến đấu!"
  },
  AvgDialog_13052_Content_2 = {
    Text = "Kỵ sĩ hộ vệ cũng chạy xuống bậc thang đến bên các bạn, đầy vẻ hoang mang."
  },
  AvgDialog_13052_Content_3 = {
    Text = "Bây giờ không phải lúc đùa giỡn, tuyệt đối không được lơ là cảnh giác."
  },
  AvgDialog_13052_Content_4 = {
    Text = "Tôi không đùa giỡn gì cả! Ngài, ngài không nhìn thấy sao?!"
  },
  AvgDialog_13052_Content_5 = {
    Text = "Augier lo lắng phân trần, nhưng kỵ sĩ hộ vệ vẫn nửa tin nửa ngờ."
  },
  AvgDialog_13052_Content_6 = {
    Text = "Không thể trách anh ta được, bởi kẻ địch mà cậu và Augier đánh bại — là dị biến thể hoàn toàn phái sinh từ Dung Thực."
  },
  AvgDialog_13052_Content_7 = {
    Text = "Người có thể quan sát hiện tượng Dung Thực bằng mắt thường, vạn người chưa chắc có một.\nAugier chính là một trong những người may mắn bất hạnh ấy."
  },
  AvgDialog_13052_Content_8 = {
    Text = "Xin hãy tin chúng tôi"
  },
  AvgDialog_13052_Content_9 = {
    Text = "Xin hãy tin chúng tôi, tin vào phẩm hạnh của Augier."
  },
  AvgDialog_13053_Content_1 = {
    Text = "Khúc tàn người tản"
  },
  AvgDialog_13053_Content_11 = {
    Text = "Cứ để Ogier cùng ở lại canh giữ hành cung đi.\nCậu ấy là kỵ sĩ hộ vệ được Đại Công tước đích thân chỉ định, danh chính ngôn thuận, phải không?"
  },
  AvgDialog_13053_Content_12 = {
    Text = "Kỵ sĩ trực ban không tìm được lý do nào khác để từ chối, ông gật đầu đồng ý, rồi các ngươi cùng nhau trở về hành cung."
  },
  AvgDialog_13053_Content_13 = {
    Text = "Hành cung trống không một bóng người, ngay cả cô thị nữ hay làm ồn cũng đã rời đi.\nNgoài ba người các ngươi ra, hành cung chỉ còn lại mỗi mình công chúa."
  },
  AvgDialog_13053_Content_14 = {
    Text = "Ngươi gõ cửa phòng ngủ lộng lẫy vàng son, tiếng gõ vang vọng trong đại sảnh tĩnh lặng, ngột ngạt đến đáng sợ."
  },
  AvgDialog_13053_Content_15 = {
    Text = "Công chúa? Người có ổn không?"
  },
  AvgDialog_13053_Content_16 = {
    Text = "Trong phòng không có hồi đáp, ngươi đợi một lát rồi mới gõ cửa lần nữa."
  },
  AvgDialog_13053_Content_17 = {
    Text = "Công chúa, tôi cùng kỵ sĩ hộ vệ, và cả Ogier đều ở đây."
  },
  AvgDialog_13053_Content_18 = {
    Text = "Xuyên qua cánh cửa gỗ dày nặng, vọng ra tiếng vải vóc cọ xát, có người đang gắng gượng ngồi dậy từ trên giường."
  },
  AvgDialog_13053_Content_19 = {
    Text = "……Thật vớ vẩn."
  },
  AvgDialog_13053_Content_2 = {
    Text = "\"Giấc mộng\""
  },
  AvgDialog_13053_Content_20 = {
    Text = "Các ngươi… đi đi, cùng những người khác rời đi, không cần phải canh giữ một cái xác."
  },
  AvgDialog_13053_Content_21 = {
    Text = "Hơi thở thiếu nữ hư phù, giọng nói nhỏ như muỗi vo. Dường như chỉ việc đáp lời ngươi đã vắt kiệt toàn bộ sức lực của nàng."
  },
  AvgDialog_13053_Content_22 = {
    Text = "Dịch bệnh lan tràn vô trật tự trong công quốc, vương công quý tộc cũng không thoát khỏi. Công chúa đã nhiễm bệnh từ trước khi chiến tranh bắt đầu, đến nay, nàng thậm chí không còn sức rời khỏi giường."
  },
  AvgDialog_13053_Content_23 = {
    Text = "Ngự y cung đình còn nói thẳng rằng, công chúa đã không thể chịu nổi sự vất vả của việc di chuyển khỏi hành cung, chỉ một chút xóc nảy nhẹ cũng có thể khiến nàng mất mạng."
  },
  AvgDialog_13053_Content_24 = {
    Text = "Công chúa……"
  },
  AvgDialog_13053_Content_25 = {
    Text = "Dù Người có nói gì, thần cũng sẽ không rời khỏi nơi đây. Xin hãy cho phép thần được hộ vệ, để thần…\ntận trách phận kỵ sĩ."
  },
  AvgDialog_13053_Content_27 = {
    Text = "……Đừng đến quá gần phòng ta. Dịch bệnh đã không thể cứu vãn, ít nhất… đừng để các ngươi cũng bị lây nhiễm."
  },
  AvgDialog_13053_Content_28 = {
    Text = "Mỗi khi đồng hồ nước chảy hết một lần, hãy đến nói chuyện với ta, được không?\nKhi nào ta không còn đáp lời nữa… các ngươi hãy rời đi."
  },
  AvgDialog_13053_Content_3 = {
    Text = "Âm mưu lẩn khuất trong bóng tối, châm ngòi dây dẫn mà dịch bệnh đã chôn sẵn, chiến tranh bùng nổ chỉ trong một đêm."
  },
  AvgDialog_13053_Content_4 = {
    Text = "<Yellow:Ôn dịch> vô phương cứu chữa đã lan tràn khắp công quốc từ lâu, binh sĩ thủ thành bệnh tật đầy mình, không đủ sức chống lại thiết kỵ của kẻ xâm lược."
  },
  AvgDialog_13053_Content_5 = {
    Text = "Ngay cả kỵ sĩ hoàng tộc cũng đã theo lệnh Đại Công tước tiến ra ngoài hào thành, gia nhập phòng tuyến cuối cùng bảo vệ đô thành."
  },
  AvgDialog_13053_Content_6 = {
    Text = "Ogier, sao cậu vẫn còn ở đây?"
  },
  AvgDialog_13053_Content_7 = {
    Text = "Tôi… tôi muốn cùng ngài thực hiện nhiệm vụ hộ vệ."
  },
  AvgDialog_13053_Content_8 = {
    Text = "Cậu còn quá trẻ, chiến tranh… tạm thời chưa đến lượt cậu tham gia.\nQuay về đi, cùng gia đình đến nơi an toàn."
  },
  AvgDialog_13053_Content_9 = {
    Text = "Nhà của Ogier, trang viên Danske… chắc nằm ngoài phòng tuyến rồi nhỉ?"
  },
  AvgDialog_13054_Content_1 = {
    Text = "Giấc mơ, hay lý tưởng"
  },
  AvgDialog_13054_Content_10 = {
    Text = "Thị quan, phiền ngươi đi một chuyến giúp ta."
  },
  AvgDialog_13054_Content_100 = {
    Text = "Những lời chúng ta vừa nói…… Ngài thật sự sẽ không kể cho công chúa chứ?"
  },
  AvgDialog_13054_Content_101 = {
    Text = "Sao? Ta không có chút uy tín nào trong mắt cậu à?"
  },
  AvgDialog_13054_Content_102 = {
    Text = "Sao có thể! Tôi tuyệt đối không có ý đó……!"
  },
  AvgDialog_13054_Content_103 = {
    Text = "Vậy thì, ta sẽ dùng chuyện hôm nay để uy hiếp cậu nhé."
  },
  AvgDialog_13054_Content_104 = {Text = "Uy hiếp?"},
  AvgDialog_13054_Content_105 = {
    Text = "Ngươi quỳ gối ngồi xuống trước mặt Augier, tầm mắt ngang bằng với chú chó con đang hoảng hốt, rồi chìa tay về phía cậu ấy."
  },
  AvgDialog_13054_Content_106 = {
    Text = "Cuộc trò chuyện hôm nay sẽ mãi mãi thối rữa trong bụng chúng ta, nhưng để đổi lại việc ta giữ bí mật, ngươi phải hứa với ta một điều."
  },
  AvgDialog_13054_Content_107 = {
    Text = "Thời đại này không có thói quen móc ngón tay thề thốt, nhưng Ogier vẫn ngơ ngác móc lấy ngón út mà ngươi chìa ra."
  },
  AvgDialog_13054_Content_108 = {
    Text = "Chỉ cần là điều tôi có thể làm được……"
  },
  AvgDialog_13054_Content_109 = {
    Text = "Vậy thì, ta sẽ giữ lại quyền ước nguyện một lần. Tương lai nào đó, biết đâu ta sẽ đến tìm ngươi để thực hiện, lúc đó đừng có quên đấy nhé, \"Kỵ sĩ các hạ\"."
  },
  AvgDialog_13054_Content_11 = {
    Text = "Nếu là trường hợp sau, liệu đánh thức chủ nhân giấc mộng có thể thoát khỏi nơi này không?"
  },
  AvgDialog_13054_Content_12 = {
    Text = "Này! Thị quan các hạ? Tỉnh lại đi!"
  },
  AvgDialog_13054_Content_13 = {
    Text = "Tư duy của bạn theo những manh mối mà trôi xa dần, khi kế hoạch \"đánh thức chủ nhân giấc mộng\" đang dần thành hình, móng tay ai đó bấm mạnh vào cánh tay bạn, cơn đau khiến bạn bừng tỉnh ngay lập tức."
  },
  AvgDialog_13054_Content_14 = {
    Text = "Xít— Đau quá!"
  },
  AvgDialog_13054_Content_15 = {
    Text = "Hóa ra ngươi vẫn biết đau! Chúng ta gọi nửa ngày trời, ngươi như xác chết không có chút phản ứng nào, tai có vấn đề gì à?"
  },
  AvgDialog_13054_Content_16 = {
    Text = "Dạo này ngươi hay thẫn thờ, chắc là quá mệt rồi, có muốn về phong địa gia tộc nghỉ ngơi một thời gian không? Đúng lúc các ngươi cũng lâu rồi chưa có kỳ nghỉ."
  },
  AvgDialog_13054_Content_17 = {
    Text = "Đừng— Thực sự xin lỗi, thần chỉ là có chút tâm sự……"
  },
  AvgDialog_13054_Content_18 = {
    Text = "Chìa khóa thoát khỏi \"mộng cảnh\" chắc chắn nằm ở Ogier, dù rất tò mò thế giới xa rời trung tâm giấc mộng sẽ trông như thế nào, nhưng vào lúc này, bạn không thể rời đi quá xa."
  },
  AvgDialog_13054_Content_19 = {
    Text = "Tâm sự? Là gì là gì? Có phải có người thích rồi đang phiền não vì chuyện đó không?"
  },
  AvgDialog_13054_Content_2 = {
    Text = "\"Mộng cảnh\"\nHành cung Công chúa"
  },
  AvgDialog_13054_Content_20 = {
    Text = "Có phải đang buồn vì đối phương không thích ngươi? Công chúa— hãy bói một quẻ cho thị quan các hạ của chúng ta đi, hay là luôn tặng {Male=anh ấy,Female=cô ấy} một liều thuốc tình yêu—"
  },
  AvgDialog_13054_Content_21 = {
    Text = "Đừng đùa nữa, làm sao có thể dùng ma pháp và thuốc để duy trì tình cảm được chứ?"
  },
  AvgDialog_13054_Content_22 = {
    Text = "Công chúa mỉm cười lướt qua chủ đề mà thị nữ khơi ra, rồi vẫy tay với bạn."
  },
  AvgDialog_13054_Content_23 = {
    Text = "Ogier đang tập luyện với đoàn kỵ sĩ, ngươi thay ta đi xem thế nào, đừng để đứa nhỏ đó bị thương."
  },
  AvgDialog_13054_Content_24 = {
    Text = "Tuân lệnh!"
  },
  AvgDialog_13054_Content_25 = {
    Text = "Đúng lúc buồn ngủ thì công chúa gửi gối đến, cho bạn lý do chính đáng để tiếp cận Ogier."
  },
  AvgDialog_13054_Content_26 = {
    Text = "Nhưng nếu thực sự cần thuốc thì vẫn có thể đến tìm ta lấy đấy nhé."
  },
  AvgDialog_13054_Content_27 = {
    Text = "\"Mộng Cảnh\"\nSân tập đoàn kỵ sĩ"
  },
  AvgDialog_13054_Content_28 = {
    Text = "Dưới sự chỉ dẫn của các thị tùng khác, bạn đi qua lâu đài và khu vườn như mê cung, tìm đến sân tập."
  },
  AvgDialog_13054_Content_29 = {
    Text = "Tiếng binh khí va chạm giòn giã cùng tiếng cổ vũ vang lên không ngớt, rõ ràng có người đang đối luyện dưới nắng gắt."
  },
  AvgDialog_13054_Content_3 = {
    Text = "Sau lần thứ ba cố gắng tỉnh dậy, nhưng chỉ khiến cảnh tượng trước mắt thay đổi vô cớ, cuối cùng bạn cũng chấp nhận sự thật rằng mình đã bị mắc kẹt trong ký ức của Ogier."
  },
  AvgDialog_13054_Content_30 = {
    Text = "——Chỉ là bạn không ngờ rằng, một trong hai bên đối luyện chính là Ogier."
  },
  AvgDialog_13054_Content_32 = {Text = "Ugh……!"},
  AvgDialog_13054_Content_33 = {
    Text = "Trước sự chênh lệch sức mạnh tuyệt đối, sự kiên trì và tín niệm chẳng có tác dụng gì. Kỵ sĩ trưởng thành chưa dùng hết sức, chấn động kim loại đã khiến hổ khẩu của Ogier mất lực."
  },
  AvgDialog_13054_Content_34 = {
    Text = "Trường thương bị đánh rơi, thiếu niên mồ hôi đầm đìa, thở hổn hển quỳ xuống nền đất cát sỏi thô ráp."
  },
  AvgDialog_13054_Content_35 = {
    Text = "Nhóc, về nghỉ đi đã. Luyện tiếp nữa, tay cậu sẽ gãy xương đấy."
  },
  AvgDialog_13054_Content_36 = {
    Text = "Đúng vậy, cậu còn quá nhỏ.\nQua vài năm nữa hãy đến tập luyện, bây giờ cậu còn chưa cầm nổi vũ khí."
  },
  AvgDialog_13054_Content_37 = {Text = "Không.."},
  AvgDialog_13054_Content_38 = {
    Text = "Ogier run rẩy toàn thân, cúi người nhặt lấy trường thương rơi xuống, gắng sức điều chỉnh tư thế chuẩn bị, hướng mũi thương về phía kỵ sĩ đối luyện,"
  },
  AvgDialog_13054_Content_39 = {
    Text = "Ta vẫn… có thể kiên trì!"
  },
  AvgDialog_13054_Content_4 = {
    Text = "Bạn đứng ở một góc tẩm điện của công chúa, giả vờ làm người lắng nghe, ngoan ngoãn đóng vai thị quan."
  },
  AvgDialog_13054_Content_40 = {
    Text = "Thằng nhóc này thật là…… bướng bỉnh quá."
  },
  AvgDialog_13054_Content_41 = {
    Text = "Khuôn mặt thiếu niên đỏ bừng vì kiệt sức và thiếu oxy, đối mặt với ý chí ngoan cường như vậy, người vốn định dùng huấn luyện để khiến Ogier biết khó mà lui cuối cùng cũng lên tiếng."
  },
  AvgDialog_13054_Content_42 = {
    Text = "Cũng khá đấy chứ, bọn bên ngoài đang nhòm ngó công quốc, những đứa trẻ có ý chí kiên định như thiếu gia Danske, càng nhiều càng tốt."
  },
  AvgDialog_13054_Content_43 = {
    Text = "Vậy ta sẽ chiến thật đấy nhé?"
  },
  AvgDialog_13054_Content_44 = {
    Text = "Đừng có không biết nặng nhẹ! Luyện cho thằng nhỏ này ngã gục rồi, ngươi định ăn nói thế nào với Đại Công và Công chúa?"
  },
  AvgDialog_13054_Content_45 = {
    Text = "Bắt đầu từ thể lực cơ bản trước, trông chừng cho kỹ, đừng để cậu ta bị vũ khí làm bị thương."
  },
  AvgDialog_13054_Content_46 = {
    Text = "Lời của đoàn trưởng đã thắp lên ngọn lửa trong Ogier, đôi mắt thiếu niên bỗng sáng rực lên, niềm hưng phấn tràn ngập trên gương mặt."
  },
  AvgDialog_13054_Content_47 = {
    Text = "Ngài đồng ý cho tôi gia nhập kỵ sĩ đoàn rồi sao?!"
  },
  AvgDialog_13054_Content_48 = {
    Text = "Cho dù không có câu nói đùa của Đại Công, chỉ riêng ý chí này thôi, làm một kỵ sĩ tập sự cũng đủ tư cách rồi."
  },
  AvgDialog_13054_Content_49 = {
    Text = "Nhìn những vết xước và vệt máu khắp người thiếu niên, đoàn trưởng ngừng lại một chút, trong lòng không nỡ."
  },
  AvgDialog_13054_Content_5 = {
    Text = "Công chúa, công chúa! Nghe nói cậu thiếu gia nhà Danske lại đến đoàn kỵ sĩ trình diện rồi, đây là ngày thứ ba rồi!"
  },
  AvgDialog_13054_Content_50 = {
    Text = "Hôm nay về nghỉ trước đi, từ ngày mai ta sẽ lên kế hoạch huấn luyện riêng cho ngươi — còn các ngươi nữa! Đừng có đứng xem nữa, mỗi người thêm hai vòng luyện tập mang tạ!"
  },
  AvgDialog_13054_Content_51 = {
    Text = "Tha cho chúng tôi đi đoàn trưởng ơi——"
  },
  AvgDialog_13054_Content_52 = {
    Text = "Đoàn trưởng chưa dứt lời, nhân lúc bầu không khí hiếm hoi nhẹ nhàng, từ trong đám đông vang lên tiếng phản kháng nhỏ nhoi, những kỵ sĩ trẻ tuổi giải tỏa áp lực bằng cách này."
  },
  AvgDialog_13054_Content_53 = {Text = "Ba vòng!"},
  AvgDialog_13054_Content_54 = {
    Text = "Giữa tiếng than vãn nổi lên khắp nơi, Ogier cuối cùng cũng buông bỏ sự căng thẳng, ngã phịch xuống đất."
  },
  AvgDialog_13054_Content_55 = {
    Text = "Tuyệt quá… cuối cùng thì……"
  },
  AvgDialog_13054_Content_56 = {
    Text = "Ogier, chúng ta có thể nói chuyện một chút được không?"
  },
  AvgDialog_13054_Content_57 = {
    Text = "Ngài là… Thị quan các hạ! Để ngài nhìn thấy bộ dạng xấu hổ thế này, tôi……"
  },
  AvgDialog_13054_Content_58 = {
    Text = "Ogier lập tức ngồi thẳng nghiêm chỉnh, đầu gối bị xước cọ xát với nền cát trong lúc cử động, cơn đau khiến biểu cảm căng thẳng của cậu trở nên méo mó."
  },
  AvgDialog_13054_Content_59 = {
    Text = "Cậu xua tay với cậu ta, lấy ra lọ thuốc thương mà công chúa không biết lúc nào đã nhét vào túi áo."
  },
  AvgDialog_13054_Content_6 = {
    Text = "Cậu ấy lại tin lời cha mình thật sao… Cậu ấy còn nhỏ tuổi thế, làm sao chịu nổi huấn luyện của đoàn kỵ sĩ?"
  },
  AvgDialog_13054_Content_60 = {
    Text = "Ơ… không đau sao? Đây không phải là thuốc thương à?"
  },
  AvgDialog_13054_Content_61 = {
    Text = "Đây là thuốc do công chúa đích thân pha chế, chắc là đã qua xử lý đặc biệt rồi."
  },
  AvgDialog_13054_Content_62 = {
    Text = "Vị công chúa mà \"cậu\" phụng sự là một thiếu nữ bí ẩn như câu đố, nàng ít khi ra ngoài, nhưng lại có sự hiểu biết và thiên phú độc đáo về dược liệu. Nếu ở thời đại mà cậu sống, nàng sẽ là một dược sư danh tiếng lừng lẫy."
  },
  AvgDialog_13054_Content_63 = {
    Text = "Đáng tiếc trong những tháng năm thất lạc hàng trăm năm trước này, thiên phú của nàng không được thế tục thấu hiểu, cậu đã không chỉ một lần nghe thấy những thị tùng khác lén gọi nàng là \"phù thủy\" sau lưng."
  },
  AvgDialog_13054_Content_64 = {
    Text = "Thuốc của công chúa?! Quý giá quá, sao có thể dùng cho tôi được——Xít!"
  },
  AvgDialog_13054_Content_65 = {
    Text = "Đừng loạn động, muốn phí hoài lòng nhân từ của công chúa sao.\nCậu ngồi xuống trước, để ta xử lý vết thương đã."
  },
  AvgDialog_13054_Content_66 = {
    Text = "Sợ lãng phí thuốc quý, Ogier cuối cùng cũng ngoan ngoãn ngồi xuống.\nNhững người khác trong đội kỵ sĩ cũng lần lượt rời khỏi sân tập, đây là cơ hội hiếm có."
  },
  AvgDialog_13054_Content_67 = {
    Text = "Ogier, cậu có cảm nhận được mình đang nằm mơ không?"
  },
  AvgDialog_13054_Content_68 = {
    Text = "Đúng vậy, giống như đang mơ vậy……"
  },
  AvgDialog_13054_Content_69 = {
    Text = "Thiếu niên đã hiểu lời bạn theo nghĩa phù hợp nhất với tình huống hiện tại, cậu nhắm mắt cảm thán, lời nói tràn đầy mãn nguyện và khao khát."
  },
  AvgDialog_13054_Content_7 = {
    Text = "Không… không đúng……có lẽ còn khả năng khác."
  },
  AvgDialog_13054_Content_70 = {
    Text = "Được triều kiến, được chọn, rồi lại được các kỵ sĩ công nhận……Thật sự giống như đang mơ vậy."
  },
  AvgDialog_13054_Content_71 = {
    Text = "<LightGray:（Có nên nói thẳng với cậu ấy đây là giấc mơ không? Nhưng bản chất của nơi này vẫn chưa rõ, rốt cuộc là ký ức hay mộng cảnh……）>"
  },
  AvgDialog_13054_Content_72 = {
    Text = "Sự do dự của bạn đã thu hút sự chú ý của Ogier, cậu bỗng trở nên có phần bối rối, hai tay bất an vò vạt áo."
  },
  AvgDialog_13054_Content_73 = {
    Text = "Thưa ngài thị quan, có phải…công chúa không hài lòng với tôi sao?"
  },
  AvgDialog_13054_Content_75 = {
    Text = "Ogier là con nhà quý tộc, rõ ràng có thể sống cả đời sung túc, tại sao nhất định phải trở thành kỵ sĩ?"
  },
  AvgDialog_13054_Content_76 = {
    Text = "Bởi vì…bởi vì……"
  },
  AvgDialog_13054_Content_77 = {
    Text = "Giọng nói của Ogier vì xấu hổ mà càng lúc càng nhỏ, đầu cũng càng cúi càng thấp. Câu trả lời rõ ràng khiến cậu cảm thấy khó nói ra miệng."
  },
  AvgDialog_13054_Content_78 = {
    Text = "Ta thề, cuộc trò chuyện giữa chúng ta sẽ không có người thứ ba nào biết."
  },
  AvgDialog_13054_Content_79 = {
    Text = "Bởi vì…cha tôi cũng bị bệnh rồi. Giống như bà Merinte ở nhà bếp, anh Pedro người làm vườn vậy……"
  },
  AvgDialog_13054_Content_8 = {
    Text = "Nghe thị nữ mô tả, Ogier đang được huấn luyện tại đoàn kỵ sĩ. Vì Ogier không tham gia đoạn đối thoại này, nên giả thuyết đây là \"ký ức của Ogier\" không thể đứng vững được."
  },
  AvgDialog_13054_Content_80 = {
    Text = "Còn rất nhiều rất nhiều người khác nữa, mọi người đều mắc cùng một căn bệnh."
  },
  AvgDialog_13054_Content_81 = {
    Text = "Cha đã không thể rời khỏi giường nữa, mà tôi vẫn chưa trưởng thành…Là đứa con duy nhất của cha, tôi……"
  },
  AvgDialog_13054_Content_82 = {
    Text = "Nếu cha lỡ qua đời, mọi người trong trang viên đều sẽ bị giải tán.\nMọi người vẫn còn đang bệnh…hoàn toàn không có nơi nào để đi."
  },
  AvgDialog_13054_Content_83 = {
    Text = "Tôi phải…tôi phải chịu trách nhiệm cho mọi người……Chỉ có trở thành kỵ sĩ, được Đại Công tước che chở……"
  },
  AvgDialog_13054_Content_84 = {
    Text = "Nói đến đây, sắc mặt Ogier đã trắng bệch. Cậu lo lắng bất an nhìn bạn, như thể sợ bạn chỉ trích \"động cơ không thuần khiết\" của cậu, sợ bạn thay mặt công chúa giáng tội cho cậu."
  },
  AvgDialog_13054_Content_85 = {
    Text = "Sự non nớt tương tự, ý chí kiên cường như đúc từ một khuôn.\nCậu ấy chính là Augier trong nhận thức của ngươi, không còn nghi ngờ gì nữa."
  },
  AvgDialog_13054_Content_86 = {
    Text = "Xin lỗi, thưa ngài Thị quan…… Nếu, nếu ngài muốn công chúa thay thế tôi…… tôi, tôi cũng không hề oán trách……"
  },
  AvgDialog_13054_Content_87 = {
    Text = "Vào đêm Đại Công tuyển chọn cậu, cậu đã lấy danh dự gia tộc thề trước mặt tất cả tân khách, đúng không?"
  },
  AvgDialog_13054_Content_88 = {
    Text = "Thề sẽ lấy sinh mạng để thực hiện trách nhiệm của kỵ sĩ…… Khi đọc lời thề cùng những người khác, cậu có thật lòng không?"
  },
  AvgDialog_13054_Content_89 = {
    Text = "<Big:Tất nhiên rồi! Tôi không đùa đâu!>"
  },
  AvgDialog_13054_Content_9 = {
    Text = "Đây không đơn thuần là \"ký ức\". Có lẽ, bạn đã bước vào một đoạn lịch sử thực sự đã xảy ra, hoặc có lẽ, đây là một giấc mộng được tiềm thức bổ khuyết?"
  },
  AvgDialog_13054_Content_90 = {
    Text = "\"Ta sẽ mãi trung thành, mãi cống hiến\"…… Cha tôi cũng sẽ mong tôi làm như vậy."
  },
  AvgDialog_13054_Content_91 = {
    Text = "Được rồi, ta sẽ không kể những chuyện này cho công chúa đâu.\nĐừng quá lo lắng, nước mắt sắp rơi rồi kìa."
  },
  AvgDialog_13054_Content_92 = {
    Text = "Có, có sao?! Thất lễ quá!"
  },
  AvgDialog_13054_Content_93 = {
    Text = "Ugh… Ugh?! Mắt, mắt đau quá……"
  },
  AvgDialog_13054_Content_94 = {
    Text = "Augier cuống quýt dụi mắt, nhưng khăn tay đã dính đầy bụi đất trong lúc luyện tập, lần lau này càng khiến vẻ luống cuống của Augier thêm tệ hơn."
  },
  AvgDialog_13054_Content_95 = {
    Text = "Để ngài Thị quan nhìn thấy bộ dạng xấu hổ thế này, tôi thật là……"
  },
  AvgDialog_13054_Content_96 = {
    Text = "Không sao, ta còn từng thấy bộ dạng luống cuống hơn thế.\nChúng ta về hành cung trước để cậu rửa mặt chỉnh trang đã, không thể để cậu về nhà với bộ dạng này được."
  },
  AvgDialog_13054_Content_98 = {
    Text = "Thưa ngài Thị quan, tôi có thể xin ngài một việc được không?"
  },
  AvgDialog_13054_Content_99 = {
    Text = "Cậu cứ nói."
  },
  AvgDialog_13055_Content_1 = {
    Text = "Sợi tơ quá khứ"
  },
  AvgDialog_13055_Content_10 = {
    Text = "Liên kết lại"
  },
  AvgDialog_13055_Content_11 = {
    Text = "Thấy Ogier ngày càng gần với trạng thái mất kiểm soát, bạn quyết định không chờ đợi thêm nữa, nắm chặt lấy đôi tay đã phủ đầy bùn đen của cậu."
  },
  AvgDialog_13055_Content_12 = {
    Text = "Ngân Thược lóe sáng, bạn dẫn dắt xúc tu tinh thần xuyên qua bão linh tri, vượt qua từng lớp bóng tối, một lần nữa liên kết với Ogier."
  },
  AvgDialog_13055_Content_13 = {
    Text = "Kèm theo cơn đau nhẹ như bị điện giật, từng khung hình lướt qua trước mắt rồi biến mất trong tích tắc."
  },
  AvgDialog_13055_Content_14 = {
    Text = "Triệu chứng mất kiểm soát rút lui như thủy triều, trạng thái của Ogier dần ổn định, gương mặt non nớt lộ vẻ mệt mỏi."
  },
  AvgDialog_13055_Content_15 = {
    Text = "Chủ quân, lần này……ta đã kiên trì được bao lâu?"
  },
  AvgDialog_13055_Content_16 = {
    Text = "Đồng hồ bấm giờ chỉ mới đi được nửa vòng, trong tình trạng ngắt liên kết, Ogier không thể kiên trì lâu hơn lần tập trước."
  },
  AvgDialog_13055_Content_17 = {
    Text = "Ừm……30 giây, cộng thêm 200 mili giây."
  },
  AvgDialog_13055_Content_18 = {
    Text = "Sao, sao lại thế này……!"
  },
  AvgDialog_13055_Content_19 = {
    Text = "Giọng cậu bất an lo lắng, bởi lẽ lần <Yellow:huấn luyện đứt liên kết> này là ý tưởng do chính cậu chủ động đề xuất."
  },
  AvgDialog_13055_Content_2 = {
    Text = "Sân tập Đại học Misage\nHoàng hôn"
  },
  AvgDialog_13055_Content_20 = {
    Text = "Cậu vẫn canh cánh trong lòng về sự biến động trong ngày lễ trao chìa khóa, sợ rằng một ngày nào đó bản thân cũng sẽ mất kiểm soát, chĩa trường thương về phía các bạn — vì thế, cậu muốn nâng cao khả năng duy trì lý trí trong trạng thái không có liên kết."
  },
  AvgDialog_13055_Content_21 = {
    Text = "Chúa công, chúng ta luyện thêm một lần nữa đi!"
  },
  AvgDialog_13055_Content_22 = {
    Text = "Chúng ta đã luyện rất lâu rồi, tập luyện khi mệt mỏi sẽ phản tác dụng thôi."
  },
  AvgDialog_13055_Content_23 = {
    Text = "Ánh mắt Ogier lấp lánh, nhưng cuối cùng vẫn chùng xuống, giọng nói mang theo vài phần tự trách."
  },
  AvgDialog_13055_Content_24 = {
    Text = "Là ta không suy nghĩ chu toàn..."
  },
  AvgDialog_13055_Content_26 = {
    Text = "Ngày mai ta cũng không có nhiệm vụ điều tra, sau bữa trưa, không gặp không về."
  },
  AvgDialog_13055_Content_27 = {
    Text = "Chúa công!"
  },
  AvgDialog_13055_Content_28 = {
    Text = "Đối mặt với ánh mắt hào hứng rạng rỡ như chú cún con, ngươi kéo lê thân thể mệt mỏi không kém trở về ký túc xá."
  },
  AvgDialog_13055_Content_29 = {
    Text = "Một xác ướp đã tắm rửa qua loa nằm xuống chiếc giường êm ái, kèm theo lời cảm ơn thầm lặng dành cho con mắt chọn đồ giường của hậu cần Mythsage, ý thức dần trôi ra khỏi đầu..."
  },
  AvgDialog_13055_Content_3 = {
    Text = "Ngân Thược lấp lánh, bạn điều khiển sợi tơ bạc mảnh mai vô hình trong tâm trí, tách rời khỏi những điểm sáng lấp lánh."
  },
  AvgDialog_13055_Content_31 = {
    Text = "Trong bóng tối vang lên giai điệu du dương lạ lẫm, hòa cùng tiếng chạm ly bạc liên hồi, bầu không khí nhộn nhịp mà trang nhã tràn ngập giấc mơ."
  },
  AvgDialog_13055_Content_32 = {
    Text = "Ồn quá... ai thế... nửa đêm tổ chức yến tiệc trong khu ký túc..."
  },
  AvgDialog_13055_Content_33 = {
    Text = "Ngươi trở mình, duỗi tay mò tìm chiếc chăn bị đạp rơi xuống giường."
  },
  AvgDialog_13055_Content_34 = {
    Text = "Bàn tay chìm vào một vùng sương mù, nắm lấy một đám mây vũ tích chứa đầy điều chưa biết, xúc giác vừa thực vừa hư ảo."
  },
  AvgDialog_13055_Content_35 = {
    Text = "Ồ, hóa ra ngươi ở đây, ta vừa mới tìm ngươi đấy."
  },
  AvgDialog_13055_Content_36 = {
    Text = "Cái... gì...?"
  },
  AvgDialog_13055_Content_37 = {
    Text = "Chân ta lại cảm thấy không có sức rồi, phiền ngươi đến chỗ phụ vương, đưa kỵ sĩ của ta đến đây."
  },
  AvgDialog_13055_Content_38 = {
    Text = "Kỵ sĩ...?"
  },
  AvgDialog_13055_Content_39 = {
    Text = "Đứng ngẩn ra làm gì? Không nghe thấy lời công chúa sao?"
  },
  AvgDialog_13055_Content_4 = {Text = "Ugh……!"},
  AvgDialog_13055_Content_40 = {
    Text = "Người phụ nữ vỗ mạnh vào vai ngươi, bóng tối lùi đi, một địa điểm xa lạ hiện ra trước mắt."
  },
  AvgDialog_13055_Content_41 = {
    Text = "Đại sảnh hào hoa, đội nhạc đang tấu những bản tổ khúc cổ xưa ở phía xa, những món tráng miệng tinh xảo hấp dẫn, và những quý phu nhân đồng loạt nhìn về phía ngươi."
  },
  AvgDialog_13055_Content_42 = {
    Text = "Còn có cô thiếu nữ được họ vây quanh, nằm nghiêng trên chiếc ghế dài êm ái."
  },
  AvgDialog_13055_Content_43 = {
    Text = "Không có gì đáng ngại, đừng trách {Male=anh ấy,Female=cô ấy} quá. Để chuẩn bị một bữa tiệc hoàn hảo cho mọi người, thị quan của ta đã bận rộn cả đêm không nghỉ chân."
  },
  AvgDialog_13055_Content_44 = {
    Text = "Thiếu nữ được mọi người gọi là công chúa, có thể thấy địa vị cao quý, nhưng lúc này lại dịu dàng giải vây cho bạn."
  },
  AvgDialog_13055_Content_45 = {
    Text = "Hãy đi dẫn vị \"kỵ sĩ\" mà phụ vương sắc phong cho ta đến gặp mặt, sau đó hôm nay có thể về nghỉ ngơi rồi, được chứ?"
  },
  AvgDialog_13055_Content_46 = {
    Text = "Lượng lớn ký ức vụn vỡ ùa vào tâm trí, không liền mạch, cũng không trọn vẹn, nhưng đủ để bạn đóng vai thân phận của thể xác này — thị quan duy nhất của công chúa."
  },
  AvgDialog_13055_Content_47 = {
    Text = "……Cảm tạ ân huệ của Công chúa."
  },
  AvgDialog_13055_Content_48 = {
    Text = "Bản năng của cơ thể khiến bạn cúi chào nàng. Giữa những ánh mắt hoặc ghen tị hoặc khinh thường, bạn xuyên qua đám quý bà, bước về phía đại sảnh nơi đông người tụ tập hơn."
  },
  AvgDialog_13055_Content_49 = {
    Text = "Bạn cúi đầu nhìn bàn tay \"của mình\", màu da sẫm hơn vài phần so với làn da thường giấu trong găng tay của bạn, khắp nơi đều lưu lại những vết mờ nhạt, rõ ràng không phải người sống trong nhung lụa."
  },
  AvgDialog_13055_Content_5 = {
    Text = "Đừng ép bản thân, khi không chịu nổi nữa thì hãy liên kết với Hắc Trì!"
  },
  AvgDialog_13055_Content_50 = {
    Text = "Chiếc bình hoa kim loại hoa lệ đi ngang qua càng chứng thực phỏng đoán chẳng lành —"
  },
  AvgDialog_13055_Content_51 = {
    Text = "Bóng phản chiếu trên đó, không phải khuôn mặt của bạn."
  },
  AvgDialog_13055_Content_52 = {
    Text = "Thưa Thị quan các hạ! Ngài đại diện cho Công chúa đến sao?"
  },
  AvgDialog_13055_Content_53 = {
    Text = "Nữ hầu từ đám đông lao ra, rõ ràng tinh mắt hơn bạn nhiều, chỉ một cái nhìn đã tìm thấy \"bạn\" quen thuộc giữa đám đông ồn ào hỗn tạp."
  },
  AvgDialog_13055_Content_54 = {
    Text = "<Small:Đại Công tước chọn một kỵ sĩ trẻ thật! Thật sự định để đứa trẻ nhỏ thế này gia nhập đoàn kỵ sĩ huấn luyện sao? Tôi cảm giác cậu ta còn chẳng nhấc nổi vũ khí.>"
  },
  AvgDialog_13055_Content_55 = {
