  AvgDialog_13055_Content_58 = {
    Text = "<Small:Một đứa trẻ thế này, phải luyện bao lâu mới thành kỵ sĩ thực thụ đây…… Đại Công tước chắc chỉ đùa thôi nhỉ?>"
  },
  AvgDialog_13055_Content_59 = {
    Text = "Nữ hầu vừa thành thạo dùng lời lẽ rẽ đám đông, vừa thì thầm nói chuyện vui với bạn, dẫn bạn chen đến trước ngai vàng."
  },
  AvgDialog_13055_Content_6 = {
    Text = "Ta vẫn…có thể……chịu được……"
  },
  AvgDialog_13055_Content_60 = {
    Text = "Xin, xin chào. Ngài chính là Thị quan các hạ sao?"
