  AvgDialog_13055_Content_61 = {
    Text = "Ngươi là……!"
  },
  AvgDialog_13055_Content_62 = {
    Text = "Tôi là trưởng tử gia tộc Dansk, cảm tạ Đại Công tước đề bạt, rất, rất vinh hạnh được trở thành kỵ sĩ của Công chúa @1."
  },
  AvgDialog_13055_Content_7 = {
    Text = "Ogier quỳ một gối xuống đất, mất đi sự duy trì của liên kết, cậu buộc phải dùng trường thương chống đỡ cơ thể để không ngã hẳn xuống."
  },
  AvgDialog_13055_Content_8 = {
    Text = "Chủ……"
  },
  AvgDialog_13055_Content_9 = {
    Text = "Khóe mắt, mép môi, lỗ tai đều rỉ ra chất lỏng đen đặc, các cơ quan đã bị bùn nhão đen bất định hình nghiền nát, có thể hình dung thiếu niên đang chịu đựng nỗi đau khổ như thế nào."
  },
  AvgDialog_13056_Content_1 = {
    Text = "Bài ca mới"
  },
  AvgDialog_13056_Content_10 = {
    Text = "Đừng đến gần nữa! Ta sẽ không nương tay đâu!"
  },
  AvgDialog_13056_Content_100 = {
    Text = "Đi thôi, hôm nay là ngày nghỉ, chợ khu Đông sẽ rất nhộn nhịp, tiện thể cũng có thể ghé viện tế bần thăm bọn trẻ…"
  },
  AvgDialog_13056_Content_101 = {
    Text = "Ngươi cố tình lẩm bẩm về lịch trình, tự mình rời khỏi sân tập, trong lòng không hề lo lắng."
  },
  AvgDialog_13056_Content_102 = {
    Text = "Chúa công! Chúa công! Xin ngài nói cho tôi biết ngài biết bằng cách nào——"
  },
  AvgDialog_13056_Content_103 = {
    Text = "Bởi vì ngươi biết, anh ấy sẽ đi theo thôi."
  },
  AvgDialog_13056_Content_11 = {
    Text = "Ogier chống cây thương dài, chắn ngang cầu thang."
  },
  AvgDialog_13056_Content_12 = {
    Text = "Đây là lần cảnh cáo cuối cùng, xin hãy rời khỏi hành cung!"
  },
  AvgDialog_13056_Content_13 = {
    Text = "Ê, ngươi có nghe thấy không? Hắn nói gì vậy? \"Xin\" chúng ta rời đi á?"
  },
  AvgDialog_13056_Content_14 = {
    Text = "Ha ha ha ha ha ha, buồn cười quá! Bảo sao công quốc lại yếu ớt đến vậy, lại còn dẫn trẻ con chơi trò hiệp sĩ đồ hàng."
  },
  AvgDialog_13056_Content_15 = {
    Text = "Nhỏ giọng đi, ồn ào đau cả tai."
  },
  AvgDialog_13056_Content_16 = {
    Text = "Sĩ quan phớt lờ lời cảnh cáo của Ogier, bước đến trước cửa phòng ngủ, nhìn xuống Ogier từ trên cao."
  },
  AvgDialog_13056_Content_17 = {Text = "Tránh ra."},
  AvgDialog_13056_Content_18 = {
    Text = "Ogier gắng sức ngang cây thương dài, cố gắng chặn bước tiến của sĩ quan."
  },
  AvgDialog_13056_Content_19 = {
    Text = "Xin ngài hãy rời đi!"
  },
  AvgDialog_13056_Content_2 = {
    Text = "Ủng giáp mang theo tàn lửa và bụi đất giẫm lên tấm thảm hành cung."
  },
  AvgDialog_13056_Content_20 = {
    Text = "Ngươi biết không, vũ khí của hiệp sĩ không hợp với ngươi đâu."
  },
  AvgDialog_13056_Content_22 = {
    Text = "Sự kháng cự trước chênh lệch sức mạnh tuyệt đối, thật nhạt nhòa.\nSĩ quan dễ dàng hất văng cây thương của Ogier, rồi đâm một con dao găm vào ngực cậu."
  },
  AvgDialog_13056_Content_23 = {
    Text = "Khụ——!"
  },
  AvgDialog_13056_Content_24 = {
    Text = "Thấy chưa? Đây mới là kỹ năng ngươi nên học.\nDù sao sau khi đất nước diệt vong, bọn ngươi chỉ xứng sống trong những con hẻm tối tăm không thấy ánh mặt trời."
  },
  AvgDialog_13056_Content_25 = {
    Text = "Trộm cắp, đói khát, oán hận lẫn nhau… đó là kết cục của bọn ngươi.\nCây thương đại diện cho vinh quang hiệp sĩ này, đối với ngươi trong tương lai tự nhiên cũng chẳng có ích gì."
  },
  AvgDialog_13056_Content_26 = {
    Text = "Máu tươi tràn vào khí quản, mang theo nỗi đau âm ỉ, như thể bị chết đuối trên cạn, mỗi lần hít thở đều sặc lên mùi tanh của máu."
  },
  AvgDialog_13056_Content_27 = {
    Text = "Ngươi muốn lao ra khỏi chiếc bàn thấp, muốn đẩy tên sĩ quan bên cầu thang xuống dưới, muốn bảo vệ Ogier đang quỳ trước cửa.\nNhưng thân thể này bỗng run rẩy, cứng đờ, không còn nghe theo sự điều khiển của ngươi nữa."
  },
  AvgDialog_13056_Content_28 = {
    Text = "Không… khụ……"
  },
  AvgDialog_13056_Content_29 = {
    Text = "Có một điều ta nói sai — ngươi đã không còn nhìn thấy tương lai đó nữa rồi — ngươi sẽ giống như tên này, trở thành củi đốt cho hành cung này."
  },
  AvgDialog_13056_Content_3 = {
    Text = "Đây là tấm thảm ngươi yêu thích nhất trong \"Giấc mộng hồi ức\". Ngươi và cô thị nữ lắm lời đã chọn lựa suốt cả buổi chiều trong kho của Đại Công, rồi mất thêm nửa ngày mới trải được nó phẳng phiu như bây giờ."
  },
  AvgDialog_13056_Content_30 = {
    Text = "Ủng giáp giẫm mạnh lên thi thể của Fernando, tiếng kim loại va chạm loảng xoảng, lắng nghe kỹ còn lẫn cả tiếng xương gãy giòn tan,"
  },
  AvgDialog_13056_Content_31 = {
    Text = "…Fer……"
  },
  AvgDialog_13056_Content_33 = {
    Text = "Từng thớ cơ đều được adrenaline chi phối, khiến cậu bật dậy giương trường thương, lao thẳng về phía kẻ thù!"
  },
  AvgDialog_13056_Content_34 = {
    Text = "<Big:Đừng đụng vào anh ấy!>"
  },
  AvgDialog_13056_Content_36 = {Text = "Ugh——!"},
  AvgDialog_13056_Content_37 = {
    Text = "Phản kháng là vô ích, đòn tấn công của cậu không những không lay chuyển được viên sĩ quan, mà còn để lộ lưng cho tên trinh sát."
  },
  AvgDialog_13056_Content_38 = {
    Text = "Thằng nhóc này cứng đầu thật, nếu ngay từ đầu nó chạy đi thì bọn mình cũng chẳng rảnh mà đuổi theo đúng không?"
  },
  AvgDialog_13056_Content_39 = {
    Text = "Nhóc con, nhìn vẻ kiên quyết của mày, chẳng lẽ đang bảo vệ ai sao?\nCông chúa có phải đang ở sau cánh cửa này không?"
  },
  AvgDialog_13056_Content_4 = {
    Text = "Công chúa hiếm hoi rời khỏi phòng, tựa vào lan can hành lang tầng hai, thong thả ngắm các ngươi bận rộn trong đại sảnh, còn Augier đến bái kiến thì căng thẳng đến mức không biết đặt chân thế nào."
  },
  AvgDialog_13056_Content_40 = {
    Text = "Máu từ tai ứa ra, Augier đã không thể nghe rõ từng từ nữa, nhưng cậu vẫn bắt được âm thanh quan trọng nhất."
  },
  AvgDialog_13056_Content_41 = {
    Text = "Không…hãy rời đi……"
  },
  AvgDialog_13056_Content_42 = {
    Text = "Tầm nhìn bắt đầu trắng dần từ rìa, có một sức mạnh nào đó đang kéo ý thức ra khỏi thân thể non nớt."
  },
  AvgDialog_13056_Content_43 = {
    Text = "Cậu bò về phía trước, bò qua thi thể Fernando, bò qua mũi ủng của sĩ quan và trinh sát, ngón tay cuối cùng cũng chạm được vào cánh cửa gỗ dày nặng ấy."
  },
  AvgDialog_13056_Content_44 = {
    Text = "Xúc giác ấm áp, mang theo mùi gỗ hơi nồng mũi, giọng nói dịu dàng quan tâm thường vang lên từ sau cánh cửa.\nLúc này, ngoài tiếng tích tắc của đồng hồ nước, sau cánh cửa không còn một tiếng động nào."
  },
  AvgDialog_13056_Content_45 = {
    Text = "Hãy rời khỏi…nơi này……"
  },
  AvgDialog_13056_Content_46 = {
    Text = "<Big:Ahhhh————!>"
  },
  AvgDialog_13056_Content_47 = {
    Text = "Lần này xuyên sâu vào da thịt, chính là cây trường thương của cậu."
  },
  AvgDialog_13056_Content_48 = {
    Text = "Vũ khí đã bị vô số người chế giễu, bị kẻ thù khinh bỉ, nhưng bản thân cậu từ đầu đến cuối chưa bao giờ buông tay."
  },
  AvgDialog_13056_Content_49 = {
    Text = "Mũi thương xuyên qua cơ thể, đóng cậu lên cánh cửa, không thể cựa quậy."
  },
  AvgDialog_13056_Content_5 = {
    Text = "Không phải kỵ sĩ công quốc……Mau trốn đi!"
  },
  AvgDialog_13056_Content_50 = {
    Text = "Ôi chao — đừng tàn nhẫn thế chứ.\nHành hạ kỵ sĩ của nàng như vậy, lỡ \"Công chúa Phù thủy\" nguyền rủa bọn mình thì sao?"
  },
  AvgDialog_13056_Content_51 = {
    Text = "Phù thủy? Thật nực cười."
  },
  AvgDialog_13056_Content_52 = {
    Text = "<Small:@1Công chúa… không phải……>"
  },
  AvgDialog_13056_Content_53 = {
    Text = "Ogier há miệng, tên của công chúa đã ở ngay đầu lưỡi, nhưng dù thế nào cũng không thể thốt ra được."
  },
  AvgDialog_13056_Content_55 = {
    Text = "Anh nghe thấy tiếng nước chảy, phải chăng đồng hồ nước đã đổ? Như vậy có phải là……@1công chúa vẫn còn sống?"
  },
  AvgDialog_13056_Content_56 = {
    Text = "<Small:Không được……đừng ra…không……vào……>"
  },
  AvgDialog_13056_Content_57 = {
    Text = "Đủ rồi……Ogier…cảm ơn ngươi……"
  },
  AvgDialog_13056_Content_58 = {
    Text = "Cảm ơn ngươi…của ta……"
  },
  AvgDialog_13056_Content_59 = {
    Text = "Dưới khe cửa, vài dòng nước đen thẫm rỉ ra trước tiên, hòa lẫn với máu của Ogier, trông giống hệt những giọt nước mắt rơi vì ai đó."
  },
  AvgDialog_13056_Content_6 = {
    Text = "Khoan đã! Còn cậu thì sao?!"
  },
  AvgDialog_13056_Content_60 = {
    Text = "Rồi, những con sóng dữ dội như hồng thủy xé toạc khe cửa thành vết nứt. Gầm gào cuồn cuộn, trong khoánh khắc nhấn chìm cả hành cung."
  },
  AvgDialog_13056_Content_61 = {
    Text = "<Shake:Ugh—— ugh!>"
  },
  AvgDialog_13056_Content_62 = {
    Text = "Dịch bệnh mà người thường không thể nhìn thấy cuốn trôi hai người kia, chất lỏng đen sệt tràn vào từ ngũ quan, nhấn chìm họ giữa không trung."
  },
  AvgDialog_13056_Content_63 = {
    Text = "<Shake:Lời nguyền, đó là lời ngu——>"
  },
  AvgDialog_13056_Content_65 = {
    Text = "Người Giữ Bí Mật? Tỉnh dậy đi, Người Giữ Bí Mật?%player%?"
  },
  AvgDialog_13056_Content_66 = {Text = "Ogier!"},
  AvgDialog_13056_Content_67 = {
    Text = "Gặp ác mộng à? Nhìn kỹ xem, ta là ai."
  },
  AvgDialog_13056_Content_68 = {
    Text = "……Dor? Sao cậu lại ở trong phòng tôi?"
  },
  AvgDialog_13056_Content_69 = {
    Text = "Tôi không quan tâm nội dung ác mộng của cậu, nhưng đêm qua sóng tinh thần của cậu hoạt động mạnh như đang nhảy giao tế vũ vậy."
  },
  AvgDialog_13056_Content_7 = {
    Text = "Augier đẩy mạnh ngươi một cái, nhét vào dưới chiếc bàn thấp.\nTầm nhìn của ngươi xoay tròn chao đảo, cuối cùng chỉ còn thấy tấm thảm Ba Tư lộng lẫy bị lửa thiêu cong mép."
  },
  AvgDialog_13056_Content_70 = {
    Text = "Các Thể Thức Tỉnh liên kết với cậu, bao gồm cả tôi, ít nhiều đều cảm nhận được sự bất thường."
  },
  AvgDialog_13056_Content_71 = {
    Text = "Đêm qua?……Hóa ra chỉ mới qua một đêm thôi sao, chẳng lẽ thật sự chỉ là một giấc mơ……"
  },
  AvgDialog_13056_Content_72 = {
    Text = "Bạn mô tả cho Doer mọi thứ trong giấc mơ hoang đường.\nCông chúa, hiệp sĩ, dịch bệnh……"
  },
  AvgDialog_13056_Content_73 = {
    Text = "Trong số các điều tra viên duy trì liên kết với Thể Thức Tỉnh, thỉnh thoảng có xuất hiện trường hợp ký ức, cảm xúc cộng hưởng với Thể Thức Tỉnh. Nhưng hiện tượng mà bạn mô tả…… tôi chưa từng nghe qua."
  },
  AvgDialog_13056_Content_74 = {
    Text = "Hiện tại mà nói, việc \"nhập mộng\" này không gây ra ảnh hưởng gì thêm đối với bạn, tôi sẽ tiếp tục giám sát chặt chẽ sóng tinh thần của bạn."
  },
  AvgDialog_13056_Content_75 = {
    Text = "……Có lẽ, bây giờ bạn muốn đi gặp Ogier một chút?"
  },
  AvgDialog_13056_Content_76 = {
    Text = "Cảm giác bị dung dịch Dung Thực nuốt chửng quá đỗi chân thực, ánh nắng ban mai chiếu lên chăn, cơ thể đáng lẽ phải cảm thấy ấm áp lại như rơi vào hố băng."
  },
  AvgDialog_13056_Content_77 = {
    Text = "Ogier anh ấy… đúng rồi, tôi đã hẹn với anh ấy hôm nay sẽ tiếp tục luyện tập……"
  },
  AvgDialog_13056_Content_78 = {
    Text = "Đại học Misager — Sân tập luyện\nBuổi sáng sớm"
  },
  AvgDialog_13056_Content_79 = {
    Text = "Ôi trời ơi—— không không không, tôi sẽ chết mất——"
  },
  AvgDialog_13056_Content_8 = {
    Text = "Chỉ có mỗi một đứa nhóc thôi sao? Chúng ta có tìm nhầm chỗ không?"
  },
  AvgDialog_13056_Content_80 = {
    Text = "Tha cho tôi đi, tha cho cô phóng viên tội nghiệp đi, Hiệp sĩ Ogier ơi——"
  },
  AvgDialog_13056_Content_81 = {
    Text = "Cô Hannah cố thêm chút nữa, còn một vòng nữa là kết thúc rồi.\nLần kiểm tra thể lực này cô nhất định sẽ vượt qua thuận lợi!"
  },
  AvgDialog_13056_Content_82 = {
    Text = "Hu hu…… được……"
  },
  AvgDialog_13056_Content_83 = {
    Text = "Cô môi giới trong trường buộc túi cát tạ trọng trên bắp chân, vừa khóc lóc vừa chạy bộ chậm quanh sân tập.\nOgier vừa chạy bước nhỏ theo cô ấy, vừa động viên, thảnh thơi tự tại đến mức không thở hổn hển một chút nào."
  },
  AvgDialog_13056_Content_84 = {Text = "Ogier"},
  AvgDialog_13056_Content_85 = {
    Text = "Người Giữ Bí Mật!"
  },
  AvgDialog_13056_Content_86 = {
    Text = "Anh giao việc giám sát Hannah cho các nhân viên khác, rồi chạy về phía bạn."
  },
  AvgDialog_13056_Content_87 = {
    Text = "Ngài không phải nói buổi luyện tập của chúng ta chiều mới bắt đầu sao? Sao lại đến sớm thế?"
  },
  AvgDialog_13056_Content_88 = {
    Text = "Anh cùng các học viên và Thể Thức Tỉnh khác đã ở sân tập cả buổi sáng, nhưng không hề tỏ ra mệt mỏi chút nào, khi nhìn bạn vẫn tràn đầy sự kính ngưỡng và năng lượng."
  },
  AvgDialog_13056_Content_89 = {Text = "Tôi……"},
  AvgDialog_13056_Content_9 = {
    Text = "Không sai, bản đồ chiến lược vẽ rõ ràng lắm, đây là hành cung dành cho nữ quyến."
  },
  AvgDialog_13056_Content_90 = {
    Text = "……Sau khi buổi luyện tập của Hannah kết thúc, chúng ta đi dạo khu trung tâm Londinium nhé."
  },
  AvgDialog_13056_Content_91 = {Text = "Hả?"},
  AvgDialog_13056_Content_92 = {
    Text = "Ogier rõ ràng không ngờ bạn lại đột nhiên đề nghị nghỉ ngơi, ngay cả chính bạn cũng không ngờ tới."
  },
  AvgDialog_13056_Content_93 = {
    Text = "Chủ nhân, xin cho phép tôi từ chối. Nguy cơ Dung Thực đã cận kề, tôi…… tôi bây giờ, vẫn chưa sẵn sàng."
  },
  AvgDialog_13056_Content_94 = {
    Text = "So với vui chơi, ta muốn tập trung hơn vào việc tinh luyện võ nghệ."
  },
  AvgDialog_13056_Content_95 = {
    Text = "Vậy thì để ta đổi cách nói vậy."
  },
  AvgDialog_13056_Content_96 = {
    Text = "Buổi chiều cùng anh ấy trải qua tại đoàn kỵ sĩ bỗng nhiên hiện lên trong tâm trí, những ký ức mà ngươi tưởng sẽ bị lãng quên khi tỉnh giấc lại ùa về."
  },
  AvgDialog_13056_Content_97 = {
    Text = "Bây giờ là lúc thực hiện nguyện ước rồi, thưa ngài kỵ sĩ."
  },
  AvgDialog_13056_Content_98 = {Text = "!?"},
  AvgDialog_13056_Content_99 = {
    Text = "Ngài, ngài biết điều đó bằng cách nào?!"
  },
  AvgDialog_130571_Content_1 = {
    Text = "Bùng——————"
  },
  AvgDialog_130571_Content_10 = {
    Text = "À, à... Viên than nhỏ, xin lỗi... Mosk, ép lại."
  },
  AvgDialog_130571_Content_11 = {
    Text = "Không sao, chỉ là Mosk, tại sao bạn lại đột nhiên xông vào đây?"
  },
  AvgDialog_130571_Content_12 = {
    Text = "À! Mosk, nóng! Ôm viên than nhỏ, dễ chịu!"
  },
  AvgDialog_130571_Content_13 = {
    Text = "Mosk, kỳ lạ, vì, không lạnh nữa."
  },
  AvgDialog_130571_Content_14 = {
    Text = "Nhưng, nóng quá, nóng quá……"
  },
  AvgDialog_130571_Content_15 = {
    Text = "(Thôi rồi, có phải là do ảnh hưởng của sông thiêng liêng không?)"
  },
  AvgDialog_130571_Content_16 = {
    Text = "Mosk, không biết…"
  },
  AvgDialog_130571_Content_17 = {
    Text = "Ánh mắt của Mosk càng trở nên mông lung, những ngón tay mảnh mai từ khe hở của trang phục thò vào, nhẹ nhàng vuốt ve làn da của bạn."
  },
  AvgDialog_130571_Content_18 = {
    Text = "Bạn rất quen thuộc với cảm giác này, trong giấc mơ đó, \"Viên than nhỏ\" thỉnh thoảng sẽ được tận hưởng dịch vụ vuốt ve này trong vòng tay của Mosk."
  },
  AvgDialog_130571_Content_19 = {
    Text = "Viên than nhỏ, ôm lấy, yên lặng~"
  },
  AvgDialog_130571_Content_2 = {
    Text = "Viên than nhỏ, ôm ôm——"
  },
  AvgDialog_130571_Content_20 = {
    Text = "Viên than nhỏ, mùi vị, thơm quá~"
  },
  AvgDialog_130571_Content_21 = {
    Text = "Mosk nhẹ nhàng ngửi trên người bạn, bạn không chắc đó là hương thơm còn sót lại trên người hay chính sự đặc biệt của bạn đã khiến Mosk bình tĩnh lại."
  },
  AvgDialog_130571_Content_22 = {
    Text = "Nhưng bạn hiểu rằng, bạn không thể để Mosk tiếp tục như vậy nữa."
  },
  AvgDialog_130571_Content_23 = {
    Text = "Sàn nhà rất cứng, lưng của bạn phát ra tiếng phản đối, nó nhớ chiếc giường mềm mại."
  },
  AvgDialog_130571_Content_24 = {
    Text = "Vậy tối nay ôm tôi nhé, chúng ta cùng ngủ nào?"
  },
  AvgDialog_130571_Content_25 = {
    Text = "Ừ! Viên than nhỏ, thích! Muốn ôm!"
  },
  AvgDialog_130571_Content_26 = {
    Text = "Ôm viên than nhỏ, ngủ đi, ngủ đi~"
  },
  AvgDialog_130571_Content_27 = {
    Text = "Bạn thuận thế nằm xuống giường mềm mại cùng với Mosk, hai người ôm nhau, bốn mắt nhìn nhau, giống như lúc ban đầu trên tàu."
  },
  AvgDialog_130571_Content_28 = {
    Text = "Mosk, không nóng nữa~ Mosk, thật thoải mái~"
  },
  AvgDialog_130571_Content_29 = {
    Text = "Chúc ngủ ngon……zzz……Viên than nhỏ……zzz"
  },
  AvgDialog_130571_Content_3 = {Text = "Mô, Mosk?"},
  AvgDialog_130571_Content_4 = {
    Text = "Mosk đột nhiên vui vẻ lao vào phòng, hai tay ôm chặt lấy eo bạn, mái tóc dài màu bạc không ngừng ma sát vào ngực bạn."
  },
  AvgDialog_130571_Content_5 = {
    Text = "Bạn thầm mừng vì cô ấy đã cất trước \"vật đáng sợ\" bám trên tay trái, giúp bạn không phải chịu rủi ro bị cắn bất ngờ."
  },
  AvgDialog_130571_Content_6 = {
    Text = "Viên than nhỏ, thoải mái——"
  },
  AvgDialog_130571_Content_7 = {
    Text = "Mosk, đợi, đợi một chút, à——"
  },
  AvgDialog_130571_Content_8 = {Text = "Đập."},
  AvgDialog_130571_Content_9 = {
    Text = "Đáng tiếc, như bạn đã nghĩ, Mosk không kiểm soát được lực của mình, cả hai cùng ngã xuống đất."
  },
  AvgDialog_131200_Content_1 = {
    Text = "Xiềng xích dịu dàng"
  },
  AvgDialog_131200_Content_10 = {
    Text = "Arachne nhẹ nhàng vuốt ve nửa khuôn mặt còn lại của cô gái. Khi cô khẽ nhắm mắt cho cô gái, cột đèn khổng lồ phía sau phát ra một luồng ánh sáng yếu ớt."
  },
  AvgDialog_131200_Content_11 = {
    Text = "Arachne đưa tay ra. Một chút tàn tro còn sót lại trong cột đèn như những hạt cát bị gió cuốn lên, bay lượn, chảy quanh những ngón tay mảnh mai của cô ấy, rồi rơi xuống đất."
  },
  AvgDialog_131200_Content_12 = {
    Text = "Tàn tro chiều không gian còn sót lại……cảm nhận của chúng ta không sai, đây từng là nơi Nephreya giấu tàn tro, nhưng bây giờ, tàn tro đã bị cô ấy mang đi."
  },
  AvgDialog_131200_Content_13 = {
    Text = "Mang đi tàn tro, giết chết bíLẻ, Nefreya rốt cuộc muốn làm gì……"
  },
  AvgDialog_131200_Content_14 = {Text = "Ừm?"},
  AvgDialog_131200_Content_15 = {
    Text = "Dường như bị thứ gì đó làm động, Arachne ngẩng đầu lên, nhìn qua ô cửa kính màu vẽ biểu tượng đèn cầm tay, hướng về phía sân ga không xa."
  },
  AvgDialog_131200_Content_16 = {
    Text = "Arachne? Bạn sao vậy?"
  },
  AvgDialog_131200_Content_17 = {
    Text = "Hơi thở của bản thể…… tôi không còn cảm nhận được nữa."
  },
  AvgDialog_131200_Content_18 = {Text = "!!!"},
  AvgDialog_131200_Content_19 = {
    Text = "Bạn đang nói rằng bạn đã rời khỏi nhà hát?"
  },
  AvgDialog_131200_Content_2 = {
    Text = "Ngón tay, bắp chân, nhãn cầu, xương sườn, đầu lâu… Chủ nhân đã cắt đứt con búp bê yêu quý, ném vào chất nhầy và máu."
  },
  AvgDialog_131200_Content_20 = {
    Text = "Trong khi chúng tôi tìm kiếm bí ngẫu, thân thể của tôi đang theo sợi chỉ của thành phố, tiến hành thanh trừng những phục vụ của vực thẳm. Sau khi biết được tung tích của \"Ký ức\", cô ấy đã đến nhà thờ để đón chúng tôi."
  },
  AvgDialog_131200_Content_21 = {
    Text = "Hơi thở của cô ấy đã rất gần…… nhưng bây giờ, hơi thở đó đã biến mất."
  },
  AvgDialog_131200_Content_22 = {
    Text = "Liệu có phải... cô ấy đã gặp phải chuyện không may? Nhưng \"ký ức\" vừa mới chết không lâu, sao lại có thể..."
  },
  AvgDialog_131200_Content_23 = {
    Text = "Cụ thể đã xảy ra điều gì, tôi không thể biết. Nhưng trước khi biến mất, cô ấy đã chạm vào mạng lưới liên lạc với tôi. Ngoài lệnh trở về, thông điệp cuối cùng cô ấy để lại là một từ."
  },
  AvgDialog_131200_Content_24 = {
    Text = "\"Hạnh phúc\"."
  },
  AvgDialog_131200_Content_25 = {
    Text = "Hạnh phúc…?"
  },
  AvgDialog_131200_Content_26 = {
    Text = "Trước mặt bạn xuất hiện nụ cười ghê tởm đó."
  },
  AvgDialog_131200_Content_27 = {
    Text = "Tôi không hiểu… các bạn có cùng một ký ức, bạn chắc chắn biết ý cô ấy muốn diễn đạt."
  },
  AvgDialog_131200_Content_28 = {
    Text = "Arachne nhẹ nhàng lắc đầu."
  },
  AvgDialog_131200_Content_29 = {
    Text = "Số phận của ngươi là một con bướm mà ta không thể tùy tiện chạm vào, bất kỳ lời giải thích nào cũng sẽ gây ra hậu quả không thể lường trước."
  },
  AvgDialog_131200_Content_3 = {
    Text = "\"Ký ức\"..."
  },
  AvgDialog_131200_Content_30 = {
    Text = "Nhưng bạn nên biết rằng, trong tương lai ngắn ngủi của bạn,\"Hạnh phúc\" là một chiếc chìa khóa, nó sẽ mở ra những bí mật mà bạn đang đối mặt."
  },
  AvgDialog_131200_Content_31 = {
    Text = "Số phận của tôi? Ý cô là, bây giờ cô có thể nhìn thấy sợi chỉ số phận của tôi?!"
  },
  AvgDialog_131200_Content_32 = {
    Text = "Bạn đối mắt với nàng. Trong nụ cười dịu dàng ấy, bạn nhìn thấy uy nghiêm bất khả xâm phạm đến từ số phận."
  },
  AvgDialog_131200_Content_33 = {
    Text = "……Dù chuyện gì xảy ra, hãy tin tưởng tôi, và cũng hãy tin tưởng vào bản thân bạn."
  },
  AvgDialog_131200_Content_34 = {
    Text = "Hãy trở về Nhà Hát Số Phận đi. Chìa khóa và ổ khóa đều đang chờ đợi ngươi ở đó, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131200_Content_35 = {
    Text = "Nhưng mà……"
  },
  AvgDialog_131200_Content_36 = {
    Text = "Giọng nói bình thản của Arachne như ánh hoàng hôn ấm áp ngày thu. Hình bóng nàng hóa thành một nắm tơ nhện, tan biến trong ánh đèn tĩnh mịch của giáo đường."
  },
  AvgDialog_131200_Content_37 = {
    Text = "Dưới ánh phản chiếu rực rỡ của cửa kính, chỉ còn tàn tro chiều không gian lơ lửng phía trên máu tươi và tứ chi đứt lìa."
  },
  AvgDialog_131200_Content_38 = {
    Text = "\"Hạnh phúc\"..."
  },
  AvgDialog_131200_Content_39 = {
    Text = "Bạn lẩm bẩm từ ngữ không rõ nghĩa đó, quay đầu lại, thấy những xác chết được gọi là \"ký ức\"."
  },
  AvgDialog_131200_Content_4 = {
    Text = "Bạn nhẹ nhàng nhặt những mảnh vỡ của cô gái, chất lỏng dính và máu trên các chi thể thấm ướt áo quần của bạn."
  },
  AvgDialog_131200_Content_40 = {
    Text = "Chúng tắm trong thứ dịch thể đục ngầu và ánh sáng thánh khiết, hòa làm một với giáo đường thiêng liêng này, không thể tách rời."
  },
  AvgDialog_131200_Content_42 = {
    Text = "Con đường kết tinh từ mạng nhện nhẹ nhàng rung động, ánh đèn mờ chiếu sáng sân khấu. Vào khoảnh khắc bạn đặt chân lên mạng nhện, tất cả những con rối đều ngừng biểu diễn."
  },
  AvgDialog_131200_Content_43 = {
    Text = "Mọi người trong tất cả các chiều đều nhìn về phía bạn. Họ tò mò, họ hưng phấn, họ vui mừng và kính sợ."
  },
  AvgDialog_131200_Content_44 = {
    Text = "Đây là một buổi lễ chào đón hoành tráng và tĩnh lặng. Vô số diễn viên đã trở thành khán giả, và khán giả duy nhất trở thành nhân vật chính."
  },
  AvgDialog_131200_Content_45 = {
    Text = "Có lẽ nghe lời Arachne không phải là một ý tưởng hay……"
  },
  AvgDialog_131200_Content_46 = {
    Text = "Bạn âm thầm nắm chặt chìa khóa bạc, một mình bước qua sự im lặng chật chội và kỳ quái này."
  },
  AvgDialog_131200_Content_47 = {
    Text = "Chủ nhân mới của nhà hát đã chờ đợi ngươi từ lâu rồi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131200_Content_48 = {
    Text = "Bóng tối tụ tập trên sân khấu cao. Gần như là phản ứng bản năng, bạn nhanh chóng dựa người ra sau, giơ chìa khóa bạc lên trước người."
  },
  AvgDialog_131200_Content_49 = {
    Text = "Chủ nhân mới?"
  },
  AvgDialog_131200_Content_5 = {
    Text = "Có lẽ…… có lẽ vẫn còn cách nào đó để cứu cô ấy…… sức mạnh của Plasmid…… sự sửa đổi số phận……"
  },
  AvgDialog_131200_Content_50 = {
    Text = "Chào mừng trở lại nhà hát, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131200_Content_51 = {
    Text = "Arachne, bạn......"
  },
  AvgDialog_131200_Content_52 = {
    Text = "Xin lỗi, câu chuyện mới này của chúng tôi cần sự tham gia của bạn."
  },
  AvgDialog_131200_Content_53 = {
    Text = "Mạng nhện nhẹ nhàng rung rinh. Người chủ rạp hát bước chậm về phía bạn, giọng nói vẫn ấm áp như hoàng hôn."
  },
  AvgDialog_131200_Content_54 = {
    Text = "Trên sân khấu xung quanh bạn, những con rối giống như nữ hầu lạnh lùng đã xoay người, đồng loạt nhảy về phía bạn……"
  },
  AvgDialog_131200_Content_55 = {Text = "!!!"},
  AvgDialog_131200_Content_6 = {
    Text = "Nephreya đã hủy diệt sợi chỉ của nàng ấy……Số phận của nàng ấy đã kết thúc rồi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131200_Content_7 = {
    Text = "Tiếng vòng quay vẫn yên tĩnh và xa xăm."
  },
  AvgDialog_131200_Content_8 = {
    Text = "\"Ký ức\" cũng bị cô ấy giết, có phải điều này có nghĩa là..."
  },
  AvgDialog_131200_Content_9 = {
    Text = "Nefreya, đã sở hữu lực lượng để thay đổi số phận của sân khấu này."
  },
  AvgDialog_131201_Content_1 = {
    Text = "Hú… Những người phục vụ của Nefreya thật khó đối phó…"
  },
  AvgDialog_131201_Content_10 = {
    Text = "Hai mươi ngày sau, anh sẽ bắt đầu nghiêm túc nghiên cứu những gì được ghi chép trong cuốn sách này… Kể từ khoảnh khắc đó, sân khấu này sẽ như những sân khấu khác, không thể tránh khỏi số phận hủy diệt."
  },
  AvgDialog_131201_Content_100 = {
    Text = "Thái tử và phu nhân ngồi ở ghế sau của chiếc xe mui trần, thưởng thức thành phố cổ kính này. Mọi người chạy theo sau xe, lao về phía số phận mà họ đã định sẵn."
  },
  AvgDialog_131201_Content_11 = {
    Text = "Thế giới vừa mới tiếp xúc nhưng lại quen thuộc này cuộn trào trong tâm trí bạn. Bạn chưa bao giờ thấy một thế giới tươi đẹp và phồn vinh đến vậy."
  },
  AvgDialog_131201_Content_12 = {
    Text = "Bạn đã trải qua quá nhiều, rỗng rỗng đã dễ dàng che phủ cảnh tượng hoang vu này, làm đầy thế giới phồn hoa này, tràn ngập trong trí tưởng tượng của bạn."
  },
  AvgDialog_131201_Content_13 = {
    Text = "Arachne đưa tay ra, nhẹ nhàng vuốt ve ánh sáng ban mai chiếu xuống góc phố. Cô đang thương tiếc cho một thế giới sắp sửa chết đi."
  },
  AvgDialog_131201_Content_14 = {
    Text = "Một thế giới không được thần linh chú ý đến... Tôi chưa bao giờ có những tưởng tượng như vậy trước đây."
  },
  AvgDialog_131201_Content_15 = {
    Text = "Chúng ta còn cơ hội để thay đổi những điều này không?"
  },
  AvgDialog_131201_Content_16 = {
    Text = "Đây chính là mục đích chúng ta đến đây."
  },
  AvgDialog_131201_Content_17 = {
    Text = "Hãy cho tôi biết, tôi nên làm gì?"
  },
  AvgDialog_131201_Content_18 = {
    Text = "Đợi đã!……"
  },
  AvgDialog_131201_Content_19 = {
    Text = "Ngài đã nhận ra rồi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131201_Content_2 = {
    Text = "Bạn dựa vào bức tường trong con hẻm bí mật này, thở hổn hển."
  },
  AvgDialog_131201_Content_20 = {
    Text = "Ngoài ngõ, một nhóm người có sóng tâm linh rõ ràng khác biệt với người bình thường đang tiến về phía các bạn."
  },
  AvgDialog_131201_Content_21 = {
    Text = "Sau, trên, trước… ngày càng nhiều kẻ địch xuất hiện trong nhận thức của bạn."
  },
  AvgDialog_131201_Content_22 = {
    Text = "Chúng ta bị bao vây rồi!……"
  },
  AvgDialog_131201_Content_23 = {
    Text = "Từ khi đến với sân khấu, tôi đã bắt đầu sửa chữa số phận bị thay đổi. Tuy nhiên, việc sửa chữa số phận của nhiều người như vậy không phải là điều dễ dàng."
  },
  AvgDialog_131201_Content_24 = {
    Text = "Nephreia để lại những người này, chính là để cản trở tôi sửa chữa số phận."
  },
  AvgDialog_131201_Content_25 = {
    Text = "Có lẽ chúng ta còn cách khác……"
  },
  AvgDialog_131201_Content_26 = {
    Text = "Arachne, cuộc ám sát mà Quốc hội phục hưng đang âm thầm lên kế hoạch tại đây hôm nay, tôi là một trong những người thực hiện."
  },
  AvgDialog_131201_Content_27 = {
    Text = "Thế giới này sẽ bị hủy diệt vì vị hoàng tử đó nghiên cứu sách ma thuật, nếu tôi có thể thành công, có lẽ có thể ngăn chặn điều này xảy ra"
  },
  AvgDialog_131201_Content_28 = {
    Text = "Điều này không phải là đúng nhất…"
  },
  AvgDialog_131201_Content_29 = {
    Text = "Ở đó! Bắt họ lại"
  },
  AvgDialog_131201_Content_3 = {
    Text = "Bạn không thấy Arachne chạy, nàng đứng bình thản bên cạnh bạn, như thể số phận đã định sẵn rằng nàng phải đứng trong con hẻm này vào đúng khoảnh khắc này."
  },
  AvgDialog_131201_Content_30 = {
    Text = "Arachne gảy dây đàn, đang chuẩn bị cho những người phục vụ biến hình đứng yên ở cửa ngõ, như một bức tượng."
  },
  AvgDialog_131201_Content_31 = {
    Text = "Âm thanh của kèn trumpet và saxophone vang lên từ xa, âm thanh đó hòa cùng tiếng gầm rú của ô tô, từ từ tiến lại gần."
  },
  AvgDialog_131201_Content_32 = {
    Text = "Kế hoạch ám sát đã bị lộ, những người khác không thể làm được việc này... Vị hoàng thái tử đã gần đến đây, nếu không làm ngay thì sẽ không kịp nữa"
  },
  AvgDialog_131201_Content_33 = {
    Text = "Arachne nhìn vào đôi mắt lo lắng của bạn, do dự một lát rồi nhẹ nhàng gật đầu."
  },
  AvgDialog_131201_Content_34 = {
    Text = "Một khi diễn biến của số phận là như vậy… có lẽ, việc thử lựa chọn cho thế giới này chính là điều bạn nên hoàn thành."
  },
  AvgDialog_131201_Content_35 = {
    Text = "Hãy làm điều ngài muốn làm đi, Người Giữ Bí Mật {Male=先生,Female=小姐}. Chân tướng của vận mệnh, sẽ được hé lộ cho ngài tại đây."
  },
  AvgDialog_131201_Content_36 = {
    Text = "Bạn không có thời gian suy nghĩ kỹ lời của Arachne, gật đầu, dưới sự giúp đỡ của Arachne, lao ra khỏi con hẻm, hòa vào đám đông cuồn cuộn."
  },
  AvgDialog_131201_Content_37 = {
    Text = "Đó chính là Đại Công Flavian sao? Người thừa kế của Đế quốc, chiếc xe của ông ấy phải đáng giá bao nhiêu tiền đây……"
  },
  AvgDialog_131201_Content_38 = {
    Text = "Tôi phỉ nhổ vào hắn! Cái đứa con hoang của tên cướp đó! Từng đồng xu trong túi đều là máu xương cạo từ thân chúng tôi mà ra!"
  },
  AvgDialog_131201_Content_39 = {
    Text = "Nếu chân không bị què, tôi nhất định sẽ chết trên chiến trường xông vào băng cướp này"
  },
  AvgDialog_131201_Content_4 = {
    Text = "Cô ấy đã chuẩn bị kỹ lưỡng như vậy... Rốt cuộc cô ta muốn làm gì?"
  },
  AvgDialog_131201_Content_40 = {
    Text = "Suỵt! Ở đây đầy rẫy vệ sĩ của Đế quốc, bạn không muốn sống nữa sao?"
  },
  AvgDialog_131201_Content_42 = {
    Text = "Khi bạn chen chúc qua đám đông đông đúc và cuối cùng đến bên lề đường, chiếc xe mui trần mới tinh đang từ từ tiến đến trước mặt bạn."
  },
  AvgDialog_131201_Content_43 = {
    Text = "Vị Thái tử gần sáu mươi tuổi cùng phu nhân ngồi ở ghế sau, vừa vẫy tay chào đám đông xung quanh, vừa chỉ trỏ những công trình kiến trúc lịch sử lâu đời của Hervats."
  },
  AvgDialog_131201_Content_44 = {
    Text = "Ngay cả trong ký ức mờ nhạt của bạn, bạn cũng biết rõ hoàng thất thời đại này đã mang đến nỗi đau thương nặng nề biết nhường nào cho mảnh đất này."
  },
  AvgDialog_131201_Content_45 = {
    Text = "Lo lắng về việc gây ra ảnh hưởng xấu đến thế giới này, bạn dừng lại cánh tay vô thức hướng tới chìa khóa bạc, lấy khẩu súng ngắn mà lẽ ra phải có ở đó từ trong áo ra, tiến gần đến chiếc xe đang di chuyển chậm rãi."
  },
  AvgDialog_131201_Content_46 = {
    Text = "Êi! Học sinh kia! Bạn không thể lại gần……"
  },
  AvgDialog_131201_Content_47 = {
    Text = "Xin lỗi, Đại Công điện hạ, một khi tôi đã đứng trên sân khấu, thì phải hoàn thành những việc mà nhân vật này phải làm"
  },
  AvgDialog_131201_Content_48 = {
    Text = "Rầm rầm rầm——"
  },
  AvgDialog_131201_Content_49 = {
    Text = "Trên con phố hỗn loạn này, bên cạnh người thừa kế đế quốc kiêu hãnh không có các biện pháp an ninh chặt chẽ như bạn tưởng tượng. Nhờ vào sự huấn luyện nghiêm ngặt, bạn dễ dàng tiếp cận chiếc xe và bóp cò."
  },
  AvgDialog_131201_Content_5 = {
    Text = "Nephreya đã để lại một mảnh ghép. Trong mạng lưới số phận khổng lồ của thế giới này, cô đã ô nhiễm một sợi dây trong đó."
  },
  AvgDialog_131201_Content_50 = {
    Text = "Khi ba viên đạn chính xác xuyên qua ngực của Đại Công, cả thế giới dường như đã ngừng lại."
  },
  AvgDialog_131201_Content_51 = {
    Text = "Đại công tước đau khổ, hoàng tử phi kinh ngạc, bảo vệ đang chạy, tất cả đều dừng lại một cách hài hước, như một bức tranh dầu sống động."
  },
  AvgDialog_131201_Content_52 = {
    Text = "！！！Đây là……"
  },
  AvgDialog_131201_Content_53 = {
    Text = "Sau một khoảnh khắc tạm dừng, màu sắc của bức tranh dầu bắt đầu chảy và quấn lấy nhau, thời gian và trọng lực tham gia vào cuộc vui hỗn loạn này, cơ thể bạn bị xé toạc, vô số hình ảnh lướt qua trước mắt bạn."
  },
  AvgDialog_131201_Content_54 = {
    Text = "Tang lễ của Thái tử. Cơn thịnh nộ của quân vương. Chiến tranh. Đại bác. Tử vong. Tiếng kèn của chiến binh, tiếng khóc than của thường dân. Kền kền đậu trên chiến trường đỏ thẫm Verdun, gặm nhấm bốn mươi vạn thi thể bị nghiền nát."
  },
  AvgDialog_131201_Content_55 = {
    Text = "Sự sụp đổ của đế chế, vùng đất bị phân chia, vị vua sa sút, quyển sách ma thuật được mở lại…"
  },
  AvgDialog_131201_Content_56 = {
    Text = "Chất lỏng đen dính tạm thời nuốt chửng trường nhìn của bạn. Câu chuyện quen thuộc đó lại một lần nữa diễn ra, bóng tối và nỗi đau hoàn toàn, xói mòn từng tế bào của bạn…"
  },
  AvgDialog_131201_Content_57 = {
    Text = "Không cần lo lắng, ngài đã an toàn rồi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131201_Content_58 = {
    Text = "Một bàn tay đặt lên vai bạn. Bức tranh sơn dầu hỗn loạn và bóng tối vô tận biến mất khỏi tầm mắt bạn."
  },
  AvgDialog_131201_Content_59 = {
    Text = "Bạn bừng mở mắt. Quán cà phê vẫn yên tĩnh như ban đầu, khẩu Browning trong tay đã biến mất, chiếc bánh Sacher vừa được bưng lên bàn đang tỏa hương thơm quyến rũ."
  },
  AvgDialog_131201_Content_6 = {
    Text = "Trong vận mệnh bị ô nhiễm, vị Thái tử của Đế quốc Phio, hai tháng trước đã phát hiện một cuốn sách."
  },
  AvgDialog_131201_Content_60 = {
    Text = "Arachne… đây… chuyện gì vậy?! Chúng tôi…"
  },
  AvgDialog_131201_Content_61 = {
    Text = "Xin đừng hoảng sợ, chúng ta đã trở lại thời điểm vừa mới vào quán cà phê. Tin tốt là, chúng ta đã có một cốc cà phê miễn phí."
  },
  AvgDialog_131201_Content_62 = {
    Text = "Arachne nâng ly cà phê, mỉm cười nhấp một ngụm. Dòng chất lỏng màu nâu phản chiếu gương mặt ngạc nhiên của bạn."
  },
  AvgDialog_131201_Content_63 = {
    Text = "Sợi dây số phận không phải là thứ bạn có thể nhìn rõ. Những diễn viên từ bên ngoài sân khấu, cưỡng chế thay đổi số phận của thế giới này, sẽ bị lạc trong mạng lưới số phận."
  },
  AvgDialog_131201_Content_64 = {
    Text = "Quá khứ và tương lai, khi vô số vận mệnh của sân khấu này đan xen trước mắt bạn, đó chính là cảnh tượng của Lưới Vận Mệnh."
  },
  AvgDialog_131201_Content_65 = {
    Text = "Số phận tương lai…… bạn đang nói rằng, những gì vừa xảy ra, đều là thật sao? Những cuộc chiến tranh, cái chết…… đều là do tôi gây ra?"
  },
  AvgDialog_131201_Content_66 = {
    Text = "Vận mệnh để ngài chứng kiến tất cả những điều này, sau khi ám sát Thái tử, tất cả những điều này đáng lẽ sẽ xảy ra. Tuy nhiên xin đừng lo lắng, Người Giữ Bí Mật {Male=先生,Female=小姐}. Vận mệnh của sân khấu này, ta đã dệt lại rồi."
  },
  AvgDialog_131201_Content_67 = {
    Text = "Bạn nhìn ra ngoài cửa sổ. Vẫn là đám đông tấp nập, nhưng những công dân và cảnh sát bị Nephreya ảnh hưởng đã hoàn toàn biến mất."
  },
  AvgDialog_131201_Content_68 = {
    Text = "Nếu theo cách tôi vừa làm…… nếu bạn không sửa chữa số phận...\nthì……"
  },
  AvgDialog_131201_Content_69 = {
    Text = "Một tháng sau, thế giới này sẽ bùng nổ cuộc chiến tranh lớn nhất trong lịch sử vì cái chết của vị hoàng tử này. Tám đế quốc sẽ bị cuốn vào, hai mươi triệu người sẽ chết trong cuộc chiến này."
  },
  AvgDialog_131201_Content_7 = {
    Text = "Một cuốn sách ghi chép về những pháp thuật huyền bí, có khả năng kết nối với các thần linh không thuộc chiều không gian này."
  },
  AvgDialog_131201_Content_70 = {
    Text = "Đất dưới chân chúng ta sẽ hóa thành bụi than, những người ngồi bên cạnh chúng ta trong quán cà phê, không ai có thể sống sót sau cuộc chiến đó."
  },
  AvgDialog_131201_Content_71 = {
    Text = "Arachne lắc ly cà phê, nhìn ra ngoài khung cửa cảnh tượng xe cộ tấp nập. Cô bình tĩnh kể chuyện, như thể đang giới thiệu một món tráng miệng bình thường nhất."
  },
  AvgDialog_131201_Content_72 = {
    Text = "Âm thanh ồn ào của con phố mang theo âm điệu an bình và thịnh vượng, truyền vào tai bạn."
  },
  AvgDialog_131201_Content_73 = {
    Text = "Rỗng rỗng thì sao? Tại sao tôi đã giết chết hoàng thái tử đó, mà vẫn mang lại sự rỗng rỗng cho thế giới này…"
  },
  AvgDialog_131201_Content_74 = {
    Text = "Trong cuộc chiến tranh vĩ đại đó, đế chế này đã thất bại. Vị vua đó, vốn dĩ phải chấp nhận phán quyết tàn nhẫn của số phận. Nhưng bây giờ, ông có một lựa chọn mới."
  },
  AvgDialog_131201_Content_75 = {
    Text = "Phép thuật không thuộc về thế giới này, vị thần vượt qua mọi sức mạnh. Đối với một người cha mất con, một vị vua mất nước, có gì hấp dẫn hơn điều này?"
  },
  AvgDialog_131201_Content_76 = {
    Text = "Lời nói dịu dàng của Arachne khiến bạn rùng mình. Trọng lượng của hai tỷ sinh mạng, như thể hiện hữu, đè nặng lên bạn."
  },
  AvgDialog_131201_Content_77 = {
    Text = "<Shake:Tôi không ngờ rằng, ám sát một vị Thái tử, lại có thể gây ra chuyện như vậy……Tôi cứ tưởng……>"
  },
  AvgDialog_131201_Content_78 = {
    Text = "Số phận đã đưa bạn đến để đưa ra lựa chọn này, là để cho bạn thấy rõ nó. Bạn không thể nhìn thấy sợi chỉ, nhưng bây giờ bạn đã hiểu, những sợi chỉ này được đan xen theo cách phức tạp như thế nào."
  },
  AvgDialog_131201_Content_79 = {
    Text = "Sợi chỉ số phận dệt nên mạng lưới khổng lồ, mỗi một sợi chỉ rung nhẹ, có lẽ sẽ khiến mạng lưới số phận sụp đổ."
  },
  AvgDialog_131201_Content_8 = {
    Text = "Arachne ngẩng đầu, nhìn về phía những sợi chỉ mà bạn không thể nhìn thấy."
  },
  AvgDialog_131201_Content_80 = {
    Text = "Đây chính là số phận——số phận phức tạp như vậy."
  },
  AvgDialog_131201_Content_81 = {
    Text = "Bạn hít sâu một lần, làm dịu trái tim đang đập mạnh vì nỗi sợ hãi."
  },
  AvgDialog_131201_Content_82 = {
    Text = "Còn may, còn may bạn đã ngăn chặn được cuộc chiến này……"
  },
  AvgDialog_131201_Content_83 = {
    Text = "Ta không hề ngăn chặn chiến tranh, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131201_Content_84 = {
    Text = "Arachne nhẹ nhàng lắc đầu."
  },
  AvgDialog_131201_Content_85 = {
    Text = "Trong số phận mới, vị vua của đế quốc sẽ nhìn thấy một phần nhỏ của kỳ tích được thể hiện trong cuốn sách phù thủy. Những sức mạnh đó sẽ trở thành chỗ dựa cho ông trong việc khởi động chiến tranh."
  },
  AvgDialog_131201_Content_86 = {
    Text = "Vua và đồng minh của ngài đã phát động một cuộc chiến tranh quy mô lớn hơn, các đế chế ở những lục địa khác cũng bị cuốn vào cuộc chiến này."
  },
  AvgDialog_131201_Content_87 = {
    Text = "Những người chết trong cuộc chiến này gấp bốn lần so với ban đầu."
  },
  AvgDialog_131201_Content_88 = {
    Text = "Nàng bình thản kể lại, như thể đang kể một câu chuyện cổ tích dịu dàng cho đứa trẻ chưa chịu ngủ."
  },
  AvgDialog_131201_Content_89 = {
    Text = "<Shake:Điều này……tại sao lại thế?>"
  },
  AvgDialog_131201_Content_9 = {
    Text = "Sân khấu này chưa bao giờ có kết nối với thần minh, trong một khoảng thời gian dài, nó có thể tránh khỏi việc bị sụp đổ vào số phận rỗng rỗng."
  },
  AvgDialog_131201_Content_90 = {
    Text = "Bạn đã thấy sự phức tạp của mạng lưới số phận. Cố gắng tránh né một số điều đã định sẽ dẫn đến những thảm họa nghiêm trọng hơn."
  },
  AvgDialog_131201_Content_91 = {
    Text = "Vị quân vương ấy vẫn thất bại, kiến thức hữu hạn trong cuốn sách đó không mang lại nhiều trợ giúp hơn cho đế quốc."
  },
  AvgDialog_131201_Content_92 = {
    Text = "Sau thất bại lần này, phù thuật trở thành một trò cười, những kẻ thống trị trên sân khấu này không còn ai dốc sức theo đuổi nó nữa."
  },
  AvgDialog_131201_Content_93 = {
    Text = "Ánh mắt của họ, rơi vào những sự vật khác. Họ tín ngưỡng khoa học, nghiên cứu những vũ khí có thể tiêu thụ hành tinh, tận hưởng hòa bình ngắn ngủi dưới sự răn đe của những vũ khí này, rồi bị chính những vũ khí do họ tạo ra hủy diệt."
  },
  AvgDialog_131201_Content_94 = {
    Text = "Sân khấu này rồi vẫn sẽ không còn tồn tại vì những kiếp nạn khác, đó là định mệnh không thể tránh khỏi của nó. Nhưng họ vẫn có thể tận hưởng một thời kỳ phồn vinh đẹp như một tác phẩm nghệ thuật."
  },
  AvgDialog_131201_Content_95 = {
    Text = "Ánh mắt của Tohvapo, tạm thời sẽ không thể chạm tới nơi này."
  },
  AvgDialog_131201_Content_96 = {
    Text = "Cái thìa của Arachne từ từ xoay trong cốc, vòng xoáy nâu sẫm ấy giống hệt những gì bạn đã thấy trong mạng số phận."
  },
  AvgDialog_131201_Content_97 = {
    Text = "Cô ấy cúi đầu xuống. Ánh nắng bên ngoài rơi trên người cô, như một tấm màn buồn bã."
  },
  AvgDialog_131201_Content_98 = {
    Text = "Vùng vẫy, dệt nên, vá lại, nhưng không thể thay đổi……đó chính là vận mệnh, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131201_Content_99 = {
    Text = "Âm nhạc của kèn trumpet và saxophone đến bên cửa sổ, rồi dần dần xa đi cùng với tiếng hoan hô và mắng chửi của đám đông."
  },
  AvgDialog_131202_Content_1 = {Text = "Pa——"},
  AvgDialog_131202_Content_10 = {
    Text = "Tín đồ?…"
  },
  AvgDialog_131202_Content_11 = {
    Text = "Bộ đồ dài màu tím…… tôi chưa từng…… chưa từng thấy……"
  },
  AvgDialog_131202_Content_12 = {
    Text = "Chúng……đã mang \"Hồi Ức\" đến bàn tế……<Shake:khụ khụ……>"
  },
  AvgDialog_131202_Content_13 = {
    Text = "Đường Thánh Vasil… thuộc về một nhà thờ của họ…"
  },
  AvgDialog_131202_Content_14 = {
    Text = "Xương cốt và thịt máu run rẩy, vùng vẫy, ép chặt sức sống cuối cùng của cơ thể rách nát này."
  },
  AvgDialog_131202_Content_15 = {
    Text = "Anh biết, cô Arachne không thể nhìn rõ những sợi dây của những người đó. Anh biết, đây là việc cần anh hoàn thành."
  },
  AvgDialog_131202_Content_16 = {
    Text = "Cô gái… kẻ ác trong bóng tối… đang săn lùng chúng ta… cô ấy đã làm biến đổi số phận của chúng ta…"
  },
  AvgDialog_131202_Content_17 = {
    Text = "Họ đã mang đi máu của tôi... Trong nhà thờ đó, cô ấy sẽ thực hiện nghi lễ kinh dị đó..."
  },
  AvgDialog_131202_Content_18 = {
    Text = "Kẻ phục thù của định mệnh, tắm trong máu chúng ta……Tà thần đến từ bóng tối sắp giáng lâm, mọi định mệnh đều sẽ rơi vào……hoàn toàn……<Shake:khụ khụ khụ……><Big:hỗn loạn tuyệt đối……！>"
  },
  AvgDialog_131202_Content_19 = {
    Text = "Đồng tử của người già bỗng nhiên giãn ra, cơ thể run rẩy vì lạnh và sợ hãi, dường như đã nhìn thấy một địa ngục khủng khiếp hơn cả ác mộng sâu thẳm nhất của ông."
  },
  AvgDialog_131202_Content_2 = {
    Text = "Lũ nhện tản ra khắp nơi, bóng người cuối cùng ngã xuống trong ánh bạc, chủ nhân của cơn mưa lớn đã biến mất từ lâu. Bạn và Arachne đến trước bóng hình ngã xuống giữa phòng."
  },
  AvgDialog_131202_Content_20 = {
    Text = "Anh ta nắm chặt tay áo của Arachne, dùng ánh mắt gần như cầu khẩn nhìn về phía Arachne."
  },
  AvgDialog_131202_Content_21 = {
    Text = "Cô gái…… tôi vẫn quen gọi cô là cô gái…… cô đã phải mất rất lâu mới học nói, khiến cho lão gia và phu nhân sốt ruột…"
  },
  AvgDialog_131202_Content_22 = {
    Text = "Bạn từ biệt tôi, mọi người đều vui mừng vì cuối cùng bạn có thể lên tiếng, nhưng tôi biết, chỉ có tôi biết… câu nói đó, là phán quyết không thể tránh khỏi của số phận…"
  },
  AvgDialog_131202_Content_23 = {
    Text = "Tôi trở về nhà, đợi đến cái chết. Tôi không thể ngừng khóc, không phải vì bản thân mình, mà là vì cô Arachne..."
  },
  AvgDialog_131202_Content_24 = {
    Text = "Tôi biết, điều bạn sắp phải gánh vác, là một lời nguyền nặng nề biết bao……"
  },
  AvgDialog_131202_Content_25 = {
    Text = "Nước mắt chảy qua gò má đầy nếp nhăn của người già. Ông run rẩy nắm lấy tay Arachne. Qua ánh nước mắt mờ ảo, ông nhìn thấy Arachne thời thơ ấu đứng trước mặt."
  },
  AvgDialog_131202_Content_26 = {
    Text = "Khuôn mặt trẻ thơ ấy chưa từng khóc lớn, nó luôn hướng đôi mắt tò mò về bầu trời trống rỗng, mỉm cười với những số phận mà họ không thể nhìn thấy."
  },
  AvgDialog_131202_Content_27 = {
    Text = "Cô Arachne, xin hãy bảo vệ cô ấy thật tốt, bảo vệ tốt \"kỷ niệm\"... Xin hãy chăm sóc bản thân thật tốt..."
  },
  AvgDialog_131202_Content_28 = {
    Text = "Đừng……lạc lối trong……mạng lưới……"
  },
  AvgDialog_131202_Content_29 = {
    Text = "Giọng nói của \"lương thiện\" cuối cùng gần như không còn nghe thấy. Khi âm thanh của anh dừng lại, Arachne nhẹ nhàng khép mắt lại cho anh."
  },
  AvgDialog_131202_Content_3 = {
    Text = "Là bạn…"
  },
  AvgDialog_131202_Content_30 = {
    Text = "\"Chúc ngủ ngon, ngài Edgar……\""
  },
  AvgDialog_131202_Content_31 = {
    Text = "Khóe miệng lão Edgar khẽ nhếch lên. Trong khoảnh khắc cuối cùng của cuộc đời, lão lại một lần nữa nghe thấy câu nói đầu tiên mà Arachne thốt ra trong đời."
  },
  AvgDialog_131202_Content_32 = {
    Text = "Anh ta không có gì để cầu."
  },
  AvgDialog_131202_Content_33 = {
    Text = "Ngươi……dùng ký ức của vị quản gia ấy, tạo ra hắn……Những bí ngẫu này hoàn toàn khác với những con rối khác mà ngươi tạo ra. Tại sao?"
  },
  AvgDialog_131202_Content_34 = {
    Text = "Có lẽ là để tưởng nhớ, có lẽ… là để an ủi chính mình."
  },
  AvgDialog_131202_Content_35 = {Text = "An ủi?"},
  AvgDialog_131202_Content_36 = {
    Text = "Tự an ủi bản thân, họ luôn ở bên cạnh tôi, chưa bao giờ rời xa…"
  },
  AvgDialog_131202_Content_37 = {
    Text = "Arachne bình tĩnh đặt xuống thân thể tàn tạ của người già, không cần giải thích thêm, bạn cũng không hỏi thêm. Bạn biết, câu trả lời đang chờ đợi bạn ở nơi không xa."
  },
  AvgDialog_131202_Content_38 = {
    Text = "Trong mạng lưới số phận này, sức mạnh của Nephreya liên quan đến họ. Cái chết của họ sẽ khiến Nephreya gắn bó chặt chẽ hơn với mạng lưới."
  },
  AvgDialog_131202_Content_39 = {
    Text = "Trước khi nàng ta sở hữu sức mạnh có thể phá hủy mạng lưới này, hãy ngăn chặn nàng ta, đó là điều duy nhất quan trọng lúc này, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131202_Content_4 = {
    Text = "<Shake:Tiểu thư Arachne……Dị hương nhân……khụ khụ……>"
  },
  AvgDialog_131202_Content_40 = {
    Text = "Hai bàn tay của Arachne nhẹ nhàng chạm vào đỉnh đầu của người già, chạm vào sợi chỉ gần như không thể nhìn thấy. Ở đầu kia của thành phố này, sợi chỉ số phận phát ra âm thanh yếu ớt."
  },
  AvgDialog_131202_Content_41 = {
    Text = "Số phận đã đáp lại bạn?"
  },
  AvgDialog_131202_Content_42 = {
    Text = "Arachne gật đầu. Trước khi đứng dậy, cô ấy cuối cùng đã nhìn một lần nữa vào gương mặt đang mỉm cười của người già."
  },
  AvgDialog_131202_Content_43 = {
    Text = "\"Ký ức\" vẫn còn sống. Những vị khách từ vực sâu, đang chờ đợi sự đến của chúng ta."
  },
  AvgDialog_131202_Content_5 = {
    Text = "Thân thể trước mặt bạn một nửa là thịt máu đã bị gặm nhấm đến thối rữa, một nửa là xương trắng mang theo màu máu."
  },
  AvgDialog_131202_Content_6 = {
    Text = "Tiếng ho dữ dội của người già cố gắng bật ra vài giọt máu tươi chưa kịp khô. Một sợi chỉ vô hình nằm trong tay Arachne, như ngọn nến trong cơn mưa bão, đang goyang-goyang."
  },
  AvgDialog_131202_Content_7 = {
    Text = "Cầm máu……chúng ta cần một thứ để cầm máu……"
  },
  AvgDialog_131202_Content_8 = {
    Text = "Không kịp nữa... cô Arachne... đi cứu cô ấy... đi cứu \"ký ức\"..."
  },
  AvgDialog_131202_Content_9 = {
    Text = "Những tín đồ…… đã đưa cô ấy đi……"
  },
  AvgDialog_131203_Content_1 = {
    Text = "Arachne! Bạn đang làm gì vậy?! Đây chính là điều bạn nói về… niềm tin?"
  },
  AvgDialog_131203_Content_10 = {
    Text = "Biểu diễn. Lừa dối. Đùa giỡn."
  },
  AvgDialog_131203_Content_11 = {
    Text = "\"Hoan Duyệt\", đây là định mệnh của ngươi. Hãy bước lên sân khấu đi, Người Giữ Bí Mật {Male=先生,Female=小姐}. Trên sân khấu này, hãy hoàn thành câu chuyện thuộc về ngươi."
  },
  AvgDialog_131203_Content_12 = {
    Text = "Trên sân khấu này, bạn sẽ đạt được điều bạn mong muốn."
  },
  AvgDialog_131203_Content_2 = {
    Text = "Học trưởng William……Học trưởng William vẫn đang dưỡng thương!……"
  },
  AvgDialog_131203_Content_3 = {
    Text = "Xin hãy yên tâm, đoạn số phận này không liên quan đến ngài William, tôi đã chuyển anh ấy đến nơi an toàn rồi."
  },
  AvgDialog_131203_Content_4 = {
    Text = "Đây là số phận mà ngươi và ta không thể trốn tránh, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131203_Content_5 = {
    Text = "Tôi chưa bao giờ nói dối với bạn. Tôi sẽ đưa bạn đến sân khấu thuộc về bạn, nơi bạn sẽ hoàn thành màn biểu diễn hoành tráng của riêng mình."
  },
  AvgDialog_131203_Content_6 = {
    Text = "Arachne từ từ tiến lại gần bạn. Bạn nhìn vào đôi mắt mờ ảo của cô ấy, muốn đọc được những thông điệp mà cô ấy không thể trực tiếp truyền đạt cho bạn."
  },
  AvgDialog_131203_Content_7 = {
    Text = "(thuộc về tôi……buổi biểu diễn……)"
  },
  AvgDialog_131203_Content_8 = {
    Text = "Một tia sáng linh thiêng lướt qua tâm trí bạn, như một ngôi sao băng thoáng qua, biến mất trong những mảnh vụn rối rắm của ý thức."
  },
  AvgDialog_131203_Content_9 = {
    Text = "Các nàng hầu gái nhện lạnh lùng tản ra xung quanh, không còn tiến lên nữa. Arachne nhẹ nhàng nâng tay, gảy những dây đàn trống rỗng."
  },
  AvgDialog_131204_Content_1 = {
    Text = "Ánh sáng bạc như lưỡi dao sắc cắt đứt những sợi chỉ, tận dụng khoảng trống này, bạn nhanh chóng vượt qua hàng phòng ngự của các nữ hầu, đến trước mặt Arachne."
  },
  AvgDialog_131204_Content_10 = {
    Text = "Cô ấy quay người. Những sợi tơ nhẹ nhàng xoay chuyển, một cơn bốc đồng không hề báo trước từ sâu bên trong bùng cháy, thúc giục bạn đứng dậy."
  },
  AvgDialog_131204_Content_11 = {
    Text = "Bạn chắc chắn rằng bạn hoàn toàn tự chủ, bạn là đại diện hoàn hảo của ý chí tự do. Bạn hoàn toàn theo ý muốn cá nhân, đi theo bước chân của Arachne, với nhịp điệu và bước đi hoàn toàn đồng nhất với cô ấy, tiến về cuối con đường mạng nhện."
  },
  AvgDialog_131204_Content_13 = {
    Text = "Ôi chào, hoan nghênh! %player%{Male=先生,Female=小姐}, vị khách quý của ta! Đây là lần tiếng bước chân của ngươi nghe du dương nhất đấy."
  },
  AvgDialog_131204_Content_14 = {
    Text = "Chủ nhân mới của nhà hát xuất hiện, giọng điệu phóng đại của Nefreya vang lên trên sân khấu tối tăm."
  },
  AvgDialog_131204_Content_15 = {
    Text = "Bị người khác thao túng số phận, cảm giác không dễ chịu chút nào phải không, Người Giữ Bí Mật {Male=先生,Female=小姐}? Nhưng không sao, câu chuyện này sắp đón nhận kết cục của nó rồi."
  },
  AvgDialog_131204_Content_16 = {
    Text = "Nephreya, bạn cuối cùng muốn làm gì?…"
  },
  AvgDialog_131204_Content_17 = {
    Text = "Huyền bí, đúng vậy, đó chính là lý do khiến khán giả đến với nhà hát này! Nhưng đừng vội, thân mến."
  },
  AvgDialog_131204_Content_18 = {
    Text = "Các bà, các ông! Hãy chuẩn bị cho tiếng hoan hô của các bạn… Hửm, con rối của tôi đâu rồi… À, đã tìm thấy"
  },
  AvgDialog_131204_Content_19 = {
    Text = "Sát hại ba vị bí ẩn, những kẻ báo thù vĩ đại của số phận, rốt cuộc muốn mang đến màn trình diễn đầy tưởng tượng nào cho sân khấu này?"
  },
  AvgDialog_131204_Content_2 = {
    Text = "Được rồi!"
  },
  AvgDialog_131204_Content_20 = {
    Text = "Tiếp theo, xin mời mọi người thưởng thức <Big:<Red:cao trào cuối cùng>> của hồi thứ hai vở kịch này!"
  },
  AvgDialog_131204_Content_21 = {
    Text = "Tôi đặt tên nó là, \"Sinh ra\"——"
  },
  AvgDialog_131204_Content_22 = {Text = "Pa——"},
  AvgDialog_131204_Content_23 = {
    Text = "Một chùm ánh sáng rực rỡ hội tụ trên sân khấu, phá vỡ sự yên tĩnh và bóng tối ngắn ngủi của nhà hát. Một con rối cầm bánh xe quay bước lên sân khấu."
  },
  AvgDialog_131204_Content_24 = {
    Text = "Nephreya, Tử Thần của Uyên Ngục, kẻ phục thù số phận……<Shake:Ta đã thần phục trước sức mạnh vĩ đại của Ngài!>"
  },
  AvgDialog_131204_Content_25 = {
    Text = "Đây là lãng mạn, nó làm cho người ta trở nên ngu ngốc. Đây là lòng tốt, nó làm cho người ta mong manh. Đây là kỷ niệm… Trong tất cả những phẩm chất tốt đẹp, kỷ niệm là nguồn gốc của mọi nỗi đau."
  },
  AvgDialog_131204_Content_26 = {
    Text = "Tôi không thể chịu đựng chúng nữa… tôi dâng chúng cho ngài, Nefreya vĩ đại."
  },
  AvgDialog_131204_Content_27 = {
    Text = "Có thật không, chị gái? Chị gái tốt của tôi……"
  },
  AvgDialog_131204_Content_28 = {
    Text = "Không sao đâu, trong thế giới này, tôi là người hiểu bạn nhất. Đừng đau khổ nữa, hãy giao hết những nỗi đau này cho tôi."
  },
  AvgDialog_131204_Content_29 = {
    Text = "Bạn xem, đèn cầm tay đến từ Địa Ngục đã được thắp sáng, ánh sáng của nó sẽ dẫn dắt chúng ta về nhà——"
  },
  AvgDialog_131204_Content_3 = {Text = "Ding——"},
  AvgDialog_131204_Content_30 = {
    Text = "Ánh sáng thật ấm áp... nhưng, con đường về nhà của chúng ta, rốt cuộc ở đâu?"
  },
  AvgDialog_131204_Content_31 = {
    Text = "Chị vẫn chưa hiểu sao? Chị gái tốt của tôi."
  },
  AvgDialog_131204_Content_32 = {
    Text = "Cái vòng quay này, chính là thân thể của Sứ đồ. Những ngọn đèn này, chính là ánh mắt của Sứ đồ—— Ngài đang nhìn chúng ta"
  },
  AvgDialog_131204_Content_33 = {
    Text = "\"Neferia\" hưng phấn đứng dậy, giang tay ra."
  },
  AvgDialog_131204_Content_34 = {
    Text = "Chỉ cần hội tụ quyền lực của ba Plasmid, thì Sứ đồ vô danh sẽ thức tỉnh tại đây"
  },
  AvgDialog_131204_Content_35 = {
    Text = "Ngài sẽ mở ra con đường dẫn đến vị thần tối cao cho chúng ta……Khi đó, <Big:mọi khổ nạn sẽ tiêu vong, mọi phí công sẽ chấm dứt!>"
  },
  AvgDialog_131204_Content_36 = {
    Text = "\"Nephreya\"đột ngột giật phăng chiếc mặt nạ gỗ, lộ ra khuôn mặt sống động của Nephreya."
  },
  AvgDialog_131204_Content_37 = {
    Text = "Sân khấu bằng gỗ, con rối bằng gỗ, cơ thể duy nhất sống động đứng ở giữa sân khấu, giang tay ra, tận hưởng ánh mắt của vị khán giả duy nhất bên dưới."
  },
  AvgDialog_131204_Content_38 = {
    Text = "Cánh cửa của thần linh sắp mở ra, nhiệm vụ của bạn sắp hoàn thành, bạn hiểu không, chị gái?"
  },
  AvgDialog_131204_Content_39 = {
    Text = "Bạn không cần phải tiếp tục dệt cái lưới vô tận của mình, bạn không cần phải từ bỏ chính mình nữa"
  },
  AvgDialog_131204_Content_4 = {
    Text = "Bàn tay mảnh khảnh vươn ra không trung nhẹ nhàng gảy. Dây đàn rung nhẹ, không khí lan tỏa một gợn sóng duyên dáng."
  },
  AvgDialog_131204_Content_40 = {
    Text = "Hãy chấp nhận lại tôi, được không, Arachne?…… Hãy để tôi trở thành một phần của bạn lần nữa……"
  },
  AvgDialog_131204_Content_41 = {
    Text = "Nước mắt làm trôi lớp trang điểm, để lại những vết đen như rỗng rỗng trên khuôn mặt. Tiếng cười điên rồ và tiếng khóc như một chiếc lưới khổng lồ, vướng víu quanh vị này, cá thể duy nhất sống động trên sân khấu.."
  },
  AvgDialog_131204_Content_42 = {
    Text = "Nephreya quỳ xuống, nâng gương mặt nhẵn thín không có ngũ quan của \"Arachne\". Nước mắt lăn xuống gương mặt khóc than đó, rơi xuống chiếc mặt nạ cười của con búp bê."
  },
  AvgDialog_131204_Content_43 = {
    Text = "Cô ấy chăm chú nhìn Arachne ở dưới sân khấu, đôi môi run rẩy nhẹ nhàng áp vào tai con rối. Giọng nói của cô nhẹ nhàng như thể đang nói với chính mình."
  },
  AvgDialog_131204_Content_44 = {
    Text = "Đừng bỏ rơi tôi nữa…… được không?"
  },
  AvgDialog_131204_Content_5 = {
    Text = "Gợn sóng lướt qua ánh sáng bạc, ánh sáng bạc tan biến, chìa khóa bạc mang sức mạnh tinh thần mạnh mẽ không biết đã đi đâu. Gợn sóng lướt qua cơ thể, thân thể của bạn biến thành xương khô, máu hóa thành bùn. Bạn bị vỡ thành nhiều mảnh, sau đó phục hồi như cũ."
  },
  AvgDialog_131204_Content_6 = {
    Text = "Tất cả lực lượng đều tan biến vô hình, tất cả ý nghĩ đều bay hơi. Ở nơi sóng gợn lan tới, muôn ngàn thế giới hóa thành những sợi chỉ trong tay cô ấy. Bao gồm cả bạn, chính bạn."
  },
  AvgDialog_131204_Content_7 = {
    Text = "Cô ấy là chủ nhân của nhà hát. \n Cô ấy chính là số phận."
  },
  AvgDialog_131204_Content_8 = {
    Text = "Arachne, bạn…… bạn có thể điều khiển số phận của tôi?!……"
  },
  AvgDialog_131204_Content_9 = {
    Text = "Nụ cười của Arachne như một hồ nước yên bình, bạn không thể nhìn rõ hình dáng của hồ, trên mặt hồ này, bạn chỉ có thể thấy bóng dáng của chính mình."
  },
  AvgDialog_131205_Content_1 = {
    Text = "Súng đạn"
  },
  AvgDialog_131205_Content_10 = {
    Text = "Bạn không cần nộp bất kỳ bài tập nào."
  },
  AvgDialog_131205_Content_11 = {
    Text = "Thầy Arachne, thầy… có ý nghĩa gì?"
  },
  AvgDialog_131205_Content_12 = {
    Text = "Bạn còn nhớ bạn là ai, đến từ đâu không?"
  },
  AvgDialog_131205_Content_13 = {
    Text = "Tôi? Tôi đương nhiên là……"
  },
  AvgDialog_131205_Content_14 = {
    Text = "%player%. Thanh niên Hervats sinh ra và lớn lên tại đây. Sinh viên năm nhất của Học viện Kịch nghệ. Cha mẹ là nhân viên bình thường của chính phủ, hết mực yêu thương cậu. Đã trải qua hai mối tình đứng đắn. Tài năng có hạn, tràn đầy nhiệt huyết, yêu thích bánh Sacher và bánh cuộn thịt nướng."
  },
  AvgDialog_131205_Content_15 = {
    Text = "Ký ức vốn rõ ràng bỗng trở nên mờ ảo, một đoạn ký ức khác đột ngột bật ra từ tâm trí bạn. Misaque, Thể thức tỉnh, rỗng rỗng, Toguwaibo…"
  },
  AvgDialog_131205_Content_16 = {
    Text = "Bạn đột ngột mở to mắt, nhìn về phía người phụ nữ đang thưởng thức cà phê đối diện."
  },
  AvgDialog_131205_Content_17 = {
    Text = "Không... không đúng... tôi là Người Giữ Gìn của Misaque... chuyện gì đang xảy ra vậy?!"
  },
  AvgDialog_131205_Content_18 = {
    Text = "Tôi đã nhớ ra…… Chúng ta ở trong nhà hát của bạn, bước lên một sân khấu, rồi…… rồi……"
  },
  AvgDialog_131205_Content_19 = {
    Text = "Sau đó bạn đã gọi trà chiều với người phục vụ. Là một người địa phương, gu thẩm mỹ của bạn thật sự không tồi."
  },
  AvgDialog_131205_Content_2 = {
    Text = "Đinh đinh——"
  },
  AvgDialog_131205_Content_20 = {
    Text = "Arachne nhấp một ngụm chất lỏng màu nâu trong cốc cà phê, gật đầu khen ngợi."
  },
  AvgDialog_131205_Content_21 = {
    Text = "Hai vị, đồ của các bạn đã đến đủ rồi."
  },
  AvgDialog_131205_Content_22 = {
    Text = "Khay thức ăn trong tay người phục vụ tỏa ra hương thơm quyến rũ, khi cúi người bày món, anh ta nhẹ nhàng ghé sát tai bạn."
  },
  AvgDialog_131205_Content_23 = {
    Text = "Kế hoạch ám sát đã bị lộ, lộ trình của Đại Công rất có thể sẽ thay đổi. Khi có tin tức mới, tuyến trên sẽ thông báo cho các cậu ngay lập tức. Hãy sẵn sàng, %player%."
  },
  AvgDialog_131205_Content_24 = {
    Text = "Một khẩu súng lục Browning mới tinh được đặt nhẹ nhàng vào tay bạn. Khi bạn ngẩng đầu lên lần nữa, khuôn mặt của người phục vụ đã trở lại nụ cười thân thiện, sau khi cúi chào các bạn, anh ta đã bưng khay trở về nhà bếp."
  },
  AvgDialog_131205_Content_25 = {
    Text = "Ký ức quá mức tích tụ trong tâm trí của bạn, bạn đau đớn xoa xoa trán đang căng lên."
  },
  AvgDialog_131205_Content_26 = {
    Text = "Hai đoạn ký ức khác nhau tồn tại trong một bộ não, đối với người lần đầu trải nghiệm, cảm giác này thật sự không vui vẻ lắm."
  },
  AvgDialog_131205_Content_27 = {
    Text = "Cũng tốt, so với việc đối mặt với Toguwaibo, cơn đau đầu này giống như đang được mát xa."
  },
  AvgDialog_131205_Content_28 = {
    Text = "Ký ức mách bảo tôi rằng, tôi sẽ tuân theo chỉ thị của Hội Phục Quốc, hai tiếng nữa, dùng khẩu súng này ám sát Thái tử Đế quốc Phio đến thăm……"
  },
  AvgDialog_131205_Content_29 = {
    Text = "Bạn vuốt ve những đường vân của khẩu súng lục, sắp xếp lại trong tâm trí mình đoạn ký ức thuộc về thế giới này."
  },
  AvgDialog_131205_Content_3 = {
    Text = "Bánh xe lăn qua mặt đường sỏi đá gập ghềnh, tiếng chuông giận dữ gào thét về phía đoàn diễu hành khổng lồ, làm bùng lên một đợt khói bụi và những lời nguyền rủa."
  },
  AvgDialog_131205_Content_30 = {
    Text = "Khi bạn chưa kịp mở miệng tiếp tục hỏi, một luồng ánh sáng mạnh chiếu vào quán cà phê. Đôi ủng quân đội va chạm với sàn bê tông phát ra âm thanh trong trẻo, tiến đến trước quầy bar."
  },
  AvgDialog_131205_Content_31 = {
    Text = "Chào các vị cảnh sát, xin hỏi……"
  },
  AvgDialog_131205_Content_32 = {
    Text = "Chưa để anh ta nói xong, một viên cảnh sát đã nhanh chóng tiến lên, giữ chặt hai tay anh ta ở phía sau, đầu đè lên quầy bar."
  },
  AvgDialog_131205_Content_33 = {
    Text = "Trong ánh mắt hoảng sợ của anh ta, một khẩu súng được chĩa vào trán của anh."
  },
  AvgDialog_131205_Content_34 = {
    Text = "Thành viên của Quốc hội phục hưng Borsante. Bạn có mười giây để nói cho tôi biết đồng bọn của bạn ở đâu."
  },
  AvgDialog_131205_Content_35 = {
    Text = "Người hầu thở hổn hển vì sợ hãi. Trong lúc giãy giụa dữ dội, anh ta nhìn về phía góc đại sảnh."
  },
  AvgDialog_131205_Content_36 = {
    Text = "Chỗ ngồi mà các bạn vừa ngồi đã không còn ai từ lâu, phía trên nửa tách cà phê chưa uống hết, hơi nóng yếu ớt nhẹ nhàng tỏa tan."
  },
  AvgDialog_131205_Content_38 = {
    Text = "Ở đây có lẽ tạm thời an toàn rồi."
  },
  AvgDialog_131205_Content_39 = {
    Text = "Các bạn rời khỏi cửa sau của quán cà phê, như hai giọt nước không đáng chú ý, hòa vào đám đông ồn ào."
  },
  AvgDialog_131205_Content_4 = {
    Text = "Bạn vẫy tay, đuổi đi những bụi bẩn từ màn cửa của quán cà phê len lỏi vào."
  },
  AvgDialog_131205_Content_40 = {
    Text = "Tình huống hiện tại này… đoạn ký ức khác nhau này, rốt cuộc là chuyện gì vậy?"
  },
  AvgDialog_131205_Content_41 = {
    Text = "Bước lên sân khấu của nhà hát số phận, bạn sẽ trở thành một nhân vật trên sân khấu. Mỗi nhân vật đều có cuộc đời riêng của mình."
  },
  AvgDialog_131205_Content_42 = {
    Text = "Thế giới này nằm ở một chiều xa xôi, bạn chưa bao giờ nghe thấy, chưa bao giờ đặt chân đến. Nhưng với tư cách là một nhân vật sinh ra trong thế giới này, bạn đã hiểu rõ nó như lòng bàn tay."
  },
  AvgDialog_131205_Content_43 = {
    Text = "Chào mừng đến với một trong những sân khấu của ta, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131205_Content_44 = {
    Text = "Ý của bạn là…… bạn có thể kết nối các thế giới khác thông qua sân khấu ?"
  },
  AvgDialog_131205_Content_45 = {
    Text = "Arachne hiểu được ý nghĩa trong ánh mắt nóng bỏng của bạn. Cô ấy nâng ly cà phê mang đi từ quán, nghiêm túc thưởng thức, khẽ lắc đầu."
  },
  AvgDialog_131205_Content_46 = {
    Text = "Mang theo cà phê và bánh ngọt trốn chạy, điều kỳ quái này hoàn toàn không gây chú ý cho bạn. Nó xảy ra một cách hài hòa trên người Arachne, tự nhiên như thể là một phần của số phận cô ấy."
  },
  AvgDialog_131205_Content_47 = {
    Text = "Phu nhân Daphodel đã giảng giải cho ngài về nguyên lý xuyên việt chiều không gian. Rào cản giữa các chiều không gian vô cùng kiên cố, mỗi lần xuyên việt đều phải trả một cái giá thảm khốc."
  },
  AvgDialog_131205_Content_48 = {
    Text = "Nhưng bây giờ chúng ta không phải đã ở đây rồi sao……"
  },
  AvgDialog_131205_Content_49 = {
    Text = "Sân khấu của nhà hát có thể kết nối tạm thời vận mệnh của các thế giới khác nhau."
  },
  AvgDialog_131205_Content_5 = {
    Text = "Một phần bánh cuộn thịt nướng, một phần bánh Sacher, hai ly cà phê Hervats. Cảm ơn."
  },
  AvgDialog_131205_Content_50 = {
    Text = "Chúng ta bây giờ chỉ là hai nhân vật chìm trong sân khấu, là hai hình chiếu thoáng qua trong thế giới này."
  },
  AvgDialog_131205_Content_51 = {
    Text = "Hình chiếu…… ngay cả hình chiếu cũng được, bạn có thể giúp tôi trở về bằng cách này không……"
  },
  AvgDialog_131205_Content_52 = {
    Text = "Vô cùng xin lỗi, %player%. Cánh cửa mà ngài đã đóng lại, đã chặn đứng ánh mắt của Tohvapo, đồng thời cũng cắt đứt sợi tơ vận mệnh."
  },
  AvgDialog_131205_Content_53 = {
    Text = "Nếu cố gắng ảnh hưởng đến nơi đó, sẽ phải đối mặt với thảm họa mà chúng ta không thể chịu đựng được."
  },
  AvgDialog_131205_Content_54 = {
    Text = "Cô ấy nhìn vẻ mặt thất vọng trên khuôn mặt bạn, mỉm cười đưa chiếc bánh trên đĩa cho bạn."
  },
  AvgDialog_131205_Content_55 = {
    Text = "Xin hãy yên tâm, %player%. Sau khi giải quyết xong chuyện của cô em gái ta, con đường kết nối giữa ngài và Cardas sẽ sớm được mở lại."
  },
  AvgDialog_131205_Content_56 = {
    Text = "Số phận sẽ không phụ lòng mỗi lần đợi, chúng ta cũng không thể phụ lòng mỗi món quà của số phận. Thử xem nhé."
  },
  AvgDialog_131205_Content_57 = {
    Text = "Bạn hít một hơi thật sâu, cầm chiếc bánh ngọt và nhẹ nhàng cắn một miếng. Hương vị ngọt ngào khiến bạn gần như quên đi cảm giác khó chịu do hai ký ức khác nhau va chạm mang lại."
  },
  AvgDialog_131205_Content_58 = {
    Text = "Hừm……Nghe nói mỗi lần Đại Công Flavian đến đây, đều phải thưởng thức loại bánh đặc sản này. Là một Thái tử, gu thẩm mỹ của ông ấy quả thực không tồi."
  },
  AvgDialog_131205_Content_59 = {
    Text = "Vậy, Nefreya đã ảnh hưởng đến điều gì của thế giới này? Chúng ta nên sửa chữa như thế nào…"
  },
  AvgDialog_131205_Content_6 = {
    Text = "Bạn đưa thực đơn làm bằng da cừu cho người phục vụ, buồn bã nhìn ra con đường quen thuộc bên ngoài."
  },
  AvgDialog_131205_Content_60 = {
    Text = "Khi bạn đang nói, Arachne dường như bị một cái gì đó thu hút, ngẩng đầu nhìn một cái về những sợi tơ trên không trung mà bạn không thể nhìn rõ."
  },
  AvgDialog_131205_Content_61 = {
    Text = "Cô ấy mỉm cười, uống hết ngụm cà phê cuối cùng trong cốc, đưa vài đồng tiền cùng với chiếc cốc còn lại cho một người phục vụ tình cờ đi qua, người đang vội quay về quán cà phê, và nhẹ nhàng cảm ơn anh ta."
  },
  AvgDialog_131205_Content_62 = {
    Text = "Cô ấy đã tìm thấy chúng ta rồi, đúng lúc. Xin hãy cẩn thận, %player%."
  },
  AvgDialog_131205_Content_63 = {
    Text = "Rầm——"
  },
  AvgDialog_131205_Content_64 = {
    Text = "Bạn theo bản năng cúi người xuống, một viên đạn gần như bay qua đỉnh đầu bạn."
  },
  AvgDialog_131205_Content_65 = {
    Text = "Ngay bên kia"
  },
  AvgDialog_131205_Content_66 = {
    Text = "Là sát thủ của Hội phục quốc! Bắt họ lại"
  },
  AvgDialog_131205_Content_67 = {
    Text = "Dưới sự dẫn đường của vài người dân, một nhóm cảnh sát rẽ đám đông, bao vây lại phía các bạn."
  },
  AvgDialog_131205_Content_68 = {
    Text = "Khi tiến lại gần các bạn, cơ thể chúng bắt đầu biến hình, trên những đốt chân nhện đen sẫm, những móng vuốt sắc bén vung về phía các bạn——"
  },
  AvgDialog_131205_Content_7 = {
    Text = "Con phố này thật sự cần mở rộng một chút, hồi nhỏ nơi đây vẫn như vậy, ngoài việc ngày càng xuống cấp ra, nhiều năm qua thật sự không có gì thay đổi."
  },
  AvgDialog_131205_Content_8 = {
    Text = "Chính quyền quả thực không giỏi xây dựng, điều duy nhất họ biết làm là bán đất của Hervats, và cung kính dâng bánh lên cho hoàng thất."
  },
  AvgDialog_131205_Content_9 = {
    Text = "Dân lưu, biểu tình, không thể không chọn thời gian này để thăm công tước… Thầy Arachne, bài tập nghiên cứu dân gian của em có thể nộp muộn một chút không? Gần đây hoạt động của Hội phục quốc đã chiếm quá nhiều sức lực của em."
  },
  AvgDialog_131206_Content_10 = {
    Text = "Chít—— chít—— nữ thần số phận xoay vòng quay của cô ấy."
  },
  AvgDialog_131206_Content_11 = {
    Text = "Chít—— chít—— sợi chỉ số phận quấn chặt trong tay cô ấy."
  },
  AvgDialog_131206_Content_12 = {
    Text = "Những con rối xếp hàng nhập trường, bước vào lưới lớn của số phận."
  },
  AvgDialog_131206_Content_13 = {
    Text = "Chúng nhảy múa. Chúng hát ca. Chít chít—— chít chít——"
  },
  AvgDialog_131206_Content_14 = {
    Text = "Chúng đã chết cùng với mạng lưới khổng lồ, lặng lẽ không một tiếng động."
  },
  AvgDialog_131206_Content_16 = {
    Text = "Chủ nhân, vở kịch mới của chúng ta đã được trình diễn."
  },
  AvgDialog_131206_Content_17 = {
    Text = "Cửa trở về Cađas đã kịp thời đóng lại, vị đó {Male=quý ông,Female=quý cô} đã đến trong thành phố."
  },
  AvgDialog_131206_Content_18 = {
    Text = "Thế nào, bạn có thích vở kịch mới này không?"
  },
  AvgDialog_131206_Content_19 = {
    Text = "Ừm…… có lẽ có chút phức tạp quá?"
  },
  AvgDialog_131206_Content_2 = {
    Text = "Thành phố sương mù chưa tỉnh"
  },
  AvgDialog_131206_Content_20 = {
    Text = "Câu chuyện đơn giản thì tự nhiên sẽ nhẹ nhàng, nhưng đối với một số người, những câu chuyện như vậy không thể viết nên số phận của họ."
  },
  AvgDialog_131206_Content_21 = {
    Text = "Cảm xúc mãnh liệt, bước ngoặt dữ dội, tình tiết lay động lòng người, kết cục bi tráng……"
  },
  AvgDialog_131206_Content_22 = {
    Text = "Những điều này, chính là định mệnh thuộc về\"Anh hùng\"."
  },
  AvgDialog_131206_Content_23 = {
    Text = "Đi đi, đến lượt bạn rồi."
  },
  AvgDialog_131206_Content_24 = {
    Text = "Thiếu nữ phủ phục hành lễ. Trong khoảnh khắc trán chạm sàn, cơ thể cô tan rã tứ phía, máu thịt và da thịt đều hóa thành những con nhện màu tím nhạt, tản mát biến mất vào các góc phòng."
  },
  AvgDialog_131206_Content_26 = {
    Text = "<Shake:khụ khụ…… khụ khụ……>"
  },
  AvgDialog_131206_Content_27 = {
    Text = "Dưới thân là mặt đường nhựa cứng. Bạn loạng choạng đứng dậy, mạnh mẽ xoa xoa cái đầu hỗn loạn của mình."
  },
  AvgDialog_131206_Content_28 = {
    Text = "Vừa mới…… đã xảy ra……"
  },
  AvgDialog_131206_Content_29 = {
    Text = "A! Đường dẫn của Cađas!"
  },
  AvgDialog_131206_Content_3 = {
    Text = "Kèn tấu hoa xoang. Dũng giả áo đen lên sân khấu."
  },
  AvgDialog_131206_Content_30 = {
    Text = "Bạn đột ngột tỉnh dậy, ngẩng đầu nhìn về bầu trời."
  },
  AvgDialog_131206_Content_31 = {
    Text = "Trên bầu trời xanh thẳm, ánh nắng rực rỡ chiếu xuống, không còn dấu vết nào của mặt trời đen và chiều không gian tồn tại."
  },
  AvgDialog_131206_Content_32 = {
    Text = "Cái này…… người này thật kỳ lạ……{Male=Anh ấy,Female=Cô ấy} vừa rơi từ trên trời xuống sao?"
  },
  AvgDialog_131206_Content_33 = {
    Text = "Ừ, theo tôi biết, xung quanh có một công ty công nghệ đang thử nghiệm máy bay, {Male=anh ấy,Female=cô ấy} chắc hẳn là một người thử nghiệm máy bay."
  },
  AvgDialog_131206_Content_34 = {
    Text = "Ừ… đây là…"
  },
  AvgDialog_131206_Content_35 = {Text = "Người."},
  AvgDialog_131206_Content_36 = {
    Text = "Đám đông dày đặc xuất hiện trong tầm mắt bị ánh sáng chói làm đau."
  },
  AvgDialog_131206_Content_37 = {
    Text = "Một thành phố phồn hoa như Londinium đưa bạn trở về ký ức xa xôi nơi Kazdel."
  },
  AvgDialog_131206_Content_38 = {
    Text = "Đường phố tắc nghẽn, đám đông vây quanh, những cửa hàng sắc màu rực rỡ khắp nơi..."
  },
  AvgDialog_131206_Content_39 = {
    Text = "Thế giới của chiều này đã giảm mạnh dân số do rỗng rỗng, ngay cả trong Thành Phố Mộ Bia bạn cũng chưa từng thấy một cảnh tượng phồn vinh như vậy."
  },
  AvgDialog_131206_Content_4 = {
    Text = "Ôi, Cađas, quê hương trong giấc mơ của tôi! Bây giờ, tôi cuối cùng có thể trở về"
  },
  AvgDialog_131206_Content_40 = {
    Text = "Xin hỏi…… đây là đâu?"
  },
  AvgDialog_131206_Content_41 = {
    Text = "Ha, lạ thật, lại có người đến tên của Lentiennam cũng chưa nghe qua? Đây chính là thành phố vĩ đại nhất trên thế giới"
  },
  AvgDialog_131206_Content_42 = {
    Text = "<Shake:!!!>"
  },
  AvgDialog_131206_Content_43 = {
    Text = "Bạn nói đây gọi là gì?"
  },
  AvgDialog_131206_Content_44 = {
    Text = "Bạn chắc chắn rằng bạn đã nghe thấy bốn từ đó."
  },
  AvgDialog_131206_Content_45 = {
    Text = "Đầu óc mơ màng lập tức tỉnh táo, bạn đột ngột đứng dậy, nhìn quanh cảnh tượng xung quanh."
  },
  AvgDialog_131206_Content_46 = {
    Text = "Ngã tư Brick, dấu ấn mờ nhạt trên biển chỉ dẫn giống hệt như trong ký ức của bạn."
  },
  AvgDialog_131206_Content_47 = {
    Text = "Cửa hàng sách cũ gấp nếp thời gian, mỗi lần lén lút ra khỏi trường, điều bạn thích nhất chính là trốn ở đây xem trộm tiểu thuyết trinh thám."
  },
  AvgDialog_131206_Content_48 = {
    Text = "Cửa hàng tạp hóa Chợ Hương, Giáo sư Dexter luôn nhờ bạn mang về một chai rượu vàng từ đây. Một trò đùa nhỏ của N."
  },
  AvgDialog_131206_Content_49 = {
    Text = "Nhà hoa sương mai. Tại buổi lễ kỷ niệm một năm bạn trở thành Người Giữ Gìn, Ramona đã dự định đặt cho bạn một bó hoa rực rỡ nhất toàn Lentiennam…"
  },
  AvgDialog_131206_Content_5 = {
    Text = "Thầy cô của tôi, đồng đội của tôi, bạn thân của tôi, và... mọi thứ của tôi."
  },
  AvgDialog_131206_Content_51 = {
    Text = "Lentiennam…… tôi thật sự…… đã trở về?"
  },
  AvgDialog_131206_Content_52 = {
    Text = "Xin hỏi…… bây giờ Misaque thế nào rồi ?"
  },
  AvgDialog_131206_Content_53 = {
    Text = "Misaque? Vị này{Male=ông, Female=chị} nói về nơi đó chúng tôi chưa từng nghe nói."
  },
  AvgDialog_131206_Content_54 = {
    Text = "Vậy rỗng rỗng thế nào? Tình hình thiệt hại ở đây ra sao?"
  },
  AvgDialog_131206_Content_55 = {
    Text = "Thảm họa? Thành phố này đã tồn tại hơn hai nghìn năm, chưa bao giờ có bất kỳ thảm họa nào."
  },
  AvgDialog_131206_Content_56 = {
    Text = "Đứa trẻ, tôi nghĩ bạn đã mệt rồi… Ngồi một chút trên ghế dài trong công viên, ăn chút gì đó nhé. Tôi có một ít ở đây."
  },
  AvgDialog_131206_Content_57 = {
    Text = "Người già đưa bánh mì và nước vừa mua từ cửa hàng tạp hóa cho bạn."
  },
  AvgDialog_131206_Content_58 = {
    Text = "À, cảm ơn bạn nhiều…… nhưng bây giờ tôi không đói, tôi chỉ là…… có một số vấn đề chưa nghĩ thông……"
  },
  AvgDialog_131206_Content_59 = {
    Text = "<Small:Điều này không thể nào…… không có Misaque, cũng không có rỗng rỗng……>"
  },
  AvgDialog_131206_Content_6 = {
    Text = "Miễn là xuyên qua cánh cửa tối tăm này, tôi sẽ lại một lần nữa hội ngộ với chúng"
  },
  AvgDialog_131206_Content_60 = {
    Text = "Ông ơi, người này kỳ lạ quá, sao cứ tự nói chuyện một mình vậy?"
  },
  AvgDialog_131206_Content_61 = {
    Text = "Đừng nói bừa, {Male=anh ấy,Female=cô ấy} có thể đã gặp phải khó khăn gì đó. Đối với vị khách từ xa đến, cần phải lịch sự."
  },
  AvgDialog_131206_Content_62 = {
    Text = "Một bàn tay nhẹ nhàng vỗ lên vai bạn. Bạn quay đầu lại, thấy một khuôn mặt xa lạ."
  },
  AvgDialog_131206_Content_63 = {
    Text = "Chúng tôi là cảnh sát tuần tra ở gần đây, thuộc quyền quản lý của hội nghị thẩm tra. Đây là giấy tờ của tôi."
  },
  AvgDialog_131206_Content_64 = {
    Text = "Xin chào bạn. Có một công dân tốt bụng đã nói với chúng tôi rằng có một vị hành khách bị lạc đường trong thành phố xinh đẹp của chúng ta."
  },
  AvgDialog_131206_Content_65 = {
    Text = "Xin hỏi vị {Male=ông, Female=cô} này, có cần giúp đỡ gì không ạ?"
  },
  AvgDialog_131206_Content_66 = {
    Text = "Bạn suy nghĩ trong một khoảnh khắc ngắn ngủi. Trước khi làm rõ tình hình, bạn cần tránh thu hút sự chú ý của người khác càng nhiều càng tốt."
  },
  AvgDialog_131206_Content_67 = {
    Text = "À... cảm ơn các bạn đã quan tâm. Tôi chỉ là đi dạo trên đường rồi ngất xỉu, không gặp phải vấn đề gì."
  },
  AvgDialog_131206_Content_68 = {
    Text = "Cảm ơn các bạn rất nhiều. Chúng tôi còn việc phải làm, xin phép đi trước một bước…"
  },
  AvgDialog_131206_Content_69 = {
    Text = "Thì ra là vậy. Vậy xin phiền ông thêm chút thời gian, tôi có vài câu hỏi muốn nhờ ông giải đáp."
  },
  AvgDialog_131206_Content_7 = {
    Text = "Nhưng tại sao cánh cửa gần trong tầm tay lại đóng lại? Bầu trời tàn nhẫn này, tại sao lại bỏ rơi tôi?"
  },
  AvgDialog_131206_Content_70 = {
    Text = "Cảnh sát mỉm cười tiến lại gần các bạn, vỗ nhẹ lên vai bạn để phủi bụi."
  },
  AvgDialog_131206_Content_71 = {
    Text = "<Red:Người Giữ Bí Mật>, tôi nên gọi ngươi như vậy, đúng không?"
  },
  AvgDialog_131206_Content_72 = {
    Text = "Tôi muốn hỏi... nghi thức chào đón dành cho tôi lần này, ngươi có hài lòng không?"
  },
  AvgDialog_131206_Content_73 = {Text = "!!!"},
  AvgDialog_131206_Content_74 = {
    Text = "Một tràng âm thanh nhung nhúc khiến người ta buồn nôn vang lên. Hàng loạt chi tiết chân nhện khổng lồ xuyên thủng cơ thể cảnh sát và người qua đường, huyết tương đặc quánh tanh nồng bắn tung tóe lên người các bạn."
  },
  AvgDialog_131206_Content_75 = {
    Text = "Thay mặt số mệnh gửi lời chào đến ngươi, Người Giữ Bí Mật thân mến."
  },
  AvgDialog_131206_Content_76 = {
    Text = "Vị khách quý đã đến nhà hát của chúng ta, hãy đưa {Male=他,Female=她} vào chỗ ngồi, các con."
  },
  AvgDialog_131206_Content_77 = {
    Text = "Vâng, thưa chủ nhân."
  },
  AvgDialog_131206_Content_78 = {
    Text = "Cẩn thận!"
  },
  AvgDialog_131206_Content_8 = {
    Text = "Chìa khóa bạc thân yêu của tôi... xin hãy soi sáng con đường của tôi... xin hãy cho tôi những mảnh ghép của câu trả lời..."
  },
  AvgDialog_131206_Content_9 = {
    Text = "Ánh đèn chuyển đổi. Ca giả bạc lên sân khấu."
  },
  AvgDialog_131207_Content_1 = {
    Text = "Bóng phản chiếu của thần minh"
  },
  AvgDialog_131207_Content_10 = {
    Text = "Còn cơ hội để dừng lại, Nefreya."
  },
  AvgDialog_131207_Content_11 = {
    Text = "Tan biến hoàn toàn, thì sao chứ?"
  },
  AvgDialog_131207_Content_12 = {
    Text = "Nefreya mỉm cười một cách khinh bạc, quay người nhìn về phía những người phục vụ đầy tín tâm."
  },
  AvgDialog_131207_Content_13 = {
    Text = "Nói cho tôi biết, trẻ em, các bạn có sợ không?"
  },
  AvgDialog_131207_Content_14 = {
    Text = "Phản hồi Arachne là một tràng cười tuyệt vọng."
  },
  AvgDialog_131207_Content_15 = {
    Text = "Haha haha haha! Chúng tôi là những người bị số phận bỏ rơi, không có thảm họa nào khiến chúng tôi phải sợ hãi... Xin hãy mang lại sự giải thoát cho chúng tôi, chủ nhân của tôi."
  },
  AvgDialog_131207_Content_16 = {
    Text = "Đứa trẻ ngoan."
  },
  AvgDialog_131207_Content_17 = {
    Text = "Nefreya ủng hộ vỗ nhẹ lên đầu phục vụ."
  },
  AvgDialog_131207_Content_18 = {
    Text = "Bạn đã sai, chị gái tốt của tôi. Số phận đã sớm tuyên án chúng ta án tử hình và tù chung thân. Một đám linh hồn bị bỏ rơi, sẽ không còn cầu xin sự thương xót của số phận nữa."
  },
  AvgDialog_131207_Content_19 = {
    Text = "Chúng ta, đang trả thù số phận."
  },
  AvgDialog_131207_Content_2 = {
    Text = "Trên sân khấu vĩ đại mà bạn chưa từng thấy, vòng quay đen của Nefreya cô đơn đứng sừng sững ở giữa sân khấu. Ở giữa vòng tròn khổng lồ, ánh sáng xanh u ám dường như không bao giờ tắt chiếu sáng khuôn mặt vui vẻ của Nefreya."
  },
  AvgDialog_131207_Content_20 = {
    Text = "Không biết là vô ý hay hữu ý, trong sợi chỉ số phận mà Nefreya đang chơi đùa, có một sợi lặng lẽ đứt đoạn."
  },
  AvgDialog_131207_Content_21 = {
    Text = "Khi sợi dây đứt gãy, một sân khấu không xa các bạn bỗng vỡ vụn, biến thành những mảnh bay tứ tán, diệt vong trong không gian chiều vô tận của nhà hát."
  },
  AvgDialog_131207_Content_22 = {
    Text = "Ôi, xin lỗi xin lỗi, tôi đã vô tình làm hỏng sợi chỉ của bạn……"
  },
  AvgDialog_131207_Content_23 = {
    Text = "Nhanh tay lên nào, chị gái tốt. Mặc dù sân khấu của nhà hát có nhiều, nhưng nếu lại bị hỏng thì chắc bạn cũng sẽ đau lòng chứ?"
  },
  AvgDialog_131207_Content_24 = {
    Text = "Tiếng thở dài của Arachne hầu như không thể nghe thấy. Khi mở mắt lần nữa, cô ấy nâng ngón tay lên, nhẹ nhàng chạm vào đỉnh đầu bạn."
  },
  AvgDialog_131207_Content_25 = {
    Text = "Arachne! Đừng như vậy… chúng ta chắc chắn có thể tìm ra cách khác…"
  },
  AvgDialog_131207_Content_26 = {
    Text = "Hãy bước lên sân khấu, dâng quyền năng chất thể cho sứ đồ của thần minh… Đây là số mệnh không thể tránh khỏi của ngươi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131207_Content_27 = {
    Text = "Giọng nói không thể từ chối của Arachne vọng lại trong thế giới tinh thần của bạn. Khi bạn nâng bước chân tiến về phía sân khấu, ba luồng lực lượng đã lâu không gặp trong cơ thể bạn bắt đầu bồn chồn không yên."
  },
  AvgDialog_131207_Content_28 = {
    Text = "Chúng quấn lấy nhau, va chạm trong cơ thể bạn, chống lại những lời tiên tri như Arachne."
  },
  AvgDialog_131207_Content_29 = {
    Text = "Ôi, không hổ danh là ba Plasmid… Chỉ với một chút quyền năng như vậy, lại có thể ảnh hưởng đến vật chủ từ chiều không gian xa xôi như thế."
  },
  AvgDialog_131207_Content_3 = {
    Text = "Nhìn kìa, Người Giữ Bí Mật {Male=先生,Female=小姐}, ánh đèn đẹp biết bao…"
  },
  AvgDialog_131207_Content_30 = {
    Text = "Hãy bảo chúng ngoan ngoãn một chút đi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131207_Content_4 = {
    Text = "Bó ánh sáng này là món quà của số phận, nó sẽ dẫn dắt chúng ta đến miền cực lạc không có đau khổ…"
  },
  AvgDialog_131207_Content_5 = {
    Text = "Nefreya đưa tay ra, vuốt ve những dấu vết ánh sáng để lại trong không gian chiều. Bóng dáng của ngón tay từ từ co lại, bò trên mặt Arachne."
  },
  AvgDialog_131207_Content_6 = {
    Text = "Đến đây đi, chị, nhân vật chính của chúng ta sắp xuất hiện rồi."
  },
  AvgDialog_131207_Content_7 = {
    Text = "……Số mệnh không phải thứ có thể bị đùa bỡn và sửa đổi, Nephreya."
  },
  AvgDialog_131207_Content_8 = {
    Text = "Số mệnh của mỗi người đã được định sẵn, đánh thức vị thần minh ấy, để tất cả kết thúc… Cưỡng ép thay đổi số mệnh sẽ mang đến tai ương mà ngươi không thể lường trước."
  },
  AvgDialog_131207_Content_9 = {
    Text = "Dù là thứ ngươi ghét bỏ hay trân trọng, tất cả đều sẽ tan biến trong tai ương."
  },
  AvgDialog_131208_Content_1 = {
    Text = "Phán quyết"
  },
  AvgDialog_131208_Content_10 = {
    Text = "Cô gái hít một hơi thật sâu, nở một nụ cười mãn nguyện."
  },
  AvgDialog_131208_Content_11 = {
    Text = "Hoa iris đã bắt đầu nở…… một mùa xuân nữa thật sự đã đến."
  },
  AvgDialog_131208_Content_12 = {
    Text = "Này, Tiểu Phù, tôi đã hỏi bạn mùa nào bạn thích nhất chưa?"
  },
  AvgDialog_131208_Content_13 = {
    Text = "……Tôi không có mùa nào thích, thưa chủ nhân."
  },
  AvgDialog_131208_Content_14 = {
    Text = "Nhàm chán."
  },
  AvgDialog_131208_Content_15 = {
    Text = "Arachne lăn mắt, giơ bàn tay không có sợi chỉ ra, đón ánh nắng chiếu xuống từ bên ngoài cửa sổ."
  },
  AvgDialog_131208_Content_16 = {
    Text = "Tôi thích mọi mùa trong năm, đặc biệt là mùa xuân. Chúng ta đã lâu không ra ngoài rồi……Mấy ngày tới tìm thời gian, chúng ta ra ngoài dạo chơi ngắm cảnh xuân nhé?"
  },
  AvgDialog_131208_Content_17 = {
    Text = "Bên cạnh điền trang nơi tôi sinh ra, có một khu vườn hoa được chăm sóc rất đẹp, chắc chắn các bạn sẽ thích."
  },
  AvgDialog_131208_Content_18 = {
    Text = "Bạn đã đợi ba ngày rồi… đã đến lúc đưa ra quyết định, thưa ngài."
  },
  AvgDialog_131208_Content_19 = {
    Text = "Pelayan thực hiện nhiệm vụ của mình, lời nói lạnh lùng như một cơn mưa lạnh. Dập tắt mùa xuân rực rỡ trong mắt Arachne."
  },
  AvgDialog_131208_Content_2 = {
    Text = "Chít—— chít—— nữ thần số phận xoay vòng quay của cô ấy."
  },
  AvgDialog_131208_Content_20 = {
    Text = "Chít à, chít à……"
  },
  AvgDialog_131208_Content_21 = {
    Text = "Dừng lại một chút, bánh xe dệt lại bắt đầu quay. Tần suất của nó nhẹ nhàng, trong trẻo, không thay đổi theo thời gian."
  },
  AvgDialog_131208_Content_22 = {
    Text = "Vương quốc mà chúng ta đang ở, vừa mới kết thúc một thế kỷ chiến tranh. Người dân đã xây dựng lại thành phố của họ trên đống đổ nát, đang chờ đợi một thời kỳ hòa bình dài lâu."
  },
  AvgDialog_131208_Content_23 = {
    Text = "Nhìn kìa, ở đó……"
  },
  AvgDialog_131208_Content_24 = {
    Text = "Theo ánh mắt của Arachne, cô hầu gái nhìn về bức tranh lớn treo trong đại sảnh. Cô ấy chưa bao giờ hiểu bức tranh đó."
  },
  AvgDialog_131208_Content_25 = {
    Text = "Trong tất cả các tác phẩm vĩ đại của ông Zoss, bức tranh này không ai quan tâm, nhưng đó lại là bức tranh tôi yêu thích nhất."
  },
  AvgDialog_131208_Content_26 = {
    Text = "Những đàn hươu được sáng tạo bằng thite đỏ và cấu trúc hình học, dù chỉ là những ký hiệu trừu tượng, cũng khiến người ta cảm nhận được sức sống mãnh liệt của chúng."
  },
  AvgDialog_131208_Content_27 = {
    Text = "Mỗi lần nhìn thấy nó, tôi lại nhớ đến vở kịch yêu thích nhất của mình……"
  },
  AvgDialog_131208_Content_28 = {
    Text = "Khe nứt đã tồn tại ba ngày rồi, chủ nhân. Số phận của chiều này đã bị ánh mắt của Vị đó xâm nhập."
  },
  AvgDialog_131208_Content_29 = {
    Text = "Nếu tiếp tục như vậy, nơi ánh mắt của Ngài sẽ hủy diệt, không chỉ dừng lại ở đây."
  },
  AvgDialog_131208_Content_3 = {
    Text = "Chít—— chít—— sợi chỉ số phận quấn chặt trong tay cô ấy."
  },
  AvgDialog_131208_Content_30 = {
    Text = "Chít à, chít à."
  },
  AvgDialog_131208_Content_31 = {
    Text = "Cô gái nhắm mắt lại, tận hưởng ánh nắng ấm áp. Căn phòng ấm áp rơi vào im lặng, chỉ có bánh xe dệt vẫn quay với nhịp điệu cổ xưa."
  },
  AvgDialog_131208_Content_32 = {
    Text = "Bạn còn nhớ, chúng ta đã thêu dệt số phận của bao nhiêu thế giới rồi không?"
  },
  AvgDialog_131208_Content_33 = {
    Text = "Tổng cộng có hai mươi bảy cái, chủ nhân."
  },
  AvgDialog_131208_Content_34 = {
    Text = "Cha tôi đã tặng tôi chiếc vòng quay này, tôi từng đi dọc theo những sợi chỉ của nó, gần gũi với cánh cửa sự thật đó. Sau cánh cửa đó, tôi đã thấy số phận mà thế giới này sẽ đón chào..."
  },
  AvgDialog_131208_Content_35 = {
    Text = "Tôi biết điều gì đang chờ đợi tôi ở phía trước. Tôi biết mình nên đưa ra lựa chọn như thế nào… nhưng tôi không thể làm được."
  },
  AvgDialog_131208_Content_36 = {
    Text = "Người thân. Bạn bè. Ký ức. Một lịch sử hoành tráng kéo dài mười bảy nghìn năm. Công nghệ và nghệ thuật như những vì sao..."
  },
  AvgDialog_131208_Content_37 = {
    Text = "Sau khi thấy câu trả lời đó, tôi bắt đầu thêu dệt số phận của thế giới này… Tôi luôn nghĩ, số phận đã ban cho tôi khả năng như vậy, tôi nhất định có thể làm điều gì đó cho thế giới này."
  },
  AvgDialog_131208_Content_38 = {
    Text = "Đây là quê hương của ta, cũng là đứa con của ta……<Shake:Ta……ta không thể làm được>, tiểu Phù……"
  },
  AvgDialog_131208_Content_39 = {
    Text = "Chủ nhân……"
  },
  AvgDialog_131208_Content_4 = {
    Text = "Những con rối xếp hàng nhập trường, bước vào lưới lớn của số phận."
  },
  AvgDialog_131208_Content_40 = {
    Text = "Nữ hầu quỳ xuống, lau đi nước mắt của chủ nhân. Dưới ánh nắng mùa xuân, giọng nói của cô ấy trong trẻo và kiên định."
  },
  AvgDialog_131208_Content_41 = {
    Text = "Ngài đã dự đoán ngày này, vì vậy ngài đã để tôi trở thành nữ hầu bên cạnh ngài."
  },
  AvgDialog_131208_Content_42 = {
    Text = "Tất cả ý nghĩa của cuộc đời tôi, chính là ở khoảnh khắc này, nói cho bạn biết nên làm gì…"
  },
  AvgDialog_131208_Content_43 = {
    Text = "Bạn là chủ nhân của số phận, là người bảo vệ của nhiều chiều không gian này. Đây là một con đường tàn khốc, nhưng bạn đã đưa ra sự lựa chọn."
  },
  AvgDialog_131208_Content_44 = {
    Text = "Ba nữ thần số phận, chịu trách nhiệm dệt may, quyết định... và cắt đứt."
  },
  AvgDialog_131208_Content_45 = {
    Text = "Từ khoảnh khắc bạn đưa ra sự lựa chọn, những điều này, chính là trách nhiệm bạn phải thực hiện."
  },
  AvgDialog_131208_Content_46 = {
    Text = "Arachne ngẩng đầu lên, trong đôi mắt mờ ảo của nàng, vết nứt mà người thường không thể nhìn thấy đang nhấp nháy trên bầu trời. Nó luôn ở đó, bên cạnh ánh nắng ấm áp của ngày xuân, giống như một nụ cười tàn nhẫn."
  },
  AvgDialog_131208_Content_47 = {
    Text = "Khe nứt thì thầm với Arachne, kể cho cô ấy về những tương lai lạnh lẽo. Cô ấy đã chấp nhận lời nguyền này từ rất sớm, và khi tương lai đến, cơ thể cô ấy vẫn run rẩy vì sợ hãi."
  },
  AvgDialog_131208_Content_48 = {
    Text = "Arachne ngồi lại trước khung dệt. Sau nỗi sợ hãi và tuyệt vọng, trên gương mặt nàng hiện lên một vệt ửng đỏ không lành mạnh."
  },
  AvgDialog_131208_Content_49 = {
    Text = "Nàng vuốt ve những sợi chỉ dày đặc, như một người mẹ vuốt ve khuôn mặt đứa con."
  },
  AvgDialog_131208_Content_5 = {
    Text = "Chúng nhảy múa. Chúng hát ca. Chít chít—— chít chít——"
  },
  AvgDialog_131208_Content_50 = {
    Text = "Năm 804, ta vẫn chưa biết nói, quản gia đã chơi một bản piano trong nhà."
  },
  AvgDialog_131208_Content_51 = {
    Text = "\"Đám tang bên sông Loos\" của Elichion, âm thanh của bản nhạc như dòng suối lặng lẽ chảy ngoài thần điện, ta thấy, ngay cả thần minh cũng dừng bước vì tiếng nhạc ấy……"
  },
  AvgDialog_131208_Content_52 = {
    Text = "Một sợi chỉ bị cắt đứt trong im lặng. Nó lặng lẽ trôi nổi trong không trung, trong sóng dư chấn của số phận, lặng lẽ bay lượn."
  },
  AvgDialog_131208_Content_53 = {
    Text = "Âm nhạc trong sảnh đã tắt, chỉ còn đĩa than vẫn đang quay. Những đường nét trên đĩa đã được lấp đầy, tên bài hát được viết bằng chữ hoa đẹp đã bị xóa đi."
  },
  AvgDialog_131208_Content_54 = {
    Text = "Elihion đã đón nhận một số phận khác. Trong thế giới cô đơn này, cuộc đời hào hùng của anh chưa bao giờ tồn tại."
  },
  AvgDialog_131208_Content_55 = {
    Text = "Cassandra, nhà thờ mà cô ấy thiết kế, còn đáng ngưỡng mộ hơn cả những vị thần ở đó……"
  },
  AvgDialog_131208_Content_56 = {
    Text = "Một sợi chỉ nữa đã đứt. Cách hai trăm km, nhà thờ hoành tráng đó vỡ nát, sụp đổ, đôi mắt từ bi của thần tượng tan vỡ, không còn khác gì với bụi đất."
  },
  AvgDialog_131208_Content_57 = {
    Text = "Huyền thoại của Mornlin, opera của Aldo, tác phẩm hội họa của Marmo, thơ của Rovel..."
  },
  AvgDialog_131208_Content_58 = {
    Text = "Sách trở thành mảnh giấy vụn, điêu khắc biến thành những mảnh vỡ, tác phẩm hội họa trở thành những màu sắc hỗn độn."
  },
  AvgDialog_131208_Content_59 = {
    Text = "Cô ấy là một phóng viên ghi chép. Cô ấy là người hành hình. Cô ấy đọc tên của mỗi nghệ sĩ vĩ đại trên thế giới này, cắt đứt sợi dây thuộc về họ."
  },
  AvgDialog_131208_Content_6 = {
    Text = "Ánh nắng chiếu sáng khuôn mặt của chúng, thật vui vẻ——"
  },
  AvgDialog_131208_Content_60 = {
    Text = "Veldburg, một thành phố vĩ đại thuộc về các anh hùng. Nó đã trải qua một trăm lẻ năm trận chiến, ba mươi bảy lần bị tàn phá và xây dựng lại, hai mươi mốt vị quân chủ đã lập công ở đây, chịu đựng thất bại."
  },
  AvgDialog_131208_Content_61 = {
    Text = "Quý tộc ở đây vui ca, dân nghèo ở đây kêu gào, thi nhân để lại những câu thơ đẹp đẽ cho nó, tiếng hát bên dòng sông Nehron và tiếng súng vang vọng trên bầu trời của nó. Lịch sử anh hùng của nó, kết thúc vào ngày hôm nay."
  },
  AvgDialog_131208_Content_62 = {
    Text = "Một nhóm dây chỉ bị cắt đứt bay lượn hỗn loạn, như một điệu múa cuồng loạn. Cách đó hai ngàn ba trăm km, thành phố hùng vĩ ấy đổ sập."
  },
  AvgDialog_131208_Content_63 = {
    Text = "Mười bảy nghìn năm tồn tại, nền văn minh cổ đại kiên cường đứng vững giữa thiên tai và nhân họa, chưa từng gục ngã…"
  },
  AvgDialog_131208_Content_64 = {
    Text = "Suy nhược, run rẩy. Arachne dùng hết sức lực nâng cao tay, nắm chặt sợi chỉ mờ mịt trước mặt."
  },
  AvgDialog_131208_Content_65 = {
    Text = "Sợi chỉ đứt. Tám ngàn km xa, quốc gia cổ đại đồ sộ mang theo nền văn minh nhân loại, chưa bao giờ bị đứt đoạn, đã biến mất trong lịch sử nhân loại, như một làn khói xanh."
  },
  AvgDialog_131208_Content_67 = {
    Text = "Người. Nghệ thuật. Thành phố. Đất nước. Văn minh."
  },
  AvgDialog_131208_Content_68 = {
    Text = "Tất cả đều đang sụp đổ, tất cả đều đang biến mất."
  },
  AvgDialog_131208_Content_69 = {
    Text = "<Shake:Em thấy không, tiểu Phù?> Đứa con đầu tiên của ta đã chết, chính tay ta đã giết nó……"
  },
  AvgDialog_131208_Content_7 = {
    Text = "Chít à, chít à."
  },
  AvgDialog_131208_Content_70 = {
    Text = "Nước mắt rơi xuống một cách yên tĩnh. Arachne mỉm cười yếu ớt, nhìn ra ngoài cửa sổ. Giữa đống đổ nát của cả thế giới, chỉ còn lại ngôi trang viên đang goyang-goyang bên ngoài vẫn còn đứng vững."
  },
  AvgDialog_131208_Content_71 = {
    Text = "Tôi từng nghĩ, trong lúc dệt nên số phận, nếu có thể liên tục nhìn về nơi tôi đã từng sống, sẽ khiến tôi bớt cô đơn trên con đường này."
  },
  AvgDialog_131208_Content_72 = {
    Text = "Thật trẻ con… Đối với một kẻ hành quyết không có sự lựa chọn, tôi đã tự tay chuẩn bị hình phạt tàn nhẫn nhất cho chính mình."
  },
  AvgDialog_131208_Content_73 = {
    Text = "Cô ấy đưa tay ra, gẩy nhẹ sợi chỉ mờ ảo trên đầu mình, mà ngay cả cô cũng không thể nhìn rõ, nối một phần của nó với sợi chỉ cuối cùng của thế giới này."
  },
  AvgDialog_131208_Content_74 = {
    Text = "Chủ nhân, ngài đang nói……?"
  },
  AvgDialog_131208_Content_75 = {
    Text = "Lãng mạn mang đến sự ngu dốt, lòng tốt mang đến sự mong manh, ký ức mang đến nỗi đau…"
  },
  AvgDialog_131208_Content_76 = {
    Text = "Tôi đã suy nghĩ kỹ, Tiểu Phù. Tôi là Hành hình giả bị lời nguyền, những điều tốt đẹp đó, không nên tồn tại trên người tôi."
  },
  AvgDialog_131208_Content_77 = {
    Text = "Ngài định……giết chết một phần của chính mình sao? Nhưng……đây đều là những phần ngài trân quý nhất, ngài sao có thể……"
  },
  AvgDialog_131208_Content_78 = {
    Text = "Khi còn rất nhỏ, tôi đã có giấc mơ đầu tiên trong đời."
  },
  AvgDialog_131208_Content_79 = {
    Text = "Arachne đưa tay ra, đón lấy tia nắng đang chiếu rọi lên đống phế tích vô tận."
  },
  AvgDialog_131208_Content_8 = {
    Text = "Bánh xe dệt cổ xưa phát ra âm điệu êm dịu, cô gái ngồi trước bánh xe, nhẹ nhàng hát một bài đồng dao với giai điệu đơn giản."
  },
  AvgDialog_131208_Content_80 = {
    Text = "Trong giấc mơ, tôi đang đi trên mặt hồ. Bên cạnh tôi là những đống đổ nát và xương khô vô tận, trong khi dưới mặt hồ, bóng dáng thời thơ ấu của tôi đang đi trong một vương quốc xinh đẹp."
  },
  AvgDialog_131208_Content_81 = {
    Text = "Không có cái chết, không có khổ đau, không có sự quên lãng. Ánh nắng dịu dàng mãi mãi chiếu sáng nơi đó, đám đông bên cạnh cô ấy vui hát, không bao giờ ngừng nghỉ…"
  },
  AvgDialog_131208_Content_82 = {
    Text = "Tôi không thể thấy sợi tơ của mình dẫn đến đâu, nhưng tôi nghĩ, bây giờ tôi đã nhìn rõ số phận mà giấc mơ đó báo hiệu."
  },
  AvgDialog_131208_Content_83 = {
    Text = "Cô ấy cố gắng nhếch môi, có thể là để hướng về nữ hầu của mình, hoặc có thể là để hướng về một thứ gì đó khác."
  },
  AvgDialog_131208_Content_84 = {
    Text = "Mẹ từng nói, đảo ngược tên Arachne lại, đọc thành Nephreya. Trong truyền thuyết của thế giới này, đó là tên của Thần Mùa Xuân."
  },
  AvgDialog_131208_Content_85 = {
    Text = "Tôi thích mỗi một mùa, đặc biệt là mùa xuân. Mùa xuân nhỏ bé hơn số phận, nhỏ bé rất nhiều, rất nhiều. Nhưng số phận luôn dẫn đến cái chết, còn mùa xuân, mùa xuân chỉ mang đến sinh mới…"
  },
  AvgDialog_131208_Content_86 = {
    Text = "Cô ấy nhìn ra ngoài cửa sổ. Ở hai bên khung cửa, số phận và mùa xuân lần cuối cùng đối diện nhau."
  },
  AvgDialog_131208_Content_87 = {
    Text = "Rời xa tôi đi, hình bóng của tôi, em gái yêu quý của tôi. Cùng với tất cả những phẩm chất tốt đẹp trên người chúng ta, và tất cả những kỷ niệm đẹp của chúng ta."
  },
  AvgDialog_131208_Content_88 = {
    Text = "Số phận……Ta sẽ hiến tế một phần của chính mình cho ngươi. Con đường gian nan này, ta sẽ thay nó bước tiếp."
  },
  AvgDialog_131208_Content_89 = {
    Text = "Arachne nhẹ nhàng vuốt ve sợi chỉ quấn quýt vào nhau. Sợi chỉ rung nhẹ, dường như đang giãy giụa, kêu khóc."
  },
  AvgDialog_131208_Content_9 = {
    Text = "Một tia nắng từ ngoài cửa sổ rọi xuống, rơi lên tấm biển khắc chữ \"Moirai\" bên cạnh guồng quay sợi."
  },
  AvgDialog_131208_Content_90 = {
    Text = "Nước mắt của cô ấy chảy qua sợi dây đó, rơi xuống biển tên của \"Moylai\"."
  },
  AvgDialog_131208_Content_91 = {
    Text = "Bạn đã tự do rồi, \"Arachne\"."
  },
  AvgDialog_131208_Content_92 = {
    Text = "Chít——."
  },
  AvgDialog_131208_Content_93 = {
    Text = "Sợi chỉ đứt gãy. Dưới ánh nắng ấm áp của mùa xuân, bánh xe dệt phát ra tiếng thở dài cuối cùng."
  },
  AvgDialog_131209_Content_1 = {
    Text = "Đoàn Viên"
  },
  AvgDialog_131209_Content_10 = {
    Text = "Nếu tôi chọn làm một diễn viên opera, thì hàng dài mua vé ở nhà hát chắc chắn sẽ kéo dài ra ngoài ba dãy phố."
  },
  AvgDialog_131209_Content_11 = {
    Text = "Tiếc thật, những con rối của Lentiennam không có cơ hội để thấy màn biểu diễn tuyệt vời của tôi. Nhìn vậy, bạn thật may mắn, cô bé dễ thương."
  },
  AvgDialog_131209_Content_12 = {
    Text = "Nefreya nhẹ nhàng véo má cô gái với tình cảm, giống như mẹ âu yếm vuốt ve con gái."
  },
  AvgDialog_131209_Content_13 = {
    Text = "Giữa đại sảnh nhà thờ, những chiếc đinh thép xuyên qua ngực, bụng, hai vai, xương ống chân, lòng bàn tay của cô gái, xuyên qua từng bộ phận trên cơ thể cô có thể treo và cảm nhận nỗi đau, đóng chặt cô vào giá đèn hình bánh xe khổng lồ."
  },
  AvgDialog_131209_Content_14 = {
    Text = "Neferet đưa bàn tay đầy máu lên mũi, đắm chìm trong cơn mê, nhắm mắt lại."
  },
  AvgDialog_131209_Content_15 = {
    Text = "À…… mùi vị của sự sống, thật là tươi sống."
  },
  AvgDialog_131209_Content_16 = {
    Text = "Trong những năm qua, tôi đã thử rất nhiều lần, cắn nát cơ thể của trẻ em, cắn nát cơ thể của chính mình, nhưng không thể nếm được một chút hương vị của sinh lực nào."
  },
  AvgDialog_131209_Content_17 = {
    Text = "Số phận đúng đắn. Sinh lực mãnh liệt. Thật đáng ghen tị… Nhưng bạn có biết không? Lẽ ra, bạn cũng nên giống như chúng tôi, bị vứt vào đống rác của số phận."
  },
  AvgDialog_131209_Content_18 = {
    Text = "Bạn không cần phải ăn uống, không bao giờ nói lời nào. Ngoài những ký ức được giữ lại cho cô ấy, bạn không có gì cả, không biết gì cả."
  },
  AvgDialog_131209_Content_19 = {
    Text = "Số phận đã sớm bỏ rơi bạn, đứa trẻ đáng thương. Bạn chỉ là một con búp bê để cô ấy tự an ủi, một người canh giữ những ký ức của cô ấy, lẻ loi lang thang trên sân khấu giả dối này…"
  },
  AvgDialog_131209_Content_2 = {
    Text = "<Shake:La♪ lala♪>"
  },
  AvgDialog_131209_Content_20 = {
    Text = "Cô ấy nhìn cô gái đã gần như không còn hơi thở, giọng nói thầm thì run rẩy vì nỗi buồn, những ngón tay lạnh giá nhẹ nhàng chỉnh sửa những sợi tóc rối bên thái dương của cô gái."
  },
  AvgDialog_131209_Content_21 = {
    Text = "Bây giờ, người mẹ tàn nhẫn của số phận con sắp đến rồi…… Dù chuyện gì xảy ra, hãy đối mặt với mọi thứ bằng vẻ đẹp nhất, hiểu chưa, em yêu?"
  },
  AvgDialog_131209_Content_23 = {
    Text = "Sau khi mắt đã thích ứng với ánh sáng mờ tối của nhà thờ, thứ đầu tiên thu hút ánh mắt bạn là một loạt bức tranh tường khổng lồ."
  },
  AvgDialog_131209_Content_24 = {
    Text = "Màu nhuộm như chất nhờn được quét lên bức tường cao hàng chục mét, kéo dài liên tục vào bóng tối không thấy tận cùng. Vĩ đại, thiêng liêng, ô uế, như hình ảnh của một thánh nhân cứu rỗi đứng vững trong cống rãnh."
  },
  AvgDialog_131209_Content_25 = {
    Text = "Người chủ nhà thấu hiểu ý người khác đã dọn dẹp cho những người tham quan, trong nhà thờ rộng rãi chỉ còn tiếng bước chân và hơi thở vang vọng. Bạn đến dưới bức tranh tường khổng lồ, ngẩng đầu lên nhìn."
  },
  AvgDialog_131209_Content_26 = {
    Text = "Một người phụ nữ ngồi trước bánh xe dệt, đang dùng kéo cắt đứt sợi chỉ... bức tranh tường này vẽ về bạn?"
  },
  AvgDialog_131209_Content_27 = {
    Text = "Có vẻ đúng như vậy…… Tôi nghĩ, đây là điều mà cô em gái của tôi muốn nói với chúng ta."
  },
  AvgDialog_131209_Content_28 = {
    Text = "Arachne không vội vàng tìm kiếm nơi của \"kỷ niệm\". Cô ấy theo bước chân của bạn, chăm chú ngắm nhìn những bức tranh tường này."
  },
  AvgDialog_131209_Content_29 = {
    Text = "Một hình bóng giống hệt, rời khỏi người phụ nữ đang ngồi, rơi vào hang động tối tăm……"
  },
  AvgDialog_131209_Content_3 = {
    Text = "Chít—— chít—— nữ thần số phận xoay vòng quay của cô ấy."
  },
  AvgDialog_131209_Content_30 = {
    Text = "Trong hang động tối tăm, người phụ nữ cùng những sinh vật bóng tối khác đang nhảy một điệu múa kỳ dị. Thứ nàng ta cầm trong tay là……một xa quay sợi?"
  },
  AvgDialog_131209_Content_31 = {
    Text = "Trung tâm xa quay sợi phát ra ánh sáng rực rỡ, như một chiếc đèn lồng, chiếu sáng cả hang động……"
  },
  AvgDialog_131209_Content_32 = {
    Text = "Phụ nữ mang theo đèn cầm tay hình bánh xe đến thành phố…… Một nhóm người mặc áo choàng thần thánh, quỳ gối trước phụ nữ và đèn cầm tay. Trên trang phục của họ khắc…… là biểu tượng của đèn cầm tay ?"
  },
  AvgDialog_131209_Content_33 = {
    Text = "Nó có một số khác biệt tinh tế với biểu tượng đèn cầm tay mà bạn đã từng thấy, ở bên ngoài hình tam giác ngược ác độc đó, có thêm một vòng tròn giống như bánh xe quay."
  },
  AvgDialog_131209_Content_34 = {
    Text = "Nhưng bạn đã hiểu rõ từng yếu tố của biểu tượng đó. Bạn biết rõ, đó chính là biểu tượng của Hội Giáo đèn lồng, đó chính là sự ra đời của Hội Giáo đèn lồng."
  },
  AvgDialog_131209_Content_35 = {
    Text = "Bức tranh cuối cùng……"
  },
  AvgDialog_131209_Content_36 = {
    Text = "Bức bích họa cuối cùng đứng ở cuối hành lang, như một cánh cửa ngăn cách số phận. Màu sắc ô uế trên bức bích họa nhấp nhô, phản chiếu ánh sáng mờ ảo trong nhà thờ."
  },
  AvgDialog_131209_Content_37 = {
    Text = "Người phụ nữ cầm đèn lồng, quỳ lạy trước một bóng người mờ ảo. Phía sau bóng người, là một thứ khổng lồ……"
  },
  AvgDialog_131209_Content_38 = {Text = "Ư…"},
  AvgDialog_131209_Content_39 = {
    Text = "Khi bạn nhận ra quả cầu mắt khổng lồ, chưa mở ra đó, một cơn đau nhói quen thuộc mạnh mẽ tấn công bạn, dấy lên những đợt sóng cuồn cuộn trong không gian tinh thần của bạn."
  },
  AvgDialog_131209_Content_4 = {
    Text = "Chít—— chít—— sợi chỉ số phận quấn chặt trong tay cô ấy."
  },
  AvgDialog_131209_Content_40 = {
    Text = "Bạn vội vàng rời mắt đi, thở hổn hển, cố trấn tĩnh cơn đau đớn cuộn trào trong không gian tinh thần."
  },
  AvgDialog_131209_Content_41 = {
    Text = "<Shake:Hô……hô……>Giáo hội Đề Đăng……Tohuwaboh……"
  },
  AvgDialog_131209_Content_42 = {
    Text = "Trong chiều này, Nephreya thật không ngờ……là người sáng tạo của Hội Giáo đèn lồng"
  },
  AvgDialog_131209_Content_43 = {
    Text = "Thì ra là vậy, tôi hiểu rồi!……"
  },
  AvgDialog_131209_Content_44 = {
    Text = "Như ngài đã biết, Người Giữ Bí Mật {Male=先生,Female=小姐}. Khi vị thần tối cao sắp tỉnh giấc, người em gái bị số phận ruồng bỏ của tôi đã trốn thoát khỏi Uyên Ngục."
  },
  AvgDialog_131209_Content_45 = {
    Text = "Cô ấy đã gây nhiễu tầm nhìn của tôi, ẩn giấu giáo phái này dưới sân khấu của tôi."
  },
  AvgDialog_131209_Content_46 = {
    Text = "Vị đó mà cô ấy tôn kính, chính là Sứ đồ kết nối với vị thần tối cao trong chiều này."
  },
  AvgDialog_131209_Content_47 = {
    Text = "Bạn lại nhìn vào bóng tối mờ ảo kết nối với Toguwaibo trên bức tranh tường."
  },
  AvgDialog_131209_Content_48 = {
    Text = "Tôi đã hiểu… Nephreya muốn làm gì, chính là dựa vào sức mạnh của vị Sứ đồ đó, táiXây dựng kết nối với Toguwaibo!…"
  },
  AvgDialog_131209_Content_49 = {
    Text = "Nhưng nếu như vậy, tại sao cô ấy lại đi săn những bí ẩn đó…"
  },
  AvgDialog_131209_Content_5 = {
    Text = "Những con rối xếp hàng nhập trường, bước vào lưới lớn của số phận."
  },
  AvgDialog_131209_Content_50 = {Text = "Đinh —"},
  AvgDialog_131209_Content_51 = {
    Text = "Tiếng chuông đục từ tháp chuông bên ngoài nhà thờ vang lên, như một lời tiên tri bẩn thỉu."
  },
  AvgDialog_131209_Content_52 = {
    Text = "Nhà thờ khổng lồ gầm rú một cách nặng nề. Trong những rung động kéo dài, những bức tường đá khắc họa bích họa ô uế từ từ dâng lên."
  },
  AvgDialog_131209_Content_53 = {Text = "Đó là!!"},
  AvgDialog_131209_Content_54 = {
    Text = "Arachne……Thưa bà……"
  },
  AvgDialog_131209_Content_55 = {
    Text = "Ái chà…… Kí ức nhỏ của chúng ta, giọng nói thật sự yếu đuối đến đáng thương."
  },
  AvgDialog_131209_Content_56 = {
    Text = "Nefreya! Buông cô ấy ra"
  },
  AvgDialog_131209_Content_57 = {
    Text = "Cơ thể của cô bé treo trên giá đèn bánh xe vĩ đại, máu đỏ tươi chảy từ từ trên nền đá cẩm thạch trắng."
  },
  AvgDialog_131209_Content_58 = {
    Text = "Ánh sáng rực rỡ chiếu sáng phía sau cô gái, khắc họa một bóng dáng thánh thiện cho thân thể đầy máu me này."
  },
  AvgDialog_131209_Content_59 = {
    Text = "Nephreya, đừng làm những cuộc tranh đấu vô nghĩa nữa. Bỏ cô ấy ra đi."
  },
  AvgDialog_131209_Content_6 = {
    Text = "Chúng nhảy múa. Chúng hát ca. Chít chít—— chít chít——"
  },
  AvgDialog_131209_Content_60 = {
    Text = "Ồ? Nữ thần số phận của chúng ta, giờ bắt đầu quan tâm đến \"ký ức\" của mình rồi à?"
  },
  AvgDialog_131209_Content_61 = {
    Text = "Bạn chưa bao giờ quan tâm đến họ, bạn đã bỏ rơi họ, Arachne."
  },
  AvgDialog_131209_Content_62 = {
    Text = "Nephreya, tôi biết bạn đang muốn gọi Sứ đồ, để Hoán tỉnh Toguwaibo lại... Có chuyện gì, chúng ta có thể bàn bạc lại, không cần thiết phải giết họ..."
  },
  AvgDialog_131209_Content_63 = {
    Text = "Cách câu giờ của ngươi thật ngây thơ đáng yêu, %player%."
  },
  AvgDialog_131209_Content_64 = {
    Text = "Bạn không hiểu gì cả. Tôi chưa từng giết họ. Tôi chỉ đang đưa họ về nhà."
  },
  AvgDialog_131209_Content_65 = {
    Text = "Để các bạn đến đây, chỉ là để các bạn cùng chứng kiến một kết thúc hoàn mỹ của họ."
  },
  AvgDialog_131209_Content_66 = {
    Text = "Màn thứ hai, cảnh thứ ba. Tôi đặt tên cho nó là, \"Hội ngộ\"."
  },
  AvgDialog_131209_Content_67 = {
    Text = "Nefreya liếc nhìn bạn với vẻ khinh bỉ. Móng tay của cô ấy nhẹ nhàng lướt qua khuôn mặt của \"Ký ức\", để lại một vết máu mảnh mai trên đó."
  },
  AvgDialog_131209_Content_68 = {
    Text = "Cô ấy cúi người, nhìn cô gái với vẻ yêu thương, khuôn mặt cô ấy run rẩy vì suy nhược và sợ hãi."
  },
  AvgDialog_131209_Content_69 = {
    Text = "Đứa trẻ ngoan, đừng sợ. Chúng ta sẽ về nhà rất nhanh thôi."
  },
  AvgDialog_131209_Content_7 = {
    Text = "Chúng đã chết cùng với mạng lưới khổng lồ, lặng lẽ không một tiếng động."
  },
  AvgDialog_131209_Content_70 = {
    Text = "Tạm biệt những kỷ niệm không đáng có với chị yêu của em——"
  },
  AvgDialog_131209_Content_71 = {
    Text = "Đợi đã…Nefreya!"
  },
  AvgDialog_131209_Content_72 = {Text = "Pa——"},
  AvgDialog_131209_Content_73 = {
    Text = "Trong tiếng nổ giòn giã của Nephreya, cơ thể cô gái nổ tung như pháo hoa đỏ rực."
  },
  AvgDialog_131209_Content_74 = {
    Text = "Ánh sáng của đèn cầm tay chiếu sáng những vết máu đang phun ra, hiện lên trên mặt các bạn một bông hoa đỏ tươi."
  },
  AvgDialog_131209_Content_75 = {
    Text = "Những giọt máu bay lên không trung, dừng lại, rồi quay trở lại, tham lam bò về phía thân thể của Nephreya, nhuộm đỏ từng inch trên cơ thể của Nephreya."
  },
  AvgDialog_131209_Content_76 = {
    Text = "Giọt máu tiếp tục chảy xuống, chảy xuống, thấm vào quần áo và làn da của cô ấy, thấm vào từng mạch máu của cô, cuộn chảy trong cơ thể mảnh mai của cô."
  },
  AvgDialog_131209_Content_77 = {
    Text = "Đầu lưỡi liếm dòng máu tươi bên môi, Nephreya thích thú ngắm nhìn những móng tay nhuộm đỏ bởi máu, như một nữ chủ nhân diện trang phục lộng lẫy, chuẩn bị đón chào một bữa tiệc đoàn viên."
  },
  AvgDialog_131209_Content_78 = {
    Text = "Chào mừng trở về nhà, thân yêu."
  },
  AvgDialog_131209_Content_79 = {
    Text = "Dừng lại!!"
  },
  AvgDialog_131209_Content_8 = {
    Text = "Giọng hát vang vọng trong nhà thờ rộng lớn. Nefreya dang rộng hai tay, thưởng thức dư âm của mình."
  },
  AvgDialog_131209_Content_80 = {
    Text = "Ánh bạc bùng nở trong tay, bạn lao về phía Nephreya."
  },
  AvgDialog_131209_Content_81 = {
    Text = "Dưới ánh sáng thánh thiện và đẫm máu, vô số bóng tối vươn ra từ bức tranh tường bẩn thỉu, chắn trước mặt bạn…"
  },
  AvgDialog_131209_Content_9 = {
    Text = "Thế nào, giọng hát của tôi có hay không?"
  },
  AvgDialog_131210_Content_1 = {
    Text = "Không ngờ lần gặp lại này, bạn lại trong tình trạng thảm hại như vậy."
  },
  AvgDialog_131210_Content_2 = {
    Text = "Thái Di Sơ…"
  },
  AvgDialog_131210_Content_3 = {
    Text = "Tavi nói đúng. Không sao đâu, Người Giữ Bí Mật."
  },
  AvgDialog_131210_Content_4 = {
    Text = "Bạn đã nói sẽ dẫn tôi chứng kiến một kết cục khác. Tôi tin bạn, từ đầu đến cuối luôn như vậy."
  },
  AvgDialog_131210_Content_5 = {
    Text = "Dù là dừng lại ở đây hay vượt qua tôi, tôi vẫn luôn ở bên bạn."
  },
  AvgDialog_131211_Content_1 = {Text = "Kén"},
  AvgDialog_131211_Content_10 = {
    Text = "Tôi không muốn trải qua trải nghiệm như vậy lần thứ hai nữa……"
  },
  AvgDialog_131211_Content_11 = {
    Text = "Ngươi không chắc đây có phải lời thật lòng của mình không. Ngươi nắm chặt nắm đấm, thích nghi lại với cơ thể vừa cùng \"N\" chung quyền kiểm soát."
  },
  AvgDialog_131211_Content_12 = {
    Text = "Tầm nhìn dần dần trở nên rõ ràng, bạn xoa xoa đầu đang đau nhức, đi về phía cái bóng mỏng manh quỳ trên đất bên mép sân khấu."
  },
  AvgDialog_131211_Content_13 = {
    Text = "Nefreya, kế hoạch của bạn đã……"
  },
  AvgDialog_131211_Content_14 = {
    Text = "Vui lòng cẩn thận."
  },
  AvgDialog_131211_Content_16 = {
    Text = "Dường như có sợi dây nhẹ nhàng kéo kéo, bước chân của bạn chậm lại một chút. Một cái chân nhện đen sắc bén gần như chạm vào mắt bạn, lướt qua trước mặt bạn trong gang tấc."
  },
  AvgDialog_131211_Content_17 = {
    Text = "Tám cái chân độc khổng lồ xé rách quần áo trên lưng cô, vung vẩy trong không trung, vặn vẹo, vùng vẫy. Nephreya dường như không mảy may bận tâm đến tất cả những điều này."
  },
  AvgDialog_131211_Content_18 = {
    Text = "Mảnh vỡ của chiều không gian bay lượn xung quanh cô như những bông hoa giấy rơi xuống. Nước mắt của cô rơi xuống, làm ướt chiếc bánh xe sợi nhạt nhòa trong tay đã mất đi ánh sáng."
  },
  AvgDialog_131211_Content_19 = {
    Text = "Kênh chiều đã biến mất, bạn không còn cơ hội nữa."
  },
  AvgDialog_131211_Content_2 = {
    Text = "……Thủ……"
  },
  AvgDialog_131211_Content_20 = {
    Text = "Số phận đang đi trên quỹ đạo của nó, Nephreya. Hãy chấp nhận nó đi."
  },
  AvgDialog_131211_Content_21 = {
    Text = "Cơ hội?… He he he he…"
  },
  AvgDialog_131211_Content_22 = {
    Text = "Bóng dáng gầy guộc rung lên vì tiếng cười, mang theo những cánh tay độc ác vẽ ra những quỹ đạo thê lương trên không trung."
  },
  AvgDialog_131211_Content_23 = {
    Text = "Tôi chưa từng có cơ hội, cũng chưa từng cần cơ hội."
  },
  AvgDialog_131211_Content_24 = {
    Text = "Tự do, thời thơ ấu, gia đình, tình yêu, bản thân… số phận đã cướp đi mọi thứ của chúng ta, tôi mãi mãi, mãi mãi sẽ không như bạn, trở thành Tù nhân của nó."
  },
  AvgDialog_131211_Content_25 = {
    Text = "Nefreya từ từ đứng dậy, đặt cơ thể vào chiếc bánh xe dệt tối tăm, bị hỏng ấy."
  },
  AvgDialog_131211_Content_26 = {
    Text = "Hãy nhìn cho kỹ, Arachne! Những điều mà bạn khao khát nhưng không dám làm, tôi sẽ làm thay bạn"
  },
  AvgDialog_131211_Content_27 = {
    Text = "Gần như trong tiếng gầm giận dữ, cơ thể của Nephreya dường như ngay lập tức bị vô số mũi nhọn xuyên qua. Máu từ cơ thể cô ấy chảy ngược ra, nối liền với chiếc bánh xe dệt vỡ nát, như một cái mạng đầy máu."
  },
  AvgDialog_131211_Content_28 = {
    Text = "<Shake:@2————!>"
  },
  AvgDialog_131211_Content_29 = {
    Text = "Một loạt tiếng gào thét tần số cao mà con người không thể chịu đựng được phát ra từ đầu của Nephreya. Cơ thể cô ấy rung lên vì cơn đau dữ dội, những đường gân màu tím tối hiện rõ trên cơ thể cô."
  },
  AvgDialog_131211_Content_3 = {
    Text = "Thủ Mật Nhân {Male=先生,Female=小姐}."
  },
  AvgDialog_131211_Content_30 = {
    Text = "Các mảnh vỡ của chiều không gian dường như bị một điều gì đó thu hút, ngừng tan biến, từ từ tụ lại bên mạng lưới dệt từ máu. Bánh xe dệt tối tăm, lại bùng cháy ánh sáng máu."
  },
  AvgDialog_131211_Content_31 = {
    Text = "Hừ……Hahaha……! <Big:<Shake:Không có thần minh, thì ta sẽ làm vị thần minh ấy!>>"
  },
  AvgDialog_131211_Content_32 = {
    Text = "Câu chuyện của ta……sân khấu của ta……mãi mãi không bao giờ kết thúc! Ta sẽ mang đến cho tấm lưới không nên tồn tại này……<Big:<Shake:<Red:sự giải thoát!!!>>>"
  },
  AvgDialog_131211_Content_33 = {
    Text = "Trong tiếng gào thét đau đớn của Nephreya, toàn bộ nhà hát số phận rung chuyển mạnh mẽ. Những con rối trên sân khấu lộn xộn, va chạm, những sợi dây nối liền các con rối rối tung…"
  },
  AvgDialog_131211_Content_34 = {
    Text = "Arachne nhìn về phía bóng hình không xa đang bị lực lượng và điên rồ trong phân mảnh chiều xói mòn. Trong đôi mắt sâu thẳm của cô ấy dâng lên những gợn sóng buồn bã, giống như ngày đầu tiên cô ấy từ bỏ chính mình."
  },
  AvgDialog_131211_Content_35 = {
    Text = "Tôi đã cố gắng giải thoát bạn khỏi lời nguyền này… Thật đáng tiếc, tôi đã sai, Nephreyah."
  },
  AvgDialog_131211_Content_36 = {
    Text = "Lời nguyền không thể tránh né, nhà tù, chúng ta sẽ không bao giờ có thể trốn thoát……"
  },
  AvgDialog_131211_Content_37 = {
    Text = "Những mảnh vụn đó…… cái bánh xe đó……"
  },
  AvgDialog_131211_Content_38 = {
    Text = "Nefreya đang hấp thụ lực lượng còn sót lại trong chiều không gian! Cô ấy... cô ấy muốn trở thành wick!!"
  },
  AvgDialog_131211_Content_39 = {
    Text = "Tiếng thở dài nhẹ nhàng, vang vọng rõ ràng trong nhà hát đang gãy gập này."
  },
  AvgDialog_131211_Content_4 = {
    Text = "<Shake:Ừm……khụ khụ……>"
  },
  AvgDialog_131211_Content_40 = {
    Text = "Xin hãy đứng vững, Thủ Mật Nhân {Male=先生,Female=小姐}."
  },
  AvgDialog_131211_Content_41 = {Text = "Gì…"},
  AvgDialog_131211_Content_42 = {
    Text = "<Shake:Rầm——>"
  },
  AvgDialog_131211_Content_43 = {
    Text = "Giọng nói còn chưa dứt, toàn bộ nhà hát đột ngột xé toạc ra. Nephreya hung bạo xé rách sợi chỉ số phận, trong vết nứt kinh hoàng, các công trình của thành phố và những mảnh vụn màu sắc của chiều không gian quấn vào nhau."
  },
  AvgDialog_131211_Content_44 = {
    Text = "Sân khấu chính của nhà hát vỡ thành nhiều mảnh, các mảnh vụn của quá khứ, tương lai và hiện tại, lộn xộn đan xen trên sân khấu vỡ, ghép lại thành những hình ảnh mà bạn không thể hiểu được."
  },
  AvgDialog_131211_Content_45 = {
    Text = "Arachne……mạng của bạn……"
  },
  AvgDialog_131211_Content_46 = {
    Text = "Bánh xe trong tay Arachne quay nhanh, tàn tro của chiều không gian mênh mông từ cơ thể Arachne tuôn ra, theo những sợi chỉ trên bánh xe, lấp đầy những khoảng trống bị vỡ trên mạng số phận, cố gắng duy trì sân khấu khỏi số phận sụp đổ."
  },
  AvgDialog_131211_Content_47 = {
    Text = "Dưới sự kéo của sợi chỉ, bạn khó khăn đứng dậy."
  },
  AvgDialog_131211_Content_48 = {
    Text = "Hấp thụ sức mạnh rải rác của Người, thay đổi hướng đi của toàn bộ mạng lưới số phận... Bạn không phải là mảnh vụn của Người, không thể chịu đựng áp lực như vậy. Bạn không cần phải chết một cách đau khổ như vậy, Nefreya."
  },
  AvgDialog_131211_Content_49 = {
    Text = "Đau đớn? Không, tôi rất vui, chị gái! Trong vô số năm ở địa ngục, tôi đã tưởng tượng ra ngày này từng phút từng giây."
  },
  AvgDialog_131211_Content_5 = {
    Text = "Tôi đang……"
  },
  AvgDialog_131211_Content_50 = {
    Text = "Chính ảo tưởng này, mới giúp tôi trụ đến hôm nay……"
  },
  AvgDialog_131211_Content_51 = {
    Text = "Tiếng cười điên cuồng của Nephreya vang vọng trong không gian vỡ vụn của nhà hát. Cô ấy ngẩng đầu lên, tham lam hấp thụ những ánh sáng mờ ảo trong những mảnh vụn."
  },
  AvgDialog_131211_Content_52 = {
    Text = "Thần linh đang chìm trong giấc ngủ, sứ đồ bị cướp đi số phận… Ha ha ha ha… Không sao, những điều này không thể ngăn cản tôi. Nếu thần linh không thể mang lại ân huệ, thì để tôi thay Ngài mang đến!"
  },
  AvgDialog_131211_Content_53 = {
    Text = "Kẻ phục thù số phận, giờ đây, <Red:hãy giáng lâm sân khấu thuộc về các ngươi!>"
  },
  AvgDialog_131211_Content_54 = {
    Text = "Nephreya đột ngột giơ tay lên. Vô tận chất nhầy đen tuôn ra từ người Nephreya, dựng nên những tấm mạng nhện đen trong khoảng trống của nhà hát."
  },
  AvgDialog_131211_Content_55 = {
    Text = "Vô số oán niệm từng bị số phận ruồng bỏ hóa thành thực thể, bò ra liên miên bất tận dọc theo tấm mạng nhện đen khổng lồ, ào ạt lao về phía các ngươi."
  },
  AvgDialog_131211_Content_56 = {
    Text = "Arachne, trên người chúng ta……!"
  },
  AvgDialog_131211_Content_57 = {
    Text = "Bạn bỗng nhận ra, một sợi tơ đen mà bạn có thể nhìn thấy mờ mờ xuất hiện từ người Arachne."
  },
  AvgDialog_131211_Content_58 = {
    Text = "Bạn ngẩng đầu lên, thấy một sợi dây đen mờ mờ tương tự từ cơ thể mình, từ mỗi sân khấu, từ cơ thể mỗi con rối kéo dài ra, nối tới bánh xe kéo sợi trong tay Nephreya."
  },
  AvgDialog_131211_Content_59 = {
    Text = "Muôn phúc, Arachne! Chúc bạn, nữ thần số phận"
  },
  AvgDialog_131211_Content_6 = {
    Text = "Choáng váng mạnh mẽ và cơn co thắt dạ dày là di tích còn sót lại của hạnh phúc, bạn cố nén cảm giác buồn nôn và từ từ bò dậy."
  },
  AvgDialog_131211_Content_60 = {
    Text = "Đến đây, rút kiếm ra, binh sĩ! Hãy chiến đấu vì số phận của chúng ta"
  },
  AvgDialog_131211_Content_61 = {
    Text = "Cô Arachne, hãy chấp nhận số phận của mình đi... Đừng kháng cự vô ích nữa..."
  },
  AvgDialog_131211_Content_62 = {
    Text = "Đừng lo lắng, người yêu dấu. Sự giải thoát của bạn sắp đến, rất nhanh, rất nhanh……"
  },
  AvgDialog_131211_Content_63 = {
    Text = "Bánh xe tối tăm của Nephreya điên cuồng quay, những con rối trên sân khấu biến thành bóng tối trong vực thẳm, theo sự kéo của những sợi chỉ bước lên tấm lưới đen mới được dệt."
  },
  AvgDialog_131211_Content_64 = {
    Text = "Arachne từ từ nhắm mắt lại, bàn tay nắm chặt sợi chỉ vì đau đớn mà hơi run rẩy."
  },
  AvgDialog_131211_Content_65 = {
    Text = "Nefreya, chúng không thể giúp bạn trở thành vị thần có thể hủy diệt mọi số phận... Điều bạn làm chỉ khiến chúng phải trải qua một cái chết đau khổ lần nữa."
  },
  AvgDialog_131211_Content_66 = {
    Text = "Vậy thì có ý nghĩa gì chứ? Trả thù, ngoài trả thù, chúng ta không còn gì khác để cầu xin! Đúng không, những đứa trẻ bị số phận ruồng bỏ?"
  },
  AvgDialog_131211_Content_67 = {
    Text = "<Shake:Hehe hehe……Hahaha haha……!>"
  },
  AvgDialog_131211_Content_68 = {
    Text = "Tiếng cười sắc nhọn, hùng tráng và thê lương vang lên từ mạng nhện đen tối vô tận, như một hợp xướng đầy đau khổ."
  },
  AvgDialog_131211_Content_69 = {
    Text = "Những số phận bị bỏ rơi đang cười điên cuồng và gào khóc, chắn trước mặt Nephreya."
  },
  AvgDialog_131211_Content_7 = {
    Text = "Ý thức của Sứ đồ đã rời khỏi bánh xe quay, và đã mất đi kết nối với thần minh, hiện tại đã bị hủy hoại hoàn toàn. Lực lượng của Plasmid cũng đã trở về yên tĩnh."
  },
  AvgDialog_131211_Content_70 = {
    Text = "Bây giờ, cánh cửa của vực thẳm đã hoàn toàn mở ra. Đến đây đi, Arachne, hãy nhìn những số phận mà chính ngươi đã tạo ra, nhìn những đứa con mà ngươi yêu thương"
  },
  AvgDialog_131211_Content_71 = {
    Text = "Hãy nhìn nỗi đau của họ, sự tuyệt vọng của họ… Nhìn họ, rồi lại một lần nữa giết chết họ"
  },
  AvgDialog_131211_Content_72 = {
    Text = "Hãy nhìn mọi thứ số phận xoay chuyển trong tay tôi, hủy diệt!…… Hãy nhìn tôi, trở thành vị thần mang lại sự kết thúc"
  },
  AvgDialog_131211_Content_73 = {
    Text = "Những mảnh vỡ chiều không gian mang theo sức mạnh của thần minh và ý chí cuồng loạn, từng mảnh từng mảnh cắm vào cơ thể Nephreya, máu tươi không ngừng tuôn vào guồng xe chỉ của Nephreya."
  },
  AvgDialog_131211_Content_74 = {
    Text = "Khuôn mặt cô co giật vì đau đớn, tiếng cười của cô càng lúc càng điên cuồng."
  },
  AvgDialog_131211_Content_75 = {
    Text = "Cô ấy đầy mong đợi nhìn về sân khấu đã vỡ vụn, như một người đang chờ đợi tác phẩm của mình ra mắt lần đầu."
  },
  AvgDialog_131211_Content_76 = {
    Text = "Địa ngục số phận đó, đã đến trên sân khấu này… Nefreya đang hiến tế bản thân."
  },
  AvgDialog_131211_Content_77 = {
    Text = "Cô ấy muốn biến mọi thứ ở đây, kể cả chúng ta, thành những con rối của cô ấy. Cô ấy muốn trở thành vị thần đó. Cô ấy... muốn trở thành số phận chính nó."
  },
  AvgDialog_131211_Content_78 = {
    Text = "Arachne với giọng điệu bình tĩnh dường như thuộc về một người xem chưa bao giờ tham gia vào vở kịch. Những tàn tro chiều được thu hồi lại như cát nhẹ nhàng cuốn quanh đầu ngón tay cô, kéo dài không dứt."
  },
  AvgDialog_131211_Content_79 = {
    Text = "Cô ấy quay bánh xe dệt một cách khó khăn, gắng gượng duy trì những số phận đang bị Nefreya phá hủy, ngăn chặn những sợi chỉ đen hội tụ vào tay Nefreya."
  },
  AvgDialog_131211_Content_8 = {
    Text = "Bạn đã hoàn thành một buổi biểu diễn tuyệt vời."
  },
  AvgDialog_131211_Content_80 = {
    Text = "Tàn tro của chiều đã được thu hồi, hiện tại tôi không còn cần phải e ngại nữa."
  },
  AvgDialog_131211_Content_81 = {
    Text = "Xin hãy giúp tôi, cố gắng lại gần cô ấy. Vòng quay của Nefreya sẽ ngừng lại, số phận sai lầm này, tôi sẽ cùng bạn sửa đổi."
  },
  AvgDialog_131211_Content_82 = {
    Text = "Xin hãy giúp tôi…… mang lại sự giải thoát cho những số phận bị bỏ rơi này."
  },
  AvgDialog_131211_Content_9 = {
    Text = "Hô… thật không thể tin được, vừa rồi những lời đó là từ miệng tôi nói ra."
  },
  AvgDialog_131212_Content_1 = {
    Text = "Cùng một thời điểm\nở đầu bên kia của thành phố"
  },
  AvgDialog_131212_Content_10 = {
    Text = "Số sáu là công tước chọn từ chuồng ngựa trong trang viên để gửi đến trường đua ngựa, lần này chắc chắn số sáu sẽ chiến thắng, nghe tôi đi, mua số sáu thì không sai đâu"
  },
  AvgDialog_131212_Content_11 = {
    Text = "Âm thanh líu ríu trong tàu điện ngầm hòa thành một dòng suối nhảy múa, Arachne lặng lẽ nhìn ra ngoài cửa sổ những ánh đèn gần lại rồi lại xa, mỉm cười lắng nghe những con rối của cô trò chuyện về buổi biểu diễn, đua ngựa và đám cưới."
  },
  AvgDialog_131212_Content_12 = {
    Text = "Cô ấy lặng lẽ lắc chiếc bánh xe sợi trong tay. Giữa hàng triệu sợi chỉ phức tạp, cô tận hưởng khoảnh khắc yên bình này."
  },
  AvgDialog_131212_Content_13 = {
    Text = "Chủ nhân, điểm đến của chúng ta sắp đến rồi. Chiếc xe ngựa chuyển tiếp đã sẵn sàng, các chị em của chúng ta đang chờ đợi bạn ở đó."
  },
  AvgDialog_131212_Content_14 = {
    Text = "Đứa trẻ ngoan."
  },
  AvgDialog_131212_Content_15 = {
    Text = "Cô ấy lướt mắt nhìn quanh những con rối đang diễn xuất một cách không nỡ rời khỏi ghế, như một khán giả không muốn rời khỏi chỗ ngồi."
  },
  AvgDialog_131212_Content_16 = {
    Text = "Bạn còn nhớ không, chúng ta đã bao lâu không rời khỏi nhà hát rồi?"
  },
  AvgDialog_131212_Content_17 = {
    Text = "Kể từ ngày tôi trở thành Nhện Lạnh, tôi luôn ở bên bạn, chưa bao giờ rời xa. Đến bây giờ… năm mươi năm? Hay sáu mươi năm? Tôi cũng không nhớ rõ lắm."
  },
  AvgDialog_131212_Content_18 = {
    Text = "Nhưng mà lần này rời khỏi nhà hát đã quá lâu rồi."
  },
  AvgDialog_131212_Content_19 = {
    Text = "Điều này phải cảm ơn Nefreya. Nếu không nhờ sự xuất hiện của cô ấy, tôi cũng sẽ không có cơ hội ở lại bên ngoài nhà hát lâu như vậy."
  },
  AvgDialog_131212_Content_2 = {
    Text = "Thưa ngài, xin vui lòng xuất trình vé xe của bạn."
  },
  AvgDialog_131212_Content_20 = {
    Text = "Phối hợp với hoạt động của Người Giữ Gìn, trong những ngày qua chúng ta đã săn giết hàng trăm phục vụ đến từ Địa Ngục. Sau khi cứu được \"Ký ức\", chúng ta sẽ trở lại nhà hát."
  },
  AvgDialog_131212_Content_21 = {
    Text = "Lần sau có cơ hội ra ngoài, không biết sẽ là khi nào……"
  },
  AvgDialog_131212_Content_22 = {
    Text = "Dường như cảm nhận được suy nghĩ của Arachne, ánh sáng bên ngoài tàu điện ngầm trở nên mờ nhạt. Cô ấy nhìn ra ngoài cửa sổ tối tăm, trong vô số ký ức của những nền văn minh đã thay đổi, tìm kiếm những ký ức bình dị về chính mình."
  },
  AvgDialog_131212_Content_23 = {
    Text = "Kim đồng hồ quay trong hai giây. Chủ nhân của thành phố nhận thấy, những âm thanh trò chuyện trong tàu điện ngầm như dòng suối trong trẻo, dường như biến mất ngay khoảnh khắc toa xe chìm vào bóng tối."
  },
  AvgDialog_131212_Content_24 = {
    Text = "Chủ nhân, ở đây hình như có chút……"
  },
  AvgDialog_131212_Content_25 = {
    Text = "Carabao——"
  },
  AvgDialog_131212_Content_26 = {
    Text = "Máu lạnh lẽo của người hầu phun ra trên gương mặt bình tĩnh của Arachne, tỏa ra hương thơm như hoa diên vĩ."
  },
  AvgDialog_131212_Content_27 = {
    Text = "Ánh đèn bên ngoài sáng lên. Arachne nhìn thấy cơ thể của Pelayan bị chém đứt, lưỡi dao đi qua cơ thể cô ấy tiếp tục hướng về phía mình, và sau lưỡi dao đó, những con rối như bầy thú ùa về phía mình."
  },
  AvgDialog_131212_Content_29 = {
    Text = "Hệ thống phanh phát ra âm thanh ma sát mệt mỏi, luồng gió nhẹ cuốn bay tóc của một người hầu khác."
  },
  AvgDialog_131212_Content_3 = {
    Text = "Vào ga có phải đã kiểm tra rồi sao? Tiền của người nộp thuế bị lãng phí như vậy…"
  },
  AvgDialog_131212_Content_30 = {
    Text = "À! Đến rồi"
  },
  AvgDialog_131212_Content_31 = {
    Text = "Cửa xe mở ra, nhưng dòng người đông đúc không xuất hiện. Chỉ có dòng máu nặng mùi tanh, chảy ra từ từng khe cửa, như một cuộc tập hợp im lặng."
  },
  AvgDialog_131212_Content_32 = {
    Text = "Dẫm lên dòng máu theo nhạc đệm này, Arachne từ từ bước ra khỏi toa xe. Cô ấy mặc bộ trang phục sạch sẽ, bánh xe quay của cô vẫn đang xoay, không bao giờ ngừng lại."
  },
  AvgDialog_131212_Content_33 = {
    Text = "Đây là…"
  },
  AvgDialog_131212_Content_34 = {
    Text = "Một vở kịch tương tác tuyệt vời. Là khán giả và diễn viên, trải nghiệm thực sự thú vị hơn nhiều so với tác giả kịch bản."
  },
  AvgDialog_131212_Content_35 = {
    Text = "Nàng liếc nhìn thị nữ trước mặt, trên gương mặt bình thản không lộ ra bất kỳ cảm xúc nào."
  },
  AvgDialog_131212_Content_36 = {
    Text = "Nữ tì của tôi đã ở bên tôi nhiều năm, tôi không thường xuyên chạm vào sợi dây số phận của họ."
  },
  AvgDialog_131212_Content_37 = {
    Text = "Trong nhà hát tẻ nhạt này, họ là những sinh lực sống còn sót lại hiếm hoi."
  },
  AvgDialog_131212_Content_38 = {
    Text = "Hôm nay bạn đã giết hai người hầu của tôi. Sự phá hủy số phận sẽ phải trả giá, Nephreya."
  },
  AvgDialog_131212_Content_39 = {
    Text = "Ha ha ha ha……<Shake:Ha ha ha ha!> Thật cao thượng làm sao, Arachne."
  },
  AvgDialog_131212_Content_4 = {
    Text = "Êi, Charlie, ghim cài của tôi đi đâu rồi?"
  },
  AvgDialog_131212_Content_40 = {
    Text = "Giống như bơ rơi vào chảo thiếc sôi sục, cơ thể của thị nữ bắt đầu tan chảy. Dưới lớp chất lỏng đen bẩn thỉu đang sôi sục, khuôn mặt giống hệt Arachne cười tươi."
  },
  AvgDialog_131212_Content_41 = {
    Text = "\"Nhìn kìa, tôi là người điều khiển số phận, là kẻ thi hành án tận tâm! Tôi sẽ chọn ra những số phận đúng đắn, đưa mọi sai lầm vào vực thẳm của sự hư vô...\""
  },
  AvgDialog_131212_Content_42 = {
    Text = "Bạn là thần tượng, là niềm tin của tôi, chị gái thân mến. Tôi chỉ đang đảm nhận vai trò của bạn mà thôi."
  },
  AvgDialog_131212_Content_43 = {
    Text = "Thế nào, người học của tôi, có làm việc tốt không?"
  },
  AvgDialog_131212_Content_44 = {
    Text = "Arachne lặng lẽ nhìn chằm chằm vào đôi mắt đang hướng về mình. Nó nóng bỏng, rực rỡ, đầy mong đợi, dường như chỉ là của một cô gái nhỏ đang chờ đợi chị gái khen ngợi."
  },
  AvgDialog_131212_Content_45 = {
    Text = "Nhà ga, cửa cầu thang, cột hành lang, trong đường hầm… Khi cô ấy nói, vô số bóng tối xuất hiện ở mọi vị trí mà cô ấy có thể nghĩ đến."
  },
  AvgDialog_131212_Content_46 = {
    Text = "Hơi thở mờ ảo của bóng tối gắn chặt với nhau, hội tụ trong tay Nephreya, như một tấm lưới khổng lồ đang siết chặt về phía Arachne."
  },
  AvgDialog_131212_Content_47 = {
    Text = "Đôi môi của Arachne nhẹ nhàng nhếch lên."
  },
  AvgDialog_131212_Content_48 = {
    Text = "Tôi chưa bao giờ nghĩ rằng sẽ có người cố gắng dùng lưới để trói buộc tôi."
  },
  AvgDialog_131212_Content_49 = {
    Text = "Bạn đã thấy tằm chưa, chị gái? Đó là một loài côn trùng đến từ phương Đông xa xôi, chúng ngày ngày không làm gì cả, chỉ biết ăn mãi, nhả tơ... rồi, à, chờ đợi những cái kén được hình thành từ tơ sẽ trói buộc chính mình."
  },
  AvgDialog_131212_Content_5 = {
    Text = "Khi ra ngoài không phải đã để lại trên quần áo rồi sao?"
  },
  AvgDialog_131212_Content_50 = {
    Text = "Gần như tất cả các phục vụ của bạn, đã biến mất ở khắp các góc phố của thành phố này, trên chuyến tàu này. Họ đã từng ở bên bạn, trải qua những năm tháng dài dằng dặc trong sự trống rỗng."
  },
  AvgDialog_131212_Content_51 = {
    Text = "Bạn đã mang đến cho họ cái kết không đáng xảy ra. Số phận không thể chống lại, Nefreya."
  },
  AvgDialog_131212_Content_52 = {
    Text = "Ý của bạn là, kết cục của họ, nên chỉ là ngoan ngoãn ở lại trong cái vực thẳm tối tăm đó, chìm đắm trong thời gian vô tận… đúng không, người nắm giữ số phận cao quý?"
  },
  AvgDialog_131212_Content_53 = {
    Text = "Nephreya cười khẩy và lắc đầu."
  },
  AvgDialog_131212_Content_54 = {
    Text = "Tôi yêu họ hơn bạn tưởng, chị gái. Nhưng họ đã nói với tôi, nếu cái chết có thể giúp họ thoát khỏi số phận bị giam cầm một lần nữa, họ sẽ không ngần ngại đón nhận nó…"
  },
  AvgDialog_131212_Content_55 = {
    Text = "Sau cuộc tàn sát trong tàu điện ngầm này, những tàn tro mà bạn dùng để sửa đổi số phận, còn lại bao nhiêu?"
  },
  AvgDialog_131212_Content_56 = {
    Text = "Nefreya khoe khoang nâng cao bánh xe dệt màu đen trong tay. Những sợi chỉ vô số kéo dài từ sân khấu thành phố, đang kết nối với chiếc bánh xe dệt đang đứng yên đó."
  },
  AvgDialog_131212_Content_57 = {
    Text = "Số phận của thành phố này, tất cả đều nằm trong tay tôi. Tôi không có khả năng kiểm soát chúng, nhiều điều thú vị không thể thực hiện được, thật là đáng tiếc…"
  },
  AvgDialog_131212_Content_58 = {
    Text = "Tuy nhiên, may thay, việc sửa chữa chúng cần tiêu tốn vô số tàn tro, còn ô nhiễm thì không cần."
  },
  AvgDialog_131212_Content_59 = {
    Text = "Miễn là tôi nhẹ nhàng buông tay như vậy… nhà hát của bạn, sân khấu của bạn, sẽ biến thành nôi ấm hoàn hảo nhất của hỗn mang, giống như… giống như nơi tôi đã ở trong suốt nhiều năm qua."
  },
  AvgDialog_131212_Content_6 = {
    Text = "Trời ơi… Tôi đã chuẩn bị cho buổi tiệc hôm nay tận một tháng! Nếu không có chiếc ghim ngực này, bộ váy này chẳng khác gì một miếng vải phủ quan tài…"
  },
  AvgDialog_131212_Content_60 = {
    Text = "Và bạn, chỉ có thể nhìn mọi thứ xảy ra. Không thể thay đổi điều gì, không thể phản kháng…"
  },
  AvgDialog_131212_Content_61 = {
    Text = "Nefreya đến trước mặt Arachne, cẩn thận vuốt ve khuôn mặt không rõ cảm xúc của cô ấy."
  },
  AvgDialog_131212_Content_62 = {
    Text = "Tôi nên làm gì đây, chị gái của tôi... là nghe lời tôi, hay cùng tôi chiêm ngưỡng thế giới này biến thành địa ngục?"
  },
  AvgDialog_131212_Content_63 = {
    Text = "Bạn là một phần số phận chưa hoàn chỉnh, ô nhiễm số phận của toàn thành phố, bạn không có khả năng như vậy…"
  },
  AvgDialog_131212_Content_64 = {
    Text = "Một tiếng đứt gãy của sợi dây vang lên bên tai Arachne. Cô ấy ngẩng đầu, nhìn về phía ánh mắt của Nephreya, mang theo một chút nỗi buồn thuộc về khán giả."
  },
  AvgDialog_131212_Content_65 = {
    Text = "... bạn cũng đã giết chết \"ký ức\"."
  },
  AvgDialog_131212_Content_66 = {
    Text = "Là sự chấp nhận. Lãng mạn, nhân hậu, ký ức…… Tôi chỉ từng cái một, đưa những thứ bị bạn vứt bỏ trở lại ngôi nhà thuộc về chúng."
  },
  AvgDialog_131212_Content_67 = {
    Text = "Nefreya đứng dậy, vui vẻ xoay một vòng."
  },
  AvgDialog_131212_Content_68 = {
    Text = "Một tôi hoàn chỉnh, một kẻ báo thù hoàn chỉnh…… Có thích không, chị gái?"
  },
  AvgDialog_131212_Content_69 = {
    Text = "Bạn đã có thể nhận được sự hỗn loạn mà bạn khao khát rồi... Vậy thì, bạn còn đang chờ gì nữa?"
  },
  AvgDialog_131212_Content_7 = {
    Text = "Điệu múa của đoàn thiên nga thực sự có thể gọi là uyển chuyển, nhưng nếu có sự xung đột về thời gian, tôi nhất định sẽ chọn \"Vườn Ngọc Bích\"."
  },
  AvgDialog_131212_Content_70 = {
    Text = "À, không không không, chị gái ơi, em còn xa lắm, xa lắm so với những gì em muốn."
  },
  AvgDialog_131212_Content_71 = {
    Text = "Tôi sẽ thay bạn giữ gìn bánh xe của bạn, chiều tàn tro mà bạn muốn sẽ không bao giờ cạn kiệt, những sân khấu mà bạn yêu thích, tôi sẽ không phá hủy một cái nào."
  },
  AvgDialog_131212_Content_72 = {
    Text = "Còn điều tôi muốn bạn làm, chỉ là giúp tôi một việc rất nhỏ, rất nhỏ."
  },
  AvgDialog_131212_Content_73 = {
    Text = "Nephreya tiến đến trước Arachne, vuốt ve cái bánh xe dệt không ngừng quay trong tay cô, hơi thở trở nên dồn dập vì những tưởng tượng hưng phấn."
  },
  AvgDialog_131212_Content_74 = {
    Text = "Hãy điều khiển Người Giữ Gìn thay cho tôi, chị gái tốt, chỉ có Người Giữ Gìn mới mang đến cho tôi những thứ tôi thật sự mong muốn."
  },
  AvgDialog_131212_Content_75 = {
    Text = "Ngươi nên biết rằng, %player% là mảnh vỡ của vị thần tối cao, chúng ta không thể thao túng số phận của %player%……"
  },
  AvgDialog_131212_Content_76 = {
    Text = "Một ánh sáng xanh lục mờ ảo phát ra từ bánh xe đen trong tay Nephreya. Dưới ánh sáng đó, một sợi chỉ mờ ảo và đục xuất hiện trong trường nhìn của Arachne."
  },
  AvgDialog_131212_Content_77 = {
    Text = "Đây là……<Shake:Sợi chỉ số phận của Người Giữ Bí Mật?!>"
  },
  AvgDialog_131212_Content_78 = {
    Text = "<Shake:Ha ha ha ha……><Big:<Shake:Ha ha ha ha!>>Đây là lần đầu tiên ta nghe thấy giọng nói của ngươi run rẩy. Thế nào, chị? Rất phấn khích phải không?!"
  },
  AvgDialog_131212_Content_79 = {
    Text = "Trong vực sâu, Vị đó hóa thân thành Sứ đồ của thần linh, được chứa đựng trong bánh xe dệt này, trở thành tim đèn của nó… chính nó đã chiếu sáng vực sâu, mang đến cho chúng ta ánh sáng duy nhất."
  },
  AvgDialog_131212_Content_8 = {
    Text = "Hình ảnh đa tầng và câu chuyện đa thời không, thật là một thủ pháp tuyệt vời và phức tạp. Sự thăng trầm của vườn hoàng gia tuyệt đối không thể so sánh với những tình tiết tầm thường đó……"
  },
  AvgDialog_131212_Content_80 = {
    Text = "Sức mạnh của chúng ta, cộng thêm sự dẫn dắt của Sứ Đồ, dù là số phận của mảnh vỡ thần minh kia, <Big:giờ đây cũng đã nằm trong tay chúng ta!>"
  },
  AvgDialog_131212_Content_81 = {
    Text = "Đây không phải là con đường đúng đắn của số phận, Nephreya…… không ai có thể chống lại số phận."
  },
  AvgDialog_131212_Content_82 = {
    Text = "Sẽ sớm có thôi, chị. Miễn là chạm vào quyền năng của ba Plasmid, sứ đồ sẽ có thể tái sinh! Ngài sẽ mở lại con đường kết nối với thần thánh, Ngài sẽ chuyển tiếng gọi của tín đồ vào ngôi đền vĩnh cửu đó"
  },
  AvgDialog_131212_Content_83 = {
    Text = "Vị thần tối cao sẽ tỉnh giấc trở lại……Ngươi sẽ không còn phải cắt xén những số phận đau khổ, không phải mãi mãi dệt tấm lưới định sẵn tan vỡ nữa……"
  },
  AvgDialog_131212_Content_84 = {
    Text = "Nefreya hít sâu một hơi, một giọt nước mắt rơi xuống từ gương mặt hưng phấn của cô ấy."
  },
  AvgDialog_131212_Content_85 = {
    Text = "Giọng cô ấy run rẩy vì giấc mơ tuyệt đẹp sắp đến. Đôi mắt ngấn lệ, nhìn sâu vào khuôn mặt bình tĩnh của Arachne."
  },
  AvgDialog_131212_Content_86 = {
    Text = "Đừng làm những sự kháng cự đau đớn đó nữa, chị."
  },
  AvgDialog_131212_Content_87 = {
    Text = "Hãy đến đây, bên cạnh tôi, cùng nhau chào đón sự tỉnh giấc của Người, cùng mang đến cho tất cả các sân khấu cái kết mà chúng đáng có!…"
  },
  AvgDialog_131212_Content_9 = {
    Text = "Ha, nếu bạn mua số tám thì bạn sẽ lỗ to đấy! Nói nhỏ với bạn, tôi có thông tin nội bộ, hôm nay sẽ có người bỏ thuốc vào cỏ số tám."
  },
  AvgDialog_131213_Content_1 = {
    Text = "Hài kịch ứng tác"
  },
  AvgDialog_131213_Content_10 = {
    Text = "Bây giờ, bạn lại đón chào một tín đồ mới——"
  },
  AvgDialog_131213_Content_100 = {
    Text = "Ta mượn quyền năng của \"N\"...<color=#98918C>Ta chiếm lấy nửa ý thức của %player%</color>... nhưng cách xưng hô là chuyện không quan trọng nhất lúc này."
  },
  AvgDialog_131213_Content_101 = {
    Text = "Điều quan trọng là hợp tác vui vẻ, Arachne."
  },
  AvgDialog_131213_Content_102 = {
    Text = "<Shake:Ngươi……các ngươi……các ngươi đã biết từ lâu……>"
  },
  AvgDialog_131213_Content_103 = {
    Text = "Ánh mắt suy nhược của Nefreya di chuyển từ khuôn mặt của Arachne sang khuôn mặt bạn. Bạn tham lam thưởng thức sự oán hận và đau khổ vô tận trong ánh mắt đó. À, một mùi hương thật mê hoặc..."
  },
  AvgDialog_131213_Content_104 = {
    Text = "Hãy nhìn kỹ đi, Nefreya yêu dấu, những chú quỷ nghịch ngợm đến từ vùng hư vô."
  },
  AvgDialog_131213_Content_105 = {
    Text = "Trò chơi của bạn khiến tôi rất vui vẻ. Một chút ý thức còn lại của Toguwaibo, một mảnh vỡ rơi ra từ Toguwaibo, chỉ khi chúng gặp nhau, quyền lực của Plasmid mới được hoàn toàn giải phóng, mới cho tôi cơ hội trải nghiệm niềm vui chưa từng có này…"
  },
  AvgDialog_131213_Content_106 = {
    Text = "Nếu có thể, tôi thật sự muốn tiếp tục chơi như bây giờ, niềm vui này đủ để tôi chơi suốt cả tuần..."
  },
  AvgDialog_131213_Content_107 = {
    Text = "Cổ họng run rẩy. Bạn thở dài đầy tiếc nuối."
  },
  AvgDialog_131213_Content_108 = {
    Text = "Thật đáng tiếc, nếu để vị đó tỉnh dậy lần nữa, thì công viên hùng vĩ này sẽ rời xa tôi."
  },
  AvgDialog_131213_Content_109 = {
    Text = "Vì vậy, rất tiếc……cao trào của câu chuyện sắp kết thúc rồi. Ngẩng đầu lên đi, người thân mến. Dù thế nào, về câu chuyện của số phận, ta nghĩ chúng ta có một sự đồng thuận tuyệt vời……"
  },
  AvgDialog_131213_Content_11 = {
    Text = "Sợi chỉ số phận kéo cơ thể bạn. Bạn chắp tay lại, hai tay đặt trước ngực, từ từ quỳ gối và cúi đầu về phía trước, hướng về vòng quay."
  },
  AvgDialog_131213_Content_110 = {
    Text = "Ngươi cúi người xuống, nắm lấy cằm thanh tú của Nephreya, ghé sát bên tai nàng."
  },
  AvgDialog_131213_Content_111 = {
    Text = "Hủy diệt, là bức tranh đẹp nhất trong vũ trụ này, đúng không, người yêu?"
  },
  AvgDialog_131213_Content_112 = {
    Text = "Một tiếng búng tay trong trẻo, mang theo niềm hạnh phúc vô hạn và nỗi tiếc nuối, vang lên trước mắt Nefreya."
  },
  AvgDialog_131213_Content_113 = {
    Text = "Rầm——"
  },
  AvgDialog_131213_Content_114 = {
    Text = "Trong cơn rung động của chiều, lối đi kết nối với thần linh bỗng nhiên rung chuyển. Vô số vết nứt, leo lên bề mặt ảo diệu của lối đi…"
  },
  AvgDialog_131213_Content_115 = {
    Text = "<Big:<Shake:Không!!——>>"
  },
  AvgDialog_131213_Content_116 = {
    Text = "Nephreya hét lên lao về phía lối đi, khi tay cô còn cách lối đi vài inch, nó vỡ nát, sụp đổ."
  },
  AvgDialog_131213_Content_117 = {
    Text = "Vô số mảnh vỡ hư ảo bay lơ lửng trước mặt Nephreya, như một kính vạn hoa vỡ nát, những mảnh giấy màu rẻ tiền bay tán loạn khắp trời, quệt qua khuôn mặt Nephreya."
  },
  AvgDialog_131213_Content_118 = {
    Text = "Bạn tháo chiếc mũ lễ hội không tồn tại ra, xoay hai vòng trong không trung, rồi cúi chào bóng lưng mơ hồ của Nephreya."
  },
  AvgDialog_131213_Content_119 = {
    Text = "Số phận, một sân khấu thật thú vị… Màn thứ ba của câu chuyện đã khép lại. Những tràng pháo tay và tiếng hoan hô của bạn khiến tôi vô cùng tận hưởng."
  },
  AvgDialog_131213_Content_12 = {
    Text = "Tôi... sứ đồ mà tôi ngưỡng mộ... tôi là... tín đồ trung thành nhất của ngài và thần linh tối cao."
  },
  AvgDialog_131213_Content_120 = {
    Text = "Chúc bạn xem kịch vui vẻ, thân mến Neferia."
  },
  AvgDialog_131213_Content_121 = {
    Text = "Trong tiếng khóc xé lòng của Nephreia, ý thức của sứ đồ vỡ nát theo sự đứt gãy của đường dẫn. Bạn ngã xuống sân khấu với nụ cười cuối cùng đầy hạnh phúc."
  },
  AvgDialog_131213_Content_13 = {
    Text = "Họng của bạn và các chi đã có số phận riêng. Chúng không còn thuộc về bạn, và bạn cũng không còn vô ích cố gắng để kiểm soát chúng lại nữa."
  },
  AvgDialog_131213_Content_14 = {
    Text = "Đừng kiểm soát. Đừng hiểu. Hãy tận hưởng chúng. Con đường hạnh phúc, chính là ở đó……"
  },
  AvgDialog_131213_Content_15 = {
    Text = "Chị xem đi, chị đã dạy dỗ nên một diễn viên xuất sắc biết nhường nào!"
  },
  AvgDialog_131213_Content_16 = {
    Text = "Arachne ngồi thẳng ở dưới sân khấu, bánh xe dệt trong tay quay với nhịp điệu vĩnh cửu. Cô ấy lặng lẽ nhìn ánh sáng mờ ảo từ chiếc đèn cầm tay trên sân khấu, dường như chỉ là một người giữ gìn nghi lễ."
  },
  AvgDialog_131213_Content_17 = {
    Text = "Ôi sứ đồ quý mến của tôi… các tín đồ của chúng tôi đã mang đến cho ngài lễ vật mà ngài khao khát nhất."
  },
  AvgDialog_131213_Content_18 = {
    Text = "Tơ nhẹ xoay chuyển, guồng xe sợi tối màu bỗng bừng nở, rải ánh sáng u ám dính nhớp khắp mọi góc sân khấu."
  },
  AvgDialog_131213_Content_19 = {
    Text = "Ừ!!……"
  },
  AvgDialog_131213_Content_2 = {
    Text = "Tách, tách, tách."
  },
  AvgDialog_131213_Content_20 = {
    Text = "Cơn đau đến không báo trước, không xảy ra trên da thịt, cũng không xảy ra nơi tạng phủ. Nó bùng phát từ nơi sâu thẳm nhất trong không gian tinh thần của bạn, từ nơi linh hồn bạn trú ngụ."
  },
  AvgDialog_131213_Content_21 = {
    Text = "Một con cự thú xuất hiện bên trong cơ thể bạn, nó vùng vẫy, gầm thét, thân hình khổng lồ nhanh chóng phình to trong người bạn."
  },
  AvgDialog_131213_Content_22 = {
    Text = "Cự thú lấp đầy toàn bộ cơ thể bạn, chèn ép từng nội tạng. Nó phình to, phình to, nó giận dữ muốn xé toạc từng tấc da của bạn, cảm giác đau tức dữ dội khiến bạn gần như ngất xỉu…"
  },
  AvgDialog_131213_Content_23 = {
    Text = "Hô……<Big:<Shake:AAAAAHH!!——>>"
  },
  AvgDialog_131213_Content_24 = {
    Text = "Trong tiếng kêu đau đớn xé lòng của bạn, ba hơi thở mờ ảo từ cơ thể đau đớn đó thẩm thấu ra, bay về phía chiếc vòng quay phát ra ánh sáng u ám."
  },
  AvgDialog_131213_Content_25 = {
    Text = "Quyền năng hòa vào ánh đèn, như nhiên liệu tinh thuần đổ vào lửa. Ngọn lửa u ám bỗng bùng cháy dữ dội, rực rỡ thiêu đốt giữa vòng tròn guồng xe sợi. Ánh sáng của đèn lồng nhanh chóng tăng vọt, gần như chiếu sáng toàn bộ không gian chiều không."
  },
  AvgDialog_131213_Content_26 = {
    Text = "<Shake:Hừ… hừ…>"
  },
  AvgDialog_131213_Content_27 = {
    Text = "Ài, thật đáng thương, tín đồ nhỏ bé trung thành của chúng ta……"
  },
  AvgDialog_131213_Content_28 = {
    Text = "Nefreya đến bên bạn, đầy thương xót vuốt ve khuôn mặt ướt đẫm mồ hôi của bạn."
  },
  AvgDialog_131213_Content_29 = {
    Text = "Không sao đâu, Người Giữ Bí Mật {Male=先生,Female=小姐}, ngươi xem, sứ đồ của chúng ta đã hiện hình rồi…"
  },
  AvgDialog_131213_Content_3 = {
    Text = "Sợi chỉ số phận nhẹ nhàng kéo, đế giày của con rối va chạm với sân khấu, phát ra tiếng vang trong trẻo."
  },
  AvgDialog_131213_Content_30 = {
    Text = "Bạn đau đớn ngẩng đầu lên. Ánh sáng của vòng quay bắt đầu hội tụ, một hình thể hư vô biến ảo xuất hiện trên ánh đèn."
  },
  AvgDialog_131213_Content_31 = {
    Text = "Ngài không có gương mặt, không có hình dạng. Ngài là sứ giả trung thành của thần minh, dõi mắt về phương hướng nơi thần minh say giấc giữa hư không."
  },
  AvgDialog_131213_Content_32 = {
    Text = "Ánh mắt của Ngài là một lời mời. Dưới sự ngưng nhìn của Ngài, một bậc thang nối đến nơi thần minh an giấc, từ từ hiện ra hình dáng……"
  },
  AvgDialog_131213_Content_33 = {
    Text = "<Shake:Thành công rồi……thành công rồi!> Con đường dẫn đến thần quốc sắp mở ra……vị thần minh ấy, sắp tỉnh giấc rồi……"
  },
  AvgDialog_131213_Content_34 = {
    Text = "Chị gái, chị có thấy không? Mạng của chị, sắp hoàn thành rồi……"
  },
  AvgDialog_131213_Content_35 = {
    Text = "Nefreya vui vẻ nhìn về phía lối đi ngày càng rõ ràng, nụ cười và nước mắt đồng thời xuất hiện trên khuôn mặt cô."
  },
  AvgDialog_131213_Content_37 = {
    Text = "Nhà hát bắt đầu rung chuyển mạnh mẽ. Sân khấu đang sụp đổ, chiều đang run rẩy. Tất cả số phận đều sợ hãi và khuất phục trong sự giáng lâm vĩ đại này."
  },
  AvgDialog_131213_Content_38 = {
    Text = "Quyền năng trong cơ thể ngươi đã yếu đến mức không thể cảm nhận. Sức mạnh của chất thể, tất cả đều quy về thân xác của sứ đồ. Ánh sáng của Ngài không thể nhìn trực tiếp, sự tồn tại của Ngài không thể phủ nhận."
  },
  AvgDialog_131213_Content_39 = {
    Text = "Dưới ánh nhìn bình tĩnh của Arachne, trong mọi sự run rẩy của số phận, Ngài sẽ đến trên sân khấu cuối cùng này——"
  },
  AvgDialog_131213_Content_4 = {
    Text = "À, khán giả thân mến, khoảnh khắc được mong đợi nhất sắp đến rồi! Hãy dành cho nhân vật chính của chúng ta một tràng pháo tay chào đón, xuất hiện lấp lánh! Ôi"
  },
  AvgDialog_131213_Content_40 = {
    Text = "Bằng...@2... tên...@3 tín đồ..."
  },
  AvgDialog_131213_Content_41 = {
    Text = "Nói đi, sứ đồ… bạn muốn nói với tôi điều gì? Là khát vọng của bạn? Hay là lời của vị thần đó?"
  },
  AvgDialog_131213_Content_42 = {
    Text = "Ngài có mệnh lệnh gì để truyền đạt cho thế giới này? Có muốn những sân khấu này tan vỡ? Hay muốn những con rối này cùng nhau chào đón sự đến của Ngài?"
  },
  AvgDialog_131213_Content_43 = {
    Text = "Hãy nói cho ta biết đi, sứ đồ thân yêu! Ngươi là một con dã thú nguy hiểm mà đáng yêu biết bao, ngoài cắn xé và hủy diệt, chẳng biết gì khác……Hãy nói cho ta, điều ngươi muốn……"
  },
  AvgDialog_131213_Content_44 = {
    Text = "Đọc kinh@2……Danh hiệu của ta……Thức tỉnh@2……@3Khởi nguyên……"
  },
  AvgDialog_131213_Content_45 = {
    Text = "À, danh hiệu của bạn, đúng vậy...... Tôi sẽ niệm danh hiệu của bạn! Tôi sẽ mang tất cả những gì bạn muốn gặm nhấm, đến bên miệng bạn. Tôi sẽ mở ra cái cũi này cho bạn......"
  },
  AvgDialog_131213_Content_46 = {
    Text = "Tên của ta……@2……"
  },
  AvgDialog_131213_Content_47 = {
    Text = "Giọng nói của sứ đồ đục ngầu không rõ, Nephreya bước về phía cột sáng ngày càng rực rỡ, không hề liếc nhìn ngươi đang run rẩy toàn thân vì đau đớn dù chỉ một lần."
  },
  AvgDialog_131213_Content_48 = {
    Text = "Nàng cuồng nhiệt thốt lên kinh ngạc, cười vang, đến trước bóng hình vĩ đại ấy, hơi thở gần như ngưng lại vì phấn khích."
  },
  AvgDialog_131213_Content_49 = {
    Text = "Cô ấy vuốt ve ánh sáng xanh huyền bí đó, vuốt ve con quái vật vĩ đại sẽ tiêu thụ tất cả. Cô sẽ trở thành món ăn đầu tiên của quái vật, cô không do dự, ngọt như mật."
  },
  AvgDialog_131213_Content_5 = {
    Text = "Nephreya giơ tay lên, như những tấm mạng nhện giống như pháo hoa bay lượn rơi xuống. Bạn đứng ở giữa sân khấu, ánh sáng mờ ảo chiếu sáng khuôn mặt bạn."
  },
  AvgDialog_131213_Content_50 = {
    Text = "Bây giờ là lúc, sứ đồ... hãy cho tôi biết, hãy cho thế giới này biết danh hiệu của bạn"
  },
  AvgDialog_131213_Content_51 = {
    Text = "Tên của ta……@2……"
  },
  AvgDialog_131213_Content_52 = {
    Text = "Danh ta……<Red:%player%>……"
  },
  AvgDialog_131213_Content_53 = {
    Text = "Danh ta……<Yellow:%player%>!"
  },
  AvgDialog_131213_Content_54 = {Text = "!!!"},
  AvgDialog_131213_Content_55 = {
    Text = "Thời gian ngừng lại vào khoảnh khắc này. Sợi dây số phận trong mắt Nephreya tan chảy và sụp đổ, số phận sụp đổ như Vortex cuồn cuộn trong đại dương, cuốn cô ấy vào và tiêu thụ."
  },
  AvgDialog_131213_Content_56 = {
    Text = "<Shake:Đây là……chuyện gì vậy?!!>"
  },
  AvgDialog_131213_Content_57 = {
    Text = "Vortex lặng lẽ, đại dương thu thập lại, những giọt nước lại tụ lại thành sợi chỉ, và mạng lưới mà chúng biên chế ra, đã là hình dáng mà Nefreya chưa từng dự kiến."
  },
  AvgDialog_131213_Content_58 = {
    Text = "Không hiểu sao, Nephreya? Hãy thành kính quỳ lạy trước sứ đồ của bạn. Sứ đồ mà bạn cầu nguyện, đã đứng trước mặt bạn."
  },
  AvgDialog_131213_Content_59 = {
    Text = "Bạn đứng trước Nephreya, nhìn về phía lối đi kết nối với đền thờ Toguwaibo, nhìn vào hình bóng tối cao đó, nở một nụ cười."
  },
  AvgDialog_131213_Content_6 = {
    Text = "Nào, Người Giữ Bí Mật {Male=先生,Female=小姐}, màn diễn cuối cùng của chúng ta sắp bắt đầu rồi…"
  },
  AvgDialog_131213_Content_60 = {
    Text = "Quyền lực của ba chất thể trong cơ thể bạn đang cuồn cuộn tràn ra, nhưng không còn khiến bạn đau đớn. Ánh sáng từ vòng quay, ý chí vô thượng trong ánh sáng đó, như đại dương ùa vào cơ thể bạn, hòa quyện với quyền lực của ba chất thể."
  },
  AvgDialog_131213_Content_61 = {
    Text = "Bạn cảm nhận được, hình ảnh của vị Sứ đồ đang chồng lên cơ thể bạn. Bạn cảm thấy hùng vĩ. Bạn cảm thấy vô biên. Bạn cảm thấy tự do. Bạn cảm thấy… niềm vui tối thượng."
  },
  AvgDialog_131213_Content_62 = {
    Text = "Bạn…… đã đánh cắp số phận của Sứ đồ?!"
  },
  AvgDialog_131213_Content_63 = {
    Text = "Hahaha…… Hahaha! Màn thứ ba của câu chuyện, đến?…… Ha, hahaha. Màn thứ ba, đúng vậy. Nhưng đây không phải câu chuyện của bạn, thân yêu Nefreya."
  },
  AvgDialog_131213_Content_64 = {
    Text = "Câu chuyện hồi thứ ba, do ta viết nên. Và ta đặt tên cho câu chuyện này là——<Big:<color=#98918C>Hoan Lạc</color>!>"
  },
  AvgDialog_131213_Content_65 = {
    Text = "<Shake:Ngươi……các ngươi……>"
  },
  AvgDialog_131213_Content_66 = {
    Text = "Không, điều này không thể nào…… Tôi có thể thấy số phận của bạn…… điều này không thể nào……"
  },
  AvgDialog_131213_Content_67 = {
    Text = "<color=#EE4D0C>\"Ôi, công tước thân mến, Ngài vì sao mà khóc! Hãy để tên hề của Ngài, mang lại cho Ngài nụ cười quý giá một lần nữa!\"</color>"
  },
  AvgDialog_131213_Content_68 = {
    Text = "<color=#BF0909>\"Ngài hãy nhìn kìa, số phận tàn khốc ấy, lời nguyền độc ác ấy... cảnh tượng mới buồn cười làm sao! Trò lừa mới ngọt ngào làm sao!\"</color>"
  },
  AvgDialog_131213_Content_69 = {
    Text = "<color=#FC1818>\"Đây chính là kết cục của kẻ làm ác... phần thưởng cho ác hạnh, chỉ có hoan lạc!\"</color>"
  },
  AvgDialog_131213_Content_7 = {
    Text = "Cảnh này, tôi gọi nó là——\"đến\""
  },
  AvgDialog_131213_Content_70 = {
    Text = "Khán đài không người vang lên tiếng vỗ tay như sấm, sân khấu đổ nát rực rỡ đèn hoa. Ngươi là trung tâm của thế giới, chủ nhân của kỳ điểm. Ngươi dang rộng đôi tay. Ngươi nói số phận cúi đầu trước ngươi, ngươi nói, vở kịch này xứng đáng được tán tụng."
  },
  AvgDialog_131213_Content_71 = {
    Text = "Lừa dối. Ngu nhốc. Hưởng thụ……<Shake:Hehe hehe, <Big:Hahaha haha!>> Màn biểu diễn thật đáng vui thú biết bao, nhện nhỏ ạ."
  },
  AvgDialog_131213_Content_72 = {
    Text = "<Shake:Ngươi……không thể có khả năng sửa đổi số phận……>"
  },
  AvgDialog_131213_Content_73 = {
    Text = "À, không không không, đó là sức mạnh thuộc về các ngươi. Kẻ theo đuổi hoan lạc không làm những chuyện vất vả như vậy."
  },
  AvgDialog_131213_Content_74 = {
    Text = "<Shake:Ta đã nhìn thấy rồi……ngươi sẽ dâng hiến quyền năng chất thể, ngươi sẽ nhìn con đường mở ra, <Big:ngươi sẽ chết trên sân khấu này! Tại sao?!!>>"
  },
  AvgDialog_131213_Content_75 = {
    Text = "Người điều khiển số phận biết tất cả, chỉ có điều không thể biết được người mang hạnh phúc. Bởi vì, bởi vì người mang hạnh phúc không có số phận, người yêu dấu…"
  },
  AvgDialog_131213_Content_76 = {
    Text = "Bạn cúi người xuống, thưởng thức đôi mắt rung động của Nefreya. Nỗi đau và sự tuyệt vọng lấp lánh trong đôi mắt ấy nuôi dưỡng từng inch cơ thể của bạn."
  },
  AvgDialog_131213_Content_77 = {
    Text = "Tất cả cuộc sống của chúng ta, đều là trong việc theo đuổi hạnh phúc. Bỏ qua hạnh phúc, chúng ta không có gì cả… Người hạnh phúc, không có số phận."
  },
  AvgDialog_131213_Content_78 = {
    Text = "Điều ngươi nhìn thấy, là một trò ảo thuật nhỏ, là ta hiện tại — kẻ đã sở hữu ý chí và sức mạnh của thần minh — mở một trò đùa nhỏ với bản thân trong quá khứ, với số phận."
  },
  AvgDialog_131213_Content_79 = {
    Text = "Nắm giữ số phận, sao sánh được với việc đùa cợt số phận thú vị chứ? Đúng không, đại diện của số phận?"
  },
  AvgDialog_131213_Content_8 = {
    Text = "Đến. Trên bức màn sau sân khấu, mạng nhện giống như chất lỏng dệt nên từ ngữ khổng lồ, kinh dị này. Nephreya hít một hơi thật sâu, giang tay ra."
  },
  AvgDialog_131213_Content_80 = {
    Text = "Ngươi từng muốn tiếp tục cuộc đối thoại này một cách nghiêm túc, nhưng ngươi không kiềm chế nổi tiếng cười điên cuồng của mình."
  },
  AvgDialog_131213_Content_81 = {
    Text = "Ngươi là Thủ Mật Nhân? Ngươi là\"N\"? Ngươi không biết, cũng chẳng quan tâm. Quyền năng của Hoan Lạc hòa vào ý chí của sứ đồ, tràn ngập trong từng tế bào của ngươi."
  },
  AvgDialog_131213_Content_82 = {
    Text = "Ngươi muốn cười điên cuồng, muốn hò reo, muốn phô bày sự sỉ nhục dịu dàng nhất và cực đoan nhất trước kẻ thao túng đã bị đánh lừa."
  },
  AvgDialog_131213_Content_83 = {
    Text = "Bạn đã tìm thấy chìa khóa để mở khóa. Bạn quay người lại, cúi chào một cách thanh lịch về phía vị đó."
  },
  AvgDialog_131213_Content_84 = {
    Text = "Arachne, nhà biên kịch vĩ đại! Ngay từ khoảnh khắc đầu tiên tôi đến với thế giới này, đã bắt đầu dệt nên sân khấu này cho tôi"
  },
  AvgDialog_131213_Content_85 = {
    Text = "Hãy dẫn tôi nhìn rõ cách vận hành của số phận, để tôi cảm nhận sức hấp dẫn của sự trêu đùa, hãy cho tôi biết bí mật của \"Hạnh phúc\"..."
  },
  AvgDialog_131213_Content_86 = {
    Text = "Bây giờ, khóa của \"hạnh phúc\"đã được mở. Thế nào, diễn viên của tôi, bạn có hài lòng không?"
  },
  AvgDialog_131213_Content_87 = {
    Text = "Tôi chỉ là người xây dựng sân khấu, việc viết câu chuyện là do chính bạn quyết định."
  },
  AvgDialog_131213_Content_88 = {
    Text = "Bạn mở miệng ra với cô ấy. Bạn là sứ đồ của thần linh. Bạn là nô lệ của hạnh phúc. Bạn là chủ nhân duy nhất không thể tranh cãi của thế giới này. Bạn nâng tay lên, nhẹ nhàng chỉ xuống như một nhạc trưởng."
  },
  AvgDialog_131213_Content_89 = {
    Text = "Để đáp lại…… bây giờ, hãy mặc trang phục diễn của bạn vào, Arachne. Buổi biểu diễn này, rất nhanh sẽ đến lượt bạn biểu diễn"
  },
  AvgDialog_131213_Content_9 = {
    Text = "Sứ đồ của thần linh tối cao, người truyền đạt sự ngu muội của hỗn mang. Ánh sáng của bạn chiếu rọi vào ngục tù vĩnh cửu, tôi đã nghe thấy tiếng gọi hỗn mang của bạn."
  },
  AvgDialog_131213_Content_90 = {
    Text = "Ngươi dễ dàng lay động những sợi tơ số phận từng vô hình kia, như thể tùy ý đặt một khối xếp hình sang một nơi khác."
  },
  AvgDialog_131213_Content_91 = {
    Text = "Khi tất cả sợi tơ số phận bị xáo trộn và tái tạo, những tàn dư chiều không gian bị đánh cắp đã quay trở lại bên nàng."
  },
  AvgDialog_131213_Content_92 = {
    Text = "Những hạt cát tím sẫm, vô tận vô cùng, chảy quanh Arachne, xoay quanh nàng. Trong sáng tạo của ngươi, những tàn dư chiều không gian ấy chưa từng bị đánh cắp."
  },
  AvgDialog_131213_Content_93 = {
    Text = "<color=#8C7E96>Trong quá khứ, trong tương lai, chúng mãi mãi thuộc về Arachne.</color>"
  },
  AvgDialog_131213_Content_94 = {
    Text = "Arachne mỉm cười gật đầu chào bạn, đưa những tàn tro vào cơ thể mình. Bánh xe của cô ấy không bao giờ ngừng lại. Nụ cười của cô ấy chưa từng thay đổi."
  },
  AvgDialog_131213_Content_95 = {
    Text = "Bạn lắc đầu trên sân khấu, phát ra một tiếng thở dài phóng đại."
  },
  AvgDialog_131213_Content_96 = {
    Text = "Chết lặng, không chút nhiệt huyết……Lẽ ra ngươi có thể là một người thú vị biết bao, Arachne."
  },
  AvgDialog_131213_Content_97 = {
    Text = "Bạn và Tà Vy giống nhau, là kẻ rình mò của số phận, cũng là nô lệ của số phận. Niềm vui hiện tại của tôi, các bạn sẽ mãi mãi không thể cảm nhận được."
  },
  AvgDialog_131213_Content_98 = {
    Text = "Hãy nhìn khuôn mặt không có sức sống của bạn đi, Arachne. Tôi thực sự cảm thấy tiếc cho các bạn."
  },
  AvgDialog_131213_Content_99 = {
    Text = "Mỗi người đều có lựa chọn riêng, %player%... có lẽ, tôi nên gọi Ngài là sứ đồ, hay là...\"N\"?"
  },
  AvgDialog_131214_Content_1 = {
    Text = "<Shake:Aaaaah!——>"
  },
  AvgDialog_131214_Content_10 = {
    Text = "Bởi vì... sự trả thù của chúng ta, vẫn chưa kết thúc, và sẽ không bao giờ kết thúc..."
  },
  AvgDialog_131214_Content_11 = {
    Text = "Bạn vô thức lùi lại một bước. Nhưng trên người Nephreya không có bất kỳ dao động nguy hiểm nào xuất hiện."
  },
  AvgDialog_131214_Content_12 = {
    Text = "Cô ấy chỉ khẽ vẫy chân càng, kéo xuống bức màn che bên cạnh, lộ ra khung cảnh sau bức màn."
  },
  AvgDialog_131214_Content_13 = {
    Text = "Đây là…!"
  },
  AvgDialog_131214_Content_14 = {
    Text = "Sợi chỉ đỏ tươi, kết nối với nhiều sân khấu trong nhà hát, kết nối với thành phố tráng lệ nơi nhà hát tọa lạc, kết nối với vô số con rối trong thành phố, hội tụ vào cơ thể đầy vết thương của Nephreya."
  },
  AvgDialog_131214_Content_15 = {
    Text = "Bạn... không nối sợi chỉ vào bánh xe sao?"
  },
  AvgDialog_131214_Content_16 = {
    Text = "Cô ấy đã thấy kết cục. Cô ấy thấy sự thất bại của chính mình. Khi còn sức mạnh, cô ấy đã gắn kết những số phận này với bản thân, giống như…"
  },
  AvgDialog_131214_Content_17 = {
    Text = "Giống như lúc bạn giết tôi lần đầu tiên vậy."
  },
  AvgDialog_131214_Content_18 = {
    Text = "Nefreya mỉm cười, khẽ nhặt lên một sợi chỉ ẩn rất bí mật trước mặt mình."
  },
  AvgDialog_131214_Content_19 = {
    Text = "Sợi chỉ đỏ tươi ấy kéo dài từ phía sau đầu cô, trải qua một hành trình dài đầy cẩn thận, ẩn mật hòa nhập vào cơ thể của Arachne."
  },
  AvgDialog_131214_Content_2 = {
    Text = "Rầm——"
  },
  AvgDialog_131214_Content_20 = {
    Text = "Chúng ta đã lâu không gần nhau như vậy, chị ạ. Cho đến vừa rồi, tôi mới tìm được cơ hội để trả lại sợi chỉ này cho chị."
  },
  AvgDialog_131214_Content_21 = {
    Text = "\"trả\"...?"
  },
  AvgDialog_131214_Content_22 = {
    Text = "Sợi dây này…… là sợi mà tôi đã cắt đứt khi lần đầu tiên phá hủy di vật của mình."
  },
  AvgDialog_131214_Content_23 = {
    Text = "Sự lãng mạn của bạn, sự tốt bụng của bạn, những kỷ niệm của bạn…… Tất cả những gì thuộc về tôi, đã hoàn toàn được trả lại cho bạn."
  },
  AvgDialog_131214_Content_24 = {
    Text = "Bạn đã hoàn thành, Arachne."
  },
  AvgDialog_131214_Content_25 = {
    Text = "Đôi môi của Nephreya cong lên, giống như một đứa trẻ đang ẩn sau bức màn, nhìn người lớn bị trò đùa ác ý của mình trêu chọc."
  },
  AvgDialog_131214_Content_26 = {
    Text = "Trong những khoảnh khắc bạn có lực lượng……đây có phải là việc bạn muốn làm không?"
  },
  AvgDialog_131214_Content_27 = {
    Text = "Thế nào? Ý tưởng tuyệt vời, phải không"
  },
  AvgDialog_131214_Content_28 = {
    Text = "Đến đây, hãy giết tôi! Hãy hoàn toàn phá hủy số phận mà bạn đã từng bỏ rơi! Phá hủy thành phố mà bạn đang trú ngụ, phá hủy nhà hát mà bạn yêu thương, phá hủy từng người ở đây"
  },
  AvgDialog_131214_Content_29 = {
    Text = "Đến đây, Arachne! Mang theo tất cả sự yếu đuối của ngươi, <Shake:giết chết một lần nữa tất cả những gì ngươi yêu thương!!!>"
  },
  AvgDialog_131214_Content_3 = {
    Text = "Tiếng gào thét đau đớn và âm thanh rung chuyển của sự sụp đổ vang vọng khắp nhà hát đổ nát. Sợi chỉ đỏ tươi đứt từng đoạn, chiếc vòng quay đã đồng hành cùng Nephreya suốt đời rơi xuống trước mặt cô ấy."
  },
  AvgDialog_131214_Content_30 = {
    Text = "Tiếng gào thét và cười điên cuồng của Nephreya vang vọng lâu dài trong nhà hát đổ nát."
  },
  AvgDialog_131214_Content_31 = {
    Text = "Thân thể của Arachne dường như trở nên nặng nề chưa từng có. Cô ấy từ từ xoay đầu, quét mắt nhìn mọi thứ liên quan đến Nephreya."
  },
  AvgDialog_131214_Content_32 = {
    Text = "Thông qua khe hở của nhà hát, cô ấy nhìn thấy xe cộ và đám đông đông đúc trong thành phố phồn hoa này. Những gương mặt quen thuộc với những cái tên quen thuộc, xuất hiện ở mọi góc phố mà cô ấy quen thuộc."
  },
  AvgDialog_131214_Content_33 = {
    Text = "Cô ấy thấy sân khấu mà đã từng cùng bạn đặt chân lên. Cuộc chiến tàn khốc đã kết thúc, thế giới đó sắp đón chào một nền hòa bình dài lâu và rực rỡ kéo dài hai trăm năm."
  },
  AvgDialog_131214_Content_34 = {
    Text = "Trong những chất lỏng đen dính đó, cô thấy được khuôn mặt của mẹ. Cô ngồi bên cha dưới cây bạch dương trong sân, vẫy tay về phía mình."
  },
  AvgDialog_131214_Content_35 = {
    Text = "Ngài Edgar đứng bên cạnh họ, lau chùi bộ đồ ăn được làm riêng cho cô."
  },
  AvgDialog_131214_Content_36 = {
    Text = "Bạn gọi đây là sự trả thù, vì bạn chưa bao giờ nhìn rõ số phận, cũng chưa bao giờ nhìn rõ tôi, Nephreya."
  },
  AvgDialog_131214_Content_37 = {
    Text = "Một sợi chỉ dính đầy chất lỏng kết nối Arachne với sân khấu đổ nát dưới chân Nephreia. Kéo theo thân thể nặng nề, Arachne bước lên sợi chỉ mong manh đó."
  },
  AvgDialog_131214_Content_38 = {
    Text = "Sợi tơ run rẩy, dường như khoảnh khắc tiếp theo sẽ đứt gãy, phán người tù nhân của vận mệnh vào vực thẳm vô tận."
  },
  AvgDialog_131214_Content_39 = {
    Text = "Arachne bình thản nhìn vào đôi mắt kinh ngạc của Nephrya. Bước chân cô chưa từng dừng lại dù chỉ một khoảnh khắc."
  },
  AvgDialog_131214_Content_4 = {
    Text = "Cô ấy nắm chặt bánh xe như một đứa bé rơi xuống nước. Trong tay cô, bánh xe tối tăm không thể ngăn cản mà vỡ vụn, biến thành tàn tro của chiều, hòa vào dòng cát bên cạnh Arachne."
  },
  AvgDialog_131214_Content_40 = {
    Text = "Thời khắc định mệnh sắp đến……"
  },
  AvgDialog_131214_Content_41 = {
    Text = "Arachne trên sợi chỉ giơ bánh xe dệt trong tay. Bạn nhìn thấy rõ ràng toàn bộ thế giới dừng lại một khoảnh khắc, toàn bộ vũ trụ gắn liền với nhà hát này đều đang chờ đợi mệnh lệnh của cô ấy."
  },
  AvgDialog_131214_Content_42 = {
    Text = "Tôi lấy danh nghĩa số phận, tại đây tuyên bố——"
  },
  AvgDialog_131214_Content_43 = {
    Text = "Tất cả vận số sai lầm, sẽ chìm vào cát bụi thời gian. Vận mệnh của thế giới, sẽ trở về quỹ đạo định mệnh."
  },
  AvgDialog_131214_Content_44 = {
    Text = "Những sợi tơ rối loạn, tại đây bị cắt đứt. Kẻ bất hạnh bị ruồng bỏ, sẽ yên nghỉ nơi đây……"
  },
  AvgDialog_131214_Content_45 = {
    Text = "Bánh xe dệt nghiêng, hàng ngàn sợi chỉ theo đó rung động."
  },
  AvgDialog_131214_Content_46 = {
    Text = "Sợi chỉ đứt. Đợi chờ sân khấu hòa bình, sụp đổ và tan biến."
  },
  AvgDialog_131214_Content_47 = {
    Text = "Sợi chỉ đứt gãy. Trong khe nứt của nhà hát, không còn thấy dấu vết của thành phố."
  },
  AvgDialog_131214_Content_48 = {
    Text = "Sợi chỉ đứt, đứt, đứt……"
  },
  AvgDialog_131214_Content_49 = {
    Text = "Bạn khó có thể nhìn thấy những sợi chỉ số phận, nhưng bạn lại nghe rõ tiếng khóc và la hét của số phận."
  },
  AvgDialog_131214_Content_5 = {
    Text = "Nephreya ngây người nhìn vào sự trôi qua của hy vọng, bỗng nhiên cười khúc khích."
  },
  AvgDialog_131214_Content_50 = {
    Text = "Vô số kiếp sống của con người, vô số nỗi buồn vui ly hợp, bên tai bạn vỡ vụn, phân tách, tái cấu trúc, diệt vong…"
  },
  AvgDialog_131214_Content_51 = {
    Text = "……ánh sáng?"
  },
  AvgDialog_131214_Content_52 = {
    Text = "Ánh đèn sân khấu không biết từ đâu sáng lên. Ánh sáng xuyên qua nhà hát đổ nát, những kẻ bị bỏ rơi ẩn mình trong bóng tối, vào khoảnh khắc ánh sáng chiếu xuống đã biến mất, dường như chưa từng xuất hiện."
  },
  AvgDialog_131214_Content_53 = {
    Text = "Arachne, chị, bạn……"
  },
  AvgDialog_131214_Content_54 = {
    Text = "Arachne mang theo bánh xe dệt, bước qua sợi chỉ mong manh, đến trước mặt cô ấy. Nephreya ngẩng đầu nhìn cô, như thể đang nhìn vào số phận không thể trái ngược."
  },
  AvgDialog_131214_Content_55 = {
    Text = "Đến gần tôi, Nefreya."
  },
  AvgDialog_131214_Content_56 = {
    Text = "Arachne nắm tay Nefreya, áp vào má mình."
  },
  AvgDialog_131214_Content_57 = {
    Text = "Khi chạm vào Arachne, một cánh cửa ẩn mở ra cho Nephreya. Nephreya đã vượt qua những lớp lớp nhà giam, lần đầu tiên thực sự đứng trước mặt Arachne."
  },
  AvgDialog_131214_Content_58 = {
    Text = "Trong cái lồng giam đó, cô ấy nhìn thấy ba khuôn mặt quen thuộc."
  },
  AvgDialog_131214_Content_59 = {
    Text = "Arachne!!! Bạn……"
  },
  AvgDialog_131214_Content_6 = {
    Text = "Tiếng cười của cô ấy ngày càng lớn, gần như không có sức để ngồi dậy. Máu từ cơ thể run rẩy của cô nhỏ giọt, nhuộm đỏ những mảnh vụn tối tăm của bánh xe."
  },
  AvgDialog_131214_Content_60 = {
    Text = "<Shake:Lãng mạn, lương thiện, ký ức…… Chúng…… Chúng……>"
  },
  AvgDialog_131214_Content_61 = {
    Text = "Tôi chưa bao giờ có thể hoàn toàn từ bỏ chúng. Tôi chưa bao giờ có thể thực sự từ bỏ bạn."
  },
  AvgDialog_131214_Content_62 = {
    Text = "Nhưng bạn đã nói, bạn không thể chịu đựng những điều này……"
  },
  AvgDialog_131214_Content_63 = {
    Text = "Ngu ngốc, mong manh, đau đớn phá hủy mọi thứ tôi trân trọng... bạn không thể trả thù tôi bằng cách này, Nephreya."
  },
  AvgDialog_131214_Content_64 = {
    Text = "Bởi vì, đây là hình phạt đã được số phận định sẵn cho tôi."
  },
  AvgDialog_131214_Content_65 = {
    Text = "Arachne bình tĩnh mỉm cười với cô ấy. Bánh xe dệt của cô ấy xoay chuyển, vĩnh viễn không ngừng."
  },
  AvgDialog_131214_Content_66 = {
    Text = "Kết thúc rồi, Nephreya."
  },
  AvgDialog_131214_Content_67 = {
    Text = "Một sợi dây đàn nhẹ nhàng rung động. Nephreya nghe thấy tiếng kêu của con cò trắng, giống như khi cô còn rất nhỏ, vào ngày cha mang đến cho cô chiếc bánh xe dệt tên là Moirai."
  },
  AvgDialog_131214_Content_68 = {
    Text = "Đây là căn phòng thuộc về cô ấy, cây bạch dương bên ngoài cửa sổ là người bạn trung thành của cô, một tù nhân cô đơn không bao giờ thay đổi từ thời xa xưa."
  },
  AvgDialog_131214_Content_69 = {
    Text = "Họ bị số phận giam cầm, họ dựa vào nhau mà sống."
  },
  AvgDialog_131214_Content_7 = {
    Text = "Kết thúc, kết thúc quả thật không thể thay đổi được… Đây chính là số phận…"
  },
  AvgDialog_131214_Content_70 = {
    Text = "Chít——"
  },
  AvgDialog_131214_Content_71 = {
    Text = "Cánh cửa gỗ mộc mạc được đẩy ra, Arachne đến bên cô, cúi xuống, nhẹ nhàng vuốt ve khuôn mặt cô."
  },
  AvgDialog_131214_Content_72 = {
    Text = "Chị…… em thua rồi…… chúng ta thua rồi……"
  },
  AvgDialog_131214_Content_73 = {
    Text = "Chúng ta chưa bao giờ có quyền thắng."
  },
  AvgDialog_131214_Content_74 = {
    Text = "Bạn còn nhớ ngày nhận được vòng quay, ước nguyện mà chúng ta đã đưa ra không?"
  },
  AvgDialog_131214_Content_75 = {
    Text = "\"Tôi sẽ không phụ món quà của vận mệnh... Tôi sẽ mang vận mệnh tốt đẹp đến cho thế giới này...\""
  },
  AvgDialog_131214_Content_76 = {
    Text = "Một ước muốn thật ngây thơ, Arachne... Lúc đó, chúng ta hoàn toàn không hiểu điều này có nghĩa là gì."
  },
  AvgDialog_131214_Content_77 = {
    Text = "Arachne đưa ra bàn tay run rẩy đó, vuốt ve khuôn mặt xa xôi của chính mình."
  },
  AvgDialog_131214_Content_78 = {
    Text = "Số phận…… ai có thể thật sự nhìn rõ chứ."
  },
  AvgDialog_131214_Content_79 = {
    Text = "Nhưng ngay cả khi có thể dự đoán, sự lựa chọn của tôi vẫn sẽ không thay đổi."
  },
  AvgDialog_131214_Content_8 = {
    Text = "Chiến thắng bi thảm này, bạn đã sớm nhìn thấy, đúng không, Arachne?"
  },
  AvgDialog_131214_Content_80 = {
    Text = "<Shake:Tại sao, Arachne?> Cô có thể rời đi, cô có thể từ bỏ, cô có thể……"
  },
  AvgDialog_131214_Content_81 = {
    Text = "Sau khi rời khỏi ngục sâu, bạn lẽ ra có thể có được tự do vĩnh cửu. Bạn biết mình cuối cùng sẽ thất bại, nhưng bạn vẫn muốn thử để mang lại sự giải thoát cho tôi, cho những số phận đã theo bạn."
  },
  AvgDialog_131214_Content_82 = {
    Text = "Mỗi một người điều khiển số phận, đều sẽ trở thành tù nhân của số phận, bạn và tôi đều như vậy. Đúng không, Nephreya?"
  },
  AvgDialog_131214_Content_83 = {
    Text = "Nefreya im lặng, buồn bã nhìn ra cây bạch dương ngoài cửa sổ. Cô ấy nhìn cây đó đâm chồi, nảy lộc, phát triển, rồi héo úa."
  },
  AvgDialog_131214_Content_84 = {
    Text = "Cô ấy thở dài nhẹ nhàng, ngẩng đầu lên, vuốt ve những giọt nước mắt từ từ rơi trên mặt Arachne. Cô mỉm cười với cô ấy."
  },
  AvgDialog_131214_Content_85 = {
    Text = "Thật tốt khi được gặp lại em... Chị gái."
  },
  AvgDialog_131214_Content_86 = {
    Text = "Một giọt nước mắt nhẹ nhàng rơi xuống, nhỏ giọt trên khuôn mặt giống hệt với Arachne."
  },
  AvgDialog_131214_Content_87 = {
    Text = "Xin hãy tha thứ cho sự ích kỷ của tôi……"
  },
  AvgDialog_131214_Content_88 = {
    Text = "Cô…… đã tự do rồi, <Red:「Arachne」>."
  },
  AvgDialog_131214_Content_89 = {
    Text = "Chít——."
  },
  AvgDialog_131214_Content_9 = {
    Text = "Vừa rồi, bạn cũng đã nhìn lén mọi thứ này trong một khoảnh khắc. Vì đã biết kết cục cuối cùng, tại sao còn phải cố chấp vào điều này?"
  },
  AvgDialog_131214_Content_90 = {
    Text = "Khi sợi tơ cuối cùng đứt lìa, bạn nghe thấy một tràng vỗ tay vang dội như sấm."
  },
  AvgDialog_131214_Content_91 = {
    Text = "Luôn luôn là những chỗ ngồi trống rỗng dưới sân khấu, nay đã không còn chỗ trống. Những số phận bị bỏ rơi và những con rối chết trong tay các bạn, đã chen chúc đầy mỗi chiếc ghế nhung bị vỡ."
  },
  AvgDialog_131214_Content_92 = {
    Text = "Các diễn viên ngồi vào vị trí của khán giả, lặng lẽ dõi theo kết cục của sân khấu này."
  },
  AvgDialog_131214_Content_93 = {
    Text = "Họ không biểu cảm, im lặng không một tiếng động. \n Họ nhiệt tình vỗ tay. Tiếng vỗ tay vang dội, kéo dài không dứt."
  },
  AvgDialog_131215_Content_1 = {
    Text = "Người trong kịch"
  },
  AvgDialog_131215_Content_10 = {
    Text = "Trước đây tôi không hiểu, tại sao Arachne lại muốn loại bỏ em gái mình khỏi mạng số phận, còn bạn tại sao lại muốn lấy sức mạnh từ ba bí ẩn đó."
  },
  AvgDialog_131215_Content_101 = {
    Text = "Nữ thần số phận kiên cường nhưng vô ích… Thật tuyệt vọng, thật đẹp đẽ làm sao…"
  },
  AvgDialog_131215_Content_102 = {
    Text = "Các bạn nói, cô ấy làm như vậy là vì lý do gì?"
  },
  AvgDialog_131215_Content_103 = {
    Text = "Nefreya chăm chú nhìn về sân khấu giản dị này, giọng nói nhỏ như thì thầm."
  },
  AvgDialog_131215_Content_104 = {
    Text = "Đây chỉ là một giấc mơ, nữ thần số phận... bạn hoàn toàn có thể chọn số phận vui vẻ nhất cho mọi người, bạn có thể điều chỉnh những ảo tưởng không thực tế của mình, thỏa mãn mọi điều bạn mong muốn."
  },
  AvgDialog_131215_Content_105 = {
    Text = "Nhưng bạn chưa bao giờ nghĩ đến việc làm như vậy…… Khi bạn tạo ra sự hoàn hảo, bạn cũng đang tạo ra nỗi đau. Bạn liên tục để nỗi đau đến với thế gian này."
  },
  AvgDialog_131215_Content_106 = {
    Text = "Bạn đã cố gắng hết sức, muốn dệt nên tấm mạng lưới khổng lồ của số phận, nhưng cảnh tượng bên trong cánh cửa đó, kết cục đã được định sẵn của số phận, bạn và tôi đều đã từng nhìn thấy."
  },
  AvgDialog_131215_Content_107 = {
    Text = "Khi mạng lưới số phận được dệt nên, chính là lúc vị đó, thần minh tối cao hoàn toàn tỉnh giấc…"
  },
  AvgDialog_131215_Content_108 = {
    Text = "Cái gì……?!"
  },
  AvgDialog_131215_Content_109 = {
    Text = "Bạn nhìn về phía Arachne, hy vọng nhận được một câu trả lời phủ định từ khuôn mặt cô ấy."
  },
  AvgDialog_131215_Content_11 = {
    Text = "Ít nhất, tôi phải cảm ơn bạn đã giải đáp những thắc mắc của tôi."
  },
  AvgDialog_131215_Content_110 = {
    Text = "Trên gương mặt ấy, ngoài sự bình thản như mọi khi, bạn chẳng thể nhìn thấy gì khác. Trên sân khấu số mệnh, bình thản là chiếc mặt nạ mà nàng không thể tháo xuống."
  },
  AvgDialog_131215_Content_111 = {
    Text = "Chị ơi, chị không thể ngừng dệt mạng, vì chị không thể ngồi nhìn số phận của vũ trụ này rơi vào hỗn loạn. Và đến ngày tấm mạng của chị được dệt xong, chị sẽ tự tay chôn vùi tất cả những gì chị yêu thương……"
  },
  AvgDialog_131215_Content_112 = {
    Text = "Thật mỉa mai, Arachne. Tại sao vậy? Tại sao không để vũ trụ này đón nhận kết thúc định mệnh trong niềm vui?"
  },
  AvgDialog_131215_Content_113 = {
    Text = "Tất cả số phận đều có định số. Tất cả số phận đều có biến số. Hai câu châm ngôn mâu thuẫn này chính là bản chất của số phận."
  },
  AvgDialog_131215_Content_114 = {
    Text = "Arachne nhìn vào mắt Nefreya, trả lời câu hỏi mà cô đã từng trả lời cho chính mình vô số lần."
  },
  AvgDialog_131215_Content_115 = {
    Text = "Nephreya, trong những chiều không gian vô tận, còn vô số người đang chiến đấu vì biến số đó."
  },
  AvgDialog_131215_Content_116 = {
    Text = "Duy trì sự vận hành của sân khấu, đợi biến số xuất hiện…… Đây là xiềng xích mà số phận đã đeo lên tôi. Đây là trách nhiệm mà tôi không thể trốn tránh."
  },
  AvgDialog_131215_Content_117 = {
    Text = "Bổn phận, hiểm nguy… em nói về tất cả những điều vĩ đại ấy, duy chỉ chưa từng nói về chính mình, Arachne, người chị đáng thương của ta. Nhưng không sao, bổn phận đau khổ của chị sắp kết thúc rồi."
  },
  AvgDialog_131215_Content_118 = {
    Text = "Nefreya âu yếm vuốt ve khuôn mặt của Arachne, nở một nụ cười ngọt ngào với cô ấy."
  },
  AvgDialog_131215_Content_119 = {
    Text = "Trong vực sâu, tôi đã tưởng tượng vô số lần hình ảnh chúng ta gặp lại, tôi suy nghĩ về món quà nào xứng đáng với cuộc tái ngộ của chúng ta lần này."
  },
  AvgDialog_131215_Content_12 = {
    Text = "Những chuyện này, tại sao trước đây không nói cho tôi?"
  },
  AvgDialog_131215_Content_120 = {
    Text = "Tôi đã nghĩ rất lâu, rất lâu. Tôi đã nghĩ đến, chị gái yêu quý! Đây là món quà tốt nhất tôi có thể tặng bạn——"
  },
  AvgDialog_131215_Content_121 = {
    Text = "——<Red:Giải thoát>."
  },
  AvgDialog_131215_Content_122 = {
    Text = "Giọng nói nhẹ nhàng của Nephreya, chất lỏng đen dính tụ lại giữa các khe hở của chiều. Ở cuối mạng nhện, một sân khấu hoành tráng xuất hiện trước mặt các bạn."
  },
  AvgDialog_131215_Content_13 = {
    Text = "Bạn nhìn về phía Arachne, người đang dẫn dắt bước chân của bạn."
  },
  AvgDialog_131215_Content_14 = {
    Text = "Một viên đá sẽ không làm dậy sóng trong hồ số phận, ngoài việc phá hoại sự yên tĩnh của hồ, hoàn toàn không có tác dụng gì."
  },
  AvgDialog_131215_Content_15 = {
    Text = "Nàng ấy và ta, từ lâu đã là hai người khác nhau rồi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131215_Content_16 = {
    Text = "Bạn có dự đoán ngày này không?"
  },
  AvgDialog_131215_Content_17 = {
    Text = "Trước khi nhận được phán quyết của số mệnh, không tù nhân nào có thể nhìn thấu vận mệnh của chính mình."
  },
  AvgDialog_131215_Content_18 = {
    Text = "Nếu bạn biết rằng những số phận bị bỏ rơi sẽ không biến mất, mà sẽ bị lưu đày vào vực sâu vĩnh hằng... bạn vẫn sẽ làm những điều này chứ, Arachne?"
  },
  AvgDialog_131215_Content_2 = {Text = "Lalalala"},
  AvgDialog_131215_Content_20 = {
    Text = "Im lặng. Im lặng chính là thảm họa vĩnh cửu của tác giả kịch. Im lặng là sự tự vệ bất lực của tù nhân. Trong sự im lặng như hình phạt cực đoan, vang lên tiếng cười điên cuồng của Nefreya."
  },
  AvgDialog_131215_Content_21 = {
    Text = "À, chị chắc chắn sẽ làm được. Số phận là giáo lý của bạn, tất cả, tất cả các điều kiện, đều không thể thay đổi câu trả lời duy nhất của nó."
  },
  AvgDialog_131215_Content_22 = {
    Text = "Nữ thần số phận, thật nhỏ bé, thật mong manh, thật tàn nhẫn…"
  },
  AvgDialog_131215_Content_23 = {
    Text = "Tuy nhiên không sao cả. Dù bạn làm thế nào, trong suốt khoảng thời gian dài này, tôi luôn lo lắng cho bạn, chị gái tốt của tôi."
  },
  AvgDialog_131215_Content_24 = {
    Text = "Lãng mạn, nhân hậu, hồi ức. Nguyên liệu tốt đẹp hòa trộn, lên men, chế biến nụ cười của Nefreya thành một liều thuốc độc ngọt ngào."
  },
  AvgDialog_131215_Content_25 = {
    Text = "Trong nụ cười rạng rỡ của cô ấy, ánh sáng từ mạng nhện bên đường chiếu sáng sân khấu."
  },
  AvgDialog_131215_Content_26 = {
    Text = "Chị ơi, Người Giữ Bí Mật {Male=先生,Female=小姐}, những vở kịch mới được trình diễn này là món quà mà em — với tư cách chủ nhân mới của nhà hát — dành tặng cho các người."
  },
  AvgDialog_131215_Content_27 = {
    Text = "Trước khi màn thứ ba hoành tráng bắt đầu, hãy thưởng thức khúc dạo đầu tuyệt vời này nhé…… Ghi nhớ nghi thức xem kịch tại nhà hát số phận, đừng nói chuyện nhé"
  },
  AvgDialog_131215_Content_28 = {
    Text = "Nefreya dang tay ra như một người giới thiệu. Sân khấu lấp lánh như những vì sao dọc đường, lần lượt sáng lên khi các bạn từ từ đi qua."
  },
  AvgDialog_131215_Content_3 = {
    Text = "Chúng nhảy múa. Chúng hát ca. Chít ya chít ya~"
  },
  AvgDialog_131215_Content_30 = {
    Text = "Nữ thần số phận kính yêu, thân xác của ba vị bí nhân đã được chuẩn bị sẵn cho ngài."
  },
  AvgDialog_131215_Content_31 = {
    Text = "Con búp bê tinh xảo biết bao… Những gì đã mất sẽ tái hiện trên chúng…"
  },
  AvgDialog_131215_Content_32 = {
    Text = "\"Arachne\" rời khỏi máy dệt, đến trước mặt búp bê."
  },
  AvgDialog_131215_Content_33 = {
    Text = "Món quà đầu tiên, tôi ban cho bạn là\"lãng mạn\"."
  },
  AvgDialog_131215_Content_34 = {
    Text = "Bạn là chương đầy đam mê nhất của bản nhạc, là sự tập hợp của cảm xúc, là trái ngọt từ những bông hoa của mùa xuân."
  },
  AvgDialog_131215_Content_35 = {
    Text = "Bạn sẽ đến với công viên của nửa đêm, mang đến cho thành phố này rượu ngon, những cuộc gặp gỡ và những cảm xúc không bao giờ phai nhạt."
  },
  AvgDialog_131215_Content_36 = {
    Text = "Cảm ơn bạn, nữ thần số phận vĩ đại Arachne. Theo ý nguyện của bạn, rượu và mật sẽ chảy trên môi và răng của tôi."
  },
  AvgDialog_131215_Content_37 = {
    Text = "Người phụ nữ xinh đẹp cúi chào Arachne."
  },
  AvgDialog_131215_Content_38 = {
    Text = "Cái thứ hai, tôi ban tặng bạn là\"Lương thiện\"."
  },
  AvgDialog_131215_Content_39 = {
    Text = "Bạn là người già đã đồng hành cùng tôi trải qua thời thơ ấu. Bạn là chiếc lông trắng rơi rớt của thiên thần, là ánh sáng mặt trời thuần khiết nhất."
  },
  AvgDialog_131215_Content_4 = {
    Text = "Câu chuyện xa xưa và bước chân vui vẻ cùng nhau rung động trên mạng nhện. Nefreya hai tay để sau lưng, nhảy nhót nhẹ nhàng tiến về phía trước."
  },
  AvgDialog_131215_Content_40 = {
    Text = "Bạn sẽ đến những con phố của thành phố, dùng lòng tốt của mình để làm ấm mọi thứ bạn thấy."
  },
  AvgDialog_131215_Content_41 = {
    Text = "Cảm ơn ngài! Nữ thần số phận vĩ đại Arachne. Sinh mệnh của tôi được ngài ban cho, không biết báo đáp thế nào."
  },
  AvgDialog_131215_Content_42 = {
    Text = "Tôi không có gì cả, chỉ yêu thương mọi thứ trên thế gian này. Tôi sẽ bảo vệ những gì cần bảo vệ, giúp đỡ những gì cần giúp đỡ."
  },
  AvgDialog_131215_Content_43 = {
    Text = "Tất cả những gì tôi có đều mở ra cho những người chịu nạn."
  },
  AvgDialog_131215_Content_44 = {
    Text = "Người già hiền hậu cúi chào sâu sắc về phía \"Arachne\"."
  },
  AvgDialog_131215_Content_45 = {
    Text = "Còn bạn, cơ thể thứ ba... tôi ban cho bạn cái tên \"Ký ức\"."
  },
  AvgDialog_131215_Content_46 = {
    Text = "\"Arachne\"đến trước bức tượng nhỏ bé đó, quỳ xuống nhìn vào đôi mắt không tồn tại của cô ấy."
  },
  AvgDialog_131215_Content_47 = {
    Text = "Bạn là đứa trẻ mồ côi của số phận, bị chôn vùi trong lá khô của tuyết sâu."
  },
  AvgDialog_131215_Content_48 = {
    Text = "Bạn đơn độc bước đi, không thể thốt nên lời, không ai hiểu được."
  },
  AvgDialog_131215_Content_49 = {
    Text = "Trong cuộc sống dài lâu yên tĩnh của bạn, bạn sẽ là người giữ mộ duy nhất của những ký ức đó."
  },
  AvgDialog_131215_Content_5 = {
    Text = "Bạn không thể không theo sau Arachne, đi dọc theo mạng nhện đến tận cùng."
  },
  AvgDialog_131215_Content_50 = {
    Text = "Cô gái im lặng ngẩng đầu lên, nhẹ nhàng vuốt ve mặt của \"Arachne\"."
  },
  AvgDialog_131215_Content_51 = {
    Text = "\"Arachne\"đứng dậy, nhẹ nhàng nhìn qua các bí ẩn của cô ấy."
  },
  AvgDialog_131215_Content_52 = {
    Text = "Đi đi, các con của tôi. Trước chiếc máy dệt của số phận, tôi sẽ mãi mãi nhìn các con."
  },
  AvgDialog_131215_Content_53 = {
    Text = "Những điều đã bị bỏ rơi vĩnh viễn, sẽ nở rộ từng cái trong số phận của các bạn."
  },
  AvgDialog_131215_Content_55 = {
    Text = "Sân khấu tối đi. Cùng với bước chân của các bạn, ánh sáng sân khấu tiếp theo sáng lên."
  },
  AvgDialog_131215_Content_56 = {
    Text = "Ánh sáng mặt trời không tồn tại ở nơi này. Gió, hoa, đám mây…… ba thế kỷ dài trôi qua, lịch cũng không còn tồn tại nữa……"
  },
  AvgDialog_131215_Content_57 = {
    Text = "Chủ nhân, người bị bỏ rơi mới đã đến."
  },
  AvgDialog_131215_Content_58 = {
    Text = "Kèn oboe tấu lên. Kẻ bị ruồng bỏ áo quần rách rưới bước ra sân khấu."
  },
  AvgDialog_131215_Content_59 = {
    Text = "\"Nefreya\"đứng dậy, tiến ra giữa sân khấu."
  },
  AvgDialog_131215_Content_6 = {
    Text = "Thế nào, Người Giữ Bí Mật {Male=先生,Female=小姐}! Màn biểu diễn vừa rồi, kết hợp với câu chuyện hậu trường này, có tuyệt vời không!"
  },
  AvgDialog_131215_Content_60 = {
    Text = "Hãy cho tôi biết, đứa trẻ đáng thương… các bạn là ai, đến từ đâu?"
  },
  AvgDialog_131215_Content_61 = {
    Text = "Nữ thần số phận, xin ngài tha thứ cho sự bất kính của tôi… nhưng cơn giận khiến tôi không thể không hỏi ngài."
  },
  AvgDialog_131215_Content_62 = {
    Text = "Tôi đã trải qua bao hiểm nguy, dùng lòng dũng cảm và sinh mệnh của mình để lại một bài ca hùng vĩ, nó đáng lẽ phải cùng với quê hương của tôi, đi đến tận cùng của vũ trụ."
  },
  AvgDialog_131215_Content_63 = {
    Text = "Tại sao, hỡi nữ thần vĩ đại… tại sao lại trục xuất chúng tôi đến vùng đất hoang vu này? <Shake:Vì sao, lại biến những nhạc chương bất tử thành tro bụi!>"
  },
  AvgDialog_131215_Content_64 = {
    Text = "Binh sĩ của tôi vừa trải qua một mùa đông dài. Chúng tôi đã đẩy lùi những kẻ xâm lược man rợ, bảo vệ nền văn minh và lịch sử của chúng tôi."
  },
  AvgDialog_131215_Content_65 = {
    Text = "Trong lúc khốc liệt nhất, những binh sĩ bị thương tự nguyện hiến dâng thịt máu của họ để đồng đội ăn uống… Một chiến thắng thật đau thương, nữ thần của tôi."
  },
  AvgDialog_131215_Content_66 = {
    Text = "Khi kẻ thù rút lui, nước mắt vui mừng tràn đầy trong đôi mắt của mọi người. Trong buổi tiệc ăn mừng, tôi sẽ rót đầy ly rượu của từng binh sĩ bằng rượu mạnh."
  },
  AvgDialog_131215_Content_67 = {
    Text = "Nhưng ngay lúc này, khi chúng ta vẫn chưa nâng chén chúc mừng, quê hương của chúng ta đã trở thành đổ nát, người thân của chúng ta đã bị diệt vong thành bụi bặm…"
  },
  AvgDialog_131215_Content_68 = {
    Text = "<Shake:Hỡi nữ thần số mệnh kính yêu, lẽ nào Người không nỡ ban cho chúng tôi dù chỉ một khoảnh khắc hoan hỉ sao?>"
  },
  AvgDialog_131215_Content_7 = {
    Text = "Nữ thần Nefreya đã rời khỏi trạng thái cuồng loạn trên sân khấu, cô ấy quay đầu lại, nhìn bạn với vẻ mong chờ tràn đầy."
  },
  AvgDialog_131215_Content_70 = {
    Text = "\"Nefreya\" lắng nghe những con rối dường như không bao giờ ngừng kể chuyện, trên khuôn mặt không có ngũ quan ấy, bất ngờ rơi xuống hai hàng nước mắt."
  },
  AvgDialog_131215_Content_71 = {
    Text = "Tôi đã nghe thấy các bạn, đã nhìn thấy các bạn rồi…"
  },
  AvgDialog_131215_Content_72 = {
    Text = "Nền văn minh vĩ đại đã biến mất khỏi tay bạn; những công trình nghệ thuật lấp lánh đã trở thành bụi mù. Những người yêu thương nhau quên đi tất cả về nhau, trong sự hoảng loạn chào đón cái chết đau khổ..."
  },
  AvgDialog_131215_Content_73 = {
    Text = "Chỉ có một số phận đúng sẽ được giữ lại, và những số phận sai lầm xảy ra trong khoảnh khắc đó, tất cả đều tràn vào vực thẳm hoang vu không đáy. Dài đằng đẵng như thời gian ngừng trôi, câu chuyện như vậy hàng ngày đều được tái diễn."
  },
  AvgDialog_131215_Content_74 = {
    Text = "Chị gái yêu quý, em muốn chị cho em xem bao lâu, nghe bao lâu…"
  },
  AvgDialog_131215_Content_75 = {
    Text = "\"Nefreya\" hướng về phía khán giả hít sâu một hơi, rồi quay người lại."
  },
  AvgDialog_131215_Content_76 = {
    Text = "Xin hãy yên tâm, những đứa trẻ ngoan của tôi… Nỗi khổ đau của các con do tôi tạo ra, thì cũng sẽ do tôi kết thúc."
  },
  AvgDialog_131215_Content_77 = {
    Text = "Xin hãy tạm nghỉ ngơi ở đây. Một ngày nào đó, tôi sẽ đưa các bạn rời khỏi đây, tôi sẽ giúp các bạn tìm lại số phận thuộc về mình…"
  },
  AvgDialog_131215_Content_78 = {
    Text = "Nhân danh báo thù của số phận, tôi hứa với các bạn……"
  },
  AvgDialog_131215_Content_8 = {
    Text = "Thấy khuôn mặt bạn im lặng, cô ấy thất vọng lắc đầu."
  },
  AvgDialog_131215_Content_80 = {
    Text = "Lalalala……la la……"
  },
  AvgDialog_131215_Content_81 = {
    Text = "Sân khấu dần dần xa khuất, trước khi ánh sáng tắt, bạn thấy con rối dang rộng đôi tay, và vết nước mắt đen trên mặt nó."
  },
  AvgDialog_131215_Content_82 = {
    Text = "Các bạn không nói chuyện, chỉ có Nephreya nhẹ nhàng hát lên những giai điệu trên sân khấu. Giọng hát của cô ấy vui vẻ và trong trẻo, câu chuyện đã diễn ra vô số lần, không khiến cô ấy phát sinh thêm bất kỳ cảm xúc dư thừa nào."
  },
  AvgDialog_131215_Content_83 = {
    Text = "Ôi! Sân khấu mà tôi thích nhất sắp đến rồi! Nhanh lên, chị gái"
  },
  AvgDialog_131215_Content_84 = {
    Text = "Giọng Nephreya hưng phấn lên. Cô nắm tay Arachne, vui vẻ chạy về phía sân khấu ở phía trước."
  },
  AvgDialog_131215_Content_86 = {
    Text = "Đèn sáng lên. Không có tiếng nhạc, cũng không có lời thoại, trên sân khấu trống trải, chỉ có một bóng hình cô độc ngồi trước guồng xe sợi."
  },
  AvgDialog_131215_Content_87 = {
    Text = "Kẽo kẹt, kẽo kẹt. Guồng xe sợi không ngừng quay, tựa như chẳng bao giờ có ngày dừng lại."
  },
  AvgDialog_131215_Content_88 = {
    Text = "……chúng nhảy múa. Chúng hát ca. Chít—— chít——"
  },
  AvgDialog_131215_Content_89 = {
    Text = "Ánh nắng chiếu sáng khuôn mặt của chúng, thật vui vẻ——"
  },
  AvgDialog_131215_Content_9 = {
    Text = "Không có tiếng vỗ tay, cũng không có nước mắt. Sự im lặng là một sự sỉ nhục... Tôi cứ tưởng rằng sau khi luyện tập lâu như vậy trong địa ngục, màn trình diễn này đã hoàn hảo rồi, thật đáng tiếc."
  },
  AvgDialog_131215_Content_90 = {
    Text = "Bài ca dao nhẹ nhàng ngân lên từ gương mặt không ngũ quan của \"Arachne\", nàng thong thả quay guồng xe sợi, không vội cũng không chậm."
  },
  AvgDialog_131215_Content_91 = {
    Text = "Đó là một nhịp điệu kỳ lạ, chỉ cần nhìn một lần là bạn hiểu, thứ nhịp điệu ấy một khi đã bắt đầu sẽ vĩnh hằng bất biến, cho đến ngày tất cả đi đến tận cùng."
  },
  AvgDialog_131215_Content_92 = {
    Text = "Nữ thần số phận, sắp phải dệt xong mạng lưới của cô ấy."
  },
  AvgDialog_131215_Content_93 = {
    Text = "Mạng lưới số phận hoàn chỉnh, che chở cho tất cả mọi người… Chúng nhảy múa, chúng ca hát…"
  },
  AvgDialog_131215_Content_94 = {
    Text = "Một tấm lưới khổng lồ được dệt ra từ máy dệt, trải khắp toàn bộ sân khấu. Phần thừa của mạng lưới số phận lan ra phía dưới sân khấu."
  },
  AvgDialog_131215_Content_95 = {
    Text = "Mỗi khi tấm lưới sắp được dệt xong, phần ngoài cùng lại bắt đầu tan chảy."
  },
  AvgDialog_131215_Content_96 = {
    Text = "Chất lỏng màu đen, bột màu đen, cuối cùng biến mất không dấu vết. Đó là cảnh tượng mà bạn không thể quen thuộc hơn."
  },
  AvgDialog_131215_Content_97 = {
    Text = "Hãy ăn mừng, con của tôi, dân tộc của tôi…… Nữ thần số phận, sắp dệt xong cái lưới của bà……"
  },
  AvgDialog_131215_Content_98 = {
    Text = "Con rối nhìn những chiếc lưới liên tục được dệt lên rồi lại biến mất."
  },
  AvgDialog_131215_Content_99 = {
    Text = "Giọng cô ấy không run rẩy, động tác của cô ấy không do dự. Cô ấy vẫn nhẹ nhàng hát những bài đồng dao, bánh xe dệt trong tay quay tròn, không bao giờ ngừng lại."
  },
  AvgDialog_131216_Content_1 = {
    Text = "Bữa tiệc mặt nạ"
  },
  AvgDialog_131216_Content_10 = {
    Text = "Thật là một tiêu chuẩn kép không hề che giấu, anh trai."
  },
  AvgDialog_131216_Content_11 = {
    Text = "Khụ... Đưa ra phán đoán phù hợp với tính cách của từng người là kỹ năng cơ bản của một điều tra viên..."
  },
  AvgDialog_131216_Content_12 = {
    Text = "William giả vờ không nghe ra sự chế nhạo của bạn, bắt đầu nghiêm túc tìm kiếm mục tiêu đáng để hỏi."
  },
  AvgDialog_131216_Content_13 = {
    Text = "Tôi đã mất tất cả trong cuộc chiến đó. Địa vị của tôi, gia đình tôi, chân trái của tôi, cuộc đời của tôi."
  },
  AvgDialog_131216_Content_14 = {
    Text = "Hai mươi năm, đúng hai mươi năm. Đây là một hình phạt, bạn tôi. Số phận đã khiến tôi sống sót, để tôi dùng phần đời còn lại để chuộc lại lỗi lầm của mình."
  },
  AvgDialog_131216_Content_15 = {
    Text = "Gia đình tôi đã bị hủy hoại bởi chính tay tôi, nhưng điều đó có ý nghĩa gì? Hãy nói cho tôi biết, trong cuộc đời này có điều gì quan trọng hơn rượu?"
  },
  AvgDialog_131216_Content_17 = {
    Text = "A, thân mến, còn nhớ lần trước đến đây, người pha chế đã pha cho chúng ta ly rượu gì không?"
  },
  AvgDialog_131216_Content_18 = {
    Text = "Tôi dám đặt cược, toàn bộ Lentiennam không tìm ra được chai rượu nào ngon hơn thế, nó thật sự chính xác, thanh lịch, giống như một lời tiên tri"
  },
  AvgDialog_131216_Content_19 = {
    Text = "Tôi nghĩ, nếu có thể mời vị này đến tham dự bữa tiệc vào tháng sau thì sẽ tốt biết bao."
  },
  AvgDialog_131216_Content_2 = {
    Text = "\"90 phút giữa đêm, mặt nạ 15 inch, 10 gallon giấc mơ, 2 ounce rượu—— công thức duy nhất cho hạnh phúc\""
  },
  AvgDialog_131216_Content_21 = {Text = "Pa——"},
  AvgDialog_131216_Content_22 = {
    Text = "Tiếng búng tay trong trẻo như pháo hoa lướt qua bên tai các bạn. Các bạn quay lại, nhìn thấy một gương mặt với nụ cười rạng rỡ."
  },
  AvgDialog_131216_Content_23 = {
    Text = "Xin lỗi đã làm gián đoạn, quý khách. Nghe nhiều chủ đề thú vị như vậy, có muốn kết hợp với một ly rượu thú vị không?"
  },
  AvgDialog_131216_Content_24 = {
    Text = "Xem danh sách rượu đi, anh William."
  },
  AvgDialog_131216_Content_25 = {
    Text = "William hiểu rõ ánh mắt của bạn. Hai người mặc đồng phục không rõ nguồn gốc xuất hiện ở đây, từ đầu đến cuối không uống một giọt rượu nào, thật khó để không gây chú ý."
  },
  AvgDialog_131216_Content_26 = {
    Text = "Thấy ánh mắt của anh ta tìm kiếm danh sách đồ uống, người pha chế cười nhẹ và lắc đầu."
  },
  AvgDialog_131216_Content_27 = {
    Text = "Danh sách rượu? À, tẻ nhạt, nhàm chán, sáo rỗng."
  },
  AvgDialog_131216_Content_28 = {
    Text = "Một quán rượu lãng mạn, không nên có những thứ nhàm chán như vậy."
  },
  AvgDialog_131216_Content_29 = {
    Text = "Không có thực đơn đồ uống? Vậy chúng ta sẽ đặt món như thế nào đây?"
  },
  AvgDialog_131216_Content_3 = {
    Text = "Tôi đã thuộc lòng câu quảng cáo của quán bar \"Mặt Nạ Nửa Đêm\". Ở Cađas, đây chính là nơi tôi muốn đến nhất."
  },
  AvgDialog_131216_Content_30 = {
    Text = "Mỗi chỗ ngồi của mặt nạ giữa đêm khuya, đều thuộc về một người khách trong nhà hát. Các bạn ở đây để xem, biểu diễn, thưởng thức…"
  },
  AvgDialog_131216_Content_31 = {
    Text = "Trong vô số câu chuyện, tôi sẽ chọn lựa đoạn phù hợp nhất với bạn."
  },
  AvgDialog_131216_Content_32 = {
    Text = "Mời quý khách ngồi, hai vị. Người đọc câu chuyện đã sẵn sàng."
  },
  AvgDialog_131216_Content_33 = {
    Text = "Bạn và William nhìn nhau, do dự ngồi ở vị trí gần quầy bar."
  },
  AvgDialog_131216_Content_34 = {
    Text = "Trước tiên là ngài, vị quý ông tóc vàng với vẻ mặt lạnh lùng."
  },
  AvgDialog_131216_Content_35 = {
    Text = "Người pha chế rượu đến trước mặt các bạn. Đối diện với ánh mắt chăm chú đó, William khẽ ho một tiếng, có chút không thoải mái quay đi ánh mắt."
  },
  AvgDialog_131216_Content_36 = {
    Text = "À… Huấn luyện khắc nghiệt ngày qua ngày đã mang lại những thành tựu tuyệt vời như thế nào. Kiên trì, bình tĩnh, kiên cường, dũng cảm, trí tuệ… Một người huyền thoại sống, được bao quanh bởi hoa và vinh quang."
  },
  AvgDialog_131216_Content_37 = {
    Text = "Và đằng sau những lời ca tụng và vinh quang ấy là... hối hận. Sự hối hận sâu thẳm hơn, đau đớn hơn cả màn sương của thành phố này."
  },
  AvgDialog_131216_Content_38 = {
    Text = "Bao nhiêu đêm khuya không ai thấy được ánh nước mắt. Những lời thề tự nói với chính mình."
  },
  AvgDialog_131216_Content_39 = {
    Text = "Từng ánh sáng đã chiếu sáng cho bạn trong hành lang bóng tối, đã tắt lịm trong bóng tối vô tận, mang theo thế giới của bạn, vỡ tan, vỡ tan……"
  },
  AvgDialog_131216_Content_4 = {
    Text = "Quy định quản lý của Misaque có đôi khi quá nghiêm khắc không?"
  },
  AvgDialog_131216_Content_40 = {
    Text = "Bạn nghĩ, nếu mình có thể nỗ lực hơn một chút, nếu mình có thể mạnh mẽ hơn một chút, có lẽ, đã có thể mang đến một kết cục khác cho những người bên cạnh..."
  },
  AvgDialog_131216_Content_41 = {
    Text = "Vẻ mặt William dường như không có gì thay đổi, nhưng bạn nhìn thấy những đường gân xanh hiện rõ trên bàn tay anh đang nắm chặt chiếc cốc."
  },
  AvgDialog_131216_Content_42 = {
    Text = "Tôi nghe thấy âm thanh của một thế giới đang vỡ vụn. Cậu bé chịu đựng nỗi đau, nhặt từng mảnh vụn, ghép lại..."
  },
  AvgDialog_131216_Content_43 = {
    Text = "Trong suốt quá trình ghép nối dài dằng dặc và tàn nhẫn này, cậu bé cuối cùng cũng đã trưởng thành thành một người đàn ông."
  },
  AvgDialog_131216_Content_44 = {
    Text = "Người pha chế rượu vừa nhẹ nhàng kể chuyện bằng giọng nói trầm bổng, vừa lấy xuống một số chai rượu hình dạng khác nhau từ kệ rượu dường như vô tận ở phía sau để bắt đầu pha chế."
  },
  AvgDialog_131216_Content_45 = {
    Text = "Rất nhanh, chất lỏng màu vàng nhạt được đổ vào cốc cổ điển và đặt trước mặt William."
  },
  AvgDialog_131216_Content_46 = {
    Text = "2 ounce Whiskey, 1 ounce rượu vang trắng, và màu nền đau đớn nhưng kiên cường đó—— 2 giọt tinh chất đắng."
  },
  AvgDialog_131216_Content_47 = {
    Text = "<Yellow:「Người Dẫn Đường」>. Hy vọng ngài có thể dẫn dắt những người ngưỡng mộ ngài cùng nhau, tìm ra con đường đúng đắn — giống như người mà ngài ngưỡng mộ, đã từng dẫn dắt ngài vậy."
  },
  AvgDialog_131216_Content_48 = {
    Text = "William đón lấy ly chất lỏng ánh vàng, chậm rãi lắc trong tay, ánh mắt dò xét người pha chế trước mặt."
  },
  AvgDialog_131216_Content_49 = {
    Text = "Những điều vừa nói đó… bạn biết làm sao?"
  },
  AvgDialog_131216_Content_5 = {
    Text = "Tôi đề nghị cấm học sinh Misaque vào những địa điểm như vậy mà không có sự cho phép, nhằm ngăn chặn một số Người Giữ Gìn không làm việc đúng mực, lợi dụng danh nghĩa nhiệm vụ điều tra để lãng phí ngân sách nhiệm vụ."
  },
  AvgDialog_131216_Content_50 = {
    Text = "Một bartender xuất sắc cần phải biết lắng nghe những tâm tư của khách hàng. Đây là bí mật của người pha chế, thưa khách quý."
  },
  AvgDialog_131216_Content_51 = {
    Text = "Cô pha chế nhẹ nhàng như chú nai nhảy qua ánh mắt sắc bén của William. Ngón tay cô khẽ lắc trước môi, rồi chỉ về phía bạn."
  },
  AvgDialog_131216_Content_52 = {
    Text = "Đến lượt bạn, vị khách này…"
  },
  AvgDialog_131216_Content_53 = {
    Text = "Tôi có một cảm giác rằng đây có thể là điều nguy hiểm nhất mà tôi từng thử trong đời—— nhưng không sao, tôi yêu thích phiêu lưu."
  },
  AvgDialog_131216_Content_54 = {
    Text = "Cô đến trước mặt bạn, chăm chú nhìn vào mắt bạn. Bạn gần như có thể nghe thấy hơi thở nhẹ nhàng của cô."
  },
  AvgDialog_131216_Content_55 = {
    Text = "Ừm…… cái mà tôi đang nhìn chằm chằm, là vị khách từ xa đến đây, hay là…… một vị thần đã rơi xuống trần gian, gặp phải nhiều khó khăn?"
  },
  AvgDialog_131216_Content_56 = {Text = "?!!"},
  AvgDialog_131216_Content_57 = {
    Text = "Bạn vô thức đứng dậy lùi hai bước."
  },
  AvgDialog_131216_Content_58 = {
    Text = "Điều này không thể là chuyện mà một bartender bình thường biết được…… bạn rốt cuộc là ai?"
  },
  AvgDialog_131216_Content_59 = {
    Text = "À, xin yên tâm, vị khách thân mến, trong quán rượu này, tôi không phải người mang ác ý."
  },
  AvgDialog_131216_Content_6 = {
    Text = "Dù sao đi nữa, trong sự nghiệp học tập của vị này, Người Giữ Gìn, có không ít tiền án."
  },
  AvgDialog_131216_Content_60 = {
    Text = "Có thể bạn đã nhận ra, phía sau bạn, có vài người bạn cũ đã đến."
  },
  AvgDialog_131216_Content_61 = {
    Text = "%player%, phía sau."
  },
  AvgDialog_131216_Content_62 = {
    Text = "Tôi cảm thấy……"
  },
  AvgDialog_131216_Content_63 = {
    Text = "Dưới sự nhắc nhở của người pha chế, bạn nhận thấy mười mấy làn sóng tinh thần mạnh mẽ từ bốn phương tám hướng đang nhanh chóng tiến lại gần các bạn."
  },
  AvgDialog_131216_Content_64 = {
    Text = "William đứng sau lưng bạn một cách ăn ý, giám sát hướng còn lại. Bạn nắm chặt chiếc chìa khóa bạc, chăm chú nhìn vào người pha chế rượu mờ ảo như sương mù trước mặt."
  },
  AvgDialog_131216_Content_65 = {
    Text = "Người pha chế rượu đặt chiếc ly trong tay xuống, đặt chai rượu trên bàn vào một góc khó bị vỡ."
  },
  AvgDialog_131216_Content_66 = {
    Text = "Xin đừng căng thẳng, %player%. Tung tích của các bạn họ đã nắm rõ từ lâu. Ở nơi này, ít nhất tôi vẫn có thể giúp các bạn."
  },
  AvgDialog_131216_Content_67 = {
    Text = "Bạn? Họ? …"
  },
  AvgDialog_131216_Content_68 = {
    Text = "Hừ... tìm thấy các ngươi rồi."
  },
  AvgDialog_131216_Content_69 = {
    Text = "Nơi bẩn thỉu thế này không thích hợp để các ngươi ở lâu đâu, những vị khách nhỏ đến từ phương xa."
  },
  AvgDialog_131216_Content_7 = {
    Text = "Tôi nhớ trong hồ sơ của anh trai Fingol có đề cập rằng, sở thích lớn nhất của anh ấy là sau giờ làm việc đến quán bar Midnight uống một ly…"
  },
  AvgDialog_131216_Content_70 = {
    Text = "Cẩn thận, họ đã đến gần rồi"
  },
  AvgDialog_131216_Content_8 = {
    Text = "……tất nhiên, thỉnh thoảng nghỉ ngơi cũng không hoàn toàn là điều xấu."
  },
  AvgDialog_131216_Content_9 = {
    Text = "Hơn nữa, danh sách thành viên của mặt nạ giữa đêm chứa đựng những nhân vật nổi tiếng nhất ở Lentiennam, là nơi lý tưởng nhất để thu thập thông tin."
  },
  AvgDialog_131217_Content_1 = {
    Text = "Quyền lực của ba chất thể trong cơ thể bạn đã lắng xuống, nhưng bạn vẫn chưa mở mắt."
  },
  AvgDialog_131217_Content_10 = {
    Text = "Tinh thần khế ước, nguyên tắc thương mại gì đó… Giao dịch luôn cần có thứ để đặt cược, cậu hiểu bộ này mà phải không?"
  },
  AvgDialog_131217_Content_11 = {
    Text = "\"N\" lắc đầu, dường như phải rất vất vả mới kìm được tiếng cười của mình."
  },
  AvgDialog_131217_Content_12 = {
    Text = "Tin tốt là, cậu luôn có thứ đặt cược hoàn hảo."
  },
  AvgDialog_131217_Content_13 = {
    Text = "Vệ đạo sĩ dũng cảm sắp từ bỏ tín ngưỡng của mình, chìm đắm trong tấm lưới khổng lồ của số mệnh, lừa gạt, dối trá, không còn giới hạn… Một màn kịch đầy sức lây lan biết bao!"
  },
  AvgDialog_131217_Content_14 = {
    Text = "Vị trí khán giả tốt nhất, ta chẳng muốn bỏ lỡ đâu."
  },
  AvgDialog_131217_Content_15 = {
    Text = "Khi nào tôi đã nói……"
  },
  AvgDialog_131217_Content_16 = {
    Text = "Kẻ Du Hí không có kiên nhẫn giải đáp thắc mắc của bạn. Ngài cân nhắc thứ mà bạn sẽ phải trả trong tương lai, mỉm cười lắc lắc ngón tay."
  },
  AvgDialog_131217_Content_17 = {
    Text = "Gợi ý không được tính, chỉ có một gợi ý nhỏ và chân thành."
  },
  AvgDialog_131217_Content_18 = {
    Text = "Tại sao phải chống lại Nephreya? Tại sao không thuận theo nàng ta, Người Giữ Bí Mật {Male=先生,Female=小姐}?"
  },
  AvgDialog_131217_Content_19 = {
    Text = "\"N\" mỉm cười tiến lại gần bạn, hiền lành như một luật sư đang đến nhà tù thăm thân chủ."
  },
  AvgDialog_131217_Content_2 = {
    Text = "Ý thức của bạn lặn sâu trong đại dương tinh thần mênh mông, lặn sâu, lặn đến bóng tối vô biên, lặn đến vực thẳm thuộc về chính bạn mà bạn không thể nhìn thấy."
  },
  AvgDialog_131217_Content_20 = {
    Text = "Bạn…… bạn nói gì? Không, tôi tuyệt đối không thể……"
  },
  AvgDialog_131217_Content_21 = {
    Text = "À, đúng vậy, tuyệt đối không nhận thua, tuyệt đối không từ bỏ, tuyệt đối không công nhận những gì Nephreya đã làm... chủ nghĩa anh hùng cổ điển và trường tồn."
  },
  AvgDialog_131217_Content_22 = {
    Text = "Giao chúng ta cho Nephreya, triệu hồi người anh em họ thân yêu của cậu, trở về tòa cung điện thuộc về cậu… Ngoài những điều này ra, bây giờ cậu còn có thể làm gì nữa, %player%?"
  },
  AvgDialog_131217_Content_23 = {
    Text = "Tôi sẽ cho bạn một bí mật: Nếu đã không thể thoát khỏi cái lưới đó, tại sao không dang rộng đôi tay, chào đón sự đến của cái lưới ấy?"
  },
  AvgDialog_131217_Content_24 = {
    Text = "Đừng mơ nữa, \"N\", tôi không thể nào..."
  },
  AvgDialog_131217_Content_25 = {
    Text = "Suỵt. Đừng dễ dàng tự đặt giới hạn cho mình, thân yêu."
  },
  AvgDialog_131217_Content_26 = {
    Text = "Đừng quên, Arachne đã kết nối số phận của bạn vào mạng lưới khổng lồ. Bạn, đã trở thành một phần của họ rồi."
  },
  AvgDialog_131217_Content_27 = {
    Text = "Vị đó, nữ thần số phận, đã trao cho bạn một chiếc chìa khóa mang tên Hạnh phúc. Nhưng bạn có từng nghĩ rằng, cánh cửa đó rốt cuộc dẫn đến đâu, và thông đến nơi nào?"
  },
  AvgDialog_131217_Content_28 = {
    Text = "Cánh cửa hướng về đâu… Cánh cửa dẫn đến nơi nào?…"
  },
  AvgDialog_131217_Content_29 = {
    Text = "Ta vốn tưởng Arachne là một quý cô cần mẫn hiền lành nhưng nhạt nhẽo, thứ duy nhất biết làm chỉ là dệt lưới và mỉm cười. Nhưng nàng thú vị hơn ta tưởng, thú vị hơn rất nhiều."
  },
  AvgDialog_131217_Content_3 = {
    Text = "Bạn cố gắng mở rộng cái miệng không tồn tại, trong vực thẳm này, bạn giận dữ và im lặng kêu gọi."
  },
  AvgDialog_131217_Content_30 = {
    Text = "Cô ấy đã dệt một tấm lưới khổng lồ cho sân khấu này, và từ giây phút bạn đến với thế giới này, tấm lưới đó đã bắt đầu trải ra cho bạn."
  },
  AvgDialog_131217_Content_31 = {
    Text = "Có khả năng xuất sắc như vậy, lại đi làm những chuyện ngu ngốc như duy trì sự vận hành của thế giới... Thật tiếc, thật sự rất tiếc."
  },
  AvgDialog_131217_Content_32 = {
    Text = "Bước lên sân khấu của nhà hát số phận, bạn sẽ trở thành một nhân vật trên sân khấu. Mỗi nhân vật đều có cuộc đời riêng của mình."
  },
  AvgDialog_131217_Content_33 = {
    Text = "Số phận đã đưa bạn đến để đưa ra lựa chọn này, là để cho bạn thấy rõ nó. Bạn không thể nhìn thấy sợi chỉ, nhưng bây giờ bạn đã hiểu, những sợi chỉ này được đan xen theo cách phức tạp như thế nào."
  },
  AvgDialog_131217_Content_34 = {
    Text = "Sợi chỉ số phận dệt nên mạng lưới khổng lồ, mỗi một sợi chỉ rung nhẹ, có lẽ sẽ khiến mạng lưới số phận sụp đổ."
  },
  AvgDialog_131217_Content_35 = {
    Text = "Đây chính là số mệnh, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131217_Content_36 = {
    Text = "Biểu diễn, trêu chọc, làm vui lòng…… Trong cơ thể bạn có sức mạnh như vậy. Sân khấu của số phận sẽ không dành cơ hội cho mọi người. Khi bạn cần bước lên sân khấu, những sức mạnh này sẽ giúp bạn."
  },
  AvgDialog_131217_Content_37 = {
    Text = "Ngươi không thể trốn tránh những sân khấu định sẽ đến. Hãy suy nghĩ, rồi biểu diễn đi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131217_Content_38 = {
    Text = "\"Hạnh phúc\"."
  },
  AvgDialog_131217_Content_39 = {
    Text = "Trong tương lai ngắn ngủi của bạn, \"Hạnh phúc\" là một chiếc chìa khóa, nó sẽ mở ra những bí mật mà bạn đang đối mặt."
  },
  AvgDialog_131217_Content_4 = {Text = "\"N\"!"},
  AvgDialog_131217_Content_40 = {
    Text = "……Dù chuyện gì xảy ra, hãy tin tưởng tôi, và cũng hãy tin tưởng vào bản thân bạn."
  },
  AvgDialog_131217_Content_41 = {
    Text = "Hãy trở về Nhà Hát Số Phận đi. Chìa khóa và ổ khóa đều đang chờ đợi ngươi ở đó, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131217_Content_42 = {
    Text = "Lời nói của Arachne như những sợi chỉ lướt qua, đan xen trong tâm trí bạn. Cuối cùng, chúng hội tụ thành một tấm mạng lưới khổng lồ và chặt chẽ."
  },
  AvgDialog_131217_Content_43 = {
    Text = "Cuối cùng bạn cũng hiểu, từ lần đầu gặp mặt, Arachne đã trò chuyện với bạn qua thời gian, với bạn hiện tại."
  },
  AvgDialog_131217_Content_44 = {
    Text = "Bạn ngạc nhiên nhìn vào cái lưới tinh xảo đó, dường như có điều gì rất quan trọng, đang dần hình thành trong tâm trí bạn."
  },
  AvgDialog_131217_Content_45 = {
    Text = "Biểu diễn, đùa giỡn, làm vui lòng……"
  },
  AvgDialog_131217_Content_46 = {
    Text = "À, đúng vậy. Đừng bao giờ cố gắng hiểu. Hãy tận hưởng chúng, đó chính là bí mật duy nhất của hạnh phúc."
  },
  AvgDialog_131217_Content_47 = {
    Text = "Buồn vui, thiện ác, tất cả cảm xúc và đạo đức đều không còn tồn tại. Ngoài sự hưởng thụ, không còn gì cả."
  },
  AvgDialog_131217_Content_48 = {
    Text = "Bây giờ, hãy cho tôi biết... bạn có hiểu \"Hạnh phúc\" không, Người Giữ Gìn?"
  },
  AvgDialog_131217_Content_49 = {
    Text = "Gương mặt cười đỏ thắm của \"N\" biến mất trong tâm trí bạn. Bạn nhìn thấy một tấm gương, trên đó phản chiếu gương mặt đang cười của chính mình."
  },
  AvgDialog_131217_Content_5 = {
    Text = "Suỵt... Giọng của bạn quá to, Người Giữ Gìn."
  },
  AvgDialog_131217_Content_50 = {
    Text = "Hạnh phúc?…Hạnh phúc…"
  },
  AvgDialog_131217_Content_51 = {
    Text = "He he he he... ha ha ha. Đúng vậy, hạnh phúc, bạn của tôi"
  },
  AvgDialog_131217_Content_52 = {
    Text = "Từ ngữ tuyệt diệu nhất trên thế gian này, toàn bộ ý nghĩa của giấc mơ này……"
  },
  AvgDialog_131217_Content_53 = {
    Text = "Dường như đã nhìn thấy cảnh tượng sắp diễn ra, toàn bộ cơ thể của N run rẩy trong khoái lạc. Hắn giơ tay phải lên, ngón trỏ bao phủ sương mù đen nhẹ nhàng chạm vào trán mình."
  },
  AvgDialog_131217_Content_54 = {
    Text = "Bạn sắp đến nơi rồi. Chỉ còn một bước nữa, bước cuối cùng… Hãy suy nghĩ kỹ, rồi bước vào cái bẫy đó, Người Giữ Gìn."
  },
  AvgDialog_131217_Content_55 = {
    Text = "Con đường hạnh phúc, chính là ở đó."
  },
  AvgDialog_131217_Content_6 = {
    Text = "Ảo ảnh của \"N\" không biến mất. Hắn đường hoàng xuất hiện trong không gian tinh thần của bạn, như thể là chủ nhân không thể tranh cãi của nơi này."
  },
  AvgDialog_131217_Content_7 = {
    Text = "「Arachne」 nói về 「Hạnh phúc」, chắc chắn là đang chỉ về bạn"
  },
  AvgDialog_131217_Content_8 = {
    Text = "\"N\", cho tôi vài gợi ý đi..."
  },
  AvgDialog_131217_Content_9 = {
    Text = "Gợi ý? Ha ha ha ha... Tôi đã làm gì, mà khiến bạn xúc phạm tôi như vậy?"
  },
  AvgDialog_131218_Content_10 = {
    Text = "Bạn… các bạn đang nói gì…"
  },
  AvgDialog_131218_Content_11 = {
    Text = "Người trung niên say rượu, cô gái tuổi xuân, quý ông sang trọng, thành viên băng nhóm trên phố, người phục vụ mặt mày mệt mỏi, bartender xinh đẹp…"
  },
  AvgDialog_131218_Content_12 = {
    Text = "Mỗi gương mặt trong quán rượu, dù trẻ hay già, tuấn tú hay bình thường, đều đồng loạt quay về phía bạn với vẻ mặt giống nhau như bản sao."
  },
  AvgDialog_131218_Content_13 = {
    Text = "Họ... không giống những cá thể riêng lẻ, mà giống như..."
  },
  AvgDialog_131218_Content_14 = {
    Text = "Những con người còn sống động ở khoảnh khắc trước, giờ đây đứng trước các bạn như những con rối vô hồn."
  },
  AvgDialog_131218_Content_15 = {
    Text = "...Giống như, những con rối bị trói buộc trong mạng lưới."
  },
  AvgDialog_131218_Content_16 = {
    Text = "Tôi đã nghe danh tiếng về khả năng quan sát nhạy bén của ông, thưa ông William."
  },
  AvgDialog_131218_Content_17 = {
    Text = "Những gì trước mắt ngài, là phông nền trên sân khấu, là bóng phản chiếu trong gương."
  },
  AvgDialog_131218_Content_18 = {
    Text = "Xin thứ lỗi, tạm thời tôi không tiện rời khỏi mạng lưới của mình, đành phải dùng chúng để đối thoại với hai vị."
  },
  AvgDialog_131218_Content_19 = {
    Text = "Chào mừng đến sân khấu của tôi, ngài William, Người Giữ Bí Mật {Male=ngài,Female=cô}."
  },
  AvgDialog_131218_Content_2 = {
    Text = "Đã giải quyết, những thứ này rốt cuộc là……"
  },
  AvgDialog_131218_Content_20 = {
    Text = "Mỗi từ ngữ được truyền đi khớp từng li từng tí, hai mươi giọng nói khác nhau, đan dệt thành cùng một thanh âm lạnh lẽo."
  },
  AvgDialog_131218_Content_21 = {
    Text = "Tất cả mọi người trong quán bar, với nụ cười và giọng điệu giống hệt nhau, cúi chào các bạn. Độ cong khi cúi người và góc đặt hai tay của họ không có bất kỳ sự khác biệt nào."
  },
  AvgDialog_131218_Content_22 = {
    Text = "Sân khấu của bạn……? Bạn rốt cuộc là ai?"
  },
  AvgDialog_131218_Content_23 = {
    Text = "Là chủ nhân ở đây, cũng là một tù nhân."
  },
  AvgDialog_131218_Content_24 = {
    Text = "Tôi nghĩ, chắc hẳn bạn có rất nhiều câu hỏi."
  },
  AvgDialog_131218_Content_25 = {
    Text = "Ở đây không an toàn, người của họ sẽ nhanh chóng đuổi đến. Người hầu của tôi sẽ đến đón hai vị, sau khi thấy cô ấy, xin đừng hoảng sợ."
  },
  AvgDialog_131218_Content_26 = {
    Text = "Sau khi gặp mặt, tất cả những thắc mắc, tôi sẽ lần lượt giải đáp cho hai vị."
  },
  AvgDialog_131218_Content_27 = {
    Text = "Sau khi nói xong câu đó, ý thức của đám đông dường như bị rút đi trong khoảnh khắc."
  },
  AvgDialog_131218_Content_28 = {
    Text = "Ly rượu pha lê của quý ông dừng lại bên môi, quý bà mở chiếc quạt gấp che nửa dưới khuôn mặt, bartender uyển chuyển nâng ly rượu lên."
  },
  AvgDialog_131218_Content_29 = {
    Text = "Như sợi dây kéo bỗng đứt lìa, tất cả mọi người đều giữ nguyên tư thế cuối cùng, đông cứng như tượng sáp trong không gian này."
  },
  AvgDialog_131218_Content_3 = {
    Text = "Cẩn thận sau lưng！！……"
  },
  AvgDialog_131218_Content_30 = {
    Text = "Bạn hít sâu một hơi, do dự nhìn quanh những \"con rối\" đông cứng với nụ cười giống hệt nhau."
  },
  AvgDialog_131218_Content_31 = {
    Text = "Dù vừa rồi họ thật sự đã giúp tôi, nhưng tôi thực sự không thể hoàn toàn tin tưởng…"
  },
  AvgDialog_131218_Content_32 = {
    Text = "William, anh trai, điều chúng tôi muốn biết, vị này \"chủ\" có lẽ là người giải đáp tốt nhất."
  },
  AvgDialog_131218_Content_33 = {
    Text = "Dù có nguy hiểm, tôi nghĩ tôi cũng phải đi một lần, chỉ là…"
  },
  AvgDialog_131218_Content_34 = {
    Text = "Tôi hiểu."
  },
  AvgDialog_131218_Content_35 = {
    Text = "Nhìn thấy ánh mắt của bạn, William gật đầu hiểu ý."
  },
  AvgDialog_131218_Content_36 = {
    Text = "Tôi sẽ điều tra hành tung của những bóng tối bên ngoài, chúng đang tìm kiếm bạn, hành tung của tôi bên ngoài sẽ an toàn hơn bạn."
  },
  AvgDialog_131218_Content_37 = {
    Text = "Vị này \"chủ nhân\" có nguồn gốc không rõ, nếu gặp phải nguy hiểm..."
  },
  AvgDialog_131218_Content_38 = {
    Text = "William nhẹ nhàng chạm vào huy hiệu trên ngực. Trong thế giới này, các bạn là người duy nhất có thể liên lạc với nhau qua huy hiệu."
  },
  AvgDialog_131218_Content_39 = {
    Text = "Hiểu rồi… bạn cũng vậy, anh William."
  },
  AvgDialog_131218_Content_4 = {
    Text = "Cảm giác nguy cơ mãnh liệt khiến bạn ngay lập tức tỉnh táo. Bạn đột ngột quay người, nhìn thấy lưỡi dao sắc hình bóng đang hiện ra cách bạn vài inch."
  },
  AvgDialog_131218_Content_40 = {
    Text = "\"Chủ nhân\" hiểu sự cẩn trọng của ngài. Thưa ông William, sân khấu này hiện tại có rất nhiều nguy hiểm, xin hãy hành động cẩn thận. Trong phạm vi khả năng, chúng tôi sẽ cung cấp sự trợ giúp cần thiết cho ngài."
  },
  AvgDialog_131218_Content_41 = {
    Text = "Những con nhện tím nhạt từ khắp nơi trong quán bar tụ lại, một nữ hầu mang đặc điểm của nhện lặng lẽ xuất hiện phía sau các bạn. Sau khi lịch sự cúi chào, cô ấy bước ra ngoài cửa."
  },
  AvgDialog_131218_Content_42 = {
    Text = "Người Giữ Bí Mật {Male=先生,Female=小姐}, xin hãy đi theo tôi. \"Chủ nhân\" đã chờ đợi ngài từ lâu rồi."
  },
  AvgDialog_131218_Content_5 = {Text = "Chì——"},
  AvgDialog_131218_Content_6 = {
    Text = "Bạn từ từ dời cánh tay che mắt. Bóng tối bị người đứng sau chém đứt, chất lỏng đen phun ra, bắn đầy lên người bạn."
  },
  AvgDialog_131218_Content_7 = {
    Text = "Xin lỗi, khiến các bạn cảm thấy sợ hãi."
  },
  AvgDialog_131218_Content_8 = {
    Text = "HọLuôn luôn tìm kiếm dấu vết của bạn. Ở đây, sức mạnh của tôi vẫn có thể cung cấp cho bạn một số trợ giúp."
  },
  AvgDialog_131218_Content_9 = {
    Text = "Không xin phép bạn, tự ý dẫn các bạn đến đây, hy vọng hai người không phiền."
  },
  AvgDialog_131219_Content_1 = {
    Text = "Sức mạnh tản mát từ những mảnh vỡ chiều không gian… Đây là…!"
  },
  AvgDialog_131219_Content_2 = {
    Text = "Quyền năng của Tam Chất Thể chưa bao giờ phản bội, màn trình diễn của ngài và N vẫn chưa kết thúc."
  },
  AvgDialog_131219_Content_3 = {
    Text = "Hãy mượn sức mạnh của họ, mang đến cho họ cái kết đã được định sẵn… Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131220_Content_1 = {
    Text = "Thiên nga bay"
  },
  AvgDialog_131220_Content_10 = {
    Text = "Bạn nhớ cánh cửa có chút gỉ sét đó, mỗi lần di chuyển đều phát ra âm thanh trầm trầm, giống như hơi thở hiền hậu của ông nội."
  },
  AvgDialog_131220_Content_11 = {
    Text = "Đại học Miska……"
  },
  AvgDialog_131220_Content_12 = {
    Text = "Trong môi trường quen thuộc này, bạn vuốt ve cái tên hoàn toàn khác biệt trên biển tên của quảng trường."
  },
  AvgDialog_131220_Content_13 = {
    Text = "Mỗi một diễn viên đều có sân khấu mà họ yêu thích nhất. Ngay cả một khuôn viên được tái hiện từ ký ức, đối với bạn cũng không thể thay thế."
  },
  AvgDialog_131220_Content_14 = {
    Text = "Tại sao lại phải tạo ra một nơi giống hệt như Misaque như vậy……"
  },
  AvgDialog_131220_Content_15 = {
    Text = "Tôi không tạo ra nó, chỉ là nó nên tồn tại ở đây. Cùng với thành phố này, thế giới này, chúng đều là một phần của mạng lưới số phận."
  },
  AvgDialog_131220_Content_16 = {
    Text = "Không cần nhìn xa đến vậy, %player%. Khi đã bước lên một sân khấu, tự khắc sẽ có ý nghĩa khi đến đây."
  },
  AvgDialog_131220_Content_17 = {
    Text = "Nói về điều đó, đã ở bên Liz lâu như vậy, tôi vẫn chưa bao giờ xem buổi biểu diễn chính thức của cô ấy tại chỗ..."
  },
  AvgDialog_131220_Content_18 = {
    Text = "Bạn nhìn quanh quảng trường quen thuộc này, đôi tay nhẹ nhàng lướt qua thảm cỏ dưới thân."
  },
  AvgDialog_131220_Content_19 = {
    Text = "Thời khắc tuyệt vời nhất trong cuộc sống là khi bạn không nhận ra mình đang mỉm cười."
  },
  AvgDialog_131220_Content_2 = {
    Text = "Thật hiếm có, giá vé của đoàn múa này ở nhà hát, vé rẻ nhất cũng phải tiêu tốn hai tháng lương của tôi."
  },
  AvgDialog_131220_Content_20 = {
    Text = "À……xin lỗi……"
  },
  AvgDialog_131220_Content_21 = {
    Text = "Bạn nhớ chuyện về Misaque à?"
  },
  AvgDialog_131220_Content_22 = {
    Text = "Tại quảng trường này, chúng tôi đã tổ chức nhiều buổi biểu diễn trong trường. Lúc đó cũng giống như bây giờ, sinh viên Đại học Misaque đã chật kín quảng trường."
  },
  AvgDialog_131220_Content_23 = {
    Text = "Có rất nhiều thể thức tỉnh có tài năng sâu sắc trong nghệ thuật. Nhiều người ban đầu không mấy muốn biểu diễn trong những dịp như vậy, tôi và các thầy cô trong viện đã nghĩ ra đủ loại phương pháp…"
  },
  AvgDialog_131220_Content_24 = {
    Text = "Đến sau đó, nhiều người trong số họ cũng chủ động bắt đầu muốn thể hiện cho các đồng đội ở đây."
  },
  AvgDialog_131220_Content_25 = {
    Text = "Múa của Liz, bài ca của tinkerer, giao hưởng của Hamlin, thơ của Ôrla, điêu khắc của sơn…"
  },
  AvgDialog_131220_Content_26 = {
    Text = "Không biết sau khi tôi rời đi, cuộc sống của Misaque có trở lại như trước đây hay không……"
  },
  AvgDialog_131220_Content_27 = {
    Text = "Màn nhảy đã động rồi! Màn nhảy đã động rồi! Cô Liz sắp xuất hiện rồi!"
  },
  AvgDialog_131220_Content_28 = {
    Text = "Bạn lắc đầu, xua đuổi những cảm xúc buồn bã ra khỏi tâm trí mình."
  },
  AvgDialog_131220_Content_29 = {
    Text = "Dù thế nào đi nữa, việc có thể thấy điệu múa của Liz một lần nữa trong thế giới xa xôi này là một điều đáng mừng."
  },
  AvgDialog_131220_Content_3 = {
    Text = "Nghe nói đây là buổi biểu diễn từ thiện được Bà Sorrel tài trợ cá nhân! Giá mà mỗi quý ông quý bà trong thành phố này đều có tấm lòng tốt như vậy thì thật tuyệt"
  },
  AvgDialog_131220_Content_30 = {
    Text = "Đợi khi sự việc này kết thúc hoàn toàn, nếu có thời gian, tôi muốn trò chuyện với họ một cách thoải mái."
  },
  AvgDialog_131220_Content_31 = {
    Text = "Các bà, các ông… Chào mừng đến với buổi biểu diễn của chúng tôi"
  },
  AvgDialog_131220_Content_32 = {
    Text = "Đoàn vũ công thiên nga, một cái tên thật thiêng liêng và cao quý! Con thiên nga trắng thanh lịch nhất của Lentiennam hôm nay sẽ lần đầu tiên xuất hiện trước công chúng ở Lentiennam"
  },
  AvgDialog_131220_Content_33 = {
    Text = "Cảm ơn mọi người đã chờ đợi. Các diễn viên của chúng tôi đã sẵn sàng. Màn trình diễn tuyệt vời, sắp sửa được trình làng cho các vị"
  },
  AvgDialog_131220_Content_34 = {
    Text = "Cùng với tiếng vỗ tay trong trẻo của người thông báo, ánh sáng xung quanh đều tắt hết, vài ánh đèn chiếu sáng rọi vào giữa màn hình."
  },
  AvgDialog_131220_Content_35 = {
    Text = "Tiếp theo, hãy thưởng thức điệu nhảy do cô Liz mang đến, thiên nga—— bay lượn!"
  },
  AvgDialog_131220_Content_36 = {
    Text = "Giữa tiếng vỗ tay và tiếng hoan hô sôi động của đám đông, tấm màn từ từ được kéo lên——"
  },
  AvgDialog_131220_Content_38 = {
    Text = "Bạn đã gặp Liz nhiều lần."
  },
  AvgDialog_131220_Content_39 = {
    Text = "Trên sân khấu của phòng lễ Misaque, cô ấy xoay tròn chỉ vì bạn."
  },
  AvgDialog_131220_Content_4 = {
    Text = "Mặc dù không hiểu, nhưng cơ hội như thế này không thể bỏ lỡ."
  },
  AvgDialog_131220_Content_40 = {
    Text = "Dưới bầu trời sao của Lentiennam, đầu ngón chân cô ấy nhón lên chạm vào ánh sáng phát sáng bay lượn trong đêm."
  },
  AvgDialog_131220_Content_41 = {
    Text = "Trong cơn gió nhẹ ở phố Charing, vạt váy của cô ấy bay cao, giống như ngọn lửa đang sôi sục."
  },
  AvgDialog_131220_Content_42 = {
    Text = "Và hôm nay, trên sân khấu xa lạ, cô ấy xuất hiện trước mặt bạn với một dáng vẻ mà bạn chưa từng thấy."
  },
  AvgDialog_131220_Content_43 = {
    Text = "Ngôi sao nhảy chính của đoàn vũ công thiên nga, ngọn lửa rực rỡ nhất của thành phố. Những mũi nhọn màu đen xuyên thủng khí quản, cánh tay, bụng ngực, và đôi chân nhón của cô, xuyên thủng cơ thể điều khiển vũ điệu của cô."
  },
  AvgDialog_131220_Content_44 = {
    Text = "Máu phun ra, vẽ lên tấm bảng phía sau cô một đôi cánh đỏ tươi, để lại trên khuôn mặt bình tĩnh mỉm cười của cô vài vết xước bi thảm."
  },
  AvgDialog_131220_Content_45 = {
    Text = "Đám đông yên tĩnh không một tiếng động, gió thổi qua quảng trường rộng lớn, chiếc váy múa đen xanh xen lẫn bay bổng trên không trung, như một đám lửa vĩnh cửu đang cháy."
  },
  AvgDialog_131220_Content_46 = {
    Text = "—— Khoảnh khắc này, bạn hoàn toàn hiểu rằng, nếu cái chết không thể ngăn cản, thì đây chính là cách chết mà Liz khao khát nhất."
  },
  AvgDialog_131220_Content_47 = {
    Text = "Cô ấy đã hoàn thành một buổi biểu diễn chia tay bằng máu và sinh lực của mình. Điệu múa của cô ấy được định hình trong khoảnh khắc đẹp nhất như một con thiên nga đen đang bay lượn."
  },
  AvgDialog_131220_Content_48 = {
    Text = "Vũ điệu của cô Liz thật cao quý, thật duyên dáng"
  },
  AvgDialog_131220_Content_49 = {
    Text = "Hãy yên lặng thưởng thức, các bạn khán giả thân yêu! Chứng kiến cảnh tượng này bằng mắt mình, là vinh dự duy nhất trong đời của các bạn."
  },
  AvgDialog_131220_Content_5 = {
    Text = "Ba mươi năm…… Tôi đã ba mươi năm không thể trở lại nhà hát để xem một buổi biểu diễn……"
  },
  AvgDialog_131220_Content_50 = {
    Text = "Bạn nhìn thấy khuôn mặt bị xé làm đôi của người báo màn. Gương mặt vô hồn của người đàn ông trung niên tan chảy như chất nhầy, lộ ra đôi mắt tràn ngập hưng phấn của Nephrea."
  },
  AvgDialog_131220_Content_51 = {
    Text = "Giữa những tiếng hét và sự hỗn loạn của đám đông, tiếng cười sắc bén của cô ấy như những mũi kim đâm vào màng nhĩ của bạn."
  },
  AvgDialog_131220_Content_52 = {
    Text = "<Big:Liz！！>"
  },
  AvgDialog_131220_Content_53 = {
    Text = "Bạn gạt đám đông hỗn loạn đang hoảng sợ, chạy đến trước sân khấu."
  },
  AvgDialog_131220_Content_54 = {
    Text = "À, vị khách thông minh này, bạn làm sao biết được buổi biểu diễn khiêu vũ này còn có màn thứ hai?"
  },
  AvgDialog_131220_Content_55 = {
    Text = "Xung quanh sân khấu, một số khán giả chưa kịp trốn đã nhanh chóng xúm lại gần bạn. Cơ thể họ nổ tung trong lúc chạy, phun ra những tên phục vụ nhện đen không ngừng bị chém giết."
  },
  AvgDialog_131220_Content_56 = {
    Text = "Trên sân khấu trước mặt bạn, cơ thể của Liz rời khỏi mũi nhọn. Một tác phẩm nghệ thuật do những kẻ dị giáo sản xuất, mang theo sự tàn nhẫn trống rỗng và máu tươi rực rỡ."
  },
  AvgDialog_131220_Content_57 = {
    Text = "Những dấu chân trần đỏ thắm kéo dài từ trung tâm sân khấu. Liz chậm rãi bước về phía ngươi, lớp trang điểm thê thảm diễm lệ vẽ bằng máu tươi khiến ngươi cảm thấy nghẹt thở."
  },
  AvgDialog_131220_Content_58 = {
    Text = "Cô ấy ngẩng đầu nhìn bạn. Đôi mắt trống rỗng, rỉ máu khiến bạn nhớ đến tất cả những tác phẩm nghệ thuật đáng được lưu truyền."
  },
  AvgDialog_131220_Content_59 = {
    Text = "Hãy cùng khiêu vũ với cố nhân của ngươi đi……Người Giữ Bí Mật {Male=先生,Female=小姐}！"
  },
  AvgDialog_131220_Content_6 = {
    Text = "Ballet, điệu múa thuần khiết nhất trên thế giới, chỉ có những người thực sự đã nhảy mới hiểu được sự thanh lịch tàn khốc đó đẹp đến nhường nào"
  },
  AvgDialog_131220_Content_7 = {
    Text = "Còn có thể thấy buổi biểu diễn của cô Liz tại chỗ, điều này là điều tôi chưa bao giờ nghĩ đến trong giấc mơ của mình…"
  },
  AvgDialog_131220_Content_8 = {
    Text = "Những âm thanh môi trường vốn dĩ ồn ào đã hòa thành một tiếng trắng xa xăm trong tai bạn."
  },
  AvgDialog_131220_Content_9 = {
    Text = "Bạn nhớ bãi cỏ này, hồ nước đó. Bạn nhớ những tòa nhà học tập cao thấp, nhớ bức điêu khắc với ánh mắt kiên định nhìn về phía xa."
  },
  AvgDialog_131221_Content_1 = {
    Text = "Màn thứ hai"
  },
  AvgDialog_131221_Content_10 = {
    Text = "Tôi là tù nhân của số phận, đây chỉ là nghĩa vụ mà tôi buộc phải thực hiện mà thôi."
  },
  AvgDialog_131221_Content_11 = {
    Text = "Một người có thể điều khiển số phận của vô số thế giới, có lẽ gọi mình là thẩm phán của số phận hoặc cai ngục sẽ hợp lý hơn?"
  },
  AvgDialog_131221_Content_12 = {
    Text = "Trong nhà tù của số phận, cai ngục và tù nhân không khác gì nhau."
  },
  AvgDialog_131221_Content_13 = {
    Text = "Thưa ông William, trên đường đi này ông có thấy quen không?"
  },
  AvgDialog_131221_Content_14 = {
    Text = "Nhờ có nữ tì của ngài, nếu chỉ dựa vào bản thân tôi, muốn thoát khỏi những người phục vụ trong bóng tối đó, e rằng tôi còn phải trả giá nhiều hơn nữa."
  },
  AvgDialog_131221_Content_15 = {
    Text = "Nefreya... Bạn lại gặp người của cô ấy rồi à?"
  },
  AvgDialog_131221_Content_16 = {
    Text = "William gật đầu một cách trầm ngâm."
  },
  AvgDialog_131221_Content_17 = {
    Text = "Khi hành động riêng, tôi đã gặp một vài người qua đường trông có vẻ không bình thường. Tôi bám theo một đoạn và nghe được cuộc trò chuyện của họ."
  },
  AvgDialog_131221_Content_18 = {
    Text = "Họ đang tìm kiếm một thứ được gọi là\"bí ngẫu\"."
  },
  AvgDialog_131221_Content_19 = {
    Text = "Tôi nghĩ… cái mà các bạn vừa nói, ô nhiễm số phận của sân khấu, có lẽ chỉ là một phương tiện tiền đề."
  },
  AvgDialog_131221_Content_2 = {
    Text = "Một vở kịch tuyệt vời……"
  },
  AvgDialog_131221_Content_20 = {
    Text = "Những \"bí ngẫu\"đó mới chính là mục đích thực sự của họ."
  },
  AvgDialog_131221_Content_21 = {
    Text = "Em gái ta đã giấu đi sợi tơ vận mệnh của cô ấy cùng các thị tùng, ta không thể dễ dàng nhìn thấy họ. Ngài đã cung cấp một thông tin rất có giá trị, ngài William."
  },
  AvgDialog_131221_Content_22 = {
    Text = "Hoạt động tiếp theo, tôi sẽ cùng các bạn……"
  },
  AvgDialog_131221_Content_23 = {
    Text = "Không được!"
  },
  AvgDialog_131221_Content_24 = {
    Text = "Không được! Anh bây giờ vẫn còn bị thương, tôi không muốn chuyện ở Lemvahi lặp lại nữa."
  },
  AvgDialog_131221_Content_25 = {
    Text = "Người Giữ Bí Mật nói đúng. Thị nữ của ta sẽ giúp ngươi chữa trị độc tố trong cơ thể, trước khi bình phục, hãy yên tâm tĩnh dưỡng trong nhà hát."
  },
  AvgDialog_131221_Content_26 = {
    Text = "Rất nhanh, chúng ta sẽđón chào ngày mà bạn cần giúp đỡ."
  },
  AvgDialog_131221_Content_27 = {
    Text = "Lời nói của Arachne như một lời phán quyết ôn hòa, dễ dàng xuyên thấu thể xác và linh hồn, nhẹ nhàng rơi vào vận mệnh của William."
  },
  AvgDialog_131221_Content_28 = {
    Text = "William nhìn một cái vào máu chảy ra từ bụng, nhẹ nhàng gật đầu."
  },
  AvgDialog_131221_Content_29 = {
    Text = "Bây giờ hành động cùng các bạn, quả thực chỉ trở thành gánh nặng. Xin hãy yên tâm, tôi sẽ để ngày đó đến sớm nhất có thể."
  },
  AvgDialog_131221_Content_3 = {
    Text = "<Shake:khụ khụ……>"
  },
  AvgDialog_131221_Content_30 = {
    Text = "Arachne mỉm cười giơ tay ra. Một con, hai con… vô số con nhện từ tay áo của cô ấy chui ra, theo những sợi chỉ rơi xuống đất."
  },
  AvgDialog_131221_Content_31 = {
    Text = "Nhện rơi xuống đất như những giọt nước, tụ lại. Hàng ngàn con nhện dày đặc chồng chất thành hình người, màu sắc và ánh sáng bám phủ lên trên."
  },
  AvgDialog_131221_Content_32 = {
    Text = "Rất nhanh, một Arachne mới, giống hệt, đứng trước mặt bạn."
  },
  AvgDialog_131221_Content_33 = {
    Text = "Xin hãy đi theo ta, Người Giữ Bí Mật {Male=先生,Female=小姐}. Ta nghĩ, chúng ta sẽ sớm gặp được cô em gái của ta thôi."
  },
  AvgDialog_131221_Content_35 = {
    Text = "Trong thành phố này có nhiều cửa hàng tôi yêu thích, nhưng giống như bạn, đây cũng là một trong những nơi tôi yêu quý."
  },
  AvgDialog_131221_Content_36 = {
    Text = "Quán rượu mặt nạ giữa đêm, bạn ngồi ở vị trí mà bạn đã ngồi lần trước, nhíu mày nhìn Arachne đang quan sát xung quanh."
  },
  AvgDialog_131221_Content_37 = {
    Text = "Vậy bây giờ bạn rốt cuộc là gì... con rối? Phân thân? Một đám nhện ghép lại, là máy móc bí ẩn giúp bạn trốn việc?"
  },
  AvgDialog_131221_Content_38 = {
    Text = "Về bản chất, tôi ở đây và tôi trong rạp hát, là số phận của hai trải nghiệm khác nhau trong cùng một khoảnh khắc."
  },
  AvgDialog_131221_Content_39 = {
    Text = "Phần lớn sức mạnh của tôi cần được giữ lại trong nhà hát, tiếp tục dệt nên tấm lưới số phận khổng lồ. Ngoài điều đó ra, chúng ta không có bất kỳ sự khác biệt nào. Đừng phá hủy tâm trạng của khoảnh khắc này vì những nghi ngờ, Người Giữ Gìn."
  },
  AvgDialog_131221_Content_4 = {
    Text = "Âm thanh tác động đến vết thương, William che bụng băng bó, không thể kiềm chế được cơn ho."
  },
  AvgDialog_131221_Content_40 = {
    Text = "Arachne mỉm cười bình tĩnh, viên đá lạnh nhẹ nhàng vang lên trong ly rượu đang lắc lư."
  },
  AvgDialog_131221_Content_41 = {
    Text = "Bạn có biết không, quán rượu này hàng tháng đều tổ chức một buổi khiêu vũ hóa trang, mỗi vị khách vào cửa đều phải đeo chiếc mặt nạ thú vị nhất của mình."
  },
  AvgDialog_131221_Content_42 = {
    Text = "Giao tiếp xã hội của tầng lớp thượng lưu thường khiến nơi này trở nên nhàm chán, chỉ có vào ngày đó, nơi đây mới trở thành điểm đến đáng giá nhất của thành phố này."
  },
  AvgDialog_131221_Content_43 = {
    Text = "Có lẽ lần giả trang tiếp theo, tôi cũng nên bỏ mọi thứ lại, để cảm nhận một cách chân thành."
  },
  AvgDialog_131221_Content_44 = {
    Text = "Tôi tưởng rằng một người có thể nhìn thấy sự phát triển của số phận sẽ không còn hứng thú với mọi thứ trong tương lai nữa."
  },
  AvgDialog_131221_Content_45 = {
    Text = "Quả đúng như vậy, %player%. Tuy nhiên, từ rất lâu trước đây, ta đã lĩnh ngộ được một cách để tránh sự nhàm chán."
  },
  AvgDialog_131221_Content_46 = {
    Text = "Đôi khi tôi sẽ từ sau màn lên sân khấu, bước vào sân khấu mà mình đã tạo ra, để bản thân cũng trở thành một trong những nhân vật đó."
  },
  AvgDialog_131221_Content_47 = {
    Text = "Che khuất cái nhìn của chính mình về số phận, hoàn toàn đặt bản thân lên sân khấu, để cảm nhận sự chảy trôi của thời gian, sự nghiêng ngả của số phận……"
  },
  AvgDialog_131221_Content_48 = {
    Text = "Đây là một sự nghỉ ngơi hiếm có. Cơ hội như vậy không nhiều, mỗi lần, tôi đều coi đó là một ngày lễ quý giá."
  },
  AvgDialog_131221_Content_49 = {
    Text = "Arachne vừa nói vừa chăm chú nhìn những vị khách hào nhoáng và những người hầu dịu dàng, ánh sáng mờ ảo của quán rượu luân chuyển trong mắt Arachne."
  },
  AvgDialog_131221_Content_5 = {
    Text = "William, Anh trai?! Bạn bị thương rồi"
  },
  AvgDialog_131221_Content_50 = {
    Text = "Dù sao đi nữa... chúng ta không phải đang đi tìm cái gì đó gọi là\"bí ngẫu\" sao? Tại sao lại đến đây?"
  },
  AvgDialog_131221_Content_51 = {
    Text = "Một người trong số đó đang ở đây. Bạn sẽ gặp lại cô ấy rất nhanh… à không, bạn đã gặp cô ấy rồi."
  },
  AvgDialog_131221_Content_52 = {
    Text = "Xin chào các bạn, khách hàng thân mến."
  },
  AvgDialog_131221_Content_53 = {
    Text = "Âm thanh của mật ong ngâm. Ngón tay được chạm khắc từ sứ. Trên cổ trần, hương thơm rực rỡ của hoa nhài và hoa hợp hoan. Còn đôi mắt như đèn neon lấp lánh, có thể nhìn thấu mọi thứ."
  },
  AvgDialog_131221_Content_54 = {
    Text = "À, ta nhớ ngươi, vị {Male=先生,Female=小姐} thanh nhã này."
  },
  AvgDialog_131221_Content_55 = {
    Text = "Quái vật trong bóng tối, ánh sáng bạc chói lọi…… Thật là một câu chuyện anh hùng tuyệt vời"
  },
  AvgDialog_131221_Content_56 = {
    Text = "Nói thật, trong khoảng thời gian bạn không có mặt, quán bar mặt nạ giữa đêm đã kiếm được không ít tiền từ câu chuyện của bạn, chúng tôi nên trả bạn phí bản quyền—— ít nhất, hãy để chúng tôi mời bạn một ly rượu."
  },
  AvgDialog_131221_Content_57 = {
    Text = "Hóa ra là bạn... Tôi sẽ không uống nữa, có thể làm ơn cho bạn tôi một ly trước được không?"
  },
  AvgDialog_131221_Content_58 = {
    Text = "Tôi đã nghĩ ra tên rồi, gọi là tự biên tự diễn."
  },
  AvgDialog_131221_Content_59 = {
    Text = "Tên khá tốt. Còn về việc có phù hợp với vị bạn này hay không, tôi cần xem xét kỹ hơn…"
  },
  AvgDialog_131221_Content_6 = {
    Text = "Dưới sự dẫn dắt của Arachne, bạn bước qua bức tường không mấy nổi bật bên cạnh quán cà phê Hervats."
  },
  AvgDialog_131221_Content_60 = {
    Text = "Vị này tên là\"Lãng Mạn\" của bí ẩn đến bên quầy bar, nghiêm túc nhìn chằm chằm vào mắt của Arachne."
  },
  AvgDialog_131221_Content_61 = {
    Text = "Người sáng tạo khiêm tốn đắm chìm trong sân khấu mà mình đã tạo ra. Arachne mỉm cười nhìn cô ấy."
  },
  AvgDialog_131221_Content_62 = {
    Text = "À, một đôi mắt thật sâu sắc, thiếu nữ."
  },
  AvgDialog_131221_Content_63 = {
    Text = "Một đại dương sâu lắng và rộng lớn như vậy, đáy biển không ai nhìn thấy, chôn giấu những bí mật mà không ai biết."
  },
  AvgDialog_131221_Content_64 = {
    Text = "Những con sóng cuộn trào đó, tất cả đều được đại dương này bao dung, bất kể sự chấn động lớn đến đâu, nó vẫn giữ được sự yên lặng vĩnh cửu."
  },
  AvgDialog_131221_Content_65 = {
    Text = "Thời gian trôi qua, biển sao xoay chuyển. Núi cao trở thành đồng ruộng, biển cả biến thành thảo nguyên……"
  },
  AvgDialog_131221_Content_66 = {
    Text = "Nhưng dưới sự biến đổi này, đại dương này đã từ bỏ điều gì…"
  },
  AvgDialog_131221_Content_67 = {
    Text = "Người pha chế ngồi đối diện Arachne, nâng cằm cô ấy lên. Những móng tay dài, một cách tự nhiên, đặt lên động mạch cổ của Arachne."
  },
  AvgDialog_131221_Content_68 = {
    Text = "Bạn đang nói…"
  },
  AvgDialog_131221_Content_69 = {
    Text = "Thần linh của số phận, Arachne vĩ đại. Cách bạn thao túng số phận thật thanh lịch. Tôi thật sự ghen tị, ghen tị với những người được bạn chọn, được bạn lưu lại."
  },
  AvgDialog_131221_Content_7 = {
    Text = "Khi trở lại sân khấu của nhà hát, bạn đã thấy ngay William đang ngồi một mình ở hàng ghế khán giả."
  },
  AvgDialog_131221_Content_70 = {
    Text = "Đáng tiếc… chúng ta sinh ra, chỉ có thể là phần bị bỏ rơi."
  },
  AvgDialog_131221_Content_71 = {
    Text = "……Có vẻ, hôm nay không còn cơ hội được thưởng thức ly rượu này nữa rồi."
  },
  AvgDialog_131221_Content_72 = {
    Text = "Arachne không cố gắng thoát khỏi bàn tay nguy hiểm đó. Cô thở dài nhẹ nhàng, dường như đang thở dài về những ký ức xa xôi, lại như đang thở dài về ly đồ uống đặc biệt không thể uống được."
  },
  AvgDialog_131221_Content_73 = {
    Text = "Bạn có thể ô nhiễm những sợi dây số phận của những bí ẩn này, khiến tôi không thể nhìn rõ, nhưng điều đó không có ý nghĩa gì. Bạn không có khả năng điều khiển số phận, Nefreya."
  },
  AvgDialog_131221_Content_74 = {
    Text = "Như kem đen tan chảy, lớp da bề ngoài của người pha rượu biến thành một vũng bùn nhão trượt khỏi cơ thể."
  },
  AvgDialog_131221_Content_75 = {
    Text = "Dưới lớp bùn lầy đó, một khuôn mặt quen thuộc xuất hiện trước mặt bạn."
  },
  AvgDialog_131221_Content_76 = {Text = "Là bạn?"},
  AvgDialog_131221_Content_77 = {
    Text = "Chị gái tốt của tôi. Những tàn tro của chiều, chị đã còn lại rất ít rồi."
  },
  AvgDialog_131221_Content_78 = {
    Text = "Tôi rất muốn trò chuyện với bạn một cách thoải mái lần nữa, nhưng bây giờ, hãy để những con nhện nhỏ của tôi chào đón bạn thật tốt nhé."
  },
  AvgDialog_131221_Content_79 = {
    Text = "Cẩn thận sau lưng"
  },
  AvgDialog_131221_Content_8 = {
    Text = "Vết thương nhỏ."
  },
  AvgDialog_131221_Content_9 = {
    Text = "Số phận xảy ra trên sân khấu này, tôi đã thấy tất cả. Tôi nghĩ, chắc hẳn có người cảm ơn sự cống hiến của bà, thưa bà Arachne."
  },
  AvgDialog_131222_Content_1 = {
    Text = "Lời mời đến biệt thự"
  },
  AvgDialog_131222_Content_10 = {
    Text = "Thư mời? Trong suốt cuộc đời tôi đến giờ, tôi chưa bao giờ phải xuất trình thư mời."
  },
  AvgDialog_131222_Content_100 = {
    Text = "Sorrel nhẹ nhàng nheo mắt lại, trong đôi mắt thanh lịch bùng cháy một cơn giận hiếm hoi."
  },
  AvgDialog_131222_Content_101 = {
    Text = "Tôi không biết bạn đã làm gì với Gia Lân, nhưng điều đó không quan trọng. Dù sao đi nữa, cái giá bạn phải trả đã được định sẵn."
  },
  AvgDialog_131222_Content_102 = {
    Text = "À, một cuộc họp kinh doanh thất bại... Thật đáng tiếc, Bà Sorrel. Có vẻ như chỉ có xác của bà mới có thể cho tôi biết được."
  },
  AvgDialog_131222_Content_103 = {
    Text = "Sorrel nhíu mày, cảm nhận được sự dao động mạnh mẽ của sức mạnh tinh thần từ đối phương. Bóng đen như mực nhanh chóng tiếp cận, chặn mọi lối thoát của cô ấy."
  },
  AvgDialog_131222_Content_105 = {
    Text = "Khi lưỡi dao sắc trong bóng tối đột ngột đâm vào Sorrel, một luồng ánh sáng bạc mạnh mẽ như sao băng nhảy vào trong nhà."
  },
  AvgDialog_131222_Content_106 = {
    Text = "Sorrel, lùi lại"
  },
  AvgDialog_131222_Content_11 = {Text = "Tránh ra."},
  AvgDialog_131222_Content_12 = {
    Text = "Xin lỗi, thưa ngài. Bữa tiệc hôm nay, phải có thư mời mới có thể tham dự."
  },
  AvgDialog_131222_Content_13 = {
    Text = "Tên ngốc không có mắt, bạn có biết tôi là ai không?"
  },
  AvgDialog_131222_Content_14 = {
    Text = "Điều đó không phải là trách nhiệm của tôi, thưa ngài."
  },
  AvgDialog_131222_Content_15 = {
    Text = "Nghe giọng của bạn, tôi nghĩ bạn là người địa phương, tôi nghĩ bạn nên có thể hiểu những gì tôi nói."
  },
  AvgDialog_131222_Content_16 = {
    Text = "Ngươi!! Tốt, tốt, ta sẽ khiến ngươi và chủ nhân của tòa trang viên này phải trả giá"
  },
  AvgDialog_131222_Content_17 = {
    Text = "Arachne nhìn theo bóng lưng đầy phẫn nộ của quý tộc, lắc đầu."
  },
  AvgDialog_131222_Content_18 = {
    Text = "Có vẻ như, để vào được trang viên này không dễ như tưởng tượng."
  },
  AvgDialog_131222_Content_19 = {
    Text = "Nếu có thể tìm được vị đó, cô hầu bán nước tắm, có thể sẽ mua được hai vé mời…"
  },
  AvgDialog_131222_Content_2 = {
    Text = "Trang viên Công tước Cadlin, nơi giao lưu xã hội nổi tiếng nhất ở Lentiennam cổ."
  },
  AvgDialog_131222_Content_20 = {
    Text = "Muối tắm biển quý hiếm từ đảo Silla, hoa oải hương, chanh, đinh hương, và nhụy hoa hồng được vận chuyển từ miền nam Konstanz…"
  },
  AvgDialog_131222_Content_21 = {
    Text = "Nước tắm còn quý giá hơn cả thư mời, hiếm có hơn."
  },
  AvgDialog_131222_Content_22 = {Text = "???"},
  AvgDialog_131222_Content_23 = {
    Text = "Tôi vốn định tự nói một chút... Sao bạn lại biết cả những chuyện tôi đã trải qua trong giấc mơ?"
  },
  AvgDialog_131222_Content_24 = {
    Text = "Mặc dù không nhìn rõ số phận của bạn, nhưng số phận của những người bên cạnh bạn, tôi luôn theo dõi."
  },
  AvgDialog_131222_Content_25 = {
    Text = "Vì số phận của những người này có thể do bạn kiểm soát, nên dù việc chỉnh sửa có phức tạp, việc làm hai bức thư mời như vậy chắc chắn cũng có thể thực hiện được chứ?"
  },
  AvgDialog_131222_Content_26 = {
    Text = "Chuỗi phản ứng liên hoàn do việc thay đổi số phận gây ra, ngài đã chứng kiến. Số phận không phải là món đồ chơi tôi tùy ý bỡn cợt, mà là một ngôi nhà kính cần được tôi chăm sóc cẩn thận."
  },
  AvgDialog_131222_Content_27 = {
    Text = "Tôi cần cẩn thận đưa ra từng lựa chọn cho nó, tiêu tốn rất nhiều tâm sức và Tàn tro chiều. Tất cả sự bất cẩn và sai sót, sẽ đổi lấy sự sụp đổ và hủy diệt."
  },
  AvgDialog_131222_Content_28 = {
    Text = "Hơn nữa… Như tôi đã nói trước đây, nhiều lúc, làm một khán giả thú vị hơn nhiều so với việc làm một nhà soạn kịch."
  },
  AvgDialog_131222_Content_29 = {
    Text = "Ta rất mong chờ màn biểu diễn của ngươi, {Male=先生,Female=小姐}."
  },
  AvgDialog_131222_Content_3 = {
    Text = "Nửa đời trước của công tước, thủ tướng và các quan chức cấp cao trong nội các đã viết nên những bức thư quyết định vận mệnh của đế quốc trên bàn trà ở đồng cỏ."
  },
  AvgDialog_131222_Content_30 = {
    Text = "Nhưng tôi không rõ gì về nơi này……"
  },
  AvgDialog_131222_Content_31 = {
    Text = "Biểu diễn, trêu chọc, làm vui lòng…… Trong cơ thể bạn có sức mạnh như vậy. Sân khấu của số phận sẽ không dành cơ hội cho mọi người. Khi bạn cần bước lên sân khấu, những sức mạnh này sẽ giúp bạn."
  },
  AvgDialog_131222_Content_32 = {
    Text = "Ngươi không thể trốn tránh những sân khấu định sẽ đến. Hãy suy nghĩ, rồi biểu diễn đi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131222_Content_33 = {
    Text = "Nụ cười lịch sự của Arachne ẩn chứa một sự nghiêm túc không khó phát hiện. Cô ấy dường như đang kể cho bạn nghe, ánh mắt đó như thể đã xuyên qua bạn, đang trò chuyện với tương lai xa xôi."
  },
  AvgDialog_131222_Content_34 = {
    Text = "Đó là mệnh lệnh không thể từ chối của số phận. Bạn cúi đầu, suy nghĩ về lời nói của Arachne."
  },
  AvgDialog_131222_Content_35 = {
    Text = "Biểu diễn, trêu chọc, làm vui……cậu đang nói đến quyền lực của N?"
  },
  AvgDialog_131222_Content_36 = {
    Text = "Có nhưng sau trận quyết chiến với Toguwaibo, tôi đã mất liên lạc với lực lượng của ba Plasmid……"
  },
  AvgDialog_131222_Content_37 = {
    Text = "Lực lượng của Họ vẫn đang ngủ say, nhưng quyền năng không chỉ là lực lượng mà thôi."
  },
  AvgDialog_131222_Content_38 = {
    Text = "Quyền lực, không chỉ là lực lượng…"
  },
  AvgDialog_131222_Content_39 = {
    Text = "Khi bạn cố gắng suy nghĩ về câu này, một tia sáng linh hồn lóe lên trong thế giới tinh thần của bạn."
  },
  AvgDialog_131222_Content_4 = {
    Text = "Nửa đời sau của công tước, bóng dáng còng lưng của ông được trang viên đã bị bán tiễn đưa đến nơi hành hình."
  },
  AvgDialog_131222_Content_40 = {
    Text = "Bạn nhặt lên hai chiếc lá phong rơi trên mặt đất, vuốt ve những đường vân của chúng như một bức thư."
  },
  AvgDialog_131222_Content_41 = {
    Text = "Tôi nhớ bạn đã nói trước đây, tất cả mọi người trong thế giới này đều có bạc tâm trong cơ thể. Điều đó có nghĩa là, thế giới tinh thần của tất cả mọi người đều có thể bị chìa khóa bạc ảnh hưởng... đúng không?"
  },
  AvgDialog_131222_Content_42 = {
    Text = "Arachne mỉm cười nhìn bạn, đứng bên cạnh bạn, tiến về phía cánh cửa của trang viên."
  },
  AvgDialog_131222_Content_43 = {
    Text = "Xin chào, xin hãy xuất trình……"
  },
  AvgDialog_131222_Content_44 = {
    Text = "Thật là một trang viên đẹp. Chúng tôi rất vinh dự khi nhận được lời mời của Bà Sorrel."
  },
  AvgDialog_131222_Content_45 = {
    Text = "Khi đưa hai chiếc lá phong cho bảo vệ, chìa khóa bạc trong lòng bạn phát ra ánh sáng yếu ớt. Bạn dễ dàng bắt được điểm sáng của bảo vệ."
  },
  AvgDialog_131222_Content_46 = {
    Text = "Đồng thời, một điểm sáng khác xuất hiện trong thế giới tinh thần của bạn. Tại giao điểm của hai điểm sáng, ảo ảnh của Clementine lắc lư chiếc đồng hồ trong tay."
  },
  AvgDialog_131222_Content_47 = {
    Text = "Hugh… Hầu tước Hugh…"
  },
  AvgDialog_131222_Content_48 = {
    Text = "À, Quận chúa Huey, phu nhân Quận chúa, trang viên Cadlin xin chào đón sự đến của hai vị."
  },
  AvgDialog_131222_Content_49 = {
    Text = "Trong ánh mắt kính trọng của các bảo vệ, các bạn đã bước lên con đường sỏi phẳng lì của trang viên."
  },
  AvgDialog_131222_Content_5 = {
    Text = "Sau một khoảng thời gian ngắn im lặng, biệt thự này lại tràn đầy những vị khách quý, chủ nhân mới của nó đã thông báo sự quay lại của nó bằng những buổi salon."
  },
  AvgDialog_131222_Content_50 = {
    Text = "Cảm giác thế nào, Người Giữ Bí Mật {Male=先生,Female=小姐}?"
  },
  AvgDialog_131222_Content_51 = {
    Text = "Mặc dù tôi vẫn không hiểu ý nghĩa của quyền lực mà bạn nói, nhưng tôi vừa cảm nhận được một số điều khác biệt…"
  },
  AvgDialog_131222_Content_52 = {
    Text = "Cảm giác đó phát sinh sau sự chế nhạo, chưa bao giờ xuất hiện trên người tôi... giống như... hoàn toàn không phải là cảm xúc của chính tôi..."
  },
  AvgDialog_131222_Content_53 = {
    Text = "Bạn nâng tay lên, hai chiếc lá phong đẹp rời khỏi đầu ngón tay bạn, vui vẻ xoay tròn trong gió."
  },
  AvgDialog_131222_Content_54 = {
    Text = "Khi bạn và Arachne bước vào biệt thự với nụ cười thích hợp, bạn có thể chắc chắn rằng bạn nghe thấy một tiếng cười vui vẻ phát ra từ sâu trong cơ thể."
  },
  AvgDialog_131222_Content_56 = {
    Text = "Thật khó tưởng tượng, có người ở độ tuổi như vậy đã đạt được thành tựu như thế."
  },
  AvgDialog_131222_Content_57 = {
    Text = "Sau khi kết thúc cuộc đàm phán thương mại lần này, mối liên hệ giữa giới thương nhân và chính trị gia của thành phố này sẽ trải qua một cuộc cách mạng chưa từng có. Đây là một cơ hội hiếm có..."
  },
  AvgDialog_131222_Content_58 = {
    Text = "Thư mời mà tổng biên tập vất vả lắm mới có được, lần này chúng ta nhất định phải ghi lại vài khoảnh khắc tuyệt vời. Một lát nữa bạn mang thiết bị theo, chúng ta cố gắng đi về phía trước, lại gần một chút…"
  },
  AvgDialog_131222_Content_59 = {
    Text = "Ra rồi! Ra rồi!"
  },
  AvgDialog_131222_Content_6 = {
    Text = "Xin chào, đây là thư mời của tôi."
  },
  AvgDialog_131222_Content_60 = {
    Text = "Khi tiếng hô của thanh niên vang lên, tất cả mọi người đều lao về phía cánh cửa lớn đang mở."
  },
  AvgDialog_131222_Content_61 = {
    Text = "Chiếc váy dài màu đỏ như những bông hoa hồng rực rỡ, khiến tất cả trang trí và đám đông trong phòng trở nên mờ nhạt."
  },
  AvgDialog_131222_Content_62 = {
    Text = "Trên gương mặt Soleil luôn treo nụ cười lịch thiệp không bao giờ sai sót, bằng tư thế chuẩn mực nhất, nhẹ nhàng vẫy tay chào đám đông."
  },
  AvgDialog_131222_Content_63 = {
    Text = "Trên sân khấu này, nàng ấy làm tốt hơn trước rồi……Lâu lắm không gặp, Hồng Tường Vi."
  },
  AvgDialog_131222_Content_64 = {
    Text = "Thưa quý vị, chào mừng đến trang viên của tôi. Trong buổi salon hôm nay, một số tuyến phố thương mại của thành phố này sẽ có chủ nhân mới."
  },
  AvgDialog_131222_Content_65 = {
    Text = "Tất nhiên, các vị quý tộc đáng kính của chúng ta cũng sẽ nhận được những lợi ích xứng đáng."
  },
  AvgDialog_131222_Content_66 = {
    Text = "Ta nghĩ, đêm nay nhất định sẽ có một bữa tiệc tối tinh tế và vui vẻ."
  },
  AvgDialog_131222_Content_67 = {
    Text = "Đầu bếp của trang viên đã chuẩn bị những món bánh và rượu sâm panh hàng đầu cho mọi người, xin hãy nghỉ ngơi một chút. Chẳng mấy chốc, bữa tiệc tối của chúng ta sẽ chính thức bắt đầu."
  },
  AvgDialog_131222_Content_68 = {
    Text = "Ánh mắt vui vẻ của Sorrel quét qua toàn bộ khán phòng, rồi cô quay người lên lầu."
  },
  AvgDialog_131222_Content_69 = {
    Text = "Sorrel… Sorrel! … Gia Lân"
  },
  AvgDialog_131222_Content_7 = {
    Text = "……à, xin chào ngài Phúc Căn. Chủ nhân đang chờ đợi sự đến của ngài ở bên trong, xin mời vào."
  },
  AvgDialog_131222_Content_70 = {
    Text = "Tiếng gọi của bạn bị chìm trong những cuộc thảo luận và tiếng hét của đám đông."
  },
  AvgDialog_131222_Content_71 = {
    Text = "Bà Sorrel! Bà Sorrel! Xin hỏi bà đã lập kế hoạch phân chia khu thương mại như thế nào? Điều này có chạm đến…"
  },
  AvgDialog_131222_Content_72 = {
    Text = "Suỵt, ông phóng viên. Tôi vừa mới trở về sau khi xử lý xong công việc bên ngoài, đợi tôi thay đồ xong, tôi sẽ trả lời tất cả những câu hỏi mà ông muốn biết."
  },
  AvgDialog_131222_Content_73 = {
    Text = "Sorrel vẫy tay chào các phóng viên, đi vào khu vực phòng ngủ trên tầng của biệt thự."
  },
  AvgDialog_131222_Content_74 = {
    Text = "Dường như chúng ta phải đợi cô ấy ra ngoài rồi mới hỏi cô ấy được."
  },
  AvgDialog_131222_Content_75 = {
    Text = "Bạn có chú ý đến cô hầu gái bên cạnh bà Sorrel không?"
  },
  AvgDialog_131222_Content_76 = {
    Text = "Gia Lân? Tất nhiên, cô ấy cũng không nghe thấy đâu... Chờ đã, ý của bạn là..."
  },
  AvgDialog_131222_Content_77 = {
    Text = "Bạn nhớ lại hơi thở của Gia Lân. Hơi thở đó hoàn toàn khác biệt với những gì bạn đã quen thuộc, ngay cả khi ở trong những chiều không gian khác nhau, chúng cũng không thể thuộc về cùng một người."
  },
  AvgDialog_131222_Content_78 = {
    Text = "Tôi cảm nhận được quỹ đạo số phận không thuộc về sân khấu này trên người cô ấy……số phận của cô ấy đã bị ô nhiễm."
  },
  AvgDialog_131222_Content_79 = {
    Text = "Bà Sorrel đang gặp nguy hiểm"
  },
  AvgDialog_131222_Content_8 = {
    Text = "Hừ, ngay cả thương nhân đầy mùi đồng như Phúc Căn cũng có thể ra vào dinh thự của công tước già, phong độ của Lentiennam đã hoàn toàn biến mất rồi..."
  },
  AvgDialog_131222_Content_80 = {
    Text = "Bạn mạnh mẽ chen qua đám đông, tìm thấy một cầu thang ẩn ở phía sau tòa nhà."
  },
  AvgDialog_131222_Content_81 = {
    Text = "Xin lỗi, {Male=先生,Female=小姐}, đây là tư dinh của phu nhân Soreil, cấm người không liên quan……"
  },
  AvgDialog_131222_Content_82 = {
    Text = "Bà Sorrel mời tôi đến để thảo luận về những việc quan trọng với bà ấy."
  },
  AvgDialog_131222_Content_83 = {
    Text = "Bạn rút ra một tờ khăn ăn bị xé xuống một cách tùy tiện. Ánh sáng bạc lấp lánh, một giấy chứng nhận cảnh sát của hội nghị thẩm tra được đặt trước mặt bảo vệ."
  },
  AvgDialog_131222_Content_84 = {
    Text = "Xin lỗi, tôi không nhận ra bà... Bà Sorrel đang ở trên, tôi có thể giúp gì cho bà..."
  },
  AvgDialog_131222_Content_85 = {
    Text = "Nhiệm vụ bí mật, chuyện tôi đến đây đừng để người khác biết."
  },
  AvgDialog_131222_Content_86 = {
    Text = "Chưa kịp để viên cảnh sát nói, bạn đã vội vàng chạy lên cầu thang."
  },
  AvgDialog_131222_Content_88 = {
    Text = "Trang phục của bà đã sẵn sàng, thưa bà Sorrel"
  },
  AvgDialog_131222_Content_89 = {
    Text = "Lentiennam là một vùng hoang dã nguyên thủy, chính trị gia và thương nhân là những con linh cẩu của thành phố này…"
  },
  AvgDialog_131222_Content_9 = {
    Text = "Xin chào, vui lòng xuất trình thư mời."
  },
  AvgDialog_131222_Content_90 = {
    Text = "Soreil cầm lấy bộ trang phục mà Galen đã chuẩn bị. Ánh sáng xuyên qua lớp voan đỏ mỏng, hắt một bóng hình rực rỡ trong phòng ngủ hoa lệ."
  },
  AvgDialog_131222_Content_91 = {
    Text = "Linh cẩu cũng có những điểm dễ thương. Một miếng thịt thối, có thể khiến chúng lao vào như thiêu thân. Tham lam, sắc bén, tàn nhẫn, ngây thơ. Không có vũ khí nào hiệu quả hơn chúng."
  },
  AvgDialog_131222_Content_92 = {
    Text = "Tôi thấy họ đã mất kiên nhẫn rồi……Hôm nay ngài xuất hiện hơi muộn, chiếc váy quý giá này cũng bị làm bẩn đôi chút."
  },
  AvgDialog_131222_Content_93 = {
    Text = "Bà nên về sớm một chút."
  },
  AvgDialog_131222_Content_94 = {
    Text = "Hành động của Sorrel dừng lại trong giây lát. Cô từ từ hạ chiếc váy màu đỏ, nhìn về phía khuôn mặt bình tĩnh của Gia Lân."
  },
  AvgDialog_131222_Content_95 = {
    Text = "Chắc hẳn đã có người dạy bạn cách nói chuyện của người hầu với chủ nhân. Hôm nay bạn sao vậy?"
  },
  AvgDialog_131222_Content_96 = {
    Text = "Bà Sorrel, bà có vết bẩn từ Khu Đông. Tôi rất tò mò, bà đã đưa vị đó, người đàn ông tốt bụng, đi đâu?"
  },
  AvgDialog_131222_Content_97 = {
    Text = "Căn phòng sáng sủa bỗng trở nên u ám trong chốc lát. Vài con nhện đen từ trong bóng tối biến thành hình người, bao vây Sorrel ở giữa."
  },
  AvgDialog_131222_Content_98 = {
    Text = "Bà có một người hầu rất trung thành, Bà Sorrel. Mặc dù cô ấy say mê việc ăn cắp và bán đi tài sản của bà, nhưng về việc bảo vệ sự an toàn của bà, lòng trung thành của cô ấy là không thể nghi ngờ."
  },
  AvgDialog_131222_Content_99 = {
    Text = "Cho đến tận bây giờ, ý chí của nàng ấy vẫn đang kịch liệt chống cự. Chỉ tiếc rằng, sức mạnh của định mệnh không phải là thứ con người có thể chống lại."
  },
  AvgDialog_131223_Content_1 = {
    Text = "Số mệnh. Hoang dã, hư vô, bi thương. Những số mệnh bị ruồng bỏ không biết mình đến từ đâu, đi về đâu."
  },
  AvgDialog_131223_Content_10 = {
    Text = "Giọng nói của Nephreya đột ngột trở nên sắc nhọn. Ánh sáng mờ ảo lóe lên, những sợi chỉ đỏ tươi siết chặt lấy cô, ngọn lửa còn lại từ đèn cầm tay thiêu đốt cơ thể cô."
  },
  AvgDialog_131223_Content_11 = {
    Text = "Cái càng khổng lồ đung đưa trong không trung, đôi mắt phức tạp khổng lồ chảy đầy chất lỏng đen dính, mang theo nụ cười nhìn về phía các bạn. Sợi chỉ đỏ tươi quấn quanh cơ thể cô, trôi nổi trong vòng xoáy số phận."
  },
  AvgDialog_131223_Content_12 = {
    Text = "Cô ấy bên cạnh, cái vòng quay bị vỡ, nơi tập hợp sợi chỉ, từ từ và không thể ngăn cản quay tròn, siết chặt tất cả các sân khấu, siết chặt chính Nefreya."
  },
  AvgDialog_131223_Content_13 = {Text = "Ừ——"},
  AvgDialog_131223_Content_14 = {
    Text = "Bạn đau đớn ôm đầu. Dưới sự chuyển động của vòng quay, thế giới tinh thần của bạn bắt đầu dâng trào. Bạn thở hổn hển, cố gắng làm dịu đi cơn đau dữ dội đó."
  },
  AvgDialog_131223_Content_15 = {
    Text = "Bên cạnh Nephreya, những mảnh vụn của đường dẫn chiều đã không còn nhiều. Những sợi dây trên người các bạn, những họa tiết như búp bê, càng ngày càng rõ ràng."
  },
  AvgDialog_131223_Content_16 = {
    Text = "Sức mạnh của chiều không gian… Cô ấy đã gần như hoàn toàn hấp thụ rồi"
  },
  AvgDialog_131223_Content_17 = {
    Text = "Tàn tro tím nhạt không ngừng tuôn ra từ cơ thể Arachne, như những con thiêu thân lao về phía tấm lưới vận mệnh gần như đã hoàn toàn tan vỡ."
  },
  AvgDialog_131223_Content_18 = {
    Text = "Arachne run rẩy đôi tay theo tần số không thay đổi từ xưa, xoay vòng tay trong bánh xe dệt. Giọng nói của cô ấy, vẫn bình tĩnh như lần đầu bạn gặp cô."
  },
  AvgDialog_131223_Content_19 = {
    Text = "Bạn đã nhìn thấy. Đây là giao điểm của số phận, Nefreya."
  },
  AvgDialog_131223_Content_2 = {
    Text = "Chúng bị sợi tơ dẫn dắt, ùa về phía ngươi, hóa thành từng vũng dịch đen trong ánh bạc của ngươi."
  },
  AvgDialog_131223_Content_20 = {
    Text = "Tất cả những sai lầm sẽ kết thúc ở đây."
  },
  AvgDialog_131223_Content_21 = {
    Text = "Một tuyên bố đầy tự tin, thưa quý cô Tù nhân. Vậy hãy để tôi xem, bạn sẽ dựa vào điều gì để ngăn cản thần minh, để ngăn cản chính số phận…"
  },
  AvgDialog_131223_Content_22 = {
    Text = "Nụ cười điên rồ nở rộ trên khuôn mặt của Nephreya. Những sợi dây hạn chế cô ấy được nâng lên, trên sân khấu vỡ vụn, cô ấy là ánh sáng duy nhất."
  },
  AvgDialog_131223_Content_23 = {
    Text = "\"Đến đây, hỡi những tín đồ bò lết trên mặt đất! Quỳ xuống bái lạy ta!\""
  },
  AvgDialog_131223_Content_24 = {
    Text = "\"Đấng Tối Cao đã hạ mình từ thiên tọa, kết cục không thể cưỡng lại, đã hiện hình nơi đây!\""
  },
  AvgDialog_131223_Content_25 = {
    Text = "\"Vận mệnh giả dối kia, hãy cùng nhau, đón nhận sự kết thúc của nó!\""
  },
  AvgDialog_131223_Content_3 = {
    Text = "Chất nhầy hoang dã, hư vô, đáng thương, như chính số phận của họ."
  },
  AvgDialog_131223_Content_4 = {
    Text = "Nefreya không quan tâm đến tất cả những điều này, cảnh tượng trước mắt cô ấy đã diễn ra trong nhiều năm, và cô ấy đã quen với điều đó từ lâu."
  },
  AvgDialog_131223_Content_5 = {
    Text = "Tôi đã nhìn rõ. Những hình ảnh mà bạn thấy, mọi thứ mà bạn thấy, cuối cùng tôi cũng đã nhìn rõ......"
  },
  AvgDialog_131223_Content_6 = {
    Text = "Nỗi đau do những mảnh vỡ mang lại đã hoàn toàn tê dại, cô ấy mỉm cười nhìn về những khoảng trống hỗn loạn trong nhà hát."
  },
  AvgDialog_131223_Content_7 = {
    Text = "Nụ cười kiêu ngạo, thương hại và thờ ơ, có một khoảnh khắc, bạn gần như không phân biệt được cô ấy với Arachne."
  },
  AvgDialog_131223_Content_8 = {
    Text = "Chỉ có những người bị giam trong nhà tù mới có thể thực sự mở ra nhà tù. Những gì bạn thấy là hỗn loạn và hủy diệt, không phải là số phận thật, Nefreya…"
  },
  AvgDialog_131223_Content_9 = {
    Text = "Hehe! … Bao năm qua, bạn vẫn tự lừa dối mình như vậy sao, Arachne?"
  },
  AvgDialog_131224_Content_1 = {
    Text = "Khán giả, diễn viên, tác giả"
  },
  AvgDialog_131224_Content_10 = {
    Text = "Đây là…!"
  },
  AvgDialog_131224_Content_100 = {
    Text = "Hãy đi tìm %player% đi, các con."
  },
  AvgDialog_131224_Content_101 = {
    Text = "Hãy đoạt lấy sức mạnh của %player%, cắt đứt từng sợi tơ vận mệnh, xé nát tấm lưới vận mệnh, để mọi kẻ cản đường trên con đường này đều chết trên con đường đó!"
  },
  AvgDialog_131224_Content_102 = {
    Text = "Chúng ta sẽ dùng máu của phân mảnh này, để đánh thức vĩ đại khởi nguyên một lần nữa."
  },
  AvgDialog_131224_Content_103 = {
    Text = "Khi ngươi nhìn thấy tấm lưới vận mệnh mà ngươi dày công gìn giữ tan tành hết thảy, hóa thành một vũng bùn nhão, ngươi có chìm vào hư vô vô tận như chúng ta không?"
  },
  AvgDialog_131224_Content_104 = {
    Text = "Nữ thần vận mệnh, chị gái tốt bụng của ta, <Red:Arachne> thân yêu?"
  },
  AvgDialog_131224_Content_105 = {
    Text = "Khoảng cách giữa sân khấu và hàng ghế khán giả dường như không còn tồn tại, không gian mất đi ý nghĩa trong nhà hát này."
  },
  AvgDialog_131224_Content_106 = {
    Text = "Trong tiếng cười thê lương, con rối dường như đang đứng ngay trước mặt các bạn, nhìn thẳng vào đôi mắt của Arachne."
  },
  AvgDialog_131224_Content_107 = {
    Text = "Ánh sáng tắt đi, màn hạ xuống. Con rối và tiếng cười của cô ấy biến mất, trong nhà hát vắng vẻ, chỉ còn lại âm thanh của bánh xe quay nhẹ nhàng."
  },
  AvgDialog_131224_Content_108 = {
    Text = "Xin lỗi, tôi không hoàn toàn hiểu…… số phận bị bỏ rơi, có nghĩa là gì?"
  },
  AvgDialog_131224_Content_109 = {
    Text = "Như bạn thấy, số phận là một đám sợi chỉ hỗn loạn, nếu không có ai dệt nên, vũ trụ này sẽ rơi vào hỗn loạn vô tận. Tôi nghĩ, đó là cảnh tượng mà chúng ta đều không muốn thấy."
  },
  AvgDialog_131224_Content_11 = {
    Text = "Ngay khi bạn bước vào cửa, cánh cửa phía sau biến mất không còn dấu vết."
  },
  AvgDialog_131224_Content_110 = {
    Text = "Tất nhiên…"
  },
  AvgDialog_131224_Content_111 = {
    Text = "Dệt sợi chỉ thành mạng lưới số phận, duy trì sự vận hành bình thường của vũ trụ này, là trách nhiệm vĩnh cửu của tôi."
  },
  AvgDialog_131224_Content_112 = {
    Text = "Mỗi khoảnh khắc, vận mệnh đều có vô số khả năng. Mỗi khoảnh khắc, tôi đều buộc phải đưa ra lựa chọn cho mọi vận mệnh."
  },
  AvgDialog_131224_Content_113 = {
    Text = "Vận mệnh đúng đắn sẽ hòa vào tấm lưới lớn, vận mệnh sai lầm sẽ bị ruồng bỏ. Lưới vận mệnh vận hành như vậy, không thể tránh khỏi."
  },
  AvgDialog_131224_Content_114 = {
    Text = "Em gái của tôi, cũng là một phần mà tôi đã bỏ rơi trong những số phận sai lầm đó."
  },
  AvgDialog_131224_Content_115 = {
    Text = "Arachne mỉm cười, trong lời kể bình thản của cô ấy, bạn không thể nhận thấy chút cảm xúc dao động nào."
  },
  AvgDialog_131224_Content_116 = {
    Text = "Những số phận bị bỏ rơi... sẽ bị gửi vào \"Địa ngục\"?"
  },
  AvgDialog_131224_Content_117 = {
    Text = "Giấc mơ của vị thần tối cao đó cấu thành nên vũ trụ này, nơi được gọi là\"Địa ngục thẳm sâu\", là tiềm thức của thần minh, là nơi tập hợp của mọi sự việc chưa xảy ra, mọi số phận không tồn tại."
  },
  AvgDialog_131224_Content_118 = {
    Text = "Chúng lẽ ra phải hoàn toàn tan biến ở nơi hư vô đó, nhưng dưới sự dẫn dắt của vị đó, chúng đã sống sót bằng một cách nào đó."
  },
  AvgDialog_131224_Content_119 = {
    Text = "Arachne nhìn về phía bức màn khổng lồ, nhìn về phía sau bức màn, nơi có con rối đại diện cho Nephreya."
  },
  AvgDialog_131224_Content_12 = {
    Text = "Trong cửa hàng hẹp mà bạn tưởng tượng, là một không gian chiều rộng lớn vô tận."
  },
  AvgDialog_131224_Content_120 = {
    Text = "Cô ấy không có khả năng điều khiển số phận, nhưng cô ấy giống như tôi, có thể nhìn thấy những sợi chỉ của số phận, che chắn chúng, ô nhiễm chúng, phá hủy quỹ đạo mà tôi đã dệt cho chúng, dẫn chúng đến cái chết……"
  },
  AvgDialog_131224_Content_121 = {
    Text = "Vậy cô ấy muốn tìm tôi, lợi dụng sức mạnh của tôi, để Hoán tỉnh Toguwaibo một lần nữa?"
  },
  AvgDialog_131224_Content_122 = {
    Text = "Tôi không thể biết kế hoạch cụ thể của cô ấy, nhưng hiện tại có vẻ đúng là như vậy. Dù sao đi nữa, cô ấy là một sai lầm mà tôi phải giải quyết."
  },
  AvgDialog_131224_Content_123 = {
    Text = "Cô ấy đóng cửa thông đạo giữa các chiều, cũng vì điều này phải không……"
  },
  AvgDialog_131224_Content_124 = {
    Text = "Chiều không gian là tôi đã đóng lại. Cô ấy luôn chờ đợi, chờ đợi khoảnh khắc cùng bạn đến với Cađas."
  },
  AvgDialog_131224_Content_125 = {
    Text = "Cađas là một chiều mà sức mạnh của tôi chưa từng chạm đến, cũng là nơi kết nối chặt chẽ nhất với Vị đó thần thánh."
  },
  AvgDialog_131224_Content_126 = {
    Text = "Nếu để cô ấy theo bạn trở về, số phận thảm họa sẽ hoàn toàn không thể cứu vãn."
  },
  AvgDialog_131224_Content_127 = {
    Text = "Xin hãy tha thứ cho sự tự ý quyết định của tôi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131224_Content_128 = {
    Text = "Tôi hiểu, Arachne. Nếu những gì bạn nói là thật, thì đó cũng không phải là cảnh tượng mà tôi muốn thấy."
  },
  AvgDialog_131224_Content_129 = {
    Text = "Vì vậy, nếu tôi muốn trở về Cađas, nhất định phải giải quyết cô ấy trước…"
  },
  AvgDialog_131224_Content_13 = {
    Text = "Vô số sân khấu lơ lửng như những vì sao trong vùng tối tăm này, những con rối trên mỗi sân khấu đang ngâm nga lời thoại của mình."
  },
  AvgDialog_131224_Content_130 = {
    Text = "Chủ nhân, sân khấu khu vực GI-9849 đã xảy ra bất thường. Đây là trường hợp thứ ba hôm nay."
  },
  AvgDialog_131224_Content_131 = {
    Text = "Sau khi đánh cắp nguyên liệu để thêu dệt số phận, cô ấy luôn thích thú với việc phá hủy số phận này."
  },
  AvgDialog_131224_Content_132 = {
    Text = "Rất xin lỗi, %player%, bây giờ tôi cần đi xử lý những rắc rối đó. Xin ngài đi theo tôi, có một số việc quan trọng tôi nghĩ cần phải cho ngài biết."
  },
  AvgDialog_131224_Content_133 = {
    Text = "Arachne mỉm cười và lắc đầu. Cô ấy thực hiện một động tác mời gọi về phía bạn, đứng dậy cầm theo bánh xe dệt."
  },
  AvgDialog_131224_Content_135 = {
    Text = "Đây…… chính là sân khấu bị hủy hoại?……"
  },
  AvgDialog_131224_Content_136 = {
    Text = "Theo con đường được dệt bằng mạng nhện, các bạn đến một sân khấu cũ kỹ. Ở quán cà phê đơn giản trên sân khấu, vài người trông như học sinh đang cúi đầu nói chuyện."
  },
  AvgDialog_131224_Content_137 = {
    Text = "Trong khoảng thời gian này, cô ấy luôn phái đi những người hầu của mình để phá hủy số phận của những thế giới này. Các nữ tì của tôi đang tìm kiếm khắp nơi, chiến đấu với họ, khiến nhiều đứa trẻ tốt mất đi sinh mạng."
  },
  AvgDialog_131224_Content_138 = {
    Text = "Tất cả số phận của các thế giới đều kết nối trên một mạng lưới khổng lồ, mỗi sự sụp đổ của một thế giới sẽ khiến toàn bộ mạng lưới số phận bị xé nát, khiến mọi thứ rơi vào sự hỗn loạn hoàn toàn và chết người."
  },
  AvgDialog_131224_Content_139 = {
    Text = "Nephreya đã đánh cắp nguyên liệu dệt vận mệnh, tôi không thể dễ dàng sử dụng sức mạnh của mình. Người Giữ Bí Mật {Male=先生,Female=小姐}, tôi nghĩ, có lẽ ngài có thể giúp tôi tu phục vận mệnh của thế giới này?"
  },
  AvgDialog_131224_Content_14 = {
    Text = "Những lời thoại ấy vọng đến tai bạn từ xa, như vô số tín đồ thành kính tụng niệm."
  },
  AvgDialog_131224_Content_140 = {
    Text = "Nếu những gì bạn nói là đúng, cô ấy cũng là vấn đề mà tôi phải giải quyết."
  },
  AvgDialog_131224_Content_141 = {
    Text = "Arachne xin lỗi gật đầu với bạn. Cô ấy giơ tay lên, nhẹ nhàng vẫy những sợi chỉ ẩn trong không khí hư vô."
  },
  AvgDialog_131224_Content_142 = {Text = "Đinh —"},
  AvgDialog_131224_Content_143 = {
    Text = "Sau tiếng nhạc cụ trong trẻo, giọng nói du dương của người giới thiệu vang lên, như dòng chảy vĩnh hằng không ngừng đổ vào cái giếng sâu thẳm."
  },
  AvgDialog_131224_Content_144 = {
    Text = "Kèn chơi hoa điệu. Sinh viên trẻ và học giả, lên——"
  },
  AvgDialog_131224_Content_145 = {
    Text = "Arachne làm một cử chỉ mời."
  },
  AvgDialog_131224_Content_146 = {
    Text = "Đã đến lúc chúng ta xuất trận rồi, %player%."
  },
  AvgDialog_131224_Content_147 = {
    Text = "Bạn gật đầu. Trong tiếng báo hiệu du dương, hai con rối bước lên sân khấu của riêng chúng."
  },
  AvgDialog_131224_Content_15 = {
    Text = "Một sợi tơ nhện kéo dài từ diễn viên con rối và sân khấu, cùng với con đường được dệt từ tơ nhện dưới chân bạn, hội tụ về giữa không gian này, nơi có sân khấu."
  },
  AvgDialog_131224_Content_16 = {
    Text = "Bạn quay đầu lại, nữ hầu bên cạnh đã đi về phía trước."
  },
  AvgDialog_131224_Content_17 = {
    Text = "Thật là một lễ chào đón kỳ lạ……"
  },
  AvgDialog_131224_Content_18 = {
    Text = "Bạn do dự, đi dọc theo con đường mạng nhện về phía sân khấu ở giữa. Khi bạn đi qua những sân khấu lơ lửng, những đoạn đối thoại bay vào tai bạn."
  },
  AvgDialog_131224_Content_19 = {
    Text = "Vị khách này, tôi đã thấy sự bối rối trong mắt của bạn."
  },
  AvgDialog_131224_Content_2 = {
    Text = "Tôi còn một vấn đề nữa…"
  },
  AvgDialog_131224_Content_20 = {
    Text = "Vụ tai nạn xảy ra ở cửa hàng vừa rồi không làm bạn sợ hãi chứ?"
  },
  AvgDialog_131224_Content_21 = {
    Text = "Cấu trúc dựa trên rượu vàng, mang hương vị hoa dâm bụt, chắc chắn rất phù hợp với tâm trạng hiện tại của bạn."
  },
  AvgDialog_131224_Content_23 = {
    Text = "À! Một đứa trẻ không nhà, thật nhỏ bé, thật đáng thương."
  },
  AvgDialog_131224_Content_24 = {
    Text = "Dựa vào những bộ quần áo mỏng manh này, bạn sẽ làm thế nào để vượt qua mùa đông này?"
  },
  AvgDialog_131224_Content_25 = {
    Text = "Hãy đi theo ta, ta sẽ đưa ngươi đến một nơi che chắn gió tuyết…"
  },
  AvgDialog_131224_Content_27 = {
    Text = "Những người này… là những người tôi vừa gặp sao?"
  },
  AvgDialog_131224_Content_28 = {
    Text = "Họ làm sao lại xuất hiện trên những sân khấu này…"
  },
  AvgDialog_131224_Content_29 = {
    Text = "Cảnh sát tuần tra, nhân viên xem báo, tài xế ngắm cảnh phố, cặp đôi mua hoa, quý tộc trò chuyện……"
  },
  AvgDialog_131224_Content_3 = {
    Text = "Đây đã là câu hỏi thứ hai mươi ba của ngài rồi, {Male=先生,Female=小姐}."
  },
  AvgDialog_131224_Content_30 = {
    Text = "Những người bạn đã gặp và chưa gặp, đang diễn những câu chuyện của riêng họ trên vô số sân khấu này. Trên sân khấu của riêng mình, họ đều là nhân vật chính của chính mình."
  },
  AvgDialog_131224_Content_31 = {
    Text = "Vạn phúc, %player%! Chúc phúc cho ngài, hài nhi của Akut!"
  },
  AvgDialog_131224_Content_32 = {
    Text = "Vạn phúc, %player%! Chúc phúc cho ngài, Người Giữ Bí Mật của Misago!"
  },
  AvgDialog_131224_Content_33 = {
    Text = "Vạn phúc, %player%! Chúc phúc cho ngài, vị thần hủy diệt vạn vật!"
  },
  AvgDialog_131224_Content_34 = {
    Text = "Khi bạn tiến gần đến sân khấu trung tâm, ba con rối có hình dạng khác nhau bước lên sân khấu, cúi người chào bạn."
  },
  AvgDialog_131224_Content_35 = {
    Text = "Chủ nhân đang chờ ngài bên trong. Xin mời vào, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131224_Content_36 = {
    Text = "Khi cánh cửa của phòng riêng mở ra, dường như hình ảnh và âm thanh của toàn bộ nhà hát đã tạm dừng trong một khoảnh khắc."
  },
  AvgDialog_131224_Content_37 = {
    Text = "Bạn bước vào trong cửa, kéo tấm màn lên——"
  },
  AvgDialog_131224_Content_38 = {
    Text = "Họ xuất hiện trên những sân khấu này, bởi vì tên của nhà hát này, được gọi là số phận."
  },
  AvgDialog_131224_Content_39 = {
    Text = "Giọng nói thanh lãnh, ôn hòa đến trước bạn sớm hơn cả sắc màu."
  },
  AvgDialog_131224_Content_4 = {
    Text = "So với những câu đố ở nơi này, vấn đề của tôi vẫn còn xa xa chưa đủ."
  },
  AvgDialog_131224_Content_40 = {
    Text = "Trong một bao loge gần như vô tận, những sợi tơ nối sân khấu với con rối hội tụ trên một chiếc xa kéo sợi tỏa ánh sáng mờ nhạt. Một người phụ nữ ngồi tại nơi giao nhau của những sợi tơ, nhẹ nhàng quay chiếc xa kéo sợi."
  },
  AvgDialog_131224_Content_41 = {
    Text = "Bạn nhìn rõ từng chi tiết của cô ấy, nhưng trong mỗi khoảnh khắc chớp mắt, mọi ấn tượng về cô ấy đều biến mất khỏi thế giới tinh thần của bạn, không còn dấu vết."
  },
  AvgDialog_131224_Content_42 = {
    Text = "Hình ảnh của cô ấy trong tâm trí bạn luôn mờ nhạt. Khi cô ấy quay đầu nhìn về phía bạn, trái tim vốn luôn giữ cảnh giác cao độ của bạn bỗng đập dữ dội."
  },
  AvgDialog_131224_Content_43 = {
    Text = "Là ngươi?!!"
  },
  AvgDialog_131224_Content_44 = {
    Text = "Trên tàu Lạc Viên… còn có mấy lần tấn công chúng ta nữa……!"
  },
  AvgDialog_131224_Content_45 = {
    Text = "Khi bạn chuẩn bị truyền sức mạnh tinh thần vào chìa khóa bạc, chủ nhân của nhà hát giơ tay ra, vẽ một đường trong không trung. Hành động của cô ấy nhẹ nhàng và duyên dáng, dường như đang khẽ gảy một sợi dây."
  },
  AvgDialog_131224_Content_46 = {Text = "!!!"},
  AvgDialog_131224_Content_47 = {
    Text = "Sức mạnh tinh thần đến đầu ngón tay của bạn, nhưng lại như dòng lũ bị ngăn cản bởi đê điều mà rút lui. Khi bạn nâng tay lên giữa không trung, bạn bỗng nhận ra rằng, không biết từ lúc nào, tay bạn đã trống rỗng."
  },
  AvgDialog_131224_Content_48 = {
    Text = "Chìa khóa bạc……chìa khóa bạc luôn ở trong tay tôi……tại sao……"
  },
  AvgDialog_131224_Content_49 = {
    Text = "Cô ấy mỉm cười nhẹ nhàng gật đầu với nữ hầu."
  },
  AvgDialog_131224_Content_5 = {
    Text = "Tôi không phải là người bạn đang tìm kiếm để giải đáp. Người có thể trả lời câu hỏi của bạn, đang ở đây chờ bạn."
  },
  AvgDialog_131224_Content_50 = {
    Text = "Trong ánh mắt kinh ngạc của bạn, nữ hầu bước lên phía trước, cung kính đặt chiếc chìa khóa bạc vào tay bạn."
  },
  AvgDialog_131224_Content_51 = {
    Text = "Không thể nào…… cô ấy tuyệt đối không thể đánh cắp chìa khóa bạc!……"
  },
  AvgDialog_131224_Content_52 = {
    Text = "Trước khi bước vào nhà hát, ngài đã cầm chìa khóa trong tay và luôn duy trì liên kết tinh thần với chiếc chìa khóa bạc."
  },
  AvgDialog_131224_Content_53 = {
    Text = "Sự huấn luyện của Misago đã mang lại cho ngài sự chuyên nghiệp và cảnh giác cao độ, không ai có thể đánh cắp chiếc chìa khóa bạc từ tay ngài."
  },
  AvgDialog_131224_Content_54 = {
    Text = "Tại sao lại như vậy…"
  },
  AvgDialog_131224_Content_55 = {
    Text = "Không ai có thể để nó rời khỏi bạn, nhưng số phận thì có thể."
  },
  AvgDialog_131224_Content_56 = {
    Text = "Rất xin lỗi, %player%, tôi hiểu sự căng thẳng của ngài, và cũng tôn trọng sức mạnh của ngài."
  },
  AvgDialog_131224_Content_57 = {
    Text = "Để ngăn ngừa ngài vô tình gây tổn hại cho nhà hát, tôi buộc phải tạm thời thay đổi vận mệnh của chiếc chìa khóa bạc trong tay ngài, xin ngài thứ lỗi."
  },
  AvgDialog_131224_Content_58 = {
    Text = "Cô ấy vẫy tay, một tia sáng chiếu vào khoảng giữa bạn và cô ấy. Bạn nhìn kỹ, cuối cùng thấy một sợi tơ mờ ảo kéo dài từ chiếc chìa khóa bạc, nối đến chiếc xa kéo sợi của cô ấy."
  },
  AvgDialog_131224_Content_59 = {
    Text = "Những sợi chỉ này là…?"
  },
  AvgDialog_131224_Content_6 = {
    Text = "Các bạn dừng lại trước một cánh cửa nhà hát chỉ rộng một người. Không có biển hiệu, cũng không có khách hàng, giữa những cửa hàng lộng lẫy ở Lentiennam như một cái mạng nhện không có gì nổi bật."
  },
  AvgDialog_131224_Content_60 = {
    Text = "Về sợi chỉ có nhiều giải thích, có cái quá phức tạp đối với hiện tại. Bạn có thể đơn giản hiểu chúng là… số phận."
  },
  AvgDialog_131224_Content_61 = {
    Text = "Chiếc xa kéo sợi tự mình nhẹ nhàng quay. Cô ấy đứng dậy, gật đầu chào bạn."
  },
  AvgDialog_131224_Content_62 = {
    Text = "Arachne, chủ nhân của nhà hát số phận. Rất hân hạnh được gặp bạn, Người Giữ Gìn."
  },
  AvgDialog_131224_Content_63 = {
    Text = "Đừng lo lắng, bạn ở đây là an toàn."
  },
  AvgDialog_131224_Content_64 = {
    Text = "Quả thật, nếu bạn muốn giết tôi, thì vừa rồi tôi e rằng không có cơ hội nào sống sót."
  },
  AvgDialog_131224_Content_65 = {
    Text = "Khi Arachne gảy sợi tơ, ánh sáng từ chiếc xa kéo sợi trong bao loge dần tối đi. Bạn nhìn chiếc chìa khóa bạc được nữ hầu trả lại với vẻ mặt phức tạp, cau mày nhìn về phía cô ấy."
  },
  AvgDialog_131224_Content_66 = {
    Text = "Trên tàu Lạc Viên, ngươi từng giúp đỡ ta. Trong thành phố này, ngươi lại hai lần tấn công ta…"
  },
  AvgDialog_131224_Content_67 = {
    Text = "Tôi hiểu sự cảnh giác của ngài. Nhưng xin hãy tin rằng, tôi chưa bao giờ làm điều gì gây hại cho ngài."
  },
  AvgDialog_131224_Content_68 = {
    Text = "Đã phong tỏa liên kết của tôi với Cađas, nhiều lần tấn công tôi…… bạn muốn nói rằng, những chuyện này không phải do bạn làm?"
  },
  AvgDialog_131224_Content_69 = {
    Text = "Vị đó làm phiền bạn mặc dù có khuôn mặt giống tôi, nhưng không phải là tôi."
  },
  AvgDialog_131224_Content_7 = {
    Text = "Cô hầu gái nhẹ nhàng đẩy cửa ra, hình bóng cô hòa vào bóng tối bên trong. Trong bóng tối, ánh sáng không rõ nguồn gốc nhấp nháy nhẹ, như một lời mời ẩn."
  },
  AvgDialog_131224_Content_70 = {
    Text = "Còn về liên kết giữa ngài và Kadath… đó là một cái bẫy nguy hiểm, %player%."
  },
  AvgDialog_131224_Content_71 = {Text = "Bẫy?"},
  AvgDialog_131224_Content_72 = {
    Text = "Một đứa trẻ sinh ra vì tôi đã gây ra phiền phức không đáng có cho ngài, vạn phần xin lỗi. Chuyện này bắt nguồn từ tôi, và tôi cũng đang cố hết sức để bù đắp sai lầm này."
  },
  AvgDialog_131224_Content_73 = {
    Text = "Tôi không nghe hiểu……"
  },
  AvgDialog_131224_Content_74 = {
    Text = "Đây là một câu chuyện có liên quan đến số phận, hơi dài một chút. Câu chuyện luôn dễ hiểu hơn so với việc chỉ đơn thuần trình bày."
  },
  AvgDialog_131224_Content_75 = {
    Text = "Xin mời ngồi, Người Giữ Bí Mật {Male=先生,Female=小姐}. Vở kịch mới này vừa mới được công diễn không lâu trước đây."
  },
  AvgDialog_131224_Content_76 = {
    Text = "Arachne nhẹ nhàng vẫy tay. Màn rèm được kéo ra, một sân khấu trống rỗng đang lơ lửng xuất hiện trước mặt bạn."
  },
  AvgDialog_131224_Content_77 = {
    Text = "Dường như trên sân khấu có một chiếc gương mờ ảo, phản chiếu hình dáng của các bạn."
  },
  AvgDialog_131224_Content_78 = {
    Text = "Nhạc nổi lên. Vận mệnh bị ruồng bỏ, lên sân khấu."
  },
  AvgDialog_131224_Content_79 = {
    Text = "Rất nhanh, hình bóng của bạn trên mặt gương biến mất, hình dáng của Arachne biến thành một con rối."
  },
  AvgDialog_131224_Content_8 = {
    Text = "Bạn do dự một chút, rồi bước vào trong cửa."
  },
  AvgDialog_131224_Content_80 = {
    Text = "Cô ấy vẫn ngồi trên ghế, nhưng sự ôn hòa và điềm tĩnh đã biến mất."
  },
  AvgDialog_131224_Content_81 = {
    Text = "Cô ấy lắc lư ly rượu đầy máu tươi trong tay, như đang ngồi trên một ngai vàng tàn nhẫn. Một ánh mắt ngây thơ, tàn nhẫn lướt qua hàng ghế khán giả."
  },
  AvgDialog_131224_Content_82 = {
    Text = "Phía sau cô ấy, bốn cặp chi nhện sắc nhọn ung dung đung đưa, lướt sát qua mặt những tùy tùng bên cạnh."
  },
  AvgDialog_131224_Content_83 = {
    Text = "À, không khí tự do……"
  },
  AvgDialog_131224_Content_84 = {
    Text = "Chúng ta đã bị giam giữ trong vực thẳm đó bao nhiêu năm rồi, phục vụ thân yêu của tôi?"
  },
  AvgDialog_131224_Content_85 = {
    Text = "Tôi không biết, thưa chủ nhân."
  },
  AvgDialog_131224_Content_86 = {
    Text = "Tên, thời gian, cảm xúc… Tôi đã quên hết mọi thứ… Tôi chỉ nhớ ngài, chủ nhân của tôi, tôn kính Nephreya."
  },
  AvgDialog_131224_Content_87 = {
    Text = "Tôi chỉ nhớ, ngài đã nói với tôi, sẽ đưa chúng ta rời khỏi đây, sẽ dẫn chúng ta, vung lưỡi dao sắc của sự trả thù với số phận."
  },
  AvgDialog_131224_Content_88 = {
    Text = "Tôi nhớ, đứa trẻ. Tôi đã hứa với các bạn chín mươi nghìn lần, bây giờ, hãy để tôi nói với bạn lần thứ chín mươi nghìn lẻ một."
  },
  AvgDialog_131224_Content_89 = {
    Text = "Mỗi khoảnh khắc, chỉ có một số phận tồn tại. Người thực hiện số phận sẽ cắt bỏ vô số số phận sai lầm, chỉ để lại số phận đúng duy nhất."
  },
  AvgDialog_131224_Content_90 = {
    Text = "Chúng ta, chính là số phận bị bỏ rơi. Ha ha ha ha... Người phục vụ thân yêu của tôi, ngươi là một sai lầm, giống như tôi vậy."
  },
  AvgDialog_131224_Content_91 = {
    Text = "Trong tiềm thức của vũ trụ này, trong vực sâu hư vô không tồn tại, chúng ta bị lưu đày, bị giam cầm. Chúng ta lang thang ở đây, quên lãng, vĩnh viễn. Thời gian chịu án của chúng ta, dài hơn cả chính thời gian..."
  },
  AvgDialog_131224_Content_92 = {
    Text = "Người phụ nữ tên Nephreya đứng dậy từ ghế, cúi người, mỉm cười nhìn Arachne ở hàng ghế khán giả."
  },
  AvgDialog_131224_Content_93 = {
    Text = "Nhưng, tại sao, nữ thần số phận? Tại sao, những người bị loại bỏ, lại phải là chúng ta?"
  },
  AvgDialog_131224_Content_94 = {
    Text = "Vô số vũ trụ, Đấng Tối Cao duy nhất, cuối cùng đã tỉnh dậy trong một khoảnh khắc. Ngài lại một lần nữa rơi vào giấc ngủ, nhưng nhà tù của ý thức Ngài, vực thẳm vĩnh hằng, cuối cùng đã mở ra cho chúng ta."
  },
  AvgDialog_131224_Content_95 = {
    Text = "Tôi vốn đã quên lãng, đã biến mất. Nhưng tại sao, tại sao lại ép buộc tôi nhớ lại tất cả những nỗi đau này?"
  },
  AvgDialog_131224_Content_96 = {
    Text = "Nephreya uống cạn chất lỏng trong ly, thở dài một tiếng mãn nguyện. Dòng nước đỏ tươi chảy dọc theo đôi môi nhợt nhạt của cô, nhỏ giọt xuống chiếc xa kéo sợi tối tăm trong tay."
  },
  AvgDialog_131224_Content_97 = {
    Text = "Có lẽ, đây chính là sự sắp đặt của số phận… số phận mà ngay cả bạn cũng không thể kiểm soát."
  },
  AvgDialog_131224_Content_98 = {
    Text = "Khởi nguyên của thần linh lại chìm vào giấc ngủ, nhưng mảnh vụn của Ngài đã đến nơi chúng ta cư trú."
  },
  AvgDialog_131224_Content_99 = {
    Text = "Tôi không có khả năng điều khiển số phận như bạn. Tôi chỉ là người sửa đổi số phận, là kẻ hành hình đến từ hư vô. Những tội lỗi trong dòng chảy của số phận sẽ do tôi thực hiện hình phạt cho khởi nguyên."
  },
  AvgDialog_131225_Content_1 = {
    Text = "Ảo Ảnh Ngày Xưa"
  },
  AvgDialog_131225_Content_10 = {
    Text = "Khác hẳn với không gian trống rỗng mà bạn tưởng tượng dựa trên kinh nghiệm, bên trong biệt thự này lại tỏ ra vô cùng chật chội, Nefreya dường như đã quyết tâm viết bừa trong kịch bản của cô ấy."
  },
  AvgDialog_131225_Content_11 = {
    Text = "Những chiếc tủ và kệ chứa đồ nối dài không dứt, đứng im lặng và chật chội, các loại lọ đựng đủ kích cỡ nhét đầy từng chỗ trống của chúng."
  },
  AvgDialog_131225_Content_12 = {
    Text = "Gương bạc, trứng nhện, giày múa của côn trùng lạ… Những vật thể đủ loại ngâm trong chất lỏng không rõ, giống như những cái miệng đang im lặng kêu gào."
  },
  AvgDialog_131225_Content_13 = {
    Text = "Bạn đến trước những chiếc lọ đủ hình dáng, nhẹ nhàng đọc những dòng chữ trên nhãn."
  },
  AvgDialog_131225_Content_14 = {
    Text = "Hai tuổi, nói ra câu đầu tiên trong cuộc đời. Không gọi tên người nhà của mình, mà là tạm biệt người đầy tớ đã chăm sóc gia đình mình qua nhiều thế hệ."
  },
  AvgDialog_131225_Content_15 = {
    Text = "Tối hôm đó, lão đầy tớ đã qua đời vì bệnh tim. Cầm di vật của ông ta, khóc bên ngoài cửa phòng của lão đầy tớ…"
  },
  AvgDialog_131225_Content_16 = {
    Text = "Đó là một chiếc huy hiệu gia đình cũ."
  },
  AvgDialog_131225_Content_17 = {
    Text = "Năm tuổi, trong tiếng hô vang khiến người ta đỏ mặt của các vị khách tại bữa tiệc tối, tôi ngại ngùng nhảy điệu waltz theo kiểu của mẹ…"
  },
  AvgDialog_131225_Content_18 = {
    Text = "Đó là một đôi giày múa đỏ tươi."
  },
  AvgDialog_131225_Content_19 = {
    Text = "Bảy tuổi, nhận được món quà sinh nhật từ cha, một cái bánh xe sợi có tên là\"Môi Lai\"."
  },
  AvgDialog_131225_Content_2 = {
    Text = "Ngõ Brick, bạn còn nhớ cảnh tượng khi điều tra ở khu vực này của Lentiennam không."
  },
  AvgDialog_131225_Content_20 = {
    Text = "Trong sợi chỉ của bánh xe, thấy bóng dáng của số phận……"
  },
  AvgDialog_131225_Content_21 = {
    Text = "Đó là một nắm chỉ bị đứt gãy."
  },
  AvgDialog_131225_Content_22 = {
    Text = "Lần đầu tiên đến nhà hát opera với cha mẹ…… lần đầu tiên kết bạn thân…… lần đầu tiên chôn cất chú chó yêu quý của mình……"
  },
  AvgDialog_131225_Content_23 = {
    Text = "Chữ trên nhãn của những cái bình lần lượt hiện lên trong mắt bạn. Mỗi khi bạn chạm vào chúng, một ký ức mờ ảo lại hiện lên trong tâm trí bạn. Bạn quay đầu lại, nghi hoặc nhìn Arachne."
  },
  AvgDialog_131225_Content_24 = {
    Text = "Những cái này…… đều là ký ức của bạn sao?"
  },
  AvgDialog_131225_Content_25 = {
    Text = "Đó là ký ức của tôi trong quá khứ. Từ rất lâu trước đây, chúng thuộc về vị gọi là\"Ký ức\" của bí mật."
  },
  AvgDialog_131225_Content_26 = {
    Text = "Đây đều là những kỷ niệm quý giá…… Tại sao lại phải bỏ chúng lên một cái bí ẩn?"
  },
  AvgDialog_131225_Content_27 = {
    Text = "Mỗi người trong cuộc đời đều cần phải đưa ra một số lựa chọn. Mỗi lựa chọn đều có cái giá của nó."
  },
  AvgDialog_131225_Content_28 = {
    Text = "Để đến được đích đến ấy, chúng ta luôn cần phải từ bỏ một số thứ. Ta nghĩ, ngài hẳn rất hiểu điều này, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131225_Content_29 = {
    Text = "Arachne không trả lời trực tiếp câu hỏi của bạn, cô ấy nhìn vào những cái tủ, nhẹ nhàng vuốt ve những chiếc bình đầy chất lỏng."
  },
  AvgDialog_131225_Content_3 = {
    Text = "Bẩn thỉu, hỗn loạn, không khí tràn ngập mùi khói than và mùi cống rãnh, những mùi này đã đồng hành cùng Mason và Jenkin trong suốt thời gian sống của họ."
  },
  AvgDialog_131225_Content_30 = {
    Text = "Động tác của cô ấy rất nhẹ nhàng, rất chậm chạp, giống như một người già sắp qua đời, vuốt ve những món đồ chơi quý giá từ thời thơ ấu."
  },
  AvgDialog_131225_Content_31 = {
    Text = "Lấy những ký ức này ra khỏi cơ thể của bí ẩn, hiện hình dưới dạng như vậy. Đây là cảnh quan mà bạn đã chuẩn bị cho tôi, Nefreya."
  },
  AvgDialog_131225_Content_32 = {
    Text = "Bạn muốn nói với tôi, tôi đã hiểu rồi…"
  },
  AvgDialog_131225_Content_33 = {
    Text = "<Big:<Shake:Aaaaah！——>>"
  },
  AvgDialog_131225_Content_34 = {
    Text = "Tiếng thét thê lương vang vọng trong phòng, những chiếc bình chứa đầy ký ức nhẹ nhàng rung chuyển, như một nhóm khán giả đang cười thầm không tiếng."
  },
  AvgDialog_131225_Content_35 = {
    Text = "！！Trong phòng ở phía sau hành lang"
  },
  AvgDialog_131225_Content_36 = {
    Text = "Rầm——"
  },
  AvgDialog_131225_Content_37 = {
    Text = "Bạn chạy nhanh qua hành lang, đâm mở cánh cửa phòng……"
  },
  AvgDialog_131225_Content_38 = {
    Text = "Bạn đang ở trong cơn bão."
  },
  AvgDialog_131225_Content_39 = {
    Text = "Không có sấm, không có gió, cũng không có mưa. Chỉ có những con nhện dày đặc, từ trần nhà trống trải rơi xuống như mưa bão."
  },
  AvgDialog_131225_Content_4 = {
    Text = "Và lúc này, một biệt thự lấp lánh vàng bạc đột ngột xuất hiện giữa hai căn nhà tạm, như một chiếc hộp trang sức được đặt giữa đống rác."
  },
  AvgDialog_131225_Content_40 = {
    Text = "Động vật chân đốt màu đen dính đặc hội tụ thành dòng triều dâng cao, tiêu thụ tất cả các vật thể và ánh sáng trong nhà."
  },
  AvgDialog_131225_Content_41 = {
    Text = "Ở trung tâm của cơn bão tối tăm, những con nhện điên cuồng leo trèo, gặm nhấm tập hợp thành một hình dáng người mà chỉ vừa đủ để nhận ra. Ở nơi mà dòng nước nhện chưa bao phủ, hiện ra một khuôn mặt của người già mà bạn đã từng thấy."
  },
  AvgDialog_131225_Content_42 = {
    Text = "Arachne.....Thiếu nữ....."
  },
  AvgDialog_131225_Content_43 = {
    Text = "Nhanh… trốn đi!…"
  },
  AvgDialog_131225_Content_44 = {
    Text = "Suỵt... ở đây không có câu thoại của bạn, ngài \"Tốt bụng\"."
  },
  AvgDialog_131225_Content_45 = {
    Text = "Sự báo thù của số phận, màn thứ hai, cảnh thứ hai. Tôi đặt tên cho nó là\"Cơn bão\"."
  },
  AvgDialog_131225_Content_46 = {
    Text = "Hãy tắm mình trong cơn mưa tuyệt diệu này, khán giả thân yêu của tôi."
  },
  AvgDialog_131225_Content_47 = {
    Text = "Nước đọng nổi lên sóng, những con nhện đen nghe thấy lệnh tối cao, tràn vào mọi góc của phòng."
  },
  AvgDialog_131225_Content_48 = {
    Text = "Trong tiếng tán thưởng của Nephreya, lính canh, tùy tùng cùng những sinh vật ghê tởm hợp thành từ nhện, ào ạt xông về phía các ngươi——"
  },
  AvgDialog_131225_Content_5 = {
    Text = "Những người vô gia cư và những công nhân mệt mỏi đi qua trước chiếc hộp sang trọng này, không ai dành cho nó một ánh mắt thừa thãi, dường như nó đã tồn tại ở đây từ khi họ sinh ra."
  },
  AvgDialog_131225_Content_6 = {
    Text = "Thật sự ngay cả số phận của thành phố này cũng bị ảnh hưởng... sức mạnh của Nephreya, đúng là đang gia tăng."
  },
  AvgDialog_131225_Content_7 = {
    Text = "Bạn cảnh giác tiến lên phía trước, ban đầu định gõ cửa, nhưng khi bạn vừa đặt tay lên cửa, cửa đã im lặng mở ra."
  },
  AvgDialog_131225_Content_8 = {
    Text = "Hình như, chủ nhân chu đáo của chúng ta đã để lại cửa cho chúng ta."
  },
  AvgDialog_131225_Content_9 = {
    Text = "Đây là…"
  },
  AvgDialog_131226_Content_1 = {
    Text = "Giết…… đã giết người!"
  },
  AvgDialog_131226_Content_10 = {
    Text = "Những gì vừa xảy ra tôi đều thấy hết. Cậu không đi qua lối đi đó, %player%. Đây, không phải nơi chúng ta cần quay về."
  },
  AvgDialog_131226_Content_11 = {
    Text = "Tôi cũng thấy lạ... rỗng rỗng và Misaque, những thiên tai đó, họ lại hoàn toàn không biết."
  },
  AvgDialog_131226_Content_12 = {
    Text = "Nhưng hình dáng của thành phố này, giống hệt như trước khi thảm họa xảy ra, và như trong ký ức của tôi. Có lẽ, bây giờ chúng ta hãy quay lại trường học xem sao, biết đâu có thể phát hiện ra điều gì……"
  },
  AvgDialog_131226_Content_13 = {
    Text = "Tôi vừa quay lại từ đó. Ở đây không có Misage, %player%."
  },
  AvgDialog_131226_Content_14 = {
    Text = "Không có…?"
  },
  AvgDialog_131226_Content_15 = {
    Text = "Bản đồ thế giới trong cửa hàng là hình dạng mà tôi chưa từng thấy, tất cả các năm được đánh dấu trên lịch cũng hoàn toàn khác với năm Aluvi."
  },
  AvgDialog_131226_Content_16 = {
    Text = "Điều kỳ quái nhất là… thành phố này không có điểm kết thúc."
  },
  AvgDialog_131226_Content_17 = {
    Text = "Không… có điểm kết thúc?"
  },
  AvgDialog_131226_Content_18 = {
    Text = "Tiếp tục đi về phía bắc từ hướng Misaque, bạn sẽ có thể rời khỏi phạm vi của Lentiennam."
  },
  AvgDialog_131226_Content_19 = {
    Text = "Tôi cũng đã gặp phải những cuộc tấn công của những con nhện trên đường, để tránh chúng, tôi đã đi dọc theo con đường đó, nhưng cuối cùng... tôi đã trở lại gần vị trí của bạn, phía nam của Lentiennam."
  },
  AvgDialog_131226_Content_2 = {
    Text = "Đám đông hét lên và bỏ chạy. Không biết từ lúc nào, mái tóc vàng bắt mắt ấy đã xuất hiện bên cạnh bạn."
  },
  AvgDialog_131226_Content_20 = {
    Text = "Đây không phải là Lentiennam, đây không phải là Cađas."
  },
  AvgDialog_131226_Content_21 = {
    Text = "Có vẻ như ký ức của tôi không sai... cái đường dẫn đó, thực sự đã đóng lại trước khi tôi vào..."
  },
  AvgDialog_131226_Content_22 = {
    Text = "Bạn nhìn ra những cảnh vật quen thuộc bên ngoài lối đi, thở dài đầy thất vọng."
  },
  AvgDialog_131226_Content_23 = {
    Text = "Một nơi giống hệt Londinium, một thành phố không có biên giới, những con nhện đen không biết xuất hiện từ đâu... còn có chủ nhân mà chúng nhắc đến..."
  },
  AvgDialog_131226_Content_24 = {
    Text = "Hiện tại vẫn chưa thể khẳng định, nhưng tôi nghĩ, việc lối đi đóng lại và chúng ta xuất hiện ở đây, chắc chắn không phải trùng hợp. Có người đã cố tình sắp đặt tất cả — chủ nhân của những con nhện đó."
  },
  AvgDialog_131226_Content_25 = {
    Text = "Bây giờ chúng ta vẫn chưa biết gì cả, cần thu thập tình báo trước đã……"
  },
  AvgDialog_131226_Content_26 = {
    Text = "Hai người……"
  },
  AvgDialog_131226_Content_27 = {Text = "Ai?!"},
  AvgDialog_131226_Content_28 = {
    Text = "Ánh sáng bạc lấp lánh trong lòng bàn tay cơ khí của William, như một lưỡi dao sắc luôn sẵn sàng xuất hiện."
  },
  AvgDialog_131226_Content_29 = {
    Text = "Trong ánh sáng bạc nguy hiểm đó, bạn thấy người già vừa định đưa cho bạn thức ăn."
  },
  AvgDialog_131226_Content_3 = {
    Text = "William, anh trai… bạn là lúc nào… chuyện gì vậy?"
  },
  AvgDialog_131226_Content_30 = {
    Text = "Là…là tôi…"
  },
  AvgDialog_131226_Content_31 = {
    Text = "Đây…… là của bạn sao?"
  },
  AvgDialog_131226_Content_32 = {
    Text = "Người già mở bàn tay ra. Chiếc huy hiệu Misaque dùng để liên lạc, nằm yên tĩnh trong lòng bàn tay thô ráp của ông."
  },
  AvgDialog_131226_Content_33 = {
    Text = "Á! Là thứ vừa nãy trong trận chiến rơi xuống……"
  },
  AvgDialog_131226_Content_34 = {
    Text = "Thứ này rất quan trọng với tôi... Cảm ơn rất nhiều!"
  },
  AvgDialog_131226_Content_35 = {
    Text = "Trong ánh mắt cảnh giác của William, bạn đã lấy lại huy hiệu, cẩn thận giữ gìn."
  },
  AvgDialog_131226_Content_36 = {
    Text = "Người già… những chuyện vừa rồi, ngài không sợ sao?"
  },
  AvgDialog_131226_Content_37 = {
    Text = "Đó là sợ hãi... Tôi đã sống ở đây cả đời, đâu có thấy những thứ này..."
  },
  AvgDialog_131226_Content_38 = {
    Text = "Nhưng tôi thấy thứ đó rất quan trọng với bạn, bạn vừa mới đến đây, nếu bị mất có lẽ bạn cũng không biết tìm ở đâu, nên tôi đã mang đến cho bạn."
  },
  AvgDialog_131226_Content_39 = {
    Text = "Rất cảm ơn bạn rất nhiều……"
  },
  AvgDialog_131226_Content_4 = {
    Text = "Đây không phải là nơi để nói chuyện. Đi thôi"
  },
  AvgDialog_131226_Content_40 = {
    Text = "Chúng tôi vừa đến đây, có nhiều điều không biết, có một số việc, có thể hỏi ngài một chút không?"
  },
  AvgDialog_131226_Content_41 = {
    Text = "Tôi thì không ngại trò chuyện thêm với hai người trẻ, nhưng những gì tôi biết thực sự có hạn, e rằng không giúp được gì nhiều."
  },
  AvgDialog_131226_Content_42 = {
    Text = "Có lẽ, bây giờ hai người cần tìm một nơi đông đúc hơn."
  },
  AvgDialog_131226_Content_43 = {
    Text = "Được rồi, đồ đã gửi đến, tôi sẽ trở về trước."
  },
  AvgDialog_131226_Content_44 = {
    Text = "Người già vẫy tay, không thèm để ý đến lời giữ chân của các bạn, rời khỏi con hẻm."
  },
  AvgDialog_131226_Content_45 = {
    Text = "Người già này trông không có ác ý gì. Ông ấy nói đúng, chúng ta cần nhanh chóng tìm một nơi có thông tin lưu thông hơn."
  },
  AvgDialog_131226_Content_46 = {
    Text = "Tôi nghĩ ra một chỗ rồi!"
  },
  AvgDialog_131226_Content_47 = {
    Text = "Nếu thành phố này giống hệt như Lentiennam, thì nơi đó chắc chắn sẽ là phù hợp nhất."
  },
  AvgDialog_131226_Content_48 = {
    Text = "Khi các bạn rời đi, một con nhện màu tím nhạt ẩn nấp trong vùng mù của tầm nhìn ngoại vi, bò theo mạng nhện chui vào khe tường, biến mất không dấu vết."
  },
  AvgDialog_131226_Content_5 = {
    Text = "William kéo bạn, chạy về hướng ngược lại với đám đông."
  },
  AvgDialog_131226_Content_7 = {
    Text = "Gần đây chắc không còn ai nữa."
  },
  AvgDialog_131226_Content_8 = {
    Text = "Chuyện gì đang xảy ra vậy? Tại sao Londinium lại biến thành thế này..."
  },
  AvgDialog_131226_Content_9 = {
    Text = "Những con nhện tấn công chúng ta, còn người đó... dường như có liên quan gì đó với người đã gặp trên tàu Nhạc Viên trước đây?"
  },
  AvgDialog_131227_Content_1 = {
    Text = "Tà Vy! Tôi……"
  },
  AvgDialog_131227_Content_2 = {
    Text = "Tôi hiểu, Người Giữ Gìn."
  },
  AvgDialog_131227_Content_3 = {
    Text = "Số phận của bạn đã bị thay đổi. Bạn không thể dừng lại, và cũng không nên dừng lại."
  },
  AvgDialog_131227_Content_4 = {
    Text = "Arachne không thể tuyên bố số phận của tương lai… xin hãy cho tôi biết, tôi nên làm gì…"
  },
  AvgDialog_131227_Content_5 = {
    Text = "Tôi không thể nói rõ với bạn về những thứ ở sau cửa. Trong vấn đề này, có người phù hợp hơn tôi để giúp bạn."
  },
  AvgDialog_131227_Content_6 = {
    Text = "Tiến lên nào, Người Giữ Gìn. Số phận của bạn, cần phải do chính bạn nhìn rõ."
  },
  AvgDialog_131228_Content_1 = {
    Text = "Ừm…… anh hùng và kẻ hề, con rối của số phận…… một vở kịch hay."
  },
  AvgDialog_131228_Content_2 = {
    Text = "ArachneNói cho tôi biết, chìa khóa để mở khóa là\"Hạnh phúc\"... Đây là lĩnh vực của bạn, N."
  },
  AvgDialog_131228_Content_3 = {
    Text = "Shhh! Đừng vội vàng như vậy. Phá hoại một vở kịch hay, là tội lỗi không thể tha thứ nhất trong vũ trụ này."
  },
  AvgDialog_131228_Content_4 = {
    Text = "Đến đây đi, Người Giữ Gìn. Lâu không gặp, để tôi xem, bạn có những nhận thức mới về hạnh phúc không?"
  },
  AvgDialog_131229_Content_10 = {
    Text = "Đáp lại tôi... Liz!..."
  },
  AvgDialog_131229_Content_11 = {
    Text = "Số phận của cô ấy đã đứt đoạn…… Sinh lực của cô ấy đã kết thúc."
  },
  AvgDialog_131229_Content_12 = {
    Text = "<Shake:Không……chúng ta không thể để Nephreya đắc ý như vậy>, nàng ta phải trả giá cho sự ngang ngược của mình！"
  },
  AvgDialog_131229_Content_13 = {
    Text = "Cái giá sắp phải trả, số phận đã chuẩn bị sẵn cho cô ấy. Manh mối sẽ không dừng lại ở đây."
  },
  AvgDialog_131229_Content_14 = {
    Text = "Nhưng, bạn vừa nói Liz bây giờ đã……"
  },
  AvgDialog_131229_Content_15 = {
    Text = "Cái chết là một phần của định mệnh. Đây là sân khấu của ta, Người Giữ Bí Mật {Male=先生,Female=小姐}. Mọi định mệnh đều là sợi tơ trong tay ta. Hướng đi của chúng, <color=#8C7E96>không do người khác dệt nên</color>."
  },
  AvgDialog_131229_Content_16 = {Text = "!!!"},
  AvgDialog_131229_Content_17 = {
    Text = "<Shake:Khoan đã, ý ngươi là……>"
  },
  AvgDialog_131229_Content_18 = {
    Text = "Gương mặt của Arachne không buồn không vui. Cô ấy đi về phía người thông báo đã bị Nefreya ký sinh tạm thời. Ánh sáng mờ của hoàng hôn phác thảo bóng dáng mờ nhạt, ổn định của cô, như chính số phận."
  },
  AvgDialog_131229_Content_19 = {
    Text = "Hahaha… Arachne, bạn vẫn kiêu ngạo như vậy, như vậy! Hahaha…"
  },
  AvgDialog_131229_Content_2 = {
    Text = "Kẻ thù xung quanh đã ngã xuống, nhưng cuộc tấn công của bạn vẫn chưa dừng lại."
  },
  AvgDialog_131229_Content_20 = {
    Text = "Nefreya dường như đã thấy được một điều gì đó hài hước vô cùng, cười đến mức lăn lộn trên đất."
  },
  AvgDialog_131229_Content_21 = {
    Text = "Ô nhiễm số phận của Liz, để cô ấyđón chào cái chết… Mỗi một việc bạn làm, mạng lưới số phận đều sẽ ghi nhớ."
  },
  AvgDialog_131229_Content_22 = {
    Text = "Số phận sai lầm sẽ được sửa chữa. Trước số phận của bạn, tự nhiên sẽ có cái giá đang chờ đợi bạn."
  },
  AvgDialog_131229_Content_23 = {
    Text = "Arachne đưa tay ra, nhẹ nhàng vén tóc trên đỉnh đầu của thi thể này. Cái vòng quay trong tay nhẹ nhàng xoay, mọi thứ xung quanh bạn dường như đang biến dạng và tái tổ hợp trong sự xoay chuyển này…"
  },
  AvgDialog_131229_Content_24 = {
    Text = "Sợi chỉ của số phận, lắng nghe tiếng gọi của mạng lưới. Dọc theo con đường duy nhất đó, hãy trở lại sân khấu……"
  },
  AvgDialog_131229_Content_25 = {
    Text = "Cơ thể của cô ấy…… đã biến mất?"
  },
  AvgDialog_131229_Content_26 = {
    Text = "Cùng với sự khẽ chạm của ngón tay Arachne, xác chết của Liz trên sân khấu như đang trải qua một cuộc đốt cháy không tiếng, hóa thành tàn tro tan biến trong không trung."
  },
  AvgDialog_131229_Content_27 = {
    Text = "Dưới những bụi than rơi rụng, một thân thể mới hiện ra trước mắt bạn."
  },
  AvgDialog_131229_Content_28 = {
    Text = "Đây là……người giới thiệu đó sao?"
  },
  AvgDialog_131229_Content_29 = {
    Text = "Mũi nhọn xuyên qua cơ thể của người thông báo, treo cô ấy lên phía trên sân khấu, tất cả các động tác, biên độ, đều giống hệt như Liz."
  },
  AvgDialog_131229_Content_3 = {
    Text = "Bạn gào thét, điên cuồng đạp nát khuôn mặt đang mỉm cười của người thông báo lên sàn gỗ của sân khấu."
  },
  AvgDialog_131229_Content_30 = {
    Text = "Người dẫn chương trình để lại nụ cười dữ tợn, không còn bất kỳ âm thanh nào nữa."
  },
  AvgDialog_131229_Content_31 = {
    Text = "Arachne, bạn......"
  },
  AvgDialog_131229_Content_32 = {
    Text = "Xin lỗi, tôi đến trễ, tôi vừa mới……À"
  },
  AvgDialog_131229_Content_33 = {
    Text = "Bóng dáng quen thuộc nâng màn che bước lên sân khấu. Ánh mắt của cô ấy lướt qua các bạn, dừng lại ở xác chết treo lơ lửng trên không."
  },
  AvgDialog_131229_Content_34 = {
    Text = "Cử động của cô ấy…… thật đẹp……"
  },
  AvgDialog_131229_Content_35 = {
    Text = "Liz dường như quên đi những xác chết nằm rải rác và khán giả đứng xung quanh. Cô ấy bước vào trung tâm sân khấu, tay lướt qua phần chân của xác chết treo lơ lửng, như thể đang ngẫm nghĩ về đường cong duyên dáng đó."
  },
  AvgDialog_131229_Content_36 = {
    Text = "Arachne, bạn... đã đổi số phận của người thông báo và Liz?"
  },
  AvgDialog_131229_Content_37 = {
    Text = "Nhưng bạn đã nói, sự tiêu hao như vậy là khó có thể chịu đựng được……"
  },
  AvgDialog_131229_Content_38 = {
    Text = "Tiêu thụ không liên quan đến sự lựa chọn. Trong số phận của tôi, đây cũng là cái giá mà tôi phải trả."
  },
  AvgDialog_131229_Content_39 = {
    Text = "Đi đi, %player%, đừng để tiểu thư Liz phải chờ lâu."
  },
  AvgDialog_131229_Content_4 = {
    Text = "Đúng vậy… chính là như vậy… giận dữ, phát tiết! Thật là một biểu cảm tuyệt vời…"
  },
  AvgDialog_131229_Content_40 = {
    Text = "Đôi mắt và hơi thở hư ảo. Vạt váy mang theo lửa xanh nhẹ nhàng bay theo gió. Mỗi cử động của đầu ngón tay đều như một điệu múa được dàn dựng tỉ mỉ."
  },
  AvgDialog_131229_Content_41 = {
    Text = "Thân hình ấy trùng khớp với bóng dáng đầy máu me lao về phía ngươi lúc nãy. Liz sống động đứng trước mặt ngươi, sự dệt tinh xảo của định mệnh không để lại chút dấu vết nào trong cuộc đời nàng."
  },
  AvgDialog_131229_Content_42 = {
    Text = "Một lúc lâu, Liz từ sự ngưỡng mộ thi thể trở lại hiện thực, quay đầu nhìn bạn đang đứng bên cạnh."
  },
  AvgDialog_131229_Content_43 = {
    Text = "Hôm nay tôi đã ngủ gục ở nhà đến chiều, đã bỏ lỡ buổi biểu diễn. Đây là tình huống chưa từng xảy ra…"
  },
  AvgDialog_131229_Content_44 = {
    Text = "Có vẻ như tôi đã bỏ lỡ một số chuyện rất quan trọng?"
  },
  AvgDialog_131229_Content_45 = {
    Text = "Đôi mắt của Liz lướt qua những xác chết và vết máu mà cô ấy đã bỏ qua trên mặt đất."
  },
  AvgDialog_131229_Content_46 = {
    Text = "Không, bạn không bỏ lỡ điều gì cả, Liz."
  },
  AvgDialog_131229_Content_47 = {
    Text = "Bạn... có ổn không? Thân thể có chỗ nào không thoải mái không?"
  },
  AvgDialog_131229_Content_48 = {
    Text = "Cũng không hẳn……Vị {Male=先生,Female=小姐} này, chúng ta quen nhau sao? Tôi dường như cảm nhận được, trên người ngài có thứ gì đó rất quen thuộc với tôi……"
  },
  AvgDialog_131229_Content_49 = {
    Text = "Có lẽ là vì, với tư cách là người theo dõi bạn, tôi đã xem nhiều buổi biểu diễn của bạn."
  },
  AvgDialog_131229_Content_5 = {
    Text = "Gương mặt như bùn lầy mỉm cười, âm thanh yếu ớt thoát ra từ cổ họng vỡ vụn của cô ấy."
  },
  AvgDialog_131229_Content_50 = {
    Text = "Bạn mỉm cười nhìn cô ấy. Cảnh sân khấu này có những câu chuyện riêng của nó, bạn không có ý định kể cho cô ấy nghe về những điều đã xa xưa."
  },
  AvgDialog_131229_Content_51 = {
    Text = "Chúng ta đến đây vì \"lương thiện\"."
  },
  AvgDialog_131229_Content_52 = {
    Text = "Cuối cùng thì bạn của bà Sorrel cũng đã đến, tôi còn lo lắng nếu mình đi biểu diễn thì sẽ làm chậm trễ vị \"đại nhân\" \"tốt bụng\" đó... Xin hai vị theo tôi, chỗ ở của tôi ở không xa đoàn múa."
  },
  AvgDialog_131229_Content_53 = {
    Text = "Liz lưu luyến liếc nhìn xác chết trên tường, rồi dẫn các bạn đi về phía sau bức màn."
  },
  AvgDialog_131229_Content_55 = {
    Text = "Vậy nên... đáng lẽ xác của tôi phải được treo trên sân khấu..."
  },
  AvgDialog_131229_Content_56 = {
    Text = "Không kịp thương tiếc cho những bạn nhảy đã khuất, cũng quên không bày tỏ lòng cảm ơn với người đã giúp mình sống lại."
  },
  AvgDialog_131229_Content_57 = {
    Text = "Trong câu chuyện của các bạn, đôi mắt của Liz nhấp nháy như những ngọn lửa nhảy múa. Cô ấy đưa tay ra, tạo dáng giống như một xác chết."
  },
  AvgDialog_131229_Content_58 = {
    Text = "Bức tranh đó, đẹp không?"
  },
  AvgDialog_131229_Content_59 = {
    Text = "Vẻ đẹp tuyệt mỹ trên thế gian chỉ hiện hữu trong hai khoảnh khắc, một là sự ra đời, một là cái chết. Đó là một bức tranh vô song, thưa cô Liz."
  },
  AvgDialog_131229_Content_6 = {
    Text = "Nephreya không ở đây, đây chỉ là ảo ảnh nàng ta để lại. Đừng để cơn phẫn nộ che mờ lý trí, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131229_Content_60 = {
    Text = "Cảm ơn bạn, quý bà Arachne. Bạn là người dệt nên số phận, vì vậy tôi nghĩ, bạn chắc chắn thường xuyên được bao quanh bởi những điều tuyệt đẹp này. Thật là… đáng ngưỡng mộ."
  },
  AvgDialog_131229_Content_61 = {
    Text = "Quá nhiều bảo vật sẽ trở thành một hình phạt."
  },
  AvgDialog_131229_Content_62 = {
    Text = "Nếu đây là hình phạt của bạn, thì ân thưởng bạn mong muốn là gì?"
  },
  AvgDialog_131229_Content_63 = {
    Text = "Liz không để ý đến sự dừng lại ngắn ngủi của Arachne, mở cửa phòng khách trong sân."
  },
  AvgDialog_131229_Content_64 = {
    Text = "Đây chính là nơi ở tạm thời của ông \"Thiện Lương\". Ông \"Thiện Lương\", bạn của ông đã đến đón ông."
  },
  AvgDialog_131229_Content_65 = {
    Text = "\"Lòng tốt\" ngài?"
  },
  AvgDialog_131229_Content_66 = {
    Text = "Phòng đơn giản, không có bất kỳ đồ đạc nào không thuộc về đây, không có bất kỳ ai không thuộc về đây."
  },
  AvgDialog_131229_Content_67 = {
    Text = "Trong căn phòng trống rỗng, một mảnh giấy giản đơn nằm yên tĩnh trên giá sách."
  },
  AvgDialog_131229_Content_68 = {
    Text = "\"Xin lỗi vì đã ra đi mà không nói lời từ biệt. Bà Sorrel lo lắng rằng bà sẽ bị liên lụy, vì vậy đã có kế hoạch mới, tôi sẽ đến biệt thự kỷ niệm để trốn tránh.\""
  },
  AvgDialog_131229_Content_69 = {
    Text = "\"Về sự chăm sóc của ngài, tôi vô cùng biết ơn. Tôi sẽ nghiêm túc đền bù ân huệ này cho ngài.\""
  },
  AvgDialog_131229_Content_7 = {
    Text = "<Shake:Hu……hu……>"
  },
  AvgDialog_131229_Content_70 = {
    Text = "Bà Sorrel nếu thay đổi kế hoạch nhất định sẽ thông báo cho chúng ta…"
  },
  AvgDialog_131229_Content_71 = {
    Text = "Bạn nhìn về phía Arachne với đôi mắt không có chút dao động nào. Trong nụ cười bình thản dường như sẽ không bao giờ biến mất đó, bạn thấy một bóng mờ thoáng qua."
  },
  AvgDialog_131229_Content_72 = {
    Text = "\"Ký ức\" là một kẻ lang thang. Cô ấy không có nhà."
  },
  AvgDialog_131229_Content_73 = {
    Text = "Gì?!! Đó……"
  },
  AvgDialog_131229_Content_74 = {
    Text = "Số phận của \"kỷ niệm\" e rằng cũng đã bị Nephreya thay đổi. Cả hai người bây giờ đều đang rơi vào tình thế nguy hiểm."
  },
  AvgDialog_131229_Content_75 = {
    Text = "Xin lỗi, tôi không nghĩ rằng…"
  },
  AvgDialog_131229_Content_76 = {
    Text = "Không phải trách nhiệm của bạn, cô Liz."
  },
  AvgDialog_131229_Content_77 = {
    Text = "Nefreya đã có thể thay đổi số phận của bạn, tìm được người bên cạnh bạn cũng không phải là chuyện khó. Những điều này, là những vấn đề chúng ta cần xử lý."
  },
  AvgDialog_131229_Content_78 = {
    Text = "Vết mực ở trên vẫn chưa khô hoàn toàn, thời gian Nephreya ra tay không còn xa, chúng ta nhanh chóng có lẽ vẫn còn kịp……"
  },
  AvgDialog_131229_Content_79 = {
    Text = "Liz, có một số lời, lần này không kịp nói……"
  },
  AvgDialog_131229_Content_8 = {
    Text = "Khi khuôn mặt cười đó không còn nhận ra chút hình dáng nào nữa, cuối cùng bạn cũng dừng lại."
  },
  AvgDialog_131229_Content_80 = {
    Text = "Sẽ luôn có cơ hội, Người Giữ Bí Mật {Male=先生,Female=小姐}. Hy vọng lần gặp sau, điệu múa mới ấy vẫn có thể lay động ngài."
  },
  AvgDialog_131229_Content_81 = {
    Text = "Sau khi tạm biệt các bạn bằng một nụ cười đơn giản, Liz không còn quan tâm đến những câu chuyện phức tạp của các bạn nữa."
  },
  AvgDialog_131229_Content_82 = {
    Text = "Cô ấy nâng cánh tay lên, tạo ra cùng một đường cong như xác chết đó, cố gắng phục hồi điệu múa luôn ám ảnh trong tâm trí cô."
  },
  AvgDialog_131229_Content_83 = {
    Text = "Gió nhẹ thổi bay vạt váy của cô ấy, như những chú thiên nga đang bay lượn."
  },
  AvgDialog_131229_Content_9 = {
    Text = "Xác của Liz bị điều khiển đã mất hết sinh khí. Bạn nhẹ nhàng đặt xác thịt máu me của cô ấy xuống sàn, mở ra đường dẫn tinh thần liên kết với cô ấy."
  },
  AvgDialog_131230_Content_1 = {Text = "Hạ màn"},
  AvgDialog_131230_Content_10 = {
    Text = "Vì đã tái tạo lại thành phố này… tôi nghĩ, bạn sẽ mang những thứ đã biến mất đó đến đây."
  },
  AvgDialog_131230_Content_11 = {
    Text = "……Bạn nhớ chúng, phải không?"
  },
  AvgDialog_131230_Content_12 = {
    Text = "So với một tách cà phê, tôi thích thấy hình ảnh mà sân khấu tự thể hiện hơn."
  },
  AvgDialog_131230_Content_13 = {
    Text = "Tôi đã tái tạo nơi này bằng những kỷ niệm, nhưng tôi vẫn không thể thay đổi thực tế rằng đây là một sân khấu hoàn toàn mới."
  },
  AvgDialog_131230_Content_14 = {
    Text = "Cà phê mới ở đây cũng có hương vị độc đáo của nó, phải không?"
  },
  AvgDialog_131230_Content_15 = {
    Text = "Arachne mỉm cười, nhẹ nhàng nhấp một ngụm chất lỏng đắng đó."
  },
  AvgDialog_131230_Content_16 = {
    Text = "Nephrya…… cuối cùng thế nào rồi?"
  },
  AvgDialog_131230_Content_17 = {
    Text = "Sợi tơ vận mệnh của các cô đã nối lại với nhau, điều này có nghĩa là…… bây giờ các cô lại trở thành cùng một người?"
  },
  AvgDialog_131230_Content_18 = {
    Text = "Những thứ từng thuộc về Nephrya, phẩm chất của cô ấy, bản tính ban đầu của cô ấy, đã quay trở lại vận mệnh của tôi. Hay nói đúng hơn, như ngài đã biết — chúng chưa bao giờ rời đi."
  },
  AvgDialog_131230_Content_19 = {
    Text = "Nhưng lưới vận mệnh là duy nhất. Nephrya mà ngài từng quen biết, kẻ báo thù chìm đắm trong Uyên Ngục, bị vận mệnh ruồng bỏ — trong tấm lưới này không có sợi tơ nào thuộc về cô ấy."
  },
  AvgDialog_131230_Content_2 = {
    Text = "Lascia ch'io pianga Hãy để ta khóc than!\nmia cruda sorte, Số phận tàn khốc."
  },
  AvgDialog_131230_Content_20 = {
    Text = "Cô ấy…… đã hoàn toàn tiêu tan rồi, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131230_Content_21 = {
    Text = "Bánh xe dệt nhẹ nhàng, không ngừng quay. Arachne nhắm mắt lại, nhẹ nhàng ngẩng đầu, hít thở hương hoa nhạt trong gió."
  },
  AvgDialog_131230_Content_22 = {
    Text = "Số phận bị bỏ rơi, chỉ đối mặt với sự giam cầm vĩnh viễn và sự biến mất hoàn toàn. Thật là một điều tàn nhẫn…"
  },
  AvgDialog_131230_Content_23 = {
    Text = "Mỗi thời mỗi khắc, vận mệnh đều cần đưa ra lựa chọn. Điều đúng đắn sẽ được giữ lại, điều sai lầm sẽ bị loại bỏ……"
  },
  AvgDialog_131230_Content_24 = {
    Text = "Trước khi chúng ta tìm được con đường chân chính, điều này cũng giống như sự sụp đổ của vũ trụ, không thể tránh khỏi."
  },
  AvgDialog_131230_Content_25 = {
    Text = "Người Giữ Bí Mật {Male=先生,Female=小姐}, nếu ngài có khả năng thao túng vận mệnh, ngài sẽ để mặc nó đi vào hỗn loạn, hay đưa ra lựa chọn cho chúng, dù điều đó có thể khiến ngài mang tội danh kẻ sát nhân?"
  },
  AvgDialog_131230_Content_26 = {
    Text = "Đây... tôi..."
  },
  AvgDialog_131230_Content_27 = {
    Text = "Đây chỉ là một đề tài tranh luận để ngài giải trí, không phải câu hỏi ngài buộc phải trả lời. Ngài đã gánh chịu quá nhiều rồi, gánh nặng này không cần ngài phải mang thêm."
  },
  AvgDialog_131230_Content_28 = {
    Text = "Arachne cười và lắc đầu."
  },
  AvgDialog_131230_Content_29 = {
    Text = "Lựa chọn là một thứ quyền lực, nhiều người dù sở hữu nó, cũng chọn cách từ bỏ. Bởi khi đưa ra lựa chọn, cũng đồng nghĩa với việc gánh chịu hậu quả."
  },
  AvgDialog_131230_Content_3 = {
    Text = "E che sospiri la libertà! \nKhao khát biết bao, ngày tự do đến!"
  },
  AvgDialog_131230_Content_30 = {
    Text = "Ngài biết đấy, đó không phải là điều dễ dàng, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131230_Content_31 = {
    Text = "Tôi là người điều khiển số phận, mọi hậu quả của số phận sẽ do tôi gánh chịu."
  },
  AvgDialog_131230_Content_32 = {
    Text = "Đây là lời nói mà Ngài đã ban tặng cho tôi khi tôi lần đầu gõ cửa cánh cửa của Chokmah-Da'at. Đối với điều này, tôi vui vẻ chấp nhận."
  },
  AvgDialog_131230_Content_33 = {
    Text = "Vì vậy, bạn... mặc dù không thể nhìn thấy số phận của mình, nhưng những điều này, tất cả những gì đang xảy ra bây giờ... bạn thực sự đều biết."
  },
  AvgDialog_131230_Content_34 = {
    Text = "Ánh nắng ấm áp chiếu sáng con phố này, nhưng khi nhìn vào khuôn mặt bình tĩnh của Arachne, tưởng tượng đến những gì người bên cạnh này phải đối mặt suốt cả ngày, ngay cả bạn cũng không khỏi rùng mình."
  },
  AvgDialog_131230_Content_35 = {
    Text = "Lãng mạn mang đến sự ngu dốt, lòng tốt mang đến sự mong manh, ký ức mang đến nỗi đau…"
  },
  AvgDialog_131230_Content_36 = {
    Text = "Dù đã chuẩn bị sẵn sàng đối mặt với những điều này từ lâu, nhưng cô chưa bao giờ thực sự vứt bỏ chúng…… Tại sao?"
  },
  AvgDialog_131230_Content_37 = {
    Text = "Đối với bạn, bỏ họ đi, chắc chắn sẽ giúp bạn sống thoải mái hơn một chút."
  },
  AvgDialog_131230_Content_38 = {
    Text = "Bạn đã từng đến nhà tù chưa? Những tù nhân bị giam giữ trong nhiều năm liền, bên cạnh họ luôn phải mang theo một số thứ mà họ quý trọng."
  },
  AvgDialog_131230_Content_39 = {
    Text = "Một tấm huân chương giành được từ trận đánh nhau, một chiếc đồng hồ gia truyền, một bức ảnh chụp cùng gia đình……"
  },
  AvgDialog_131230_Content_4 = {
    Text = "Giọng hát du dương vọng lại trên đường phố, bay bổng theo làn gió ấm áp. Những người đi bộ trên đường dừng lại hoặc tiếp tục bước đi trong âm thanh này, tận hưởng sự sống yên bình của họ trong ánh sáng mùa xuân này."
  },
  AvgDialog_131230_Content_40 = {
    Text = "Đối với các tù nhân, những ham muốn khiến họ đau khổ này chính là động lực để họ có thể tiếp tục sống."
  },
  AvgDialog_131230_Content_41 = {
    Text = "Họ cẩn thận giữ lại những vật quý giá nhất này, cho đến giây phút gần kề cái chết, sẽ từng món một giao ra những thứ vô giá trị đó."
  },
  AvgDialog_131230_Content_42 = {
    Text = "……Trong lồng giam của vận mệnh, chúng ta đều trắng tay, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131230_Content_43 = {
    Text = "Il duolo infranga Khổ đau trần thế,\nqueste ritorte vô cùng vô tận."
  },
  AvgDialog_131230_Content_44 = {
    Text = "de miei martiri Nỗi thống khổ này,\nsol per pietà chẳng ai thương xót."
  },
  AvgDialog_131230_Content_45 = {
    Text = "Nhà hát bên đường đang hát về dòng sông số phận chảy xiết của thành phố này. Arachne nhâm nhi cà phê, chăm chú lắng nghe. Từ đầu đến cuối, góc độ nụ cười của cô ấy chưa bao giờ thay đổi."
  },
  AvgDialog_131230_Content_46 = {
    Text = "Ngài có biết không, Người Giữ Bí Mật {Male=先生,Female=小姐}, tôi thường mơ đi mơ lại cùng một cảnh tượng."
  },
  AvgDialog_131230_Content_47 = {
    Text = "Đó là một nhà hát xinh đẹp, chỉ có tôi và Nefreya. Chính trong bài hát đẹp này, tôi đã tiễn biệt cô ấy."
  },
  AvgDialog_131230_Content_48 = {
    Text = "Bạn xem, ngay cả khi chúng ta không thể nhìn rõ số phận của mình, phán quyết của nó cũng ở khắp mọi nơi."
  },
  AvgDialog_131230_Content_49 = {
    Text = "E che sospiri la libertà! Khao khát biết bao!\nE che sospiri la libertà! Khao khát biết bao!"
  },
  AvgDialog_131230_Content_5 = {
    Text = "Bạn nâng cốc cà phê lên, uống một ngụm lớn."
  },
  AvgDialog_131230_Content_50 = {
    Text = "Giọng hát của nghệ sĩ opera không bao giờ ngừng nghỉ, sợi chỉ của bánh xe quay mãi mãi. Arachne đặt chiếc cốc trong tay xuống, chân thành vỗ tay nhẹ nhàng cùng với những khán giả đang đứng lại."
  },
  AvgDialog_131230_Content_51 = {
    Text = "Dù sao đi nữa, một buổi biểu diễn đã kết thúc, sân khấu này sẽ đón nhận một khoảng nghỉ ngắn. Chúng tôi, những diễn viên, cũng sắp tới với sân khấu tiếp theo."
  },
  AvgDialog_131230_Content_52 = {
    Text = "Ảnh hưởng của Nefreya đã biến mất, giờ có thể mở lại lối đi kết nối với Cađas được rồi phải không?"
  },
  AvgDialog_131230_Content_53 = {
    Text = "Cánh cửa kết nối đến Cađas nằm trong số phận của thế giới này. Bạn cũng đã thử vượt qua chiều không gian."
  },
  AvgDialog_131230_Content_54 = {
    Text = "Nguy hiểm ở đây, bạn cũng đã biết."
  },
  AvgDialog_131230_Content_55 = {
    Text = "Quả thật… những ánh mắt của Toguwaibo, tôi không muốn phải đối mặt lần nữa…"
  },
  AvgDialog_131230_Content_56 = {
    Text = "Arachne, bạn có thể kiểm soát số phận của thế giới này, có lẽ bạn có cách nào đó có thể giúp tôi?"
  },
  AvgDialog_131230_Content_57 = {
    Text = "Tôi rất vui lòng phục vụ, nhưng trong thế giới này, chỉ thành phố này là sân khấu của tôi. Chủ nhân của số phận thế giới này không phải là tôi."
  },
  AvgDialog_131230_Content_58 = {
    Text = "Quả nhiên!……"
  },
  AvgDialog_131230_Content_59 = {
    Text = "Chủ nhân của thế giới này, sở hữu năng lực mà ngay cả tôi cũng không thể sánh kịp. Thế giới này, tồn tại nhờ ý chí của Ngài."
  },
  AvgDialog_131230_Content_6 = {
    Text = "So với cà phê Khvarts thì kém xa lắm."
  },
  AvgDialog_131230_Content_60 = {
    Text = "Trừ khi chủ động mở thông đạo, nếu không, nơi đây sẽ là một chốn mà ngay cả ánh mắt của thần minh tối cao cũng không thể chạm tới…… Đó cũng chính là lý do tôi trú ngụ tại đây."
  },
  AvgDialog_131230_Content_61 = {
    Text = "Có nghĩa là… nếu tôi mở đường dẫn, sẽ gây ra nguy hiểm ở đây?"
  },
  AvgDialog_131230_Content_62 = {
    Text = "Như tôi đã nói, số phận có quỹ đạo riêng của nó. Chỉ ở đây, chỉ là chậm rãi đợi cái chết. Hỗ trợ bạn trở về Cađas, cũng là nguyện vọng từ trước của chủ nhân thế giới này."
  },
  AvgDialog_131230_Content_63 = {
    Text = "Vì điểm sáng phía trước vận mệnh, đây là hiểm nguy mà chúng tôi hoàn toàn sẵn lòng gánh chịu."
  },
  AvgDialog_131230_Content_64 = {
    Text = "Thì ra là vậy…… Tôi hiểu rồi."
  },
  AvgDialog_131230_Content_65 = {
    Text = "Tôi có thể tìm thấy Ngài ở đâu?"
  },
  AvgDialog_131230_Content_66 = {
    Text = "Đường tơ số phận của Ngài rộng lớn như biển sao, lại nhỏ bé như bụi mờ. Chỉ dựa vào việc nắm bắt số phận, tôi không thể chỉ ra vị trí của Ngài một cách trực tiếp cho bạn."
  },
  AvgDialog_131230_Content_67 = {
    Text = "Nhưng có lẽ, điều này có thể giúp bạn."
  },
  AvgDialog_131230_Content_68 = {
    Text = "Arachne đưa cho bạn một trang tờ rơi quảng cáo. Bạn nhíu mày, nhìn những dòng chữ hoa mỹ đầy cảm giác tôn giáo trên đó."
  },
  AvgDialog_131230_Content_69 = {
    Text = "Tin tuyển dụng:"
  },
  AvgDialog_131230_Content_7 = {
    Text = "Lần trước đi đến sân khấu đó nếm thử, tôi cũng thấy hương vị rất ngon. Thật tiếc, gia đình phát minh ra loại cà phê đó đã tuyệt chủng từ rất lâu trước đây."
  },
  AvgDialog_131230_Content_70 = {
    Text = "Đại giáo chủ vĩ đại, Người được chọn của thần minh, Người thực hiện của thần tối cao, Người kế thừa hợp pháp của giáo phái vĩ đại, Người giải cứu khỏi khổ nạn, bạn thân của thần vương đã đến vùng đất Bắc cuối cùng, giáo phái hiện đang phát triển nhanh chóng, tín đồ có thể nhanh chóng đến đây để diện kiến."
  },
  AvgDialog_131230_Content_71 = {
    Text = "Mười hai tín đồ đến trước tiên sẽ được phong làm thánh, mãi mãi theo sau nàng tiên, nhận được sự che chở vĩnh viễn từ các vị thần…"
  },
  AvgDialog_131230_Content_72 = {
    Text = "Đây là…… cái gì vậy?"
  },
  AvgDialog_131230_Content_73 = {
    Text = "Như bạn thấy, đây là một cuốn brochure được sản xuất tỉ mỉ."
  },
  AvgDialog_131230_Content_74 = {
    Text = "Nội dung trên sao lại kỳ quái như vậy…… Arachne, bạn có thể thấy được hướng đi của số phận, bạn chắc chắn rằng đây không phải là một trò lừa đảo?"
  },
  AvgDialog_131230_Content_75 = {
    Text = "Trên sợi dây của nó, tôi đã nhìn thấy hình bóng của bạn. Tôi rất chắc chắn, đó là số phận mà bạn sẽ đón nhận."
  },
  AvgDialog_131230_Content_76 = {
    Text = "Là giúp đỡ, hay là nguy hiểm, tôi không thể biết. Nhưng tôi biết, giữa bạn và vị chủ nhân của thế giới đó, đây là liên kết duy nhất."
  },
  AvgDialog_131230_Content_77 = {
    Text = "Bàn tay Arachne vươn ra phía trên tờ quảng cáo hoang đường kia, nhón lấy một thứ mà bạn không thể nhìn thấy, đặt vào lòng bàn tay bạn."
  },
  AvgDialog_131230_Content_78 = {
    Text = "Cái này lại là?……"
  },
  AvgDialog_131230_Content_79 = {
    Text = "Rất nhanh, một sợi tơ mờ ảo phản chiếu ánh sáng lờ mờ trong tay bạn."
  },
  AvgDialog_131230_Content_8 = {
    Text = "Bạn nhìn quanh thành phố này. Ngã tư Brick, hiệu sách cũ thời gian gập lại, cửa hàng tạp hóa chợ thơm……"
  },
  AvgDialog_131230_Content_80 = {
    Text = "Đây là cơ duyên kết nối ngươi với đoạn vận mệnh đó. Nó sẽ dẫn đường cho ngươi, đến nơi ngươi cần phải đến."
  },
  AvgDialog_131230_Content_81 = {
    Text = "Tôi hiểu rồi. Đợi vết thương của học trưởng William lành, chúng tôi sẽ lập tức……"
  },
  AvgDialog_131230_Content_82 = {
    Text = "Trong khoảnh khắc ngắn ngủi tôi nhìn thoáng qua sợi chỉ vận mệnh của bạn, bạn sẽ gặp một câu chuyện thú vị."
  },
  AvgDialog_131230_Content_83 = {
    Text = "Tôi không thể nhìn thấy kết cục của bạn, đó là một điều may mắn — đối với vận mệnh của bạn, tôi vẫn còn giữ được vinh hạnh làm một khán giả."
  },
  AvgDialog_131230_Content_84 = {
    Text = "Tôi nghĩ, không có bất kỳ câu chuyện nào đáng bị phụ bạc…… Vì vậy, xin đừng vội vàng. Hãy cùng nghe trọn vẹn vở opera này nhé, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131230_Content_85 = {
    Text = "Tiếng hát của nghệ sĩ opera lại tràn ngập khắp phố phường. Arachne nhắm mắt lại, ánh nắng rơi trên gương mặt tĩnh lặng của cô, ấm áp như những mùa xuân mà cô đã đánh mất."
  },
  AvgDialog_131230_Content_86 = {
    Text = "Xa quay quay tròn, tiếng hát không ngừng. Người qua kẻ lại, vạn ngàn sợi chỉ mà bạn không thể nhìn thấy hội tụ bên cô, đan dệt."
  },
  AvgDialog_131230_Content_87 = {
    Text = "Bạn nhìn gương mặt đang mỉm cười của Arachne. Bạn thấy, bên cạnh cô trống không, chẳng có gì cả."
  },
  AvgDialog_131230_Content_9 = {
    Text = "Mọi thứ dường như vẫn không thay đổi, ngay cả những vết gỉ sét mờ nhạt trên biển hiệu cũng giống hệt như trong ký ức của bạn."
  },
  AvgDialog_131231_Content_1 = {
    Text = "Phù… còn may kịp rồi…"
  },
  AvgDialog_131231_Content_10 = {
    Text = "Sorrel híp mắt quan sát Arachne. Cô ấy phát hiện ra rằng khả năng nhận biết người mà mình tự hào hoàn toàn vô dụng. Cô không thể nhìn rõ quá khứ của người đứng trước, cũng không đoán được những khao khát của cô ấy."
  },
  AvgDialog_131231_Content_11 = {
    Text = "Cô ấy nhanh chóng ghi nhớ mọi chi tiết trên khuôn mặt đó, nhưng trong khoảnh khắc chớp mắt đã quên hết. Mép môi của Sorrel khẽ nhếch lên với vẻ thú vị."
  },
  AvgDialog_131231_Content_12 = {
    Text = "Hai vị khách quý đầy hấp dẫn. Buổi salon này nhất định sẽ khiến tôi mãi không quên. Hai vị xin mời ngồi."
  },
  AvgDialog_131231_Content_13 = {
    Text = "Sorrel quay lại ngồi trên ghế sofa, giơ tay ra hiệu cho các bạn."
  },
  AvgDialog_131231_Content_14 = {
    Text = "Tôi đã có vài lần gặp gỡ với \"lương thiện\", anh ấy tìm đến tôi, tìm kiếm sự che chở của tôi."
  },
  AvgDialog_131231_Content_15 = {
    Text = "Các bạn đã cứu tôi. Tôi không thể nhìn rõ các bạn, nhưng tôi có thể thấy rằng các bạn không có ác ý."
  },
  AvgDialog_131231_Content_16 = {
    Text = "Đúng vậy, thưa bà Sorrel. Chúng tôi đến đây để cứu anh ấy."
  },
  AvgDialog_131231_Content_17 = {
    Text = "Anh ấy không có mặt trong điền trang này."
  },
  AvgDialog_131231_Content_18 = {
    Text = "Nhưng bạn vừa nói……"
  },
  AvgDialog_131231_Content_19 = {
    Text = "Như bạn thấy, trang viên của tôi cũng không an toàn."
  },
  AvgDialog_131231_Content_2 = {
    Text = "Xác nhận trạng thái của Gia Lân xong, bạn đứng dậy, lau mồ hôi lạnh trên trán."
  },
  AvgDialog_131231_Content_20 = {
    Text = "Sorrel giơ tay lên, như thể đang trưng bày những bảo vật quý giá, nhìn về phía những xác chết lộn xộn trong căn phòng rực rỡ và gọn gàng."
  },
  AvgDialog_131231_Content_21 = {
    Text = "Đó là một vị ông tốt bụng nhưng không ngu ngốc. Tôi có thể thấy rằng, ông ấy đang đối mặt với tình huống rất nguy cấp."
  },
  AvgDialog_131231_Content_22 = {
    Text = "Mối quan hệ giữa tôi và anh ta, có không ít người biết. Giấu anh ta trong biệt thự không phải là một quyết định khôn ngoan."
  },
  AvgDialog_131231_Content_23 = {
    Text = "Xin hỏi bây giờ anh ấy ở đâu?"
  },
  AvgDialog_131231_Content_24 = {
    Text = "Soreil đứng dậy, bước đến trước một bức họa. Ngươi đứng lên, nhìn rõ hình ảnh trên đó."
  },
  AvgDialog_131231_Content_25 = {
    Text = "Đó là...!"
  },
  AvgDialog_131231_Content_26 = {
    Text = "Vài năm trước, tôi đã đến xem một buổi biểu diễn của đoàn múa thiên nga tại nhà hát Lentiennam. Đó vốn là một buổi giao lưu đơn giản, nhưng tôi đã bị sốc sâu sắc bởi điệu nhảy của cô ấy."
  },
  AvgDialog_131231_Content_27 = {
    Text = "Những năm qua, thỉnh thoảng tôi đã ghé thăm hậu trường khi mời đoàn múa biểu diễn. Chúng tôi không có mối quan hệ thực sự nào, chính vì vậy, đoàn múa mà cô ấy thuộc về là nơi thích hợp nhất để đặt vị đó\"Thiện Lương\"."
  },
  AvgDialog_131231_Content_28 = {
    Text = "Trên bức họa trước mắt, Liz mặc chiếc váy múa thanh lệ, nhảy vọt cao trong không trung, tựa như thiên nga tung cánh."
  },
  AvgDialog_131231_Content_29 = {
    Text = "Liz... vũ đoàn của cô ấy, bây giờ ở đâu?"
  },
  AvgDialog_131231_Content_3 = {
    Text = "Gia Lân chắc không sao, cô ấy bị ảnh hưởng một chút, nghỉ ngơi một thời gian sẽ tốt lên thôi."
  },
  AvgDialog_131231_Content_30 = {
    Text = "Theo sợi chỉ số phận ngày càng rõ ràng, Arachne nhìn ra ngoài cửa sổ, nơi kết nối với sợi chỉ, ẩn mình trong rừng rậm."
  },
  AvgDialog_131231_Content_31 = {
    Text = "Tại một nơi mà bạn vô cùng quen thuộc."
  },
  AvgDialog_131231_Content_4 = {
    Text = "Tôi có thể nhớ rõ từng khuôn mặt mà tôi đã thấy, nhưng cảm giác bạn mang lại cho tôi thật kỳ lạ. Tôi không thể chắc chắn liệu mình đã gặp bạn chưa… điều này chưa từng xảy ra với tôi."
  },
  AvgDialog_131231_Content_5 = {
    Text = "Sorrel cầm chai rượu chưa bị đổ trên bàn trà, rót vào ly, vượt qua những xác chết đang tan chảy khắp phòng, đưa ly rượu đến trước mặt các bạn."
  },
  AvgDialog_131231_Content_6 = {
    Text = "Rượu vang Bồ Đào Nha 40 năm tuổi, bộ sưu tập riêng của tôi, những con chó rừng ở dưới lầu không có tư cách thưởng thức nó. Dù các bạn là ai, tại sao lại xuất hiện ở đây, tôi nghĩ rằng ly rượu này nên thuộc về các bạn."
  },
  AvgDialog_131231_Content_7 = {
    Text = "Chúng tôi đến vì \"Lòng tốt\", thưa bà Sorrel."
  },
  AvgDialog_131231_Content_8 = {
    Text = "Arachne nhận lấy ly rượu, mỉm cười gật đầu chào Sorrel."
  },
  AvgDialog_131231_Content_9 = {
    Text = "Khi không mở miệng, cô ấy giống như mạng nhện trong ánh sáng buổi sáng, hoàn toàn không gây chú ý. Sau khi cô mở miệng, mọi ánh sáng trong phòng dường như đều hội tụ vào người cô."
  },
  AvgDialog_131232_Content_1 = {
    Text = "Một trận chiến thật tuyệt vời, chị gái."
  },
  AvgDialog_131232_Content_10 = {
    Text = "Bạn và người hầu của bạn là những người đã mất đi số phận, sợi chỉ số phận của các bạn tôi không thể nắm bắt. Nhưng khả năng của bạn đến từ tôi, tôi không thể nhìn rõ số phận của mình, bạn cũng vậy."
  },
  AvgDialog_131232_Content_11 = {
    Text = "Bạn và tôi… đây là một cuộc chiến vô nghĩa đã định sẵn sẽ bế tắc. Nó lẽ ra không nên xảy ra."
  },
  AvgDialog_131232_Content_12 = {
    Text = "Tất nhiên, tất nhiên. Đối với bạn, những thứ đã bị bỏ rơi như chúng tôi, nên biến mất trong nghĩa trang số phận, bị phân hủy, tiêu vong, tan biến ở đây, cho đến mãi mãi, mãi mãi."
  },
  AvgDialog_131232_Content_13 = {
    Text = "Thật đáng tiếc, bạn không thể nhìn rõ Ngài... Dù bạn có sức mạnh mạnh mẽ đến đâu, cũng không thể so sánh với vị thần tối cao đó?"
  },
  AvgDialog_131232_Content_14 = {
    Text = "Bạn biết mà. Bạn rõ ràng biết, tất cả những điều này đều là vô ích. Nhưng bạn không thể ngừng dệt mạng…"
  },
  AvgDialog_131232_Content_15 = {
    Text = "Khi bạn đã nhìn thấy, bạn không thể chịu đựng những đường nét rối rắm đó. Khi bạn đã có khả năng như vậy, bạn không thể ngồi nhìn những thế giới rơi vào sự hỗn loạn không ngừng."
  },
  AvgDialog_131232_Content_16 = {
    Text = "Bạn mang đến cho họ sự bình yên giả tạo, và cũng dẫn họ lên một con đường cuối cùng sẽ dẫn đến sự diệt vong."
  },
  AvgDialog_131232_Content_17 = {
    Text = "Thật là một người đáng thương, Arachne."
  },
  AvgDialog_131232_Content_18 = {
    Text = "Đây là số phận của chúng ta, Nephreya."
  },
  AvgDialog_131232_Content_19 = {
    Text = "À… có vẻ như tôi hơi buồn ngủ. Tranh luận với kẻ ngu ngốc là việc nhàm chán nhất trên đời này."
  },
  AvgDialog_131232_Content_2 = {
    Text = "Quán bar ồn ào bỗng trở nên im lặng, những xác chết đổ xuống đất biến thành chất lỏng và bột đen, tan biến trong ánh đèn dịu dàng."
  },
  AvgDialog_131232_Content_20 = {
    Text = "Chào mừng bạn đến với màn thứ hai của câu chuyện này. Đây là sân khấu của bạn, nhưng từ bây giờ, câu chuyện này sẽ được tôi viết nên."
  },
  AvgDialog_131232_Content_21 = {
    Text = "Phần mở đầu là quan trọng nhất, đúng không? Nên đặt tên gì cho tốt nhỉ... À, gọi là\"Gặp lại\" thì sao?"
  },
  AvgDialog_131232_Content_22 = {
    Text = "Nefreya rất hài lòng với cái tên của mình, dùng chi tiết của mình nhúng vào ly rượu lâu năm rồi cho vào miệng, phát ra một tiếng thở dài say sưa."
  },
  AvgDialog_131232_Content_23 = {
    Text = "Để cho ngày này, tôi đã chuẩn bị quá lâu, quá lâu. Tôi sẽ thật sự tận hưởng câu chuyện này với bạn, chị gái thân mến."
  },
  AvgDialog_131232_Content_24 = {
    Text = "Không cho các bạn cơ hội hỏi thêm. Đầu ngón tay sắc nhọn của Nephreya nhẹ nhàng lướt qua mép má của Arachne, rồi cùng với cơ thể ngã xuống đất."
  },
  AvgDialog_131232_Content_25 = {
    Text = "Đợi đã…!"
  },
  AvgDialog_131232_Content_26 = {
    Text = "Nàng ấy không ở đây, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131232_Content_27 = {
    Text = "Một tiếng sôi sục vang lên, chất nhầy màu đen lại trượt xuống từ khuôn mặt của xác chết."
  },
  AvgDialog_131232_Content_28 = {
    Text = "\"Lãng mạn\"đôi mắt quyến rũ đó vẫn giữ nguyên độ cong của nụ cười, con nhện đen bò lổm ngổm trong cơ thể cô, hiện lên mờ ảo trong hốc mắt sáng ngời. Đôi môi thanh lịch đó không còn phát ra bất kỳ âm thanh nào nữa."
  },
  AvgDialog_131232_Content_29 = {
    Text = "Đây là…"
  },
  AvgDialog_131232_Content_3 = {
    Text = "Nefreya và Arachne vẫn ngồi đối diện nhau, cô ấy rót một ly rượu và đẩy về phía Arachne."
  },
  AvgDialog_131232_Content_30 = {
    Text = "Cô ấy đã giết chết con rối bí mật này, để lại dấu ấn trên cơ thể cô, ô nhiễm số phận của cô, khiến bản thân tồn tại ngắn ngủi trong cơ thể cô."
  },
  AvgDialog_131232_Content_31 = {
    Text = "Arachne đến trước bí ẩn, đưa tay về phía đỉnh đầu của \"lãng mạn\", nhìn chằm chằm vào sợi chỉ gần như đã biến mất."
  },
  AvgDialog_131232_Content_32 = {
    Text = "…có thấy gì không?"
  },
  AvgDialog_131232_Content_33 = {
    Text = "Những bí ẩn khác cũng đã bị ô nhiễm, tôi không thể cảm nhận được sự tồn tại của họ từ mạng lưới số phận... nhưng số phận của \"lãng mạn\" kết nối với họ."
  },
  AvgDialog_131232_Content_34 = {
    Text = "Cô ấy đã nói cho tôi biết,\"lòng tốt\"ở đâu."
  },
  AvgDialog_131232_Content_35 = {
    Text = "Arachne bỏ sợi chỉ số phận, đang sắp xếp mái tóc đẹp của \"lãng mạn\"."
  },
  AvgDialog_131232_Content_36 = {
    Text = "Nefreya có sức mạnh từ tôi, số phận bị cô ta ô nhiễm, tôi không thể nhìn thấy, nhiều khả năng cũng bị hạn chế bởi điều này."
  },
  AvgDialog_131232_Content_37 = {
    Text = "Ngài là mảnh vỡ của vị thần minh ấy, là người mà chúng ta không thể nhìn thấu định mệnh. Vì vậy, ta cần sự giúp đỡ của ngài, Người Giữ Bí Mật {Male=先生,Female=小姐}."
  },
  AvgDialog_131232_Content_38 = {
    Text = "Hãy yên tâm, chỉ vì trở về Cađas, tôi cũng nhất định phải giải quyết cô ấy."
  },
  AvgDialog_131232_Content_39 = {
    Text = "Cô ấy tìm kiếm những bí ẩn này, là để làm gì?"
  },
  AvgDialog_131232_Content_4 = {
    Text = "Mặc dù tiểu thư \"Lãng mạn\"đã không còn nữa, nhưng rượu ở đây thì không nên lãng phí."
  },
  AvgDialog_131232_Content_40 = {
    Text = "Những bí ẩn này sẽ trở thành nguồn sức mạnh của cô ấy."
  },
  AvgDialog_131232_Content_41 = {
    Text = "Thì chúng ta phải nhanh chóng lên đường... tìm những bí ẩn đó, còn có những tàn tro chiều có thể giúp bạn dệt nên số phận..."
  },
  AvgDialog_131232_Content_42 = {
    Text = "Nhóc nhỏ gọi là\"Lương thiện\" bây giờ đang ở đâu?"
  },
  AvgDialog_131232_Content_43 = {
    Text = "\"Lãng Mạn\" không lâu trước đây đã báo cho hắn biết về mối nguy hiểm. Hiện tại hắn đang ẩn náu, người che chở hắn là một người bạn cũ của ngài."
  },
  AvgDialog_131232_Content_44 = {
    Text = "Bạn cũ?…"
  },
  AvgDialog_131232_Content_45 = {
    Text = "Xin mời đi theo ta, Người Giữ Bí Mật {Male=先生,Female=小姐}. Buổi salon thịnh đại của phu nhân Soreil sắp bắt đầu rồi."
  },
  AvgDialog_131232_Content_5 = {
    Text = "Bạn có muốn thử không? So với cái bí mật tự biên tự diễn đó, tôi mới là người thật sự hiểu bạn."
  },
  AvgDialog_131232_Content_6 = {
    Text = "Arachne không do dự, cô ấy mỉm cười nâng ly rượu lên, nhấp nhẹ một ngụm."
  },
  AvgDialog_131232_Content_7 = {
    Text = "Bạn không phù hợp với nghề này, Nefreya. Ngoài vị đắng và chua, nó không còn hương vị nào khác."
  },
  AvgDialog_131232_Content_8 = {
    Text = "Ta gọi nó là \"Định Mệnh\". Thích không?"
  },
  AvgDialog_131232_Content_9 = {
    Text = "Arachne không để ý đến ánh mắt mong chờ của Nephreya. Cô ấy từ từ uống rượu trong ly, nhẹ nhàng đặt ly rượu xuống bàn."
  },
  AvgDialog_132684_Content_1 = {
    Text = "<Small:<LightGray:Chíp……? (Ừm……?)>>"
  },
  AvgDialog_132684_Content_10 = {
    Text = "Không sai, và xét rằng Misaque vốn có truyền thống trêu chọc mọi người để giao tiếp tình cảm trong ngày hôm nay, nhà trường sẽ không phạt loại \"trò đùa\" không quá mức này."
  },
  AvgDialog_132684_Content_11 = {
    Text = "Két! Két, két—!<Small:<LightGray:(đóa thầy, bạn đang nắm tay và mặt tôi phải không, bạn đang xoa mặt tôi đúng không!)>>"
  },
  AvgDialog_132684_Content_12 = {
    Text = "Mặc dù giọng điệu vẫn lạnh lùng như mọi khi, thậm chí có chút châm biếm, nhưng bạn rất chắc chắn rằng khóe miệng của Đóa ít nhất đã nhếch lên 2 milimét."
  },
  AvgDialog_132684_Content_13 = {
    Text = "Xin lỗi, Người Giữ Gìn. Bạc tâm dịch máy dường như gặp chút vấn đề, nhưng không sao, thuốc thử sẽ được tổng hợp vào sáng mai."
  },
  AvgDialog_132684_Content_14 = {
    Text = "Bạn nhìn Đóa với vẻ mặt kinh ngạc, ngay cả khi bây giờ bạn chỉ có bộ não của một con hải cẩu, cũng có thể nhận ra rằng chất thử phía sau cô ấy rõ ràng đã ở trạng thái hoàn thành."
  },
  AvgDialog_132684_Content_15 = {
    Text = "Giáo viên, tìm Mosk?"
  },
  AvgDialog_132684_Content_16 = {
    Text = "！！！Viên than nhỏ—"
  },
  AvgDialog_132684_Content_17 = {
    Text = "Chiếp—<Small:<LightGray:(Lão Đại—)>>"
  },
  AvgDialog_132684_Content_18 = {
    Text = "Vì chúng ta có những người có kinh nghiệm phong phú về nhóm này, tôi nghĩ, dành một ngày với họ sẽ giúp Người Giữ Gìn của chúng ta nhớ lâu hơn."
  },
  AvgDialog_132684_Content_19 = {
    Text = "Mosk, quản lý nhiệm vụ của %player% thì giao cho bạn rồi."
  },
  AvgDialog_132684_Content_2 = {Text = "*nhảy"},
  AvgDialog_132684_Content_20 = {
