  AvgDialog_132684_Content_4 = {Text = "???!!!"},
  AvgDialog_132684_Content_5 = {
    Text = "Két két két két két！Ước ước ước ước ước！！！<Small:<LightGray:(Tôi đã biến thành hải ly rồi! Ramona, cứu tôi!)>>"
