  AvgDialog_132684_Content_7 = {
    Text = "Tin tốt, hiệu ứng của loại xịt này không phải là không thể đảo ngược, việc điều chế chất phản ứng cũng rất đơn giản, rõ ràng bên kia không có ác ý."
