  AvgDialog_132684_Content_9 = {
    Text = "Vì vậy, việc chuyển đổi tạm thời này sẽ không gây ra bất kỳ thương tổn nào cho Người Giữ Gìn?"
  },
  AvgDialog_13733_Content_1 = {
    Text = "Lễ tế đỏ"
  },
  AvgDialog_13733_Content_10 = {
    Text = "Heh heh, ngươi không bao giờ có thể trông chờ vào tầm hiểu biết của bọn Lemwashi. Mở to mắt mà xem…"
  },
  AvgDialog_13733_Content_11 = {
    Text = "Purin rút từ trong tay áo ra một con dao nghi lễ, không chút do dự cắt vào cổ tay mình."
  },
  AvgDialog_13733_Content_12 = {
    Text = "Máu đỏ thẫm từng giọt nhỏ xuống pháp trận được vẽ bằng lưu huỳnh, phép màu đã xảy ra như thế—"
  },
  AvgDialog_13733_Content_13 = {
    Text = "Như một giọt nước hòa vào sa mạc khô cằn, pháp trận hấp thụ máu tươi nhanh chóng phát ra từng vòng từng vòng ánh sáng đỏ sẫm."
  },
  AvgDialog_13733_Content_14 = {
    Text = "Chúng như ngọn lửa dưới bầu trời đen, tham lam liếm láp cát vàng cuồn cuộn trong gió, tựa như muốn nuốt trọn cả mặt đất vào bụng mình."
  },
  AvgDialog_13733_Content_15 = {
    Text = "Thấy chưa, đây mới là khoảnh khắc ma pháp thực sự! Ha ha ha ha!"
  },
  AvgDialog_13733_Content_16 = {
    Text = "Ha ha ha… <Big:Ugh ahhh!!!>"
  },
  AvgDialog_13733_Content_17 = {
    Text = "Purin \"rầm\" một tiếng quỳ sụp xuống đất, không thể kiểm soát mà bóp chặt lấy cổ họng mình."
  },
  AvgDialog_13733_Content_18 = {
    Text = "Xiềng xích nối liền hắn với Yuuhashi nhanh chóng căng cứng, kéo chặt huyết nhục và linh hồn của hai người lại với nhau."
  },
  AvgDialog_13733_Content_19 = {
    Text = "Ugh… cái gì…?"
