  AvgDialog_13733_Content_20 = {
    Text = "Yuuhashi không thể duy trì tư thế ngồi thảnh thơi được nữa."
  },
  AvgDialog_13733_Content_21 = {
    Text = "Hắn bị một lực vô hình hất tung, có phần ngơ ngác nhìn pháp trận trước mắt sắp mất kiểm soát."
