  AvgDialog_13733_Content_25 = {
    Text = "Đau đớn sao… đau đớn là đúng rồi…"
  },
  AvgDialog_13733_Content_26 = {
    Text = "Lúc này ý thức của chúng ta đang bị kết nối chặt chẽ với nhau…"
  },
  AvgDialog_13733_Content_27 = {
    Text = "Bọn chó Lemwashi đã tàn sát đồng bào ta, làm nhục vợ ta như thế nào, ngươi đã thấy chưa… đã cảm nhận được chưa…"
