  },
  AvgDialog_13733_Content_36 = {
    Text = "Purin phát ra tiếng rên rỉ đau đớn, da thịt trên mặt hắn như vỏ cây không ngừng thối rữa, bong tróc, lộ ra đám thịt mơ hồ bên trong."
  },
  AvgDialog_13733_Content_37 = {
    Text = "Pháp trận mở rộng miệng đen ngòm, nuốt sạch từng chút máu thịt của hắn, cho đến khi phù thủy hoàn toàn biến thành một bộ xương trống rỗng."
  },
  AvgDialog_13733_Content_38 = {
    Text = "Ta đã hiến tế máu thịt, linh hồn và tất cả của ta……còn ngươi thì sao……"
  },
  AvgDialog_13733_Content_39 = {
    Text = "Trước khi giết được một vạn con chó Lemwashi, ngươi không thể nào có được tự do thực sự!"
  },
  AvgDialog_13733_Content_4 = {
    Text = "Không đúng, xem trong sách viết thế nào……"
