  AvgDialog_13733_Content_40 = {
    Text = "Yuwuhashi từ từ đứng dậy."
  },
  AvgDialog_13733_Content_41 = {
    Text = "Khuôn mặt hắn bị ngọn lửa vô hình thiêu đốt thành tro đen sì, gió thổi qua liền rơi lả tả."
  },
  AvgDialog_13733_Content_42 = {Text = "Hừ……"},
  AvgDialog_13733_Content_43 = {
    Text = "\"Tự do thực sự\"……? Thứ đó là cái gì?"
  },
  AvgDialog_13733_Content_44 = {
    Text = "Chiến binh cháy sém đứng sừng sững giữa ánh lửa rực rỡ. Đôi mắt hắn đỏ ngầu, chỉ phát ra tiếng rung khàn khàn từ trong cổ họng."
  },
  AvgDialog_13733_Content_45 = {
    Text = "Ta, Yuwuhashi, thứ thực sự quan tâm, từ trước đến nay chỉ có một —"
  },
  AvgDialog_13733_Content_46 = {
    Text = "Hắn lao ra với tốc độ cực nhanh, đè ngã phù thủy xuống đất."
