  AvgDialog_13733_Content_47 = {
    Text = "Rồi hắn nhe nanh nhọn hoắt, cắn đứt cổ phù thủy."
  },
  AvgDialog_13733_Content_48 = {
    Text = "<Red:Đó chính là máu!!>"
  },
  AvgDialog_13733_Content_49 = {
    Text = "Ngài Purin!"
  },
  AvgDialog_13733_Content_5 = {
    Text = "Cách chiến trường chưa đến năm mươi thước, Purin đang cần mẫn bận rộn."
  },
  AvgDialog_13733_Content_50 = {
    Text = "<Shake:Mạng này, cho ngươi……báo thù@2giúp ta……>"
