  AvgDialog_13733_Content_52 = {
    Text = "Con mồi không có tư cách đòi hỏi ta — Yuwuhashi."
  },
  AvgDialog_13733_Content_53 = {
    Text = "Ta ngoan ngoãn nghe lời ngươi, là vì ta có thể bất cứ lúc nào đập nát món đồ chơi xích sắt của ngươi, chứ không phải vì cái khế ước chó má đó."
  },
  AvgDialog_13733_Content_54 = {
