  AvgDialog_13733_Content_56 = {
    Text = "<Change>Ác quỷ……ngươi là ác quỷ……"
  },
  AvgDialog_13733_Content_57 = {
    Text = "Máu tươi của Purin tuôn chảy tràn lan trong pháp trận, khiến những tia sáng đỏ máu kia cũng trở nên vô cùng ảm đạm."
  },
  AvgDialog_13733_Content_58 = {
