  AvgDialog_13733_Content_59 = {
    Text = "Hehe……ahhh@4……"
  },
  AvgDialog_13733_Content_6 = {
    Text = "Còn Yuuhashi theo yêu cầu của Purin, ngồi ngay ngắn giữa pháp trận được vẽ bằng bột lưu huỳnh."
  },
  AvgDialog_13733_Content_60 = {
    Text = "Yuwuhashi từ từ ngẩng đầu lên, khóe miệng vẫn còn vương máu tươi chưa liếm sạch, đôi mắt đã sớm bị bóng tối xâm thực."
  },
  AvgDialog_13733_Content_61 = {
    Text = "Hắn đã biến thành một con dã thú thực sự. Hay nói đúng hơn, đây mới là bộ mặt vốn có của hắn."
  },
  AvgDialog_13733_Content_62 = {
    Text = "<Red:Trở lại rồi, tất cả đều trở lại rồi……>"
  },
  AvgDialog_13733_Content_7 = {
    Text = "Hô……hô……"
  },
  AvgDialog_13733_Content_8 = {
    Text = "Thật lợi hại, trong tình huống thế này mà vẫn ngủ được……"
  },
  AvgDialog_13733_Content_9 = {
    Text = "Tôi có một câu hỏi kỹ thuật muốn thỉnh giáo, ngài Purin.\nBột mà ngài rắc ra chẳng phải sẽ bị gió thổi bay sao?"
  },
  AvgDialog_13734_Content_1 = {
    Text = "Hừ……cuối cùng cũng đuổi kịp rồi.\nTa cảnh cáo ngươi, Yuuhashi, hậu quả của việc tự ý rời xa ta, ngươi nên hiểu rõ chứ?"
  },
  AvgDialog_13734_Content_10 = {
    Text = "Các ngươi cuối cùng cũng đến được điểm cuối của chuyến đi này. Purin ép ra vài tiếng cười quái dị từ cổ họng, ngọn lửa mang tên phục thù thiêu đốt khiến toàn thân hắn run rẩy."
  },
  AvgDialog_13734_Content_11 = {
    Text = "<Shake:Đi thôi, Yuuhashi……>"
  },
  AvgDialog_13734_Content_12 = {
    Text = "<Red:Giết cho thỏa thích.>"
  },
  AvgDialog_13734_Content_2 = {Text = "Suỵt!!"},
  AvgDialog_13734_Content_3 = {
    Text = "Yuuhashi ngồi xổm trên đỉnh cồn cát cao, khoang mũi phát ra tiếng suỵt bực bội, giống như một con thú đang tập trung săn mồi bị muỗi mòng quấy rầy."
  },
  AvgDialog_13734_Content_4 = {
    Text = "Môi hắn hé mở, cánh mũi rung nhẹ, ánh sáng đỏ máu trong mắt rực rỡ hơn bao giờ hết."
  },
  AvgDialog_13734_Content_5 = {
    Text = "<RedShake:Tìm thấy rồi, tìm thấy rồi……>"
  },
  AvgDialog_13734_Content_6 = {
    Text = "Các ngươi thuận theo ánh mắt hắn nhìn xuống phía dưới—"
  },
  AvgDialog_13734_Content_7 = {
    Text = "Vô số chấm đen nhỏ bé rải rác trên những cồn cát nhấp nhô, giống như đàn kiến đang bò trên bàn cát."
  },
  AvgDialog_13734_Content_8 = {
    Text = "Tiếng binh khí va chạm, tiếng gào thét và tiếng vó ngựa nối tiếp nhau, bức tranh cuộn chiến tranh hùng vĩ từ từ mở ra trước mắt các ngươi."
  },
  AvgDialog_13734_Content_9 = {
    Text = "Người Lemwashi, người Reo……tốt, rất tốt."
