  AvgDialog_13735_Content_1 = {
    Text = "Viễn Chinh Mặt Trời"
  },
  AvgDialog_13735_Content_10 = {
    Text = "Hắn vẫn bị trói buộc bởi xiềng xích vô hình, chỉ có thể ngồi xếp bằng trong tư thế gượng gạo, cả người gần như hòa làm một với bóng tối."
