  AvgDialog_13735_Content_14 = {
    Text = "Hehe……đừng giả vờ nữa."
  },
  AvgDialog_13735_Content_15 = {
    Text = "Ngươi có thể nhìn thấy xiềng xích trên người ta, chắc hẳn cũng biết rõ ma tượng là thứ gì rồi chứ."
  },
  AvgDialog_13735_Content_16 = {
    Text = "Không ngờ cái liếc mắt tưởng chừng bất chợt lúc đó lại bị hắn phát hiện.\nTrên người hắn quả thực có bản năng của dã thú."
  },
  AvgDialog_13735_Content_17 = {
    Text = "Thầy tôi từng nói với tôi……"
  },
  AvgDialog_13735_Content_18 = {
    Text = "Vào thời La Mã cổ đại, có một thuật sĩ giả kim điên cuồng đã dùng vô số người làm vật tế, luyện chế ra ma tượng đầu tiên."
  },
  AvgDialog_13735_Content_19 = {
    Text = "Đây cũng là thực thể gần nhất với Giác Tỉnh Thể trong các văn hiến cổ đại."
  },
  AvgDialog_13735_Content_2 = {
    Text = "Phía bắc sa mạc Kusi, đêm"
