  AvgDialog_13735_Content_21 = {
    Text = "Không sai……là ta. Ta đã trở thành tay sai của <Blue:Caligula>, thay hắn giết rất nhiều người."
  },
  AvgDialog_13735_Content_22 = {
    Text = "Sau đó bọn họ không cần ta nữa, liền nhốt ta trong hầm ngục tối đen không thấy tay, cho đến khi tên đó thả ta ra."
  },
  AvgDialog_13735_Content_23 = {
    Text = "Yuu Hashi vừa nói, ánh mắt lướt qua Purin vẫn đang ngủ say trong lều."
  },
  AvgDialog_13735_Content_24 = {
    Text = "——Điều kiện là gì?"
