  AvgDialog_13735_Content_25 = {
    Text = "Điều kiện là, trước tiên làm chó cho hắn, ra chiến trường giết thật nhiều người Lemwashi."
  },
  AvgDialog_13735_Content_26 = {
    Text = "Sau đó chúng ta đường ai nấy đi, mỗi người sống cuộc sống của mình."
  },
  AvgDialog_13735_Content_27 = {
