  AvgDialog_13735_Content_3 = {
    Text = "Khò……khò……phì……"
  },
  AvgDialog_13735_Content_30 = {
    Text = "<Red:Có nhiều người, thì sẽ có nhiều máu.>"
  },
  AvgDialog_13735_Content_31 = {
    Text = "<RedShake:Phải biết rằng, ta đã gần nghìn năm chưa được nếm mùi vị của những dòng máu ấy rồi……>"
  },
  AvgDialog_13735_Content_33 = {
    Text = "Gã đó trông không giống kiểu người biết giữ lời hứa. Lỡ hắn lừa cậu thì sao?"
  },
  AvgDialog_13735_Content_34 = {
    Text = "Thì giết hắn. Đơn giản thôi, phải không?"
  },
  AvgDialog_13735_Content_36 = {
    Text = "Phải thừa nhận, lời hắn nói rất có lý."
  },
  AvgDialog_13735_Content_37 = {
    Text = "Gió đêm nhẹ nhàng thổi qua, những đụn cát nhấp nhô mềm mại trải dài trước mắt bạn, dưới bầu trời bao la chỉ còn lại hai bóng hình nhỏ bé."
  },
  AvgDialog_13735_Content_38 = {
    Text = "Bạn ngẩng đầu ngắm nhìn bầu trời đầy sao."
  },
  AvgDialog_13735_Content_39 = {
    Text = "Để giết thời gian trong đêm dài này, bạn quyết định trò chuyện đôi chút với vị Ma Tượng trước mặt."
  },
  AvgDialog_13735_Content_4 = {
    Text = "Tiếng ngáy vang như sấm trong đêm tĩnh lặng, có vẻ chuyện nhỏ ban ngày chẳng ảnh hưởng gì đến giấc ngủ ngon của Pulin."
  },
  AvgDialog_13735_Content_40 = {
    Text = "Bị nhốt dưới lòng đất chắc hẳn rất khó chịu.\nSau khi hoàn thành giao ước, ngươi sẽ được tự do, giờ cảm thấy thế nào?"
  },
  AvgDialog_13735_Content_41 = {
    Text = "Thế còn ngươi?\nNgươi cũng đã không còn là nô lệ từ lâu rồi, suốt ngày lang thang kiếm sống trong sa mạc, cảm giác thế nào?"
  },
  AvgDialog_13735_Content_43 = {
    Text = "Quả thật chẳng tốt đẹp gì. Cái nơi quỷ quái này đến mặt trời cũng chẳng thấy……"
  },
  AvgDialog_13735_Content_44 = {
    Text = "Ngươi đúng là mù thật. Mặt trời to thế giữa sa mạc mà không thấy à?"
  },
  AvgDialog_13735_Content_45 = {
    Text = "Ngươi không hiểu đâu. Ta nói là loại mặt trời dịu dàng, tươi sáng, phơi mình dưới nắng ấm áp ấy…… Ở sa mạc thì làm gì có."
  },
  AvgDialog_13735_Content_46 = {
    Text = "Bạn ngáp một cái, cơn buồn ngủ dần dần ập đến.\nThần kinh vừa lơi lỏng, cuộc trò chuyện cũng trở nên thoải mái hơn hẳn."
  },
  AvgDialog_13735_Content_47 = {
    Text = "Ngoài dự liệu của bạn, Yuwuhashi cũng tạm coi là một người biết lắng nghe."
  },
  AvgDialog_13735_Content_48 = {
    Text = "Nói ra ngươi có thể không tin, thực ra ta cũng đang mang nhiệm vụ trên người……"
  },
  AvgDialog_13735_Content_49 = {
    Text = "Đợi đến ngày hoàn thành hết những việc cần làm, ta nhất định sẽ tìm một nơi nằm phơi nắng, ăn thật nhiều thật nhiều bánh ngọt nhỏ……"
  },
  AvgDialog_13735_Content_5 = {
    Text = "Bạn không thể chịu nổi nữa, cuối cùng vén lều bước ra ngoài."
  },
  AvgDialog_13735_Content_50 = {
    Text = "……Khó hiểu."
  },
  AvgDialog_13735_Content_51 = {
    Text = "Ma Tượng sinh ra từ bóng tối, bản tính vốn sợ ánh mặt trời, gần ngàn năm bị giam cầm càng khiến hắn thêm ghét ánh nắng."
  },
  AvgDialog_13735_Content_52 = {
    Text = "Ta thật thấy tiếc cho ngươi, phơi nắng là chuyện vui sướng nhất trên đời……"
  },
  AvgDialog_13735_Content_53 = {
    Text = "Tiếc là đối với ta, ngay cả một ước nguyện như vậy cũng khó mà thực hiện……"
  },
  AvgDialog_13735_Content_54 = {
    Text = "Gió nổi lên rồi.\nNhững hạt cát mịn bay lơ lửng dệt thành từng lớp từng lớp lụa mỏng vàng nhạt, nhẹ nhàng phiêu đãng dưới bầu trời đêm đầy sao."
  },
  AvgDialog_13735_Content_55 = {
    Text = "Bạn lắng nghe tiếng gió trong lành vọng đến từ phương xa, rồi cuối cùng chìm vào giấc ngủ."
  },
  AvgDialog_13735_Content_57 = {
    Text = "Phía bắc sa mạc Kushi, ban ngày"
  },
  AvgDialog_13735_Content_58 = {
    Text = "Thật là quỷ tha ma bắt! Trước đó cậu chẳng phải vỗ ngực đảm bảo mấy ngày gần đây không thể có bão cát sao?!"
  },
  AvgDialog_13735_Content_59 = {
    Text = "Purin trợn mắt chỉ tay về phía cuồng sa cuồn cuộn ập đến từ chân trời."
  },
  AvgDialog_13735_Content_6 = {
    Text = "Đẹp quá……"
  },
  AvgDialog_13735_Content_60 = {
    Text = "Giờ cậu nói cho tôi biết, <Big:@1 đó là cái gì?>"
  },
  AvgDialog_13735_Content_61 = {Text = "Ờ……"},
  AvgDialog_13735_Content_62 = {
    Text = "Trước khi bạn \"nhập mộng\", chủ nhân cũ vì muốn chặt chém con cừu béo này, quả thực đã đưa ra một số lời hứa trái lòng."
  },
  AvgDialog_13735_Content_63 = {
    Text = "Giờ không phải lúc cãi nhau, bão cát sắp đến rồi, còn không mau chạy đi——"
  },
  AvgDialog_13735_Content_64 = {
    Text = "Nói xong bạn liền lao ra ngoài với tốc độ nhanh nhất, bỏ Purin lại tít phía sau."
  },
  AvgDialog_13735_Content_65 = {
    Text = "<Big:Này……đứng lại cho tôi!>"
  },
  AvgDialog_13735_Content_66 = {
    Text = "Bão cát? Là cái gì thế, phong cảnh trông có vẻ đẹp mà."
