  AvgDialog_13735_Content_67 = {
    Text = "Uu Hashi quay lưng chạy nhẹ nhàng đến bên cạnh bạn, mắt vẫn không chớp nhìn chằm chằm về phía xa."
  },
  AvgDialog_13735_Content_68 = {
    Text = "Cậu chưa bao giờ thấy bão cát à?"
