  AvgDialog_13735_Content_69 = {
    Text = "Uu Hashi nhún vai."
  },
  AvgDialog_13735_Content_7 = {
    Text = "Chào buổi tối, ngài hướng đạo."
  },
  AvgDialog_13735_Content_70 = {
    Text = "Phạm vi hoạt động trước đây của tôi chỉ giới hạn trong thành Roma, thứ chưa từng thấy thì nhiều lắm."
