  },
  AvgDialog_13735_Content_78 = {
    Text = "Nói rồi Uukhashi nhẹ nhàng kẹp pháp sư dưới nách, chân trước bước ra một bước, nửa bàn chân sau đạp đất, cong cả người lại."
  },
  AvgDialog_13735_Content_79 = {
    Text = "Này……ta cảnh cáo ngươi, bây giờ không phải lúc đùa giỡn——<Big:AAAAAH!!!>"
  },
  AvgDialog_13735_Content_8 = {Text = "!!"},
  AvgDialog_13735_Content_80 = {
    Text = "Uukhashi đột ngột đạp mạnh chân, lao vút đi như mũi tên rời dây cung."
  },
  AvgDialog_13735_Content_81 = {
    Text = "Ta, ngươi……thằng @1 thối, thả ta xuống!"
  },
  AvgDialog_13735_Content_82 = {
    Text = "Uukhashi bật ra những tràng cười lớn.\nTiếng cười bay trong gió, đan xen cùng cát vàng mịn và bụi trần, hân hoan lao về phía xa."
  },
  AvgDialog_13735_Content_83 = {
    Text = "Không được đâu, ta còn phải giữ mạng ngươi để giúp ta lấy lại tự do cơ mà!"
  },
  AvgDialog_13735_Content_9 = {
