  },
  AvgDialog_13736_Content_101 = {
    Text = "Lính đánh thuê toàn là lũ không có tín ngưỡng. Còn nô lệ thì càng không thể hiểu được tôn nghiêm và vinh dự là gì."
  },
  AvgDialog_13736_Content_102 = {
