  },
  AvgDialog_13736_Content_2 = {
    Text = "@2 năm, Giáo hoàng thất thế, vương quyền trỗi dậy\nThánh thành Acre trở thành vùng đất tranh giành\n\nVì kiêng dè thế lực Mamluk do Baibars đứng đầu\nVương tử kêu gọi toàn dân xuất chinh viễn Đông, đoạt lại Thánh thành Acre"
  },
  AvgDialog_13736_Content_20 = {
    Text = "Hắn duy trì tư thế ngồi xổm, đôi cánh tay dài tùy ý chống trên mặt đất, giống như một con mãnh thú đang chực chờ."
  },
  AvgDialog_13736_Content_21 = {
