  },
  AvgDialog_13736_Content_31 = {
    Text = "Hắn lấy tay quệt dòng máu tươi chảy từ góc trán, đưa lòng bàn tay lên trước mũi hít ngửi, rồi bất ngờ thong thả liếm máu trên đầu ngón tay."
