  },
  AvgDialog_13736_Content_78 = {
    Text = "Lính đào ngũ cũng cần ăn, nên giờ tôi kiếm sống bằng nghề hướng dẫn.\nYên tâm đi, ưu điểm lớn nhất của tôi là làm việc cực kỳ nghiêm túc."
