  AvgDialog_13736_Content_80 = {Text = "Phụt."},
  AvgDialog_13736_Content_81 = {
    Text = "Xem đủ màn hề trước mắt rồi, Yuuhashi vươn vai một cái, thong thả bước đến trước mặt cậu."
