  AvgDialog_13736_Content_93 = {Text = "Hừ……"},
  AvgDialog_13736_Content_94 = {
    Text = "Năm xưa lính đánh thuê Mamluk tàn sát hàng vạn đồng bào của ta, vợ ta, chiến hữu, sư phụ…… tất cả đều bỏ mạng nơi đây."
