  },
  AvgDialog_13739_Content_22 = {
    Text = "Hắn bước những bước chân nặng nhọc, chậm rãi tiến về phía ngươi."
  },
  AvgDialog_13739_Content_23 = {
    Text = "Sau đó hắn dùng răng cắn rách cổ tay mình."
