  AvgDialog_13739_Content_24 = {
    Text = "Dòng máu đỏ tươi nồng nặc tuôn trào như suối, nhỏ giọt lên đỉnh đầu ngươi, lên mí mắt, rồi chảy dọc sống mũi xuống đôi môi khô nứt."
