  AvgDialog_13739_Content_38 = {
    Text = "Tầm nhìn cuối cùng cũng bị màn sương máu mịt mù che phủ.\nNgươi nhắm mắt lại, cảm thấy từng cơn chóng mặt, như thể mặt đất đang không ngừng chìm xuống."
