  AvgDialog_139657_Content_81 = {
    Text = "Dù trong khoảnh khắc nhắm mắt lại, tôi vẫn sẽ cảm thấy trọn vẹn và mãn nguyện."
  },
  AvgDialog_139657_Content_82 = {
    Text = "Bởi vì cuộc đời tôi vừa có những ký ức quý giá, vừa có nơi mà dù thế nào cũng phải đến."
  },
  AvgDialog_139657_Content_83 = {
    Text = "Bản thân việc tìm kiếm, đã là ý nghĩa rồi."
  },
  AvgDialog_139657_Content_84 = {
    Text = "Lời nói vừa dứt, xung quanh bỗng yên tĩnh đến mức chỉ còn tiếng xào xạc của bồ công anh đung đưa trong gió nhẹ."
  },
  AvgDialog_139657_Content_85 = {
    Text = "……Saya?"
  },
  AvgDialog_139657_Content_86 = {
    Text = "Saya nhắm mắt lại, sắc mặt cô trắng bệch như tờ giấy mỏng. Tim bạn thắt lại đau đớn."
  },
  AvgDialog_139657_Content_87 = {Text = "Saya……"},
  AvgDialog_139657_Content_88 = {
    Text = "Bạn lo lắng ghé sát lại, nhưng phát hiện hơi thở của Saya nhẹ nhàng và đều đặn, lồng ngực khẽ nhấp nhô theo nhịp thở, như gợn sóng li ti nhất trên mặt hồ."
  },
  AvgDialog_139657_Content_89 = {
    Text = "Chỉ là ngủ thiếp đi thôi mà……"
  },
  AvgDialog_139657_Content_9 = {
    Text = "Những thay đổi bề ngoài này… thực ra không quan trọng lắm."
  },
  AvgDialog_139657_Content_90 = {
    Text = "Mình cũng, hơi, buồn ngủ rồi……"
  },
  AvgDialog_139657_Content_91 = {
    Text = "Dưới cảm giác an tâm ập đến bất ngờ, sự mệt mỏi sau một ngày bôn ba cùng áp lực thị giác từ cảnh tượng đầy thịt cuối cùng cũng chiếm lấy bạn."
  },
  AvgDialog_139657_Content_92 = {
    Text = "Trước khi kết cục đến, đêm nay cũng lặng lẽ trôi qua."
  },
  AvgDialog_139658_Content_1 = {
    Text = "Khi mưa tạnh"
  },
  AvgDialog_139658_Content_10 = {
    Text = "Thật tốt quá, có thể cảm nhận được mặt trời."
  },
  AvgDialog_139658_Content_11 = {
    Text = "Saya mỉm cười, đưa tay chạm về phía ánh nắng chiếu vào, như một cây non vươn mình đón ánh sáng."
  },
  AvgDialog_139658_Content_12 = {
    Text = "Có thể dìu mình ra ngoài xem được không?"
  },
  AvgDialog_139658_Content_13 = {
    Text = "Bạn dìu Saya ra ngoài, để cô tựa lưng vào tường ngồi xuống bên cạnh căn nhà nhỏ. Dù chỉ là đoạn đường ngắn ngủi ấy, Saya cũng không giấu nổi hơi thở hổn hển."
  },
  AvgDialog_139658_Content_14 = {
    Text = "Saya, cơ thể cậu……"
  },
  AvgDialog_139658_Content_15 = {
    Text = "Đừng bận tâm, mình nghĩ thời gian sắp đến rồi."
  },
  AvgDialog_139658_Content_16 = {
    Text = "Cậu cũng cảm nhận được đúng không? Bức tường rào cản trở liên kết giữa chúng ta…… đang dần tiêu tan."
  },
  AvgDialog_139658_Content_17 = {
    Text = "Chỉ một lát nữa thôi, chắc chắn sẽ sụp đổ hoàn toàn.\nĐến lúc đó... có lẽ sẽ có thể thiết lập \"liên kết\" mà cậu nói rồi nhỉ."
  },
  AvgDialog_139658_Content_18 = {
    Text = "Nhưng mà……"
  },
  AvgDialog_139658_Content_19 = {
    Text = "Sau khi liên kết, Saya có lẽ sẽ biến mất. Bức tường chắn kia là bức tường cô ấy dựng lên để bảo vệ bản thân, nên mới trở nên mong manh vì sự suy yếu của cô ấy."
  },
  AvgDialog_139658_Content_2 = {
    Text = "Khi bạn tỉnh dậy, ánh sáng đã thay đổi."
  },
  AvgDialog_139658_Content_20 = {
    Text = "Xin đừng bận tâm. Khoảnh khắc này, có cậu ở bên cạnh bầu bạn, trò chuyện, tôi rất vui đấy."
  },
  AvgDialog_139658_Content_21 = {
    Text = "Saya khẽ nheo mắt, nở nụ cười chân thành nhưng yếu ớt. Cậu không nỡ nhìn thẳng, nhưng vẫn cố gắng khắc ghi nụ cười của cô ấy vào ký ức."
  },
  AvgDialog_139658_Content_22 = {
    Text = "Tôi sẽ luôn ở bên cạnh cậu."
  },
  AvgDialog_139658_Content_23 = {
    Text = "Thôi nào, đừng lộ vẻ mặt u sầu như thế. Chúng ta tiếp tục chủ đề hôm qua đi."
  },
  AvgDialog_139658_Content_24 = {
    Text = "Cậu nói, dù không thể chống lại Dung Thực, dù xung quanh không còn ai, cậu vẫn muốn tiếp tục tiến về phía trước."
  },
  AvgDialog_139658_Content_25 = {
    Text = "Tôi rất tò mò, tại sao vậy?"
  },
  AvgDialog_139658_Content_26 = {
    Text = "Tại sao nhỉ? Ánh nắng sau cơn mưa hơi chói mắt, khiến cậu không kìm được muốn rơi nước mắt."
  },
  AvgDialog_139658_Content_27 = {
    Text = "Cậu hít một hơi thật sâu."
  },
  AvgDialog_139658_Content_28 = {
    Text = "Bởi vì tôi yêu Ramona, yêu tất cả đồng đội ở Đại học Misaga.\nĐồng thời, tôi tin chắc rằng họ cũng yêu tôi."
  },
  AvgDialog_139658_Content_29 = {
    Text = "Nhưng các cậu cách nhau rất xa rất xa, không thể chạm vào nhau, không thể xác nhận tâm ý của nhau."
  },
  AvgDialog_139658_Content_3 = {
    Text = "Trong không khí ẩm ướt có một mùi trong lành như vừa được gột rửa, thứ lọt qua khe cửa không phải gió, mà là một tia sáng yên tĩnh."
  },
  AvgDialog_139658_Content_30 = {
    Text = "Huống chi thế giới của bạn tồn tại hiện tượng bất thường gọi là\"Dung Thực\", làm sao bạn có thể chắc chắn rằng người bạn thương nhớ chưa quên đi sự tồn tại của bạn?"
  },
  AvgDialog_139658_Content_31 = {
    Text = "Giọng cô ấy mang theo sự nhẹ nhàng gần như mê sảng."
  },
  AvgDialog_139658_Content_32 = {
    Text = "Dung Thực có thể xóa bỏ sự tồn tại, nhưng Ngân Tâm đã liên kết tôi và Ramona trong đại dương tiềm thức."
  },
  AvgDialog_139658_Content_33 = {
    Text = "Cậu nhìn về phía xa. Đường chân trời sau cơn mưa rõ ràng đến không thể tin được, tầng mây bị gió xé ra một vết nứt, những cột sáng vàng kim từ khe hở tuôn trào xuống, rơi trên dãy núi phía xa."
  },
  AvgDialog_139658_Content_34 = {
    Text = "Tôi có thể cảm nhận được sự tồn tại của cô ấy, dù là khoảnh khắc này cũng vậy, dù chúng tôi bị buộc phải phân tán ở những thế giới khác nhau cũng vậy."
  },
  AvgDialog_139658_Content_35 = {
    Text = "Hơn nữa……"
  },
  AvgDialog_139658_Content_36 = {Text = "Ừm?"},
  AvgDialog_139658_Content_37 = {
    Text = "Cô ấy hơi nghiêng đầu sang."
  },
  AvgDialog_139658_Content_38 = {
    Text = "Người yêu thương thực sự không cần ở bên cạnh cũng có thể cảm nhận được nhau, cũng có thể xác nhận tình yêu của nhau."
  },
  AvgDialog_139658_Content_39 = {
    Text = "Dù cho ngày tận thế có luân hồi bất tận, tôi cũng nhất định sẽ tìm được Ramona. Và cô ấy cũng nhất định sẽ đưa ra cùng một lựa chọn."
  },
  AvgDialog_139658_Content_4 = {
    Text = "……Bên ngoài yên tĩnh quá."
  },
  AvgDialog_139658_Content_40 = {
    Text = "Tôi có linh cảm đó. Nỗi nhớ nhung kết nối chúng tôi trong biển tinh thần, sẽ mãi mãi không bao giờ đứt đoạn."
  },
  AvgDialog_139658_Content_41 = {
    Text = "Saya im lặng rất lâu, cơn gió sau mưa xuyên qua căn nhà nhỏ, lướt qua đôi má gần như không còn chút huyết sắc của cô."
  },
  AvgDialog_139658_Content_42 = {
    Text = "Rồi, cô ấy mỉm cười."
  },
  AvgDialog_139658_Content_43 = {
    Text = "Thật là, một niềm tin mãnh liệt và kiên định, thật là, một tình yêu vĩ đại…"
  },
  AvgDialog_139658_Content_44 = {
    Text = "Khi cô ấy nói chữ \"yêu\", trong giọng nói không có ghen tị, không có bi thương, không có tiếc nuối."
  },
  AvgDialog_139658_Content_45 = {
    Text = "Chỉ có sự dịu dàng."
  },
  AvgDialog_139658_Content_46 = {
    Text = "Giống như một lữ khách cô độc lặn lội trong đêm đông dài đằng đẵng, cuối cùng cũng nhìn thấy tia sáng bình minh đầu tiên nơi chân trời — cô chưa chắc đã đi được đến đó, nhưng chỉ cần ánh sáng tồn tại, thế đã là đủ."
  },
  AvgDialog_139658_Content_47 = {
    Text = "Saya cười ngẩn ngơ."
  },
  AvgDialog_139658_Content_48 = {
    Text = "Rồi, cô ấy chìa tay về phía bạn."
  },
  AvgDialog_139658_Content_49 = {
    Text = "……Nắm lấy tay tôi."
  },
  AvgDialog_139658_Content_5 = {
    Text = "Mưa…… đã tạnh rồi sao?"
  },
  AvgDialog_139658_Content_50 = {
    Text = "Bàn tay ấy trắng nhợt, mảnh mai, run rẩy nhẹ, cô không thể nhìn thấy bạn, nhưng bàn tay cô lại chính xác không sai lệch vươn về hướng bạn đang đứng —"
  },
  AvgDialog_139658_Content_51 = {
    Text = "Như thể có thứ gì đó cổ xưa hơn thị giác, sâu thẳm hơn ngôn ngữ, đang dẫn lối cho cô."
  },
  AvgDialog_139658_Content_52 = {
    Text = "Bạn chìa tay ra, nắm lấy cô."
  },
  AvgDialog_139658_Content_53 = {
    Text = "Ngay khoảnh khắc lòng bàn tay hai người chạm vào nhau —"
  },
  AvgDialog_139658_Content_54 = {
    Text = "Hốc mắt bỗng đau nhói dữ dội."
  },
  AvgDialog_139658_Content_55 = {
    Text = "Thứ gì đó sắc bén hơn, thiêu đốt hơn rất nhiều, như một tia sét xẻ đôi hộp sọ bạn, xuyên thẳng vào tận nơi sâu nhất của ý thức."
  },
  AvgDialog_139658_Content_56 = {
    Text = "Tầm nhìn bắt đầu rung lắc dữ dội."
  },
  AvgDialog_139658_Content_57 = {
    Text = "Bạn nhìn thấy những bông bồ công anh ướt đẫm dưới ánh nắng, khuôn mặt nghiêng trắng nhợt nhưng thanh thản của Saya, nụ cười nở trên đôi môi nứt nẻ của cô —"
  },
  AvgDialog_139658_Content_58 = {
    Text = "Rồi tất cả đột ngột biến thành vũ trụ của máu thịt, bầu trời đỏ máu, mặt đất đỏ máu, ngay cả Saya trước mắt cũng —"
  },
  AvgDialog_139658_Content_59 = {
    Text = "Không——"
  },
  AvgDialog_139658_Content_6 = {
    Text = "Đôi mắt Saya hướng về phía cửa sổ, nhưng ánh mắt ấy không có điểm dừng."
  },
  AvgDialog_139658_Content_60 = {
    Text = "Hai cảnh tượng luân phiên lóe sáng, chồng chéo, hòa quyện trong tầm nhìn của bạn, hai dòng sông vốn nên song song bỗng va vào nhau tại một điểm giao nhau bất khả thi."
  },
  AvgDialog_139658_Content_61 = {
    Text = "Liên kết giữa bạn và Saya đã hoàn thành."
  },
  AvgDialog_139658_Content_7 = {
    Text = "Ánh nắng chiếu vào đáy mắt cô, như một viên sỏi ném xuống mặt nước, nhưng không gợn lên bất kỳ làn sóng nào."
  },
  AvgDialog_139658_Content_8 = {
    Text = "Mưa tạnh rồi."
  },
  AvgDialog_139658_Content_9 = {
    Text = "Giọng bạn khô khốc khó nhọc."
  },
  AvgDialog_139659_Content_1 = {
    Text = "\"Tình yêu\""
  },
  AvgDialog_139659_Content_10 = {
    Text = "Saya đứng giữa cánh đồng hoa bồ công anh trong buổi sáng sớm."
  },
  AvgDialog_139659_Content_11 = {
    Text = "Sau trận mưa rửa trôi, vô số hạt giống bồ công anh rơi xuống mặt đất đỏ đen, một số thậm chí đã bắt đầu nảy mầm sinh trưởng."
  },
  AvgDialog_139659_Content_12 = {
    Text = "Một đêm mà sinh, một đêm mà nở..."
  },
  AvgDialog_139659_Content_13 = {
    Text = "Nhìn vẻ mặt cậu, có phải đã nhớ ra điều gì sao?"
