  AvgDialog_139659_Content_14 = {
    Text = "Ừm, tôi từng thấy cảnh tượng tương tự ở sa mạc Yalan."
  },
  AvgDialog_139659_Content_15 = {
    Text = "Mảnh đất nơi đó được ban phước bởi \"Phong Nhương Mẫu Thụ\", hậu duệ của chủng tộc chạm đất liền sinh, đón gió mà lớn."
  },
  AvgDialog_139659_Content_16 = {
    Text = "Vậy chẳng phải rất tốt sao?"
  },
  AvgDialog_139659_Content_17 = {
    Text = "...Nhưng mà, nghe giọng cậu, có vẻ như cậu không cho rằng điều đó tốt đẹp lắm."
  },
  AvgDialog_139659_Content_18 = {
    Text = "Là người ngoài cuộc, tôi không tiện đưa ra nhận xét."
  },
  AvgDialog_139659_Content_19 = {
    Text = "Chỉ là, đối với nhiều người, mỗi giai đoạn của cuộc đời đều rất quan trọng."
  },
  AvgDialog_139659_Content_2 = {
    Text = "Bạn và Saya mỗi người co mình trong một góc căn nhà nhỏ, cả đêm không nói lời nào."
  },
  AvgDialog_139659_Content_20 = {
    Text = "Chẳng hạn như đứa trẻ tên Nefrurei kia… cậu bé chưa bao giờ trải qua một tuổi thơ thực sự, chưa được hưởng tình yêu thương từ cha mẹ, đã vội vàng bước lên chiến trường đối đầu với Bức Tường Bão Tố…"
  },
  AvgDialog_139659_Content_21 = {
    Text = "Saya gật đầu tỏ vẻ hiểu mà chưa hiểu hết."
  },
  AvgDialog_139659_Content_22 = {
    Text = "Ý cậu là, đối với con người, chiều dài của sinh mệnh cũng rất quan trọng, đúng không?"
  },
  AvgDialog_139659_Content_23 = {
    Text = "Không chỉ vậy, mỗi sự việc trải qua trong đời, mỗi người gặp gỡ, đều sẽ hóa thành một phần ký ức trong tương lai."
  },
  AvgDialog_139659_Content_24 = {
    Text = "Sự tích lũy của những ký ức ấy tạo nên chính bản thân mỗi người."
  },
  AvgDialog_139659_Content_25 = {
    Text = "Thậm chí có thể nói, con người là vật mang ký ức.\nDù thể xác tiêu vong, ký ức vẫn sẽ được truyền thừa, cho đến khi bị tất cả mọi người lãng quên."
  },
  AvgDialog_139659_Content_26 = {
    Text = "Vậy à… tôi hiểu rồi."
  },
  AvgDialog_139659_Content_27 = {
    Text = "Vậy, nếu có một ngày tôi chết đi, kỷ niệm hôm nay của tôi và cậu ở đây, cũng sẽ trở thành một phần của cậu sao?"
  },
  AvgDialog_139659_Content_28 = {
    Text = "Sẽ như vậy."
  },
  AvgDialog_139659_Content_29 = {
    Text = "Trong nụ cười yếu ớt của Saya, bạn kiên định gật đầu."
  },
  AvgDialog_139659_Content_3 = {
    Text = "Không biết từ lúc nào, bạn đã chìm vào giấc ngủ sâu dưới sự thúc giục của mệt mỏi."
  },
  AvgDialog_139659_Content_30 = {
    Text = "Ngày hôm ấy, lại trôi qua trong việc khám phá và quanh quẩn nơi biên giới."
  },
  AvgDialog_139659_Content_31 = {
    Text = "Tuy nhiên bên ngoài cánh đồng hoa bồ công anh, chỉ có từng khung cảnh hoang vu tương tự nhau, mặt đất bị phủ kín bởi huyết nhục đến mức không còn nhận ra hình dạng ban đầu."
  },
  AvgDialog_139659_Content_32 = {
    Text = "Dù bạn cố sức kìm nén, cảm giác bất an vẫn dần dần nảy mầm từ đáy lòng, từng chút một leo lên ý thức của bạn."
  },
  AvgDialog_139659_Content_33 = {
    Text = "(Nếu không tìm thấy gì cả, vậy thì lõi của mật cảnh này chỉ có thể là…)"
  },
  AvgDialog_139659_Content_34 = {
    Text = "Đêm đã khuya."
  },
  AvgDialog_139659_Content_35 = {
    Text = "Nghỉ ngơi cho tốt nhé, tôi thấy hơi mệt rồi."
  },
  AvgDialog_139659_Content_36 = {
    Text = "Vừa hay, tôi cũng muốn nghỉ sớm, như vậy ngày mai mới có thể đi xa hơn để khám phá."
  },
  AvgDialog_139659_Content_37 = {
    Text = "Cùng với cuộc trò chuyện như thế, hai người chìm vào giấc ngủ yên bình."
  },
  AvgDialog_139659_Content_39 = {
    Text = "Bạn bị một âm thanh nào đó đánh thức, chỉ cảm thấy toàn thân nóng bức, như thể đang ở giữa sa mạc."
  },
  AvgDialog_139659_Content_4 = {
    Text = "(Lạnh quá... Hy vọng ngày mai được ngủ trên chiếc giường ấm áp...)"
  },
  AvgDialog_139659_Content_40 = {Text = "?!!"},
  AvgDialog_139659_Content_41 = {
    Text = "Bạn cảm thấy đầu óc mình choáng váng, không biết là vì cảnh tượng kỳ quái trước mắt, hay vì làn khói mờ ảo đang lan tỏa trong không trung."
  },
  AvgDialog_139659_Content_42 = {
    Text = "Hoặc là do ảnh hưởng của Thánh Hà Mẫu Thụ."
  },
  AvgDialog_139659_Content_43 = {
    Text = "Thật là tiếc, người mà bạn đang mong đợi không phải là tôi sao?"
  },
  AvgDialog_139659_Content_44 = {
    Text = "Nữ hoàng của Aran —— Thái Di Sơ kéo rèm bước vào, cô ấy không chút e dè tiến lại gần, lớp vải mỏng như không của chiếc áo choàng dán chặt vào cánh tay nhỏ nhắn của bạn, phát ra lời mời rõ ràng."
  },
  AvgDialog_139659_Content_45 = {
    Text = "Nào, hãy tiếp nhận dòng máu của Á Lan và trở thành một phần của chúng ta."
  },
  AvgDialog_139659_Content_46 = {
    Text = "Lại gần tôi, ôm lấy tôi… Hãy cho tôi máu của bạn, dòng giống của bạn…"
  },
  AvgDialog_139659_Content_47 = {
    Text = "Ánh lửa nhảy múa trong còng kinh cuồng nhiệt của cô, khuôn mặt ửng đỏ phảng phất sự khao khát bệnh hoạn."
  },
  AvgDialog_139659_Content_48 = {
    Text = "Chỉ cần một giọt thôi, chỉ cần xương máu của chúng ta hòa quyện, Người sẽ ban cho chúng ta tương lai mà chúng ta khao khát.."
  },
  AvgDialog_139659_Content_49 = {
    Text = "Hãy… sinh ra con cái cho bộ tộc, cùng tận hưởng sự vĩnh cửu…"
  },
  AvgDialog_139659_Content_5 = {
    Text = "Trong cơn mơ màng, bạn cảm thấy có thứ gì đó bao phủ lấy mình."
  },
  AvgDialog_139659_Content_50 = {
    Text = "Bạn cố gắng vận dụng lý trí để chống lại sự mê hoặc của Taiyisi, nhưng tiếng chuông từng đánh thức bạn năm xưa mãi không vang lên."
  },
  AvgDialog_139659_Content_51 = {
    Text = "Trong lúc giằng co, bạn bỗng nghe thấy một âm thanh mới len lỏi vào tai."
  },
  AvgDialog_139659_Content_52 = {
    Text = "Tại sao, tại sao lại từ chối chứ?"
  },
  AvgDialog_139659_Content_53 = {
    Text = "Không biết từ lúc nào, thiếu nữ đã chui ra từ một góc lều trại."
  },
  AvgDialog_139659_Content_54 = {
    Text = "Khác với giọng điệu vui tươi thường ngày, dường như ẩn chứa một thứ cảm xúc đặc biệt nào đó."
  },
  AvgDialog_139659_Content_55 = {
    Text = "Việc \"sinh sản\" này, tôi nghĩ là điều tốt, cũng là mục đích của mọi sinh mệnh……"
  },
  AvgDialog_139659_Content_56 = {
    Text = "Vậy tại sao không chấp nhận?"
  },
  AvgDialog_139659_Content_57 = {
    Text = "Tại sao, tại sao lại từ chối chứ?"
  },
  AvgDialog_139659_Content_58 = {
    Text = "Bởi vì điều này không liên quan đến tình yêu, đây chỉ là cám dỗ."
  },
  AvgDialog_139659_Content_59 = {
    Text = "Cám dỗ không phải là yêu, sứ mệnh không phải là yêu, dục vọng cũng không phải là yêu."
  },
  AvgDialog_139659_Content_6 = {Text = "... Uh?"},
  AvgDialog_139659_Content_60 = {
    Text = "Yêu là—"
  },
  AvgDialog_139659_Content_61 = {
    Text = "Yêu là—"
  },
  AvgDialog_139659_Content_62 = {
    Text = "Bạn ngất đi."
  },
  AvgDialog_139659_Content_63 = {
    Text = "Tất cả chìm vào bóng tối dài đằng đẵng."
  },
  AvgDialog_139659_Content_7 = {
    Text = "Trên người bạn đắp một lớp chăn mỏng."
  },
  AvgDialog_139659_Content_8 = {
    Text = "Trời đã tạnh rồi."
  },
  AvgDialog_139659_Content_9 = {
    Text = "Ra ngoài xem thử nào."
  },
  AvgDialog_139660_Content_1 = {Text = "\"Ký Ức\""},
  AvgDialog_139660_Content_10 = {
    Text = "Tôi đúng là không phải người bình thường, tôi là điều tra viên đến từ Đại học Misager."
  },
  AvgDialog_139660_Content_11 = {
    Text = "Ánh mắt Saya đầy nghi hoặc, rõ ràng những danh từ này đối với cô ấy đều quá xa lạ."
  },
  AvgDialog_139660_Content_12 = {
    Text = "Nếu giải thích chi tiết thì sẽ quá dài dòng. Bây giờ tôi có chuyện quan trọng hơn cần giải quyết."
  },
  AvgDialog_139660_Content_13 = {
    Text = "Đồng đội của tôi, Ramona, tôi nhìn thấy cô ấy bị thứ gì đó nuốt chửng, cô ấy biến thành……"
  },
  AvgDialog_139660_Content_14 = {
    Text = "Bạn không nói hết. Bạn không thể nào nói hết được."
  },
  AvgDialog_139660_Content_15 = {
    Text = "Ngôn từ chẳng qua chỉ là những ký hiệu khô khan, không thể truyền tải nỗi sợ hãi mà bạn cảm nhận được trong khoảnh khắc ấy, lan tỏa từ đáy cột sống lên."
  },
  AvgDialog_139660_Content_16 = {
    Text = "Nỗi sợ hãi về khả năng mất đi Ramona mãi mãi."
  },
  AvgDialog_139660_Content_17 = {
    Text = "Cô ấy là người không thể thay thế đối với tôi."
  },
  AvgDialog_139660_Content_18 = {
    Text = "Ánh mắt Saya chợt mất tiêu cự trong giây lát."
  },
  AvgDialog_139660_Content_19 = {
    Text = "Người không thể thay thế……thì ra là vậy."
  },
  AvgDialog_139660_Content_2 = {
    Text = "Chưa kịp để bạn sắp xếp lại bao nhiêu thắc mắc trong lòng, thiếu nữ đã lên tiếng trước."
  },
  AvgDialog_139660_Content_20 = {
    Text = "Hình như tôi cũng từng có…… một người như vậy."
  },
  AvgDialog_139660_Content_21 = {
    Text = "Cô ấy cúi đầu, nhíu mày lẩm bẩm."
  },
  AvgDialog_139660_Content_22 = {
    Text = "Có một người. Một người rất quan trọng. Khuôn mặt người đó…… tôi đáng lẽ phải nhớ. Tôi chắc chắn nhớ mà. Nhưng bây giờ khi tôi cố nghĩ về người ấy, thứ tôi nhìn thấy chỉ có——"
  },
  AvgDialog_139660_Content_23 = {
    Text = "——chỉ có đường viền. Như nhìn qua một lớp kính mờ. Biết người ấy ở đó, biết người ấy rất quan trọng, nhưng mọi chi tiết đều bị…… xóa nhòa đi."
  },
  AvgDialog_139660_Content_24 = {
    Text = "Không chỉ người ấy. Những chuyện khác cũng vậy. Tôi biết tôi có việc phải làm—— việc rất quan trọng."
  },
  AvgDialog_139660_Content_25 = {
    Text = "Nhưng mỗi mảnh ký ức lại mâu thuẫn với nhau. Mảnh này nói anh ấy rất dịu dàng, mảnh tiếp theo lại nói tôi đã ở trong một nơi rất tối tăm rất lâu."
  },
  AvgDialog_139660_Content_26 = {
    Text = "Mảnh này nói tôi đang chờ ai đó đến đón, mảnh tiếp theo lại nói tôi cần làm một việc… sẽ khiến người ta sợ hãi."
  },
  AvgDialog_139660_Content_27 = {
    Text = "Mỗi đoạn đều cảm thấy là thật. Nhưng đặt chúng cạnh nhau thì lại mâu thuẫn với nhau."
  },
  AvgDialog_139660_Content_28 = {
    Text = "Cậu từng thấy trạng thái này."
  },
  AvgDialog_139660_Content_29 = {
    Text = "Đây là triệu chứng được ghi chép trong báo cáo về hiện tượng ăn mòn, không chỉ xảy ra với cô ấy.\nÝ thức mờ nhạt, ký ức phân mảnh, nhận thức bản thân sụp đổ."
  },
  AvgDialog_139660_Content_3 = {
    Text = "Tôi là……ừm, cứ gọi tôi là \"Saya\" đi.\nMà nói vậy, bạn có biết đây là đâu không?"
  },
  AvgDialog_139660_Content_30 = {
    Text = "Tôi không biết đoạn nào mới thực sự đã xảy ra, tôi không biết đâu mới là ký ức thật sự thuộc về chính mình……"
  },
  AvgDialog_139660_Content_31 = {
    Text = "Những ngón tay của Saya co quắp lại, dường như muốn nắm giữ thứ gì đó đã không còn tồn tại."
  },
  AvgDialog_139660_Content_32 = {
    Text = "Theo sự dao động của cô ấy, cậu cảm thấy môi trường xung quanh bắt đầu thay đổi."
  },
  AvgDialog_139660_Content_33 = {
    Text = "Cẩn thận!"
  },
  AvgDialog_139660_Content_34 = {
    Text = "Cậu nhìn ra vùng ngoại vi cánh đồng bồ công anh. Lớp màng thịt phủ dịch đen đang từng tấc từng tấc nghiền ép tới, ranh giới cánh đồng bồ công anh trông ngày càng mong manh."
  },
  AvgDialog_139660_Content_4 = {
    Text = "Tại sao lại ở nơi như thế này nhỉ……\nỪm— cảm giác có rất nhiều chuyện không thể nhớ ra."
  },
  AvgDialog_139660_Content_5 = {
    Text = "……Bạn, có vẻ không phải người bình thường?\nSở hữu sức mạnh đặc biệt gì đó……?"
  },
  AvgDialog_139660_Content_6 = {
    Text = "Bạn không trả lời ngay. Thiếu nữ tên Saya buông tay ra, lùi lại nửa bước, nheo mắt quan sát bạn."
  },
  AvgDialog_139660_Content_7 = {
    Text = "Nhìn thấy tôi, bạn không có cảm giác gì sao? Tại sao lại đến đây?"
  },
  AvgDialog_139660_Content_8 = {
    Text = "Từ từ đã, từng câu hỏi một nào."
  },
  AvgDialog_139660_Content_9 = {
    Text = "Theo kinh nghiệm của tôi, nơi đây rất có thể là một Mật Cảnh."
  },
  AvgDialog_139661_Content_1 = {
    Text = "Tâm tượng phong cảnh"
  },
  AvgDialog_139661_Content_10 = {
    Text = "Một thiếu nữ xinh đẹp, và một chàng trai trẻ."
  },
  AvgDialog_139661_Content_11 = {
    Text = "Họ nắm tay nhau, thân mật bước đi trên hoang nguyên gió cát gào thét."
  },
  AvgDialog_139661_Content_13 = {
    Text = "Cô ấy cười đùa, dang tay ôm lấy gió."
  },
  AvgDialog_139661_Content_14 = {
    Text = "Chàng trai bên cạnh cũng nghiêng người theo, lắng nghe từng tiếng cười trong trẻo của cô."
  },
  AvgDialog_139661_Content_15 = {
    Text = "Bầu trời trong xanh, nhưng mang theo một chút u sầu."
  },
  AvgDialog_139661_Content_16 = {
    Text = "Nhưng từ bóng dáng đồng hành của hai người, bạn cảm nhận được một niềm hạnh phúc tự nhiên dâng trào."
  },
  AvgDialog_139661_Content_17 = {
    Text = "Dù xung quanh không một bóng người, dù không nhận được sự thông cảm hay chúc phúc từ bất kỳ ai, tình yêu ấy vẫn——"
  },
  AvgDialog_139661_Content_18 = {
    Text = "Rồi giấc mộng đột ngột dừng lại, gió cát cuốn đi tất cả."
  },
  AvgDialog_139661_Content_19 = {
    Text = "Thế giới rơi vào bóng tối hư không."
  },
  AvgDialog_139661_Content_2 = {
    Text = "Trời đất đều được tạo thành từ cát."
  },
  AvgDialog_139661_Content_20 = {
    Text = "——Khi ấy, có một ca cơ đang xuyên hành giữa các vì sao."
  },
  AvgDialog_139661_Content_21 = {
    Text = "Giữa một vũ trụ hoang vu, cô ấy đã nhặt được một lõi bạc."
  },
  AvgDialog_139661_Content_22 = {
    Text = "Vào khoảnh khắc cô ấy chạm vào nó, \"tôi\" đã tỉnh giấc."
  },
  AvgDialog_139661_Content_23 = {
    Text = "\"Tôi\" đã mất đi ký ức, chỉ biết rằng phải đi tìm \"người không thể thay thế\" ấy."
  },
  AvgDialog_139661_Content_24 = {
    Text = "\"Tôi\" đã hỏi vị ca cơ ấy liệu có thể đồng hành cùng nhau không, nhưng yêu cầu đó đã bị từ chối."
  },
  AvgDialog_139661_Content_25 = {
    Text = "Tôi phải đi tìm người tôi yêu thương sâu sắc — chị gái của tôi."
  },
  AvgDialog_139661_Content_26 = {
    Text = "Ca cơ đã nói như vậy."
  },
  AvgDialog_139661_Content_27 = {
    Text = "Hy vọng Saya cũng có thể tìm lại được người mình yêu thương. Tôi chân thành mong rằng bạn sẽ có được kết cục như vậy."
  },
  AvgDialog_139661_Content_28 = {
    Text = "Để lại câu nói ấy, ca cơ đã rời đi."
  },
  AvgDialog_139661_Content_29 = {
    Text = "Kể từ đó, tôi — người đã mất đi ký ức quá khứ, cũng mất đi vị ca cơ ấy."
  },
  AvgDialog_139661_Content_3 = {
    Text = "Trong cơn gió vĩnh hằng thổi qua sa mạc, bạn mơ hồ nhìn xuống."
  },
  AvgDialog_139661_Content_30 = {
    Text = "Mang theo lời chúc phúc của cô ấy, một mình bước đi không ngừng trong thế giới này."
  },
  AvgDialog_139661_Content_31 = {
    Text = "Để tìm lại người từng không thể thay thế, để tìm lại ký ức quá khứ……"
  },
  AvgDialog_139661_Content_32 = {
    Text = "Luôn tin rằng, điều đang theo đuổi, nhất định đang ở phía trước."
  },
  AvgDialog_139661_Content_33 = {
    Text = "……Rồi sau đó, gặp được cậu."
  },
  AvgDialog_139661_Content_4 = {
    Text = "Đây là…"
  },
  AvgDialog_139661_Content_5 = {
    Text = "Không có bùn lầy xói mòn, không có thịt rải khắp nơi."
  },
  AvgDialog_139661_Content_6 = {
    Text = "Phong cảnh nơi đây cô độc, thuần khiết và tươi đẹp."
  },
  AvgDialog_139661_Content_7 = {
    Text = "Đây là tâm tượng phong cảnh của tôi đấy."
  },
  AvgDialog_139661_Content_8 = {
    Text = "Là sự tồn tại không thể lãng quên, không gì thay thế được của Saya."
  },
  AvgDialog_139661_Content_9 = {
    Text = "Cát bụi cuồn cuộn bay đi, ở một góc sa mạc, hiện ra hai bóng người."
  },
  AvgDialog_139662_Content_10 = {
    Text = "Tôi sẽ là người hỗ trợ bạn, cùng bạn đến cuối con đường này……<Yellow:Mong rằng chìa khóa bạc sẽ soi sáng con đường phía trước.>"
  },
  AvgDialog_139662_Content_11 = {
