  AvgDialog_142853_Content_16 = {
    Text = "Đây là…"
  },
  AvgDialog_142853_Content_17 = {
    Text = "Bạn áp tai vào trụ đá, mơ hồ nghe thấy một nhịp đập cực kỳ trầm thấp, như thể một sinh vật khổng lồ đang thở chậm rãi trong lòng đá."
  },
  AvgDialog_142853_Content_18 = {
    Text = "Một cơn buồn nôn vô cớ cùng xung động giết chóc ùa vào cơ thể bạn, bạn vội vàng lùi ra."
