  AvgDialog_142853_Content_2 = {
    Text = "Đây là con Đường bạn dẫn?"
  },
  AvgDialog_142853_Content_20 = {
    Text = "Theo truyền thuyết, Tinh Thiên Chi Kình đã dùng thân thể của Ngài tạo ra thế giới này, dân chúng của sáu quốc gia đều tồn tại trên thân thể của Ngài."
  },
  AvgDialog_142853_Content_21 = {
    Text = "Có vẻ như, chúng ta đã rất gần với nó rồi."
  },
  AvgDialog_142853_Content_22 = {
    Text = "Lơ-tan bước đến một chiếc bàn đá ở trung tâm quảng trường. Chiếc bàn đá làm từ đá lapis lazuli đó, với công nghệ tinh xảo và vật liệu đắt tiền, hoàn toàn lạc lõng với nơi hoang tàn này."
  },
  AvgDialog_142853_Content_23 = {
    Text = "Bề mặt bàn đá phủ một lớp vảy nhỏ mịn, ẩm ướt, khẽ mở ra rồi khép lại dưới ánh sáng yếu ớt, nhịp điệu giống hệt tiếng thở mà bạn vừa nghe thấy."
  },
  AvgDialog_142853_Content_24 = {
    Text = "lơ-tan đặt hai Ấn Xương lên đó. Ngay khoảnh khắc Ấn Xương chạm vào vảy, những chiếc vảy ấy đột ngột siết chặt lại, như vô số ngón tay nắm chặt con mồi, nuốt chửng hai con dấu cũ kỹ làm từ xương."
