  AvgDialog_142853_Content_32 = {
    Text = "Bớt nói vòng vo đi."
  },
  AvgDialog_142853_Content_33 = {
    Text = "……Bạn khá vô lễ đấy, thách đấu giả. May mắn thay, Cá Voi Tinh Thiên chưa bao giờ để tâm đến những điều đó."
  },
  AvgDialog_142853_Content_34 = {
    Text = "Điều Ngài quan tâm chỉ có một: Sức mạnh. Sức mạnh thuần túy, không pha lẫn một chút tạp niệm nào."
