  AvgDialog_142853_Content_35 = {
    Text = "Chào mừng, chào mừng đến với Đấu trường của Cá Voi Tinh Thiên, chào mừng đến với sân khấu của sức mạnh thuần túy——"
  },
  AvgDialog_142853_Content_36 = {
