  AvgDialog_142853_Content_37 = {
    Text = "！！！Đây là……"
  },
  AvgDialog_142853_Content_38 = {
    Text = "Tiếng hát lan ra như gợn sóng, nơi những vòng sóng đi qua, bầu trời bị nhuốm một màu đỏ trầm tối, những bức tường đổ nát được chất nhầy bí ẩn bám vào kết nối lại, những tòa nhà hoang tàn hóa thành một Đấu trường cổ đại hùng vĩ."
  },
  AvgDialog_142853_Content_39 = {
    Text = "Những bức tượng thần khổng lồ xung quanh đứng với những tư thế khác nhau, dùng đôi mắt từ bi hoặc giận dữ nhìn xuống những sinh linh nhỏ bé như kiến dưới chân."
  },
  AvgDialog_142853_Content_4 = {
    Text = "Tôi nhớ bản đồ rất rõ, đáng lẽ phải là nơi này mới đúng... Nhưng tại sao nơi này lại khác với những gì được Ghi lại?"
  },
  AvgDialog_142853_Content_40 = {
    Text = "Hơn chục người thách đấu tản ra từng nhóm nhỏ Xung quanh khán đài chính, lặng lẽ quan sát các bạn."
