  AvgDialog_142853_Content_41 = {
    Text = "Một, hai, ba… mười lăm, mười sáu."
  },
  AvgDialog_142853_Content_42 = {
    Text = "Ấn Xương có tất cả hai mươi miếng, phía Sau đáng lẽ còn hai người nữa…"
