  },
  AvgDialog_142853_Content_49 = {
    Text = "Các cuộc họp của Kỵ sĩ đoàn tôi không được phép phát biểu, nhưng cũng đã dự thính nhiều lần. Lãnh chúa Elian đã kể cho chúng tôi nghe rất nhiều……"
  },
  AvgDialog_142853_Content_5 = {
