  AvgDialog_142853_Content_53 = {
    Text = "lơ-tan không để ý đến tiếng reo hò hưng phấn không kìm được của bạn. Cô ấy liếc mắt nhìn qua các thí sinh, dựa vào cột đá và nhắm mắt lại."
