  AvgDialog_142853_Content_6 = {
    Text = "Quốc vương đã nói trong nhật ký của mình rằng, những bức tường nơi đây được làm bằng Vàng, bầu trời nơi đây có những sứ giả thần thánh sáu cánh bay lượn, những dòng sông nơi đây chảy đầy mật và rượu..."
  },
  AvgDialog_142853_Content_60 = {
