  },
  AvgDialog_142853_Content_62 = {
    Text = "Hãy tin tưởng vào Ê-li-an tốt bụng một chút, Cá Voi Tinh Thiên vĩ đại luôn ban Phước lành cho người tốt."
  },
  AvgDialog_142853_Content_63 = {
