  },
  AvgDialog_142853_Content_7 = {
    Text = "Bây giờ cái quảng trường trông như phế tích này là chuyện gì vậy... cũng chẳng thấy ai kiểm tra ấn xương."
  },
  AvgDialog_142853_Content_70 = {
    Text = "Chỉ là một chức hư vị mà thôi, tác dụng duy nhất là tiết kiệm thời gian tự giới thiệu."
