  AvgDialog_142853_Content_71 = {
    Text = "Ê-li-an mỉm cười, ngồi xuống cột đá trước mặt lơ-tan."
  },
  AvgDialog_142853_Content_72 = {
    Text = "Bạn dẫn theo nô bộc của ta đến đây, nhưng đoàn Kỵ sĩ của ta lại biến mất. Ta nghĩ, ta đã hiểu đại khái chuyện gì đã xảy ra trên Đường rồi."
  },
  AvgDialog_142853_Content_73 = {
    Text = "Đoàn Kỵ sĩ của bạn chết thật vô vị. Mười hai người, không chạm được vào giáp trụ của một tên chiến binh hạng bét."
  },
  AvgDialog_142853_Content_74 = {
    Text = "Còn bạn, đã dễ dàng trở thành người chiến thắng trong trận đấu đó."
  },
  AvgDialog_142853_Content_75 = {
    Text = "Bạn dường như không có chút hứng thú nào với cái chết của họ."
