  AvgDialog_142853_Content_8 = {
    Text = "Này! Đợi tôi với..."
  },
  AvgDialog_142853_Content_80 = {
    Text = "Tốc độ nói của Elian ngày càng nhanh hơn. Sát khí và dục vọng quyền lực lan tỏa trong không khí thấm vào người ông, khiến trái tim từng trải phong sương của ông cũng không thể kìm nén mà đập loạn lên."
  },
  AvgDialog_142853_Content_81 = {
    Text = "Dường như nhận ra sự mất bình tĩnh của bản thân, ông hít một hơi thật sâu, lùi lại nửa bước."
