  AvgDialog_142853_Content_84 = {
    Text = "Kẻ yếu thường có thói quen bầy đàn, bạn tất nhiên không phải kiểu người đó. Nhưng, ai cũng có lúc cần hợp tác, bạn cũng không ngoại lệ."
  },
  AvgDialog_142853_Content_85 = {
    Text = "lơ-tan chưa kịp đáp lời, vô số Ảo ảnh giống hệt nhau xuất hiện trên các chỗ ngồi của Đấu trường, lấp đầy kín khán đài, giọng nói tựa tiếng hát của cá voi lại một lần nữa vang khắp Đấu trường rộng lớn này."
  },
  AvgDialog_142853_Content_86 = {
    Text = "Được rồi, các thách đấu giả, chúng ta đã không thể chờ thêm nữa. Thử thách cuối cùng, sắp sửa diễn ra tại Đấu trường huy hoàng này!"
  },
  AvgDialog_142853_Content_87 = {
    Text = "Khi người chiến thắng cuối cùng xuất hiện, một Cửa dẫn đến cung điện của Tinh Thiên Chi Kình sẽ mở ra cho người đó!"
  },
  AvgDialog_142853_Content_88 = {
