  AvgDialog_142853_Content_90 = {
    Text = "Luật lệ? Hê hê hê… Ha ha ha ha! Luật lệ?!…"
  },
  AvgDialog_142853_Content_91 = {
    Text = "Tiếng cười phóng đại của các Ảo ảnh làm đau nhức màng nhĩ của Mọi người trong Đấu trường. Trong tiếng cười Điên loạn đó, chúng không còn lên tiếng nữa, mà háo hức nhìn về phía trung tâm của Đấu trường rộng lớn."
  },
  AvgDialog_142853_Content_92 = {
