  },
  AvgDialog_142853_Content_94 = {
    Text = "Giết chóc, thách đấu, liên minh, phản bội… Mười tám người tham gia, chỉ một người đứng vững, mới có thể bước qua cánh cửa đó."
  },
  AvgDialog_142853_Content_95 = {
