  AvgDialog_142853_Content_96 = {
    Text = "Những gì bạn phải đối mặt sẽ là những người mạnh nhất trên thế giới này."
  },
  AvgDialog_142853_Content_97 = {
    Text = "Xin đừng hiểu lầm, tôi không hề nghi ngờ sức mạnh của bạn, thưa cô lơ-tan."
  },
  AvgDialog_142853_Content_98 = {
    Text = "Nhưng tôi nghĩ, bạn cũng không muốn bị những kẻ nhàm chán làm phiền khi đang tận hưởng những cuộc giết chóc thú vị đó chứ?"
  },
  AvgDialog_142853_Content_99 = {
