  AvgDialog_142854_Content_10 = {
    Text = "Lơ… Lơ-tan đại nhân?"
  },
  AvgDialog_142854_Content_11 = {
    Text = "Bạn không thể nhận ra người đứng trước mặt mình, toàn thân đầy máu, có phải là lơ-tan hay không."
  },
  AvgDialog_142854_Content_12 = {
    Text = "Máu bẩn thỉu, mục nát phủ kín khắp thân thể cô ấy, không biết là từ chính cô ấy hay từ thứ gì khác."
  },
  AvgDialog_142854_Content_13 = {
    Text = "Bên dưới lớp máu bẩn và bộ giáp vỡ vụn ấy, nửa thân mình cô ấy chỉ còn lại những khúc xương trắng hếu."
  },
  AvgDialog_142854_Content_14 = {
    Text = "Người chiến binh chỉ còn nửa thân bước ra từ khe nứt đầy mùi tanh. Bước chân cô ấy chậm chạp, mệt mỏi, thanh đại kiếm gãy lê trên mặt đất, vạch một vệt nông trong vũng máu."
  },
  AvgDialog_142854_Content_15 = {
    Text = "Trên bàn tay còn lại của cô ấy, chiếc Vương Miện được kết tụ từ Máu Tươi đang nhỏ giọt máu bẩn."
  },
  AvgDialog_142854_Content_16 = {
    Text = "Đôi Mắt cô ấy sáng rực hơn bao giờ hết."
