  AvgDialog_142854_Content_18 = {
    Text = "Ngài đã thua."
  },
  AvgDialog_142854_Content_19 = {
    Text = "Giọng lơ-tan không hề run rẩy, dường như chỉ là đang kể lại một điều tất yếu phải xảy ra."
