  AvgDialog_142854_Content_2 = {
    Text = "Khụ… khụ khụ…"
  },
  AvgDialog_142854_Content_20 = {
    Text = "Ngài đã ký Khế Ước với Ngài ấy… Nếu Ngài ấy chịu thương, thì Ngài cũng…"
  },
  AvgDialog_142854_Content_21 = {
    Text = "Bạn không cần hỏi thêm nữa. Những vết thương trên người lơ-tan đã nói lên tất cả."
  },
  AvgDialog_142854_Content_22 = {
    Text = "Lơ-tan đại nhân, ngài đã chiến thắng tất cả những người thách đấu, thậm chí… thậm chí là cả Cá Voi Tinh Thiên!"
  },
  AvgDialog_142854_Content_23 = {
    Text = "Bây giờ, Ngài là vị vương không thể tranh cãi của hành tinh này… Bây giờ là khoảnh khắc huy hoàng nhất trong cuộc đời Ngài! Bây giờ…"
  },
  AvgDialog_142854_Content_24 = {
    Text = "Bây giờ, cũng là lúc cô ấy Mong manh nhất."
  },
  AvgDialog_142854_Content_25 = {
    Text = "Mùi tanh của Máu rỉ ra từ khe nứt bao phủ lấy bạn, tiếng Thầm thì như tiếng hát của cá voi ngày càng rõ ràng hơn bên tai bạn."
  },
  AvgDialog_142854_Content_26 = {
    Text = "Hãy nhìn xem, chiếc Vương Miện được kết tụ từ Máu Tươi…"
  },
  AvgDialog_142854_Content_27 = {
    Text = "Ngai vàng của sáu quốc gia, sự thần phục của hàng triệu người, tài phú và vinh quang không bao giờ cạn kiệt… Chiếc Vương Miện ấy có thể ban cho chủ nhân của nó tất cả mọi thứ."
  },
  AvgDialog_142854_Content_28 = {
    Text = "Mỗi người trong Đấu trường đều khao khát nó. Những Kỵ sĩ ngày ngày Chửi mắng bạn, Graku, chị em nhà Vorn, tướng quân Alish, lão gia Elian toàn năng…"
  },
  AvgDialog_142854_Content_29 = {
