  AvgDialog_142854_Content_3 = {
    Text = "Đây là…"
  },
  AvgDialog_142854_Content_30 = {
    Text = "Bạn nhìn chằm chằm vào chiếc Vương miện Đỏ tươi trên tay lơ-tan. Mỗi giọt Máu Tươi rơi xuống, tiếng Thầm thì của Cá Voi Trời Sao lại càng trở nên rõ ràng hơn."
  },
  AvgDialog_142854_Content_31 = {
    Text = "Bạn sẽ không bao giờ phải sống như một nô lệ nữa, chim sẻ nhỏ."
  },
  AvgDialog_142854_Content_32 = {
    Text = "Bạn sẽ xây cho mẹ bạn một lăng mộ hùng vĩ. Bạn sẽ đón những người anh em từ chuồng ngựa về, cùng họ sống trong cung điện rực rỡ."
  },
  AvgDialog_142854_Content_33 = {
    Text = "Những kẻ từng khinh thường các bạn sẽ quỳ xuống trước mặt bạn, hôn lên mu bàn chân của bạn."
  },
  AvgDialog_142854_Content_34 = {
    Text = "Quyền lực. Quyền lực tối thượng."
  },
  AvgDialog_142854_Content_35 = {
    Text = "Những cái tên lưu truyền trong huyền thoại, tất cả đều chết vì nó… mà giờ đây, nó đang ở trước mắt bạn, gần trong tầm tay."
  },
  AvgDialog_142854_Content_36 = {
    Text = "Hãy đi đi, chim sẻ nhỏ. Trong cuộc đời này của bạn, đây là cơ hội duy nhất của bạn!"
  },
  AvgDialog_142854_Content_37 = {
    Text = "Tiếng thì thầm biến thành tiếng gầm vang, một cơn충động mãnh liệt Sóng động trong tâm trí bạn. Cổ họng khô khốc cuộn lại, bàn tay run rẩy của bạn nâng lên con dao găm nạm châu báu mà Elian để lại. Trên lưỡi dao găm, vẫn còn dính Máu của chính bạn."
  },
  AvgDialog_142854_Content_38 = {
    Text = "Cổ họng khô khốc rung động, bàn tay run rẩy của bạn nâng lên con dao găm nạm đá quý mà Elian để lại. Trên lưỡi dao găm, vẫn còn dính máu của chính bạn."
  },
  AvgDialog_142854_Content_39 = {
    Text = "Bạn đã đến được đây rồi, tại sao không thể tiến thêm một bước nữa? Đó là của bạn… Vương miện vốn dĩ là của bạn…"
  },
  AvgDialog_142854_Content_4 = {
    Text = "Bạn bò dậy từ đống bụi đất đầy mặt đất, phủi cát sỏi trên người, mất vài giây để nhớ lại mình đang ở đâu."
  },
  AvgDialog_142854_Content_40 = {
    Text = "<Red:Giết Cô ấy đi?……Giết Cô ấy đi……Giết Cô ấy đi……Giết Cô ấy đi!!!>"
  },
  AvgDialog_142854_Content_41 = {
    Text = "Ba bước. Khoảng cách giữa bạn và vinh quang tối thượng đó, Chỉ còn ba bước…"
  },
  AvgDialog_142854_Content_42 = {
    Text = "<ShakeRed:(Ta phải… giết cô ấy…!)>"
  },
  AvgDialog_142854_Content_43 = {
    Text = "Đúng lúc bạn lấy hết can đảm định bước chân đầu tiên, lơ-tan quay đầu lại. Đôi Mắt mệt mỏi đó, bình thản nhìn về phía bạn."
  },
  AvgDialog_142854_Content_44 = {
    Text = "Trong khoảnh khắc bị Ánh Mắt đó nhìn vào, tất cả những tiếng thì thầm đang chống đỡ bạn đồng loạt biến mất, dòng Máu đang sôi sục của bạn lập tức nguội lạnh."
  },
  AvgDialog_142854_Content_45 = {
    Text = "<Shake:lơ… lơ-tan đại nhân… xin lỗi…>"
