  AvgDialog_142854_Content_46 = {
    Text = "<Shake:Ta… ta…>"
  },
  AvgDialog_142854_Content_47 = {
    Text = "Trong Đôi Mắt của lơ-tan không có chút sát ý nào. Nhìn vào Đôi Mắt đó, bạn chợt hiểu ra, nếu không phải để gặp Cá Voi Trời Sao, không có bất kỳ ai ở đây đáng để Cô ấy ra tay."
  },
  AvgDialog_142854_Content_48 = {
    Text = "Đó là ánh nhìn của một người đang nhìn xuống những con kiến tranh giành nhau vì một viên kẹo. Ngoài ra, không có thêm bất kỳ cảm xúc nào khác."
  },
  AvgDialog_142854_Content_49 = {
    Text = "Câu chuyện của những con kiến, chưa bao giờ thay đổi. Cô ấy giơ bàn tay đã thành xương trắng lên, tùy tiện bỏ thứ trong tay lên đầu bạn."
  },
  AvgDialog_142854_Content_5 = {
    Text = "Tường đá của Đấu trường vỡ vụn như giấy, những tảng đá khổng lồ rơi xuống từ khán đài, bóng dáng cuối cùng của những khán giả ảo ảnh đó đã biến mất từ lâu."
  },
  AvgDialog_142854_Content_50 = {
    Text = "！！！Đây là……"
  },
  AvgDialog_142854_Content_51 = {
    Text = "Những vệt Máu ấm áp, bẩn thỉu nhỏ xuống từ đỉnh đầu bạn. Bạn đưa tay ra, trên đầu mình, chạm vào chiếc Vương miện lạnh lẽo nhớp nháp được Hội Tụ từ Máu Tươi."
  },
  AvgDialog_142854_Content_52 = {
    Text = "Vô số anh hùng đã giết chóc vì nó, vô số nhân tính đã sa ngã vì nó. Quyền lực và của cải của sáu quốc gia, sự cao quý và vinh quang tối thượng, lúc này đang nhẹ nhàng đội trên đỉnh đầu bạn."
  },
  AvgDialog_142854_Content_53 = {
    Text = "Kẻ chiến thắng cuối cùng đã tùy tay ném nó cho bạn, như nhét một viên kẹo vào miệng Tham lam của đứa trẻ — giờ đây, bạn đã có tất cả rồi."
  },
  AvgDialog_142854_Content_54 = {
    Text = "Đại nhân lơ-tan… Ngài… Ngài…"
  },
  AvgDialog_142854_Content_55 = {
    Text = "Hãy giúp ta một việc."
  },
  AvgDialog_142854_Content_56 = {
    Text = "Ta sẽ đi tìm đối thủ mới. Trước đó, ta cần một đôi kiếm mới."
  },
  AvgDialog_142854_Content_57 = {
    Text = "lơ-tan nhìn đôi trường kiếm đã đồng hành cùng mình bao năm trong tay, rồi cất những tàn tích tan vỡ của chúng vào vỏ kiếm."
  },
  AvgDialog_142854_Content_58 = {
    Text = "Cô ấy quay người, kéo lê thân xác tàn tạ, mệt mỏi và chậm chạp bước về phía trước, tiến đến một đích đến mà bạn không thể nào hiểu được."
  },
  AvgDialog_142854_Content_59 = {
    Text = "Trong vết nứt phía sau lưng bạn, những rune cổ xưa lần lượt tắt lịm, vị thần đang tan rã và mục ruỗng kia lộ ra nụ cười mãn nguyện mà bạn chưa từng thấy bao giờ."
  },
  AvgDialog_142854_Content_6 = {
    Text = "Bạn nằm sấp trên mặt đất đầy đá vụn, tai ù không ngừng. Khe nứt chiều đó treo lơ lửng ở trung tâm Đấu trường, rìa đang co giật dữ dội, trông như một vết thương hung tàn."
  },
  AvgDialog_142854_Content_60 = {
    Text = "Hãy… Ghi nhớ tên của cô ấy thay ta."
  },
  AvgDialog_142854_Content_61 = {
    Text = "Máu Tươi chảy dọc theo đầu và Khuôn Mặt bạn nhỏ xuống, vũng Máu bên dưới phản chiếu đôi Mắt bàng hoàng, bất lực của bạn."
  },
  AvgDialog_142854_Content_62 = {
    Text = "Vương Miện trên đầu thật nặng, thật nặng. Sức nặng của dục vọng mười hai nghìn năm khiến bạn quỳ trong vũng Máu, nhìn theo bóng dáng kia ngày càng xa dần, mãi không thể đứng dậy."
  },
  AvgDialog_142854_Content_63 = {
    Text = "Vương miện trên đầu rất nhẹ, rất nhẹ, nhẹ đến mức dường như chưa từng tồn tại."
  },
  AvgDialog_142854_Content_7 = {
    Text = "Một tiếng than thở trầm thấp, kéo dài truyền ra từ vết thương, xuyên qua hộp sọ bạn thẳng vào sâu trong tâm trí, nặng nề như tiếng thở dài của một hành tinh."
  },
  AvgDialog_142854_Content_8 = {
    Text = "Âm thanh đó… là Tinh Thiên Chi Kình?!"
  },
  AvgDialog_142854_Content_9 = {
    Text = "Từ khe nứt tỏa ra mùi tanh máu nồng nặc, khiến người ta buồn nôn. Khi bạn chuẩn bị từ từ tiến lại gần nó, một bàn chân chỉ còn trơ xương bước ra từ khe nứt."
  },
  AvgDialog_142888_Content_1 = {
    Text = "Lời Nói Dối"
  },
  AvgDialog_142888_Content_10 = {
    Text = "Bạn không có cách nào trả lời, ký ức của bạn lúc này rối loạn như một con chó lông dài vừa lăn ba vòng trong bùn."
  },
  AvgDialog_142888_Content_100 = {
    Text = "Tràn qua ngực, tràn qua vành tai, tràn qua……"
  },
  AvgDialog_142888_Content_101 = {
    Text = "Chúa công!"
  },
  AvgDialog_142888_Content_102 = {
    Text = "Bạn chợt tỉnh lại, phía xa, Augier, Rotan, Ramona đã kết thúc huấn luyện và đang đi về phía bạn, phân thân búp bê của Doll đang phân tích dữ liệu huấn luyện của họ."
  },
  AvgDialog_142888_Content_103 = {
    Text = "Người bên cạnh thở dài một cái đầy tiếc nuối."
  },
  AvgDialog_142888_Content_104 = {
    Text = "Đừng lo, ta sẽ luôn giữ lại sự lựa chọn này cho cậu."
  },
  AvgDialog_142888_Content_105 = {
    Text = "Bên cạnh đã không còn ai, đường chân trời nơi hoàng hôn sắp lặn khúc xạ ra chút ánh ngọc trai huyền ảo dịu dàng."
  },
  AvgDialog_142888_Content_106 = {Text = "A……"},
  AvgDialog_142888_Content_107 = {
    Text = "Bạn còn rất nhiều điều muốn nói. Về thảm họa đó, không nhắm vào bất kỳ ai cụ thể, chỉ là N vì tính hiếu kỳ mà mê hoặc tín đồ gây ra."
  },
  AvgDialog_142888_Content_108 = {
    Text = "Về việc Giáo hội Đèn Lồng đã tiếp tay trong đó, về những hành động trả thù điên cuồng đủ kiểu của Pontos trong suốt hàng trăm năm sau đó."
  },
  AvgDialog_142888_Content_109 = {
    Text = "Về việc… liệu có một khoảnh khắc nào đó, anh ấy cũng đã độnglắc trước một khả năng khác, nên để năm tháng lưu lại dấu vết trên người anh ấy."
  },
  AvgDialog_142888_Content_11 = {
    Text = "Leisa, người cũng gần như kiệt sức vì trận chiến trước đó, cố gắng chống người ngồi dậy, đứng chắn giữa bạn và Pontos."
  },
  AvgDialog_142888_Content_110 = {
    Text = "Về Yage và Leisa, liệu bây giờ họ có vẫn đang cuồng hoan ở Epoyanth không."
  },
  AvgDialog_142888_Content_111 = {
    Text = "……Cuối cùng bạn chỉ muốn cầu nguyện rằng anh ấy đừng gây ra chuyện gì với giáo sư Dexter ở trường."
  },
  AvgDialog_142888_Content_112 = {
    Text = "Bạn lắc đầu, không chút do dự bước về phía các bạn bè."
  },
  AvgDialog_142888_Content_12 = {
    Text = "Pontos, kết thúc rồi."
  },
  AvgDialog_142888_Content_13 = {
    Text = "Những người còn sống, nếu ở lại Epoyanth, sẽ phải trả giá bằng cách quên đi ký ức về thế giới bên ngoài Epoyanth."
  },
  AvgDialog_142888_Content_14 = {
    Text = "Còn những người như tôi, đã chết và được tái tạo thành ác mộng, cuối cùng tất cả ký ức sẽ bị Xói mòn dần dần."
  },
  AvgDialog_142888_Content_15 = {
    Text = "Yage đã đưa ra lựa chọn của anh ấy, tôi cũng đã đưa ra lựa chọn của mình…\nHãy rời đi thôi."
  },
  AvgDialog_142888_Content_16 = {
    Text = "Đôi môi Pontos mím lại thành một đường lạnh lùng, hàm răng siết chặt."
  },
  AvgDialog_142888_Content_17 = {
    Text = "Anh vẫn còn nhớ chứ, anh tồn tại nhờ vào Epoyanth. Rời khỏi Epoyanth, anh sẽ chết."
  },
  AvgDialog_142888_Content_18 = {
    Text = "Đúng, nhưng những ký ức trong quá khứ của tôi cũng sẽ trở lại. Tôi sẽ chết như một con người, đó là cách duy nhất."
  },
  AvgDialog_142888_Content_19 = {
    Text = "Tôi đã… không còn nhớ hình dáng lúc nhỏ của anh và Jager nữa rồi, ít nhất, trước khi tôi hoàn toàn quên mất các anh."
  },
  AvgDialog_142888_Content_2 = {
    Text = "Uy áp ngạt thở rút lui như thủy triều, đầu óc bạn truyền đến cơn đau nhói dữ dội, trước mắt cứ từng đợt trắng xóa."
  },
  AvgDialog_142888_Content_20 = {
    Text = "Pontos đứng khựng tại chỗ, lần đầu tiên, bạn thấy trên khuôn mặt anh ấy xuất hiện một biểu cảm đau buồn đến vậy."
  },
  AvgDialog_142888_Content_21 = {
    Text = "……Tôi thực sự ước mình có thể nói rằng sức mạnh đó vẫn đang kiểm soát tôi."
  },
  AvgDialog_142888_Content_22 = {
    Text = "Anh nhắm mắt lại, như thể muốn trốn tránh khỏi những điều anh không muốn đối mặt. Cuối cùng, anh nở một nụ cười tự嘲 và chán nản."
  },
  AvgDialog_142888_Content_23 = {
    Text = "Như vậy tôi có thể hiên ngang làm trái ý nguyện của các anh, gây hại cho các anh."
  },
  AvgDialog_142888_Content_25 = {
    Text = "Pontos đã Im Lặng mà nhượng bộ, chiếc chiến xa từng chở anh đi báo thù kẻ thù, nay cũng tiễn đưa Leisa."
  },
  AvgDialog_142888_Content_26 = {
    Text = "Khoảnh khắc thân xe tỏa ánh châu quang khó tả lướt vào bầu trời bên ngoài Epoyanth, trên Khuôn Mặt Leisa hiện lên nụ cười thanh thản, cô ấy quay đầu nhìn về phía các bạn—"
  },
  AvgDialog_142888_Content_27 = {
    Text = "Rồi, hoàn toàn tan biến trong gió biển đêm."
  },
  AvgDialog_142888_Content_28 = {
    Text = "Cả hai đều không lên tiếng, chỉ lặng lẽ nhìn chằm chằm vào khoảng Hư vô đó mãi, cho đến khi Pontos phá vỡ sự im lặng này."
  },
  AvgDialog_142888_Content_29 = {
    Text = "Cuộc sống của bạn sau khi rời khỏi Epoyanth, cuộc sống của \"bạn\", trông như thế nào?"
  },
  AvgDialog_142888_Content_3 = {
    Text = "Hít… đau quá!"
  },
  AvgDialog_142888_Content_30 = {
    Text = "Bạn không ngờ câu đầu tiên của anh ấy lại là điều này, sững người một lúc, rồi mới bắt đầu sắp xếp lại những ký ức rối rắm đó."
  },
  AvgDialog_142888_Content_31 = {
    Text = "Lần này thâm cảnh dường như có chút vấn đề, dù là ký ức của Yage hay của %player%, đều không hoàn toàn đầy đủ."
  },
  AvgDialog_142888_Content_32 = {
    Text = "……Tôi không nhớ rõ, trong đầu tôi bây giờ vừa có ký ức với tư cách là Jager, vừa có ký ức của một người khác ở nơi xa xôi, tất cả ký ức đều rất hỗn loạn."
  },
  AvgDialog_142888_Content_33 = {
    Text = "Bạn theo phản xạ thò tay vào túi, vuốt ve con châu chấu đó."
  },
  AvgDialog_142888_Content_34 = {
    Text = "Nhưng dù rất bình thường, rất tầm thường, bận rộn, ngày qua ngày, nhưng cũng rất hạnh phúc."
  },
  AvgDialog_142888_Content_35 = {
    Text = "Hạnh phúc đủ để khiến tôi trở thành chính mình, đủ để dù thế nào tôi cũng muốn quay trở về."
  },
  AvgDialog_142888_Content_36 = {
    Text = "Anh ấy lặng lẽ Nhìn chằm chằm vào Đôi Mắt bạn, Dường như, cũng giống như… cách Leisa nhìn bạn vậy."
  },
  AvgDialog_142888_Content_37 = {
    Text = "<Red:Anh ấy không chỉ đang nhìn Yage.>"
  },
  AvgDialog_142888_Content_38 = {
    Text = "Các bạn đã nghĩ sai rồi, Yage… <Red:%player%>."
  },
  AvgDialog_142888_Content_39 = {
    Text = "！！！???"
  },
  AvgDialog_142888_Content_4 = {
    Text = "Pontos đứng đơn độc tại chỗ, bạn không nhìn rõ biểu cảm của anh ta."
  },
  AvgDialog_142888_Content_40 = {
    Text = "Gì vậy?!"
  },
  AvgDialog_142888_Content_41 = {
    Text = "Bạn giật mình kinh hãi, tại sao Pontos lại biết tên của <Red:「bạn」>, đây chẳng phải Chỉ là một thâm cảnh sao?"
  },
  AvgDialog_142888_Content_42 = {
    Text = "Anh ấy lại trở về với thái độ lạnh lùng, kiêu kỳ đó, như thể mọi thứ đều vẫn nằm trong tầm kiểm soát, bình thản nở nụ cười."
  },
  AvgDialog_142888_Content_43 = {
    Text = "Tôi biết <Red:「bạn」> luôn ở đây, tôi biết <Red:「bạn」> chính là 「anh ấy」, từ khi <Red:「bạn」> còn nhỏ, tôi đã biết <Red:「bạn」> khác biệt với mọi người."
  },
  AvgDialog_142888_Content_44 = {
    Text = "Tiếng ồn ào u ám, thuộc về nước biển lại một lần nữa vang vọng bên tai bạn."
  },
  AvgDialog_142888_Content_45 = {
    Text = "Các bạn còn quá nhỏ, quá ngây thơ, lầm tưởng rằng sự tầm thường đó chính là hạnh phúc."
  },
  AvgDialog_142888_Content_46 = {
    Text = "Lần này, ta sẽ không mắc phải <Red:「sai lầm」> trao quyền lựa chọn cho các ngươi nữa."
  },
  AvgDialog_142888_Content_47 = {
    Text = "Các bạn đã nhầm, anh ấy không hề nhượng bộ, anh ấy sẽ không, và tuyệt đối không có ý định buông tay, anh ấy Chỉ là bỏ xuống một cái mồi nhử."
  },
  AvgDialog_142888_Content_48 = {
    Text = "Anh ấy đã Phát hiện ra phần còn lại của \"bạn\" từ lâu, anh ấy muốn tìm \"bạn\", anh ấy không cho phép có thêm bất kỳ sự cố nào nữa."
  },
  AvgDialog_142888_Content_49 = {
    Text = "Quá dễ dàng, trận chiến đó, chiến thắng đó.\nĐó là một cái bẫy để nhử <Red:bạn> ra."
  },
  AvgDialog_142888_Content_5 = {
    Text = "Nhưng rõ ràng, có gì đó đã rời khỏi anh ta."
  },
  AvgDialog_142888_Content_50 = {
    Text = "Dù phải trả giá như thế nào, dù phải tuyên thệ trung thành với sự tồn tại nào đó…"
  },
  AvgDialog_142888_Content_51 = {
    Text = "Ta sẽ khiến lễ hội cuồng hoan của Epoyanth kéo dài mãi mãi."
  },
  AvgDialog_142888_Content_52 = {
    Text = "Không ai biết, tại sao ông ấy đột nhiên cho phép sự lão hóa xảy ra trên cơ thể mình."
  },
  AvgDialog_142888_Content_53 = {
    Text = "Cả Epoyanth đang rung chuyển cùng với ông, tất cả mọi thứ xung quanh và làn nước biển sóng động từ lồng ngực ông hòa quyện vào nhau không phân biệt."
  },
  AvgDialog_142888_Content_54 = {
    Text = "Có lẽ là bạn bè, có lẽ là kẻ thù, vô số cánh tay đen từ lồng ngực ông vươn ra, xé toạc và vuốt ve làn da ông."
  },
  AvgDialog_142888_Content_55 = {
    Text = "Như muốn trốn thoát, lại như muốn mãi mãi ở bên ông."
  },
  AvgDialog_142888_Content_56 = {
    Text = "Ta đang trên một con đường mà từ lâu đã không thể quay đầu, ta cũng không cần phải quay đầu."
  },
  AvgDialog_142888_Content_57 = {
    Text = "Những tháng ngày chưa từng trải qua chẳng có gì quan trọng, ở Epoyanth, chúng có thể kiểm soát được, thuần phục, sẽ không gây ra thương tổn."
  },
  AvgDialog_142888_Content_58 = {
    Text = "Thật tiếc, ta tạm thời chưa có cách nào giữ bạn lại, thời gian của chúng ta đã đến rồi, <Red:%player%>."
  },
  AvgDialog_142888_Content_59 = {Text = "!!!"},
  AvgDialog_142888_Content_6 = {
    Text = "Cho ta một lý do."
  },
  AvgDialog_142888_Content_60 = {
    Text = "Cảm giác mất trọng lực kéo bạn từ không gian bị xé toạc, bắn vọt lên cao.\nNhững con ác mộng che kín bầu trời xòe đôi cánh màng, ào ạt lao về phía bạn."
  },
  AvgDialog_142888_Content_61 = {
    Text = "Yên tâm, chúng ta sẽ sớm gặp lại nhau thôi."
  },
  AvgDialog_142888_Content_62 = {
    Text = "Ta và Epoyanth, sẽ mãi mãi đợi bạn Trở Về."
  },
  AvgDialog_142888_Content_63 = {
    Text = "Dấu vết của năm tháng như phong hóa lan khắp thân thể Pontos."
  },
  AvgDialog_142888_Content_64 = {
    Text = "Ông cất tiếng cười lớn, tại Epoyanth đang nhanh chóng rời xa bạn, nâng chén về phía bạn."
  },
  AvgDialog_142888_Content_65 = {
    Text = "Cái nhìn cuối cùng trước khi chìm vào bóng tối, bạn nhìn thấy hai bóng người đứng bên cạnh ông."
  },
  AvgDialog_142888_Content_66 = {
    Text = "Ông không buông tha bất kỳ ai, ông đã giữ lại tất cả mọi người."
  },
  AvgDialog_142888_Content_67 = {
    Text = "<Red:Đó là Leisa, và Yage lúc còn trẻ.>"
  },
  AvgDialog_142888_Content_69 = {
    Text = "Ơ?! Sau đó thì sao, sau đó thì sao? Người giữ bí mật không bị ngã chết chứ! Chú Pontos thật xấu xa quá!"
  },
  AvgDialog_142888_Content_7 = {
    Text = "Giọng anh ta khàn khàn, nhưng thân thể vẫn căng cứng, như một loài thú đường cùng."
  },
  AvgDialog_142888_Content_70 = {
    Text = "Đúng đó, sao mà xấu tính vậy Pontos!"
  },
  AvgDialog_142888_Content_71 = {
    Text = "Đúng đó, sao mà xấu tính vậy Pontos!"
  },
  AvgDialog_142888_Content_72 = {
    Text = "Bạn đang hùng hổ thì thầm với Ô Ryta về những trải nghiệm trong Giấc mơ, vừa quay đầu lại…"
  },
  AvgDialog_142888_Content_73 = {
    Text = "Thì giật mình trước một người nào đó cũng đang hứng thú không kém, tay đút túi đứng ở cửa không biết đã nghe từ lúc nào."
  },
  AvgDialog_142888_Content_74 = {
    Text = "Về sau trong câu chuyện, cậu bé Yage đã thuận lợi rời đi, mở mắt ra từ trong Giấc mơ."
  },
  AvgDialog_142888_Content_75 = {
    Text = "Cậu phát hiện mình đang nằm trên giường ở Nhà, những người cậu yêu thương vây quanh bên cạnh."
  },
  AvgDialog_142888_Content_76 = {
    Text = "Nhân vật chính khác của câu chuyện tựa vào tường phòng ngủ của Ô Ryta, giọng trầm thấp nhẹ nhàng bổ sung phần kết của câu chuyện."
  },
  AvgDialog_142888_Content_77 = {
    Text = "Cậu nhớ lại tất cả ký ức của cả đời mình, an nhiên nhắm mắt lại, đến một nơi hạnh phúc."
  },
  AvgDialog_142888_Content_78 = {
    Text = "Ô Ryta thỏa mãn phát ra tiếng thở nhỏ qua mũi, dần dần mơ màng chìm vào giấc ngủ, giống hệt Vera trong ký ức của bạn."
  },
  AvgDialog_142888_Content_79 = {
    Text = "Pontos hướng ra ngoài cửa, thực hiện một cử chỉ mang ý nghĩa mời."
  },
  AvgDialog_142888_Content_8 = {
    Text = "Tại sao, tại sao ngay cả ngươi cũng muốn rời đi, tại sao thà chọn cái chết, mà không phải——"
  },
  AvgDialog_142888_Content_80 = {
    Text = "Tôi nghĩ, bạn hẳn muốn nói chuyện với tôi?"
