  },
  AvgDialog_142889_Content_4 = {
    Text = "Bạn nhìn Vera với ánh mắt hiền từ, những người thân vì không muốn bạn quá mệt mỏi, đã chu đáo để lại không gian riêng cho hai người."
  },
  AvgDialog_142889_Content_40 = {
    Text = "Tiếng nổ chói tai như miếng sắt cào lên kính từ trong hộp sọ đập thẳng xuống cổ họng cậu, não bộ cậu theo đó biến thành một vũng hồ đặc quánh."
