  AvgDialog_142889_Content_7 = {
    Text = "Có thể họ chưa bao giờ thực sự rời đi, chỉ là đang bay lượn đâu đó trên bầu trời đêm, nếu một ngày nào đó ta biến mất, thì là họ đến đón ta rồi."
