  },
  AvgDialog_142889_Content_80 = {
    Text = "Bước chân bạn bỗng dừng sững lại, bởi vẻ mặt vô cùng bất lực và bi thương trên khuôn mặt Leisa."
  },
  AvgDialog_142889_Content_81 = {
    Text = "Hắn đã tìm thấy ngươi rồi, Jager tội nghiệp của ta, ngươi không nên đến đây."
  },
  AvgDialog_142889_Content_82 = {
    Text = "Hãy nghĩ đi, nhân lúc ngươi chưa quên hết, hãy nhớ lại đi, ngươi đã sống một cuộc đời như thế nào."
  },
  AvgDialog_142889_Content_83 = {
    Text = "Nước mắt của mẹ rơi xuống tay ngươi, lạnh đến mức ngươi vô thức rụt tay lại, không khí giá buốt khiến cơn ớn lạnh tức khắc lan khắp toàn thân."
  },
  AvgDialog_142889_Content_84 = {
    Text = "Nhìn xem những người xung quanh này, nhìn xem ta, chúng ta đáng lẽ phải như thế nào."
  },
  AvgDialog_142889_Content_85 = {
    Text = "Hãy sờ vào túi của bạn đi, Yage."
  },
  AvgDialog_142889_Content_86 = {
    Text = "Vụng về, thô ráp, hơi cứng tay — ở đó có một con <Red:châu chấu>."
  },
  AvgDialog_142889_Content_87 = {
    Text = "Một con châu chấu do <Red:Vera> làm, mang tên <Red:Vera>."
  },
  AvgDialog_142889_Content_88 = {
    Text = "<Shake:<Red:Vera>… không phải, tôi đã… đã rất lâu rồi…>"
  },
  AvgDialog_142889_Content_89 = {
    Text = "<Shake:Tôi sắp chết, tôi nằm trên giường, tôi đã từng có bạn bè, người yêu, con cái, tôi đang ở…>"
  },
  AvgDialog_142889_Content_9 = {
    Text = "Bạn bật cười, móc từ trong ngực ra chiếc la bàn chưa từng rời thân suốt mấy chục năm, đặt vào lòng bàn tay Vera."
  },
  AvgDialog_142889_Content_90 = {
    Text = "Mọi thứ xung quanh đang xoay vòng hỗn loạn vô trật tự, hai luồng suy nghĩ hoàn toàn khác biệt hòa lẫn vào nhau."
  },
  AvgDialog_142889_Content_91 = {
    Text = "Bạn ôm đầu, đau đớn khom lưng xuống, cố gắng Hút Lấy từng hơi thở oxy."
  },
  AvgDialog_142889_Content_92 = {
    Text = "Trời ơi, Jager, ngươi sao vậy, sắc mặt tệ thế này!"
  },
  AvgDialog_142889_Content_93 = {
    Text = "Orni từ đâu bước ra đâm sầm vào bạn, tiếng ù tai vang vọng đột ngột biến mất."
  },
  AvgDialog_142889_Content_94 = {
    Text = "Bạn ngẩng đầu lên, bóng dáng của Leisa đã không còn đâu nữa."
  },
  AvgDialog_142889_Content_95 = {
    Text = "Orni, Orni, không, không, tôi nhớ ra rồi!"
  },
  AvgDialog_142889_Content_96 = {
    Text = "Chúng ta rõ ràng đã lớn lên cùng nhau, tôi đã tham dự lễ tốt nghiệp, đám cưới của bạn, bạn đáng lẽ phải giống tôi, bạn không nên trẻ như vậy, chúng ta đã già rồi."
  },
  AvgDialog_142889_Content_97 = {
    Text = "Orni nhìn chằm chằm vào bạn với một biểu cảm mà bạn hoàn toàn xa lạ, nhìn rất lâu, rất lâu, cho đến khi bạn Hầu như muốn trốn chạy."
  },
  AvgDialog_142889_Content_98 = {
    Text = "Rồi thì……"
  },
  AvgDialog_142889_Content_99 = {
    Text = "À, Jager……"
  },
  AvgDialog_142890_Content_1 = {
    Text = "Cô Ấy Và Anh Ấy"
  },
  AvgDialog_142890_Content_10 = {
    Text = "Cảm ơn quà tặng của cậu, cậu Pontos, nhưng…"
  },
  AvgDialog_142890_Content_11 = {
    Text = "Đó chắc chắn là một cuộc đời rất dài và quý giá, vì vậy, tôi sẵn lòng từ bỏ tuổi xuân vĩnh cửu và Sinh lực."
  },
  AvgDialog_142890_Content_12 = {
    Text = "Mọi người không còn trò chuyện nữa, đồng loạt, tất cả đều quay mặt nhìn bạn."
  },
  AvgDialog_142890_Content_13 = {
    Text = "Màng nhĩ đau căng như sắp vỡ ra, tiếng nước biển xao động khoan sâu vào trong hộp sọ ngươi."
  },
  AvgDialog_142890_Content_14 = {
    Text = "Xuyên qua làn nước biển u trầm, ngươi nghe thấy một tiếng thở dài."
  },
  AvgDialog_142890_Content_15 = {
    Text = "<Red:Lại như vậy rồi.>"
  },
  AvgDialog_142890_Content_16 = {
    Text = "<Shake:<Red:Kít… ừm, ục ục, ục…>>"
  },
  AvgDialog_142890_Content_17 = {
    Text = "Bốn bức tường Rung động, tất cả nhỏ giọt trong chất nhầy ẩm ướt."
  },
  AvgDialog_142890_Content_18 = {
    Text = "Dù ta đã tách ngươi ra, tuổi già vẫn khiến ngươi nói ra những <Red:lời ngu ngốc yếu đuối> như vậy, giống hệt Leisa."
  },
  AvgDialog_142890_Content_19 = {
    Text = "Bạn đột nhiên cảm nhận được, anh ấy <Red:không còn là> Pontos nữa."
  },
  AvgDialog_142890_Content_2 = {
    Text = "Nhìn bàn tay quen thuộc, ấm áp ấy, cuối cùng bạn — lùi lại một bước."
  },
  AvgDialog_142890_Content_20 = {
    Text = "Cổ xưa đến mức đã bị lãng quên, nỗi Sợ hãi sâu thẳm lạnh lẽo bao la, uy nghiêm, khó mà Nhìn chằm chằm vào khiến bạn đứng sững tại chỗ phát ra tiếng <Red:thét câm>."
  },
  AvgDialog_142890_Content_22 = {
    Text = "Bạn nhớ ra rồi, âm thanh đó khi đến Epoyangs, khi rời Epoyangs, khi trở lại Epoyangs."
  },
  AvgDialog_142890_Content_23 = {
    Text = "Da thịt, xương sườn, lật ra bên ngoài duỗi thẳng, rồi là……"
  },
  AvgDialog_142890_Content_24 = {
    Text = "Trống rỗng, vô số bàn tay, trống rỗng, trống rỗng, trống rỗng, trống rỗng, trống rỗng, @2y@2, @4@4@2@4\n@3@2@4@3@1@3@3!!!!!!"
  },
  AvgDialog_142890_Content_25 = {
    Text = "Ở lại đây, ở lại Epoyanth."
  },
  AvgDialog_142890_Content_26 = {
    Text = "<Change>Lắng nghe vực thẳm, lao mình vào vực thẳm."
  },
  AvgDialog_142890_Content_27 = {
    Text = "Mặt trăng."
  },
  AvgDialog_142890_Content_28 = {
    Text = "Mặt trăng sáng trong, treo lơ lửng trên bầu trời xa xôi."
  },
  AvgDialog_142890_Content_29 = {
    Text = "Xương sườn anh làn da anh cánh tay anh lồng ngực anh vòng tay anh\nVòng tay anh vòng tay anh vòng tay anh vòng tay anh vòng tay anh\nVòng tay anh vòng tay anh vòng tay anh vòng tay anh vòng tay anh\nE@3@4poyan@3@2th\nEpo@4@3@2yan@4@3@2th\nVòng ôm anh xương sườn anh làn da anh cánh tay anh lồng ngực anh\nMãi mãi mãi mãi mãi mãi mãi mãi mãi mãi mãi mãi mãi\nMãi mãi mãi mãi mãi mãi mãi mãi mãi mãi mãi <Red:Epoyanth>"
  },
  AvgDialog_142890_Content_3 = {
    Text = "……Có đấy."
  },
  AvgDialog_142890_Content_30 = {
    Text = "<Red:Epoyanth đến trong vòng tay của anh.>"
  },
  AvgDialog_142890_Content_31 = {
    Text = "Những đôi cánh chồng chất lên nhau, cuốn theo vòng ôm chặt chẽ, kiên định, không thể cưỡng lại và sự nuốt chửng bên trong."
  },
  AvgDialog_142890_Content_32 = {
    Text = "Ngươi bị đẩy dồn, ngươi bị bao bọc, ngươi được dung nạp, ngươi đang rơi vào sự tĩnh lặng vô tận."
  },
  AvgDialog_142890_Content_33 = {
    Text = "Dừng lại!"
  },
  AvgDialog_142890_Content_34 = {
    Text = "Một bóng người mạnh mẽ xé toạc đám đông lạnh lùng vô tri vô giác, xông thẳng vào vòng xoáy của <Red:「Pontos」>."
  },
  AvgDialog_142890_Content_35 = {
    Text = "Không gây ra bất kỳ thương tích nào, nhưng cơn kinh ngạc quá rõ ràng khiến đồng tử của <Red:「Pontos」> rung lên, ánh mắt dán chặt vào khuôn mặt cô ấy."
  },
  AvgDialog_142890_Content_36 = {
    Text = "Ta vẫn luôn nghĩ rằng… ta chỉ tái tạo lại một Vỏ rỗng."
  },
  AvgDialog_142890_Content_37 = {
    Text = "Giống như những thứ Yage đã quên nhưng vẫn còn ảnh hưởng đến anh ấy, một phần của ta vẫn còn tồn tại."
  },
  AvgDialog_142890_Content_38 = {
    Text = "Hãy để anh ấy đi, Pontos, anh ấy không thuộc về nơi này."
  },
  AvgDialog_142890_Content_39 = {
    Text = "Ồ, Leisa."
  },
  AvgDialog_142890_Content_4 = {Text = "Cái gì?"},
  AvgDialog_142890_Content_40 = {
    Text = "Ta yêu anh ấy, yêu anh ấy như ngươi vậy."
  },
  AvgDialog_142890_Content_41 = {
    Text = "Orni, White."
  },
  AvgDialog_142890_Content_42 = {
    Text = "Tất cả mọi người của Epoyanth."
  },
  AvgDialog_142890_Content_43 = {
    Text = "Họ im lặng cùng với ác mộng, tiến đến gần ngươi như một bức tường đang đổ sập."
  },
  AvgDialog_142890_Content_44 = {
    Text = "Không, không không không! Không!!"
  },
  AvgDialog_142890_Content_45 = {
    Text = "Leisa nhìn bạn, nhìn Yage, rồi cũng nhìn… bạn."
  },
  AvgDialog_142890_Content_46 = {
    Text = "Ta biết tại sao ngươi muốn họ đến vậy, ở đó không chỉ có Yage, không chỉ có một linh hồn."
  },
  AvgDialog_142890_Content_47 = {
    Text = "À… họ sẽ quên hết mọi thứ, họ sẽ ở lại đây."
  },
  AvgDialog_142890_Content_48 = {
    Text = "Leisa lại bị kẹt, cô ấy dồn hết sức lực xoay người lại, nhìn chằm chằm vào đôi mắt của bạn, dường như muốn nhìn thấu tận sâu thẳm linh hồn."
  },
  AvgDialog_142890_Content_49 = {
    Text = "Xin hãy, dù bạn là ai, tôi biết bạn đang ở đó. Hãy đưa Yage trở về, trở về cuộc sống vốn có của các bạn!"
  },
  AvgDialog_142890_Content_5 = {
    Text = "Anh ta như không hiểu câu hỏi của ngươi, khó tin mà nhíu mày lại."
  },
  AvgDialog_142890_Content_50 = {
    Text = "Những màng cánh đen dày đặc xòe ra, tất cả đều quá tĩnh lặng, quá… hấp dẫn, bạn gần như muốn bước về phía Chúng."
  },
  AvgDialog_142890_Content_51 = {
    Text = "Rồi, bạn nghe thấy… giọng nói của <Red:「bạn」>."
  },
  AvgDialog_142890_Content_52 = {
    Text = "Tôi nghĩ, <Red:「Tôi」> đã đưa ra lựa chọn của mình."
  },
  AvgDialog_142890_Content_53 = {
    Text = "Từ sâu thẳm thức hải, một linh tính vùng vẫy thoát ra."
  },
  AvgDialog_142890_Content_54 = {
    Text = "Sống sót qua vụ nổ lớn ở Akutê, với tư cách là <Red:「Người giữ bí mật Misaque」>, 「bạn」 đã tiếp quản thân xác này."
  },
  AvgDialog_142890_Content_55 = {
    Text = "Ánh huy hoàng bạc lấp lánh trong lòng bàn tay bạn."
  },
  AvgDialog_142890_Content_56 = {
    Text = "Những ký ức hỗn độn thuộc về Yage được nhặt nhạnh lại từng chút một."
  },
  AvgDialog_142890_Content_57 = {
    Text = "Bạn có biết không, cậu Pontos, điều đầu tiên tôi nhớ lại, lại là một chuyện chẳng đáng kể gì."
  },
  AvgDialog_142890_Content_59 = {
    Text = "\"Pontos\" không lên tiếng, anh Im Lặng nhìn bạn từ đầu đến chân."
  },
  AvgDialog_142890_Content_6 = {
    Text = "Là có ý nghĩa, những ký ức đó."
  },
  AvgDialog_142890_Content_60 = {
    Text = "Năm mười tám tuổi, Orni và \"Tôi\" lén trốn xuống khoang dưới của con tàu gần nhất, dày mặt xin làm việc giúp các thủy thủ, và được đi một chuyến du thuyền miễn phí."
  },
  AvgDialog_142890_Content_61 = {
    Text = "Sáng sớm hôm sau, chúng tôi nhìn thấy vầng bình minh đẹp nhất mà chúng tôi từng thấy. Orni nói, mong mặt trời đừng bao giờ lặn, nhưng tôi không nghĩ vậy."
  },
  AvgDialog_142890_Content_62 = {
    Text = "Chính vì mặt trời sẽ lặn, một ngày sẽ kết thúc, nên những điều chúng ta Trải nghiệm mỗi ngày mới trở nên đặc biệt quý giá."
  },
  AvgDialog_142890_Content_63 = {
    Text = "Đừng nói những điều ngớ ngẩn nữa, tại Epoyanth, Chỉ cần bạn muốn, ta có thể khiến mặt trời mọc hay lặn theo ý bạn."
  },
  AvgDialog_142890_Content_64 = {
    Text = "Anh chán nản nhắm mắt lại, cuối cùng mất đi kiên nhẫn, bạn Kiên định lắc đầu."
  },
  AvgDialog_142890_Content_65 = {
    Text = "Điều quan trọng là khoảng thời gian chúng ta đã Trải nghiệm, chứ không phải mặt trời mãi mãi treo cao."
  },
  AvgDialog_142890_Content_66 = {
    Text = "Xin lỗi, Pontos."
  },
  AvgDialog_142890_Content_67 = {
    Text = "Anh giơ tay lên, bức tường ác mộng lại một lần nữa ép xuống phía bạn."
  },
  AvgDialog_142890_Content_68 = {
    Text = "Hãy đi đi, những kẻ tùy tùng."
  },
  AvgDialog_142890_Content_7 = {
    Text = "Không phải với người khác, mà là với chính bản thân tôi."
  },
  AvgDialog_142890_Content_8 = {
    Text = "Tôi muốn biết mình đã trải qua một cuộc đời như thế nào, sau khi mất đi ký ức, tại sao dù niềm vui nào cũng khiến tôi cảm thấy như thiếu vắng điều gì."
  },
  AvgDialog_142890_Content_9 = {
    Text = "Gai của con châu chấu cỏ khẽ đâm vào đầu ngón tay ngươi, ngươi bỗng dưng nhớ đến bóng dáng đứa trẻ khóc bên cạnh giường."
  },
  AvgDialog_142891_Content_1 = {
    Text = "Bí Mật Gia Tộc"
  },
  AvgDialog_142891_Content_10 = {
    Text = "Nó tên là — ừm, nó tên là Vera, vì Vera là ông đặt cho, là cái tên hay nhất."
  },
  AvgDialog_142891_Content_100 = {
    Text = "Cơn thịnh nộ của Ngài sẽ thiêu rụi các ngươi, chỉ có Hạnh phúc mới có thể… @1!"
  },
  AvgDialog_142891_Content_101 = {Text = "Phụt."},
  AvgDialog_142891_Content_102 = {
    Text = "Máu Tươi bắn tung tóe, bạn đứng ngây ra nhìn Leisa và vài vị khách quen của quán trọ ở phía xa, đang điều khiển những sinh vật giống hệt con bên dưới hai người để chiến đấu."
  },
  AvgDialog_142891_Content_103 = {
    Text = "Mấy thứ đáng nguyền rủa này rốt cuộc tại sao lại chạy đến đây…\nThôi, đây chắc là con cuối cùng rồi."
  },
  AvgDialog_142891_Content_104 = {
    Text = "Hy vọng chúng chỉ đi ngang qua thôi……"
  },
  AvgDialog_142891_Content_105 = {
    Text = "Leisa và các đồng đội đã rời đi, bạn và Pontos đứng trong bóng tối, anh đỡ chặt phần vai sau của bạn, nhờ vậy bạn mới không ngã sụp xuống đất."
  },
  AvgDialog_142891_Content_106 = {
    Text = "Bạn nắm chặt vạt áo của anh, giọng anh bình thản và nhẹ nhàng, dường như đang cố hết sức không làm bạn thêm hoảng sợ."
  },
  AvgDialog_142891_Content_107 = {
    Text = "Yage, đúng như những gì bạn đã thấy... loài sinh vật này được gọi là Yêm, chúng tôi điều khiển chúng để chiến đấu cho mình."
  },
  AvgDialog_142891_Content_108 = {
    Text = "Anh dừng lại một chút, đặt tay lên bên hông con \"Yêm\", bẻ đốt ngón tay kêu răng rắc, dường như đang do dự không biết giải thích thế nào,"
  },
  AvgDialog_142891_Content_109 = {
    Text = "Chúng ta là nhân vật chính trong những câu chuyện phiêu lưu dũng cảm, ý tôi là, giống như những người cưỡi rồng — chỉ là gia tộc chúng ta cưỡi Yêm mà thôi."
  },
  AvgDialog_142891_Content_11 = {
    Text = "Vera… Ông nội cần nghỉ ngơi, lại đây với bố nào."
  },
  AvgDialog_142891_Content_110 = {
    Text = "Cái... gì?! Cậu đang nói gì vậy, cậu Pontos?! Nhà mình rõ ràng chỉ là đang mở một quán trọ thôi mà."
  },
  AvgDialog_142891_Content_111 = {
    Text = "Sau... một tai nạn, tộc người này chỉ còn lại một số ít người, Leisa đã làm rất nhiều cho tộc, mọi người cũng đều rất dựa vào cô ấy."
  },
  AvgDialog_142891_Content_112 = {
    Text = "Nhưng cô ấy không muốn chúng ta, đặc biệt là bạn, tiếp xúc với những điều này, cuộc sống vô danh tiểu tốt hiện tại chính là cuộc sống cô ấy muốn chúng ta có được."
  },
  AvgDialog_142891_Content_113 = {
    Text = "Tuy nhiên trên thế giới này vẫn còn tồn tại rất nhiều thứ邪ác, xấu xa, giống như những gì bạn thấy hôm nay, tôi không hiểu..."
  },
  AvgDialog_142891_Content_114 = {
    Text = "Pontos hiếm khi lộ ra biểu cảm có phần bực bội, tiện tay gạt mái tóc vàng rủ xuống trước trán ra sau đầu."
  },
  AvgDialog_142891_Content_115 = {
    Text = "Gần đây, \"Yêm\" đã tìm đến tôi, và tôi có thể cảm nhận được sức mạnh mạnh mẽ hơn đằng sau Chúng, Ngài đã chọn tôi, đang Gọi tôi."
  },
  AvgDialog_142891_Content_116 = {
    Text = "Tôi có thể làm được nhiều hơn, nhưng Leisa cho rằng Chỉ cần ẩn náu tốt, những con quái vật đó sẽ không liên quan đến chúng ta, mọi thứ sẽ an toàn."
  },
  AvgDialog_142891_Content_117 = {
    Text = "Lượng thông tin khổng lồ khiến bạn chỉ có thể đứng ngây ra chớp mắt, đây là lần đầu tiên bạn có cảm giác hiểu từng từ riêng lẻ nhưng ghép lại thì hoàn toàn không hiểu gì."
  },
  AvgDialog_142891_Content_118 = {
    Text = "Pontos dường như cũng chợt nhận ra, lấy lại thần trí rồi mỉm cười với bạn."
  },
  AvgDialog_142891_Content_119 = {
    Text = "Xin lỗi, Yage, tôi có nói quá nhiều một lúc không?"
  },
  AvgDialog_142891_Content_12 = {
    Text = "Con trai có phần lo lắng cho sức khỏe của ngươi, muốn bế đứa cháu gái ra, cô ấy chu môi lại, gần như sắp bật khóc thành tiếng."
  },
  AvgDialog_142891_Content_120 = {
    Text = "Trước khi Leisa phát hiện chúng ta lén ra ngoài, hãy về đi thôi, chúng ta còn rất nhiều thời gian để nói chuyện về điều này."
  },
  AvgDialog_142891_Content_121 = {
    Text = "Ở phía xa, Leisa dường như nhận ra có gì đó động tĩnh, nhìn về phía này một cái, Pontos lại ra hiệu im lặng với bạn một lần nữa."
  },
  AvgDialog_142891_Content_123 = {
    Text = "Cánh cửa sổ lặng lẽ mở ra, rồi lại lặng lẽ đóng lại."
  },
  AvgDialog_142891_Content_124 = {
    Text = "Như thể chỉ là gió từng thổi mở cửa sổ, bên ngoài, sóng biển vỗ bờ rồi rút đi, cậu nghe thấy tiếng Lesa từ tầng dưới bước lên."
  },
  AvgDialog_142891_Content_125 = {
    Text = "Hai người hít thở đều đặn, vùi mặt vào gối, giả vờ như đây vẫn là một đêm bình thường."
  },
  AvgDialog_142891_Content_13 = {
    Text = "Bạn mỉm cười và ho vài tiếng, cố gắng chống đỡ bộ xương Mong manh này, dựa vào đầu giường."
  },
  AvgDialog_142891_Content_14 = {
    Text = "Vera, đừng khóc. Ánh trăng bên ngoài đẹp thế, hãy vặn đèn xuống một chút đi."
  },
  AvgDialog_142891_Content_15 = {
    Text = "Ông còn thời gian kể cho cháu một câu chuyện nữa, để ông nghĩ xem……"
  },
  AvgDialog_142891_Content_16 = {
    Text = "Ánh mắt bạn dừng lại trên chiếc la bàn đồng thau chưa bao giờ rời khỏi người, nó không bị thời gian xói mòn, được mặt trăng phủ lên một lớp viền bạc mềm mại."
  },
  AvgDialog_142891_Content_17 = {
    Text = "Bạn chậm rãi vuốt ve bề mặt của nó với nỗi hoài niệm, giọng khàn khàn chìm vào ký ức."
  },
  AvgDialog_142891_Content_18 = {
    Text = "Đó là…… hơn sáu mươi năm trước, khi ông còn là một đứa trẻ."
  },
  AvgDialog_142891_Content_19 = {
    Text = "Leisa, tàu sắp rời bến rồi, anh ấy vẫn chưa về sao?"
  },
  AvgDialog_142891_Content_2 = {
    Text = "Mặt trăng."
  },
  AvgDialog_142891_Content_20 = {
    Text = "Xem ra thực sự không thể gặp mặt để từ biệt rồi, xin ít nhất hãy giữ lại chiếc trâm cài này……"
  },
  AvgDialog_142891_Content_21 = {
    Text = "Còi tàu ở cảng vang lên, những vị chủ nhân của các món trang sức leng keng để lại một đống đồ trang sức cá nhân, đầy vẻ tiếc nuối quay trở lại tàu."
  },
  AvgDialog_142891_Content_22 = {
    Text = "Trời ơi, vì @3 mà, cưng ơi, cậu của con rốt cuộc bao giờ mới chịu học cách đừng có nhiều \"bạn bè\" đến vậy?"
  },
  AvgDialog_142891_Content_23 = {
    Text = "Mẹ bạn, Leisa, vừa buồn cười vừa bất lực nhìn bạn, thở dài rồi nhét đống trang sức vào chiếc hộp nhỏ sẽ được gửi lại cho thuyền trưởng chuyển giao khi tàu cập bến lần sau."
  },
  AvgDialog_142891_Content_24 = {
    Text = "Gia đình bạn kinh doanh một quán trọ nhỏ hết sức bình thường ở thị trấn ven biển, chỉ có một điều hơi đặc biệt……"
  },
  AvgDialog_142891_Content_25 = {
    Text = "Để ta xem cậu nhóc đẹp trai này là ai nào——"
  },
  AvgDialog_142891_Content_26 = {
    Text = "Cửa lớn lại mở toang cùng làn gió mang vị mặn, \"chuyện đặc biệt\" kia cười vang rồi ôm chặt lấy eo ngươi, quay ngươi một vòng trên không trung."
  },
  AvgDialog_142891_Content_27 = {
    Text = "Pontos! Nói bao nhiêu lần rồi, anh sẽ làm trật tay nó đấy!"
  },
  AvgDialog_142891_Content_28 = {
    Text = "Cậu Pontos!"
  },
  AvgDialog_142891_Content_29 = {
    Text = "Này, Jager nhỏ, xem cậu mang gì về cho cháu nào?"
  },
  AvgDialog_142891_Content_3 = {
    Text = "Một vầng trăng tròn sáng nhất mà bạn từng thấy treo lơ lửng trên bầu trời. Tứ chi của bạn Yếu đuối không còn sức lực, tư duy cũng có phần trì trệ."
  },
  AvgDialog_142891_Content_30 = {
    Text = "Cậu ấy búng tay một cái, năm ngón tay xòe ra trong không trung, một chiếc la bàn mạ đồng nặng trịch rơi vào lòng bàn tay bạn."
