  AvgDialog_142891_Content_31 = {
    Text = "Tốt nhất là thứ này kiếm được từ con đường chính đáng, ngôi nhà này không còn chỗ chứa thêm \"Tín Vật\" và \"trái tim tan vỡ\" nữa rồi."
  },
  AvgDialog_142891_Content_32 = {
    Text = "Leisa trêu chọc ném hộp trang sức cho anh ta, ngẩng cằm ra hiệu con tàu chở nửa còn lại của \"trái tim tan vỡ\" vừa rời bến."
  },
  AvgDialog_142891_Content_33 = {
    Text = "Ôi trời ơi…… bạn biết đấy, tôi thực sự không giỏi từ chối người khác."
  },
  AvgDialog_142891_Content_34 = {
    Text = "Pontos cười hì hì nghiêng đầu né tránh một đòn đánh nặng của Leisa, đặt bạn xuống đất."
  },
  AvgDialog_142891_Content_35 = {
    Text = "Nói đến đây, tôi đã quen biết một số bạn mới, chúng ta có lẽ cần nói chuyện, Leisa."
  },
  AvgDialog_142891_Content_36 = {
    Text = "Về những chuyện mà cô không muốn nhắc đến."
  },
  AvgDialog_142891_Content_37 = {
    Text = "Bạn mải mê nghiên cứu món đồ chơi mới trên tay, bỏ lỡ biểu cảm không mấy vui vẻ trên Khuôn Mặt Leisa, Pontos xoa xoa đầu bạn."
  },
  AvgDialog_142891_Content_38 = {
    Text = "Tôi và mẹ có chút chuyện cần nói, nếu người đàn ông mà tôi yêu quý nhất chịu lên lầu chơi một lúc, tôi sẽ kể cho cậu nghe vài câu chuyện du lịch thú vị, thỏa thuận nhé?"
