  AvgDialog_142891_Content_39 = {
    Text = "Anh ta xòe năm ngón tay ra, bạn vì chiếc la bàn mà đáp lại, đó là nghi thức \"bắt tay thỏa thuận\" chỉ thuộc về hai người các bạn."
  },
  AvgDialog_142891_Content_4 = {
    Text = "Giơ tay lên, những nếp nhăn tượng trưng cho tuổi già đã bò khắp làn da của bạn."
  },
  AvgDialog_142891_Content_41 = {
    Text = "Bạn nằm sấp trên sàn phòng ngủ tầng trên, lôi bản đồ ra, chuyên tâm thử dùng la bàn tìm những hướng đi trong các câu chuyện hàng hải."
  },
  AvgDialog_142891_Content_42 = {
    Text = "Nhưng ngôi nhà này quá cũ rồi, biển cả và gió không ngừng bào mòn nó, vẫn có vài mẩu lời lẻ tẻ lọt qua khe sàn vọng lên."
