  AvgDialog_142891_Content_44 = {
    Text = "……họ……tôi có thể……Tài năng của tôi……"
  },
  AvgDialog_142891_Content_45 = {
    Text = "Giọng cậu Pontos ngày càng gấp gáp, cậu vừa tò mò định áp tai lại gần thì——"
