  AvgDialog_142891_Content_46 = {
    Text = "Rầm! Bịch!"
  },
  AvgDialog_142891_Content_47 = {
    Text = "Cửa bị đẩy bật ra một cái rầm, Pontos bị túm cổ áo ném vào trong, Leisa nghiêm mặt với biểu cảm mang ý nghĩa \"không có gì để bàn cãi\"."
  },
  AvgDialog_142891_Content_48 = {
    Text = "Tôi không đồng ý, Pontos. Nguyện vọng duy nhất của tôi là các em đều bình an vô sự……tránh xa mấy người bạn mới của em ra."
  },
  AvgDialog_142891_Content_49 = {
    Text = "Nếu mọi chuyện thật sự không kiểm soát được, tôi sẽ đưa các em rời khỏi đây."
  },
  AvgDialog_142891_Content_5 = {
    Text = "À, hóa ra ta đã đến cái tuổi này rồi… Có lẽ tối nay là đêm cuối cùng."
  },
  AvgDialog_142891_Content_50 = {
    Text = "Này, Leisa, em không còn là trẻ con nữa rồi! Chúng ta không thể cứ chạy trốn mãi thế này."
  },
  AvgDialog_142891_Content_51 = {
    Text = "Học cách giúp tôi xử lý công việc kinh doanh trước đã, đừng suốt ngày lang thang bên ngoài rồi hãy nói chuyện này."
  },
  AvgDialog_142891_Content_52 = {
    Text = "Bạn hiếm khi nghe Leisa nói chuyện với giọng nghiêm khắc như vậy, cô ấy hít một hơi, miễn cưỡng nở một nụ cười với bạn."
  },
  AvgDialog_142891_Content_53 = {
    Text = "Yage, giúp mẹ một việc. Trông chừng cậu con, ít nhất tối nay đừng để ông ấy đi lang thang nữa."
  },
  AvgDialog_142891_Content_54 = {
    Text = "Cô ấy bỏ lại những lời đó, vội vàng xuống lầu lật những cuốn sổ kế toán không bao giờ lật hết, dường như muốn kết thúc chủ đề này càng sớm càng tốt."
