  AvgDialog_142891_Content_58 = {
    Text = "Có lẽ vì những câu chuyện ly kỳ từ khoang tàu cùng hàng hóa lăn ra quá hấp dẫn, đến tận nửa đêm, cậu vẫn ngủ không sâu."
  },
  AvgDialog_142891_Content_59 = {
