  AvgDialog_142892_Content_9 = {
    Text = "Đất diệt."
  },
  AvgDialog_142892_Content_90 = {
    Text = "Olney của Erboyance, chú White, mỗi người trong sàn nhảy chật ních, dường như đều đồng loạt chú ý đến nơi đây."
