  AvgDialog_142893_Content_10 = {
    Text = "<Red:Không nên là như vậy.>"
  },
  AvgDialog_142893_Content_11 = {
    Text = "Đáng lẽ cậu sẽ tình cờ biết được huyết mạch của mình, mẹ được cậu Pontos thuyết phục rồi hướng dẫn cậu, cùng nhau bước vào hành trình, trải qua nhiều chuyện ly kỳ, hồi hộp và thú vị."
