  AvgDialog_142893_Content_12 = {
    Text = "<Shake:Rồi bạn sẽ trở thành một <Red:dũng sĩ> vĩ đại, trong tiểu thuyết phiêu lưu đều viết như vậy.>"
  },
  AvgDialog_142893_Content_13 = {
    Text = "Yage! Hãy vững lên, không sao đâu, mẹ của bạn là Kẻ Điều Khiển Ác Mộng mạnh nhất mà tôi từng thấy, mọi thứ rồi sẽ được giải quyết thôi!"
