  AvgDialog_142893_Content_16 = {
    Text = "Chỉ là một ngày trôi qua, những kẻ cuồng tín xuất hiện đột ngột, tràn ngập khắp nơi, nhấn chìm tất cả những gì bạn có thể nhìn thấy."
