  AvgDialog_142893_Content_2 = {
    Text = "Đêm hôm đó, vì quá sợ hãi và mệt mỏi do suy nghĩ nhiều, cậu nhanh chóng chìm vào giấc ngủ."
  },
  AvgDialog_142893_Content_20 = {
    Text = "Leisa, người đang cùng các Kẻ Điều Khiển Ác Mộng khác ra sức ngăn chặn làn sóng quái vật tiến đến, thấy bạn bình an vô sự, Đôi Mắt sáng lên, gào thét khản cổ vào mặt Pontos."
