  AvgDialog_142893_Content_21 = {Text = "Chít!"},
  AvgDialog_142893_Content_22 = {
    Text = "Thêm một cái đầu giống hải quỳ bị vuốt sắc của Yểm xé nát, Leisa tiện tay phóng ra một luồng bạch quang u ám giống như của Pontos, ngăn Pontos lao về phía bà."
  },
  AvgDialog_142893_Content_23 = {
    Text = "Lần này chúng ta không thắng nổi đâu, nhưng vẫn có thể câu giờ cho các người, chạy đi, chạy càng xa càng tốt!"
  },
  AvgDialog_142893_Content_24 = {
    Text = "Đùa gì vậy, kẻ thù đông hơn thế này bạn cũng đã từng dễ dàng giải quyết, sẽ không sao đâu! Hơn nữa, bạn biết đấy, chúng ta vẫn còn cách."
  },
  AvgDialog_142893_Content_25 = {
    Text = "Bạn không biết cái gọi là cách giải quyết của cậu Pontos là gì, Chỉ là thấy Ánh Mắt ông đặt vào chiếc còi săn mà từ lúc trở về lần này ông chưa rời ra lần nào."
  },
  AvgDialog_142893_Content_26 = {
