  AvgDialog_142893_Content_29 = {Text = "Leisa!!!"},
  AvgDialog_142893_Content_3 = {
    Text = "Cậu và Pontos đều nghĩ rằng hai người còn rất nhiều cơ hội để nói chuyện về chuyện này."
  },
  AvgDialog_142893_Content_30 = {
    Text = "Giữa tiếng vảy vỡ rầm rộ, một kẻ cuồng tín với nửa thân người đã bị xé toạc, nhãn cầu Đỏ tươi lồi hẳn ra ngoài, Hung bạo lầm bầm lao về phía Leisa."
  },
  AvgDialog_142893_Content_31 = {
