  AvgDialog_142893_Content_43 = {
    Text = "Không ai sống sót, những Chúa Tể Mộng Quỷ ngày thường Dường như Chỉ là những người hàng xóm thân thiện lần lượt ngã xuống, những người dân bình thường khác trong thị trấn kêu la thảm thiết trong biển lửa và làn sóng quái vật."
