  AvgDialog_142893_Content_44 = {
    Text = "Còn bạn đã không còn nghe thấy những điều này nữa, cơ thể bạn hoàn toàn phản bội bạn, đang cùng với họ, cất lên tiếng hú khóc thê lương."
