  AvgDialog_145231_Content_29 = {
    Text = "Gai nhọn trên đầu ngón tay của bộ giáp trượt dọc theo đường hàm của bạn, lướt qua cổ họng, lướt qua ngực, lướt qua eo bụng… Bạn ra sức vùng vẫy, miệng phát ra những âm tiết vô nghĩa, nhưng đôi kiếm lớn kia vững như bàn thạch, không nhúc nhích."
  },
  AvgDialog_145231_Content_3 = {
    Text = "Á! Ai vậy——"
  },
  AvgDialog_145231_Content_30 = {
