  },
  AvgDialog_145231_Content_31 = {
    Text = "Máu Tươi chảy dọc theo khóe miệng đang mỉm cười của cô ấy, nhỏ xuống Khuôn Mặt bạn."
  },
  AvgDialog_145231_Content_32 = {
    Text = "Hãy ra sức vùng vẫy đi. Để ta xem, liệu ngươi có thể thoát khỏi nơi này không… \"đối thủ\" của ta."
