  },
  AvgDialog_14530_Content_19 = {
    Text = "Cảm giác ngạt thở còn sót lại khiến bạn không nhịn được vỗ vỗ ngực, bạn từ từ ngồi dậy, phải một lúc lâu mới thực sự cảm nhận được mình đã tỉnh."
