  },
  AvgDialog_14530_Content_38 = {
    Text = "Lúc đó, chủ thể tinh thần có nhận ra người đến thăm hay không, và sẽ có thái độ như thế nào với họ…… ha, nghĩ thôi đã thấy thú vị rồi."
  },
  AvgDialog_14530_Content_39 = {
    Text = "Nếu Mật Cảnh Nhân Tạo khả thi, nó sẽ trở thành phương thức tốt nhất để Điều Tra Viên, Thủ Mật Nhân cùng Thể Đánh Thức của mình xây dựng sự ăn ý và hiểu biết lẫn nhau sâu sắc hơn."
  },
  AvgDialog_14530_Content_4 = {
    Text = "Bạn đang rơi xuống."
  },
  AvgDialog_14530_Content_40 = {
