  AvgDialog_145512_Content_34 = {
    Text = "Tất nhiên được!"
  },
  AvgDialog_145512_Content_35 = {
    Text = "Caraboo bước sang một bên, nhường vị trí đối diện với pháp trận cho Bạn."
  },
  AvgDialog_145512_Content_36 = {
    Text = "Sợi Chỉ của Môi Lai, là món quà tặng từ Arachne."
  },
  AvgDialog_145512_Content_37 = {
    Text = "Gương Bát Xích, nhặt được bên bờ hồ băng nơi tinkerer lang thang."
  },
  AvgDialog_145512_Content_38 = {
    Text = "Lông Vũ Ma'at, rơi xuống từ Tuyết gió sau khi Cas-tơ-lơ rời đi."
  },
  AvgDialog_145512_Content_39 = {
    Text = "Mắt Balor, đông kết trong vũng Máu của Hiro."
  },
  AvgDialog_145512_Content_4 = {
    Text = "Nhãn cầu đó đột nhiên trở nên hung tàn, đồng tử đỏ thẫm ánh lên ánh Máu và trợn to ra."
  },
  AvgDialog_145512_Content_40 = {
    Text = "Táo Vàng, Caraboo không biết lấy ra từ cái túi nào."
