  AvgDialog_145512_Content_41 = {
    Text = "Chìa Khóa Solomon, thực ra chính là chìa khóa bạc bạn mang theo bên mình."
  },
  AvgDialog_145512_Content_42 = {
    Text = "Còn nữa, thứ mà đội thám hiểm trước tìm được, Vương Miện Ariadne…"
