  AvgDialog_145512_Content_44 = {
    Text = "Vương Miện Ariadne… cái này là Vương Miện Ariadne gì chứ, đây chẳng phải là <Yellow:Vương Miện của tulô> sao!"
  },
  AvgDialog_145512_Content_45 = {
    Text = "Có gì mà phải ầm ĩ vậy? Táo Vàng cũng đâu có màu vàng?"
  },
  AvgDialog_145512_Content_46 = {
    Text = "Nhưng mà, Vương Miện của tulô, tại sao lại ở đây?"
  },
  AvgDialog_145512_Content_47 = {
    Text = "Bởi vì, đây là pháp khí của Ngài, lễ vật dâng lên Ngài, nguyên liệu nấu ăn mà Ngài yêu thích nhất."
  },
  AvgDialog_145512_Content_48 = {
    Text = "Theo lời Caraboo vừa dứt, Đất bỗng nhiên rung động dữ dội."
  },
  AvgDialog_145512_Content_49 = {
    Text = "Chuyện gì xảy ra vậy?"
