  AvgDialog_145512_Content_51 = {
    Text = "…Cười?"
  },
  AvgDialog_145512_Content_52 = {
    Text = "Đỉnh núi rung động từng đợt từng đợt, dường như một thiếu nữ đang ở độ tuổi xuân thì, đang cười vì chứng kiến điều gì đó thú vị, cười đến rung rinh cả người."
  },
  AvgDialog_145512_Content_53 = {
    Text = "Tuyết tích tụ rơi xuống."
  },
  AvgDialog_145512_Content_54 = {
    Text = "Đỉnh nhọn kia không phải là núi non, mà là con sâu khổng lồ đang cuộn mình trên đỉnh núi, tựa như con rắn khổng lồ có thể nuốt trời nuốt đất."
  },
  AvgDialog_145512_Content_55 = {
    Text = "Vì sự yếu đuối của con người khi không thể đối mặt với thực tại, họ đã chọn tin vào Lời Nói Dối, gửi gắm ước nguyện cho những Thần Minh Hư vô."
  },
  AvgDialog_145512_Content_56 = {
    Text = "Họ chưa bao giờ nghĩ đến — rằng những Thần Minh kia, cũng biết nói dối. Bởi vì Thần Minh cũng có những ước nguyện của riêng mình muốn thực hiện."
  },
  AvgDialog_145512_Content_57 = {
    Text = "Ước nguyện của Thần Minh, chính là — ăn thịt họ."
  },
  AvgDialog_145512_Content_58 = {
    Text = "Vương Miện, Sợi Chỉ, Chìa Khóa Bạc, trái cấm, lông vũ, gương sáng, mắt ma thuật. Bảy pháp khí, chính là những Lễ vật được hóa thành từ Sinh lực của những con người Tham lam đó."
  },
  AvgDialog_145512_Content_59 = {
    Text = "Tất cả mọi thứ của các bạn, chẳng qua chỉ là một bữa ăn no nê của Ngài mà thôi."
  },
  AvgDialog_145512_Content_6 = {
    Text = "Mắt Balor, ma nhãn của ác thần. Đủ sức hủy diệt tất cả những gì bị nhìn vào, nhưng lại là điểm yếu duy nhất của Ngài."
  },
  AvgDialog_145512_Content_60 = {
    Text = "Bây giờ, Ngài đã có được thứ Ngài muốn, tất nhiên Ngài phải cười rồi!"
  },
  AvgDialog_145512_Content_61 = {
    Text = "Sự việc đã đến mức này, đã đến lúc nói thật với chúng tôi rồi chứ?"
  },
  AvgDialog_145512_Content_62 = {
    Text = "Bạn hoàn toàn không phải như cách bạn diễn, tình cờ bám vào chuyến hành trình này."
  },
  AvgDialog_145512_Content_63 = {
    Text = "Nói đúng hơn, cả đội leo núi đã đi đến bước này dưới sự dẫn dắt của bạn."
  },
  AvgDialog_145512_Content_64 = {
    Text = "Cuộc gặp gỡ tình cờ trong hang động lúc đầu với Cas-tơ-lơ, lựa chọn của tinkerer khi đi ngắm hồ băng…"
  },
  AvgDialog_145512_Content_65 = {
    Text = "Và cả Hiro cứ đi theo chúng tôi mãi, thực ra bạn đã dự đoán trước tất cả từ lâu rồi."
