  AvgDialog_145512_Content_66 = {
    Text = "Rốt cuộc bạn là người như thế nào?"
  },
  AvgDialog_145512_Content_7 = {
    Text = "Chủ nhân của Bạn không nói cho Bạn biết sao? Nhãn cầu này, chỉ khi thấm đẫm Máu Tươi của Bạn, mới đủ tư cách được gọi là \"Mắt Balor\"."
  },
  AvgDialog_145512_Content_8 = {
    Text = "Hắn nói…"
