  },
  AvgDialog_145513_Content_1 = {
    Text = "Liên Minh Dối Trá"
  },
  AvgDialog_145513_Content_10 = {
    Text = "<Yellow:Chính mày đã đốt gói hàng của tao phải không>? Xem tao không vạch trần cái mặt nạ người của mày—"
  },
  AvgDialog_145513_Content_11 = {
    Text = "Cô ấy nắm chặt hai má của Naraka, kéo giật sang hai bên."
