  AvgDialog_145513_Content_13 = {
    Text = "Roạc——"
  },
  AvgDialog_145513_Content_14 = {
    Text = "Cái xác mang tên \"Naraka\" đó, như một con búp bê cao su trong tay đứa trẻ nghịch ngợm, bị xé toạc thành hai mảnh."
  },
  AvgDialog_145513_Content_15 = {
    Text = "Từ vết nứt ùa ra cuồn cuộn, là làn khói đen mang tên \"Hỗn Mang\"."
  },
  AvgDialog_145513_Content_16 = {
    Text = "Khói cuộn trào, xoắn lại, ngưng tụ, rồi phóng túng đưa ra một bông hồng."
  },
  AvgDialog_145513_Content_17 = {
    Text = "Lại gặp nhau rồi, người bạn cũ."
  },
  AvgDialog_145513_Content_18 = {
    Text = "Trước khi hàn huyên, hãy khởi động một chút để xoa dịu tên lừa đảo nhỏ đang nổi giận của chúng ta nhé?"
