  AvgDialog_145513_Content_2 = {
    Text = "Ở cuối Sợi Chỉ, cô gái bước ra từ bóng tối."
  },
  AvgDialog_145513_Content_3 = {
    Text = "Ồ, kẻ lừa đảo nhỏ, đã tự đặt cược cả bản thân mình vào rồi sao?"
  },
  AvgDialog_145513_Content_4 = {
    Text = "Lời nói của Naraka đã chọc giận cô gái vốn đã cúi đầu buồn bã."
