  AvgDialog_145513_Content_5 = {
    Text = "Bạn thật nhàn hạ nhỉ."
  },
  AvgDialog_145513_Content_6 = {
    Text = "Caraboo ngẩng đầu, đôi mắt đầy phẫn nộ nhìn chằm chằm vào Naraka."
  },
  AvgDialog_145513_Content_7 = {
    Text = "Thôi diễn đi, một hướng dẫn viên Sherpa, bị nuốt vào bụng núi, mà vẫn còn tâm trạng đùa giỡn?"
  },
  AvgDialog_145513_Content_8 = {
    Text = "Từ lần đầu gặp bạn tôi đã biết rồi, tên này, cũng là một kẻ lừa đảo."
  },
  AvgDialog_145513_Content_9 = {
    Text = "Caraboo lao bổ vào. Lần này, cô ấy không cho phép Naraka né tránh."
  },
  AvgDialog_145514_Content_1 = {
    Text = "Con Wendigo cuối cùng, tan biến dưới bóng của Cas-tơ-lơ."
  },
  AvgDialog_145514_Content_10 = {
    Text = "Có lẽ mối quan hệ giữa người với người đều Bắt đầu từ việc tiết lộ một bí mật nhỏ nào đó, phải không?"
  },
  AvgDialog_145514_Content_11 = {
    Text = "Không biết từ lúc nào, Caraboo đã tiến lại gần, cười tươi nói ra trước mặt bạn đúng những điều bạn đang nghĩ trong lòng."
  },
  AvgDialog_145514_Content_12 = {
    Text = "Trao đổi bí mật không phải chuyện một chiều đâu nhé."
  },
  AvgDialog_145514_Content_13 = {
    Text = "Người mà bạn đã Gọi nhiều lần — Dì Rosa ấy, có phải là người rất quan trọng không?"
  },
  AvgDialog_145514_Content_14 = {
    Text = "Tất nhiên là tôi bịa ra rồi. Bạn không thật sự tin chứ?"
  },
  AvgDialog_145514_Content_15 = {
    Text = "Hừ hừ, lừa được kẻ ngốc thì chẳng có gì lạ, nhưng lừa được bạn mới là chuyện không dễ."
  },
  AvgDialog_145514_Content_16 = {
    Text = "Khiến Wendigo tin rằng bạn đã bị mê hoặc còn khó hơn nhiều so với việc lừa tôi."
  },
  AvgDialog_145514_Content_17 = {
    Text = "Chúng có thể nghe thấy tiếng lòng của bạn, rồi dùng gió để đọc lại."
  },
  AvgDialog_145514_Content_18 = {
    Text = "Thì ai mà biết được chứ? Có lẽ trong lòng Nữ thần Tuyết Sơn có quá nhiều câu chuyện, mỗi câu chuyện đều như thật cả?"
  },
  AvgDialog_145514_Content_19 = {
    Text = "Caraboo dùng một câu đùa nhẹ nhàng để lướt qua chuyện đó."
