  AvgDialog_145514_Content_2 = {
    Text = "Rồi cơn gió lướt qua bên tai bỗng trở nên trong lành hơn. Trong gió không còn lẫn bất kỳ âm thanh nào nữa."
  },
  AvgDialog_145514_Content_20 = {
    Text = "Đã vậy bạn không muốn nói, chúng tôi cũng sẽ không ép hỏi đâu."
  },
  AvgDialog_145514_Content_21 = {
    Text = "Nhưng chân thành là thứ rất quý giá, dù bạn là kẻ lừa đảo, cũng tốt nhất đừng để mọi người thất vọng."
  },
  AvgDialog_145514_Content_22 = {
    Text = "Đây là lời khuyên chân thành của tôi, nghe hay không là tùy bạn."
