  AvgDialog_145514_Content_24 = {
    Text = "Thật vậy sao."
  },
  AvgDialog_145514_Content_25 = {
    Text = "{Male=恩公,Female=恩人}, chắc chắn bạn sẽ không vô tâm như anh ấy đúng không?"
  },
  AvgDialog_145514_Content_26 = {
    Text = "Tôi và William đã sát cánh chiến đấu trong một thời gian dài, anh ấy không phải người thích nói những lời thừa."
  },
  AvgDialog_145514_Content_27 = {
    Text = "Trong ký ức của tôi, mỗi lời khuyên ông ấy đưa ra đều có hiệu quả."
  },
  AvgDialog_145514_Content_28 = {
    Text = "<Shake:Huhu, {Male=恩公,Female=恩人}, bạn cũng lạnh lùng quá vậy……>"
  },
  AvgDialog_145514_Content_29 = {
    Text = "Caraboo giả vờ buồn bã rồi bỏ đi, còn bạn thì đuổi kịp William đang trò chuyện với Naraka."
