  AvgDialog_145514_Content_3 = {
    Text = "Yên tĩnh đồng nghĩa với an toàn, thế nhưng sự an toàn ấy lại khiến người ta cảm thấy hụt hẫng."
  },
  AvgDialog_145514_Content_30 = {
    Text = "Ông ấy ra hiệu bằng mắt bảo bạn bước ra xa vài bước, cho đến khi những người bên cạnh không còn nghe thấy tiếng thầm thì của hai người."
  },
  AvgDialog_145514_Content_31 = {
