  AvgDialog_145514_Content_32 = {Text = "Đâu?"},
  AvgDialog_145514_Content_33 = {Text = "Naraka."},
  AvgDialog_145514_Content_34 = {
    Text = "Bạn hãy nhớ lại, từ lúc những tiếng động trong gió vang lên, đến khi Wendigo xuất hiện, rồi đến lúc vừa rồi bao vây—"
  },
  AvgDialog_145514_Content_35 = {
