  AvgDialog_145515_Content_11 = {
    Text = "Lời chưa dứt, cô ấy đã chạy về phía sườn dốc thoải bên kia."
  },
  AvgDialog_145515_Content_12 = {
    Text = "Đó là một tế đàn sáu góc."
