  AvgDialog_145515_Content_13 = {
    Text = "Tại trung tâm tế đàn, đã có một chiếc Vương Miện được đặt lên."
  },
  AvgDialog_145515_Content_14 = {
    Text = "Người phụ nữ khoác đầy xiềng xích kiểm đếm những báu vật cướp được. %player%Chìa Khóa Bạc và Sợi Chỉ trong túi, gương, Lông đen, Táo vàng trong gói đồ của Caraboo."
