  },
  AvgDialog_145515_Content_17 = {
    Text = "Một tiếng bọp, quả cầu xích phát ra âm thanh kỳ lạ sền sệt."
  },
  AvgDialog_145515_Content_18 = {
    Text = "Cô ấy khuấy động, móc bới… cho đến khi lấy ra được một nhãn cầu dính Máu."
