  AvgDialog_145515_Content_23 = {
    Text = "Hãy cho Sự phục sinh của cô ấy… hãy để ta tự tay giết kẻ thù, thực hiện mối thù hận lâu dài của ta."
  },
  AvgDialog_145515_Content_24 = {
    Text = "Cơn gió lạnh buốt thổi qua đỉnh núi Vùng Tuyết. Điều ước của cô ấy không nhận được bất kỳ hồi đáp nào."
  },
  AvgDialog_145515_Content_25 = {
    Text = "Tại sao? Chẳng phải ta đã dâng đủ bảy lễ vật cúng bái cho ngươi rồi sao?"
  },
  AvgDialog_145515_Content_26 = {
    Text = "Tiếng chất vấn của Hiro Vang vọng giữa những đỉnh núi xa, gây ra hết đợt tuyết lở nhỏ này đến đợt khác."
  },
  AvgDialog_145515_Content_27 = {
    Text = "Bởi vì, có lễ vật là giả mà?"
  },
  AvgDialog_145515_Content_28 = {Text = "Ai?!"},
  AvgDialog_145515_Content_29 = {
    Text = "Caraboo nhảy tung tăng, bước lên phía trước nhẹ nhàng, Dường như hoàn toàn không coi Hiro ra gì."
  },
  AvgDialog_145515_Content_3 = {
    Text = "Đây là nơi dấu chân con người chưa từng đặt tới."
  },
  AvgDialog_145515_Content_30 = {
    Text = "Các ngươi ấy, lòng Chỉ nghĩ đến điều ước của bản thân, mà chưa bao giờ suy nghĩ xem Thần Minh thực sự muốn lễ vật gì."
  },
  AvgDialog_145515_Content_31 = {
    Text = "Táo Vàng, Táo Vàng, chẳng lẽ Bạn nghĩ Chỉ cần là Táo màu vàng là chọn đúng rồi sao?"
  },
  AvgDialog_145515_Content_32 = {
    Text = "Cô ấy bưng quả Táo Vàng trên bàn thờ lên, nhẹ nhàng cắn một miếng."
