  AvgDialog_145515_Content_33 = {
    Text = "Ừm ừm, đúng là Bạn rồi."
  },
  AvgDialog_145515_Content_34 = {
    Text = "Lớp giấy bạc màu vàng theo đó bong ra, lộ ra bộ mặt thật bên trong."
  },
  AvgDialog_145515_Content_35 = {
    Text = "Đồ ăn vặt, kẹo, khối ca cao, gọi bằng tên gì cũng được, tóm lại là socola bình thường không thể bình thường hơn."
  },
  AvgDialog_145515_Content_36 = {
    Text = "<BigShake:Xèng xèng! phúc lành của tiên nữ, món ngon tuyệt hảo!>"
