  AvgDialog_145515_Content_38 = {
    Text = "Kẻ cướp cũng chẳng tốt hơn kẻ lừa đảo là bao nhỉ?"
  },
  AvgDialog_145515_Content_39 = {
    Text = "Thôi dài dòng, đưa Táo Vàng thật ra đây!"
  },
  AvgDialog_145515_Content_4 = {
    Text = "Đứng trên đỉnh Tuyết sơn, nhìn xa những dãy núi trắng xóa, thứ Vang vọng trong lồng ngực, lại không phải là cảm giác Thành Tựu khi lên đến đỉnh."
  },
  AvgDialog_145515_Content_40 = {
    Text = "Vậy thì ngươi phải hỏi xem họ có đồng ý không đã."
  },
  AvgDialog_145515_Content_41 = {
    Text = "Caraboo nghiêng người, đội leo núi đang trèo qua vách đá cuối cùng."
