  AvgDialog_145515_Content_5 = {
    Text = "Mà là Sợ hãi."
  },
  AvgDialog_145515_Content_6 = {
    Text = "Nỗi Sợ hãi khi xa rời cõi người, nỗi Sợ hãi khi bị cách ly khỏi những gì quen thuộc."
  },
  AvgDialog_145515_Content_7 = {
    Text = "Nơi đây không còn đỉnh cao nào xa hơn, người lên đến đỉnh Chỉ có thể quỳ xuống bái lạy bầu trời."
