  AvgDialog_145516_Content_1 = {
    Text = "Người Tiên Phong"
  },
  AvgDialog_145516_Content_10 = {
    Text = "Vẫn còn thiếu <Blue:Chìa Khóa Solomon> và <Blue:Mắt Balor>."
