  AvgDialog_145516_Content_13 = {
    Text = "Câu đùa này chẳng buồn cười chút nào."
  },
  AvgDialog_145516_Content_14 = {
    Text = "Bạn không biết chuyện gì đã xảy ra với Cas-tơ-lơ, nhưng trên chiếc Lông Vũ đen tuyền kia vẫn còn lưu lại hơi thở của anh ấy."
  },
  AvgDialog_145516_Content_15 = {
    Text = "Phía trước không còn xa nữa."
  },
  AvgDialog_145516_Content_16 = {
    Text = "Trước khi đến đỉnh, chúng ta không thể quay đầu."
  },
  AvgDialog_145516_Content_17 = {
    Text = "William vỗ vai bạn. Rõ ràng, anh ấy biết bạn đang nghĩ gì."
