  AvgDialog_145516_Content_18 = {
    Text = "Bạn có biết không? Tôi có một linh cảm."
  },
  AvgDialog_145516_Content_19 = {
    Text = "Cas-tơ-lơ chắc chắn đã tìm thấy thứ mình muốn theo đuổi, nên mới rời khỏi đội."
  },
  AvgDialog_145516_Content_2 = {
    Text = "Đây là điểm nghỉ ngơi cuối cùng trước khi chinh phục đỉnh núi."
