  AvgDialog_145516_Content_20 = {
    Text = "Hơn nữa, nếu là anh ấy, chắc chắn sẽ thực hiện được ước nguyện thôi."
  },
  AvgDialog_145516_Content_21 = {
    Text = "Evelyn khẽ hắng giọng, như thể để lời nói của mình thêm phần trọng lượng, rồi bổ sung thêm một câu."
  },
  AvgDialog_145516_Content_22 = {
    Text = "Chỉ cần người ta sống đủ lâu, sẽ có thể Nhìn lén xu hướng số phận của người khác qua những khoảng thời gian ngắn ngủi bên nhau."
  },
  AvgDialog_145516_Content_23 = {
    Text = "Ở Cas-tơ-lơ, bạn nhìn thấy điều gì?"
