  },
  AvgDialog_145516_Content_3 = {
    Text = "Nhìn lại những ngọn núi xa xa, dưới chân là biển tuyết bao la, chìm khuất vào chân trời xa thẳm giữa màn mây mù của thung lũng."
  },
  AvgDialog_145516_Content_30 = {
    Text = "Nếu đã chuẩn bị xong, thì hãy Bắt đầu chặng cuối cùng thôi."
  },
  AvgDialog_145516_Content_31 = {
    Text = "Đừng lơ là. Rất nhiều sự cố xảy ra ở một nghìn mét cuối cùng."
  },
  AvgDialog_145516_Content_32 = {
    Text = "Sừng sững trước mặt các bạn là một vách băng gần như thẳng đứng."
  },
  AvgDialog_145516_Content_33 = {
    Text = "Naraka vung chiếc rìu băng lên, đầu rìu xiên xuống đập vào tuyết cứng, phát ra một tiếng bịch, rồi nâng trọng tâm lên một chút, móc băng bước chính xác vào hố nhỏ mà đầu rìu vừa để lại."
