  AvgDialog_145517_Content_27 = {
    Text = "Cas-tơ-lơ không nghe theo. Anh Chỉ là tiếp tục tiến về phía Pollux."
  },
  AvgDialog_145517_Content_28 = {
    Text = "Dù đó có là Wendigo cũng không sao. Anh Chỉ tiến về phía trước."
  },
  AvgDialog_145517_Content_29 = {
    Text = "Pollux giơ dao lên. Chiếc dao quen thuộc. Trong lần Truy bắt trước, Cas-tơ-lơ đã từng bị nó Xuyên thấu qua ngực."
  },
  AvgDialog_145517_Content_3 = {
    Text = "Không còn gì có thể ngăn cản cậu nữa."
  },
  AvgDialog_145517_Content_30 = {
    Text = "<Big:Tiến thêm một bước nữa, ánh sáng thánh thần sẽ trừng phạt ngươi!>"
  },
  AvgDialog_145517_Content_4 = {
