  AvgDialog_145517_Content_5 = {
    Text = "Con Đường không phải gánh nặng Lời Nói Dối, khiến tâm hồn cậu cũng nhẹ bẫng bay lên."
  },
  AvgDialog_145517_Content_6 = {
    Text = "Xin lỗi, tôi không nên lừa dối các bạn."
