  AvgDialog_145518_Content_106 = {
    Text = "-Độ cao 6000m-"
  },
  AvgDialog_145518_Content_11 = {
    Text = "Tôi biết điều này rất khó tin, nhưng tôi đến từ một nơi rất rất xa. Lưu lạc quá lâu quá lâu, tôi chỉ nhớ rằng, trong những ngày cuối cùng, chúng tôi gọi nó là <Blue:Sao hoang>."
  },
  AvgDialog_145518_Content_12 = {
    Text = "Tôi đã Trải nghiệm một khoảng thời gian dài đến mức không thể đếm được, mới đến được nơi đây."
  },
  AvgDialog_145518_Content_13 = {
    Text = "Tôi tin bạn."
  },
  AvgDialog_145518_Content_14 = {
