  },
  AvgDialog_145518_Content_15 = {
    Text = "Nhưng vừa rồi, tôi dường như trong mặt hồ… nhìn thấy chị gái tôi, Phiệt."
  },
  AvgDialog_145518_Content_16 = {
    Text = "tinkerer cắn nhẹ môi."
  },
  AvgDialog_145518_Content_17 = {
    Text = "Không, thực ra cũng không phải… Chỉ là tôi cảm nhận được một điềm báo nào đó, bóng hình trong hồ, cũng đến từ Sao hoang…"
  },
  AvgDialog_145518_Content_18 = {
    Text = "Tôi biết điều này hoàn toàn không thể, nhưng tôi cảm thấy, <Shake:đó không phải ảo giác……>"
  },
  AvgDialog_145518_Content_19 = {
    Text = "Bạn trông có vẻ rất mệt mỏi."
  },
  AvgDialog_145518_Content_2 = {
    Text = "gió tuyết không biết từ lúc nào đã ngừng, giữa trời đất chỉ còn lại một sự tĩnh lặng trống rỗng đến rùng mình. Phía trên đầu là bầu trời xanh thẳm không một gợn mây, ngay cả những đỉnh tuyết xa xa cũng hiện ra rõ nét từng chi tiết."
  },
  AvgDialog_145518_Content_20 = {
    Text = "Evelyn lộ vẻ lo lắng trên mặt."
  },
  AvgDialog_145518_Content_21 = {
    Text = "Nếu cảm thấy mệt, hãy nghỉ ngơi kịp thời."
  },
  AvgDialog_145518_Content_22 = {
    Text = "Mới xuất phát chưa lâu, một mình xuống núi cũng không nguy hiểm lắm."
  },
  AvgDialog_145518_Content_23 = {
    Text = "<Yellow:<Big:Không……! Tôi không mệt! Tôi sẽ không rút lui!>>"
  },
  AvgDialog_145518_Content_24 = {
    Text = "Ngoài sự mong đợi của tất cả mọi người, tinkerer bỗng hét lên như phản xạ."
  },
  AvgDialog_145518_Content_25 = {
    Text = "Nhận ra Ánh Mắt của mọi người đang nhìn về phía mình, tinkerer cố tỏ ra bình tĩnh, nhưng lồng ngực phập phồng vẫn phản lộ cảm xúc thật của cô ấy."
  },
  AvgDialog_145518_Content_26 = {
    Text = "Mất bình tĩnh rồi. Cảm ơn bạn đã quan tâm, <Yellow:tôi không mệt>."
  },
  AvgDialog_145518_Content_27 = {
    Text = "Nói dối chẳng hay ho gì đâu."
