  },
  AvgDialog_145518_Content_31 = {
    Text = "Bạn hành quân nửa ngày, tìm được một khoảng đất bằng phẳng để dựng trại, Naraka dặn tất cả người leo núi thu thập Tuyết tan, dùng bếp gas cao nguyên để đun nước."
  },
  AvgDialog_145518_Content_32 = {
