  AvgDialog_145518_Content_97 = {
    Text = "Hình như không có. Suốt Đường này tôi luôn đề phòng sự truy dấu của Giáo Hội Đèn Lồng. Nhưng các bạn là nhóm người đầu tiên tôi gặp..."
