  AvgDialog_145518_Content_98 = {
    Text = "Tôi cũng không cảm thấy vậy."
  },
  AvgDialog_145518_Content_99 = {
    Text = "Vậy à? Thì cứ coi như tôi nghĩ nhiều quá vậy."
  },
  AvgDialog_145519_Content_10 = {
    Text = "Gương Bát Xích, cùng với kiếm Kusanagi và ngọc Yasakani no Magatama, được gọi chung là Tam Thần Khí trong thần thoại Nhật Bản. Trong các bức tranh phổ biến, Gương Bát Xích thường được làm bằng kim loại, mặt sau gương khắc hoa văn phong cách Nhật Bản."
  },
  AvgDialog_145519_Content_11 = {
    Text = "Nhưng bạn hãy nhìn chiếc gương này…"
  },
  AvgDialog_145519_Content_12 = {
    Text = "Mặt gương mỏng manh, phẳng lặng, bóng loáng, hình dáng tròn trịa, tựa như vầng trăng sáng treo cao trên bầu trời."
  },
  AvgDialog_145519_Content_13 = {
    Text = "Dưới bề mặt kính lạnh giá, dường như có những hạt ánh sáng mờ ảo nào đó đang lưu chuyển."
