  AvgDialog_145519_Content_14 = {
    Text = "Dù sao thì, hãy lấy ra xem thử đã."
  },
  AvgDialog_145519_Content_15 = {
    Text = "Naraka giơ một chiếc dùi băng lên, dễ dàng đục vỡ lớp băng và lấy ra chiếc gương đó."
  },
  AvgDialog_145519_Content_16 = {
    Text = "Caraboo lướt người tiến lên, giật lấy một cái, rồi nhanh chóng cất nó vào túi hành lý mang theo."
  },
  AvgDialog_145519_Content_17 = {
    Text = "<Shake:Làm gì vậy! Nhìn gì, đừng nhìn tôi!>"
  },
  AvgDialog_145519_Content_18 = {
    Text = "Đây vốn là bảo vật của Nữ thần Tuyết Sơn, phát hiện ra thì đương nhiên phải thuộc về tôi!"
  },
  AvgDialog_145519_Content_19 = {
    Text = "Không ai cố tranh giành quyền sở hữu với cô ấy."
  },
  AvgDialog_145519_Content_2 = {
    Text = "Các bạn lảng vảng bên hồ băng. Mặt hồ phẳng lặng như gương, sạch bóng tinh khôi, bốn phía trống trải nhìn thấu, không có bóng dáng tinkerer đâu cả."
  },
  AvgDialog_145519_Content_20 = {
    Text = "So với một chiếc gương trông có vẻ tầm thường, sự biến mất của tinkerer rõ ràng đáng được quan tâm hơn."
  },
  AvgDialog_145519_Content_21 = {
    Text = "Nhưng không ai nhắc đến chuyện đó nữa. Chỉ có bóng u ám của nó vẫn không thể tránh khỏi, nặng nề đè lên lòng mỗi người."
  },
  AvgDialog_145519_Content_3 = {
    Text = "Trong tiếng gió Vang vọng giữa núi tuyết, Dường như xen lẫn tiếng hát và tiếng khóc thút thít của tinkerer — thoảng ẩn thoảng hiện, không phân biệt được là tiếng gió hay ảo giác."
  },
  AvgDialog_145519_Content_4 = {
    Text = "tinkerer… có phải sẽ không trở về nữa rồi?"
