  AvgDialog_145519_Content_5 = {
    Text = "Không ai phản bác."
  },
  AvgDialog_145519_Content_6 = {
    Text = "Lạ thật, hôm qua có thứ này không nhỉ?"
  },
  AvgDialog_145519_Content_7 = {
    Text = "Trên mặt hồ băng, trong lớp băng trong suốt, một chiếc gương tròn trịa đang nằm yên lặng bị phong kín."
  },
  AvgDialog_145519_Content_8 = {
    Text = "<Shake:Gương Bát Xích, đây chính là Gương Bát Xích cần dâng lên cho Nữ Thần Tuyết Sơn!>"
  },
  AvgDialog_145519_Content_9 = {
    Text = "William, trông bạn có vẻ như muốn nói điều gì đó mà lại thôi."
  },
  AvgDialog_145520_Content_1 = {
    Text = "Hành Khách Thứ Bảy"
  },
  AvgDialog_145520_Content_10 = {
    Text = "Mấy ngày nay không có đoàn leo núi nào khác, mọi người có thể nghỉ ngơi thoải mái ở đây, sẽ không có ai đến quấy rầy——"
  },
  AvgDialog_145520_Content_100 = {
    Text = "Cẩn thận! Có gì đó nổi lên rồi!"
