  },
  AvgDialog_145520_Content_14 = {
    Text = "Chúng tôi là đoàn leo núi, đến đây tránh gió tuyết, không có ác ý gì đâu."
  },
  AvgDialog_145520_Content_15 = {
    Text = "Bạn phát ra tín hiệu thân thiện, xách đèn đi về phía sau tảng đá."
