  AvgDialog_145520_Content_17 = {
    Text = "Bóng người sau tảng đá bỗng căng cứng lại. Chưa kịp để mọi người giải thích, một đợt tấn công mãnh liệt đã ập đến từ bóng tối."
  },
  AvgDialog_145520_Content_19 = {
    Text = "Có lẽ vì phải một chọi nhiều, kẻ đến phát động một đợt Phục kích rồi thoắt cái lại ẩn vào bóng tối. Nhưng trong khoảnh khắc giao chiến ngắn ngủi đó, bạn vẫn nhận ra được bóng dáng kia."
  },
  AvgDialog_145520_Content_2 = {
    Text = "Sau khi Naraka dẫn đường cho các bạn một lúc, một khe hở màu đen lộ ra giữa những đỉnh núi."
  },
  AvgDialog_145520_Content_20 = {
    Text = "<Shake:Cas-tơ-lơ?!>"
  },
  AvgDialog_145520_Content_21 = {
    Text = "Một lúc sau, từ trong bóng tối chui ra một chiếc áo choàng đen, phía sau áo choàng, một nửa Khuôn Mặt đầy vẻ cảnh giác ló ra."
