  AvgDialog_145520_Content_26 = {
    Text = "……………"
  },
  AvgDialog_145520_Content_27 = {
    Text = "Ừm, tôi và em trai mình — Pollux đã hẹn nhau trốn khỏi Giáo Hội Đèn Lồng theo những cách khác nhau, lần lượt từng người. Nhưng tôi đã chờ ở điểm hẹn suốt một tháng mà anh ấy vẫn không xuất hiện."
  },
  AvgDialog_145520_Content_28 = {
    Text = "Tôi nghĩ, chắc chắn là vì việc tôi rời đi đã khiến bà Yu Li-ét tăng cường canh gác. Từ đó đến nay, tôi vẫn luôn tìm cách giải cứu anh ấy."
  },
  AvgDialog_145520_Content_29 = {
