  AvgDialog_145520_Content_3 = {Text = "Vào đi."},
  AvgDialog_145520_Content_30 = {
    Text = "Cuối cùng, tôi nghe nói rằng trên đỉnh núi tuyết có một vị Thần Minh có thể thực hiện mọi điều ước."
