  AvgDialog_145520_Content_33 = {Text = "Ơ… ?"},
  AvgDialog_145520_Content_34 = {
    Text = "Chưa thấy ai không có não như anh."
  },
  AvgDialog_145520_Content_35 = {
    Text = "Dù cậu có một mình leo lên núi, cậu định đi đâu để tìm đủ bảy pháp khí?"
  },
  AvgDialog_145520_Content_37 = {
    Text = "Hình như tôi chưa nghĩ đến điều đó…"
  },
  AvgDialog_145520_Content_38 = {
    Text = "Đúng rồi! Vậy thì bây giờ, cậu cần đến sự giúp đỡ của Nữ Thần Tuyết Sơn rồi đó."
  },
  AvgDialog_145520_Content_39 = {
    Text = "Nào, Chỉ cần quy y dưới Giáo Phái Tiên Nữ, ta đảm bảo sau khi chinh phục đỉnh núi thành công, sẽ giúp cậu giải quyết nỗi khổ Phân li giữa cậu và em trai!"
  },
  AvgDialog_145520_Content_4 = {
