  AvgDialog_145520_Content_42 = {
    Text = "Nhưng để thể hiện thành ý của cậu với Giáo Phái Tiên Nữ, tất cả bảo vật mang theo người của cậu phải nộp lên để Tiên Nữ bảo quản hộ."
