  AvgDialog_145520_Content_44 = {
    Text = "Cas-tơ-lơ ấp úng mãi, rồi móc ra vài đồng xu và một cuốn Sách Cổ Tích đã cũ nát vì lật nhiều."
  },
  AvgDialog_145520_Content_45 = {
    Text = "Tôi chỉ có vậy thôi. Có thể cho tôi gia nhập không?"
