  AvgDialog_145520_Content_47 = {
    Text = "Xem đủ chưa?"
  },
  AvgDialog_145520_Content_48 = {
    Text = "Khụ, này, Cas-tơ-lơ, chào mừng cậu gia nhập đội thám hiểm của chúng tôi."
  },
  AvgDialog_145520_Content_49 = {
    Text = "Caraboo chỉ đang trêu cậu thôi, Chỉ cần cậu tự chuẩn bị vật tư, không cần phải nộp thêm bất cứ thứ gì."
  },
  AvgDialog_145520_Content_5 = {
    Text = "Khe nứt dài và phẳng, tựa như một đôi mắt hé mở, che chắn gió tuyết bên ngoài."
