  AvgDialog_145520_Content_50 = {
    Text = "Hừ, nữ thần tuyết sơn cũng chẳng thèm nhận cái thứ cúng bái tầm thường này của ngươi, tốt hơn hết hãy tự cất đi đi."
  },
  AvgDialog_145520_Content_51 = {
    Text = "Cas-tơ-lơ nâng niu vuốt phẳng những nếp nhăn trên cuốn Sách Cổ Tích, rồi cẩn thận cất vào lòng."
  },
  AvgDialog_145520_Content_52 = {
    Text = "Sau đó anh liếc nhìn mấy đồng xu, ánh mắt lướt qua từng người trong số các bạn."
