  AvgDialog_145520_Content_83 = {
    Text = "Có vẻ như, tối nay chúng ta phải qua đêm trong hang động rồi."
  },
  AvgDialog_145520_Content_84 = {
    Text = "Naraka gạt đi những tàn tích đã ẩm ướt ở khoảng trống trung tâm hang động, cố gắng dùng củi khô để nhóm lên đống lửa trại mới."
  },
  AvgDialog_145520_Content_85 = {
    Text = "Sâu trong hang động hơn, từ trong tối vang lên một tiếng động vụn vặt nào đó, như thể có gì đó đang dùng móng tay cào vào vách đá."
