  },
  AvgDialog_145520_Content_90 = {
    Text = "Naraka giơ đuốc lên, soi theo tiếng động vào Sâu trong hang động. Ánh lửa chỉ tiến được vài bước thì bị bóng tối phía trước nuốt chửng."
  },
  AvgDialog_145520_Content_91 = {
    Text = "Đừng đi vào đó."
  },
  AvgDialog_145520_Content_92 = {
    Text = "Tôi chỉ nhìn một cái thôi."
  },
  AvgDialog_145520_Content_93 = {
    Text = "Naraka tựa vào vách đá, cẩn thận nghiêng người ra ngoài."
  },
  AvgDialog_145520_Content_94 = {
    Text = "Ánh lửa bập bùng vượt qua mép đá dưới chân, soi rõ một vũng nước tối đen phía dưới. Mặt nước phẳng lặng không một gợn sóng, hầu như hòa làm một với bóng tối xung quanh."
  },
  AvgDialog_145520_Content_95 = {
    Text = "Phía Dưới có nước. <Shake:Có vẻ rất sâu——>"
  },
  AvgDialog_145520_Content_96 = {
    Text = "Lời chưa dứt, \"mặt nước\" đen kịt kia bỗng nhiên sụp xuống."
  },
  AvgDialog_145520_Content_97 = {
    Text = "Naraka nghiêng người, nửa bàn chân đã bước vào khoảng trống đột ngột mở rộng."
  },
  AvgDialog_145520_Content_98 = {
    Text = "<Shake:Bắt lấy tôi——!>"
  },
  AvgDialog_145520_Content_99 = {
    Text = "Bạn vội vàng túm lấy cổ áo anh, kéo mạnh anh ngã về phía sau."
  },
  AvgDialog_145521_Content_1 = {
    Text = "Chuyện Trò Bên Lò Sưởi"
  },
  AvgDialog_145521_Content_10 = {
    Text = "Góc hang chất mấy chiếc hòm gỗ đã mốc, trên vách đá sâu hơn bên trong, có một đoạn xích sắt gãy được đóng vào."
  },
  AvgDialog_145521_Content_100 = {
    Text = "Anh nhắm Mắt lại, cảm nhận đường nét lướt qua đầu ngón tay."
  },
  AvgDialog_145521_Content_101 = {
    Text = "<Small:……\"Kẻ xấu đã dùng phép thuật, biến em trai thành một con quạ.\">"
  },
  AvgDialog_145521_Content_102 = {
    Text = "<Small:……\"Nhưng người anh nhận ra màu sắc đôi cánh của em.\">"
  },
  AvgDialog_145521_Content_103 = {
    Text = "Ngọn lửa nhảy lên một cái, rồi lại tắt dần."
  },
  AvgDialog_145521_Content_104 = {
    Text = "Tôi có thể đưa bạn trở về không?"
  },
  AvgDialog_145521_Content_105 = {
    Text = "Lần sau khi gặp lại, bạn còn nhận ra tôi không?"
  },
  AvgDialog_145521_Content_107 = {
    Text = "Rất lâu sau, anh ấy gấp sách lại, đứng dậy, lặng lẽ bước đến cửa hang, cúi người dọn sạch khe thông gió bị tuyết đêm lấp đầy."
  },
  AvgDialog_145521_Content_108 = {
    Text = "Tuyết rơi qua kẽ ngón tay anh, rơi xuống đống tuyết nhỏ đã tích lại, không một tiếng động."
  },
  AvgDialog_145521_Content_109 = {
    Text = "Trời chưa sáng."
  },
  AvgDialog_145521_Content_11 = {
    Text = "Trước đây có người từng ở đây sao?"
  },
  AvgDialog_145521_Content_110 = {
    Text = "Bạn được đánh thức bởi ánh sáng yếu ớt lọt qua cửa hang."
  },
  AvgDialog_145521_Content_111 = {
    Text = "Cas-tơ-lơ đã thu dọn Hành Lý xong, đứng ở cửa hang chờ bạn thức dậy."
  },
  AvgDialog_145521_Content_112 = {
    Text = "Xin lỗi, tôi chuẩn bị rời đi rồi."
  },
  AvgDialog_145521_Content_113 = {
    Text = "Mong muốn của tôi khác với của các bạn."
  },
  AvgDialog_145521_Content_114 = {
    Text = "Tôi muốn tìm lại em trai mình, và tôi có thể tự tay làm được điều đó."
  },
  AvgDialog_145521_Content_115 = {
    Text = "Nhưng con đường này quá nguy hiểm, một mình bạn——"
  },
  AvgDialog_145521_Content_116 = {
    Text = "…Còn một điều nữa, tôi vốn do dự không biết có nên nói với các bạn không. Nhưng, bây giờ là lúc thành thật——"
  },
  AvgDialog_145521_Content_117 = {
    Text = "Cas-tơ-lơ hít một hơi thật sâu, như thể đã đưa ra một quyết định rất lớn."
  },
  AvgDialog_145521_Content_118 = {
    Text = "Lần đầu gặp mặt, tinkerer nói rằng, dù không được lòng người như Pollux, nhưng tôi cũng có ưu điểm của mình, tôi có thể một mình thoát khỏi sự truy đuổi của Giáo Hội Đèn Lồng."
  },
  AvgDialog_145521_Content_119 = {
    Text = "Nhưng đó là giả dối. Là để lừa các bạn."
  },
  AvgDialog_145521_Content_12 = {
    Text = "Điểm trú ẩn của đội leo núi cũ, bỏ hoang nhiều năm rồi. Chỗ đốt lửa trại ở đằng kia, tôi đi dọn một chút."
  },
  AvgDialog_145521_Content_120 = {
    Text = "Tôi yếu đuối hơn những gì các bạn biết, tôi đã không làm được."
  },
  AvgDialog_145521_Content_121 = {
    Text = "Các tín đồ vẫn đang bám sát phía sau tôi. Nếu tiếp tục ở lại, tôi sẽ kéo lùi tất cả các bạn."
  },
  AvgDialog_145521_Content_122 = {
    Text = "Anh ngẩng đầu lên, nhìn về phía sâu hơn bên trong hang động, nơi những người khác vẫn đang ngủ say."
  },
  AvgDialog_145521_Content_123 = {
    Text = "Ký hiệu bị hư hỏng trong hang động đó, tôi đã nhận ra rồi, đó là ký hiệu của Giáo Hội Đèn Lồng."
  },
  AvgDialog_145521_Content_124 = {
    Text = "Đây là căn cứ tạm thời của họ."
  },
  AvgDialog_145521_Content_125 = {
    Text = "Càng lên cao càng trống trải, sớm muộn gì tôi cũng sẽ bị họ phát hiện. Chi bằng rời đi sớm, trốn vào đám đông, sẽ dễ tránh khỏi sự truy bắt của họ hơn."
  },
  AvgDialog_145521_Content_126 = {
    Text = "Anh ta quay người bước vào trong gió tuyết."
  },
  AvgDialog_145521_Content_127 = {
    Text = "Bạn đứng yên nhìn mãi, cho đến khi bóng dáng anh ta hoàn toàn biến mất."
  },
  AvgDialog_145521_Content_128 = {
    Text = "Từ phía sau vang lên tiếng bước chân khẽ khàng."
  },
  AvgDialog_145521_Content_129 = {
    Text = "Caraboo không biết từ lúc nào cũng đã thức dậy, tựa vào miệng hang, nhìn về hướng Cas-tơ-lơ rời đi."
  },
  AvgDialog_145521_Content_13 = {
    Text = "Anh thành thạo bước đến một tảng đá bị khói hun đen ở trung tâm hang, ngồi xổm xuống, Bắt đầu gạt lớp Bụi than cũ ra."
  },
  AvgDialog_145521_Content_130 = {
    Text = "……Đồ ngốc."
  },
  AvgDialog_145521_Content_131 = {
    Text = "Trong giọng nói của cô ấy, không còn những Mũi nhọn như thường ngày nữa."
  },
  AvgDialog_145521_Content_132 = {
    Text = "Đội leo núi từ năm người, giảm xuống còn bốn người."
  },
  AvgDialog_145521_Content_14 = {
    Text = "Ánh Mắt của Cas-tơ-lơ dừng lại một lúc trên những hình khắc trên vách. Anh không nói gì, Chỉ là thu lại Ánh Mắt."
  },
  AvgDialog_145521_Content_15 = {
    Text = "Chưa kịp hỏi, tất cả mọi người đều bị tiếng Gọi của Caraboo thu hút Ánh Mắt."
  },
  AvgDialog_145521_Content_16 = {
    Text = "<Big:Hang núi ấm áp! Lửa trại! nghỉ ngơi dài! >"
  },
  AvgDialog_145521_Content_17 = {
    Text = "Caraboo Hưng phấn vô cùng."
  },
  AvgDialog_145521_Content_18 = {
    Text = "Dù tất cả mọi người đều đang cố gắng gượng tinh thần, nhưng bạn có thể thấy ai nấy đều kiệt sức vì trận chiến với Wendigo."
  },
  AvgDialog_145521_Content_19 = {
    Text = "Một hang động vừa vặn. Một khoảnh khắc nghỉ ngơi vừa vặn."
  },
  AvgDialog_145521_Content_2 = {
    Text = "Tuyết gió chưa ngừng. Các bạn men theo những kẽ nứt của băng tìm kiếm nơi trú ẩn, cuối cùng tìm được một hang tuyết khuất gió dưới chân vách đá."
  },
  AvgDialog_145521_Content_20 = {
    Text = "Dù phía trước có ẩn chứa nguy hiểm gì, cũng không thể ngăn các bạn tận hưởng một chút thư thái lúc này."
  },
  AvgDialog_145521_Content_21 = {
    Text = "Lửa được nhóm ở phía trong gần cửa hang. Khói bị gió xiên đưa ra ngoài hang."
  },
  AvgDialog_145521_Content_22 = {
    Text = "Evelyn lấy từ ba lô ra một tấm đệm chống ẩm, trước tiên nén một lớp tuyết mỏng xuống đất, rồi mới trải tấm đệm lên."
  },
  AvgDialog_145521_Content_23 = {
    Text = "Mọi người cởi những chiếc áo khoác đã đóng cứng vì lạnh, quây quần bên đống lửa, chìa tay ra gần ngọn lửa nhất có thể."
  },
  AvgDialog_145521_Content_24 = {
    Text = "Giá mà trên núi lúc nào cũng ấm áp như thế này thì tốt biết mấy."
  },
  AvgDialog_145521_Content_25 = {Text = "Phì."},
  AvgDialog_145521_Content_26 = {
    Text = "Cười gì vậy?"
  },
  AvgDialog_145521_Content_27 = {
    Text = "Cười anh ngốc không biết ăn nói cẩn thận. Lỡ Nữ Thần Tuyết Sơn coi đó là điều ước thật sự của anh rồi thực hiện cho anh thì sao?"
  },
  AvgDialog_145521_Content_28 = {
    Text = "Vậy cũng được thôi. Như vậy thì những người leo núi sẽ an toàn hơn nhiều."
  },
  AvgDialog_145521_Content_29 = {
    Text = "Ánh lửa trại phản chiếu trong đôi mắt nghiêm túc của Cas-tơ-lơ."
  },
  AvgDialog_145521_Content_3 = {
    Text = "Cửa hang hẹp, nhưng bên trong lại rộng rãi đến bất ngờ."
  },
  AvgDialog_145521_Content_30 = {
    Text = "Thôi, trêu anh ngốc này chán lắm."
  },
  AvgDialog_145521_Content_31 = {
    Text = "Caraboo, bạn có điều ước gì không?"
  },
  AvgDialog_145521_Content_32 = {
    Text = "Caraboo có vẻ không ngờ lại bị hỏi đột ngột như vậy, sau một thoáng ngẩn người, đôi mắt lại liếc qua liếc lại."
  },
  AvgDialog_145521_Content_33 = {
    Text = "Ta là Nữ Thần Tuyết Sơn, là người chịu trách nhiệm thực hiện điều ước của các ngươi mà!"
  },
  AvgDialog_145521_Content_34 = {
    Text = "Nếu phải nói có điều ước gì, thì đó là lấy lại quyền năng của ta."
  },
  AvgDialog_145521_Content_35 = {
    Text = "Ừ! Đúng vậy! Sau khi lấy lại quyền năng, ta sẽ chấn chỉnh lại Giáo Phái Tiên Nữ! Để cả đại lục đều đến cúng bái Nữ Thần Tuyết Sơn!"
  },
  AvgDialog_145521_Content_36 = {
    Text = "Evelyn khẽ cười một cái. Ánh lửa lay động trong đôi mắt sâu thẳm như vực nước của cô."
  },
  AvgDialog_145521_Content_37 = {
    Text = "Còn những người khác đâu?"
  },
  AvgDialog_145521_Content_38 = {
    Text = "Cô ấy quay sang bạn, ánh mắt không có vẻ dò hỏi, chỉ là sự quan tâm Trò chuyện thường ngày."
  },
  AvgDialog_145521_Content_39 = {
    Text = "Tôi cũng rất tò mò! Tôi sẽ thực hiện điều ước gì cho {Male=恩公,Female=恩人} đây nhỉ?"
  },
  AvgDialog_145521_Content_4 = {
    Text = "Mọi người chưa vào vội."
  },
  AvgDialog_145521_Content_40 = {
    Text = "Có người đã chỉ cho tôi một con Đường trở về Nhà, để quay về, tôi cần tìm một người."
  },
  AvgDialog_145521_Content_41 = {
    Text = "Bạn cũng ngốc thật. Sao không ước ngay để quay về cho xong?"
  },
  AvgDialog_145521_Content_42 = {
    Text = "Đã có người viết Lời tiên tri cho tôi."
  },
  AvgDialog_145521_Content_43 = {
    Text = "<Yellow:Số phận là những sợi chỉ kinh vĩ đan xen nhau, kẻ nào mưu toan bỏ qua bất kỳ một mắt nối nào để thẳng tiến đến đích, ắt sẽ phải chịu đựng nỗi đau của sợi chỉ đứt lìa.>"
  },
  AvgDialog_145521_Content_44 = {
    Text = "Hiểu rồi. Vậy còn vị William này bên cạnh bạn thì sao?"
  },
  AvgDialog_145521_Content_45 = {
    Text = "Câu chuyện của William, nói ra thì có phần phức tạp."
  },
  AvgDialog_145521_Content_46 = {
    Text = "Ít nhất là lúc này, đối với tôi, điều quan trọng nhất chính là đồng hành cùng %player% trở về Misaque, trở về bên cạnh Ramona."
  },
  AvgDialog_145521_Content_47 = {
    Text = "Bạn nhìn William với vẻ kinh ngạc. Anh ấy mặt mày bình thản, bạn không tìm thấy bất kỳ dấu hiệu nói dối nào trong những biểu cảm nhỏ trên khuôn mặt anh."
  },
  AvgDialog_145521_Content_48 = {
    Text = "Đừng nhìn chằm chằm vào tôi như vậy."
  },
  AvgDialog_145521_Content_49 = {
    Text = "<Yellow:Sứ mệnh khác của tôi trong thế giới này, đã tạm thời kết thúc rồi.>"
  },
  AvgDialog_145521_Content_5 = {
    Text = "Anh giơ cuốc chim lên, gõ từng tấc dọc theo phần trần phía trong cửa hang."
  },
  AvgDialog_145521_Content_50 = {
    Text = "Khi nói câu đó, William cố ý đưa tay gạt mái tóc che mắt sang một bên, che đi phần lớn biểu cảm trên khuôn mặt."
  },
  AvgDialog_145521_Content_51 = {
    Text = "Còn bạn thì sao, đồ ngốc?"
  },
  AvgDialog_145521_Content_52 = {Text = "Tôi?"},
  AvgDialog_145521_Content_53 = {
    Text = "Cas-tơ-lơ đờ đẫn nhìn vào đống lửa trại."
  },
  AvgDialog_145521_Content_54 = {
    Text = "Tôi muốn Pollux… trở về."
  },
  AvgDialog_145521_Content_55 = {
    Text = "Caraboo ngước mắt nhìn Cas-tơ-lơ, ánh mắt bỡn cợt thường ngày trong đó chợt biến mất trong thoáng chốc."
  },
  AvgDialog_145521_Content_56 = {
    Text = "Bạn vừa nói rằng, bạn muốn anh ấy trở về."
  },
  AvgDialog_145521_Content_57 = {
    Text = "Nhưng khi lần đầu gặp chúng tôi, bạn nói bạn muốn cứu anh ấy ra."
  },
  AvgDialog_145521_Content_58 = {
    Text = "Hai cách diễn đạt này có sự khác biệt tinh tế… nhưng cũng chưa chắc không thể dung hòa được."
  },
  AvgDialog_145521_Content_59 = {
    Text = "Cas-tơ-lơ, em trai của bạn, có thực sự bị cái vị giáo chủ nào đó giam cầm không?"
  },
  AvgDialog_145521_Content_6 = {
    Text = "Chỗ này bị Thông rồi, khi dựng trại tránh ra khỏi ngay bên dưới."
  },
  AvgDialog_145521_Content_60 = {
    Text = "Im Lặng ngắn ngủi. Caraboo cầm Táo lên cắn thêm một miếng, như thể chẳng có chuyện gì xảy ra và chuyển sang chủ đề khác."
  },
  AvgDialog_145521_Content_61 = {
    Text = "Thật ra thì, muốn thực hiện ước nguyện rất đơn giản thôi."
  },
  AvgDialog_145521_Content_62 = {
    Text = "Bạn thấy đấy, trong bảy bảo vật kia chẳng phải còn có một cái lông vũ gì đó không? Biết đâu chiếc lông vũ trên người bạn chính là <Yellow:Lông Vũ Ma'at> thì sao."
  },
  AvgDialog_145521_Content_63 = {
    Text = "Ma'at, nữ thần của sự thật, trật tự và công lý, trên đầu đội một chiếc lông đà điểu."
  },
  AvgDialog_145521_Content_64 = {
    Text = "Khi xét xử vong linh, Anubis sẽ đặt trái tim của vong linh lên cùng chiếc lông vũ này trên một chiếc cân. Nếu tim nặng hơn lông vũ, sẽ bị quái vật Ammit nuốt chửng; nếu tim nhẹ bằng lông vũ, sẽ được vào Cánh Đồng Lau."
  },
  AvgDialog_145521_Content_65 = {
    Text = "Chiếc lông vũ là toàn bộ định nghĩa của nền văn minh này về \"vô tội\"."
  },
  AvgDialog_145521_Content_66 = {
    Text = "Lông vũ vô tội… thật mỉa mai."
  },
  AvgDialog_145521_Content_67 = {
    Text = "Cas-tơ-lơ nở một nụ cười có phần bất lực."
  },
  AvgDialog_145521_Content_68 = {
    Text = "Đôi cánh này, là do giáo chủ Giáo Hội Đèn Lồng, Yu Li-ét, cấy ghép vào tôi và em trai để tạo ra Thần Minh của cô ấy."
  },
  AvgDialog_145521_Content_69 = {
    Text = "Trong lời kể của anh ấy, bạn nghe thấy một giọng nói. Giọng nói của nỗi đau không thể kìm nén."
  },
  AvgDialog_145521_Content_7 = {
    Text = "Anh khom lưng đi vào sâu hơn trong hang, ngồi xổm áp sát mặt đất lắng nghe một lúc, rồi lại dùng mu bàn tay thử độ ẩm của vách đá."
  },
  AvgDialog_145521_Content_70 = {
    Text = "Sau đó, cô ấy lại nhổ đi đôi cánh của Pollux. Giờ đây, chỉ còn mình tôi vẫn còn mang đôi cánh phỉ báng này."
  },
  AvgDialog_145521_Content_71 = {
    Text = "Cas-tơ-lơ nhẹ nhàng vuốt ve những chiếc lông vũ ở đầu cánh, bạn bỗng dưng cảm thấy như trên đó đầy vết máu."
  },
  AvgDialog_145521_Content_72 = {
    Text = "Vì vậy, nói đến vô tội… đôi cánh này có lẽ là thứ xa cách với vô tội nhất."
  },
  AvgDialog_145521_Content_73 = {
    Text = "Không khí lắng xuống, chỉ còn tiếng lửa trại thiêu đốt lách tách."
  },
  AvgDialog_145521_Content_74 = {
    Text = "Naraka, vậy còn ước nguyện của bạn thì sao?"
  },
  AvgDialog_145521_Content_75 = {
    Text = "William đột nhiên quay sang Naraka, người đang ngồi sưởi lửa bên cạnh và có vẻ không có ý định tham gia vào câu chuyện."
  },
  AvgDialog_145521_Content_76 = {
    Text = "Tôi chỉ là một người dẫn đường, không có ý định cùng các bạn đi cầu nguyện ước gì cả."
  },
  AvgDialog_145521_Content_77 = {
    Text = "Nếu nhất định phải nói đến <Yellow:ước nguyện của Naraka>, thì có lẽ anh ấy mong muốn tên của những người dẫn đường Sherpa cũng được ghi vào sử sách của những người chinh phục đỉnh núi."
  },
  AvgDialog_145521_Content_78 = {
    Text = "Nhưng loại ước nguyện đó mà phải nhờ đến thần tích để thực hiện thì thật vô vị, phải không?"
  },
  AvgDialog_145521_Content_79 = {
    Text = "Thông qua việc biên soạn và giả mạo sách vở, tạo ra Lời Nói Dối xuyên suốt Lịch sử, quá đơn giản, quá dễ dàng, dễ đến mức mất đi giá trị."
  },
  AvgDialog_145521_Content_8 = {
    Text = "Vào đi, Bên trong có vẻ an toàn rồi."
  },
  AvgDialog_145521_Content_80 = {
    Text = "Chuyện chinh phục đỉnh núi, vẫn phải dựa vào đôi chân của chính mình thôi."
  },
  AvgDialog_145521_Content_81 = {
    Text = "Dựa vào bản thân…"
  },
  AvgDialog_145521_Content_82 = {
    Text = "Cas-tơ-lơ dường như cảm nhận được điều gì đó."
  },
  AvgDialog_145521_Content_83 = {
    Text = "Ơ kìa — trông bạn chẳng giống người hay nói những lời chính đáng như vậy chút nào."
  },
  AvgDialog_145521_Content_84 = {
    Text = "Caraboo bịt mũi quạt tay, dường như ngửi thấy mùi gì đó hôi thối."
  },
  AvgDialog_145521_Content_85 = {
    Text = "Phần nói thật lòng đây, thôi đừng diễn nữa, nói chuyện thật tình đi nhé?"
  },
  AvgDialog_145521_Content_86 = {
    Text = "Cô ấy nhìn chằm chằm vào Đôi Mắt của Naraka với vẻ thích thú, Naraka Né tránh Ánh Mắt, cô ấy cúi người xuống, Ánh Mắt bám chặt không buông."
  },
  AvgDialog_145521_Content_87 = {
    Text = "<Shake:Nào, hãy để ta nhìn thấy bộ mặt thật của ngươi——>"
  },
  AvgDialog_145521_Content_88 = {
    Text = "Caraboo lao về phía trước, muốn chộp lấy Naraka như đại bàng vồ gà, nhưng Naraka Chỉ khẽ nghiêng người né qua."
  },
  AvgDialog_145521_Content_89 = {
    Text = "Thôi đừng làm loạn nữa, ngày mai còn phải lên Đường đấy. Ta không muốn các bạn không lên được đỉnh núi đâu."
  },
  AvgDialog_145521_Content_9 = {
    Text = "Trên vách đá còn sót lại những hoa văn đã phai màu, trông như đường nét của một loại ký hiệu nào đó, sơn đã bong tróc đến mức khó nhận ra."
  },
  AvgDialog_145521_Content_90 = {
    Text = "Caraboo vồ hụt, tiện thể ngồi phịch xuống Tuyết, nhe răng cười."
  },
  AvgDialog_145521_Content_91 = {
    Text = "Đã vậy thì bạn cũng muốn chúng ta lên được đỉnh, ta yên tâm rồi."
  },
  AvgDialog_145521_Content_93 = {
    Text = "Đống lửa cháy đến nửa đêm, chỉ còn lại những tia sáng đỏ lẻ loi, thoi thóp trong tàn tro."
  },
  AvgDialog_145521_Content_94 = {
    Text = "Naraka chia ca trực đêm, mỗi người hai tiếng.\nMọi người lần lượt chìm vào giấc ngủ. Từ trong túi ngủ vọng ra tiếng ngáy nhỏ nhẹ, khẽ khàng."
  },
  AvgDialog_145521_Content_95 = {
    Text = "Cas-tơ-lơ tự nhiên nhận ca đầu tiên. Anh tựa vào vách hang, từ sâu trong Hành Lý, lấy ra một cuốn sách nhỏ đã sờn góc trắng bạc."
  },
  AvgDialog_145521_Content_96 = {
    Text = "Đó là một cuốn Sách Cổ Tích."
  },
  AvgDialog_145521_Content_97 = {
    Text = "Đầu ngón tay anh lướt qua hai cái tên trên trang bìa."
  },
  AvgDialog_145521_Content_98 = {
    Text = "Nét chữ ngay ngắn của trẻ con là của chính anh, còn cái kia được tô nguệch ngoạc bằng bút sáp đỏ, màu sắc dần phai theo năm tháng mài mòn."
  },
  AvgDialog_145521_Content_99 = {Text = "Pollux…"},
  AvgDialog_145522_Content_1 = {
    Text = "Đừng Trả Lời"
  },
  AvgDialog_145522_Content_10 = {
    Text = "Cas-tơ-lơ đi ở cuối đoàn, anh lặng lẽ hơn thường ngày."
  },
  AvgDialog_145522_Content_11 = {
    Text = "Này, ngốc. Bạn có lạnh không?"
  },
  AvgDialog_145522_Content_12 = {
    Text = "Vẫn ổn."
  },
  AvgDialog_145522_Content_13 = {
    Text = "Tôi cũng vậy. Thật kỳ lạ."
  },
  AvgDialog_145522_Content_14 = {
    Text = "Vậy thì, tiếng thở nặng nề và thô như vậy, là từ ai vậy?"
  },
  AvgDialog_145522_Content_15 = {
    Text = "Đoàn người dừng lại. Tất cả đồng loạt quay đầu nhìn lại. Phía sau chỉ có những dấu chân sâu nông do chính họ để lại."
  },
  AvgDialog_145522_Content_16 = {
    Text = "Ở rìa những dấu chân, tuyết rất sạch. Sạch đến mức như thể đã bị thứ gì đó nhẹ nhàng xóa đi."
  },
  AvgDialog_145522_Content_17 = {
    Text = "Tĩnh lặng. Chỉ có gió. Gió thổi từ rất xa, vòng qua sườn núi, chui vào cổ áo của từng người."
  },
  AvgDialog_145522_Content_18 = {
    Text = "Trong gió mang theo một âm thanh hầu như không nghe rõ. Đó không phải tiếng hát. Đó là tiếng gọi."
  },
  AvgDialog_145522_Content_19 = {
    Text = "<Change>……E, ve, lyn……"
  },
  AvgDialog_145522_Content_2 = {
    Text = "Tuyết và gió đã nhỏ hơn, nhưng bầu trời lại trông tệ hơn cả lúc tuyết gió nổi lớn."
  },
  AvgDialog_145522_Content_20 = {Text = "?！"},
  AvgDialog_145522_Content_21 = {
    Text = "Cô ấy đột ngột quay người lại. Bãi tuyết trống trải, chẳng có gì cả. Nhưng âm thanh đó lại vang lên, lần này gần hơn, mang theo một sự dịu dàng gần như tàn nhẫn."
  },
  AvgDialog_145522_Content_22 = {
    Text = "<Change>……Evelyn……tôi lạnh……"
  },
  AvgDialog_145522_Content_23 = {
    Text = "Đây là…"
  },
  AvgDialog_145522_Content_24 = {
    Text = "<Shake:Không thể nào…>"
  },
  AvgDialog_145522_Content_25 = {
    Text = "Khuôn Mặt cô ấy lập tức mất đi sắc máu. Đôi môi cô tái nhợt, giọng run rẩy, như thể khoảnh khắc mà cô đã hơn một lần tưởng tượng cuối cùng đã đến."
  },
  AvgDialog_145522_Content_26 = {
    Text = "Các bạn… các bạn có nghe thấy không?!"
  },
  AvgDialog_145522_Content_27 = {
    Text = "Là anh ấy."
  },
  AvgDialog_145522_Content_28 = {
    Text = "<Shake:Là giọng của anh ấy……>"
  },
  AvgDialog_145522_Content_29 = {
    Text = "Thưa bà Evelyn, dù bà nghe thấy giọng của ai, xin đừng hồi đáp nó."
  },
  AvgDialog_145522_Content_3 = {
    Text = "Tầng mây xám chì nặng nề đè thấp xuống trên đỉnh núi, như một giấc mơ cũ nặng nề, không chịu tan đi."
  },
  AvgDialog_145522_Content_30 = {
    Text = "Các bạn nín thở. Gió bãi tuyết cuốn qua tai các bạn, rồi— \nCác bạn cũng đều nghe thấy."
  },
  AvgDialog_145522_Content_31 = {
    Text = "Gió biến thành vô số giọng nói, vô số lời Gọi tha thiết. Mỗi lời đều thổi đến từ một hướng mà bạn từng quen thuộc, rồi từng đánh mất."
  },
  AvgDialog_145522_Content_32 = {
    Text = "Giọng nói. Giọng nói đang Gọi bạn. Lạnh lẽo mà trong trẻo."
  },
  AvgDialog_145522_Content_33 = {
    Text = "<Change>Tôi đang chờ bạn, đối tác."
  },
  AvgDialog_145522_Content_34 = {
    Text = "<Change>Đừng bị bỏ lại phía sau, chúng ta sẽ cùng nhau đến điểm cuối của con đường này."
  },
  AvgDialog_145522_Content_35 = {Text = "Ramona..."},
  AvgDialog_145522_Content_36 = {
    Text = "Bạn nghiến răng, Khắc chế ham muốn đi tìm kiếm."
  },
  AvgDialog_145522_Content_37 = {
    Text = "Đôi chân bạn như bị đóng băng trong tuyết, không nghe lời bạn điều khiển. Bạn có thể cảm nhận một sức lực rất nhẹ, rất mềm mại, từ hướng giọng nói, chậm rãi, chậm rãi, kéo trọng tâm của bạn về phía trước."
  },
  AvgDialog_145522_Content_38 = {
    Text = "Đó là lời Mời. Lời Mời không thể từ chối."
  },
  AvgDialog_145522_Content_39 = {
    Text = "Chỉ cần bạn chịu bước thêm một bước về phía trước, bạn có thể quay lại bất kỳ khoảnh khắc ấm áp nào trong quá khứ——"
  },
  AvgDialog_145522_Content_4 = {
    Text = "Không ai nói chuyện. Những con chó hướng dẫn đi ở phía trước, ngay cả chúng cũng kìm lại tiếng rên rỉ quen thuộc trong cổ họng."
  },
  AvgDialog_145522_Content_40 = {
    Text = "Người giữ gìn——"
  },
  AvgDialog_145522_Content_41 = {
    Text = "Giọng của William vang đến từ nơi rất xa. Lúc này bạn mới Phát hiện mình đã không biết từ lúc nào đã bước ra nửa bước."
  },
  AvgDialog_145522_Content_42 = {
    Text = "Bên cạnh các bạn, vài con chó hướng dẫn đã bị cắn rách cổ họng, máu tươi phun ra nhuộm đỏ chói mấy mảng trên nền tuyết trắng xóa."
  },
  AvgDialog_145522_Content_43 = {
    Text = "Lùi lại đây."
  },
  AvgDialog_145522_Content_44 = {
    Text = "Đưa tay cho tôi."
  },
  AvgDialog_145522_Content_45 = {
    Text = "Sắc mặt William trắng bệch như tờ giấy, tay anh nắm lấy cánh tay bạn đang run rẩy không tự chủ."
  },
  AvgDialog_145522_Content_46 = {
    Text = "Bạn có thể cảm nhận anh đang cố gắng Khắc chế bản thân, Khắc chế không để bị giọng nói đó mê hoặc."
  },
  AvgDialog_145522_Content_47 = {
    Text = "Giọng nói đó là giả. Các bạn phải tỉnh lại."
  },
  AvgDialog_145522_Content_48 = {
    Text = "Anh nói bằng giọng rất khẽ, như thể đang tuyên bố một Phán quyết."
  },
  AvgDialog_145522_Content_49 = {
    Text = "<Shake:<Small:Ư… Dì Rosa…>>"
  },
  AvgDialog_145522_Content_5 = {
    Text = "Đi chậm thôi, địa hình không ổn lắm."
  },
  AvgDialog_145522_Content_50 = {
    Text = "Caraboo như vừa tỉnh mộng, vẫn còn lẩm bẩm điều gì đó."
  },
  AvgDialog_145522_Content_51 = {
    Text = "Nhưng không phải ai cũng có thể tỉnh lại được."
  },
  AvgDialog_145522_Content_52 = {
    Text = "Pollux…! Pollux…! Bạn ở đâu?!"
  },
  AvgDialog_145522_Content_53 = {
    Text = "<Shake:<Big:Pollux…!!!>>"
  },
  AvgDialog_145522_Content_54 = {
    Text = "<Italic:…Anh ơi, em lạnh…>"
  },
  AvgDialog_145522_Content_55 = {
    Text = "<Italic:Anh ơi, phòng cấm cố tối lắm, tối tăm lắm, đáng sợ lắm… em xin anh… cho em ra ngoài… thưa Giáo chủ…>"
  },
  AvgDialog_145522_Content_56 = {
    Text = "<Shake:<Italic:…Anh ơi, sao anh không đến tìm em…>>"
  },
  AvgDialog_145522_Content_57 = {
    Text = "Pollux!! Bạn đợi tôi, tôi đến ngay—"
  },
  AvgDialog_145522_Content_58 = {
    Text = "<Shake:Này, đồ ngốc, đứng lại!>"
  },
  AvgDialog_145522_Content_59 = {
    Text = "Không để ý đến tiếng gọi của các bạn, Cas-tơ-lơ lao ra ngoài."
  },
  AvgDialog_145522_Content_6 = {
    Text = "Đoạn này trước đây là dốc thẳng, giờ lại nứt ra những rãnh ngang."
  },
  AvgDialog_145522_Content_60 = {
    Text = "<Shake:Bắt lấy hắn!>"
  },
  AvgDialog_145522_Content_61 = {
    Text = "Đừng để thằng ngốc đó bị dụ đi mất!"
  },
  AvgDialog_145522_Content_7 = {
    Text = "Đây là vết nứt mới hình thành sau trận tuyết lở lần trước… không nên sâu đến vậy."
  },
  AvgDialog_145522_Content_8 = {
    Text = "Hình dạng của ngọn núi đang thay đổi."
  },
  AvgDialog_145522_Content_9 = {
    Text = "William không nói thêm gì nữa. Đôi mắt xanh biếc của anh nhìn về phía xa, đôi mày khẽ cau lại."
  },
  AvgDialog_145523_Content_1 = {
    Text = "Đỉnh Nhọn Vô Nguyện"
  },
  AvgDialog_145523_Content_10 = {
    Text = "William từ từ ngồi xuống, đầu ngón tay lướt qua những vết khắc phức tạp giữa các bệ đá — những thứ mà trước đây cậu chỉ coi là trang trí."
  },
  AvgDialog_145523_Content_100 = {
    Text = "<Shake:Dừng lại, hãy dừng nó lại! Cứ thế này, <Red:trước khi hoàn thành điều ước, ta sẽ chết mất!>>"
  },
  AvgDialog_145523_Content_101 = {
    Text = "Điều này không nằm trong giao ước của chúng ta."
  },
  AvgDialog_145523_Content_102 = {
    Text = "Đúng vậy, hắn chỉ hứa khởi động nghi lễ cho ngươi, chứ không hứa rằng ngươi sẽ còn sống sau khi nghi lễ kết thúc."
  },
  AvgDialog_145523_Content_103 = {
    Text = "Thì ra vậy, mỗi lời William học trưởng nói đều là thật… nhưng thủ pháp dựng ghép lại tạo ra một ảo tượng hoàn toàn."
  },
  AvgDialog_145523_Content_104 = {
    Text = "Vòng hào quang thứ sáu trỗi dậy."
  },
  AvgDialog_145523_Content_105 = {
    Text = "Cả ngọn núi rung chuyển như đang hấp hối. Vô số huyết nhục trắng bệch chui ra từ những tầng đá nứt vỡ, cuồn cuộn như sóng lớn đổ về phía tế đàn."
  },
  AvgDialog_145523_Content_106 = {
    Text = "Không! Đó là của ta! Huyết Nhục của ta! Sức mạnh của ta! Nguyện vọng của ta!"
  },
  AvgDialog_145523_Content_107 = {
    Text = "Hay có lẽ chúng chưa bao giờ thuộc về ngươi, chưa bao giờ là sức mạnh của ngươi. Đó là những điều ước mà vô số người hành hương đã dâng lên ngọn núi."
  },
  AvgDialog_145523_Content_108 = {
    Text = "Sức mạnh thuộc về tất cả những người đã bị ngươi lừa dối, nuốt chửng, chôn vùi nơi đây. Ngươi không có quyền chiếm đoạt chúng."
  },
  AvgDialog_145523_Content_109 = {
    Text = "Giờ đây, chúng chỉ đơn giản là trở về nơi chúng thuộc về."
  },
  AvgDialog_145523_Content_11 = {
    Text = "Không thể nào… sao lại thế này… những ký hiệu đặc biệt bên cạnh hoa văn bàn thờ này… ta nhận ra chúng."
  },
  AvgDialog_145523_Content_110 = {
    Text = "tinkerer, Cas-tơ-lơ, Evelyn, và cả Fingol mà ngươi chưa từng gặp…"
  },
  AvgDialog_145523_Content_111 = {
    Text = "Từng khuôn mặt, từng cái tên hiện lên trong tâm trí bạn, rồi lặn sâu vào ký ức."
  },
  AvgDialog_145523_Content_112 = {
    Text = "<BigShake:Đừng hòng! Đừng hòng!>"
  },
  AvgDialog_145523_Content_113 = {
    Text = "Trước khi sức mạnh bị rút cạn, <Big:<Red:ta sẽ phá hủy tế đàn trước, rồi nhai nát từng đứa một!>>"
  },
  AvgDialog_145523_Content_114 = {
    Text = "William gật đầu về phía ngươi."
  },
  AvgDialog_145523_Content_115 = {
    Text = "Mỗi người làm phần việc của mình, ta sẽ duy trì sự vận hành của nghi lễ."
  },
  AvgDialog_145523_Content_116 = {
    Text = "Nhiệm vụ ngăn chặn Ngài, hãy để ta đảm nhận!"
  },
  AvgDialog_145523_Content_12 = {
    Text = "Đây là tác phẩm của Fingol."
  },
  AvgDialog_145523_Content_13 = {Text = "Fingol?"},
  AvgDialog_145523_Content_14 = {
    Text = "Bạn biết cái tên đó. Người đồng hành của William, điều tra viên đã biến mất khỏi \"thế giới đó\" trước anh ấy."
  },
  AvgDialog_145523_Content_15 = {
    Text = "Thì ra là vậy, Chìa Khóa Solomon… lý do Con Sâu không thể khởi động nghi lễ… và mục đích Fingol đến với thế giới này…"
  },
  AvgDialog_145523_Content_16 = {
    Text = "Ha ha ha, thì ra là vậy, thú vị, thú vị, thật sự thú vị!"
  },
  AvgDialog_145523_Content_17 = {
    Text = "Vị thợ dệt vất vả đó sai ta dẫn các ngươi lên đỉnh, hóa ra là để cho ta xem trò vui này!"
  },
  AvgDialog_145523_Content_18 = {
    Text = "Ý nghĩa là gì?"
  },
  AvgDialog_145523_Content_19 = {
    Text = "N nhún vai."
  },
  AvgDialog_145523_Content_2 = {
    Text = "Đó là một tế đàn khổng lồ, Dường như cùng tuổi với cả dãy núi."
  },
  AvgDialog_145523_Content_20 = {
    Text = "Phiên dịch là hắn, không phải ta. Dù giao dịch của hắn cũng thả ta ra, nhưng ta trông có vẻ là người biết ơn đáp nghĩa không?"
  },
  AvgDialog_145523_Content_21 = {
    Text = "Để ta giải thích vậy."
  },
  AvgDialog_145523_Content_22 = {
    Text = "\"Chìa Khóa Solomon\" thực ra không phải là chìa khóa, mà là một cuốn ma điển."
  },
  AvgDialog_145523_Content_23 = {
    Text = "Và nội dung quan trọng nhất được ghi chép trong ma điển, là phương pháp triệu hồi bảy mươi hai trụ ma thần của Solomon. Nói cách khác, là phương pháp kết nối các thế giới."
  },
  AvgDialog_145523_Content_24 = {
    Text = "Anh ngẩng đầu lên, nhìn về phía trung tâm của bảy bệ đỡ kia — một lỗ khóa hẹp, hầu như hòa lẫn vào bóng tối."
  },
  AvgDialog_145523_Content_25 = {
    Text = "Những ký hiệu này là mật ngữ chỉ có anh và tôi mới đọc được."
  },
  AvgDialog_145523_Content_26 = {
    Text = "William nhận ra từng chữ, từng chữ một trong những vết khắc dưới đất, những con chữ vô thanh đó dần dần ghép lại thành một giọng nói quen thuộc trong tâm trí anh."
  },
  AvgDialog_145523_Content_27 = {
    Text = "Có phải William không? Ta biết cậu có thể đi đến đây. \n\nPháp trận được khắc tại đây bao gồm ba loại ngôn ngữ cổ xưa, ta đoán trong số chúng ta chỉ có cậu, người học trò chăm chỉ đó, mới có thể đọc thông suốt một lần.\nChúng là những chú ngữ triệu hồi và phong ấn. Cậu nên hiểu ý nghĩa của hai từ này."
  },
  AvgDialog_145523_Content_28 = {
    Text = "Sự mở ra và đóng lại của \"Cánh Cửa\"."
  },
  AvgDialog_145523_Content_29 = {
    Text = "Nói ngắn gọn, pháp trận này lấy \"Vương Miện\" làm매介, kết nối với điểm khởi nguyên của thế giới này. Vì vậy, chỉ giới hạn trong thế giới này, nó thực sự có thể thực hiện bất kỳ điều ước nào.\n\nCó phải ngươi từng tự hỏi tại sao mình lại đến thế giới xa lạ này không?\n\nBây giờ, ta có thể trả lời ngươi rồi.\n\nNgươi chính là điều ước đó."
  },
  AvgDialog_145523_Content_3 = {
    Text = "Những bậc đá hình vòng tròn xếp chồng lên nhau, cuối cùng là bảy bệ đá trống rỗng đứng sừng sững, xếp thành một vòng tròn. Giữa các bệ đá với nhau, trong những rãnh cổ xưa nào đó, đọng lại ánh sáng vàng sẫm đã khô cạn từ lâu."
  },
  AvgDialog_145523_Content_30 = {
    Text = "Chỉ tiếc rằng, sức mạnh ta bỏ ra vẫn chưa đủ nhiều, chỉ có thể miễn cưỡng mở ra một khe hở cho bạc tâm của ngươi.\n\nĐích đến mà ta không thể chạm tới, cần ngươi thay ta mà đến.\n\nDù sao, ngươi là điều tra viên huyền thoại William, phải không?"
  },
  AvgDialog_145523_Content_31 = {
    Text = "Không nói nhiều nữa, hy vọng ngươi đã thu hồi được chìa khóa bạc của ta.\n\nHãy dùng nó để kích hoạt pháp trận, rồi hãy cầu nguyện, Ngài sẽ dẫn ngươi đến vùng đất hứa.\n\nCon đường phía trước, hãy tự mình bước đi.\n\nChân thành của ngươi, Fingol."
  },
  AvgDialog_145523_Content_32 = {
    Text = "Ngón tay William dừng lại."
  },
  AvgDialog_145523_Content_33 = {
    Text = "Anh ấy im lặng rất lâu, rất lâu. Ngươi chưa bao giờ thấy anh ấy có biểu cảm như vậy."
  },
  AvgDialog_145523_Content_34 = {Text = "%player%."},
  AvgDialog_145523_Content_35 = {
    Text = "Tôi đây."
  },
  AvgDialog_145523_Content_36 = {
    Text = "Lúc đó bạn chẳng phải đã hỏi tôi, tại sao lại là người đầu tiên tỉnh dậy dưới tiếng Gọi của Wendigo sao?"
  },
  AvgDialog_145523_Content_37 = {
    Text = "Vì tôi là người duy nhất trong số chúng ta đã từng nhìn thấy hài cốt của ông ấy."
  },
  AvgDialog_145523_Content_38 = {
    Text = "Toàn thân ông ấy đã mục rữa, hoàn toàn không thể nhận ra danh tính. Nhưng tôi nhận ra nửa chiếc chìa khóa bạc trên người ông ấy."
  },
  AvgDialog_145523_Content_39 = {
    Text = "Mã số I-1021, con số thuộc về Fingol. Mỗi khi một con số biến mất khỏi hồ sơ, chúng tôi biết rằng lại có thêm một vị tiền bối bị thế giới lãng quên."
  },
  AvgDialog_145523_Content_4 = {
    Text = "Đây chính là điểm cuối mà con sâu của núi dùng ước nguyện làm mồi nhử, dẫn dụ vô số người leo núi tìm đến."
  },
  AvgDialog_145523_Content_40 = {
    Text = "Từ đó về sau, tôi luôn mang theo chiếc chìa khóa bạc này bên mình."
  },
  AvgDialog_145523_Content_41 = {
    Text = "Ông khép mắt lại. Khi mở ra, trong đôi mắt xanh biếc ấy, chỉ còn lại một thứ gì đó trầm tĩnh, không thể độnglắc."
  },
  AvgDialog_145523_Content_42 = {
    Text = "…Fingol, cảm ơn vì sự tin tưởng bạn đã dành cho tôi."
  },
  AvgDialog_145523_Content_43 = {
    Text = "Sâu của Núi, ta sẽ giải thích cho ngươi cách kích hoạt pháp trận."
  },
  AvgDialog_145523_Content_44 = {
    Text = "Dâng điều ước cho Người của Núi, sức mạnh mà họ sở hữu sẽ hóa thành nguồn năng lượng cho pháp trận, từ đó kết nối với \"điểm khởi nguyên\" của thế giới."
  },
  AvgDialog_145523_Content_45 = {
    Text = "\"Điểm khởi nguyên\" của thế giới?"
  },
  AvgDialog_145523_Content_46 = {
    Text = "Nếu phỏng đoán của ta không sai, thì đó chính là \"Hắc Nhật\" trên bầu trời."
  },
  AvgDialog_145523_Content_47 = {
    Text = "Sự tồn tại của Hắc Nhật rất giống với \"Hắc Trì\" của Misaque, bao hàm vạn vật, là tàn tích của tất cả những gì đã tiêu vong trong quá khứ và tương lai, trôi nổi trên làn sóng xói mòn."
  },
  AvgDialog_145523_Content_48 = {
    Text = "Quy mô của điều ước được thực hiện phụ thuộc vào việc người cầu nguyện muốn lấy ra bao nhiêu làn sóng từ \"Hắc Nhật\"."
  },
  AvgDialog_145523_Content_49 = {
    Text = "Nhóc con, giúp ta nhìn chằm chằm vào mắt tên này. Xác nhận hắn không nói dối."
  },
  AvgDialog_145523_Content_5 = {
    Text = "Chưa từng có ai có thể rời khỏi nơi này còn sống. Tất cả những người leo núi, họ đều nằm dưới chân chúng ta, trong lòng ngọn núi."
  },
  AvgDialog_145523_Content_50 = {
    Text = "Caraboo miễn cưỡng bước lên, ngước nhìn vào đôi mắt của William."
  },
  AvgDialog_145523_Content_51 = {Text = "<Shake:!!>"},
  AvgDialog_145523_Content_52 = {
    Text = "William nhắm mắt lại, nhẹ nhàng lắc đầu."
  },
  AvgDialog_145523_Content_53 = {
    Text = "Mỗi lời hắn nói đều là sự thật."
  },
  AvgDialog_145523_Content_54 = {
    Text = "<Shake:Đừng có lừa ta! Ngươi đã dao động rồi, đồ lừa đảo nhỏ bé!>"
  },
  AvgDialog_145523_Content_55 = {
    Text = "Lời ta nói thật hay giả, ngươi biết rõ hơn ta."
  },
  AvgDialog_145523_Content_56 = {
    Text = "Sâu của Núi phát ra một tiếng cười lạnh, tuyết tích theo đó rơi xuống."
  },
  AvgDialog_145523_Content_57 = {
    Text = "Hừ, trọng điểm bây giờ là nghi lễ. Đợi mọi chuyện kết thúc, ta sẽ trừng phạt ngươi, tên phản đồ."
  },
  AvgDialog_145523_Content_58 = {
    Text = "Hãy nói cho ta biết đi, Sâu của Núi, ngươi muốn thực hiện điều ước ở quy mô nào?"
  },
  AvgDialog_145523_Content_59 = {
    Text = "Hí hí hí, còn phải nói nữa sao? Tất nhiên là càng nhiều càng tốt, càng nhiều càng tốt! Ta muốn nuốt trọn cả thế giới này vào bụng, vô tận, không bao giờ cạn kiệt!"
  },
  AvgDialog_145523_Content_6 = {
    Text = "Thôi bớt nói nhảm đi. Bắt đầu giải mã pháp trận."
  },
  AvgDialog_145523_Content_60 = {
    Text = "Thật là đồ ngu tham lam, có lẽ học cách biết đủ sẽ tốt hơn đấy?"
  },
  AvgDialog_145523_Content_61 = {
    Text = "Kẻ hỗn độn như ngươi sao có thể hiểu được, nếu cứ theo khuôn phép, ta đã chẳng thể đi đến ngày hôm nay."
  },
  AvgDialog_145523_Content_62 = {
    Text = "Cái \"ngày hôm nay\" mà ngươi tự hào nói đến là chỉ việc nằm phục trên núi, làm một con sâu béo ục ịch hay sao?"
  },
  AvgDialog_145523_Content_63 = {
    Text = "Thôi vậy… thật chẳng có mấy kẻ chịu nghe lời khuyên tốt của N."
  },
  AvgDialog_145523_Content_64 = {
    Text = "Tôi hiểu rồi."
  },
  AvgDialog_145523_Content_65 = {
    Text = "William gật đầu."
  },
  AvgDialog_145523_Content_66 = {
    Text = "Để thực hiện điều ước ở quy mô lớn nhất, cần phải dâng lên toàn bộ tế phẩm."
  },
  AvgDialog_145523_Content_67 = {
    Text = "<BigShake:Cầm lấy đi!> Chúng tồn tại chính là vì khoảnh khắc này."
  },
  AvgDialog_145523_Content_68 = {
    Text = "%player%, đưa Lễ vật cho tôi."
  },
  AvgDialog_145523_Content_69 = {
    Text = "Bạn mở chiếc vali ra."
  },
  AvgDialog_145523_Content_7 = {
    Text = "Giọng nói của Con Sâu Núi vang lên từ dưới chân. Lần này, trong giọng nói của nó không còn chỉ có sự chế giễu, mà còn ẩn chứa một sự cấp bách bị kìm nén suốt bao năm dài."
  },
  AvgDialog_145523_Content_70 = {
    Text = "Táo Vàng, Gương Bát Xích, Lông Vũ Ma'at, Mắt Balor, Sợi Chỉ Nữ Thần Số Phận, Vương Miện Ariadne… và chính chiếc Chìa Khóa Bạc đó."
  },
  AvgDialog_145523_Content_71 = {
    Text = "Bảy tế phẩm lần lượt khớp vào bệ đỡ, trong những rãnh khắc cổ xưa, ánh sáng vàng đen lại chảy tràn, cuộn trào, nối thành một vòng tròn hoàn chỉnh."
  },
  AvgDialog_145523_Content_72 = {
    Text = "<Shake:Ha ha ha ha! Cuối cùng… cuối cùng!>"
  },
  AvgDialog_145523_Content_73 = {
    Text = "Núi sẽ thưởng thức bữa tiệc thịnh soạn của Ngài, Núi sẽ dốc hết bộ sưu tập của Ngài."
  },
  AvgDialog_145523_Content_74 = {
    Text = "Núi đã khao khát từ lâu."
  },
  AvgDialog_145523_Content_75 = {
    Text = "William cầm chiếc Chìa Khóa độc nhất vô nhị đó, đưa nó vào ổ khóa."
  },
  AvgDialog_145523_Content_76 = {
    Text = "Nhân danh Fingol —"
  },
  AvgDialog_145523_Content_77 = {
    Text = "<Red:Bắt đầu.>"
  },
  AvgDialog_145523_Content_78 = {Text = "Tách."},
  AvgDialog_145523_Content_79 = {
    Text = "Một tiếng động khẽ vang lên, bảy tế phẩm đồng thời bùng phát ánh hào quang chói lòa."
  },
  AvgDialog_145523_Content_8 = {
    Text = "Ánh mắt của tất cả mọi người đều hướng về những ký tự thần bí dày đặc trên bàn thờ."
  },
  AvgDialog_145523_Content_80 = {
    Text = "Vầng hào quang thứ nhất dâng lên từ phía trên tế đàn. Rồi đến vầng thứ hai, thứ ba. Những điều ước ngủ yên trong bảy pháp khí hòa vang cùng nhau, tựa như bảy dòng sông chảy về cùng một đại dương."
  },
  AvgDialog_145523_Content_81 = {
    Text = "Nếu Núi có đôi tay, chắc Ngài sẽ vươn những bàn tay khao khát lên phía vòng tròn trên cao kia."
  },
  AvgDialog_145523_Content_82 = {
    Text = "<Shake:Cuối cùng cũng đợi được ngày này!>"
  },
  AvgDialog_145523_Content_83 = {
    Text = "Rồi Ngài sẽ hạ xuống vòng tròn treo lơ lửng giữa trời, ôm chặt, thật chặt vào lòng, cho đến khi nó chìm vào thân thể phình to của Ngài, cho đến khi toàn bộ sức mạnh bị Ngài nuốt trọn."
  },
  AvgDialog_145523_Content_84 = {
    Text = "Ngươi ngơ ngác nhìn lên bầu trời cao. Khi Núi thực hiện điều ước, số phận của các ngươi sẽ ra sao? Hành trình của các ngươi có kết thúc ở đây không?"
  },
  AvgDialog_145523_Content_85 = {
    Text = "Trong khoảnh khắc đó, ngươi thấy tròng kính của William lóe sáng."
  },
  AvgDialog_145523_Content_86 = {
    Text = "Ngay sau đó, vầng hào quang thứ tư sáng lên."
  },
  AvgDialog_145523_Content_87 = {
    Text = "Cả ngọn núi dưới chân phát ra một tiếng rền trầm. Đó là sự rung chuyển như của sinh vật sống, không thuộc về đá. Từng tia sáng le lói rỉ ra từ dưới lớp đá nứt vỡ."
  },
  AvgDialog_145523_Content_88 = {
    Text = "<Shake:……Cái gì?>"
  },
  AvgDialog_145523_Content_89 = {
    Text = "<Shake:Tại sao, sức mạnh của ta… đang chảy mất?>"
  },
  AvgDialog_145523_Content_9 = {
    Text = "Khoan đã… những vân hoa này…"
  },
  AvgDialog_145523_Content_90 = {
    Text = "Đó là cái giá của nghi lễ mà ngươi khao khát."
  },
  AvgDialog_145523_Content_91 = {
    Text = "Sau khi trả giá, nó sẽ trở thành thứ gì?"
  },
  AvgDialog_145523_Content_92 = {
    Text = "Nghi lễ sẽ hút cạn \"toàn bộ\" sức mạnh của lễ vật, vì vậy ta đoán, nó sẽ trở lại hình dạng trước khi gặp ngươi, thậm chí còn yếu hơn."
  },
  AvgDialog_145523_Content_93 = {
    Text = "Yếu ớt như một con sâu nhỏ bé đang ngọ nguậy trong quả táo, chỉ cần bóp nhẹ là vỡ tan?"
  },
  AvgDialog_145523_Content_94 = {
    Text = "<BigShake:Ngươi đã lừa ta! Tên lừa đảo đê tiện!>"
  },
  AvgDialog_145523_Content_95 = {
    Text = "Ta đã hứa với ngươi sẽ khởi động nghi lễ theo quy cách cao nhất, còn ngươi cũng đã đồng ý dâng lên \"tất cả\" vật tế."
  },
  AvgDialog_145523_Content_96 = {
    Text = "Tất cả những gì ngươi đã nuốt vào bụng, sức mạnh của cả ngọn núi, đều sẽ được dâng lên tế đàn, dâng lên vị thần đã thiết lập pháp trận này."
  },
  AvgDialog_145523_Content_97 = {
    Text = "Vòng hào quang thứ năm trỗi dậy."
  },
  AvgDialog_145523_Content_98 = {
    Text = "Những tảng đá dưới chân bắt đầu nứt vỡ, bong tróc, để lộ ra lớp thịt máu bên dưới — ẩm ướt, tái nhợt, đang co rút dữ dội."
  },
  AvgDialog_145523_Content_99 = {
    Text = "Từng mảng tuyết dày ầm ầm trượt xuống, bầu trời bị một bóng tối khổng lồ nào đó, từng chút một nuốt chửng."
  },
  AvgDialog_145524_Content_1 = {
    Text = "Bạn… đừng lại gần!"
  },
  AvgDialog_145524_Content_10 = {
    Text = "<Change>Ngươi còn nhớ sứ mệnh của mình không?"
  },
  AvgDialog_145524_Content_11 = {
    Text = "<Small:Tiêu diệt đi, kẻ phản bội……>"
  },
  AvgDialog_145524_Content_12 = {
    Text = "Hỗn Mang trong mắt Pollux dần tan biến, thay vào đó là một sự trống rỗng, một sự trống rỗng chỉ có thể bị giọng trong đầu điều khiển."
  },
  AvgDialog_145524_Content_13 = {
    Text = "Ừ, đúng vậy, ta là kẻ phản bội. Ta là người đã phản bội ngươi, người đã bỏ trốn."
  },
  AvgDialog_145524_Content_14 = {
    Text = "Nhưng bây giờ, ta sẽ không rời đi nữa."
  },
  AvgDialog_145524_Content_15 = {
    Text = "<Shake:Kẻ phản bội, Cas-tơ-lơ……>"
  },
  AvgDialog_145524_Content_16 = {
    Text = "Anh mơ hồ, anh muốn chống lại điều gì đó, muốn nắm lấy điều gì đó, nhưng giọng nói trong đầu không ngừng giằng xé."
  },
  AvgDialog_145524_Content_17 = {
    Text = "Pollux, ngươi đã theo dõi chúng ta suốt thời gian qua, chắc ngươi cũng đã gặp Wendigo rồi."
  },
  AvgDialog_145524_Content_18 = {
    Text = "Trong ảo ảnh của Wendigo, ngươi đã nghe thấy gì?"
  },
  AvgDialog_145524_Content_19 = {
    Text = "Đồng tử của Pollux lập tức giãn ra, rồi dần dần mờ đi. Anh chìm vào suy tư như người đang Mơ Ngủ."
  },
  AvgDialog_145524_Content_2 = {
    Text = "Pollux trợn to Đôi Mắt. Hắn không hiểu được suy nghĩ của tên cuồng đồ đứng trước mặt."
  },
  AvgDialog_145524_Content_20 = {
    Text = "Ta nghe thấy… có người đang Gọi ta…"
  },
  AvgDialog_145524_Content_21 = {
    Text = "Người ấy nói, chúng ta có thể trở thành những hiệp sĩ phi thường."
  },
  AvgDialog_145524_Content_22 = {
    Text = "Chúng ta cưỡi ngựa, vượt qua núi non, vượt qua sông biển, chém giết rồng…"
  },
  AvgDialog_145524_Content_23 = {
    Text = "Rồi, rồi, vào cuối giấc mơ……"
  },
  AvgDialog_145524_Content_25 = {
    Text = "<BigShake:Không, không……!>"
  },
  AvgDialog_145524_Content_26 = {
    Text = "Rất đau khổ, Yu Li-ét, <Shake:Cứu tôi, cứu tôi……>"
  },
  AvgDialog_145524_Content_27 = {
    Text = "<Shake:Ta là……cao quý……duy nhất……Con Thánh……Cứu tôi……<Small:Ta không thể……>>"
  },
  AvgDialog_145524_Content_28 = {
    Text = "Không sao đâu……Bạn không cần phải nhớ lại."
  },
  AvgDialog_145524_Content_29 = {
    Text = "Những đau khổ không thể chịu đựng được, hãy để ta gánh chịu thay. Như hồi còn nhỏ vậy."
  },
  AvgDialog_145524_Content_3 = {
    Text = "Trên khuôn mặt Cas-tơ-lơ không có sự kính sợ đối với giáo lý, cũng không có nỗi sợ hãi trước thái độ thù địch."
  },
  AvgDialog_145524_Content_30 = {
    Text = "Dù sao, ta là anh trai mà."
  },
  AvgDialog_145524_Content_31 = {
    Text = "Cas-tơ-lơ ôm lấy Pollux, dùng giọng nói nhẹ nhàng như dỗ dành trẻ con để an ủi."
  },
  AvgDialog_145524_Content_32 = {
    Text = "Hơi thở của Pollux chậm dần lại, khuôn mặt tựa vào vai Cas-tơ-lơ, mí mắt từ từ sụp xuống."
  },
  AvgDialog_145524_Content_33 = {
    Text = "<Shake:Cas-tơ-lơ……>"
  },
  AvgDialog_145524_Content_34 = {
    Text = "Là ta, ta là, Cas-tơ-lơ……"
  },
  AvgDialog_145524_Content_35 = {
    Text = "<Shake:Cas-tơ-lơ, Cas-tơ-lơ……>"
  },
  AvgDialog_145524_Content_36 = {
    Text = "<Shake:<Small:……Anh trai?>>"
  },
  AvgDialog_145524_Content_37 = {
    Text = "Đôi mắt đờ đẫn bỗng chốc trở nên trong sáng, giọng nói của Pollux nhẹ đến mức hầu như bị gió thổi tan, nhưng vẫn chính xác lọt vào tai Cas-tơ-lơ."
  },
  AvgDialog_145524_Content_38 = {
    Text = "Tiếng gọi mà anh đã hình dung vô số lần trong tưởng tượng, cuối cùng lại vang lên bên tai anh."
  },
  AvgDialog_145524_Content_39 = {Text = "À——"},
  AvgDialog_145524_Content_4 = {
    Text = "Anh chỉ bước tới, vượt qua lưỡi dao đó, vượt qua tất cả những rào cản lẽ ra phải tồn tại nhưng đã không còn nữa."
  },
  AvgDialog_145524_Content_40 = {
    Text = "Anh muốn khóc, muốn hét lên, muốn gào thét."
  },
  AvgDialog_145524_Content_41 = {
    Text = "Dù lúc này xung quanh chỉ có bãi tuyết mênh mông vô tận, anh vẫn muốn vô nghĩa mà loan báo với cả thiên hạ rằng, em trai anh đã trở về."
  },
  AvgDialog_145524_Content_42 = {
    Text = "Nhưng anh chẳng nói ra điều gì, như thường lệ, như khi Pollux chế nhạo anh là khúc gỗ, khi Caraboo chế nhạo anh là kẻ ngốc."
  },
  AvgDialog_145524_Content_43 = {
    Text = "<Shake:Pollux……>"
  },
  AvgDialog_145524_Content_44 = {
    Text = "—Chính vào khoảnh khắc này, trên đỉnh núi tuyết—nơi cao hơn, cao đến mức không thấy đỉnh—"
  },
  AvgDialog_145524_Content_45 = {
    Text = "Một ánh mắt xét xử, đã đổ xuống."
  },
  AvgDialog_145524_Content_46 = {
    Text = "<Change>Phế phẩm."
  },
  AvgDialog_145524_Content_47 = {
    Text = "Cas-tơ-lơ vội vàng ôm chặt người em trai—"
  },
  AvgDialog_145524_Content_48 = {
    Text = "Nhưng điều đó vô ích. Ánh sáng bùng nở từ lồng ngực của Pollux."
  },
  AvgDialog_145524_Content_49 = {
    Text = "Ánh sáng xuyên thẳng qua lồng ngực hai người, xuyên qua tấm áo choàng cũ kỹ của Cas-tơ-lơ, xuyên qua đôi Cánh của Cas-tơ-lơ đang ôm trọn hai người—"
  },
  AvgDialog_145524_Content_5 = {
    Text = "Anh ôm chặt Pollux vào lòng."
  },
  AvgDialog_145524_Content_50 = {
    Text = "Tựa như xiềng xích trắng tinh, gắn chặt hai người lại với nhau, hứa hẹn từ nay về sau, mãi mãi không Phân li."
  },
  AvgDialog_145524_Content_51 = {
    Text = "Anh ơi… xin lỗi anh…"
  },
  AvgDialog_145524_Content_52 = {
    Text = "Để lại những lời cuối cùng, Pollux tựa đầu vào vai Cas-tơ-lơ, chìm vào giấc ngủ sâu."
  },
  AvgDialog_145524_Content_53 = {
    Text = "Như vậy… cũng tốt… chúng ta sẽ không bao giờ chia cắt nữa…"
  },
  AvgDialog_145524_Content_54 = {
    Text = "Đây cũng là… chút tư tâm của anh…"
  },
  AvgDialog_145524_Content_55 = {
    Text = "Anh nhìn lại một lần về phía cao hơn của ngọn núi, tưởng tượng hình ảnh những người bạn đồng hành trong đội leo núi năm xưa cùng nhau dìu đỡ mà tiến lên."
  },
  AvgDialog_145524_Content_56 = {
    Text = "Lời Nói Dối đã kết thúc, chuyến hành trình này không còn thuộc về anh nữa."
  },
  AvgDialog_145524_Content_57 = {
    Text = "Dùng một Lời Nói Dối, để đổi lấy một Lời Nói Dối khác…"
  },
  AvgDialog_145524_Content_58 = {
    Text = "Tạm biệt… tất cả mọi người… chúc hành trình của các bạn… cuối cùng đến được miền đất hứa…"
  },
  AvgDialog_145524_Content_59 = {
    Text = "Một chiếc Lông Vũ đen rơi ra từ đôi Cánh của Cas-tơ-lơ, bị cơn Tuyết gió cuốn lên cao."
  },
  AvgDialog_145524_Content_6 = {
    Text = "Giống như thuở còn trong nước ối."
  },
  AvgDialog_145524_Content_60 = {
    Text = "Hãy để nó thay mặt chúng ta, đến nơi bạn đã ước nguyện, miền tịnh thổ không tội lỗi…"
  },
  AvgDialog_145524_Content_61 = {
    Text = "Một khe hở mở ra dưới chân hai người, từ từ nuốt chửng tất cả những nặng nề vào trong băng tuyết của lòng núi."
  },
  AvgDialog_145524_Content_62 = {
    Text = "Chúc ngủ ngon, Pollux."
  },
  AvgDialog_145524_Content_63 = {
    Text = "Các bạn leo qua con đường núi mới, chỉnh lại hành lý nặng nề."
  },
  AvgDialog_145524_Content_64 = {
    Text = "Một cơn Tuyết gió Dường như mang theo ý thức riêng, cuộn xoáy trên bầu trời."
  },
  AvgDialog_145524_Content_65 = {Text = "Đó là.."},
  AvgDialog_145524_Content_66 = {
    Text = "Trong làn Tuyết gió, một chiếc Lông Vũ đen tuyền từ từ rơi xuống."
  },
  AvgDialog_145524_Content_67 = {
    Text = "Bạn giơ tay lên, nó vừa vặn rơi xuống lòng bàn tay bạn."
  },
  AvgDialog_145524_Content_68 = {
    Text = "Tựa như Lời chúc đến từ xa."
  },
  AvgDialog_145524_Content_69 = {
    Text = "Độ cao -7000m-"
  },
  AvgDialog_145524_Content_7 = {
    Text = "Hãy trở về đây, Pollux. Giống như hồi chúng ta còn nhỏ."
  },
  AvgDialog_145524_Content_8 = {
    Text = "Đầu óc Pollux tràn ngập sự bối rối, đầy những điều không thể hiểu. Nhưng không hiểu sao, anh không thể đẩy vòng tay ấm áp đó ra."
  },
  AvgDialog_145524_Content_9 = {
    Text = "Tiếng quở trách nghiêm khắc đột ngột vang lên bên tai."
  },
  AvgDialog_145525_Content_1 = {
    Text = "Hang động trở lại vẻ yên tĩnh kỳ lạ, mọi người vẫn chưa hoàn hồn nhìn nhau."
  },
  AvgDialog_145525_Content_10 = {
    Text = "Chỉ là trong núi này còn có một sự tồn tại nào đó ngoài nữ thần, đang mưu toan cướp đi ước nguyện của các bạn."
  },
  AvgDialog_145525_Content_11 = {
    Text = "Thôi đừng dọa mọi người nữa, Caraboo."
  },
  AvgDialog_145525_Content_12 = {
    Text = "Tin hay không là tùy các bạn nhé. Nữ thần núi Tuyết có thể cảm nhận được nó, ngay gần đoàn của chúng ta, đang bám theo sát sao…"
  },
  AvgDialog_145525_Content_13 = {
    Text = "Bạn không thể phân biệt được từ giọng điệu của cô ấy rằng cô ấy đang giả vờ hay thực sự cảm nhận được điều gì đó."
  },
  AvgDialog_145525_Content_14 = {
    Text = "gió tuyết dần tắt."
  },
  AvgDialog_145525_Content_15 = {
    Text = "Trong sự nặng nề như vậy, các bạn lại Khởi hành."
  },
  AvgDialog_145525_Content_2 = {
    Text = "Kỳ lạ, tôi đã nhiều lần đi cùng đoàn leo núi đến độ cao này, nhưng đây là lần đầu tiên gặp phải chuyện như thế này…"
  },
  AvgDialog_145525_Content_3 = {
    Text = "Điều đó chứng tỏ rằng những nguy hiểm trên ngọn núi Tuyết này không chỉ là nhiệt độ âm ba mươi độ và tình trạng thiếu oxy ở độ cao lớn."
  },
  AvgDialog_145525_Content_4 = {
    Text = "Caraboo hạ thấp giọng, chậm rãi trình bày bằng giọng điệu khiến người ta lạnh sống lưng."
  },
  AvgDialog_145525_Content_5 = {
    Text = "Nữ thần núi Tuyết thực sự tồn tại."
  },
  AvgDialog_145525_Content_6 = {
    Text = "<Red:Nữ thần tuyết sơn không chào đón các người, không chào đón những kẻ thiếu lòng thành kính.>"
  },
  AvgDialog_145525_Content_7 = {
    Text = "Không khí trở nên cứng đờ."
  },
  AvgDialog_145525_Content_8 = {
    Text = "Đùa các bạn thôi! Không ai thực sự tin chứ!"
  },
  AvgDialog_145525_Content_9 = {
    Text = "Ta là nữ thần núi Tuyết tốt bụng nhất, với lời cầu nguyện của ta, ngọn núi sẽ chào đón các bạn, thẳng tiến đến đỉnh cao nhất."
  },
  AvgDialog_145526_Content_1 = {
    Text = "Ngày Rời Tổ"
  },
  AvgDialog_145526_Content_10 = {
    Text = "Chúng ta vừa chỉ chống đỡ được một đợt tấn công, nhưng đợt công kích của nó sẽ không dừng lại."
  },
  AvgDialog_145526_Content_11 = {
    Text = "Ở nơi hiểm trở như núi cao thế này, con người khó tránh khỏi có lúc bộc lộ sự Mong manh và yếu đuối…"
  },
  AvgDialog_145526_Content_12 = {
    Text = "Những lúc như vậy, tốt nhất là tự lừa mình đi."
  },
  AvgDialog_145526_Content_13 = {
    Text = "Caraboo không biết từ đâu lấy ra một quả Táo, cắn một miếng rau ráu, vẻ mặt thản nhiên kiểu \"câu đó không phải tôi nói\"."
  },
  AvgDialog_145526_Content_14 = {
    Text = "…Bạn nói vậy cũng không sai."
  },
  AvgDialog_145526_Content_15 = {
    Text = "Dù sao, chúng ta phải tìm ra, rồi bắt lấy nó."
  },
  AvgDialog_145526_Content_16 = {
    Text = "Nhưng chúng đi trên tuyết không để lại dấu vết, chúng ta phải làm thế nào…"
  },
  AvgDialog_145526_Content_17 = {
    Text = "Để tôi lo. Tôi giỏi đối phó với kẻ lừa đảo nhất rồi, phải không?"
  },
  AvgDialog_145526_Content_18 = {
    Text = "Xem kìa, họ sắp đến rồi."
  },
  AvgDialog_145526_Content_19 = {
    Text = "Caraboo chỉ về phía bên cạnh đoàn, con chó dẫn đường duy nhất còn sống cúi thấp người, miệng rên rỉ khe khẽ."
  },
  AvgDialog_145526_Content_2 = {Text = "Wendigo."},
  AvgDialog_145526_Content_20 = {
    Text = "Các bạn đừng động đậy, cũng đừng nói gì."
  },
  AvgDialog_145526_Content_21 = {
    Text = "Cô ấy ném cho bạn quả Táo đã cắn một miếng."
  },
  AvgDialog_145526_Content_22 = {
    Text = "Trong vết cắt giấu một mảnh giấy nhỏ: Dù tôi nói gì tiếp theo, đừng tin."
  },
  AvgDialog_145526_Content_23 = {
    Text = "Caraboo im lặng lại, cô ấy nhắm mắt, rồi mở ra."
  },
  AvgDialog_145526_Content_24 = {
    Text = "Khoảnh khắc đó, ánh mắt cô ấy thay đổi. Mơ hồ, lo lắng, mê man, những cảm xúc phức tạp chứa đựng trong đôi mắt nhỏ bé của cô ấy."
  },
  AvgDialog_145526_Content_25 = {
    Text = "<Shake:Dì Rosa, có phải dì không?>"
  },
  AvgDialog_145526_Content_26 = {
    Text = "<Shake:Dì có đang làm bánh Táo không? Con ngửi thấy mùi thơm rồi.>"
  },
  AvgDialog_145526_Content_27 = {
    Text = "<Shake:Dì Rosa, con sẽ không phàn nàn về vỏ bánh Táo dày nữa đâu. Từ đó đến nay, con chưa bao giờ ăn được chiếc bánh Táo nào ngon như vậy nữa. Con nhớ cái mùi thơm cháy đó lắm.>"
  },
  AvgDialog_145526_Content_28 = {
    Text = "<Shake:Dì Rosa. Con sẽ đến tìm dì ngay bây giờ, dì đợi con nhé.>"
  },
  AvgDialog_145526_Content_29 = {
    Text = "Caraboo loạng choạng bước về phía trước."
  },
  AvgDialog_145526_Content_3 = {
    Text = "William đọc từng chữ một."
  },
  AvgDialog_145526_Content_30 = {
    Text = "Trên tuyết, phía sau lưng Caraboo, hai đống tuyết cao bằng một người rưỡi đột ngột nhô lên."
  },
  AvgDialog_145526_Content_31 = {
    Text = "Nó lao thẳng về phía Caraboo. Ngay khoảnh khắc nó lao tới, Caraboo khom người xuống."
  },
  AvgDialog_145526_Content_32 = {
    Text = "<Big:William, chuẩn bị!!>"
  },
  AvgDialog_145526_Content_4 = {
    Text = "<Italic:\"Chân nó được đúc bằng lửa — khi nó chạy, Tuyết Thiêu Đốt dưới chân nó.\">"
  },
  AvgDialog_145526_Content_5 = {
    Text = "\"Dị Văn Phương Bắc\" quyển bảy có chép: <Italic:Phàm ai nghe Thầm thì trong đêm đông, tuyệt chớ đáp lời.>"
  },
  AvgDialog_145526_Content_6 = {
    Text = "<Italic:Đáp một lần, nó Ghi nhớ tên Bạn; đáp hai lần, nó nhận ra bóng Bạn; đáp đến lần thứ ba — Bạn chính là nó rồi.>"
  },
  AvgDialog_145526_Content_7 = {
    Text = "Chúng ta không thể tránh né nó sao?"
  },
  AvgDialog_145526_Content_8 = {
    Text = "Vô ích thôi, Chỉ cần nơi nào gió tuyết bao phủ, đó đều là lãnh địa Wendigo lang thang."
  },
  AvgDialog_145526_Content_9 = {
    Text = "Chúng từng là người. Vì ăn thịt đồng loại mà biến hình, từ đó môi miệng thối rữa, Đói Khát muôn đời — ăn cả khu rừng cũng chẳng no."
  },
  AvgDialog_145527_Content_1 = {Text = "Hành Lý"},
  AvgDialog_145527_Content_10 = {
    Text = "Không được."
  },
  AvgDialog_145527_Content_100 = {
    Text = "Anh đưa cành của mình lại gần lò lửa để châm lửa, rồi hòa vào giữa mọi người."
  },
  AvgDialog_145527_Content_101 = {
    Text = "Ngọn lửa truyền qua từng cành cây, ánh lửa Blinking lần lượt soi sáng từng Khuôn Mặt ngước nhìn lên."
  },
  AvgDialog_145527_Content_102 = {
    Text = "Khi vạn vật im lặng, dường như nghe thấy tiếng tụng kinh trầm thấp, tiếng chuông, tiếng trống vọng lại từ không xa."
  },
  AvgDialog_145527_Content_103 = {
    Text = "Hãy hô vang Lha Gyalo, rồi ném chúng vào đống lửa."
  },
  AvgDialog_145527_Content_104 = {
    Text = "Giọng khàn khàn nhưng mạnh mẽ Vang vọng trong không khí loãng, những cành cây trên tay lần lượt rơi vào đống lửa theo tiếng hô vang."
  },
  AvgDialog_145527_Content_105 = {
    Text = "Cảm ơn Thần Núi đã khoan dung cho hành động bất kính của chúng tôi khi bước vào thần vực."
  },
  AvgDialog_145527_Content_106 = {
    Text = "Cành thông bách phát ra tiếng lách tách trong đống lửa, làn khói xanh bay thẳng lên, rồi bị gió trên cao xé tan."
  },
  AvgDialog_145527_Content_107 = {
    Text = "Và bạn đã ngửi thấy một mùi bất thường từ đó."
  },
  AvgDialog_145527_Content_109 = {
    Text = "Được rồi, mức độ nguy hiểm và kế hoạch ứng phó khẩn cấp cho chuyến leo núi lần này đã được giải thích đầy đủ với mọi người."
  },
  AvgDialog_145527_Content_11 = {
    Text = "Ơ!!! Tại sao vậy!!!"
  },
  AvgDialog_145527_Content_110 = {
    Text = "Trong Một tuần vừa qua, các bạn cũng đã Thích Nghi với việc di chuyển khi đeo găng tay, giày leo núi và kính tuyết, đồng thời luyện tập và nắm vững cách sử dụng dây thừng và đinh tuyết."
  },
  AvgDialog_145527_Content_111 = {
    Text = "Dựa trên theo dõi chặt chẽ trong những ngày qua, 5-7 ngày tới là cửa sổ thời tiết thuận lợi nhất để leo núi, đây là thời điểm tốt để khởi hành."
  },
  AvgDialog_145527_Content_112 = {
    Text = "Hãy kiểm tra bản đồ tuyến đường, thức ăn, nhiên liệu, bình oxy, túi y tế và các vật dụng bổ sung khác mà mỗi người mang theo."
  },
  AvgDialog_145527_Content_113 = {
    Text = "Nhắc lại một lần nữa, trong quá trình leo núi phải <Yellow:tuyệt đối tuân theo lệnh của hướng dẫn viên>, ngoài những thành viên rút lui sớm, những người còn lại <Yellow:nghiêm cấm hành động rời khỏi đội>."
  },
  AvgDialog_145527_Content_114 = {
    Text = "Nếu đã sẵn sàng, chúng ta xuất phát thôi!"
  },
  AvgDialog_145527_Content_116 = {
    Text = "……………"
  },
  AvgDialog_145527_Content_117 = {
    Text = "Các bạn mới đi được chưa đầy nửa ngày trong núi thì thời tiết đang quang đãng bỗng nhiên mây đen kéo đến."
  },
  AvgDialog_145527_Content_118 = {
    Text = "Gió tuyết bỗng mạnh lên dữ dội, nhìn ra xung quanh ngay cả những góc cạnh của núi cũng khó mà nhận ra, những con chó dẫn đường đi cùng hướng dẫn viên cũng rên rỉ không chịu tiếp tục tiến lên."
  },
  AvgDialog_145527_Content_119 = {
    Text = "Kỳ lạ thật, theo kết quả theo dõi của chúng tôi, không nên xuất hiện thời tiết bất thường nhanh như vậy."
  },
  AvgDialog_145527_Content_12 = {
    Text = "Hai người kia chẳng phải cũng mới gia nhập đó sao?"
  },
  AvgDialog_145527_Content_120 = {
    Text = "Trước đây đã từng gặp tình huống tương tự chưa?"
  },
  AvgDialog_145527_Content_121 = {
    Text = "Chưa bao giờ. Dù kết quả theo dõi có sai lệch, thông thường cũng chỉ xảy ra sau ba ngày so với kết quả dự báo."
  },
  AvgDialog_145527_Content_122 = {
    Text = "<Shake:Tuyết gió bất thường… có vẻ như… <Yellow:ngọn núi đang từ chối chúng ta>.>"
  },
  AvgDialog_145527_Content_123 = {
    Text = "Không thể nào, đã có Nữ thần Tuyết Sơn là tôi trong đội, sao chuyện như vậy có thể xảy ra được?"
  },
  AvgDialog_145527_Content_124 = {
    Text = "Cũng không cần lo lắng quá, khi xuống núi đôi khi cũng gặp bão tuyết bất ngờ."
  },
  AvgDialog_145527_Content_125 = {
    Text = "Gần đây có điểm trú ẩn, ở đó thậm chí còn có một ít vật tư bổ sung, chúng ta hãy đến đó nghỉ ngơi một lúc, đợi tuyết gió ngừng rồi chỉnh đốn lại và xuất phát lại."
  },
  AvgDialog_145527_Content_126 = {
    Text = "Thế thì còn nói gì nữa, đi nhanh thôi!"
  },
  AvgDialog_145527_Content_13 = {
    Text = "Caraboo tức tối chìa tay ra chỉ vào bạn và William."
  },
  AvgDialog_145527_Content_14 = {
    Text = "Đơn giản thôi. Hai người đó là người lớn, có khả năng tự lo cho bản thân."
  },
  AvgDialog_145527_Content_15 = {
    Text = "Leo núi không phải trò chơi nhà chòi đâu, cô bé ạ."
  },
  AvgDialog_145527_Content_16 = {
    Text = "Ở đây, bạn có thể tự xưng là bố, là mẹ, là Tuyết Sơn Nữ Thần hay Ý Chí Tối Thượng đều được."
  },
  AvgDialog_145527_Content_17 = {
    Text = "Nhưng khi lên đến đỉnh cao trên năm nghìn mét, mọi Lời Nói Dối đều sẽ hiện nguyên hình trong gió tuyết và chứng say độ cao."
  },
  AvgDialog_145527_Content_18 = {
    Text = "Nhưng tôi có tiền, tôi có <Big:rất——nhiều——tiền——>!"
  },
  AvgDialog_145527_Content_19 = {
    Text = "Bạn chỉ là một đứa trẻ, bạn có thể có bao nhiêu——"
  },
  AvgDialog_145527_Content_2 = {
    Text = "Dưới sự dẫn dắt của hướng dẫn viên Naraka, các bạn và các thành viên đội leo núi đã tự giới thiệu với nhau."
  },
  AvgDialog_145527_Content_20 = {Text = "<Big:!>"},
  AvgDialog_145527_Content_21 = {
    Text = "Lời nói của Naraka bỗng dừng lại đột ngột."
  },
  AvgDialog_145527_Content_22 = {
    Text = "Cô gái móc ra một túi vải nặng trĩu, bốc ra một nắm đồng vàng, để chúng rào rào đổ trở vào túi, chỉ giữ lại một đồng, tung hứng xoay chuyển giữa các ngón tay."
  },
  AvgDialog_145527_Content_23 = {
    Text = "Đã nói rồi ta là tiên nữ, sao lại có thể thiếu thứ Vật ngoài thân như tiền bạc chứ!"
  },
  AvgDialog_145527_Content_24 = {
    Text = "<Small:Rốt cuộc là tiên nữ hay nữ thần đây……>"
  },
  AvgDialog_145527_Content_25 = {
    Text = "Kệ đi, ai quan tâm!"
  },
  AvgDialog_145527_Content_26 = {
    Text = "Caraboo tùy tay ném đồng vàng ra, Naraka vội vàng vươn người ra đỡ, loạng choạng, suýt ngã vào Tuyết."
  },
  AvgDialog_145527_Content_27 = {
    Text = "Anh ta cầm đồng vàng, cắn thử một cái, vui mừng khôn xiết."
  },
  AvgDialog_145527_Content_28 = {
    Text = "<Shake:Là thật rồi……!>"
  },
  AvgDialog_145527_Content_29 = {
    Text = "Hừ, đồng vàng trong tay tiên nữ, sao có thể là giả được?"
  },
  AvgDialog_145527_Content_3 = {
    Text = "tinkerer, một ca nương bí ẩn và xa cách, tự nói rằng muốn tìm chị gái của mình."
  },
  AvgDialog_145527_Content_30 = {
    Text = "Tóm lại, đoàn leo núi có thể đưa ta theo rồi chứ?"
  },
  AvgDialog_145527_Content_31 = {
    Text = "<Shake:<Small:Thật ra, để một đứa trẻ tham gia đoàn leo núi thì hơi thiếu trách nhiệm với sự an toàn của bạn…>>"
  },
  AvgDialog_145527_Content_32 = {
    Text = "<BigShake:Hm?>"
  },
  AvgDialog_145527_Content_33 = {
    Text = "Nhưng mà nói lại, đoàn leo núi của chúng tôi có Kinh nghiệm leo cao phong phú và vật tư dự trữ đầy đủ, bảo vệ một mình bạn thì <Big:quá dư sức> rồi!"
  },
  AvgDialog_145527_Content_34 = {
    Text = "Nhưng tôi nói trước, một khi bạn quyết định quay lại giữa chừng, chúng tôi sẽ để lại đủ vật tư bảo đảm cho bạn xuống núi, nhưng phí hướng dẫn đã thu thì <Big:không hoàn lại một xu> đâu nhé."
  },
  AvgDialog_145527_Content_35 = {
    Text = "Biết rồi biết rồi, tiên nữ mà lại đi tính toán mấy đồng lẻ với bạn sao?"
  },
  AvgDialog_145527_Content_36 = {
    Text = "<Shake:<Small:Lạ thật, lúc nãy Cô ấy không phải đang biểu diễn xin tiền sao?>>"
  },
  AvgDialog_145527_Content_37 = {
    Text = "Đừng tưởng ta không nghe thấy!"
  },
  AvgDialog_145527_Content_38 = {
    Text = "Ta đã nói rồi, đó là cúng bái! Những gì nữ thần muốn nhận là thành ý của mọi người, hiểu không?"
  },
  AvgDialog_145527_Content_39 = {
    Text = "<Shake:<Small:Khi không cần thiết, thính giác cũng tốt thật…>>"
  },
  AvgDialog_145527_Content_4 = {
    Text = "Evelyn, nhà khảo cổ học, vẫn đến vì mục đích nghiên cứu khoa học trong thế giới hậu tận thế này."
  },
  AvgDialog_145527_Content_40 = {
    Text = "<BigShake:Câu này tôi cũng nghe thấy!>"
  },
  AvgDialog_145527_Content_41 = {
    Text = "Cả đoàn kiểm đếm vật tư, chủ đề nhanh chóng chuyển sang nghi lễ cầu nguyện của nữ thần tuyết sơn."
  },
  AvgDialog_145527_Content_42 = {
    Text = "Các bạn có thực sự tin rằng trên đỉnh núi tuyết có một vị nữ thần có thể thực hiện mọi điều ước không?"
  },
  AvgDialog_145527_Content_43 = {
    Text = "William giả vờ hỏi một cách thờ ơ."
  },
  AvgDialog_145527_Content_44 = {
    Text = "Ít nhất người địa phương đều tin vào điều đó. Vì đội leo núi trước đó."
  },
  AvgDialog_145527_Content_45 = {
    Text = "Đội leo núi trước đó?"
  },
  AvgDialog_145527_Content_46 = {
    Text = "Ừ. Kể từ khi tin tức về Nữ thần Tuyết Sơn lan ra, Đại lục Bắc Tận đã tự hình thành một trật tự riêng. Đội leo núi đó là đội được huấn luyện bài bản nhất và có nhiều hy vọng chinh phục đỉnh núi nhất trong tất cả các đội."
  },
  AvgDialog_145527_Content_47 = {
    Text = "Họ xuất phát với tổng cộng bảy người. Nhưng trong quá trình leo núi, các thành viên lần lượt, từng người một, qua đời."
  },
  AvgDialog_145527_Content_48 = {
    Text = "Có người nửa đêm rời khỏi lều, chân trần bước vào bão tuyết; có người cắt đứt dây an toàn của mình, nhảy xuống từ vách băng;"
  },
  AvgDialog_145527_Content_49 = {
    Text = "Còn có người mất tích mấy ngày, cuối cùng lại được phát hiện chết cóng ở phía trước đoàn—"
  },
  AvgDialog_145527_Content_5 = {
    Text = "Khi các bạn đang bàn bạc kế hoạch Khởi hành vào ngày hôm sau, bỗng nhiên một cái đầu trắng thò vào cửa trại."
  },
  AvgDialog_145527_Content_50 = {
    Text = "Như thể sau khi chết, anh ta vẫn tiếp tục leo núi."
  },
  AvgDialog_145527_Content_51 = {
    Text = "Mọi người kiểm kê vật tư đều đồng loạt chậm lại."
  },
  AvgDialog_145527_Content_52 = {
    Text = "Cuối cùng, chỉ có một người sống sót trở về chân núi."
  },
  AvgDialog_145527_Content_53 = {
    Text = "Tuy nhiên, cũng không thể nói anh ta thực sự \"sống sót trở về\"."
  },
  AvgDialog_145527_Content_54 = {
    Text = "Ý nghĩa là gì?"
  },
  AvgDialog_145527_Content_55 = {
    Text = "Mười ngón tay của anh ta đều bị đóng băng thối rữa, tai nhét đầy tuyết lẫn Máu. Dù người khác hỏi gì, anh ta cũng chỉ lặp đi lặp lại mấy câu đó."
  },
  AvgDialog_145527_Content_56 = {
    Text = "Naraka hạ thấp giọng, bắt chước giọng điệu Mơ Ngủ của người sống sót đó."
  },
  AvgDialog_145527_Content_57 = {
    Text = "<Shake:\"Truyền thuyết là thật. Điều ước trên đỉnh núi là thật.\">"
  },
  AvgDialog_145527_Content_58 = {
    Text = "<Shake:<Red:\"Bịt tai lại, đừng nghe.\">>"
  },
  AvgDialog_145527_Content_59 = {
    Text = "<Shake:\"Người nghe thấy tiếng hát sẽ bị dụ dỗ, bị Nuốt chửng… rồi bay lên trời, biến thành <Red:mặt trăng>.\">"
  },
  AvgDialog_145527_Content_6 = {
    Text = "Này~ Đây có phải đội leo núi của Naraka không?"
  },
  AvgDialog_145527_Content_60 = {
    Text = "Sau đó thì sao?"
  },
  AvgDialog_145527_Content_61 = {
    Text = "Sau đó à……"
  },
  AvgDialog_145527_Content_62 = {
    Text = "Naraka nở một nụ cười kỳ lạ, nửa như cười nửa không."
  },
  AvgDialog_145527_Content_63 = {
    Text = "Người dân bản địa cho rằng họ đã xúc phạm Nữ thần Tuyết Sơn trên đường leo núi, lo sợ cơn thịnh nộ của nữ thần sẽ giáng xuống dân làng."
  },
  AvgDialog_145527_Content_64 = {
    Text = "Thế là họ chọn một đêm tối trời gió lớn, ném ông xuống khe băng sâu thăm thẳm."
  },
  AvgDialog_145527_Content_65 = {
    Text = "Đó là kết cục của câu chuyện sao?"
  },
  AvgDialog_145527_Content_66 = {Text = "Không."},
  AvgDialog_145527_Content_67 = {
    Text = "Từ đó về sau, mỗi khi trăng tròn, những người đi ngang qua khe băng ấy vẫn nghe thấy có tiếng hát vọng lên từ phía dưới."
  },
  AvgDialog_145527_Content_68 = {
    Text = "Vì vậy mọi người đều biết, những gì ông nói là thật. Trên núi nhất định tồn tại điều gì đó."
  },
  AvgDialog_145527_Content_69 = {
    Text = "Naraka cúi đầu xuống, cuộn từng vòng dây thừng vào hành lý, dường như những gì vừa kể chẳng qua là một chuyện cũ chẳng đáng bận tâm."
  },
  AvgDialog_145527_Content_7 = {
    Text = "Tìm tôi à?"
  },
  AvgDialog_145527_Content_70 = {
    Text = "Trong khoảnh khắc im lặng ngắn ngủi, chỉ có gió lướt qua lều, phát ra tiếng rên rỉ dài và mơ hồ."
  },
  AvgDialog_145527_Content_71 = {
    Text = "Tôi còn nghe nói, trong lúc leo núi, họ đã nghe thấy tiếng hát của Siren."
  },
  AvgDialog_145527_Content_72 = {
    Text = "Bạn lại nói nhảm rồi, Siren là yêu quái biển, sao lại xuất hiện trên núi được?"
  },
  AvgDialog_145527_Content_73 = {
    Text = "Caraboo bĩu môi không hài lòng, khẽ phát ra một tiếng."
  },
  AvgDialog_145527_Content_74 = {
    Text = "Dưới biển có quái vật biết hát, sao trên núi lại không thể có?"
  },
  AvgDialog_145527_Content_75 = {
    Text = "Tin hay không tùy bạn. Khi nghe thấy tiếng hát, nhớ bịt tai lại."
  },
  AvgDialog_145527_Content_76 = {
    Text = "Khi bạn còn muốn hỏi thêm, thì phát hiện Caraboo đã quay người bước vào trong căn lều nhỏ, không có ý tiếp tục tham gia cuộc thảo luận nữa."
  },
  AvgDialog_145527_Content_77 = {
    Text = "……………"
  },
  AvgDialog_145527_Content_78 = {
    Text = "Bảy ngày sau"
  },
  AvgDialog_145527_Content_79 = {
    Text = "Buổi tập hôm nay kết thúc tại đây, ngày mai chính là ngày leo núi chính thức rồi."
  },
  AvgDialog_145527_Content_8 = {
    Text = "Hehe, tôi nghe nói anh là hướng dẫn viên leo núi giỏi nhất cả tộc Sherpa đấy!"
  },
  AvgDialog_145527_Content_80 = {
    Text = "Caraboo bất ngờ bước lên, chặn Naraka lại khi cô chuẩn bị rời đi."
  },
  AvgDialog_145527_Content_81 = {
    Text = "Không tổ chức <Yellow:Nghi Lễ Weisang> sao?"
  },
  AvgDialog_145527_Content_82 = {
    Text = "Nghi Lễ Weisang, đó là gì vậy?"
  },
  AvgDialog_145527_Content_83 = {
    Text = "Trước mỗi lần leo núi, mười người Sherpa thì cả mười đều phải thực hiện nghi lễ cầu nguyện này. Bạn không có chút kính sợ Thần Minh nào sao?"
  },
  AvgDialog_145527_Content_84 = {
    Text = "Naraka vỗ tay lên trán."
  },
  AvgDialog_145527_Content_85 = {
    Text = "<Yellow:Ôi trời, việc nhiều quá, lỡ quên mất rồi.>"
  },
  AvgDialog_145527_Content_86 = {
    Text = "Cái này cũng có thể quên được sao?"
  },
  AvgDialog_145527_Content_87 = {
    Text = "Không sao, sáng mai tôi sẽ làm nhanh một cái đơn giản bù vào."
  },
  AvgDialog_145527_Content_89 = {
    Text = "Bạn vươn vai cho đỡ mỏi rồi đẩy cửa phòng ra, trong hành lang đã thoảng vào một làn khói nhẹ."
  },
  AvgDialog_145527_Content_9 = {
    Text = "Với Lời chúc của Tuyết Sơn Nữ Thần trên cao, anh có thể dẫn tôi cùng leo núi không?"
  },
  AvgDialog_145527_Content_90 = {
    Text = "William đứng trước gương đồng cách vài bước, đang từng nếp một vuốt phẳng nếp nhăn ở cổ áo."
  },
  AvgDialog_145527_Content_91 = {
    Text = "Chào buổi sáng, Người Giữ Bí Mật."
  },
  AvgDialog_145527_Content_92 = {
    Text = "Bạn hít hít mũi. Trong không khí là mùi cỏ cây đang cháy, bên dưới phảng phất một tầng hương thơm thanh mát lạnh lẽo."
  },
  AvgDialog_145527_Content_93 = {
    Text = "Đẩy cánh cửa lớn ra, hơi lạnh và làn khói hương nồng nàn cùng ùa vào."
  },
  AvgDialog_145527_Content_94 = {
    Text = "Giữa khoảng sân trống, một lò sang nhỏ đang cháy. Làn khói xanh trắng bốc lên từ cành tùng bách và thảo dược, thẳng tắp vươn lên bầu trời xám xanh."
  },
  AvgDialog_145527_Content_95 = {
    Text = "Người Sherpa xem các đỉnh núi là thần linh, riêng đỉnh Everest còn là nơi ngự trị của Nữ Thần Mẹ của Thế Giới."
  },
  AvgDialog_145527_Content_96 = {
    Text = "Trước lần leo núi chính thức đầu tiên, người Sherpa sẽ dựng bàn thờ, treo cờ kinh, tụng kinh văn, thực hiện nghi lễ \"đốt hương\" bên cạnh bàn thờ, để khói hương truyền lễ vật và lời cầu nguyện đến thần linh."
  },
  AvgDialog_145527_Content_97 = {
    Text = "Nghi lễ cầu phúc khá phức tạp, nghi lễ chính thức thậm chí kéo dài đến ba đến bốn tiếng đồng hồ."
  },
  AvgDialog_145527_Content_98 = {
    Text = "Naraka lấy từ trong túi vải ra một bó cành tùng bách, phân phát cho từng người."
  },
  AvgDialog_145527_Content_99 = {
    Text = "Giơ cao lên, chụm lại."
  },
  AvgDialog_145528_Content_1 = {
    Text = "Bạn lao tới, từ phía sau ôm chặt lấy eo Cas-tơ-lơ. Cas-tơ-lơ vẫn đang giãy giụa, dây thanh quản của hắn khóc gào trong gió tuyết đến hầu như xé toạc."
  },
  AvgDialog_145528_Content_10 = {
    Text = "Evelyn từng bước bước lại gần. Cô ấy ngồi xuống, nhìn thẳng vào mắt cậu thiếu niên đang bị bạn và William cùng nhau ghì xuống tuyết."
  },
  AvgDialog_145528_Content_11 = {
    Text = "Cas-tơ-lơ, hãy nghe tôi nói. Tôi cũng đã từng nghĩ rằng, Wendigo chỉ là sinh vật tồn tại trong truyền thuyết."
  },
  AvgDialog_145528_Content_12 = {
    Text = "Nhưng vừa rồi… tôi đã nghe thấy."
  },
  AvgDialog_145528_Content_13 = {
    Text = "Tôi đã nghe thấy… chồng tôi đang gọi tôi."
  },
  AvgDialog_145528_Content_14 = {
    Text = "Kể từ ngày anh ấy mất tích, ngày nào tôi cũng nghe thấy tiếng gọi như vậy, nhưng chưa lần nào rõ ràng, thật đến thế này…"
  },
  AvgDialog_145528_Content_15 = {
    Text = "Giọng Evelyn khẽ khàng trở nên khàn đi một chút."
  },
  AvgDialog_145528_Content_16 = {
    Text = "<Shake:Nhưng Cas-tơ-lơ… bạn có biết không…>"
  },
  AvgDialog_145528_Content_17 = {
    Text = "Kể từ khi chồng tôi mất tích trên núi tuyết, đã hơn chín mươi ngày trôi qua, từ lâu đã bỏ lỡ thời điểm cứu hộ tốt nhất."
  },
  AvgDialog_145528_Content_18 = {
    Text = "Trường hợp may mắn nhất, tôi chẳng qua chỉ có thể gặp được hài cốt của anh ấy trên một con đường núi nào đó."
  },
  AvgDialog_145528_Content_19 = {
    Text = "Anh ấy sẽ không còn sống… ở đây. Em trai của bạn, lại càng không thể."
  },
  AvgDialog_145528_Content_2 = {
    Text = "Cas-tơ-lơ, đó không phải hắn."
  },
  AvgDialog_145528_Content_20 = {
    Text = "Chúng ta phải tiếp tục đi lên, đi mãi đến tận đỉnh núi."
  },
  AvgDialog_145528_Content_21 = {
    Text = "Đó là cơ hội duy nhất để chúng ta có thể Gặp lại họ."
  },
  AvgDialog_145528_Content_22 = {
    Text = "Dưới sự an ủi của Evelyn, Cas-tơ-lơ dần dần bình tĩnh lại."
  },
  AvgDialog_145528_Content_23 = {
    Text = "Bạn nói đúng… trên núi tuyết sẽ không có phòng giam… anh ấy không ở nơi như vậy."
  },
  AvgDialog_145528_Content_24 = {
    Text = "Tôi sẽ kiên trì… cho đến khi Gặp lại anh ấy."
  },
  AvgDialog_145528_Content_25 = {
    Text = "Phía sau các bạn, ai đó cầm chiếc rìu băng, gõ lên tảng đá hai tiếng cộc cộc."
  },
  AvgDialog_145528_Content_26 = {
    Text = "Nếu tâm trạng của mọi người đã ổn định, chúng ta cần chuẩn bị đối phó với mối đe dọa thực sự rồi."
  },
  AvgDialog_145528_Content_27 = {
    Text = "<Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_3 = {
    Text = "<Shake:Bạn làm sao biết không phải hắn?! Bạn có quen hắn đâu!>"
  },
  AvgDialog_145528_Content_4 = {
    Text = "Các bạn không ai quen hắn cả! Chỉ có tôi quen, tôi nhận ra giọng hắn!! Chính tôi đã bỏ hắn lại đó!"
  },
  AvgDialog_145528_Content_5 = {
    Text = "Lần đầu tiên anh ta nâng cao giọng với William. Rồi chính anh ta cũng bị giọng mình làm cho giật mình."
  },
  AvgDialog_145528_Content_6 = {
    Text = "Cas-tơ-lơ, bình tĩnh lại, đó là <Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_7 = {
    Text = "Wendigo — quái vật trong núi… sẽ đào bới ra bóng tối sâu thẳm nhất trong lòng bạn…"
  },
  AvgDialog_145528_Content_8 = {
    Text = "Rồi, nó sẽ mượn giọng nói của người bạn thương nhớ, dụ dỗ kẻ lạc đường bước vào bẫy của nó."
  },
  AvgDialog_145528_Content_9 = {
    Text = "<Shake:Không, anh lấy tư cách gì mà nói——>"
  },
  AvgDialog_145529_Content_1 = {
    Text = "Một Mùa Xuân Khác"
  },
  AvgDialog_145529_Content_10 = {
    Text = "<Shake:Đây là… nơi nào vậy…?>"
  },
  AvgDialog_145529_Content_100 = {
    Text = "Dù là cuộc sống bình yên, hay người bề trên yêu thương."
  },
  AvgDialog_145529_Content_101 = {
    Text = "Thậm chí là chú thỏ nhỏ đó."
  },
  AvgDialog_145529_Content_102 = {
    Text = "Con thỏ hoang ngoài đồng quay đầu lại, đôi mắt tròn xoe nhìn thẳng vào cô ấy."
  },
  AvgDialog_145529_Content_103 = {
    Text = "Rồi quay người lại, hai chân đạp tung đất, chui vào hang đất mà đi."
  },
  AvgDialog_145529_Content_11 = {
    Text = "Dựa theo những lời cuối của Caraboo mà suy đoán, chúng ta hiện đang chính vị trong lòng núi."
  },
  AvgDialog_145529_Content_12 = {
    Text = "Việc cấp bách nhất bây giờ là tìm Đường thoát ra ngoài."
  },
  AvgDialog_145529_Content_13 = {
    Text = "Nơi này ta cũng chưa từng đến, e rằng không thể làm hướng dẫn cho các bạn được."
  },
  AvgDialog_145529_Content_14 = {
    Text = "Đừng lo, chúng ta đã trải nghiệm những khoảnh khắc khó khăn hơn thế này nhiều rồi."
  },
  AvgDialog_145529_Content_15 = {
    Text = "%player%, trên tay bạn là gì vậy?"
  },
  AvgDialog_145529_Content_16 = {
    Text = "Ủa, đây là… Sợi Chỉ của Arachne…"
  },
  AvgDialog_145529_Content_17 = {
    Text = "Không biết từ lúc nào, sợi chỉ này đã lặng lẽ quấn quanh ngón út của bạn."
  },
  AvgDialog_145529_Content_18 = {
    Text = "Sợi Chỉ vốn im lặng và dịu dàng kia, lúc này đang tỏa sáng và lấp lánh với ánh hào quang mê hoặc, phần đuôi tự nhiên kéo dài về phía bóng tối xa xăm."
  },
  AvgDialog_145529_Content_19 = {
    Text = "Đây là sự chỉ dẫn của số phận? Hãy đi theo nó và xem thử nào."
  },
  AvgDialog_145529_Content_2 = {
    Text = "tối. Bóng tối vô tận."
  },
  AvgDialog_145529_Content_20 = {
    Text = "Caraboo đi theo Sợi Chỉ, không biết đã tiến về phía trước bao lâu. Ở cuối Sợi Chỉ, một tia sáng xuất hiện."
  },
  AvgDialog_145529_Content_21 = {
    Text = "Ánh sáng…?"
  },
  AvgDialog_145529_Content_22 = {
    Text = "Ánh sáng và bóng tối đột ngột biến đổi."
  },
  AvgDialog_145529_Content_23 = {
    Text = "Đây là……?"
  },
  AvgDialog_145529_Content_24 = {
    Text = "Này, Caraboo, chậm thôi!"
  },
  AvgDialog_145529_Content_25 = {
    Text = "Nhìn kìa, Dì Rosa, ở đó có thỏ!"
  },
  AvgDialog_145529_Content_26 = {
    Text = "À, nó chui vào hang rồi!"
  },
  AvgDialog_145529_Content_27 = {
    Text = "Cô ấy đợi từ ban ngày đến tối, nhưng con thỏ mãi không chịu ra."
  },
  AvgDialog_145529_Content_28 = {
    Text = "Dì Rosa, con rõ ràng thấy con thỏ chui vào cái hang này mà!"
  },
  AvgDialog_145529_Content_29 = {
    Text = "Dì Rosa âu yếm vuốt ve những sợi tóc của Caraboo."
  },
  AvgDialog_145529_Content_3 = {
    Text = "Đau đau đau… Ta đang ở đâu thế này?"
  },
  AvgDialog_145529_Content_30 = {
    Text = "Đứa ngốc ơi, thỏ không phải là loài động vật đơn giản như vậy đâu."
  },
  AvgDialog_145529_Content_31 = {
    Text = "Những hang động trong các cánh đồng này kết nối với nhau dưới lòng đất như một mạng lưới giao thông phức tạp."
  },
  AvgDialog_145529_Content_32 = {
    Text = "Con thỏ trắng nhỏ mà con nhắm tới, chắc đã chạy mất từ cái hang nào đó rồi."
  },
  AvgDialog_145529_Content_33 = {
    Text = "Vậy thì phải làm sao?"
  },
  AvgDialog_145529_Content_34 = {
    Text = "Không làm sao cả, Caraboo nhỏ ơi."
  },
  AvgDialog_145529_Content_35 = {
    Text = "Chúng ta gieo hạt trên cánh đồng, Tưới nước, đợi chúng chín, thu hoạch, và thưởng thức những hoa trái mà Thần Minh ban tặng cho chúng ta."
  },
  AvgDialog_145529_Content_36 = {
    Text = "Nhưng, nếu con muốn con thỏ đó thì sao?"
  },
  AvgDialog_145529_Content_37 = {
    Text = "Caraboo bé nhỏ thân yêu của ta, chúng ta không thèm muốn con thỏ đó. Nếu con muốn ăn thịt, chúng ta có thể ra chợ đổi rau củ quả lấy."
  },
  AvgDialog_145529_Content_38 = {
    Text = "Nhưng, nếu con vẫn muốn con thỏ đó thì sao?"
  },
  AvgDialog_145529_Content_39 = {
    Text = "<Red:Tại sao, ta lại không thể có con thỏ đó chứ?>"
  },
  AvgDialog_145529_Content_4 = {
    Text = "Không cần hỏi cô ấy cũng biết. Cô ấy đang ở trong bụng con sâu."
  },
  AvgDialog_145529_Content_41 = {
    Text = "……………"
  },
  AvgDialog_145529_Content_42 = {
    Text = "Tại sao vào lúc này, lại nhìn thấy ký ức thời thơ ấu của mình…?"
  },
  AvgDialog_145529_Content_43 = {
    Text = "Bình tĩnh. Có lẽ vì đi trong tối quá lâu, ta bị ảo giác rồi."
  },
  AvgDialog_145529_Content_44 = {
    Text = "Đây không phải ảo giác đâu nhé?"
  },
  AvgDialog_145529_Content_45 = {
    Text = "<Shake:Ối trời! Có ma!! >"
  },
  AvgDialog_145529_Content_46 = {
    Text = "Bạn còn nhớ một trong bảy pháp khí, Sợi Chỉ số phận không? Những gì bạn thấy, chính là Quỹ đạo của số phận."
  },
  AvgDialog_145529_Content_47 = {
    Text = "Tiếp theo, Quỹ đạo của số phận sẽ chỉ cho bạn thấy một khả năng khác, cùng với điểm phân kỳ của nó."
  },
  AvgDialog_145529_Content_48 = {
    Text = "Điều này liên quan gì đến việc ta đang ở trong bụng quái vật?"
  },
  AvgDialog_145529_Content_49 = {
    Text = "Bởi vì, đó là ước nguyện của bạn. Ước nguyện là ngòi nổ, sẽ dẫn dắt mỗi người đến điểm cuối đã định."
  },
  AvgDialog_145529_Content_5 = {
    Text = "Chết tiệt, dụ người ta vào, rốt cuộc lại bị ăn thịt."
  },
  AvgDialog_145529_Content_50 = {
    Text = "Người đố câu đố gì đó, có thời gian đó sao không nói cho tôi biết cách ra ngoài đi? <BigShake:Này——>"
  },
  AvgDialog_145529_Content_51 = {
    Text = "Bóng tối lặng lẽ biến mất."
  },
  AvgDialog_145529_Content_52 = {
    Text = "Tch, keo kiệt thật. Thôi được rồi, dù sao trong khoang bụng của con sâu cũng không có lối rẽ nào khác, cứ tiếp tục đi thôi."
  },
  AvgDialog_145529_Content_54 = {
    Text = "……………"
  },
  AvgDialog_145529_Content_55 = {
    Text = "Dì Rosa! Dì đừng vội, con đến giúp dì ngay đây!"
  },
  AvgDialog_145529_Content_56 = {
    Text = "Đây là… con à?"
  },
  AvgDialog_145529_Content_57 = {
    Text = "Con ngoan, dì Chỉ là đến xem con thôi."
  },
  AvgDialog_145529_Content_58 = {
    Text = "Dì ơi, chân dì không tốt, dì không cần phải cứ vào vườn trồng trọt đâu. Con hái xong ít húng quế này rồi sẽ cùng dì về cho thỏ ăn."
  },
  AvgDialog_145529_Content_59 = {
    Text = "Bạn đã đi xem chưa? Con thỏ cái Đại Phì Mạc Tê tối qua đẻ một ổ thỏ con, đen, trắng, xám, vàng, hoa, đủ màu sắc hết!"
  },
  AvgDialog_145529_Content_6 = {
    Text = "Khoan đã, cái này là gì vậy? Sợi Chỉ…?"
  },
  AvgDialog_145529_Content_60 = {
    Text = "Caraboo của chúng ta đã lớn thành thiếu nữ rồi đấy nhỉ."
  },
  AvgDialog_145529_Content_61 = {
    Text = "Dì ơi, dì nói gì vậy. Mấy việc đồng áng này, hồi con mười ba tuổi con đã tự làm được rồi."
  },
  AvgDialog_145529_Content_62 = {
    Text = "Quyết định đúng đắn nhất mà dì đã làm trong đời này, chính là đón con từ tay cha mẹ con về bên dì."
  },
  AvgDialog_145529_Content_63 = {
    Text = "Khi bạn kể với tôi rằng bố say rượu và đánh bạn, tôi đã do dự cả một đêm, rồi vào Rạng Sáng, tôi đã lên chuyến tàu sớm nhất."
  },
  AvgDialog_145529_Content_64 = {
    Text = "Suýt nữa thì đánh nhau với bố bạn, mới giành được bạn về."
  },
  AvgDialog_145529_Content_65 = {
    Text = "Từ đó đến nay, đã gần mười năm rồi phải không?"
  },
  AvgDialog_145529_Content_66 = {
    Text = "Bây giờ, nếu không có bạn, chỉ với đôi chân này của tôi, thật không biết phải sống một mình thế nào—"
  },
  AvgDialog_145529_Content_67 = {
    Text = "À— À—"
  },
  AvgDialog_145529_Content_68 = {
    Text = "Đây là, đêm hôm đó— đêm hôm đó— một khả năng khác—"
  },
  AvgDialog_145529_Content_69 = {
    Text = "Đêm hôm đó, đêm cô ấy gặp \"Sâu Của Núi\", đêm cô ấy quyết định tự tay thoát khỏi số phận."
  },
  AvgDialog_145529_Content_7 = {
    Text = "Một Sợi Chỉ lấp lánh trong suốt, từ bóng tối phía xa vươn ra, lơ lửng trước mặt Caraboo."
  },
  AvgDialog_145529_Content_70 = {
    Text = "Thuộc về thế giới thật, đêm mà cô ấy đã trải nghiệm."
  },
  AvgDialog_145529_Content_71 = {
    Text = "Trong tiếng lửa lò sưởi lách tách, cô ấy đứng trước giường người cha say rượu, do dự rất lâu rất lâu."
  },
  AvgDialog_145529_Content_72 = {
    Text = "Hãy đi thôi, hãy làm điều mà bạn đã muốn làm từ lâu."
  },
  AvgDialog_145529_Content_73 = {
    Text = "Cô ấy giơ dao lên—"
  },
  AvgDialog_145529_Content_74 = {
    Text = "Đúng vậy, chính là như thế."
  },
  AvgDialog_145529_Content_75 = {
    Text = "Giết hắn đi, tất cả mọi người đều có thể được hạnh phúc."
  },
  AvgDialog_145529_Content_76 = {
    Text = "Rồi từ từ, từ từ hạ xuống."
  },
  AvgDialog_145529_Content_77 = {
    Text = "Xin lỗi, tôi vẫn không thể làm được."
  },
  AvgDialog_145529_Content_78 = {
    Text = "Hãy rời đi, Chỉ cần chạy thật xa khỏi nơi này, sẽ không phải chịu đựng đau khổ nữa."
  },
  AvgDialog_145529_Content_79 = {
    Text = "Đứa nhóc vô dụng."
  },
  AvgDialog_145529_Content_8 = {
    Text = "Kệ rồi tính, mày tốt nhất đừng có lừa tao!"
  },
  AvgDialog_145529_Content_80 = {
    Text = "Thôi được, thứ ta nhìn thấy ở ngươi là thứ khác."
  },
  AvgDialog_145529_Content_81 = {
    Text = "Đi thôi, nhờ cái lưỡi xảo quyệt của ngươi, chúng ta vẫn có thể có được báu vật quý giá nhất."
  },
  AvgDialog_145529_Content_82 = {
    Text = "Sáng sớm hôm sau, tôi lén trốn trong đống rơm trên xe bò, lẫn vào thị trấn gần nhất."
  },
  AvgDialog_145529_Content_83 = {
    Text = "Rồi thông qua danh tính và vé giả mạo, tôi lên chuyến tàu hướng về phía Đông."
  },
  AvgDialog_145529_Content_84 = {
    Text = "Từ đó về sau, tôi đã có nhiều danh tính, cháu gái của trưởng tàu, bạn của bảo vệ, thánh nữ giáo phái, nữ thần tuyết sơn…"
  },
  AvgDialog_145529_Content_85 = {
    Text = "Tôi đã bỏ lại tất cả quá khứ phía sau, bỏ lại trong đêm tuyết rơi dày đặc khi bỏ trốn đó."
  },
  AvgDialog_145529_Content_86 = {
    Text = "Sau đó, rất lâu rất lâu về sau, tôi mới nghe được từ miệng người đồng hương tình cờ gặp trên chiến trường—"
  },
  AvgDialog_145529_Content_87 = {
    Text = "Ông Hans ư?"
  },
  AvgDialog_145529_Content_88 = {
    Text = "Có một ngày tuyết rơi dày, ông ấy say xỉn bí tỉ."
  },
  AvgDialog_145529_Content_89 = {
    Text = "Ngọn lửa trong lò sưởi bị tuyết tan nhỏ giọt từ trần nhà dập tắt, thường ngày, cô con gái nhỏ của ông sẽ đến giúp ông nhóm lại."
  },
  AvgDialog_145529_Content_9 = {
    Text = "Bạn tỉnh dậy từ cơn mê, trước mắt là một khoảng trống mềm mại, ẩm ướt và ngột ngạt."
  },
  AvgDialog_145529_Content_90 = {
    Text = "Chỉ là ngày hôm đó, cô bé nhỏ đó không biết vì sao lại không ở nhà."
  },
  AvgDialog_145529_Content_91 = {
    Text = "Ông ấy đã chết cóng trong đêm tuyết đó."
  },
  AvgDialog_145529_Content_92 = {
    Text = "Sau đó chúng tôi cũng không gặp lại cô bé đó nữa."
  },
  AvgDialog_145529_Content_93 = {
    Text = "À đúng rồi, thưa Thánh nữ, tại sao ngài lại đột nhiên hỏi thăm chuyện này? phúc lành của ngài, có thể ban cho tôi chưa?"
  },
  AvgDialog_145529_Content_94 = {
    Text = "Caraboo bốc cho người thanh niên trước mặt một nắm kẹo đầy ắp."
  },
  AvgDialog_145529_Content_95 = {
    Text = "Thánh nữ ở trên cao, mỗi ngày một viên, ăn hết những viên kẹo phúc lành này, vết thương ở chân của anh sẽ lành lại thôi."
  },
  AvgDialog_145529_Content_96 = {
    Text = "Dù trong lòng cô ấy biết rõ, không có viên kẹo nào có thể chữa lành đôi chân đã bị cắt cụt của người thanh niên."
  },
  AvgDialog_145529_Content_98 = {
    Text = "……………"
  },
  AvgDialog_145529_Content_99 = {
    Text = "Thật buồn cười, thật sự buồn cười. Hóa ra đêm hôm đó, chỉ cần tôi không làm gì cả, là có thể có được hạnh phúc mà tôi khao khát."
  },
  AvgDialog_145530_Content_1 = {
    Text = "Đại Mộng"
  },
  AvgDialog_145530_Content_10 = {
    Text = "Nếu vậy, ta ủng hộ Bạn."
  },
  AvgDialog_145530_Content_11 = {
    Text = "Ta ủng hộ Bạn, tìm lại chính mình đã bị đánh mất."
  },
  AvgDialog_145530_Content_12 = {
    Text = "Xét cho cùng, chúng ta vốn là những kẻ ích kỷ nhất mà."
  },
  AvgDialog_145530_Content_13 = {
    Text = "Ngọn núi Tuyết đã chết."
  },
  AvgDialog_145530_Content_14 = {
    Text = "<Shake:Kết thúc rồi…>"
  },
  AvgDialog_145530_Content_15 = {
    Text = "Trung tâm ngọn núi Tuyết nứt ra một vết thương kinh hoàng, từ đỉnh đầu con sâu khổng lồ kéo dài đến tận cuối khoang bụng."
  },
  AvgDialog_145530_Content_16 = {
    Text = "Thân thể con sâu theo vết thương đó, chậm rãi, chậm rãi đổ sụp xuống hai bên."
  },
  AvgDialog_145530_Content_17 = {
    Text = "Các Bạn cũng theo sự sụp đổ của đỉnh núi mà rơi thẳng xuống."
  },
  AvgDialog_145530_Content_18 = {
    Text = "<Shake:Cẩn thận, núi sắp sụp rồi!>"
  },
  AvgDialog_145530_Content_19 = {
    Text = "Trong tiếng gió rít khi rơi xuống, Bạn bất ngờ nghe thấy một tiếng Thì thầm."
  },
  AvgDialog_145530_Content_2 = {
    Text = "Bạn đã nghĩ kỹ chưa?"
  },
  AvgDialog_145530_Content_20 = {
    Text = "Vẫn chưa kết thúc."
  },
  AvgDialog_145530_Content_21 = {
    Text = "Caraboo giơ tay ra."
  },
  AvgDialog_145530_Content_22 = {
    Text = "Trên Khuôn Mặt đầy vết nước mắt của Cô ấy, hiện lên một nụ cười thản nhiên."
  },
  AvgDialog_145530_Content_23 = {
    Text = "Rồi, trong lực hút mà các Bạn không thể kiểm soát, bảy vòng hào quang sáng lên."
  },
  AvgDialog_145530_Content_24 = {
    Text = "Những thứ đã chết… Chỉ là núi tuyết… Nghi lễ… vẫn đang vận hành!"
  },
  AvgDialog_145530_Content_25 = {
    Text = "Trong khoảnh khắc đó, trời đất dường như mất đi mọi âm thanh."
  },
  AvgDialog_145530_Content_26 = {
    Text = "Bạn Chỉ thấy môi cô ấy khẽ động, thốt ra một câu nói mãi nhiều giây sau mới Bắt đầu vang vọng khắp trời đất."
  },
  AvgDialog_145530_Content_27 = {
    Text = "Nguyện vọng của ta, là trên đời này sẽ không còn bất kỳ Lời Nói Dối nào nữa."
  },
  AvgDialog_145530_Content_28 = {
    Text = "Ngay trong khoảnh khắc lời cô ấy vừa thốt ra, thế giới trước Mắt tan vỡ."
  },
  AvgDialog_145530_Content_29 = {
    Text = "Tro bạc lả tả, rơi xuống thật nhẹ thật chậm từ bầu trời cao xa tít tắp."
  },
  AvgDialog_145530_Content_3 = {
    Text = "Ừ, tôi đã quyết định rồi."
  },
  AvgDialog_145530_Content_30 = {
    Text = "Đó là một sự sụp đổ lặng lẽ, một cuộc crash chậm rãi, Kết thúc buổi diễn của một Giấc mơ dài lâu từ thuở hồng hoang."
  },
  AvgDialog_145530_Content_31 = {
    Text = "Đỉnh núi."
  },
  AvgDialog_145530_Content_32 = {
    Text = "Tuyết tích."
  },
  AvgDialog_145530_Content_33 = {
    Text = "Bầu trời."
  },
  AvgDialog_145530_Content_34 = {Text = "Đất."},
  AvgDialog_145530_Content_35 = {
    Text = "Tất cả những gì từng tồn tại, như Lời Nói Dối bị vạch trần, tan biến thành Hư vô."
  },
  AvgDialog_145530_Content_36 = {
    Text = "……tại sao……?"
  },
  AvgDialog_145530_Content_37 = {
    Text = "Một loại tri thức mà Bạn không nên biết, cùng với ký ức xa xôi, như Mũi nhọn đâm thẳng vào tâm trí Bạn."
  },
  AvgDialog_145530_Content_38 = {
    Text = "Chiếc thuyền này là một giấc mơ, nhưng khi bức màn của những lời dối trá được vén lên..."
  },
  AvgDialog_145530_Content_39 = {
    Text = "Toàn bộ thế giới cũng là giấc mơ của ai đó, chỉ là giấc mơ này lớn hơn, ảo diệu hơn, và xa xôi hơn……"
  },
  AvgDialog_145530_Content_4 = {
    Text = "Đây là Lời Nói Dối, là sự phản bội."
  },
  AvgDialog_145530_Content_40 = {
    Text = "Ngay cả mặt trời, mặt trăng và các vì sao cũng xuất phát từ sự hư cấu của Ngài, chỉ những sinh linh ràng buộc với linh hồn của Ngài mới có thể..."
  },
  AvgDialog_145530_Content_41 = {
    Text = "\"Cả thế giới này đều là một lời nói dối khổng lồ\"."
  },
  AvgDialog_145530_Content_42 = {
    Text = "Cùng với nhận thức đó, sự tan rã càng thêm tăng tốc. Trên trời đổ xuống một trận mưa bạc dày đặc."
  },
  AvgDialog_145530_Content_43 = {
    Text = "Mưa dày rơi xuống mặt nước. Những mảnh vỡ từng là \"thế giới\" ấy, hóa thành những giọt mưa bạc, từ từ chìm xuống Hải Vực bao la vô tận."
  },
  AvgDialog_145530_Content_44 = {
    Text = "Còn Bạn thì đang ở trong lòng biển đó."
  },
  AvgDialog_145530_Content_45 = {
    Text = "Chìm xuống, chìm xuống."
  },
  AvgDialog_145530_Content_46 = {
    Text = "Cho đến khi giấc mộng dài kết thúc, Bạn lại mở Mắt ra."
  },
  AvgDialog_145530_Content_47 = {
    Text = "Đối mặt với sự thật của thế giới này."
  },
  AvgDialog_145530_Content_48 = {
    Text = "Tại đáy sâu thẳm tối tăm nhất của Hải Vực."
  },
  AvgDialog_145530_Content_49 = {
    Text = "Thần Quốc huy hoàng đã diệt vong, cuối cùng cũng hiện ra chân dung thật sự của Ngài."
  },
  AvgDialog_145530_Content_5 = {
    Text = "Tất cả mọi người đều chăm sóc Bạn chu đáo, họ cũng có những ước nguyện muốn thực hiện."
  },
  AvgDialog_145530_Content_6 = {
    Text = "Nhưng cơ hội ước nguyện, Chỉ có một lần."
  },
  AvgDialog_145530_Content_7 = {
    Text = "Dù vậy, Bạn vẫn muốn cầu <Yellow:\"điều đó\"> sao?"
  },
  AvgDialog_145530_Content_8 = {
    Text = "Không có ước nguyện nào quan trọng hơn điều này."
  },
  AvgDialog_145530_Content_9 = {
    Text = "Cái bóng mỉm cười."
  },
  AvgDialog_145531_Content_1 = {
    Text = "Đêm Lành"
  },
  AvgDialog_145531_Content_10 = {
    Text = "Phía sau cô ấy, một ai đó lặng lẽ Mở mắt một bên, Nhìn lén theo bóng lưng cô ấy rời đi."
  },
  AvgDialog_145531_Content_11 = {
    Text = "tinkerer dò theo hướng tiếng hát mà bước đi chậm rãi, những mảnh băng vụn và đất đóng băng phát ra tiếng lạo xạo dưới đôi giày đế mỏng của cô ấy."
  },
  AvgDialog_145531_Content_12 = {
    Text = "(Đây là… hồ băng ban ngày…)"
  },
  AvgDialog_145531_Content_13 = {
    Text = "(Nhưng lại có chút gì đó khác…)"
  },
  AvgDialog_145531_Content_14 = {
    Text = "Mặt hồ đóng băng ban ngày, không hiểu vì sao đã Tỉnh giấc."
  },
  AvgDialog_145531_Content_15 = {
    Text = "Mặt nước tĩnh lặng không gợn sóng Mở mắt hướng lên vòm trời, tựa như một tấm gương sáng, lặng lẽ phản chiếu mặt trăng ngàn đời bất biến."
  },
  AvgDialog_145531_Content_16 = {
    Text = "Phiệt, có phải bạn không?"
  },
  AvgDialog_145531_Content_17 = {
    Text = "(Nước hồ… trong vắt bất thường…)"
  },
  AvgDialog_145531_Content_18 = {
    Text = "Cô ấy nhìn xuống đáy hồ."
  },
  AvgDialog_145531_Content_19 = {
    Text = "Nước hồ sâu không thấy đáy, dường như Xuyên thấu Đất, dẫn đến một nơi nào đó xa hơn cả những vì Sao."
  },
  AvgDialog_145531_Content_2 = {
    Text = "Vào lúc nửa đêm, tinkerer bị đánh thức bởi một âm thanh mơ hồ từ xa."
  },
  AvgDialog_145531_Content_20 = {
    Text = "Trong gió vang vọng một giọng hát mơ hồ, khàn khàn, già nua, như thể đã trải qua sự侵蚀của những năm tháng dài đằng đẵng không thể tưởng tượng mà vẫn chưa dừng lại."
  },
  AvgDialog_145531_Content_21 = {
    Text = "<Italic:La——la la~la~♪>"
  },
  AvgDialog_145531_Content_22 = {
    Text = "tinkerer nhắm mắt, hít thở sâu."
  },
  AvgDialog_145531_Content_23 = {
    Text = "(Giai điệu quen thuộc… nhớ nhung… hơi thở…)"
  },
  AvgDialog_145531_Content_24 = {
    Text = "Chất giọng khiến người ta liên tưởng đến lòng sông khô cạn, đến những lớp đá sa thạch bị phong hóa suốt mười vạn năm, đến tiếng kêu của những khu rừng cổ đại bị nén thành than dưới sức ép của các kỷ địa chất."
  },
  AvgDialog_145531_Content_25 = {
    Text = "(Đây có vẻ là… giai điệu… đến từ Sao hoang…)"
  },
  AvgDialog_145531_Content_26 = {
    Text = "Ký ức từ nghìn năm trước dần Phục hồi, cô ấy Bắt đầu thử khẽ hát theo, thử bắt kịp tiếng hát phiêu bạt kia."
  },
  AvgDialog_145531_Content_27 = {
    Text = "<Shake:La——la~la la la~♪>"
  },
  AvgDialog_145531_Content_28 = {
    Text = "Cô ấy cảm nhận được rồi, cô ấy đã nắm bắt được rồi."
  },
  AvgDialog_145531_Content_29 = {
    Text = "Trên Khuôn Mặt cô ấy hiện lên niềm vui chân thành."
  },
  AvgDialog_145531_Content_3 = {
    Text = "(Bên ngoài kia… đây là… tiếng hát?)"
  },
  AvgDialog_145531_Content_30 = {
    Text = "Âm vực của cô ấy mở rộng, vươn lên cao. Giọng hát trong trẻo như chim họa mi, uyển chuyển, nhẹ nhàng Vướng víu lấy giai điệu nền khàn khàn kia."
  },
  AvgDialog_145531_Content_31 = {
    Text = "Hai làn giọng Bắt đầu kéo căng, quấn quýt, xích lại gần nhau."
  },
  AvgDialog_145531_Content_32 = {
    Text = "<Change>La la la la la la~♪"
  },
  AvgDialog_145531_Content_33 = {
    Text = "Lớp băng từng tấc khép lại, sâu dưới đáy hồ, vô số khuôn mặt trắng bệch ngẩng đầu lên theo tiếng hát."
  },
  AvgDialog_145531_Content_34 = {
    Text = "Nhưng tinkerer hoàn toàn không hay biết."
  },
  AvgDialog_145531_Content_35 = {
    Text = "Chỉ còn tiếng hát. Tiếng hát vượt qua Vùng Tuyết đất đóng băng, vượt qua biển sao vũ trụ, vượt qua năm tháng ngàn đời, hóa thành một sự tồn tại mà mỗi người đều nên xem là vĩnh cửu."
  },
  AvgDialog_145531_Content_36 = {
    Text = "Đúng vậy, tôi không nên tự lừa dối mình nữa……"
  },
  AvgDialog_145531_Content_37 = {
    Text = "Tôi đã, không muốn tìm kiếm nữa rồi……Ở đâu cũng chẳng còn hy vọng……Cô ấy ở trong ký ức của tôi, và chỉ trong ký ức của tôi mà thôi……"
  },
  AvgDialog_145531_Content_38 = {
    Text = "Người bạn cũ dưới nước duỗi tay về phía cô ấy."
  },
  AvgDialog_145531_Content_39 = {
    Text = "Giọng hát già nua nhẹ nhàng Gọi cô ấy, Gọi tên cô ấy từ nghìn năm trước."
  },
  AvgDialog_145531_Content_4 = {
    Text = "Âm thanh đó rất nhẹ rất xa, xuyên qua vô số lớp băng tuyết và đá, thấm lên từ một nơi sâu thẳm không thể đo lường."
  },
  AvgDialog_145531_Content_41 = {
    Text = "Tôi nên từ bỏ rồi……"
  },
  AvgDialog_145531_Content_42 = {
    Text = "Hành trình này quá dài, quá dài, tôi đã từ lâu, rất mệt mỏi rồi……"
  },
  AvgDialog_145531_Content_43 = {
    Text = "Tiếng Gọi rung lên theo từng đốt xương của cô ấy, ban tặng cho cô ấy sự an ủi mà cô ấy khao khát. Nỗi u uất Không có chỗ nương tựa, nỗi đau buồn Không có chỗ trút bỏ, cuối cùng đã được một sự tồn tại nào đó thấu hiểu và đón nhận trọn vẹn."
  },
  AvgDialog_145531_Content_44 = {
    Text = "<Shake:Hãy ôm lấy tôi đi, Phiệt……Bóng hình trong ký ức của tôi ơi……Hãy ôm lấy tôi, như ngày xưa vậy……>"
  },
  AvgDialog_145531_Content_45 = {
    Text = "<Shake:Hãy ban cho tôi, sự Ninh bình mà tôi khao khát……>"
  },
  AvgDialog_145531_Content_46 = {
    Text = "Cô ấy nhẹ nhàng, thật nhẹ nhàng, bước vào làn nước hồ yên tĩnh."
  },
  AvgDialog_145531_Content_47 = {
    Text = "Mặt hồ không gợn lấy một chút sóng, như một chiếc lưỡi lạnh giá, nhẹ nhàng liếm qua eo, vai và cổ họng của cô."
  },
  AvgDialog_145531_Content_48 = {
    Text = "<Change>La la……"
  },
  AvgDialog_145531_Content_49 = {
    Text = "Cô ấy vẫn đang hát."
  },
  AvgDialog_145531_Content_5 = {
    Text = "Nó khàn khàn và chậm chạp, từng âm tiết như cát bụi cuộn qua mặt đất; nó cố chấp và không bao giờ ngừng nghỉ, như một dòng sông ngầm mãi mãi chảy trôi."
  },
  AvgDialog_145531_Content_50 = {
    Text = "Bóng hình cô ấy, thân xác cô ấy, sự tồn tại của cô ấy đều dần tan loãng theo tiếng hát, hòa tan và tản mát trong ánh trăng."
  },
  AvgDialog_145531_Content_51 = {
    Text = "Một ý nghĩ, một ý nghĩ yếu ớt đến mức Hầu như khó nắm bắt, vào khoảnh khắc này, bỗng nhiên len lỏi vào ý thức của tinkerer."
  },
  AvgDialog_145531_Content_52 = {
    Text = "(Kỳ lạ……hôm nay……đáng lẽ phải là trăng non mới đúng……)"
