  AvgDialog_145531_Content_53 = {
    Text = "Rồi — mặt hồ đột ngột sụp xuống phía trong."
  },
  AvgDialog_145531_Content_54 = {
    Text = "Không có tiếng nước bắn, cũng không có tiếng kêu la. Chỉ có tiếng hát vẫn còn vương vấn."
  },
  AvgDialog_145531_Content_55 = {
    Text = "mặt trăng trên bầu trời không biết đã biến mất từ lúc nào."
  },
  AvgDialog_145531_Content_56 = {
    Text = "Chỉ còn lại mặt hồ gợn sóng với ánh trăng, phản chiếu rõ nét bóng hình của tinkerer."
  },
  AvgDialog_145531_Content_58 = {
    Text = "Sáng sớm hôm sau."
  },
  AvgDialog_145531_Content_59 = {
    Text = "Có ai nhìn thấy tinkerer không?"
  },
  AvgDialog_145531_Content_6 = {
    Text = "(Rất xa xôi, mà lại rất quen thuộc…)"
  },
  AvgDialog_145531_Content_60 = {
    Text = "Mọi người đều lắc đầu."
  },
  AvgDialog_145531_Content_61 = {
    Text = "Ừm… tối qua tôi nghe thấy có tiếng động bên cạnh, nhưng rồi nhanh chóng ngủ thiếp đi mất."
  },
  AvgDialog_145531_Content_62 = {
    Text = "Tôi đã tìm khắp tất cả các lều, cô ấy không có ở đâu cả."
  },
  AvgDialog_145531_Content_63 = {
    Text = "Có thể cô ấy đã rút lui giữa chừng?"
  },
  AvgDialog_145531_Content_64 = {
    Text = "Hôm qua khi cô ấy đứng bên hồ băng, trạng thái đã rất không ổn rồi…"
  },
  AvgDialog_145531_Content_65 = {
    Text = "Evelyn lo lắng lẩm bẩm."
  },
  AvgDialog_145531_Content_66 = {
    Text = "Cô ấy thậm chí còn không mang bình oxy theo khi ra ngoài."
  },
  AvgDialog_145531_Content_67 = {
    Text = "Đây là đỉnh núi cao sáu nghìn mét, mỗi người phải — và chỉ có thể — tự chịu trách nhiệm cho sinh lực của chính mình."
  },
  AvgDialog_145531_Content_68 = {
    Text = "Ít nhất… ít nhất hãy đến bờ hồ băng xem một cái đã."
