  AvgDialog_145531_Content_69 = {
    Text = "Có đi không?"
  },
  AvgDialog_145531_Content_7 = {
    Text = "Những người đồng đội trong lều bên cạnh đều chìm vào giấc ngủ say vì mệt mỏi sau một ngày leo núi, ngay cả con chó hướng dẫn lẽ ra phải canh gác cũng đang phát ra tiếng ngáy đều đặn nhỏ nhẹ."
  },
  AvgDialog_145531_Content_70 = {
    Text = "Bạn muốn đi tìm tinkerer, không muốn từ bỏ bất kỳ khả năng nào dù nhỏ nhoi. Nhưng bạn cũng hiểu rõ, mỗi lựa chọn bạn đưa ra đều gánh trên vai tính mạng của cả đội."
  },
  AvgDialog_145531_Content_71 = {
    Text = "Đi thôi, độ cao ở đây và hồ băng hầu như không có sự khác biệt, thời gian đi về nằm trong tầm kiểm soát."
  },
  AvgDialog_145531_Content_72 = {
    Text = "Điều duy nhất cần chú ý, chỉ là những dã thú trên núi tuyết dọc đường mà thôi."
  },
  AvgDialog_145531_Content_8 = {
    Text = "Ra ngoài xem thử nào."
  },
  AvgDialog_145531_Content_9 = {
    Text = "Cô ấy kéo túi ngủ ra, vén cửa lều, từ từ thò người bước ra ngoài."
  },
  AvgDialog_145532_Content_1 = {
    Text = "Ngược Chiều"
  },
  AvgDialog_145532_Content_10 = {
    Text = "Rồi, đến lượt Evelyn. William đi sau cùng, Ánh Mắt trầm tĩnh và tập trung Bảo vệ tất cả mọi người."
