  AvgDialog_145532_Content_11 = {
    Text = "Khoan đã…"
  },
  AvgDialog_145532_Content_12 = {
    Text = "Ánh Mắt của Evelyn Nhìn chằm chằm vào một đoạn dây thừng trên vách đá gãy."
  },
  AvgDialog_145532_Content_13 = {
    Text = "Đây là… móc dây của họ! Tôi nhận ra dấu hiệu này!"
  },
  AvgDialog_145532_Content_14 = {
    Text = "Góc kẹp do mái Tuyết tạo thành! Góc kẹp do mái Tuyết tạo thành đã tạo nên một vùng an toàn, khiến nơi này không bị tuyết rơi che phủ!"
  },
  AvgDialog_145532_Content_15 = {
    Text = "Bạn nhìn xuống phía Evelyn. Chỉ một cái nhìn, ảo giác rơi xuống đó đã khiến bạn chóng mặt hoa mắt."
