  AvgDialog_145532_Content_18 = {
    Text = "Nguy hiểm lắm, Evelyn!"
  },
  AvgDialog_145532_Content_19 = {
    Text = "Không sao, tôi đến đây chính là vì điều này! Nói đến nguy hiểm, bản thân việc leo núi đã đủ nguy hiểm rồi!"
  },
  AvgDialog_145532_Content_2 = {
    Text = "Bốn người, như bốn viên xúc xắc, lơ lửng trên bàn cờ mang tên vách băng."
