  },
  AvgDialog_145532_Content_35 = {
    Text = "Vách băng mà khi leo lên từng bước đều vô cùng gian nan, lúc tụt xuống lại dễ dàng đến vậy, thoáng chốc William và Evelyn đã trở thành hai chấm nhỏ xa xôi trong khe băng."
  },
  AvgDialog_145532_Content_36 = {
