  AvgDialog_145532_Content_85 = {
    Text = "Bạn sẽ không bao giờ quên được."
  },
  AvgDialog_145532_Content_86 = {
    Text = "Chỉ cần một truyền thuyết, một đốm lửa nhỏ, nó sẽ Bắt đầu Thiêu Đốt…"
