  AvgDialog_145532_Content_9 = {
    Text = "Khi ánh mắt lướt qua, Chỉ thấy bên trong khe nứt là một màu đen tối tăm rùng rợn, không biết sẽ kết thúc ở đâu."
  },
  AvgDialog_145532_Content_90 = {
    Text = "Còn đối phương Chỉ là nhẹ nhàng nhìn lại, thứ lấp đầy Đôi Mắt ấy rốt cuộc là ngọn lửa hay là sự trống rỗng, cách nhau qua lớp phản chiếu của kính bảo hộ, anh không thể phân biệt được."
  },
  AvgDialog_145532_Content_91 = {
    Text = "Thôi đừng đứng ngẩn ra nữa, đi thôi. Ta đã hứa với ngươi, sẽ cùng các ngươi lên đến đỉnh, phải không?"
  },
  AvgDialog_145532_Content_92 = {
    Text = "Không hiểu sao, William luôn cảm thấy, dù Ánh Mắt đã chạm nhau, nhưng đối tượng mà đối phương đang nói chuyện, dường như không phải là bản thân mình."
  },
  AvgDialog_145532_Content_93 = {
    Text = "Evelyn không còn chờ anh nữa. Cô ấy quay người bước ra ngoài hang, cúi xuống kiểm tra dây kéo, động tác dứt khoát đến mức dường như lời Thú Nhận vừa rồi chưa từng xảy ra."
  },
  AvgDialog_145532_Content_94 = {
    Text = "William đứng yên tại chỗ, cổ họng khô khốc. Anh nhìn theo bóng lưng cô dần khuất xa, rồi quay lại nhìn cái miệng hang tối đen phía sau."
  },
  AvgDialog_145532_Content_95 = {
    Text = "Anh không tìm được lý do nào để nán lại thêm một giây. Anh thu lại Ánh Mắt, Im Lặng bước theo chân cô ấy."
  },
  AvgDialog_145534_Content_1 = {
    Text = "Trò hề kết thúc. Bây giờ, núi tuyết sẽ nuốt chửng các ngươi đấy."
  },
  AvgDialog_145534_Content_10 = {
    Text = "Đỉnh núi Xé toạc ra từ trung tâm, càng mở càng rộng, biến thành một cái miệng hố khổng lồ xuyên suốt trời Đất; nước dãi đỏ tươi chảy ào ào theo từng lớp nanh vuốt, đổ xuống như mưa."
