  AvgDialog_145534_Content_12 = {
    Text = "Mọi người chưa kịp thốt lên tiếng kêu đầu tiên đã bị nuốt vào bụng sâu thẳm không đáy của nó."
  },
  AvgDialog_145534_Content_13 = {
    Text = "Đất ngừng Rung động, giữa làn Tuyết rơi lả tả, một chiếc mũ nhọn nhỏ nhô lên."
  },
  AvgDialog_145534_Content_14 = {
    Text = "Caraboo phủi sạch Tuyết đầy người, hài lòng nhìn lại thành quả của mình—"
  },
  AvgDialog_145534_Content_15 = {
    Text = "Tại sao? Tại sao Bạn vẫn còn ở đây?"
