  AvgDialog_145534_Content_18 = {
    Text = "Bạn vừa nói, người đến thăm dâng nguyện ước cho núi, và núi sẽ đáp lại nguyện cầu của họ."
  },
  AvgDialog_145534_Content_19 = {
    Text = "Có lẽ vì, so với các vị, tôi không có nguyện ước gì, quá tầm thường, quá bình phàm, không đủ ngon chăng?"
