  AvgDialog_145534_Content_21 = {
    Text = "Caraboo trợn tròn đôi mắt, trong lời chất vấn của cô ấy ẩn chứa một chút không thể tin nổi lẫn tức giận."
  },
  AvgDialog_145534_Content_22 = {
    Text = "Không. Nguyện ước duy nhất của tôi trong chuyến đi này, đã thành hiện thực rồi."
  },
  AvgDialog_145534_Content_23 = {
    Text = "Dưới vách núi cuối cùng, tôi đã tìm thấy hài cốt của anh ấy. May mắn quá, anh ấy bị kẹt trong khe đá, không bị tuyết vùi lấp."
