  AvgDialog_145534_Content_24 = {
    Text = "Thể xác đã mục nát, nhưng biển tên vẫn còn đó. Tôi vẫn có thể nhận ra anh ấy, vẫn có thể xác nhận sự tồn tại của anh ấy."
