  },
  AvgDialog_145534_Content_30 = {
    Text = "<Shake:Không, bạn đang tự lừa dối mình… điều đó không phải sự thật, bạn không thể cam lòng như vậy được…>"
  },
  AvgDialog_145534_Content_31 = {
