  AvgDialog_146516_Content_24 = {
    Text = "Và Máu Liên · Shiro… hẹn gặp lại trên đỉnh núi."
  },
  AvgDialog_146516_Content_25 = {
    Text = "Phía xa, đường viền đỉnh núi Tuyết ẩn hiện giữa những tầng mây."
  },
  AvgDialog_146516_Content_26 = {
    Text = "-Độ cao 7950m-"
  },
  AvgDialog_146516_Content_3 = {
    Text = "Cầu xích bay múa trên không, bạn và William bảo vệ Evelyn và Naraka, vất vả ứng phó tứ phía."
  },
  AvgDialog_146516_Content_4 = {
    Text = "Caraboo không biết đang ẩn sau đống tuyết nào, tuyết trắng tinh che khuất bóng hình cô ấy."
  },
  AvgDialog_146516_Content_5 = {
    Text = "Các bạn không thấy kỳ lạ sao? Cô ấy đã theo dõi chúng ta từ khi bắt đầu leo núi."
  },
  AvgDialog_146516_Content_6 = {
    Text = "Tại sao bây giờ mới đột nhiên tấn công?"
  },
  AvgDialog_146516_Content_7 = {
    Text = "<Shake:Nếu, mục tiêu của cô ấy không phải là giết chúng ta, mà là——>"
