  AvgDialog_146516_Content_8 = {
    Text = "Không kịp nữa rồi. Những sợi dây xoay vòng đã chia cắt tất cả mọi người, khiến các bạn không còn để ý đến hành lý nặng nề."
  },
  AvgDialog_146516_Content_9 = {
    Text = "<Big:——Báu vật trong tay chúng ta!>"
