  },
  AvgDialog_147080_Content_10 = {
    Text = "Được rồi được rồi, tôi biết. Nhưng không thể nói cho các bạn biết."
  },
  AvgDialog_147080_Content_100 = {
    Text = "Theseus nhờ cuộn chỉ của Ariadne mà thoát ra khỏi mê cung, nhưng tình yêu của họ lại không được nữ thần số phận ban lời chúc..."
  },
  AvgDialog_147080_Content_101 = {
    Text = "Cuối cùng, thần rượu Dionysus đã tặng cho Ariadne một chiếc vương miện hoa lệ khảm bảy viên bảo thạch lấp lánh."
  },
  AvgDialog_147080_Content_102 = {
    Text = "William liếc nhìn Caraboo một cái."
  },
  AvgDialog_147080_Content_103 = {
    Text = "Dù đã đồng hành suốt chặng đường dưới sự dẫn dắt của sợi chỉ, cùng nhau vượt qua gian nan, nhưng Theseus và Ariadne có lẽ vốn dĩ không phải người cùng đường."
