  AvgDialog_147080_Content_104 = {
    Text = "Caraboo tránh ánh mắt của William."
  },
  AvgDialog_147080_Content_105 = {
    Text = "Một vỏ rỗng đã hoàn thành sứ mệnh, đổi lấy một điều ước đủ sức cải tạo số phận, ngươi không thấy thiệt sao?"
  },
  AvgDialog_147080_Content_106 = {
    Text = "Mục đích chúng ta leo núi, vốn là thông qua chiếc vương miện này để tìm ra chủ nhân của vương miện."
  },
  AvgDialog_147080_Content_107 = {
    Text = "Ngươi có thể trực tiếp đọc ý thức của Caraboo, còn cô ấy có thể quan sát xem chúng ta có đang nói lời nói dối hay không."
  },
  AvgDialog_147080_Content_108 = {
    Text = "Vậy, bạn có thể khẳng định rằng những gì tôi nói bây giờ là sự thật, đúng không?"
  },
  AvgDialog_147080_Content_109 = {
    Text = "<Yellow:Bài của tôi, chính là lật bài ngửa>."
  },
  AvgDialog_147080_Content_11 = {
    Text = "Bạn đáp lại bằng Ánh Mắt giận dữ."
  },
  AvgDialog_147080_Content_111 = {
    Text = "<Shake:Ha ha, ha ha ha ha!> Nói rất đúng, thậm chí còn có thể lợi dụng ngược cơ chế này, làm ăn với người thông minh thật đơn giản."
  },
  AvgDialog_147080_Content_112 = {
    Text = "<Big:Hãy chuẩn bị để lấy lại tự do!>"
  },
  AvgDialog_147080_Content_113 = {
    Text = "<Shake:Đếm ngược, ba, hai, một——>"
  },
  AvgDialog_147080_Content_114 = {
    Text = "——Không."
  },
  AvgDialog_147080_Content_115 = {
    Text = "Những bức tường thịt từ bốn phía đồng loạt ép về phía các bạn, chất nhầy rỉ ra từ các nếp gấp biến thành vô số xúc tu mảnh dài, quấn chặt cổ tay, mắt cá chân và eo."
  },
  AvgDialog_147080_Content_116 = {
    Text = "Khoan đã, cái này với việc lấy lại tự do như đã nói có vẻ hơi khác nhau——"
  },
  AvgDialog_147080_Content_117 = {
    Text = "Ta chỉ hứa đưa các ngươi ra ngoài, chứ có hứa cho các ngươi một hành trình thoải mái dễ chịu không?"
  },
  AvgDialog_147080_Content_118 = {
    Text = "Một Sức mạnh khó cưỡng lại trào lên từ dưới chân."
  },
  AvgDialog_147080_Content_119 = {
    Text = "Các bạn như dị vật bị nuốt vào rồi đẩy ngược ra thực quản, nhanh chóng trồi lên trong hành lang Huyết Nhục chật hẹp và trơn ướt."
  },
  AvgDialog_147080_Content_12 = {
    Text = "Đừng giận, đừng giận, tôi sẽ giải thích ngay bây giờ."
  },
  AvgDialog_147080_Content_120 = {
    Text = "Trường nhìn bị bóng tối nuốt chửng. Bên tai chỉ còn tiếng nhớp nháp của Huyết Nhục cọ xát, cùng với nhịp tim trầm đục và kéo dài của cả ngọn núi."
  },
  AvgDialog_147080_Content_121 = {Text = "Đập."},
  AvgDialog_147080_Content_122 = {Text = "Đập."},
  AvgDialog_147080_Content_123 = {
    Text = "<Red:Đùng——>"
  },
  AvgDialog_147080_Content_124 = {
    Text = "Khi tiếng tim đập cuối cùng vang lên, phía trước nứt ra một vệt ánh sáng trắng chói mắt."
  },
  AvgDialog_147080_Content_125 = {
    Text = "Gió thổi vào mặt cuốn theo băng Tuyết."
  },
  AvgDialog_147080_Content_126 = {
    Text = "Các bạn bị Sức mạnh đó hất tung ra ngoài, ngã nặng xuống lớp tuyết tích sâu ngang đầu gối."
  },
  AvgDialog_147080_Content_127 = {
    Text = "Khụ… tên này chắc chắn đang trả thù."
  },
  AvgDialog_147080_Content_128 = {
    Text = "Ít nhất cũng không thu phí dọn phòng khi trả phòng. Theo tiêu chuẩn tiếp đón của Ngài, như vậy đã có thể gọi là hào phóng rồi."
  },
  AvgDialog_147080_Content_129 = {
    Text = "Bạn chống tay vào tuyết đứng dậy. Mùi tanh Máu vương vấn mãi trong lồng ngực, cuối cùng cũng bị cơn gió lạnh buốt thổi tan."
  },
  AvgDialog_147080_Content_13 = {
    Text = "Để bàn về cách rời khỏi đây, trước tiên chúng ta cần biết, đây là đâu, và tại sao chúng ta lại ở đây."
  },
  AvgDialog_147080_Content_130 = {
    Text = "Nơi này đã không còn là sườn núi lúc mới đến nữa."
  },
  AvgDialog_147080_Content_131 = {
    Text = "Nhìn ra xung quanh, tất cả những đỉnh núi thấp hơn đều chìm dưới biển mây. Bầu trời đen kịt gần đến mức dường như có thể với tay chạm được, còn Sao thì ẩn hiện sau màn Tuyết bị cơn gió cuốn lên."
  },
  AvgDialog_147080_Content_132 = {
    Text = "Các bạn đang đứng trên đỉnh cao nhất của cả dãy núi."
  },
  AvgDialog_147080_Content_133 = {
    Text = "Đây là…"
  },
  AvgDialog_147080_Content_134 = {
    Text = "Đỉnh núi thực sự."
  },
  AvgDialog_147080_Content_135 = {
    Text = "Tiếng nói vang lên từ bên dưới lớp tuyết tích."
  },
  AvgDialog_147080_Content_136 = {
    Text = "Lớp băng khẽ Rung động theo, dường như ngọn núi tuyết này chẳng qua chỉ là một đoạn xương lộ ra ngoài của một sinh vật khổng lồ nào đó."
  },
  AvgDialog_147080_Content_137 = {
    Text = "Nghi lễ của Nữ Thần Tuyết Sơn ở phía trước. Bảy đế pháp khí và tế phẩm lần lượt khớp vào nhau. Phần giải mã còn lại thì phải nhờ vào cậu nhóc tóc vàng lúc nãy thôi."
  },
  AvgDialog_147080_Content_138 = {
    Text = "Bạn không đi cùng chúng tôi sao?"
  },
  AvgDialog_147080_Content_139 = {
    Text = "Ta hiện diện khắp nơi."
  },
  AvgDialog_147080_Content_14 = {
    Text = "Đây là bụng của Sơn Trùng, và lý do Sơn Trùng dùng Nữ Thần Tuyết Sơn cùng nghi lễ ước nguyện để lừa các ngươi đến đây…"
  },
  AvgDialog_147080_Content_140 = {
    Text = "Một tiếng cười trầm vang lên từ dưới chân."
  },
  AvgDialog_147080_Content_141 = {
    Text = "Cả ngọn núi này đều là thân xác của ta. Mỗi bước các ngươi đặt xuống, đều đang bước trên Huyết Nhục của ta."
  },
  AvgDialog_147080_Content_142 = {
    Text = "Vì vậy, đừng ảo tưởng mà chơi những trò hề đáng cười."
  },
  AvgDialog_147080_Content_143 = {
    Text = "Hãy tiến lên. Để ta xem, các ngươi mang theo biết bao nhiêu ước nguyện như vậy, rốt cuộc sẽ mở ra cho ta một Cửa như thế nào."
  },
  AvgDialog_147080_Content_144 = {
    Text = "Tuyết tích trước mặt các bạn từ từ rẽ ra."
  },
  AvgDialog_147080_Content_145 = {
    Text = "Một bậc đá cổ xưa bị gió tuyết vùi lấp không biết bao nhiêu năm hiện ra, uốn lượn dẫn lên đỉnh núi."
  },
  AvgDialog_147080_Content_146 = {
    Text = "Và ở cuối bậc đá, bảy luồng ánh sáng vàng mờ nhạt lần lượt sáng lên, tựa như Đôi Mắt ngủ ngàn năm, cuối cùng cũng đợi được người đến Hoán tỉnh chúng."
  },
  AvgDialog_147080_Content_147 = {
    Text = "William bước lên bậc đá đầu tiên."
  },
  AvgDialog_147080_Content_148 = {
    Text = "Tay anh luôn đặt vào bên trong áo khoác — dường như đang vỗ về một ước nguyện đã bị cắt bỏ."
  },
  AvgDialog_147080_Content_149 = {
    Text = "Lúc này, không ai chú ý rằng chiếc Chìa Khóa Sự im lặng bao năm kia đang xuyên qua lớp vải, phát ra tiếng Rung động vô cùng nhỏ bé."
  },
  AvgDialog_147080_Content_15 = {
    Text = "Là để Nuốt chửng Sức mạnh của các bạn."
  },
  AvgDialog_147080_Content_150 = {
    Text = "Dường như có thứ gì đó, đang đợi nó Tại đỉnh núi."
  },
  AvgDialog_147080_Content_16 = {
    Text = "Giải thích ngắn gọn dễ hiểu."
  },
  AvgDialog_147080_Content_17 = {
    Text = "Vậy thì, Sức mạnh của những người leo núi khác…"
  },
  AvgDialog_147080_Content_18 = {
    Text = "Đều nằm trong những Lễ vật này rồi."
  },
  AvgDialog_147080_Content_19 = {
    Text = "Cơ chế hợp tác giữa Caraboo và Sâu Núi là, Cô ấy sàng lọc những Lễ vật có ước nguyện mạnh mẽ và linh tính, dụ dỗ đối phương bước vào vùng núi."
  },
  AvgDialog_147080_Content_2 = {
    Text = "Vậy thì, vị đại nhân này, điều gì thúc đẩy ngài nhập vai một hướng dẫn viên leo núi Sherpa vậy? Chẳng lẽ là vì tình yêu với môn thể thao mạo hiểm của con người?"
  },
  AvgDialog_147080_Content_20 = {
    Text = "Vấn đề đặt ra là, tại sao Sâu Núi lại chủ động phá vỡ sự hợp tác này?"
  },
  AvgDialog_147080_Content_21 = {
    Text = "Vì nó biết, tôi đã độnglắc."
  },
  AvgDialog_147080_Content_22 = {
    Text = "Caraboo nhắc đến cuộc trò chuyện cuối cùng trên sườn núi."
  },
  AvgDialog_147080_Content_23 = {
    Text = "Tôi từng nghĩ, không ai có thể Khắc chế được ham muốn, muốn thực hiện ước nguyện, Chỉ có thể dựa vào \"thứ phi nhân\". Nhưng cô ấy khiến tôi hiểu rằng, bằng lòng với sự bình thường cũng có thể có được hạnh phúc."
  },
  AvgDialog_147080_Content_24 = {
    Text = "Vào khoảnh khắc đó, tôi đã nảy sinh \"ước nguyện\" không cần thiết."
  },
  AvgDialog_147080_Content_25 = {
    Text = "\"Ước nguyện\" là mồi nhử, là ngòi nổ."
  },
  AvgDialog_147080_Content_26 = {
    Text = "Từ ngay ban đầu, tôi chính là \"Táo Vàng\" định sẵn bị nuốt."
  },
  AvgDialog_147080_Content_27 = {
    Text = "Chúng tôi làm sao xác nhận được rằng bạn không phải đang lừa chúng tôi một lần nữa?"
  },
  AvgDialog_147080_Content_28 = {
    Text = "Tin hay không tùy bạn. Hiện tại trong số tất cả các bạn, tôi là người căm ghét Sâu Của Núi nhất."
  },
  AvgDialog_147080_Content_29 = {
    Text = "Nếu không phải vào đêm tuyết đó, Sâu Của Núi dụ dỗ tôi, ký Khế Ước với nó… tôi đã không bước lên con đường ngày hôm nay."
  },
  AvgDialog_147080_Content_3 = {
    Text = "Nếu ta nói là để lên tiếng cho người Sherpa, bạn có tin không?"
  },
  AvgDialog_147080_Content_30 = {
    Text = "<Small:Tên lừa đảo đáng ghét>."
  },
  AvgDialog_147080_Content_31 = {
    Text = "Trong khoảnh khắc Im Lặng ngắn ngủi, chỉ có tiếng thở phập phồng buồn nôn của bức tường Huyết Nhục."
  },
  AvgDialog_147080_Content_32 = {
    Text = "Hiểu rồi. Chỉ cần bạn không có hành động quá đáng, chúng tôi tạm thời sẽ không truy cứu những vấn đề trong quá khứ."
  },
  AvgDialog_147080_Content_33 = {
    Text = "Điều cấp bách hơn lúc này, là tìm ra cách thoát khỏi dạ dày của vị Thần Minh này… tốt nhất là không cần nhờ đến sức mạnh của vị N tiên sinh đó."
  },
  AvgDialog_147080_Content_34 = {
    Text = "Ôi ôi ôi, các bạn cứ phũ phàng với tấm lòng tốt đẹp của N tiên sinh như vậy sao?"
  },
  AvgDialog_147080_Content_35 = {
    Text = "Hay các bạn thực sự cho rằng, bước ra khỏi bụng của Ngài đơn giản như trả phòng khách sạn không vừa ý vậy?"
  },
  AvgDialog_147080_Content_36 = {
    Text = "Bạn đã nói bạn không thể cho chúng tôi biết."
  },
  AvgDialog_147080_Content_37 = {
    Text = "Tưởng tôi cố tình giấu các bạn? Thế thì bạn oan uổng cho tôi quá rồi."
  },
  AvgDialog_147080_Content_38 = {
    Text = "N mân mê bông hồng tự nhiên xuất hiện giữa các ngón tay, thong thả đưa Ánh Mắt về phía Caraboo."
  },
  AvgDialog_147080_Content_39 = {
    Text = "Dù tôi có cách nào, cũng không thể để bạn biết được. Phải không, kẻ lừa dối nhỏ bé?"
  },
  AvgDialog_147080_Content_4 = {
    Text = "Tin chứ, tôi không chỉ tin điều đó, còn tin rằng Bà Sorrel chủ trương vô vi nhi trị, Lắc rửa tay gác kiếm không bao giờ đặt cược nữa, Erika thông suốt nhân tính ăn nói duyên dáng…"
  },
  AvgDialog_147080_Content_40 = {
    Text = "Caraboo không phản bác. Cô ấy Chỉ là cắn chặt môi dưới, tránh ánh mắt của tất cả mọi người."
  },
  AvgDialog_147080_Content_41 = {Text = "Caraboo?"},
  AvgDialog_147080_Content_42 = {
    Text = "… Nó có thể nghe thấy ta."
  },
  AvgDialog_147080_Content_43 = {
    Text = "Không phải ẩn dụ đâu. Năm sáu tuổi, khi tôi theo nó rời đi trong đêm tuyết đó, tôi đã đem linh hồn mình thế chấp cho nó rồi."
  },
  AvgDialog_147080_Content_44 = {
    Text = "Đây là Khế Ước giữa ta và nó. Nó cho ta mượn Sức mạnh của \"Lời Nói Dối\", khiến ta có thể lừa dối tất cả mọi người trên đời; còn như một cái giá —"
  },
  AvgDialog_147080_Content_45 = {
    Text = "Đối với nó, ta Không có thể giấu đi bất kỳ một suy nghĩ nào."
  },
  AvgDialog_147080_Content_46 = {
    Text = "… Vậy thì, lúc này, mỗi câu chúng ta nói —"
  },
  AvgDialog_147080_Content_47 = {
    Text = "Chỉ cần lọt vào tai ta, vào đầu óc ta, nó sẽ biết tất cả."
  },
  AvgDialog_147080_Content_48 = {
    Text = "Huyết Nhục bốn phía bỗng căng cứng lại một khoảnh khắc, rồi từ từ chùng xuống. Như thể có thứ gì đó khổng lồ đang ẩn sau tấm màn, thú vị lắng nghe tất cả những điều này."
  },
  AvgDialog_147080_Content_49 = {
    Text = "Bây giờ các bạn hiểu rồi chứ?"
  },
  AvgDialog_147080_Content_5 = {
    Text = "Bây giờ không phải lúc cãi nhau."
  },
  AvgDialog_147080_Content_50 = {
    Text = "Cách giải quyết vẫn luôn ở đó. Nhưng chỉ cần nó lọt vào tai cô tiểu thư này, thì chẳng khác nào đang chơi poker mà lật thẳng bài tẩy cho đối thủ xem."
  },
  AvgDialog_147080_Content_51 = {
    Text = "Khi chúng ta bàn kế hoạch, để Caraboo né tránh ra một chút?"
  },
  AvgDialog_147080_Content_52 = {
    Text = "Dù tôi không nghe kế hoạch của các bạn, khi thực hiện tôi cũng có thể nhận ra điều bất thường."
  },
  AvgDialog_147080_Content_53 = {
    Text = "Tôi không thể nhìn thấy micro biểu cảm của Bạn, những cử chỉ nhỏ của Bạn. Nếu không, tôi sẽ biết câu nào đang nói Lời Nói Dối."
  },
  AvgDialog_147080_Content_54 = {
    Text = "Hay là, bạn có thể không nhìn?"
  },
  AvgDialog_147080_Content_55 = {
    Text = "Không, Lời Nói Dối là một bầu không khí lưu động… và tôi đã ngâm mình trong đó quá lâu rồi."
  },
  AvgDialog_147080_Content_56 = {
    Text = "Đôi khi dù không ai lên tiếng, tôi vẫn có thể cảm nhận được sự tồn tại của Lời Nói Dối từ trong không khí đông cứng."
  },
  AvgDialog_147080_Content_57 = {
    Text = "Để tôi thử xem."
  },
  AvgDialog_147080_Content_58 = {
    Text = "Cùng với tiếng búng ngón tay giòn tan, làn khói đen trườn lên mí Mắt của Caraboo."
  },
  AvgDialog_147080_Content_59 = {
    Text = "Được rồi, Mở mắt ra đi."
  },
  AvgDialog_147080_Content_6 = {
    Text = "Arachne dẫn chúng ta đến đây, chắc chắn có lý do của cô ấy. Còn bạn, hẳn là một mắt xích của số phận."
  },
  AvgDialog_147080_Content_60 = {
    Text = "Caraboo Mở mắt. Mọi thứ trước mắt cô ấy đều bị bao phủ bởi một lớp khói Sự biến dạng, ngay cả âm thanh cũng trở nên mơ hồ và xa xăm."
  },
  AvgDialog_147080_Content_61 = {
    Text = "William lại bỗng cúi mắt xuống, đốt ngón tay chống vào cằm, như thể đang Suy luận một ván cờ chỉ mình anh ấy có thể nhìn thấy."
  },
  AvgDialog_147080_Content_62 = {
    Text = "Dừng lại đi."
  },
  AvgDialog_147080_Content_63 = {Text = "Ừm?"},
  AvgDialog_147080_Content_64 = {
    Text = "Không cần che Đôi Mắt cô ấy."
  },
  AvgDialog_147080_Content_65 = {
    Text = "Ngược lại là đằng khác, tiếp theo, tôi muốn Caraboo hãy tập trung hết mười hai phần tinh thần, để phân biệt thật giả trong từng câu nói của tôi."
  },
  AvgDialog_147080_Content_66 = {
    Text = "Nghe cho rõ nhé, Caraboo — hay nói đúng hơn, con sâu của núi ẩn sau Caraboo. Ta muốn giao dịch với ngươi."
  },
  AvgDialog_147080_Content_67 = {
    Text = "Bức tường thịt rung lên như tiếng cười chế nhạo."
  },
  AvgDialog_147080_Content_68 = {
    Text = "Buồn cười thật, các ngươi đang ở trong bụng ta. Ngươi định dùng gì để giao dịch với ta?"
  },
  AvgDialog_147080_Content_69 = {
    Text = "Điều ước."
  },
  AvgDialog_147080_Content_7 = {
    Text = "Bạn nhất định biết cách ra ngoài đúng không, N?"
  },
  AvgDialog_147080_Content_70 = {
    Text = "Xung quanh bỗng nhiên im lặng hẳn."
  },
  AvgDialog_147080_Content_71 = {
    Text = "Trận pháp điều ước trên đỉnh núi <Yellow:không phải do ngươi tạo ra>, mà là thứ gì đó cổ xưa hơn ngươi từ bên ngoài, đúng không?"
  },
  AvgDialog_147080_Content_73 = {
    Text = "Sâu Núi im lặng một thoáng, rồi phát ra tiếng cười nhẹ không rõ thái độ."
  },
  AvgDialog_147080_Content_74 = {
    Text = "Thú vị. Tiếp tục đi."
  },
  AvgDialog_147080_Content_75 = {
    Text = "Trước lần leo núi này, truyền thuyết mà Caraboo kể có đôi chút khác biệt so với những gì lưu truyền trong dân gian vùng núi. Nói đơn giản, người dân vùng núi chỉ biết rằng leo lên đỉnh có thể thực hiện điều ước, chứ không biết đến sự tồn tại của bảy pháp khí."
  },
  AvgDialog_147080_Content_76 = {
    Text = "Điều này hoàn toàn hợp lý. Nếu mục đích chỉ là dụ dỗ con người leo núi rồi nuốt chửng họ, thì không cần phải dệt nên truyền thuyết về bảy pháp khí."
  },
  AvgDialog_147080_Content_77 = {
    Text = "Chỉ cần nói với tất cả mọi người rằng, leo lên đỉnh là có thể thực hiện điều ước."
  },
  AvgDialog_147080_Content_78 = {
    Text = "Độ khó càng cao, người thách thức càng ít — đạo lý cơ bản này, các ngươi không thể không hiểu, trừ phi——"
  },
  AvgDialog_147080_Content_79 = {
    Text = "Trừ phi——"
  },
  AvgDialog_147080_Content_8 = {
    Text = "Ta biết… hay là không biết nhỉ… ôi chao, đây thực sự là một câu hỏi thú vị."
  },
  AvgDialog_147080_Content_80 = {
    Text = "Sâu Núi kéo dài giọng điệu mỉa mai."
  },
  AvgDialog_147080_Content_81 = {
    Text = "Trừ phi bảy pháp khí thật sự tồn tại, và nghi thức thực hiện điều ước cũng thật sự tồn tại."
  },
  AvgDialog_147080_Content_82 = {
    Text = "Còn ngươi ẩn náu bên cạnh trận pháp, không chỉ để nuốt chửng những kẻ leo núi.\nNgươi cũng đang đợi một cơ hội để kích hoạt nghi thức."
  },
  AvgDialog_147080_Content_83 = {
    Text = "Thế giới Huyết Nhục ngừng thở."
  },
  AvgDialog_147080_Content_84 = {
    Text = "Đã canh giữ nghi thức suốt bao lâu, tại sao ngươi không tự mình kích hoạt nó?"
  },
  AvgDialog_147080_Content_85 = {
    Text = "Con người, ngươi hỏi quá nhiều rồi đấy."
  },
  AvgDialog_147080_Content_86 = {
    Text = "Có vẻ như đã hỏi đúng rồi."
  },
  AvgDialog_147080_Content_87 = {
    Text = "Để ta đoán thử xem."
  },
  AvgDialog_147080_Content_88 = {
    Text = "Trong pháp trận tồn tại một nhân cốt lõi mà ngươi không thể phá giải, đúng không? Vì vậy bao nhiêu năm qua, ngươi tích lũy hết đợt lễ vật này đến đợt khác, nhưng vẫn không thể mở được cánh cửa cuối cùng đó."
  },
  AvgDialog_147080_Content_89 = {
    Text = "Bức tường thịt đột nhiên siết chặt lại, hầu như sắp nghiền nát tất cả mọi người."
  },
  AvgDialog_147080_Content_9 = {
    Text = "Đừng vòng vo, nói thẳng vào vấn đề đi."
  },
  AvgDialog_147080_Content_90 = {
    Text = "Ta biết tại sao ngươi không thể phá giải. Ta vừa nhìn lướt qua pháp trận, những ký văn khắc trên đó bao gồm tiếng Latin và các cổ tự khác."
  },
  AvgDialog_147080_Content_91 = {
    Text = "Còn vị... người thực hiện nhỏ bé của ngươi, dựa vào thời gian cô ấy rời nhà mà dự đoán, rõ ràng chưa từng được hưởng nền giáo dục học viện tử tế..."
  },
  AvgDialog_147080_Content_92 = {
    Text = "<Shake:Không biết chữ thì làm sao bạn được!>"
  },
  AvgDialog_147080_Content_93 = {
    Text = "Thời gian gấp rút, lúc nãy ta chưa kịp đọc kỹ đã bị ngươi nuốt vào đây. Nhưng ta đoán những gì ghi nhớ trên đó, phần lớn chính là kiến thức liên quan đến việc kích hoạt pháp trận."
  },
  AvgDialog_147080_Content_94 = {
    Text = "Nữ thần số phận dẫn dắt chúng ta đến đây, bảy pháp khí đã tề tựu đủ, ngươi nên biết, đây là lần ngươi đến gần nhất với việc thực hiện điều ước."
  },
  AvgDialog_147080_Content_95 = {
    Text = "Còn chúng ta, có thể <Yellow:tự nguyện từ bỏ cơ hội cầu nguyện với ngọn núi>."
  },
  AvgDialog_147080_Content_96 = {
    Text = "Con sâu của núi rơi vào Im Lặng kéo dài. Khi các bạn tưởng rằng nó sẽ không hồi đáp nữa, nó phát ra một tiếng khẽ."
  },
  AvgDialog_147080_Content_97 = {
    Text = "Từ bỏ điều ước... quả thật là một sự hy sinh đáng kể. Những gì ngươi muốn chắc không chỉ là ta thả các ngươi ra chứ?"
  },
  AvgDialog_147080_Content_98 = {
    Text = "Sau khi nghi lễ kết thúc, các pháp khí khác đều có thể thuộc về ngươi, nhưng chúng ta phải mang theo <Blue:Vương Miện Ariadne>."
  },
  AvgDialog_147080_Content_99 = {
    Text = "Vương Miện Ariadne..."
  },
  AvgDialog_147095_Content_1 = {
    Text = "Trong đại điện trống rỗng, chỉ có tiếng bước chân của bạn và Murphy vang vọng."
  },
  AvgDialog_149752_Content_1 = {
    Text = "Hang Rồng"
  },
  AvgDialog_149752_Content_10 = {
    Text = "Ngươi đã không còn gì, không thể chịu đựng thêm một lần lãng quên nữa."
  },
  AvgDialog_149752_Content_11 = {
    Text = "Ngọn lửa bùng cháy dữ dội đã bị mưa dập tắt, ngươi bước qua cánh cổng không người canh gác, nhìn thấy cảnh tượng tan hoang khắp nơi."
  },
  AvgDialog_149752_Content_12 = {
    Text = "Lâu đài sừng sững trong im lặng, thùng dầu rỗng, bao tải rách, khiên vỡ vụn, giáo gãy nát, tên cắm xuống như từng khóm cỏ tranh rạp mình trong gió, mùi tanh của bùn ướt hòa lẫn mùi khét cháy không tan."
  },
  AvgDialog_149752_Content_13 = {
    Text = "Nơi đây từng xảy ra một trận thảm sát, mà giờ chỉ còn lại bóng tối."
  },
  AvgDialog_149752_Content_14 = {
    Text = "Bóng tối lan tràn tự do trong màn đêm, leo lên tường cao, bò qua lỗ châu mai, nhấn chìm những xác chết nằm la liệt, phát ra tiếng ọc ọc. Ngươi cố không nghĩ đến điều đó có nghĩa là gì."
  },
  AvgDialog_149752_Content_15 = {
    Text = "Theo bóng tối… chỉ cần theo bóng tối…"
  },
  AvgDialog_149752_Content_16 = {
    Text = "Hơ, hơ… cứu… cứu tôi với…"
  },
  AvgDialog_149752_Content_17 = {
    Text = "Tiếng rên rỉ đau đớn vang lên từ dưới chiếc mũ giáp biến dạng, bóng tối quấn chặt lấy nó như người tình thân mật, ngươi lấy hết can đảm bước tới."
  },
  AvgDialog_149752_Content_18 = {
    Text = "Người mang bóng tối đến, hắn đã đi đâu rồi?"
  },
  AvgDialog_149752_Content_19 = {
    Text = "<Shake:Bóng… tối? Không, không, đó là quái vật! Máu đen… rỗng ruột… kỵ sĩ tử thần… là thật, tất cả đều là thật!>"
  },
  AvgDialog_149752_Content_2 = {
    Text = "Ước hẹn là gì? Là phép màu chỉ thành hiện thực khi ta tin vào nó."
  },
  AvgDialog_149752_Content_20 = {
    Text = "<Shake:Chạy… hơ… chạy mau! Quái vật bất tử… báo thù… hủy diệt… ọc… ọc ọc ọc…>"
  },
  AvgDialog_149752_Content_21 = {
    Text = "Từ cổ họng quái vật trào ra những âm thanh đặc quánh, nó co giật như con cá mắc cạn, nhưng cánh tay lại từ từ giơ lên, vươn về phía gói đồ trong lòng ngươi, từ các khe nối của giáp trụ rỉ ra thứ bùn mềm đang ngọ nguậy."
  },
  AvgDialog_149752_Content_22 = {
    Text = "Là bóng tối. Nó muốn chén thánh."
  },
  AvgDialog_149752_Content_23 = {
    Text = "Không, không được, đây là thứ quan trọng, ta không thể cho ngươi."
  },
  AvgDialog_149752_Content_24 = {
    Text = "Từ chối vô ích, bóng tối chảy xuống từ tường thành, nhanh chóng tụ lại về phía ngươi, ngươi vội vàng ôm chặt gói đồ, quay người chạy sâu hơn vào lòng lâu đài."
  },
  AvgDialog_149752_Content_25 = {
    Text = "Tháp cổng, đại sảnh, nhà nguyện, bậc thang đá xoắn ốc kéo dài xuống lòng đất, lâu đài là một hang rồng nguy hiểm. Không khí ngày càng lạnh hơn, tiếng thở hổn hển và bước chân của ngươi bị vách đá khuếch đại lên nhiều lần, nghe như của một người khác."
  },
  AvgDialog_149752_Content_26 = {
    Text = "Ánh lửa bùng lên ở cuối cầu thang xoắn, ngươi nhìn thấy một bóng dáng quen thuộc."
  },
  AvgDialog_149752_Content_27 = {Text = "Or——"},
  AvgDialog_149752_Content_28 = {
    Text = "Ngươi vừa định vui mừng gọi tên hắn, thì đột nhiên nhận ra nơi này không chỉ có hai người. Quái vật đã lên tiếng trước ngươi."
  },
  AvgDialog_149752_Content_29 = {
    Text = "<Shake:Khọc khọc khọc khọc… Orci…>"
  },
  AvgDialog_149752_Content_3 = {
    Text = "Chia ly là gì? Là khoảnh khắc tiếp theo sau khi đã đến nơi."
  },
  AvgDialog_149752_Content_30 = {
    Text = "Sao ngươi lại trở nên như thế này?"
  },
  AvgDialog_149752_Content_31 = {
    Text = "Diện mạo… của ta?"
  },
  AvgDialog_149752_Content_32 = {
    Text = "Trên bàn bày sẵn rượu ngon và cao lương mỹ vị, bộ đồ ăn bằng bạc lấp lánh dưới ánh nến, nếu không có cái lạnh buốt thấu xương rỉ ra từ kẽ đá, sự bài trí tỉ mỉ này gần như khiến người ta quên mất rằng mình đang ở dưới lòng đất tối tăm."
  },
  AvgDialog_149752_Content_33 = {
    Text = "Vị lãnh chúa gầy gò ngồi một mình sau bàn, hốc mắt trũng sâu, gò má nhô cao, ẩn mình dưới đống lụa là nặng nề, tựa như một con ác long đang ngự trên đống vàng bạc châu báu."
  },
  AvgDialog_149752_Content_34 = {
    Text = "Kỵ sĩ của ngươi từng bước tiến về phía nó, phía sau kéo dài một bóng tối dài. Có lẽ bản thân hắn cũng là một bóng tối. Quần áo hắn rách rưới, diện mạo hung tàn, bước chân không một tiếng động."
  },
  AvgDialog_149752_Content_35 = {
    Text = "Đúng vậy, nếu không tận mắt chứng kiến, ta gần như không dám tin… khọc khọc khọc… vị kỵ sĩ trẻ tuổi nhất của công quốc, lại sa đọa thành quái vật."
  },
  AvgDialog_149752_Content_36 = {
    Text = "Công quốc… đã diệt vong rồi."
  },
  AvgDialog_149752_Content_37 = {
    Text = "Vì ngươi."
  },
  AvgDialog_149752_Content_38 = {
    Text = "Vì chiến tranh, vì dịch bệnh, vì lòng tham của các nước láng giềng, vì sự yếu đuối của chính mình. Có rất nhiều nguyên nhân khiến một công quốc diệt vong, ta chỉ là, khọc khọc, nguyên nhân nhỏ nhoi nhất trong số đó."
  },
  AvgDialog_149752_Content_39 = {
    Text = "<Shake:Ngươi… phản bội công quốc… câu kết ngoại địch… bán đứng… thần dân…>"
  },
  AvgDialog_149752_Content_4 = {
    Text = "Cái chết là gì? Là ngày mai không có lời tạm biệt."
  },
  AvgDialog_149752_Content_40 = {
    Text = "<Shake:Kẻ phản bội… đáng chết.>"
  },
  AvgDialog_149752_Content_41 = {
    Text = "Đúng vậy, đúng vậy, như ngươi thấy đó, hậu quả đã giáng xuống đầu ta rồi. Thời gian của ta không còn nhiều nữa, khọc khọc khọc khọc."
  },
  AvgDialog_149752_Content_42 = {
    Text = "Dịch bệnh không tha cho ta, Orci. Cái chết, nó đối xử bình đẳng với tất cả, kiên nhẫn chờ đợi ở đầu bên kia cây cầu, không ai thoát khỏi được… ngoại trừ ngươi."
  },
  AvgDialog_149752_Content_43 = {
    Text = "Hãy nói cho ta biết, ngươi đã giao kèo gì với ác quỷ?"
  },
  AvgDialog_149752_Content_45 = {
    Text = "Cái giá để trốn tránh cái chết, chỉ có thể nặng nề hơn cái chết mà thôi. Kỵ sĩ tử thần… trở thành đao phủ của nó, đó là điều ngươi đã ước nguyện, hay là hình phạt ngươi phải chịu?"
  },
  AvgDialog_149752_Content_46 = {
    Text = "Orci, vị kỵ sĩ trung thành nhất, mộ đạo nhất của công quốc, hừ, <Shake:khọc khọc khọc khọc khọc…>"
  },
  AvgDialog_149752_Content_47 = {
    Text = "Ta là kẻ phản bội đáng chết, còn ngươi thì sao?"
  },
  AvgDialog_149752_Content_48 = {Text = "!!"},
  AvgDialog_149752_Content_49 = {
    Text = "Tia sét vô hình giáng xuống hiệp sĩ của ngươi, ghim chặt hắn tại chỗ. Những bóng tối trong góc khuất run rẩy dữ dội, vui mừng hay phẫn nộ, chúng đã không còn kiên nhẫn được nữa."
  },
  AvgDialog_149752_Content_5 = {
    Text = "Lãng quên là gì?"
  },
  AvgDialog_149752_Content_50 = {
    Text = "Ta đã phản bội Đại Công, nhưng còn ngươi, ngươi và công chúa của ngươi, các ngươi đã phản bội Thần."
  },
  AvgDialog_149752_Content_51 = {
    Text = "Ngươi còn nhớ không… ngươi còn dám nhắc đến…"
  },
  AvgDialog_149752_Content_52 = {
    Text = "<Red:Công chúa phù thủy>, khục khục khục, thật mỉa mai thay, trò bịp của nàng ta cuối cùng cũng bị lộ, vậy mà đến cái tên cũng chẳng còn ai nhớ. Ta đã nói từ lâu rồi, dâng nàng ta ra, chiến lửa sẽ tắt, công quốc cũng không đến nỗi diệt vong."
  },
  AvgDialog_149752_Content_53 = {
    Text = "Ngươi biết nàng ta đã kéo đến thứ gì, ngươi rất rõ. Lời nguyền… chiến tranh vì đó mà bắt đầu, cũng vì đó mà kết thúc. Nhờ ơn nàng ta, công quốc @3 đã trở thành một nơi bị lãng quên."
  },
  AvgDialog_149752_Content_54 = {
    Text = "Câm miệng! Ngươi… không xứng… nhắc đến nàng!"
  },
  AvgDialog_149752_Content_55 = {
    Text = "Cây thương vô định chặt đứt chiếc bàn dài, chén đĩa rơi vỡ tứ tung, bữa tiệc giả tạo tan vỡ thành mảnh, lộ ra bộ mặt thật hỗn độn."
  },
  AvgDialog_149752_Content_56 = {
    Text = "Bóng tối vươn ra những xúc tu nhầy nhụa, tham lam nuốt chửng tất cả những gì chạm phải, đầm lầy trào ra từ chốn không ánh sáng, và thế giới bắt đầu chìm xuống."
  },
  AvgDialog_149752_Content_57 = {
    Text = "Cái chết… rồi bị lãng quên… như thể chưa từng xảy ra. Đó là hậu quả của kẻ phản bội Thần."
  },
  AvgDialog_149752_Content_58 = {
    Text = "Chính nàng ta đã biến ngươi thành hình dạng này phải không… kéo cả công quốc vào hư không, rồi để lại một con rối đầy hận thù, gieo rắc cái chết thực sự lên khắp đại địa. Thực thi sứ mệnh như vậy, ngươi gọi đó là trung thành sao?"
  },
  AvgDialog_149752_Content_59 = {
    Text = "Orci… rốt cuộc ngươi trung thành với ai?"
  },
  AvgDialog_149752_Content_60 = {
    Text = "<Shake:Không… không… công chúa không phải… ục… ục ục…>"
  },
  AvgDialog_149752_Content_61 = {
    Text = "Hiệp sĩ của ngươi đau đớn ôm chặt lấy đầu, bóng tối trào ra từ ngực, từ tai, từ khóe mắt. Sự hành hạ ngày đêm không ngừng của ác quỷ khiến hắn kiệt sức, hắn không còn phát ra được tiếng nào, như một con búp bê đất sét đang tan chảy trong dòng nước đen."
  },
  AvgDialog_149752_Content_62 = {
    Text = "Vào lúc cả hai đều không để ý, lãnh chúa xoay chiếc xe lăn sang một bên, trên vách đá phía sau hóa ra ẩn giấu một lỗ châu mai to bằng nắm đấm. Một bóng đen thoáng qua như rắn, kèm theo một tiếng bịch, cây thương sắt xuyên thấu lồng ngực hiệp sĩ của ngươi."
  },
  AvgDialog_149752_Content_63 = {
    Text = "<Big:Orci!!!>"
  },
  AvgDialog_149752_Content_64 = {
    Text = "<Shake:Khục khục khục khục…> Quái vật bò ra từ nấm mồ, tốt nhất hãy mau quay về nấm mồ đó đi."
  },
  AvgDialog_149752_Content_65 = {
    Text = "Ngươi và con quái vật nhỏ của ngươi, hãy cùng nhau chôn vùi ở đây đi."
  },
  AvgDialog_149752_Content_66 = {
    Text = "Vài tên vệ sĩ vũ trang đầy đủ xuất hiện từ đường hầm bí mật, khiên và kiếm lấp lánh ánh sáng hiểm ác, cái bẫy cuối cùng cuối cùng cũng lộ diện."
  },
  AvgDialog_149752_Content_7 = {
    Text = "……………"
  },
  AvgDialog_149752_Content_8 = {
    Text = "<Red:Lời nguyền.>"
  },
  AvgDialog_149752_Content_9 = {
    Text = "Lời nguyền. Dịch bệnh. Trừng phạt. Hố rỗng bị sâu đục khoét. Lòng sông khô cạn nứt vỡ. Mục ruỗng trong im lặng. Phong hóa. Chìm xuống. Ánh mắt đã cạn kiệt. Từ câu chuyện phai nhạt thành bóng tối. Cái chết cuối cùng."
  },
  AvgDialog_149753_Content_1 = {
    Text = "Chén Thánh"
  },
  AvgDialog_149753_Content_10 = {
    Text = "Những gì ta làm không có điều nào là hành động của một hiệp sĩ, ngươi đã thấy rồi đó."
  },
  AvgDialog_149753_Content_11 = {
    Text = "Tại sao? Hiệp sĩ phải chiến đấu với quái vật, đó là trách nhiệm của ngươi, ngươi đã làm rất tốt."
  },
  AvgDialog_149753_Content_12 = {
    Text = "Hơn nữa ngươi đang tìm gì đó phải không? Ta nhìn ra rồi. Ngươi tìm từng nơi một, từ khi vào thành, đã mấy ngày rồi. Quái vật cũng cướp đi thứ gì đó của ngươi sao?"
  },
  AvgDialog_149753_Content_14 = {
    Text = "Đến rồi."
  },
  AvgDialog_149753_Content_15 = {
    Text = "Ánh nến vàng ấm áp quyến rũ tràn ngập bốn bức tường, cánh cửa gỗ sồi ngăn cách gió lạnh, đối với những kẻ lang thang không nhà, kho lương của tu viện mở cửa trong đêm mưa thậm chí có thể cứu mạng người."
  },
  AvgDialog_149753_Content_16 = {
    Text = "Nhưng ngươi sẽ không bị ảo tượng đánh lừa, ngươi nhớ chúng. Những kẻ cầm giá nến đi lại qua lại đó, áo choàng đen, dây chuyền đồng thau, tự xưng là mục sư nhưng thực chất là đao phủ, chúng là quái vật trong số những quái vật."
  },
  AvgDialog_149753_Content_17 = {
    Text = "<Small:Tại sao chúng ta lại đến đây… thứ ngươi tìm có ở đây không?>"
  },
  AvgDialog_149753_Content_18 = {
    Text = "Ở lại đây chờ ta, đừng đi theo."
  },
  AvgDialog_149753_Content_19 = {
    Text = "<Big:Cái gì?! Không! Tuyệt đối không!>"
  },
  AvgDialog_149753_Content_2 = {
    Text = "<Shake:Con không biết, con không biết đó là — không, không không không, xin ngài, xin ngài tha thứ —>"
  },
  AvgDialog_149753_Content_20 = {
    Text = "<Big:Ta không ở lại đây, ta tuyệt đối không ở lại đây! Ta muốn đi cùng ngươi!>"
  },
  AvgDialog_149753_Content_21 = {
    Text = "Có chuyện gì vậy? Cháu ơi, cháu có cần giúp đỡ không?"
  },
  AvgDialog_149753_Content_22 = {
    Text = "Vâng, xin hãy trông chừng cô ấy, đừng để cô ấy bỏ trốn."
  },
  AvgDialog_149753_Content_23 = {
    Text = "Ồ… muộn thế này rồi, lại còn đang mưa to, cháu vội đi đâu vậy? Đợi mặt trời mọc rồi hãy đi, đừng bỏ em gái cháu một mình."
  },
  AvgDialog_149753_Content_24 = {
    Text = "Khi trời sáng ta sẽ đến đón cô ấy."
  },
  AvgDialog_149753_Content_25 = {
    Text = "Nếu cháu nhất quyết vậy thì thôi, được rồi, được rồi. Đứa trẻ tội nghiệp, ướt hết cả người rồi, lại đây, lại đây, để ta lau mặt cho cháu."
  },
  AvgDialog_149753_Content_26 = {
    Text = "Cậu bị giam cầm, không thể cử động, tấm vải lanh khô ráp cọ xát vào má cậu, cậu không biết lúc nào nó sẽ bịt kín miệng mũi cậu."
  },
  AvgDialog_149753_Content_27 = {
    Text = "Nỗi sợ hãi bóp nghẹt lồng ngực cậu, cậu không thể thở, chỉ có thể gào thét."
  },
  AvgDialog_149753_Content_28 = {
    Text = "<Shake:Quay lại đây! Anh là hiệp sĩ của em, anh phải bảo vệ em, không được bỏ em lại — anh đã hứa với em mà!>"
  },
  AvgDialog_149753_Content_29 = {
    Text = "<Shake:Xin anh, em sẽ không gây rắc rối, cho em đi cùng anh!>!"
  },
  AvgDialog_149753_Content_3 = {Text = "À!"},
  AvgDialog_149753_Content_30 = {
    Text = "Tiếng gào thét khản cổ của cậu kéo ra vô số đôi mắt, có cái như mắt bọ cánh cứng, có cái như mắt dê, có cái như mắt cú vọ."
  },
  AvgDialog_149753_Content_31 = {
    Text = "Chúng nhìn chằm chằm vào cậu, như thể chỉ riêng cậu là không có mắt."
  },
  AvgDialog_149753_Content_32 = {
    Text = "<SmallShake:Đừng… đừng đi… anh đã hứa mà…>"
  },
  AvgDialog_149753_Content_33 = {
    Text = "<SmallShake:Xin anh, đừng bỏ em lại…>"
  },
  AvgDialog_149753_Content_34 = {
    Text = "Ta đổi ý rồi, để cô bé đi cùng ta."
  },
  AvgDialog_149753_Content_35 = {
    Text = "Cậu ngẩng đầu lên đột ngột, hiệp sĩ của cậu không biết từ lúc nào đã quay trở lại, che khuất toàn bộ ánh mắt của những con quái vật ra phía sau lưng."
  },
  AvgDialog_149753_Content_36 = {
    Text = "Nhưng ngươi định đưa cô bé đi đâu? Trong thành không còn nhiều chỗ trú mưa, lại cũng không thích hợp cho trẻ con vào."
  },
  AvgDialog_149753_Content_37 = {
    Text = "Nơi ta muốn đến không ở trong thành."
  },
  AvgDialog_149753_Content_38 = {
    Text = "Ngoài thành thì càng không có — à! Chẳng lẽ ngươi muốn đến trang viên đó?"
  },
  AvgDialog_149753_Content_39 = {
    Text = "Trang viên đó thì sao?"
  },
  AvgDialog_149753_Content_4 = {
    Text = "Tiếng thét thảm bị cơn mưa xối xả dập tắt, hòa cùng máu chảy vào rãnh thoát nước dưới chân tường, cùng bùn lầy, phân ngựa, lá rau mà mục rữa, cho đến khi bị con hẻm tối nuốt chửng."
  },
  AvgDialog_149753_Content_40 = {
    Text = "Nơi đó, nơi đó… thôi, các ngươi cũng là người chạy nạn đến đây phải không? Đứa trẻ, đừng đến gần chỗ đó."
  },
  AvgDialog_149753_Content_41 = {
    Text = "Vị lãnh chúa đó, ông ta từng là người tốt, nhưng chiến tranh, dịch bệnh, tai họa như sóng triều rút rồi lại dâng, con người cũng trở nên không còn ra người nữa. Ai cũng nói ông ta điên rồi. Người trong thành ngày càng ít đi, những kẻ đến xin bánh mì, chẳng ai quay trở về."
  },
  AvgDialog_149753_Content_42 = {
    Text = "Nguyện Chúa tha thứ… ai cũng nói ông ta đang lén lút ăn thịt người."
  },
  AvgDialog_149753_Content_43 = {
    Text = "Quái vật sẽ ăn thịt người, cậu đã biết điều đó từ lâu, nên chẳng hề ngạc nhiên, cũng không sợ hãi… ít nhất là không sợ đến vậy. Cậu có hiệp sĩ của mình."
  },
  AvgDialog_149753_Content_44 = {
    Text = "Đi sát theo ta, nơi này có gì đó không ổn."
  },
  AvgDialog_149753_Content_45 = {
    Text = "Được, được."
  },
  AvgDialog_149753_Content_46 = {
    Text = "Trang viên rộng lớn trống rỗng hoàn toàn, không có lính canh, cũng không có người hầu, như thể đã bị bỏ hoang từ lâu, trong hành lang dài hẹp chỉ có tiếng bước chân cố ý đi nhẹ của hai người."
  },
  AvgDialog_149753_Content_47 = {
    Text = "Vậy thì… rốt cuộc cậu đang tìm gì? Quan trọng với cậu lắm sao? Nói cho tôi biết nó trông như thế nào, tôi cũng có thể giúp cậu tìm."
  },
  AvgDialog_149753_Content_48 = {
    Text = "Một chiếc cốc vàng."
  },
  AvgDialog_149753_Content_49 = {
    Text = "Cốc vàng? Ý là làm bằng vàng? Ồ, nó to bao nhiêu, cao bao nhiêu? Dùng để đựng gì? Vàng trông như thế nào, có phải giống mặt trăng không, ban đêm sẽ phát sáng?"
  },
  AvgDialog_149753_Content_5 = {
    Text = "Xác người mềm nhũn đổ xuống đất, ánh lạnh của kim loại lóe lên rồi tắt, kẻ sát nhân kéo chặt áo choàng, bước nhanh ra ngoài, tiếng chân cũng tan biến trong mưa."
