  },
  AvgDialog_149753_Content_68 = {
    Text = "Trong câu nói đó chắc chắn ẩn chứa một phép thuật mạnh mẽ nào đó, vì hiệp sĩ của cậu đột nhiên đông cứng như một pho tượng đá, lại như thể lần đầu tiên sống lại. Cái bóng của anh ta run rẩy không ngừng."
