  AvgDialog_149753_Content_76 = {Text = "\"Khặc.\""},
  AvgDialog_149753_Content_77 = {
    Text = "Lời chưa nói hết, nhưng đã không thể tiếp tục, bóng tối bẻ gãy cổ nó. Chiếc đầu phình to như túi gai buộc chặt, rũ xuống một bên không còn sức lực, qua những lỗ thủng lộ ra hai con mắt gỉ sét, vẫn đăm đăm nhìn vào hư không."
