  AvgDialog_149754_Content_36 = {
    Text = "Nước biển thủy triều dâng ngập qua đầu gối, bạn vất vả lội trong bóng tối, những mỏm đá nhọn cắt rách bắp chân, vết thương bị nước biển ngâm tê dại, bạn nghiến răng, không kêu đau."
