  AvgDialog_149754_Content_41 = {
    Text = "Hôm qua, là câu chuyện của hôm nay, hôm nay là, câu chuyện của ngày mai. Có những thứ, đã biến mất, có những thứ, sẽ tiếp tục. Nhưng không thể, không có câu chuyện."
  },
  AvgDialog_149754_Content_42 = {
    Text = "Vì vậy, hãy đi tìm, đảo Táo đi. Đi, hù, hù……đi hoàn thành, câu chuyện của chúng ta."
  },
  AvgDialog_149754_Content_5 = {
    Text = "Ánh vàng lăn tròn, bay vút qua đầm lầy bóng tối, đập vào vách đá, nảy lên mặt đất hai lần, rồi lăn thẳng đến chân lãnh chúa không lệch một chút."
  },
  AvgDialog_149754_Content_6 = {
    Text = "Ngươi thấy ông ta giơ tay ngăn vệ sĩ, đích thân cúi xuống nhặt chiếc chén vàng nhỏ bé lên, dùng ngón cái vuốt theo hoa văn trên thành chén, như thể nhớ ra điều gì đó, rồi quay đầu nhìn lại với ánh mắt đầy chế nhạo."
