  AvgDialog_149754_Content_8 = {
    Text = "… Trước khi lâu đài hoàn toàn sụp đổ thành đống đổ nát, chôn vùi bóng tối, ác long và di vật, hiệp sĩ của ngươi đã kéo ngươi trốn vào đường hầm bí mật."
  },
  AvgDialog_149754_Content_9 = {
    Text = "Anh ta đã kiệt sức, thậm chí không thể đứng dậy nổi, ngươi nắm chặt cánh tay anh ta, khó nhọc bước từng bước, như đang vác một bao lúa mì nặng trĩu."
  },
  AvgDialog_149755_Content_1 = {
    Text = "Đảo Táo"
  },
  AvgDialog_149755_Content_10 = {
    Text = "Vết thương trên chân mãi không lành, ngược lại càng đau hơn theo những ngày mưa dầm liên tiếp, từ đầu gối trở xuống sưng phồng như củ cà rốt, không thể bước đi nổi. Mấy ngày qua, đều là Orci cõng bạn vượt núi băng rừng."
  },
  AvgDialog_149755_Content_100 = {
    Text = "Thưa Công chúa điện hạ, Người không cần khóc vì thần. Quái vật đã quá nhiều rồi, điều duy nhất thần có thể làm cho Người là bảo vệ thiên đường thuộc về con người, thuộc về Người, đó là trách nhiệm của thần, cũng là sự chuộc tội của thần."
