  AvgDialog_149755_Content_103 = {
    Text = "Bóng tối thay thế máu phun trào ra, người bước vào dòng lũ gầm thét kia, chớp mắt đã mất dạng, nhưng bóng tối vẫn chưa tan biến."
  },
  AvgDialog_149755_Content_104 = {
    Text = "Bóng tối uốn lượn, bóng tối cuộn trào, bóng tối tụ lại thành khiên, thành tường, cuối cùng thành một con đê khổng lồ, ngươi chằm chằm nhìn vào bóng tối thăm thẳm nhất, cho đến khi xe bò rẽ qua một khúc cua, ngươi không còn nhìn thấy mặt sông nữa."
  },
  AvgDialog_149755_Content_105 = {
    Text = "Kỵ sĩ của ngươi từ đó bặt vô âm tín, hắn chỉ hoàn thành được một nửa lời hứa, nhưng lại để lại một câu di ngôn vô cùng xảo quyệt, khiến ngươi dù khóc mà chìm vào giấc ngủ, vẫn sẽ mong chờ ngày mai."
  },
  AvgDialog_149755_Content_106 = {
    Text = "Bởi vì lúc đó sẽ có mặt trời mới mọc lên, ngày nào cũng vậy, chưa bao giờ thay đổi."
  },
  AvgDialog_149755_Content_11 = {
    Text = "Cầm lấy, vừa hái xong."
  },
  AvgDialog_149755_Content_12 = {
    Text = "Như thể để an ủi, anh ấy nhét một quả vào tay bạn, bạn mơ màng cắn một miếng, mãi đến khi một vị chua chát lan ra từ chân răng, bạn mới nhận ra đó là thứ gì."
  },
  AvgDialog_149755_Content_13 = {
    Text = "……Táo?"
  },
  AvgDialog_149755_Content_14 = {
    Text = "Ừ, lúc nãy đi qua một khu rừng táo."
  },
  AvgDialog_149755_Content_15 = {
    Text = "Táo… Đảo Táo, chúng ta đến nơi rồi sao?"
  },
  AvgDialog_149755_Content_16 = {
    Text = "Sắp rồi."
  },
  AvgDialog_149755_Content_17 = {
    Text = "Anh ấy tháo băng vải ra, đắp thuốc thảo dược lên vết thương, rồi lại quấn lại từng vòng từng vòng. Bạn nhìn chăm chú vào nét mặt anh ấy, cảm thấy đó không phải là sự mong đợi."
  },
  AvgDialog_149755_Content_18 = {
    Text = "Bạn còn muốn hỏi đến tận cùng, nhưng bị tiếng chó sủa từ xa vọng lại ngắt lời."
  },
  AvgDialog_149755_Content_19 = {
    Text = "Khoan đã, đừng chạy nhanh thế! Ngươi định đi đâu? Đó không phải đường về làng— Á!"
  },
  AvgDialog_149755_Content_2 = {
    Text = "……tỉnh……"
  },
  AvgDialog_149755_Content_20 = {
    Text = "Con chó chăn cừu hung hăng lao ra từ bụi cây, sủa inh ỏi xua đuổi kẻ không mời mà đến, cô gái chạy theo sau nhìn thấy hai người, không nhịn được mà thét lên, chiếc giỏ liễu trên tay cũng rơi xuống đất."
  },
  AvgDialog_149755_Content_21 = {
    Text = "Đó là Orci, những vết sẹo đen bẩn thỉu loang đầy khuôn mặt anh, trông như một con búp bê vải bị xé nát rồi khâu vá cẩu thả, gợi lên trong lòng người ta bao truyền thuyết kinh dị."
  },
  AvgDialog_149755_Content_22 = {
    Text = "Anh nhìn cô gái trong im lặng, rồi đứng dậy đội mũ trùm đầu lên."
  },
  AvgDialog_149755_Content_23 = {
    Text = "Chúng ta đi ngay bây giờ."
  },
  AvgDialog_149755_Content_24 = {
    Text = "Không… không phải, tôi không phải— Xin hãy đợi một chút!"
  },
  AvgDialog_149755_Content_25 = {
    Text = "Orci vừa cõng em trên lưng bước đi vài bước, cô gái đã hốt hoảng chạy theo."
  },
  AvgDialog_149755_Content_26 = {
    Text = "Đừng đi! Tôi không có ý đó, trong làng còn nhiều người bệnh lắm, để tôi dẫn các anh đến!"
  },
  AvgDialog_149755_Content_27 = {Text = "Bệnh?"},
  AvgDialog_149755_Content_28 = {
    Text = "Đúng, toàn là người mắc bệnh phong. Ban đầu chỉ có người bệnh phong thôi, sau đó quân đội kéo đến, tàn phá vô số làng mạc, nhưng chưa bao giờ dám đến gần làng phong, nên những người mất nhà mới chạy đến đây trú ẩn, tôi cũng vậy."
  },
  AvgDialog_149755_Content_29 = {
    Text = "Đừng lo, mọi người đã quen rồi. Thực ra ngoài vẻ ngoài khác biệt, chúng tôi chẳng khác gì nhau, cũng ăn cơm, ngủ nghỉ, làm việc như thường… Bệnh phong còn không đáng sợ bằng quân đội, quen rồi sẽ thấy ổn thôi."
  },
  AvgDialog_149755_Content_3 = {
    Text = "……trời mưa……nghỉ ngơi……tỉnh dậy đi……"
  },
  AvgDialog_149755_Content_30 = {
    Text = "Xin lỗi, tôi không phải sợ anh, chỉ là tôi chưa từng thấy… Xin lỗi! Giỏ táo xanh này tặng anh, tôi đã chọn kỹ rồi, đảm bảo to nhất và ngọt nhất!"
  },
  AvgDialog_149755_Content_31 = {
    Text = "Thiên đường trông sẽ như thế nào?"
  },
  AvgDialog_149755_Content_32 = {
    Text = "Không có quái vật, không có tuyệt vọng, không có nỗi kinh hoàng khó nói thành lời, không có những ánh mắt ẩn nấp trong bóng tối, trước khi ngủ không phải sợ rằng sẽ không thức dậy được nữa, mỗi ngày đều được uống canh nóng."
  },
  AvgDialog_149755_Content_33 = {
    Text = "Em không biết còn nơi nào giống thiên đường hơn nơi này."
  },
  AvgDialog_149755_Content_34 = {
    Text = "…Xong rồi."
  },
  AvgDialog_149755_Content_35 = {
    Text = "Lưỡi dao sắc bén rạch vào chỗ mưng mủ, từng chút một cắt bỏ những mảng thịt thối rữa, thanh sắt nung đỏ ấn lên vết thương máu chảy không ngừng, cơn đau dữ dội khiến em nghiến răng thét lên, mồ hôi đầm đìa."
  },
  AvgDialog_149755_Content_36 = {
    Text = "Xong rồi. Cục vải nhét trong miệng được lấy ra, em dốc hết sức thở, gần như nuốt cả không khí vào bụng."
  },
  AvgDialog_149755_Content_37 = {
    Text = "Lần này khác, em biết. Họ làm vậy để cứu em, và hiệp sĩ của em cũng đang ở bên cạnh."
  },
  AvgDialog_149755_Content_38 = {
    Text = "Thuốc, mang về sắc uống. Sáng một lần, tối một lần."
  },
  AvgDialog_149755_Content_39 = {
    Text = "Vâng, cảm ơn."
  },
  AvgDialog_149755_Content_4 = {
    Text = "Có ai đó nhẹ nhàng đẩy bạn dậy, trong lúc ý thức còn mơ màng, bạn nghe thấy tiếng mưa rơi lách tách."
  },
  AvgDialog_149755_Content_40 = {
    Text = "Anh lấy ra vài đồng tiền để trả công, nhưng người thợ cạo xua tay từ chối. Ở nơi cách biệt với thế giới bên ngoài, giá trị của đồng tiền ngoài kia chẳng có nghĩa lý gì, người ở đây không sống vì điều đó."
  },
  AvgDialog_149755_Content_41 = {
    Text = "<Small:Trời quang rồi…>"
  },
  AvgDialog_149755_Content_42 = {
    Text = "<Small:Orci, tôi muốn đến rừng táo.>"
  },
  AvgDialog_149755_Content_43 = {
    Text = "Ngươi cần nghỉ ngơi."
  },
  AvgDialog_149755_Content_44 = {
    Text = "Hãy đưa ta đến đó, ta có một phát hiện trọng đại… muốn nói với ngươi."
  },
  AvgDialog_149755_Content_45 = {
    Text = "Đến rồi. Phát hiện trọng đại gì vậy?"
  },
  AvgDialog_149755_Content_46 = {
    Text = "Hà… ta phát hiện ra, nơi này chính là Đảo Táo, chúng ta đã tìm thấy rồi."
  },
  AvgDialog_149755_Content_47 = {
    Text = "Người kỵ sĩ của ngươi đặt ngươi lên một khúc gỗ đổ ngang, quỳ gối xuống, cẩn thận nâng đỡ chân bị thương của ngươi. Ánh mắt anh chuyên chú và lo lắng, rõ ràng sự thật mà ngươi vừa bừng tỉnh nhận ra không khiến anh kinh ngạc."
  },
  AvgDialog_149755_Content_48 = {
    Text = "Nhưng đây không phải đảo."
  },
  AvgDialog_149755_Content_49 = {
    Text = "Chẳng ai nói rằng đảo nhất định phải ở giữa biển cả? Chỉ cần không liền với bên ngoài, thì đó là đảo rồi."
  },
  AvgDialog_149755_Content_5 = {
    Text = "Mưa lại rơi rồi, mưa chưa bao giờ thực sự ngừng."
  },
  AvgDialog_149755_Content_50 = {
    Text = "Hơn nữa nơi đây còn có tiên linh."
  },
  AvgDialog_149755_Content_51 = {
    Text = "Tiên linh?"
  },
  AvgDialog_149755_Content_52 = {
    Text = "Đúng vậy, trong làng có rất nhiều tiên linh. Có người mang mặt sư tử, có người phủ vảy cá, lại có người lột xác như rắn, họ chính là những tiên linh sống trong cõi tiên."
  },
  AvgDialog_149755_Content_53 = {
    Text = "Là tiên linh… không phải quái vật?"
  },
  AvgDialog_149755_Content_54 = {
    Text = "Tất nhiên không phải! Tiên linh và quái vật, sao có thể giống nhau được?"
  },
  AvgDialog_149755_Content_55 = {
    Text = "Quái vật ăn thịt người, tìm đủ mọi cách để ăn thịt người, đôi khi trực tiếp cầm dao giết rồi ăn, đôi khi bịa đặt dối trá, vây nhốt người lại, từng nhát dao cắt thịt mà ăn."
  },
  AvgDialog_149755_Content_56 = {
    Text = "Không chỉ tự ăn, còn nấu thành canh, làm thành thịt muối, nghiền thành cháo, đem cho người ăn. Khắp nơi đều là thịt người, không ăn thì chết đói, nhưng chỉ cần đã ăn thịt người, sẽ biến thành quái vật, vì vậy quái vật ngày càng nhiều thêm."
  },
  AvgDialog_149755_Content_57 = {
    Text = "Người không ăn thịt người, tiên linh cũng không ăn thịt người. Trên Đảo Táo, họ trong sạch."
  },
  AvgDialog_149755_Content_58 = {
    Text = "Vậy còn ta thì sao? Ta không phải người, cũng không phải tiên linh. Tay ta nhuốm đầy máu, trong thân thể ta trú ngụ một ác ma, ngươi đã tận mắt thấy hình dạng của nó."
  },
  AvgDialog_149755_Content_59 = {
    Text = "Tại sao không sợ?"
  },
  AvgDialog_149755_Content_6 = {
    Text = "Khu rừng che giấu những kẻ lưu vong đang trốn chạy, tội ác của quái vật tắm máu lâu đài đã truyền đến tai kẻ cầm quyền, lệnh truy nã dán khắp mọi thị trấn, kỵ sĩ đoàn của giáo hội và lính đánh thuê đều đã xuất động, các bạn buộc phải chạy trốn ngày đêm không ngừng nghỉ."
  },
  AvgDialog_149755_Content_60 = {
    Text = "Tại sao phải sợ? Từ lần đầu gặp anh ngươi đã biết, anh nhất định là một kỵ sĩ. Xuyên qua bóng tối vây quanh không tan, ngươi vẫn có thể nhìn thấy hình dạng của anh với tư cách một kỵ sĩ, rõ ràng đến vậy, chắc chắn đến vậy, như thể ngươi đã từng gặp anh ở đâu đó."
  },
  AvgDialog_149755_Content_61 = {
    Text = "Để trở thành một kỵ sĩ thực sự cần có gì? Trung thành, dũng cảm, lòng trắc ẩn, hy sinh, và còn…"
  },
  AvgDialog_149755_Content_62 = {
    Text = "Lễ phong tước của chúa công."
  },
  AvgDialog_149755_Content_63 = {
    Text = "Hắng hắng… Vậy thì, ta tuyên bố, nhân danh công chúa, ta phong ngươi làm hiệp sĩ."
  },
  AvgDialog_149755_Content_64 = {
    Text = "Ngươi đã đánh bại quái vật, giành được chén thánh, chống lại ác ma, bảo vệ ta. Ngươi đã hoàn thành lời hứa của mình, đưa công chúa của ngươi đến đảo Táo."
  },
  AvgDialog_149755_Content_65 = {
    Text = "Dù ngươi từng là ai, trong câu chuyện của chúng ta, ngươi là một hiệp sĩ, và không có công chúa nào sợ hãi hiệp sĩ của mình."
  },
  AvgDialog_149755_Content_66 = {
    Text = "Ngươi mãi mãi là hiệp sĩ của ta."
  },
  AvgDialog_149755_Content_67 = {
    Text = "Hiệp sĩ của ngươi đứng sững người, một tay siết chặt tấm áo choàng, như thể muốn ẩn mình vào bóng tối rộng lớn đó. Áo choàng che khuất dấu vết của bóng tối, chỉ có anh mới biết bên dưới lớp ngụy trang ấy là điều tồi tệ đến nhường nào."
  },
  AvgDialog_149755_Content_68 = {
    Text = "Những cành cây mảnh mai còn đọng sương mưa, khẽ đặt lên vai anh. Khát vọng xa xôi tưởng đã gần như bị lãng quên bỗng chốc trở thành hiện thực, thứ khiến linh hồn anh run rẩy lại không phải là niềm vui."
  },
  AvgDialog_149755_Content_69 = {
    Text = "Mà là Sợ hãi."
  },
  AvgDialog_149755_Content_7 = {
    Text = "Phía trước có một ngôi làng, ta đi đổi ít thức ăn và thuốc, ngươi nghỉ ngơi ở đây, đợi mưa tạnh rồi chúng ta lại đi."
  },
  AvgDialog_149755_Content_70 = {
    Text = "Ngọn lửa sợ hãi bốc lên từ hố thẳm không đáy, dưới chân, trên đầu, trong đôi mắt kinh hoàng sau khe hở. Bỏng rát, ấm nóng, phun trào từ cổ gãy, tuôn chảy từ lồng ngực. Ngọn lửa vặn vẹo đến vậy, bóng tối cũng theo đó mà điên cuồng. Lửa và bóng tối vốn là một."
  },
  AvgDialog_149755_Content_71 = {
    Text = "Đó là một cuộc thảm sát, không chút danh dự, không chút công lý, như nhau với tất cả mọi người. Cái kết đẫm máu xé toạc lớp son phấn của những lời hoa mỹ, cái chết chỉ là cái chết. Anh không nhớ mình đã sống sót như thế nào, có lẽ anh chưa từng sống sót."
  },
  AvgDialog_149755_Content_72 = {
    Text = "Quái vật sa ngã, oan hồn báo thù, cuộc truy tìm của anh tựa như ôm củi chữa lửa, Kẻ Lạc Đường không thể cưỡng lại mà trượt dài về phía tận cùng, chưa bao giờ tin rằng mình có thể được cứu rỗi."
  },
  AvgDialog_149755_Content_73 = {
    Text = "<Shake:Nhưng mà… nhưng mà…>"
  },
  AvgDialog_149755_Content_74 = {
    Text = "Orci, Orci? Này, ngươi có đang nghe không, ta nói xong rồi, đến lượt ngươi rồi đấy."
  },
  AvgDialog_149755_Content_76 = {
    Text = "Vâng, tôi nguyện ý."
  },
  AvgDialog_149755_Content_77 = {
    Text = "Nhân danh quê hương đã mất của tôi, Orci, con trai của Gia đình Danske, xin tuyên thệ trung thành và kính ngưỡng với Người."
  },
  AvgDialog_149755_Content_78 = {
    Text = "Tôi dâng lên Người tấm khiên và ngọn giáo của mình, cùng với đức tin đã bị tôi làm ô uế, nỗi sợ hãi vĩnh cửu của tôi, và trái tim không còn nguyên vẹn. Tôi từng đánh mất tên mình trong đêm dài, chính tiếng gọi của Người đã thắp sáng bình minh."
  },
  AvgDialog_149755_Content_79 = {
    Text = "Kẻ bội thề không còn xứng được gọi là người trung tín, nhưng nếu ánh mắt Người vẫn còn muốn dừng lại, thì tôi sẽ thuộc về Người, cho đến hơi thở cuối cùng của cuộc đời."
  },
  AvgDialog_149755_Content_8 = {
    Text = "<Small:Biết rồi… mau quay lại nhé.>"
  },
  AvgDialog_149755_Content_80 = {
    Text = "Câu chuyện không phải lúc nào cũng có khởi đầu rực rỡ, cũng có thể bắt đầu từ bờ bên kia của tuyệt vọng."
  },
  AvgDialog_149755_Content_81 = {
    Text = "Dù tận cùng có đứng sừng sững mãi mãi, gieo xuống bóng tối nặng nề lên vạn vật, trước khi đến nơi đó, các ngươi vẫn có quyền tự do chọn điều gì sẽ trở thành số phận."
  },
  AvgDialog_149755_Content_82 = {
    Text = "Làn gió nhẹ, ánh nắng, hương thơm của táo chín, sương mù tựa mây trắng bốc lên từ rừng cây, thế giới đẹp như tranh vẽ, ngươi cười vui vẻ, như thể đang đón nhận một kết thúc viên mãn."
  },
  AvgDialog_149755_Content_83 = {
    Text = "Nhưng ngươi biết câu chuyện vẫn sẽ tiếp tục, nó luôn luôn tiếp tục."
  },
  AvgDialog_149755_Content_84 = {
    Text = "<Big:Còn bao nhiêu người chưa thức dậy? Mau đi gọi họ, lũ lụt sắp đến rồi!>"
  },
  AvgDialog_149755_Content_85 = {
    Text = "Màn đêm tiếp thêm sức mạnh cho cơn mưa dữ dội, những hạt mưa như đá cuội đập xuống lộp bộp, dòng nước đục ngầu gầm thét tràn lên hai bờ, nước đã ngập quá đầu gối."
  },
  AvgDialog_149755_Content_86 = {
    Text = "Bóng người chạy qua chạy lại, la hét vang trời, ra sức đập vào từng cánh cửa, nhưng các tinh linh cử động chậm chạp, ngã xuống rồi không thể đứng dậy, không thể tự mình lội qua những vũng nước lồi lõm."
  },
  AvgDialog_149755_Content_87 = {
    Text = "\"Ầm!!\" Tiếng động lớn rõ mồn một khiến tim bạn thắt lại, nhưng màn đêm buông thấp, mọi người nhìn quanh ngơ ngác, không biết thứ gì sắp sụp đổ."
  },
  AvgDialog_149755_Content_88 = {
    Text = "<Big:Không ổn rồi, là đê vỡ!!>"
  },
  AvgDialog_149755_Content_89 = {
    Text = "<Big:Chạy mau! Ai đi được thì chạy ngay, không kịp nữa rồi!>"
  },
  AvgDialog_149755_Content_9 = {
    Text = "Dù rất không muốn ở lại, nhưng toàn thân bạn nóng ran đến mức đáng sợ, đã không còn sức để theo kịp anh ấy."
  },
  AvgDialog_149755_Content_90 = {
    Text = "Tiếng van xin, tiếng rên rỉ, tiếng khóc thét, thiên đường trong giấc mơ của bạn đang lung lay, sắp bị cơn mưa bất tận nhấn chìm, chỉ còn lại đống đổ nát hoang tàn. Vậy mà bạn thậm chí không thể tự mình bước đi, chỉ có thể bất lực đứng nhìn."
  },
  AvgDialog_149755_Content_91 = {
    Text = "Hiệp sĩ của bạn đỡ bạn lên thành xe, tháo tấm áo choàng ra, quấn chặt quanh người bạn."
  },
  AvgDialog_149755_Content_92 = {
    Text = "Thưa Công chúa điện hạ, thần kính xin Người cho phép thần rời đi, để chống lại trận lũ lụt đang hoành hành."
  },
  AvgDialog_149755_Content_93 = {
    Text = "Ngươi có thể ngăn được lũ lụt không?"
  },
  AvgDialog_149755_Content_94 = {
    Text = "Thần sẽ cố hết sức mình."
  },
  AvgDialog_149755_Content_95 = {
    Text = "Ngươi còn có thể trở về không?"
  },
  AvgDialog_149755_Content_96 = {
    Text = "……Thần sẽ cố hết sức mình."
  },
  AvgDialog_149755_Content_97 = {
    Text = "<Big:Không, không được, ta không đồng ý! Ta không cho phép!>"
  },
  AvgDialog_149755_Content_98 = {
    Text = "Chúng ta đi, đi ngay bây giờ… sẽ còn có nơi tiếp theo mà, đảo Táo, đảo Bí Ngô, gì cũng được, sẽ còn có nơi tiếp theo mà!"
  },
  AvgDialog_149755_Content_99 = {
    Text = "Bạn dùng hết sức nắm chặt vạt áo của anh, nhưng trong lòng hiểu rõ điều đó chẳng qua là vô ích, anh đã đưa ra lựa chọn của mình. Anh cúi chào bạn, như người anh hùng hiền hòa nhất, người hiệp sĩ trung thành nhất trong mọi câu chuyện."
  },
  AvgDialog_149756_Content_1 = {
    Text = "Công chúa"
  },
  AvgDialog_149756_Content_10 = {
    Text = "Ngươi muốn lớn tiếng phản bác, muốn chế nhạo, muốn nguyền rủa, muốn gào thét, nhưng mảnh vải thấm dầu đã bịt chặt miệng ngươi. Vật lạ tanh hôi nhờn nhụa ép chặt gốc lưỡi ngươi, ngoài việc muốn nôn mửa, ngươi không thể phát ra bất kỳ âm thanh nào."
  },
  AvgDialog_149756_Content_11 = {
    Text = "Nhìn kìa, nó đang run rẩy, ác quỷ đang vùng vẫy trong người nó, đây chính là bộ mặt thật xấu xí của nó."
  },
  AvgDialog_149756_Content_12 = {
    Text = "Lạy Chúa nhân từ, con cầu xin Ngài mở miệng bị quỷ dữ phong ấn của nó, để nó tự miệng thú nhận tội lỗi, nếu trong lòng nó vẫn còn khao khát được cứu rỗi."
  },
  AvgDialog_149756_Content_13 = {
    Text = "Cục vải bịt miệng bị ai đó thô bạo giật ra, ngươi ho sặc hai tiếng, thở hổn hển từng hơi dài, nước dãi chảy dài từ khóe miệng."
  },
  AvgDialog_149756_Content_14 = {
    Text = "Những con quái vật cầm rìu và chĩa cỏ khô vây thành vòng tròn, cảnh giác nhìn chằm chằm vào ngươi. Ở xa hơn, trên bờ ruộng, giữa cành cây, sau những ô cửa sổ hé mở, còn ẩn náu thêm nhiều cặp mắt nữa."
  },
  AvgDialog_149756_Content_15 = {
    Text = "Hãy nói ra đi, con ơi! Hãy tuyên bố trước Chúa sự hối hận của con, đây là khoảnh khắc cuối cùng để con thoát khỏi hình phạt vĩnh cửu!"
  },
  AvgDialog_149756_Content_16 = {
    Text = "<Small:… Quái vật.>"
  },
  AvgDialog_149756_Content_17 = {
    Text = "Gì? Nó nói gì vậy?"
  },
  AvgDialog_149756_Content_18 = {
    Text = "<BigShake:Quái vật! Quái vật! Quái — khục khục khục!>"
  },
  AvgDialog_149756_Content_19 = {
    Text = "Trò lừa bịp được dàn dựng công phu bị ngươi vạch trần, những con quái vật lộ ra vẻ mặt hoảng loạn, ngươi cảm thấy một niềm khoái cảm tàn nhẫn."
  },
  AvgDialog_149756_Content_2 = {
    Text = "Quái vật đã ăn thịt gia đình tôi, giờ đây, chúng định ăn thịt tôi."
  },
  AvgDialog_149756_Content_20 = {
    Text = "Lời nguyền, là lời nguyền! Con phù thủy chết tiệt!"
  },
  AvgDialog_149756_Content_21 = {
    Text = "Mau bịt miệng nó lại!"
  },
  AvgDialog_149756_Content_22 = {
    Text = "Lạy Chúa… xin bảo vệ chúng con…"
  },
  AvgDialog_149756_Content_23 = {
    Text = "<Big:Thiêu chết nó! Thiêu chết nó!>"
  },
  AvgDialog_149756_Content_24 = {
    Text = "<Big:Tiểu yêu! Quái đầm lầy! Quỷ ăn xác! Quái vật! Tất cả các người đều là quái ư ư ư ư—!!>"
  },
  AvgDialog_149756_Content_25 = {
    Text = "Quỷ dữ đã cướp đi linh hồn của nó rồi, để bảo vệ làng chúng ta khỏi tà thuật, phải trừ khử kẻ ô uế này."
  },
  AvgDialog_149756_Content_26 = {
    Text = "Nguyện lửa thánh thiêu sạch tội lỗi của cô ta, nguyện Chúa ban bình an cho chúng ta."
  },
  AvgDialog_149756_Content_27 = {
    Text = "Từng bó củi khô được chất dưới chân ngươi, gai góc cào rách làn da trần, ngươi đau đớn vùng vẫy, xiềng xích kêu loảng xoảng."
  },
  AvgDialog_149756_Content_28 = {
    Text = "Điều đó khiến ngươi nhận thêm nhiều lời chửi rủa, cùng một sợi dây thừng buộc chặt hơn."
  },
  AvgDialog_149756_Content_29 = {
    Text = "Lửa bùng lên."
  },
  AvgDialog_149756_Content_3 = {
    Text = "Hoàng hôn là dấu hiệu của sự hồi sinh nào đó, mặt trời lặn như một vết đỏ bệnh hoạn, bầu trời cũng sưng phù vì bầm tím."
  },
  AvgDialog_149756_Content_30 = {
    Text = "Chúng ta trục xuất ngươi… linh hồn ô uế, kẻ dị giáo phản đạo… như khói bị gió thổi tan, như sáp bị lửa thiêu chảy…"
  },
  AvgDialog_149756_Content_31 = {
    Text = "Kẻ sa ngã, kẻ bức hại, kẻ bị lưu đày, nhân danh Thánh Chủ, ta ra lệnh cho ngươi, hãy sợ hãi đi, hãy khuất phục đi, hãy chạy trốn—"
  },
  AvgDialog_149756_Content_32 = {
    Text = "Giọng hắn đột ngột dừng lại, như bị một chiếc kéo cắt đứt ngang."
  },
  AvgDialog_149756_Content_33 = {
    Text = "Ngươi cố gắng mở to đôi mắt đang rát bỏng, xuyên qua làn khói cuồn cuộn, ngươi thấy một bóng người lạ đứng bên cạnh vị mục sư."
  },
  AvgDialog_149756_Content_34 = {
    Text = "Hắn xuất hiện từ lúc nào? Ngươi không biết. Ngươi nhìn sang đám quái vật còn lại, chúng đứng im bất động, như một đàn ếch há hốc miệng."
  },
  AvgDialog_149756_Content_35 = {
    Text = "Vị mục sư co giật như người mất trí, hai tay ôm lấy cổ, máu trào ra từ kẽ ngón tay, phun ra từ miệng hắn, khuôn mặt hắn cùng màu với bầu trời. Hắn ngã xuống."
  },
  AvgDialog_149756_Content_36 = {
    Text = "<Big:Aaaa——!!>"
  },
  AvgDialog_149756_Content_37 = {
    Text = "Tiếng thét, vang hơn cả tiếng còi, những lưỡi lửa cũng run rẩy theo."
  },
  AvgDialog_149756_Content_38 = {
    Text = "Máu… nhiều máu quá… giết người rồi! Cứu với, quái vật giết người rồi!"
  },
  AvgDialog_149756_Content_39 = {
    Text = "Không, không… ác quỷ, là ác quỷ! Con phù thủy đó đã triệu hồi thứ gì đó từ địa ngục! Lạy Chúa, xin Ngài tha thứ cho chúng con…"
  },
  AvgDialog_149756_Content_4 = {
    Text = "Lửa chưa kịp bùng cháy, cây khô đã vặn vẹo, dáng vẻ tuyệt vọng đó, như thể ánh sáng ban ngày ngày qua ngày cũng là một thứ thiêu đốt khó chịu đựng."
  },
  AvgDialog_149756_Content_40 = {
    Text = "Tim đập thình thịch loạn nhịp, ngươi biết hắn là ai, ngươi biết sinh mệnh của mình sẽ không kết thúc hôm nay, chẳng qua là một lớp dọn đường, một đoạn dạo đầu, để chào đón sự xuất hiện của hắn."
  },
  AvgDialog_149756_Content_41 = {
    Text = "Tràn đầy nhiệt huyết hy vọng, ngươi ra sức vặn vẹo thân mình, kêu ú ớ, nóng lòng muốn hắn nhìn về phía mình, gần như quên mất sợi xích đang bỏng rát."
  },
  AvgDialog_149756_Content_43 = {
    Text = "Một bàn tay đeo găng kéo ngươi ra khỏi đống lửa, chân ngươi mềm nhũn, không kiểm soát được mà ngã sụp xuống đất, vừa ho vừa nôn mửa, nước mắt và nước mũi hòa lẫn vào nhau."
  },
  AvgDialog_149756_Content_44 = {
    Text = "<Shake:Khục khục khục khục khục khục khục——!! Đợi, khục khục khục khục, đợi đã! Đừng đi!>"
  },
  AvgDialog_149756_Content_45 = {
    Text = "Trước khi hắn quay người bước đi, ngươi vội vàng túm lấy tà áo choàng của hắn."
  },
  AvgDialog_149756_Content_46 = {
    Text = "Có vẻ như không ngờ đến hành động của ngươi, mũ trùm đầu của hắn trượt xuống một bên, để lộ ra khuôn mặt của một thiếu niên."
  },
  AvgDialog_149756_Content_47 = {
    Text = "Buông tay ra."
  },
  AvgDialog_149756_Content_48 = {
    Text = "Ngươi rất thông minh, phân biệt được sự khác nhau giữa dọa nạt và cảnh cáo. Nhớ lại cái chết của vị mục sư không lâu trước, ngươi rùng mình co rúm lại."
  },
  AvgDialog_149756_Content_49 = {
    Text = "Nhưng rồi ngươi lại nhìn thấy khuôn mặt của hắn, không còn nghi ngờ gì nữa, vị hiệp sĩ cao quý trong câu chuyện chính là phải như vậy. Hắn nhất định là đến vì ngươi, ngươi thậm chí còn cảm thấy đôi mày và ánh mắt ấy như đã từng gặp ở đâu đó."
  },
  AvgDialog_149756_Content_5 = {
    Text = "<BigShake:Đừng để bị gương mặt của cô ta đánh lừa!>Khuôn mặt trẻ thơ chỉ là lớp ngụy trang, bên trong thân xác đó trú ngụ một con quỷ, tội lỗi của cô ta, Chúa đều đã thấy."
  },
  AvgDialog_149756_Content_50 = {
    Text = "Đúng rồi, ngươi nhất định đã từng gặp hắn ở đâu đó, trong giấc mơ, lời nguyền, hay lời tiên tri. Nếu không thì làm sao giải thích được lòng dũng cảm bỗng dưng xuất hiện trong ngươi?"
  },
  AvgDialog_149756_Content_51 = {
    Text = "<Shake:Không… khụ khụ khụ, ngươi không thể đi.>"
  },
  AvgDialog_149756_Content_52 = {Text = "Tại sao?"},
  AvgDialog_149756_Content_53 = {
    Text = "Vì, khụ khụ, vì ngươi đến để cứu ta, sao có thể bỏ ta lại đây?"
  },
  AvgDialog_149756_Content_54 = {
    Text = "Ngươi đã được cứu rồi, hãy trở về với cuộc sống của mình đi."
  },
  AvgDialog_149756_Content_55 = {
    Text = "Nơi này không có cuộc sống nào thuộc về ta cả, khắp nơi đều là quái vật, chỉ biết bắt người, ăn thịt người, ngươi đã thấy rồi đó."
  },
  AvgDialog_149756_Content_56 = {
    Text = "Không liên quan đến ta."
  },
  AvgDialog_149756_Content_57 = {
    Text = "Sao có thể không liên quan đến ngươi? Ta rõ ràng đã chờ ngươi suốt."
  },
  AvgDialog_149756_Content_58 = {
    Text = "Chờ ta? Ngươi… ngươi biết ta?"
  },
  AvgDialog_149756_Content_59 = {
    Text = "Dĩ nhiên, ngươi là hiệp sĩ của ta."
  },
  AvgDialog_149756_Content_6 = {
    Text = "Nó là kẻ trộm, là kẻ lừa đảo, là tôi tớ của bóng tối. Tai họa tuôn ra từ miệng nó, thuốc độc làm ô nhiễm giếng và sông, khiến trâu bò ngã chết trong chuồng, người ngoan đạo mắc bệnh hiểm nghèo."
  },
  AvgDialog_149756_Content_60 = {
    Text = "Kinh ngạc, bàng hoàng, hoảng loạn, đau khổ, vô số cảm xúc cùng lúc hiện lên trên khuôn mặt hắn, hắn giật mạnh tay ra khỏi ngươi, như né tránh một con rắn độc, thanh kiếm ngắn dính máu áp vào cổ ngươi."
  },
  AvgDialog_149756_Content_61 = {
    Text = "Ngươi là ai!"
  },
  AvgDialog_149756_Content_62 = {
    Text = "Ta, ta là công chúa! Đúng vậy, ta là công chúa, ta bị quái vật bắt đi, đã chờ ngươi đến cứu suốt!"
  },
  AvgDialog_149756_Content_63 = {
    Text = "Đừng không tin, nếu ta không phải công chúa, sao trời lại phái một vị hiệp sĩ đến cứu ta?"
  },
  AvgDialog_149756_Content_65 = {
    Text = "Kiếm ngắn vào vỏ, hắn đứng dậy đi sâu vào rừng rậm, không nói thêm với ngươi một lời nào nữa."
  },
  AvgDialog_149756_Content_66 = {
    Text = "Đợi đã, ngươi định đi đâu, ta, khụ, ta đi cùng ngươi."
  },
  AvgDialog_149756_Content_67 = {
    Text = "<Shake:Đứng lại! Khụ khụ, nhân danh công chúa, ta ra lệnh cho ngươi đứng lại!>"
  },
  AvgDialog_149756_Content_68 = {
    Text = "Dù hắn nhanh nhẹn đến kinh ngạc, nhưng ngươi lại có lợi thế là thuộc lòng khu rừng này như lòng bàn tay."
  },
  AvgDialog_149756_Content_69 = {
    Text = "Hơn nữa ngươi đã không còn nơi nào để đi, chỉ có thể chạy, chạy mãi, dù có ngã xuống giữa rừng, trở thành thức ăn cho dã thú."
  },
  AvgDialog_149756_Content_7 = {
    Text = "Các người hãy làm chứng, bao nhiêu lần nó bước vào rừng, biến mất, rồi trở về như không có chuyện gì? Đó chính là bằng chứng của việc hành phù thủy!"
  },
  AvgDialog_149756_Content_70 = {
    Text = "<Shake:Hù… hù… đợi đã, ta, ta biết luật lệ.>"
  },
  AvgDialog_149756_Content_71 = {
    Text = "Ta có nơi cần đến, hãy đưa ta đến đó, ngươi sẽ nhận được danh dự và phần thưởng."
  },
  AvgDialog_149756_Content_72 = {
    Text = "Ta không cần."
  },
  AvgDialog_149756_Content_73 = {
    Text = "Ngươi cần, ít nhất là lúc này, ngươi cần một người dẫn ngươi ra khỏi đây, phải không?"
  },
  AvgDialog_149756_Content_74 = {
    Text = "Hắn không trả lời, nhưng dần dần dừng bước lại."
  },
  AvgDialog_149756_Content_75 = {
    Text = "Ngươi định đi đâu?"
  },
  AvgDialog_149756_Content_76 = {
    Text = "Ừm… à đúng rồi, Đảo Táo, ngươi có nghe nói chưa? Không cần canh tác, không bao giờ ốm đau, cũng không có mùa đông — đó là thiên đường, ta sắp đến đó rồi."
  },
  AvgDialog_149756_Content_77 = {
    Text = "Chưa bao giờ nghe. Nó ở đâu?"
  },
  AvgDialog_149756_Content_78 = {
