  AvgDialog_149756_Content_79 = {
    Text = "Chiếc áo choàng đen hòa vào màn đêm, hắn đứng sau bụi cây rậm rạp, khuôn mặt mờ nhạt không rõ ràng."
  },
  AvgDialog_149756_Content_8 = {
