  AvgDialog_149757_Content_26 = {
    Text = "<Shake:Ô nhục… ô nhục ô nhục ô nhục ô nhục ô nhục ô nhục ô nhục ô nhục, ô nhục là thứ duy nhất ta còn có…>"
