  AvgDialog_149757_Content_79 = {
    Text = "Mưa lại đổ xuống, đường phố tựa như một dòng sông đang chảy."
  },
  AvgDialog_149757_Content_8 = {
    Text = "Trước khi bị bóng tối nuốt chửng, hắn bảo ngươi rời đi, nhưng công chúa sao có thể không có kỵ sĩ? Ngươi cố gắng cứu hắn ra, hắn lại gạt tay ngươi ra, đập vỡ cửa sổ nhảy xuống từ gác xép, biến mất vào khu rừng hoang bên ngoài trang viên."
  },
  AvgDialog_149757_Content_80 = {
    Text = "Ngươi ôm chặt toàn bộ di vật trong lòng, cắm đầu chạy điên cuồng qua những con hẻm hẹp, khéo léo tránh hết toán lính canh này đến toán lính canh khác, lao thẳng về phía túp lều rơm nơi các ngươi ẩn náu."
  },
  AvgDialog_149757_Content_81 = {
    Text = "<Shake:Nhanh lên, nhanh lên về báo cho hắn…>"
  },
  AvgDialog_149757_Content_82 = {
    Text = "Con quái vật trong miệng quái vật, không còn nghi ngờ gì nữa chính là kỵ sĩ của ngươi, những vụ giết người trắng trợn của hắn cuối cùng đã đến tai lãnh chúa, nghe nói đêm nay lính canh sẽ lục soát từng góc khuất trong thành."
  },
  AvgDialog_149757_Content_83 = {
    Text = "Vẫn còn thời gian, cổng thành chưa đóng, chỉ cần nhanh hơn một chút…"
  },
  AvgDialog_149757_Content_84 = {
    Text = "<Big:Orci! Chạy mau, chúng sắp đến—>"
  },
  AvgDialog_149757_Content_85 = {
    Text = "Túp lều chật hẹp dựng ở cuối ngõ cụt, xung quanh chất đầy bao tải vải thô, vẫn không ngăn được bùn lầy tràn vào. Ngươi lao về phía bóng người nằm ở góc sâu nhất, giật mạnh chiếc áo choàng của hắn lên — chỉ giật được một chiếc áo choàng."
  },
  AvgDialog_149757_Content_86 = {
    Text = "Trong lều ngoài rơm khô ra không có gì khác, kỵ sĩ của ngươi đã biến mất không còn dấu vết."
  },
  AvgDialog_149757_Content_9 = {
    Text = "Mưa lớn che khuất những cành cây gãy và dấu chân còn sót lại, cảnh vật xung quanh trông như nhau cả, bước chân ngươi ngày càng chậm lại, cuối cùng dừng lại trong mê mang."
  },
  AvgDialog_15363_Content_1 = {
    Text = "Cái chết của thiếu nữ san hô"
  },
  AvgDialog_15363_Content_10 = {
    Text = "Mọi người vây quanh kín mít, vô số đèn flash lóe sáng, tiếng bàn tán ồn ào không ngớt, cho đến khi nhân viên vén tấm vải phủ lên."
  },
  AvgDialog_15363_Content_11 = {
    Text = "Đây là…… Trời ơi."
  },
  AvgDialog_15363_Content_12 = {
    Text = "……Không thể tin được."
  },
  AvgDialog_15363_Content_13 = {
    Text = "Như thể chạm vào một công tắc nào đó, đám đông tự động im lặng, đại sảnh vốn ồn ào náo nhiệt bỗng trở nên trống vắng."
  },
  AvgDialog_15363_Content_14 = {
    Text = "Bạn vất vả rẽ đám đông, cuối cùng cũng nhìn thấy tác phẩm được vây ở trung tâm."
  },
  AvgDialog_15363_Content_16 = {
    Text = "Là Coral. Cô ấy đã lột bỏ toàn bộ sắc màu và cảm xúc, hóa thành một bức tượng san hô thuần trắng."
  },
  AvgDialog_15363_Content_17 = {
    Text = "Ánh sáng trời trong vắt xuyên qua mái vòm kính tinh khiết chiếu rọi lên cô, bao phủ cô trong một lớp ánh sáng dịu màu vàng nhạt."
  },
  AvgDialog_15363_Content_18 = {
    Text = "Bạn cúi đầu nhìn tấm biển đồng trên bệ tượng, trên đó khắc tên bức tượng bằng kiểu chữ đẹp đẽ: <Red:\"Thiếu Nữ San Hô Vô Danh\">."
  },
  AvgDialog_15363_Content_19 = {
    Text = "San hô vô danh……"
  },
  AvgDialog_15363_Content_2 = {
    Text = "Kính gửi ngài Claudel:\n\nGần đây đã xảy ra rất nhiều chuyện, xin hãy tha thứ cho sự chậm trễ trong việc hồi thư của tôi.\n\nSau khi cô San rời đi, ngài Auguste không còn có thể cho ra đời tác phẩm nào khiến người ta mắt sáng lên nữa.\nDưới áp lực dư luận, ông ấy tuyên bố tạm ngừng sự nghiệp điêu khắc vô thời hạn.\nÔng ấy đã nhận được hình phạt xứng đáng, nhưng tôi không thể vui nổi——<Yellow:cô San vẫn biệt vô âm tín.>"
  },
  AvgDialog_15363_Content_20 = {
    Text = "Bạn ngẩn ngơ nhìn dòng chữ ấy, ý thức dường như cũng lay động, vặn xoắn theo những nét chữ đẹp đẽ……"
  },
  AvgDialog_15363_Content_21 = {
    Text = "Đưa tay dụi mắt, lại phát hiện đầu ngón tay không biết từ lúc nào đã phủ lên từng lớp màu trắng thô ráp, ảm đạm."
  },
  AvgDialog_15363_Content_22 = {Text = "?！"},
  AvgDialog_15363_Content_23 = {
    Text = "Màn sương san hô trắng không ngừng lan rộng từ kẽ ngón tay, từng chút phủ kín toàn thân bạn, nhanh chóng tràn ngập cả phòng triển lãm, rồi——"
  },
  AvgDialog_15363_Content_24 = {Text = "——!!"},
  AvgDialog_15363_Content_25 = {
    Text = "Bạn và phòng triển lãm đồng thời vỡ tan thành vô số mảnh trắng, lần lượt rơi vào đáy đại dương vô tận."
  },
  AvgDialog_15363_Content_26 = {
    Text = "Giữa vô số tượng trắng và san hô, dưới ánh bình minh tĩnh lặng, tàn tích cung điện trắng sừng sững hiện ra."
  },
  AvgDialog_15363_Content_27 = {
    Text = "Những chú cá đủ màu sắc bơi lượn qua những cổng vòm và hành lang xiêu vẹo của tàn tích, tận hưởng khoảng thời gian nhàn nhã vui vẻ."
  },
  AvgDialog_15363_Content_28 = {
    Text = "Toàn bộ phế tích dường như bị bỏ lại trong bóng tối của thời gian, xa rời sự Xói mòn của trần thế, tránh khỏi sự quấy rầy của đám đông."
  },
  AvgDialog_15363_Content_29 = {
    Text = "Khi bạn đã thấy những kỳ tích ấy…… bạn sẽ hiểu tôi……"
  },
  AvgDialog_15363_Content_3 = {
    Text = "<Yellow:Ngày mai tôi sẽ đến triển lãm Salon ở Cité, tìm kiếm \"câu trả lời\" mà cô San đã nói.>\nHãy chúc tôi may mắn nhé.\n\nCamille@1\nA.F.2@1 Tháng 9"
  },
  AvgDialog_15363_Content_30 = {
    Text = "Đây chính là…… kỳ tích mà cô đã nhìn thấy sao, cô Coral?"
  },
  AvgDialog_15363_Content_31 = {
    Text = "Bạn trôi dạt trong làn nước biển ấm áp, say mê nhưng hoang mang ngắm nhìn tất cả trước mắt."
  },
  AvgDialog_15363_Content_32 = {
    Text = "Tránh ra, để tôi đi qua!!"
  },
  AvgDialog_15363_Content_33 = {
    Text = "<Big:Để tôi đi qua!!>"
  },
  AvgDialog_15363_Content_34 = {
    Text = "Tiếng ồn ào hỗn loạn kéo bạn trở về thực tại."
  },
  AvgDialog_15363_Content_35 = {
    Text = "Một ông lão quần áo rách rưới đã phá vỡ vòng vây an ninh, lao về phía bạn, túm chặt lấy tay bạn."
  },
  AvgDialog_15363_Content_36 = {
    Text = "Cậu cũng nhìn thấy rồi đúng không, biển sâu, cung điện, những ảo ảnh hỗn loạn đó……"
  },
  AvgDialog_15363_Content_37 = {Text = "?！"},
  AvgDialog_15363_Content_38 = {
    Text = "Người phụ nữ tà ác này, bà ta là kẻ trộm……"
  },
  AvgDialog_15363_Content_39 = {
    Text = "Ông lão lẩm bẩm không ngừng, bạn nhìn khuôn mặt ẩn sau vành mũ rộng và bộ râu rậm rạp, bỗng nhận ra một manh mối."
  },
  AvgDialog_15363_Content_4 = {
    Text = "Triển lãm Salon Cité\nNgày khai mạc"
  },
  AvgDialog_15363_Content_40 = {
    Text = "……Ngài Auguste?!"
  },
  AvgDialog_15363_Content_41 = {
    Text = "Trời, đúng là ông ta thật……Chúa ơi! Sao ông ta lại biến thành bộ dạng thế này?"
  },
  AvgDialog_15363_Content_42 = {
    Text = "Ông ta phá sản từ lâu rồi, cậu chưa nghe nói sao? Sau khi \"Nàng Thơ Bi Kịch\" thất bại thảm hại, gã này đổ tiền khổng lồ vào mấy tác phẩm, nhưng tiếc là chẳng bán được cái nào..."
  },
  AvgDialog_15363_Content_43 = {
    Text = "Chính phủ giờ e ngại danh tiếng của ông ta, không đặt hàng nữa, chắc là bị kích thích quá nhiều nên phát điên rồi……"
  },
  AvgDialog_15363_Content_44 = {
    Text = "Mọi người vừa kinh ngạc vừa sợ hãi, đứng cách một khoảng không xa không gần nhìn Auguste."
  },
  AvgDialog_15363_Content_45 = {
    Text = "Auguste hất tay bạn ra, ông ta khập khiễng bước đến trước bức tượng, trong mắt là sự căm hận không thể kìm nén."
  },
  AvgDialog_15363_Content_46 = {
    Text = "Hừ……Ngươi tưởng chết đi là có thể xóa sạch mọi thứ ngươi đã làm sao?"
  },
  AvgDialog_15363_Content_47 = {
    Text = "Ngươi đã lừa tất cả mọi người……Tài năng, cảm hứng và danh tiếng của ta đều bị ngươi mang đi hết."
  },
  AvgDialog_15363_Content_48 = {
    Text = "Ta hủy rồi, hủy hoàn toàn rồi. Còn ngươi thì sao, ung dung ngồi đây, tận hưởng sự ngưỡng mộ của tất cả, chờ họ tôn ngươi thành kinh điển……"
  },
  AvgDialog_15363_Content_5 = {
    Text = "Nghe nói chưa, ngài Auguste mang tác phẩm điêu khắc đến triển lãm lần nữa rồi."
  },
  AvgDialog_15363_Content_50 = {
    Text = "Đối mặt với những lời chửi rủa cuồng loạn của người thầy năm xưa, bức tượng lặng lẽ đứng yên, vẻ mặt thờ ơ không hề suy giảm."
  },
  AvgDialog_15363_Content_51 = {
    Text = "Auguste không thể chịu đựng thêm nữa, ông ta hung hãn lao về phía bức tượng."
  },
  AvgDialog_15363_Content_52 = {
    Text = "Lại cái biểu cảm này, lại cái nụ cười chế giễu này……"
  },
  AvgDialog_15363_Content_53 = {
    Text = "Quỷ dữ……Quỷ dữ! <Big:Ta sẽ xé toạc mặt nạ của ngươi!>"
  },
  AvgDialog_15363_Content_6 = {
    Text = "Auguste, nhà điêu khắc đó á? Ông ta chẳng phải đã biến mất sau khi bị nghi ngờ đạo nhái sao, tôi còn tưởng cả đời này ông ta không còn mặt mũi nào mà xuất hiện nữa."
  },
  AvgDialog_15363_Content_7 = {
    Text = "Tôi lại khá tò mò, rời xa cô đồ đệ kia rồi, giờ ông ta còn có thể làm nên trò trống gì nữa……"
