  },
  AvgDialog_15364_Content_14 = {
    Text = "Cô Coral, ngài August hôm nay đã bị người ta đưa đi. Ông ấy nói……\ncô đã lừa dối tất cả mọi người."
  },
  AvgDialog_15364_Content_15 = {
