  AvgDialog_15365_Content_18 = {
    Text = "Đây là chất liệu điêu khắc hoàn hảo nhất mà tôi từng thấy."
  },
  AvgDialog_15365_Content_2 = {
    Text = "Kính gửi ngài Claudel:\n\nTiểu thư Shan không từ chối yêu cầu trở về nhà, nhưng cô ấy mong tôi có thể cho cô ấy thêm chút thời gian.\nCô ấy nói:<Yellow:Sau khi triển lãm Salon kết thúc, tôi sẽ có thể về nhà.>\n\nTuy nói vậy, tình trạng gần đây của tiểu thư Shan thật đáng lo ngại.\nCứ đến đêm khuya cô ấy lại lén lút rời đi, mãi đến rạng sáng mới quay về."
  },
  AvgDialog_15365_Content_20 = {
    Text = "Cô trốn ra ngoài mỗi đêm, chỉ để thu thập dịch Tan chảy ở đây sao?"
  },
  AvgDialog_15365_Content_21 = {
    Text = "Cậu biết tên của chúng? Cậu rất hiểu về chúng nhỉ."
