  AvgDialog_15365_Content_32 = {
    Text = "Chúng giống như xúc tu san hô, không ngừng lan rộng lên trên, lấp lánh ánh sáng lạnh màu xanh xám trong khoảnh khắc ánh trăng dịch chuyển."
