  },
  AvgDialog_15365_Content_35 = {
    Text = "Dù sao bạn giờ đây đã sở hữu toàn bộ ký ức và cảm xúc của chủ nhân trước, cô hầu gái đến từ vùng quê Besançon này có một tình yêu sâu sắc dành cho nữ chủ nhân của mình."
  },
  AvgDialog_15365_Content_36 = {
