  },
  AvgDialog_15365_Content_40 = {
    Text = "Đây là một nhà kho bỏ hoang nằm bên bờ biển, bên trong bày biện rất nhiều tác phẩm điêu khắc tập luyện với đủ tư thế khác nhau, kỳ dị và xoắn vặn vô cùng."
  },
  AvgDialog_15365_Content_41 = {
