  },
  AvgDialog_15365_Content_47 = {
    Text = "Cơ thể nó bị bao bọc trong những Xúc tu hung tàn, Sự biến dạng thành những góc độ không thể tưởng tượng. Các mạch máu ở cổ căng phồng, dường như như một con rắn uốn lượn."
  },
  AvgDialog_15365_Content_48 = {
