  AvgDialog_15606_Content_15 = {Text = "Erica?"},
  AvgDialog_15606_Content_16 = {
    Text = "Bạn chớp mắt, không biết từ lúc nào Mei đã bước vào.\nÁnh mắt cô ấy lướt quanh căn phòng một vòng, cuối cùng dừng lại ở chiếc động cơ bên cạnh bạn."
  },
  AvgDialog_15606_Content_18 = {
    Text = "Sau khi quan sát căn phòng lần thứ hai, cô ấy khép cửa lại, bước nhanh về phía chiếc động cơ."
  },
  AvgDialog_15606_Content_19 = {
    Text = "Xin lỗi, Erica."
  },
  AvgDialog_15606_Content_2 = {
    Text = "Người Tích Tắc, cưng ơi, cậu nghe thấy tôi không?"
  },
  AvgDialog_15606_Content_20 = {
    Text = "Nắp được vặn ra, Mei kẹp lấy thứ bên trong. Lần này bạn nhìn rõ rồi, đó là một ống kim loại đường kính chỉ khoảng 5 cm, mặt bên khắc chữ cái \"S\"."
  },
  AvgDialog_15606_Content_21 = {
    Text = "Một khi cô ấy rút hoàn toàn ống trụ ra, cậu sẽ lại mất ý thức.\nVì vậy trước khi điều đó xảy ra, cậu phải——"
  },
  AvgDialog_15606_Content_22 = {
    Text = "Nắm lấy tay cô ấy"
  },
  AvgDialog_15606_Content_23 = {Text = "A!"},
  AvgDialog_15606_Content_24 = {
    Text = "Sao thế sao thế——"
  },
  AvgDialog_15606_Content_25 = {
    Text = "Erica lao vào phòng, vẻ lo lắng trên mặt cô đông cứng lại ngay khi nhìn thấy ống trụ trong tay Mei."
  },
  AvgDialog_15606_Content_26 = {
    Text = "Mei, cậu đang làm gì vậy?"
  },
  AvgDialog_15606_Content_27 = {
    Text = "Cậu đang làm gì vậy!"
  },
  AvgDialog_15606_Content_28 = {
    Text = "Tớ chỉ đang thử… nguồn năng lượng này… thật sự có thể…"
  },
  AvgDialog_15606_Content_29 = {
    Text = "Đối diện với ống trụ nhỏ đã vận hành toàn bộ động cơ điện cùng mọi thiết bị kết nối, Mei trợn tròn mắt."
  },
  AvgDialog_15606_Content_3 = {
    Text = "Tỉnh dậy từ bóng tối vĩnh hằng, bạn phát hiện mình vẫn đang ở trong xưởng, chiếc động cơ cháy đen vẫn đặt trên bàn làm việc, được nối với cơ thể bạn bằng nhiều sợi cáp to nhỏ khác nhau."
  },
  AvgDialog_15606_Content_30 = {
    Text = "Cậu có biết điều này có ý nghĩa gì không, Erica?"
  },
  AvgDialog_15606_Content_31 = {
    Text = "Điều đó có nghĩa là nó rất nguy hiểm, tớ đã nói rồi, Mei, không được tùy tiện động vào——"
  },
  AvgDialog_15606_Content_32 = {
    Text = "Không, không, nghe này, Erica—— thứ này, thứ nhỏ bé này, có thể cung cấp năng lượng không hao tổn, không khí thải, trong thời gian dài, cậu vẫn chưa hiểu sao?"
  },
  AvgDialog_15606_Content_33 = {
    Text = "Than đá, dầu mỏ, trước mặt nó chẳng là gì cả. Nếu có thể sản xuất hàng loạt, chúng ta sẽ viết lại cấu trúc năng lượng của nhân loại, chúng ta sẽ lưu danh sử sách!"
  },
  AvgDialog_15606_Content_34 = {
    Text = "Cậu phải nói cho tớ biết cậu đã làm ra nó như thế nào, cậu phải nói!"
  },
  AvgDialog_15606_Content_35 = {
    Text = "Erica, cậu đi đâu vậy? Sao lại nói cậu không biết cách làm, Erica!"
  },
  AvgDialog_15606_Content_36 = {
    Text = "Nhà đầu tư đã nói, chỉ cần thấy mẫu thử, ông ấy sẵn sàng cung cấp cho chúng ta lượng lớn vốn, thậm chí cả phòng nghiên cứu chuyên dụng."
  },
  AvgDialog_15606_Content_37 = {
    Text = "Sao cậu cứ không chịu nghe—— tớ không biết thứ này được làm ra như thế nào, tớ làm không được!"
  },
  AvgDialog_15606_Content_38 = {
    Text = "Tớ đã qua cái tuổi tin vào chuyện cổ tích rồi, Erica. Nào là <Blue:chủ tiệm bí ẩn>, muốn qua mặt tớ thì cũng nên tìm lý do khá hơn chứ."
  },
  AvgDialog_15606_Content_39 = {
    Text = "Cậu rõ ràng có thể làm ra thứ lợi hại như vậy, sao tầm nhìn không xa hơn một chút?"
  },
  AvgDialog_15606_Content_4 = {
    Text = "Nghe được."
  },
  AvgDialog_15606_Content_40 = {
    Text = "Sao vẫn cứ nhốt mình ở cái nơi thế này, mày mò mấy thứ đồng nát?"
  },
  AvgDialog_15606_Content_41 = {
    Text = "Giọng nói của Mei như một cái tát giáng thẳng vào mặt Erica, cô nhìn người đồng hành, đối tác của mình, không thể tin nổi những gì mình vừa nghe."
  },
  AvgDialog_15606_Content_42 = {
    Text = "……Đồ sắt vụn, đây thật sự là suy nghĩ của cậu sao?"
  },
  AvgDialog_15606_Content_43 = {
    Text = "Tôi cứ tưởng chúng ta có chung lý tưởng."
  },
  AvgDialog_15606_Content_44 = {
    Text = "Mei cắn chặt răng, nắm chặt chiếc ống trụ trong tay."
  },
  AvgDialog_15606_Content_45 = {
    Text = "Hãy nhìn rõ sự thật đi, Erica. Bây giờ không ai muốn bỏ tiền cho nhân ngẫu tự động nữa, năng lượng mới mới là lối thoát của chúng ta."
  },
  AvgDialog_15606_Content_46 = {
    Text = "……Đặt năng lượng đặc biệt xuống."
  },
  AvgDialog_15606_Content_47 = {
    Text = "Hãy nghĩ về tất cả những gì chúng ta có thể sở hữu, nhiều kinh phí hơn, nhiều tài nguyên hơn.\nCó những thứ đó cậu mới có thể tiếp tục giấc mơ của mình, có những thứ đó, cậu mới có thể——"
  },
  AvgDialog_15606_Content_48 = {
    Text = "Tôi bảo đặt xuống!"
  },
  AvgDialog_15606_Content_49 = {
    Text = "Erica lao lên giành lấy, Mei né không kịp, va vào chiếc tủ bên cạnh."
  },
  AvgDialog_15606_Content_5 = {
    Text = "Xin lỗi nhé, tôi hứa tiếp theo sẽ tập trung giải quyết mô-đun phát âm! Thời gian này cậu chịu khó một chút, được không?"
  },
  AvgDialog_15606_Content_50 = {Text = "!!"},
  AvgDialog_15606_Content_51 = {
    Text = "Những chai lọ chứa đầy thuốc thử và nhiên liệu đổ ập xuống, bạn lao tới chắn trước mặt hai người, giây tiếp theo——"
  },
  AvgDialog_15606_Content_6 = {
    Text = "Gật đầu."
  },
  AvgDialog_15606_Content_7 = {
    Text = "Cha Thần phù hộ, tuyệt quá. Tôi thật sự sợ có sợi dây nào bị cháy hỏng mất."
  },
  AvgDialog_15606_Content_8 = {
    Text = "Cô ấy thở phào nhẹ nhõm, rồi ngáp một cái thật to như thể giờ mới cảm nhận được sự mệt mỏi."
  },
  AvgDialog_15606_Content_9 = {
    Text = "Tôi phải đi uống một tách cà phê, còn bữa tối nữa…"
  },
  AvgDialog_15607_Content_1 = {
    Text = "Súng plasma bắn vào tay khổng lồ mech, bạc tâm bị tách ra khỏi lòng bàn tay và rơi xuống đất trong im lặng."
  },
  AvgDialog_15607_Content_10 = {
    Text = "Tôi… rốt cuộc đã… làm gì…"
  },
  AvgDialog_15607_Content_11 = {
    Text = "Bạn vẫn không hiểu, nhưng không sao, bạn đã thúc đẩy cuộc cách mạng về sinh lực và linh hồn này, cuộc <Red:\"Lột Xác\"> này.\nHãy yên tâm mà chết đi, tôi đảm bảo mọi người sẽ ghi nhớ đóng góp của bạn."
  },
  AvgDialog_15607_Content_12 = {
    Text = "Erica nhắm mắt lại."
  },
  AvgDialog_15607_Content_13 = {
    Text = "Cậu… đúng, cậu luôn luôn đúng…"
  },
  AvgDialog_15607_Content_14 = {
    Text = "Nước mắt đen lăn dài từ khóe mắt cô, cô nhăn mũi, rồi đột nhiên quay đầu nhìn về phía bạn."
  },
  AvgDialog_15607_Content_15 = {
    Text = "Ngay từ đầu tôi… nên nghe… lời cậu… tôi… không nên lấy thứ này…"
  },
  AvgDialog_15607_Content_16 = {
    Text = "Lý trí của tôi… của tôi… hãy giúp tôi… lần cuối cùng này…"
  },
  AvgDialog_15607_Content_17 = {
    Text = "Liệu trong thân xác này thực sự có ý thức thứ ba hay không, hay đó chỉ là cảm giác tội lỗi của cô được hiện thực hóa dưới ảnh hưởng của sự xâm thực? Bạn không thể biết được."
  },
  AvgDialog_15607_Content_18 = {
    Text = "Cô chìa tay về phía bạn."
  },
  AvgDialog_15607_Content_19 = {
    Text = "Giúp tôi… cứu…"
  },
  AvgDialog_15607_Content_2 = {
    Text = "Sau một khoảnh khắc trì hoãn, bàn tay khổng lồ tan rã, chất lỏng đen như mưa lớn tuôn rơi, nó xuyên qua bạn nhưng đã làm tối đi hình bóng của Erika."
  },
  AvgDialog_15607_Content_20 = {
    Text = "Bạn chỉ biết rằng bạn sẽ giúp cô, chứng kiến kết cục của cô với tư cách là một \"con người\"."
  },
  AvgDialog_15607_Content_21 = {
    Text = "Nắm lấy tay cô"
  },
  AvgDialog_15607_Content_22 = {
    Text = "Cô ngạc nhiên nhìn bạn, như thể không ngờ rằng mình lại thực sự có thể chạm vào \"lý trí\" của chính mình."
  },
  AvgDialog_15607_Content_23 = {
    Text = "Gật đầu"
  },
  AvgDialog_15607_Content_24 = {
    Text = "Cô ngạc nhiên nhìn bạn, như thể hoàn toàn không ngờ rằng \"lương tri\" của mình lại có thể đáp lại mình."
  },
  AvgDialog_15607_Content_25 = {
    Text = "Cảm ơn……"
  },
  AvgDialog_15607_Content_26 = {
    Text = "Ảo ảnh vỡ tan như bong bóng, chỉ còn lại quả cầu sáng lập lòe, vẫn đang tỏa ra ánh sáng cuối cùng."
  },
  AvgDialog_15607_Content_27 = {
    Text = "Bạn ôm quả cầu sáng đã thu nhỏ vào lòng, nhìn về phía Ngân Tâm vỡ nát không xa."
  },
  AvgDialog_15607_Content_28 = {
    Text = "Bạn sẽ thành công."
