  AvgDialog_15607_Content_5 = {Text = "!?"},
  AvgDialog_15607_Content_6 = {
    Text = "Ta đã nói rồi, chỉ cần bước vào trái tim bạc này là có thể đón nhận sự bất tử thực sự."
  },
  AvgDialog_15607_Content_7 = {
    Text = "Cứ giãy giụa đi, vật chất đen rồi sẽ xóa sổ ngươi, khi đó ta sẽ mang đến cho thế giới cuộc <Red:「Lột Xác」> thực sự — ai ai cũng được bất tử, ai ai cũng được trường sinh."
  },
  AvgDialog_15607_Content_8 = {
    Text = "Đó là… chết… không phải…"
  },
  AvgDialog_15607_Content_9 = {
    Text = "Màu đen ngày càng chiếm lĩnh cơ thể cô, Erica đau đớn cúi người xuống, tinh thần đã trên bờ vực tan rã."
  },
  AvgDialog_15608_Content_1 = {
    Text = "Đây là……không gian tinh thần?"
