  },
  AvgDialog_15609_Content_4 = {
    Text = "Như màu mực hòa vào nước, bóng tối lan tỏa trong quả cầu sáng, phủ kín tất cả bên trong.\nQuả cầu sáng bắt đầu nhấp nháy."
  },
  AvgDialog_15609_Content_5 = {
    Text = "Chuyện gì thế, tay tôi… tự nó…"
  },
  AvgDialog_15609_Content_6 = {
    Text = "Có phải ngươi làm không? Dừng lại, <Big:dừng lại!>"
