  },
  AvgDialog_15610_Content_1 = {
    Text = "Phòng tuyến của một người gần như không tồn tại, bất kể ngươi đập vỡ bao nhiêu quái vật, thân thể cấu thành từ chất nhầy nhanh chóng tụ lại, xuyên qua bên cạnh ngươi, lao thẳng vào cầu sáng."
  },
  AvgDialog_15610_Content_10 = {
    Text = "Điện tương màu vàng kim lách tách trên bóng hình, thân ảnh của Erica ngày càng ngưng tụ rõ ràng."
  },
  AvgDialog_15610_Content_11 = {
    Text = "Cô giơ tay dùng điện tương đánh tan quái vật trước mặt ngươi. Bàn tay khổng lồ nhúc nhích, phát ra một tiếng thở dài."
  },
  AvgDialog_15610_Content_12 = {
    Text = "Tôi chỉ muốn đền đáp ơn bạn đã mang tôi trở lại và cho tôi một thân thể mới. Tại sao lại làm tổn thương tôi như vậy?"
