  },
  AvgDialog_15610_Content_16 = {
    Text = "Nếu bạn lo lắng nó không thể hỗ trợ hoạt động lâu dài của con rối, đừng lo lắng. \nMột thứ như vậy, đủ để vận hành thứ gì đó phức tạp và lớn hơn."
  },
  AvgDialog_15610_Content_17 = {
