  AvgDialog_18714_Content_32 = {
    Text = "Nó trông chẳng giống muối tắm chút nào."
  },
  AvgDialog_18714_Content_34 = {
    Text = "Ngươi muốn nói… tối qua ngươi nhìn thấy một người trông giống hệt ta?"
