  AvgDialog_18717_Content_33 = {
    Text = "<Change>Giúp ta tìm một người……"
  },
  AvgDialog_18717_Content_34 = {
    Text = "Daphodel cùng những chiếc đầu lâu nhanh chóng trao đổi bằng thứ ngôn ngữ mà bạn không hiểu. Không biết nói đến chuyện gì, cô vui vẻ bật cười."
