  AvgDialog_18717_Content_57 = {
    Text = "Chúng ta dung thứ cho loài người ngu muội, chúng ta tuân theo những quy tắc hay thay đổi, chúng ta phục tùng những liên kết mong manh, tất cả đều xuất phát từ sự sợ hãi…"
  },
  AvgDialog_18717_Content_58 = {
    Text = "Nàng nhẹ nhàng chạm lên khuôn mặt bạn."
