  AvgDialog_18717_Content_59 = {
    Text = "Và lời hứa."
  },
  AvgDialog_18717_Content_61 = {
    Text = "Vì vậy ngươi trở thành một trong số ít Thể Thức Tỉnh được đăng ký nhưng chưa từng liên kết với bất kỳ ai."
  },
  AvgDialog_18717_Content_62 = {
