  AvgDialog_18717_Content_63 = {
    Text = "Cá nhân ta thực ra không ghét cái gọi là \"liên kết\"… Chỉ cần đôi bên cùng có lợi, hà tất phải câu nệ bề ngoài?"
  },
  AvgDialog_18717_Content_64 = {
