  },
  AvgDialog_18719_Content_33 = {
    Text = "<RedItalic:Chúng ta lấy máu làm bút, chúng ta lấy đất làm giấy.>\n<RedItalic:Chúng ta dùng thân xác dầm mưa viết nên nỗi bi thương và sợ hãi……>"
