    Text = "Bạn lắc đầu, cố xua đi những suy nghĩ hỗn loạn trong đầu."
  },
  AvgDialog_18719_Content_57 = {
    Text = "Cuộc điều tra ở thị trấn Rye mới kết thúc chưa được hai ngày, vết thương trên người bạn vẫn chưa lành hẳn."
  },
  AvgDialog_18719_Content_58 = {
    Text = "Hài, biết làm sao khi các điều tra viên khác cũng đều bận rộn không rảnh tay chứ?"
  },
  AvgDialog_18719_Content_59 = {
    Text = "Đã đến nước này rồi, cứ giải quyết sớm vụ án này đi, tôi còn muốn nghỉ phép nữa."
