  AvgDialog_18719_Content_61 = {
    Text = "Tiếng lật trang sách bỗng dừng lại đột ngột."
  },
  AvgDialog_18719_Content_62 = {
    Text = "Bạn chăm chú nhìn vào trang sách đang mở, bắt đầu suy tính kế hoạch điều tra tiếp theo."
  },
  AvgDialog_18719_Content_63 = {
    Text = "Ramona…… trước khi hội hợp với thanh tra, tôi muốn đến một nơi trước đã."
  },
  AvgDialog_18719_Content_7 = {
    Text = "Chào buổi sáng, %player%{Male=ngài,Female=cô}. Chào mừng đến tệ xá……"
  },
  AvgDialog_18719_Content_8 = {
    Text = "Cô Aurla?!"
  },
  AvgDialog_18719_Content_9 = {
    Text = "Ký ức bắt đầu dần dần hồi phục."
  },
  AvgDialog_18720_Content_1 = {
    Text = "11:00, Nghĩa địa hoang Highgate"
  },
  AvgDialog_18720_Content_10 = {
    Text = "Đừng kỳ vọng quá nhiều vào trình độ chuyên môn của thám tử vùng hẻo lánh."
  },
  AvgDialog_18720_Content_11 = {
    Text = "……Có lý."
  },
  AvgDialog_18720_Content_12 = {
    Text = "Cậu lấy kính lúp mang theo ra tiếp tục quan sát bộ xương trắng này."
  },
  AvgDialog_18720_Content_13 = {
    Text = "Trên xương cổ có <Red:vết cắt hình răng cưa>…"
  },
  AvgDialog_18720_Content_14 = {
    Text = "Tuy nhiên rất lộn xộn, còn có nhiều vết cắt chồng chéo, hoàn toàn khác với những gì chúng ta đã thấy trong ảnh trước đó."
  },
  AvgDialog_18720_Content_15 = {
    Text = "Tay nghề còn non nhỉ, phạm tội lần đầu à?"
  },
  AvgDialog_18720_Content_16 = {
    Text = "Trước tiên hãy lấy bãi chôn tập thể làm trung tâm để triển khai điều tra.\nKẻ mới vào nghề chưa thành thạo khi phạm tội lần đầu, thường sẽ không đi xa nhà quá."
  },
  AvgDialog_18720_Content_17 = {
    Text = "Hiểu rồi. Lần này tôi rất tự tin, hung thủ nhất định sẽ sớm sa lưới!"
  },
  AvgDialog_18720_Content_18 = {
    Text = "Hung thủ (murderer)? Cậu dám chắc thế nào, ợ, rằng hung thủ chỉ có một?"
  },
  AvgDialog_18720_Content_19 = {
    Text = "Từ sâu trong rừng rậm bước ra một ông già nồng nặc mùi rượu, mặt đỏ bừng."
  },
  AvgDialog_18720_Content_2 = {
    Text = "Bạn một mình len lỏi giữa nghĩa địa hoang vắng."
  },
  AvgDialog_18720_Content_20 = {
    Text = "Xin lỗi, không cố ý nghe lén cậu nói chuyện một mình."
  },
  AvgDialog_18720_Content_21 = {
    Text = "Tôi là người giữ mộ ở đây, cậu có thể gọi tôi là lão… ợ, <Blue:lão Freeman>."
  },
  AvgDialog_18720_Content_22 = {
    Text = "Chào buổi chiều, ông Freeman.\nÝ ông vừa nói là, hung thủ không chỉ một người?"
  },
  AvgDialog_18720_Content_23 = {
    Text = "Lão Freeman nâng chai rượu tu ừng ực vào cổ họng, cục yết hầu to bự không ngừng trượt lên trượt xuống."
  },
  AvgDialog_18720_Content_24 = {
    Text = "Ợ! Cái khu rừng tồi tàn này cả ngày chẳng thấy bóng người. Hiếm lắm cậu mới đến, vậy thì nghe tôi kể cho mà nghe…"
  },
  AvgDialog_18720_Content_25 = {
    Text = "Đó là khoảng đầu năm nay thì phải……? Tôi cũng không nhớ rõ nữa."
  },
  AvgDialog_18720_Content_26 = {
    Text = "Như thường lệ, tôi uống xong rượu, tìm đại chỗ râm mát rồi ngủ thiếp đi."
  },
  AvgDialog_18720_Content_27 = {
    Text = "Rồi tôi nghe thấy mấy âm thanh kỳ lạ, giống như là……"
  },
  AvgDialog_18720_Content_28 = {
    Text = "<RedItalic:Xèo……cạch cạch……>"
  },
  AvgDialog_18720_Content_29 = {
    Text = "Âm thanh kỳ lạ, rồi sau đó thì sao?"
  },
  AvgDialog_18720_Content_3 = {
    Text = "Quạ bay lướt qua bầu trời u ám ảm đạm, gió thu hiu hắt không ngừng rít gào."
  },
  AvgDialog_18720_Content_30 = {
    Text = "Đừng vội, thám tử nhỏ.\nTôi mở mắt ra……ợ, cậu đoán tôi thấy gì nào?"
  },
  AvgDialog_18720_Content_31 = {
    Text = "Không lẽ trùng hợp vậy, đúng là Kẻ Săn Đầu sao?"
  },
  AvgDialog_18720_Content_32 = {
    Text = "Đúng vậy, là Kẻ Săn Đầu! Hoặc, cũng có thể nói là một người phụ nữ……"
  },
  AvgDialog_18720_Content_33 = {
    Text = "Một người phụ nữ đang cắt đầu Pinoco!"
  },
  AvgDialog_18720_Content_34 = {
    Text = "Rồi cô ta thấy tôi, ợ, thì giống như gặp ma vậy, chạy nhanh hơn ai hết!"
  },
  AvgDialog_18720_Content_35 = {
    Text = "Pinoco tội nghiệp của tôi, cổ chỉ còn nửa lủng lẳng ở đó!"
  },
  AvgDialog_18720_Content_36 = {
    Text = "Haha, <Big:hahahaha……>"
  },
  AvgDialog_18720_Content_37 = {
    Text = "Lão Friedman phát ra một tràng cười vang dội vô cùng, cười đến rơi cả nước mắt."
  },
  AvgDialog_18720_Content_38 = {
    Text = "<SmallShake:Kiên nhẫn, kiên nhẫn……>"
  },
  AvgDialog_18720_Content_39 = {
    Text = "Ợ, ợ! Qua khoảng một tháng, tôi lại nghe thấy âm thanh đó……"
  },
  AvgDialog_18720_Content_4 = {
    Text = "Tìm thấy rồi."
  },
  AvgDialog_18720_Content_40 = {
    Text = "<RedItalic:Xèo xèo……cạch cạch cạch……>"
  },
  AvgDialog_18720_Content_41 = {
    Text = "Lần này đến không phải người phụ nữ đó, mà là một gã đàn ông rất gầy."
  },
  AvgDialog_18720_Content_42 = {
    Text = "Đó mới là tay lành nghề đấy! Một nhát dao xuống……"
