  AvgDialog_18720_Content_43 = {
    Text = "<RedBig:Vèo!> Đầu Pinoco bay mất rồi!"
  },
  AvgDialog_18720_Content_44 = {
    Text = "Nghe có vẻ có hai Kẻ Săn Đầu. Sau đó thì sao?"
  },
  AvgDialog_18720_Content_45 = {
    Text = "Sau đó ư? Chẳng có sau đó gì cả. Đó là toàn bộ câu chuyện của lão Freeman và Kẻ Săn Đầu, ợ."
  },
  AvgDialog_18720_Content_46 = {
    Text = "Lão Freeman mãn nguyện ợ một tiếng, rồi lại nheo đôi mắt vàng đục, nhìn ngắm cậu từ đầu đến chân."
  },
  AvgDialog_18720_Content_47 = {
    Text = "Cậu có vẻ chẳng biết gì cả, thám tử nhỏ tội nghiệp. Cậu đã nghe qua <Red:truyền thuyết về Kẻ Săn Đầu> chưa?"
