  AvgDialog_18720_Content_48 = {
    Text = "Truyền thuyết Kẻ Săn Đầu? Xin hãy kể cho tôi nghe."
  },
  AvgDialog_18720_Content_49 = {
    Text = "Lão Freeman thong thả tựa vào bia mộ, uống hết số rượu còn lại trong chai chỉ trong vài ngụm, rồi tiện tay ném nó xuống đất."
  },
  AvgDialog_18720_Content_5 = {
    Text = "Cậu dừng lại trước một ngôi mộ cô quạnh, nắp quan tài mục nát bên dưới đã bị mở tung từ lâu."
  },
  AvgDialog_18720_Content_50 = {
    Text = "Chất lỏng chảy ra từ chai rượu vỡ, kéo thành vệt ngoằn ngoèo trên mặt đất. Như nước mắt, cũng như máu."
  },
  AvgDialog_18720_Content_51 = {
    Text = "Có người nói, Kẻ Săn Đầu là quái vật được sinh ra từ trận <Yellow:dịch bệnh> năm đó."
  },
  AvgDialog_18720_Content_52 = {
    Text = "Cũng có người nói, Kẻ Săn Đầu không phải một người, cũng không phải hai người."
  },
  AvgDialog_18720_Content_53 = {
    Text = "<Red:Kẻ Săn Đầu là một tổ chức.>"
