  AvgDialog_18720_Content_54 = {
    Text = "Tổ chức?"
  },
  AvgDialog_18720_Content_55 = {
    Text = "Đúng vậy, một tổ chức."
  },
  AvgDialog_18720_Content_56 = {
    Text = "Chúng chỉ xuất hiện trong những đêm mưa tối trời, tiếng bước chân ẩn trong tiếng mưa, chỉ cần lặng lẽ vòng ra sau lưng cậu…"
  },
  AvgDialog_18720_Content_57 = {
    Text = "<RedBig:Rắc!>"
  },
  AvgDialog_18720_Content_58 = {Text = "!!"},
  AvgDialog_18720_Content_59 = {
    Text = "Ha ha ha ha! Sao, chỉ vậy thôi mà đã sợ mất mật rồi à, thám tử nhỏ của tôi?"
  },
  AvgDialog_18720_Content_6 = {
    Text = "Một bộ xương trắng không đầu nằm ngổn ngang trong quan tài, từ lâu đã trở thành thiên đường của rêu xanh và côn trùng."
  },
  AvgDialog_18720_Content_60 = {
    Text = "Lão lảo đảo bước lại gần cậu thêm vài bước. Đôi mắt vàng đục lờ đờ đảo qua đảo lại, như muốn thiêu cháy cậu."
  },
  AvgDialog_18720_Content_61 = {
    Text = "Gã này có gì đó không ổn. Phải rời khỏi đây ngay."
  },
  AvgDialog_18720_Content_62 = {
    Text = "Xin lỗi, ông Freeman. Trời không còn sớm nữa, tôi nghĩ tôi phải đi đây…"
  },
  AvgDialog_18720_Content_63 = {
    Text = "Cậu hít nhẹ một hơi, quay người rời đi không ngoảnh lại."
  },
  AvgDialog_18720_Content_64 = {
    Text = "Phía sau vọng lại tiếng cười chế giễu, nhưng cậu đã chẳng còn tâm trí để bận tâm. Bây giờ cậu chỉ muốn rời khỏi đây."
  },
  AvgDialog_18720_Content_65 = {
    Text = "Trời dần tối sầm lại, mây đen thấp che khuất ánh sáng nhợt nhạt, gió thổi lá cây dập dờn như sóng triều."
  },
  AvgDialog_18720_Content_66 = {
    Text = "Ngay tại cuối nghĩa trang, bạn nhìn thấy một bóng hình vừa quen thuộc vừa xa lạ."
  },
  AvgDialog_18720_Content_67 = {
    Text = "Là Daphodel. Phần lớn khuôn mặt cô ẩn dưới vành mũ sụp thấp, những lọn tóc xám bạc bay nhẹ trong gió."
  },
  AvgDialog_18720_Content_68 = {
    Text = "Thấy bộ dạng tả tơi của bạn, Daphodel vui vẻ bật cười."
  },
  AvgDialog_18720_Content_69 = {
    Text = "Lâu rồi không gặp, Người Giữ Bí Mật{Male=ngài,Female=cô}."
  },
  AvgDialog_18720_Content_7 = {
    Text = "Thời gian phát hiện ghi trong sổ tay là nửa năm trước, thời gian tử vong chắc chắn còn sớm hơn…"
  },
  AvgDialog_18720_Content_8 = {
    Text = "Nói cách khác, đây rất có thể là nạn nhân sớm nhất được biết đến của \"Kẻ Săn Đầu\". Nhưng hồ sơ của sở cảnh sát chưa bao giờ đề cập…"
  },
  AvgDialog_18720_Content_9 = {
    Text = "Nơi này đến một bệnh viện hay nhà tang lễ tử tế cũng không có, cũng chẳng ai coi trọng người chết cho lắm."
  },
  AvgDialog_18721_Content_1 = {
    Text = "Hay thử dùng truy vết tinh thần để tìm Kẻ Săn Đầu?"
