  AvgDialog_18721_Content_2 = {
    Text = "Phương pháp này ít hiệu quả với sinh vật từ Siêu Chiều Giới Vực."
  },
  AvgDialog_18721_Content_3 = {
    Text = "Truy vết tinh thần cũng không phải vạn năng."
  },
  AvgDialog_18722_Content_1 = {
    Text = "Hẹn ngày gặp lại"
  },
  AvgDialog_18722_Content_10 = {
    Text = "<LightGray:Đầu lâu quý giá? Sẽ là của ai nhỉ……>"
  },
  AvgDialog_18722_Content_12 = {
    Text = "Trông cậu có vẻ rất khổ sở, %player%. Có vẻ cậu thực sự muốn biết câu trả lời?"
  },
  AvgDialog_18722_Content_13 = {
    Text = "Cũng bình thường thôi"
  },
  AvgDialog_18722_Content_14 = {
    Text = "Khụ khụ, tôi không phải kiểu người thích tùy tiện dò hỏi chuyện riêng tư của người khác."
  },
  AvgDialog_18722_Content_15 = {
    Text = "Vậy sao? Nhưng biểu cảm của cậu đã tố cáo cậu rồi đấy."
  },
  AvgDialog_18722_Content_16 = {
    Text = "Đúng là muốn biết"
  },
  AvgDialog_18722_Content_17 = {
    Text = "Tôi chỉ muốn hiểu thêm về bà, phu nhân Daphodel."
  },
  AvgDialog_18722_Content_18 = {
    Text = "Ồ? Có ai đó dường như ngày càng tham lam rồi."
  },
  AvgDialog_18722_Content_19 = {
    Text = "Cho cậu một gợi ý nhé: <Yellow:Là thứ cậu đã từng thấy trước đây.>"
  },
  AvgDialog_18722_Content_2 = {
    Text = "Đội chi viện và hội thẩm tra đang trên đường đến rồi, cậu ở lại đây bảo vệ hiện trường trước."
  },
  AvgDialog_18722_Content_20 = {
    Text = "Thứ đã từng thấy……?"
  },
  AvgDialog_18722_Content_21 = {
    Text = "Cậu suy nghĩ miệt mài, những câu chuyện xảy ra trong hai ngày qua, những người đã gặp lướt qua trước mắt cậu như đèn kéo quân."
  },
  AvgDialog_18722_Content_23 = {Text = "!!"},
  AvgDialog_18722_Content_24 = {
    Text = "Chẳng lẽ là trên phố Norwich, cái đầu giống hệt bà……"
