  AvgDialog_18722_Content_25 = {
    Text = "Thông minh lắm."
  },
  AvgDialog_18722_Content_26 = {
    Text = "Nhưng tại sao……Tôi không hiểu."
  },
  AvgDialog_18722_Content_27 = {
    Text = "Daphodel dõi mắt nhìn ra ánh bình minh mờ ảo nơi đường chân trời xa xa, làn gió mát lạnh thổi bay mái tóc dài của nàng."
  },
  AvgDialog_18722_Content_28 = {
    Text = "Đó là một \"tiêu bản\", nó thuộc về chủ nhân trước đây của tôi."
  },
  AvgDialog_18722_Content_29 = {
    Text = "Nói cho cậu một bí mật: khuôn mặt hiện tại của tôi chính là được tạo ra dựa theo nó đấy."
  },
  AvgDialog_18722_Content_3 = {
    Text = "Yên tâm đi, lần này tôi nhất định sẽ ngoan ngoãn đợi, tuyệt đối không chạy lung tung nữa."
  },
  AvgDialog_18722_Content_30 = {Text = "?！"},
  AvgDialog_18722_Content_31 = {
    Text = "<LightGray:Hóa ra đây không phải diện mạo thật sự của phu nhân Daphodel……>"
  },
  AvgDialog_18722_Content_32 = {
    Text = "Lần này cậu đã giúp tôi rất nhiều.\nĐem một Người Giữ Bí Mật non nớt như vậy ra làm mồi nhử, đến giờ tôi vẫn không thể tha thứ cho bản thân mình."
  },
  AvgDialog_18722_Content_33 = {
    Text = "……Không sao, chỉ cần hoàn thành được cuộc điều tra, tôi không ngại bị lợi dụng một lần."
  },
  AvgDialog_18722_Content_34 = {
    Text = "Vậy sao, nhưng tôi rất áy náy đấy. Cho nên……"
  },
  AvgDialog_18722_Content_35 = {
    Text = "Để bù đắp và xin lỗi, tôi có thể đáp ứng một yêu cầu của cậu."
  },
  AvgDialog_18722_Content_36 = {
    Text = "Miễn phí đấy nhé～"
  },
  AvgDialog_18722_Content_37 = {Text = "!!"},
  AvgDialog_18722_Content_38 = {
    Text = "Đứng trước mặt cậu là một thương nhân nổi tiếng tàn nhẫn và tinh ranh, tình báo, tri thức cấm kỵ và bộ sưu tập quý giá mà bà ta nắm giữ là thứ mà biết bao người mơ ước."
  },
  AvgDialog_18722_Content_39 = {
    Text = "Và bây giờ, bà ấy có thể vô điều kiện đáp ứng một yêu cầu của cậu."
  },
  AvgDialog_18722_Content_4 = {
    Text = "Không ngờ cuộc điều tra lại hoàn thành nhanh như vậy.\nLàm tốt lắm, %player%."
  },
  AvgDialog_18722_Content_40 = {
    Text = "<LightGray:Không được……nếu tiểu thư Dorl biết tôi tùy tiện giao dịch với người ngoài, chắc chắn sẽ nổi giận mất.>"
  },
  AvgDialog_18722_Content_41 = {
    Text = "Trong đầu lướt qua vô số khả năng, tạo vật hoàng kim đã thất truyền, chiếc bánh nhỏ ngon nhất, số Leofang khổng lồ……"
  },
  AvgDialog_18722_Content_42 = {
    Text = "Những ý nghĩ hỗn loạn không ngừng đan xen, va chạm, cuối cùng đều rút đi như thủy triều — cậu quyết định tuân theo bản năng trong tim mình."
  },
  AvgDialog_18722_Content_43 = {
    Text = "Đã nghĩ ra yêu cầu chưa? Không được tham lam quá đấy nhé."
  },
  AvgDialog_18722_Content_44 = {
    Text = "Nghĩ ra rồi, yêu cầu của tôi rất đơn giản."
  },
  AvgDialog_18722_Content_45 = {
    Text = "Hãy cho tôi xem diện mạo thật sự của bà đi."
  },
  AvgDialog_18722_Content_47 = {
    Text = "Đơn giản vậy thôi sao? Cậu phải suy nghĩ kỹ đấy, tôi có thể cho cậu rất nhiều thứ, bất kỳ thứ nào cũng có giá trị hơn nó."
  },
  AvgDialog_18722_Content_48 = {
    Text = "Giá trị bao nhiêu, phụ thuộc vào phán đoán của tôi. Ngoài điều này ra, tôi không có yêu cầu nào khác."
  },
  AvgDialog_18722_Content_49 = {
    Text = "Không hổ danh là Người Giữ Bí Mật{Male=ngài,Female=cô}, luôn khiến tôi bất ngờ. Vậy thì……"
  },
  AvgDialog_18722_Content_5 = {
    Text = "Khụ khụ, lần này đều nhờ phu nhân Daphodel."
  },
  AvgDialog_18722_Content_50 = {
    Text = "Daphodel chậm rãi bước về phía bạn. Gió thổi tung mái tóc dài của cô, như những con sóng xám bay lượn lên xuống."
  },
  AvgDialog_18722_Content_51 = {
    Text = "Hai người đứng rất gần nhau, bạn gần như có thể nhìn thấy hình ảnh phản chiếu của mình trong đôi mắt cô."
  },
  AvgDialog_18722_Content_52 = {
    Text = "Nhớ giữ bí mật nhé, %player%."
  },
  AvgDialog_18722_Content_53 = {
    Text = "Lời vừa dứt, gương mặt cô bắt đầu nhòe đi, hòa tan như màu sơn dầu rơi vào nước..."
  },
  AvgDialog_18722_Content_54 = {
    Text = "Cuối cùng, bạn cũng nhìn rõ khuôn mặt của cô."
  },
  AvgDialog_18722_Content_55 = {
    Text = "Đó là một khuôn mặt @2, khiến bạn liên tưởng đến rất nhiều thứ."
  },
  AvgDialog_18722_Content_56 = {
    Text = "Chẳng hạn như làn sương ẩm ướt sau cơn mưa, những bông thủy tiên lặng lẽ nở rộ trong góc khuất, hay như một con thú nhỏ cuộn mình trong bóng tối..."
  },
  AvgDialog_18722_Content_57 = {
    Text = "Bạn chưa kịp nhìn kỹ, khuôn mặt ấy đã như giọt nước rơi xuống mặt nước, lại tan biến mất một lần nữa."
  },
  AvgDialog_18722_Content_58 = {
    Text = "Thì ra... đây mới là diện mạo thật sự của cậu."
  },
  AvgDialog_18722_Content_59 = {
    Text = "Thế nào, có thấy xấu xí không?"
  },
  AvgDialog_18722_Content_6 = {
    Text = "Chỉ là chuyện nhỏ thôi, tôi cũng tìm lại được thứ đã mất."
  },
  AvgDialog_18722_Content_60 = {
    Text = "Bạn lắc đầu."
  },
  AvgDialog_18722_Content_61 = {
    Text = "Thật bất ngờ... nhưng lại là một khuôn mặt rất giống cậu."
  },
  AvgDialog_18722_Content_62 = {
    Text = "Ánh nắng ban mai xua tan hơi ẩm của mưa, toàn thân cô được bao phủ trong quầng sáng dịu dàng."
  },
  AvgDialog_18722_Content_63 = {
    Text = "Thành thật mà nói... lúc nãy tôi thậm chí còn cảm thấy sợ hãi, rồi lại ngạc nhiên vì chính nỗi sợ hãi của mình."
  },
  AvgDialog_18722_Content_64 = {
    Text = "Mười năm, năm mươi năm? Tôi đã không còn nhớ lần cuối cùng mình cảm thấy sợ hãi là bao nhiêu năm trước rồi."
  },
  AvgDialog_18722_Content_65 = {
    Text = "Sợ hãi...? Chẳng lẽ là sợ tôi thấy cậu xấu xí sao?"
  },
  AvgDialog_18722_Content_66 = {
    Text = "Daphodel không đáp, chỉ nhẹ nhàng xoa đầu bạn."
  },
  AvgDialog_18722_Content_67 = {
    Text = "%player%, giờ cậu là người duy nhất trên đời này từng nhìn thấy \"tôi\" đấy."
  },
  AvgDialog_18722_Content_68 = {
    Text = "Hehe, cậu có một điểm yếu nhỏ nằm trong tay tôi rồi đấy."
  },
  AvgDialog_18722_Content_69 = {
    Text = "Nhân lúc chưa mất trí nhớ, tôi phải nhanh chóng vẽ khuôn mặt cậu lên giấy mới được."
  },
  AvgDialog_18722_Content_7 = {
    Text = "Từ góc độ thương nhân mà nói, đây là một \"giao dịch\" hoàn hảo."
  },
  AvgDialog_18722_Content_70 = {
    Text = "Daphodel bật cười, đôi mắt cong thành một đường vòng cung xinh đẹp."
  },
  AvgDialog_18722_Content_71 = {
    Text = "Đúng là một đứa trẻ ngốc nghếch."
  },
  AvgDialog_18722_Content_72 = {
    Text = "Được rồi, bạn bè của cậu ở hội thẩm tra và sở cảnh sát chắc đang trên đường đến rồi nhỉ?"
  },
  AvgDialog_18722_Content_73 = {
    Text = "<Shake:Hóa ra chị biết hết rồi……>"
  },
  AvgDialog_18722_Content_74 = {
    Text = "Tôi không có hứng thú đối phó với mấy cuộc thẩm vấn nhàm chán đó.\nLần sau tìm một nơi không ai quấy rầy, tôi mời cậu một tách cà phê."
  },
  AvgDialog_18722_Content_75 = {
    Text = "Hẹn gặp lại, Người Giữ Gìn của tôi{Male=ngài,Female=cô}."
  },
  AvgDialog_18722_Content_76 = {
    Text = "Hả? Ồ……tạ, tạm biệt, phu nhân Daphodel."
  },
  AvgDialog_18722_Content_77 = {
    Text = "Daphodel vẫy tay chào cậu, rồi quay người rời đi."
  },
  AvgDialog_18722_Content_78 = {
    Text = "Cậu dõi theo bóng lưng thong thả của cô, tâm trạng cũng trở nên nhẹ nhõm."
  },
  AvgDialog_18722_Content_79 = {
    Text = "Màn mây u ám kéo dài cuối cùng cũng tan hết, bầu trời rốt cuộc đã hửng nắng. Ánh dương xuyên qua những đám mây lười biếng, sưởi ấm toàn thân cậu."
  },
  AvgDialog_18722_Content_8 = {
    Text = "Thứ đã mất……"
  },
  AvgDialog_18722_Content_80 = {
    Text = "Không hiểu sao, cậu có một linh cảm—"
  },
  AvgDialog_18722_Content_81 = {
    Text = "Các cậu sẽ còn gặp lại nhau nhiều lần nữa, trong những chiều không gian và thời gian khác nhau."
  },
  AvgDialog_18722_Content_9 = {
    Text = "Kẻ Săn Đầu đã lấy đi từ tôi một <Yellow:chiếc đầu lâu quý giá>, nên tôi đến đây để điều tra một chút. Đơn giản vậy thôi."
  },
  AvgDialog_18723_Content_1 = {
    Text = "Khụ khụ, thể thức tỉnh của Siêu Chiều Giới Vực thật khó đuổi theo……"
  },
  AvgDialog_18723_Content_10 = {
    Text = "Câu trả lời……?"
  },
  AvgDialog_18723_Content_11 = {
    Text = "Nó nhân lúc cậu tạm rời đi, khi tôi và cô Orla đang trò chuyện bên cạnh thì bỏ chạy."
  },
  AvgDialog_18723_Content_12 = {
    Text = "Nhưng không cần lo, đi theo tôi thì cậu sẽ sớm gặp lại nó thôi."
  },
  AvgDialog_18723_Content_13 = {
    Text = "Là ở <Blue:vùng hoang địa phía bắc thị trấn Reini> phải không?"
  },
  AvgDialog_18723_Content_14 = {
    Text = "Ồ? Xem ra thám tử nhỏ của chúng ta khá nhạy bén đấy. Cậu nhận ra bằng cách nào vậy?"
  },
  AvgDialog_18723_Content_15 = {
    Text = "Trên người kẻ đó có hiện tượng dung thực, rất có thể liên quan đến trận dịch bệnh xảy ra ở phía bắc ba năm trước."
  },
  AvgDialog_18723_Content_16 = {
    Text = "Giờ nó bị thương nặng như vậy, lại phải đối mặt với sự truy kích từ cả chúng ta lẫn cảnh sát, những nơi nó có thể đến không còn nhiều."
  },
  AvgDialog_18723_Content_17 = {
    Text = "Bất kể cuối cùng nó có ẩn náu ở hoang địa hay không, nơi đó vẫn là một đầu mối đáng để điều tra."
  },
  AvgDialog_18723_Content_18 = {
    Text = "Không tệ, khá thông minh. Nhưng cậu có biết vùng hoang địa đó rộng bao nhiêu không?"
  },
  AvgDialog_18723_Content_19 = {
    Text = "Gần 50 dặm vuông.\nCậu cũng không muốn kỳ nghỉ quý giá bị lãng phí vào việc thám hiểm địa chất và điều tra dân số chứ?"
  },
  AvgDialog_18723_Content_2 = {
    Text = "Bạn loạng choạng chạy đến một ngã rẽ."
  },
  AvgDialog_18723_Content_20 = {
    Text = "Còn tôi thì tình cờ có thể tìm ra nơi ẩn náu chính xác của nó.\nCậu muốn đi cùng tôi một chuyến không?"
  },
  AvgDialog_18723_Content_21 = {
    Text = "Đừng đồng ý. Cô ta rất nguy hiểm, nhất định đừng bị cô ta mê hoặc."
  },
  AvgDialog_18723_Content_22 = {
    Text = "Tôi đếm đến ba nhé. Ba, hai…"
  },
  AvgDialog_18723_Content_24 = {
    Text = "Tôi đi theo cô."
  },
  AvgDialog_18723_Content_26 = {
    Text = "Ừm, đúng là đứa trẻ ngoan biết nghe lời."
  },
  AvgDialog_18723_Content_27 = {
    Text = "Phu nhân Daphodel, tôi có thể đi cùng các người được không?"
  },
  AvgDialog_18723_Content_28 = {
    Text = "Cô gái gầy yếu bước ra từ bóng cây phía sau các bạn, đôi mắt đầy lo lắng."
  },
  AvgDialog_18723_Content_29 = {
    Text = "Tôi biết cô rất lo lắng cho %player%."
  },
  AvgDialog_18723_Content_3 = {
    Text = "Nơi đây đã không còn bóng dáng của Kẻ Săn Đầu, chỉ còn lại Daphdale và bóng hình kéo dài dưới chân cô."
  },
  AvgDialog_18723_Content_30 = {
    Text = "Nhưng rất tiếc, bông hồng nhỏ của tôi. Lần này tôi chỉ có thể dẫn theo một người."
  },
  AvgDialog_18723_Content_31 = {
    Text = "Đường phố đêm khuya gió lạnh thấu xương, Orlya không khỏi cuốn chặt những tờ thư đủ để chắn gió giữ ấm. Cô ngẩng khuôn mặt nhỏ nhắn tái nhợt, nghiêm túc nhìn Daphodel."
  },
  AvgDialog_18723_Content_32 = {
    Text = "Tại sao? Tuy tôi không giỏi chiến đấu, nhưng thêm một người giúp đỡ vẫn tốt hơn, phải không?"
  },
  AvgDialog_18723_Content_33 = {
    Text = "Tôi chỉ dẫn theo một người. Xin lỗi, bông hồng nhỏ, tôi có lý do của mình."
  },
  AvgDialog_18723_Content_35 = {
    Text = "Phu nhân Daphodel, bà nhất định sẽ hộ tống %player%{Male=ngài,Female=cô} trở về bình an, đúng không?"
  },
  AvgDialog_18723_Content_36 = {
    Text = "Daphodel nhìn những con thiêu thân không ngừng bay lượn dưới ánh đèn đường, thong thả thổi ra một vòng khói tròn từ miệng."
  },
  AvgDialog_18723_Content_37 = {
    Text = "Đương nhiên rồi, yên tâm đi."
  },
  AvgDialog_18723_Content_4 = {
    Text = "Không hiểu sao, bạn cảm thấy cô đã đứng như vậy rất lâu, rất lâu rồi."
  },
  AvgDialog_18723_Content_5 = {
    Text = "Dường như từ thuở hồng hoang xa xưa, cô đã một mình canh giữ nơi đây, lặng lẽ nhìn về phía xa, không nói một lời."
  },
  AvgDialog_18723_Content_6 = {
    Text = "Cậu đến rồi à."
  },
  AvgDialog_18723_Content_7 = {
    Text = "Daphdale quay người lại, biểu cảm vẫn nhạt nhẽo như thường."
  },
  AvgDialog_18723_Content_8 = {
    Text = "Kẻ Săn Đầu đâu? Bị mất dấu rồi à?"
  },
  AvgDialog_18723_Content_9 = {
    Text = "Ừ, mất dấu rồi. Nhưng mà…… tôi nghĩ tôi đã biết câu trả lời rồi."
  },
  AvgDialog_18724_Content_1 = {
    Text = "Đến từ phương xa"
  },
  AvgDialog_18724_Content_10 = {
    Text = "Từ tình trạng thi thể và lời khai nhân chứng, thời gian tử vong của hai người khá gần nhau, không quá nửa giờ."
  },
  AvgDialog_18724_Content_11 = {
    Text = "Còn địa điểm tử vong, có gần nhau không?"
  },
  AvgDialog_18724_Content_12 = {
    Text = "Ramona lắc đầu."
  },
  AvgDialog_18724_Content_13 = {
    Text = "Dù lái xe cũng mất hơn một tiếng, huống chi người có xe trong thị trấn rất ít."
  },
  AvgDialog_18724_Content_14 = {
    Text = "……Có lẽ lão Freeman nói đúng."
  },
  AvgDialog_18724_Content_15 = {
    Text = "Kẻ Săn Đầu là một tổ chức. Nhưng mục đích của chúng rốt cuộc là gì?"
  },
  AvgDialog_18724_Content_16 = {
    Text = "Đầu@2nhiều đầu hơn nữa……"
  },
  AvgDialog_18724_Content_17 = {
    Text = "Phía sau bỗng nổi lên một cơn gió lạnh."
  },
  AvgDialog_18724_Content_18 = {
    Text = "Cậu quay đầu lại, chỉ thấy cái xác đã bị cậu chặt đầu đang lao tới với tốc độ cực nhanh."
  },
  AvgDialog_18724_Content_19 = {Text = "?！"},
  AvgDialog_18724_Content_2 = {
    Text = "00:15, Nhà gỗ của Aurla"
  },
  AvgDialog_18724_Content_20 = {
    Text = "Đưa ta đầu@3đưa@1đầu@4"
  },
  AvgDialog_18724_Content_21 = {
    Text = "Cậu nhanh chóng né sang một bên. Thi thể lao thẳng đâm vỡ kính phía trước, lập tức biến mất trong màn đêm mênh mông."
  },
  AvgDialog_18724_Content_22 = {
    Text = "Tốc độ nhanh thật……Là thể thức tỉnh từ Siêu Chiều Giới Vực sao?"
  },
  AvgDialog_18724_Content_23 = {
    Text = "Đang còn nghi hoặc, một mùi thủy tiên nồng nàn đã bao trùm lấy cậu từng lớp từng lớp."
  },
  AvgDialog_18724_Content_24 = {
    Text = "Tà váy tím bay vụt qua trước mắt cậu, rồi cũng biến mất trước mặt cậu."
  },
  AvgDialog_18724_Content_25 = {
    Text = "Phu nhân Daffodil……?"
  },
  AvgDialog_18724_Content_26 = {
    Text = "Mau đuổi theo, không thể để manh mối quan trọng chạy mất."
  },
  AvgDialog_18724_Content_3 = {
    Text = "Bạn tìm một góc yên tĩnh, giải thích cho Ramona về tình hình vừa xảy ra."
  },
  AvgDialog_18724_Content_4 = {
    Text = "Tất nhiên, bỏ qua phần bạn suýt bị cắt cổ."
  },
  AvgDialog_18724_Content_6 = {
    Text = "Từ chiều đến giờ tôi đã gọi <Red:35> lần rồi, cậu không hề hồi đáp."
  },
  AvgDialog_18724_Content_7 = {
    Text = "Xin lỗi, mọi chuyện xảy ra quá bất ngờ…"
  },
  AvgDialog_18724_Content_8 = {
    Text = "……Lần sau không được như vậy nữa."
  },
  AvgDialog_18724_Content_9 = {
    Text = "Danh tính nạn nhân mới phát hiện ban ngày đã được điều tra rõ.\nThợ mộc Damon Mendez, 35 tuổi; thanh niên vô công rỗi nghề Thomas Quillen, 23 tuổi."
  },
  AvgDialog_18725_Content_1 = {
    Text = "Một chiếc khung ảnh úp ngược thu hút sự chú ý của bạn."
  },
  AvgDialog_18725_Content_10 = {
    Text = "<RedItalic:Chủ nhật lão uống mười chai rượu, mất việc làm, mất luôn cả vợ.>"
  },
  AvgDialog_18725_Content_11 = {
    Text = "Có ai đó khẽ ngân nga một bài đồng dao đều đều không chút biến đổi nhịp điệu."
  },
  AvgDialog_18725_Content_12 = {
    Text = "Giai điệu khô khốc như một bàn tay ẩm ướt vô hình, nhẹ nhàng vuốt ve những sợi lông tóc đã dựng đứng từ lâu trên gáy bạn."
  },
  AvgDialog_18725_Content_13 = {
    Text = "<RedItalic:Lão Freeman khóc oa oa, thứ Hai lại uống mười một chai rượu……>"
  },
  AvgDialog_18725_Content_14 = {
    Text = "Hòa cùng tiếng ván gỗ kẽo kẹt, Harriet lặng lẽ đứng trước hành lang tối tăm."
  },
  AvgDialog_18725_Content_15 = {
    Text = "Đúng vậy, lão Freeman là chồng tôi."
  },
  AvgDialog_18725_Content_16 = {
    Text = "Gì vậy?!"
  },
  AvgDialog_18725_Content_17 = {
    Text = "Lúc đó, tất cả mọi người đều nghĩ tôi đã chết. Chồng tôi cũng vậy."
  },
  AvgDialog_18725_Content_18 = {
    Text = "Sau đó, không biết đã qua bao lâu, tôi lại sống dậy… nhưng tôi đã trở nên khác đi một chút."
  },
  AvgDialog_18725_Content_19 = {
    Text = "Bạn im lặng không nói, trong lòng đã đoán được câu chuyện phía sau."
  },
  AvgDialog_18725_Content_2 = {
    Text = "Từ nhà bếp vọng ra tiếng nước sôi ùng ục, phu nhân Harriet vẫn đang bận rộn trong đó."
  },
  AvgDialog_18725_Content_20 = {
    Text = "Con người sau khi nhiễm Dung Thực, tinh thần sẽ bị tổn thương không thể phục hồi, từ đó dẫn đến đủ loại biến chứng."
  },
  AvgDialog_18725_Content_21 = {
    Text = "Phu nhân Harriet trở nên như thế này cũng không có gì lạ."
  },
  AvgDialog_18725_Content_22 = {
    Text = "Tôi bắt đầu khao khát đầu lâu, rất nhiều đầu lâu… thế là tôi lén chạy đến một bãi chôn xác tập thể."
  },
  AvgDialog_18725_Content_23 = {
    Text = "Tôi nằm sấp trên người lão Pinocchio, dùng lưỡi liềm rỉ sét cố sức cắt đầu lão.\nNhưng lúc đó tôi quá yếu ớt, ngay cả dao cũng cầm không vững…"
  },
  AvgDialog_18725_Content_24 = {
    Text = "Rồi đoán xem tôi đã gặp ai?"
  },
  AvgDialog_18725_Content_26 = {
    Text = "Tôi gặp chồng mình."
  },
  AvgDialog_18725_Content_27 = {
    Text = "Ông ấy béo hơn, cũng già hơn, lại còn trở thành một tên bợm nhậu."
  },
  AvgDialog_18725_Content_28 = {
    Text = "Hehe…… Cái thế đạo này lúc nào cũng tìm đủ mọi cách để hành hạ những kẻ đáng thương như chúng ta."
  },
  AvgDialog_18725_Content_29 = {
    Text = "Hắn xách rượu, nhìn ta như nhìn một con chó hoang."
  },
  AvgDialog_18725_Content_3 = {
    Text = "Bạn nhẹ nhàng lật chiếc khung ảnh lại."
  },
  AvgDialog_18725_Content_30 = {
    Text = "Hắn cứ cười mãi. Đúng vậy, ta biết bộ dạng lúc đó của mình chắc hẳn vừa đáng thương, vừa đáng cười."
  },
  AvgDialog_18725_Content_31 = {
    Text = "Nhưng hắn lại…… hoàn toàn không nhận ra ta nữa."
  },
  AvgDialog_18725_Content_32 = {
    Text = "……Thì ra ngươi chính là kẻ Săn Đầu mà hắn nhắc đến."
  },
  AvgDialog_18725_Content_33 = {
    Text = "Harriet nghiêng đầu sang phải một cách máy móc, từ cổ phát ra tiếng \"cạch cạch cạch\"."
  },
  AvgDialog_18725_Content_34 = {
    Text = "Ừ. Biết rõ hắn đã không còn nhớ ta từ lâu, nhưng vẫn lén chạy đi nhìn trộm hắn."
  },
  AvgDialog_18725_Content_35 = {
    Text = "Rồi ngươi nghe được cuộc trò chuyện của chúng ta, biết ta đang điều tra vụ án mạng, nên mới quyết định bám theo tập kích?"
  },
  AvgDialog_18725_Content_37 = {
    Text = "Ngươi quả nhiên khác với bọn họ. Ta nói nhiều như vậy, mà ngươi vẫn có thể giữ bình tĩnh."
  },
  AvgDialog_18725_Content_38 = {
    Text = "Ngươi thở dài nhẹ, cúi đầu nhìn cánh cửa khóa chặt bên cạnh."
  },
  AvgDialog_18725_Content_39 = {
    Text = "Máu đỏ sẫm như mật đường đặc quánh từ từ rỉ ra từ khe cửa, từng chút một bò đến dưới chân ngươi."
  },
  AvgDialog_18725_Content_4 = {
    Text = "Đây là một bức ảnh gia đình cũ kỹ. Khuôn mặt của người vợ và những đứa trẻ đã mờ nhạt không còn rõ nét, chỉ còn lại người chồng đứng ở phía ngoài cùng bên trái."
  },
  AvgDialog_18725_Content_40 = {
    Text = "Ngươi có biết không……"
  },
  AvgDialog_18725_Content_41 = {
    Text = "Trên sàn, trên trần nhà, trên tủ ở đây…… toàn là mùi máu và mùi xác chết."
  },
  AvgDialog_18725_Content_42 = {
    Text = "Từ khoảnh khắc bước vào, ta đã biết hết mọi thứ rồi."
  },
  AvgDialog_18725_Content_5 = {
    Text = "Ông ấy vóc dáng vạm vỡ, tư thế thư thái tựa vào ngôi nhà mới vừa xây xong, nở nụ cười rạng rỡ trước ống kính."
  },
  AvgDialog_18725_Content_6 = {
    Text = "Bạn nhìn đôi mắt và đường nét gương mặt hơi quen thuộc của ông ta, một ý nghĩ hoang đường bỗng lóe lên trong đầu như tia chớp."
  },
  AvgDialog_18725_Content_7 = {
    Text = "Lão Freeman……?!"
  },
  AvgDialog_18725_Content_8 = {
    Text = "Chẳng lẽ ông ta là chồng của phu nhân Harriet?"
  },
  AvgDialog_18725_Content_9 = {
    Text = "<RedItalic:Lão Freeman, lão Freeman, tên bợm nhậu vừa nghèo vừa điên lão Freeman……>"
  },
  AvgDialog_18726_Content_1 = {
    Text = "Ngươi bước sâu vào con hẻm, nước mưa đã sớm làm ướt đẫm chiếc áo khoác."
  },
  AvgDialog_18726_Content_10 = {
    Text = "Tách, tách, tách."
  },
  AvgDialog_18726_Content_11 = {
    Text = "Từ con đường bên ngoài hẻm vọng đến tiếng bước chân thong thả, một bóng hình mờ ảo xuất hiện dưới ánh đèn đường."
  },
  AvgDialog_18726_Content_12 = {
    Text = "Chỗ này nguy hiểm, mau rời—"
  },
  AvgDialog_18726_Content_13 = {
    Text = "Đó là một người phụ nữ."
  },
  AvgDialog_18726_Content_14 = {
    Text = "Cô ta đứng một mình dưới ánh đèn đường, tay xách một cái đầu béo phị, kích thước hoàn toàn khớp với cổ của xác không đầu phía sau ngươi."
  },
  AvgDialog_18726_Content_15 = {
    Text = "Máu tươi từ cổ chiếc đầu nhỏ tách tách xuống, chảy chậm rãi theo kẽ gạch trên mặt đường."
  },
  AvgDialog_18726_Content_16 = {
    Text = "Đứng yên tại chỗ.\nNgươi là ai?"
  },
  AvgDialog_18726_Content_17 = {
    Text = "Ánh đèn đường vàng vọt liên tục chớp tắt, phát ra tiếng điện rì rì khó chịu."
  },
  AvgDialog_18726_Content_18 = {
    Text = "Người phụ nữ ngẩng đầu lên, ngươi cuối cùng cũng nhìn rõ gương mặt cô ta."
  },
  AvgDialog_18726_Content_2 = {
    Text = "Máu đỏ sẫm chảy ra từ bóng tối, vươn những xúc tu gớm ghiếc, gửi đến ngươi lời mời gọi câm lặng."
  },
  AvgDialog_18726_Content_20 = {
    Text = "<Gray:Daph…… Phu nhân Daphdale?>"
  },
  AvgDialog_18726_Content_3 = {
    Text = "Nơi đây rất yên tĩnh, ngươi chỉ nghe thấy tiếng mưa, tiếng bước chân và tiếng thở."
  },
  AvgDialog_18726_Content_4 = {
    Text = "Chúng như những nhịp trống rối loạn đan xen, ngày càng nhanh, ngày càng lớn, cho đến khi ngươi đến cuối con hẻm."
  },
  AvgDialog_18726_Content_5 = {
    Text = "Xác chết béo phị bị vứt bừa bãi trên đống rác, mềm nhũn rũ xuống."
  },
  AvgDialog_18726_Content_6 = {
    Text = "Vết cắt ở cổ mờ nhòe không rõ, từng dòng máu đỏ sẫm ứa ra từ mạch máu."
  },
  AvgDialog_18726_Content_7 = {
    Text = "Không cần chạm vào, ngươi cũng biết máu đó chắc chắn còn ấm nóng."
  },
  AvgDialog_18726_Content_8 = {
    Text = "Đầu bị mất, trên cổ có vết thương hình răng cưa…"
  },
  AvgDialog_18726_Content_9 = {
    Text = "Là \"Kẻ Săn Đầu\"."
