  AvgDialog_18727_Content_10 = {
    Text = "Nếu bà ấy không nói dối hay nhìn nhầm thì đúng vậy."
  },
  AvgDialog_18727_Content_11 = {
    Text = "<Blue:Đội tiên phong> đã đến thị trấn Reini từ một tuần trước, và phát hiện dấu hiệu Ngân Tâm hoạt động tại hiện trường tử vong."
  },
  AvgDialog_18727_Content_12 = {
