  AvgDialog_18727_Content_16 = {
    Text = "Mới 8 giờ tối mà tất cả cửa nẻo xung quanh đều khóa chặt cứng. Nỗi sợ hãi tràn ra từ những ô cửa sổ tối đen, lặng lẽ bao trùm khắp nơi."
  },
  AvgDialog_18727_Content_17 = {
    Text = "Ngoài một hai tiếng chó sủa kéo dài, nơi đây tĩnh lặng vô thanh."
  },
  AvgDialog_18727_Content_18 = {
    Text = "Tí tách tí tách……"
  },
  AvgDialog_18727_Content_19 = {
    Text = "Ơ, mưa rồi sao?"
  },
  AvgDialog_18727_Content_2 = {
    Text = "Beren·Stoke, 46 tuổi, ngày 12 tháng 9 chết tại nhà bếp trong nhà.\n<Red:Đầu bị mất>, phần còn lại của thi thể nguyên vẹn, cổ có vết cắt hình răng cưa."
  },
  AvgDialog_18727_Content_20 = {
    Text = "Những hạt mưa lạnh nhẹ rơi từ bầu trời đêm, phủ trước mặt bạn một lớp màn trắng mỏng manh."
  },
  AvgDialog_18727_Content_21 = {
    Text = "Tôi nghe thấy tiếng mưa bên phía cậu. Có mang ô không?"
