  AvgDialog_18727_Content_22 = {
    Text = "<Shake:Tệ thật. Cậu luôn là người mang ô, nên……>"
  },
  AvgDialog_18727_Content_23 = {
    Text = "Có vẻ tôi cần phải thích nghi với cuộc sống không có cậu bên cạnh."
  },
  AvgDialog_18727_Content_25 = {
    Text = "Xin lỗi, lần này không thể đi cùng cậu được."
  },
  AvgDialog_18727_Content_26 = {
    Text = "Cô Doyle kiên quyết giữ tôi ở lại, cùng cô ấy thực hiện một số nghiên cứu dung thực được cho là \"rất quan trọng\"……"
  },
  AvgDialog_18727_Content_27 = {
