  AvgDialog_18727_Content_33 = {
    Text = "Ờ……vậy cô Orla cũng sẽ tham gia điều tra sao?"
  },
  AvgDialog_18727_Content_34 = {
    Text = "Không phải thể thức tỉnh nào cũng hứng thú với nhiệm vụ ngoại cần. Nếu cậu thấy cần thiết, có thể hỏi ý kiến cô ấy."
  },
  AvgDialog_18727_Content_35 = {
    Text = "Tình hình hiện tại vẫn ổn định và kiểm soát được, không cần phải——"
  },
  AvgDialog_18727_Content_36 = {
    Text = "Xoạt——"
