  AvgDialog_18727_Content_37 = {
    Text = "Từ con hẻm phía trước bỗng vang lên tiếng máu thịt bắn tung, tiếp theo là tiếng bước chân hỗn loạn, đột ngột phá vỡ sự yên tĩnh của đêm khuya."
  },
  AvgDialog_18727_Content_38 = {Text = "?！"},
  AvgDialog_18727_Content_39 = {
    Text = "Giờ này, âm thanh này……chẳng lẽ là……"
