  },
  AvgDialog_18796_Content_14 = {
    Text = "Đây là cảnh chuyển dài nhất, dài nhất ~"
  },
  AvgDialog_18796_Content_15 = {
    Text = "Đó là tất cả các hiệu ứng chuyển cảnh rồi đó, mọi người đã hiểu chưa?"
  },
  AvgDialog_18796_Content_16 = {
    Text = "Chúng ta gặp lại vào kỳ sau"
  },
  AvgDialog_18796_Content_2 = {
    Text = "Dưới đây xin mời chuyển cảnh số 1——chuyển cảnh từ trái sang phải~!"
  },
  AvgDialog_18796_Content_3 = {
    Text = "Cầm cầm cầm! Sao nào, có phải rất hoa lệ không!"
  },
  AvgDialog_18796_Content_4 = {
    Text = "Chuyển cảnh này thường được sử dụng để chuyển đổi giữa các cảnh trong cùng một bối cảnh."
  },
  AvgDialog_18796_Content_5 = {
    Text = "Đây là chuyển cảnh số 2 ——"
  },
  AvgDialog_18796_Content_6 = {
    Text = "Cảnh chuyển này thường được sử dụng để chuyển sang cảnh sáng hơn."
  },
  AvgDialog_18796_Content_7 = {
    Text = "Rồi đến……số 3 chuyển cảnh!"
  },
  AvgDialog_18796_Content_8 = {
    Text = "Sự chuyển cảnh số 3 cũng phù hợp để chuyển sang cảnh sáng hơn, tuy nhiên nhịp độ sẽ chậm hơn một chút, hihi."
  },
  AvgDialog_18796_Content_9 = {
    Text = "Người tiếp theo đi về phía chúng ta là——4 cảnh chuyển!"
  },
  AvgDialog_18797_Content_1 = {
    Text = "Mị…@1…Ưm…"
  },
  AvgDialog_18797_Content_10 = {
    Text = "Bạn không phải là \"Thần Vương\" sao!"
  },
  AvgDialog_18797_Content_11 = {
    Text = "Rốt cuộc, với tư cách là người mà Miriam phụng sự, dự ngôn về sự tái sinh của thần minh chính là do ngài đưa ra đúng không?"
  },
  AvgDialog_18797_Content_12 = {Text = "Bạn…"},
  AvgDialog_18797_Content_13 = {
    Text = "Tôi vừa thấy... qua liên kết, tôi đã thấy ký ức của bạn."
  },
  AvgDialog_18797_Content_14 = {Text = "……là."},
  AvgDialog_18797_Content_15 = {
    Text = "Là lời tiên tri mà Yu đã đưa ra, nhưng không có gì gọi là \"thần dụ\" cả."
  },
  AvgDialog_18797_Content_16 = {Text = "Cái gì?"},
  AvgDialog_18797_Content_17 = {
    Text = "Sớm trước khi trận lũ đến, dư đã mất khả năng nhìn thấu tương lai từ giấc mơ của thần minh. \nDư không biết Ngài đã đi đâu, có thể Ngài đã tỉnh dậy, hoặc đã rời đi."
  },
  AvgDialog_18797_Content_18 = {
    Text = "Lời tiên tri của bạn…"
  },
  AvgDialog_18797_Content_19 = {
    Text = "Miriam là một tín đồ, cô sinh ra để phục vụ thần quốc, và được thúc đẩy bởi ý chí của Dư."
  },
  AvgDialog_18797_Content_2 = {
    Text = "Muphí phát ra tiếng rên rỉ đau đớn, lời thì thầm đứt quãng."
  },
  AvgDialog_18797_Content_20 = {
    Text = "Ta chỉ hy vọng những lời đó có thể an ủi nỗi sợ hãi của nàng trước khi chết, chưa từng nghĩ rằng nàng sẽ luôn xem đó như kim chỉ nam, ý định tái lập thần quốc."
  },
  AvgDialog_18797_Content_21 = {
    Text = "Tất cả điều này đều như vậy……"
  },
  AvgDialog_18797_Content_22 = {
    Text = "Đúng, tất cả đều là lỗi lầm của ta."
  },
  AvgDialog_18797_Content_23 = {
    Text = "Đếm ngược 1 giờ"
  },
  AvgDialog_18797_Content_3 = {
    Text = "!Đây là gì?!"
  },
  AvgDialog_18797_Content_4 = {
    Text = "Dấu vết đáng sợ màu xanh đen hiện lên trên khuôn mặt của Muphí, giống như hệ thống rễ cây ăn sâu vào dưới da của cô."
  },
  AvgDialog_18797_Content_5 = {
    Text = "Ngài đã bắt đầu ngăn chặn dòng máu của vật chủ."
  },
  AvgDialog_18797_Content_6 = {
    Text = "Chẳng phải chỉ cần tránh xa thiên thể là được rồi sao?"
  },
  AvgDialog_18797_Content_7 = {
    Text = "Ý của Dư là, có lẽ cô ấy sẽ không cảm thấy quá khó chịu."
  },
  AvgDialog_18797_Content_8 = {
    Text = "Thiên thể đã vào quỹ đạo, không thể quay đầu lại."
  },
  AvgDialog_18797_Content_9 = {
    Text = "Có phải là không còn cách nào khác sao?"
  },
  AvgDialog_18798_Content_1 = {
    Text = "Thở... thở……không thấy ở trên, cũng không thấy ở dưới……"
  },
  AvgDialog_18798_Content_10 = {
    Text = "Muphí lập tức buông lỏng sức, dựa vào thành tàu trượt xuống boong, không còn để ý đến tư thế ngồi có đoan trang hay không."
  },
  AvgDialog_18798_Content_11 = {
    Text = "Cô ấy muốn tìm một điểm tựa để không bị ngã, sau một hồi mò mẫm, cô ấy dựa vào vai bạn."
  },
  AvgDialog_18798_Content_12 = {
    Text = "Một chút thôi…"
  },
  AvgDialog_18798_Content_13 = {
    Text = "Chưa đầy vài giây, bên tai đã vang lên hơi thở gấp gáp nhưng đều đặn. \nMurphy lại mất đi ý thức."
  },
  AvgDialog_18798_Content_14 = {
    Text = "Cô ấy càng ngày càng yếu ớt…"
  },
  AvgDialog_18798_Content_15 = {
    Text = "Thần linh mà ta kết nối đến từ muôn vàn ngôi sao, dù chỉ là bản sao không hoàn hảo, cũng không phải là điều con người có thể kháng cự."
  },
  AvgDialog_18798_Content_16 = {
    Text = "Thật sự không có cách nào để giảm bớt sao?"
  },
  AvgDialog_18798_Content_17 = {
    Text = "……đưa cô ấy xuống."
  },
  AvgDialog_18798_Content_18 = {
    Text = "Xa khỏi thiên thể, có thể cô ấy sẽ cảm thấy tốt hơn."
  },
  AvgDialog_18798_Content_2 = {
    Text = "Họ… hỗn… cuối cùng ở đâu rồi?"
  },
  AvgDialog_18798_Content_3 = {
    Text = "<Small:ghét chết được…… con tàu này sao mà lớn thế này……>"
  },
  AvgDialog_18798_Content_4 = {
    Text = "Bạn có khỏe không?"
  },
  AvgDialog_18798_Content_5 = {
    Text = "Tôi rất khỏe! Khụ, khụ khụ…"
  },
  AvgDialog_18798_Content_6 = {
    Text = "Muphí nâng giọng trả lời bạn, nhưng không may bị hụt hơi và ho dữ dội."
  },
  AvgDialog_18798_Content_7 = {
    Text = "Nhưng tôi mệt lắm, đầu còn đau nữa."
  },
  AvgDialog_18798_Content_8 = {
    Text = "Trong khi nói, bạn đã ngồi xuống tại chỗ."
  },
  AvgDialog_18798_Content_9 = {
    Text = "Vậy, vậy nghỉ ngơi một chút đi... chỉ một chút thôi.."
  },
  AvgDialog_18802_Content_1 = {
    Text = "Nếu tôi mạnh hơn một chút, nếu tôi có thể luôn kháng cự lại hắn... \nNhưng tôi không thể.."
  },
  AvgDialog_18802_Content_10 = {
    Text = "Xin lỗi... Xin lỗi... Đều là tại tôi... Đều là lỗi của tôi.."
  },
  AvgDialog_18802_Content_11 = {
    Text = "Tôi là một con quái vật vô dụng, tôi đã hại chết nhiều người như vậy, nhưng tôi thậm chí không thể cứu chị của Jenkin"
  },
  AvgDialog_18802_Content_12 = {
    Text = "Cô ấy bị đưa đi, cô ấy bị đưa đi, nhưng tôi thậm chí còn không biết cô ấy đi đâu……\nTôi cũng không rõ ai đang kiểm soát chúng tôi…"
  },
  AvgDialog_18802_Content_13 = {
    Text = "Ramona quỳ trước Ai Jī Sī, nhẹ nhàng ôm cô bé vào lòng"
  },
  AvgDialog_18802_Content_14 = {
    Text = "Bạn đã cố gắng rất nhiều rồi, Ái Cơ Tư. Đó không phải là lỗi của bạn"
  },
  AvgDialog_18802_Content_15 = {
    Text = "Đó là lỗi của tên Jack the Ripper thực sự, kẻ đã điều khiển bạn và phạm phải những tội ác đó. \n Điều đó chưa bao giờ là lỗi của bạn"
  },
  AvgDialog_18802_Content_16 = {
    Text = "Cô gái lao vào lòng Ramona khóc lớn, tay phải vẫn che mắt mình"
  },
  AvgDialog_18802_Content_17 = {
    Text = "Chúng tôi sẽ tìm thấy người đó thôi"
  },
  AvgDialog_18802_Content_18 = {
    Text = "Chúng tôi sẽ tìm thấy anh ta, rồi bắt anh ta trả giá. \nTôi hứa với bạn"
  },
  AvgDialog_18802_Content_19 = {
    Text = "Cảm ơn, cảm ơn các bạn… cảm ơn các bạn…"
  },
  AvgDialog_18802_Content_2 = {
    Text = "Lần trước tôi chống lại anh ta, nhưng cuối cùng… tôi không thể làm được hu hu…"
  },
  AvgDialog_18802_Content_20 = {
    Text = "Ánh hoàng hôn vàng rực xuyên qua mặt đồng hồ lớn trong suốt của tháp chuông, rọi lên người cô gái"
  },
  AvgDialog_18802_Content_21 = {
    Text = "Ai Ji Xư quay người sang một bên, đặt một tay lên kính, nheo mắt lại đón ánh nắng ấm áp"
  },
  AvgDialog_18802_Content_22 = {
    Text = "Hôm nay, có thể nhìn thấy mặt trời đấy…"
  },
  AvgDialog_18802_Content_24 = {
    Text = "Dường như được khích lệ bởi một ngày nắng hiếm hoi, cô ấy chống dậy thân thể, lảo đảo bước tới một tấm kính sạch sẽ hơn."
  },
  AvgDialog_18802_Content_25 = {
    Text = "Vista mờ ảo cuối cùng trở nên rõ ràng, cô ấy nhìn những con đường quen thuộc hoặc xa lạ, trong lúc mơ màng, tai dường như vang lên tiếng thì thầm của ai đó."
  },
  AvgDialog_18802_Content_26 = {
    Text = "Nhìn này, tiếng nói ấy nói rằng, tối nay chắc chắn sẽ thấy bầu trời đầy sao lấp lánh."
  },
  AvgDialog_18802_Content_28 = {
    Text = "Cô gái cúi đầu, nở một nụ cười đầy hoài niệm."
  },
  AvgDialog_18802_Content_29 = {
    Text = "Trước đây, mỗi khi có thể nhìn thấy mặt trời, Tiyug sẽ lén đưa tôi lên đây vào ban đêm."
  },
  AvgDialog_18802_Content_3 = {
    Text = "Đừng làm như vậy nữa, đừng ép buộc mạnh mẽ tôi làm những việc như thế này nữa"
  },
  AvgDialog_18802_Content_30 = {
    Text = "Cô Sara không bao giờ cho phép chúng tôi đến đây, cô ấy nói rằng nơi này quá nguy hiểm, chúng tôi rất dễ bị thương. Nhưng Tiyug chẳng màng những điều đó."
  },
  AvgDialog_18802_Content_31 = {
    Text = "Mắt anh ấy rất tốt, dù ở nơi tối tăm nhất vẫn nhìn rõ đường."
  },
  AvgDialog_18802_Content_32 = {
    Text = "Anh ta giống như Jenkin, thông minh và dũng cảm, luôn biết những con đường nhỏ và bẫy mà người khác không biết."
  },
  AvgDialog_18802_Content_33 = {
    Text = "Chừng nào có anh ấy dẫn đường, chúng ta sẽ không bị cô Sara phát hiện."
  },
  AvgDialog_18802_Content_34 = {
    Text = "Chừng nào còn có anh ấy dẫn đường, nơi đây sẽ mãi là nơi trú ẩn bí mật của chúng ta."
  },
  AvgDialog_18802_Content_35 = {
    Text = "Anh ấy bảo tôi phải tiếp xúc nhiều hơn với những ngôi sao, pháp lực mới có thể mạnh mẽ. \nDù rằng chúng tôi không thể nhìn thấy ngôi sao nào ở đây."
  },
  AvgDialog_18802_Content_36 = {
    Text = "Lúc đó, anh ấy là người duy nhất tin tôi. \nTin rằng tôi có thể nhìn thấy những dấu hiệu hắc ám, và nói với tôi rằng đó là năng lực đặc biệt của phù thủy."
  },
  AvgDialog_18802_Content_37 = {
    Text = "Sau đó, các bác sĩ bắt đầu đưa bệnh nhân ra ngoài và không còn khám chữa bệnh tại nhà thương nghèo nữa. Tôi cũng không thể thu thập bằng chứng, không thể trả thù cho Tiyug."
  },
  AvgDialog_18802_Content_38 = {
    Text = "Nếu tôi thông minh như anh ta, can đảm như Jenkin, có lẽ đã sớm tra rõ sự thật rồi."
  },
  AvgDialog_18802_Content_39 = {
    Text = "Nhưng tôi không phải là phù thủy."
  },
  AvgDialog_18802_Content_4 = {
    Text = "Tôi không muốn gây thương tích cho người khác, cũng không muốn giết người"
  },
  AvgDialog_18802_Content_40 = {
    Text = "Tôi chỉ là một người nhút nhát."
  },
  AvgDialog_18802_Content_41 = {
    Text = "Một con quái vật."
  },
  AvgDialog_18802_Content_42 = {
    Text = "Một……người đã gây ra cái chết."
  },
  AvgDialog_18802_Content_43 = {
    Text = "Các người có biết đây là lần thứ mấy tôi bị người ta điều khiển không? \nCác người có biết trên tay tôi đã có bao nhiêu vết máu không?"
  },
  AvgDialog_18802_Content_44 = {
    Text = "Tôi sợ hãi vô cùng, sợ chính mình sẽ trở thành điều gì đó."
  },
  AvgDialog_18802_Content_46 = {
    Text = "Trước đây mắt tôi rất đau, thân thể cũng rất đau. Nhưng bây giờ tôi không còn cảm thấy gì cả, giống như tôi cũng là đá vậy."
  },
  AvgDialog_18802_Content_48 = {
    Text = "Chết tiệt, một hai người đều chạy đi đâu rồi…"
  },
  AvgDialog_18802_Content_49 = {Text = "Đó là.."},
  AvgDialog_18802_Content_5 = {
    Text = "<Shake:<AvgNormalFont:Không! Đừng! \nĐừng để Tiểu Mạch làm như vậy, cậu bé còn nhỏ như vậy, sao có thể……<Shake:Làm ơn……>>>"
  },
  AvgDialog_18802_Content_50 = {
    Text = "Ai Jī Sī?! Ai Jī Sī—— !"
  },
  AvgDialog_18802_Content_51 = {
    Text = "Giọng của Jenkin bỗng nhiên vang lên từ dưới tháp chuông, không biết cô ấy đã xuất hiện trong sân từ khi nào."
  },
  AvgDialog_18802_Content_52 = {
    Text = "Cô ấy lo lắng kêu to tên Ai Jī Sī, dang rộng hai tay hướng về bầu trời."
  },
  AvgDialog_18802_Content_53 = {
    Text = "Thân thể nhỏ bé của cô gái trong quá trình rơi đã vĩnh viễn biến mất khỏi bầu trời đêm này."
  },
  AvgDialog_18802_Content_54 = {
    Text = "Một con chim bay qua bầu trời đêm, biến mất trong làn sương dày, không để lại dấu vết."
  },
  AvgDialog_18802_Content_55 = {
    Text = "Đôi tay Jenkin đưa ra chỉ ngơ ngác ôm lấy chiếc váy trống rỗng của Ai Jī Sī và những mảnh giấy hình chữ nhật rơi rớt xuống như những bông tuyết."
  },
  AvgDialog_18802_Content_56 = {
    Text = "Ai…… Ai Jī Sī……? \nSao lại…… sao lại……"
  },
  AvgDialog_18802_Content_57 = {
    Text = "Giấy mỏng được vẽ con bướm vàng, mép nhăn nheo được người ta tỉ mỉ ấn phẳng và gấp gọn gàng, khi nhẹ nhàng rơi xuống, mang theo hương ngọt ngào của kẹo."
  },
  AvgDialog_18802_Content_58 = {
    Text = "Hừm…… Ai Jī Sī…………"
  },
  AvgDialog_18802_Content_59 = {
    Text = "Dải lụa nhuốm máu rơi xuống tay cô gái cùng với giấy kẹo, nó khẽ lay động theo gió, nhẹ nhàng chạm vào đầu ngón tay cô, tựa như một sự an ủi dịu dàng đến từ ai đó."
  },
  AvgDialog_18802_Content_6 = {
    Text = "Tôi không nghe thấy, tôi không nghe thấy, tôi không nghe thấy nữa—"
  },
  AvgDialog_18802_Content_60 = {
    Text = "Cô gái nháy mắt, những giọt nước mắt làm mờ đi ánh nhìn qua lớp nước mắt rơi từ mi mắt, được vệt màu đỏ rực ôm lấy một cách lặng lẽ."
  },
  AvgDialog_18802_Content_61 = {
    Text = "Màu sắc quen thuộc này, cảm giác quen thuộc này——chỉ thiếu một chiếc khóa bạc hình vuông để có thể hoàn toàn trùng khớp với ký ức của cô ấy."
  },
  AvgDialog_18802_Content_62 = {
    Text = "……chị……?"
  },
  AvgDialog_18802_Content_7 = {
    Text = "Thành, thành công rồi? \n Bạn mau chạy đi, nhanh lên, nhưng làm ơn đừng nói với ai cả"
  },
  AvgDialog_18802_Content_8 = {
    Text = "<Shake:<AvgNormalFont:đợi đã, không đúng, đây là cái gì! Đầu tôi, đầu tôi…\nA… A a…!<Shake:A——!!>>>"
  },
  AvgDialog_18802_Content_9 = {
    Text = "Xin lỗi… thật sự xin lỗi…"
  },
  AvgDialog_18804_Content_1 = {
    Text = "Người giữ bí mật đường đường, bị mấy đứa trẻ bình thường trộm sạch sành sanh, một năm huấn luyện coi như uổng phí, học sinh mới của trường tiểu học công lập còn thông minh hơn cậu nhiều."
