  AvgDialog_18809_Content_1 = {
    Text = "Muphí không e thẹn mà, cô kéo Ramona sang một bên và bắt đầu cởi bỏ lớp áo ngoài. \nKhi chiếc cúc cuối cùng ở ngực được mở ra, Ramona nhìn thấy \"vị thần\" bên trong cô gái trẻ."
  },
  AvgDialog_18809_Content_2 = {
    Text = "Ở vị trí ngực rõ ràng có một mảng da trong suốt, mảng da trong suốt này kéo căng và làm biến dạng da và cơ bắp xung quanh, khiến toàn bộ vùng ngực và bụng đều mang một màu trắng xám héo úa."
  },
  AvgDialog_18809_Content_3 = {
    Text = "Như vậy, hiện tượng kỳ lạ này để lộ rõ các cơ quan trong lồng ngực, Ramona nhìn thấy một trái tim trẻ tuổi màu đỏ nhạt và một \"trứng\" màu sữa."
  },
  AvgDialog_18809_Content_4 = {
    Text = "Số lượng sợi tơ không đếm được từ \"trứng\" chui ra, bị cuốn vào mạch máu của Muphí một cách chặt chẽ, tạo nên sự tương hỗ."
  },
  AvgDialog_18809_Content_5 = {
    Text = "Nếu không phải sự tồn tại của nó đã chèn ép vào tim Muphí, trông nó như thể hòa làm một với lồng ngực trong suốt, không giống một vật thể lạ."
  },
  AvgDialog_18809_Content_6 = {
    Text = "Nó hỗn loạn mà yên tĩnh, hình tam giác ngược màu đen khắc trên đó cũng đông cứng lại, giống như một tác phẩm nghệ thuật lạ kỳ."
  },
  AvgDialog_18809_Content_7 = {
    Text = "Rỗng rỗng… cái này đã bị hòa tan rồi."
  },
  AvgDialog_18809_Content_8 = {
    Text = "Đã xem đủ chưa?"
  },
  AvgDialog_18809_Content_9 = {
    Text = "Xin lỗi, là tôi mạo muội, nhanh chóng mặc quần áo vào nhé."
  },
  AvgDialog_18810_Content_1 = {
    Text = "Còn 20 phút nữa"
