  AvgDialog_18810_Content_10 = {
    Text = "Cẩn thận! Đừng rơi xuống biển!"
  },
  AvgDialog_18810_Content_11 = {
    Text = "Con rắn khổng lồ vượt qua mặt biển, suýt chút nữa đã làm lật cả con tàu. \n Nhiều đầu rắn bay lượn và uốn éo, đổ xuống boong tàu những bóng tối đáng sợ."
  },
  AvgDialog_18810_Content_12 = {
    Text = "Kẻ vượt quyền… kẻ vô lễ… kẻ ngu dại!"
