  AvgDialog_18810_Content_13 = {
    Text = "Thần mẫu……thần mẫu……@3!"
  },
  AvgDialog_18810_Content_14 = {
    Text = "Chết rồi, là Miriam!"
  },
  AvgDialog_18810_Content_15 = {
    Text = "Nhanh chóng đưa Muphí xuống!"
  },
  AvgDialog_18810_Content_16 = {Text = "À!"},
  AvgDialog_18810_Content_17 = {
    Text = "Khi bạn quay đầu nhìn về phía boong tàu phía sau, nơi mà bóng dáng của Muphí đã biến mất. Đầu rắn khổng lồ cắn lấy cô gái, kéo cô xuống biển sâu."
  },
  AvgDialog_18810_Content_2 = {
    Text = "Liên kết? Có phải là ý nghĩa cô ấy sẽ dựa vào bạn để sống không?"
  },
  AvgDialog_18810_Content_3 = {
    Text = "Chỉ là biện pháp tạm thời, chúng tôi không có ý định chuyển giao Hilaster từ ngài."
