  AvgDialog_18810_Content_5 = {
    Text = "Hilaster, bạn có đồng ý không?"
  },
  AvgDialog_18810_Content_6 = {
    Text = "Giống như bị một từ khóa kích hoạt, Hilaster ngẩng đầu lên, nhưng lại nhìn về phía đại dương phía sau, hành trình cũng dừng lại."
