  AvgDialog_18826_Content_1 = {
    Text = "Trong đám đông hỗn loạn, Ramona vất vả chống trả những công nhân có dấu hiệu bất thường để giúp các công nhân khác thoát hiểm an toàn."
  },
  AvgDialog_18826_Content_2 = {
    Text = "Y tá!Nhanh gọi y tá!"
  },
  AvgDialog_18826_Content_3 = {
    Text = "Các bước chân vội vã vang lên, vài người mặc đồng phục đặc biệt đi ngược dòng người, họ cầm dây thừng trong tay, biểu cảm nghiêm trọng."
  },
  AvgDialog_18826_Content_4 = {
    Text = "Ở sau lưng họ là một bóng hình mặc áo trắng."
  },
  AvgDialog_18826_Content_5 = {
    Text = "Cô Mary, cẩn thận!"
  },
  AvgDialog_18826_Content_6 = {
    Text = "Ramona né người một cái, lợi dụng đà tấn công của công nhân bất thường, đẩy mạnh về phía trước, dùng đầu kiếm chưa rút ra đặt lên xương ngực, buộc đối phương phải lùi lại vài bước."
  },
  AvgDialog_18826_Content_7 = {
    Text = "Sau lưng cô, các nhân viên chăm sóc đã dừng lại."
