  AvgDialog_18826_Content_8 = {
    Text = "Tôi sẽ phối hợp với các bạn, cùng chuẩn bị nhé."
  },
  AvgDialog_18827_Content_1 = {
    Text = "Sương mù nhuốm máu"
  },
  AvgDialog_18827_Content_10 = {
    Text = "Nhìn thấy khuôn mặt hơi mơ hồ của Ai Jī Sī, Jenkin thở dài nặng nề, lấy bình trà nặng trĩu trên khay, dùng vải bọc lại và ôm vào lòng."
