  AvgDialog_18827_Content_13 = {Text = "Ừ, ừ!"},
  AvgDialog_18827_Content_14 = {
    Text = "20:27, phường Lily\nsân trước"
  },
  AvgDialog_18827_Content_15 = {
    Text = "… các người thật sự tin cô gái đó, định chờ ở đây cho cái bóng đen ngòm kia à?"
  },
  AvgDialog_18827_Content_16 = {
    Text = "Xét đến dấu ăn mòn dị thường xuất hiện trong xưởng lao động phường, cũng như \"nhà nghiên cứu\" đã biến mất, việc theo dõi thực sự là một lựa chọn hợp lý."
  },
  AvgDialog_18827_Content_17 = {
    Text = "……được rồi, dù sao lãng phí cũng là thời gian của các người. \nNói về chủ đề vừa nãy, các người không phát hiện ra thảm họa trong phường không?"
  },
  AvgDialog_18827_Content_18 = {
    Text = "Chìa khóa bạc không có phản ứng, tôi đoán thực thể sức sống không rõ không phải là thảm họa mới sinh, mà có lẽ liên quan nhiều hơn đến dấu ăn mòn đặc biệt và \"nhà nghiên cứu\" kia."
  },
  AvgDialog_18827_Content_19 = {
    Text = "Tôi chưa bao giờ thấy dấu ăn mòn như thế này, trông nó thậm chí hơi giống một nỗ lực vá víu vụng về. \nCòn thuốc chế ngự dị biến thể của anh ta… thực tế, tôi có chút nghi ngờ liệu họ có thể can thiệp vào quá trình rỗng rỗng hay không."
  },
  AvgDialog_18827_Content_2 = {
    Text = "20:27,xưởng Lily\nphòng ăn phường"
  },
  AvgDialog_18827_Content_20 = {
    Text = "Không có thảm họa nhưng có rỗng rỗng, dấu ăn mòn dạng khâu may… Có lẽ là họ?"
  },
  AvgDialog_18827_Content_21 = {
    Text = "Từ khóa đã được đọc thành công, \"dấu ăn mòn dạng khâu\", có tổng cộng 37 sự kiện liên quan. \n Từ khóa sự kiện: <Blue:hành động tổ chức ác tính, Hiệp hội Điêu khắc gia>."
  },
  AvgDialog_18827_Content_22 = {
    Text = "Họ không phải đã bị tiêu diệt trong cuộc hành động chung giữa Misaque và <Blue:hội nghị thẩm tra> cách đây 14 năm rồi sao?"
  },
  AvgDialog_18827_Content_23 = {
    Text = "Hành động ban đầu đã có sơ suất, khiến nhóm chủ chốt của họ trốn thoát. Suốt nhiều năm nay, đội điều tra vẫn không tìm thấy tung tích của họ, thật không ngờ lại có thể gặp ở đây."
  },
  AvgDialog_18827_Content_24 = {
    Text = "Tính chất của sự việc đã thay đổi, các người chuẩn bị rút lui đi. \nNhớ kỹ đừng hành động bốc đồng, bằng không tôi sẽ là người đầu tiên ép tập thêm cho các người."
  },
  AvgDialog_18827_Content_25 = {
    Text = "Đợi đã, đóa——"
  },
  AvgDialog_18827_Content_26 = {
    Text = "Giáo sư Đóa đã ra đi, bạn có muốn để lại tin nhắn?"
  },
  AvgDialog_18827_Content_27 = {
    Text = "Thật sự giống như ở trong phòng thí nghiệm. \nKhông cần để lại lời nhắn nữa, cảm ơn Erika."
  },
  AvgDialog_18827_Content_28 = {
    Text = "Bộ đàm im lặng, bạn nhìn Ramona và thấy trong mắt cô ấy cảm xúc giống bạn."
  },
  AvgDialog_18827_Content_29 = {
    Text = "Đây là nhiệm vụ của chúng ta."
  },
  AvgDialog_18827_Content_3 = {
    Text = "Tôi thật sự không hiểu, vừa giúp việc bếp núc lại vừa phải đưa cơm cho Rogers. \nBạn thích làm việc đến vậy sao? Không ngừng nghỉ một chút nào."
  },
  AvgDialog_18827_Content_30 = {
