  AvgDialog_18827_Content_32 = {
    Text = "Bạn biết rằng tôi chắc chắn sẽ ủng hộ quyết định của bạn, bất kể đó là gì. \nTôi tin tưởng bạn, %player%."
  },
  AvgDialog_18827_Content_33 = {
