  AvgDialog_18827_Content_35 = {
    Text = "20:35, xưởng làm việc của Lily\nphường hành lang"
  },
  AvgDialog_18827_Content_36 = {
    Text = "Bạn định làm gì cho cậu bé Mike đến đâu vậy? Đừng mỗi lần cậu ấy kêu đói là bạn lại đưa cả bữa tối của mình cho cậu ấy!"
