  AvgDialog_18827_Content_37 = {
    Text = "Tôi ăn ít bữa cũng không sao, Việt Tiểu Mạch nhỏ vậy, ăn nhiều một chút mới khỏe, mới không bị bệnh."
  },
  AvgDialog_18827_Content_38 = {
    Text = "Bạn có lớn lắm không? Nếu tôi không trộm tiền của %player% để mua bánh kẹo cho bạn, bạn sẽ không biết phải đói đến khi nào!"
  },
  AvgDialog_18827_Content_39 = {
    Text = "Nhưng cậu ấy rất ngoan, sau khi ăn no sẽ vui vẻ gọi tôi là chị, và còn tặng tôi một quà tặng nữa."
  },
  AvgDialog_18827_Content_4 = {
    Text = "Jenkin dựa vào cạnh bàn dài phân thức ăn, nhìn Ai Jī Sī và một vài y tá cùng đầu bếp đang tất bật làm việc."
  },
  AvgDialog_18827_Content_40 = {
