  AvgDialog_18827_Content_46 = {
    Text = "Khiến tôi bất giác nhớ lại đêm đầu tiên chúng ta gặp nhau."
  },
  AvgDialog_18827_Content_47 = {
    Text = "20:35, phường Lily \n sân trước"
  },
  AvgDialog_18827_Content_48 = {
    Text = "Thời tiết này…… người sống sót đó có phải đã nói rằng, đêm họ gặp nạn cũng đột nhiên xuất hiện sương mù như vậy không?"
  },
  AvgDialog_18827_Content_49 = {
    Text = "Ánh sáng yếu ớt từ đèn pin không thể xuyên qua làn sương nước, mọi thứ xung quanh mờ mịt, khó phân biệt, bạn không thể nhìn rõ cánh cửa sắt gần đó."
