  AvgDialog_18829_Content_8 = {
    Text = "Đang tìm kiếm, đợi chút nhé."
  },
  AvgDialog_18829_Content_9 = {
    Text = "Ngoài việc tiêu diệt các thể dị biến, có thể thử sử dụng chìa khóa bạc để ảnh hưởng đến tinh thần của các thể dị biến và thể dị biến đặc biệt."
