  AvgDialog_18830_Content_1 = {
    Text = "Cô Sara—— Cô Sara, cô hãy tỉnh lại, cô nhìn tôi đi, cô Sara——"
  },
  AvgDialog_18830_Content_2 = {
    Text = "Biến thể này có lẽ đã được kích hoạt bởi cảm xúc mạnh mẽ và vẫn giữ được một phần trí tuệ. \n Tôi chưa bao giờ thấy biểu hiện như vậy, khác hẳn các biến thể khác."
  },
  AvgDialog_18830_Content_3 = {
    Text = "Cái gì dị biến thể, cái thứ gì, gì cơ chứ!"
  },
  AvgDialog_18830_Content_4 = {
    Text = "Lưu ý đừng để cô ta lách qua, nếu gặp phải người bình thường thì nguy rồi."
  },
  AvgDialog_18830_Content_5 = {
    Text = "Đi đến hầm vừa rồi, xem có cách nào làm cho cô ấy bình tĩnh lại không."
  },
  AvgDialog_18830_Content_6 = {
    Text = "Cô Sara! Xin hãy đừng làm hại cô Sara!"
