  AvgDialog_18831_Content_24 = {Text = "!"},
  AvgDialog_18831_Content_25 = {
    Text = "Lưỡi dao sắc bén phản chiếu ánh sáng lạnh, thân dao ngắn hiển thị rõ khuôn mặt bạn. \nPhản xạ có điều kiện từ quá trình huấn luyện giúp bạn kịp thời lách mình né tránh và nhìn rõ bóng dáng của người tới."
