  },
  AvgDialog_18831_Content_28 = {
    Text = "Đồng thời, động tác của cô ấy lại dị thường nhanh nhẹn. Lưỡi dao lạnh giá vẽ nên một cung đường trong không khí, không để bạn kịp suy nghĩ, cô gái lại lao tới phía bạn."
  },
  AvgDialog_18831_Content_29 = {
    Text = "Tránh ngay"
  },
  AvgDialog_18831_Content_3 = {
    Text = "Ánh trăng trong phòng bỗng trở nên mờ ảo, như có một lớp sương mỏng che phủ. \nMột người đột nhiên ngồi dậy từ giường, đánh thức cả không gian yên bình trong căn phòng."
  },
  AvgDialog_18831_Content_30 = {
    Text = "Ramona, tỉnh lại đi!"
  },
  AvgDialog_18831_Content_31 = {
    Text = "Bạn lùi lại bên cạnh Ramona và lắc mạnh vai cô ấy."
  },
  AvgDialog_18831_Content_32 = {
    Text = "Sao...? Có chuyện gì vậy?"
  },
  AvgDialog_18831_Content_33 = {
    Text = "Là Jenkin, cô ấy đột nhiên tấn công tôi!"
  },
  AvgDialog_18831_Content_34 = {
    Text = "Thức tỉnh Ramona"
  },
  AvgDialog_18831_Content_35 = {
    Text = "Chết tiệt, như vậy…"
  },
  AvgDialog_18831_Content_36 = {
    Text = "Bạn nhắm mắt lại, tập trung tinh thần, chìa khóa bạc trước ngực lóe sáng nhẹ."
  },
  AvgDialog_18831_Content_37 = {
    Text = "Mối quan hệ được duy trì bởi liên kết tinh thần, dù cách xa hàng ngàn dặm, hay giữa tỉnh thức và mộng mơ, cũng sẽ đáp lại người gọi."
  },
  AvgDialog_18831_Content_38 = {Text = "Ramona!"},
  AvgDialog_18831_Content_4 = {
    Text = "……Jenkin?"
  },
  AvgDialog_18831_Content_40 = {
    Text = "Lưỡi kiếm va chạm, Ramona chặn được con dao nhỏ. Cô hơi nghiêng đầu, liếc mắt kiểm tra bạn có an toàn không."
  },
  AvgDialog_18831_Content_41 = {
    Text = "Không sao chứ?"
  },
  AvgDialog_18831_Content_42 = {
    Text = "Bạn đã thức dậy rất đúng lúc."
  },
  AvgDialog_18831_Content_43 = {Text = "Jenkin?"},
  AvgDialog_18831_Content_44 = {
    Text = "Jenkin không trả lời, lại một lần nữa giơ con dao lên."
  },
  AvgDialog_18831_Content_45 = {
    Text = "Dường như chỉ còn cách khiến cô ta khuất phục rồi mới có thể hỏi chuyện. Dẫn cô ta ra ngoài!"
  },
  AvgDialog_18831_Content_5 = {
    Text = "Tiếng động nhẹ của việc mặc quần áo là phản ứng duy nhất của cô ấy. Ai Jī Sī xoa đôi mắt sưng đỏ, nhìn thấy Jenkin nhảy xuống giường và bước ra ngoài cửa."
  },
  AvgDialog_18831_Content_6 = {
    Text = "Chít chít? chít chít chít!"
  },
  AvgDialog_18831_Content_7 = {
    Text = "Jenkin, bạn... bạn định đi toilet?"
  },
  AvgDialog_18831_Content_8 = {
    Text = "Dường như hoàn toàn không nghe thấy câu hỏi của bạn đồng hành và tiếng kêu lo lắng của chuột đồng loại, Jenkin đeo ba lô lên vai rồi mở cửa ra, mặt không hề biểu lộ cảm xúc."
  },
  AvgDialog_18831_Content_9 = {
    Text = "Khuôn mặt của Ai Jī Sī lập tức xanh xao."
  },
  AvgDialog_18832_Content_1 = {
    Text = "Trong bóng tối, có một hình dáng nhỏ màu trắng co ro."
  },
  AvgDialog_18832_Content_10 = {
    Text = "Hãy từ bỏ đi, nhắm mắt lại, mọi thứ hãy giao cho tôi. \nSara, Tiểu Mic… tất cả mọi người trong phường của các bạn sẽ hóa thành vẻ đẹp và sự vĩnh hằng."
  },
  AvgDialog_18832_Content_100 = {
    Text = "Dải ruy băng buộc trên tay tuột ra, bay theo gió. Thân thể nhỏ bé của cô gái trong lúc rơi xuống đã mãi mãi hòa tan vào bầu trời đêm tĩnh lặng này."
  },
  AvgDialog_18832_Content_101 = {
    Text = "Chiếc váy trắng nhẹ bẫng, cùng với những mảnh giấy hình vuông rơi rải rác, từ từ đáp xuống tay Jenkin."
  },
  AvgDialog_18832_Content_102 = {
    Text = "Không để lại chút dư nhiệt nào."
  },
  AvgDialog_18832_Content_103 = {
    Text = "Ai… Ai Jī Sī…?"
  },
  AvgDialog_18832_Content_104 = {
    Text = "Giấy vẽ hình con bướm màu vàng, mép giấy nhăn nheo được người ta với sự chăm sóc ép phẳng và gấp gọn, thậm chí còn mang theo hương thơm ngọt ngào của kẹo."
  },
  AvgDialog_18832_Content_105 = {
    Text = "Làm sao…… Làm sao có thể……"
  },
  AvgDialog_18832_Content_106 = {
    Text = "Dải lụa màu đỏ đậm rơi xuống tay cô gái cùng với giấy kẹo, nó nhẹ nhàng vuốt ve qua đầu ngón tay của cô, giống như một sự an ủi dịu dàng đầy xúc cảm từ ai đó."
  },
  AvgDialog_18832_Content_107 = {
    Text = "Cô gái nháy mắt, những giọt nước mắt từ mi mắt mờ đi và rơi xuống, được bông hoa đỏ rực thầm lặng đón nhận."
  },
  AvgDialog_18832_Content_108 = {
    Text = "Ai Jī Sī……"
  },
  AvgDialog_18832_Content_11 = {
    Text = "Không được, không thể…! Xin hãy dừng lại, đừng như vậy, không được!"
  },
  AvgDialog_18832_Content_12 = {
    Text = "Chú chuột nhỏ kia là bạn của cậu phải không? Vì cậu đã giúp tôi thu thập rất nhiều tài liệu, tôi có thể ưu tiên biến cô ấy thành vĩnh cửu, thoát khỏi khổ đau."
  },
  AvgDialog_18832_Content_13 = {
    Text = "Không được! Đừng làm thương họ! Xin hãy! Tôi sẵn sàng làm bất cứ điều gì, bất cứ thứ gì!"
  },
  AvgDialog_18832_Content_14 = {
    Text = "Từng có thời gian tôi cũng cầu xin anh ấy, nhưng rồi sau đó tôi đã hiểu được lý tưởng của anh ấy. \nTôi tin rằng bạn cũng sẽ hiểu cho tôi, dù sao, ngoài việc này ra, bạn còn có thể làm gì khác?"
  },
  AvgDialog_18832_Content_15 = {Text = "Ta——"},
  AvgDialog_18832_Content_16 = {
    Text = "Kháng cự? Tinh thần của bạn sắp không chịu nổi nữa rồi, nếu không phải như vậy, tôi cũng không thể ảnh hưởng đến bạn khi bạn tỉnh táo."
  },
  AvgDialog_18832_Content_17 = {
    Text = "Thôi, hãy từ bỏ đi. Sau đó, bạn có thể giúp tôi biến tất cả mọi người ở đây thành nguồn tài nguyên quý báu."
  },
  AvgDialog_18832_Content_18 = {
    Text = "Hình dáng lớn lao đứng im ở xa, bạn nhanh chóng lấy ra chìa khóa bạc, bất chấp sự can ngăn của Đóa và Ramona, ném nó lên không trung."
  },
  AvgDialog_18832_Content_19 = {
    Text = "Chiếc chìa khóa bạc lơ lửng trong không trung, toả ra ánh sáng dịu nhẹ. Bạn nhắm mắt, chìm sâu vào bóng tối băng giá."
  },
  AvgDialog_18832_Content_2 = {
    Text = "Ông Charlie có một con mèo vằn mà ông rất yêu quý. Một ngày nọ, cô ấy biến mất, ông đã đi khắp mọi nơi để tìm cô ấy…"
  },
  AvgDialog_18832_Content_20 = {
    Text = "Sự phản chiếu bạc xung quanh bạn dần dần biến mất, chỉ còn lại một điểm sáng yếu ớt lơ lửng trước mặt bạn. \nBạn nghiêng tai lắng nghe, như thể nghe thấy tiếng thì thầm của một cô gái."
  },
  AvgDialog_18832_Content_21 = {
    Text = "Tôi muốn bảo vệ mọi người, bảo vệ cô Sara, bảo vệ cậu Mike nhỏ, bảo vệ Jenkin. \n Tôi không muốn họ trở thành tượng sáp."
  },
  AvgDialog_18832_Content_22 = {
    Text = "Tôi sẽ bảo vệ họ, dù phải trả giá bằng mọi thứ——"
  },
  AvgDialog_18832_Content_23 = {
    Text = "Bạn cố gắng chạm vào điểm nhỏ đó, chìa khóa bạc rung lên, như một sự đáp lại nào đó."
  },
  AvgDialog_18832_Content_24 = {
    Text = "…cái gì vậy?"
  },
  AvgDialog_18832_Content_25 = {
    Text = "Cô gái ngẩng mặt lên, phát hiện trước mặt xuất hiện một chiếc chìa khóa nhỏ màu bạc, nó quay chậm rãi, tỏa sáng vừa dịu dàng vừa rực rỡ như ngôi sao."
  },
  AvgDialog_18832_Content_26 = {
    Text = "Cô ấy cố gắng di chuyển cánh tay, chống dưới thân thể. \n Bóng tối bao quanh cô từ mọi phía, ép chặt, giam giữ cô tại chỗ, không thể cử động."
  },
  AvgDialog_18832_Content_27 = {
    Text = "Đồ chơi đặc biệt. Đừng nhúc nhích, Ai Jī Sī, tôi còn chưa muốn mất đi công cụ hữu ích như bạn. \nNếu bạn tiếp tục như vậy, bạn sẽ không bao giờ gặp lại đồng đội của mình. Điều đó có sao không?"
  },
  AvgDialog_18832_Content_28 = {
    Text = "Tôi không nghe... Tôi sẽ không bao giờ nghe nữa."
  },
  AvgDialog_18832_Content_29 = {
    Text = "Dù tôi không thể ăn kẹo nữa, không gặp lại mọi người ở phường, không thấy Jenkin. \n Dù có chuyện gì xảy ra với tôi đi nữa."
  },
  AvgDialog_18832_Content_3 = {
    Text = "Tôi sẽ làm được câu tiếp theo! Anh ta lục tủ quần áo rồi nhìn dưới giường."
  },
  AvgDialog_18832_Content_30 = {
    Text = "Tôi cũng tuyệt đối không để bạn làm thương họ thêm lần nào nữa."
  },
  AvgDialog_18832_Content_31 = {
    Text = "Chìa khóa bạc lấp lánh dữ dội, cô gái đột ngột chống đỡ thân thể, mơ hồ nghe thấy tiếng vật gì đó bị xé rách."
  },
  AvgDialog_18832_Content_32 = {
    Text = "Khẩu trang che mắt từ từ rơi xuống, những màu sắc ngọ nguậy thay thế cho bóng tối, một con ngươi trắng bệch khổng lồ xuất hiện dưới thân thể cô, đã dõi theo cô lâu rồi."
  },
  AvgDialog_18832_Content_33 = {
    Text = "Bạn là… mắt?"
  },
  AvgDialog_18832_Content_34 = {
    Text = "Thật sự có thể mượn lực lượng cho tôi không? \n……không sao, dù chỉ một lát, tôi cũng…có điều muốn nói với họ."
  },
  AvgDialog_18832_Content_35 = {
    Text = "Cảm ơn cậu."
  },
  AvgDialog_18832_Content_36 = {
    Text = "Ai Jī Sī nhúc nhích, thực sự mở mắt ra."
  },
  AvgDialog_18832_Content_37 = {
    Text = "Sau tiếng hú chói tai và đau đớn, thân thể khổng lồ của quái vật tan rã thành chất lỏng đen và sụp đổ. Chất lỏng biến thành bột phấn, bay lên cao rồi làm đen các dầm gỗ."
  },
  AvgDialog_18832_Content_38 = {
    Text = "Bạn ngã xuống đất một cách vô lực, cố chịu đựng cơn đau đầu từng đợt và cảm giác buồn nôn kéo đến ngay sau đó."
  },
  AvgDialog_18832_Content_39 = {Text = "%player%!"},
  AvgDialog_18832_Content_4 = {
    Text = "Ai Jī Sī, nhìn xem tôi đã làm gì cho bạn? Dây bịt mắt này đẹp hơn cái trước đúng không."
  },
  AvgDialog_18832_Content_40 = {
    Text = "Sức mạnh tinh thần đã cạn kiệt rồi à? Tôi đã nói là đừng liều lĩnh mà. \n Công việc ngoại trường không giống như ở trường, nếu bạn gặp rắc rối thì không ai có thể giúp bạn dọn dẹp."
  },
  AvgDialog_18832_Content_41 = {
    Text = "Đừng lo lắng về tôi, mau đi xem Ai Ji Si."
  },
  AvgDialog_18832_Content_42 = {
    Text = "Âm thanh bốc hơi của chất lỏng dần dần yếu đi, không lâu sau đó hoàn toàn biến mất. \n Trên sàn nhà dính chất nhầy màu đen, cô gái ngồi yên."
  },
  AvgDialog_18832_Content_43 = {
    Text = "Ramona……và……%player%.\nThật tốt là các người không sao."
  },
  AvgDialog_18832_Content_44 = {
    Text = "Thật lòng tôi rất xin lỗi. Nếu tôi nói ra sớm hơn, thừa nhận sớm hơn, có lẽ mọi chuyện đã kết thúc từ lâu rồi."
  },
  AvgDialog_18832_Content_45 = {
    Text = "Tôi không gây thương cho bất kỳ ai khác, phải không? Tôi… tôi cũng coi là đã kháng cự thành công, đúng không?"
  },
  AvgDialog_18832_Content_46 = {
    Text = "Vâng, bạn rất dũng cảm, rất giỏi. Bạn đã bảo vệ mọi người ở xưởng."
  },
  AvgDialog_18832_Content_47 = {
    Text = "Được rồi... như vậy, chỉ còn lại một việc nữa. \nTôi sẽ nói cho các bạn biết, tất cả những gì tôi biết."
  },
  AvgDialog_18832_Content_48 = {
    Text = "<Small:Tôi phải… tranh thủ thời gian…>"
  },
  AvgDialog_18832_Content_49 = {
    Text = "Không biết từ ngày nào, tiếng nói bí ẩn ấy đã xuất hiện. \nNó luôn đến vào những đêm sương mù dày đặc. Sau đó, len lỏi vào suy nghĩ của chúng tôi và điều khiển chúng tôi làm những việc xấu."
  },
  AvgDialog_18832_Content_5 = {
    Text = "Ai Jī Sī, Ai Jī Sī! Hôm nay có mặt trời, chắc chắn có thể nhìn thấy sao trời!"
  },
  AvgDialog_18832_Content_50 = {
    Text = "Lần đầu tiên tôi phát hiện, là vào một đêm khi tôi thức dậy đi vệ sinh, bé Lucy đang cầm một con dao. Tôi nhìn cô ấy giấu con dao vào tủ quần áo, sau đó trực tiếp leo lên giường ngủ."
  },
  AvgDialog_18832_Content_51 = {
    Text = "Tôi sợ cô ấy bị mắng vì bộ đồ ngủ bẩn, nên đã giúp cô ấy thay quần áo và ga giường. Cô ấy bị tôi đánh thức và còn hỏi tại sao phải thay, giống như là... hoàn toàn không biết mình đã làm gì."
  },
  AvgDialog_18832_Content_52 = {
    Text = "Tôi sợ khủng khiếp, vừa muốn nói với cô Sara, lại sợ cô Sara phạt bé Lucy, càng sợ cô Sara không tin tôi…"
  },
  AvgDialog_18832_Content_53 = {
    Text = "Thế nên, cuối cùng tôi đã chẳng nói gì cả."
  },
  AvgDialog_18832_Content_54 = {
    Text = "Sau khi chuyện đó xảy ra với bé Lucy, đã nhiều ngày trôi qua mà không có chuyện gì xảy ra vào ban đêm. Tôi cứ nghĩ là mọi thứ đã ổn, nhưng rồi một ngày tôi tỉnh dậy và phát hiện mình đang cầm một cái dao."
  },
  AvgDialog_18832_Content_55 = {
    Text = "Một chị gái ngã ngồi xuống trước mặt tôi. Chị ấy đang khóc, cầu xin, tôi muốn dừng lại, nhưng…"
  },
  AvgDialog_18832_Content_56 = {
    Text = "Tôi không thể làm được."
  },
  AvgDialog_18832_Content_57 = {
    Text = "Chừng nào giọng hát đó còn vang lên, tôi không thể làm được."
  },
  AvgDialog_18832_Content_58 = {
    Text = "Giọng nói phát hiện tôi vẫn còn \"thức\", rất vui mừng, nó nói tôi có tài năng, bảo tôi phải ngoan ngoãn nghe lời, nếu không nó sẽ biến mọi người thành đá, thành \"nguyên liệu\" của nó."
  },
  AvgDialog_18832_Content_59 = {
    Text = "Tôi nói rằng tôi sẽ báo cho cô Sara, nhưng nó lại cười, bảo tôi thử xem liệu có ai tin không."
  },
  AvgDialog_18832_Content_6 = {
    Text = "Ai Jī Sī, thỉnh thoảng bướng bỉnh một chút cũng không sao cả. Hiểu chưa?"
  },
  AvgDialog_18832_Content_60 = {
    Text = "Giọng nói là đúng, trong những việc xấu, dường như luôn đúng."
  },
  AvgDialog_18832_Content_61 = {
    Text = "Không ai tin tôi, không ai nhớ những gì đã xảy ra vào ban đêm. Và mỗi khi màn sương bao phủ, mỗi khi bài hát đó vang lên trong đầu chúng ta, sẽ có đứa trẻ bị giọng nói mê hoặc dẫn dắt, rời bỏ phường."
  },
  AvgDialog_18832_Content_62 = {
    Text = "Mỗi đứa trẻ trở về đều đầy máu, mỗi đứa trẻ bị kiểm soát đều là \"kẻ phân thây\". \nCó những đứa còn nhỏ hơn cả tôi, nếu thực sự bị cảnh sát bắt đi…"
  },
  AvgDialog_18832_Content_63 = {
    Text = "Tôi không thể để chuyện đó xảy ra."
  },
  AvgDialog_18832_Content_64 = {
    Text = "Vì vậy tôi đã giấu tất cả những thứ bị nhuốm máu vào sân sau. Tôi không thể chống lại tiếng thì thầm, ít nhất, tôi có thể bảo vệ họ không bị cảnh sát đưa đi."
  },
  AvgDialog_18832_Content_65 = {
