  AvgDialog_18850_Content_42 = {
    Text = "Khi bị bệnh thì phải đi khám và điều trị theo đúng triệu chứng. Vì các bạn đều có thể nhìn thấy những thứ màu đen, nên tất cả đều cần được chữa trị để mau chóng khỏe lại, phải không?"
  },
  AvgDialog_18850_Content_43 = {
    Text = "Không… Tí Uóc, Tí Uóc anh ta căn bản không nhìn thấy…! Buông ra! \n Các người cứ tiếp tục như vậy, tôi, tôi, tôi sẽ nói với cô Sara!"
  },
  AvgDialog_18850_Content_44 = {
    Text = "Không thấy? Không ngờ lại là một cậu nhóc thích nói dối. \nVì anh ta không thấy, thì——"
  },
  AvgDialog_18850_Content_45 = {
    Text = "Ai Jī Sī! Cẩn thận phía sau!"
  },
  AvgDialog_18850_Content_47 = {
    Text = "—— cứ để bạn làm vậy."
  },
  AvgDialog_18850_Content_48 = {
    Text = "Ừ…… đây là…"
  },
  AvgDialog_18850_Content_49 = {
    Text = "Ánh sáng mạnh mẽ khiến người ta không tự chủ được mà muốn nhắm mắt lại, Ai Jī Sī cố gắng chớp mắt nhưng phát hiện ra mình không thể làm được."
  },
  AvgDialog_18850_Content_5 = {
    Text = "Tôi là…… Misaque……"
  },
  AvgDialog_18850_Content_50 = {
    Text = "Có thứ gì đó giữ chặt mắt cô, cô chỉ có thể trơ mắt nhìn người đàn ông mặc áo trắng xuất hiện trong tầm nhìn, tay cầm một con dao mỏng."
  },
  AvgDialog_18850_Content_51 = {
    Text = "<Big:không, đừng, cô Sara, cô Sara!>"
  },
  AvgDialog_18850_Content_52 = {
    Text = "Dao bạc di chuyển theo tay của nhà nghiên cứu, vẽ nên một vệt sáng bạc dài lấp lánh."
  },
  AvgDialog_18850_Content_53 = {
    Text = "<Big:Cô Sara! Tiyug! Cứu tôi! Cứu tôi với! Cứu tôi!>"
  },
  AvgDialog_18850_Content_54 = {
    Text = "Đỉnh dao càng lúc càng gần, càng lúc càng gần, cho đến khi chiếm lấy toàn bộ tầm nhìn. \nRồi ——"
  },
  AvgDialog_18850_Content_55 = {
    Text = "<Shake:À———!>"
  },
  AvgDialog_18850_Content_56 = {
    Text = "Trong bóng tối vô tận, cô ấy lơ lửng một mình, như bị nước hồ lạnh lẽo bao quanh từ mọi phía.\n\nCác chi của cô ấy tê cứng, không thể cử động."
  },
  AvgDialog_18850_Content_57 = {
    Text = "Đau quá trời……mắt khó chịu thật……"
  },
  AvgDialog_18850_Content_58 = {
    Text = "Màu sắc rực rỡ, giống như đang ngọ nguậy, lan tỏa từng chút một. Màu sắc đó là một chất lỏng đặc quánh, được hòa lẫn từ cả máu và nước mắt, chảy róc rách không ngừng."
  },
  AvgDialog_18850_Content_59 = {
    Text = "Tôi đã sai, tôi rõ ràng là một kẻ vô dụng… không nên… không nên làm những việc mình không thể làm được…"
  },
  AvgDialog_18850_Content_6 = {Text = "!?"},
  AvgDialog_18850_Content_60 = {
    Text = "Nó thay thế nước hồ, thay thế không khí, thay thế mùi vị, âm thanh, xúc giác, sức sống. \n Nó trở thành tất cả những gì cô ấy có và ban cho cô ấy một cái ôm đầy đau đớn."
  },
  AvgDialog_18850_Content_61 = {
    Text = "Cô Sara…… Tyug…… Cứu tôi với…… Tôi đau đớn quá…… Khó chịu tột cùng……"
  },
  AvgDialog_18850_Content_62 = {
    Text = "Màu sắc cuồn cuộn bay lên, cô ấy đột nhiên rơi vào bức màn ánh sáng trắng. Xung động không thuộc về cô ấy hóa thành muôn vàn màu sắc tràn vào mắt cô, cô ấy cố gắng che mắt lại nhưng không thể cử động."
  },
  AvgDialog_18850_Content_63 = {
    Text = "Bạn là……ai……?"
  },
  AvgDialog_18850_Content_64 = {
    Text = "Đau đớn quá mức cuối cùng hóa thành tê dại, không biết đã qua bao lâu, cô ấy cuối cùng cũng lắng nghe được một tiếng động nhỏ trong sự tĩnh lặng."
  },
  AvgDialog_18850_Content_65 = {
    Text = "Có thể thấy mắt của @2, đây thực sự là nguyên liệu tốt nhất. \nNếu không phải Sara và thằng nhóc này luôn chắn ngang, đã sớm lấy nó để làm thí nghiệm rồi."
  },
  AvgDialog_18850_Content_66 = {
    Text = "Bây giờ cũng chưa muộn, Bác sĩ, chúng ta cuối cùng đã @4@2 rồi, điều này đáng để ăn mừng!"
  },
  AvgDialog_18850_Content_67 = {
    Text = "Tiếng ồn bên tai, rốt cuộc đó là giọng của ai? Họ đang nói về nội dung gì? Khi cơn ác mộng kết thúc, mọi thứ đã trở nên mơ hồ và không còn nhớ rõ nữa."
  },
  AvgDialog_18850_Content_68 = {
    Text = "Ai Jī Sī phát hiện mình không biết từ khi nào đã ngồi trên một chiếc ghế, các nhà nghiên cứu áo trắng vây quanh cô, họ hào hứng nói gì đó, nhưng cô lại không nghe thấy gì cả."
  },
  AvgDialog_18850_Content_69 = {
    Text = "Đề……đề Yogg…?"
  },
  AvgDialog_18850_Content_7 = {
    Text = "Đây, lẽ nào là người mất tích kia…!"
  },
  AvgDialog_18850_Content_70 = {
    Text = "Khuôn mặt quen thuộc trước mắt như bị nước cuốn trôi đi sắc màu vốn có. Trước khi tròng mắt nâu bị đá trắng hoàn toàn thay thế, nó, hoặc anh ta, đã thở ra hơi thở cuối cùng."
  },
  AvgDialog_18850_Content_71 = {
    Text = "Ai……Ky-si……"
  },
  AvgDialog_18850_Content_72 = {
    Text = "<Shake:Tiêu Gác——!>"
  },
  AvgDialog_18850_Content_73 = {
    Text = "Khi tôi tỉnh lại, tôi đã ở trong phòng, và Tiyug cũng đã biến thành… trạng thái tồi tệ."
  },
  AvgDialog_18850_Content_74 = {
    Text = "Nếu lúc đó tôi không vào bừa bãi, nếu tôi, tôi nhận ra mình là người chẳng có ích gì… tôi sẽ không làm họ tức giận, và họ cũng sẽ không đối xử với Tiyug như vậy…"
  },
  AvgDialog_18850_Content_75 = {
    Text = "Không thể nào, điều này không phải là thật, không thể như vậy được……!"
  },
  AvgDialog_18850_Content_76 = {
    Text = "<Big:bạn còn giả ngu gì nữa!>"
  },
  AvgDialog_18850_Content_77 = {
    Text = "Jenkin dùng sức đẩy Sara một cái, gần như làm cô ấy ngã xuống đất. Con chuột trên vai chia sẻ sự tức giận của cô, nhe răng về phía Sara."
  },
  AvgDialog_18850_Content_78 = {
    Text = "Nói đi, tên tiến sĩ chó má kia đã đưa mọi người đi đâu, chị tôi bị chúng đưa đi đâu rồi! Nói!"
  },
  AvgDialog_18850_Content_79 = {
    Text = "Jenkin, đừng như vậy…! Cô Sara cô ấy, cô ấy cũng không phải cố ý, cũng không biết ——"
  },
  AvgDialog_18850_Content_8 = {
    Text = "Các bạn đã tìm thấy người rồi à? Tình hình của anh ấy thế nào? Có cần cứu trợ không?"
  },
  AvgDialog_18850_Content_80 = {
    Text = "Đừng tiếp tục bao che cho cô ta nữa! Bạn trở thành như vậy, những kẻ điên kia trở thành như thế, chị tôi mất tích, tất cả đều vì cô ta! Cô ta phải trả giá đắt!"
  },
  AvgDialog_18850_Content_81 = {
    Text = "Xin lỗi, xin lỗi……"
  },
  AvgDialog_18850_Content_82 = {
    Text = "……Erika, giúp chúng tôi liên hệ với đội điều tra.Có nhu cầu vận chuyển."
  },
  AvgDialog_18850_Content_83 = {
    Text = "Đang gửi đơn đề nghị hỗ trợ điều tra. \n Đã gửi và xác nhận, đội điều tra số 3 sẽ đến địa điểm mục tiêu trong vòng 3 giờ."
  },
  AvgDialog_18850_Content_84 = {
    Text = "Xin hãy, cô Sara. \nTrước khi những người có liên quan đến, mong bạn thông cảm ngồi ở văn phòng một lát."
  },
  AvgDialog_18850_Content_85 = {
    Text = "Xin lỗi... Tôi thực sự... xin lỗi.."
  },
  AvgDialog_18850_Content_86 = {
    Text = "Bạn đã đi vài bước,để ý thấy bên cạnh thiếu một hình dáng nhỏ bé màu trắng."
  },
  AvgDialog_18850_Content_87 = {
    Text = "Cô ấy có thể cần thời gian để yên lặng một chút."
  },
  AvgDialog_18850_Content_88 = {Text = "?"},
  AvgDialog_18850_Content_89 = {
    Text = "Chẳng có gì đâu, đi thôi."
  },
  AvgDialog_18850_Content_9 = {
    Text = "Cái dị thể trước mắt đang đau đớn bò lết, gương mặt vừa giống người vừa biến dạng lúc thì kéo dài vặn vẹo, lúc thì tụ lại với nhau, dù sao đi nữa, cũng đã là bộ dạng không còn khả năng cứu vãn."
  },
  AvgDialog_18850_Content_90 = {
    Text = "Ai Jī Sī?"
  },
  AvgDialog_18850_Content_91 = {
    Text = "Bạn quay đầu lại, thấy cô gái đứng bất động."
  },
  AvgDialog_18850_Content_92 = {
    Text = "Sao vậy, Ai Jī Sī? Tôi có nên đưa cô về nghỉ ngơi không?"
  },
  AvgDialog_18850_Content_93 = {
    Text = "……Cô Sara, cô có sao không?"
  },
  AvgDialog_18850_Content_94 = {
    Text = "Chúng tôi chỉ muốn hỏi cô ấy một số câu hỏi, không cần lo lắng."
  },
  AvgDialog_18850_Content_95 = {
    Text = "Còn cô ấy, liệu có quay lại không?"
  },
  AvgDialog_18850_Content_96 = {
    Text = "Cô ấy... chắc là sẽ quay lại."
  },
  AvgDialog_18850_Content_98 = {
    Text = "Ai Jī Sī?"
  },
  AvgDialog_18850_Content_99 = {
    Text = "Không sao…… chúng ta đi thôi, %player%{Male=ngài,Female=cô}.\nTôi, sẽ ổn thôi."
  },
  AvgDialog_18851_Content_1 = {
    Text = "13:37, Lentiennam Đông\nPhường của Lily"
  },
  AvgDialog_18851_Content_10 = {
    Text = "Cô lấy ra một miếng sắt và một cây đinh sắt dài từ túi, cắm vào lỗ khóa, con chuột trên vai cô đứng thẳng lên, ôm chặt hai chân trước và cảnh giác nhìn xung quanh."
  },
  AvgDialog_18851_Content_11 = {
    Text = "Cánh cửa khóa kêu lên một tiếng lách cách nhẹ, cô nắm lấy tay cầm và vặn, đẩy cửa vào trong."
  },
  AvgDialog_18851_Content_12 = {
    Text = "He he, nhẹ nhàng dễ dàng!"
  },
  AvgDialog_18851_Content_13 = {
    Text = "13:37, Lentiennam Đông\nPhường của Lily"
  },
  AvgDialog_18851_Content_14 = {
    Text = "Tôi nói cô Sara, tại sao cô không để Ai Jī Sī mặc đẹp một chút? Hôm nay không phải có khách quý đến sao."
  },
  AvgDialog_18851_Content_15 = {
    Text = "Bạn hiểu gì? Mặc quá đẹp sẽ khiến người ta nghĩ chúng ta không thiếu tiền. Mặc quá tệ thì lại làm người ta thấy chúng ta như cái hố không đáy, chỉ biết nhận, điều này sẽ khiến các nhà tài trợ sợ hãi."
  },
  AvgDialog_18851_Content_16 = {
    Text = "Cô ấy nói rồi kéo mạnh váy của Ai Jī Sī, sau đó dùng tay dính chút nước bọt và lau mạnh má của Ai Jī Sī."
  },
  AvgDialog_18851_Content_17 = {
    Text = "Ai Jī Sī, người bạn thân yêu của tôi, sau khi gặp nhà tài trợ, cô còn nhớ phải nói gì không?"
  },
  AvgDialog_18851_Content_18 = {
    Text = "Nhớ rồi, cô Sara ạ. Em có nghe lời, tối qua trước khi đi ngủ vẫn còn cố gắng học thuộc lòng mà."
  },
  AvgDialog_18851_Content_19 = {
    Text = "Sara gật đầu hài lòng, sau đó nhìn về phía người đàn ông trung niên đang để tay thoải mái trong túi."
  },
  AvgDialog_18851_Content_2 = {
    Text = "Ai Jī Sī bạn đang làm gì thế? Người tài trợ sắp đến!"
  },
  AvgDialog_18851_Content_20 = {
    Text = "Bạn cũng chú ý một chút, đừng nói những lời thừa thãi, nhé?"
  },
  AvgDialog_18851_Content_21 = {
    Text = "Rõ ràng rõ ràng!"
  },
  AvgDialog_18851_Content_22 = {
    Text = "Hãy đứng sẵn, {Male=anh ấy,Female=cô ấy} đã đến."
  },
  AvgDialog_18851_Content_23 = {
    Text = "Kết quả là không tìm thấy ví, lại còn gặp phải dị thể bị rỗngsuy yếu. Thế này mà gọi là không nguy hiểm sao…"
  },
  AvgDialog_18851_Content_24 = {
    Text = "Bạn chưa kịp nói hết, một giọng nói quen thuộc đã vang lên trong đầu bạn."
  },
  AvgDialog_18851_Content_25 = {
    Text = "Sự kiện không thể luôn giữ nguyên, nhiệm vụ cũng vậy. \nHay là bạn có ý kiến về phán đoán của William?"
  },
  AvgDialog_18851_Content_26 = {
    Text = "Tôi hoàn toàn tin tưởng vào phán đoán của ông Draper, chắc chắn là hiện tượng rỗng rỗng đã xấu đi!"
  },
  AvgDialog_18851_Content_27 = {
    Text = "Phản ứng khá nhanh. \nĐược rồi, tập trung tinh thần, gặp phải dị biến thể, có nghĩa là các người đã gần đến mục tiêu."
  },
  AvgDialog_18851_Content_28 = {
    Text = "Thật vậy. Nhìn này."
  },
  AvgDialog_18851_Content_29 = {
    Text = "Bạn nhìn theo hướng cô ấy chỉ. Không xa là một cánh cửa sắt có khắc chữ \"Xưởng làm việc Lily phường\", trước cửa có ba người."
  },
  AvgDialog_18851_Content_3 = {
    Text = "Đến rồi, xin lỗi cô Sara, tôi, tôi không cố ý để cô phải chờ."
  },
  AvgDialog_18851_Content_30 = {
    Text = "Báo cáo, đã tới nơi nhận nhiệm vụ."
  },
  AvgDialog_18851_Content_31 = {
    Text = "Xác nhận đã đến địa điểm nhiệm vụ. Đối chiếu mục tiêu nhiệm vụ: thâm nhập phường lao động, tìm lại học sinh mất tích, xác định danh tính của thực thể sống chưa xác định và kiềm chế hoạt động của nó."
  },
  AvgDialog_18851_Content_32 = {
    Text = "Mục tiêu nhiệm vụ đã được đối chiếu. Sắp vào phường, giữ liên lạc thông suốt."
  },
  AvgDialog_18851_Content_33 = {
    Text = "Ramona nhìn bạn."
  },
  AvgDialog_18851_Content_34 = {
    Text = "Thế nào, sẵn sàng chưa?"
  },
  AvgDialog_18851_Content_35 = {
    Text = "Tôi có thể đối phó được, chỉ cần người bên trong không giống đám trẻ vừa rồi!"
  },
  AvgDialog_18851_Content_36 = {
    Text = "<Small:… cũng không giống như đóa.>"
  },
  AvgDialog_18851_Content_37 = {
    Text = "Bạn biết rằng bộ thông tin bạc tâm rất nhạy bén."
  },
  AvgDialog_18851_Content_38 = {
    Text = "<Shake:khụ khụ!>"
  },
  AvgDialog_18851_Content_39 = {
    Text = "Hãy yên tâm. Tôi sẽ bảo vệ huy hiệu và cúc tay áo của ngài đến cùng, Ashe{Male=ngài,Female=cô}."
  },
  AvgDialog_18851_Content_4 = {
    Text = "Được rồi, đều là những đứa lớn cả rồi mà còn không hiểu chuyện. Nhanh lên, nếu muộn thì không tốt đâu…"
  },
  AvgDialog_18851_Content_40 = {
    Text = "Vậy thì tôi đành nhờ vào cô Mary quản gia thân yêu rồi."
  },
  AvgDialog_18851_Content_41 = {
    Text = "Nếu các người còn dám đùa giỡn với danh tính giả mạo, thì cứ đợi mà xem, sẽ có thêm huấn luyện chờ các người đấy."
  },
  AvgDialog_18851_Content_5 = {
    Text = "Cô bé ngoan ngoãn theo sau, len lén ngoảnh lại, vẫy tay chào chậu cây ở góc tường. \nTiếng bước chân dần dần xa đi. Cô bé ôm chuột, len lén thò đầu ra khỏi những tán lá xanh."
  },
  AvgDialog_18851_Content_6 = {
    Text = "Cuối cùng! Cô ả đáng ghét suốt ngày ở trong văn phòng, thậm chí tối cũng không về, hôm nay cuối cùng cũng để tôi có cơ hội rồi!"
  },
  AvgDialog_18851_Content_7 = {
    Text = "Chít! Chít chít!"
  },
  AvgDialog_18851_Content_8 = {
    Text = "Hãy yên tâm, Ai Jī Sī nói rằng hôm nay họ sẽ đưa người tự phục vụ kia đi tham quan, trưa không về. Tôi phải kiểm tra thật kỹ, không bỏ sót một chi tiết nào."
  },
  AvgDialog_18851_Content_9 = {
    Text = "Thời gian làm việc, hành lang khu sinh hoạt không có một bóng người. Cô gái đến trước cửa phòng có bảng hiệu \"Văn phòng quản lý\"."
  },
  AvgDialog_18852_Content_1 = {
    Text = "Ash{Male=ngài,Female=cô}, cô Mary!"
  },
  AvgDialog_18852_Content_2 = {
    Text = "Chúng tôi ổn, mau đưa mọi người lùi lại, chúng tôi sẽ xử lý."
  },
  AvgDialog_18852_Content_3 = {
    Text = "Được, được. Trời ạ, điều này thật sự… Các con, các con nhanh lên, đến đây với mẹ."
  },
  AvgDialog_18852_Content_4 = {
    Text = "Hành động nhanh, có một tên khó đối phó xuất hiện này."
  },
  AvgDialog_18853_Content_1 = {
    Text = "Bạo động kết thúc, mọi người lại xếp thành hàng. \nÁi Kế Tư đứng giữa những đứa trẻ, mặt tái nhợt, run rẩy nhẹ."
