  AvgDialog_18854_Content_3 = {Text = "!"},
  AvgDialog_18855_Content_1 = {
    Text = "Những giai điệu không thể nghe thấy dẫn lối phía trước mờ ảo. Bạn vén lớp sương mù, lao về phía trước, nhưng vẫn không thể nhìn thấy đích đến."
