  },
  AvgDialog_18855_Content_13 = {
    Text = "Khu vực này ngoài phường lao động, chỉ có nơi đây xuất hiện dấu rỗng rỗng. \nTôi không tin rằng đây là sự trùng hợp."
  },
  AvgDialog_18855_Content_14 = {
    Text = "Điều này hầu như chứng minh hung thủ đến từ xưởng, điều còn lại cần giải quyết là: nó là ai và đang ẩn náu ở đâu trong xưởng? Nó có phải là sức sống chưa biết mà các người đang tìm kiếm không?"
  },
  AvgDialog_18855_Content_15 = {
    Text = "Chờ đã, kích thước này… Đây là dấu chân của đứa trẻ sao!?"
