  AvgDialog_18855_Content_16 = {Text = "?！"},
  AvgDialog_18855_Content_17 = {
    Text = "……thật vậy, nhìn hướng là đi về phía xưởng."
  },
  AvgDialog_18855_Content_18 = {
    Text = "Nhanh lên, cố gắng tìm thấy cậu bé trước khi cậu ấy trốn đi."
  },
  AvgDialog_18855_Content_19 = {
    Text = "20:47,xưởng làm việc của Lily\nhành lang"
  },
  AvgDialog_18855_Content_2 = {
    Text = "Những tòa nhà hai bên đường nhìn bạn bằng những ô cửa sổ đen như mực, tiếng bước chân vang vọng trong sương mù. Một lúc sau, bạn có cảm giác rằng mình đã chạy một mình rất lâu trên con phố này."
  },
  AvgDialog_18855_Content_20 = {
    Text = "Trong làn sương mù bao trùm mọi nơi, phường làm việc trở nên lạnh lẽo hơn bao giờ hết. \nNgười đàn ông đeo cây gậy gỗ bên hông cầm đèn lồng đi tuần tra trong hành lang không người và không có đèn."
  },
  AvgDialog_18855_Content_21 = {
    Text = "Không được bật đèn, tiết kiệm điện —— **, cô Sara thật là keo kiệt. Còn lắm chuyện nữa! Chỉ ở cái nơi nghèo nàn này, có tên trộm nào muốn đến… Ừ?"
