  AvgDialog_18855_Content_22 = {
    Text = "Dưới ánh sáng vàng nhạt, một cánh cửa mở ra trong im lặng."
  },
  AvgDialog_18855_Content_23 = {
    Text = "Ai, ai ở đó?"
  },
  AvgDialog_18855_Content_24 = {
    Text = "Anh ta nắm chặt cây gậy, mạnh dạn bước lên phía trước."
