  AvgDialog_18855_Content_25 = {
    Text = "Đèn treo cổ điển bỗng nhiên tắt hẳn."
  },
  AvgDialog_18855_Content_26 = {Text = "!!!"},
  AvgDialog_18855_Content_27 = {
    Text = "Lực lượng vô hình đã kéo anh ta vào một cách mạnh mẽ. Cánh cửa gỗ đóng lại với một tiếng ‘rầm’, hành lang trở lại sự tĩnh lặng."
  },
  AvgDialog_18855_Content_28 = {
    Text = "20:43, xưởng lao động của Lily\nhành lang"
  },
  AvgDialog_18855_Content_29 = {
    Text = "Hai cô gái cuộn tròn trong ánh sáng mờ nhạt của chiếc đèn lồng, liên tục đưa mắt nhìn quanh."
  },
  AvgDialog_18855_Content_3 = {
    Text = "Mọi thứ không có điểm bắt đầu, không có điểm kết thúc, bạn sẽ tiếp tục tiến lên, cho đến khi sức sống kết thúc, cho đến khi thời gian——"
  },
  AvgDialog_18855_Content_30 = {
    Text = "Bước chân nhẹ nhàng vọng lại từ xa, trong hành lang yên tĩnh đến mức chói tai."
  },
  AvgDialog_18855_Content_31 = {
    Text = "Ai, ai ở đó? \n Bước ra! Tôi, tôi cảnh cáo bạn, tôi có vũ khí đấy!"
  },
  AvgDialog_18855_Content_32 = {
    Text = "Đường corridor không có chút gió nào, nhưng ngọn lửa trên cây nến lại lay động như bị gió thổi."
  },
  AvgDialog_18855_Content_33 = {
    Text = "Dĩa trong tay Ai Jī Sī run rẩy, cốc trà trắng và đĩa đỡ va vào nhau, tạo ra tiếng động như tiếng kêu thảm thiết của chú chim non."
  },
  AvgDialog_18855_Content_34 = {
    Text = "Tiếng chân ngày càng gần, ngày càng gần. Móng vuốt của brun cắm sâu vào vai áo của Jenkin, nó hở răng, phát ra âm thanh đe dọa sắc bén đặc trưng của loài gặm nhấm."
  },
  AvgDialog_18855_Content_35 = {
    Text = "Giống như bị giọng của Brun kích thích, tiếng bước chân bỗng nhiên nhanh hơn, thẳng tiến về phía hai người."
  },
  AvgDialog_18855_Content_36 = {
    Text = "Bóng tối dày đặc nuốt chửng ngọn nến yếu ớt, các cô gái nhắm mắt lại nhưng chỉ cảm thấy một làn hơi nước nhẹ nhàng lướt qua mặt."
  },
  AvgDialog_18855_Content_37 = {
    Text = "Một bàn tay từ trong bóng tối duỗi ra, đặt chính xác lên chiếc cốc trà đang run rẩy, làm nó im lặng hẳn."
  },
  AvgDialog_18855_Content_38 = {
    Text = "Các cậu sao vậy? Mặt các cậu nhạt thế này?"
  },
  AvgDialog_18855_Content_39 = {
    Text = "Ông Rogers!\n Ở đây quá tối. Chúng tôi……"
  },
  AvgDialog_18855_Content_4 = {Text = "Vị máu."},
  AvgDialog_18855_Content_40 = {
    Text = "Đêm sương mù thực sự dễ khiến người ta rất sợ hãi và lo lắng, phải không?"
  },
  AvgDialog_18855_Content_41 = {
    Text = "Rogers đẩy cửa ra, ánh sáng dịu nhẹ tuôn trào ra, xua tan bóng tối dày đặc trong hành lang."
  },
  AvgDialog_18855_Content_42 = {
    Text = "Cảm ơn các bạn đã đặc biệt mang cơm cho tôi, Ai Jī Sī, Jenkin."
  },
  AvgDialog_18855_Content_43 = {
    Text = "Đặt khay lên bàn nhỏ, Rogers ôm lấy con búp bê tinh xảo từ trên giường và mỉm cười với hai cô gái."
  },
  AvgDialog_18855_Content_44 = {
    Text = "Làm phần thưởng, có muốn sờ thử không? \nGióoc-giơ sẽ rất vui."
  },
  AvgDialog_18855_Content_45 = {
    Text = "Đôi mắt vô cơ của con búp bê phản chiếu ánh sáng vàng của ngọn đèn, như thể đang thầm lặng mong muốn cô bé: Hãy chạm vào tôi đi, chỉ một lần thôi."
  },
  AvgDialog_18855_Content_46 = {
    Text = "Vuốt ve tôi, sau đó——"
  },
  AvgDialog_18855_Content_47 = {
    Text = "Trở thành người bạn trung thành của tôi."
  },
  AvgDialog_18855_Content_5 = {
    Text = "Bạn bỗng nhiên tỉnh táo, sau đó mới nhận ra mùi hôi tanh ngọt. \n Bạn chậm bước, tiến gần đến bóng tối nằm sụp trên mặt đất phía trước."
  },
  AvgDialog_18855_Content_6 = {
    Text = "Đó là một xác chết nữ bị tan nát, ổ bụng mở ra vẫn còn bốc hơi nóng, khuôn mặt bị thịt máu nát bét, hai cánh tay bị mất, mặt cắt gọn gàng, như thể bị ai đó chặt đứt một cách nhẹ nhàng nhưng quyết đoán."
  },
  AvgDialog_18855_Content_7 = {
    Text = "Chiêu thức này, đúng là kẻ phân thây."
  },
  AvgDialog_18855_Content_8 = {
    Text = "Mở bụng, cắt lấy các bộ phận làm chiến lợi phẩm, đúng như đặc điểm tội phạm của kẻ xé xác trong báo cáo cảnh sát. \nBạn nhất thời không thể phân biệt được điều nào tàn nhẫn hơn: sự rỗng rỗng, hay kẻ giết người."
  },
  AvgDialog_18855_Content_9 = {
    Text = "Vậy tại sao tiếng hát truy tìm tinh thần lại dẫn bạn đến đây? Khả năng của sức sống chưa biết rõ ràng là đá hóa, hay là, ở đây không chỉ có một cá thể đặc biệt?"
  },
  AvgDialog_18856_Content_1 = {
    Text = "Gánh nặng của lương tâm"
  },
  AvgDialog_18856_Content_10 = {
    Text = "Bạn đi theo sau SARA đến bên cửa kim loại của phường, vừa thấy mấy người mặc đồng phục đang giữ một cô bé khóc lóc và giãy dụa, bước ra ngoài."
  },
  AvgDialog_18856_Content_11 = {
    Text = "Là hội nghị thẩm tra."
  },
  AvgDialog_18856_Content_12 = {
    Text = "Có phải đây là việc rút lui mà đóa đã nói không! Sao lại đến nhanh vậy!"
  },
  AvgDialog_18856_Content_13 = {
    Text = "Buông tay! Các người định đưa cô ấy đi đâu, các người định đưa Lucy đi đâu!"
  },
  AvgDialog_18856_Content_14 = {
    Text = "Dợi một chút!"
  },
  AvgDialog_18856_Content_15 = {
    Text = "Bạn lấy ra sợi dây chuyền giấu dưới áo, chìa khóa bạc treo trên đó dưới sự điều khiển của bạn đứng thẳng và lơ lửng trong lòng bàn tay, đồng thời phát ra ánh sáng dịu nhẹ."
  },
  AvgDialog_18856_Content_16 = {
    Text = "Đại học Misaque, Người Giữ Gìn %player%, số hiệu chìa khóa K-0617, muốn đối thoại với người phụ trách hành động lần này."
  },
  AvgDialog_18856_Content_17 = {
    Text = "Người đứng trước mặt bạn thu hồi ánh mắt từ chìa khóa bạc và chào bạn."
  },
  AvgDialog_18856_Content_18 = {
    Text = "<Blue:Hội nghị thẩm tra Hiệp định Misidia> Đội trưởng Đội Phản ứng Thứ ba, phụ trách công tác giao nhận điều tra về tổ chức đặc biệt S."
  },
  AvgDialog_18856_Content_19 = {
    Text = "Không ngờ lại gặp được Người Giữ Gìn mới tại đây, thật là vinh dự của tôi, %player%{Male=ngài,Female=cô}."
  },
  AvgDialog_18856_Content_2 = {
    Text = "10:20, phường Lily \n trước cửa văn phòng quản lý"
  },
  AvgDialog_18856_Content_20 = {
    Text = "Xin hỏi đây là chuyện gì xảy ra? Tại sao các người lại đột nhiên bắt giữ thành viên của xưởng?"
  },
  AvgDialog_18856_Content_21 = {
    Text = "Xin hãy để tôi giải thích."
  },
  AvgDialog_18856_Content_22 = {
    Text = "Đội trưởng vẫy vẫy tay, một nhân viên điều tra bên cạnh liền đưa lên một túi giấy."
  },
  AvgDialog_18856_Content_23 = {
    Text = "Bạn mở túi ra và phát hiện bên trong có một bộ pyjama trẻ em cũ kỹ. Viền áo pyjama bị bẩn bởi những vết bẩn nâu, chất lỏng khô làm nó cứng lại."
  },
  AvgDialog_18856_Content_24 = {
    Text = "Sau khi nhận được thông báo điều tra chung từ Đại học Misag, chúng tôi đã đến đây vào lúc 10 giờ 23 phút và tiến hành khám xét sơ bộ phường lao động, xác nhận tình trạng của phường."
  },
  AvgDialog_18856_Content_25 = {
    Text = "Trong quá trình khám xét, chúng tôi phát hiện vết máu trong căn phòng cũ phía đông nam tầng một của phường, và tìm thấy vật này cùng một con dao chặt thịt dính máu dưới cầu thang trong phòng chứa đồ."
  },
  AvgDialog_18856_Content_26 = {
    Text = "Theo chỉ nhận của thành viên phường, bộ pyjama này thuộc sở hữu của cô bé tên là Lucy. Kết hợp vết máu trong phòng cũ và tiếng la hét đêm qua, chúng tôi quyết định đưa cô bé về để điều tra."
  },
  AvgDialog_18856_Content_27 = {
    Text = "Là tôi, tôi đã hét lên! Tôi bị bóng tối dọa vào tối qua, nhưng không có chuyện gì xảy ra! Người giữ bí mật này cũng thấy rồi, không có gì xảy ra, phải không?"
  },
  AvgDialog_18856_Content_28 = {
    Text = "Thưa ông, chuyện này thực sự không đơn giản như vậy. Chúng tôi nghi ngờ có một thế lực thứ ba can thiệp, đứa trẻ này rất có thể bị người khác kiểm soát. Ông có thể để cô ấy lại đây không?"
  },
  AvgDialog_18856_Content_29 = {
    Text = "Chúng tôi đã biết về sự kiện của tổ chức bất hợp pháp. Nhưng dù có bị người khác chỉ thị hay không, kẻ gây án vẫn là kẻ gây án. Về phương diện quy trình, tôi không thể để cô ấy hoạt động bên ngoài."
  },
  AvgDialog_18856_Content_3 = {
    Text = "Các người còn chưa kịp đến cửa văn phòng thì đã thấy một cô gái trẻ vội vàng chạy tới."
  },
  AvgDialog_18856_Content_30 = {
    Text = "Hội nghị thẩm tra sẽ tuân thủ các quy định liên quan của \"Hiệp định\" trong quá trình điều tra, không để cô ấy phải chịu sự đối xử bất công. Điều này tôi có thể đảm bảo với bạn."
  },
  AvgDialog_18856_Content_31 = {
    Text = "Thêm vào đó, xe đưa hai người trở lại trường đã sẵn sàng. Tình huống đặc biệt, tôi sẽ chỉ định thêm hai điệp viên đi cùng để đảm bảo an toàn cho các bạn. Xin vui lòng đi theo tôi."
  },
  AvgDialog_18856_Content_32 = {
    Text = "Không được."
  },
  AvgDialog_18856_Content_33 = {
    Text = "Hiệp hội Điêu khắc gia dùng viện nghiên cứu làm bình phông, thông qua nhà tài trợ Rogers liên hệ với phường, bí mật tiến hành thí nghiệm trên cơ thể người. Thí nghiệm này cũng dẫn đến sự xuất hiện của hiện tượng rỗng rỗng."
  },
  AvgDialog_18856_Content_34 = {
    Text = "Dựa trên những manh mối hiện có, ngoài \"bệnh điên\" ở phường, \"kẻ xé xác\" đang hoạt động tích cực ở khu Đông gần đây rất có thể cũng là một trong những biểu hiện bất thường của sự rỗng rỗng."
  },
  AvgDialog_18856_Content_35 = {
    Text = "Chúng ta đã tìm ra rất nhiều thông tin, chỉ còn thiếu danh tính của kẻ tháo gỡ, là có thể làm sáng tỏ hoàn toàn sự thật của sự kiện, cũng như phá hủy kế hoạch của nhà điêu khắc. Bây giờ, chúng ta tuyệt đối không thể rời đi."
  },
  AvgDialog_18856_Content_36 = {
    Text = "Tôi hiểu mong muốn của bạn để tiếp tục điều tra, nhưng lệnh của tôi —"
  },
  AvgDialog_18856_Content_37 = {
    Text = "Anh ta đột nhiên nhấn vào huy hiệu trên cánh tay của hội nghị thẩm tra, dường như đang lắng nghe điều gì đó. \n Thiết bị này hẳn là máy truyền tin bạc tâm mà Đại học Misaque cung cấp cho hội nghị thẩm tra, có phải là có lệnh mới không?"
  },
  AvgDialog_18856_Content_38 = {
    Text = "<Blue:Trung tá Lydia>. Vâng, Người Giữ Gìn không muốn từ bỏ cuộc điều tra. \nBa ngày? Không, tôi không đang nghi ngờ bạn… Vâng, tôi hiểu. Tốt, xác nhận thông tin."
  },
  AvgDialog_18856_Content_39 = {
    Text = "Xin chào, rất vinh dự được liên lạc với <Blue:Người Giữ Gìn>."
  },
  AvgDialog_18856_Content_4 = {
    Text = "Cô Sara, không tốt rồi! Có mấy người đang muốn đưa Lucy đi!"
  },
  AvgDialog_18856_Content_40 = {
    Text = "Bạn chỉ biết một người duy nhất xứng đáng với danh hiệu đó — vị thầy của bạn, người luôn sống dưới lòng đất của Misaque. Trong suốt năm qua, bạn chưa bao giờ thấy ông chủ động liên lạc với ai khác ngoài bạn và đóa, hay là……"
  },
  AvgDialog_18856_Content_41 = {
    Text = "Vâng, tôi đã hiểu. Tạm biệt thưa ông!"
  },
  AvgDialog_18856_Content_42 = {
    Text = "Đội trưởng ngừng nói chuyện và quay sang bạn, trong lúc đó, giọng nói ôn hòa của giáo viên vang lên trong đầu bạn."
  },
  AvgDialog_18856_Content_43 = {
    Text = "Hãy làm những gì bạn muốn, %player%, còn những việc khác cứ để tôi lo. \nTôi tin tưởng bạn."
  },
  AvgDialog_18856_Content_44 = {
    Text = "Câu nói tương tự anh ấy cũng đã nói với bạn trước khi đi. \nCó vẻ như bạn không cần phải vội trở về."
  },
  AvgDialog_18856_Content_45 = {
    Text = "Sau khi thương lượng với Người Giữ Gìn thế hệ đầu, hội nghị thẩm tra quyết định cho phép Người Giữ Gìn tiếp tục điều tra sự kiện tại xưởng lao động Lily phường. Nhưng bạn chỉ có ba ngày. Sau ba ngày nữa, sự kiện sẽ được chuyển giao cho điều tra viên cao cấp hơn."
  },
  AvgDialog_18856_Content_46 = {
    Text = "Nói xong, anh ta quay người và ra lệnh cho các điệp viên xung quanh."
  },
  AvgDialog_18856_Content_47 = {
    Text = "Việc bàn giao tạm ngừng, ngay lập tức thực hiện phong tỏa khu vực cấp 5. Nghi phạm tạm thời bị giam giữ, chờ sau khi hoàn thành việc bàn giao sẽ tiến hành thẩm vấn."
  },
  AvgDialog_18856_Content_48 = {
    Text = "Không được, không được! Làm ơn, tôi sẵn sàng làm bất cứ điều gì, xin hãy đừng mang cô ấy đi! Lucy, <Big:Lucy——>"
  },
  AvgDialog_18856_Content_49 = {
    Text = "Không phải do cô ấy làm, không phải cô ấy! %player%! Xin hãy giúp Lucy!"
  },
  AvgDialog_18856_Content_5 = {
    Text = "Gì, gì vậy?!"
  },
  AvgDialog_18856_Content_50 = {
    Text = "Xin lỗi, đây là một mệnh lệnh bắt buộc, tôi không thể không thực hiện. \n Vậy, tôi xin phép đi trước."
  },
  AvgDialog_18856_Content_51 = {
    Text = "Thề sẽ dùng lưỡi kiếm xuyên thủng bóng tối."
  },
  AvgDialog_18856_Content_52 = {
    Text = "Ông ta một lần nữa chào bạn, sau đó bất chấp tiếng khóc thảm thiết của Lucy và sự van nài đầy tuyệt vọng của Sara và Ái Kế Tư, ra lệnh cho thuộc hạ áp giải các cô gái đi, rồi quay người bước vào chiếc xe đang chờ sẵn bên cạnh."
  },
  AvgDialog_18856_Content_53 = {
    Text = "Cánh cửa xe đóng lại, cách ly mọi tầm nhìn. Xe hơi nối đuôi nhau rời đi, Sara hoàn toàn kiệt sức, gục xuống đất."
  },
  AvgDialog_18856_Content_54 = {
    Text = "<Small:Tôi vô năng, tôi không có tác dụng, tôi không phải là một hiệu trưởng tốt, tôi không thể bảo vệ mọi người, bảo vệ trẻ em…>"
  },
  AvgDialog_18856_Content_55 = {
    Text = "Cô Sara, đừng như vậy… Chúng tôi, mọi người đều hiểu, cô đã cố gắng hết sức rồi."
  },
  AvgDialog_18856_Content_56 = {
    Text = "<Small:xin lỗi, Tiểu Mạch, xin lỗi, Ai Jī Sī, xin lỗi… Jenkin…\nxin lỗi, Diana, Henry, bé Lucy…>"
  },
  AvgDialog_18856_Content_57 = {
    Text = "Cô ấy co thân thể lại, hai tay ôm lấy đầu mình, những lời thì thầm đau đớn dần trở nên khàn đặc và hỗn loạn, khó có thể phân biệt."
  },
  AvgDialog_18856_Content_58 = {
    Text = "Cô Sara…?"
  },
  AvgDialog_18856_Content_59 = {
    Text = "Phường sáng sủa và ồn ào bỗng chìm vào im lặng lạnh lẽo như đang ở dưới đáy nước. \nÁp lực vô hình xuất hiện đột ngột, bạn hít một hơi sâu, nhận ra có điều gì đó không ổn."
  },
  AvgDialog_18856_Content_6 = {
    Text = "Họ mặc đồng phục lạ, trông rất đáng sợ. Sau khi đi một vòng, họ lập tức nói Lucy là kẻ tình nghi, không ai có thể ngăn cản."
  },
  AvgDialog_18856_Content_60 = {
    Text = "Chết rồi, Ramona, nhanh lên, hãy để mọi người rời đi!"
  },
  AvgDialog_18856_Content_61 = {
    Text = "Không kịp rồi. \n Đầu của quản lý trẻ tuổi nứt ra giống như một bông hoa, chất lỏng đen sẫm phun ra trên mặt đất."
  },
  AvgDialog_18856_Content_62 = {
    Text = "Sara, cô Sara! !"
  },
  AvgDialog_18856_Content_63 = {
    Text = "Cô ấy phát ra tiếng rít cao và sắc nhọn, từ xa vọng lại vài tiếng kêu đáp lại. \n Cơ thể méo mó, dị thể bị rỗng rỗng xâm nhập lao ra từ tòa nhà."
  },
  AvgDialog_18856_Content_7 = {
    Text = "Sao có thể là Lucy?! Hiển nhiên là.."
  },
  AvgDialog_18856_Content_8 = {
