  AvgDialog_18857_Content_1 = {
    Text = "Đêm vắng bóng chim"
  },
  AvgDialog_18857_Content_10 = {
    Text = "Dường như không thấy người đó, cô gái vẫn tiếp tục bước đi, từng bước một."
  },
  AvgDialog_18857_Content_11 = {
    Text = "Khi cô ấy đi qua, Ai Jī Sī nghe thấy một bài hát vô cùng mỏng manh."
  },
  AvgDialog_18857_Content_12 = {
    Text = "Ông Charlie có một con mèo vằn mà ông yêu thương vô cùng…"
