  AvgDialog_18857_Content_19 = {
    Text = "Tôi, tôi không thể động đậy?! Tại sao, tại sao thân thể tôi không thể động đậy?"
  },
  AvgDialog_18857_Content_2 = {
    Text = "Hơi nước tụ lại thành lớp sương mù dày đặc, khiến hành lang vốn đã không rộng rãi trở nên sâu thẳm hơn, cho đến khi hoàn toàn bị bóng tối nuốt chửng."
  },
  AvgDialog_18857_Content_20 = {
