  AvgDialog_18857_Content_32 = {Text = "Bà!"},
  AvgDialog_18857_Content_33 = {
    Text = "Anh trai đừng qua, anh ơi!"
  },
  AvgDialog_18857_Content_34 = {
    Text = "Thưa ngài bí ẩn, xin ngài đừng như vậy."
