  AvgDialog_18857_Content_35 = {
    Text = "Một ngày cô ấy biến mất, anh ta tìm kiếm mọi nơi."
  },
  AvgDialog_18857_Content_36 = {
    Text = "Liên hệ trường học ngay lập tức!"
  },
  AvgDialog_18857_Content_37 = {
    Text = "Tôi không muốn gây thương họ, xin anh, tôi sẽ nghe theo mọi thứ anh nói, chỉ là——đừng gây thương họ."
  },
  AvgDialog_18857_Content_38 = {
    Text = "Anh lục tủ quần áo. Anh nhìn dưới giường."
  },
  AvgDialog_18857_Content_39 = {
    Text = "<Shake:anh, anh trai… đằng sau, đằng sau!>"
  },
  AvgDialog_18857_Content_4 = {
    Text = "Tiếng xào xạc biến thành những bước chân nhẹ nhàng, một hình bóng mờ mờ từ từ tiến gần hòn đảo vàng mờ."
  },
  AvgDialog_18857_Content_40 = {
    Text = "Anh ta đã đi vòng quanh tầng hầm nơi có lò hơi đang cháy."
