  AvgDialog_18857_Content_49 = {Text = "Đừng…"},
  AvgDialog_18857_Content_5 = {
    Text = "Bé Lucy, bạn đi đâu vậy? Bạn đi vệ sinh đêm đã lâu, tôi hơi lo lắng ——"
  },
  AvgDialog_18857_Content_50 = {
    Text = "Tại sao... chúng ta đã làm sai điều gì... tại sao chúng ta phải trải qua chuyện này.."
  },
  AvgDialog_18857_Content_51 = {
    Text = "Nhỏ Mc mặt không biểu cảm, nhìn thẳng về phía trước, tay cầm một con dao nhọn, bộ quần áo bị thấm đẫm máu đang không ngừng nhỏ xuống chất lỏng đặc quánh."
  },
  AvgDialog_18857_Content_52 = {
    Text = "Sau lưng anh là một cánh cửa mở, từ bên ngoài có thể nhìn thấy lờ mờ một thân thể bị hủy hoại nằm trong phòng."
  },
  AvgDialog_18857_Content_53 = {
    Text = "Mọi người đều nghe theo lời của giọng nói, nhưng lại không ai nhớ gì cả. Nếu, nếu giọng nói đi tìm Jenkin…"
  },
  AvgDialog_18857_Content_54 = {
    Text = "Bé tội nghiệp, bạn lại muốn làm việc vô ích rồi sao?"
  },
  AvgDialog_18857_Content_55 = {
    Text = "……!\nLà, là ngươi…! Kẻ xấu! Đừng kiểm soát Tiểu Mạch!"
  },
  AvgDialog_18857_Content_56 = {
    Text = "Đừng kiểm soát anh ta nữa! Nếu không, tôi sẽ nói... nói…"
  },
  AvgDialog_18857_Content_57 = {
    Text = "Bạn định nói với ai, cô Sara thân yêu của bạn sao? \nAi Jī Sī, bạn đã quên rồi sao, lần trước khi bạn nói chuyện với cô ấy, cô ấy đã đối xử với bạn như thế nào?"
  },
  AvgDialog_18857_Content_59 = {
    Text = "Cô ấy nghĩ rằng bạn đang gặp ác mộng hoặc lại thấy ảo giác, chuẩn bị đưa bạn đi 「kiểm tra」 nữa. \nBằng chứng bạn đưa ra cũng bị coi là rác mà tiến sĩ để lại khi điều trị bệnh nhân."
  },
  AvgDialog_18857_Content_6 = {Text = "!!"},
  AvgDialog_18857_Content_60 = {
    Text = "Nhìn bạn buồn như vậy, tôi cũng rất đau lòng, nhưng đây chính là hiện thực tàn nhẫn và xấu xí. \nNếu đôi mắt của bạn không còn hữu dụng, tôi sẽ giải thoát bạn và biến bạn thành một sáng tạo tuyệt đẹp."
  },
  AvgDialog_18857_Content_61 = {
    Text = "Bây giờ, tiếp tục làm những gì bạn đã làm trước đây: lau sạch dấu vết, đốt cháy bằng chứng. \nChắc đây là việc duy nhất mà bạn có thể làm rồi."
  },
  AvgDialog_18857_Content_62 = {
    Text = "Cậu bé đi xa với khuôn mặt không biểu cảm. \n Ai Jī Sī bước vào phòng, quỳ xuống bên cạnh xác bảo vệ vẫn còn ấm."
  },
  AvgDialog_18857_Content_63 = {
    Text = "Cô ấy tháo mắt bịt, đầu ngón tay của người đàn ông lập tức cứng lại và trắng bệch, giống như một bức tượng đá. Một vật kim loại hình tròn lăn ra từ bàn tay cứng đờ, khi Ai Jī Sī đang định nhặt lên thì nghe thấy một tiếng thét từ phía sau."
  },
  AvgDialog_18857_Content_64 = {
    Text = "Ai, Ai Jī Sī…?!"
  },
  AvgDialog_18857_Content_65 = {
    Text = "Tôi đã giết người đó, đang chuẩn bị xử lý thi thể thì bị cô Sara phát hiện."
  },
  AvgDialog_18857_Content_66 = {
    Text = "Cô ấy kéo tôi ra, lau sạch máu trên tay tôi và an ủi rằng mọi thứ rồi sẽ ổn thôi, cứ giao cho cô ấy là được."
  },
  AvgDialog_18857_Content_67 = {
    Text = "Tôi vừa đi xem, phòng rất sạch sẽ, chắc chắn là cô Sara đã giúp tôi dọn dẹp. \n Và ——"
  },
  AvgDialog_18857_Content_68 = {
    Text = "Cô ấy lấy ra một cúc tay lấp lánh từ con gấu bông và trưng bày trước mặt các bạn. \nDù là kiểu dáng hay chất liệu, đều hoàn toàn giống với cái mà các bạn đã tìm thấy hôm qua."
  },
  AvgDialog_18857_Content_69 = {
    Text = "Các cậu đã nhặt được rồi, cái cúc tay tôi làm rơi ở đó."
  },
  AvgDialog_18857_Content_7 = {
    Text = "Hình bóng dần dần được chiếu sáng. Đó là một đứa trẻ, cô bé mặt không biểu cảm, nhìn thẳng về phía trước, tay cầm một con dao nhọn, đầu dao vẫn đang nhỏ máu."
  },
  AvgDialog_18857_Content_70 = {
    Text = "Tôi không tin. Bất kể bạn có động cơ hay không, bạn không phải là người như vậy, Ai Jī Sī. \nBạn là một đứa trẻ ngoan, hãy nói cho chúng tôi biết sự thật, chúng ta cùng nghĩ cách giải quyết, được không?"
