  AvgDialog_18857_Content_72 = {
    Text = "Ai Jī Sī đã tháo miếng che mắt phải, lộ ra một con mắt nhợt nhạt như tượng đá."
  },
  AvgDialog_18857_Content_73 = {Text = "Là tôi."},
  AvgDialog_18857_Content_74 = {
    Text = "Tôi đã biến anh ta thành đá."
  },
  AvgDialog_18857_Content_75 = {
    Text = "Ai Jī Sī, chúng ta——"
  },
  AvgDialog_18857_Content_76 = {
    Text = "Đừng nói nữa! Tôi… chính là kẻ sát nhân."
  },
  AvgDialog_18857_Content_77 = {
    Text = "Cô ấy lùi lại một bước, xung quanh cô, chất lỏng màu đen không biết từ đâu xuất hiện đang chờ cơ hội hành động."
  },
  AvgDialog_18857_Content_8 = {
    Text = "<Shake:này, này, này… Lucy…? Cô có phải, có phải đã… giết…>"
  },
  AvgDialog_18857_Content_9 = {
    Text = "Cô không thể kiềm chế được, quay người lại và nôn hết bữa tối đạm bạc ra góc tường."
  },
  AvgDialog_18858_Content_1 = {
    Text = "Những người đó là… những bệnh nhân sao? Những người mà Ai Jī Sī nói có thứ gì đó màu đen trên người? Đây có phải là hình dạng họ sẽ biến thành không?"
  },
  AvgDialog_18858_Content_2 = {
    Text = "Đây là những người… mất tích phải không?"
  },
  AvgDialog_18859_Content_1 = {
    Text = "Trong không gian thuần đen, những điểm nhỏ tỏa ánh bạc yếu ớt liên tiếp nối thành một dải, trôi nổi lên xuống như sóng triều theo quy luật khó hiểu."
  },
  AvgDialog_18859_Content_10 = {
    Text = "Điểm sáng đột ngột xa rời, không gian tối nhanh chóng tan biến."
  },
  AvgDialog_18859_Content_11 = {
    Text = "Bạn mở mắt ra, vừa lúc đối diện với ánh mắt bối rối của Jenkin."
  },
  AvgDialog_18859_Content_12 = {
    Text = "01:14, phường Lily\nphòng khách"
  },
  AvgDialog_18859_Content_13 = {
    Text = "%player%……? Sao vậy, có chuyện gì sao?"
  },
  AvgDialog_18859_Content_14 = {
    Text = "Jenkin xoa xoa mắt, đang định ngồi dậy thì phát hiện hai tay bị trói ngược sau lưng."
  },
  AvgDialog_18859_Content_15 = {
    Text = "Đây là chuyện gì vậy?! Ai làm việc này, mau thả tôi ra!"
  },
  AvgDialog_18859_Content_16 = {
    Text = "Bạn gật đầu về phía Ramona, cô ấy rút ra thanh kiếm mảnh, cắt đứt dây trói trên cổ tay Jenkin một cách gọn gàng."
  },
  AvgDialog_18859_Content_17 = {
    Text = "Xin lỗi, tình hình khẩn cấp, chúng tôi buộc phải áp dụng một số biện pháp bảo vệ. \nBạn… còn nhớ những gì bạn vừa làm không?"
  },
  AvgDialog_18859_Content_18 = {
    Text = "Tôi vừa mới ngủ mà, cùng với Brun và Ai Jī Sī, còn mơ thấy một giấc mơ lộn xộn… Đợi chút, đây không phải là phòng của Ai Jī Sī, sao tôi lại ở đây?"
  },
  AvgDialog_18859_Content_19 = {
    Text = "Các người, các người đưa tôi đến đây là muốn làm gì? Không phải là muốn bắt cóc tôi để bịt miệng chứ?"
  },
  AvgDialog_18859_Content_2 = {
    Text = "Bạn đứng giữa họ, lại như lơ lửng phía trên. Bạn là một trong số đó, nhưng lại không thực sự thuộc về họ. \nBạn không rõ họ cụ thể là ai, chỉ biết rằng bạn đến đây để tìm kiếm ai đó."
  },
  AvgDialog_18859_Content_20 = {
    Text = "Điều đó không phù hợp với phong cách và quy tắc của điều tra viên Đại học Misaque."
  },
  AvgDialog_18859_Content_22 = {
    Text = "Kiếm của Ramona lập tức ra khỏi bao. Thân kiếm bạc trắng lơ lửng bên cổ Clementine, nhưng cô không hề tỏ ra sợ hãi, ngược lại còn thản nhiên dùng hai ngón tay đẩy nhẹ lưỡi kiếm sang một bên."
  },
  AvgDialog_18859_Content_23 = {
    Text = "Bạn cảnh giác nhìn chằm chằm vào người phụ nữ trước mặt — cửa sổ và cửa ra đều đóng kín, cô ta gần như đột nhiên xuất hiện. Không một tiếng động, giống như một bóng ma."
  },
  AvgDialog_18859_Content_24 = {
    Text = "Rốt cuộc bạn là ai? Làm sao bạn biết được thân phận của chúng tôi?"
  },
  AvgDialog_18859_Content_25 = {
    Text = "Bạn có phải là thành viên của Hiệp hội Điêu khắc gia không? Và vừa nãy trong sương mù, đôi cánh của bạn… \n Bạn — có phải là con người không?"
  },
  AvgDialog_18859_Content_26 = {
    Text = "Tôi chỉ là một bên thứ ba nhiệt tình mà thôi, mặc dù, tôi thực sự có một chút tư tâm. \n Bạn khiến tôi rất quan tâm, điều tra viên đặc biệt."
  },
  AvgDialog_18859_Content_27 = {
    Text = "Cô ấy mỉm cười nhìn bạn, ánh mắt rơi trên người bạn ẩn chứa vẻ cuồng nhiệt kỳ lạ."
  },
  AvgDialog_18859_Content_28 = {
    Text = "……tại sao?"
  },
  AvgDialog_18859_Content_29 = {
    Text = "Đây không phải là điều tôi có thể bàn luận. \nChỉ có vị tồn tại tối cao mới có thể cho bạn câu trả lời mà bạn mong muốn."
  },
  AvgDialog_18859_Content_3 = {
    Text = "\"chị...chị...\""
  },
  AvgDialog_18859_Content_30 = {
    Text = "Nhưng để tạ lỗi, tôi không ngại trả lời câu hỏi trước đó của bạn. \nĐúng như bạn nghĩ, trái tim con người được tạo nên từ thịt máu, còn tôi, tôi có một trái tim bạc."
  },
  AvgDialog_18859_Content_31 = {
    Text = "Vì vậy, chúng ta tuyệt đối không thể để bạn rời đi."
  },
  AvgDialog_18859_Content_32 = {
    Text = "Nếu chỉ có một mình tôi, tôi rất sẵn lòng đi cùng các bạn. \nTuy nhiên, tôi còn phải nghĩ đến bệnh nhân của mình, họ hiện tại không thể thiếu tôi được."
  },
  AvgDialog_18859_Content_33 = {
    Text = "Clementine không biết từ đâu lấy ra một mặt dây chuyền kỳ lạ và khẽ lắc nó, cảm giác mệt mỏi nặng nề ngay lập tức ập xuống người bạn. Bạn cố gắng đứng dựa vào cạnh bàn, nhưng không thể bước thêm bước nào."
  },
  AvgDialog_18859_Content_34 = {
    Text = "Lưỡi kiếm mảnh trong tay Ramona buông thõng xuống, đầu cô khẽ lắc, gần như không thể mở nổi mắt. \nJenkin thì nằm bất động trên mặt đất, dường như đã chìm vào giấc ngủ sâu."
  },
  AvgDialog_18859_Content_35 = {
    Text = "Bạn... đã làm gì.."
  },
  AvgDialog_18859_Content_36 = {
    Text = "Một chút thủ đoạn nhỏ, đủ để tôi rời khỏi đây thôi. \nVới khả năng của bạn, chắc hẳn có thể dễ dàng giải quyết được mà."
  },
  AvgDialog_18859_Content_37 = {
    Text = "Tạm biệt, <Blue:mắt không có tròng nhạt>, chúng ta sẽ gặp lại nhau ở đây…"
  },
  AvgDialog_18859_Content_38 = {
    Text = "Cô ấy cúi đầu với bạn, rồi bước ra khỏi phòng. Bạn không thể chịu đựng thêm nữa, ngã xuống ghế."
  },
  AvgDialog_18859_Content_39 = {
    Text = "Clementine đóng cửa phòng, khẽ ngân nga một bài hát vui tươi trong cổ họng, vui vẻ vẫy tay về phía cuối hành lang rồi quay người rời đi."
  },
  AvgDialog_18859_Content_4 = {
    Text = "Bạn nhìn về hướng có tiếng động, một điểm sáng đặc biệt mờ nhạt đang lấp lánh trong biển sao. Những sợi tơ đen ánh kim loại kỳ dị bị cuốn vào nó, kéo nó, khiến nó không thể cử động."
  },
  AvgDialog_18859_Content_40 = {
    Text = "Trong bóng tối, cô gái mặc váy im lặng như một pho tượng. \nCô cúi đầu và siết chặt chiếc mặt nạ che mắt trắng trong tay."
  },
  AvgDialog_18859_Content_5 = {
    Text = "Dòng đen mờ ảo truyền ra giai điệu vui tươi, như một bài đồng dao do trẻ em hát. \nÔng Charlie có một con mèo vằn mà ông rất yêu quý…"
  },
  AvgDialog_18859_Content_6 = {
    Text = "\"chị chị... đừng đi...\""
  },
  AvgDialog_18859_Content_7 = {
    Text = "Giọng của Jenkin vang lên từ bên trong quả cầu ánh sáng. Nó muốn tiến gần bạn hơn, nhưng ngay khi di chuyển, nó đã bị những sợi dây đen nhỏ siết chặt, buộc phải lùi lại, giống như một con rối bị điều khiển."
  },
  AvgDialog_18859_Content_8 = {
    Text = "Bạn đột nhiên hiểu ra, có người hoặc có thứ gì đó đang điều khiển cô ấy. \n Bạn đang định giúp cô ấy thoát khỏi sự ràng buộc thì thấy những sợi dây đen đột nhiên mỏng dần, cuối cùng hoàn toàn biến mất."
  },
  AvgDialog_18859_Content_9 = {
    Text = "\"Không… Ai Jī Sī…?\""
  },
  AvgDialog_18860_Content_1 = {
    Text = "Bạn đuổi theo Ai Jī Sī, chạy tới đỉnh tháp chuông trong hơi thở gấp gáp."
  },
  AvgDialog_18860_Content_2 = {
    Text = "Ai Jī Sī đứng vững trên bục, cô ấy quay người lại, hai mắt cô ấy bị che kín chảy xuống những giọt nước mắt màu máu lẫn rỗng rỗng."
  },
  AvgDialog_18860_Content_3 = {
    Text = "Xin lỗi…… tôi…… không thể chịu đựng thêm nữa……"
  },
  AvgDialog_18860_Content_4 = {
    Text = "Thân thể của cô ấy nhanh chóng phình to, da thịt giống như sôi lên, nổi lên các bọng nước lớn nhỏ, rất nhanh đã chặn kín lối cầu thang hiện tại và chèn vào trần nhà cao vút."
  },
  AvgDialog_18860_Content_5 = {
    Text = "Trong tiếng kinh hoàng của các chi thể bị bẻ cong và vặn xoắn, giọng nói của cô gái chỉ còn lại một chút mỏng manh, sắp tan biến."
  },
  AvgDialog_18860_Content_6 = {
    Text = "<Shake:nhanh… chạy…>"
  },
  AvgDialog_18861_Content_1 = {
    Text = "Đừng trông mặt mà bắt hình dong"
  },
  AvgDialog_18861_Content_10 = {
    Text = "Một ngày cô ấy biến mất, anh ta tìm kiếm mọi nơi."
  },
  AvgDialog_18861_Content_11 = {
    Text = "Bạn hãy chạy trước! Đừng lo cho chúng tôi! Liên lạc ngay với trường học, nhanh lên!"
  },
  AvgDialog_18861_Content_12 = {
    Text = "Anh lục tủ quần áo. Anh nhìn dưới giường."
  },
  AvgDialog_18861_Content_13 = {
    Text = "<Shake:anh, anh trai… đằng sau, đằng sau!>"
  },
  AvgDialog_18861_Content_15 = {
    Text = "Cái móng vuốt đen xé toạc làn sương và chụp lấy mái tóc người phụ nữ."
  },
  AvgDialog_18861_Content_16 = {
    Text = "Dải lụa đỏ nhẹ nhàng trôi xuống, đường nét của con mắt khổng lồ đột nhiên hiện ra từ trong bóng tối."
  },
  AvgDialog_18861_Content_17 = {
    Text = "Anh ta đã đi vòng quanh tầng hầm nơi có lò hơi đang cháy."
  },
  AvgDialog_18861_Content_18 = {
    Text = "Đôi mắt chớp theo nhịp bài đồng dao, khuôn mặt của chàng trai trẻ trong khoảnh khắc đó chuyển sang màu nhợt nhạt và cứng đờ. \nAnh ta há miệng, tiếng thét cùng với thân thể đông cứng lại thành một pho tượng đá."
  },
  AvgDialog_18861_Content_19 = {
    Text = "À……à!!"
  },
  AvgDialog_18861_Content_2 = {
    Text = "Sương mù dày đặc nhấn chìm những con phố ẩm ướt và u tối, ánh đèn vàng nhạt phản chiếu trên mặt nước đọng, như đang hướng về thế giới u ám này."
  },
  AvgDialog_18861_Content_20 = {
    Text = "Ông Charlie không thể tìm thấy con mèo vằn của mình ở đâu cả."
  },
  AvgDialog_18861_Content_21 = {
    Text = "<Shake:không, không, đừng… xin hãy tha cho tôi…>"
  },
  AvgDialog_18861_Content_22 = {
    Text = "Vì vậy anh ấy khóc, khóc——"
  },
  AvgDialog_18861_Content_23 = {
    Text = "<Shake:tôi còn có một em gái……xin đừng giết tôi……>"
  },
  AvgDialog_18861_Content_24 = {
    Text = "—— cho đến khi chính mình cũng biến mất."
  },
  AvgDialog_18861_Content_25 = {
    Text = "<BigShake:à———!>"
  },
  AvgDialog_18861_Content_26 = {
    Text = "08:00, Đại học Misaque, Tòa nhà Hệ thống Thức tỉnh\nTrong văn phòng của William·Delaplane"
  },
  AvgDialog_18861_Content_27 = {
    Text = "Bạn ngồi trước bàn làm việc, dưới ánh mắt của William, cẩn thận xem xét các vật phẩm trên đĩa trước mặt: \nmột bàn tay đá được điêu khắc tinh xảo và một đoạn ruy-băng đỏ với nút bạc vuông."
  },
  AvgDialog_18861_Content_28 = {
    Text = "Thế nào."
  },
  AvgDialog_18861_Content_29 = {
    Text = "Bạn có chút căng thẳng. William không chỉ là đàn anh của bạn, mà còn là thầy huấn luyện của bạn. \nMặc dù bây giờ bạn đã là một Người Giữ Gìn chính thức, vẫn có cảm giác như đang chịu sự kiểm tra của ông ấy."
  },
  AvgDialog_18861_Content_3 = {
    Text = "Một chiếc giày da đã dẫm nát bóng phản chiếu trong nước đọng, sau đó vội vàng rời đi."
  },
  AvgDialog_18861_Content_30 = {
    Text = "Đây có lẽ là một phần của tượng. Tuy nhiên, tượng rỗng ruột như thế này tôi vẫn chưa từng thấy. \nVà những thứ bên trong này… là máu?"
  },
  AvgDialog_18861_Content_31 = {
    Text = "Điều này có liên quan đến hai học sinh chạy ra khỏi trường đúng không?"
  },
  AvgDialog_18861_Content_32 = {
    Text = "Đúng vậy. Năm ngày trước, hai học sinh đã tự ý rời trường, đến <Blue:Lentiennam phía đông>, nhằm điều tra <Red:\"vụ án giết người hàng loạt Xẻ Thịt\">."
  },
  AvgDialog_18861_Content_33 = {
    Text = "Đêm đó, hai người đang đi trên đường Bernard, gần <Blue:xưởng lao động Lily>nghe thấy tiếng kêu cứu,đi xem,phát hiện một phụ nữ đang bị<Yellow:thực thể sống không rõ> truy sát."
  },
  AvgDialog_18861_Content_34 = {
    Text = "Hai học sinh thực hiện theo lời dạy của trường, cố gắng cứu người nhưng đã bị tấn công. Cuối cùng, học sinh năm nhất đã thành công thoát khỏi và trở về trường vào sáng sớm bốn ngày trước, còn học sinh năm hai thì vẫn mất tích."
  },
  AvgDialog_18861_Content_35 = {
    Text = "Ba ngày trước, học sinh năm nhất tỉnh lại từ trạng thái mất ý thức, thuật lại sự kiện đã xảy ra. \nAnh ấy cho chúng tôi biết rằng sức sống dường như có khả năng hóa đá, đã biến chân của một phụ nữ thành đá."
  },
  AvgDialog_18861_Content_36 = {
    Text = "Đá hóa? Không lẽ bức tượng đá này là… phần của học sinh mất tích?"
  },
  AvgDialog_18861_Content_37 = {
    Text = "Người sống sót không thể nhận ra, nhưng rất có thể. \nCòn về dải lụa này, rất có thể thuộc về nạn nhân nữ."
  },
  AvgDialog_18861_Content_38 = {
    Text = "Có phát hiện <Yellow:hiện tượng ăn mòn> tại hiện trường không? Với khả năng đặc biệt như vậy, tôi nghi ngờ sinh vật lạ kia thực chất là một <Yellow:thảm họa> mới sinh."
  },
  AvgDialog_18861_Content_39 = {
    Text = "Đây cũng là một điểm kỳ lạ. Thảm họa với vai trò là <Yellow:lõi của rã nứt>, lẽ ra phải thực hiện <Yellow:sự hòa tan không phân biệt> đối với khu vực xung quanh, tôi chưa từng nghe nói rằng chúng sẽ chủ động tấn công."
  },
  AvgDialog_18861_Content_4 = {
    Text = "Nhanh lên! Nó sắp đuổi kịp rồi!"
  },
  AvgDialog_18861_Content_40 = {
    Text = "Và ngoài một lượng nhỏ <Yellow:dung dịch ăn mòn>, chúng tôi không thể phát hiện bất kỳ dấu ăn mòn rõ ràng nào tại hiện trường, cũng như trong toàn bộ khu vực phía Đông, điều này không phù hợp với <Yellow:đặc điểm rỗng rỗng> của rã nứt."
  },
  AvgDialog_18861_Content_41 = {
    Text = "Hiện tại, chúng ta có thể xác định rằng: các vụ mất tích gần đây xảy ra tại <Blue:Lily phường lao động> và khu vực xung quanh, thậm chí cả vụ án <Red:\"Kẻ xé xác\">, đều có thể liên quan đến sức sống đó."
  },
  AvgDialog_18861_Content_42 = {
    Text = "Sau khi phân tích sơ bộ, chúng tôi xác định rằng sinh vật không rõ nguồn gốc có khả năng đang ẩn náu trong phường lao động của Lily."
  },
  AvgDialog_18861_Content_43 = {
    Text = "Xem ra, chúng ta cần phải đến đó một lần."
  },
  AvgDialog_18861_Content_44 = {
    Text = "Đúng vậy. Xác nhận tung tích của học sinh mất tích, điều tra sự thật đằng sau sự kiện, xác định và ngăn chặn kẻ cầm đầu vụ việc, đó chính là mục tiêu nhiệm vụ của bạn lần này."
  },
  AvgDialog_18861_Content_45 = {
    Text = "Thế nào, %player%, làm được không?"
  },
  AvgDialog_18861_Content_46 = {
    Text = "Dễ như ăn kẹo."
  },
  AvgDialog_18861_Content_47 = {
    Text = "Tôi sẽ cố gắng hết sức."
  },
  AvgDialog_18861_Content_48 = {
    Text = "Rất tốt. Xem xét mục tiêu lần này có thể có trí thông minh không thấp, tôi đề nghị các bạn đi lấy trang phục ngụy trang ở bộ hậu cần trước khi xuất phát, để tránh đánh động chúng."
  },
  AvgDialog_18861_Content_49 = {
    Text = "Hãy mang theo dải lụa này, có thể thông qua nó để điều tra nguyên nhân thực thể sức sống không rõ nguồn gốc tấn công chủ nhân của nó. Nếu có thể, cũng hãy xác nhận danh tính của nạn nhân."
  },
  AvgDialog_18861_Content_5 = {
    Text = "Ba người chạy như điên trong sương mù, họ thở hổn hển, dưới tiếng hát rộn ràng như những con chuột bị mèo săn đuổi, hoảng loạn không biết đường nào mà đi."
  },
  AvgDialog_18861_Content_50 = {
    Text = "Nhiệm vụ không quá nguy hiểm, chúng tôi sẽ giữ liên lạc thông suốt, <Blue:Đoã> và <Blue:Erika> cũng sẽ luôn sẵn sàng hỗ trợ và dẫn dắt bạn."
  },
  AvgDialog_18861_Content_51 = {
    Text = "Bạn sờ lên huy hiệu trường trước ngực, với <Blue:bạc tâm phân mảnh> chính là bảo đảm cho việc liên lạc từ xa của các bạn."
  },
  AvgDialog_18861_Content_52 = {
    Text = "Đừng trì hoãn nữa, hãy bắt đầu ngay thôi!"
  },
  AvgDialog_18861_Content_53 = {
    Text = "Nguyện Chìa Khóa Bạc soi sáng con đường phía trước."
  },
  AvgDialog_18861_Content_54 = {
    Text = "13:07,khu đông Lentiennam \n một ngõ nhỏ"
  },
  AvgDialog_18861_Content_55 = {
    Text = "Mấy đứa trẻ mặc quần áo sơ sài, gầy nhỏ, đang quây quần trong hẻm, có vẻ đang bàn bạc điều gì."
  },
  AvgDialog_18861_Content_56 = {
    Text = "Lần này vẫn như cũ, tôi và Brun sẽ phụ trách hành động, các người phụ trách làm nhiễu loạn kẻ ngốc, giúp tôi kéo dài thời gian. Kết thúc thì tập trung ở cửa sau phường bánh mì."
  },
  AvgDialog_18861_Content_57 = {
    Text = "Bạn không định quay lại xưởng lao động phường nữa sao?"
  },
  AvgDialog_18861_Content_58 = {
    Text = "Phải mua ít đồ ăn trước đã. Bánh mì ở nơi đó cứng hơn cả đá, nuốt cũng không nuốt được, tôi thực sự không chịu nổi nữa rồi."
  },
  AvgDialog_18861_Content_59 = {
    Text = "Bà Lắc từ cửa hàng sữa nói rằng, một khi đã vào đó thì không thể ra được, thậm chí chết cũng không ra được, rất đáng sợ, liệu chị gái của bạn có phải đã…"
  },
  AvgDialog_18861_Content_6 = {
    Text = "Ông Charlie có một con mèo vằn mà ông yêu quý vô cùng."
  },
  AvgDialog_18861_Content_60 = {
    Text = "Không được nói bậy! Chị lớn chắc chắn sẽ không sao, phải không Jenkin?"
  },
  AvgDialog_18861_Content_61 = {
    Text = "Cô gái không trả lời, chỉ nhìn ra ngoài hẻm. \nChuột trên vai cô nhẹ nhàng dùng mũi chạm vào cô, như thể đang an ủi, lại như thể lo lắng."
  },
  AvgDialog_18861_Content_62 = {
    Text = "Đường phố náo nhiệt, một chiếc xe hơi toàn thân sơn đen, đánh bóng loáng từ từ dừng lại. \nHai người từ trên xe bước xuống, họ mặc quần áo thanh lịch, một trong số họ có mái tóc bạc ấn tượng."
  },
  AvgDialog_18861_Content_63 = {
    Text = "Thấy hai kẻ dễ bị lợi dụng kia chưa? Mục tiêu hôm nay chính là họ. \nChuẩn bị bắt đầu!"
  },
  AvgDialog_18861_Content_64 = {
    Text = "13 giờ 10, quận Đông của Lentiennam \n một đường phố"
  },
  AvgDialog_18861_Content_65 = {
    Text = "Bạn vừa xuống xe, đã bị không khí ẩm ướt và mùi thối rữa làm cho khó thở."
  },
  AvgDialog_18861_Content_66 = {
    Text = "Một cơn chóng mặt mạnh mẽ kèm theo tiếng ù tai dữ dội đột nhiên ập đến bạn. Những hình ảnh mờ ảo lướt qua trong tâm trí bạn, dường như đã từng nhìn thấy cảnh tượng tương tự."
  },
  AvgDialog_18861_Content_67 = {
    Text = "Có phải là ảo giác, hay đó là một phần ký ức mà bạn đã mất? \nChưa kịp hoài niệm, bạn đã bị một nhóm trẻ con đang chơi đùa va phải."
  },
  AvgDialog_18861_Content_68 = {Text = "!"},
  AvgDialog_18861_Content_69 = {
    Text = "Bạn ôm lấy cánh tay bị đau do va chạm, để ý thấy *Ramona* đang nhìn bạn với nụ cười nửa miệng."
  },
  AvgDialog_18861_Content_7 = {
    Text = "Chân tôi, chân tôi không thể động được rồi, cứu tôi! Cứu tôi!"
  },
  AvgDialog_18861_Content_70 = {
    Text = "Có chuyện gì vậy?"
  },
  AvgDialog_18861_Content_71 = {
    Text = "Cô ấy chỉ vào túi của bạn, bạn nhìn theo hướng ngón tay cô ấy chỉ, đột nhiên nhớ ra một câu nói. \n\"Lễ chào mừng khét tiếng nhất ở khu Đông chính là việc ví tiền của bạn biến mất mà không hề hay biết.\""
  },
  AvgDialog_18861_Content_72 = {
    Text = "Không phải chứ… ví của tôi!"
  },
  AvgDialog_18861_Content_73 = {
    Text = "Nhanh lên, %player%, muộn quá tháng này sẽ không đủ tiền mua bánh ngọt nhỏ nữa đâu."
  },
  AvgDialog_18861_Content_8 = {Text = "Bà!"},
  AvgDialog_18861_Content_9 = {
    Text = "Anh trai đừng qua, anh ơi!"
  },
  AvgDialog_18862_Content_1 = {
    Text = "Ramona đã chặn đòn tấn công của Ai Jī Sī. Ai Jī Sī lảo đảo và lui lại vài bước một cách khó khăn, hai tay run rẩy, tay che mắt từ kẽ ngón tay chảy ra nhiều chất lỏng màu đen đặc quánh."
  },
  AvgDialog_18862_Content_10 = {
    Text = "Đừng lại đây… Đừng lại đây!"
  },
  AvgDialog_18862_Content_11 = {
    Text = "Cô gái quay người và chạy."
  },
  AvgDialog_18862_Content_12 = {
    Text = "Ai Jī Sī!"
  },
  AvgDialog_18862_Content_13 = {
    Text = "Đừng gọi nữa, nhanh đuổi theo!"
  },
  AvgDialog_18862_Content_2 = {
    Text = "Ai Jī Sī, bạn còn ổn không?"
  },
  AvgDialog_18862_Content_3 = {
    Text = "Cô ấy giật mình ngẩng đầu lên, ánh mắt lúc thì mờ ảo, lúc thì rõ ràng."
  },
  AvgDialog_18862_Content_4 = {
    Text = "Làm sao có thể… Không, không, tôi rõ ràng chưa ngủ, đừng…"
  },
  AvgDialog_18862_Content_5 = {
    Text = "Ai Jī Sī?"
  },
  AvgDialog_18862_Content_6 = {
    Text = "Đừng nói, đừng, đừng, bây giờ trời vẫn chưa tối, chưa có sương mù, anh không thể kiểm soát tôi, không thể…!"
  },
  AvgDialog_18862_Content_7 = {
    Text = "Ai Jī Sī che lấy đầu, thân thể nhỏ bé của cô ấy cong về phía trước dưới cơn đau không rõ nguyên nhân."
  },
  AvgDialog_18862_Content_8 = {
    Text = "Không được……làm thành bình tượng nến……tôi không muốn, đừng làm vậy chứ……"
  },
  AvgDialog_18862_Content_9 = {
    Text = "Cô có nghe thấy gì không, Ai Jī Sī, Ai Jī Sī?"
  },
  AvgDialog_18863_Content_1 = {
    Text = "***Cô ấy trông cũng không có bệnh, sao lại phát điên thế! Ai Jī Sī cẩn thận, tránh ra!"
  },
  AvgDialog_18863_Content_2 = {
    Text = "Cô ấy nói rằng mình đã được chữa trị, có lẽ là vào thời điểm đó……\nTóm lại, phải dẫn cô ấy đến nơi ít người."
  },
  AvgDialog_18863_Content_3 = {
    Text = "Trước đó, hãy giải quyết bọn chúng trước."
  },
  AvgDialog_18864_Content_1 = {
    Text = "Bạn và Ramona vừa đánh vừa lui, rút về sân trước của phường mà không làm kinh động đến những người khác."
  },
  AvgDialog_18864_Content_2 = {
    Text = "Lại có sương rồi!"
  },
  AvgDialog_18864_Content_3 = {
    Text = "Không biết từ bao giờ, màn sương dày đặc bao trùm mọi thứ, cùng với sương là những tiếng rít kỳ quái, chúng vang lên từ nơi tầm mắt không thể xuyên thấu và dần dần tiến gần các bạn."
  },
  AvgDialog_18864_Content_4 = {
    Text = "Bạn và Ramona dựa lưng vào nhau, cảnh giác nhìn những bóng tối méo mó."
  },
  AvgDialog_18864_Content_5 = {
    Text = "Tại sao lại có dị thể ở đây? Chẳng phải bệnh nhân đã bị khóa lại rồi hay sao?"
  },
  AvgDialog_18864_Content_6 = {
    Text = "Dù từ đâu đến, chỉ cần đánh lui là được!"
  },
  AvgDialog_18864_Content_7 = {
    Text = "Ramona vung thanh kiếm mảnh, chủ động lao vào tấn công những con quái vật gần các người nhất."
  },
  AvgDialog_18865_Content_1 = {
    Text = "Quái vật biến dị ngã xuống trước thanh kiếm của Ramona, không lâu sau đó hóa thành những hạt bụi đen nhỏ bé, tan biến trong không khí."
  },
  AvgDialog_18865_Content_10 = {
    Text = "Bạn hít sâu một hơi, đứng thẳng thân thể."
  },
  AvgDialog_18865_Content_11 = {
    Text = "Cẩn thận nào, Ramona."
  },
  AvgDialog_18865_Content_12 = {
    Text = "Đừng lo làm gì, tôi biết giới hạn."
  },
  AvgDialog_18865_Content_2 = {
    Text = "Bạn lau mồ hôi trên trán, thở gấp và chớp mắt vài lần với sức lực."
  },
  AvgDialog_18865_Content_3 = {
    Text = "Bạn có khỏe không?"
  },
  AvgDialog_18865_Content_4 = {
    Text = "Không sao. chỉ là đầu có chút tức."
  },
  AvgDialog_18865_Content_5 = {
    Text = "Đầu tôi như muốn nổ tung ra khỏi mắt vậy."
  },
  AvgDialog_18865_Content_6 = {
    Text = "Còn tâm trạng đùa giỡn, có vẻ cũng không có chuyện gì lớn."
  },
  AvgDialog_18865_Content_7 = {
    Text = "Bạn cần nghỉ ngơi một chút không?"
  },
  AvgDialog_18865_Content_8 = {
    Text = "Nên nhanh chóng tìm được Jenkin, tôi luôn cảm thấy chuyện này không đơn giản như vậy."
  },
  AvgDialog_18865_Content_9 = {
    Text = "Một hình dáng nhỏ nhắn xuất hiện trước mặt bạn từ trong sương mù, cô ấy hơi cong đầu gối, cơ thể căng cứng, rõ ràng là tư thế tấn công."
  },
  AvgDialog_18866_Content_1 = {
    Text = "À, ở đó chẳng có ai cả, có phải bạn nhìn nhầm rồi không?"
  },
  AvgDialog_18866_Content_2 = {
    Text = "Cô Mary, cô đang đi đâu vậy, ôi cô Mary!"
  },
  AvgDialog_18867_Content_1 = {Text = "%player%!"},
  AvgDialog_18867_Content_10 = {
    Text = "Cô Sara, tôi rất sợ, xin hãy giúp tôi……"
  },
  AvgDialog_18867_Content_11 = {
    Text = "Cô Sara…"
  },
  AvgDialog_18867_Content_12 = {
    Text = "Sao vậy, Ai Jī Sī?"
  },
  AvgDialog_18867_Content_13 = {
    Text = "Cô Sara, cô có thể hát lại bài hát đó một lần nữa không, chỉ một lần thôi? Tôi muốn nói là, nếu như vậy không gây phiền phức cho cô…"
  },
  AvgDialog_18867_Content_14 = {
    Text = "Kính yêu bé Tiểu Ai Jī Sī, bạn hãy nghe đây, bạn là đứa trẻ ngoan và hiểu chuyện nhất trong cả phường. Bạn là người mà mọi người yêu quý nhất."
  },
  AvgDialog_18867_Content_15 = {
    Text = "Vì vậy, thỉnh thoảng thả lỏng một chút cũng không sao cả. Hiểu chưa nhé?"
  },
  AvgDialog_18867_Content_16 = {
    Text = "Thế… tôi, tôi muốn nghe cô Sara hát lại bài hát thiếu nhi."
  },
  AvgDialog_18867_Content_17 = {
    Text = "Không vấn đề gì. \n Ông Charlie có một con mèo vằn mà ông ấy rất yêu thích…"
  },
  AvgDialog_18867_Content_18 = {
    Text = "Bạn đột ngột mở mắt, bước vào thế giới thực đầy màu sắc."
  },
  AvgDialog_18867_Content_19 = {
    Text = "%player%,bạn có sao không?"
  },
  AvgDialog_18867_Content_2 = {
    Text = "Trong khi Ramona kìm hãm Sara ở xa, bạn nhanh chóng tập trung tinh thần, chìm vào không gian hoàn toàn đen tối dần trở nên quen thuộc."
  },
  AvgDialog_18867_Content_20 = {
    Text = "Bạn gật đầu dù đang choáng váng. \nLúc này, bạn bắt gặp một hình dáng màu trắng từ khóe mắt."
  },
  AvgDialog_18867_Content_21 = {
    Text = "Ai Jī Sī? Ở đây rất nguy hiểm, mau trở về tìm Jenkin đi."
  },
  AvgDialog_18867_Content_22 = {
    Text = "Cô Sara, cô có phải đang ngủ không?"
  },
  AvgDialog_18867_Content_23 = {Text = "……?"},
  AvgDialog_18867_Content_24 = {
    Text = "Cũng được, cô Sara đã rất rất lâu rồi không ngủ ngon."
  },
  AvgDialog_18867_Content_25 = {
    Text = "Để không để phường bị giải thể, cô ấy chạy khắp nơi, gặp những ông chủ và bà chủ giàu có sống trong lâu đài, không có thời gian ăn cơm, không có thời gian nghỉ ngơi."
  },
  AvgDialog_18867_Content_26 = {
    Text = "Tối về đến phường, cô ấy thắp một cây nến trong văn phòng, miệt mài tính toán xem số tiền xin được từ ông chủ có đủ dùng không."
  },
  AvgDialog_18867_Content_27 = {
    Text = "Xem trang sức cầu được từ các bà tiểu thư có thể đổi được bao nhiêu tiền."
  },
  AvgDialog_18867_Content_28 = {
    Text = "Họ đều cười cô ấy, nói những lời rất tổn thương. Cô Sara chưa từng giận, còn an ủi tôi và hát cho chúng tôi nghe."
  },
  AvgDialog_18867_Content_29 = {
    Text = "Cô ấy rất tốt với chúng tôi, thật sự. Với tôi cũng vậy, tốt vô cùng."
  },
  AvgDialog_18867_Content_3 = {
    Text = "Chìa khóa bạc rung động và phát ra tiếng vo ve dữ dội, bóng tối trước mắt bạn cũng thay đổi mấy lần, dần dần từ mép tầm nhìn sáng lên."
  },
  AvgDialog_18867_Content_30 = {
    Text = "Tôi là gánh nặng của mẹ, bị mẹ bỏ rơi. Ông quản lý trước đây không chịu nhận tôi, là cô Sara nói rằng cô ấy sẵn sàng làm hai công việc để đón tôi vào."
  },
  AvgDialog_18867_Content_31 = {
    Text = "Từ đó tôi thề rằng, tôi nhất định không được làm gánh nặng cho cô Sara, nhất định phải trở thành một đứa trẻ có ích."
  },
  AvgDialog_18867_Content_32 = {
    Text = "Xin lỗi, Sara. Tôi đã cố gắng rất nhiều, nhưng vẫn không thể bảo vệ được Michael, không thể bảo vệ được bạn. Xin lỗi."
  },
  AvgDialog_18867_Content_33 = {
    Text = "Ai Jī Sī nhẹ nhàng chạm vào má của Sara, sau đó quay sang các bạn."
  },
  AvgDialog_18867_Content_34 = {
    Text = "Ai Jī Sī, bạn.."
  },
  AvgDialog_18867_Content_35 = {
    Text = "Các bạn có muốn biết những gì đã xảy ra vào đêm qua đúng không?"
  },
  AvgDialog_18867_Content_36 = {
    Text = "Cô gái mở rộng miệng, lộ ra một biểu cảm miễn cưỡng gần như là cười."
  },
  AvgDialog_18867_Content_37 = {
    Text = "Hãy thả bé Lucy và cô Sara ra. \nTôi mới chính là Jack Bào Thây mà các người vẫn luôn tìm kiếm."
