  },
  AvgDialog_18870_Content_30 = {
    Text = "Có mùi máu, rất nhẹ, có thể đã được ai đó dọn dẹp. \nDựa vào độ ẩm, có lẽ chỉ mới xảy ra trong giờ này."
  },
  AvgDialog_18870_Content_31 = {
