  AvgDialog_18872_Content_28 = {
    Text = "Đúng vậy. Còn về những gì đứa trẻ nói về viên ngọc quý, đó hoàn toàn là chuyện vô căn cứ, xin ngài tin tôi, Ashe {Male=ngài,Female=cô}!"
  },
  AvgDialog_18872_Content_29 = {
    Text = "Jenkin lấy từ sâu trong túi xách ra hai chiếc nhẫn bạc."
  },
  AvgDialog_18872_Content_3 = {
    Text = "Dây chuyền ngọc lục bảo, nhẫn… kỳ lạ, sổ kế toán của tôi đâu?"
  },
  AvgDialog_18872_Content_30 = {
    Text = "Bạn có ý nói rằng hai món đồ nhỏ trong ngăn kéo bên phải của văn phòng là do tôi biến ra từ hư không sao?"
  },
  AvgDialog_18872_Content_31 = {
    Text = "Thế còn ở chỗ tôi thì sao? Trả lại cho tôi, đó là quà tặng từ những nhà tài trợ khác!"
  },
  AvgDialog_18872_Content_32 = {
    Text = "Ash {Male=ngài,Female=cô}, tin tôi đi, tôi chỉ coi chúng như những mặt hàng dự phòng để hỗ trợ phường. Làm sao có thể, làm sao có thể vì những thứ này mà gây thương tổn cho các đứa trẻ trong phường?"
  },
  AvgDialog_18872_Content_33 = {
    Text = "Vậy còn cái này thì sao?"
  },
  AvgDialog_18872_Content_34 = {Text = "……!!"},
  AvgDialog_18872_Content_35 = {
    Text = "Cúc tay áo?"
  },
  AvgDialog_18872_Content_36 = {
    Text = "Chúng tôi đã vào phòng từ hôm qua."
  },
  AvgDialog_18872_Content_37 = {
    Text = "Đó đã được quét dọn mới, sàn chưa khô, giữa các khe gạch vẫn còn sót lại vết máu. \nCái này có lẽ bị bỏ quên một cách vô tình, nằm ở góc đó."
  },
  AvgDialog_18872_Content_38 = {
    Text = "Nó được làm từ những vật liệu tinh tế, và công nghệ chế tác cũng khá tinh xảo. \nCả phường này, ngoài viện trưởng như ngài, còn ai khác có thể sở hữu món đồ trang trí như vậy?"
  },
  AvgDialog_18872_Content_39 = {
    Text = "Không phải, đó không phải của cô ấy! Không phải của Sara, mà là của tôi! Là tôi để lại ở đó!"
  },
  AvgDialog_18872_Content_4 = {
    Text = "? Ai vậy. \nMời vào."
  },
  AvgDialog_18872_Content_40 = {
    Text = "Đó là của cô ấy, đó là của cô ấy! Kẻ giết người, kẻ bắt cóc!"
  },
  AvgDialog_18872_Content_41 = {
    Text = "Bất chấp sự cản trở của Ai Jī Sī, Jenkin lao tới, túm lấy váy của Sara."
  },
  AvgDialog_18872_Content_42 = {
    Text = "Đồ khốn kiếp, nói cho ta biết, chị gái của ta đang ở đâu!<Big:các người đã đưa chị gái ta đi đâu rồi!>"
  },
  AvgDialog_18872_Content_43 = {
    Text = "Bạn đang chuẩn bị bước lên để khuyên ngăn, đột nhiên cảm thấy da đầu tê rần. \nCó thứ gì đó phía sau bạn, phía sau mọi người, đang dõi theo các bạn bằng ánh mắt đầy ác ý."
  },
  AvgDialog_18872_Content_44 = {
    Text = "Bạn quay đầu lại và thấy đống quần áo bẩn trong góc không biết từ khi nào đã ngọ nguậy."
  },
  AvgDialog_18872_Content_45 = {
    Text = "Dung dịch màu đen chảy ra từ kẽ vải, thấm ướt toàn bộ quần áo vốn khô ráo, tụ lại trên mặt đất thành những thể dị biến nhỏ giọt chất nhầy."
  },
  AvgDialog_18872_Content_46 = {Text = "Ramona!"},
  AvgDialog_18872_Content_5 = {
    Text = "Thưa Cô Sara."
  },
  AvgDialog_18872_Content_6 = {
    Text = "Cô Mary! \nXin hỏi, có điều gì cần tôi giúp đỡ không ạ?"
  },
  AvgDialog_18872_Content_7 = {
    Text = "Phải làm phiền bạn và tôi đi một chuyến rồi. \nAsh {Male=ngài,Female=cô} đã gặp phải một số vấn đề, hy vọng bạn có thể giải đáp."
  },
  AvgDialog_18872_Content_8 = {
    Text = "Ash {Male=ngài,Female=cô}? Điều này… có thể hoãn lại một chút không? Tôi đang có một chút việc."
  },
  AvgDialog_18872_Content_9 = {
    Text = "Tôi sợ rằng tôi phải kiên quyết."
  },
  AvgDialog_18873_Content_1 = {
    Text = "Cô bé, chúng tôi cũng muốn điều tốt nhất cho Ai Jī Sī. Tình trạng của cô ấy khá đặc biệt, nếu không kiểm soát tốt sẽ rất rắc rối."
  },
  AvgDialog_18873_Content_10 = {
    Text = "Jenkin, đừng đánh nữa! \n... Tôi đi đây rồi."
  },
  AvgDialog_18873_Content_11 = {Text = "……ah?!"},
  AvgDialog_18873_Content_12 = {
    Text = "Đây đều là điều tôi nên làm. Một khi đã bắt đầu, một khi trên người có… sẽ không…"
  },
  AvgDialog_18873_Content_13 = {
    Text = "Gọi là điều bạn nên làm? Dựa vào đâu chứ!"
  },
  AvgDialog_18873_Content_14 = {
    Text = "Bác sĩ Miller nói đúng, nếu tôi tái phát, sẽ gây rắc rối lớn cho mọi người. \nTôi không muốn gây tổn thương cho bạn, tôi… bạn hãy để tôi đi."
  },
  AvgDialog_18873_Content_15 = {
    Text = "Bạn, bạn có bệnh à?! Bạn làm gì vậy, tự ý hành động, tôi đã bảo là không được đi!"
  },
  AvgDialog_18873_Content_16 = {
    Text = "Jenkin——"
  },
  AvgDialog_18873_Content_17 = {
    Text = "Bác sĩ Miller."
  },
  AvgDialog_18873_Content_18 = {
    Text = "Hôm nay cứ dừng lại ở đây, sau này, nói cũng không muộn."
  },
  AvgDialog_18873_Content_19 = {
    Text = "……bạn có chắc không, thưa ông Rogers."
  },
  AvgDialog_18873_Content_2 = {
    Text = "Thậm chí có thể gây tổn thương cho những người xung quanh."
  },
  AvgDialog_18873_Content_20 = {
    Text = "Tôi nghĩ như vậy."
  },
  AvgDialog_18873_Content_21 = {
    Text = "Được rồi, tôi nghĩ, một tuần không kiểm tra chắc cũng ổn. \nVì vậy, tôi xin phép cáo lui. Tạm biệt, Sara, Rogers, và Ash{Male=ngài,Female=cô}."
  },
  AvgDialog_18873_Content_22 = {
    Text = "Bác sĩ Miller cúi chào mọi người và rời đi cùng với vài nhà nghiên cứu."
  },
  AvgDialog_18873_Content_23 = {
    Text = "Bạn có linh cảm không nên để họ đi, nhưng—hiện tại mọi thứ chỉ là phỏng đoán. Bạn không biết liệu họ có thực sự đến từ Hiệp hội Điêu khắc gia hay không, cũng như không biết còn bao nhiêu người và cứ điểm của họ ở đâu."
  },
  AvgDialog_18873_Content_24 = {
    Text = "Bạn nhìn về phía Ramona, vẻ mặt cô ấy u ám, rõ ràng có những lo ngại tương tự như bạn: \nNếu bây giờ giữ họ lại, liệu có phải chỉ là làm cho rắn lọt ra khỏi hang?"
  },
  AvgDialog_18873_Content_25 = {
    Text = "Tôi, tôi cũng chuẩn bị rời đi, cô Sara. Hẹn gặp lại vào tháng sau."
  },
  AvgDialog_18873_Content_26 = {
    Text = "Tôi sẽ đưa Ai Jī Sī và Jenkin đi nghỉ trước. \n Cô Sara, lát nữa gặp cô ở văn phòng, được không?"
  },
  AvgDialog_18873_Content_27 = {
    Text = "Ơ? có, Ai Jī Sī cô ấy——"
  },
  AvgDialog_18873_Content_28 = {
    Text = "Cô ấy có vẻ rất hoảng loạn, tôi hy vọng có thể ở bên cô ấy một lúc, giúp cô ấy bình tĩnh lại."
  },
  AvgDialog_18873_Content_29 = {
    Text = "Thì… được. phiền các người rồi, Ashe{Male=ngài,Female=cô}."
  },
  AvgDialog_18873_Content_3 = {
    Text = "Bạn xem, Ai Jī Sī, đây chính là hậu quả khi bạn không nghe lời và không hợp tác tốt."
  },
  AvgDialog_18873_Content_4 = {
    Text = "Người bạn quan tâm, những người xung quanh bạn…… tất cả đều sẽ phải gánh chịu hậu quả."
  },
  AvgDialog_18873_Content_5 = {
    Text = "Vâng lời, thuận theo, đừng phản kháng. Hãy biết rằng, thực ra bạn không có nơi nào để trốn."
  },
  AvgDialog_18873_Content_6 = {
    Text = "Xung quanh cái gì xung quanh, tôi với cô ấy ở bên nhau lâu như vậy, sao lại không sao?"
  },
  AvgDialog_18873_Content_7 = {
    Text = "……Jenkin……"
  },
  AvgDialog_18873_Content_8 = {
    Text = "Ai Jī Sī, đừng sợ, xem tôi xử lý hắn thế nào. Brun, cắn hắn!"
  },
  AvgDialog_18873_Content_9 = {Text = "Chít!"},
  AvgDialog_18874_Content_1 = {
    Text = "Tin tìm người"
  },
  AvgDialog_18874_Content_10 = {
    Text = "Hai người đừng bi quan như vậy, chúng tôi cũng hy vọng phường chế tạo ngày càng phát triển tốt hơn ——"
  },
  AvgDialog_18874_Content_11 = {Text = "Ugh!"},
  AvgDialog_18874_Content_12 = {
    Text = "Bên hông bị va mạnh, bạn cúi đầu nhìn xuống: một đứa trẻ gầy yếu ngã ngồi trên mặt đất, toàn thân không ngừng rung nhẹ."
  },
  AvgDialog_18874_Content_13 = {
    Text = "Có, có, có quái vật!!"
  },
  AvgDialog_18874_Content_14 = {
    Text = "Vài phút trước, Lily phường"
  },
  AvgDialog_18874_Content_15 = {
    Text = "Trong hành lang yên tĩnh, cánh cửa có bảng tên kim loại từ từ mở ra. \nMột con chuột lọt ra từ khe cửa, nó nhìn trái phải rồi kêu chíp chíp hai tiếng gọi đồng bọn phía sau."
  },
  AvgDialog_18874_Content_16 = {
    Text = "Lần trước ngươi cũng nói là không có ai! Nếu không phải gặp được Ai Jī Sī, ta chắc chắn sẽ gặp rắc rối lớn."
  },
  AvgDialog_18874_Content_17 = {
    Text = "Chít chít, chít chít chít chít!"
  },
  AvgDialog_18874_Content_18 = {
    Text = "Đúng rồi đúng rồi, những gì bạn nói đều đúng. brun nhà chúng ta lợi hại nhất!"
  },
  AvgDialog_18874_Content_19 = {
    Text = "Chít chít chít, chít chít"
  },
  AvgDialog_18874_Content_2 = {
    Text = "14:01,xưởng làm việc của Lily"
  },
  AvgDialog_18874_Content_20 = {
    Text = "Hãy yên tâm, người phụ nữ đó có rất nhiều trang sức vàng bạc, tôi chỉ lấy hai chiếc nhẫn, cô ta sẽ không nhận ra đâu!"
  },
  AvgDialog_18874_Content_21 = {
    Text = "Tuy nhiên……hehe, bây giờ tôi biết cô ấy để đồ tốt ở đâu rồi. Đợi tôi tìm thấy chị ấy, xem tôi không lấy hết của con đàn bà khốn nạn đó!"
  },
  AvgDialog_18874_Content_22 = {Text = "Chít!"},
  AvgDialog_18874_Content_23 = {
    Text = "Được rồi, đừng nói nữa——Ừ? \n Đó là… tiếng gì vậy?"
  },
  AvgDialog_18874_Content_24 = {
    Text = "Cuối hành lang, có thứ gì đó loé sáng một cái ở góc rẽ."
  },
  AvgDialog_18874_Content_25 = {Text = "Brun."},
  AvgDialog_18874_Content_26 = {
    Text = "Chuột nhảy xuống từ túi xách, dựa vào sự nhanh nhẹn đặc trưng của loài chuột, men theo góc tường lướt nhẹ nhàng đến chỗ rẽ để kiểm tra."
  },
  AvgDialog_18874_Content_27 = {
    Text = "Chít chít!"
  },
  AvgDialog_18874_Content_28 = {
    Text = "Nghe thấy bạn đồng hành báo an toàn, cô gái cúi người theo sau. \nCô ấy bám vào tường, khẽ nghiêng mình, và cảm thấy nhẹ nhõm hẳn ra khi nhận ra trước mặt không có ai."
  },
  AvgDialog_18874_Content_29 = {
    Text = "Quyết định nhanh chóng rời đi, cô gái rụt đầu lại, ánh mắt thoáng bắt gặp một bóng dáng nhợt nhạt."
  },
  AvgDialog_18874_Content_3 = {
    Text = "Như bạn thấy, dù chúng tôi đã cố gắng chứa chấp, nhưng số người cần giúp đỡ quá nhiều, như vậy này, phường lao động này cũng không thể duy trì được lâu nữa. Tôi…!"
  },
  AvgDialog_18874_Content_30 = {Text = "?"},
  AvgDialog_18874_Content_31 = {
    Text = "Cô bước vào hành lang và phát hiện một vật thể trắng không đều nằm trên sàn gỗ bẩn thỉu, giống như một loại đá nào đó."
  },
  AvgDialog_18874_Content_32 = {
    Text = "Đó dường như là một phần của mặt nạ đá, được chế tác rất tinh xảo, thậm chí mỗi sợi lông mày cũng được điêu khắc cẩn thận, như thể đang sống."
  },
  AvgDialog_18874_Content_33 = {
    Text = "Gì vậy, trong phường không thấy có chế tác mặt nạ đá hoặc tượng đâu."
  },
  AvgDialog_18874_Content_34 = {
    Text = "Cô ấy nghiêng đầu, nhìn trái nhìn phải, tò mò dùng ngón trỏ chọc nhẹ."
  },
  AvgDialog_18874_Content_35 = {
    Text = "Sao vẫn còn ấm……"
  },
  AvgDialog_18874_Content_36 = {
    Text = "Cô đang định nhặt mặt nạ lên, thì đôi môi đá đột nhiên mở ra, thốt lên một tiếng rên rỉ đau đớn không thể tồn tại."
  },
  AvgDialog_18874_Content_37 = {Text = "!!"},
  AvgDialog_18874_Content_38 = {
    Text = "Cô ấy lùi hai bước trong sự kinh hoàng, giữa những hơi thở gấp gáp như ngửi thấy hơi thở tanh tưởi của sự phân hủy."
  },
  AvgDialog_18874_Content_39 = {
    Text = "Quái, quái vật… quái vật!"
  },
  AvgDialog_18874_Content_4 = {
    Text = "Cô Sara mỗi ngày đều rất vất vả, còn bán đi những thứ cô ấy thích nhất, chỉ để hỗ trợ phường. Xin hãy giúp chúng tôi…"
  },
  AvgDialog_18874_Content_40 = {
    Text = "14:37, xưởng lao động của Lilian\nphòng của Ai Ji Si"
  },
  AvgDialog_18874_Content_41 = {
    Text = "Rồi tôi chạy, rồi tôi va phải bạn. Sau đó, các bạn nhất định đưa tôi đi \"nghỉ ngơi\", và giờ tôi ở đây."
  },
  AvgDialog_18874_Content_42 = {
    Text = "Lần này đủ chi tiết rồi đúng không nhỉ?"
  },
  AvgDialog_18874_Content_43 = {Text = "Ừm…"},
  AvgDialog_18874_Content_44 = {
    Text = "Hai đứa trẻ ngồi cạnh nhau trên giường, bạn nhìn các cô bé, đặc biệt là Jenkin, cuối cùng vẫn đặt ra câu hỏi đó."
  },
  AvgDialog_18874_Content_45 = {
    Text = "Bạn… rốt cuộc là trai hay gái vậy?"
  },
  AvgDialog_18874_Content_46 = {
    Text = "Mắt cậu có vấn đề à!? Tôi là con gái, con gái!"
  },
  AvgDialog_18874_Content_47 = {
    Text = "Xác nhận một chút, xác nhận một chút."
  },
  AvgDialog_18874_Content_48 = {
    Text = "Thật là, người gì vậy, đầu óc có vấn đề không……\nHỏi xong chưa? Đến lượt tôi rồi."
  },
  AvgDialog_18874_Content_49 = {
    Text = "Tay Jenkin lắc một cái, từ đâu đó lấy ra một cái ví da. \nHình dáng quen thuộc, hình in huy hiệu trường Misaque: Đúng rồi, đó là ví của bạn, chỉ có điều…"
  },
  AvgDialog_18874_Content_5 = {
    Text = "Đừng nói nữa, người bạn đáng thương và dễ thương của tôi, Ai Jī Sī. Nếu phường thực sự không được nữa, tôi thà chết đói cũng tuyệt đối không để bạn đói!"
  },
  AvgDialog_18874_Content_50 = {
    Text = "… bên trong làm sao lại trống không, tiền của tôi đâu!"
  },
  AvgDialog_18874_Content_51 = {
    Text = "Đó không phải là điểm quan trọng!"
  },
  AvgDialog_18874_Content_52 = {
    Text = "Khụ khụ, dù sao, đừng thấy tôi như thế này, tôi vẫn nhận biết được chút chữ nghĩa. \nBên trong này không phải là chứng chỉ của {Male=ngài,Female=cô}, %player%."
  },
  AvgDialog_18874_Content_53 = {
    Text = "Nếu tôi nói cho người phụ nữ khó chịu đó biết danh tính của hai người, bạn đoán xem cô ta có bảo những kẻ ở cửa đuổi các người đi không?"
  },
  AvgDialog_18874_Content_54 = {
    Text = "Đây là con của phường không?"
  },
  AvgDialog_18874_Content_55 = {
    Text = "Không……không phải vậy, haha, phường chúng tôi, an ninh rất nghiêm ngặt, tuyệt đối không cho phép người không rõ lai lịch ra vào."
  },
  AvgDialog_18874_Content_56 = {
    Text = "Dựa vào phản ứng của Sara, cô ấy rõ ràng không nhận ra Jenkin. Vậy ——"
  },
  AvgDialog_18874_Content_57 = {
    Text = "Nếu bị phát hiện, rắc rối sẽ không chỉ là của mình tôi đâu nhỉ? Dù sao bạn cũng không phải người của phường."
  },
  AvgDialog_18874_Content_58 = {
    Text = "Tôi có cách để vào đây. Còn bạn, đã mất danh phận của người tự lực, muốn quay lại đây sẽ rất khó khăn."
