  },
  AvgDialog_18876_Content_18 = {
    Text = "Nhìn tôi này, đã quên cả thời gian rồi, Ashe{Male=ngài,Female=cô} chắc chắn đã đói lắm rồi."
  },
  AvgDialog_18876_Content_19 = {
