  },
  AvgDialog_18876_Content_29 = {Text = "!"},
  AvgDialog_18876_Content_3 = {
    Text = "Các bạn theo Sara đến một căn phòng với những chiếc giường đơn giản. \nNơi này dường như từng là nhà ăn, ở giữa vẫn còn chiếc bàn dài dùng để ăn."
  },
  AvgDialog_18876_Content_30 = {
    Text = "Bạn vội vàng nhìn về nguồn âm thanh, thấy một quái vật với khuôn mặt hoàn toàn bị thay thế bằng lỗ hổng màu đen đang giữ chặt Ai Ji Xư."
