  AvgDialog_18876_Content_45 = {
    Text = "Jenkin gật đầu mạnh mẽ, rồi biến mất trong nháy mắt."
  },
  AvgDialog_18876_Content_46 = {
    Text = "Ramona lấy ra khăn tay lau nhẹ máu cho Ai Jī Sī, động tác tránh khỏi cổ tay. \nAi Jī Sī nhìn Ramona, sau đó nhìn bạn, dường như đang do dự."
  },
  AvgDialog_18876_Content_47 = {
    Text = "Ai Jī Sī, cô có muốn nói gì không?"
  },
  AvgDialog_18876_Content_48 = {Text = "!"},
  AvgDialog_18876_Content_49 = {
    Text = "Không, không… tôi không có…"
  },
  AvgDialog_18876_Content_5 = {
    Text = "Tôi không muốn đặt niềm tin của nhà tài trợ vào rủi ro, vì vậy, tôi đã cố gắng giấu tất cả mọi thứ, chỉ có nhà tài trợ chính <Blue:Mr. Rogers> biết."
  },
  AvgDialog_18876_Content_50 = {
    Text = "Đừng sợ hãi, Ê Gi Si, dù là gì đi nữa, chúng tôi chắc chắn sẽ giúp bạn."
  },
  AvgDialog_18876_Content_51 = {
    Text = "Đừng sợ, Ai Ji Xơ, Bác sĩ Miller đến để giúp bạn."
  },
  AvgDialog_18876_Content_52 = {
    Text = "Đừng sợ, Ai Jī Sī, chỉ là tiêm phòng thôi, sẽ không đau đâu."
  },
  AvgDialog_18876_Content_53 = {
    Text = "Đừng sợ, Ai Jī Sī, sẽ qua nhanh thôi!"
  },
  AvgDialog_18876_Content_54 = {
    Text = "Đừng sợ hãi, Ai Ji Tư…"
  },
  AvgDialog_18876_Content_55 = {
    Text = "Đừng sợ……"
  },
  AvgDialog_18876_Content_56 = {
    Text = "Ai Jī Sī?"
  },
  AvgDialog_18876_Content_57 = {
    Text = "Cô gái lắc đầu mạnh mẽ. \nLúc này, Sara vội vàng đến bên các bạn sau khi đã an ủi xong các công nhân khác."
  },
  AvgDialog_18876_Content_58 = {
    Text = "Ai Jī Sī bạn—— Trời ơi, bạn chảy máu rồi! Băng gạc đâu, mau lấy băng gạc đến đây!"
  },
  AvgDialog_18876_Content_59 = {
    Text = "Tôi không sao, cô Sara. \nXin lỗi, đều là do tôi quá bất cẩn, khiến cô phải lo lắng."
  },
  AvgDialog_18876_Content_6 = {
    Text = "Bạn nhìn quanh bốn phía, những bệnh nhân đó có mức độ tan chảy khác nhau, mỗi người đều có hình dạng biến dạng, giống như người đàn ông vừa rồi."
  },
  AvgDialog_18876_Content_60 = {
    Text = "Bạn… ôi. Tôi đã nói bao nhiêu lần rồi, những kẻ điên này rất nguy hiểm, vậy mà bạn vẫn không chịu nghe, luôn khăng khăng nhận việc đưa cơm này. Sao bạn lại cố chấp vậy?"
  },
  AvgDialog_18876_Content_61 = {
    Text = "Xin lỗi… Tôi không muốn như vậy…"
  },
  AvgDialog_18876_Content_62 = {
    Text = "Tôi biết, bạn muốn chia sẻ gánh nặng cho mọi người, nhưng bạn cũng cần xem xét khả năng của mình. Bạn làm vậy chẳng phải là gây thêm phiền phức cho mọi người sao?"
  },
  AvgDialog_18876_Content_63 = {
    Text = "Thật là không để người ta yên tâm. Bạn như vậy bướng bỉnh, phải đến bao giờ mới trưởng thành ——"
  },
  AvgDialog_18876_Content_64 = {
    Text = "Đã nói đủ chưa!"
  },
  AvgDialog_18876_Content_65 = {
    Text = "Jenkin không biết từ lúc nào đã chạy trở lại. Cô ném xô nước xuống đất, chắn ngay trước mặt Ai Jī Sī."
  },
  AvgDialog_18876_Content_66 = {
    Text = "Ai Jī Sī mỗi ngày vất vả như vậy, giúp bạn làm nhiều việc như vậy, bạn còn có gì không hài lòng? \n Còn lớn lên, nếu lớn lên là nói gì làm nấy, tôi thấy cả đời không lớn lên là tốt nhất!"
  },
  AvgDialog_18876_Content_67 = {
    Text = "Đây là sao, làm sao vậy?"
  },
  AvgDialog_18876_Content_68 = {
    Text = "Bạn quay đầu theo tiếng động và phát hiện có hai người đứng sau lưng. \nTrong số đó, bạn nhận ra một người: cô ấy từng đưa cho bạn một bảng câu hỏi tâm lý trên phố."
  },
  AvgDialog_18876_Content_69 = {
    Text = "Ông Rogers, Bác sĩ Philips! \nThưa ông, ông không phải thường đến vào buổi tối sao? Nếu biết sớm hơn, tôi còn ra cửa đón ông nữa."
  },
  AvgDialog_18876_Content_7 = {
    Text = "Lạ thay, người mặc áo blouse trắng được gọi là \"<Blue:nghiên cứu viên>\" khi Sara giải thích lúc nãy, hiện không có ở đây."
  },
  AvgDialog_18876_Content_70 = {
    Text = "Tôi đã rất quen thuộc với nơi này, cô Sara, không cần phải phiền phức như vậy. \nSo với việc đó, tại sao Ai Jī Sī lại khócbuồn như vậy? Có ai bắt nạt cô ấy không?"
  },
  AvgDialog_18876_Content_71 = {
    Text = "Chưa phải là cô Sara này sao! Cô ta chính là…"
  },
  AvgDialog_18876_Content_72 = {
    Text = "Trong tiếng la hét của Jenkin, Clementine cúi người xuống, nắm lấy tay Ai Ji Si một cách thuần thục."
  },
  AvgDialog_18876_Content_73 = {
    Text = "Cô bé Ai Jī Sī có gặp phải rắc rối mới không, có nên nói chuyện với bác sĩ Clementine không?"
  },
  AvgDialog_18876_Content_74 = {
    Text = "Khoan đã, bạn là ai vậy? Đừng có kéo lung tung chứ!"
  },
  AvgDialog_18876_Content_75 = {
    Text = "Tôi và Tiểu Ai Jī Sī đã quen nhau từ lâu, cô bé mới đến. Trước đây, mỗi khi Ai Jī Sī buồn, cô ấy đều tìm tôi để trò chuyện."
  },
  AvgDialog_18876_Content_76 = {
    Text = "Dù sao, việc kể lể những rắc rối cũng là một phương pháp trị liệu tâm lý, và tôi lại là một người nghe rất chuyên nghiệp. \n Bạn có muốn tham gia cùng chúng tôi không? Bạn trông có vẻ đang lo lắng điều gì đó."
  },
  AvgDialog_18876_Content_77 = {
    Text = "Tôi mới không đi, tâm lý gì trị liệu gì đó, lạ lùng quá…"
  },
  AvgDialog_18876_Content_78 = {
    Text = "Thật đáng tiếc. Nếu bạn thay đổi ý kiến, hãy qua đây và tham gia nhé. \nĐi nào, Ai Ji Tư."
  },
  AvgDialog_18876_Content_79 = {
    Text = "Sau khi hai người rời đi, bạn chuyển sự chú ý trở lại phía trước."
  },
  AvgDialog_18876_Content_8 = {
    Text = "Có thể nói rằng ông Rogers là một trong những người đầu tiên phát hiện ra căn bệnh kỳ lạ. Ông luôn theo dõi tình trạng của các bệnh nhân và đã giới thiệu với chúng tôi <Blue:TS Miller>, người chuyên nghiên cứu các ca bệnh khó chữa."
  },
  AvgDialog_18876_Content_80 = {
    Text = "George Rogers, rất vui được gặp hai vị."
  },
  AvgDialog_18876_Content_81 = {
    Text = "Anh ta nhường ra một tay và nhẹ nhàng nắm lấy tay bạn. Trong khoảnh khắc lòng bàn tay chạm nhau, một cảm giác chóng mặt tột độ ập đến bạn."
  },
  AvgDialog_18876_Content_82 = {
    Text = "Mọi thứ xung quanh tan chảy nhanh như sáp, ngay cả người trước mặt bạn cũng biến dạng vặn vẹo. \nDưới khuôn mặt trẻ trung, bộ xương nhợt nhạt quấn vào nhau như những dây leo."
  },
  AvgDialog_18876_Content_83 = {
    Text = "Ảo ảnh kỳ quái biến mất không còn dấu vết sau vài lần chớp mắt, chỉ còn lại tiếng ong ong nhọn ở tai —— liệu đây là ảo giác do mệt mỏi gây ra, hay là một điềm báo nào đó?"
  },
  AvgDialog_18876_Content_84 = {
    Text = "Bạn không biết. Bạn chỉ biết rằng, điều này rất giống với trải nghiệm của bạn vài ngày trước ở nghĩa trang."
  },
  AvgDialog_18876_Content_85 = {
    Text = "… Mỗi tháng anh ấy đều tự mình đến để xem tình trạng của bệnh nhân, nhờ có anh ấy, chúng tôi mới có thể thành lập khu vực y tế này để chữa trị cho bệnh nhân. Anh ấy là ân nhân thực sự của xưởng chúng tôi."
  },
  AvgDialog_18876_Content_86 = {
    Text = "Cô Sara quá khen, quá khen rồi, tôi chỉ là một người bình thường muốn làm điều gì đó cho thế nhân mà thôi."
  },
  AvgDialog_18876_Content_87 = {
    Text = "Rất hân hạnh, ông Rogers. Tôi họ Ash, đây là người quản gia của tôi, Mary. \nCậu bé này là Jenkin… à?"
  },
  AvgDialog_18876_Content_88 = {
    Text = "Lại trốn đi đâu rồi?"
  },
  AvgDialog_18876_Content_89 = {
    Text = "Ai Jī Sī nắm tay Clementine, theo bước chân của đối phương đi dạo trong khuôn viên phía trước."
  },
  AvgDialog_18876_Content_9 = {
    Text = "Bác sĩ Miller đồng ý cung cấp cho chúng tôi sự chữa trị miễn phí, chỉ yêu cầu chúng tôi sử dụng \"<Blue:phương pháp điều trị thử nghiệm>\" của ông."
  },
  AvgDialog_18876_Content_90 = {
    Text = "Thì ra vậy, cái <Red:\"giọng nói\"> luôn xuất hiện trong đầu bạn vào ban đêm lại khiến bạn làm chuyện xấu nữa rồi?"
  },
  AvgDialog_18876_Content_91 = {
    Text = "Tôi đã thử khóa cửa phòng lại, bịt tai lại… nhưng \"âm thanh\" luôn có cách khiến tôi, khiến tất cả mọi người…"
  },
  AvgDialog_18876_Content_92 = {
    Text = "Họ đều không nhớ \"tiếng động\", chỉ có tôi, dù muốn quên cũng không thể nào quên được."
  },
  AvgDialog_18876_Content_93 = {
    Text = "Có rất nhiều người đã chết, còn chị của Jenkin nữa… Tôi thực sự không chịu đựng nổi nữa, nếu tiếp tục như thế này, sớm muộn gì mọi người sẽ bị phát hiện và bị cảnh sát bắt!"
  },
  AvgDialog_18876_Content_94 = {
    Text = "Bạn nghĩ rằng họ là vô tội?"
  },
  AvgDialog_18876_Content_95 = {
    Text = "Tôi biết họ là vô tội! Tất cả đều vì cái \"giọng nói\" đó, nó đã khiến mọi người không còn là chính mình nữa, tôi cũng... như vậy"
  },
  AvgDialog_18876_Content_96 = {
    Text = "Bạn có thể giúp tôi không, Bác sĩ Clementine? Mọi người không tin vào những cảnh báo của tôi, nhưng nếu là bạn nói, họ chắc chắn sẽ nghe theo."
  },
  AvgDialog_18876_Content_97 = {
    Text = "Tiếng \"âm thanh\" mà người khác không nghe thấy thực sự không thể coi là bằng chứng, và mọi người rất khó phản ứng với những cảnh báo không có bằng chứng, nhưng —— bạn cũng đừng nản lòng."
  },
  AvgDialog_18876_Content_98 = {
    Text = "Thế giới này, không có gì là không thể đổi lấy khi đánh cược cả mạng sống."
  },
  AvgDialog_18876_Content_99 = {
    Text = "Ai Jī Sī cúi đầu, như có điều suy nghĩ. \nPhía sau những thùng gỗ xếp chồng bên tường viện, một cái đầu đội mũ trùm màu nâu thò ra."
  },
  AvgDialog_18877_Content_1 = {
    Text = "Ai đã giết chim sâu"
  },
  AvgDialog_18877_Content_10 = {
    Text = "Công phường chìm trong sương mù, xung quanh tối tăm, nhưng điều này dường như không ảnh hưởng đến cô gái. \nCô ấy dùng hết sức lực, chạy về phía trước."
  },
  AvgDialog_18877_Content_11 = {
    Text = "Phải nhanh lên, nhất định phải nhanh! Nếu bị người khác phát hiện, nếu bị %player% phát hiện…\nHọ sẽ bắt người đó đi, chắc chắn sẽ không tha."
  },
  AvgDialog_18877_Content_12 = {
    Text = "Cô ấy rẽ qua một góc và bỗng dừng lại."
  },
  AvgDialog_18877_Content_13 = {
    Text = "Không, trời ơi không…"
  },
  AvgDialog_18877_Content_14 = {
    Text = "Không phải là bạn, bé Mike."
  },
  AvgDialog_18877_Content_15 = {
    Text = "20:50, phường của Lily\nPhòng của Ai Jī Sī"
  },
  AvgDialog_18877_Content_16 = {
    Text = "Jenkin đi một vòng quanh căn phòng không một bóng người, đặt hai tay lên hông và thở dài."
  },
  AvgDialog_18877_Content_17 = {
    Text = "Không ở trong toilet, cũng không ở trong bếp, cả phòng ăn cũng không có, cô ấy đã chạy đi đâu rồi ?"
  },
  AvgDialog_18877_Content_18 = {
    Text = "Cô ấy ngồi thẳng xuống đất, đưa tay vào dưới nệm và mò mẫm xung quanh."
  },
  AvgDialog_18877_Content_19 = {
    Text = "Thôi, mặc kệ vậy, cô ấy sớm muộn gì cũng sẽ trở về để ngủ, tôi sẽ ngồi đây vừa ăn kẹo vừa chờ cô ấy!"
  },
  AvgDialog_18877_Content_2 = {
    Text = "20:43,xưởng lao động của Lily an\nphòng khách"
  },
  AvgDialog_18877_Content_20 = {
    Text = "Chít chít chít!"
  },
  AvgDialog_18877_Content_21 = {
    Text = "Bạn không được tiết lộ đâu nhé! Mà thôi, sau này tôi sẽ mua cho cô ấy nhiều hơn ——"
  },
  AvgDialog_18877_Content_22 = {
    Text = "Cô ấy dừng lại, rút ra một vật từ bên trong. \n Dải lụa đỏ, nút vuông bạc trắng, một đầu trông như bị rách vụn, thô ráp."
  },
  AvgDialog_18877_Content_23 = {
    Text = "Đây là……chị ấy……?"
  },
  AvgDialog_18877_Content_24 = {
    Text = "20:50,xưởng lao động của Lily Ann \n sân trước phường"
  },
  AvgDialog_18877_Content_25 = {
    Text = "Công phường dưới màn đêm chìm vào giấc ngủ, bạn và Ramona vội vàng trở về, trong lòng dâng lên một dự cảm —— \nRất nhanh, sẽ có thứ gì đó ngoài các bạn phá vỡ sự yên tĩnh."
  },
  AvgDialog_18877_Content_26 = {Text = "%player%."},
  AvgDialog_18877_Content_27 = {
    Text = "Bạn lại nhắm mắt. Một cảm giác lạnh lẽo lan tỏa từ sau gáy ra tứ chi, những khúc ca không rõ nguồn gốc dần trở nên mờ ảo, tựa như sắp tan biến theo gió."
  },
  AvgDialog_18877_Content_28 = {
    Text = "Bạn mở mắt và phát hiện sương xung quanh cũng đã mờ dần."
  },
  AvgDialog_18877_Content_29 = {
    Text = "Tôi không cảm nhận được nữa, giống như… giống như âm thanh yếu đi."
  },
  AvgDialog_18877_Content_3 = {
    Text = "Rogers đang nghịch ngón tay của George, để bình tượng nến gật đầu với Jenkin."
  },
  AvgDialog_18877_Content_30 = {
    Text = "Có phải sóng tinh thần của cá thể đặc biệt có liên quan đến lớp sương này?"
  },
  AvgDialog_18877_Content_31 = {Text = "!"},
  AvgDialog_18877_Content_32 = {
    Text = "Từ hướng đó đến đây!"
  },
  AvgDialog_18877_Content_33 = {
    Text = "Các người lập tức phóng chạy về hướng có tiếng động, và va chạm mạnh với Jenkin ngay tại cửa phường."
  },
  AvgDialog_18877_Content_34 = {Text = "Jenkin?"},
  AvgDialog_18877_Content_35 = {
    Text = "Ai Jī Sī không ở trong phòng! Vừa rồi có thể là—à, dù sao cũng nhanh lên đi!"
  },
  AvgDialog_18877_Content_36 = {
    Text = "Nhớ lại cảnh tượng thảm khốc vừa nhìn thấy trên đường, bạn vội vàng bước vào phường. \nChẳng bao lâu, một tia sáng le lói xuất hiện phía trước hành lang."
  },
  AvgDialog_18877_Content_37 = {
    Text = "Đó là chiếc đèn lồng kiểu cũ, cầm trên tay, soi sáng mặt người phụ nữ và đứa trẻ."
  },
  AvgDialog_18877_Content_38 = {
    Text = "Ai Jī Sī!Tôi nghe thấy tiếng thét,bạn có sao không!"
  },
  AvgDialog_18877_Content_39 = {
    Text = "Cô gái co ro trong vòng tay Sara run rẩy, chôn mặt sâu hơn vào cổ bên cạnh của Sara. \nKhi nhìn thấy cảnh này, Jenkin hơi sững sờ, rồi quay sang Sara đầy tức giận."
  },
  AvgDialog_18877_Content_4 = {
    Text = "Xin chào, người bạn tốt. Bạn có thích George không?"
  },
  AvgDialog_18877_Content_40 = {
    Text = "Con đàn bà kia, có phải mày đã làm gì xấu với cô ấy không! Mày buông cô ấy ra, có nghe thấy không!"
  },
  AvgDialog_18877_Content_42 = {
    Text = "Sara im lặng đặt cô bé xuống. \n Ai Jī Sī cúi đầu, nhưng bạn vẫn nhìn thấy khuôn mặt cô ấy đầy nước mắt nhờ ánh đèn."
  },
  AvgDialog_18877_Content_43 = {
    Text = "Bạn có thể đưa cô ấy về nghỉ ngơi trước không? Ai Jī Sī đã lạc đường, lại sợ bóng tối, bây giờ rất cần nghỉ ngơi."
  },
  AvgDialog_18877_Content_44 = {
