  AvgDialog_18878_Content_10 = {
    Text = "Ông Charlie có một con mèo vằn mà ông yêu thương vô cùng…"
  },
  AvgDialog_18878_Content_11 = {
    Text = "\"chị chị... đừng đi...\""
  },
  AvgDialog_18878_Content_12 = {
    Text = "Giọng của Jenkin vang lên từ bên trong quả cầu ánh sáng. Nó muốn tiến gần bạn, nhưng ngay khi di chuyển đã bị những sợi dây đen mảnh mai siết chặt, chỉ có thể lùi lại, giống như một con rối bị điều khiển bởi bàn tay vô hình."
  },
  AvgDialog_18878_Content_13 = {
    Text = "Bạn đột nhiên hiểu ra, có người hoặc có thứ gì đó đang điều khiển cô ấy. \n Bạn đang định giúp cô ấy thoát khỏi sự ràng buộc thì thấy những sợi dây đen đột nhiên mỏng dần, cuối cùng hoàn toàn biến mất."
  },
  AvgDialog_18878_Content_14 = {
    Text = "\"Không… Ai Jī Sī…?\""
