  AvgDialog_18878_Content_5 = {
    Text = "Bạn chìm vào không gian thuần đen, những điểm sáng bạc yếu ớt nối liền thành từng dải, trôi nổi lên xuống như những con sóng theo quy luật khó mà đoán được."
  },
  AvgDialog_18878_Content_6 = {
    Text = "Bạn đứng giữa họ, lại như lơ lửng phía trên. Bạn là một trong số đó, nhưng lại không thực sự thuộc về họ. \nBạn không rõ họ cụ thể là ai, chỉ biết rằng bạn đến đây để tìm kiếm ai đó."
