  AvgDialog_18878_Content_7 = {
    Text = "\"chị...chị...\""
  },
  AvgDialog_18878_Content_8 = {
    Text = "Bạn nhìn về hướng có tiếng động, một điểm sáng đặc biệt mờ nhạt đang lấp lánh trong biển sao. \n Những sợi tơ đen ánh kim loại quái dị bị cuốn vào nó, kéo nó, khiến nó không thể cử động."
