  AvgDialog_18879_Content_1 = {
    Text = "Các bạn bước ra khỏi con hẻm, đến trước cổng sắt của trại tế bần."
  },
  AvgDialog_18879_Content_2 = {
    Text = "Cạnh cửa, một người đàn ông trung niên ngồi trên chiếc ghế gỗ, khuôn mặt bóng nhờn. Anh ta buộc một cây gậy đen ở eo và ngậm một điếu tẩu thuốc đen sẫm trong miệng."
