  AvgDialog_18879_Content_3 = {
    Text = "Các bạn đã để ý thấy, trên cánh tay người đàn ông còn sót lại một chút vết đen nhỏ, vết thương hình tam giác trông như một hố sâu nhỏ, chất lỏng sền sệt đang từ từ chảy ra từ đó."
  },
  AvgDialog_18879_Content_4 = {
    Text = "Ramona khẽ hắng giọng, nâng cằm cao và bước tới với dáng vẻ đầy kiêu hãnh, tựa như một quản gia quý tộc."
  },
  AvgDialog_18879_Content_5 = {
    Text = "Chào buổi sáng, thưa ông. Làm ơn thông báo có khách đến thăm."
  },
  AvgDialog_18879_Content_6 = {
    Text = "Lời cô ấy chưa dứt, thân thể của bảo vệ đột ngột biến dạng, chất nhầy từ ngực ngưng tụ thành một quái vật đen khổng lồ, trườn tới các người."
