  AvgDialog_18880_Content_13 = {
    Text = "Không……sẽ không đâu……"
  },
  AvgDialog_18880_Content_14 = {
    Text = "Cô bé nhỏ nhắn mà bạn quen thuộc đứng đó, miếng che mắt trắng rơi xuống, ánh mắt trống rỗng, tay cầm nửa đoạn dải lụa màu đỏ tươi."
  },
  AvgDialog_18880_Content_2 = {
    Text = "Đừng hỏi nữa, chạy ngay, Jenkin."
