  AvgDialog_18880_Content_3 = {
    Text = "Quái vật ngày càng gần, dần dần ép các người vào vực thẳm."
  },
  AvgDialog_18880_Content_4 = {
    Text = "Cô ấy chỉ là một đứa trẻ từ khu ổ chuột mà thôi, không hiểu biết gì cả, tuyệt đối không thể gây ra bất kỳ mối đe dọa nào cho các người"
  },
  AvgDialog_18880_Content_5 = {
