  AvgDialog_18880_Content_8 = {
    Text = "Trong khoảnh khắc giọng nói bị ngắt quãng, bóng dáng quen thuộc của bạn rơi từ trên cao xuống, vẫn nắm chặt nửa dải ruy-băng đỏ trong tay."
  },
  AvgDialog_18880_Content_9 = {
    Text = "Dây nơ là do bạn tiết kiệm tiền tiêu vặt trong một năm, tự tay đặt làm riêng cho cô ấy. \nBạn chưa bao giờ gặp cha mẹ ruột của mình, cô ấy chính là người thân thiết nhất của bạn."
  },
  AvgDialog_18881_Content_1 = {
    Text = "Bỗng nhiên, một bóng đen từ góc tường lao ra, cọ vào Ai Jī Sī và đập vào bức tường bên trái."
  },
  AvgDialog_18881_Content_10 = {
    Text = "Anh ta đột nhiên thoát khỏi người phía sau và lao thẳng về phía bạn."
  },
  AvgDialog_18881_Content_2 = {
    Text = "Đến lúc này bạn mới nhìn rõ, người xông ra là một người đàn ông tóc tai bù xù. \nAnh ta trần chân, mặc quần áo của nhà nuôi người nghèo, cổ tay và cổ chân có dấu vết bị trói buộc rõ ràng."
  },
  AvgDialog_18881_Content_3 = {
    Text = "Vài người có vẻ là nhân viên chăm sóc đuổi theo sau anh ta, cố gắng tách anh ta ra. \nNgười đàn ông không hề bị ảnh hưởng, anh ta ngả đầu ra sau, rồi đột nhiên đập đầu vào bức tường lạnh lẽo và cứng rắn."
  },
  AvgDialog_18881_Content_4 = {
    Text = "Ở sau lưng bạn, Ai Jī Sī hít một hơi sâu."
  },
  AvgDialog_18881_Content_5 = {Text = "——!"},
  AvgDialog_18881_Content_6 = {
    Text = "Tiếng va đập xương máu vào gạch đá dần tăng tần suất, người đàn ông như thể không cảm nhận được đau đớn, liên tục đâm vào tường."
  },
  AvgDialog_18881_Content_7 = {
    Text = "Máu văng lên, để lại những vết bẩn tối màu trên tường và mặt đất. \nBạn bước lên một bước chuẩn bị giúp đỡ, nhưng người đàn ông bất ngờ ngừng động tác."
  },
  AvgDialog_18881_Content_8 = {
    Text = "Anh ta hít mạnh một cái, ngửi xung quanh như động vật, rồi từ từ, cứng ngắc quay về phía bạn."
  },
  AvgDialog_18881_Content_9 = {
    Text = "Máu từ từ chảy xuống từ trán anh ta, vết thương sưng tấy do va chạm mạnh, da bị nứt ra, bạn thậm chí có thể nhìn thấy một chút màu trắng của xương."
  },
  AvgDialog_18882_Content_1 = {
    Text = "Các người chưa đuổi kịp được bao xa, lũ trẻ đang chơi đùa nhanh chóng tụ tập trước mặt các người, chặn đường đi của các người."
  },
  AvgDialog_18882_Content_2 = {
    Text = "Ông chủ tốt bụng, xin hãy cho tôi một chút tiền lẻ. Nếu không có Myanmar, thì bất kỳ loại tiền nào cũng được…"
  },
  AvgDialog_18882_Content_3 = {
    Text = "Nếu bạn lấy tay ra khỏi túi của %player%, chúng ta có thể cân nhắc lại."
  },
  AvgDialog_18882_Content_4 = {Text = "Hừ!"},
  AvgDialog_18882_Content_5 = {
    Text = "Đứa trẻ bỏ chạy."
  },
  AvgDialog_18882_Content_6 = {
    Text = "Có cần thiết phải dạy cho những đứa trẻ không may mắn thiếu giáo dục này một bài học nhỏ, bạn thấy thế nào?"
  },
  AvgDialog_18882_Content_7 = {
    Text = "Hãy thử xem."
  },
  AvgDialog_18882_Content_8 = {
    Text = "Họ dường như là một nhóm với người đội nón màu nâu."
  },
  AvgDialog_18882_Content_9 = {
    Text = "Vậy hãy xuất phát, đứng lên bảo vệ lẽ phải cũng là một nghĩa vụ của công dân."
  },
  AvgDialog_18883_Content_1 = {
    Text = "Orci lo lắng chạy nhanh, đi qua những bức tường gạch đỏ bị không khí ô nhiễm của Lentiennam làm đen dần."
