  AvgDialog_18883_Content_11 = {
    Text = "Xin lỗi rất nhiều, là do tôi đã không kịp thời chú ý đến tình hình xung quanh."
  },
  AvgDialog_18883_Content_12 = {
    Text = "Clementine nở một nụ cười dịu dàng, nhẹ nhàng phủi đi những hạt bụi không tồn tại trên vạt áo. \n Cô gật đầu chào rồi nhẹ nhàng rời đi."
  },
  AvgDialog_18883_Content_13 = {
    Text = "Các bạn ngẩng đầu nhìn lên, trên tấm biển sắt lớn viết rõ ràng mấy chữ rỉ sét \"Nhà nuôi trẻ mồ côi Lily\". \nDưới những chữ lớn đó, một bảo vệ ngồi không có gì làm."
  },
  AvgDialog_18883_Content_14 = {
    Text = "Đã đến nước này, chúng ta vào xem trước đi. \nCòn nhớ thân phận giả của các người không, Ashe {Male=ngài,Female=cô}, cậu chủ nhỏ Ashe?"
  },
  AvgDialog_18883_Content_15 = {
    Text = "Hãy yên tâm, cô quản gia Mary thân yêu."
  },
  AvgDialog_18883_Content_16 = {
    Text = "Xin chào và sẵn sàng phục vụ bà Mary."
  },
  AvgDialog_18883_Content_17 = {
    Text = "… thôi, lệch không nhiều là được."
  },
  AvgDialog_18883_Content_2 = {
    Text = "Lần đầu tiên làm việc cùng chủ công, không thể nào……"
  },
  AvgDialog_18883_Content_3 = {Text = "Ưa!"},
  AvgDialog_18883_Content_4 = {
    Text = "Cánh cửa sắt gắn trên tường gạch mở ra phía trong. Một phụ nữ mặc áo trắng bất ngờ lọt vào tầm mắt và va phải Orci."
  },
  AvgDialog_18883_Content_5 = {
    Text = "<Small:à……>"
  },
  AvgDialog_18883_Content_6 = {
    Text = "Xin lỗi, xin lỗi! Bạn có sao không?"
  },
  AvgDialog_18883_Content_7 = {
    Text = "Bạn và Ramona vừa kịp đuổi theo Orci."
  },
  AvgDialog_18883_Content_8 = {
    Text = "Xin lỗi, chúng tôi… À, cô là chuyên gia tâm lý vừa phát bảng câu hỏi lúc nãy?"
  },
  AvgDialog_18883_Content_9 = {
    Text = "Đây là niềm vinh hạnh to lớn đối với tôi khi bạn nhớ đến tôi, dù chúng ta chỉ gặp nhau một lần."
  },
  AvgDialog_18884_Content_1 = {
    Text = "Trong không gian ngầm chật hẹp lại ẩn chứa nhiều quái vật như vậy……"
  },
  AvgDialog_18884_Content_2 = {
    Text = "Trại tế bần này thật không thể coi thường."
  },
  AvgDialog_18884_Content_3 = {
    Text = "Suỵt, xin hãy yên lặng, các vị. Sắp kết thúc rồi."
  },
  AvgDialog_18885_Content_1 = {
    Text = "Quái vật màu đen rống lên một tiếng, hóa thành bùn nhão và ngã quỵ xuống đất."
  },
  AvgDialog_18885_Content_10 = {
    Text = "Bạn đã đỡ thi thể của bảo vệ dựa vào cánh cửa sắt, sau đó đứng dậy bước vào Nhà Từ Thiện Lily."
  },
  AvgDialog_18885_Content_11 = {
    Text = "Tại cuối góc, một hình bóng trắng lóe lên."
  },
  AvgDialog_18885_Content_12 = {
    Text = "Họ là... cần nhanh chóng quay lại trước khi họ gặp cô Sara, chúng ta hãy vào từ cửa sổ nhà bếp."
  },
  AvgDialog_18885_Content_13 = {
    Text = "Họ có thể giúp ích, đừng e ngại sự xuất hiện của họ."
  },
  AvgDialog_18885_Content_14 = {Text = "Đừng!"},
  AvgDialog_18885_Content_15 = {
    Text = "Những người đó sẽ không bị hù dọa bởi những điều xảy ra ở đây, tôi cam đoan với bạn."
  },
  AvgDialog_18885_Content_16 = {
    Text = "Không... không thể kéo thêm người vào được nữa... Những người đến gần chỗ này đều rất nguy hiểm, bạn biết rõ mà.."
  },
  AvgDialog_18885_Content_17 = {
    Text = "<Red:ông Anderson>."
  },
  AvgDialog_18885_Content_2 = {
    Text = "Này, này…… anh ta làm sao mà bỗng nhiên thay đổi thế này!"
  },
  AvgDialog_18885_Content_3 = {
    Text = "<Yellow:rỗng rỗng giai đoạn đầu của sự xói mòn>.\nKhông nên bùng phát sớm như vậy…… thậm chí không nên bùng phát."
  },
  AvgDialog_18885_Content_4 = {
    Text = "Hai giọng nói truyền qua huy hiệu, vang lên trong tâm trí các bạn."
  },
  AvgDialog_18885_Content_5 = {
    Text = "Nghe có vẻ như là sản phẩm của quá trình xúc tác nhân tạo."
  },
  AvgDialog_18885_Content_6 = {
    Text = "Sự phát triển bất thường của rỗng rỗng… có lẽ không thể tách rời khỏi <Yellow:sự mất tích của Điều tra viên Shawn Anderson>. \nE rằng đã có kẻ nhắm đến Viện Từ thiện… thậm chí là nhắm đến các bạn rồi."
  },
  AvgDialog_18885_Content_7 = {
    Text = "Chúng tôi sẽ chú ý."
  },
  AvgDialog_18885_Content_8 = {
    Text = "Giữ vững sự cảnh giác, Người Giữ Gìn."
  },
  AvgDialog_18885_Content_9 = {Text = "Tôi sẽ."},
  AvgDialog_18886_Content_1 = {
    Text = "Có vẻ như đứa trẻ mới đến này có chút khác biệt."
  },
  AvgDialog_18886_Content_2 = {
    Text = "Đã đến lúc phải nghiêm túc rồi."
  },
  AvgDialog_18887_Content_1 = {
    Text = "Đồng thời——\nOrci, qua cửa sổ, ngắm nhìn cảnh trong sân của nhà nuôi dưỡng người nghèo."
  },
  AvgDialog_18887_Content_10 = {
    Text = "Không, không được đưa cô ấy đi!"
  },
  AvgDialog_18887_Content_11 = {
    Text = "Cháu này, có phải cháu hiểu lầm gì đó không? \nChúng tôi là bác sĩ được Viện Trợ Giúp người nghèo thuê, cần đưa cô ấy đi kiểm tra sức khỏe định kỳ."
  },
  AvgDialog_18887_Content_12 = {
    Text = "Orci đỏ mặt, linh hoạt xử lý."
  },
  AvgDialog_18887_Content_13 = {
    Text = "Không được! {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn} đã nói, lát nữa chúng ta sẽ thay mặt Lord Ash tìm hiểu tình hình từ Ai Jī Sī, bây giờ không thể đưa cô ấy đi."
  },
  AvgDialog_18887_Content_14 = {
    Text = "Đối với những đứa trẻ không nghe lời, chúng ta cần phải dùng một chút biện pháp của người lớn."
  },
  AvgDialog_18887_Content_2 = {
    Text = "Cánh cửa sắt kẽo kẹt mở ra, một nhóm người mặc áo trắng tiến vào liên tiếp. \nNhững đứa trẻ xếp thành hàng nhỏ trong làn sương xám xịt, để họ tùy ý chọn lựa."
  },
  AvgDialog_18887_Content_3 = {
    Text = "Trong số những đứa trẻ, Orci nhận ra một hình dáng quen thuộc: \nCô bé mặc áo trắng nhỏ nhắn từng đến chào đón mọi người hôm đó."
  },
  AvgDialog_18887_Content_4 = {
    Text = "Cô co vai, cúi đầu, hai tay vò chặt mép áo, trông đầy vẻ hoảng sợ, nhưng vẫn chủ động đứng trước các đứa trẻ khác."
  },
  AvgDialog_18887_Content_5 = {
    Text = "Cô ấy cố thu mình lại càng nhỏ càng tốt, cố co rúm người lại để biến mất hẳn. Một bóng dáng cao lớn bao trùm lên cô, cô giật mình, không dám nhúc nhích."
  },
  AvgDialog_18887_Content_6 = {
    Text = "Tranh cãi bùng phát. \nQuái nhân mặc áo trắng nắm lấy cánh tay cô gái, dường như đang ép buộc cô tuân theo mình."
  },
  AvgDialog_18887_Content_7 = {
    Text = "—— Dừng lại!"
  },
  AvgDialog_18887_Content_8 = {
    Text = "Orci không thể kiềm chế được nữa, trực tiếp xông vào giữa người đàn ông mặc áo trắng và cô gái."
  },
  AvgDialog_18887_Content_9 = {
    Text = "Ài... cậu bé Ash?"
  },
  AvgDialog_18888_Content_1 = {
    Text = "Ông nội Robert……sao có thể……"
  },
  AvgDialog_18888_Content_2 = {
    Text = "Cẩn thận, anh ta có vẻ đã hoàn toàn mất lý trí!"
  },
  AvgDialog_18889_Content_1 = {
    Text = "Làm ơn, đừng làm hại cô Sara, tôi sẽ kể hết sự thật cho các người…"
  },
  AvgDialog_18889_Content_2 = {
    Text = "Ai……Ky-si……"
  },
  AvgDialog_18889_Content_3 = {
    Text = "Còn lại một tia ý thức!"
  },
  AvgDialog_18889_Content_4 = {
    Text = "Tiêu diệt những con quái vật này trước, kiềm chế Sara! Chúng ta còn cần hỏi cô ấy về tung tích của Sean!"
  },
  AvgDialog_18889_Content_5 = {Text = "Rõ ràng!"},
  AvgDialog_18890_Content_1 = {
    Text = "Ramona lách người ra sau lưng người đàn ông, một tay nắm lấy cổ tay anh ta, tay kia ấn vai anh ta xuống, bẻ cong cánh tay anh ta ra sau và khống chế chặt chẽ mọi cử động."
  },
  AvgDialog_18890_Content_10 = {
    Text = "Tôi đã rất quen thuộc với nơi này, cô Sara, không cần phải phiền phức như vậy. \nSo với việc đó, tại sao Ai Jī Sī lại khócbuồn như vậy? Có ai bắt nạt cô ấy không?"
  },
  AvgDialog_18890_Content_11 = {
    Text = "<Small:Tôi không sao cả, ông Rogers.>"
  },
  AvgDialog_18890_Content_12 = {
    Text = "Dưới ánh mắt hơi gấp gáp của hiệu trưởng, Ai Ji Si nuốt lại lời định nói. \nCô ấy cúi đầu chào mọi người, nhìn các bạn lần cuối, dáng vẻ nhỏ nhắn biến mất sau cánh cửa."
  },
  AvgDialog_18890_Content_13 = {
    Text = "Xin lỗi vì đã giấu các bạn về sự tồn tại của khu vực y tế, tôi chỉ lo sợ tình trạng của bệnh nhân có thể lây nhiễm cho các bạn……"
  },
  AvgDialog_18890_Content_14 = {
    Text = "Thôi, không nói về những chuyện đó nữa, xin phép tôi giới thiệu với các bạn người tài trợ lâu dài của chúng ta — ông Rogers, một nhà bình tượng nến nổi tiếng."
  },
  AvgDialog_18890_Content_15 = {
    Text = "Khu vực y tế này và việc điều trị cho bệnh nhân đều nhờ có anh ấy mới thực hiện được."
  },
  AvgDialog_18890_Content_16 = {
    Text = "George Rogers, rất vui được gặp ba vị."
  },
  AvgDialog_18890_Content_17 = {
    Text = "Anh ta đưa tay ra và nhẹ nhàng nắm lấy tay bạn. \n Khi lòng bàn tay chạm nhau, một cảm giác choáng váng dữ dội ập đến bạn."
  },
  AvgDialog_18890_Content_18 = {
    Text = "Mọi thứ xung quanh dường như tan chảy nhanh chóng như sáp, thậm chí cả người trước mặt bạn cũng bị méo mó. Phía dưới khuôn mặt, những khung xương trắng bệch quấn vào nhau như dây leo."
  },
  AvgDialog_18890_Content_19 = {
    Text = "Ảo ảnh kỳ quái biến mất không còn dấu vết sau vài lần chớp mắt, chỉ còn tiếng ong ong nhọn hoắt bên tai —— liệu đó có phải là ảo giác do mệt mỏi gây ra? Bạn không biết."
  },
  AvgDialog_18890_Content_2 = {
    Text = "Orci nhanh chóng tiến lên, với sự giúp đỡ của Ramona dùng vải buộc chặt tay chân của hắn. \nNgười đàn ông vẫn không ngừng giãy dụa, giữa ngực lộ ra một vết thương kỳ quái."
  },
  AvgDialog_18890_Content_20 = {
    Text = "Bạn chỉ biết, điều này giống trải nghiệm ở nghĩa trang vài ngày trước."
  },
  AvgDialog_18890_Content_21 = {
    Text = "… Mỗi tháng ông ấy đều tự mình đến thăm tình trạng của bệnh nhân, là một vị ân nhân vĩ đại và cũng là người có tấm lòng nhân từ lớn lao của chúng tôi ở viện tế bần."
  },
  AvgDialog_18890_Content_22 = {
    Text = "Cô Sara quá khen, quá khen rồi, tôi chỉ là một người bình thường muốn làm điều gì đó cho thế nhân mà thôi."
  },
  AvgDialog_18890_Content_23 = {
    Text = "Nói đến chuyện này, hôm qua ngài nói hôm nay sẽ mang theo <Yellow:người bạn> đến thăm…"
  },
  AvgDialog_18890_Content_24 = {
    Text = "Vị điêu khắc gia, <Yellow:điêu khắc gia> đã tìm thấy cảm hứng và quay về xưởng ngay lập tức."
  },
  AvgDialog_18890_Content_25 = {
    Text = "Những người trẻ này là…?"
  },
  AvgDialog_18890_Content_26 = {
    Text = "……{Male=ngài,Female=cô}? Ash {Male=ngài,Female=cô}?"
  },
  AvgDialog_18890_Content_27 = {
    Text = "À, xin lỗi, có lẽ do tối qua không nghỉ ngơi tốt, hơi mất tập trung. Rất hân hạnh được gặp ông, Rogers. \nHọ của tôi là Ash, đây là em trai tôi Orci và người quản gia Mary. Đây là Jenkin…"
  },
  AvgDialog_18890_Content_28 = {Text = "Ơ??"},
  AvgDialog_18890_Content_29 = {
    Text = "Jenkin đứa trẻ này, chạy đi đâu rồi?"
  },
  AvgDialog_18890_Content_3 = {
    Text = "Vết thương sâu hoắm chạy dọc khắp ngực. Những đường khâu méo mó cố gắng giữ cho vết rách không thể lành lại. Từ khe hở, chất lỏng đen nhánh vẫn đang rỉ ra từ từ."
  },
  AvgDialog_18890_Content_4 = {
    Text = "Tiếng bước chân gấp gáp vang lên bên ngoài khu vực y tế, Sara xuất hiện, thở hổn hển và vịn vào cửa."
  },
  AvgDialog_18890_Content_5 = {
    Text = "Thấy bên trong đã ổn định, cô ấy có vẻ thư giãn trong chốc lát, sau đó lập tức nhíu mày quay sang cô gái đang co ro ở góc phòng."
  },
  AvgDialog_18890_Content_6 = {
    Text = "Ai Jī Sī! Không phải đã nói là không được để người tài trợ đến khu y tế sao? \nNếu người tài trợ gặp chuyện gì ở đây, sau này ai còn…"
  },
  AvgDialog_18890_Content_7 = {
    Text = "Đây là sao, làm sao vậy?"
  },
  AvgDialog_18890_Content_8 = {
    Text = "Bạn quay đầu theo tiếng động và phát hiện ra có hai người không biết từ bao giờ đã đứng sau lưng bạn. \nTrong số đó, bạn nhận ra một người: Đó là người phụ nữ mặc áo trắng mà Orci từng va phải."
  },
  AvgDialog_18890_Content_9 = {
    Text = "Thưa ông Rogers, bác sĩ Philips! \nXin lỗi, quý vị có thể nghỉ ngơi và thưởng thức trà điểm tâm ở khu vực chờ, tôi sẽ đến tiếp đón quý vị sau khi xử lý xong việc ở đây…"
  },
  AvgDialog_18891_Content_1 = {
    Text = "Thám tử nhí"
  },
  AvgDialog_18891_Content_10 = {
    Text = "Bạn theo địa điểm trong tờ giấy đến sân sau, còn chưa lại gần thì đã nghe thấy một giọng nói trẻ con nói lẩm bẩm dưới chân tường."
  },
  AvgDialog_18891_Content_11 = {
    Text = "Nhớ kỹ, nếu người tài trợ gây bất lợi cho chúng ta, cậu hãy đi báo tin. \nNgười phụ nữ đáng ghét đó chắc chắn sẽ sai Ai Jī Sī đến giúp <Yellow:kẻ điên rồ> bên kia, cậu dẫn cô ấy tới là được."
  },
  AvgDialog_18891_Content_12 = {
    Text = "Bệnh điên gì?"
  },
  AvgDialog_18891_Content_13 = {
    Text = "Wow! Sao bạn lại xuất hiện đột ngột như vậy! Và, tôi đã bảo bạn tự đến mà!"
  },
  AvgDialog_18891_Content_14 = {
    Text = "Chú chuột nhỏ nhảy phắt lên vai cậu bé mặc áo trùm đầu, râu dựng đứng vì căng thẳng khi nhìn bạn."
  },
  AvgDialog_18891_Content_15 = {
    Text = "Đó không phải là ví của tôi, tôi không quyết định được."
  },
  AvgDialog_18891_Content_16 = {
    Text = "Đừng giả vờ nữa, không có gì có thể qua mắt được con chuột nhỏ—— Chị gái tóc trắng đóng vai người quản gia, chú cún vàng còn phải phụ trách hỏi đường, chỉ có cậu là đứng không làm gì cả."
  },
  AvgDialog_18891_Content_17 = {
    Text = "Đừng nghĩ là tôi không nhìn ra, chính cậu mới là người có quyền quyết định. Dù sao, thứ trong này cũng không phải là giấy chứng nhận con nhà giàu."
  },
  AvgDialog_18891_Content_18 = {
    Text = "Tay Jenkin lắc nhẹ, từ đâu đó lấy ra một ví da. Nó có chất liệu và hình dáng quen thuộc, trên đó in huy hiệu của Đại học Misaque, chính là ví của Orci."
  },
  AvgDialog_18891_Content_19 = {
    Text = "Đúng chứ, Brun?"
  },
  AvgDialog_18891_Content_2 = {
    Text = "Như bạn thấy, dù chúng tôi đã cố gắng hết sức để giúp đỡ những người cần cứu trợ, nhưng số người cần giúp đỡ quá nhiều! Nếu tiếp tục như vậy, viện từ thiện cũng không thể duy trì được lâu... Tôi... ôi trời!"
  },
  AvgDialog_18891_Content_20 = {
    Text = "Chít, chít chít!"
  },
  AvgDialog_18891_Content_21 = {
    Text = "Ah! Ví của tôi!"
  },
  AvgDialog_18891_Content_22 = {
    Text = "Orci vội vàng đưa tay về phía ví da, Jenkin tránh sang một bên, và ví da lại biến mất như thể có phép thuật vậy."
  },
  AvgDialog_18891_Content_23 = {
    Text = "Quá vô lễ, Tiểu Kim Mao. \nNgười của Đại học Misaque đều bắt nạt những cô bé lang thang trên phố như vậy sao?"
  },
  AvgDialog_18891_Content_24 = {
    Text = "Bạn là… cô gái?"
  },
  AvgDialog_18891_Content_25 = {
    Text = "Bạn có vấn đề về mắt phải không?? Tôi đương nhiên là nữ, nữ!"
  },
  AvgDialog_18891_Content_26 = {
    Text = "Thôi, bỏ qua chuyện này đi, tôi khuyên các người hãy ngoan ngoãn nghe theo, chỉ cần theo tôi——"
  },
  AvgDialog_18891_Content_27 = {
    Text = "Được rồi, chúng tôi đồng ý. Để đổi chỗ, bạn dẫn chúng tôi đi gặp những <Yellow:người bị điên bệnh hoạn> mà bạn nói."
  },
  AvgDialog_18891_Content_28 = {Text = "… à?"},
  AvgDialog_18891_Content_29 = {
    Text = "Bạn không nhờ chúng tôi giúp tìm người ở nhà tế bần sao? Nói đi, cần tìm ai?"
  },
  AvgDialog_18891_Content_3 = {
    Text = "Cô Sara làm việc vất vả mỗi ngày, thậm chí bán cả những thứ mình yêu thích nhất, chỉ để hỗ trợ viện từ thiện. Xin hãy giúp chúng tôi…"
  },
  AvgDialog_18891_Content_30 = {
    Text = "Tôi còn chưa nói gì cả!"
  },
  AvgDialog_18891_Content_31 = {
    Text = "Bạn sẽ nói. Vì vậy, tôi đề xuất chúng ta bỏ qua những cuộc dò xét không cần thiết và đối xử trực tiếp, thành thật với nhau."
  },
  AvgDialog_18891_Content_32 = {
    Text = "Bạn hẳn là đến để điều tra vụ <Yellow:mất tích> gần nhà nuôi người nghèo phải không? \n Chúng tôi cũng vậy, giúp bạn cùng điều tra chỉ là việc nhỏ nhặt."
  },
  AvgDialog_18891_Content_33 = {
    Text = "Bạn…bạn làm sao biết được?"
  },
  AvgDialog_18891_Content_34 = {
    Text = "Rất đơn giản. Bạn có một đôi tay khéo léo và một nhóm đối tác cố định hợp tác ăn ý, có thể mang lại thu nhập ổn định, dù không hoàn toàn hợp pháp."
  },
  AvgDialog_18891_Content_35 = {
    Text = "Ramona vừa nói, vừa bước đi quen thuộc trong sân."
  },
  AvgDialog_18891_Content_36 = {
    Text = "Bạn có một kế hoạch hoàn chỉnh: bạn chịu trách nhiệm chính, họ sẽ che chở cho bạn, đảm bảo bạn có thể thoát thân an toàn. Đổi lại, bạn sẽ chia sẻ một ít thành quả."
  },
  AvgDialog_18891_Content_37 = {
    Text = "Bạn có thể sống một cuộc sống thoải mái và tự do hơn trên phố, hoàn toàn không cần phải đến nhà cứu tế để kiếm sống. Hơn nữa, việc bạn vào nhà cứu tế mà không được phép, nếu bị phát hiện, có thể khiến bạn gặp phải rắc rối nghiêm trọng."
  },
  AvgDialog_18891_Content_38 = {
    Text = "Tại sao? Điều gì đã thúc đẩy bạn, khiến bạn sẵn sàng đối mặt với nguy cơ bị phạt tiền thậm chí bị giam giữ, cũng nhất quyết ở lại viện tế bần?"
  },
  AvgDialog_18891_Content_39 = {
    Text = "Điều này, cùng với các vụ mất tích gần đây ở khu vực lân cận, dẫn đến một giả thuyết: \nNgười thân hoặc bạn bè của bạn đã mất tích, và bạn nghi ngờ sự mất tích của họ có liên quan đến trại tế bần."
  },
  AvgDialog_18891_Content_4 = {
    Text = "Nhìn thấy vở kịch của hai người —— chủ yếu là Sara —— càng diễn càng quá đà, bạn cảm thấy khá bất lực."
  },
  AvgDialog_18891_Content_40 = {
    Text = "Cô gái ngây người nhìn Ramona, một lúc sau mới phản ứng lại."
  },
  AvgDialog_18891_Content_41 = {
    Text = "Tôi, chúng ta còn chưa nói đủ mười câu, mà cậu đã làm như theo dõi tôi mười ngày rồi…"
  },
  AvgDialog_18891_Content_42 = {
    Text = "Tính cả lúc bạn mượn ví của Orci, bạn đã nói với chúng tôi tổng cộng mười sáu câu. \nCùng với những quan sát về thực tế, những lời này đã đủ để phân tích và suy luận về cuộc đời của bạn."
  },
  AvgDialog_18891_Content_43 = {
    Text = "……bạn thật sự rất giỏi. Vậy thì, Brun."
  },
  AvgDialog_18891_Content_44 = {Text = "Chít!"},
  AvgDialog_18891_Content_45 = {
    Text = "Chuột nhỏ được gọi là Brown kêu chíp chíp, ngậm ví tiền nhảy xuống từ cây lớn, và ném nó vào lòng của Orci."
  },
  AvgDialog_18891_Content_46 = {
    Text = "Tôi sẽ đưa các người đi gặp những kẻ điên, và cũng sẽ kể cho các người tất cả những điều tôi biết, đổi chỗ——"
  },
  AvgDialog_18891_Content_47 = {
    Text = "Bạn phải giúp tôi đánh bại ma quỷ trong nhà tế bần và cứu chị gái của tôi, <Blue:Mason>."
  },
  AvgDialog_18891_Content_48 = {
    Text = "Các bạn hãy theo chân Jenkin, di chuyển qua các hành lang của nhà nuôi dưỡng người nghèo."
  },
  AvgDialog_18891_Content_49 = {
    Text = "Chị gái mỗi thứ năm đều đến viện tế bần thu quần áo, mang về nhà giặt sạch. Có thể là những bộ quần áo đó cũng không sạch sẽ, chị gái đã mắc phải căn bệnh lạ đang lưu hành gần đây, gọi là \"<Yellow:chứng hysteria>\"."
  },
  AvgDialog_18891_Content_5 = {
    Text = "Đang lúc đó, bạn bị một cục giấy nhỏ ném trúng đầu."
  },
  AvgDialog_18891_Content_50 = {
    Text = "Đúng lúc bệnh viện từ thiện đã mời bác sĩ, cô ấy tiện thể ghé qua kiểm tra. \nGần đây, cô ấy nói sẽ đến để chữa trị, rồi không trở về nữa."
  },
  AvgDialog_18891_Content_51 = {
    Text = "Jenkin có vẻ rất lo lắng."
  },
  AvgDialog_18891_Content_52 = {
    Text = "Không biết tại sao, gần đây tôi dần dần không nhớ rõ chị gái trông như thế nào."
  },
  AvgDialog_18891_Content_53 = {
    Text = "Đôi khi, chỉ cần nhìn thấy một chút đồ vật mà chị để lại, tôi có thể tạm thời nhớ lại, nhưng rất nhanh sau đó lại quên mất."
  },
  AvgDialog_18891_Content_54 = {
    Text = "Ramona đột nhiên dừng lại, gật đầu với bạn."
  },
  AvgDialog_18891_Content_55 = {
    Text = "Sao không đi nữa? Không đi khám người mất trí nữa à?"
  },
  AvgDialog_18891_Content_56 = {
    Text = "Về bệnh của chị gái bạn… chúng tôi có thể đã tìm ra một số manh mối."
  },
  AvgDialog_18891_Content_58 = {
    Text = "Sau khi gửi báo cáo xin tiết lộ thông tin qua thông tin liên lạc, Ramona từ từ quay sang Jenkin và bắt đầu giải thích về sự rỗng."
  },
  AvgDialog_18891_Content_59 = {
    Text = "Jenkin, chị của bạn đã bị ảnh hưởng bởi một hiện tượng đặc biệt gọi là \"rỗng rỗng\". Hiện tượng này khiến sự tồn tại của con người dần bị lãng quên."
  },
  AvgDialog_18891_Content_6 = {
    Text = "Gã nào đến từ đâu ——"
  },
  AvgDialog_18891_Content_60 = {
    Text = "Thịt, danh tính, lý lịch, mối quan hệ xã hội, đều sẽ biến mất không chút dấu vết."
  },
  AvgDialog_18891_Content_61 = {
    Text = "Bạn nói về những trường hợp của những kẻ điên rồ, rất giống như <Yellow:triệu chứng sớm của sự tan biến>. Chị gái của bạn thậm chí đã phát triển đến mức tồn tại bắt đầu bị xóa bỏ hoàn toàn, sợ rằng cô ấy… sẽ không còn tồn tại nữa"
  },
  AvgDialog_18891_Content_62 = {
    Text = "Jenkin, Mason đã... mất tích bao lâu rồi?"
  },
  AvgDialog_18891_Content_63 = {
    Text = "Hai mươi bảy ngày. Kể từ đó, tôi đếm từng ngày."
  },
  AvgDialog_18891_Content_64 = {
    Text = "Thấy vẻ mặt Ramona bối rối, Jenkin hít nhẹ một cái."
  },
  AvgDialog_18891_Content_65 = {
    Text = "Tôi biết, sau một thời gian dài như vậy, các người chắc chắn đã nghĩ không còn hy vọng nữa. \nNhưng tôi tin rằng chị ấy vẫn còn sống…… trực giác của trẻ em sống ngoài đường rất chính xác."
  },
  AvgDialog_18891_Content_66 = {
    Text = "Vì vậy... phải nhanh chóng tìm thấy chị ấy. Nếu không, sẽ quên mất khuôn mặt của cô ấy, khi đối diện cũng không nhận ra."
  },
  AvgDialog_18891_Content_67 = {
    Text = "Đừng buồn, chúng tôi sẽ giúp bạn tìm chị gái. Chỉ cần gặp được cô ấy, chẳng phải bạn sẽ nhớ lại sao?"
  },
  AvgDialog_18891_Content_68 = {
    Text = "Ramona không trả lời. \nDưới ánh mắt u sầu của cô ấy, bạn nhớ lại những gì đóa đã kể trong lớp."
  },
  AvgDialog_18891_Content_69 = {
    Text = "<Yellow:\"Sự tồn tại bị xóa sổ là triệu chứng cuối cùng của sự rỗng tuếch, và quá trình này là không thể đảo ngược.\">"
  },
  AvgDialog_18891_Content_7 = {
    Text = "Bạn đưa tay ngăn cơn giận của Sara, mở tờ giấy vo tròn ra, trên đó có một dòng chữ viết nguệch ngoạc."
  },
  AvgDialog_18891_Content_8 = {
    Text = "\"Muốn lấy lại túi trước, hãy tự đến sân sau.\""
  },
  AvgDialog_18892_Content_1 = {
    Text = "Các người bị đánh thức bởi tiếng kêu chói tai và gấp gáp của loài gặm nhấm, Ramona nhanh chóng ngồi dậy và bật đèn phòng lên."
  },
  AvgDialog_18892_Content_10 = {
    Text = "Lưỡi dao sắc nhọn phản chiếu ánh sáng lạnh, thân dao ngắn gọn phản chiếu khuôn mặt bạn."
  },
  AvgDialog_18892_Content_11 = {Text = "Ai!"},
  AvgDialog_18892_Content_12 = {
    Text = "Phản xạ có điều kiện đã giúp bạn kịp thời nghiêng người tránh qua một bên và nhìn rõ bóng dáng của người đến."
  },
  AvgDialog_18892_Content_13 = {Text = "Jenkin?!"},
  AvgDialog_18892_Content_14 = {
    Text = "Cặp mắt trống rỗng của cô gái không có bất kỳ sắc màu nào, vẻ mặt của cô gần như tê liệt và vô cảm, hoàn toàn không để ý đến lời gọi của bạn."
  },
  AvgDialog_18892_Content_15 = {
    Text = "Tôi muốn trả thù cho chị gái……"
  },
  AvgDialog_18892_Content_16 = {
    Text = "Cô ta di chuyển một cách nhanh nhẹn, lưỡi dao vẽ nên những đường cong băng giá trong không khí. \nKhông cho bạn thêm thời gian để suy nghĩ, cô gái lại lao về phía bạn."
  },
  AvgDialog_18892_Content_17 = {
    Text = "Dường như chỉ còn cách bắt cô ta lại để thẩm vấn. \nRamona, Orci, dẫn cô ta đến một không gian trống trải."
  },
  AvgDialog_18892_Content_18 = {Text = "Ở!"},
  AvgDialog_18892_Content_19 = {
    Text = "Tuân lệnh của bạn!"
  },
  AvgDialog_18892_Content_2 = {
    Text = "Brun? Sao bạn lại đến một mình."
  },
  AvgDialog_18892_Content_3 = {
    Text = "Rít——!rít rít!"
  },
  AvgDialog_18892_Content_4 = {
    Text = "Chúng tôi không phải là Jenkin, không hiểu ý bạn."
  },
  AvgDialog_18892_Content_5 = {
    Text = "Thời gian cũng sắp đến rồi, Jenkin nên đến để gặp chúng ta rồi."
  },
  AvgDialog_18892_Content_6 = {
    Text = "Bạn nhìn ra cửa sổ, trong làn sương trắng nhạt, bóng dáng của những tòa nhà giống như những bức tượng đứng sừng sững trong nghĩa trang."
  },
  AvgDialog_18892_Content_7 = {
    Text = "Cánh cửa kẽo kẹt mở ra một khe nhỏ, gió lạnh buốt của đêm khuya lùa vào qua khe hở tối tăm."
  },
  AvgDialog_18892_Content_8 = {
    Text = "Một bóng đen nhanh chóng lao ra từ phía sau bàn ghế, liền xuất hiện ngay trước mặt bạn."
  },
  AvgDialog_18893_Content_1 = {
    Text = "Mùa xuân của Botticelli"
  },
  AvgDialog_18893_Content_10 = {
    Text = "Chuột tấn công chồn tuyết."
  },
  AvgDialog_18893_Content_11 = {
    Text = "Bạn nói ai là chuột đấy!"
  },
  AvgDialog_18893_Content_12 = {
    Text = "Bạn nói ai là chồn tuyết cơ chứ!"
  },
  AvgDialog_18893_Content_13 = {
    Text = "Hannah? Jenkin? Các người đang.."
  },
  AvgDialog_18893_Content_14 = {
