  AvgDialog_18893_Content_16 = {
    Text = "Vậy người mà cô ấy tìm chính là các bạn rồi nhỉ? Các bạn gặp nhau ở đâu, tại Trại từ thiện Lily? À! Cô ấy chính là cô bé Jenkin phải không?"
