  AvgDialog_18893_Content_20 = {
    Text = "Liệu người mà cô ấy đang khao khát tìm kiếm có thể mang đến cho cô chút ánh sáng? \n Phóng viên chiến trường Hannah Peasly sắp tiến hành báo cáo theo dõi!"
  },
  AvgDialog_18893_Content_21 = {
    Text = "Hannah vừa nói, vừa đột nhiên lấy ra một cuốn sổ tay từ đâu đó, nhìn các bạn với ánh mắt đầy mong đợi, như thể sẵn sàng ghi lại từng lời và cử chỉ của các bạn."
  },
  AvgDialog_18893_Content_22 = {
    Text = "……Tôi đã hiểu, các người ở cái trường đại học điên rồ này, từng người một đều không nói tiếng người."
