  AvgDialog_18893_Content_3 = {
    Text = "Bạn và Ramona vừa trở lại cổng trường thì thấy Jenkin và một học sinh mặc đồng phục đang ẩu đả."
  },
  AvgDialog_18893_Content_30 = {
    Text = "Đây là một nhóm bình tượng nến được tạo ra theo bức tranh nổi tiếng \"Mùa xuân\" của Botticelli, giữa là một nữ bình tượng nến được sơn bằng màu sắc kỳ quặc, với biểu cảm đau khổ."
  },
  AvgDialog_18893_Content_31 = {
    Text = "Người này… không biết tại sao, tôi thấy cô ấy rất giống chị gái tôi."
  },
  AvgDialog_18893_Content_32 = {
    Text = "Rogers… bác sĩ Miller, chính ông ta đã giới thiệu cho Sara. Sau khi vụ việc ở trại tế bần xảy ra, ông ta đã biến mất một cách bí ẩn."
