  AvgDialog_18893_Content_35 = {
    Text = "Xem xét đối phương có thể rất nguy hiểm, tôi thực sự mong rằng bạn sẽ đồng ý chờ tin tức của chúng tôi ở đây. Tuy nhiên —— chắc hẳn bạn có suy nghĩ khác rồi phải không?"
