  AvgDialog_18893_Content_38 = {
    Text = "Có vẻ như cần phải nộp ngay đơn xin đi công tác khẩn cấp rồi."
  },
  AvgDialog_18893_Content_39 = {
    Text = "Tôi đang chuẩn bị đi tìm giáo sư Alistair, hy vọng ông ấy sẵn lòng tạo cơ hội đặc biệt cho chúng tôi."
