  AvgDialog_18893_Content_4 = {
    Text = "……………"
  },
  AvgDialog_18893_Content_40 = {
    Text = "Chỉ cần bạn nói một tiếng, chắc chắn không có vấn đề gì. Điều quan trọng hơn là —— chúng ta cần William tạm hoãn thời gian nộp báo cáo của chúng ta."
