  AvgDialog_18893_Content_42 = {Text = "?"},
  AvgDialog_18893_Content_43 = {
    Text = "Cách đây khoảng một giờ, William đã cầm giấy phép thực địa và rời khỏi trường."
  },
  AvgDialog_18893_Content_44 = {
    Text = "Tôi vốn muốn theo dõi anh ta, xem có thể đào được tin tức gì không, nhưng lại bị mất dấu trên đường, mới vừa trở về. Xem hướng, dường như là đi về phía tây của Lentiennam."
