  AvgDialog_18893_Content_53 = {
    Text = "Được, hãy tăng cường cảnh giác. Khi cần thiết, xin hãy đặt sức sống của bản thân lên hàng đầu."
  },
  AvgDialog_18893_Content_54 = {
    Text = "Báo cáo. Đã đến địa điểm nhiệm vụ, số 44 Namwark Street, Bảo tàng Tượng sáp Rogers. Mục tiêu xác nhận: Xác nhận mối liên hệ có thể giữa chủ bảo tàng tượng sáp Rogers và Hiệp hội Điêu khắc gia."
