  AvgDialog_18895_Content_10 = {
    Text = "Bạn đã nghe đoạn ca này trong giấc mơ của mình."
  },
  AvgDialog_18895_Content_11 = {
    Text = "Thân thể dần dần cứng đờ, xương cốt cố gắng di chuyển phát ra tiếng kêu lạo xạo, mỗi cử động đều giống như cố gắng vặn bánh răng của một con rối cơ khí bị rỉ sét, bạn có thể cảm nhận được bột vụn nhỏ rơi xuống từ các khớp xương của mình."
  },
  AvgDialog_18895_Content_12 = {
    Text = "<Italic:Một ngày nọ cô ấy biến mất, anh ấy tìm kiếm khắp mọi nơi với sự lo lắng.>"
  },
  AvgDialog_18895_Content_13 = {
    Text = "Mi mắt nặng như chứa chì, không thể chịu nổi và nhắm lại. \nkhi chìm vào thế giới tối tăm, chỉ có sương mù đặc quánh bao quanh."
  },
  AvgDialog_18895_Content_14 = {
