  AvgDialog_18895_Content_19 = {
    Text = "Theo bản năng không rõ từ đâu mà có, bạn ngẩng đầu lên, hướng về đôi mắt ở trên cao dường như đang muốn nói điều gì đó, thầm thì hỏi."
  },
  AvgDialog_18895_Content_2 = {
    Text = "Theo lời của Jenkin, <Yellow:ma nhà tế bần> sẽ lang thang trong sân vào những đêm sương mù, bắt cóc các nạn nhân. Có thể điều tra viên Anderson cũng nằm trong số đó."
