  AvgDialog_18896_Content_1 = {
    Text = "Trong mờ ảo, giọng nói huyền bí vang lên bên tai cô gái ."
  },
  AvgDialog_18896_Content_2 = {
    Text = "Hãy từ bỏ đi, nhắm mắt lại, mọi thứ hãy giao cho tôi. \nSara, Michael nhỏ... Tất cả mọi người trong trại tế bần sẽ trở thành cái đẹp, trở thành vĩnh cửu."
  },
  AvgDialog_18896_Content_3 = {
    Text = "Không được, không được, lần này, tôi tuyệt đối tuyệt đối… sẽ không để ngươi kiểm soát tôi nữa…"
  },
  AvgDialog_18896_Content_4 = {
    Text = "Kháng cự? Không có sự giúp đỡ của kẻ phiền phức đó, tinh thần của ngươi sẽ không trụ được bao lâu. Nếu không như vậy, ta cũng chẳng thể tác động đến ngươi khi ngươi còn tỉnh táo."
  },
  AvgDialog_18896_Content_5 = {
    Text = "Thôi, hãy từ bỏ đi. Sau đó, bạn có thể giúp tôi biến tất cả mọi người ở đây thành nguồn tài nguyên quý báu."
  },
  AvgDialog_18896_Content_6 = {
    Text = "Tôi sẽ không bỏ cuộc! Ông Anderson cũng không phải là người gây phiền phức!"
  },
  AvgDialog_18896_Content_7 = {
    Text = "Anh ấy đã bảo vệ tôi… Tôi cũng muốn bảo vệ mọi người, đặc biệt là chị Sara, cậu Mike nhỏ và Jenkin. Cũng bảo vệ anh chị lớn từ bên ngoài."
  },
  AvgDialog_18896_Content_8 = {
    Text = "Tôi sẽ bảo vệ họ, dù phải trả giá bằng mọi thứ——"
  },
  AvgDialog_18897_Content_1 = {
    Text = "Thế nào, bạn đã nhận ra chưa? Dù bạn có cố gắng vùng vẫy đến mấy, dù bạn sẵn sàng hy sinh tất cả, những thay đổi đang diễn ra với bạn cũng sẽ không dừng lại."
  },
  AvgDialog_18897_Content_10 = {
    Text = "Tôi tin vào họ, nhất định có thể tiêu diệt…"
  },
  AvgDialog_18897_Content_11 = {
    Text = "<Red:tôi>."
  },
  AvgDialog_18897_Content_12 = {
    Text = "Tôi đều đã nghe, các người rất rất khó để tìm được một đứa trẻ phù hợp để làm thí nghiệm."
  },
  AvgDialog_18897_Content_13 = {
    Text = "Việc xấu của bạn đã bị phơi bày. Tiếp theo, chỉ cần tôi không còn ở đây, họ chắc chắn sẽ an toàn, phải không?"
