  },
  AvgDialog_18897_Content_6 = {
    Text = "%player%{Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}, chị Ramona thân thiết, Orci…\nHọ khác với những người ở nhà nuôi dưỡng, họ rất mạnh mẽ, chắc chắn có thể tiêu diệt…"
