  AvgDialog_18898_Content_19 = {
    Text = "Sara nằm im lặng trên một chiếc giường nhỏ. Đầu cô vẫn giữ nguyên tư thế nứt vỡ, bốn chi bị khóa chặt bởi xiềng xích."
