  AvgDialog_18899_Content_42 = {
    Text = "Mặc dù bạn có khả năng liên kết cùng lúc với nhiều thân thể được đánh thức, nhưng để tránh gánh nặng thân thể do việc liên kết gây ra, lần này Orci – người đã hoàn thành liên kết sẽ đi cùng."
  },
  AvgDialog_18899_Content_43 = {
