  AvgDialog_18901_Content_16 = {
    Text = "Sau khi cô ấy nhắc nhở, các người mới nhận ra, đúng rồi, dường như có một cảm giác ngứa ngáy khó chịu trên da, từ đầu ngón chân đến mắt cá chân, lan dần lên lưng…"
  },
  AvgDialog_18901_Content_17 = {
    Text = "Jenkin cuối cùng cũng thắp sáng đèn cầm tay, cô nhẹ nhàng hạ thấp đèn, chiếu sáng một khoảng đất nhỏ."
