  AvgDialog_18901_Content_2 = {
    Text = "Sau một đêm rối ren, trời đã gần sáng."
  },
  AvgDialog_18901_Content_20 = {
    Text = "Số lượng kiến không thể đếm được tụ tập thành một đàn kiến dày đặc, bò liên tục với sự bồn chồn và bất an."
  },
  AvgDialog_18901_Content_21 = {
    Text = "Chúng dâng lên, tụ tập, xoay tròn, rồi đổ vào vực thẳm tối tăm."
  },
  AvgDialog_18901_Content_3 = {
    Text = "Orci ở lại trong phòng để đề phòng, giữ chân Sara. \nBạn và Ramona thì theo Jenkin đến trước cửa hầm nơi \"Ma nhà tế bần\" ẩn náu."
  },
  AvgDialog_18901_Content_4 = {
    Text = "Hãy nhỏ giọng, đừng để Sara biết. \nCô ấy sẽ dẫn theo một đội công nhân đuổi chúng ta ra ngoài."
  },
  AvgDialog_18901_Content_5 = {
    Text = "Orci đang giám sát hành động của Sara, có anh ta ở đây, chúng ta sẽ không bị phát hiện. \nBạn kể lại điều đã phát hiện ở văn phòng Sara lần trước đi."
  },
  AvgDialog_18901_Content_6 = {
    Text = "Ôi trời, các người còn muốn tôi nói bao nhiêu lần nữa."
  },
  AvgDialog_18901_Content_7 = {
    Text = "Người phụ nữ đáng ghét đó đã bán những người ở viện tế bần cho một bác sĩ tồi tệ để làm thí nghiệm, tự mình kiếm được một khoản tiền lớn! Bà ta mua rất nhiều trang sức vàng bạc và giấu trong ngăn kéo phòng ngủ."
  },
  AvgDialog_18901_Content_8 = {
    Text = "Bạn cũng đã xem thẻ sinh viên của các bạn đồng hành rồi, còn gì phải hỏi nữa chứ?"
  },
  AvgDialog_18901_Content_9 = {
