  },
  AvgDialog_18902_Content_1 = {
    Text = "Nghệ thuật ngọt ngào"
  },
  AvgDialog_18902_Content_10 = {
    Text = "Sự xuất hiện của các bạn dường như không hề ảnh hưởng đến công việc của cô ấy. Cô cúi đầu chăm chú ngắm tượng, đổi vị trí con dao khắc, rồi tiếp tục mài giũa."
  },
  AvgDialog_18902_Content_11 = {
    Text = "Đó là hồn ma của nhà tế bần…\nChị gái tôi đâu! Cậu giấu cô ấy rồi phải không?"
  },
  AvgDialog_18902_Content_12 = {
    Text = "Bóng ma liếc qua mọi người, nhưng chẳng đáp lại."
