  AvgDialog_18902_Content_13 = {
    Text = "Ramona rút vũ khí, nhìn bạn một cái, và tiến lên phía trước."
  },
  AvgDialog_18902_Content_14 = {
    Text = "Hãy kiên nhẫn một chút, đừng làm phiền quá trình sáng tạo nghệ thuật…"
  },
  AvgDialog_18902_Content_15 = {
    Text = "Khi lời nói của cô ấy vừa dứt, vô số quái vật gào thét từ bóng tối tầng hầm lao ra, chúng xông thẳng qua những cơ thể đang ngọ nguậy một cách hung hãn, rồi ào tới tấn công mọi người."
  },
  AvgDialog_18902_Content_2 = {
    Text = "Các bạn cuối cùng cũng đã mở được cánh cửa sắt của hầm, một luồng hương thơm ngọt lịm và đậm đặc xông thẳng vào mũi."
  },
  AvgDialog_18902_Content_3 = {
    Text = "Cảnh tượng thảm khốc trong tầng hầm còn gây sốc hơn: trên mặt đất nằm la liệt vài thi thể bị phủ kín bởi một lớp siro."
  },
  AvgDialog_18902_Content_4 = {
    Text = "Thân thể đã mất hình dáng con người vặn vẹo, ngọ nguậy một cách khó khăn, để lại những vết loang lổ hỗn loạn phía sau."
  },
  AvgDialog_18902_Content_5 = {
    Text = "Bầy kiến dày đặc bò quanh xi-rô, tham lam uống, dùng râu chạm vào nhau để vận chuyển, như thể chúng đã phát hiện ra kho báu quý giá nhất trên thế gian."
  },
  AvgDialog_18902_Content_6 = {
    Text = "Tuy nhiên, điều thu hút sự chú ý nhất lại không phải là những điều này."
  },
  AvgDialog_18902_Content_7 = {
    Text = "Trong tầng hầm, có vài bức tượng màu nâu đỏ sáng bóng, mỗi bức đều có dáng vẻ đoan trang, ánh mắt mệt mỏi, chỉ cần liếc qua một cái, đã không khỏi bị sự thiêng liêng đó chấn động."
  },
  AvgDialog_18902_Content_8 = {
    Text = "Trong số những tượng đó, có bóng ma của viện tế bần đang ngồi thiền."
  },
  AvgDialog_18902_Content_9 = {
    Text = "Đó rõ ràng là bóng ma của nhà tế bần —— cô ấy toàn thân màu đá, nhẹ nhàng cầm một con dao khắc trong tay, từng nhát dao khắc lên biểu cảm kinh hoàng của bức tượng, phát ra âm thanh gọt cào xước làm người ta rợn tóc gáy."
  },
  AvgDialog_18903_Content_1 = {
    Text = "Mối nguy hiểm tiềm ẩn"
