  AvgDialog_18903_Content_2 = {
    Text = "Rầm rầm"
  },
  AvgDialog_18903_Content_3 = {
    Text = "Bạn rõ ràng rằng mình đang ở trong giấc mơ."
  },
  AvgDialog_18903_Content_4 = {
    Text = "Có người đang tiếp cận bằng cách dẫm lên các ống sắt trong cống."
  },
  AvgDialog_18903_Content_5 = {
    Text = "Trong mờ mịt, có một bóng dáng quen thuộc chạy tới. \nCô ấy nắm lấy tay bạn, lôi bạn chạy một cách nhanh chóng, và liên tục gọi tên bạn trong lo lắng."
