  AvgDialog_18903_Content_7 = {
    Text = "Sau lưng các bạn, vô số quái vật màu đen nhầy nhụa đang đuổi theo bạn và chị."
  },
  AvgDialog_18904_Content_1 = {Text = "%player%!"},
  AvgDialog_18904_Content_10 = {
    Text = "Cô Sara, tôi rất sợ, xin hãy giúp tôi……"
