  AvgDialog_18904_Content_11 = {
    Text = "Cô Sara…"
  },
  AvgDialog_18904_Content_12 = {
    Text = "Sao vậy, Ai Jī Sī?"
  },
  AvgDialog_18904_Content_13 = {
    Text = "Cô Sara, cô có thể hát lại bài hát đó một lần nữa không, chỉ một lần thôi?\nÝ tôi là, nếu như vậy không gây phiền phức cho cô…"
  },
  AvgDialog_18904_Content_14 = {
    Text = "Kính yêu Ai Jī Sī, bạn hãy lắng nghe, bạn là đứa trẻ ngoan nhất và hiểu chuyện nhất trong toàn viện tế bần. Bạn là người bạn nhỏ được mọi người yêu quý nhất."
