  AvgDialog_18904_Content_17 = {
    Text = "Không vấn đề. \n<Italic:Ông Charlie có một con mèo vằn mà ông rất yêu quý…>"
  },
  AvgDialog_18904_Content_18 = {
    Text = "Bạn đột ngột mở mắt, bước vào thế giới thực đầy màu sắc."
  },
  AvgDialog_18904_Content_19 = {
    Text = "%player%,bạn có sao không?"
  },
  AvgDialog_18904_Content_2 = {
    Text = "Trong khi Ramona kìm hãm Sara ở xa, bạn nhanh chóng tập trung tinh thần, chìm vào không gian hoàn toàn đen tối dần trở nên quen thuộc."
  },
  AvgDialog_18904_Content_20 = {
    Text = "Bạn cố gắng gật đầu trong cơn chóng mặt. Đúng lúc đó, ánh mắt bạn liếc thấy một hình bóng trắng. \nCô gái không biết từ bao giờ đã vượt qua bên cạnh mọi người, tiến vào chiến trường hỗn loạn."
  },
  AvgDialog_18904_Content_21 = {
    Text = "Ai Jī Sī nhanh quay lại! Nơi đó rất nguy hiểm!"
  },
  AvgDialog_18904_Content_22 = {
    Text = "Ai Jī Sī ngẩn người nhìn Sara nằm bất động trên mặt đất. \n Bên cạnh vết thương nổ, chất nhầy vẫn tuôn ra không ngừng, tụ thành dòng suối đen ngòm."
  },
  AvgDialog_18904_Content_23 = {
    Text = "Sau đó, cô ấy bước vào cái ao tối đen, ngồi xuống giữa chất nhầy. \nCô gái để Sara nằm lên đùi mình, rồi nhẹ nhàng vỗ về lưng Sara với sự dịu dàng thành thục."
  },
  AvgDialog_18904_Content_24 = {
    Text = "Giống như cách hiệu trưởng đã từng ru mình đi ngủ."
  },
  AvgDialog_18904_Content_25 = {
    Text = "Cô Sara… Không sao, không sao… Chỉ là một cơn ác mộng…"
  },
  AvgDialog_18904_Content_26 = {
    Text = "Ánh sáng yếu ớt trong mắt xuyên qua tấm bịt mắt, biến mất trong chớp mắt. Nếu không có một đợt linh tri thức mạnh mẽ kèm theo, bạn hầu như đã nghĩ rằng đó chỉ là nỗi buồn chưa tan của cô gái."
  },
  AvgDialog_18904_Content_27 = {
    Text = "Các mảnh nứt trên đầu và mặt Sara ban đầu rung động không yên, sau khi một tia sáng lướt qua, cô ấy ngừng di chuyển, giống như đã thực sự chìm vào giấc ngủ sâu."
  },
  AvgDialog_18904_Content_28 = {
    Text = "Cô Sara đã lâu lắm rồi không ngủ được một giấc ngon."
  },
  AvgDialog_18904_Content_29 = {
    Text = "Để tránh việc trại tế bần bị giải thể, cô ấy liên tục di chuyển khắp nơi để gặp những quý ông và quý bà giàu có sống trong lâu đài, không có thời gian để ăn uống hay nghỉ ngơi."
  },
  AvgDialog_18904_Content_3 = {
    Text = "Chìa khóa bạc rung động và phát ra tiếng vo ve dữ dội, bóng tối trước mắt bạn cũng thay đổi mấy lần, dần dần từ mép tầm nhìn sáng lên."
  },
  AvgDialog_18904_Content_30 = {
    Text = "Tối về, cô ấy thắp một cây nến trong văn phòng, cứ tính toán mãi, xem số tiền xin được từ ông chủ có đủ dùng không."
  },
  AvgDialog_18904_Content_31 = {
    Text = "Xem trang sức cầu được từ các bà tiểu thư có thể đổi được bao nhiêu tiền."
  },
  AvgDialog_18904_Content_32 = {
    Text = "Họ đều cười cô ấy, nói những lời rất tổn thương, Sara không bao giờ giận. \nCòn an ủi tôi, hát cho chúng tôi nghe."
  },
  AvgDialog_18904_Content_33 = {
    Text = "Cô ấy rất tốt với chúng tôi, thật sự. Với tôi cũng vậy, tốt vô cùng."
  },
  AvgDialog_18904_Content_34 = {
    Text = "Tôi từng là gánh nặng của mẹ, và rồi bị mẹ bỏ rơi. Ông hiệu trưởng trước không chịu nhận tôi vào, nhưng cô Sara đã sẵn sàng làm hai công việc để đưa tôi về đây."
  },
  AvgDialog_18904_Content_35 = {
    Text = "Từ đó tôi thề rằng, tôi nhất định không được làm gánh nặng cho cô Sara, nhất định phải trở thành một đứa trẻ có ích."
  },
  AvgDialog_18904_Content_36 = {
    Text = "Xin lỗi, Sara. Tôi đã cố gắng rất nhiều, nhưng mọi việc vẫn… luôn đi theo hướng xấu. Tôi không thể bảo vệ mọi người, không thể bảo vệ bạn. Xin lỗi."
