  AvgDialog_18911_Content_7 = {
    Text = "Ánh sáng mạnh mẽ khiến người ta không tự chủ được muốn nhắm mắt lại, Ai Ji Si cố gắng kiểm soát mí mắt, nhưng cô nhận ra mình không thể kiểm soát được."
  },
  AvgDialog_18911_Content_8 = {
    Text = "Kim loại lạnh buốt ghim chặt cơ mắt, cô chỉ có thể bất lực nhìn người đàn ông áo trắng cầm dao mổ từ từ tiến lại."
  },
  AvgDialog_18911_Content_9 = {
    Text = "Không, đừng mà, cô Sara, cô Sara!"
  },
  AvgDialog_18912_Content_1 = {
    Text = "Chìa khóa bạc lấp lánh dữ dội, cô gái đột ngột chống đỡ thân thể, mơ hồ nghe thấy tiếng vật gì đó bị xé rách."
  },
  AvgDialog_18912_Content_10 = {
    Text = "Bạn cũng ngã ngồi xuống đất, cố chịu đựng cơn đau đầu từng đợt và cảm giác buồn nôn dồn dập kéo tới."
  },
  AvgDialog_18912_Content_11 = {Text = "%player%!"},
  AvgDialog_18912_Content_12 = {
    Text = "Có phải sức mạnh tinh thần đã cạn kiệt? Nếu luôn hành động bừa bãi, bạn sẽ không thể chứng kiến tương lai của Misaque. \nHãy ngồi xuống nghỉ ngơi, sức mạnh tinh thần cạn kiệt sẽ ảnh hưởng đến khả năng cảm nhận của bạn."
  },
  AvgDialog_18912_Content_13 = {
    Text = "Đừng lo lắng về tôi, mau đi xem Ai Ji Si."
  },
  AvgDialog_18912_Content_14 = {
    Text = "Âm thanh giống như chất lỏng bốc hơi dần dần nhỏ lại, chẳng bao lâu đã tan biến hẳn. \n Trên sàn nhà dính chất lỏng màu đen, cô gái che một bên mắt, ngồi im lặng."
  },
  AvgDialog_18912_Content_15 = {
    Text = "Cô Ramona…… và…… %player%, {Male=ngài,Female=cô}. \nThật tốt vì mọi người đều bình an."
  },
  AvgDialog_18912_Content_16 = {
    Text = "Ai Jī Sī……"
  },
  AvgDialog_18912_Content_17 = {
