  AvgDialog_18912_Content_30 = {
    Text = "Dường như được khích lệ bởi một ngày nắng hiếm hoi, cô ấy chống dậy thân thể, lảo đảo bước tới một tấm kính sạch sẽ hơn."
  },
  AvgDialog_18912_Content_31 = {
    Text = "Vista mờ ảo cuối cùng trở nên rõ ràng, cô ấy nhìn những con đường quen thuộc hoặc xa lạ, trong lúc mơ màng, tai dường như vang lên tiếng thì thầm của ai đó."
  },
  AvgDialog_18912_Content_32 = {
    Text = "Nhìn này, tiếng nói ấy nói rằng, tối nay chắc chắn sẽ thấy bầu trời đầy sao lấp lánh."
  },
  AvgDialog_18912_Content_33 = {
    Text = "Trước đây, mỗi khi có thể nhìn thấy mặt trời, Tiyug sẽ lén đưa tôi lên đây trong bóng tối."
  },
  AvgDialog_18912_Content_34 = {
    Text = "Cô Sara không bao giờ cho phép chúng tôi đến đây, cô ấy nói rằng nơi này quá nguy hiểm, chúng tôi rất dễ bị thương."
  },
  AvgDialog_18912_Content_35 = {
    Text = "Nhưng Dityug không quan tâm đến những điều đó. Mỗi ngày sau khi tắt đèn, chờ cô Sara đi tuần xong, anh ta sẽ lén đưa tôi lên đây trong bóng tối."
  },
  AvgDialog_18912_Content_36 = {
    Text = "Anh ta giống như Jenkin, thông minh và dũng cảm, luôn biết những con đường nhỏ và bẫy mà người khác không biết."
  },
  AvgDialog_18912_Content_37 = {
    Text = "Chừng nào có anh ấy dẫn đường, chúng ta sẽ không bị cô Sara phát hiện."
  },
  AvgDialog_18912_Content_38 = {
    Text = "Chừng nào còn có anh ấy dẫn đường, nơi đây sẽ mãi là nơi trú ẩn bí mật của chúng ta."
  },
  AvgDialog_18912_Content_39 = {
    Text = "Anh ấy bảo tôi phải tiếp xúc nhiều hơn với những ngôi sao, năng lượng phép thuật mới có thể mạnh mẽ. Mặc dù chúng ta không thể nhìn thấy một ngôi sao nào ở đây."
  },
  AvgDialog_18912_Content_4 = {
    Text = "Không, không đúng! Cảm giác đây là…! Là ông @2!"
  },
  AvgDialog_18912_Content_40 = {
    Text = "Đó là lúc anh ấy là người duy nhất tin tôi. Tin rằng tôi có thể nhìn thấy những thứ đen tối, và bảo tôi rằng đó là năng lực bẩm sinh của phù thủy."
  },
  AvgDialog_18912_Content_41 = {
    Text = "Nhưng anh ấy đã bị tiến sĩ mang đi vì muốn bảo vệ tôi……"
  },
  AvgDialog_18912_Content_42 = {
    Text = "Nếu tôi thông minh như anh ta, can đảm như Zhenkin, có lẽ tôi đã sớm tìm ra sự thật rồi. \nNhưng tôi không phải là một phù thủy, tôi chỉ là một kẻ nhát gan, một con quái vật."
