  AvgDialog_18912_Content_43 = {
    Text = "Một……người đã gây ra cái chết."
  },
  AvgDialog_18912_Content_44 = {
    Text = "Ai Jī Sī, bạn là một đứa trẻ ngoan, bạn đã bị khống chế, những điều đó không phải là lỗi của bạn."
  },
  AvgDialog_18912_Content_45 = {
