  AvgDialog_18912_Content_9 = {
    Text = "Sau tiếng hú chói tai và đau đớn, thân thể khổng lồ của quái vật tan rã thành chất lỏng đen và sụp đổ. Chất lỏng biến thành bột phấn, bay lên cao rồi làm đen các dầm gỗ."
  },
  AvgDialog_18913_Content_1 = {
    Text = "Các bạn cuối cùng cũng đuổi kịp cô gái. Ai Jī Sī bị mọi người cùng nhau khống chế, bạn vội vàng đưa tay ra, nắm lấy cánh tay của cô ấy, một tay ấn vào chìa khóa bạc, chuẩn bị hoàn thành liên kết."
  },
  AvgDialog_18913_Content_10 = {
    Text = "Không, không, Ai Jī Sī, hãy tin tưởng chúng tôi. Đại học Misaque đã từng đối mặt với những tình huống nguy hiểm hơn nhiều…"
  },
  AvgDialog_18913_Content_11 = {
    Text = "Thật sao? Orci… Hãy nhìn thân thể của họ."
  },
  AvgDialog_18913_Content_12 = {
    Text = "Orci quay đầu nhìn về phía Người Giữ Gìn và Ramona vẫn đang kiên trì. \nLàn da của họ đang tiết ra mồ hôi có màu sắc lạ lùng —— đó không phải là mồ hôi, mà là những giọt siro mịn."
  },
  AvgDialog_18913_Content_13 = {
    Text = "Sau khi giọng của ông Anderson biến mất, màu sắc trong mắt tôi, thân thể tôi dần mất kiểm soát. Ngay cả khi tôi không nhìn bằng mắt, những người xung quanh cũng sẽ dần dần biến thành đá bất động."
  },
  AvgDialog_18913_Content_14 = {
    Text = "Tôi còn có thể kiên trì bao lâu? Một năm, một tháng, một ngày và một giờ?"
  },
  AvgDialog_18913_Content_15 = {
    Text = "Phải chăng tôi cứ mãi trốn sau lưng mọi người, đợi đến khi không còn gì cứu vãn được nữa mới hành động?"
  },
  AvgDialog_18913_Content_16 = {
    Text = "Lần này, tôi muốn can đảm như Tiyug, như Jenkin, như bạn."
  },
  AvgDialog_18913_Content_17 = {
    Text = "Orci, bạn không phải là hiệp sĩ sao? Vậy bạn nên hiểu chứ. \nDù tôi có ở lại, cũng đã định sẵn là kẻ bị hiệp sĩ xét xử."
