  AvgDialog_18913_Content_20 = {
    Text = "Bây giờ… anh có thể nhìn vào tôi không, nhìn vào linh hồn của tôi… liệu nó có còn cơ hội được cứu rỗi không?"
  },
  AvgDialog_18913_Content_21 = {
    Text = "Orci nhìn vào còng kinh duy nhất bình thường của Ai Jī Sī, sau một thoáng do dự, buông tay một cách thận trọng."
  },
  AvgDialog_18913_Content_22 = {
    Text = "Với động tác của anh ta, Ai Jī Sī đã thoát khỏi liên kết kiểm soát của bạn."
  },
  AvgDialog_18913_Content_23 = {
    Text = "Chớp mắt, thân thể cô gái nhanh chóng phình to, da thịt như sôi sùng sục nổi lên những cục u tròn to nhỏ khác nhau, nhanh chóng chặn kín lối đi cầu thang hiện tại và chèn vào trần nhà cao vút."
  },
  AvgDialog_18913_Content_24 = {
