  AvgDialog_18935_Content_21 = {
    Text = "Bạn có vẻ không thích nói chuyện. Yên tâm đi, tôi tạm thời không định biến bạn thành bình tượng nến… Bạn cứ tự nhiên nói đi, đừng ngại."
  },
  AvgDialog_18935_Content_22 = {
