  AvgDialog_18935_Content_27 = {
    Text = "Đó là một trải nghiệm đau đớn. Mẹ tôi nghiện các loại liệu pháp \"mới\", và đối xử với tôi như một món đồ chơi, tùy ý can thiệp."
