  AvgDialog_18935_Content_30 = {
    Text = "Vì vậy, tôi hát vang bài hát chữ cái vui nhộn, máu không ngừng trào ra từ miệng, chảy dài xuống ngực."
  },
  AvgDialog_18935_Content_31 = {
    Text = "Đừng khóc nữa, con của mẹ. Mỗi tượng sáp ở đây đều có một câu chuyện buồn phía sau."
