  },
  AvgDialog_18959_Content_81 = {
    Text = "Bạn vội vàng đứng dậy quay một vòng, hóa ra thật sự thấy một chú chuột béo mập đáng yêu trong bụi cỏ phía sau bia mộ."
  },
  AvgDialog_18959_Content_82 = {
    Text = "Khò... khò.."
  },
  AvgDialog_18959_Content_83 = {
    Text = "Thể hình này, và cả màu sắc nữa… đúng là brun rồi!!"
  },
  AvgDialog_18959_Content_84 = {
    Text = "Bạn và 24 cùng thốt lên."
  },
  AvgDialog_18959_Content_85 = {
    Text = "Chú chuột nhỏ này đã biến mất kể từ sự kiện tại bảo tàng sáp và chưa bị các người làm gián đoạn giấc ngủ."
  },
  AvgDialog_18959_Content_86 = {
    Text = "Nó dường như vừa trải qua một cuộc phiêu lưu kinh hoàng, lúc này đang kiệt sức nằm ngủ ở điểm cuối của hành trình."
  },
  AvgDialog_18959_Content_87 = {
    Text = "Huhu……xèo……lululu……"
  },
  AvgDialog_18959_Content_88 = {
    Text = "Nó dường như đang ôm một thứ gì đó…"
  },
  AvgDialog_18959_Content_9 = {
    Text = "<Big:《Xuân Baltic》!>"
  },
  AvgDialog_18959_Content_90 = {
    Text = "Là bạc tâm. Bạc tâm thuộc về Jenkin."
  },
  AvgDialog_18959_Content_91 = {
    Text = "Đôi móng vuốt nhỏ bé ôm chặt lấy một bạc tâm. Nó vẫn chưa được mài dũa, toàn thân toả ra ánh sáng mờ ảo."
  },
  AvgDialog_18959_Content_92 = {
    Text = "Tuy nhiên, dưới ánh sáng yếu ớt này, bạn dường như nghe thấy tiếng đập trái tim rất vui tươi và tràn đầy sức sống."
  },
  AvgDialog_18959_Content_93 = {
    Text = "Lâu không gặp, anh Jenkin."
  },
  AvgDialog_18959_Content_94 = {
    Text = "Bầu trời cuối cùng cũng tạnh. Ánh nắng treo cao trên không trung, rải rắc ánh vàng kim và sự ấm áp dịu nhẹ và dễ chịu."
  },
  AvgDialog_18959_Content_95 = {
    Text = "Gió mang theo hương thơm tươi mát của đất đai thổi đến, bạn và 24 được bao phủ bởi ánh nắng ấm áp, mỉm cười nhìn nhau."
  },
  AvgDialog_18959_Content_96 = {
    Text = "Đi nào, cô gái 24."
  },
  AvgDialog_18959_Content_97 = {
    Text = "Những đám mây u ám liên tiếp những ngày qua cuối cùng cũng tan đi, câu chuyện phiêu lưu của các bạn vừa mới bắt đầu."
  },
  AvgDialog_18960_Content_1 = {
    Text = "Sự sụp đổ trong im lặng"
  },
  AvgDialog_18960_Content_10 = {
    Text = "Bây giờ chúng ta không còn lựa chọn nào khác."
  },
  AvgDialog_18960_Content_11 = {
    Text = "Có thể thử"
  },
  AvgDialog_18960_Content_12 = {
    Text = "%player%,hy vọng bạn bình tĩnh một chút."
  },
  AvgDialog_18960_Content_13 = {
    Text = "Phía trước đã bị dung dịch rỗng rỗng lấp đầy, ngay cả thân thể được đánh thức, ngâm trong đó trong thời gian dài cũng sẽ bị ảnh hưởng."
  },
  AvgDialog_18960_Content_14 = {
    Text = "Bây giờ đã không thể đi qua đường bình thường trở về, cần tìm một giải pháp khác."
  },
  AvgDialog_18960_Content_15 = {
    Text = "Các biện pháp khác…các đường dẫn khác…"
  },
  AvgDialog_18960_Content_16 = {
    Text = "Tôi đã hiểu!"
  },
  AvgDialog_18960_Content_17 = {
    Text = "Nhìn, có một cửa thông gió ở đó."
  },
  AvgDialog_18960_Content_18 = {
    Text = "Các bạn theo ánh mắt của Jenkin ngẩng đầu lên, lỗ thông gió bé xíu nằm ngay trên đầu các bạn."
  },
  AvgDialog_18960_Content_19 = {
    Text = "Đó có thể là con đường dẫn đến phòng của quản lý, rỗng rỗng cũng không thể tiếp cận được…"
  },
  AvgDialog_18960_Content_2 = {
    Text = "16:15, bảo tàng sáp Rogers"
  },
  AvgDialog_18960_Content_20 = {
    Text = "Không được, đường dẫn này quá nhỏ, chúng ta không thể vào được."
  },
  AvgDialog_18960_Content_21 = {
    Text = "Tôi có thể chui vào."
  },
  AvgDialog_18960_Content_22 = {
    Text = "Các cậu quên rồi sao, tôi chính là \"chuột\"."
  },
  AvgDialog_18960_Content_23 = {Text = "Chít!"},
  AvgDialog_18960_Content_24 = {
    Text = "Không được, như vậy quá mạo hiểm. Không ai có thể đảm bảo chìa khóa vẫn còn trong phòng quản lý, thậm chí cả lỗ thông gió này có thực sự——"
  },
  AvgDialog_18960_Content_25 = {
    Text = "Chậc. Rườm rà, phiền phức chết được! Tôi còn tưởng cô là một người lớn dứt khoát cơ, Ramona."
  },
  AvgDialog_18960_Content_26 = {
    Text = "Tôi sẽ giúp các bạn làm rõ thực tế: Thứ nhất, giờ chẳng còn cách nào khác rồi phải không? Thay vì ngồi đây chờ chết, chi bằng thử vận may xem sao."
  },
  AvgDialog_18960_Content_27 = {
    Text = "Thứ hai, tôi và Brun cùng đi, tôi chỉ huy, còn nó là người giữ chìa khóa."
  },
  AvgDialog_18960_Content_28 = {
    Text = "Chít! Chít chít!"
  },
  AvgDialog_18960_Content_29 = {Text = "Thứ ba.."},
  AvgDialog_18960_Content_3 = {
    Text = "Các người loạng choạng chạy trong đống đổ nát, tiếng thở dồn dập hòa lẫn vào nhau."
  },
  AvgDialog_18960_Content_30 = {
    Text = "Lần này tôi đã gây ra không ít rắc rối, chị còn phải chịu đòn vì tôi."
  },
  AvgDialog_18960_Content_31 = {
    Text = "Vậy nên……"
  },
  AvgDialog_18960_Content_32 = {
    Text = "Hãy để tôi giúp đỡ một chút, tôi không muốn mãi là gánh nặng mà các bạn phải chăm sóc."
  },
  AvgDialog_18960_Content_33 = {
    Text = "Sau khi nói xong, Jenkin nhanh chóng trèo lên cửa thông gió và biến mất trong nháy mắt, giống như cách cậu đã làm nhiều lần trước đây khi di chuyển qua lại giữa những ngôi nhà cao thấp ở Whitechapel."
  },
  AvgDialog_18960_Content_34 = {
    Text = "Jenkin…! Cô ấy chưa bao giờ chịu lắng nghe tôi…"
  },
  AvgDialog_18960_Content_35 = {
    Text = "Đừng lo lắng, Cô 24. Jenkin khéo léo hơn tất cả chúng ta, cô ấy sẽ ổn thôi."
  },
  AvgDialog_18960_Content_36 = {
    Text = "……Tôi tin cô ấy."
  },
  AvgDialog_18960_Content_4 = {
    Text = "Cuối cùng, các người thấy cánh cửa nặng nề phía trước. Chỉ cần nhẹ nhàng đẩy một cái ——"
  },
  AvgDialog_18960_Content_5 = {
    Text = "Ôi không, cửa bị khóa rồi."
  },
  AvgDialog_18960_Content_6 = {
    Text = "Phía trước đã trở thành một đại dương tối tăm, nguy hiểm dần dần tiếp cận, không có bất kỳ con đường lui nào."
  },
  AvgDialog_18960_Content_7 = {
    Text = "Dường như là cánh cửa mà anh William đã đề cập… chìa khóa có lẽ ở phòng của thủ thư trưởng."
  },
  AvgDialog_18960_Content_8 = {
    Text = "Không đi được"
  },
  AvgDialog_18960_Content_9 = {
    Text = "Đây toàn là dung dịch ăn mòn… ngay cả thân thể được đánh thức, nếu ngâm trong đó quá lâu cũng sẽ nhanh chóng dẫn đến tử vong."
  },
  AvgDialog_18961_Content_1 = {
    Text = "Hầm nước ngầm"
  },
  AvgDialog_18961_Content_10 = {
    Text = "À, mệt quá mệt quá!"
  },
  AvgDialog_18961_Content_100 = {
    Text = "Giây tiếp theo, cô nhẹ nhàng rung cổ tay, sáp nóng bỏng bỗng nhiên đổ xuống, cánh tay trắng muốt nở rộ những bông hoa đỏ rực ghê rợn."
  },
  AvgDialog_18961_Content_101 = {
    Text = "Á á á á——!"
  },
  AvgDialog_18961_Content_102 = {
    Text = "Ồ ya… hoa văn thật đẹp."
  },
  AvgDialog_18961_Content_103 = {
    Text = "George ghét lũ heo ồn ào, nhét toàn bộ sáp vào miệng cô ta."
  },
  AvgDialog_18961_Content_104 = {
    Text = "Đèn nến bay đến trước mặt Jenkin, hơi nóng bốc lên làm mặt Jenkin đỏ bừng."
  },
  AvgDialog_18961_Content_105 = {
    Text = "Đế nến chứa đầy sáp nóng, sắp tràn ra ngoài."
  },
  AvgDialog_18961_Content_106 = {
    Text = "<Shake:kẻ lừa gạt…… không phải nói là không đau chút nào sao……>"
  },
  AvgDialog_18961_Content_107 = {
    Text = "Thật sự ngại quá, tôi đã không còn là con người từ lâu rồi, không ngờ lại cảm thấy khó chịu như vậy~"
  },
  AvgDialog_18961_Content_108 = {
    Text = "Hoàn hảo. Hai người lên đi, cạy miệng cô ta ra."
  },
  AvgDialog_18961_Content_109 = {
    Text = "Tiếp theo chỉ cần đổ sáp vào, những con chuột bẩn thỉu trong cống sẽ mãi mãi ngậm miệng."
  },
  AvgDialog_18961_Content_11 = {
    Text = "Lần sau nếu còn chậm chạp như vậy, tớ sẽ nhét cậu vào quan tài luôn đấy~"
  },
  AvgDialog_18961_Content_110 = {
    Text = "Dừng lại… nhanh dừng lại! cô ấy không liên quan đến chuyện này…"
  },
  AvgDialog_18961_Content_111 = {
    Text = "<Small:chị… thật đau… rất đau…>"
  },
  AvgDialog_18961_Content_112 = {
    Text = "Đừng... đừng, tôi đổi ý rồi, tôi không muốn chết! Đừng lại gần...!"
  },
  AvgDialog_18961_Content_114 = {
    Text = "……đợi một chút."
  },
  AvgDialog_18961_Content_115 = {
    Text = "Trong hỗn loạn, bạn bỗng nghe thấy một tiếng thở dài nhẹ nhàng."
  },
  AvgDialog_18961_Content_116 = {
    Text = "Tôi nói… xin hãy chờ một chút."
  },
  AvgDialog_18961_Content_12 = {
    Text = "Xin lỗi, cô Pandia……"
  },
  AvgDialog_18961_Content_13 = {
    Text = "<Big:Ngài Pandia ——!!>"
  },
  AvgDialog_18961_Content_14 = {
    Text = "Hình dáng người phụ nữ bay lượn như mây, vạt váy dài xoay tròn phát ra ánh sáng trắng. Cô ấy quỳ sụp xuống trước mặt Pandia."
  },
  AvgDialog_18961_Content_15 = {
    Text = "Pandia đại nhân! Xin đừng đối xử với 24 như vậy, nếu muốn trừng phạt…"
  },
  AvgDialog_18961_Content_16 = {
    Text = "Hãy nhắm vào tôi!"
  },
  AvgDialog_18961_Content_18 = {
    Text = "Tôi đã thay đổi ý định, mọi người đều làm rất tốt, lui xuống đi."
  },
  AvgDialog_18961_Content_19 = {
    Text = "Thưa ngài, tôi hiểu ngài không nỡ trách mắng tôi. Ngài luôn luôn dịu dàng như vậy.."
  },
  AvgDialog_18961_Content_2 = {
    Text = "Không tồi, mọi người đều đã tập trung đủ. Bây giờ chúng ta phải chuẩn bị một món quà lớn cho Misaque."
  },
  AvgDialog_18961_Content_21 = {
    Text = "Ôi người yêu dấu của tôi, người yêu dấu nhất, quý giá nhất của tôi, hãy thả chân tôi ra trước được không?"
  },
  AvgDialog_18961_Content_22 = {
    Text = "Mọi thứ đều nghe theo ngài, thưa ngài Pandia."
  },
  AvgDialog_18961_Content_23 = {
    Text = "Thật ngoan. Giống như bây giờ… sau đó quay lưng lại, đi thẳng mười bước, rời khỏi căn phòng này và đừng bao giờ quay đầu lại."
  },
  AvgDialog_18961_Content_24 = {
    Text = "Hiểu ý tôi không?"
  },
  AvgDialog_18961_Content_25 = {
    Text = "Rõ... Tôi sẽ nhớ ngài, thưa Pandia...\nKhông đúng, tôi đã bắt đầu nhớ ngài rồi!"
  },
  AvgDialog_18961_Content_26 = {
    Text = "Phụ nữ quay người lại, trước khi đi còn không quên đóng cửa phòng một cách cẩn thận."
  },
  AvgDialog_18961_Content_27 = {
    Text = "Hừm… Thật là đau đầu."
  },
  AvgDialog_18961_Content_28 = {
    Text = "Sau khi xác nhận cửa phòng đã đóng chặt, Pandia hít một hơi thật sâu rồi nhanh chóng lấy lại năng lượng như bình thường."
  },
  AvgDialog_18961_Content_29 = {
    Text = "Được rồi các bạn, chúng ta vừa nói đến đâu nhỉ~"
  },
  AvgDialog_18961_Content_3 = {
    Text = "Nhưng mà, lúc này chờ đợi vẫn hơi chút —— không đúng, cực kỳ lâu."
  },
  AvgDialog_18961_Content_30 = {
    Text = "Hô hấp……thật khó khăn"
  },
  AvgDialog_18961_Content_32 = {
    Text = "Đừng, đừng cử động, tôi đang trang điểm cho bạn."
