  AvgDialog_18961_Content_33 = {
    Text = "Không tốt, khóe miệng bị mờ đi. hmm…"
  },
  AvgDialog_18961_Content_34 = {
    Text = "Bạn là, Rogers…"
  },
  AvgDialog_18961_Content_35 = {
    Text = "Ngón tay lạnh lẽo lướt qua khóe môi bạn, bạn ngửi thấy mùi mỡ thiu thối rữa nồng nặc."
  },
  AvgDialog_18961_Content_36 = {
