  },
  AvgDialog_18961_Content_47 = {
    Text = "Đối tác của bạn đã bị biến thành bình tượng nến rồi, ngài Rogers đã mất một giờ để hoàn thành việc này."
  },
  AvgDialog_18961_Content_48 = {
    Text = "Mèo hổ báo! meo!"
  },
  AvgDialog_18961_Content_49 = {
    Text = "Có thích không? Có phải siêu đáng yêu~"
  },
  AvgDialog_18961_Content_5 = {
    Text = "……vâng, Pandia."
  },
  AvgDialog_18961_Content_50 = {
    Text = "Phì, hãy lấy tay bẩn thỉu của ngươi ra khỏi người cô ấy!"
  },
  AvgDialog_18961_Content_51 = {
    Text = "Rogers, người khiến tôi ngất xỉu trong phường chính là bạn phải không."
