  AvgDialog_18961_Content_55 = {
    Text = "Bạn @2 đang chửi ai vậy?! @1 lợn!"
  },
  AvgDialog_18961_Content_56 = {
    Text = "À, phải không? Bạn tên là Jenkin, đúng không. Sara đã kể cho chúng tôi nghe về Jenkin."
