  },
  AvgDialog_18961_Content_59 = {
    Text = "Người phụ nữ điên đánh đập cậu bé Jenkin mỗi ngày bằng chổi, dây da, và bất kỳ dụng cụ nào có thể tìm được, đồng thời dùng những lời lẽ bẩn thỉu nhất để chửi mắng cậu bé…"
