  AvgDialog_18980_Content_19 = {Text = "Cô ấy.."},
  AvgDialog_18980_Content_2 = {
    Text = "Kiểm tra mục tiêu nhiệm vụ. \n<Yellow:Nhiệm vụ một: đến bảo tàng sáp Rogers, tìm cô Mason và điều tra viên William.>"
  },
  AvgDialog_18980_Content_20 = {
