  AvgDialog_18980_Content_27 = {
    Text = "Bây giờ……một chữ, tôi thậm chí không thể nhớ ra một chữ."
  },
  AvgDialog_18980_Content_28 = {
    Text = "À, các bạn không nhớ gì sao?"
  },
  AvgDialog_18980_Content_29 = {
    Text = "\"Nhà bảo vệ xuất sắc của chủ nghĩa lập thể, linh hồn của Botticelli đang ẩn dật tại bảo tàng sáp ở góc đường Southwark...\""
  },
  AvgDialog_18980_Content_3 = {
    Text = "<Yellow:nhiệm vụ thứ hai: điều tra mối liên hệ giữa Rogers và vụ mất tích tại \"Nhà nuôi dưỡng người nghèo\".>"
  },
  AvgDialog_18980_Content_30 = {
