  },
  AvgDialog_18982_Content_47 = {
    Text = "Khi những cấm kỵ bị phá vỡ hoàn toàn, quy tắc bị chà đạp tùy tiện, tiếng chuông phán xét không thể tiếp tục im lặng và đồng loạt vang lên những lời đe dọa sắc bén nhất."
