    Text = "Tiền bối…"
  },
  AvgDialog_18991_Content_1 = {
    Text = "Xin chào, Bà Daphne"
  },
  AvgDialog_18991_Content_10 = {
    Text = "Giọng điệu của cô mềm mại và ẩn ý, mang theo sự thanh lịch đặc trưng của giới thượng lưu."
  },
  AvgDialog_18991_Content_11 = {
    Text = "Mặc dù nói xin lỗi, nhưng biểu cảm trên khuôn mặt không hề tỏ ra hối lỗi, ngược lại còn toát lên vẻ châm chọc."
  },
  AvgDialog_18991_Content_12 = {
    Text = "Gần đây có \"chó địa ngục\" xuất hiện ở vùng quê này, sớm chìm vào giấc mơ hoặc nghỉ ngơi yên tĩnh có thể giúp bạn tránh khỏi tầm mắt của nó."
  },
  AvgDialog_18991_Content_13 = {
    Text = "Chó địa ngục?"
  },
  AvgDialog_18991_Content_14 = {
    Text = "Huyền thoại kể rằng chỉ cần bị ánh mắt của nó bắt được ba lần, sẽ rơi vào hư vô và đón nhận cái chết. \nCác bạn, cẩn thận một chút nhé!"
  },
  AvgDialog_18991_Content_15 = {
    Text = "Tôi nghĩ rằng đây chỉ là lời nói dỗ dành cho trẻ em không chịu ngủ."
  },
  AvgDialog_18991_Content_16 = {
    Text = "Chân giả khó phân, ai mà biết được? Những truyền thuyết dân gian vùng quê cũng có phần chân thực của nó."
  },
  AvgDialog_18991_Content_17 = {
    Text = "Bạn có vẻ không nghĩ vậy."
  },
  AvgDialog_18991_Content_18 = {
    Text = "Đúng và sai luôn đi cùng nhau, sự thật trong mắt một người có thể là sai lầm trong mắt người khác."
  },
  AvgDialog_18991_Content_19 = {
    Text = "Nhìn tôi xem, lại đang nói những lời lộn xộn, mong mọi người đừng để ý. \nHãy nghỉ sớm đi, những vị khách thân yêu."
  },
  AvgDialog_18991_Content_2 = {
    Text = "Bạn được dẫn dắt bởi cô gái trẻ đến một cửa hàng nhỏ và giản dị ở góc phố."
  },
  AvgDialog_18991_Content_20 = {
    Text = "Nói xong, Đào Đen Đá đứng dậy, thong dong rời đi, chỉ để lại cho các người một bóng lưng tỏa hương thơm ngát."
  },
  AvgDialog_18991_Content_21 = {
    Text = "… các người đang nói bậy bạ gì vậy?"
  },
  AvgDialog_18991_Content_22 = {
    Text = "Tôi cũng không hiểu."
  },
  AvgDialog_18991_Content_23 = {
    Text = "Chúng ta hiện đang ở trong một ảo ảnh. \n Hãy dùng chìa khóa bạc xem, bạn sẽ hiểu tôi đang nói gì."
  },
  AvgDialog_18991_Content_25 = {Text = "!"},
  AvgDialog_18991_Content_26 = {
    Text = "Mức độ rỗng rỗng ở khu vực này vượt xa mức bình thường, nhưng Đào Đen Đá và hàng hóa vẫn nguyên vẹn không tì vết."
  },
  AvgDialog_18991_Content_27 = {
    Text = "Bà Đào Đen Đá (Lady Daffodil), Bà Hoa Thủy Tiên, thật khó tin đó là tên thật."
  },
  AvgDialog_18991_Content_28 = {
    Text = "Nếu là một thương nhân buôn bán hàng cấm, việc sử dụng tên giả vẫn có thể hiểu được."
  },
  AvgDialog_18991_Content_29 = {
    Text = "Dù vậy, cũng rất kỳ lạ."
  },
  AvgDialog_18991_Content_3 = {
    Text = "Cửa hàng nhỏ bao quanh bởi sương tím chỉ rộng khoảng 3 mét, nhưng cách bài trí lại rất tinh tế. \nNhững đồ trang trí cổ điển và tinh xảo được xếp chồng lên nhau trên quầy, lộn xộn nhưng vẫn có trật tự."
  },
  AvgDialog_18991_Content_30 = {
    Text = "Giả sử bạn là một thương nhân \"có kinh nghiệm\", trong thị trấn thường xuyên xảy ra các vụ mất tích, liệu bạn có dễ dàng cho ba người lạ vào nhà vào nửa đêm không?"
  },
  AvgDialog_18991_Content_31 = {
    Text = "Và tôi cứ cảm thấy như có gì đó đang nhìn chúng ta."
  },
  AvgDialog_18991_Content_32 = {
    Text = "Bạn cũng cảm thấy gai góc toàn thân phải không?"
  },
  AvgDialog_18991_Content_33 = {
    Text = "Đừng nghĩ tôi như bạn. \nTôi chỉ rất tò mò, rốt cuộc là tên nào liều lĩnh dám coi tôi là con mồi."
  },
  AvgDialog_18991_Content_34 = {
    Text = "Đây ít nhất có mái che mưa. \nChúng ta luân phiên nghỉ ngơi, giữ gìn sự cảnh giác, việc còn lại để dành đến ngày mai."
  },
  AvgDialog_18991_Content_36 = {
    Text = "Đúng rồi, Erika?"
  },
  AvgDialog_18991_Content_37 = {
    Text = "Xin chào, nhân hình tự động Erika sẵn sàng hoạt động 24/7, cung cấp cho bạn sự hỗ trợ kỹ thuật và thông tin ngay lập tức."
  },
  AvgDialog_18991_Content_38 = {
    Text = "Từ khóa: \"Bà Daphne\", nghề người buôn cổ vật."
  },
  AvgDialog_18991_Content_39 = {
    Text = "Đang nhập từ khóa \"Đào Đen Đá\", \"cổ vật thương nhân\", đang thực hiện tìm kiếm, vui lòng chờ trong giây lát. \nKết quả tìm kiếm, không có. Rất xin lỗi, vui lòng thay đổi từ khóa và thử lại…"
  },
  AvgDialog_18991_Content_4 = {
    Text = "À, nói là cửa hàng của \"bà\" Đào Đen Đá, hóa ra chỉ là một cửa hàng bán lẻ trên đường phố."
  },
  AvgDialog_18991_Content_41 = {
    Text = "Đêm dần sâu lắng, cùng với tiếng trò chuyện của Ramona và Erika, bạn dần chìm vào giấc mơ…"
  },
  AvgDialog_18991_Content_43 = {
    Text = "… đừng tranh cãi với cô ấy nữa. Sau vụ đó, đã có người nói cô ấy không bình thường rồi."
  },
  AvgDialog_18991_Content_44 = {
    Text = "Cô ấy tìm đến bác sĩ, tuyên bố rằng mình có thể nhìn thấy những \"<Yellow:lỗ hổng trên thân thể con người>\"…\nCòn nói rằng, những lỗ hổng đó đã khiến chồng và con gái của cô ấy chết."
  },
  AvgDialog_18991_Content_45 = {
    Text = "Cô ấy không phải vẫn độc thân sao, làm gì có chồng và con gái?"
  },
  AvgDialog_18991_Content_46 = {
    Text = "Đúng vậy, chẳng phải là điên khùng sao?"
  },
  AvgDialog_18991_Content_47 = {
    Text = "Vậy thì, chúng ta có thể yêu cầu đánh giá trạng thái tinh thần của cô ấy không?"
  },
  AvgDialog_18991_Content_48 = {
    Text = "Còn cần phải đánh giá? Người bình thường sống tốt, có ai tự nguyện đi chịu chết đâu?"
  },
  AvgDialog_18991_Content_49 = {
    Text = "Còn những người yêu thích khám phá điên rồ kia, tôi thấy đầu họ cũng không bình thường lắm. Nếu thực sự làm kiểm tra tâm lý, chắc chắn không ai vượt qua được."
  },
  AvgDialog_18991_Content_5 = {
    Text = "Và, những thứ này... cổ vật? Hình dáng kỳ dị, thật sự méo mó."
  },
  AvgDialog_18991_Content_50 = {
    Text = "Chất lỏng đen đặc quánh từ chân trời rơi xuống, che khuất tầm mắt."
  },
  AvgDialog_18991_Content_51 = {
    Text = "Được phủ lên <Blue:Quỹ> trên bậc thang, trên cánh cửa lớn của Quỹ, và trên quầy hàng của Quỹ."
  },
  AvgDialog_18991_Content_52 = {
    Text = "Lên tới khuôn mặt của nhân viên Quỹ."
  },
  AvgDialog_18991_Content_53 = {
    Text = "Tôi cảnh cáo các bạn, tôi có quyền kiện các bạn ra tòa vì tội phỉ báng."
  },
  AvgDialog_18991_Content_54 = {
    Text = "Những chất nhầy màu đen này…… mặc dù các ngươi không thể nhìn thấy, nhưng chúng là có thật. \n chính là chúng, đã cướp đi……"
  },
  AvgDialog_18991_Content_55 = {
    Text = "Đã cướp đi… người thân yêu nhất của tôi…"
  },
  AvgDialog_18991_Content_56 = {
    Text = "Tại sao? Tại sao họ đều không thấy?"
  },
  AvgDialog_18991_Content_57 = {
    Text = "Rất đau, nhưng @2 có thể chịu đựng được, mẹ ơi."
  },
  AvgDialog_18991_Content_58 = {
    Text = "Không được, đừng như vậy, bạn sẽ biến mất. \nTôi đã mất @3, tôi không thể mất bạn nữa."
  },
  AvgDialog_18991_Content_59 = {
    Text = "Tôi sẽ không rời bỏ mẹ."
  },
  AvgDialog_18991_Content_6 = {
    Text = "Tôi rất trân trọng những món đồ sưu tập này. Bạn không thấy chúng mang một vẻ đẹp của thời gian tích lũy sao?"
  },
  AvgDialog_18991_Content_60 = {
    Text = "Tại sao? Bạn không nói là sẽ không rời bỏ tôi sao?"
  },
  AvgDialog_18991_Content_61 = {
    Text = "Đúng rồi, bạn cũng không thấy."
  },
  AvgDialog_18991_Content_62 = {
    Text = "Nhưng tôi nhìn thấy mà, tôi thật sự nhìn thấy!"
  },
  AvgDialog_18991_Content_63 = {
    Text = "Họ không phải mất tích, họ bị bệnh, họ đang tan biến……\nDịch đen đặc quánh đó, đang nuốt chửng họ……"
  },
  AvgDialog_18991_Content_64 = {
    Text = "Phụ nữ thì thầm rồi chìm vào giấc ngủ. Sương mù xung quanh nhẹ nhàng lan tỏa, dần dần bao trùm lấy cô ấy. \n Trong làn sương dày, xuất hiện bóng màu tím thẫm."
  },
  AvgDialog_18991_Content_65 = {
    Text = "Ban đầu chỉ định vào xem có phải đã đến lúc thu hoạch... thật không ngờ mọi việc lại phát triển một cách thú vị như vậy."
  },
  AvgDialog_18991_Content_66 = {
    Text = "Thôi, mạng sống này bạn cứ giữ lấy trước đi."
  },
  AvgDialog_18991_Content_67 = {
    Text = "Chờ bạn trở về từ vùng đất băng giá lạnh lẽo đó, hãy nhớ giao cho tôi nhé!"
  },
  AvgDialog_18991_Content_7 = {
    Text = "Giọng nói u linh chảy ra từ bóng tối mờ ảo, như một âm bass sâu lắng hòa vào bản giao hưởng phức hợp."
  },
  AvgDialog_18991_Content_8 = {
    Text = "Xin lỗi, hãy để tôi tự giới thiệu, tôi chính là chủ cửa hàng nhỏ này, Đào Đen Đá."
  },
  AvgDialog_18991_Content_9 = {
    Text = "Tôi không có ý định làm phiền cuộc trò chuyện của các vị khách. \nChỉ muốn nhắc nhở mọi người, đêm đã khuya lắm rồi, nên đi nghỉ sớm."
  },
  AvgDialog_18992_Content_1 = {
    Text = "Cuộc đời không có bạn bè"
  },
  AvgDialog_18992_Content_10 = {
    Text = "Hiro lẩm bẩm, miệng khẽ mở ra và ngậm lại, đọc lên những câu chú ngữ điệu vụng về, cổ xưa và khó hiểu."
  },
  AvgDialog_18992_Content_12 = {
    Text = "Tiếng gì vậy! Khốn kiếp, đầu đau quá……"
  },
  AvgDialog_18992_Content_13 = {
    Text = "Bạn chưa bao giờ nghe qua ngôn ngữ này, nhưng không hiểu sao bạn lại hiểu được ý nghĩa của nó. \nNhững lời thì thầm vô tận xâm nhập vào vỏ não, giọng điệu kỳ quái vang lên ám ảnh."
