  AvgDialog_18994_Content_1 = {
    Text = "Giao dịch công bằng"
  },
  AvgDialog_18994_Content_10 = {
    Text = "Đào Đen Đá lôi ra hai tập tài liệu <Blue:tập hồ sơ> từ khoảng trống của sương xám, nhẹ nhàng gạt bỏ lớp bụi trên đó."
  },
  AvgDialog_18994_Content_11 = {
    Text = "Sau khi mọi việc đã lắng đọng, tôi sẽ gửi chúng đến đại bản doanh của hai vị. \nVà điều kiện duy nhất của tôi là hai vị hãy từ biệt tại đây và mỗi người đi con đường riêng của mình."
  },
  AvgDialog_18994_Content_12 = {
    Text = "Có lẽ một ngày nào đó, con đường sẽ lại giao nhau ở phía trước, nhưng điều đó chỉ có thể giao phó cho số phận được \"Người\" chú mục."
  },
  AvgDialog_18994_Content_13 = {
    Text = "Dữ liệu đó……"
  },
  AvgDialog_18994_Content_14 = {
    Text = "Và \"chó địa ngục\". Bạn không thật sự nghĩ rằng tôi đến Laï là để làm ăn cổ vật chứ?"
  },
  AvgDialog_18994_Content_15 = {
    Text = "Tôi cần xác nhận giá trị của hồ sơ."
  },
  AvgDialog_18994_Content_16 = {
    Text = "Ramona, bạn nghĩ sao?"
  },
  AvgDialog_18994_Content_17 = {
    Text = "Chúng ta vốn là bên bị tấn công, ngừng chiến không làm chúng ta thiệt hại."
  },
  AvgDialog_18994_Content_18 = {
    Text = "Tuy nhiên, tôi cần xác nhận giá trị của bản ghi này. \nBạn có thể cho tôi đọc trang bìa không?"
  },
  AvgDialog_18994_Content_19 = {
    Text = "Đúng là như vậy."
  },
  AvgDialog_18994_Content_2 = {
    Text = "Tiếng lẩm bẩm tan biến, trong toa xe chỉ còn lại sự yên lặng vô tận."
  },
  AvgDialog_18994_Content_20 = {
    Text = "Ramona nhận hồ sơ từ tay Đào Đen Đá, ánh mắt nhanh chóng di chuyển qua vài dòng dưới kính, rồi gật đầu về phía bạn."
  },
  AvgDialog_18994_Content_21 = {
    Text = "Thành công."
  },
  AvgDialog_18994_Content_22 = {
    Text = "Tôi rất ngưỡng mộ những vị khách sảng khoái như quý vị. \nTài liệu sẽ được gửi đến phòng thu phát của Đại học Misag trong vòng bảy ngày."
  },
  AvgDialog_18994_Content_23 = {
    Text = "Không biết quý cô này đã đưa ra quyết định chưa?"
  },
  AvgDialog_18994_Content_24 = {
    Text = "Hiro gập cổ, dịch nhầy trong lòng bàn tay cô ngưng tụ thành gai."
  },
  AvgDialog_18994_Content_25 = {
    Text = "Tôi từ chối. Tôi cần thực hiện nhiệm vụ."
  },
  AvgDialog_18994_Content_26 = {
    Text = "Bạn sẽ suy nghĩ lại. \nĐây là tài liệu liên quan đến \"<Yellow:sự việc đó>\" cách đây mười năm."
  },
  AvgDialog_18994_Content_27 = {
    Text = "Đào Đen Đá lấy ra một huy hiệu, đặt trên lòng bàn tay, rồi đưa cho Hiro xem. \nNhìn thấy huy hiệu, sắc mặt Hiro đột nhiên thay đổi."
  },
  AvgDialog_18994_Content_28 = {
    Text = "Bạn đến từ đâu——"
  },
  AvgDialog_18994_Content_29 = {
    Text = "Suỵt——\nTrước khi bạn hứa giao dịch, tôi sẽ không nói gì cả."
  },
  AvgDialog_18994_Content_3 = {
    Text = "Lơ-tan bay lên, đỡ lấy Lily đang ngã."
  },
  AvgDialog_18994_Content_30 = {
    Text = "Hiro cau mày, mở miệng như muốn nói điều gì đó, cuối cùng không nói gì và rút lui vào bóng tối."
  },
  AvgDialog_18994_Content_31 = {
    Text = "Với một tiếng rên khẽ, Hiro hướng mũi gai xuống đất, dùng sức vẽ ra một đường khắc sâu, gai ma sát với mặt đất tạo ra những tia lửa nhỏ."
  },
  AvgDialog_18994_Content_32 = {
    Text = "Tôi cũng đồng ý. Nhưng ——"
  },
  AvgDialog_18994_Content_33 = {
    Text = "Cô ấy nâng tay lên, chỉa đầu nhọn vào hồ sơ trong vòng tay của Đào Đen Đá."
  },
  AvgDialog_18994_Content_34 = {
    Text = "Bạn phải giao hồ sơ cho tôi ngay bây giờ nhé."
  },
  AvgDialog_18994_Content_35 = {
    Text = "Vội vàng vậy sao? Tiếc rằng, giá cả đã được định sẵn. Cửa hàng giải sầu của Đào Đen Đá không có chỗ cho việc mặc cả."
  },
  AvgDialog_18994_Content_36 = {
    Text = "Đào Đen Đá gọi ra sương xám, đặt tài liệu lên đó, và tài liệu sắp bị sương xám nuốt chửng."
  },
  AvgDialog_18994_Content_37 = {
    Text = "Chậm mà chắc, Hiro như một bóng ảnh lướt nhanh về phía Đào Đen Đá."
  },
  AvgDialog_18994_Content_39 = {
    Text = "Tuy nhiên, bóng hình tím ấy đã biến mất ngay khi cô tiến đến. \nDạ Phong thong thả xuất hiện phía sau Hiro, trong tay vẫn giữ vững tập tài liệu."
  },
  AvgDialog_18994_Content_4 = {
    Text = "Pác, pác, pác. \n Trong đường hầm tối om, tiếng vỗ tay rõ ràng đột ngột vang lên."
  },
  AvgDialog_18994_Content_40 = {
    Text = "Đừng vội vàng, chú nhóc. \nĐược rồi, tôi sẽ không làm phiền nữa, chúc mọi người —— chuyến đi vui vẻ."
  },
  AvgDialog_18994_Content_41 = {
    Text = "Sương xám bao phủ. \nHơn mười giây sau, mọi thứ lại trở nên yên tĩnh, và dáng vẻ của Đào Đen Đá đã hoàn toàn biến mất."
  },
  AvgDialog_18994_Content_43 = {
    Text = "Hiro lạnh lùng hừ một tiếng, di chuyển nhanh rồi ẩn vào bóng tối."
  },
  AvgDialog_18994_Content_44 = {
    Text = "Ramona, vậy chúng ta…?"
  },
  AvgDialog_18994_Content_45 = {
    Text = "……lơ-tan, vui lòng chăm sóc Lily, đợi chúng tôi trở về."
  },
  AvgDialog_18994_Content_46 = {
    Text = "Tôi đã nói trước rồi, tôi không giỏi chăm sóc trẻ con."
  },
  AvgDialog_18994_Content_47 = {
    Text = "Người giữ bí mật, bạn có tin tôi không?"
  },
  AvgDialog_18994_Content_48 = {
    Text = "Tất nhiên."
  },
  AvgDialog_18994_Content_49 = {
    Text = "Hãy tạm thời nhắm mắt lại. \nChúng ta sẽ đi đến một nơi."
  },
  AvgDialog_18994_Content_5 = {
    Text = "Kèm theo những tràng pháo tay đầy nhịp nhàng là giọng nữ mơ hồ với nụ cười tán thưởng nhẹ nhàng. Tà váy bị cuốn vào làn sương xám, dần hiện ra từ ranh giới ánh sáng và bóng tối, xung quanh lập tức bao trùm bởi làn khói màu tím nhạt."
  },
  AvgDialog_18994_Content_50 = {
    Text = "Bạn nhắm mắt theo lời. \nTrong bóng tối, bạn cảm thấy bàn tay hơi lạnh của Ramona nắm lấy bạn, chậm rãi bước đi về một hướng xác định."
  },
  AvgDialog_18994_Content_6 = {
    Text = "Cảm ơn mọi người đã mang đến một màn trình diễn tuyệt vời, tôi thấy mọi người đều đã kiệt sức, có lẽ chúng ta nên tạm dừng cuộc chiến?"
  },
  AvgDialog_18994_Content_7 = {
    Text = "Bạn nói không đánh là không đánh? Chúng tôi dựa vào gì để nghe theo sự chỉ huy của bạn?"
  },
  AvgDialog_18994_Content_8 = {
    Text = "Cửa hàng nhỏ giải sầu chưa bao giờ phụ lòng khách hàng của mình. \nTôi đến để bàn một cuộc giao dịch."
  },
  AvgDialog_18994_Content_9 = {
    Text = "Tôi có hai tài liệu ở đây, mỗi tài liệu chứa những thông tin mà mọi người muốn biết."
  },
  AvgDialog_18995_Content_1 = {
    Text = "Những mụn mủ này... tôi có một dự cảm không tốt."
