  },
  AvgDialog_18997_Content_10 = {
    Text = "William cẩn thận lấy ra vài bức ảnh từ tập hồ sơ. \nỞ giữa bức ảnh, một tam giác đen kỳ quái và khó hiểu từ từ tỏa ra làn sương đen."
  },
  AvgDialog_18997_Content_11 = {
    Text = "<Yellow:nặng nề rỗng rỗng>."
  },
  AvgDialog_18997_Content_12 = {
    Text = "Cảnh sát nhận được báo cáo về việc mất tích cách đây hai tuần."
  },
  AvgDialog_18997_Content_13 = {
    Text = "<Yellow:tốc độ lây lan rất nhanh>, nhanh một cách bất thường."
  },
  AvgDialog_18997_Content_14 = {
    Text = "Trong thị trấn cũng xuất hiện một lượng lớn bệnh nhân hysteria, cảnh sát cũng đã cung cấp báo cáo về việc nhìn thấy \"<Blue:chó địa ngục Khắc Nhĩ Bá Lạc Tư>\"."
  },
  AvgDialog_18997_Content_15 = {
