  AvgDialog_18997_Content_17 = {
    Text = "Lần hành động này có thể phải đối mặt với một trận chiến ác liệt, tôi muốn mời \"vị đó\" đi cùng Người Giữ Gìn."
  },
  AvgDialog_18997_Content_18 = {
    Text = "Đứa điên chỉ biết nghĩ đến chiến đấu ấy… Sau khi hồ đen biến dị, cô ấy vẫn luôn ở đó, bỏ mặc mọi nhiệm vụ giảng dạy."
  },
  AvgDialog_18997_Content_19 = {
    Text = "Có lẽ phải để Người Giữ Gìn đích thân đi mời, mới có thể khiến cô ấy di chuyển."
  },
  AvgDialog_18997_Content_2 = {
    Text = "Đại học Misaque Phòng Thức tỉnh"
