  },
  AvgDialog_18997_Content_21 = {
    Text = "Lơ-tan ngồi ở góc xa nhất của hồ đen, ngẩng đầu nhìn lên bầu trời mênh mông. \n Đó là nơi Tà Vy từng xuất hiện."
  },
  AvgDialog_18997_Content_22 = {
    Text = "Bạn nói, Đấng còn tỉnh lại được không?"
