  },
  AvgDialog_18997_Content_3 = {
    Text = "<Blue:Cerberus> truyền thuyết, có thể truy ngược về thế kỷ thứ 8 trước Công nguyên của Hy Lạp cổ đại. \nVào thời điểm đó, các nhà thơ đã mô tả nó như sau"
