  },
  AvgDialog_18997_Content_35 = {
    Text = "Bạn nói."
  },
  AvgDialog_18997_Content_36 = {
    Text = "Trước hết, tôi chỉ phụ trách chiến đấu, những việc rắc rối khác đừng tìm đến tôi."
  },
  AvgDialog_18997_Content_37 = {
    Text = "Thứ hai, đừng ảnh hưởng đến hành động riêng lẻ của tôi."
  },
  AvgDialog_18997_Content_38 = {
    Text = "Thứ ba, đối thủ tôi chọn phải cho tôi cơ hội đấu tay đôi với anh ta."
