  AvgDialog_18997_Content_4 = {
    Text = "Echidna là mẹ, Typhon là cha, đầu nó có ba. <Yellow:Kẻ bị nó săn đuổi ba lần, hồn sẽ phải về Địa phủ>."
  },
  AvgDialog_18997_Content_40 = {
