  AvgDialog_19013_Content_2 = {
    Text = "Cầu thép Foles bắc ngang mặt sông vào giờ nửa đêm, \n các thanh dầm thép như những dây đàn hạc, gió cất lên thành khúc ai ca trong đêm tối."
  },
  AvgDialog_19013_Content_3 = {
    Text = "Đêm tối như bóng tối sâu thẳm thôn tính mọi vật, ở đây Koom đã chờ các người rất lâu rồi, gừ gừ hai tiếng, cuối cây cầu sắt mờ tối, ánh đèn mờ ảo, lay động không rõ ràng."
