  AvgDialog_19014_Content_2 = {
    Text = "Cuộc điều tra về hiện tượng rỗng rỗng không phải là môn thể thao đánh nhau, Lơ-tan. Nếu chỉ có đổ mồ hôi mới giúp bạn tập trung hơn, tôi sẽ khuyên bạn tìm đến Sylvia để được tư vấn tâm lý và cải thiện sự chú ý."
  },
  AvgDialog_19014_Content_3 = {
