  AvgDialog_19019_Content_63 = {
    Text = "Lily bịt mặt lùi hai bước, co lại phía sau lưng bạn."
  },
  AvgDialog_19019_Content_64 = {
    Text = "Chưa có bằng chứng cho thấy việc của con gái bạn liên quan đến Lily!"
  },
  AvgDialog_19019_Content_65 = {
    Text = "Ramona liếc mắt một cái, ra hiệu cho bạn đừng nói nữa."
  },
  AvgDialog_19019_Content_66 = {
    Text = "Đừng có mà bắt nạt mẹ Lisa!"
  },
  AvgDialog_19019_Content_67 = {
    Text = "Các bạn là ai?"
  },
  AvgDialog_19019_Content_68 = {
    Text = "Tôi tên là Hank, anh ấy là John, chúng tôi đều là bạn của Lisa!"
  },
  AvgDialog_19019_Content_69 = {
    Text = "Ngày đó Lily đã đưa Lisa đi ngoại ô, chúng tôi đã tận mắt chứng kiến!"
  },
  AvgDialog_19019_Content_7 = {
    Text = "Chúng tôi gọi bạn mãi không tỉnh, đứa bé này chỉ nói muốn xem xem sao thế… ai ngờ lại ngủ thiếp đi trên ngực bạn."
  },
  AvgDialog_19019_Content_70 = {
    Text = "Đừng nói nhiều, {Male=anh ấy,Female=cô ấy}của họ chắc chắn là đồng bọn của tên quỷ này, hãy cho {Male=anh ấy,Female=cô ấy}của họ một bài học!"
  },
  AvgDialog_19019_Content_71 = {
    Text = "Bảo vệ mẹ Lisa!"
  },
  AvgDialog_19019_Content_72 = {
    Text = "… Bạn có thấy rằng chúng ta luôn gây khó dễ cho con cái không, phải không?"
  },
  AvgDialog_19019_Content_8 = {
    Text = "Cô gái lưu luyến đứng dậy, ánh mắt vẫn hướng về phía ngực bạn. \nBạn cúi đầu nhìn xuống, chìa khóa bạc vẫn nằm trên ngực dù đang ngủ say, tỏa ra ánh bạc rực rỡ."
  },
  AvgDialog_19019_Content_9 = {
    Text = "Bạn tên là gì?"
  },
  AvgDialog_19021_Content_1 = {
    Text = "Ẩn dưới vành mũ"
  },
  AvgDialog_19021_Content_10 = {
    Text = "Vậy, anh tìm tôi là vì một mục đích chính đáng và hợp lý. \nXét đến định nghĩa của cửa hàng tạp hóa này, bạn đến đây chắc chắn là để thực hiện một giao dịch nào đó."
  },
  AvgDialog_19021_Content_11 = {
    Text = "Bạn không đưa ra yêu cầu ngay lúc đó, mà lại đi đường vòng lớn như vậy để tìm đến tôi, điều này cho thấy tại hiện trường có người mà bạn không muốn họ nghe cuộc giao dịch này."
  },
  AvgDialog_19021_Content_12 = {
    Text = "Vì vậy, tôi có thể kết luận rằng, bạn muốn tìm hiểu thông tin liên quan đến Hiro và Lily."
  },
  AvgDialog_19021_Content_13 = {
    Text = "Đúng vậy. Chính xác hơn, mối quan hệ giữa Hiro và Lily là gì? \n Điều được gọi là <Yellow:「đồng nguồn」>, rốt cuộc là khái niệm như thế nào?"
  },
  AvgDialog_19021_Content_14 = {
    Text = "Đây không phải là vấn đề thực sự của bạn."
  },
  AvgDialog_19021_Content_15 = {
    Text = "Bạn thực sự muốn hỏi về lực lượng của chính mình, phải không…\nBạn đã gặp những tồn tại sở hữu <Yellow:「cùng nguồn」>, đúng không?"
  },
  AvgDialog_19021_Content_16 = {
    Text = "<Gray:Ramona đã biết?! Quả nhiên, thỏa thuận giữa tôi và lord không thể giấu được cô ấy…>"
  },
  AvgDialog_19021_Content_17 = {
    Text = "Sắc mặt của Ramona thay đổi đột ngột, Đào Đen Đá vẫn cười tươi rạng rỡ, đầy toan tính."
  },
  AvgDialog_19021_Content_18 = {
    Text = "Không cần lo lắng, tôi không có thói quen xấu là đi cáo trạng. Tại nơi của Lord Dexter, bạn vẫn có thể tiếp tục che đậy sự thật."
  },
  AvgDialog_19021_Content_19 = {
    Text = "Nhưng rất tiếc, tôi không thể nói cho bạn câu trả lời. \nTrong giao dịch của tôi với Đại học Misag, có viết rõ ràng trên giấy trắng mực đen: không được can thiệp vào công việc của trường."
  },
  AvgDialog_19021_Content_2 = {
    Text = "Chúng ta đã đến."
  },
  AvgDialog_19021_Content_20 = {
    Text = "Tôi chỉ có thể đưa ra một lời khuyên cho bạn: \nVì bạn có vẻ rất tò mò, tại sao không thử hỏi <Yellow:cô ấy> trực tiếp nhỉ?"
  },
  AvgDialog_19021_Content_21 = {
    Text = "Ramona giật mình."
  },
  AvgDialog_19021_Content_22 = {
    Text = "Có thể là vì câu trả lời quá đơn giản, nên ngược lại trở thành điểm mù trong suy nghĩ. Cô ấy chưa bao giờ cân nhắc đến khả năng này."
  },
  AvgDialog_19021_Content_23 = {
    Text = "Cô ấy nhấc góc váy lên, cúi chào lịch sự."
  },
  AvgDialog_19021_Content_24 = {
    Text = "Cảm ơn sự chỉ dẫn, tôi xin từ biệt ."
  },
  AvgDialog_19021_Content_25 = {
    Text = "Cẩn thận. Đường lui không dễ dàng như vậy đâu."
  },
  AvgDialog_19021_Content_26 = {
    Text = "Nhưng……"
  },
  AvgDialog_19021_Content_27 = {
    Text = "Có lẽ, điều này đúng như các bạn mong đợi."
  },
  AvgDialog_19021_Content_3 = {
    Text = "Xuất hiện trước mặt là căn phòng bao phủ bởi sương tím. \nThoáng chút quen thuộc, nhưng chi tiết đã có sự khác biệt tinh tế so với ký ức."
  },
  AvgDialog_19021_Content_4 = {
    Text = "Bạn hồi tưởng lại ký ức, cẩn thận phân biệt, cuối cùng đã nhận ra sự khác biệt…"
  },
  AvgDialog_19021_Content_5 = {
    Text = "Hàng hóa ở đây…"
  },
  AvgDialog_19021_Content_6 = {
    Text = "Ôi trời ơi, xem ra có khách không mời mà đến rồi!"
  },
  AvgDialog_19021_Content_7 = {
    Text = "Tôi đã cố ý để lại những dấu vết rõ ràng trên hồ sơ, vì ông không xóa đi, vậy tôi tin rằng ông cho phép tôi ghé thăm."
  },
  AvgDialog_19021_Content_8 = {
    Text = "Bạn rất thông minh, cũng đủ khiêm tốn. \nNói đi, cô gái nhỏ, tại sao bạn đến đây?"
  },
  AvgDialog_19021_Content_9 = {
    Text = "Không đúng, thay vào đó, lần này để tôi đoán xem……\nBạn hẳn không có ý định theo dõi tôi một cách kín đáo, nếu không bạn đã không cố tình để lại dấu hiệu rõ ràng như vậy."
  },
  AvgDialog_19025_Content_1 = {
    Text = "Bạn đuổi theo con quái vật màu đen cho đến khi nó chìm vào bóng tối sâu thẳm và biến mất."
  },
  AvgDialog_19025_Content_10 = {
    Text = "Herbert? Người <Blue:Herbert·Rosenthal> đó ư? Nhà nghiên cứu từng của Misaque, người đã bị truy nã vì giết thầy và bỏ trốn ——"
  },
  AvgDialog_19025_Content_11 = {
    Text = "Đúng vậy, và Hiệp hội Điêu khắc gia chính là do ông ấy thành lập—— hy vọng tay chân các người còn yên vị ở chỗ cũ."
  },
  AvgDialog_19025_Content_12 = {
    Text = "Ông ta không gây trở ngại gì cho chúng ta. \nTuy nhiên, có vẻ như ông ta đang tìm một cô bé khoảng tám, chín tuổi."
  },
  AvgDialog_19025_Content_13 = {
    Text = "Lại đang làm gì vậy… biết rồi, William sẽ sắp xếp để các điều tra viên khác truy tìm tung tích của Herbert. \nNhiệm vụ ưu tiên hàng đầu của các người vẫn là \"thảm họa\"."
  },
  AvgDialog_19025_Content_14 = {
    Text = "Dù sao, những quái vật bị rỗng rỗng này đã chứng minh sự tồn tại của \"thảm họa\". \nChúng không giống như sương mù ở Lentiennam hay những kẻ điên ở Đại học Misag, không phải nơi nào cũng dễ dàng bắt gặp."
  },
  AvgDialog_19025_Content_15 = {
    Text = "Vâng. Tuy nhiên… hiện tại chúng ta có một vấn đề cấp bách hơn."
  },
  AvgDialog_19025_Content_16 = {
    Text = "Lại có dị biến thể xuất hiện!?"
  },
  AvgDialog_19025_Content_17 = {
    Text = "Cũng không đến nỗi khẩn cấp — chỉ là vấn đề chỗ ở thôi. \nNếu được, tôi vẫn không định dùng tuyết để làm chăn đâu."
  },
  AvgDialog_19025_Content_18 = {
    Text = "<Italic:{Male=Anh, chị, Female=Chị},các người là khách từ nơi rất xa xôi đến phải không?>"
  },
  AvgDialog_19025_Content_19 = {
    Text = "Giọng nói non nớt đã phá vỡ cuộc trò chuyện của mọi người."
  },
  AvgDialog_19025_Content_2 = {
    Text = "Chạy trốn như chuột, vậy còn có thể gọi là<Yellow:chó địa ngục> không?"
  },
  AvgDialog_19025_Content_20 = {
    Text = "Ai người?"
  },
  AvgDialog_19025_Content_21 = {
    Text = "Tuyết bám trên tường phản chiếu ánh trăng sáng rực, ở giữa là cô gái trắng hơn cả ánh trăng."
  },
  AvgDialog_19025_Content_22 = {
    Text = "Nếu không tìm được nơi ở, <Blue:Bà Đào Đen Đá> sẵn lòng cho mượn phòng. \nCách đây một góc đường."
  },
  AvgDialog_19025_Content_23 = {
    Text = "Bạn đưa mắt ra hiệu cho Ramona, Ramona đáp lại bằng ánh mắt đầy tự tin."
  },
  AvgDialog_19025_Content_24 = {
    Text = "Váy trắng, phiếu khám bệnh, còn nhỏ. Đây là cô gái mà Herbert đang truy tìm, có lẽ cô ấy nắm giữ những đầu mối liên quan đến cuộc điều tra."
  },
  AvgDialog_19025_Content_25 = {
    Text = "Đi đi, các người còn chờ gì nữa? \nThích thật à? Muốn ở ngoài trời hú với sói cả đêm sao?"
  },
  AvgDialog_19025_Content_26 = {
    Text = "Muốn trải qua gió sương thì tôi sẵn sàng đồng hành, chỉ sợ các người với thân hình yếu đuối không chịu nổi."
  },
  AvgDialog_19025_Content_27 = {
    Text = "Lơ-tan vỗ nhẹ vào vai sau của Ramona, Ramona lộ ra biểu cảm khó chịu rõ rệt, nhưng không nói gì cả."
  },
  AvgDialog_19025_Content_28 = {
    Text = "Bà Daphne… nghe có vẻ là một người giàu có và từ thiện, phải không?"
  },
  AvgDialog_19025_Content_3 = {
    Text = "Nó dường như đã chạy trốn sau khi nhận ra chúng ta không hề sợ hãi nó. \nTìm lợi, tránh hại là bản năng của động vật, nhưng chưa từng nghe nói về thảm họa có hành vi tương tự."
  },
  AvgDialog_19025_Content_4 = {
    Text = "Và nó đã bị thương."
  },
  AvgDialog_19025_Content_5 = {
    Text = "Thật vậy, tôi ngửi thấy mùi máu."
