  AvgDialog_19025_Content_6 = {
    Text = "Máy thông tin phát ra tiếng kêu nhẹ nhàng."
  },
  AvgDialog_19025_Content_7 = {
    Text = "Cuối cùng cũng khôi phục rồi, đợi nhiệm vụ này kết thúc tôi sẽ cố gắng nâng cấp thiết bị liên lạc."
  },
  AvgDialog_19025_Content_8 = {
    Text = "Đóa? Vừa mới xảy ra chuyện gì vậy?"
  },
  AvgDialog_19025_Content_9 = {
    Text = "Gián đoạn thông tin, <Blue:Herbert> thường dùng thủ đoạn này. \nXem ra các người đã gặp hắn rồi, kẻ lập dị nuôi một con mèo hai đầu kia."
  },
  AvgDialog_19026_Content_1 = {
    Text = "Lord Dexter nói rằng tốt nhất là đừng chọc giận Bà Đào Đen Đá."
