  AvgDialog_19026_Content_3 = {
    Text = "Những con quái vật phía trước chắc là không nghĩ vậy đâu…"
  },
  AvgDialog_19028_Content_1 = {
    Text = "Hãy buông tôi ra, hãy buông tôi ra, người lớn bắt nạt trẻ con rồi ——"
  },
  AvgDialog_19028_Content_10 = {
