  },
  AvgDialog_19028_Content_18 = {
    Text = "Nữ giới, tự xưng là \"Bà Thủy Tiên\", nhìn có vẻ khoảng hai mươi tám tuổi, có mái tóc dài màu tro nhạt, buôn bán đồ cổ."
  },
  AvgDialog_19028_Content_19 = {
    Text = "Không sai, nhưng Erika nói rằng không tìm thấy tài liệu liên quan trong kho lưu trữ."
  },
  AvgDialog_19028_Content_2 = {
    Text = "Đầu tiên, các người đã phát động cuộc tấn công."
  },
  AvgDialog_19028_Content_20 = {
    Text = "Đó là vì trong các bản ghi chính thức, cô ấy <Blue:không hề tồn tại>."
