  AvgDialog_19028_Content_50 = {
    Text = "Vụ án liên quan đến chó địa ngục không phù hợp với phong cách của cô ấy, trong thị trấn chắc chắn còn có thế lực khác. \nMột khi đã dính vào tình huống phức tạp, các người không phải là đối thủ của cô ấy."
