  AvgDialog_19036_Content_66 = {
    Text = "Nhưng chúng tôi… cũng có thể trở thành gia đình của bạn."
  },
  AvgDialog_19036_Content_67 = {
    Text = "Gì gia đình không gia đình."
  },
  AvgDialog_19036_Content_68 = {
    Text = "Lơ-tan bước vào với dáng đi nhanh nhẹn, vẻ mặt đầy hăm dọa gia nhập cuộc đối thoại của bạn."
  },
  AvgDialog_19036_Content_69 = {
    Text = "Các cậu đến xem Lily mà không gọi tớ à? \nĐây chính là cách các cậu đối xử với đồng đội đã cùng sinh tử sao?"
