  AvgDialog_19036_Content_70 = {
    Text = "Lơ-tan bạn… không trở về hồ đen nữa sao?"
  },
  AvgDialog_19036_Content_71 = {
    Text = "Mỗi ngày chờ đợi cũng thật nhàm chán, đi theo các người làm nhiệm vụ ngoại vi, biết đâu lại gặp được đối thủ thú vị."
