  AvgDialog_19036_Content_73 = {
    Text = "Lơ-tan vỗ nhẹ vào vai mảnh mai của Lily."
  },
  AvgDialog_19036_Content_74 = {
    Text = "Nếu bạn không phiền, từ nay trở đi, bạn cũng có thể gọi tôi là mẹ."
