  AvgDialog_19036_Content_81 = {
    Text = "Có lơ-tan dẫn dắt, nếu Lily dành nhiều thời gian hơn để ở bên Ô Ryta và những người khác... chắc chắn sẽ nhanh chóng hòa nhập vào đây."
  },
  AvgDialog_19036_Content_82 = {
    Text = "May mà không phải ai cũng như cậu, đóa và William lúc nào cũng nhăn nhó, nếu không thì sống ở Misaque sẽ mệt lắm."
