  },
  AvgDialog_19036_Content_87 = {
    Text = "Trong quá trình điều tra sự kiện này, nhiều lần bạn trông có vẻ không khỏe."
  },
  AvgDialog_19036_Content_88 = {
    Text = "Rõ ràng nhất là lần bạn đọc nhật ký của Francis... \nPhản ứng của bạn khác hẳn với điều tôi dự đoán."
