  },
  AvgDialog_19036_Content_9 = {
    Text = "Mẹ Lisa, Lisa lại gửi thư rồi! Cô ấy nói rằng cô ấy và Bà Daphne đã rời khỏi sa mạc Vương quốc Lemvahi, đi trên một con tàu lớn băng qua đại dương đến Cộng hòa Agro mới nổi."
  },
  AvgDialog_19036_Content_90 = {
    Text = "Liên quan đến vấn đề này, tôi có một dự đoán."
