  AvgDialog_19036_Content_92 = {
    Text = "Bạn do dự một lúc, nhưng cuối cùng vẫn quyết định kể lại toàn bộ những gì đã thấy trong giấc mơ, không giấu diếm điều gì."
  },
  AvgDialog_19036_Content_93 = {
    Text = "<Yellow:thông cảm lực>trên người bạn lại thể hiện mạnh mẽ đến vậy……\nBạn sớm đã biết toàn bộ sự kiện, nên cuối cùng, bạn mới có thể kiên định như vậy."
