  },
  AvgDialog_19040_Content_13 = {Text = "Haiz……"},
  AvgDialog_19040_Content_14 = {
    Text = "Hai người nói chuyện rôm rả rồi đi xa, Ramona lúc này mới có cơ hội quan sát kỹ căn phòng nơi cô đã ẩn náu."
  },
  AvgDialog_19040_Content_2 = {
