  AvgDialog_19040_Content_6 = {
    Text = "Cô ấy cảm nhận được một chút tiếng gọi mờ ảo từ bên trong, tiếng gọi này khiến cô cảm thấy mình có một nghĩa vụ nhất định đối với đứa trẻ."
  },
  AvgDialog_19040_Content_7 = {
    Text = "Cũng chính lời gọi đó khiến cô cảm thấy giữa mình và Lily có một mối liên hệ nào đó, cô rất chắc chắn rằng Lily đang ở trong phòng ở phía đông nhất của viện dưỡng lão."
  },
  AvgDialog_19040_Content_8 = {
    Text = "Nếu đủ may mắn, cô ấy có thể lặng lẽ đưa Lily đi. Sau đó, thông báo cho Misaque cử người tiến hành tìm kiếm toàn diện tại viện dưỡng lão, làm rõ nguyên nhân khiến bạc tâm mất hiệu lực…"
  },
  AvgDialog_19040_Content_9 = {Text = "Ho, ho!"},
  AvgDialog_19041_Content_1 = {
