  },
  AvgDialog_19041_Content_21 = {
    Text = "Vị của nó hoàn toàn khác với những gì bạn tưởng tượng, mang một hương ngọt đậm đà, đi thẳng lên đỉnh đầu, như thể chạm tới linh hồn."
