  AvgDialog_19056_Content_18 = {
    Text = "Francis giật mình một chút, cười khẽ trong sự ngỡ ngàng."
  },
  AvgDialog_19056_Content_19 = {
    Text = "Các vị có lẽ đã hiểu lầm rồi.Lily gọi tôi là mẹ, nhưng tôi chưa chắc đã là mẹ đẻ của cô ấy."
  },
  AvgDialog_19056_Content_2 = {Text = "Mia!"},
  AvgDialog_19056_Content_20 = {
    Text = "Cô ấy là một cô bé mồ côi mà tôi đã giải cứu từ ổ trộm, những dị thường trên người cô ấy đều do những tên ác ôn ban đầu bắt cóc cô ấy gây ra."
  },
  AvgDialog_19056_Content_21 = {
    Text = "Còn Kum và Mia, chúng là những con mà Lily tìm thấy ở bên ngoài, cụ thể từ đâu tôi cũng không biết."
  },
  AvgDialog_19056_Content_22 = {
    Text = "Tất nhiên, người bình thường nhìn thấy vẻ ngoài của Kumm và Mia, nếu không sợ hãi thì ít nhất cũng sẽ cẩn trọng, giữ chúng tránh xa trẻ em."
  },
  AvgDialog_19056_Content_23 = {
    Text = "Nhưng khi còn trẻ, tôi đã có một \"cuộc phiêu lưu kỳ diệu\", được chứng kiến những kỳ quan hiếm có mà người thường chưa từng nghe nói."
  },
  AvgDialog_19056_Content_24 = {
    Text = "Vì vậy, mặc dù Kume trông có chút… khác thường, nhưng vì Lily thích nó, tôi đã giữ lại. Dù sao, đó cũng là người bạn mà Lily đã vất vả tìm được."
  },
  AvgDialog_19056_Content_25 = {
    Text = "Cậu bé này vốn đã có một sự xa cách sâu sắc với những người khác, tôi sao nỡ chia cắt họ chứ?"
  },
  AvgDialog_19056_Content_27 = {
    Text = "Nếu điều này vẫn chưa thể xóa tan nghi ngờ của các bạn, tôi có thể cùng mọi người kiểm tra lại một lần nữa. Chúng ta sẽ bắt đầu từ viện điều dưỡng, bao gồm cả văn phòng của tôi."
  },
  AvgDialog_19056_Content_28 = {
    Text = "Đừng lo, trước khi hội nghị thẩm tra diễn ra, tôi sẽ không đi đâu cả."
  },
  AvgDialog_19056_Content_3 = {
    Text = "Hống——"
  },
  AvgDialog_19056_Content_4 = {
    Text = "Tôi cứ nghĩ không biết tại sao không thấy bạn đâu, hóa ra bạn đã chạy đến đây. Nhanh lên, hãy đi với tôi ——"
  },
  AvgDialog_19056_Content_5 = {
    Text = "Khi nhận thấy các bạn, Francis dừng lời."
  },
  AvgDialog_19056_Content_6 = {
    Text = "Tôi hình như đã nhắc nhở hai người rồi, văn phòng không cho phép vào tham quan mà."
  },
  AvgDialog_19056_Content_7 = {
    Text = "Xin lỗi, nhưng \"cuộc tham quan\" có lẽ phải kết thúc ở đây."
  },
  AvgDialog_19056_Content_8 = {
    Text = "Theo Điều 81, Khoản A của \"Hiệp định\", mọi cá nhân, tổ chức hoặc cơ quan phải được <Blue:Hội đồng xem xét Hiệp định Misidia> phê duyệt. Nếu không, họ không được phép thực hiện bất kỳ thí nghiệm nào trên con người hoặc các cá thể chưa biết."
  },
  AvgDialog_19056_Content_9 = {
    Text = "Bây giờ chúng tôi nghi ngờ có hoạt động cải tạo cơ thể người trong viện dưỡng lão và đã liên hệ với <Blue:hội nghị thẩm tra>, họ sẽ phong tỏa viện dưỡng lão, mong bạn phối hợp."
  },
  AvgDialog_19057_Content_1 = {
    Text = "Từ góc bóng tối của cây cầu thép, vài con sinh vật dị hình lao ra, mang theo những tiếng rít làm kẻ thù khiếp sợ."
  },
  AvgDialog_19057_Content_10 = {
    Text = "Mỗi lần không thể thở được, cô đều khao khát mình có thể thở như một con cá."
  },
  AvgDialog_19057_Content_11 = {
    Text = "Để tìm danh y chữa trị căn bệnh hiếm gặp của cô, cha mẹ cô thường xuyên đi buôn bán ở xa. Cô yếu ớt không thể đi xa. Vì vậy, cha mẹ đã gửi cô vào một trung tâm điều dưỡng, nơi cô lớn lên với sự đồng hành của những quyển sách thơ."
  },
  AvgDialog_19057_Content_12 = {
    Text = "…Lúc đó, không ai nói với cô rằng đó không phải là một căn bệnh, mà là một hiện tượng bí ẩn mang tên \"rỗng rỗng\"."
  },
  AvgDialog_19057_Content_13 = {
    Text = "Nhà dưỡng lão nơi cô sống coi cô là người mang mầm bệnh đáng sợ, thu phí quản lý cao ngất, và người giao thức ăn cũng từ chối giao tiếp với cô."
  },
  AvgDialog_19057_Content_14 = {
    Text = "Càng ở lâu, cha mẹ cô càng không thể bên cạnh cô. \nNgoài thơ ca và đại dương, không có gì khác ngoài thơ ca và đại dương có thể dung nạp sự hiện diện của cô."
  },
  AvgDialog_19057_Content_15 = {
    Text = "Sau đó, cha mẹ cô qua đời trong một vụ đắm tàu, cô bị trục xuất khỏi viện điều dưỡng và chỉ còn cách chọn sống cô độc giữa lòng đại dương."
  },
  AvgDialog_19057_Content_16 = {
    Text = "Xin hỏi, nếu có một bác sĩ chuyên nghiên cứu về hiện tượng rỗng rỗng, khi cho cô ấy nơi nương náu và coi cô ấy như một người bình thường bị ảnh hưởng bởi hiện tượng huyền bí, cô ấy có nên thể hiện lòng biết ơn qua hành động không?"
  },
  AvgDialog_19057_Content_17 = {
    Text = "Bây giờ, đã đến lúc rồi."
  },
  AvgDialog_19057_Content_2 = {
    Text = "Ở sau sinh vật dị hình là một cô gái váy đen."
  },
  AvgDialog_19057_Content_3 = {
    Text = "Quý an.Rất vui được gặp lại quý vị."
  },
  AvgDialog_19057_Content_4 = {
    Text = "Mặc dù có chút thành thật xin lỗi, nhưng có thể xin mọi người tạm thời rời khỏi Lai Ne không?"
  },
  AvgDialog_19057_Content_5 = {
    Text = "Ninh Phi Nga, bạn phụ trách chăm sóc bệnh nhân, không thể không biết về hành vi của Francis ở viện dưỡng lão. \nDù vậy, bạn vẫn chọn cùng tham gia vào việc xấu sao?"
