  AvgDialog_19057_Content_6 = {
    Text = "……Tôi sẽ kể cho các bạn một câu chuyện."
  },
  AvgDialog_19057_Content_7 = {
    Text = "Xưa kia, có một cô gái, cô ấy ốm yếu, thường xuyên bệnh tật, sợ hãi con người, chỉ quen thuộc với hơi thở của biển cả."
  },
  AvgDialog_19057_Content_8 = {
