  AvgDialog_19058_Content_13 = {
    Text = "Nhà dưỡng lão bên trong toả ra ánh sáng sâu thẳm, tối tăm và quái dị, tường và sàn nhà nứt nẻ thành những vết rách, sau những khe hở là hỗn loạn sâu thẳm và ánh sao lấp lánh."
  },
  AvgDialog_19058_Content_14 = {
    Text = "Chiều đã bị xâm nhập. \nPhép thuật mà Francis thực hiện với không gian và thời gian… đã thu hút <Yellow:sự chú ý>."
