  AvgDialog_19058_Content_5 = {
    Text = "Nghiên cứu của Francis tập trung vào phương pháp chữa trị sự rỗng rỗng, điều này không phù hợp với lý tưởng của Herbert, thậm chí có phần xung đột."
  },
  AvgDialog_19058_Content_6 = {
