  },
  AvgDialog_19059_Content_5 = {
    Text = "Nhưng tôi cũng không thể trách những bệnh nhân đáng thương đó. Họ phần lớn bị gia đình bỏ rơi ở đây, thường xuyên bất ổn về cảm xúc vào ban đêm, khóc lén hoặc bệnh tình tái phát."
  },
  AvgDialog_19059_Content_6 = {
    Text = "Vừa nói xong, Francis liền đẩy cửa phòng bệnh trước mặt."
