  AvgDialog_19059_Content_9 = {
    Text = "Chúng tôi không sao, nhưng Tiểu Mya bên kia đang ồn ào đòi gặp hiệu trưởng, đã khóc lâu rồi, ngài hãy qua xem thử."
  },
  AvgDialog_19060_Content_1 = {Text = "Đây là!"},
  AvgDialog_19060_Content_2 = {
    Text = "Từ góc phòng, một con quái vật đen kịt ló ra."
