  AvgDialog_19062_Content_10 = {
    Text = "Dưới sự coi trọng, nhưng nghiên cứu khoa học không phải là chuyện đùa với dao kiếm, mỗi nhát đều có thể gây thương tích."
  },
  AvgDialog_19062_Content_11 = {
    Text = "Tôi phải nhắc bạn rằng, nếu bây giờ để những nhà nghiên cứu lớn tuổi trong bộ phận nghiên cứu xử lý, dù họ mất thêm mười tám tiếng, họ cũng sẽ không tìm ra nguyên nhân của sự cố."
  },
  AvgDialog_19062_Content_12 = {
    Text = "Kéramona đã ra ngoài rồi, chỉ cần tìm kiếm sơ qua căn phòng, không tốn quá nhiều thời gian như vậy…"
  },
  AvgDialog_19062_Content_13 = {
