  AvgDialog_19066_Content_12 = {
    Text = "Cô ấy như thể đã nhìn thấy thứ gì kinh khủng nhất trên thế gian, vung tay ném đồng hồ bỏ túi ra, lùi lại hai bước, đầu gối run rẩy rồi quỵ ngã xuống đất."
