  AvgDialog_19066_Content_15 = {
    Text = "<BigShake:không thể, không thể, điều này tuyệt đối không thể, tôi không tin!>"
  },
  AvgDialog_19066_Content_16 = {
    Text = "Ramona bước lên, nhặt chiếc đồng hồ bỏ túi kia. \nCô ấy bấm mở chốt kim loại, sau đó lặng lẽ đưa cho bạn."
