  },
  AvgDialog_19067_Content_9 = {
    Text = "Cô ấy lăn người xuống đất, còn Kum thì vươn người duỗi lưng."
  },
  AvgDialog_19068_Content_1 = {
    Text = "Lily vẫn đang điều khiển những bọc dịch đen để đối phó với chó địa ngục, nhưng hành động của cô đã không còn nhanh nhẹn như trước."
