  AvgDialog_19070_Content_1 = {Text = "28 ngày"},
  AvgDialog_19070_Content_10 = {
    Text = "Kum gật đầu, ra hiệu cho các người cưỡi lên lưng nó. \nThấy các người đã ngồi vững, nó hét lớn một tiếng và lao thẳng đến viện điều dưỡng."
  },
  AvgDialog_19070_Content_2 = {
    Text = "Thế nào, đã nói xong lời thì thầm chưa?"
  },
  AvgDialog_19070_Content_3 = {
    Text = "Bạn phản xạ \"bụp!\" đóng máy tính xách tay lại, lưng lạnh buốt, như thể vừa thoát khỏi một nơi đóng băng suốt ngàn năm."
  },
  AvgDialog_19070_Content_4 = {
    Text = "Lời thì thầm nào……\nĐợi đã, chỉ số Nos của tôi hoàn toàn không có vấn đề gì đúng không?"
  },
  AvgDialog_19070_Content_5 = {
    Text = "Không kiểm tra thì làm sao biết có vấn đề hay không, thấy bạn tràn đầy năng lượng như vừa mới được thức tỉnh, tôi thực sự rất vui."
  },
  AvgDialog_19070_Content_6 = {
    Text = "Rối loạn của Rai đã vượt quá dự kiến, chỉ sợ rằng chúng ta không còn nhiều thời gian để trì hoãn, hãy xuất phát ngay đi."
  },
  AvgDialog_19070_Content_7 = {
    Text = "Đóa lấy từ ba lô ra vài chiếc kính đơn kim loại có hình dạng kỳ lạ và một số ống nghiệm.\n Dung dịch trong ống nghiệm tỏa ra ánh kim màu vàng tối."
  },
  AvgDialog_19070_Content_8 = {
    Text = "Cầm lấy, khi cần đeo thì hãy đeo."
  },
  AvgDialog_19070_Content_9 = {
    Text = "Cậu bé, cậu có muốn theo chúng tôi vào không?"
  },
  AvgDialog_19071_Content_1 = {
    Text = "Sông bí ẩn"
  },
  AvgDialog_19071_Content_10 = {
    Text = "Đôi mắt đen phát ra những tiếng lạo xạo kỳ quái, đôi môi của cô gái mở ra khép lại, những lời thì thầm hòa quyện cùng âm thanh lạ lùng từ đôi mắt tạo nên một bản giao hưởng u uất và nặng nề."
  },
  AvgDialog_19071_Content_12 = {
    Text = "Quả cầu màu đen lao về phía tín đồ, đám đông bắt đầu xao động."
  },
  AvgDialog_19071_Content_13 = {
    Text = "Bạn và Đại tá Bertrand lợi dụng thời cơ trong hỗn loạn, chui vào con đường nhỏ."
  },
  AvgDialog_19071_Content_15 = {
    Text = "……………"
  },
  AvgDialog_19071_Content_16 = {
    Text = "Đi trong bóng tối không biết bao lâu, phía sau không xa luôn có tiếng rít, tiếng kêu quái dị, tiếng thở hổn hển, tiếng thì thầm và tiếng lẩm bẩm vang lên."
  },
  AvgDialog_19071_Content_17 = {
    Text = "Nhanh lên, đạp vào vai tôi, bạn hãy trèo lên trước!"
  },
  AvgDialog_19071_Content_18 = {
    Text = "Trong sự hỗ trợ của Trung tá Bertrand, bạn đã chui ra khỏi đường hầm hẹp trước. \nXuất hiện trước mắt là một vùng tuyết trắng mênh mông khiến người ta ngỡ ngàng."
  },
  AvgDialog_19071_Content_19 = {
    Text = "Chờ một chút, tôi bị loá mắt vì tuyết……Tôi sẽ đến kéo bạn ngay……"
  },
  AvgDialog_19071_Content_2 = {
    Text = "Nhanh lên, lối ra đang ở ngay phía trước."
  },
  AvgDialog_19071_Content_20 = {
    Text = "Không sao, tôi có thể tự.."
  },
  AvgDialog_19071_Content_21 = {
    Text = "Lời của Trung tá Bertrand chưa kịp dứt, bỗng nhiên, trên khuôn mặt ông hiện rõ vẻ kinh hoàng."
  },
  AvgDialog_19071_Content_22 = {
    Text = "Từ khe hở giữa anh ta và lối ra của đường hầm, rất nhiều nhánh dạng lỏng, dày đặc và xoắn lại chui ra."
  },
  AvgDialog_19071_Content_23 = {
    Text = "Vật đó dường như mang ý chí riêng, siết chặt lấy thân thể của Đại tá Bertrand."
  },
  AvgDialog_19071_Content_24 = {
    Text = "Bertran duỗi năm ngón tay ra, nắm chặt mặt đất, nhưng vô ích. Chỉ có mặt đất phủ đầy tuyết không có điểm tựa nào, anh ta bị kéo xuống trong mỗi lần hít thở."
  },
  AvgDialog_19071_Content_25 = {
    Text = "Tiếp theo, màng nhĩ nhận được âm thanh khiến thần kinh căng thẳng…"
  },
  AvgDialog_19071_Content_26 = {
    Text = "Co giật, nhai, va chạm xương… \n Ngay cả âm thanh của dịch tiêu hóa tác động lên chất hữu cơ cũng trở nên rõ ràng đến thế."
  },
  AvgDialog_19071_Content_27 = {
    Text = "…Sau vài giây hồi hộp, mọi thứ trở lại yên tĩnh. \nChỉ có gió thổi làm tuyết trên cành cây xào xạc rơi xuống mặt đất tuyết."
  },
  AvgDialog_19071_Content_28 = {
    Text = "Cảm giác buồn nôn muộn màng từ bụng dâng lên ngực, bạn cúi xuống đất tuyết và nôn khan."
  },
  AvgDialog_19071_Content_29 = {Text = "Ọe……"},
  AvgDialog_19071_Content_3 = {
    Text = "Bạn nhìn về nơi Ramona chỉ, ánh sáng trắng chói chang che khuất tầm nhìn."
  },
  AvgDialog_19071_Content_30 = {
    Text = "Nước mắt không thể kiểm soát tràn ra từ hốc mắt, bạn không phân biệt được đó là nỗi buồn hay nỗi sợ hãi trong lòng ngực."
  },
  AvgDialog_19071_Content_31 = {
    Text = "Bạn sờ vào túi tìm đồng hồ bỏ túi, hy vọng nó sẽ mang lại cho bạn chút an ủi. \nNhưng nơi đó trống không, không có gì cả."
  },
  AvgDialog_19071_Content_32 = {
    Text = "……thì ra là bạn không lấy được gì cả."
  },
  AvgDialog_19071_Content_33 = {
    Text = "Thân thể bạn chìm xuống, bàn tay lạnh giá đặt lên vai bạn."
  },
  AvgDialog_19071_Content_34 = {
    Text = "Cảnh báo, chủ nhân! Xin hãy ra lệnh cho tôi."
  },
  AvgDialog_19071_Content_36 = {
    Text = "……………"
  },
  AvgDialog_19071_Content_37 = {
    Text = "Sau vài ngày hành trình, những quái vật và tín đồ đuổi theo các người đã biến mất trong đồng tuyết. \nBạn và cô gái đã gạt bớt đi một chút tuyết, cùng dựa vào nhau, ngồi bên đống lửa để nghỉ ngơi."
  },
  AvgDialog_19071_Content_38 = {
    Text = "Cô ấy thỉnh thoảng sẽ rời bỏ bạn, rồi mang về những miếng thịt máu không biết là của sinh vật gì."
  },
  AvgDialog_19071_Content_39 = {
    Text = "Bạn cố ý không truy cứu, mà nhóm lửa nướng chín sau đó, chặn khứu giác và vị giác để nhai nhỏ và nuốt vào bụng protein quý giá."
  },
  AvgDialog_19071_Content_4 = {
    Text = "Trực quan biến mất trong ảo giác màu trắng xù xì, như bị mắc chứng mù tuyết."
  },
  AvgDialog_19071_Content_40 = {
    Text = "Cô gái dường như không cần ăn, nhưng nếu bạn đưa thức ăn cho cô ấy, cô ấy cũng sẽ ăn ngấu nghiến."
  },
  AvgDialog_19071_Content_41 = {
    Text = "Bạn có tên không?"
  },
  AvgDialog_19071_Content_42 = {
    Text = "Cô ấy vừa nhai miếng thịt nướng đầy nước, vừa lắc đầu."
  },
  AvgDialog_19071_Content_43 = {
    Text = "Vậy… người thân thì sao? Bạn có biết bố mẹ mình đang ở đâu không?"
  },
  AvgDialog_19071_Content_45 = {
    Text = "Cô ấy nhìn bạn, nhìn ngọn núi tuyết xa xôi, lại ngẩng đầu nhìn bầu trời vô tận rồi lắc đầu."
  },
  AvgDialog_19071_Content_46 = {
    Text = "… nói chung, vẫn nên có một cái tên mới được."
  },
  AvgDialog_19071_Content_47 = {
    Text = "Gọi bạn là <Blue:Lily>, được không?"
  },
  AvgDialog_19071_Content_48 = {
    Text = "Chủ nhân bảo gọi thế nào thì cứ gọi như vậy."
  },
  AvgDialog_19071_Content_49 = {
    Text = "Tôi chẳng phải là chủ nhân gì cả…"
  },
  AvgDialog_19071_Content_5 = {
    Text = "Trong hỗn loạn vặn vẹo, ý thức bị kéo ra khỏi thân thể, giác quan được gửi đến một chiều không gian cực kỳ xa xôi và lạnh lẽo. \nCái <Yellow:khung cảnh trong mơ> ấy lại một lần nữa tìm đến bạn……"
  },
  AvgDialog_19071_Content_50 = {
    Text = "Chủ nhân, cẩn thận. Có thứ gì đó đang đuổi theo."
  },
  AvgDialog_19071_Content_51 = {
    Text = "Sao thế?! Chúng ta rõ ràng đã gần rời khỏi vùng tuyết nguyên rồi mà…"
  },
  AvgDialog_19071_Content_52 = {
    Text = "Đau nhói, ý thức bị kéo và nén. \n<Yellow:giấc mơ> đang từ chối bạn, cố gắng đẩy bạn ra khỏi thế giới trắng. \nNhưng……"
  },
  AvgDialog_19071_Content_53 = {
    Text = "Không được… không thể để họ (nữ) bị đuổi kịp… ngay cả trong giấc mơ của tôi!"
  },
  AvgDialog_19071_Content_7 = {
    Text = "Những gì đã xảy ra ở Elworth đã vượt xa những gì <Yellow:bạn> biết là lẽ thường, nhưng bây giờ bạn không có thời gian để cảm thấy bối rối, còn có những việc quan trọng hơn đang chờ bạn hoàn thành."
  },
  AvgDialog_19071_Content_8 = {
    Text = "Giúp tôi, chặn họ lại."
  },
  AvgDialog_19071_Content_9 = {
    Text = "Thưa chủ nhân, được."
  },
  AvgDialog_19072_Content_1 = {
    Text = "Có một chiếc hộp nhỏ bị khóa chặt trên giá sách…"
  },
  AvgDialog_19072_Content_2 = {
    Text = "Phía dưới bức tranh treo tường có chìa khóa……"
  },
  AvgDialog_19073_Content_1 = {
    Text = "Tiếng gầm gừ dần bị bóng tối nuốt chửng, chất lỏng đen bám lại trên hành lang cũng nhanh chóng tan biến không dấu vết như nước sôi."
  },
  AvgDialog_19073_Content_10 = {
    Text = "Những lời này không cần vội vàng nói. \nMời của tôi vừa rồi, cô nghĩ sao về lời mời của tôi, cô đóa?"
  },
  AvgDialog_19073_Content_11 = {
    Text = "Dù sao bạn cũng không quan tâm đến sự tồn vong của loài người, đúng không?"
  },
  AvgDialog_19073_Content_12 = {
    Text = "Thật vậy!"
  },
  AvgDialog_19073_Content_13 = {Text = "Đóa?"},
  AvgDialog_19073_Content_14 = {
    Text = "Khác với họ, tôi đã từ bỏ thân thể con người từ lâu, sự tồn tại hay diệt vong của những người bình thường vốn dĩ không liên quan đến tôi."
  },
  AvgDialog_19073_Content_15 = {
    Text = "Là một nhà nghiên cứu theo đuổi công nghệ tối tân nhất, ai lại không muốn từ bỏ những quy tắc đạo đức con người vốn không nên trói buộc chúng ta, để thực hiện những thí nghiệm táo bạo nhất?"
  },
  AvgDialog_19073_Content_16 = {
    Text = "Tiếc rằng.."
  },
  AvgDialog_19073_Content_17 = {
    Text = "So với những kẻ chỉ biết tìm lợi tránh hại như trùng cỏ, tôi vẫn ngưỡng mộ hơn sự can đảm của nhóm này khi dám làm điều tưởng chừng không thể."
  },
  AvgDialog_19073_Content_18 = {
    Text = "Thôi, nói chuyện đến đây thôi. \nNếu để cậu kéo dài thêm, e rằng Francis sẽ dẫn LILY chạy sang bên kia đại dương mất."
  },
  AvgDialog_19073_Content_19 = {
    Text = "Thật không hổ là \"Não của Misaque\", không có gì có thể qua mắt được ông."
  },
  AvgDialog_19073_Content_2 = {
    Text = "Hiệp hội Điêu khắc gia kiểm soát <Yellow:mẫu thí nghiệm>, thật rẻ và hữu dụng."
  },
  AvgDialog_19073_Content_20 = {
    Text = "Herbert vỗ tay, khoảng mười mấy cánh cửa sau lưng ông mở ra theo tiếng vỗ."
  },
  AvgDialog_19073_Content_21 = {
    Text = "Sát ý lạnh buốt lan tỏa trong bóng tối, hành lang âm u và chật hẹp vang vọng những tiếng gào rú kỳ quái, dính chặt vào không khí."
  },
  AvgDialog_19073_Content_22 = {
    Text = "Ramona, %player%!"
  },
  AvgDialog_19073_Content_23 = {
    Text = "Chúng tôi đang ở đây!"
  },
  AvgDialog_19073_Content_24 = {
    Text = "Vị bạn già này giao cho tôi, các người đi chặn Francis lại."
  },
  AvgDialog_19073_Content_25 = {
    Text = "Chiếc kính chúng tôi vừa đưa bạn, đeo vào sẽ nhìn thấy \"<Yellow:đường dẫn>\" tới các chiều không gian khác."
  },
  AvgDialog_19073_Content_26 = {
    Text = "Không có trường hợp đặc biệt, tuyệt đối đừng tháo ra. Đau đầu là hiện tượng bình thường, nếu thực sự không chịu đựng nổi, thì hãy uống một ống thuốc."
  },
  AvgDialog_19073_Content_27 = {
    Text = "Nhưng chỉ một mình bạn——"
  },
  AvgDialog_19073_Content_28 = {Text = "Đi!"},
  AvgDialog_19073_Content_29 = {
    Text = "Đại học Misag và Hiệp hội Điêu khắc gia đã đối đầu nhau suốt bao nhiêu năm, nếu hắn có khả năng giải quyết chúng ta thì đã chẳng đợi đến tận bây giờ."
  },
  AvgDialog_19073_Content_3 = {
    Text = "Hy vọng bạn đừng nảy sinh ý nghĩ gì sẽ bị giam cầm dưới lòng đất."
  },
  AvgDialog_19073_Content_30 = {
    Text = "Nguyện Chìa Khóa Bạc soi sáng con đường phía trước."
  },
  AvgDialog_19073_Content_32 = {
    Text = "Nguyện chìa khóa bạc dẫn đường cho chúng ta."
  },
  AvgDialog_19073_Content_33 = {
    Text = "Bạn đeo kính đơn kim loại và cùng Ramona quay người hướng về phía đông cuối hành lang để phá vây."
  },
  AvgDialog_19073_Content_34 = {
    Text = "Trong tầm mắt, hơn mười sinh vật thí nghiệm được Herbert triệu hồi đã bao vây chặt đóa, mỗi con đều thèm khát và sẵn sàng lao vào hành động."
  },
  AvgDialog_19073_Content_35 = {
    Text = "Đừng nhìn nữa! đóa nói cô ấy có thể giải quyết được."
  },
  AvgDialog_19073_Content_36 = {
    Text = "Tin tưởng cô ấy và tập trung vào nhiệm vụ của chúng ta!"
  },
  AvgDialog_19073_Content_4 = {
    Text = "Dù có động cũng không lạ chứ. \nBởi vì, lập trường của chúng ta cũng không ở bên người thường."
  },
  AvgDialog_19073_Content_5 = {
    Text = "Vì bạn có ý tưởng như vậy, tại sao không thử nghĩ tới việc hợp tác với chúng tôi?"
  },
  AvgDialog_19073_Content_6 = {
    Text = "Công nghệ của <Yellow:Ale Meses> đã khiến tôi mê mẩn từ lâu."
  },
  AvgDialog_19073_Content_7 = {
    Text = "Thật hiếm khi thấy anh xuất hiện trực tiếp, Herbert. \nTôi tưởng anh ghét nhất là phải ra mặt."
  },
  AvgDialog_19073_Content_8 = {
    Text = "Ôi, dù sao đi nữa, Hiệp hội Điêu khắc gia đã đầu tư không ít vào \"thiên tài\" này. Nếu bị các người bắt hết, nỗ lực của chúng tôi sẽ trở thành vô ích."
  },
  AvgDialog_19073_Content_9 = {
    Text = "Bạn vẫn quá tự tin đấy, nỗ lực của các bạn từ đầu đã không đi theo hướng khác."
  },
  AvgDialog_19074_Content_1 = {
    Text = "Ô cửa bí ẩn"
  },
  AvgDialog_19074_Content_10 = {
    Text = "Nếu không, làm sao chúng ta có thể trắng tay?"
  },
  AvgDialog_19074_Content_11 = {
    Text = "Ánh sáng từ xa…"
  },
  AvgDialog_19074_Content_12 = {
    Text = "Là nỗi ám ảnh sâu thẳm nhất của chủ nhân không gian ý thức, điều không thể quên."
  },
  AvgDialog_19074_Content_13 = {
    Text = "Có vẻ như là một mặt số."
  },
  AvgDialog_19074_Content_14 = {
    Text = "Không lẽ gã muốn trở thành chủ nhân của thời gian?"
  },
  AvgDialog_19074_Content_15 = {
    Text = "Cô ấy cần rất rất nhiều thời gian để hoàn thành mục tiêu của mình, vì vậy mới tự giam mình trong căn phòng đó."
  },
  AvgDialog_19074_Content_16 = {
    Text = "Tự giam mình?"
  },
  AvgDialog_19074_Content_17 = {
    Text = "Vâng, giá của việc du hành giữa các chiều không phải là điều mà người bình thường có thể chịu đựng được."
  },
  AvgDialog_19074_Content_18 = {
    Text = "Mỗi lần cô ấy rời khỏi phòng, có lẽ đều phải đối mặt với nguy cơ cực cao ——"
  },
  AvgDialog_19074_Content_19 = {
    Text = "Cẩn thận!"
  },
  AvgDialog_19074_Content_2 = {
    Text = "Bạn và Ramona chạy dọc theo hành lang về phía đông, không lâu sau, một bức tường xuất hiện trước mặt các bạn."
  },
  AvgDialog_19074_Content_20 = {
    Text = "Quái vật hình tam giác hỗn loạn nổi lên từ bùn đen dưới chân."
  },
  AvgDialog_19074_Content_21 = {
    Text = "Hãy rời khỏi đây!"
  },
  AvgDialog_19074_Content_3 = {
    Text = "Bức tường trắng cao treo một bức tranh vẽ tay đơn giản của trẻ em, mẹ đang ôm con chơi đùa —— \n còn nơi từng là của đứa trẻ, chỉ còn lại chất dịch đen."
  },
  AvgDialog_19074_Content_4 = {
    Text = "Không còn đường?"
  },
  AvgDialog_19074_Content_5 = {
    Text = "Không. . . tin vào trực giác của bạn. \n đi vào đi."
  },
  AvgDialog_19074_Content_6 = {
    Text = "Trong khoảnh khắc bước qua bức tường, bạn như thấy hình vẽ trên tường động một chút —— \nHình dáng cô gái xuất hiện trong tích tắc, rồi lại chìm vào bóng tối."
  },
  AvgDialog_19074_Content_7 = {
    Text = "Không gian này.."
  },
  AvgDialog_19074_Content_8 = {
    Text = "Nếu tôi không đoán sai, đây là đường dẫn hình thành ý thức của Francis."
  },
  AvgDialog_19074_Content_9 = {
    Text = "Ẩn thật kỹ nhỉ."
  },
  AvgDialog_19075_Content_1 = {Text = "Phòng"},
  AvgDialog_19075_Content_10 = {
    Text = "Francis đứng trước cửa sổ, hai tay đan sau lưng, nhìn xa xăm."
  },
  AvgDialog_19075_Content_11 = {
    Text = "Bạn đã phụ lòng tốt bụng của Lily. \nTrước khi Herbert can thiệp, chúng ta lẽ ra đã có thể chia tay nhau tại đây."
  },
  AvgDialog_19075_Content_12 = {
    Text = "Chúng tôi sẽ không ngồi yên trước bạo hành của bạn."
  },
  AvgDialog_19075_Content_13 = {
    Text = "Bạo hành… các người nhìn tôi như vậy sao? \n một quái vật, một kẻ điên, một tội phạm?"
  },
  AvgDialog_19075_Content_14 = {
    Text = "Tôi khác Herbert, tôi chưa bao giờ chủ động làm tổn thương bất kỳ ai."
  },
  AvgDialog_19075_Content_15 = {
    Text = "Trong mắt bạn có thể là như vậy, nhưng những con người đã bị dị hóa… có lẽ vẫn còn những người sẵn lòng chấp nhận họ, quan tâm đến họ."
  },
  AvgDialog_19075_Content_16 = {
    Text = "Tôi biết các bạn đều là những người tốt và chính trực, nhưng các bạn vẫn còn trẻ."
  },
  AvgDialog_19075_Content_17 = {
    Text = "Tôi từng tiếp nhận những người từng phạm tội nghiêm trọng đã mãn hạn tù, những người xung quanh họ sau khi biết về quá khứ của họ đều tránh xa… dù họ đã ăn năn sâu sắc."
  },
  AvgDialog_19075_Content_18 = {
    Text = "Con người là sinh vật được hình thành bởi những trải nghiệm. \nSau một số trải nghiệm, họ không còn giữ được bản chất con người và không nên được đối xử như con người."
  },
  AvgDialog_19075_Content_19 = {
    Text = "Đây không phải là ý kiến cá nhân của tôi. Nhận thức của thế giới về họ đã thay đổi."
  },
  AvgDialog_19075_Content_2 = {
    Text = "Đúng phòng này, Lily và Francis… có lẽ đang ở bên trong."
  },
  AvgDialog_19075_Content_20 = {
    Text = "Dù bạn không coi những nạn nhân của sự rỗng rỗng là con người, nhưng những người thân và bạn bè đã đưa họ đến viện dưỡng lão thì sao?"
  },
  AvgDialog_19075_Content_21 = {
    Text = "Họ không ai thoát khỏi bị chó địa ngục nuốt chửng, chắc chắn là do cậu giở trò rồi. \nHọ đều là những con người thuần khiết một trăm phần trăm, hoàn toàn không pha tạp."
  },
  AvgDialog_19075_Content_22 = {
    Text = "Những người chỉ vì đối phương bị bệnh, hoặc già yếu và suy kiệt, mà bỏ rơi người thân của mình ở viện dưỡng lão xa xôi và cô lập này, họ có đáng bị trừng phạt không?"
  },
  AvgDialog_19075_Content_23 = {
    Text = "Điều này chưa đến mức phải chết, ngươi không có tư cách xét xử họ."
  },
  AvgDialog_19075_Content_24 = {
    Text = "Tôi không có tư cách để xét xử họ……\nVậy các người có tư cách để xét xử tôi không?"
  },
  AvgDialog_19075_Content_25 = {
    Text = "Bạn có biết đây là đâu không? Đây là phòng của con gái tôi. \n Thời gian ở đây, mãi mãi dừng lại vào buổi hoàng hôn hôm cô ấy biến mất."
  },
  AvgDialog_19075_Content_26 = {
    Text = "Tôi đã dùng mọi cách để giữ cô ấy lại, thậm chí sẵn sàng bán linh hồn cho quỷ dữ. \nThế nhưng… ngay cả quỷ dữ cũng không xuất hiện, cô ấy vẫn rời bỏ tôi."
  },
  AvgDialog_19075_Content_27 = {
    Text = "Tôi đã đặt tên con gái của tôi là <Blue:Lily>, nhưng cô ấy rốt cuộc không phải con gái của tôi. \nCô ấy chỉ là một sinh vật có tuổi tương đương con gái tôi."
  },
  AvgDialog_19075_Content_28 = {
    Text = "Trên bàn phẫu thuật, vết thương lớn trên ngực Lily đang từ từ lành lại, đôi mắt trống rỗng cũng dần dần phục hồi màu sắc."
  },
  AvgDialog_19075_Content_29 = {
    Text = "Cô ấy là một đối tượng thí nghiệm hoàn hảo, bất kể tạo ra bao nhiêu vết thương cũng sẽ tiếp tục lành lại, và phẫu thuật sẽ không bị buộc phải dừng lại do phản ứng với cơn đau."
  },
  AvgDialog_19075_Content_3 = {
    Text = "Chúng ta đã rời khỏi đường dẫn chiều rồi, bạn cảm thấy thế nào hiện tại, còn có cảm giác choáng váng hoặc muốn nôn không?"
  },
  AvgDialog_19075_Content_30 = {
    Text = "Nhưng tôi chỉ muốn có con gái của mình! Một cô bé bình thường biết khóc, biết cười, biết tìm đến tôi để nũng nịu khi đau đớn!"
  },
  AvgDialog_19075_Content_31 = {
    Text = "Những kẻ đó…… những kẻ ngay cả người thân bên cạnh cũng có thể bỏ rơi…… đã sớm mất hết nhân tính rồi!"
  },
  AvgDialog_19075_Content_32 = {
    Text = "Người đã mất nhân tính, còn có thể được gọi là con người nữa không? \n Những kẻ đã trở thành quái vật như vậy, bị làm mồi cho chó địa ngục, chẳng phải đáng ra như thế sao?"
  },
  AvgDialog_19075_Content_33 = {
    Text = "Không thể lý giải."
  },
  AvgDialog_19075_Content_34 = {
    Text = "Thật hiếm khi chúng ta đồng ý với nhau."
  },
  AvgDialog_19075_Content_35 = {
    Text = "Francis bước lên, nhẹ nhàng vuốt ve khuôn mặt trắng trẻo và mềm mại của Lily. Sự dịu dàng ấy tạo nên sự đối lập rõ rệt với những lời lẽ cay nghiệt mà cô vừa thốt ra."
  },
  AvgDialog_19075_Content_36 = {
    Text = "Tôi biết các bạn sẽ không hiểu."
  },
  AvgDialog_19075_Content_37 = {
    Text = "Cô ấy thì thầm một cách đầy u sầu, giọng nói hầu như không thể nghe thấy."
  },
  AvgDialog_19075_Content_38 = {
    Text = "Khi lời thì thầm giữa kẽ răng lặp lại lần thứ ba, các bạn cuối cùng đã phân biệt được âm điệu đó——"
  },
  AvgDialog_19075_Content_4 = {
    Text = "Đã tốt hơn nhiều, dù có bất kỳ sự khó chịu đột ngột nào, tôi cũng sẽ cố gắng chống chọi."
  },
  AvgDialog_19075_Content_42 = {
    Text = "Quái vật đang ngủ say đã thức tỉnh, Lily vốn đang nằm phẳng dậy với động tác cứng ngắc, trong mắt lóe lên ánh sáng xanh lục kỳ dị…"
  },
  AvgDialog_19075_Content_43 = {
    Text = "<Change>Trở về tổ gốc đi"
  },
  AvgDialog_19075_Content_44 = {
    Text = "<Change>Hãy quay trở lại thế giới vĩnh cửu"
  },
  AvgDialog_19075_Content_45 = {
    Text = "<Change>Trở về vòng tay của mẹ đi"
  },
  AvgDialog_19075_Content_46 = {
    Text = "<Change>Vì mẹ, tiêu diệt chúng"
  },
  AvgDialog_19075_Content_47 = {Text = "Sī——"},
  AvgDialog_19075_Content_48 = {
    Text = "Ramona, hãy tìm cách thức tỉnh Lily!"
  },
  AvgDialog_19075_Content_49 = {Text = "Rõ ràng!"},
  AvgDialog_19075_Content_5 = {
    Text = "Hít một hơi thật sâu, bạn đẩy cánh cửa đang nhỏ giọt chất lỏng đặc quánh, đến nơi tận cùng."
  },
  AvgDialog_19075_Content_6 = {
    Text = "Đập vào mắt là cảnh mặt trời lặn vĩnh cửu không bao giờ tắt, cùng với căn phòng của cô gái mang lại cảm giác ấm áp và thân thiện."
  },
  AvgDialog_19075_Content_7 = {
    Text = "Búp bê trên đầu giường, chiếc váy màu hồng trên giá treo, rèm giường có viền hoa...\nTất cả đều không phù hợp với viện dưỡng lão u ám và lạnh lẽo."
  },
  AvgDialog_19075_Content_8 = {
    Text = "Giường phẫu thuật ở giữa có một hình dáng nhỏ bé mà các bạn đã quen thuộc, ngực bị cắt một lỗ lớn, im lặng, dường như không còn sự sống."
  },
  AvgDialog_19075_Content_9 = {Text = "Lily!"},
  AvgDialog_19076_Content_1 = {
    Text = "Miệng kẻ điên"
  },
  AvgDialog_19076_Content_10 = {
    Text = "Đáp lại cô chỉ có tiếng \"ừ\" nhẹ của Ramona, sau đó mọi âm thanh lại như bị hút vào khoảng không gian trống rỗng và trở nên im lặng."
  },
  AvgDialog_19076_Content_11 = {
    Text = "Lily, sắp được gặp mẹ rồi, bạn có vui không?"
  },
  AvgDialog_19076_Content_12 = {
    Text = "Ừ, mẹ…"
  },
  AvgDialog_19076_Content_13 = {
    Text = "Tay nhỏ nhắn và mềm mại của Lily siết chặt ngón tay của bạn, bạn cảm nhận được mồ hôi nhẹ nhàng từ lòng bàn tay cô ấy, nhẹ nhàng siết lại để an ủi cô ấy."
  },
  AvgDialog_19076_Content_14 = {
    Text = "Nếu bạn không muốn trở về đây, có muốn đi cùng chúng tôi đến Misaque không?"
  },
  AvgDialog_19076_Content_15 = {
    Text = "Bố đã nhận nuôi tôi năm xưa, bây giờ chắc cũng không ngại nhận thêm một người nữa. \nCó một cô em út ngoan ngoãn như vậy, tôi cũng sẽ rất vui."
  },
  AvgDialog_19076_Content_16 = {
    Text = "Chuyện không phải là vậy, Lily cô ấy…"
  },
  AvgDialog_19076_Content_17 = {
    Text = "<Blue:Hiro>. Nếu bạn hỏi về thân phận, tôi có thể coi là chị của đứa trẻ đó. \nNói chính xác hơn, lực lượng của chúng tôi là <Yellow:「cùng nguồn」>."
  },
  AvgDialog_19076_Content_18 = {
    Text = "Nếu như những lời của Hiro là sự thật, thì đứa bé ngoan mà bạn đang dắt, không nghi ngờ gì cũng là <Yellow:thân thể được đánh thức>."
  },
  AvgDialog_19076_Content_19 = {
    Text = "Tôi biết, không phải có anh ở đây sao? \n Chỉ cần thực hiện liên kết tạm thời, cố gắng cho đến khi cô ấy được liên kết với hồ đen của trường thì ổn."
  },
  AvgDialog_19076_Content_2 = {
    Text = "Đi qua cầu đường sắt, khi bước vào trung tâm điều dưỡng, ánh sáng trời đã vượt qua đường chân trời."
  },
  AvgDialog_19076_Content_20 = {
    Text = "Lily nắm chặt tay bạn, cô nhìn Ramona rồi nhìn bạn, trong mắt đầy vẻ bất an."
  },
  AvgDialog_19076_Content_21 = {
    Text = "Lily… vẫn muốn ở bên mẹ.\nBởi vì…Lily chỉ có một người mẹ, và mẹ cũng chỉ có một mình Lily."
  },
  AvgDialog_19076_Content_22 = {
    Text = "Mẹ cũng không phải là muốn trở thành như vậy. \n<Small:mẹ đã mất đi thứ quan trọng, mẹ muốn tìm lại thứ quan trọng đó, nên mới...>"
  },
  AvgDialog_19076_Content_23 = {
    Text = "Giọng của Lily càng nhỏ, âm cuối hầu như bị tiếng thở che khuất."
  },
  AvgDialog_19076_Content_24 = {
    Text = "<SmallShake:xì——>"
  },
  AvgDialog_19076_Content_25 = {
    Text = "Các bạn cuối cùng cũng đến rồi. Chào mừng đến với Bệnh viện điều dưỡng Laï."
  },
  AvgDialog_19076_Content_26 = {
    Text = "Lily, bạn cứ đi nghỉ ngơi trước nhé, cùng với chị Ninh Phi Nga."
  },
  AvgDialog_19076_Content_27 = {
    Text = "Đi nào, Lily. \nSau chuyến đi dài, chắc em cũng mệt lắm rồi?"
  },
  AvgDialog_19076_Content_28 = {
    Text = "Lily cẩn thận nắm lấy tay Ninh Phi Nga, quay đầu nhìn bạn một cái, rồi thầm lặng đi về cuối hành lang."
  },
  AvgDialog_19076_Content_29 = {
    Text = "Các vị đã vất vả rồi, kính mong được phép tự giới thiệu bản thân."
  },
  AvgDialog_19076_Content_3 = {
    Text = "Đẩy cửa ra, bụi bẩn bốc lên và lan tỏa trong hành lang đầy mùi hôi kỳ quái. \nDù là ngày tuyết tan với ánh nắng rực rỡ, hành lang vẫn chìm trong bóng tối, không một tia sáng."
  },
  AvgDialog_19076_Content_30 = {
    Text = "Tôi là <Blue:Francis Ozwald>, người quản lý bệnh viện này. \nMọi người ở đây thường gọi tôi là Viện trưởng, tất nhiên, các bạn có thể gọi tôi là Francis."
  },
  AvgDialog_19076_Content_31 = {
    Text = "Nhìn trang phục của hai người, các bạn là học sinh? Còn vị này.."
  },
  AvgDialog_19076_Content_32 = {
    Text = "Vâng, chúng tôi là sinh viên năm nhất của Đại học Misaque. \n Lơ-tan… hãy coi cô ấy là giáo viên hướng dẫn của chúng tôi."
  },
  AvgDialog_19076_Content_33 = {
    Text = "Thì ra là vậy. Thật khiến người ta hoài niệm quá! Thời học sinh đã xa quá, tôi cũng không còn nghiêm túc và tập trung như ngày ấy, niềm tin lúc đó cũng đã phai nhạt rồi."
  },
  AvgDialog_19076_Content_34 = {
    Text = "Ánh mắt của bạn khiến tôi nhớ đến bản thân mình hồi đó, nhưng… so với tối qua, hôm nay bạn có thêm một chút dao động."
  },
  AvgDialog_19076_Content_35 = {
    Text = "Đã xảy ra chuyện gì sao? Hay là… \nbạn cũng đã mở chiếc hộp không nên mở đó?"
  },
  AvgDialog_19076_Content_37 = {
    Text = "Không dám so sánh với Giáo sư Ozwood."
  },
  AvgDialog_19076_Content_38 = {
    Text = "Giáo sư Aozwude nếu tiếp tục đầu tư vào nghiên cứu khoa học, có lẽ sẽ đạt được những thành tựu cao hơn trong lĩnh vực y học. \nNhưng ngài lại chọn lui bước khi đang ở đỉnh cao, biến mất khỏi giới học thuật."
  },
  AvgDialog_19076_Content_39 = {
    Text = "À, đều là những chuyện đã qua, không đáng nhắc tới."
  },
  AvgDialog_19076_Content_4 = {
    Text = "Tôi không thích nơi này."
  },
  AvgDialog_19076_Content_40 = {
    Text = "Thế nào? Ngài chính là thành viên của <Blue:đội thám hiểm Elworth> đầu tiên."
  },
  AvgDialog_19076_Content_41 = {
    Text = "Tôi không khỏi tò mò, viện dưỡng lão này đã mời được một học giả như ông/bà bằng cách nào?"
  },
  AvgDialog_19076_Content_42 = {
    Text = "Thay vì thuê tôi, tôi thích nghĩ rằng tôi đã chọn viện dưỡng lão này."
  },
  AvgDialog_19076_Content_43 = {
    Text = "Bạn nên biết rằng, kết quả của chuyến thám hiểm đó hoàn toàn khác xa với \"thành công\". \nTôi là người duy nhất sống sót, còn tất cả những người còn lại đã bị chôn vùi dưới tuyết."
  },
  AvgDialog_19076_Content_44 = {
    Text = "Lần trải nghiệm đó đã thay đổi tôi sâu sắc, tôi bắt đầu suy nghĩ, liệu chúng ta có đang đánh mất những thứ quý giá hơn vì cái gọi là tiến bộ, và việc đánh mất này lại có ý nghĩa gì?"
  },
  AvgDialog_19076_Content_45 = {
    Text = "Đây chính là câu trả lời của bạn?"
