  AvgDialog_19081_Content_12 = {
    Text = "Elton hít thở sâu mấy lần, mới dần đứng vững lại với sự giúp đỡ của Hilaster."
  },
  AvgDialog_19081_Content_13 = {
    Text = "Còn Hilaster……"
  },
  AvgDialog_19081_Content_14 = {
    Text = "Các bạn……"
  },
  AvgDialog_19081_Content_15 = {
    Text = "Họ trở nên yếu ớt hơn."
  },
  AvgDialog_19081_Content_16 = {
    Text = "Được thuyền trưởng ban cho một tia sinh cơ, <Red:quái vật dị> trong cơ thể cô đã ngừng phát triển nhờ thân thể được đánh thức, sức sống đang dần tiêu tán."
  },
  AvgDialog_19081_Content_17 = {
    Text = "Sợ hãi… sợ hãi cái chết, sợ hãi sự mất mát tràn ngập trí óc, trước mắt chỉ còn một màu trắng xóa."
  },
  AvgDialog_19081_Content_18 = {
    Text = "...tôi...các bạn.."
  },
  AvgDialog_19081_Content_19 = {
    Text = "Không sao cả, Muphí, đừng sợ."
  },
  AvgDialog_19081_Content_2 = {
    Text = "22:45\nSonanier\nkhoang hàng thứ ba"
  },
  AvgDialog_19081_Content_20 = {
    Text = "Luôn tìm được cách giải quyết thôi, mọi thứ sẽ ổn cả, đừng lo."
  },
  AvgDialog_19081_Content_21 = {
    Text = "Rời khỏi sự đỡ của Hilaster, thuyền trưởng loạng choạng đứng vững thân thể, rồi lập tức đưa tay ra —— mạnh mẽ xoa một cái lên đỉnh đầu của cô ấy."
  },
  AvgDialog_19081_Content_22 = {
    Text = "Đừng chạm mạnh như vậy! Tóc em dựng cả lên rồi!!"
  },
  AvgDialog_19081_Content_23 = {
    Text = "Bạn luôn nói như vậy! Bạn nhìn xem, bạn sắp không đứng nổi rồi!"
  },
  AvgDialog_19081_Content_24 = {
    Text = "Bây giờ không có vấn đề gì, cậu thấy đấy, tôi đã hồi phục rồi."
  },
  AvgDialog_19081_Content_25 = {
    Text = "Vậy… còn họ? Còn hai học sinh lên nhầm tàu thì sao?"
  },
  AvgDialog_19081_Content_26 = {
    Text = "Họ đã giúp chúng ta kéo dài thời gian, bây giờ sự chú ý của tất cả mọi người đều tập trung vào phòng động lực."
  },
  AvgDialog_19081_Content_27 = {
    Text = "Phòng động lực... Miriam đang ở trong phòng động lực !"
  },
  AvgDialog_19081_Content_28 = {
    Text = "Họ rất tỉnh táo, biết mình có thể làm gì, nên làm gì. \nTrường đại học đó… đã đào tạo những đứa trẻ khá tốt."
  },
  AvgDialog_19081_Content_29 = {
    Text = "Tuy nhiên, chúng ta cũng không phải là không làm được gì, chỉ cần đủ gần bờ, Hilaster có thể chuyển hai người họ lên bờ."
  },
  AvgDialog_19081_Content_3 = {
    Text = "Đế giày cứng đạp lên boong tàu, phát ra tiếng bước chân đều đặn và nặng nề."
  },
  AvgDialog_19081_Content_30 = {
    Text = "Nhưng thân thể cậu…"
  },
  AvgDialog_19081_Content_31 = {
    Text = "Không sao, chút sức sống này tôi còn có thể cho."
  },
  AvgDialog_19081_Content_32 = {
    Text = "Thông đồng với giáo đoàn, đối với <Blue:khổ nạn> của ngươi mà làm ngơ… tội lỗi của ta đã đủ nặng nề, ta không muốn phải gánh thêm hai mạng sống vô tội."
  },
  AvgDialog_19081_Content_33 = {
    Text = "Của tôi……sự đau khổ?"
  },
  AvgDialog_19081_Content_35 = {
    Text = "Người đã đưa cậu đến tay Miriam, chính là tôi."
  },
  AvgDialog_19081_Content_37 = {
    Text = "Bạn là \"hàng hóa\" quý giá nhất mà tôi đã vận chuyển kể từ khi gia nhập giáo đoàn. \n Nhờ chuyến đi hoàn hảo đó, tôi mới nhận được sự ưu ái của Miriam."
  },
  AvgDialog_19081_Content_38 = {
    Text = "Vì vậy, khi tôi nhờ các bạn giúp đỡ, bạn đã không do dự và đồng ý…"
  },
  AvgDialog_19081_Content_39 = {
    Text = "Khi đủ gần bờ biển, tôi sẽ để Hilaster đưa bạn xuống tàu, càng xa biển càng tốt."
  },
  AvgDialog_19081_Content_4 = {
    Text = "Chú thuyền trưởng… Hilaster…"
  },
  AvgDialog_19081_Content_40 = {
    Text = "Dường như đang đáp lại thuyền trưởng, Hilaster lắc chiếc la bàn trong tay."
  },
  AvgDialog_19081_Content_41 = {
    Text = "Bạn có ý muốn cho Hilaster và tôi cùng đi không?"
  },
  AvgDialog_19081_Content_42 = {
    Text = "Hai học sinh đó có phương tiện di chuyển, chỉ cần biến chiếc xe của họ thành <Yellow:thâm cảnh>.."
  },
  AvgDialog_19081_Content_43 = {
    Text = "Đừng đùa nữa! Anh nghĩ rằng anh có thể chặn được hai con quái vật đó sao? \n Anh thậm chí không phải là một người dấn thân vào biển, chỉ là một con người bình thường thôi!"
  },
  AvgDialog_19081_Content_44 = {
    Text = "Tôi hy vọng bạn có thể thoát khỏi tất cả điều này, hãy coi đó là ước nguyện cuối cùng của tôi."
  },
  AvgDialog_19081_Content_45 = {
    Text = "Kết quả tồi tệ nhất không phải là chìm xuống đáy biển sao? Tôi đã sớm nên cùng con tàu Sonanier nằm lại dưới biển sâu rồi."
  },
  AvgDialog_19081_Content_46 = {
    Text = "Murphí bám chặt vào phần đuôi áo khoác của thuyền trưởng, kiên quyết không chịu buông tay."
  },
  AvgDialog_19081_Content_47 = {
    Text = "Thân thể được đánh thức không có ý định tham gia vào cuộc tranh cãi này. Anh ta cảm nhận trạng thái của Người Giữ Gìn ở đầu kia của liên kết, và chuẩn bị đi tới phòng động lực."
  },
  AvgDialog_19081_Content_48 = {
    Text = "——đợi đã! bạn định đi đâu!"
  },
  AvgDialog_19081_Content_49 = {
    Text = "Cô gái đẩy mở cửa buồng, đưa tay kéo một xúc tu."
  },
  AvgDialog_19081_Content_5 = {
    Text = "Ramona, còn %player%… sao vẫn chưa trở về."
  },
  AvgDialog_19081_Content_50 = {
    Text = "Bạn làm thế nào mà biết tôi.."
  },
  AvgDialog_19081_Content_51 = {
    Text = "Bạn chính là \"tulô\" mà Ramona nói, phải không? Bạn có định đi giúp họ không?"
  },
  AvgDialog_19081_Content_52 = {
    Text = "Việc ta làm, ngoại nhân không được can thiệp."
  },
  AvgDialog_19081_Content_53 = {
    Text = "Tôi cũng đi."
  },
  AvgDialog_19081_Content_54 = {
    Text = "Muphí! Nếu bạn rơi vào tay Miriam, mọi nỗ lực của chúng ta sẽ trở nên vô ích."
  },
  AvgDialog_19081_Content_55 = {Text = "Ta biết."},
  AvgDialog_19081_Content_56 = {
    Text = "Nhưng... tôi không thể...\nTôi không muốn chết, nhưng... nếu họ hy sinh trước khi cập bến.."
  },
  AvgDialog_19081_Content_57 = {
    Text = "<SmallShake:tôi… không muốn…… chuyện như thế……>"
  },
  AvgDialog_19081_Content_58 = {
    Text = "Khụ, khụ khụ!"
  },
  AvgDialog_19081_Content_59 = {
    Text = "Ý tôi là… tôi không thể ở mãi trong thâm cảnh, nếu muốn thoát ra hoàn toàn, tôi cần sự giúp đỡ của hai học sinh đó."
  },
  AvgDialog_19081_Content_6 = {
    Text = "Muphí cắn môi, đi tới đi lui trong sự lo lắng tột độ. Lúc thì đá mạnh vào thùng hàng, lúc lại kéo hai lần dây cố định thùng hàng."
  },
  AvgDialog_19081_Content_60 = {
    Text = "Tôi không thể trực tiếp tìm đến trường, nói với hiệu trưởng rằng học sinh của họ đã hy sinh để giúp tôi. \n Tôi cần họ sống sót, tôi muốn trở thành khách của họ một cách chính đáng và đầy tự hào."
  },
  AvgDialog_19081_Content_61 = {
    Text = "Ta sẽ không phân tâm bảo vệ ngươi."
  },
  AvgDialog_19081_Content_62 = {
    Text = "Không cần anh bảo vệ, tôi biết rõ điểm yếu của người dấn thân vào biển, tôi có thể tự chăm sóc bản thân."
  },
  AvgDialog_19081_Content_63 = {
    Text = "Được, nếu bạn nhất quyết như vậy."
  },
  AvgDialog_19081_Content_64 = {
    Text = "Bạn nhìn tôi với ánh mắt như thế nào vậy?"
  },
  AvgDialog_19081_Content_65 = {
    Text = "Ta vốn nghĩ rằng, ngươi không xứng đáng để họ hy sinh như vậy. \nBây giờ xem ra, ta đã có suy nghĩ chủ quan từ trước."
  },
  AvgDialog_19081_Content_66 = {
    Text = "Bạn đang nói gì vậy? Nhanh lên, đi đi!"
  },
  AvgDialog_19081_Content_67 = {
    Text = "Đứa trẻ này… thôi thì, nếu đây là lựa chọn của cô ấy."
  },
  AvgDialog_19081_Content_68 = {
    Text = "Hilaster, duy trì toàn tốc tiến lên"
  },
  AvgDialog_19081_Content_7 = {
    Text = "Họ sẽ không sao chứ……"
  },
  AvgDialog_19081_Content_8 = {
    Text = "Cô ấy không thể yên tĩnh để cầu nguyện, không thể yên tâm ngồi xuống."
  },
  AvgDialog_19081_Content_9 = {
    Text = "Rầm—— !"
  },
  AvgDialog_19082_Content_1 = {
    Text = "Bạn còn đang chờ gì nữa? Đợi tôi mời à?"
  },
  AvgDialog_19082_Content_10 = {
    Text = "Nhanh lên! Bạn xuống trước đi!"
  },
  AvgDialog_19082_Content_11 = {
    Text = "Không được! anh là người bình thường, tôi có nghĩa vụ bảo vệ anh —— <BigShake:á!>"
  },
  AvgDialog_19082_Content_12 = {
    Text = "Cô gái giả vờ không nghe thấy lời càu nhàu của bạn, cô ấy nhờ vào vóc dáng nhỏ nhắn và sự linh hoạt để lách sang phía sau bạn."
  },
  AvgDialog_19082_Content_13 = {
    Text = "—— Rồi, đá mạnh một cú thật đau vào người bạn và hất bạn vào trong bóng tối của cửa hang."
  },
  AvgDialog_19082_Content_14 = {
    Text = "<SmallShake:đau đau đau……>"
  },
  AvgDialog_19082_Content_15 = {
    Text = "Cô gái trẻ nhảy theo sau, cô ấy đóng sầm cửa sắt lại, thành thạo xoay cần capstan, khóa chặt cửa."
  },
  AvgDialog_19082_Content_16 = {
    Text = "Thở —— có lẽ tạm thời an toàn rồi."
  },
  AvgDialog_19082_Content_17 = {
    Text = "Cô gái nhấn công tắc, đèn điện cũ kỹ nhấp nháy vài lần trước khi ánh sáng lan ra bốn phía, xua tan bóng tối."
  },
  AvgDialog_19082_Content_18 = {
    Text = "Khoang hàng rộng rãi và trống trải, vài món hàng lẻ tẻ được cố định một cách rời rạc ở các góc. Bụi bay lơ lửng trong ánh đèn mờ tối, tạo nên khung cảnh hoang tàn của một nơi đã lâu không có dấu vết con người."
  },
  AvgDialog_19082_Content_19 = {
    Text = "Âm thanh đục từ trên đỉnh đầu liên tục vang lên, từng tiếng một rung động trong hộp sọ của bạn."
  },
  AvgDialog_19082_Content_2 = {
    Text = "Cánh cửa bí mật?!"
  },
  AvgDialog_19082_Content_20 = {
    Text = "Đầu tôi.."
  },
  AvgDialog_19082_Content_21 = {
    Text = "Thái dương đập theo tần suất gõ, cơn đau dữ dội xé toạc hai bán cầu não, axit dạ dày lại trào lên đến cổ họng."
  },
  AvgDialog_19082_Content_22 = {
    Text = "Họ tạm thời không thể vào được... ê?! Bạn sao vậy?!"
  },
  AvgDialog_19082_Content_23 = {
    Text = "Đừng, đừng hù tôi? Đừng chết!"
  },
  AvgDialog_19082_Content_24 = {
    Text = "Phù, cuối cùng cũng thoát khỏi họ rồi."
  },
  AvgDialog_19082_Content_25 = {
    Text = "Cánh cửa này rất chắc chắn, đến đây nên tạm thời an toàn rồi…<BigShake:Khốn kiếp!>"
  },
  AvgDialog_19082_Content_26 = {
    Text = "Khốn kiếp khốn kiếp khốn kiếp! Cậu đã gây ra rắc rối lớn! Làm rối kế hoạch của bản tiểu thư! Phải nghĩ cách…"
  },
  AvgDialog_19082_Content_27 = {
    Text = "Đúng rồi, cô nên nhớ kỹ tên của tiểu thư đây ——"
  },
  AvgDialog_19082_Content_28 = {
    Text = "Gương mặt lo lắng của cô gái và những mảnh ký ức hiện lên trong đầu dần hòa vào nhau, hai cảnh tượng tương đồng nhưng khác biệt cũng hợp nhất thành một bức tranh duy nhất."
  },
  AvgDialog_19082_Content_29 = {
    Text = "Muphí……?"
  },
  AvgDialog_19082_Content_3 = {
    Text = "Cánh cửa bí mật nào? Đã đến nước này rồi mà anh còn dám đùa với tôi sao?! Anh có điên không hả?!"
  },
  AvgDialog_19082_Content_30 = {
    Text = "Bạn, bạn có ổn không?"
  },
  AvgDialog_19082_Content_31 = {
    Text = "Đau một chút vì ngã."
  },
  AvgDialog_19082_Content_32 = {
    Text = "Không lẽ, bị thương ở đâu vậy?"
  },
  AvgDialog_19082_Content_33 = {
    Text = "Dưới ánh sáng mờ nhạt, cô ấy nhẹ nhàng bước trên đầu ngón chân để kiểm tra tình trạng của bạn."
  },
  AvgDialog_19082_Content_34 = {Text = "——!"},
  AvgDialog_19082_Content_35 = {
    Text = "Có chuyện gì vậy?"
  },
  AvgDialog_19082_Content_36 = {
    Text = "<SmallShake:không, không có gì……>"
  },
  AvgDialog_19082_Content_37 = {
    Text = "<Small:hình như có thứ có thể dùng được trong lô hàng này…>"
  },
  AvgDialog_19082_Content_38 = {
    Text = "Muphí lầm bầm không rõ, di chuyển một cách cứng ngắc tới chỗ đống thùng hàng, lục tìm thứ gì đó."
  },
  AvgDialog_19082_Content_39 = {
    Text = "(đến gần cô ấy)"
  },
  AvgDialog_19082_Content_4 = {
    Text = "Đã không phải chưa từng vào khoang tàu, đừng có lề mề nữa, chuẩn bị đi!"
  },
  AvgDialog_19082_Content_40 = {
    Text = "Muphí tháo dỡ hộp hàng một cách thô bạo, vật liệu nhồi và rơm dùng để lót trong hộp hàng rơi rớt khắp nơi, góc này nhanh chóng trở nên bừa bộn."
  },
  AvgDialog_19082_Content_41 = {
    Text = "Không đúng……hộp này toàn đồ trang sức bị hỏng."
  },
  AvgDialog_19082_Content_42 = {
    Text = "Bạn liếc nhìn, trong thùng hàng là một bộ trang sức bạch kim phong cách cung đình, được đính ngọc trai và kim cương trông vô giá."
  },
  AvgDialog_19082_Content_43 = {
    Text = "… là cái gì vậy, toàn là đồ dùng nghi lễ."
  },
  AvgDialog_19082_Content_44 = {
    Text = "Hộp thứ hai được nhét đầy các loại đồ đạc và thảo dược khác nhau, cối đá, xô thơm, myrrh… Người không có kiến thức cơ bản về luyện kim có lẽ chỉ nghĩ rằng đây là hàng hóa của một nhà thuốc."
  },
  AvgDialog_19082_Content_45 = {
    Text = "Đã tìm thấy! Nhanh lên, bạn hãy cúi xuống."
  },
  AvgDialog_19082_Content_46 = {
    Text = "Chất dẻo dính được bôi lên sau gáy của bạn mà không cần hỏi ý kiến, cảm giác lạnh lẽo kèm theo một chút cay, giúp giảm đau ở mức độ nhất định."
  },
  AvgDialog_19082_Content_47 = {
    Text = "Đây là…"
  },
  AvgDialog_19082_Content_48 = {
    Text = "Ê! Đừng sờ lung tung."
  },
  AvgDialog_19082_Content_49 = {
    Text = "Muphí đưa cho bạn một hũ thuốc mỡ."
  },
  AvgDialog_19082_Content_5 = {
    Text = "Dưới đây có an toàn không?"
  },
  AvgDialog_19082_Content_50 = {
    Text = "Nhãn không ghi công thức hay tên thuốc, chỉ vẽ một hình vẽ kỳ lạ, dường như là một lọ thuốc tự chế."
  },
  AvgDialog_19082_Content_51 = {
    Text = "……Có phải mình đã thấy cái này ở đâu rồi không? Hình trên nhãn tuýp thuốc, trông quen lắm."
  },
  AvgDialog_19082_Content_52 = {
    Text = "Nè, chính là cái này, yên tâm đi, không sao đâu, chẳng độc chút nào!"
  },
  AvgDialog_19082_Content_53 = {
    Text = "Từ nhỏ đến lớn, mỗi khi bị thương ngoài da, mình đều dùng loại thuốc mỡ này. \n Thế nào, có phải vừa bôi lên là không còn đau nữa không?"
  },
  AvgDialog_19082_Content_54 = {
    Text = "Cô ấy cảm thấy rất lo lắng về việc bạn bị ngã cầu thang và đập đầu, ánh mắt nhìn bạn đầy lo lắng và áy náy."
  },
  AvgDialog_19082_Content_55 = {
    Text = "Đỡ đau rồi"
  },
  AvgDialog_19082_Content_56 = {
    Text = "Nhìn này, tôi đã nói là rất hiệu quả rồi ——"
  },
  AvgDialog_19082_Content_57 = {
    Text = "Được câu trả lời khẳng định, Mốp-phí cuối cùng cũng thả lỏng và nở nụ cười."
  },
  AvgDialog_19082_Content_58 = {
    Text = "Đầu sau cảm thấy thoải mái hơn một chút, nhưng huyệt thái dương vẫn còn đau nhức. \n Nhìn thấy vẻ mặt thư giãn của cô ấy, có một giọng nói trong lòng bạn nói như thế này ——"
  },
  AvgDialog_19082_Content_59 = {
    Text = "Có một số việc có thể để sau khi gặp gỡ <Blue:đối tác của bạn> rồi mới đi sâu nghiên cứu."
  },
  AvgDialog_19082_Content_6 = {
    Text = "Tôi đâu biết."
  },
  AvgDialog_19082_Content_7 = {
    Text = "Tốt hơn bị bọn điên này bắt đi cho cá ăn! Đừng lề mề nữa, sẵn sàng lên!"
  },
  AvgDialog_19082_Content_8 = {
    Text = "Bạn cố gắng trì hoãn cuộc tấn công của kẻ địch, trong khi bảo vệ cô gái kéo cánh cửa sắt lên một cách vội vàng."
  },
  AvgDialog_19082_Content_9 = {
    Text = "Dưới cửa hang, cầu thang sắt kéo dài xuống bóng tối sâu thẳm."
  },
  AvgDialog_19083_Content_1 = {
    Text = "Thực tại bị bóp méo"
  },
  AvgDialog_19083_Content_10 = {
    Text = "Với ánh sáng, cô nhìn thấy \"mẹ\" có vô số vết thương đen lớn nhỏ trên bề mặt mịn màng."
  },
  AvgDialog_19083_Content_11 = {
    Text = "\"Xin lỗi...\""
  },
  AvgDialog_19083_Content_12 = {
    Text = "Dịch chất đen sôi lên, đánh tan sự tĩnh lặng dưới đáy bờ."
  },
  AvgDialog_19083_Content_13 = {
    Text = "\"mẹ\" phát ra một tiếng kêu thê thảm, các xúc tu động đậy, đưa thứ gì đó vào trong lồng ngực của con non."
  },
  AvgDialog_19083_Content_14 = {
    Text = "Những xúc tu mềm mại, trơn trượt và lạnh lẽo quấn quanh cô, nước hồ đen không còn làm tắc nghẽn miệng và mũi cô nữa, mà ngược lại, giống như nước ối, đã nuôi dưỡng sự sống của cô."
  },
  AvgDialog_19083_Content_15 = {
    Text = "<Change>\"Xin lỗi...\"\n \"Tôi còn... không muốn chết...\""
  },
  AvgDialog_19083_Content_16 = {
    Text = "Bề mặt nước giữ được sự yên lặng lâu dài, thậm chí cả gió hú ở vùng cực cũng không thể làm cho nước ao đặc quánh nổi lên gợn sóng."
  },
  AvgDialog_19083_Content_17 = {
    Text = "Thánh nữ có phải đã…"
  },
  AvgDialog_19083_Content_18 = {
    Text = "Cô ấy sinh vào thời khắc chính vị của ngôi sao trước đó, là đứa trẻ \"có thể nhìn thấy\"."
  },
  AvgDialog_19083_Content_19 = {
    Text = "Trên thế giới, không ai xứng đáng nhận được sự công nhận từ dòng máu thần thánh hơn cô ấy."
  },
  AvgDialog_19083_Content_2 = {
    Text = "Chú chim non bị gãy cánh, rơi vào ao nước đen."
  },
  AvgDialog_19083_Content_20 = {
    Text = "Kèm theo những tiếng thì thầm mơ hồ, dường như năng lượng sâu trong lòng đất sắp bùng nổ, mặt nước đột nhiên sôi sục dữ dội."
  },
  AvgDialog_19083_Content_21 = {
    Text = "Nước đen đặc và dày tràn ra khỏi bờ ao, ngập qua mắt cá chân của mọi người rồi chảy tới bên chân trần của người phụ nữ."
  },
  AvgDialog_19083_Content_22 = {
    Text = "Đi qua đám giáo đồ trẻ thì thầm kinh ngạc, cô im lặng bước lên con đường lát chất lỏng đen, nhúng sâu hai tay vào hồ nước ——"
  },
  AvgDialog_19083_Content_23 = {
    Text = "—— xào"
  },
  AvgDialog_19083_Content_24 = {
    Text = "Cô gái bám vào đôi tay của mình, nhảy ra khỏi nước trong hồ. \n Chất lỏng đen chảy dọc theo đường nét khuôn mặt, giống như hai vệt nước mắt rùng rợn."
  },
  AvgDialog_19083_Content_25 = {
    Text = "Ồ, không tệ mà. Xem ra, <Blue:thần thai> đã chấp nhận <Blue:người mẹ mới>."
  },
  AvgDialog_19083_Content_26 = {
    Text = "Goliath lên tiếng bất ngờ, giọng điệu mỉa mai, nhưng chẳng còn ai bận tâm đến lời mỉa mai của hắn."
  },
  AvgDialog_19083_Content_27 = {
    Text = "Thánh nữ, thành công rồi? Chúng ta đã thành công!"
  },
  AvgDialog_19083_Content_28 = {
    Text = "Miriam nhẹ nhàng nhắm mắt lại, buông tay cô gái trẻ đang nắm chặt, quay người đối mặt với đám tín đồ trong cơn cuồng nhiệt."
  },
  AvgDialog_19083_Content_29 = {
    Text = "Cô ấy giơ cao hai tay, chất lỏng màu đen trượt dọc theo đường nét làn da, lưới che mặt lập tức bị nhuộm thành màu đen đậm."
  },
  AvgDialog_19083_Content_3 = {
    Text = "Lời cầu nguyện lảm nhảm của chủ tế bay bổng nhưng vững chắc, những lời điên cuồng xuyên qua chất dịch đen đặc, hóa thành lưỡi kiếm sắc bén xé toạc lồng ngực của chú chim non."
  },
  AvgDialog_19083_Content_30 = {
    Text = "Lời cầu nguyện vang lên liên tục, cuối cùng hòa quyện trong hang động lạnh lẽo, cuồng nhiệt, méo mó, ầm ĩ đến mức rung chuyển cả hang động."
  },
  AvgDialog_19083_Content_31 = {
    Text = "Mẹ thần đã đến!"
  },
  AvgDialog_19083_Content_32 = {
    Text = "Ngài sẽ phục hồi từ @1, khiến @2 đến!"
  },
  AvgDialog_19083_Content_33 = {
    Text = "Ngài sẽ phục hồi từ @1, khiến @2 đến!"
  },
  AvgDialog_19083_Content_34 = {
    Text = "Ba tháng sau"
  },
  AvgDialog_19083_Content_35 = {
    Text = "Bạn đã làm cho người phụ nữ đó càng ngày càng rất đau đầu. Vài tháng trước cô ấy còn rất ngoan phải không? Sao bây giờ lại không muốn nghe lời mẹ nữa rồi?"
  },
  AvgDialog_19083_Content_36 = {
    Text = "Cô gái liếc mắt nhìn Goliath, cắm con dao khắc vào gỗ một cách giận dữ, rồi ném cả dụng cụ và vật liệu sang một bên."
  },
  AvgDialog_19083_Content_37 = {
    Text = "Mẹ, mẹ?"
  },
  AvgDialog_19083_Content_38 = {
    Text = "Bạn… từ đâu học được cách nói như vậy?"
  },
  AvgDialog_19083_Content_39 = {
    Text = "Từ điển! Bạn xem, \"người trưởng thành nữ có tình cảm kết nối và chăm sóc trẻ nhỏ\"."
  },
  AvgDialog_19083_Content_4 = {
    Text = "Dịch chất lỏng màu đỏ tươi nổi lên từ ngực, nở rộ quyến rũ trên mặt nước đen đã yên tĩnh ——"
  },
  AvgDialog_19083_Content_40 = {
    Text = "Không, tôi sẽ không phải là mẹ của bạn."
  },
  AvgDialog_19083_Content_41 = {
    Text = "Ngài là Thánh nữ của giáo đoàn, là người được mệnh định tôn quý… Nếu ngài muốn, có thể gọi thẳng tên tôi."
  },
  AvgDialog_19083_Content_42 = {
    Text = "Ừ… Miri… Am?"
  },
  AvgDialog_19083_Content_43 = {
    Text = "Vâng, thánh nữ."
  },
  AvgDialog_19083_Content_44 = {
    Text = "Tôi là người hầu trung thành của ngài."
  },
  AvgDialog_19083_Content_45 = {
    Text = "……cô ấy không phải là mẹ tôi, chưa bao giờ."
  },
  AvgDialog_19083_Content_46 = {
    Text = "Chỉ có những kẻ ở trên Hội Giáo đèn lồng biết về nguồn gốc của tôi, tôi cũng không có mẹ, tôi chỉ là món quà họ dành cho Miriam."
  },
  AvgDialog_19083_Content_47 = {
    Text = "Ồ? Cô ấy thật sự kể cả chuyện này cho anh nghe à?"
  },
  AvgDialog_19083_Content_48 = {
    Text = "Đối với một tù nhân đã định ngày chết, biết bao nhiêu bí mật cũng không sao, dù sao thì mọi thứ rồi cũng sẽ theo tôi vào lòng đất."
  },
  AvgDialog_19083_Content_49 = {
    Text = "Đây cũng là sự bù đắp của người phụ nữ đó dành cho bạn. Hãy nhớ rằng, vào ngày thai thần được cấy vào cơ thể bạn, chủ tế đại nhân của chúng ta đã không nghỉ ngơi suốt cả đêm."
  },
  AvgDialog_19083_Content_5 = {
    Text = "Cô ấy không ngừng chìm xuống, những rễ cây đẫm máu kéo cô vào nơi sâu thẳm nhất, vào một vòng tay vừa mềm mại vừa lạnh giá."
  },
  AvgDialog_19083_Content_50 = {
    Text = "Cảm giác tội lỗi đã hành hạ cô ấy rất nhiều."
  },
  AvgDialog_19083_Content_51 = {
    Text = "Cảm giác tội lỗi? Bạn đang đùa phải không? Cô ấy sẽ không có cảm xúc này."
  },
  AvgDialog_19083_Content_52 = {
    Text = "Thật tuyệt tình, tiểu công chúa. \nNếu con gái quá lạnh lùng, sẽ làm mẹ buồn đó."
  },
  AvgDialog_19083_Content_53 = {
    Text = "Bạn có phiền không! Đã nói rồi, cô ấy không phải là mẹ tôi!"
  },
  AvgDialog_19083_Content_54 = {
    Text = "Điều này chưa chắc, bạn có muốn nghe câu chuyện không."
  },
  AvgDialog_19083_Content_55 = {
    Text = "<BigShake:Không muốn nghe, tôi cũng không muốn gặp bạn!>\nNếu là cố ý đến để châm chọc tôi, bạn có thể rời đi!"
  },
  AvgDialog_19083_Content_56 = {
    Text = "Không, bạn muốn nghe..."
  },
  AvgDialog_19083_Content_57 = {
    Text = "Giọng điệu của Goliath bỗng chốc trở nên trầm lắng, mang theo uy nghi của người từng trải qua nhiều chiến trường, hai trái tim trong cơ thể Muphí suýt nữa ngừng đập vì điều đó."
  },
  AvgDialog_19083_Content_58 = {
    Text = "Cô ấy đột nhiên nhận ra—— người khổng lồ chưa bao giờ là món đồ chơi mà cô có thể tùy tiện nghịch ngợm. \nChỉ là mình đã dựa vào danh phận để lấn tới, còn đối phương thì cũng vui vẻ đứng nhìn xem trò cười thôi."
  },
  AvgDialog_19083_Content_59 = {
    Text = "Vâng… vâng, hãy nói đi."
  },
  AvgDialog_19083_Content_60 = {
    Text = "Có một giáo hội bí ẩn, để duy trì sự tinh khiết tuyệt đối của dòng máu, mọi cuộc hôn nhân đều do giáo chủ chỉ định. \nNhững người kết hôn và sinh con với người ngoài cuối cùng đều phải trả giá."
  },
  AvgDialog_19083_Content_61 = {
    Text = "Trong lần thanh toán trước, người thực hiện đã mang về một đứa trẻ — một bé gái có khả năng nhìn thấy <Yellow:thực thể tinh thần>."
  },
  AvgDialog_19083_Content_62 = {
    Text = "Bé gái……"
  },
  AvgDialog_19083_Content_63 = {
    Text = "Cô ấy đã ở trong ngăn bí mật dưới thân thể mẹ quá lâu, khi bị giáo đồ tìm thấy, cô ấy suýt bị <Red:máu của chính mẹ ruột> làm cho ngạt thở đến chết."
  },
  AvgDialog_19083_Content_64 = {
    Text = "Người phụ nữ bình thường, không có thành tựu gì nổi bật, thành tựu lớn nhất của đời này chính là sinh hạ một cô con gái ưu tú và cố gắng không để giáo hội mang cô bé đi."
  },
  AvgDialog_19083_Content_65 = {
    Text = "——Quả là tình mẫu tử tuyệt vời, tôi sắp khóc vì xúc động rồi."
  },
  AvgDialog_19083_Content_66 = {
    Text = "Goliath… bạn…"
  },
  AvgDialog_19083_Content_67 = {
    Text = "Tại sao…… tại sao phải nói cho tôi những điều này?"
  },
  AvgDialog_19083_Content_68 = {
    Text = "Cảm thấy u uất không phải là điều tốt, hãy nhớ rằng, sự phát triển của <Blue:thần> phụ thuộc vào trạng thái của chủ thể."
  },
  AvgDialog_19083_Content_69 = {
    Text = "Hãy làm điều gì đó bạn thích đi, gây rối loạn, dùng roi trừng phạt những người dấn thân vào biển, giải trí với nữ tỳ của bạn… bất cứ điều gì cũng được."
  },
  AvgDialog_19083_Content_70 = {
    Text = "Goliath đơn phương chấm dứt cuộc đối thoại, xoa nhẹ đầu cô ấy một cách lạnh lùng không chút tình cảm."
  },
  AvgDialog_19083_Content_71 = {
    Text = "Khi rời đi, anh ta liếc nhìn bức tượng gỗ mà Muphí ném vào góc tường. Kỹ nghệ của cô gái còn non nớt, hình dáng to lớn và kỳ lạ ngồi trên đế gỗ khiến người ta chỉ liếc qua cũng cảm thấy không thoải mái."
  },
  AvgDialog_19083_Content_72 = {Text = "Hừ."},
  AvgDialog_19083_Content_73 = {
    Text = "Sau khi Goliath rời đi, không gian trở nên im lặng. Các sinh vật bị giam cầm để hiến tế trong lồng cũng im lặng hoàn toàn."
  },
  AvgDialog_19083_Content_74 = {
    Text = "Muphí đã ngồi bên đống lửa rất lâu, cho đến khi ánh sáng dần yếu đi, đống lửa sắp tắt, cô mới như vừa tỉnh dậy và vỗ nhẹ vào má mình."
  },
  AvgDialog_19083_Content_75 = {
    Text = "Cô ấy đá mạnh vào một cái lồng bên cạnh, khiến người phụ nữ tiều tụy co ro ở góc lồng sợ hãi rùng mình."
  },
  AvgDialog_19083_Content_76 = {
    Text = "Này, bạn vừa nghe hết rồi đúng không?"
  },
  AvgDialog_19083_Content_77 = {
    Text = "Đúng, đúng…"
  },
  AvgDialog_19083_Content_78 = {
    Text = "Tôi không giúp bạn một cách vô ích. Tôi muốn bạn sau khi trốn thoát, tìm cách quay lại đưa tôi theo."
  },
  AvgDialog_19083_Content_79 = {
    Text = "Tôi sợ rằng tôi không có khả năng lớn như vậy, tôi chỉ là một nhà khoa học bình thường……"
  },
  AvgDialog_19083_Content_8 = {
    Text = "Cô ấy đã thấy. \n Cô ấy nhìn lên, \"Mẹ\" buông xuống ba đôi mắt, đối diện với cô."
  },
  AvgDialog_19083_Content_80 = {
    Text = "Thế nên cậu phải nghĩ ra cách đi! Não bộ của nhà khoa học, chắc chắn không thể không nghĩ ra được một cách nào đó!"
  },
  AvgDialog_19083_Content_81 = {
    Text = "Nhìn thấy khuôn mặt của cô gái trẻ đang cố nén nước mắt, người phụ nữ nhớ lại hình ảnh con gái của mình trong ký ức đã trở nên mờ nhạt, cuối cùng cũng cảm thấy thương xót."
  },
  AvgDialog_19083_Content_82 = {
    Text = "Đừng quá buồn nhé."
  },
  AvgDialog_19083_Content_83 = {
    Text = "Trước đây, khi gặp phải khó khăn trong nghiên cứu, tôi thường thức trắng đêm không ngủ được, lúc đó tôi sẽ vào phòng con gái một cách nhẹ nhàng, ngồi bên giường và nhìn cô ấy."
  },
  AvgDialog_19083_Content_84 = {
    Text = "Cô ấy nhỏ bé và ngoan ngoãn như vậy… Khi nghĩ đến mọi việc tôi làm đều là để mang lại tương lai tốt đẹp hơn cho cô ấy, thì mọi mệt mỏi dường như tan biến hoàn toàn."
  },
  AvgDialog_19083_Content_85 = {
    Text = "Tôi cũng từng là một người mẹ, tôi hiểu... mẹ ruột của bạn hẳn đã rất mong chờ ngày bạn chào đời. Trên thế giới này, chắc hẳn có ai đó luôn yêu thương bạn."
  },
  AvgDialog_19083_Content_87 = {
    Text = "Bạn có nói đủ chưa? Đừng xen vào việc của cô gái này, hãy lo giữ mạng sống của mình trước đi!"
  },
  AvgDialog_19083_Content_88 = {
    Text = "\"Xin lỗi...\"\n \"Tôi... không muốn chết...\""
  },
  AvgDialog_19083_Content_89 = {
    Text = "Tôi cũng không muốn... kết thúc như vậy.."
  },
  AvgDialog_19083_Content_9 = {
    Text = "Đó là một sinh vật khổng lồ màu đỏ thẫm, những nơi bị máu nhuốm lên trở nên trong suốt, ánh lên sắc trắng mờ ảo. \"Bà Mẹ\" phát ra thứ ánh sáng mỏng manh, tạm thời soi rọi một góc nhỏ của thế giới."
  },
  AvgDialog_19084_Content_1 = {
    Text = "Các bạn đã để tài xế rời đi."
  },
  AvgDialog_19084_Content_10 = {
    Text = "Từ đầu, cuộc tấn công của chúng đã mang tính mục đích, nhằm buộc chúng ta đến đây —— <Blue:Đình cảng thứ ba, bến số 2>."
  },
  AvgDialog_19084_Content_11 = {
    Text = "Có vẻ như ở đây không có gì đặc biệt cả.."
