  AvgDialog_19084_Content_23 = {
    Text = "Sona Niêl, từng thuộc <Blue:Công ty Vận tải Hắc Tinh>, hoạt động như một tàu khách thực hiện các chuyến vận chuyển qua đại dương. Sau khi công ty phá sản, Sona Niêl được mua lại bởi một cá nhân ẩn danh, thay đổi đăng ký vận chuyển và cải tạo thành tàu hàng."
  },
  AvgDialog_19084_Content_24 = {
    Text = "Tiền bối Viliam! Anh có biết con tàu này không?"
