  AvgDialog_19088_Content_25 = {Text = "Tulô."},
  AvgDialog_19088_Content_26 = {
    Text = "Tôi không phải là những kẻ cứng nhắc trong hội nghị thẩm tra, thức tỉnh đối với tôi không phải là con thú cần phải khóa chân, và bây giờ cũng không phải là lúc để truy cứu về việc \"bỏ nhà ra đi\"."
