  AvgDialog_19120_Content_8 = {
    Text = "Đây có phải là mục đích của những người dấn thân vào biển? Để tổ chức các nghi lễ dị giáo trên tàu?"
  },
  AvgDialog_19120_Content_9 = {
    Text = "Hiện tại vẫn chưa rõ, nhưng tôi nghĩ, tulô có thể biết câu chuyện đằng sau."
  },
  AvgDialog_19121_Content_1 = {
    Text = "Vây hãm tứ phía"
  },
  AvgDialog_19121_Content_10 = {
    Text = "Điều tra viên Draper dự kiến sẽ đến Cầu cảng số 3 trong vòng nửa giờ."
  },
  AvgDialog_19121_Content_11 = {
    Text = "Nửa giờ quá lâu. Có quá nhiều địch ở phía nam con đường, chúng ta sẽ thử đột phá từ phía bắc."
  },
  AvgDialog_19121_Content_12 = {
    Text = "Đã thông báo cho tài xế đến khu vực phía bắc của bến cảng số 3 để đón."
  },
  AvgDialog_19121_Content_13 = {
    Text = "Địch không rõ? Là <Yellow:Hội Giáo đèn lồng> và những người có liên quan không?"
  },
  AvgDialog_19121_Content_14 = {
    Text = "Có muốn ghi nhận thông tin về kẻ địch mới?"
