  AvgDialog_19121_Content_8 = {
    Text = "Chúng ta cần sự hỗ trợ ngay!"
  },
  AvgDialog_19121_Content_9 = {
    Text = "Chúng ta đang ở <Blue:Brillport>, tại <Blue:đình tàu thứ ba>, và đã xảy ra trận chiến với kẻ thù vô danh."
  },
  AvgDialog_19122_Content_1 = {
    Text = "Những khuôn mặt xấu xí, chỉ cần nhìn thẳng đã khiến người ta cảm thấy như thể đang xúc phạm thuyết tiến hóa."
  },
  AvgDialog_19122_Content_2 = {
    Text = "Chúng đẩy nhau, binh khí va vào nhau phát ra âm thanh chói tai và hỗn loạn. Ở trung tâm của sự hỗn loạn, chúng dường như đang bao quanh một sự tồn tại nào đó…"
  },
  AvgDialog_19123_Content_1 = {
    Text = "Không lối thoát"
  },
  AvgDialog_19123_Content_10 = {
    Text = "Tại bến cảng, kẻ địch phát động tấn công, ép các người lên cầu thang. Chúng đứng vây kín dưới chân cầu thang, ánh mắt trống rỗng như những con cá chết, chăm chú nhìn chằm chằm vào từng bước di chuyển của các người."
