  AvgDialog_19123_Content_11 = {
    Text = "Chúng không theo kịp cầu thang.."
  },
  AvgDialog_19123_Content_12 = {
    Text = "Ramona hạ thấp giọng, thì thầm một cách kín đáo."
  },
  AvgDialog_19123_Content_13 = {
    Text = "Chúng ta bị coi là chuột bạch mở đường, một khi lên boong tàu, e rằng sẽ mất đi giá trị sử dụng đối với họ."
  },
  AvgDialog_19123_Content_14 = {
    Text = "Vì vậy… tôi có một ý tưởng."
  },
  AvgDialog_19123_Content_15 = {
    Text = "Bạn bước lên bậc thang cuối cùng của cầu dẫn."
  },
  AvgDialog_19123_Content_16 = {
    Text = "Ramona, có gì không ổn! Hãy chờ đã!"
  },
  AvgDialog_19123_Content_17 = {
    Text = "Cầu thang rung lên, kẻ thù không cho các bạn cơ hội thở. Chúng không còn đứng quan sát nữa, mà bò lên bằng tay và chân."
  },
  AvgDialog_19123_Content_18 = {
    Text = "Cộp——!"
  },
  AvgDialog_19123_Content_19 = {
    Text = "Ramona đã dùng hết sức lực để chém vỡ khóa cố định, cầu thang rơi xuống nhưng không phát ra một tiếng động nào khi rơi xuống."
  },
  AvgDialog_19123_Content_2 = {
    Text = "21:10\ncảng thị trấn - Brillport\nbến cảng thứ ba"
  },
  AvgDialog_19123_Content_20 = {
    Text = "Ít nhất chúng không thể leo lên tàu qua cầu thang tàu này."
  },
  AvgDialog_19123_Content_21 = {
    Text = "Khoan đã, điều này……"
  },
  AvgDialog_19123_Content_22 = {
    Text = "Giống như những cánh chim được vuốt ve bởi trời xanh, đôi mắt các bạn lướt qua làn gió dịu êm, thế giới trước mắt bỗng chốc thay đổi."
  },
  AvgDialog_19123_Content_23 = {
    Text = "Mặt trăng lớn biến mất trên bầu trời, ánh hào quang giống như cực quang khuấy động không gian bao quanh con tàu, những đốm sáng chiếu lên boong tàu cũng mang sắc màu lạ kỳ."
  },
  AvgDialog_19123_Content_24 = {
    Text = "Hiện tượng quét qua não các người, mất một lúc lâu các người mới lấy lại khả năng."
  },
  AvgDialog_19123_Content_25 = {
    Text = "Thú vị……"
  },
  AvgDialog_19123_Content_26 = {
    Text = "Ramona, bạn có ý kiến gì?"
  },
  AvgDialog_19123_Content_27 = {
    Text = "Thú vị, quá thú vị rồi. Cầu thang rơi xuống mà không phát ra tiếng động —— điều này có nghĩa là chúng ta có thể đang ở trong một không gian độc lập."
  },
  AvgDialog_19123_Content_28 = {
    Text = "Đây là <Yellow:thâm cảnh> có thể nhìn thấy bằng mắt thường!"
  },
  AvgDialog_19123_Content_29 = {
    Text = "Bảo vệ sương mù của trường học được điều khiển bởi <Yellow:Công nghệ Bạc Tâm>, không biết con tàu này sẽ nằm dưới sự kiểm soát của lực lượng nào?"
  },
  AvgDialog_19123_Content_3 = {
    Text = "Mùi tanh tưởi của thép gỉ xộc thẳng vào mũi, mỗi bước chân, cầu thang lại phát ra những tiếng rên xiết đầy nguy hiểm, như thể nó sắp sụp đổ đến nơi."
  },
  AvgDialog_19123_Content_30 = {
    Text = "Có phải là thân thể được đánh thức không?"
  },
  AvgDialog_19123_Content_31 = {
    Text = "Không có ghi chép tương tự trong hồ sơ, nhưng từ góc độ lý thuyết, việc thân thể được đánh thức tạo ra không gian độc lập là khả thi——bạn có muốn nghe lý thuyết cụ thể không?"
  },
  AvgDialog_19123_Content_32 = {
    Text = "Thả tôi ra đi……"
  },
  AvgDialog_19123_Content_33 = {
    Text = "Xem xét hoàn cảnh nhé!"
  },
  AvgDialog_19123_Content_34 = {
    Text = "Xin lỗi, mong bạn tha thứ cho sự tò mò của tôi."
  },
  AvgDialog_19123_Content_35 = {
    Text = "Đóa, các bạn có nghe thấy không?"
  },
  AvgDialog_19123_Content_36 = {
    Text = "Ramona chạm nhẹ vào huy hiệu, bề mặt thiết bị liên lạc như có ánh sáng lấp lánh lướt qua."
  },
  AvgDialog_19123_Content_37 = {Text = "Hả…?"},
  AvgDialog_19123_Content_38 = {
    Text = "Ramona nghiêng người, đưa tay chạm vào máy liên lạc của bạn. \nBạn cố gắng tập trung tinh thần như bình thường, nhưng không có tác dụng."
  },
  AvgDialog_19123_Content_39 = {
    Text = "Sức mạnh tinh thần giống như giọt nước mắt rơi vào đại dương, tĩnh lặng."
  },
  AvgDialog_19123_Content_4 = {
    Text = "Thiếu bảo trì sửa chữa, nhưng ngoài việc lỗi thời ra, thân tàu vẫn tương đối hoàn chỉnh."
  },
  AvgDialog_19123_Content_40 = {
    Text = "Máy liên lạc của tôi cũng đã mất kết nối."
  },
  AvgDialog_19123_Content_41 = {
    Text = "Từ bên ngoài, bộ thông tin trông không bị hư hại, nhưng không thể gửi tin nhắn."
  },
  AvgDialog_19123_Content_42 = {
    Text = "<Small:Sao lại có nhiều thứ như vậy có thể ngăn chặn liên lạc, lần trước ở bảo tàng sáp cũng vậy……>"
  },
  AvgDialog_19123_Content_43 = {
    Text = "Công nghệ được thúc đẩy bởi bạc tâm không phải là vạn năng. Hơn nữa, đối với chính bạc tâm, nghiên cứu của chúng ta vẫn còn ở bước đầu tiên."
  },
  AvgDialog_19123_Content_44 = {
    Text = "…… không thì, chúng ta vẫn nên xuống thuyền đi?"
  },
  AvgDialog_19123_Content_45 = {
    Text = "Hãy đi xung quanh boong tàu, biết đâu bạn sẽ tìm được cách khác để rời tàu."
  },
  AvgDialog_19123_Content_46 = {
    Text = "Cẩn thận xung quanh và cầu nguyện con tàu này đừng khởi hành nhé."
  },
  AvgDialog_19123_Content_47 = {
    Text = "<Big:ư———>"
  },
  AvgDialog_19123_Content_48 = {
    Text = "Như tiếng sáo của chim sơn ca hòa cùng giai điệu opera, tiếng còi tàu dài vang lên, đáp lại lời cầu nguyện của Ramona."
  },
  AvgDialog_19123_Content_5 = {
    Text = "Dấu hiệu xâm thực của nước biển không rõ ràng, dưới đường nước cũng không có con hà, hàu…"
  },
  AvgDialog_19123_Content_51 = {
    Text = "Tôi biết bạn muốn nói gì, nhưng làm ơn mà, không phải bây giờ."
  },
  AvgDialog_19123_Content_52 = {
    Text = "Chúng ta không thể đi theo tàu Sonanil ra biển, con tàu này có quá nhiều điểm đáng ngờ."
  },
  AvgDialog_19123_Content_53 = {
    Text = "Đi xem bên kia boong tàu, trên tàu lớn thường trang bị xuồng cứu sinh, biết đâu có thể hạ xuồng và rời đi bằng đường biển."
  },
  AvgDialog_19123_Content_54 = {
    Text = "Đợi đã… có vẻ như có tiếng gì đó."
  },
  AvgDialog_19123_Content_56 = {
    Text = "Khuôn mặt mang dáng dấp của loài cá xuất hiện trên boong tàu, những kẻ đã đuổi các người lên tàu đang dần ép sát."
  },
  AvgDialog_19123_Content_6 = {
    Text = "Bạn có phát hiện gì?"
  },
  AvgDialog_19123_Content_7 = {
    Text = "Tàu Sonanier thiếu các đặc điểm của một con tàu ma đã chìm, không phù hợp với bản ghi về việc nó đã chìm trong cơn bão."
  },
  AvgDialog_19123_Content_8 = {
    Text = "Nếu có cơ hội, tôi nhất định sẽ điều tra kỹ lưỡng về nguồn gốc của con tàu này…"
  },
  AvgDialog_19123_Content_9 = {
    Text = "Nhưng bây giờ rõ ràng không phải là thời điểm thích hợp."
