  AvgDialog_19124_Content_1 = {
    Text = "Á á… tại sao… tại sao!"
  },
  AvgDialog_19124_Content_2 = {
    Text = "Miriam trông có điều gì đó bất thường."
  },
  AvgDialog_19124_Content_3 = {
    Text = "Đúng lúc quá, mau cứu <Yellow:%player%> xuống!"
  },
  AvgDialog_19125_Content_1 = {
    Text = "Khi tâm trí của Miriam trở nên bất ổn, nhóm người dấn thân vào biển cũng dần mất đi trật tự, sự hỗn loạn bắt đầu lan rộng."
  },
  AvgDialog_19125_Content_2 = {
    Text = "Đuôi rắn quật mạnh vào thành cabin, âm vang kim loại rền rĩ."
  },
  AvgDialog_19125_Content_3 = {
    Text = "Bụi bẩn tích tụ lâu ngày cũng bị khuấy động, tạo nên một cơn mưa tuyết đen dày đặc dưới phòng động lực."
  },
  AvgDialog_19126_Content_1 = {
    Text = "Đuổi theo những vì sao"
  },
  AvgDialog_19126_Content_10 = {
    Text = "Dù bạn nghĩ đã xảy ra điều gì, mọi thứ đều do tôi quyết định, tôi mới là chủ của con tàu này. \nHilaster hầu như không có ý thức tự thân, làm sao có thể thay đổi tôi?"
