  AvgDialog_19126_Content_11 = {
    Text = "Thật sao?"
  },
  AvgDialog_19126_Content_12 = {
    Text = "Tôi có thể khiến cô ấy thức tỉnh, và tôi cũng có thể biến cô ấy trở về thành một vốc cát bạc."
