  AvgDialog_19126_Content_16 = {Text = "Ugh!"},
  AvgDialog_19126_Content_17 = {
    Text = "Cú tấn công đã đánh trúng vào lá chắn mà Ramona phát ra, ánh sáng lấp lánh chỉ kéo dài nửa giây, lá chắn liền vỡ nát."
