  AvgDialog_19126_Content_19 = {Text = "Ramona!"},
  AvgDialog_19126_Content_2 = {
    Text = "22:35\nSonanier Hào\nphòng động lực"
  },
  AvgDialog_19126_Content_20 = {
    Text = "Tôi không sao, bạn đừng qua đây!"
  },
  AvgDialog_19126_Content_21 = {
    Text = "Trong tình trạng phải phân tâm bảo vệ người, tôi không phải là đối thủ của người phụ nữ này. \nTôi sẽ cố gắng trì hoãn cuộc tấn công của cô ta, cậu hãy đưa họ đi trước."
  },
  AvgDialog_19126_Content_22 = {
    Text = "Bạn sẽ vội vàng đến gặp tôi, phải không?"
