  AvgDialog_19135_Content_3 = {Text = "Ừm…"},
  AvgDialog_19135_Content_4 = {
    Text = "Muphí à.."
  },
  AvgDialog_19135_Content_5 = {
    Text = "Đừng làm ồn! Làm phiền tôi đang suy nghĩ."
  },
  AvgDialog_19135_Content_6 = {
    Text = "Đối với việc \"đánh quấy nhiễu đến Muphí suy nghĩ\", bạn không tỏ thái độ rõ ràng. \n Nhưng bạn biết, nhất định phải ngăn cô ấy tiếp tục \"suy nghĩ\"."
  },
  AvgDialog_19135_Content_7 = {
    Text = "Bởi vì các bạn đã đi đi lại lại, lên lên xuống xuống trong khoang tàu cũng đã khá lâu rồi."
  },
  AvgDialog_19135_Content_8 = {
    Text = "Bạn có bị lạc đường không?"
