  AvgDialog_19135_Content_9 = {
    Text = "Không! Tôi không thể bị lạc đường!"
  },
  AvgDialog_19136_Content_1 = {
    Text = "Thuyền trưởng, anh có thể cho tàu cập bến ngay lập tức không?"
  },
  AvgDialog_19136_Content_2 = {
    Text = "Nếu có thể làm được việc này, Sonanil cũng không bị người dấn thân vào biển đuổi kịp."
  },
  AvgDialog_19136_Content_3 = {
    Text = "Lại gần hơn chút nữa, lại gần hơn… chỉ để các người rời đi… liệu có thể làm được không……\nBờ biển, như trong tầm tay."
  },
  AvgDialog_19136_Content_4 = {
    Text = "Chỉ cần đủ gần đất liền, bạn có cách để mọi người rời khỏi tàu, phải không, Hilaster?"
  },
  AvgDialog_19136_Content_5 = {
    Text = "Mọi người…"
  },
  AvgDialog_19136_Content_6 = {
    Text = "Cẩn thận, họ đã đuổi kịp chúng ta!"
  },
  AvgDialog_19137_Content_1 = {
    Text = "Chạy trốn"
  },
  AvgDialog_19137_Content_10 = {
    Text = "Người giữ bí mật, hãy biết điểm dừng."
  },
  AvgDialog_19137_Content_11 = {
    Text = "Tệ hại, quá tệ hại rồi."
  },
  AvgDialog_19137_Content_12 = {
    Text = "Sự diễn xuất giả tạo đã khiến khán giả la ó không ngừng. Khán giả với khuôn mặt khó chịu nhảy lên sân khấu và tấn công diễn viên chính — Muphí đã tung một cú khuỷu tay mạnh vào bụng bạn."
  },
  AvgDialog_19137_Content_13 = {
    Text = "Khụ, khụ khụ khụ!"
  },
  AvgDialog_19137_Content_14 = {
    Text = "Trả lời cô ấy một cách tràn đầy năng lượng"
  },
  AvgDialog_19137_Content_15 = {
    Text = "Để đáp lại sự quan tâm của người bạn đồng hành, bạn nở một nụ cười tràn đầy năng lượng, nụ cười méo mó, khoe tám chiếc răng đều đặn——khiến bạn trông giống như một tác phẩm của Rogers."
  },
  AvgDialog_19137_Content_17 = {
    Text = "Xem ra, khi tôi không có mặt, bạn sống khá thoải mái."
  },
  AvgDialog_19137_Content_18 = {
    Text = "Cũng, cũng không có…"
  },
  AvgDialog_19137_Content_19 = {
    Text = "Đúng vậy, tôi không thấy học sinh nào bị những người dấn thân vào biển rượt đuổi khắp nơi, cuối cùng va phải rồi đau lưng đến mức lăn lộn trên mặt đất."
  },
  AvgDialog_19137_Content_2 = {
    Text = "10 giờ 22 phút\nSơn Namiel\nphòng động lực"
  },
  AvgDialog_19137_Content_20 = {
    Text = "Muphí tiến lên phía trước, chen vào giữa bạn và Ramona —— đồng thời không quên va phải lưng bạn đang bị đau."
  },
  AvgDialog_19137_Content_21 = {Text = "Sī——"},
  AvgDialog_19137_Content_22 = {
    Text = "À, anh không định giới thiệu chúng ta với nhau sao?"
