  AvgDialog_19137_Content_23 = {
    Text = "Tôi tên là Muphí ——"
  },
  AvgDialog_19137_Content_24 = {
    Text = "Địch đã đụng mở cánh cửa sâu bên trong, lảo đảo xông tới chỗ các bạn."
  },
  AvgDialog_19137_Content_25 = {
    Text = "Trong làn bụi than do tín đồ khơi dậy, người phụ nữ cao gầy bước qua với sự thành kính và cuồng nhiệt."
  },
  AvgDialog_19137_Content_26 = {
    Text = "<BigShake:chạy nhanh lên!>"
  },
  AvgDialog_19137_Content_3 = {
    Text = "Người Giữ Bí Mật!"
