  AvgDialog_19137_Content_5 = {
    Text = "Biểu cảm của người bạn đồng hành chuyển đổi giữa ngạc nhiên, vui sướng và lo lắng, vẻ mặt sống động như vậy không phải lúc nào cũng thấy."
