  },
  AvgDialog_19144_Content_31 = {
    Text = "Đây không phải là nơi nên ở lâu."
  },
  AvgDialog_19144_Content_32 = {
    Text = "Muốn tìm đối tác càng ngày càng cấp bách. Bạn cố gắng chịu đựng cơn đau âm ỉ ở sau đầu cùng với cảm giác buồn nôn, vịn vào thành thuyền và bước đi hai bước."
  },
  AvgDialog_19144_Content_33 = {
    Text = "Đừng hành động vội vàng."
  },
  AvgDialog_19144_Content_34 = {Text = "Tulô?!"},
  AvgDialog_19144_Content_35 = {Text = "Bạn…"},
  AvgDialog_19144_Content_36 = {
    Text = "Tại sao bạn vẫn thức?"
  },
  AvgDialog_19144_Content_37 = {
    Text = "Thiếu niên đã được thức tỉnh liếc bạn một cái, ánh mắt bình tĩnh và uy nghiêm dừng lại trên bạn."
  },
  AvgDialog_19144_Content_38 = {
    Text = "Lần này, tôi sẽ coi như chưa nghe thấy những lời bất kính."
  },
  AvgDialog_19144_Content_39 = {
    Text = "Sao bạn cũng ở đây?"
  },
  AvgDialog_19144_Content_4 = {
    Text = "Trời sáng rồi…?"
  },
  AvgDialog_19144_Content_40 = {
    Text = "Thiếu niên với thân thể được thức tỉnh bất ngờ nhướng mày, ánh mắt đánh giá nhìn bạn vài lượt."
  },
  AvgDialog_19144_Content_41 = {
    Text = "Còn có thể đùa, xem ra cậu không sao cả."
  },
  AvgDialog_19144_Content_42 = {
    Text = "Giống như lơ-tan, Orci và những người khác, tulô là một trong nhiều thân thể được <Yellow:Misaque> giám sát. \nNhưng trong năm Misaque được huấn luyện, số lần bạn gặp tulô có thể đếm trên đầu ngón tay của một bàn tay."
  },
  AvgDialog_19144_Content_43 = {
    Text = "Được cho rằng hầu hết thời gian, tulô đều đang ngủ, số lần thức tỉnh có thể đếm trên đầu ngón tay. Do đó, tulô không nằm trong danh sách thân thể được đánh thức ngoài giờ hành chính."
  },
  AvgDialog_19144_Content_44 = {
    Text = "Nhưng lúc này, các người bị <Yellow:liên kết> vô hình buộc chặt, bạn có thể cảm nhận được năng lượng tinh thần mạnh mẽ như cơn bão của tulô."
  },
  AvgDialog_19144_Content_45 = {
    Text = "Tôi... và bạn có liên kết?!"
  },
  AvgDialog_19144_Content_46 = {
    Text = "Dại dột hỏi"
  },
  AvgDialog_19144_Content_47 = {
    Text = "Đợi đã, bạn có biết Ramona đang ở đâu không? Chúng ta đã rời trường cùng nhau."
  },
  AvgDialog_19144_Content_48 = {
    Text = "Bây giờ không phải lúc để đùa giỡn, thời gian còn lại không còn nhiều nữa."
  },
  AvgDialog_19144_Content_49 = {
    Text = "<Yellow:lễ triệu hồi thần linh> vẫn chưa kết thúc, các ngôi sao đang dần lên đến vị trí của chúng."
  },
  AvgDialog_19144_Content_5 = {
    Text = "Đau đầu chóng mặt, cảm giác nhói ở thái dương."
  },
  AvgDialog_19144_Content_50 = {
    Text = "\"lễ triệu hồi thần linh\"?"
  },
  AvgDialog_19144_Content_51 = {
    Text = "Vấn đề vừa thốt ra, không khí giữa bạn và tulô bỗng nhiên trở nên ngưng đọng, không khí nặng nề đến mức khiến người ta bắt đầu nghi ngờ liệu mình có đủ tư cách để hỏi anh ấy hay không."
  },
  AvgDialog_19144_Content_52 = {
    Text = "Nhưng, <Yellow:「Giáng Thần」> đối với Người Giữ Gìn Misaque mà nói, thực sự là một từ khóa quá nhạy cảm và quan trọng."
  },
  AvgDialog_19144_Content_53 = {
    Text = "Tulô, tôi…"
  },
  AvgDialog_19144_Content_54 = {
    Text = "Sẵn sàng đối phó."
  },
  AvgDialog_19144_Content_55 = {Text = "Cái gì?"},
  AvgDialog_19144_Content_56 = {Text = "Bịch.."},
  AvgDialog_19144_Content_57 = {
    Text = "Kèm theo âm thanh kỳ quái giống như tiếng vỗ của chân vịt lặn, kẻ thù lao ra từ trong bóng tối."
  },
  AvgDialog_19144_Content_6 = {
    Text = "Cổ họng cũng cảm thấy như đã nuốt một ngụm xì dầu cay, mỗi lần hít thở đều mang theo cảm giác nghẹt thở và đau đớn."
  },
  AvgDialog_19144_Content_7 = {
    Text = "Mở mắt, đau đầu, địa điểm xa lạ."
  },
  AvgDialog_19144_Content_8 = {
    Text = "Ôi trời ơi, chẳng lẽ không thể có một màn mở đầu sáng tạo hơn được sao?"
  },
  AvgDialog_19144_Content_9 = {
    Text = "Bạn đứng dậy, cảnh tượng không ngờ tới đột ngột hiện ra trước mắt."
  },
  AvgDialog_19145_Content_1 = {
    Text = "Địch tấn công không để lại cho Ramona nhiều thời gian phản ứng, thanh kiếm của cô thậm chí còn chưa kịp rút ra khỏi bao——"
  },
  AvgDialog_19145_Content_2 = {
    Text = "Lưỡi kiếm lớn bị ném mạnh mẽ từ xa về phía hai người, lực lượng lớn đến mức xé toạc không khí, tạo ra một làn sóng xung kích mạnh mẽ."
  },
  AvgDialog_19145_Content_3 = {
    Text = "Chiếc xúc tu cứng như thép quấn chặt lấy eo của Ramona, mạnh mẽ kéo cô ra khỏi điểm rơi của lưỡi kiếm khổng lồ."
  },
  AvgDialog_19145_Content_4 = {
    Text = "Sau khi Ramona đứng vững, các xúc tu của Tulô nhanh chóng rút lui và gia nhập hàng ngũ để chống lại cuộc tấn công."
  },
  AvgDialog_19145_Content_5 = {
    Text = "Xem ra bây giờ chúng ta phải hợp tác rồi."
  },
  AvgDialog_19145_Content_6 = {
    Text = "Không cần nói nhiều."
  },
  AvgDialog_19163_Content_1 = {
    Text = "Khởi đầu bi thảm"
  },
  AvgDialog_19163_Content_10 = {
    Text = "Không sao, các ngươi hãy đi gặp những người khác trước. \nTôi cần đi xác nhận lý do họ không tiếp tục tổ chức nghi lễ."
  },
  AvgDialog_19163_Content_11 = {
    Text = "Tulô đang điều tra một mình, anh ấy muốn xác nhận tại sao những người ra khơi vẫn tiếp tục hành động."
  },
  AvgDialog_19163_Content_12 = {
    Text = "Tulô? Vậy là sau vụ nổ, các người đã gặp nhau. Anh ấy không có biểu hiện gì bất thường sau trận chiến và vụ nổ chứ?"
  },
  AvgDialog_19163_Content_13 = {
    Text = "Bạn đã hồi tưởng kỹ về tất cả cuộc trao đổi với Tulô sau vụ nổ —— anh ta thể hiện sự bình tĩnh đáng kinh ngạc."
  },
  AvgDialog_19163_Content_14 = {
    Text = "Tulô tỉnh táo hơn tôi khi tôi vừa tỉnh lại, và không phát hiện gì bất thường từ liên kết."
  },
  AvgDialog_19163_Content_15 = {
    Text = "Bạn cẩn thận giấu liên kết giữa Tulô và Ramona ở sâu nhất trong thế giới tinh thần, vô thức che giấu tình trạng từng có cơn bão quét qua não bộ."
  },
  AvgDialog_19163_Content_16 = {
    Text = "Dome linh tri thức tan vỡ đang dần hồi phục, nỗi đau của linh hồn bị xé rách và ghép lại cũng dần mờ nhạt. Hiện tại, bạn không muốn gây thêm phiền phức mới cho người đồng hành đã kiệt sức."
  },
  AvgDialog_19163_Content_17 = {
    Text = "Bạn có mất ý thức không?!"
  },
  AvgDialog_19163_Content_18 = {
    Text = "Đừng lo lắng, tôi hiện giờ rất khỏe —— Hilaster đã chữa trị cho tôi hoàn toàn rồi."
  },
  AvgDialog_19163_Content_19 = {
    Text = "Bạn liếc nhìn Hilaster một cách áy náy, và cô ấy cũng ngẩng đầu nhìn lại. \nBạn nháy mắt với cô ấy, nhưng cô chỉ nhìn bạn một lúc mà không nói gì."
  },
  AvgDialog_19163_Content_2 = {
    Text = "Còn lại: 80 phút \n tới chính vị"
  },
  AvgDialog_19163_Content_20 = {
    Text = "Thôi được rồi, vì cậu đã nói thế…"
  },
  AvgDialog_19163_Content_21 = {
    Text = "Sinh vật ký sinh trong cơ thể Muphí cần phải được phẫu thuật tách bỏ càng sớm càng tốt, càng để lâu nó phát triển trong cơ thể Muphí, tình hình của mọi người sẽ càng nguy hiểm."
  },
  AvgDialog_19163_Content_22 = {
    Text = "Chúng ta cần phải trở lại đất liền nhanh chóng, nhưng… tôi không cảm nhận được chuyển động của tàu."
  },
  AvgDialog_19163_Content_23 = {
    Text = "Thuyền trưởng, trạng thái của các người đã không đủ để điều khiển tàu Sonaril quay về, phải không?"
  },
  AvgDialog_19163_Content_24 = {
    Text = "… Đúng vậy, việc Hilaster vẫn có thể tồn tại quả thực là một điều kỳ diệu, không chỉ đối với tôi mà còn đối với cô ấy nữa."
  },
  AvgDialog_19163_Content_25 = {
    Text = "Nếu sử dụng thuyền cứu sinh?"
  },
  AvgDialog_19163_Content_26 = {
    Text = "Elton lắc đầu."
  },
  AvgDialog_19163_Content_27 = {
    Text = "Thuyền cứu sinh không có động cơ, chở đông người như chúng ta mà phải chèo về đất liền? Quá không thực tế."
  },
  AvgDialog_19163_Content_28 = {
    Text = "Làm sao có thể… Thật sự chẳng còn cách nào khác nữa hay sao?"
  },
  AvgDialog_19163_Content_29 = {
    Text = "Elton vỗ nhẹ lên đầu Muphí một cách trấn an, vừa ngẩng đầu lên đã thấy mình bị ánh mắt lo lắng của bạn và Ramona bao quanh. Anh ấy thoáng ngẩn người, sau đó bật cười khẽ."
  },
  AvgDialog_19163_Content_3 = {
    Text = "Những rạn sơn này… mọc từ đâu ra?"
  },
  AvgDialog_19163_Content_30 = {
    Text = "Các bạn đừng quên đấy…"
  },
  AvgDialog_19163_Content_31 = {
    Text = "Sơn Năng Nhĩ hào, là một con tàu."
  },
  AvgDialog_19163_Content_32 = {
    Text = "Tôi đều đặn bảo dưỡng hệ thống động lực của nó theo hướng dẫn tiêu chuẩn mỗi năm, và phòng động lực của nó cũng luôn cháy."
  },
  AvgDialog_19163_Content_33 = {
    Text = "Chỉ cần có thể chạm vào bánh lái.."
  },
  AvgDialog_19163_Content_34 = {
    Text = "Có... cuộc chiến đấu của chúng ta với Miriam đã gây ra không ít hư hại cho phòng động lực, chưa kể đến vụ nổ mà cô ấy gây ra sau đó…"
  },
  AvgDialog_19163_Content_35 = {
    Text = "Ừm… tôi lại quên mất điểm này rồi…\nNếu không có nồi hơi cung cấp năng lượng, thì dù có đến phòng điều khiển cũng vô ích."
  },
  AvgDialog_19163_Content_36 = {
    Text = "Không… có ."
  },
  AvgDialog_19163_Content_37 = {
    Text = "Tôi và %player% đã đi vòng qua từ phòng động lực, mặc dù đã trở nên hoang tàn, nhưng vẫn còn ít nhất hai lò hơi đang cháy."
  },
  AvgDialog_19163_Content_38 = {
    Text = "Hai nồi hơi, đủ kiểm soát con tàu này."
  },
  AvgDialog_19163_Content_39 = {
    Text = "Bây giờ có thể đi xem buồng lái được chưa? Nói thật là tôi đã tò mò từ lâu rồi——"
  },
  AvgDialog_19163_Content_4 = {
    Text = "Ánh mắt lướt qua từng cây san hô sơn có hình dạng khác nhau, cuối cùng dừng lại ở cây san hô lớn nhất, thu hút ánh nhìn."
  },
  AvgDialog_19163_Content_40 = {
    Text = "Suỵt, suỵt, nhỏ giọng lại! Địch đang bị dẫn dụ tới đây!"
  },
  AvgDialog_19163_Content_5 = {
    Text = "Rạn sơn mọc từ dấu ăn mòn, thô bạo đẩy mở boong tàu, thẳng hướng lên vách ngăn phía trên."
  },
  AvgDialog_19163_Content_6 = {
    Text = "Chúng tôi gọi những thứ này là rối rắm sinh vật. \n Nói một cách đơn giản, càng gần tâm của hiện tượng ăn mòn khu vực, càng dễ xuất hiện các sinh vật."
  },
  AvgDialog_19163_Content_7 = {
    Text = "Rỗng rỗng… lại là rỗng rỗng."
  },
  AvgDialog_19163_Content_8 = {
    Text = "Trong nhóm người dấn thân vào biển xuất hiện cá thể dị thường bị ký sinh, có lẽ cũng liên quan chặt chẽ đến sự lan rộng của hiện tượng rỗng rỗng."
  },
  AvgDialog_19163_Content_9 = {
    Text = "Về điểm này……"
  },
  AvgDialog_19170_Content_1 = {
    Text = "Vết sao bí ẩn"
  },
  AvgDialog_19170_Content_10 = {
    Text = "Còn về nơi những người dấn thân vào biển cả đã đi… khi chúng tôi ra tới biển, tàu Sonanil đã hoàn toàn chìm xuống, chúng tôi chẳng tìm thấy gì cả."
  },
  AvgDialog_19170_Content_11 = {
    Text = "Goliath cũng đã rơi xuống?"
  },
  AvgDialog_19170_Content_12 = {
    Text = "Không rõ, có thể nó đã biến thành một con cá thật, có thể đã bị chết đuối, hoặc có thể đã chạy thoát bằng thuyền cứu sinh. Nhân tiện, chúng tôi đang cố gắng vớt lõi bạc của Miriam, nhưng tạm thời vẫn chưa có kết quả."
  },
  AvgDialog_19170_Content_13 = {
    Text = "Thôi không nói về những thứ này nữa, tôi đến đây để giải thích báo cáo kiểm tra cho bạn."
  },
  AvgDialog_19170_Content_14 = {
    Text = "Đóa đặt một chồng báo cáo giấy trên bàn làm việc, ra hiệu cho bạn tự mình lật xem."
  },
  AvgDialog_19170_Content_15 = {
    Text = "Nhưng sau ba ngày kiểm tra thân thể, bạn cảm thấy kiệt quệ cả tinh thần lẫn thể xác, mong muốn sớm nhận được câu trả lời."
  },
  AvgDialog_19170_Content_16 = {
    Text = "Cứ nói nếu có tin xấu, tôi chịu được."
  },
  AvgDialog_19170_Content_17 = {
    Text = "Thân thể của bạn…"
  },
  AvgDialog_19170_Content_18 = {
    Text = "Rất khỏe mạnh, ngoại trừ thiếu máu, không có gì bất thường."
  },
  AvgDialog_19170_Content_19 = {
    Text = "Đóa ngừng một chút, tiếp tục nói."
  },
  AvgDialog_19170_Content_2 = {
    Text = "Ba ngày sau · Đại học Misaque"
  },
  AvgDialog_19170_Content_20 = {
    Text = "Còn nguyên nhân gây ra tình trạng thiếu máu… ước tính ban đầu là do trong ba ngày kiểm tra này, đã lấy quá nhiều máu."
  },
  AvgDialog_19170_Content_21 = {
    Text = "Rất khỏe mạnh…sao lại thế? Tôi rõ ràng…"
  },
  AvgDialog_19170_Content_22 = {
    Text = "Dựa vào báo cáo của Ramona và những người khác, vết thương bạn bị trên tàu đủ để khiến một người bình thường chết đến chín lần. Ngay cả quái thú mèo cũng không chịu nổi sự tra tấn này."
  },
  AvgDialog_19170_Content_23 = {
    Text = "Tôi gần như bắt đầu nghi ngờ, liệu bạn có phải là người có dòng máu của gã khổng lồ không."
  },
  AvgDialog_19170_Content_24 = {
    Text = "Trái tim bạn đã nhảy lên đến họng, cảm giác căng thẳng khiến toàn thân bạn trở nên cứng ngắc."
  },
  AvgDialog_19170_Content_25 = {
    Text = "Nói đùa thôi, loài quái vật khổng lồ này không tồn tại trên thế giới, ít nhất là trong phạm vi thế giới loài người hiện nay."
  },
  AvgDialog_19170_Content_26 = {
    Text = "Lệnh cấm túc của bạn đã được giải trừ. Nếu bạn muốn trò chuyện với những người bạn đã trải qua sinh tử trên tàu Sonanier, họ đang ở sân trường để tiễn biệt thuyền trưởng."
  },
  AvgDialog_19170_Content_27 = {
    Text = "Tiễn đưa?!"
  },
  AvgDialog_19170_Content_28 = {
    Text = "Đúng, mặc dù Đại học Misaque không thiếu một chỗ để đặt chân, nhưng chính Elton rõ ràng không muốn ở lại đó mãi."
  },
  AvgDialog_19170_Content_29 = {
    Text = "Bạn vội vàng lấy áo khoác, lật người xuống giường và gật đầu với Đóa. Nhưng khi bạn sắp rời khỏi phòng ký túc xá, Đóa gọi bạn lại."
  },
  AvgDialog_19170_Content_3 = {
    Text = "Bạn hôm nay dậy sớm vậy, sao mặt mày lo lắng thế? Khi bạn có biểu cảm này, trông bạn rất giống William."
  },
  AvgDialog_19170_Content_30 = {
    Text = "……Tôi rất vui khi thấy bạn trở về nguyên vẹn và khỏe mạnh."
  },
  AvgDialog_19170_Content_31 = {
    Text = "Thôi được rồi, mau đi đi. Họ đang chờ bạn."
  },
  AvgDialog_19170_Content_32 = {
    Text = "Người giữ bí mật, chúng tôi ở đây."
  },
  AvgDialog_19170_Content_33 = {
    Text = "Tất cả mọi người đều đứng ở sân giữa trường, ba ngày không gặp, tinh thần của mọi người trông đã hồi phục khá nhiều."
  },
  AvgDialog_19170_Content_34 = {
    Text = "—— Ngoại trừ Hilaster. Cô vẫn giữ nguyên dáng vẻ bán trong suốt, mỏng manh như có thể bị một cơn gió thổi tan thành hình bóng ảo đẹp đẽ."
  },
  AvgDialog_19170_Content_35 = {
    Text = "Khi Sonaniel bị đánh bại và giải thể, làn gió trắng quen thuộc bao bọc lấy mọi người. Hilaster đã kích hoạt một cuộc dịch chuyển từ xa, đưa mọi người trở lại đất liền."
  },
  AvgDialog_19170_Content_36 = {
    Text = "Như một cái giá, tinh thần của Thuyền trưởng Elton đã bị tổn hại nghiêm trọng. Ngay cả sau khi được Đại học Misaque chữa trị, liên kết giữa ông và Hilaster cũng khó có thể khôi phục lại."
  },
  AvgDialog_19170_Content_37 = {
    Text = "Cô nghiên cứu viên nhỏ tuổi cuối cùng cũng thả bạn ra, tôi còn tưởng không thể gặp lại bạn trước khi rời đi, đang lo lắng lắm."
  },
  AvgDialog_19170_Content_38 = {
    Text = "Thuyền trưởng…"
  },
  AvgDialog_19170_Content_39 = {
    Text = "Nói ngắn gọn."
  },
  AvgDialog_19170_Content_4 = {
    Text = "Tôi vẫn đang nghĩ về những chuyện xảy ra trên biển... những người dấn thân vào biển, vị \"thần giả\" kia, biến thành bụi, và biến mất trên biển..."
  },
  AvgDialog_19170_Content_40 = {
    Text = "Thuyền trưởng đi đến bên bạn, vẫy tay về phía Hilaster, người có thân thể trong suốt đến mức chỉ còn lại một chút đường viền mờ ảo."
  },
  AvgDialog_19170_Content_41 = {
    Text = "Thân thể được đánh thức cũng giống như bạn vậy, không hiểu gì cả, nhưng vẫn lặng lẽ trôi đến bên bạn ——"
  },
  AvgDialog_19170_Content_42 = {
    Text = "Học sinh, đưa tay."
  },
  AvgDialog_19170_Content_43 = {Text = "(thò tay)"},
  AvgDialog_19170_Content_44 = {
    Text = "Elton cầm lấy tay trong suốt của cô ấy và đặt lên bàn tay bạn đã mở sẵn."
  },
  AvgDialog_19170_Content_45 = {
    Text = "Bất kể bạn dùng cách gì, hãy giữ cô ấy lại."
  },
  AvgDialog_19170_Content_46 = {
    Text = "Cô ấy đã chịu đủ đau khổ khi còn sống, không cần bắt cô ấy sống vì mong muốn của tôi."
  },
  AvgDialog_19170_Content_47 = {
    Text = "……Đây cũng là ước muốn của bạn sao?"
  },
  AvgDialog_19170_Content_48 = {
    Text = "Đội trưởng vì những lời nói từ thân thể đã được thức tỉnh mà ngẩn người ra, nhưng chỉ sau vài giây, ông ấy bật cười vui vẻ."
  },
  AvgDialog_19170_Content_49 = {
    Text = "Chuyến \"hành trình\" tiếp theo của Hilaster, tôi giao lại cho bạn."
  },
  AvgDialog_19170_Content_5 = {
    Text = "Từ nơi \"Thần giả\" tan biến làm gốc, các thế giới thâm cảnh gần đó đã trở nên đảo lộn. Đây là tình huống chưa từng xuất hiện sau khi tiêu diệt \"Thảm họa\" trong quá khứ."
  },
  AvgDialog_19170_Content_50 = {
    Text = "...Được."
  },
  AvgDialog_19170_Content_51 = {
    Text = "Khi liên kết với Hilaster, ý thức mỏng manh nhưng mạnh mẽ cuốn vào tâm trí bạn. \nDù đang đứng trên mặt đất, lồng ngực vẫn truyền đến cảm giác ngạt thở."
  },
  AvgDialog_19170_Content_52 = {
    Text = "Hình thể của Hilaster không còn mờ ảo, cô ấy thực sự tồn tại trong thế giới này."
  },
  AvgDialog_19170_Content_53 = {
    Text = "Elton vẫy tay chào tạm biệt lần cuối, các bạn tiễn anh ấy bước lên hành trình mới tìm kiếm quê hương đã mất."
  },
  AvgDialog_19170_Content_54 = {
    Text = "Nói đến đó, Kẻ khắc sét đâu? Anh ấy và thuyền trưởng lẽ ra thân thiết nhất, sao không đến tiễn anh ấy?"
  },
  AvgDialog_19170_Content_55 = {
    Text = "Ramona chỉ vào cây cảnh không xa, cậu thiếu niên ẩn trong bóng cây chính là Kẻ khắc sét. Cậu ta dõi theo chiếc xe khởi động, cho đến khi nó hoàn toàn biến mất trong thâm cảnh sương mù của Misaque."
  },
  AvgDialog_19170_Content_56 = {
    Text = "Tâm trạng của Kaikes... vẫn luôn u ám. Trong thời gian trên tàu, cuộc sống của anh ấy cũng đã biến đổi mạnh mẽ. Để anh ấy tĩnh tâm một chút."
  },
  AvgDialog_19170_Content_57 = {
    Text = "Có lẽ, bạn muốn đi gặp Muphí không?"
  },
  AvgDialog_19170_Content_58 = {
    Text = "Đại học Misaque\nNgoài ký túc xá thân thể được đánh thức"
  },
  AvgDialog_19170_Content_59 = {
    Text = "Muphí, là tôi."
  },
  AvgDialog_19170_Content_6 = {
    Text = "Trời long đất lở?"
  },
  AvgDialog_19170_Content_60 = {Text = "Vào đi."},
  AvgDialog_19170_Content_61 = {
    Text = "Phòng hậu cần đã chuẩn bị cho Muphí căn phòng ngủ sang trọng nhất. Khi bạn đẩy cửa vào, Muphí đang ngồi trên chiếc giường nệm len mềm mại uống trà, đĩa trà được đặt tùy tiện trên giường."
  },
  AvgDialog_19170_Content_62 = {
    Text = "Bạn… cảm thấy thế nào nhỉ?"
  },
  AvgDialog_19170_Content_63 = {
    Text = "Gì thế? Bạn đang nói về những món tráng miệng nhạt nhẽo của Đại học Misag? Hay là chúng ta đã thoát khỏi những người dấn thân vào biển? Hay là việc tôi đã trở thành thân thể được đánh thức?"
  },
  AvgDialog_19170_Content_64 = {
    Text = "Tôi, tôi… xin lỗi, tôi đã không xin phép bạn mà…"
  },
  AvgDialog_19170_Content_65 = {
    Text = "Bạn đã biến tôi thành thân thể được đánh thức, đúng không?"
  },
  AvgDialog_19170_Content_66 = {
    Text = "Xin lỗi, tôi biết có thể đây không phải là kết quả bạn mong muốn… nhưng tôi chỉ…"
  },
  AvgDialog_19170_Content_67 = {
    Text = "Tôi chỉ là... không muốn nữa.."
  },
  AvgDialog_19170_Content_69 = {
    Text = "Tôi cảm thấy rất nhẹ nhõm."
  },
  AvgDialog_19170_Content_7 = {
    Text = "Môi trường nguy hiểm hơn, dị thể mạnh hơn, khả năng của Công nghệ Bạc Tâm và thân thể được đánh thức đều bị hạn chế ở mọi nơi…… Đội tiên phong đã đặt tên cho tình huống này là<Yellow:「hòa hợp với thiên tai」>."
  },
  AvgDialog_19170_Content_70 = {
    Text = "Cảm giác tim không còn đập, thật sự rất xa lạ và đáng sợ. Nhưng…"
  },
  AvgDialog_19170_Content_71 = {
    Text = "Tôi thực sự cảm thấy một sự giải thoát chưa từng có."
  },
  AvgDialog_19170_Content_72 = {
    Text = "Biểu cảm của Muphí rất thoải mái, không giống như đang diễn. Dựa vào sự hiểu biết của bạn về cô ấy, cô ấy thực sự cũng không phải là người giỏi nói dối."
  },
  AvgDialog_19170_Content_73 = {
    Text = "Thật sao? Vừa rồi khi tôi từ biệt thuyền trưởng, bạn không có mặt, tôi còn tưởng…"
  },
  AvgDialog_19170_Content_74 = {
    Text = "Vì sao? Nghĩ rằng tôi đang khóc thầm dưới chăn sao?"
  },
  AvgDialog_19170_Content_75 = {
    Text = "Có gì mà buồn, anh ấy không nói với bạn sao? Anh ấy nói rằng mỗi năm vào đêm Ngân Sương đều sẽ đến thăm tôi và Kẻ khắc sét."
  },
  AvgDialog_19170_Content_76 = {
    Text = "Và thuyền trưởng còn kéo tôi uống trà từ sớm, nói nửa ngày về việc hy vọng tôi tự do, hy vọng tôi không bị ràng buộc bởi thân thể được đánh thức… hừ, lại còn phải để anh ta dạy tôi điều này sao?"
  },
  AvgDialog_19170_Content_77 = {
    Text = "Đúng rồi, có muốn thử chút đồ ăn vặt không? Bếp hôm nay làm bánh brownie ngon lắm ——"
  },
  AvgDialog_19170_Content_78 = {
    Text = "Vừa rồi ai nói rằng đồ ngọt ở đại học nhạt nhẽo……"
  },
  AvgDialog_19170_Content_79 = {
    Text = "Nĩa đã được đưa đến miệng, bạn cắn một miếng bánh."
  },
  AvgDialog_19170_Content_8 = {
    Text = "Tin tốt là, hòa hợp với thiên tai hiện đang giới hạn trong phạm vi cục bộ; tin xấu là, chúng ta hiện không thể kiểm soát sự xuất hiện và di chuyển của nó, giống như cố nắm bắt bóng cá trơn trong nước vậy."
  },
  AvgDialog_19170_Content_80 = {
    Text = "Vị chua, ngọt và đắng của sô-cô-la tan chảy đồng thời trong miệng, dầu từ các loại hạt khéo léo kết hợp nhiều tầng vị giác lại với nhau, khiến brun thực hiện điệu nhảy tinh tế trên đầu lưỡi của bạn."
  },
  AvgDialog_19170_Content_81 = {
    Text = "Bạn và Muphí ngồi bên giường, nói chuyện lẻ tẻ, ăn hết phần trà chiều và đồ tráng miệng của năm người."
  },
  AvgDialog_19170_Content_9 = {
    Text = "Tóm lại, vùng biển đó đã được hội nghị thẩm tra chỉ định là khu vực cấm do thiên tai hoà nhập. Tôi nghĩ, nó sẽ mãi biến mất khỏi bản đồ tài nguyên vốn đã khan hiếm của Vương quốc Leo."
  },
  AvgDialog_19196_Content_10 = {
    Text = "……hừ. \n<Small:cũng tạm, kẻ này ít nhất vẫn nhớ đến Ramona…>"
  },
  AvgDialog_19196_Content_11 = {
    Text = "Sự tiếp cận của người sống mang theo sức nóng của sức sống, trong bóng tối, một cơn đau nhói lan tỏa từ trán ra tứ chi."
  },
  AvgDialog_19196_Content_12 = {
    Text = "Có người gõ bằng đầu ngón tay vào trán bạn."
  },
  AvgDialog_19196_Content_13 = {Text = "Đau quá!"},
  AvgDialog_19196_Content_14 = {
    Text = "Còn cảm thấy đau, có nghĩa là bạn vẫn rất khỏe đấy."
  },
  AvgDialog_19196_Content_15 = {
    Text = "Tôi… vừa mới nhớ lại mọi thứ."
  },
  AvgDialog_19196_Content_16 = {
    Text = "Ramona, tulô, Thuyền trưởng Elton, Hilaster, những người dấn thân vào biển cả, và bạn cùng sinh vật ký sinh đó…"
  },
  AvgDialog_19196_Content_17 = {
    Text = "Thôi được, việc bạn buộc tôi và quái vật này lại với nhau tôi có thể chấp nhận. Nhưng tại sao bạn thậm chí không nhớ đến tôi trước những người dấn thân vào biển!"
  },
  AvgDialog_19196_Content_18 = {
    Text = "Tôi, tôi tuyệt đối không có ý đó…"
  },
  AvgDialog_19196_Content_19 = {
    Text = "Muphí hừ một tiếng, kéo bạn đứng dậy từ mặt đất."
  },
  AvgDialog_19196_Content_2 = {
    Text = "Khởi động lại thực tế"
  },
  AvgDialog_19196_Content_20 = {
    Text = "Tôi đã nói mà, sau vụ nổ bạn cư xử thật kỳ lạ, hóa ra thật sự bị va chạm ở đầu rồi…"
  },
  AvgDialog_19196_Content_21 = {
    Text = "Nhưng có một điểm tôi vẫn chưa thực sự hiểu……"
  },
  AvgDialog_19196_Content_22 = {
    Text = "Ai đã cứu mọi người khỏi hiện trường vụ nổ khi Miriam gây ra vụ nổ ở phòng động lực?"
  },
  AvgDialog_19196_Content_23 = {
    Text = "Phải là Hilaster rồi, trên con tàu này không có ai khác có thể phát ra thứ ánh sáng trắng đó đâu."
  },
  AvgDialog_19196_Content_24 = {
    Text = "Lòng đại dương trở nên sắc nhọn, nước biển phản ứng với làn da bị cháy tạo ra sự giằng co đến nghẹt thở. Sự hỗn loạn mù quáng tựa như những bóng ma trong đêm tối, xé toạc và nghiền nát thân thể bạn."
  },
  AvgDialog_19196_Content_25 = {
    Text = "Sau đó, từ trong hỗn loạn chợt lóe lên một tia ấm áp. Trong bóng tối mênh mông, nỗi cô đơn, sự bất lực và tuyệt vọng dần rút lui, để lại ánh sáng ấm áp kỳ bí tỏa sáng giữa vũ trụ giá lạnh."
  },
  AvgDialog_19196_Content_26 = {
    Text = "Dường như đã chạm vào lòng từ bi của vũ trụ, ý thức bước đi trên ranh giới của linh tri thức. Thân thể dần hòa tan vào oxy trong nước biển, bạn đột ngột mở mắt, và dòng nước biển tràn vào cơ thể qua khóe mắt."
  },
  AvgDialog_19196_Content_27 = {
    Text = "Cuối cùng, ánh sáng dịu dàng xé tan bóng tối dưới đáy biển. Lực lượng xanh trắng đưa tay về phía bạn —— tựa như thần nữ bảo hộ cho chuyến hải trình, giúp đỡ bạn."
  },
  AvgDialog_19196_Content_28 = {
    Text = "<Gray:Thật vậy, lực lượng kéo tôi ra khỏi nước chắc chắn thuộc về Hilaster.>"
  },
  AvgDialog_19196_Content_29 = {
    Text = "Bạn nhắm mắt lại, hồi tưởng về khoảnh khắc ngọn lửa thiêu đốt đôi mắt, ánh sáng ấm áp ấy đã xé toạc và tái hợp ý chí của bạn."
  },
  AvgDialog_19196_Content_3 = {
    Text = "Dậy đi, %player%, mau tỉnh dậy."
  },
  AvgDialog_19196_Content_30 = {
    Text = "<Gray:nhưng lực lượng đó trước đó… tuyệt đối không phải là Hilaster. Nó quá xa lạ, lại quá quen thuộc…>"
  },
  AvgDialog_19196_Content_31 = {
    Text = "Bạn đang ngẩn ngơ cái gì vậy? Không lẽ bị tôi gõ hỏng rồi sao? Tôi rõ ràng đã kiểm soát lực mà…"
  },
  AvgDialog_19196_Content_32 = {
    Text = "Muphí lẩm bẩm, nhón chân lên, đưa tay vuốt mái tóc của bạn. Khi cô ấy búng trán, cô ấy thực sự đã kiểm soát lực, đủ để làm cho người ta tỉnh táo, nhưng không đến nỗi đau cả buổi."
  },
  AvgDialog_19196_Content_33 = {
    Text = "Tôi chỉ đang lo lắng cho những người khác… Từ hiện trạng khi chúng ta gặp nhau, tình huống lúc vụ nổ xảy ra quá gấp gáp, Hilaster có lẽ đã không thể kiểm soát chính xác điểm rơi của mọi người."
  },
  AvgDialog_19196_Content_34 = {
    Text = "Phải nhanh chóng tìm thấy Ramona, sau đó gặp lại nhóm của thuyền trưởng."
  },
  AvgDialog_19196_Content_35 = {
    Text = "Thân thể bạn thật sự không sao rồi chứ? Nếu có cảm thấy khó chịu thì phải nói ngay nhé."
  },
  AvgDialog_19196_Content_36 = {
    Text = "Ừ, tôi sẽ làm."
  },
  AvgDialog_19196_Content_4 = {
    Text = "Đừng, đừng làm tôi sợ... Đừng ngủ nữa, mau tỉnh lại."
  },
  AvgDialog_19196_Content_5 = {
    Text = "Tiếng nức nở của thiếu nữ vang vọng trong tai, kéo ý thức của bạn ra khỏi dòng chảy ký ức."
  },
  AvgDialog_19196_Content_7 = {
    Text = "Ký ức như những hình ảnh chuyển cảnh, được đưa vào máy chiếu cũ kỹ của bạn từng tấm một. \nMỗi lần hình ảnh thay đổi, đều khiến linh hồn bạn phát ra tiếng thét từ sâu thẳm."
  },
  AvgDialog_19196_Content_8 = {
    Text = "Ừ… Ramon… na…"
  },
  AvgDialog_19196_Content_9 = {
    Text = "Bạn đang nói…"
  },
  AvgDialog_19200_Content_1 = {
    Text = "Chiến đấu chỉ kéo theo sự xuất hiện của nhiều kẻ thù hơn, tiếp theo phải cẩn thận hơn để tránh xung đột."
  },
  AvgDialog_19200_Content_10 = {
    Text = "Giờ thì coi như chúng ta hòa rồi."
  },
  AvgDialog_19200_Content_11 = {
    Text = "Tôi đã kiểm soát sức mạnh của mình, nếu không bạn đã bị tôi hất văng ra xa khoảng 9 mét rồi."
  },
  AvgDialog_19200_Content_12 = {
    Text = "Ha a?! Bạn đâu có sức mạnh như vậy. Đừng đùa nữa, tôi đã thấy hết cảnh bạn bị Miriam treo lên rồi!"
  },
  AvgDialog_19200_Content_13 = {
    Text = "Không khí u ám gần như dính đặc bị tan vỡ ngay lập tức, nỗi lo lắng và buồn bã trong mắt cô ấy bỗng nhiên bị lòng quyết tâm áp đảo."
