  AvgDialog_21392_Content_2 = {
    Text = "Đó... đó là cái gì vậy?!"
  },
  AvgDialog_21392_Content_3 = {
    Text = "Trên đường ray sắt phía trước hang tối, nơi ánh sáng chiếu đến, đứng một hình bóng dường như không thuộc về thế gian này."
  },
  AvgDialog_21392_Content_4 = {
    Text = "Phụ nữ có dáng người cao ráo, ánh mắt sắc bén như dao, thản nhiên đón nhận đoàn tàu đang lao đến."
