  AvgDialog_21801_Content_1 = {
    Text = "Bộ sưu tập bạn bè"
  },
  AvgDialog_21801_Content_10 = {
    Text = "Sao bạn đi đường lắt léo vậy, chân bị thương à?"
  },
  AvgDialog_21801_Content_11 = {
    Text = "Bạn quay đầu nhìn lại đoạn đường mình đã đi qua: để tránh dung dịch Dung Thực tràn ngập khắp mặt đất, dấu chân in trên nền bùn thành một đường cong kỳ quái."
  },
  AvgDialog_21801_Content_12 = {
    Text = "Hay là, hay là để Aurita cõng bạn đi nhé!"
  },
  AvgDialog_21801_Content_13 = {
    Text = "Không, không cần đâu. Tớ chỉ thấy đi kiểu này vui hơn thôi, Aurita không thấy thú vị sao?"
  },
  AvgDialog_21801_Content_14 = {
    Text = "Giống nhảy ô!"
  },
  AvgDialog_21801_Content_15 = {
    Text = "Đúng, giống nhảy ô."
  },
  AvgDialog_21801_Content_16 = {
    Text = "……Auretta, chúng ta chơi trò giẫm bóng nhé?"
  },
  AvgDialog_21801_Content_17 = {
    Text = "Tớ đi trước, cậu giẫm theo dấu chân tớ mà đi……được không?"
  },
  AvgDialog_21801_Content_18 = {
    Text = "Ừm…cũng không phải là không được đâu! Vậy bạn đi trước đi, Auretta sẽ chỉ đường cho bạn."
  },
  AvgDialog_21801_Content_19 = {
    Text = "Auretta ngoan ngoãn lùi lại hai bước nhường đường cho bạn, trong lúc nhảy nhót suýt chút nữa đã giẫm chân vào vũng dung dịch xói mòn."
  },
  AvgDialog_21801_Content_2 = {
    Text = "Hừ～hừ hừ hừ～"
  },
  AvgDialog_21801_Content_20 = {
    Text = "Bạn vội vàng kéo cô bé lại, cô bé chẳng hề hay biết, chớp chớp mắt, trên mặt vẫn tràn ngập niềm vui khi trò chơi bắt đầu."
  },
  AvgDialog_21801_Content_21 = {
    Text = "Bíp bíp—— Tàu lửa nhỏ xuất phát! Quảng trường trung tâm—— rẽ trái!"
  },
  AvgDialog_21801_Content_3 = {
    Text = "Aurita ngân nga giai điệu vui tươi, sánh bước cùng bạn trên con đường đã bị Dung Thực hòa tan."
  },
  AvgDialog_21801_Content_4 = {
    Text = "Những ô cửa sổ tối tăm không đèn cho thấy nơi đây đã vắng bóng người từ lâu, hai bên con đường tĩnh lặng chỉ còn lại những đường nét đổ nát của nhà cửa."
  },
  AvgDialog_21801_Content_5 = {
    Text = "Những cư dân đó đâu rồi? Liệu họ đã rời khỏi nhà trước khi hiện tượng Dung Thực bùng phát, liệu họ đã tìm được nơi ở mới, hay là……"
  },
  AvgDialog_21801_Content_6 = {
    Text = "Chất dịch đen sệt lặng lẽ chảy bên chân, bạn hít một hơi thật sâu, nén cơn buồn nôn suýt trào lên cổ họng."
  },
  AvgDialog_21801_Content_7 = {
    Text = "Hay là…… họ chưa bao giờ rời khỏi quê hương mà mình yêu thương?"
  },
  AvgDialog_21801_Content_9 = {
    Text = "Tiếng ậm ừ khi đang suy nghĩ nghiêm túc kéo bạn ra khỏi dòng suy tư, Aurita nhìn bạn từ đầu đến chân, cuối cùng mở miệng hỏi với vẻ khó hiểu."
  },
  AvgDialog_21803_Content_1 = {
    Text = "Cung điện dưới nước"
  },
  AvgDialog_21803_Content_10 = {
    Text = "Thật sao! Cảm ơn bà!"
  },
  AvgDialog_21803_Content_11 = {
    Text = "Bà Betty chỉ vài câu đã dỗ xong Aurita, dõi theo cô bé nhảy chân sáo chạy vào đống phế tích phía bên kia, rồi mới mỉm cười quay sang bạn."
  },
  AvgDialog_21803_Content_12 = {
    Text = "Bà cố tình chi Aurita đi, rốt cuộc muốn nói gì với tôi vậy?"
  },
  AvgDialog_21803_Content_13 = {
    Text = "Đừng quá đề phòng, ta chỉ muốn… kể một câu chuyện thôi."
  },
  AvgDialog_21803_Content_14 = {
    Text = "Ngày xưa, nơi đây là một cảng cá. Những người trẻ có hoài bão thì đến thành phố, cũng có người ở lại quê hương mưu sinh bằng nghề đánh cá… yên bình chẳng khác gì những làng chài khác."
  },
  AvgDialog_21803_Content_15 = {
    Text = "Sự thay đổi diễn ra lặng lẽ, lúc nào không hay, nơi đây chỉ còn lại phụ nữ và trẻ nhỏ."
  },
  AvgDialog_21803_Content_16 = {
    Text = "Từng chiếc thuyền đánh cá rời đi, nhưng chỉ có những mảnh sống tàu vỡ nát theo dòng hải lưu trôi về bờ biển."
  },
  AvgDialog_21803_Content_17 = {
    Text = "Dòng nước đen tràn qua đê chắn, đường phố bị xâm thực đến tan nát."
  },
  AvgDialog_21803_Content_18 = {
    Text = "Đến khi Aurita kịp nhận ra, bạn bè, gia đình cô bé, thậm chí cả cư dân của cả thị trấn nhỏ, đều đã biến mất không còn dấu vết…"
  },
  AvgDialog_21803_Content_19 = {
    Text = "Khoan đã, vậy còn bà thì sao ạ?"
  },
  AvgDialog_21803_Content_2 = {
    Text = "Bà lão tự xưng là Betty mỉm cười quan sát bạn, dường như đang kín đáo đánh giá tư cách \"bạn của Aurita\" của bạn."
  },
  AvgDialog_21803_Content_20 = {
    Text = "Bà lắc đầu, ra hiệu cho cậu nhìn xuống phần thân dưới của bà."
  },
  AvgDialog_21803_Content_21 = {
    Text = "Thứ chảy ra từ dưới chiếc váy dài vải thô, rõ ràng là dung dịch dung thực.\nPhần thân dưới của bà gần như hoàn toàn ngâm trong hủy diệt và hư vô."
  },
  AvgDialog_21803_Content_22 = {Text = "?！"},
  AvgDialog_21803_Content_23 = {
    Text = "Bà, bà hiện giờ cảm thấy thế nào ạ?"
  },
  AvgDialog_21803_Content_24 = {
    Text = "Bà lão bật cười phì, bà vỗ vỗ vai cậu, như một người trưởng bối thực sự."
  },
  AvgDialog_21803_Content_25 = {
    Text = "Đừng sợ, người trẻ, đừng sợ."
  },
  AvgDialog_21803_Content_26 = {
    Text = "\"Bà Betty\" đã biến mất từ lâu rồi, chính nỗi chấp niệm của đứa trẻ ấy đã giữ ta lại nơi đây."
  },
  AvgDialog_21803_Content_27 = {
    Text = "Trong lúc nói chuyện, một tờ truyền đơn không biết từ đâu bị gió thổi đến.\nHình ảnh trên tờ giấy đã bị dung dịch dung thực bôi đen gần hết, nhưng dòng chữ quảng cáo vẫn còn mờ mờ nhìn được."
  },
  AvgDialog_21803_Content_28 = {
    Text = "\"Tiệm bánh mì Betty, bánh mì thủ công của bà ngoại quê nhà\""
  },
  AvgDialog_21803_Content_29 = {
    Text = "Ôi chao… xem ra, \"Betty\" cũng chưa chắc là tên thật của ta."
  },
  AvgDialog_21803_Content_3 = {
    Text = "Hồi lâu, bà mới thu ánh mắt lại, vỗ vỗ lưng Aurita."
  },
  AvgDialog_21803_Content_30 = {
    Text = "…Tại sao bà lại kể cho cháu nghe những điều này?"
  },
  AvgDialog_21803_Content_31 = {
    Text = "Bà Betty nhìn về phía tòa nhà hoang đổ nghiêng không xa, Aurita đang ở đó \"tìm kho báu\", làm bụi bay mù mịt."
  },
  AvgDialog_21803_Content_32 = {
    Text = "Để Aurita không buồn, ta đã nói dối con bé rất nhiều."
  },
  AvgDialog_21803_Content_33 = {
    Text = "Ví dụ như…"
  },
  AvgDialog_21803_Content_34 = {
    Text = "\"Ngôi nhà dưới biển\""
  },
  AvgDialog_21803_Content_35 = {
    Text = "Cô ấy thậm chí còn kể cho cháu cả chuyện này sao? Có vẻ cô ấy thực sự rất tin vào lời nói dối đó……\nNhưng ngoài việc dệt nên những lời dối trá, bà ngoại thật sự của cô ấy còn có thể làm gì đây?"
  },
  AvgDialog_21803_Content_36 = {
    Text = "Chúng ta có thể nói với cô bé rằng, cha mẹ cô bé sẽ không bao giờ trở về nữa sao?\nỞ thị trấn không có tương lai này, những lời như vậy quá tàn nhẫn."
  },
  AvgDialog_21803_Content_37 = {
    Text = "Vì vậy, ta muốn nhờ cháu một việc……Xin cháu, xin cháu hãy giữ bí mật với cô bé."
  },
  AvgDialog_21803_Content_38 = {
    Text = "Đừng nói cho cô bé biết những gì đang xảy ra ngoài thực tế……Ít nhất, hãy để cô bé ra đi trong niềm vui."
  },
  AvgDialog_21803_Content_39 = {
    Text = "Đây là nguyện vọng của ta, và cũng là……nguyện vọng của cô ấy."
  },
  AvgDialog_21803_Content_4 = {
    Text = "Aurita, con tự đi chơi một lát được không.\nBà nói chuyện với người bạn mới này một chút, sẽ đến tìm con ngay."
  },
  AvgDialog_21803_Content_40 = {
    Text = "Giọng bà Betty chân thành, trong tiếng nói thậm chí còn mang theo sự van nài."
  },
  AvgDialog_21803_Content_41 = {Text = "Ra đi?"},
  AvgDialog_21803_Content_42 = {
    Text = "Rõ ràng chẳng có gì cả mà!"
  },
  AvgDialog_21803_Content_43 = {
    Text = "Bà thật sự giấu tượng gốm ở bên đó sao? Oreta đã lục tung hết rồi!"
  },
  AvgDialog_21803_Content_44 = {
    Text = "Giọng nói buồn bực của Oreta khiến cậu vô thức nhìn sang, cô bé đứng trên đống đổ nát quay lưng về phía cậu.\nLần này, cậu cuối cùng cũng nhìn rõ vết ố đen lóe lên trên lưng cô bé."
  },
  AvgDialog_21803_Content_45 = {
    Text = "Trên thân hình nhỏ bé ấy hiện rõ một khoảng trống — đó rõ ràng là một vết dung thực khổng lồ."
  },
  AvgDialog_21803_Content_46 = {
    Text = "Cậu sững người, quay đầu nhìn về nơi \"Bà Betty\" từng đứng.\nỞ đó chỉ còn lại một vũng chất lỏng nhầy nhụa, hòa lẫn vào dòng nước đen bẩn."
  },
  AvgDialog_21803_Content_47 = {
    Text = "Trong vũng nước bẩn, gốm sứ phản chiếu ánh sáng ấm áp dịu dàng."
  },
  AvgDialog_21803_Content_48 = {
    Text = "Nhặt tượng gốm lên"
  },
  AvgDialog_21803_Content_49 = {
    Text = "Thật bất ngờ, sau khi \"Bà Betty\" biến mất, thứ còn lại không phải là tượng gốm hình bà lão."
