  AvgDialog_21803_Content_5 = {
    Text = "Aurita không thể nói chuyện cùng sao?"
  },
  AvgDialog_21803_Content_50 = {
    Text = "Tán dù tròn đầy, những xúc tu mảnh và dày, trên nền sứ trắng điểm xuyết men xanh hình bốn lá."
