  AvgDialog_21803_Content_51 = {
    Text = "Waaaa— là con sứa mà Oreta thích nhất!"
  },
  AvgDialog_21803_Content_52 = {
    Text = "Cậu quả nhiên chơi gian! Lừa Oreta sang bên kia tìm, rõ ràng nó ở trong tay cậu mà!"
