  AvgDialog_21803_Content_54 = {
    Text = "Bạn nặn ra một nụ cười gượng gạo, lại lấy từ trong túi ra \"Pony\" và \"Bạch Tuyết\", cùng với tượng gốm \"Sứa\" đưa cho Aurita."
