  AvgDialog_22121_Content_2 = {
    Text = "Chúng ta đã đến!"
  },
  AvgDialog_22121_Content_20 = {
    Text = "Kể từ khi đến đây, chúng tôi thường chơi trò chơi này. Có lúc tôi đóng vai quý tộc, có lúc Colette đóng."
