  },
  AvgDialog_22121_Content_22 = {
    Text = "Chiếc váy đỏ này, là do cô ấy dùng nước ép từ cánh hoa hồng để vẽ lên… Hiện tại đã không còn nhìn rõ nữa, thật đáng tiếc."
  },
  AvgDialog_22121_Content_23 = {
    Text = "Ngón tay của Ôrla nhẹ nhàng lướt qua bức tranh đơn giản, khóe miệng khẽ cong lên."
