  AvgDialog_22121_Content_25 = {
    Text = "Cũng là người bạn tốt nhất của tôi."
  },
  AvgDialog_22121_Content_26 = {
    Text = "Khi còn nhỏ sống trong nhà hoa, mặc dù cũng rất tốt, nhưng có chút chật chội. Chúng tôi đã mơ ước rằng, một ngày nào đó có thể có một căn nhà nhỏ phía trên."
