  AvgDialog_22121_Content_28 = {
    Text = "Ôrla nhìn với ánh mắt tiếc nuối vào biệt thự hoa lệ trước mắt, rồi tiếp tục đi về phía trước."
  },
  AvgDialog_22121_Content_29 = {
    Text = "Người giữ bí mật {Male=ngài,Female=cô}, đi qua khu vườn hồng này, chúng ta sắp đến rồi."
  },
  AvgDialog_22121_Content_3 = {
    Text = "Đi qua đại lộ Medici sầm uất ở Tây Đài, đi về hướng đông bắc, bạn sẽ sớm đến một khu căn hộ xinh đẹp."
