  AvgDialog_22121_Content_33 = {
    Text = "Ừ! Vào thời điểm đó, chúng tôi vừa bị đuổi khỏi ngôi biệt thự cũ, không có nơi nào để đi……"
  },
  AvgDialog_22121_Content_34 = {
    Text = "Chờ đã! Colette... Tôi vừa thấy biển số nhà. Ở đây là vườn của phu nhân bá tước?"
  },
  AvgDialog_22121_Content_35 = {
    Text = "Bạn không phải nói là đã lâu chưa nhìn thấy vườn hoa à? Nào, đây chính là vườn hoa đẹp nhất khu vực này."
  },
  AvgDialog_22121_Content_36 = {
