  AvgDialog_22121_Content_45 = {
    Text = "Nhưng… bạn làm thế nào đây…"
  },
  AvgDialog_22121_Content_46 = {
    Text = "Cô ấy mới nhận ra rằng chiếc vòng cổ mà mẹ của Colette để lại cho cô không còn đeo trên cổ cô."
  },
  AvgDialog_22121_Content_47 = {
    Text = "Kolette! Bạn…"
  },
  AvgDialog_22121_Content_48 = {
    Text = "Điều đó không quan trọng, Ôrla. Điều quan trọng là, đây không phải là khu vườn của một bá tước——đây là khu vườn của chúng ta."
  },
  AvgDialog_22121_Content_49 = {
    Text = "Từ nay, chúng ta sẽ cùng ngủ và nấu ăn trong vườn nhé. Tôi sẽ dùng những bông hoa từ mảnh đất này để mua quần áo và thức ăn cho chúng ta."
  },
  AvgDialog_22121_Content_5 = {
    Text = "Tuy nhiên…… tại sao nơi này lại trở nên như thế này nhỉ?"
  },
  AvgDialog_22121_Content_50 = {
    Text = "Một ngày nào đó, ngay cả những ngôi nhà trong tòa nhà ở trên kia, tôi cũng sẽ mua!"
  },
  AvgDialog_22121_Content_51 = {
    Text = "Nhưng... tôi có thể làm gì đây.."
  },
  AvgDialog_22121_Content_52 = {
    Text = "Ngoài việc viết một số bài thơ ít người đọc, tôi không thể giúp gì khác…"
  },
  AvgDialog_22121_Content_53 = {
    Text = "Thành thật mà nói, những bài thơ của bạn tôi cũng không hiểu…… Tuy nhiên, điều đó không quan trọng. Bạn cứ viết những bài thơ bạn muốn viết thôi."
  },
  AvgDialog_22121_Content_54 = {
    Text = "Mỗi người đều có việc phải làm ngay từ khi sinh ra. Tôi sinh ra là để cố gắng vì khu vườn này, vì nhà kia…"
  },
  AvgDialog_22121_Content_55 = {
    Text = "Và bạn, bạn được sinh ra với sứ mệnh viết nên những vần thơ."
