  AvgDialog_22121_Content_56 = {
    Text = "Sau đó, cô ấy đã nuôi sống chúng tôi cả hai bằng những bông hoa trong vườn này."
  },
  AvgDialog_22121_Content_57 = {
    Text = "Dù rất vất vả, khoảng cách để mua được nhà vẫn còn rất xa, nhưng tôi có thể cảm nhận được rằng, trong khoảng thời gian đó, chúng tôi thực sự sống rất vui vẻ."
  },
  AvgDialog_22121_Content_58 = {
    Text = "Cho đến một ngày, nhà xuất bản gửi cho tôi khoản nhuận bút đầu tiên cho những bài thơ của tôi…"
  },
  AvgDialog_22121_Content_59 = {
    Text = "Mặc dù sau đó cô ấy đã khóa bạn trong nhà hoa và phóng hỏa, nhưng dường như bạn không hề ghét cô ấy."
