  AvgDialog_22121_Content_69 = {
    Text = "Chúng ta đã đến!"
  },
  AvgDialog_22121_Content_7 = {
    Text = "Càng gần đây, màu sắc xung quanh càng trở nên u ám… Những điều này, có phải cũng xuất phát từ trí tưởng tượng trong tập thơ của bạn không?"
