  },
  AvgDialog_22125_Content_100 = {
    Text = "Đi nào, Người Giữ Gìn {Male=ngài,Female=cô}, chúng ta đến vườn hồng… nơi tôi đã chết."
  },
  AvgDialog_22125_Content_11 = {
    Text = "Ôrla tắm trong ánh sáng, hai chân lắc lư trong không trung, vỗ theo một nhịp điệu không rõ tên."
  },
  AvgDialog_22125_Content_12 = {
    Text = "Tôi nhớ báo chí có nói rằng, con phố Ba Tháng vốn là một con phố bình thường, nhưng nhờ một họa sĩ vẽ bức tranh cho quán cà phê này mà nó bắt đầu trở nên nổi tiếng."
  },
  AvgDialog_22125_Content_13 = {
    Text = "Tôi rất thích câu chuyện này, từng viết một bài thơ về nó. Trong bài thơ đó, họa sĩ cuối cùng đã định cư tại số 99, cuối con phố Tháng Ba."
  },
  AvgDialog_22125_Content_14 = {
    Text = "Tuy nhiên, tôi nghĩ rằng không phải là Đường Ba Tháng gặp được họa sĩ, mà chính là họa sĩ đã gặp được Đường Ba Tháng mới đúng."
  },
  AvgDialog_22125_Content_15 = {
    Text = "Tây Đài trở nên kỳ lạ như vậy, bạn có vẻ không hề sợ hãi, thậm chí còn rất thích thú?"
  },
  AvgDialog_22125_Content_16 = {
    Text = "Ở đây không cần tiếp xúc với người khác, vẫn có thể gặp được nhiều điều mới lạ."
  },
  AvgDialog_22125_Content_17 = {
    Text = "Tôi không rõ lý do. Tuy nhiên, tôi luôn cảm nhận rằng, so với Tây Đài trên báo và ảnh, nơi này quen thuộc hơn với tôi…"
  },
  AvgDialog_22125_Content_18 = {
    Text = "À, bạn xem, Người giữ gìn {Male=ngài,Female=cô}! Là những ngôi sao!"
  },
  AvgDialog_22125_Content_19 = {
    Text = "Sao? Nhưng có vẻ như ở đây không có ban ngày và ban đêm…"
  },
  AvgDialog_22125_Content_2 = {
    Text = "Hai, hai cốc cà phê… cảm ơn."
  },
  AvgDialog_22125_Content_20 = {
    Text = "Bạn ngẩng đầu lên. Bên cạnh những ngôi sao lấp lánh ánh vàng, những cánh hoa trắng đã nở rộ."
  },
  AvgDialog_22125_Content_21 = {
    Text = "Những ngôi sao lớn như những bông hoa sen đã biến bầu trời thành một khu vườn."
  },
  AvgDialog_22125_Content_22 = {
    Text = "Tây Đài là một thành phố của thơ và hoa…… Nếu không có những việc khẩn cấp, nơi này khá dễ chịu."
  },
  AvgDialog_22125_Content_23 = {
    Text = "Sau ba mươi phút, gặp khoảng hơn một trăm người dân, không bị tấn công…… chiếc xe điện đó chắc không lừa chúng ta."
  },
  AvgDialog_22125_Content_24 = {
    Text = "À, hóa ra Người giữ gìn {Male=ngài,Female=cô} đã quan sát từ trước phải không?"
