  AvgDialog_22125_Content_25 = {
    Text = "Không sao, có người ngắm nhìn những ngôi sao trên trời, thì cũng cần có người chú ý đến mặt đất dưới chân."
  },
  AvgDialog_22125_Content_26 = {
    Text = "Dù không có tài năng về thơ ca, nhưng dù sao cũng là Người Giữ Gìn của Misaque, cũng có thể làm được."
