  AvgDialog_22127_Content_57 = {Text = "Vâng."},
  AvgDialog_22127_Content_58 = {
    Text = "Quả nhiên, ngay cả con phố nổi tiếng nhất này cũng không biết…"
  },
  AvgDialog_22127_Content_59 = {
    Text = "Hãy yên tâm, hãy yên tâm, người dân Tây Đài đều rất nhiệt tình và hiếu khách. Đại lộ Medici nằm ở…"
  },
  AvgDialog_22127_Content_6 = {
    Text = "Bạn đi qua những con đường mờ ảo, vuốt ve những viên gạch trên kiến trúc, hái lá cây ngô đồng như mực màu."
  },
  AvgDialog_22127_Content_60 = {Text = "Ừ——"},
  AvgDialog_22127_Content_61 = {
    Text = "Vị tiên sinh ong này chưa nói xong, đột nhiên cả người bắt đầu co giật."
  },
  AvgDialog_22127_Content_62 = {
    Text = "Một đôi cánh màng lớn xé toạc áo của anh ta, giống như bơ dưới nắng nóng chảy nhanh chóng, rồi rơi xuống."
  },
  AvgDialog_22127_Content_63 = {
    Text = "Mật, ông Mật!……"
  },
  AvgDialog_22127_Content_64 = {Text = "Pa——"},
  AvgDialog_22127_Content_65 = {
    Text = "Cơ thể con ong hình người rơi xuống đất, biến thành màu đen, sau đó hóa thành một đống bột và tan biến trong không khí."
  },
  AvgDialog_22127_Content_66 = {
    Text = "Không phải là biểu hiện điển hình của rỗng rỗng…"
  },
  AvgDialog_22127_Content_67 = {
    Text = "Bạn lại cẩn thận quan sát môi trường xung quanh."
  },
  AvgDialog_22127_Content_68 = {
    Text = "Những tòa nhà giống như những bức tranh trừu tượng bao quanh bạn. Xa xa, thỉnh thoảng xuất hiện những cư dân, quan sát kỹ, bạn có thể thấy trên thân thể họ có nhiều đặc điểm giống như động vật và thực vật."
  },
  AvgDialog_22127_Content_69 = {
    Text = "—— Tây Đài trước mặt, giống như được chuyển từ một giấc mơ quái dị nào đó vậy."
  },
  AvgDialog_22127_Content_7 = {
    Text = "Thành phố này dường như bị phủ lên một lớp bộ lọc kỳ lạ, tất cả các tòa nhà và thực vật đều giống như những bức tranh được vẽ bằng bút nước màu, hiên ngang một cách kỳ lạ với hình ảnh cực kỳ không hợp lý."
  },
  AvgDialog_22127_Content_70 = {Text = "Ding——"},
  AvgDialog_22127_Content_71 = {
    Text = "Huân chương trên ngực lấp lánh ánh bạc. Bạn thiết lập liên lạc."
  },
  AvgDialog_22127_Content_72 = {
    Text = "Giáo sư Đóa, tôi vừa gặp một dị biến thể rỗng rỗng không điển hình…"
  },
  AvgDialog_22127_Content_73 = {
    Text = "Tây Đài gọi đến. Một cư dân đã biến thành bột ăn mòn ở một con đường đông đúc trong khu phố."
  },
  AvgDialog_22127_Content_74 = {Text = "!!!"},
  AvgDialog_22127_Content_75 = {
    Text = "Và tình huống tôi gặp phải……giống hệt nhau……"
  },
  AvgDialog_22127_Content_76 = {
    Text = "Tôi đang ở Tây Đài, nơi này hoàn toàn không giống như phố thị nhộn nhịp."
  },
  AvgDialog_22127_Content_77 = {
    Text = "Đây cũng không thấy được giao diện giữa thế giới thực và thâm cảnh. Nhưng nếu không phải là thâm cảnh, thì tại sao nơi này và những người này lại trở nên như vậy…… thật không hợp lý……"
  },
  AvgDialog_22127_Content_78 = {
    Text = "Nhìn vậy, có vẻ như thâm cảnh này không giống với những thâm cảnh thông thường, mà là một không gian độc lập hoàn toàn."
  },
  AvgDialog_22127_Content_79 = {
    Text = "Nhưng ảnh hưởng của nó đối với Tây Đài vẫn tồn tại một cách rõ ràng."
  },
  AvgDialog_22127_Content_8 = {
    Text = "Người giữ bí mật {Male=ngài,Female=cô}, ngài có thấy ngôi nhà này không, trên đó dường như có một số đường nét đang nổi lên?"
  },
  AvgDialog_22127_Content_80 = {
    Text = "Dù sao, trước khi việc này lan rộng hơn, phải nhanh chóng tìm ra nguyên nhân."
  },
  AvgDialog_22127_Content_81 = {
    Text = "Hiểu rồi."
  },
  AvgDialog_22127_Content_82 = {
    Text = "Kết thúc liên lạc, không khí trở nên nặng nề."
  },
  AvgDialog_22127_Content_83 = {
    Text = "Người giữ bí mật {Male=ngài,Female=cô}…… ông ong, đã chết rồi sao?"
