  AvgDialog_22127_Content_86 = {
    Text = "Mong là như vậy……"
  },
  AvgDialog_22127_Content_87 = {
    Text = "Ôrla lấy một chiếc lá ngô đồng và đặt nó lên những hạt bột rỗng rỗng còn sót lại."
  },
  AvgDialog_22127_Content_88 = {
    Text = "Đi thôi, đến Đại lộ Medici, tìm người liên lạc để điều tra rõ ràng."
  },
  AvgDialog_22127_Content_9 = {
    Text = "Như những bài thơ được viết trên kiến trúc… thật đẹp làm sao!"
  },
  AvgDialog_22127_Content_90 = {
    Text = "Quý vị xem, Người Giữ Gìn {Male=ngài,Female=cô}! Có xe điện!"
  },
  AvgDialog_22127_Content_91 = {
    Text = "Các người đi tiếp một đoạn đường. Một khối đen mờ mịt lao đến phía các người."
  },
  AvgDialog_22127_Content_92 = {
    Text = "Có xe điện, nhưng không tìm thấy bảng chỉ dẫn, không biết có thể đến nơi chúng tôi muốn đi không."
  },
  AvgDialog_22127_Content_93 = {
    Text = "Tôi có kể với ngài chưa? Từ hàng rào của khu vườn cũ, có thể nhìn thấy xe điện chạy qua, nhưng tôi chưa bao giờ thực sự ngồi trên đó."
  },
  AvgDialog_22127_Content_94 = {
    Text = "Tôi rất muốn được ngồi một lần. Tôi nghĩ, nó có thể chở tôi đi bất cứ nơi đâu."
  },
  AvgDialog_22127_Content_95 = {
    Text = "Mỗi lần nhìn thấy chiếc xe điện đó, tôi đều cảm thấy nó giống như một con quái vật khổng lồ……"
  },
  AvgDialog_22127_Content_96 = {
    Text = "Xin chào, bạn có cần đón xe không ạ?"
