  AvgDialog_22128_Content_12 = {Text = "Hannah."},
  AvgDialog_22128_Content_13 = {
    Text = "Xin vui lòng chờ Người Giữ Gìn!Tôi có việc gấp cần tìm cô Ninh Phi Nga!Rất có thể đây sẽ là tin tức nổi bật!"
