  AvgDialog_22129_Content_11 = {
    Text = "Cái lồng này có thể là sản phẩm của sự hư không, hãy giúp tôi giành thêm chút thời gian, tôi sẽ cố gắng thoát khỏi đây càng sớm càng tốt."
  },
  AvgDialog_22129_Content_12 = {
    Text = "À, tôi suýt quên mất, bạn vẫn ngại ngùng như vậy đấy, Ôrla."
