  AvgDialog_22130_Content_32 = {
    Text = "……theo thống kê, số lượng trường hợp mục kích hiện đã vượt qua mười."
  },
  AvgDialog_22130_Content_33 = {
    Text = "Theo mô tả của nhân chứng, sự thay đổi ở Tây Đài dường như không phải do hiện tượng rỗng rỗng thông thường gây nên."
  },
  AvgDialog_22130_Content_34 = {
    Text = "Bây giờ Tây Đài, rất.."
  },
  AvgDialog_22130_Content_35 = {
    Text = "Rất……?"
  },
  AvgDialog_22130_Content_36 = {
    Text = "Theo lời của người chứng kiến, \"rất đẹp\"."
  },
  AvgDialog_22130_Content_37 = {
    Text = "Rỗng rỗng…rất đẹp?"
