  AvgDialog_22130_Content_55 = {
    Text = "Tôi… không thực sự muốn…"
  },
  AvgDialog_22130_Content_56 = {
    Text = "Những bài thơ đó, chỉ mang lại bất hạnh cho mọi người… Tôi không muốn chuyện này xảy ra nữa."
  },
  AvgDialog_22130_Content_57 = {
    Text = "Nhớ lại những chuyện đã qua của Ôrla, bạn hiểu ý cô ấy và gật gù."
  },
  AvgDialog_22130_Content_58 = {
    Text = "Tôi vẫn nên sống bên ngoài trường học, không nên ở những nơi đông người như trường học……"
  },
  AvgDialog_22130_Content_59 = {
    Text = "Người giữ bí mật {Male=ngài,Female=cô}, có thể xin quý vị giúp tôi nghĩ cách được không?"
  },
  AvgDialog_22130_Content_6 = {
    Text = "Ôrla thò đầu ra từ dưới tờ giấy da cừu khổng lồ, cẩn thận quan sát xung quanh."
  },
  AvgDialog_22130_Content_60 = {
    Text = "Thực sự, đối mặt với khứu giác nhạy bén và tốc độ phản ứng nhanh nhẹn của con chồn tuyết, tôi cũng không nghĩ ra được cách nào hay hơn."
  },
  AvgDialog_22130_Content_61 = {
    Text = "—— Tuy nhiên, nếu bạn sẵn lòng ra ngoài, thì có một cách có thể giúp bạn."
  },
  AvgDialog_22130_Content_62 = {
    Text = "À… nhất định phải ra ngoài sao.."
