  },
  AvgDialog_22130_Content_65 = {
    Text = "Tây Đài, quê hương của bạn."
  },
  AvgDialog_22130_Content_66 = {
    Text = "Tàu du lịch trôi im lìm, hai bên là những ngôi nhà và bụi hoa từ từ lùi về phía sau, biến mất ở khúc cua êm đềm của sông Sông Sêrêpôk."
  },
  AvgDialog_22130_Content_67 = {
