  AvgDialog_22130_Content_69 = {
    Text = "Mặc dù đã qua nhiều năm, nhưng tôi chỉ cần ngửi thấy là nhớ ngay được."
  },
  AvgDialog_22130_Content_7 = {
    Text = "Sau khi xác nhận xung quanh không có người lạ, cô ấy thở phào nhẹ nhõm và chui ra từ dưới cuộn giấy cổ."
  },
  AvgDialog_22130_Content_70 = {
    Text = "Cảnh đẹp của Tây Đài, bạn có thấy nhớ không?"
