  AvgDialog_22130_Content_75 = {
    Text = "Mỗi khi đến mùa hoa hồng nở, khu vườn đó đều đầy hoa hồng, giống như đang sống trong một giấc mơ!"
  },
  AvgDialog_22130_Content_76 = {
    Text = "Chỉ là không biết, sau trận hỏa hoạn kia, bây giờ nơi đó còn hoa hồng không. Còn tập thơ nữa không…"
  },
  AvgDialog_22130_Content_77 = {
    Text = "Khi ngọn lửa bùng lên, tôi thấy không thể chạy ra ngoài, nên đã chôn tập thơ tôi viết trong vườn. Lần này khi trở về, tôi muốn tìm lại nó."
