  AvgDialog_22130_Content_82 = {
    Text = "Dù là muốn giữ gìn hay hủy bỏ, tôi đều muốn tìm thấy nó."
  },
  AvgDialog_22130_Content_83 = {
    Text = "Hãy yên tâm, tôi nhất định sẽ đưa bạn đi xem. Chỉ là không biết qua bao nhiêu năm như vậy, còn có thể tìm được không."
  },
  AvgDialog_22130_Content_84 = {
