  AvgDialog_22130_Content_86 = {
    Text = "Nếu bướm đậu trên người ai đó, điều đó có nghĩa là trong mắt bướm, cuộc sống của người đó giống như một bông hoa."
  },
  AvgDialog_22130_Content_87 = {
    Text = "Trong mắt người Tây Đài, một sức sống tươi đẹp như đóa hoa luôn có thể gặp nhiều may mắn~"
