  AvgDialog_23352_Content_6 = {
    Text = "Ở góc cầu thang treo một bức chân dung được đóng khung tinh xảo, phía trên được vẽ bằng những nét bút dịu dàng mờ ảo, khắc họa một vị phụ nữ ăn mặc xa hoa."
