  AvgDialog_23355_Content_24 = {
    Text = "Nghe nói phu nhân Soreil sau khi chết đã hóa thành một nhúm Ngân Tâm, hiện đang ở bộ phận Thức Tỉnh để tiếp nhận chiết xuất, chờ đợi <Yellow:lần Thức Tỉnh thứ hai>?"
  },
  AvgDialog_23355_Content_25 = {
    Text = "Tin tức nhanh nhạy lắm nhỉ. Nhưng tỷ lệ thành công của Thức Tỉnh lần hai cực kỳ thấp, đừng đặt hy vọng vào đó."
  },
  AvgDialog_23355_Content_26 = {
    Text = "Hiểu rồi, tôi chỉ không ngờ Thức Tỉnh Thể sau khi chết vẫn có thể tách ra Ngân Tâm. Vậy Thức Tỉnh Thể mới có gì khác so với trước?"
  },
  AvgDialog_23355_Content_27 = {
    Text = "Sẽ kế thừa ký ức và tính cách của người tiền nhiệm, nhưng năng lực sẽ kém xa trước đây.\nVì vậy tôi luôn nhắc nhở các Thức Tỉnh Thể của chúng ta, cố gắng đừng chết một cách quá tùy tiện."
  },
  AvgDialog_23355_Content_28 = {
    Text = "Phu nhân Soreil với tư cách là Thức Tỉnh Thể, có kỹ năng đặc biệt gì không?\nMột người ở vị trí cao như bà ấy, chắc hẳn thực lực phi phàm nhỉ."
  },
  AvgDialog_23355_Content_29 = {
    Text = "Dorl lắc đầu."
  },
  AvgDialog_23355_Content_3 = {
    Text = "Tiếng bước chân vội vã vang lên ở cuối con hẻm chật hẹp. Cách xa đám đông hiếu kỳ, các thám tử của Londinium đang bận rộn làm việc."
  },
  AvgDialog_23355_Content_30 = {
    Text = "Hồ sơ tài liệu của bà ấy là thông tin tuyệt mật của Misage, ngay cả tôi cũng không có quyền xem.\nNhưng tôi nghe nói đó là một số…… ừm, kỹ năng khá hư phù."
  },
  AvgDialog_23355_Content_31 = {
    Text = "Điều này cũng giải thích vì sao bà ấy dù là Thể Thức Tỉnh, nhưng vẫn bị đâm chết trước mắt mọi người ngay tại nhà hát opera."
  },
  AvgDialog_23355_Content_32 = {
    Text = "Hư Phù? Chẳng lẽ là loại như mê hoặc người khác giới, giữ mãi tuổi xuân gì đó sao?"
  },
  AvgDialog_23355_Content_33 = {
    Text = "Có lẽ vậy, tôi không hứng thú với những phỏng đoán vô nghĩa này."
  },
  AvgDialog_23355_Content_34 = {
    Text = "Thông tin tuyệt mật… Tại sao?"
  },
  AvgDialog_23355_Content_35 = {
    Text = "Tất nhiên là vì bà ấy có địa vị đủ cao. Soreil có quan hệ mật thiết lâu dài với Misager cùng các quan chức cấp cao trong chính phủ, nhưng xuất thân và lai lịch của bà ấy luôn là một bí ẩn."
  },
  AvgDialog_23355_Content_36 = {
    Text = "Còn những nạn nhân khác thì sao? Quan hệ huyết thống, giao dịch tài chính, lập trường chính trị… Tôi cần biết mọi thông tin, ai là người hưởng lợi lớn nhất từ chuỗi vụ án này."
  },
  AvgDialog_23355_Content_37 = {
    Text = "Đang điều tra, nhưng tiến độ sẽ chậm hơn một chút. Mạng lưới quan hệ xã hội của mấy vị quý tộc này còn phức tạp hơn cả các nhánh của sông Isis."
  },
  AvgDialog_23355_Content_38 = {
    Text = "Những nhân vật nổi tiếng tham dự tang lễ đang lần lượt bị giết."
  },
  AvgDialog_23355_Content_39 = {
    Text = "Theo tình hình hiện tại, Dexter rất có thể sẽ trở thành mục tiêu tiếp theo…"
  },
  AvgDialog_23355_Content_4 = {
    Text = "Nạn nhân là Nam tước @1·Cavendish, 32 tuổi. Đêm qua rời buổi tiệc với bạn bè một mình, 4 giờ sáng bị phát hiện nằm gục tại đây."
  },
  AvgDialog_23355_Content_40 = {
    Text = "Đừng lo, đây chính là lý do tôi đưa các bạn đến đây."
  },
  AvgDialog_23355_Content_41 = {
    Text = "Trong lúc trò chuyện, các bạn đã đến nơi đích của chuyến đi. Doer dừng bước, chỉ về phía cánh cửa khóa chặt ở góc phòng tối."
  },
  AvgDialog_23355_Content_42 = {
    Text = "Bạn từng đi qua nó để vào Mật Cảnh nhân tạo của Ramona, đó là một ký ức khó quên."
  },
  AvgDialog_23355_Content_43 = {
    Text = "Đã vậy thì phương thức điều tra truyền thống gặp nhiều khó khăn, chi bằng hãy tận dụng <Yellow:Mật Cảnh nhân tạo> đi."
  },
  AvgDialog_23355_Content_44 = {
    Text = "Tôi hiểu rồi, có thể thông qua Mật Cảnh của phu nhân Soreil quay lại hiện trường vụ án, điều tra một lần cho thỏa!"
  },
  AvgDialog_23355_Content_45 = {
    Text = "Chỉ riêng Mật Cảnh của Soreil e rằng chưa đủ, chúng ta còn cần kết hợp Mật Cảnh của <Blue:thị nữ Garen>, thậm chí của nhiều người liên quan hơn nữa để thu thập manh mối."
  },
  AvgDialog_23355_Content_46 = {
    Text = "Thị nữ Garen?"
  },
  AvgDialog_23355_Content_47 = {
    Text = "Doer gật đầu."
  },
  AvgDialog_23355_Content_48 = {
    Text = "Cô ấy đau buồn tột độ vì cái chết của Soreil, thề sẽ toàn lực phối hợp với chúng tôi tiến hành điều tra, tìm ra hung thủ thực sự."
  },
  AvgDialog_23355_Content_49 = {
    Text = "Misager, lối vào Mật Cảnh nhân tạo\nTrước khi lên đường"
  },
  AvgDialog_23355_Content_5 = {
    Text = "Đã là quý tộc thứ 7 chết bất thường rồi. Tôi nhớ người đầu tiên chết là……"
  },
  AvgDialog_23355_Content_50 = {
    Text = "Sau khi mọi thứ đã chuẩn bị xong, Ramona quay người nhìn về phía Dexter."
  },
  AvgDialog_23355_Content_51 = {
    Text = "Đừng rời khỏi trường, ở trong trường cũng đừng đi lung tung. Đợi chúng tôi quay lại."
  },
  AvgDialog_23355_Content_52 = {
    Text = "Lại cái giọng dỗ trẻ con này nữa. Con còn nhớ ta là cha của con, người lớn tuổi hơn và đáng kính trọng chứ?"
  },
  AvgDialog_23355_Content_54 = {
    Text = "Được, được, ta chịu thua……\nTa sẽ ở đây mỗi ngày, không đi đâu cả, tuyệt đối không gây phiền phức cho mọi người."
  },
  AvgDialog_23355_Content_55 = {
    Text = "Dexter vẫn giữ vẻ mặt tươi cười như mọi khi. Ông đặt tay lên lưng cậu và Ramona, rồi nhẹ nhàng đẩy về phía trước——"
  },
  AvgDialog_23355_Content_56 = {
    Text = "Đi nhanh đi, các con. Mạng sống của ta trông cậy cả vào các con đấy."
  },
  AvgDialog_23355_Content_6 = {
    Text = "<Red:Công tước Harold>. Vụ án này tôi nhớ rất rõ, đó là xe Porsche đấy, cả vương quốc chẳng có mấy chiếc!"
  },
  AvgDialog_23355_Content_7 = {
    Text = "Tiếc là bị đâm nát thành sắt vụn……Lúc đó trên xe có Công tước Harold cùng quản gia và tài xế, cả ba người đều chết."
  },
  AvgDialog_23355_Content_8 = {
    Text = "Ngoài việc đều là người nổi tiếng, điểm chung duy nhất của các nạn nhân là đều đã tham dự tang lễ của phu nhân Soreil ba tuần trước."
  },
  AvgDialog_23355_Content_9 = {
    Text = "Chẳng lẽ đúng như báo lá cải nói, bị <Red:hồn ma của phu nhân Soreil> ám theo……"
  },
  AvgDialog_23356_Content_1 = {
    Text = "Đám tang Tường Vi"
  },
  AvgDialog_23356_Content_10 = {
    Text = "Hannah vẫn chưa dò hỏi được thêm tin tức từ sở cảnh sát……Nhưng không sao, phóng viên Hannah tuyệt không nản chí! Giờ tôi lại mang tin tức mới quay lại rồi!"
  },
  AvgDialog_23356_Content_11 = {
    Text = "Tin tức 1: Nghe nói hôm nay nghĩa trang được trang trí bằng hàng ngàn bông hồng dại \"Lễ Hội Đỏ\" vận chuyển từ Constance, tổng chi phí lên đến mười ngàn Leofang!"
  },
  AvgDialog_23356_Content_12 = {
    Text = "Tin tức 2: Đoán xem, vừa nãy tôi đã gặp những gương mặt quen thuộc nào ở bên ngoài?"
  },
  AvgDialog_23356_Content_13 = {
    Text = "Gia tộc Cavendish, vợ chồng Công tước Windsor, và điều mọi người quan tâm nhất……"
  },
  AvgDialog_23356_Content_14 = {
    Text = "<Big:Công tước Harold đức cao vọng trọng cùng con trai duy nhất của ông — Nicholas·Harold!>"
  },
  AvgDialog_23356_Content_15 = {
    Text = "Nhớ ngày trước, tin tức hai cha con hẹn nhau đấu tay đôi vì phu nhân Soleil đã gây chấn động cả thành phố……"
  },
  AvgDialog_23356_Content_16 = {
    Text = "Cùng lúc đó, bên trong nghĩa trang Woodlawn……"
  },
  AvgDialog_23356_Content_17 = {
    Text = "Hôm nay chúng ta tề tựu nơi đây để tưởng nhớ và hoài niệm cuộc đời của Soleil·@1."
  },
  AvgDialog_23356_Content_18 = {
    Text = "Bà là người con gái sùng đạo nhất của Đức Cha, một người phụ nữ phẩm hạnh cao quý, đáng ngưỡng mộ……"
  },
  AvgDialog_23356_Content_19 = {
    Text = "Hắt xì……<Big:Hắt xì!>"
  },
  AvgDialog_23356_Content_2 = {
    Text = "Bên ngoài nghĩa trang Woodlawn\nBa tuần trước"
  },
  AvgDialog_23356_Content_20 = {
    Text = "Công tước đại nhân bị cảm rồi sao? Ngài cứ hắt xì liên tục."
  },
  AvgDialog_23356_Content_21 = {
    Text = "Tôi bị mùi của đám hoa sặc sỡ tầm thường này xông cho không chịu nổi……Vận chuyển chúng đến đây ít nhất cũng phải tốn vài ngàn Leofang chứ nhỉ?"
  },
  AvgDialog_23356_Content_22 = {
    Text = "Soleil đến chết vẫn giữ nguyên tác phong trọc phú như mọi khi, quả thật đáng ngưỡng mộ……Hắt xì!"
  },
  AvgDialog_23356_Content_23 = {
    Text = "Quả thật đáng ngưỡng mộ."
  },
  AvgDialog_23356_Content_24 = {
    Text = "Cách hành xử như vậy có thể cung cấp không ít chuyện để bàn tán cho đám phóng viên săn tin và thị dân bên ngoài, chẳng trách bà ấy có thể trở thành thần tượng đại chúng của Londinium."
  },
  AvgDialog_23356_Content_25 = {
    Text = "Hừ. Trò vặt không đáng nhắc tới."
  },
  AvgDialog_23356_Content_26 = {
    Text = "Dexter nhún vai, chán nản đưa mắt nhìn quanh."
  },
  AvgDialog_23356_Content_27 = {
    Text = "Những nhân vật danh giá ăn mặc sang trọng tụ tập thành từng nhóm nhỏ trước mộ, tiếng bàn tán cố tình hạ thấp hòa lẫn với lời cầu nguyện của người chủ lễ thỉnh thoảng lọt vào tai."
  },
  AvgDialog_23356_Content_28 = {
    Text = "<Gray:Một con nhỏ nhà quê, lại giả vờ làm quý tộc nước ngoài…>"
  },
  AvgDialog_23356_Content_29 = {
    Text = "<Gray:Bộ đồ bà ta mặc khi hạ táng, được may bằng vải flannel phải không? Chất liệu thật đẹp…>"
  },
  AvgDialog_23356_Content_3 = {
    Text = "Xèo… xèo…"
  },
  AvgDialog_23356_Content_30 = {
    Text = "<Gray:…tình nhân của Quốc vương…và Hoàng tử…Nữ hoàng lại làm ngơ…>"
  },
  AvgDialog_23356_Content_32 = {
    Text = "Xem ra quan hệ xã giao của vị phu nhân này quả thật không tốt lắm nhỉ."
  },
  AvgDialog_23356_Content_33 = {
    Text = "Cát bụi trở về cát bụi, đất trở về đất.\nLinh hồn của quý bà Soreil đã bước vào miền cực lạc vĩnh hằng, trở về vòng tay của Đức Cha…"
  },
  AvgDialog_23356_Content_34 = {
    Text = "Huân tước Dexter, nhìn phản ứng của ngài, có vẻ ngài không đồng tình với nhận xét của chúng tôi về phu nhân Soreil?"
  },
  AvgDialog_23356_Content_35 = {
    Text = "Chẳng lẽ ngài cũng là kẻ say mê bà ta? Hay nói đúng hơn… từng là? Sắp là?"
