  AvgDialog_23356_Content_36 = {
    Text = "Đám đông bật ra tiếng cười khúc khích, Dexter cau mày."
  },
  AvgDialog_23356_Content_37 = {
    Text = "Tôi và phu nhân Soreil khi còn sống không có nhiều giao tình, cũng chẳng hứng thú biết về mâu thuẫn giữa bà ấy và các vị."
  },
  AvgDialog_23356_Content_38 = {
    Text = "Nhưng lẽ thường cho tôi biết, bàn tán về người đã khuất tại tang lễ không phải hành vi của một quý ông."
