  AvgDialog_23356_Content_40 = {
    Text = "…Nguyện Đức Cha phù hộ, hỡi con."
  },
  AvgDialog_23356_Content_41 = {
    Text = "Màn đêm buông xuống, một chiếc xe Ferdinand Porsche mới tinh chạy trên con đường đá gồ ghề."
  },
  AvgDialog_23356_Content_42 = {
    Text = "Thật quỷ tha ma bắt, đi đâu cũng gặp mấy tay phóng viên lá cải."
  },
  AvgDialog_23356_Content_43 = {
    Text = "Bên ngoài đồn đại rằng tôi và Nicholas đánh nhau vì tranh giành Soreil, thật là chuyện hoang đường!"
  },
  AvgDialog_23356_Content_44 = {
    Text = "Dân thường làm sao hiểu được suy nghĩ thực sự của đại nhân Công tước? Họ thà tin vào những câu chuyện tình yêu sáo rỗng hoang đường."
  },
  AvgDialog_23356_Content_45 = {
