  AvgDialog_23356_Content_53 = {
    Text = "Bóng đen đứng một mình dưới ánh trăng lạnh lẽo, khuôn mặt cười vẽ bằng máu trên chiếc mặt nạ kéo dài đến tận khóe mắt trống rỗng."
