  AvgDialog_23356_Content_7 = {
    Text = "Chào buổi sáng tất cả bạn bè ở Mithager! Đây là phóng viên báo trường Hannah mang đến cho các bạn bản tin độc·quyền!"
  },
  AvgDialog_23356_Content_8 = {
    Text = "Một thế hệ danh viện xã giao, được thị dân Londinium yêu mến — <Blue:tang lễ của phu nhân Soleil> đang được tổ chức tại nghĩa trang Woodlawn cách tôi không xa!"
