  AvgDialog_23356_Content_9 = {
    Text = "Thời gian thấm thoắt thoi đưa! Không ngờ cái chết ly kỳ của phu nhân Soleil tại nhà hát opera đã qua đúng một tuần rồi."
  },
  AvgDialog_23359_Content_10 = {
    Text = "Con là người thông minh, Soreil. Ngài Binder là gia đình tốt nhất mà chúng ta có thể kết giao, con hiểu chứ?"
  },
  AvgDialog_23359_Content_11 = {
    Text = "Không thích cũng không sao. Chỉ cần có được tài sản của ông ấy, con có thể làm bất cứ điều gì con muốn, hẹn hò với bất kỳ ai con thích."
  },
  AvgDialog_23359_Content_13 = {
    Text = "Con không thích kiểu này, cha ơi."
  },
  AvgDialog_23359_Content_14 = {
    Text = "Gia đình như nhà mình không có tư cách tùy ý muốn gì làm nấy.\nNhìn bệnh tình của mẹ con đi, con nỡ lòng nhìn bà ấy cứ chịu khổ mãi sao?"
  },
  AvgDialog_23359_Content_15 = {
    Text = "<Shake:Khụ khụ……Đừng lo cho mẹ, Soreil. Dù sao mẹ cũng chẳng sống được bao lâu nữa……>"
  },
  AvgDialog_23359_Content_16 = {Text = "Mẹ……"},
  AvgDialog_23359_Content_17 = {
    Text = "Soreil, cha và mẹ con đã già rồi. Con là hy vọng duy nhất của chúng ta."
  },
  AvgDialog_23359_Content_18 = {
    Text = "Chúng ta đổ bao nhiêu tiền vào con không phải làm từ thiện, mà là để một ngày nào đó thu về nhiều hơn, con hiểu chứ?"
  },
  AvgDialog_23359_Content_19 = {
    Text = "Đừng làm những chuyện khiến bản thân phải hối hận."
  },
  AvgDialog_23359_Content_2 = {
    Text = "Năm 245 trước Hồng Tích, phía nam Konstanz"
  },
  AvgDialog_23359_Content_20 = {
    Text = "Trong đêm tĩnh lặng, thiếu nữ ngồi bên giường, thẫn thờ ngắm ánh trăng sáng vằng vặc ngoài cửa sổ."
  },
  AvgDialog_23359_Content_21 = {
    Text = "Cô ôm chặt đầu gối, giống như trước đây, lặng lẽ tự động viên bản thân trong lòng."
  },
  AvgDialog_23359_Content_22 = {
    Text = "Đừng sợ, Soleil. Con sẽ nghĩ ra cách thôi."
  },
  AvgDialog_23359_Content_23 = {
    Text = "<Red:Thật đáng tiếc… Đây chính là cái giá phải trả cho vẻ đẹp sao.>"
  },
  AvgDialog_23359_Content_24 = {
    Text = "<Red:Dù là vầng trăng trong trẻo nhất, khi rơi xuống trần gian cũng bị bụi trần vấy bẩn.>"
  },
  AvgDialog_23359_Content_25 = {
    Text = "Làn sương mù ở góc phòng xào xạc rung động, bất ngờ ngưng tụ thành một bóng người hỗn độn."
  },
  AvgDialog_23359_Content_26 = {Text = "?！"},
  AvgDialog_23359_Content_27 = {
    Text = "Ngươi là ai? Ta sẽ gọi người đấy——"
  },
  AvgDialog_23359_Content_28 = {
    Text = "Suỵt… Ta chỉ là một hồn ma lang thang nơi thế gian mà thôi, thân phận đều là hư cấu, bề ngoài cũng chỉ là ngụy trang."
  },
  AvgDialog_23359_Content_29 = {
    Text = "Lần đầu gặp mặt, ngươi có thể gọi ta là <Red:「N」>."
  },
  AvgDialog_23359_Content_3 = {
    Text = "Soreil, Soreil xinh đẹp của ta. Đây là chiếc váy mới mua cho con, màu trắng mà con yêu thích nhất."
  },
  AvgDialog_23359_Content_30 = {
    Text = "Vì một thú vui khó nói thành lời, ta sưu tầm câu chuyện, cũng viết lại câu chuyện.\nGặp được con người thú vị, ta cũng không ngại giúp họ một tay —— trong phạm vi hợp lý."
  },
  AvgDialog_23359_Content_31 = {
    Text = "Vậy nên cứ nói cho ta nghe nỗi khổ tâm của ngươi đi."
  },
  AvgDialog_23359_Content_32 = {
    Text = "Giọng nói của làn sương đen trầm ấm dễ nghe, mang một sức mê hoặc lòng người khó hiểu.\nThiếu nữ dần dần bình tĩnh lại."
  },
  AvgDialog_23359_Content_33 = {
    Text = "Cha tôi không đủ thông minh, ngài Binder cũng tuyệt nhiên không phải người xứng đôi. Ông ta tham lam ham cờ bạc, không quá ba năm là có thể phá sạch gia sản."
  },
  AvgDialog_23359_Content_34 = {
    Text = "Nhưng tôi quá yếu đuối, không có cách nào chống lại họ."
  },
  AvgDialog_23359_Content_35 = {
    Text = "Còn mẹ tôi… bà ấy lúc nào cũng khóc. Bà ấy không giúp được tôi đâu."
  },
  AvgDialog_23359_Content_36 = {
    Text = "Thiếu nữ cúi đầu, vẻ mặt u buồn."
  },
  AvgDialog_23359_Content_37 = {
    Text = "Tôi đã chán lắm rồi. Chán phải lo sợ vì tiền bạc mọi lúc, chán cái cảm giác số phận bị nắm trong tay người khác."
  },
  AvgDialog_23359_Content_38 = {
    Text = "Ngươi nói ngươi có thể giúp tôi, vậy ngươi có thể cho tôi thật nhiều tiền không?"
  },
  AvgDialog_23359_Content_39 = {
    Text = "E là không được, hỡi đứa trẻ của ta."
  },
  AvgDialog_23359_Content_4 = {
    Text = "Đẹp quá, cảm ơn cha. Nhưng trông nó quá đắt tiền……"
  },
  AvgDialog_23359_Content_40 = {
    Text = "Vậy giết người thay tôi thì sao?"
  },
  AvgDialog_23359_Content_41 = {
    Text = "Ha ha ha… Đây không phải là lời mà một tiểu thư 13 tuổi nên nói, nhưng đây cũng chính là lý do ta chọn ngươi."
  },
  AvgDialog_23359_Content_42 = {
    Text = "Rất tiếc, ta không thể thay ngươi giết người.\nNhưng ta đảm bảo với ngươi, nếu chúng ta ký kết khế ước, ngươi sẽ nhận được một số \"hỗ trợ cần thiết\"."
  },
  AvgDialog_23359_Content_43 = {
    Text = "Những thủ đoạn này không trực tiếp, nhưng đủ để chí mạng."
  },
  AvgDialog_23359_Content_44 = {
    Text = "Chúng sẽ giúp ngươi leo lên những đỉnh cao chưa từng chạm tới, đưa ngươi chiêm ngưỡng những phong cảnh chưa từng thấy, ngươi sẽ không bao giờ phải gả cho một tay cờ bạc vừa già vừa hói nữa."
  },
  AvgDialog_23359_Content_45 = {
    Text = "Thiếu nữ lặng lẽ lắng nghe, trên gương mặt lạnh lùng dần nở một nụ cười."
  },
  AvgDialog_23359_Content_46 = {
    Text = "Từ nhỏ tôi đã là một đứa trẻ xinh đẹp, được yêu thích. Rất nhiều người tiếp cận tôi, muốn kết bạn với tôi."
  },
  AvgDialog_23359_Content_47 = {
    Text = "Họ như lũ sói rình rập tôi, mỗi người đều khao khát có thể đòi lại từ tôi cả vốn lẫn lời — đúng như cha tôi thường nói."
  },
  AvgDialog_23359_Content_48 = {
    Text = "Vì vậy tôi đã sớm hiểu ra, phép màu sẽ không bao giờ giáng xuống đầu tôi."
  },
  AvgDialog_23359_Content_49 = {
    Text = "Tôi không ngốc đâu, ngài N. Ngài đã đưa ra nhiều điều khoản hấp dẫn đến vậy, vậy thì…"
  },
  AvgDialog_23359_Content_5 = {
    Text = "Đúng vậy, rất đắt. Tốn của cha tận 200 Sterling."
  },
  AvgDialog_23359_Content_50 = {
    Text = "Cái giá phải trả là gì?"
  },
  AvgDialog_23359_Content_51 = {
    Text = "Ngoại ô Londinium\nDinh thự của Langbell"
  },
  AvgDialog_23359_Content_52 = {
    Text = "Ngài Langbell, ngài bị cáo buộc liên quan đến vụ sát hại phu nhân Saurel, phiền ngài đi cùng chúng tôi một chuyến."
  },
  AvgDialog_23359_Content_53 = {
    Text = "Thời gian dường như đã ngưng đọng từ lâu. Ánh sáng nhợt nhạt tuôn xuống, phủ lên đại sảnh trống vắng một lớp màn trắng."
  },
  AvgDialog_23359_Content_54 = {
    Text = "Gió lạnh không ngừng tràn vào qua khe cửa sổ vỡ, thổi cho hoa tường vi và lá khô trên mặt đất xào xạc."
  },
  AvgDialog_23359_Content_55 = {
    Text = "Khục khục, cuối cùng cũng đến rồi… Ta đã đợi các người rất lâu rồi…"
  },
  AvgDialog_23359_Content_56 = {
    Text = "Lão già sắp mục rữa ngồi sâu trong chiếc ghế nhung mềm mại, tay cầm ly rượu vang đỏ nhẹ nhàng lắc lư."
  },
  AvgDialog_23359_Content_57 = {
    Text = "Nếu ta nói người giết bà ấy không phải ta, các người có tin không?"
  },
  AvgDialog_23359_Content_58 = {
    Text = "Với tư cách là người thụ hưởng duy nhất trong di chúc của phu nhân Saurel, gần đây lại nợ nần chồng chất vì cờ bạc, ngài có động cơ phạm tội hoàn hảo."
  },
  AvgDialog_23359_Content_59 = {
    Text = "Ngoài ra…"
  },
  AvgDialog_23359_Content_6 = {
    Text = "200 Sterling?! Thu nhập cả năm của cha mới chỉ……Không được, chúng ta phải mau trả lại."
  },
  AvgDialog_23359_Content_60 = {
    Text = "Ramona rút ra con dao găm tinh xảo đó."
  },
  AvgDialog_23359_Content_61 = {
    Text = "Đây là thứ chúng tôi tìm thấy tại hiện trường vụ án, một món đồ quý hiếm nhập khẩu từ Viễn Đông."
  },
  AvgDialog_23359_Content_62 = {
    Text = "Chúng tôi đã tìm được người bán nó, vị thương nhân đồ cổ thừa nhận rằng ngài Lambert đã mua nó cách đây hai tháng."
  },
  AvgDialog_23359_Content_63 = {
    Text = "Có lẽ ngài có thể giải thích lý do mang nó đến nhà hát opera vào ngày hôm đó?"
  },
  AvgDialog_23359_Content_64 = {
    Text = "Lý do ư? Heh heh heh…"
  },
  AvgDialog_23359_Content_65 = {
    Text = "Bên tai vang lên tiếng ghế kẽo kẹt."
  },
  AvgDialog_23359_Content_66 = {
    Text = "Lambert chật vật đứng dậy, khó nhọc lê bước tiến về phía Ramona."
  },
  AvgDialog_23359_Content_67 = {
    Text = "Bởi vì cô ta đáng chết.\nChính ta là người đưa cô ta lên đỉnh cao, tài sản, địa vị, danh vọng… tất cả đều do ta một tay sắp đặt phía sau."
  },
  AvgDialog_23359_Content_68 = {
    Text = "Còn cô ta thì sao? Sau khi thành đạt, không những không báo đáp ta, còn muốn tránh xa ta hết mức có thể."
  },
  AvgDialog_23359_Content_69 = {
    Text = "Hãy nhìn ngôi nhà này đi… Ta đã cầm cố tất cả những gì có thể cầm cố, chỉ còn lại căn phòng đầy hoa tường vi này."
  },
  AvgDialog_23359_Content_7 = {
    Text = "Con xứng đáng với những thứ tốt nhất, Soreil."
  },
  AvgDialog_23359_Content_70 = {
    Text = "Đây là loài hoa mà vợ ta yêu thích nhất khi còn sống.\nSau khi vợ ta qua đời, sợi dây ràng buộc duy nhất giữa ta và Sorel cũng không còn nữa."
  },
  AvgDialog_23359_Content_71 = {
    Text = "Vì vậy ta quyết định giết cô ta…"
  },
  AvgDialog_23359_Content_72 = {
    Text = "Những cánh hoa tơi tả rơi rụng từ trên không."
  },
  AvgDialog_23359_Content_73 = {
    Text = "Lão nhân ngẩng đầu lên, khuôn mặt đã bị Dung Thực Tương xâm thực gần hết, chất dịch đen kịt như nước mắt chảy dài từ khóe mắt ông ta."
  },
  AvgDialog_23359_Content_74 = {
    Text = "…Giống như ta quyết tâm giết các ngươi vậy."
  },
  AvgDialog_23359_Content_8 = {
    Text = "Ba ngày sau, ông Binder sẽ đến Nhà chơi. Lúc đó bạn hãy mặc chiếc váy này và cư xử tốt với ông ấy."
  },
  AvgDialog_23359_Content_9 = {
    Text = "……Ông già kiêu ngạo tự đại đó sao? Con không thích ông ta."
  },
  AvgDialog_23360_Content_1 = {
    Text = "Tù nhân của số mệnh"
  },
  AvgDialog_23360_Content_10 = {
    Text = "<Red:Hi hi.>"
  },
  AvgDialog_23360_Content_11 = {
    Text = "<Red:Tôi thích {Male=anh ấy,Female=cô ấy}.>"
  },
  AvgDialog_23360_Content_12 = {
    Text = "Cô ấy dường như đang sợ hãi điều gì đó."
  },
  AvgDialog_23360_Content_13 = {
    Text = "……Cô thực sự rất muốn tôi chơi trò chơi này với cô sao?"
  },
  AvgDialog_23360_Content_14 = {
    Text = "Phu nhân Soleil sững lại một khoảnh khắc, rồi khẽ gật đầu."
  },
  AvgDialog_23360_Content_15 = {
    Text = "<Gray:Uống hai ly champagne chắc không sao đâu nhỉ……>"
  },
  AvgDialog_23360_Content_16 = {
    Text = "Tôi chấp nhận đề nghị của cô, chúng ta nhanh chóng giải quyết thôi.\nCâu hỏi đầu tiên là gì?"
  },
  AvgDialog_23360_Content_17 = {Text = "Ugh…"},
  AvgDialog_23360_Content_18 = {
    Text = "Soleil một tay chống cằm, những ngón tay thon dài gõ nhẹ trên má."
  },
  AvgDialog_23360_Content_19 = {
    Text = "Câu hỏi đầu tiên, làm sao Misage biết tối nay sẽ có người đến giết tôi?"
  },
  AvgDialog_23360_Content_2 = {
    Text = "U, uống rượu?!"
  },
  AvgDialog_23360_Content_20 = {
    Text = "Nếu cậu không thể trả lời, liệu tôi có thể hợp lý nghi ngờ rằng, các người cũng ở mức độ khác nhau đã tham gia vào đó không?"
  },
  AvgDialog_23360_Content_21 = {
    Text = "Đây không phải là câu hỏi có thể trả lời bừa được……"
  },
  AvgDialog_23360_Content_22 = {
    Text = "Bạn nâng ly champagne trên bàn lên và uống một hơi."
  },
  AvgDialog_23360_Content_23 = {
    Text = "Ngoài dự kiến, thứ rượu màu vàng nhạt lại có hương vị thanh nhẹ tinh tế, bạn còn ngửi thấy một chút hương cam quýt thoang thoảng."
  },
  AvgDialog_23360_Content_24 = {
    Text = "<Gray:Ừm……ngon phết đấy.>"
  },
  AvgDialog_23360_Content_25 = {
    Text = "Uống từ từ thôi, Người Giữ Bí Mật. Chai rượu này đủ để mua một căn nhà ở khu trung tâm Londinium đấy."
  },
  AvgDialog_23360_Content_26 = {
    Text = "Khụ khụ……<Big:Cái gì?!>"
  },
  AvgDialog_23360_Content_27 = {
    Text = "Tiếp theo là câu hỏi thứ hai. Câu này thay mặt các quý cô và phu nhân ở Londinium hỏi……"
  },
  AvgDialog_23360_Content_28 = {
    Text = "Soreil mỉm cười với bạn. Không hiểu sao, bạn có một linh cảm chẳng lành."
  },
  AvgDialog_23360_Content_29 = {
    Text = "Mẹ ruột của con gái Huân tước Dexter rốt cuộc là ai?"
  },
  AvgDialog_23360_Content_3 = {
    Text = "<Gray:Tiểu thư Doer nói tôi chưa đến tuổi được uống rượu, trong thời gian điều tra cũng không được uống rượu……>"
  },
  AvgDialog_23360_Content_30 = {
    Text = "Phụt——!!"
  },
  AvgDialog_23360_Content_31 = {
    Text = "Rượu chưa kịp nuốt đã bị bạn phun hết ra ngoài. Soreil nhướn mày, Galen lập tức tiến lên lau sạch rượu trên bàn."
  },
  AvgDialog_23360_Content_32 = {
    Text = "<SmallShake:Tsk tsk, chỉ một ngụm nhỏ cũng là tiền đấy! Đủ để tôi ra Harrods mua một sợi dây chuyền mới rồi……>"
  },
  AvgDialog_23360_Content_33 = {
    Text = "Không ngờ phu nhân Soreil cũng quan tâm đến những tin đồn nhảm nhí thế này, thật bất ngờ……Ha, haha."
  },
  AvgDialog_23360_Content_34 = {
    Text = "Để tôi nói cho bạn một bí mật nhé: Những \"danh viện\" như chúng tôi, ít nhất một nửa thời gian trong ngày đều sống trong tin đồn."
  },
  AvgDialog_23360_Content_35 = {
    Text = "Không thì bạn nghĩ <Blue:Salon của phu nhân Soreil> dựa vào cái gì để vận hành chứ?"
  },
  AvgDialog_23360_Content_36 = {
    Text = "……Có thể tưởng tượng được."
  },
  AvgDialog_23360_Content_37 = {
    Text = "Mọi người không tin chuyện cha nuôi con nuôi đâu. Theo tin đồn trong giới, mẹ ruột của đứa trẻ đó hẳn là tình nhân của một vị đại nhân nào đó……"
  },
  AvgDialog_23360_Content_38 = {
    Text = "Đừng,đừng nói bậy.\nHuân tước Dexter là người chính trực, tự trọng, tuyệt đối không phải như mọi người nghĩ..."
  },
  AvgDialog_23360_Content_39 = {
    Text = "%player%, thiết bị liên lạc vẫn luôn trong trạng thái bật, tôi nghe hết rồi đấy."
  },
  AvgDialog_23360_Content_4 = {
    Text = "Xin lỗi, phu nhân Soleil."
  },
  AvgDialog_23360_Content_40 = {
    Text = "Khuyên các người đừng làm chuyện vô ích, ngay cả tôi còn không biết mẹ ruột mình là ai."
  },
  AvgDialog_23360_Content_42 = {
    Text = "Không biết có phải do rượu hay không, bạn bỗng cảm thấy hơi chóng mặt."
  },
  AvgDialog_23360_Content_43 = {
    Text = "Tuyệt đối không phải như mọi người nghĩ? Vậy thì là như thế nào?"
  },
  AvgDialog_23360_Content_44 = {
    Text = "Bạn lắc đầu, nâng ly rượu trên bàn lên."
  },
  AvgDialog_23360_Content_45 = {
    Text = "Câu hỏi này quan trọng với cô lắm sao?"
  },
  AvgDialog_23360_Content_46 = {
    Text = "Không quan trọng, chỉ là để cho đủ ba câu hỏi thôi."
  },
  AvgDialog_23360_Content_47 = {
    Text = "<Red:Rất tốt, Soleil. Tiếp theo……>"
  },
  AvgDialog_23360_Content_48 = {
    Text = "Soleil nhẹ nhàng đặt tay lên ly rượu trước mặt bạn. Không hiểu sao, bạn cảm thấy cơ mặt cô ấy dường như co giật trong một khoảnh khắc."
  },
  AvgDialog_23360_Content_49 = {
    Text = "Trẻ con không được uống rượu bừa bãi nhé, ly này coi như cậu nợ tôi đi. Câu hỏi tôi thực sự muốn hỏi là……"
  },
  AvgDialog_23360_Content_5 = {
    Text = "Nếu tôi nói với cậu rằng, tôi luôn biết người muốn giết mình là ai thì sao?"
  },
  AvgDialog_23360_Content_50 = {
    Text = "Lời vừa dứt, khuôn mặt phu nhân Soleil bỗng nhiên bắt đầu méo mó, nhòe đi……"
  },
  AvgDialog_23360_Content_51 = {
    Text = "Rồi hoàn toàn biến thành một diện mạo khác."
  },
  AvgDialog_23360_Content_52 = {
    Text = "Chào buổi tối, {Male=ngài,Female=cô}. Xin hãy cho phép tôi mượn miệng người khác để gửi lời chào đến cậu."
  },
  AvgDialog_23360_Content_53 = {
    Text = "Mười phút nữa, cậu sẽ hoàn toàn quên hết toàn bộ nội dung cuộc trò chuyện này, vì vậy đừng sợ khi trả lời bất kỳ câu hỏi nào của tôi."
  },
  AvgDialog_23360_Content_54 = {
    Text = "Câu hỏi của tôi cũng rất đơn giản……"
  },
  AvgDialog_23360_Content_55 = {
    Text = "Khuôn mặt hắn bị bao phủ trong làn sương mù đen mịt mùng. Bạn không thể nhìn rõ dung mạo hắn, nhưng lại cảm thấy một sự quen thuộc khó tả."
  },
  AvgDialog_23360_Content_56 = {
    Text = "Dường như từ rất lâu rất lâu trước đây, các bạn đã từng lướt qua nhau ở một nơi nào đó, hoặc có lẽ, hắn đã từng đứng ở nơi xa xăm nhìn bạn, đứng lặng hồi lâu."
  },
  AvgDialog_23360_Content_57 = {
    Text = "Tên trước đây của cậu, có phải là @2 không?"
