  AvgDialog_23360_Content_59 = {
    Text = "Thế giới dường như trong khoảnh khắc rút đi như thủy triều."
  },
  AvgDialog_23360_Content_6 = {Text = "?！"},
  AvgDialog_23360_Content_60 = {
    Text = "Tất cả âm thanh đều biến mất, tất cả hình ảnh cũng biến mất."
  },
  AvgDialog_23360_Content_61 = {
    Text = "Đôi môi mấp máy, thốt ra những lời vô thanh. Nhưng bạn biết, hắn đã nói chính xác không sai <Yellow:cái tên vốn có> của bạn."
