  AvgDialog_23360_Content_63 = {
    Text = "Bạn mở đôi môi khô khốc, nhưng không thể phát ra bất kỳ âm thanh nào nữa."
  },
  AvgDialog_23360_Content_64 = {
    Text = "Tiếng ù ù dày đặc không ngừng quấn quýt gào thét trong sâu thẳm ý thức, điên cuồng xé nát dây thần kinh của bạn."
  },
  AvgDialog_23360_Content_65 = {
    Text = "<Change>Tôi không biết……"
  },
  AvgDialog_23360_Content_66 = {Text = "……?"},
  AvgDialog_23360_Content_67 = {
    Text = "Đứng yên ở đó, %player%. Tôi lên ngay đây——"
  },
  AvgDialog_23360_Content_68 = {Text = "Bùm!"},
  AvgDialog_23360_Content_69 = {
    Text = "Đèn trong nhà hát đột ngột tắt ngấm."
  },
  AvgDialog_23360_Content_7 = {
    Text = "Chơi xong trò chơi này với tôi, tôi sẽ cho cậu biết đáp án."
  },
  AvgDialog_23360_Content_70 = {
    Text = "Ngay tại nguồn sáng duy nhất trước sân khấu, bóng đen vừa quen vừa lạ ấy lại xuất hiện lần nữa."
  },
  AvgDialog_23360_Content_71 = {
    Text = "Hắn tay cầm hoa tường vi, từng đợt ngâm vịnh quái dị chói tai tuôn ra từ làn sương đen không ngừng bò trườn trên khuôn mặt."
  },
  AvgDialog_23360_Content_72 = {
    Text = "<RedItalic:Hỡi kẻ tù nhân của số mệnh.>"
  },
  AvgDialog_23360_Content_73 = {
    Text = "<RedItalic:Ngươi giả dạng sứ giả của ánh sáng để ngu muội chúng sinh, ngươi tự ý xâm nhập cấm địa chưa biết để cầu xin chân tướng.>"
  },
  AvgDialog_23360_Content_74 = {
    Text = "<RedItalic:Ký ức ngươi đánh rơi mọc lên từ đôi mắt trống rỗng, tuôn trào, tương lai đáng thương của ngươi chết đi trong tiếng sáo.>"
  },
  AvgDialog_23360_Content_75 = {
    Text = "<RedItalic:Giờ ta ra lệnh cho ngươi——>"
  },
  AvgDialog_23360_Content_76 = {
    Text = "<Red:Mở mắt ra.>"
  },
  AvgDialog_23360_Content_8 = {
    Text = "Đe dọa sao?\nBạn nhíu mày, đang định từ chối cô ấy, nhưng lại chú ý đến một chi tiết khác."
  },
  AvgDialog_23360_Content_9 = {
    Text = "Ẩn giấu dưới vẻ đùa cợt khinh bạc, là đồng tử liên tục co lại, cùng với những đốt ngón tay hơi trắng bệch."
  },
  AvgDialog_23361_Content_1 = {
    Text = "Bài Ca Rượu"
  },
  AvgDialog_23361_Content_10 = {
    Text = "A a! Ngươi, ngươi là ai? Đây là phòng riêng của phu nhân Soreil!"
  },
  AvgDialog_23361_Content_11 = {
    Text = "Garen ra lệnh cho ngươi lập tức rời khỏi đây, không được phá hỏng hứng thú của phu nhân……<Big:Ái chà!>"
  },
  AvgDialog_23361_Content_12 = {
    Text = "Bạn đẩy cô hầu gái lắm lời sang một bên, bước đến trước mặt một người phụ nữ ăn mặc lộng lẫy."
  },
  AvgDialog_23361_Content_13 = {
    Text = "Nàng được bao quanh bởi lụa là tinh xảo và châu báu, tựa như một đóa tường vi nở rộ, tỏa ánh hào quang mê hoặc dưới ánh đèn."
  },
  AvgDialog_23361_Content_14 = {
    Text = "Hào quang mong manh, khiến người ta không nhịn được muốn tự tay nghiền nát."
  },
  AvgDialog_23361_Content_16 = {
    Text = "Bây giờ không phải lúc ngắm mỹ nhân, chúng ta chỉ còn chưa đến nửa giờ, %player%."
  },
  AvgDialog_23361_Content_17 = {
    Text = "Hả? Hả……!"
  },
  AvgDialog_23361_Content_18 = {
    Text = "Chào buổi tối, phu nhân Soreil. Sở Cảnh sát Londinium, Bộ phận Điều tra @2, %player%."
  },
  AvgDialog_23361_Content_19 = {
    Text = "Bộ phận Điều tra @2……?"
  },
  AvgDialog_23361_Content_2 = {
    Text = "Thưa quý bà, quý ông, chào buổi tối."
  },
  AvgDialog_23361_Content_20 = {
    Text = "Đừng lấy cái trò đó mà lừa ta. Người trong giới đều biết, Bộ phận Điều tra @2 chẳng qua chỉ là bình phong mà Misage treo danh ở sở cảnh sát."
  },
  AvgDialog_23361_Content_21 = {
    Text = "Nhưng trông ngươi khá lạ mặt…… Nhóc mới mà Misage thu nhận à?"
  },
  AvgDialog_23361_Content_22 = {
    Text = "Lại là Misage, mỗi lần các người tìm đến phu nhân nhà tôi chẳng bao giờ có chuyện tốt! Không chết người thì thiên tai, không thì là mượn tiền……"
  },
  AvgDialog_23361_Content_23 = {
    Text = "Soreil khẽ nhướn mi, vẻ thờ ơ liếc nhìn Garen."
  },
  AvgDialog_23361_Content_24 = {
    Text = "Garen, đây không phải nơi mà ai cũng có thể vào được. {Male=anh ấy,Female=cô ấy} vào đây bằng cách nào, có liên quan đến ngươi không?"
  },
  AvgDialog_23361_Content_25 = {
    Text = "A, a? Phu nhân nói gì vậy ạ! Lòng trung thành của Garen thuần khiết như viên hồng ngọc <Blue:Cameo> trên vương miện của Người vậy!"
  },
  AvgDialog_23361_Content_26 = {
    Text = "<SmallShake:Tất nhiên, xin đừng hiểu lầm, câu này tuyệt đối không có ý thèm muốn nó……>"
  },
  AvgDialog_23361_Content_27 = {
    Text = "Tóm lại thưa phu nhân, Jiālún xin mổ tim ra ngay cho người xem — một trái tim trung thành!"
  },
  AvgDialog_23361_Content_28 = {
    Text = "Suỵt…… Jiālún. Nói thêm một câu nữa, ta sẽ phạt ngươi một đồng Léi'ōu."
  },
  AvgDialog_23361_Content_29 = {
    Text = "Nàng dùng giọng nói dịu dàng ban ra mệnh lệnh không thể phản bác cho thị nữ."
  },
  AvgDialog_23361_Content_3 = {
    Text = "Câu chuyện tôi muốn kể đêm nay xảy ra ngay tại Londinium, nơi nổi tiếng với màn sương mù."
  },
  AvgDialog_23361_Content_30 = {
    Text = "Cái gì?! Một……<Small:Oa ú!>"
  },
  AvgDialog_23361_Content_31 = {
    Text = "Jiālún chậm rãi mới nhận ra, vội bịt miệng lại, không dám nói thêm một chữ nào nữa."
  },
  AvgDialog_23361_Content_32 = {
    Text = "Soléir nhấp một ngụm rượu champagne, đôi mắt hồng nhạt thận trọng nhìn bạn."
  },
  AvgDialog_23361_Content_33 = {
    Text = "Sắp đến bản nhạc ta yêu thích nhất rồi, ta không muốn bỏ lỡ nó. Vì vậy……"
  },
  AvgDialog_23361_Content_34 = {
    Text = "Cho ngươi một phút. Nói đi, muốn gì?"
