  AvgDialog_23362_Content_103 = {
    Text = "Hehe…… suy luận của cậu thật đáng yêu. Vậy bóng đen kia cậu giải thích thế nào?"
  },
  AvgDialog_23362_Content_104 = {
    Text = "Nó giết người trước mặt bao nhiêu người, cậu làm sao chứng minh mối quan hệ giữa tôi và nó?"
