  AvgDialog_23362_Content_105 = {
    Text = "Mùi hương."
  },
  AvgDialog_23362_Content_106 = {
    Text = "Lần trước khi bà lao vào người tôi, tôi đã ngửi thấy. Trên người hai người có cùng một mùi……\n<Red:Mùi hoa tường vi thối rữa>."
  },
  AvgDialog_23362_Content_107 = {
    Text = "Thực ra nó là phân thân hay thứ gì đó tương tự của bà phải không?"
  },
  AvgDialog_23362_Content_109 = {
    Text = "Không hổ là Người Giữ Bí Mật, khứu giác của cậu rất nhạy bén."
  },
  AvgDialog_23362_Content_11 = {
    Text = "Đám người phía trên?"
  },
  AvgDialog_23362_Content_110 = {
    Text = "Soleil tháo chiếc găng tay đỏ ở tay phải, một mùi hôi thối nồng nặc lập tức lan tỏa."
  },
  AvgDialog_23362_Content_111 = {
    Text = "Dưới những vết xước và sẹo chằng chịt dữ tợn, những chữ cái đỏ sẫm lờ mờ hiện ra."
  },
  AvgDialog_23362_Content_113 = {
    Text = "Soleil thong thả đưa bàn tay lên dưới mũi, nhẹ nhàng hít ngửi."
  },
  AvgDialog_23362_Content_114 = {
    Text = "Cậu thấy chưa? Vết sẹo trên mu bàn tay này. Chừng nào nó còn tồn tại, khế ước giữa tôi và <Yellow:Ngài> sẽ vẫn còn hiệu lực."
  },
  AvgDialog_23362_Content_115 = {
    Text = "Tôi vẫn phải theo yêu cầu của Ngài mà không ngừng gây ra xung đột, tạo nên hỗn loạn… Những quý tộc đã chết chính là tế phẩm tôi dâng lên cho Ngài."
  },
  AvgDialog_23362_Content_116 = {
    Text = "Nhưng tôi đã chán ngấy từ lâu rồi. Con người và phần lớn Thể Thức Tỉnh vốn khao khát trật tự, chỉ có kẻ điên mới tìm thấy niềm vui trong sự hỗn loạn bất tận."
  },
  AvgDialog_23362_Content_117 = {
    Text = "Cái giá để giải trừ khế ước này cũng rất đơn giản: <Red:Cái chết>."
  },
  AvgDialog_23362_Content_118 = {
    Text = "……Hóa ra đây mới là mục đích cuối cùng của bà."
  },
  AvgDialog_23362_Content_119 = {
    Text = "Đúng vậy. Cái gọi là quý tộc, bao gồm cả cha tôi, chỉ là món tráng miệng kèm theo mà thôi.\nGiải quyết bọn họ không cần phải trả giá bằng mạng sống."
  },
  AvgDialog_23362_Content_120 = {
    Text = "Ngài không bao giờ chủ động hiện thân. Thực tế, Ngài cũng đã rất lâu không đáp lại tôi rồi."
  },
  AvgDialog_23362_Content_121 = {
    Text = "Đã có vô số đêm, tôi quỳ rạp xuống đất, vừa khóc vừa cầu xin Ngài giải trừ khế ước."
  },
  AvgDialog_23362_Content_122 = {
    Text = "Thế nhưng tôi chẳng nghe thấy gì, chẳng nhìn thấy gì. Đáp lại tôi chỉ có sự tĩnh lặng chết chóc."
  },
  AvgDialog_23362_Content_123 = {
    Text = "Vì vậy tôi không muốn chờ nữa. Lần này, tôi sẽ tự tay chém đứt khế ước này."
  },
  AvgDialog_23362_Content_124 = {
    Text = "……Dù phải trả giá bằng cái chết."
  },
  AvgDialog_23362_Content_13 = {
    Text = "Xin lỗi, đây không phải thứ mà cậu hiện tại có thể biết được."
  },
  AvgDialog_23362_Content_14 = {
    Text = "Không sao đâu, cô Dorr."
  },
  AvgDialog_23362_Content_15 = {
    Text = "Hiện tại tôi vẫn còn một số nghi ngờ và phỏng đoán, nếu có thể vào Mật Cảnh xác minh thì tốt quá rồi."
  },
  AvgDialog_23362_Content_16 = {
    Text = "Doer gật đầu."
  },
  AvgDialog_23362_Content_17 = {
    Text = "Tay buôn tin mà các cậu gặp trong Mật Cảnh, còn nhớ không? Chúng tôi đã cử người đi điều tra nguồn cung phía trên của cô ta, không ngờ lại thu được một bất ngờ lớn."
  },
  AvgDialog_23362_Content_18 = {
    Text = "Còn có tư liệu danh tính, mạng lưới quan hệ của những quý tộc đã chết…"
  },
  AvgDialog_23362_Content_19 = {
    Text = "Đây là báo cáo điều tra vừa được sở cảnh sát gửi về, mở ra xem đi."
  },
  AvgDialog_23362_Content_2 = {
    Text = "Phòng y tế Misage"
