  AvgDialog_23362_Content_25 = {
    Text = "<Yellow:Rất đơn giản, một cuộc đàm phán.>"
  },
  AvgDialog_23362_Content_26 = {
    Text = "Mật Cảnh nhân tạo lần thứ ba: Nhà hát Covent\nNgày diễn vở\"Tên của Tường Vi\""
  },
  AvgDialog_23362_Content_27 = {
    Text = "Giọng hát tuyệt vời như dòng suối chảy dài bất tận, lặng lẽ lan tỏa khắp nhà hát."
  },
  AvgDialog_23362_Content_28 = {
    Text = "Khán giả bên dưới sân khấu lộ vẻ kinh ngạc, nhẹ nhàng lắc lư theo giai điệu của âm nhạc, đã sớm chìm đắm trong giấc mộng được dệt nên từ những nốt nhạc."
  },
  AvgDialog_23362_Content_29 = {
    Text = "Nói đến đây, vở kịch này từng có một cái tên khác — \"Cái Chết Của Tường Vi\"."
  },
  AvgDialog_23362_Content_3 = {
    Text = "Nghe nói bên Ramona tiến triển rất thuận lợi. Còn cậu thì sao, bây giờ cảm thấy thế nào?"
  },
  AvgDialog_23362_Content_30 = {
    Text = "Nhân vật chính là một cô gái nhà quê một mình bươn chải ở Cité. Ngoài gương mặt trẻ trung xinh đẹp, cô chẳng có gì cả."
  },
  AvgDialog_23362_Content_31 = {
    Text = "Giống hệt tôi ngày xưa."
  },
  AvgDialog_23362_Content_32 = {
    Text = "Phu nhân là công chúa lưu vong nơi đất khách, cô gái nhà quê sao có thể sánh với ngài được!"
  },
  AvgDialog_23362_Content_33 = {
    Text = "Hehe…… Cái gọi là công chúa ngoại quốc, chẳng qua chỉ là lớp vỏ giả tạo mà thôi. Tôi là người nhà quê Constance chính gốc đấy."
  },
  AvgDialog_23362_Content_34 = {
    Text = "A……<Big:Aaa!>"
  },
  AvgDialog_23362_Content_35 = {
    Text = "<Gray:Bí mật quan trọng như vậy, phu nhân lại cứ thế nói cho tôi biết!>"
  },
  AvgDialog_23362_Content_36 = {
    Text = "<Gray:Hay là vì tôi đưa thư mời cho gã tóc xoăn kia, bị phu nhân biết rồi, muốn giết tôi diệt khẩu……>"
  },
  AvgDialog_23362_Content_37 = {
    Text = "\"Cái Chết Của Tường Vi\" là vở kịch tôi yêu thích nhất hồi nhỏ."
  },
  AvgDialog_23362_Content_38 = {
    Text = "Thăm bạn bè, đi dưỡng bệnh, ra ngoài mua sắm……"
  },
  AvgDialog_23362_Content_39 = {
    Text = "Tôi đã tìm đủ mọi cớ, chỉ để được đứng ngoài nhà hát lén nghe năm phút."
  },
  AvgDialog_23362_Content_4 = {
    Text = "Cảm thấy tốt hơn nhiều rồi."
  },
  AvgDialog_23362_Content_40 = {
    Text = "Vì tôi quá bận. Piano, thêu thùa, rồi cả lễ nghi……\nMọi kỹ năng có thể lấy lòng giới quý tộc, tôi đều phải học."
  },
  AvgDialog_23362_Content_41 = {
    Text = "Phong thái của phu nhân đủ khiến cả công chúa hoàng gia cũng phải lu mờ! Đây chẳng phải như câu tục ngữ nói sao, ừm, con chim dậy sớm thì có sâu ăn……"
  },
  AvgDialog_23362_Content_42 = {
    Text = "A, không phải, là cơ hội chỉ dành cho người có sự chuẩn bị!"
  },
  AvgDialog_23362_Content_43 = {
    Text = "<Gray:Mình đúng là đồ ngốc. Tối nay chắc là ngày tận số của mình rồi, hehe……>"
  },
  AvgDialog_23362_Content_44 = {
    Text = "Sau đó tôi nghe vở opera một cách chắp vá, nhưng tôi không thích cái kết của nó."
  },
  AvgDialog_23362_Content_45 = {
    Text = "Cô gái nhà quê đó đã thành công len lỏi vào giới thượng lưu Cité, nhưng lại yêu một chàng quý tộc bất tài, cuối cùng vì hắn mà chết."
  },
  AvgDialog_23362_Content_46 = {
    Text = "Thật, thật là kết cục buồn…… Garen cũng không thích. Garen ghét bi kịch!"
  },
  AvgDialog_23362_Content_47 = {
    Text = "Đúng vậy, không ai thích bi kịch cả."
  },
  AvgDialog_23362_Content_48 = {
    Text = "Sau khi góp vốn vào nhà hát, việc đầu tiên tôi làm là đổi tên và kết cục của \"Cái Chết Của Tường Vi\"."
  },
  AvgDialog_23362_Content_49 = {
    Text = "Cuối cùng ta cũng có thể tùy ý làm mọi thứ ta muốn.\nHoặc nói cách khác, ta <Yellow:tưởng rằng> cuối cùng ta cũng có thể tùy ý làm mọi thứ."
  },
  AvgDialog_23362_Content_5 = {
    Text = "Vậy thì tốt. Xem ra mấy thứ công nghệ y tế mà Winkel ngày thường mày mò nghiên cứu cũng có ích đấy chứ."
  },
  AvgDialog_23362_Content_50 = {
    Text = "Soreil ngẩn ngơ nhìn chất lỏng màu vàng kim trong ly, cùng những bong bóng sủi lên từ đáy cốc."
  },
  AvgDialog_23362_Content_51 = {
    Text = "Tài sản, danh lợi, tri thức… Con người đổ xô theo đuổi chúng, bởi vì một khi sở hữu được chúng, họ sẽ có được tự do."
  },
  AvgDialog_23362_Content_52 = {
    Text = "Tự do thay đổi cái kết vở opera mà mình không thích, hay tự do mua một viên hồng ngọc Cameo mà mình yêu thích."
  },
  AvgDialog_23362_Content_53 = {
    Text = "Con người là một loài sinh vật đơn giản như vậy đấy."
  },
  AvgDialog_23362_Content_54 = {
    Text = "Phu nhân, sao lại đột nhiên nói những chuyện này, nặng nề quá, haha…"
