  AvgDialog_23362_Content_55 = {
    Text = "Con luôn là một đứa trẻ lanh lợi. Dù có rời xa ta, chắc chắn cũng sẽ sống tốt thôi."
  },
  AvgDialog_23362_Content_56 = {
    Text = "Soreil nhẹ nhàng xoa đầu Garen."
