  AvgDialog_23362_Content_57 = {
    Text = "Phu… phu nhân…"
  },
  AvgDialog_23362_Content_58 = {
    Text = "Người nói vậy, là muốn bỏ rơi Garen sao…"
  },
  AvgDialog_23362_Content_59 = {
    Text = "Không ai sẽ bỏ rơi con cả, Garen. Con luôn luôn tự do."
  },
  AvgDialog_23362_Content_6 = {
    Text = "Tiếp theo tôi cũng không vòng vo với cậu nữa. %player%, cậu có thể phải chuẩn bị vào Mật Cảnh nhân tạo thêm một lần nữa."
  },
  AvgDialog_23362_Content_60 = {Text = "Xì……"},
  AvgDialog_23362_Content_61 = {
