  },
  AvgDialog_23362_Content_63 = {Text = "Xì……"},
  AvgDialog_23362_Content_64 = {
    Text = "Tiếng xào xạc dần yếu đi, nhưng bóng đen thì không còn động tĩnh gì nữa."
  },
  AvgDialog_23362_Content_65 = {Text = "Hả…?"},
  AvgDialog_23362_Content_66 = {
    Text = "Soreil ngạc nhiên quay người lại."
