  AvgDialog_23362_Content_7 = {
    Text = "Cái gì……?!"
  },
  AvgDialog_23362_Content_70 = {
    Text = "Bắt được thằng cha này tốn không ít công sức đấy. Nhờ lần giao đấu trước, ta mới nắm rõ được chiến thuật của nó."
