  AvgDialog_23363_Content_10 = {
    Text = "Nhận rõ. Tầng hai hiện tại mọi thứ bình thường."
  },
  AvgDialog_23363_Content_11 = {
    Text = "Còn hai mươi phút nữa mới đến buổi biểu diễn……không có việc gì, để tôi đi tìm phu nhân Soreil trước."
  },
  AvgDialog_23363_Content_12 = {
    Text = "Ừm, hãy cẩn thận mọi việc. Nguyện Chìa Khóa Bạc soi sáng con đường phía trước."
  },
  AvgDialog_23363_Content_13 = {
    Text = "Cùng một vở kịch, cùng một hành lang."
