  AvgDialog_23363_Content_14 = {
    Text = "Bạn thành thạo kéo tấm rèm của phòng VIP sang trọng."
  },
  AvgDialog_23363_Content_15 = {
    Text = "Cùng với hương rượu nồng nàn và tiếng leng keng của trang sức va chạm, một vật thể mềm mại bất ngờ lao vào vòng tay bạn."
  },
  AvgDialog_23363_Content_16 = {
    Text = "Cuối cùng cậu cũng đến rồi, tôi đợi cậu lâu lắm rồi……"
  },
  AvgDialog_23363_Content_17 = {
    Text = "Soleil âu yếm ôm lấy bạn, hơi thở ấm nóng xông lên khiến mặt bạn đỏ bừng."
  },
  AvgDialog_23363_Content_18 = {
    Text = "<Shake:Đ-đợi tôi?>"
  },
  AvgDialog_23363_Content_19 = {
    Text = "Đúng vậy, chẳng phải đã hẹn thương thảo sao……Ơ, cậu không phải phu nhân Bernard?"
  },
  AvgDialog_23363_Content_2 = {
    Text = "Mật cảnh nhân tạo lần thứ hai: Nhà hát Covent\nNgày Soreil tử vong"
