  AvgDialog_23363_Content_21 = {
    Text = "Đừng lấy bộ đó ra lừa tôi.\nNgười trong giới đều biết, Bộ phận Điều tra @2 chẳng qua chỉ là bình phong mà Messager treo ở sở cảnh sát thôi～"
  },
  AvgDialog_23363_Content_22 = {
    Text = "Ôi chao, tôi lỡ nói ra bí mật của các cậu rồi sao……Xin lỗi, hình như tôi uống hơi nhiều rồi."
