  AvgDialog_23363_Content_24 = {
    Text = "<Gray:Sao cô ấy lại uống rượu……? Lần trước rõ ràng rất tỉnh táo mà.>"
  },
  AvgDialog_23363_Content_25 = {
    Text = "Hóa ra là ngươi! Thưa phu nhân, tên này là một kẻ cướp, {Male=anh ấy,Female=cô ấy} đã cướp thư mời của Gallen!"
  },
  AvgDialog_23363_Content_26 = {
