  },
  AvgDialog_23363_Content_30 = {
    Text = "Để cậu phải chứng kiến cảnh buồn cười rồi, %player%{Male=ngài,Female=cô}.\nThị nữ của tôi không có ý xấu gì, chỉ là hơi ngốc thôi."
  },
  AvgDialog_23363_Content_31 = {
    Text = "Hôm nay là ngày vui đáng ăn mừng, nhà hát tôi góp vốn đang diễn vở kịch tôi yêu thích nhất."
  },
  AvgDialog_23363_Content_32 = {
    Text = "Chọn lúc này để cử người đến, bọn cổ hủ ở Messager cố ý à?"
  },
  AvgDialog_23363_Content_33 = {
    Text = "Xin lỗi đã làm phiền, phu nhân Soreil. Chúng tôi nhận được tin tình báo rằng có người sẽ ám sát bà vào đêm nay."
