  AvgDialog_23363_Content_36 = {Text = "……?"},
  AvgDialog_23363_Content_37 = {
    Text = "Soreil nhẹ nhàng nhấp một ngụm champagne trong ly, hàng mi dài khẽ rung, thân thiện nháy mắt với bạn."
  },
  AvgDialog_23363_Content_38 = {
    Text = "Cậu là người được họ cử đến bảo vệ tôi đúng không? Đã có một hiệp sĩ nhỏ rồi, tại sao phải đi chứ?"
  },
  AvgDialog_23363_Content_39 = {
    Text = "Rất tiếc, hiện thực không đẹp đẽ như trong sách tranh đâu. Hiệp sĩ đơn thương độc mã không cứu được công chúa, chỉ có thể đưa nàng chạy trốn thôi."
  },
  AvgDialog_23363_Content_4 = {
    Text = "■Người sở hữu mật cảnh: Soreil·@2\n■Người xâm nhập mật cảnh: %player%, Ramona\n\n■Mục đích xâm nhập: <Yellow:Dựa trên kết quả xâm nhập mật cảnh lần thứ nhất, tìm kiếm nguồn dao động Ngân Tâm ở tầng một>"
  },
  AvgDialog_23363_Content_40 = {
    Text = "Chạy trốn… chạy đi đâu? Đến nơi mà kẻ xấu không tìm được sao?"
  },
  AvgDialog_23363_Content_41 = {
    Text = "Bà có thể hiểu như vậy…"
  },
  AvgDialog_23363_Content_42 = {
    Text = "Pfft. Trên đời này còn có nơi mà kẻ xấu không tìm được sao? Tôi chưa từng thấy bao giờ."
  },
  AvgDialog_23363_Content_43 = {
    Text = "Hướng mười giờ rưỡi, có một người đàn ông đang lén tiến lên. Nhanh đi ra lối thoát bên phải, chúng ta cùng chặn hắn lại."
  },
  AvgDialog_23363_Content_44 = {Text = "?！"},
  AvgDialog_23363_Content_45 = {
    Text = "Xin lỗi, phu nhân Soreil. Tôi ra ngoài một chút, sẽ quay lại ngay."
  },
  AvgDialog_23363_Content_5 = {
    Text = "Rất tốt, lần này chúng ta có chuẩn bị trước, đã né được nước tắm của Karen một cách suôn sẻ, còn giành được hai tấm thư mời từ tay cô ấy."
  },
  AvgDialog_23363_Content_6 = {
    Text = "Thật là hả hê!"
  },
  AvgDialog_23363_Content_7 = {
    Text = "Phải nói rằng, khả năng né tránh linh hoạt của cậu đã để lại ấn tượng sâu sắc cho tôi."
  },
  AvgDialog_23363_Content_8 = {
    Text = "Khụ khụ, quay lại chủ đề chính đi. Tầng một có động tĩnh gì không?"
  },
  AvgDialog_23363_Content_9 = {
    Text = "Tạm thời an toàn. Lần trước khi vào mật cảnh, hướng mười giờ từng xuất hiện dấu hiệu hoạt động Ngân Tâm yếu ớt, lần này tôi sẽ chú ý hơn."
  },
  AvgDialog_23364_Content_1 = {
    Text = "Mật cảnh nhân tạo lần hai: Nhà hát Covent\nHành lang tầng hai"
  },
  AvgDialog_23364_Content_10 = {
    Text = "Rất tốt. Chiến dịch bắt giữ trong mật cảnh nhân tạo lần thứ hai, bắt đầu ngay!"
  },
  AvgDialog_23364_Content_11 = {
    Text = "Bạn vận động tay chân một chút, rồi nhanh chóng lao về phía người đàn ông."
  },
  AvgDialog_23364_Content_2 = {
    Text = "Cẩn thận. Hắn ở ngay chỗ góc rẽ phía trước."
  },
  AvgDialog_23364_Content_3 = {
    Text = "<Small:Suỵt… đừng nói. Tôi thấy hắn rồi.>"
  },
  AvgDialog_23364_Content_4 = {
    Text = "Người đàn ông ẩn nấp ở nơi không xa phòng VIP, gần như hòa làm một với bóng tối phía sau. Từ tiếng thở đục và chậm rãi của hắn, có thể thấy đây là một người già."
  },
  AvgDialog_23364_Content_5 = {
    Text = "Vừa dứt lời, bóng tối liền rung động nhẹ đến mức gần như không thể nhận ra."
  },
  AvgDialog_23364_Content_6 = {
    Text = "Ai ở đằng kia?!"
  },
  AvgDialog_23364_Content_7 = {
    Text = "Bạn cách hắn ít nhất 30 feet, không ngờ lại bị phát hiện."
  },
  AvgDialog_23364_Content_8 = {
    Text = "Khá nhạy bén đấy, khỏi mất công tôi phải chào hỏi rồi. Ramona, sẵn sàng chưa?"
  },
  AvgDialog_23364_Content_9 = {
    Text = "Sẵn sàng chiến đấu bất cứ lúc nào."
  },
  AvgDialog_23365_Content_1 = {Text = "Ư——!!"},
  AvgDialog_23365_Content_10 = {
    Text = "Cái gì thế——"
  },
  AvgDialog_23365_Content_11 = {
    Text = "Khi định thần lại, trước mắt đã chẳng còn ai."
  },
  AvgDialog_23365_Content_13 = {
    Text = "Gã này không phải cái bóng đen đeo mặt nạ kia, biết đâu đây là chiêu nghi binh của kẻ thù."
  },
  AvgDialog_23365_Content_14 = {
    Text = "Tôi đi truy đuổi hắn, cậu mau quay lại phòng VIP của Soreil xem sao."
  },
  AvgDialog_23365_Content_15 = {
    Text = "Hiểu rồi, luôn giữ liên lạc."
  },
  AvgDialog_23365_Content_16 = {
    Text = "Sau khi Ramona vội vã rời đi, bạn nhặt lên vật mà người đàn ông vừa ném ra."
  },
  AvgDialog_23365_Content_17 = {
    Text = "Đây là một con dao găm tinh xảo sắc bén, cán dao khắc hoa văn phức tạp tinh tế, trông có vẻ giá trị không nhỏ."
  },
  AvgDialog_23365_Content_18 = {
    Text = "Hắn không định dùng thứ này để giết phu nhân Soreil chứ?"
  },
  AvgDialog_23365_Content_19 = {
    Text = "Ngoài ra, với tư cách là một người già, động tác của ông ta nhanh nhẹn quá mức… Bệnh nhân Dung thực?"
  },
  AvgDialog_23365_Content_2 = {
    Text = "Lão già bị các bạn dễ dàng quật ngã xuống đất, ông ta nhanh chóng giơ tay lên, dùng ống tay áo che kín khuôn mặt mình."
  },
  AvgDialog_23365_Content_20 = {
    Text = "Nếu là bệnh nhân Dung thực đã đột biến, thì hoàn toàn có khả năng giết được Soreil…"
  },
  AvgDialog_23365_Content_21 = {
    Text = "Bạn bối rối gãi gãi đầu."
  },
  AvgDialog_23365_Content_23 = {
    Text = "Buổi biểu diễn sắp bắt đầu rồi. Dù sao đi nữa, quay lại xem tình hình trước đã."
  },
  AvgDialog_23365_Content_3 = {
    Text = "Nói đi, ngươi là ai? Tại sao lại tấn công phu nhân Soreil?"
  },
  AvgDialog_23365_Content_4 = {
    Text = "Thẩm vấn ta? Heh heh… Các ngươi là cái gì. Nói đi, thủ lĩnh của các ngươi là ai?"
  },
  AvgDialog_23365_Content_5 = {
    Text = "François hay Oliver·@2? Ta muốn… khụ khụ, nói chuyện với hắn."
  },
  AvgDialog_23365_Content_6 = {Text = "?！"},
  AvgDialog_23365_Content_7 = {
    Text = "Người đàn ông không chút do dự nêu đích danh hai vị lãnh đạo cấp cao của sở cảnh sát, giọng nói mang theo sự kiêu ngạo và bất cần khó kìm nén."
  },
  AvgDialog_23365_Content_8 = {
    Text = "Ngay sau đó, hắn bất ngờ giơ tay lên, ném mạnh một vật phát sáng ra ngoài."
  },
  AvgDialog_23366_Content_1 = {
    Text = "Mật cảnh nhân tạo lần thứ nhất: Phố Lincoln\nNgày Sorrel tử vong"
  },
  AvgDialog_23366_Content_10 = {
    Text = "Nhắc nhở nhẹ, bây giờ đã là 6 giờ 15 tối rồi, chúng ta còn phải tìm cách kiếm thư mời để vào nhà hát opera."
  },
  AvgDialog_23366_Content_11 = {
    Text = "Chính xác hơn là thư mời buổi công diễn đầu tiên tối nay của vở opera <Blue:\"Tên của Tường Vi\">."
  },
  AvgDialog_23366_Content_12 = {
    Text = "Cậu nở một nụ cười đầy tự tin với Ramona."
  },
  AvgDialog_23366_Content_13 = {
    Text = "Yên tâm đi. Tớ đã dò hỏi trước rồi, cách lấy thư mời rất đơn giản."
  },
  AvgDialog_23366_Content_14 = {
    Text = "Cứ đi theo tớ, Ramona."
  },
  AvgDialog_23366_Content_2 = {Text = "Ugh……!"},
  AvgDialog_23366_Content_3 = {
    Text = "Khụ khụ……"
  },
  AvgDialog_23366_Content_4 = {
    Text = "Khu phố phồn hoa từ từ mở ra trước mắt các cậu như một bức tranh cuộn. Lúc này đã gần tối, đèn đường lần lượt sáng lên, chiếu rọi những biển hiệu cửa hàng rực rỡ bên đường."
  },
  AvgDialog_23366_Content_5 = {
    Text = "Mọi người hối hả qua lại trên phố, tiếng cười nói và tiếng xe ngựa nối tiếp nhau, đan xen thành một bản giao hưởng vui tươi."
  },
  AvgDialog_23366_Content_6 = {
    Text = "Lâu rồi không đến khu Tây, vẫn y như cũ không thay đổi gì nhỉ!"
  },
  AvgDialog_23366_Content_7 = {
    Text = "Tớ nghĩ chúng ta có thể đi dọc theo phố Lincoln xuống phía dưới, ở đó có một tiệm bánh ngọt, có loại bánh cupcake ngon nhất thế giới!"
  },
  AvgDialog_23366_Content_8 = {
    Text = "Không biết bánh cupcake ăn trong mật cảnh nhân tạo sẽ có vị gì nhỉ……"
  },
  AvgDialog_23366_Content_9 = {
    Text = "Ramona mặt không biểu cảm giơ cổ tay lên xem giờ."
  },
  AvgDialog_23367_Content_1 = {
    Text = "Phán Xét Sụp Đổ"
  },
  AvgDialog_23367_Content_10 = {
    Text = "Hehe, bọn họ vẫn tham lam như mọi khi nhỉ.\nNếu ta đồng ý hết, chẳng phải bao nhiêu năm nỗ lực đều đổ sông đổ biển sao."
  },
  AvgDialog_23367_Content_11 = {
    Text = "Như vậy sao được chứ?"
  },
  AvgDialog_23367_Content_12 = {
    Text = "Nhưng nếu bà từ chối, Misage sẽ căn cứ theo nội dung bổ sung trong điều khoản, lập tức chấm dứt Lần Đánh Thức Thứ Hai, đồng thời công bố mọi hành vi của bà ra thiên hạ."
  },
  AvgDialog_23367_Content_13 = {
    Text = "Thực ra, e rằng bà không có lựa chọn nào khác, phu nhân Soleil."
  },
  AvgDialog_23367_Content_14 = {
    Text = "Không có lựa chọn nào khác ư? Ngươi vẫn chưa hiểu ta lắm, Người Giữ Bí Mật."
  },
  AvgDialog_23367_Content_15 = {
    Text = "Công bố ra thiên hạ… Ngươi nói xem, ta nên công bố sự tồn tại của Dung Thực ra thiên hạ, hay công bố sự tồn tại của Thể Đánh Thức ra thiên hạ đây?"
  },
  AvgDialog_23367_Content_16 = {
    Text = "Các ngươi chọn một cái đi?"
  },
  AvgDialog_23367_Content_17 = {
    Text = "Khóe miệng bà ta nở nụ cười, nhưng đáy mắt lại lạnh băng. Ngươi thừa biết mình đã đắc tội với vị phu nhân này rồi."
  },
  AvgDialog_23367_Content_18 = {
    Text = "May thay, phản ứng này của bà ấy cũng đã nằm trong tính toán của các vị đại nhân kia. Ngươi chỉ có thể cắn răng đưa ra những lời lẽ đã chuẩn bị sẵn."
  },
  AvgDialog_23367_Content_19 = {
    Text = "Xin lỗi, phu nhân Soleil. Xin đừng coi cuộc đàm phán này là lời đe dọa, đây là một sự hợp tác đôi bên cùng có lợi, các vị đại nhân bên trên hoàn toàn thành tâm về việc này…"
  },
  AvgDialog_23367_Content_2 = {
    Text = "Khế ước……tôi hiểu rồi.\nNgài ban cho bà một số năng lực đặc biệt, đổi lại, bà cũng phải làm việc cho Ngài."
  },
  AvgDialog_23367_Content_20 = {
    Text = "<Red:Thật chán, buồn ngủ quá.>"
  },
  AvgDialog_23367_Content_21 = {
    Text = "Không biết từ lúc nào âm nhạc đã ngừng hẳn, cả nhà hát opera yên tĩnh như một ngôi mộ khổng lồ."
  },
  AvgDialog_23367_Content_22 = {
    Text = "Tất cả diễn viên, khách mời, thậm chí cả Jialen đều như bị đóng băng tại chỗ, chỉ dùng đôi mắt đen ngòm nhìn chằm chằm vào ngươi và Soleil."
  },
  AvgDialog_23367_Content_23 = {
    Text = "……Hả?"
  },
  AvgDialog_23367_Content_24 = {
    Text = "Soleil chống cằm nhìn từng gương mặt cứng đờ, thở dài một tiếng u uất."
  },
  AvgDialog_23367_Content_25 = {
    Text = "Từ khoảnh khắc ngươi lại đứng trước mặt ta, ta đã biết sẽ là kết cục như thế này."
  },
  AvgDialog_23367_Content_26 = {
    Text = "Điều tồi tệ nhất cuối cùng vẫn xảy ra rồi…\nNgươi chắc chẳng biết gì về sự tồn tại mà mình đã triệu hồi đến đâu, Người Giữ Bí Mật."
  },
  AvgDialog_23367_Content_27 = {
    Text = "Giọng nói của bà ấy rất nhẹ, dường như sợ kinh động đến sự tồn tại kia."
  },
  AvgDialog_23367_Content_28 = {
    Text = "Trong đầu ngươi thoáng lướt qua bóng đen đã thấy trong Mật Cảnh lần trước."
  },
  AvgDialog_23367_Content_29 = {
    Text = "Sự tồn tại mà bà nói, chẳng lẽ là……?!"
  },
  AvgDialog_23367_Content_3 = {
    Text = "Thảo nào phân thân của bà trông giống Ngài đến vậy, bởi vì bà đã mượn sức mạnh của Ngài."
  },
  AvgDialog_23367_Content_30 = {
    Text = "Cố lợi dụng Misage để kiềm chế ta, bọn người phía trên rất thông minh, nhưng cũng có lúc sơ suất — chúng đã tính sót sự tồn tại của ngươi."
  },
  AvgDialog_23367_Content_31 = {
    Text = "……Tôi?"
  },
  AvgDialog_23367_Content_32 = {
    Text = "Thùng thùng. Thùng thùng."
  },
  AvgDialog_23367_Content_33 = {
    Text = "Từ nơi xa xăm vọng lại tiếng trống trầm thấp, sau đó là âm thanh đơn điệu nhỏ nhẹ của tiếng sáo."
  },
  AvgDialog_23367_Content_34 = {
    Text = "Rồi bạn nghe thấy tiếng hát."
  },
  AvgDialog_23367_Content_35 = {
    Text = "<RedItalic:Hỡi kẻ phản nghịch số mệnh.>"
  },
  AvgDialog_23367_Content_36 = {
    Text = "Bóng hình sinh ra từ bóng tối đứng sừng sững dưới ánh đèn sân khấu, làn sương mù trôi nổi trên khuôn mặt tựa như xúc tu đen kịt, theo tiếng sáo chậm rãi duỗi ra."
  },
  AvgDialog_23367_Content_37 = {
    Text = "Tiếng hát của Ngài khàn đục và báng bổ, bạn cảm nhận được nhịp mạch trường cửu trong đó, tựa như thủy triều lên xuống bất tận."
  },
  AvgDialog_23367_Content_38 = {
    Text = "<RedItalic:Ngươi nở rộ tuổi xuân trong bùn lầy thối rữa, ngươi leo lên những dây leo xanh biếc cao vút, ngươi chà đạp chúng sinh nhỏ bé như mình.>"
  },
  AvgDialog_23367_Content_39 = {
    Text = "<RedItalic:Dục vọng của ngươi vô biên vô tận, linh hồn ngươi đã mục nát từ lâu.>"
  },
  AvgDialog_23367_Content_4 = {
    Text = "Đây không phải chuyện cậu nên lo, điều tra viên nhỏ ạ."
  },
  AvgDialog_23367_Content_40 = {
    Text = "<RedItalic:Trong vườn tường vi bệnh hoạn của ngươi, ta đã nhìn thấy. Cuộc tàn sát tĩnh lặng ấy……>"
  },
  AvgDialog_23367_Content_41 = {
    Text = "<Red:Sắp bắt đầu rồi.>"
  },
  AvgDialog_23367_Content_5 = {
    Text = "Giờ cậu đã có được sự thật mình muốn rồi. Vậy tiếp theo, cậu định làm gì?"
  },
  AvgDialog_23367_Content_6 = {
    Text = "Thành thật mà nói, tôi thực sự chẳng làm được gì."
  },
  AvgDialog_23367_Content_7 = {
    Text = "Tôi chỉ là người nhận lệnh, đến đây để đàm phán với phu nhân. Đây là các điều khoản do cấp trên soạn thảo, xin mời phu nhân xem qua."
  },
  AvgDialog_23367_Content_8 = {
    Text = "Cậu đưa tài liệu đã chuẩn bị sẵn cho phu nhân Soleille."
  },
  AvgDialog_23367_Content_9 = {
    Text = "Soleille nhanh chóng lướt qua những điều khoản chi chít trên giấy trắng mực đen, khóe miệng nhếch lên một nụ cười châm biếm."
  },
  AvgDialog_23368_Content_1 = {
    Text = "Đừng hòng chạy!!"
