  },
  AvgDialog_23368_Content_25 = {
    Text = "<Gray:Nụ cười đáng sợ quá…… Sau này nhất định không được tùy tiện đắc tội với người này.>"
  },
  AvgDialog_23368_Content_26 = {
    Text = "Cô Doyle nói rằng mật cảnh nhân tạo của phu nhân Sorrel đã được điều chỉnh xong, chúng ta có thể vào lại lần nữa."
