  AvgDialog_23369_Content_19 = {
    Text = "Nhưng nếu phu nhân Soleil biết được cô hầu gái thân tín nhất của bà đang ở ngoài bán lén nước tắm, thì bà sẽ nghĩ sao nhỉ?"
