  AvgDialog_23372_Content_20 = {
    Text = "Cô hầu gái lắm mồm kia nghi vấn rất lớn đấy…"
  },
  AvgDialog_23372_Content_21 = {Text = "Rầm!!"},
  AvgDialog_23372_Content_22 = {
    Text = "Có người đi ngang qua và đâm mạnh vào vai bạn. Bạn cau mày nghiêng người sang bên, nhưng cổ tay lại bị nắm chặt."
  },
  AvgDialog_23372_Content_23 = {
    Text = "<SmallShake:Này, tôi thấy cậu đứng trước áp phích của phu nhân Soreil lâu lắm rồi, cậu cũng là người hâm mộ bà ấy phải không?>"
  },
  AvgDialog_23372_Content_24 = {
    Text = "<SmallShake:Tôi đây bán giá rẻ số phòng VIP tối nay của phu nhân Soleil, cùng với lối đi mà bà ấy sẽ dùng khi rời đi……>"
  },
  AvgDialog_23372_Content_25 = {
    Text = "<SmallShake:Muốn chiêm ngưỡng nữ thần ở cự ly gần không? Đêm nay chính là thời khắc tốt nhất, cơ hội không thể bỏ lỡ đâu!>"
  },
  AvgDialog_23372_Content_26 = {Text = "……?"},
  AvgDialog_23372_Content_27 = {
    Text = "Tôi biết Soleil rất được yêu thích, nhưng không ngờ lại đến mức này……"
  },
  AvgDialog_23372_Content_28 = {
    Text = "Tôi chỉ có một câu hỏi: Có cần thiết đến vậy không?"
  },
  AvgDialog_23372_Content_29 = {
    Text = "Tch, hóa ra không phải à.\nĐừng chắn đường, đây là địa điểm giao lưu cố định của hội sùng bái Soleil chúng tôi……"
  },
  AvgDialog_23372_Content_3 = {
    Text = "<Yellow:Nhật ký điều tra mật cảnh nhân tạo lần thứ hai Ⅰ>\n\n■Mã số mật cảnh: M-B04-002\n■Thời gian thiết lập: Năm Hồng Tích 315, tháng 6 ngày @1, 2:00-6:00pm (một ngày trước khi Sorrel tử vong).\n■Địa điểm thiết lập: Phố cao Lincoln"
  },
  AvgDialog_23372_Content_30 = {
    Text = "Khoan đã, thông tin về Soleil là ai tiết lộ cho các người vậy? Nói cho tôi biết, tôi trả gấp đôi."
  },
  AvgDialog_23372_Content_31 = {
    Text = "Không hổ danh là Ramona, vẫn nhạy bén như mọi khi."
  },
  AvgDialog_23372_Content_32 = {
    Text = "Ơ……? Quan… quan tâm nhiều thế làm gì! Các người không phải cảnh sát chứ?"
  },
  AvgDialog_23372_Content_33 = {
    Text = "Trong lúc giằng co, một cỗ xe ngựa lộng lẫy từ từ dừng lại trước mặt các bạn."
  },
  AvgDialog_23372_Content_34 = {
    Text = "Một bàn tay xanh xao gầy guộc, đeo đầy nhẫn đính châu báu thò ra, trong tay còn nắm chặt một xấp phiếu vàng Tường Vi."
  },
  AvgDialog_23372_Content_35 = {
    Text = "Khụ khụ……Thông tin của cô, ta mua rồi, cô bé."
  },
  AvgDialog_23372_Content_36 = {
    Text = "Từ trong xe vọng ra một giọng nói già nua kỳ quái. Chủ nhân của giọng nói dường như đang mắc bệnh nặng, không ngừng ho, như một chiếc bễ lò lâu ngày không được sửa chữa."
  },
  AvgDialog_23372_Content_37 = {
    Text = "Ôi chao! Nhiều… nhiều tiền thế này? Toàn bộ là của tôi sao?"
  },
  AvgDialog_23372_Content_38 = {
    Text = "Người trong xe dường như có chút mất kiên nhẫn, ra vẻ muốn rút tay lại."
  },
  AvgDialog_23372_Content_39 = {
    Text = "Cô bé vội vàng nhét một mẩu giấy qua, sau đó với tốc độ nhanh nhất rút lấy xấp phiếu vàng, cười tít mắt thành một đường."
  },
  AvgDialog_23372_Content_4 = {
    Text = "■Chủ sở hữu Mật Cảnh: Soreil·@2\n■Kẻ xâm nhập Mật Cảnh: %player%, Ramona\n\n■Mục đích xâm nhập: <Yellow:Điều tra môi trường xung quanh nhà hát, thu thập thêm manh mối.>"
  },
  AvgDialog_23372_Content_40 = {
    Text = "Đây là thông tin ngài cần! Thưa ngài cao quý hào phóng, chúc ngài mau chóng khỏe mạnh, sống lâu trăm tuổi!"
  },
  AvgDialog_23372_Content_41 = {
    Text = "Chưa đợi cô bé nói xong, cỗ xe ngựa đã nhanh chóng rời đi."
  },
  AvgDialog_23372_Content_42 = {
    Text = "Vị lão tiên sinh này trông không giống người sùng bái Soleil. Đuổi theo xem sao."
  },
  AvgDialog_23372_Content_5 = {
    Text = "Trên con phố nhộn nhịp, người đi bộ và xe ngựa qua lại tấp nập, không khí lễ hội vui tươi tràn ngập khắp nơi."
  },
  AvgDialog_23372_Content_6 = {
    Text = "Còn một ngày nữa mới đến buổi biểu diễn opera, nhưng áp phích vở diễn đã được dán khắp mọi ngóc ngách."
  },
  AvgDialog_23372_Content_7 = {
    Text = "Điều thú vị là, phu nhân Soreil với tư cách cổ đông của nhà hát đã chiếm phần lớn diện tích trên áp phích, chẳng ai thực sự quan tâm vở diễn kể về điều gì."
  },
  AvgDialog_23372_Content_8 = {
    Text = "\"\"Tên của Tường Vi\" là vở opera đầu tiên được trình diễn sau khi phu nhân Soreil góp vốn vào <Blue:Nhà hát Covent>.\""
  },
  AvgDialog_23372_Content_9 = {
    Text = "\"Ngày nay, dấu hiệu của việc gia nhập giới thượng lưu không phải là mặc lụa từ phương Đông, cũng không phải sở hữu một chiếc bình gốm cổ từ Lemvahi...\""
  },
  AvgDialog_23841_Content_1 = {
    Text = "Bạn đã cho tài xế đi rồi, viện quân của địch có nhiều không?"
  },
  AvgDialog_23841_Content_10 = {
    Text = "Từ đầu, cuộc tấn công của chúng đã mang tính mục đích, nhằm ép chúng ta đến đây —— Bến số 2, Cảng thứ ba."
  },
  AvgDialog_23841_Content_11 = {
    Text = "Có vẻ như ở đây không có gì đặc biệt cả.."
  },
  AvgDialog_23841_Content_12 = {
    Text = "Đúng, bến đỗ số 2 này không có gì đặc biệt."
  },
  AvgDialog_23841_Content_13 = {
    Text = "Thực sự có vấn đề là con <Yellow:tàu>."
  },
  AvgDialog_23841_Content_14 = {Text = "Tàu?"},
  AvgDialog_23841_Content_15 = {
    Text = "Lời nói của Ramona đã tạo ra một cơn gió mạnh, lập tức xua tan đám sương mù dày đặc trong đầu."
  },
  AvgDialog_23841_Content_16 = {Text = "!"},
  AvgDialog_23841_Content_17 = {
    Text = "Một con tàu lớn lặng lẽ xuất hiện phía sau các người, che phủ bầu trời và chặn ánh trăng, bao trùm tất cả trong bóng tối dày đặc."
  },
  AvgDialog_23841_Content_18 = {
    Text = "Con tàu khổng lồ bất ngờ xuất hiện giữa không trung, đám người cá vây quanh các ngươi bỗng chốc reo hò đầy kinh ngạc, tiếp đó liền có những hành động kỳ dị đến khó tin."
  },
  AvgDialog_23841_Content_19 = {
    Text = "Xem họ kìa!"
  },
  AvgDialog_23841_Content_2 = {
    Text = "Số lượng địch quá nhiều, đường lui cũng đã bị chúng bao vây chặt."
  },
  AvgDialog_23841_Content_20 = {
    Text = "Người cá xếp thành hàng dài, liên tiếp lao vào con tàu lớn, giống như những kẻ không sợ chết lao xuống biển."
  },
  AvgDialog_23841_Content_21 = {
    Text = "Điều kỳ lạ hơn nữa là, mỗi khi màng tay của người cá sắp chạm vào thân tàu, thân tàu đều rung động và phát ra ánh huỳnh quang nhạt, đẩy tất cả những người cá cố gắng chạm vào nó xuống nước."
  },
  AvgDialog_23841_Content_22 = {
    Text = "Con tàu này… có phải đang từ chối sự tiếp cận của những murloc không?"
  },
  AvgDialog_23841_Content_23 = {
    Text = "Vỏ tàu bên ngoài bị rỉ sét, phai màu nặng nề, không thể nhìn rõ lớp sơn ban đầu của con tàu khổng lồ; tên tàu được sơn trắng cũng mờ mịt, khó lòng phân biệt."
  },
  AvgDialog_23841_Content_24 = {Text = "Sona…"},
  AvgDialog_23841_Content_25 = {
    Text = "<Blue:Sơn Namiel>. \nErika, có ghi chép về Misaque trong hồ sơ không?"
  },
  AvgDialog_23841_Content_26 = {
    Text = "Số Na Ni Nhĩ Hào, từng thuộc <Blue:Công ty Vận tải Hắc Tinh>, chở khách vượt đại dương."
  },
  AvgDialog_23841_Content_27 = {
    Text = "Sau khi Công ty Hắc Tinh phá sản, tàu Sonanir đã được một chủ sở hữu giấu tên mua lại, đổi đăng ký và cải tạo thành tàu hàng."
  },
  AvgDialog_23841_Content_28 = {
    Text = "Tiền bối Viliam! Anh có biết con tàu này không?"
  },
  AvgDialog_23841_Content_29 = {
    Text = "Năm 288 sau Hồng Tích, tàu Sonanir đã chìm trong một cơn bão. Nhiều năm sau đó, dọc theo bờ biển Biển Bắc bắt đầu xuất hiện các bản ghi về việc nhìn thấy \"<Blue:tàu ma>\"."
  },
  AvgDialog_23841_Content_3 = {
    Text = "Biển được ánh trăng chiếu sáng vẫn đang tạo nên gợn sóng, ở những góc tối mà ánh sáng không thể thâm nhập, không biết còn ẩn giấu bao nhiêu kẻ thù."
  },
  AvgDialog_23841_Content_30 = {
    Text = "Đã có một điều tra viên Misaque đã lên tàu Sonanir, nhưng không mang về bất kỳ thông tin hữu ích nào."
  },
  AvgDialog_23841_Content_31 = {
    Text = "Không có thông tin hữu ích để báo cáo.."
  },
  AvgDialog_23841_Content_32 = {
    Text = "Nhưng điều này có nghĩa là, điều tra viên đã trở về trường an toàn, đúng không?"
  },
  AvgDialog_23841_Content_33 = {
    Text = "Đúng, mặc dù đã mất một phần ký ức, nhưng việc lên tàu không gây ra bất thường nào khác cho thân thể anh. \nSau một khoảng thời gian ngắn nghỉ ngơi, anh lại trở lại tuyến đầu của cuộc điều tra."
  },
  AvgDialog_23841_Content_34 = {
    Text = "Có thể cho vị tiền bối ấy liên lạc được không?"
  },
  AvgDialog_23841_Content_35 = {
    Text = "… rất tiếc.\nNgay từ trước khi bạn gia nhập Misaque, anh ấy đã hy sinh trong một nhiệm vụ."
  },
  AvgDialog_23841_Content_36 = {
    Text = "Đợi đã! Ramona, cô không thể muốn…"
  },
  AvgDialog_23841_Content_37 = {
    Text = "Ừ, tôi không nghĩ chúng sẽ để chúng ta chờ đến khi có người đến cứu."
  },
  AvgDialog_23841_Content_38 = {
    Text = "Các người cá không còn lao vào cố gắng chạm vào tàu Sonanil, mà thay vào đó là nhắm vũ khí về phía các người. Vòng vây đang dần thu hẹp, bạn và Ramona không còn đường lui, gần như sắp va phải thân tàu."
  },
  AvgDialog_23841_Content_39 = {
    Text = "Ramona hít sâu một hơi, đưa tay chạm vào cầu thang hạ xuống từ thành tàu."
  },
  AvgDialog_23841_Content_4 = {
    Text = "Lùi@2——!@1! dạy@1!"
  },
  AvgDialog_23841_Content_40 = {
    Text = "Khác với những người cá bị hất văng ra vài mét, ngón tay của cô ấy thực sự đặt lên thân tàu. \nBạn và cô ấy trao nhau ánh mắt, rồi cũng đặt tay lên thân tàu."
  },
  AvgDialog_23841_Content_41 = {
    Text = "Một lực cản nhẹ khiến tay bạn dừng lơ lửng giữa không trung, nhưng ngay sau đó lực cản biến mất, cảm giác lạnh buốt của thép xuyên qua găng tay, gây cảm giác tê tái da đầu."
  },
  AvgDialog_23841_Content_42 = {
    Text = "Tàu Sonanier này, <Yellow:không từ chối các người>."
  },
  AvgDialog_23841_Content_43 = {
    Text = "Bây giờ chúng ta lên tàu."
  },
  AvgDialog_23841_Content_5 = {
    Text = "Sau khi thu hẹp vòng vây đến mức nhỏ nhất, quái vật người cá không tiếp tục tấn công mà đối đầu với các ngươi tại một vị trí neo đậu, miệng liên tục phát ra những lời nói mê sảng kỳ lạ."
  },
  AvgDialog_23841_Content_6 = {
    Text = "Tại sao chúng không tiếp tục tấn công chúng ta?"
  },
  AvgDialog_23841_Content_8 = {
    Text = "Ramona, có chuyện gì vậy?"
  },
  AvgDialog_23841_Content_9 = {
    Text = "Dù dùng số lượng để dồn chúng ta về phía bắc, hay cuối cùng phong tỏa lối ra, địch vẫn luôn chừa lại một đường lui."
  },
  AvgDialog_23842_Content_1 = {
    Text = "Căn nhà an toàn mà thuyền trưởng bảo tôi nằm sau cánh cửa này."
  },
  AvgDialog_23842_Content_10 = {
    Text = "Cậu bé mặt khó chịu này đội vương miện tên là Tulô, còn người bên cạnh tên là……"
  },
  AvgDialog_23842_Content_12 = {
    Text = "Tôi, tôi có lẽ chưa từng hỏi tên của bạn, …"
  },
  AvgDialog_23842_Content_13 = {
    Text = "Muphí gãi đầu một cách ngại ngùng, lẩn sau lưng thuyền trưởng và để người lớn duy nhất xử lý tình huống xã hội không phù hợp này."
  },
  AvgDialog_23842_Content_14 = {
    Text = "Tôi là %player%, là sinh viên của Đại học Misaque."
  },
  AvgDialog_23842_Content_15 = {
    Text = "Bạn chính là thuyền trưởng phải không? Trường tôi từng ghi nhận, có một tiền bối của trường này đã lên tàu Sonanir."
  },
  AvgDialog_23842_Content_16 = {
    Text = "Đội trưởng lấy hộp thuốc lá từ túi thắt lưng, vừa khẽ gẩy lên ít lá thuốc cuối cùng thì Muphí đã nhẹ nhàng vỗ vào tay anh."
  },
  AvgDialog_23842_Content_17 = {
    Text = "Không phải anh đã hứa với tôi là sẽ không bao giờ hút thuốc nữa sao."
  },
  AvgDialog_23842_Content_18 = {
    Text = "Thuyền trưởng cười chua chát, cất hộp thuốc lá."
  },
  AvgDialog_23842_Content_19 = {
    Text = "Tôi nhớ bộ đồng phục học sinh của bạn. Thật đáng tiếc, bây giờ không phải là thời điểm tốt. \nNếu đổi sang ngày khác lên tàu, tôi còn có thể rót cho bạn một ly rượu để trò chuyện thoải mái."
  },
  AvgDialog_23842_Content_2 = {
    Text = "Lúc đó chúng ta đã hẹn ám hiệu là gì nhỉ...ba nhẹ một nặng? nhẹ nhẹ nặng nhẹ?"
  },
  AvgDialog_23842_Content_20 = {
    Text = "Elton, mình là Elton."
  },
  AvgDialog_23842_Content_21 = {
    Text = "Khi các bạn tự giới thiệu, Muphí đã đi một vòng trong cabin mờ tối. Khi cô ấy lọt vào tầm mắt các bạn lần nữa, trông đầy vẻ nghi hoặc."
  },
  AvgDialog_23842_Content_22 = {
    Text = "Thuyền trưởng, Hilaster không ở bên cạnh anh?"
  },
  AvgDialog_23842_Content_3 = {Text = "—— ya!"},
  AvgDialog_23842_Content_4 = {
    Text = "Khi Muphí đang cố gắng nhớ mật khẩu, toát mồ hôi, cửa bất ngờ được mở ra từ bên trong và một bàn tay kéo cô vào trong."
  },
  AvgDialog_23842_Content_5 = {
    Text = "Tulô nhanh mắt lẹ tay đỡ cửa không để nó đóng lại, anh ấy và bạn liếc mắt nhìn nhau rồi đồng thời lách mình vào trong."
  },
  AvgDialog_23842_Content_6 = {
    Text = "Tàu, thuyền trưởng! Thật tốt, quả nhiên anh đang chờ tôi ở đây…"
  },
  AvgDialog_23842_Content_7 = {
    Text = "Người đàn ông trung niên có làn da ngăm đen, mặc trang phục thủy thủ, vỗ nhẹ vào đầu Murphy để thể hiện sự quan tâm."
  },
  AvgDialog_23842_Content_8 = {
    Text = "Nói là làm, đó là điều người lớn phải tuân thủ."
  },
  AvgDialog_23842_Content_9 = {
    Text = "Nói đến đây, hai người này là?"
  },
  AvgDialog_23843_Content_10 = {
    Text = "Ramona cẩn thận!"
  },
  AvgDialog_23843_Content_11 = {
    Text = "Bạn lấy ra chìa khóa bạc, cố gắng dùng liên kết để kiềm chế thân thể được đánh thức đang bùng nổ của cậu thiếu niên."
  },
  AvgDialog_23843_Content_12 = {
    Text = "Nhưng bạn gần như ngay lập tức nhận ra điều không ổn: tinh thần của anh ta vô cùng ổn định, và một chuỗi khóa hình con rắn đang kéo ý thức của anh ta về phía không xa."
  },
  AvgDialog_23843_Content_13 = {
    Text = "——kéo theo người liên kết của anh ta."
  },
  AvgDialog_23843_Content_14 = {
    Text = "Bóng ma méo mó lao ra từ đám người dấn thân vào biển, đập mạnh vào tay bạn cầm chìa khóa bạc với tốc độ chớp nhoáng, lực đạo đó hất bạn vào thành tàu."
  },
  AvgDialog_23843_Content_15 = {
    Text = "Kaikes, quá lâu rồi."
  },
  AvgDialog_23843_Content_16 = {
    Text = "Thưa ngài Miriam! Cho tôi thêm một cơ hội nữa, tôi nhất định sẽ giải quyết hai người này!"
  },
  AvgDialog_23843_Content_17 = {
    Text = "Người phụ nữ đội vương miện gai nhọn lạnh lùng liếc nhìn anh ta, không đáp lại. Ánh mắt chuyển sang Ramona đang cầm kiếm, rồi hướng về phía bạn, cuối cùng dừng lại trên chiếc chìa khóa bạc vẫn phát sáng mờ ảo trước ngực bạn."
  },
  AvgDialog_23843_Content_18 = {
    Text = "Chìa khóa bạc……"
  },
  AvgDialog_23843_Content_19 = {
    Text = "Vào khoảnh khắc tiếp theo, bóng rắn bắn ra từ dưới khăn voan của cô ấy, bò lên thân thể bạn như một con rắn độc."
  },
  AvgDialog_23843_Content_2 = {
    Text = "Hừm…! Rõ ràng chỉ là loài người thấp kém, sao lại khó đối phó như vậy……"
  },
  AvgDialog_23843_Content_20 = {
    Text = "Đó đích thực là \"rắn độc\", một con rắn hình thành từ năng lượng tím bị cuốn vào cổ tay, những chiếc răng toả ra năng lượng bấtchi tiết đang nhắm vào bạn một cách âm hiểm——"
  },
  AvgDialog_23843_Content_22 = {
    Text = "Đừng chạm vào {Male=anh ấy,Female=cô ấy}!"
  },
  AvgDialog_23843_Content_23 = {
    Text = "Ramona quay người ném ra thanh kiếm mảnh, đánh tan một bóng rắn đang rình rập bạn."
  },
  AvgDialog_23843_Content_24 = {
    Text = "Vài giây sau, đôi chân của cô bùng nổ lực lượng kinh người, cô gần như bay vút qua hai người kia đến bên cạnh bạn, kéo bạn ngã xuống đất, đồng thời tránh được đòn tấn công tiếp theo của bóng rắn."
  },
  AvgDialog_23843_Content_25 = {
    Text = "Chúng ta không phải là đối thủ của người phụ nữ đó, mau lên thuyền cứu sinh!"
  },
  AvgDialog_23843_Content_26 = {
    Text = "Ramona không cho bạn cơ hội phản kháng, đẩy bạn vào thuyền cứu sinh một cách dứt khoát."
  },
  AvgDialog_23843_Content_27 = {
    Text = "Sau đó, cô ấy nhảy lên mạn thuyền, hơi gập đầu gối để ổn định thân thể, và nhanh chóng tuốt kiếm từ bên hông. \n Cơ chế cố định thuyền cứu sinh vỡ tung theo tiếng động, cảm giác mất trọng lực mạnh mẽ bao trùm não bạn."
  },
  AvgDialog_23843_Content_28 = {
    Text = "<Big:Ramona!>"
  },
  AvgDialog_23843_Content_29 = {
    Text = "Ramona nửa người treo ngoài tàu, bóng rắn quấn lấy cổ chân cô, kéo cô trở lại bên trong thành tàu."
  },
  AvgDialog_23843_Content_3 = {
    Text = "Thiếu niên mở to mắt kinh ngạc, trong cuộc giằng co, vây và đuôi của cậu bị lưỡi kiếm như mưa của Ramona đâm thương, máu màu xám đỏ chảy tràn lan trên boong tàu, lấp đầy các khe hở giữa các tấm gỗ."
  },
  AvgDialog_23843_Content_30 = {
    Text = "Thuyền cứu sinh mất thăng bằng khi rơi xuống, bóng tối và nước biển lạnh thấu xương tràn vào cổ họng bạn."
  },
  AvgDialog_23843_Content_31 = {
    Text = "Vào khoảnh khắc cuối cùng, bạn nhìn thấy bàn tay của Ramona đưa ra về phía mình."
  },
  AvgDialog_23843_Content_32 = {
    Text = "Ramona ngồi bệt trên boong tàu, xoa chân mình, cau mày."
  },
  AvgDialog_23843_Content_33 = {
    Text = "Kẹt——"
  },
  AvgDialog_23843_Content_34 = {
    Text = "Cô cắn chặt răng, khom người để đưa khớp mắt cá chân bị trật về vị trí cũ. Biểu cảm chỉ méo mó trong chốc lát, rồi nhanh chóng khôi phục lại vẻ kiên nghị và uy nghiêm thường ngày."
  },
  AvgDialog_23843_Content_35 = {
    Text = "Người phụ nữ với dáng vẻ của một thủ lĩnh thong dong bước tới trước mặt Ramona, nhìn xuống cô từ trên cao."
  },
  AvgDialog_23843_Content_36 = {
    Text = "Chìa khóa bạc, liên kết, thể thức tỉnh…"
  },
  AvgDialog_23843_Content_37 = {
    Text = "Khi ở cảng, ta chưa để ý đến diện mạo của các ngươi, nhưng giờ đây, tiên tri của \"Đấng Tối Cao\" quả nhiên đã thành hiện thực——không ai có thể ngăn cản các vì sao di chuyển đến chính vị, mọi thứ trong thế gian này đều đang đi về nơi chúng phải đến."
  },
  AvgDialog_23843_Content_38 = {
    Text = "Cảng… người ra lệnh cho những người dấn thân vào biển đuổi theo chúng ta, lợi dụng chúng ta để phá vỡ ranh giới thâm cảnh trên tàu, chính là ngươi."
  },
  AvgDialog_23843_Content_39 = {
    Text = "Miriam không tỏ thái độ, trên khuôn mặt xinh đẹp hiện lên một nụ cười mang vẻ thành tâm."
  },
  AvgDialog_23843_Content_4 = {
    Text = "Anh ta phải tựa vào vũ khí để có thể đứng vững, rõ ràng đã khó khăn trong việc tiếp tục chống đỡ các đòn tấn công của các người."
  },
  AvgDialog_23843_Content_40 = {
    Text = "Sinh viên của Đại học Misaque, làm thức ăn dâng cho \"Chúa\" không thể phù hợp hơn."
  },
  AvgDialog_23843_Content_41 = {
    Text = "Miriam không còn nhìn Ramona, cũng không quan tâm Ramona vẫn nắm chặt vũ khí trong tay. Cô ấy dường như đã có kế hoạch rõ ràng và không bận tâm đến sự phản kháng của Ramona."
  },
  AvgDialog_23843_Content_42 = {
    Text = "Có lẽ, cô ta rất chắc chắn rằng sự phản kháng của Ramona không còn gây ra sóng gió."
  },
  AvgDialog_23843_Content_43 = {
    Text = "Đây là cơ hội cuối cùng của ngươi, Kaikes. \nĐưa cô ấy xuống và canh gác cẩn thận."
  },
  AvgDialog_23843_Content_44 = {
    Text = "Cô sẽ trở thành vòng cuối cùng của nghi lễ, <Yellow:「Chúa tể」> tái sinh sau đó, sẽ uống cạn thịt máu thơm ngon của kẻ ngốc."
  },
  AvgDialog_23843_Content_45 = {
    Text = "<Yellow:Ngài> sẽ khiến thành phố của chúng ta nổi lên từ biển, sẽ tái hiện quốc gia của chúng ta trong thế giới hỗn loạn này, trở thành tương lai mới cho người đi biển."
  },
  AvgDialog_23843_Content_5 = {
    Text = "Bạn không giống những con quái vật đầu cá thân người kia, còn lực lượng của bạn…"
  },
  AvgDialog_23843_Content_6 = {
    Text = "Ramona vung kiếm, đầu kiếm vẽ nên những đường nét tuyệt đẹp và sắc nhọn như dao cạo, chỉ thẳng vào thiếu niên đang quỳ một gối."
  },
  AvgDialog_23843_Content_7 = {
    Text = "Bạn là thân thể được đánh thức… đúng không?"
  },
  AvgDialog_23843_Content_8 = {
    Text = "Quá phóng túng! Dòng máu của chúng ta cao quý hơn nhiều so với loài người thấp hèn, ngươi không có tư cách gọi người dấn thân vào biển là quái vật!"
  },
  AvgDialog_23843_Content_9 = {
    Text = "Lời của Ramona đã chạm đến dây thần kinh của thiếu niên, cậu bất ngờ vận hết sức toàn thân, những gai trên lưng dựng đứng lên và mạnh mẽ hất tung kiếm của Ramona ra."
  },
  AvgDialog_23844_Content_1 = {
    Text = "Chiếc xúc tu đập xuống nặng nề, thân thể của người dấn thân vào biển bị ép đến tan vỡ, nhưng kỳ diệu thay đã tránh khỏi nơi cô gái đang ở."
  },
  AvgDialog_23844_Content_10 = {
    Text = "À! Nói đến nghi lễ... cô bé, họ có làm em bị thương không? Em cứ giữ cổ tay, có bị trẹo không nhỉ?"
