  AvgDialog_23844_Content_12 = {
    Text = "Muphí, gọi tôi là Muphí."
  },
  AvgDialog_23844_Content_13 = {
    Text = "Muphí, tôi đã được đào tạo xử lý vết thương ngoài da, có thể để tôi xem tay bạn không?"
