  AvgDialog_23844_Content_14 = {
    Text = "Cô gái do dự nhìn bạn, nhưng cuối cùng đã không phản đối việc bạn lại gần và đưa ra một tay."
  },
  AvgDialog_23844_Content_15 = {
    Text = "Bạn nhẹ nhàng nắm tay cô ấy, kéo tay áo lên một chút. Cô ấy mặc trang phục mùa đông dày, ngoại trừ việc da hơi ửng đỏ vì bị kéo ra, không có dấu hiệu tổn thương nào khác."
  },
  AvgDialog_23844_Content_16 = {
    Text = "Có thể có một chút bong gân, mức độ này, nghỉ ngơi yên tĩnh trong hai ngày là ổn rồi."
  },
  AvgDialog_23844_Content_17 = {
    Text = "Cảm nhận được tâm trạng của Muphí đã dịu lại một chút, bạn khéo léo tránh né vết thương của cô ấy và đột ngột nắm chặt cánh tay trên của cô."
  },
  AvgDialog_23844_Content_18 = {
    Text = "Bạn đang làm gì vậy?!"
  },
  AvgDialog_23844_Content_19 = {
    Text = "Bạn biết đến thủ lĩnh của những người dấn thân vào biển, Miriam, nhưng lại bị những người dấn thân vào biển truy đuổi. \nMuphí, rốt cuộc bạn là ai?"
  },
  AvgDialog_23844_Content_2 = {
    Text = "Tulô rút lại xúc tu và nhìn chất lỏng màu xám xanh, đỏ trắng đan xen trên đó, vẻ mặt chán ghét của anh ta biến mất ngay sau khi anh ta lặng lẽ lau đi vết bẩn trên boong tàu."
