  AvgDialog_23844_Content_21 = {
    Text = "Lúc này, Tulô đã kết thúc việc quan sát bùa chú và tham gia vào đối thoại."
  },
  AvgDialog_23844_Content_22 = {
    Text = "Chú ngữ đó là nghi lễ thôi miên của người dấn thân vào biển. Bọn họ muốn cô ấy chợp mắt một lúc, tránh mọi phiền phức"
  },
  AvgDialog_23844_Content_23 = {
    Text = "Chưa để tulô nói xong, khuôn mặt của Muphí đã trở nên trắng nhợt. Những động tác đá và cắn loạn xạ của cô ấy đối với bạn cũng ngừng lại, dường như đang suy nghĩ điều gì đó."
