  },
  AvgDialog_23845_Content_13 = {
    Text = "Người dấn thân vào biển đa số thân thể yếu ớt, thiện sử khinh binh. Chiếc kiếm lớn này có chủ nhân khác, cẩn thận đối phó."
  },
  AvgDialog_23845_Content_14 = {
