  AvgDialog_23845_Content_15 = {
    Text = "Nhưng với vai trò là người tiên phong trong chiến tranh, một kẻ thiếu ý thức tự thân lại trở nên cực kỳ hữu dụng."
  },
  AvgDialog_23845_Content_16 = {
