  },
  AvgDialog_23845_Content_17 = {
    Text = "Anh ta rút thanh kiếm lớn đang cắm sâu vào boong tàu, giọng điệu châm chọc, ánh mắt nhìn bạn với sự đánh giá và hứng thú."
  },
  AvgDialog_23845_Content_18 = {
