  },
  AvgDialog_23845_Content_20 = {
    Text = "Tôi tên là Goliath. \n Hãy nhớ kỹ, đây là tên của người đã dẫm nát muôn biển!"
  },
  AvgDialog_23845_Content_3 = {
    Text = "Bạn gật đầu tỏ vẻ hiểu biết, đang mò mẫm trong túi tìm những món đồ vặt có thể ném đi thì tiếng bước chân nặng nề từ xa dần dần tiến lại gần."
  },
  AvgDialog_23845_Content_4 = {
    Text = "Muphí hít một hơi lạnh, vẻ mặt đầy kinh hoàng. Cô nhìn quanh một lượt, sau đó nhanh chóng giật mở tấm bạt chống nước trên thùng hàng, rồi dùng cả tay và chân leo vào trong."
