  AvgDialog_23846_Content_7 = {
    Text = "Mỗi lần chúng tấn công lên, bạn đều có thể ngửi thấy mùi hôi thối của sự suy giảm sức sống."
  },
  AvgDialog_23846_Content_8 = {
    Text = "Cũng không thể loại trừ nghi ngờ đối với Hiệp hội Điêu khắc gia, Herbert là một đồ khốn nạn lấy danh nghĩa thực nghiệm để chơi đùa với sức sống."
  },
  AvgDialog_23846_Content_9 = {
    Text = "Tôi thích cách bạn đánh giá Herbert. Tuy nhiên, đừng quên rằng hiện tượng rỗng rỗng cũng có thể gây ra sự biến dị nhóm như vậy."
  },
  AvgDialog_23847_Content_1 = {
    Text = "Bạn và Tulô trốn vào một góc đủ kín đáo, anh ta cảnh giác với xung quanh, còn bạn thì chìm vào thế giới tinh thần như một ảo ảnh."
  },
  AvgDialog_23847_Content_10 = {
