  },
  AvgDialog_23847_Content_14 = {
    Text = "Khi mở mắt ra, không gian ý thức đã biến dạng thành một hình dạng khác."
  },
  AvgDialog_23847_Content_15 = {
    Text = "Ở chân trời, thành phố méo mó vươn lên từ mặt đất. Những tiếng ồn ào không còn làm xao lạc tâm trí bạn, bốn bề im lặng, chỉ có ánh sáng u tối trước mắt đang tỏa ra hơi lạnh không ngừng."
