  },
  AvgDialog_23847_Content_17 = {
    Text = "Miriam đại nhân, bàn thờ Elworth đã bị những người trong đội phiêu lưu phá hủy! Thời điểm chính vị đã qua, cái thứ có thể thức tỉnh.."
