  AvgDialog_23852_Content_69 = {Text = "Bịch.."},
  AvgDialog_23852_Content_7 = {
    Text = "Đã sáng chưa.."
  },
  AvgDialog_23852_Content_70 = {
    Text = "Bước chân vội vã pha lẫn tiếng động kỳ quái như chân vịt vỗ vào mặt đất, dưới chân truyền đến một cơn rung nhẹ, một bóng dáng lao nhanh từ đầu kia của boong tàu tiến về phía bạn."
