  AvgDialog_23852_Content_73 = {
    Text = "Giúp tôi! %player%!"
  },
  AvgDialog_23852_Content_74 = {
    Text = "Cô gái trẻ lao đến bên bạn, nói năng hổn hển, nhưng lại nắm chặt mép áo choàng của bạn như thể đó là hy vọng cuối cùng."
  },
  AvgDialog_23852_Content_75 = {
    Text = "Còn…@2…@1 mẹ! @2!"
  },
  AvgDialog_23852_Content_76 = {
    Text = "Những thân thể này giống con người, nhưng lại có đặc điểm của sinh vật thủy sinh, phát ra những tiếng rên rỉ kỳ dị. Âm thanh không theo trật tự và chói tai, nhưng bạn lại hiểu được ý nghĩa của chúng một cách khó hiểu."
  },
  AvgDialog_23852_Content_77 = {
    Text = "Họ đang nói… \"trả lại cho chúng tôi\"?"
  },
  AvgDialog_23852_Content_78 = {
    Text = "Tiếng gầm gừ lộn xộn trở nên rõ ràng hơn trong tai bạn. \nChỉ một chút nữa thôi, bạn có thể hiểu họ muốn gì ——"
  },
  AvgDialog_23852_Content_79 = {
    Text = "Trong khoảnh khắc bạn lơ đễnh, cô gái đã dẫm mạnh lên đôi giày da của bạn."
  },
  AvgDialog_23852_Content_8 = {
    Text = "Mỗi khối xương đều như bị đánh vỡ và tái cấu trúc, toàn thân bao phủ bởi sự mệt mỏi một cách không hợp lý. \n Huyệt thái dương đau nhói, mắt cũng khô rát như có kim châm."
  },
  AvgDialog_23852_Content_80 = {Text = "Sī——"},
  AvgDialog_23852_Content_81 = {
    Text = "Bạn chỉ đứng nhìn thôi sao! Làm gì đi chứ!"
  },
  AvgDialog_23852_Content_82 = {
    Text = "Còn cậu nữa! Đừng nhìn ta, tập trung vào bản tiểu thư này đi! Cẩn thận đừng để họ bắt được."
  },
  AvgDialog_23852_Content_83 = {
    Text = "Tulô quay mặt đi, không còn nhìn bạn và cô gái. Những xúc tu vung mạnh, quét sạch từng kẻ địch lao tới ra khỏi tàu."
  },
  AvgDialog_23852_Content_84 = {
    Text = "Còn viện quân, họ đang tìm đến bạn."
  },
  AvgDialog_23852_Content_85 = {
    Text = "Cô gái mím môi, sau một lúc, mắt cô sáng lên với vẻ mặt chợt hiểu ra."
  },
  AvgDialog_23852_Content_86 = {
    Text = "Đi vào khoang tàu! Có thể tạm thời tránh khỏi họ."
  },
  AvgDialog_23852_Content_87 = {
    Text = "Cô gái tự bước lui vài bước, bạn vội vàng che chở cô ấy và theo sau. Chỉ thấy cô ấy đá bay vài tấm gỗ, trên boong tàu bỗng nhiên lộ ra một cánh cửa dẫn xuống hầm."
  },
  AvgDialog_23852_Content_88 = {
    Text = "Cánh cửa bí mật?!"
  },
  AvgDialog_23852_Content_89 = {
    Text = "Cánh cửa bí mật gì? Anh lại cứ nhất định đùa giỡn với ta vào lúc mấu chốt này sao!"
  },
  AvgDialog_23852_Content_9 = {
    Text = "Cảm giác họng như vừa nuốt một ngụm lớn xốt Worcestershire, mỗi lần thở đều mang theo cảm giác nghẹt thở và đau đớn."
  },
  AvgDialog_23852_Content_90 = {
    Text = "Đã không phải chưa từng vào khoang tàu, đừng có lề mề nữa, chuẩn bị đi!"
  },
  AvgDialog_23852_Content_91 = {
    Text = "Tulô không phản đối kế hoạch của cô gái, trong sự im lặng đầy bảo vệ của anh ta, bạn và cô gái cùng kéo cánh cửa sắt ra."
  },
  AvgDialog_23852_Content_92 = {
    Text = "Dưới lỗ cửa, cầu thang sắt kéo dài xuống, tiến thẳng vào nơi khuất tầm mắt."
  },
  AvgDialog_23852_Content_93 = {
    Text = "Nhanh lên! Bạn xuống trước đi!"
  },
  AvgDialog_23852_Content_94 = {
    Text = "Bạn không có khả năng chiến đấu, tôi có nghĩa vụ bảo vệ bạn——À!"
  },
  AvgDialog_23852_Content_95 = {
    Text = "Cô gái giả vờ không nghe thấy lời càu nhàu của bạn, cô ấy nhờ vào vóc dáng nhỏ nhắn và sự linh hoạt để lách sang phía sau bạn."
  },
  AvgDialog_23852_Content_96 = {
    Text = "—— Rồi, đá mạnh một cú thật đau vào người bạn và hất bạn vào trong bóng tối của cửa hang."
  },
  AvgDialog_23852_Content_97 = {
    Text = "<SmallShake:đau đau đau……>"
  },
  AvgDialog_23852_Content_98 = {
    Text = "Bạn dường như đã ngã vào một bãi rong biển mềm mại, mùi tanh của cá và vị mặn của nước biển ùa vào mũi, khiến cái đầu đang đau nhức của bạn cảm thấy quay cuồng."
  },
  AvgDialog_23852_Content_99 = {
    Text = "Này! Đừng cố nữa, mau xuống đi!"
  },
  AvgDialog_23853_Content_1 = {
    Text = "Trong chớp mắt người đã biến mất……\nTìm như vậy không phải là cách. Thôi, vẫn nên đi tìm Ramona"
  },
  AvgDialog_23853_Content_2 = {
    Text = "Không được, không thể để cô ấy đi!"
  },
  AvgDialog_23853_Content_3 = {
    Text = "Ho… ý của tôi là, có thể cô ấy nắm giữ chìa khóa giải mã bí ẩn của những người dấn thân vào biển."
  },
  AvgDialog_23853_Content_4 = {
    Text = "Dựa vào sự quen thuộc của cô ấy với những ngườingười dấn thân vào biển, cô ấy chắc chắn biết mục đích của họ."
  },
  AvgDialog_23853_Content_6 = {
    Text = "Tôi sẽ thử dùng theo dõi tinh thần để tìm cô ấy. \nĐây là lần đầu tiên tôi sử dụng theo dõi tinh thần để định vị con người, không chắc chắn sẽ hiệu quả."
  },
  AvgDialog_23854_Content_1 = {Text = "Dao găm"},
  AvgDialog_23854_Content_10 = {
    Text = "Thành thật mà nói, thậm chí tên của bạn, tôi cũng vừa mới nhớ ra."
  },
  AvgDialog_23854_Content_11 = {
    Text = "……ah! Không phải là cậu bị đập đầu khi bị đá xuống chứ! \nChết tiệt, tại sao lại xảy ra chuyện này vào lúc quan trọng như vậy…"
  },
  AvgDialog_23854_Content_12 = {
    Text = "Muphí bực bội gãi đầu, rõ ràng cũng chẳng biết làm gì hơn."
  },
  AvgDialog_23854_Content_13 = {
    Text = "Lý do và hậu quả… giải thích quá phức tạp. Nơi này cũng không phải là nơi an toàn, cũng nên nhanh chóng hội họp với những người khác."
  },
  AvgDialog_23854_Content_14 = {
    Text = "Người khác là chỉ ai?"
  },
  AvgDialog_23854_Content_15 = {
    Text = "Các thuyền trưởng của con tàu Sonanil này, và Ramona."
  },
  AvgDialog_23854_Content_16 = {
    Text = "Đúng rồi! Bạn có thể thử lại cái đó không? Chính là phương pháp tìm người trong thế giới tinh thần."
  },
  AvgDialog_23854_Content_17 = {
    Text = "Truy tìm tinh thần? Bạn không chỉ biết Ramona, Tulô, thậm chí còn biết tôi có thể thực hiện truy tìm tinh thần... \n Trước đây đã xảy ra chuyện gì?"
  },
  AvgDialog_23854_Content_18 = {
    Text = "Đừng rề rà! Bạn hãy tìm vị trí của Ramona trước, trên đường tôi sẽ từ từ giải thích cho bạn."
  },
  AvgDialog_23854_Content_19 = {
    Text = "Quá trình chìm vào thế giới tinh thần chưa bao giờ đau đớn đến vậy, tinh thần như đang đi qua một rừng gai, khắp nơi đều thấm đẫm những cơn đau nhói mỏng manh. Và khi bạn cuối cùng cũng nhìn thấy những đốm sáng quen thuộc ——"
  },
  AvgDialog_23854_Content_2 = {
    Text = "Tulô nói rằng chúng ta nên gặp gỡ những người khác… Hừm, anh ta nghĩ đơn giản quá."
  },
  AvgDialog_23854_Content_20 = {
    Text = "Tách tách——"
  },
  AvgDialog_23854_Content_21 = {Text = "Ugh……!"},
  AvgDialog_23854_Content_22 = {
    Text = "Những xúc tu của thần trí vừa chạm đến mép không gian tinh thần thì đã đứt rời từng sợi, như những cành leo khô héo."
  },
  AvgDialog_23854_Content_23 = {
    Text = "Cơn đau dữ dội đến mức có thể xé toạc linh hồn và cơ thể xuyên qua thái dương, khiến bạn ngã xuống trước mặt Muphí."
  },
  AvgDialog_23854_Content_24 = {
    Text = "Aí, aí?! Đừng làm tôi sợ, đừng chết đi?!"
  },
  AvgDialog_23854_Content_25 = {
    Text = "Tôi, tôi không sao…"
  },
  AvgDialog_23854_Content_26 = {
    Text = "Việc truy tìm tinh thần luôn là điểm mạnh của bạn, nhưng lúc này thân thể bạn dường như đang ngăn cản bạn lặn sâu vào thế giới tinh thần."
  },
  AvgDialog_23854_Content_27 = {
    Text = "Bạn rất chắc chắn: chính thân thể của bạn đã đẩy bạn ra khỏi thế giới tinh thần, không phải một thực thể huyền bí nào khác."
  },
  AvgDialog_23854_Content_28 = {
    Text = "@2…gừm u…"
  },
  AvgDialog_23854_Content_29 = {
    Text = "Đó là tiếng của những người dấn thân vào biển, họ đã tìm đến đây! \nKhông thể ở lại đây nữa, hãy theo tôi."
  },
  AvgDialog_23854_Content_3 = {
    Text = "Muphí lẩm bẩm đi vòng vòng trong kho hàng, sự bồn chồn lộ rõ trên nét mặt. \nBạn hít một hơi sâu và gọi cô ấy lại."
  },
  AvgDialog_23854_Content_30 = {
    Text = "Muphí vất vả đỡ bạn dậy, trọng lượng của bạn khiến đôi chân cô run rẩy. Thấy vậy, bạn hơi dịch trọng tâm về phía cabin, và cuối cùng dưới sự hỗ trợ của cô, bạn đi sâu vào trong tàu…"
  },
  AvgDialog_23854_Content_31 = {
    Text = "Các ngươi dừng lại trước một cánh cửa sắt nặng nề, trên cửa có những vết lõm kỳ lạ và phần nổi gồ ghề. Từ khe cửa không còn khép kín, mùi khói cháy gay gắt lan tỏa nhẹ nhàng."
  },
  AvgDialog_23854_Content_32 = {
    Text = "Muphí, chúng ta vào không?"
  },
  AvgDialog_23854_Content_33 = {
    Text = "Shhh, để tôi nghe…"
  },
  AvgDialog_23854_Content_34 = {
    Text = "Muphí nhẹ nhàng thả bạn ra, áp tai vào cửa và nhắm mắt lắng nghe một lúc."
  },
  AvgDialog_23854_Content_35 = {
    Text = "Dường như không có ai, chúng ta vào trốn trước đã."
  },
  AvgDialog_23854_Content_36 = {
    Text = "Trước khi Muphí mở cửa, bạn liếc nhìn nhãn trên cửa — \"phòng động lực\"."
  },
  AvgDialog_23854_Content_37 = {
    Text = "Sau cánh cửa không có cảnh tượng sôi động như bạn tưởng tượng: không có những công nhân cơ bắp cuồn cuộn, không có lò hơi đang cháy rực, chỉ có những tia lửa bắn tung tóe khắp nơi."
  },
  AvgDialog_23854_Content_38 = {
    Text = "Trên mặt đất nằm ngổn ngang vô số thân thể lạnh lẽo và cứng ngắc—— là những quái vật người cá đã đuổi theo các ngươi suốt đường."
  },
  AvgDialog_23854_Content_39 = {
    Text = "Muphí và tulô gọi họ là \"<Yellow:người dấn thân vào biển>\"."
  },
  AvgDialog_23854_Content_4 = {Text = "Muphí."},
  AvgDialog_23854_Content_40 = {
    Text = "Tường tàu đã mở ra một lỗ hổng lớn, gió lạnh tranh nhau thổi vào khoang tàu. Muphí nắn nắn dái tai mình bị đông đỏ, đỡ bạn bước qua ngọn lửa, đi vào trong cảnh hoang tàn."
  },
  AvgDialog_23854_Content_41 = {
    Text = "Khụ, khụ khụ khụ… mùi thật sự rất khó chịu."
  },
  AvgDialog_23854_Content_42 = {
    Text = "Đây… đã trải qua một trận chiến ác liệt?"
  },
  AvgDialog_23854_Content_43 = {
    Text = "Trận chiến ác liệt? Bạn dùng từ nhẹ nhàng như thế để mô tả trận chiến đó sao?"
  },
  AvgDialog_23854_Content_44 = {
    Text = "Ồ… nói đến chuyện đó, bạn vẫn chưa biết đã xảy ra điều gì."
  },
  AvgDialog_23854_Content_45 = {
    Text = "Trong phế tích hoang tàn, có thứ gì đó phản chiếu ánh sáng chói mắt."
  },
  AvgDialog_23854_Content_46 = {
    Text = "Bạn còn chưa kịp nhìn rõ đó là thứ gì, Muphí đã biến sắc, dường như vừa sợ hãi vừa buồn bã."
  },
  AvgDialog_23854_Content_47 = {
    Text = "Không biết từ khi nào, người phụ nữ đó trở nên khùng khùng điên điên như bây giờ……"
  },
  AvgDialog_23854_Content_48 = {
    Text = "Cô ấy kéo môi mình, một mặt kể về \"quá khứ\" không có hệ thống, một mặt bước về phía ánh sáng trong đống đổ nát."
  },
  AvgDialog_23854_Content_49 = {
    Text = "Cô ấy không nghe vào bất cứ điều gì, dù tôi có van xin thế nào đi nữa, cô ấy vẫn quyết tâm tổ chức buổi lễ này……"
  },
  AvgDialog_23854_Content_5 = {
    Text = "Hay là kiếm một góc nào đó ngồi xuống nhỉ……"
  },
  AvgDialog_23854_Content_50 = {
    Text = "—— Đó là một con dao găm có hình dạng kỳ lạ, nằm yên trong tro tàn của ngọn lửa đã tắt. Mặc dù lưỡi dao phủ đầy bụi bẩn, vẫn có thể thấy được độ sắc lạnhbắt người của nó."
  },
  AvgDialog_23854_Content_51 = {
    Text = "Rõ ràng… cô ấy từng đối xử với tôi thật sự rất tốt…"
  },
  AvgDialog_23854_Content_52 = {
    Text = "Muphí nhìn chằm chằm vào con dao găm trong giây lát, rồi đột nhiên bò bằng tay và chân vào đống đổ nát chồng chất, đưa tay ra với lấy con dao găm."
  },
  AvgDialog_23854_Content_53 = {
    Text = "Gừ... gừ ư.."
  },
  AvgDialog_23854_Content_54 = {
    Text = "Trong số những người dấn thân vào biển nằm rạp xuống, có một người chống đỡ thân thể bằng vũ khí gãy, run rẩy cố gắng đứng dậy. Với đôi mắt mở to gần như lọt khỏi hốc mắt, người đó nhìn chằm chằm vào Muphí ở trên cao với ánh mắt đầy căm phẫn."
  },
  AvgDialog_23854_Content_55 = {
    Text = "Tại sao… tại sao…… từ bên cạnh người tế chủ…… tại sao?"
  },
  AvgDialog_23854_Content_56 = {
    Text = "Mẹ thần, mẹ thần… gừ, gừ…! Tôi đã tìm thấy mẹ thần!"
  },
  AvgDialog_23854_Content_57 = {
    Text = "Thưa ngài Chủ tế, thưa ngài Chủ tế! Nghi lễ sắp diễn ra, <Big:Nghi lễ sắp diễn ra!>"
  },
  AvgDialog_23854_Content_58 = {
    Text = "Hàm dưới của người dấn thân vào biển được mở rộng đến cực hạn, mô kết nối giữa hàm trên và hàm dưới bị kéo dãn đến mức trong suốt."
  },
  AvgDialog_23854_Content_59 = {
    Text = "Bị thúc đẩy bởi nỗi sợ hãi, hy vọng và đức tin, anh ta bùng nổ một sức sống khó có thể tưởng tượng nổi. \n Người Đạo Hải đột ngột đẩy bạn ra, thét chói tai và lao thẳng về phía ngoài phòng động lực."
  },
  AvgDialog_23854_Content_6 = {
    Text = "<BigShake:Muphí! Tôi có chuyện muốn nói với bạn!>"
  },
  AvgDialog_23854_Content_60 = {
    Text = "Không tốt, anh ta định bỏ chạy!"
  },
  AvgDialog_23854_Content_61 = {
    Text = "Chê————"
  },
  AvgDialog_23854_Content_62 = {
    Text = "Đầu nhọn sắc bén xuyên ra từ ngực xám xanh, chất lỏng bắn tung tóe. Chiến binh đại dương gục xuống với tiếng động lớn."
  },
  AvgDialog_23854_Content_63 = {
    Text = "Muphí không biết từ lúc nào đã đứng canh ở bên cạnh cửa phòng động lực, máu màu xám lục, đặc quánh lặng lẽ nhỏ giọt từ mũi dao trong tay."
  },
  AvgDialog_23854_Content_64 = {
    Text = "Đó là những mảnh vải treo trên đó, các họa tiết lõm bị thịt máu lấp đầy. Thân thể của Muphí run rẩy rõ rệt, nhưng tay cầm dao lại đặc biệt vững chắc và mạnh mẽ."
  },
  AvgDialog_23854_Content_65 = {
    Text = "… Xin lỗi, tôi không thể để bạn đi."
  },
  AvgDialog_23854_Content_66 = {
    Text = "Muphí hạ mắt, nhìn chằm chằm vào con dao găm một lúc, cuối cùng lau sạch máu của người dấn thân vào biển trên đó."
  },
  AvgDialog_23854_Content_67 = {
    Text = "Phản ứng của anh ta là muốn đi thông báo…"
  },
  AvgDialog_23854_Content_68 = {
    Text = "Muphí dựa vào cửa, liếc nhìn sự hỗn loạn trong phòng động lực, hàng mi khẽ rung động với vẻ bất an."
  },
  AvgDialog_23854_Content_69 = {
    Text = "Có thể <Blue:Miriam> không phải đã… tại sao vẫn chưa từ bỏ…"
  },
  AvgDialog_23854_Content_7 = {
    Text = "Đừng gọi lớn thế! Nếu thật sự dẫn người dấn thân vào biển đến thì làm sao bây giờ!"
  },
  AvgDialog_23854_Content_70 = {
    Text = "Tên mà Muphí lẩm bẩm khiến bạn cảm thấy một cơn chóng mặt khó hiểu, bạn nháy mắt, đợi cơn khó chịu tan biến rồi mới hỏi ra câu hỏi trong lòng."
  },
  AvgDialog_23854_Content_71 = {
    Text = "Miriam là?"
  },
  AvgDialog_23854_Content_72 = {
    Text = "Cô ấy là người dấn thân vào biển… cũng chính là thủ lĩnh của những người cá này."
  },
  AvgDialog_23854_Content_73 = {
    Text = "Được gọi là \"Mẹ Thần\"..."
  },
  AvgDialog_23854_Content_74 = {
    Text = "Vừa thốt lên câu hỏi, bạn đã nuốt một cách máy móc mấy lần."
  },
  AvgDialog_23854_Content_75 = {
    Text = "Thân thể của bạn dường như đã biết câu trả lời từ lâu, nhưng tiềm thức lại sợ hãi khi nhắc nhở bạn về nó."
  },
  AvgDialog_23854_Content_77 = {
    Text = "Muphí ngẩng đầu nhìn bạn, trong ánh mắt cô ấy hiện lên nỗi buồn sâu thẳm."
  },
  AvgDialog_23854_Content_78 = {Text = "Là tôi."},
  AvgDialog_23854_Content_79 = {
    Text = "Tôi là một con sâu tội nghiệp bị quái vật ký sinh, là phương tiện định mệnh cho sự tái sinh của các thần minh dị giáo."
  },
  AvgDialog_23854_Content_8 = {
    Text = "Nói đi, chuyện gì vậy?"
  },
  AvgDialog_23854_Content_80 = {
    Text = "Tôi... là \"Thần Mẫu\" của giáo đoàn Người dấn thân vào biển."
  },
  AvgDialog_23854_Content_81 = {
    Text = "Khi từ cuối cùng thốt ra khỏi miệng Muphí, ánh sáng trắng cùng cơn đau dữ dội nổ tung trước mắt."
  },
  AvgDialog_23854_Content_82 = {
    Text = "Này?!! này! %player%?!"
  },
  AvgDialog_23854_Content_83 = {
    Text = "Thân thể không thể kiểm soát được mà ngã ra sau, âm thanh tần số thấp vang vọng bên tai, tiếng kêu sợ hãi của thiếu nữ bị dòng đau đớn nuốt chửng."
  },
  AvgDialog_23854_Content_84 = {
    Text = "Ánh sáng trắng ở phía cuối, có một ánh nhìn như có như không dường như đang chăm chú vào bạn."
  },
  AvgDialog_23854_Content_85 = {
    Text = "Sự tồn tại bí ẩn dường như đang đánh giá bạn, xem xét hộp sọ vỡ của bạn có đáng để ghép lại hay không, và liệu linh hồn tan vỡ có thể được tái tạo hay không."
  },
  AvgDialog_23854_Content_86 = {
    Text = "Bạn mở to đôi mắt, ý thức tách khỏi thân thể.."
  },
  AvgDialog_23854_Content_9 = {
    Text = "Tôi… có chút không hiểu rõ chuyện gì đang xảy ra. \n Tại sao tôi lại ở trên tàu, tại sao tôi lại biết bạn, chẳng lẽ…"
  },
  AvgDialog_23855_Content_1 = {
    Text = "Muphí, đừng chạy nữa, chúng tôi không phải là người xấu!"
  },
  AvgDialog_23855_Content_2 = {
    Text = "Có kẻ xấu nào lại tự nhận mình là kẻ xấu đâu!"
  },
  AvgDialog_23855_Content_3 = {
    Text = "Thằng nhóc này còn có thể nhận ra tác dụng của bùa chú, các người còn dám nói mình không phải là đồng bọn của những người dấn thân vào biển!"
  },
  AvgDialog_23855_Content_4 = {
    Text = "Đó là câu thần chú được viết bằng cổ ngữ Lemuria, những ai thông thạo ngôn ngữ Lemuria đều không có lý do gì khiến họ không thể đọc được các dòng phù văn."
  },
  AvgDialog_23855_Content_5 = {
    Text = "Bạn còn nhớ không, Lemuria là nền văn minh đã mất từ trước khi lịch sử loài người ra đời. Ngay cả tại Đại học Misag, số lượng bài báo nghiên cứu về Lemuria cũng chỉ đếm trên đầu ngón tay."
  },
  AvgDialog_23855_Content_6 = {
    Text = "……Hừ."
  },
  AvgDialog_23855_Content_7 = {
    Text = "Mau đuổi theo cô ấy đi!"
  },
  AvgDialog_23856_Content_1 = {
    Text = "Thực tại bị bóp méo"
  },
  AvgDialog_23856_Content_10 = {
    Text = ", làm gì, tại sao đột nhiên nhìn tôi như vậy? Hai người các bạn đang có ánh mắt gì vậy?"
  },
  AvgDialog_23856_Content_100 = {
    Text = "Goliath… cậu…"
  },
  AvgDialog_23856_Content_101 = {
    Text = "Tại sao…… tại sao phải nói cho tôi những điều này?"
  },
  AvgDialog_23856_Content_102 = {
    Text = "Cảm thấy u uất không phải là điều tốt, hãy nhớ rằng, trạng thái của bạn quyết định sự phát triển của \"Thần\"."
  },
  AvgDialog_23856_Content_103 = {
    Text = "Sao tiếp theo sẽ chính vị sau hai mươi lăm năm nữa. Tôi ước tính, chị Miriam sẽ đến đây trong hai ngày tới để khiến bạn chìm vào giấc ngủ."
  },
  AvgDialog_23856_Content_104 = {
    Text = "Hãy làm điều gì đó bạn thích đi, gây rối loạn, dùng roi trừng phạt những người dấn thân vào biển, giải trí với nữ tỳ của bạn… bất cứ điều gì cũng được."
  },
  AvgDialog_23856_Content_105 = {
    Text = "Goliath đơn phương chấm dứt cuộc đối thoại, xoa nhẹ đầu cô ấy một cách lạnh lùng không chút tình cảm."
  },
  AvgDialog_23856_Content_106 = {
    Text = "Khi rời đi, anh ta liếc nhìn bức tượng gỗ mà Muphí ném vào góc tường. Kỹ nghệ của cô gái còn non nớt, hình dáng to lớn và kỳ lạ ngồi trên đế gỗ khiến người ta chỉ liếc qua cũng cảm thấy không thoải mái."
  },
  AvgDialog_23856_Content_107 = {Text = "Hừ."},
  AvgDialog_23856_Content_108 = {
    Text = "Sau khi Goliath rời đi, không gian trở nên im lặng. Các sinh vật bị giam cầm để hiến tế trong lồng cũng im lặng hoàn toàn."
  },
  AvgDialog_23856_Content_109 = {
    Text = "Muphí đã ngồi bên đống lửa rất lâu, cho đến khi ánh sáng dần yếu đi, đống lửa sắp tắt, cô mới như vừa tỉnh dậy và vỗ nhẹ vào má mình."
  },
  AvgDialog_23856_Content_11 = {
    Text = "Bạn có thể nhận ra Goliath từ tiếng bước chân, và trước đó, lời nói và hành động của bạn đã tiết lộ sự quen biết của bạn với Miriam."
  },
  AvgDialog_23856_Content_110 = {
    Text = "Cô ấy đá mạnh vào chiếc lồng bên cạnh, nhớ lại người phụ nữ đã phá hủy buổi lễ cách đây vài tháng… người phụ nữ đã thoát khỏi tay Miriam (Miriam) nhờ sức mạnh ý chí kiên cường."
  },
  AvgDialog_23856_Content_113 = {
    Text = "\"Xin lỗi...\"\n \"Tôi... không muốn chết...\""
  },
  AvgDialog_23856_Content_115 = {
    Text = "Tôi cũng không muốn... kết thúc như vậy.."
  },
  AvgDialog_23856_Content_12 = {
    Text = "Bạn rất am hiểu về tổ chức \"người dấn thân vào biển\", bạn là một thành viên của \"người dấn thân vào biển\", thậm chí còn giữ vị trí cao... hoặc có thể nói, họ đến vì bạn."
  },
  AvgDialog_23856_Content_13 = {
    Text = "Bạn là \"Thần Mẫu\" mà những người dấn thân vào biển nhắc đến, là chiếc nôi sinh ra các vị thần mới... đúng không?"
  },
  AvgDialog_23856_Content_14 = {
    Text = "<Big:Tôi không phải!>"
  },
  AvgDialog_23856_Content_15 = {
    Text = "Vậy làm thế nào để giải thích sự quen thuộc của bạn với Goliath, Miriam và việc bạn tránh né những người dấn thân vào biển?"
  },
  AvgDialog_23856_Content_16 = {
    Text = "Tôi chỉ là… người hầu… một người hầu bình thường, tại trụ sở của giáo đoàn, có vô số cô gái như tôi."
  },
  AvgDialog_23856_Content_17 = {
    Text = "Trong nhóm người dấn thân vào biển, ngoại hình giống con người hẳn là rất hiếm. Nếu không, dựa vào khả năng chiến đấu của họ, họ cũng sẽ không cần hợp tác với Hội Giáo đèn lồng."
  },
  AvgDialog_23856_Content_18 = {
    Text = "Nếu bạn chỉ là một người hầu gái bình thường, tại sao họ lại huy động nhiều người để truy bắt bạn?"
  },
  AvgDialog_23856_Content_19 = {
    Text = "Đều là, đây chỉ là ……"
  },
  AvgDialog_23856_Content_2 = {
    Text = "Muphí, Muphí?"
  },
  AvgDialog_23856_Content_20 = {
    Text = "Muphí, tôi cần biết đã xảy ra chuyện gì."
  },
  AvgDialog_23856_Content_21 = {
    Text = "Chỉ có như vậy, chúng ta mới có cơ hội sống sót và giúp đỡ bạn."
  },
  AvgDialog_23856_Content_23 = {
    Text = "Được rồi……"
  },
  AvgDialog_23856_Content_25 = {
    Text = "Chú chim non bị gãy cánh, rơi vào ao nước đen."
  },
  AvgDialog_23856_Content_26 = {
    Text = "Lời cầu nguyện lảm nhảm của chủ tế bay bổng nhưng vững chắc, những lời điên cuồng xuyên qua chất dịch đen đặc, hóa thành lưỡi kiếm sắc bén xé toạc lồng ngực của chú chim non."
  },
  AvgDialog_23856_Content_27 = {
    Text = "Dịch chất lỏng màu đỏ tươi nổi lên từ ngực, nở rộ quyến rũ trên mặt nước đen đã yên tĩnh ——"
  },
  AvgDialog_23856_Content_28 = {
    Text = "Cô ấy không ngừng chìm xuống, những rễ cây đẫm máu kéo cô vào nơi sâu thẳm nhất, vào một vòng tay vừa mềm mại vừa lạnh giá."
  },
  AvgDialog_23856_Content_3 = {
    Text = "Đừng trốn nữa, Goliath đã đi đủ xa rồi."
  },
  AvgDialog_23856_Content_30 = {
    Text = "……………"
  },
  AvgDialog_23856_Content_31 = {
    Text = "Cô ấy đã thấy. \n Cô ấy nhìn lên, \"Mẹ\" buông xuống ba đôi mắt, đối diện với cô."
  },
  AvgDialog_23856_Content_32 = {
    Text = "Đó là một sinh vật khổng lồ màu đỏ thẫm, nơi bị máu nhuốm lên trở nên trắng trong suốt. \n \"Mẹ\" phát ra ánh sáng mờ nhạt, tạm thời soi sáng một khoảng trời nhỏ."
  },
  AvgDialog_23856_Content_33 = {
    Text = "Với ánh sáng, cô nhìn thấy \"mẹ\" có vô số vết thương đen lớn nhỏ trên bề mặt mịn màng."
  },
  AvgDialog_23856_Content_34 = {
    Text = "\"Xin lỗi...\""
  },
  AvgDialog_23856_Content_35 = {
    Text = "Dịch chất đen sôi lên, đánh tan sự tĩnh lặng dưới đáy bờ."
  },
  AvgDialog_23856_Content_36 = {
    Text = "\"mẹ\" phát ra một tiếng kêu thê thảm, các xúc tu động đậy, đưa thứ gì đó vào trong lồng ngực của con non."
  },
  AvgDialog_23856_Content_37 = {
    Text = "Những xúc tu mềm mại, trơn trượt và lạnh lẽo quấn quanh cô, nước hồ đen không còn làm tắc nghẽn miệng và mũi cô nữa, mà ngược lại, giống như nước ối, đã nuôi dưỡng sự sống của cô."
  },
  AvgDialog_23856_Content_38 = {
    Text = "\"Xin lỗi...\"\n \"Tôi còn... không muốn chết...\""
  },
  AvgDialog_23856_Content_39 = {
    Text = "Bề mặt nước giữ được sự yên lặng lâu dài, thậm chí cả gió hú ở vùng cực cũng không thể làm cho nước ao đặc quánh nổi lên gợn sóng."
  },
  AvgDialog_23856_Content_4 = {
    Text = "Thật sự, thật thật sao?"
  },
  AvgDialog_23856_Content_40 = {
    Text = "Thánh nữ có phải đã…"
  },
  AvgDialog_23856_Content_41 = {
    Text = "Cô ấy sinh vào <Blue:thời khắc chính vị sao sáng> trước, là đứa trẻ \"có khả năng nhìn thấy\"."
  },
  AvgDialog_23856_Content_42 = {
    Text = "Trên thế giới, không ai xứng đáng nhận được sự công nhận từ dòng máu thần thánh hơn cô ấy."
  },
  AvgDialog_23856_Content_43 = {
    Text = "Người phụ nữ gầy guộc được bao quanh, đứng trên đỉnh cao nhất có thể nhìn xuống mọi người. \n Lớp voan mỏng làm mờ khuôn mặt của cô, ngay cả những người hầu cận cũng không thể đoán được suy nghĩ trong lòng chủ nhân."
  },
  AvgDialog_23856_Content_44 = {Text = "Muphí…"},
  AvgDialog_23856_Content_45 = {
    Text = "Kèm theo những tiếng thì thầm mơ hồ, dường như năng lượng sâu trong lòng đất sắp bùng nổ, mặt nước đột nhiên sôi sục dữ dội."
  },
  AvgDialog_23856_Content_46 = {
    Text = "Nước đen đặc và dày tràn ra khỏi bờ ao, ngập qua mắt cá chân của mọi người rồi chảy tới bên chân trần của người phụ nữ."
  },
  AvgDialog_23856_Content_47 = {
    Text = "Đi qua đám giáo đồ trẻ thì thầm kinh ngạc, cô im lặng bước lên con đường lát chất lỏng đen, nhúng sâu hai tay vào hồ nước ——"
  },
  AvgDialog_23856_Content_48 = {
    Text = "—— xào"
  },
  AvgDialog_23856_Content_49 = {
    Text = "Cô gái bám vào đôi tay của mình, nhảy ra khỏi nước trong hồ. \n Chất lỏng đen chảy dọc theo đường nét khuôn mặt, giống như hai vệt nước mắt rùng rợn."
  },
  AvgDialog_23856_Content_5 = {
    Text = "Không sao rồi, những người dấn thân vào biển trên boong cũng đã đi theo anh ấy. \nđến đây, đưa tay cho tôi, tôi sẽ giúp bạn ra ngoài."
  },
  AvgDialog_23856_Content_50 = {
    Text = "Ồ, khá ổn. Xem ra, <Blue:thần minh> đã công nhận người <Blue:mẹ> mới."
  },
  AvgDialog_23856_Content_51 = {
    Text = "Goliath lên tiếng bất ngờ, giọng điệu mỉa mai, nhưng chẳng còn ai bận tâm đến lời mỉa mai của hắn."
  },
  AvgDialog_23856_Content_52 = {
    Text = "Thánh nữ, thành công rồi? Chúng ta đã thành công!"
  },
  AvgDialog_23856_Content_53 = {
    Text = "Lời cầu nguyện vang lên liên tục, cuối cùng hòa quyện trong hang động lạnh lẽo, cuồng nhiệt, méo mó, ầm ĩ đến mức rung chuyển cả hang động."
  },
  AvgDialog_23856_Content_54 = {
    Text = "Miriam, như bạn mong muốn, tôi đã hoàn thành việc bạn yêu cầu."
  },
  AvgDialog_23856_Content_55 = {
    Text = "\"Ngài\"...đã đập ở đây."
  },
  AvgDialog_23856_Content_56 = {
    Text = "Không chỉ Murphy, Miriam cũng có thể nghe thấy. \nHai trái tim với nhịp điệu khác nhau đang đập trong lồng ngực của cô gái."
  },
  AvgDialog_23856_Content_57 = {
    Text = "Bây giờ, bạn có thể trả lời câu hỏi của tôi chưa?"
  },
  AvgDialog_23856_Content_58 = {
    Text = "Biết không giấu diếm."
  },
  AvgDialog_23856_Content_59 = {
    Text = "Bạn nuôi dưỡng tôi từ ban đầu chẳng lẽ chỉ vì hôm nay sao?"
  },
  AvgDialog_23856_Content_6 = {
    Text = "Muphí vừa đứng vững, những xúc tu của tulô đã siết chặt lấy mắt cá chân của cô ta dưới sự đồng ý thầm lặng của bạn."
  },
  AvgDialog_23856_Content_61 = {Text = "Không."},
  AvgDialog_23856_Content_62 = {
    Text = "Bạn là \"Thánh nữ\" của tôi, lẽ ra phải là cầu nối liên thông thần quốc... Sau đó, linh hồn bạn sẽ được đón vào thần quốc."
  },
  AvgDialog_23856_Content_63 = {
    Text = "Lễ nghi hôm nay, nằm ngoài kế hoạch…… nhưng, đừng lo lắng quá. \nSau lễ thần sinh, ta sẽ bảo quản linh hồn của ngươi thật tốt, ngươi sẽ không lang thang trong đêm dài."
  },
  AvgDialog_23856_Content_64 = {
    Text = "Nói gì về linh hồn, hồn ma.."
  },
  AvgDialog_23856_Content_65 = {
    Text = "Thời điểm chết của tôi, từ đầu đã được định vào lúc gọi là \"thời điểm chính vị của sao trời\", phải không?"
  },
  AvgDialog_23856_Content_66 = {
    Text = "Miriam đóng nhẹ đôi mắt, cô không trả lời câu hỏi nữa, quay người quay mặt về phía đám tín đồ cuồng nhiệt. \nCô giơ cao hai tay, chất lỏng đen chảy dọc theo làn da, khăn che đầu lập tức bị nhuộm thành màu đen đậm."
  },
  AvgDialog_23856_Content_67 = {
    Text = "Mẹ thần đã đến!"
  },
  AvgDialog_23856_Content_68 = {
    Text = "Ngài sẽ phục hồi từ @1, khiến @2 đến!"
  },
  AvgDialog_23856_Content_69 = {
    Text = "Ngài sẽ phục hồi từ @1, khiến @2 đến!"
  },
  AvgDialog_23856_Content_7 = {
    Text = "Làm, làm gì?! Tôi biết rằng việc tôi bỏ các người lại để đối mặt với Goliath là sai…"
  },
  AvgDialog_23856_Content_70 = {
    Text = "Ba tháng sau"
  },
  AvgDialog_23856_Content_71 = {
    Text = "Bạn đang khiến người phụ nữ đó càng ngày càng đau đầu. Vài tháng trước không phải còn rất ngoan sao? \nSao vậy, bây giờ không muốn nghe lời mẹ nữa à?"
  },
  AvgDialog_23856_Content_72 = {
    Text = "Cô gái liếc mắt nhìn Goliath, cắm con dao khắc vào gỗ một cách giận dữ, rồi ném cả dụng cụ và vật liệu sang một bên."
  },
  AvgDialog_23856_Content_73 = {
    Text = "Mẹ, mẹ?"
  },
  AvgDialog_23856_Content_74 = {
    Text = "Bạn… từ đâu học được cách nói như vậy?"
  },
  AvgDialog_23856_Content_75 = {
    Text = "Từ điển! Bạn xem, \"người trưởng thành nữ có tình cảm kết nối và chăm sóc trẻ nhỏ\"."
  },
  AvgDialog_23856_Content_76 = {
    Text = "Không… Tôi không phải là mẹ của bạn."
  },
  AvgDialog_23856_Content_77 = {
    Text = "Ngài là Thánh nữ của giáo đoàn, là người được mệnh định tôn quý… Nếu ngài muốn, có thể gọi thẳng tên tôi."
  },
  AvgDialog_23856_Content_78 = {
    Text = "Ừ… Miri… Am?"
  },
  AvgDialog_23856_Content_79 = {
    Text = "Vâng, thánh nữ."
  },
  AvgDialog_23856_Content_8 = {
    Text = "Nhưng, nhưng nếu anh ta đến tìm tôi, bị anh ta bắt được thì tôi chỉ còn đường chết! Tôi, tôi…"
  },
  AvgDialog_23856_Content_80 = {
    Text = "……cô ấy không phải là mẹ tôi, chưa bao giờ."
  },
  AvgDialog_23856_Content_81 = {
    Text = "Chỉ có những kẻ ở trên Hội Giáo đèn lồng biết về nguồn gốc của tôi, tôi cũng không có mẹ, tôi chỉ là món quà họ dành cho Miriam."
  },
  AvgDialog_23856_Content_82 = {
    Text = "Ồ? Cô ấy thật sự kể cả chuyện này cho anh nghe à?"
  },
  AvgDialog_23856_Content_83 = {
    Text = "Đối với một tù nhân đã định ngày chết, biết bao nhiêu bí mật cũng không sao, dù sao thì mọi thứ rồi cũng sẽ theo tôi vào lòng đất."
  },
  AvgDialog_23856_Content_84 = {
    Text = "Đây cũng là sự đền bù của người phụ nữ đó cho cậu. Hãy biết rằng, vào ngày thần minh được cấy ghép vào cơ thể cậu, vị chủ tế của chúng ta đã buồn bã đến mức thức trắng đêm."
  },
  AvgDialog_23856_Content_85 = {
    Text = "Buồn bã? Đùa gì thế, cô ấy không có cảm xúc đó."
  },
  AvgDialog_23856_Content_86 = {
    Text = "Thật tuyệt tình, tiểu công chúa. \nNếu con gái quá lạnh lùng, sẽ làm mẹ buồn đó."
  },
  AvgDialog_23856_Content_87 = {
    Text = "Bạn có phiền không! Đã nói rồi, cô ấy không phải là mẹ tôi!"
  },
  AvgDialog_23856_Content_88 = {
    Text = "Điều này chưa chắc, bạn có muốn nghe câu chuyện không."
  },
  AvgDialog_23856_Content_89 = {
    Text = "<BigShake:Không muốn nghe, tôi cũng không muốn gặp bạn!>\nNếu là cố ý đến để châm chọc tôi, bạn có thể rời đi!"
  },
  AvgDialog_23856_Content_9 = {Text = "Muphí."},
  AvgDialog_23856_Content_90 = {
    Text = "Không, bạn muốn nghe..."
  },
  AvgDialog_23856_Content_91 = {
    Text = "Giọng điệu của Goliath bỗng chốc trở nên trầm lắng, mang theo uy nghi của người từng trải qua nhiều chiến trường, hai trái tim trong cơ thể Muphí suýt nữa ngừng đập vì điều đó."
  },
  AvgDialog_23856_Content_92 = {
    Text = "Cô ấy đột nhiên nhận ra—— người khổng lồ chưa bao giờ là món đồ chơi mà cô có thể tùy tiện nghịch ngợm. \nChỉ là mình đã dựa vào danh phận để lấn tới, còn đối phương thì cũng vui vẻ đứng nhìn xem trò cười thôi."
  },
  AvgDialog_23856_Content_93 = {
    Text = "Vâng… vâng, hãy nói đi."
  },
  AvgDialog_23856_Content_94 = {
    Text = "Có một giáo hội bí ẩn, để duy trì sự tinh khiết tuyệt đối của dòng máu, mọi cuộc hôn nhân đều do giáo chủ chỉ định. Những kẻ kết hôn và sinh con với người ngoài cuối cùng đều phải trả giá."
  },
  AvgDialog_23856_Content_95 = {
    Text = "Trong lần thanh trừng trước, người thực hiện đã mang về một đứa bé —— một bé gái có thể nhìn thấy sự tồn tại tinh thần."
  },
  AvgDialog_23856_Content_96 = {
    Text = "Bé gái……"
  },
  AvgDialog_23856_Content_97 = {
    Text = "Cô ấy đã ở trong ngăn bí mật dưới thân thể người mẹ quá lâu, khi bị tín đồ tìm thấy, cô ấy suýt nữa hít phải máu của chính mẹ ruột mình đến chết."
  },
  AvgDialog_23856_Content_98 = {
    Text = "Người phụ nữ bình thường, không có thành tựu gì nổi bật, thành tựu lớn nhất của đời này chính là sinh hạ một cô con gái ưu tú và cố gắng không để giáo hội mang cô bé đi."
  },
  AvgDialog_23856_Content_99 = {
    Text = "——Quả là tình mẫu tử tuyệt vời, tôi sắp khóc vì xúc động rồi."
  },
  AvgDialog_23857_Content_1 = {
    Text = "Hạt giống định mệnh"
  },
  AvgDialog_23857_Content_10 = {
    Text = "Còn bao lâu nữa?"
  },
  AvgDialog_23857_Content_11 = {
    Text = "Còn bao lâu nữa là gì?"
  },
  AvgDialog_23857_Content_12 = {
    Text = "Thần minh. Khoảng bao lâu nữa Người ra đời?"
  },
  AvgDialog_23857_Content_13 = {
    Text = "……Tôi không biết. Không bằng chính bạn xác nhận đi, dù sao từ thái độ của bạn đối với Miriam và Goliath, bạn cũng đã sớm dính líu vào chuyện này rồi."
  },
  AvgDialog_23857_Content_14 = {
    Text = "Muphí không chút do dự, nhanh chóng cởi bỏ quần áo. \nKhi chiếc cúc cuối cùng ở vạt trước được mở ra, các người nhìn thấy \"vị thần\"ẩn sâu trong cơ thể cô gái."
  },
  AvgDialog_23857_Content_15 = {
    Text = "Thân thể dưới ngực cô ấy rõ ràng là trong suốt, cấu trúc trong suốt kéo giãn da và cơ bắp xung quanh, khiến toàn bộ vùng ngực và bụng đều mang màu trắng xám héo úa."
  },
  AvgDialog_23857_Content_16 = {
    Text = "Hiện tượng trong suốt khiến các cơ quan trong lồng ngực lộ rõ, bạn nhìn thấy một trái tim trẻ mỏng màu đỏ nhạt, và một quả cầu màu sữa."
  },
  AvgDialog_23857_Content_17 = {
    Text = "Số lượng sợi tơ không đếm được từ \"trứng\" chui ra, bị cuốn vào mạch máu của Muphí một cách chặt chẽ, tạo nên sự tương hỗ."
  },
  AvgDialog_23857_Content_18 = {
    Text = "Nếu không phải sự tồn tại của nó đã chèn ép vào tim Muphí, trông nó như thể hòa làm một với lồng ngực trong suốt, không giống một vật thể lạ."
  },
  AvgDialog_23857_Content_19 = {
    Text = "Nó hỗn loạn mà yên tĩnh, hình tam giác ngược màu đen khắc trên đó cũng đông cứng lại, giống như một tác phẩm nghệ thuật lạ kỳ."
  },
  AvgDialog_23857_Content_2 = {
    Text = "Hội giáo đồ người dấn thân vào biển, nghi lễ bị đội mạo hiểm phá hủy, cựu mẫu thể bị rỗng rỗng... và \"thần minh\" trong cơ thể bạn..."
  },
  AvgDialog_23857_Content_20 = {
    Text = "Rỗng rỗng… cái này đã bị hòa tan rồi."
  },
  AvgDialog_23857_Content_21 = {
    Text = "Đã xem đủ chưa?"
  },
  AvgDialog_23857_Content_22 = {
    Text = "Xin lỗi… bạn có thể nhanh chóng sắp xếp lại quần áo được không?"
  },
  AvgDialog_23857_Content_23 = {
    Text = "Muphí cúi đầu, vừa chỉnh lại quần áo vừa nhìn bạn."
  },
  AvgDialog_23857_Content_24 = {
    Text = "Bạn vừa nhắc đến \"rỗng rỗng\", có phải đang nói về vết thương đen trên Người ấy không?"
  },
  AvgDialog_23857_Content_25 = {
    Text = "Cái bình cũ… chính là kẻ đã nuôi dưỡng thứ này, trên người đầy những vết tích như vậy."
  },
  AvgDialog_23857_Content_26 = {
    Text = "Nếu không phải là \"rỗng rỗng\" khiến người tiền nhiệm ngày càng yếu đuối, tôi cũng sẽ không bị…"
  },
  AvgDialog_23857_Content_27 = {
    Text = "Giọng Muphí dần dần nhỏ đi. \nCô ấy cố nuốt những lời chưa kịp nói, đưa tay lên ngực mình, vẻ mặt u ám."
  },
  AvgDialog_23857_Content_28 = {
    Text = "Tulô, bạn cũng đã thấy hình dạng của thần minh đó. \nCòn bao lâu nữa cho đến khi Ngài trưởng thành?"
  },
  AvgDialog_23857_Content_29 = {
    Text = "Khỏe mạnh, thậm chí chỉ còn thiếu bước cuối cùng……\nchỉ còn thiếu dùng chòm sao để dẫn dắt Người xé rách thân thể của vật chứa."
  },
  AvgDialog_23857_Content_3 = {
    Text = "Ai Jī Sī, Miss Mason, Lily, Lisa… Cho đến nay, bạn đã gặp không ít người bị cải tạo thân thể."
  },
  AvgDialog_23857_Content_30 = {
    Text = "Tôi rất ngạc nhiên, đến giờ này mà ngươi vẫn có thể hành động tự nhiên."
  },
  AvgDialog_23857_Content_31 = {
    Text = "Thật sao… đã đến lúc này rồi…"
  },
  AvgDialog_23857_Content_32 = {
    Text = "Tôi vẫn chưa mất ý thức là nhờ <Blue:Hilaster> đã giúp tôi."
  },
  AvgDialog_23857_Content_33 = {
    Text = "Hilaster là?"
  },
  AvgDialog_23857_Content_34 = {
    Text = "Muphí nhìn lên bầu trời quay vòng với ánh sáng kỳ lạ. \n Những con chim bay lượn dưới màn ánh sáng, ánh sáng mềm mại lan tỏa, ngăn chặn cơn bão hoặc mưa lớn có thể xảy ra từ bên ngoài."
  },
  AvgDialog_23857_Content_35 = {
    Text = "Trong ghi chú của giáo đoàn Người dấn thân vào biển, <Blue:sao chính vị> được nhấn mạnh đi nhấn mạnh lại về tầm quan trọng của nó. Nghi lễ giáng lâm cũng phải được thực hiện vào thời điểm cụ thể, và đó chính là lý do người phụ nữ đã khiến tôi chìm vào giấc ngủ."
  },
  AvgDialog_23857_Content_36 = {
    Text = "Đội trưởng suy đoán, sự phát triển của Ngài có thể liên quan đến quy luật vận hành của thiên thể. \nVì vậy, Hilaster đã lấy con tàu làm trung tâm và tạo ra thâm cảnh này, tách biệt hoàn toàn với thế giới bên ngoài."
  },
  AvgDialog_23857_Content_37 = {
    Text = "Chúng ta đã đoán đúng, từ khi rời khỏi bầu trời thực sự, Ngài đã im lặng. Chỉ cần trên tàu vượt qua lần này \"thời điểm chính vị của các vì sao\", có lẽ Ngài sẽ mãi mãi chìm vào giấc ngủ sâu."
  },
  AvgDialog_23857_Content_38 = {
    Text = "Chính Hilaster đã tạo ra thâm cảnh này, và cũng là người điều khiển con tàu Sonanil đáng lẽ đã chìm nhưng vẫn tiếp tục hành trình."
  },
  AvgDialog_23857_Content_39 = {
    Text = "Nghe có vẻ như cô ấy cũng là một thân thể được đánh thức. \nChờ đã… cô ấy chính là người mà bạn nói \"có thể giúp tìm thấy Ramona\" à?"
  },
  AvgDialog_23857_Content_4 = {
    Text = "Nhưng cấy ghép <Blue:\"thần minh\"> vào thân thể của một người sống? Thực sự là…"
  },
  AvgDialog_23857_Content_40 = {
    Text = "Không sai, trên con tàu này không có gì lọt khỏi tầm mắt của cô ấy."
  },
  AvgDialog_23857_Content_41 = {
    Text = "Cô ấy chắc chắn đã đưa thuyền trưởng tránh khỏi những người dấn thân vào biển, chỉ cần chúng ta tìm thấy cô ấy, tìm đồng đội của bạn sẽ dễ dàng."
  },
  AvgDialog_23857_Content_42 = {
    Text = "Tóm lại, dù chúng ta chọn giúp bạn trước hay đi cứu Ramona trước, Hilaster này vẫn đóng vai trò then chốt."
  },
  AvgDialog_23857_Content_43 = {
    Text = "Tulô không nói gì nữa, chỉ nghiêng đầu nhìn bạn, đợi bạn đưa ra quyết định."
  },
  AvgDialog_23857_Content_44 = {
    Text = "Không sai. Dù là đưa con tàu này trở về đất liền, ngăn chặn nghi lễ giáng thần, hay cứu Ramona, cách duy nhất hiện tại đều là tìm thấy \"Hilaster\"."
  },
  AvgDialog_23857_Content_45 = {
    Text = "Muphí, dẫn đường đi. \n Chúng ta hãy đi tìm thuyền trưởng, đi tìm Hilaster."
  },
  AvgDialog_23857_Content_5 = {
    Text = "Bạn có biểu cảm gì vậy? Nếu không tin thì thôi, tôi cũng không mong bạn hiểu ngay lời của tôi."
  },
  AvgDialog_23857_Content_6 = {
    Text = "Xin lỗi… Chỉ là, tất cả những điều này đều vô cùng khó hiểu và đáng ngờ."
  },
  AvgDialog_23857_Content_7 = {
    Text = "Muphí, có thể cho tôi xem cái đó... \"thần minh\" không?"
  },
  AvgDialog_23857_Content_8 = {
    Text = "Bạn còn nói bạn không tin!"
  },
  AvgDialog_23857_Content_9 = {
    Text = "Tôi, tôi chỉ là.."
  },
  AvgDialog_23858_Content_1 = {
    Text = "Vây hãm tứ phía"
  },
  AvgDialog_23858_Content_10 = {
    Text = "Chúng ta đang ở <Blue:Brillport>, tại <Blue:đình tàu thứ ba>, và đã xảy ra trận chiến với kẻ thù vô danh."
  },
  AvgDialog_23858_Content_11 = {
    Text = "Đang thông báo cho điều tra viên ngoại trường gần nhất……\nĐiều tra viên Đrapơ dự kiến sẽ đến Bến cảng thứ ba trong vòng nửa giờ."
  },
  AvgDialog_23858_Content_12 = {
    Text = "Nửa giờ quá lâu. Có quá nhiều địch ở phía nam con đường, chúng ta sẽ thử đột phá từ phía bắc."
  },
  AvgDialog_23858_Content_13 = {
    Text = "Đã thông báo cho tài xế đến khu vực phía bắc của bến cảng số 3 để đón."
  },
  AvgDialog_23858_Content_14 = {
    Text = "Kẻ thù không rõ? Chẳng lẽ không phải là <Yellow:Hội Giáo đèn lồng> sao?"
  },
  AvgDialog_23858_Content_15 = {
    Text = "Có muốn ghi nhận thông tin về kẻ địch mới?"
  },
  AvgDialog_23858_Content_16 = {
    Text = "Xin hãy, Erika, không phải bây giờ."
  },
  AvgDialog_23858_Content_17 = {
    Text = "Là loài sinh vật giống người chưa từng có bản ghi chứng kiến. Sau khi trở về, tôi sẽ trình bày báo cáo."
  },
  AvgDialog_23858_Content_18 = {
    Text = "%player%,bảo vệ bản thân, chuẩn bị phá vây."
  },
  AvgDialog_23858_Content_2 = {
    Text = "Ba giờ trước\ncảng thị trấn·Brielleport\nbến thứ ba"
  },
  AvgDialog_23858_Content_3 = {
    Text = "%player%,đề phòng kẻ địch phía sau!"
  },
  AvgDialog_23858_Content_5 = {
    Text = "Phát hiện sóng âm tần số cao không cảnh báo, kết nối thông tin tự động. \nLại một lần nữa, tối nay tốt lành, Người Bảo Mật, Ramona."
  },
  AvgDialog_23858_Content_6 = {
    Text = "Có vẻ như ai đó đã sợ đến mất mật rồi."
  },
  AvgDialog_23858_Content_7 = {
    Text = "Vui lòng không gây nhiễu ngôn ngữ không cần thiết cho nhân viên thực địa."
  },
  AvgDialog_23858_Content_8 = {
    Text = "Được, được. \nVậy, bạn cần sự giúp đỡ không?"
  },
  AvgDialog_23858_Content_9 = {
    Text = "Chúng ta cần sự hỗ trợ ngay!"
  },
  AvgDialog_23859_Content_1 = {
    Text = "Không lối thoát"
  },
  AvgDialog_23859_Content_10 = {
    Text = "Quả nhiên, chúng không theo kịp cầu thang dẫn lên boong…"
  },
  AvgDialog_23859_Content_11 = {
    Text = "Ramona hạ thấp giọng, thì thầm một cách kín đáo."
  },
  AvgDialog_23859_Content_12 = {
    Text = "Những người cá này bị tàu Sonanil chặn bên ngoài, nhưng không biết vì lý do gì, chúng ta không bị tàu này từ chối."
  },
  AvgDialog_23859_Content_13 = {
    Text = "Chúng ta bị dùng làm công cụ để mở đường, một khi họ cũng lên tàu, chúng ta sẽ trở nên không còn cần thiết."
  },
  AvgDialog_23859_Content_14 = {
    Text = "Đúng vậy. Vì vậy... tôi có một ý tưởng."
  },
  AvgDialog_23859_Content_15 = {
    Text = "Bạn bước lên bậc thang cuối cùng của cầu dẫn."
  },
  AvgDialog_23859_Content_16 = {
    Text = "Như cánh chim được bầu trời ôm ấp, đôi mắt nhẹ nhàng lướt qua làn gió dịu êm, thế giới trước mắt như đảo lộn hoàn toàn."
  },
  AvgDialog_23859_Content_17 = {
    Text = "Mặt trăng lớn biến mất trên bầu trời, ánh hào quang giống như cực quang khuấy động không gian bao quanh con tàu, những đốm sáng chiếu lên boong tàu cũng mang sắc màu lạ kỳ."
  },
  AvgDialog_23859_Content_18 = {
    Text = "Ramona, có gì không ổn!"
  },
  AvgDialog_23859_Content_19 = {
    Text = "Cầu thang rung chuyển một trận, sau khi các người thành công lên boong tàu, loài người cá cũng không còn đứng quan sát nữa mà bắt đầu leo lên bằng cả tay lẫn chân."
  },
  AvgDialog_23859_Content_2 = {
    Text = "Ba giờ trước\ncảng thị trấn·Brielleport\nbến thứ ba"
  },
  AvgDialog_23859_Content_20 = {
    Text = "Không kịp rồi, họ sắp đuổi kịp chúng ta."
  },
  AvgDialog_23859_Content_21 = {
    Text = "Ramona đã dùng hết sức lực để chém vỡ khóa cố định, cầu thang rơi xuống nhưng không phát ra một tiếng động nào khi rơi xuống."
  },
  AvgDialog_23859_Content_22 = {
    Text = "Trái tim đập mạnh, những hiện tượng kỳ lạ trên tàu như cuốn trôi tâm trí, phải một lúc sau mọi người mới dần lấy lại được khả năng nói chuyện."
  },
  AvgDialog_23859_Content_23 = {
    Text = "Ít nhất chúng không thể leo lên tàu qua cầu thang tàu này."
  },
  AvgDialog_23859_Content_24 = {
    Text = "Cảnh tượng trên con tàu này... đúng là phù hợp với những ấn tượng cố hữu của tôi về \"con tàu ma\"."
  },
  AvgDialog_23859_Content_25 = {
    Text = "Thang máy rơi xuống mà không phát ra tiếng động——điều này có nghĩa là chúng ta có thể đang ở trong một không gian riêng biệt. Rất thú vị, đúng không?"
