  AvgDialog_23859_Content_27 = {
    Text = "Bảo vệ sương mù của trường học được điều khiển bởi <Yellow:Công nghệ Bạc Tâm>, không biết con tàu này sẽ nằm dưới sự kiểm soát của lực lượng nào?"
