  AvgDialog_23859_Content_29 = {
    Text = "Không có ghi chép tương tự trong hồ sơ, nhưng từ góc độ lý thuyết, việc thân thể được đánh thức tạo ra không gian độc lập là khả thi——bạn có muốn nghe lý thuyết cụ thể không?"
  },
  AvgDialog_23859_Content_3 = {
    Text = "Mùi thép rỉ sét xông thẳng vào mũi, mỗi bước đi, cầu thang đều phát ra tiếng rên rỉ yếu ớt."
  },
  AvgDialog_23859_Content_30 = {
    Text = "Thả tôi ra đi……"
  },
  AvgDialog_23859_Content_31 = {
