  AvgDialog_23859_Content_40 = {
    Text = "<Small:Sao lại có nhiều thứ như vậy có thể ngăn chặn liên lạc, lần trước ở bảo tàng sáp cũng vậy……>"
  },
  AvgDialog_23859_Content_41 = {
    Text = "Công nghệ được thúc đẩy bởi bạc tâm không phải là vạn năng. \nHơn nữa, đối với chính bạc tâm, nghiên cứu của chúng ta vẫn chỉ mới ở giai đoạn đầu."
  },
  AvgDialog_23859_Content_42 = {
    Text = "Hy vọng những người cá đừng bò lên từ nơi khác…"
  },
  AvgDialog_23859_Content_43 = {
    Text = "Ừ, cẩn thận khu vực xung quanh và cầu nguyện con tàu này đừng ra khơi."
  },
  AvgDialog_23859_Content_44 = {
    Text = "<Big:ư———>"
  },
  AvgDialog_23859_Content_45 = {
    Text = "Như tiếng sáo của chim sơn ca hòa cùng giai điệu opera, tiếng còi tàu dài vang lên, đáp lại lời cầu nguyện của Ramona."
  },
  AvgDialog_23859_Content_48 = {
    Text = "Tôi biết bạn muốn nói gì, nhưng làm ơn mà, không phải bây giờ."
  },
  AvgDialog_23859_Content_49 = {
    Text = "Chúng ta không thể đi theo tàu Sonanil ra biển, con tàu này có quá nhiều điểm đáng ngờ."
  },
  AvgDialog_23859_Content_5 = {
    Text = "Bạn và Ramona cùng nhau bước lên cầu dẫn tàu run rẩy, con đường lên dường như bị bao phủ bởi sương mù, khiến người ta không thể nhìn thấy điểm cuối."
  },
  AvgDialog_23859_Content_50 = {
    Text = "Đi xem ở đầu kia của boong tàu! Tôi thấy có dây thừng buộc thuyền cứu sinh ở đó, chúng ta thử rút lui qua mặt biển."
