  AvgDialog_23859_Content_51 = {
    Text = "Đợi đã… có vẻ như có tiếng gì đó."
  },
  AvgDialog_23859_Content_53 = {
    Text = "Khuôn mặt mang dáng dấp của loài cá xuất hiện trên boong tàu, những kẻ đã đuổi các người lên tàu đang dần ép sát."
  },
  AvgDialog_23859_Content_6 = {
    Text = "Bạn có phát hiện gì?"
  },
  AvgDialog_23859_Content_7 = {
    Text = "Tàu Sonanier thiếu các đặc điểm của một con tàu ma đã chìm, không phù hợp với bản ghi về việc nó đã chìm trong cơn bão."
  },
  AvgDialog_23859_Content_8 = {
    Text = "Tôi sẽ muốn điều tra rõ ràng về nguồn gốc của con tàu này, nhưng hiện tại rõ ràng không phải là thời điểm thích hợp."
  },
  AvgDialog_23859_Content_9 = {
    Text = "Cô quay đầu lại và thấy kẻ thù đã dồn các người lên cầu thang, chúng đứng vây quanh dưới chân cầu thang. Đôi mắt vô hồn như mắt cá của chúng nhìn thẳng vào cô."
  },
  AvgDialog_23860_Content_1 = {
    Text = "Kẻ sa đà"
