  AvgDialog_23860_Content_10 = {
    Text = "Cuối cùng, là một khuôn mặt quen thuộc và xa lạ."
  },
  AvgDialog_23860_Content_11 = {
    Text = "Khụ, khụ khụ khụ…!"
  },
  AvgDialog_23860_Content_12 = {
    Text = "Không khí khô kết hợp với nước biển còn sót lại trong khí quản, đường hô hấp bị kích thích chưa từng có, cơ bắp co thắt mang lại những cơn ho khó kìm chế."
  },
  AvgDialog_23860_Content_13 = {
    Text = "Thiếu niên tóc xanh nhíu mày nhẹ, xúc tu dưới sự kiểm soát của cậu ta một lần nữa quấn quanh người bạn, sau đó——"
  },
  AvgDialog_23860_Content_14 = {
    Text = "Chiếc xúc tu co thắt vài lần với độ mạnh vừa phải, nước biển và cá nhỏ trong cổ họng bị đẩy ra hết dưới sự ép chặt."
  },
  AvgDialog_23860_Content_15 = {
    Text = "Ho, ho... cám ơn bạn."
  },
  AvgDialog_23860_Content_16 = {
    Text = "Không cần cảm ơn, giọng của bạn quá to, sẽ thu hút những người dấn thân vào biển khác."
  },
  AvgDialog_23860_Content_17 = {
    Text = "……Tôi muốn nói là việc cứu tôi khỏi biển…"
  },
  AvgDialog_23860_Content_18 = {
    Text = "Dù việc trở thành thân thể được đánh thức không phải điều ta mong muốn, nhưng Đại học Misag đã kết thúc giấc ngủ vạn năm của ta. \nXét cả tình lẫn lý, ta sẽ không ngồi nhìn \"Người Giữ Gìn\" gặp nguy hiểm."
  },
  AvgDialog_23860_Content_19 = {
    Text = "Nhưng... bạn không nên có mặt ở đây, đúng không? \nDanh sách nhiệm vụ điều tra lần này chỉ có tôi và Ramona."
  },
  AvgDialog_23860_Content_2 = {
    Text = "Nước không ngừng chảy vào thân thể. \n Mũi, tai, họng, khóe mắt… tất cả các lỗ trên chi trên đều bị nước biển lấp đầy."
  },
  AvgDialog_23860_Content_20 = {
    Text = "Không được phép rời khỏi lãnh thổ Misaque mà không có sự phê duyệt của trưởng nhóm hành động ngoại vi và trước khi được liên kết với điều tra viên. Tôi nghĩ rằng bạn đã rõ về điểm này…"
  },
  AvgDialog_23860_Content_21 = {
    Text = "Thân thể được đánh thức tulô, số hiệu lưu trữ -6291, biệt danh \"Chúa Tể Ngủ Say\"."
  },
  AvgDialog_23860_Content_22 = {
    Text = "Ta tin rằng ngươi cũng rõ, những \"giới luật\" của Đại học Misaque trước mặt ta chỉ như không tồn tại."
  },
  AvgDialog_23860_Content_23 = {
    Text = "Hãy ngừng sử dụng những biệt danh ngu ngốc để chỉ ta."
