  AvgDialog_23860_Content_24 = {Text = "Tulô."},
  AvgDialog_23860_Content_25 = {
    Text = "Tôi không phải kẻ cứng nhắc trong hội nghị thẩm tra, thân thể được đánh thức đối với tôi không phải là con thú phải bị xiềng xích."
  },
  AvgDialog_23860_Content_26 = {
    Text = "Tôi lo lắng rằng bạn không có trong danh sách nhân viên của nhiệm vụ ngoại vi, cũng không được liên kết với bất kỳ ai. \nNếu rời khỏi <Yellow:hồ đen> của Misaque quá lâu, bạn có thể mất kiểm soát."
