  AvgDialog_23860_Content_29 = {
    Text = "……Thở."
  },
  AvgDialog_23860_Content_3 = {
    Text = "Máu của bạn đã phản ứng với nước biển, tế bào bị tống ra khỏi cơ thể. Chảy trong mạch máu giờ đây dường như đã trở thành những hạt muối thô ráp và cát bụi."
  },
  AvgDialog_23860_Content_30 = {
    Text = "——Tôi chỉ muốn biết, bạn đang làm gì ở đây? \nBạn thường xuyên duy trì trạng thái ngủ say, ngay cả sự thay đổi đột ngột tại <Yellow:Lễ trao chìa khóa bạc> cũng không thể đánh thức bạn."
  },
  AvgDialog_23860_Content_31 = {
    Text = "Nhưng bạn đã không ngại nguy cơ mất lý trí để xuất hiện ở đây…… Chắc hẳn điều này rất quan trọng đối với bạn."
  },
  AvgDialog_23860_Content_32 = {
    Text = "Điều xảy ra ở đây, đều do tôi mà khởi. \nCòn chi tiết, không liên quan đến ngươi."
