  AvgDialog_23860_Content_33 = {
    Text = "Thế à? Vì không liên quan đến tôi và Ramona, nên khi gặp Miriam, anh cũng khó mà xuất hiện để cứu giúp?"
  },
  AvgDialog_23860_Content_34 = {
