  },
  AvgDialog_23860_Content_35 = {
    Text = "Thái độ im lặng của Tulô gần như kích động sự tức giận trong bạn, nhưng thực tế đã giúp bạn giữ vững lý trí."
  },
  AvgDialog_23860_Content_36 = {
    Text = "Hai tay vài lần nắm chặt rồi lại thả lỏng. Sau vài lần hít thở sâu, bạn cuối cùng cũng nhìn vào thiếu niên được thức tỉnh trước mặt."
  },
  AvgDialog_23860_Content_37 = {
    Text = "Ramona đang ở trong tay của những người dấn thân vào biển. Tulô, tôi rất cần sự giúp đỡ của bạn!"
  },
  AvgDialog_23860_Content_38 = {
    Text = "Tulô ngẩng đầu nhìn sâu vào mắt bạn một lúc lâu, dường như đang chuẩn bị từ chối."
  },
  AvgDialog_23860_Content_39 = {
    Text = "Chính khi cơ miệng anh ta khẽ động, chuẩn bị nói ra câu trả lời, từ sâu trong cabin truyền đến tiếng hét kinh hoàng của một cô gái."
  },
  AvgDialog_23860_Content_4 = {
    Text = "Chúng cào xé từ bên trong thân thể và linh hồn, phổi bị chất lỏng lấp đầy. Ý thức chìm dần theo thân thể, nỗi lo lắng về người đồng đội cũng bị đau đớn và ngạt thở đẩy ra khỏi tâm trí…"
