  },
  AvgDialog_23860_Content_45 = {
    Text = "Tulô ôm đầu không trả lời, nhưng trước khi bạn quay người lao vào sâu trong cabin, bạn nghe thấy tiếng thở dài như có như không của cậu bé."
  },
  AvgDialog_23860_Content_6 = {
    Text = "Sóng mặt bị khuấy động va vào màng nhĩ, vất vả mở mắt, có thứ gì đó ngược ánh sáng lặn xuống nước."
  },
  AvgDialog_23860_Content_7 = {
    Text = "Nó quấn quanh eo bạn một cách linh hoạt, giống như rong biển… không, đó không phải là rong biển, mà là một loại cơ bắp mềm mại và rất dai sức…"
