  AvgDialog_23861_Content_1 = {
    Text = "Những khuôn mặt xấu xí, chỉ cần nhìn thẳng đã khiến người ta cảm thấy như thể đang xúc phạm thuyết tiến hóa."
  },
  AvgDialog_23861_Content_2 = {
    Text = "Chúng đẩy nhau, vũ khí lạnh trong tay va chạm phát ra tiếng động sắc nhọn. Còn ở trung tâm hỗn loạn, chúng dường như đang bao quanh một sự tồn tại nào đó…"
