  AvgDialog_23862_Content_3 = {
    Text = "Nhưng… họ đã đánh bại rất nhiều người dấn thân vào biển… lẽ nào gã đó thật sự không lừa tôi?"
  },
  AvgDialog_23863_Content_1 = {
    Text = "Nhưng… Miriam khi nào lại dùng cách này vậy? \nSao lại nhờ người đến lừa tôi quay về… không giống với cách cô ấy thường làm chút nào."
