  AvgDialog_23864_Content_1 = {
    Text = "Thủy thủ"
  },
  AvgDialog_23864_Content_10 = {
    Text = "Bạn đã dùng những trò đùa về tinh thần để xúc phạm Miriam, còn nói \"biết cô ấy vẫn sống\"... Ngay cả cá chết ngoài biển cũng phải hiểu rằng các người không cùng một phe."
