  },
  AvgDialog_23864_Content_13 = {
    Text = "Muphí cũng không quan tâm bạn và tulô có theo kịp cô ấy hay không, cô thành thạo đẩy một cánh cửa chắn khác và nhẹ nhàng chui vào phía sau cánh cửa."
  },
  AvgDialog_23864_Content_14 = {
    Text = "Bạn đang chuẩn bị đuổi theo thì Tulô duỗi ra một xúc tu, chặn giữa bạn và cửa."
  },
  AvgDialog_23864_Content_15 = {
