  AvgDialog_24075_Content_1 = {Text = "Ugh!!"},
  AvgDialog_24075_Content_10 = {
    Text = "Thậm chí không ngần ngại giết chết con gái ruột của mình…"
  },
  AvgDialog_24075_Content_11 = {
    Text = "Lambert thong thả nâng ly rượu trên bàn, nhấp một ngụm nhỏ rượu vang bên trong."
  },
  AvgDialog_24075_Content_12 = {
    Text = "Heh heh… Trong mắt các người, tôi đương nhiên đã không còn nếm được vị của ly rượu này từ lâu rồi."
  },
  AvgDialog_24075_Content_13 = {
    Text = "Nhưng cậu có biết không? Khi tôi nuốt nó xuống bụng, ký ức của tôi, trí tưởng tượng của tôi sẽ không ngừng mách bảo tôi…"
  },
  AvgDialog_24075_Content_14 = {
    Text = "Đây là rượu vang Montrachet năm @2. Ban đầu ngửi sẽ có mùi hương cam thảo, sau hai tiếng, bạn sẽ cảm nhận được hương hoa hồng nồng nàn…"
  },
  AvgDialog_24075_Content_15 = {
    Text = "Lambert say sưa hít hương rượu vang trong ly, trên mặt lộ ra nụ cười mãn nguyện vô cùng."
  },
  AvgDialog_24075_Content_16 = {
    Text = "Đó chỉ là tưởng tượng mà thôi. Sớm muộn gì ông cũng phải đối mặt với thực tại, thưa ngài Lambert."
  },
  AvgDialog_24075_Content_17 = {
    Text = "Đúng vậy, tưởng tượng! Nó là một sức mạnh phi thường."
  },
  AvgDialog_24075_Content_18 = {
    Text = "Tưởng tượng về tiền bạc, tưởng tượng về quyền lực, tưởng tượng về dục vọng… Nó vừa có thể khiến vị tu sĩ thánh khiết nhất sa ngã, vừa có thể biến tên trộm đê tiện nhất thành tiên tri."
  },
  AvgDialog_24075_Content_19 = {
    Text = "Còn cô con gái yêu quý nhất của tôi? Nó dám tước đoạt chút tưởng tượng cuối cùng của tôi."
  },
  AvgDialog_24075_Content_2 = {
    Text = "Ngài Lambert, ngài đã không còn đường lui nữa, xin hãy hợp tác với chúng tôi."
