  AvgDialog_24079_Content_44 = {
    Text = "Gió lạnh bò qua chân, sắc mặt của đám tín đồ cầm đèn bị thổi tan trong nháy mắt——cô ấy có trở về cùng với Goliath không? Cô ấy đã nghe được bao nhiêu?"
  },
  AvgDialog_24079_Content_45 = {
    Text = "Nhưng điều mà Ramona và hai tín đồ cầm đèn không ngờ tới là Miriam không hề nổi giận, thậm chí không biểu lộ chút bất mãn nào."
  },
  AvgDialog_24079_Content_46 = {
    Text = "Cô ấy nhìn xuống mọi người với thái độ kiêu ngạo, như thể vở hài kịch trước mắt chỉ là tiếng chim hót không đáng để tâm."
  },
  AvgDialog_24079_Content_47 = {
    Text = "Goliath, nhiệm vụ giao cho bạn tiến triển thế nào rồi?"
  },
  AvgDialog_24079_Content_48 = {
    Text = "Ha... Chuột nhỏ của Misaque giỏi đào hang khắp nơi, tôi đã nói rồi, nếu không thể tháo dỡ con tàu này thì tôi cũng chẳng tìm được ai. Hơn nữa, chúng ta vẫn còn con tin mà?"
  },
  AvgDialog_24079_Content_49 = {
    Text = "Goliath vừa nói, vừa vung cây đại đao chỉ về phía Ramona."
  },
  AvgDialog_24079_Content_5 = {
    Text = "Cô nghiêng người xoa xoa cổ chân, mặc dù đã xử lý cấp tốc khớp bị trật, nhưng vết thương vẫn không thể tránh khỏi sưng lên. Chỉ cần chạm nhẹ, cũng có thể gây ra cảm giác bỏng rát như lửa đốt."
  },
  AvgDialog_24079_Content_50 = {
    Text = "Chỉ cần giữ cô gái này, tin rằng người bạn đồng hành của cô ấy sẽ tìm đến theo dấu vết."
  },
  AvgDialog_24079_Content_51 = {
    Text = "Nói đến đó, làm sao bạn đưa thân thể được đánh thức của Elton đến đây? Elton đâu rồi?"
  },
  AvgDialog_24079_Content_52 = {
    Text = "Lễ hội sắp đến, trạng thái của \"Mẹ Thần\"đặc biệt quan trọng. Mặc dù các trợ tế đã thành thạo các bùa chú an giấc, nhưng nếu có thể, tôi không muốn thấy Mẹ Thần phải chịu khổ."
  },
  AvgDialog_24079_Content_53 = {
    Text = "Chỉ cần Hilaster nằm trong tầm kiểm soát của chúng ta, để đảm bảo con tàu này, Sonanil, không mất kiểm soát, Elton chắc chắn sẽ ngoan ngoãn dâng lên Thần Mẫu bằng cả hai tay…"
  },
  AvgDialog_24079_Content_54 = {
    Text = "<Gray:Có vẻ như, thể xác được đánh thức này chính là người điều khiển con tàu ma Sonariel. \nVậy thì thâm cảnh này cũng là kiệt tác của cô ta.>"
  },
  AvgDialog_24079_Content_55 = {
    Text = "<Gray:đợi đã… có lẽ có cách rồi.>"
  },
  AvgDialog_24079_Content_56 = {
    Text = "Khi mọi ánh mắt đều đổ dồn về Miriam, Ramona lặng lẽ chạm vào tay thân thể được đánh thức của cô gái. Người sau ngẩng đầu nhìn cô, khuôn mặt không biểu lộ bất kỳ cảm xúc nào."
  },
  AvgDialog_24079_Content_57 = {
    Text = "<Small:Hilaster… Có lẽ tôi có cách để chúng ta trốn thoát.>"
  },
  AvgDialog_24079_Content_58 = {
    Text = "Sương mù trong mắt Hilaster tan đi một chút, lóe lên vài tia kinh ngạc."
  },
  AvgDialog_24079_Content_59 = {
    Text = "<Small:Bạn là chủ nhân của thâm cảnh, nếu bạn có thể khiến thâm cảnh biến mất một lúc, gây hỗn loạn cho những người dấn thân vào biển…>"
  },
  AvgDialog_24079_Content_6 = {
    Text = "<Gray:chỉ số đau khoảng 4, theo đánh giá chức năng vận động của tôi trong học kỳ này, tốc độ sẽ giảm 20%…>"
  },
  AvgDialog_24079_Content_60 = {
    Text = "Hilaster không trả lời cô ấy, chỉ nháy mắt. Ramona không chắc liệu đối phương có hiểu ý mình hay không, nhưng cô biết rằng dưới găng tay đã thấm mồ hôi vì căng thẳng."
  },
  AvgDialog_24079_Content_61 = {
    Text = "<Small:Đây……là ước muốn của bạn?>"
  },
  AvgDialog_24079_Content_62 = {
    Text = "Ramona ngẩn người, nhưng thân thể đã phản ứng trước suy nghĩ — cô gật đầu một cách vô thức."
  },
  AvgDialog_24079_Content_63 = {
    Text = "Hilaster nâng cao chiếc la bàn trong tay, ánh sáng lan tỏa lấp lánh xoay quanh chân váy của cô, nhanh chóng biến mất không để lại dấu vết."
  },
  AvgDialog_24079_Content_64 = {
    Text = "Đồng thời, không khí ẩm lạnh từ biển Bắc Dương thật sự đã đến. Kèm theo đó là những tiếng la hét ồn ào từ boong tàu."
  },
  AvgDialog_24079_Content_65 = {
    Text = "Mặt trăng!mặt trăng!"
  },
  AvgDialog_24079_Content_66 = {
    Text = "Vào khoảnh khắc đó, phòng động lực chìm vào bóng tối hoàn toàn. Sự yên lặng lạ lẫm và sâu thẳm bao trùm xung quanh, bóng tối nuốt chửng mọi hình dạng, nhưng lại khiến Ramona cảm thấy căng thẳng tột độ."
  },
  AvgDialog_24079_Content_67 = {
    Text = "<Small:hãy tận dụng ngay!>"
  },
  AvgDialog_24079_Content_68 = {
    Text = "Ramona nắm lấy tay thân thể được đánh thức, dồn hết sức mạnh vào chân. Cô ấy đẩy bật người nhảy biển bên cạnh, lao đi với tốc độ tối đa ra khỏi phòng động lực."
  },
  AvgDialog_24079_Content_7 = {
    Text = "<Gray:Thời gian không đủ. Hiện tại phòng động lực đã trở thành cứ điểm của họ, có quá nhiều kẻ địch. Tôi sẽ bị những người dấn thân vào biển ngăn cản trước khi kịp chạy đến cửa.>"
  },
  AvgDialog_24079_Content_8 = {
    Text = "<Gray:thêm vào đó… anh ta cũng canh chừng quá kỹ.>"
  },
  AvgDialog_24079_Content_9 = {
    Text = "Những người dấn thân vào biển đang chuẩn bị cho \"lễ nghi\", và cậu thiếu niên mang thân thể được đánh thức cũng tận tụy hoàn thành nhiệm vụ, đứng bất động để canh gác cô ấy."
  },
  AvgDialog_24080_Content_1 = {
    Text = "Bạn lắc đầu, dựng ngón trỏ lên và đặt nó trên môi, ra hiệu cho cô ấy tạm thời giữ im lặng. Nhưng khi ánh mắt bạn quét qua người trong bóng tối, ngược lại, bạn suýt thốt lên vì kinh ngạc."
  },
  AvgDialog_24080_Content_2 = {
    Text = "<Small:Cô ấy là Hilaster, là một thân thể được đánh thức…>"
  },
  AvgDialog_24080_Content_3 = {
    Text = "Bạn đang trên tàu Sonanil, đã nhiều lần gặp cô ấy trong hình bóng —— cái bóng quen thuộc mà lạ lẫm này hóa ra chính là Hilaster, người kiểm soát thâm cảnh."
  },
  AvgDialog_24080_Content_4 = {
    Text = "Nhân vật quan trọng lẽ ra phải bị Miriam kiểm soát, lại cùng Ramona trốn thoát —— điều này thật bất ngờ, nhưng cũng nằm trong dự đoán."
  },
  AvgDialog_24080_Content_5 = {
    Text = "Dù sao, đối tác của bạn chưa bao giờ là người ngồi không chờ chết."
  },
  AvgDialog_24080_Content_6 = {
    Text = "<Small:… đợi, đợi chút? Đây là thân thể được đánh thức của tulô có số hiệu lưu trữ -6291!>"
