  AvgDialog_24081_Content_15 = {
    Text = "Elton tiếp nhận hộp thuốc lá mà Muphí nhặt lên. Nhìn cô ấy len lén đá lá thuốc vào góc, anh khẽ cười."
  },
  AvgDialog_24081_Content_16 = {
