  },
  AvgDialog_24081_Content_3 = {
    Text = "Elton nhắm mắt lại, thở ra một hơi dài, giống như đang phun những vòng khói, dường như vậy có thể loại bỏ hết sự ô uế trong cơ thể."
  },
  AvgDialog_24081_Content_4 = {
