  AvgDialog_24081_Content_7 = {
    Text = "Liên kết? Vậy có nghĩa là Hilaster này thực sự là thân thể được đánh thức…"
  },
  AvgDialog_24081_Content_8 = {
    Text = "Elton lộ ra một nụ cười khổ, anh lại theo thói quen muốn sờ vào hộp thuốc lá. Nhưng vừa cầm lấy cái hộp nhôm nhỏ lạnh lẽo, tay anh đã run lên dữ dội, hộp rơi xuống đất, làm rớt đầy lá thuốc lá."
  },
  AvgDialog_24081_Content_9 = {
    Text = "Bạn chợt nhận ra rằng, đôi tay của Elton đang run rẩy, không rõ là do vẫn còn bối rối hay đã kiệt sức hoàn toàn."
