  AvgDialog_24083_Content_1 = {
    Text = "Dưới sự hướng dẫn của Hilaster, hai người đi qua các khoang tàu như mê cung. \nKhông lâu sau, họ (chỉ hai người) rẽ vào một khoang mờ tối."
  },
  AvgDialog_24083_Content_10 = {
