  },
  AvgDialog_24084_Content_11 = {
    Text = "Chưa để Tu-lô nói xong, Muphí đã ngồi dậy với mồ hôi nhễ nhại. Cô ấy sờ vào ngực mình, vẻ mặt bối rối."
  },
  AvgDialog_24084_Content_12 = {
    Text = "Tôi... Tôi vẫn còn sống.."
  },
  AvgDialog_24084_Content_13 = {
    Text = "Phải nhanh chóng lấy Ngài ra. Dù thâm cảnh này có thể ngăn sức hút của thiên thể đối với Ngài, nhưng sự tồn tại của Ngài đối với ngươi vẫn là gánh nặng."
  },
  AvgDialog_24084_Content_14 = {
    Text = "Nói thì dễ mà.."
  },
  AvgDialog_24084_Content_15 = {
    Text = "Bạn nhớ lại vật thể ngoại lai ký sinh trên trái tim của cô ấy."
  },
  AvgDialog_24084_Content_16 = {
    Text = "Mạch máu và động mạch chủ của cô ấy đã hòa vào nhau, ngay cả các bác sĩ phẫu thuật giỏi nhất ở Lentiennam cũng không thể đảm bảo thực hiện được ca phẫu thuật như vậy."
  },
  AvgDialog_24084_Content_17 = {
    Text = "Số Naniel thâm cảnh đã ngăn chặn ảnh hưởng của thiên thể, liệu còn cách nào khác để cố gắng giành thêm thời gian cho Muphí…"
  },
  AvgDialog_24084_Content_18 = {
    Text = "Thời gian…thời gian…dừng lại…"
  },
  AvgDialog_24084_Content_19 = {Text = "Muphí…"},
  AvgDialog_24084_Content_2 = {
    Text = "Thuyền trưởng, bạn biết cô ấy đang sao không?"
  },
  AvgDialog_24084_Content_20 = {
    Text = "Động tác của thuyền trưởng khi đỡ cô lên rất chậm rãi và cẩn trọng, giống như đang nâng niu một bức tượng sứ quý giá."
  },
  AvgDialog_24084_Content_21 = {
    Text = "Học sinh, tôi thấy bạn vừa mới suy nghĩ gì đó, bạn có giải pháp nào không?"
  },
  AvgDialog_24084_Content_22 = {
    Text = "Không phải là giải pháp… và rất nguy hiểm."
  },
  AvgDialog_24084_Content_23 = {
    Text = "Đến lúc này, cũng không thể đánh giá còn nguy hiểm hay không nữa. \nAnh cứ nói, chỉ cần có thể giúp Muphí thoát khỏi nguy hiểm…"
  },
  AvgDialog_24084_Content_24 = {
    Text = "Đại học Misag đang tiến hành nghiên cứu về \"dừng thời gian\"."
  },
  AvgDialog_24084_Content_25 = {
    Text = "Hay là các ngươi đã mang về từ Bệnh viện điều dưỡng Laï cái phù văn đó…"
  },
  AvgDialog_24084_Content_26 = {
    Text = "Đúng vậy. Đóa và quý bà Wenkel đang nghiên cứu về phù hiệu đó, hy vọng tạo ra một không gian thí nghiệm an toàn, không bị <Red:chó chiều không gian> phát hiện."
  },
  AvgDialog_24084_Content_27 = {
    Text = "Nghiên cứu đã có hình hài ban đầu, trước khi chúng ta xuất phát, bà Wenkel đã bắt đầu chuẩn bị cho các thí nghiệm trên động vật."
  },
  AvgDialog_24084_Content_28 = {
    Text = "Đừng phí công vô ích."
  },
  AvgDialog_24084_Content_29 = {
    Text = "Trường học của các bạn... không thể ở trên biển được. \n Từ đây trở về đất liền, rồi gấp gáp trở về trường học của các bạn... không kịp đâu."
  },
  AvgDialog_24084_Content_3 = {
    Text = "Thần minh… thần minh trong cơ thể cô ấy…"
  },
  AvgDialog_24084_Content_30 = {
    Text = "Hơn nữa, Hilaster vẫn còn… Nếu cô ấy rơi vào tay người phụ nữ đó, liệu con tàu có thể cập bến hay không vẫn là một ẩn số."
  },
  AvgDialog_24084_Content_31 = {
    Text = "Vậy chúng ta phải tăng tốc rồi. Thuyền trưởng, anh có thể chỉ cho tôi vị trí đại khái của Hilaster không? Tôi và Tulô sẽ tìm cách tìm cô ấy, còn anh và Muphí hãy tạm lánh về nhà an toàn."
  },
  AvgDialog_24084_Content_32 = {
    Text = "Không được!"
  },
  AvgDialog_24084_Content_33 = {
    Text = "Tàu, thuyền trưởng?"
  },
  AvgDialog_24084_Content_34 = {
    Text = "Elton nhận ra sự mất bình tĩnh của mình, anh run rẩy với tay lấy hộp thuốc lá, nhưng khi mở hộp mới nhớ ra lá thuốc đã bay đi xa, không thể với tới."
  },
  AvgDialog_24084_Content_35 = {
    Text = "...đừng đi tìm Hilaster."
  },
  AvgDialog_24084_Content_36 = {
    Text = "Tại sao? Thuyền trưởng, liệu ngài có biết điều gì không?"
  },
  AvgDialog_24084_Content_37 = {
    Text = "Elton buông tay đỡ Muphí, lùi lại hai bước, anh ta cúi đầu nhìn các người, thân hình cao lớn một phần ẩn trong bóng tối."
  },
  AvgDialog_24084_Content_38 = {
    Text = "Hilaster... trong tay của Miriam."
  },
  AvgDialog_24084_Content_39 = {
    Text = "Gì vậy?!"
  },
  AvgDialog_24084_Content_4 = {
    Text = "Tulô nghe lời, sắc mặt hơi thay đổi, một xúc tu trong tầm kiểm soát của anh ta cuốn lấy cánh tay trái của Muphí."
  },
  AvgDialog_24084_Content_40 = {
    Text = "Người khổng lồ… Goliath, vừa lên tàu đã tìm thấy tôi và Hilaster, chúng tôi bị đưa đến trước mặt Miriam…"
  },
  AvgDialog_24084_Content_41 = {
    Text = "Thương cảm vì cả bạn và tôi đều là những kẻ lang thang mất phương hướng, tôi sẽ truyền lại cho bạn cách đưa người đã khuất về thế gian."
  },
  AvgDialog_24084_Content_42 = {
    Text = "Sự xuất hiện của cô ấy, đại diện cho ước nguyện lâu nay của bạn đã được thực hiện, chắc hẳn bạn đã nhận đủ sự an ủi từ những người thân đã qua đời…"
  },
  AvgDialog_24084_Content_43 = {
    Text = "Mà ước nguyện của tôi, niềm hy vọng lớn lao mà vị thần minh gửi gắm cho tôi, chính là đứa trẻ đó. \nXin hãy trả lại Thánh Nữ… không, trả lại Thần Mẫu cho tôi."
  },
  AvgDialog_24084_Content_44 = {
    Text = "Lời thề nguyện của vị chủ tế, khi thần linh tái sinh, thần quốc tái hiện... ngươi cũng sẽ bước vào thần quốc, tìm thấy sự an lạc vĩnh cửu."
  },
  AvgDialog_24084_Content_45 = {
    Text = "Thưa chủ tế, nghe tin thần mẫu mất tích, tôi cũng rất ngạc nhiên. \nNhưng tôi đã nói rồi, thần mẫu không có trên tàu."
  },
  AvgDialog_24084_Content_46 = {
    Text = "Sao phải giả vờ ngây thơ, cố tỏ ra ngu ngốc?"
  },
  AvgDialog_24084_Content_47 = {
    Text = "Tôi từng rất ngưỡng mộ trí thông minh và sự kiên trì của bạn. Điều gì đã làm thay đổi lòng trung thành của bạn với tôi? \n Có phải vì <Blue:tượng ma thuật> này không? Yếu đuối và mỏng manh như vậy…"
  },
  AvgDialog_24084_Content_48 = {
    Text = "Mọi thứ đều do tôi quyết định, tôi mới là chủ của con tàu này. Hilaster hầu như không có ý thức tự chủ, làm sao có thể thay đổi tôi?"
  },
  AvgDialog_24084_Content_49 = {
    Text = "Thật sao? Tôi có thể khiến bạn thức tỉnh cô ấy, và tôi cũng có thể biến cô ấy thành một nắm cát bạc."
  },
  AvgDialog_24084_Content_5 = {
    Text = "Câm miệng lại!"
  },
  AvgDialog_24084_Content_50 = {Text = "Bạn…!"},
  AvgDialog_24084_Content_51 = {
    Text = "Hãy tìm thấy thần mẫu và đưa bà ấy về đây, vẫn nguyên vẹn như cũ."
  },
  AvgDialog_24084_Content_52 = {
    Text = "Đây là cơ hội cuối cùng của bạn, Elton."
  },
  AvgDialog_24084_Content_6 = {
    Text = "Tulô nhắm mắt cảm nhận thông tin mà xúc tu truyền lại. Một lúc sau, ngoài tiếng sóng biển vỗ vào thân tàu, boong tàu chỉ còn lại tiếng khóc đau đớn của Muphí."
  },
  AvgDialog_24084_Content_7 = {
    Text = "Thời gian vài giây trở nên vô cùng dài, ngay trước khi lý trí gần như không thể chịu đựng thêm, tulô cuối cùng đã rút lại xúc tu."
  },
  AvgDialog_24084_Content_8 = {
    Text = "Cô ấy sao rồi?"
  },
  AvgDialog_24084_Content_9 = {
    Text = "Vào giây phút thâm cảnh biến mất, \"giả thần\" trong cơ thể cô đã bị thu hút mạnh mẽ."
  },
  AvgDialog_24091_Content_1 = {
    Text = "Người đi biển đều không quá sợ đau, khi tôi còn nhỏ thường xuyên giẫm phải đuôi của họ, không có bao nhiêu người phản ứng."
  },
  AvgDialog_24091_Content_10 = {
    Text = "Chỉ lần này thôi, sau khi về trường thì tự ngắt kết nối nhé."
  },
  AvgDialog_24091_Content_11 = {
    Text = "Bạn gật đầu, nắm chặt chìa khóa bạc trong tay. Tập trung nhắm mắt, bạn lặn vào bóng tối."
  },
  AvgDialog_24091_Content_12 = {
    Text = "Bạn đuổi theo đốm sáng nhất trong tầm nhìn. Tinh thần bị chèn ép trong bóng tối chật chội bởi vô số sự tồn tại, não bộ đau đến tột độ."
  },
  AvgDialog_24091_Content_13 = {
    Text = "Bạn gắng sức \"đưa tay ra\", bắt lấy ngôi sao đó."
  },
  AvgDialog_24091_Content_14 = {
    Text = "Như linh hồn rời khỏi thân thể, tầm nhìn đột nhiên tăng vọt, bị một lực lượng không thể kháng cự kéo thẳng ra khỏi cơ thể."
  },
  AvgDialog_24091_Content_15 = {
    Text = "Bạn thấy chính mình, thấy Miriam, thấy các tòa tháp thành phố nghiêng ngả trong dòng lũ… Cuối cùng, bạn thấy vị vua trẻ ngồi trên đỉnh núi cao, vẻ mặt điềm tĩnh và lạnh nhạt."
  },
  AvgDialog_24091_Content_16 = {
    Text = "Mở mắt lần nữa, dòng chảy linh tri thức như điện giật nhẹ nhàng kích thích dây thần kinh của bạn. \nĐau đớn, nhưng lại tràn đầy lực lượng chưa từng có."
  },
  AvgDialog_24091_Content_17 = {
    Text = "Hừ… Cuối cùng cũng đến lúc này rồi."
  },
  AvgDialog_24091_Content_18 = {
    Text = "Lần này, Tulô đã tấn công trước vào Goliath vừa xuất hiện, không để anh ta có cơ hội tấn công trước."
  },
  AvgDialog_24091_Content_2 = {
    Text = "Điều này có nghĩa là những người dấn thân vào biển sẽ liên tục đứng dậy… Chúng ta không thể đảm bảo mỗi lần đều có thể tiêu diệt chúng hoàn toàn, đánh như vậy không phải là cách."
  },
  AvgDialog_24091_Content_20 = {
    Text = "Chiếc xúc tu đập vào than đá, tạo ra một làn khói đen xám. \nKhi làn khói rơi xuống như mưa, hình dáng của Miriam bỗng nhiên xuất hiện."
  },
  AvgDialog_24091_Content_21 = {
    Text = "Miriam, bạn có thấy không? Cậu nhóc giả mạo này đã liên kết với người khác ——"
  },
  AvgDialog_24091_Content_22 = {
    Text = "Con rắn khổng lồ tấn công Goliath như một cơn bão dữ dội, sức mạnh dữ dội đến nỗi đã đẩy Goliath vào bức tường sắt của phòng động lực."
  },
  AvgDialog_24091_Content_23 = {
    Text = "Như một viên sao chổi rơi xuống mặt đất, Goliath bị ghim vào thành cabin."
  },
  AvgDialog_24091_Content_24 = {
    Text = "Không thể tha thứ."
  },
  AvgDialog_24091_Content_25 = {
    Text = "Vật ô uế, dám chạm vào chủ ta, chia sẻ lực lượng của thần Lemuria…"
  },
  AvgDialog_24091_Content_26 = {
    Text = "Miriam cúi gằm, từng bước ép sát các người. Dù đi chân trần trên mặt đất, trong tai vẫn vang lên tiếng lá chạm nhẹ như gợn sóng."
  },
  AvgDialog_24091_Content_27 = {
    Text = "Không thể tha thứ… Ngoài tôi, không ai có thể thức tỉnh thần quốc đại diện, không ai!"
  },
  AvgDialog_24091_Content_28 = {
    Text = "Cô ấy, trạng thái của cô ấy không ổn! Nhanh lên! Chạy đi!"
  },
  AvgDialog_24091_Content_29 = {
    Text = "Trong một khoảnh khắc, bóng ma bao phủ phòng động lực ngưng tụ thành thực thể. \nKiến trúc vặn vẹo khó mà hình dung mọc lên từ mặt đất."
  },
  AvgDialog_24091_Content_3 = {
    Text = "Chỉ có tôi, tulô và Người Giữ Gìn là ba người có thể chiến đấu, không gian để nâng cao sức chiến đấu cũng rất hạn chế…"
  },
  AvgDialog_24091_Content_30 = {
    Text = "Vương… chúa thượng…… Muphí… Muphí……"
  },
  AvgDialog_24091_Content_32 = {
    Text = "Bây giờ... vẫn còn cơ hội để quay lại. \nQuay trở lại giáo đoàn, bạn vẫn sẽ là vị \"Thần Mẫu\" tôn quý."
  },
  AvgDialog_24091_Content_33 = {
    Text = "Lễ tang của bạn sẽ trở thành lễ hội long trọng nhất trong lịch sử thần quốc, được nhiều người kính trọng... tên của bạn cũng sẽ được ghi vào sử sách, lưu truyền ngàn đời."
  },
  AvgDialog_24091_Content_34 = {
    Text = "Quay lại bên tôi, chúng ta sẽ… sẽ xử lý <Blue:kẻ bất kính> này."
  },
  AvgDialog_24091_Content_35 = {
    Text = "Xử tử kẻ bẩn thỉu này, kẻ đã giả mạo diện mạo của Chủ nhân, trả lại lực lượng của Chủ nhân cho Chủ nhân. \nChính như vậy… Chủ nhân của Đất nước Thần mới có thể hoàn thiện."
  },
  AvgDialog_24091_Content_36 = {
    Text = "Miriam, hãy mở mắt ra và nhìn tôi, xem tôi là ai!"
  },
  AvgDialog_24091_Content_37 = {Text = "Im lặng!"},
  AvgDialog_24091_Content_38 = {
    Text = "Rắn khổng lồ tan biến rồi lại ngưng tụ, dưới sự tác động của lực lượng của Miriam, không gian dần dần bị bóp méo, thay đổi."
  },
  AvgDialog_24091_Content_39 = {
    Text = "Kẻ giả thần, kẻ lừa đảo, kẻ bất kính… kẻ vô tín… không được sử dụng hình dạng của @2!"
  },
  AvgDialog_24091_Content_4 = {
    Text = "Nói đến nửa chừng, ánh mắt Ramona bỗng lóe lên."
  },
  AvgDialog_24091_Content_40 = {
    Text = "<Change>▼▼người đó…không kính▼▼……không kính, không cảnh, không cấm▼▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_24091_Content_41 = {
    Text = "Miệng phát ra âm thanh chói tai không rõ nghĩa, Miriam dùng hai tay siết chặt cổ mình, thân thể biến dạng và kéo dài."
  },
  AvgDialog_24091_Content_42 = {
    Text = "Cẩn thận! Cô ấy sắp mất kiểm soát!"
  },
  AvgDialog_24091_Content_5 = {
    Text = "Tulô và Người Giữ Gìn… chưa có liên kết, phải không?"
  },
  AvgDialog_24091_Content_6 = {
    Text = "Thật sự không có. Ý bạn là để tôi và Tulô…"
  },
  AvgDialog_24091_Content_7 = {
    Text = "Liên kết không chỉ để áp chế và sắp xếp linh tri thức thiên nhiên điên cuồng của thân thể được đánh thức, mà còn giúp các điều tra viên dẫn dắt dòng chảy của điên cuồng, từ đó điều khiển biểu hiện của thân thể được đánh thức trong chiến đấu."
  },
  AvgDialog_24091_Content_8 = {
    Text = "Nói đơn giản, liên kết càng nhiều thì khả năng chiến đấu của thân thể được đánh thức càng mạnh."
  },
  AvgDialog_24092_Content_1 = {
    Text = "Mở mắt ra"
  },
  AvgDialog_24092_Content_10 = {
    Text = "Chủ trì cuộc họp?"
  },
  AvgDialog_24092_Content_100 = {
    Text = "Chưa đi được hai bước, một cơn rung động dữ dội, như thể sắp xé nát con tàu, truyền đến từ dưới chân."
  },
  AvgDialog_24092_Content_101 = {
    Text = "Trong tiếng nổ lớn, ngọn lửa bắn lên trời, không khí nóng bỏng đẩy mạnh bạn ngã nhào xuống đất."
  },
  AvgDialog_24092_Content_102 = {
    Text = "—— Trước khi ý thức lại bị ngắt quãng, hình ảnh cuối cùng in vào mắt là những con chim biển bay vụt qua bầu trời đêm trăng tròn."
  },
  AvgDialog_24092_Content_11 = {
    Text = "Ngủ thế nào?"
  },
  AvgDialog_24092_Content_12 = {Text = "Đóa?!"},
  AvgDialog_24092_Content_13 = {
    Text = "Đừng lo lắng, bây giờ không phải lúc để truy cứu việc bạn dẫm lên cỏ vào buổi chiều ngày làm việc đâu."
  },
  AvgDialog_24092_Content_14 = {
    Text = "<Gray:Đó là ý nghĩa sớm muộn gì cũng sẽ bị truy cứu…>"
  },
  AvgDialog_24092_Content_15 = {
    Text = "Ramona tránh ánh nhìn của bạn, phía sau đầu cô ấy như thể hiện rõ \"vô phương giúp đỡ\"."
  },
  AvgDialog_24092_Content_16 = {
    Text = "Trong nhật ký của Francis có đề cập đến một số thông tin về \"Hội Giáo đèn lồng\"—đúng rồi, bạn chưa kịp ôn lại ba tiết học bắt buộc phải không."
  },
  AvgDialog_24092_Content_17 = {
    Text = "Hội Giáo đèn lồng, tin tưởng \"Sự tiêu vong là phúc lành của thần, là sự cứu rỗi duy nhất cho nhân loại\", dụ dỗ những người bệnh đau khổ gia nhập và nhiễm rỗng rỗng."
  },
  AvgDialog_24092_Content_18 = {
    Text = "Cảm ơn bạn đã nhắc lại, Giáo sư Dexter. \nTuy nhiên, tôi nghĩ Erika sẽ không thích bạn can thiệp vào công việc của cô ấy."
  },
  AvgDialog_24092_Content_19 = {
    Text = "Đều tại tôi, thời gian còn lại giao lại cho các bạn."
  },
  AvgDialog_24092_Content_2 = {
    Text = "Sao bạn lại ngủ ở đây vậy?"
  },
  AvgDialog_24092_Content_20 = {
    Text = "Francis đã để lại nhiều manh mối chỉ hướng đến Hội Giáo đèn lồng, trong đó điểm \"người chết hồi sinh\"đặc biệt gây chú ý."
  },
  AvgDialog_24092_Content_21 = {
    Text = "Với sự xuất hiện của Lily, chúng ta có lý do nghi ngờ rằng Hội Giáo đèn lồng đã nắm được cách thức triệu hồi thân thể được đánh thức."
  },
  AvgDialog_24092_Content_22 = {
    Text = "Sự tồn tại của thân thể được đánh thức, trên thế giới không nên là bí mật tuyệt đối sao?"
  },
  AvgDialog_24092_Content_23 = {
    Text = "Có vẻ như bạn cũng không để tâm đến các khóa học liên quan đến lịch sử thân thể được đánh thức. \nTôi bắt đầu cảm thấy tò mò, không biết bằng cách nào bạn đã vượt qua bài kiểm tra sơ kỳ."
  },
  AvgDialog_24092_Content_24 = {
    Text = "Các công ty nắm giữ công nghệ như bạc tâm thức tỉnh hoặc tương tự, không chỉ riêng Misaque."
  },
  AvgDialog_24092_Content_25 = {
    Text = "Sự xuất hiện của thân thể được đánh thức có thể truy ngược về thời kỳ trước Hồng Tích, thậm chí trong lăng mộ của triều đại thứ mười chín Gulumuwa, cũng có những bức tranh tường nghi ngờ là miêu tả việc gọi thân thể được đánh thức."
  },
  AvgDialog_24092_Content_26 = {
    Text = "Trong số này, \"Ma Tượng\" gần gũi nhất với kỹ thuật thân thể được đánh thức của Misaque, được kế thừa từ các dòng họ phù thủy ở vùng Levant."
  },
  AvgDialog_24092_Content_27 = {
    Text = "Lời nói lạc đề."
  },
  AvgDialog_24092_Content_28 = {
    Text = "Dựa vào niềm tin và quy cách nghi lễ được mô tả trong nhật ký, \"Hội Giáo đèn lồng\" mà Francis tiếp xúc có sự khác biệt so với thông tin chúng ta có được."
  },
  AvgDialog_24092_Content_29 = {
    Text = "Sau đó, thiết bị truyền hình ảnh từ xa mà tôi để lại cho Herbert đã gửi lại biểu tượng này. \nChúng tôi nghi ngờ Herbert là người môi giới giữa Francis và Hội Giáo đèn lồng."
  },
  AvgDialog_24092_Content_3 = {
    Text = "Dậy đi, ngủ ở đây sẽ bị cảm lạnh nhé."
  },
  AvgDialog_24092_Content_30 = {
    Text = "Nhiệm vụ ngoại trường tiếp theo của các bạn là xác minh nội dung nhật ký —— đồng thời điều tra mối liên hệ giữa biểu tượng phù hiệu này và Hội Giáo đèn lồng."
  },
  AvgDialog_24092_Content_31 = {
    Text = "Francis đã ghi lại trong nhật ký của mình về hành trình trước khi xuất phát đến cực địa. \nLần này chúng ta sẽ đi đến nơi cô ấy lên tàu —— thị trấn Brillport, có thể có những manh mối được để lại ở đó."
  },
  AvgDialog_24092_Content_32 = {
    Text = "Khi bạn đã sẵn sàng, chúng ta sẽ xuất phát. Tôi sẽ tiếp tục đảm nhận vai trò là đối tác của bạn."
  },
  AvgDialog_24092_Content_33 = {
    Text = "Hành lý để xuất phát luôn luôn sẵn sàng."
  },
  AvgDialog_24092_Content_34 = {
    Text = "Hay là ngủ thêm một chút nữa?"
  },
  AvgDialog_24092_Content_35 = {
    Text = "Không cần đâu! \nTôi đã hiểu rõ yêu cầu nhiệm vụ, và nhớ lại tất cả chi tiết từ tối qua!"
  },
  AvgDialog_24092_Content_36 = {
    Text = "Vậy thì, xuất phát thôi. \nNếu khởi hành hôm nay, có lẽ khi trở về vẫn kịp xem lần đầu ra mắt vở kịch mới tại Nhà hát Opera Lentiennam."
  },
  AvgDialog_24092_Content_37 = {
    Text = "Tôi đi tìm tài xế, hẹn gặp ở cổng trường nhé."
  },
  AvgDialog_24092_Content_38 = {
    Text = "Hình dáng của Ramona nhanh chóng biến mất khỏi tầm nhìn, bạn cũng chuẩn bị trở về ký túc xá để lấy hành lý."
  },
  AvgDialog_24092_Content_39 = {
    Text = "Người Giữ Bí Mật."
  },
  AvgDialog_24092_Content_4 = {
    Text = "Ừ… Ramona?"
  },
  AvgDialog_24092_Content_40 = {
    Text = "Lần nhiệm vụ này, có thể sẽ có tiếp xúc trực diện với Hội Giáo đèn lồng."
  },
  AvgDialog_24092_Content_41 = {
    Text = "Tiết lộ những bí mật họ giấu diếm chỉ là nhiệm vụ phụ, ưu tiên hàng đầu của bạn là phải sống sót. Tôi không biết phải tìm Người Giữ Gìn khác từ đâu trong đống đổ nát này."
  },
  AvgDialog_24092_Content_42 = {
    Text = "Đừng có khắt khe với người trẻ như thế."
  },
  AvgDialog_24092_Content_43 = {
    Text = "Tuy nhiên, đóa nói đúng. Trước đây, những tín đồ các người gặp đều chỉ là thành viên ngoại vi, lõi cốt thực sự của Hội Giáo đèn lồng vẫn chưa lộ diện."
  },
  AvgDialog_24092_Content_44 = {
    Text = "Có vẻ như giáo sư rất quen thuộc với Hội Giáo đèn lồng?"
  },
  AvgDialog_24092_Content_45 = {
    Text = "Haha, chỉ là một đoạn duyên nợ mà thôi."
  },
  AvgDialog_24092_Content_46 = {
    Text = "Nếu cần thiết, Misaque sẽ cử những điều tra viên có kinh nghiệm chiến đấu hơn, thậm chí cầu viện Hội nghị thẩm tra Hiệp định Misidia để giải quyết vấn đề này."
  },
  AvgDialog_24092_Content_47 = {
    Text = "Hãy nhất định sống sót trở về."
  },
  AvgDialog_24092_Content_48 = {
    Text = "Tôi hiểu rồi, chúng ta nhất định sẽ trở về bình an."
  },
  AvgDialog_24092_Content_5 = {
    Text = "Tôi đã ngủ bao lâu?"
  },
  AvgDialog_24092_Content_50 = {
    Text = "Còn đang xem gì? Họ đã xuất phát rồi đấy."
  },
  AvgDialog_24092_Content_51 = {
    Text = "Đừng lo lắng, họ đều là những đứa trẻ có chừng mực."
  },
  AvgDialog_24092_Content_52 = {
    Text = "Tôi không lo lắng. Ngay cả khi phải đào tạo lại một Người Giữ Gìn, tiền cũng sẽ được lấy từ tài khoản ngân hàng của gia đình Dexter."
  },
  AvgDialog_24092_Content_53 = {
    Text = "Quan tâm đến bản thân nhiều hơn đi. Tôi vừa nghe được, có một cô gái nào đó sắp đi hẹn hò ở nhà hát opera."
  },
  AvgDialog_24092_Content_54 = {
    Text = "Ha, haha,… Những người trẻ hiện nay…"
  },
  AvgDialog_24092_Content_55 = {
    Text = "Đêm hôm đó"
  },
  AvgDialog_24092_Content_56 = {
    Text = "Tàu định kỳ đi cực địa? Tôi thấy các người điên rồi! Ở đây không có tàu định kỳ nào cả, cũng không có nhà thờ hay giáo hội nào!"
  },
  AvgDialog_24092_Content_57 = {
    Text = "Đừng hỏi nữa, chúng tôi chỉ là những ngư dân bình thường, chúng tôi không biết gì cả."
  },
  AvgDialog_24092_Content_58 = {
    Text = "Bà này, xin hãy chờ một chút——"
  },
  AvgDialog_24092_Content_59 = {
    Text = "Các người đang dựa vào thân phận quan chức thành phố để bắt nạt người dân quê!"
  },
  AvgDialog_24092_Content_6 = {
    Text = "Ai biết được? Bạn thậm chí không có mặt trong cuộc họp trước giờ xuất phát buổi chiều."
  },
  AvgDialog_24092_Content_60 = {
    Text = "Chúng tôi tuyệt đối không có ý đó—— à!"
  },
  AvgDialog_24092_Content_61 = {
    Text = "Người phụ nữ đóng sầm cửa lại, nếu không có Ramona kịp thời kéo bạn một cái, có lẽ bạn đã phải về trường với chiếc mũi bị lệch rồi."
  },
  AvgDialog_24092_Content_62 = {
    Text = "Brielle Port… thị trấn này thật kỳ lạ."
  },
  AvgDialog_24092_Content_63 = {
    Text = "Đây là cánh cửa thứ ba chúng ta đã gõ, nhưng không có ai muốn chia sẻ thông tin về thị trấn nhỏ với chúng ta."
  },
  AvgDialog_24092_Content_64 = {
    Text = "Chúng tôi thậm chí chỉ đang hỏi đường. Họ có vẻ như đang cùng nhau che giấu điều gì đó, rất kỳ lạ."
  },
  AvgDialog_24092_Content_65 = {
    Text = "Hãy đến bến cảng xem, biết đâu sẽ có manh mối."
  },
  AvgDialog_24092_Content_67 = {
    Text = "Có chuyện gì sao?"
  },
  AvgDialog_24092_Content_68 = {
    Text = "Có lẽ chỉ là ảo giác chăng, trong gió dường như có tiếng người nói."
  },
  AvgDialog_24092_Content_69 = {
    Text = "Yo, đúng lúc, có hai kẻ lơ đễnh từ nơi khác đến. \n Ngăn họ lại? Để khỏi phải tìm người khác."
  },
  AvgDialog_24092_Content_7 = {
    Text = "Hội nghị?"
  },
  AvgDialog_24092_Content_70 = {
    Text = "Đuổi họ về hướng con tàu."
  },
  AvgDialog_24092_Content_71 = {
    Text = "Hừ, đồ xấu tính."
  },
  AvgDialog_24092_Content_72 = {
    Text = "Đi đi, Kẻ khắc sét, đây là lúc để bạn tỏa sáng."
  },
  AvgDialog_24092_Content_73 = {
    Text = "Vâng, thưa ngài Goliath."
  },
  AvgDialog_24092_Content_74 = {
    Text = "Đếm ngược ba giờ"
  },
  AvgDialog_24092_Content_75 = {
    Text = "—— khi!"
  },
  AvgDialog_24092_Content_76 = {
    Text = "Đau nhói lên từ trán, cú va chạm khiến bạn cảm thấy trời đất như quay cuồng. Muphí nhân cơ hội thoát khỏi bạn, ôm trán chạy vào sâu hơn trong tàu."
  },
  AvgDialog_24092_Content_77 = {
    Text = "Tôi biết ngay mà, các người quả nhiên không phải là người tốt!!"
  },
  AvgDialog_24092_Content_78 = {
    Text = "Đừng, đừng… nghe tôi giải thích…"
  },
  AvgDialog_24092_Content_79 = {
    Text = "Đếm ngược @2 phút"
  },
  AvgDialog_24092_Content_8 = {
    Text = "Là có liên quan đến Francis ——"
  },
  AvgDialog_24092_Content_80 = {
    Text = "Bây giờ chúng ta lên tàu."
  },
  AvgDialog_24092_Content_81 = {
    Text = "Đã xem đủ chưa?"
  },
  AvgDialog_24092_Content_82 = {
    Text = "Vào giây phút thâm cảnh biến mất, \"giả thần\" trong cơ thể cô đã bị thu hút mạnh mẽ."
  },
  AvgDialog_24092_Content_83 = {
    Text = "Hàng giả…… đi chết đi!"
  },
  AvgDialog_24092_Content_84 = {
    Text = "Người giữ bí mật! Đừng buông tay tôi!"
  },
  AvgDialog_24092_Content_86 = {
    Text = "Vòng tay của biển cả trở nên sắc nhọn, nước biển và làn da bị cháy phản ứng ra cuộc đấu tranh khiến người ta nghẹt thở. \nHỗn loạn mù quáng như ma quỷ trong bóng tối, xé toạc, bẻ gãy thân thể của bạn."
  },
  AvgDialog_24092_Content_87 = {
    Text = "Sau đó, từ trong hỗn loạn chợt lóe lên một tia ấm áp. Trong bóng tối mênh mông, nỗi cô đơn, sự bất lực và tuyệt vọng dần rút lui, để lại ánh sáng ấm áp kỳ bí tỏa sáng giữa vũ trụ giá lạnh."
  },
  AvgDialog_24092_Content_88 = {
    Text = "Dường như đã chạm vào lòng từ bi của vũ trụ, ý thức bước đi trên ranh giới của linh tri thức. Thân thể dần hòa tan vào oxy trong nước biển, bạn đột ngột mở mắt, và dòng nước biển tràn vào cơ thể qua khóe mắt."
  },
  AvgDialog_24092_Content_89 = {
    Text = "Cuối cùng, ánh sáng dịu dàng xé tan bóng tối dưới đáy biển. Lực lượng xanh trắng đưa tay về phía bạn —— tựa như thần nữ bảo hộ cho chuyến hải trình, giúp đỡ bạn."
  },
  AvgDialog_24092_Content_9 = {
    Text = "Thôi, cứ để người chủ trì cuộc họp giải thích trực tiếp cho bạn nhé."
  },
  AvgDialog_24092_Content_90 = {
    Text = "Tôi nhớ rồi… Miriam hấp hối đã gây ra một vụ nổ, tôi không thể nắm lấy tay Ramona và rơi xuống biển… Không đúng, nhưng… đây là boong tàu Sonanir."
  },
  AvgDialog_24092_Content_91 = {
    Text = "Cái lực lượng cuối cùng giúp tôi… có phải là Hilaster không? Cô ấy đã cứu tôi khỏi biển sâu…"
  },
  AvgDialog_24092_Content_92 = {
    Text = "Thì những người khác có lẽ cũng đang ổn cả!"
  },
  AvgDialog_24092_Content_93 = {
    Text = "Ánh sáng ấm áp mơ màng bị thay thế bởi ánh trăng trắng bệch, màn rèm bao phủ con tàu không biết từ bao giờ vỡ vụn, biến mất, và rơi xuống biển sâu."
  },
  AvgDialog_24092_Content_94 = {
    Text = "Màn che…… biến mất?!"
  },
  AvgDialog_24092_Content_95 = {
    Text = "Đuôi tàu bốc lên những làn khói cuồn cuộn, chính là hướng của phòng động lực."
  },
  AvgDialog_24092_Content_96 = {
    Text = "Xấu rồi!"
  },
  AvgDialog_24092_Content_97 = {
    Text = "Bạn cố gắng bỏ qua cơn đau dữ dội từ sâu thẳm linh hồn, bám vào thành tàu và đi về hướng khói đặc đang bốc lên."
  },
  AvgDialog_24092_Content_98 = {
    Text = "Cuống họng đầy mùi máu và khói súng, mỗi lần hít thở khi di chuyển dường như đều trở thành cực hình."
  },
  AvgDialog_24092_Content_99 = {
    Text = "Ramona, Muphí, Hilaster, tulô… Phải nhanh chóng gặp họ."
  },
  AvgDialog_24093_Content_1 = {
    Text = "Quyết tâm"
  },
  AvgDialog_24093_Content_10 = {
    Text = "Ai đó——Hilaster!!"
  },
  AvgDialog_24093_Content_11 = {
    Text = "Elton hít sâu vài lần, đón chào ba người xuất hiện trong bộ dạng bối rối và mệt mỏi."
  },
  AvgDialog_24093_Content_12 = {
    Text = "Cánh tay xúc tu của Tulô đỡ lấy Ramona, người có vẻ mặt nghiêm trọng, nhưng vẫn lộ ra vẻ mệt mỏi từ những cơ bắp run rẩy."
  },
  AvgDialog_24093_Content_13 = {
    Text = "Đồng phục học sinh……bạn chính là người bạn đồng hành của %player%."
  },
  AvgDialog_24093_Content_14 = {
    Text = "Ramona nhìn quanh một vòng, ngoài tulô đã quen biết từ trong trường và Hilaster cùng trốn thoát ra, còn có hai gương mặt lạ."
  },
  AvgDialog_24093_Content_15 = {
    Text = "Họ… là thuyền trưởng của tàu Muphí và Sonanir. Những Người Giữ Gìn sẵn sàng hy sinh để bảo vệ họ."
  },
  AvgDialog_24093_Content_16 = {
    Text = "Ramona Dexter, bạn có thể gọi tôi là Ramona. \nChúng ta hãy bỏ qua những lời khách sáo, bây giờ tôi cần biết mọi thứ đang xảy ra trên con tàu này, ngắn gọn và nhanh chóng."
  },
  AvgDialog_24093_Content_17 = {
    Text = "Các người là ai, tại sao người dấn thân vào biển lại săn lùng các người, và \"nghi lễ\" mà Miriam cuồng nhiệt theo đuổi..."
  },
  AvgDialog_24093_Content_18 = {
    Text = "Tôi, tôi là…"
  },
  AvgDialog_24093_Content_19 = {
    Text = "Elton đã chặn lại Muphí đang muốn mở miệng vội vàng, anh biết đứa trẻ này không thể mô tả toàn bộ sự việc một cách toàn diện và chi tiết dưới áp lực lớn."
  },
  AvgDialog_24093_Content_2 = {
    Text = "Tàu hàng ngoại hải · Sonaniel \n hầm hàng thứ ba"
  },
  AvgDialog_24093_Content_20 = {
    Text = "Tôi là Elton, đó là người bạn đồng hành của tôi Hilaster, là hai thuyền viên duy nhất trên tàu hàng Sonanil này."
  },
  AvgDialog_24093_Content_21 = {
    Text = "Trong thời trẻ của tôi, Miriam đã giúp tôi thức tỉnh Hilaster. Đổi lại, chúng tôi điều khiển tàu Sonanil, di chuyển giữa lục địa và vùng cực, vận chuyển vật tư cho giáo đoàn Đạo Hải Nhân."
  },
  AvgDialog_24093_Content_22 = {
    Text = "Cuối cùng, vì đã giúp Muphí thoát khỏi giáo đoàn, chúng tôi bị Miriam truy đuổi."
  },
  AvgDialog_24093_Content_23 = {
    Text = "Muphí mang trong mình vị thần giả mà Miriam muốn gọi, tôi không biết đó có phải là thần minh thật hay không, nhưng nghi lễ diễn ra, Muphí khó tránh khỏi số phận."
  },
  AvgDialog_24093_Content_24 = {
    Text = "Muphí cũng kể về một số điều, thân thể của cô ấy, cô ấy và Miriam, và quá khứ của cô ấy trong giáo đoàn…"
  },
  AvgDialog_24093_Content_25 = {
    Text = "Thật không ngờ đã xảy ra nhiều chuyện như vậy…"
  },
  AvgDialog_24093_Content_26 = {
    Text = "Tôi sẽ cho Hilaster quay về đất liền với tốc độ tối đa, nhưng liệu có thể cứu được %player%, tôi không thể đảm bảo với bạn."
  },
  AvgDialog_24093_Content_27 = {
    Text = "Elton chưa dứt lời, tất cả mọi người đều loạng choạng hai bước vì quán tính —— đúng như anh ấy nói, Hilaster đã tăng tốc con tàu."
  },
  AvgDialog_24093_Content_28 = {
    Text = "Khụ, khụ khụ…"
  },
  AvgDialog_24093_Content_29 = {
    Text = "Đội trưởng! Lái tàu nhanh như vậy, gánh nặng cho anh quá lớn rồi."
  },
  AvgDialog_24093_Content_3 = {
    Text = "Đế giày cứng đạp lên boong tàu, phát ra tiếng bước chân đều đặn và nặng nề."
  },
  AvgDialog_24093_Content_30 = {
    Text = "…… đều là những chuyện nhỏ."
  },
  AvgDialog_24093_Content_31 = {
    Text = "Cấu kết với giáo đoàn, đã làm ngơ trước nỗi đau của ngươi, tội lỗi của ta đã quá nặng nề."
  },
  AvgDialog_24093_Content_32 = {
    Text = "Của tôi……sự đau khổ?"
  },
  AvgDialog_24093_Content_33 = {
    Text = "Người đã đưa cậu đến tay Miriam, chính là tôi."
  },
  AvgDialog_24093_Content_35 = {
    Text = "Bạn là \"hàng hóa\" quý giá nhất mà tôi đã vận chuyển kể từ khi gia nhập giáo đoàn. Nhờ chuyến đi hoàn hảo đó, tôi mới được Miriam để mắt đến."
  },
  AvgDialog_24093_Content_36 = {
    Text = "Vì vậy, nên khi ở trụ sở giáo đoàn, bạn đã không do dự mà giúp đỡ tôi ngay lập tức…"
  },
  AvgDialog_24093_Content_37 = {
    Text = "Khi chúng ta đến đủ gần bờ biển, tôi sẽ để Hilaster và bạn cùng xuống tàu, các bạn càng xa đại dương càng tốt."
  },
  AvgDialog_24093_Content_38 = {
    Text = "Dường như đang đáp lại thuyền trưởng, Hilaster lắc chiếc la bàn trong tay."
  },
  AvgDialog_24093_Content_39 = {
    Text = "Bạn có ý muốn cho Hilaster và tôi cùng đi không?"
  },
  AvgDialog_24093_Content_4 = {
    Text = "Hilaster, %player%"
  },
  AvgDialog_24093_Content_40 = {
    Text = "Ramona hiểu ý của thuyền trưởng sớm hơn một chút."
  },
  AvgDialog_24093_Content_41 = {
    Text = "Tôi và Người Giữ Gìn có thể liên lạc phương tiện giao thông, chỉ cần để Hilaster biến chiếc xe hơi của chúng ta thành thâm cảnh…"
  },
  AvgDialog_24093_Content_42 = {
    Text = "Đúng vậy, như vậy sẽ giúp bạn có đủ thời gian."
  },
  AvgDialog_24093_Content_43 = {
    Text = "Đừng đùa nữa! Anh nghĩ chỉ với mình anh có thể chặn được những con quái vật đó sao? Anh thậm chí không phải là người dấn thân vào biển, mà chỉ là một con người bình thường!"
  },
  AvgDialog_24093_Content_44 = {
    Text = "Không, việc này để chúng tôi lo liệu."
  },
  AvgDialog_24093_Content_45 = {
    Text = "Chặn đứng nghi lễ dị giáo, bảo vệ thế giới khỏi sự vô định……\nĐây là trách nhiệm của mọi người tại Đại học Misaque."
  },
  AvgDialog_24093_Content_46 = {
    Text = "Bạn cũng điên rồi sao? Bạn thậm chí còn không biết chúng tôi có đang nói dối bạn hay không."
  },
  AvgDialog_24093_Content_47 = {
    Text = "Người giữ bí mật đã chọn tin tưởng bạn, vì vậy tôi cũng sẽ tin tưởng bạn."
  },
  AvgDialog_24093_Content_48 = {
    Text = "Thuyền trưởng đứng dậy lảo đảo, sau đó đưa tay về phía Murphy — \nanh ta xoa mạnh tóc Murphy."
  },
  AvgDialog_24093_Content_49 = {
    Text = "<Small:Sao thế! Đừng chạm mạnh như thế! Tóc bị dựng hết lên rồi!>"
  },
  AvgDialog_24093_Content_5 = {
    Text = "Còn tulô… sao vẫn chưa trở về."
  },
  AvgDialog_24093_Content_50 = {
    Text = "Tôi hy vọng bạn có thể thoát khỏi tất cả điều này, hãy coi đó là ước nguyện cuối cùng của tôi."
  },
  AvgDialog_24093_Content_51 = {
    Text = "Kết quả tồi tệ nhất không phải là chìm xuống đáy biển sao? Tôi đã sớm nên cùng con tàu Sonanier nằm lại dưới biển sâu rồi."
  },
  AvgDialog_24093_Content_52 = {
    Text = "Murphí bám chặt vào phần đuôi áo khoác của thuyền trưởng, kiên quyết không chịu buông tay."
  },
  AvgDialog_24093_Content_53 = {
    Text = "Ramona nắm chặt trong lòng bàn tay, cuối cùng như đã quyết định điều gì đó, đưa vật cầm trong tay cho Muphí —— hóa ra là máy liên lạc của Đại học Misag."
  },
  AvgDialog_24093_Content_54 = {
    Text = "Di sản, di sản?"
  },
  AvgDialog_24093_Content_55 = {
    Text = "Đây là một thiết bị liên lạc, mặc dù nó tạm thời không hoạt động trong thâm cảnh, nhưng nhà trường có lẽ vẫn đang cố gắng liên lạc với chúng ta."
  },
  AvgDialog_24093_Content_56 = {
    Text = "Nếu bạn thực sự có thể nhìn thấy sự rỗng rỗng bằng mắt thường, thì bạn chắc chắn có đủ sức mạnh tinh thần để sử dụng nó. \nKhi chiếc ghim ngực phát sáng, hãy tập trung chú ý, bạn sẽ có thể thiết lập liên lạc với người kia."
  },
  AvgDialog_24093_Content_57 = {
    Text = "Dù cho tôi và Người Giữ Gìn không thể quay lại tìm các bạn, đồng nghiệp của chúng tôi chắc chắn sẽ hỗ trợ bạn."
  },
  AvgDialog_24093_Content_58 = {
    Text = "Muphí nhận lấy huy hiệu, cô nhìn vào những hoa văn kim loại tinh xảo trên đó, đôi mắt bỗng nhiên đỏ ngầu."
  },
  AvgDialog_24093_Content_59 = {
    Text = "Gì thế này…… giả vờ như sẵn sàng hy sinh."
  },
  AvgDialog_24093_Content_6 = {
    Text = "Muphí cắn môi, đi tới đi lui trong sự lo lắng tột độ. Lúc thì đá mạnh vào thùng hàng, lúc lại kéo hai lần dây cố định thùng hàng."
  },
  AvgDialog_24093_Content_60 = {
    Text = "Tulô không có ý định tham gia vào cuộc tranh cãi này, anh ấy đứng ngoài cửa cảm nhận sự dao động của lực lượng, chuẩn bị lên đường đến phòng động lực."
  },
  AvgDialog_24093_Content_61 = {
    Text = "——đợi đã! bạn định đi đâu!"
  },
  AvgDialog_24093_Content_62 = {
    Text = "Cô gái đẩy mở cửa buồng, đưa tay kéo một xúc tu."
  },
  AvgDialog_24093_Content_63 = {
    Text = "Bạn có đi cứu {Male=anh ấy,Female=cô ấy} không?"
  },
  AvgDialog_24093_Content_64 = {
    Text = "Việc ta làm, ngoại nhân không được can thiệp."
  },
  AvgDialog_24093_Content_65 = {
    Text = "Tôi cũng đi."
  },
  AvgDialog_24093_Content_66 = {
    Text = "Muphí! Đừng cứng đầu."
  },
  AvgDialog_24093_Content_67 = {
    Text = "Bạn ở lại đây, tôi và Tulô sẽ đi giúp Người Giữ Gìn thoát khỏi cảnh khốn khổ. \nNếu bạn rơi vào tay của Miriam, nỗ lực của chúng ta sẽ trở nên vô nghĩa."
  },
  AvgDialog_24093_Content_68 = {Text = "Ta biết."},
  AvgDialog_24093_Content_69 = {
    Text = "Nhưng... thật sự tôi không thể... \nTôi không muốn chết, nhưng... nếu, nếu các người không quay lại thì sao?"
  },
  AvgDialog_24093_Content_7 = {
    Text = "Họ sẽ không sao chứ……"
  },
  AvgDialog_24093_Content_70 = {
    Text = "Tôi... không muốn chuyện đó.."
  },
  AvgDialog_24093_Content_71 = {
    Text = "……Tôi không thể ở mãi trong thâm cảnh, nếu muốn thoát thân thực sự, tôi cần các bạn giúp đỡ bằng cách giới thiệu."
  },
  AvgDialog_24093_Content_72 = {
    Text = "Tôi không thể trực tiếp tìm đến trường học và nói với hiệu trưởng rằng học sinh của họ đã hy sinh để giúp tôi. \n Tôi cần sự giới thiệu của các bạn, cả hai đều phải sống."
  },
  AvgDialog_24093_Content_73 = {
    Text = "Ta sẽ không phân tâm bảo vệ ngươi."
  },
  AvgDialog_24093_Content_74 = {
    Text = "Không cần anh bảo vệ, tôi biết rõ điểm yếu của người dấn thân vào biển, tôi có thể tự chăm sóc bản thân."
  },
  AvgDialog_24093_Content_75 = {
    Text = "Được, nếu bạn nhất quyết như vậy."
  },
  AvgDialog_24093_Content_76 = {
    Text = "Bạn nhìn tôi với ánh mắt như thế nào vậy?"
  },
  AvgDialog_24093_Content_77 = {
    Text = "Ta vốn nghĩ rằng, ngươi không xứng đáng để họ hy sinh như vậy. \nBây giờ xem ra, ta đã có suy nghĩ chủ quan từ trước."
  },
  AvgDialog_24093_Content_78 = {
    Text = "Bạn đang nói gì vậy? Nhanh lên, đi đi!"
  },
  AvgDialog_24093_Content_79 = {
    Text = "Muphí một tay đẩy tulô, một tay kéo Ramona, nhanh chóng biến mất trong đường đi sâu và tối của khoang tàu."
  },
  AvgDialog_24093_Content_8 = {
    Text = "Cô ấy không thể yên tĩnh để cầu nguyện, không thể yên tâm ngồi xuống."
  },
  AvgDialog_24093_Content_80 = {
    Text = "Đứa trẻ này… thôi thì, nếu đây là lựa chọn của cô ấy."
  },
  AvgDialog_24093_Content_81 = {
    Text = "Hilaster, duy trì toàn tốc tiến lên"
  },
  AvgDialog_24093_Content_9 = {
    Text = "Rầm—— !"
  },
  AvgDialog_24094_Content_1 = {
    Text = "Khi tâm trí của Miriam trở nên bất ổn, nhóm người dấn thân vào biển cũng dần mất đi trật tự, sự hỗn loạn bắt đầu lan rộng."
  },
  AvgDialog_24094_Content_2 = {
    Text = "Những người dấn thân vào biển đã nhận ra Muphí, người \"sinh ra\" thần minh, và gần như bản năng, họ lùi lại khi cô ấy đến gần. Các người đã chạy nhanh qua vòng vây của quái vật."
  },
  AvgDialog_24095_Content_1 = {
    Text = "Vung đuôi hất bay những người dấn thân vào biển vây quanh, tulô đi ở cuối đội, dọn dẹp phía sau cho các người."
  },
  AvgDialog_24095_Content_2 = {
    Text = "Những người dấn thân vào biển tuy kém thông minh, nhưng đến lúc này, bỗng trở nên do dự. \n Trong cụm bắt đầu thì thầm to nhỏ, ngôn ngữ cổ xưa và khó hiểu, nhưng Tulô lại vì thế mà cau chặt mày."
  },
  AvgDialog_24095_Content_3 = {
    Text = "Sự suy đoán của những kẻ liều lĩnh chỉ làm cho Miriam phẫn nộ."
  },
  AvgDialog_24095_Content_4 = {
    Text = "Suy đoán? Bạn có thể nghe hiểu những gì họ nói không?"
  },
  AvgDialog_24095_Content_5 = {
    Text = "Không có thời gian để giải thích cho tulô, Miriam đã dùng hành động để dịch trọn vẹn thứ ngôn ngữ cổ xưa này."
  },
  AvgDialog_24095_Content_6 = {
    Text = "Con dao găm lướt qua cổ họng của nhiều người dấn thân vào biển, cô tắm mình trong dòng máu xám xanh bắn ra, xuyên qua đám đông những người dấn thân vào biển."
  },
  AvgDialog_24095_Content_7 = {
    Text = "Vua Thần tái thế? Không… \nNgài chỉ sẽ giáng sinh vào thế gian khi các vì sao chính vị, thông qua nghi lễ dẫn dắt!"
  },
  AvgDialog_24095_Content_8 = {
    Text = "Chỉ có nghi lễ của tôi mới có thể làm cho Thần Vương tái sinh, để thần quốc tái lâm! Chỉ có tôi !"
  },
  AvgDialog_24095_Content_9 = {
    Text = "Người dấn thân vào biển…… Hãy để những kẻ xúc phạm tên của Chủ ta chứng kiến uy nghi của dòng máu thần quốc!"
  },
  AvgDialog_24096_Content_1 = {
    Text = "Ánh sáng thất lạc"
  },
  AvgDialog_24096_Content_10 = {
    Text = "Các chi bị vặn vẹo, biểu cảm trên khuôn mặt dưới cùng còn sót lại bị đóng băng trong khoảnh khắc cuối cùng trước khi chết. Dòng máu chảy ra đông cứng thành các ký tự khó hiểu, khiến không khí tràn ngập sự điên cuồng của cái chết."
  },
  AvgDialog_24096_Content_11 = {
    Text = "Thần minh của ngươi, có lẽ sẽ không thích thú với lễ hiến tế kinh hoàng như vậy đâu? \nSứ giả của họ mất tích ở đây, ngươi định giải thích thế nào với người của Hội Giáo đèn lồng?"
  },
  AvgDialog_24096_Content_12 = {
    Text = "Goliath chưa kịp dứt lời, vết sẹo trên cổ co thắt mạnh, siết chặt cơ cổ của anh ta."
  },
  AvgDialog_24096_Content_13 = {
    Text = "Đầu của ngươi được nhào nặn bằng máu Lemuria, không phải để ngươi thốt ra những lời ngạo mạn về thần minh của ta, Goliath."
  },
  AvgDialog_24096_Content_14 = {
    Text = "Chúa của tôi vĩ đại, toàn năng, Người có thể lấy lực lượng từ lời cầu nguyện của tôi và thấy lòng thành kính của tôi qua những hiến tế."
  },
  AvgDialog_24096_Content_15 = {
    Text = "Còn về hai sứ giả đèn lồng này... thất lễ, ngu xuẩn, đám rác rưởi không đáng kể. Nếu đèn lồng có điều gì oán trách, thì tôi cũng không cần phải tiếp tục đi cùng chúng nữa."
  },
  AvgDialog_24096_Content_16 = {
    Text = "Miriam lau đi máu trên ngón tay, cuối cùng quay đầu nhìn bạn. Trên người cô ấy toát ra một mùi thối nát không thể xua tan, mỗi bước tiến lại gần đều là sự tra tấn đối với tinh thần của bạn."
  },
  AvgDialog_24096_Content_17 = {
    Text = "Bạn đã... làm gì họ vậy?"
  },
  AvgDialog_24096_Content_18 = {
    Text = "Bạn và họ không giống nhau."
  },
  AvgDialog_24096_Content_19 = {
    Text = "Miriam không trả lời câu hỏi của bạn. Cô ấy nhìn bạn, đôi mắt như một hồ nước sâu thẳm, khó lay động, ẩn chứa những bí mật của nghìn năm lịch sử."
  },
  AvgDialog_24096_Content_2 = {
    Text = "Tàu hàng ngoài khơi · S.S. Sonanier \n phòng động lực"
  },
  AvgDialog_24096_Content_20 = {
    Text = "Bạn sở hữu linh hồn độc đáo nhất mà tôi đã thấy kể từ khi trở thành thân thể được đánh thức… rực rỡ và u ám hơn người đồng hành của bạn."
  },
  AvgDialog_24096_Content_21 = {
    Text = "Người giữ bí mật của Đại học Misaque… Đối với những người tài năng, tôi luôn mang lòng trân trọng và thương xót. Tôi chân thành mong rằng bạn sẽ được đón nhận ánh sáng thiêng liêng của Đấng Tối Cao."
  },
  AvgDialog_24096_Content_22 = {
    Text = "Người thông minh không nên bị chôn vùi trong cuộc sống tầm thường. Đất nước của thần linh dù được hình thành từ những mối quan hệ huyết thống phức tạp, nhưng vẫn sẵn lòng đón nhận dòng máu ngoại lai."
  },
  AvgDialog_24096_Content_23 = {
    Text = "Các ngươi hy vọng cứu thế giới khỏi sự ô uế, điều này không xung đột với <Blue:thần quốc tái lâm>."
  },
  AvgDialog_24096_Content_24 = {
    Text = "Hãy phục vụ ta, gia nhập vào sự tái lâm và phục hưng của thần quốc, đạt tới vinh quang rực rỡ nhất… như vậy, cả ngươi và ta đều có thể bước đi trên miền cực lạc."
  },
  AvgDialog_24096_Content_25 = {
    Text = "Nếu như sự tái lâm và phục hưng mà bạn nói đến, là dùng người sống làm lễ vật, dùng người vô tội làm vật chủ cho quái vật.."
  },
  AvgDialog_24096_Content_26 = {
    Text = "Xin lỗi, tôi không thể làm được. \nLễ nghi của bạn man rợ và tàn nhẫn, tôi không nhìn thấy chút dấu hiệu nào của sự lý trí hay văn minh."
  },
  AvgDialog_24096_Content_27 = {
    Text = "Có thể trở thành vật chủ trước khi tái sinh làm thần minh, có thể trở thành nền tảng cho sự tái lâm của thần quốc, đáng để cảm thấy vinh quang!"
  },
  AvgDialog_24096_Content_28 = {
    Text = "Lần này là do tôi nhìn lầm, không cần phải phí lời với người khờ… Cuộc hài kịch này nên kết thúc rồi."
  },
  AvgDialog_24096_Content_29 = {
    Text = "Lực lượng bùng nổ trong bóng tối, những khối năng lượng ẩn hiện ngưng tụ thành hình rắn khổng lồ và đặc quánh."
  },
  AvgDialog_24096_Content_3 = {
    Text = "Miriam đôi mắt khép hờ, thong thả đứng giữa căn phòng, như thể một pho tượng thiêng liêng. Dù Goliath có thô bạo ném bạn tới trước mặt, cô ấy chỉ nhẹ nhàng ngước lên, thoáng nhìn bạn một cái."
  },
  AvgDialog_24096_Content_30 = {
    Text = "Con rắn khổng lồ va chạm loạn xạ trong không gian, cuối cùng đôi mắt rắn khóa chặt vào bạn——con rắn quấn quanh eo bạn, dễ dàng nâng bổng bạn lên."
  },
  AvgDialog_24096_Content_31 = {
    Text = "Dừng lại, Miriam."
  },
  AvgDialog_24096_Content_32 = {Text = "Ai vậy!"},
  AvgDialog_24096_Content_33 = {
    Text = "Giọng nói quen thuộc vượt qua rãnh lịch sử, nhẹ nhàng như gió biển, nhưng đã khuấy động sóng lớn trong lòng."
  },
  AvgDialog_24096_Content_34 = {
    Text = "Miriam, người nói, buông học sinh đó ra."
  },
  AvgDialog_24096_Content_35 = {
    Text = "Cuộc trò hề này, thật sự nên kết thúc rồi."
  },
  AvgDialog_24096_Content_36 = {
    Text = "Tôi không nhớ mặt bạn, nhưng trên người bạn… có dấu vết của Đức Chúa của tôi."
  },
  AvgDialog_24096_Content_37 = {
    Text = "Mặt Miriam hiện lên một tia thương cảm, đôi mắt cô như những bông hoa bị cơn mưa điên loạn tàn phá, chứa đựng nỗi buồn và đau đớn khôn nguôi."
  },
  AvgDialog_24096_Content_38 = {
    Text = "Da rắn lạnh lẽo và trơn trượt trượt trên thân thể bạn, giống như đang siết chặt con mồi, thân thể của con rắn khổng lồ dần dần siết chặt lại."
  },
  AvgDialog_24096_Content_39 = {
    Text = "Nước mắt đã khắc lên khuôn mặt cô những dấu vết không thể xóa nhòa, đôi mắt cô nhìn chằm chằm vào Tulô, như muốn xuyên thấu linh hồn anh ta, nhìn thấu cả lịch sử hàng vạn năm của họ."
  },
  AvgDialog_24096_Content_4 = {
    Text = "Đôi mắt đó lạnh lùng như độc xà, toát lên sự tàn nhẫn và lạnh lùng, nhưng lại hoàn toàn loại bạn ra ngoài —— bạn không phải là đối thủ của cô ấy, cũng không thuộc về chuỗi thức ăn của cô ấy."
  },
  AvgDialog_24096_Content_40 = {
    Text = "<Blue:chủ thượng>…… tôi kính yêu <Blue:vua>……\nLàm sao ngài có thể… có hơi thở của thân thể thức tỉnh?"
  },
  AvgDialog_24096_Content_41 = {
    Text = "Ai đã làm ô uế di cốt của ngươi? Ai đã… làm ô uế lời hứa của chúng ta?"
  },
  AvgDialog_24096_Content_42 = {
    Text = "Bạn bị con rắn khổng lồ nâng bổng lên không trung, toàn bộ máu trong cơ thể chảy dồn về não, trước mắt dần dần tối sầm lại."
  },
  AvgDialog_24096_Content_43 = {
    Text = "Nhưng trong cơn hoảng hốt, bạn vẫn kịp nhìn thấy hai cô gái… Họ bị kẻ xuống biển bao vây, tại sao lại càng lúc càng gần?"
  },
  AvgDialog_24096_Content_44 = {
    Text = "Ramona! Bây giờ!"
  },
  AvgDialog_24096_Content_45 = {
    Text = "Ramona hít sâu một hơi, gập một chân, và nhảy lên cao bằng năng lượng tụ tập dưới chân ——"
  },
  AvgDialog_24096_Content_47 = {
    Text = "Đầu kiếm mảnh phá vỡ thể năng lượng hình vảy rắn, đâm vào bảy tấc của con rắn khổng lồ."
  },
  AvgDialog_24096_Content_48 = {
    Text = "Ê ê! Người sắp rơi xuống rồi!"
  },
  AvgDialog_24096_Content_49 = {
    Text = "Bạn cũng rơi trong tiếng gầm của thằn lằn khổng lồ."
  },
  AvgDialog_24096_Content_5 = {
    Text = "Còn những người khác đâu?"
  },
  AvgDialog_24096_Content_50 = {
    Text = "—— Rồi rơi vào một vòng tay ấm áp đang run rẩy."
  },
  AvgDialog_24096_Content_51 = {
    Text = "……bạn còn ổn không, %player%."
  },
  AvgDialog_24096_Content_52 = {
    Text = "Ramona… tôi…"
  },
  AvgDialog_24096_Content_53 = {
    Text = "Xin lỗi, bây giờ không phải là lúc để hồi tưởng."
  },
  AvgDialog_24096_Content_54 = {
    Text = "Ramona ôm bạn, không ngoảnh lại, lao đi về hướng xa rời Miriam."
  },
  AvgDialog_24096_Content_55 = {
    Text = "Bạn quay đầu nhìn về phía Miriam, dáng hình con rắn lại một lần nữa hiện ra, và ánh mắt của cô ấy cũng rơi lên bạn và Ramona."
  },
  AvgDialog_24096_Content_56 = {
    Text = "Giống như ánh mắt của loài rắn độc đang nhắm tới con mồi."
  },
  AvgDialog_24096_Content_57 = {
    Text = "Tulô! Đừng dây dưa với cô ấy, ưu tiên bảo vệ Muphí rời đi."
  },
  AvgDialog_24096_Content_6 = {
    Text = "Tôi không phải đã nói rồi sao? Chuột nhỏ của Misaque thích đào hang khắp nơi, có thể giữ được con này đã là rất khó rồi."
  },
  AvgDialog_24096_Content_7 = {
    Text = "Tuy nhiên, những người khác đã không còn quan trọng nữa, phải không? \nCó vẻ như bạn đã chuẩn bị sẵn bàn thờ cho \"thần minh\" rồi."
  },
  AvgDialog_24096_Content_8 = {
    Text = "Miriam từ từ quay người, bóng ma hình con rắn tan biến theo cử động của cô, khiến cô được bao phủ trong ánh sáng tím, trông giống như một tín đồ đang tham gia nghi lễ trang trọng."
  },
  AvgDialog_24096_Content_9 = {
    Text = "Nàng đứng sau bàn thờ, hình dạng của nó dần dần lộ ra, ánh sáng mờ tối từ phòng động lực chiếu lên khuôn mặt nàng tạo nên những bóng dáng kỳ lạ. Ở trung tâm bàn thờ, hai thân thể không thể nhận ra hình dạng ban đầu nằm yên lặng."
  },
  AvgDialog_24097_Content_10 = {
    Text = "Nói đến chuyện đó, cẳng chân bạn còn đau không? Hình như đã không còn chảy máu nữa rồi."
  },
  AvgDialog_24097_Content_11 = {
    Text = "Hầu như không còn cảm thấy đau nữa.."
  },
  AvgDialog_24097_Content_12 = {
    Text = "Trong khi các người đang nói về tương lai, ảo ảnh của Miriam tan ra như tuyết tan. \nKẻ thù dần lấy lại chút thần trí sau khi thoát khỏi trạng thái mất kiểm soát, đồng thời thoát khỏi hình dạng quái dị."
  },
  AvgDialog_24097_Content_13 = {
    Text = "Miriam nằm yếu đuối trong bụi đen, ánh mắt mờ nhạt và hư vô. Thậm chí khi tulô đến, cô ấy vẫn không có phản ứng gì."
  },
  AvgDialog_24097_Content_14 = {
    Text = "Đừng cố chấp nữa, Miriam."
  },
  AvgDialog_24097_Content_15 = {
    Text = "Thời đại của chúng ta, <Blue:quốc gia vĩnh cửu> của chúng ta, sự biến mất của nó là điều không thể tránh khỏi."
  },
  AvgDialog_24097_Content_16 = {
    Text = "Không... không... anh ta đã hứa với tôi.."
  },
  AvgDialog_24097_Content_17 = {
    Text = "<Yellow:bạn> đã hứa với tôi."
  },
  AvgDialog_24097_Content_18 = {
    Text = "Người phụ nữ gầy guộc cuối cùng đã có phản ứng, cô ấy ngẩng đầu lên ngẩn ngơ, miệng lẩm bẩm."
  },
  AvgDialog_24097_Content_19 = {
    Text = "Thần minh toàn năng của tôi sẽ thi hành quyền năng của Ngài… đưa ra phán quyết đối với những kẻ dị giáo đã tạo ra vật giả mạo, tội không thể tha thứ!"
  },
  AvgDialog_24097_Content_2 = {
    Text = "Những tòa nhà này đang biến mất, mọi thứ…… đã kết thúc rồi phải không?"
  },
  AvgDialog_24097_Content_20 = {
    Text = "Cô rút con dao găm từ thắt lưng, ngọn lửa tím đen như sương mù dày đặc bao phủ lưỡi dao, toả ra hơi chết chóc lạnh buốt."
  },
  AvgDialog_24097_Content_21 = {
    Text = "Hàng giả…… đi chết đi!"
  },
  AvgDialog_24097_Content_22 = {
    Text = "—— Ngọn lửa âm u và kỳ lạ trên lưỡi dao găm đã làm bùng cháy bụi than."
  },
  AvgDialog_24097_Content_23 = {
    Text = "<BigShake:Ya á!>"
  },
  AvgDialog_24097_Content_24 = {
    Text = "Trong chuỗi phản ứng giữa ngọn lửa và bụi, tiếng nổ vang rền bao trùm mọi người, và con tàu cũng nghiêng mạnh về một hướng trong nháy mắt."
  },
  AvgDialog_24097_Content_25 = {
    Text = "Trước mặt là ngọn lửa lan rộng với tốc độ khủng khiếp, sau lưng là bức tường cabin bị nổ thủng một lỗ lớn."
  },
  AvgDialog_24097_Content_26 = {
    Text = "Người giữ bí mật! Đừng buông tay tôi!"
  },
  AvgDialog_24097_Content_27 = {
    Text = "Mũi đầy mùi khét đắng ngắt của than đá cháy hết, găng tay chỉ kịp chạm nhau trong chớp mắt, trước khi một bên bị trọng lực kéo mạnh xuống hố sâu."
  },
  AvgDialog_24097_Content_28 = {
    Text = "Giọng nói quen thuộc và hơi ấm từ người đó đang nhanh chóng biến mất, ngược lại, sự ẩm ướt và lạnh lẽo dần dần xâm nhập vào lưng."
  },
  AvgDialog_24097_Content_29 = {
    Text = "Người Giữ Bí Mật!"
  },
  AvgDialog_24097_Content_3 = {
    Text = "Đây là ảo cảnh do Miriam tạo ra, có thể đây chính là <Blue:thần quốc> mà cô ấy đã từng nói…"
  },
  AvgDialog_24097_Content_30 = {
    Text = "Vào khoảnh khắc này, thời gian như ngừng trôi, làn sóng nhiệt độ bùng cháy tựa như hàng ngàn lưỡi dao sắc bén xé toạc da thịt, từng thớ gân đều bị thiêu đốt đến mức mỏng manh như giấy."
  },
  AvgDialog_24097_Content_31 = {
    Text = "Tiếng kèn hỗn loạn và chát chúa xuyên thủng lĩnh vực tinh thần, sự tỉnh táo và bình yên của năm qua bị đập tan. Trong khoảnh khắc vô tận này, bạn cảm nhận được sự bất an và đấu tranh trong hỗn loạn."
  },
  AvgDialog_24097_Content_32 = {
    Text = "Nhưng cuối cùng, vạn vật bị lửa dữ dội thiêu rụi, ý thức chìm vào trong bóng tối vô tận…"
  },
  AvgDialog_24097_Content_4 = {
    Text = "Quốc gia dưới sự cai trị của thần minh, vĩnh cửu Lemuria."
  },
  AvgDialog_24097_Content_5 = {
    Text = "\"Lemuria\"... tôi có ấn tượng, một số học giả thuộc khoa Lịch sử Misaque đang tranh cãi không ngừng về việc nó có thực sự tồn tại hay không."
  },
  AvgDialog_24097_Content_6 = {
    Text = "Nếu thảm họa không từng xảy ra, nó lẽ ra vẫn đứng sừng sững tại đây…"
  },
  AvgDialog_24097_Content_7 = {
    Text = "Vì chuyện đó đã trở thành lịch sử, liệu có thể đợi chúng ta an toàn hẳn rồi hãy nói về thành phố này không? Giải quyết cái này trước đi."
  },
  AvgDialog_24097_Content_8 = {
    Text = "Ramona, đợi thuyền cập bến, chúng ta rời thâm cảnh, liên lạc với trường và chuẩn bị. \nTulô, bạn ở lại trên thuyền tạm thời chăm sóc Muphí."
  },
  AvgDialog_24097_Content_9 = {
    Text = "Ừm, cần thông báo cho mọi người chuẩn bị phòng phẫu thuật đã được bố trí thời gian phù văn. Về ca phẫu thuật tách ký sinh vật, có lẽ Phó viện trưởng Khổ Lệ Đặc sẽ phải tự mình thực hiện."
  },
  AvgDialog_24260_Content_1 = {
    Text = "Thế mà lại phục hồi rồi…?! Phải chăng đòn tấn công của chúng ta hoàn toàn vô tác dụng sao?"
  },
  AvgDialog_24260_Content_2 = {
    Text = "Không… nhìn hai con rắn năng lượng khổng lồ kia, chúng có hơi thở của Miriam rất mạnh mẽ, có lẽ chúng ta cần phải đánh bại chúng trước…"
  },
  AvgDialog_24260_Content_3 = {
    Text = "Khi thần quốc vẫn tồn tại, cô chỉ có thể triệu hồi một bóng rắn. Sau hàng vạn năm ẩn náu, có lẽ giờ đây cô có thể kiểm soát tối đa <Yellow:tám> bóng của các sứ giả."
  },
  AvgDialog_24260_Content_4 = {
    Text = "Nghi lễ huyền bí không truyền của Lemuria... Không thể để cô ấy tiếp tục bị cơn giận dữxâm thực nữa, khi hoàn toàn mất kiểm soát, cô ấy sẽ trở thành một con quái vật thực sự."
  },
  AvgDialog_24261_Content_1 = {
    Text = "Bóng của những kẻ trung thành rõ ràng đã bị đánh tan hết rồi, tại sao cô ấy vẫn còn…!"
  },
  AvgDialog_24261_Content_2 = {
    Text = "Cô ấy muốn thực hiện nghi lễ một cách cưỡng bức, nhưng nơi đây chỉ là ảo cảnh của cô… Không có sự dẫn dắt của các vì sao, nghi lễ sẽ đốt cháy hoàn toàn linh hồn của tất cả mọi người."
  },
  AvgDialog_24261_Content_3 = {
    Text = "Chủ tế Miriam!Nhân danh @2 Đại hành giả, ta ra lệnh cho ngươi dừng lại!"
  },
  AvgDialog_24261_Content_4 = {
    Text = "Trí tuệ đã bị cơn giận dữ nuốt chửng, sinh vật kỳ dị từng được gọi là Miriam chỉ dừng lại trong chốc lát, rồi lại phát động tấn công điên cuồng."
  },
  AvgDialog_24261_Content_5 = {
    Text = "Cô ấy tin rằng Yu là kẻ giả mạo… Nếu vậy, Yu buộc phải dùng cách riêng của Lemuria để ứng phó. Thu phục cô ta, hoặc… loại bỏ cô ta."
  },
  AvgDialog_24261_Content_6 = {
    Text = "Miriam… thần tử trung thành nhất của ta…\nNguyện ngươi… không còn bối rối."
  },
  AvgDialog_24282_Content_1 = {
    Text = "Tiếp theo sẽ thử rung màn hình lần 2"
  },
  AvgDialog_24282_Content_2 = {
    Text = "Về lý thuyết, ảnh nhân vật cần rung lắc cùng với nền"
  },
  AvgDialog_24282_Content_3 = {
    Text = "Tiếp theo sẽ kiểm tra di chuyển ngang 2"
  },
  AvgDialog_24282_Content_4 = {
    Text = "Theo lý thuyết, hình vẽ phải dịch chuyển ngang cùng với nền"
  },
  AvgDialog_24282_Content_5 = {
    Text = "Kết thúc kiểm tra"
  },
  AvgDialog_24296_Content_1 = {
    Text = "Không được, người quá nhiều…… tiếp tục như vậy chỉ càng tồi tệ hơn……"
  },
  AvgDialog_24296_Content_10 = {
    Text = "Không, ngài Goliath—— !"
  },
  AvgDialog_24296_Content_11 = {
    Text = "Mọi thứ trước mắt dường như đã tạm ngừng hoạt động."
  },
  AvgDialog_24296_Content_12 = {
    Text = "Phản xạ tự nhiên của thân thể vượt khỏi tầm kiểm soát của bạn. Nó vọt tới, một cách tuyệt vọng chắn trước Goliath."
  },
  AvgDialog_24296_Content_13 = {Text = "Ừ——"},
  AvgDialog_24296_Content_14 = {
    Text = "Dao sắc cắt đứt cổ họng, bạn run rẩy che vết thương không ngừng chảy máu, đầu óc hỗn loạn."
  },
  AvgDialog_24296_Content_15 = {
    Text = "Bạn điên rồi sao, chạy đến đây làm gì?!!"
  },
  AvgDialog_24296_Content_16 = {
    Text = "Tôi không biết… thân thể, bất giác cử động…"
  },
  AvgDialog_24296_Content_17 = {
    Text = "Xin lỗi, ngài Goliath…"
  },
  AvgDialog_24296_Content_2 = {
    Text = "Ta……còn có thể tiếp tục……giết!"
  },
  AvgDialog_24296_Content_20 = {
    Text = "Mũi tên nhọn ngấm đầy độc dược xé toang không khí,đâm vào vai Goliath,khiến anh ta không thể kiểm soát được mà ngã về phía bạn."
  },
  AvgDialog_24296_Content_21 = {
    Text = "Goliath… Người khổng lồ đó, cuối cùng đã ngã xuống!"
  },
  AvgDialog_24296_Content_22 = {
    Text = "Đầu của hắn thuộc về tôi, ai cũng đừng hòng cướp!!!"
  },
  AvgDialog_24296_Content_23 = {
    Text = "Biển cả phát ra một tiếng rung động ầm ỉ, gã khổng lồ che khuất mặt trời rực rỡ trước mắt bạn và sụp đổ trong tiếng động lớn."
  },
  AvgDialog_24296_Content_24 = {
    Text = "Máu của các ngươi tụ lại một chỗ, nhuộm biển xanh thành màu đỏ tươi rực."
  },
  AvgDialog_24296_Content_25 = {
    Text = "Tiếng gió, tiếng sóng biển, cùng với tiếng reo hò và ẩu đả từ xa truyền đến. Kế tiếp, điều chờ đón các ngươi sẽ chỉ là cuộc tàn sát và sỉ nhục không dứt."
  },
  AvgDialog_24296_Content_26 = {
    Text = "Nước biển mặn chát xâm nhập vào vết thương ở cổ, khiến bạn đau đớn đến mức không ngừng hít thở."
  },
  AvgDialog_24296_Content_27 = {
    Text = "Goliath cũng chẳng khá hơn bạn là mấy."
  },
  AvgDialog_24296_Content_28 = {
    Text = "Thấy bạn như vậy, anh ta vẫn còn tâm trạng nở một nụ cười đầy ác ý."
  },
  AvgDialog_24296_Content_29 = {
    Text = "Tôi nói… anh thật nên đi soi gương, xem thử bộ dạng hài hước của mình bây giờ."
  },
  AvgDialog_24296_Content_3 = {
    Text = "Tiếng kèn trầm bổng không ngừng vang vọng trên mặt biển. Với phần thưởng hấp dẫn, các chiến binh tham gia liên tục vào cuộc đi săn này."
  },
  AvgDialog_24296_Content_30 = {
    Text = "Quả nhiên là một kẻ vô dụng."
  },
  AvgDialog_24296_Content_4 = {
    Text = "Goliath đã kiệt sức. Ông ta lại một lần nữa vung cây kiếm khổng lồ trong tay, nhưng lần này, động tác chậm chạp của ông ta đã bị đối phương khai thác sơ hở."
  },
  AvgDialog_24296_Content_6 = {
    Text = "Anh ta quỳ xuống đất, vết thương phơi bày xương trắng hếu, máu chảy như suối cạn kiệt."
  },
  AvgDialog_24296_Content_8 = {
    Text = "Chính là bây giờ, cùng một lúc hạ gục hắn!!"
  },
  AvgDialog_24296_Content_9 = {
    Text = "Các chiến binh vây quanh như những con cá mập khát máu la oà tới."
  },
  AvgDialog_24297_Content_1 = {Text = "Ư——!!"},
  AvgDialog_24297_Content_10 = {
    Text = "Dưới phần thưởng lớn, tất nhiên sẽ có người dũng cảm. Các chiến binh hào hứng reo hò, vũ khí va chạm tạo nên tiếng kim loại rung động đầy phấn khích."
  },
  AvgDialog_24297_Content_11 = {
    Text = "Đúng vậy, sợ, sợ gì chứ? Chúng ta có nhiều người như vậy!"
  },
  AvgDialog_24297_Content_12 = {
    Text = "Chặt đứt tay cầm dao của hắn!"
  },
  AvgDialog_24297_Content_13 = {
    Text = "Những chiến binh vốn co ro nay gầm thét, ùa tới như đàn châu chấu điên cuồng."
  },
  AvgDialog_24297_Content_14 = {
    Text = "He he… những người đồng tộc thân yêu nhất của tôi. Tôi đã dạy các ngươi cách chiến đấu, cách giết chóc, cách sinh tồn."
  },
  AvgDialog_24297_Content_15 = {
    Text = "Nhưng tôi chưa bao giờ dạy các ngươi, khi đối mặt với kẻ thù mạnh gấp nhiều lần, cách để giữ mạng."
  },
  AvgDialog_24297_Content_16 = {
    Text = "Goliath liếm máu trên khóe miệng, lộ ra những chiếc răng nanh."
  },
  AvgDialog_24297_Content_17 = {
    Text = "… vì các bạn đã không còn đường lui."
  },
  AvgDialog_24297_Content_18 = {
    Text = "Nói xong, hắn tùy tay bóp chặt cổ họng của hai người, nhấc đầu họ lên và đập mạnh vào nhau——"
  },
  AvgDialog_24297_Content_19 = {Text = "Rầm!!"},
  AvgDialog_24297_Content_2 = {
    Text = "Con dao lớn vung lên điên cuồng đã chém con tàu thành từng mảnh, Glen chỉ còn một chân, cố gắng lê mình về góc tàu."
  },
  AvgDialog_24297_Content_20 = {
    Text = "Dòng chất lỏng và rắn màu vàng trắng lẫn máu vỡ vụn phun trào ra, Goliath cười sằng sặc, trong còng kinh bùng lên ác ý khát máu."
  },
  AvgDialog_24297_Content_21 = {
    Text = "Ha ha ha! Nghe nói có người muốn lấy đầu ta?"
  },
  AvgDialog_24297_Content_22 = {
    Text = "Có bản lĩnh thì hãy xếp hàng, từng người một đến lấy!"
  },
  AvgDialog_24297_Content_3 = {
    Text = "<Shake:Chẳng phải bạn đã bị thương sao, sao lại...>"
  },
  AvgDialog_24297_Content_4 = {
    Text = "Thật ngại quá, để đối phó với những kẻ như ngươi, ta hoàn toàn không cần dùng hết sức."
  },
  AvgDialog_24297_Content_5 = {
    Text = "Goliath đứng kiêu hãnh ở mũi tàu, kiếm khổng lồ vẽ nên một đường vạch cong trước người, tách biệt những đồng bào cũ ở bên ngoài."
  },
  AvgDialog_24297_Content_6 = {
    Text = "Còn ai lên đây chơi với tao không? Một mình thì giết gì cho đã!"
  },
  AvgDialog_24297_Content_7 = {
    Text = "Sợ hãi trước sức ép khủng khiếp của người khổng lồ, các chiến binh co rúm lại như những con sói con, không ai dám bước vào vùng cấm trước mặt, giống như đó là nơi cấm kỵ không được phép đụng đến."
  },
  AvgDialog_24297_Content_8 = {
    Text = "Một đám vô dụng! Anh ta bị thương nặng như vậy, đã không còn là bá chủ trên biển như xưa nữa rồi."
  },
  AvgDialog_24297_Content_9 = {
    Text = "Tôi, chiến binh Glen thề bằng mạng sống, chỉ cần có thể lấy được đầu của gã này, tài sản, đất đai và phụ nữ của tôi sẽ thuộc về anh ta!"
  },
  AvgDialog_24415_Content_1 = {
    Text = "Khoan đã, Ramona!"
  },
  AvgDialog_24415_Content_10 = {
    Text = "Tiểu thư Ramona!"
  },
  AvgDialog_24415_Content_11 = {
    Text = "Từ góc nhìn của cậu chỉ có thể thấy, Ramona dường như hơi nghiêng đầu nói điều gì đó, còn Ogier thì mặt tái nhợt, đỡ Doer lùi lại hai bước."
  },
  AvgDialog_24415_Content_12 = {
    Text = "Ramona rũ chất dịch đen trên mũi kiếm, mặt không biểu cảm bước nhanh về phía tháp chuông."
  },
  AvgDialog_24415_Content_13 = {
    Text = "Ramona, đợi đã!"
  },
  AvgDialog_24415_Content_14 = {
    Text = "Đây không phải ký ức."
  },
  AvgDialog_24415_Content_15 = {
    Text = "Đây thậm chí không phải Ramona mà cậu biết."
  },
  AvgDialog_24415_Content_16 = {
    Text = "Lạnh nhạt, lạnh lùng, khiến người ta khiếp sợ—— đồng đội của cậu không phải như vậy."
  },
  AvgDialog_24415_Content_17 = {
    Text = "Cô ấy sẽ không bước qua thi thể của đồng đội cũ, không ra tay giết Rotan, cũng không……phớt lờ tiếng gọi của cậu."
  },
  AvgDialog_24415_Content_18 = {
    Text = "Ramona, Ramona!"
  },
  AvgDialog_24415_Content_19 = {
    Text = "Bóng dáng cô ấy dần xa đi, cậu không kịp nghĩ ngợi gì khác, chỉ có thể bước nhanh đuổi theo."
  },
  AvgDialog_24415_Content_3 = {
    Text = "Trên quảng trường trường học, Rotan mất kiểm soát đang điên cuồng giết chóc.\nOgier cố hết sức che chở cho Doer, trông chừng sắp không chống đỡ nổi nữa."
  },
  AvgDialog_24415_Content_4 = {
    Text = "Chưa kịp đợi cậu đuổi kịp, Ramona đã giơ thanh kiếm mảnh, không chút nương tay đâm thẳng vào mặt Rotan."
  },
  AvgDialog_24415_Content_5 = {
    Text = "Ramona, nguy——"
  },
  AvgDialog_24415_Content_6 = {
    Text = "Khi thanh kiếm mảnh tiến gần trán Rotan, một khoảng trống xuất hiện tại nơi mũi kiếm chỉ tới, gương mặt hung tợn của Rotan có một khoảnh khắc trống rỗng."
  },
  AvgDialog_24415_Content_7 = {
    Text = "Giây tiếp theo, kiếm hoa lóe lên, lõi bạc của Rotan vỡ tan tành."
  },
  AvgDialog_24415_Content_8 = {
    Text = "Không……có thể……"
  },
  AvgDialog_24415_Content_9 = {
    Text = "Thanh kiếm mảnh lạnh lùng rút ra, đường kiếm sắc lạnh vạch ra suýt chút nữa cắt trúng Ogier đứng bên cạnh."
  },
  AvgDialog_24422_Content_1 = {
    Text = "<Gray:Tiền bối đã mất, nghĩa trang trường… Đây chắc hẳn là ký ức của Ramona về ngày Lễ Trao Chìa Khóa.>"
  },
  AvgDialog_24422_Content_2 = {
    Text = "<Gray:Nhưng tôi nhớ, lúc đó…>"
  },
  AvgDialog_24422_Content_3 = {
    Text = "Cảm ơn cậu, Người Giữ Bí Mật, cậu lại cứu tôi thêm một lần nữa.\nNếu không có liên kết này, có lẽ giờ tôi đã ngàn cân treo sợi tóc rồi."
  },
  AvgDialog_24422_Content_4 = {
    Text = "Kéo dài thêm sẽ bất lợi cho chúng ta, phải đánh nhanh thắng nhanh."
  },
  AvgDialog_24422_Content_5 = {
    Text = "Hừ, xin lỗi, giờ không có thời gian chờ cậu thích nghi nữa đâu."
  },
  AvgDialog_24422_Content_6 = {
    Text = "<Gray:Đây rốt cuộc là ký ức của ai? Ramona đó, thực ra……>"
  },
  AvgDialog_24422_Content_7 = {
    Text = "<Gray:Không được, phải nhanh chóng đuổi theo cô ấy.>"
  },
  AvgDialog_25177_Content_1 = {
    Text = "Trạng thái của Tavi đã hồi phục?! Sao có thể như vậy?"
  },
  AvgDialog_25177_Content_2 = {
    Text = "Trong ký ức của ta về trận chiến này, Ngài chưa từng thể hiện năng lực như thế."
  },
  AvgDialog_25177_Content_3 = {
    Text = "Không có……thực sự không có."
  },
  AvgDialog_25177_Content_4 = {
    Text = "Hay nói đúng hơn, chưa từng có bao giờ."
  },
  AvgDialog_25177_Content_5 = {
    Text = "Ramona cúi đầu nhìn chiếc chìa khóa bạc trước ngực ngươi, lẩm bẩm."
  },
  AvgDialog_25177_Content_6 = {
    Text = "Biến số duy nhất……hóa ra……"
  },
  AvgDialog_25177_Content_7 = {
    Text = "Ramona thu lại vẻ kinh ngạc, một lần nữa giơ kiếm chĩa về phía Tavi."
  },
  AvgDialog_25177_Content_8 = {
    Text = "Tiếp tục ra chỉ thị, kết thúc tất cả đi……\nNgười Giữ Bí Mật."
  },
  AvgDialog_25186_Content_1 = {
    Text = "Người Thổi Sáo"
  },
  AvgDialog_25186_Content_10 = {
    Text = "Đừng sợ, ta sẽ tìm cách đưa các người rời khỏi đây."
  },
  AvgDialog_25186_Content_11 = {
    Text = "Dân làng chỉ im lặng nhìn ngươi, ánh mắt không có hy vọng, cũng không có thù địch."
  },
  AvgDialog_25186_Content_12 = {
    Text = "Đúng rồi, thị nữ kia……"
  },
  AvgDialog_25186_Content_13 = {
    Text = "Cha và em trai tôi đều bị giam Bên Dưới. Tôi phải cứu họ—"
  },
  AvgDialog_25186_Content_14 = {
    Text = "Xin hỏi, các người có quen một nữ hầu tên Susanna không?"
  },
  AvgDialog_25186_Content_15 = {
    Text = "Susanna, là chị gái đó!"
  },
  AvgDialog_25186_Content_16 = {
    Text = "Từ góc phòng vang lên giọng trẻ con trong trẻo."
  },
  AvgDialog_25186_Content_17 = {
    Text = "Nhờ ánh nến lờ mờ, ngươi mới chú ý đến ông lão nằm ở góc phòng và cậu bé mắt tròn xoe bên cạnh."
  },
  AvgDialog_25186_Content_18 = {
    Text = "Susanna là con gái tôi…… cô ấy sao rồi?"
  },
  AvgDialog_25186_Content_19 = {
    Text = "Cô ấy rất lo lắng cho sự an nguy của các người, muốn cứu các người ra ngoài."
  },
  AvgDialog_25186_Content_2 = {
    Text = "Lâu đài Cambrian\nNgục ngầm"
  },
  AvgDialog_25186_Content_20 = {
    Text = "Chúng tôi không thể rời khỏi đây……"
  },
  AvgDialog_25186_Content_21 = {
    Text = "Trên người ông lão chi chít những lỗ hổng bị dung thực, chất nhầy từ đó tuôn ra đã nhuộm đen lớp rơm khô bên dưới từ lâu."
  },
  AvgDialog_25186_Content_22 = {
    Text = "Chúng tôi tự nguyện ở lại đây. Sau khi mắc bệnh, người ta sẽ phát điên, rồi biến thành quái vật."
  },
  AvgDialog_25186_Content_23 = {
    Text = "Đúng vậy, gần đây đã xảy ra rất nhiều vụ giết người…… sau đó phu nhân đã dẫn người đi kiểm tra từng nhà, giam tất cả những ai bị bệnh vào đây."
  },
  AvgDialog_25186_Content_24 = {
    Text = "Nếu không muốn bị giam, thì phải rời khỏi lãnh địa, thề sẽ không bao giờ quay lại."
  },
  AvgDialog_25186_Content_25 = {
    Text = "Ở đây mỗi ngày đều được uống cháo, ăn bánh mì ngọt nữa đấy!"
  },
  AvgDialog_25186_Content_26 = {
    Text = "<Gray:Thì ra là vậy. Chẳng lẽ chúng ta đã hiểu lầm bà ấy?>"
  },
  AvgDialog_25186_Content_27 = {
    Text = "Phu nhân Wanda sau khi đến lãnh địa, đối xử tốt với các người chứ?"
  },
  AvgDialog_25186_Content_28 = {
    Text = "Tốt ư? Tôi không biết. Tôi thậm chí chưa từng gặp bà ấy, chỉ nghe nói bà ấy rất tàn nhẫn, khắc chết bốn đời chồng, là hiện thân của ác quỷ."
  },
  AvgDialog_25186_Content_29 = {
    Text = "Nhưng những năm bà ấy ở lãnh địa, đã làm rất nhiều việc tốt, cuộc sống của chúng tôi quả thực khá hơn trước rất nhiều."
  },
  AvgDialog_25186_Content_3 = {
    Text = "Cánh cửa sắt nặng nề đóng lại sau lưng ngươi."
  },
  AvgDialog_25186_Content_30 = {
    Text = "Bà ấy dạy chúng tôi khai hoang đất nông nghiệp, chăn cừu, rồi vào dịp lễ hội hàng năm, mang len đến <Blue:Sharich> đi chợ, kiếm được một khoản lớn đấy."
  },
  AvgDialog_25186_Content_31 = {
    Text = "Đúng vậy, chợ Sharich còn là do bà ấy giành được từ tay Bá tước Goodrich, hai bên vì nó đã đánh nhau gần một năm rồi……"
  },
  AvgDialog_25186_Content_32 = {
    Text = "Dân làng tranh nhau kể cho ngươi nghe những giai thoại về việc Wanda quản lý lãnh địa. Canh tác, chăn nuôi, luyện kim, quản trị trang viên……"
  },
  AvgDialog_25186_Content_33 = {
    Text = "Bạn ngạc nhiên trước sự hiểu biết và am tường sâu sắc của Wanda về các công việc trong lãnh địa, bà tuyệt nhiên không phải loại lãnh chúa chỉ biết hưởng lạc."
  },
  AvgDialog_25186_Content_34 = {
    Text = "Là một lãnh chúa không tồi, tiếc là lại gặp phải Dung Thực."
  },
  AvgDialog_25186_Content_35 = {
    Text = "<Gray:Lan rộng với quy mô lớn như thế này, gần đây e rằng có khe nứt Dung Thực……>"
  },
  AvgDialog_25186_Content_36 = {
    Text = "Cánh cửa sắt phía sau bất ngờ mở ra."
  },
  AvgDialog_25186_Content_37 = {
    Text = "Không biết từ lúc nào Wanda đã đứng bên ngoài cửa ngục, ánh nến phủ lên đường viền của bà một lớp ánh sáng cam ấm áp."
  },
  AvgDialog_25186_Content_38 = {
    Text = "Thả hắn ra, ta có chuyện muốn nói riêng với hắn."
  },
  AvgDialog_25186_Content_39 = {
    Text = "Lâu đài Cambrian\nHoa viên"
  },
  AvgDialog_25186_Content_4 = {
    Text = "Ngươi quay người lại, bất ngờ bắt gặp từng đôi mắt sáng lên, trong bóng tối như dã thú vây quanh ngươi."
  },
  AvgDialog_25186_Content_40 = {
    Text = "Hai người cùng dạo bước trên thảm cỏ mềm mại, đi mãi đến tận bờ hồ."
  },
  AvgDialog_25186_Content_41 = {
    Text = "Mặt hồ đêm khuya như một tấm gương đen thẫm, trên đó phản chiếu lờ mờ ánh trăng vỡ vụn."
  },
  AvgDialog_25186_Content_42 = {
    Text = "Ta nghĩ ngươi cũng hiểu, Cambrian hiện đang bùng phát thảm họa rất nghiêm trọng, ta hoàn toàn bất lực trước chuyện này."
  },
  AvgDialog_25186_Content_43 = {
    Text = "Còn ngươi, khi giao chiến với đám quái vật trong lâu đài, ngươi tỏ ra rất thành thạo, trông giống như một tay lão luyện vậy."
  },
  AvgDialog_25186_Content_44 = {
    Text = "<Gray:Dù gì đây cũng là nghề của tôi……>"
  },
  AvgDialog_25186_Content_45 = {
    Text = "Phu nhân lúc đó chẳng phải đang ở trong tẩm cung sao, sao lại biết rõ ràng đến vậy?"
  },
  AvgDialog_25186_Content_46 = {
    Text = "Tai mắt của ta có khắp Cambrian, hoa tiểu thương lan ở đây muốn nở cũng phải được ta cho phép, không có chuyện gì ta không biết."
  },
  AvgDialog_25186_Content_47 = {
    Text = "Còn con thị nữ đó thì sao? Biết rõ nó là gián điệp, sao vẫn giữ nó lại?"
