  AvgDialog_25186_Content_63 = {
    Text = "Đôi khi ta có những ảo giác tuyệt đẹp…… cứ như từ bóng phản chiếu của hồ nước này, có thể nhìn thấy thành phố nơi ta từng sinh sống."
