  AvgDialog_25186_Content_70 = {
    Text = "Sau đó hành tinh của ta xảy ra thảm họa mà các ngươi gọi là \"Dung Thực\", tất cả mọi người đều chết."
  },
  AvgDialog_25186_Content_71 = {
    Text = "Ta một mình ngồi trong đại sảnh rất lâu, rất lâu, nhìn cung điện của ta, đô thành của ta, tất cả của ta đều biến thành phế tích."
  },
  AvgDialog_25186_Content_72 = {
