  AvgDialog_25190_Content_11 = {
    Text = "<Gray:Cùng bàn đại sự? Đại sự gì?>"
  },
  AvgDialog_25190_Content_12 = {
    Text = "Con thú cưng nhỏ của ta bảo rằng, ngươi có vẻ là một gián điệp đấy. Thân là tu sĩ do giáo khu phái đến, mà ngay cả kinh văn cơ bản cũng không nhớ nổi."
  },
  AvgDialog_25190_Content_13 = {
    Text = "Chẳng lẽ thật sự bị tên thị tùng đó nói trúng, ta thực sự là gián điệp sao?"
  },
  AvgDialog_25190_Content_14 = {
    Text = "Thông tin quan trọng thế này mà ta lại không nắm bắt được từ ký ức của hắn…… Xem ra quả thật đã bị tra tấn đến mất hết thần trí rồi."
  },
  AvgDialog_25190_Content_15 = {
    Text = "Bạn cất mảnh giấy đi, trong lòng vạn mối tơ vò."
  },
  AvgDialog_25190_Content_16 = {
    Text = "Đứng ngẩn ra làm gì? Phu nhân chẳng có kiên nhẫn đâu, người trước đến muộn giờ đã bị nhốt trong ngục hai năm rồi."
  },
  AvgDialog_25190_Content_17 = {
    Text = "……Này."
  },
  AvgDialog_25190_Content_18 = {
    Text = "Bạn lén lại gần nữ hầu, cố gắng hạ giọng thấp nhất có thể."
  },
  AvgDialog_25190_Content_19 = {
    Text = "<SmallShake:Ngươi cũng là nội gián của Bá tước Guderian sao?>"
  },
  AvgDialog_25190_Content_2 = {
    Text = "Bạn dễ dàng đẩy lùi lũ quái vật tấn công."
