  AvgDialog_25190_Content_20 = {
    Text = "Khục khục! Lẩm bẩm cái gì, còn không mau đi!"
  },
  AvgDialog_25190_Content_21 = {
    Text = "Nữ hầu miệng thì lầm bầm chửi rủa, nhưng không ngừng liếc mắt nhìn về phía bạn, trên mặt đầy vẻ nhiệt thành và ám thị."
  },
  AvgDialog_25190_Content_22 = {
    Text = "<Gray:Thưa cô, cô thể hiện hơi quá rõ ràng rồi đấy.>"
  },
  AvgDialog_25190_Content_23 = {
    Text = "Tiếp theo nên làm gì? Hoàn thành kế hoạch của chủ nhân cũ, hay quy thuận Wanda?"
  },
  AvgDialog_25190_Content_24 = {
    Text = "<Gray:Nói thật, ta khá tò mò kế hoạch của vị Bá tước đó rốt cuộc là gì…>"
