  },
  AvgDialog_34830_Content_36 = {
    Text = "Cánh cửa sắt phía sau bất ngờ mở ra."
  },
  AvgDialog_34830_Content_37 = {
    Text = "Bạn quay người lại, Vanda không biết từ bao giờ đã đứng bên ngoài cửa nhà tù. Ánh nến trong hành lang bị dáng người cao quý của cô che khuất, tạo nên một lớp ánh sáng cam ấm áp bao quanh đường nét của cô."
  },
  AvgDialog_34830_Content_38 = {
    Text = "Đưa thằng này ra, tôi có chuyện muốn nói riêng với {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_34830_Content_39 = {
    Text = "Lâu đài Cambrian\nHoa viên"
  },
  AvgDialog_34830_Content_4 = {
    Text = "Bạn quay người lại, đột ngột đụng phải những đôi mắt sáng rực, trong bóng tối mịt mùng như những con thú đang vây chặt bạn."
  },
  AvgDialog_34830_Content_40 = {
    Text = "Hai người cùng dạo bước trên thảm cỏ mềm mại, đi mãi đến tận bờ hồ."
  },
  AvgDialog_34830_Content_41 = {
