  AvgDialog_34830_Content_66 = {
    Text = "Lúc đó, ta có một cung điện rất lớn, riêng số tùy tùng hầu hạ ta đã lên đến hàng nghìn người."
  },
  AvgDialog_34830_Content_67 = {
    Text = "Như cậu nói, tôi chưa bao giờ quan tâm đến sự sống chết của những đầy tớ của mình."
  },
  AvgDialog_34830_Content_68 = {
    Text = "Ta luôn làm theo ý mình. Tùy tùng của ta, thậm chí cả thành phố, đều là sự mở rộng của dục vọng và tham vọng của ta."
  },
  AvgDialog_34830_Content_69 = {
    Text = "Sau đó hành tinh của ta xảy ra thảm họa mà các ngươi gọi là \"Dung Thực\", tất cả mọi người đều chết."
  },
  AvgDialog_34830_Content_7 = {
    Text = "Người ngồi, người nằm, người dựa tường đứng…… toàn là dân làng quần áo rách rưới."
  },
  AvgDialog_34830_Content_70 = {
    Text = "Ta một mình ngồi trong đại sảnh rất lâu, rất lâu, nhìn cung điện của ta, đô thành của ta, tất cả của ta đều biến thành phế tích."
  },
  AvgDialog_34830_Content_71 = {
    Text = "Nói thật, cảm giác đó rất tồi tệ, không ai muốn trải qua lần thứ hai."
  },
  AvgDialog_34830_Content_72 = {
    Text = "Bà Vanda…"
  },
  AvgDialog_34830_Content_73 = {
    Text = "Xin lỗi, lần này tôi không thể giúp bạn. Việc đóng rã nứt là một quá trình rất phức tạp, chỉ dựa vào mình tôi e rằng khó có thể thực hiện được."
  },
  AvgDialog_34830_Content_74 = {
    Text = "Không cần lo lắng, hãy nói cho ta nghe những băn khoăn của ngươi, ta sẽ cung cấp mọi sự giúp đỡ cần thiết."
  },
  AvgDialog_34830_Content_75 = {
    Text = "Bạn lắc đầu."
  },
  AvgDialog_34830_Content_76 = {
    Text = "Không chỉ là chuyện đó…… Hoàn cảnh mà chúng ta đang ở hiện tại, cũng có một số, ừm, điều đặc biệt……"
  },
  AvgDialog_34830_Content_77 = {
    Text = "Khi đang mơ, bạn không thể thực hiện các thao tác phức tạp như niêm phong khe nứt."
  },
  AvgDialog_34830_Content_78 = {
    Text = "<Gray:Phải giải thích chuyện này với phu nhân Wanda thế nào đây……>"
