  AvgDialog_34830_Content_90 = {
    Text = "<Change>Phu nhân…"
  },
  AvgDialog_34830_Content_91 = {
    Text = "Cambrian là quê hương thứ hai của ta. Ta ở bên nó chẳng được bao lâu, không ngờ lại đến lúc phải nói lời tạm biệt."
