  },
  AvgDialog_34830_Content_94 = {
    Text = "Yên tâm đi. Đã làm lãnh chúa của vùng đất phong, ta phải chịu trách nhiệm với mọi người."
  },
  AvgDialog_34830_Content_95 = {
    Text = "Chẳng qua là cùng nhau đi vào cõi chết thôi mà? Vậy thì cùng nhau chết cho thật thoải mái!"
