  AvgDialog_34830_Content_98 = {
    Text = "Một bữa tiệc chia ly huy hoàng."
  },
  AvgDialog_34831_Content_1 = {
    Text = "Cuối cùng ngươi cũng thoát khỏi sự quấy rầy của tiểu Beckman, nhưng dân làng vẫn đang liên tục phát sinh dị biến."
  },
  AvgDialog_34831_Content_10 = {
    Text = "Nếu chúng ta chắc chắn phải đón nhận cái chết, thì tại sao không thể vui vẻ mà ra đi?"
  },
  AvgDialog_34831_Content_11 = {
    Text = "Hay là chúng ta nên cuộn tròn trên giường và khóc trong cô đơn, để thỏa mãn mọi ý nghĩ của bạn về người sắp chết?"
