  AvgDialog_34831_Content_12 = {
    Text = "Ta đã nói rồi, ở Cambrian, ta chính là toàn bộ luật pháp."
  },
  AvgDialog_34831_Content_13 = {
    Text = "Bây giờ nữ hoàng ra lệnh, hãy nhảy múa, tiếp tục nhảy múa! Quá khứ, hiện tại, tương lai, chúng ta không hề run sợ trước cái chết."
