  AvgDialog_34831_Content_19 = {
    Text = "Điên rồi…… tất cả đều điên rồi……"
  },
  AvgDialog_34831_Content_2 = {
    Text = "Phòng tiệc còn một khoảnh khắc trước đó vô cùng vui vẻ nay đã biến thành một nghĩa trang lớn, dòng dung dịch ăn mòn rỗng rỗng không ngừng tràn ra giống như những con sâu bọ dày đặc dưới chiếc áo choàng hoa lệ."
  },
  AvgDialog_34831_Content_20 = {
    Text = "Ngươi ngơ ngác nhìn tất cả những gì đang diễn ra trước mắt. Ngay cả trong giấc mơ điên cuồng nhất, ngươi cũng chưa bao giờ thấy cảnh tượng kỳ dị đến vậy."
  },
  AvgDialog_34831_Content_21 = {
    Text = "Tất cả mọi người đều điên. Tất cả mọi người đều đầy thương tích."
  },
  AvgDialog_34831_Content_22 = {
    Text = "Nhưng tất cả mọi người đều rất hạnh phúc."
  },
  AvgDialog_34831_Content_24 = {
    Text = "Thế thì thôi, tôi đầu hàng."
  },
  AvgDialog_34831_Content_25 = {
    Text = "Bạn kéo cổ áo ra, mệt mỏi ngồi phịch xuống đất."
  },
  AvgDialog_34831_Content_26 = {
    Text = "Thật mỉa mai. Tôi đã từng thề không sợ chết trước mộ của Misaque, nhưng chưa bao giờ thực sự sẵn sàng đối mặt với cái chết."
