  AvgDialog_34831_Content_27 = {
    Text = "Bạn đã dạy tôi một bài học, Vanda."
  },
  AvgDialog_34831_Content_28 = {
    Text = "Bạn nâng ly rượu bên cạnh, cách Wanda qua lớp chất nhầy đen kịt, rượu vang đỏ bắn tung tóe và hoa tươi, cùng nhau nâng ly chúc mừng từ xa."
  },
  AvgDialog_34831_Content_29 = {
