  AvgDialog_34968_Content_52 = {
    Text = "Ramona tùy chỉnh cấu trúc của thiết bị liên lạc, không lâu sau, cô đã sử dụng chiếc ghim lớn đơn giản để phá vỡ lớp bảo vệ cuối của lõi năng lượng."
