  },
  AvgDialog_34968_Content_84 = {
    Text = "Khi đại hồng thủy xảy ra, tại lục địa mới đã xuất hiện báo cáo về việc nhìn thấy. \nMột nhóm người tị nạn \"xấu xí như cá\"đã băng qua biển và biến mất trong dòng lũ."
