  AvgDialog_34968_Content_85 = {
    Text = "Theo truyền thuyết, họ tự xưng là những người thừa kế của nền văn minh cổ đại, trong người chảy dòng máu được \"thần minh\" ban tặng."
  },
  AvgDialog_34968_Content_86 = {
    Text = "Những người này khi sinh ra đều có hình dạng con người, là máu thần khiến họ dần dần biến đổi thành hình dạng mà các bạn thấy."
  },
  AvgDialog_34968_Content_87 = {
