  AvgDialog_35536_Content_21 = {
    Text = "\"Misaque Người Giữ Gìn hy sinh bản thân vì người khác, đặt mình vào tình huống nguy hiểm, bị thương nặng, mất ý thức và không tỉnh lại.\""
