  AvgDialog_35828_Content_28 = {
    Text = "Muphí vô thức nhìn sang Người Giữ Gìn, người sau đang nháy mắt với cô, rõ ràng là không muốn để cô nói thật."
  },
  AvgDialog_35828_Content_29 = {
    Text = "Cô nhắm mắt lại, cố gắng hồi tưởng lại cảnh tượng mà Người Giữ Gìn đã kể với cô về Đại học Misaque. Tuy nhiên, mọi thứ đều như dòng nước, bức tranh vừa mới phác họa xong đã trôi mất không còn dấu vết."
