  AvgDialog_35828_Content_46 = {
    Text = "Chẳng phải đã hứa... sẽ không bỏ rơi tôi sao?"
  },
  AvgDialog_35828_Content_47 = {
    Text = "Bạn vừa suýt chút nữa thì \"mất kiểm soát\", phải không? Chẳng lẽ có chuyện gì xảy ra với học sinh sao?"
