  AvgDialog_35828_Content_49 = {
    Text = "……không sao. Goliath đã bắt cóc Muphí, Người Giữ Gìn chắc chắn sẽ sớm chìm vào trận chiến khó khăn, {Male=anh ấy,Female=cô ấy} cần sự giúp đỡ của Dư."
  },
  AvgDialog_35828_Content_5 = {
    Text = "Người giữ bí mật, đừng trêu cô ấy nữa. \nHãy yên tâm, cô Hilaster đã giành thời gian cho bạn, chúng ta sẽ bình an trở lại Lentiennam."
