  AvgDialog_35984_Content_62 = {
    Text = "Mái nhà bảo tàng tượng sáp bỗng dưng bị xé toạc một lỗ lớn, thứ gì đó nặng nề đập mạnh xuống người George, ép nó thành một đống thịt nhầy."
  },
  AvgDialog_35984_Content_63 = {Text = "A wuu!!"},
  AvgDialog_35984_Content_64 = {
    Text = "Chưa kịp nói ra một câu hoàn chỉnh, George đã không còn phát ra tiếng nào nữa."
  },
  AvgDialog_35984_Content_65 = {
    Text = "Khục khục……cái gì thế, mông dính nhớp nháp……"
  },
  AvgDialog_35984_Content_66 = {
    Text = "Ơ, tôi không phải đã quay về rồi sao? Sao lại đến bảo tàng tượng sáp thế này?"
  },
  AvgDialog_35984_Content_67 = {
    Text = "%player%{Male=ngài,Female=cô}, ngài không sao chứ?"
  },
  AvgDialog_35984_Content_68 = {
    Text = "Cô Mason, sao cô cũng ở đây?! Chẳng lẽ tôi vẫn chưa thoát khỏi mật cảnh……"
  },
  AvgDialog_35984_Content_69 = {
    Text = "Ahhh! Từ, từ trên trời rơi xuống……"
  },
  AvgDialog_35984_Content_7 = {
    Text = "<Big:tôi！>"
  },
  AvgDialog_35984_Content_70 = {
    Text = "Geo, George?"
  },
  AvgDialog_35984_Content_71 = {
    Text = "Rogers kinh ngạc nhìn George dưới mông bạn đã biến dạng hoàn toàn, trong mắt dâng lên nỗi phẫn nộ và bi thương vô tận."
  },
  AvgDialog_35984_Content_72 = {
    Text = "Pandiya……bắt, bắt lấy chúng!"
  },
  AvgDialog_35984_Content_8 = {
    Text = "Tsk tsk, có người ở với nô lệ ma cà rồng lâu rồi, cũng học được cách hát luôn rồi."
  },
  AvgDialog_35984_Content_9 = {
    Text = "Khó nghe, khó nghe quá!"
  },
  AvgDialog_35985_Content_1 = {Text = "Ư——!!"},
  AvgDialog_35985_Content_10 = {
    Text = "Không, những bức tượng sáp của tôi……"
  },
  AvgDialog_35985_Content_11 = {
    Text = "Chưa kịp phản ứng, cổ tay bạn đã bị nắm chặt."
  },
  AvgDialog_35985_Content_12 = {
    Text = "Mau đi theo tôi."
  },
  AvgDialog_35985_Content_13 = {
    Text = "Trong đêm tĩnh lặng, ba người nắm tay nhau chạy qua hết ngã rẽ này đến ngã rẽ khác."
  },
  AvgDialog_35985_Content_14 = {
    Text = "Hô……Cô đeo kính kia, ờ, cô 24, chúng ta còn phải chạy bao lâu nữa……"
  },
  AvgDialog_35985_Content_15 = {
    Text = "Ở đây được rồi, Rogers sẽ không muốn đến một bãi tha ma hỗn loạn chẳng có chút mỹ cảm nào như thế này đâu."
  },
  AvgDialog_35985_Content_16 = {
    Text = "Lần này nhờ có các bạn."
  },
  AvgDialog_35985_Content_17 = {
    Text = "Thằng nhóc đó canh tôi chặt lắm, khắp bảo tàng sáp đều là tai mắt của chúng, 23 kế hoạch trốn thoát tôi lập ra đều thất bại hết."
  },
  AvgDialog_35985_Content_18 = {
    Text = "Thật ra chỉ là một tai nạn thôi……Chúng tôi cũng không hiểu sao lại đến được đây."
  },
  AvgDialog_35985_Content_19 = {
    Text = "Ơ, các bạn không thấy ngạc nhiên sao? Đối mặt với một phiên bản khác của chính mình."
  },
  AvgDialog_35985_Content_2 = {
    Text = "Khá giỏi đấy. Xem ra mấy <Red:nhóc con> ở dưới lòng đất cũng đến lúc phải thức dậy làm việc rồi……"
  },
  AvgDialog_35985_Content_20 = {
    Text = "\"24\" và Mason đồng loạt nhìn bạn, dường như bạn vừa đặt ra một câu hỏi rất kỳ lạ."
  },
  AvgDialog_35985_Content_21 = {
    Text = "Tôi không hiểu ý bạn……Trên thế giới vốn có rất nhiều 24 mà, chúng tôi luôn sẽ gặp nhau thôi."
  },
  AvgDialog_35985_Content_22 = {
    Text = "<Gray:Chẳng lẽ đây là quy tắc kỳ lạ trong mật cảnh này……>"
  },
  AvgDialog_35985_Content_23 = {
    Text = "Thôi, coi như tôi chưa hỏi gì vậy."
  },
  AvgDialog_35985_Content_24 = {
    Text = "Tôi phải về nhà ngay, Jenkins chắc chắn rất lo lắng cho tôi."
  },
  AvgDialog_35985_Content_25 = {
    Text = "Khoan đã, cô 24!!"
  },
  AvgDialog_35985_Content_26 = {
    Text = "\"24\" sải bước tiến về phía trước, cô còn có việc quan trọng hơn phải làm. Tuy nhiên——"
  },
  AvgDialog_35985_Content_27 = {
    Text = "Cộc cộc."
  },
  AvgDialog_35985_Content_28 = {
    Text = "Ngũ tạng lục phủ dường như bị những sợi dây vô hình kéo giật, nhanh chóng tách rời khỏi vị trí ban đầu."
  },
  AvgDialog_35985_Content_29 = {Text = "Ư——!!"},
  AvgDialog_35985_Content_3 = {
    Text = "Mấy nhóc con ở bên dưới……"
  },
  AvgDialog_35985_Content_30 = {
    Text = "Gần đây, có thứ gì đó…… Ai ở đằng kia?!"
  },
  AvgDialog_35985_Content_31 = {
    Text = "\"24\"ôm ngực, đau đớn cúi gập người xuống."
  },
  AvgDialog_35985_Content_32 = {
    Text = "Giây tiếp theo, đất dưới đầu gối cô nhanh chóng trắng bệch, cả thế giới biến thành một màu trắng xóa mênh mông."
  },
  AvgDialog_35985_Content_33 = {
    Text = "Khi mở mắt lần nữa, bầu trời và mặt đất phủ đầy tuyết trắng hòa quyện thành một khoảng hư vô huyền bí khôn lường, chỉ có dãy núi trùng điệp sừng sững phía trước."
  },
  AvgDialog_35985_Content_34 = {
    Text = "Tất cả đều tắm trong ánh dương cực địa xanh nhạt, lạnh lùng, sắc bén, không buồn không vui."
  },
  AvgDialog_35985_Content_35 = {
    Text = "Cô quỳ sụp dưới chân núi tuyết."
  },
  AvgDialog_35985_Content_4 = {
    Text = "Có lẽ đang nói đến những bức tượng sáp đã thấy ở tầng hầm bảo tàng sáp trước đó."
  },
  AvgDialog_35985_Content_5 = {
    Text = "Nếu là chúng thì chắc chắn sẽ là một trận chiến khốc liệt……"
  },
  AvgDialog_35985_Content_6 = {Text = "Tách."},
  AvgDialog_35985_Content_7 = {
    Text = "Ở một góc không ai chú ý, có người dùng nến châm lửa vào thi thể còn lại của George."
  },
  AvgDialog_35985_Content_8 = {
    Text = "Chỉ trong chốc lát, bảo tàng sáp bùng lên ngọn lửa dữ dội."
  },
  AvgDialog_35985_Content_9 = {
    Text = "Ôi trời, sao lại cháy rồi!"
  },
  AvgDialog_35987_Content_1 = {Text = "\"nguồn\""},
  AvgDialog_35987_Content_10 = {
    Text = "? Nghe cô Wenkel nói, thâm cảnh của tôi rất đáng sợ, đầy quái vật hung dữ…"
  },
  AvgDialog_35987_Content_11 = {
    Text = "Đó chỉ là những suy đoán của cô ấy mà thôi. \nTuy nhiên, tôi thực sự đã nhìn thấy thứ gì đó rất đặc biệt, chẳng hạn như \"bạn\"."
  },
  AvgDialog_35987_Content_12 = {
    Text = "Tôi……?"
  },
  AvgDialog_35987_Content_13 = {
    Text = "Bạn mỉm cười khẽ, nháy mắt với cô ấy."
  },
  AvgDialog_35987_Content_14 = {
    Text = "Đây là bí mật giữa tôi và \"cô ấy\", nếu có cơ hội sau này tôi sẽ kể cho bạn nghe từ từ."
  },
  AvgDialog_35987_Content_15 = {
    Text = "Chị—— !!"
  },
  AvgDialog_35987_Content_16 = {
    Text = "Jenkin bất ngờ nhảy ra từ bụi hoa gần các người."
  },
  AvgDialog_35987_Content_17 = {
    Text = "Tôi và Ai Jī Sī đã trở về sau khi dạo chơi. Xem chúng tôi đã tìm được những gì."
  },
  AvgDialog_35987_Content_18 = {
    Text = "Jenkin đang lắc một dải lụa đỏ trong tay. \n Không giống dải lụa Mason hay dùng, cuối dải lụa này còn đính một quả chuông vàng ố."
  },
  AvgDialog_35987_Content_19 = {
    Text = "Gió nhẹ thổi qua, chuông nhỏ phát ra tiếng leng keng trong trẻo, như một linh hồn vui vẻ."
  },
  AvgDialog_35987_Content_2 = {
    Text = "Đại học Misag, trong khuôn viên\nba ngày sau"
  },
  AvgDialog_35987_Content_20 = {
    Text = "Đây là những gì thấy được trong thâm cảnh…"
  },
  AvgDialog_35987_Content_21 = {
    Text = "À, bạn cũng đã gặp trong thâm cảnh rồi à? Vậy chắc chắn bạn đã gặp chị gái biến thành mèo rồi!"
  },
  AvgDialog_35987_Content_22 = {
    Text = "Đừng, đừng nói nữa…"
  },
  AvgDialog_35987_Content_23 = {
    Text = "Không thể nói, chiếc ruy-băng này là vật kỷ niệm vô cùng, tuyệt đối, cực kỳ quan trọng!"
  },
  AvgDialog_35987_Content_24 = {
    Text = "Đó là khoảng thời gian tôi hằng ngày chăm sóc và vui đùa cùng bạn, vui không tả nổi!"
  },
  AvgDialog_35987_Content_25 = {
    Text = "Jenkin đặt nhẹ nhàng dải lụa vào tay Mason."
  },
  AvgDialog_35987_Content_26 = {
    Text = "Tôi vẫn nhớ có người đã nói, kiếp sau muốn làm một con mèo."
  },
  AvgDialog_35987_Content_27 = {
    Text = "Nếu thật sự có thể như vậy mãi không lo lắng cũng rất tốt, tôi còn có thể tiếp tục chăm sóc bạn nữa."
  },
  AvgDialog_35987_Content_28 = {
    Text = "Cái gì cá khô, cỏ bạc hà, tất cả cứ để ta lo!"
  },
  AvgDialog_35987_Content_29 = {
    Text = "Mason cúi đầu cười, ngón tay nhẹ nhàng vuốt qua dải lụa mềm mại và lạnh lẽo."
  },
  AvgDialog_35987_Content_3 = {
    Text = "Thì ra là vậy. Không lâu sau khi giết Albinô, bạn đã bị Hiệp hội Điêu khắc gia bắt đi."
  },
  AvgDialog_35987_Content_30 = {
    Text = "Làm một con mèo ư? Đó là chuyện kiếp sau rồi."
  },
  AvgDialog_35987_Content_31 = {
    Text = "Bây giờ tôi chỉ muốn làm \"Mason\", và sống tốt đẹp cùng mọi người."
  },
  AvgDialog_35987_Content_32 = {
    Text = "À… dường như lần này thâm cảnh đã khiến chị ấy thay đổi rất nhiều, trước đây cô ấy không phải như vậy."
  },
  AvgDialog_35987_Content_33 = {
    Text = "Tôi xin thề, những gì Miss Mason nói đều là sự thật."
  },
  AvgDialog_35987_Content_34 = {
    Text = "Bạn và Mason nhìn nhau mỉm cười. Ký ức ùa về khoảnh khắc trước khi thâm cảnh sụp đổ…"
  },
  AvgDialog_35987_Content_35 = {
    Text = "Thì ra là vậy…… Tôi hiểu rồi."
  },
  AvgDialog_35987_Content_36 = {
    Text = "Bạn là nguồn gốc của tất cả, cũng là điểm kết thúc của tất cả…"
  },
  AvgDialog_35987_Content_37 = {
    Text = "Khi ánh sáng cuối cùng của ngôi sao tan biến, thế giới như đánh mất trong làn mực đen."
  },
  AvgDialog_35987_Content_38 = {
    Text = "Bạn nghe thấy tiếng chuông từ xa vọng lại, như thể đến từ những âm thanh hỗn loạn sâu trong lớp mantô."
  },
  AvgDialog_35987_Content_39 = {
    Text = "Đây... là... thâm cảnh sắp sụp đổ?!!"
  },
  AvgDialog_35987_Content_4 = {
    Text = "Chính điều này đã dẫn tới câu chuyện xảy ra sau đó."
  },
  AvgDialog_35987_Content_40 = {
    Text = "Nắm lấy tay tôi, %player%{Male=ngài,Female=cô}!"
  },
  AvgDialog_35987_Content_41 = {
    Text = "Bạn nắm chặt tay Mason."
  },
  AvgDialog_35987_Content_42 = {
    Text = "Lúc đó, máu của bạn dường như chảy vào thân thể cô ấy, không gặp bất kỳ trở ngại nào, ý thức của hai người đang dần hòa làm một."
  },
  AvgDialog_35987_Content_43 = {
    Text = "Bạn cảm thấy mình đang dần dần thiếp đi, vô số giấc mơ ùa đến, đưa bạn trôi vào bóng tối."
  },
  AvgDialog_35987_Content_44 = {
    Text = "Lần nữa mở mắt, bạn đứng một mình trong hang động. Dưới chân là dòng sông ánh vàng rực rỡ, giống như mạch máu xuyên qua lòng đất."
  },
  AvgDialog_35987_Content_45 = {
    Text = "Là ánh sáng sao đã từng thấy… hóa ra chúng đều tập trung ở đây rồi?"
  },
  AvgDialog_35987_Content_46 = {
    Text = "<Red:Trở về đi, trở về đi……>"
  },
  AvgDialog_35987_Content_47 = {
    Text = "Bạn đi sâu vào hang động theo dòng chảy của ánh sao."
  },
  AvgDialog_35987_Content_48 = {
    Text = "Đây là……?!"
  },
  AvgDialog_35987_Content_49 = {
    Text = "Đây chính là gốc rễ của mọi thứ biến dạng, quái dị và bẩn thỉu."
  },
  AvgDialog_35987_Content_5 = {
    Text = "Ừ. Tôi bây giờ đều nhớ lại rồi, đó không phải là ký ức vui vẻ gì…"
  },
  AvgDialog_35987_Content_50 = {
    Text = "Khối u xám nhạt không ngừng rung động và phình to, phân chia ra những quái vật kỳ dị ngọ nguậy, giống như túi dạ dày đang không ngừng giãy dụa."
  },
  AvgDialog_35987_Content_51 = {
    Text = "Tuy nhiên, chúng chưa kịp lên bờ đã ngã trở lại hồ, bị nuốt chửng bởi những vết nứt lớn trên thân khối u."
  },
  AvgDialog_35987_Content_52 = {
    Text = "Những đường nét của những quái vật này dường như có chút quen thuộc… Hay là… chẳng lẽ…"
  },
  AvgDialog_35987_Content_53 = {
    Text = "Bạn đột nhiên có một trực giác mạnh mẽ. Bạn lội qua chất nhầy màu xám, đến trước khối chất."
  },
  AvgDialog_35987_Content_54 = {
    Text = "Mason… có phải cậu không?"
  },
  AvgDialog_35987_Content_55 = {
    Text = "Khối vật chất đứng yên một khoảnh khắc, sau đó lại bắt đầu di chuyển nhẹ nhàng."
  },
  AvgDialog_35987_Content_56 = {
    Text = "Nó phát ra tiếng xào xạc, như thể một lời chào thân thiện."
  },
  AvgDialog_35987_Content_57 = {
    Text = "Bạn nhìn xuống những quái vật bò sụp dưới hồ, chúng di chuyển khó khăn, co giật trong chất nhầy, chỉ mong được trở về với khối của mình."
  },
  AvgDialog_35987_Content_58 = {
    Text = "Như những người hành hương vượt qua gió tuyết để tìm kiếm diệu kỳ."
  },
  AvgDialog_35987_Content_59 = {
    Text = "<Red:mọi nguồn gốc của sự ô uế, bất tịnh và điềm xấu…>"
  },
  AvgDialog_35987_Content_6 = {
    Text = "Bạn nhẹ nhàng cầm tay Mason."
  },
  AvgDialog_35987_Content_60 = {
    Text = "<Red:trở về đi……>"
  },
  AvgDialog_35987_Content_62 = {
    Text = "Bởi vì đó là nơi kết thúc của tất cả các con sông, dù cách xa nhau bao nhiêu, chúng cuối cùng cũng sẽ hội tụ tại đây."
  },
  AvgDialog_35987_Content_63 = {
    Text = "Thì ra là thế… Ngươi mới chính là điểm đến mà họ khao khát trở về. Vậy đây chính là điều ngươi làm mỗi ngày sao?"
  },
  AvgDialog_35987_Content_64 = {
    Text = "Với thân thể yếu ớt, kéo những nhân cách tán loạn trở lại và nỗ lực duy trì dáng vẻ của một người \"bình thường\"."
  },
  AvgDialog_35987_Content_65 = {
    Text = "Như một người mẹ mệt mỏi đang chờ đợi đứa con xa xứ trở về, sau những cuộc chia ly và hợp nhất dài đằng đẵng, bà thậm chí còn quên mất vai trò làm mẹ của mình."
  },
  AvgDialog_35987_Content_66 = {
    Text = "……Thì ra tôi đã mơ thấy những chuyện trong quá khứ."
  },
  AvgDialog_35987_Content_67 = {
    Text = "Lần cuối thấy những ánh sao kia, tôi bỗng nhiên cảm thấy mình rất giống chúng."
  },
  AvgDialog_35987_Content_68 = {
    Text = "… cũng có điểm khác. Chúng biết quê hương của mình ở đâu, còn tôi thì thậm chí đã mất cả ký ức."
  },
  AvgDialog_35987_Content_69 = {
    Text = "Mũi bỗng nhiên có chút chua xót, bạn nhẹ nhàng đặt tay lên khối thịt mềm, cảm nhận nhịp đập bình yên của nó."
  },
  AvgDialog_35987_Content_7 = {
    Text = "Đều đã qua rồi, Miss Mason. Tôi xin đảm bảo, từ nay chúng sẽ không bao giờ xảy ra nữa."
  },
  AvgDialog_35987_Content_70 = {
    Text = "Mason… Tôi sau này cũng sẽ tìm lại được quê hương phải không? Giống như những gì các người đang làm…"
  },
  AvgDialog_35987_Content_71 = {
    Text = "Khối thịt co giật nhẹ, từ cuối khối thịt tách ra một xúc tu êm ái và nhờn nhẵn, nhẹ nhàng lau đi nước mắt ở góc mắt bạn."
