  AvgDialog_35987_Content_72 = {
    Text = "<Change>Chắc chắn rồi…"
  },
  AvgDialog_35987_Content_73 = {
    Text = "<Change>Đừng khóc……"
  },
  AvgDialog_35987_Content_74 = {
    Text = "Rầm rộ…"
  },
  AvgDialog_35987_Content_75 = {
    Text = "Từ sâu dưới lòng đất truyền đến những rung động nhẹ nhàng, vách đá bị xé ra thành những vết nứt."
  },
  AvgDialog_35987_Content_76 = {
    Text = "Còn <Red:0> phút trước khi thâm cảnh sụp đổ:"
