  AvgDialog_35987_Content_78 = {
    Text = "Khi đi đến miệng hang, bạn không thể kiềm chế và liếc nhìn cô ấy lần cuối."
  },
  AvgDialog_35987_Content_79 = {
    Text = "Hẹn gặp lại, cô Mason."
  },
  AvgDialog_35987_Content_8 = {
    Text = "Cảm ơn bạn… %player%{Male=ngài,Female=cô}."
  },
  AvgDialog_35987_Content_80 = {
    Text = "Hạnh phúc, buồn bã, đau khổ… những nhân cách và cảm xúc khác nhau đến rồi đi, nhưng cô ấy vẫn luôn ở trong động đá đó."
  },
  AvgDialog_35987_Content_81 = {
    Text = "—— cô ấy còn sống."
  },
  AvgDialog_35987_Content_9 = {
    Text = "Đúng là tôi phải cảm ơn bạn mới đúng. \nLúc thâm cảnh sụp đổ, bạn đã cho tôi rất nhiều sự khích lệ và an ủi."
