  AvgDialog_35988_Content_1 = {
    Text = "Rắn Mất Ngủ"
  },
  AvgDialog_35988_Content_10 = {
    Text = "Cô run rẩy giơ cao hai tay, ngẩng đầu ngước nhìn vòm trần tối đen, miệng không ngừng phát ra những lời mê sảng mơ hồ."
  },
  AvgDialog_35988_Content_11 = {
    Text = "Nguồn cội của mọi sự bất tịnh, bất khiết, bất tường……"
  },
  AvgDialog_35988_Content_12 = {
    Text = "Trở về đi……<Big:Trở về đi!>"
  },
  AvgDialog_35988_Content_13 = {
    Text = "Ugh……đầu đau quá……"
  },
  AvgDialog_35988_Content_14 = {
    Text = "Lời mê sảng như gợn sóng lan tỏa từng vòng ra ngoài. Mason đau đớn ôm đầu, cũng quỳ sụp phía sau \"24\"."
  },
  AvgDialog_35988_Content_15 = {
    Text = "Đừng nói nữa……<Big:Đừng nói nữa>!"
  },
  AvgDialog_35988_Content_16 = {
    Text = "Cô lao tới, từ phía sau ôm chặt \"24\"đang máu chảy đầm đìa trên mặt."
  },
  AvgDialog_35988_Content_17 = {
    Text = "Xin cậu, đừng nói nữa……"
  },
  AvgDialog_35988_Content_18 = {
    Text = "Mason dốc sức ghì chặt đôi tay giơ cao của \"24\", máu và nước mắt của hai người hòa quyện vào nhau. Nhưng tất cả đều vô ích."
  },
  AvgDialog_35988_Content_19 = {
    Text = "<Red:Trở về đi, trở về đi……>"
  },
  AvgDialog_35988_Content_2 = {
    Text = "Người phụ nữ chân trần bò lê về phía trước."
  },
  AvgDialog_35988_Content_20 = {
    Text = "<Red:Cùng chung hưởng bữa tiệc — ô uế này!!>"
  },
  AvgDialog_35988_Content_21 = {
    Text = "Tiểu thư 24, đừng——!!"
  },
  AvgDialog_35988_Content_22 = {
    Text = "Những cánh tay xoắn vặn dị dạng mọc ra từ bên trong cơ thể\"24\". Chúng tắm mình trong máu tươi và ánh trăng, rồi——"
  },
  AvgDialog_35988_Content_23 = {
    Text = "Dịu dàng nhưng kiên quyết bẻ gãy cổ của \"24\"."
  },
  AvgDialog_35988_Content_25 = {
    Text = "Không có cảnh tượng đẫm máu như dự tưởng. Cơ thể\"24\" hóa thành từng đốm ánh sao vàng kim, tựa như những con đom đóm nhảy nhót trong đêm tối."
  },
  AvgDialog_35988_Content_26 = {
    Text = "Ơ……cái này là……"
  },
  AvgDialog_35988_Content_27 = {
    Text = "Ánh sao dịu dàng bao quanh Mason, có đốm chui vào cơ thể cô, có đốm nhảy múa trên đầu ngón tay, rồi nhẹ nhàng bay đi."
  },
  AvgDialog_35988_Content_28 = {
    Text = "……Tôi đã từng thấy những ánh sao này."
  },
  AvgDialog_35988_Content_29 = {
    Text = "Trong mơ, trong thực tại……chúng đến để đưa \"chúng tôi\" đi."
  },
  AvgDialog_35988_Content_3 = {
    Text = "Mái tóc dài lê thê kéo lết trên mặt đất, bị cỏ khô, tuyết trắng và những cục máu đông bám chặt, đã mất đi vẻ bóng mượt ngày xưa từ lâu."
  },
  AvgDialog_35988_Content_30 = {
    Text = "Bạn đưa tay chạm vào ánh sao. Đầu ngón tay truyền đến cảm giác ấm áp, như thể có một sợi dây liên kết bí ẩn đang chảy giữa bạn và chúng."
  },
  AvgDialog_35988_Content_31 = {
    Text = "<Gray:Kỳ lạ, trong lòng bỗng thấy hơi buồn……>"
