  AvgDialog_35988_Content_32 = {
    Text = "Ầm ầm ầm——！！"
  },
  AvgDialog_35988_Content_33 = {
    Text = "Sau khi tia sáng cuối cùng biến mất, bạn cảm nhận được sự rung chuyển phẫn nộ quen thuộc truyền đến từ sâu trong lòng đất."
  },
  AvgDialog_35988_Content_34 = {
    Text = "Tệ rồi, chẳng lẽ mật cảnh lại sắp sụp đổ sao?"
