  AvgDialog_35988_Content_35 = {
    Text = "Nắm lấy tay tôi, cô Mason!"
  },
  AvgDialog_35988_Content_36 = {
    Text = "<Yellow:Nhật ký điều tra Mật Cảnh Nhân Tạo II>\n\n■Mã số mật cảnh: M-C06\n■Thời gian rơi vào: Ngày 17 tháng 12 năm Hồng Tích 315\n■Địa điểm rơi vào: Phố Southwark@2"
  },
  AvgDialog_35988_Content_37 = {
    Text = "<Yellow:■Kết quả điều tra>\n\nBóng đen săn lùng các \"24\" khác/Xu hướng tự sát không rõ nguyên nhân/Tôn giáo@2?\nMối liên hệ giữa chúng là gì?\n\n... Cần thêm manh mối."
  },
  AvgDialog_35988_Content_38 = {
    Text = "Cùng lúc đó, bên ngoài mật cảnh nhân tạo……"
  },
  AvgDialog_35988_Content_39 = {
    Text = "Tại lối vào mật cảnh, các nhà nghiên cứu mặc áo blouse trắng đang tất bật ra vào không ngừng."
  },
  AvgDialog_35988_Content_4 = {
    Text = "Ngay bên cạnh cô, chôn vùi trong tuyết, treo lơ lửng trên cây, là từng xác chết đã khô quắt của những \"24\"."
  },
  AvgDialog_35988_Content_40 = {
    Text = "Đã qua một ngày rồi, %player% vẫn chưa tỉnh. Có cần xin phép cưỡng chế ngắt mật cảnh không?"
  },
  AvgDialog_35988_Content_41 = {
    Text = "Các chỉ số sinh hiệu của %hisorher% đều rất ổn định, dường như không trải qua biến động nguy hiểm nào."
