  AvgDialog_35988_Content_5 = {
    Text = "Họ đến nơi cao như thế này để tìm kiếm điều gì, chẳng ai từng giải thích."
  },
  AvgDialog_35988_Content_50 = {
    Text = "Chương 3, Khoản 3, Điều 2, nếu hành vi của nghi phạm mang tính chất né tránh, bỏ trốn, Hội Thẩm tra có quyền lập tức đưa người đó về."
  },
  AvgDialog_35988_Content_51 = {
    Text = "Chương 4, Khoản 1, bất kỳ tổ chức hay cá nhân nào có hành vi che giấu Thể Thức tỉnh……"
  },
  AvgDialog_35988_Content_53 = {
    Text = "Ngài William, ngài có đang nghe tôi nói không?"
