  AvgDialog_35988_Content_54 = {
    Text = "<Small:……Đang nghe.>"
  },
  AvgDialog_35988_Content_56 = {
    Text = "Đừng phí công sức nữa, thi thể và vật chứng đã bị dọn sạch từ lâu rồi, cậu chẳng tìm được gì ở đây đâu."
  },
  AvgDialog_35988_Content_57 = {
    Text = "Vậy sao. Xin hỏi đây là gì?"
  },
  AvgDialog_35988_Content_58 = {
    Text = "William cẩn thận dùng nhíp gắp lên một mẩu chất khô bán trong suốt."
  },
  AvgDialog_35988_Content_59 = {
    Text = "Trông giống như một loại xác lột của rắn. Nhưng nó có liên quan gì đến vụ án này?"
  },
  AvgDialog_35988_Content_6 = {
    Text = "Cô chỉ biết @2 đang đợi cô, ngay tại nơi băng tuyết và ánh sáng trời tan hòa vào nhau."
  },
  AvgDialog_35988_Content_60 = {
    Text = "Đã là tháng Mười Hai rồi, sao lại có xác lột rắn ở đây?"
