  AvgDialog_35988_Content_61 = {
    Text = "Loảng xoảng!"
  },
  AvgDialog_35988_Content_62 = {
    Text = "Từ phòng trong của phòng khám bỗng vang lên tiếng thiết bị đổ ngã."
  },
  AvgDialog_35988_Content_63 = {
    Text = "Tiếng gì vậy?! Nơi này chẳng phải đã bị niêm phong từ lâu rồi sao……"
  },
  AvgDialog_35988_Content_64 = {Text = "Ra đây."},
  AvgDialog_35988_Content_65 = {
    Text = "Tiếng bước chân không vội không vàng từ xa đến gần, một người đàn ông trắng bệch bất thường bước ra từ phòng trong."
  },
  AvgDialog_35988_Content_66 = {
    Text = "Chào buổi tối, ngài cảnh sát."
  },
  AvgDialog_35988_Content_67 = {
    Text = "Tại hạ là đồng nghiệp của bác sĩ Bernard, được cấp trên ủy thác đến lấy lại tài liệu nghiên cứu lúc sinh thời của ông ấy……"
  },
  AvgDialog_35988_Content_68 = {
    Text = "Đôi mắt người đàn ông hé mở, dường như có chút buồn ngủ. Hắn cười hì hì đưa ra một tấm danh thiếp."
