  AvgDialog_35988_Content_7 = {
    Text = "<Red:Bất tịnh. Bất khiết. Bất tường.>"
  },
  AvgDialog_35988_Content_70 = {
    Text = "Xin lỗi, chúng tôi đã điều tra vòng quan hệ xã hội của bác sĩ Bernard từ lâu rồi. Nếu tôi nhớ không nhầm, vị Pierce này là một ông già ngoài 50 tuổi."
