  AvgDialog_35988_Content_72 = {
    Text = "Hehe……quả không hổ danh là ngài Hội Thẩm tra, khả năng quá mục bất vong thật đáng khâm phục."
  },
  AvgDialog_35988_Content_73 = {
    Text = "Hắn đột ngột mở to đôi mắt, đồng tử dọc màu vàng coban lấp lánh ánh sáng lạnh lẽo trong bóng tối."
  },
  AvgDialog_35988_Content_74 = {
    Text = "Vậy thì chơi với các người một lát vậy."
