  AvgDialog_35988_Content_75 = {Text = "Xì……"},
  AvgDialog_35988_Content_76 = {
    Text = "Trên mặt truyền đến cảm giác lạnh lẽo và trơn nhớt."
  },
  AvgDialog_35988_Content_77 = {
    Text = "Không biết từ lúc nào, trần nhà đã bò đầy những con rắn nhỏ trắng bệch, chúng nhanh chóng trườn đi trong im lặng, rơi xuống như mưa."
  },
  AvgDialog_35988_Content_78 = {
    Text = "Rắn… toàn rắn ở khắp nơi!"
  },
  AvgDialog_35988_Content_79 = {
    Text = "Trần nhà, mặt đất, tường… không biết từ lúc nào xung quanh đã bò đầy rắn, tựa như vô số đám rong trắng bệch trôi dạt trong dòng sông đen tĩnh lặng."
  },
  AvgDialog_35988_Content_8 = {
    Text = "Nguồn cội của mọi sự bất tịnh, bất khiết, bất tường……"
  },
  AvgDialog_35988_Content_80 = {
    Text = "Gọi tiểu đội A-2, B-1, bên trong có nguy hiểm, lập tức vào vị trí."
  },
  AvgDialog_35988_Content_81 = {
    Text = "William nhanh chóng rút chìa khóa bạc ra, nhưng người đàn ông trước mắt đã biến mất từ lúc nào."
