  AvgDialog_35989_Content_1 = {
    Text = "Chờ đợi hài kịch"
  },
  AvgDialog_35989_Content_10 = {
    Text = "Tớ cũng nhìn thấy rồi! Hai người nắm tay nhau, tóc bay phấp phới, đẹp như người mẫu ma-nơ-canh vậy!"
