  AvgDialog_35989_Content_11 = {
    Text = "Suỵt! Ồn ào cái gì, không được làm phiền mọi người xem kịch!"
  },
  AvgDialog_35989_Content_12 = {
    Text = "Trên một sân khấu dựng tạm, chú hề mặt tô đầy phấn sáp đang biểu diễn tiết mục cho mọi người."
  },
  AvgDialog_35989_Content_13 = {
    Text = "Tương truyền từ rất lâu rất lâu về trước, trong vùng tuyết sơn ở cực bắc, nơi tận cùng của dòng sông cổ xưa, có một con quái vật màu xám đang say giấc ngủ dài～～～"
  },
  AvgDialog_35989_Content_14 = {
    Text = "Xin chào mọi người, tôi chính là con quái vật đó. <BigShake:Gào——>"
  },
  AvgDialog_35989_Content_15 = {
    Text = "<Shake:Waaaa——>Ơ, đó chẳng phải là Zhankin sao?"
  },
  AvgDialog_35989_Content_16 = {
    Text = "Không ai biết lai lịch và tên gọi của con quái vật, ngoại trừ cái bụng tham ăn của nó — mỗi năm vào mùa đông, cư dân sống dưới chân núi tuyết sẽ bỏ đồ ăn ngon và rượu vào giỏ……"
  },
  AvgDialog_35989_Content_17 = {
    Text = "Thắp một ngọn nến bạc, rồi đặt giỏ xuống dòng sông gần nhà nhất, như vậy con quái vật sẽ nhận được lễ vật của mọi người."
  },
  AvgDialog_35989_Content_18 = {
    Text = "Tớ, tớ có một câu hỏi!\nCon quái vật chẳng phải sống trong núi tuyết sao, làm sao nhận được lễ vật ở dưới sông được?"
