  AvgDialog_35989_Content_19 = {
    Text = "Bởi vì tận cùng của mọi dòng sông đều nằm dưới chân núi tuyết, bất kể cách xa bao nhiêu, chúng rồi sẽ hội tụ tại đây."
  },
  AvgDialog_35989_Content_2 = {
    Text = "Mật cảnh nhân tạo: Viện cứu tế Lillian, Khu Đông"
