  AvgDialog_35989_Content_20 = {
    Text = "Ồ…… rồi sao nữa?"
  },
  AvgDialog_35989_Content_21 = {
    Text = "Nhồm nhoàm nhồm nhoàm, ta đã nhận được lễ vật của mọi người rồi! Ta rất vui, quyết định báo đáp mọi người!"
