  AvgDialog_35992_Content_8 = {
    Text = "Sniff sniff… ưm?!"
  },
  AvgDialog_35992_Content_80 = {
    Text = "Bạn là người mang lại niềm vui cho mọi người"
  },
  AvgDialog_35992_Content_81 = {
    Text = "Tương truyền từ rất lâu rất lâu về trước, trong vùng tuyết sơn ở cực bắc, nơi tận cùng của dòng sông cổ xưa, có một con quái vật màu xám đang say giấc ngủ dài～～～"
  },
  AvgDialog_35992_Content_82 = {
    Text = "Xin chào mọi người, tôi là quái vật.<Shake:ào——>"
