  AvgDialog_35992_Content_85 = {
    Text = "Mệt quá à uwu."
  },
  AvgDialog_35992_Content_86 = {
    Text = "Ọc ọc…"
  },
  AvgDialog_35992_Content_87 = {
    Text = "Thật sự phát ra tiếng gừ gừ giống như mèo... giống như những con mèo trong khuôn viên trường Misaque."
  },
  AvgDialog_35992_Content_88 = {
    Text = "Này, bạn đang cười gì vậy!"
  },
  AvgDialog_35992_Content_89 = {
    Text = "Cô ấy hiện tại trông rất vui vẻ, thực sự giống như một chú mèo con vô tư."
  },
  AvgDialog_35992_Content_9 = {
    Text = "Cô ngửi thấy âm thanh. Chúng lơ lửng trong không khí, không rõ chữ hay nhịp, tựa như lời ru nhẹ nhàng của mẹ."
  },
  AvgDialog_35992_Content_90 = {
    Text = "Đúng vậy... họ đều là những người tốt \"24\". \n So sánh với họ, tôi chẳng có ích gì cả..."
  },
  AvgDialog_35992_Content_91 = {
    Text = "Bạn nhẹ nhàng lắc đầu."
  },
  AvgDialog_35992_Content_92 = {
