  },
  AvgDialog_35993_Content_11 = {
    Text = "Theo <Blue:《Báo cáo Sự kiện Dung thực phố Southwark: C06》>, ở đây vừa hay có sinh vật đồng thời phù hợp cả ngoại hình lẫn phạm vi hoạt động."
