  AvgDialog_35993_Content_12 = {
    Text = "Đơn vị lưu trữ báo cáo này vào kho hồ sơ liên hợp chính là Đại học Misager.\nChẳng lẽ, bây giờ ngài muốn phủ nhận tính xác thực của nó sao?"
