  AvgDialog_35993_Content_13 = {
    Text = "Chỉ là hơi nghi ngờ một chút về độ tin cậy của báo cáo nhân chứng thôi, các vị phản ứng hơi quá rồi."
  },
  AvgDialog_35993_Content_14 = {
    Text = "Có thời gian chơi trò chữ nghĩa, chi bằng hỏi thẳng đương sự đi."
  },
  AvgDialog_35993_Content_15 = {
    Text = "Tiểu thư 24, tối ngày 17 tháng 12 lúc 9 giờ 15 phút, cô đã làm gì tại <Blue:phòng khám của Bác sĩ Bernard>, còn nhớ không?"
