  AvgDialog_35993_Content_21 = {
    Text = "Tiểu thư 24? Cô có đang nghe không?"
  },
  AvgDialog_35993_Content_22 = {
    Text = "Một nhát, hai nhát, ba nhát……Tôi đập nát khuôn mặt đẹp đẽ của ông ta, không còn sót lại cả xương."
  },
  AvgDialog_35993_Content_23 = {
    Text = "Mùi máu bám trên người tôi, suốt cả một tuần vẫn không thể tan đi."
  },
  AvgDialog_35993_Content_24 = {
