  },
  AvgDialog_35993_Content_26 = {
    Text = "<Small:Cô ấy mắc chứng hysteria, cô ấy là kẻ điên, điều này ai cũng rõ. Nhưng kẻ điên thì có thể tùy tiện giết hại một vị bác sĩ đáng kính sao?>"
  },
  AvgDialog_35993_Content_27 = {
    Text = "<Small:Điều này không hợp lý, tiểu thư Doer.>"
