  },
  AvgDialog_35993_Content_3 = {
    Text = "Gió tuyết nơi cực bắc phủ kín gương mặt người hành hương. Các ngón chân nàng đã nứt nẻ từ lâu, tầm nhìn đã mờ mịt từ lâu, máu nàng kéo lê thành vệt dài trên tuyết."
  },
  AvgDialog_35993_Content_30 = {
