  },
  AvgDialog_35993_Content_34 = {
    Text = "Nghe nói gần đây ký ức của cậu bị lẫn lộn nghiêm trọng, để tôi giải thích sơ qua một chút nhé."
  },
  AvgDialog_35993_Content_35 = {
    Text = "Lần trước cuộc thẩm vấn liên quan đến <Yellow:cái chết của bác sĩ Bernard>, chúng ta đã xảy ra xung đột gay gắt với Hội Thẩm Tra."
  },
  AvgDialog_35993_Content_36 = {
    Text = "Kết luận cuối cùng là: bảy ngày. Chúng ta chỉ có bảy ngày để điều tra ra sự thật."
  },
  AvgDialog_35993_Content_37 = {
    Text = "Nếu tôi nhớ không nhầm, chuyện này xảy ra trước khi cậu bị đưa đến Bảo tàng Tượng Sáp, nên chúng tôi cũng hoàn toàn không biết gì."
  },
  AvgDialog_35993_Content_38 = {
    Text = "Hồ sơ đã bị niêm phong mấy tháng rồi, trời mới biết họ lôi ra từ đâu. Hơn nữa, điều tra ở một nơi hỗn tạp như Khu Đông thì đúng là mơ giữa ban ngày……"
  },
  AvgDialog_35993_Content_39 = {
    Text = "Vì vậy, chúng tôi quyết định để %player% tiến vào Mật Cảnh Nhân Tạo của cậu để điều tra, vì thế cần cậu hợp tác một chút……"
  },
  AvgDialog_35993_Content_4 = {
    Text = "Nhưng nàng vẫn kiên định, không ngoảnh lại, tiến về phía đỉnh núi."
  },
  AvgDialog_35993_Content_40 = {
    Text = "Thì ra là vậy. Xin lỗi, gần đây tôi cứ lơ mơ mãi……"
  },
  AvgDialog_35993_Content_41 = {
    Text = "Như thể bên trong cơ thể đang ủ một cơn bão dữ dội, nhưng chủ nhân của thân xác này lại hoàn toàn không hay biết."
  },
  AvgDialog_35993_Content_42 = {
    Text = "Khoan đã."
  },
  AvgDialog_35993_Content_43 = {
    Text = "\"Tôi\" thực sự là chủ nhân của thân xác này sao?"
