  },
  AvgDialog_35993_Content_45 = {
    Text = "Wenkel nhanh chóng rút ra ống tiêm đã chuẩn bị sẵn từ trước."
  },
  AvgDialog_35993_Content_46 = {
    Text = "Yên tâm đi, tôi đến đây chính vì việc này.\nChỉ cần một mũi tiêm, cái đầu hỗn loạn của cậu sẽ tỉnh táo hơn nhiều……"
