  },
  AvgDialog_35993_Content_5 = {
    Text = "Đúng vậy——\nNgay bên dưới dãy núi trắng kia, trong hang động u tối sâu thẳm, trú ngụ <Red:nguồn cội> của mọi uế tạp."
