  },
  AvgDialog_35993_Content_55 = {
    Text = "Đã ở trong kênh mật cảnh nhân tạo rồi.\nYên tâm đi, lần này chúng tôi chỉ đặt thời gian nửa tiếng thôi, sẽ không nán lại quá lâu."
