  AvgDialog_35994_Content_5 = {
    Text = "Mùi máu tanh nồng nặc bao trùm phòng khám, khắp nơi là dụng cụ y tế, sách vở và hồ sơ bệnh án vương vãi trên sàn."
  },
  AvgDialog_35994_Content_50 = {
    Text = "Ngươi……hình như ta đã gặp ngươi ở đâu đó……"
  },
  AvgDialog_35994_Content_51 = {
    Text = "%player%……ngươi là Thủ Mật Nhân{Male=ngài,Female=cô}!"
  },
  AvgDialog_35994_Content_53 = {
    Text = "Sao lại nhớ ra tôi là ai rồi?"
  },
  AvgDialog_35994_Content_54 = {
    Text = "Bạn bỗng cảm thấy hơi đau đầu."
  },
  AvgDialog_35994_Content_55 = {
    Text = "Đừng vội vào, tôi chưa nói xong."
  },
  AvgDialog_35994_Content_56 = {
    Text = "Mật cảnh của tiểu thư 24 khác với Ramona và phu nhân Soreil. Cô ấy không có nhân cách ổn định, đặc điểm này chắc chắn sẽ thể hiện trong mật cảnh."
  },
  AvgDialog_35994_Content_57 = {
    Text = "Các nhân cách khác nhau cách biệt lẫn nhau, nhưng lại hòa trộn vào nhau. Bạn thậm chí có thể nhìn thấy rất nhiều 24 ở trong đó."
  },
  AvgDialog_35994_Content_58 = {
    Text = "Tất cả mọi thứ, nhân vật, địa điểm, thời gian……có lẽ đều không phải thật."
  },
  AvgDialog_35994_Content_59 = {
    Text = "Nếu tất cả đều là giả, vậy tôi còn cần điều tra không?"
  },
  AvgDialog_35994_Content_6 = {
    Text = "Thi thể bác sĩ Bernard gục ngã bên tường. Đầu ông đã không còn nguyên vẹn, không thể nhận ra khuôn mặt nữa."
  },
  AvgDialog_35994_Content_60 = {
    Text = "Tất nhiên. Dù bên trong chỉ có một phần trăm là sự thật, chúng ta cũng phải nắm lấy nó."
  },
  AvgDialog_35994_Content_61 = {
    Text = "Tiểu thư 24 tuyệt đối không phải kẻ xấu giết người vô tội bừa bãi, điều này chúng ta đều rõ trong lòng."
  },
  AvgDialog_35994_Content_62 = {
    Text = "Đều không phải thật đâu……Bình tĩnh nào, %player%. Trước tiên hãy xác định mục tiêu điều tra."
  },
  AvgDialog_35994_Content_63 = {
    Text = "Cậu kéo tay Mason ra xem. Trên đó rất sạch sẽ, không có bất kỳ dấu vết bị thương hay đánh nhau nào."
  },
  AvgDialog_35994_Content_64 = {
    Text = "Cô Mason, cô có mâu thuẫn gì với bác sĩ Bernard không?"
  },
  AvgDialog_35994_Content_65 = {
    Text = "Ông ấy……ông ấy chữa bệnh cho tôi, gần đây tôi cứ thấy người ngứa ngáy, rất kỳ lạ……"
  },
  AvgDialog_35994_Content_66 = {
    Text = "Mason vừa nói, vừa thản nhiên gãi gãi con mắt trắng mọc ra từ vết thương dung thực."
  },
  AvgDialog_35994_Content_67 = {
    Text = "Tất nhiên, cô ấy hoàn toàn không ý thức được hành vi này của mình."
  },
  AvgDialog_35994_Content_68 = {
    Text = "Ông ấy chữa trị cho cô. Rồi sao, hai người cãi nhau à?"
