  AvgDialog_35994_Content_74 = {
    Text = "Mật Cảnh sắp kết thúc rồi, lần điều tra này tạm dừng ở đây thôi."
  },
  AvgDialog_35994_Content_75 = {
    Text = "Cô Dole e rằng lo lắng quá rồi, Mật Cảnh này đơn giản hơn nhiều so với của phu nhân Soreil……"
  },
  AvgDialog_35994_Content_76 = {
    Text = "Cậu vươn vai một cái, rồi ngồi xổm trước mặt Mason, nhìn thẳng vào đôi mắt cô ấy."
  },
  AvgDialog_35994_Content_77 = {
    Text = "Cô Mason, bệnh của cô không phải bệnh thường đâu, không phải bác sĩ nào có bằng cấp đẹp đẽ là chữa được."
  },
  AvgDialog_35994_Content_78 = {
    Text = "Lần sau nhớ đến Misage tìm chúng tôi, hiểu chưa?"
  },
  AvgDialog_35994_Content_79 = {
    Text = "Mi, sa, ge……"
  },
  AvgDialog_35994_Content_8 = {
    Text = "\"Tính tình nhân hậu, nhiều năm qua luôn tiến hành công tác y tế thiện nguyện tại nhiều nơi ở Khu Đông…\""
  },
  AvgDialog_35994_Content_80 = {
    Text = "Đúng rồi, Đại học Misage. Chúng tôi là chuyên gia đấy."
  },
  AvgDialog_35994_Content_81 = {Text = "Ồ……"},
  AvgDialog_35994_Content_82 = {
    Text = "Tách. Tách."
  },
  AvgDialog_35994_Content_83 = {
    Text = "Tường phía trên đầu bắt đầu bong tróc từng chút một, mật cảnh không còn ổn định nữa."
  },
  AvgDialog_35994_Content_84 = {
    Text = "Hẹn gặp lại, cô Mason."
  },
  AvgDialog_35994_Content_86 = {
    Text = "Thời gian đã là 9 giờ 30 tối.\nGió lạnh rít qua, bên ngoài cửa sổ vọng lại một hai tiếng kêu cô quạnh của quạ."
  },
  AvgDialog_35994_Content_87 = {
    Text = "Bạn vẫn đứng vững trong phòng khám, bên cạnh là Mason đang quỳ ngồi với vẻ mặt ngơ ngác."
  },
  AvgDialog_35994_Content_88 = {
    Text = "Ơ… Thủ Mật Nhân{Male=ngài,Female=cô}, ngài lại không định rời đi sao?"
