  },
  AvgDialog_35994_Content_9 = {
    Text = "Lý lịch không chê vào đâu được, chẳng trách cảnh sát và hội đồng thẩm tra lại coi trọng đến vậy."
  },
  AvgDialog_35994_Content_90 = {
