  AvgDialog_35994_Content_93 = {
    Text = "<Yellow:Nhật ký điều tra mật cảnh nhân tạo I>\n\n■Mã mật cảnh: M-C06\n■Thời gian thiết lập: Ngày 17 tháng 12 năm Hồng Tích 315, 9:00-9:30pm\n■Địa điểm thiết lập: Phòng khám của bác sĩ Bernard"
  },
  AvgDialog_35994_Content_94 = {
    Text = "<Yellow:■Kết quả điều tra>\n\n——Thủ Mật Nhân mất liên lạc."
