  },
  AvgDialog_35996_Content_2 = {
    Text = "Bóng tối đã bị các bạn đánh bại. Cô ta quỳ gục trên mặt đất, thân thể phát ra những hạt ánh sáng nhỏ li ti."
  },
  AvgDialog_35996_Content_20 = {
    Text = "Bởi vì tôi phải đảm bảo anh ta chết hẳn. Chỉ cần anh ta còn một hơi thở, anh ta sẽ làm tổn thương những đứa trẻ ở nhà tế bần và Jenkin…"
  },
  AvgDialog_35996_Content_21 = {
