  AvgDialog_35996_Content_22 = {
    Text = "Anh ta là một con quỷ chính hiệu."
  },
  AvgDialog_35996_Content_23 = {
    Text = "Thì ra là ngươi……không ngờ là ngươi……"
  },
  AvgDialog_35996_Content_24 = {
    Text = "Lúc đó, tôi đang làm gì nhỉ… chẳng lẽ tôi không biết gì cả sao…"
