  AvgDialog_35996_Content_27 = {
    Text = "Tất cả các \"24\" kết hợp lại, mới có một \"Mason\". \nKhông có \"24\" nào có thể tồn tại cô lập."
  },
  AvgDialog_35996_Content_28 = {
    Text = "Giống như tất cả các dòng sông đều đổ về một nơi, tất cả các \"24\" cũng sẽ tụ về một nơi..."
  },
  AvgDialog_35996_Content_29 = {
    Text = "Mason nhẹ nhàng hôn lên trán của bóng."
  },
  AvgDialog_35996_Content_3 = {
    Text = "Với sức mạnh tuyệt vời của tôi, với sự tức giận tràn đầy của tôi…… sao tôi có thể thua các người, thua kẻ nhút nhát này……"
  },
  AvgDialog_35996_Content_30 = {
    Text = "Thuộc về tôi."
  },
  AvgDialog_35996_Content_32 = {
    Text = "Thân thể của bóng tối hóa thành những điểm sáng lấp lánh. Chúng tản ra xung quanh Mason, rồi tràn vào làn da của cô ấy."
