  AvgDialog_35996_Content_33 = {
    Text = "Thì ra là vậy…… Tôi hiểu rồi."
  },
  AvgDialog_35996_Content_34 = {
    Text = "Bạn là nguồn gốc của tất cả, cũng là điểm kết thúc của tất cả…"
  },
  AvgDialog_35996_Content_35 = {
    Text = "Cô ấy dần mất đi giọng nói trong sự ôm ấp ấm áp."
