  AvgDialog_35996_Content_58 = {Text = "Rào rào!"},
  AvgDialog_35996_Content_59 = {
    Text = "Bác sĩ không cẩn thận làm đổ tập hồ sơ bên cạnh, giấy đã ngả vàng rải rác khắp sàn."
  },
  AvgDialog_35996_Content_6 = {
    Text = "Giao cho tôi."
  },
  AvgDialog_35996_Content_60 = {
    Text = "Xin lỗi, gần đây dịch bệnh ở khu đông xảy ra liên tục, số lượng tài liệu tích lũy trong phòng khám cũng ngày càng nhiều——"
