  AvgDialog_35996_Content_62 = {Text = "Tôi…"},
  AvgDialog_35996_Content_63 = {
    Text = "Tay dừng lại ở khoảng cách chưa đến 2 inch so với tập tài liệu. Đó là một xấp hồ sơ cá nhân, Mason nhận ra vài từ quen thuộc sau một hồi cố gắng."
  },
  AvgDialog_35996_Content_64 = {
    Text = "Báo cáo thí nghiệm, bản ghi vận chuyển……?"
