  AvgDialog_35997_Content_53 = {Text = "Ư ư…"},
  AvgDialog_35997_Content_54 = {
    Text = "Thở dài. Từ khi tìm được vị thầy lang dỏm đó, bệnh tình của chị gái càng ngày càng nặng."
