  AvgDialog_35997_Content_6 = {
    Text = "Cô gái bước đến với những bước chân vững chãi, gió thổi tung chiếc áo choàng te tua của cô."
  },
  AvgDialog_35997_Content_60 = {
    Text = "Rất tốt, anh ấy rất tốt, anh ấy là bác sĩ giỏi nhất trên thế giới."
