  AvgDialog_38841_Content_12 = {
    Text = "Giây tiếp theo, một bảng đá lớn rơi xuống trước mặt bạn."
  },
  AvgDialog_38841_Content_13 = {
    Text = "Những người điên cuồng lao về phía bạn, máu me bắn tung tóe, hỗn loạn và những tiếng thét kinh hoàng… Tất cả mọi thứ đều được ngăn cách sau tấm bảng đá."
  },
  AvgDialog_38841_Content_14 = {
    Text = "Một bàn tay đeo găng đen đặt lên cánh tay nhỏ của bạn, vải mát lạnh làm dịu đi cơn đau và cũng lau đi máu tươi đang trượt trên cánh tay bạn."
  },
  AvgDialog_38841_Content_15 = {
    Text = "Người cắn bạn đã biến mất, giờ đây bên cạnh bạn là một vị giám mục mặc áo choàng đen, nắm lấy tay bạn."
  },
  AvgDialog_38841_Content_16 = {
    Text = "Sau lưng anh ta treo bốn tấm bảng đá, trên mỗi tấm đều khắc những phù văn phức tạp, mỗi phù văn đều có ánh sáng xanh lưu chuyển, giống như dải ngân hà thu nhỏ vô số lần."
  },
  AvgDialog_38841_Content_17 = {
    Text = "Một tia sáng xanh chảy từ cánh tay anh ta đến bạn. Bạn cúi đầu, vết cắn trên cẳng tay đã ngừng chảy máu và dần lành lại khi bạn nhìn vào."
  },
  AvgDialog_38841_Content_18 = {
    Text = "Salvador……Giám mục?"
