  AvgDialog_38841_Content_6 = {
    Text = "Những đôi mắt đỏ au nhìn về phía bạn, những đôi tay vươn ra hướng về bạn, phía sau là những cái miệng rộng mở và những chiếc răng trắng nhợt."
