  AvgDialog_38842_Content_24 = {Text = "Đúng!"},
  AvgDialog_38842_Content_3 = {
    Text = "Đánh nhau biến thành hành hạ, tự thương biến thành tự tử, và những người vốn đã tích cực tìm cách chết, càng bắt đầu kết thúc sức sống của mình theo những cách không thể tưởng tượng được."
