  AvgDialog_38842_Content_7 = {
    Text = "Hãy sám hối, tội nhân! Trước khi người cầm đèn nghiêm khắc đưa ra phán quyết, hãy thanh tẩy linh hồn bẩn thỉu của các ngươi!"
  },
  AvgDialog_38842_Content_8 = {
    Text = "Chiếc gương cầm tay không ngừng nhấp nháy, ánh sáng đỏ tươi làm đau mắt bạn, thậm chí xuyên qua đôi mắt, đi thẳng vào đầu óc và tinh thần của bạn."
  },
  AvgDialog_38842_Content_9 = {
    Text = "Có thứ gì đó càng kéo càng chặt, càng kéo càng chặt, là gì vậy? Rất khó chịu, rất đau, rất muốn nôn…"
