  AvgDialog_38843_Content_10 = {
    Text = "Ho sặc, một vũng chất lỏng rơi xuống đất. \nMùi máu càng trở nên gay gắt."
  },
  AvgDialog_38843_Content_11 = {
    Text = "Bây giờ cô ấy đã chết...<Blue:Millie> đã chết...!<Blue:Thompson> tên điên đó muốn tôi phải chôn cùng với cô ấy. Tôi... tôi không muốn chết, ngài Giám mục, nhưng tôi cũng.."
