  },
  AvgDialog_38843_Content_13 = {
    Text = "… \"Những người đã từng phạm lỗi, Ngài cũng sẵn lòng dang rộng vòng tay, miễn là họ thật tâm sám hối.\""
  },
  AvgDialog_38843_Content_14 = {
