  AvgDialog_38843_Content_2 = {
    Text = "Giám mục… Giám mục Salvador…"
  },
  AvgDialog_38843_Content_20 = {
    Text = "Mùi hương của đền thánh nhẹ nhàng chạm đến chóp mũi bạn, thanh thoát, mơ hồ, như thể chưa từng hiện hữu, nhưng lại hoàn toàn che lấp đi mùi tanh của máu tươi."
  },
  AvgDialog_38843_Content_21 = {
    Text = "……thân thể được đánh thức."
  },
  AvgDialog_38843_Content_22 = {
    Text = "Anh ta đột nhiên vặn mình, há miệng sắp sửa cắn vào tay bạn. Những chiếc răng đi kèm với hơi thở ẩm ướt tiến gần cánh tay bạn, lông tay bạn dựng đứng, thân thể căng cứng, chuẩn bị cho cơn đau sắp ập tới."
  },
  AvgDialog_38843_Content_23 = {
    Text = "Đột nhiên, một bàn tay đeo găng đen phủ lên cánh tay bạn."
