  AvgDialog_43788_Content_31 = {
    Text = "Nếu có thể, hãy cử một đại diện đến gặp nữ hoàng."
  },
  AvgDialog_43788_Content_33 = {
    Text = "Trời dần tối, mặt trời lặn như máu. \n Chim ưng sa mạc bay quanh vài vòng, phát ra tiếng kêu dài cuối cùng đầy não nề, rồi rơi xuống cành cây khô chìm vào giấc ngủ."
  },
  AvgDialog_43788_Content_34 = {
    Text = "Nhờ sự hướng dẫn của Yu Li-ét, bạn đến trước một chiếc lều có hình dạng độc đáo."
  },
  AvgDialog_43788_Content_35 = {
    Text = "Đây là trại của nữ hoàng. Theo truyền thống của người Aran, tất cả khách quý đều cần phải nhận được sự đồng ý của tộc trưởng dưới sự giám sát của nữ hoàng."
  },
  AvgDialog_43788_Content_36 = {
    Text = "Bạn ở đây chờ trưởng tộc, tôi đi xử lý công việc vừa nãy trước."
  },
  AvgDialog_43788_Content_37 = {
    Text = "Nhớ kỹ, tuyệt đối đừng vào."
  },
  AvgDialog_43788_Content_38 = {
    Text = "Nếu làm phật ý nữ hoàng, phần tôi có thể giúp đỡ sẽ rất hạn chế."
  },
  AvgDialog_43788_Content_4 = {
    Text = "Mảnh hương liệu này, xin vui lòng mang theo người bất cứ lúc nào, có thể giấu trong cà vạt, treo trên gậy hoặc đặt nhẹ vào tai đều được."
  },
  AvgDialog_43788_Content_40 = {
    Text = "Gió nhẹ nhàng thổi động rèm mành, cảnh bên trong lều trại ẩn hiện mờ ảo qua khe hở."
  },
  AvgDialog_43788_Content_41 = {
