  AvgDialog_43788_Content_61 = {Text = "Pụng!"},
  AvgDialog_43788_Content_62 = {
    Text = "Cây đổ sập, một khúc gỗ mục trôi theo dòng nước, hình dạng của khúc gỗ giống như một quan tài……"
