  AvgDialog_43806_Content_2 = {
    Text = "Theo như Elva nói, những kẻ này chỉ là thủ lĩnh của các nhóm nhỏ, mối đe dọa thực sự chắc chắn sẽ khủng khiếp hơn nhiều so với con này."
