  AvgDialog_43807_Content_52 = {
    Text = "Nói quan trọng thì cũng không quá quan trọng —— đến đi, vào lều của tôi nói chuyện tiếp."
  },
  AvgDialog_43807_Content_6 = {
    Text = "Dao phẫu thuật cắt vào thân thể NUBIA, không có chất lỏng đen chảy ra như dự kiến."
  },
  AvgDialog_43807_Content_7 = {
    Text = "William căng thẳng thần kinh, từ từ đưa lưỡi dao vào sâu, rồi kẻ một đường xuống dưới——"
