  AvgDialog_43808_Content_1 = {
    Text = "Giọng nói tập hợp trong không gian ý thức này là sự kết hợp của ý thức tất cả người Aran từ cổ chí kim."
  },
  AvgDialog_43808_Content_10 = {
    Text = "Yu Li-ét quỳ trước nôi, thành tâm hát khe khẽ một bài ca dao."
