  AvgDialog_43808_Content_20 = {
    Text = "Nhưng nguồn tin từ Đào Đen Đá cho chúng ta biết rằng, một khi cây mẹ phong thịnh phục sinh, có thể dẫn đến hiện tượng rỗng rỗng trên toàn cầu."
  },
  AvgDialog_43808_Content_21 = {
    Text = "Di cốt cây thánh nằm trong doanh trại của nữ hoàng. Nếu phá hủy di cốt cây thánh trước khi vào Tường Bão, nhiệm vụ có thể hoàn thành với tổn thất tối thiểu."
  },
  AvgDialog_43808_Content_22 = {
    Text = "Vậy, vấn đề là, trong mắt các bạn, thương nhân tên Đào Đen Đá có uy tín như thế nào? Nguồn tin của cô ấy có đáng tin cậy không?"
