  AvgDialog_43808_Content_23 = {
    Text = "Alistair đã cố gắng hết sức, chỉ xác nhận được rằng thật sự có người cố ý truyền đi thông điệp này, không thể đánh giá độ chính xác của thông điệp."
  },
  AvgDialog_43808_Content_24 = {
    Text = "Đốt cháy bất cẩn di cốt cây thánh có thể sẽ cắt đứt con đường lui cuối cùng của người Aran."
  },
  AvgDialog_43808_Content_25 = {
    Text = "Trước sự xói mòn, chúng ta cũng không có đường lui. \nĐừng để lòng trắc ẩn sai lầm làm nhiễu loạn phán đoán của bạn."
  },
  AvgDialog_43808_Content_26 = {
    Text = "Không sao đâu, Đóa. Dù cuối cùng có phải xông vào hiện trường nghi lễ để đốt cây mẹ, tôi cũng sẽ đi cùng."
  },
  AvgDialog_43808_Content_27 = {
    Text = "Tôi đồng ý với quan điểm của Người Giữ Gìn, chúng ta biết rất ít về mọi thứ liên quan đến Aran, tấn công lúc này quả thật thiếu thận trọng."
  },
  AvgDialog_43808_Content_28 = {
    Text = "Nghiên cứu của tôi về Nubia vẫn sẽ tiếp tục. \n Người giữ bí mật, Lắc, việc điều tra xác chết cây thánh sẽ giao cho các bạn."
  },
  AvgDialog_43808_Content_3 = {
    Text = "Vâng, linh hồn của người Aran đang than khóc. \n Vì tội lỗi của sự sống và nỗi sợ của cái chết."
