  AvgDialog_43816_Content_46 = {
    Text = "Đúng vậy…… làm rất tốt."
  },
  AvgDialog_43816_Content_47 = {
    Text = "Trở thành lá trên cây, tránh khỏi tầm nhìn của những người đó, đừng để ánh mắt họ chạm tới bạn nữa."
