  AvgDialog_43816_Content_48 = {
    Text = "Đừng để những ánh mắt bẩn thỉu... chú ý đến bạn."
  },
  AvgDialog_43816_Content_5 = {
    Text = "Tỉnh giấc từ giấc ngủ sâu bởi tiếng nhạc, bốn chi vô lực theo bản năng nhẹ nhàng duỗi ra, nhưng đôi mắt lại cảm thấy đặc biệt nặng nề."
  },
  AvgDialog_43816_Content_6 = {
    Text = "Mi mắt trên và dưới dính chặt vào nhau, dù cố gắng thế nào cũng không thể mở ra được dù chỉ một khe hở nhỏ."
  },
  AvgDialog_43816_Content_7 = {
    Text = "Ứ… cảm giác này… là bước vào giấc mơ…"
  },
  AvgDialog_43816_Content_8 = {
    Text = "Trong tiếng nhạc chấn động tai, ý thức của bạn dần lấy lại sự kiểm soát thân thể, và ngay khi đôi mắt có thể cảm nhận được ánh sáng, tứ chi đột nhiên cứng ngắc."
  },
  AvgDialog_43816_Content_9 = {
    Text = "Nhảy rất tốt, các cô gái của tôi. Giữ vững phong độ này, theo đúng nhịp nhạc và tiếp tục — Ê! Đừng mất tập trung!"
  },
  AvgDialog_44435_Content_1 = {
    Text = "Sợi dây nguyền rủa đắng cay"
