  AvgDialog_44435_Content_2 = {
    Text = "Ký ức đi kèm với ánh sao lấp lánh hỗn loạn tuôn vào."
  },
  AvgDialog_44435_Content_3 = {
    Text = "Những ký ức bị tạo ra và cắt nhỏ một cách bạo lực ùa vào tâm trí của Mason, rồi nhanh chóng rút đi như thủy triều."
  },
  AvgDialog_44435_Content_4 = {
    Text = "Đến cuối cùng, cô ấy đến chân tuyết sơn, nơi có lối vào hang động tối đen."
  },
  AvgDialog_44435_Content_5 = {
    Text = "Dọc theo dòng sông chảy dọc theo chân, bạn sẽ đến được hang ổ của con quái vật đang say ngủ."
  },
  AvgDialog_44435_Content_6 = {
    Text = "Thùng thùng. Thùng thùng."
  },
  AvgDialog_44435_Content_7 = {
    Text = "Đó là tiếng đập tim trầm bổng như nhịp kim đồng hồ xưa cũ. Tiếng đập chung ấy, thuộc về cô và con quái vật, hòa quyện vào nhau."
  },
  AvgDialog_44435_Content_8 = {
    Text = "Tôi hiểu rồi.."
