  AvgDialog_44436_Content_1 = {
    Text = "Tại sao... tại sao.."
  },
  AvgDialog_44436_Content_10 = {
    Text = "Hạnh phúc vì cuộc sống đơn giản, là \"24\"."
  },
  AvgDialog_44436_Content_11 = {
    Text = "Bị Hiệp hội Điêu khắc gia hành hạ, cũng là [24]."
  },
  AvgDialog_44436_Content_12 = {
    Text = "Không… Nếu không phải vì sự hèn nhát của bạn, thì cũng đã không bị bác sĩ đó…"
  },
  AvgDialog_44436_Content_13 = {
    Text = "Suỵt……"
  },
  AvgDialog_44436_Content_14 = {
    Text = "Mason nhẹ nhàng bịt miệng của Shadow. Mason cúi đầu, thì thầm vào tai Shadow."
  },
  AvgDialog_44436_Content_15 = {
    Text = "Hãy để tôi kể cho bạn một bí mật: <Red:bác sĩ đó là do tôi giết>"
  },
  AvgDialog_44436_Content_16 = {
    Text = "Bạn làm sao mà có thể can đảm như vậy……!?"
  },
  AvgDialog_44436_Content_17 = {
    Text = "Giết người không phải là việc khó khăn gì. Tôi không có vũ khí bên mình, nên đã dùng tay đập vỡ đầu hắn như bể một trái dừa."
  },
  AvgDialog_44436_Content_18 = {
    Text = "Đến cuối cùng, tay tôi đã tê liệt, trong mắt ngoài máu không còn thấy gì khác."
  },
  AvgDialog_44436_Content_19 = {
    Text = "Bởi vì tôi phải đảm bảo anh ta chết hẳn. Chỉ cần anh ta còn một hơi thở, anh ta sẽ làm tổn thương những đứa trẻ ở nhà tế bần và Jenkin…"
  },
  AvgDialog_44436_Content_2 = {
    Text = "Bóng tối bị các ngươi đánh bại, cô ta gục xuống trong không gian ý thức, thân thể tỏa ra những hạt ánh sáng nhỏ li ti."
  },
  AvgDialog_44436_Content_20 = {
    Text = "Anh ta giống như những người trong Hiệp hội Điêu khắc gia, không —— anh ta còn đáng sợ hơn họ…"
  },
  AvgDialog_44436_Content_21 = {
    Text = "Anh ta là một con quỷ chính hiệu."
  },
  AvgDialog_44436_Content_22 = {
    Text = "Lúc đó, tôi đang làm gì nhỉ… chẳng lẽ tôi không biết gì cả sao…"
  },
  AvgDialog_44436_Content_23 = {
    Text = "(Mason) Mason nhẹ nhàng lắc đầu."
  },
  AvgDialog_44436_Content_24 = {
    Text = "Bạn thực ra đã biết, là bạn và những \"24\" khác đã truyền cho tôi lòng can đảm."
  },
  AvgDialog_44436_Content_25 = {
    Text = "Tất cả các \"24\" hợp lại mới tạo nên một \"Mason\". \"24\" không thể tồn tại riêng lẻ."
  },
  AvgDialog_44436_Content_26 = {
    Text = "Giống như tất cả các dòng sông đều đổ về một nơi, tất cả các \"24\" cũng sẽ tụ về một nơi..."
  },
  AvgDialog_44436_Content_27 = {
    Text = "Mason nhẹ nhàng hôn lên trán của bóng."
  },
  AvgDialog_44436_Content_28 = {
    Text = "Thuộc về tôi."
  },
  AvgDialog_44436_Content_29 = {
    Text = "Thân thể của bóng tối hóa thành những điểm sáng lấp lánh. Chúng tản ra xung quanh Mason, rồi tràn vào làn da của cô ấy."
  },
  AvgDialog_44436_Content_3 = {
    Text = "Với sức mạnh tuyệt vời của tôi, với sự tức giận tràn đầy của tôi…… sao tôi có thể thua các người, thua kẻ nhút nhát này……"
  },
  AvgDialog_44436_Content_30 = {
    Text = "Thì ra là vậy…… Tôi hiểu rồi."
