  },
  AvgDialog_44436_Content_61 = {
    Text = "<Shake:Đây là……những đứa trẻ mất tích từ viện tế bần! Không, không chỉ có vậy……>"
  },
  AvgDialog_44436_Content_62 = {
    Text = "Ở góc dưới cùng của tập hồ sơ lộ ra, khuôn mặt có phần bướng bỉnh của Jenkin xuất hiện trước mắt Mason."
  },
  AvgDialog_44436_Content_63 = {
    Text = "Đây là em gái của bạn phải không? Tôi đã gặp cô ấy. Cô ấy luôn lo lắng cho bạn, thậm chí còn cố gắng lẻn vào đây."
