  AvgDialog_44436_Content_64 = {
    Text = "Anh cười nhẹ, vẻ mặt cũng trở nên dịu dàng."
  },
  AvgDialog_44436_Content_65 = {
    Text = "Tôi cũng từng có rất nhiều anh chị em…… Chúng chỉ biết sợ hãi tôi, vì vậy tôi đã nuốt chửng chúng."
  },
  AvgDialog_44436_Content_66 = {
    Text = "Đều, ăn hết rồi…?"
