  AvgDialog_44436_Content_74 = {
    Text = "Á á á á á——!!"
  },
  AvgDialog_44436_Content_75 = {
    Text = "Mason cảm thấy chân mềm nhũn, ngã quỵ xuống đất một cách nặng nề."
  },
  AvgDialog_44436_Content_76 = {
    Text = "Bạn muốn… bạn muốn đưa Jenkin cũng…"
  },
  AvgDialog_44436_Content_77 = {
    Text = "Người đàn ông chỉnh lại gọng kính, lấy ra hồ sơ bệnh án và ghi chép vội vàng trên đó."
  },
  AvgDialog_44436_Content_78 = {
    Text = "Đồng tử giãn ra, cơ thể run rẩy dữ dội, nhịp tim tăng nhanh… Bạn bây giờ chắc chắn rất sợ hãi, lạnh không?"
