  AvgDialog_44436_Content_80 = {
    Text = "Rất nhanh, bạn sẽ ngất đi vì suy nghĩ quá mức dẫn đến thiếu máu lên não, giống như những con người nhàm chán khác."
  },
  AvgDialog_44436_Content_81 = {
