  },
  AvgDialog_44436_Content_87 = {
    Text = "Xác người đàn ông mềm dựa vào góc tường. Đầu của anh ta đã vỡ nát, từ đó không ngừng chảy máu."
  },
  AvgDialog_44436_Content_88 = {
