  },
  AvgDialog_44436_Content_89 = {
    Text = "Lời nguyền quấn quanh như con rắn, từ từ chuyển động. Thịt máu bị nghiền nát không ngừng tụ tập và tái tổ hợp…"
  },
  AvgDialog_44436_Content_9 = {
    Text = "Vì sinh kế mà bị khốn đốn, không có nơi để cầu cứu, là \"24\"."
