  AvgDialog_44439_Content_7 = {
    Text = "Không biết đã bao lâu, bạn nghe thấy tiếng cười mờ ảo, có người nắm lấy tay bạn. Bạn đáp lại hơi ấm quen thuộc mà đã lâu không cảm nhận."
  },
  AvgDialog_44439_Content_8 = {
    Text = "Mẹ. Chưa kịp gọi thành tiếng, nước mắt đã tuôn rơi trước."
