  AvgDialog_44440_Content_13 = {Text = "Ừ——"},
  AvgDialog_44440_Content_16 = {
    Text = "Dao sắc cắt đứt cổ họng, bạn run rẩy che vết thương không ngừng chảy máu, đầu óc hỗn loạn."
