  AvgDialog_44440_Content_24 = {
    Text = "Đầu của hắn thuộc về tôi, ai cũng đừng hòng cướp!!!"
  },
  AvgDialog_44440_Content_25 = {
    Text = "Biển cả phát ra một tiếng rung động ầm ỉ, gã khổng lồ che khuất mặt trời rực rỡ trước mắt bạn và sụp đổ trong tiếng động lớn."
  },
  AvgDialog_44440_Content_26 = {
    Text = "Máu của các ngươi tụ lại một chỗ, nhuộm biển xanh thành màu đỏ tươi rực."
  },
  AvgDialog_44440_Content_27 = {
    Text = "Tiếng gió, tiếng sóng biển, cùng với tiếng reo hò và ẩu đả từ xa truyền đến. Kế tiếp, điều chờ đón các ngươi sẽ chỉ là cuộc tàn sát và sỉ nhục không dứt."
  },
  AvgDialog_44440_Content_28 = {
    Text = "Nước biển mặn chát xâm nhập vào vết thương ở cổ, khiến bạn đau đớn đến mức không ngừng hít thở."
