  AvgDialog_44440_Content_32 = {
    Text = "……đồ vô dụng."
  },
  AvgDialog_44440_Content_4 = {
    Text = "Goliath đã kiệt sức. Ông ta lại một lần nữa vung cây kiếm khổng lồ trong tay, nhưng lần này, động tác chậm chạp của ông ta đã bị đối phương khai thác sơ hở."
