  AvgDialog_44811_Content_20 = {
    Text = "Quản lý vũ đoàn vạm vỡ mỉm cười nịnh bợ, chen lấn đến bên cạnh Liz."
  },
  AvgDialog_44811_Content_21 = {
    Text = "Liz lùi lại hai bước, tránh khỏi bàn tay của người quản lý đang với về phía cô ấy, như một con bướm vỗ cánh, thanh thoát và không để lại dấu vết."
