  AvgDialog_44811_Content_23 = {
    Text = "Đóng vai gì cao quý vậy? Nếu không có sự trọng dụng của ngài tước, tôi đã sớm xử lý đồ con gái hạ tiện này rồi…"
  },
  AvgDialog_44811_Content_24 = {
    Text = "Xem gì vậy! Còn không mau đi chuẩn bị cho điệu nhảy tiếp theo? Nếu làm cho các quý ông quý bà không hài lòng, thì người gặp xui xẻo chỉ có thể là các người!"
