  AvgDialog_44811_Content_25 = {
    Text = "Các cô gái rùng mình, nhưng cuối cùng không ai dám đối đầu với quản lý, tất cả đều ngoan ngoãn bò lên khỏi sân khấu và xếp lại đội hình nhảy."
