  AvgDialog_44812_Content_105 = {
    Text = "Bạn nhớ lại cuộc đối thoại với Liz được ghi lại trong hồ sơ của Đại học Misaque."
  },
  AvgDialog_44812_Content_106 = {
    Text = "Múa… là thuần khiết. Người nhảy thật sự nên dùng bước nhảy để thể hiện tâm hồn của mình, chứ không phải thân thể."
