  AvgDialog_44812_Content_11 = {
    Text = "Vâng, người sáng lập nhóm múa Salle chính là ông nội của tôi."
  },
  AvgDialog_44812_Content_110 = {
    Text = "Giúp bạn? Liz, bạn có kế hoạch gì không?"
