  AvgDialog_44812_Content_111 = {
    Text = "Tôi không muốn để tội lỗi của họ tiếp tục lây lan…… Tôi sẽ kết thúc nó ngay tại tôi."
  },
  AvgDialog_44812_Content_112 = {
    Text = "Được. Tôi sẽ giúp bạn, tôi cần làm gì."
