  AvgDialog_44812_Content_113 = {
    Text = "Liz vuốt ve khuôn mặt bạn, giọng điệu dần trở nên dịu dàng hơn, trong mắt hiện lên vài phần buồn bã và hối hận."
  },
  AvgDialog_44812_Content_114 = {
    Text = "Quản lý rất đề phòng tôi, anh ta chắc chắn sẽ không tin rằng tôi sẽ chủ động lên sân khấu…"
  },
  AvgDialog_44812_Content_115 = {
    Text = "Cô dùng hai ngón tay nhẹ nhàng nhấc túi băng đơn giản, đá đã tan gần hết, cả miếng vải ướt đến nỗi có thể vắt ra nước."
  },
  AvgDialog_44812_Content_116 = {
    Text = "Một cơn buồn ngủ vô cớ bỗng nhiên tràn đến, thậm chí hơi thở cũng bị chặn ở cổ họng ——"
  },
  AvgDialog_44812_Content_117 = {
    Text = "Liz… Elisabeth… bạn đã làm gì với tôi…"
  },
  AvgDialog_44812_Content_118 = {
    Text = "Bạn là người được ông ta chỉ định làm người đứng đầu, chỉ khi bạn vắng mặt, ông ta mới buộc phải cầu cứu tôi…"
  },
  AvgDialog_44812_Content_119 = {
    Text = "Liz dùng vải bịt miệng và mũi của bạn, một mùi vừa quen thuộc vừa khó chịu bắt đầu lan tỏa trong mũi."
  },
  AvgDialog_44812_Content_12 = {
    Text = "Ồ… thì ra là như vậy. Elizabeth, tôi có thể gọi bạn là Liz được không? Bạn rất thích nhảy múa?"
