  AvgDialog_44812_Content_120 = {
    Text = "Băng… thuốc…"
  },
  AvgDialog_44812_Content_121 = {
    Text = "……Không ngờ bạn có thể cắn viên băng lâu như vậy, cuối cùng thì nó cũng tan rồi."
  },
  AvgDialog_44812_Content_122 = {
    Text = "Bạn sẽ không sao đâu, tôi đã thấy quản lý dùng loại thuốc này để khiến những cô gái \"không nghe lời\" phải ngoan ngoãn… chỉ là ngủ một giấc mà thôi."
