  AvgDialog_44812_Content_123 = {
    Text = "Không sai, sau khi thức tỉnh, mọi thứ sẽ kết thúc……"
  },
  AvgDialog_44812_Content_13 = {
    Text = "Tôi rất thích nhảy múa, thưa ông. Chỉ cần nhìn một lần, tôi có thể nhớ được các bước nhảy, và khi tôi mười hai tuổi, tôi đã biên đạo cả một vở kịch múa."
  },
  AvgDialog_44812_Content_14 = {
    Text = "Ồ? Bạn còn biết biên đạo múa sao? Vậy đón nhận vở vũ kịch này ra sao?"
  },
  AvgDialog_44812_Content_15 = {
    Text = "Xin lỗi, giám đốc. Vở ballet của tôi chưa bao giờ được biểu diễn trên sân khấu. Bố mẹ luôn nói rằng nếu tôi tiếp tục nhảy múa, họ sẽ cắt đứt quan hệ với tôi, thậm chí ông đã đánh tôi nhiều lần vì điều này…"
  },
  AvgDialog_44812_Content_16 = {
    Text = "<Small:Không ngờ Sarle lại biết làm bộ làm tịch……>"
  },
  AvgDialog_44812_Content_17 = {
    Text = "Quản lý? Bạn vừa nói gì vậy?"
