  AvgDialog_44812_Content_99 = {
    Text = "Nháy mắt không kiểm soát được, nước mắt liền đọng trên mi, khiến thế giới trước mắt trở nên mờ nhòe."
  },
  AvgDialog_44833_Content_1 = {
    Text = "Bài ca thiên nga"
  },
  AvgDialog_44833_Content_10 = {
    Text = "Đây là mùi gì…… rất quen thuộc."
  },
  AvgDialog_44833_Content_11 = {
    Text = "Khoảnh khắc tay bạn chạm vào cửa, bạn cảm nhận được nhiệt độ bao trùm trong hành lang sau sân khấu, khói dày đặc cũng theo khe hở tràn vào phòng."
  },
  AvgDialog_44833_Content_12 = {
    Text = "Cháy rồi?!"
  },
  AvgDialog_44833_Content_13 = {
    Text = "Dựa trên kiến thức thông thường, cánh cửa phòng không thể chịu đựng được lâu. Nếu cấu trúc của nhà hát này chỉ đơn thuần là gỗ, thì cả tòa nhà sẽ nhanh chóng chìm trong biển lửa."
  },
  AvgDialog_44833_Content_14 = {
    Text = "Để rời khỏi phòng, nhưng không thể ra vào qua cửa — tầm nhìn của bạn chuyển sang cửa sổ duy nhất. \nNếu Liz có thể vào bằng cửa sổ, bạn cũng có thể ra bằng cửa sổ."
  },
  AvgDialog_44833_Content_15 = {
    Text = "Dưới cửa sổ quả nhiên đậu một chiếc xe ngựa, bạn leo qua cửa sổ, dẫm lên nóc xe ngựa và dễ dàng rời khỏi phòng ở tầng hai."
  },
  AvgDialog_44833_Content_16 = {
    Text = "Bạn theo tiếng động quanh đến quảng trường trước nhà hát. Quảng trường náo nhiệt, những vị khách mặc quần áo lộng lẫy chen lấn nhau chạy đua để thoát khỏi nhà hát——"
  },
  AvgDialog_44833_Content_17 = {
    Text = "Đi đi! Tôi là người hầu của bá tước Jeffrey, hãy để tôi đi trước!"
  },
  AvgDialog_44833_Content_18 = {
    Text = "Điên rồi! cô ấy điên rồi!"
  },
  AvgDialog_44833_Content_19 = {
    Text = "Bạn nhanh nhẹn bắt được quý bà chạy đến mức búi tóc xổ tung."
  },
  AvgDialog_44833_Content_2 = {
    Text = "Tách tách."
  },
  AvgDialog_44833_Content_20 = {
    Text = "Thưa bà, có chuyện gì xảy ra trong nhà hát?"
  },
  AvgDialog_44833_Content_21 = {
    Text = "Bạn là vũ công?! Đừng có đụng vào tôi! Bạn và người phụ nữ điên trong Nhà hát thứ hai là đồng bọn phải không!"
  },
  AvgDialog_44833_Content_22 = {
    Text = "Sân khấu thứ hai... là Liz sao? Có phải là Elizabeth không? Cô gái mặc váy múa màu đen?"
  },
  AvgDialog_44833_Content_23 = {
    Text = "Bạn biết tên điên đó! Còn nói bạn không phải đồng bọn của cô ta! Nhanh lên! Đánh chết vũ công này ngay!"
  },
  AvgDialog_44833_Content_24 = {
    Text = "Tạp dịch và một số người đi đường nhìn nhau, rõ ràng không muốn vì quý tộc mà vi phạm pháp luật."
  },
  AvgDialog_44833_Content_25 = {
    Text = "Tôi sẽ thưởng 100 Reo phường cho người đầu tiên cắt đầu!Không, 300 Reo phường!"
  },
  AvgDialog_44833_Content_26 = {
    Text = "Số tiền lớn đã được ném về phía những người hầu vẫn còn co ro, khiến họ cầm công cụ lao vào bạn——"
  },
  AvgDialog_44833_Content_3 = {
    Text = "Bạn ôm đầu từ từ tỉnh lại, không biết đã qua bao lâu, bên ngoài cửa sổ vẫn là đêm tối. \nCó thể chỉ ngất đi nửa giờ, cũng có thể đã nằm cả ngày."
  },
  AvgDialog_44833_Content_4 = {
    Text = "Là mùi của ether nồng độ cao… Không ngờ giám đốc lại đóng băng thứ nguy hiểm này trong khối băng."
  },
  AvgDialog_44833_Content_6 = {
    Text = "Liz vừa vào đã cho tôi viên đá, nên… dù tôi có nói gì đi chăng nữa, từ đầu cô ấy đã quyết định sẽ cho tôi uống thuốc…"
  },
  AvgDialog_44833_Content_7 = {
    Text = "Elizabeth Salle, Liz… bạn rốt cuộc muốn làm gì?"
  },
  AvgDialog_44833_Content_8 = {
    Text = "Tách tách."
  },
  AvgDialog_44833_Content_9 = {
    Text = "Một loại hương thơm tự nhiên nguyên thủy xông chiếm mũi, xông thẳng vào sâu não, ép đi lực lượng còn lại của thuốc."
  },
  AvgDialog_44835_Content_1 = {
    Text = "Bạn dồn hết can đảm mở cửa nhà hát thứ nhất. Mặc dù ngọn lửa chưa lan đến đây, nhưng khói dày đặc và làn sóng nhiệt ào tới, khiến mắt bạn cảm thấy rát buốt."
  },
  AvgDialog_44835_Content_10 = {
    Text = "Vũ công run rẩy dữ dội như vừa nghe thấy tên ác quỷ."
  },
  AvgDialog_44835_Content_11 = {
    Text = "Elizabeth, Elizabeth! Cô ấy đã phát điên rồi! Cô ấy đã bỏ thuốc vào thức ăn của khán giả và những người khác! Mọi người đều đã ngất đi!"
  },
  AvgDialog_44835_Content_12 = {
    Text = "Chỉ có tôi, một người béo không được phép ăn, và một số quý bà muốn giữ vóc dáng nên không ăn gì, đã thoát ra được……"
  },
  AvgDialog_44835_Content_13 = {
    Text = "Ê! Ê, đừng chạy! Đã bảo đừng vào rồi!"
  },
  AvgDialog_44835_Content_14 = {
    Text = "Bạn phớt lờ lời khuyên của vũ công, lao thẳng về phía nhà hát thứ hai với quyết tâm không gì lay chuyển."
  },
  AvgDialog_44835_Content_15 = {
    Text = "@2 vườn hoa thứ hai"
  },
  AvgDialog_44835_Content_16 = {Text = "Liz!"},
  AvgDialog_44835_Content_17 = {
    Text = "Đẩy cửa nhà hát thứ hai ra, cảnh tượng khiến máu trong người bạn như đóng băng ngay lập tức. Khách mời và vũ công nằm mất ý thức trên mặt đất, sống chết chưa rõ."
  },
  AvgDialog_44835_Content_18 = {
    Text = "Sảnh đường từng rộn ràng tiếng cốc chén va chạm nay im lặng, lưỡi lửa bùng lên khắp nơi, chỉ có những khu vực treo dấu rỗng rỗng mới được miễn nhiễm —— trên thế giới này, cũng có những thứ mà ngọn lửa không thể tiêu thụ."
  },
  AvgDialog_44835_Content_19 = {
    Text = "Bạn không nên đến đây."
  },
  AvgDialog_44835_Content_2 = {
    Text = "Khụ, khụ khụ…"
  },
  AvgDialog_44835_Content_20 = {
    Text = "Liz đứng ở góc sân khấu, bạn không thể nhìn thấy cô ấy, chỉ có giọng nói vọng đến từ xa, cách nửa rạp hát."
  },
  AvgDialog_44835_Content_21 = {
    Text = "Liz, ngọn lửa này do bạn gây ra à?"
  },
  AvgDialog_44835_Content_22 = {
    Text = "Hai tiếng cười méo mó vang lên từ phía sân khấu, bạn cũng biết rằng câu hỏi này quá mờ nhạt. \nDù Liz có phải là người châm ngòi hay không, kết cục của cô ấy và \"bạn\" đã không thể thay đổi được nữa."
  },
  AvgDialog_44835_Content_23 = {
    Text = "█A.F.29@1 năm @2 Vụ cháy lớn tại Nhà hát Hoa viên Thứ hai bùng phát khi đang biểu diễn vở ballet 《Thiên Nga Tuyệt Ca》. \n█Bao gồm bá tước Elbert, tổng cộng có 13 quý tộc, 25 người hầu, 12 vũ công và 1 quản lý đoàn vũ bị thiệt mạng trong đám cháy. \n█Qua điều tra, kẻ phóng hỏa chính là nữ chính ballet trong danh sách tử vong 「Elizabeth Salle」."
  },
  AvgDialog_44835_Content_24 = {
    Text = "Liz không trả lời bạn, cô ấy vẫn quay lưng lại với bạn, một tay lắc qua lại, dường như đang lên dây cót cho thứ gì đó."
  },
  AvgDialog_44835_Content_25 = {
    Text = "Được rồi."
  },
  AvgDialog_44835_Content_26 = {
    Text = "Cô ấy bước hai bước về phía trước, đứng vững ở trung tâm sân khấu, âm nhạc du dương tuôn trào, hòa quyện với tiếng lửa tí tách bập bùng."
  },
  AvgDialog_44835_Content_27 = {
    Text = "Lời từ biệt thực sự của \"Bài ca thiên nga\" chỉ có thể được thực hiện bằng cách kết hợp với máy hát."
  },
  AvgDialog_44835_Content_28 = {
    Text = "Bạn đã để nhạc công rời đi, vì họ vô tội, phải không?"
  },
  AvgDialog_44835_Content_29 = {
    Text = "Bạn cũng có thể rời đi, tôi đã quan sát bạn trong một thời gian dài, bạn không trở thành đồng lõa của họ."
  },
  AvgDialog_44835_Content_3 = {
    Text = "Bạn xé một mảnh khăn bàn, làm đổ bình hoa cảnh quan, và dùng nước tưới cây để làm ướt khăn bàn."
  },
  AvgDialog_44835_Content_30 = {
    Text = "Tôi... không đúng, tôi đã xúc phạm đến nghệ thuật của bạn. Bạn quên rồi sao, tôi suýt nữa đã hủy hoại bản \"Thiên Nga Ca Ngạo\" của bạn."
  },
  AvgDialog_44835_Content_31 = {
    Text = "Liz quỳ trên sân khấu, đưa tay ra hiệu cho bạn tiến lại gần. Bạn chợt nhận ra sân khấu đã phủ đầy chất nhầy đen — có phải là Phân rã không?"
  },
  AvgDialog_44835_Content_32 = {
    Text = "Bạn vừa bước hai bước về phía cô ấy thì một cơn gió thổi tung cửa sổ nhà hát. Ngọn lửa vốn âm thầm cháy trong bóng tối bỗng chốc bùng lên, những lưỡi lửa cuồn cuộn lan nhanh và táp vào màn sân khấu."
  },
  AvgDialog_44835_Content_33 = {
    Text = "Liz! Nhanh xuống đi, lửa bùng lên rồi!"
  },
  AvgDialog_44835_Content_34 = {
    Text = "Cánh cửa của sân khấu thứ hai sụp đổ ầm ầm, các thanh gỗ bị carbon hóa rơi xuống đất, làm bốc lên tro carbon và tia lửa, đồng thời làm tấm thảm len bùng cháy."
  },
  AvgDialog_44835_Content_35 = {
    Text = "Liz, Elizabeth! Đừng có dại, mau chạy đi với tôi, còn kịp đấy!"
  },
  AvgDialog_44835_Content_36 = {
    Text = "Nếu cho thế giới một cơ hội nữa… Sau ba mươi năm, vũ đạo sẽ là một trong những nghệ thuật tinh khiết nhất, chỉ cần cho thế giới thêm một chút thời gian…"
  },
  AvgDialog_44835_Content_37 = {
    Text = "Liz nằm bên cạnh sân khấu, lại một lần đưa tay ra phía bạn."
  },
  AvgDialog_44835_Content_38 = {
    Text = "Bàn tay cô ấy dính đầy rỗng rỗng, nhưng khi áp vào má bên của bạn, vẫn thực sự truyền đến hơi ấm của một người sống."
  },
  AvgDialog_44835_Content_39 = {
    Text = "Tôi biết rằng hôm nay tôi không thể chấm dứt những tội ác này…… Tôi đã hiểu điều này ngay từ đầu."
  },
  AvgDialog_44835_Content_4 = {
    Text = "Dùng vải ướt bịt kín miệng và mũi, hơi nước mang theo mùi tanh của đất và rễ cây đã được hít vào phổi. Bạn gập người xuống thấp, dò dẫm trên thảm để tiến lên một cách chậm rãi."
  },
  AvgDialog_44835_Content_40 = {
    Text = "Điều tôi muốn là để thế giới thấy bóng tối. Tôi muốn ánh sáng chói vào, nhưng ngoài cách này, tôi không còn lựa chọn nào khác."
  },
  AvgDialog_44835_Content_41 = {
    Text = "Nói xong, cô ấy dồn hết sức đẩy bạn ra mạnh mẽ."
  },
  AvgDialog_44835_Content_42 = {
    Text = "Xin lỗi, tôi đã cho bạn uống thuốc mà không bàn trước."
  },
  AvgDialog_44835_Content_43 = {
    Text = "Bạn thật sự không rời đi sao? Nhảy xuống từ cửa sổ còn kịp mà."
  },
  AvgDialog_44835_Content_44 = {
    Text = "Bạn lắc đầu, ôm chân ngồi xuống bên mép sân khấu."
  },
  AvgDialog_44835_Content_45 = {
    Text = "Bạn đã đếm số người mặc váy diễn trong nhà hát, bao gồm Liz, tổng cộng chỉ có 11 người."
  },
  AvgDialog_44835_Content_46 = {
    Text = "Bạn là người thứ 12 bị chôn vùi trong biển lửa."
  },
  AvgDialog_44835_Content_47 = {
    Text = "Được, vậy cứ nhìn kỹ tôi nhé."
  },
  AvgDialog_44835_Content_48 = {
    Text = "Elizabeth·Salle(Elizabeth Salle), mang đến điệu múa đơn \"Khúc ca thiên nga cuối cùng\"."
  },
  AvgDialog_44835_Content_49 = {
    Text = "Liz cúi mình trước bạn, tiện tay vén màn rèm đang bốc cháy, dung dịch rỗng rỗng trên tay và người cô lập tức bùng lên —— không, đó là nhựa đường."
  },
  AvgDialog_44835_Content_5 = {
    Text = "—— Ối!"
  },
  AvgDialog_44835_Content_50 = {
    Text = "Ngọn lửa đỏ rực bừng nở trong im lặng trên tà váy, đó là đôi cánh rung động trong khoảnh khắc thiên nga thoát khỏi bụi bẩn."
  },
  AvgDialog_44835_Content_51 = {
    Text = "Liz quay nhẹ nhàng, mỗi lần quay đều đưa cô gần hơn với những sao băng bay qua bầu trời đêm."
  },
  AvgDialog_44835_Content_52 = {
    Text = "Cô con gái của nghệ thuật đang hét lên chương cuối cùng của cuộc sống, ngọn lửa bùng cháy trên sân khấu, nhưng trong mắt cô không có chút sợ hãi nào."
  },
  AvgDialog_44835_Content_53 = {
    Text = "Ngọn lửa gặm nhấm và thiêu rụi máy hát thành tro bụi, nốt nhạc cuối cùng tan biến trong biển lửa, hình bóng của cô ấy cũng dần mờ đi trong ánh lửa."
  },
  AvgDialog_44835_Content_54 = {
    Text = "Trong khoảnh khắc cuối cùng được ngọn lửa ôm trọn, một câu chuyện đã tìm thấy kết cục, một thời đại đã bước tới hồi kết."
  },
  AvgDialog_44835_Content_6 = {
    Text = "Cô gái đang chạy đã va phải bạn, cả hai ngã dúi dụi."
