  AvgDialog_44835_Content_8 = {
    Text = "Bạn có ấn tượng về cô vũ công này, trong mô tả của Liz, cô ấy dường như là một người đặc biệt nhiệt tình."
  },
  AvgDialog_44835_Content_9 = {
    Text = "Liz có ở bên trong không?"
  },
  AvgDialog_45413_Content_11 = {
    Text = "Việc sở hữu dung mạo này, tôi đã lâu không còn nhớ lại nữa."
  },
  AvgDialog_45413_Content_12 = {
    Text = "Là vì nghe thấy tên người đàn ông đó, hay dòng hồi tưởng cuối đời khi cận kề cái chết?"
  },
  AvgDialog_45413_Content_13 = {
    Text = "Kí ức từ rất lâu rất lâu trước đây, bỗng nhiên lóe lên trong tâm trí tôi."
  },
  AvgDialog_45413_Content_14 = {
    Text = "Trước khi trở thành \"Quái vật\", tôi chỉ là một thám tử bình thường sống trong cuộc sống hàng ngày, sau khi nhận được tiền đặt cọc sẽ đi uống vài ly và thử vận may một chút."
  },
  AvgDialog_45413_Content_15 = {
    Text = "Vì may mắn hơn người thường, thám trưởng ở Lentiennam thường mời tôi hỗ trợ thu thập manh mối và truy tìm nghi phạm."
  },
  AvgDialog_45413_Content_16 = {
    Text = "Hoa hồng đưa đến cửa không có lý do gì để không lấy."
  },
  AvgDialog_45413_Content_17 = {
    Text = "Cho đến khi tên tội phạm mà tôi bắt giữ biến mất một cách bí ẩn trong trại giam, chỉ để lại đôi còng tay bạc vẫn khóa chặt, hình dáng nguyên vẹn, phát ra tiếng leng keng trong gió."
  },
  AvgDialog_45413_Content_18 = {
    Text = "Tất nhiên, điều đó không liên quan đến tôi. Tôi chỉ thường xuyên đến sòng bạc ngầm với ánh đèn mờ ảo và rượu đỏ để tiêu thụ số tiền hoa hồng vừa nhận được."
  },
  AvgDialog_45413_Content_19 = {
    Text = "Bạn là… kẻ trốn thoát!"
  },
  AvgDialog_45413_Content_2 = {
    Text = "Một chiếc móng câu trong suốt khổng lồ hiện ra ở trên không trung, rồi đập mạnh Lắc vào tường."
  },
  AvgDialog_45413_Content_20 = {
    Text = "À, đã bắt được tôi rồi sao?"
