  AvgDialog_45413_Content_21 = {
    Text = "Tôi không ngại đi theo cậu về và ngồi thêm hai ngày trong tù ——"
  },
  AvgDialog_45413_Content_22 = {
    Text = "Người đàn ông lắc cái chén xúc xắc bên tay."
  },
  AvgDialog_45413_Content_23 = {
    Text = "Nhưng bạn phải thắng tôi trước."
