  },
  AvgDialog_45413_Content_53 = {
    Text = "Tò mò đến mức đánh đổi cả mạng sống, mọi người gọi tôi là điên, tôi không biết ai trong chúng ta mới thật sự điên."
  },
  AvgDialog_45413_Content_54 = {
