  AvgDialog_45416_Content_25 = {Text = "Không tin"},
  AvgDialog_45416_Content_26 = {
    Text = "Bạn chưa kịp mở miệng, Thái Di Sơ đã tiến lại gần, ngón tay trỏ khẽ chạm vào đỉnh môi bạn."
