  AvgDialog_45417_Content_18 = {
    Text = "Rồi, một cái ôm ấm áp và mềm mại bất ngờ dành cho bạn."
  },
  AvgDialog_45417_Content_19 = {
    Text = "Con ngoan, bạn đã làm rất tốt."
  },
  AvgDialog_45417_Content_2 = {
    Text = "Người đầu tiên tiến hóa ra cổ họng phát ra một tiếng rên rỉ, vất vả thoát khỏi cây mẹ, rơi từ trên cao xuống sông thiêng liêng."
  },
  AvgDialog_45417_Content_20 = {
    Text = "Ngực cô ấy, viên bạch ngọc mà bạn đã đeo lên tay, tỏa sáng bên làn da mềm mại tựa lụa là."
  },
  AvgDialog_45417_Content_21 = {
    Text = "Thái Di Sơ đưa tay hái nó xuống, nuốt vào miệng, nhẹ nhàng cắn một miếng nhỏ."
  },
  AvgDialog_45417_Content_22 = {
    Text = "Tôi sẽ trở về sông thiêng liêng, nuôi dưỡng cả vùng đất. \nĐây là món quà chia tay dành cho bạn."
  },
  AvgDialog_45417_Content_23 = {
    Text = "Trong khoảnh khắc rơi xuống dòng sông thiêng cuồn cuộn, môi cô ấy chạm vào môi bạn."
  },
  AvgDialog_45417_Content_24 = {
    Text = "Hơi thở của các bạn đan xen, linh hồn hợp nhất."
  },
  AvgDialog_45417_Content_25 = {
    Text = "Đầu lưỡi nhẹ nhàng đẩy vào, mang theo hơi ấm và độ ẩm mượt mà, tràn đầy tình cảm dịu dàng và không thể chối từ."
  },
  AvgDialog_45417_Content_26 = {
    Text = "Nụ hôn ấy pha lẫn vị ngọt ngào của tình yêu, mùi tanh của máu, và một vật nhỏ, tròn trĩnh."
  },
  AvgDialog_45417_Content_27 = {
    Text = "Hạt giống cây."
