  AvgDialog_45418_Content_2 = {
    Text = "Nhưng mà…"
  },
  AvgDialog_45418_Content_20 = {
    Text = "Không biết từ lúc nào, Dư Lệ Ét đã trở lại. \nCô ấy xuất hiện sau cánh cửa sắt, bước qua tầng tầng bậc đá tiến về phía các bạn."
  },
  AvgDialog_45418_Content_21 = {
    Text = "Vì đều là người can thiệp vào bí ẩn, tôi sẽ hỏi thẳng: Đại học Misag có hiểu biết gì về ba chất thể lớn không?"
  },
  AvgDialog_45418_Content_22 = {
    Text = "Ramona và Lắc cùng nhìn về phía bạn. \nCân nhắc thái độ của Dư Li-ét suốt quãng đường, bạn ngập ngừng một lát rồi gật đầu."
  },
  AvgDialog_45418_Content_23 = {
