  },
  AvgDialog_45418_Content_24 = {
    Text = "Sở vị xác chết cây thánh……là chất thể <Yellow:Tifrayesod> được ướp xác."
  },
  AvgDialog_45418_Content_25 = {
    Text = "Đối với người Aran, điều quan trọng nhất là chất lỏng tích tụ trong quan tài này."
