  AvgDialog_45418_Content_28 = {
    Text = "Sức mạnh của thần Tevreyesod khiến sự xói mòn của sự rỗng rỗng cực kỳ chậm. Người Aran đã khai thác từ đó nguồn sức mạnh để tái sinh và phát triển."
