  AvgDialog_45418_Content_34 = {
    Text = "Do cây mẹ biến mất, thần lực suy yếu, nên tỷ lệ thai nhi dị tật ngày càng tăng."
  },
  AvgDialog_45418_Content_35 = {
    Text = "Bạn cũng đã nhận ra rồi phải không? Những làn sương đen tan rã bốc lên từ người của những người Aran."
  },
  AvgDialog_45418_Content_36 = {
