  },
  AvgDialog_45418_Content_52 = {
    Text = "Lực lượng của ba chất thể sẽ tương khắc lẫn nhau, nguồn nước của Lemvahi bắt nguồn từ chất thể dục vọng, đối với Ramona, bản thân nó chính là độc dược."
  },
  AvgDialog_45418_Content_53 = {
    Text = "Càng tiến về phía trước, càng gần nơi khởi nguồn của sông thiêng liêng, tác động của sự xung khắc càng trở nên mạnh mẽ."
  },
  AvgDialog_45418_Content_54 = {
    Text = "Người Aran ngày mai sẽ lại cố gắng một lần nữa đột phá Tường Bão."
  },
  AvgDialog_45418_Content_55 = {
    Text = "Ramona phải ở bên ngoài Tường Bão."
  },
  AvgDialog_45418_Content_56 = {
    Text = "Đường tiếp theo, do ba người chúng ta đi."
  },
  AvgDialog_45418_Content_57 = {
    Text = "Không thể nào, tôi cũng là một thành viên của Misaque, điều này không thể xảy ra……"
  },
  AvgDialog_45418_Content_58 = {
    Text = "Ramona cố gắng đứng dậy từ giường, lảo đảo rồi run rẩy, suýt nữa ngã quỵ xuống."
  },
  AvgDialog_45418_Content_59 = {
    Text = "Ramona, trạng thái thân thể của bạn không phù hợp để đi cùng chúng tôi."
  },
  AvgDialog_45418_Content_6 = {Text = "Ê——"},
  AvgDialog_45418_Content_60 = {
    Text = "Bạn kéo chăn cho cô ấy. \nCô gái bị làn sóng nhiệt tấn công run rẩy nhìn bạn với vẻ khó chịu, không nói gì."
  },
  AvgDialog_45418_Content_61 = {
    Text = "Các cậu đừng có mà bỏ tôi lại một mình…"
  },
  AvgDialog_45418_Content_7 = {
    Text = "Hãy để họ đi, Tàn dư cây thiêng vẫn ở đây, không thể đảm bảo không phải là một kế hoạch đánh lạc hướng."
  },
  AvgDialog_45418_Content_8 = {
    Text = "Kassia lắc lọ chứa chất lỏng đen sẫm trong tay."
  },
  AvgDialog_45418_Content_9 = {
    Text = "Thật sự chỉ vậy thôi chứ? Tôi có thể vớt cả cái quan tài lên luôn."
  },
  AvgDialog_45419_Content_1 = {
    Text = "Hiệp hội Điêu khắc gia thí nghiệm khổng lồ đổ sập, không khí tràn ngập mùi sắt rỉ khó chịu."
  },
  AvgDialog_45419_Content_10 = {
    Text = "Trên lãnh địa của Á Lan, việc quan trọng nhất hẳn là không do các vị định đoạt."
  },
  AvgDialog_45419_Content_11 = {
    Text = "Âm thanh tức giận vang vọng trong không gian trống rỗng của nhà máy. \n Trưởng tộc Aran dẫn dắt hàng chục chiến binh Aran, hoàn toàn chặn bạn lại trong đống đổ nát này."
  },
  AvgDialog_45419_Content_12 = {
    Text = "Những người lính mà các người giấu bên ngoài nhà máy không biết từ lúc nào đã cởi trói, theo sau cô ấy và chỉ về phía các người."
  },
  AvgDialog_45419_Content_13 = {
    Text = "Tôi nghĩ, chúng ta đã không còn gì để thương lượng nữa, người lạ."
  },
  AvgDialog_45419_Content_2 = {
    Text = "……không có xác chết ở đây."
  },
  AvgDialog_45419_Content_3 = {
    Text = "Không, đã từng ở đây."
  },
  AvgDialog_45419_Content_4 = {
    Text = "Đầu ngón tay của Lắc nhẹ nhàng lướt qua mặt đất, giơ tay lên vò vò, rồi thổi một hơi.\nBụi trần Dispersi từ đôi găng tay đen, múa lượn trong ánh sáng chiếu qua khung cửa sổ."
  },
  AvgDialog_45419_Content_5 = {
    Text = "Độ dày của bụi không đồng đều, còn có những dấu chân vừa đủ để nhận ra."
  },
  AvgDialog_45419_Content_6 = {
    Text = "Cái bóng từ cửa sổ bị vỡ in hắt lên bệ xi măng còn dấu vết hình quan tài. \nCòn quan tài thì đã biến mất."
  },
  AvgDialog_45419_Content_7 = {
    Text = "Chúng ta nên nghĩ đến —— Bà Daphne sẽ không hài lòng chỉ bán thông tin với một mức giá duy nhất."
  },
  AvgDialog_45419_Content_8 = {
    Text = "Có lẽ cô ấy nên cân nhắc báo giá độc quyền mua đứt?"
  },
  AvgDialog_45419_Content_9 = {
    Text = "Hãy gác lại sự hài hước không cần thiết của bạn, bây giờ điều quan trọng nhất là tung tích của di hài cây mẹ."
  },
  AvgDialog_45420_Content_1 = {
    Text = "Thưa ngài Elva, xin hãy cho tôi nói vài lời với {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_45420_Content_10 = {
    Text = "Dáng vẻ của cô ấy khác thường cuồng nhiệt, tốc độ nói cực nhanh, cơ thể không kiềm chế được mà ngả về phía trước, ánh mắt ma quái."
  },
  AvgDialog_45420_Content_11 = {
    Text = "Tạm biệt, mắt vô hình."
  },
  AvgDialog_45420_Content_13 = {
    Text = "Không, điều này vẫn chưa phải là kết thúc. Vì người đó đã từng dùng giọng nói tha thiết nhất, nhắc nhở bạn một cách tha thiết gọi tên cô ấy."
  },
  AvgDialog_45420_Content_14 = {
    Text = "Nhớ lại ánh mắt của Thái Di Sơ, bạn liền kích hoạt chìa khóa bạc."
  },
  AvgDialog_45420_Content_15 = {
    Text = "Sợi chỉ bạc rung rinh, kéo dắt, tìm kiếm…"
  },
  AvgDialog_45420_Content_16 = {
    Text = "Ở tận cùng sợi chỉ đó, chẳng có gì cả."
  },
  AvgDialog_45420_Content_17 = {
    Text = "Hiện tượng tan biến đã nuốt chửng cô hoàn toàn, thậm chí bạn cũng không thể tìm thấy bóng dáng của cô."
  },
  AvgDialog_45420_Content_18 = {
    Text = "Cô ta còn có thể trở lại không? Người Aran đã tuân lệnh tôi rồi."
  },
  AvgDialog_45420_Content_19 = {
    Text = "Thái Di Sơ…… Thái Di Sơ!"
  },
  AvgDialog_45420_Content_2 = {
    Text = "Bạn và Elva đang căng thẳng không ai nhường ai, Yu Li-ét lên tiếng ngăn cản."
  },
  AvgDialog_45420_Content_20 = {
    Text = "Nếu cô ấy có thể xuất hiện, nếu cô ấy có thể dùng sức mạnh thần thánh của mình để chỉ cho Elva thấy tương lai của tộc Aran."
  },
  AvgDialog_45420_Content_21 = {
    Text = "Dù chỉ là giải thích, bạn cũng không cần phải ở đây, đối đầu với Elva bằng vũ khí."
  },
  AvgDialog_45420_Content_22 = {
    Text = "Thái Di Sơ…… Thái Di Sơ—— !"
  },
  AvgDialog_45420_Content_23 = {
    Text = "Dù có kêu gọi thế nào đi chăng nữa, cuộc đối thoại cuối cùng giữa bạn và cô ấy vẫn dừng lại ở những lời buộc tội."
  },
  AvgDialog_45420_Content_24 = {
    Text = "Sự tồn tại đã bị rỗng rỗng hòa tan, không có vết tích tiếp xúc của bạc tâm, bạn không thể chạm tới cô ấy dù chỉ một chút."
  },
  AvgDialog_45420_Content_26 = {
    Text = "Sao nào, hành trình quá khứ đã khiến bạn quá tự hào sao?"
  },
  AvgDialog_45420_Content_27 = {
    Text = "Hay là khi rời xa tôi, anh sẽ biến thành kẻ yếu đuối chỉ biết khóc nhè?"
  },
  AvgDialog_45420_Content_28 = {
    Text = "Dù sao đi nữa, ngay cả khi đã mất hết đồng đội, bạn vẫn có thể một mình đến được đây, sự kiên trì này vẫn luôn đáng được tán dương."
  },
  AvgDialog_45420_Content_29 = {
    Text = "Vì vậy, hãy để tôi cho cô ấy và bạn mượn năng lực của mình."
  },
  AvgDialog_45420_Content_3 = {
    Text = "Nếu bạn đã quyết tâm như vậy."
  },
  AvgDialog_45420_Content_30 = {
    Text = "Sự yên bình của sa mạc bị phá vỡ bởi một tiếng gió gấp gáp, bầu trời nhanh chóng trở nên tối sầm, dường như mọi ánh sáng đều bị cơn thịnh nộ sắp tới nuốt chửng."
  },
  AvgDialog_45420_Content_31 = {
    Text = "Cơn bão cát như một con quái vật bị giật mình nổi giận, gầm rú cuốn theo hàng triệu tấn cát mịn, che khuất bầu trời, khiến mặt trời và bầu trời xanh cùng bị tiêu diệt."
  },
  AvgDialog_45420_Content_32 = {
    Text = "Trong sức mạnh điên cuồng của tự nhiên, có một hình dáng khổng lồ chập chờn, không ngừng lóe sáng trong làn bụi cát."
  },
  AvgDialog_45420_Content_33 = {
    Text = "Tường Bão……"
  },
  AvgDialog_45420_Content_34 = {
    Text = "Tường Bão, vốn dĩ là vật được triệu hồi nhờ quyền năng của ta."
  },
  AvgDialog_45420_Content_35 = {
    Text = "Bạn là…… Thái Di Sơ……?"
  },
  AvgDialog_45420_Content_36 = {
    Text = "Nó dường như sở hữu lực lượng vô tận, cùng với sự điên cuồng của cát bụi, bóng đen đó cũng nhảy múa và vặn vẹo, giống như một con quái vật sa mạc cổ đại, săn lùng mồi trong cơn bão cát."
  },
  AvgDialog_45420_Content_37 = {
    Text = "Hình dạng của nó to lớn và kinh khủng, đầu lớn uốn lượn, móng vuốt sắc nhọn và bốn vó nặng nề, đều có thể thấy mờ ảo trong cơn bụi mù mịt."
  },
  AvgDialog_45420_Content_38 = {
    Text = "Cách gọi này cũng không hẳn là sai đâu."
  },
  AvgDialog_45420_Content_39 = {
    Text = "Nhưng tôi không phải là vị nữ hoàng mà bạn mong đợi."
  },
  AvgDialog_45420_Content_4 = {
    Text = "Vệ binh, đừng để họ làm tổn thương đến một sợi lông của vị sứ giả."
  },
  AvgDialog_45420_Content_40 = {
    Text = "Nếu muốn mượn lực lượng của tôi, hãy lớn tiếng niệm tên thánh của tôi. \nTôi là thể chất của dục vọng ——"
  },
  AvgDialog_45420_Content_41 = {
    Text = "Đó là cái bóng lớn lao và kỳ dị dần dần tan biến, hình bóng mà bạn khao khát nhưng không thể với tới bước ra từ cơn bão cát gào thét."
  },
  AvgDialog_45420_Content_42 = {
    Text = "Hạt cát vô tình gào thét và cuồng loạn nhảy múa xung quanh cô, nhưng không thể lay chuyển bước chân của cô."
  },
  AvgDialog_45420_Content_44 = {
    Text = "Nữ hoàng! Là Nữ hoàng trở về!"
  },
  AvgDialog_45420_Content_45 = {
    Text = "Nữ hoàng, ánh mắt của nữ hoàng luôn nhìn vào chúng ta!"
  },
  AvgDialog_45420_Content_46 = {
    Text = "Ánh mắt cô luôn hướng về Aran, dõi theo dòng chảy của quá khứ và tương lai trong huyết mạch."
  },
  AvgDialog_45420_Content_47 = {
    Text = "Thái Di Sơ…… đại nhân……"
  },
  AvgDialog_45420_Content_48 = {
    Text = "Tất cả người dân tộc Aran, hãy nghe lệnh! Tiên tri cổ xưa đã ứng nghiệm, cây mẹ tái hiện trên thế gian, hãy trao vinh quang cho những người đã khuất!"
  },
  AvgDialog_45420_Content_49 = {
    Text = "Nữ hoàng bước qua cát trở về, tái vị trên ngai vàng!"
  },
  AvgDialog_45420_Content_5 = {Text = "Đúng!"},
  AvgDialog_45420_Content_50 = {
    Text = "Kính gửi nữ hoàng duy nhất của xứ Aran, ngài Thái Di Sơ ——"
  },
  AvgDialog_45420_Content_51 = {
    Text = "Dâng lên lòng trung thành và ý chí của các bạn!"
  },
  AvgDialog_45420_Content_6 = {
    Text = "Yu Li-ét tiến lại gần, chỉ cách bạn một cánh tay, rồi thì thầm."
  },
  AvgDialog_45420_Content_7 = {
    Text = "Việc trở về sông thiêng liêng là số phận của người Aran, tôi chỉ giúp họ nhanh hơn một chút."
  },
  AvgDialog_45420_Content_8 = {
    Text = "Chờ đến khi ánh mắt của Ngài bao phủ khắp vùng Cadas, họ sẽ cùng với sông thiêng liêng hòa nhập vào thế giới mới."
  },
  AvgDialog_45420_Content_9 = {
    Text = "Đây chính là sự lựa chọn của bạn, đúng không?"
