  AvgDialog_45421_Content_1 = {
    Text = "Ai ở đó? !"
  },
  AvgDialog_45421_Content_2 = {
    Text = "Ôi trời, trước có mai phục, sau có quân truy đuổi."
  },
  AvgDialog_45421_Content_3 = {
    Text = "Phải đảm bảo không để những binh sĩ Aran phát hiện chúng ta."
  },
  AvgDialog_45421_Content_4 = {
    Text = "Xem ra, chúng ta ngoài việc đi sâu vào trong thì không còn lựa chọn nào khác?"
  },
  AvgDialog_45422_Content_1 = {
    Text = "Có chút rắc rối. Chúng tôi không biết xác chết ở đâu. \n Nhà máy có đường dẫn phức tạp và nhiều phòng, không biết phải mất bao lâu để tìm hết."
  },
  AvgDialog_45422_Content_10 = {
    Text = "Các người hãy ẩn nấp giúp tôi, đừng lộ diện, tôi sẽ bịt mắt họ lại!"
  },
  AvgDialog_45422_Content_2 = {
    Text = "Tôi có một mẹo nhỏ."
  },
  AvgDialog_45422_Content_3 = {
    Text = "Chúng ta tìm một vệ binh Aran, trói lại và hỏi một lượt là được."
  },
  AvgDialog_45422_Content_4 = {
    Text = "Rồi sao? Bạn định giết để bịt miệng, chôn hắn trong cát, hay thả họ đi và để chúng ta trở thành tội phạm bị truy nã hàng đầu ở Aran?"
  },
  AvgDialog_45422_Content_5 = {
    Text = "Ôi trời, tôi lại không nghĩ đến cái này, thật sơ suất."
  },
  AvgDialog_45422_Content_6 = {
    Text = "Lỗi của anh ta được nói một cách nhẹ nhàng, trông như thể anh ta không hề quan tâm. \nTừ giọng điệu mập mờ đó, bạn nghe ra rằng anh ta còn giữ lại một phương án dự phòng."
