  AvgDialog_45423_Content_3 = {
    Text = "Nữ hoàng đã sớm bỏ rơi chúng ta."
  },
  AvgDialog_45423_Content_4 = {
    Text = "Tiếng thét bi ai không dứt."
  },
  AvgDialog_45424_Content_1 = {
    Text = "Nữ hoàng, nữ hoàng phù hộ chúng tôi!"
  },
  AvgDialog_45424_Content_2 = {
    Text = "Nữ hoàng bảo vệ Aran!"
  },
  AvgDialog_45424_Content_3 = {
    Text = "<Small:Thái Di Sơ rõ ràng không ở đây...>"
  },
  AvgDialog_45424_Content_4 = {
    Text = "Nubia còn đang tụ tập ngày càng nhiều!"
  },
  AvgDialog_45424_Content_5 = {
    Text = "Không còn cách nào khác, chúng ta chỉ có thể tiến về phía trước cùng với những người mất trí này!"
  },
  AvgDialog_45425_Content_1 = {Text = "Cược"},
  AvgDialog_45425_Content_10 = {
    Text = "Bạn mở mắt ra, bầu trời bên ngoài đã trở nên sáng rõ, mọi thứ vẫn giữ nguyên như khi bạn đi ngủ."
  },
  AvgDialog_45425_Content_11 = {
    Text = "Tôi đã hiểu. \n Câu trả lời là động lực."
  },
  AvgDialog_45425_Content_12 = {
    Text = "Nếu tất cả những điều này đều là hành động của Hội Giáo đèn lồng, cô ta không cần để lại ngọn đèn lồng trong thân thể của Nubia."
  },
  AvgDialog_45425_Content_13 = {
    Text = "Dựa vào những điều chúng ta đã chứng kiến trên đường đi, tôi nghĩ hung thủ chỉ có thể là——"
  },
  AvgDialog_45425_Content_14 = {
    Text = "Vuốt sói xé toạc màn che, ảo thuật gia nhẹ nhàng và sa mạc vô tận cùng xuất hiện trong lỗ thủng của lều."
  },
  AvgDialog_45425_Content_15 = {
    Text = "Hai người của Hiệp hội Điêu khắc gia."
