  AvgDialog_45425_Content_16 = {
    Text = "Chào chào, bị phát hiện rồi à? Tôi còn muốn nghe thêm một lúc nữa."
  },
  AvgDialog_45425_Content_17 = {
    Text = "Giọng điệu của cô ấy vui vẻ, không hề có chút căng thẳng nào từ việc nghe lén thất bại."
  },
  AvgDialog_45425_Content_18 = {
    Text = "Kassia, bạn ——"
