  AvgDialog_45427_Content_15 = {
    Text = "Tôi còn rất nhiều câu hỏi…"
  },
  AvgDialog_45427_Content_16 = {
    Text = "Giấc mơ dài dường như đã đưa bạn ra khỏi chuyến hành trình căng thẳng, những câu hỏi lần lượt hiện lên trong tâm trí bạn."
  },
  AvgDialog_45427_Content_17 = {
    Text = "Tại sao nước trong bao nước của Ramona lại biến thành rỗng rỗng?"
