  },
  AvgDialog_45427_Content_2 = {
    Text = "▼▼Đang trong hỗn loạn, không ai biết kết cục. \nĐiều sẽ xảy ra nằm trong lời nói của tôi, nhưng thính giác và thị giác của con người đã bị mất, \nchỉ còn lại sự im lặng bao trùm khắp nơi."
  },
  AvgDialog_45427_Content_20 = {
    Text = "Sứ giả bí ẩn Yu Li-ét có mục đích gì?"
