  AvgDialog_45427_Content_43 = {
    Text = "Sự chạm nhẹ và mát lạnh truyền lên đôi môi."
  },
  AvgDialog_45427_Content_44 = {
    Text = "Bạn mở mắt, ngón tay trỏ của Thái Di Sơ khẽ chạm vào môi bạn. \nKhuôn mặt cô ấy gần kề, ánh trăng phủ lên làn da một lớp sáng mờ ảo."
