  AvgDialog_45435_Content_7 = {
    Text = "Vừa rồi, chúng ta đã chứng kiến Chủ tịch Hiệp hội Điêu khắc gia Herbert bước vào nhà máy có di cốt cây thánh, chính là nơi này."
  },
  AvgDialog_45435_Content_8 = {
    Text = "Herbert vì tư lợi đã tìm kiếm di vật đặc biệt ở khắp nơi, chúng tôi nghi ngờ rằng anh ta muốn có được lực lượng của di cốt cây thánh."
  },
  AvgDialog_45435_Content_9 = {
    Text = "Vì tình huống khẩn cấp, chúng tôi buộc phải ép hỏi binh sĩ để biết vị trí của xác chết, tiếc thay vẫn đến muộn một bước."
  },
  AvgDialog_45436_Content_1 = {
    Text = "Ngọn lửa"
  },
  AvgDialog_45436_Content_2 = {
    Text = "Tại sao… di cốt cây thánh vẫn còn…"
  },
  AvgDialog_45436_Content_3 = {
    Text = "Bạn còn chưa hiểu sao? Điều gọi là xác chết cây mẹ chỉ là một cái cớ."
  },
  AvgDialog_45436_Content_4 = {
    Text = "Chúng ta thực sự cần chỉ có \"sứ giả từ miền đất lạ\" và \"thịt máu của người Aran\" mà thôi."
  },
  AvgDialog_45436_Content_5 = {
    Text = "Ngày nay, sứ giả khờ dại từ phương xa đã mở Tường Bão cho tôi, người Aran cũng đã uống nước sông pha tro đèn."
  },
  AvgDialog_45436_Content_6 = {
    Text = "Ước nguyện của tôi đã đi đúng hướng, chỉ cần chờ cây mẹ phát triển hoàn thiện là được."
  },
  AvgDialog_45436_Content_7 = {
    Text = "À à, tôi không thể chờ thêm để thấy cảnh tượng rỗngsuy yếu bao phủ khắp mặt đất, cửa thần quốc hoàn toàn mở ra…"
  },
  AvgDialog_45437_Content_1 = {
    Text = "Dây chuyền"
  },
  AvgDialog_45437_Content_10 = {
    Text = "Dòng người vẫn chưa tan."
  },
  AvgDialog_45437_Content_11 = {
    Text = "Được rồi, mọi người, hãy trở về làm việc của mình đi."
  },
  AvgDialog_45437_Content_12 = {
    Text = "Hai ngày nữa chúng ta sẽ khởi hành đến Tường Bão, tôi cũng cần phải nghỉ ngơi thật tốt!"
  },
  AvgDialog_45437_Content_13 = {
    Text = "Chúng tôi ngày ngày dọn dẹp phòng, chỉ chờ ngài trở về. Vừa rồi đã cho người thắp hương giúp ngủ ngon, mong rằng dưới bóng cây mẹ, ngài sẽ có giấc mơ an lành."
  },
  AvgDialog_45437_Content_14 = {
    Text = "Ở một góc khuất tầm mắt, Thái Di Sơ nhảy xuống từ quan tài và dễ dàng hòa mình vào đám đông."
  },
  AvgDialog_45437_Content_15 = {
    Text = "Bạn có để ý đến hướng di chuyển của di cốt cây thánh không?"
  },
  AvgDialog_45437_Content_16 = {
    Text = "Từ lâu đã sai Người Giữ Gìn luôn theo dõi rồi."
  },
  AvgDialog_45437_Content_17 = {
    Text = "Đợi chút, Người Giữ Gìn đâu rồi?"
  },
  AvgDialog_45437_Content_18 = {
    Text = "Nhường đường, làm ơn nhường đường."
  },
  AvgDialog_45437_Content_19 = {
    Text = "Bạn rẽ qua hai góc đường, đẩy dòng người đang cuồn cuộn, ánh mắt tìm kiếm cái bóng lưng đó."
  },
  AvgDialog_45437_Content_2 = {
    Text = "Chợ phía trước… có nhiều người quá!"
  },
  AvgDialog_45437_Content_20 = {
    Text = "Cảm giác bực bội dâng lên trong lòng, bạn bất lực chuẩn bị quay lại đội, nhưng chợt phát hiện Thái Di Sơ đứng trong bóng tối sau căn nhà nhỏ, mỉm cười vẫy tay gọi bạn."
  },
  AvgDialog_45437_Content_21 = {
    Text = "Bạn đang tìm tôi à?"
  },
  AvgDialog_45437_Content_22 = {
    Text = "Bạn đi theo sau Thái Di Sơ, cô ấy bất ngờ đi qua các con hẻm một cách yên lặng."
  },
  AvgDialog_45437_Content_23 = {
    Text = "Đi ngang qua một gian hàng trang sức đa dạng, cô ấy cuối cùng cũng dừng lại, quay đầu lại và thì thầm nhẹ nhàng vào tai bạn."
  },
  AvgDialog_45437_Content_24 = {
    Text = "Bạn có thể cho tôi cái này được không?"
  },
  AvgDialog_45437_Content_25 = {
    Text = "Bạn nhìn theo hướng ngón tay cô ấy chỉ, ánh mắt dừng lại trên một chiếc vòng cổ kim loại."
  },
  AvgDialog_45437_Content_26 = {
    Text = "Khách có con mắt tinh tường! Có muốn xem chiếc vòng cổ này không?"
  },
  AvgDialog_45437_Content_27 = {
    Text = "Đây là món đồ do chính con gái tôi chọn nguyên liệu và chế tác, đặc biệt là viên đá lapis lazuli ở giữa, có chất lượng đồng đều, màu sắc tinh tế, chắc chắn với sự tinh tường của ông/bà, điều này không thể qua mắt được!"
  },
  AvgDialog_45437_Content_28 = {
    Text = "Đừng sử dụng đá lazurit."
  },
  AvgDialog_45437_Content_29 = {
    Text = "Không muốn dùng đá lazurit?"
  },
  AvgDialog_45437_Content_3 = {
    Text = "Sứ giả! Là đội của sứ giả đã trở lại!"
  },
  AvgDialog_45437_Content_30 = {
    Text = "Ể? Đá thanh kim là điểm nhấn của chiếc vòng cổ, ngài có chắc là không muốn nó không?"
  },
  AvgDialog_45437_Content_31 = {
    Text = "Nếu thêm viên lapis lazuli này, quỹ mà Misaque chuẩn bị cho bạn sẽ trở nên eo hẹp."
  },
  AvgDialog_45437_Content_32 = {
    Text = "Ừ, không cần đá lazurit."
  },
  AvgDialog_45437_Content_33 = {
    Text = "Được, tôi sẽ gói món hàng này cho quý khách."
  },
  AvgDialog_45437_Content_34 = {
    Text = "Bạn và Thái Di Sơ đi tới ngoài thôn, phóng tầm mắt chỉ thấy gió cát mịt mù, vài con kền kền lướt qua chân trời, để lại tiếng kêu khàn đục."
  },
  AvgDialog_45437_Content_35 = {
    Text = "Nghệ thuật của gia đình Cara, truyền từ đời này sang đời khác đến nay, vẫn còn giỏi giang như xưa."
  },
  AvgDialog_45437_Content_36 = {
    Text = "Cô ấy nhẹ nhàng vuốt ve vết khắc trên dây chuyền, sau đó lật viên ngọc quý hướng về phía bạn để cho bạn xem."
  },
  AvgDialog_45437_Content_37 = {
    Text = "Mẫu hoa văn này là biểu tượng của cây mẹ phong thịnh, cũng là do tôi tự tay vẽ."
  },
  AvgDialog_45437_Content_38 = {
    Text = "Người đưa tin từ phương xa ạ, có thể giúp tôi đeo chiếc vòng cổ này không?"
  },
  AvgDialog_45437_Content_39 = {
    Text = "Bạn theo lời lấy chiếc vòng cổ, Thái Di Sơ hơi cúi đầu, để mặc cánh tay bạn vòng qua đầu và cổ của cô, hơi thở giao hòa."
  },
  AvgDialog_45437_Content_4 = {
    Text = "Các cư dân đã bao vây kín con đường hẹp, trên tay nâng niu những lễ vật dâng tặng cho Yu Li-ét."
  },
  AvgDialog_45437_Content_40 = {
    Text = "Một viên đá quý gần như bằng ngọc trắng được đính ở giữa mặt dây chuyền, sắc trắng trong veo tỏa ra lờ mờ màu đỏ nhạt của sức sống, giống như gương mặt ngượng ngùng của thiếu nữ, toát lên vẻ duyên dáng vừa phải."
  },
  AvgDialog_45437_Content_41 = {
    Text = "Ừ, tôi rất thích. Nhìn vào quà tặng này, tôi sẽ trả lời câu hỏi của bạn nhé? \nBạn có nhiều câu hỏi muốn hỏi phải không?"
  },
  AvgDialog_45437_Content_42 = {
    Text = "Tuy nhiên, trước đó, có một số kẻ không tốt đã xuất hiện, cùng dạy cho những con quái vật nhỏ không biết lãng mạn này một bài học đi?"
  },
  AvgDialog_45437_Content_5 = {
    Text = "Dâng lễ cho Đại nhân sứ giả!"
  },
  AvgDialog_45437_Content_6 = {
    Text = "Ở cuối đội ngũ, Thái Di Sơ ngồi ung dung trên quan tài, được bốn chiến binh Á Lan cẩn trọng khiêng vào."
  },
  AvgDialog_45437_Content_7 = {
    Text = "So sánh với sự chào đón nồng nhiệt mà Yu Li-ét nhận được, lác đác những tiếng reo hò dành cho cô khiến danh xưng nữ hoàng có vẻ không xứng đáng."
  },
  AvgDialog_45437_Content_8 = {
    Text = "Cảm ơn mọi người. Thử thách của mặt trời nóng bỏng đã thử thách mỗi người bước vào sa mạc, sự nhiệt tình của các bạn giống như nước sông thiêng liêng, khiến người ta không thể quên."
  },
  AvgDialog_45437_Content_9 = {
    Text = "Chắc hẳn mọi người đều đã mệt mỏi, hãy về nhà của mình và tận hưởng sự yên bình của đêm."
  },
  AvgDialog_45438_Content_1 = {
    Text = "Yu Li-ét… tại sao…"
  },
  AvgDialog_45438_Content_2 = {
    Text = "Đến nước này rồi, cũng không còn gì phải e ngại."
  },
  AvgDialog_45438_Content_3 = {
    Text = "Người Aran đã trả giá bằng máu tươi của những kẻ dị hình để đổi lấy sự sinh tồn của giống nòi, sự tồn tại của các ngươi chính là sự ô nhục và tội lỗi."
  },
  AvgDialog_45438_Content_4 = {
    Text = "Người sinh ra mang nguyên tội chỉ xứng đáng trở thành củi xây nền cho thần quốc."
  },
  AvgDialog_45438_Content_5 = {
    Text = "Mà đứa con quý giá nhất, đã thuộc về tôi, trở thành người đủ điều kiện đến thế giới mới."
  },
  AvgDialog_45438_Content_6 = {
    Text = "Trước mặt Elva, một sinh vật nửa người nửa chó cúi phục trên mặt đất."
  },
  AvgDialog_45438_Content_7 = {
    Text = "Thật ngoan, không hổ là đứa trẻ được tôi chọn."
  },
  AvgDialog_45438_Content_8 = {
    Text = "Néfer… Luri…"
  },
  AvgDialog_45438_Content_9 = {
    Text = "Đi đi, đứa trẻ, để bảo vệ sự tái sinh của cây mẹ, nghiền nát kẻ thù của ngươi."
  },
  AvgDialog_45439_Content_1 = {
    Text = "Chuyện gì đang ồn ào vậy?"
  },
  AvgDialog_45439_Content_10 = {
    Text = "Bạn có bằng chứng gì?"
  },
  AvgDialog_45439_Content_11 = {
    Text = "Hình ảnh về cái chết thảm khốc của William hiện lên trước mắt bạn. \nAnh ta đã chết bởi một con quái vật cực kỳ hung ác, có liên quan mật thiết đến Hội Giáo đèn lồng."
  },
  AvgDialog_45439_Content_12 = {
    Text = "Nhưng buộc tội Yu Li-ét... bạn không có cách nào đưa ra bất kỳ bằng chứng nào."
  },
  AvgDialog_45439_Content_13 = {
    Text = "Xin hãy nhớ lại thật kỹ, những ngày tháng chúng ta đã cùng nhau trải qua."
  },
  AvgDialog_45439_Content_14 = {
    Text = "Bạn có tin những lời nói nhảm của %hisorher% không?"
  },
  AvgDialog_45439_Content_15 = {
    Text = "Tiếng hoài nghi dồn dập từ khắp mọi nơi, trong đó không có bất kỳ sự tin tưởng nào dành cho bạn."
  },
  AvgDialog_45439_Content_16 = {
    Text = "%player%,tôi cũng rất buồn, cho đến nay, tôi luôn tin tưởng bạn, bỏ qua những hành động vô lễ của bạn ở Aran, thậm chí còn thay bạn cầu xin trưởng tộc."
  },
  AvgDialog_45439_Content_17 = {
    Text = "Bây giờ xem ra, quả thật, tôi đã sai khi đánh giá về cậu."
  },
  AvgDialog_45439_Content_18 = {
    Text = "Thưa ngài Elva, xin hãy khoan dung cho lỗi lầm của tôi."
  },
  AvgDialog_45439_Content_19 = {
    Text = "Dù cuộc tranh chấp giữa bạn và Yu Li-ét cuối cùng có kết thúc như thế nào, hôm nay, nghi lễ phải được tiến hành đến cùng."
