  AvgDialog_45439_Content_2 = {
    Text = "Đám đông dẹp đường"
  },
  AvgDialog_45439_Content_20 = {
    Text = "Bất kỳ ai cản trở sự tái sinh của cây mẹ đều sẽ trở thành tế phẩm trên con đường cây mẹ tái hiện!"
  },
  AvgDialog_45439_Content_3 = {
    Text = "Là các bạn?"
