  AvgDialog_45439_Content_4 = {
    Text = "Vâng, chúng tôi có việc quan trọng cần báo cáo."
  },
  AvgDialog_45439_Content_5 = {
    Text = "Yu Li-ét… luôn lừa dối các bạn."
  },
  AvgDialog_45439_Content_6 = {
    Text = "Cô ấy không phải là người đưa tin huyền thoại, cô ấy cũng không có sức mạnh thần thánh để làm cho cây mẹ hồi sinh."
  },
  AvgDialog_45439_Content_7 = {
    Text = "Cô ấy thậm chí còn không được phép vào Tường Bão, vì Tường Bão được Nữ hoàng Thái Di Sơ xây dựng, là rào cản ngăn chặn những kẻ có lòng phản bội!"
  },
  AvgDialog_45439_Content_8 = {
    Text = "Bạn nhìn xung quanh, Dư Lệ-ét đứng ở đầu đám đông, bài phát biểu của bạn dường như không tạo nên bất kỳ gợn sóng cảm xúc nào trong lòng cô ấy."
  },
  AvgDialog_45439_Content_9 = {
    Text = "Bạn có bằng chứng gì cho cáo buộc này không?"
