  AvgDialog_45441_Content_1 = {
    Text = "Đối thủ"
  },
  AvgDialog_45441_Content_2 = {
    Text = "Lắc đá tung cánh cửa sắt phủ đầy gỉ sét, bụi khói bốc lên mù mịt."
  },
  AvgDialog_45441_Content_3 = {
    Text = "Tiếng rít kỳ quái và quen thuộc, tiếng xương khớp vặntiếng động từ bốn phía truyền đến.đúng vậytiếng rít gê rợn mà quen thuộc, tiếng khớp xương vặn vẹo rùng rợn vọng đến từ bốn phía."
  },
  AvgDialog_45441_Content_4 = {
    Text = "Tôi không nhầm chứ? Đó là những sản phẩm thí nghiệm được Hiệp hội Điêu khắc gia cải tạo phải không?"
  },
  AvgDialog_45441_Content_5 = {
    Text = "Tôi cũng đã thấy."
