  AvgDialog_45441_Content_6 = {
    Text = "Đại hỗn chiến. Tôi ngửi thấy mùi khó chịu."
  },
  AvgDialog_45441_Content_7 = {
    Text = "Xác chết cây mẹ ở bên trong cùng, vị trí gần cửa sổ!"
  },
  AvgDialog_45441_Content_8 = {
    Text = "Hãy đi xem trước đi, nếu để lâu nữa chắc anh ta sẽ tè dầm mất."
  },
  AvgDialog_45442_Content_1 = {Text = "Mơ"},
  AvgDialog_45442_Content_10 = {
    Text = "Không được đâu, Elva."
  },
  AvgDialog_45442_Content_101 = {
    Text = "Tôi nghe thấy một tiếng thở dài thườn thượt."
  },
  AvgDialog_45442_Content_102 = {
    Text = "Cuối cùng cũng chỉ là một con rối không hoàn hảo, vẫn cần tiêu thụ quá nhiều sức lực để điều khiển."
  },
  AvgDialog_45442_Content_103 = {
    Text = "Sự quyết tâm của bạn dành cho Aran càng mạnh mẽ bao nhiêu, thì sự phản kháng sau khi nhận ra sự thật sẽ càng mãnh liệt và sâu sắc bấy nhiêu."
  },
  AvgDialog_45442_Content_104 = {
    Text = "May mắn thay, tôi đã dự đoán trước tình huống này rồi."
  },
  AvgDialog_45442_Content_105 = {
    Text = "Thời gian đã đến, tất cả các ngươi, vì cây mẹ mà các ngươi yêu quý nhất……"
  },
  AvgDialog_45442_Content_106 = {
    Text = "Hãy dâng hiến thịt máu và sinh lực của mình."
  },
  AvgDialog_45442_Content_107 = {
    Text = "Tôi mở miệng, kinh ngạc phát hiện mình không thể phát ra âm thanh. \nMọi thứ xung quanh rơi vào sự tĩnh lặng đáng sợ."
  },
  AvgDialog_45442_Content_108 = {
    Text = "Không, điều dừng lại không phải là thế giới, mà là nhận thức của tôi, mỗi cái chớp mắt nhẹ đều như thể đã qua một thế kỷ."
  },
  AvgDialog_45442_Content_109 = {
    Text = "Trong chuỗi dài lê thê, chỉ có những người đồng đội cũ của tôi, các binh sĩ Aran liên tục, ồ ạt lao về phía sông thiêng liêng."
  },
  AvgDialog_45442_Content_11 = {
    Text = "Hay làm như thế này, vừa rồi <Blue:Harleman> đã sai người đưa thư mời, cô ấy chuẩn bị rượu vang thượng hạng, mời tôi qua thưởng thức."
  },
  AvgDialog_45442_Content_110 = {Text = "Xoà——"},
  AvgDialog_45442_Content_111 = {
    Text = "Thế giới lại có âm thanh và màu sắc."
  },
  AvgDialog_45442_Content_112 = {
    Text = "Họ nối tiếp nhau, không do dự nhảy vào dòng nước cuồn cuộn của sông thiêng liêng, dồn hết sức dang rộng đôi tay, ôm lấy thân cây mẹ đã khô héo."
  },
  AvgDialog_45442_Content_113 = {
    Text = "Họ khóc lóc cuồng nhiệt, phát ra những tiếng gào thét điên rồ không thể gọi thành tên."
  },
  AvgDialog_45442_Content_114 = {
    Text = "Da của họ trở nên lỏng lẻo, như thể bùn nhão chảy ra; dịch thể trong cơ thể họ bị rút đi, hòa vào dòng nước cuồn cuộn của sông thiêng liêng."
  },
  AvgDialog_45442_Content_115 = {
    Text = "Xương cốt của họ mềm hóa như da thịt, các chi uốn cong, kéo dài và bị cuốn vào theo cách phi nhân tính. Từ chính thịt máu của mình, họ tạo thành những nhánh cây to lớn, phình đại của cây thánh."
  },
  AvgDialog_45442_Content_116 = {
    Text = "Họ từ từ và đau đớn hòa làm một với cây Thánh."
  },
  AvgDialog_45442_Content_12 = {
    Text = "Bạn có muốn đi cùng tôi, không say không về không?"
  },
  AvgDialog_45442_Content_13 = {
    Text = "Thái Di Sơ đại nhân, tôi e rằng…"
  },
  AvgDialog_45442_Content_14 = {
    Text = "Quân nhân nghe lệnh hành động, đây là lời ngươi đã nói mà."
  },
  AvgDialog_45442_Content_15 = {
    Text = "Lệnh của tôi là—— không say không về."
  },
  AvgDialog_45442_Content_16 = {
    Text = "Có phải một utopia không có máu và nước mắt?"
  },
  AvgDialog_45442_Content_17 = {
    Text = "Thật không ngờ, bạn trông cứng nhắc và nguyên tắc vậy mà trong lòng lại đang mơ những giấc mơ ngây thơ như thế."
  },
  AvgDialog_45442_Content_18 = {
    Text = "Thái Di Sơ đại nhân, đừng cười tôi……"
  },
  AvgDialog_45442_Content_19 = {
    Text = "Làm sao có thể cười nhạo bạn được?"
  },
  AvgDialog_45442_Content_2 = {
    Text = "Elva, bạn đã được gọi ra khá lâu rồi, mỗi ngày ngoài việc tập thể dục buổi sáng thì chỉ còn lại lao động, Kalune lần trước mời bạn đi dự tiệc tối, bạn cũng từ chối."
  },
  AvgDialog_45442_Content_20 = {
    Text = "Với xương và máu của tôi nuôi dưỡng cả vùng Lemvahi, để dòng máu của Aran không ngừng chảy."
  },
  AvgDialog_45442_Content_21 = {
    Text = "Dòng máu vô hạn, hy vọng rằng trong số chúng sẽ có một kẻ thoát khỏi ánh mắt của vị đại nhân kia, để tiếp tục ý chí của ta trong vòng tuần hoàn từ khởi đầu đến kết thúc…"
  },
  AvgDialog_45442_Content_22 = {
    Text = "Tôi và bạn, có phải cũng ngây thơ đến buồn cười không?"
  },
  AvgDialog_45442_Content_24 = {
    Text = "Ngủ rồi à?"
  },
  AvgDialog_45442_Content_25 = {
    Text = "Cũng tốt. Ngươi vốn không phải là dân tộc A-lan, không nên bị giam cầm trong sa mạc hoang vu này."
  },
  AvgDialog_45442_Content_26 = {
    Text = "Khi sức sống của tôi kết thúc, hãy rời bỏ Lemvahi và đi tìm người ký kết hợp đồng mới."
  },
  AvgDialog_45442_Content_27 = {
    Text = "Ngày đó… sắp đến nơi rồi."
  },
  AvgDialog_45442_Content_28 = {
    Text = "Tôi ngồi trong lều của nữ hoàng, bên ngoài, tiếng khóc tang lễ chất chứa nỗi buồn sâu sắc, đau đớn và lưu luyến."
  },
  AvgDialog_45442_Content_29 = {
    Text = "Có thể khóc trước người mình tin tưởng, cũng là một loại may mắn. \nTrên chiến trường, chúng tôi thường không có thời gian để rơi nước mắt cho đồng đội đã khuất."
  },
  AvgDialog_45442_Content_3 = {
    Text = "Bạn không muốn có phần thưởng à?"
  },
  AvgDialog_45442_Content_30 = {
    Text = "Đối với tôi, điều quan trọng hơn là người Aran mất nữ hoàng nên đi đâu. \nNgười Aran ngừng suy nghĩ vì nỗi buồn, thì tôi sẽ suy nghĩ thay họ."
  },
  AvgDialog_45442_Content_31 = {
    Text = "Quý bà Thái Di Sơ không tin tưởng tôi, tôi luôn biết điều đó."
  },
  AvgDialog_45442_Content_32 = {
    Text = "Người Aran phân biệt quan hệ họ hàng dựa trên dòng máu, trong mắt họ, tôi luôn là kẻ ngoại lai vì có máu của tộc khác chảy trong người."
  },
  AvgDialog_45442_Content_33 = {
    Text = "Nhưng người Aran cần một nhà lãnh đạo, cả về tinh thần lẫn thực tế."
  },
  AvgDialog_45442_Content_34 = {
    Text = "Tôi sẽ đảm nhận vai trò tộc trưởng, gìn giữ linh cữu của Thái Di Sơ đại nhân."
  },
  AvgDialog_45442_Content_35 = {
    Text = "Mỗi bước tiếp theo của tộc Á Lan sẽ tiến lên dưới sự giám sát của <Red:Thái Di Sơ đại nhân>."
  },
  AvgDialog_45442_Content_36 = {
    Text = "Dân tộc Aran sẽ tiến bước trong tương lai dưới sự giám sát của <Red:Đại nhân Nữ hoàng>."
  },
  AvgDialog_45442_Content_37 = {
    Text = "Dân tộc Aran sẽ tiến lên từng bước trong sự giám sát của <Red:@1 ngài>."
  },
  AvgDialog_45442_Content_39 = {
    Text = "Rốt cuộc tại sao tôi lại xuất hiện ở đây?"
  },
  AvgDialog_45442_Content_4 = {
    Text = "Chừng nào Á Lan ổn định và thịnh vượng, đó chính là phần thưởng tốt nhất đối với tôi, thưa ngài Thái Di Sơ."
  },
  AvgDialog_45442_Content_40 = {
    Text = "Đồ vật được đặt trong quan tài đó… Đúng rồi, có vẻ như là di cốt cây thánh."
  },
  AvgDialog_45442_Content_41 = {
    Text = "Tại sao di cốt cây thánh lại được đặt trong trại của nữ hoàng?"
  },
  AvgDialog_45442_Content_42 = {
    Text = "Thôi được rồi, không nhớ nổi."
  },
  AvgDialog_45442_Content_43 = {
    Text = "Nhưng không sao."
  },
  AvgDialog_45442_Content_44 = {
    Text = "<Big:Chừng nào cây mẹ hồi sinh, <Red:mọi thứ> đều sẽ tốt đẹp trở lại.>"
  },
  AvgDialog_45442_Content_46 = {
    Text = "Trong hàng trăm năm cuộc đời, tôi đã đào tạo nhiều người kế nhiệm."
  },
  AvgDialog_45442_Content_47 = {
    Text = "Tôi tin rằng sẽ có một anh hùng mang lại ánh sáng cho Á Lan."
  },
  AvgDialog_45442_Content_48 = {
    Text = "Người kế nhiệm đầu tiên chết vì độc rắn."
  },
  AvgDialog_45442_Content_49 = {
    Text = "Người kế nhiệm thứ hai chết trong cơn bão."
  },
  AvgDialog_45442_Content_5 = {
    Text = "Bạn căn bản không thích Aran phải không? Bạn thậm chí còn không chịu tham gia bữa tiệc lửa trại."
  },
  AvgDialog_45442_Content_50 = {
    Text = "Người kế nhiệm thứ ba chết vì sự đố kỵ của người khác."
  },
  AvgDialog_45442_Content_51 = {
    Text = "Có quá nhiều sự cố và biến số trong sa mạc, loài sống sót lâu nhất trong sa mạc không phải là đại bàng vương miện hung dữ hay rắn cát độc hại, mà là kiến bạc chỉ hoạt động mười phút mỗi ngày."
  },
  AvgDialog_45442_Content_52 = {
    Text = "Đặt hy vọng vào một cá nhân, đối với Á Lan mà nói là vô cùng thiếu khôn ngoan."
  },
  AvgDialog_45442_Content_53 = {
    Text = "Mà tốc độ giảm chủng loài không chờ đợi ai cả. \nChỉ cần một cơn bão bất ngờ, có thể cuốn đi các nhóm người."
  },
  AvgDialog_45442_Content_54 = {
    Text = "Ở thời điểm ít nhất, đội của Á Lan co lại còn không đầy trăm người."
  },
  AvgDialog_45442_Content_55 = {
    Text = "<Red:Nếu tiếp tục như thế này, dân tộc Á Lan sẽ bị xóa sổ trong tay tôi.>"
  },
  AvgDialog_45442_Content_56 = {
    Text = "Tối mai… khởi động lại buổi họp lửa trại."
  },
  AvgDialog_45442_Content_57 = {
    Text = "Tại bữa tiệc, họ hát hò và uống rượu vui vẻ. \nKhi bình minh đến, một đứa trẻ chào đời chỉ sau một đêm."
  },
  AvgDialog_45442_Content_58 = {
    Text = "Khi bế đứa bé vừa chào đời trên tay, tôi không khỏi rơi lệ vì xúc động."
  },
  AvgDialog_45442_Content_59 = {
    Text = "Quyền năng của cây mẹ là phép màu mà trời ban cho Aran, còn tôi lại vì sự hiểu biết hạn hẹp và thiển cận của mình mà xem nó là dị đoan."
  },
  AvgDialog_45442_Content_6 = {
    Text = "Không cần phải biện minh, tôi đều nhìn ra được. \nĐây toàn là những kẻ điên cuồng phóng túng, không hợp với bạn."
  },
  AvgDialog_45442_Content_60 = {
    Text = "Chỉ là…"
  },
  AvgDialog_45442_Content_61 = {
    Text = "Sức mạnh của cây mẹ đang không ngừng suy yếu."
  },
  AvgDialog_45442_Content_62 = {
    Text = "Có nhiều hơn thai nhi bị dị tật."
  },
  AvgDialog_45442_Content_63 = {
    Text = "Tôi bối rối, cho đến khi một phụ nữ lớn tuổi tình cờ đề cập——"
  },
  AvgDialog_45442_Content_64 = {
    Text = "Bạn còn nhớ bài hát đó không?"
  },
  AvgDialog_45442_Content_65 = {
    Text = "Cái chết đã cận kề, sự diệt vong đã bắt đầu."
  },
  AvgDialog_45442_Content_66 = {
    Text = "Xác chết của mẹ không còn tung tích, máu và hạt giống phiêu bạt trên mặt đất, bị những con thú mới sinh nuốt chửng."
  },
  AvgDialog_45442_Content_67 = {
    Text = "Trời đất và các vị thần bị bao phủ bởi những đám mây, cho đến khi sứ giả từ nơi xa lạ đến."
  },
  AvgDialog_45442_Content_68 = {
    Text = "Cây mẹ tái sinh sông thiêng liêng, trao vinh quang cho những người đã khuất, trả lại dòng máu cho Aran."
  },
  AvgDialog_45442_Content_69 = {
    Text = "Chỉ cần tìm thấy <Yellow:người đưa tin từ xa>, có lẽ có thể chứng kiến sự tái sinh của cây mẹ!"
  },
  AvgDialog_45442_Content_7 = {
    Text = "Nhưng, cuộc sống chỉ vì trách nhiệm như vậy, bạn không thấy nhàm chán sao"
