  AvgDialog_45442_Content_70 = {
    Text = "Thái Di Sơ, Thái Di Sơ——!"
  },
  AvgDialog_45442_Content_71 = {
    Text = "Người nào đó, đang gọi tên một người."
  },
  AvgDialog_45442_Content_72 = {
    Text = "Đầu đau như búa bổ, vô số kim châm đâm xuyên não, tiếng ồn chói tai xé toạc màng nhĩ, nhưng âm thanh của dòng máu chảy trong huyết quản vẫn rõ ràng đến đáng sợ."
  },
  AvgDialog_45442_Content_73 = {
    Text = "<Big:Thái Di Sơ, Thái Di Sơ—— !>"
