  AvgDialog_45442_Content_74 = {
    Text = "Thái Di Sơ, đó là ai?"
  },
  AvgDialog_45442_Content_75 = {
    Text = "Đừng để tâm đến những tạp âm đó, chúng chỉ làm xao lãng sự tập trung của bạn."
  },
  AvgDialog_45442_Content_76 = {
    Text = "Cây Mẹ sắp trở lại mặt đất rồi, anh không cảm thấy vui mừng sao?"
  },
  AvgDialog_45442_Content_77 = {
    Text = "Tôi nhớ mình đã từng nghe qua cái tên Thái Di Sơ ở đâu đó."
  },
  AvgDialog_45442_Content_78 = {
    Text = "Nhưng, vậy rốt cuộc là ở đâu?"
  },
  AvgDialog_45442_Content_79 = {
    Text = "Sân chiến biến đổi nhanh chóng trước khi chết, nụ cười của đồng đội khi lâm chung, câu trả lời lạnh lùng vô tình của chỉ huy……\nkhông, chẳng phải vậy."
  },
  AvgDialog_45442_Content_8 = {
    Text = "Bà Thái Di Sơ, người biết mà. \nTôi từng là người lính. Người lính tuân lệnh hành động."
  },
  AvgDialog_45442_Content_80 = {
    Text = "Sau khi được thức tỉnh, ngày này qua ngày khác lao động, tổ chức yến tiệc, đối đầu với bầy thú…"
