  AvgDialog_45442_Content_84 = {
    Text = "<Red:Thái Di Sơ.>"
  },
  AvgDialog_45442_Content_85 = {
    Text = "Tại sao mình lại quên mất tên của cô ấy nhỉ?"
  },
  AvgDialog_45442_Content_86 = {
    Text = "Tôi rõ ràng mỗi ngày, đều gọi tên cô ấy——"
