  AvgDialog_45442_Content_88 = {
    Text = "Mỗi bước chân của cô ấy in đậm trên mặt đất bị gió mài mòn, trong lồng ngực tôi dâng lên những đợt sóng cảm xúc dâng trào, khiến những giọt nước mắt nóng bỏng lăn dài."
  },
  AvgDialog_45442_Content_89 = {
    Text = "Thái Di Sơ đại nhân…"
  },
  AvgDialog_45442_Content_9 = {
    Text = "Bạn là người liên kết của tôi. \n Bảo vệ Aran là điều bạn mong muốn, cũng chính là điều tôi mong muốn."
  },
  AvgDialog_45442_Content_90 = {
    Text = "Tôi vẫn luôn chờ đợi ngài. \nTôi biết ngài sẽ trở lại, ngài chưa bao giờ quên Aran."
  },
  AvgDialog_45442_Content_91 = {
    Text = "Tất cả người dân tộc Aran, hãy nghe lệnh! Tiên tri cổ xưa đã ứng nghiệm, cây mẹ tái hiện trên thế gian, hãy trao vinh quang cho những người đã khuất!"
