  AvgDialog_45442_Content_95 = {
    Text = "Tôi cuối cùng, cuối cùng cũng kiên trì đến được thời khắc này."
  },
  AvgDialog_45442_Content_96 = {
    Text = "Vậy, bây giờ ngài có thể khen tôi một câu được không?"
  },
  AvgDialog_45442_Content_97 = {
    Text = "Lời khen cho sự kiên nhẫn hàng trăm năm, sự nén chịu hàng trăm năm, và cuối cùng sau hàng trăm năm đã tìm thấy người đưa đường cho cây mẹ phong thịnh tái sinh ——"
  },
  AvgDialog_45442_Content_98 = {
    Text = "Hãy cùng nhau, biến Á Lan thành một quốc gia lý tưởng không có máu và nước mắt, một thiên đường tinh khiết và hoàn mỹ."
  },
  AvgDialog_45442_Content_99 = {
    Text = "À, Thái Di Sơ đại nhân, ngài tại sao lại lắc đầu với tôi?"
  },
  AvgDialog_45443_Content_1 = {Text = "Quay lại"},
  AvgDialog_45443_Content_10 = {
    Text = "Bạn cô đơn một mình, cần có sự hỗ trợ từ người bạn đồng hành —— Thái Di Sơ —— lóe lên trong tâm trí."
  },
  AvgDialog_45443_Content_11 = {
    Text = "Bạn chỉ cần làm một điều, đó là tin tưởng tôi hoàn toàn. \nTin tưởng Nữ hoàng Aran."
  },
  AvgDialog_45443_Content_12 = {
