  AvgDialog_45443_Content_16 = {
    Text = "Nữ hoàng……sao vậy?"
  },
  AvgDialog_45443_Content_17 = {
    Text = "Còn gì nữa đây? Nữ hoàng đã mất từ hàng trăm năm trước, nếu ngươi còn dám nói lời bất kính, ta sẽ không nể mặt nữa đâu!"
  },
  AvgDialog_45443_Content_18 = {
    Text = "Nhìn thấy biểu cảm nghiêm túc của anh ta, trái tim bạn như chìm vào vực băng giá."
  },
  AvgDialog_45443_Content_2 = {
    Text = "Gần một nghìn người dân tộc Aran tụ tập bên bờ sông thiêng liêng, những bài ca trầm bổng vang vọng lan tỏa, hòa quyện cùng tiếng hú của thú dữ từ xa tạo nên một chương hỗn loạn."
  },
  AvgDialog_45443_Content_20 = {
    Text = "Bạn nhìn về phía xa, tâm điểm của buổi lễ."
  },
  AvgDialog_45443_Content_21 = {
    Text = "Quan tài nằm yên trên giá gỗ cao lớn của bàn thờ. \nHiển nhiên, không có bóng dáng của Thái Di Sơ mà bạn từng gặp ở đó."
  },
  AvgDialog_45443_Content_22 = {
    Text = "Không chỉ ở đó. \n Ở đâu cũng không tồn tại."
  },
  AvgDialog_45443_Content_23 = {
    Text = "Màn trướng của túp lều bị đẩy ra, một người phụ nữ Alan khoảng cuối ba mươi, với vẻ mặt nghiêm nghị, bước mạnh vào lều."
  },
  AvgDialog_45443_Content_24 = {
    Text = "Thái Di Sơ hoảng loạn nhảy vội về quan tài, duy trì phong thái đoan trang, tựa như một nữ vương kiêu hãnh trên ngai vàng."
  },
  AvgDialog_45443_Content_25 = {
    Text = "Khách quý kính mến……"
  },
  AvgDialog_45443_Content_26 = {
    Text = "<Red:giọng điệu làm bộ làm tịch của cô ta bị người đến dứt khoát cắt ngang>."
  },
  AvgDialog_45443_Content_27 = {
    Text = "Elva đương nhiên sẽ không \"cắt ngang\" tuyên bố của nữ hoàng."
  },
  AvgDialog_45443_Content_28 = {
    Text = "Sứ giả! Là đội của sứ giả đã trở lại!"
  },
  AvgDialog_45443_Content_29 = {
    Text = "Các cư dân đã bao vây kín con đường hẹp, trên tay nâng niu những lễ vật dâng tặng cho Yu Li-ét."
  },
  AvgDialog_45443_Content_3 = {
    Text = "Một bàn thờ gỗ lớn sừng sững giữa đám đông, quan tài được điêu khắc bằng những ký hiệu khó hiểu được trưng bày trên đó, ánh mắt xung quanh pha trộn giữa nỗi sợ hãi, sự phấn khích và mong đợi."
  },
  AvgDialog_45443_Content_30 = {
    Text = "Ở cuối đội ngũ, Thái Di Sơ ngồi ung dung trên quan tài, được bốn chiến binh Á Lan cẩn trọng khiêng vào."
  },
  AvgDialog_45443_Content_31 = {
    Text = "So sánh với sự chào đón nồng nhiệt dành cho Dư Lệ-ét, <Red:tiếng reo hò lác đác mà cô nhận được khiến tên gọi Nữ hoàng dường như trở nên không xứng đáng>."
  },
  AvgDialog_45443_Content_32 = {
    Text = "Trong mắt tất cả người dân, không tồn tại nữ hoàng ngự trên hài cốt."
  },
  AvgDialog_45443_Content_33 = {
    Text = "Bạn có thể cho tôi cái này được không?"
  },
  AvgDialog_45443_Content_34 = {
    Text = "Bạn nhìn theo hướng ngón tay cô ấy chỉ, ánh mắt dừng lại trên một chiếc vòng cổ kim loại."
  },
  AvgDialog_45443_Content_35 = {
    Text = "Khách có con mắt tinh tường! Có muốn xem chiếc vòng cổ này không?"
  },
  AvgDialog_45443_Content_36 = {
    Text = "Đây là do chính tay con gái tôi làm, đặc biệt là viên đá lapis lazuli ở giữa, chất liệu mượt mà và màu sắc rất tinh xảo, bạn chắc chắn sẽ nhận ra được!"
  },
  AvgDialog_45443_Content_37 = {
    Text = "Đừng sử dụng đá lazurit."
  },
  AvgDialog_45443_Content_38 = {
    Text = "Không muốn dùng đá lazurit?"
  },
  AvgDialog_45443_Content_39 = {
    Text = "À...? Bạn chắc chắn không muốn đá lazurit sao?"
  },
  AvgDialog_45443_Content_4 = {
    Text = "Ngay khi bạn vừa bước vào, đã bị chặn lại một cách gay gắt."
  },
  AvgDialog_45443_Content_40 = {
    Text = "Nếu thêm viên lapis lazuli này, quỹ mà Misaque chuẩn bị cho bạn sẽ trở nên eo hẹp."
  },
  AvgDialog_45443_Content_41 = {
    Text = "Ừ, không cần đá lazurit."
  },
  AvgDialog_45443_Content_42 = {
    Text = "Được, gói <Red:khách này> lại."
  },
  AvgDialog_45443_Content_43 = {
    Text = "Người bán hàng chỉ đang đáp lại lời nói của bạn."
  },
  AvgDialog_45443_Content_44 = {
    Text = "Trên một đụn cát cách đó không xa, bạn đã thấy bóng dáng ấy."
  },
  AvgDialog_45443_Content_45 = {
    Text = "Từ đường nét bạn nhận ra đó là Thái Diễm Sơ."
  },
  AvgDialog_45443_Content_46 = {
    Text = "Cơn bão……có phải đã nhỏ hơn không?"
  },
  AvgDialog_45443_Content_47 = {
    Text = "Cô ấy ngân nga những lời cầu nguyện không rõ tên, để gió mạnh cuốn lấy áo choàng của mình, từ từ và vững chắc bước vào cơn bão cát tối tăm."
  },
  AvgDialog_45443_Content_48 = {
    Text = "Tiếng gầm rền vang động dữ dội, nhưng tiếng đọc kinh vẫn rõ ràng đến lạ thường, như thể vang vọng trong đầu bạn."
  },
  AvgDialog_45443_Content_49 = {
    Text = "Trong cơn cuồng phong nuốt trọn đất trời, cô ấy như đang bình thản trò chuyện với một sinh linh nào đó sống trong sa mạc."
  },
  AvgDialog_45443_Content_5 = {Text = "Ai vậy!"},
  AvgDialog_45443_Content_50 = {
    Text = "Là nữ hoàng! Nữ hoàng đến cứu chúng ta, cứu Á Lan!"
  },
  AvgDialog_45443_Content_51 = {
    Text = "Đội ngũ của Á Lan cần gấp rút thoát thân bỗng nhiên dừng lại."
  },
  AvgDialog_45443_Content_52 = {
    Text = "Vô số người Aran quay mặt về hướng Thái Di Sơ đang ở, quỳ gối trang nghiêm và thành kính."
  },
  AvgDialog_45443_Content_53 = {
    Text = "Nhưng ở cuối hướng họ quỳ lạy…\nChỗ đó trống không, chỉ có bạn mới thấy góc áo của Thái Di Sơ bị gió cát thổi phăng lên."
  },
  AvgDialog_45443_Content_54 = {
    Text = "Làm chất thể của dục vọng, sự tồn tại của cây mẹ phong thịnh chắc chắn đã để lại dấu ấn sâu sắc và đủ mạnh trên hành tinh."
  },
  AvgDialog_45443_Content_55 = {
    Text = "Sức sống mãnh liệt của cây mẹ khiến tốc độ bị ăn mòn chậm hơn hàng vạn lần so với người bình thường."
  },
  AvgDialog_45443_Content_56 = {
    Text = "Vì vậy, <Red:đối với bạn, cô ấy vẫn chưa hoàn toàn tan biến khỏi tâm trí bạn>."
  },
  AvgDialog_45443_Content_57 = {
    Text = "Nếu sau hàng trăm, hàng nghìn năm nữa, <Red:người Aran có thể quên mất sự tồn tại của cây mẹ>."
  },
  AvgDialog_45443_Content_59 = {
    Text = "Họ chưa từng gặp nữ hoàng tên Thái Di Sơ; niềm tin và sự tôn kính của họ chỉ là hư vô được lưu truyền qua lời kể."
  },
  AvgDialog_45443_Content_6 = {
    Text = "Đây là thời khắc quan trọng của nghi lễ, những người không liên quan không được vào!"
  },
  AvgDialog_45443_Content_60 = {
    Text = "Người dẫn bạn du lịch, múa hát cho bạn, ngồi trên quan tài và giả vờ cao ngạo, Thái Di Sơ, <Red:trong mắt họ chưa bao giờ tồn tại>."
  },
  AvgDialog_45443_Content_61 = {
    Text = "Nhưng bạn rất chắc chắn ——"
  },
  AvgDialog_45443_Content_62 = {
    Text = "Ghi nhớ ký ức dưới ánh trăng đêm."
  },
  AvgDialog_45443_Content_63 = {
    Text = "Tin chắc nhiệt độ còn lại trên đầu ngón tay."
  },
  AvgDialog_45443_Content_64 = {
    Text = "Khẳng định lời nói nhẹ nhàng của cô ấy."
  },
  AvgDialog_45443_Content_65 = {
    Text = "Bạn có biết không? Tôi đã thấy thảm họa trong mắt bạn, thấy tàn tro của thời cổ đại, thấy khí tức của trời đất và vũ trụ."
  },
  AvgDialog_45443_Content_66 = {
    Text = "Chuyến hành trình của bạn rất dài, chắc hẳn bạn đã mệt mỏi rồi, phải không? Nhưng ánh mắt của bạn vẫn kiên định như vậy, không một chút mờ mịt."
  },
  AvgDialog_45443_Content_67 = {
    Text = "Những vì sao không thể thay đổi bạn, và sa mạc cát cũng chưa chắc đã làm được."
  },
  AvgDialog_45443_Content_68 = {
    Text = "Thở nhẹ của cô ấy hòa quyện với bạn. \n Trong đáy mắt cô ấy, biển sao đang bừng cháy."
  },
  AvgDialog_45443_Content_69 = {
    Text = "Tôi sẽ đi kết thúc nghi lễ của Á Lan."
  },
  AvgDialog_45443_Content_7 = {
    Text = "Tôi muốn gặp Thái Di Sơ!"
  },
  AvgDialog_45443_Content_70 = {
    Text = "Thái Di Sơ…… chắc chắn sẽ đợi tôi ở đó."
  },
  AvgDialog_45443_Content_8 = {
    Text = "Bạn sẽ không hiểu lầm những manh mối quan trọng mà William để lại cho bạn —— Nubia, sứ giả giả, sự ô nhiễm của cây mẹ… Tất cả những điều này đều là thủ đoạn của Hội Giáo đèn lồng."
  },
  AvgDialog_45443_Content_9 = {
    Text = "Ramona, William, Layc… Các đồng nghiệp của Misaque lúc này đều đã rời đi."
  },
  AvgDialog_45444_Content_1 = {
    Text = "Dưới gốc cây mẹ, Elva yếu ớt quỳ khóc."
  },
  AvgDialog_45444_Content_10 = {
    Text = "Chỉ trong những khe hở hẹp, có thể nhìn thấy ánh sáng của một thế giới khác bên ngoài."
  },
  AvgDialog_45444_Content_11 = {
    Text = "Trong khe hở chớp nhoáng ấy, tôi đã theo đội quân của tộc Aran di chuyển và lưu lạc khắp nơi."
  },
  AvgDialog_45444_Content_12 = {
    Text = "Tôi đã chứng kiến Elva kiên quyết gánh vác trọng trách khi thiếu lãnh đạo."
  },
  AvgDialog_45444_Content_13 = {
    Text = "Tôi đã chứng kiến quyết tâm của Elva khi bãi bỏ nghi lễ đống lửa, nỗi đau đớn tột cùng khi người kế thừa do cô ấy đào tạo qua đời quá sớm, và sự bất lực khi phải tái khởi động nghi lễ đó."
  },
  AvgDialog_45444_Content_14 = {
    Text = "Đã chứng kiến Elva dẫn đội tìm kiếm nước uống và vật tư, cũng như cô ấy chủ động ra trận để đối kháng Nubia."
  },
  AvgDialog_45444_Content_15 = {
    Text = "Elva, bạn đã làm rất tốt rồi."
  },
  AvgDialog_45444_Content_16 = {
    Text = "Dù tôi có ở lại đây, cũng chẳng thể làm tốt hơn cậu."
  },
  AvgDialog_45444_Content_17 = {
    Text = "Vì vậy, những việc tiếp theo, giao hết cho tôi đi."
  },
  AvgDialog_45444_Content_18 = {
    Text = "Thái Di Sơ vuốt ve đầu Elva, sau đó quay người đối mặt với hàng vạn binh lính Á Lan đang ngây dại."
  },
  AvgDialog_45444_Content_19 = {
    Text = "Tôi là mẹ của trái đất, hóa thân của bản chất dục vọng."
  },
  AvgDialog_45444_Content_2 = {
    Text = "Nữ hoàng đại nhân…… tôi…… xin lỗi…… Aran……"
  },
  AvgDialog_45444_Content_20 = {
    Text = "Tôi tên là Thái Di Sơ, Thánh danh <Yellow:Đề Phu Lôi · Da Xơ Đồ>."
  },
  AvgDialog_45444_Content_21 = {
    Text = "Tôi, nhân danh nữ hoàng duy nhất của Aran, trừng phạt cây mẹ phong thịnh giả dối này, kẻ nuốt chửng sinh linh và lan truyền cái chết."
  },
  AvgDialog_45444_Content_22 = {
    Text = "Tôi sẽ giải cứu người dân Aran thông qua bạn, tìm kiếm con đường sinh tồn cho họ."
  },
  AvgDialog_45444_Content_23 = {
    Text = "Hỡi người dân của A-lan, nếu các ngươi vẫn có thể nghe thấy tiếng ta, hãy thức tỉnh đi!"
  },
  AvgDialog_45444_Content_24 = {
    Text = "Thế giới chìm vào sự tĩnh lặng trong khoảnh khắc."
  },
  AvgDialog_45444_Content_25 = {
    Text = "Tuy nhiên, chỉ sau vài giây, đội của Á Lan lại lao xuống sông thiêng liêng như những kẻ không biết mệt mỏi, không hề chùn bước."
  },
  AvgDialog_45444_Content_26 = {
    Text = "Không có ích gì, bạn và cây mẹ phong thịnh cùng gốc rễ, đều đã bị ý chí của đại nhân ấy xâm nhiễm. Với lực lượng hiện tại của bạn, hoàn toàn không thể lay chuyển ý chí của cây mẹ đã bị xâm thực."
  },
  AvgDialog_45444_Content_27 = {
    Text = "Tất nhiên tôi biết."
  },
  AvgDialog_45444_Content_28 = {
    Text = "Nếu không phải như vậy, thì đâu cần phải mất hàng trăm năm gian nan để vượt qua?"
  },
  AvgDialog_45444_Content_29 = {
    Text = "Tôi dùng thân cây mẹ ẩn mình trong sông thiêng liêng, bằng thân xác chịu đựng rỗng rỗng để giấu hạt giống của cây mẹ, chẳng phải chính là để chờ đợi thời khắc này sao?"
  },
  AvgDialog_45444_Content_3 = {
    Text = "Không cần lo lắng. Lời tâm sự của bạn, tôi đã nghe thấy rồi."
  },
  AvgDialog_45444_Content_30 = {
    Text = "Giờ khắc quyết chiến đã đến!"
  },
  AvgDialog_45444_Content_31 = {
    Text = "Tôi nhân danh Tifra Yesod, Thể Chất của ham muốn, đề nghị <Yellow:Tà Vy> hãy đáp lại lời hứa từ ngàn năm trước ——"
  },
  AvgDialog_45444_Content_32 = {
    Text = "Khi sứ giả từ phương xa đến, hãy để hóa thân của bạn dẫn lối, tạm thời xua tan bóng tối phủ Lemvahi."
  },
  AvgDialog_45444_Content_33 = {
    Text = "Trong bầu trời vang lên tiếng kêu bi thảm và vang dội."
  },
  AvgDialog_45444_Content_34 = {
    Text = "Thái Di Sơ mở quan tài, người lật mình ra chính là Ramona bị cháy đỏ bừng mặt."
  },
  AvgDialog_45444_Content_35 = {
    Text = "Cuối cùng…… cần tôi rồi chăng……"
  },
  AvgDialog_45444_Content_36 = {
    Text = "Trốn ở đây và theo sau, cũng thật khéo nghĩ ra, cô gái nhỏ."
  },
  AvgDialog_45444_Content_37 = {
    Text = "Cũng may bạn đã đi theo, nếu không thì mỗi phút quay lại đón bạn, sẽ tiêu thụ không biết bao nhiêu sức sống."
  },
  AvgDialog_45444_Content_38 = {
    Text = "Giọng nói trong đầu tôi… cô ấy bảo tôi… tôi phải kiên trì…"
  },
  AvgDialog_45444_Content_39 = {
    Text = "Tuy nhiên, ngay cả khi cô ấy không nói… \nTôi cũng là trợ lý duy nhất của %player%, khi nguy hiểm nhất, tôi phải ở cạnh {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_45444_Content_4 = {
    Text = "Bởi vì, không ai hiểu rõ nỗi đau không được lắng nghe hơn tôi."
  },
  AvgDialog_45444_Content_40 = {
    Text = "Đây là trách nhiệm của tôi với tư cách là trợ lý duy nhất, đúng không?"
  },
  AvgDialog_45444_Content_41 = {
    Text = "Cô ấy nhấn mạnh hai chữ \"duy nhất\"."
  },
  AvgDialog_45444_Content_42 = {
    Text = "Trên mảnh đất này, khi đánh thức lực lượng của cô ấy, ảnh hưởng lên cơ thể bạn sẽ ngày càng dữ dội hơn."
  },
  AvgDialog_45444_Content_43 = {
    Text = "Nếu còn cách khác, tôi cũng không muốn phải dùng đến biện pháp hạ sách này."
  },
  AvgDialog_45444_Content_44 = {
    Text = "Misaque đã đến đây để ngăn chặn nghi lễ, tôi là một thành viên của Misaque, sẵn sàng hy sinh tất cả!"
  },
  AvgDialog_45444_Content_45 = {
    Text = "Good! Ramona suppresses the desire essence. %player%, you and I together will completely defeat the Mother Tree!"
  },
  AvgDialog_45444_Content_46 = {
    Text = "Trong không trung vang lên tiếng rít chói tai, bóng dáng bạc mờ ảo cắt qua bầu trời sa mạc."
  },
  AvgDialog_45444_Content_48 = {
    Text = "Bạn cảm thấy thân thể nhẹ bẫng, và trong giây tiếp theo đã rơi xuống trước một khối u bẩn và hôi thối."
  },
  AvgDialog_45444_Content_49 = {
    Text = "Người Aran bị cây mẹ nuốt chửng tích tụ ở đây dưới dạng trứng, trong những lỗ hổng bán trong suốt, vô số khuôn mặt méo mó và mờ ảo, chỉ có chất lỏng màu đỏ đen chảy ra không ngừng từ các lỗ hổng, đổ vào dòng sông thiêng liêng không còn trong lành."
  },
  AvgDialog_45444_Content_5 = {
    Text = "Tôi theo đội của Á Lan, đã di cư suốt hàng trăm năm."
  },
  AvgDialog_45444_Content_6 = {
    Text = "Không một ai nhìn thấy hay nghe thấy tôi cả."
  },
  AvgDialog_45444_Content_7 = {
    Text = "Tôi từng là vũ công xinh đẹp nhất trong buổi tiệc, cũng từng là nữ hoàng được kính trọng nhất của tộc Á Lan. \nNhưng giờ đây, không ai còn nhìn thấy điệu nhảy của tôi, không ai còn lắng nghe mệnh lệnh của tôi."
  },
  AvgDialog_45444_Content_8 = {
    Text = "Bên trong vùng rỗng, là một thế giới khác."
  },
  AvgDialog_45444_Content_9 = {
    Text = "Tối đen, yên lặng, tuyệt vọng."
  },
  AvgDialog_46539_Content_1 = {
    Text = "Sau một năm giảng dạy và điều tra nhiệm vụ gần đây, tư cách của bạn hiện đã đủ để tiếp xúc với \"đối đầu pha\"."
  },
  AvgDialog_46539_Content_10 = {
    Text = "Tất nhiên, những thực thể tham gia chiến đấu đều là thân thể được đánh thức —— tuy nhiên trong quá trình pha vị, một số tồn tại sẽ bị giới hạn vật lý <Yellow:sự méo mó>."
  },
  AvgDialog_46539_Content_11 = {
    Text = "<Yellow:khả năng của thân thể được đánh thức>, <Yellow:rào cản giữa các giới vực> cũng như <Yellow:quy tắc chiến đấu> đều khác xa so với thực tế."
  },
  AvgDialog_46539_Content_12 = {
    Text = "Bạn sẽ không thể <Yellow:phát triển> các thân thể được đánh thức, nhưng <Yellow:đối phương cũng vậy>. Trong một mức độ nhất định, \"Đối đầu Pha\" là một cuộc <Yellow:đấu tay đôi công bằng>."
  },
  AvgDialog_46539_Content_13 = {
    Text = "Khởi động thiết bị pha, hãy thử một ván cờ đi, mọi thắc mắc sẽ được giải đáp trong thực chiến. Mong chìa khóa bạc soi sáng con đường phía trước."
  },
  AvgDialog_46539_Content_2 = {
    Text = "À, mà, bạn có nghe ai đó đề cập đến \"đối đầu pha\" không?"
  },
  AvgDialog_46539_Content_3 = {
    Text = "Hiểu biết một phần"
  },
  AvgDialog_46539_Content_4 = {
    Text = "Rất tốt, nhưng dựa trên nội quy của trường, tôi phải giải thích cho bạn một cách toàn diện hơn về các rủi ro và quy tắc."
  },
  AvgDialog_46539_Content_5 = {
    Text = "Chưa hề nghe thấy"
  },
  AvgDialog_46539_Content_6 = {
    Text = "Được, vậy tôi sẽ bắt đầu giới thiệu từ đầu."
  },
  AvgDialog_46539_Content_7 = {
    Text = "Trong quá trình nghiên cứu về bạc tâm, chúng tôi đã phát hiện ra rằng khi bạc tâm rung động, sóng dao động được tạo ra thỉnh thoảng có thể vượt qua ranh giới vật lý. Chúng tôi gọi vị trí xảy ra sóng dao động là <Yellow:phased>."
  },
  AvgDialog_46539_Content_8 = {
    Text = "Mà \"đối đầu pha\", chính là một phương pháp sử dụng pha để <Yellow:chiến đấu> với bản thân từ một không gian-thời gian khác, nhằm đạt được hiệu ứng rèn luyện tinh thần và ý thức chiến đấu."
  },
  AvgDialog_46539_Content_9 = {
    Text = "Phiên bản khác của chính mình…"
  },
  AvgDialog_46700_Content_1 = {
    Text = "Chỉ số Nos 89.8, tần số triều 762hz, vẫn đang tiếp tục tăng…"
  },
  AvgDialog_46700_Content_2 = {
    Text = "Không còn nghi ngờ gì nữa, đó là <Yellow:đại thủy triều đen>. Các bộ phận vào vị trí, nhóm giám sát báo cáo chỉ số Nos theo thời gian thực, nhóm đối sách chuẩn bị phương án, nhóm hành động triển khai thiên nhiên mật cảnh, chuẩn bị xâm nhập khu vực cấm của hòa hợp với thiên tai thông qua kích thước tinh thần!"
  },
  AvgDialog_46700_Content_3 = {
    Text = "Dòng lũ đen tối?"
  },
  AvgDialog_46700_Content_4 = {
    Text = "Sự dao động theo giai đoạn của chiều không gian ý thức bên trong hồ đen do thủy triều ảnh hưởng, nếu xử lý không đúng cách cũng có thể gây ra thảm họa lớn trong các <Yellow:khu vực cấm hòa hợp với thiên tai>."
  },
  AvgDialog_46700_Content_5 = {
    Text = "Dị thường nổi lên mà Giám đốc Học viện Kherat đề cập trong lễ trao chìa khóa chính là dấu hiệu của sự bùng phát đại thủy triều đen."
  },
  AvgDialog_46700_Content_6 = {
    Text = "Dòng triều tinh thần không rõ có thể can thiệp vào sự ổn định của thâm cảnh, môi trường bên trong biến đổi liên tục, <Yellow:thân thể được đánh thức và kẻ địch có thể bị ảnh hưởng bởi đại thủy triều đen>…"
  },
  AvgDialog_46700_Content_7 = {
    Text = "Nguyên lý sẽ được thảo luận sau trong lớp, làn sóng đầu tiên của hòa hợp với thiên tai đang tới, chuẩn bị đối phó với đại thủy triều đen!"
  },
  AvgDialog_46700_Content_8 = {
    Text = "Nguyện chìa khóa bạc dẫn đường cho các bạn."
  },
  AvgDialog_46733_Content_1 = {
    Text = "Dù chỉ là một đêm trực ngoại bình thường, nhưng những đêm ở ngoài trường, em luôn ngủ không yên tâm."
  },
  AvgDialog_46733_Content_10 = {
    Text = "Orci, bạn có chỗ nào không thoải mái không?"
  },
  AvgDialog_46733_Content_11 = {
    Text = "Chủ công, tôi... không... là chúng.."
  },
  AvgDialog_46733_Content_12 = {
    Text = "Orci cố gắng ôm lấy đối tượng vô hình không thể kiểm soát, những thứ vốn chỉ quấn quanh bên người như lực lượng của Orci bỗng trở nên cực kỳ hoạt bát——"
  },
  AvgDialog_46733_Content_13 = {Text = "Xèo."},
  AvgDialog_46733_Content_14 = {
    Text = "Hoạt động, chúng sẽ \"liếm\" lên mặt bạn như lưỡi mèo khi bạn lại gần để xem."
  },
  AvgDialog_46733_Content_15 = {
    Text = "Chủ quân——?!"
  },
  AvgDialog_46733_Content_16 = {
    Text = "Tôi, ơ, không… cố ý…"
  },
  AvgDialog_46733_Content_17 = {
    Text = "Bạn đẩy ra vật vô hình mềm mại như một con mèo, ngón tay chìm vào mái tóc vàng mềm mại của Orci, xoa dịu nhẹ nhàng mái tóc của anh ấy."
  },
  AvgDialog_46733_Content_18 = {
    Text = "Không sao, từ từ nói"
  },
  AvgDialog_46733_Content_19 = {
    Text = "Tôi… Tôi không biết tại sao, hôm nay tôi rất muốn ở bên cạnh chủ công. Cảm giác này mạnh mẽ đến nỗi, mạnh mẽ đến nỗi những vật vô hình hoàn toàn không còn nghe theo sự điều khiển của tôi…"
  },
  AvgDialog_46733_Content_2 = {
    Text = "Tiếng thế giới trở nên đặc biệt rõ ràng và gây chú ý trong bóng tối, đặc biệt là những hơi thở non nớt mà nặng nề ——"
  },
  AvgDialog_46733_Content_20 = {
    Text = "<Small:Có phải là do ảnh hưởng của sông thiêng liêng và cây mẹ không?>"
  },
  AvgDialog_46733_Content_21 = {
    Text = "Nếu làm phiền đến chủ công thì……"
  },
  AvgDialog_46733_Content_22 = {
    Text = "Không sao đâu."
  },
  AvgDialog_46733_Content_23 = {
    Text = "Thật, thật sự sao?!"
  },
  AvgDialog_46733_Content_24 = {
    Text = "Bạn kéo Orci vào phòng, đẩy mạnh anh ta xuống giường, rồi kéo một chiếc ghế lại, ngồi cạnh giường."
  },
  AvgDialog_46733_Content_25 = {
    Text = "Hãy ở lại đây tối nay, như vậy bạn có thể ngủ thật ngon."
  },
  AvgDialog_46733_Content_26 = {
    Text = "Tôi làm sao có thể qua đêm trên giường của chúa công, điều này không phù hợp với lễ tiết ——"
  },
  AvgDialog_46733_Content_27 = {
    Text = "Orci bị bạn quấn trong chăn thành một cục, cả người ngọ nguậy bất an như sâu đang bò, cho đến khi bạn đặt tay lên trán của anh ấy."
  },
  AvgDialog_46733_Content_28 = {
    Text = "Ngủ đi, ngủ đi……"
  },
  AvgDialog_46733_Content_29 = {
    Text = "Bạn chưa nghe qua mấy bài ru, giai điệu mà bạn bất giác ngân nga cũng chỉ là một trong nhiều bài đồng dao kinh dị của Lentiennam."
  },
  AvgDialog_46733_Content_3 = {
    Text = "Sau khi trời sáng còn có nhiệm vụ điều tra chờ chúng ta, sao còn chưa ngủ?"
  },
  AvgDialog_46733_Content_30 = {
    Text = "Nhưng đôi mắt sáng của Orci dần tối đi, như những vì sao sớm chìm vào sương mỏng trước bình minh."
  },
  AvgDialog_46733_Content_31 = {
    Text = "Chủ... gọi... chủ quân.."
  },
  AvgDialog_46733_Content_32 = {
    Text = "Bạn đứng bên giường nhìn anh ấy lâu lắm, cho đến khi hơi thở trở nên đều đặn, bầu trời đêm bên ngoài cũng trở nên mờ ảo. Bạn mới vuốt ve những sợi tóc mai trên trán anh ấy, rồi rón rén rời khỏi phòng."
  },
  AvgDialog_46733_Content_33 = {
    Text = "Ngủ một giấc ngon, bé ngoan."
  },
  AvgDialog_46733_Content_4 = {
    Text = "Chủ, chủ quân! Orci không cố ý quấy rầy giấc ngủ của chủ quân, chỉ là, chỉ là…"
  },
  AvgDialog_46733_Content_5 = {
    Text = "Orci ôm vũ khí, dựa lưng vào lối đi, như một tượng đài hiệp sĩ canh gác trước cửa của bạn."
  },
  AvgDialog_46733_Content_6 = {
    Text = "Anh ta không biết đã đứng ngốc nghếch ở hành lang bao lâu, khi thấy bạn mở cửa, anh ta phản xạ muốn chào bạn, nhưng thân thể yếu ớt loạng choạng."
  },
  AvgDialog_46733_Content_7 = {
    Text = "—— Cẩn thận!"
  },
  AvgDialog_46733_Content_8 = {
    Text = "Bạn đã vững vàng đỡ lấy cậu thiếu niên suýt ngã, nhưng dường như chỉ khiến Orci càng lúng túng."
  },
  AvgDialog_46733_Content_9 = {
    Text = "Anh ta mặt đỏ bừng, luống cuống, dường như cố gắng kiểm soát thứ vô hình không ngừng tuôn ra, lại như muốn chạy trốn khỏi bạn."
  },
  AvgDialog_46734_Content_1 = {
    Text = "Xin lỗi, người giữ gìn, xin đừng nhìn tôi tạm thời."
  },
  AvgDialog_46734_Content_10 = {
    Text = "Bàn tay của người phụ nữ nắm chặt cánh tay bạn, các khớp ngón tay dài và mạnh mẽ, thậm chí qua lớp vải, bạn vẫn có thể cảm nhận được vết chai do sử dụng súng lâu năm."
  },
  AvgDialog_46734_Content_11 = {
    Text = "Trong suốt những năm dài này, tôi đã quen với việc chịu đựng ảnh hưởng từ Sông thiêng… Đúng vậy, Ngài thánh thiện, đầy lòng từ bi, giúp cho tộc người được duy trì, nhưng những gì tôi theo đuổi, không thể tìm thấy trong ánh sáng rực rỡ của Ngài."
  },
  AvgDialog_46734_Content_12 = {
    Text = "Khi nói những câu rất chính trực như vậy, Alva... Hành động của bạn có vẻ không nên như vậy nhỉ?!"
  },
  AvgDialog_46734_Content_13 = {
    Text = "Ý tôi là, bây giờ tôi rất bình tĩnh, hành động của tôi không phải xuất phát từ Sông thiêng, cũng không đến từ bất kỳ sức mạnh bên ngoài nào."
  },
  AvgDialog_46734_Content_14 = {
    Text = "<LightGray:（Không, bạn trông hoàn toàn không bình tĩnh。）>"
  },
  AvgDialog_46734_Content_15 = {
    Text = "Nói rằng có lẽ không phù hợp, ngay cả khi bị tước đoạt thị lực, bạn vẫn biết hành động bây giờ chắc chắn không phải là những gì Alva thường làm được."
  },
  AvgDialog_46734_Content_16 = {
    Text = "……Chỉ là đối phương rõ ràng không nghĩ như vậy."
  },
  AvgDialog_46734_Content_17 = {
    Text = "Bởi vì tôi đã biết, để đạt được tầm nhìn mà tôi ao ước, nên bảo vệ cái gì, vì ai mà sử dụng."
  },
  AvgDialog_46734_Content_18 = {
    Text = "Vậy, tôi đang nghĩ—liệu bây giờ, tôi có thể chọn tuân theo bản năng, để khám phá những điều mà tôi chưa bao giờ chạm đến."
  },
  AvgDialog_46734_Content_19 = {
    Text = "Narra của Alva vô cùng bình tĩnh, dường như đây chỉ là báo cáo về một kế hoạch tập huấn nào đó."
  },
  AvgDialog_46734_Content_2 = {
    Text = "Alva, bạn có chắc mình không sao chứ, bạn nghe có vẻ không được tốt."
  },
  AvgDialog_46734_Content_20 = {
    Text = "Nhưng nhịp tim lại phản bội chủ nhân, sự ồn ào đó khó khăn như ánh sáng trước mắt bạn khó bị che giấu."
  },
  AvgDialog_46734_Content_21 = {
    Text = "Người đã từng dấn thân vào sự chính nghĩa này, rõ ràng đang trải qua một cuộc chiến khác với chính mình."
  },
  AvgDialog_46734_Content_22 = {
