  AvgDialog_47175_Content_13 = {
    Text = "Khen ngợi Chúa của chúng ta! Chào đón thần quốc!"
  },
  AvgDialog_47175_Content_14 = {
    Text = "Đền thần Lemuria hùng vĩ sừng sững, như một ngọn núi đứng hiên ngang bên bờ biển rộng lớn."
  },
  AvgDialog_47175_Content_15 = {
    Text = "Các tín đồ ùa đến, chen chúc ở quảng trường bên ngoài đền thần, nhìn vào bàn thờ thần lấp lánh ánh sáng mờ ảo và bí ẩn, khí thế hùng vĩ."
  },
  AvgDialog_47175_Content_16 = {
    Text = "Người dân nhón chân, vượt qua biển người và đám đông thị vệ, cố gắng nhìn vào bên trong bàn thờ thần, chỉ mong thoáng nhìn thấy bóng hình vị vua mới."
  },
  AvgDialog_47175_Content_17 = {
    Text = "Sau bàn thờ thần, cánh cửa đá lớn và uy nghiêm của đền thần hiếm khi mở ra trước mặt tín đồ. Gió mang theo hơi thở sâu thẳm của biển từ bên trong đền thần thổi ra, tấm rèm mỏng manh trong suốt nhẹ nhàng bay phất phơ trong gió."
  },
  AvgDialog_47175_Content_18 = {
    Text = "Miriam đứng trước hàng các linh mục bên ngoài bàn thờ thần, hai tay nắm chặt, đứng nhìn không động đậy vào phía sau bức màn."
  },
  AvgDialog_47175_Content_19 = {
    Text = "Một bóng dáng mờ ảo, nghiêng mình dựa vào ngai vàng phía sau bức màn, đang ngủ say. Chiếc vương miện độc nhất vô nhị tượng trưng cho vua, khiến hơi thở của Miriam không tự chủ được mà trở nên rối loạn."
  },
  AvgDialog_47175_Content_2 = {
    Text = "Đùng…… đùng……"
