  AvgDialog_47175_Content_20 = {
    Text = "Rầm——"
  },
  AvgDialog_47175_Content_21 = {Text = "À!——"},
  AvgDialog_47175_Content_22 = {
    Text = "Tiếng sấm đột ngột vang lên, khiến các tín đồ dừng lại. Nỗi sợ hãi về sấm sét chảy trong huyết mạch của họ, họ lo lắng ngẩng đầu lên."
  },
  AvgDialog_47175_Content_23 = {
    Text = "Bầu trời vốn bị che phủ bởi tầng mây trở nên tối tăm hơn. Sấm sét vang rền, đại dương gầm lên, dâng lên những con sóng tượng trưng cho thảm họa và cái chết."
