  AvgDialog_47175_Content_32 = {
    Text = "Từ hôm nay, Lemuria sẽ có vị vua mới."
  },
  AvgDialog_47175_Content_33 = {
    Text = "Kể từ ngày này, mọi tai họa sẽ phải lùi bước trước ta."
