  AvgDialog_47175_Content_36 = {
    Text = "Bạn xem! Bạn xem trên trời!"
  },
  AvgDialog_47175_Content_37 = {
    Text = "Gần như ngay khi lời của Tulô vừa thốt ra, những đám mây đen trên trời bắt đầu tan biến với tốc độ mắt thường có thể thấy."
  },
  AvgDialog_47175_Content_38 = {
    Text = "Tiếng gọi của đại dương bắt đầu lắng xuống, ánh nắng mặt trời chiếu rọi, soi sáng khuôn mặt của mỗi tín đồ."
  },
  AvgDialog_47175_Content_39 = {
    Text = "Diệu kỳ…… Đây là diệu kỳ!"
  },
  AvgDialog_47175_Content_4 = {
    Text = "Tiếng chuông vang đến bờ biển, vang đến núi non, vang đến thành phố và làng quê."
  },
  AvgDialog_47175_Content_40 = {
    Text = "Màn che phía sau bàn thờ thần, dưới ánh nắng, hiện ra một hình dáng rõ ràng."
  },
  AvgDialog_47175_Content_41 = {
