  AvgDialog_47175_Content_42 = {
    Text = "Rầm……"
  },
  AvgDialog_47175_Content_43 = {
    Text = "Dưới động tác của anh ta, nhiều xúc tu khổng lồ xuyên qua đại dương, đồng bằng và núi đồi. Cuối cùng, chúng hiện ra trước mắt mọi người."
  },
  AvgDialog_47175_Content_44 = {
