  AvgDialog_47175_Content_56 = {
    Text = "Ah, vị linh mục lớn của tôi đã trở về!"
  },
  AvgDialog_47175_Content_57 = {Text = "Bố……"},
  AvgDialog_47175_Content_58 = {
    Text = "Nước mắt làm mờ tầm nhìn của cô ấy. Giọng cô ấy khàn đặc, không thể nói nên lời."
