  AvgDialog_47175_Content_6 = {
    Text = "Tiếng kêu cùng với tiếng chuông vang vọng, truyền vào tai mỗi người dân trong vương quốc rộng lớn này."
  },
  AvgDialog_47175_Content_60 = {
    Text = "Đừng buồn, Miriam. Cô đã làm được… Cô đã giúp vua, mang lại thần quốc!"
  },
  AvgDialog_47175_Content_61 = {
    Text = "Bây giờ, chúng ta không còn phải sợ hãi gì nữa. Gia đình chúng ta sẽ sống hạnh phúc bên nhau trong thần quốc. Mãi mãi…"
