  AvgDialog_47175_Content_63 = {
    Text = "Em gái chạy đến bên cô ấy, ôm chặt cô ấy. mẹ đến bên cô ấy, ghé vào lòng cô ấy. cha đến bên cô ấy, ôm lấy cô ấy."
  },
  AvgDialog_47175_Content_64 = {
    Text = "Ôm. Ôm với thân thể. Ôm ấm áp. Ôm chỉ để sum họp, không phải để chia ly. Ôm mà không ai vắng mặt."
  },
  AvgDialog_47175_Content_65 = {
    Text = "Ôm, đó là tất cả những gì cô ấy tìm kiếm."
