  AvgDialog_47175_Content_66 = {
    Text = "Nước mắt tràn ra lăn xuống khuôn mặt của Miriam. Cô ấy ngẩng đầu lên."
  },
  AvgDialog_47175_Content_67 = {
    Text = "Cái ôm biến mất. Ánh sáng thay đổi, cô ấy trở lại trước đền thần. Trước mặt cô là vô số tín đồ, họ cũng đang rơi nước mắt."
  },
  AvgDialog_47175_Content_68 = {
    Text = "Cảnh quan huy hoàng của thần quốc, khát vọng sâu thẳm nhất trong lòng mỗi người, hiện ra rõ ràng trước mắt các tín đồ."
  },
  AvgDialog_47175_Content_69 = {
    Text = "Tôi đã thấy…… Tôi đã thấy, bệ hạ!"
  },
  AvgDialog_47175_Content_7 = {
    Text = "Hàng triệu người Lemuria đổ ra đường phố, chiếm lĩnh mọi con đường và quảng trường, hò reo và mong ngóng cuồng nhiệt."
  },
  AvgDialog_47175_Content_70 = {
    Text = "Đây chính là thần quốc…… Đây chính là thần quốc mà ngài sẽ mang lại cho chúng ta!"
  },
  AvgDialog_47175_Content_71 = {
    Text = "Chủ nhân… tôi đã thấy!"
  },
  AvgDialog_47175_Content_72 = {
    Text = "Miriam thì thầm những lời lẽ lặp đi lặp lại, quỳ gối trước vị tân vương sau tấm màn."
  },
  AvgDialog_47175_Content_73 = {
