  AvgDialog_47175_Content_74 = {
    Text = "Qua đôi mắt đẫm lệ mờ ảo, vô số ánh mắt chăm chú hướng về phía bàn thờ thần, về phía sau tấm màn, nơi in hình dáng nhỏ bé của vị vua mới."
  },
  AvgDialog_47175_Content_75 = {
