  AvgDialog_47175_Content_78 = {
    Text = "Lễ chính dời sang một bên, hạ thấp giọng."
  },
  AvgDialog_47175_Content_79 = {
    Text = "Chủ nhân, Lemuria đã chứng kiến uy nghi của ngài. Xin hãy tiếp tục nói. Hãy mang hy vọng đến cho Lemuria."
  },
  AvgDialog_47175_Content_8 = {
    Text = "Vị vua già hoặc là đã thoái vị, hoặc là đã qua đời. Người Lemuria không hề hay biết, cũng chẳng mấy bận tâm."
  },
  AvgDialog_47175_Content_80 = {
    Text = "Anh ta làm cử chỉ mời, cúi người chào tulô ."
  },
  AvgDialog_47175_Content_81 = {
    Text = "Vị vua trẻ im lặng một lúc, sau đó tiến lên một bước."
  },
  AvgDialog_47175_Content_82 = {
    Text = "Dư, người thay mặt thần minh, Vua Lemuria."
  },
  AvgDialog_47175_Content_83 = {
    Text = "Dư…… sẽ mang đến cho Lemuria thần quốc."
  },
  AvgDialog_47175_Content_84 = {
    Text = "Thần minh… thần minh bảo hộ Lemuria!"
  },
  AvgDialog_47175_Content_85 = {
    Text = "Chúa của tôi! Ngợi khen Chúa của tôi!"
  },
  AvgDialog_47175_Content_86 = {
    Text = "Tán tụng chủ ta!!"
  },
  AvgDialog_47175_Content_87 = {
    Text = "Nhiều ngàn tín đồ quỳ gối trên mặt đất, tiếng reo hò như sấm động, vang vọng khắp mọi góc của vương quốc."
  },
  AvgDialog_47175_Content_88 = {
    Text = "Tulô mệt mỏi quay người."
  },
  AvgDialog_47175_Content_89 = {
    Text = "Lemuria mong đợi những lời còn lại của ta, ta đã nói xong."
  },
  AvgDialog_47175_Content_9 = {
    Text = "Trong những năm tháng dài đằng đẵng đấu tranh chống lại tai ương, họ đã học được cách không than khóc cho ngày hôm qua. Trong mắt họ, chỉ có ngày mai sáng ngời dưới ánh hào quang của thần quốc mà vị tân vương mang lại."
  },
  AvgDialog_47175_Content_90 = {
    Text = "Tôi mệt rồi. Không cần phải theo tôi."
  },
  AvgDialog_47175_Content_91 = {
    Text = "Ông vẫy tay, giữ lại các vệ sĩ và chủ tế muốn theo sau."
  },
  AvgDialog_47175_Content_92 = {
    Text = "Trong tiếng hò hét đầy nhiệt huyết của tín đồ, vị vua mới trẻ tuổi im lặng, một mình bước vào đền thần không một bóng người."
  },
  AvgDialog_47176_Content_1 = {Text = "Dự ngôn"},
  AvgDialog_47176_Content_10 = {
    Text = "Nhà cửa gần như hoàn toàn sụp đổ, đá vụn chặn cô trong góc hẹp này. Cơn mưa lớn xuyên qua khe hở giữa các tảng đá, tạt vào người cô."
  },
  AvgDialog_47176_Content_100 = {
    Text = "\"Nhưng, nhưng cha tôi là một tín đồ mộ đạo, vua yêu quý dân chúng của mình, sẽ không để tôi...\""
  },
  AvgDialog_47176_Content_101 = {
    Text = "\"Ngươi không nên làm linh mục. Ngươi không nên sinh ra ở Lemuria. Ngươi nên bị lưu đày, hoặc xử tử.\""
  },
  AvgDialog_47176_Content_102 = {
    Text = "\"Miriam, Đại tế tự không phải là ý đó...\""
  },
  AvgDialog_47176_Content_103 = {
    Text = "\"Thưa người chủ tế! Xin tha thứ cho Miriam, cô ấy chỉ không biết cách diễn đạt... Chúng tôi sẵn lòng dâng hiến mọi thứ cho vua!...\""
  },
  AvgDialog_47176_Content_104 = {
    Text = "\"Thần minh dẫn dắt tôi đến đây. Đây chính là số mệnh mà các vì sao chỉ ra... số mệnh, ha.\""
  },
  AvgDialog_47176_Content_105 = {
    Text = "Linh mục không để ý đến lời của Inos và Miriam, ông thở dài sâu và quay trở lại sâu bên trong đền thần."
  },
  AvgDialog_47176_Content_106 = {
    Text = "Rất nhanh, một linh mục chạy đến, tiếng bước chân vang vọng trong đại sảnh yên tĩnh."
  },
  AvgDialog_47176_Content_107 = {
    Text = "Cô ấy dừng lại trước mặt Miriam, mỉm cười với Miriam và trao cho Miriam một huy hiệu."
  },
  AvgDialog_47176_Content_108 = {
    Text = "\"Bảy ngày sau, mang nó đến đền thần để tham gia huấn luyện.\""
  },
  AvgDialog_47176_Content_109 = {
    Text = "\"Chúc mừng bạn, Miriam. Bạn đã trở thành thực tập sinh linh mục của Lemuria.\""
  },
  AvgDialog_47176_Content_11 = {
    Text = "Một số tảng đá lớn treo lơ lửng trên đầu cô, được một cột đá mỏng đầy nứt nẻ cố gắng đỡ lấy, run rẩy trong mưa."
  },
  AvgDialog_47176_Content_110 = {Text = "\"!!!\""},
  AvgDialog_47176_Content_111 = {
    Text = "\"chị gái được chọn! chị gái được chọn!\""
  },
  AvgDialog_47176_Content_112 = {
    Text = "Sara vui mừng nhảy lên, Inos hướng về phía bức tượng, đôi tay nắm chặt run nhẹ trước ngực."
  },
  AvgDialog_47176_Content_113 = {
    Text = "\"Cảm ơn ngài linh mục, cảm ơn ngài!\""
  },
  AvgDialog_47176_Content_114 = {
    Text = "\"Chúa đã nghe thấy tiếng chúng con... Cảm tạ Chúa... Nguyện cảm tạ mãi mãi...\""
  },
  AvgDialog_47176_Content_115 = {
    Text = "\"Paya, cô có nghe thấy không? Con của chúng ta đã trở thành thực tập sinh linh mục rồi!\""
  },
  AvgDialog_47176_Content_116 = {
    Text = "\"Nếu như bạn có thể thấy, chắc chắn bạn sẽ rất vui phải không, Paya...\""
  },
  AvgDialog_47176_Content_117 = {
    Text = "Miriam vẫn đứng im tại chỗ, vẫn chưa hiểu chuyện gì xảy ra."
  },
  AvgDialog_47176_Content_118 = {
    Text = "Em gái reo hò một cách vô tư, cha lặng lẽ lau đi nước mắt, xung quanh là những lời chúc mừng chân thành hoặc đố kỵ từ đám đông."
  },
  AvgDialog_47176_Content_119 = {
    Text = "Một huy hiệu tối màu khắc họa xúc tu và bão nằm yên trong lòng bàn tay cô, thờ ơ trước mọi cảnh vật và âm thanh xung quanh, tựa như một lời tiên tri lặng lẽ."
  },
  AvgDialog_47176_Content_12 = {
    Text = "\"Kính, kính yêu Đại Vương...\""
  },
  AvgDialog_47176_Content_120 = {
    Text = "\"Bạn thích ăn cá, sau khi về, tôi sẽ nấu một bàn thức ăn mà bạn yêu thích nhất!\""
  },
  AvgDialog_47176_Content_121 = {
    Text = "\"Tôi sẽ đi thông báo cho mọi người, kể cho họ biết tin vui này!\""
  },
  AvgDialog_47176_Content_122 = {
    Text = "\"Nhà tôi, Miriam, sắp trở thành linh mục tại Lemuria rồi!\""
  },
  AvgDialog_47176_Content_123 = {
    Text = "\"còn là học việc mà...\""
  },
  AvgDialog_47176_Content_124 = {
    Text = "\"Chủ tế đại nhân đã đặc biệt quan tâm đến em, điều đó chứng tỏ tài năng của Miriam chúng ta là không thể xem thường! Chắc chắn sẽ không có vấn đề gì đâu!\""
  },
  AvgDialog_47176_Content_125 = {
    Text = "Miriam không hiểu ý của chủ tế, cũng không rõ vì sao mình được trao quyền này. Cô nhìn bố và em gái. Đã lâu rồi cô không thấy họ hạnh phúc như vậy."
  },
  AvgDialog_47176_Content_126 = {
    Text = "Miriam vuốt ve biểu trưng, nụ cười hiện lên trên khuôn mặt cô."
  },
  AvgDialog_47176_Content_127 = {
    Text = "Cuối cùng, cô cũng giống như cha mình, mang lại nụ cười cho gia đình. Vậy thì hãy để nụ cười này tiếp tục duy trì mãi mãi. Cô nghĩ."
  },
  AvgDialog_47176_Content_13 = {
    Text = "\"Xin... cứu giúp người tín đồ trung thành của ngài...\""
  },
  AvgDialog_47176_Content_14 = {
    Text = "Cô nhìn những tảng đá vụn trên đầu đang lung lay, cố gắng co thân thể vào góc, hai tay mười ngón đan chéo, hợp trước ngực cầu nguyện."
  },
  AvgDialog_47176_Content_15 = {
    Text = "Bão lớn.sấm sét.động đất.sóng thần."
  },
  AvgDialog_47176_Content_16 = {
    Text = "Người dân Lemuria ngủ cùng với thảm họa từ trời, cầu nguyện là điều đầu tiên họ học được."
  },
  AvgDialog_47176_Content_17 = {
    Text = "\"Quý vị là đại diện của thần minh, là niềm tin của người dân Lemuria... Tôi nguyện dâng hiến tất cả mọi thứ cho ngài...\""
  },
  AvgDialog_47176_Content_18 = {
    Text = "\"Xin hãy giúp tôi... Cứu tôi...\""
  },
  AvgDialog_47176_Content_19 = {
    Text = "Cha nói rằng thần minh và vua sẽ cứu dân Lemuria. Cô ấy không biết gì về thần minh hay vua. Cô ấy không ngừng thì thầm trong lòng."
  },
  AvgDialog_47176_Content_2 = {
    Text = "\"Trong ảo mộng của ngai vàng, nhà vua lắng nghe lời chỉ dẫn của thần minh:\""
  },
  AvgDialog_47176_Content_20 = {
    Text = "Thần minh vẫn chưa xuất hiện, và chưa bao giờ xuất hiện trước mặt cô. Nhưng ngoài việc cầu nguyện, cô không thể làm gì khác."
  },
  AvgDialog_47176_Content_21 = {
    Text = "Các vết nứt trên cột đá ngày càng rõ rệt. Nó đã không thể chống đỡ được trọng lượng đá phía trên nữa."
  },
  AvgDialog_47176_Content_22 = {
    Text = "\"chủ nhân... xin cứu tôi với...\""
  },
  AvgDialog_47176_Content_23 = {
    Text = "Miriam nhớ đến thân thể rách nát và bẩn thỉu của mẹ khi được đào ra từ dưới đống đổ nát."
  },
  AvgDialog_47176_Content_24 = {
    Text = "Trong khoảnh khắc cuối cùng của cô ấy, liệu cô ấy có cũng cảm thấy lạnh lẽo, sợ hãi và tuyệt vọng giống như mình bây giờ không?"
  },
  AvgDialog_47176_Content_25 = {
    Text = "Nước mắt vô lực hòa lẫn trong mưa. Giọng nói càng lúc càng yếu, run rẩy cùng với thân thể…"
  },
  AvgDialog_47176_Content_26 = {
    Text = "Rầm——"
  },
  AvgDialog_47176_Content_27 = {Text = "\"á!!!...\""},
  AvgDialog_47176_Content_28 = {
    Text = "\"Mi-li-am!\""
  },
  AvgDialog_47176_Content_29 = {
    Text = "Trụ đá bị nứt. Trước khi những tảng đá lớn sắp rơi xuống, một hình dáng quen thuộc vọt tới, kéo Miriam vào lòng mình."
  },
  AvgDialog_47176_Content_3 = {
    Text = "\"Cơn bão Lemuria sẽ lắng xuống. Hố sâu Lemuria sẽ biến mất.\""
  },
  AvgDialog_47176_Content_30 = {
    Text = "\"bố... bố!...\""
  },
  AvgDialog_47176_Content_31 = {
    Text = "Miriam từ từ di chuyển cánh tay che trước mặt vô thức."
  },
  AvgDialog_47176_Content_32 = {Text = "\"Oa oa...\""},
  AvgDialog_47176_Content_33 = {
    Text = "Cô ấy ôm chầm lấy bóng dáng thân quen này."
  },
  AvgDialog_47176_Content_34 = {
    Text = "\"đừng sợ, Miriam. đừng sợ. tôi ở đây.\""
  },
  AvgDialog_47176_Content_35 = {
    Text = "\"xì... cẩn thận nào, đứa trẻ... đừng chạm vào vai...\""
  },
  AvgDialog_47176_Content_36 = {
    Text = "\"Bạn bị chảy máu?!\""
  },
  AvgDialog_47176_Content_37 = {
    Text = "Đá rơi xuống, mảnh vỡ bắn tung tóe, người đàn ông đứng chắn giữa đá và cô gái, làn da sạm đen vì nắng gió lâu ngày đầy vết thương do mảnh đá và ngói vỡ để lại."
  },
  AvgDialog_47176_Content_38 = {
    Text = "Đào điên rồ để loại bỏ đá và đất, ngay cả đôi tay thô ráp cũng bị thịt máu nhão nhoẹt."
  },
  AvgDialog_47176_Content_39 = {
    Text = "Mưa rửa trôi thân thể người đàn ông, mang theo máu tươi và nhuộm đỏ đống đổ nát trên mặt đất."
  },
  AvgDialog_47176_Content_4 = {
    Text = "\"Vua sẽ bảo vệ dân chúng hiền lành của mình, mang lại vương quốc của chúa. \nNước nhẹ nhàng, tưới mát mỗi tấc cỏ cây...\""
  },
  AvgDialog_47176_Content_40 = {
    Text = "\"cha... tôi... là tôi đã làm ông bị thương...\""
  },
  AvgDialog_47176_Content_41 = {
    Text = "Một bàn tay thô ráp, ấm áp và rộng rãi đặt lên đầu cô, vuốt ve nhẹ nhàng."
  },
  AvgDialog_47176_Content_42 = {
    Text = "\"Đứa trẻ ngốc, đang nói gì vậy. Miễn là con không sao, dù có bị thương nhiều đến đâu cũng không thành vấn đề.\""
  },
  AvgDialog_47176_Content_43 = {
    Text = "\"còn may, còn may... cuối cùng cũng kịp...\""
  },
  AvgDialog_47176_Content_44 = {
    Text = "\"Cảm ơn chủ nhân! Đã bảo vệ gia đình tôi...\""
  },
  AvgDialog_47176_Content_45 = {
    Text = "\"Bảo vệ tôi, rõ ràng là cha...\""
  },
  AvgDialog_47176_Content_46 = {
    Text = "\"Người dân Lemuria có thể sống sót đều nhờ sự giúp đỡ của Vua. Chỉ có sự sùng kính đối với Vua mới có thể giữ gìn gia đình mình. Hiện tại con còn nhỏ, khi lớn lên con sẽ hiểu.\""
  },
  AvgDialog_47176_Content_47 = {
    Text = "Inos cười, vỗ nhẹ vào đầu của cô gái. Ông dẫn Miriam cùng hướng về phía đền thần, thành kính hành lễ."
  },
  AvgDialog_47176_Content_48 = {
    Text = "\"Đến, hãy cùng đọc theo tôi. \nBất kỳ ai lạc lối, Chúa sẽ dẫn đường...\""
  },
  AvgDialog_47176_Content_5 = {
    Text = "Rầm——"
  },
  AvgDialog_47176_Content_50 = {
    Text = "……Những gì mong ước, Chúa sẽ ban cho……"
  },
  AvgDialog_47176_Content_51 = {Text = "\"Miriam?\""},
  AvgDialog_47176_Content_52 = {
    Text = "……Hễ thành tâm, Ngài sẽ ban phước lành……"
  },
  AvgDialog_47176_Content_53 = {
    Text = "\"Miriam? Đã ngủ chưa?\""
  },
  AvgDialog_47176_Content_54 = {
    Text = "\"À, cha! Xin lỗi... Tôi vừa mới nghĩ về một số chuyện trước đây...\""
  },
  AvgDialog_47176_Content_55 = {
    Text = "\"Miriam, bạn có chắc chắn muốn trở thành thực tập sinh linh mục không?\""
  },
  AvgDialog_47176_Content_56 = {
    Text = "\"Vâng, cha.\""
  },
  AvgDialog_47176_Content_57 = {
    Text = "\"Vậy thì tốt, vậy thì tốt. Tôi thấy cậu có vẻ tâm trí không tập trung, bình thường cũng ít thích nói về những chuyện này, còn tưởng rằng cậu không thích nữa...\""
  },
  AvgDialog_47176_Content_58 = {
    Text = "\"Con tự nguyện nói muốn tham gia cuộc tuyển chọn để trở thành thực tập sinh linh mục, bố thực sự rất vui. Con gái của bố đã lớn rồi...\""
  },
  AvgDialog_47176_Content_59 = {
    Text = "\"Vì đã đến đây, chúng ta hãy lắng nghe lời của vị linh mục. Vua là người gần gũi nhất với thần minh, Người có thể nhìn thấy mọi thứ. Những kẻ không thành tâm sẽ không thể nhận được sự ưu ái của vua.\""
  },
  AvgDialog_47176_Content_6 = {Text = "\"À!...\""},
  AvgDialog_47176_Content_60 = {
    Text = "\"Ừ... con biết rồi, cha.\""
  },
  AvgDialog_47176_Content_61 = {
    Text = "Người luôn chăm sóc bản thân không bao giờ là vua. Miriam nghĩ vậy nhưng không nói ra."
  },
  AvgDialog_47176_Content_62 = {
    Text = "\"Ba ơi, chị có được chọn không?\""
  },
  AvgDialog_47176_Content_63 = {
    Text = "\"Tất nhiên là được! Các linh mục trong thành đều nói rằng, sức mạnh tinh thần của chị gái ngươi còn mạnh hơn cả bản thân linh mục.\""
  },
  AvgDialog_47176_Content_64 = {
    Text = "\"Cô ấy không chỉ có thể trở thành linh mục, mà còn có thể trở thành chủ tế trong tương lai nữa!\""
  },
  AvgDialog_47176_Content_65 = {
    Text = "\"Đó là vinh dự vô thượng... Nếu thực sự như vậy, mẹ các con ở thế giới bên kia cũng sẽ cảm thấy vui mừng vì các con!\""
  },
  AvgDialog_47176_Content_66 = {
    Text = "\"Ah! Linh mục đang đến!\""
  },
  AvgDialog_47176_Content_67 = {
    Text = "Sara reo lên đầy phấn khích, mọi người nhìn về phía trước."
  },
  AvgDialog_47176_Content_68 = {
    Text = "Linh mục đội khăn voan tím vừa đi vừa đọc lời cầu nguyện. Bà ấy đi qua từng đứa trẻ, và cuối cùng đến trước mặt gia đình Miriam."
  },
  AvgDialog_47176_Content_69 = {
    Text = "\"Chúa của con, xin hãy lắng nghe lòng thành kính của con, xin hãy chấp nhận con gái của con, Miriam...\""
  },
  AvgDialog_47176_Content_7 = {
    Text = "Tiếng sấm nổ vang trên bầu trời hòn đảo. Thân thể nhỏ bé run rẩy dưới đống đổ nát."
  },
  AvgDialog_47176_Content_70 = {
    Text = "Lời khấn nguyện thấp giọng của người cha và uy nghi của linh mục khiến Miriam không nói thêm gì nữa."
  },
  AvgDialog_47176_Content_71 = {
    Text = "Cô cúi đầu chờ đợi. Vị linh mục đưa tay lên, đặt lên trán cô."
  },
  AvgDialog_47176_Content_72 = {
    Text = "\"Thưa ngài linh mục, xin hỏi về đứa con của tôi...\""
  },
  AvgDialog_47176_Content_73 = {
    Text = "Cha nhìn vị linh mục một cách khiêm nhường. Vị linh mục không trả lời, cũng không có bất kỳ biểu cảm nào. Bà đã chứng kiến quá nhiều câu chuyện như vậy, đối với tiếng kêu thấp của động vật, bà đã không còn chút hứng thú nào."
  },
  AvgDialog_47176_Content_74 = {
    Text = "Đôi tay được chăm sóc kỹ lưỡng không hề dừng lại một khắc nào. Linh mục và thị tùng quay người rời đi, trở về lễ đàn."
  },
  AvgDialog_47176_Content_75 = {
    Text = "\"bị loại rồi...\""
  },
  AvgDialog_47176_Content_76 = {
    Text = "\"Bố ơi, con xin lỗi, con vẫn chưa giúp được gì cho gia đình...\""
  },
  AvgDialog_47176_Content_77 = {
    Text = "\"Nói gì thế, con ngốc. Các vì sao đã định sẵn số phận của mỗi người, bố mình cũng không làm được linh mục đâu?\""
  },
  AvgDialog_47176_Content_78 = {
    Text = "\"Chỉ cần các con có thể sống một cuộc sống khỏe mạnh và vui vẻ, bố đã mãn nguyện rồi. Ngay cả khi không làm được linh mục, con vẫn là đứa con tốt của bố.\""
  },
  AvgDialog_47176_Content_79 = {
    Text = "\"Bố, thế còn con thì sao?\""
  },
  AvgDialog_47176_Content_8 = {
    Text = "Biển cả gầm rống giận dữ không xa cô, gần như nuốt chửng cả tiếng sấm. Hòn đảo Lemuria vĩ đại giống như một chiếc lá khô lạc lõng, run rẩy giữa đại dương mênh mông."
  },
  AvgDialog_47176_Content_80 = {
    Text = "\"Hahaha, các bạn đều là những đứa trẻ tốt!\""
  },
  AvgDialog_47176_Content_81 = {
    Text = "Miriam có thể nhìn ra rằng, biểu cảm của cha có chút thất vọng. Nhưng bàn tay chai sạn, rộng lớn ấy vẫn dịu dàng đặt trên đầu cô."
  },
  AvgDialog_47176_Content_82 = {
    Text = "Từ nhỏ đến lớn, khi cô ấy sợ hãi, khi cô ấy thất vọng, khi cô ấy buồn bã, bàn tay này luôn xuất hiện, vuốt ve đầu tôi như vậy, giúp tôi bình tĩnh lại."
  },
  AvgDialog_47176_Content_83 = {
    Text = "Từ nhỏ đến lớn, người sở hữu bàn tay ấy đã phải chịu đựng những gì? Bản thân mình đã làm gì để giúp đỡ họ?"
  },
  AvgDialog_47176_Content_84 = {
    Text = "Miriam cúi đầu xuống, giấu đi quầng mắt đỏ."
  },
  AvgDialog_47176_Content_85 = {
    Text = "\"Ơ, chị ơi, có một ông cụ đi lên sân khấu kìa!\""
  },
  AvgDialog_47176_Content_86 = {
    Text = "\"cái áo đó!... bộ đồ màu tím!...\""
  },
  AvgDialog_47176_Content_87 = {
    Text = "Một tín đồ hào hứng chen đến bên cạnh Inos, nhón chân để nhìn ngó."
  },
  AvgDialog_47176_Content_88 = {
    Text = "\"Là người chủ tế? Người chủ tế lại ra khỏi đền thần?! Cũng không có ai thông báo chuyện này cả...\""
  },
  AvgDialog_47176_Content_89 = {
    Text = "Một người già từ phòng phía sau bước ra. Khuôn mặt ông ta già nua, nhưng vẫn bước đi vững vàng, trang phục trên người được chăm sóc kỹ lưỡng, không có một nếp nhăn nào."
  },
  AvgDialog_47176_Content_9 = {
    Text = "Cơn động đất mạnh mẽ trên đảo đã lắng xuống, nhưng cô vẫn cảm thấy chóng mặt."
  },
  AvgDialog_47176_Content_90 = {
    Text = "Chủ tế, người duy nhất có thể diện kiến vua. Trong toàn bộ Lemuria, ngoài vua - người có thể giao tiếp với thần minh, địa vị của ông ta cao quý nhất."
  },
  AvgDialog_47176_Content_91 = {
    Text = "Bậc trưởng lão liếc mắt nghiêm nghị quét qua toàn trường. Ông không nói gì cả, nhưng dưới ánh mắt đó, đền thần vốn ồn ào lập tức trở nên yên tĩnh."
  },
  AvgDialog_47176_Content_92 = {
    Text = "Rất nhanh, ánh mắt đó hướng về phía Miriam. Theo sự chỉ dẫn của linh mục, vị lão nhân bước đến trước mặt Miriam, bàn tay chi chít những nếp nhăn nhẹ nhàng đặt lên trán cô."
  },
  AvgDialog_47176_Content_93 = {
    Text = "Những linh mục kiêu ngạo lúc này cúi mình, dừng lại trước mặt vị lão nhân. Mọi thứ trong đền thần dường như đều đứng lại vì sự xuất hiện của ông. Cô không thể thở được và cũng không còn cảm nhận được thời gian trôi qua."
  },
  AvgDialog_47176_Content_94 = {
    Text = "\"Bạn có sẵn lòng giết cha mình vì vua không?\""
  },
  AvgDialog_47176_Content_95 = {
    Text = "Giọng nói lạnh giá từ chủ tế vang lên, như sấm sét làm vỡ tan thời gian ngưng đọng."
  },
  AvgDialog_47176_Content_96 = {
    Text = "Miriam đột nhiên ngẩng đầu lên, thấy khuôn mặt già nua và uy nghiêm của chủ tế."
  },
  AvgDialog_47176_Content_97 = {
    Text = "\"Quý... Quý nói gì?\""
  },
  AvgDialog_47176_Content_98 = {
    Text = "\"Hãy nói cho tôi biết, đức tin là gì.\""
  },
  AvgDialog_47176_Content_99 = {
    Text = "\"Tín ngưỡng là... là hiến dâng tất cả vì đức vua...\""
  },
  AvgDialog_47177_Content_1 = {Text = "Thịt cá"},
  AvgDialog_47177_Content_10 = {
    Text = "Chị gái ơi, cá ngon như vậy, tại sao chị không thích ăn nhỉ?"
  },
  AvgDialog_47177_Content_11 = {
    Text = "Có thể là do khi còn nhỏ ăn quá nhiều, có thể là do mùi tanh của cá quá nồng, hoặc cũng có thể là…"
  },
  AvgDialog_47177_Content_12 = {
    Text = "Sara, tớ chưa kể cho cậu nghe về chuyện mẹ tớ mất, phải không?"
  },
  AvgDialog_47177_Content_13 = {
    Text = "Sara lắc đầu, im lặng dựa vào lòng Miriam lắng nghe."
  },
  AvgDialog_47177_Content_14 = {
    Text = "Lúc đó, em vừa mới sinh không lâu, mẹ nằm bệnh trên giường. Khi những tảng đá trên núi lăn xuống, mẹ không kịp chạy thoát."
  },
  AvgDialog_47177_Content_15 = {
    Text = "Ngày đó gió thổi rất lớn, những con cá rơi từ trên trời xuống, rơi lên người của người mẹ."
  },
  AvgDialog_47177_Content_16 = {
    Text = "Mắt cô ấy mở tròn như những con cá vậy…"
  },
  AvgDialog_47177_Content_17 = {
    Text = "Miriam không nói thêm gì nữa, Sara cũng không hỏi thêm. Em gái dựa sát vào ngực chị gái, vỗ nhẹ vào lưng chị gái."
  },
  AvgDialog_47177_Content_18 = {
    Text = "Nếu con không thích nữa, tại sao không nói với bố?"
  },
  AvgDialog_47177_Content_19 = {
    Text = "Nếu tôi không thích điều gì, tôi sẽ nói thẳng với mọi người."
  },
  AvgDialog_47177_Content_2 = {
    Text = "Xèo xèo——"
  },
  AvgDialog_47177_Content_20 = {
    Text = "Mẹ mất sau đó, bố một mình nuôi sống cả gia đình chúng tôi. Cuộc sống của ông vô cùng khó khăn."
  },
  AvgDialog_47177_Content_21 = {
    Text = "Ở Lemuria, cá là món ăn rẻ nhất."
  },
  AvgDialog_47177_Content_22 = {
    Text = "Tôi không có nhiều tài năng, không thể giúp gì cho gia đình. Điều duy nhất tôi có thể làm, là ít gây rắc rối cho gia đình hơn…"
  },
  AvgDialog_47177_Content_23 = {
    Text = "Sara, con cũng phải nhớ rằng, khi con lớn lên, con cũng phải giúp đỡ bố, được không?"
  },
  AvgDialog_47177_Content_24 = {
    Text = "Ừ! À, vậy chị, chị nói chị thích làm linh mục, cũng giống như chị nói chị thích ăn cá phải không?"
  },
  AvgDialog_47177_Content_25 = {
    Text = "Đến nào! Hai cô công chúa nhỏ, món cuối cùng đã sẵn sàng!"
  },
  AvgDialog_47177_Content_26 = {
    Text = "Giọng của người cha vọng từ nhà bếp, cắt ngang câu hỏi của Sarah. Miriam mỉm cười và chuyển hướng cuộc trò chuyện."
  },
  AvgDialog_47177_Content_27 = {
    Text = "Sara, những chuyện của tôi, đừng kể cho người khác nghe nhé?"
  },
  AvgDialog_47177_Content_28 = {
    Text = "Biết! Sara cũng không gây rắc rối cho chị và bố ~"
  },
  AvgDialog_47177_Content_29 = {
    Text = "Miriam mỉm cười vỗ nhẹ vào đầu em gái, dẫn cô ấy đến nhà bếp để đón bữa tiệc mà cha đã chuẩn bị cho mình."
  },
  AvgDialog_47177_Content_3 = {
    Text = "Thịt cá tươi được cho vào nồi, âm thanh và mùi thơm tỏa ra từ căn bếp nhỏ."
  },
  AvgDialog_47177_Content_30 = {
    Text = "Rất nhanh, các món ăn từ cá đã phủ kín chiếc bàn nhỏ trong nhà."
  },
  AvgDialog_47177_Content_31 = {
    Text = "Các bạn đi mua rau củ, tôi đã nói với mọi người trong thị trấn, và tôi cũng đã viết thư cho những người họ hàng ở xa. Họ sẽ biết tin vài ngày sau."
  },
  AvgDialog_47177_Content_32 = {
    Text = "Những người thân xung quanh, những người đã chứng kiến bạn lớn lên từ nhỏ, đều rất vui mừng và mang đến nhiều đồ ăn thức uống."
  },
  AvgDialog_47177_Content_33 = {
    Text = "À, đúng rồi, còn có vị linh mục trong thành, nghe nói anh được chủ tế chọn ra, chủ động tìm đến nói chuyện với tôi, thái độ thật tốt!"
  },
  AvgDialog_47177_Content_34 = {
    Text = "Chỉ là việc nhỏ nhặt…… Không cần phải nói cho nhiều người như vậy đâu……"
  },
  AvgDialog_47177_Content_35 = {
    Text = "Đâu phải chuyện nhỏ! Nếu chị làm linh mục, chị sẽ kiếm được rất nhiều tiền, còn có thể tìm người đến quét dọn cho em…"
  },
  AvgDialog_47177_Content_36 = {
    Text = "Đừng nói bậy, Sarla. Linh mục là một nghề thiêng liêng, không phải để làm những chuyện như vậy."
  },
  AvgDialog_47177_Content_37 = {
    Text = "Linh mục là người làm gì?"
  },
  AvgDialog_47177_Content_38 = {
    Text = "Sứ mệnh của linh mục… Điều này phải kể từ rất lâu trước đây. Đây là câu chuyện mà mỗi người dân Lemuria đều nên biết."
  },
  AvgDialog_47177_Content_39 = {
    Text = "Inos bế Sarah, đặt cô ấy lên đùi mình và nhẹ nhàng vuốt ve đầu cô."
  },
  AvgDialog_47177_Content_4 = {
    Text = "Đây là những món ăn mà các cô con gái yêu thích nhất. Inos đã làm những món ăn này hơn mười năm nay, thậm chí có thể nhắm mắt lại vẫn điều chỉnh chính xác lượng của mỗi loại gia vị."
  },
  AvgDialog_47177_Content_40 = {
    Text = "Lemuria, với lịch sử huy hoàng và nền văn minh tươi sáng. Thần minh che chở quốc gia này, mang lại niềm hạnh phúc và sự an lành vô tận."
  },
  AvgDialog_47177_Content_41 = {
    Text = "Đây không có thiên tai, không có bệnh tật, ai cũng có vô tận thức ăn và rượu ngon. Nhờ sự giúp đỡ của thần minh, những người đã khuất có thể đoàn tụ với người còn sống."
  },
  AvgDialog_47177_Content_42 = {
    Text = "Không biết từ khi nào, người dân nơi đây không còn nghe được tiếng của thần minh. Thiên tai ngày càng xảy ra thường xuyên…"
  },
  AvgDialog_47177_Content_43 = {
    Text = "Quốc gia của chúng ta bị bao quanh bởi biển cả vô tận, chưa ai có thể rời khỏi nơi này. Chỉ có thần minh mới có thể thay đổi tất cả."
  },
  AvgDialog_47177_Content_44 = {
    Text = "Và đức vua của chúng ta là người duy nhất có thể giao tiếp với thần linh. Ngài sẽ lắng nghe lời sấm truyền và mang lại ân điển của thần lần nữa cho chúng ta."
  },
  AvgDialog_47177_Content_45 = {
    Text = "Đến lúc đó, mọi tai họa sẽ biến mất, người thân đã chết sẽ được tái sinh, chúng ta sẽ mãi mãi an cư trên mảnh đất này… Lemuria sẽ trở thành thần quốc hoàn hảo một lần nữa!"
  },
  AvgDialog_47177_Content_46 = {
    Text = "Yết hầu của anh ta chuyển động, ánh mắt tràn đầy hy vọng từ từ thu lại từ hướng đền thần."
  },
  AvgDialog_47177_Content_47 = {
    Text = "Tuy nhiên, lực lượng của vua có hạn, cần sự giúp đỡ của người dân. Chỉ những người có sức mạnh tinh thần đủ mạnh mẽ mới có khả năng trở thành linh mục, để truyền đạt ý chỉ của đức vua, để giúp đỡ đức vua."
  },
  AvgDialog_47177_Content_48 = {
    Text = "Người bình thường như tôi, không có tài năng này, không thể làm gì, chỉ có thể đứng nhìn mẹ của các bạn…"
  },
  AvgDialog_47177_Content_49 = {
    Text = "Thôi được rồi, hôm nay là ngày tốt lành, chúng ta đừng nói về những chuyện này."
  },
  AvgDialog_47177_Content_5 = {Text = "Ừ——"},
  AvgDialog_47177_Content_50 = {
    Text = "Anh ấy lau khóe mắt, mỉm cười vỗ nhẹ lên đầu hai cô con gái."
  },
  AvgDialog_47177_Content_51 = {
    Text = "Trở thành linh mục, giúp vua, cứu Lemuria, đây là vinh dự lớn nhất."
  },
  AvgDialog_47177_Content_52 = {
    Text = "Cảm ơn đức vua đã ban cho gia đình nhỏ bé của chúng tôi cơ hội này…"
  },
  AvgDialog_47177_Content_53 = {
    Text = "Inos giơ chiếc cốc lên. Dung dịch đục ngà trong cốc rung lắc, toả ra mùi rượu kém chất lượng gay gắt."
  },
  AvgDialog_47177_Content_54 = {
    Text = "Người nghèo ở Lemuria thích loại rượu này, rẻ tiền, mạnh mẽ, mang lại cho họ sự an ủi tạm thời với một cái giá thấp."
  },
  AvgDialog_47177_Content_55 = {
    Text = "Các tạp chất trong rượu sẽ khiến họ đau đầu vô cùng khi thức dậy vào ngày hôm sau. Đối với họ, cơn đau đầu sau khi say và cảm giác đau đớn là một món quà quý giá."
  },
  AvgDialog_47177_Content_56 = {
    Text = "Anh ta uống cạn."
  },
  AvgDialog_47177_Content_57 = {
    Text = "Sara, cha của bạn tuy không mấy hữu dụng, nhưng chị gái của bạn là niềm tự hào của cả gia đình chúng ta!"
  },
  AvgDialog_47177_Content_58 = {
    Text = "Đến, Miriam, đây là miếng cá rán mà bạn thích ăn nhất. Ông Oona vừa mới bắt được hôm nay! Tôi đã dặn ông ấy giữ lại cho tôi."
  },
  AvgDialog_47177_Content_59 = {
    Text = "Bố không muốn gây áp lực cho con, cứ làm đi, bố tin rằng con sẽ làm tốt mọi việc!"
  },
  AvgDialog_47177_Content_6 = {
    Text = "Chị gái, dạ dày của chị lại khó chịu rồi… mỗi lần ngửi thấy mùi cá là lại muốn nôn, thôi."
  },
  AvgDialog_47177_Content_60 = {
    Text = "Bố chỉ mong rằng, con sẽ biết tự chăm sóc bản thân. Nếu có điều gì không vui, hãy viết thư kể cho bố."
  },
  AvgDialog_47177_Content_61 = {
    Text = "Ngày mai rời khỏi nhà, lần sau được ăn cá do bố nấu lại chẳng biết sẽ là khi nào nữa…"
  },
  AvgDialog_47177_Content_62 = {
    Text = "Dĩa cá đầy ắp được đặt trước mặt Miriam. Màu vàng kim, hương thơm đậm đà."
  },
  AvgDialog_47177_Content_63 = {
    Text = "Em gái đang mỉm cười. Cha đang mỉm cười, mắt ngấn lệ. Mẹ dường như cũng ngồi bên cạnh, mỉm cười với mình."
  },
  AvgDialog_47177_Content_64 = {
    Text = "Cô ta mặc quần áo rách rưới, cơ thể khiếm khuyết, đôi mắt mở to và tròn, giống hệt con cá trong đĩa."
  },
  AvgDialog_47177_Content_65 = {
    Text = "Tôi sẽ trở thành một linh mục…… Tôi nhất định sẽ không làm cha thất vọng."
  },
  AvgDialog_47177_Content_66 = {
    Text = "Miriam đặt con cá vào miệng. Cô nhai, nuốt rồi mỉm cười với gia đình."
  },
  AvgDialog_47177_Content_7 = {
    Text = "Em gái vừa vỗ lưng Miriam, vừa lắc đầu than vãn."
  },
  AvgDialog_47177_Content_8 = {
    Text = "Biểu cảm như một bà cụ hiện lên trên khuôn mặt đứa trẻ mười tuổi, khiến Miriam không khỏi bật cười."
  },
  AvgDialog_47177_Content_9 = {
    Text = "Tôi không sao đâu, Sarah."
  },
  AvgDialog_47178_Content_1 = {
    Text = "Cầu nguyện giữa biển sâu"
  },
  AvgDialog_47178_Content_10 = {Text = "Xèo——"},
  AvgDialog_47178_Content_100 = {
    Text = "Đôi mắt lúc ẩn lúc hiện, dường như đã vượt qua những người theo dõi trong căn phòng này. Chúng xuyên qua những cánh cửa bảng đá lớn, hướng về muôn loài ở Lemuria."
  },
  AvgDialog_47178_Content_101 = {
    Text = "Đôi mắt ấy khắc họa không biết là niềm tin, là niềm cảm thương, hay là sự mỏi mệt."
  },
  AvgDialog_47178_Content_11 = {
    Text = "<Shake:ừ ừ ừ!!!……>"
  },
  AvgDialog_47178_Content_12 = {
    Text = "Một sinh vật ướt nhẹp lao vút lên từ mặt nước, mái tóc thưa thớt của con người rơi nhẹ từ đầu xuống, phủ trên gương mặt mang dáng dấp của loài cá."
  },
  AvgDialog_47178_Content_13 = {
    Text = "Mang cá của nó mở ra nhẹ nhàng, đôi môi trơn nhẵn khẽ cử động, thanh quản biến dị rung động nhẹ, phát ra những âm tiết hỗn loạn không có ý nghĩa."
  },
  AvgDialog_47178_Content_14 = {
    Text = "Tay và chân của con người đầy vảy lộn xộn, phản chiếu ánh kim ô uế, vỗ nước một cách hỗn loạn."
  },
  AvgDialog_47178_Content_15 = {
    Text = "Phập phập phập phập……"
  },
  AvgDialog_47178_Content_16 = {
    Text = "Trong hai bể nước khổng lồ, vô số sinh vật mặt cá với khuôn mặt giống hệt nhau thò đầu ra từ mặt nước, điên rồ vỗ nước, phát ra những tiếng kêu kỳ lạ."
  },
  AvgDialog_47178_Content_17 = {
    Text = "Chúng chen chúc nhau trong nước, vô số đôi mắt cá tròn xoe nhìn Miriam mà không có chút cảm xúc nào."
  },
  AvgDialog_47178_Content_18 = {Text = "Ừ——"},
  AvgDialog_47178_Content_19 = {
    Text = "Miriam dùng hết sức lực, kiềm chế không nôn ra."
  },
  AvgDialog_47178_Content_2 = {
    Text = "Âm thanh trầm bổng, giống như lời gọi từ thời cổ đại."
  },
  AvgDialog_47178_Content_20 = {
    Text = "Đây chính là.."
  },
  AvgDialog_47178_Content_21 = {
    Text = "Đúng vậy, đó chính là những vị tiền bối vĩ đại! Tôi cũng là lần đầu tiên thấy, hóa ra chúng trông như vậy!"
  },
  AvgDialog_47178_Content_22 = {
    Text = "Thực tập sinh linh mục tên là Déborah đứng bên cạnh Miriam, vui vẻ vỗ vào cô ấy mà không chút e dè đây là lần đầu tiên họ gặp nhau."
  },
  AvgDialog_47178_Content_23 = {
    Text = "Truyền thuyết kể rằng, vua nhận được lời tiên tri. Trước khi Lemuria biến thành thần quốc, ông phải dùng máu thần để cải tạo dân chúng, giúp họ có khả năng đối phó với thiên tai."
  },
  AvgDialog_47178_Content_24 = {
    Text = "Những người tiên phong này, vì tương lai của người Lemuria, đã dũng cảm bước đi trước."
  },
  AvgDialog_47178_Content_25 = {
    Text = "Sau khi chúng ta trở thành linh mục, nghi lễ hóa người cá sẽ do chúng ta thực hiện. Đến lúc đó, tôi chắc chắn sẽ phấn khích đến nỗi không thể ngủ được!"
  },
  AvgDialog_47178_Content_26 = {
    Text = "Deborah vui vẻ cúi chào những người cá này, dịu dàng vuốt ve khuôn mặt mịn màng của chúng."
  },
  AvgDialog_47178_Content_27 = {
    Text = "Những học viên khác bên cạnh cũng cúi người, tỏ lòng kính trọng đối với những vị tiên hiền. Miriam đứng im tại chỗ, quan sát cảnh tượng này."
  },
  AvgDialog_47178_Content_28 = {
    Text = "\"Những người tiên phong vĩ đại\"… không biết gia đình họ nhìn thấy cảnh này có nghĩ như vậy không…"
  },
  AvgDialog_47178_Content_29 = {
    Text = "Phòng cầu nguyện ở phía trước. Các vị, hãy theo tôi."
  },
  AvgDialog_47178_Content_3 = {
    Text = "Cánh cửa bảng đá lớn khắc phù điêu bị dẫn dắt bởi một sức mạnh không rõ nguồn gốc, trượt sang hai bên. Ánh sáng từ bên ngoài không thể thâm nhập vào trong dù chỉ một chút."
  },
  AvgDialog_47178_Content_31 = {
    Text = "Cánh cửa đá phẳng đóng lại im lặng, ngăn cách tiếng rít của người cá và sự ồn ào bên ngoài."
  },
  AvgDialog_47178_Content_32 = {
    Text = "Các học trò quỳ trên các ghế cầu nguyện, nhìn về phía bàn thờ và bức tượng khổng lồ phía sau, bao gồm cơ thể người, ngai vàng và xúc tu."
  },
  AvgDialog_47178_Content_33 = {
    Text = "Khuôn mặt người trên bức tượng có phần mờ nhạt, thân thể con người nằm giữa ngai lớn và những xúc tu, tạo nên sự tương phản mạnh mẽ."
  },
  AvgDialog_47178_Content_34 = {
    Text = "Đây là tượng của vua."
  },
  AvgDialog_47178_Content_35 = {
    Text = "Lão nhân từ phía bên phải phòng có tượng đi ra, vẫy vẫy tay, ngăn cản những học trò muốn đứng dậy chào."
  },
  AvgDialog_47178_Content_36 = {
    Text = "Lời cầu nguyện đang ở trước mặt các bạn. Đọc nó, tụng niệm nó. Điều quan trọng nhất là, tin tưởng vào nó."
  },
  AvgDialog_47178_Content_37 = {
    Text = "Thưa ngài Chủ tế,làm được những điều này,chúng ta có thể giúp đỡ nhà vua rồi phải không?"
  },
  AvgDialog_47178_Content_38 = {
    Text = "Vị chủ tế liếc nhìn cô ấy."
  },
  AvgDialog_47178_Content_39 = {
    Text = "Vua sẽ nói cho các ngươi. Hãy cầu nguyện."
  },
  AvgDialog_47178_Content_4 = {
    Text = "Bóng tối dày đặc và nguyên chất từ bên trong cánh cửa phát ra lời mời gọi tới tất cả mọi người."
  },
  AvgDialog_47178_Content_40 = {
    Text = "Lão nhân đã rời khỏi phòng, bên trong chỉ còn lại một vị linh mục và vài vệ sĩ."
  },
  AvgDialog_47178_Content_41 = {
    Text = "Ánh sáng trong phòng cầu nguyện trở nên mờ tối, bức tượng phía trước lấp lánh ánh hào quang huyền bí mờ ảo."
  },
  AvgDialog_47178_Content_42 = {
    Text = "Miriam lấy bản văn cầu nguyện trước mặt."
  },
  AvgDialog_47178_Content_43 = {Text = "A……"},
  AvgDialog_47178_Content_44 = {
    Text = "Những gì được viết trên giấy không phải là ngôn ngữ thông dụng của Lemuria, mà là một loại ký hiệu hình tượng phức tạp, có nhiều chiều không gian hơn so với không gian thực tế."
  },
  AvgDialog_47178_Content_45 = {
    Text = "Dấu hiệu đó đến từ thời cổ đại, hoặc thậm chí từ một thế giới khác, Miriam chưa bao giờ thấy. Nhưng khi đọc dấu hiệu này, ý nghĩa trong đó tự nhiên hiện lên trong tâm trí cô."
  },
  AvgDialog_47178_Content_46 = {
    Text = "Mỗi chữ đều chứa đựng một lượng thông tin khổng lồ, vô số kinh văn tuôn vào não bộ của Miriam, khiến cái đầu người yếu đuối khó lòng gánh chịu."
  },
  AvgDialog_47178_Content_47 = {
    Text = "<Shake:đầu…… đầu đau quá……>"
  },
  AvgDialog_47178_Content_48 = {
    Text = "Xung quanh không ngừng có người ngã xuống. Miriam nghiến răng chịu đựng cơn đau, đọc lời cầu nguyện trên giấy."
  },
  AvgDialog_47178_Content_49 = {
    Text = "\"Trong hố sâu u tối xa xôi, những linh hồn vĩ đại cổ xưa đang chìm vào giấc ngủ……\""
  },
  AvgDialog_47178_Content_5 = {
    Text = "Phần bên ngoài đền thần dành cho tín đồ bình thường hành hương, còn chỉ những người dân đủ tư cách trở thành linh mục mới có thể đến đây."
  },
  AvgDialog_47178_Content_50 = {
    Text = "Miriam đã nói những lời này bằng tiếng Lemuria phổ thông, nhưng khi chúng thoát ra khỏi miệng cô, chúng đã trở thành một ngôn ngữ khác."
  },
  AvgDialog_47178_Content_51 = {
    Text = "Ở cùng một thời điểm, giọng nói của cô ấy chồng chéo và vang lên phức tạp. Giống như văn bản, giọng nói của cô ấy cũng trở thành một cấu trúc chiều, giống như từ một không gian thời gian mà con người không thể tưởng tượng được."
  },
  AvgDialog_47178_Content_52 = {
    Text = "\"...Ý chí của Ngài như mạng lưới các vì sao đan xen, Ngài chờ đợi trong hư vô vĩnh cửu để dẫn ngươi vào giấc mơ...\""
  },
  AvgDialog_47178_Content_53 = {
    Text = "Miriam vẫn tiếp tục đọc kinh."
  },
  AvgDialog_47178_Content_54 = {
    Text = "Từ lúc nào không hay, thế giới trước mắt đã biến mất."
  },
  AvgDialog_47178_Content_55 = {
    Text = "Cô ấy đang ở biển sâu, dù nhìn về hướng nào, cũng chỉ thấy nước biển trống rỗng."
  },
  AvgDialog_47178_Content_56 = {
    Text = "Trong biển sâu, những ánh sáng lấp lánh như các vì sao trong vũ trụ rơi."
  },
  AvgDialog_47178_Content_57 = {
    Text = "Miriam cảm thấy mình cũng hóa thành một ngôi sao, ánh sáng trên người cô dần tụ lại về một nơi xa xăm. Đôi mắt cô hướng về phía ấy."
  },
  AvgDialog_47178_Content_58 = {
    Text = "Số lượng ánh sáng tụ lại với nhau, ở nơi đó hình thành một dáng hình mờ ảo. Đó là một dáng hình được cấu thành bởi cơ thể người, ngai vàng và xúc tu."
  },
  AvgDialog_47178_Content_59 = {
    Text = "Đó là… vua sao?"
  },
  AvgDialog_47178_Content_6 = {
    Text = "Các vị, chào mừng đến Cung điện trong. Chào mừng đến cư sở của Đức Vua."
  },
  AvgDialog_47178_Content_60 = {Text = "Pa——"},
  AvgDialog_47178_Content_61 = {
    Text = "Dường như bị một âm thanh nào đó làm giật mình, anh ta thức dậy từ chiếc ghế đá. Khi anh ta tỉnh giấc, cả không gian hư vô dường như tối đi trong chốc lát."
  },
  AvgDialog_47178_Content_62 = {
    Text = "Ở phía sau anh ta, hình dáng mờ ảo của một người cao tuổi hiện ra."
  },
  AvgDialog_47178_Content_63 = {
    Text = "Thưa chủ nhân, ngài đã nghe thấy giọng của nàng rồi."
  },
  AvgDialog_47178_Content_64 = {
    Text = "Vua của Lemuria vẫn còn trên ngai vàng, ta chỉ là người kế vị. Bạn không nên gọi như thế."
  },
  AvgDialog_47178_Content_65 = {
    Text = "Vua của Lemuria, không bao giờ do ai ngồi trên ngai vàng quyết định. Ai gần gũi với thần minh nhất, người đó chính là người được tôn kính nhất."
  },
  AvgDialog_47178_Content_66 = {
    Text = "Ta không thích cái danh hiệu này."
  },
  AvgDialog_47178_Content_67 = {
    Text = "Vị vua già trong suốt cuộc đời đã từng nghe một lời tiên tri. Lời tiên tri ấy đã khiến ông ngồi vững trên ngai vàng, trở thành niềm tin của thần dân."
  },
  AvgDialog_47178_Content_68 = {
    Text = "Những lời thần dụ mà ngài đã lắng nghe, đã vượt xa vô số tiên vương của Lemuria. Thế nhưng ngài… vẫn chỉ là một đứa trẻ thôi."
  },
  AvgDialog_47178_Content_69 = {
    Text = "Quý vị là hy vọng của Lemuria. Vị vua già không còn nhiều thời gian, ông ấy đã trao quyền từ lâu. Sắp tới, quý vị sẽ lên ngai vàng. Quý vị cần làm quen với danh xưng này, Đức Chúa tể của tôi."
  },
  AvgDialog_47178_Content_7 = {
    Text = "Một cơn gió thổi từ nội điện được đóng kín, mang theo mùi tanh nồng của biển sâu."
  },
  AvgDialog_47178_Content_70 = {
    Text = "Cậu bé mệt mỏi dựa vào lưng ghế, không còn tranh cãi với người lớn tuổi nữa."
  },
  AvgDialog_47178_Content_71 = {
    Text = "Lần đầu cầu nguyện, ngươi có thể kết nối với người này và nhìn thấy hình bóng của ta. Những ngôi sao báo hiệu, có phải cô ấy không?"
  },
  AvgDialog_47178_Content_72 = {
    Text = "Là cô ấy, tôi đã kiểm tra rồi. Nếu những gì các vì sao chỉ không sai, cô ấy… sẽ trở thành tương lai của Lemuria."
  },
  AvgDialog_47178_Content_73 = {
    Text = "Bạn không nghĩ như vậy."
  },
  AvgDialog_47178_Content_74 = {
    Text = "Có tài năng, nhưng có tạp niệm. Cô ấy không thể giúp đỡ ngài, thưa ngài."
  },
  AvgDialog_47178_Content_75 = {
    Text = "Cô ấy không tin vào lời cầu nguyện, không tin vào ngài, cũng không tin vào tương lai của Lemuria. Cô ấy chỉ tin vào gia đình của mình."
  },
  AvgDialog_47178_Content_76 = {
    Text = "Miriam là người sống thực tế. Kiểu người như cô ấy không thể gánh vác số phận của Lemuria."
  },
  AvgDialog_47178_Content_77 = {
    Text = "Sống trong thực tế thay vì ảo ảnh, đó chính là hy vọng của Dư."
  },
  AvgDialog_47178_Content_78 = {
    Text = "Số phận của Lemuria…… không ai nên gánh chịu."
  },
  AvgDialog_47178_Content_79 = {
    Text = "Mong ước tốt đẹp, thưa ngài. Sinh ra ở Lemuria, chúng tôi đều có trách nhiệm riêng cần phải gánh vác."
  },
  AvgDialog_47178_Content_8 = {
    Text = "Đi theo bước chân của linh mục vào nội điện, bóng tối một cách kỳ diệu biến mất, không biết ánh sáng từ đâu chiếu đến, làm sáng con đường sỏi dài dường như không có điểm cuối."
  },
  AvgDialog_47178_Content_80 = {
    Text = "Chúng ta không có lựa chọn. Dù là cô ấy, tôi, hay ngài, đều như nhau．"
  },
  AvgDialog_47178_Content_81 = {
    Text = "……chán chường. Tôi muốn nghỉ ngơi."
  },
  AvgDialog_47178_Content_82 = {
    Text = "Ông vẫy tay. Vị lão nhân cúi người chào ông, rồi biến mất trong hư vô vô tận."
  },
  AvgDialog_47178_Content_83 = {
    Text = "Trước khi ngủ, anh ta liếc nhìn những người đã dâng ánh sáng cho anh. Một tiếng thở dài lặng lẽ tan biến, mất hút trong hư vô vô tận."
  },
  AvgDialog_47178_Content_84 = {Text = "A!"},
  AvgDialog_47178_Content_85 = {
    Text = "Tiếp theo sau cảm giác rơi tự do khiến tim ngừng đập là một cơn đau nhói mạnh mẽ."
  },
  AvgDialog_47178_Content_86 = {
    Text = "Cơn đau không kéo dài lâu. Miriam rời khỏi không gian hư vô và nhìn quanh mình."
  },
  AvgDialog_47178_Content_87 = {
    Text = "Một số người không thể đọc hoặc tụng đọc kinh đã được mời ra khỏi phòng cầu nguyện, chỉ còn lại một phần nhỏ. Một số người đau khổ ngã xuống đất, còn những người khác thì đang nhắm mắt cầu nguyện, nụ cười hạnh phúc nở trên môi."
  },
  AvgDialog_47178_Content_88 = {
    Text = "Deborah ngồi bên cạnh cô, mỉm cười và từ từ mở mắt. Nhìn thấy vẻ mặt của Miriam, cô lộ ra vẻ quan tâm."
  },
  AvgDialog_47178_Content_89 = {
    Text = "Này, Miriam? Bạn có ổn không?"
  },
  AvgDialog_47178_Content_9 = {
    Text = "Hai đầu con đường là hai hồ nước lớn. Miriam lại gần hồ nước, nghiêng đầu nhẹ vào trong một chút."
  },
  AvgDialog_47178_Content_90 = {
    Text = "Đau đầu quá…… Vừa rồi tôi còn bình thường, tại sao tôi lại đột nhiên rời đi? Có phải là có chỗ nào đó không ổn rồi phải không……"
  },
  AvgDialog_47178_Content_91 = {
    Text = "Bạn hình như…… đã thất bại. Giấc mơ của nhà vua đã từ chối bạn."
  },
  AvgDialog_47178_Content_92 = {
    Text = "Nhưng tại sao… tôi rõ ràng đã thấy một hình dáng, tại sao đột nhiên…"
  },
  AvgDialog_47178_Content_93 = {
    Text = "Linh mục thông qua lời cầu nguyện bước vào giấc mơ của vua, cung cấp sự giúp đỡ cho vua. Theo lý thuyết, có thể nhìn thấy hình dáng của vua là một điều rất đặc biệt, chỉ có những linh mục tài năng nhất mới làm được vậy!"
  },
  AvgDialog_47178_Content_94 = {
    Text = "Tôi cũng không rõ vấn đề nằm ở đâu…… Nhưng đây mới là lần đầu tiên! Có thể chỉ là chưa quen, sau này sẽ tốt hơn!"
  },
  AvgDialog_47178_Content_95 = {
    Text = "Cảm ơn bạn…"
  },
  AvgDialog_47178_Content_96 = {
    Text = "Khách khí gì~ cố gắng lên! Lời cầu nguyện này là điều mà mỗi linh mục đều cần phải nắm vững, sau này dù là cầu nguyện hay nghi lễ hóa Người Cá, đều cần dùng lời cầu nguyện này để thiết lập kết nối với Đức Vua."
  },
  AvgDialog_47178_Content_97 = {
    Text = "Sau này chúng ta sẽ ở lại đền thần, trở thành linh mục của vua, để Lemuria một lần nữa trở thành thần quốc!"
  },
  AvgDialog_47178_Content_98 = {
    Text = "Sự tử tế của người bạn đã làm giảm bớt cảm giác yếu đuối của Miriam. Khi chuẩn bị đứng dậy rời đi, cô lại nhìn về phía tượng. Trong không gian tinh thần, cô đã thấy những hình ảnh ánh sáng và bóng tối. Những hình ảnh này giờ đây chồng lên nhau với bức tượng."
  },
  AvgDialog_47178_Content_99 = {
    Text = "Dáng vẻ mờ ảo ngồi xiên trên ngai vàng, khuôn mặt bị xúc tu tượng trưng sức mạnh che phủ."
  },
  AvgDialog_47232_Content_1 = {
    Text = "Khu vực quản lý phía trước, người không liên quan không được vào tùy tiện. Xin vui lòng xuất trình giấy tờ tùy thân."
  },
  AvgDialog_47232_Content_10 = {
    Text = "Nguyện chìa khóa bạc dẫn đường cho chúng ta."
  },
  AvgDialog_47232_Content_2 = {
    Text = "Điều tra viên Đại học Misag William Delaplane, ID chìa khóa bạc I-2083."
  },
  AvgDialog_47232_Content_3 = {
    Text = "%player%, K-0617."
  },
  AvgDialog_47232_Content_4 = {
    Text = "Ramona, I-3017."
  },
  AvgDialog_47232_Content_5 = {
    Text = "Ánh mắt của anh ta, giống như đang nhìn một người chuẩn bị hy sinh…"
  },
  AvgDialog_47232_Content_6 = {
    Text = "Khu vực cấm trong thiên tai có kích thước tinh thần hỗn loạn bất thường, chúng ta thường phải <Yellow:đối mặt đồng thời với nhiều chiến trường tinh thần>, gây thương tổn tinh thần lớn hơn nhiều so với thể xác."
  },
  AvgDialog_47232_Content_7 = {
    Text = "Không ít điều tra viên đã mất tinh thần khi cố gắng kiểm soát khu vực thảm họa hòa tan. Các người cũng cần chú ý cân bằng việc phân bổ tài nguyên giữa các chiến trường, tránh để xảy ra tình huống xấu nhất."
  },
  AvgDialog_47232_Content_8 = {
    Text = "Trong gương chiếu hậu, người lính canh gác chào các bạn một cách lịch sự."
  },
  AvgDialog_47232_Content_9 = {
    Text = "Nguyện Chìa Khóa Bạc soi sáng con đường phía trước."
  },
  AvgDialog_47798_Content_1 = {
    Text = "Chúng ta lén vào đây như vậy có được không? Bà Sylvia… Đây là văn phòng của bà ấy."
  },
  AvgDialog_47798_Content_10 = {Text = "Thử xem?"},
  AvgDialog_47798_Content_11 = {
    Text = "Muphí nhặt lên một viên sô-cô-la sữa, cúi đầu im lặng. Phòng tư vấn tâm lý chìm vào một sự yên lặng đầy căng thẳng, khiến bạn rùng mình không kiềm được."
  },
  AvgDialog_47798_Content_12 = {
    Text = "Khó, hay bạn không thích ăn sô cô la? Hay bạn bị dị ứng với hạt cacao?"
  },
  AvgDialog_47798_Content_13 = {
    Text = "Chúng ta đi đến quán cà phê của trường để tìm thêm thứ khác nào! Mặc dù đầu bếp đã nghỉ vào giờ này, nhưng chúng ta có thể tự thử làm gì đó —— ưm!"
  },
  AvgDialog_47798_Content_14 = {
    Text = "Chưa kịp phản ứng, một viên sô-cô-la sữa đã được đưa vào miệng bạn."
  },
  AvgDialog_47798_Content_15 = {
    Text = "Cô ấy rút người ra, phần thịt đầu ngón tay lạnh lẽo lướt qua đầu lưỡi của bạn. Giây tiếp theo, hương vị sô-cô-la đậm đà nổ bùng trong miệng, trượt xuống bụng."
  },
  AvgDialog_47798_Content_16 = {
    Text = "Tôi không có nói là đừng ăn——"
  },
  AvgDialog_47798_Content_17 = {
    Text = "Muphí nói, từ hộp quà, anh ta chọn ra viên sô-cô-la có màu tối nhất. Độ tinh khiết rất cao, trông như không thêm bất kỳ loại đường nào ——"
  },
  AvgDialog_47798_Content_18 = {
    Text = "Chua quá…! Vừa chua vừa đắng…"
  },
  AvgDialog_47798_Content_19 = {
    Text = "Thấy khuôn mặt cô ấy hoàn toàn biến dạng, bạn vội vàng lấy thêm một miếng sô-cô-la sữa cho cô ấy."
  },
  AvgDialog_47798_Content_2 = {
    Text = "Không sao cả. Cô Sylva đã nói rằng tôi có thể lấy đồ ngọt trong phòng tư vấn tâm lý bất cứ lúc nào."
  },
  AvgDialog_47798_Content_20 = {
    Text = "Cảm ơn, cảm ơn…"
  },
  AvgDialog_47798_Content_21 = {
    Text = "Phòng tư vấn tâm lý có đầy đủ bộ ấm chén, các bạn pha một ấm trà đỏ nhạt và trò chuyện một cách thoải mái, không vội vã."
  },
  AvgDialog_47798_Content_22 = {
    Text = "Cho đến khi Muphí ăn hết miếng sô-cô-la sữa cuối cùng và vẫn còn thèm, bạn mới nhìn lên đồng hồ treo tường."
  },
  AvgDialog_47798_Content_23 = {
    Text = "Tôi sẽ đi thực hiện nhiệm vụ sau, ăn đồ ngọt vào nửa đêm, trước khi nằm nghỉ nhớ đánh răng."
  },
  AvgDialog_47798_Content_24 = {
    Text = "Thực hiện nhiệm vụ? Muộn thế này?"
  },
  AvgDialog_47798_Content_25 = {
    Text = "Vẫn là do ảnh hưởng của sự biến dị Lemvaxi, toàn bộ Đại học Misaque đều bận túi bụi. \n Đi thôi, tôi đưa bạn về phòng nhé."
  },
  AvgDialog_47798_Content_26 = {
    Text = "Bạn vừa bước ra ngoài một bước, giây tiếp theo, bạn vô tình vấp ngã xuống đất."
  },
  AvgDialog_47798_Content_27 = {
    Text = "Á?! Xin, xin lỗi."
  },
  AvgDialog_47798_Content_28 = {
    Text = "Muphí luống cuống đỡ bạn dậy, bạn cúi đầu nhìn xuống và mới phát hiện một cái xúc tu màu nâu đỏ đang bám chặt vào chân bạn."
  },
  AvgDialog_47798_Content_29 = {
    Text = "Đó là một phần của trang phục váy của Muphí, hoặc là một phần của \"thân thể\" cô ấy."
  },
  AvgDialog_47798_Content_3 = {
    Text = "Nếu thật sự như vậy, chúng ta cũng không cần phải trèo cửa sổ vào chứ?"
  },
  AvgDialog_47798_Content_30 = {
    Text = "Bạn… bây giờ nhất định phải đi sao?"
  },
  AvgDialog_47798_Content_31 = {
    Text = "Do ảnh hưởng của dòng sông thiêng liêng Lemvahi, các thâm cảnh trên khắp thế giới đều xuất hiện những dị thường."
  },
  AvgDialog_47798_Content_32 = {
    Text = "Đội điều tra viên lớp hai đã tuần tra suốt đêm, tôi đã hẹn họ vào lúc tám giờ sáng để tiếp nhận việc tuần tra thâm cảnh ở khu đông."
  },
  AvgDialog_47798_Content_33 = {
    Text = "Bất thường……"
  },
  AvgDialog_47798_Content_34 = {
    Text = "Tôi, tôi cảm thấy... Tôi cũng... có chút bất thường..."
  },
  AvgDialog_47798_Content_35 = {
    Text = "Có khó chịu không? có phải đang sốt không?"
  },
  AvgDialog_47798_Content_36 = {
    Text = "Nói xong, bạn cởi găng tay và đưa tay ra để sờ trán cô ấy. Muphí đột ngột lùi một bước, tránh khỏi tay bạn —— nhưng xúc tu vẫn quấn chặt lấy chân bạn."
  },
  AvgDialog_47798_Content_37 = {
    Text = "Nếu tôi nhớ không lầm, đưa bạn đến khu Đông chỉ mất nửa giờ thôi, không cần phải xuất phát sớm như vậy."
  },
  AvgDialog_47798_Content_38 = {
    Text = "Làm phần thưởng…, tiểu thư đây sẽ đi tuần cùng cậu vào ban ngày…"
  },
  AvgDialog_47798_Content_39 = {
    Text = "Dù sao…… hãy ở bên tôi đến khi trời sáng……"
  },
  AvgDialog_47798_Content_4 = {
    Text = "…không sao cả, dù sao cô Sylva cũng không có ở trường. Để dập tắt ảnh hưởng của sự kiện Lemvaxi, cô ấy đã cùng với các điều tra viên khác thành lập đội và đi đến thành phố Lentiennam."
  },
  AvgDialog_47798_Content_5 = {
    Text = "Tìm thấy rồi."
  },
  AvgDialog_47798_Content_6 = {
    Text = "Từ tủ bánh ngọt của phòng tư vấn tâm lý, bạn lấy ra một hộp quà tinh xảo ——"
  },
  AvgDialog_47798_Content_7 = {
    Text = "Thương hiệu sô-cô-la này… có lẽ.."
  },
  AvgDialog_47798_Content_8 = {
    Text = "Giấy gói mạ kim phẳng phiu, thậm chí dải ruy băng trang trí cũng được thêu một đường chỉ bạc, đủ để chứng minh giá trị cao của hộp sô cô la này."
  },
  AvgDialog_47798_Content_9 = {
    Text = "Hương đắng của ca cao đã ngay lập tức lan tỏa ra ngay khi dải lụa được tháo mở."
  },
  AvgDialog_47803_Content_1 = {
    Text = "Hừ… Người Giữ Gìn nhỏ của Misaque, thật sự đã nể mặt ghé thăm ngôi nhà khiêm tốn của tôi. \nPhòng làm việc nhỏ bé này của tôi, nhờ sự hiện diện của ngài mà tỏa sáng rực rỡ."
  },
  AvgDialog_47803_Content_10 = {
    Text = "Cô Sơn ơi!"
  },
  AvgDialog_47803_Content_11 = {
    Text = "Suỵt, suỵt… Hãy để yên cho tôi xem."
  },
  AvgDialog_47803_Content_12 = {
    Text = "Cô ấy ngừng lại, đưa lưỡi dao khắc chạm vào mặt bạn và vuốt ve qua lại"
  },
  AvgDialog_47803_Content_13 = {
    Text = "Bạn có biết không, mỗi nghệ sĩ đều có một nàng thơ độc nhất vô nhị."
  },
  AvgDialog_47803_Content_14 = {
    Text = "Catullus có Lesbia của mình, Petrarch có Laura mà ông yêu sâu sắc…"
  },
  AvgDialog_47803_Content_15 = {
    Text = "Đôi mắt sâu thẳm ấy không có chút hung ác bạo lực nào, trái lại đầy những cảm xúc mà bạn khó có thể miêu tả——"
  },
  AvgDialog_47803_Content_16 = {
    Text = "Và bây giờ, tôi cũng có <Blue:Camiel> của tôi. Ông nghĩ sao? Ngài Người Giữ Gìn."
  },
  AvgDialog_47803_Content_2 = {
    Text = "Bạn đẩy đống vật liệu điêu khắc bên cửa, vất vả chen qua vào xưởng làm việc của nghệ sĩ sơn ở tầng tây của cánh phụ Misaque."
  },
  AvgDialog_47803_Content_3 = {
    Text = "Nghệ sĩ điêu khắc ngồi trên bệ sơn, con dao khắc bay lượn giữa các ngón tay của cô, khiến người xem không khỏi rùng mình — con dao quá sắc, đủ để cắt đứt ngón tay của cô."
  },
  AvgDialog_47803_Content_4 = {
    Text = "Chẳng phải điều tra viên cùng người canh gác đã bảo anh rằng muốn gặp tôi sao?"
  },
  AvgDialog_47803_Content_5 = {
    Text = "Các thân thể được đánh thức có quyền tự do tuyệt đối trong giới hạn quy định tại trường, nhưng Sơn là một ngoại lệ——dựa trên tội ác mà cô đã phạm phải tại nhà tế bần, cô không được phép hành động một mình."
  },
  AvgDialog_47803_Content_6 = {
    Text = "À… đúng vậy. Ngài xem, đều là do thiếu cảm hứng, khiến đầu óc tôi cũng bị lấp đầy bởi sơn."
  },
  AvgDialog_47803_Content_7 = {
    Text = "Xin hãy đến gần tôi một chút, để tôi có thể nhìn rõ đôi mắt bạn lần nữa... Để tôi, người không may bị mắc kẹt trong căn phòng này, được nhìn thế giới qua ánh mắt của bạn."
  },
  AvgDialog_47803_Content_8 = {
    Text = "Lý do của cô ta thật hoành tráng, bạn nhất thời không thể tìm ra lý do từ chối, chỉ có thể tiến lại gần cô ấy ——"
  },
  AvgDialog_47803_Content_9 = {
    Text = "Sơn đột ngột giật mạnh áo choàng đồng phục, khiến mặt bạn lập tức tiến sát đến trước mặt cô ấy."
  },
  AvgDialog_47807_Content_1 = {
    Text = "Sương mù dày đặc bao phủ giác quan đang chìm trong giấc mơ, bóng tối kéo dài thoạt nhìn bình yên như mặt nước tĩnh lặng, nhưng thực tế những cơn sóng đen đã cuồn cuộn trào lên, va chạm mạnh mẽ vào hàng rào tinh thần."
  },
  AvgDialog_47807_Content_10 = {
    Text = "Hilaster vung chiếc la bàn, ấn bạn xuống giường."
  },
  AvgDialog_47807_Content_11 = {
    Text = "Cô ấy chỉ ra mặt trăng tròn treo cao ngoài cửa sổ, rồi chỉ vào bạn ——"
  },
  AvgDialog_47807_Content_12 = {
    Text = "……ác mộng."
  },
  AvgDialog_47807_Content_13 = {
    Text = "Tôi ở đây, sẽ không có ác mộng đâu."
  },
  AvgDialog_47807_Content_14 = {
    Text = "Hơi thở của bạn và nhịp điệu nhẹ nhàng của cô ấy vuốt ve chăn gối dần dần hòa quyện, mỗi hơi thở giống như một bản hợp tấu cùng gió. Ý thức lại bắt đầu chìm xuống, chìm vào giấc mơ."
  },
  AvgDialog_47807_Content_15 = {
    Text = "Lại thêm một giấc mơ dịu dàng, nhẹ nhàng, dẫn lối tới bình minh yên bình."
  },
  AvgDialog_47807_Content_2 = {
    Text = "Đến ngày nay, ảnh hưởng của sông thiêng liêng và cây khổng lồ vẫn bao quanh bạn."
  },
  AvgDialog_47807_Content_3 = {
    Text = "Những ký ức quá khứ ngưng tụ thành những bong bóng mỏng manh dễ vỡ trong giấc mơ, mỗi lần bạn trở mình, chúng đều tan biến như hoa trong gương và trăng dưới nước, chạm vào là tiêu tan."
  },
  AvgDialog_47807_Content_4 = {
    Text = "Bóng tối hỗn loạn kéo bạn chìm sâu vào đáy tâm thức. Ngay trước khi bạn cảm nhận cơ thể vỡ vụn, một làn gió nhẹ thổi vào giấc mơ của bạn."
  },
  AvgDialog_47807_Content_5 = {
    Text = "Gió dường như có màu sắc, khiến người ta không thể bỏ qua, nhưng cũng không phô trương. Nó giống như một người bảo vệ mong manh, dùng sự hiện diện của mình để chứng minh rằng bạn sẽ không bị lạc trong giấc mơ ——"
  },
  AvgDialog_47807_Content_6 = {
    Text = "Mở mắt trong khoảnh khắc, bạn đã đối diện với \"Người Giữ Mơ\"."
  },
  AvgDialog_47807_Content_7 = {
    Text = "Hilaster… sao bạn ở đây?"
  },
  AvgDialog_47807_Content_8 = {
    Text = "Thân thể được đánh thức gật đầu và ngồi xuống mép giường của bạn, tấm nệm mềm mại lõm xuống một chút do trọng lượng."
  },
  AvgDialog_47807_Content_9 = {
    Text = "Có phải đã xảy ra tình huống bất thường trong nhiệm vụ không? Tôi sẽ ngay lập tức——"
  },
  AvgDialog_47808_Content_1 = {
    Text = "Pháp Luân Tư, bạn đang xem gì?"
  },
  AvgDialog_47808_Content_10 = {
    Text = "Ánh sáng của Pháp Luân Tư nhấp nháy một vài lần."
  },
  AvgDialog_47808_Content_11 = {
    Text = "Trước đây chưa từng, khi tôi đủ tuổi để tham gia các buổi tụ họp, Lemuria đã bị bao vây bởi thảm họa từ thiên nhiên."
  },
  AvgDialog_47808_Content_13 = {
    Text = "Người giữ bí mật, anh có muốn ở lại đây tối nay để bầu bạn với tôi không?"
  },
  AvgDialog_47808_Content_14 = {
    Text = "Hãy coi như… nghe một kẻ điên kể câu chuyện. Một đêm, chỉ cần một đêm thôi…"
  },
  AvgDialog_47808_Content_2 = {
    Text = "Bạn đã nhìn thấy Pháp Luân Tư từ xa, cô ấy thực sự quá \"đặc biệt nổi bật\" trong đêm. Giữa sa mạc tĩnh lặng, đó là ánh sáng khác biệt duy nhất."
