  AvgDialog_47808_Content_8 = {
    Text = "Trước khi mọi thảm họa xảy ra, các thanh niên mỗi năm vào đêm hè đều tụ tập bên bờ sông… để tìm kiếm người bạn đời, để xây dựng gia đình mới."
  },
  AvgDialog_47808_Content_9 = {
    Text = "Nghe có vẻ sẽ rất náo nhiệt. Pháp Luân Tư thì sao? Bạn cũng đã tham gia vào bữa tiệc đêm hè chưa?"
