  AvgDialog_48142_Content_16 = {
    Text = "Salvador đã mở cửa sổ nhỏ của phòng xưng tội, đặt hai tay lên song cửa, lòng bàn tay ngửa ra đối diện bạn."
  },
  AvgDialog_48142_Content_17 = {
    Text = "Nếu có thể, hãy nắm lấy tay tôi."
  },
  AvgDialog_48142_Content_18 = {
    Text = "(duỗi thẳng hai tay)"
  },
  AvgDialog_48142_Content_19 = {
    Text = "Dù tất cả các bạn đều đeo găng tay, cũng không thể ngăn cản nhiệt độ bất thường của anh ta. Giống như ngọn lửa bùng cháy khi linh hồn sôi sục, thiêu đốt huyết quản của bạn một cách không thể kháng cự."
  },
  AvgDialog_48142_Content_2 = {
    Text = "Không có chuyện đó, chỉ cần có thể giúp đỡ Đức Giám mục Salvador…"
  },
  AvgDialog_48142_Content_20 = {
    Text = "Chiếc chìa khóa bạc trên ngực cũng nóng rực, làm bong tróc từng lớp linh hồn của các ngươi, chỉ để lại phần lõi trần trụi, lộ rõ nhất."
  },
  AvgDialog_48142_Content_21 = {
    Text = "Tiếp theo, xin vui lòng nhắc lại những gì tôi nói."
  },
  AvgDialog_48142_Content_22 = {
    Text = "Tội lỗi như xiềng xích, nhưng chìa khóa của sự tha thứ và cứu rỗi vẫn nằm ngay trên xiềng xích ấy."
  },
  AvgDialog_48142_Content_23 = {
    Text = "Tội lỗi như xiềng xích, nhưng chìa khóa của sự tha thứ và cứu rỗi vẫn nằm ngay trên xiềng xích ấy."
  },
  AvgDialog_48142_Content_24 = {
    Text = "Lòng bị đốt cháy bởi khổ hạnh của đức hạnh, anh ta đã gặt hái hậu quả."
  },
  AvgDialog_48142_Content_25 = {
    Text = "Lòng bị khổ hạnh thiêu rụi, ông đã nếm trái đắng…"
  },
  AvgDialog_48142_Content_26 = {
    Text = "Một tia cảm hứng như chớp đã kết nối những từ trong tâm trí. Trước khi Salvador nói tiếp, bản năng khiến bạn cất tiếng trước."
  },
  AvgDialog_48142_Content_27 = {
    Text = "……thần cha nhân từ, xin cho người bước đi trong ánh sáng, xin tha thứ cho tội lỗi của người."
  },
  AvgDialog_48142_Content_28 = {
    Text = "Bạn cũng đã nghe thấy sự hướng dẫn của Cha Thần…"
  },
  AvgDialog_48142_Content_29 = {
    Text = "Sứ giả xanh xao, cảm ơn bạn đã xua tan bóng tối của tôi một lần nữa."
  },
  AvgDialog_48142_Content_3 = {
    Text = "Phòng xưng tội mờ tối và chật hẹp, bạn ngồi trên chiếc ghế gỗ sồi như trên đống lửa, nhưng sự \"tò mò\" về lý do mình bị gọi đến đã vượt xa nỗi sợ hãi."
  },
  AvgDialog_48142_Content_4 = {
    Text = "Thông thường, Salvador mới là người ngồi trong phòng xưng tội. Nhưng ngay khi bạn đến đền thánh lớn, anh ta đã để bạn ngồi vào đây, chắc chắn có lý do đặc biệt."
  },
  AvgDialog_48142_Content_5 = {
    Text = "Xin hãy để tôi bỏ qua những nghi thức rườm rà, 'lửa nhợt nhạt', và lắng nghe lời sám hối của tôi."
  },
  AvgDialog_48142_Content_6 = {
    Text = "Gần đây, tôi…… không biết tại sao lại xuất hiện những khát vọng không nên có."
  },
  AvgDialog_48142_Content_7 = {
    Text = "Giọng anh ta như tiếng vọng từ xa trong núi, dần chìm xuống và thấm vào tường gỗ cổ kính của phòng xưng tội. Giọng nói trầm thấp trói buộc một con thú hoang vô danh, e ngại nó chạm tới điều cấm kỵ vô hình."
  },
  AvgDialog_48142_Content_8 = {
    Text = "Tôi phải thừa nhận, dù tôi biết đến những dục vọng này, nhưng chưa bao giờ thực sự trải nghiệm chúng, càng không hiểu chúng đã len lỏi vào tâm trí tôi và vượt qua ánh hào quang của Cha như thế nào."
  },
  AvgDialog_48142_Content_9 = {
    Text = "Nhưng, như bác sĩ cũng cần được chữa lành, có lẽ tôi, người thay mặt này, cũng cần phải xưng tội với sứ giả của Cha thần, cầu xin sự hướng dẫn và tha thứ."
  },
  AvgDialog_48238_Content_1 = {
    Text = "Có khá hơn chút nào không, Liz?"
  },
  AvgDialog_48238_Content_10 = {
    Text = "Một bàn tay từ trên sân khấu duỗi ra, đưa đến trước mặt bạn một cách thanh lịch."
  },
  AvgDialog_48238_Content_11 = {
    Text = "Tôi? Nhưng tôi chưa bao giờ…… A……"
  },
  AvgDialog_48238_Content_12 = {
    Text = "Chưa để bạn nói xong, bàn tay đó đã kéo bạn lên sân khấu mà chẳng nói chẳng rằng."
  },
  AvgDialog_48238_Content_13 = {
    Text = "...vui lòng đỡ lấy eo tôi, Người Giữ Gìn."
  },
  AvgDialog_48238_Content_14 = {
    Text = "Tôi vẫn không thể nhảy, nhưng tôi nghĩ mình có thể dạy bạn các động tác đẹp này."
  },
  AvgDialog_48238_Content_15 = {
    Text = "Hãy giúp tôi giải quyết ảnh hưởng của sông thiêng liêng, đây chính là điều bạn đã nói…"
  },
  AvgDialog_48238_Content_16 = {
    Text = "Bàn tay đó dẫn dắt bạn đặt lên hông, thân thể run rẩy một chút."
  },
  AvgDialog_48238_Content_17 = {
    Text = "Cảm giác lạnh lẽo của lụa truyền đến đầu ngón tay. Dưới lớp lụa, vòng eo mềm mại, săn chắc phập phồng theo nhịp thở."
  },
  AvgDialog_48238_Content_18 = {
    Text = "Tôi hoàn toàn chưa từng tiếp xúc với múa ballet… như vậy có thực sự được không?"
  },
  AvgDialog_48238_Content_19 = {
    Text = "Theo nhạc, làm những gì bạn muốn, thì tốt rồi."
  },
  AvgDialog_48238_Content_2 = {
    Text = "Trong rạp hát vắng vẻ, cô gái lắc đầu. Bạn nghe thấy hơi thở gấp gáp của cô ấy, nhìn thấy má cô ấy ửng đỏ dưới ánh sáng mờ ảo."
  },
  AvgDialog_48238_Content_20 = {
    Text = "Hãy nhớ, bí mật của múa ballet là quay."
  },
  AvgDialog_48238_Content_21 = {
    Text = "Từ hai tay đến eo bụng. Rồi từ eo bụng xuống hai chân. Người vũ công dẫn dắt bạn hoàn thành từng động tác uyển chuyển, cảm nhận sự chuyển động tinh tế lan tỏa qua từng phần cơ thể của cô ấy."
  },
  AvgDialog_48238_Content_22 = {
    Text = "Hãy đá chân. Hãy uốn lưng. Hãy nhảy."
  },
  AvgDialog_48238_Content_23 = {
    Text = "Nhạc nhẹ nhàng vang vọng trong nhà hát vắng người, một tia sáng lạnh lùng theo dõi các bạn trên sân khấu."
  },
  AvgDialog_48238_Content_24 = {
    Text = "Các bạn cùng nhau xoay vòng.Liz ngày càng đỏ mặt, đôi mắt xanh ngập tràn sự e thẹn khi nhìn bạn."
  },
  AvgDialog_48238_Content_25 = {
    Text = "Tôi nhảy thế nào?"
  },
  AvgDialog_48238_Content_26 = {
    Text = "Hoàn toàn vô ích. Nhưng đây sẽ là buổi biểu diễn múa yêu thích của tôi, bạn giữ bí mật."
  },
  AvgDialog_48238_Content_27 = {
    Text = "Chúng ta có nên chuyển chậm một chút không? Tôi cảm thấy có chút…"
