  AvgDialog_48238_Content_28 = {
    Text = "Đôi mắt xanh nhẹ nhàng khép lại, đôi môi lạnh giá hôn bạn."
  },
  AvgDialog_48238_Content_29 = {Text = "Xoay.xoay."},
  AvgDialog_48238_Content_3 = {
    Text = "Ban đầu tôi nghĩ, nhà hát có thể làm cho tâm trạng bạn bình tĩnh lại, loại bỏ ảnh hưởng của sông thiêng liêng."
  },
  AvgDialog_48238_Content_30 = {
    Text = "Mái tóc trắng bay trong gió, những ngọn lửa màu xanh lục bao quanh các bạn, không chút hơi ấm, nhảy múa cùng với giai điệu. Trang phục khiêu vũ đen và xanh lá uốn lượn trong không trung như những đường cong của cánh thiên nga."
  },
  AvgDialog_48238_Content_31 = {
    Text = "Choáng váng.Bạn muốn nói choáng váng."
  },
  AvgDialog_48238_Content_32 = {
    Text = "Liz thở ngày càng nặng nề phả vào mặt bạn, bạn vô thức dùng sức hai tay, siết chặt eo cô ấy, lực mạnh khiến cô cau mày nhẹ. Các bạn quay cuồng."
  },
  AvgDialog_48238_Content_33 = {
    Text = "Hãy nhớ, Người Giữ Gìn. Bí mật của ba lê là sự quay vòng…"
  },
  AvgDialog_48238_Content_34 = {
    Text = "Đêm nay, dưới ánh sáng rực rỡ của nhà hát, một đôi vũ công lạc trong những vòng quay."
  },
  AvgDialog_48238_Content_4 = {
    Text = "Có lẽ nên làm gì đó khác để xoa dịu tâm trí. Tôi nghĩ xem…"
  },
  AvgDialog_48238_Content_5 = {
    Text = "Đôi mắt xanh lấp lánh, chiếc váy đen vẽ nên một vòng cung trước mặt bạn, cô gái thành thục bước lên sân khấu."
  },
  AvgDialog_48238_Content_6 = {
    Text = "Tôi nghĩ, bạn vẫn còn vấn vương điều gì đó về việc nhảy múa…"
  },
  AvgDialog_48238_Content_7 = {
    Text = "Tôi không nói là muốn nhảy."
  },
  AvgDialog_48238_Content_8 = {
    Text = "Ý bạn là…?"
  },
  AvgDialog_48238_Content_9 = {
    Text = "Tôi sẽ dạy bạn nhảy, Người Giữ Gìn."
  },
  AvgDialog_48555_Content_1 = {
    Text = "Đi qua một góc nữa của tòa nhà giảng đường, áp lực tinh thần bủa vây bạn từ sáng sớm càng trở nên nặng nề hơn, khiến bạn gần như nghẹt thở."
  },
  AvgDialog_48555_Content_10 = {
    Text = "Quả bong bóng trong lòng bàn tay bạn phát ra ánh sáng yếu ớt, tràn đầy sức sống."
  },
  AvgDialog_48555_Content_11 = {
    Text = "Trong vách nang bán trong suốt, những cành cây giống như cánh ve sầu đôi bên khép lại, nó vỗ cánh không theo quy luật nào cả, như thể đang chìm đắm trong một giấc mơ dài lâu."
  },
  AvgDialog_48555_Content_12 = {
    Text = "Đây là...?"
  },
  AvgDialog_48555_Content_13 = {
    Text = "Phiệt thấy bạn không từ chối quà tặng của cô ấy, cuối cùng cũng thở phào nhẹ nhõm và nở nụ cười hài lòng."
  },
  AvgDialog_48555_Content_14 = {
