  },
  AvgDialog_48555_Content_15 = {
    Text = "Trong khoảng thời gian rất rất lâu trước đây, tôi chưa bao giờ nảy mầm… Tôi đã từng nghĩ rằng, tôi sẽ mãi không trở thành một @2 hoàn chỉnh."
  },
  AvgDialog_48555_Content_16 = {
    Text = "<Small:phát triển bất thường…… lại là ảnh hưởng từ phía Lemvahi.>"
  },
  AvgDialog_48555_Content_17 = {
    Text = "Phiệt bây giờ cảm thấy thế nào? Sau khi nảy mầm, có gì bất thường khác không?"
  },
  AvgDialog_48555_Content_18 = {
    Text = "Phiệt lắc đầu, trên khuôn mặt trẻ thơ tràn đầy niềm vui."
  },
  AvgDialog_48555_Content_19 = {
    Text = "Nóng quá… đầu óc, tứ chi đều cảm thấy nóng. Có lẽ đây chính là cảm giác trở thành người lớn mà Tinkerer nói?"
  },
  AvgDialog_48555_Content_2 = {
    Text = "Bạn dựa vào tường và ngồi xổm xuống, giữa các động tác, ánh mắt bạn bắt gặp một bóng dáng quen thuộc lóe lên."
  },
  AvgDialog_48555_Content_3 = {
    Text = "……Phiệt? Là bạn không?"
