  AvgDialog_48555_Content_5 = {
    Text = "……Người Giữ Gìn."
  },
  AvgDialog_48555_Content_6 = {
    Text = "Cô ấy đưa tay về phía bạn, dường như muốn bò ra khỏi \"cái nôi\"— nhưng rời bỏ \"cái nôi\" này, chỉ càng làm bản năng của cô ấy mạnh mẽ hơn."
  },
  AvgDialog_48555_Content_7 = {
    Text = "Phiệt nhanh chóng nhận ra sự bất thường của mình, vì vậy cuối cùng chỉ mím môi, vặn bỏ quả cầu gần thân thể nhất trên \"giường nôi\"."
  },
  AvgDialog_48555_Content_8 = {
    Text = "Xin hãy nhận… nhận cái này."
  },
  AvgDialog_48555_Content_9 = {
    Text = "Bạn đưa tay ra, khi lấy bóng, đầu ngón tay chạm vào lòng bàn tay mềm mại của cô ấy. Phiệt lập tức run rẩy toàn thân, co người lại và trốn sâu hơn vào trong nôi."
  },
  AvgDialog_48556_Content_1 = {
    Text = "Người giữ bí mật, nếu tiện, ngài có thể dừng lại một chút để giúp tôi không?"
  },
  AvgDialog_48556_Content_10 = {
    Text = "Đó tuyệt đối không phải là giai điệu của cà đa sác, âm thanh xuyên qua thùy thái dương như vũ trụ huyền bí, lại lấp lánh dịu dàng như những ngôi sao buổi sáng."
  },
  AvgDialog_48556_Content_11 = {
    Text = "Ý thức trở thành một con tàu không có lái, dưới sự dẫn dắt của tiếng hát từ Tinkerer, trôi dần về bờ bên kia của dục vọng."
  },
  AvgDialog_48556_Content_12 = {
    Text = "Góc môi in dấu cảm giác lạnh lẽo và ẩm ướt, trong họng bốc lên lửa âm không tên."
  },
  AvgDialog_48556_Content_13 = {
    Text = "Mở mắt lần nữa, tinkerer cũng đang ngẩng đầu lên, đôi môi của cô ấy trông đặc biệt mềm mại và căng mọng."
  },
  AvgDialog_48556_Content_14 = {
    Text = "Một câu trả lời khó tin nổi đang sẵn sàng thốt ra từ môi bạn, nhưng lý trí nhanh chóng bị cuốn đi khi những lời niệm tụng lại chạm đến môi."
  },
  AvgDialog_48556_Content_15 = {
    Text = "Giọng hát chơi đùa với những dục vọng sâu thẳm trong lòng, ranh giới giữa thực tế và ảo tưởng lại trở nên mờ nhạt, không đủ sức chống lại, cũng không đủ sức thoát thân."
  },
  AvgDialog_48556_Content_16 = {
    Text = "Suỵt… Chỉ trong đêm nay, xin hãy trở thành tù nhân của tiếng hát tôi…"
  },
  AvgDialog_48556_Content_2 = {
    Text = "Tất nhiên, gần đây có gặp chuyện gì không vui ở trường không?"
