  AvgDialog_48556_Content_3 = {
    Text = "Không, không,… không phải như vậy."
  },
  AvgDialog_48556_Content_4 = {
    Text = "Chỉ là tôi có một bài hát, dù thế nào đi nữa… đều muốn hát cho bạn nghe nhé."
  },
  AvgDialog_48556_Content_5 = {
    Text = "Bạn gật đầu, lại ngồi xuống chiếc ghế dài trong phòng nghỉ —— chỉ là một bài hát mà thôi."
  },
  AvgDialog_48556_Content_6 = {
