  AvgDialog_48596_Content_1 = {
    Text = "Dựa theo những manh mối mà Erika cung cấp, chiếc áo choàng dự phòng của tôi cuối cùng đã được nhìn thấy bên ngoài khu nhà cũ của thân thể được đánh thức…"
