  AvgDialog_4871_Content_11 = {
    Text = "Xử lý? Phim ở bách hóa không thể dùng trực tiếp sao?"
  },
  AvgDialog_4871_Content_12 = {
    Text = "Ngân tâm sẽ khiến phim bị phơi sáng bất thường, chỉ có phim đã được xử lý tại <Blue:Phòng thí nghiệm Ngân Tâm Misage> mới có thể ghi lại hình ảnh của Thể Thức Tỉnh."
  },
  AvgDialog_4871_Content_13 = {
    Text = "Cuộn phim nguyên mẫu độc nhất vô nhị trên tay cậu có lẽ chỉ ghi lại được khoảng 20 phút hình ảnh… Thế nào, quay xong chưa?"
  },
  AvgDialog_4871_Content_14 = {
    Text = "Ừm… có lẽ… còn cần thêm một chút thời gian nữa…… mọi người đang…… lên ý tưởng!"
  },
  AvgDialog_4871_Content_15 = {
    Text = "Cũng phải, dù sao thì việc thử nghiệm hiệu quả máy quay chỉ là nhiệm vụ phụ — vui vẻ mới là điều quan trọng nhất, phải không?"
  },
  AvgDialog_4871_Content_16 = {
    Text = "Vậy thì, chúc các cậu có một kỳ nghỉ tuyệt vời, tôi mong được xem tác phẩm của các cậu."
  },
  AvgDialog_4871_Content_17 = {
    Text = "Ramona ngắt liên lạc, bỏ lại cậu với gương mặt tái nhợt như tro tàn."
  },
  AvgDialog_4871_Content_2 = {
    Text = "Tôi cảm nhận được dao động tinh thần lực, bạn gặp chiến đấu rồi sao? Không bị thương chứ?"
  },
  AvgDialog_4871_Content_3 = {
    Text = "Chỉ gặp vài dị biến thể thôi, mọi người đều ổn."
  },
  AvgDialog_4871_Content_4 = {
    Text = "Vậy thì tốt, mọi thứ vẫn thuận lợi chứ?"
  },
  AvgDialog_4871_Content_5 = {
    Text = "Cũng… thuận lợi."
  },
  AvgDialog_4871_Content_6 = {
    Text = "Bạn đối mặt với mấy gương mặt đầy lo lắng, những khuôn mặt trẻ trung ấy ít nhiều đều lộ rõ sự e sợ đối với \"chủ nhân chiếc máy quay\"."
  },
  AvgDialog_4871_Content_7 = {
    Text = "À đúng rồi, có chuyện muốn hỏi — phim máy quay có đắt không? Oreta rất tò mò."
  },
  AvgDialog_4871_Content_8 = {
    Text = "Oreta cũng không có rất — ừm ừm!"
  },
  AvgDialog_4871_Content_9 = {
    Text = "Không biết từ lúc nào Kassia đã bò xuống từ vai Rotan, bịt miệng Oreta và kéo cô gái ồn ào sang một bên."
  },
  AvgDialog_4872_Content_1 = {
    Text = "Tôi ngửi thấy mùi của Cửa Hàng Trao Đổi rồi, đi hướng này."
