  AvgDialog_4872_Content_4 = {
    Text = "Hai người không phải chó con mà!"
  },
  AvgDialog_4873_Content_1 = {
    Text = "Tôi là người hiểu rõ Daphodel nhất, cô ấy không phải kiểu người hứng thú với những lời nhảm nhí của trẻ con đâu."
  },
  AvgDialog_4873_Content_10 = {
    Text = "Câu chuyện. Cậu không muốn quay câu chuyện của mình sao?"
  },
  AvgDialog_4873_Content_11 = {
    Text = "Nhiệm vụ của tôi là đưa các cậu trở về trường an toàn nguyên vẹn.\nViết kịch bản, quay phim mấy chuyện đó đừng tính tôi vào."
  },
  AvgDialog_4873_Content_13 = {
    Text = "Hình hài của dị biến thể tan biến trong tiếng kiếm rẽ gió, Rotten lau sạch bùn đen trên kiếm, nghiêng đầu mỉm cười với bạn."
  },
  AvgDialog_4873_Content_14 = {
    Text = "Đây mới là việc tôi nên làm."
  },
  AvgDialog_4873_Content_2 = {
    Text = "Chỉ có những cảm xúc mãnh liệt nhất, cực đoan nhất……mới có thể khiến cô ấy lộ ra nụ cười thật sự."
  },
  AvgDialog_4873_Content_3 = {
    Text = "Đó chính là đau khổ! Cô ấy chắc chắn khao khát một câu chuyện chôn sâu nỗi đau, có thể khiến tất cả mọi người đều <Red:đẫm máu>!"
  },
  AvgDialog_4873_Content_4 = {
    Text = "Đằng sau vẻ ngoài thanh nhã như vậy lại là tính cách như thế sao?\nVậy câu chuyện của tôi……có lẽ không lọt vào mắt cô ấy được rồi."
  },
  AvgDialog_4873_Content_5 = {
    Text = "Đừng nghe gia hóc này nói bậy.\nDù Daphodel là người thích xem náo nhiệt, nhưng tính cách không tệ đến mức đó đâu."
