  AvgDialog_4889_Content_18 = {
    Text = "Vì muốn ủng hộ công việc của bạn—— hoặc đơn giản chỉ là muốn nghịch ngợm, dù miệng lẩm bẩm không hài lòng, nhưng cô ấy vẫn rất phối hợp, một lần nữa dựng lên ảo cảnh ma thuật."
