  AvgDialog_4898_Content_28 = {
    Text = "Chủ nhân, chúng ta đi đâu ạ?"
  },
  AvgDialog_4898_Content_29 = {
    Text = "Nhắc đến \"người biết viết lách\"…thì nhất định phải đi gặp người đó."
  },
  AvgDialog_4898_Content_3 = {
    Text = "Câu chuyện… câu chuyện……"
  },
  AvgDialog_4898_Content_30 = {
    Text = "\"Người đó\" ư?"
  },
  AvgDialog_4898_Content_31 = {
    Text = "Một chị gái tài năng xuất chúng. Rotan đã giúp chúng ta liên lạc với chị ấy, đợi tàu chạy đến trạm cuối là có thể gặp được."
  },
  AvgDialog_4898_Content_32 = {
    Text = "Lily ngơ ngác gật đầu, nắm tay bạn và không nói gì thêm."
  },
  AvgDialog_4898_Content_33 = {
    Text = "Đây là lần thứ hai cô bé lên tàu điện ngầm, không còn sự háo hức và tò mò như lần trước, lần này cô bé nhỏ xíu chỉ ngoan ngoãn và cảnh giác bám sát bên bạn. Giống hệt những chú thú nhỏ quyến luyến vòng tay mẹ."
  },
  AvgDialog_4898_Content_4 = {
    Text = "Cô bé cầm bút lẩm bẩm, đầu bút trượt trên mặt giấy phát ra tiếng xoạt xoạt."
  },
  AvgDialog_4898_Content_5 = {
    Text = "Thần thái nghiêm túc, nét bút mạnh mẽ xuyên thấu mặt giấy, chắc chắn đầy sức lực——"
  },
  AvgDialog_4898_Content_6 = {
    Text = "Nhưng thứ hiện ra trên mặt giấy không phải là chữ, mà chỉ là một bức tranh nguệch ngoạc non nớt."
  },
  AvgDialog_4898_Content_7 = {
    Text = "Đây là… Kum và Francis?"
  },
  AvgDialog_4898_Content_8 = {Text = "A…!"},
  AvgDialog_4898_Content_9 = {
    Text = "Chủ, chủ nhân……"
  },
  AvgDialog_4899_Content_1 = {
    Text = "Bạn và Lily gõ cửa một cánh cửa không mấy nổi bật ở góc phố."
  },
  AvgDialog_4899_Content_10 = {
    Text = "Không không không, tiểu thư Aurla hiểu nhầm rồi."
  },
  AvgDialog_4899_Content_11 = {
    Text = "Bạn đến thăm tôi, chẳng phải vì kịch bản sao?"
  },
  AvgDialog_4899_Content_12 = {
    Text = "Đúng, mà cũng không hẳn."
  },
  AvgDialog_4899_Content_13 = {
    Text = "Bạn cúi đầu nhìn Lily gần như bám trên chân bạn, nhẹ nhàng đẩy cô bé ra trước mặt Aurla."
  },
  AvgDialog_4899_Content_14 = {
    Text = "<Italic:Sinh mệnh ngoài dự liệu, nở rộ ngoài thời gian…>"
  },
  AvgDialog_4899_Content_15 = {
    Text = "Xin chào, Lily."
  },
  AvgDialog_4899_Content_16 = {
    Text = "Xin… Xin chào!"
  },
  AvgDialog_4899_Content_17 = {
    Text = "Chúng tôi muốn thỉnh giáo, phương pháp sáng tác câu chuyện ạ."
  },
  AvgDialog_4899_Content_2 = {
    Text = "Đến từ xa, thật thất lễ vì không ra đón sớm…"
  },
  AvgDialog_4899_Content_3 = {
    Text = "Đó là hương thơm hoa hồng mang theo hơi sương sớm, từ khe cửa mở ra tỏa lan khắp nơi, âm thầm và không ngừng chảy tràn."
  },
  AvgDialog_4899_Content_4 = {
    Text = "Lâu rồi không gặp, <Blue:tiểu thư Aurla>."
  },
  AvgDialog_4899_Content_5 = {
    Text = "Chào buổi sáng, Người Giữ Bí Mật."
  },
  AvgDialog_4899_Content_6 = {
    Text = "Vị khách nhỏ này là…?"
  },
  AvgDialog_4899_Content_7 = {
    Text = "Bạn giải thích với nhà thơ một hồi, về việc quay phim, về kịch bản, về Lily…"
  },
  AvgDialog_4899_Content_8 = {
    Text = "Thì ra là vậy, để thử nghiệm máy quay mà tiểu thư Doll đã cải tạo, các bạn cần quay một bộ phim…"
  },
  AvgDialog_4899_Content_9 = {
    Text = "Nhưng có lẽ bạn còn nhớ, tôi chỉ là một nhà thơ nhỏ bé… về việc viết kịch bản phim, tôi còn xa mới đạt đến mức \"đủ tiêu chuẩn\"."
  },
  AvgDialog_4900_Content_1 = {
    Text = "Ảo cảnh huy hoàng nhất"
  },
  AvgDialog_4900_Content_10 = {
    Text = "Nếu không thì sao thì sao?"
  },
  AvgDialog_4900_Content_11 = {
    Text = "Sẽ bị phông nền phim trường thật bên dưới ảo cảnh đâm cho bầm mặt sưng mũi!"
  },
  AvgDialog_4900_Content_12 = {
    Text = "Mấy người, có gặp bà bác sĩ kiêm chuyên gia tâm lý của trường Đại học Misage chưa?"
  },
  AvgDialog_4900_Content_13 = {
    Text = "Đó là đại ma vương nham hiểm, xảo quyệt, tà ác, nghe nói người bị thương đến chỗ bà ấy, cuối cùng đều nằm bẹp ra mà ra."
  },
  AvgDialog_4900_Content_14 = {
    Text = "Đ-đoạn này không quay lại chứ?"
  },
  AvgDialog_4900_Content_15 = {
    Text = "Augier lo lắng bất an nhìn về phía bạn — người đang cầm máy quay, sau khi nhận được câu trả lời khẳng định mới thở phào nhẹ nhõm."
  },
  AvgDialog_4900_Content_16 = {
    Text = "Cô Sylvia đối xử với học sinh bị thương ngoài ý muốn, vẫn rất dịu dàng mà……"
  },
  AvgDialog_4900_Content_17 = {
    Text = "Đã mọi người đều sẵn sàng rồi, vậy thì bắt đầu quay thôi."
  },
  AvgDialog_4900_Content_18 = {
    Text = "Tuyệt vời—— quay phim～quay phim～"
  },
  AvgDialog_4900_Content_19 = {
    Text = "Aureta lại đây! Màn này chúng ta không cần lên sân khấu, ra ngoài ống kính đợi trước đã——"
  },
  AvgDialog_4900_Content_2 = {
    Text = "Các diễn viên nhí, đã sẵn sàng chưa!"
  },
  AvgDialog_4900_Content_20 = {
    Text = "Các Thể Thức Tỉnh tự tìm chỗ trốn ra ngoài ống kính, cậu nhìn lần cuối tờ \"kịch bản\" chỉ vỏn vẹn vài dòng, rồi cũng bước đến vị trí xuất hiện đã định sẵn."
  },
  AvgDialog_4900_Content_3 = {
    Text = "Người giữ bí mật, đã sẵn sàng chưa!"
  },
  AvgDialog_4900_Content_4 = {
    Text = "Đừng chớp mắt, nín thở đi— thôi, bây giờ thở cũng được."
  },
  AvgDialog_4900_Content_5 = {
    Text = "Vì ảo thuật ảo cảnh của Cassia, nhất định sẽ khiến người ta choáng ngợp đến nghẹt thở——!"
  },
  AvgDialog_4900_Content_6 = {
    Text = "Quang cảnh méo mó mờ ảo, sau khoảnh khắc tan vỡ, những mảnh ghép lại thành khung cảnh thực quen thuộc vô cùng với bạn."
  },
  AvgDialog_4900_Content_7 = {
    Text = "Đ-đây là phép thuật gì vậy?!"
  },
  AvgDialog_4900_Content_8 = {
    Text = "Chít, chít chít chít!"
  },
  AvgDialog_4900_Content_9 = {
    Text = "Trông chừng đồng bọn trộm cắp của cậu, ảo thuật ảo cảnh của Cassia chỉ là giả tượng… Hành động cẩn thận ở đây, đừng thật sự bước vào ảo cảnh, nếu không……"
  },
  AvgDialog_4901_Content_1 = {
    Text = "Sự hào phóng của thương nhân"
  },
  AvgDialog_4901_Content_10 = {
    Text = "Hộp đen chứa cuộn phim lăn sang một bên, ánh sáng chiếu vào qua vết nứt bị va ra trên hộp đen."
  },
  AvgDialog_4901_Content_11 = {
    Text = "Doll đã đặc biệt dặn dò, phim không được tiếp xúc với ánh sáng…… Lần này tệ rồi!"
  },
  AvgDialog_4901_Content_12 = {
    Text = "<Shake:Nhiệm vụ lần này của chúng ta là thử nghiệm máy quay mà Doll đã cải tạo mà!>"
  },
  AvgDialog_4901_Content_13 = {
    Text = "Có gì đâu, ra bách hóa mua thêm một cuộn phim nữa là được."
  },
  AvgDialog_4901_Content_14 = {
    Text = "\"Ví tiền của \"Ash\"{Male=ngài,Female=cô} chắc không còn xẹp lép như trước chứ?\""
  },
  AvgDialog_4901_Content_15 = {
    Text = "Bạn sờ chiếc ví tội nghiệp, trong lòng thầm tính ngày phát trợ cấp điều tra tiếp theo…"
  },
  AvgDialog_4901_Content_16 = {
    Text = "Túi không bị thủng rồi chứ? Hay là, để tôi thử đi \"kiếm\" một cuộn phim gì đó về?"
  },
  AvgDialog_4901_Content_17 = {
    Text = "Làm ơn đi, để cho pháp luật còn chút thể diện."
  },
  AvgDialog_4901_Content_18 = {
    Text = "Chúng ta đi đến bách hóa ngay thôi."
  },
  AvgDialog_4901_Content_2 = {
    Text = "Gì vậy?!"
  },
  AvgDialog_4901_Content_3 = {
    Text = "Tch, phiền phức."
  },
  AvgDialog_4901_Content_4 = {
    Text = "Rotan không còn muốn đánh tiếp, quay tay dùng chuôi kiếm đánh ngất Cassia, vừa gọn gàng thu kiếm vừa bước đến bên Lily."
  },
  AvgDialog_4901_Content_5 = {
    Text = "Chiếc máy bị ảnh hưởng trong trận chiến, đổ vào đống đạo cụ phông nền đổ nát."
  },
  AvgDialog_4901_Content_6 = {
    Text = "Cái gì cái gì? Máy bị sao vậy? Mệt rồi à?"
  },
  AvgDialog_4901_Content_7 = {
    Text = "Có thứ gì rơi ra từ bên trong kìa, hỏng rồi sao?"
  },
  AvgDialog_4901_Content_8 = {
    Text = "Cậu đỡ chiếc máy dậy, máy quay trông không có hư hỏng gì khác, chỉ có một bộ phận hình bánh xe bị rơi ra."
  },
  AvgDialog_4901_Content_9 = {
    Text = "Hỏng rồi! Phim!"
  },
  AvgDialog_4902_Content_1 = {
    Text = "Đ-Đứng lại! Đừng chạy nữa!"
  },
  AvgDialog_4902_Content_10 = {
    Text = "Các người là thân nhân của ai? Giờ thăm viện dưỡng đã qua lâu rồi!"
  },
  AvgDialog_4902_Content_11 = {
    Text = "<Small:An ninh do Quỹ Dexter cung cấp thật vô dụng…>\nThôi, các người không thể ở lại đây, tôi sẽ gọi an ninh đưa các người ra ngoài."
  },
  AvgDialog_4902_Content_12 = {
    Text = "Sau sự kiện Chó Địa Ngục, gia tộc Dexter đã hào phóng tài trợ cho Viện dưỡng tâm thần Rye. Ở một khía cạnh nào đó, viện dưỡng này đã trở thành tài sản riêng của Giáo sư."
  },
  AvgDialog_4902_Content_13 = {
    Text = "Tôi là học trò của Huân tước Dexter"
  },
  AvgDialog_4902_Content_14 = {
    Text = "Tôi là học trò của Huân tước ở Londinium. Trên đường du học ngang qua Rai, mong có thể xin nghỉ trọ một đêm tại viện dưỡng."
  },
  AvgDialog_4902_Content_15 = {
    Text = "Học trò của Huân tước? Từ tận Londinium xa xôi tới đây sao?"
  },
  AvgDialog_4902_Content_16 = {
    Text = "Cho dù ngươi thật sự là người quen của Huân tước, tình hình chúng tôi hiện tại, làm sao mà cho người ở trọ được!\nPhiền phức quá… Thôi được, tôi dẫn các ngươi đi gặp người phụ trách."
  },
  AvgDialog_4902_Content_17 = {
    Text = "Tôi là Ramona·Dexter"
  },
  AvgDialog_4902_Content_18 = {Text = "?！"},
  AvgDialog_4902_Content_19 = {
    Text = "Bạn đặt tay lên vai Lily, ra hiệu cho cô ấy đừng hoảng sợ."
  },
  AvgDialog_4902_Content_2 = {
    Text = "Bệnh nhân tầng ba chơi té nước ngoài sân, bệnh nhân tầng một nghịch khoai tây với cà ri trong bếp, tầng hai thì la hét inh ỏi——Trời ơi!!"
  },
  AvgDialog_4902_Content_20 = {
    Text = "Tôi là người thừa kế duy nhất của gia tộc Dexter, việc đến thăm và kiểm tra tài sản dưới tên gia tộc là hoàn toàn chính đáng."
  },
  AvgDialog_4902_Content_21 = {
    Text = "……Tôi từng gặp tiểu thư Dexter tại buổi dạ tiệc, đó là một quý cô có mái tóc bạc rực rỡ."
  },
  AvgDialog_4902_Content_22 = {
    Text = "Ngươi… Thôi được, thôi được.\n<Small:Robert, ngươi phải bình tĩnh, ngươi đã gặp đủ nhiều kẻ điên ở đây rồi, thêm một người nữa cũng chẳng sao.>"
  },
  AvgDialog_4902_Content_23 = {
    Text = "Dù là đến thăm hay nhập viện, đều phải được sự đồng ý của người phụ trách.\nTôi dẫn các ngươi đi gặp bà ấy."
  },
  AvgDialog_4902_Content_3 = {
    Text = "Nghỉ việc! Tôi muốn nghỉ việc!!"
  },
  AvgDialog_4902_Content_4 = {
    Text = "Chuông báo động vang rền, đèn đỏ nhấp nháy. Viện dưỡng tâm thần Rye từ trong ra ngoài loạn thành một nồi cháo, bệnh nhân chạy tán loạn nghịch ngợm, các hộ lý kiệt sức đuổi theo bên ngoài."
  },
  AvgDialog_4902_Content_6 = {
    Text = "Viện dưỡng… Mẹ!"
  },
  AvgDialog_4902_Content_7 = {
    Text = "Lily đừng vội, bình tĩnh đã."
  },
  AvgDialog_4902_Content_8 = {
    Text = "Dù nhân viên y tế trông có vẻ rối bời, nhưng từ hành động có trật tự của họ mà xét, họ chỉ đang than phiền bằng miệng về sự bận rộn và phiền phức của công việc."
  },
  AvgDialog_4902_Content_9 = {
    Text = "Xin chào, xin hỏi viện dưỡng có chuyện gì vậy ạ?"
  },
  AvgDialog_4903_Content_1 = {
    Text = "Những dị biến thể này là sao?"
  },
  AvgDialog_4903_Content_10 = {
    Text = "Mất tích từ lúc nào vậy?!"
  },
  AvgDialog_4903_Content_11 = {
    Text = "Xin đừng lo lắng, đây là nhà của Lily, cô bé sẽ không gặp nguy hiểm.\nChúng ta vừa dọn dẹp những dị biến thể này, vừa đi tìm cô bé nhé."
  },
  AvgDialog_4903_Content_2 = {
    Text = "Ngài còn nhớ nữ chiến binh bị ngài và cô Lortan đánh bại không?"
  },
  AvgDialog_4903_Content_3 = {
    Text = "Giao cô ấy…… cho ta!"
  },
  AvgDialog_4903_Content_4 = {
    Text = "Shilo… người giải phóng đầu tiên của tộc Tiro, bóng ma phục thù."
  },
  AvgDialog_4903_Content_5 = {
    Text = "Đúng vậy.\nTheo nguyện vọng của Viện trưởng Ozwood, người liên kết của cô Shilo là tất cả bệnh nhân trong viện dưỡng lão."
  },
  AvgDialog_4903_Content_6 = {
    Text = "Hành động của cô ấy bên ngoài đã gây ra dị biến trong viện dưỡng lão, trời sáng thường sẽ trở lại bình thường……\nVì sự hỗn loạn một đêm này mà yêu cầu ngài đi truy tìm cô ấy khi tung tích bất minh, thật sự quá miễn cưỡng."
  },
  AvgDialog_4903_Content_7 = {
    Text = "Giữa các thể thức tỉnh đồng nguyên tồn tại cảm ứng yếu ớt, Lily có lẽ có thể cảm nhận được vị trí của Shilo. Nếu tình hình viện dưỡng lão xấu đi hơn nữa, nhất định hãy liên hệ chúng tôi kịp thời."
  },
  AvgDialog_4903_Content_8 = {
    Text = "Cảm ơn lòng tốt của ngài, tôi sẽ làm vậy…… Ơ?"
  },
  AvgDialog_4903_Content_9 = {Text = "Lily?"},
  AvgDialog_4904_Content_1 = {
    Text = "El@1……@4…!"
  },
  AvgDialog_4904_Content_2 = {
    Text = "Bệnh nhân trên giường phát ra tiếng thét đau đớn, âm tiết bị xóa đi một cách đột ngột, thế giới này dường như đang từ chối để anh ta phát ra âm thanh."
  },
  AvgDialog_4904_Content_3 = {
    Text = "Suỵt, suỵt… hãy lắng nghe tiếng nước biển chảy……"
  },
  AvgDialog_4904_Content_4 = {
    Text = "Nymphia nhẹ nhàng an ủi bệnh nhân, dòng nước vô hình quấn quanh người bệnh nhân, chẳng mấy chốc anh ta đã im lặng, yên tĩnh ngả vào lòng Nymphia."
  },
  AvgDialog_4904_Content_5 = {
    Text = "Đây là…"
  },
  AvgDialog_4904_Content_6 = {
    Text = "Nymphia ra hiệu im lặng với bạn, đắp chăn cho bệnh nhân xong mới dẫn các bạn trở lại hành lang."
  },
  AvgDialog_4904_Content_7 = {
    Text = "Xin đừng lo lắng, chỉ là một lượng cực nhỏ độc tố biển, trong quá trình ngủ cơ thể sẽ tự chuyển hóa được."
  },
  AvgDialog_4904_Content_8 = {
    Text = "Tiếp tục đi về phía trước, đi qua hành lang này, có lẽ Lily đang ở sâu bên trong viện dưỡng."
  },
  AvgDialog_4904_Content_9 = {
    Text = "Bạn nhìn con đường quen thuộc mà u tối, gật đầu đồng ý."
  },
  AvgDialog_4905_Content_1 = {
    Text = "Sức mạnh của Andy·Johnson"
  },
  AvgDialog_4905_Content_10 = {
    Text = "Tiếng bước chân nhẹ nhàng vang lên từ một góc phông cảnh, Rotten nhướn mày ra hiệu cho Aurita, cô kia lập tức hiểu ý và chiếu đèn về phía góc đó."
