  AvgDialog_49092_Content_16 = {
    Text = "Bạn muốn nói thêm điều gì đó, nhưng một vật thể mềm mại và mát lạnh đã chặn miệng bạn."
  },
  AvgDialog_49092_Content_17 = {
    Text = "Bạn nhắm mắt lại. Không có sân khấu, không có khán giả. Trong một không gian chiều khác, chỉ có những ngôi sao, chỉ có chúng ta."
  },
  AvgDialog_49092_Content_18 = {
    Text = "Trong ký ức của bạn, đó là màn ảo thuật thành công nhất của Kasia."
  },
  AvgDialog_49092_Content_2 = {
    Text = "Đây là…… đâu vậy?"
  },
  AvgDialog_49092_Content_3 = {
    Text = "Tất nhiên là một không gian chiều khác rồi~ Người giữ bí mật, anh không nhận ra nơi này nữa sao?"
  },
  AvgDialog_49092_Content_4 = {
    Text = "Này, Kassia, tôi phối hợp với bạn thực hiện màn biểu diễn chuyển đổi cơ thể, nhưng không có nghĩa là để bạn đưa tôi đến đây."
  },
  AvgDialog_49092_Content_5 = {
    Text = "Chúng ta vẫn nên trở về sớm, tiếp tục buổi biểu diễn này, giảm bớt ảnh hưởng của sông thiêng liêng đối với bạn…"
  },
  AvgDialog_49092_Content_6 = {
    Text = "Biểu diễn không phải đang tiếp tục sao? Bạn đã hứa sẽ phối hợp với tôi để biểu diễn ảo thuật, giờ không được đổi ý đâu nha."
  },
  AvgDialog_49092_Content_7 = {
    Text = "Nhưng mà những khán giả vẫn đang chờ đợi.."
  },
  AvgDialog_49092_Content_8 = {
    Text = "Sự biểu diễn ảo thuật cho khán giả đã kết thúc. Cuộc biểu diễn này dành tặng cho Người Giữ Gìn."
  },
  AvgDialog_49092_Content_9 = {
    Text = "Kassia đặt hai tay sau lưng, đầu hơi nghiêng, nhảy đến trước mặt bạn."
  },
  AvgDialog_49093_Content_10 = {
    Text = "Thổi ra là được rồi?"
  },
  AvgDialog_49093_Content_11 = {
    Text = "Hô———"
  },
  AvgDialog_49093_Content_12 = {Text = "?"},
  AvgDialog_49093_Content_13 = {
    Text = "Không đau nữa, bụi có lẽ đã bị thổi đi. chúng ta tiếp tục."
  },
  AvgDialog_49093_Content_14 = {
    Text = "Không, hôm nay đến đây thôi."
  },
  AvgDialog_49093_Content_15 = {
    Text = "Dừng huấn luyện chiến đấu trước khi bạn hết hứng thú? Điều này không giống phong cách bình thường của bạn…"
  },
  AvgDialog_49093_Content_16 = {
    Text = "Ha... nhờ có Tholm Vahi, hiện tại bạn không thể khiến tôi \"hết mình\"được nữa."
  },
  AvgDialog_49093_Content_17 = {
    Text = "Lọn tóc mai trên trán bị hất lên, linh hồn nặng nề đặt một nụ hôn đầy quyền uy lên góc trán."
  },
  AvgDialog_49093_Content_18 = {Text = "Lơ-tan?!"},
  AvgDialog_49093_Content_19 = {
    Text = "Lơ-tan vỗ nhẹ vào mặt bạn rồi nhanh chóng kéo bạn dậy từ mặt đất lạnh giá."
  },
  AvgDialog_49093_Content_2 = {
    Text = "Không đủ, vẫn chưa đủ!"
  },
  AvgDialog_49093_Content_20 = {
    Text = "Trong trạng thái tỉnh táo, những dục vọng hỗn loạn không thể kiểm soát tôi. \nĐừng quên, tôi là sáng tạo từ thời cổ đại."
  },
  AvgDialog_49093_Content_21 = {
    Text = "Bây giờ, về đi. Cậu nhóc."
  },
  AvgDialog_49093_Content_3 = {
    Text = "Đây chính là thực lực của cậu sao? Một năm huấn luyện, cộng thêm nhiều lần nhiệm vụ rèn luyện…"
  },
  AvgDialog_49093_Content_4 = {
    Text = "Các đòn tấn công rơi xuống như mưa rào, làm nứt vỡ các viên gạch trên sân tập."
  },
  AvgDialog_49093_Content_5 = {
    Text = "Bụi đất bay vào mắt, cảm giác có vật lạ khiến bạn không thể kiểm soát và nhắm mắt lại."
  },
  AvgDialog_49093_Content_6 = {
    Text = "Lơ-tan! Dừng lại một chút, tôi——"
  },
  AvgDialog_49093_Content_7 = {
    Text = "Người võ sĩ mạnh mẽ tách mi mắt trên và dưới của bạn ra, sợi vải của găng tay ma sát trên làn da nhạy cảm và mong manh, khiến bạn không thể kiềm chế được việc chớp mắt liên tục."
  },
  AvgDialog_49093_Content_8 = {
    Text = "Đừng cử động."
  },
  AvgDialog_49093_Content_9 = {
    Text = "Lơ-tan quyết định buông vũ khí, dùng một tay cố định đầu bạn, khiến thân thể bạn không thể lùi lại theo bản năng."
  },
  AvgDialog_49094_Content_1 = {
    Text = "Bu lông, thanh sắt… Đúng rồi, giống như khi sửa khung xe máy vậy."
  },
  AvgDialog_49094_Content_2 = {
    Text = "Ơ? Không hỏng à, vậy tại sao thằng đó lại bảo tôi đến phòng bệnh nhỉ? Chẳng lẽ cái giường hỏng không phải là cái này sao?"
  },
  AvgDialog_49094_Content_3 = {
    Text = "Cô gái nhíu mày ngẩng đầu lên, đôi tay bẩn dầu mỡ cho thấy cô đã hoàn thành một lần sửa chữa lớn trong phòng bệnh một cách hoàn hảo."
  },
  AvgDialog_49094_Content_4 = {
    Text = "Hị... hị hị……"
  },
  AvgDialog_49094_Content_5 = {
    Text = "Người này có hơi của tôi…"
  },
  AvgDialog_49094_Content_6 = {
    Text = "Nốtira cúi xuống nhìn học sinh ngủ sâu trên giường bệnh, lâm vào trầm ngâm."
  },
  AvgDialog_49094_Content_7 = {
    Text = "%hisorher% góc môi và khuôn mặt đều có một vết bẩn đen đậm rõ ràng, Nốtira nhìn một cái là biết đó là dấu vết của dầu máy đặc chế."
  },
  AvgDialog_49094_Content_8 = {
    Text = "Ừm... tôi chắc chắn đã biết {Male=anh ấy,Female=cô ấy}, %hisorher% tên là……"
  },
  AvgDialog_49094_Content_9 = {
    Text = "%player%……đúng vậy, %player%."
  },
  AvgDialog_49095_Content_1 = {
    Text = "Bạn đang chìm sâu hơn vào trong giấc mơ."
  },
  AvgDialog_49095_Content_10 = {
    Text = "Dừng thở, tôi sẽ đưa bạn trở lại thực tại."
  },
  AvgDialog_49095_Content_11 = {
    Text = "Tulô?! Khục, khụ…"
  },
  AvgDialog_49095_Content_12 = {
    Text = "Sự xuất hiện của thân thể được đánh thức đã giúp làm rõ một số tình hình. Bạn vội vàng gọi tên anh ấy, nhưng những ý tưởng kỳ lạ bỗng chốc tuôn trào, tràn ngập đường hô hấp."
  },
  AvgDialog_49095_Content_13 = {
    Text = "...Dư vừa nói, ngừng thở."
  },
  AvgDialog_49095_Content_14 = {
    Text = "Vài giây sau, xúc tu căng tròn và lạnh lẽo mạnh mẽ chui vào miệng, đẩy những ký ức hỗn loạn sang một bên, xua đuổi những âm thanh vô nghĩa hiện tại."
  },
  AvgDialog_49095_Content_15 = {
    Text = "Gió mùa thực sự thổi vào mặt, thân thể dần thả lỏng trong cơn mệt mỏi tột độ, như thể sắp chìm vào giấc ngủ sâu không mơ…"
  },
  AvgDialog_49095_Content_16 = {
    Text = "Mới vừa thoát chết từ giấc mơ của Dư, mà vẫn còn dám lập tức ngủ? Dũng khí này, thật khiến Dư phải nhìn lại."
  },
  AvgDialog_49095_Content_17 = {
    Text = "Tulô, tulô,…"
  },
  AvgDialog_49095_Content_18 = {
    Text = "Bạn vừa nói, đó là giấc mơ của bạn?"
  },
  AvgDialog_49095_Content_19 = {
    Text = "Thân thể được đánh thức quay mặt đi với vẻ ngại ngùng."
  },
  AvgDialog_49095_Content_2 = {
    Text = "Dòng lũ bất ngờ đánh sập những cây cột của giấc mơ, biên giới giữa giấc mơ và thực tại ngập tràn trong tiếng thét, rồi biến thành vô số tảng đá tối ẩm ướt."
  },
  AvgDialog_49095_Content_20 = {
    Text = "\"Khi ta ngủ, giấc mơ tràn ra sẽ khiến linh hồn sôi sục\"… Sự bất thường của thân thể ta đã cuốn bạn vào trong giấc mơ, đây là lỗi của ta."
  },
  AvgDialog_49095_Content_21 = {
    Text = "Loại cảm giác kỳ lạ này đã khiến giấc mơ của Dư vô thức xâm phạm giấc mơ của ngươi... Nếu điều này khiến ngươi cảm thấy khó chịu, Dư hoàn toàn có thể hiểu được cảm xúc của ngươi."
  },
  AvgDialog_49095_Content_22 = {
    Text = "Củ cải, nỗi lo lắng nhỏ? Làm sao có thể, bạn vô tình mà. Hơn nữa, khi tôi sắp bị tiếng nói của Lemuria nhấn chìm, bạn không phải đã kịp thời đến sao?"
  },
  AvgDialog_49095_Content_23 = {Text = "Bạn…"},
  AvgDialog_49095_Content_24 = {
    Text = "Sau khi trở lại trường, ta sẽ lập tức đến hồ đen, có lẽ môi trường ở đó có thể tạm thời áp chế dị thường trong cơ thể ta… điều này khiến ta không khỏi lo lắng."
  },
  AvgDialog_49095_Content_25 = {
    Text = "Anh ta khẽ thu mình vào một góc của khoang xe, ánh mắt liếc qua cửa sổ nhìn ra bóng đêm sâu thẳm."
  },
  AvgDialog_49095_Content_26 = {
    Text = "Nhưng góc nhìn thoáng qua thường xuyên rơi trên khóe miệng của bạn, dường như không phải là vô tình."
  },
  AvgDialog_49095_Content_3 = {
    Text = "Đây không phải là giấc mơ của tôi……Đây không phải của tôi"
  },
  AvgDialog_49095_Content_4 = {
    Text = "Bạn thì thầm muốn tỉnh lại. Phế nang đầy nước của bạn phình lên như bụng của một bệnh nhân cuối đời, thân thể bạn đang thích nghi với đại dương bị lãng quên."
  },
  AvgDialog_49095_Content_5 = {
    Text = "Nhưng dòng nước lẽ ra không nghe thấy được đã kéo bạn quay ngược lại."
  },
  AvgDialog_49095_Content_6 = {
    Text = "Nhạc, tranh vẽ, câu chuyện viết bằng ký tự bí ẩn, hàng loạt ý tưởng kỳ quái ùa vào giấc mơ của bạn trong khoảnh khắc quay đầu."
  },
  AvgDialog_49095_Content_7 = {
    Text = "Bạn muốn mở miệng, chỉ có thể thốt ra những âm tiết lộn xộn vô nghĩa——nhưng chúng thực sự có ý nghĩa."
  },
  AvgDialog_49095_Content_8 = {
    Text = "Chúng thực sự có ý nghĩa, trong thời gian xa xưa, chúng từng là——"
  },
  AvgDialog_49095_Content_9 = {
    Text = "Đừng nuốt nước ở đây nữa."
  },
  AvgDialog_49261_Content_1 = {
    Text = "Đầu tôi đau quá… Tôi cảm thấy không ổn lắm……"
  },
  AvgDialog_49261_Content_10 = {
    Text = "<Small:ư… tôi biết mà, một kẻ như tôi chỉ là con chuột chui rúc trong bóng tối của chiếc áo đen không ai để ý, giọt sương sẽ biến mất khi trời quang…>"
  },
  AvgDialog_49261_Content_11 = {
    Text = "Cô Mason, cô Mason!"
  },
  AvgDialog_49261_Content_12 = {
    Text = "Bạn nắm lấy vai cô ấy và lắc lắc, cố gắng giúp cô ấy thoát khỏi sự nghi ngờ bản thân không có hồi kết."
  },
  AvgDialog_49261_Content_13 = {
    Text = "Không ai từ chối tiếp nhận bạn, bạn là một thành viên của chúng tôi."
  },
  AvgDialog_49261_Content_14 = {
    Text = "Không ai từ chối đón nhận tôi.."
  },
  AvgDialog_49261_Content_15 = {
    Text = "Cô ấy đột nhiên ngẩng đầu nhìn bạn, khóe miệng cong lên thành một nét cong méo mó."
  },
  AvgDialog_49261_Content_16 = {
    Text = "Đúng vậy, trở thành một phần của tôi, hãy cùng nhau tạo ra \"24\" mới!"
  },
  AvgDialog_49261_Content_17 = {
    Text = "Vai cô ấy nứt ra một vết nứt ghê rợn, nhưng bên trong không có cơ bắp hay xương trắng. Một khối màu xám nhạt rung động và phình lên dưới làn da, giống như một vũ trụ đang hình thành."
  },
  AvgDialog_49261_Content_18 = {
    Text = "Dịch nhầy co giật bò ra khỏi khe nứt, chúng quấn quanh ngón tay bạn, cảm giác ẩm ướt và mềm mại đó ngay lập tức đưa bạn trở lại khoảnh khắc tỉnh dậy từ cơn ngủ mê."
  },
  AvgDialog_49261_Content_19 = {
    Text = "\"24\" còng kinh tán loạn, cô ấy khao khát được hòa mình với bạn, hướng đến kết thúc như một phần không thể thiếu."
  },
  AvgDialog_49261_Content_2 = {
    Text = "Dưới lưng là chiếc giường mềm mại quen thuộc, cơn đau sau gáy vẫn quen thuộc với bạn."
  },
  AvgDialog_49261_Content_20 = {
    Text = "Dù bạn là nhân cách mới nào của cô Mason… hãy tỉnh táo lại ngay!"
  },
  AvgDialog_49261_Content_21 = {
    Text = "Bạn cố gắng với tay để chạm vào chìa khóa bạc treo trước ngực, nhưng tay vừa di chuyển một chút thì đã bị một lực vô cùng mạnh mẽ bắt giữ."
  },
  AvgDialog_49261_Content_22 = {
    Text = "Tại sao phải phản kháng? Không phải nói sẽ hoàn toàn đón nhận tôi sao? \"người đó\" quý trọng bạn như vậy, cô ấy chắc chắn cũng rất khao khát..."
  },
  AvgDialog_49261_Content_23 = {
    Text = "Khi đôi môi lạnh lẽo chạm vào khóe miệng của bạn, bạn nhận thấy rằng đôi mắt của cô ấy đã bị sự điên rồ hoàn toàn xâm chiếm — cô ấy không còn là \"Mason\" mà bạn từng quen."
  },
  AvgDialog_49261_Content_24 = {Text = "Ugh!"},
  AvgDialog_49261_Content_25 = {
    Text = "\"24\" toàn thân run rẩy, cổ họng phát ra tiếng thở hổn hển như chiếc hộp gió hỏng. Cô ta buông lỏng sự kiềm chế đối với bạn, bắt đầu cào xé cổ mình."
  },
  AvgDialog_49261_Content_26 = {
    Text = "Tại sao lại! Tại sao lại là ngươi đến chủ đạo——"
  },
  AvgDialog_49261_Content_27 = {
    Text = "Không, đừng, đừng đừng đừng——"
  },
  AvgDialog_49261_Content_28 = {
    Text = "\"24\" phát ra một tiếng thét dài, bốn chi gập lại, mềm mại buông thõng trên vai, cuối cùng cô cúi đầu, chìm vào sự tĩnh lặng."
  },
  AvgDialog_49261_Content_29 = {
    Text = "Mai, cô Mason? Đó là cô sao?"
  },
  AvgDialog_49261_Content_3 = {
    Text = "Bạn dùng hai tay chống lên giường cố gắng đứng dậy, nhưng lại bị mắc kẹt trong một khối tổ chức ẩm ướt và trơn mềm."
  },
  AvgDialog_49261_Content_30 = {
    Text = "Người giữ bí mật! Thật sự, thật sự xin lỗi… Không biết vì sao, nhân cách mới đột nhiên xuất hiện của tôi lại có một số cảm xúc bất thường đối với ngài…"
  },
  AvgDialog_49261_Content_31 = {
    Text = "Mason hoảng loạn vung vẩy hai cánh tay trật khớp của cô, trông như hai túi bột mềm oặt trên vai."
  },
  AvgDialog_49261_Content_32 = {
    Text = "Không cần phải xin lỗi tôi, bạn chỉ do dòng sông thiêng liêng tác động."
  },
  AvgDialog_49261_Content_33 = {
    Text = "Bạn nâng đỡ tay cô ấy —— tay phần con người của cô ấy, nhẹ nhàng đưa khớp xương bị sai vị trí trở về đúng vị trí."
  },
  AvgDialog_49261_Content_34 = {
    Text = "Thật sự làm phiền bạn rồi…"
  },
  AvgDialog_49261_Content_35 = {
    Text = "Giọng cô nhỏ như tiếng muỗi kêu, nhưng trong giọng điệu dường như có một tia vui mừng lóe lên."
  },
  AvgDialog_49261_Content_4 = {
    Text = "Người giữ bí mật, Người Giữ Gìn…"
  },
  AvgDialog_49261_Content_5 = {
    Text = "Thấy bạn tỉnh lại, người phụ nữ trẻ tuổi mặt đầy ngượng ngùng, thốt lên giọng nói dịu dàng và e thẹn mà bạn chưa từng nghe từ miệng cô ấy."
  },
  AvgDialog_49261_Content_6 = {
    Text = "Mai, cô Mason?!"
  },
  AvgDialog_49261_Content_7 = {
    Text = "\"Mason\" nằm nghiêng bên kia giường, đầu ngón tay đen của cô ấy đặt trên ngực bạn. Đôi tay trông có vẻ yếu ớt, nhưng lại giữ bạn chặt trên giường."
  },
  AvgDialog_49261_Content_8 = {
    Text = "Đừng đi… tại sao phải đi chứ?"
  },
  AvgDialog_49261_Content_9 = {
    Text = "Hay là những lời đường mật mà \"24\" nói đều là ảo giác của tôi khi tinh thần không ổn định?"
  },
  AvgDialog_49398_Content_1 = {
    Text = "Bão táp càng giận dữ, binh sĩ A-lan khóc lóc, điên cuồng, kêu la lớn, cầu xin, nguyền rủa."
  },
  AvgDialog_49398_Content_10 = {
    Text = "Vô số người Aran quay mặt về hướng Thái Di Sơ đang ở, quỳ gối trang nghiêm và thành kính."
  },
  AvgDialog_49398_Content_11 = {
    Text = "Linh hồn cát điên cuồng dần dịu đi cơn giận dưới sự an ủi của lời cầu nguyện, cơn bão dần dần bình lặng."
