  },
  AvgDialog_49398_Content_6 = {
    Text = "Tiếng gầm rền vang động dữ dội, nhưng tiếng đọc kinh vẫn rõ ràng đến lạ thường, như thể vang vọng trong đầu bạn."
  },
  AvgDialog_49398_Content_7 = {
    Text = "Trong cơn cuồng phong nuốt trọn đất trời, cô ấy như đang bình thản trò chuyện với một sinh linh nào đó sống trong sa mạc."
  },
  AvgDialog_49398_Content_8 = {
    Text = "Là nữ hoàng! Nữ hoàng đến cứu chúng ta, cứu Á Lan!"
