  },
  AvgDialog_49399_Content_12 = {
    Text = "Đó là bức màn xám bao trùm cả đất trời, cuồn cuộn kéo đến dưới hình thái che phủ bầu trời."
  },
  AvgDialog_49399_Content_13 = {
    Text = "Nó lẽ ra là dòng thủy triều, nhưng không hẳn là dòng thủy triều. Nó to lớn và tĩnh lặng, đang tiến về phía trước nhưng dường như bất động."
  },
  AvgDialog_49399_Content_14 = {
