  },
  AvgDialog_49402_Content_81 = {
    Text = "Cô ấy kéo tay bạn, hướng dẫn ngón tay bạn chạm vào viên ngọc trắng như thể có nhịp đập của sự sống."
  },
  AvgDialog_49402_Content_82 = {
    Text = "Sao băng rơi từ bầu trời xa xôi. \n Đôi mắt của cô ấy rực rỡ hơn cả những vì sao."
  },
  AvgDialog_49402_Content_84 = {
    Text = "Cô ấy hé môi, làn gió đêm mang theo lời thì thầm êm đềm của cô."
  },
  AvgDialog_49402_Content_85 = {
    Text = "Tôi có thể tin tưởng giao họ cho bạn không?"
  },
  AvgDialog_49402_Content_86 = {
    Text = "Cảm giác cuốn hút tương tự như đêm tiệc bên đống lửa đã lôi kéo bạn, gần như không kiềm chế được, bạn lẩm bẩm."
  },
  AvgDialog_49402_Content_87 = {
    Text = "Có thể, chắc chắn có thể."
  },
  AvgDialog_49402_Content_88 = {
    Text = "Thế thì tốt."
  },
  AvgDialog_49402_Content_89 = {
    Text = "Thái Di Sơ cười."
  },
  AvgDialog_49402_Content_9 = {
    Text = "Cuối cùng là ai đang lan truyền Nubia?"
  },
  AvgDialog_49402_Content_90 = {
    Text = "Bạn bè của bạn đã đến."
  },
  AvgDialog_49402_Content_91 = {
    Text = "Bạn theo ánh mắt của Thái Di Sơ, Ramona đang chạy nhanh về phía bạn, Lắc theo sau cô ấy, bước chân nhanh nhẹn nhưng vẫn vững chắc và đầy phong thái."
  },
  AvgDialog_49402_Content_92 = {
    Text = "Đừng quên, đêm nay là bí mật dành riêng cho chúng ta."
  },
  AvgDialog_49402_Content_93 = {
    Text = "Lại quay người nhìn, hình bóng của Thái Diễm Sơ đã biến mất, chỉ còn lại tiếng gió rít gào xuyên qua sa mạc."
  },
  AvgDialog_49402_Content_94 = {
    Text = "Trên cát trước mặt bạn, một vệt rỗng rỗng dung dịch đen chảy vào cát, hòa làm một với mặt đất."
  },
  AvgDialog_49414_Content_1 = {
    Text = "Người giữ bí mật, chức năng truy mơ đã được kích hoạt. Nếu cần sử dụng, hãy nhấn vào thiết bị liên lạc, sau khi nghe tiếng píp, gọi Erika để tiến hành hồi suyệt."
  },
  AvgDialog_49414_Content_2 = {
    Text = "Truy mơ… Đây là gì?"
  },
  AvgDialog_49414_Content_3 = {
    Text = "Đây là nơi lưu trữ bản ghi ký ức của bạn, thông qua chức năng truy mơ, bạn có thể dễ dàng hơn trong việc hồi tưởng lại những trải nghiệm trong các sự kiện điều tra."
  },
  AvgDialog_49414_Content_4 = {
    Text = "Hãy chú tâm đến những chi tiết mà bạn từng lơ là, bởi con người luôn cần rút ra bài học từ quá khứ để đối mặt với tương lai."
  },
  AvgDialog_49440_Content_1 = {
    Text = "(hổn hển, hổn hển...)"
  },
  AvgDialog_49440_Content_2 = {
    Text = "Gia Lân…? Bạn đang làm gì vậy?"
  },
  AvgDialog_49440_Content_3 = {
    Text = "Bạn đang ở trong bóng tối hoàn toàn. Một thứ gì đó đã che mắt bạn."
  },
  AvgDialog_49440_Content_4 = {
    Text = "Bạn thử nâng hai tay lên, nhưng những dải vải mềm đã khóa chặt cổ tay bạn, khiến bạn chỉ có thể di chuyển trong phạm vi rất nhỏ."
  },
  AvgDialog_49440_Content_5 = {
    Text = "Còn cần phải hỏi sao? Tất nhiên là… dọn dẹp lớn rồi đấy!"
  },
  AvgDialog_49440_Content_6 = {
    Text = "Tại sao phải trói tôi khi dọn dẹp lớn?"
  },
  AvgDialog_49440_Content_7 = {
    Text = "Bạn cảm thấy một dự cảm không lành. Những hành động của cô hầu gái nhỏ luôn xuất hiện bất ngờ, dưới ảnh hưởng của sông thiêng liêng, hoàn toàn nằm ngoài dự đoán của bạn."
  },
  AvgDialog_49440_Content_8 = {
    Text = "Đại——sweep——thoroughly khóa là phải triệt để!Người Giữ Gìn cũng là một phần của việc dọn dẹp lớn!"
  },
  AvgDialog_49440_Content_9 = {
    Text = "Đây, đó… mọi nơi đều phải được quét sạch sẽ thôi nhé~"
  },
  AvgDialog_49441_Content_1 = {
    Text = "Erika, bạn có thể tìm thấy thư số A-617 ở giá sách nào không?"
  },
  AvgDialog_49441_Content_10 = {Text = "Ai——"},
  AvgDialog_49441_Content_11 = {
    Text = "Giọng của bạn bị dòng điện yếu ớt như thể sắp tan biến đẩy trở lại trong bụng, cảm giác tại nơi hai tay nắm chặt mang đến một sức mạnh kinh ngạc mà người bình thường không thể chịu đựng."
  },
  AvgDialog_49441_Content_12 = {
    Text = "Dòng điện ngắn ngủi nhưng chói lọi đã đánh thức mọi giác quan trong bạn, sự liên kết vượt ngoài lẽ thường khiến máu chảy rạo rực với những khát khao khó lòng diễn tả."
  },
  AvgDialog_49441_Content_14 = {
    Text = "Erika nháy mắt, rút tay lại."
  },
  AvgDialog_49441_Content_15 = {
    Text = "Được. Bản ghi thư A-617 nằm trong khu vực cấm của kho dữ liệu, đang hướng dẫn Người Giữ Gìn."
  },
  AvgDialog_49441_Content_16 = {
    Text = "Erika nói xong, cô ấy không quay đầu lại và bước thẳng vào khu cấm, để lại phía sau một bóng dáng đầy mạnh mẽ và quyết đoán."
  },
  AvgDialog_49441_Content_17 = {
    Text = "……búp bê tự động sẽ không bị ảnh hưởng bởi dị biến của sông thiêng liêng?"
  },
  AvgDialog_49441_Content_18 = {
    Text = "Đúng rồi?"
  },
  AvgDialog_49441_Content_3 = {Text = "Erica?"},
  AvgDialog_49441_Content_4 = {
    Text = "Người máy đứng sững ở góc phòng, trên khuôn mặt vẫn mang nụ cười quen thuộc, tuy nhiên sự im lặng này khiến nụ cười của nó càng trở nên đáng sợ hơn."
  },
  AvgDialog_49441_Content_5 = {
    Text = "Bạn đưa tay ra trước mắt cô ấy và lắc hai lần, nhưng đôi con ngươi đó vẫn không có dấu hiệu di chuyển."
  },
  AvgDialog_49441_Content_6 = {
    Text = "Lạ thật, Erika chưa bao giờ mất tập trung… Có lẽ có vấn đề với cơ thể máy móc?"
  },
  AvgDialog_49441_Content_7 = {
    Text = "Bạn lẩm bẩm một cách tự nhủ, vừa đi vòng quanh xác thân của Erika."
  },
  AvgDialog_49441_Content_8 = {
    Text = "—— pì pā."
  },
  AvgDialog_49441_Content_9 = {
    Text = "Tiếng nổ nhỏ thu hút sự chú ý của bạn, bạn vô thức nhìn về nguồn âm thanh, nhưng bị ai đó bất ngờ nắm chặt lấy tay."
  },
  AvgDialog_49442_Content_1 = {Text = "Mơ"},
  AvgDialog_49442_Content_10 = {Text = "Xoà——"},
  AvgDialog_49442_Content_11 = {
    Text = "Thế giới lại có âm thanh và màu sắc."
  },
  AvgDialog_49442_Content_12 = {
    Text = "Họ nối tiếp nhau, không do dự nhảy vào dòng nước cuồn cuộn của sông thiêng liêng, dồn hết sức dang rộng đôi tay, ôm lấy thân cây mẹ đã khô héo."
  },
  AvgDialog_49442_Content_13 = {
    Text = "Họ khóc lóc cuồng nhiệt, phát ra những tiếng gào thét điên rồ không thể gọi thành tên."
  },
  AvgDialog_49442_Content_14 = {
    Text = "Da của họ trở nên lỏng lẻo, như thể bùn nhão chảy ra; dịch thể trong cơ thể họ bị rút đi, hòa vào dòng nước cuồn cuộn của sông thiêng liêng."
  },
  AvgDialog_49442_Content_15 = {
    Text = "Xương cốt của họ mềm hóa như da thịt, các chi uốn cong, kéo dài và bị cuốn vào theo cách phi nhân tính. Từ chính thịt máu của mình, họ tạo thành những nhánh cây to lớn, phình đại của cây thánh."
  },
  AvgDialog_49442_Content_16 = {
    Text = "Họ từ từ và đau đớn hòa làm một với cây Thánh."
  },
  AvgDialog_49442_Content_2 = {
    Text = "Cuối cùng cũng chỉ là một con rối không hoàn hảo, vẫn cần tiêu thụ quá nhiều sức lực để điều khiển."
  },
  AvgDialog_49442_Content_3 = {
    Text = "Sự quyết tâm của bạn dành cho Aran càng mạnh mẽ bao nhiêu, thì sự phản kháng sau khi nhận ra sự thật sẽ càng mãnh liệt và sâu sắc bấy nhiêu."
  },
  AvgDialog_49442_Content_4 = {
    Text = "May mắn thay, tôi đã dự đoán trước tình huống này rồi."
  },
  AvgDialog_49442_Content_5 = {
    Text = "Thời gian đã đến, tất cả các ngươi, vì cây mẹ mà các ngươi yêu quý nhất……"
  },
  AvgDialog_49442_Content_6 = {
    Text = "Hãy dâng hiến thịt máu và sinh lực của mình."
  },
  AvgDialog_49442_Content_7 = {
    Text = "Tôi mở miệng, kinh ngạc phát hiện mình không thể phát ra âm thanh. \nMọi thứ xung quanh rơi vào sự tĩnh lặng đáng sợ."
  },
  AvgDialog_49442_Content_8 = {
    Text = "Không, điều dừng lại không phải là thế giới, mà là nhận thức của tôi, mỗi cái chớp mắt nhẹ đều như thể đã qua một thế kỷ."
  },
  AvgDialog_49442_Content_9 = {
    Text = "Trong chuỗi dài lê thê, chỉ có những người đồng đội cũ của tôi, các binh sĩ Aran liên tục, ồ ạt lao về phía sông thiêng liêng."
  },
  AvgDialog_49443_Content_1 = {
    Text = "Dưới gốc cây mẹ, Elva yếu ớt quỳ khóc."
  },
  AvgDialog_49443_Content_10 = {
    Text = "Cũng may bạn đã đi theo, nếu không thì mỗi phút quay lại đón bạn, sẽ tiêu thụ không biết bao nhiêu sức sống."
  },
  AvgDialog_49443_Content_11 = {
    Text = "Giọng nói trong đầu tôi… cô ấy bảo tôi… tôi phải kiên trì…"
  },
  AvgDialog_49443_Content_12 = {
    Text = "Tuy nhiên, ngay cả khi cô ấy không nói… \nTôi cũng là trợ lý duy nhất của %player%, khi nguy hiểm nhất, tôi phải ở cạnh {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_49443_Content_13 = {
    Text = "Đây là trách nhiệm của tôi với tư cách là trợ lý duy nhất, đúng không?"
  },
  AvgDialog_49443_Content_14 = {
    Text = "Cô ấy nhấn mạnh hai chữ \"duy nhất\"."
  },
  AvgDialog_49443_Content_15 = {
    Text = "Trên mảnh đất này, khi đánh thức lực lượng của cô ấy, ảnh hưởng lên cơ thể bạn sẽ ngày càng dữ dội hơn."
  },
  AvgDialog_49443_Content_16 = {
    Text = "Nếu còn cách khác, tôi cũng không muốn phải dùng đến biện pháp hạ sách này."
  },
  AvgDialog_49443_Content_17 = {
    Text = "Misaque đã đến đây để ngăn chặn nghi lễ, tôi là một thành viên của Misaque, sẵn sàng hy sinh tất cả!"
  },
  AvgDialog_49443_Content_18 = {
    Text = "Good! Ramona suppresses the desire essence. %player%, you and I together will completely defeat the Mother Tree!"
  },
  AvgDialog_49443_Content_19 = {
    Text = "Trong không trung vang lên tiếng rít chói tai, bóng dáng bạc mờ ảo cắt qua bầu trời sa mạc."
  },
  AvgDialog_49443_Content_2 = {
    Text = "Tôi dùng thân cây mẹ ẩn mình trong sông thiêng liêng, bằng thân xác chịu đựng rỗng rỗng để giấu hạt giống của cây mẹ, chẳng phải chính là để chờ đợi thời khắc này sao?"
  },
  AvgDialog_49443_Content_21 = {
    Text = "Bạn cảm thấy thân thể nhẹ bẫng, và trong giây tiếp theo đã rơi xuống trước một khối u bẩn và hôi thối."
  },
  AvgDialog_49443_Content_22 = {
    Text = "Người Aran bị cây mẹ nuốt chửng tích tụ ở đây dưới dạng trứng, trong những lỗ hổng bán trong suốt, vô số khuôn mặt méo mó và mờ ảo, chỉ có chất lỏng màu đỏ đen chảy ra không ngừng từ các lỗ hổng, đổ vào dòng sông thiêng liêng không còn trong lành."
  },
  AvgDialog_49443_Content_3 = {
    Text = "Giờ khắc quyết chiến đã đến!"
  },
  AvgDialog_49443_Content_4 = {
    Text = "Tôi nhân danh Tifra Yesod, Thể Chất của ham muốn, đề nghị <Yellow:Tà Vy> hãy đáp lại lời hứa từ ngàn năm trước ——"
  },
  AvgDialog_49443_Content_5 = {
    Text = "Khi sứ giả từ phương xa đến, hãy để hóa thân của bạn dẫn lối, tạm thời xua tan bóng tối phủ Lemvahi."
  },
  AvgDialog_49443_Content_6 = {
    Text = "Trong bầu trời vang lên tiếng kêu bi thảm và vang dội."
  },
  AvgDialog_49443_Content_7 = {
    Text = "Thái Di Sơ mở quan tài, người lật mình ra chính là Ramona bị cháy đỏ bừng mặt."
  },
  AvgDialog_49443_Content_8 = {
    Text = "Cuối cùng…… cần tôi rồi chăng……"
  },
  AvgDialog_49443_Content_9 = {
    Text = "Trốn ở đây và theo sau, cũng thật khéo nghĩ ra, cô gái nhỏ."
  },
  AvgDialog_49476_Content_1 = {
    Text = "Cánh cửa mở nhẹ, ánh đèn hiện lên một bóng dáng quen thuộc."
  },
  AvgDialog_49476_Content_10 = {
    Text = "Xem ra ảnh hưởng của sông thiêng liêng đã lan đến chiều không gian nơi bạn đang ở… Bạn có ổn không?"
  },
  AvgDialog_49476_Content_11 = {
    Text = "Có thể ở bên tôi không, Người Giữ Gìn,"
  },
  AvgDialog_49476_Content_12 = {
    Text = "Tất nhiên. Chỉ là, tôi không biết phải làm sao để giúp bạn……"
  },
  AvgDialog_49476_Content_13 = {
    Text = "Tôi muốn đưa bạn đến một nơi."
  },
  AvgDialog_49476_Content_14 = {Text = "Đâu?"},
  AvgDialog_49476_Content_15 = {
    Text = "Ramona ngồi bên cạnh bạn. Vẻ đỏ ửng tự nhiên hòa quyện dưới ánh đèn và làn da trắng mịn, khiến nhịp thở của bạn như ngừng lại một nhịp."
  },
  AvgDialog_49476_Content_16 = {
    Text = "Cô ấy nắm lấy tay bạn trong khoảnh khắc, không gian bên cạnh bạn bắt đầu thay đổi. Hàng loạt hình ảnh tạo thành một cảnh tượng hỗn loạn mà bạn cảm thấy quen thuộc, xuất hiện trước mặt bạn."
  },
  AvgDialog_49476_Content_17 = {
    Text = "Cảnh tượng ở đây rất hỗn loạn… Đây là hình ảnh trong ký ức của bạn?"
  },
  AvgDialog_49476_Content_18 = {
    Text = "Xin lỗi... Tôi đã trải qua cảnh này nhiều lần, ký ức quá phức tạp... nhưng tôi nghĩ bạn có thể nhìn rõ nơi này."
  },
  AvgDialog_49476_Content_19 = {
    Text = "Những hình ảnh và mùi vị mờ ảo, rất quen thuộc… giống như di tích sau một vụ nổ lớn… Đây không lẽ là?!"
  },
  AvgDialog_49476_Content_2 = {
    Text = "Ramona? Bạn không nói là mai có kỳ thi, tối nay phải đi ngủ sớm sao?"
  },
  AvgDialog_49476_Content_20 = {
    Text = "Akutê, nơi bắt đầu ký ức cuộc đời bạn… cũng là nơi bạn và tôi trong thế giới này gặp nhau."
  },
  AvgDialog_49476_Content_21 = {Text = "!!!"},
  AvgDialog_49476_Content_22 = {
    Text = "Người giữ bí mật, có những chuyện bạn đã quên từ lâu, nhưng tôi vẫn nhớ."
  },
  AvgDialog_49476_Content_23 = {
    Text = "Ở đây, tôi đã mất bạn, lần này đến lần khác. Mỗi lần, tôi đều nhớ như in."
  },
  AvgDialog_49476_Content_24 = {
    Text = "Chỉ có một lần duy nhất, bạn bước xuống, tiến vào sự hủy diệt vô tận, điểm sáng của hy vọng... nhưng điểm sáng ấy, không liên quan đến tôi."
  },
  AvgDialog_49476_Content_25 = {
    Text = "Trái tim dường như bị lưỡi dao sắc nhọn đâm vào, một cơn đau nhói tấn công bạn. Bạn đưa hai tay ra, ghì cô gái vào lòng."
  },
  AvgDialog_49476_Content_26 = {
    Text = "Lần này, thiếu nữ trầm tĩnh đã chiến đấu trong vô số không gian và thời gian, không né tránh."
  },
  AvgDialog_49476_Content_27 = {
    Text = "Cô ấy thuận theo dựa vào lòng bạn, nhẹ nhàng cọ cọ vào lồng ngực bạn, giống như một con mèo bị thương cuối cùng đã trở về với chủ nhân."
  },
  AvgDialog_49476_Content_28 = {
    Text = "Trong chiều này, bên cạnh bạn có nhiều người bạn đồng hành. đóa, Khổ Lệ Đặc, Alistair… và luôn bên bạn trong thế giới này."
  },
  AvgDialog_49476_Content_29 = {
    Text = "Tôi tin rằng, các bạn nhất định sẽ tiến triển thuận lợi và hoàn thành những việc mà các bạn muốn làm."
  },
  AvgDialog_49476_Content_3 = {
    Text = "Đúng lúc, Giáo sư Dexter vừa nói với tôi rằng ngày mai trưa ông ấy sẽ ở nhà làm bữa trưa, bảo chúng ta làm xong bài kiểm tra rồi trực tiếp đến đó."
  },
  AvgDialog_49476_Content_30 = {
    Text = "Tôi không nên xuất hiện như vậy. Sau nhiều trải nghiệm qua không gian và thời gian, tôi lẽ ra phải trưởng thành hơn."
  },
  AvgDialog_49476_Content_31 = {
    Text = "Tôi không muốn mất bạn nữa, Người Giữ Gìn."
  },
  AvgDialog_49476_Content_32 = {
    Text = "Chất lỏng trong veo trượt ra từ miếng che mắt của cô gái, chảy qua mái tóc bạc trắng, nhẹ nhàng lướt qua đôi má ửng hồng."
  },
  AvgDialog_49476_Content_33 = {
    Text = "Trán cô ấy áp sát vào bạn, mái tóc nhẹ nhàng cọ xát vào má bạn. Hơi thở của bạn ngưng lại, ngẩn ngơ nhìn qua lớp bịt mắt mềm mại, tưởng như thấy đôi mắt đẫm lệ của cô ấy."
  },
  AvgDialog_49476_Content_34 = {
    Text = "Giọng nói mát mẻ, run rẩy nhẹ của cô vang lên bên tai bạn. Hơi thở ấm áp phả vào tai bạn, như thể vọng về từ vô số chiều không gian và dòng thời gian, giống như những lời thì thầm đầy cảm xúc và mong manh."
  },
  AvgDialog_49476_Content_35 = {
    Text = "Đồng phục học sinh Misaque đã bị hỏng vì vô số trận chiến, trượt nhẹ vào tay bạn."
  },
  AvgDialog_49476_Content_36 = {
    Text = "Hãy coi đó là ảnh hưởng của sông thiêng liêng, được không?"
  },
  AvgDialog_49476_Content_37 = {
    Text = "Hôm nay, hãy để tôi trở nên trẻ con một lần. Lần cuối cùng."
  },
  AvgDialog_49476_Content_4 = {
    Text = "Tôi cũng rất muốn đi, thưa ngài. Tôi đã lâu không gặp cha rồi… Tuy nhiên, tôi sợ rằng mình không phù hợp để xuất hiện ở nhà cha."
  },
  AvgDialog_49476_Content_5 = {
    Text = "Cùng một vóc dáng, cùng một âm sắc, nhưng trong giọng nói không còn chút ngây thơ nào nữa, chỉ có sự bình tĩnh sau những khổ nạn đã trải qua, và một chút bối rối khó hiểu, không rõ từ đâu mà đến."
  },
  AvgDialog_49476_Content_6 = {
    Text = "Xuất hiện dưới ánh đèn theo tiếng nói này là chiếc mặt nạ khiến bạn không thể quên."
  },
  AvgDialog_49476_Content_7 = {Text = "Là bạn?"},
  AvgDialog_49476_Content_8 = {
    Text = "Xin lỗi, tôi đã nói rằng sẽ không chủ động đến làm phiền bạn, chỉ là…"
  },
  AvgDialog_49476_Content_9 = {
    Text = "Cô gái đeo đai bịt mắt đen, trên khuôn mặt vốn trắng bệch lấm tấm một sắc đỏ khác thường."
  },
  AvgDialog_49742_Content_1 = {
    Text = "Bạn đã hỏi tất cả mọi người: đóa, Erika, Sylvia, Khổ Lệ Đặc, Hannah…"
  },
  AvgDialog_49742_Content_10 = {
    Text = "Người Giữ Bí Mật……"
  },
  AvgDialog_49742_Content_11 = {
    Text = "Ramona lùi lại nửa bước khéo léo và dành cho bạn một biểu cảm xa cách."
  },
  AvgDialog_49742_Content_12 = {
    Text = "Xin lỗi, xin hãy tạm thời đừng đến gần tôi, tôi……"
  },
  AvgDialog_49742_Content_13 = {
    Text = "Sự biến động của dòng sông linh thiêng đã ảnh hưởng đến không ít thân thể được đánh thức. Tôi từng nghĩ mình sẽ là ngoại lệ, cuối cùng… thân phận của tôi…"
  },
  AvgDialog_49742_Content_14 = {
    Text = "Ramona vẫn là Ramona, sẽ không thay đổi."
