  AvgDialog_49742_Content_15 = {
    Text = "Tôi chính là tôi…"
  },
  AvgDialog_49742_Content_16 = {
    Text = "Đúng vậy."
  },
  AvgDialog_49742_Content_17 = {
    Text = "Bạn bước hai bước thật kiên định về phía trước, đến trước mặt cô ấy và nắm lấy tay cô ấy."
  },
  AvgDialog_49742_Content_18 = {
    Text = "Dù là ở thị trấn Lai hay trong giấc mơ của tôi, dù bạn hỏi tôi bao nhiêu lần, tôi cũng sẽ trả lời bạn như vậy."
  },
  AvgDialog_49742_Content_19 = {
    Text = "Sức mạnh không thể cưỡng lại được đã kéo bạn về phía Ramona, cô ấy đỡ lấy bạn đang loạng choạng. Hai tay vòng qua lưng bạn, cằm tựa vào vai trái bạn."
  },
  AvgDialog_49742_Content_2 = {
    Text = "Tất cả mọi người đều chỉ cho bạn cùng một hướng, họ muốn bạn băng qua sân giữa trường, và mở cánh cửa sắt khắc hoa ở cuối con đường đá."
  },
  AvgDialog_49742_Content_20 = {
    Text = "Bạn chỉ cần hai câu đơn giản như vậy đã khiến linh hồn tôi bình ổn lại… Dạo này tôi có phải quá căng thẳng không?"
