  AvgDialog_49742_Content_22 = {
    Text = "Hai tay đáp lại, ôm nhẹ lấy eo cô ấy. Cả hai và cả thế giới chìm vào im lặng, chỉ còn nghe thấy hơi thở của nhau. Dẫu vậy, vẫn không ngừng cảm nhận hơi ấm dịu dàng từ đối phương."
  },
  AvgDialog_49742_Content_23 = {
    Text = "……xin cảm ơn bạn, %player%."
  },
  AvgDialog_49742_Content_24 = {
    Text = "Ramona dẫn đầu rời khỏi nơi trú ẩn, cô ấy đỡ vai bạn, định nói gì đó nhưng lại thôi."
  },
  AvgDialog_49742_Content_25 = {
    Text = "Bạn còn điều gì muốn nói với tôi không?"
  },
  AvgDialog_49742_Content_26 = {
    Text = "Không, không phải bây giờ."
  },
  AvgDialog_49742_Content_27 = {
    Text = "Cô ấy vỗ nhẹ vào vai bạn, ra hiệu chỉ hướng rời đi."
  },
  AvgDialog_49742_Content_28 = {
    Text = "Hãy về trước đi, được không? Tôi hứa với bạn rằng, ngày mai bạn sẽ thấy tôi đã hoàn toàn bình thường rồi."
  },
  AvgDialog_49742_Content_29 = {
    Text = "Cô ấy tạm thời cần thêm thời gian và không gian, bạn chắc chắn có thể hiểu."
  },
  AvgDialog_49742_Content_3 = {
    Text = "Khoảnh khắc bước vào Diệu Trủng, đám mây đen dày đặc trên đỉnh đầu đã phát ra tiếng gầm giận dữ đầu tiên. Ánh chớp sắc lạnh từ trên trời giáng xuống, tan vào cuối chân trời."
  },
  AvgDialog_49742_Content_30 = {
    Text = "Ramona nhìn bóng lưng của người bạn đồng hành biến mất giữa những bia đá, mới thở ra một hơi thật mạnh."
  },
  AvgDialog_49742_Content_31 = {
    Text = "Họng cô như bị lửa đốt, mỗi lần thở ra đều giống như tiếng rên rỉ của người bệnh —— nhưng trước mặt đối tác, cô đã cố gắng hết sức để che giấu sự bất thường của mình."
  },
  AvgDialog_49742_Content_32 = {
    Text = "Cô từ từ ngồi xuống trước bia đá hình chìa khóa, như bị số phận dẫn dắt, mười ngón tay đặt lên tên được khắc trên đó."
  },
  AvgDialog_49742_Content_33 = {
    Text = "Cô nghiêng đầu, đôi môi từ từ áp sát vào bề mặt lạnh lẽo của bia đá, dùng đôi môi mềm mại cảm nhận nhiệt độ của số phận."
  },
  AvgDialog_49742_Content_35 = {
    Text = "Đây là cái tên mà cô ấy sẽ mãi mãi không quên."
  },
  AvgDialog_49742_Content_4 = {
