  AvgDialog_49836_Content_20 = {
    Text = "Họ chọn nhiều cô gái, ép buộc các cô gái uống sữa đỏ tươi từ cây mẹ, tắm trong nhựa cây mẹ, cho đến khi cô gái và cây hòa làm một."
