  AvgDialog_49836_Content_27 = {
    Text = "Cô gái chạy trốn đã hòa mình vào đám đông, cô rúm ró ở góc tường, khi sợ hãi sự tiếp cận của người khác thì chỉ nhận được một miếng bánh mì."
  },
  AvgDialog_49836_Content_28 = {
    Text = "Những người đó cho cô ấy bánh mì, không phải vì cô ấy là hoàng hậu của đế chế, không phải vì cô ấy là đại diện của cây mẹ…… chỉ vì cô ấy là một đứa trẻ."
