  AvgDialog_49871_Content_7 = {
    Text = "Trước khi ảnh hưởng hoàn toàn lắng xuống, đừng để các thân thể được đánh thức không có phòng bị. Họ có thể trở thành nguồn <Red:nguy hiểm>."
  },
  AvgDialog_49880_Content_1 = {
    Text = "Giáp lướt nhẹ giữa má và cổ, đầu nhọn của nó khẽ gạt mở cúc áo đồng phục, ngón tay chạm lên xương quai xanh lộ ra."
  },
  AvgDialog_49880_Content_10 = {
    Text = "Vanda mạnh mẽ giật tấm vải bịt mắt của bạn xuống, cô ấy nheo mắt lại, một cảm giác áp lực kỳ lạ khác biệt với sự hung bạo đang lan tỏa quanh người cô."
  },
  AvgDialog_49880_Content_11 = {
    Text = "Gai nhọn lướt qua xương quai xanh, da thịt bị những gai xương thô ráp và sắc nhọn xé rách. Vanda nhắm mắt, hít mùi máu tươi bay trong không khí, tâm trạng thỏa mãn sâu sắc."
  },
  AvgDialog_49880_Content_12 = {
    Text = "Chẳng bao lâu sau khi tôi giết chết vị vua thứ tư, quốc gia của tôi trên hành tinh này đã bị diệt vong."
  },
  AvgDialog_49880_Content_13 = {
    Text = "Nói đến chuyện đó, tôi đã rất lâu, rất lâu không gặp người mới rồi."
  },
  AvgDialog_49880_Content_14 = {
    Text = "Gai nhọn được giơ cao, chất lỏng sền sệt tụ lại ở đầu nhọn, gần sát với vết thương hở của bạn."
  },
  AvgDialog_49880_Content_15 = {
    Text = "Bây giờ là thời điểm tốt, bạn nghĩ sao?"
  },
  AvgDialog_49880_Content_16 = {
    Text = "Xa lánh sự rối ren và dịch bệnh, không có phiền não, không có trách nhiệm… chỉ có những người đáng tin cậy bên cạnh. Đây thực sự là thời đại tốt đẹp nhất!"
  },
  AvgDialog_49880_Content_17 = {
    Text = "Vanda, bạn thực sự nghĩ như vậy sao?"
  },
  AvgDialog_49880_Content_18 = {
    Text = "Ý nghĩa là gì?"
  },
  AvgDialog_49880_Content_19 = {
    Text = "Không có lo âu, không có trách nhiệm…"
  },
  AvgDialog_49880_Content_2 = {
    Text = "Bạn... Bạn là thân thể được đánh thức phải không?"
  },
  AvgDialog_49880_Content_20 = {
    Text = "Bạn, đồng hành cùng với Cambrian, chưa bao giờ coi trách nhiệm là gánh nặng."
  },
  AvgDialog_49880_Content_21 = {
    Text = "Bạn làm thế nào mà biết về Cambrian——"
  },
  AvgDialog_49880_Content_22 = {
    Text = "Nữ hoàng của hành tinh khác, trước khi biến tôi thành ông vua mới, hãy lắng nghe trái tim của chính mình."
  },
  AvgDialog_49880_Content_23 = {
    Text = "Sự ảnh hưởng của dòng sông thiêng liêng Lemvahix không làm bạn biến thành một hình dạng khác."
  },
  AvgDialog_49880_Content_25 = {
    Text = "Bạn nói đúng, bé pet."
  },
  AvgDialog_49880_Content_26 = {
    Text = "Không khí thơ mộng tan biến, gai nhọn rút lui như bờ biển đang rút nước, đung đưa một cách không ổn định phía sau Vanda."
  },
  AvgDialog_49880_Content_27 = {
    Text = "Đi đi, tối nay còn chưa phải lúc."
  },
  AvgDialog_49880_Content_28 = {
    Text = "Không phải lúc?"
  },
  AvgDialog_49880_Content_29 = {
    Text = "Đầy tớ bất tử ùa lên, đẩy bạn ra, trong khi Vanda phát ra một tiếng hít mũi đầy vui vẻ."
  },
  AvgDialog_49880_Content_3 = {
    Text = "Tầm nhìn bị che khuất bởi tấm lụa đen, các giác quan của thân thể bị bóng tối khuếch đại đến cực độ. Tiếng động của áo giáp trượt trên da hòa vào với hơi thở, khiến người ta cảm nhận được một cơn run rẩy khởi nguồn từ sâu thẳm trong linh hồn."
  },
  AvgDialog_49880_Content_30 = {
    Text = "Nữ hoàng sẽ không mất lý trí, cũng không thu hồi những lời đã nói, chỉ là để bạn trở thành người kế nhiệm tiếp theo của ta, quả thật còn quá sớm."
  },
  AvgDialog_49880_Content_31 = {
    Text = "Đi đi, thú cưng nhỏ. Nhưng hãy chuẩn bị sẵn sàng —— khi thời cơ chín muồi, ta sẽ gọi ngươi lại."
  },
  AvgDialog_49880_Content_4 = {
    Text = "Alô?Bạn có hiểu tôi đang nói gì không?"
  },
  AvgDialog_49880_Content_5 = {
    Text = "Một tiếng cười nhẹ vang lên từ trên đầu, khi bạn còn đang suy nghĩ về chủ nhân của tiếng cười đó, một chiếc gai nhọn đã ôm lấy eo bạn."
  },
  AvgDialog_49880_Content_6 = {
    Text = "Nó giống như một con trăn khổng lồ với tâm trạng thất thường, khi tức giận, gai xương sẽ không chút nương tay đâm xuyên qua thân thể bạn, đôi khi lại lười biếng cuộn trên vai bạn."
  },
  AvgDialog_49880_Content_7 = {
    Text = "Lúc này, nó bơi qua thân thể bạn, đầu nhọn chạm vào xương cổ của bạn, giống như một con vật đang âu yếm cầu tình, lại giống như một con dao nguy hiểm."
  },
  AvgDialog_49880_Content_8 = {
    Text = "Vanda……là cô phải không!"
  },
  AvgDialog_49880_Content_9 = {
    Text = "Hừ… chậm như vậy mới nhận ra chủ, cậu đúng là một con thú cưng chẳng ra gì."
  },
  AvgDialog_50760_Content_1 = {
    Text = "Bạn ngây người nhìn vào đống chất lỏng đen đặc trước mặt. Đồng đội từng sát cánh không lâu trước đây giờ nằm ở đây, mãi mãi ở lại trên dãy băng tuyết quanh năm này."
  },
  AvgDialog_50760_Content_10 = {
    Text = "Các bạn ngẩng đầu lên. Giống như một đám mây đen che mặt trời, một bóng đen khổng lồ từ bên vách đá dâng lên, xuất hiện phía trên các bạn."
  },
  AvgDialog_50760_Content_11 = {
    Text = "Trên thân thể của con quái vật khổng lồ, khắc một biểu tượng lớn —— trong mơ, bạn đã từng thấy nó."
  },
  AvgDialog_50760_Content_12 = {
    Text = "Đó là……Hội Giáo đèn lồng!!!"
  },
  AvgDialog_50760_Content_13 = {Text = "Rầm!!!"},
  AvgDialog_50760_Content_14 = {
    Text = "<Shake:à——>"
  },
  AvgDialog_50760_Content_15 = {
    Text = "Anh/chị lớn {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}!!!"
  },
  AvgDialog_50760_Content_16 = {
    Text = "Vật thể khổng lồ lơ lửng trên không trung đột ngột rơi xuống. Một tiếng nổ vang rền như xé toạc đỉnh núi, khiến tảng đá dưới chân các ngươi vỡ vụn."
  },
  AvgDialog_50760_Content_17 = {
    Text = "Bạn bước hụt chân và cùng với Hiro rơi xuống thung lũng sâu."
  },
  AvgDialog_50760_Content_18 = {
    Text = "——Trong những tiếng kêu sợ hãi của các bạn, Hiro nhe răng và lần đầu tiên cười lớn."
  },
  AvgDialog_50760_Content_2 = {Text = "Ọe——"},
  AvgDialog_50760_Content_3 = {
    Text = "Số lượng người thám hiểm chết trên tuyết sơn không thể đếm hết, nhưng tình cảnh bi thương và số người chết nhiều như vậy đối với hướng dẫn viên vẫn là lần đầu tiên."
  },
  AvgDialog_50760_Content_4 = {
    Text = "Anh ta không còn đủ sức chống đỡ, vai run rẩy dữ dội, ói mửa đến mức trời đất như rung chuyển."
  },
  AvgDialog_50760_Content_5 = {
    Text = "Họ cũng đã bị rỗng rỗng… tốc độ phát triển của rỗng rỗng ở đây thật sự quá nhanh…"
  },
  AvgDialog_50760_Content_6 = {
    Text = "Những con quái vật chạy trốn, và phản ứng của những người đồng đội này, đều quá bất thường.."
  },
  AvgDialog_50760_Content_7 = {
    Text = "Chỉ còn chúng ta, cần phải xuống núi nhanh chóng, nếu không…"
  },
  AvgDialog_50760_Content_8 = {
    Text = "Rầm——"
  },
  AvgDialog_50760_Content_9 = {
    Text = "Lời của anh ta chưa nói hết, chỉ cảm thấy trước mắt tối sầm lại."
  },
  AvgDialog_50761_Content_1 = {
    Text = "Sông băng lại phát ra tiếng gầm rống, bắt đầu thay đổi tư thế một cách cực kỳ chậm chạp."
  },
  AvgDialog_50761_Content_10 = {
    Text = "Rời đi… chúng ta chưa bao giờ có quyền rời đi."
  },
  AvgDialog_50761_Content_11 = {
    Text = "Một \"Hiro\" khác bỗng nhiên mất đi sự ám ảnh và điên rồ trong mắt."
  },
  AvgDialog_50761_Content_12 = {
    Text = "Cô nhìn về phía Hiro, trong ánh mắt chứa đầy sự bình thản và tĩnh tâm chưa từng có."
  },
  AvgDialog_50761_Content_13 = {
    Text = "Những thứ từng gây thương tổn cho bạn, những mối hận khắc cốt ghi tâm, bạn đều quên rồi sao, \"Hiro\"?"
  },
  AvgDialog_50761_Content_14 = {
    Text = "Tôi chưa bao giờ quên… Tôi chỉ là…"
  },
  AvgDialog_50761_Content_15 = {
    Text = "Bạn đang bối rối, \"Hiro\"."
  },
  AvgDialog_50761_Content_16 = {
    Text = "Chỉ có lực lượng đủ mạnh mới có thể hoàn thành việc trả thù của chúng ta. Trả thù chính là ý nghĩa duy nhất của chúng ta."
  },
  AvgDialog_50761_Content_17 = {
    Text = "Trả thù… cho ai ?"
  },
  AvgDialog_50761_Content_18 = {
    Text = "Số phận."
  },
  AvgDialog_50761_Content_19 = {
    Text = "Hai chữ \"bình tĩnh\" khiến thân thể Hiro rùng mình."
  },
  AvgDialog_50761_Content_2 = {
    Text = "Lần này, hồ băng đã bị che khuất lâu nay lộ ra diện mạo thật sự, các người có thể nhìn thấy cái bóng gầy guộc với những vết mụn đen sẫm, đầy ghê rợn trên mặt hồ băng."
  },
  AvgDialog_50761_Content_20 = {
    Text = "Dù chúng ta ở đâu, ngọn núi này cũng sẽ gọi chúng ta, nuốt chửng chúng ta."
  },
  AvgDialog_50761_Content_21 = {
    Text = "Đây là số phận của chúng ta, giống như những điều tồi tệ mà chúng ta đã trải qua…"
  },
  AvgDialog_50761_Content_22 = {
    Text = "Bạn đã biết câu trả lời từ lâu, nhưng đã làm ngơ đối với nó. Đúng không?"
  },
  AvgDialog_50761_Content_23 = {
    Text = "So với những người và việc khiến bạn căm ghét, số phận là một đối thủ đáng gờm…"
  },
  AvgDialog_50761_Content_24 = {
    Text = "Ngươi, kẻ hèn nhát như vậy, không xứng đáng được gọi là chiến binh."
  },
  AvgDialog_50761_Content_25 = {
    Text = "Thân thể của bạn đã không thể duy trì được nữa… Bạn sẽ chết ở đây."
  },
  AvgDialog_50761_Content_26 = {
    Text = "Dù sao đi nữa…… thì đã sao?"
  },
  AvgDialog_50761_Content_27 = {
    Text = "Cô ta quay mặt về phía các người, miệng nở nụ cười đầy tinh ranh, để lộ hai chiếc răng nanh sắc bén."
  },
  AvgDialog_50761_Content_28 = {
    Text = "Chiếc đèn dẫn dụ tôi đến đây, muốn lợi dụng tôi để hồi sinh @3. Ngọn núi này đang gọi tôi, muốn nuốt chửng tôi. Tôi đã biết từ lâu, nhưng tôi vẫn đến."
  },
  AvgDialog_50761_Content_29 = {
    Text = "Núi muốn gặp tôi, tôi sẽ đến gặp Người."
  },
  AvgDialog_50761_Content_3 = {
    Text = "Khe nứt trên hồ băng ngày càng lớn, giống như một vết rách sâu hoắm, nằm ngang trên mặt hồ dưới dãy băng tuyết kéo dài."
  },
  AvgDialog_50761_Content_30 = {
    Text = "Tôi phải cảm ơn Đèn Dẫn Đường, đã cho tôi cơ hội đối mặt với Ngài…"
  },
  AvgDialog_50761_Content_31 = {
    Text = "Bạn yếu đuối như vậy, nhưng bạn cũng đã đến, phải không?"
  },
  AvgDialog_50761_Content_32 = {
    Text = "Tôi là tương lai của bạn, \"Hiro\". Khi bạn có can đảm giơ kiếm đối đầu với số phận, bạn sẽ trở thành tôi."
  },
  AvgDialog_50761_Content_33 = {
    Text = "Những mụn mủ đen ngày càng tích tụ nhiều, giống như một đàn sinh vật nguyên thủy đói khát, tham lam lao vào thân thể cô, lan dần lên gò má cô."
  },
  AvgDialog_50761_Content_34 = {
    Text = "Cô ấy cười lên, như một con thú săn mồi dữ dội, như một vị vua sắp sửa bước lên ngai vàng."
  },
  AvgDialog_50761_Content_35 = {
    Text = "Hãy nhìn này, \"Hiro\"… Tôi sẽ tiêu thụ Ngài, tôi sẽ mạnh hơn, mọi số phận đều không thể ngăn cản tôi nữa!"
  },
  AvgDialog_50761_Content_36 = {
    Text = "Không còn xiềng xích…… không còn…… tôi sẽ không bội phản……"
  },
  AvgDialog_50761_Content_37 = {
    Text = "Những mụn mủ đen không ngừng lan rộng, tích tụ trên cơ thể cô, chui vào thân thể cô đã không còn chịu đựng được nữa, bao phủ khuôn mặt bình tĩnh nhưng điên rồ của cô…"
  },
  AvgDialog_50761_Content_38 = {
    Text = "Tôi sẽ……<Big:trả thù!>"
  },
  AvgDialog_50761_Content_39 = {
    Text = "Rầm——"
  },
  AvgDialog_50761_Content_4 = {
    Text = "Dịch nhầy đen chảy ra không ngừng, bao phủ lên cơ thể của \"Hiro\" khác."
  },
  AvgDialog_50761_Content_40 = {
    Text = "Giống như một vết loét bị chọc thủng, chất dịch màu đen và đỏ bắn tung tóe khắp nơi."
  },
  AvgDialog_50761_Content_41 = {
    Text = "Tiếng gầm cuối cùng của con thú vẫn còn vang vọng trong thung lũng trống. \nNơi cô từng đứng, giờ chỉ còn lại một vũng dịch thể, không có gì khác."
  },
  AvgDialog_50761_Content_42 = {
    Text = "\"trả thù\"...à.."
  },
  AvgDialog_50761_Content_43 = {
    Text = "Hiro có chút bối rối ngẩng đầu lên, nhìn về bầu trời âm u."
  },
  AvgDialog_50761_Content_44 = {
    Text = "Bụi tuyết gồ ghề lăn trên da cô, tan chảy thành những vệt nước nhỏ."
  },
  AvgDialog_50761_Content_45 = {
    Text = "Cô ấy… bị núi tiêu thụ?"
  },
  AvgDialog_50761_Content_47 = {
    Text = "Chưa đợi Hiro nói, câu hỏi của bạn đã nhận được câu trả lời ——"
  },
  AvgDialog_50761_Content_48 = {
    Text = "Đất dưới chân bắt đầu rung động. Từ sâu trong dãy núi, vang lên một tiếng gọi trầm thấp và ô uế…"
  },
  AvgDialog_50761_Content_5 = {
    Text = "Tôi cảm nhận được… nhiều hơn, hãy cho tôi thêm nữa!"
  },
  AvgDialog_50761_Content_6 = {
    Text = "Những mụn mủ kỳ quái này cảm nhận được lời gọi của cô, rung động với tiếng vo ve phấn khích, chen chúc nhau chui vào khoang miệng của cô, như thể khao khát được cô nuốt chửng."
  },
  AvgDialog_50761_Content_7 = {
    Text = "Chúng dường như thích bị nghiền nát, mê đắm việc bị nuốt chửng, và khao khát được tiêu hóa."
  },
  AvgDialog_50761_Content_8 = {
    Text = "Các ngươi đến trước một \"Hiro\" khác. Thân thể của cô ta ngâm trong những bọng mủ đen kịt, hình dáng đã trở nên mờ ảo như làn sương mỏng manh, dễ dàng bị thổi tan."
  },
  AvgDialog_50761_Content_9 = {
    Text = "Bây giờ rời khỏi đây, vẫn còn cơ hội…"
  },
  AvgDialog_50762_Content_1 = {
    Text = "Không kịp suy nghĩ. Bản năng sinh tồn thúc đẩy các bạn, dùng cả tay và chân để bò qua chất nhầy mà hang động tiết ra, bò về lỗ hang đang thu hẹp."
  },
  AvgDialog_50762_Content_10 = {
    Text = "Khói bụi pha lẫn những hạt tuyết, tán đi ngay trước mắt bạn."
  },
  AvgDialog_50762_Content_11 = {
    Text = "Đường hầm tối tăm bị chẻ ra một vết nứt, ánh sáng trắng chói lóa rọi lên vai."
  },
  AvgDialog_50762_Content_12 = {
    Text = "Nhanh lên, tôi đưa các bạn ra ngoài."
  },
  AvgDialog_50762_Content_13 = {
    Text = "Cô ấy đã chẻ nứt những tảng đá trong hang động và lôi các người ra khỏi đống đá vụn."
  },
  AvgDialog_50762_Content_14 = {
    Text = "Nợ bạn tình, giờ đã trả hết……"
