  AvgDialog_50762_Content_15 = {Text = "……á!"},
  AvgDialog_50762_Content_16 = {Text = "Hiro!!.."},
  AvgDialog_50762_Content_17 = {
    Text = "Lời chưa dứt, cô ấy bất ngờ bị hụt chân."
  },
  AvgDialog_50762_Content_18 = {
    Text = "——Trong ký ức, mặt đất vốn là một ngọn đồi bỗng biến mất chỉ trong chớp mắt, hóa thành vực thẳm vạn trượng."
  },
  AvgDialog_50762_Content_2 = {
    Text = "Đến rồi, ở ngay phía trước——"
  },
  AvgDialog_50762_Content_3 = {
    Text = "<Big:ầm——>"
  },
  AvgDialog_50762_Content_4 = {
    Text = "Ngọn núi hoàn toàn đảo lộn, góc độ hành lang thay đổi đột ngột, nghiêng xuống một cách nhanh chóng."
  },
  AvgDialog_50762_Content_5 = {
    Text = "Dưới lớp chất nhầy trơn tuột không thể nắm bắt, các ngươi gắng sức tiến gần đến lỗ hổng sáng ở cuối hang, nhưng sự co bóp của hành lang lại càng trở nên mạnh mẽ hơn."
  },
  AvgDialog_50762_Content_6 = {
    Text = "Tấm đá ấm áp không ngừng co lại, ép chặt vào lồng ngực của bạn, bạn chỉ cảm thấy không khí càng lúc càng loãng. Thân thể của Lily cũng bị kẹt vào khe đá, hoàn toàn không thể nhúc nhích."
  },
  AvgDialog_50762_Content_7 = {
    Text = "Cửa ra duy nhất bị những tảng đá đen dần nuốt chửng, con đường gần trong gang tấc bị cắt đứt, trước mắt bạn chìm vào bóng tối vô vọng."
  },
  AvgDialog_50762_Content_8 = {
    Text = "Không thể...ở đây.."
  },
  AvgDialog_50762_Content_9 = {
    Text = "Rầm rộ——"
  },
  AvgDialog_50763_Content_1 = {
    Text = "Hiro cúi người xuống, học theo bạn, vụng về xoa nhẹ mái tóc mềm mại của Lily."
  },
  AvgDialog_50763_Content_10 = {
    Text = "Cô đâm kiếm vào đá, những lọn tóc ướt nhẹp rũ xuống trước mặt, nhanh chóng đông thành những khối băng nhọn hoắt, lay động không ngừng theo đôi vai run rẩy của cô."
  },
  AvgDialog_50763_Content_11 = {
    Text = "Gió lạnh trên tuyết sơn không ngừng hoành hành, những âm thanh trầm đục tiếp tục vang lên."
  },
  AvgDialog_50763_Content_12 = {
    Text = "Cơn đau dữ dội liên tục giày vò cô, nhưng vào lúc này, giọng nói trong đầu cô đặc biệt rõ ràng."
  },
  AvgDialog_50763_Content_13 = {
    Text = "Tôi có rất nhiều việc không muốn làm, rất nhiều……bị ép buộc, bị thúc đẩy phải làm."
  },
  AvgDialog_50763_Content_14 = {
    Text = "<Change>giao…cô ấy…cho…tôi!"
