  AvgDialog_50763_Content_15 = {
    Text = "Có phải ngay cả khả năng giao tiếp cũng đã mất rồi không?"
  },
  AvgDialog_50763_Content_16 = {
    Text = "Hãy gửi gắm lời nói, cảm xúc của bạn vào thanh kiếm. \nHãy để tôi nghe thấy cơn giận dữ của bạn qua chiến đấu!"
  },
  AvgDialog_50763_Content_17 = {
    Text = "Tôi đã bị bội phản rất nhiều, rất nhiều lần."
