  AvgDialog_50763_Content_19 = {
    Text = "Đừng nghĩ nữa, còn tưởng mình là con nuôi cao quý của quan chức cao cấp sao?"
  },
  AvgDialog_50763_Content_2 = {
    Text = "Lily đã mất kiểm soát, nửa thân mình chìm vào núi. Những giọt nước mắt đen nhánh lăn dài trên khuôn mặt, ánh mắt trống rỗng nhìn chằm chằm vào Hiro."
  },
  AvgDialog_50763_Content_20 = {
    Text = "Máu bẩn thỉu, cuối cùng cũng chỉ sinh ra một kẻ <Blue:phản bội> như ngươi."
  },
  AvgDialog_50763_Content_21 = {
    Text = "<BigShake:Trả lời tôi!>\nTôi đã bị bỏ rơi rồi sao?!"
  },
  AvgDialog_50763_Content_22 = {
    Text = "Xét về kết quả thì đúng là vậy, nhưng…"
  },
  AvgDialog_50763_Content_23 = {
    Text = "Tay cô run rẩy không còn cầm chắc được cán dao, thanh kiếm bị va đập bởi sự rung động của đá, tạo ra tiếng ngân của kim loại."
  },
  AvgDialog_50763_Content_24 = {
    Text = "Tôi từng nghĩ, trả thù chính là tất cả của tôi… nhưng cho đến hôm nay tôi mới hiểu ra, tôi đã hiểu lầm bản chất ý nghĩa và tìm sai đối thủ."
  },
  AvgDialog_50763_Content_25 = {
    Text = "Chỉ có lực lượng đủ mạnh mới có thể hoàn thành việc trả thù của chúng ta. Trả thù chính là ý nghĩa duy nhất của chúng ta."
  },
  AvgDialog_50763_Content_26 = {
    Text = "Núi muốn gặp tôi, tôi sẽ đến gặp Người."
  },
  AvgDialog_50763_Content_27 = {
    Text = "Tôi là tương lai của bạn, \"Hiro\". Khi bạn có can đảm giơ kiếm đối đầu với số phận, bạn sẽ trở thành tôi."
  },
  AvgDialog_50763_Content_28 = {
    Text = "Cho nên bạn muốn trả thù kẻ phản bội, muốn bảo vệ Francis đã cứu bạn. \nNhưng chiến đấu không phải là thứ như vậy."
  },
  AvgDialog_50763_Content_29 = {
    Text = "Không phải để bảo vệ, không phải để trả thù, không phải để chứng minh. \nChiến đấu chỉ là chiến đấu mà thôi."
