  AvgDialog_50763_Content_30 = {
    Text = "Thế giới của bạn quá nhỏ hẹp, nên luôn như con bướm đêm để ý đến những tia sáng le lói mà người khác thắp lên."
  },
  AvgDialog_50763_Content_31 = {
    Text = "Nếu có cơ hội, thử đi khám phá xem thế giới rộng lớn hơn nhé."
