  AvgDialog_50763_Content_58 = {
    Text = "Cánh vai gầy guộc của cô ấy mang trên mình những xích sắt, bước đi một mình trong cô độc. Thân thể của cô ấy bị xiềng xích nặng nề trói buộc, dần cảm thấy ngạt thở, quỳ xuống trên mặt tuyết."
  },
  AvgDialog_50763_Content_59 = {Text = "Hiro……"},
  AvgDialog_50763_Content_6 = {
    Text = "Muốn để các người sống sót rời khỏi Elworth, muốn không phải trở thành quái vật trước mặt bạn lần nữa, chỉ có cách này thôi…"
  },
  AvgDialog_50763_Content_60 = {
    Text = "Lời thì thầm cấm kỵ không ngừng đổ vào tai, trong tiếng động đặc quánh và u tối, Hiro cảm nhận được sự cộng hưởng của núi và tim."
  },
  AvgDialog_50763_Content_61 = {
    Text = "Thịch, thịch, thịch……"
  },
  AvgDialog_50763_Content_62 = {
    Text = "Dưới lớp đất đá đóng băng cứng ngắc, con quái vật vừa được thức tỉnh đang gầm gừ đầy khao khát, thèm khát sự hiện diện của cô ấy."
