  },
  AvgDialog_50763_Content_75 = {
    Text = "Núi Elworth rung chuyển. Dãy núi liên miên nhấc lên sương băng trắng sữa, thân núi cứng nhắc và vụng về cố gắng vùng vẫy, dường như đang chống lại điều gì đó."
