  AvgDialog_50895_Content_1 = {
    Text = "Không được, tôi đã…… không còn chịu nổi……"
  },
  AvgDialog_50895_Content_10 = {
    Text = "Tiếng rít quen thuộc lại vang lên ở bầu trời cao của Lemvahi, khác với mọi ngày, lần này âm điệu đặc biệt nhẹ nhàng, như gió bạc nhẹ nhàng thổi qua."
