  AvgDialog_50895_Content_3 = {
    Text = "Hai luồng lực lượng sắc bén va chạm trong tâm trí cô, tiếng gào thét bạc lạnh và nhịp mạch máu sôi sục khiến biển nhận thức của cô trở nên hỗn độn."
