  },
  AvgDialog_50895_Content_6 = {
    Text = "Đây là cuối cùng rồi sao? Các người đã cạn kiệt đạn dược, còn phôi thai của cây mẹ vẫn đang tiếp tục nở lớn, vặn vẹo, sinh sôi…"
  },
  AvgDialog_50895_Content_7 = {
    Text = "Đông đong——"
  },
  AvgDialog_50895_Content_8 = {
    Text = "Những chiếc lông vũ lạnh lẽo và mềm mại hóa thành giọt bạc lấp lánh, lặng lẽ lăn dài trên gò má bạn đã bị vấy bẩn bởi máu, để lại dấu vết tựa như những giọt lệ bạc trong trẻo."
  },
  AvgDialog_50895_Content_9 = {
    Text = "Để dành cho Misaque, để dành cho tương lai của nhân loại, hãy cố gắng thêm một chút nữa."
  },
  AvgDialog_50896_Content_1 = {
    Text = "Canker khổng lồ của cây mẹ bị xuyên thủng bởi một thanh kiếm mảnh, huyết tương bắn tung tóe, các người đứng dưới mưa máu nhẹ nhàng."
  },
  AvgDialog_50896_Content_10 = {Text = "Yu Li-ét!"},
  AvgDialog_50896_Content_11 = {
    Text = "Yu Li-ét ngồi trên cành cây, thở dài với vẻ trầm ngâm. Cô nhẹ nhàng xoa dịu những cành cây của cây mẹ đang đung đưa mạnh như cánh tay, giống như đang dỗ dành một loài thú dữ đang kích động."
  },
  AvgDialog_50896_Content_12 = {
    Text = "Ôi, cây mẹ vĩ đại, xin hãy hấp thụ sức sống."
  },
  AvgDialog_50896_Content_13 = {
    Text = "Hãy dùng thân thể của bạn, gieo rắc lời chúc phúc tối thượng tới sa mạc, mở đường đến thế giới mới."
  },
  AvgDialog_50896_Content_14 = {
    Text = "Không cần phải cảm thương kẻ tội đồ, để cầu xin sự cứu rỗi, người Aran đã quyết tâm dâng trọn vẹn tất cả lòng sùng kính của họ cho bạn."
  },
  AvgDialog_50896_Content_15 = {
    Text = "Rắc rắc, âm thanh xương gãy vang lên liên tục, thịt máu của Á Lan hòa vào cành cây với tốc độ có thể nhìn thấy bằng mắt thường, các khối u co giật, khuấy động, tan ra rồi tái tạo."
  },
  AvgDialog_50896_Content_16 = {
    Text = "Vạn con cháu và thịt máu tụ lại thành hình hài dị dạng của mẹ mang thai, thân cây lung lay cũng dần trở nên vững chắc."
  },
  AvgDialog_50896_Content_17 = {
    Text = "Mong đèn luôn sáng."
  },
  AvgDialog_50896_Content_2 = {Text = "Ho, ho…"},
  AvgDialog_50896_Content_3 = {
    Text = "Mưa máu điên cuồng ảnh hưởng đến Ramona mạnh mẽ hơn nhiều so với các người. Cô đưa tay lau máu trên phần tóc mái, rồi ho dữ dội."
  },
  AvgDialog_50896_Content_4 = {
    Text = "Ramona, bạn…"
  },
  AvgDialog_50896_Content_5 = {
    Text = "Không sao đâu, tôi vẫn còn chịu được, các bạn nhìn u cục trên cây!"
  },
  AvgDialog_50896_Content_6 = {
    Text = "Các u nốt nổ tung, mềm oặt như những khối thịt bị rút cạn sinh lực, thân cây mẹ vốn đứng thẳng tự hào cũng run rẩy theo, như thể đang thì thầm về nỗi kinh hoàng và bất an kỳ lạ."
  },
  AvgDialog_50896_Content_7 = {
    Text = "Cây mẹ…… có phải đang sắp ngã xuống không??"
  },
  AvgDialog_50896_Content_8 = {
    Text = "Không, chưa…"
  },
  AvgDialog_50896_Content_9 = {
    Text = "Thật đáng buồn, tại sao các người lại làm những việc vô ích như vậy nhỉ?"
  },
  AvgDialog_50897_Content_1 = {
    Text = "Cây mẹ vẫn đang tiếp tục phân chia Nubia…!"
  },
  AvgDialog_50897_Content_2 = {
    Text = "Xin lỗi, sự ô nhiễm do Yu Li-ét gây ra đã ăn sâu, trước khi Tà Vy hoàn thành quá trình thanh lọc, tôi không thể kiểm soát hành động của cây mẹ."
  },
  AvgDialog_50897_Content_3 = {
    Text = "Đây là sự thất trách của tôi với tư cách là Chất Thể của Ham Muốn. Vì vậy, trong các trận chiến sắp tới, tôi sẽ trao quyền năng của mình cho bạn."
  },
  AvgDialog_50897_Content_4 = {
    Text = "Cơ hội để lực lượng của Tifaret Yesod bị điều khiển bởi người khác quả thật rất hiếm có."
  },
  AvgDialog_50897_Content_5 = {
    Text = "Sử dụng một cách tự do nhé, đừng lãng phí một giọt nào nhé?"
  },
  AvgDialog_51150_Content_1 = {Text = "Ôrla?"},
  AvgDialog_51150_Content_10 = {
    Text = "Những thứ này, đều từng xuất hiện trong tập thơ của tôi. Mọi thứ ở đây, đều như tôi từng tưởng tượng trong tập thơ của mình…"
  },
  AvgDialog_51150_Content_11 = {
    Text = "Người giữ bí mật {Male=ngài,Female=cô}, đây không phải là Tây Đài thực sự."
  },
  AvgDialog_51150_Content_12 = {
    Text = "Đây chính là <Yellow:thơ của Tây Đài>……"
  },
  AvgDialog_51150_Content_13 = {
    Text = "Dưới ánh sao lấp lánh của \"Phố Mơ\", Ôrla từ từ xoay vòng, ngắm nhìn khung cảnh trong bài thơ của cô."
  },
  AvgDialog_51150_Content_14 = {
    Text = "Ánh nắng như một lớp màn sương rơi xuống, chiếu sáng khuôn mặt tò mò, u sầu và bối rối của cô ấy."
  },
  AvgDialog_51150_Content_15 = {
    Text = "Thì ra là vậy… Thảo nào ở đây có nhiều thứ kỳ quặc."
  },
  AvgDialog_51150_Content_16 = {
    Text = "Nhưng, hòn đảo Tây Đài được hình thành như thế nào nhỉ……"
  },
  AvgDialog_51150_Content_17 = {
    Text = "Tôi cũng không biết… và, có một số thứ ở đây không hoàn toàn giống như những gì tôi viết trong bài thơ, họa sĩ kia, ban đầu nên là một ông lão dễ mến và hiền lành…"
  },
  AvgDialog_51150_Content_18 = {
    Text = "Tuy nhiên, tôi nghĩ rằng nếu muốn giải quyết vấn đề ở đây, có lẽ cần phải tìm thấy tập thơ trước mới được."
  },
  AvgDialog_51150_Content_19 = {
    Text = "Bạn có nhớ con đường này không?"
  },
  AvgDialog_51150_Content_2 = {
    Text = "Ah, xin lỗi, Người Giữ Gìn {Male=ngài,Female=cô}, tôi vừa mới bị phân tâm……"
  },
  AvgDialog_51150_Content_20 = {
    Text = "Trong bài thơ của tôi, phố Tháng Ba cách nhà rất gần. Đường về nhà, tôi luôn nhớ rõ."
  },
  AvgDialog_51150_Content_21 = {
    Text = "Cô ấy mỉm cười hướng về phía khu dân nghèo."
  },
  AvgDialog_51150_Content_22 = {
    Text = "Đi nào, Người Giữ Gìn {Male=ngài,Female=cô}, chúng ta đến vườn hồng… nơi tôi đã chết."
  },
  AvgDialog_51150_Content_3 = {
    Text = "Tôi có một dự đoán… không phải dự đoán, tôi chắc chắn."
  },
  AvgDialog_51150_Content_4 = {
    Text = "Đây không phải là Tây Đài!"
  },
  AvgDialog_51150_Content_5 = {
    Text = "……Ôrla, bạn có muốn nghiêm túc nghe xem mình đang nói gì không?"
  },
  AvgDialog_51150_Content_6 = {
    Text = "À, ý tôi là, chỗ này không phải là Tây Đài thật đâu."
  },
  AvgDialog_51150_Content_7 = {
    Text = "Không phải Tây Đài thật sự……"
  },
  AvgDialog_51150_Content_8 = {
    Text = "Xe điện sâu đo mua vé bằng thơ, bà bướm, con đường tháng Ba số 99, họa sĩ, sao cúc dại…"
  },
  AvgDialog_51150_Content_9 = {
    Text = "Những thứ chúng ta nhìn thấy, tôi luôn thấy vô cùng quen thuộc. Mãi đến vừa rồi tôi mới nhớ ra."
  },
  AvgDialog_51254_Content_1 = {
    Text = "Ánh mắt của cô ấy thanh tẩy linh hồn của bạn, mệt mỏi tan biến trong chớp mắt, ý chí chiến đấu mạnh mẽ không ngừng cháy trong lồng ngực."
  },
  AvgDialog_51254_Content_2 = {
    Text = "Cảm ơn bạn, Tà Vy ạ…"
  },
  AvgDialog_51254_Content_3 = {
    Text = "Tôi sẽ thực thi ý chí của bạn đến giây phút cuối cùng. \nNguyện chìa khóa bạc soi sáng con đường phía trước."
  },
  AvgDialog_51254_Content_4 = {
    Text = "Nguyện chìa khóa bạc dẫn đường cho chúng ta."
  },
  AvgDialog_51998_Content_1 = {
    Text = "Sự chế giễu của người Phi-li-tin vang lên trong phòng. Đội trưởng Phi-li-tin lắc đầu, túm tóc Talis rồi rút con dao ra."
  },
  AvgDialog_51998_Content_10 = {
    Text = "\"Bạn đã nhắc nhở tôi, tôi nên vứt bỏ tất cả đồ đạc của Goliath, để tránh Glen nghi ngờ.\""
  },
  AvgDialog_51998_Content_11 = {
    Text = "\"Vì điều này, tôi có thể để bạn chết không đau đớn như vậy... ?\""
  },
  AvgDialog_51998_Content_2 = {
    Text = "Anh ta quay người về phía Miriam. Ở hông anh, một bức tượng nhỏ đang đung đưa. Cô ấy đột nhiên mở to mắt."
  },
  AvgDialog_51998_Content_3 = {
    Text = "\"tượng đó... là từ đâu đến?\""
  },
  AvgDialog_51998_Content_4 = {
    Text = "\"Yo... thì ra cậu cũng biết nói, còn tưởng là đồ đần độn.\""
  },
  AvgDialog_51998_Content_5 = {
    Text = "\"tượng, từ đâu ra vậy?\""
  },
  AvgDialog_51998_Content_6 = {
    Text = "Đội trưởng Philistin đặt dao xuống. Cúi đầu nhìn bức tượng bên hông."
  },
  AvgDialog_51998_Content_7 = {
    Text = "Tượng được làm bằng một loại đá tối màu và cổ xưa, khắc họa hình ảnh một thiếu niên ngồi trên ngai vàng. Một số xúc tu kỳ quái vươn ra một cách hỗn loạn và kỳ dị, che khuất khuôn mặt của thiếu niên."
  },
  AvgDialog_51998_Content_8 = {
    Text = "\"Hế... cái này? Trưởng tộc Goliath tìm được trước đây. Vì sự dũng cảm của tôi, đã thưởng cho tôi.\""
  },
  AvgDialog_51998_Content_9 = {
    Text = "\"Tôi đã liều mạng vì anh ta, vậy mà anh ta lại cho tôi thứ này. Không biết là nền văn minh nào để lại, một món đồ vô dụng.\""
  },
  AvgDialog_51999_Content_1 = {
    Text = "Rầm——"
  },
  AvgDialog_51999_Content_10 = {
    Text = "\"Bạn cũng đang bị một ý chí cao hơn đuổi theo, săn lùng. Bạn và người còn lại đều là những linh hồn cô đơn không chủ.\""
  },
  AvgDialog_51999_Content_11 = {
    Text = "\"Người Lemuria, tin vào thần minh vô tình, và vị vua yếu đuối. Thần quốc... thôi, thật tẻ nhạt.\""
  },
  AvgDialog_51999_Content_2 = {
    Text = "Tiếng động trầm lặng, xuyên qua vô số bức tường đá dày, vang vọng trong cung điện của đền thần."
  },
  AvgDialog_51999_Content_3 = {
    Text = "Tulô dùng một tay chống cằm, mệt mỏi ngồi trên ngai vàng."
  },
  AvgDialog_51999_Content_4 = {
    Text = "Dân cư của Lemuria đã chìm vào giấc ngủ. Ông đã dùng hết lực lượng của mình, tặng họ một giấc mơ đẹp."
  },
  AvgDialog_51999_Content_5 = {
    Text = "「“Cơn bão Lemuria sẽ bình yên. Hố sâu Lemuria sẽ biến mất.”」"
  },
  AvgDialog_51999_Content_6 = {
    Text = "「“Vua sẽ che chở cho con dân lành thiện, mang lại vương quốc của Chúa…”」"
  },
  AvgDialog_51999_Content_7 = {
    Text = "「Thật là châm biếm. Đó là ý chí của ngươi truyền đạt phải không, “Lemuria”?」"
  },
  AvgDialog_51999_Content_8 = {
    Text = "Anh ta ngẩng đầu lên, ánh mắt xuyên qua tấm bảng đá trên đỉnh đầu, xuyên qua cơn mưa dữ dội và những đám mây đen, hướng tới bầu trời đêm thăm thẳm, rồi tiến sâu hơn vào giấc mơ còn mênh mông hơn cảbầu trời sao."
  },
  AvgDialog_51999_Content_9 = {
    Text = "\"Bạn đã chết từ lâu. Bạn chưa bao giờ quan tâm đến Lemuria.\""
  },
  AvgDialog_52000_Content_1 = {
    Text = "Ưu điểm của lời nói dối"
  },
  AvgDialog_52000_Content_10 = {
    Text = "Vị vua này đã được người Lemuria ca ngợi vô số lần. Lần đầu tiên, ông đứng trước mặt Miriam."
  },
  AvgDialog_52000_Content_11 = {
    Text = "Đi vào cửa này, có người sẽ khóc, có người sẽ điên cuồng, cũng có người đã từng cố gắng giết Dư."
  },
  AvgDialog_52000_Content_2 = {
    Text = "Anh ta đăm chiêu nhìn vào nước hồ."
  },
  AvgDialog_52000_Content_3 = {
    Text = "Những đầu trơn nhẵn nổi lên khỏi mặt nước, rồi lại chìm xuống, liên tục nổi chìm, tạo nên những gợn sóng đục trong hồ nước."
  },
  AvgDialog_52000_Content_4 = {
    Text = "Một con mắt lớn mọc ra hai bên đầu người cá. Nó nhìn chằm chằm vào anh ta, môi mở ra đóng lại, thốt ra những âm thanh mơ hồ, khó hiểu, dường như đang hỏi điều gì đó."
  },
  AvgDialog_52000_Content_5 = {
    Text = "Phía sau, bảng đá mở ra."
  },
  AvgDialog_52000_Content_6 = {
    Text = "Tán tụng chủ ta……Lemuria, vị vua vĩ đại……"
  },
  AvgDialog_52000_Content_7 = {
    Text = "Khi gặp mỗi chủ tế lần đầu tiên, anh ấy đều nghe thấy câu châm biếm này."
  },
  AvgDialog_52000_Content_8 = {
    Text = "Vương miện khổng lồ của Lemuria phản chiếu ánh sáng u tối không rõ từ đâu trong phòng, không tương xứng với tỷ lệ cơ thể của cậu thiếu niên, nhưng khi đeo trên đầu cậu lại không có chút gì lạc lõng, dường như sinh ra để trở thành một phần của thân thể cậu."
  },
  AvgDialog_52000_Content_9 = {
    Text = "Đôi mắt ngái ngủ nhìn về phía Miriam, giống như biển sâu thở nhẹ. Trên khuôn mặt còn đầy nét trẻ con, không hề thấy bất kỳ cảm xúc nào thuộc về một thiếu niên."
  },
  AvgDialog_52001_Content_1 = {
    Text = "Nhưng không sao cả, ngài có thể hiểu nỗi sợ hãi của ngươi. Tình bạn của chúng ta sẽ không thay đổi vì những lời xúc phạm này."
  },
  AvgDialog_52001_Content_10 = {
    Text = "Lại đây, cùng cầu nguyện với tôi, Débora."
  },
  AvgDialog_52001_Content_11 = {
    Text = "Không……Miriam……tôi van em……"
  },
  AvgDialog_52001_Content_12 = {
    Text = "Hãy nói với tôi: \"Hễ ai chịu khổ, Chúa sẽ trả.\""
  },
  AvgDialog_52001_Content_13 = {
    Text = "Phàm……khổ nạn……không, Miriam……"
  },
  AvgDialog_52001_Content_14 = {
    Text = "Hãy nói với tôi. \"Bất cứ ai mắc tội lỗi, Chúa sẽ trừng phạt.\""
  },
  AvgDialog_52001_Content_15 = {
    Text = "Miriam đọc lời cầu nguyện và đến bên cạnh cô ấy."
  },
  AvgDialog_52001_Content_16 = {
    Text = "Cho tôi nói một câu với Nord! Miriam… cho tôi nói một câu với anh ấy…"
  },
  AvgDialog_52001_Content_17 = {
    Text = "À!!!——"
  },
  AvgDialog_52001_Content_18 = {
    Text = "Cơn đau dữ dội lan tỏa từ bụng cô. Cô ngẩng đầu lên, thấy bàn tay nhợt nhạt của Miriam cầm con dao găm, đâm vào bụng mình và tạo nên một vệt đỏ thẫm như máu chảy trong cơ thể."
  },
  AvgDialog_52001_Content_19 = {
    Text = "Miriam không nghe thấy tiếng thét kinh khủng của Déborah, không nhìn thấy khuôn mặt cô ấy nhăn nhó vì sợ hãi và đau đớn."
  },
  AvgDialog_52001_Content_2 = {
    Text = "Cô ấy kính cẩn đặt tượng tulô bên cạnh bàn thờ, hành lễ trước nó."
  },
  AvgDialog_52001_Content_20 = {
    Text = "Dao găm di chuyển ổn định, máu ấm bắn lên mặt của Miriam. Cô thành tâm tụng niệm, bước lên những bậc thang dẫn đến thần quốc."
  },
  AvgDialog_52001_Content_22 = {
    Text = "Giết Miriam! Phân chia tài sản của gia đình Orn! Liên minh của chúng ta thịnh vượng! Cạn chén!!"
  },
  AvgDialog_52001_Content_23 = {
    Text = "Ly rượu chạm vào nhau, lòng tham không che giấu lan tỏa theo mùi thơm của rượu và thịt."
  },
  AvgDialog_52001_Content_24 = {
    Text = "Goliath liếm môi, tận hưởng hương vị khiến anh ta mê hoặc."
  },
  AvgDialog_52001_Content_25 = {
    Text = "Thôi, tiếp tục đi, bạn đang sao vậy?"
  },
  AvgDialog_52001_Content_26 = {
    Text = "Bạn… khuôn mặt của bạn…"
  },
  AvgDialog_52001_Content_27 = {
    Text = "Mặt tôi?"
  },
  AvgDialog_52001_Content_28 = {
    Text = "Anh ta nhìn vào viên gạch men bóng như gương bên cạnh, thấy một khuôn mặt mang dáng dấp của loài cá."
  },
  AvgDialog_52001_Content_29 = {Text = "À!!!"},
  AvgDialog_52001_Content_3 = {
    Text = "Tán tụng chủ ta……Lemuria, vị vua vĩ đại……đêm nay, tôi sẽ đón chào ngài trở lại."
  },
  AvgDialog_52001_Content_30 = {
    Text = "Những đạo vết thương xuất hiện trên ngực anh ta, giống như bị con dao vô hình cắt qua. Tai và lông mày đang biến mất, nhãn cầu nhanh chóng phình to, mọc ra hai bên."
  },
  AvgDialog_52001_Content_31 = {
    Text = "Đau đớn dữ dội vượt qua cồn và adrenaline đến não anh. Anh ngã xuống đất, phát ra tiếng rên rỉ đau đớn muộn màng, hai tay loạn xạ xé rách khuôn mặt mình."
  },
  AvgDialog_52001_Content_32 = {
    Text = "Đây là? À!!——"
  },
  AvgDialog_52001_Content_33 = {
    Text = "Một, hai, ba……trong đại sảnh tiệc sang trọng, quý tộc lần lượt ngã xuống đất."
  },
  AvgDialog_52001_Content_34 = {
    Text = "Vết thương đỏ sẫm liên tục xuất hiện trên thân thể họ, máu và thịt vẽ nên một bức tranh cổ xưa trên thân thể họ."
  },
  AvgDialog_52001_Content_35 = {
    Text = "Tiếng rên rỉ đau đớn hòa thành bài ca hùng tráng, máu tươi phun ra, rót đầy mỗi chiếc ly rượu."
  },
  AvgDialog_52001_Content_36 = {
    Text = "Đây là…… Đây là…… Lễ hội Người cá!"
  },
  AvgDialog_52001_Content_37 = {
    Text = "Đúng vậy, nghi lễ Người Cá. Bi kịch của gia đình Orn, các bạn hẳn đã biết."
  },
  AvgDialog_52001_Content_38 = {
    Text = "Tại sao…… Goliath?"
  },
  AvgDialog_52001_Content_39 = {Text = "Tại sao?"},
  AvgDialog_52001_Content_4 = {
    Text = "Xin quý khách hãy kiên nhẫn chờ đợi. Thời khắc chính vị của tinh tú sắp đến…"
  },
  AvgDialog_52001_Content_40 = {
    Text = "Goliath dường như đã nghe được một câu chuyện hài hước. Ông ấy đứng dậy từ ghế chủ tọa, rồi cầm lấy con dao của mình."
  },
  AvgDialog_52001_Content_41 = {
    Text = "Hợp tác với các người, tôi có thể nhận được một mảnh đất nhỏ của gia tộc Ornn."
  },
  AvgDialog_52001_Content_42 = {
    Text = "Hợp tác với Miriam, tôi có thể đạt được lực lượng mà các người không thể tưởng tượng, biến tất cả các gia tộc của các người thành một phần của loài người cá, và kiểm soát toàn bộ tài sản của các người…"
  },
  AvgDialog_52001_Content_43 = {
    Text = "Hãy nói cho tôi biết, thưa ông Edmond, nếu là ông, ông sẽ chọn như thế nào?"
  },
  AvgDialog_52001_Content_44 = {
    Text = "Tôi……Chúng tôi sẽ không đầu hàng!"
  },
  AvgDialog_52001_Content_45 = {
    Text = "Đúng vậy! Goliath, vì vinh quang của gia đình Enom, chúng ta sẽ… a——"
  },
  AvgDialog_52001_Content_46 = {
    Text = "Lưỡi kiếm lớn lao xuống dọc, quý tộc trẻ tuổi bị chẻ làm đôi, đổ gục sang hai phía, mất đi khả năng chứng minh vinh quang."
  },
  AvgDialog_52001_Content_47 = {
    Text = "Các cánh cửa xung quanh mở ra, vô số người cá tràn vào đại sảnh như dòng nước thủy triều."
  },
  AvgDialog_52001_Content_48 = {
    Text = "……Vệ binh bên ngoài đâu?"
  },
  AvgDialog_52001_Content_49 = {
    Text = "Khi các người đang nâng chén, những binh lính hộ vệ đã bị chúng tôi xử lý gọn gàng rồi."
  },
  AvgDialog_52001_Content_5 = {
    Text = "Cô đứng dậy, nhẹ nhàng bước tới gần Deborah. Trong bàn tay tái nhợt, con dao tế lễ có hình dáng kỳ quái lóe lên thứ ánh sáng mờ ám."
  },
  AvgDialog_52001_Content_50 = {
    Text = "Còn về quân đội bên ngoài… cũng không cần nghĩ đến việc liên lạc với họ nữa."
  },
  AvgDialog_52001_Content_51 = {
    Text = "Máu tươi nhuộm đỏ mọi góc của sảnh lớn, tiếng kêu thảm thiết điên rồ va chạm và vang dội khắp các bức tường, giống như bản giao hưởng từ địa ngục."
  },
  AvgDialog_52001_Content_52 = {
    Text = "Những người không uống phải rượu độc, thân thể run rẩy, thậm chí không còn sức để rút kiếm hoặc chạy trốn."
  },
  AvgDialog_52001_Content_53 = {
    Text = "Goliath ngắm nhìn bức tranh đẫm máu trong đại sảnh, thấy vẻ kinh hoàng trên gương mặt các quý tộc, thở dài đầy mãn nguyện, rồi cầm lên thanh kiếm khổng lồ."
  },
  AvgDialog_52001_Content_54 = {
    Text = "Uống rượu độc để biến thành người cá, hoặc chết tại đây. Hãy chọn đi!"
  },
  AvgDialog_52001_Content_56 = {
    Text = "À!!!——"
  },
  AvgDialog_52001_Content_57 = {
    Text = "Tiếng kêu thê lương va vào bảng đá, phát ra âm thanh trầm đục."
  },
  AvgDialog_52001_Content_58 = {
    Text = "Cô ấy muốn vùng vẫy và trốn chạy, nhưng thân thể bị Miriam kiểm soát nên không thể di chuyển dù chỉ một chút."
  },
  AvgDialog_52001_Content_59 = {
    Text = "Cô ấy muốn ngất đi, nhưng tâm trí cô ấy vẫn minh mẫn, đón nhận từng cảm giác đau đớn và nỗi sợ hãi."
  },
  AvgDialog_52001_Content_6 = {
    Text = "Không! Miriam!! Tôi van cầu cô… tôi van cầu cô… đừng làm việc tàn nhẫn như vậy…"
  },
  AvgDialog_52001_Content_60 = {
    Text = "Hãy nói với ta, \"Hễ ai thành tâm, Chúa sẽ quan tâm...\""
  },
  AvgDialog_52001_Content_61 = {
    Text = "Máu của Déborah vấy đầy lên người Miriam. Cô nhớ lại nhiều năm trước, trên bàn tế trong đền thần, cô cũng đã tiễn biệt cha mình trong cảnh tượng như vậy."
  },
  AvgDialog_52001_Content_62 = {
    Text = "Tiễn biệt, là để ngày tái ngộ thêm phần ý nghĩa, phải không, chúa công?"
  },
  AvgDialog_52001_Content_63 = {
    Text = "Cô ấy nhìn sâu vào bụng của Deborah, con dao găm khẽ lướt qua, hoàn thành nét vẽ cuối cùng của bức tranh."
  },
  AvgDialog_52001_Content_64 = {
    Text = "Đi nào, Deborah. Nói đi. Những ước nguyện của bạn…"
  },
  AvgDialog_52001_Content_65 = {
    Text = "Tay của Miriam đưa vào bụng cô ấy, khuấy đảo, xé rách."
  },
  AvgDialog_52001_Content_66 = {
    Text = "Đê-bô-ra họng khàn đau đớn rít lên, đôi mắt đỏ tươi mở to điên rồ, nhìn chằm chằm vào bụng mình."
  },
  AvgDialog_52001_Content_67 = {
    Text = "……\"Mọi ước nguyện, Chúa sẽ đáp ứng.\""
  },
  AvgDialog_52001_Content_68 = {
    Text = "Miriam đã xé rách một thứ gì đó, có lẽ rất đau, nhưng Deborah đã không còn cảm nhận được."
  },
  AvgDialog_52001_Content_69 = {
    Text = "Não bộ của cô ấy đã trở nên tê dại, cảm xúc và giác quan đều đã rời xa cô ấy."
  },
  AvgDialog_52001_Content_7 = {
    Text = "Nhìn tôi, Deborah. Nhìn tôi…"
  },
  AvgDialog_52001_Content_70 = {
    Text = "Cô ấy nhìn mờ mờ thấy, Miriam bế ra một khối thịt đẫm máu từ khoang bụng của cô."
  },
  AvgDialog_52001_Content_71 = {
    Text = "Sa…… Sa……"
  },
  AvgDialog_52001_Content_72 = {
    Text = "Sara. Miriam đã từng kể với cô rằng đó là tên của em gái cô."
  },
  AvgDialog_52001_Content_73 = {
    Text = "Cô ấy đã thảo luận với Nord và họ sẽ đặt tên con gái của mình là tên này. Nhưng cô ấy vẫn chưa kịp nói với Miriam."
  },
  AvgDialog_52001_Content_74 = {
    Text = "Gọi cô ấy là Sara. Deborah thì thầm, nhưng cô ấy đã không thể phát ra bất kỳ âm thanh nào nữa."
  },
  AvgDialog_52001_Content_75 = {
    Text = "\"Thưa Chủ nhân, nguyện cho tiếng hát của chúng con xuyên qua biển sâu, cùng Người tiến tới cảnh giới bình an vô tận và cực lạc.\""
  },
  AvgDialog_52001_Content_76 = {
    Text = "Miriam âu yếm hôn cô con gái nuôi của mình, máu trên người đứa bé nhuộm đỏ môi cô. Máu chảy dọc theo khóe môi, cô nhẹ nhàng đóng mắt cho Deborah."
  },
  AvgDialog_52001_Content_8 = {
    Text = "Tôi biết, bạn rất sợ hãi. Tôi đã gặp nhiều người mộ đạo, đối mặt với kết thúc cuộc đời, họ đều cảm thấy sợ hãi."
  },
  AvgDialog_52001_Content_9 = {
    Text = "Nhưng đừng lo lắng. Bạn là con dân tối cao của thần quốc, mọi điều bạn phải chịu đựng đều sẽ được bù đắp trong thần quốc."
  },
  AvgDialog_52002_Content_1 = {
    Text = "Các vì sao đã vào chính vị. Thánh thai của Đức Vua đã được cấy vào cơ thể của Thánh Thể. Chẳng bao lâu nữa, Đức Vua sẽ tái hiện trên thế gian."
  },
  AvgDialog_52002_Content_10 = {
    Text = "Trong tiếng hát đồng thanh vang dội của bộ tộc người cá, Miriam đưa hai tay lên, nâng cao đứa bé trong vòng tay."
  },
  AvgDialog_52002_Content_11 = {
    Text = "Ở nơi trái tim ban đầu của cô, thai thánh dưới những vì sao, tỏa ra ánh sáng trắng thuần khiết như tuyết."
  },
  AvgDialog_52002_Content_12 = {
    Text = "Ư wah——"
  },
  AvgDialog_52002_Content_13 = {
    Text = "Mọi thứ đều yên tĩnh lại. Đứa trẻ bị bao phủ bởi máu, xoắn thân thể, trong những tàn tích cổ xưa, vang lên tiếng khóc đầu tiên của cô ấy."
  },
  AvgDialog_52002_Content_14 = {
    Text = "Các ngôi sao trên bầu trời im lặng, lắng nghe tiếng khóc như lời thần dụ. Một ngôi sao rơi xuống, vẽ nên một dấu chấm đau thương và khắc khoải trong đêm tối."
  },
  AvgDialog_52002_Content_15 = {
    Text = "——Một câu chuyện khác về các ngôi sao, sắp bắt đầu."
  },
  AvgDialog_52002_Content_2 = {
    Text = "Vua, sẽ bảo vệ dân lành của Người, mang lại thần quốc!"
  },
  AvgDialog_52002_Content_3 = {
    Text = "Thần quốc!thần quốc!"
  },
  AvgDialog_52002_Content_4 = {
    Text = "Những người cá reo hò và nhảy múa trong cơn điên cuồng. Miriam bước đến giữa đám đông. Ánh sao rơi xuống, chiếu sáng khuôn mặt đẫm máu và nước mắt của cô."
  },
  AvgDialog_52002_Content_5 = {
    Text = "Đạo lý của Vua sẽ lan truyền khắp thế giới. Kính thưa Chủ tế, xin hãy đặt tên cho giáo phái này."
  },
  AvgDialog_52002_Content_6 = {
    Text = "Đôi mắt lạnh lùng và nóng bỏng từ từ di chuyển. Miriam nhìn quanh các binh sĩ và thần dân của mình. Cô nở một nụ cười đầy uy nghiêm của chủ tế."
  },
  AvgDialog_52002_Content_7 = {
    Text = "Chúng ta bước ra biển cả, theo dấu chân của Vua. Chúng ta vượt sóng trở về, mang theo vương quốc của Vua…"
  },
  AvgDialog_52002_Content_8 = {
    Text = "Thế giới sẽ gọi chúng ta, những người dấn thân vào biển."
  },
  AvgDialog_52002_Content_9 = {
    Text = "Người dấn thân vào biển!người dấn thân vào biển!!"
  },
  AvgDialog_52003_Content_1 = {
    Text = "Vua sẽ nói cho các ngươi. Hãy cầu nguyện."
  },
  AvgDialog_52003_Content_10 = {
    Text = "Xung quanh không ngừng có người ngã xuống. Miriam nghiến răng chịu đựng cơn đau, đọc lời cầu nguyện trên giấy."
  },
  AvgDialog_52003_Content_11 = {
    Text = "\"Trong hố sâu u tối xa xôi, những linh hồn vĩ đại cổ xưa đang chìm vào giấc ngủ……\""
  },
  AvgDialog_52003_Content_12 = {
    Text = "Miriam đã nói những lời này bằng tiếng Lemuria phổ thông, nhưng khi chúng thoát ra khỏi miệng cô, chúng đã trở thành một ngôn ngữ khác."
  },
  AvgDialog_52003_Content_13 = {
    Text = "Ở cùng một thời điểm, giọng nói của cô ấy chồng chéo và vang lên phức tạp. Giống như văn bản, giọng nói của cô ấy cũng trở thành một cấu trúc chiều, giống như từ một không gian thời gian mà con người không thể tưởng tượng được."
  },
  AvgDialog_52003_Content_14 = {
    Text = "\"...Ý chí của Ngài như mạng lưới các vì sao đan xen, Ngài chờ đợi trong hư vô vĩnh cửu để dẫn ngươi vào giấc mơ...\""
  },
  AvgDialog_52003_Content_15 = {
    Text = "Miriam vẫn tiếp tục đọc kinh."
  },
  AvgDialog_52003_Content_16 = {
    Text = "Từ lúc nào không hay, thế giới trước mắt đã biến mất."
  },
  AvgDialog_52003_Content_17 = {
    Text = "Cô ấy đang ở biển sâu, dù nhìn về hướng nào, cũng chỉ thấy nước biển trống rỗng."
  },
  AvgDialog_52003_Content_18 = {
    Text = "Trong biển sâu, những ánh sáng lấp lánh như các vì sao trong vũ trụ rơi."
  },
  AvgDialog_52003_Content_19 = {
    Text = "Miriam cảm thấy mình cũng hóa thành một ngôi sao, ánh sáng trên người cô dần tụ lại về một nơi xa xăm. Đôi mắt cô hướng về phía ấy."
  },
  AvgDialog_52003_Content_2 = {
    Text = "Lão nhân đã rời khỏi phòng, bên trong chỉ còn lại một vị linh mục và vài vệ sĩ."
  },
  AvgDialog_52003_Content_20 = {
    Text = "Số lượng ánh sáng tụ lại với nhau, ở nơi đó hình thành một dáng hình mờ ảo. Đó là một dáng hình được cấu thành bởi cơ thể người, ngai vàng và xúc tu."
  },
  AvgDialog_52003_Content_21 = {
    Text = "Đó là… vua sao?"
  },
  AvgDialog_52003_Content_22 = {Text = "Pa——"},
  AvgDialog_52003_Content_23 = {
    Text = "Có vẻ như bị một âm thanh nào đó làm giật mình, ông ta tỉnh giấc từ ngai vàng. Khi ông ta thức dậy, cả không gian hư vô dường như tối đi một chút."
  },
  AvgDialog_52003_Content_24 = {
    Text = "Ở phía sau anh ta, hình dáng mờ ảo của một người cao tuổi hiện ra."
  },
  AvgDialog_52003_Content_25 = {
    Text = "Thưa chủ nhân, ngài đã nghe thấy giọng của nàng rồi."
  },
  AvgDialog_52003_Content_26 = {
    Text = "Người được các vì sao báo hiệu, có phải chính là cô ấy?"
  },
  AvgDialog_52003_Content_27 = {
    Text = "Là cô ấy, tôi đã kiểm tra rồi. Nếu những gì các vì sao chỉ không sai, cô ấy… sẽ trở thành tương lai của Lemuria."
  },
  AvgDialog_52003_Content_28 = {
    Text = "Bạn không nghĩ như vậy."
  },
  AvgDialog_52003_Content_29 = {
    Text = "Có tài năng, nhưng có tạp niệm. Cô ấy không thể giúp đỡ ngài, thưa ngài."
  },
  AvgDialog_52003_Content_3 = {
    Text = "Ánh sáng trong phòng cầu nguyện trở nên mờ tối, bức tượng phía trước lấp lánh ánh hào quang huyền bí mờ ảo."
  },
  AvgDialog_52003_Content_30 = {
    Text = "Cô ấy không tin vào lời cầu nguyện, không tin vào ngài, cũng không tin vào tương lai của Lemuria. Cô ấy chỉ tin vào gia đình của mình."
  },
  AvgDialog_52003_Content_31 = {
    Text = "Miriam là người sống thực tế. Kiểu người như cô ấy không thể gánh vác số phận của Lemuria."
  },
  AvgDialog_52003_Content_32 = {
    Text = "Sống trong thực tế thay vì ảo ảnh, đó chính là hy vọng của Dư."
  },
  AvgDialog_52003_Content_33 = {
    Text = "Mong ước tốt đẹp, thưa ngài. Sinh ra ở Lemuria, chúng tôi đều có trách nhiệm riêng cần phải gánh vác."
  },
  AvgDialog_52003_Content_34 = {
    Text = "Chúng ta không có lựa chọn. Dù là cô ấy, tôi, hay ngài, đều như nhau．"
  },
  AvgDialog_52003_Content_35 = {
    Text = "……chán chường. Tôi muốn nghỉ ngơi."
  },
  AvgDialog_52003_Content_36 = {
    Text = "Ông vẫy tay. Vị lão nhân cúi người chào ông, rồi biến mất trong hư vô vô tận."
  },
  AvgDialog_52003_Content_37 = {
    Text = "Trước khi ngủ, anh ta liếc nhìn những người đã dâng ánh sáng cho anh. Một tiếng thở dài lặng lẽ tan biến, mất hút trong hư vô vô tận."
  },
  AvgDialog_52003_Content_38 = {Text = "A!"},
  AvgDialog_52003_Content_39 = {
    Text = "Tiếp theo sau cảm giác rơi tự do khiến tim ngừng đập là một cơn đau nhói mạnh mẽ."
  },
  AvgDialog_52003_Content_4 = {
    Text = "Miriam lấy bản văn cầu nguyện trước mặt."
  },
  AvgDialog_52003_Content_40 = {
    Text = "Cơn đau không kéo dài lâu. Miriam rời khỏi không gian hư vô và nhìn quanh mình."
  },
  AvgDialog_52003_Content_41 = {
    Text = "Một số người không thể đọc hoặc tụng đọc kinh đã được mời ra khỏi phòng cầu nguyện, chỉ còn lại một phần nhỏ. Một số người đau khổ ngã xuống đất, còn những người khác thì đang nhắm mắt cầu nguyện, nụ cười hạnh phúc nở trên môi."
  },
  AvgDialog_52003_Content_42 = {
    Text = "Deborah ngồi bên cạnh cô, mỉm cười và từ từ mở mắt. Nhìn thấy vẻ mặt của Miriam, cô lộ ra vẻ quan tâm."
  },
  AvgDialog_52003_Content_5 = {Text = "A……"},
  AvgDialog_52003_Content_6 = {
    Text = "Những gì được viết trên giấy không phải là ngôn ngữ thông dụng của Lemuria, mà là một loại ký hiệu hình tượng phức tạp, có nhiều chiều không gian hơn so với không gian thực tế."
  },
  AvgDialog_52003_Content_7 = {
    Text = "Dấu hiệu đó đến từ thời cổ đại, hoặc thậm chí từ một thế giới khác, Miriam chưa bao giờ thấy. Nhưng khi đọc dấu hiệu này, ý nghĩa trong đó tự nhiên hiện lên trong tâm trí cô."
  },
  AvgDialog_52003_Content_8 = {
    Text = "Mỗi chữ đều chứa đựng một lượng thông tin khổng lồ, vô số kinh văn tuôn vào não bộ của Miriam, khiến cái đầu người yếu đuối khó lòng gánh chịu."
  },
  AvgDialog_52003_Content_9 = {
    Text = "<Shake:đầu…… đầu đau quá……>"
  },
  AvgDialog_52004_Content_1 = {
    Text = "Chỉ cần tin vào Vua, Vua sẽ đáp lại niềm tin của bạn…"
  },
  AvgDialog_52004_Content_10 = {
    Text = "Nguyện cho ánh mắt tinh tường của ngài nhìn thấu tai họa, \nnguyện cho trí tuệ của ngài dẫn dắt con dân."
  },
  AvgDialog_52004_Content_11 = {
    Text = "\"Nguyện cho đôi mắt sáng của ngài nhìn thấu tai ương, \n nguyện cho trí tuệ của ngài dẫn dắt con dân.!\""
  },
  AvgDialog_52004_Content_12 = {
    Text = "Bão tố im lìm, sóng nước không gợn;\nđộng đất yên lặng, mặt đất an lành."
  },
  AvgDialog_52004_Content_13 = {
    Text = "Thảm họa biến thành hư vô trong giấc mơ bình yên của bạn. \ntrong sự bảo vệ của bạn, chúng tôi đón chào vương quốc của thần."
  },
  AvgDialog_52004_Content_14 = {
    Text = "\"Thảm họa biến thành hư vô trong giấc mơ tĩnh lặng của bạn!\""
  },
  AvgDialog_52004_Content_15 = {
    Text = "\"Trong sự bảo vệ của ngài, \n chúng tôi đón chào vương quốc của thần…\""
  },
  AvgDialog_52004_Content_16 = {
    Text = "Rầm……"
  },
  AvgDialog_52004_Content_17 = {
    Text = "Trong tiếng gầm rú, nhiều xúc tu khổng lồ chui ra từ dưới đền thần."
  },
  AvgDialog_52004_Content_18 = {
    Text = "Là vua! Diệu kỳ của vua đã xuất hiện!!!"
  },
  AvgDialog_52004_Content_19 = {
    Text = "Các tín đồ dang rộng đôi tay, reo hò cuồng nhiệt."
  },
  AvgDialog_52004_Content_2 = {
    Text = "Vậy, hãy nói cho tôi biết, bạn có tin vào Vua không? Bạn có sẵn lòng đem hết thảy dâng cho Vua không?"
  },
  AvgDialog_52004_Content_20 = {
    Text = "Tua rung động nhẹ nhàng trong mưa gió, tất cả mọi người ở Lemuria đều không nghi ngờ gì rằng, những vị thần vĩ đại của Lemuria có lực lượng để chống lại mọi thảm họa."
  },
  AvgDialog_52004_Content_21 = {
    Text = "Chủ nhân của tôi, tulô ——"
  },
  AvgDialog_52004_Content_22 = {
    Text = "Chủ nhân, tulô! Tulô!!!"
  },
  AvgDialog_52004_Content_23 = {
    Text = "Cô ấy quay người, nhìn về hướng bên trong đền thần, và quỳ gục xuống đất."
  },
  AvgDialog_52004_Content_24 = {
    Text = "Trong con mắt mà không ai có thể thấy, không còn chút hy vọng và uy nghiêm của bất kỳ chủ tế nào, chỉ còn lại nỗi băn khoăn."
  },
  AvgDialog_52004_Content_25 = {
    Text = "Xin hãy lắng nghe lời kêu gọi của tín đồ của Ngài. Xin hãy mang đến cho chúng tôi thiên đường."
  },
  AvgDialog_52004_Content_26 = {
    Text = "Hãy mang đến cho chúng tôi, thần quốc!"
  },
  AvgDialog_52004_Content_27 = {
    Text = "Chúa của tôi! Thần quốc! Hahaha… Thần quốc sắp đến rồi!"
  },
  AvgDialog_52004_Content_28 = {
    Text = "Kèm theo những tiếng la hét điên rồ, những xúc tu bắt đầu uốn lượn. Không khí tĩnh lặng của biển sâu từ những xúc tu truyền đến, thâm nhập vào giác quan của mỗi người Lemuria."
  },
  AvgDialog_52004_Content_29 = {
    Text = "Rầm——"
  },
  AvgDialog_52004_Content_3 = {
    Text = "Tôi tin vào Vua, ngài Chủ tế! Tôi sẵn sàng dâng hiến tất cả cho Vua!"
  },
  AvgDialog_52004_Content_30 = {
    Text = "Trong tiếng sấm rền, tiếng hoan hô lắng xuống. Tia chớp từ bầu trời chiếu sáng, soi rọi vùng đất cô đơn của Lemuria."
  },
  AvgDialog_52004_Content_31 = {
    Text = "Trong khoảnh khắc cuồng nhiệt này, các tín đồ dừng lại, chìm đắm trong sự ca tụng và niềm tin sâu sắc đối với Vương, và mơ về những hy vọng vô tận cho tương lai."
  },
  AvgDialog_52004_Content_32 = {
    Text = "Dưới cơn mưa lớn, người dân Lemuria chìm vào giấc ngủ sâu."
  },
  AvgDialog_52004_Content_4 = {
    Text = "Tôi là người theo dõi trung thành nhất của Vương!"
  },
  AvgDialog_52004_Content_5 = {
    Text = "Tôi nguyện! Thượng tế đại nhân, tôi nguyện!"
  },
  AvgDialog_52004_Content_6 = {
    Text = "Thì bây giờ, cùng tôi đọc tên của vua ——"
  },
  AvgDialog_52004_Content_7 = {
    Text = "Cô ấy nhìn xung quanh quảng trường, nhìn mọi người."
  },
  AvgDialog_52004_Content_8 = {
    Text = "Trong cơn bão tố, tất cả mọi người đều quỳ xuống, dang rộng hai tay, hướng ánh mắt đầy thành kính về phía ngai vàng trong đền thần."
  },
  AvgDialog_52004_Content_9 = {
    Text = "Dưới bầu trời sao lấp lánh, trên hòn đảo cô đơn giữa biển sâu, thành tâm cầu nguyện cho chủ nhân của tôi"
  },
  AvgDialog_52005_Content_1 = {
    Text = "Đúng vậy, cha… Chúng con sẽ gặp lại nhau ở thần quốc! Gia đình chúng ta sẽ sống cùng nhau ở thần quốc…"
  },
  AvgDialog_52005_Content_10 = {
    Text = "Thần quốc sắp đến rồi, cha. Rất nhanh, gia đình chúng ta sẽ đoàn tụ…"
  },
  AvgDialog_52005_Content_11 = {Text = "Phì——"},
  AvgDialog_52005_Content_12 = {
    Text = "Dao găm đâm mạnh vào ngực Inos, Inos phát ra tiếng gào thét đau đớn. Máu tươi phun ra, nhuộm đỏ nửa bên mặt phải của Miriam."
  },
  AvgDialog_52005_Content_13 = {
    Text = "Miriam mở to đôi mắt, chăm chú nhìn vào đường cắt giữa con dao găm và thịt, như thể đang ngắm một kiệt tác vô song."
  },
  AvgDialog_52005_Content_14 = {
    Text = "Dao găm lướt đi, trượt, cắt qua da và thịt xương. Inos khóc thét đau đớn, giống như một con thú đang bị xẻ xác."
  },
  AvgDialog_52005_Content_15 = {
    Text = "Tiếng gầm và dòng máu trong gian lễ, như những gai dày đặc, xuyên qua khuôn mặt và làn da của Miriam, đâm vào trái tim và phổi của cô."
  },
  AvgDialog_52005_Content_17 = {
    Text = "\"Tín đồ của Chúa, hãy mở rộng trái tim, đón nhận Chúa…\""
  },
  AvgDialog_52005_Content_18 = {
    Text = "Máu và nước mắt rửa sạch khuôn mặt méo mó của Miriam. Cô ấy đọc lời cầu nguyện, động tác trên tay càng lúc càng nhanh."
  },
  AvgDialog_52005_Content_19 = {
    Text = "Dao dừng lại. Trên thân thể của Inos, bằng xương thịt và máu của chính anh ta, vẽ nên những biểu tượng của hạnh phúc và hy vọng."
  },
  AvgDialog_52005_Content_2 = {
    Text = "Cô ấy gạt đi những giọt nước mắt trên khuôn mặt, từ từ đứng dậy và nhặt lấy con dao găm bên cạnh."
  },
  AvgDialog_52005_Content_20 = {
    Text = "\"Phàm thành tâm, chúa sẽ chiếu cố…\""
  },
  AvgDialog_52005_Content_21 = {
    Text = "<Big:\"Phàm kỳ nguyện, Chúa sẽ ứng hứa…\">"
  },
  AvgDialog_52005_Content_22 = {
    Text = "Cô ấy nâng máu thần lên, đổ vào những vết thương dạng biểu tượng trên người Inos."
  },
  AvgDialog_52005_Content_23 = {
    Text = "Ngay khi máu thần chạm vào những ký hiệu đó, giống như một con rắn cảm nhận được nguồn nhiệt của con mồi, trở nên sống động và hưng phấn."
  },
  AvgDialog_52005_Content_24 = {
    Text = "Không cần sự hướng dẫn của Miriam, chúng theo dõi nguồn nhiệt và chui vào cơ thể Inos thông qua những vết thương."
  },
  AvgDialog_52005_Content_25 = {
    Text = "Khi máu thần đổ vào, tiếng kêu thảm thiết của Inos càng trở nên dữ dội. Những vết thương trên người anh ta đang lành lại với tốc độ có thể nhìn thấy bằng mắt thường."
  },
  AvgDialog_52005_Content_26 = {
    Text = "Đồng thời, ngũ quan của hắn bắt đầu thoái hóa, đôi mắt trở nên to lớn và lồi ra, môi trở nên nhầy nhụa, hình dạng đầu cũng trở nên phẳng và dài."
  },
  AvgDialog_52005_Content_27 = {
    Text = "Một cơ quan mang hình dạng xuất hiện trên cổ anh ta, vảy thay thế lông mọc ra từ khắp nơi trên thân thể anh ta."
  },
  AvgDialog_52005_Content_28 = {
    Text = "Anh ta vẫn phát ra những âm thanh đau đớn, từ tiếng gào thét của một người đàn ông trưởng thành dần chuyển thành những tiếng rít mang theo hơi thở ẩm ướt và ô nhiễm của biển sâu……"
  },
  AvgDialog_52005_Content_29 = {
    Text = "Tôi đã thành công, cha... Tôi không làm cha thất vọng, phải không?"
  },
  AvgDialog_52005_Content_3 = {
    Text = "Dao găm cong theo một góc kỳ lạ, trên đó khắc các ký hiệu tượng hình phức tạp giống như trong lời cầu nguyện."
  },
  AvgDialog_52005_Content_30 = {
    Text = "Tiếng rít ngừng lại. Trí tuệ biến mất, con quái vật nửa người nửa cá nhìn cô bằng đôi mắt to trắng bệch, mơ hồ."
  },
  AvgDialog_52005_Content_31 = {
    Text = "Miriam đi đến bên cạnh bàn đá, vuốt ve con quái vật, cảm nhận mùi tanh đậm đặc của cá trong không khí và cảm giác dính nhớp trên tay."
  },
  AvgDialog_52005_Content_32 = {
    Text = "Mùi tanh và cảm giác chạm vào từng khiến cô cảm thấy kinh tởm, nhưng bây giờ, cô cảm nhận được sự ấm áp đặc biệt từ chúng."
  },
  AvgDialog_52005_Content_33 = {
    Text = "Tôi rất thích cá, đợi khi chúng ta tái ngộ ở thần quốc, mỗi ngày tôi sẽ thưởng thức món cá do bạn nấu…"
  },
  AvgDialog_52005_Content_34 = {
    Text = "Xin hãy đợi con, thưa cha."
  },
  AvgDialog_52005_Content_35 = {
    Text = "Cô cúi người, hôn lên khuôn mặt trơn láng và ẩm ướt của nó."
  },
  AvgDialog_52005_Content_4 = {
    Text = "Trong chậu đá bên cạnh con dao găm, máu tươi có nguồn gốc từ thần minh nhè nhẹ gợn sóng, ánh nến phản chiếu, tạo ra ánh đỏ xanh kỳ dị."
  },
  AvgDialog_52005_Content_5 = {
    Text = "Sự loạn trí nghiêm trọng khiến Inos mất đi phần lớn ý thức. Anh mở mắt, nhìn Miriam với vẻ tò mò, như đứa trẻ sơ sinh nhìn thế giới mới lạ trước mắt."
  },
  AvgDialog_52005_Content_6 = {
    Text = "Miriam, bây giờ cô đã trở thành linh mục rồi… Cô có hỏi vua chưa? Vua có nói với cô là thần quốc sẽ đến Lemuria vào thời điểm nào không?"
  },
  AvgDialog_52005_Content_7 = {
    Text = "Tôi đã hỏi rồi, cha… Vua nói, rất nhanh, rất nhanh…"
  },
  AvgDialog_52005_Content_8 = {
    Text = "Giữa những giọt nước mắt, xuất hiện một nụ cười đượm buồn. Cô đến bên cạnh Inos, cúi xuống, vuốt ve khuôn mặt anh."
  },
  AvgDialog_52005_Content_9 = {
    Text = "Tôi sẽ không làm cha thất vọng."
  },
  AvgDialog_54067_Content_1 = {
    Text = "Mơ về Lemuria"
  },
  AvgDialog_54067_Content_10 = {
    Text = "Tiếng ồn ào như đàn cá trong biển, bơi lượn quanh cô. Giữa cô và đàn cá, vùng nước lặng im mênh mông cuộn trào, và giọng nói của chính cô vang lên rõ ràng giữa không gian ấy."
  },
  AvgDialog_54067_Content_100 = {
    Text = "Cơn mưa dữ dội đánh vào thân thể khô héo của ông, gió mạnh hầu như muốn thổi ngã ông. Tại điểm cao nhất của Lemuria, vị lão nhânnhìn xa hòn đảo rộng lớn này."
  },
  AvgDialog_54067_Content_101 = {
    Text = "Mắt không còn sắc bén và già nua, chúng trong veo, sảng khoái và tò mò, giống như một đứa trẻ vừa chào đời, hân hoan quan sát vùng đất đầy thương tích này."
  },
  AvgDialog_54067_Content_102 = {
    Text = "\"hì hì hì... Lemuria, nơi đẹp đẽ biết bao.\""
  },
  AvgDialog_54067_Content_103 = {
    Text = "\"Bây giờ ngài đang nghĩ gì, chúa công?\""
  },
  AvgDialog_54067_Content_104 = {
    Text = "\"Quý vị luôn nói rằng, quý vị không quan tâm đến việc cứu vãn Lemuria, quý vị chỉ cảm thấy mệt mỏi. Nhưng vì Lemuria, quý vị đã giam mình trên ngai vàng, trong giấc mơ của chính mình.\""
  },
  AvgDialog_54067_Content_105 = {
    Text = "\"Thần minh đã biến mất, nhưng ngài vẫn đang tìm kiếm... Tôi chỉ là một kẻ lừa đảo, ngài mới là người bảo vệ vĩ đại nhất của Lemuria.\""
  },
  AvgDialog_54067_Content_106 = {
    Text = "\"Hãy nhìn thêm một lần nữa, bệ hạ. Hãy nhìn lần cuối cùng. Lemuria, quê hương của chúng ta...\""
  },
  AvgDialog_54067_Content_107 = {
    Text = "Người già ngẩng đầu, ánh mắt từ những người dân đang chìm vào giấc ngủ trên đảo, chuyển sang biển sôi động ở chân trời, rồi đến sấm sét dữ dội và mưa lạnh lùng trên bầu trời."
  },
  AvgDialog_54067_Content_108 = {
    Text = "Ông ta run rẩy đứng dậy, sự dịu dàng tan chảy trong đôi mắt thẳm sâu. Râu tóc và áo choàng bay phất phới trong gió, đôi mắt trở nên sắc bén như mũi kiếm đâm thẳng lên bầu trời."
  },
  AvgDialog_54067_Content_109 = {
    Text = "\"Sự lừa dối phức tạp, nhiệm vụ nhàm chán, lời hứa trang nghiêm, hãy để tất cả những thứ đó đi tong.\""
  },
  AvgDialog_54067_Content_11 = {
    Text = "\"……tulô, nhân danh chủ nhân của tôi thề:\""
  },
  AvgDialog_54067_Content_110 = {
    Text = "Anh ta ném bỏ cây gậy, dang rộng hai tay, chào đón cơn bão. Anh ta gào thét."
  },
  AvgDialog_54067_Content_111 = {
    Text = "\"Đến đây, thảm họa! Đến đây, thần minh hèn hạ!\""
  },
  AvgDialog_54067_Content_112 = {
    Text = "\"Tôi là đồng phạm của các bạn. Hãy cùng nhau, tiễn biệt Lemuria!\""
  },
  AvgDialog_54067_Content_114 = {
    Text = "Rầm——"
  },
  AvgDialog_54067_Content_115 = {
    Text = "Tiếng động trầm lặng, xuyên qua vô số bức tường đá dày, vang vọng trong cung điện của đền thần."
  },
  AvgDialog_54067_Content_116 = {
    Text = "Tulô dùng một tay chống cằm, mệt mỏi ngồi trên ngai vàng."
  },
  AvgDialog_54067_Content_117 = {
    Text = "Dân cư của Lemuria đã chìm vào giấc ngủ. Ông đã dùng hết lực lượng của mình, tặng họ một giấc mơ đẹp."
  },
  AvgDialog_54067_Content_118 = {
    Text = "「“Cơn bão Lemuria sẽ bình yên. Hố sâu Lemuria sẽ biến mất.”」"
  },
  AvgDialog_54067_Content_119 = {
    Text = "「“Vua sẽ che chở cho con dân lành thiện, mang lại vương quốc của Chúa…”」"
  },
  AvgDialog_54067_Content_12 = {
    Text = "\"Tôi là người hầu của Lemuria. Tôi là người hầu cận của đức vua.\""
  },
  AvgDialog_54067_Content_120 = {
    Text = "「Thật là châm biếm. Đó là ý chí của ngươi truyền đạt phải không, “Lemuria”?」"
  },
  AvgDialog_54067_Content_121 = {
    Text = "Anh ta ngẩng đầu lên, ánh mắt xuyên qua tấm bảng đá trên đỉnh đầu, xuyên qua cơn mưa dữ dội và những đám mây đen, hướng tới bầu trời đêm thăm thẳm, rồi tiến sâu hơn vào giấc mơ còn mênh mông hơn cảbầu trời sao."
  },
  AvgDialog_54067_Content_122 = {
    Text = "\"Bạn đã ra đi từ lâu... Bạn chưa bao giờ quan tâm đến Lemuria. Đúng không?\""
  },
  AvgDialog_54067_Content_123 = {
    Text = "\"Bạn cũng đang bị một ý chí cao hơn truy đuổi, săn lùng, bỏ rơi. Bạn và tôi đều là những linh hồn lang thang vô định.\""
  },
  AvgDialog_54067_Content_124 = {
    Text = "\"Người Lemuria, tin vào thần minh vô tình, và vị vua yếu đuối. Thần quốc... thôi, thật tẻ nhạt.\""
  },
  AvgDialog_54067_Content_125 = {
    Text = "\"Xin lỗi, nhưng lần này, tôi thực sự mệt rồi.\""
  },
  AvgDialog_54067_Content_126 = {
    Text = "Ông ta ngồi nghiêng trên ngai vàng, một tay chống dưới cằm, chìm vào giấc ngủ."
  },
  AvgDialog_54067_Content_127 = {
    Text = "Anh ấy và thần dân của mình đã bước vào cùng một giấc mơ. Ở đó, Lemuria nắng sáng, tiếng cười rộn ràng."
  },
  AvgDialog_54067_Content_128 = {
    Text = "Ông đã mang đến cho Lemuria thần quốc mà họ hằng mơ ước. Ông đã mang đến cho Lemuria lời dối trá mà họ mong muốn."
  },
  AvgDialog_54067_Content_129 = {
    Text = "Với lời dối trá, ông tiễn biệt quê hương. Đây là quyền lực và lòng từ bi cuối cùng của ông trong vai trò là vua của Lemuria."
  },
  AvgDialog_54067_Content_13 = {
    Text = "\"Tôi sẽ dẫn dắt con dân Lemuria. Tôi sẽ lắng nghe tiếng Đức Chúa, thi hành mệnh lệnh của Đức Chúa.\""
  },
  AvgDialog_54067_Content_131 = {Text = "Pa——"},
  AvgDialog_54067_Content_132 = {
    Text = "Đá vụn rơi xuống từ bức tượng. Bức tượng im lìm khổng lồ kia, nay đã bị hư hại nặng nề."
  },
  AvgDialog_54067_Content_133 = {
    Text = "\"Cha ơi, ngài xem... đó là nước mắt của vua. Chủ nhân của chúng ta đang than khóc cho Lemuria.\""
  },
  AvgDialog_54067_Content_134 = {
    Text = "Trong vòng tay cô ấy, một người cá lật đôi mắt to lớn, mơ màng nhìn xung quanh."
  },
  AvgDialog_54067_Content_135 = {
    Text = "Cô ấy không thể tìm thấy Inos, nên mỗi cá nhân đều trở thành Inos."
  },
  AvgDialog_54067_Content_136 = {
    Text = "Tiếng mưa to xâm nhập qua bức tường, càng lúc càng mạnh mẽ, mùi tanh nồng của người cá lan tỏa khắp phòng. Cô nhẹ nhàng vuốt ve nó."
  },
  AvgDialog_54067_Content_137 = {
    Text = "\"Giáo viên, Vương... họ dường như đã từ bỏ.\""
  },
  AvgDialog_54067_Content_138 = {
    Text = "\"Tôi... sẽ không từ bỏ... Tôi có thể cứu Lemuria, tôi có thể đưa Lemuria trở lại. Đây là điều Vua đã nói với tôi.\""
  },
  AvgDialog_54067_Content_139 = {
    Text = "\"Mẹ đã chết, em gái cũng đã chết, còn cha... thì cũng không còn nữa.\""
  },
  AvgDialog_54067_Content_14 = {
    Text = "\"Thần quốc sẽ đến, tôi sẽ cùng tất cả các tín đồ nghênh đón.\""
  },
  AvgDialog_54067_Content_140 = {
    Text = "\"Tôi rất sợ, Miriam. Tôi sợ những điều chúng ta làm đều không có ý nghĩa...\""
  },
  AvgDialog_54067_Content_141 = {
    Text = "\"Đã có quá nhiều thảm họa, cha chỉ là một người bình thường, nhưng ông ấy chưa bao giờ sợ hãi, cũng không bao giờ từ bỏ.\""
  },
  AvgDialog_54067_Content_142 = {
    Text = "\"Chúng tôi là chủ tế của Lemuria, chúng tôi cũng tuyệt đối không bỏ cuộc... Đây là điều cha tôi đã dạy tôi.\""
  },
  AvgDialog_54067_Content_143 = {
    Text = "Cô ấy mỉm cười, an ủi nhẹ nhàng. Nước mắt tuôn rơi, hòa lẫn với những lời nói mà chính cô cũng không rõ là thật hay giả, nhỏ xuống vảy của người cá, phản chiếu ánh sáng u ám."
  },
  AvgDialog_54067_Content_144 = {
    Text = "Rầm rầm rầm——"
  },
  AvgDialog_54067_Content_145 = {
    Text = "Đất dưới chân bỗng nhiên rung chuyển. Các cột đá kiên cố của đền thần cố gắng chống đỡ, các tấm đá trên đầu dần dần vỡ vụn, rơi xuống đất."
  },
  AvgDialog_54067_Content_146 = {
    Text = "Trong cơn rung động dữ dội này, phần còn lại của tượng sụp đổ tan tành. Tiếng bão tố và động đất vang lên như tiếng trống từng hồi, đập mạnh vào màng nhĩ của Miriam."
  },
  AvgDialog_54067_Content_147 = {
    Text = "Cô ấy nhắm mắt, quỳ trước bức tượng bị hư hại, cầm lấy bàn tay nhỏ nhắn của Miriam."
  },
  AvgDialog_54067_Content_148 = {
    Text = "\"Lắng nghe Đức Chúa, quy y Đức Chúa, ca ngợi Đức Chúa...\""
  },
  AvgDialog_54067_Content_149 = {
    Text = "\"Hễ ai gặp khổ nạn, Chúa sẽ đền bù. \nHễ ai phạm tội lỗi, Chúa sẽ trừng phạt...\""
  },
  AvgDialog_54067_Content_15 = {
    Text = "Rầm——"
  },
  AvgDialog_54067_Content_150 = {
    Text = "Sự rung động không dừng lại, ánh sáng dường như trở nên tối dần. Ở xa trên biển, một bức tường màu xanh dương đậm cao vút lên đến bầu trời ——"
  },
  AvgDialog_54067_Content_151 = {
    Text = "Biển cả đứng dậy, như một người khổng lồ thức tỉnh, tiến về phía Lemuria."
  },
  AvgDialog_54067_Content_152 = {
    Text = "Trước biển cả, vương quốc huy hoàng này nhỏ bé và yếu đuối như một chiếc lá khô."
  },
  AvgDialog_54067_Content_153 = {
    Text = "\"Phàm thành tâm, người chủ sẽ chiếu cố.\""
  },
  AvgDialog_54067_Content_154 = {
    Text = "\"Phàm điều mong ước, chúa ta sẽ ban cho... sẽ ban cho...\""
  },
  AvgDialog_54067_Content_155 = {
    Text = "Cơn bão cuồng nộ tấn công vào đền thần yếu đuối, lật tung những tấm bảng đá nặng nề và nền móng kiên cố."
  },
  AvgDialog_54067_Content_156 = {
    Text = "Ánh sáng còn lại hầu như bị đại dương dựng đứng che khuất hoàn toàn. Trong đống hoang tàn u ám và đổ nát, cô ấy ôm chặt lấy người cá trong lòng."
  },
  AvgDialog_54067_Content_157 = {
    Text = "Hơi thở của cái chết từ đáy đại dương bao quanh cô ấy. Nước mắt ngập tràn trong đôi mắt của cô."
  },
  AvgDialog_54067_Content_159 = {
    Text = "\"Chúa của tôi... niềm tin của tôi ở bên ngài, cho đến tận cùng của các vì sao...\""
  },
  AvgDialog_54067_Content_16 = {
    Text = "Một tia sét nổ vang trên bầu trời Lemuria."
  },
  AvgDialog_54067_Content_160 = {
    Text = "\"Ngài không lừa tôi, thần quốc sẽ đến, phải không, thưa ngài?\""
  },
  AvgDialog_54067_Content_161 = {
    Text = "Lần cuối cùng, cô ấy ngẩng đầu lên, nhìn chằm chằm vào nơi bức tượng của vua từng đứng với vẻ tuyệt vọng."
  },
  AvgDialog_54067_Content_162 = {
    Text = "Ở đó không có tượng, và cũng chẳng có vị vua nào."
  },
  AvgDialog_54067_Content_164 = {
    Text = "<Big:ầm—>"
  },
  AvgDialog_54067_Content_165 = {
    Text = "Đại dương đã đến trước mặt Cây Lá Khô."
  },
  AvgDialog_54067_Content_167 = {
    Text = "Lịch cũ năm thứ 3, Lemuria chìm xuống biển sâu, không ai sống sót."
  },
  AvgDialog_54067_Content_17 = {
    Text = "Tiếng động lớn làm cho đám đông dần trở nên im lặng."
  },
  AvgDialog_54067_Content_18 = {
    Text = "Thảm họa… lại bắt đầu rồi, phải không?"
  },
  AvgDialog_54067_Content_19 = {
    Text = "Thưa ngài Chủ tế… Đây là… Đại họa sắp đến rồi chăng?"
  },
  AvgDialog_54067_Content_2 = {
    Text = "Gió gào thét cuốn theo cơn mưa, tạt vào những người trên quảng trường."
  },
  AvgDialog_54067_Content_20 = {
    Text = "Thảm họa chưa bao giờ biến mất. Lemuria ngủ cùng thảm họa."
  },
  AvgDialog_54067_Content_21 = {
    Text = "Nhưng Lemuria vẫn tồn tại, phải không?"
  },
  AvgDialog_54067_Content_22 = {
    Text = "Đúng… đúng…"
  },
  AvgDialog_54067_Content_23 = {
    Text = "Thưa ngài Chủ tế, thần quốc… thần quốc khi nào mới đến?"
  },
  AvgDialog_54067_Content_24 = {
    Text = "Sắp rồi, bạn của tôi."
  },
  AvgDialog_54067_Content_25 = {
    Text = "Rất nhanh?!"
  },
  AvgDialog_54067_Content_26 = {
    Text = "Vâng,rất nhanh…"
  },
  AvgDialog_54067_Content_27 = {
    Text = "Miriam đã rời khỏi sự bảo vệ của vệ sĩ và đến bên bàn thờ."
  },
  AvgDialog_54067_Content_28 = {
    Text = "Vô số bàn tay vươn ra, các tín đồ chen lấn cuồn cuộn về phía cô, khao khát nhận được sự chúc phúc của chủ tế Lemuria."
  },
  AvgDialog_54067_Content_29 = {
    Text = "Cô quét mắt một lượt, ánh mắt bình tĩnh, nụ cười nhẹ nhàng, nhưng ánh nhìn ấy đã khiến đám đông tín đồ nhanh chóng im bặt."
  },
  AvgDialog_54067_Content_3 = {
    Text = "Người ta đã lâu không thấy cơn mưa lớn như vậy, nhưng tiếng kêu của họ vẫn át đi tiếng gầm thét giận dữ của hòn đảo."
  },
  AvgDialog_54067_Content_30 = {
    Text = "Trong tiếng ồn ào của gió mưa, cô ấy đưa tay ra, chạm vào trán của người tín đồ."
  },
  AvgDialog_54067_Content_31 = {
    Text = "Tín đồ đưa hai tay ôm trước ngực, rồi quỳ xuống đất."
  },
  AvgDialog_54067_Content_32 = {
    Text = "Chỉ cần tin vào Vua, Vua sẽ đáp lại niềm tin của bạn…"
  },
  AvgDialog_54067_Content_33 = {
    Text = "Vậy, hãy nói cho tôi biết, bạn có tin vào Vua không? Bạn có sẵn lòng đem hết thảy dâng cho Vua không?"
  },
  AvgDialog_54067_Content_34 = {
    Text = "Tôi tin vào Vua, ngài Chủ tế! Tôi sẵn sàng dâng hiến tất cả cho Vua!"
  },
  AvgDialog_54067_Content_35 = {
    Text = "Tôi là người theo dõi trung thành nhất của Vương!"
  },
  AvgDialog_54067_Content_36 = {
    Text = "Tôi nguyện! Thượng tế đại nhân, tôi nguyện!"
  },
  AvgDialog_54067_Content_37 = {
    Text = "Thì bây giờ, cùng tôi đọc tên của vua ——"
  },
  AvgDialog_54067_Content_38 = {
    Text = "Cô ấy nhìn xung quanh quảng trường, nhìn mọi người."
  },
  AvgDialog_54067_Content_39 = {
    Text = "Trong cơn bão tố, tất cả mọi người đều quỳ xuống, dang rộng hai tay, hướng ánh mắt đầy thành kính về phía ngai vàng trong đền thần."
  },
  AvgDialog_54067_Content_4 = {
    Text = "Thưa Đại tế tự!Đại tế tự đã mang đến cho chúng ta thần dụ của vua!"
  },
  AvgDialog_54067_Content_40 = {
    Text = "Dưới bầu trời sao lấp lánh, trên vương quốc cổ đại biển sâu, cầu nguyện thành tâm cho chủ nhân của tôi"
  },
  AvgDialog_54067_Content_41 = {
    Text = "Nguyện cho ánh mắt tinh tường của ngài nhìn thấu tai họa, \nnguyện cho trí tuệ của ngài dẫn dắt con dân."
  },
  AvgDialog_54067_Content_42 = {
    Text = "\"Nguyện cho đôi mắt sáng của ngài nhìn thấu tai họa, \n nguyện cho trí tuệ của ngài dẫn dắt con dân!\""
  },
  AvgDialog_54067_Content_43 = {
    Text = "Bão tố im lìm, sóng nước không gợn;\ndao động dần lắng xuống, mặt đất bình yên."
  },
  AvgDialog_54067_Content_44 = {
    Text = "Thảm họa biến thành hư vô trong giấc mơ bình yên của bạn. \ntrong sự bảo vệ của bạn, chúng tôi đón chào vương quốc của thần."
  },
  AvgDialog_54067_Content_45 = {
    Text = "\"Thảm họa biến thành hư vô trong giấc mơ tĩnh lặng của bạn!\""
  },
  AvgDialog_54067_Content_46 = {
    Text = "\"Trong sự bảo vệ của ngài, \n chúng tôi đón chào vương quốc của thần…\""
  },
  AvgDialog_54067_Content_47 = {
    Text = "Rầm……"
  },
  AvgDialog_54067_Content_48 = {
    Text = "Trong tiếng gầm rú, nhiều xúc tu khổng lồ chui ra từ dưới đền thần."
  },
  AvgDialog_54067_Content_49 = {
    Text = "Là vua! Diệu kỳ của vua đã xuất hiện!!!"
  },
  AvgDialog_54067_Content_5 = {
    Text = "Chúc tụng Chúa của chúng ta! Xin chúc tụng ngài Chủ tế!"
  },
  AvgDialog_54067_Content_50 = {
    Text = "Các tín đồ dang rộng đôi tay, reo hò cuồng nhiệt."
  },
  AvgDialog_54067_Content_51 = {
    Text = "Tua rung động nhẹ nhàng trong mưa gió, tất cả mọi người ở Lemuria đều không nghi ngờ gì rằng, những vị thần vĩ đại của Lemuria có lực lượng để chống lại mọi thảm họa."
  },
  AvgDialog_54067_Content_52 = {
    Text = "Chủ nhân của tôi, tulô ——"
  },
  AvgDialog_54067_Content_53 = {
    Text = "Chủ nhân, tulô! Tulô!!!"
  },
  AvgDialog_54067_Content_54 = {
    Text = "Cô ấy quay người, nhìn về hướng bên trong đền thần, và quỳ gục xuống đất."
  },
  AvgDialog_54067_Content_55 = {
    Text = "Trong con mắt mà không ai có thể thấy, không còn chút hy vọng và uy nghiêm của bất kỳ chủ tế nào, chỉ còn lại nỗi băn khoăn."
  },
  AvgDialog_54067_Content_56 = {
    Text = "Xin hãy lắng nghe lời kêu gọi của tín đồ của Ngài. Xin hãy mang đến cho chúng tôi thiên đường."
  },
  AvgDialog_54067_Content_57 = {
    Text = "Hãy mang đến cho chúng tôi, thần quốc!"
  },
  AvgDialog_54067_Content_58 = {
    Text = "Chúa của tôi! Thần quốc! Hahaha… Thần quốc sắp đến rồi!"
  },
  AvgDialog_54067_Content_59 = {
    Text = "Kèm theo những tiếng la hét điên rồ, các xúc tu bắt đầu vũ động. Không khí tĩnh lặng của biển sâu từ các xúc tu lan truyền, từ đền thần đến từng tấc đất của Lemuria, thấm sâu vào giác quan của người Lemuria."
  },
  AvgDialog_54067_Content_6 = {
    Text = "Đại tế tự sẽ dẫn chúng ta đến gặp thần quốc!"
  },
  AvgDialog_54067_Content_60 = {
    Text = "Rầm——"
  },
  AvgDialog_54067_Content_61 = {
    Text = "Trong tiếng sấm rền, tiếng hoan hô lắng xuống. Tia chớp từ bầu trời chiếu sáng, soi rọi vùng đất cô đơn của Lemuria."
  },
  AvgDialog_54067_Content_62 = {
    Text = "Trong khoảnh khắc cuồng nhiệt này, các tín đồ dừng lại, chìm đắm trong sự ca tụng và niềm tin sâu sắc đối với Vương, và mơ về những hy vọng vô tận cho tương lai."
  },
  AvgDialog_54067_Content_63 = {
    Text = "Dưới cơn mưa lớn, người dân Lemuria chìm vào giấc ngủ sâu."
  },
  AvgDialog_54067_Content_65 = {
    Text = "Tiếng cửa bảng đá đóng lại trở nên kéo dài và nặng trĩu."
  },
  AvgDialog_54067_Content_66 = {
    Text = "Mùi tanh nồng của cá ngập tràn cả căn phòng. Phòng cầu nguyện vốn rộng rãi và tĩnh lặng bỗng trở nên chật chội vô cùng."
  },
  AvgDialog_54067_Content_67 = {
    Text = "Tất cả những ngư nhân đều được vớt lên từ bể nước và đặt trên sàn phòng cầu nguyện."
  },
  AvgDialog_54067_Content_68 = {
    Text = "Các vệ sĩ không biết vị chủ tế mới muốn làm gì, và họ không còn cơ hội biết thêm."
  },
  AvgDialog_54067_Content_69 = {
    Text = "Miriam đến góc phòng, cúi người xuống và vuốt ve người cá gần mình nhất."
  },
  AvgDialog_54067_Content_7 = {
    Text = "Tiếng reo hò cuồng nhiệt như sóng biển, cuồn cuộn đổ về phía bàn thờ."
  },
  AvgDialog_54067_Content_70 = {
    Text = "\"Cha... có phải ông không?\""
  },
  AvgDialog_54067_Content_71 = {
    Text = "\"Tôi là Miriam, con gái ngài.\""
  },
  AvgDialog_54067_Content_72 = {
    Text = "\"Nếu con có thể nghe thấy, hãy đáp lại, được không? Cha...\""
  },
  AvgDialog_54067_Content_73 = {
    Text = "\"...ư...ư...\""
  },
  AvgDialog_54067_Content_74 = {
    Text = "Đôi mang của người cá mở ra rồi khép lại, đôi môi cử động lên xuống, phát ra những tiếng rên rỉ không rõ nghĩa, giống hệt giọng nói thường ngày."
  },
  AvgDialog_54067_Content_75 = {
    Text = "Miriam đi đến con thứ hai, cúi người xuống và vuốt ve nó."
  },
  AvgDialog_54067_Content_76 = {
    Text = "\"Cha ơi, con đã trở thành chủ tế của Lemuria, con đã làm tốt hơn những gì cha từng mơ ước...\""
  },
  AvgDialog_54067_Content_77 = {
    Text = "\"Tôi không làm bố thất vọng... Hãy mở mắt ra và nhìn tôi đi...\""
  },
  AvgDialog_54067_Content_78 = {
    Text = "Người cá nhìn bừa bãi quanh nơi lạ lẫm này bằng đôi mắt to lớn, không hề tỏ ra hứng thú với vị chủ tế trước mặt."
  },
  AvgDialog_54067_Content_79 = {
    Text = "Cô ấy đi đến con thứ ba."
  },
  AvgDialog_54067_Content_8 = {
    Text = "Dòng người nhộn nhịp khiến Miriam nhớ đến những con cá trong bể, đôi mắt mở to."
  },
  AvgDialog_54067_Content_80 = {
    Text = "\"Tôi đã gặp vua, vị vua chúng tôi tôn sùng... nhưng vua bảo tôi rằng Lemuria sắp bị diệt vong.\""
  },
  AvgDialog_54067_Content_81 = {
    Text = "\"Vua nói, ta có thể cứu Lemuria, ta có thể đưa Lemuria trở lại...\""
  },
  AvgDialog_54067_Content_82 = {
    Text = "\"Tôi không thể tin lời của vua, nhưng nếu vậy, tôi chỉ còn cách tin rằng chúng ta luôn sống trong dối trá, mọi việc chúng ta làm, những điều tôi đã làm với bạn... những chuyện đó, đều không có ý nghĩa gì cả.\""
  },
  AvgDialog_54067_Content_83 = {
    Text = "\"Tôi không biết, tôi không biết... Bố ơi, tôi phải làm sao?\""
  },
  AvgDialog_54067_Content_84 = {
    Text = "\"Mở mắt ra nhìn con đi, cha... nói chuyện với con, sờ đầu con một cái, chỉ một cái thôi...\""
  },
  AvgDialog_54067_Content_85 = {
    Text = "Người cá nhìn chằm chằm vào nó. Đôi mắt trống rỗng, như thể đang nhìn một cây cỏ nước màu tím nhẹ nhàng đung đưa."
  },
  AvgDialog_54067_Content_86 = {
    Text = "Miriam đi đến con tiếp theo, rồi con nữa… Cô ấy cúi xuống, vuốt ve nhẹ nhàng và hôn đầy yêu thương từng con."
  },
  AvgDialog_54067_Content_87 = {
    Text = "Thầy mang đến cho cô trách nhiệm, vua mang đến cho cô hy vọng. Người có thể lắng nghe nỗi đau và bối rối, cũng như an ủi cô bằng cách vuốt ve đầu cô, đã sớm không còn nữa."
  },
  AvgDialog_54067_Content_88 = {
    Text = "Cô ấy từng con ghé sát tai chúng, thì thầm với chúng, tìm kiếm trong số chúng."
  },
  AvgDialog_54067_Content_89 = {
    Text = "Bố còn sống không? Người cá còn sống sót kia, có còn được coi là bố của mình không?"
  },
  AvgDialog_54067_Content_9 = {
    Text = "Như chìm vào biển sâu, nước biển ngập các giác quan của cô. Hình ảnh trở nên mờ ảo, âm thanh trở nên hỗn loạn."
  },
  AvgDialog_54067_Content_90 = {
    Text = "Cô ấy không biết, cũng không quan tâm."
  },
  AvgDialog_54067_Content_91 = {
    Text = "Tiếng mưa lớn xuyên qua tường truyền vào. Trong căn phòng cầu nguyện rộng lớn, vô số người cá nằm trên mặt đất, vẫy động chi và vây đuôi của chúng."
  },
  AvgDialog_54067_Content_92 = {
    Text = "Một bóng dáng màu tím, len lỏi giữa những người cá, tìm kiếm, thuật lại."
  },
  AvgDialog_54067_Content_93 = {
    Text = "Nửa bức tượng bị vỡ, ngồi trên ngai vàng đã bị hủy hoại, lặng lẽ dõi theo cô."
  },
  AvgDialog_54067_Content_95 = {
    Text = "Rầm——"
  },
  AvgDialog_54067_Content_96 = {
    Text = "Sấm sét vang lên trên đầu vị lão nhân. Ông không để ý, bước lên bậc thạch cuối cùng."
  },
  AvgDialog_54067_Content_97 = {
    Text = "\"hu... hu...\""
  },
  AvgDialog_54067_Content_98 = {
    Text = "Ông ấy đã quá già, leo lên núi một mình đối với ông ấy là một việc vô cùng khó khăn."
  },
  AvgDialog_54067_Content_99 = {
    Text = "Anh ta ngồi bệt trên đỉnh núi trọc, thở hổn hển, phổi như những cối xay gió rỉ sét, phát ra tiếng kêu già yếu."
  },
  AvgDialog_54802_Content_1 = {Text = "À!——"},
  AvgDialog_54802_Content_10 = {
    Text = "Đó... đó là.."
  },
  AvgDialog_54802_Content_100 = {
    Text = "Bàn tay đầy vết thương đưa một bông hồng có phần tàn tạ nhưng vẫn còn tươi đỏ đến trước mặt Orla."
  },
  AvgDialog_54802_Content_101 = {
    Text = "Một bài thơ hay, Ôrla… Sau này, tôi sẽ dùng hoa của mình để đổi lấy thơ của bạn!"
  },
  AvgDialog_54802_Content_11 = {
    Text = "Các ngươi đang đứng ở quảng trường bên cạnh vườn. Những vết rã nứt rỗng rỗng từ dưới tòa nhà nhỏ lan lên, bao trùm khoảng trống giữa vườn."
  },
  AvgDialog_54802_Content_12 = {
    Text = "Đó là……vườn của chúng ta……không……Colette, không……"
  },
  AvgDialog_54802_Content_13 = {
    Text = "Ôrla cúi đầu xuống. Colette bước đến bên cô, nhẹ nhàng nâng cằm cô lên, để mắt cô nhìn vào giữa vườn."
  },
  AvgDialog_54802_Content_14 = {
    Text = "Bạn có biết không, Ôrla. Nhiều năm trước, ngay tại đây, tôi đã chứng kiến ngọn lửa kia bùng lên."
  },
  AvgDialog_54802_Content_15 = {
    Text = "Tôi đã cải tạo nơi này thành quảng trường, dựng tượng của tôi ở đây… Bạn thấy đấy, tôi cũng hiểu về biểu tượng."
  },
  AvgDialog_54802_Content_16 = {
    Text = "Nhìn đây. Nhìn kỹ đi. Đó là nơi chúng ta sống… Đó là khu vườn của chúng ta. Rất nhanh, mọi thứ ở đó sẽ biến mất."
  },
  AvgDialog_54802_Content_17 = {
    Text = "Sức sống của tôi, chính thức bắt đầu từ ngày bạn chết. Hôm nay, nó sẽ một lần nữa đạt đến vinh quang ở đây…"
  },
  AvgDialog_54802_Content_18 = {
    Text = "Khe nứt màu đen nhanh chóng lan rộng. Rất nhanh, biệt thự hoành tráng đã bị nuốt chửng hoàn toàn."
  },
  AvgDialog_54802_Content_19 = {
    Text = "Vườn hoa, tro tàn, nét vẽ mộc mạc, thơ ca, ký ức, tiếng cười, lời thề… tất cả đều chìm dần vào bóng tối vô tận."
  },
  AvgDialog_54802_Content_2 = {
    Text = "Sự tấn công bất ngờ của các bạn đã đánh bại Colette, nhưng ngay khi các bạn tiến gần, vô số dây hoa bỗng chui ra từ đất quanh cô ấy."
  },
  AvgDialog_54802_Content_20 = {
    Text = "Tí tách——"
  },
  AvgDialog_54802_Content_21 = {
    Text = "Hử? Mắt tôi, chuyện gì đang xảy ra…"
  },
  AvgDialog_54802_Content_22 = {
    Text = "Cảm giác vừa rồi là… đau lòng? Tại sao lại…"
  },
  AvgDialog_54802_Content_23 = {
    Text = "Một giọt nước mắt lăn xuống khuôn mặt của Ôrla."
  },
  AvgDialog_54802_Content_24 = {
    Text = "Nước mắt rơi xuống đất, như rơi vào mặt hồ không gợn sóng. Những gợn sóng yên lặng lan tỏa, nhẹ nhàng lướt qua, tất cả những trái tim nhợt nhạt trong thế giới hư ảo này."
  },
  AvgDialog_54802_Content_25 = {
    Text = "!! Không đúng……cảm giác này……"
  },
  AvgDialog_54802_Content_26 = {
    Text = "Kollette cảm nhận được sự thay đổi cảm xúc của mình. Cô ngạc nhiên nhìn sang bên cạnh Ôrla."
  },
  AvgDialog_54802_Content_27 = {
    Text = "<LightGray:Đây……là khả năng truyền cảm xúc của Ôrla?!>"
  },
  AvgDialog_54802_Content_28 = {
    Text = "<LightGray:thâm cảnh này dựa trên bài thơ của Ôrla…… có lẽ khả năng của cô ấy sẽ phát huy tác dụng!>"
  },
  AvgDialog_54802_Content_29 = {
    Text = "Bạn muốn giết tôi, dùng tập thơ để đổi lấy cuộc sống mà bạn mong muốn…… Dù bạn làm gì, tôi chưa bao giờ ghét bạn, Cô-lết."
  },
  AvgDialog_54802_Content_3 = {
    Text = "Những gai nhọn trên dây hoa đâm vào thân thể các người, trói chặt các người."
  },
  AvgDialog_54802_Content_30 = {
    Text = "Cô bé Colette ngày xưa là người bạn tốt nhất của tôi. Nhưng nếu nơi này bị phá hủy… thì chỉ còn lại Cô bé Colette hiện tại mà thôi."
  },
  AvgDialog_54802_Content_31 = {
    Text = "Tôi không thể……nhìn thấy Cô Lét trước kia bị xóa sổ bởi bạn……"
  },
  AvgDialog_54802_Content_32 = {
    Text = "Hãy nhìn bạn đây, Ôrla… Ngoài việc làm thơ, Ôrla còn biết làm gì nữa?"
  },
  AvgDialog_54802_Content_33 = {
    Text = "Bạn nói đúng… ngoài việc làm thơ, tôi chẳng biết làm gì khác…"
  },
  AvgDialog_54802_Content_34 = {
    Text = "Tây Đài là thành phố của hoa và thơ, là quê hương của chúng ta… nhưng những bông hồng ở đây đều đã chết, Colette…"
  },
  AvgDialog_54802_Content_35 = {
    Text = "Những bông hồng này, là những gì bạn đã tặng tôi. Hôm nay tôi trả lại chúng cho bạn."
  },
  AvgDialog_54802_Content_36 = {
    Text = "Cô ấy tiến lên một bước."
  },
  AvgDialog_54802_Content_37 = {Text = "Ôrla!!!"},
  AvgDialog_54802_Content_38 = {
    Text = "Những gai hồng khổng lồ đã xuyên thủng trái tim của cô ấy."
  },
  AvgDialog_54802_Content_39 = {
    Text = "Máu của cô ấy chảy dọc theo những dây leo đen."
  },
  AvgDialog_54802_Content_4 = {
    Text = "Bạn... đã làm bẩn quần áo của tôi.."
  },
  AvgDialog_54802_Content_40 = {
    Text = "Những bông hoa đen nhanh chóng héo úa trên cành."
  },
  AvgDialog_54802_Content_41 = {
    Text = "Một bông hồng đỏ, từ cành cây nhô ra nụ hoa, bung tỏa nhẹ nhàng, nở rộ."
  },
  AvgDialog_54802_Content_42 = {
    Text = "Máu tươi chảy theo dây leo, giống như mạch máu của lá cây, lan tỏa đến mọi ngõ ngách của thành phố."
  },
  AvgDialog_54802_Content_43 = {
    Text = "Nơi nó đi qua, bóng tối mờ ảo dần tan biến."
  },
  AvgDialog_54802_Content_44 = {
    Text = "Nó đã trả lại màu sắc và cảm xúc, hoa và thơ, cho Tây Đài."
  },
  AvgDialog_54802_Content_45 = {
    Text = "Đau... thật là đau.."
  },
  AvgDialog_54802_Content_46 = {
    Text = "Trái tim…… có vẻ như đã bị xuyên thủng……"
  },
  AvgDialog_54802_Content_47 = {
    Text = "Đó là……mẹ! Mẹ"
  },
  AvgDialog_54802_Content_48 = {
    Text = "Con yêu……con của tôi đã chào đời rồi……"
  },
  AvgDialog_54802_Content_49 = {
    Text = "Dòng máu loang rộng, từng cảnh tượng dần hiện lên trước mắt mọi người."
  },
  AvgDialog_54802_Content_5 = {
    Text = "Bạn có biết đã tốn bao nhiêu tiền để mua bộ quần áo này không?"
  },
  AvgDialog_54802_Content_50 = {
    Text = "Đó là sự ra đời của đứa trẻ, là bài ca dao của người mẹ, là lời vĩnh biệt của người yêu."
  },
  AvgDialog_54802_Content_51 = {
    Text = "Đó là thời khắc quý giá nhất trong cuộc đời các bạn."
  },
  AvgDialog_54802_Content_53 = {
    Text = "Đau đớn lớn lao mà Ôrla trải qua, cùng với máu của cô, lan tỏa như gợn sóng khắp Tây Đài."
  },
  AvgDialog_54802_Content_54 = {
    Text = "Gai của hoa hồng đã xuyên qua vô số trái tim. Những đóa hồng đỏ rực nở trong tim mỗi người."
  },
  AvgDialog_54802_Content_55 = {
    Text = "Đây là……bài thơ bạn viết……"
  },
  AvgDialog_54802_Content_56 = {
    Text = "Nước mắt rửa trôi lớp trang điểm tinh xảo của cô ấy, cô ấy hoàn toàn không để ý, để mặc chúng để lại những dấu vết lộn xộn không đẹp trên khuôn mặt."
  },
  AvgDialog_54802_Content_57 = {
    Text = "Colette đã quên, nước mắt của cô ấy bắt đầu rơi từ khi nào."
  },
  AvgDialog_54802_Content_58 = {
    Text = "——Những hình ảnh quá khứ hiện lên rõ ràng trước mắt cô. Đây là lần đầu tiên, cô thực sự hiểu được thơ của Ôrla. Cô cuối cùng đã hiểu ra điều mình thực sự trân trọng."
  },
  AvgDialog_54802_Content_59 = {
    Text = "Không chỉ có cô ấy. Tất cả mọi người trong Tây Đài đều hiểu rõ bài thơ của Ôrla."
  },
  AvgDialog_54802_Content_6 = {
    Text = "Nỗi giận của Colette nhanh chóng biến mất. Cô tiếp tục khoác lên mình nụ cười thanh lịch và tao nhã."
  },
  AvgDialog_54802_Content_60 = {
    Text = "Ham muốn quyền lực đang phai nhạt, tình cảm đang trở lại. Những nền tảng của thế giới này đã tan biến trong bài thơ."
  },
  AvgDialog_54802_Content_61 = {
    Text = "Cô ấy cảm nhận được lực lượng đang biến mất. Cô ấy cảm nhận được sự thất bại đang đến gần. Cô ấy triệu hồi các gai nhọn sắc bén như dao và bước về phía Ôrla."
  },
  AvgDialog_54802_Content_62 = {
    Text = "\"Colette\", chiến thắng… Con chó của bà lão đã chết, và bà ấy đã đặt tên con chó đó cho tôi, lúc đó bạn đang ở bên tôi."
  },
  AvgDialog_54802_Content_63 = {
    Text = "Tên này tôi chưa bao giờ đổi. Vì tôi không muốn thua nữa, Ôrla…"
  },
  AvgDialog_54802_Content_64 = {
    Text = "Kolette khóc trong đau đớn, bước đi chật vật, từ từ tiến gần Ôrla."
  },
  AvgDialog_54802_Content_65 = {
    Text = "Thâm cảnh đang biến mất, kế hoạch của ngươi đã thất bại rồi, Colette."
  },
  AvgDialog_54802_Content_66 = {
    Text = "Dù cho bây giờ anh động tay với cô ấy, cũng không thay đổi được gì!"
  },
  AvgDialog_54802_Content_67 = {
    Text = "Bạn cố gắng tiến gần đến Ôrla. Những gai góc và nỗi đau bao quanh bạn, khiến bạn không thể di chuyển."
  },
  AvgDialog_54802_Content_68 = {
    Text = "Gai hướng về đầu của Ôrla."
  },
  AvgDialog_54802_Content_69 = {
    Text = "Đợi đã!"
  },
  AvgDialog_54802_Content_7 = {
    Text = "Không sao, không sao.."
  },
  AvgDialog_54802_Content_70 = {Text = "——"},
  AvgDialog_54802_Content_71 = {
    Text = "Một bông hồng bị cắt xuống. Colette cầm nó và đưa đến trước mặt Ôrla."
  },
  AvgDialog_54802_Content_72 = {
    Text = "Một bài thơ hay, Ôrla…… Tôi sẽ dùng bông hoa của tôi để đổi lấy bài thơ của bạn nhé……"
  },
  AvgDialog_54802_Content_73 = {
    Text = "Rầm——"
  },
  AvgDialog_54802_Content_74 = {
    Text = "Có lẽ sự tiêu tán của thâm cảnh đã khiến người thợ làm vườn thay đổi."
  },
  AvgDialog_54802_Content_75 = {
    Text = "Hoặc có lẽ sự thay đổi của người làm vườn đã khiến thâm cảnh biến mất."
  },
  AvgDialog_54802_Content_76 = {
    Text = "Tập thơ của Tây Đài dần dần biến mất, sức mạnh duy trì Colette cũng không còn tồn tại."
  },
  AvgDialog_54802_Content_77 = {
    Text = "Thân thể cô ấy biến thành một vũng bùn đen, pha trộn với những cánh hoa rơi rụng, chìm xuống đất trước mặt Ôrla."
  },
  AvgDialog_54802_Content_78 = {
    Text = "Colette, đã xem xong chưa?"
  },
  AvgDialog_54802_Content_79 = {
    Text = "Ừm... xem xong rồi... nhưng hình như tôi không hiểu lắm."
  },
  AvgDialog_54802_Content_8 = {
    Text = "Muốn đánh bại tôi trong vườn của tôi, vừa can đảm, lại vừa ngu ngốc."
  },
  AvgDialog_54802_Content_80 = {
    Text = "À, vậy sao… Đây là bài thơ đầu tiên tôi viết, viết không tốt…"
  },
  AvgDialog_54802_Content_81 = {
    Text = "Không phải lỗi của bạn, Ôrla, tôi không hiểu thơ của ai cả."
  },
  AvgDialog_54802_Content_82 = {
    Text = "Tôi đã hỏi rất nhiều người xung quanh, nhưng họ cũng không hiểu."
  },
  AvgDialog_54802_Content_83 = {
    Text = "Tôi không hiểu lắm, một thứ mà mọi người đều không thể hiểu được, rốt cuộc có ý nghĩa gì chứ.."
  },
  AvgDialog_54802_Content_84 = {
    Text = "Ừm... tôi nghĩ rằng, thơ không phải là một loại chữ hoặc hình ảnh, nó giống như một chiếc chìa khóa."
  },
  AvgDialog_54802_Content_85 = {
    Text = "Chìa khóa?"
  },
  AvgDialog_54802_Content_86 = {
    Text = "Đúng! Trái tim con người giống như một chiếc hộp, bên trong chứa đầy những cảm xúc sâu sắc. Chiếc hộp này bị khóa lại, và những cảm xúc đó thường ngày bị nhốt chặt trong hộp, muốn lấy ra cũng chẳng thể nào."
  },
  AvgDialog_54802_Content_87 = {
    Text = "Chìa khóa để mở chiếc hòm này chính là bài thơ."
  },
  AvgDialog_54802_Content_88 = {
    Text = "Thực ra, thơ không cần phải được hiểu, thậm chí không cần đọc."
  },
  AvgDialog_54802_Content_89 = {
    Text = "Mỗi người, dù có đọc thơ hay không, dù sớm hay muộn, trong một khoảnh khắc của sức sống, chắc chắn sẽ tìm thấy chìa khóa này."
  },
  AvgDialog_54802_Content_9 = {
    Text = "Các bạn đã lãng phí cơ hội cuối cùng để trốn thoát……buổi lễ này, các bạn cần phải ở lại xem đến cùng với ta."
  },
  AvgDialog_54802_Content_90 = {
    Text = "Bạn chắc chắn sẽ trở thành người thợ chìa khóa giỏi nhất!"
  },
  AvgDialog_54802_Content_91 = {
    Text = "Lừa người… bạn vừa nói là không hiểu mà."
  },
  AvgDialog_54802_Content_92 = {
    Text = "Bạn nói những điều tôi không hiểu. Nhưng tôi tin bạn, Ôrla."
  },
  AvgDialog_54802_Content_93 = {
    Text = "Bài thơ \"Nơi hoa hồng trú ngụ\" này là bài thơ đầu tiên bạn viết. Từ hôm nay, tôi sẽ giúp bạn lưu giữ tất cả các bài thơ của bạn."
  },
  AvgDialog_54802_Content_94 = {
    Text = "Tôi sẽ dùng ghim để ghim chúng lại, đợi đến khi có tiền, tôi sẽ in chúng thành một tập thơ đẹp!"
  },
  AvgDialog_54802_Content_95 = {
    Text = "Cô ấy đưa ra tay đã luôn giấu sau lưng. Đôi tay đó đầy vết thương do gai nhọn gây ra, sẫm màu, thô ráp, không thể nhận ra được là đôi tay của một cô gái."
  },
  AvgDialog_54802_Content_96 = {
    Text = "Đây... cái này là.."
  },
  AvgDialog_54802_Content_97 = {
    Text = "Nghe những quý tộc mới nói, Tây Đài là thành phố của hoa và thơ, một bài thơ hay có thể đổi được một bó hồng…"
  },
  AvgDialog_54802_Content_98 = {
    Text = "Hoa hồng tôi trồng hôm nay đã nở. Không nở nhiều, toàn bộ đều mang đi trả tiền thuê nhà và tiền thuê đất."
  },
  AvgDialog_54802_Content_99 = {
    Text = "Nhưng tôi đã lợi dụng lúc họ không để ý, âm thầm để lại một bông hoa……"
  },
  AvgDialog_56163_Content_1 = {
    Text = "Do gần đây các thân thể được đánh thức liên tục xuất hiện tình trạng bất thường, nhà trường quyết định tăng cường giám sát. Định kỳ kiểm tra nhằm phòng ngừa mọi tai nạn có thể xảy ra."
  },
  AvgDialog_56163_Content_10 = {
    Text = "Bạn cảm thấy nhẹ nhõm trong lòng, vì không phải đối mặt với người phụ nữ điên rồ này."
  },
  AvgDialog_56163_Content_11 = {
    Text = "Tuy nhiên, kinh nghiệm và trực giác từ việc điều tra của bạn bỗng thấy bất thường, bạn dừng lại, quan sát kỹ lưỡng ngọn nến đó."
  },
  AvgDialog_56163_Content_12 = {
    Text = "Những bóng đen mờ ảo được ánh nến phản chiếu trên tường, những hình ảnh lay động kia đâu phải là ngọn nến, rõ ràng là những bóng rắn đang uốn lượn, xoắn lại."
  },
  AvgDialog_56163_Content_13 = {
    Text = "Một loạt bóng rắn vây quanh ngọn nến, như thể muốn tước đoạt hơi ấm duy nhất còn lại trong căn phòng."
  },
  AvgDialog_56163_Content_14 = {
    Text = "Miriam quay đầu lại, khuôn mặt cô đỏ ửng một cách đặc biệt, giọng nói nhẹ nhàng và hạnh phúc như được nhận ân huệ của thần linh."
  },
  AvgDialog_56163_Content_15 = {
    Text = "Là ngài, Người Giữ Gìn, ngài có phải là vì cảm ứng được lời gọi của thần quốc mà đến đây không."
  },
  AvgDialog_56163_Content_16 = {
    Text = "Các chi của cô ta gầy yếu và tái nhợt, quấn quanh bởi những bóng rắn đang di chuyển, nhưng hai tay vẫn giữ nguyên tư thế cầu nguyện, giống như một nữ tu bị trói buộc, bị đóng khung trong sứ mệnh vĩnh cửu."
  },
  AvgDialog_56163_Content_17 = {
    Text = "Đầu óc bạn hét lên rằng điều này không ổn, nhưng quyết định lùi lại đã chậm một bước, bóng dáng con rắn lạnh lẽo và ẩm ướt đã sớm lẻn tới trong bóng tối, siết chặt lấy đôi chân bạn, bò lên eo lưng bạn."
  },
  AvgDialog_56163_Content_18 = {
    Text = "Thân thể của bạn thật ấm áp…"
  },
  AvgDialog_56163_Content_19 = {
    Text = "Rõ ràng bạn đã thay thế ánh nến le loe, trở thành nguồn nhiệt lớn nhất trong căn phòng."
  },
  AvgDialog_56163_Content_2 = {
    Text = "Để đối phó với khả năng mất kiểm soát của thân thể được đánh thức, nhiệm vụ kiểm tra phòng được phân công luân phiên giữa các điều tra viên rảnh rỗi. Hôm nay, đúng lượt bạn đảm nhận vai trò quản lý."
  },
  AvgDialog_56163_Content_20 = {
    Text = "Không không không,chắc chắn là anh đã hiểu lầm gì đó!Tôi không nghe thấy lời gọi của thần quốc,tôi chỉ đến để kiểm tra phòng!"
  },
  AvgDialog_56163_Content_21 = {
    Text = "Bạn giải thích trong lo lắng nhưng không có chút tác dụng nào, bóng rắn bao trùm và kéo bạn đến bên bàn cầu nguyện, ép bạn ngồi cạnh Miriam trước bức tượng với xúc tu vươn ra."
  },
  AvgDialog_56163_Content_22 = {
    Text = "Đã từ rất lâu rồi tôi chưa từng cảm thấy vui mừng và phấn khởi như thế này. Thần quốc, nó đã hồi đáp tôi!"
  },
  AvgDialog_56163_Content_23 = {
    Text = "Bạn rất muốn mở miệng phủ nhận, nói ra sự thật, nhưng khi nhìn thấy vẻ đắm chìm trên khuôn mặt cô ấy, bạn đã khéo léo nuốt lại lời định nói."
  },
  AvgDialog_56163_Content_24 = {
    Text = "Thần quốc đang thúc giục tôi, bảo tôi làm một việc gì đó, tôi nên tuân theo ý chỉ này."
  },
  AvgDialog_56163_Content_25 = {
    Text = "Bây giờ, chỉ dụ này đã đến tay ngài."
  },
  AvgDialog_56163_Content_26 = {
    Text = "Cô ấy nghiêng đầu, đầu ngón tay run rẩy khẽ vuốt ve khuôn mặt bạn, hai tay ôm lấy đôi má của bạn, như thể một lời an ủi dịu dàng, như thể một lời mời gọi sâu lắng."
  },
  AvgDialog_56163_Content_27 = {
    Text = "Hãy đến, cùng tôi cầu nguyện, cùng tôi… dâng hiến tất cả cho sự tiếp nối của thần quốc."
  },
  AvgDialog_56163_Content_28 = {
    Text = "Cảm giác lạnh lẽo từ bóng rắn khiến bạn run rẩy trong tình trạng mất nhiệt, sức từ chối bị sự quấn buộc mạnh mẽ phá vỡ, đưa thân thể bạn vào một tư thế thành kính."
  },
  AvgDialog_56163_Content_29 = {
    Text = "Bạn cùng với vị chủ tế cuồng nhiệt này đã bắt đầu cầu nguyện để làm hài lòng thần linh."
  },
  AvgDialog_56163_Content_3 = {
    Text = "Bạn, người đã bị quấy rối nhiều lần, lo lắng gõ cửa các phòng và ghi nhận trạng thái bình thường."
  },
  AvgDialog_56163_Content_4 = {
    Text = "Cuối cùng, khi gõ cửa một căn phòng nào đó chỉ còn lại sự im lặng không hồi đáp, trong lòng bạn không khỏi giật mình, thầm nghĩ \"Rốt cuộc cũng đến rồi\"."
  },
  AvgDialog_56163_Content_5 = {
    Text = "Bạn ngẩng đầu nhìn tên Miriam trên biển hiệu phòng, vẻ mặt trầm ngâm mở cửa phòng, cẩn thận thò nửa người ra ngoài."
  },
  AvgDialog_56163_Content_6 = {
    Text = "Miriam? Bạn có ở đó không?"
  },
  AvgDialog_56163_Content_7 = {
    Text = "Phòng tối chỉ có một ngọn nến lay động chiếu sáng góc mờ ấm áp, phản chiếu trên khuôn mặt của nữ tu đang cầu nguyện thành tâm."
  },
  AvgDialog_56163_Content_8 = {
    Text = "Hình bóng của cô ấy bình yên và hiền hòa, giống như hàng trăm năm tu luyện gian khổ như thường lệ."
  },
  AvgDialog_56163_Content_9 = {
    Text = "Thì ra bạn đang cầu nguyện, xin lỗi đã làm phiền. Nếu bạn không có gì cần thì tôi sẽ tiếp tục kiểm tra phòng."
  },
  AvgDialog_56308_Content_1 = {
    Text = "Nóng quá.."
  },
  AvgDialog_56308_Content_10 = {
    Text = "Khó mà nói là để chuyển sự chú ý của mình hay thực sự tò mò. Bạn quan sát xung quanh."
  },
  AvgDialog_56308_Content_11 = {
    Text = "Hoa nở rộ hơn, thời tiết nóng hơn, kiến trúc và âm nhạc khiến lòng người rung động hơn."
  },
  AvgDialog_56308_Content_12 = {
    Text = "Thế giới được hiện hóa từ chữ viết, mỗi nơi đều là ẩn dụ và ý nghĩa ngầm."
  },
  AvgDialog_56308_Content_13 = {
    Text = "Xin lỗi, Người Giữ Gìn… Tôi cũng không biết tại sao… những câu thơ tôi viết hôm nay, luôn… luôn…"
  },
  AvgDialog_56308_Content_14 = {
    Text = "Cảm xúc như gợn sóng lan tỏa trong không gian này. Bạn cảm thấy cổ họng hơi động đậy."
  },
  AvgDialog_56308_Content_15 = {
    Text = "Bạn đưa tay ra, nhẹ nhàng lấy xuống tờ giấy cổ trên đầu cô gái."
  },
  AvgDialog_56308_Content_16 = {Text = "A!"},
  AvgDialog_56308_Content_17 = {
    Text = "Cô gái như một chú thỏ non hoảng sợ, ẩn mình trong bóng tối và không ngừng lo lắng. Khuôn mặt đỏ bừng lan tới tận mang tai."
  },
  AvgDialog_56308_Content_18 = {
    Text = "Ôrla, tôi thích bài thơ này."
  },
  AvgDialog_56308_Content_19 = {
    Text = "Nhưng… nhưng bài thơ này còn chưa viết xong…"
  },
  AvgDialog_56308_Content_2 = {
    Text = "Một cảm giác khô nóng không biết từ đâu đến khiến bạn mở mắt."
  },
  AvgDialog_56308_Content_20 = {
    Text = "Thế, hãy cùng viết xong nó."
  },
  AvgDialog_56308_Content_21 = {
    Text = "Dưới, câu tiếp theo... nên viết gì đây.."
  },
  AvgDialog_56308_Content_22 = {
    Text = "Đêm đã buông, tất cả ánh mắt đều đã tan biến.."
  },
  AvgDialog_56308_Content_23 = {
    Text = "Mặt trời và các ngôi sao đều đã lặn……"
  },
  AvgDialog_56308_Content_24 = {
    Text = "……chỉ còn hoa hồng, bí mật nép mình trong vườn của cô ấy……"
  },
  AvgDialog_56308_Content_25 = {
    Text = "Văn tự vô hình hiện lên xung quanh cô, khu vườn tưởng tượng dần trở nên mờ nhạt."
  },
  AvgDialog_56308_Content_26 = {
    Text = "Giọng nói nhẹ nhàng của Ôrla ngày càng gần bạn. Bạn nghe thấy hơi thở êm ái của cô ấy. Bạn cảm nhận hơi ấm run rẩy của cô ấy."
  },
  AvgDialog_56308_Content_27 = {
    Text = "—— Trong khu vườn tối tăm, bạn đã biết được bí mật của một bông hồng."
  },
  AvgDialog_56308_Content_3 = {Text = "!!!"},
  AvgDialog_56308_Content_4 = {
    Text = "Chẳng phải tôi đang ngủ ở ký túc xá sao… Đây là chỗ nào vậy?"
  },
  AvgDialog_56308_Content_5 = {
    Text = "Xin lỗi, xin lỗi... Người Giữ Gìn"
  },
  AvgDialog_56308_Content_6 = {
    Text = "Thì ra là ngươi… Khó trách."
  },
  AvgDialog_56308_Content_7 = {
    Text = "Khả năng lan tỏa cảm xúc, gặp phải ảnh hưởng của sông thiêng liêng… thật là một sự kết hợp bất ngờ."
  },
  AvgDialog_56308_Content_8 = {
    Text = "Dưới ảnh hưởng của Ôrla, bạn cuối cùng cũng cảm nhận được cảm giác bị sông thiêng liêng tác động."
  },
  AvgDialog_56308_Content_9 = {
    Text = "Thế giới ẩn hiện trong thi ca lần này, có vẻ như khác với trước đây?"
  },
  AvgDialog_57563_Content_1 = {
    Text = "Vừa kết thúc một nhiệm vụ ngoại vi, bạn gặp phải mưa như trút nước trên đường về, bị mắc kẹt ở vùng ngoại ô xa trung tâm thành phố."
  },
  AvgDialog_57563_Content_10 = {
    Text = "Bạn nhìn vào khuôn mặt quen thuộc trước mắt, trong sự giằng xé, gọi tên cô ấy với sự ngạc nhiên cùng giọng nói khàn đặc."
  },
  AvgDialog_57563_Content_11 = {
    Text = "Ho……Xi……Luo!"
  },
  AvgDialog_57563_Content_12 = {
    Text = "Cô gái trước mặt nhíu nhẹ đôi mày, tuy nhiên trong đôi mắt đỏ tươi của cô không hề toát lên vẻ vui mừng khi gặp lại bạn cũ, mà chỉ là sự lạnh lùng sâu thẳm như mặt hồ băng giá."
  },
  AvgDialog_57563_Content_13 = {
    Text = "Khi bạn nghĩ rằng mình sắp mất mạng, khóe miệng của cô gái cong lên nhẹ nhàng, và bàn tay đó cuối cùng đã buông ra cổ bạn."
  },
  AvgDialog_57563_Content_14 = {
    Text = "Thì ra là bạn, tôi hình như đã nói, nếu gặp lại sẽ xé nát bạn ra."
  },
  AvgDialog_57563_Content_15 = {
    Text = "Bạn quỳ gối trên đất, gần như sắp sửa ho ra cả phổi, sau một hồi lâu mới khó khăn lật người lại."
  },
  AvgDialog_57563_Content_16 = {
    Text = "Bạn không biết đâu, khụ khụ, vì chúng ta là bạn thân…"
  },
  AvgDialog_57563_Content_17 = {
    Text = "Nhìn rõ toàn bộ dáng vẻ của cô gái trước mắt, bạn đứng sững tại chỗ. \nQuần áo trên người cô dính chặt vào da thịt, liên tục nhỏ nước mưa. Trong không khí ẩm ướt pha lẫn mùi máu, khuôn mặt trắng bệch còn mang theo một chút sắc đỏ không khỏe mạnh."
  },
  AvgDialog_57563_Content_18 = {
    Text = "Khóa lớn đã gắn chặt vào thân thể cô, bốn chi kết nối với dây xích tràn ngập màu đen và đỏ đầy bất tường."
