  },
  AvgDialog_57813_Content_11 = {
    Text = "Bạn đột nhiên tìm đến tôi, có nhìn thấy một tương lai mới không?"
  },
  AvgDialog_57813_Content_12 = {
    Text = "\"Dơr\" nhìn bạn như vậy, theo bước chân của bạn từng bước tiến gần, như thể hai người đang khiêu vũ trong sự ăn ý."
  },
  AvgDialog_57813_Content_13 = {
    Text = "Tương lai là không thể thay đổi, nhưng gần đây tôi đột nhiên có nhiều suy nghĩ, linh cảm tự nhiên đến, cuối cùng đã nghĩ ra cách nhanh nhất để đạt đến đích."
