  AvgDialog_57813_Content_21 = {
    Text = "Đường dẫn ngầm."
  },
  AvgDialog_57813_Content_22 = {
    Text = "Bao nhiêu lần bạn lướt qua lưỡi hái của tử thần, loạng choạng va vào tường, ngã xuống góc cua, nhưng không dám dừng lại, chỉ có thể chạy trốn trong hơi thở nặng nề."
  },
  AvgDialog_57813_Content_23 = {
    Text = "Thật là học sinh xuất sắc của tôi, hãy để thầy dạy em một bài học thực hành đỉnh cao nhất!"
  },
  AvgDialog_57813_Content_24 = {
    Text = "Tiếng cười điên rồ không giấu diếm đuổi theo bạn như bóng ma, sát ý như xuyên thủng lưng, bạn lại một lần nữa ngã sấp xuống đất, sau lưng vang lên tiếng \"coong\" của lưỡi hái cắm vào ống kim loại."
