  },
  AvgDialog_57813_Content_26 = {
    Text = "Bạn nhanh chóng nhận ra điều gì đó và ngay lập tức men theo hướng đường ống trốn vào một phòng thí nghiệm."
  },
  AvgDialog_57813_Content_27 = {
    Text = "Cánh cửa phòng thí nghiệm đóng kín nhanh chóng bị phá vỡ bởi vài tiếng nổ lớn, giọng nói quen thuộc từ từ tiến lại gần."
  },
  AvgDialog_57813_Content_28 = {
    Text = "Trò chơi trốn tìm kết thúc ở đây, đi đến bây giờ đã đủ để thêm mười điểm vào điểm cuối kỳ của bạn."
  },
  AvgDialog_57813_Content_29 = {
    Text = "\"đóa\" liềm của đóa kéo trên mặt đất, phát ra tiếng động sắc nhọn."
  },
  AvgDialog_57813_Content_3 = {
    Text = "\"đóa\"đã thoát khỏi sự giam cầm của hồ đen?"
