  AvgDialog_57813_Content_30 = {
    Text = "Đừng sợ, đợi tôi nghiền nát bạn, tôi sẽ đặt xác bạn vào quan tài băng và trân trọng cất giữ."
  },
  AvgDialog_57813_Content_31 = {
    Text = "Bạn sẽ là nghiên cứu quý giá nhất, cũng là thành tựu xuất sắc nhất của tôi. Chúng ta còn rất nhiều thời gian bên nhau…"
  },
  AvgDialog_57813_Content_32 = {
    Text = "Trong làn sương mờ, cô thoáng nhìn thấy một góc tà áo bên cạnh chiếc máy khổng lồ ở giữa căn phòng, môi cô hơi nhếch lên."
