  },
  AvgDialog_57813_Content_35 = {
    Text = "Thời gian gần như đóng băng trong sự chờ đợi đầy đau khổ, giọng nói của cô ấy cuối cùng cũng vang lên một lần nữa, nhẹ nhàng như một lời thì thầm."
