  },
  AvgDialog_57813_Content_39 = {
    Text = "Trong khoảnh khắc liềm bị kẹt vào máy, bạn đã nhấn nút đỏ mà bạn đang nắm chặt trong tay, cửa nạp liệu của lò luyện mở ra nhanh chóng sang hai bên, lộ ra cảnh tượng dung nham như địa ngục bên trong."
  },
  AvgDialog_57813_Content_4 = {
    Text = "Bạn nhớ đến đôi mắt điên rồ đang nhìn chằm chằm vào bạn, theo bản năng liền chuẩn bị mở cửa ra ngoài, nhanh chóng hội họp với các thân thể được đánh thức khác."
  },
  AvgDialog_57813_Content_40 = {
