  AvgDialog_58289_Content_59 = {Text = "Bạn…"},
  AvgDialog_58289_Content_6 = {
    Text = "Ôi trời ơi, hôm nay là bài kiểm tra giới thiệu học thuyết Rỗng Rỗng. Mấy giờ rồi…"
  },
  AvgDialog_58289_Content_60 = {
    Text = "Đầu của Elsa nổ tung thành một vũng chất lỏng ấm nóng. Chất lỏng đặc sệt bắn tung tóe lên mặt, không khí ngập tràn mùi tanh của sắt gỉ."
