  AvgDialog_58289_Content_68 = {
    Text = "Ông Lắc?!"
  },
  AvgDialog_58289_Content_69 = {
    Text = "Lắc thu lại móng thú, với bước chân nhẹ nhàng tiến về phía bạn."
  },
  AvgDialog_58289_Content_7 = {
    Text = "6 giờ 37 phút, còn sớm mà……"
  },
  AvgDialog_58289_Content_70 = {
    Text = "Sao lại có vẻ mặt sắp khóc vậy? Đừng lo, nơi này có lẽ là thâm cảnh của ai đó."
