  AvgDialog_58289_Content_72 = {
    Text = "Ừm. Điều đó có nghĩa là, trong thực tế, Elsa rất có thể vẫn còn sống khỏe mạnh."
  },
  AvgDialog_58289_Content_73 = {
    Text = "Không hổ là thám tử tiên sinh, chỉ cần liếc mắt là có thể nhận ra. Lý do là gì?"
  },
  AvgDialog_58289_Content_74 = {
    Text = "Tôi và Elsa gặp nhau lần đầu cũng vào một đêm như thế này."
  },
  AvgDialog_58289_Content_75 = {
    Text = "Lúc đó cô ấy bị một nhóm quái vật Rỗng Rỗng đuổi rất gấp, tôi vừa ra khỏi quán rượu, chỉ cho cô ấy lối thoát và tiện thể tiêu diệt những con quái vật đuổi theo."
  },
  AvgDialog_58289_Content_76 = {
    Text = "Vừa rồi chúng ta lại gặp nhau. Cùng một thời gian, cùng một địa điểm, nhưng tôi đã chỉ cho cô ấy một con đường sai lầm, khiến cô ấy bị thương ở đầu. Điều đó có nghĩa là——"
