  AvgDialog_58289_Content_77 = {
    Text = "Điều đó có nghĩa là?"
  },
  AvgDialog_58289_Content_78 = {
    Text = "May mắn của tôi đã biến mất! Đây là điều tuyệt đối không thể xảy ra, vì vậy tôi suy luận rằng đây không phải là thực tế."
  },
  AvgDialog_58289_Content_79 = {
    Text = "Hoặc anh hãy tát tôi hai cái, chúng ta xác nhận xem đây có phải là trong mơ không? Vừa rồi tôi đã tự tát mình nhiều lần rồi, nhưng không giúp ích gì."
  },
  AvgDialog_58289_Content_8 = {
    Text = "Bạn mò mẫm bấm công tắc đồng hồ báo thức, rồi lại thiếp đi trong cơn mệt mỏi."
  },
  AvgDialog_58289_Content_81 = {
    Text = "Tôi chỉ biết rằng, dù là trong thâm cảnh hay thực tế, tôi cũng không muốn nhìn thấy đầu mình nở hoa."
  },
  AvgDialog_58289_Content_82 = {
    Text = "Bạn cần sự giúp đỡ của tôi ngay lập tức! Trên đường đi, tôi đã gặp không ít người như Elsa, những người không may mắn đến muộn. Tốt nhất chúng ta nên đi đường khác."
  },
  AvgDialog_58289_Content_83 = {
    Text = "Lắc nói, chỉ về phía mái nhà của một tòa nhà gần đó."
