  AvgDialog_58289_Content_88 = {
    Text = "<Shake:ư wa a a a!>"
  },
  AvgDialog_58289_Content_89 = {
    Text = "Bạn hoảng sợ túm chặt cổ áo của Lắc. Thám tử nhanh nhẹn cúi người, khéo léo nhảy qua những mái nhà cao thấp, len lỏi giữa những tòa nhà san sát của Lentiennam."
