  AvgDialog_58289_Content_90 = {
    Text = "Một người một sói tấn công nhanh trong đêm trăng tĩnh lặng."
  },
  AvgDialog_58289_Content_91 = {
    Text = "Tai chỉ nghe thấy tiếng gió trong trẻo, bạn khẽ cúi người xuống, tựa mình vào lớp lông tơ mềm mại phía dưới."
