  AvgDialog_58290_Content_1 = {Text = "Nhà ma"},
  AvgDialog_58290_Content_10 = {
    Text = "Trên bàn bài, cuộc đấu đang diễn ra nảy lửa, không ai để ý đến thắc mắc nhỏ của bạn."
