  },
  AvgDialog_58290_Content_37 = {Text = "Ờ..."},
  AvgDialog_58290_Content_38 = {
    Text = "Đúng rồi! Phản ứng của ông Dexter vừa rồi thật kỳ lạ. Đi, chúng ta đi xem phòng ngủ của ông ấy."
  },
  AvgDialog_58290_Content_39 = {
