  },
  AvgDialog_58290_Content_4 = {
    Text = "Cược chung đã vượt quá mười nghìn Rieuphường rồi, còn tiếp tục tăng cược không?"
  },
  AvgDialog_58290_Content_40 = {
    Text = "Biệt thự Fran\nĐầu cầu thang"
