  AvgDialog_58290_Content_59 = {
    Text = "Thưa ngài Dexter, ngài có ở trong đó không? Ngài cảm thấy tốt hơn chưa?"
  },
  AvgDialog_58290_Content_6 = {
    Text = "Nghe ông nói như vậy tôi yên tâm rồi, thưa ông Lắc. Khi ra khỏi thâm cảnh này, tôi sẽ nhờ người quản gia gửi hóa đơn cho ông."
