  AvgDialog_58291_Content_108 = {
    Text = "Rất tuyệt, hãy tiếp tục phát huy tinh thần cãi nhau này, đừng để sự hiện diện của tôi ảnh hưởng đến việc phát huy!"
  },
  AvgDialog_58291_Content_109 = {
    Text = "Quy tắc hành vi của chúng tôi, điều đầu tiên, hỗn loạn!Điều thứ hai, hỗn loạn!Điều thứ ba…"
