  AvgDialog_58291_Content_116 = {
    Text = "Bạn trầm ngâm, băn khoăn có nên nói hết mọi thứ mình biết cho Hannah hay không. Nhưng rất nhanh bạn nhận ra mình đã lo lắng quá mức."
  },
  AvgDialog_58291_Content_117 = {
    Text = "Đối với N, bạn cũng chẳng biết gì cả."
