  AvgDialog_58291_Content_45 = {
    Text = "Bông hồng kiều diễm nhất, dành tặng cho người đẹp xinh đẹp nhất ở Lentiennam."
  },
  AvgDialog_58291_Content_46 = {
    Text = "Rất tuyệt vời, cô ảo thuật gia! Cô có quan tâm đến các chức vụ trong cung đình không? Tôi nhất định sẽ giới thiệu cô với nữ hoàng bệ hạ."
