  AvgDialog_58291_Content_5 = {
    Text = "Xin lỗi, đây là một trong hơn năm mươi bất động sản của ông, kém nổi bật nhất."
  },
  AvgDialog_58291_Content_50 = {
    Text = "Từ khi chia tay ở Á Lan, ta nhớ các ngươi mỗi ngày đấy."
