  AvgDialog_58291_Content_57 = {
    Text = "Bong— bong—"
  },
  AvgDialog_58291_Content_58 = {
    Text = "Cái đồng hồ khổng lồ bỗng nhiên lơ lửng đe dọa trên đầu mọi người, thời gian trên mặt số chỉ đúng mười hai giờ đêm."
  },
  AvgDialog_58291_Content_59 = {
