  AvgDialog_58291_Content_62 = {
    Text = "Chúc mừng mọi người đã vượt qua thử thách đầu tiên mà tôi đã đặt ra, nhờ vào sự thông minh và tinh thần hợp tác của mỗi người."
  },
  AvgDialog_58291_Content_63 = {
    Text = "Thời gian làm nóng đã kết thúc, tiếp theo xin mời quý vị lắng nghe nội dung chính ——"
  },
  AvgDialog_58291_Content_64 = {Text = "Bùm!"},
  AvgDialog_58291_Content_65 = {
    Text = "Đạn chính xác xuyên qua khuôn mặt của người tí hon bí ẩn, để lại một lỗ thủng khổng lồ ở giữa."
  },
  AvgDialog_58291_Content_66 = {
    Text = "Xin lỗi, súng ngắn không may bị cướp cò. Trò chơi đóng vai có vui không, N?"
