  AvgDialog_58292_Content_81 = {
    Text = "Vu khống một con người vô tội là tội nặng không thể tha thứ, và bây giờ đã đến lúc phải chịu sự trừng phạt!"
  },
  AvgDialog_58292_Content_82 = {
    Text = "N có vẻ đăm chiêu khi đỡ cằm tròn trĩnh của mình. Mỗi khi Người suy nghĩ, tốc độ sương mù trên khuôn mặt cũng chậm lại."
