  AvgDialog_58293_Content_19 = {
    Text = "Sao các cậu lại ở đây? Có chuyện gì xảy ra không?"
  },
  AvgDialog_58293_Content_20 = {
    Text = "Thầm thì cho các bạn biết, trò chơi săn đuổi đã bắt đầu rồi đó~"
  },
  AvgDialog_58293_Content_21 = {
    Text = "Thân thể mảnh mai lướt qua bóng tối, Kassia nhẹ nhàng như ảo thuật xuất hiện trước mặt các người."
  },
  AvgDialog_58293_Content_22 = {
    Text = "Tôi biết tiếng súng từ đâu phát ra, có muốn đi cùng tôi không? Một mình tôi hơi sợ."
  },
  AvgDialog_58293_Content_23 = {
    Text = "Bạn từ đâu xuất hiện……"
  },
  AvgDialog_58293_Content_24 = {
    Text = "Kassia vừa mới nằm trên đèn treo trần nhà để ngủ. Như người Việt thường nói, đứng cao nhìn xa…"
  },
  AvgDialog_58293_Content_25 = {
    Text = "Tôi đã thấy mọi thứ rồi nha~"
  },
  AvgDialog_58293_Content_26 = {
    Text = "Kassia nói xong, cười tinh nghịch và nháy mắt với bạn."
  },
  AvgDialog_58293_Content_28 = {
    Text = "Sao còn đứng đó làm gì? Không muốn là người đầu tiên đến hiện trường vụ án sao?"
  },
  AvgDialog_58293_Content_29 = {
    Text = "Dinh thự Fran\nThư phòng tầng một"
  },
  AvgDialog_58293_Content_3 = {
    Text = "Đến đây thôi, tiếp theo chúng ta sẽ mỗi người một ngả. Bạn vẫn còn muốn tìm kiếm <Yellow:bức tường Chân Lý> chứ?"
  },
  AvgDialog_58293_Content_30 = {
    Text = "Bạn đẩy cửa phòng sách."
  },
  AvgDialog_58293_Content_31 = {
    Text = "Đây, đây là……"
  },
  AvgDialog_58293_Content_32 = {
    Text = "Ông Dexter?!"
  },
  AvgDialog_58293_Content_33 = {
    Text = "Người đàn ông bị treo lơ lửng dưới xà nhà, như một chiếc lá rơi trong gió. Mặt anh ta bị bao phủ bởi một lớp bóng tối ảm đạm xanh tím, đôi mắt gần như muốn lồi ra khỏi hốc mắt."
  },
  AvgDialog_58293_Content_34 = {
    Text = "Mọi người xin hãy giữ bình tĩnh, tránh làm hỏng hiện trường tội phạm."
  },
  AvgDialog_58293_Content_35 = {
    Text = "Tội phạm……hiện trường?"
  },
  AvgDialog_58293_Content_36 = {
    Text = "Đừng nhìn nữa, tên này chết hẳn rồi. Để tôi đoán xem, đây chính là đố mà họ để lại cho chúng ta phải không?"
  },
  AvgDialog_58293_Content_37 = {
    Text = "Một loại trò chơi thám tử suy luận?"
  },
  AvgDialog_58293_Content_38 = {
    Text = "Bingo! Đúng rồi~!"
  },
  AvgDialog_58293_Content_39 = {
    Text = "Vậy rốt cuộc là ai, trong một đêm tuyết rơi dày đặc như vậy, đã tàn nhẫn giết hại một quý tộc lịch lãm?"
  },
  AvgDialog_58293_Content_4 = {
    Text = "\"bạn\" gật đầu."
  },
  AvgDialog_58293_Content_40 = {
    Text = "Hãy thử tìm ra sự thật đi, các thám tử tài ba."
  },
  AvgDialog_58293_Content_41 = {
    Text = "Thật kỳ lạ, chẳng phải người bị nghi ngờ nhiều nhất chính là ông N thân mến hay sao?"
  },
  AvgDialog_58293_Content_42 = {
    Text = "Khụ khụ, hãy để tôi chính xác hơn—hãy tìm ra kẻ sát nhân giả mạo là phân thân của tôi!"
  },
  AvgDialog_58293_Content_43 = {
    Text = "Đang ở ngay giữa mọi người đó!"
  },
  AvgDialog_58293_Content_44 = {
    Text = "Im lặng đến rợn người"
  },
  AvgDialog_58293_Content_45 = {
    Text = "Sự nghi ngờ và bất an lặng lẽ lan rộng trong đám đông. Ánh mắt dường như vô tình quét qua những người khác, lặng lẽ suy ngẫm về tính chân thực trong lời nói của N."
  },
  AvgDialog_58293_Content_46 = {
    Text = "Nếu chúng ta từ chối cái trò chơi này thì sao?"
  },
  AvgDialog_58293_Content_47 = {
    Text = "Các bạn có biết đối với một nhà thiết kế game đầy nhiệt huyết và sáng tạo như tôi, điều quan trọng nhất là gì không?"
  },
  AvgDialog_58293_Content_48 = {
    Text = "Tất nhiên là sự tham gia của người chơi! Nếu mọi người đều không quan tâm, thì tôi chỉ có thể tiếc nuối thông báo kết thúc trò chơi!"
  },
  AvgDialog_58293_Content_49 = {
    Text = "Không ai trả lời. Mọi người đều đang chờ đợi \"nhưng\" ở sau ——"
  },
  AvgDialog_58293_Content_5 = {
    Text = "Thế thì tôi không khuyên nữa. Nói thật là tôi luôn không hiểu nổi cậu… Cậu trông trẻ vậy mà lại như đã sống mấy nghìn năm."
  },
  AvgDialog_58293_Content_50 = {Text = "Nhưng!"},
  AvgDialog_58293_Content_51 = {
    Text = "Ông Dexter đáng thương và cô Elsa, từ giờ chỉ có thể nói lời vĩnh biệt với các bạn."
  },
  AvgDialog_58293_Content_52 = {
    Text = "Phòng y tế của Misaque\nTrong khi đó……"
  },
  AvgDialog_58293_Content_53 = {
    Text = "Tình hình thế nào rồi?"
  },
  AvgDialog_58293_Content_54 = {
    Text = "Rất bi quan. Elsa bị chảy máu não nghiêm trọng, áp lực dịch não tủy tiếp tục tăng, nhiệt độ cơ thể luôn duy trì trên 100°F."
  },
  AvgDialog_58293_Content_55 = {
    Text = "Người giữ bí mật và Hannah thì rơi vào trạng thái mê sảng nào đó. Mặc dù hôn mê liên tục, nhưng các chỉ số sinh học của thân thể đều bình thường."
  },
  AvgDialog_58293_Content_56 = {
    Text = "Rõ. Vậy…… anh ấy thì sao?"
  },
  AvgDialog_58293_Content_57 = {
    Text = "Cô gái không đề cập rõ tên, nhưng mọi người ở đây đều biết cô đang nói ai."
  },
  AvgDialog_58293_Content_58 = {
    Text = "Ông Dexter… được chẩn đoán ban đầu là do áp lực lên thần kinh gây ra ngừng đập phản xạ của tim, giống như đã trải qua một dạng ngạt cơ học."
  },
  AvgDialog_58293_Content_59 = {
    Text = "Tim ngừng đập?"
  },
  AvgDialog_58293_Content_6 = {
    Text = "Dù sao đi nữa, cám ơn. Tôi đã có cách giải phong ấn, tiếp theo là đi đến Rome, thả con quái vật ra……"
  },
  AvgDialog_58293_Content_60 = {
    Text = "Wenkel gật đầu nhẹ."
  },
  AvgDialog_58293_Content_61 = {
    Text = "Cứu chữa không thành công, năm phút trước đã ngừng thở. Về mặt lý thuyết…"
  },
  AvgDialog_58293_Content_62 = {
    Text = "Anh ta đã chết."
  },
  AvgDialog_58293_Content_63 = {
    Text = "Dinh thự Fran\nThư phòng tầng một"
  },
  AvgDialog_58293_Content_64 = {
    Text = "Nghĩa là, nếu chúng ta không tuân theo quy tắc của cậu, những người chết ở đây sẽ không thể thức dậy trong thế giới thực?"
