  AvgDialog_58293_Content_67 = {
    Text = "……hừ, tôi thật sự không cảm thấy tự hào về điều này."
  },
  AvgDialog_58293_Content_68 = {
    Text = "Vạn nhất đây chỉ là trò lừa bịp thì sao? Bạn làm sao để chứng minh mình không nói dối?"
  },
  AvgDialog_58293_Content_69 = {
    Text = "Tôi đương nhiên có thể chứng minh—nhưng tôi không muốn, hihi."
  },
  AvgDialog_58293_Content_7 = {
    Text = "Phù thủy khó nhọc đóng gói hành lý, vừa đi vài bước thì quay đầu trở lại."
  },
  AvgDialog_58293_Content_70 = {
    Text = "Hoặc các người cũng có thể cược một lần xem sao? Kết thúc trò chơi ngay, trở về thế giới nhỏ dễ thương của các người, mọi thứ đều như cũ."
  },
  AvgDialog_58293_Content_71 = {
    Text = "Chăn ấm luôn thoải mái, bài kiểm tra vẫn tiếp tục, mọi người đều khỏe mạnh."
  },
  AvgDialog_58293_Content_72 = {
    Text = "N nhìn về phía Lắc, dang rộng đôi tay bé nhỏ đầy nhiệt huyết."
  },
  AvgDialog_58293_Content_73 = {
    Text = "Thế nào, có muốn đánh một ván không? Đây chính là điều mà bạn giỏi nhất."
  },
  AvgDialog_58293_Content_74 = {
    Text = "Thật ngại quá, tôi không bao giờ đánh cược bằng mạng người khác."
  },
  AvgDialog_58293_Content_75 = {
    Text = "Trò chơi mới chỉ bắt đầu, kết thúc nhanh như vậy thì quá nhàm chán!"
  },
  AvgDialog_58293_Content_76 = {
    Text = "Kassia đứng thẳng người, \"vèo\" nâng cao tay phải."
  },
  AvgDialog_58293_Content_77 = {
    Text = "Bíp bíp! Tôi tán thành tiếp tục trò chơi~!"
  },
  AvgDialog_58293_Content_78 = {
    Text = "Sau một cuộc thảo luận, với những lý do khác nhau, mọi người lần này đã đồng lòng một cách khó tin."
  },
  AvgDialog_58293_Content_79 = {
    Text = "Thật cảm động! Cảm ơn mọi người đã tôn trọng vô điều kiện kết quả thiết kế của tôi!"
  },
  AvgDialog_58293_Content_8 = {
    Text = "Này, bạn còn chưa nói cho tôi biết tên của bạn."
  },
  AvgDialog_58293_Content_80 = {
    Text = "Thì tôi tuyên bố ở đây: <Red:Thử thách vòng hai chính thức bắt đầu!>"
  },
  AvgDialog_58293_Content_81 = {
    Text = "Các vị có tận hai giờ đồng hồ để giải đố nhé~"
  },
  AvgDialog_58293_Content_82 = {
    Text = "Mới có hai giờ, thế này làm sao đủ…"
  },
  AvgDialog_58293_Content_83 = {
    Text = "Ô hê hê, ngay khi một số người đang nghi ngờ ngài N tôn quý, thời gian lại trôi qua thêm mười giây."
  },
  AvgDialog_58293_Content_84 = {
    Text = "Vậy, chúc mọi người chơi vui vẻ nhé~"
