  AvgDialog_58293_Content_89 = {
    Text = "Hãy thư giãn. Xác nhận xem bạn có phải là kẻ mạo danh không."
  },
  AvgDialog_58293_Content_9 = {
    Text = "Gió thổi lên những hạt cát vàng mịn. Phù thủy mặc quần áo rách rưới tựa lưng vào bầu trời xanh, khuôn mặt ửng đỏ hiếm khi lộ ra một vẻ tốt bụng."
