  AvgDialog_58293_Content_91 = {
    Text = "Bạn một tay túm lấy lông mịn trên mặt Lắc và rút phăng vài sợi."
  },
  AvgDialog_58293_Content_92 = {Text = "Xì!!"},
  AvgDialog_58293_Content_93 = {
    Text = "Ngửi ngửi... à, đúng là hàng thật rồi."
  },
  AvgDialog_58293_Content_94 = {
    Text = "Đừng khách sáo, đều tặng cho bạn đây, nhớ rửa sạch phơi khô rồi bảo quản kỹ nha."
  },
  AvgDialog_58294_Content_1 = {
    Text = "Thực tế thấp hơn"
  },
  AvgDialog_58294_Content_10 = {
    Text = "Anh ta một cách kiên quyết bước ra, đi đến trước mặt N."
  },
  AvgDialog_58294_Content_11 = {
    Text = "Lý luận sai? Không thể nào, chắc chắn bạn đã động tay chân ở đâu đó."
  },
  AvgDialog_58294_Content_12 = {
    Text = "Hai vết hằn khác nhau, cùng với đôi giày đã biến mất, anh đã quên sạch sẽ rồi à?"
  },
  AvgDialog_58294_Content_13 = {
    Text = "Tôi có thể liệt kê ngay hàng chục khả năng, nhưng liệu chúng có thực sự quan trọng? Hay là, chúng vốn không quan trọng, chỉ là do bạn sắp xếp ——"
  },
  AvgDialog_58294_Content_14 = {
    Text = "\"Bản gốc\"? Thật kỳ lạ, nếu đề tài của tôi là tiết lộ <Red:thâm cảnh> sự thật, thì thâm cảnh chính là sự thật và điểm tham chiếu duy nhất mà các bạn đang dựa vào lúc này."
  },
  AvgDialog_58294_Content_15 = {
    Text = "Tại sao ai đó luôn muốn bám víu vào cái gọi là \"quá khứ\" vậy~"
  },
  AvgDialog_58294_Content_16 = {Text = "!!"},
  AvgDialog_58294_Content_17 = {
    Text = "Có lẽ trong quá khứ, bạn đã giải quyết vụ án này một cách gọn gàng, thu được chút ít lòng kiêu hãnh ít ỏi và mong manh, đồng thời vẫn còn đắm chìm trong ký ức đó cho đến tận bây giờ."
  },
  AvgDialog_58294_Content_18 = {
    Text = "Nhưng thật đáng tiếc, ở đây, anh đã gây ra một mớ hỗn độn. Thám tử."
  },
  AvgDialog_58294_Content_19 = {
    Text = "N nâng tay lên từ từ, búng tay nhẹ nhàng."
  },
  AvgDialog_58294_Content_2 = {
    Text = "Nên giết chết ai nhỉ……"
  },
  AvgDialog_58294_Content_20 = {Text = "……Ơ?"},
  AvgDialog_58294_Content_21 = {
    Text = "Giây tiếp theo, từ trong cơ thể Kassia đang xem kịch bỗng nhiên toả ra những luồng sương đen."
  },
  AvgDialog_58294_Content_22 = {
    Text = "Quyết định rồi, hình phạt sẽ giáng xuống đầu bạn."
  },
  AvgDialog_58294_Content_23 = {
    Text = "Oi… Người thất bại trong việc suy luận không phải là thằng kia sao, tại sao Kassia lại phải chịu tội thay cho hắn!"
