  AvgDialog_58894_Content_35 = {
    Text = "Gửi người nhận ở xa: \nVui lòng đến biệt thự Flandre trước nửa đêm. Đúng giờ, nếu không hậu quả tự chịu (@2Não sẽ nổ tung @3). \nĐịa chỉ: @2Quận \n-▼-"
  },
  AvgDialog_58894_Content_36 = {
    Text = "Biệt thự Franke? Tôi nhớ đó là dinh thự thuộc sở hữu của ông Dexter. Khi nào thì gã này cũng học được cách đùa giỡn rồi…"
