  AvgDialog_58894_Content_88 = {
    Text = "<Shake:ư wa a a a!>"
  },
  AvgDialog_58894_Content_89 = {
    Text = "Bạn sợ hãi túm chặt lấy cổ áo của Lắc. Thám tử cúi gập lưng, di chuyển khéo léo qua các mái nhà lớn nhỏ, len lỏi giữa những tòa nhà san sát ở Lentiennam."
