  AvgDialog_58894_Content_90 = {
    Text = "Một người một con sói tấn công nhanh dưới ánh trăng yên bình. Bên tai chỉ nghe thấy tiếng gió trong trẻo, bạn cúi thấp người, dựa mình vào bộ lông mềm mại phía dưới thân."
