  AvgDialog_58895_Content_135 = {Text = "Gì…?"},
  AvgDialog_58895_Content_136 = {
    Text = "Lắc đứng trước mặt bạn với dáng vẻ kiêu ngạo, môi nhếch lên nụ cười đầy mỉa mai."
  },
  AvgDialog_58895_Content_137 = {
    Text = "Tôi đã chờ đợi khoảnh khắc này rất lâu rồi, bạn gác bí mật."
