  },
  AvgDialog_58895_Content_91 = {
    Text = "Được rồi, những người không liên quan đã rời đi, chúng ta có thể mở lòng với nhau rồi."
  },
  AvgDialog_58895_Content_92 = {
    Text = "N thể hiện ra làn sương mù lạnh lẽo và rờn rợn, che phủ khuôn mặt của Người, cho đến khi lộ ra khuôn mặt nguyên thủy."
  },
  AvgDialog_58895_Content_93 = {
    Text = "Không chỉ vậy, địa hình tuyết các bạn đang đứng cũng biến mất đột ngột, thay vào đó là nhà hát opera quen thuộc."
  },
  AvgDialog_58895_Content_94 = {
    Text = "Xin mọi người đừng cười. Tôi luôn là một người có yêu cầu rất cao về chất lượng môi trường."
  },
  AvgDialog_58895_Content_95 = {
    Text = "Lâu không gặp, những người bạn cũ thân yêu của tôi."
  },
  AvgDialog_58895_Content_96 = {
    Text = "Bạn vừa nói gì, điều đó không phải là sự thật cuối cùng…?"
  },
  AvgDialog_58895_Content_97 = {
    Text = "Bởi vì bạn vẫn chưa tìm ra kẻ đã giết bà Sorrel. Tất cả những suy luận của bạn đều cố tình tránh né cái chết của bà ấy, phải không?"
  },
  AvgDialog_58895_Content_99 = {
    Text = "Xin lỗi, tôi đã quá vội vàng cắt ngang lời bạn."
  },
  AvgDialog_59157_Content_1 = {
    Text = "Hướng đạo, Phù thủy và Nô lệ"
  },
  AvgDialog_60107_Content_10 = {
    Text = "Lơ-tan dựa vào ghế dài, ngửa đầu cử động các khớp của mình."
  },
  AvgDialog_60107_Content_100 = {
    Text = "Kế hoạch của Lemvahi đã thất bại, thật đáng tiếc, nhưng không có gì đáng lo ngại."
  },
  AvgDialog_60107_Content_101 = {
    Text = "Điều quan trọng nhất chỉ có hôm nay —— hai mươi năm sau hôm nay."
  },
  AvgDialog_60107_Content_102 = {
    Text = "Việc có thể chứng kiến thời khắc quan trọng này cùng với một người hợp tác như bạn là một niềm vui lớn."
  },
  AvgDialog_60107_Content_103 = {
    Text = "Chúng ta có cùng mục đích. Buổi biểu diễn này không phải dành cho chúng ta."
  },
  AvgDialog_60107_Content_104 = {
    Text = "Để lại được nghe âm thanh mà vị tồn tại vĩ đại kia mang đến, mọi sự hy sinh đều trở nên không đáng kể."
  },
  AvgDialog_60107_Content_105 = {
    Text = "Quay lại, đứng nghiêm. Người chỉ huy trẻ tuổi nâng hai tay lên, chào rạp hát vắng lặng và hướng về nơi sâu thẳm của dải Ngân hà mà không ai biết tới."
  },
  AvgDialog_60107_Content_106 = {
    Text = "Mọi thứ đã sẵn sàng, hãy bắt đầu hành trình thôi, bà Yu Li-ét."
  },
  AvgDialog_60107_Content_107 = {
    Text = "Buổi biểu diễn chính thức bắt đầu rồi."
  },
  AvgDialog_60107_Content_11 = {
    Text = "Từ sau lễ thức Khóa Mộ, Misaque đã liên tục gặp rắc rối."
  },
  AvgDialog_60107_Content_12 = {
    Text = "Được gặp đối thủ thú vị là điều tốt, tuy nhiên, có thời gian nghỉ ngơi cũng khá tốt."
  },
  AvgDialog_60107_Content_13 = {
    Text = "Orci đặt cây thương xuống, đứng bên cạnh, nhíu mày lại một chút."
  },
  AvgDialog_60107_Content_14 = {
    Text = "Nói đến chuyện này… Bà Lơ-tan, bà có thấy rằng gần đây chúng ta gặp hơi nhiều chuyện rồi không?"
  },
  AvgDialog_60107_Content_15 = {
    Text = "Từ nhà nuôi người nghèo, bảo tàng bình tượng nến, đến La Í, tàu Sonanier, và sau đó là đụn cát sông thiêng liêng ở Lơmuah…"
  },
  AvgDialog_60107_Content_16 = {
    Text = "Từ khi chủ công kế nhiệm chức Người Giữ Gìn, những chuyện này đã xảy ra cùng lúc. Điều này nhìn thế nào cũng không giống như là trùng hợp."
  },
  AvgDialog_60107_Content_17 = {
    Text = "Đoã Nhĩ cũng đã nói với tôi về vấn đề này, tuy nhiên, tôi không quá quan tâm."
  },
  AvgDialog_60107_Content_18 = {
    Text = "Việc suy nghĩ sâu, cứ để đóa và những người khác lo. Đây không phải nhiệm vụ của chúng ta."
  },
  AvgDialog_60107_Content_19 = {
    Text = "Lơ Tan thành thạo đặt tay lên thanh kiếm khổng lồ dựng đứng bên cạnh."
  },
  AvgDialog_60107_Content_2 = {Text = "Vào sân"},
  AvgDialog_60107_Content_20 = {
    Text = "Người giữ bí mật dẫn Misaque đi trên con đường đúng đắn, điều tôi cần làm chỉ là xuất hiện trước mặt {Male=anh ấy,Female=cô ấy} với thanh kiếm của mình khi {Male=anh ấy,Female=cô ấy} cần."
  },
  AvgDialog_60107_Content_21 = {
    Text = "Đúng như cô lơ-tan nói! Tôi tin rằng chủ nhân sẽ dẫn dắt chúng ta tìm ra cách chiến thắng sự rỗng rỗng. Sự bình yên của Misaque chính là minh chứng tốt nhất!"
  },
  AvgDialog_60107_Content_22 = {
    Text = "Orci nhìn lại ngôi trường thanh bình phía sau, đầy kỳ vọng nhấc lại cây thương dài."
  },
  AvgDialog_60107_Content_23 = {
    Text = "Đi nào, cô lơ-tan. Tôi biết nhiều hoạt động đấu kiếm thú vị. Sau khi hoàn thành nhiệm vụ tuần tra hôm nay, chúng ta sẽ mời chủ nhân cùng tham gia…"
  },
  AvgDialog_60107_Content_24 = {
    Text = "Nếu được, có thể mang chúng tôi theo không?"
  },
  AvgDialog_60107_Content_25 = {Text = "!!!"},
  AvgDialog_60107_Content_26 = {
    Text = "Đột ngột, Orci quay người lại."
  },
  AvgDialog_60107_Content_27 = {
    Text = "Cánh cổng của Misaque mở ra lặng lẽ, từ trong đám sương mù dày đặc vốn tách biệt Misaque với thế giới bên ngoài, một nhóm người từ từ bước ra."
  },
  AvgDialog_60107_Content_28 = {
    Text = "Trên đồng phục của họ, biểu tượng của Hội nghị thẩm tra Hiệp định Misidia rõ ràng có thể nhìn thấy."
  },
  AvgDialog_60107_Content_29 = {
    Text = "Bạn… các bạn là…"
  },
  AvgDialog_60107_Content_3 = {Text = "Ding——"},
  AvgDialog_60107_Content_30 = {
    Text = "Điệp viên đứng đầu từ trong ngực lấy ra một tờ giấy có con dấu và hoa văn tối, đưa đến trước mặt Orci."
  },
  AvgDialog_60107_Content_31 = {
    Text = "Sau khi điều tra, thành viên của Misaque do Alistair đứng đầu đã tự ý sử dụng hồ đen để tiến hành nghiên cứu hòa tan bất hợp pháp, đe dọa nghiêm trọng sự an toàn của người dân Reo."
  },
  AvgDialog_60107_Content_32 = {
    Text = "Nhóm Hành động Đặc biệt của Hội đồng xem xét Hiệp định Misidia, đến tiếp quản Misaque và bắt giữ những người vi phạm pháp luật."
  },
  AvgDialog_60107_Content_33 = {
    Text = "Hội nghị thẩm tra…tội phạm…nhưng chúng tôi chưa bao giờ nhận được thông báo!"
  },
  AvgDialog_60107_Content_34 = {
    Text = "Hành động của hội nghị thẩm tra không cần phải thông báo cho trường của cậu, cậu nhóc."
  },
  AvgDialog_60107_Content_35 = {
    Text = "Thế à? Nhưng tôi nhớ quy định của Misaque không phải như vậy."
  },
  AvgDialog_60107_Content_36 = {
    Text = "Lơ Tan cầm kiếm đứng dậy."
  },
  AvgDialog_60107_Content_37 = {
    Text = "Tôi không biết các bạn đã vượt qua sương mù ngoài khuôn viên trường như thế nào, nhưng tôi đoán trước khi bị đánh bại, bạn cũng chẳng thể thành thật đến vậy."
  },
  AvgDialog_60107_Content_38 = {
    Text = "Quy định của Misaque, bất cứ ai xâm nhập mà không được đồng ý, đều sẽ bị coi là kẻ xâm lược."
  },
  AvgDialog_60107_Content_39 = {
    Text = "Xin vui lòng chú ý lời nói của bạn, cô. Hiện tại bạn đang đối thoại với hội nghị thẩm tra!"
  },
  AvgDialog_60107_Content_4 = {
    Text = "Tiếng chuông trong trẻo vang lên, kèm theo tiếng cười đùa của học sinh Misaque từ xa truyền đến, làm cho đàn chim đang nghỉ ngơi trên mái nhà bay lên."
  },
  AvgDialog_60107_Content_40 = {
    Text = "Xin lỗi, tôi học môn giáo dục đại cương không tốt. Hội nghị thẩm tra... là gì?"
  },
  AvgDialog_60107_Content_41 = {Text = "!!!"},
  AvgDialog_60107_Content_42 = {
    Text = "Chưa kịp nhìn rõ, hình dáng của Lơ-tan đã xuất hiện sau lưng anh."
  },
  AvgDialog_60107_Content_43 = {
    Text = "Orci theo sát một cách ăn ý lơ-tan, kích hoạt lá chắn phía sau cô ấy."
  },
  AvgDialog_60107_Content_44 = {
    Text = "Misaque không phải là nơi các ngươi muốn đến là đến được, cậu nhóc."
  },
  AvgDialog_60107_Content_45 = {
    Text = "Lơ-tan đảo ngược cây kiếm lớn, dùng cán kiếm tấn công không thể cản phá vào đội trưởng của hội nghị thẩm tra ——"
  },
  AvgDialog_60107_Content_46 = {Text = "Ding——"},
  AvgDialog_60107_Content_47 = {
    Text = "Hãy dập tắt cơn giận của bạn và lắng nghe tiếng nói từ sâu thẳm tâm trí."
  },
  AvgDialog_60107_Content_48 = {
    Text = "Hãy chìm vào giấc ngủ bình yên, bạn tôi. Tất cả những xao động này đều không liên quan đến các bạn…"
  },
  AvgDialog_60107_Content_49 = {
    Text = "Tiếng chuông gió thanh thoát vang lên từ đâu đó, mặc dù yếu ớt và xa xôi, nhưng lại rất rõ ràng khi truyền vào tai."
  },
  AvgDialog_60107_Content_5 = {
    Text = "Vào giờ hoàng hôn, ánh sáng nhè nhẹ, mơ hồ vượt qua tượng của người sáng lập, chiếu lên khuôn mặt của Lơ-tan."
  },
  AvgDialog_60107_Content_50 = {
    Text = "Thanh kiếm lớn của lơ-tan và khiên súng của Orci rơi xuống đất. Hai người hoàn toàn không phòng bị, trong khoảnh khắc nghe thấy tiếng chuông gió, họ đã mất hết sức lực."
  },
  AvgDialog_60107_Content_51 = {
    Text = "Cơn buồn ngủ mạnh mẽ tràn ngập thân thể họ. Họ cố gắng mở mắt ra."
  },
  AvgDialog_60107_Content_52 = {
    Text = "Trong tầm nhìn mờ ảo, một bóng hình phụ nữ từ từ bước ra từ sau làn sương mù."
  },
  AvgDialog_60107_Content_53 = {
    Text = "Không hổ là Misaque. Cảnh quan nơi đây, đúng như lời đồn, thật quyến rũ."
  },
  AvgDialog_60107_Content_54 = {
    Text = "Bạn… bạn là…"
  },
  AvgDialog_60107_Content_55 = {
    Text = "Chúng ta từng gặp nhau một lần, nhưng có lẽ ngài đã quên rồi."
  },
  AvgDialog_60107_Content_56 = {
    Text = "Nhà nuôi dưỡng người nghèo……bác sĩ tâm thần……"
  },
  AvgDialog_60107_Content_57 = {
    Text = "À, cách đã lâu như vậy mà vẫn còn được nhớ đến, thật vinh hạnh."
  },
  AvgDialog_60107_Content_58 = {
    Text = "Xin lỗi vì không gặp mặt các bạn ngay từ đầu, nhưng đối mặt với thể thức tỉnh của Misaque, muốn ép buộc xông vào, thực sự cần một vài mưu mẹo."
  },
  AvgDialog_60107_Content_59 = {
    Text = "Hãy nghỉ ngơi thật tốt."
  },
  AvgDialog_60107_Content_6 = {
    Text = "Thời tiết thật tuyệt. Orci, hãy đến tập luyện kiếm thuật với tôi đi."
  },
  AvgDialog_60107_Content_60 = {
    Text = "Cô ấy nhẹ nhàng vỗ vào đầu lơ-tan và Orci. Họ không còn sức để chống đỡ, ngất đi."
  },
  AvgDialog_60107_Content_61 = {
    Text = "Clementine đứng dậy, cánh tay hơi nâng lên, chỉ vào Misaque."
  },
  AvgDialog_60107_Content_62 = {
    Text = "Cảnh trường này, vốn dĩ đứng ngoài mọi chuyện, cũng nên đón nhận số phận của nó."
  },
  AvgDialog_60107_Content_63 = {
    Text = "Hành động xâm lược của Misaque đã bắt đầu."
  },
  AvgDialog_60107_Content_64 = {
    Text = "Từ khoảng cách 12 mét, Hannah ẩn nấp trong bụi cỏ, siết chặt miệng mình, không dám phát ra bất kỳ tiếng động nào."
  },
  AvgDialog_60107_Content_65 = {
    Text = "Qua khe hở của đám cỏ, cô nhìn Clementine dẫn đầu đoàn kiểm tra tiến vào bên trong Misaque."
  },
  AvgDialog_60107_Content_66 = {
    Text = "Chuyện lớn……xảy ra rồi……"
  },
  AvgDialog_60107_Content_67 = {
    Text = "Phải nhanh chóng thông báo cho mọi người… và Người Giữ Gìn!"
  },
  AvgDialog_60107_Content_69 = {
    Text = "Cây đũa chỉ huy của người chỉ huy vẽ nên một đường cong du dương trong không khí. Bản nhạc đang bước vào giai đoạn kết thúc."
  },
  AvgDialog_60107_Content_7 = {
    Text = "Cô lơ-tan, cuộc tuần tra của chúng ta vẫn chưa kết thúc."
  },
  AvgDialog_60107_Content_70 = {
    Text = "Những hợp âm mạnh mẽ cùng với bè âm phức tạp đã tạo nên một khung cảnh âm thanh đầy cảm xúc mạnh mẽ, giờ đây đã dần lắng xuống."
  },
  AvgDialog_60107_Content_71 = {
    Text = "Những arpeggio của sáo và đàn tranh từ từ bay ra, như ánh hoàng hôn đang chiếu sáng lên những đám mây."
  },
  AvgDialog_60107_Content_72 = {
    Text = "Hòa âm êm dịu dần tan trong không khí, nốt lặng cuối cùng của dây đàn mang nốt nhạc vào hồi kết."
  },
  AvgDialog_60107_Content_73 = {
    Text = "Trong khoảnh khắc xa xôi này, người chỉ huy đã cất đi cây chỉ huy. Ông im lặng định hình."
  },
  AvgDialog_60107_Content_74 = {
    Text = "Mười giây, khán giả say đắm trong âm nhạc, nhà hát sẽ chìm vào sự yên tĩnh như buổi sớm mai."
  },
  AvgDialog_60107_Content_75 = {
    Text = "Một phút mười lăm giây, tiếng vỗ tay của khán giả sẽ như sấm động, kéo dài không dứt, rồi dần tan biến."
  },
  AvgDialog_60107_Content_76 = {
    Text = "Hai mươi lăm phút, ban nhạc và khán giả sẽ rời đi."
  },
  AvgDialog_60107_Content_77 = {
    Text = "Thời gian không chênh lệch một chút nào so với dự kiến, giống như một buổi biểu diễn chính xác một lần nữa."
  },
  AvgDialog_60107_Content_78 = {
    Text = "Nhạc trưởng gật đầu hài lòng, cúi người chào khán giả trong khán phòng trống vắng lặng."
  },
  AvgDialog_60107_Content_8 = {
    Text = "Bạn này mọi thứ đều tốt, chỉ là quá nghiêm túc."
  },
  AvgDialog_60107_Content_80 = {
    Text = "Trong góc khuất bên cạnh khán đài, một tràng vỗ tay nhẹ nhàng vang lên một lần nữa."
  },
  AvgDialog_60107_Content_81 = {
    Text = "Một buổi biểu diễn vĩ đại, thưa ông Hamlin."
  },
  AvgDialog_60107_Content_82 = {
    Text = "Có lẽ được xem là hoàn chỉnh, nhưng vẫn chưa xứng đáng gọi là vĩ đại. Sự biểu diễn thực sự vĩ đại nằm ngoài rạp hát."
  },
  AvgDialog_60107_Content_83 = {
    Text = "Nhạc trưởng cất cây đũa chỉ huy, cau mày nhìn về phía người phụ nữ ở bên hông khán đài."
  },
  AvgDialog_60107_Content_84 = {
    Text = "Chúng tôi đã nói trước rồi, thưa bà Yu Li-ét, bà không nên xuất hiện trong nhà hát."
  },
  AvgDialog_60107_Content_85 = {
    Text = "Sự hợp tác của chúng tôi không liên quan đến buổi biểu diễn, tôi không muốn buổi biểu diễn của mình bị làm phiền. Tôi nghĩ bạn hiểu điều này ."
  },
  AvgDialog_60107_Content_86 = {
    Text = "Ngoài ra, nếu bạn xuất hiện ở đây với tư cách này, sẽ gây ra những rắc rối không đáng có."
  },
  AvgDialog_60107_Content_87 = {
    Text = "Tất nhiên, ông Hamlin. Chỉ là, nếu không đến tận nơi để nghe buổi biểu diễn của ông, tôi sẽ rất đáng tiếc."
  },
  AvgDialog_60107_Content_88 = {
    Text = "Yu Li-ét mỉm cười gật đầu chào, nhẹ nhàng chỉnh lại nếp nhăn trên vạt áo của mình."
  },
  AvgDialog_60107_Content_89 = {
    Text = "Đối với cách diễn đạt của Hamlin, cô ấy đã quen thuộc và không bận tâm."
  },
  AvgDialog_60107_Content_9 = {
    Text = "Thời gian rảnh rỗi quý giá như vậy, không chịu tìm chút hoạt động giải trí nào thì thật sự quá nhàm chán."
  },
  AvgDialog_60107_Content_90 = {
    Text = "Tôi cũng có việc quan trọng cần phải thông báo với bạn trực tiếp."
