  AvgDialog_60203_Content_20 = {Text = "Vi phạm!"},
  AvgDialog_60203_Content_21 = {
    Text = "Dưới ánh sáng bạc mạnh mẽ đó, vô số xúc tu khổng lồ chui ra từ lòng đất, đánh ngã những điệp viên đang giam giữ học sinh Misaque."
