  AvgDialog_60203_Content_35 = {
    Text = "Người giữ gìn {Male=ngài,Female=cô}, bạn không còn là trẻ con nữa, hãy suy nghĩ thật kỹ. Chúng tôi là nhân viên chính thức, đang tìm kiếm Misaque, đây là lệnh chính thức."
