  },
  AvgDialog_60209_Content_11 = {Text = "Thầy!"},
  AvgDialog_60209_Content_12 = {
    Text = "Chiếc xe lăn khẽ rung lên. Bạn tiến lên đỡ Alistair."
  },
  AvgDialog_60209_Content_13 = {
    Text = "Một câu nói đơn giản dường như đã làm anh ta kiệt quệ về tinh thần, khiến thân thể vốn đã tàn tạ của anh ta càng trở nên yếu ớt."
  },
  AvgDialog_60209_Content_14 = {
    Text = "Thầy/cô, những chuyện này…… thầy/cô làm sao biết được?"
  },
  AvgDialog_60209_Content_15 = {
    Text = "Alistair lăn bánh xe đến bên cửa sổ. Bạn dõi theo ánh mắt của anh ấy, cùng nhìn về vệt sáng trong hồ đen."
  },
  AvgDialog_60209_Content_16 = {
    Text = "Chất thể trí tuệ đã truyền dạy cho Tà Vy rất nhiều kiến thức. Những kiến thức này không hề được ghi lại dưới dạng văn bản, bởi chỉ cần ghi chép bằng chữ viết thôi cũng có thể gây ra tai họa vô tận."
  },
  AvgDialog_60209_Content_17 = {
    Text = "Dư lại trong hồ đen là một vỏ bọc đang ngủ say. Ý thức của Đấng không ở đây, hoặc nói cách khác, không ở trong chiều này, thời gian này…"
  },
  AvgDialog_60209_Content_18 = {
    Text = "Trong khi Người còn tỉnh táo, Người đã thông báo cho tôi những kiến thức này…… khụ khụ……."
  },
  AvgDialog_60209_Content_19 = {
    Text = "Tà Vy không ở trong chiều này… Phải chăng Ngài đang trốn tránh điều gì đó?"
  },
  AvgDialog_60209_Content_2 = {
    Text = "Thảm họa từ bên ngoài thế giới? Thầy giáo, em không hiểu lắm…"
  },
  AvgDialog_60209_Content_20 = {
    Text = "Thái Di Sơ cũng từng nói với tôi rằng, Người đang trốn chạy khỏi một \"cuộc khủng hoảng cuối cùng\"…"
  },
  AvgDialog_60209_Content_21 = {
    Text = "Thảm họa có liên quan đến sự tồn tại tối cao?"
  },
  AvgDialog_60209_Content_22 = {
    Text = "Điều khiến cả hai Đại diện Chất Thể đều cảm thấy sợ hãi như vậy, có phải đây chính là tai họa từ bên ngoài thế giới mà ngài vừa nhắc đến?"
  },
  AvgDialog_60209_Content_23 = {
    Text = "Cuộc thảm họa này có liên quan đến sự tồn tại tối cao kia?"
  },
  AvgDialog_60209_Content_24 = {
    Text = "Alistair nhìn bạn với sự ngưỡng mộ, mỉm cười và gật đầu."
  },
  AvgDialog_60209_Content_25 = {
    Text = "Bạn rất nhạy bén, %player%. Điều này rất tốt."
  },
  AvgDialog_60209_Content_26 = {
    Text = "Sự nhạy bén là phẩm chất quý của Người Giữ Gìn."
  },
  AvgDialog_60209_Content_27 = {
    Text = "Bạn nói đúng. Họ đang sợ hãi."
  },
  AvgDialog_60209_Content_28 = {
    Text = "Alistair ngồi thẳng người, vẻ mặt trở nên nghiêm túc."
  },
  AvgDialog_60209_Content_29 = {
    Text = "Vị tồn tại tối cao, Tà Vy gọi Ngài là, ý chí vô thượng…"
  },
  AvgDialog_60209_Content_3 = {
    Text = "Bạn nhìn chằm chằm vào đoạn cây mẹ trên bàn. Sau khi trở về từ sa mạc, nó đã nằm trên bàn của Alistair, giống như một lời nhắc nhở xấu xí."
  },
  AvgDialog_60209_Content_30 = {
    Text = "Ngài là vị chúa tể duy nhất của vô số vũ trụ. Từ thân Ngài sinh ra ba chất thể lớn. Ngài sáng tạo tất cả, chi phối tất cả và hủy diệt tất cả."
  },
  AvgDialog_60209_Content_31 = {
    Text = "Ngài, chính là nguồn của mọi thảm họa."
  },
  AvgDialog_60209_Content_32 = {
    Text = "Nguồn của mọi thảm họa……Ý ngài là……!"
  },
  AvgDialog_60209_Content_33 = {
    Text = "Đúng vậy. Thứ mà chúng ta luôn muốn hiểu rõ và đánh bại —— rỗng rỗng."
  },
  AvgDialog_60209_Content_34 = {
    Text = "Mối quan hệ giữa rỗng rỗng và ý chí vô thượng rốt cuộc là gì?"
  },
  AvgDialog_60209_Content_35 = {
    Text = "Tà Vy đã không cho tôi biết. Có lẽ, thể chất trí tuệ đã giấu Người một điều gì đó."
  },
  AvgDialog_60209_Content_36 = {
    Text = "Chúng tôi có một giả thuyết, vị ý chí vô thượng kia và.."
  },
  AvgDialog_60209_Content_37 = {
    Text = "Alistair nhìn chằm chằm vào bạn. Bỗng nhiên, lông mày của anh ta nhíu chặt lại."
  },
  AvgDialog_60209_Content_38 = {Text = "Thầy?"},
  AvgDialog_60209_Content_39 = {
    Text = "Một dự cảm mạnh mẽ, giống như ngày Akutê nổ tung. Dự cảm vô cùng xấu…"
  },
  AvgDialog_60209_Content_4 = {
    Text = "Alistair đã lâu không trả lời. Ông nhìn ra hồ đen trống trải bên ngoài cửa sổ, dường như có những mâu thuẫn trong suy nghĩ đang giằng xé tâm trí ông."
  },
  AvgDialog_60209_Content_40 = {
    Text = "Hãy chuẩn bị đi, %player%. Có thể, sắp có chuyện lớn xảy ra."
  },
  AvgDialog_60209_Content_41 = {
    Text = "Điều mà chúng ta không thể tưởng tượng nổi, khiến mọi người đều cảm thấy sợ hãi và đau khổ…"
  },
  AvgDialog_60209_Content_42 = {
    Text = "Đùng đùng đùng——"
  },
  AvgDialog_60209_Content_43 = {
    Text = "Chưa đợi Alistair nói xong, bên ngoài phòng nghiên cứu dưới đất vang lên tiếng gõ cửa gấp gáp."
  },
  AvgDialog_60209_Content_44 = {
    Text = "Alistair nhíu mày suy nghĩ. Bạn mở cửa với vẻ mặt đầy băn khoăn."
  },
  AvgDialog_60209_Content_45 = {
    Text = "Xảy……xảy ra chuyện rồi!"
  },
  AvgDialog_60209_Content_46 = {
    Text = "Hannah? Bạn đến chỗ này làm gì?"
  },
  AvgDialog_60209_Content_47 = {
    Text = "Đây gần hồ đen, rất nguy hiểm, chỉ có những người sở hữu thẻ thông hành đặc biệt mới có thể…"
  },
  AvgDialog_60209_Content_48 = {
    Text = "Chưa để bạn nói xong, Hannah đã kéo bạn dậy và chạy về phía bên ngoài phòng nghiên cứu dưới đất."
  },
  AvgDialog_60209_Content_49 = {
    Text = "Này! Hannah, rốt cuộc…"
  },
  AvgDialog_60209_Content_5 = {
    Text = "Bạn đã tiếp xúc với ba Đại diện của Thể Chất. Tôi nghĩ, đã đến lúc kể cho bạn."
  },
  AvgDialog_60209_Content_50 = {
    Text = "Hội nghị thẩm tra… Hội nghị thẩm tra xâm nhập trường học!"
  },
  AvgDialog_60209_Content_51 = {Text = "!!!"},
  AvgDialog_60209_Content_6 = {
    Text = "Thấy ánh mắt của Alistair, bạn khéo léo bước lên, đỡ lấy chiếc xe lăn của Alistair, đẩy anh ta đến bên bàn."
  },
  AvgDialog_60209_Content_7 = {
    Text = "Bạn hiện đã hiểu bao nhiêu về Tam Chất Thể?"
  },
  AvgDialog_60209_Content_8 = {
    Text = "Không ít. Tôi biết rằng Họ lần lượt nắm giữ quyền bính của trí tuệ, dục vọng và sự vui thú, sở hữu lực lượng to lớn mà chúng ta không thể tưởng tượng được, là những thần minh mạnh mẽ nhất trong vũ trụ này.."
  },
  AvgDialog_60209_Content_9 = {
    Text = "Không, %player%, trên ba chất thể còn có một vị tối cao……"
  },
  AvgDialog_60210_Content_1 = {Text = "Thân tàn"},
  AvgDialog_60210_Content_10 = {
    Text = "Dù là giá trị làm con tin hay mức độ bất tiện trong hành động, luôn có một người cần bạn bảo vệ hơn tôi."
  },
  AvgDialog_60210_Content_100 = {
    Text = "Nó đi báo tin! Ngăn nó lại!"
  },
  AvgDialog_60210_Content_11 = {
    Text = "Tôi hiểu, hiệu trưởng. Sau khi ngài đến khu vực an toàn, tôi sẽ lập tức đi tìm giáo sư Alistair."
  },
  AvgDialog_60210_Content_12 = {
    Text = "Ba người cùng nhìn về phía sau, khe nứt bí ẩn và nguy hiểm như miệng của một con quái vật tham lam khổng lồ màu đen, dường như có thể nuốt chửng cả thành Misaque."
  },
  AvgDialog_60210_Content_13 = {
    Text = "Hy vọng Alistair bình an…"
  },
  AvgDialog_60210_Content_14 = {
    Text = "Sáng nay tôi pha trà đen. Bạn có muốn uống không?"
  },
  AvgDialog_60210_Content_15 = {
    Text = "Đối với những người khuyết tật nặng, việc hấp thụ chất khác ngoài duy trì sức sống chỉ thêm rắc rối mà thôi."
  },
  AvgDialog_60210_Content_16 = {
    Text = "Tôi không muốn làm phiền mình, càng không muốn làm phiền người khác. Xin ngài cứ tự nhiên, Giáo sư đóa."
  },
  AvgDialog_60210_Content_17 = {
    Text = "Đóa thổi nhẹ vào tách trà, rồi nhấp một ngụm nhỏ."
  },
  AvgDialog_60210_Content_18 = {
    Text = "Nước hồ đen tràn vào phòng nghiên cứu ngầm, cuồn cuộn đầy nguy hiểm dưới chân họ, giống như một điệu nhạc quái dị trong buổi họp mặt."
  },
  AvgDialog_60210_Content_19 = {
    Text = "Ghen tỵ chứ? Thân thể này thậm chí còn được trang bị cảm biến mùi, đủ để trải nghiệm cảm giác trà đen ấm áp lướt trên đầu lưỡi."
  },
  AvgDialog_60210_Content_2 = {
    Text = "Ramona thò đầu ra và cẩn thận nhìn quanh đường dẫn thoát hiểm."
  },
  AvgDialog_60210_Content_20 = {
    Text = "Thay vì ghen tị với việc bạn có thể nhấm nháp tách trà đen thơm ngon, tôi càng ghen tị hơn với sự thuận tiện khi bạn có thể chuyển sang các thân thể nhân tạo khác bất kỳ lúc nào."
  },
  AvgDialog_60210_Content_21 = {
    Text = "Rất tiếc, thân thể nhân tạo không thể chịu đựng được sức mạnh tinh thần của bạn. Tận hưởng sự ưu việt của tài năng xuất chúng đồng nghĩa với việc gánh chịu những cái giá đắt đỏ."
  },
  AvgDialog_60210_Content_22 = {
    Text = "Đóa đặt cốc trà xuống, nhìn về phía Alistair."
  },
  AvgDialog_60210_Content_23 = {
    Text = "Giáo sư Alistair, ngài có thể cảm nhận được là ai không?"
  },
  AvgDialog_60210_Content_24 = {
    Text = "Bạn đang nói đến kẻ phản bội trong nhóm Misaque?"
  },
  AvgDialog_60210_Content_25 = {
    Text = "Đúng vậy. Sương mù đặc biệt của Misaque được sáng tạo bởi người sáng lập trường và Tà Vy, vị trí của hồ đen cũng là điều bí ẩn không dễ nắm bắt."
  },
  AvgDialog_60210_Content_26 = {
    Text = "Phá bỏ sương mù, gây nổ hồ đen, những người có thể làm được việc này e rằng chỉ đếm trên đầu ngón tay."
  },
  AvgDialog_60210_Content_27 = {
    Text = "Tôi đã khoanh vùng một số người. Nhưng với thông tin hiện có, việc thu hẹp thêm nữa quả thực rất khó khăn."
  },
  AvgDialog_60210_Content_28 = {
    Text = "Tôi cũng là một trong những người bị khóa?"
  },
  AvgDialog_60210_Content_29 = {
    Text = "Alistair hơi ngẩng đầu, ánh sáng mơ hồ và đầy ẩn ý lấp lánh trong đáy mắt anh."
  },
  AvgDialog_60210_Content_3 = {
    Text = "Bên này không có ai từ hội nghị thẩm tra, chúng ta hãy đi lối này."
  },
  AvgDialog_60210_Content_30 = {
    Text = "Bạn là người đầu tiên."
  },
  AvgDialog_60210_Content_31 = {
    Text = "Đóa nhấp một ngụm trà đỏ, làn khói dày đặc che khuất vẻ mặt của cô, không khí trong phòng nghiên cứu đột nhiên trở nên nặng nề."
  },
  AvgDialog_60210_Content_32 = {
    Text = "Tuy nhiên đã bị loại trừ."
  },
  AvgDialog_60210_Content_33 = {
    Text = "Không phải ngươi, ngươi là \"hạt nhân\" của Misaque, có nhiều cách hơn để tiêu diệt Misaque, không cần phải tốn công như vậy."
  },
  AvgDialog_60210_Content_34 = {
    Text = "Trong cuộc hỗn loạn này, kẻ phản bội ngầm đóng vai trò nguy hiểm nhất."
  },
  AvgDialog_60210_Content_35 = {
    Text = "Khả năng của tôi không phù hợp với chiến trường chính diện. \nTìm ra kẻ nội gián này là nhiệm vụ của tôi. Tôi cần ý kiến của bạn."
  },
  AvgDialog_60210_Content_36 = {
    Text = "Rất tiếc, Giáo sư Đóa, đối với người bạn nội gián này, tôi không có chút cảm nhận nào."
  },
  AvgDialog_60210_Content_37 = {
    Text = "Điều này không nên, toàn bộ Misaque, mọi rung động của mỗi bạc tâm, theo lý thuyết, lẽ ra đều nằm trong tầm kiểm soát của bạn."
  },
  AvgDialog_60210_Content_38 = {
    Text = "Sự thật là vậy. \nAnh ấy không ở trong phạm vi nhận thức của tôi."
  },
  AvgDialog_60210_Content_39 = {
    Text = "Điều này có nghĩa là, anh ta có khả năng thoát khỏi sự nhận biết của bạn?"
  },
  AvgDialog_60210_Content_4 = {
    Text = "Cô ấy quay người, đỡ lấy tay của Khổ Lệ Đặc."
  },
  AvgDialog_60210_Content_40 = {
    Text = "Cũng có các khả năng khác."
  },
  AvgDialog_60210_Content_41 = {
    Text = "Đóa im lặng một lúc, dường như liên tưởng đến điều gì đó."
  },
  AvgDialog_60210_Content_42 = {
    Text = "Tôi đã hiểu. Đây sẽ là một hướng suy nghĩ mới."
  },
  AvgDialog_60210_Content_43 = {
    Text = "Alistair gật đầu, nhắm mắt lại và hít mùi hương từ tách trà trước mặt, sau đó thở dài một cách mãn nguyện."
  },
  AvgDialog_60210_Content_44 = {
    Text = "Bạn thật ung dung. Hiện giờ có lẽ cả Misaque đều đang lo lắng cho bạn."
  },
  AvgDialog_60210_Content_45 = {
    Text = "Tôi là người không cần phải lo lắng nhất."
  },
  AvgDialog_60210_Content_46 = {
    Text = "Đóa nhìn Alistair, trên khuôn mặt bình tĩnh hiện lên một tia không nỡ."
  },
  AvgDialog_60210_Content_47 = {
    Text = "Từ khuôn mặt của bạn, tôi hoàn toàn không thấy bất kỳ sự khó chịu nào. Ý chí của bạn thật đáng khâm phục."
  },
  AvgDialog_60210_Content_48 = {
    Text = "……Bây giờ nỗi đau mà ngài đang gánh chịu, có lẽ đã vượt xa sự tưởng tượng của chúng ta, Giáo sư Alistair?"
  },
  AvgDialog_60210_Content_49 = {
    Text = "Tôi……khụ khụ……"
  },
  AvgDialog_60210_Content_5 = {
    Text = "Ramona, tôi sẽ hộ tống Giám đốc Học viện Khổ Lệ Đặc. Hồ đen gặp vấn đề, tình trạng của bạn hiện tại cũng không được tốt lắm…"
  },
  AvgDialog_60210_Content_50 = {
    Text = "Alistair ho sù mạnh mẽ vài lần, xe lăn va vào bàn, nước trà từ cốc đổ ra, rơi vào hồ đen và biến mất."
  },
  AvgDialog_60210_Content_51 = {
    Text = "Vụ nổ hồ đen, bạn là người gần hồ đen nhất và cũng là người bị ảnh hưởng lớn nhất từ sự chấn động của hồ đen."
  },
  AvgDialog_60210_Content_52 = {
    Text = "Không rời khỏi đây, thân thể của cậu không chịu đựng được đâu."
  },
  AvgDialog_60210_Content_53 = {
    Text = "Người nổi tiếng với sự lý trí, không phù hợp để nói những lời cảm tính như vậy."
  },
  AvgDialog_60210_Content_54 = {
    Text = "Bạn giả vờ giọng điệu vô tri một cách rất cứng nhắc, Giáo sư Đóa."
  },
  AvgDialog_60210_Content_55 = {
    Text = "Alistair mỉm cười lắc đầu."
  },
  AvgDialog_60210_Content_56 = {
    Text = "Tôi đi rồi, hồ đen sẽ hoàn toàn mất kiểm soát. Đến lúc đó, không chỉ Misaque bị hủy diệt."
  },
  AvgDialog_60210_Content_57 = {
    Text = "Đóa đã nghe rõ, giọng nói dịu dàng của Alistair bắt đầu run rẩy không thể kiềm chế. Đó là nỗi đau từ sâu thẳm tinh thần, không thể che giấu."
  },
  AvgDialog_60210_Content_58 = {
    Text = "Những lời quan tâm luôn cần phải nói."
  },
  AvgDialog_60210_Content_59 = {
    Text = "Ngoài lễ nghi vô ích này, tôi tạm thời không nghĩ ra cách khác để thể hiện sự tôn trọng của mình đối với một con người."
  },
  AvgDialog_60210_Content_6 = {
    Text = "Những người trong hội nghị thẩm tra có thể chém bị thương Giám đốc Học viện Khổ Lệ Đặc, thì hoàn toàn có thể làm những việc điên rồ hơn."
  },
  AvgDialog_60210_Content_60 = {
    Text = "Có thể nghe được những lời như vậy từ miệng của bạn không phải là điều dễ dàng. Đây là niềm vinh hạnh của tôi."
  },
  AvgDialog_60210_Content_61 = {
    Text = "Người có thể giúp tôi, có lẽ đang trên đường đến. Xin đừng lo lắng cho tôi."
  },
  AvgDialog_60210_Content_62 = {
    Text = "Còn có nơi khác cần đến, Giáo sư Đớ. \nTrong hồ đen, có một lão già là đủ rồi."
  },
  AvgDialog_60210_Content_63 = {
    Text = "Đóa nhắm mắt lại thở dài, không nói thêm gì nữa, rời khỏi phòng nghiên cứu dưới lòng đất."
  },
  AvgDialog_60210_Content_64 = {
    Text = "Sau lưng cô, Người Giữ Gìn đầu tiên của Misaque ngồi trên xe lăn, thản nhiên nhìn vào điểm sáng yếu ớt trong hồ đen."
  },
  AvgDialog_60210_Content_65 = {
    Text = "Cơ thể tàn tạ còn lại của anh run rẩy nhẹ, mồ hôi và máu thấm qua băng gạc, rơi xuống, hòa vào dòng nước sục sôi dưới chân anh."
  },
  AvgDialog_60210_Content_66 = {
    Text = "Trong chiều sâu không thể nhìn thấy của tinh thần, trong không gian vừa ảo tưởng vừa nguy hiểm, Alistair đối đầu một mình với hồ đen."
  },
  AvgDialog_60210_Content_68 = {
    Text = "Lãnh tụ của Hội Giáo đèn lồng? Yu Li-ét?! Aaaa——"
  },
  AvgDialog_60210_Content_69 = {
    Text = "Giữ bình tĩnh. Càng gần hồ đen, áp lực tinh thần bạn phải chịu càng lớn. \nNếu cảm xúc của bạn trở nên quá kịch liệt, ngay cả âm nhạc của tôi cũng không thể xoa dịu nỗi đau của bạn."
  },
  AvgDialog_60210_Content_7 = {
    Text = "Dù mục đích của họ là bắt cóc con tin hay gì khác, các bạn cần những người có khả năng chiến đấu để hộ tống."
  },
  AvgDialog_60210_Content_70 = {
    Text = "Hiệp hội Điêu khắc gia, những kẻ dấn thân vào biển… những kẻ này…"
  },
  AvgDialog_60210_Content_71 = {
    Text = "Có phải rất bất ngờ không? Thực ra giữa họ đã tồn tại những mối liên hệ phức tạp?"
  },
  AvgDialog_60210_Content_72 = {
    Text = "Sự biến dị mang tên Rỗng Rỗng đã kết nối họ lại, bao quanh và lan tỏa cùng dịch hạch đen, tạo thành một mạng lưới dày đặc bao trùm khắp Cà Đa Sác."
  },
  AvgDialog_60210_Content_73 = {
    Text = "Misaque theo đuổi sự thật về rỗng rỗng và sự tồn tại của nhân loại, về bản chất là đối thủ của sự rỗng rỗng, không thể chung sống với đèn cầm tay đang nỗ lực lan tỏa sự rỗng rỗng."
  },
  AvgDialog_60210_Content_74 = {
    Text = "Hiệp hội Điêu khắc gia mong muốn vượt qua sự xói mòn bằng sức mạnh cá nhân, bất chấp mọi trật tự của xã hội loài người. Tài liệu nghiên cứu và nguồn tài nguyên mà Hội Giáo đèn lồng cung cấp vượt xa những nơi khác — việc Herbert phản bội có lẽ không hề vô can."
  },
  AvgDialog_60210_Content_75 = {
    Text = "Còn những kẻ lao mình xuống biển, chỉ là một nhóm dân ngu muội mà tinh thần vẫn còn sống trong thời đại cũ."
  },
  AvgDialog_60210_Content_76 = {
    Text = "Dục vọng chính là điểm yếu. Với tài năng của Yu Li-ét, việc thao túng những người này chỉ là việc dễ dàng."
  },
  AvgDialog_60210_Content_77 = {
    Text = "Bạn biết quá nhiều rồi."
  },
  AvgDialog_60210_Content_78 = {
    Text = "Không có gì lạ. Trước đây bạn chỉ là chưa có \"quyền hạn\" mà thôi."
  },
  AvgDialog_60210_Content_79 = {
    Text = "Những thông tin này, ngoại trừ sự nổi lên gần đây của Yu Li-ét, phần còn lại chỉ là chuyện trò vặt vãnh sau bữa ăn."
  },
  AvgDialog_60210_Content_8 = {
    Text = "Hãy yên tâm, Giáo sư Sylvia. Tôi không rõ lý do, nhưng dường như biến động của hồ đen không ảnh hưởng đến khả năng chiến đấu của tôi."
  },
  AvgDialog_60210_Content_80 = {
    Text = "Không ngờ lại là cô ta đứng sau tất cả những chuyện này… Vậy ra, hội nghị thẩm tra và kẻ nội gián trong Misaque đều có liên quan đến Hội Giáo đèn lồng?"
  },
  AvgDialog_60210_Content_81 = {
    Text = "Hamlin gật đầu nhẹ nhàng, đôi găng tay trắng và cây chỉ huy giấu sau lưng, giống như một lưỡi kiếm sắc bén luôn sẵn sàng tấn công bất cứ lúc nào."
  },
  AvgDialog_60210_Content_82 = {
    Text = "Một thành viên cấp cao của hội nghị thẩm tra là người do Yu Li-ét an bài. Lực lượng mà người này có thể điều phối hiện nay phần lớn đã tập trung toàn bộ tại Misaque."
  },
  AvgDialog_60210_Content_83 = {
    Text = "Ai là nội gián của Misaque? Bạn biết không?"
  },
  AvgDialog_60210_Content_84 = {
    Text = "Yu Li-ét và anh ta liên lạc đơn tuyến, chỉ họ biết cụ thể là ai."
  },
  AvgDialog_60210_Content_85 = {
    Text = "Ngay cả bạn cũng không rõ, thật sự xem ra muốn tìm ra kẻ nội gián là một việc khó khăn…"
  },
  AvgDialog_60210_Content_86 = {
    Text = "Cô ta cuối cùng có mục đích gì?"
  },
  AvgDialog_60210_Content_87 = {
    Text = "Yu Li-ét như vậy xông vào Misaque, mục đích thực sự là gì?"
  },
  AvgDialog_60210_Content_88 = {
    Text = "Bạn biết bao nhiêu về Kế hoạch Sinh Đôi của Hội Giáo đèn lồng?"
  },
  AvgDialog_60210_Content_89 = {
    Text = "Hamlin không trả lời trực tiếp câu hỏi của bạn, mà thay vào đó ném ra một câu hỏi."
  },
  AvgDialog_60210_Content_9 = {
    Text = "Lôgic của bạn không có vấn đề, Ramona."
  },
  AvgDialog_60210_Content_90 = {
    Text = "Ánh mắt lạnh lùng của anh ta như lưỡi dao sắc bén đâm thẳng vào bạn. Bạn nhíu mày, tập trung hồi tưởng lại."
  },
  AvgDialog_60210_Content_91 = {
    Text = "Trước đây khi tiếp xúc với Lily và Hiro, tôi đã có đôi chút hiểu biết."
  },
  AvgDialog_60210_Content_92 = {
    Text = "Họ gọi hai thân thể được đánh thức cùng nguồn gốc là \"Song Sinh Đèn Lồng\", có lẽ là muốn dùng cách này để gọi một thứ gì đó..."
  },
  AvgDialog_60210_Content_93 = {
    Text = "Hội Giáo đèn lồng cho rằng, việc kết hợp hai thân thể được đánh thức sẽ tạo ra một vật chứa đựng có thể mang thần cách."
  },
  AvgDialog_60210_Content_94 = {
    Text = "Họ muốn sử dụng cách này để tạo ra thần minh."
  },
  AvgDialog_60210_Content_95 = {
    Text = "Tạo ra thần linh…… thế nhưng, điều này có liên quan gì đến Misaque?"
  },
  AvgDialog_60210_Content_96 = {
    Text = "Bởi vì……"
  },
  AvgDialog_60210_Content_97 = {
    Text = "Hamlin bất ngờ dừng lại, ánh mắt sắc bén hướng về sau bia mộ."
  },
  AvgDialog_60210_Content_98 = {
    Text = "Ở phía sau tấm bảng đá hình chiếc chìa khóa màu xám xanh, phát ra âm thanh xào xạc."
  },
  AvgDialog_60210_Content_99 = {
    Text = "Là quái vật đầu người thân chó của Yu Li-ét. Việc tôi giúp bạn tuyệt đối không được để Yu Li-ét biết."
  },
  AvgDialog_60212_Content_1 = {
    Text = "Luyện tập"
  },
  AvgDialog_60212_Content_10 = {
    Text = "Không ngờ, Misaque và hội nghị thẩm tra lại quan tâm tới tôi."
  },
  AvgDialog_60212_Content_11 = {
    Text = "Trong cuộc điều tra, chúng tôi phát hiện rằng lộ trình lưu diễn của bạn và hoạt động của Hội Giáo đèn lồng có độ trùng khớp cao."
  },
  AvgDialog_60212_Content_12 = {
    Text = "Bạn quan sát một cách cảnh giác thân thể được đánh thức trước mặt."
  },
  AvgDialog_60212_Content_13 = {
    Text = "Bạn đã cứu tôi và các thể thức tỉnh, vì điều này tôi rất biết ơn. Nhưng hiện tại Misaque đang rơi vào nguy cơ, hy vọng bạn có thể tha thứ cho sự phòng bị của tôi."
  },
  AvgDialog_60212_Content_14 = {
    Text = "Dọc đường, tôi đã hỏi bạn, bạn đã vào Misaque như thế nào và mục đích của bạn đến đây là gì. Bây giờ, bạn có thể trả lời tôi rồi."
  },
  AvgDialog_60212_Content_15 = {
    Text = "Bạn đã sắp xếp thân thể được đánh thức chưa?"
  },
  AvgDialog_60212_Content_16 = {
    Text = "…Tôi đã cho phần lớn thân thể được đánh thức đi đến gần hồ đen. Bên cạnh chỉ còn lại một vài người này."
  },
  AvgDialog_60212_Content_17 = {
    Text = "Liên kết đã được khôi phục như thế nào?"
  },
  AvgDialog_60212_Content_19 = {
    Text = "Nhờ âm nhạc của bạn, tôi đã khôi phục liên kết với những thân thể được đánh thức."
  },
  AvgDialog_60212_Content_2 = {
    Text = "Đến rồi."
  },
  AvgDialog_60212_Content_20 = {
    Text = "Trường hợp của bạn đặc biệt, tôi chỉ có thể giúp bạn duy trì liên kết với một lượng nhỏ thân thể được đánh thức. Như thế hẳn là đủ rồi."
  },
  AvgDialog_60212_Content_21 = {
    Text = "Anh nhẹ nhàng nhấc cây gậy chỉ huy."
  },
  AvgDialog_60212_Content_22 = {
    Text = "Bây giờ, hãy tấn công tôi!"
  },
  AvgDialog_60212_Content_23 = {Text = "???"},
  AvgDialog_60212_Content_24 = {
    Text = "Ngươi nói cái gì?"
  },
  AvgDialog_60212_Content_25 = {
    Text = "Phát âm tiếng Riolu của tôi chắc là không có vấn đề gì."
  },
  AvgDialog_60212_Content_26 = {
    Text = "Tôi đã nghe, ý tôi là……"
  },
  AvgDialog_60212_Content_27 = {
    Text = "Mục đích khác khi đến phòng học âm nhạc là vì ở đây có rất nhiều nhạc cụ. Sự cộng hưởng giữa các nhạc cụ này có thể giúp khả năng của tôi phát huy tốt hơn."
  },
  AvgDialog_60212_Content_28 = {
    Text = "Không muốn tấn công, phòng thủ cũng được. Chuẩn bị sẵn sàng."
  },
  AvgDialog_60212_Content_29 = {
    Text = "Chưa kịp hiểu rõ tình hình, cây chỉ huy của Hamlin đã thành thạo điểm xuống."
  },
  AvgDialog_60212_Content_3 = {
    Text = "Phòng học nhạc? Nơi này an toàn?"
  },
  AvgDialog_60212_Content_30 = {
    Text = "Một âm thanh dây trong trẻo vang lên cùng một lúc trong phòng học nhạc và trong đầu bạn."
  },
  AvgDialog_60212_Content_31 = {
    Text = "Phần trình diễn bắt đầu."
  },
  AvgDialog_60212_Content_4 = {
    Text = "Về mặt chức năng, khu vực này gần khu vực khám xét của hội nghị thẩm tra, không phải là nơi an toàn."
  },
  AvgDialog_60212_Content_5 = {
    Text = "Ừ, tôi hiểu rồi… nơi nguy hiểm nhất chính là nơi an toàn nhất. ý tưởng rất hay."
  },
  AvgDialog_60212_Content_6 = {
    Text = "Bạn nghĩ quá nhiều. Tôi đến đây vì thích ở những nơi có nhạc cụ."
  },
  AvgDialog_60212_Content_7 = {
    Text = "……Dù đã chọn giúp tôi, thực ra cũng có thể tiếp tục trò chuyện theo hướng đó."
  },
  AvgDialog_60212_Content_8 = {
    Text = "Hamlin, tôi đã nghe về anh, người chỉ huy hàng đầu trên thế giới hiện nay, đang thực hiện chuyến lưu diễn tại Lentiennam."
  },
  AvgDialog_60212_Content_9 = {
    Text = "Misaque và hội nghị thẩm tra đều từng điều tra về bạn. Không ai ngờ rằng bạn lại là một thân thể đã được đánh thức."
  },
  AvgDialog_60213_Content_1 = {
    Text = "Hứ... Tôi vẫn còn bị thương, liên kết vừa mới được khôi phục, có cần thiết như vậy không?"
  },
  AvgDialog_60213_Content_10 = {
    Text = "Hamlin trầm ngâm giây lát, rồi ngẩng đầu lên nhìn bạn."
  },
  AvgDialog_60213_Content_11 = {
    Text = "Tôi đã nghe một bản nhạc vĩ đại, âm thanh của một tồn tại tối cao."
  },
  AvgDialog_60213_Content_12 = {
    Text = "Tôi đến vì nốt nhạc hoàn hảo nhất trong vũ trụ này."
  },
  AvgDialog_60213_Content_13 = {
    Text = "Nhưng những điều này thì có liên quan gì đến tôi chứ? Điểm số môn âm nhạc của tôi thật sự… không lấy gì làm đẹp mắt…"
