  AvgDialog_60213_Content_15 = {
    Text = "Tôi không hiểu lắm……"
  },
  AvgDialog_60213_Content_16 = {
    Text = "Bây giờ không phải là lúc giải thích chuyện này. Điều quan trọng nhất bây giờ là hãy nhanh chóng đến hồ đen để ổn định tình hình."
  },
  AvgDialog_60213_Content_17 = {
    Text = "Người của hội nghị thẩm tra đã đi xa, chúng ta có thể xuất phát được rồi."
