  AvgDialog_60213_Content_19 = {
    Text = "Âm nhạc của tôi có giới hạn về khoảng cách. Không có sự giúp đỡ của tôi, bạn hiện tại không thể làm gì cả."
  },
  AvgDialog_60213_Content_2 = {
