  AvgDialog_60213_Content_23 = {
    Text = "Không ai thích cả. Tuy nhiên, bản giao hưởng này đã bắt đầu. Dưới ánh đèn sân khấu, mỗi nhạc công đều phải đảm nhận trách nhiệm của mình."
  },
  AvgDialog_60213_Content_24 = {
