  },
  AvgDialog_60213_Content_25 = {
    Text = "Anh ta cất cây chỉ huy, hướng về phía cửa lớp học mà đi."
  },
  AvgDialog_60213_Content_26 = {
    Text = "Tôi không để tâm đến sự thù địch của bạn. Nhưng giờ đây, bạn chẳng còn lựa chọn nào khác."
  },
  AvgDialog_60213_Content_27 = {
    Text = "Điều bạn muốn biết, trên đường tôi sẽ kể cho bạn. Xuất phát đi…"
