  },
  AvgDialog_60217_Content_1 = {
    Text = "Đại {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}, Lily... đầu của Lily rất đau.."
  },
  AvgDialog_60217_Content_10 = {Text = "Erica?!"},
  AvgDialog_60217_Content_11 = {
    Text = "Erika! Cô có sao không?"
  },
  AvgDialog_60217_Content_12 = {
    Text = "Phát hiện đối tượng thù địch……vui lòng rời đi……Người Giữ Gìn……"
  },
  AvgDialog_60217_Content_13 = {
    Text = "Cô ấy ôm đầu trong đau đớn, giọng nói lạnh lùng và máy móc vang lên ngắt quãng."
  },
  AvgDialog_60217_Content_14 = {
    Text = "Đường liên kết của tôi đang yếu đi, Erika, tôi sẽ đưa cô đến hồ đen, khi chúng ta đến hồ đen, tất cả sẽ ổn thôi…"
  },
  AvgDialog_60217_Content_15 = {
    Text = "Bạn tiến gần cô ấy, muốn đỡ tay cô ấy. Cô ấy dùng hết ý thức còn lại, lùi lại."
  },
  AvgDialog_60217_Content_16 = {
    Text = "Đổi mới……không thể kiểm soát……nguy hiểm, hãy rời đi ngay……"
  },
  AvgDialog_60217_Content_17 = {Text = "Erica?"},
  AvgDialog_60217_Content_18 = {
    Text = "Bạn dường như nghe thấy một âm thanh cơ khí mờ nhạt."
  },
  AvgDialog_60217_Content_19 = {
    Text = "Sau tiếng nói đó, Erika ngẩng đầu lên, đôi mắt vô cảm nhìn thẳng vào bạn."
  },
  AvgDialog_60217_Content_2 = {
    Text = "Dư…… tinh thần của Dư cũng bị ảnh hưởng……"
  },
  AvgDialog_60217_Content_20 = {
    Text = "Phát hiện nhân viên thù địch, khởi động chương trình loại bỏ."
  },
  AvgDialog_60217_Content_21 = {
    Text = "Cẩn thận!"
  },
  AvgDialog_60217_Content_3 = {
    Text = "Tôi và liên kết của các bạn đang trở nên ngày càng yếu ớt… Nếu tiếp tục như vậy, các bạn sẽ không thể kiểm soát được nữa…"
  },
  AvgDialog_60217_Content_4 = {
    Text = "Tôi đã nói với Hannah, bảo tất cả các thân thể được đánh thức tập trung tại hồ đen."
  },
  AvgDialog_60217_Content_5 = {
    Text = "Chúng ta cũng cần phải nhanh chóng đến đó. Ở đó có sự giúp đỡ của giáo viên và Tà Vy, có thể giúp các bạn ổn định tạm thời."
  },
  AvgDialog_60217_Content_6 = {
    Text = "Trong khi người của hội nghị thẩm tra chưa đuổi kịp, chúng ta hãy……"
  },
  AvgDialog_60217_Content_7 = {
    Text = "Cảnh báo, phát hiện lực lượng địch."
  },
  AvgDialog_60217_Content_8 = {
    Text = "Nguy cơ lưu lại lớn hơn 90%. Hãy rời khỏi nơi này, Người Giữ Gìn."
  },
  AvgDialog_60217_Content_9 = {
    Text = "Vào cuối hành lang, Erika xuất hiện với dáng vẻ di chuyển không vững."
  },
  AvgDialog_60222_Content_1 = {Text = "Erica!"},
  AvgDialog_60222_Content_10 = {
    Text = "Phản ứng của Erika vừa rồi…… Cô ấy không bị ảnh hưởng bởi hồ đen."
  },
  AvgDialog_60222_Content_11 = {
    Text = "Bạn nhìn vào đống đổ nát còn lại sau vụ nổ của Erika, giữa những mảnh vỡ có một thiết bị hình dáng kỳ lạ."
  },
  AvgDialog_60222_Content_12 = {
    Text = "Dụng cụ hình chóp được gắn vào não của Erika, ngay cả khi bạn không hiểu rõ về cấu trúc cơ khí của Erika, bạn cũng biết rõ rằng trong não cô ấy không có dụng cụ như vậy."
  },
  AvgDialog_60222_Content_13 = {
    Text = "Phá vỡ sương mù, kích nổ hồ đen, điều khiển Erika…"
  },
  AvgDialog_60222_Content_14 = {
    Text = "Misaque, có nội gián."
  },
  AvgDialog_60222_Content_15 = {
    Text = "Là thằng nào?! Tôi bảo Brun đi lấy nó... Ừ.."
  },
  AvgDialog_60222_Content_16 = {
    Text = "Cơn đau dữ dội ngắt lời Jenkin, người đang nói trong sự kích động."
  },
  AvgDialog_60222_Content_17 = {
    Text = "Một tiếng bước chân mơ hồ vang đến."
  },
  AvgDialog_60222_Content_18 = {
    Text = "Tiếng nổ đến từ bên đó, đi hướng đó!"
  },
  AvgDialog_60222_Content_19 = {
    Text = "Họ đuổi theo chúng ta rồi… chúng ta hãy rời khỏi nơi này!"
  },
  AvgDialog_60222_Content_2 = {
    Text = "Lùi lại!"
  },
  AvgDialog_60222_Content_20 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} đã chạy về phía đó!Tìm kiếm!"
  },
  AvgDialog_60222_Content_21 = {
    Text = "Hô……hô……"
  },
  AvgDialog_60222_Content_22 = {
    Text = "Bước chân vội vàng tiến gần phía sau bạn, rồi xa dần."
  },
  AvgDialog_60222_Content_23 = {
    Text = "Bạn núp sau cột đứng bên cạnh hành lang, tranh thủ thở dốc."
  },
  AvgDialog_60222_Content_24 = {
    Text = "Hội nghị thẩm tra sẽ nhanh chóng tìm đến nơi này, phải nghĩ cách đối phó… à!…"
  },
  AvgDialog_60222_Content_25 = {
    Text = "Bạn đau đớn ôm đầu."
  },
  AvgDialog_60222_Content_26 = {
    Text = "Một cơn chấn động mạnh mẽ lan rộng trong chiều tinh thần, đầu bạn đau dữ dội, phải vịn vào cột mới có thể đứng vững."
  },
  AvgDialog_60222_Content_27 = {
    Text = "Những cơ thể được thức tỉnh đã hầu như không còn sức để nói. Bạn nhìn về hướng hồ đen với vẻ mặt nghiêm trọng."
  },
  AvgDialog_60222_Content_28 = {
    Text = "Nếu tiếp tục như vậy, cả tôi và thân thể được đánh thức đều không thể chịu đựng được. Phải tìm cách tránh…"
  },
  AvgDialog_60222_Content_29 = {
    Text = "Bắt được bạn rồi, bạn giữ bí mật."
  },
  AvgDialog_60222_Content_3 = {
    Text = "Rầm——"
  },
  AvgDialog_60222_Content_30 = {Text = "!!!"},
  AvgDialog_60222_Content_31 = {Text = "Tránh ra"},
  AvgDialog_60222_Content_32 = {
    Text = "Hai chân bỗng nhiên dùng sức, bạn né sang một bên."
  },
  AvgDialog_60222_Content_33 = {
    Text = "Một thanh kiếm mảnh rơi xuống vị trí bạn vừa đứng, đầu kiếm va vào cột đá, tạo ra một tiếng kêu giòn tan."
  },
  AvgDialog_60222_Content_34 = {
    Text = "Sự sốc tinh thần cộng với vết thương trên thân thể, vậy mà vẫn phản ứng được như thế."
  },
  AvgDialog_60222_Content_35 = {
    Text = "Người giữ bí mật của Misaque, kể từ khi lên nắm quyền đã đối mặt với vô số nguy hiểm."
  },
  AvgDialog_60222_Content_36 = {
    Text = "Dùng một thanh kiếm mảnh, cũng không thể nắm bắt được {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_60222_Content_37 = {
    Text = "Nhanh thật đấy, Clementine."
  },
  AvgDialog_60222_Content_38 = {
    Text = "Bạn vừa cảnh giác với những công cụ gây thôi miên trên người cô ta, vừa quét mắt xung quanh để theo dõi các điệp viên thẩm tra đang tiến lại gần bạn."
  },
  AvgDialog_60222_Content_39 = {
    Text = "Hàng chục điệp viên đã phong tỏa mọi tuyến đường mà bạn có thể trốn thoát."
  },
  AvgDialog_60222_Content_4 = {Text = "Ừ——"},
  AvgDialog_60222_Content_40 = {
    Text = "Thật đáng tiếc, lần này thời gian gấp gáp, không thể hàn huyên thêm với Người Giữ Gìn."
  },
  AvgDialog_60222_Content_41 = {
    Text = "Tuy nhiên, xin Người Giữ Gìn yên tâm. Người của tôi sẽ đưa bạn đến một nơi an toàn, chẳng bao lâu nữa, chúng ta sẽ có đủ thời gian để trò chuyện."
  },
  AvgDialog_60222_Content_42 = {
    Text = "Clementine vẫy tay."
  },
  AvgDialog_60222_Content_43 = {
    Text = "Nhìn những điệp viên đang vây quanh bạn, tim bạn bắt đầu đập mạnh không thể kiểm soát."
  },
  AvgDialog_60222_Content_44 = {
    Text = "Nếu bây giờ bị họ bắt được, thân thể được đánh thức của Misaque sẽ mất kiểm soát…"
  },
  AvgDialog_60222_Content_45 = {
    Text = "Không, tôi không thể để điều này xảy ra.."
  },
  AvgDialog_60222_Content_46 = {
    Text = "Dù hồ đen có mất kiểm soát, dù liên kết với thân thể được đánh thức có yếu đi, chắc chắn sẽ có cách giải quyết.."
  },
  AvgDialog_60222_Content_47 = {
    Text = "Bạn từ từ lùi vào góc cụt, một tay nắm chặt chìa khóa bạc, một tay che vết thương do Erika nổ tung để lại."
  },
  AvgDialog_60222_Content_48 = {
    Text = "Sóng chấn liên tục tác động đến tinh thần của bạn, bạn có thể cảm nhận được sự sôi động của hồ đen."
  },
  AvgDialog_60222_Content_49 = {
    Text = "Những điểm sáng từng tỏa ánh hào quang trong thế giới tinh thần của bạn, tượng trưng cho thân thể được đánh thức, nay đã trở nên vô cùng tối tăm, thậm chí biến mất hoàn toàn khỏi thế giới tinh thần."
  },
  AvgDialog_60222_Content_5 = {
    Text = "Tulô duỗi ra xúc tu, kéo bạn ra khỏi vụ nổ dữ dội."
  },
  AvgDialog_60222_Content_50 = {
    Text = "Người giữ bí mật không còn thân thể được đánh thức, không thể làm gì cả."
  },
  AvgDialog_60222_Content_51 = {
    Text = "Bình tĩnh, suy nghĩ.."
  },
  AvgDialog_60222_Content_52 = {
    Text = "Chắc chắn……còn cách nào đó……"
  },
  AvgDialog_60222_Content_53 = {
    Text = "Bình tĩnh, %player%. Hãy bình tĩnh…"
  },
  AvgDialog_60222_Content_54 = {
    Text = "Chỉ cần có đủ sức mạnh tinh thần để điều khiển chìa khóa bạc, có thể khiến các thân thể được đánh thức xung quanh tái nhận được khả năng chiến đấu mạnh mẽ…"
  },
  AvgDialog_60222_Content_55 = {
    Text = "Không sai, bạn biết cách mà. Bạn luôn hiểu mà."
  },
  AvgDialog_60222_Content_56 = {
    Text = "Nhưng với tình trạng tinh thần hiện tại của bạn, việc ép buộc kích hoạt thân thể được đánh thức sẽ gây ra những tổn thương không thể phục hồi như thế nào?"
  },
  AvgDialog_60222_Content_57 = {
    Text = "Bị tổn thương não? mất khả năng hành động, hoàn toàn trở thành người thực vật? hay là…"
  },
  AvgDialog_60222_Content_58 = {
    Text = "Trong sâu thẳm tinh thần, bạn nghe thấy những tiếng kêu yếu ớt của các thực thể được thức tỉnh. Bạn quay đầu lại, nhìn về phía Misaque, tay nắm chặt chìa khóa bạc run rẩy nhẹ vì dùng sức."
  },
  AvgDialog_60222_Content_59 = {
    Text = "Hậu quả có thể đã không còn quan trọng nữa. Bạn biết mà, bạn không có lựa chọn nào khác."
  },
  AvgDialog_60222_Content_6 = {
    Text = "Các bộ phận của thân thể Erika rơi rớt khắp nơi. Những mảnh vỡ sắc nhọn để lại vô số vết thương trên thân thể bạn, máu chảy ra, nhuộm đỏ đồng phục trường của bạn."
  },
  AvgDialog_60222_Content_60 = {
    Text = "Chỉ còn cách này thôi…"
  },
  AvgDialog_60222_Content_61 = {
    Text = "Bắt giữ {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_60222_Content_62 = {
    Text = "Ép buộc kích hoạt chìa khóa bạc"
  },
  AvgDialog_60222_Content_63 = {
    Text = "Bạn đưa lên tay cầm chìa khóa bạc."
  },
  AvgDialog_60222_Content_64 = {
    Text = "Tôi sẽ không để các người.."
  },
  AvgDialog_60222_Content_65 = {
    Text = "Chương thứ hai, bắt đầu!"
  },
  AvgDialog_60222_Content_66 = {Text = "Ừ——"},
  AvgDialog_60222_Content_67 = {Text = "?!!!"},
  AvgDialog_60222_Content_68 = {
    Text = "Chưa đợi chìa khóa bạc trong tay bạn phát ra ánh sáng chói lọi làm tổn thương bạn và kẻ địch, một giọng nói thanh thoát và lạnh giá vang lên từ phía sau bạn."
  },
  AvgDialog_60222_Content_69 = {
    Text = "Giọng nói đó là quỹ đạo mà nhạc trưởng vạch ra, là mệnh lệnh không thể vi phạm trong thế giới của các nốt nhạc."
  },
  AvgDialog_60222_Content_7 = {
    Text = "Lớn {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}!"
  },
  AvgDialog_60222_Content_70 = {
    Text = "Sau âm thanh này, bản nhạc hùng vĩ vang lên từ sâu thẳm trong tâm trí của các bạn."
  },
  AvgDialog_60222_Content_72 = {Text = "!!!"},
  AvgDialog_60222_Content_73 = {
    Text = "Đây là?…"
  },
  AvgDialog_60222_Content_74 = {
    Text = "Cất chìa khóa bạc của bạn đi. Nếu sử dụng nó ngay bây giờ, bạn sẽ chết."
  },
  AvgDialog_60222_Content_75 = {
    Text = "Nhịp điệu. Giai điệu. Hòa âm mềm mại của dây đàn tràn ngập tâm trí các bạn."
  },
  AvgDialog_60222_Content_76 = {
    Text = "Đó là một dải tần số bí ẩn. Các thành viên của hội nghị thẩm tra ngã xuống đất trong cơn đau đớn vì âm thanh đó, còn bạn cảm thấy mình đang được bao bọc và rửa sạch bởi dòng suối ấm áp."
  },
  AvgDialog_60222_Content_77 = {
    Text = "Bạn cảm nhận rất rõ, liên kết giữa bạn và các thân thể được đánh thức đã được khôi phục. Những chấn động từ hồ đen dường như cũng tan biến hoàn toàn trong tiếng nhạc này."
  },
  AvgDialog_60222_Content_78 = {
    Text = "Clementine ngạc nhiên nhìn về phía chủ nhân của giọng nói."
  },
  AvgDialog_60222_Content_79 = {
    Text = "Là bạn! Tại sao…"
  },
  AvgDialog_60222_Content_8 = {
    Text = "Tôi không sao……"
  },
  AvgDialog_60222_Content_80 = {
    Text = "Nhạc cụ gõ, ngừng lại."
  },
  AvgDialog_60222_Content_81 = {
    Text = "Người đàn ông nhẹ nhàng vung cây gậy chỉ huy. Một âm thanh mệnh lệnh ngắn gọn và quyết đoán, mang lại sự yên lặng trong chớp mắt."
  },
  AvgDialog_60222_Content_82 = {
    Text = "Clementine không còn đủ sức để đứng, ngã xuống đất."
  },
  AvgDialog_60222_Content_83 = {
    Text = "Bạn… bạn là…"
  },
  AvgDialog_60222_Content_84 = {
    Text = "Những người khác sẽ đến rất nhanh, âm nhạc của tôi không thể kéo dài lâu được."
  },
  AvgDialog_60222_Content_85 = {
    Text = "Tôi sẽ đưa bạn đến một nơi an toàn."
  },
  AvgDialog_60222_Content_86 = {
    Text = "Anh ta quay người, gật đầu nhẹ với bạn, biểu cảm bình thản như mặt nước cổ giếng."
  },
  AvgDialog_60222_Content_87 = {
    Text = "Nhạc trưởng Hamlin, sẵn sàng phục vụ quý vị."
  },
  AvgDialog_60222_Content_9 = {
    Text = "Erika dường như không bị hồ đen ảnh hưởng"
  },
  AvgDialog_60223_Content_1 = {
    Text = "Khi các bạn chuẩn bị tiến lên kết liễu nó, con chó mặt người vốn đã hấp hối đột nhiên nhảy vọt lên, lao ra khỏi bên cạnh các bạn."
  },
  AvgDialog_60223_Content_10 = {
    Text = "Một phụ nữ vạm vỡ xuất hiện trước mặt các ngươi, gài dao vào bao."
  },
  AvgDialog_60223_Content_11 = {
    Text = "Elva! Are you okay?"
  },
  AvgDialog_60223_Content_12 = {
    Text = "Chịu một số tác động và tuân lệnh rút lui về gần hồ đen."
  },
  AvgDialog_60223_Content_13 = {
    Text = "Vị này là?"
  },
  AvgDialog_60223_Content_14 = {
    Text = "Cô nhíu mày, nắm chặt con dao phía sau lưng."
  },
  AvgDialog_60223_Content_15 = {
    Text = "Trên người anh ta có mùi hương của Hội Giáo đèn lồng."
  },
  AvgDialog_60223_Content_16 = {
    Text = "Đây là Hamlin…… những chuyện khác sau sẽ giải thích thêm cho bạn, hiện giờ anh ấy là đồng minh của Misaque."
  },
  AvgDialog_60223_Content_17 = {
    Text = "Bạn bước lên, kiểm tra thi thể của con chó mặt người."
  },
  AvgDialog_60223_Content_18 = {
    Text = "Đúng là dấu hiệu của Hội Giáo đèn lồng. Nó muốn đi về hướng hồ đen……"
  },
  AvgDialog_60223_Content_19 = {
    Text = "Yu Li-ét đã đến hồ đen. Chúng ta cần hành động nhanh hơn một chút."
  },
  AvgDialog_60223_Content_2 = {
    Text = "Nó chạy rồi! Cản nó lại!"
  },
  AvgDialog_60223_Content_20 = {
    Text = "Bạn dọn dẹp đồ đạc, ánh mắt hướng thẳng về phía tháp chuông. \nTrong suốt ba trăm năm, hồ đen vẫn luôn ẩn mình trong hố sâu dưới chân nó."
  },
  AvgDialog_60223_Content_21 = {
    Text = "Hamlin, bạn vừa nói, Kế hoạch Song Sinh và Misaque có mối quan hệ gì với nhau?"
  },
  AvgDialog_60223_Content_22 = {
    Text = "Đèn đã tạo ra ba cặp song sinh, hai trong số đó đã thất bại hoàn toàn."
  },
  AvgDialog_60223_Content_23 = {
    Text = "Họ đã tạo ra cặp song sinh đầu tiên và cũng là cặp có hy vọng thành công nhất, ở Misaque."
  },
  AvgDialog_60223_Content_24 = {Text = "Ai đó?"},
  AvgDialog_60223_Content_25 = {
    Text = "Nhiều năm trước, một trong cặp song sinh đầu tiên do Hội Giáo đèn lồng chế tạo bằng toàn bộ lực lượng của giáo hội đã bị Lord Dekster, người được Misaque cử đi, dẫn đầu đội ngũ bắt giữ."
  },
  AvgDialog_60223_Content_26 = {
    Text = "Khi nghe thấy tên \"Dexter\", trái tim bạn nhảy lên tận cổ họng."
  },
  AvgDialog_60223_Content_27 = {
    Text = "Hamlin hạ thấp hàng mi dài, nói nhỏ những suy nghĩ bạn không muốn tin."
  },
  AvgDialog_60223_Content_28 = {
    Text = "Cô ấy tên là Ramona."
  },
  AvgDialog_60223_Content_29 = {
    Text = "Đầu óc bạn hoa lên, mọi thứ xung quanh mơ hồ như một giấc mơ sắp tỉnh."
  },
  AvgDialog_60223_Content_3 = {
    Text = "Hamlin vung nhanh cây gậy chỉ huy, âm nhạc vang lên, nhưng tốc độ của chó mặt người cực kỳ nhanh, chỉ trong nháy mắt đã chạy đến rìa phạm vi tấn công của Hamlin."
  },
  AvgDialog_60223_Content_30 = {
    Text = "Bạn đang nói rằng.."
  },
  AvgDialog_60223_Content_31 = {
    Text = "Bạn học của bạn, bạn bè của bạn, người bạn thân thiết nhất của bạn."
  },
  AvgDialog_60223_Content_32 = {
    Text = "Yu Li-ét đã sử dụng toàn bộ lực lượng của mình. Cô ấy đã đến đây vì Ramona."
  },
  AvgDialog_60223_Content_4 = {
    Text = "Tiếng nhạc khiến nó loạng choạng, nhưng không ngăn cản hoàn toàn."
  },
  AvgDialog_60223_Content_5 = {
    Text = "Không để nó chạy thoát!"
  },
  AvgDialog_60223_Content_6 = {
    Text = "Bạn đuổi theo một cách vô ích. Tốc độ của chó mặt người nhanh đến mức nó sắp chạy ra khỏi tầm mắt của các bạn…"
  },
  AvgDialog_60223_Content_7 = {Text = "Xèo——"},
  AvgDialog_60223_Content_8 = {
    Text = "Một ánh dao bỗng nhiên xuất hiện từ sau bụi cỏ, cắt qua đầu chó mặt người."
  },
  AvgDialog_60223_Content_9 = {
    Text = "Đầu lâu và thân thể tách rời, lăn xuống đất, để lại một vệt máu bẩn thỉu."
  },
  AvgDialog_60327_Content_1 = {
    Text = "Rầm——"
  },
  AvgDialog_60327_Content_10 = {
    Text = "Cú rung động mạnh mẽ đẩy các người ra sau. Song Tử phát ra tiếng rít sắc nhọn lớn, gần như khiến màng nhĩ của bạn không chịu nổi."
  },
  AvgDialog_60327_Content_11 = {
    Text = "Bánh xe khổng lồ tượng trưng cho thời gian và số phận vỡ vụn, sau đó là thân tượng đá."
  },
  AvgDialog_60327_Content_12 = {
    Text = "Trong tiếng rít, tượng thần song sinh vỡ nát, sụp đổ. Những khối lớn hóa thành rỗng rỗng màu đen rồi rơi xuống hồ đen, không để lại dấu vết nào."
  },
  AvgDialog_60327_Content_13 = {
    Text = "Người giữ bí mật, chúng ta…… thành công rồi?"
  },
  AvgDialog_60327_Content_14 = {
    Text = "Đúng vậy, Ramona, chúng ta đã thành công!"
  },
  AvgDialog_60327_Content_15 = {
    Text = "Bạn ôm chặt cô ấy."
  },
  AvgDialog_60327_Content_16 = {
    Text = "Lần này, Ramona không còn giãy dụa. Cô ấy nằm trong vòng tay bạn, mỉm cười như một đứa trẻ."
  },
  AvgDialog_60327_Content_17 = {
    Text = "Cảm ơn bạn, %player%."
  },
  AvgDialog_60327_Content_18 = {
    Text = "Bạn ngẩng đầu lên."
  },
  AvgDialog_60327_Content_19 = {
    Text = "Hình bóng canh gác trước cánh cửa, hình bóng gặp gỡ bạn trong ảo cảnh, đang đứng trang nghiêm trước mặt bạn."
  },
  AvgDialog_60327_Content_2 = {Text = "Ramona!"},
  AvgDialog_60327_Content_20 = {Text = "Tavy?!"},
  AvgDialog_60327_Content_21 = {
    Text = "Tà Vy? Bạn…"
  },
  AvgDialog_60327_Content_22 = {
    Text = "Ý thức của tôi và Tà Vy hòa nhập rồi phân ly trong tượng thần."
  },
  AvgDialog_60327_Content_23 = {
    Text = "Sau khi tượng thần bị phá hủy, ý thức của cô ấy cũng trở lại với thân xác của cô ấy."
  },
  AvgDialog_60327_Content_24 = {
    Text = "Sức mạnh của thể chất trí tuệ trên cơ thể tôi đã gần như cạn kiệt. Chiều ẩn náu đã bị nuốt chửng bởi sự tan biến."
  },
  AvgDialog_60327_Content_25 = {
    Text = "May mắn thay, tôi cũng không cần phải trốn nữa. Ý chí vô thượng không còn nghe được tiếng nói của tôi."
  },
  AvgDialog_60327_Content_26 = {
    Text = "Tà Vy mỉm cười nhẹ với bạn. Một vầng sáng nhạt bao phủ khuôn mặt yếu đuối và hiền từ của cô ấy."
  },
  AvgDialog_60327_Content_27 = {
    Text = "Bạn đã làm được điều đã hứa với tôi, %player%."
  },
  AvgDialog_60327_Content_28 = {
    Text = "Bạn đã đánh bại chúng tôi… Bạn đã cứu chúng tôi."
  },
  AvgDialog_60327_Content_29 = {
    Text = "Người giữ bí mật, bạn nhìn xem ."
  },
  AvgDialog_60327_Content_3 = {
    Text = "Bạn phi thân ra, tiếp lấy cái hình dáng yếu đuối đó trong bức tượng thần sụp đổ."
  },
  AvgDialog_60327_Content_30 = {
    Text = "Bạn dõi theo ánh mắt của Ramona."
  },
  AvgDialog_60327_Content_31 = {
    Text = "Sau tượng đá, hai cánh cửa đá khổng lồ ngừng di chuyển, vô số hình ảnh ảo bên trong trở nên bình yên."
  },
  AvgDialog_60327_Content_32 = {
    Text = "Màu sắc rực rỡ chảy chậm rãi bên trong cánh cửa, giống như một giấc mơ không bao giờ kết thúc."
  },
  AvgDialog_60327_Content_4 = {
    Text = "Người giữ… Người Giữ Gìn…"
  },
  AvgDialog_60327_Content_5 = {
    Text = "Ramona nhìn bạn. Bạn có chút khó phân biệt cô ấy tồn tại ở chiều không gian nào, cũng như khó phân biệt cô ấy rốt cuộc là Ramona, là Tà Vy hay ai khác."
  },
  AvgDialog_60327_Content_6 = {
    Text = "Nhưng những điều đó không quan trọng. Điều quan trọng là, cô ấy đã trở lại bên cạnh bạn, giống như bao lần trước đây."
  },
  AvgDialog_60327_Content_7 = {
    Text = "Bạn nắm lấy tay cô ấy,giống như lần đầu tiên trở thành Người Giữ Gìn."
  },
  AvgDialog_60327_Content_8 = {
    Text = "Sức mạnh tinh thần không ngừng, giống như đại dương mênh mông, tuôn chảy vào chìa khóa bạc, rồi truyền vào cơ thể của Ramona."
  },
  AvgDialog_60327_Content_9 = {
    Text = "Ù a a——"
  },
  AvgDialog_60340_Content_1 = {Text = "Đường"},
  AvgDialog_60340_Content_10 = {
    Text = "Cô ấy và Sylva đang hộ tống Khổ Lệ Đặc, đi từ hành lang hẻo lánh ở phía tây đến tòa nhà Khoa Sinh học…"
  },
  AvgDialog_60340_Content_11 = {
    Text = "Hành lang phía Tây?"
  },
  AvgDialog_60340_Content_12 = {
    Text = "Nghe lời của Elva, Hamlin nhíu mày nhẹ."
  },
  AvgDialog_60340_Content_13 = {
    Text = "Trước khi tôi tìm đến bạn, Herbert đã dẫn người đi về phía tây trường học. Nhiệm vụ của anh ta là tìm Ramona."
  },
  AvgDialog_60340_Content_14 = {
    Text = "Ramona rất thông minh, với một người như Herbert, anh ta khó lòng làm gì được cô ấy…"
  },
  AvgDialog_60340_Content_15 = {
    Text = "Không hề đơn giản. Trong cơ thể Ramona vẫn lưu lại dấu ấn mà Hội Giáo đèn lồng đã khắc ghi."
  },
  AvgDialog_60340_Content_16 = {
    Text = "Dựa theo dấu vết mờ nhạt, họ không chỉ có thể theo dõi vị trí của Ramona, mà thậm chí còn có thể chủ động tước bỏ khả năng hành động của cô ấy."
  },
  AvgDialog_60340_Content_17 = {Text = "!!!"},
  AvgDialog_60340_Content_18 = {
    Text = "Tôi sẽ dùng âm nhạc tạm thời tăng cường liên kết tinh thần của bạn lên mức bình thường, bạn có thể thử tìm cô ấy."
  },
  AvgDialog_60340_Content_19 = {Text = "Cảm ơn!"},
  AvgDialog_60340_Content_2 = {
    Text = "Ý của bạn là… Ramona do Đèn Pin tạo ra?!"
  },
  AvgDialog_60340_Content_20 = {
    Text = "Hamlin khẽ gật đầu. Chiếc đũa chỉ huy vút lên, vẽ nên một đường cong tuyệt đẹp trong không trung."
  },
  AvgDialog_60340_Content_21 = {
    Text = "Một chuỗi âm nhạc nồng nhiệt theo động tác nhanh nhẹn của anh ta tràn vào tâm trí bạn.\nBạn nhắm mắt, để mặc cho dòng âm nhạc như sóng cuốn hút ý thức đang trôi nổi của bạn."
  },
  AvgDialog_60340_Content_22 = {
    Text = "Tìm kiếm Ramona"
  },
  AvgDialog_60340_Content_23 = {
    Text = "Trong không gian tinh thần, những điểm sáng quen thuộc lại một lần nữa sáng lên. Bạn nỗ lực tìm kiếm."
  },
  AvgDialog_60340_Content_24 = {
    Text = "Trong những điểm sáng này, dù bạn có tìm kiếm thế nào đi nữa, cũng không thể tìm thấy hình bóng thân thương đó."
  },
  AvgDialog_60340_Content_26 = {
    Text = "Người giữ bí mật, như thế nào?"
  },
  AvgDialog_60340_Content_27 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} không tìm thấy."
  },
  AvgDialog_60340_Content_28 = {
    Text = "Vì mục đích của việc mang đèn là nhắm vào Ramona, chúng ta hãy đi cứu Ramona trước!"
  },
  AvgDialog_60340_Content_29 = {
    Text = "Bạn vừa nói, vừa đi theo hướng tây."
  },
  AvgDialog_60340_Content_3 = {
    Text = "Thân thể di chuyển về phía hồ đen một cách máy móc, nhưng tâm trí của bạn đã hoàn toàn bị lời nói của Hamlin chiếm lấy."
  },
  AvgDialog_60340_Content_30 = {
    Text = "Tôi biết Ramona quan trọng với bạn. Tuy nhiên, hãy giữ bình tĩnh, Người Giữ Gìn."
  },
  AvgDialog_60340_Content_31 = {
    Text = "Việc xử lý vấn đề ở hồ đen cần ưu tiên hơn. Hiện bạn vẫn chưa rõ vị trí của Ramona."
  },
  AvgDialog_60340_Content_32 = {
    Text = "Điều này khác với trước đây. Chiếc đèn là nhằm vào cô ấy, tôi không thể bỏ mặc."
  },
  AvgDialog_60340_Content_33 = {
    Text = "Chỉ cần đến vị trí cuối cùng của cô ấy, chúng ta sẽ nhanh chóng xác định được cô ấy…"
  },
  AvgDialog_60340_Content_34 = {
    Text = "Tôi biết nàng ở đâu."
  },
  AvgDialog_60340_Content_35 = {Text = "!!!"},
  AvgDialog_60340_Content_36 = {
    Text = "Bạn đột ngột dừng bước. Hamlin khẽ gật đầu, trang phục gọn gàng của anh ấy đung đưa nhịp nhàng theo cử động."
  },
  AvgDialog_60340_Content_37 = {
    Text = "Bạn không thể tìm thấy cô ấy trong kích thước tinh thần. Rõ ràng, cô ấy đã bị bắt."
  },
  AvgDialog_60340_Content_38 = {
    Text = "Theo kế hoạch, Herbert sẽ đưa Ramona đến hồ đen. Cô ấy tạm thời sẽ không gặp nguy hiểm."
  },
  AvgDialog_60340_Content_39 = {Text = "Tại sao?"},
  AvgDialog_60340_Content_4 = {
    Text = "Gần hai mươi năm trước, Hội Giáo đèn lồng đã xâm nhập vào hồ đen với sự giúp đỡ của Herbert, sử dụng thần thức của Tà Vy để tạo ra thánh thể song sinh Ramona."
  },
  AvgDialog_60340_Content_40 = {
    Text = "Lễ nghi tạo thần bằng đèn cầm tay cần mượn lực lượng từ rã nứt. Rã nứt của Misaque chỉ có một."
  },
  AvgDialog_60340_Content_41 = {
    Text = "——Ngoài việc cản trở hành động của bạn, khiến thân thể được đánh thức rơi vào hỗn loạn, làm cho lực lượng của hồ đen xuất hiện nhiều hơn cũng là mục đích của Yu Li-ét khi kích nổ hồ đen."
  },
  AvgDialog_60340_Content_42 = {Text = "Narmona…"},
  AvgDialog_60340_Content_43 = {
    Text = "Việc Ramona chết đi không mang lại ý nghĩa gì. Lễ tạo thần cần thời gian chuẩn bị dài, trước đó Ramona vẫn an toàn."
  },
  AvgDialog_60340_Content_44 = {
    Text = "Thì ra là vậy…… Tôi hiểu rồi."
  },
  AvgDialog_60340_Content_45 = {
    Text = "Bạn hít một hơi sâu, làm mình bình tĩnh lại, sau đó nhìn về phía cửa vào đường dẫn dưới đất không xa."
  },
  AvgDialog_60340_Content_46 = {
    Text = "Đi nào…… Chúng ta đến hồ đen, tìm họ!"
  },
  AvgDialog_60340_Content_5 = {
    Text = "Khi đang chuẩn bị rời đi, Ramona được một giáo sư từ Misaque cứu giúp. Từ đó, cô ấy vẫn luôn ở lại Misaque."
  },
  AvgDialog_60340_Content_6 = {
    Text = "Giáo sư Dexter……đúng, ông ấy đã đề cập đến nguồn gốc của Ramona."
  },
  AvgDialog_60340_Content_7 = {
    Text = "Thì ra, năm đó anh ấy đã cứu Ramona khỏi tay Hội Giáo đèn lồng!"
  },
  AvgDialog_60340_Content_8 = {
    Text = "Vì Hội Giáo đèn lồng đang nhắm vào Ramona, nên phải nhanh chóng thông báo cho cô ấy cẩn thận…"
  },
  AvgDialog_60340_Content_9 = {
    Text = "Trên đường đến đây, tôi đã gặp ấy."
  },
  AvgDialog_60341_Content_1 = {
    Text = "Loại bỏ những điệp viên của hội nghị thẩm tra trên đường, bạn đến trước căn phòng quen thuộc, nhẹ nhàng đẩy cửa ra."
  },
  AvgDialog_60341_Content_10 = {
    Text = "Alistair nhẹ nhàng thở dài."
  },
  AvgDialog_60341_Content_11 = {
    Text = "Thầy giáo, xin hãy cho em biết… em nên làm gì bây giờ?"
  },
  AvgDialog_60341_Content_12 = {
    Text = "Lực lượng của Tam Chất Thể, tôi đã cảm nhận được… Họ đều đã xuất hiện trong hồ đen."
  },
  AvgDialog_60341_Content_13 = {
    Text = "Mặc dù không biết lý do, nhưng tôi đã thấy con đường bạn sẽ đi."
  },
  AvgDialog_60341_Content_14 = {
    Text = "Đi đến hồ đen, %player%. Đi tìm ba thực thể lớn."
  },
  AvgDialog_60341_Content_15 = {
    Text = "Họ sẽ giúp chúng ta?"
  },
  AvgDialog_60341_Content_16 = {
    Text = "Đối với thảm họa cuối cùng, ba thực thể chính đã có những lựa chọn hoàn toàn khác biệt."
  },
  AvgDialog_60341_Content_17 = {
    Text = "Thể chất trí tuệ chọn đối kháng. Cô ấy chọn ra người được chọn, thiết lập Misaque, truyền dạy Công nghệ Bạc Tâm cho loài người."
  },
  AvgDialog_60341_Content_18 = {
    Text = "Yêu đã chọn cách trốn tránh. Cô lợi dụng các đại diện của mình, gieo rắc hạt giống ở mọi nơi, với hy vọng có thể sống sót qua thảm họa cuối cùng bằng cách này."
  },
  AvgDialog_60341_Content_19 = {
    Text = "Chất thể của niềm vui?"
  },
  AvgDialog_60341_Content_2 = {
    Text = "Bạn đã đến, %player%, khụ…"
  },
  AvgDialog_60341_Content_20 = {
    Text = "Tà Vy nói với tôi, Đấng chọn là đứng ngoài quan sát. Đấng không quan tâm đến sự sống, cũng không quan tâm đến cái chết. Ngoài việc thỏa mãn bản thân, Đấng không quan tâm đến bất cứ điều gì."
  },
  AvgDialog_60341_Content_21 = {
    Text = "Như vậy, ngoài thể chất trí tuệ, thái độ của hai người kia đối với Misaque không rõ ràng, không chắc chắn sẽ giúp tôi…"
  },
  AvgDialog_60341_Content_22 = {
    Text = "Điều này không quan trọng. Bạn không phải đi cầu cứu Các Ngài, %player%."
  },
  AvgDialog_60341_Content_23 = {
    Text = "Trong ánh mắt ôn hòa của Alistair, bỗng lóe lên một tia ánh sáng sắc lẹm."
  },
  AvgDialog_60341_Content_24 = {
    Text = "Bạn phải làm là đi lấy khả năng của Họ, nhận quyền năng của Họ!"
  },
  AvgDialog_60341_Content_25 = {
    Text = "Có thể…… đó là ba chất thể……"
  },
  AvgDialog_60341_Content_26 = {
    Text = "Thầy… điều này…"
  },
  AvgDialog_60341_Content_27 = {
    Text = "Họ còn không chịu giúp đỡ, làm sao có thể đồng ý…"
  },
  AvgDialog_60341_Content_28 = {
    Text = "Và những quyền hạn đó là gì, cách sử dụng chúng như thế nào, tôi không rõ."
  },
  AvgDialog_60341_Content_29 = {
    Text = "Đây là con đường của bạn. Bạn sẽ hiểu."
  },
  AvgDialog_60341_Content_3 = {
    Text = "Thầy Alistair!"
  },
  AvgDialog_60341_Content_30 = {
    Text = "Nụ cười của Alistair giống như một bàn tay dịu dàng, vuốt ve qua đầu bạn."
  },
  AvgDialog_60341_Content_31 = {
    Text = "Trên con đường này, bạn sẽ có bạn bè, và kẻ thù."
  },
  AvgDialog_60341_Content_32 = {
    Text = "Dòng lũ sắp đến, mỗi người đều phải đóng vai trò của mình. Tất cả chúng ta đều như nhau."
  },
  AvgDialog_60341_Content_33 = {
    Text = "Anh ta liếc nhìn bạn và Hamlin, lời nói đầy ẩn ý, không biết là nói với ai."
  },
  AvgDialog_60341_Content_34 = {
    Text = "Hamlin đứng trong bóng tối, gật đầu nhẹ chào anh ta."
  },
  AvgDialog_60341_Content_35 = {
    Text = "Alistair không nói thêm gì nữa. Anh ta quay người đi và tiếp tục nhìn vào cái hồ đen không có bờ bến này."
  },
  AvgDialog_60341_Content_36 = {
    Text = "Đừng lo lắng về hồ đen, cũng như đừng lo lắng về tôi."
  },
  AvgDialog_60341_Content_37 = {
    Text = "Điều bạn nên biết, bạn sẽ sớm biết."
  },
  AvgDialog_60341_Content_38 = {
    Text = "Đi đi. Đã đến lúc, để bạn bước trên con đường riêng của mình."
  },
  AvgDialog_60341_Content_4 = {
    Text = "Máu tươi phun ra từ miệng của Alistair, nhuộm đỏ thẫm nửa người băng bó."
  },
  AvgDialog_60341_Content_5 = {
    Text = "Sau vài giờ ngắn ngủi, toàn thân Alistair trở nên yếu đuối không thể chịu nổi, thân thể ông run rẩy nhẹ vì lạnh và đau đớn, trên chiếc xe lăn, ông như đang chực ngã xuống."
  },
  AvgDialog_60341_Content_6 = {
    Text = "Thầy… tôi đến trễ… bây giờ tôi sẽ đưa thầy ra ngoài!"
  },
  AvgDialog_60341_Content_7 = {
    Text = "Alistair không nói nhiều, chỉ mỉm cười và lắc đầu một cách nhẹ nhàng."
  },
  AvgDialog_60341_Content_8 = {
    Text = "Dẹp yên hồ đen là trách nhiệm của tôi. Trách nhiệm của bạn không nằm ở đây."
  },
  AvgDialog_60341_Content_9 = {
    Text = "Đó là một con đường, vất vả hơn tôi vạn lần…"
  },
  AvgDialog_60342_Content_1 = {
    Text = "Đã đến rồi!"
  },
  AvgDialog_60342_Content_10 = {
    Text = "Bạn bước lên và đưa tay ra với cô ấy."
  },
  AvgDialog_60342_Content_11 = {
    Text = "Hãy trả lời tôi, Tà Vy…"
  },
  AvgDialog_60342_Content_12 = {Text = "!!!"},
  AvgDialog_60342_Content_13 = {
    Text = "Đây là…"
  },
  AvgDialog_60342_Content_14 = {
    Text = "Ngay khi chạm vào thân thể của Tà Vy, hồ đen biến mất trước mắt bạn."
  },
  AvgDialog_60342_Content_15 = {
    Text = "Bạn nhìn vào chất lỏng đang chảy trước mắt. Bạn không rõ chúng là gì, đưa tay ra, để mặc chúng xuyên qua thân thể, chảy qua một cách chậm rãi."
  },
  AvgDialog_60342_Content_16 = {
    Text = "Trong ánh sáng huyền ảo này, những hình ảnh hư vô phảng phất trước mắt bạn. Một khuôn mặt quen thuộc dần hiện ra trước mặt bạn."
  },
  AvgDialog_60342_Content_17 = {
    Text = "Ramona! Đây là…"
  },
  AvgDialog_60342_Content_18 = {
    Text = "Ý thức, giấc mơ, sự hợp nhất của vô số thời gian và chiều, nơi giao thoa giữa mọi lý tính và phi lý tính. Một điểm kỳ dị không tồn tại…"
  },
  AvgDialog_60342_Content_19 = {
    Text = "Ramona huyền ảo mở miệng, kể về nguồn gốc nơi đây, sau đó cô ấy biến mất."
  },
  AvgDialog_60342_Content_2 = {
    Text = "Ramona có vẻ như không ở đây…"
  },
  AvgDialog_60342_Content_20 = {Text = "Ramona!"},
  AvgDialog_60342_Content_21 = {
    Text = "Đó là bóng của cô ấy. Một bóng ma từ dĩ vãng."
  },
  AvgDialog_60342_Content_22 = {
    Text = "Một giọng nói, như thể vọng đến từ cõi xa xăm, lại như thể vang lên từ sâu trong tâm trí bạn."
  },
  AvgDialog_60342_Content_23 = {
    Text = "Chào mừng đến nơi trú ẩn bí mật của tôi. Người giữ bí mật."
  },
  AvgDialog_60342_Content_24 = {
    Text = "Tà Vy... tôi đã hiểu rồi, đây chính là nơi bạn trốn tránh ý chí vô thượng."
  },
  AvgDialog_60342_Content_25 = {
    Text = "Đã xảy ra nhiều việc ở Misaque, tôi tìm đến bạn là để…"
  },
  AvgDialog_60342_Content_26 = {
    Text = "Họa kiếp sắp đến, Alistair đã thông báo cho bạn mọi thứ. Tifreye Sod và Marukote đã giao phó toàn bộ sức mạnh cho bạn."
  },
  AvgDialog_60342_Content_27 = {
    Text = "Bạn có biết mọi chuyện xảy ra bên ngoài?"
  },
  AvgDialog_60342_Content_28 = {
    Text = "Không gian này luôn hiện diện tất cả về quá khứ, hiện tại và tương lai."
  },
  AvgDialog_60342_Content_29 = {
    Text = "Thể chất trí tuệ, hiểu biết vô biên."
  },
  AvgDialog_60342_Content_3 = {
    Text = "Các thành viên tuần tra xung quanh của hội nghị thẩm tra đều xuất hiện các dấu hiệu tan rã ở mức độ khác nhau."
  },
  AvgDialog_60342_Content_30 = {
    Text = "Để không gây ra thảm họa cuối cùng, tôi không thể can thiệp trực tiếp vào thế giới của bạn. Vì vậy, tôi đã dẫn bạn đến đây gặp mặt."
  },
  AvgDialog_60342_Content_31 = {
    Text = "Tôi sẽ giúp Misaque. Tôi sẽ giúp thế giới bạn."
  },
  AvgDialog_60342_Content_32 = {
    Text = "Thật tuyệt! Vậy bây giờ…"
  },
  AvgDialog_60342_Content_33 = {
    Text = "Mùa xuân của Akutê, tôi đã nhìn thấy bạn rồi. Trên người bạn có thứ gì đó mà tôi không thể nhìn rõ."
  },
  AvgDialog_60342_Content_34 = {
    Text = "Tôi tính toán tại đây. Trong vô số tương lai, tôi đã nhìn thấy con đường đúng đắn… Bây giờ, tôi đã nhìn rõ bạn."
  },
  AvgDialog_60342_Content_35 = {
    Text = "Cô ấy nhẹ nhàng mở mắt, đôi mắt lạnh lùng vì sự hiểu biết sâu sắc nhìn về phía bạn."
  },
  AvgDialog_60342_Content_36 = {
    Text = "Chất chảy bên cạnh đột nhiên ngừng lại, bạn không có chút chuẩn bị nào, cảm giác áp bức mạnh mẽ như một thực thể bao quanh bạn, khiến bạn không thể thở."
  },
  AvgDialog_60342_Content_37 = {
    Text = "Bạn đang… nói gì…"
  },
  AvgDialog_60342_Content_38 = {
    Text = "Trong tất cả các tính toán, bạn đều mắc lỗi."
  },
  AvgDialog_60342_Content_39 = {
    Text = "Để bảo vệ Misaque, để duy trì sự tồn tại của thế giới này, tôi sẽ ở đây, khắc phục sai lầm này."
  },
  AvgDialog_60342_Content_4 = {
    Text = "Càng gần Tà Vy, sự xâm thực do dung hợp càng nghiêm trọng. Trước khi nghi lễ chuẩn bị xong, Yu Li-ét sẽ không dám đến gần nơi này."
  },
  AvgDialog_60342_Content_40 = {Text = "!!!"},
  AvgDialog_60342_Content_5 = {
    Text = "Trước khi cô ấy xuất hiện, hãy nhanh chóng hoàn thành việc thu hồi quyền hạn."
  },
  AvgDialog_60342_Content_6 = {
    Text = "Bạn nhìn vào bóng dáng mờ ảo trước mắt."
  },
  AvgDialog_60342_Content_7 = {
    Text = "Những chiếc lông trắng sáng nhẹ nhàng rơi xuống, tan biến vào không trung. Trong đôi cánh khổng lồ bao bọc, lộ ra một gương mặt đang ngủ say."
  },
  AvgDialog_60342_Content_8 = {
    Text = "Ánh sáng và bóng tối đan xen, dù bạn cố gắng thế nào đi nữa cũng không thể nhìn rõ khuôn mặt của cô ấy, dường như khuôn mặt ấy không tồn tại trong thế giới của bạn."
  },
  AvgDialog_60342_Content_9 = {
    Text = "Va chạm với Tà Vy"
  },
  AvgDialog_60343_Content_1 = {
    Text = "Khá tốt, Người Giữ Gìn {Male=ngài,Female=cô}."
  },
  AvgDialog_60343_Content_2 = {
    Text = "Vừa mới hấp thụ quyền lực của dục vọng, mà vẫn có thể trụ được đến tận bây giờ…… là ta đã xem nhẹ ngươi."
  },
  AvgDialog_60343_Content_3 = {
    Text = "N đứng dậy từ hàng ghế khán giả, nhẹ nhàng kéo vành mũ, và gật đầu chào bạn trên sân khấu một cách lịch sự."
  },
  AvgDialog_60343_Content_4 = {
    Text = "Vậy thì, tiếp theo sẽ là màn đối đầu của chúng ta."
  },
  AvgDialog_60343_Content_5 = {
    Text = "Kẻ phản diện cuối cùng đầy mưu mô và quyến rũ, sắp xuất hiện ——"
  },
  AvgDialog_60344_Content_1 = {
    Text = "Học sinh tốt, học sinh xấu"
  },
  AvgDialog_60344_Content_10 = {
    Text = "Ramona, đã gây rắc rối cho các người. Nếu không bị thương, có lẽ tôi còn có thể giúp bạn chia sẻ một chút .."
  },
  AvgDialog_60344_Content_100 = {
    Text = "Anh ấy đứng dậy, mỉm cười âu yếm vuốt ve con mèo không lông trên vai."
  },
  AvgDialog_60344_Content_101 = {
    Text = "Con mèo ngẩng đầu lên, đôi mắt vô vị và thờ ơ quét qua những con người xung quanh, coi như một câu trả lời."
  },
  AvgDialog_60344_Content_11 = {
    Text = "Không cần phải nói như vậy, Thầy/Cô Hiệu trưởng. \nNgười Misaque không bao giờ coi người bị thương là gánh nặng."
  },
  AvgDialog_60344_Content_12 = {
    Text = "Đợi đưa các bạn vào tòa nhà Khoa Sức sống, chúng tôi có thể……"
  },
  AvgDialog_60344_Content_13 = {
    Text = "Có cần tôi tiễn các cô một đoạn không, cô Ramona?"
  },
  AvgDialog_60344_Content_14 = {Text = "!!!"},
  AvgDialog_60344_Content_15 = {
    Text = "Cẩn thận!"
  },
  AvgDialog_60344_Content_16 = {
    Text = "Ramona nhanh chóng giơ kiếm chắn ngang trước người."
  },
  AvgDialog_60344_Content_17 = {
    Text = "Ở sau lưng cô, Sylva cau mày lại, bảo vệ Khổ Lệ Đặc đang yếu đuối."
  },
  AvgDialog_60344_Content_18 = {
    Text = "Một tiếng bước chân gấp gáp vang lên, dường như đã mai phục ở đây trong một thời gian dài."
  },
  AvgDialog_60344_Content_19 = {
    Text = "Hai đầu con hẻm hẹp, điệp viên trong đồng phục của hội nghị thẩm tra đứng chen chúc chặn đường họ."
  },
  AvgDialog_60344_Content_2 = {
    Text = "Dãy hành lang dài hẹp không thấy bóng người nào. Một tiếng thở nặng nề và tiếng bước chân vang lên, vọng lại trong hành lang."
  },
  AvgDialog_60344_Content_20 = {
    Text = "Người đàn ông một mắt vừa bước tới trước đám đông, vừa nhẹ nhàng trêu đùa con mèo kỳ dị trên vai – một con mèo không lông bị khâu ghép hai đầu."
  },
  AvgDialog_60344_Content_21 = {
    Text = "Phải…… là ngươi……"
  },
  AvgDialog_60344_Content_22 = {
    Text = "Thấy khuôn mặt xuất hiện trước mắt, cơ thể của Khổ Lệ Đặc lập tức cứng đờ."
  },
  AvgDialog_60344_Content_23 = {
    Text = "Herbert... tên khốn kiếp này.."
  },
  AvgDialog_60344_Content_24 = {
    Text = "Thầy Crowley đã đối xử với cậu như con cái của mình, vậy mà cậu lại giết ông ấy, cướp đoạt thành quả nghiên cứu của ông ấy… Đến giờ, cậu vẫn còn dám mặt dày mày quay lại đây…"
  },
  AvgDialog_60344_Content_25 = {
    Text = "Học sinh Khổ Lệ Đặc… à không, phải gọi là Giám đốc Học viện Kherat."
  },
  AvgDialog_60344_Content_26 = {
    Text = "Sau khi tôi rời đi, vị trí hiệu trưởng chắc chắn thuộc về bạn."
  },
  AvgDialog_60344_Content_27 = {
    Text = "Tôi rất muốn cùng bạn ôn lại những kỷ niệm đẹp thời học sinh, nhưng hôm nay tôi đến đây còn có việc quan trọng khác cần làm."
  },
  AvgDialog_60344_Content_28 = {
    Text = "Ánh mắt anh hướng về phía Ramona."
  },
  AvgDialog_60344_Content_29 = {
    Text = "Lâu không gặp, thật là nhớ nhung, cô Ramona."
  },
  AvgDialog_60344_Content_3 = {
    Text = "Hô… Giám đốc Học viện Kherat, xin hãy cố gắng thêm một chút, chúng ta sắp đến rồi."
  },
  AvgDialog_60344_Content_30 = {
    Text = "Nhưng chỉ gặp vài lần trong khoảng thời gian này, không cần quá thân mật."
  },
  AvgDialog_60344_Content_31 = {
    Text = "Đoạn thời gian này? Không, không."
  },
  AvgDialog_60344_Content_32 = {
    Text = "Herbert ngẩng mắt, ánh mắt của anh ta vượt qua Khổ Lệ Đặc, vượt qua Ramona, cuối cùng rơi vào hư không tối tăm, như thể đang nhìn vào một nơi xa xôi không thể chạm tới."
  },
  AvgDialog_60344_Content_33 = {
    Text = "Tôi vẫn còn nhớ lần đầu tiên gặp bạn, có lẽ là trong hành lang này."
  },
  AvgDialog_60344_Content_34 = {
    Text = "Lúc đó bạn chỉ… lớn đến vậy thôi…"
  },
  AvgDialog_60344_Content_35 = {
    Text = "Herbert đưa hai tay ra, làm động tác mô phỏng chiều dài của một con mèo không lông."
  },
  AvgDialog_60344_Content_36 = {
    Text = "Bạn là... có ý gì vậy?"
  },
  AvgDialog_60344_Content_37 = {
    Text = "Con đẻ của tôi. Đứa trẻ của tôi."
  },
  AvgDialog_60344_Content_38 = {
    Text = "Hiro là sản phẩm thất bại, cặp song sinh yếu ớt kia cũng không đủ sức gánh vác sứ mệnh vĩ đại. \nTrong sự hợp tác giữa tôi và Hội Giáo đèn lồng, bạn chính là kết tinh hoàn hảo nhất."
  },
  AvgDialog_60344_Content_39 = {
    Text = "Tôi không hiểu.."
  },
  AvgDialog_60344_Content_4 = {
    Text = "Ramona à, hãy cẩn thận với vết thương…"
  },
  AvgDialog_60344_Content_40 = {
    Text = "Bạn còn chưa hiểu sao, Ramona?"
  },
  AvgDialog_60344_Content_41 = {
    Text = "Những người mà bạn quan tâm, hoảng sợ, bị thương, đối mặt với nguy cơ mất kiểm soát và cái chết… Tất cả những thảm họa mà Misaque phải chịu đựng, đều là vì bạn."
  },
  AvgDialog_60344_Content_42 = {
    Text = "Bạn…… nói gì?"
  },
  AvgDialog_60344_Content_43 = {
    Text = "Nhìn thanh kiếm rung động và phát ra tiếng vo ve trong tay Ramona, Herbert mỉm cười rồi bước hai bước về phía trước."
  },
  AvgDialog_60344_Content_44 = {
    Text = "Nhiều năm trước, tên trộm Dexter đã giật bạn đi từ chúng tôi."
  },
  AvgDialog_60344_Content_45 = {
    Text = "Ngày đó đến muộn hơn nhiều, nhưng không sao cả —— nó đến đúng lúc."
  },
  AvgDialog_60344_Content_46 = {
    Text = "Bạn là bảo vật song sinh, là sáng tạo hoàn hảo của đèn dẫn đường."
  },
  AvgDialog_60344_Content_47 = {
    Text = "Chúng tôi đến đây lần này chính là để tìm lại người."
  },
  AvgDialog_60344_Content_48 = {
    Text = "Vậy thì, hãy đi với tôi, Ramona."
  },
  AvgDialog_60344_Content_49 = {
    Text = "Tôi đảm bảo với bạn, miễn là bạn yên lặng đi cùng tôi, mọi sự quấy rối đối với Misaque sẽ hoàn toàn chấm dứt."
  },
  AvgDialog_60344_Content_5 = {
    Text = "Cô lấy khăn tay ra, cẩn thận lau sạch máu trên cánh tay của Ramona."
  },
  AvgDialog_60344_Content_50 = {
    Text = "Ramona, bạn…"
  },
  AvgDialog_60344_Content_51 = {
    Text = "Tôi có phải là người ngu ngốc đến vậy trong mắt anh, Héc-bớt?"
  },
  AvgDialog_60344_Content_52 = {
    Text = "Đây là Misaque. Bất kể mục đích của các người là gì, chúng tôi nhất định sẽ không để các người đạt được mục đích đâu."
  },
  AvgDialog_60344_Content_53 = {
    Text = "Thấy thanh kiếm mảnh của Ramona được nâng lên, Herbert nhẹ nhàng lay động ngón tay."
  },
  AvgDialog_60344_Content_54 = {
    Text = "Bạn đương nhiên là một người thông minh, Ramona."
  },
  AvgDialog_60344_Content_55 = {
    Text = "Bạn cần hộ tống hai phụ nữ thiếu khả năng tự bảo vệ, vì vậy đã chọn con đường ít người biết đến này."
  },
  AvgDialog_60344_Content_56 = {
    Text = "Tôi hoàn toàn tin tưởng vào khả năng đột phá của bạn. Nếu chỉ đến đây một mình, tôi không chắc có thể ngăn bạn lại."
  },
  AvgDialog_60344_Content_57 = {
    Text = "Tuy nhiên, hãy nhìn lại hai vị thầy cô kính yêu của em, Giám đốc Học viện Kherat và Cô giáo Sylviya, bạn học Ramona."
  },
  AvgDialog_60344_Content_58 = {
    Text = "Ramona nhìn xung quanh những điệp viên của hội nghị thẩm tra với ánh mắt đầy đe dọa, thanh kiếm trong tay cô không nhúc nhích trước ngực."
  },
  AvgDialog_60344_Content_59 = {
    Text = "An toàn của Misaque quan trọng hơn hết. Hãy làm điều đúng đắn, Ramona."
  },
  AvgDialog_60344_Content_6 = {
    Text = "À……xin lỗi."
  },
  AvgDialog_60344_Content_60 = {
    Text = "Lời của Khổ Lệ Đặc thì thầm vào tai Ramona. Cô ấy khựng lại, không gật đầu."
  },
  AvgDialog_60344_Content_61 = {
    Text = "Một lát sau, cô ngẩng đầu lên, nhìn về phía Herbert."
  },
  AvgDialog_60344_Content_62 = {
    Text = "Tôi hứa với bạn…"
  },
  AvgDialog_60344_Content_63 = {Text = "Ramona!"},
  AvgDialog_60344_Content_64 = {
    Text = "Tuy nhiên, tôi có một điều kiện."
  },
  AvgDialog_60344_Content_65 = {
    Text = "Xin mời nói."
  },
  AvgDialog_60344_Content_66 = {
    Text = "Hãy để người của anh rút ra ngoài đường dẫn, đợi Giám đốc Khổ Lệ Đặc và cô Sylphie đi xa, tôi sẽ đi cùng anh."
  },
  AvgDialog_60344_Content_67 = {
    Text = "À, tất nhiên, không có vấn đề gì ——"
  },
  AvgDialog_60344_Content_68 = {
    Text = "Anh ta vẫy tay. Theo lời chỉ dẫn của anh ta, các điệp viên của hội nghị thẩm tra nhường một con đường."
  },
  AvgDialog_60344_Content_69 = {
    Text = "Ramona, mục đích của họ là đưa bạn đi, bạn không thể đi với họ!"
  },
  AvgDialog_60344_Content_7 = {
    Text = "Vừa rồi khi chiến đấu với những người trong hội nghị thẩm tra, tôi đã bị phân tâm một lúc…"
  },
  AvgDialog_60344_Content_70 = {
    Text = "Hãy yên tâm, Giám đốc Kherat, tôi rất quan trọng với họ, họ sẽ không dám làm gì tôi đâu."
  },
  AvgDialog_60344_Content_71 = {
    Text = "Nhưng mà……"
  },
  AvgDialog_60344_Content_72 = {
    Text = "Giám đốc Học viện Kherat, chúng ta đi thôi."
  },
  AvgDialog_60344_Content_73 = {
    Text = "Ramona nói đúng, Herbert sẽ không làm hại cô ấy."
  },
  AvgDialog_60344_Content_74 = {
    Text = "Hãy tin tưởng cô ấy."
  },
  AvgDialog_60344_Content_75 = {
    Text = "Từ ánh mắt vui vẻ của cô ấy, Khổ Lệ Đặc hiểu được ý định của cô ấy. Cô khẽ gật đầu."
  },
  AvgDialog_60344_Content_76 = {
    Text = "Các điệp viên của hội nghị thẩm tra tách ra hai bên, đội hình ban đầu hoàn chỉnh nay trở nên rối loạn. Ở cả hai đầu vòng vây, xuất hiện một lỗ hổng rõ ràng."
  },
  AvgDialog_60344_Content_77 = {
    Text = "Các điệp viên đang di chuyển dần chuyển sự chú ý sang việc thay đổi đội hình, mà không còn để ý đến từng cử chỉ của Ramona."
  },
  AvgDialog_60344_Content_78 = {Text = "À!"},
  AvgDialog_60344_Content_79 = {
    Text = "Hai tiếng hét thảm thiết của các điệp viên đã thu hút ánh mắt của mọi người."
  },
  AvgDialog_60344_Content_8 = {
    Text = "Sự hỗn loạn của hồ đen vẫn không thể tránh khỏi ảnh hưởng đến bạn, phải không?"
  },
  AvgDialog_60344_Content_80 = {
    Text = "Khi sự đề phòng của hội nghị thẩm tra bắt đầu lỏng lẻo, Ramona đã dùng kiếm giải quyết một cách dứt khoát hai điệp viên đang kiểm soát cô."
  },
  AvgDialog_60344_Content_81 = {
    Text = "(Xin lỗi, Giám đốc Học viện Khổ Lệ Đặc, Giáo sư Sylvia. Tôi không thể để Misaque rơi vào nguy hiểm.)"
  },
  AvgDialog_60344_Content_82 = {
    Text = "(Tôi sẽ mang các thân thể được đánh thức khác đến để cứu các bạn. Sẽ rất nhanh!)"
  },
  AvgDialog_60344_Content_83 = {
    Text = "Ramona không có thời gian để nói những lời này. Đây là cơ hội duy nhất, qua khe hở bất ngờ này, cô ấy nhanh chóng thoát thân."
  },
  AvgDialog_60344_Content_84 = {
    Text = "Một vài các điệp viên phản ứng lại được, nhưng họ hoàn toàn không thể chặn được thanh kiếm của Ramona. Khổ Lệ Đặc và Sylva nhìn nhau, trên mặt hiện lên vẻ vui mừng."
  },
  AvgDialog_60344_Content_85 = {
    Text = "Herbert thấy vẻ mặt của họ từ khóe mắt, cười, đưa tay lên vẫy nhẹ."
  },
  AvgDialog_60344_Content_86 = {
    Text = "Chúng tôi đang chờ đón ngài, Đấng chí tôn…"
  },
  AvgDialog_60344_Content_87 = {
    Text = "Để chào mừng sự giáng sinh của ngài, xin ban phúc lành cho chúng tôi và trừng phạt những kẻ bất kính.."
  },
  AvgDialog_60344_Content_88 = {
    Text = "Một chuỗi âm tiết kỳ quái từ từ bay ra từ đám đông, rơi vào tai Ramona trong khoảnh khắc đó. Nội tạng cô như bị siết chặt bởi một sợi dây vô hình, cảm giác căng tức ập đến, cướp đi toàn bộ sức lực của cô."
  },
  AvgDialog_60344_Content_89 = {
    Text = "Cô ấy không hề phòng bị, đột ngột ngã xuống đất, thanh kiếm mảnh trong tay lăn sang một bên, sau tiếng kim loại nhỏ trượt đi thì dừng lại ở vị trí không xa. \nRamona đưa tay lên, nhưng không thể chạm tới."
  },
  AvgDialog_60344_Content_9 = {
    Text = "Một chút thôi."
  },
  AvgDialog_60344_Content_90 = {
    Text = "Đây… Đây là…"
  },
  AvgDialog_60344_Content_91 = {
    Text = "Dù là tạo vật từ đèn dầu rẻ nhất, trong cơ thể vẫn sẽ để lại dấu ấn của đèn dầu. Huống chi là ngươi."
  },
  AvgDialog_60344_Content_92 = {
    Text = "Bạn cần tìm cơ hội để trốn thoát, tôi cũng đang chờ Hội Giáo đèn lồng kích hoạt pháp ấn trong bạn, điều này cần thời gian."
  },
  AvgDialog_60344_Content_93 = {
    Text = "Nếu sử dụng bạo lực, làm tổn thương bạn, hoặc để bạn trốn thoát, thì điều đó sẽ không hay lắm."
  },
  AvgDialog_60344_Content_94 = {
    Text = "Bạn… đã biết từ lâu rằng tôi sẽ bỏ trốn…"
  },
  AvgDialog_60344_Content_95 = {
    Text = "Tôi chưa bao giờ nghĩ rằng bạn sẽ đầu hàng dễ dàng. Bạn không phải là người kém thông minh như vậy."
  },
  AvgDialog_60344_Content_96 = {
    Text = "Herbert đi đến bên Ramona, nhặt thanh kiếm mảnh lên và nghịch nó trong tay, thở dài đầy tiếc nuối."
  },
  AvgDialog_60344_Content_97 = {
    Text = "Nếu từ đầu bạn đã chọn kháng cự, có lẽ chúng tôi thực sự không thể ngăn cản bạn. Nhưng bạn muốn mọi thứ, nhiều thông tin hơn, cái giá nhỏ hơn……"
  },
  AvgDialog_60344_Content_98 = {
    Text = "Tôi hiểu bạn, Ramona. Bạn quá cầu toàn. Ngay cả trong hoàn cảnh tuyệt vọng này, bạn cũng muốn giúp Misaque nhiều nhất có thể, giúp Người Giữ Gìn."
  },
  AvgDialog_60344_Content_99 = {
    Text = "Nhưng, khi thông tin không đối xứng, càng theo đuổi sự hoàn hảo, thì càng dễ mắc sai lầm. Bạn có nghĩ vậy không?"
  },
  AvgDialog_60346_Content_1 = {
    Text = "Con đường tồn vong"
  },
  AvgDialog_60346_Content_10 = {
    Text = "Thái Di Sơ…"
  },
  AvgDialog_60346_Content_11 = {
    Text = "Tôi ở đây."
  },
  AvgDialog_60346_Content_12 = {
    Text = "Thái Di Sơ, bạn sẽ đến gặp tôi chứ?"
  },
  AvgDialog_60346_Content_13 = {
    Text = "Sẽ phải trả giá"
  },
  AvgDialog_60346_Content_14 = {
    Text = "Tôi sẵn sàng chịu đựng!"
  },
  AvgDialog_60346_Content_15 = {Text = "Ừ——"},
  AvgDialog_60346_Content_16 = {
    Text = "Cơn đau dữ dội khiến bạn quỳ gục xuống đất. Một hạt giống phát sáng nhẹ nhàng từ bụng bạn chui ra, trôi nổi lên trên hồ đen."
  },
  AvgDialog_60346_Content_17 = {
    Text = "Hạt giống rơi vào hồ đen, tạo nên một gợn sóng, khi gợn sóng lan ra, cảnh tượng trong hồ đen rung động biến đổi. Một đụn cát quen thuộc hiện ra trước mắt bạn."
  },
  AvgDialog_60346_Content_18 = {
    Text = "Cát vàng mịn màng bị một làn gió trong lành và ngọt dịu cuốn lên, tụ lại trước mặt bạn."
  },
  AvgDialog_60346_Content_19 = {
    Text = "Rất nhanh, với hạt giống làm lõi, cát vàng hóa thành xương thịt, một sinh vật hình người xuất hiện trước mặt bạn."
  },
  AvgDialog_60346_Content_2 = {
    Text = "Ánh sáng của phòng nghiên cứu dưới đất càng lúc càng xa bạn, dần trở thành một tia sáng yếu ớt như ánh sáng đom đóm."
  },
  AvgDialog_60346_Content_20 = {
    Text = "Thái Di Sơ……?"
  },
  AvgDialog_60346_Content_21 = {
    Text = "Từ khi cô ấy biến mất trong dòng sông thiêng liêng khi cây mẹ sụp đổ, không ai còn biết tung tích của cô ấy."
  },
  AvgDialog_60346_Content_22 = {
    Text = "Đây là…… hồ đen, đại thủy triều đen từ tâm trái đất trào lên……\nChỉ có cô ấy mới có thể bền bỉ đối mặt với bóng tối sâu thẳm và vĩnh cửu nơi đây."
  },
  AvgDialog_60346_Content_23 = {
    Text = "Thái Di Sơ bất ngờ đến gần, đôi môi căng mọng của cô, ánh mắt gợi cảm cùng nụ cười im lặng không khác gì Lemvahxi."
  },
  AvgDialog_60346_Content_24 = {
    Text = "Trả lời ta, trong khoảnh khắc này trước khi đến thế giới mới, Người Giữ Gìn, tại sao ngươi lại thức tỉnh ta ở đây?"
  },
  AvgDialog_60346_Content_25 = {
    Text = "Bạn kể lại lời dặn dò của Alistair."
  },
  AvgDialog_60346_Content_26 = {
    Text = "Khuôn mặt của Thái Di Sơ từ nghi hoặc, đến hoảng loạn, cuối cùng lại chuyển thành kinh hãi."
  },
  AvgDialog_60346_Content_27 = {
    Text = "Không… đây không phải là con đường khả thi"
  },
  AvgDialog_60346_Content_28 = {
    Text = "Ngài sẽ thức tỉnh, không ai có thể đánh bại Ngài…"
  },
  AvgDialog_60346_Content_29 = {
    Text = "Nhưng tôi đã quyết định."
  },
  AvgDialog_60346_Content_3 = {
    Text = "Hồ đen sôi sục dưới chân bạn, ánh sáng le lói của Tà Vy lay động ở phía xa, giống như màu trắng tinh khiết rơi vào biển sâu, nhanh chóng biến mất."
  },
  AvgDialog_60346_Content_30 = {
    Text = "Thái Di Sơ thở dài khẽ một tiếng."
  },
  AvgDialog_60346_Content_31 = {
    Text = "Xin hãy cho tôi mượn quyền năng của Thể Chất Ham Muốn."
  },
  AvgDialog_60346_Content_32 = {
    Text = "Bạn bước lên một bước, nhìn thẳng vào mắt của Thái Di Sơ."
  },
  AvgDialog_60346_Content_33 = {
    Text = "Ài, thằng nhóc…"
  },
  AvgDialog_60346_Content_34 = {
    Text = "Tôi đã trao quyền hạn của mình cho bạn từ lâu rồi. \nMọi thứ của tôi đều hoàn toàn cởi mở với bạn."
  },
  AvgDialog_60346_Content_35 = {
    Text = "Hạt giống mà ta đã cấy vào cơ thể ngươi…… uy quyền của ta dựa vào nó."
  },
  AvgDialog_60346_Content_36 = {
    Text = "Chỉ là, nó đã bị bạn tách rời một cách tàn nhẫn. \nNó đang sợ hãi, đang tức giận……"
  },
  AvgDialog_60346_Content_37 = {
    Text = "Để trồng lại nó, phải làm cho nó bình tĩnh trước…"
  },
  AvgDialog_60346_Content_4 = {
    Text = "Khi bạn đi sâu hơn, sự xao động của hồ đen cũng trở nên rõ rệt hơn."
  },
  AvgDialog_60346_Content_5 = {
    Text = "Nếu bây giờ đi tìm Tà Vy chắc chắn sẽ khiến Yu Li-ét chú ý, vì vậy chỉ có thể để cô ấy lại sau cùng."
  },
  AvgDialog_60346_Content_6 = {
    Text = "Hai chất thể còn lại, nên đi đâu để tìm nhỉ…"
  },
  AvgDialog_60346_Content_7 = {
    Text = "Thầy của bạn biết rất nhiều điều. Điều này ông ấy không nói với bạn, có lẽ, bạn mới là người cần biết hơn cả."
  },
  AvgDialog_60346_Content_8 = {
    Text = "Hồi tưởng về họ, gọi tên họ, biết đâu họ sẽ đáp lại bạn."
  },
  AvgDialog_60346_Content_9 = {
    Text = "Trong tâm trí bạn hiện lên một khuôn mặt tươi cười, cô ấy từng bước qua cát đến bên bạn vào thời khắc quyết định khi bạn đối mặt với di cốt cây thánh, giúp bạn vượt qua mọi trở ngại."
  },
  AvgDialog_60347_Content_1 = {
    Text = "Phong cách chuyển biến kiểu Dexter"
  },
  AvgDialog_60347_Content_10 = {
    Text = "Bạn cẩn thận cảm nhận. Lực lượng mạnh mẽ của Thái Di Sơ tàn phá bên trong thân thể bạn, bạn hoàn toàn không biết cách kiểm soát nó, thậm chí việc hành động bình thường cũng bị ảnh hưởng nghiêm trọng."
  },
  AvgDialog_60347_Content_11 = {
    Text = "Không biết tình trạng này sẽ kéo dài bao lâu nữa. Ramona vẫn còn bị mắc kẹt trong hồ đen, tôi phải tăng tốc…"
  },
  AvgDialog_60347_Content_12 = {
    Text = "Thời tiết lạnh như vậy, nằm trong hồ đen, có thể sẽ bị ốm."
  },
  AvgDialog_60347_Content_13 = {
    Text = "Giáo sư Dexter?"
  },
  AvgDialog_60347_Content_14 = {
    Text = "Giáo sư Dexter?!"
  },
  AvgDialog_60347_Content_15 = {
    Text = "Giọng nói quen thuộc, cùng bóng dáng mà tôi đã từng biết."
  },
  AvgDialog_60347_Content_16 = {
    Text = "Đôi tay được chăm chút tỉ mỉ chống gậy, tiến đến trước mặt bạn."
  },
  AvgDialog_60347_Content_17 = {
    Text = "Giáo sư Dexter, hiện tại hồ đen rất nguy hiểm. Xin hãy rời khỏi đây trước."
  },
  AvgDialog_60347_Content_18 = {
    Text = "Xin đừng lo lắng cho Ramona, tôi sẽ sớm đi cứu cô ấy…"
  },
  AvgDialog_60347_Content_19 = {
    Text = "Bạn vẫn luôn quan tâm đến Ramona như vậy, Người Giữ Gìn."
  },
  AvgDialog_60347_Content_2 = {
    Text = "Sa mạc……biến mất……"
  },
  AvgDialog_60347_Content_20 = {
    Text = "Xin cảm ơn sự quan tâm của bạn, tôi vừa mới gặp Ramona."
  },
  AvgDialog_60347_Content_21 = {
    Text = "Bạn đã……?"
  },
  AvgDialog_60347_Content_22 = {
    Text = "Đúng vậy. Cô ấy hiện đang rất... thoải mái."
  },
  AvgDialog_60347_Content_23 = {
    Text = "Cô ấy đã lâu không ngủ ngon như vậy. Chắc là cô ấy đang rất cần một giấc ngủ như thế này."
  },
  AvgDialog_60347_Content_24 = {
    Text = "Cô ấy……bây giờ rất nguy hiểm……tại sao ngài không……"
  },
  AvgDialog_60347_Content_25 = {
    Text = "Cố gắng cứu cô ấy? Đúng vậy, tại sao không chứ… Dexter yêu con gái mình đến vậy, lẽ ra anh ta phải tìm cách cứu cô ấy mới đúng."
  },
  AvgDialog_60347_Content_26 = {
    Text = "Dù phải hy sinh mạng sống của mình, vẫn sẵn lòng…"
  },
  AvgDialog_60347_Content_27 = {
    Text = "Dexter ngẩng đầu lên, thở dài nhẹ nhàng, như đang hồi tưởng điều gì đó."
  },
  AvgDialog_60347_Content_28 = {
    Text = "Đây cũng là một lựa chọn, một diễn biến của câu chuyện."
  },
  AvgDialog_60347_Content_29 = {
    Text = "Nếu thật sự cứu được cô ấy ra, câu chuyện này há chẳng thiếu đi một vở kịch hay để xem?"
