  },
  AvgDialog_60347_Content_31 = {
    Text = "Bạn thấy, anh ta nở một nụ cười hoàn hảo, lạnh lùng và không chút cảm xúc."
  },
  AvgDialog_60347_Content_32 = {
    Text = "Giáo sư Dexter tuyệt đối không bao giờ nói những lời như vậy…… rốt cuộc anh là ai!?"
  },
  AvgDialog_60347_Content_33 = {
    Text = "Anh ấy đến trước mặt bạn, đôi mắt quen thuộc mang theo nụ cười mang vẻ xa cách nhìn bạn."
  },
  AvgDialog_60347_Content_34 = {
    Text = "Một làn khói đen từ người hắn bốc lên, từ từ bao phủ hắn."
