  AvgDialog_60347_Content_35 = {
    Text = "Đúng vậy, tôi là ai nhỉ.."
  },
  AvgDialog_60347_Content_36 = {
    Text = "Cổ đông tiêu xài hoang phí. Người cha yêu thương con gái. Chàng trai phong lưu nổi tiếng. Giáo sư Misaque nổi tiếng và được yêu mến."
  },
  AvgDialog_60347_Content_37 = {
    Text = "Một diễn viên tận tụy. Suốt hai mươi năm đảm nhận cùng một vai diễn, vì sự chuyển biến tuyệt vời của câu chuyện, chưa hề lơi là."
  },
  AvgDialog_60347_Content_38 = {
    Text = "Bây giờ.."
  },
  AvgDialog_60347_Content_39 = {
