  },
  AvgDialog_60347_Content_4 = {
    Text = "Xin lỗi vì làm phiền, nhưng đây không phải là lúc để chìm đắm trong những cảm xúc này."
  },
  AvgDialog_60347_Content_40 = {
    Text = "Sương mù đen bao quanh, giống như sự tán dương."
  },
  AvgDialog_60347_Content_41 = {
    Text = "Xuất hiện trước mặt bạn là một khuôn mặt mà bạn từng thấy, mang đến cho bạn vô số cơn ác mộng!"
  },
  AvgDialog_60347_Content_42 = {
    Text = "Trên khuôn mặt không có ngũ quan, cái miệng mang theo nụ cười kia mở rộng hết cỡ, tham lam tận hưởng sự bàng hoàng và khiếp đảm của bạn."
