  AvgDialog_60347_Content_48 = {
    Text = "Bạn có ý gì…… chúng ta làm sao có thể…… hay là?!"
  },
  AvgDialog_60347_Content_49 = {
    Text = "Bạn nhớ lời của N. Những năm qua, anh ấy vẫn luôn đóng vai diễn đó…"
  },
  AvgDialog_60347_Content_5 = {
    Text = "Tôi và cô ấy không phải.."
  },
  AvgDialog_60347_Content_50 = {
    Text = "Còng kinh co lại mạnh mẽ. Bạn đột ngột ngẩng đầu lên, nhìn vào khuôn mặt vô cảm của N."
