  AvgDialog_60347_Content_51 = {
    Text = "Xuất sắc, Người Giữ Gìn. Chính là biểu cảm này!"
  },
  AvgDialog_60347_Content_52 = {
    Text = "Đừng cử động, giữ nguyên. Đúng rồi, chính là như vậy… để tôi nhớ kỹ dáng vẻ của bạn bây giờ…"
  },
  AvgDialog_60347_Content_53 = {
    Text = "Thật đáng tiếc, khi Ramona biết được chuyện này, cô ấy vẫn chưa tỉnh lại, tôi chỉ thấy những giọt nước mắt của cô ấy."
  },
  AvgDialog_60347_Content_54 = {
    Text = "Tôi nghĩ, tâm trạng trong lòng cô ấy lúc đó chắc chắn còn thú vị hơn bạn."
  },
  AvgDialog_60347_Content_55 = {
