  AvgDialog_60347_Content_59 = {
    Text = "Một diễn viên xuất sắc cần thể hiện và trở thành."
  },
  AvgDialog_60347_Content_6 = {
    Text = "Không cần giải thích. Dù bằng cách nào, việc thu hồi quyền hạn là một điều tuyệt vời."
  },
  AvgDialog_60347_Content_60 = {
    Text = "Anh ta ghé sát vào tai bạn, thì thầm nhỏ nhẹ, như thể muốn chia sẻ với bạn một bí mật lớn lao ——"
  },
  AvgDialog_60347_Content_61 = {
    Text = "Dexter đã chết từ lâu, chết vào ngày cứu Ramona."
  },
  AvgDialog_60347_Content_62 = {
    Text = "Những năm qua, bạn và Ramona, chắc hẳn đã sống cùng tôi rất vui vẻ đúng không?"
  },
  AvgDialog_60347_Content_63 = {
    Text = "Khuôn mặt của anh ta đối diện với bạn. Trên khuôn mặt trống rỗng đó, bạn dường như nhìn thấy rõ ràng những đường nét ngạo mạn và sắc bén trên khuôn mặt."
  },
  AvgDialog_60347_Content_64 = {
    Text = "Anh ta cúi người xuống và nhìn chăm chú, như thể muốn ghi nhớ từng biểu cảm, từng run rẩy ngoài tầm kiểm soát của bạn."
  },
  AvgDialog_60347_Content_65 = {
    Text = "Một chàng playboy phong lưu, một người cha đầy tình cảm, tôi vốn không quan tâm nhiều đến loại nhân vật như vậy."
  },
  AvgDialog_60347_Content_66 = {
    Text = "Tôi quan tâm, chỉ là cô ấy… \"con gái\" của tôi. Hai sáng tạo song sinh của Tà Vy, Ramona."
  },
  AvgDialog_60347_Content_67 = {
    Text = "N mỉm cười nhìn về phía trung tâm hồ đen, nơi Tà Vy đang ở."
  },
  AvgDialog_60347_Content_68 = {
    Text = "Bạn… bạn tại sao lại hại chết anh ấy…"
  },
  AvgDialog_60347_Content_69 = {
    Text = "Sự hiểu lầm của bạn thật đáng buồn, Người Giữ Gìn."
  },
  AvgDialog_60347_Content_7 = {
    Text = "Tôi… thôi, lười nói chuyện cái này với cậu. Chúng ta trước… s!…"
  },
  AvgDialog_60347_Content_70 = {
    Text = "Kế hoạch của cặp song sinh cầm đèn, làm sao một quý công tử chẳng biết gì ngoài ăn chơi có thể dễ dàng đối kháng được. Nhưng hắn lại có thể cứu được đứa bé gái ra ngoài."
  },
  AvgDialog_60347_Content_71 = {
    Text = "Khi nhìn thấy tôi, ánh mắt của anh ta giống như đã nhìn thấy vị cứu tinh…… Ha ha."
  },
  AvgDialog_60347_Content_72 = {
    Text = "N nhớ lại câu chuyện đó và mỉm cười đầy thích thú."
  },
  AvgDialog_60347_Content_73 = {
    Text = "Anh ta đã làm một cuộc giao dịch với tôi. Bạn có thể tin nổi không? Một người bình thường sắp chết, lại dám giao dịch với tôi…"
  },
  AvgDialog_60347_Content_74 = {
    Text = "Anh ấy đã cho tôi mọi thứ. Tài sản của anh ấy, địa vị của anh ấy, con gái của anh ấy……"
