  },
  AvgDialog_60347_Content_77 = {
    Text = "Kẻ phản bội trong nhóm Misaque… là bạn?"
  },
  AvgDialog_60347_Content_78 = {
    Text = "Nhìn vào đôi mắt đầy nghi hoặc, tức giận của bạn, An vô tư nhún vai."
  },
  AvgDialog_60347_Content_79 = {
    Text = "Là tôi, không phải tôi, có đáng để bận tâm không? Thật khó tin là đến bây giờ bạn vẫn còn tâm trạng để nghĩ về những điều này."
  },
  AvgDialog_60347_Content_8 = {
    Text = "Vừa định đứng dậy, bạn cảm nhận một cơn đau xé rách trong cơ thể khiến bạn rùng mình."
  },
  AvgDialog_60347_Content_80 = {
    Text = "Đóng vai Dexter, có thể ở gần Misaque, thực sự mang lại khá nhiều tiện lợi."
  },
  AvgDialog_60347_Content_81 = {
    Text = "Nơi này, giống như là công viên giải trí thú vị nhất thế giới."
  },
  AvgDialog_60347_Content_82 = {
    Text = "Xem biểu cảm của các người khi nhận ra bị tôi lừa gạt. Xem dáng vẻ tan vỡ của Tà Vy khi kế hoạch thất bại."
