  },
  AvgDialog_60347_Content_85 = {
    Text = "Anh ta nhìn bạn, liếm môi, giống như một đứa trẻ vô tội, đang nhìn vào một đồ chơi sắp bị phá hủy."
  },
  AvgDialog_60347_Content_86 = {
    Text = "Thái Di Sơ đã tặng hạt giống của cô ấy cho bạn, cô ấy lại tin rằng bạn có thể mang cô ấy sống sót… Ha, người phụ nữ điên thật."
  },
  AvgDialog_60347_Content_87 = {
    Text = "Thật đáng tiếc, cô ấy đã tin nhầm người. Quyền năng của dục vọng, tôi sẽ nắm lấy."
  },
  AvgDialog_60347_Content_88 = {
    Text = "Hãy để ta xem, khi hy vọng cháy bỏng bị tước mất, trên khuôn mặt ngươi sẽ hiện lên vẻ mặt như thế nào?"
