  AvgDialog_60348_Content_5 = {
    Text = "Chưa phải lúc."
  },
  AvgDialog_60348_Content_6 = {
    Text = "Yu Li-ét lần này đến Misaque, đã huy động toàn bộ sức mạnh. Những khả năng mà cô sở hữu, ngay cả tôi cũng không thể hoàn toàn nắm bắt được."
