  },
  AvgDialog_60348_Content_8 = {
    Text = "Nếu bạn bại trận, sân khấu này của Misaque sẽ không còn tồn tại."
  },
  AvgDialog_60348_Content_9 = {
    Text = "Bạn nói đúng, tôi không có cơ hội thứ hai."
  },
  AvgDialog_60349_Content_1 = {
    Text = "Khi ánh sáng của chìa khóa bạc tắt dần, N ngã xuống đất."
