  AvgDialog_60349_Content_12 = {
    Text = "Tuy nhiên, đồng thời là một người theo dõi tận tụy, nên quên đi câu chuyện đã qua và nghiêm túc mong đợi buổi biểu diễn tiếp theo."
  },
  AvgDialog_60349_Content_13 = {
    Text = "Ramona và Tà Vy, màn diễn hấp dẫn này sắp bắt đầu rồi!"
  },
  AvgDialog_60349_Content_14 = {
    Text = "Bạn có ba mươi giây để tuyên bố lời từ biệt của mình, Người Giữ Gìn {Male=ngài,Female=cô}."
  },
  AvgDialog_60349_Content_15 = {
    Text = "N vừa nói, vừa chỉnh sửa hình dáng của bông hồng trong tay, giống như đang chuẩn bị một món quà vĩnh biệt trong nghi lễ trang trọng."
  },
  AvgDialog_60349_Content_16 = {
    Text = "Tôi thu hồi quyền bính, là để cứu Misaque, cứu những người bên cạnh tôi… và mọi thứ trên thế giới này, cũng bao gồm cả bạn!"
  },
  AvgDialog_60349_Content_17 = {
    Text = "Hai mươi giây."
  },
  AvgDialog_60349_Content_18 = {
    Text = "N đưa mũi không tồn tại của mình đến gần bông hồng, hít một hơi sâu và thốt lên tiếng thở dài đầy thỏa mãn."
  },
  AvgDialog_60349_Content_19 = {
    Text = "Hai mươi năm… bạn và Misaque đã ở bên nhau hai mươi năm. Dù bạn có bỏ qua mọi người khác, còn Ramona thì sao?"
