  AvgDialog_60349_Content_26 = {Text = "Ba giây."},
  AvgDialog_60349_Content_27 = {
    Text = "Anh ta ngắt một cánh hoa hồng. Cánh hoa biến thành dao nhọn, kề sát cổ bạn."
  },
  AvgDialog_60349_Content_28 = {
    Text = "Tà Vy nói với tôi, Đấng chọn là đứng ngoài quan sát. Đấng không quan tâm đến sự sống, cũng không quan tâm đến cái chết. Ngoài việc thỏa mãn bản thân, Đấng không quan tâm đến bất cứ điều gì."
  },
  AvgDialog_60349_Content_29 = {
    Text = "Lưỡi dao cắt vào cổ họng của bạn. Bạn cảm nhận rõ ràng cơn đau. Bạn chợt mở mắt."
  },
  AvgDialog_60349_Content_3 = {
    Text = "N, tôi có điều muốn…"
  },
  AvgDialog_60349_Content_30 = {
    Text = "Nhạt nhẽo"
  },
  AvgDialog_60349_Content_31 = {
    Text = "Không thú vị!"
  },
  AvgDialog_60349_Content_32 = {Text = "Hừm?"},
  AvgDialog_60349_Content_33 = {
    Text = "Lựa chọn của bạn... thật sự rất nhạt nhẽo.."
  },
  AvgDialog_60349_Content_34 = {Text = "Ồ?"},
  AvgDialog_60349_Content_35 = {
    Text = "Lưỡi dao dừng lại ở cổ họng của bạn. N đang chờ đợi."
  },
  AvgDialog_60349_Content_36 = {
    Text = "Cuối cùng, thảm họa sẽ đến…… Trong thảm họa này, không ai có thể tránh được……"
  },
  AvgDialog_60349_Content_37 = {
    Text = "Còn nếu, có người có thể ngăn chặn thảm họa này thì sao?"
  },
  AvgDialog_60349_Content_38 = {
    Text = "Bạn…… nói gì?"
  },
  AvgDialog_60349_Content_39 = {
    Text = "Tôi có thể. Dù thảm họa này là gì, tôi sẽ đi ngăn chặn sự đến của Ngài!"
  },
  AvgDialog_60349_Content_4 = {Text = "!!!"},
  AvgDialog_60349_Content_40 = {
    Text = "Thành công, hoặc thất bại…… dù là cái nào, đối với bạn đều là câu chuyện thú vị nhất."
  },
  AvgDialog_60349_Content_41 = {
    Text = "Hehehe… bạn? hihihi!"
  },
  AvgDialog_60349_Content_42 = {
    Text = "N dường như đã nghe được một câu chuyện hài hước vô cùng. Ngài ấy ôm bụng và cười nghiêng ngả."
  },
  AvgDialog_60349_Content_43 = {
    Text = "Tiếng cười điên rồ vang lên liên tục trong sân khấu hồ đen rộng rãi và trống vắng."
  },
  AvgDialog_60349_Content_44 = {
    Text = "Bạn thực sự không biết mình đang nói về cái gì cả!"
  },
  AvgDialog_60349_Content_45 = {
    Text = "Tôi thực sự không biết. Nhưng điều này không ảnh hưởng đến tính chính xác của câu nói."
  },
  AvgDialog_60349_Content_46 = {
    Text = "N, thực ra bạn đã nghĩ đến từ lâu rồi. Bạn chưa bao giờ có ý định giết tôi."
  },
  AvgDialog_60349_Content_47 = {
    Text = "Hãy cho tôi ba mươi giây, chỉ là muốn nghe tôi nói câu này. Đúng không?"
  },
  AvgDialog_60349_Content_48 = {
    Text = "Sau một lúc lâu, N cuối cùng cũng ngừng cười. Người ấy hít sâu một hơi, nhìn bạn một cách nghiêm túc."
  },
  AvgDialog_60349_Content_49 = {
    Text = "Xin lỗi, mình không giữ được bình tĩnh…"
  },
  AvgDialog_60349_Content_5 = {
    Text = "Chưa kịp để bạn phản ứng, thân thể trên mặt đất đã tan thành sương đen rồi biến mất."
  },
  AvgDialog_60349_Content_50 = {
    Text = "Bạn nói đúng, Người Giữ Gìn. Hoàn toàn đúng. Trên đời này, không có niềm vui nào lớn hơn thế."
  },
  AvgDialog_60349_Content_51 = {
    Text = "Anh mỉm cười, đưa bông hồng đến tay bạn."
  },
  AvgDialog_60349_Content_52 = {
    Text = "Đây là...?"
  },
  AvgDialog_60349_Content_53 = {
    Text = "Bạn vừa hỏi, vừa vô thức chạm vào bông hồng."
  },
  AvgDialog_60349_Content_54 = {
    Text = "Vào khoảnh khắc chạm vào cánh hoa, vô số tiếng cười vang lên cùng một lúc trong tai bạn."
  },
  AvgDialog_60349_Content_55 = {
    Text = "Sự mạnh mẽ, thanh nhã, sắc bén, ảm đạm… đủ loại tiếng cười, tụ họp thành một đội quân hề hỗn loạn, rộn ràng trong tai bạn."
  },
  AvgDialog_60349_Content_56 = {
    Text = "Tâm trí bạn ngưng lại, đau như dao đâm vào dây thần kinh."
  },
  AvgDialog_60349_Content_57 = {
    Text = "Trong tiếng cười dữ dội, hỗn loạn, gần như điên rồ, lời nói của N vẫn truyền vào tâm trí bạn rõ ràng."
  },
  AvgDialog_60349_Content_58 = {
    Text = "Quyền năng của sự vui sướng, hãy tận hưởng đi."
  },
  AvgDialog_60349_Content_59 = {
    Text = "Tôi sẽ im lặng chờ đợi. Chờ màn trình diễn hoành tráng này bắt đầu, tôi nhất định sẽ trong hàng ghế khán giả, dành cho bạn những tràng pháo tay nồng nhiệt nhất."
  },
  AvgDialog_60349_Content_6 = {
    Text = "Kết thúc, cái chết bi tráng của anh hùng."
  },
  AvgDialog_60349_Content_7 = {
    Text = "Rầm——"
  },
  AvgDialog_60349_Content_8 = {
    Text = "Cú va chạm mạnh mẽ khiến thân thể bạn gần như rời rạc."
  },
  AvgDialog_60349_Content_9 = {
    Text = "Sự thương tích dọc đường, sức ép của Quyền trượng Dục vọng, cú sốc tinh thần từ hồ đen, tất cả khiến bạn không thể chịu đựng nổi nữa, đau đớn ngã quỵ xuống đất, không còn chút lực lượng nào để đứng dậy."
  },
  AvgDialog_60350_Content_1 = {
    Text = "Lực lượng của Thái Di Sơ dường như không có giới hạn. Áp lực ngày càng tăng khiến bạn cảm thấy nghẹt thở."
  },
  AvgDialog_60350_Content_10 = {
    Text = "Tôi không biết, Thái Di Sơ. Nhưng tôi biết tôi sẽ không từ bỏ."
  },
  AvgDialog_60350_Content_11 = {
    Text = "Bạn có muốn giao quyền lực cho tôi hay không? Đó là lựa chọn của bạn, tôi sẽ không ép buộc."
  },
  AvgDialog_60350_Content_12 = {
    Text = "Đây là hạt giống quý giá nhất của bạn, hãy tặng nó cho người có hy vọng lớn nhất để thoát khỏi nơi này…"
  },
  AvgDialog_60350_Content_13 = {
    Text = "Tôi sẽ không bao giờ từ bỏ nơi này. Dù thế nào đi nữa, tôi cũng sẽ đấu tranh đến cùng với những thứ muốn phá hủy nơi đây…"
  },
  AvgDialog_60350_Content_14 = {
    Text = "Nhưng…… tại sao?"
  },
  AvgDialog_60350_Content_15 = {
    Text = "Có điều gì quan trọng hơn việc tiếp tục sống?"
  },
  AvgDialog_60350_Content_16 = {
    Text = "Để tôi buông bỏ thế giới này, từ bỏ những người bên cạnh tôi, buông bỏ thân thể được đánh thức, từ bỏ bạn, tôi không thể làm được…"
  },
  AvgDialog_60350_Content_17 = {
    Text = "Cũng giống như, bạn cũng chưa bao giờ từ bỏ Aran."
  },
  AvgDialog_60350_Content_19 = {
    Text = "Từ sau vụ nổ đó, tất cả ký ức của tôi đều liên quan đến các bạn. Các bạn chính là toàn bộ thế giới của tôi."
  },
  AvgDialog_60350_Content_2 = {
    Text = "Con của ta, sức sống của ta, mãi mãi không ngừng… Ngươi không thể đánh bại ta được, Người Giữ Gìn."
  },
  AvgDialog_60350_Content_20 = {
    Text = "Tôi đã mất một lần cuộc đời của mình. Chết để bảo vệ mọi thứ của mình, hoặc sống bằng cách từ bỏ mọi thứ, lựa chọn duy nhất của tôi là đây."
  },
  AvgDialog_60350_Content_21 = {
    Text = "Thái Di Sơ im lặng nhìn chằm chằm vào mắt bạn trong thời gian dài."
  },
  AvgDialog_60350_Content_22 = {
    Text = "Tôi có thể phân biệt được lời nói dối…… anh nói là sự thật, Người gìn giữ bí mật."
  },
  AvgDialog_60350_Content_23 = {
    Text = "Xem ra, tôi đã đặt niềm tin nhầm người. Bạn thật sự không phải là người có thể đưa tôi đến thế giới mới…"
  },
  AvgDialog_60350_Content_24 = {
    Text = "Thái Di Sơ nhẹ nhàng thở dài trong sự thất vọng."
  },
  AvgDialog_60350_Content_25 = {
    Text = "Cô ấy đến gần bạn."
  },
  AvgDialog_60350_Content_26 = {
    Text = "Thái Di Sơ, cô muốn… a——"
  },
  AvgDialog_60350_Content_27 = {
    Text = "Một vật êm dịu và ấm áp đã bịt miệng bạn."
  },
  AvgDialog_60350_Content_28 = {
    Text = "Một vật thể hình cầu từ miệng của Thái Di Sơ tách ra, trượt động nhẹ nhàng."
  },
  AvgDialog_60350_Content_29 = {
    Text = "Nó đi qua miệng bạn, họng và thực quản của bạn. Nó hóa thành một làn gió mùa xuân nhẹ nhàng, thổi qua từng cơ quan trong cơ thể bạn, len lỏi tới tận đầu mút của mỗi mạch máu."
  },
  AvgDialog_60350_Content_3 = {
    Text = "Hãy từ bỏ đi, mọi nỗ lực chỉ là công cốc, đừng cố gắng chống lại Ngài."
  },
  AvgDialog_60350_Content_30 = {
    Text = "Không biết đã qua bao lâu. Thái Di Sơ thả bạn ra, đưa lưỡi liếm nhẹ lên môi."
  },
  AvgDialog_60350_Content_31 = {
    Text = "Thái Di Sơ……?"
  },
  AvgDialog_60350_Content_32 = {
    Text = "Vừa rồi... đó là.."
  },
  AvgDialog_60350_Content_33 = {
    Text = "Bạn là một kẻ lừa đảo, một kẻ ngốc, %player%. Bạn hoàn toàn không thể đánh bại Người. Bạn không có tư cách để đối mặt với Người…"
  },
  AvgDialog_60350_Content_34 = {
    Text = "Nhưng mà, cậu chính là loại người như vậy, tôi còn có cách nào khác nữa chứ?"
  },
  AvgDialog_60350_Content_35 = {
    Text = "Thái Di Sơ nhẹ nhàng thở dài. Làn hơi thở mơn man trên gương mặt bạn, ngọt ngào tựa làn gió xuân dịu dàng len lỏi vào tâm hồn."
  },
  AvgDialog_60350_Content_36 = {
    Text = "Trong hạt giống này, có sức mạnh chi phối dục vọng."
  },
  AvgDialog_60350_Content_37 = {
    Text = "Tôi đã tặng nó cho bạn từ lâu rồi… quà tặng đã đưa ra, không có lý do gì để thu hồi."
  },
  AvgDialog_60350_Content_38 = {
    Text = "Cô ấy nâng cằm bạn lên, nhìn bạn với vẻ tò mò, mỉm cười nhẹ nhàng."
  },
  AvgDialog_60350_Content_39 = {
    Text = "Tôi sẽ để mắt đến bạn, Người Giữ Gìn."
  },
  AvgDialog_60350_Content_4 = {
    Text = "Tôi tin bạn. Hãy cùng nhau, tiến tới thế giới mới không lo lắng…"
  },
  AvgDialog_60350_Content_40 = {
    Text = "Tôi sẽ nhìn bạn, kiên định bước trên con đường tuyệt vọng này… Tôi sẽ tham dự lễ tang của bạn, khóc thương bạn."
  },
  AvgDialog_60350_Content_41 = {
    Text = "Không còn hạt giống làm điểm tựa, cơ thể cát vàng không thể duy trì."
  },
  AvgDialog_60350_Content_42 = {
    Text = "Trong làn gió xuân dịu dàng kia, hình dáng của Thái Di Sơ hóa thành những hạt cát bay rơi rớt, như một tiếng thở dài nhẹ nhàng."
  },
  AvgDialog_60350_Content_5 = {
    Text = "Trước đây tôi không hiểu mục đích bạn gieo hạt giống đâu."
  },
  AvgDialog_60350_Content_6 = {
    Text = "Tôi sẽ không đồng ý với bạn, Thái Ý Tư."
  },
  AvgDialog_60350_Content_7 = {
    Text = "Hãy nhìn xem, Người Giữ Gìn… ngay cả tôi, một hạt giống biến thành, cũng có thể khiến bạn rơi vào tình cảnh thảm hại như vậy."
  },
  AvgDialog_60350_Content_8 = {
    Text = "Dù có thu hồi tất cả quyền hạn, ngươi cũng chỉ là một phân mảnh mà thôi... Ngươi có thể làm được gì?"
  },
  AvgDialog_60350_Content_9 = {
    Text = "Tôi sẽ không bỏ cuộc, Thái Diễm Sơ"
  },
  AvgDialog_60351_Content_1 = {
    Text = "Người cha và cô con gái"
  },
  AvgDialog_60351_Content_10 = {
    Text = "Tà Vy… tôi… đã từng gặp bạn…"
  },
  AvgDialog_60351_Content_11 = {
    Text = "Herbert nói, tôi là sáng tạo song sinh của đèn lồng, Hội Giáo đèn lồng được thành lập vì tôi…"
  },
  AvgDialog_60351_Content_12 = {
    Text = "Anh ấy không nói dối. Đầu kia của Song Tử, là tôi."
  },
  AvgDialog_60351_Content_13 = {
    Text = "...thì ra là vậy."
  },
  AvgDialog_60351_Content_14 = {
    Text = "Bạn dường như không ngạc nhiên."
  },
  AvgDialog_60351_Content_15 = {
    Text = "Tôi đã có một số suy đoán. \nHerbert nói rằng tôi là một trong những sáng tạo quan trọng của Hội Giáo đèn lồng, và tôi được sinh ra từ hồ đen."
  },
  AvgDialog_60351_Content_16 = {
    Text = "Và tôi đã từng gặp bạn. Đã thấy khuôn mặt của bạn…"
  },
  AvgDialog_60351_Content_17 = {
    Text = "Dự đoán của bạn hoàn toàn chính xác."
  },
  AvgDialog_60351_Content_18 = {
    Text = "Đây là đâu?"
  },
  AvgDialog_60351_Content_19 = {
    Text = "Tâm trí, giấc mơ, sự hội tụ của vô số thời khắc và chiều không gian, nơi gặp gỡ giữa logic và phi lý."
  },
  AvgDialog_60351_Content_2 = {
    Text = "Hào quang. màu sắc."
  },
  AvgDialog_60351_Content_20 = {
    Text = "Đây là một điểm kỳ dị không tồn tại……chốn ẩn náu của tôi."
  },
  AvgDialog_60351_Content_21 = {
    Text = "Nơi ẩn náu...\nBạn đang trốn tránh điều gì?"
  },
  AvgDialog_60351_Content_22 = {
    Text = "Một ánh mắt, đến từ ý chí vô thượng."
  },
  AvgDialog_60351_Content_23 = {
    Text = "Một……tia nhìn?"
  },
  AvgDialog_60351_Content_24 = {
    Text = "Dựa trên nhận thức của bạn, hãy tưởng tượng Người như một đứa trẻ đang ngủ say."
  },
  AvgDialog_60351_Content_25 = {
    Text = "Vũ trụ mà chúng ta tồn tại, toàn bộ hành tinh và văn minh, chỉ là một giấc mơ của Đấng Tối Cao. \nKhi Đấng Tối Cao bị đánh thức, cả vũ trụ sẽ không còn tồn tại."
  },
  AvgDialog_60351_Content_26 = {
    Text = "Universum của chúng ta……?!"
  },
  AvgDialog_60351_Content_27 = {
    Text = "Tà Vy không hề do dự dù chỉ một chút vì sự kinh ngạc của Ramona. Giọng nói của cô tiếp tục vang vọng từ mọi ngóc ngách của không gian này."
  },
  AvgDialog_60351_Content_28 = {
    Text = "Đối với Ngài, tất cả sự tồn tại đều là tiếng ồn, và sự hiện diện của ba thực thể cốt lõi quá mạnh mẽ, quá dễ dàng đánh thức Ngài khỏi ảo mộng."
  },
  AvgDialog_60351_Content_29 = {
    Text = "Vì vậy, tôi phải ẩn nấp. Ẩn nấp bên ngoài giấc mơ của Ngài."
  },
  AvgDialog_60351_Content_3 = {
    Text = "Dòng sông mộng ảo chảy trước mắt Ramona."
  },
  AvgDialog_60351_Content_30 = {
    Text = "Vì vậy, tôi không thể trực tiếp can thiệp vào mọi việc xảy ra trong thế giới của các bạn."
  },
  AvgDialog_60351_Content_31 = {
    Text = "Chúng ta chính là hai vị thần sinh đôi mà Hội Giáo đèn lồng muốn triệu hồi…"
  },
  AvgDialog_60351_Content_32 = {
    Text = "Họ… có ý định gây ra tiếng ồn để đánh thức ý chí vô thượng?!"
  },
  AvgDialog_60351_Content_33 = {
    Text = "Gương mặt mơ hồ của Tà Vy dường như hiện lên nụ cười hài lòng. Cô gật đầu với Ramona."
  },
  AvgDialog_60351_Content_34 = {
    Text = "Bạn là mảnh vỡ tách ra từ tư duy của tôi, thông qua bạn, họ sẽ đưa trí tuệ của tôi rời khỏi nơi này và nhập vào thân thể của bạn."
  },
  AvgDialog_60351_Content_35 = {
    Text = "Nếu họ thành công, ánh mắt của ý chí vô thượng sẽ sớm khóa chặt thế giới của bạn…"
  },
  AvgDialog_60351_Content_36 = {
    Text = "Đến lúc đó, cảnh tượng mà phân mảnh khác của tôi đã chứng kiến sẽ lại xảy ra."
  },
  AvgDialog_60351_Content_37 = {
    Text = "Hãy cho tôi biết, tôi có thể làm gì! Chỉ cần có thể đánh bại Yu Li-ét, thì có thể.."
  },
  AvgDialog_60351_Content_38 = {
    Text = "Đèn cầm tay không quan trọng, Ramona. Không có đèn cầm tay, không có Song Sinh, cũng sẽ có những thứ khác."
  },
  AvgDialog_60351_Content_39 = {
    Text = "Sự xuất hiện của ý chí vô thượng, không thể tránh khỏi. Tất cả những gì tôi làm, chỉ là để trì hoãn thời gian Ngài tỉnh dậy."
  },
  AvgDialog_60351_Content_4 = {
    Text = "Điều hiện ra trước mắt, là thời gian, là chiều, và là sự hòa hợp giữa lý tính và phi lý tính."
  },
  AvgDialog_60351_Content_40 = {
    Text = "Người có thể cứu Misaque, cứu thế giới của bạn, chỉ có {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_60351_Content_41 = {
    Text = "Bạn là chỉ… Người Giữ Gìn?"
  },
  AvgDialog_60351_Content_42 = {
    Text = "Từ vụ nổ của Akutê, {Male=anh ấy,Female=cô ấy} đã định sẵn bước chân lên con đường này."
  },
  AvgDialog_60351_Content_43 = {
    Text = "Khi tượng thần song sinh xuất hiện, \"cánh cửa\" sẽ xuất hiện."
  },
  AvgDialog_60351_Content_44 = {
    Text = "Lúc đó, {Male=anh ấy,Female=cô ấy} sẽ bước vào Cửa, biết tất cả những gì {Male=anh ấy,Female=cô ấy} nên biết."
  },
  AvgDialog_60351_Content_45 = {
    Text = "Người giữ bí mật…… rốt cuộc là ai?"
  },
  AvgDialog_60351_Content_46 = {
    Text = "Biểu cảm trên khuôn mặt của Tà Vy lại trở nên mơ hồ. Cô ấy lắc đầu."
  },
  AvgDialog_60351_Content_47 = {
    Text = "Tôi là đại diện của thể chất trí tuệ, tôi chỉ biết những điều mà Ngài cho phép tôi biết."
  },
  AvgDialog_60351_Content_48 = {
    Text = "Cô ấy mở mắt, nhìn RAMONA một cách nghiêm túc."
  },
  AvgDialog_60351_Content_49 = {
    Text = "Ramona, sự ra đời của bạn là một sai lầm. Cuộc sống của bạn, là một sự suy diễn sai lầm."
  },
  AvgDialog_60351_Content_5 = {
    Text = "Tất cả những nhận thức tụ thành dòng sông hư ảo, rửa sạch thân thể nhẹ nhàng của cô ấy."
  },
  AvgDialog_60351_Content_50 = {
    Text = "Nhưng, sự kết hợp của những sai lầm lại sinh ra kết quả đúng."
  },
  AvgDialog_60351_Content_51 = {
    Text = "Trong vô số tương lai, sự giúp đỡ của bạn dành cho {Male=anh ấy,Female=cô ấy} sẽ là con đường duy nhất để tránh khỏi thảm họa này…"
  },
  AvgDialog_60351_Content_52 = {
    Text = "Ừm… hình như tôi nghe thấy cô ấy đang nói chuyện với ai đó?"
  },
  AvgDialog_60351_Content_53 = {
    Text = "Ramona không biết mình đang tỉnh táo hay đang chìm vào giấc ngủ. Giọng nói của Tà Vy đã biến mất, bên tai cô vang lên một giọng nói quen thuộc khác."
  },
  AvgDialog_60351_Content_54 = {Text = "Ai?!"},
  AvgDialog_60351_Content_55 = {
    Text = "Sao thế, người bạn cũ của tôi? Không nhận ra tôi sao?"
  },
  AvgDialog_60351_Content_56 = {
    Text = "(Giáo sư Dexter... bố?)"
  },
  AvgDialog_60351_Content_57 = {
    Text = "Herbert không biết người đàn ông này đã đột nhiên xuất hiện bên cạnh anh ta như thế nào."
  },
  AvgDialog_60351_Content_58 = {
    Text = "Xung quanh anh ta, Clementine và các thành viên của hội nghị thẩm tra bao quanh Dexter."
  },
  AvgDialog_60351_Content_59 = {
    Text = "Dexter dường như không nhìn thấy dao và súng đang hướng về phía anh, anh đi thẳng đến bên Ramona, sau đó quan sát kỹ."
  },
  AvgDialog_60351_Content_6 = {
    Text = "Thức tỉnh đi. Người thừa kế của ta. Phân mảnh của ta."
  },
  AvgDialog_60351_Content_60 = {
    Text = "Hồi đó chính bạn, tên trộm này đã cướp cô ấy đi… Hôm nay, bạn và cô ấy đừng hòng rời khỏi đây!"
  },
  AvgDialog_60351_Content_61 = {
    Text = "Tôi tha thứ cho sự thiếu lễ độ của bạn. Dù sao, tôi cũng chưa có ý định lấy mạng các bạn ngay bây giờ."
  },
  AvgDialog_60351_Content_62 = {
    Text = "Tất nhiên, cũng không cần phải lo lắng về tôi. Thấy con gái tôi an toàn, tôi yên tâm rồi. Các bạn đã chăm sóc cô ấy rất tốt, tôi không sẵn sàng đưa cô ấy đi."
  },
  AvgDialog_60351_Content_63 = {
    Text = "Herbert nhíu mày, chăm chú nhìn vào mắt Dexter, muốn hiểu được anh ta đang nghĩ gì."
  },
  AvgDialog_60351_Content_64 = {
    Text = "Nhưng trên khuôn mặt đó, ngoài nụ cười thanh lịch của một quý ông, anh ta không thấy gì khác."
  },
  AvgDialog_60351_Content_65 = {
    Text = "Anh ta cảm nhận được một luồng khí nguy hiểm, và đã làm một cử chỉ phía sau lưng."
  },
  AvgDialog_60351_Content_66 = {
    Text = "Không cần lo lắng, ông Herbert. Dexter là bạn của chúng ta."
  },
  AvgDialog_60351_Content_67 = {Text = "Bạn?"},
  AvgDialog_60351_Content_68 = {
    Text = "Xin đừng hiểu lầm, bà Yu Li-ét, Nhiều năm trước, tôi đã nói rất rõ ràng với bà rồi."
  },
  AvgDialog_60351_Content_69 = {
    Text = "Tôi không phải là bạn của các bạn. Tôi chỉ là một khán giả."
  },
  AvgDialog_60351_Content_7 = {
    Text = "Ramona mở to mắt."
  },
  AvgDialog_60351_Content_70 = {
    Text = "Khán giả yêu thích nhất — mua vé năm cho phòng riêng, lịch sự, không bao giờ ồn ào và không bao giờ vắng mặt."
  },
  AvgDialog_60351_Content_71 = {
    Text = "Anh nhẹ nhàng vỗ vào vai Yu Li ét, như một khán giả cao quý đang bày tỏ sự tán thưởng chân thành đối với một diễn viên xuất sắc."
  },
  AvgDialog_60351_Content_72 = {
    Text = "Bà Yu Li-ét, tôi rất vui khi thấy bà cuối cùng cũng đến để thực hiện lời hứa của mình."
  },
  AvgDialog_60351_Content_73 = {
    Text = "Tuy nhiên, các người phải cẩn thận một chút. Tôi chỉ có một cô con gái, ngàn vạn lần, đừng để cô ấy gặp phải điều gì bất trắc."
  },
  AvgDialog_60351_Content_74 = {
    Text = "Tôi đã chờ đợi buổi biểu diễn này suốt hai mươi năm."
  },
  AvgDialog_60351_Content_75 = {
    Text = "Ramona hy vọng, hy vọng cô vẫn đang ở trong không gian của Tà Vy, mong đây là một giấc mơ kỳ quặc."
  },
  AvgDialog_60351_Content_76 = {
    Text = "Nhưng cô không thể kiểm soát sự run rẩy của thân thể mình, cũng không thể ngăn được giọt nước mắt lăn xuống từ khóe mắt, rơi vào hồ đen đang sôi sục."
  },
  AvgDialog_60351_Content_77 = {
    Text = "Giọt nước mắt long lanh ấy phản chiếu trong mắt Dexter, tạo nên một tia sáng chảy động."
  },
  AvgDialog_60351_Content_78 = {
    Text = "Tôi còn khách quan trọng cần gặp. Hẹn gặp lại mọi người nhé."
  },
  AvgDialog_60351_Content_79 = {
    Text = "Anh mỉm cười gật đầu chào mọi người, biến mất trong bóng tối đen đặc của hồ đen, không dừng lại dù chỉ một khắc vì giọt nước mắt đó."
  },
  AvgDialog_60351_Content_8 = {
    Text = "Trong không gian hư ảo này, hình bóng đang ngủ yên trong hồ đen đã lộ ra khuôn mặt được che phủ bởi lớp voan mỏng."
  },
  AvgDialog_60351_Content_9 = {
    Text = "—— và khuôn mặt y hệt Ramona."
  },
  AvgDialog_60352_Content_1 = {
    Text = "Thái Di Sơ giơ cao cánh tay, rải một nắm điểm sáng giống như hạt giống trước mặt bạn."
  },
  AvgDialog_60352_Content_2 = {
    Text = "Điểm sáng thu hút cát vàng, ngưng tụ thành một nhóm sinh vật quen thuộc."
  },
  AvgDialog_60352_Content_3 = {
    Text = "Những sinh vật từng gặp trong sa mạc lại xuất hiện trước mặt bạn dưới hình hài kinh hoàng."
  },
  AvgDialog_60352_Content_4 = {
    Text = "Thái Di Sơ! Bình tĩnh một chút.."
  },
  AvgDialog_60352_Content_5 = {
    Text = "Tôi rất bình tĩnh, Người Giữ Gìn."
  },
  AvgDialog_60352_Content_6 = {
    Text = "Đánh bại chúng, an ủi chúng, dù bạn có nhìn thấy hình bóng của tôi, vẫn chấp nhận. \nSau đó, tôi sẽ hóa thành hạt giống và đi vào cơ thể bạn."
  },
  AvgDialog_60352_Content_7 = {
    Text = "Tôi sẽ cùng bạn, đi đến thế giới mới…"
  },
  AvgDialog_60352_Content_8 = {
    Text = "Ngài vẫy tay. Sinh vật được tạo ra từ hồ đen tấn công bạn mãnh liệt…"
  },
  AvgDialog_60353_Content_1 = {
    Text = "Định mệnh"
  },
  AvgDialog_60353_Content_10 = {
    Text = "Thời lượng của bản nhạc có hạn, cần phải giữ lại cho những lúc quan trọng hơn. So với thất bại, đau đớn không là gì."
  },
  AvgDialog_60353_Content_11 = {
    Text = "Bạn thở dài."
  },
  AvgDialog_60353_Content_12 = {
    Text = "Gió xuân nhẹ nhàng và tiếng cười điên cuồng đan xen, hòa tan vào nhau, dần dần trở nên dịu dàng hơn, khả năng hành động của bạn đã phục hồi đáng kể."
  },
  AvgDialog_60353_Content_13 = {
    Text = "Hai thực thể khó thuyết phục đều đã trao quyền lực cho tôi."
  },
  AvgDialog_60353_Content_14 = {
    Text = "Tiếp theo, chỉ còn duy nhất thể chất trí tuệ vốn đã đứng về phía Misaque…"
  },
  AvgDialog_60353_Content_15 = {
    Text = "Bạn nhìn chằm chằm về phía trước, siết chặt tay."
  },
  AvgDialog_60353_Content_16 = {
    Text = "Đi nào, Hamlin. Chúng ta cần tăng tốc độ lên."
  },
  AvgDialog_60353_Content_17 = {
    Text = "Gần vị trí của Tà Vy, Yu Li-ét sẽ triển khai lực lượng tuần tra dày đặc."
  },
  AvgDialog_60353_Content_18 = {
    Text = "Cẩn thận một chút."
  },
  AvgDialog_60353_Content_2 = {
    Text = "Dáng vẻ của bạn thoải mái hơn nhiều. Lần thu hồi quyền lực thứ hai, xem ra bạn đã thích nghi khá tốt."
  },
  AvgDialog_60353_Content_3 = {
    Text = "Bạn nhăn mặt trước tiếng cười điên rồ bên tai và không thể kiềm chế được việc lườm nguýt Hamlin một cái."
  },
  AvgDialog_60353_Content_4 = {
    Text = "Bạn còn mặt mũi nào mà nói… Khi N đe dọa tôi lúc nãy, sao không thấy bạn ra giúp tôi?"
  },
  AvgDialog_60353_Content_5 = {
    Text = "Thuyết phục N là trách nhiệm của bạn. Bạn có thể xử lý vấn đề này."
  },
  AvgDialog_60353_Content_6 = {
    Text = "N là một người kiêu ngạo, cách giao tiếp của tôi chỉ khiến bạn khó đạt mục tiêu hơn."
  },
  AvgDialog_60353_Content_7 = {
    Text = "Bạn quả nhiên rất biết mình…"
  },
  AvgDialog_60353_Content_8 = {
    Text = "Mỗi người đều có vị trí của riêng mình. Nếu không hoàn thành trách nhiệm, buổi diễn sẽ không thể tiếp tục."
  },
  AvgDialog_60353_Content_9 = {
    Text = "Thế thì bạn hãy dùng âm nhạc giúp tôi giảm bớt một chút đau đớn đi… Bạn có biết thứ N đưa cho tôi khó chịu đến mức nào không?"
  },
  AvgDialog_60354_Content_1 = {
    Text = "Hô……hô……"
  },
  AvgDialog_60354_Content_10 = {
    Text = "Bụng bạn phát ra một cơn đau quặn dữ dội. Bạn mở miệng, một luồng sương mù đặc quánh thoát ra từ cơ thể bạn, giống như mực tan trong dòng sông."
  },
  AvgDialog_60354_Content_11 = {
    Text = "Sương mù giống như một thực thể, tụ lại thành một vật thể hình bầu dục ba chiều, giống như con mắt của một sinh vật nào đó."
  },
  AvgDialog_60354_Content_12 = {
    Text = "Con mắt đó chưa kịp mở ra đã tan biến trong ánh sáng rực rỡ của Tà Vy."
  },
  AvgDialog_60354_Content_13 = {
    Text = "Đây là…"
  },
  AvgDialog_60354_Content_14 = {
    Text = "Bạn từ từ bỏ tay che mắt ra. Dáng hình ảo ảnh của Tà Vy đứng trước mặt bạn, gật đầu chậm rãi."
  },
  AvgDialog_60354_Content_15 = {
    Text = "Những lỗi lầm trên người bạn đã được sửa chữa."
  },
  AvgDialog_60354_Content_16 = {
    Text = "Bạn nói sai, không phải tôi?…"
  },
  AvgDialog_60354_Content_17 = {
    Text = "Lỗi ký sinh trong cơ thể bạn. Đó là con mắt mà ý chí vô thượng dùng để nhìn thấu thế giới này."
  },
  AvgDialog_60354_Content_18 = {
    Text = "N cảm nhận được sự tồn tại của nó. Ngài ban cho bạn không chỉ quyền năng mà còn một ý chí để kiểm soát bạn."
  },
  AvgDialog_60354_Content_19 = {
    Text = "Bây giờ, những lỗi này đã được khắc phục. Bạn hiện tại an toàn."
  },
  AvgDialog_60354_Content_2 = {
    Text = "Bạn vừa đủ sức chống lại cuộc tấn công của Tà Vy."
  },
  AvgDialog_60354_Content_20 = {
    Text = "Thì ra là vậy, tôi còn tưởng… có lẽ là tôi đã quá lo xa."
  },
  AvgDialog_60354_Content_21 = {
    Text = "Bạn thở phào một hơi dài, rồi từ từ đứng dậy."
  },
  AvgDialog_60354_Content_22 = {
    Text = "Cảm ơn bạn…"
  },
  AvgDialog_60354_Content_23 = {
    Text = "Không cần cảm ơn, tôi chỉ hoàn thành những gì mình nên làm. Những việc tiếp theo, sẽ giao lại cho bạn."
  },
  AvgDialog_60354_Content_24 = {
    Text = "Có một điều tôi không hiểu."
  },
  AvgDialog_60354_Content_25 = {
    Text = "Ý chí vô thượng, có liên quan gì đến tôi… tại sao lại chọn tôi? Tôi rốt cuộc… là ai?"
  },
  AvgDialog_60354_Content_26 = {
    Text = "Bạn nhíu mày và nhìn về phía Tà Vy."
  },
  AvgDialog_60354_Content_27 = {
    Text = "Sự thật, thường có nghĩa là trách nhiệm, cũng có nghĩa là khổ đau."
  },
  AvgDialog_60354_Content_28 = {
    Text = "Tôi sẵn sàng đảm nhận"
  },
  AvgDialog_60354_Content_29 = {
    Text = "Tôi là Người Giữ Gìn của Misaque, tôi đã thề ở Nấm Mộ Chìa Khóa."
  },
  AvgDialog_60354_Content_3 = {
    Text = "Cú va chạm mạnh mẽ khiến bạn không còn chút sức lực nào, quỳ sụp xuống đất."
  },
  AvgDialog_60354_Content_30 = {
    Text = "Nếu đó là điều tôi phải gánh vác, tôi sẵn lòng chịu trách nhiệm."
  },
  AvgDialog_60354_Content_31 = {
    Text = "Tà Vy nhìn vào đôi mắt kiên định của bạn, khuôn mặt cô nhẹ nhàng lấp lánh, dường như đang nghĩ đến những chuyện xa xôi."
  },
  AvgDialog_60354_Content_32 = {
    Text = "Ngài là hỗn loạn nguyên thủy, kẻ hủy diệt vô thức…… Dù là một phần nhỏ của Ngài, bạn vẫn khác biệt với Ngài."
  },
  AvgDialog_60354_Content_33 = {Text = "?!!"},
  AvgDialog_60354_Content_34 = {
    Text = "Xuân của Akutê, bạn đã đến thế giới này. Tôi không thể nhìn rõ số phận mà bạn sẽ mang lại. Tôi đã từng nghĩ, bạn sẽ là nguyên nhân dẫn đến sự hủy diệt của thế giới."
  },
  AvgDialog_60354_Content_35 = {
    Text = "Tôi đã sai, Người Giữ Gìn. Hủy diệt không cần ngòi nổ. Những mảnh vỡ tinh thần của Ngài, ý thức mơ hồ về sự tồn tại của Ngài, sẽ là câu trả lời duy nhất."
  },
  AvgDialog_60354_Content_36 = {
    Text = "Ý chí vô thượng……phân mảnh……"
  },
  AvgDialog_60354_Content_37 = {
    Text = "Trái tim bỗng nhiên nhảy lên. Điều luẩn quẩn trong lòng dường như là một sự cộng hưởng từ sâu thẳm của vũ trụ."
  },
  AvgDialog_60354_Content_38 = {
    Text = "Tài năng của bạn, thái độ của ba chất thể đối với bạn… Bạn không phải chưa từng nghĩ đến chuyện này. Khi câu trả lời thực sự đến trước mặt bạn, bạn vẫn cảm nhận được sự rúng động."
  },
  AvgDialog_60354_Content_39 = {
    Text = "Nhưng bạn cũng hiểu rằng, bây giờ còn có những vấn đề quan trọng hơn, cần bạn trả lời."
  },
  AvgDialog_60354_Content_4 = {
    Text = "Tại sao……"
  },
  AvgDialog_60354_Content_40 = {
    Text = "Tà Vy, xin hãy nói cho tôi biết, tôi phải làm gì để có được lực lượng của Người… Tôi phải làm gì để ngăn chặn sự đến của Người!"
  },
  AvgDialog_60354_Content_41 = {
    Text = "Sự đến của ý chí vô thượng là không thể ngăn cản. Người gìn giữ bí mật."
  },
  AvgDialog_60354_Content_42 = {
    Text = "Thể chất trí tuệ thông hiểu vạn vật, nhưng Ngài chưa ban cho tôi toàn bộ kiến thức. \nToàn tri chưa hẳn là điều tốt lành, đôi khi chỉ gây ra tai họa lớn hơn."
  },
  AvgDialog_60354_Content_43 = {
    Text = "Trong những điều tôi biết, không có câu trả lời mà bạn đang tìm kiếm."
  },
  AvgDialog_60354_Content_44 = {
    Text = "Tất cả các câu trả lời, tất cả các tai họa, đều ở sau cánh cửa.."
  },
  AvgDialog_60354_Content_45 = {
    Text = "Một âm thanh mơ hồ đã ngắt lời Tà Vy. Cô bình tĩnh quay đầu lại, ánh mắt dường như xuyên qua không gian này, hướng tới một nơi nào đó bên ngoài."
  },
  AvgDialog_60354_Content_46 = {
    Text = "Khuôn mặt huyền ảo, xinh đẹp ấy lộ ra nụ cười nhẹ nhõm."
  },
  AvgDialog_60354_Content_47 = {
    Text = "Cô ấy cuối cùng cũng tìm thấy tôi rồi."
  },
  AvgDialog_60354_Content_48 = {
    Text = "Bỗng nhiên, một luồng rỗng rỗng xuất hiện trong không gian bí mật này."
  },
  AvgDialog_60354_Content_49 = {
    Text = "Cô ấy? Bạn có nghĩa là… Yu Li-ét?"
  },
  AvgDialog_60354_Content_5 = {
    Text = "Biến mất đi."
  },
  AvgDialog_60354_Content_50 = {
    Text = "Rỗng rỗng tăng lên với tốc độ nhanh chóng, làm ô uế mọi góc cạnh của không gian này."
  },
  AvgDialog_60354_Content_51 = {
    Text = "Rỗng rỗng tấn công Tà Vy như thể muốn bao vây, trói buộc và nhấn chìm cô."
  },
  AvgDialog_60354_Content_52 = {Text = "Tà Vy!!"},
  AvgDialog_60354_Content_53 = {
    Text = "Đôi cánh khổng lồ đột nhiên mở ra, trong sự kéo của rỗng rỗng, cô ấy bất ngờ nhảy về phía bạn——"
  },
  AvgDialog_60354_Content_54 = {
    Text = "Dòng chất lỏng rỗng rỗng kéo xé trên cơ thể cô, để lại những vết thương lớn. Chất lỏng đen bên trong Người hòa lẫn với dòng chảy rỗng rỗng, biến Người thành một bức tranh dầu mờ ảo và bẩn thỉu."
  },
  AvgDialog_60354_Content_55 = {
    Text = "Trong cơn đau đớn và bẩn thỉu này, Người bình thản nhìn bạn, đưa tay ra hướng bạn ——"
  },
  AvgDialog_60354_Content_56 = {
    Text = "Tôi và Ramona sẽ chết tạm thời hoặc mãi mãi."
  },
  AvgDialog_60354_Content_57 = {
    Text = "Khi bạn rời khỏi đây, chúng ta sẽ là kẻ thù."
  },
  AvgDialog_60354_Content_58 = {
    Text = "Ngón tay của Ngài nhẹ nhàng chạm vào trán bạn."
  },
  AvgDialog_60354_Content_59 = {
    Text = "Một tia sáng tinh khiết chiếu vào tâm trí bạn, soi sáng mọi đầu mút thần kinh của bạn. Não bộ của bạn ngập tràn vô số kiến thức."
  },
  AvgDialog_60354_Content_6 = {
    Text = "Cô ấy nâng tay lên."
  },
  AvgDialog_60354_Content_60 = {
    Text = "Lực lượng của Thái Di Sơ và N vốn đang hoành hành trong cơ thể bạn, nhưng khi tia sáng chiếu vào, cơn gió gào thét và tiếng cười bỗng nhiên im lặng."
  },
  AvgDialog_60354_Content_61 = {
    Text = "Như thể đã bổ sung mảnh ghép cuối cùng, ba luồng lực lượng trong cơ thể bạn cân bằng và thống nhất, hội tụ thành một dải ngân hà tĩnh lặng và bao la."
  },
  AvgDialog_60354_Content_62 = {
    Text = "Không có cách nào cầu xin. Không có cách nào trốn tránh. Đây là số phận của thế giới này."
  },
  AvgDialog_60354_Content_63 = {
    Text = "Tôi trao cho bạn mọi lực lượng và quyền hạn, Người Giữ Gìn."
  },
  AvgDialog_60354_Content_64 = {
    Text = "Đánh bại chúng tôi. Giết chết chúng tôi. Rồi,cứu chúng tôi."
  },
  AvgDialog_60354_Content_7 = {
    Text = "Đợi đã!——"
  },
  AvgDialog_60354_Content_8 = {
    Text = "Ánh sáng trắng chói chang bùng phát từ Tà Vy. \nBạn hoàn toàn bất lực, chỉ có thể để cho tia sáng mạnh mẽ đó xuyên thẳng qua thân thể của bạn."
  },
  AvgDialog_60354_Content_9 = {Text = "Ừ——"},
  AvgDialog_60356_Content_1 = {
    Text = "Hô……hô……"
  },
  AvgDialog_60356_Content_10 = {
    Text = "Dù thế nào đi nữa, tôi nhất định không để cho mưu đồ của bạn thành công!"
  },
  AvgDialog_60356_Content_11 = {
    Text = "Hamlin, bảo vệ tôi!"
  },
  AvgDialog_60356_Content_12 = {
    Text = "Hamlin nhẹ nhàng nâng cây đũa chỉ huy lên."
  },
  AvgDialog_60356_Content_13 = {
    Text = "Dáng vẻ của Yu Li-ét không thay đổi, dù bao nhiêu thuộc hạ ngã xuống, cô vẫn mỉm cười nhìn bạn, như thể những người đó chỉ là nguồn tài nguyên tiêu hao giá trị thấp để tiêu thụ lực lượng tinh thần của bạn."
  },
  AvgDialog_60356_Content_14 = {
    Text = "Bạn không dám chậm trễ, ra lệnh cho các thân thể được đánh thức. Đây là cơ hội không thể bỏ lỡ, bạn quyết tâm đánh bại cô ta hoàn toàn trong một đòn quyết định!"
  },
  AvgDialog_60356_Content_15 = {
    Text = "Bạn giơ cao tay cầm chìa khóa bạc. Chìa khóa bạc phát ra ánh sáng chói lọi, sức mạnh tinh thần to lớn truyền vào thân thể được đánh thức."
  },
  AvgDialog_60356_Content_16 = {
    Text = "Chuẩn bị tấn công!"
  },
  AvgDialog_60356_Content_17 = {
    Text = "Thân thể được đánh thức, hãy chuẩn bị…"
  },
  AvgDialog_60356_Content_18 = {
    Text = "Chương thứ tư, tạm dừng."
  },
  AvgDialog_60356_Content_19 = {
    Text = "Giọng nói quen thuộc. Thanh thoát, kiên định, không thể từ chối. \nCây gậy chỉ huy nhẹ nhàng điểm xuống sau lưng bạn, tựa như trên sân khấu nhà hát, ổn định và thanh nhã."
  },
  AvgDialog_60356_Content_2 = {
    Text = "Thân thể bạn run rẩy vì mệt mỏi quá độ, và áp lực từ liên kết tinh thần cũng khiến đầu bạn đau nhói từng cơn."
  },
  AvgDialog_60356_Content_20 = {
    Text = "Trong lệnh này, giai điệu giúp duy trì sự ổn định tinh thần của bạn đã biến mất, thay vào đó là những âm thanh chói tai và hỗn loạn."
  },
  AvgDialog_60356_Content_21 = {
    Text = "Nhạc thanh ấy từng là mái vòm bảo vệ thế giới tinh thần của bạn, giúp bạn ngăn chặn làn nước đen cuồn cuộn."
  },
  AvgDialog_60356_Content_22 = {
    Text = "Lúc này, mái vòm đột nhiên sụp đổ, hóa thành những mảnh dao sắc bén, hòa cùng với hồ đen sôi sục, cùng nhau tấn công thế giới tinh thần của bạn."
  },
  AvgDialog_60356_Content_23 = {Text = "À!!——"},
  AvgDialog_60356_Content_24 = {
    Text = "Đau đớn lớn khiến bạn không thể chịu được. Đường dẫn liên kết giữa bạn và thân thể được đánh thức bị cắt đứt, thân thể được đánh thức ngay lập tức mất hết lực lượng, từng cái một đổ xuống bên chân Yu Li-ét."
  },
  AvgDialog_60356_Content_25 = {
    Text = "Cuộc chiến kéo dài gây ra sự tiêu thụ, cộng với việc không có bất kỳ sự chuẩn bị nào, biến cố bất ngờ khiến bạn mất khả năng phản kháng."
  },
  AvgDialog_60356_Content_26 = {
    Text = "Nhiệm vụ của tôi đã hoàn thành rồi."
  },
  AvgDialog_60356_Content_27 = {
    Text = "Nhạc trưởng cất cây gậy chỉ huy của mình. Gọn gàng, thanh lịch, không mang bất kỳ sự do dự nào."
  },
  AvgDialog_60356_Content_28 = {
    Text = "Đánh giá của thưa ngài Hamlin rất chính xác."
  },
  AvgDialog_60356_Content_29 = {
    Text = "Người giữ bí mật là mối đe dọa lớn nhất của chúng ta. Đây là sân nhà của %hisorher%, nếu để {Male=anh ấy,Female=cô ấy} thoát khỏi tầm kiểm soát, kế hoạch của chúng ta sẽ bị đe dọa nghiêm trọng."
  },
  AvgDialog_60356_Content_3 = {
    Text = "Rất nhiều binh sĩ và giáo sĩ của hội nghị thẩm tra ngã xuống hồ đen gần bạn, nhìn từ trên cao, giống như một bức tranh được tạo nên từ những xác chết."
  },
  AvgDialog_60356_Content_30 = {
    Text = "Để giành lấy sự tin tưởng của %hisorher%, không chỉ có thể khiến {Male=anh ấy,Female=cô ấy} giúp chúng ta tìm thấy Tà Vy, mà còn có thể theo dõi nhất cử nhất động của %hisorher% khi ở bên cạnh {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_60356_Content_31 = {
    Text = "Nếu không phải là kế sách của ngài, kế hoạch của chúng tôi rất khó có thể suôn sẻ như vậy. Được hợp tác với một nhân tài xuất chúng như ngài, đó là vinh dự của tôi."
  },
  AvgDialog_60356_Content_32 = {
    Text = "Không cần khách khí."
  },
  AvgDialog_60356_Content_33 = {
    Text = "Hamlin gật đầu nhẹ nhàng, đáp lại lời của Yu Li-ét."
  },
  AvgDialog_60356_Content_34 = {
    Text = "Bạn dùng hết sức lực cuối cùng, ngước lên, nhìn người bên cạnh."
  },
  AvgDialog_60356_Content_35 = {Text = "Hamlin…?"},
  AvgDialog_60356_Content_36 = {
    Text = "Hamlin, bạn…"
  },
  AvgDialog_60356_Content_37 = {
    Text = "Liên kết tinh thần của bạn đã bị phá hủy hoàn toàn, hiện tại bạn không thể làm gì được."
  },
  AvgDialog_60356_Content_38 = {
    Text = "Đến nước này, nói nhiều cũng vô ích. Hãy chấp nhận và chờ đợi."
  },
  AvgDialog_60356_Content_39 = {
    Text = "Đợi chờ bản nhạc tối thượng đến."
  },
  AvgDialog_60356_Content_4 = {
    Text = "Thật khó tin, Người Giữ Gìn …… tài năng của bạn thật đáng ngưỡng mộ."
  },
  AvgDialog_60356_Content_40 = {
    Text = "Giọng của Hamlin bình tĩnh như một hồ băng, bên trong sạch sẽ, trống rỗng, bạn chẳng thể nhìn thấy gì."
  },
  AvgDialog_60356_Content_41 = {
    Text = "Tiếng bước chân vang lên, một đội giáo sĩ khiêng một người xuất hiện trước mặt các bạn."
  },
  AvgDialog_60356_Content_42 = {
    Text = "Ramona……!!"
  },
  AvgDialog_60356_Content_43 = {
    Text = "Bạn muốn vùng vẫy, nhưng thân thể không thể di chuyển dù chỉ một chút, chỉ có thể trơ mắt nhìn họ đặt thân thể của Ramona xuống dưới cơ thể của Tà Vy."
  },
  AvgDialog_60356_Content_44 = {
    Text = "Khi thân thể của Ramona được đặt vào hồ đen, một pháp trận lớn khắc biểu tượng đèn lồng xuất hiện dưới chân cô."
  },
  AvgDialog_60356_Content_45 = {
    Text = "Yu Li-ét mỉm cười, đặt một chiếc đèn có hình thù kỳ lạ lên đầu Ramona."
  },
  AvgDialog_60356_Content_46 = {
    Text = "Cô từ từ nâng cánh tay lên, nụ cười trên khuôn mặt dần trở nên nghiêm trang."
  },
  AvgDialog_60356_Content_47 = {
    Text = "Cản trở cuối cùng đã bị loại bỏ, tất cả đã sẵn sàng."
  },
  AvgDialog_60356_Content_48 = {
    Text = "Đấng sáng tạo tối cao, xin hãy đáp lại lời kêu gọi của chúng tôi…"
  },
  AvgDialog_60356_Content_49 = {
    Text = "Hãy mang đến cho thế giới này sự thanh lọc vĩ đại!"
  },
  AvgDialog_60356_Content_5 = {
    Text = "Tuy nhiên, thật đáng tiếc, bạn không phải là đối thủ của tôi."
  },
  AvgDialog_60356_Content_50 = {
    Text = "Xoạt——"
