  AvgDialog_60356_Content_51 = {
    Text = "Hồ đen bát ngát bắt đầu rung lắc mạnh mẽ."
  },
  AvgDialog_60356_Content_52 = {
    Text = "Dưới pháp trận khổng lồ, trong đôi mắt tuyệt vọng của bạn, một tượng thần trắng vô cùng huy hoàng từ từ lộ ra đỉnh đầu của Ngài."
  },
  AvgDialog_60356_Content_6 = {
    Text = "Sức mạnh của ba chất thể đã ổn định, lực lượng của tôi đã được khôi phục."
  },
  AvgDialog_60356_Content_7 = {
    Text = "Tôi đã giao đấu với cô, khả năng của cô tôi rất rõ, Dư Lệ Эт."
  },
  AvgDialog_60356_Content_8 = {
    Text = "Tôi biết bạn rất mạnh mẽ, tôi cũng biết rằng bạn còn có lực lượng ẩn chưa sử dụng… nhưng nếu muốn nhắm đến Misaque, bạn đã chọn sai đối thủ."
  },
  AvgDialog_60356_Content_9 = {
    Text = "Bạn nắm chặt bạc tâm, các thể xác đã thức tỉnh xung quanh nhận được lệnh của bạn, bao vây Yu Li-ét."
  },
  AvgDialog_60357_Content_1 = {
    Text = "Chương ba (Phần nhạc thứ ba)"
  },
  AvgDialog_60357_Content_10 = {
    Text = "Thân thể và sức mạnh tinh thần đã được phục hồi!"
  },
  AvgDialog_60357_Content_11 = {
    Text = "Tác động của hồ đen đã cơ bản biến mất, chỉ là tôi vẫn chưa tìm ra cách kích hoạt quyền năng của ba thực thể lớn…"
  },
  AvgDialog_60357_Content_12 = {
    Text = "Phương pháp hấp thụ quyền năng, đằng sau cánh cửa."
  },
  AvgDialog_60357_Content_13 = {
    Text = "Vừa rồi ở không gian của Tà Vy, Người ấy cũng đã thông báo cho tôi về chuyện này… Sao bạn biết?"
  },
  AvgDialog_60357_Content_14 = {Text = "Đoán."},
  AvgDialog_60357_Content_15 = {
    Text = "Bây giờ ngắt tiếng nhạc có rủi ro. Trước khi quyền năng của ba chất thể phát huy hoàn toàn, tôi sẽ tiếp tục giúp bạn giữ vững sự ổn định tinh thần."
  },
  AvgDialog_60357_Content_16 = {
    Text = "Cảm ơn… Hamlin, nếu không có sự giúp đỡ của bạn, tôi không thể đi đến bước này ."
  },
  AvgDialog_60357_Content_17 = {
    Text = "Tôi có mục đích của tôi."
  },
  AvgDialog_60357_Content_18 = {
    Text = "Bạn đã giúp tôi, điều bạn muốn tìm, tôi nhất định sẽ cố gắng giúp bạn tìm thấy."
  },
  AvgDialog_60357_Content_19 = {
    Text = "Bạn đương nhiên sẽ làm được. Tôi chưa bao giờ nghi ngờ điều đó."
  },
  AvgDialog_60357_Content_2 = {
    Text = "Cảm giác từ ngón tay biến mất trên trán bạn. Bạn mở mắt ra, Tà Vy và thế giới của Ngài biến mất, hồ đen xuất hiện trở lại dưới chân bạn."
  },
  AvgDialog_60357_Content_20 = {
    Text = "Bây giờ chúng ta hãy đi tìm Yu Li-ét, giải cứu Ramona…"
  },
  AvgDialog_60357_Content_21 = {
    Text = "He he, tôi đến thăm Misaque, làm gì có chuyện phiền chủ nhân phải tìm tôi."
  },
  AvgDialog_60357_Content_22 = {Text = "!!!"},
  AvgDialog_60357_Content_23 = {
    Text = "Cảm giác nguy cơ mạnh mẽ khiến bạn lập tức căng thẳng. Bạn và Hamlin quay người lại, đưa lưng cho nhau, mỗi người giám sát một nửa khu vực."
  },
  AvgDialog_60357_Content_24 = {
    Text = "Một chiếc mũ tím mỏng manh hiện lên trong ánh sáng mờ ảo của hồ đen."
  },
  AvgDialog_60357_Content_25 = {
    Text = "Lại gặp nhau rồi, Người Giữ Gìn. Còn anh, thưa ông phản bội."
  },
  AvgDialog_60357_Content_27 = {
    Text = "Phụ nữ dưới chiếc nón che mặt mỉm cười với bạn một cách hiền từ, giống hệt như nụ cười khi hai người lần đầu gặp nhau ở sa mạc."
  },
  AvgDialog_60357_Content_28 = {
    Text = "Khi giọng nói của cô ấy vang lên, vô số điệp viên và giáo sĩ mặc áo tím xuất hiện bên cạnh các bạn, bao vây các bạn một cách chặt chẽ."
  },
  AvgDialog_60357_Content_29 = {
    Text = "Họ không biết đã ở trong hồ đen sôi sục bao lâu, việc nằm ở trung tâm rỗng rỗng khiến họ phải chịu đựng thương tích nặng nề. Đôi khi ai đó ngã xuống và tan thành chất lỏng đen đặc, hòa vào hồ đen."
  },
  AvgDialog_60357_Content_3 = {
    Text = "Tôi……đã trở về?"
  },
  AvgDialog_60357_Content_30 = {
    Text = "Dù là người bên cạnh hay chính bản thân họ ngã xuống, khuôn mặt của những người này đều không biểu lộ cảm xúc."
  },
  AvgDialog_60357_Content_31 = {
    Text = "Họ là chó của Dzơ-li-ét. Họ chỉ tuân theo ý chí của người cầm đèn."
  },
  AvgDialog_60357_Content_32 = {
    Text = "Bạn luôn… chờ tôi?"
  },
  AvgDialog_60357_Content_33 = {
    Text = "Tôi đã đợi bạn rất lâu, may mắn là sự chờ đợi của tôi không vô ích. Tôi muốn cảm ơn bạn, Người giữ gìn {Male=ngài,Female=cô}."
  },
  AvgDialog_60357_Content_34 = {
    Text = "Tìm kiếm Tà Vy đối với người thường khó như lên trời. Nếu không phải vì Tà Vy đã đưa bạn vào không gian của Người, có lẽ tôi sẽ mất vài tuần để định vị Người."
  },
  AvgDialog_60357_Content_35 = {Text = "!!!"},
  AvgDialog_60357_Content_36 = {
    Text = "Đây là……bạn cố ý?"
  },
  AvgDialog_60357_Content_37 = {
    Text = "Không thể nào……ở nghĩa trang, con chó mặt người đã bị chúng ta tiêu diệt, bạn không thể biết được hành tung và kế hoạch của tôi……"
  },
  AvgDialog_60357_Content_38 = {
    Text = "Con người không thể hiểu được toàn bộ sự việc, đây chính là ranh giới của sự hiểu biết con người."
  },
  AvgDialog_60357_Content_39 = {
    Text = "Người giữ bí mật {Male=ngài,Female=cô}, bạn đã đóng góp xuất sắc cho sự đến của thần minh. Trong thế giới mới mà thần minh tạo ra, bạn chắc chắn sẽ nhận được sự sủng ái khiến người khác ghen tỵ."
  },
  AvgDialog_60357_Content_4 = {
    Text = "Bạn dường như vừa mất ý thức trong giây lát."
  },
  AvgDialog_60357_Content_40 = {
    Text = "Cô ấy vẫy tay. Những giáo sĩ và binh sĩ bao vây bạn, mặt vô biểu cảm, lao tới phía bạn…"
  },
  AvgDialog_60357_Content_5 = {
    Text = "Tôi... đã được Tà Vy đưa đến một không gian kỳ lạ.."
  },
  AvgDialog_60357_Content_6 = {
    Text = "Xem ra, sức mạnh của ba đại thực thể, bạn đã thu hồi hết rồi."
  },
  AvgDialog_60357_Content_7 = {
    Text = "Bạn nhắm mắt lại, cảm nhận lực lượng đang dâng trào trong cơ thể mình."
  },
  AvgDialog_60357_Content_8 = {
    Text = "Ba luồng lực lượng phồn thịnh kia, trong cơ thể bạn chế ngự lẫn nhau, tụ hợp thành một biển hài hòa, theo hơi thở của bạn lặng lẽ dâng lên và hạ xuống."
  },
  AvgDialog_60357_Content_9 = {
    Text = "Bạn đứng dậy, kiểm tra trạng thái thân thể của mình."
  },
  AvgDialog_60358_Content_1 = {
    Text = "Rất nhiều bóng từ cơ thể của N rơi rớt ra."
  },
  AvgDialog_60358_Content_10 = {
    Text = "Vậy thì, hãy mang đến cho tôi vở kịch tuyệt vời này, Người Giữ Gìn {Male=ngài,Female=cô}."
  },
  AvgDialog_60358_Content_2 = {
    Text = "Bóng tối rơi xuống sân khấu, nhanh chóng biến thành sinh vật nguy hiểm bị hòa tan, vây quanh bạn."
  },
  AvgDialog_60358_Content_3 = {
    Text = "Thế nào, bạn tôi?"
  },
  AvgDialog_60358_Content_4 = {
    Text = "Cảm giác như thế nào khi đã thu hồi được quyền lực của Thể Chất Dục Vọng một cách suôn sẻ, nhưng giờ đây phải chứng kiến nó bị cướp đi?"
  },
  AvgDialog_60358_Content_5 = {
    Text = "Bạn muốn làm gì, N!"
  },
  AvgDialog_60358_Content_6 = {
    Text = "Quyền năng này, đối với bạn hoàn toàn không có tác dụng!"
  },
  AvgDialog_60358_Content_7 = {
    Text = "Thật sự không có ích lợi… nhưng, nhìn thấy quyền lực của ngươi bị mất đi, điều này rất hữu ích cho ta."
  },
  AvgDialog_60358_Content_8 = {
    Text = "Bạn có ý gì……"
  },
  AvgDialog_60358_Content_9 = {
    Text = "Là diễn viên, là khán giả, xung đột kịch tính xuất sắc nên là mục tiêu truy cầu suốt đời của chúng ta……"
  },
  AvgDialog_60596_Content_1 = {
    Text = "Đèn lồng đã xuất hiện. Ý chí tối thượng, hãy để tôi thắp sáng ngọn đèn cho ngài ——"
  },
  AvgDialog_60596_Content_2 = {
    Text = "Thần tượng đang nuốt chửng Tà Vy và Ramona."
  },
  AvgDialog_60596_Content_3 = {
    Text = "Âm nhạc của tôi đã vang lên vì bạn. Hãy phá vỡ sự hòa hợp của chúng, Người Giữ Gìn!"
  },
  AvgDialog_60842_Content_1 = {
    Text = "Chân Lý Quên Lãng"
  },
  AvgDialog_60842_Content_10 = {
    Text = "Tìm thấy cậu rồi… Tà Vy!"
  },
  AvgDialog_60842_Content_11 = {
    Text = "Tiếng kêu sắc nhọn vang vọng khắp hồ đen. Quyền năng trí tuệ trong cơ thể rung động theo tiếng kêu."
  },
  AvgDialog_60842_Content_12 = {
    Text = "Vô số hình bóng trắng, từ các chiều không gian và thời gian khác nhau được bắt giữ, tụ hội vào bức tượng đen trắng kia."
  },
  AvgDialog_60842_Content_13 = {
    Text = "Rất nhanh, những tiếng hí và rung động đều biến mất."
  },
  AvgDialog_60842_Content_14 = {
    Text = "Dù không có đèn lồng, vẫn sẽ có người khác. Không ai có thể trốn tránh Người, Tà Vy."
  },
  AvgDialog_60842_Content_15 = {
    Text = "Đến đây, hãy cùng nhau chào đón sự giáng sinh của Người!"
  },
  AvgDialog_60842_Content_16 = {
    Text = "Khi động tác của Yu Li-ét dừng lại, hai tượng đèn cầm tay khổng lồ bắt đầu tụ về trung tâm, như thể những thân xác đang tìm kiếm linh hồn, gấp rút muốn hòa vào làm một với bức tượng đen trắng ở trung tâm."
  },
  AvgDialog_60842_Content_17 = {
    Text = "Tà Vy! Ramona!! À——"
  },
  AvgDialog_60842_Content_18 = {
    Text = "Một tia sáng mạnh mẽ đột nhiên bùng lên. Đằng sau hai sáng tạo khổng lồ, xuất hiện một khe hở."
  },
  AvgDialog_60842_Content_19 = {
    Text = "Bạn từ từ bỏ tay đang che mắt ra."
  },
  AvgDialog_60842_Content_2 = {
    Text = "Bạn đang ở trong cơn bão."
  },
  AvgDialog_60842_Content_20 = {
    Text = "Đó là…… cửa?"
  },
  AvgDialog_60842_Content_21 = {
    Text = "Cánh cửa ảo phía sau Tà Vy vào thời điểm này đã trở thành hiện thực."
  },
  AvgDialog_60842_Content_22 = {
    Text = "Ánh sáng từ khe cửa đang mở rộng tỏa ra, vô cảm như vũ trụ, tinh khiết như chân lý."
  },
  AvgDialog_60842_Content_23 = {
    Text = "Dư Lị-ét si mê nhìn vào vùng sáng đó, hai dòng nước mắt trượt xuống dưới ánh sáng chói chang, cô hoàn toàn không hay biết. Cô không thể dời mắt đi chỗ khác được nữa."
  },
  AvgDialog_60842_Content_24 = {
    Text = "Cửa…cửa mang vạn vật…ngôi nhà của thần minh…"
  },
  AvgDialog_60842_Content_25 = {
    Text = "Cuối cùng cũng đã đến ngày này!"
  },
  AvgDialog_60842_Content_26 = {
    Text = "Không, không thể để cửa mở…"
  },
  AvgDialog_60842_Content_27 = {
    Text = "Bạn muốn làm gì? Bạn nỗ lực thúc đẩy chìa khóa bạc, nhưng sức mạnh tinh thần của bạn lúc này bị đè nén chặt chẽ, chìa khóa bạc không có chút phản ứng nào."
  },
  AvgDialog_60842_Content_29 = {
    Text = "Bạn nhìn chằm chằm vào cánh cửa đó trong tuyệt vọng. Từ mờ ảo đến rõ ràng, nó mở ra một khe hở."
  },
  AvgDialog_60842_Content_3 = {
    Text = "Cơn rung động mạnh mẽ khiến nước trong hồ đen dao động dữ dội, gây ra những đợt sóng lớn vỗ vào người bạn."
  },
  AvgDialog_60842_Content_30 = {
    Text = "Lực lượng mạnh mẽ đó, giống như dòng lũ sắp nhấn chìm thế giới, từ trong cánh cửa tràn ra hướng tới tượng sinh đôi Đèn."
  },
  AvgDialog_60842_Content_31 = {
    Text = "Yu Li-ét mở to đôi mắt nhìn vào cửa và tượng thần, nụ cười trên khuôn mặt trở nên càng thêm độc ác và méo mó."
  },
  AvgDialog_60842_Content_32 = {
    Text = "Lực lượng, là lực lượng bên trong… Tượng Thần Song Sinh, sắp hoàn thành sự hợp nhất."
  },
  AvgDialog_60842_Content_33 = {
    Text = "Misaque… Người Giữ Gìn… cùng với thế giới tội lỗi này, hãy đón nhận sự thanh tẩy cuối cùng!"
  },
  AvgDialog_60842_Content_34 = {Text = "Ding——"},
  AvgDialog_60842_Content_35 = {
    Text = "Sonata, bắt đầu"
  },
  AvgDialog_60842_Content_36 = {Text = "!!!"},
  AvgDialog_60842_Content_37 = {
    Text = "Như thể hàng vạn nhạc công cùng lúc tấu lên nhạc cụ, đàn dây, kèn, trống, những âm thanh khác nhau đan xen, hòa quyện, trở thành một dòng sông mạnh mẽ và cuồn cuộn."
  },
  AvgDialog_60842_Content_38 = {
    Text = "Dòng sông cuồn cuộn, đột nhiên lao về phía mối liên kết mỏng manh giữa cửa và tượng thần song sinh."
  },
  AvgDialog_60842_Content_39 = {Text = "Ho——"},
  AvgDialog_60842_Content_4 = {
    Text = "Hồ đen đang rung chuyển. Mái vòm cũng vậy. Dường như cả Misaque và toàn bộ lục địa đều run rẩy trong lời tụng đọc của Yu Li-ét."
  },
  AvgDialog_60842_Content_40 = {
    Text = "Một ngụm máu tươi từ miệng Hamlin phun ra, nhuộm đỏ vạt áo và cây chỉ huy của ông."
  },
  AvgDialog_60842_Content_41 = {
    Text = "Tiếng nhạc và lực lượng của cánh cửa va chạm, lực va đập mạnh mẽ khiến thân thể của Hamlin khó có thể chịu đựng."
  },
  AvgDialog_60842_Content_42 = {
    Text = "Nhạc trưởng luôn chăm chút bản thân một cách kỹ lưỡng không hề bận tâm đến vẻ bối rối lúc này, ông tập trung nhìn vào cánh cửa, động tác vung cây chỉ huy không chút do dự."
  },
  AvgDialog_60842_Content_43 = {
    Text = "Dòng chảy âm nhạc, không ngừng đổ về phía bức tường kiên cố."
  },
  AvgDialog_60842_Content_44 = {
    Text = "Rầm——"
  },
  AvgDialog_60842_Content_45 = {
    Text = "Đôi tượng rung chuyển dữ dội. Dưới sự tấn công của dòng nhạc, vào thời điểm quan trọng và mong manh nhất khi đôi tượng thần đang thành hình, mối nối giữa cánh cửa và tượng thần xuất hiện một khe hở nhỏ."
  },
  AvgDialog_60842_Content_46 = {
    Text = "Khí tức nguy hiểm từ tượng thần rõ ràng trở nên mờ nhạt dần. Tượng đá đang di chuyển về trung tâm đã dừng lại."
  },
  AvgDialog_60842_Content_47 = {
    Text = "Đó là gương mặt thân thương, từ bóng tối bước ra, đứng lại bên cạnh bạn."
  },
  AvgDialog_60842_Content_48 = {
    Text = "Thời cơ đã đến. Vở diễn cuối cùng, sắp bắt đầu."
  },
  AvgDialog_60842_Content_49 = {
    Text = "Anh ấy nhẹ nhàng vung cây chỉ huy. Một giai điệu dịu dàng truyền vào thế giới tinh thần của bạn."
  },
  AvgDialog_60842_Content_5 = {
    Text = "Trong cơn rung chuyển trời đất này, bạn ngẩng đầu lên, nhìn vào sáng tạo ngày càng ấn tượng trước mắt."
  },
  AvgDialog_60842_Content_50 = {
    Text = "Những gánh nặng và đau khổ đột nhiên biến mất, bạn lại được tắm trong suối nước nóng, trong đầu tràn ngập lực lượng tinh thần mạnh mẽ hơn trước."
  },
  AvgDialog_60842_Content_51 = {
    Text = "Bạn… bạn không phá hủy liên kết tinh thần của tôi?"
  },
  AvgDialog_60842_Content_52 = {
    Text = "Trước đó, khả năng liên kết của bạn đã bị tạm ngắt. Đây là một thủ đoạn để làm Yu Li-ét phân tâm."
  },
  AvgDialog_60842_Content_53 = {
    Text = "Hạn chế của bạn đã được gỡ bỏ. Bây giờ, cánh cửa đã mở, mọi thứ đã sẵn sàng."
  },
  AvgDialog_60842_Content_54 = {
    Text = "Anh ta đứng trước mặt bạn, trong đôi mắt tĩnh lặng, bùng cháy ngọn lửa cuồng nhiệt."
  },
  AvgDialog_60842_Content_55 = {
    Text = "Anh ta đặt gậy chỉ huy sau lưng và cúi người chào bạn."
  },
  AvgDialog_60842_Content_56 = {
    Text = "Mắt không có tròng, người thực thi ý chí vô thượng. Người chỉ huy Hamlin, sẵn sàng phục vụ ngài."
  },
  AvgDialog_60842_Content_57 = {
    Text = "Tôi sẽ hỗ trợ bạn, lấy lại quyền bính thuộc về bạn."
  },
  AvgDialog_60842_Content_58 = {
    Text = "Bạn… bạn biết…"
  },
  AvgDialog_60842_Content_59 = {
    Text = "Sự đến của ý chí vô thượng không thể tránh khỏi, chỉ bạn mới có thể chống lại."
  },
  AvgDialog_60842_Content_6 = {
    Text = "Song sinh... tượng thần.."
  },
  AvgDialog_60842_Content_60 = {
    Text = "Khi Song Tử xuất hiện, cánh cửa mở ra, bạn mới có thể nhận lại khả năng đối kháng với Ngài."
  },
  AvgDialog_60842_Content_61 = {
    Text = "Việc cấp bách phải xử lý linh hoạt, mong bạn tha thứ cho sự bất lịch sự của tôi trước đây."
  },
  AvgDialog_60842_Content_62 = {
    Text = "Hamlin! Bạn… bạn đang làm gì vậy?!!"
  },
  AvgDialog_60842_Content_63 = {
    Text = "Làm những gì tôi nên làm."
  },
  AvgDialog_60842_Content_64 = {
    Text = "Tượng đá bị phá hủy khi tượng đá yếu đuối nhất, thần minh của bạn sẽ khó có thể nghe thấy lời cầu nguyện của bạn nữa."
  },
  AvgDialog_60842_Content_65 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} chỉ là một mảnh vỡ! Chỉ có theo cách của tôi, mới có thể khiến ý chí tối cao thực sự tỉnh lại……"
  },
  AvgDialog_60842_Content_66 = {
    Text = "Bạn không muốn lắng nghe âm nhạc tối cao từ ý chí vô thượng sao? Hamlin, bạn đã phản bội những gì bạn tín ngưỡng!"
  },
  AvgDialog_60842_Content_67 = {
    Text = "Thần minh không nhất định phải vĩ đại hơn các phân mảnh của mình. Điều này cũng không phải là điều tôi quan tâm, bà Yu Lie-et."
  },
  AvgDialog_60842_Content_68 = {
    Text = "Tôi cũng từng nghĩ rằng, bản an hồn ca của ý chí vô thượng là âm thanh vĩ đại nhất trong vũ trụ này, sau đó tôi đã hiểu. Nghệ thuật cao cả nhất vượt lên chính nó."
  },
  AvgDialog_60842_Content_69 = {
    Text = "Anh ta ngẩng đầu lên, đôi mắt bùng cháy dữ dội, lặng lẽ nhìn Yu Li-ét."
  },
  AvgDialog_60842_Content_7 = {
    Text = "Hai pho tượng đá hình người màu trắng từ từ nổi lên từ hồ đen, khiến cả hồ đen rung động."
  },
  AvgDialog_60842_Content_70 = {
    Text = "Nó sẽ vang lên trong cuộc đấu tranh——cuộc đối đầu giữa loài người và thần minh. Cuộc đối đầu giữa phân mảnh và bản nguyên."
  },
  AvgDialog_60842_Content_71 = {
    Text = "Đối kháng với ý chí vô thượng, hòa tấu cùng ý chí vô thượng… Đây sẽ là bản nhạc cao cả vượt xa cả phần an hồn của ý chí vô thượng!"
  },
  AvgDialog_60842_Content_72 = {
    Text = "Bạn là từ khi nào……"
  },
  AvgDialog_60842_Content_73 = {
    Text = "Mùa xuân của Akutê, chúng ta đã chứng kiến vụ nổ đó."
  },
  AvgDialog_60842_Content_74 = {
    Text = "Vào ngày đó, tôi đã nghe thấy nó… âm thanh mà tôi luôn tìm kiếm, hơn cả sự vĩnh cửu của bài ca an hồn."
  },
  AvgDialog_60842_Content_75 = {
    Text = "Lúc đó tôi chỉ nghe được phần dạo đầu của nó. Hôm nay, nó sẽ vang vọng khắp thế giới này."
  },
  AvgDialog_60842_Content_76 = {
    Text = "Giọng nói bình tĩnh của Hamlin không thể kiềm chế được rung rẩy."
  },
  AvgDialog_60842_Content_77 = {
    Text = "Vậy, từ ngày đó, anh đã bắt đầu lên kế hoạch bội phản……"
  },
  AvgDialog_60842_Content_78 = {
    Text = "Thần minh đã quên mất âm nhạc của Người. Người chỉ là một khối hỗn loạn vô thức, một thảm họa kinh hoàng."
  },
  AvgDialog_60842_Content_79 = {
    Text = "Tất cả vẻ đẹp của Ngài, tất cả chân lý của Ngài, đều nằm trong các phân mảnh của Ngài."
  },
  AvgDialog_60842_Content_8 = {
    Text = "Trong khe hở giữa các tượng đá, thân thể của Ramona bị cuốn vào và bọc kín bởi lớp vỏ của Tà Vy."
  },
  AvgDialog_60842_Content_80 = {
    Text = "Tôi trung thành với âm nhạc, trung thành với cái đẹp và sự thật. Tôi chưa bao giờ bội phản, Dư Lị Êt."
  },
  AvgDialog_60842_Content_81 = {
    Text = "Hành động của bạn không thể được tha thứ"
  },
  AvgDialog_60842_Content_82 = {
    Text = "Tại sao… nếu bạn đã giúp tôi từ đầu, Ramona sẽ không…"
  },
  AvgDialog_60842_Content_83 = {
    Text = "Hamlin, tôi không thể tha thứ cho những hành động của bạn."
  },
  AvgDialog_60842_Content_84 = {
    Text = "Tại sao phải làm như vậy?"
  },
  AvgDialog_60842_Content_85 = {
    Text = "Tại sao… nếu bạn đã giúp tôi từ đầu, Ramona sẽ không…"
  },
  AvgDialog_60842_Content_86 = {
    Text = "Anh ta lặng lẽ nhìn vào Yu Li-ét, pho tượng khổng lồ, và cánh cửa phía sau pho tượng."
  },
  AvgDialog_60842_Content_87 = {
    Text = "Anh ấy đứng bên cạnh cậu."
  },
  AvgDialog_60842_Content_88 = {
    Text = "Người giữ bí mật {Male=ngài,Female=cô}, chặn đứng Yu Li-ét, chỉ có thể làm chậm sự đến của ý chí vô thượng. Cái chết kéo dài không mang lại ý nghĩa gì."
  },
  AvgDialog_60842_Content_89 = {
    Text = "Để Yuli-ét triệu hồi cánh cửa, giúp bạn thu hồi quyền hạn một cách suôn sẻ, là con đường duy nhất."
  },
  AvgDialog_60842_Content_9 = {
    Text = "Hai xác không chủ liên tục biến đổi, hòa quyện, trở thành một tượng điêu khắc khổng lồ hai màu đen trắng, lơ lửng giữa những pho tượng đá nửa thân khổng lồ."
  },
  AvgDialog_60842_Content_90 = {
    Text = "Điều chúng ta theo đuổi khác nhau, nhưng dù là âm thanh tối cao hay sự trường tồn của thế giới, cơ hội chỉ có một lần."
  },
  AvgDialog_60842_Content_91 = {
    Text = "Trong cuộc biểu diễn không thể tránh khỏi này, bạn, tôi, Ramona và tất cả mọi người ở đây, đều chỉ là những nghệ sĩ chơi nhạc."
  },
  AvgDialog_60842_Content_92 = {
    Text = "Tôi không mong cầu sự thấu hiểu và tha thứ của bạn, tôi chịu trách nhiệm cho mỗi nốt nhạc của mình."
  },
  AvgDialog_60842_Content_93 = {
    Text = "Trước đó, tôi sẽ cùng bạn ngăn cản Yu Li-ét và cứu lấy Ramona."
  },
  AvgDialog_60842_Content_94 = {
    Text = "Bạn biết đấy, Hamlin nói đúng. Để thế giới tiếp tục tồn tại, Ramona không bao giờ ngại hy sinh bản thân. \nNhưng bạn thì không muốn như vậy."
  },
  AvgDialog_60842_Content_95 = {
    Text = "Cảm nhận sức mạnh tinh thần trong cơ thể ngày càng dâng trào, bạn từ từ ngước lên, hướng ánh mắt về phía bức tượng thần vĩ đại kia."
  },
  AvgDialog_60842_Content_96 = {
    Text = "Ai cũng không được tiếp cận Người... tín đồ của ta, \"chó\" của ta, chặn họ lại!"
  },
  AvgDialog_60886_Content_1 = {
    Text = "Đây cũng là một lựa chọn, một diễn biến của câu chuyện."
  },
  AvgDialog_60886_Content_10 = {
    Text = "Một diễn viên tận tụy. Mười chín năm đóng vai cùng một nhân vật, không hề lơi là vì sự chuyển biến tuyệt vời của cốt truyện."
  },
  AvgDialog_60886_Content_11 = {
    Text = "Bây giờ.."
  },
  AvgDialog_60886_Content_12 = {
    Text = "Khán giả thân yêu của tôi, hãy dành cho tôi những tràng pháo tay nồng nhiệt nhất."
  },
  AvgDialog_60886_Content_13 = {
    Text = "Sương mù đen bao quanh, giống như sự tán dương."
  },
  AvgDialog_60886_Content_14 = {
    Text = "Xuất hiện trước mặt bạn là một khuôn mặt mà bạn từng thấy, mang đến cho bạn vô số cơn ác mộng!"
  },
  AvgDialog_60886_Content_15 = {
    Text = "Trên khuôn mặt không có ngũ quan, cái miệng mang theo nụ cười kia mở rộng hết cỡ, tham lam tận hưởng sự bàng hoàng và khiếp đảm của bạn."
  },
  AvgDialog_60886_Content_16 = {
    Text = "Bạn là……N!"
  },
  AvgDialog_60886_Content_17 = {
    Text = "Một danh hiệu, đối với muôn vàn hóa thân của tôi, đây là một sự sỉ nhục… nhưng tùy bạn gọi thế nào."
  },
  AvgDialog_60886_Content_18 = {
    Text = "Bạn đã làm gì với Giáo sư Dexter!"
