  AvgDialog_60886_Content_19 = {
    Text = "Giáo sư Dexter? Ai là giáo sư Dexter?"
  },
  AvgDialog_60886_Content_2 = {
    Text = "Nếu thật sự cứu được cô ấy ra, câu chuyện này há chẳng thiếu đi một vở kịch hay để xem?"
  },
  AvgDialog_60886_Content_20 = {
    Text = "Người giữ bí mật, bạn và Ramona… các bạn thực sự biết Dexter?"
