  AvgDialog_60886_Content_21 = {
    Text = "Bạn có ý gì…… chúng ta làm sao có thể…… hay là?!"
  },
  AvgDialog_60886_Content_22 = {
    Text = "Bạn nhớ lời của N. Trong mười chín năm, anh ấy vẫn luôn đóng vai trò đó……"
  },
  AvgDialog_60886_Content_23 = {
    Text = "Còng kinh co lại mạnh mẽ. Bạn đột ngột ngẩng đầu lên, nhìn vào khuôn mặt vô cảm của N."
  },
  AvgDialog_60886_Content_24 = {
    Text = "Xuất sắc, Người Giữ Gìn. Chính là biểu cảm này!"
  },
  AvgDialog_60886_Content_25 = {
    Text = "Đừng cử động, giữ nguyên. Đúng rồi, chính là như vậy… để tôi nhớ kỹ dáng vẻ của bạn bây giờ…"
  },
  AvgDialog_60886_Content_26 = {
    Text = "Thật đáng tiếc, khi Ramona biết được chuyện này, cô ấy vẫn chưa tỉnh lại, tôi không thể nhìn thấy biểu cảm của cô ấy."
  },
  AvgDialog_60886_Content_27 = {
    Text = "Tôi nghĩ, thần sắc của cô ấy, có lẽ cũng ấn tượng như của bạn."
  },
  AvgDialog_60886_Content_28 = {
    Text = "Thân thể của N run rẩy nhẹ, dường như đang nhẫn nại cười không thể kiềm chế."
  },
  AvgDialog_60886_Content_29 = {
    Text = "Anh ta cúi người, ghé sát trước mặt bạn, chăm chú quan sát."
  },
  AvgDialog_60886_Content_3 = {
