  AvgDialog_60886_Content_49 = {
    Text = "Anh ta đã chết trong lúc ôm cô bé. Khi hấp hối, anh ta vẫn luôn lẩm bẩm những lời như \"cha sẽ bảo vệ cô bé tốt\" và những điều tương tự như vậy…"
  },
  AvgDialog_60886_Content_5 = {
    Text = "Giáo sư Dexter tuyệt đối không bao giờ nói những lời như vậy…… rốt cuộc anh là ai!?"
  },
  AvgDialog_60886_Content_50 = {
    Text = "Kẻ phản bội trong nhóm Misaque… là bạn?"
  },
  AvgDialog_60886_Content_51 = {
    Text = "Nhìn vào đôi mắt đầy nghi hoặc, tức giận của bạn, An vô tư nhún vai."
  },
  AvgDialog_60886_Content_52 = {
    Text = "Là tôi, không phải tôi, có đáng để bận tâm không? Thật khó tin là đến bây giờ bạn vẫn còn tâm trạng để nghĩ về những điều này."
  },
  AvgDialog_60886_Content_53 = {
    Text = "Đóng vai Dexter, có thể ở gần Misaque, mang lại sự thuận tiện."
