  AvgDialog_60886_Content_57 = {
    Text = "Anh ta nhìn bạn, liếm môi, giống như một đứa trẻ vô tội, đang nhìn vào một đồ chơi sắp bị phá hủy."
  },
  AvgDialog_60886_Content_58 = {
    Text = "Thái Di Sơ đã tặng hạt giống của cô ấy cho bạn, cô ấy lại tin rằng bạn có thể mang cô ấy sống sót… Ha, người phụ nữ điên thật."
  },
  AvgDialog_60886_Content_59 = {
    Text = "Thật đáng tiếc, cô ấy đã tin nhầm người. Quyền hạn sinh sản, tôi sẽ giữ lấy nó."
  },
  AvgDialog_60886_Content_6 = {
    Text = "Anh ấy đến trước mặt bạn, đôi mắt quen thuộc mang theo nụ cười mang vẻ xa cách nhìn bạn."
  },
  AvgDialog_60886_Content_60 = {
    Text = "Hãy để ta xem, khi hy vọng cháy bỏng bị tước mất, trên khuôn mặt ngươi sẽ hiện lên vẻ mặt như thế nào?"
  },
  AvgDialog_60886_Content_7 = {
    Text = "Một làn khói đen từ người hắn bốc lên, từ từ bao phủ hắn."
