  },
  AvgDialog_60887_Content_12 = {Text = "!!!"},
  AvgDialog_60887_Content_13 = {
    Text = "Đây… Đây là…"
  },
  AvgDialog_60887_Content_14 = {
    Text = "Cất chìa khóa bạc của bạn đi. Nếu sử dụng nó ngay bây giờ, bạn sẽ chết."
  },
  AvgDialog_60887_Content_15 = {
    Text = "Nhịp điệu. Giai điệu. Hòa âm mềm mại của dây đàn tràn ngập tâm trí các bạn."
