  AvgDialog_60887_Content_25 = {
    Text = "Tôi sẽ đưa bạn đến một nơi an toàn."
  },
  AvgDialog_60887_Content_26 = {
    Text = "Anh ta quay người, gật đầu nhẹ với bạn, biểu cảm bình thản như mặt nước cổ giếng."
  },
  AvgDialog_60887_Content_27 = {
    Text = "Nhạc trưởng Hamlin, sẵn sàng phục vụ quý vị."
  },
  AvgDialog_60887_Content_3 = {
    Text = "Bạn giơ tay lên."
  },
  AvgDialog_60887_Content_4 = {
    Text = "Tôi sẽ không để các người.."
  },
  AvgDialog_60887_Content_5 = {
    Text = "Chương thứ hai, bắt đầu!"
  },
  AvgDialog_60887_Content_6 = {Text = "Ừ——"},
  AvgDialog_60887_Content_7 = {Text = "?!!!"},
  AvgDialog_60887_Content_8 = {
    Text = "Chưa đợi chìa khóa bạc trong tay bạn phát ra ánh sáng chói lọi làm tổn thương bạn và kẻ địch, một giọng nói thanh thoát và lạnh giá vang lên từ phía sau bạn."
  },
  AvgDialog_60887_Content_9 = {
    Text = "Giọng nói đó là quỹ đạo mà nhạc trưởng vạch ra, là mệnh lệnh không thể vi phạm trong thế giới của các nốt nhạc."
  },
  AvgDialog_60888_Content_1 = {
    Text = "Chuyện lớn……xảy ra rồi……"
  },
  AvgDialog_60888_Content_10 = {
    Text = "Một phút mười lăm giây, tiếng vỗ tay của khán giả sẽ như sấm động, kéo dài không dứt, rồi dần tan biến."
  },
  AvgDialog_60888_Content_11 = {
    Text = "Hai mươi lăm phút, ban nhạc và khán giả sẽ rời đi."
  },
  AvgDialog_60888_Content_12 = {
    Text = "Thời gian không chênh lệch một chút nào so với dự kiến, giống như một buổi biểu diễn chính xác một lần nữa."
  },
  AvgDialog_60888_Content_13 = {
    Text = "Nhạc trưởng gật đầu hài lòng, cúi người chào khán giả trong khán phòng trống vắng lặng."
  },
  AvgDialog_60888_Content_15 = {
    Text = "Trong góc khuất bên cạnh khán đài, một tràng vỗ tay nhẹ nhàng vang lên một lần nữa."
  },
  AvgDialog_60888_Content_16 = {
    Text = "Một buổi biểu diễn vĩ đại, thưa ông Hamlin."
  },
  AvgDialog_60888_Content_17 = {
    Text = "Có lẽ được xem là hoàn chỉnh, nhưng vẫn chưa xứng đáng gọi là vĩ đại. Sự biểu diễn thực sự vĩ đại nằm ngoài rạp hát."
  },
  AvgDialog_60888_Content_18 = {
    Text = "Nhạc trưởng cất cây đũa chỉ huy, cau mày nhìn về phía người phụ nữ ở bên hông khán đài."
  },
  AvgDialog_60888_Content_19 = {
    Text = "Chúng tôi đã nói trước rồi, thưa bà Yu Li-ét, bà không nên xuất hiện trong nhà hát."
  },
  AvgDialog_60888_Content_2 = {
    Text = "Phải nhanh chóng thông báo cho mọi người… và Người Giữ Gìn!"
  },
  AvgDialog_60888_Content_20 = {
    Text = "Sự hợp tác của chúng tôi không liên quan đến buổi biểu diễn, tôi không muốn buổi biểu diễn của mình bị làm phiền. Tôi nghĩ bạn hiểu điều này ."
  },
  AvgDialog_60888_Content_21 = {
    Text = "Ngoài ra, nếu bạn xuất hiện ở đây với tư cách này, sẽ gây ra những rắc rối không đáng có."
  },
  AvgDialog_60888_Content_22 = {
    Text = "Tất nhiên, ông Hamlin. Chỉ là, nếu không đến tận nơi để nghe buổi biểu diễn của ông, tôi sẽ rất đáng tiếc."
  },
  AvgDialog_60888_Content_23 = {
    Text = "Yu Li-ét mỉm cười gật đầu chào, nhẹ nhàng chỉnh lại nếp nhăn trên vạt áo của mình."
  },
  AvgDialog_60888_Content_24 = {
    Text = "Đối với cách diễn đạt của Hamlin, cô ấy đã quen thuộc và không bận tâm."
  },
  AvgDialog_60888_Content_25 = {
    Text = "Ngoài ra, tôi cũng có việc quan trọng cần phải thông báo với bạn trực tiếp."
  },
  AvgDialog_60888_Content_26 = {
    Text = "Hành động đã bắt đầu?"
  },
  AvgDialog_60888_Content_27 = {
    Text = "Khá tốt. Clementine đã xử lý thành công những tên tuần tra của Misaque. Chúng ta đã giành được nhiều thời gian hơn so với dự kiến."
  },
  AvgDialog_60888_Content_28 = {
    Text = "Kế hoạch của bạn rất thành công!"
  },
  AvgDialog_60888_Content_29 = {
    Text = "Chỉ là một đoạn dạo đầu khá đơn giản, nói là đã thành công thì vẫn còn quá sớm."
  },
  AvgDialog_60888_Content_30 = {
    Text = "Tôi tin vào sự khôn ngoan của ông, thưa Ngài Chỉ huy."
  },
  AvgDialog_60888_Content_31 = {
    Text = "Hôm nay, chúng ta đã chờ bao lâu rồi?"
  },
  AvgDialog_60888_Content_32 = {
    Text = "Mười chín năm."
  },
  AvgDialog_60888_Content_33 = {
    Text = "Đúng, mười chín năm. Một khoảng thời gian dài."
  },
  AvgDialog_60888_Content_34 = {
    Text = "Hiệp hội Điêu khắc gia và trò chơi của những người dấn thân vào biển đã thu hút đủ sự chú ý cho chúng tôi, chúng tôi đã ẩn mình rất tốt."
  },
  AvgDialog_60888_Content_35 = {
    Text = "Kế hoạch của Lemvahi đã thất bại, thật đáng tiếc, nhưng không có gì đáng lo ngại."
  },
  AvgDialog_60888_Content_36 = {
    Text = "Điều thực sự quan trọng, chỉ có hôm nay —— mười chín năm sau hôm nay."
  },
  AvgDialog_60888_Content_37 = {
    Text = "Việc có thể chứng kiến thời khắc quan trọng này cùng với một người hợp tác như bạn là một niềm vui lớn."
  },
  AvgDialog_60888_Content_38 = {
    Text = "Chúng ta có cùng mục đích. Buổi biểu diễn này không phải dành cho chúng ta."
  },
  AvgDialog_60888_Content_39 = {
    Text = "Để lại được nghe âm thanh mà vị tồn tại vĩ đại kia mang đến, mọi sự hy sinh đều trở nên không đáng kể."
  },
  AvgDialog_60888_Content_4 = {
    Text = "Cây đũa chỉ huy của người chỉ huy vẽ nên một đường cong du dương trong không khí. Bản nhạc đang bước vào giai đoạn kết thúc."
  },
  AvgDialog_60888_Content_40 = {
    Text = "Quay lại, đứng nghiêm. Người chỉ huy trẻ tuổi nâng hai tay lên, chào rạp hát vắng lặng và hướng về nơi sâu thẳm của dải Ngân hà mà không ai biết tới."
  },
  AvgDialog_60888_Content_41 = {
    Text = "Mọi thứ đã sẵn sàng, hãy bắt đầu hành trình thôi, bà Yu Li-ét."
  },
  AvgDialog_60888_Content_42 = {
    Text = "Buổi biểu diễn chính thức bắt đầu rồi."
  },
  AvgDialog_60888_Content_5 = {
    Text = "Những hợp âm mạnh mẽ cùng với bè âm phức tạp đã tạo nên một khung cảnh âm thanh đầy cảm xúc mạnh mẽ, giờ đây đã dần lắng xuống."
  },
  AvgDialog_60888_Content_6 = {
    Text = "Những arpeggio của sáo và đàn tranh từ từ bay ra, như ánh hoàng hôn đang chiếu sáng lên những đám mây."
  },
  AvgDialog_60888_Content_7 = {
    Text = "Hòa âm êm dịu dần tan trong không khí, nốt lặng cuối cùng của dây đàn mang nốt nhạc vào hồi kết."
  },
  AvgDialog_60888_Content_8 = {
    Text = "Trong khoảnh khắc xa xôi này, người chỉ huy đã cất đi cây chỉ huy. Ông im lặng định hình."
  },
  AvgDialog_60888_Content_9 = {
    Text = "Mười giây, khán giả say đắm trong âm nhạc, nhà hát sẽ chìm vào sự yên tĩnh như buổi sớm mai."
  },
  AvgDialog_60889_Content_1 = {
    Text = "Dãy hành lang dài hẹp không thấy bóng người nào. Một tiếng thở nặng nề và tiếng bước chân vang lên, vọng lại trong hành lang."
  },
  AvgDialog_60889_Content_10 = {
    Text = "Không cần nói vậy, hiệu trưởng."
  },
  AvgDialog_60889_Content_11 = {
    Text = "Đợi đưa các bạn vào tòa nhà Khoa Sức sống, chúng tôi có thể……"
  },
  AvgDialog_60889_Content_12 = {
    Text = "Có cần tôi tiễn các cô một đoạn không, cô Ramona?"
  },
  AvgDialog_60889_Content_13 = {Text = "!!!"},
  AvgDialog_60889_Content_14 = {
    Text = "Cẩn thận!"
  },
  AvgDialog_60889_Content_15 = {
    Text = "Ramona nhanh chóng giơ kiếm chắn ngang trước người."
  },
  AvgDialog_60889_Content_16 = {
    Text = "Ở sau lưng cô, Sylva cau mày lại, bảo vệ Khổ Lệ Đặc đang yếu đuối."
  },
  AvgDialog_60889_Content_17 = {
    Text = "Một tiếng bước chân gấp gáp vang lên, dường như đã mai phục ở đây trong một thời gian dài."
  },
  AvgDialog_60889_Content_18 = {
    Text = "Hai đầu con hẻm hẹp, điệp viên trong đồng phục của hội nghị thẩm tra đứng chen chúc chặn đường họ."
  },
  AvgDialog_60889_Content_19 = {
    Text = "Người đàn ông một mắt vừa bước tới trước đám đông, vừa nhẹ nhàng trêu đùa con mèo kỳ dị trên vai – một con mèo không lông bị khâu ghép hai đầu."
  },
  AvgDialog_60889_Content_2 = {
    Text = "Hô… Giám đốc Học viện Kherat, xin hãy cố gắng thêm một chút, chúng ta sắp đến rồi."
  },
  AvgDialog_60889_Content_20 = {
    Text = "Phải…… là ngươi……"
  },
  AvgDialog_60889_Content_21 = {
    Text = "Thấy khuôn mặt xuất hiện trước mắt, cơ thể của Khổ Lệ Đặc lập tức cứng đờ."
  },
  AvgDialog_60889_Content_22 = {
    Text = "Herbert... tên khốn kiếp này.."
  },
  AvgDialog_60889_Content_23 = {
    Text = "Thầy Crowley đối xử với em như con của mình, vậy mà em lại làm những chuyện như thế với ông ấy. Còn mặt mũi nào quay về…"
  },
  AvgDialog_60889_Content_24 = {
    Text = "Học sinh Khổ Lệ Đặc… à không, phải gọi là Giám đốc Học viện Kherat."
  },
  AvgDialog_60889_Content_25 = {
    Text = "Sau khi tôi rời đi, vị trí hiệu trưởng chắc chắn thuộc về bạn."
  },
  AvgDialog_60889_Content_26 = {
    Text = "Tôi rất muốn cùng bạn ôn lại những kỷ niệm đẹp thời học sinh, nhưng hôm nay tôi đến đây còn có việc quan trọng khác cần làm."
  },
  AvgDialog_60889_Content_27 = {
    Text = "Ánh mắt anh hướng về phía Ramona."
  },
  AvgDialog_60889_Content_28 = {
    Text = "Lâu không gặp, rất nhớ chị Ramona."
  },
  AvgDialog_60889_Content_29 = {
    Text = "Nhưng chỉ gặp vài lần trong khoảng thời gian này, không cần quá thân mật."
  },
  AvgDialog_60889_Content_3 = {
    Text = "Ramona, vết thương của cậu……"
  },
  AvgDialog_60889_Content_30 = {
    Text = "Đoạn thời gian này? Không, không."
  },
  AvgDialog_60889_Content_31 = {
    Text = "Tôi vẫn còn nhớ lần đầu tiên gặp bạn, có lẽ là trong hành lang này."
  },
  AvgDialog_60889_Content_32 = {
    Text = "Lúc đó bạn chỉ… lớn đến vậy thôi…"
  },
  AvgDialog_60889_Content_33 = {
    Text = "Herbert đưa hai tay ra, làm động tác mô phỏng chiều dài của một con mèo không lông."
  },
  AvgDialog_60889_Content_34 = {
    Text = "Bạn là... có ý gì vậy?"
  },
  AvgDialog_60889_Content_35 = {
    Text = "Con đẻ của tôi. Đứa trẻ của tôi."
  },
  AvgDialog_60889_Content_36 = {
    Text = "Hiro là kết quả không thành công. Trong sự hợp tác giữa tôi và Hội Giáo đèn lồng, bạn là kết tinh hoàn hảo nhất."
  },
  AvgDialog_60889_Content_37 = {
    Text = "Tôi không hiểu.."
  },
  AvgDialog_60889_Content_38 = {
    Text = "Bạn còn chưa hiểu sao, Ramona?"
  },
  AvgDialog_60889_Content_39 = {
    Text = "Những người mà bạn quan tâm, hoảng sợ, bị thương, đối mặt với nguy cơ mất kiểm soát và cái chết… Tất cả những thảm họa mà Misaque phải chịu đựng, đều là vì bạn."
  },
  AvgDialog_60889_Content_4 = {
    Text = "Cô lấy ra chiếc khăn tay, lau sạch máu trên cánh tay của RAMONA."
  },
  AvgDialog_60889_Content_40 = {
    Text = "Bạn…… nói gì?"
  },
  AvgDialog_60889_Content_41 = {
    Text = "Nhìn thấy thanh kiếm run rẩy trong tay Ramona, Herbert mỉm cười bước về phía trước hai bước."
  },
  AvgDialog_60889_Content_42 = {
    Text = "Nhiều năm trước, tên trộm Dexter đã giật bạn đi từ chúng tôi."
  },
  AvgDialog_60889_Content_43 = {
    Text = "Ngày đó đến muộn hơn nhiều, nhưng không sao cả —— nó đến đúng lúc."
  },
  AvgDialog_60889_Content_44 = {
    Text = "Bạn là bảo vật song sinh, là sáng tạo hoàn hảo của đèn dẫn đường."
  },
  AvgDialog_60889_Content_5 = {
    Text = "À……xin lỗi."
  },
  AvgDialog_60889_Content_6 = {
    Text = "Vừa rồi khi chiến đấu với những người trong hội nghị thẩm tra, tôi đã bị phân tâm một lúc…"
  },
  AvgDialog_60889_Content_7 = {
    Text = "Sự hỗn loạn của hồ đen vẫn ảnh hưởng đến bạn, phải không?"
  },
  AvgDialog_60889_Content_8 = {
    Text = "Một chút thôi."
  },
  AvgDialog_60889_Content_9 = {
    Text = "Ramona, đã gây rắc rối cho các người. Nếu không bị thương, có lẽ tôi còn có thể giúp bạn chia sẻ một chút .."
  },
  AvgDialog_60890_Content_1 = {
    Text = "Bạn đang ở trong cơn bão."
  },
  AvgDialog_60890_Content_10 = {
    Text = "Tiếng kêu sắc nhọn vang vọng khắp hồ đen. Quyền năng trí tuệ trong cơ thể rung động theo tiếng kêu."
  },
  AvgDialog_60890_Content_11 = {
    Text = "Vô số hình bóng trắng, từ các chiều không gian và thời gian khác nhau được bắt giữ, tụ hội vào bức tượng đen trắng kia."
  },
  AvgDialog_60890_Content_12 = {
    Text = "Rất nhanh, những tiếng hí và rung động đều biến mất."
  },
  AvgDialog_60890_Content_13 = {
    Text = "Không ai có thể trốn tránh Ngài, Đà Vy."
  },
  AvgDialog_60890_Content_14 = {
    Text = "Đến đây, hãy cùng nhau chào đón sự giáng sinh của Người!"
  },
  AvgDialog_60890_Content_15 = {
    Text = "Khi động tác của Yu Li-ét dừng lại, hai tượng đèn lớn bắt đầu di chuyển về phía giữa. Chúng như những hình bóng đang khao khát linh hồn, vội vã hòa vào bức tượng đen trắng ở trung tâm."
  },
  AvgDialog_60890_Content_16 = {
    Text = "Tà Vy! Ramona!! À——"
  },
  AvgDialog_60890_Content_17 = {
    Text = "Một tia sáng mạnh mẽ đột nhiên bùng lên. Đằng sau hai sáng tạo khổng lồ, xuất hiện một khe hở."
  },
  AvgDialog_60890_Content_18 = {
    Text = "Bạn từ từ bỏ tay đang che mắt ra."
  },
  AvgDialog_60890_Content_19 = {
    Text = "Đó là…… cửa?"
  },
  AvgDialog_60890_Content_2 = {
    Text = "Cơn rung động mạnh mẽ khiến nước trong hồ đen dao động dữ dội, gây ra những đợt sóng lớn vỗ vào người bạn."
  },
  AvgDialog_60890_Content_20 = {
    Text = "Cánh cửa ảo phía sau Tà Vy vào thời điểm này đã trở thành hiện thực."
  },
  AvgDialog_60890_Content_21 = {
    Text = "Ánh sáng từ khe cửa đang mở rộng tỏa ra, vô cảm như vũ trụ, tinh khiết như chân lý."
  },
  AvgDialog_60890_Content_22 = {
    Text = "Bạn mê mẩn nhìn vào tia sáng đó, hai dòng nước mắt trượt xuống dưới ánh sáng chói chang, bạn không hề hay biết. Bạn không thể dời mắt đi được nữa."
  },
  AvgDialog_60890_Content_23 = {
    Text = "Cửa…cửa mang vạn vật…ngôi nhà của thần minh…"
  },
  AvgDialog_60890_Content_24 = {
    Text = "Cuối cùng cũng đã đến ngày này!"
  },
  AvgDialog_60890_Content_25 = {
    Text = "Không, không thể để cửa mở…"
  },
  AvgDialog_60890_Content_26 = {
    Text = "Bạn muốn làm gì? Bạn nỗ lực thúc đẩy chìa khóa bạc, nhưng sức mạnh tinh thần của bạn lúc này bị đè nén chặt chẽ, chìa khóa bạc không có chút phản ứng nào."
  },
  AvgDialog_60890_Content_28 = {
    Text = "Bạn nhìn chằm chằm vào cánh cửa đó trong tuyệt vọng. Từ mờ ảo đến rõ ràng, nó mở ra một khe hở."
  },
  AvgDialog_60890_Content_29 = {
    Text = "Lực lượng mạnh mẽ đó, giống như dòng lũ sắp nhấn chìm thế giới, từ trong cánh cửa tràn ra hướng tới tượng sinh đôi Đèn."
  },
  AvgDialog_60890_Content_3 = {
    Text = "Hồ đen đang rung chuyển. Mái vòm cũng vậy. Dường như cả Misaque và toàn bộ lục địa đều run rẩy trong lời tụng đọc của Yu Li-ét."
  },
  AvgDialog_60890_Content_30 = {
    Text = "Yu Li-ét mở to đôi mắt nhìn vào cửa và tượng thần, nụ cười trên khuôn mặt trở nên càng thêm độc ác và méo mó."
  },
  AvgDialog_60890_Content_31 = {
    Text = "Lực lượng, là lực lượng bên trong… Tượng Thần Song Sinh, sắp hoàn thành sự hợp nhất."
  },
  AvgDialog_60890_Content_32 = {
    Text = "Misaque… Người Giữ Gìn… cùng với thế giới tội lỗi này, hãy đón nhận sự thanh tẩy cuối cùng!"
  },
  AvgDialog_60890_Content_33 = {Text = "Ding——"},
  AvgDialog_60890_Content_34 = {
    Text = "Chương thứ tư, khởi động."
  },
  AvgDialog_60890_Content_35 = {Text = "!!!"},
  AvgDialog_60890_Content_36 = {
    Text = "Như thể hàng vạn nhạc công cùng lúc tấu lên các loại nhạc cụ, đàn dây, kèn, trống, những âm thanh khác nhau đan xen, tụ hợp thành một dòng sông vĩ đại và tráng lệ."
  },
  AvgDialog_60890_Content_37 = {
    Text = "Dòng sông cuồn cuộn, đột nhiên lao về phía mối liên kết mỏng manh giữa cửa và tượng thần song sinh."
  },
  AvgDialog_60890_Content_38 = {
    Text = "Sức mạnh phản phệ từ bên trong cánh cửa khiến Song Tử rung chuyển mạnh mẽ. Khí tức nguy hiểm từ tượng thần đã giảm rõ rệt."
  },
  AvgDialog_60890_Content_39 = {
    Text = "Tượng đá di chuyển về phía trung tâm đã dừng động tác của nó."
  },
  AvgDialog_60890_Content_4 = {
    Text = "Trong cơn rung lắc dữ dội này, bạn ngẩng đầu lên và nhìn vào sáng tạo ngày càng vĩ đại và tráng lệ trước mắt."
  },
  AvgDialog_60890_Content_40 = {
    Text = "Đó là khuôn mặt quen thuộc, từ trong bóng tối bước ra, tái xuất hiện trong tầm mắt của bạn."
  },
  AvgDialog_60890_Content_41 = {
    Text = "Thời cơ đã đến. Vở diễn cuối cùng, sắp bắt đầu."
  },
  AvgDialog_60890_Content_42 = {
    Text = "Anh ấy nhẹ nhàng vung cây chỉ huy. Một giai điệu dịu dàng truyền vào thế giới tinh thần của bạn."
  },
  AvgDialog_60890_Content_43 = {
    Text = "Những gánh nặng và đau khổ đột nhiên biến mất, bạn lại được tắm trong suối nước nóng, trong đầu tràn ngập lực lượng tinh thần mạnh mẽ hơn trước."
  },
  AvgDialog_60890_Content_44 = {
    Text = "Bạn… bạn không phá hủy liên kết tinh thần của tôi…"
  },
  AvgDialog_60890_Content_45 = {
    Text = "Trước đó, khả năng liên kết của bạn đã bị tạm ngắt. Đây là một thủ đoạn để làm Yu Li-ét phân tâm."
  },
  AvgDialog_60890_Content_46 = {
    Text = "Hạn chế của bạn đã được gỡ bỏ. Bây giờ, cánh cửa đã mở, mọi thứ đã sẵn sàng."
  },
  AvgDialog_60890_Content_47 = {
    Text = "Anh ta đứng trước mặt bạn, trong đôi mắt tĩnh lặng, bùng cháy ngọn lửa cuồng nhiệt."
  },
  AvgDialog_60890_Content_48 = {
    Text = "Anh ta đặt gậy chỉ huy sau lưng và cúi người chào bạn."
  },
  AvgDialog_60890_Content_49 = {
    Text = "Mắt không có tròng, người đại diện của ý chí vô thượng. Ta sẽ hỗ trợ ngươi, giành lại quyền lực thuộc về ngươi."
  },
  AvgDialog_60890_Content_5 = {
    Text = "Song sinh... tượng thần.."
  },
  AvgDialog_60890_Content_50 = {
    Text = "Bạn…… nói gì?"
  },
  AvgDialog_60890_Content_51 = {
    Text = "Sự đến của ý chí vô thượng không thể tránh khỏi, chỉ bạn mới có thể chống lại."
  },
  AvgDialog_60890_Content_52 = {
    Text = "Khi Song Tử xuất hiện, cánh cửa mở ra, bạn mới có thể nhận lại khả năng đối kháng với Ngài."
  },
  AvgDialog_60890_Content_53 = {
    Text = "Việc cấp bách phải xử lý linh hoạt, mong bạn tha thứ cho sự bất lịch sự của tôi trước đây."
  },
  AvgDialog_60890_Content_54 = {
    Text = "Hamlin! Bạn… bạn đang làm gì vậy?!!"
  },
  AvgDialog_60890_Content_55 = {
    Text = "Làm những gì tôi nên làm."
  },
  AvgDialog_60890_Content_56 = {
    Text = "Hắn chỉ là một phân mảnh!Chỉ có dùng cách của ta, mới có thể khiến ý chí vô thượng chân chính thức tỉnh…"
  },
  AvgDialog_60890_Content_57 = {
    Text = "Bạn không muốn lắng nghe âm nhạc tối cao từ ý chí vô thượng sao? Hamlin, bạn đã phản bội những gì bạn tín ngưỡng!"
  },
  AvgDialog_60890_Content_58 = {
    Text = "Thần minh không nhất định phải vĩ đại hơn các phân mảnh của mình. Điều này cũng không phải là điều tôi quan tâm, bà Yu Lie-et."
  },
  AvgDialog_60890_Content_59 = {
    Text = "Tôi cũng từng nghĩ rằng, bản Anh hồn khúc của ý chí vô thượng là âm thanh vĩ đại nhất trong vũ trụ này. Rốt cuộc, tôi đã hiểu: nghệ thuật chân chính cao cả nhất sẽ vượt qua chính nó."
  },
  AvgDialog_60890_Content_6 = {
    Text = "Hai pho tượng đá hình người màu trắng từ từ nổi lên từ hồ đen, khiến cả hồ đen rung động."
  },
  AvgDialog_60890_Content_60 = {
    Text = "Anh ta ngẩng đầu lên, đôi mắt bùng cháy dữ dội, lặng lẽ nhìn Yu Li-ét."
  },
  AvgDialog_60890_Content_61 = {
    Text = "Nó sẽ vang lên trong cuộc đấu tranh——cuộc đối đầu giữa loài người và thần minh. Cuộc đối đầu giữa phân mảnh và bản nguyên."
  },
  AvgDialog_60890_Content_62 = {
    Text = "Đối kháng với ý chí vô thượng, hòa tấu cùng ý chí vô thượng… Đây sẽ là bản nhạc cao cả vượt xa cả phần an hồn của ý chí vô thượng!"
  },
  AvgDialog_60890_Content_63 = {
    Text = "Bạn là từ khi nào……"
  },
  AvgDialog_60890_Content_64 = {
    Text = "Mùa xuân của Akutê, chúng ta đã chứng kiến vụ nổ đó."
  },
  AvgDialog_60890_Content_65 = {
    Text = "Vào ngày đó, tôi đã nghe thấy nó… Tôi theo đuổi tiếng nhạc vang lên trong cuộc đấu tranh, còn vĩnh cửu hơn cả bản an hồn khúc."
  },
  AvgDialog_60890_Content_66 = {
    Text = "Lúc đó, tôi chỉ nghe được bản tiền tấu của nó. Hôm nay, nó sẽ vang lên trọn vẹn và lan tỏa khắp thế giới này."
  },
  AvgDialog_60890_Content_67 = {
    Text = "Giọng nói bình tĩnh của Hamlin không thể kiềm chế được rung rẩy."
  },
  AvgDialog_60890_Content_68 = {
    Text = "Vậy, từ ngày đó, anh đã bắt đầu lên kế hoạch bội phản……"
  },
  AvgDialog_60890_Content_69 = {
    Text = "Thần minh đã quên mất âm nhạc của Người. Người chỉ là một khối hỗn loạn vô thức, một thảm họa kinh hoàng."
  },
  AvgDialog_60890_Content_7 = {
    Text = "Trong khe hở giữa các tượng đá, thân thể của Ramona bị cuốn quanh và bao bọc bởi xác của Tà Vy."
  },
  AvgDialog_60890_Content_70 = {
    Text = "Tất cả vẻ đẹp của Ngài đều nằm trong những mảnh vỡ của Ngài."
  },
  AvgDialog_60890_Content_71 = {
    Text = "Tôi trung thành với âm nhạc, tôi chưa bao giờ bội phản, Yu Li-ét."
  },
  AvgDialog_60890_Content_72 = {
    Text = "Anh ta lặng lẽ nhìn vào Yu Li-ét, pho tượng khổng lồ, và cánh cửa phía sau pho tượng."
  },
  AvgDialog_60890_Content_73 = {
    Text = "Anh ấy đứng bên cạnh cậu."
  },
  AvgDialog_60890_Content_74 = {
    Text = "Tại sao… nếu bạn đã giúp tôi từ đầu, Ramona sẽ không…"
  },
  AvgDialog_60890_Content_75 = {
    Text = "Người giữ bí mật %player%, sự đến của ý chí vô thượng không thể ngăn cản. Để Yu Li-ét triệu hồi cánh cửa, giúp bạn thuận lợi thu hồi quyền năng, đó là con đường duy nhất."
  },
  AvgDialog_60890_Content_76 = {
    Text = "Điều chúng ta theo đuổi khác nhau, nhưng dù là âm thanh tối cao hay sự trường tồn của thế giới, cơ hội chỉ có một lần."
  },
  AvgDialog_60890_Content_77 = {
    Text = "Trong buổi biểu diễn này, bạn, tôi, cô Ramona, và tất cả mọi người ở đây, đều chỉ là những nhạc công."
  },
  AvgDialog_60890_Content_78 = {
    Text = "Cô Ramona sẽ hiểu."
  },
  AvgDialog_60890_Content_79 = {
    Text = "Bạn biết đấy, Hamlin nói đúng. Ramona nhất định sẽ hiểu. Để duy trì thế giới, cô ấy không bao giờ ngại hy sinh bản thân."
  },
  AvgDialog_60890_Content_8 = {
    Text = "Hai xác không chủ liên tục biến đổi, hòa quyện, trở thành một tượng điêu khắc khổng lồ hai màu đen trắng, lơ lửng giữa những pho tượng đá nửa thân khổng lồ."
  },
  AvgDialog_60890_Content_80 = {
    Text = "Dexter đã biến mất, nhưng trên thế giới này, vẫn có người bận tâm."
  },
  AvgDialog_60890_Content_81 = {
    Text = "——ít nhất, cô ấy vẫn còn sống."
  },
  AvgDialog_60890_Content_82 = {
    Text = "Cảm nhận sức mạnh tinh thần trong cơ thể ngày càng mạnh mẽ, bạn ngẩng đầu lên, nhìn về phía bức điêu khắc đen trắng."
  },
  AvgDialog_60890_Content_83 = {
    Text = "Đi nào, Người Giữ Gìn %player%. Hãy đi đập vỡ bức tượng đá đó và giải cứu đồng đội của bạn."
  },
  AvgDialog_60890_Content_84 = {
    Text = "Hãy thể hiện quyền lực của bạn cho thế giới này… và nhớ lại tất cả về ý chí vô thượng."
  },
  AvgDialog_60890_Content_9 = {
    Text = "Tìm thấy cậu rồi… Tà Vy!"
  },
  AvgDialog_60897_Content_1 = {
    Text = "Người giữ bí mật…… Chúng ta đã thành công!"
  },
  AvgDialog_60897_Content_10 = {
    Text = "Cô ấy quay đầu lại, nhìn về hướng bạn đang nhìn ——"
  },
  AvgDialog_60897_Content_11 = {
    Text = "Sau cánh cửa mở rộng đó, vô số bong bóng đồng loạt nổ tung. Thời gian, không gian và kiến thức vỡ thành từng mảnh, như dầu loang lộn xộn, nhuộm lên chiều này những sắc thái phức tạp và xấu xí."
  },
  AvgDialog_60897_Content_12 = {
    Text = "Sau những phân mảnh tượng trưng cho muôn vật, một con mắt từ từ mở ra, giống như một đứa trẻ vừa chào đời, tò mò nhìn ngắm thế giới này."
  },
  AvgDialog_60897_Content_13 = {
    Text = "Ở nơi ánh mắt hướng tới, vô số vật thể từng tồn tại trên thế giới đều hóa thành chất lỏng rỗng rỗng, chảy vào hồ đen."
  },
  AvgDialog_60897_Content_14 = {
    Text = "Đôi mắt di chuyển, cuối cùng khóa chặt trên người bạn."
  },
  AvgDialog_60897_Content_15 = {
    Text = "Thức tỉnh……@3……thức tỉnh!……"
  },
  AvgDialog_60897_Content_16 = {
    Text = "Còng kinh của Ngài bỗng nhiên giãn to, cả vũ trụ dường như cũng chấn động trong khoảnh khắc theo Ngài."
  },
  AvgDialog_60897_Content_17 = {
    Text = "Bạn đối mặt với Ngài. Cuộc đối mặt này chắc chắn là một sự xúc phạm. Tất cả mọi thứ trên thế gian đều biến mất. Ý thức của bạn trở nên trống rỗng."
  },
  AvgDialog_60897_Content_18 = {
    Text = "Sợ hãi. Nỗi sợ hãi nguyên thủy nhất và tinh khiết nhất, không thể tưởng tượng, không thể kháng cự, đã ngấm tràn khắp cơ thể bạn."
  },
  AvgDialog_60897_Content_2 = {
    Text = "Khuôn mặt của Ramona nở nụ cười."
  },
  AvgDialog_60897_Content_20 = {
    Text = "He he he he... ha ha ha ha!"
  },
  AvgDialog_60897_Content_21 = {
    Text = "Tôi không nhìn lầm bạn, %player%. Tôi không nhìn lầm bạn!"
  },
  AvgDialog_60897_Content_22 = {
    Text = "Giọng N vang lên từ bóng tối của hồ đen. Hình ảnh trước mắt khiến Người hoàn toàn quên mất việc duy trì sự thanh nhã của mình. Người cười điên rồ, nhìn vào cửa với ánh mắt cuồng nhiệt."
  },
  AvgDialog_60897_Content_23 = {
    Text = "Ngài đã tỉnh. Ngài đã tỉnh! Ha!"
  },
  AvgDialog_60897_Content_24 = {
    Text = "Vậy, %player%, phân mảnh, kẻ giả mạo……"
  },
  AvgDialog_60897_Content_25 = {
    Text = "Ngài quay đầu lại, miệng nở một nụ cười tà ác, khuôn mặt không mắt, đen tối hoàn toàn, chăm chú nhìn bạn với vẻ đầy ẩn ý."
  },
  AvgDialog_60897_Content_26 = {
    Text = "Hãy nói cho tôi… bây giờ, bạn có thể làm gì?"
  },
  AvgDialog_60897_Content_3 = {
    Text = "Người giữ bí mật, bây giờ chúng ta có thể.."
  },
  AvgDialog_60897_Content_4 = {Text = "?!!!"},
  AvgDialog_60897_Content_5 = {
    Text = "Người Giữ Bí Mật?"
  },
  AvgDialog_60897_Content_6 = {
    Text = "Ramona nhìn bạn với vẻ nghi hoặc."
  },
  AvgDialog_60897_Content_7 = {
    Text = "Trong khoảnh khắc vui vẻ này, cô ấy đã nhìn thấy một biểu cảm mà chưa bao giờ xuất hiện trên khuôn mặt của bạn ——"
  },
  AvgDialog_60897_Content_8 = {
    Text = "Đó là khi một người đối mặt với sự sụp đổ của vũ trụ hùng vĩ……"
  },
  AvgDialog_60897_Content_9 = {
    Text = "Sự lạnh giá, sợ hãi, tuyệt vọng, yếu ớt."
  },
  AvgDialog_61921_Content_1 = {
    Text = "Bạn bị cuốn vào những cơn ác mộng vô hình, những suy nghĩ kỳ lạ nắm giữ ý thức của bạn, khiến giấc mơ trở nên đảo lộn và mơ hồ."
  },
  AvgDialog_61921_Content_10 = {
    Text = "Cô quay đầu lại, ánh mắt bình thản và dửng dưng, nhưng bạn không thể cưỡng lại lời nói của cô."
  },
  AvgDialog_61921_Content_11 = {
    Text = "Lại gần hơn một chút."
  },
  AvgDialog_61921_Content_12 = {
    Text = "Cô ấy tựa vào ngực bạn, bạn cảm nhận thấy nhịp thở của mình ngày càng gấp gáp."
  },
  AvgDialog_61921_Content_13 = {
    Text = "Tà Vy nắm lấy tay bạn, chạm nhẹ vào mặt nước hồ đen. Những vòng gợn sóng lan ra ngoài."
  },
  AvgDialog_61921_Content_14 = {
    Text = "Bạn có nghe thấy không nhỉ? Đây là tiếng đập của trái tim bạn."
  },
  AvgDialog_61921_Content_15 = {
    Text = "Dù tôi ở thời đại nào, không gian nào… nhịp thở và nhịp tim của bạn vẫn sẽ truyền đến tôi qua làn nước trong hồ này."
  },
  AvgDialog_61921_Content_16 = {
    Text = "Đây là lần đầu tiên, tôi lắng nghe nhịp tim của bạn như thế này. \nNó cùng tần số với những gì tôi nghe ngày đêm, vang dội đến mức khiến tim ngừng đập."
  },
  AvgDialog_61921_Content_17 = {
    Text = "Cô ấy ngẩng mắt nhìn bạn, trong còng kinh xám lục nhạt chứa đựng những suy tư mơ hồ."
  },
  AvgDialog_61921_Content_18 = {
    Text = "Bạn cảm thấy xung quanh có vẻ như đang mưa lại. \n Hồ đen cũng sẽ có mưa không?"
  },
  AvgDialog_61921_Content_19 = {
    Text = "Những sợi mưa bạc óng ánh nhẹ nhàng bao quanh hai người một cách khéo léo và dày đặc. \n Đây là khoảnh khắc và không gian chỉ thuộc về bạn và cô ấy."
  },
  AvgDialog_61921_Content_2 = {
    Text = "Một giọt chất lỏng mát mẻ như một nụ hôn nhẹ nhàng rơi trên trán bạn, theo sau là cơn mưa bạc phủ kín bầu trời. \nBạn được thức tỉnh bởi những sợi mưa."
  },
  AvgDialog_61921_Content_20 = {
    Text = "Bạn có biết không? Cô ấy sẽ hối hận vì lan truyền những khát vọng như thế này…"
  },
  AvgDialog_61921_Content_21 = {
    Text = "Liên kết giữa tôi và bạn sâu sắc và xa hơn nhiều so với những gì cô ta cố gắng lây nhiễm vào bạn…"
  },
  AvgDialog_61921_Content_3 = {
    Text = "Hô, hô……"
  },
  AvgDialog_61921_Content_4 = {
    Text = "Đêm trong ký túc xá như được bao phủ bởi một lớp màn mỏng, âm thanh mờ ảo vang vọng bên tai bạn."
  },
  AvgDialog_61921_Content_5 = {
    Text = "Tôi đang đợi bạn ở hồ đen."
  },
  AvgDialog_61921_Content_7 = {
    Text = "Lụa mỏng trắng tinh che khuất bên mặt cô ấy, làn hơi nước bao quanh hồ đen như một phần mở rộng của cô, cuốn bạn vào giấc mơ ảo giác."
  },
  AvgDialog_61921_Content_8 = {
    Text = "Trong vô số giấc mơ, cô ấy đứng trước cánh cửa tận cùng, đặt ra những câu hỏi không lời cho bạn."
  },
  AvgDialog_61921_Content_9 = {
    Text = "Lại đây với tôi."
  },
  AvgDialog_62163_Content_1 = {
    Text = "Ramona bị tượng thần… tiêu thụ trở lại?!"
  },
  AvgDialog_62163_Content_2 = {
    Text = "Đây là lực lượng của \"Quy luật Quên lãng\"... ý thức của tôi đã bị ảnh hưởng, không thể tiếp tục cung cấp âm nhạc hoàn chỉnh cho bạn nữa. Cuộc chiến tiếp theo sẽ vô cùng khó khăn..."
  },
  AvgDialog_62163_Content_3 = {
    Text = "Ngài ấy cũng giống chúng ta, đã đạt đến giới hạn… Tôi tuyệt đối không… gục ngã tại đây!"
  },
  AvgDialog_62164_Content_1 = {
    Text = "Ramona bị tượng thần… tiêu thụ trở lại?!"
  },
  AvgDialog_62164_Content_2 = {
    Text = "Là lực lượng của \"Lý do bị Quên\"... ý thức của tôi đã bị ảnh hưởng, không thể tiếp tục cung cấp cho bạn âm nhạc đầy đủ nữa."
  },
  AvgDialog_62164_Content_3 = {
    Text = "Trước khi bị tiêu thụ, ý thức của Ramona cũng đã khiến Ngài bị thương nặng. Cô ấy vẫn đứng cùng bạn, Người Giữ Gìn."
  },
  AvgDialog_62164_Content_4 = {
    Text = "Sợi dây thần kinh trong đầu rung động nhẹ, bạn nghe thấy một tiếng nói yếu ớt."
  },
  AvgDialog_62164_Content_5 = {
    Text = "Ghi nhớ quá khứ... không thể... quên.."
  },
  AvgDialog_62164_Content_6 = {
    Text = "Hãy để tôi và bạn, đứng bên nhau.."
  },
  AvgDialog_62165_Content_1 = {
    Text = "Người Giữ Bí Mật……"
  },
  AvgDialog_62165_Content_2 = {
    Text = "Ramona?!! Bạn… đã hồi phục ý thức?!!"
  },
  AvgDialog_62165_Content_3 = {
    Text = "Rất tiếc, lần này không được cùng bạn chiến đấu… nhưng bây giờ tôi sẽ không vi phạm lời hứa nữa."
  },
  AvgDialog_62165_Content_4 = {
    Text = "Từ những liên kết ban đầu, những ký ức thuộc về chúng ta, chúng ta sẽ không để bất kỳ ai cướp đi. \nĐúng chứ, Người Giữ Gìn?"
  },
  AvgDialog_62165_Content_5 = {
    Text = "Khi lời của Ramona vang lên trong đầu bạn, tượng thần phát ra một tiếng gầm mạnh mẽ, dường như có một mũi dao nhọn đâm vào thần kinh của Ngài."
  },
  AvgDialog_62165_Content_6 = {
    Text = "Một tia sáng từ bông hoa bạc trên đầu nó bùng nổ, rơi xuống người bạn."
  },
  AvgDialog_62165_Content_7 = {
    Text = "Bạn biết đấy, cô ấy chưa bao giờ quên. Cô ấy đã đến bên bạn —— giống như đã từng rất nhiều lần."
  },
  AvgDialog_62166_Content_1 = {
    Text = "Chỉ dựa vào chúng ta không thể ngăn chặn tượng thần… Tôi sẽ dùng âm thanh để giúp bạn liên kết với Ramona. Hãy nhắm mắt lại và dùng ý thức của bạn để gọi cô ấy!"
  },
  AvgDialog_62166_Content_10 = {
    Text = "Ramona ngẩng đầu lên, nhìn về hướng phát ra tiếng động."
  },
  AvgDialog_62166_Content_11 = {
    Text = "Tôi đã hứa với {Male=anh ấy,Female=cô ấy}. Dù là khi nào, dù đối mặt với điều gì… tôi sẽ luôn đứng về phía {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_62166_Content_12 = {
    Text = "Trong tiếng nhạc của Hamlin và lời gọi của bạn, sự hợp nhất của tượng thần bất ngờ dừng lại. \n Một bông hoa bạc rực rỡ ánh sáng, tuy không hoàn chỉnh, nhẹ nhàng rời khỏi thân thể của tượng đen trắng."
  },
  AvgDialog_62166_Content_13 = {
    Text = "Ramona, chờ tôi!"
  },
  AvgDialog_62166_Content_14 = {
    Text = "Tôi nhất định sẽ cứu bạn ra!…… Ramona, hãy chờ tôi!!"
  },
  AvgDialog_62166_Content_15 = {
    Text = "Bạn hét to tới bông hoa bạc nguyên chất. Qua thế giới tinh thần hư vô, hình bóng bạc mờ ảo đang mỉm cười với bạn."
  },
  AvgDialog_62166_Content_16 = {
    Text = "Tôi tin tưởng bạn, Người Giữ Gìn."
  },
  AvgDialog_62166_Content_17 = {
    Text = "……Tôi sẽ đợi bạn."
  },
  AvgDialog_62166_Content_2 = {Text = "Ramona!"},
  AvgDialog_62166_Content_3 = {
    Text = "Có tiếng... rất quen thuộc, là.."
  },
  AvgDialog_62166_Content_4 = {
    Text = "Tượng thần đang tiêu thụ ý thức của chúng ta. Ký ức của chúng ta sắp biến mất, Ramona. Từ mọi chiều không gian, mọi dòng thời gian trong thế giới này, chưa bao giờ tồn tại."
  },
  AvgDialog_62166_Content_5 = {
    Text = "Cha, lực lượng, tự do, sức sống… ngươi sắp mất nhiều hơn nữa, Ramona."
  },
  AvgDialog_62166_Content_6 = {
    Text = "Không, Tà Vy… Có những thứ tôi không thể mất. Ít nhất bây giờ, tôi vẫn còn có {Male=anh ấy,Female=cô ấy}…"
  },
  AvgDialog_62166_Content_7 = {
    Text = "Bức tượng thần không thể bị phá vỡ, nếu cố gắng vùng vẫy thoát ra, bạn sẽ phải chịu đựng nỗi đau khôn cùng, và sự giúp đỡ cung cấp cho {Male=anh ấy,Female=cô ấy} cũng hạn chế rất nhiều."
  },
  AvgDialog_62166_Content_8 = {
    Text = "Mặc dù vậy, bạn vẫn sẵn sàng chứ?"
  },
  AvgDialog_62166_Content_9 = {
    Text = "Nếu không như vậy, chúng ta chỉ có thể để mặc tượng thần thành hình. Phải không?"
  },
  AvgDialog_62167_Content_1 = {
    Text = "Đây là điểm kết thúc của trò chơi, Người Giữ Gìn {Male=ngài,Female=cô}."
  },
  AvgDialog_62167_Content_10 = {
    Text = "Cô ấy không còn để ý đến hình tượng của mình nữa, cúi người xuống nôn khan."
  },
  AvgDialog_62167_Content_11 = {
    Text = "Không, không thể nào… Ngài là ý chí tối cao… Ngài mang sự tịnh hóa đến cho thế giới này…"
  },
  AvgDialog_62167_Content_12 = {
    Text = "Giấc mơ…… hủy diệt…… không…… không!"
  },
  AvgDialog_62167_Content_13 = {
    Text = "Cô ấy ngã quỵ trước cửa, ôm chặt lấy cánh tay mình, thân thể không ngừng run rẩy."
  },
  AvgDialog_62167_Content_14 = {
    Text = "Yu Li-ét? Bạn thấy gì vậy?!"
  },
  AvgDialog_62167_Content_15 = {
    Text = "Sự thật...thì ra...đây chính là sự thật.."
  },
  AvgDialog_62167_Content_16 = {
    Text = "Yu Li-ét không để ý đến lời kêu gọi của bạn. Ngay khi nhìn thấy cánh cửa, dường như mọi thứ trên thế gian này không còn liên quan gì đến cô ấy nữa."
  },
  AvgDialog_62167_Content_17 = {
    Text = "Tượng đá!……"
  },
  AvgDialog_62167_Content_18 = {
    Text = "Bạn ngẩng đầu lên——"
  },
  AvgDialog_62167_Content_19 = {
    Text = "Luồng khí tràn ra từ sau cánh cửa đều bị hấp thụ, những tượng đá bị chặn lại đột nhiên hợp nhất với nhau."
  },
  AvgDialog_62167_Content_2 = {
    Text = "Trước mặt Yu Li-ét, cánh cửa mở ra một khe hở đủ rộng để người đi qua."
  },
  AvgDialog_62167_Content_20 = {
    Text = "Tượng đá khổng lồ kia như một sinh vật sống, đứng uy nghiêm, bất động như một biểu tượng của quyền lực trước mặt bạn."
  },
  AvgDialog_62167_Content_21 = {
    Text = "Yu Li-ét yếu đuối nâng đầu lên, nhìn vào sáng tạo khổng lồ trước mắt mà cô không thể kiểm soát được nữa, dùng hết sức lực cuối cùng, với một nụ cười chua chát và đau đớn."
  },
  AvgDialog_62167_Content_22 = {
    Text = "Bắt đầu sai, kết thúc sai. Kết thúc, cũng là thanh tẩy… Hãy để tất cả khép lại tại đây."
  },
  AvgDialog_62167_Content_23 = {
    Text = "Yu Li-ét từ từ ngã xuống. Ngã trước bí mật về cánh cửa."
  },
  AvgDialog_62167_Content_24 = {
    Text = "Trước thân thể của cô ấy, bức tượng đá khổng lồ mang hơi thở như từ hố sâu từ từ đứng dậy trước mặt bạn ——"
  },
  AvgDialog_62167_Content_3 = {
    Text = "Ý chí của các ngươi thật đáng kính nể, tiếc thay, ý chí sai hướng chỉ là vô dụng mà thôi."
  },
  AvgDialog_62167_Content_4 = {
    Text = "Tất cả kiến thức và sức mạnh đều nằm sau cánh cửa này. Cánh cửa sẽ hỗ trợ tôi trong việc hợp nhất hai bức tượng thần."
  },
  AvgDialog_62167_Content_5 = {
    Text = "Tôi sẽ ở đây, chào đón thần minh tối cao thanh tẩy thế gian ——"
  },
  AvgDialog_62167_Content_6 = {
    Text = "Cô ấy đến trước cánh cửa, mỉm cười len lén nhìn vào bên trong."
  },
  AvgDialog_62167_Content_7 = {
    Text = "Yu Li-ét… chờ đã!"
