  AvgDialog_65471_Content_15 = {
    Text = "Ánh sáng vặn vẹo nhấp nháy trong bóng tối, giống như một khuôn mặt không có biểu cảm, lặng lẽ nhìn nhóm người bất lực."
  },
  AvgDialog_65471_Content_16 = {
    Text = "Trước cánh cửa, một phần thân thể của \"đóa\" bị khe hở nuốt chửng, nhưng cô ấy hoàn toàn không bận tâm. Cô nhìn biểu cảm trên khuôn mặt mọi người và vui vẻ nở nụ cười."
  },
  AvgDialog_65471_Content_17 = {
    Text = "Các người vẫn chưa hiểu sao? Hủy diệt, những kẻ yếu đuối. Chỉ có hủy diệt mới là logic duy nhất đúng đắn."
  },
  AvgDialog_65471_Content_18 = {
    Text = "Vũ trụ là một lời nói dối, một giấc mơ vô nghĩa do một đứa trẻ ngốc nghếch và mơ mộng tạo ra."
  },
  AvgDialog_65471_Content_19 = {
    Text = "Mọi sự giãy dụa đều vô ích. Chỉ có một khởi đầu mới mới xứng đáng gọi là tương lai."
  },
  AvgDialog_65471_Content_2 = {Text = "Ừ——"},
  AvgDialog_65471_Content_20 = {
    Text = "Chào đón khoảnh khắc này đi——"
  },
  AvgDialog_65471_Content_21 = {Text = "@2!——"},
  AvgDialog_65471_Content_22 = {
    Text = "Dường như nghe thấy một lời gọi, giọng nói hỗn loạn vang lên từ cánh cửa."
  },
  AvgDialog_65471_Content_23 = {
    Text = "Đó là tiếng khóc của trẻ sơ sinh, là lời nguyền cổ xưa, là sự ác ý thuần túy. Âm thanh điên loạn dường như chảy ra từ huyết mạch của nó, mang theo hơi thở hủy diệt, tuôn trào từ cánh cửa."
  },
  AvgDialog_65471_Content_24 = {Text = "Tà Vy!"},
  AvgDialog_65471_Content_25 = {
    Text = "Tà Vy đứng chắn trước mặt mọi người, đôi cánh chim khổng lồ mở rộng, nhưng màu sắc tượng trưng cho nhiều chiều không gian càng ngày càng tối đi."
  },
  AvgDialog_65471_Content_26 = {
    Text = "Rãnh nứt mở rộng một cách mất kiểm soát, tiêu thụ lý trí cuối cùng của Ngài."
  },
  AvgDialog_65471_Content_27 = {
    Text = "Ramona, bạn có thể cảm nhận được {Male=anh ấy,Female=cô ấy} không?"
  },
  AvgDialog_65471_Content_28 = {
    Text = "Tôi……không tìm thấy……\nSau khi bước qua cánh cửa, %hisorher% liên kết đã biến mất……"
  },
  AvgDialog_65471_Content_29 = {
    Text = "Ramona nắm chặt thanh kiếm trong tay, đứng dậy."
  },
  AvgDialog_65471_Content_3 = {
    Text = "Tà Vy? Bạn…"
  },
  AvgDialog_65471_Content_30 = {
    Text = "Trước khi {Male=anh ấy,Female=cô ấy} trở về, tôi nhất định sẽ giúp {Male=anh ấy,Female=cô ấy} bảo vệ tốt……"
  },
  AvgDialog_65471_Content_31 = {
    Text = "Lùi lại."
  },
  AvgDialog_65471_Content_32 = {Text = "!!!"},
  AvgDialog_65471_Content_33 = {
    Text = "Vào khoảnh khắc Ramona chuẩn bị lao vào Tà Vy, một bàn tay vô hình nào đó bất ngờ giữ chặt cô lại."
  },
  AvgDialog_65471_Content_34 = {
    Text = "Rãnh nứt…… dừng lại rồi?……"
  },
  AvgDialog_65471_Content_35 = {
    Text = "Không, nó đang giãy giụa…"
  },
  AvgDialog_65471_Content_36 = {
    Text = "Tà Vy từ từ mở mắt."
  },
  AvgDialog_65471_Content_37 = {
    Text = "Khe nứt đang nuốt chửng Người, rung động với tần số không thể cảm nhận trước mặt Người."
  },
  AvgDialog_65471_Content_38 = {
    Text = "Vết thương kinh khủng đó giống như một con mãnh thú co rúm người, run rẩy trước hai lực lượng khiến nó khiếp sợ."
  },
  AvgDialog_65471_Content_39 = {
    Text = "Tôi đến muộn."
  },
  AvgDialog_65471_Content_4 = {
    Text = "Lực lượng của thể chất trí tuệ đã cạn kiệt…Ngài đã trở lại."
  },
  AvgDialog_65471_Content_40 = {
    Text = "Trong cánh cửa, dưới mắt không có tròng, một hình bóng gầy gò đứng trước cánh cửa."
  },
  AvgDialog_65471_Content_41 = {
    Text = "Người giữ bí mật…… chính là Người Giữ Gìn!"
  },
  AvgDialog_65471_Content_42 = {
    Text = "Lớn {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}!"
  },
  AvgDialog_65471_Content_43 = {
    Text = "Bạn cuối cùng…"
  },
  AvgDialog_65471_Content_44 = {
    Text = "Ramona tiến về phía bạn. Bạn khẽ vẫy tay, và đôi tay vô hình lại chặn cô ấy lại."
  },
  AvgDialog_65471_Content_45 = {
    Text = "Ánh mắt của Người sẽ hủy diệt các ngươi. \nRời khỏi nơi này."
  },
  AvgDialog_65471_Content_46 = {
    Text = "Đi? Bạn… bạn đang nói gì?"
  },
  AvgDialog_65471_Content_47 = {
    Text = "Chúng tôi là thân thể được đánh thức của bạn…… Chúng tôi sẽ ở bên bạn……"
  },
  AvgDialog_65471_Content_48 = {
    Text = "Khi Ramona chuẩn bị lao tới cánh cửa một lần nữa, giọng của Alistair vang lên từ phía sau cô."
  },
  AvgDialog_65471_Content_49 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} không cần đánh thức thân thể nữa, Ramona."
  },
  AvgDialog_65471_Content_5 = {
    Text = "Thân thể của Tà Vy run rẩy nhẹ. Dưới sự đỡ đần của Ramona, Người yếu ớt từ từ ngẩng đầu lên."
  },
  AvgDialog_65471_Content_50 = {
    Text = "Bạn… bạn nói gì?"
  },
  AvgDialog_65471_Content_51 = {
    Text = "Không đợi Alistair trả lời, Ramona nhắm mắt lại, tái hiện lại mối liên kết sâu sắc giữa cô ấy và bạn."
  },
  AvgDialog_65471_Content_52 = {Text = "!!!"},
  AvgDialog_65471_Content_53 = {
    Text = "Liên kết... biến mất.."
  },
  AvgDialog_65471_Content_54 = {
    Text = "Ramona, cô đang nói gì vậy? Liên kết là sợi dây liên kết mạnh mẽ nhất giữa chúng ta và Người Giữ Gìn, làm sao có thể..."
  },
  AvgDialog_65471_Content_55 = {Text = "!!!……"},
  AvgDialog_65471_Content_56 = {
    Text = "Mỗi một thân thể được đánh thức đều nhắm mắt lại, bắt đầu truy hồi ở chiều tinh thần."
  },
  AvgDialog_65471_Content_57 = {
    Text = "Dù họ có cố gắng đến đâu, hình bóng từng gắn bó với họ ngày đêm, luôn dẫn dắt họ trong chiều kích tinh thần, giờ đây đã hoàn toàn biến mất."
  },
  AvgDialog_65471_Content_58 = {
    Text = "Dù người đó đang đứng ngay trước mặt họ, dù diện mạo của người đó không hề thay đổi, nhưng trong mắt họ lúc này, bóng dáng ấy đã trở nên quá đỗi xa lạ."
  },
  AvgDialog_65471_Content_59 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} hiện đang liên kết với một thực thể vô thức, được {Male=anh ấy,Female=cô ấy} tái tạo bằng quyền năng và ký ức của mình."
  },
  AvgDialog_65471_Content_6 = {
    Text = "Trong sắc màu rực rỡ nhưng phức tạp bên trong cánh cửa, con mắt ấy đã xé toang lời dối trá mà Tà Vy dệt nên, một lần nữa đến trước mặt mọi người."
  },
  AvgDialog_65471_Content_60 = {
    Text = "{Male=Anh ấy,Female=Cô ấy}……đã cắt đứt liên kết với chúng ta."
  },
  AvgDialog_65471_Content_61 = {Text = "?!!"},
  AvgDialog_65471_Content_62 = {
    Text = "Tại sao? Lily… Lily có thể giúp được {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}…"
  },
  AvgDialog_65471_Content_63 = {
    Text = "Tà Vy ngẩng đầu lên, hướng ánh mắt về phía cánh cửa, nơi có một bóng hình đơn độc."
  },
  AvgDialog_65471_Content_64 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} là phân mảnh của Thỏa Hợp Va Ba, người đại diện cho ý chí vô thượng. Trong chiều tinh thần của {Male=anh ấy,Female=cô ấy}, là hỗn loạn vô tận, điên rồ nguyên thủy…"
  },
  AvgDialog_65471_Content_65 = {
    Text = "Nếu liên kết với {Male=anh ấy,Female=cô ấy} hiện tại, chúng ta sẽ mất kiểm soát."
  },
  AvgDialog_65471_Content_66 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} là đúng. {Male=anh ấy,Female=cô ấy} bây giờ đã không cần chúng ta nữa."
  },
  AvgDialog_65471_Content_67 = {
    Text = "Ngài thu lại sáu cánh đã bị sự ăn mòn nuốt gần hết, lộ ra những khuôn mặt của các thân thể kích hoạt phía sau."
  },
  AvgDialog_65471_Content_68 = {
    Text = "Bạn đã thành công, Người Giữ Gìn… Hoặc có lẽ tôi nên gọi bạn là, mắt không có tròng?"
  },
  AvgDialog_65471_Content_69 = {
    Text = "Giọng của cô ấy vang đến tai bạn. Bạn cảm nhận được ánh mắt buồn bã của những thân thể được đánh thức. Bạn biết rằng, họ đang mong đợi sự gọi như mọi khi."
  },
  AvgDialog_65471_Content_70 = {
    Text = "Bạn mỉm cười. Mọi lời giải thích đều không còn cần thiết nữa."
  },
  AvgDialog_65471_Content_71 = {
    Text = "Thế giới của bạn còn lại chỉ có con mắt hùng vĩ thuộc về chủ sáng tạo ở phía trước. \nXung quanh bạn, đã không còn ai nữa."
  },
  AvgDialog_65471_Content_72 = {
    Text = "Ký ức của tôi bắt đầu từ Misaque. Trong ký ức của tôi, đầy những hình bóng của họ."
  },
  AvgDialog_65471_Content_73 = {
    Text = "Họ đã bảo vệ tôi nhiều lần. Lần này, đã đến lúc tôi đứng ra bảo vệ họ."
  },
  AvgDialog_65471_Content_74 = {
    Text = "Còng kinh to lớn tò mò mở tròn, nhìn chằm chằm vào bạn, như một đứa trẻ phát hiện ra món đồ chơi mới lạ và đầy màu sắc."
  },
  AvgDialog_65471_Content_75 = {
    Text = "Bạn hít sâu một hơi, ngẩng đầu lên. Bạn đối mặt với ý chí mạnh mẽ nhất."
  },
  AvgDialog_65471_Content_76 = {
    Text = "Tôi là mảnh vỡ mà bạn đã đánh mất. Giờ đây, mảnh vỡ này đang nhắm thẳng vào đôi mắt của bạn."
  },
  AvgDialog_65471_Content_77 = {
    Text = "Dù là người tạo ra, cũng không có quyền hủy diệt. Hỗn loạn hãy trở về hỗn loạn, nhân gian hãy trở về nhân gian."
  },
  AvgDialog_65471_Content_78 = {
    Text = "Trước khi hủy diệt giấc mơ của ngươi, hãy vượt qua ta đã. Ý chí tối thượng, vị sáng tạo chủ điên rồ —— Toghvabop."
  },
  AvgDialog_65471_Content_8 = {
    Text = "Khi tiếng sáo trầm vang lên lần nữa, hồ đen vừa yên bình bắt đầu nổi sóng dữ dội."
  },
  AvgDialog_65471_Content_9 = {
    Text = "Lời tụng niệm của Tà Vy như một bức tường mỏng manh, sụp đổ hoàn toàn trước lực lượng vĩ đại này."
  },
  AvgDialog_65472_Content_1 = {
    Text = "Quyết định: Bóng tối nguyên thủy"
  },
  AvgDialog_65472_Content_10 = {
    Text = "Thái Di Sơ……, xin lỗi, tôi……"
  },
  AvgDialog_65472_Content_11 = {
    Text = "Chập chập chập. Trước đây khi nói những lời cứng rắn, đâu phải là biểu cảm thất vọng như thế này, đồ giả mạo."
  },
  AvgDialog_65472_Content_12 = {
    Text = "Bạn đã thất bại, mảnh vỡ của mắt không có tròng. Hoàn toàn và triệt để."
  },
  AvgDialog_65472_Content_13 = {
    Text = "Bạn nói đúng, N… Tôi đã thất bại. Tôi không thể đánh bại Người…"
  },
  AvgDialog_65472_Content_14 = {
    Text = "Đối mặt với vị sáng tạo thật sự, một phân mảnh, không thể làm gì cả…"
  },
  AvgDialog_65472_Content_15 = {
    Text = "Xin lỗi, tôi đã phụ lòng mong đợi của mọi người…"
  },
  AvgDialog_65472_Content_16 = {
    Text = "Phản bội? Không, tôi rất vui, %player%. Vở kịch không tự lượng sức này thật khiến người ta mê mẩn."
  },
  AvgDialog_65472_Content_17 = {
    Text = "Bạn đã làm hết sức mình, %player%. Bạn chưa bao giờ phụ lòng tôi."
  },
  AvgDialog_65472_Content_18 = {
    Text = "Và… cuộc chiến đấu của bạn vẫn chưa kết thúc."
  },
  AvgDialog_65472_Content_19 = {
    Text = "Thái Di Sơ vuốt ve đầu bạn, mỉm cười nhẹ nhàng nhìn bạn."
  },
  AvgDialog_65472_Content_2 = {Text = "Thủ.."},
  AvgDialog_65472_Content_20 = {
    Text = "Còn……chưa kết thúc?"
  },
  AvgDialog_65472_Content_21 = {
    Text = "Trong vô số thất bại, tôi từng nhìn thấy một con đường của chiến thắng."
  },
  AvgDialog_65472_Content_22 = {
    Text = "Một con đường……hoàn toàn giống như hiện tại."
  },
  AvgDialog_65472_Content_23 = {
    Text = "Bạn nhắm mắt lại. Sức mạnh quyền lực của thể chất trí tuệ tràn ngập trong cơ thể bạn. Những suy nghĩ vô tận thuộc về Tà Vy ùa vào đầu bạn. Một cách dễ dàng, bạn nhìn thấy con đường trong mắt cô ấy."
  },
  AvgDialog_65472_Content_24 = {
    Text = "Bạn bất chợt mở mắt, nhìn xung quanh không gian này."
  },
  AvgDialog_65472_Content_25 = {
    Text = "Ngoài cánh cửa, bạn nhìn thấy những ánh sáng và bóng tối vượt ngoài quy luật vật lý, chập chờn lay động ở bờ biên của chiều không gian."
  },
  AvgDialog_65472_Content_26 = {
    Text = "Đó là… ranh giới của chiều… Bạn đã mở cánh cửa giữa các chiều rồi sao?"
  },
  AvgDialog_65472_Content_27 = {
    Text = "Trong vô số chiều, tồn tại vô số bản thân chúng ta. \nVô số chúng ta đang đối mặt với cùng một kẻ thù."
  },
  AvgDialog_65472_Content_28 = {
    Text = "Cánh cửa kết nối tất cả… Bây giờ, cánh cửa đã hoàn toàn mở ra."
  },
  AvgDialog_65472_Content_29 = {
    Text = "Thì ra là vậy… Tôi đã hiểu, Tà Vy!"
  },
  AvgDialog_65472_Content_3 = {
    Text = "Người Giữ Bí Mật……"
  },
  AvgDialog_65472_Content_30 = {
    Text = "Trong vô số các chiều, Toghuvabo là duy nhất, nhưng… chúng ta không phải vậy."
  },
  AvgDialog_65472_Content_31 = {
    Text = "Bạn đứng dậy, đối mặt với ánh mắt của gã khổng lồ trước mặt."
  },
  AvgDialog_65472_Content_32 = {
    Text = "Nhìn kìa, bạn bè giả mạo của chúng ta, lại sắp bắt đầu vở kịch {Male=anh ấy,Female=cô ấy} không biết chết sống rồi."
  },
  AvgDialog_65472_Content_33 = {
    Text = "N, bạn nói đúng. Một mảnh vỡ, căn bản không làm được gì."
  },
  AvgDialog_65472_Content_34 = {
    Text = "Nhưng những mảnh vỡ từ vị thần sáng tạo này không chỉ có một.."
  },
  AvgDialog_65472_Content_35 = {
    Text = "Bạn quét mắt qua không gian bên trong cánh cửa. Vô số con mắt, đang nhìn bạn từ vô số chiều khác nhau."
  },
  AvgDialog_65472_Content_36 = {
    Text = "Nhưng bạn biết đấy, chúng không nhìn vào bạn."
  },
  AvgDialog_65472_Content_37 = {
    Text = "Trong những chiều không gian mà bạn chưa từng biết đến, có vô số phiên bản của bạn đang đối diện với đôi mắt của Đấng Sáng Tạo."
  },
  AvgDialog_65472_Content_38 = {
    Text = "Hãy mở rộng giới hạn của chiều đi, Tà Vy."
  },
  AvgDialog_65472_Content_39 = {
    Text = "Tà Vy gật đầu nhẹ, đưa hai tay lên."
  },
  AvgDialog_65472_Content_4 = {
    Text = "Bạn là… Tà Vy?"
  },
  AvgDialog_65472_Content_40 = {
    Text = "Dường như có một lớp màng bị xé rách, vô số đôi mắt dần hiện rõ trong tầm mắt bạn."
  },
  AvgDialog_65472_Content_41 = {
    Text = "Vào khoảnh khắc lớp màng mỏng bị xé đi, vô số âm thanh chui vào tai bạn."
  },
  AvgDialog_65472_Content_42 = {
    Text = "\"Tôi đã đánh mất cuộc sống của mình một lần. Chết để bảo vệ tất cả những gì thuộc về mình, hoặc sống mà từ bỏ mọi thứ, tôi chỉ có một lựa chọn duy nhất.\""
  },
  AvgDialog_65472_Content_43 = {
    Text = "\"Tôi có thể. Dù thảm họa này là gì, tôi sẽ ngăn chặn đến của Ngài!\""
  },
  AvgDialog_65472_Content_44 = {
    Text = "\"Tôi nhất định sẽ cứu bạn ra... Hãy chờ tôi!\""
  },
  AvgDialog_65472_Content_45 = {
    Text = "\"thân thể được đánh thức, xếp hàng, đón đánh!\""
  },
  AvgDialog_65472_Content_47 = {
    Text = "Giọng đàn ông.Giọng phụ nữ.Giọng đầy nhiệt huyết.Giọng buồn bã."
  },
  AvgDialog_65472_Content_48 = {
    Text = "Những âm thanh này khiến bạn cảm thấy vừa quen thuộc vừa xa lạ, giống như một đứa trẻ lần đầu tiên nhìn thấy gương mặt mình."
  },
  AvgDialog_65472_Content_49 = {
    Text = "Bạn biết đấy, đứa trẻ trong gương lúc này cũng đang nhìn bạn."
  },
  AvgDialog_65472_Content_5 = {
    Text = "Là Tà Vy, cũng là biểu hiện của thể chất trí tuệ trong cơ thể bạn. \nBạn đã được cứu rồi, Người Giữ Gìn."
  },
  AvgDialog_65472_Content_50 = {
    Text = "Đây là giọng của tôi"
  },
  AvgDialog_65472_Content_51 = {
    Text = "Tôi đã nghe thấy… những âm thanh này, chính là giọng nói của tôi."
  },
  AvgDialog_65472_Content_52 = {
    Text = "Tuyệt vời, tuyệt vời… ngay cả tôi cũng không thể kiềm chế, muốn lên sân khấu cùng bạn."
  },
  AvgDialog_65472_Content_53 = {
    Text = "Hãy tiếp tục biểu diễn đi. Cho tôi xem, những phân mảnh các ngươi rốt cuộc có thể làm được gì?"
  },
  AvgDialog_65472_Content_54 = {
    Text = "Đi đi, người gìn giữ bí mật…… Tôi đã chọn tin tưởng vào bạn. Dù bạn đưa ra quyết định gì, tôi cũng sẽ giúp đỡ bạn."
  },
  AvgDialog_65472_Content_55 = {
    Text = "Tà Vy, Thái Di Sơ, N… Lực lượng của ba chất thể đang tuôn chảy về phía bạn. \nBạn đứng dậy, giơ chìa khóa bạc lên."
  },
  AvgDialog_65472_Content_56 = {
    Text = "Không gian mờ ảo, khung cảnh quen thuộc dần hiện ra trước mắt. Trong vô số chiều không gian sắp tan vỡ, vô số điểm sáng bạc đồng loạt bùng cháy."
  },
  AvgDialog_65472_Content_57 = {
    Text = "Ánh sáng bạc chiếu rọi bình tượng nến Lentiennam, viện điều dưỡng của La-i, mặt biển Brirpơ, và đụn cát Lemvahi. Ánh sáng bạc chiếu rọi quá khứ của bạn, tất cả những kiếp nạn và sự trưởng thành của bạn."
  },
  AvgDialog_65472_Content_58 = {
    Text = "Những phân mảnh yếu đuối, nhỏ bé đã quay lưỡi dao về phía nhà sáng tạo của mình."
  },
  AvgDialog_65472_Content_59 = {
    Text = "Một con mắt, một vết thương, một vết xước, thậm chí không để lại gì cả… tất cả đều không thành vấn đề."
  },
  AvgDialog_65472_Content_6 = {
    Text = "Đây là…"
  },
  AvgDialog_65472_Content_60 = {
    Text = "Nhìn này, Toghva Bo. Chúng tôi là mảnh vỡ của bạn, chúng tôi là những người gìn giữ bí mật của Misaque…"
  },
  AvgDialog_65472_Content_61 = {
    Text = "Dù phải trả giá như thế nào, chúng tôi cũng sẽ giữ bạn ở đây!"
  },
  AvgDialog_65472_Content_7 = {
    Text = "Thể chất trí tuệ đã tạm thời quay ngược thời gian, chúng ta vẫn còn ở bên trong cánh cửa."
  },
  AvgDialog_65472_Content_8 = {
    Text = "Ngài đã nhìn thấy quá khứ của bạn, và Ngài đang dõi theo từng bước chân mà bạn đã đi qua. Lentiennam, Rai, Lemvahi…"
  },
  AvgDialog_65472_Content_9 = {
    Text = "Ánh mắt của Người, vẫn đang đuổi theo chúng ta."
  },
  AvgDialog_65473_Content_1 = {
    Text = "Trong dự đoán của tôi, thật sự tôi không ngờ rằng bạn có thể tiến xa đến vậy."
  },
  AvgDialog_65473_Content_2 = {
    Text = "Từ bỏ những thứ mình đang sở hữu, điều đó không phải là dễ dàng."
  },
  AvgDialog_65473_Content_3 = {
    Text = "Bạn đang do dự. Do dự là điều bình thường. Do dự là phần mục nát nhưng cũng đầy huy hoàng trong bản chất con người."
  },
  AvgDialog_65473_Content_4 = {
    Text = "Nhưng bạn đã đi đến đây rồi. Bạn không thể do dự thêm nữa, %player%."
  },
  AvgDialog_65473_Content_5 = {
    Text = "Chỉ có thần minh mới có thể cản đường thần minh. Mọi tính người sẽ dần trở nên xa lạ với bạn."
  },
  AvgDialog_65473_Content_6 = {
    Text = "Cho tôi biết, bạn đã sẵn sàng chưa?"
