  AvgDialog_65476_Content_13 = {
    Text = "Mắt. Vô số mắt. Khi bạn dồn hết sức đánh vỡ một con mắt, nghìn mắt từ từ hé mở trong mờ mịt, từ thế giới bên trong cánh cửa, từ mọi chiều không gian của vũ trụ nhìn về phía bạn."
  },
  AvgDialog_65476_Content_14 = {
    Text = "Đạo rung động mạnh mẽ đó làm tan vỡ ý thức của bạn, khiến ký ức của bạn bắt đầu trở nên hỗn loạn. \nTrong tâm trí hỗn loạn, lời nói của N nhảy múa và lơ lửng trước mặt bạn. Bạn cười tự giễu, khóe miệng khẽ nhếch lên."
  },
  AvgDialog_65476_Content_15 = {
