  AvgDialog_65476_Content_17 = {
    Text = "Bạn gắng gượng đứng dậy, nhìn vào vô số những đôi mắt si ngốc."
  },
  AvgDialog_65476_Content_18 = {
    Text = "Cảm xúc giận dữ và buồn bã dâng trào trong lòng bạn. Nhưng bạn hiểu rằng, bạn không thể thay đổi điều gì."
  },
  AvgDialog_65476_Content_2 = {
    Text = "Tất cả các cuộc tấn công đều rơi vào hư không, tất cả các biện pháp phòng thủ đều dễ dàng bị phá vỡ."
  },
  AvgDialog_65476_Content_20 = {
    Text = "Vô số ánh mắt đổ dồn về phía bạn. Rỗng rỗng cuồn cuộn như thủy triều tràn lên cơ thể bạn. \n Quyền năng trong cơ thể bạn đang cố gắng hóa giải rỗng rỗng, nhưng tốc độ xuất hiện của nó vẫn nhanh hơn nhiều."
  },
  AvgDialog_65476_Content_21 = {
    Text = "Cơn đau dữ dội khiến bạn run rẩy toàn thân. Ký ức tan biến trong sự rỗng rỗng và sụp đổ, não bộ dần trở nên trống rỗng. \nBạn cầm chìa khóa bạc một cách máy móc, giơ lên trước ánh nhìn đầy sợ hãi ——"
  },
  AvgDialog_65476_Content_22 = {Text = "@3!"},
  AvgDialog_65476_Content_23 = {
