  AvgDialog_65478_Content_21 = {
    Text = "Ánh sáng đó không làm bạn cảm thấy chói mắt, chỉ khiến bạn cảm thấy ấm áp, như những chiếc lông vũ bạc trắng đầy đặn trong mắt bạn."
  },
  AvgDialog_65478_Content_22 = {
    Text = "Trước mặt bạn là khuôn mặt của Tà Vy. \nGiống như ngày đầu tiên gặp gỡ, thiêng liêng, hiền hòa, không thể xúc phạm."
  },
  AvgDialog_65478_Content_23 = {
    Text = "Sáu cánh của Ngài mở rộng, chắn giữa bạn và ánh mắt hủy diệt tất cả. Ánh sáng thiêng liêng vượt qua lẽ thường lấp lánh phía sau. Mỗi lần đập cánh, là một lần thay đổi chiều không gian, chuyển hướng ánh mắt hủy diệt về điểm kỳ dị vô hình."
  },
  AvgDialog_65478_Content_24 = {
    Text = "Dung dịch đen ăn mòn chảy dọc theo đôi cánh của nàng, thèm muốn từng tấc thân thể thánh thiêng không thể xúc phạm. Mỗi một khoảnh khắc, thân thể của Ngài vô số lần hóa thành xương khô, dung nhan của Ngài vô số lần bị hủy hoại hoàn toàn, rồi lại vô số lần khôi phục như ban đầu."
  },
  AvgDialog_65478_Content_25 = {
    Text = "——Ngài dùng chiều để đối kháng với cái nhìn đó, đối kháng với ý chí hủy diệt mọi thứ, không thể kháng cự."
  },
  AvgDialog_65478_Content_26 = {
    Text = "Trong cuộc chiến giữa sự tinh khiết và ô uế, chúng giao tranh vô số lần trong mỗi khoảnh khắc. Mỗi lần giao tranh, sắc mặt của Tà Vy lại càng thêm tái nhợt và mệt mỏi."
  },
  AvgDialog_65478_Content_27 = {
    Text = "Mục quang của Người sẽ tạm thời dừng lại ở chiều không gian tôi ẩn náu. Bạn còn thời gian, Người Giữ Gìn."
  },
  AvgDialog_65478_Content_28 = {
    Text = "Tà Vy, bạn…!"
  },
  AvgDialog_65478_Content_29 = {
    Text = "Hãy lắng nghe tôi, Người Giữ Gìn."
  },
  AvgDialog_65478_Content_3 = {
    Text = "Tương lai? Tôi và Yu Li-ét, kẻ ngây thơ đơn thuần kia, không giống nhau. Điều tôi muốn, chưa bao giờ là tương lai."
  },
  AvgDialog_65478_Content_30 = {
    Text = "Bước qua cánh cửa. Đi tìm câu trả lời. Hãy nhớ lại, tất cả những điều về chính bạn."
  },
  AvgDialog_65478_Content_31 = {
    Text = "Cô ấy nhìn bạn. Trên khuôn mặt hiền từ và thanh khiết đó, tỏa ra một sự uy nghiêm không thể chống lại."
  },
  AvgDialog_65478_Content_32 = {
    Text = "Bạn đã đánh bại chúng tôi. Bạn thật sự đã làm được!"
  },
  AvgDialog_65478_Content_33 = {
    Text = "Bây giờ, đi cứu họ."
  },
  AvgDialog_65478_Content_34 = {
