  AvgDialog_65480_Content_50 = {
    Text = "Cô ấy tin tưởng anh. Chỉ riêng trong chuyện này, cô ấy đã mắc sai lầm. \nTin tưởng người không đáng tin, thì phải trả giá. Anh nói đúng chứ, Người Giữ Gìn?"
  },
  AvgDialog_65480_Content_51 = {
    Text = "Cô ấy quay người. Trong tay cô nhẹ nhàng tung một não trong bình."
  },
  AvgDialog_65480_Content_52 = {
    Text = "Đó là...!"
  },
  AvgDialog_65480_Content_53 = {
    Text = "Ý thức bị mắc kẹt trong bình não, những thân thể dự phòng cũng mất đi tác dụng."
  },
  AvgDialog_65480_Content_54 = {
    Text = "Hãy yên tâm, cô ấy sẽ không chết, và tôi cũng sẽ không để cô ấy chết. \nTôi muốn cô ấy tận mắt chứng kiến cách mà những gì cô ấy muốn bảo vệ bị hủy diệt."
  },
  AvgDialog_65480_Content_55 = {
    Text = "Tôi sẽ chứng minh, các bạn sai rồi."
  },
  AvgDialog_65480_Content_56 = {
    Text = "Đạo phong ấn là do người sáng lập Misaque và Tà Vy tạo ra……bạn lại có thể……"
  },
  AvgDialog_65480_Content_57 = {
    Text = "Phong ấn của Misaque thực sự rắc rối. Tuy nhiên, dù có rắc rối đến đâu, sau thời gian dài suy nghĩ, cũng đủ để tôi nghĩ ra cách giải trừ phong ấn."
  },
  AvgDialog_65480_Content_58 = {
    Text = "Tự hủy thân thể, chuyển sang thân thể dự phòng của đóa. Rất đơn giản, phải không?"
  },
  AvgDialog_65480_Content_59 = {
    Text = "Lần sau nhớ tàn nhẫn hơn, hủy luôn cả não của tôi đi——nhưng rất tiếc, không có lần sau nữa."
  },
  AvgDialog_65480_Content_6 = {
    Text = "——Bạn nhận ra khuôn mặt này. Hơn một tháng trước, kẻ này đã xâm nhập vào Misaque, giả dạng đóa, gây ra hàng loạt vụ án nghiêm trọng, thậm chí suýt nữa kích nổ bom bạc tâm để tạo ra rã nứt lớn."
  },
  AvgDialog_65480_Content_60 = {
    Text = "Phá bỏ sương mù bên ngoài trường, phá hủy hồ đen, dẫn đến ý chí vô thượng…… tất cả những điều này đều là do bạn làm?"
  },
  AvgDialog_65480_Content_61 = {
    Text = "Là tôi. Bây giờ, chỉ còn một bước nữa là hoàn thành."
  },
  AvgDialog_65480_Content_62 = {
    Text = "Góc môi cô ấy khẽ nhếch lên, lộ ra một chiếc răng nhọn."
  },
  AvgDialog_65480_Content_63 = {
    Text = "Tôi đã đặt tín hiệu. Ngài đã nhìn thấy nơi này, nhìn thấy các người. Cánh cửa đó, đã không thể đóng lại."
  },
  AvgDialog_65480_Content_64 = {
    Text = "Bạn đã thua, Người Giữ Gìn."
  },
  AvgDialog_65480_Content_65 = {
    Text = "Dòng sóng âm thanh lớn từ phía sau cô ấy truyền đến, cơn gió từ vụ nổ làm tung lên mái tóc đỏ chói đầy ấn tượng của cô, tiếng cười sắc bén báo hiệu chiến thắng dường như xuyên thủng màng nhĩ của bạn."
  },
  AvgDialog_65480_Content_66 = {
    Text = "Sự thức tỉnh của Toghwa đang tăng tốc… Hãy ngăn cô ấy lại!"
  },
  AvgDialog_65480_Content_7 = {
    Text = "Sau khi hủy diệt chiều của mình, ánh mắt cô ấy đổ dồn về phía các ngươi. \nChính tay ngươi đã phong ấn cô ấy sâu trong hồ đen."
  },
  AvgDialog_65480_Content_8 = {
    Text = "Gây thương hại cho dân thường, gây ra sự rỗng mới... Tại sao? \"đóa\"."
  },
  AvgDialog_65480_Content_9 = {
    Text = "Bạn có đạt được bước đột phá mới trong nghiên cứu về rỗng ở một chiều khác không?"
  },
  AvgDialog_65481_Content_1 = {Text = "Lễ tế"},
  AvgDialog_65481_Content_10 = {Text = "Ramona..."},
  AvgDialog_65481_Content_11 = {
    Text = "Bạn vỗ nhẹ vào tay cô ấy, cố gắng che giấu sự bất an của mình, cười nhẹ nhàng với cô ấy."
  },
  AvgDialog_65481_Content_12 = {
    Text = "Để bạn, để tất cả các bạn… Tôi phải vào. Đây là trách nhiệm của tôi."
  },
  AvgDialog_65481_Content_13 = {
    Text = "Người giữ bí mật, bạn sẽ trở lại, bạn sẽ luôn chiến đấu bên cạnh tôi, cho đến ngày chúng ta tiêu diệt được rỗng rỗng… Nhớ lời hứa bạn đã nói với tôi nhé!"
  },
  AvgDialog_65481_Content_14 = {
    Text = "Bạn gật đầu một cách trang trọng. Đưa tay cô ấy ra, bạn quay người đối mặt với cánh cửa."
  },
  AvgDialog_65481_Content_15 = {Text = "Ding——"},
  AvgDialog_65481_Content_16 = {
    Text = "Cảm giác rung động từ ngực. Chiếc chìa khóa bạc dường như bị thu hút bởi điều gì đó, nổi lơ lửng trước mặt bạn."
  },
  AvgDialog_65481_Content_17 = {
    Text = "Từ chìa khóa bạc tỏa ra ánh sáng bạc mạnh mẽ, rồi nhanh chóng biến mất."
  },
  AvgDialog_65481_Content_18 = {
    Text = "Bạn nghe thấy tiếng gầm rền trầm. Hai cánh cửa vô tận và không thể chạm vào, từ từ mở ra phía sau."
  },
  AvgDialog_65481_Content_19 = {
    Text = "Ánh sáng tối từ bên trong cánh cửa tràn ra, bao quanh bạn."
  },
  AvgDialog_65481_Content_2 = {
    Text = "Cánh cửa mở ra đứng yên lặng trước mặt bạn, như một lời mời huyền bí và mê hoặc."
  },
  AvgDialog_65481_Content_20 = {
    Text = "Cánh cửa, Song Tử, hình bóng… mọi thứ xung quanh đều biến mất. Ánh sáng đen đưa bạn vào một chiều mới."
  },
  AvgDialog_65481_Content_21 = {
    Text = "Mọi thứ đều biến mất khỏi chiều này. Chỉ còn lại bóng tối thuần túy."
  },
  AvgDialog_65481_Content_26 = {
    Text = "Một quả cầu ánh sáng xuất hiện trước mặt bạn. Quả cầu thứ hai, thứ ba…"
  },
  AvgDialog_65481_Content_27 = {
    Text = "Màu sắc rực rỡ và biến ảo chảy trên bề mặt vô số quả cầu ánh sáng, giống như những bông hoa với họa tiết tinh tế, nở rộ và tan vỡ trong không gian tối tăm này."
  },
  AvgDialog_65481_Content_28 = {
    Text = "Trong những bọt nước sinh diệt không ngừng đó, bạn thấy khái niệm về màu sắc luôn chuyển động và xoay vòng trước mắt mình"
  },
  AvgDialog_65481_Content_29 = {
    Text = "Bạn thấy tất cả các chữ cái chồng lên nhau trong bong bóng thành một điểm, một bài thơ sử thi vĩ đại, bất tận"
  },
  AvgDialog_65481_Content_3 = {
    Text = "Mắt đó đã tạm thời biến mất sau khi được chuyển đến một chiều không gian khác, ánh sáng huyền bí chiếu qua khe cửa, soi rọi khuôn mặt do dự của bạn."
  },
  AvgDialog_65481_Content_30 = {
    Text = "Bạn thấy hình ảnh của quá khứ, hiện tại và tương lai. Bạn thấy mọi không-thời gian tồn tại và hủy diệt."
  },
  AvgDialog_65481_Content_31 = {
    Text = "Dường như có một tia sáng nở rộ trong cơ thể bạn, xuyên qua nội tạng và não bộ của bạn."
  },
  AvgDialog_65481_Content_32 = {
    Text = "Thể chất trí tuệ……Chekhoma……Daat……"
  },
  AvgDialog_65481_Content_33 = {
    Text = "Xin hãy cho tôi biết, tôi phải làm thế nào để đánh bại ý chí vô thượng. Tôi phải làm sao, mới có thể bảo vệ họ…"
  },
  AvgDialog_65481_Content_34 = {
    Text = "Chekhoma-Daat. Tên này vang lên rõ ràng trong không gian này."
  },
  AvgDialog_65481_Content_35 = {
    Text = "Một bong bóng nổi lên trước mặt bạn, bạn đưa ngón tay ra, chạm vào nó một cách thành kính."
  },
  AvgDialog_65481_Content_36 = {Text = "Pa——"},
  AvgDialog_65481_Content_37 = {
    Text = "Bong bóng vỡ thành vô số điểm sáng nhỏ trước mặt bạn. Những điểm sáng ấy bao quanh bạn, như một tấm màn mỏng manh, nhẹ nhàng phủ lên người bạn."
  },
  AvgDialog_65481_Content_38 = {
    Text = "Ngài là sự khởi đầu, là điểm kết thúc……Ngài chính là tất cả……"
  },
  AvgDialog_65481_Content_39 = {
    Text = "Ý chí vô thượng, không thể đánh bại."
  },
  AvgDialog_65481_Content_4 = {
    Text = "Người Giữ Bí Mật……"
  },
  AvgDialog_65481_Content_40 = {
    Text = "Giọng nói mờ mịt và xa xôi, từ bên trong mỗi bong bóng, từ trong não của bạn vang lên."
  },
  AvgDialog_65481_Content_41 = {
    Text = "Không… sức sống, nền văn minh, cảm xúc… Thế giới của chúng ta không thể bị hủy diệt như vậy!"
  },
  AvgDialog_65481_Content_42 = {
    Text = "Nhìn tôi. Lắng nghe tôi. Mảnh vỡ của mắt không có tròng. Ý thức của mắt không có tròng. Mặt tối của mắt không có tròng…"
  },
  AvgDialog_65481_Content_43 = {
    Text = "Ý thức, mặt tối… Ý ngài là gì?"
  },
  AvgDialog_65481_Content_44 = {
    Text = "Bạn ngẩng đầu lên, nhìn vào vô số bong bóng hư ảo trước mắt."
  },
  AvgDialog_65481_Content_45 = {
    Text = "Trước khi Người thức tỉnh, hãy đóng cánh cửa lại. Để ý chí vô thượng một lần nữa chìm vào giấc ngủ. Thế giới của bạn sẽ tạm thời giải thoát."
  },
  AvgDialog_65481_Content_46 = {
    Text = "Khi bạn khôi phục quyền lực của Bóng Tối, bạn sẽ có được sức mạnh để đóng cánh cửa."
  },
  AvgDialog_65481_Content_47 = {
    Text = "Thế giới của bạn, những người bạn quan tâm… họ không thể chịu đựng được lực lượng của phân mảnh ý chí vô thượng."
  },
  AvgDialog_65481_Content_48 = {
    Text = "Bạn sẽ từ bỏ mọi thứ, vĩnh viễn canh gác trước cánh cửa. \n Bạn sẽ chết, trong bóng tối không có ý thức, trải qua quãng thời gian dài đến vô tận…"
  },
  AvgDialog_65481_Content_49 = {
    Text = "Những phân mảnh của mắt không có tròng, chính là cái giá mà bạn phải trả."
  },
  AvgDialog_65481_Content_5 = {
    Text = "Thấy bạn quay đầu lại, cô ấy hơi cúi đầu xuống, nhưng tay kéo góc áo bạn không có chút ý định buông ra."
  },
  AvgDialog_65481_Content_50 = {
    Text = "Trên bong bóng trước mặt, bạn thấy khuôn mặt của mình."
  },
  AvgDialog_65481_Content_51 = {
    Text = "Mồ hôi lạnh lăn dài trên khuôn mặt đó. Nó run lên vì lạnh, vì sợ hãi."
  },
  AvgDialog_65481_Content_52 = {
    Text = "Bạn tưởng tượng về cái chết không hoàn toàn, dài đằng đẵng, sự cô đơn vĩnh cửu sẽ khiến mọi sức sống trở nên điên rồ."
  },
  AvgDialog_65481_Content_53 = {
    Text = "Không còn cách nào khác sao…… tôi đã thề với Ramona, tôi đã hứa với họ……"
  },
  AvgDialog_65481_Content_54 = {
    Text = "Mắt Ngài đã mở. Đối kháng với sức mạnh của Ngài, đóng cánh cửa lại, để Ngài một lần nữa chìm vào giấc ngủ. Đây là con đường duy nhất."
  },
  AvgDialog_65481_Content_55 = {
    Text = "Chọn đi."
  },
  AvgDialog_65481_Content_56 = {
    Text = "Thời gian dường như đã ngừng trôi. Cuối cùng, bạn có thể nhìn rõ những màu sắc huyền ảo xung quanh mình."
  },
  AvgDialog_65481_Content_57 = {
    Text = "Tất cả những hình ảnh trong ký ức của bạn đang chảy trên đó."
  },
  AvgDialog_65481_Content_58 = {
    Text = "Lần đầu tiên nắm chìa khóa bạc… Lần đầu tiên liên kết với thân thể được đánh thức… Lần đầu tiên đóng rỗng rỗng nứt…"
  },
  AvgDialog_65481_Content_59 = {
    Text = "Vô số hình ảnh, vô số khuôn mặt, nhìn về phía bạn."
  },
  AvgDialog_65481_Content_6 = {Text = "Ramona?"},
  AvgDialog_65481_Content_60 = {
    Text = "Bạn hít sâu một hơi, ngước lên."
  },
  AvgDialog_65481_Content_61 = {
    Text = "Tôi……đồng ý."
  },
  AvgDialog_65481_Content_62 = {
    Text = "Tôi……đồng ý."
  },
  AvgDialog_65481_Content_63 = {
    Text = "Tạm biệt mọi thứ với ngươi, phân mảnh của mắt không có tròng. \nBên cạnh ngươi, sẽ chỉ còn lại những thực thể vô thức được tạo ra bằng quyền hạn và ký ức."
  },
  AvgDialog_65481_Content_64 = {
    Text = "Cắt đứt liên kết giữa bạn và thân thể được đánh thức bằng chính tay mình. \nHãy để thân thể của bạn lặng lẽ chìm vào hỗn loạn và bóng tối thuần túy."
  },
  AvgDialog_65481_Content_65 = {
    Text = "Sau đó, tôi sẽ giúp bạn, tiếp nhận quyền năng của ba thực thể."
  },
  AvgDialog_65481_Content_66 = {
    Text = "Tôi sẽ giúp bạn trở thành vị thần."
  },
  AvgDialog_65481_Content_7 = {
    Text = "Tôi có một dự cảm không tốt…"
  },
  AvgDialog_65481_Content_8 = {
    Text = "Một phiên bản khác của tôi, đã từng chứng kiến vô số sự lựa chọn. Tôi không có ký ức của cô ấy, nhưng…"
  },
  AvgDialog_65481_Content_9 = {
    Text = "Tôi biết, kết quả sau cánh cửa này, sẽ không phải là điều tôi muốn thấy…"
  },
  AvgDialog_65482_Content_1 = {
    Text = "Misaque từng hứa với tôi rằng, sẽ cùng tôi chiến đấu… chiến đấu đến tận ngày tận thế của hành tinh này."
  },
  AvgDialog_65482_Content_10 = {
    Text = "Tôi sẽ không còn bị kiểm soát, không còn gây thương cho bất kỳ ai, không còn để bạn bè phải chết vì tôi."
  },
  AvgDialog_65482_Content_11 = {
    Text = "Bạn còn nhớ những gì đã nói với tôi lúc đó không?"
  },
  AvgDialog_65482_Content_12 = {
    Text = "Bạn nói… tôi chưa bao giờ cô đơn, tôi còn có bạn, còn có mọi người."
  },
  AvgDialog_65482_Content_13 = {
    Text = "Từ giây phút đó, tôi đã biết.."
  },
  AvgDialog_65482_Content_14 = {
    Text = "Tôi sẵn sàng làm bất cứ điều gì, miễn là cho các bạn."
  },
  AvgDialog_65482_Content_15 = {
    Text = "Cảm ơn bạn, cảm ơn tất cả mọi người… Tôi xin nhờ một điều cuối cùng, mong các bạn giúp đỡ…"
  },
  AvgDialog_65482_Content_16 = {
    Text = "Đừng quên tôi nhé."
  },
  AvgDialog_65482_Content_17 = {
    Text = "Đừng quên tôi nhé."
  },
  AvgDialog_65482_Content_18 = {
    Text = "Cô gái đột nhiên nhìn chằm chằm vào bạn, nhìn bạn đang ngồi yên trên tảng đá ngầm."
  },
  AvgDialog_65482_Content_19 = {
    Text = "Những đốm sáng nhảy nhót trong đôi mắt, còn trên gương mặt non nớt ấy, nở một nụ cười rực rỡ khác thường."
  },
  AvgDialog_65482_Content_2 = {
    Text = "Nếu biết trước như vậy, tôi tuyệt đối sẽ không đồng ý với các người…"
  },
  AvgDialog_65482_Content_20 = {
    Text = "Đóa bách hợp bị thời gian giam cầm, lỡ mất mùa hoa——"
  },
  AvgDialog_65482_Content_21 = {
    Text = "Cuối cùng cũng đón được khoảnh khắc nở rộ."
