  AvgDialog_65482_Content_23 = {
    Text = "Tôi đã làm được… Tôi đã thật sự làm được!"
  },
  AvgDialog_65482_Content_24 = {
    Text = "Tôi……đã xuyên thủng……Ngài sẽ không bao giờ được sinh ra nữa……"
  },
  AvgDialog_65482_Content_25 = {
    Text = "Như vậy……"
  },
  AvgDialog_65482_Content_26 = {
    Text = "Tay nắm chặt chuôi dao buông thõng xuống, chất lỏng đỏ tươi, sánh đặc và đen ngòm từ lưỡi dao tuôn ra, len qua kẽ tay rồi tan vào đại dương."
  },
  AvgDialog_65482_Content_27 = {
    Text = "Máu chảy nhanh khỏi thân thể, sắc da của Muphí trắng bệch vô cùng, nhưng toàn thân lại tỏa ra một sức sống kỳ lạ."
  },
  AvgDialog_65482_Content_28 = {
    Text = "Máu chảy nhanh khỏi thân thể, sắc da của Muphí trắng bệch vô cùng, nhưng toàn thân lại tỏa ra một sức sống kỳ lạ."
  },
  AvgDialog_65482_Content_29 = {
    Text = "Dù đêm dài vẫn tối, dù ánh sáng le lói, tinh thần không bao giờ từ bỏ của họ mới thực sự có thể thay đổi tương lai đã được định trước."
  },
  AvgDialog_65482_Content_3 = {
    Text = "Hãy để tôi chứng kiến điều đó——tương lai của Misaque, rốt cuộc được giao phó cho chỉ huy nào."
  },
  AvgDialog_65482_Content_30 = {
    Text = "Bây giờ, tôi đã tìm ra một câu trả lời mới."
  },
  AvgDialog_65482_Content_31 = {
    Text = "Vậy nên, cậu cũng phải rộng rãi một chút, cho tôi mượn người được truyền thừa của cậu nhé?"
  },
  AvgDialog_65482_Content_32 = {
    Text = "Tôi sẵn lòng tin tưởng người trước mặt này, giao phó hạt giống lửa cho {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_65482_Content_33 = {
    Text = "Hạt giống này cuối cùng sẽ nảy mầm, lớn lên thành cây cổ thụ,"
  },
  AvgDialog_65482_Content_34 = {
    Text = "Giống như ngày cây mẹ đầu tiên ra đời."
  },
  AvgDialog_65482_Content_36 = {
    Text = "Đây là hạt giống cuối cùng, tôi sẽ để nó trong cơ thể bạn ."
  },
  AvgDialog_65482_Content_37 = {
    Text = "Trước khi nó lan truyền dòng máu của tôi đến mặt đất, ngươi, tuyệt đối không được chết…"
  },
  AvgDialog_65482_Content_38 = {
    Text = "Luôn nhớ đến tôi, đừng quên tôi."
  },
  AvgDialog_65482_Content_39 = {
    Text = "Sóng triều dâng cao."
  },
  AvgDialog_65482_Content_4 = {
    Text = "Hãy để tôi chứng kiến điều đó——tương lai của Misaque, rốt cuộc được giao phó cho chỉ huy nào."
  },
  AvgDialog_65482_Content_40 = {
    Text = "Vòng tay ấm áp đã đẩy bạn ra."
  },
  AvgDialog_65482_Content_41 = {
    Text = "Trong làn nước cuồn cuộn, bạn thấy cô ấy trôi dần vào vùng sâu thẳm của dòng sông."
  },
  AvgDialog_65482_Content_42 = {
    Text = "Trong làn nước cuồn cuộn, bạn thấy cô ấy trôi dần vào vùng sâu thẳm của dòng sông."
  },
  AvgDialog_65482_Content_43 = {
    Text = "Bây giờ? Ở đây?"
  },
  AvgDialog_65482_Content_44 = {
    Text = "Chỉ sớm một chút xíu, nhưng không sao cả, phải không?"
  },
  AvgDialog_65482_Content_45 = {
    Text = "Từ một năm trước, tôi đã mong chờ đến ngày hôm nay."
  },
  AvgDialog_65482_Content_46 = {
    Text = "Mưa nhẹ làm ẩm ướt đầu ngón tay, dòng điện yếu ớt xuyên qua găng tay, chảy dọc theo làn da của bạn và đầu ngón tay của cô ấy một cách kín đáo."
  },
  AvgDialog_65482_Content_47 = {
    Text = "Cảm xúc kỳ lạ theo dòng điện kích thích dây thần kinh của bạn, đó là niềm vui, sự hân hoan, lo lắng và……"
  },
  AvgDialog_65482_Content_48 = {
    Text = "……<Yellow:hy vọng>."
  },
  AvgDialog_65482_Content_49 = {
    Text = "Thật ấm áp… Liên kết tinh thần rất ổn định, tinh thần và sức sống của bạn chưa bao giờ mạnh mẽ như hôm nay."
  },
  AvgDialog_65482_Content_5 = {
    Text = "Không sao cả, Người Giữ Gìn."
  },
  AvgDialog_65482_Content_50 = {
    Text = "Bạn không thể ngã xuống dễ dàng đâu, <Yellow:duy nhất trên thế giới> Người Giữ Gìn. \n\nChúng tôi còn trông cậy vào bạn để điều tra và ghi chép lại toàn bộ lịch sử bị xóa sổ bởi sự rỗng rỗng."
  },
  AvgDialog_65482_Content_51 = {
    Text = "Nỗi lo lắng trong đáy mắt tan biến, Ramona mỉm cười nửa đùa nửa thật, tạo nên một nụ cười an ủi."
  },
  AvgDialog_65482_Content_52 = {
    Text = "Tiếng mưa lất phất lấp đầy trời đất."
  },
  AvgDialog_65482_Content_53 = {
    Text = "Tiếng mưa lất phất lấp đầy trời đất."
  },
  AvgDialog_65482_Content_54 = {
    Text = "Ramona... Ramona.."
  },
  AvgDialog_65482_Content_55 = {
    Text = "Từng đoạn ký ức đang biến mất. Từng khuôn mặt bị xóa bỏ."
  },
  AvgDialog_65482_Content_56 = {
    Text = "Câu chuyện quá khứ bị lưu đày đến rìa trí óc, bạn đã chuyển từ vai trò nhân vật chính sang người quan sát."
  },
  AvgDialog_65482_Content_57 = {
    Text = "Trái tim ban đầu như bị dao cắt, dần dần trở nên tê liệt."
  },
  AvgDialog_65482_Content_58 = {
    Text = "Bạn thấy mình rời khỏi mặt đất, đến sâu trong các vì sao."
  },
  AvgDialog_65482_Content_59 = {
    Text = "Những thứ từng ở bên mình ngày càng xa cách, cho đến khi biến mất hẳn."
  },
  AvgDialog_65482_Content_6 = {
    Text = "Hiệp sĩ tồn tại là để bảo vệ tất cả mọi người, Orci nhất định có thể kiên cường đứng vững!"
  },
  AvgDialog_65482_Content_60 = {
    Text = "Không có Ramona. Cũng không có kẻ canh gác bí mật."
  },
  AvgDialog_65482_Content_61 = {
    Text = "Khi bạn rời khỏi đây, bạn và họ sẽ không còn bất kỳ mối quan hệ nào nữa ."
  },
  AvgDialog_65482_Content_62 = {
    Text = "……Tôi hiểu, Khechma-Đaát."
  },
  AvgDialog_65482_Content_63 = {
    Text = "Bạn ngẩng đầu lên. Trong thế giới bọt nước vô tận này, bạn đối thoại với vị thần minh hư vô."
  },
  AvgDialog_65482_Content_64 = {
    Text = "Hãy cho tôi biết, tên của bạn."
  },
  AvgDialog_65482_Content_65 = {
    Text = "Tôi là %player%. Tôi là Người Giữ Gìn. Tôi là… mắt không có tròng."
  },
  AvgDialog_65482_Content_66 = {
    Text = "Nhiệm vụ của bạn đã hoàn thành. Hãy rời khỏi chiều không gian này, Khekho-ma Da-at."
  },
  AvgDialog_65482_Content_67 = {
    Text = "Tôi sẽ ngăn chặn Ngài."
  },
  AvgDialog_65482_Content_68 = {
    Text = "Tôi sẽ ngăn chặn… chính mình."
  },
  AvgDialog_65482_Content_7 = {
    Text = "Hiệp sĩ tồn tại là để bảo vệ tất cả mọi người, Orci nhất định có thể kiên cường đứng vững!"
  },
  AvgDialog_65482_Content_8 = {
    Text = "Tôi sợ hãi tột độ, sợ chính mình sắp trở thành thứ gì đó. Nhưng tất cả điều này không còn quan trọng nữa."
  },
  AvgDialog_65482_Content_9 = {
    Text = "Tôi sẽ không còn bị kiểm soát, không còn gây thương cho bất kỳ ai, không còn để bạn bè phải chết vì tôi."
  },
  AvgDialog_65948_Content_1 = {Text = "Lalalala"},
  AvgDialog_65948_Content_2 = {
    Text = "Giọng nói của cô bị bóp méo bởi cảm giác quen thuộc, tan biến thành những lời thì thầm khó lòng nhận ra."
  },
  AvgDialog_65948_Content_3 = {
    Text = "……Cái gì?"
  },
  AvgDialog_65948_Content_4 = {
    Text = "Một khi ánh mắt @3 thực sự đến, mọi thứ đều sẽ đi đến kết thúc. Trước khi thời điểm cuối cùng đến, bạn có thể tháo vòng cổ của Misaque và bước vào vòng tay của tôi."
  },
  AvgDialog_65948_Content_5 = {
    Text = "Cô ấy chẳng màng đến phản ứng của bạn, chỉ tự mình thổ lộ lời mời đầy ám ảnh, vừa nồng nàn vừa chân thực, như thể một người tình thì thầm những lời yêu thương vào tai bạn trong màn đêm tĩnh lặng."
  },
  AvgDialog_65948_Content_6 = {
    Text = "Tôi sẽ ở đây quan sát bạn."
  },
  AvgDialog_65948_Content_7 = {
    Text = "Rất nhanh, đóa bị tách ra khỏi bạn và bị thêm nhiều xiềng xích. Cô ấy không có bất kỳ phản ứng nào, ngoan ngoãn như một con rối thực sự, chỉ có đôi mắt luôn nhìn chằm chằm vào bạn, dường như có thể xuyên thấu tất cả, mãi mãi dõi theo linh hồn của bạn."
  },
  AvgDialog_65948_Content_8 = {
    Text = "Giống như đang chờ đợi một cuộc tái ngộ đầy mong đợi."
  },
  AvgDialog_66597_Content_1 = {
    Text = "Misaque từng hứa với tôi rằng, sẽ cùng tôi chiến đấu… chiến đấu đến tận ngày tận thế của hành tinh này."
  },
  AvgDialog_66597_Content_10 = {
    Text = "Tôi sẽ không còn bị kiểm soát, không còn gây thương cho bất kỳ ai, không còn để bạn bè phải chết vì tôi."
  },
  AvgDialog_66597_Content_11 = {
    Text = "Bạn còn nhớ những gì đã nói với tôi lúc đó không?"
  },
  AvgDialog_66597_Content_12 = {
    Text = "Bạn nói… tôi chưa bao giờ cô đơn, tôi còn có bạn, còn có mọi người."
  },
  AvgDialog_66597_Content_13 = {
    Text = "Từ giây phút đó, tôi đã biết.."
  },
  AvgDialog_66597_Content_14 = {
    Text = "Tôi sẵn sàng làm bất cứ điều gì, miễn là cho các bạn."
  },
  AvgDialog_66597_Content_15 = {
    Text = "Cảm ơn bạn, cảm ơn tất cả mọi người… Tôi xin nhờ một điều cuối cùng, mong các bạn giúp đỡ…"
  },
  AvgDialog_66597_Content_16 = {
