  AvgDialog_66599_Content_28 = {
    Text = "Không… sức sống, nền văn minh, cảm xúc… Thế giới của chúng ta không thể bị hủy diệt như vậy!"
  },
  AvgDialog_66599_Content_29 = {
    Text = "Nhìn tôi. Lắng nghe tôi. Mảnh vỡ của mắt không có tròng. Ý thức của mắt không có tròng. Mặt tối của mắt không có tròng…"
  },
  AvgDialog_66599_Content_3 = {
