  AvgDialog_66599_Content_34 = {
    Text = "Thế giới của bạn, những người bạn quan tâm… họ không thể nào chịu nổi lực lượng từ những mảnh vỡ của ý chí vô thượng."
  },
  AvgDialog_66599_Content_35 = {
