  AvgDialog_6770_Content_49 = {Text = "Rầm!!!"},
  AvgDialog_6770_Content_5 = {
    Text = "Các người chính là một bọn! Lũ lừa đảo của Misaque!"
  },
  AvgDialog_6770_Content_50 = {
    Text = "<Shake:à——>"
  },
  AvgDialog_6770_Content_51 = {
    Text = "Anh/chị lớn {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}!!!"
  },
  AvgDialog_6770_Content_52 = {
    Text = "Vật thể khổng lồ lơ lửng trên không trung đột ngột rơi xuống. Một tiếng nổ vang rền như xé toạc đỉnh núi, khiến tảng đá dưới chân các ngươi vỡ vụn."
  },
  AvgDialog_6770_Content_53 = {
    Text = "Bạn bước hụt chân và cùng với Hiro rơi xuống thung lũng sâu."
  },
  AvgDialog_6770_Content_54 = {
    Text = "——Trong những tiếng kêu sợ hãi của các bạn, Hiro nhe răng và lần đầu tiên cười lớn."
  },
  AvgDialog_6770_Content_6 = {Text = "Tôi……"},
  AvgDialog_6770_Content_7 = {
    Text = "Hãy tỉnh táo một chút! Nếu không phải nhờ sự giúp đỡ của %player%, chúng ta đã chết trên ngọn núi này mười lần liền!"
  },
  AvgDialog_6770_Content_8 = {
    Text = "Hướng dẫn viên dùng sức lắc vai của đội viên. Dưới ánh mắt nghiêm nghị và lời nói đầy quyền uy của anh ta, đội viên đó cuối cùng cũng bình tĩnh lại một chút."
  },
  AvgDialog_6770_Content_9 = {
    Text = "Cảm ơn rất nhiều……"
  },
  AvgDialog_6773_Content_1 = {Text = "Tái ngộ"},
  AvgDialog_6773_Content_10 = {
    Text = "Lily… hãy chạy đi! … đây rất nguy hiểm…"
  },
  AvgDialog_6773_Content_100 = {
    Text = "Chúng ta phải nhanh chóng rời đi, còn phải mang theo Lily cùng những người khác."
  },
  AvgDialog_6773_Content_101 = {
    Text = "Hiro nhìn quanh một lượt."
  },
  AvgDialog_6773_Content_102 = {
    Text = "Lily đâu? Cô ấy không phải luôn ở bên cạnh bạn sao?"
  },
  AvgDialog_6773_Content_103 = {
    Text = "Chúng ta vừa bị quái vật đẩy xuống vực thẳm, Lily và vài người sống sót vẫn còn ở trên đó. \nPhải tìm họ, xác nhận họ an toàn rồi nhanh chóng đưa họ đi."
  },
  AvgDialog_6773_Content_104 = {
    Text = "Dưới những vết nứt trên mặt hồ, lẩn khuất vô số bí mật đen tối. Những bọc mủ đen từ các vết nứt không ngừng mở rộng của tầng băng tuôn trào ra, bao vây chúng ta."
  },
  AvgDialog_6773_Content_105 = {
    Text = "Lily và Aivis vẫn đang trong tình trạng nguy hiểm, ở đây lại không thể thoát thân…"
  },
  AvgDialog_6773_Content_106 = {
    Text = "Hai hình bóng của Hiro cùng lúc rung động, nghe thấy những tiếng thúc giục mạnh mẽ từ sâu thẳm trong linh hồn."
  },
  AvgDialog_6773_Content_107 = {
    Text = "Lại là… giọng nói đó."
  },
  AvgDialog_6773_Content_108 = {
    Text = "Một \"Hiro\" khác điều khiển xích cầu đập ra một hố sâu, vô số khối u nhầy từ hố bò lên, từ mặt đất bám dính vào xích cầu của cô ấy."
  },
  AvgDialog_6773_Content_109 = {
    Text = "Mụn mủ ngọ nguậy thân thể, từ bốn phương tám hướng tụ tập lại, còn cô ấy thì đột nhiên dừng lại."
  },
  AvgDialog_6773_Content_11 = {
    Text = "Giọng của người hướng dẫn đang run rẩy. Đối mặt với nỗi sợ hãi chưa từng trải qua trong cuộc đời, người bình thường này lấy hết can đảm, đứng trước mặt Lily."
  },
  AvgDialog_6773_Content_110 = {
    Text = "Trên khuôn mặt cô ấy, một nụ cười điên cuồng dần hiện lên."
  },
  AvgDialog_6773_Content_111 = {
    Text = "Đúng… là cái này… chính là cái này!"
  },
  AvgDialog_6773_Content_112 = {
    Text = "Là @3! Ngài thấy chúng ta rồi, Hiro… Ngài đang gọi chúng ta!"
  },
  AvgDialog_6773_Content_113 = {
    Text = "Hãy cùng chúng tôi thoát khỏi nơi này!"
  },
  AvgDialog_6773_Content_114 = {
    Text = "Không, tôi đến đây với mục đích khác, không phải để trốn."
  },
  AvgDialog_6773_Content_115 = {
    Text = "Đừng ngốc nghếch! Những mụt mủ này sẽ không ngừng tuôn ra, tiếp tục như vậy, bạn sẽ bị nuốt chửng!"
  },
  AvgDialog_6773_Content_116 = {
    Text = "Nếu, nếu tôi tiêu thụ nó thì như thế nào?"
  },
  AvgDialog_6773_Content_117 = {Text = "Cái gì?"},
  AvgDialog_6773_Content_118 = {
    Text = "Những mụn mủ này thuộc về ngọn núi này. Ngươi cũng cảm nhận được, phải không Hiro? Nó luôn kêu gọi chúng ta quay trở lại. Đây là số phận của chúng ta."
  },
  AvgDialog_6773_Content_119 = {
    Text = "Đến đây, Hiro, hãy cùng tôi hòa nhập với ngọn núi này, cùng tôi đối mặt với số phận chung của chúng ta…"
  },
  AvgDialog_6773_Content_12 = {
    Text = "Anh cố gắng chắn cho cô khỏi cái lạnh thấu xương của tử thần. Anh đối mặt với số phận không thể tránh khỏi."
  },
  AvgDialog_6773_Content_120 = {
    Text = "Nó muốn tiêu thụ chúng ta,hấp thụ lực lượng của chúng ta,vậy thì ngược lại,chúng ta cũng có thể tiêu thụ nó!"
  },
  AvgDialog_6773_Content_121 = {
    Text = "Hiro với vẻ mặt lạnh lùng đứng bên cạnh bạn."
  },
  AvgDialog_6773_Content_122 = {
    Text = "Ngay cả một thực thể như tôi cũng không thể chống lại sự điên rồ do lực lượng to lớn này mang lại, đừng nói đến một phân mảnh từ chiều khác như bạn."
  },
  AvgDialog_6773_Content_123 = {
    Text = "Hừ… Nếu sợ thì mau đi đi, kẻ yếu đuối. Các người không phải đi tìm người sao?"
  },
  AvgDialog_6773_Content_124 = {
    Text = "Hãy yên tâm, đợi tôi nuốt chửng chúng, tôi sẽ tìm các người sau. \nKhi đó, tôi sẽ nuốt chửng luôn cả các người."
  },
  AvgDialog_6773_Content_125 = {
    Text = "Đến đây, tất cả hãy đến đây! Đưa thêm cho tôi, càng nhiều càng tốt……"
  },
  AvgDialog_6773_Content_126 = {
    Text = "……chúng ta đi thôi."
  },
  AvgDialog_6773_Content_127 = {Text = "Hilo?"},
  AvgDialog_6773_Content_128 = {
    Text = "Không biết tên điên này muốn làm gì. Thay vì ở đây phát điên với cô ta, chúng ta có việc quan trọng hơn. Tôi sẽ giúp bạn tìm Lily."
  },
  AvgDialog_6773_Content_13 = {
    Text = "Lily bước lên vài bước, đứng trước người hướng dẫn."
  },
  AvgDialog_6773_Content_14 = {
    Text = "Anh/chị lớn {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn} nói, Lily rất giỏi. Vì vậy, Lily sẽ bảo vệ các bạn."
  },
  AvgDialog_6773_Content_15 = {
    Text = "Lily! A——"
  },
  AvgDialog_6773_Content_16 = {
    Text = "Sự lạnh giá tăng nhanh đã chích điện lưỡi và miệng của anh. Cảm giác như bị đóng băng trong nitơ lỏng âm hàng trăm độ, không một tế bào nào trong não anh có thể di chuyển dù chỉ một chút."
  },
  AvgDialog_6773_Content_17 = {
    Text = "Sự lạnh lẽo tột độ, có thể làm đông cứng suy nghĩ trong chớp mắt và biến chúng thành bụi."
  },
  AvgDialog_6773_Content_18 = {
    Text = "Hướng dẫn viên và thân thể của Aivs đông cứng thành tượng băng, bị cuồng phong quật ngã xuống tuyết, cái lạnh tột độ lan tỏa tới đầu ngón tay của Lily."
  },
  AvgDialog_6773_Content_19 = {
    Text = "Bạn,đã làm gì?"
  },
  AvgDialog_6773_Content_2 = {
    Text = "Đây… ẩn chứa một con quái vật khổng lồ như vậy…"
  },
  AvgDialog_6773_Content_20 = {
    Text = "Bạn @3……không @2……"
  },
  AvgDialog_6773_Content_21 = {
    Text = "Lily cau mày, ánh mắt chuyển từ hướng dẫn sang quái vật khổng lồ đang bay lơ lửng trên không trung."
  },
  AvgDialog_6773_Content_22 = {
    Text = "Quái vật màu xanh lam huỳnh quang rít lên những lời độc ác, tuyết ào ạt tuôn ra lướt qua má Lily, nhưng cô vẫn giữ nguyên biểu cảm trên khuôn mặt."
  },
  AvgDialog_6773_Content_23 = {
    Text = "Lily, nghe lời người anh/chị {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}, bảo vệ mọi người."
  },
  AvgDialog_6773_Content_24 = {
    Text = "Quả cầu đen nhẵn bóng lớn tụ hình từ đầu ngón tay cô. Lily đưa ra một ngón tay, chỉ vào quái vật màu xanh huỳnh quang đang bay lơ lửng."
  },
  AvgDialog_6773_Content_25 = {
    Text = "Bạn không được, thương họ!"
  },
  AvgDialog_6773_Content_27 = {
    Text = "Lily… Giáo sư Avis?…"
  },
  AvgDialog_6773_Content_28 = {
    Text = "Không có ai trả lời bạn. Bạn mơ màng mở mắt, cảm thấy phía sau lưng ẩm ướt, chiếc áo khoác thấm đẫm nước tuyết đang bị bóp chặt và kéo căng."
  },
  AvgDialog_6773_Content_29 = {
    Text = "Ừm…… đây là cái gì?!"
  },
  AvgDialog_6773_Content_3 = {
    Text = "Đây…… Đây là…… cái gì vậy……"
  },
  AvgDialog_6773_Content_30 = {
    Text = "Bạn rơi xuống một mặt hồ đóng băng, dưới thân bị đập thành một hố sâu. Từ những khe nứt trên mặt băng không ngừng trào ra những quả cầu mềm mại giống như mụn mủ đen."
  },
  AvgDialog_6773_Content_31 = {
    Text = "Bạn hoảng hốt và lập tức tránh xa cái hố sâu này."
  },
  AvgDialog_6773_Content_32 = {
    Text = "Không có sự phong tỏa của bạn, những bọc mủ đen ngòm dưới mặt băng đồng loạt trào lên, nhanh chóng lan rộng tới tận mép hồ băng."
  },
  AvgDialog_6773_Content_33 = {
    Text = "Khoan đã, hình như đây không phải là rỗng rỗng?"
  },
  AvgDialog_6773_Content_34 = {
    Text = "Á á á——ứh á——"
  },
  AvgDialog_6773_Content_35 = {
    Text = "Hiro bao phủ bởi những mụn mủ đen, như thể chịu tác động của một loại cảm ứng, thân thể run rẩy mạnh mẽ theo sự chuyển động điên rồ của chúng."
  },
  AvgDialog_6773_Content_36 = {
    Text = "Cô ta cuồng nộ vung chiếc xích cầu khổng lồ của mình, đập nát những thứ vật chất đen tràn ra từ vết nứt, sau đó tấn công về phía bạn."
  },
  AvgDialog_6773_Content_37 = {
    Text = "!!!Hiro!Hãy bình tĩnh lại!"
  },
  AvgDialog_6773_Content_38 = {
    Text = "Trong còng kinh của Hiro tỏa ra hơi đen, chìa khóa bạc trên ngực bạn phát sáng mạnh mẽ."
  },
  AvgDialog_6773_Content_39 = {
    Text = "Bạn có thể cảm nhận rõ ràng rằng liên kết đang bị tấn công dữ dội, việc duy trì nó chỉ miễn cưỡng cũng trở nên vô cùng khó khăn."
  },
  AvgDialog_6773_Content_4 = {
    Text = "Đối mặt với con quái vật khổng lồ chưa từng thấy, anh ta đã dùng hết sức lực của mình, mới đủ sức đứng vững."
  },
  AvgDialog_6773_Content_40 = {
    Text = "Khuôn mặt đầy chất lỏng đen dính của cô ấy hiện lên nụ cười méo mó kỳ lạ, bóng xích trong tay cô như một món đồ chơi, vung lên, từng bước tiến về phía bạn."
  },
  AvgDialog_6773_Content_41 = {
    Text = "Tôi cảm nhận được…… tiếng gọi của núi……"
  },
  AvgDialog_6773_Content_42 = {
    Text = "Bạn muốn làm gì?!"
  },
  AvgDialog_6773_Content_43 = {
    Text = "Liên kết, không còn cần thiết tồn tại!"
  },
  AvgDialog_6773_Content_44 = {
    Text = "Quả cầu xích rít lên, mắt thấy sắp rơi trúng đầu bạn——"
  },
  AvgDialog_6773_Content_45 = {
    Text = "Rầm——"
  },
  AvgDialog_6773_Content_46 = {
    Text = "Tiếng động lớn nổ lên trên đầu bạn. Bạn từ từ dời cánh tay che trước mắt một cách bản năng."
  },
  AvgDialog_6773_Content_47 = {
    Text = "Đủ rồi, hãy dừng lại."
  },
  AvgDialog_6773_Content_48 = {
    Text = "Quả bóng bị đánh bay, ngã quỵ sang một bên với vẻ thất vọng."
  },
  AvgDialog_6773_Content_49 = {
    Text = "Trong làn gió lạnh thấu xương, bóng đen quen thuộc ấy luôn cầm vũ khí đứng chắn ngay trước mặt bạn."
  },
  AvgDialog_6773_Content_5 = {
    Text = "\"Ầm ầm——\""
  },
  AvgDialog_6773_Content_50 = {
    Text = "Rầm——"
  },
  AvgDialog_6773_Content_51 = {
    Text = "\"Hiro\" vung chiếc xích cự đại, chẻ nứt một đám mụn mủ đen, dư lực quét qua lớp băng bao quanh khối đá, núi non phát ra tiếng than khóc tan vỡ."
  },
  AvgDialog_6773_Content_52 = {
    Text = "Gai và quả cầu va chạm dữ dội, hai người đối đầu trong mắt bắn ra tia lửa, hướng về đối phương tuôn trào cơn giận chưa tắt."
  },
  AvgDialog_6773_Content_53 = {
    Text = "Bóng đen chặn trước mặt bạn, dũng cảm đỡ lấy quả cầu xích cuồng nộ của \"Hiro\", lùi vài bước về sau."
  },
  AvgDialog_6773_Content_54 = {
    Text = "Gió lạnh rít lên, thổi tung chiếc áo choàng bị mảnh gai sắt xé nát, lộ ra khuôn mặt quen thuộc."
  },
  AvgDialog_6773_Content_55 = {Text = "Hiro?!!!"},
  AvgDialog_6773_Content_56 = {
    Text = "Bạn cuối cùng cũng xuất hiện... Tôi đã chờ bạn từ rất lâu rồi!"
  },
  AvgDialog_6773_Content_57 = {
    Text = "Bạn quá chậm."
  },
  AvgDialog_6773_Content_58 = {
    Text = "Cô ta ném gai nhầy cô đặc trong tay ra, đâm thủng một cách dứt khoát các vết loét đặc quánh trên người \"Hiro\", để lại một chuỗi dấu đen trên nền tuyết."
  },
  AvgDialog_6773_Content_59 = {
    Text = "Hiro, cậu… chính là cái bóng đen luôn theo sau chúng ta?!"
  },
  AvgDialog_6773_Content_6 = {
    Text = "Một tiếng động lớn vang lên, Lily chặn được cuộc tấn công của quái vật, trọng tâm hơi mất ổn định, cô loạng choạng vài bước, nhưng vẫn chăm chú nhìn quái vật phía xa."
  },
  AvgDialog_6773_Content_60 = {
    Text = "Là tôi. Tôi cảm nhận được lời gọi, đã đến đây——giống như cô ấy."
  },
  AvgDialog_6773_Content_61 = {
    Text = "Tại sao không ra gặp tôi?"
  },
  AvgDialog_6773_Content_62 = {
    Text = "Một lực lượng đồng nguồn đã dẫn tôi đến đây, tôi muốn xem cô ấy rốt cuộc muốn làm gì."
  },
  AvgDialog_6773_Content_63 = {
    Text = "Sau đó, tôi đã nhìn thấy con quái vật."
  },
  AvgDialog_6773_Content_64 = {
    Text = "Bạn đã từng giúp tôi. Giúp bạn giải quyết rắc rối, như vậy chúng ta sẽ không còn nợ nhau gì nữa."
  },
  AvgDialog_6773_Content_65 = {
    Text = "Quái vật?"
  },
  AvgDialog_6773_Content_66 = {
    Text = "Con quái vật đã săn lùng và đẩy các thành viên đội thám hiểm của các người xuốngvách đá."
  },
  AvgDialog_6773_Content_67 = {
    Text = "Vậy những người mất tích đều là.."
  },
  AvgDialog_6773_Content_68 = {
    Text = "Ừm. Quái vật đang rình rập phía sau các bạn, chuẩn bị tấn công."
  },
  AvgDialog_6773_Content_69 = {
    Text = "Tôi đã cố gắng ngăn cản và bảo vệ vài người. Họ đã sống sót, nhưng sau đó bị quái vật bắt vào hang ổ của nó."
  },
  AvgDialog_6773_Content_7 = {
    Text = "@3con cái……@2ở đây@3……"
  },
  AvgDialog_6773_Content_70 = {
    Text = "Nếu bạn là Hiro, vậy cô ấy là?…"
  },
  AvgDialog_6773_Content_71 = {
    Text = "Ánh mắt Hiro lạnh lùng, ánh nhìn thù địch lướt qua vai bạn, rơi vào \"Hiro khác\" phía sau lưng bạn."
  },
  AvgDialog_6773_Content_72 = {
    Text = "Gai bay ra theo ánh mắt lạnh lùng của cô, bị một \"Hiro\" khác ném quả cầu xích khổng lồ đánh rơi xuống đất tuyết, tan chảy thành một vũng chất lỏng màu đen sền sệt."
  },
  AvgDialog_6773_Content_73 = {
    Text = "Đợi đã… có chuyện gì, mọi người hãy nói rõ…"
  },
  AvgDialog_6773_Content_74 = {
    Text = "Bạn vội vàng ngăn chặn ánh mắt đối địch của hai người họ, thử làm dịu bầu không khí."
  },
  AvgDialog_6773_Content_75 = {
    Text = "Nhưng có vẻ như……không có hiệu ứng."
  },
  AvgDialog_6773_Content_76 = {
    Text = "Bạn đã sớm cảm nhận được tôi. Suốt quãng đường này, bạn đã luôn chuẩn bị để giết tôi."
  },
  AvgDialog_6773_Content_77 = {
    Text = "Một mảnh vỡ từ một chiều không gian khác, rất dễ dàng mất kiểm soát. Nếu bạn muốn sống sót trong thế giới này, còn có cách khác."
  },
  AvgDialog_6773_Content_78 = {
    Text = "\"Sống\"? Điều tôi mong muốn không chỉ đơn thuần là sống."
  },
  AvgDialog_6773_Content_79 = {
    Text = "Một \"Hiro\" khác liếm môi dính chất lỏng đen, quả cầu xích trong tay cô ta quay một cách điên rồ, tiếng gió cuồng vũ càng lúc càng tiến gần."
  },
  AvgDialog_6773_Content_8 = {
    Text = "Quái vật lơ lửng trong không trung, thân thể run rẩy, phát ra một tiếng hú sắc nhọn."
  },
  AvgDialog_6773_Content_80 = {
    Text = "Thế giới này chỉ có thể tồn tại một Hiro. \"Tôi\" yếu đuối mới là bóng ma không nên tồn tại."
  },
  AvgDialog_6773_Content_81 = {
    Text = "Chiều, phân mảnh, \"tôi\" yếu đuối… Đây lẽ nào là, nguồn gốc?!"
  },
  AvgDialog_6773_Content_82 = {
    Text = "Bạn nhớ lại cuộc gặp gỡ với Ramona nguồn gốc."
  },
  AvgDialog_6773_Content_83 = {
    Text = "Đúng vậy, phân mảnh này của cô ấy là từ \"tôi\" ở một thế giới khác bong ra. Về bản chất, chúng tôi là cùng một người."
  },
  AvgDialog_6773_Content_84 = {
    Text = "Nhưng tôi không rõ, tại sao cô ấy lại xuất hiện trong thế giới này…"
  },
  AvgDialog_6773_Content_85 = {
    Text = "Một \"Hiro\" khác cười to đầy kiêu ngạo, thả hết mọi sự ác ý đang dâng trào trong tiếng cười của mình."
  },
  AvgDialog_6773_Content_86 = {
    Text = "Hahaha… Ai bảo chúng ta là cùng một người?"
  },
  AvgDialog_6773_Content_87 = {
    Text = "Herbert nói đúng, cậu và tôi trong quá khứ giống nhau, yếu đuối, bối rối, dễ bị đánh bại."
  },
  AvgDialog_6773_Content_88 = {
    Text = "Herbert… lại là hắn."
  },
  AvgDialog_6773_Content_89 = {
    Text = "Tôi không biết Herbert và Đèn Dẫn Đường đã hứa hẹn gì với bạn, nhưng anh ta là kẻ bội phản. \nLời nói của kẻ bội phản không đáng để tin tưởng."
  },
  AvgDialog_6773_Content_9 = {
    Text = "Lily chuẩn bị ngưng tụ quả cầu đen lần nữa, một bóng người bước ra, chắn ngay trước mặt cô."
  },
  AvgDialog_6773_Content_90 = {
    Text = "Bạn chẳng hiểu gì cả, Hiro. Tôi không tin tưởng bất kỳ ai, và việc tôi đến đây không liên quan đến bất kỳ ai."
  },
  AvgDialog_6773_Content_91 = {
    Text = "Chỉ có lực lượng tuyệt đối mới có thể giúp tôi hoàn thành sự trả thù."
  },
  AvgDialog_6773_Content_92 = {
    Text = "Quả cầu xích bị lực lớn kéo dắt, trong tay cô ấy vung mạnh, từ từ tiến gần đến Hiro."
  },
  AvgDialog_6773_Content_93 = {
    Text = "Nuốt chửng ngươi, mới có thể làm cho \"Hiro\" trở nên mạnh mẽ ——"
  },
  AvgDialog_6773_Content_94 = {
    Text = "Quả cầu sắt gào thét đã nhấn chìm lời nói của cô ấy, tấn công các bạn."
  },
  AvgDialog_6773_Content_96 = {
    Text = "Hiro tránh được đòn tấn công bằng xích sắt, ném gai nhầy trong tay về phía điểm yếu của \"Hiro\" khác, và đứng vững một cách nguy hiểm trên bờ vực hang băng với mủ tràn ra."
  },
  AvgDialog_6773_Content_97 = {
    Text = "Mụt mủ…… mụt mủ lại tràn ra!"
  },
  AvgDialog_6773_Content_98 = {
    Text = "Hai người họ đồng thời ngừng tay, nhìn về phía cái hang băng lớn ở trung tâm hồ băng, từ đó đang từ từ tràn ra chất đen đặc quánh."
  },
  AvgDialog_6773_Content_99 = {
    Text = "Dãy nứt này đang dần dần mở rộng, những mụn mủ bên trong càng ngày càng nhiều, nếu để lâu hơn nữa, e là sẽ không thể đi được nữa ——"
  },
  AvgDialog_67773_Content_1 = {
    Text = "Thắng rồi, cuối cùng"
  },
  AvgDialog_67773_Content_2 = {
    Text = "Không, không phải vậy… cảm giác này… áp lực không thể kháng cự, còn mạnh hơn vừa nãy…"
  },
  AvgDialog_67773_Content_3 = {
    Text = "Đây là?!!……"
  },
  AvgDialog_6777_Content_1 = {
    Text = "Đồng đội hay kẻ địch"
  },
  AvgDialog_6777_Content_10 = {
    Text = "Có lẽ chính vì có những con người như vậy tồn tại, thế giới này mới có thể giữ được một chút bình yên giữa những điên rồ ấy."
  },
  AvgDialog_6777_Content_100 = {
    Text = "Anh ta dừng lại một chút, giọng điệu có vẻ hơi xin lỗi."
  },
  AvgDialog_6777_Content_101 = {
    Text = "Tôi cần phải chịu trách nhiệm về an toàn của mọi người."
  },
  AvgDialog_6777_Content_102 = {
    Text = "Sau khi leo lên rất lâu, bạn vẫn không tìm thấy tung tích của Hiro, đỉnh núi đang hứng chịu cơn bão tuyết dữ dội."
  },
  AvgDialog_6777_Content_103 = {
    Text = "Liệu có nên từ bỏ việc hành động và theo đội xuống núi, hay đối mặt với khó khăn để tiếp tục leo lên đỉnh núi, bạn cần đưa ra sự lựa chọn…"
  },
  AvgDialog_6777_Content_104 = {
    Text = "Đại {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}, đây có mùi quen thuộc, Lily cảm nhận được.."
  },
  AvgDialog_6777_Content_105 = {
    Text = "Hống——"
