  AvgDialog_6777_Content_107 = {
    Text = "Hiro đang ở phía trước... Cô ấy có thể gặp nguy hiểm!"
  },
  AvgDialog_6777_Content_108 = {
    Text = "Đi theo hướng dẫn của Lily, các bạn rẽ qua con đường uốn lượn và thấy một bóng người từ từ tiến lại gần."
  },
  AvgDialog_6777_Content_109 = {
    Text = "Đó là……Hiro?!!!"
  },
  AvgDialog_6777_Content_11 = {
    Text = "Đại {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}, bạn nói gì vậy…… Lily không hiểu."
  },
  AvgDialog_6777_Content_110 = {
    Text = "Bạn lao tới với bước dài."
  },
  AvgDialog_6777_Content_111 = {
    Text = "Cô gái trẻ mặc trang phục mỏng manh, nghe thấy tiếng kêu của các người, dừng lại trong tuyết và nhìn về phía bạn đứng với vẻ cảnh giác."
  },
  AvgDialog_6777_Content_112 = {
    Text = "Đúng vậy, đó không nghi ngờ gì là khuôn mặt của Hiro, nhưng bạn nhất thời không thể khẳng định được — khí chất của cô ấy hoàn toàn khác so với lần cuối bạn gặp."
  },
  AvgDialog_6777_Content_113 = {
    Text = "Cô ấy bị kích thích bởi tiếng động của các người, vẻ cảnh giác trên khuôn mặt cô ấy giống như một con thú hoang bị bao vây, lúc nào cũng có thể phát động một đòn tấn công chết người."
  },
  AvgDialog_6777_Content_114 = {
    Text = "Con vật siết chặt cơ thể, nín thở nhìn chằm chằm. Vào khoảnh khắc tiếp theo, cô ta mỉm cười, trong ánh mắt thoáng hiện sự mơ hồ, sau đó hoàn toàn biến thành sự thù hận và ý định giết chóc."
  },
  AvgDialog_6777_Content_115 = {Text = "?!!"},
  AvgDialog_6777_Content_116 = {
    Text = "Hiro bước ra một bước, đột nhiên ra tay, quả cầu xích khổng lồ trong tay vù vù lao về phía các bạn."
  },
  AvgDialog_6777_Content_118 = {
    Text = "Một tiếng động trầm. Hướng dẫn viên bị quả cầu xích đen tuyền hung hãn cào rách và hất tung lên không trung, dòng máu nóng phun ra mãnh liệt làm tan chảy lớp tuyết vĩnh cửu, nhuộm ngọn giày leo núi đang cứng đờ bên cạnh thành một màu đỏ thắm đầy kịch tính."
  },
  AvgDialog_6777_Content_119 = {
    Text = "Ừ… mọi người… nhanh lùi lại!"
  },
  AvgDialog_6777_Content_12 = {
    Text = "Lily lại một lần nữa kéo góc áo của bạn. Bạn cúi người xuống và mỉm cười với cô ấy."
  },
  AvgDialog_6777_Content_120 = {
    Text = "Trong ánh mắt của mọi người, Hiro giống như một con quái thú điên cuồng, nhanh chóng lao về phía đám đông."
  },
  AvgDialog_6777_Content_121 = {
    Text = "%player%! Hãy nghĩ cách đi! Cô điên này thật sự muốn giết tất cả chúng ta!"
  },
  AvgDialog_6777_Content_122 = {
    Text = "Cô ấy đã hoàn toàn mất lý trí… Phải ép cô ấy dừng lại ngay!"
  },
  AvgDialog_6777_Content_123 = {
    Text = "Bạn lấy ra chìa khóa bạc từ ngực, tập trung toàn bộ tinh thần, toàn thân toát lên một lớp ánh sáng bạc dịu dàng."
  },
  AvgDialog_6777_Content_124 = {
    Text = "Ánh sáng bạc dịu dàng xâm nhập vào ý thức của Hiro, thế giới tinh thần điên cuồng của cô ấy gào rú trong gió lốc, toàn lực kháng cự sự liên kết của bạn."
  },
  AvgDialog_6777_Content_125 = {
    Text = "Tiếng gầm gừ tiến gần trước mắt ——"
