  AvgDialog_6777_Content_126 = {
    Text = "Hiro… nhanh dừng lại!"
  },
  AvgDialog_6777_Content_127 = {
    Text = "Hiro bùng phát một tiếng gầm thét đau đớn đến xé lòng, cô ấy ném điên cuồng quả cầu xích, phá hủy mọi thứ trên tuyết sơn."
  },
  AvgDialog_6777_Content_128 = {
    Text = "Lớn vậy à! Kẻ điên này —— không chỉ tấn công người, cô ta còn muốn gây ra trận lở tuyết nữa sao?!!"
  },
  AvgDialog_6777_Content_129 = {
    Text = "Cô ấy trông như không nhớ gì cả, rốt cuộc đã gặp phải chuyện gì kinh khủng đến vậy?!"
  },
  AvgDialog_6777_Content_13 = {
    Text = "Tôi muốn nói là, lát nữa sẽ có một nhóm anh chị lớn chơi cùng Lily, nhưng nơi này rất nguy hiểm, họ không có khả năng bảo vệ bản thân."
  },
  AvgDialog_6777_Content_130 = {
    Text = "%player%! Hãy nghĩ ra cách nào đó! Kiểm soát tên điên này!"
  },
  AvgDialog_6777_Content_131 = {
    Text = "Hiro! Nhanh dậy đi! Là tôi ——"
