  AvgDialog_6777_Content_132 = {
    Text = "Đinh————"
  },
  AvgDialog_6777_Content_133 = {
    Text = "Cuối cùng, ánh bạc dịu dàng đã khó khăn xuyên qua dòng ý thức cuồn cuộn, chiếu vào đôi mắt của Hiro, nơi sự điên rồ vừa tan biến."
  },
  AvgDialog_6777_Content_134 = {
    Text = "Hiro dường như đang trôi nổi trong một dòng sông Ngân Hà đầy ánh sáng, để cho dòng nước nhẹ nhàng nâng niu tinh thần của cô."
  },
  AvgDialog_6777_Content_135 = {
    Text = "Cô ấy cố gắng vùng vẫy, nhưng dòng nước lại ôm lấy cô một cách dịu dàng hơn, khiến cô càng chìm sâu hơn…"
  },
  AvgDialog_6777_Content_136 = {
    Text = "Tôi chỉ vừa kiềm chế được xu hướng điên rồ của bạn, ý thức của bạn vẫn đang cố thoát khỏi liên kết… Bạn không muốn ở đây, phải không?"
  },
  AvgDialog_6777_Content_137 = {
    Text = "Trong mắt Hiro đã không còn vẻ điên rồ, nhưng ánh mắt của cô vẫn bỏng rát, như đang nhìn chằm chằm vào một miếng thịt, giữ chặt ánh nhìn của bạn."
