  AvgDialog_6777_Content_140 = {
    Text = "Bạn còn nhớ mình thuộc về đâu không?"
  },
  AvgDialog_6777_Content_141 = {
    Text = "Hiro im lặng."
  },
  AvgDialog_6777_Content_142 = {
    Text = "Tôi không biết đã xảy ra chuyện gì với bạn. Có lẽ trước khi bạn trở lại bình thường, chúng ta có thể hợp tác không?"
  },
  AvgDialog_6777_Content_143 = {
    Text = "Elworth thực sự quá khó đoán, vì đã tìm thấy Hiro, \"càng nhanh rời đi càng tốt\" hiện là nhiệm vụ ưu tiên hàng đầu của các người. Bạn cần cô ấy dễ kiểm soát hơn."
  },
  AvgDialog_6777_Content_144 = {
    Text = "Thấy Hiro vẫn im lặng, tinh thần vẫn cố gắng liên tục thoát khỏi liên kết của bạn, bạn cau mày, nét mặt trở nên nghiêm trọng."
  },
  AvgDialog_6777_Content_145 = {
    Text = "Tinh thần của bạn cực kỳ không ổn định, nếu không liên kết với bạn, bạn rất có thể sẽ tái dị biến thành quái vật mất nhân tính và lý trí."
  },
  AvgDialog_6777_Content_146 = {
    Text = "Bạn cũng không muốn như vậy, đúng không?"
  },
  AvgDialog_6777_Content_147 = {
    Text = "Trong mắt Hiro bùng lên ngọn lửa. Cô ấy nhe răng, lộ ra những chiếc răng nhọn, cười vào mặt bạn. \nÁnh mắt cô ấy nhìn bạn giống như ánh mắt của một con thú đang nhìn con mồi."
  },
  AvgDialog_6777_Content_148 = {
    Text = "Đe dọa và dụ dỗ…… thật là một thằng khốn. \n chờ cho tôi ổn định lại, tôi sẽ xé nát cậu, nuốt chửng, không còn lại gì cả——"
  },
  AvgDialog_6777_Content_149 = {
    Text = "Bạn đối mặt với ánh mắt của cô ấy không hề sợ hãi."
