  AvgDialog_6777_Content_17 = {Text = "Ừm!"},
  AvgDialog_6777_Content_18 = {
    Text = "Á! quái…quái vật!!…"
  },
  AvgDialog_6777_Content_19 = {
    Text = "Tiếng ồn ào từ xa truyền đến, ngắt quãng cuộc trò chuyện của các ngươi."
  },
  AvgDialog_6777_Content_2 = {
    Text = "Đây có phải nơi đó không?"
  },
  AvgDialog_6777_Content_20 = {
    Text = "Bạn và Lily nhìn nhau, nắm tay cô ấy và chạy về hướng nguồn âm thanh.."
  },
  AvgDialog_6777_Content_22 = {
    Text = "Các bạn giải quyết gọn gàng lũ quái vật đang tiến gần, rồi quay lại nhìn trại."
  },
  AvgDialog_6777_Content_23 = {
    Text = "Đều không sao chứ?"
  },
  AvgDialog_6777_Content_24 = {
    Text = "Đội ngũ trong trại có khoảng mười người, hầu hết đều là nhân viên không chiến đấu và khá yếu đuối. Họ hoảng loạn nhìn những sinh vật đáng sợ này, phản kháng của họ rất mỏng manh."
  },
  AvgDialog_6777_Content_25 = {
    Text = "Rất cảm ơn ngài/thưa quý vị, {Male=ngài,Female=cô}, nếu không có ngài/quý vị, chúng tôi có lẽ đã không thể qua khỏi."
  },
  AvgDialog_6777_Content_26 = {
    Text = "Nhìn trang phục, các bạn không giống như là nhân viên khảo sát chuyên nghiệp, đến nơi này để làm gì?"
  },
  AvgDialog_6777_Content_27 = {
    Text = "À, tôi đã nhận được tin nhắn của Đóa, nói rằng sẽ gửi một học sinh qua, %player%... chính là bạn phải không?"
  },
  AvgDialog_6777_Content_28 = {
    Text = "Giọng anh ta nghe rất trầm ổn, ngực đeo huy hiệu trường có gắn bộ đàm. Nhìn qua, giống như giáo sư mà đóa nhắc đến đang tiến hành khảo sát thực địa —— Aivis."
  },
  AvgDialog_6777_Content_29 = {
    Text = "Gặp được sinh viên cùng trường khi đi khảo sát ở Elworth thật là một bất ngờ vui vẻ… Xin chào, tôi là giáo sư cổ sinh vật học tại Đại học Misaque, đồng thời cũng là nhà leo núi chuyên nghiệp."
  },
  AvgDialog_6777_Content_3 = {
    Text = "Ừ, Lily cảm thấy. Chị Hiro… có lẽ đang ở đây rồi."
  },
  AvgDialog_6777_Content_30 = {
    Text = "Rất vui được gặp bạn, Giáo Sư."
  },
  AvgDialog_6777_Content_31 = {
    Text = "Gọi tôi là Aivis nhé."
  },
  AvgDialog_6777_Content_32 = {
    Text = "Vừa nãy tôi không để ý, bên cạnh bạn lại giấu một đứa trẻ nhỏ như thế này sao?"
  },
  AvgDialog_6777_Content_33 = {
    Text = "Nơi này băng giá, cô ấy còn mặc quần áo mỏng như vậy, không sợ cô ấy bị cóng sao?"
  },
  AvgDialog_6777_Content_34 = {
    Text = "Lily không cảm thấy lạnh, Lily đến để bảo vệ mọi người."
  },
  AvgDialog_6777_Content_35 = {
    Text = "Hì hì. em bé thật là đáng yêu."
  },
  AvgDialog_6777_Content_36 = {
    Text = "Được rồi, nhờ %player% mà chúng ta không phải tốn quá nhiều sức lực trong việc giao tranh với động vật."
  },
  AvgDialog_6777_Content_37 = {
    Text = "Mọi người đã bị hoảng sợ, hãy nghỉ ngơi một thời gian tại trại đi."
  },
  AvgDialog_6777_Content_38 = {
    Text = "Lily được cô y tá ôm trong lòng, Avi có làn da rám nắng đang nhăn mặt để chọc cô bé cười."
  },
  AvgDialog_6777_Content_39 = {
    Text = "Bên cạnh cô là một nhóm đồng đội, vừa che chắn gió tuyết cho cô, vừa nhét đầy bàn tay nhỏ bé của cô bằng sô-cô-la và các loại hạt."
  },
  AvgDialog_6777_Content_4 = {
    Text = "Lily còn nghe thấy một giọng nói lạ."
  },
  AvgDialog_6777_Content_40 = {
    Text = "Đối với những người luôn đối mặt với nguy cơ tử vong, nụ cười của một đứa trẻ là sự an ủi duy nhất còn lại của họ."
  },
  AvgDialog_6777_Content_41 = {
    Text = "Ờ…… không thể ăn hết rồi……"
  },
  AvgDialog_6777_Content_42 = {
    Text = "Lily cất đầy hạt dẻ trong má, dùng chiếc răng nhỏ nhấm nháp thanh sô-cô-la bị đông cứng, mắt cong cong."
  },
  AvgDialog_6777_Content_43 = {
    Text = "Thấy ánh mắt của bạn, Lily nhảy xuống từ đầu gối của điều dưỡng viên và chạy tới bên bạn với tiếng bước chân \"tách tách\"."
  },
  AvgDialog_6777_Content_44 = {
    Text = "Mùi trên người chị ấy, rất giống mẹ. \nKhi phẫu thuật, Lily thường ngửi thấy mùi hương này… thật quen thuộc."
  },
  AvgDialog_6777_Content_45 = {
    Text = "Lily có muốn chơi cùng họ không?"
  },
  AvgDialog_6777_Content_46 = {
    Text = "Lily nhìn bạn rất nghiêm túc."
  },
  AvgDialog_6777_Content_47 = {
    Text = "{Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn} lớn rất quan trọng, nhưng những anh chị này đều rất tốt với Lily, và Lily cũng thích ở bên họ."
  },
  AvgDialog_6777_Content_48 = {
    Text = "Bạn xoa đầu Lily và nhìn quanh một vòng."
  },
  AvgDialog_6777_Content_49 = {
    Text = "Khi đi qua một hố, một mùi hôi thối ghê tởm bốc lên từ bên trong hố."
  },
  AvgDialog_6777_Content_5 = {
    Text = "Ngọn núi đó, đang gọi Lily…"
  },
  AvgDialog_6777_Content_50 = {
    Text = "Thật kỳ lạ, dù đây là nơi tuyết phủ trắng xóa, tại sao lại có mùi này trong hố này?"
  },
  AvgDialog_6777_Content_51 = {
    Text = "Avis bước tới gần hơn."
  },
  AvgDialog_6777_Content_52 = {
    Text = "Dưới nguyên băng của Elworth có tồn tại một ngọn núi lửa đang ngủ, có thể là khí độc từ magma tràn ra. Chắc không có vấn đề gì lớn đâu."
  },
  AvgDialog_6777_Content_53 = {
    Text = "Bạn nhìn xung quanh, chỉ có bạn và Aivis. Bạn đi đến bên cạnh anh ấy, hạ thấp giọng."
  },
  AvgDialog_6777_Content_54 = {
    Text = "Thưa giáo sư, để những người bình thường trong đội thám hiểm nhìn thấy những con quái vật đó, có ổn không?"
  },
  AvgDialog_6777_Content_55 = {
    Text = "Hãy yên tâm, họ không thể nhìn thấy dấu vết của sự tan biến. Về hành vi kỳ lạ của động vật, tôi đã giải thích rằng đó là do một loại virus sinh học đặc biệt ở Elworth, sau khi bị nhiễm sẽ trở nên như vậy."
  },
  AvgDialog_6777_Content_56 = {
    Text = "Vì trong đội chỉ có một học giả liên quan đến sinh học, mọi người đều tin tưởng tôi hoàn toàn, không ai muốn nhìn kỹ những con vật đó, nên chẳng ai phát hiện ra gì cả."
  },
  AvgDialog_6777_Content_57 = {
    Text = "Bạn gật đầu. Giọng nói đầm ấm của hướng dẫn viên vang lên từ không xa."
  },
  AvgDialog_6777_Content_58 = {
    Text = "Mọi người đã nghỉ ngơi đủ rồi, vì trời còn sớm, chúng ta dọn trại và mau chóng leo núi đi."
  },
  AvgDialog_6777_Content_59 = {
    Text = "Rất nhanh, các người dọn dẹp trại và theo hướng dẫn của người dẫn đường leo lên. Dọc đường, những mảnh thi thể ngựa bị gặm nhấm nằm rải rác bên đường, xương trắng ẩn sâu trong tuyết."
  },
  AvgDialog_6777_Content_6 = {
    Text = "Một dãy núi kéo dài trước mặt các bạn, những đỉnh nhọn luôn bị tuyết bao phủ và xói mòn quanh năm đang tắm mình trong ánh vàng, sừng sững đầy uy nghiêm trên cánh đồng băng."
  },
  AvgDialog_6777_Content_60 = {
    Text = "Những mảnh vải màu sắc này ——"
  },
  AvgDialog_6777_Content_61 = {
    Text = "Là những người leo núi chết trên đường từ nhiều năm trước, tình trạng tử vong vô cùng đa dạng và kỳ lạ, có người bị đóng băng đến chết, có người bị tuyết lở chôn sống, có người rơi từ đỉnh núi xuống và thiệt mạng… Quá nhiều người đã bỏ mạng trên ngọn núi này."
  },
  AvgDialog_6777_Content_62 = {
    Text = "Ngựa có thể được dùng làm phương tiện di chuyển, cũng có thể bị giết để ăn. Tuy nhiên, khi leo lên cao hơn, ngựa sẽ không thể tiếp tục tiến xa."
  },
  AvgDialog_6777_Content_63 = {
    Text = "Hướng dẫn viên nhúc nhích môi, chỉ cho bạn nhìn thi thể nằm bên đường."
  },
  AvgDialog_6777_Content_64 = {
    Text = "Nó bị phủ kín bởi băng tuyết, bề mặt da xuất hiện màu tím xanh thẫm, giữ nguyên tư thế bò ra khỏi túi ngủ. Mặt lộ rõ nụ cười khổ sở đầy quái lạ."
  },
  AvgDialog_6777_Content_65 = {
    Text = "\"Hành vi cởi quần áo bất thường\" và \"biểu cảm cười khổ\", những đặc điểm điển hình của việc chết cóng."
  },
  AvgDialog_6777_Content_66 = {
    Text = "Xác của những nhà leo núi chết trên tuyết sơn thường trở thành dấu hiệu dẫn lối, chỉ hướng đi cho những người kế tiếp."
  },
  AvgDialog_6777_Content_67 = {
    Text = "Tôi có bạn đã ở lại trên núi này. Tôi có thể đi kiểm tra thẻ tên của nhà leo núi này không?"
  },
  AvgDialog_6777_Content_68 = {
    Text = "Tất nhiên."
  },
  AvgDialog_6777_Content_69 = {
    Text = "Aivs dẫm lên tuyết mềm, từng bước tiến đến xác chết cứng đờ, anh cố gắng dời nó để lộ thẻ tên trên túi ngủ."
  },
  AvgDialog_6777_Content_7 = {
    Text = "Tiếng gọi của núi… là vì Hiro ở đó, giữa hai người có thể cảm nhận được nhau không"
  },
  AvgDialog_6777_Content_70 = {
    Text = "Vào giây tiếp theo, ngay khi anh ta không có bất kỳ sự đề phòng nào, một cơ thể tái nhợt và tím tái phủ đầy băng tuyết đột nhiên lao ra từ túi ngủ."
  },
  AvgDialog_6777_Content_71 = {
    Text = "Xác chết vô danh với nụ cười rợn người, đưa đôi tay đầy chất lỏng đen sẫm dính keo về phía Avis đang ngã trên mặt đất."
  },
  AvgDialog_6777_Content_72 = {Text = "À!!!!!!!"},
  AvgDialog_6777_Content_73 = {
    Text = "Quái, quái…… quái vật!"
  },
  AvgDialog_6777_Content_74 = {
    Text = "Mọi người cẩn thận! Lily!"
  },
  AvgDialog_6777_Content_75 = {Text = "Ừm!"},
  AvgDialog_6777_Content_76 = {
    Text = "Quả cầu đen xuất hiện bên cạnh Lily, tiếp cận những xác chết có dáng vẻ kỳ quái. Không lâu sau, các mụn nhọt đen bên trong xác chết đã bị loại bỏ."
  },
  AvgDialog_6777_Content_77 = {
    Text = "Á á á á——là thần núi! Kẻ phạm thánh sẽ phải chịu hình phạt của thần minh!"
  },
  AvgDialog_6777_Content_78 = {
    Text = "Người ngoại đạo không biết kính sợ, đã đặt chân vào nơi cư ngụ của thần minh, nơi đây không chào đón các ngươi! Nhanh đi đi! Nhanh đi đi!"
  },
  AvgDialog_6777_Content_79 = {
    Text = "Đây là người bản địa Elworth được đội thám hiểm thuê, anh ta đã cau có suốt hành trình, nhưng lúc này lại lộ ra sự cuồng nhiệt bất thường."
  },
  AvgDialog_6777_Content_8 = {
    Text = "Theo như đóa, đội thám hiểm lúc này cũng gần đến rồi. Chúng ta hãy chờ ở đây đi."
  },
  AvgDialog_6777_Content_80 = {
    Text = "Cả đội im lặng. Thi thể đột ngột bùng lên cùng với những lời thì thầm điên cuồng của người dân địa phương đã bao trùm đoàn thám hiểm trong một bầu không khí đầy sợ hãi."
  },
  AvgDialog_6777_Content_81 = {
    Text = "Ngoài mấy người xuất thân từ Mi Đại, chưa từng có ai gặp phải tình huống này."
  },
  AvgDialog_6777_Content_82 = {
    Text = "Vừa rồi……là gì?"
  },
  AvgDialog_6777_Content_83 = {
    Text = "……không rõ."
  },
  AvgDialog_6777_Content_84 = {
    Text = "Bạn không trả lời được."
  },
  AvgDialog_6777_Content_85 = {
    Text = "Trong khuôn khổ các điều khoản của Hiệp định \"Misthia\", bạn có nghĩa vụ giữ bí mật với bên ngoài và không tiết lộ sự tồn tại của hiện tượng rỗng rỗng cho người thường."
  },
  AvgDialog_6777_Content_86 = {
    Text = "Người bản địa mặt mày xám xịt, môi run rẩy thốt ra những lời nói mê sảng ghê tởm, như thể có gì đó kinh khủng đang từ từ chui ra từ miệng anh ta."
  },
  AvgDialog_6777_Content_87 = {
    Text = "Chẳng lẽ là… thần… ?"
  },
  AvgDialog_6777_Content_88 = {
    Text = "Người hướng dẫn lấy lại tinh thần, nhíu mày, nhưng vẫn kiên quyết lắc đầu."
  },
  AvgDialog_6777_Content_89 = {
    Text = "Giáo sư đã giải thích trước đây rằng những virus động vật kỳ lạ có thể tấn công con người sau khi nhiễm virus, vậy nên… con người cũng có thể tấn công do nhiễm virus."
  },
  AvgDialog_6777_Content_9 = {
    Text = "Những nhà khoa học đến từ Misaque đã không ngại đường xa, di chuyển đến nơi nguy hiểm này để tiến hành nghiên cứu."
  },
  AvgDialog_6777_Content_90 = {
    Text = "Đây là điều có thể giải thích trong phạm vi khoa học, chúng ta không nên suy đoán quá mức."
  },
  AvgDialog_6777_Content_91 = {
    Text = "Giọng của người hướng dẫn trầm ổn và mạnh mẽ, dường như rất đáng tin cậy, nhưng nắm đấm anh ta để sau lưng lại đang rung nhẹ."
  },
  AvgDialog_6777_Content_92 = {
    Text = "Anh ta cố gắng tạo ra một lý do đáng tin cậy và hợp lý, để nói với người khác và cũng để nói với chính mình."
  },
  AvgDialog_6777_Content_93 = {
    Text = "Các thành viên trong đội thám hiểm, mang trong lòng nỗi sợ hãi, rõ ràng không bị thuyết phục bởi lời giải thích sơ sài này, nhưng sắc mặt của họ dần dần bình tĩnh lại, giấu sự bất an vào đáy lòng, bắt đầu thu dọn hành trang và tiếp tục xuất phát."
  },
  AvgDialog_6777_Content_94 = {
    Text = "Trên đỉnh tuyết sơn ở độ cao hàng nghìn mét, đối mặt với hoàn cảnh tuyệt vọng chưa biết, con người cần tìm đến một sự an ủi giả tạm. Họ cần tin vào điều gì đó."
  },
  AvgDialog_6777_Content_95 = {
    Text = "——Đội thám hiểm chìm vào thinh lặng, lại một lần nữa leo lên đỉnh núi."
  },
  AvgDialog_6777_Content_97 = {
    Text = "Các bạn đã leo núi trong hai ngày và dần dần làm quen với khí hậu ở đây. Nhóm nghiên cứu đã thu thập được nhiều kết quả, nhưng trên khuôn mặt mọi người vẫn thiếu đi nét vui mừng."
  },
  AvgDialog_6777_Content_98 = {
    Text = "Những sự kiện kỳ quái đó vẫn đang làm phiền những người không hay biết."
  },
  AvgDialog_6777_Content_99 = {
    Text = "Mẫu đá mà đội thám hiểm thu thập trên đường đã đủ rồi. Nếu các người vẫn cố gắng tiếp tục đi lên, đội thám hiểm sẽ không thể đi cùng nữa."
  },
  AvgDialog_6787_Content_1 = {
    Text = "Một mùa xuân"
  },
  AvgDialog_6787_Content_10 = {
    Text = "Bạn gật đầu, rồi lại nhìn ra cửa sổ."
  },
  AvgDialog_6787_Content_11 = {
    Text = "Về việc tìm kiếm bạc tâm của Hiro, bạn vốn cũng không đặt nhiều kỳ vọng."
  },
  AvgDialog_6787_Content_12 = {
    Text = "Ramona, cô nói xem, tuyết sơn Elworth có tan không?"
  },
  AvgDialog_6787_Content_13 = {
    Text = "……Elworth là vùng đất cực kỳ lạnh lẽo, với gió tuyết quanh năm không tan."
  },
  AvgDialog_6787_Content_14 = {
    Text = "Đúng vậy, đó là điều ai cũng biết. Gió tuyết của Elworth, quanh năm không tan."
  },
  AvgDialog_6787_Content_15 = {
    Text = "Lời hứa bị cơn gió mạnh cuốn tới tai bạn, giống như một lời từ biệt nhẹ nhàng và an ủi."
  },
  AvgDialog_6787_Content_16 = {
    Text = "Bầu trời chảy tràn sắc đỏ rực rỡ như sơn dầu, ánh hoàng hôn tuôn chảy trên tay. Bên ngoài cửa sổ, khuôn viên trường Đại học Misag đang chìm đắm trong ánh tà dương."
  },
  AvgDialog_6787_Content_17 = {
    Text = "Đã ngủ một tuần rồi… Tình hình hồi phục thế nào, Người Giữ Gìn?"
  },
  AvgDialog_6787_Content_18 = {
    Text = "Thời gian thanh xuân tươi đẹp không nên lãng phí trên giường bệnh."
  },
  AvgDialog_6787_Content_19 = {
    Text = "Xem này, tôi đã mang cho bạn thứ tốt đây rồi!"
  },
  AvgDialog_6787_Content_2 = {
    Text = "Giáo sư Aivis vẫn đang trong trạng thái mất ý thức, nhưng đã xác nhận rằng không có nguy hiểm đến tính mạng."
  },
  AvgDialog_6787_Content_20 = {
    Text = "%player% là bệnh nhân, không thể uống rượu… Hy vọng ngài có chút kiến thức cơ bản, Giáo sư Dexter."
  },
  AvgDialog_6787_Content_21 = {
    Text = "Cốc rượu này là tôi nợ %player%."
  },
  AvgDialog_6787_Content_22 = {
    Text = "Lần này, mọi chuyện phần lớn là do tôi mà ra, nên tôi đến đây đặc biệt để xin lỗi."
  },
  AvgDialog_6787_Content_23 = {
    Text = "Tin tôi đi, việc giữ những chai rượu ngon này đến bây giờ không hề dễ dàng, tôi đã phải rất cố gắng để kiềm chế sự thôi thúc của mình."
  },
  AvgDialog_6787_Content_24 = {
    Text = "Uống rượu không phải là cách biểu đạt tốt."
  },
  AvgDialog_6787_Content_25 = {
