  AvgDialog_6788_Content_4 = {
    Text = "Tôi và Lily không thể chịu đựng thêm lâu nữa, đường xuống núi đã bị chặn… Bây giờ chạy trốn đã quá muộn, chúng ta buộc phải phá hủy nó."
