  AvgDialog_6798_Content_15 = {Text = "Con mồi."},
  AvgDialog_6798_Content_16 = {
    Text = "Cô không nói thêm gì nữa, chỉ quay đầu lại liên tục, nhìn về một nơi nào đó trong tuyết trắng mênh mông, trong mắt đầy sự hào hứng và khao khát."
  },
  AvgDialog_6798_Content_17 = {
    Text = "Bạn dõi theo ánh mắt của cô ấy, dường như nhìn thấy một bóng đen lướt qua trong chớp mắt. Khi bạn quay lại nhìn, ngoài trận bão tuyết cuồn cuộn không ngừng, phía sau hoàn toàn trống vắng."
  },
  AvgDialog_6798_Content_19 = {
    Text = "So với việc leo lên núi, đường xuống núi lại khó đi hơn, và quái vật cũng ngày càng đông đảo."
  },
  AvgDialog_6798_Content_2 = {
    Text = "Đây là tình hình tổng quát. Tôi đã thảo luận với hướng dẫn viên và Giáo sư Avis, thông tin về Elworth vẫn chưa đủ, việc tiếp tục sẽ rất nguy hiểm."
  },
  AvgDialog_6798_Content_20 = {
    Text = "Sau khi quét sạch đàn quái vật, chúng ta tìm một nơi tránh gió, dễ phòng thủ để đóng quân, và đến đêm đã hẹn sẵn người thay phiên canh gác."
  },
  AvgDialog_6798_Content_21 = {
    Text = "Sau một ngày dài mất quá nhiều năng lượng, bạn không thể cưỡng lại cơn buồn ngủ và chìm vào giấc ngủ sâu…"
  },
  AvgDialog_6798_Content_23 = {
    Text = "Tiếng cãi vã mơ hồ và không rõ ràng, đánh thức bạn khỏi giấc mơ. Bạn kéo rèm cửa lều lên và phát hiện khuôn mặt mọi người nghiêm trọng đến đáng sợ."
