  AvgDialog_6798_Content_24 = {
    Text = "Không phải đã định rõ là bạn sẽ tiếp ca vào nửa đêm sao? Bây giờ thì hay rồi, người đã mất! Bạn nói xem, điều này nên trách ai?!"
