  AvgDialog_6798_Content_65 = {
    Text = "Đêm qua tôi không nhận thấy có gì bất thường ở đầu dây bên kia kết nối. Tôi nghĩ, Hiro có lẽ không phải là hung thủ thật sự."
  },
  AvgDialog_6798_Content_66 = {
    Text = "Tôi tin vào phán đoán của bạn. Nhưng để người khác tin tưởng, e rằng không đơn giản như vậy…"
  },
  AvgDialog_6798_Content_67 = {
    Text = "Anh ấy nhìn quanh một vòng khuôn mặt của các thành viên trong đội, rồi hạ thấp giọng nói của mình."
  },
  AvgDialog_6798_Content_68 = {
    Text = "Trời đã tối, nhiệt độ bên ngoài không còn thích hợp để tiếp tục tiến về phía trước… Hãy dừng lại và cắm trại nghỉ ngơi."
