  AvgDialog_6798_Content_73 = {
    Text = "Những nhà khoa học yếu đuối, có người dùng những thứ dễ thấy trên các tuyết sơn buộc thành rìu đá và dao đá, đặt dưới gối để tự an ủi mình."
  },
  AvgDialog_6798_Content_74 = {
    Text = "Một số thì hoàn toàn từ bỏ lý trí, tập trung vào việc bắt chước những cử chỉ mà người bản địa từng dùng để làm hài lòng thần linh, bò lê trên mặt đất với dáng vẻ khó nhọc và quái dị…"
