  AvgDialog_6811_Content_27 = {
    Text = "Bạn thở dài, vuốt ve cái đầu nhỏ ngẩng lên của cô ấy, đứng dậy và nhìn về phía trước thế giới trắng xóa mênh mông."
  },
  AvgDialog_6811_Content_28 = {
    Text = "Gió tuyết cuồn cuộn thổi qua, rơi xuống những dãy núi uốn lượn ở cuối băng nguyên cực địa, rơi xuống nơi các người sẽ đến."
  },
  AvgDialog_6811_Content_29 = {
    Text = "Một tuần trước"
  },
  AvgDialog_6811_Content_3 = {
    Text = "Đây, chính là Elworth?"
  },
  AvgDialog_6811_Content_30 = {
    Text = "Động đất, tuyết lở, núi lửa phun trào, còn có sự tan chảy vô hình mà mắt thường không thể nhìn thấy… Thế giới này thật sự không hề yên ổn, ngay cả thời gian để nhâm nhi một ly rượu cũng không có."
  },
  AvgDialog_6811_Content_31 = {
    Text = "……Giáo sư Dexter?"
  },
  AvgDialog_6811_Content_32 = {
    Text = "Ngọn lửa nhảy múa trong lò sưởi. Người đàn ông trung niên ăn mặc tinh tế đặt tờ báo xuống, vẫy tay với bạn."
  },
  AvgDialog_6811_Content_33 = {
    Text = "À, bạn đã đến! Cứ tự nhiên ngồi nhé."
  },
  AvgDialog_6811_Content_34 = {
    Text = "Giáo sư, tôi nghe nói ông có việc khẩn cấp cần gặp tôi?"
  },
  AvgDialog_6811_Content_35 = {
    Text = "Đúng vậy, cực kỳ khẩn cấp."
  },
  AvgDialog_6811_Content_36 = {
    Text = "Sau khi quỹ từ thiện tiếp quản viện điều trị tinh thần Ray, việc xử lý hậu quả đã được thực hiện khá tốt."
  },
  AvgDialog_6811_Content_37 = {
    Text = "Có một bệnh nhân gia đình sở hữu xưởng sản xuất rượu, để cảm ơn, gia đình đã tặng hai chai rượu vang được làm thủ công tại nhà."
  },
  AvgDialog_6811_Content_38 = {
    Text = "Một người thưởng thức thì quá cô đơn. Thế nào, bạn có muốn cùng tôi thử một chút không?"
  },
  AvgDialog_6811_Content_39 = {
    Text = "Bạn nhìn ly rượu cao chân anh đưa qua và thở dài ngao ngán."
  },
  AvgDialog_6811_Content_4 = {
    Text = "Đúng vậy. Chào mừng trở về nhà, Hiro."
  },
  AvgDialog_6811_Content_40 = {
    Text = "Thưa giáo sư, tôi gần đây rất bận... Nếu không có chuyện gì quan trọng, tôi đi trước đây."
  },
  AvgDialog_6811_Content_41 = {
    Text = "Cuộc sống không biết tận hưởng là cuộc sống không có niềm vui."
  },
  AvgDialog_6811_Content_42 = {
    Text = "À, còn có một việc khác, mặc dù không đáng kể so với việc nếm rượu, nhưng tôi nghĩ bạn có thể quan tâm."
  },
  AvgDialog_6811_Content_43 = {Text = "Cái gì?"},
  AvgDialog_6811_Content_44 = {
    Text = "Vị bạn mang rượu đến cho tôi biết, một bệnh nhân đã xuất hiện những dấu hiệu bất thường. Bệnh viện tâm thần vang vọng tiếng rên rỉ và hét lên của cô ấy suốt ngày đêm, và tình trạng tinh thần và thể chất ngày càng xấu đi cũng khiến các bác sĩ vô phương cứu chữa."
  },
  AvgDialog_6811_Content_45 = {
    Text = "Thật sự rất tệ, nhưng tôi không có thành tựu gì trong lĩnh vực bệnh tinh thần…"
  },
  AvgDialog_6811_Content_46 = {
    Text = "Và không liên quan đến lĩnh vực y học —— có lẽ bạn vẫn nhớ, một cô gái với thân thể được đánh thức đang liên kết với bệnh nhân tại Bệnh viện Tâm thần Francis."
  },
  AvgDialog_6811_Content_47 = {Text = "!!!"},
  AvgDialog_6811_Content_48 = {
    Text = "Giao cô ấy…… cho ta!"
  },
  AvgDialog_6811_Content_49 = {
    Text = "Quả thật đáng thương thay, chỉ vì mất liên kết bạc tâm mà suy tàn thành hình dạng như thế này."
  },
  AvgDialog_6811_Content_5 = {
    Text = "Núi bạn muốn đến, người bạn muốn gặp đều có mặt tại đây."
  },
  AvgDialog_6811_Content_50 = {
    Text = "Francis đã liên kết với Lily, còn người liên kết của Hiro…"
  },
  AvgDialog_6811_Content_51 = {
    Text = "Đóa từng giảng trong khóa học \"Cơ bản về Chế tạo và Liên kết Thể thức Thức tỉnh\" rằng, trừ các tác dụng phụ không thể kiểm soát, đối tượng liên kết tốt nhất của thân thể được đánh thức chính là những bệnh nhân tại ngôi nhà dưỡng lão này."
  },
  AvgDialog_6811_Content_52 = {
    Text = "Bệnh nhân trong viện dưỡng lão……?\nVì tinh thần vốn đã không ổn định nên có lẽ không sợ mất kiểm soát?"
  },
  AvgDialog_6811_Content_53 = {
    Text = "Hiro cô đơn đứng ở bến cảng, mái tóc dài bay nhẹ nhàng trong gió."
  },
  AvgDialog_6811_Content_54 = {
    Text = "Tàu sắp khởi hành,bạn muốn lên tàu không?"
  },
  AvgDialog_6811_Content_55 = {
    Text = "Hiro vẫy tay, ra hiệu cho thuyền không cần đợi mình. \nCô vẫn chưa biết sẽ đi đâu tiếp."
  },
  AvgDialog_6811_Content_56 = {
    Text = "Hiro… sau khi rời viện dưỡng lão, cô ấy đã mất tích. Có chuyện gì xảy ra không?"
  },
  AvgDialog_6811_Content_57 = {
    Text = "Xem cái này."
  },
  AvgDialog_6811_Content_58 = {
    Text = "Một tờ báo mới in, toát lên mùi mực in mới, được đẩy đến trước mặt bạn."
  },
  AvgDialog_6811_Content_59 = {
    Text = "\"Vùng tuyết nguyên Elworth nằm ở vùng cực, đã xảy ra trận tuyết lở đặc biệt lớn vào ngày @2 tháng @2 năm @2, được xác định là có quy mô lớn nhất hiện tại, nguyên nhân chưa rõ…\""
  },
  AvgDialog_6811_Content_6 = {
    Text = "Herbert đưa tay ra, chỉ về phía trước dãy núi bị tuyết bao phủ."
  },
  AvgDialog_6811_Content_60 = {
    Text = "El… Worth?"
  },
  AvgDialog_6811_Content_61 = {
    Text = "Bệnh nhân tâm thần bị ảnh hưởng bởi thân thể được đánh thức của Hiro, điều họ hét lên chính là đồng tuyết Elworth, nơi vừa trải qua một trận lở tuyết gần đây."
  },
  AvgDialog_6811_Content_62 = {
    Text = "Còn những hình ảnh bạn đã thấy trong mơ trước đây. Ấn tượng lắm, đúng không?"
  },
  AvgDialog_6811_Content_63 = {
    Text = "Cảnh tượng trong giấc mơ, động thái của Hiro, còn trận tuyết lở bất thường này, đều hướng tới nơi đó…"
  },
  AvgDialog_6811_Content_64 = {
    Text = "Trong giấc mơ xuất hiện biểu tượng của Hội Giáo đèn lồng, những việc họ muốn làm rất có thể liên quan đến Hiro."
  },
  AvgDialog_6811_Content_65 = {
    Text = "Đúng vậy. Trên thế giới này luôn có những kẻ không biết thưởng thức, thích quấy rối cuộc sống của người khác."
  },
  AvgDialog_6811_Content_66 = {
    Text = "Tôi sẽ điều tra rõ những gì đã xảy ra ở Elworth"
  },
  AvgDialog_6811_Content_67 = {
    Text = "Tôi sẽ tìm thấy Hiro"
  },
  AvgDialog_6811_Content_68 = {
    Text = "Hiểu rồi. Thời gian cấp bách, tôi sẽ lập tức khởi hành, hướng đến Elworth."
  },
  AvgDialog_6811_Content_69 = {
    Text = "Tôi không có ý đó…Êi?"
  },
  AvgDialog_6811_Content_7 = {
    Text = "Bạn có chắc là cô ấy sẽ xuất hiện không?"
  },
  AvgDialog_6811_Content_70 = {
    Text = "Thật không hiểu, tại sao mọi người đều vội vàng như vậy. Ít nhất cũng nên uống cạn chén rượu này đi…"
  },
  AvgDialog_6811_Content_71 = {
    Text = "Rượu trước mặt đã được uống cạn, anh ta cầm chiếc cốc rỗng, lắc nhẹ nhàng về phía cửa."
  },
  AvgDialog_6811_Content_72 = {
    Text = "Nguyện chìa khóa bạc chỉ dẫn con đường, Người Giữ Gìn."
  },
  AvgDialog_6811_Content_73 = {
    Text = "Người giữ bí mật, tình hình hiện tại ra sao?"
  },
  AvgDialog_6811_Content_74 = {
    Text = "Đã đặt chân lên băng nguyên Elworth, tình hình ổn định."
  },
  AvgDialog_6811_Content_75 = {
    Text = "Như bạn đã dự đoán, Lily có thể mơ hồ cảm nhận được sự dao động của lực lượng cùng nguồn, tìm ra hướng đi đúng."
  },
  AvgDialog_6811_Content_76 = {
    Text = "Có điều gì bất ổn xảy ra trong chuyến đi không?"
  },
  AvgDialog_6811_Content_77 = {
    Text = "Không có gì lạ, chỉ là di chuyển trên biển đầy băng vỡ, mỗi ngày cầu nguyện để gió giận dữ không làm lật thuyền… Cũng không biết tại sao. Cả Hội Giáo đèn lồng và Hiro đều nhắm đến nơi này."
  },
  AvgDialog_6811_Content_78 = {
    Text = "Tuy nhiên, người dân địa phương gần đó dường như không chào đón chúng ta, thường nói những lời khó hiểu về thần núi, quái vật và các thứ khác."
  },
  AvgDialog_6811_Content_79 = {
    Text = "Có một việc cần thông báo với bạn. Lần này chuyến đi của bạn được phê duyệt rất vội vàng, không kịp thực hiện cuộc điều tra chi tiết trước đó."
  },
  AvgDialog_6811_Content_8 = {
    Text = "Như thể bạn sẽ xuất hiện ở đây. Đây là lời gọi của số phận. \nKhông ai có thể từ chối số phận, đúng không?"
  },
  AvgDialog_6811_Content_80 = {
    Text = "Tôi những ngày gần đây vẫn ở trong phòng lưu trữ, đã tìm thấy một tài liệu về Elworth, trên đó đề cập đến……"
  },
  AvgDialog_6811_Content_81 = {
    Text = "Bạn đang nói chuyện với đóa, thấy Lily tiến tới một cái hang."
  },
  AvgDialog_6811_Content_82 = {
    Text = "Lily, cẩn thận một chút, đừng để bị rơi vào đó."
  },
  AvgDialog_6811_Content_83 = {
    Text = "Lily đi vài bước về phía xa, rồi tò mò ngồi xổm xuống."
  },
  AvgDialog_6811_Content_84 = {
    Text = "Có…tiếng…"
  },
  AvgDialog_6811_Content_85 = {
    Text = "Bạn tiến lên vài bước. Nước biển không biết bị thứ gì khuấy động, phát ra âm thanh trầm đục qua lớp băng bán trong suốt."
  },
  AvgDialog_6811_Content_86 = {
    Text = "Một bóng đen mờ nhạt bỗng nhiên xuất hiện dưới lớp băng, đang phình to với tốc độ cực nhanh…"
  },
  AvgDialog_6811_Content_87 = {
    Text = "Nguy hiểm!"
  },
  AvgDialog_6811_Content_88 = {
    Text = "Bạn nhanh chóng kéo thiếu nữ từ bờ vực của hố sâu trở lại. Mặt băng dưới chân cô ấy lập tức vỡ ra, vài sinh vật Bắc Cực khổng lồ đến mức gần như quái dị phá vỡ tầng băng, vặn vẹo thân thể không cân đối để leo lên."
  },
  AvgDialog_6811_Content_89 = {
    Text = "Những mụn nhọt đen kỳ quái tràn ra từ dưới lông của chúng, bên trong những mụn nhọt như thể có gì đó đang xáo trộn, toả ra mùi thối rữa."
  },
  AvgDialog_6811_Content_9 = {
    Text = "Nghe những lời này, cô gái trẻ cười toe toét, lộ ra hai chiếc răng nhọn."
  },
  AvgDialog_6811_Content_90 = {
    Text = "Tiếng thét chói tai, khàn khàn vang lên. Những con quái vật mở to đôi mắt bị loét lở nhìn các ngươi, đầy sự thù địch nguyên thủy."
  },
  AvgDialog_6811_Content_91 = {
    Text = "Là do sự biến đổi gây ra bởi rỗng rỗng… Lily, cẩn thận!"
  },
  AvgDialog_6811_Content_92 = {
    Text = "Chiếc chìa khóa bạc trong tay tỏa ra ánh sáng dịu nhẹ, quả cầu đen chắn trước mặt Lily, nghiền nát những con quái vật không rõ nguồn gốc."
  },
  AvgDialog_6811_Content_93 = {
    Text = "Tránh được cuộc tấn công nguy hiểm của quái vật trước khi nó chết, bạn thở ra một hơi dài."
  },
  AvgDialog_6811_Content_94 = {
    Text = "Địch đã bị tiêu diệt… đóa, quái vật lạ đó là gì?"
  },
  AvgDialog_6811_Content_95 = {
    Text = "Tôi cũng vừa mới tra cứu tài liệu và biết được, Misaque đã cử một đội các nhà khoa học và điều tra viên đến Elworth để tiến hành cuộc khảo sát bí mật, họ cũng đã gặp và ghi chép lại loài sinh vật biến dị này."
  },
  AvgDialog_6811_Content_96 = {
    Text = "Trong bản ghi mà đội thám hiểm gửi về, có đề cập đến \"thần núi\" không? Tôi luôn nghi ngờ rằng điều này có liên quan đến Hiro."
  },
  AvgDialog_6811_Content_97 = {
    Text = "Rất tiếc, bản lưu của cuộc khảo sát bí mật cũng trống rỗng như bộ não của một số người."
  },
  AvgDialog_6811_Content_98 = {
    Text = "Họ không thể điều tra ra bất kỳ kết quả nào? Tôi có một số câu hỏi muốn hỏi họ, có thể nói chuyện trực tiếp với họ không?"
  },
  AvgDialog_6811_Content_99 = {
    Text = "Đầu dây bên kia im lặng trong chốc lát."
