  AvgDialog_6812_Content_106 = {Text = "……á!"},
  AvgDialog_6812_Content_107 = {Text = "Hiro!!.."},
  AvgDialog_6812_Content_108 = {
    Text = "Lời chưa dứt, cô ấy bất ngờ bị hụt chân."
