  AvgDialog_6812_Content_109 = {
    Text = "——Trong ký ức, mặt đất vốn là một ngọn đồi bỗng biến mất chỉ trong chớp mắt, hóa thành vực thẳm vạn trượng."
  },
  AvgDialog_6812_Content_11 = {
    Text = "Tại sao những xác chết này lại ở trong tường? Tường… có thật sự ăn thịt người không?"
