  AvgDialog_6812_Content_12 = {
    Text = "Bây giờ đã có đủ việc cần chúng ta lo lắng rồi. Cứ tiếp tục đi."
  },
  AvgDialog_6812_Content_14 = {
    Text = "……Mùi ở đây có chút kỳ lạ, giống như mùi hôi chúng ta đã ngửi trước đây, nhưng mạnh mẽ hơn nhiều. Có thể liên quan đến hoạt động núi lửa."
