  AvgDialog_6812_Content_2 = {
    Text = "Các người leo lên dọc theo vách đá băng hầu như không có chỗ đặt chân, dựa vào cảm ứng mờ nhạt của Hiro đối với Lily, chui vào khe đá này."
  },
  AvgDialog_6812_Content_20 = {
    Text = "Một số thứ bẩn đã rơi lên người bạn."
