  AvgDialog_6812_Content_21 = {Text = "!!!"},
  AvgDialog_6812_Content_22 = {
    Text = "Cô ta ném hòn mụn đen nhỏ trên tay lên tường, rồi đâm một kiếm xuyên qua."
  },
  AvgDialog_6812_Content_23 = {Text = "Đi thôi."},
  AvgDialog_6812_Content_25 = {
    Text = "Càng đi vào trong, mùi hôi càng nồng… À, xin lỗi, tôi đã đụng vào bạn rồi."
  },
  AvgDialog_6812_Content_26 = {
    Text = "Nếu tiếp tục tiến gần, hậu quả sẽ do chính loài người gánh chịu."
  },
  AvgDialog_6812_Content_27 = {
    Text = "Đúng là không thể trách tôi, đường càng đi càng hẹp… Bức tường này có vẻ như đang di chuyển…"
