  },
  AvgDialog_6812_Content_3 = {
    Text = "Các khe nứt trong băng hà lẽ ra phải đầy tuyết và băng, nhưng nhiệt độ ở đây lại không thấp, thậm chí trên các vách còn bám đầy mảng rêu kỳ lạ khiến người ta cảm thấy bất an."
  },
  AvgDialog_6812_Content_30 = {
    Text = "Tiếng nói yếu ớt từ sâu trong hang động vang lại."
