  AvgDialog_6812_Content_31 = {
    Text = "Có người bên trong! Cuối cùng cũng tìm thấy họ rồi!"
  },
  AvgDialog_6812_Content_32 = {
    Text = "Bạn đang muốn đi sâu vào bên trong, thì một bàn tay kéo tay bạn. Hiro với vẻ mặt nghiêm trọng lắc đầu với bạn."
  },
  AvgDialog_6812_Content_33 = {
    Text = "Bạn nói đúng… Tường đang trở nên hẹp lại. Nếu tiếp tục đi sâu hơn nữa, sẽ không thể ra được."
  },
  AvgDialog_6812_Content_34 = {
    Text = "Tường như đang đáp lại lời cô ấy, bắt đầu chuyển động chậm chạp."
  },
  AvgDialog_6812_Content_35 = {
