  },
  AvgDialog_6812_Content_36 = {
    Text = "Số lượng vô số các mảnh xác tuôn ra từ bức tường, có những mảnh đã thành xương trắng, có những mảnh vẫn còn dính thịt thối rữa."
  },
  AvgDialog_6812_Content_37 = {
    Text = "Những mảnh xác đứt đoạn từ những người leo núi khác nhau, giống như một bông hoa hôi thối và độc ác, từ từ nở rộ trước mặt bạn."
