  AvgDialog_6812_Content_41 = {Text = "Ê…!"},
  AvgDialog_6812_Content_42 = {
    Text = "Chưa để cô ấy nói xong, bạn đã vùng ra khỏi tay cô ấy rồi lao thẳng vào con đường hầm sâu thẳm tỏa ra mùi hôi thối."
  },
  AvgDialog_6812_Content_44 = {
    Text = "Lily! Giáo sư Avis! Hướng dẫn viên! Các bạn đang ở đâu?"
