  AvgDialog_6812_Content_45 = {
    Text = "Hướng tới @3 vĩ đại... lễ tưởng niệm"
  },
  AvgDialog_6812_Content_46 = {
    Text = "Bạn theo tiếng động bước vào cuối hang động, nơi có vô số tảng đá và gai bảo vệ một bàn thờ đen tối."
  },
  AvgDialog_6812_Content_47 = {
    Text = "Có vài cơ thể màu đỏ sẫm trên bàn thờ, co ro quỳ gối dưới đất, đã hoàn toàn im lặng."
  },
  AvgDialog_6812_Content_48 = {
    Text = "Vẫn chậm mất một bước.."
  },
  AvgDialog_6812_Content_49 = {
    Text = "Bạn thò đầu ra từ bóng tối của đường dẫn, ngước lên bầu trời nơi mọi người đang cúi đầu tôn kính."
