  AvgDialog_6812_Content_5 = {
    Text = "Đây là lựa chọn của chị ấy."
  },
  AvgDialog_6812_Content_50 = {
    Text = "Trên vòm trời có một vết nứt không tự nhiên. Trong khoảng trống của đá, lơ lửng một con quái vật màu xanh lam huỳnh quang. Nó từng được nhìn thấy một lần và mang dấu ấn của Hội Giáo đèn lồng."
  },
  AvgDialog_6812_Content_51 = {
    Text = "Đó là sinh vật vô cùng kinh khủng và to lớn, đây cũng là lần đầu tiên bạn có thể quan sát kỹ vẻ bề ngoài của nó."
  },
  AvgDialog_6812_Content_52 = {
    Text = "Gần giống như bộ xương của động vật chân đốt lộ ra ngoài, bề mặt cơ thể phủ một lớp băng giá, trung tâm các chi có một ngọn lửa xanh dương đặc biệt nhảy múa, tỏa ra làn khí lạnh buốt giá, khiến người ta không thể thở nổi."
  },
  AvgDialog_6812_Content_53 = {Text = "Gầm…"},
  AvgDialog_6812_Content_54 = {
    Text = "Lại những mụn mủ này, rắc rối rồi…"
  },
  AvgDialog_6812_Content_55 = {
    Text = "Không được làm thương đại{Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}!"
  },
  AvgDialog_6812_Content_57 = {
    Text = "Quả cầu đen xuất hiện trước mặt bạn, nghiền nát những mụn mủ tấn công bạn thành những vũng chất lỏng bẩn thỉu."
  },
  AvgDialog_6812_Content_58 = {
    Text = "Lily?! Bạn có sao không?"
  },
  AvgDialog_6812_Content_59 = {
    Text = "Lily không sao. Tên ác quỷ đó, là kẻ giết người."
  },
  AvgDialog_6812_Content_6 = {
    Text = "Cô ấy ở đó, cũng coi như đã giành được thời gian cho chúng ta, chúng ta phải nhanh lên…… á!"
  },
  AvgDialog_6812_Content_60 = {
    Text = "Lily chui ra từ một khe hở, tay nhỏ kéo theo một sợi dây thừng leo núi dài, đầu kia thì treo hai người lớn bị bọc kín và không thể động đậy."
  },
  AvgDialog_6812_Content_61 = {
    Text = "Họ đều bị thứ xấu xa này đóng băng, nhưng vẫn chưa chết. Lily nhớ lời của {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}, Lily — phải bảo vệ họ."
  },
  AvgDialog_6812_Content_62 = {
    Text = "Nhưng Lily không nhớ đường, đi nhầm, mới đến được đây…"
  },
  AvgDialog_6812_Content_63 = {
    Text = "Lily, bạn có biết đây là nơi đâu không?"
  },
  AvgDialog_6812_Content_64 = {
    Text = "Lily ngẩng đầu lên, nhìn quái vật cuộn tròn thân thể một cách ngây thơ."
  },
  AvgDialog_6812_Content_65 = {
    Text = "Đây là…… ừ, nơi quái vật ngủ."
  },
  AvgDialog_6812_Content_66 = {
    Text = "Người đã khuất trên bàn thờ đầy máu, nhìn kỹ lại, đều là những người quen của đội thám hiểm đã mất tích trước đó."
  },
  AvgDialog_6812_Content_67 = {
    Text = "Bạn dẫn Lily lẻn qua hành lang, luồn lách qua đống đá vụn. Trong khi chưa làm kinh động quái vật, bạn đã thành công tiếp cận bàn thờ."
  },
  AvgDialog_6812_Content_68 = {
    Text = "Thằng này, có lẽ đang lên kế hoạch cho nghi lễ hiến tế con người còn sống."
  },
  AvgDialog_6812_Content_69 = {
    Text = "Là……gì?"
  },
  AvgDialog_6812_Content_7 = {
    Text = "Bạn bị vấp phải một đoạn xương trắng nổi lên trên mặt đất, nhưng Hiro đã nhanh chóng và kịp thời kéo bạn trở lại."
  },
  AvgDialog_6812_Content_70 = {
    Text = "Bằng cách hiến tế người sống, thức tỉnh một sự tồn tại. Quái vật này được Hội Giáo đèn lồng điều khiển, họ muốn kẻ không nên tồn tại trên thế gian này trở về."
  },
  AvgDialog_6812_Content_71 = {
    Text = "Người đó…… là thứ gì vậy?"
  },
  AvgDialog_6812_Content_72 = {
    Text = "Không rõ, lúc học chỉ đề cập đến nghi lễ tế sống này…"
  },
  AvgDialog_6812_Content_73 = {
    Text = "Dường như đối tượng được quái vật thờ phụng rất khó tính trong việc chọn lễ vật, nên ở đây chỉ có vài người mà thôi."
  },
  AvgDialog_6812_Content_74 = {
    Text = "Những thành viên đoàn thám hiểm bị giết trước đây, với nhiều vết thương trên cơ thể và gãy nát toàn thân, chỉ là… những lễ vật không được mong đợi, nên có thể xử lý tùy tiện."
  },
  AvgDialog_6812_Content_75 = {
    Text = "Đối mặt với sinh vật dễ dàng bị nghiền nát, chúng không hề có chút lòng trắc ẩn đáng thương nào."
  },
  AvgDialog_6812_Content_76 = {
    Text = "Bạn cắn chặt răng, cố gắng không để sự tức giận và buồn bã ảnh hưởng đến mình. Lily cảm nhận được tâm trạng của bạn, dựa vào gần hơn một chút, cố gắng an ủi bạn."
  },
  AvgDialog_6812_Content_77 = {
    Text = "Im lặng một lát, bạn vuốt ve đầu Lily, làn da truyền đến cảm giác ấm áp — đó là sức sống mãnh liệt."
  },
  AvgDialog_6812_Content_78 = {
    Text = "Lily, bây giờ, chúng ta cần đưa những người còn sống về nhà."
  },
  AvgDialog_6812_Content_79 = {
    Text = "Kéo họ đi, đúng rồi, chính là như vậy……khoan đã, hãy cẩn thận!"
  },
  AvgDialog_6812_Content_8 = {
    Text = "Vật làm bạn vấp ngã là một khúc xương chân người hoàn chỉnh, bị nhét sâu vào trong tường, như thể bị bức tường đá nuốt gọn, chỉ còn sót lại chút dấu vết."
  },
  AvgDialog_6812_Content_80 = {
    Text = "Lily kéo xác với sức lực quá lớn, cơ thể như điêu khắc băng đâm mạnh vào đá vụn, phía sau lưng các người đột ngột bùng lên ánh xanh lấp lánh."
  },
  AvgDialog_6812_Content_81 = {
    Text = "Không xong, nó đã thấy chúng ta!"
  },
  AvgDialog_6812_Content_82 = {
    Text = "Gió lạnh như lưỡi dao cắt qua má. Quái vật phun ra sương băng, sau đó dồn sự chú ý vào các bạn trong bóng tối, co giãn xương cốt và tiến đến gần."
  },
  AvgDialog_6812_Content_83 = {
    Text = "……đi đi!"
  },
  AvgDialog_6812_Content_84 = {
    Text = "Hống——"
  },
  AvgDialog_6812_Content_85 = {
    Text = "Lily điều khiển quả cầu lớn, đẩy mạnh con quái vật to lớn vào tường. Nó phát ra tiếng gào thét tức giận."
  },
  AvgDialog_6812_Content_86 = {
    Text = "Các người kéo hai thành viên khảo sát đang thoi thóp, lao vào hành lang."
