  AvgDialog_6812_Content_87 = {
    Text = "Nhanh lên! Bên này!"
  },
  AvgDialog_6812_Content_88 = {
    Text = "Các bạn gần như đang chạy thục mạng, bước chân càng ngày càng nặng nề, nhưng quái vật sẽ nhanh chóng khôi phục khả năng di chuyển, các bạn tuyệt đối không được dừng lại."
  },
  AvgDialog_6812_Content_9 = {
    Text = "Đây……Đây là?!"
  },
  AvgDialog_6812_Content_90 = {
    Text = "Giống như thở ra một luồng khí đục, núi phát ra một tiếng động lớn và nặng nề, sau đó bắt đầu rung chuyển mạnh mẽ, làm cho các người bị xô ngã."
  },
  AvgDialog_6812_Content_91 = {
    Text = "Đây là… chuyện gì vậy?!"
