  AvgDialog_6812_Content_92 = {
    Text = "Không kịp suy nghĩ. Bản năng sinh tồn thúc đẩy các bạn, dùng cả tay và chân để bò qua chất nhầy mà hang động tiết ra, bò về lỗ hang đang thu hẹp."
  },
  AvgDialog_6812_Content_93 = {
    Text = "Đến rồi, ở ngay phía trước——"
  },
  AvgDialog_6812_Content_94 = {
    Text = "<Big:ầm——>"
  },
  AvgDialog_6812_Content_95 = {
    Text = "Ngọn núi hoàn toàn đảo lộn, góc độ hành lang thay đổi đột ngột, nghiêng xuống một cách nhanh chóng."
  },
  AvgDialog_6812_Content_96 = {
    Text = "Dưới lớp chất nhầy trơn tuột không thể nắm bắt, các ngươi gắng sức tiến gần đến lỗ hổng sáng ở cuối hang, nhưng sự co bóp của hành lang lại càng trở nên mạnh mẽ hơn."
  },
  AvgDialog_6812_Content_97 = {
    Text = "Tấm đá ấm áp không ngừng co lại, ép chặt vào lồng ngực của bạn, bạn chỉ cảm thấy không khí càng lúc càng loãng. Thân thể của Lily cũng bị kẹt vào khe đá, hoàn toàn không thể nhúc nhích."
  },
  AvgDialog_6812_Content_98 = {
    Text = "Cửa ra duy nhất bị những tảng đá đen dần nuốt chửng, con đường gần trong gang tấc bị cắt đứt, trước mắt bạn chìm vào bóng tối vô vọng."
  },
  AvgDialog_6812_Content_99 = {
    Text = "Không thể...ở đây.."
  },
  AvgDialog_6813_Content_1 = {
    Text = "Quái vật quái dị bị đánh rơi xuống mặt băng, tạo ra một rãnh sâu như hào trời. Nó vo ve, nhiều lần bò dậy nhưng lại ngã xuống đất."
  },
  AvgDialog_6813_Content_10 = {
    Text = "Nó đang triệu hồi lực lượng cùng nguồn gốc với nó. Nếu nó tiêu thụ chúng ta, tinh thần của chúng ta sẽ hòa hợp với nó…"
  },
  AvgDialog_6813_Content_11 = {
    Text = "Hiro nhắm mắt lại. Những phân mảnh đã từng tiêu tan lại hiện lên trong tâm trí cô."
  },
  AvgDialog_6813_Content_12 = {
    Text = "Nếu, nếu tôi tiêu thụ nó thì như thế nào?"
  },
  AvgDialog_6813_Content_13 = {
    Text = "Nó muốn tiêu thụ tôi, hút cạn lực lượng của tôi, vậy thì ngược lại, tôi cũng có thể tiêu thụ nó!"
  },
  AvgDialog_6813_Content_14 = {
    Text = "Hiro mở mắt thêm lần nữa."
  },
  AvgDialog_6813_Content_15 = {
    Text = "Cách duy nhất là thử hấp thụ lực lượng của tuyết sơn, giống như \"Hiro\" kia..."
  },
  AvgDialog_6813_Content_16 = {
    Text = "Hiro cúi người xuống, học theo bạn, vụng về xoa nhẹ mái tóc mềm mại của Lily."
  },
  AvgDialog_6813_Content_17 = {
    Text = "Lily đã mất kiểm soát, nửa thân mình chìm vào núi. Những giọt nước mắt đen nhánh lăn dài trên khuôn mặt, ánh mắt trống rỗng nhìn chằm chằm vào Hiro."
  },
  AvgDialog_6813_Content_18 = {
    Text = "Cô ấy đã chịu đựng quá nhiều đau khổ. Hãy để tôi làm."
  },
  AvgDialog_6813_Content_19 = {
    Text = "Không… không được, không nên là kết quả như vậy… chúng ta chắc chắn có thể nghĩ ra cách khác…"
  },
  AvgDialog_6813_Content_2 = {
    Text = "Dù đã hấp hối, nhưng ngọn lửa ở lưng nó vẫn tiếp tục cháy, thậm chí còn lớn hơn, sắp thiêu rụi chính nó."
  },
  AvgDialog_6813_Content_20 = {
    Text = "Không còn thời gian nữa, Người Giữ Gìn."
  },
  AvgDialog_6813_Content_21 = {
    Text = "Muốn để các người sống sót rời khỏi Elworth, muốn không phải trở thành quái vật trước mặt bạn lần nữa, chỉ có cách này thôi…"
  },
  AvgDialog_6813_Content_22 = {
    Text = "Bạn sẽ chết ở đây!"
  },
  AvgDialog_6813_Content_23 = {
    Text = "\"“Dù vậy… thì sao?”\""
  },
  AvgDialog_6813_Content_25 = {
    Text = "Cô đâm kiếm vào đá, những lọn tóc ướt nhẹp rũ xuống trước mặt, nhanh chóng đông thành những khối băng nhọn hoắt, lay động không ngừng theo đôi vai run rẩy của cô."
  },
  AvgDialog_6813_Content_26 = {
    Text = "Gió lạnh trên tuyết sơn không ngừng hoành hành, những âm thanh trầm đục tiếp tục vang lên."
  },
  AvgDialog_6813_Content_27 = {
    Text = "Cơn đau dữ dội liên tục giày vò cô, nhưng vào lúc này, giọng nói trong đầu cô đặc biệt rõ ràng."
  },
  AvgDialog_6813_Content_28 = {
    Text = "Tôi có rất nhiều việc không muốn làm, rất nhiều……bị ép buộc, bị thúc đẩy phải làm."
  },
  AvgDialog_6813_Content_29 = {
