  AvgDialog_6813_Content_3 = {
    Text = "Hiro đã đâm gai vào ngọn lửa một cách dữ dội, nhưng dù có bao nhiêu lần đi nữa, cũng không thể dập tắt ngọn lửa cháy."
  },
  AvgDialog_6813_Content_30 = {
    Text = "Có phải ngay cả khả năng giao tiếp cũng đã mất rồi không?"
