  },
  AvgDialog_6813_Content_39 = {
    Text = "Tôi từng nghĩ, trả thù chính là tất cả của tôi… nhưng cho đến hôm nay tôi mới hiểu ra, tôi đã hiểu lầm bản chất ý nghĩa và tìm sai đối thủ."
  },
  AvgDialog_6813_Content_4 = {
    Text = "Đây là… chuyện gì vậy?!"
  },
  AvgDialog_6813_Content_40 = {
    Text = "Chỉ có lực lượng đủ mạnh mới có thể hoàn thành việc trả thù của chúng ta. Trả thù chính là ý nghĩa duy nhất của chúng ta."
  },
  AvgDialog_6813_Content_41 = {
    Text = "Núi muốn gặp tôi, tôi sẽ đến gặp Người."
  },
  AvgDialog_6813_Content_42 = {
    Text = "Tôi là tương lai của bạn, \"Hiro\". Khi bạn có can đảm giơ kiếm đối đầu với số phận, bạn sẽ trở thành tôi."
  },
  AvgDialog_6813_Content_43 = {
    Text = "Cho nên bạn muốn trả thù kẻ phản bội, muốn bảo vệ Francis đã cứu bạn. \nNhưng chiến đấu không phải là thứ như vậy."
  },
  AvgDialog_6813_Content_44 = {
    Text = "Không phải để bảo vệ, không phải để trả thù, không phải để chứng minh. \nChiến đấu chỉ là chiến đấu mà thôi."
  },
  AvgDialog_6813_Content_45 = {
    Text = "Thế giới của bạn quá nhỏ hẹp, nên luôn như con bướm đêm để ý đến những tia sáng le lói mà người khác thắp lên."
  },
  AvgDialog_6813_Content_46 = {
    Text = "Nếu có cơ hội, thử đi khám phá xem thế giới rộng lớn hơn nhé."
