  AvgDialog_6813_Content_50 = {
    Text = "Tôi sẽ không bỏ lại bất kỳ người bạn đồng hành nào… tuyệt đối không!"
  },
  AvgDialog_6813_Content_53 = {
    Text = "Lơ-tan nói, chiến đấu chỉ là chiến đấu, không phải để bảo vệ, cũng không phải trả thù."
  },
  AvgDialog_6813_Content_54 = {
    Text = "Tôi đã suy nghĩ rất lâu, cuối cùng hiểu, tại sao bạn và thân thể được đánh thức của bạn lại mạnh mẽ như vậy…"
