  AvgDialog_6813_Content_70 = {
    Text = "Hiro bị chất lỏng đen tối cuốn vào, ràng buộc, sự điên rồ vô thức biến thành những xiềng xích kiên cố, trói cô vào vô số gông cùm."
  },
  AvgDialog_6813_Content_73 = {
    Text = "Cánh vai gầy guộc của cô ấy mang trên mình những xích sắt, bước đi một mình trong cô độc. Thân thể của cô ấy bị xiềng xích nặng nề trói buộc, dần cảm thấy ngạt thở, quỳ xuống trên mặt tuyết."
  },
  AvgDialog_6813_Content_74 = {Text = "Hiro……"},
  AvgDialog_6813_Content_75 = {
    Text = "Lời thì thầm cấm kỵ không ngừng đổ vào tai, trong tiếng động đặc quánh và u tối, Hiro cảm nhận được sự cộng hưởng của núi và tim."
