  AvgDialog_6813_Content_77 = {
    Text = "Dưới lớp đất đá đóng băng cứng ngắc, con quái vật vừa được thức tỉnh đang gầm gừ đầy khao khát, thèm khát sự hiện diện của cô ấy."
