  },
  AvgDialog_6816_Content_27 = {
    Text = "Sau vài giây, các bạn dừng lại. Vách đá sinh tử vừa rồi, bây giờ đã trở thành đất bằng."
  },
  AvgDialog_6816_Content_28 = {
    Text = "Cách mấy trăm mét, Lily đứng ở vị trí bạn vừa dùng rìu băng đập, vẫy tay gọi các bạn."
  },
  AvgDialog_6816_Content_29 = {
    Text = "Những lời hùng hồn và quyết tâm sống chết vừa rồi dường như trở thành một vở hài kịch đáng cười."
  },
  AvgDialog_6816_Content_3 = {
    Text = "Trong khoảnh khắc cô ấy rơi xuống, bạn theo bản năng đưa tay ra kéo cô ấy lại."
