  AvgDialog_6816_Content_37 = {
    Text = "Chúng ta có lẽ phải chuẩn bị cho tình huống xấu nhất, cần phải luôn cẩn thận với những biến đổi của địa hình núi."
  },
  AvgDialog_6816_Content_38 = {
    Text = "Đường xuống núi trước đó đã bị chặn, chúng ta chỉ có thể đi lên đỉnh núi trước, rồi tìm đường khác… Chúng ta cần nhanh chóng tìm cách xuống núi."
  },
  AvgDialog_6816_Content_4 = {
    Text = "Cuốc băng đâm vào núi, bạn khó nhọc treo mình giữa vách đá tuyết sơn, vết thương trên cánh tay thấm ra máu tươi, gây ra cơn đau dữ dội từng trận."
  },
  AvgDialog_6816_Content_40 = {
    Text = "Cẩn thận, đây còn có một khe tuyết… Thật may, suýt nữa lại rơi vào rồi."
