  AvgDialog_6816_Content_44 = {
    Text = "Tôi tạm thời còn chịu đựng được, đừng lo lắng…"
  },
  AvgDialog_6816_Content_45 = {Text = "À!——"},
  AvgDialog_6816_Content_46 = {
    Text = "Lily, bạn sao vậy?"
  },
  AvgDialog_6816_Content_47 = {
    Text = "Ể… Lily thấy thứ gì đó kỳ quái……"
  },
  AvgDialog_6816_Content_48 = {
    Text = "Cô bé dùng tay nhỏ che đầu, bối rối nắm nhẹ vạt áo của bạn."
  },
  AvgDialog_6816_Content_49 = {
    Text = "Lily đã thấy gì?"
  },
  AvgDialog_6816_Content_5 = {
    Text = "Cũng đang ở tay kia của cô, hai thành viên thám hiểm bị trói chặt."
  },
  AvgDialog_6816_Content_50 = {
    Text = "Cao nguyên tuyết, người đã chết, sao trời, còn có…… chúng ta."
  },
  AvgDialog_6816_Content_51 = {
    Text = "Tôi cũng thấy, những bóng ma mờ ảo không ngừng quấn quanh, quấn quanh tôi… và Lily."
  },
  AvgDialog_6816_Content_52 = {
    Text = "Tôi có thể cảm nhận được, có một lực lượng đang thức tỉnh."
  },
  AvgDialog_6816_Content_53 = {
    Text = "Sông băng lại phát ra tiếng gầm rống, bắt đầu thay đổi tư thế một cách cực kỳ chậm chạp."
  },
  AvgDialog_6816_Content_54 = {
    Text = "Lần này, hồ băng đã bị che khuất lâu nay lộ ra diện mạo thật sự, các người có thể nhìn thấy cái bóng gầy guộc với những vết mụn đen sẫm, đầy ghê rợn trên mặt hồ băng."
  },
  AvgDialog_6816_Content_55 = {
    Text = "Khe nứt trên hồ băng ngày càng lớn, giống như một vết rách sâu hoắm, nằm ngang trên mặt hồ dưới dãy băng tuyết kéo dài."
  },
  AvgDialog_6816_Content_56 = {
    Text = "Dịch nhầy đen chảy ra không ngừng, bao phủ lên cơ thể của \"Hiro\" khác."
  },
  AvgDialog_6816_Content_57 = {
    Text = "Tôi cảm nhận được… nhiều hơn, hãy cho tôi thêm nữa!"
  },
  AvgDialog_6816_Content_58 = {
    Text = "Những mụn mủ kỳ quái này cảm nhận được lời gọi của cô, rung động với tiếng vo ve phấn khích, chen chúc nhau chui vào khoang miệng của cô, như thể khao khát được cô nuốt chửng."
  },
  AvgDialog_6816_Content_59 = {
    Text = "Chúng dường như thích bị nghiền nát, mê đắm việc bị nuốt chửng, và khao khát được tiêu hóa."
  },
  AvgDialog_6816_Content_6 = {
    Text = "Cô ấy muốn nhảy lên, nhưng rìu băng, và cánh tay run rẩy của bạn, đã không thể chịu đựng thêm trọng lượng nào nữa."
  },
  AvgDialog_6816_Content_60 = {
    Text = "Các ngươi đến trước một \"Hiro\" khác. Thân thể của cô ta ngâm trong những bọng mủ đen kịt, hình dáng đã trở nên mờ ảo như làn sương mỏng manh, dễ dàng bị thổi tan."
  },
  AvgDialog_6816_Content_61 = {
    Text = "Bây giờ rời khỏi đây, vẫn còn cơ hội…"
  },
  AvgDialog_6816_Content_62 = {
    Text = "Rời đi… chúng ta chưa bao giờ có quyền rời đi."
  },
  AvgDialog_6816_Content_63 = {
    Text = "Một \"Hiro\" khác bỗng nhiên mất đi sự ám ảnh và điên rồ trong mắt."
  },
  AvgDialog_6816_Content_64 = {
    Text = "Cô nhìn về phía Hiro, trong ánh mắt chứa đầy sự bình thản và tĩnh tâm chưa từng có."
  },
  AvgDialog_6816_Content_65 = {
    Text = "Những thứ từng gây thương tổn cho bạn, những mối hận khắc cốt ghi tâm, bạn đều quên rồi sao, \"Hiro\"?"
  },
  AvgDialog_6816_Content_66 = {
    Text = "Tôi chưa bao giờ quên… Tôi chỉ là…"
  },
  AvgDialog_6816_Content_67 = {
    Text = "Bạn đang bối rối, \"Hiro\"."
  },
  AvgDialog_6816_Content_68 = {
    Text = "Chỉ có lực lượng đủ mạnh mới có thể hoàn thành việc trả thù của chúng ta. Trả thù chính là ý nghĩa duy nhất của chúng ta."
  },
  AvgDialog_6816_Content_69 = {
    Text = "Trả thù… cho ai ?"
  },
  AvgDialog_6816_Content_7 = {
    Text = "Lớn {Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}!"
  },
  AvgDialog_6816_Content_70 = {
    Text = "Số phận."
  },
  AvgDialog_6816_Content_71 = {
    Text = "Hai chữ \"bình tĩnh\" khiến thân thể Hiro rùng mình."
  },
  AvgDialog_6816_Content_72 = {
    Text = "Dù chúng ta ở đâu, ngọn núi này cũng sẽ gọi chúng ta, nuốt chửng chúng ta."
  },
  AvgDialog_6816_Content_73 = {
    Text = "Đây là số phận của chúng ta, giống như những điều tồi tệ mà chúng ta đã trải qua…"
  },
  AvgDialog_6816_Content_74 = {
    Text = "Bạn đã biết câu trả lời từ lâu, nhưng đã làm ngơ đối với nó. Đúng không?"
  },
  AvgDialog_6816_Content_75 = {
    Text = "So với những người và việc khiến bạn căm ghét, số phận là một đối thủ đáng gờm…"
  },
  AvgDialog_6816_Content_76 = {
    Text = "Ngươi, kẻ hèn nhát như vậy, không xứng đáng được gọi là chiến binh."
  },
  AvgDialog_6816_Content_77 = {
    Text = "Thân thể của bạn đã không thể duy trì được nữa… Bạn sẽ chết ở đây."
  },
  AvgDialog_6816_Content_78 = {
    Text = "Dù sao đi nữa…… thì đã sao?"
  },
  AvgDialog_6816_Content_79 = {
    Text = "Cô ta quay mặt về phía các người, miệng nở nụ cười đầy tinh ranh, để lộ hai chiếc răng nanh sắc bén."
  },
  AvgDialog_6816_Content_8 = {
    Text = "Lily lo lắng gọi to, muốn ngưng tụ ra quả cầu đen để nâng các bạn lên."
  },
  AvgDialog_6816_Content_80 = {
    Text = "Chiếc đèn dẫn dụ tôi đến đây, muốn lợi dụng tôi để hồi sinh @3. Ngọn núi này đang gọi tôi, muốn nuốt chửng tôi. Tôi đã biết từ lâu, nhưng tôi vẫn đến."
  },
  AvgDialog_6816_Content_81 = {
    Text = "Núi muốn gặp tôi, tôi sẽ đến gặp Người."
  },
  AvgDialog_6816_Content_82 = {
    Text = "Tôi phải cảm ơn Đèn Dẫn Đường, đã cho tôi cơ hội đối mặt với Ngài…"
  },
  AvgDialog_6816_Content_83 = {
    Text = "Bạn yếu đuối như vậy, nhưng bạn cũng đã đến, phải không?"
  },
  AvgDialog_6816_Content_84 = {
    Text = "Tôi là tương lai của bạn, \"Hiro\". Khi bạn có can đảm giơ kiếm đối đầu với số phận, bạn sẽ trở thành tôi."
  },
  AvgDialog_6816_Content_85 = {
    Text = "Những mụn mủ đen ngày càng tích tụ nhiều, giống như một đàn sinh vật nguyên thủy đói khát, tham lam lao vào thân thể cô, lan dần lên gò má cô."
  },
  AvgDialog_6816_Content_86 = {
    Text = "Cô ấy cười lên, như một con thú săn mồi dữ dội, như một vị vua sắp sửa bước lên ngai vàng."
  },
  AvgDialog_6816_Content_87 = {
    Text = "Hãy nhìn này, \"Hiro\"… Tôi sẽ tiêu thụ Ngài, tôi sẽ mạnh hơn, mọi số phận đều không thể ngăn cản tôi nữa!"
  },
  AvgDialog_6816_Content_88 = {
    Text = "Không còn xiềng xích…… không còn…… tôi sẽ không bội phản……"
  },
  AvgDialog_6816_Content_89 = {
    Text = "Những mụn mủ đen không ngừng lan rộng, tích tụ trên cơ thể cô, chui vào thân thể cô đã không còn chịu đựng được nữa, bao phủ khuôn mặt bình tĩnh nhưng điên rồ của cô…"
  },
  AvgDialog_6816_Content_9 = {
    Text = "Nhưng cô ấy đã cạn kiệt sức lực trong cuộc chiến đấu vừa rồi, quả cầu đen đã khó mà ngưng tụ, đừng nói đến việc chở trọng lượng của một người."
  },
  AvgDialog_6816_Content_90 = {
    Text = "Tôi sẽ……<Big:trả thù!>"
