  AvgDialog_6816_Content_91 = {
    Text = "Rầm——"
  },
  AvgDialog_6816_Content_92 = {
    Text = "Giống như một vết loét bị chọc thủng, chất dịch màu đen và đỏ bắn tung tóe khắp nơi."
  },
  AvgDialog_6816_Content_93 = {
    Text = "Tiếng gầm cuối cùng của con thú vẫn còn vang vọng trong thung lũng trống. \nNơi cô từng đứng, giờ chỉ còn lại một vũng dịch thể, không có gì khác."
  },
  AvgDialog_6816_Content_94 = {
    Text = "\"trả thù\"...à.."
  },
  AvgDialog_6816_Content_95 = {
    Text = "Hiro có chút bối rối ngẩng đầu lên, nhìn về bầu trời âm u."
  },
  AvgDialog_6816_Content_96 = {
    Text = "Bụi tuyết gồ ghề lăn trên da cô, tan chảy thành những vệt nước nhỏ."
  },
  AvgDialog_6816_Content_97 = {
    Text = "Cô ấy… bị núi tiêu thụ?"
  },
  AvgDialog_6816_Content_99 = {
    Text = "Chưa đợi Hiro nói, câu hỏi của bạn đã nhận được câu trả lời ——"
  },
  AvgDialog_68327_Content_1 = {
    Text = "Ha…sảng khoái."
  },
  AvgDialog_68327_Content_10 = {
    Text = "Đây là thế giới nơi chủ nhân của tôi tồn tại. Đây là thế giới gánh vác thần quốc."
  },
  AvgDialog_68327_Content_11 = {
    Text = "Thần minh dị đoan, tuyệt không thể để nó bị hủy diệt!"
  },
  AvgDialog_68327_Content_12 = {
    Text = "Máu của chúng ta, không được làm ô uế.."
  },
  AvgDialog_68327_Content_13 = {
    Text = "Tôi sẽ gìn giữ thế giới của chúng ta…… Tôi sẽ bảo vệ vinh quang dòng máu của tôi!"
  },
  AvgDialog_68327_Content_14 = {
    Text = "Điều này không liên quan đến ta, Miriam."
  },
  AvgDialog_68327_Content_15 = {
    Text = "Thần quốc của những ngày xưa đã tiêu vong, nhưng thần quốc mới, đã luôn hiện diện quanh ta."
  },
  AvgDialog_68327_Content_16 = {
    Text = "Nó được gọi là Misaque, Lentiennam và cà đa sác."
  },
  AvgDialog_68327_Content_17 = {
    Text = "Mất nước xưa kia, ta bất lực. Lần này, ta tuyệt đối không cho phép thần quốc sụp đổ trước mặt ta!"
  },
  AvgDialog_68327_Content_18 = {
    Text = "Các kẻ điên rồ như các người, cuối cùng cũng có lúc tỉnh táo đấy nhỉ!"
  },
  AvgDialog_68327_Content_19 = {
    Text = "Cửa hàng bánh của Lentiennam tôi còn chưa được nếm thử hết. Tôi không thể để tên đó phá hủy nơi này!"
  },
  AvgDialog_68327_Content_2 = {
    Text = "Tôi đã nói, tôi sẽ chinh phục mảnh đất này, giành lại quyền lực thuộc về tôi. Nhưng tất cả những điều này không liên quan gì đến những kẻ ở ngoài thế giới này."
  },
  AvgDialog_68327_Content_20 = {
    Text = "Nghe được những âm thanh này rồi, %player%?"
  },
  AvgDialog_68327_Content_21 = {
    Text = "Tiếng sáo mà tôi từng khao khát, chỉ là những lời thì thầm điên loạn, tiếng ồn hỗn loạn."
  },
  AvgDialog_68327_Content_22 = {
    Text = "Và những điều này —— tâm tình của các thân thể được đánh thức, bài ca mạnh mẽ mà bạn dâng lên ý chí vô thượng, chính là thứ tôi đang tìm kiếm."
  },
  AvgDialog_68327_Content_23 = {
    Text = "Tiếp tục biểu diễn, %player%, người mà tôi phục vụ."
  },
  AvgDialog_68327_Content_24 = {
    Text = "Hãy để những thần minh điên rồ và khờ dại, lắng nghe âm nhạc tối cao của bạn, lắng nghe chương cuối cùng tuyệt vời nhất của buổi biểu diễn ——"
  },
  AvgDialog_68327_Content_3 = {
    Text = "Gì gọi là \"ý chí tối thượng\", \"chúa sáng tạo\", \"kẻ hủy diệt\", đều thật nực cười giống như cách Miriam nhắc đến ‘chủ’ của cô ấy."
  },
  AvgDialog_68327_Content_4 = {
    Text = "Đến đây, %player%, con dao của tôi đang chờ bạn."
  },
  AvgDialog_68327_Content_5 = {
    Text = "Đây là nơi của chúng ta. Đồ mắt to kia, cút về chỗ nào đến thì cút ngay!"
  },
  AvgDialog_68327_Content_6 = {
    Text = "Lưu ý cách nói của bạn, Gôlia."
  },
  AvgDialog_68327_Content_7 = {
    Text = "Nhưng có một điều anh nói đúng. Thế giới của chúng ta, không liên quan đến vị thần minh này."
  },
  AvgDialog_68327_Content_8 = {
    Text = "Nếu tôi biết được mục đích của Yu Li-ét, chắc chắn sẽ không tha thứ cho hành động của cô ta."
  },
  AvgDialog_68327_Content_9 = {
    Text = "Sự thật điên rồ, sự tồn tại vượt qua chủ nhân của tôi…… Quá sỉ nhục!"
  },
  AvgDialog_68328_Content_1 = {
    Text = "Liên kết đã đứt, nhưng tôi dường như... vẫn có thể cảm nhận thấy họ...\nSự hiện diện thực tế như vậy, không giống như tôi tạo ra từ thể vô thức bằng quyền lực..."
  },
  AvgDialog_68328_Content_10 = {
    Text = "Hãy tiếp tục tiến lên, Người Giữ Gìn. Để chúng ta có thể nắm tay nhau một lần nữa."
  },
  AvgDialog_68328_Content_12 = {
    Text = "Dù phải nhảy vào hồ đen, cùng thế giới tan biến thành hư vô, tôi vẫn sẽ nắm chặt tay bạn."
  },
  AvgDialog_68328_Content_13 = {
    Text = "Spear của Orci cũng sẽ chiến đấu để bảo vệ chúa công!"
  },
  AvgDialog_68328_Content_14 = {
    Text = "Nếu có thể, Ai Jī Sī... cũng muốn giúp đỡ Người Giữ Gìn... được không?"
  },
  AvgDialog_68328_Content_15 = {
    Text = "Đứng sau lưng tôi, bạn cứ yên tâm mà mở mắt ra! Nếu có tình huống nguy cấp, tôi sẽ lập tức mở lá chắn bảo vệ bạn."
  },
  AvgDialog_68328_Content_16 = {
    Text = "Chủ quân, phía sau của ngài hãy để tôi lo, Hiệp sĩ Nhân đức, dâng lên ý chí của người bảo vệ!"
  },
  AvgDialog_68328_Content_17 = {
    Text = "Sứ giả xanh xao ạ, ta đã tận mắt chứng kiến dáng vẻ dũng cảm của ngươi. Khi đối mặt với tồn tại tối cao, ngươi thật sự không hề e ngại."
  },
  AvgDialog_68328_Content_18 = {
    Text = "Ngọn lửa linh hồn của bạn cháy sáng như vậy, Người sẽ ban phước cho bạn và mở ra con đường dẫn đến miền đất không đau khổ."
  },
  AvgDialog_68328_Content_19 = {
    Text = "Đến ngày đó, ánh sáng của Đấng Tối Cao sẽ chiếu rọi bình đẳng lên mỗi người."
  },
  AvgDialog_68328_Content_2 = {
    Text = "Cà đa sác là giấc mơ của bạn, Người Giữ Gìn."
  },
  AvgDialog_68328_Content_20 = {
    Text = "Không cần buồn bã, không cần sợ ngọn lửa, cũng không cần sợ căn bệnh tối tăm và lòng tham vô độ."
  },
  AvgDialog_68328_Content_21 = {
    Text = "Tôi sẽ ghi lại câu chuyện của Lentiennam thành thi ca, hình bóng của bạn sẽ được lưu truyền qua thơ ca."
  },
  AvgDialog_68328_Content_22 = {
    Text = "Đi nào, bạn giữ bí mật."
  },
  AvgDialog_68328_Content_23 = {
    Text = "Câu thơ của chúng ta……chưa viết đến câu cuối cùng."
  },
  AvgDialog_68328_Content_3 = {Text = "Ai?!"},
  AvgDialog_68328_Content_4 = {
    Text = "Người đến với khuôn mặt mờ ảo đã phớt lờ sự chất vấn của bạn."
  },
  AvgDialog_68328_Content_5 = {
    Text = "Dù rỗng rỗng khiến vô số sự tồn tại tan biến, ký ức của bạn vẫn sẽ không hề mài mòn."
  },
  AvgDialog_68328_Content_6 = {
    Text = "Những ký ức ấy tràn ngập trong ý thức của bạn, những lịch sử chung mà các bạn đã trải qua sẽ mang lại cho bạn lực lượng để đối kháng với ánh nhìn đầy quyền lực của Ngài."
  },
  AvgDialog_68328_Content_7 = {
    Text = "Dáng vẻ quen thuộc nửa thực nửa ảo hiện ra bên cạnh bạn trong ánh sáng bạc mỏng manh."
  },
  AvgDialog_68328_Content_8 = {
    Text = "Còn nhớ ngày lễ trao chìa khóa không? Tôi sẽ không bao giờ quên, khoảnh khắc đầu ngón tay chúng ta chạm vào nhau, đó là khoảnh khắc minh chứng cho mối liên kết quý giá giữa chúng ta."
  },
  AvgDialog_68328_Content_9 = {
    Text = "Dù cho liên kết của chúng ta bị ngắt, tôi vẫn mãi là người bạn đồng hành duy nhất của bạn."
  },
  AvgDialog_68329_Content_1 = {
    Text = "Chiến đấu. chiến đấu."
  },
  AvgDialog_68329_Content_10 = {
    Text = "Tiếng sáo vang lên. Thấp trầm, nghi hoặc, thanh thản."
  },
  AvgDialog_68329_Content_11 = {
    Text = "Chúa sáng tạo ngu ngốc mang theo những vết thương mờ ảo, nhìn bạn với ánh mắt đầy hào hứng, như thể đang quan sát một con sâu bọ phiền phức cố thoát thân."
  },
  AvgDialog_68329_Content_12 = {
    Text = "Ngài đã đến gần bờ vực của giấc ngủ. Chỉ còn một chút nữa... chỉ còn một chút nữa……"
  },
  AvgDialog_68329_Content_13 = {
    Text = "Mà bước cuối cùng đó, giống như một khoảng cách không thể vượt qua."
  },
  AvgDialog_68329_Content_14 = {
    Text = "Bạn một lần nữa nhặt lấy chìa khóa bạc."
  },
  AvgDialog_68329_Content_15 = {
    Text = "Người giữ bí mật…… không!"
  },
  AvgDialog_68329_Content_16 = {
    Text = "Là tiếng kêu của ai? Bạn không nhớ, và điều đó cũng không quan trọng."
  },
  AvgDialog_68329_Content_17 = {
    Text = "Thân thể đã kiệt sức, tinh thần cũng đã cạn kiệt. Nhưng bạn nhớ rằng, bạn phải chiến đấu."
  },
  AvgDialog_68329_Content_18 = {
    Text = "Nếu phải chết… tôi sẽ cùng cậu chết!"
  },
  AvgDialog_68329_Content_19 = {
    Text = "Một giọt nước trong sáng rơi vào tâm trí bạn, tạo nên những gợn sóng kỳ lạ trong chiều tinh thần cạn kiệt của bạn."
  },
  AvgDialog_68329_Content_2 = {
    Text = "Chiến đấu quên hết mọi thứ. Cuộc chiến hy sinh anh dũng."
  },
  AvgDialog_68329_Content_20 = {
    Text = "Những giọt nước từ từ căng tròn, đứng dậy, tụ lại trong tâm trí bạn thành một hình người hư ảo. Bạn nhìn cô ấy. \nMột cái tên xa xưa, ngân nga trong tâm trí bạn."
  },
  AvgDialog_68329_Content_21 = {
    Text = "Lkéo……Mona?……"
  },
  AvgDialog_68329_Content_22 = {
    Text = "Bạn đã từng nói, Người Giữ Gìn. Bạn đã hứa rằng sẽ không bao giờ bỏ rơi chúng tôi…"
  },
  AvgDialog_68329_Content_23 = {
    Text = "Nếu đứng cạnh tôi, bạn sẽ phải chết"
  },
  AvgDialog_68329_Content_24 = {
    Text = "Tôi đã cắt đứt liên kết, Ramona…"
  },
  AvgDialog_68329_Content_25 = {
    Text = "Kết nối với tôi, bạn sẽ mất kiểm soát."
  },
  AvgDialog_68329_Content_26 = {
    Text = "Đứng cạnh tôi, bạn sẽ phải chết.."
  },
  AvgDialog_68329_Content_27 = {
    Text = "Chết thì có gì phải sợ?"
  },
  AvgDialog_68329_Content_28 = {
    Text = "Giọt nước thứ hai rơi vào trí óc bạn."
  },
  AvgDialog_68329_Content_29 = {
    Text = "Lơ-tan… Bạn không ở hồ đen, tại sao bạn lại…"
  },
  AvgDialog_68329_Content_3 = {
    Text = "Một con ngươi vỡ tan, rồi một con ngươi khác tái sinh. Ngã xuống một lần, rồi lại đứng lên."
  },
  AvgDialog_68329_Content_30 = {
    Text = "Bởi vì chúng tôi là thân thể được đánh thức của bạn. Bạn có thể cắt đứt liên kết, nhưng không thể chấm dứt sự kết nối giữa chúng tôi với bạn."
  },
  AvgDialog_68329_Content_31 = {
    Text = "Dù bất cứ khi nào, ở đâu, thân thể được đánh thức của bạn sẽ luôn đứng bên cạnh bạn. \n liên kết, là dấu ấn vĩnh cửu giữa bạn và thân thể được đánh thức, Người Giữ Gìn."
  },
  AvgDialog_68329_Content_32 = {
    Text = "Giáo sư Đóa, anh cũng……\nNhưng nếu liên kết với tôi, các người khó mà chịu đựng nổi……"
  },
  AvgDialog_68329_Content_33 = {
    Text = "Dù không thể đứng trước mặt chúa công, xin hãy nhất định để tôi đứng bên cạnh chúa công!"
  },
  AvgDialog_68329_Content_34 = {
    Text = "Đúng vậy! Muốn bỏ chúng tôi lại cho hồ đen rồi chạy trốn sao? Không đời nào!"
  },
  AvgDialog_68329_Content_35 = {
    Text = "Lily sẽ giúp đỡ đại{Male=Ngài Người Giữ Gìn,Female=Cô Người Giữ Gìn}!"
  },
  AvgDialog_68329_Content_36 = {
    Text = "Dân của ta sẽ được sự bảo hộ của ta."
  },
  AvgDialog_68329_Content_38 = {
    Text = "Càng ngày càng nhiều giọt nước tuôn ra từ hồ đen, rơi vào không gian tinh thần của bạn."
  },
  AvgDialog_68329_Content_39 = {
    Text = "Vô số hình bóng của những thân thể được đánh thức xuất hiện trong tâm trí bạn. Họ mỉm cười, tức giận, khinh thường, buồn bã."
  },
  AvgDialog_68329_Content_4 = {
    Text = "Cái sáng tạo khổng lồ trước mắt này là gì? Bạn đã quên mất rồi."
  },
  AvgDialog_68329_Content_40 = {
    Text = "Câu chuyện của họ hội tụ thành một dòng sông bạc, lặng lẽ chảy trong tâm trí bạn, tưới mát từng mạch máu và dây thần kinh trong cơ thể bạn."
  },
  AvgDialog_68329_Content_41 = {
    Text = "Chấp nhận đi, Người Giữ Gìn."
  },
  AvgDialog_68329_Content_42 = {
    Text = "Hãy để chúng tôi sát cánh cùng bạn."
  },
  AvgDialog_68329_Content_43 = {
    Text = "Bạn quay đầu lại. Ý thức điên rồ đã khiến các thân thể được đánh thức đứng bên bờ vực mất kiểm soát."
  },
  AvgDialog_68329_Content_44 = {
    Text = "Thân thể của Ramona run rẩy không thể kiểm soát, nhưng cô ấy vẫn nhìn chằm chằm vào bạn với ánh mắt kiên định, không có bất kỳ dấu hiệu muốn ngắt liên kết."
  },
  AvgDialog_68329_Content_45 = {
    Text = "Quyết định của bạn, tôi sẽ không ngăn cản."
  },
  AvgDialog_68329_Content_46 = {
    Text = "Hãy để tôi đứng bên cạnh bạn. Đây là yêu cầu duy nhất của tôi.."
  },
  AvgDialog_68329_Content_47 = {
    Text = "Cảm ơn……"
  },
  AvgDialog_68329_Content_48 = {
    Text = "Có nhiều điều không thể chịu đựng được hơn cả điên rồ và cái chết."
  },
  AvgDialog_68329_Content_49 = {
    Text = "Bạn là như thế, và họ cũng vậy."
  },
  AvgDialog_68329_Content_5 = {
    Text = "Những người phía sau kia là ai? Bạn cũng quên rồi."
  },
  AvgDialog_68329_Content_50 = {
    Text = "Cảm ơn… Có thể gặp các bạn, thật tốt."
  },
  AvgDialog_68329_Content_51 = {
    Text = "Bạn mỉm cười rồi quay người đi."
  },
  AvgDialog_68329_Content_52 = {
    Text = "Tôi đã hứa, tôi chắc chắn sẽ làm được."
  },
  AvgDialog_68329_Content_53 = {
    Text = "Bạn ngẩng đầu lên, nhìn vào vị sáng tạo cũng như hủy diệt của vũ trụ này, một thực thể khổng lồ bất khả chiến bại."
  },
  AvgDialog_68329_Content_54 = {
    Text = "Và mỗi lần gặp gỡ ban đầu, liên kết với từng thân thể được đánh thức, từng câu nói, từng trải nghiệm cùng họ lướt qua trong tâm trí bạn."
  },
  AvgDialog_68329_Content_55 = {
    Text = "Bạn cảm nhận lực lượng đang tuôn chảy từ những liên kết đó. Đó là sương của Lentiennam, tuyết của Rai, biển của Brillperth và cát của Lemvahi."
  },
  AvgDialog_68329_Content_56 = {
    Text = "Đó là cuộc gặp gỡ của các bạn, là sự chung sống ngày qua ngày ở Misaque. Đó là sức sống của họ, là gông cùm không thể phá vỡ. Đó là niềm ám ảnh chung của các bạn."
  },
  AvgDialog_68329_Content_57 = {
    Text = "Những điều tốt đẹp này, chắc chắn sẽ không bị phá hủy"
  },
  AvgDialog_68329_Content_58 = {
    Text = "Bạn biết, bạn muốn bảo vệ điều gì. \nBạn biết, bạn sẽ bảo vệ những điều này."
  },
  AvgDialog_68329_Content_59 = {
    Text = "Bạn mỉm cười, giơ chìa khóa bạc trong tay lên trước mặt sáng tạo. \nNhư một con đom đóm kiêu hãnh đứng trước mặt trời."
  },
  AvgDialog_68329_Content_6 = {
    Text = "Sức mạnh tinh thần đã cạn kiệt, rỗng rỗng đã nghiêm trọng ăn mòn thân thể và tâm trí của bạn. Bạn không hề quan tâm."
  },
  AvgDialog_68329_Content_60 = {
    Text = "Nguyện chìa khóa bạc, dẫn lối phía trước!!"
  },
  AvgDialog_68329_Content_64 = {
    Text = "Không biết đã bao lâu. Ánh sáng bạc chiếu sáng cả Vương quốc Leo từ từ tắt dần."
  },
  AvgDialog_68329_Content_66 = {
    Text = "Người giữ bí mật?!!……"
  },
  AvgDialog_68329_Content_67 = {
    Text = "Cô ấy đến trước cửa. Ở đây đã lâu không còn bóng dáng của người đó."
  },
  AvgDialog_68329_Content_68 = {
    Text = "Cô ấy ngẩng đầu lên, nhìn thấy một cánh cửa đóng chặt, và trước cánh cửa to lớn đó, chìa khóa bạc lơ lửng yên lặng."
  },
  AvgDialog_68329_Content_69 = {
    Text = "Số hiệu, K-0617…đây…đây là…"
  },
  AvgDialog_68329_Content_7 = {
    Text = "Bạn chỉ nhớ chiến đấu. Máy móc, tê liệt, không mang bất kỳ cảm xúc nào."
  },
  AvgDialog_68329_Content_70 = {
    Text = "Tôi thay mặt hiệu trưởng thứ sáu của Misaque, <Blue:Oliver Elsey>, trao cho bạn chiếc chìa khóa bạc này, mang số hiệu K-0617."
  },
  AvgDialog_68329_Content_71 = {
    Text = "Từ nay trở đi, bạn sẽ mang danh hiệu Người Giữ Gìn, cùng với vạn nghìn học sinh và giáo viên của Misaque."
  },
  AvgDialog_68329_Content_72 = {
    Text = "Ramona bước lên, cẩn thận nâng niu chìa khóa bạc."
  },
  AvgDialog_68329_Content_73 = {
    Text = "Tại sao……"
  },
  AvgDialog_68329_Content_74 = {Text = "Ramona..."},
  AvgDialog_68329_Content_75 = {
    Text = "Luật lệ của Người Giữ Gìn... điều đầu tiên.."
  },
  AvgDialog_68329_Content_76 = {
    Text = "Chìa khóa bạc… là biểu tượng của Người Giữ Gìn… không được để mất, không được vứt bỏ…"
  },
  AvgDialog_68329_Content_77 = {
    Text = "Tôi đã dạy {Male=anh ấy,Female=cô ấy}…… tại sao…… tại sao {Male=anh ấy,Female=cô ấy} vẫn không nhớ?"
  },
  AvgDialog_68329_Content_78 = {
    Text = "Ánh mắt của Toghwa đã bị cách ly sau cánh cửa. Ngài đã lại chìm vào giấc ngủ."
  },
  AvgDialog_68329_Content_79 = {
    Text = "Người giữ bí mật và Người ấy cùng nhau chìm vào hư vô vô thức, thay mặt chúng ta, thay mặt thế giới này, canh giữ cánh cửa phong ấn Tô Hư Ba Bô."
  },
  AvgDialog_68329_Content_8 = {
    Text = "Bạn chỉ nhớ, bạn đã nói, sẽ bảo vệ những người phía sau."
  },
  AvgDialog_68329_Content_80 = {
    Text = "%hisorher% ý thức và sức sống, đều đã mất rồi……\n{Male=anh ấy,Female=cô ấy} đã chết, Ramona."
  },
  AvgDialog_68329_Content_81 = {
    Text = "Chết? {Male=anh ấy,Female=cô ấy} sao có thể chết… {Male=anh ấy,Female=cô ấy} sao có thể bỏ lại nơi này?"
  },
  AvgDialog_68329_Content_82 = {
    Text = "Nhiều người như vậy……nhiều việc như vậy……{Male=anh ấy,Female=cô ấy} làm sao nỡ lòng sẵn sàng?"
  },
  AvgDialog_68329_Content_83 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} làm sao sẵn sàng…"
  },
  AvgDialog_68329_Content_84 = {
    Text = "Giọt nước mắt làm ướt cả găng tay lẫn chìa khóa bạc."
  },
  AvgDialog_68329_Content_85 = {
    Text = "Nước mắt rơi xuống hồ đen, tạo nên một vòng gợn sóng trong suốt."
  },
  AvgDialog_68329_Content_86 = {
    Text = "Trên mặt nước gợn sóng, sau cánh cửa, một hình bóng hư ảo đang say giấc trong sự bao bọc của đôi cánh."
  },
  AvgDialog_68329_Content_87 = {
    Text = "%hisorher% mặt mang nụ cười tinh khiết, giống như một đứa trẻ sinh ra trong đêm tối, lần đầu tiên trông thấy bình minh."
  },
  AvgDialog_68330_Content_1 = {
    Text = "Hì hì……con mắt to đã nhắm lại!"
  },
  AvgDialog_68330_Content_10 = {
    Text = "Tôi tin rằng, nó sẽ vượt qua cơn bão này, tiếp tục hành trình an toàn, mãi mãi…"
  },
  AvgDialog_68330_Content_11 = {
    Text = "Tôi không nhớ được nhiều điều, Người Giữ Gìn. Nhưng những trải nghiệm ở Misaque, những cuộc phiêu lưu cùng bạn, tôi đều chưa quên."
  },
  AvgDialog_68330_Content_12 = {
    Text = "Cái gì đèn biển và tàu thuyền, tôi không hiểu. Tôi chỉ biết, đồ đạc hỏng thì nên sửa, có thứ mình thích thì nên bảo vệ."
  },
  AvgDialog_68330_Content_13 = {
    Text = "Những ký ức ít ỏi……cũng như bạn, tôi không muốn quên chúng."
  },
  AvgDialog_68330_Content_14 = {
    Text = "Tôi muốn cùng bạn khắc ghi quá khứ, tôi muốn cùng bạn trải qua những cuộc phiêu lưu mới."
  },
  AvgDialog_68330_Content_15 = {
    Text = "Đây… chính là niềm tin của tôi!"
  },
  AvgDialog_68330_Content_16 = {
    Text = "Thật là một bức tranh sinh động và phấn khích."
  },
  AvgDialog_68330_Content_17 = {
    Text = "Chiến đấu, niềm tin gì đó, tôi đều không quá hứng thú. Tuy nhiên, thân thể yếu ớt đối mặt với thần minh tối cao, giơ cao lưỡi dao tàn khuyết trong tay…"
  },
  AvgDialog_68330_Content_18 = {
    Text = "Tôi đã nhìn thấy vẻ đẹp tinh khiết nhất trong cảnh này —— những hình thể vô úy, những đường nét kiên định, khiến người ta say đắm."
  },
  AvgDialog_68330_Content_19 = {
    Text = "Tiếp tục chiến đấu, Người Giữ Gìn. Đi bảo vệ niềm tin của bạn và duy trì đức tin của mình, đi bảo vệ những gì bạn trân trọng."
  },
  AvgDialog_68330_Content_2 = {
    Text = "Nghe này, Người Giữ Gìn! Những con sứa ở Ô Ryta đang bắt đầu hào hứng rồi!"
  },
  AvgDialog_68330_Content_20 = {
    Text = "Tôi sẽ cùng với bạn, trở thành một phần của điêu khắc vĩ đại này."
  },
  AvgDialog_68330_Content_3 = {
    Text = "Họ nói rằng, họ sẽ theo Người Giữ Gìn và Ô Ryta để bảo vệ các bạn đồng hành của chúng ta!"
  },
  AvgDialog_68330_Content_4 = {
    Text = "Trong con ngươi đó, dòng chảy của niềm tin xấu xa —— đó là sự hủy diệt hoàn toàn, là sự phỉ báng đối với mọi điều tốt đẹp."
  },
  AvgDialog_68330_Content_5 = {
    Text = "Và thế giới này của vương quốc vĩnh hằng đang thắp sáng ngọn đèn hy vọng dưới sự bảo hộ của bạn."
  },
  AvgDialog_68330_Content_6 = {
    Text = "Người giữ bí mật, đối với những người lạc lối trong thế giới này, bạn chính là ngọn hải đăng duy nhất."
  },
  AvgDialog_68330_Content_7 = {
    Text = "Ngọn hải đăng của chúng ta, sẽ mãi sáng."
  },
  AvgDialog_68330_Content_8 = {
    Text = "Những con ngươi này là vùng biển nguy hiểm không có điểm cuối. Thế giới của chúng ta đang chao đảo trong cơn bão, run rẩy từng hồi."
  },
  AvgDialog_68330_Content_9 = {
    Text = "Người giữ bí mật, tôi đã không thể bảo vệ con tàu thuộc về mình... nhưng lần này, tôi sẽ cùng bạn bảo vệ con tàu \"tàu\"."
  },
  AvgDialog_68331_Content_1 = {
    Text = "Kiến nhỏ"
  },
  AvgDialog_68331_Content_10 = {
    Text = "Bạn cầm chìa khóa bạc, bước về phía trước. Bạn biết, cuộc chiến đấu của bạn chưa kết thúc. \nCuộc đối đầu cuối cùng, mới chỉ bắt đầu."
  },
  AvgDialog_68331_Content_11 = {
    Text = "Rầm!!——"
