  AvgDialog_71792_Content_18 = {
    Text = "Tín niệm của chúng tôi ở cùng Chúa, cho đến khi các vì sao lụi tàn, cho đến tận cùng thời gian…"
  },
  AvgDialog_71792_Content_19 = {
    Text = "Lắng nghe chúa.quy y chúa……"
  },
  AvgDialog_71792_Content_2 = {Text = "Xoà——"},
  AvgDialog_71792_Content_20 = {
    Text = "Giọng nói của tất cả mọi người đồng thanh vang vọng, trong vô số lời cầu nguyện, cả mặt đất cũng rung động."
  },
  AvgDialog_71792_Content_21 = {
    Text = "Lễ tế đi dọc theo vòng tròn được tạo thành bởi các ngọn đuốc, cầm quyền trượng trong tay vẽ nên những hoạ tiết và ký hiệu phức tạp. Khi từng ký hiệu phát sáng rực rỡ, bạn cảm thấy cơ thể kim loại này từ từ tỉnh dậy."
  },
  AvgDialog_71792_Content_22 = {
    Text = "Linh hồn bạn như được làm nóng và nở ra, từ từ bay lên, nổi lên, tầm nhìn vươn tới tầm vóc khổng lồ, giống như chủ nhân của hành tinh này đang ngắm nhìn mặt đất và đại dương."
  },
  AvgDialog_71792_Content_23 = {
    Text = "<Gray:Đây chính là, góc nhìn của Thần Linh……>"
  },
  AvgDialog_71792_Content_24 = {
    Text = "Tất cả những người trên mặt đất chẳng qua chỉ là những con kiến tầm thường như hạt mè, tiếng động vừa rồi cũng chỉ là tiếng ồn nhỏ nhặt, tất cả thật nhàm chán."
  },
  AvgDialog_71792_Content_26 = {
    Text = "(<Gray:Ồ, đó là gì?>)"
  },
  AvgDialog_71792_Content_27 = {
    Text = "Sự chú ý của bạn bỗng nhiên bị thu hút bởi thứ gì đó đang dần đến gần, bạn quay đầu lại nhìn về mặt biển màu xám xanh."
  },
  AvgDialog_71792_Content_28 = {
    Text = "Đồng thời, Tulô vốn đang cúi mắt cũng bỗng nhiên ngẩng đầu lên, cùng bạn nhìn về phía biển cả."
  },
  AvgDialog_71792_Content_29 = {
    Text = "Một tia sét đánh xuống, mây đen, gió mạnh, mưa lớn như bị gọi đến một cách đột ngột, sắc trời thay đổi trong chớp mắt."
  },
  AvgDialog_71792_Content_3 = {
    Text = "Bạn đứng trên bệ tế cao vút bên bờ biển."
  },
  AvgDialog_71792_Content_30 = {
    Text = "Ngọn đuốc trên bàn thờ bị cơn mưa lớn bất ngờ dập tắt, tiếng cầu nguyện trang nghiêm của hàng triệu người dần yếu đi như thể bị một sự kinh ngạc nuốt chửng, những tiếng thì thầm lộn xộn từ từ vang lên."
  },
  AvgDialog_71792_Content_31 = {
    Text = "Im lặng! Lễ thức bình thường, cầu nguyện tiếp tục!"
  },
  AvgDialog_71792_Content_32 = {
    Text = "Áo lễ trang nghiêm của chủ tế bị gió mạnh quất vào vù vù, biểu cảm của ông vẫn vững vàng không lay chuyển, nhưng đôi mắt đầy nếp nhăn cũng không khỏi lộ ra một tia ưu tư."
  },
  AvgDialog_71792_Content_33 = {
    Text = "Chưa đợi vị chủ tế tiếp tục chỉnh đốn hiện trường, tiếng cầu nguyện hỗn loạn nhanh chóng tan biến hoàn toàn, trong đám đông vang lên những tiếng thét kinh hoàng."
  },
  AvgDialog_71792_Content_34 = {
    Text = "Bóng tối như núi bỗng nhiên xuất hiện từ cuối đường chân trời và đang trở nên to lớn hơn với tốc độ có thể nhìn thấy bằng mắt thường, giống như muốn che khuất hoàn toàn ánh sáng cuối cùng của mặt trời."
  },
  AvgDialog_71792_Content_35 = {
    Text = "Quái vật…… có quái vật đến!"
  },
  AvgDialog_71792_Content_36 = {
    Text = "Dường như tiếng ong ong và gào thét từ thời cổ đại đã nghiền nát linh hồn yếu đuối của con người, làm dâng lên những con sóng khổng lồ nuốt chửng đất liền."
  },
  AvgDialog_71792_Content_37 = {
    Text = "Đó là sự tồn tại không thể đối kháng, nếu như quái vật như vậy có tên, đó chỉ có thể là —— Thiên Tai."
  },
  AvgDialog_71792_Content_38 = {
    Text = "Gần như trong gang tấc, bờ biển bị dòng thủy triều đột ngột dâng cao cắn xé mất một mảng lớn đất liền, đê điều của con người sụp đổ như giấy."
  },
  AvgDialog_71792_Content_39 = {
    Text = "Chuẩn bị rút lui, đến địa hình cao!"
  },
  AvgDialog_71792_Content_4 = {
    Text = "Sóng biển dâng lên bọt trắng không ngừng vỡ trên những tảng đá nhấp nhô, đám mây dày đặc, xám xịt kết nối với dòng sóng xám ở chân trời, bao phủ biên giới của đất nước này."
  },
  AvgDialog_71792_Content_40 = {
    Text = "Giọng gầm già nua nhưng uy nghiêm vang lên lần nữa, chủ tế và vệ binh nhanh chóng xua đuổi đám đông ngây dại."
  },
  AvgDialog_71792_Content_41 = {
    Text = "Dân chúng hoảng loạn chạy như đàn cừu mất phương hướng, nhưng trong hỗn loạn lại chen chúc vào nhau, giẫm đạp lên nhau tiến tới cái chết nhanh hơn."
  },
  AvgDialog_71792_Content_42 = {
    Text = "Đi phân ra vài tuyến đường sơ tán, gửi người đến phía trước để hướng dẫn dân chúng!"
  },
  AvgDialog_71792_Content_43 = {
    Text = "Lễ tân hầu như gầm lên khi ra lệnh cho vệ binh, cố gắng níu lại chiếc xe ngựa đang điên cuồng lao xuống hố sâu."
  },
  AvgDialog_71792_Content_44 = {
    Text = "Bàn thờ có địa thế cao, các người tạm thời không có nguy cơ bị nhấn chìm, nhưng trước một tồn tại khổng lồ như vậy, sự hủy diệt chỉ đến muộn một chút mà thôi."
  },
  AvgDialog_71792_Content_45 = {
    Text = "Dù người dân không ngừng chạy trốn, đâu mới là nơi an toàn thực sự?"
  },
  AvgDialog_71792_Content_46 = {
    Text = "Lắng nghe chúa.quy y chúa……"
  },
  AvgDialog_71792_Content_47 = {
    Text = "Trẻ em đã bắt đầu cầu nguyện một cách chân thành ngay khi thảm họa vừa xảy ra."
  },
  AvgDialog_71792_Content_48 = {
    Text = "Mọi người đều nhíu chặt mày, dồn hết sức lực để vươn những xúc tu nhỏ bé của tinh thần về phía vương miện, như thể những bàn tay tuyệt vọng đang cố gắng cầu cứu, khao khát sự thương xót và cứu rỗi từ thần minh."
  },
  AvgDialog_71792_Content_49 = {
    Text = "Nhưng mà đó thực sự là.."
  },
  AvgDialog_71792_Content_5 = {
    Text = "Tiếng người ầm ĩ hơn cả tiếng sóng biển truyền đến từ phía sau bạn, đó là một biển người bao la, được tạo thành bởi vô số dân chúng."
  },
  AvgDialog_71792_Content_50 = {
    Text = "(<Gray:... quá yếu ớt.>)"
  },
  AvgDialog_71792_Content_51 = {
    Text = "Trong mắt bạn, những linh hồn yếu đuối dù cố gắng hết sức cũng chỉ tỏa ra ánh sáng mờ nhạt như đom đóm, dù bạn có gắng sức đáp lại thế nào, thân xác mang vương miện này vẫn cứ thờ ơ không lay động."
  },
  AvgDialog_71792_Content_52 = {
    Text = "Sao có thể, chủ đã bỏ rơi chúng ta rồi, tại sao vương miện không đáp lại…"
  },
  AvgDialog_71792_Content_53 = {
    Text = "Không phải, chắc chắn là chúng ta chưa đủ thành tâm, chắc chắn là sức mạnh tinh thần của chúng ta chưa đủ ổn định, hãy cố gắng thêm một chút!"
  },
  AvgDialog_71792_Content_54 = {
    Text = "Không còn thời gian nữa."
  },
  AvgDialog_71792_Content_55 = {
    Text = "Tất cả mọi người nhìn về phía đứa trẻ đưa ra quyết định, cậu bé thường là người lý trí nhất trong nhóm im lặng nhìn các bạn đồng hành một cái, sau đó bước lên bậc thang đầu tiên."
  },
  AvgDialog_71792_Content_56 = {
    Text = "Chúng ta không còn thời gian để chờ đợi nữa, có thể Chủ vẫn đang say ngủ, có thể Người lúc này chưa nhìn về phía này, hoặc cũng có thể chỉ là tiếng nói của chúng ta quá đỗi nhỏ nhoi."
  },
  AvgDialog_71792_Content_57 = {
    Text = "Chúng ta phải chủ động đi tìm Ngài."
  },
  AvgDialog_71792_Content_58 = {
    Text = "Vương miện trên đài cao lấp lánh với ánh sáng lạnh lẽo, như một con mắt thờ ơ.\nThần chưa từng hứa hẹn, thần cũng chưa từng phủ nhận."
  },
  AvgDialog_71792_Content_59 = {
    Text = "Khi cậu bé tiến lên, ngày càng nhiều đứa trẻ im lặng theo sau bước chân của cậu, tiếng bước chân nhẹ như lông vũ của một nhóm trẻ em vang lên trên những bậc đá, bị nhấn chìm hoàn toàn bởi tiếng khóc than của đám đông và tiếng gầm giận dữ của sóng biển."
  },
  AvgDialog_71792_Content_6 = {
    Text = "Ánh mắt theo dõi tuần tra cảm ứng quen thuộc, bạn dễ dàng phát hiện tulô đang đứng cùng một nhóm trẻ em dưới bệ tế."
  },
  AvgDialog_71792_Content_60 = {
    Text = "Ở phía sau cùng của những đứa trẻ, biểu cảm của tulô bỗng trở nên ngẩn ngơ, trong mắt anh phản chiếu bóng hình của vương miện, con ngươi giãn ra một cách mất tập trung."
  },
  AvgDialog_71792_Content_61 = {
    Text = "Rất nhanh, hình bóng màu vàng kia biến thành một vòng xoáy hỗn loạn, tulô cứng đờ rơi vào một cơn ác mộng, trở thành người quan sát đứng ngoài."
  },
  AvgDialog_71792_Content_62 = {
    Text = "Tulô, tulô! Sao bạn vậy… Bạn không khỏe sao?"
  },
  AvgDialog_71792_Content_63 = {
    Text = "Sự quan tâm đầy lo lắng của người bạn thân không thức tỉnh được linh hồn của anh ta, anh ta đứng im như một pho tượng đá bị phong hóa."
  },
  AvgDialog_71792_Content_64 = {
    Text = "Cậu bé đầu tiên bước lên bục cao đã đứng bên cạnh bạn, cậu quay đầu nhìn lại từng người bạn đồng hành với vẻ mặt nghiêm trọng, rồi gật đầu trang trọng."
  },
  AvgDialog_71792_Content_65 = {
    Text = "Khi đôi tay cậu bé đưa ra một cách kiên định hướng về chiếc vương miện, đôi mắt của tulô chuyển động nhẹ nhàng."
  },
  AvgDialog_71792_Content_67 = {
    Text = "Dường như đang vật lộn trong cơn ác mộng, đôi môi của anh ta run rẩy và lẩm bẩm một cách khó hiểu, thốt ra một tiếng lẩm bẩm từ họng."
  },
  AvgDialog_71792_Content_68 = {
    Text = "<Small:không...>"
  },
  AvgDialog_71792_Content_69 = {
    Text = "Gì? Bạn nói gì đó à?"
  },
  AvgDialog_71792_Content_7 = {
    Text = "(<Gray:Đây là... lễ chọn trữ quân mà họ nói?>)"
  },
  AvgDialog_71792_Content_70 = {
    Text = "Cậu bé trên bục cao đã nhẹ nhàng và đầy tôn kính đội vương miện lên đầu mình."
  },
  AvgDialog_71792_Content_71 = {
    Text = "<Big:Không!!!>"
  },
  AvgDialog_71792_Content_72 = {
    Text = "Anh ta cuối cùng đã tìm lại được dây thanh quản, nhưng mọi thứ đã quá muộn."
  },
  AvgDialog_71792_Content_73 = {
    Text = "Vào khoảnh khắc vương miện được đặt chính xác trên kiệu mới, khuôn mặt non nớt nhưng nghiêm túc của cậu bé hiện lên một vẻ mặt gần như bối rối và mất phương hướng."
  },
  AvgDialog_71792_Content_74 = {
    Text = "Tất cả các đứa trẻ nín thở, mong chờ ông mang đến lời sấm cứu thế."
  },
  AvgDialog_71792_Content_75 = {
    Text = "Tuy nhiên, vào khoảnh khắc tiếp theo, từ miệng cậu bé hơi hé mở đột nhiên bắn ra chỉ vài cái râu chạm xanh đậm khổng lồ, không ngừng vặn vẹo. Máu và thịt nóng hổi như một bó pháo hoa nổ tung, và bắn tung tóe lên mặt mọi người."
  },
  AvgDialog_71792_Content_76 = {Text = "Keng——"},
  AvgDialog_71792_Content_77 = {
    Text = "Vương miện lăn ra từ thân thể vừa sụp đổ mạnh mẽ, rơi xuống chân các đứa trẻ."
  },
  AvgDialog_71792_Content_78 = {
    Text = "<Red:như một lời nguyền rủa bất tường.>"
  },
  AvgDialog_71792_Content_8 = {
    Text = "Chủ tế trong bộ áo choàng lộng lẫy, tay cầm quyền trượng, bước chậm rãi về phía trung tâm bàn tế."
  },
  AvgDialog_71792_Content_9 = {
    Text = "Dưới khán đài, vô số khuôn mặt đỏ bừng vì kích động dần dần yên lặng lại, chỉ còn lại những đôi mắt lấp lánh ánh sáng."
  },
  AvgDialog_71793_Content_1 = {
    Text = "Đăng quang"
  },
  AvgDialog_71793_Content_10 = {
    Text = "Nỗi sợ hãi tột độ bao trùm quanh vương miện."
  },
  AvgDialog_71793_Content_100 = {
    Text = "Tôi đã quên, bạn đã là vua của tương lai rồi…"
  },
  AvgDialog_71793_Content_101 = {
    Text = "Tay của tulô bỗng nhiên đặt lên vai Noah, vẻ mặt phức tạp thiếu vui mừng cuối cùng cũng tan biến, để lộ một nụ cười nhạt."
  },
  AvgDialog_71793_Content_102 = {
    Text = "Vua lẽ nào không thể có bạn bè?"
  },
  AvgDialog_71793_Content_103 = {
    Text = "Noah ngây người nhìn nụ cười đó, rồi cũng bật cười, dùng tay áo lau nước mắt trên mặt một cách tùy tiện."
  },
  AvgDialog_71793_Content_104 = {
    Text = "Đúng vậy, như thế vua quá khổ sở, tôi sẽ không để bạn phải chịu đựng như thế."
