  AvgDialog_71793_Content_105 = {
    Text = "Như vô số ngày hôm qua, cánh tay dài của Noah khoác lên vai Tulô, vỗ ngực với lòng nhiệt huyết."
  },
  AvgDialog_71793_Content_106 = {
    Text = "Tôi sẽ luôn là bạn của vua, đến lúc đó có thể sẽ có vô số bánh Amaranth để ăn!"
  },
  AvgDialog_71793_Content_107 = {
    Text = "Đến cuối cùng cũng chỉ còn lại ước nguyện này, thật là kém cỏi……"
  },
  AvgDialog_71793_Content_108 = {
    Text = "Tulô lại lăn mắt một cách khinh bỉ, những đứa trẻ sống sót tụ tập xung quanh hai người, lần lượt ôm chặt lấy nhau như những đứa trẻ mồ côi bám víu vào nhau."
  },
  AvgDialog_71793_Content_109 = {
    Text = "Bạn và tulô nhìn những khuôn mặt khóc lóc, xúc động, vui mừng, ngay cả vị chủ tế cũng hiện lên nụ cười vừa thán phục vừa cảm kích. Dấu hiệu thần thánh xuất hiện, tai họa lui đi, hoàng tử ra đời, kết cục dường như quá hoàn mỹ."
  },
  AvgDialog_71793_Content_11 = {
    Text = "Những xúc tu điên cuồng đã mất đi vật chủ, dần dần hóa thành một vũng chất keo màu xanh lục, bị cơn mưa càng lúc càng mạnh cuốn trôi và lan rộng trên bàn thờ."
  },
  AvgDialog_71793_Content_110 = {
    Text = "Tuy nhiên, vào khoảnh khắc thần minh đến, bạn đã nghe thấy lời sấm truyền định mệnh đó."
  },
  AvgDialog_71793_Content_111 = {
    Text = "Đại diện của ta, ngươi sẽ mãi ngồi trên ngai vàng, gắn liền với vận mệnh của đất nước này."
  },
  AvgDialog_71793_Content_112 = {
    Text = "Lực lượng và vinh quang không bao giờ cạn kiệt, muôn dân sẽ quy phục dưới chân ngài."
  },
  AvgDialog_71793_Content_113 = {
    Text = "Lời tâm sự của tulô lúc này truyền từ vương miện vào tâm trí bạn, đan xen với tâm trạng của bạn."
  },
  AvgDialog_71793_Content_114 = {
    Text = "(<Gray:Vậy, giá của nó là gì?>)"
  },
  AvgDialog_71793_Content_12 = {Text = "Tách."},
  AvgDialog_71793_Content_13 = {
    Text = "Một chiếc giày nhỏ bước một bước về phía trước, vượt qua những phân mảnh vẫn còn ấm, một bàn tay từ trong chất nhầy bẩn nhặt lại vương miện."
  },
  AvgDialog_71793_Content_14 = {Text = "Xin gia…"},
  AvgDialog_71793_Content_15 = {
    Text = "Cô gái bị gọi tên khẽ dừng lại, quay đầu về phía bạn bè và nở một nụ cười nghèn nghẹn."
  },
  AvgDialog_71793_Content_16 = {
    Text = "Những ngày tháng bên mọi người, tôi luôn rất vui vẻ. Hãy cười đi, Amos, bạn cười trông thật tuyệt."
  },
  AvgDialog_71793_Content_17 = {Text = "Keng——"},
  AvgDialog_71793_Content_18 = {
    Text = "Số phận không dễ dàng ban ơn, tuy nhiên lần này, vương miện nhanh chóng được đôi tay tiếp theo nhặt lên."
  },
  AvgDialog_71793_Content_19 = {
    Text = "Bóng tối xa xôi, những đám mây đen, sóng thần vẫn đang rít gào, tối tăm vô tận bao trùm cả đất nước."
  },
  AvgDialog_71793_Content_2 = {
    Text = "Trở thành đại diện của Chúa, phần nhiều là một số phận đã định."
  },
  AvgDialog_71793_Content_20 = {
    Text = "Giữa trời đất u tối, chỉ có trên bàn thờ nhỏ này liên tục phát ra những màu sắc rực rỡ."
  },
  AvgDialog_71793_Content_21 = {
    Text = "Sức sống không ngừng ngã xuống và được những người sau tiếp tục, trước mắt bạn chỉ còn lại màu đỏ và xanh đặc quánh."
  },
  AvgDialog_71793_Content_22 = {
    Text = "(<Shake:không, không đúng, các người không chịu đựng được đâu, mau dừng lại!>)"
  },
  AvgDialog_71793_Content_23 = {
    Text = "Lời kêu gọi của bạn giống như một linh hồn bị cách ly khỏi thế giới, chẳng một ai nghe thấu."
  },
  AvgDialog_71793_Content_24 = {
    Text = "Những đứa trẻ nhỏ lần lượt tiến lên, vào thời khắc này, mỗi người trong số họ chưa được chọn đều gánh vác trọng trách dưới vương miện."
  },
  AvgDialog_71793_Content_25 = {
    Text = "Họ là vị vua mới chưa định, phải bảo vệ đất nước này đến khi số phận gõ tiếng búa cuối."
  },
  AvgDialog_71793_Content_26 = {
    Text = "Samuêl, Grêtchen, Amôt…"
  },
  AvgDialog_71793_Content_27 = {
    Text = "Noah, người đứng sau tulô ở bậc thang, mở to đôi mắt trong sự kinh ngạc, đau đớn và sợ hãi… Trong vô số những màu sắc u ám, một điểm sáng dần dần mở rộng, từ từ chiếm lấy tâm trí của anh."
  },
  AvgDialog_71793_Content_28 = {
    Text = "Noah quay lại nhìn Tulô vẫn đang trong trạng thái mơ màng, nhẹ nhàng vỗ vai anh ta, sau đó quay người đi về phía các đồng đội."
  },
  AvgDialog_71793_Content_3 = {
    Text = "Người được định không thể đeo vương miện nếu cố gắng tiếp nhận thần dụ, chỉ có thể vì không thể chịu đựng lực lượng của thần mà đi đến cái chết."
  },
  AvgDialog_71793_Content_30 = {
    Text = "Tài năng, thường giống như một lời nguyền không thể chọn lựa."
  },
  AvgDialog_71793_Content_31 = {
    Text = "Một lần lại một lần trong thực tế tái hiện giấc mơ, lời tiên tri không thể ngăn cản hay thay đổi, ảo ảnh khó diễn tả, lời thì thầm méo mó và điên rồ…"
  },
  AvgDialog_71793_Content_32 = {
    Text = "Anh ta từ khi sinh ra đã phải chịu đựng những điều này, ân huệ của thần linh cũng chưa từng hỏi ý kiến của anh."
  },
  AvgDialog_71793_Content_33 = {
    Text = "Lực lượng của nghi lễ thức tỉnh đang cuồn cuộn và xao động trong thân thể bạn, sứ mệnh đã được thiết lập đột nhiên thức tỉnh, hơi thở thuộc về thần lan tỏa ra ngoài."
  },
  AvgDialog_71793_Content_34 = {
    Text = "Người phàm ngu muội giống như động vật không biết gì, chỉ có linh hồn rực rỡ như vì sao luôn thu hút bạn. Giống như định mệnh gắn kết các bạn."
  },
  AvgDialog_71793_Content_35 = {
    Text = "<Gray:trả lời ta, thần vương đã định…>"
  },
  AvgDialog_71793_Content_36 = {
    Text = "Một khoảnh khắc, tulô lại một lần nữa bị cuốn vào cơn ác mộng điên rồ, bước vào chiều kích tương đồng với bạn."
  },
  AvgDialog_71793_Content_37 = {
    Text = "Ông nhìn thấy thành phố rực rỡ bị phá hủy như những khối xây dựng yếu đuối, lũ lụt lan rộng, tất cả sinh linh mở to mắt không thể nhắm lại, bị cuốn vào xoáy nước biển sâu."
  },
  AvgDialog_71793_Content_38 = {Text = "Không.."},
  AvgDialog_71793_Content_39 = {
    Text = "Anh ta nhìn thấy những đứa trẻ đã sống cùng anh ta ngày đêm, một tiếp một biến thành quái vật và tan chảy thành nước mủ. Linh hồn của chúng bị xé tan trong cơn ác mộng của thần linh."
  },
  AvgDialog_71793_Content_4 = {
    Text = "Vì vậy, điều cuối cùng các ngươi cần làm là yên lặng chờ đợi sự lựa chọn của thần. Đừng quá buồn, cũng đừng gượng ép."
  },
  AvgDialog_71793_Content_40 = {
    Text = "Ngày hôm qua, Noah còn đang đùa giỡn với anh, giờ đây đôi mắt chảy máu đỏ au, tiếng kêu khản đặc gọi tên anh vỡ vụn trong không khí."
  },
  AvgDialog_71793_Content_41 = {
    Text = "Đừng mà!!!"
  },
  AvgDialog_71793_Content_42 = {
    Text = "Tại sao phải lao vào cái chết… Tại sao phải đấu tranh một cách vô vọng như vậy…"
  },
  AvgDialog_71793_Content_43 = {
    Text = "Chiếc vương miện mà anh ta luôn né tránh ánh nhìn vẫn đứng cao ngạo trên đỉnh, vô cảm quan sát tất cả, như thể đang mỉa mai sự trốn tránh của anh ta bấy lâu nay."
  },
  AvgDialog_71793_Content_44 = {
    Text = "Mặt Tulô bỗng chốc đầy sự phẫn nộ không thể kiềm chế, giống như một con thú dữ bị dồn vào đường cùng đang nhìn chằm chằm vào bạn."
  },
  AvgDialog_71793_Content_45 = {
    Text = "Luôn luôn, mãi mãi như thế này…… Có ích gì khi để tôi thấy những tương lai hão huyền này?"
  },
  AvgDialog_71793_Content_46 = {
    Text = "Khi thấy tôi, chẳng ai cứu nổi, mọi thứ đều bất lực. Cậu có vui không?!"
  },
  AvgDialog_71793_Content_47 = {
    Text = "Chọn đi… Đấng ấy đang chờ đợi bạn…"
  },
  AvgDialog_71793_Content_48 = {
    Text = "Đột nhiên Tulô cảm thấy có người vỗ nhẹ vào mình, anh ta bối rối đưa tay ra, dường như có một góc áo nhẹ nhàng trượt qua đầu ngón tay, các ngón tay của anh ta co lại, nhưng không bắt được gì cả."
  },
  AvgDialog_71793_Content_49 = {
    Text = "Ôi, không thử sao biết? Có cơ hội mà không thử thì sẽ hối hận."
  },
  AvgDialog_71793_Content_50 = {
    Text = "Không phải như vậy, vạn nhất thì sao? Thế hệ phàm nhân vẫn luôn cố gắng, chắc chắn sẽ có điều gì đó thay đổi được. Nếu không, tại sao chúng ta lại chọn Thần Vương chứ?"
  },
  AvgDialog_71793_Content_51 = {
    Text = "Mặt Tulô bỗng nhiên xuất hiện vẻ giãy dụa như thể vừa bừng tỉnh trong hoảng loạn, mang theo một quyết tâm mãnh liệt và nặng nề."
  },
  AvgDialog_71793_Content_52 = {
    Text = "Ai nấy đều giống như những anh hùng.."
  },
  AvgDialog_71793_Content_53 = {
    Text = "Anh ta nhìn xuyên qua ảo ảnh vương miện mà đồng đội đang cố giành lấy, ngẩng đầu lên hướng về vương miện lấp lánh bất tận trên cao."
  },
  AvgDialog_71793_Content_54 = {
    Text = "Hãy nói cho tôi biết, làm thế nào để ngăn chặn tất cả điều này!"
  },
  AvgDialog_71793_Content_55 = {
    Text = "Đeo @2……"
  },
  AvgDialog_71793_Content_56 = {
    Text = "Gần như hét lên, tulô bước lên một bước, sau đó bắt đầu chạy như điên."
  },
  AvgDialog_71793_Content_57 = {
    Text = "Hãy nói cho tôi biết, rốt cuộc phải làm sao để Ngài hài lòng?!"
  },
  AvgDialog_71793_Content_58 = {
    Text = "Thức tỉnh@3……"
  },
  AvgDialog_71793_Content_59 = {
    Text = "Một bước, hai bước, anh ta đi qua giấc mơ đầy chết chóc, lảo đảo chạy lên những bậc đá."
  },
  AvgDialog_71793_Content_6 = {
    Text = "Mỗi đứa trẻ khi nhận lấy sứ mệnh gánh vác hy vọng của đất nước, bước lên con đường trở thành vua, đều đã biết rõ kết cục có thể là cái chết."
  },
  AvgDialog_71793_Content_60 = {
    Text = "Bước cuối cùng của bậc thang chạm dưới chân, nguồn năng lượng tinh thần mạnh mẽ bỗng chốc phá vỡ giấc mơ được ban tặng ấy, thực tại dần hiện rõ trong đôi mắt anh."
  },
  AvgDialog_71793_Content_61 = {
    Text = "Trong đống tàn tích đầy bi thương, Noah nhặt lên chiếc vương miện từ mặt đất, ánh sáng lạnh giá lấp lánh hướng về phía cậu."
  },
  AvgDialog_71793_Content_62 = {
    Text = "Mắt Noah trong một khoảnh khắc trở nên mờ đục một cách đáng sợ, hai hàng nước mắt máu chảy xuống khuôn mặt anh, mọi thứ hoàn toàn trùng khớp với những hình ảnh trong giấc mơ."
  },
  AvgDialog_71793_Content_63 = {
    Text = "Vào khoảnh khắc tiếp theo, một bàn tay siết chặt đầy quyết tâm chiếc vương miện đầy gai, và từng chút một, kiên định kéo nó ra khỏi tay Noah."
  },
  AvgDialog_71793_Content_64 = {
    Text = "Đồ……lộ?"
  },
  AvgDialog_71793_Content_65 = {
    Text = "Xin lỗi, tôi đến trễ."
  },
  AvgDialog_71793_Content_66 = {
    Text = "Tulô thở hổn hển, lòng bàn tay của anh bị vương miện cắt, những giọt máu đỏ tươi nhỏ xuống viên đá quý ở trung tâm vương miện, tựa như một ánh mắt đẫm lệ."
  },
  AvgDialog_71793_Content_67 = {
    Text = "Hiện tại, sóng thần đã nhấn chìm vùng đất ven biển, chỉ còn lại bệ thờ cao như một hòn đảo nổi trên mặt biển.\nTrong những cơn sóng gần kề, quái vật hủy diệt đã đến."
  },
  AvgDialog_71793_Content_68 = {
    Text = "Lắng nghe chúa.quy y chúa……"
  },
  AvgDialog_71793_Content_69 = {
    Text = "Trong ký ức của bạn, vị vua trẻ luôn điềm tĩnh và không chút xao động, lúc này đây lần đầu tiên nâng vương miện lên. Trước sóng biển cuồn cuộn, anh ta ngẩng đầu lên, tự mình đội lên đầu vương miện."
  },
  AvgDialog_71793_Content_7 = {
    Text = "Khi họ theo chân người tiên phong đầu tiên bước lên cầu thang dẫn đến vương miện, họ đã đưa ra lựa chọn của mình."
  },
  AvgDialog_71793_Content_70 = {
    Text = "Vẫn là tôi… tulô?!"
  },
  AvgDialog_71793_Content_71 = {
    Text = "Noah yếu đuối ngã ngồi xuống đất, anh ta nhìn đờ đẫn lên vương miện đội vững trên đầu tulô, tay muốn ngăn cản dừng lại vô định giữa không trung."
  },
  AvgDialog_71793_Content_72 = {
    Text = "Tulô quay đầu lại, ánh mắt dịu dàng nhìn người bạn vẫn kiên quyết gánh vác nguy hiểm thay mình, rồi nở một nụ cười đầy an ủi."
  },
  AvgDialog_71793_Content_73 = {
    Text = "…… Mong đôi mắt sáng của ngài nhìn thấu tai ương, mong sự khôn ngoan của ngài dẫn dắt dân chúng."
  },
  AvgDialog_71793_Content_74 = {
    Text = "Trong tiếng gầm của quái vật, anh ta bước tới giữa cơn gió gào thét và màn mưa xối xả, đưa tay về phía trước."
  },
  AvgDialog_71793_Content_75 = {
    Text = "Bão táp im lìm, sóng nước không gợn…"
  },
  AvgDialog_71793_Content_76 = {
    Text = "Tóc mai và góc áo của anh ta bị thổi loạn lên, vương miện tẩm máu của anh ta, tỏa ra ánh hào quang ngày càng mạnh trên đỉnh đầu anh ta."
  },
  AvgDialog_71793_Content_77 = {
    Text = "Như thần minh cuối cùng đáp lại, một bóng mờ che phủ bầu trời hiện ra phía sau hắn."
  },
  AvgDialog_71793_Content_78 = {
    Text = "Động đất ngừng, mặt đất bình yên."
  },
  AvgDialog_71793_Content_79 = {
    Text = "Đầu quái vật khổng lồ lao xuống, ép sát về phía con người nhỏ bé dưới chân, nhưng ngay sau đó, nó như bị ánh sáng chói chang đốt cháy và bị hất tung ra, phát ra tiếng kêu thảm thiết."
  },
  AvgDialog_71793_Content_8 = {
    Text = "Tuy nhiên, khi tận mắt chứng kiến người bạn ngày đêm ở bên cạnh phân hủy thành bùn ngay trước mắt, tất cả bọn trẻ đều đứng khựng lại tại chỗ."
  },
  AvgDialog_71793_Content_80 = {
    Text = "Bầu trời có những ngôi sao cực kỳ sáng lóe sáng chói lọi, trong một khoảnh khắc, mây đen tản đi, sóng biển rút lui, gió mưa ngừng lại."
  },
  AvgDialog_71793_Content_81 = {
    Text = "Trong giấc mơ bình yên, thảm họa tan biến thành hư vô, thần dân được bảo vệ dưới sự che chở của ngài…"
  },
  AvgDialog_71793_Content_82 = {
    Text = "Sức mạnh vô biên bùng phát từ thân thể nhỏ bé đó. Đôi còng kinh màu hổ phách toát lên hơi thở của thời gian, ẩn chứa sự thờ ơ kiêu hãnh."
  },
  AvgDialog_71793_Content_83 = {
    Text = "Những xúc tu xanh đậm bò động tụ tập lực lượng hùng hậu của hố sâu, leo ra từ thân tulô, lan rộng tựa như mang ý chí riêng, dường như muốn biến thành ngai vàng bằng đá lam quý giá dưới thân vị vua."
  },
  AvgDialog_71793_Content_84 = {
    Text = "Con quái vật kinh khủng dường như bị một lệnh không thể kháng cự khiến nó phát ra tiếng rên rỉ không cam lòng, lùi một bước trong cuộc đối đầu đó."
  },
  AvgDialog_71793_Content_85 = {
    Text = "Đó là lưng vững chãi tựa dãy núi dần dần chìm vào nước, cuối cùng theo sóng lui chầm chậm trở về biển sâu."
  },
  AvgDialog_71793_Content_86 = {
    Text = "An toàn vô sự."
  },
  AvgDialog_71793_Content_87 = {
    Text = "Ánh sáng trời chiếu qua tầng mây, tái chiếu xuống mặt đất của Lemuria."
  },
  AvgDialog_71793_Content_88 = {
    Text = "Những người bị sóng biển đuổi theo và nuốt chửng dần dần dừng bước, những tòa nhà và đất đai bị ngập lụt tái hiện lại, trên tất cả những khuôn mặt kinh hoàng và bàng hoàng lộ ra sự vui mừng tột độ sau thảm họa."
  },
  AvgDialog_71793_Content_89 = {
    Text = "Chủ! Chủ đã đến cứu chúng ta rồi!"
  },
  AvgDialog_71793_Content_9 = {Text = "Ya——"},
  AvgDialog_71793_Content_90 = {
    Text = "Đó là hoàng tử, các hoàng tử đã thức tỉnh chủ nhân của ta!"
  },
  AvgDialog_71793_Content_91 = {
    Text = "Từ khi nhìn thấy những đứa trẻ bước về phía vương miện, chủ tế đã im lặng đồng ý. Giờ đây, ông cúi sâu trước tulô trên đỉnh bàn thờ — đó là nghi lễ linh mục quỳ gối trước vua."
  },
  AvgDialog_71793_Content_92 = {
    Text = "Sau đó, ông ta quay người run rẩy giơ cao cây trượng và tuyên án bằng giọng nói trang trọng nhất."
  },
  AvgDialog_71793_Content_93 = {
    Text = "Chúa của chúng ta đã cứu rỗi Lemuria, Người đã đưa ra quyết định cuối cùng, hãy cúi đầu trước vị hoàng tử mới —— Điện hạ Tulô!"
  },
  AvgDialog_71793_Content_94 = {
    Text = "Tiếng tán tụng từ đám đông bùng nổ, mọi người cúi mình trước vị vua mới của tương lai, có những người mộ đạo thậm chí quỳ xuống, hôn đất và khóc trong niềm vui sướng tột độ."
  },
  AvgDialog_71793_Content_95 = {
    Text = "Noah, người đang đứng ngẩn ngơ bên cạnh, cuối cùng cũng phản ứng lại, lao đến ôm chầm lấy tulô, suýt chút nữa đã làm tulô ngã xuống đất."
