  AvgDialog_71794_Content_1 = {
    Text = "Tuổi thơ"
  },
  AvgDialog_71794_Content_10 = {
    Text = "Bạn cố gắng mở mắt, trong tầm nhìn bỗng nhiên xuất hiện là hai hàng cột đá đứng sừng sững như răng của quái vật, vòm trần đầy những họa tiết khắc tinh xảo, và những bậc thang đá dài dằng dặc dẫn xuống——đây là một đền thần uy nghi tráng lệ."
  },
  AvgDialog_71794_Content_100 = {
    Text = "Rõ ràng viết chữ chậm nhất, lại còn cố gắng tỏ ra anh hùng, chỉ cần một chút lợi ích đã bị mua chuộc, thật là kém cỏi."
  },
  AvgDialog_71794_Content_101 = {
    Text = "Chuyện của bạn bè, làm sao có thể gọi là mua chuộc được, đó là, đó là…… Tôi hơn cậu vài tuổi, làm anh trai chăm sóc cậu là điều đương nhiên, ôi——"
