  AvgDialog_71794_Content_102 = {
    Text = "Noah hùng dũng đứng thẳng lưng, nhưng không may đã vặn phải cổ đau nhức, khiến anh ta nhăn nhó và rên rỉ."
  },
  AvgDialog_71794_Content_104 = {
