  AvgDialog_71794_Content_106 = {Text = "Ugh…"},
  AvgDialog_71794_Content_107 = {
    Text = "Hãy nói chuyện một chút, nói chuyện một lúc sẽ không còn buồn ngủ, à… Lễ chọn trữ quân sắp đến rồi, cậu nghĩ ai sẽ là người cuối cùng đội vương miện?"
