  AvgDialog_71794_Content_109 = {
    Text = "Bạn có nhiệt huyết để đọc đi đọc lại lời cầu nguyện nhiều lần như vậy, chắc chắn ngay cả những vị thần lạnh lùng nhất cũng không thể không bị bạn lay động."
