  AvgDialog_71794_Content_11 = {
    Text = "Góc nhìn quái dị gần 360 độ khiến các giác quan của bạn tạm thời bị choáng váng, nhưng so với các tình huống khác, đây rõ ràng không phải là vấn đề nghiêm trọng nhất."
  },
  AvgDialog_71794_Content_110 = {
