  },
  AvgDialog_71794_Content_111 = {
    Text = "Noah đầy vẻ trầm ngâm, như thể cũng bị sự nhàm chán nhấn chìm, bắt đầu lẩm bẩm không ngừng."
  },
  AvgDialog_71794_Content_112 = {
    Text = "Amos luôn có sự nhạy cảm mạnh mẽ với vương miện, sức mạnh tinh thần của Samuel gần như là tốt nhất trong chúng ta……"
  },
  AvgDialog_71794_Content_113 = {
    Text = "Ồ không, mặc dù bạn ngủ suốt ngày, nhưng tôi nghĩ bạn mới là người giỏi nhất trong chúng ta."
  },
  AvgDialog_71794_Content_114 = {
