  AvgDialog_71794_Content_115 = {
    Text = "Tôi đương nhiên tin bạn mà. Những giấc mơ bạn thường gặp chắc chắn không phải bình thường, biết đâu đấy chính là gợi ý từ đấng tối cao."
  },
  AvgDialog_71794_Content_116 = {
    Text = "…Người cho tôi những lời chỉ dẫn khó hiểu như vậy để làm gì, một kẻ phàm nhân như tôi thì không thể thay đổi được điều gì."
  },
  AvgDialog_71794_Content_117 = {
    Text = "Không phải như vậy, vạn nhất thì sao? Thế hệ phàm nhân vẫn luôn cố gắng, chắc chắn sẽ có điều gì đó thay đổi được. Nếu không, tại sao chúng ta lại chọn Thần Vương chứ?"
