  AvgDialog_71794_Content_122 = {
    Text = "Hừm, bạn đang khen tôi hay mắng tôi… chẳng lẽ bạn không chút tò mò về cuộc sống khi trở thành Thần Vương sao?"
  },
  AvgDialog_71794_Content_123 = {
    Text = "Trong tiếng chửi rủa của Noah, bạn đối diện với đôi mắt màu cam vàng, bạn cảm thấy một xung động khó hiểu từ sâu thẳm trong lòng mình trào dâng lên."
  },
  AvgDialog_71794_Content_124 = {
