    Text = "Những đứa trẻ chỉ mới chạy được vài bước, khi bị gọi tên lớn, đành cúi đầu, lê từng bước nặng nề trở về."
  },
  AvgDialog_71794_Content_6 = {
    Text = "Ở phía ngoài vô số những bong bóng nhỏ bé, là giấc mơ dài vô tận của các vị Cổ Lão, vừa hỗn loạn vừa điên rồ."
  },
  AvgDialog_71794_Content_60 = {
    Text = "Lễ chính cười khẩy một tiếng, nhìn đám tội nhân nhỏ đang đứng hàng trước mặt."
  },
  AvgDialog_71794_Content_61 = {
    Text = "Hãy nói đi, các người đến đây để làm gì? Tôi đã dạy dỗ các ứng viên hoàng tử lâu như vậy, lẽ nào lại dạy ra một đám kẻ trộm lén lén lút lút sao?"
  },
  AvgDialog_71794_Content_62 = {
    Text = "Tôi, chúng tôi.."
  },
  AvgDialog_71794_Content_63 = {
    Text = "Noah lặng lẽ chắn trước tulô, siết chặt tay và chủ động bước ra."
  },
  AvgDialog_71794_Content_64 = {
    Text = "Vì lễ tuyển chọn người kế vị sắp diễn ra, chúng tôi muốn được tiếp xúc với vương miện trước buổi lễ để có thêm cảm nhận sâu sắc, hoàn toàn không có ý bất kính…"
  },
  AvgDialog_71794_Content_65 = {
    Text = "Tăng cường cảm ngộ, vậy tôi còn phải khen các bạn chăm chỉ nữa không?"
  },
  AvgDialog_71794_Content_66 = {
    Text = "Xin lỗi, thưa Chủ tế, việc này là do chúng tôi làm không đúng."
  },
  AvgDialog_71794_Content_67 = {
    Text = "Chỉ là chúng ta đã tu luyện quá lâu để giao tiếp với Chủ nhân, nhưng vẫn chưa thể đến gần vương miện mà Ngài trao tặng. Tất cả chúng ta đều tò mò về nó."
  },
  AvgDialog_71794_Content_68 = {
    Text = "Lễ chính nhìn cậu bé đầy lý trí, ngoài dự kiến không lên tiếng trách mắng."
  },
  AvgDialog_71794_Content_69 = {
    Text = "Samuel, em là đứa trẻ có sức mạnh tinh thần vượt trội trong số mọi người, em nghĩ tại sao tôi luôn không cho các em chạm vào vương miện?"
  },
  AvgDialog_71794_Content_70 = {
    Text = "Bởi vì chúng ta vẫn chưa thể kiểm soát được lực lượng của vương miện, có lẽ vương miện sẽ không đáp lại chúng ta."
  },
  AvgDialog_71794_Content_71 = {
    Text = "Amốt, Grếtchen, các bạn nghĩ sao?"
  },
  AvgDialog_71794_Content_72 = {
    Text = "Vì vương miện thiêng liêng và cao quý, đại diện cho quyền lực và trách nhiệm của thần vương, chúng ta còn chưa có tư cách chạm vào?"
  },
  AvgDialog_71794_Content_73 = {
    Text = "Bởi vì linh hồn của chúng ta không nhất thiết phù hợp với ý thích của Chúa, tự tiện chạm vào vương miện có thể là một sự xúc phạm?"
  },
  AvgDialog_71794_Content_74 = {
    Text = "Vị già nhân này, đã phụng sự thần minh suốt đời, lắc đầu với biểu cảm nghiêm trọng."
  },
  AvgDialog_71794_Content_75 = {
    Text = "Các bạn nói đúng, nhưng cũng không hoàn toàn đúng. Điều này chỉ vì một lý do đơn giản: không phải ai cũng có thể đội vương miện."
  },
  AvgDialog_71794_Content_76 = {
    Text = "Vậy thì, thưa ngài Chủ tế, cuối cùng người như thế nào mới có thể đội vương miện?"
  },
  AvgDialog_71794_Content_77 = {
    Text = "Các ngươi tu luyện mỗi ngày, rèn luyện tinh thần, quả thật là để tiếp nhận ý chí của Chúa tốt hơn. Nhưng trở thành đại diện của Chúa, đó là một định mệnh đã được sắp đặt từ trước."
  },
  AvgDialog_71794_Content_78 = {
    Text = "Vì vậy, điều cuối cùng các ngươi cần làm là chờ đợi sự lựa chọn của Chúa. Không cần phải buồn bã, không cần gượng ép. Về lý do tại sao các ngươi không được phép chạm vào…"
  },
  AvgDialog_71794_Content_79 = {
    Text = "Dáng vẻ nghiêm nghị của vị chủ tế bỗng trở nên mềm mỏng hơn trong khoảnh khắc này, nhưng đó không phải là lòng từ bi, mà là mang theo một chút ý nghĩa thương cảm."
  },
  AvgDialog_71794_Content_8 = {
    Text = "Ẩm ướt.\nCó vẻ như không khí ẩm ướt vĩnh viễn tràn vào giấc mơ của bạn, mang theo hơi thở mặn mà nhẹ nhàng."
  },
  AvgDialog_71794_Content_80 = {
    Text = "Người không được định mệnh chọn để tiếp nhận lời tiên tri nếu cố gắng đeo vương miện, sẽ chỉ dẫn đến cái chết do không thể chịu nổi lực lượng của thần linh."
  },
  AvgDialog_71794_Content_81 = {
    Text = "Trong đền thần, những đứa trẻ rơi vào im lặng lâu dài, khuôn mặt của thủ tế cũng từ từ khôi phục sự nghiêm khắc như xưa."
  },
  AvgDialog_71794_Content_82 = {
    Text = "Với lòng nhiệt thành đáng khen ngợi, các người đã bất chấp hiểm nguy đến thờ phụng vương miện."
  },
  AvgDialog_71794_Content_83 = {
    Text = "Để thể hiện lòng thành kính đối với Đấng tối cao, tất cả mọi người phải chép lời cầu nguyện một trăm lần trước vương miện. Khi nào chép xong thì khi đó mới được rời đi."
  },
  AvgDialog_71794_Content_84 = {
    Text = "Các đứa trẻ phát ra những tiếng than vãn dài, rồi lại im lặng dưới ánh mắt của chủ tế, chỉ còn cách cúi đầu, mặt mày ủ rũ chấp nhận số phận."
  },
  AvgDialog_71794_Content_85 = {
    Text = "Trong những ánh mắt bất mãn, sợ hãi, ngưỡng mộ và tôn kính hướng về phía bạn, chỉ có Tulô chưa bao giờ liếc nhìn bạn."
  },
  AvgDialog_71794_Content_86 = {
    Text = "Lễ chính nhìn tulô, người vẫn không động lòng từ đầu đến cuối, với ánh mắt thâm trầm và cuối cùng rời đi mà không nói một lời."
  },
  AvgDialog_71794_Content_87 = {
    Text = "Trong khoảnh khắc hai người lướt qua nhau, bạn đã nghe được tiếng lòng của người lãnh đạo tương lai."
  },
  AvgDialog_71794_Content_88 = {
    Text = "(<Gray:không có ích gì, dù có đeo vương miện, thì có thể thay đổi được điều gì ?>)"
  },
  AvgDialog_71794_Content_9 = {
    Text = "(<Gray:hương gió biển... lại vào giấc mơ rồi sao?>)"
  },
  AvgDialog_71794_Content_90 = {
    Text = "Chẳng mấy chốc, bạn ngồi ngay ngắn trên bệ thờ cao, tầm mắt nhìn xuống dọc theo bậc đá, thấy lũ trẻ nghiêng ngả nằm quỳ trên đệm ngồi chép lời cầu nguyện."
  },
  AvgDialog_71794_Content_91 = {
    Text = "Lắng nghe Đức Chúa. Quy y Đức Chúa. Phàm tội lỗi, Đức Chúa sẽ trừng phạt. Phàm lạc lối, Đức Chúa sẽ chỉ dẫn……"
  },
  AvgDialog_71794_Content_92 = {
    Text = "Tiếng thì thầm đọc thuộc lòng kèm theo tiếng giấy lật rào rào vang vọng trong đền thần, thỉnh thoảng còn xen kẽ những tiếng thở dài mệt mỏi."
  },
  AvgDialog_71794_Content_93 = {
    Text = "Hễ ai gặp khó khăn, Chúa sẽ đền bù. Hễ ai thành tâm, Chúa sẽ ban phúc. Hễ ai cầu xin, Chúa sẽ ban ơn. Hễ ai mong đợi, Chúa sẽ thực hiện…"
  },
  AvgDialog_71794_Content_94 = {
    Text = "Khuôn mặt đầy vẻ khổ sở của Noah bên cạnh là một chồng giấy cao hơn người khác, chỉ cần nhìn qua lớp giấy mỏng trước mặt Tulô là có thể hiểu nguyên nhân — đó là những tờ giấy mà anh ta đã hùng hồn giành lấy từ tay Tulô."
  },
  AvgDialog_71794_Content_95 = {
    Text = "Bạn bị tôi kéo đến đây, xét về tình cảm và lý trí, tôi đều phải chia sẻ gánh nặng với bạn."
  },
  AvgDialog_71794_Content_96 = {
    Text = "Tulô không giành lấy từ anh ta, chỉ im lặng rút ra vài miếng bánh ngọt có vị hạt, lạnh lùng đưa cho Noah."
  },
  AvgDialog_71794_Content_97 = {
    Text = "Đây là phần tích lũy từ hai ngày phân bữa, tôi không thích ăn."
  },
  AvgDialog_71794_Content_98 = {
    Text = "Amalant sụ?! Huru, bạn thật sự rất tuyệt.."
  },
  AvgDialog_71794_Content_99 = {
    Text = "Noah phồng má lên, mắt đẫm lệ, lắc nhẹ tay tulô."
  },
  AvgDialog_71986_Content_1 = {
    Text = "Im lặng. Giống như bóng tối và sự yên tĩnh vĩnh cửu."
  },
  AvgDialog_71986_Content_10 = {
    Text = "Ảnh ảo tan vỡ trước mắt, một cô gái hiện ra với đôi môi mím chặt, đôi mắt bị che khuất hoàn toàn bởi miếng bịt mắt."
  },
  AvgDialog_71986_Content_11 = {
    Text = "Không phải cô ấy, mà là tôi."
  },
  AvgDialog_71986_Content_12 = {
    Text = "Vào khoảnh khắc cuối cùng, cô ấy đã giao thân thể cho tôi."
  },
  AvgDialog_71986_Content_13 = {
    Text = "Đứng trước sự hồi tố của hủy diệt, tôi đã không biết trải qua bao nhiêu lần……"
  },
  AvgDialog_71986_Content_14 = {
    Text = "Cô ấy tiến lên, dùng đôi bàn tay mảnh mai che mắt bạn."
  },
  AvgDialog_71986_Content_15 = {
    Text = "Hãy giao cho tôi một phần ý thức của bạn."
  },
  AvgDialog_71986_Content_16 = {
    Text = "Giống như màn đêm buông xuống, vạn vật chìm vào bóng tối…"
  },
  AvgDialog_71986_Content_17 = {
    Text = "Rồi mặt trời mọc lên, mọi thứ trở lại điểm khởi đầu."
  },
  AvgDialog_71986_Content_18 = {
    Text = "Đây là ý thức của bạn, mọi thứ của họ đều xuất phát từ bạn."
  },
  AvgDialog_71986_Content_19 = {
    Text = "Họ sẽ không lưu giữ ký ức về đoạn hủy diệt này, nhưng tôi tin rằng bạn sẽ không quên."
  },
  AvgDialog_71986_Content_2 = {
    Text = "Trong sự yên lặng vô tận ấy, một điểm sáng trắng nhỏ bé lặng lẽ ngưng tụ, lơ lửng trước mắt."
  },
  AvgDialog_71986_Content_20 = {
    Text = "Từng khoảnh khắc nhỏ bé này"
  },
  AvgDialog_71986_Content_21 = {
    Text = "Trước khi sự hủy diệt định mệnh trở lại."
  },
  AvgDialog_71986_Content_3 = {
    Text = "Rất tiếc, trong hành trình đối đầu với sự rỗng rỗng này… chúng ta đã phải chịu tổn thất vô cùng nặng nề."
  },
  AvgDialog_71986_Content_4 = {
    Text = "Với cái giá là ngươi…"
  },
  AvgDialog_71986_Content_5 = {
    Text = "Nhưng tôi không thể chịu đựng được, thấy bạn bước vào cánh cửa đó, cô đơn mãi mãi."
  },
  AvgDialog_71986_Content_6 = {
    Text = "Giọng nữ thanh thoát và lạnh nhạt. Đủ quen thuộc, nhưng lại có chút khác biệt."
  },
  AvgDialog_71986_Content_7 = {
    Text = "Mở mắt ra đi!"
  },
  AvgDialog_71986_Content_8 = {
    Text = "Tôi sẽ trả lại cho bạn… một thế giới."
  },
  AvgDialog_71986_Content_9 = {Text = "Ramon…"},
  AvgDialog_71987_Content_1 = {
    Text = "Lương thực của con người"
  },
  AvgDialog_71987_Content_10 = {
    Text = "Ý của bạn là.."
  },
  AvgDialog_71987_Content_11 = {
    Text = "Ai ở đó?"
  },
  AvgDialog_71987_Content_12 = {
    Text = "Xin lỗi, là, là tôi."
  },
  AvgDialog_71987_Content_13 = {
    Text = "Thông thường, tôi sẽ kiểm tra nhà thờ lần cuối trước lúc trời tối. Thấy hai người không có trên giường, tôi quyết định đi xem thử, không cố tình nghe lén câu chuyện của mọi người…"
  },
  AvgDialog_71987_Content_14 = {
    Text = "Không sao cả, Orci, bạn cũng hãy qua đây đi."
  },
  AvgDialog_71987_Content_15 = {
    Text = "Được, được."
  },
  AvgDialog_71987_Content_16 = {
    Text = "Orci khéo léo nhưng chậm chạp bước lên bục theo các bậc gỗ, cẩn thận không để phát ra tiếng động dưới chân, để không làm phiền giấc ngủ của mọi người."
  },
  AvgDialog_71987_Content_17 = {
    Text = "Quay lại câu hỏi vừa rồi."
  },
  AvgDialog_71987_Content_18 = {
    Text = "Tôi đã suy nghĩ kỹ về vấn đề này: liệu mọi bi kịch mà chúng ta đang chứng kiến có phải do tôi gây ra không?"
  },
  AvgDialog_71987_Content_19 = {
    Text = "Tôi có thể trả lời bạn là: rất giống."
  },
  AvgDialog_71987_Content_2 = {
    Text = "Mấy người họ đã ngủ chưa?"
  },
  AvgDialog_71987_Content_20 = {
    Text = "Gọn gàng, súc tích, với mục tiêu cái chết nhanh gọn, khá hợp với sở thích thẩm mỹ của tôi."
  },
  AvgDialog_71987_Content_21 = {
    Text = "Nhưng vẫn có những điểm khác biệt —— tôi không thích các thiết bị có độ trễ, sự chờ đợi và tra tấn ấy quả thực là một cực hình mà tôi không thể dung thứ."
  },
  AvgDialog_71987_Content_22 = {
    Text = "Vì tôi đã hành động cùng mọi người trong khoảng thời gian này, nên không có thời gian để gửi lệnh gọi là \"thông báo tử vong\"."
  },
  AvgDialog_71987_Content_23 = {
    Text = "Thế, thế thì tốt quá!"
  },
  AvgDialog_71987_Content_24 = {Text = "Tại sao?"},
  AvgDialog_71987_Content_25 = {
    Text = "Vừa nghe cuộc trò chuyện của các bạn, tôi lo rằng cô đóa là kẻ đứng sau mọi việc này."
  },
  AvgDialog_71987_Content_26 = {
    Text = "Như vậy, tôi sẽ phải đứng ra và trở thành kẻ thù của cô Đóa."
  },
  AvgDialog_71987_Content_27 = {
    Text = "Bây giờ, biết được kẻ chủ mưu là người khác, tôi không cần phải lo âu nữa và có thể coi cô đóa là đồng minh!"
  },
  AvgDialog_71987_Content_28 = {
    Text = "Orci đã cất cây súng dài mà anh ta vừa mới lén giấu sau lưng, nụ cười chân thành và tỏa sáng."
  },
  AvgDialog_71987_Content_3 = {
    Text = "Ừ, họ nên nghỉ ngơi thật tốt."
  },
  AvgDialog_71987_Content_30 = {
    Text = "Hừm, tôi cũng chẳng quan tâm gì đến chuyện đồng đội hay không đồng đội."
  },
  AvgDialog_71987_Content_31 = {
    Text = "Không, đóa."
  },
  AvgDialog_71987_Content_32 = {
    Text = "Mặc dù tôi không biết gì về bạn trong thế giới này đã nguồn gốc, nhưng tôi quá quen thuộc với đóa… khi cô ấy là giáo sư."
  },
  AvgDialog_71987_Content_33 = {
    Text = "Không bằng anh hãy nói cho tôi biết, người \"đóa\" mà anh biết là một người như thế nào?"
  },
  AvgDialog_71987_Content_35 = {
    Text = "Giáo sư có khuôn mặt lạnh lùng mà tôi gặp lần đầu tiên trong lớp học giới vực."
  },
  AvgDialog_71987_Content_36 = {
    Text = "Tại lễ trao chìa khóa, đóa đã trang trọng và cẩn trọng giao chìa khóa bạc vào tay bạn."
  },
  AvgDialog_71987_Content_37 = {
    Text = "Đóa thường châm biếm luận văn và trí óc của bạn, nhưng cuối cùng sẽ giải quyết mọi lo lắng cho bạn."
  },
  AvgDialog_71987_Content_38 = {
    Text = "Đóa khi đối mặt một mình với Herbert tại bệnh viện điều dưỡng Laï, đã mở ra con đường sinh tồn cho các bạn."
  },
  AvgDialog_71987_Content_39 = {
    Text = "……và cuối cùng, đóa đã dứt khoát cắt đứt liên kết với bạn."
  },
  AvgDialog_71987_Content_4 = {
    Text = "Bạn nhìn thấy vào ban ngày từ giấc mơ rỗng tuếch.."
  },
  AvgDialog_71987_Content_40 = {
    Text = "Những kỷ niệm xưa dần hiện lên, hóa ra trong vô thức, các bạn đã bên nhau trải qua biết bao nhiêu câu chuyện."
  },
  AvgDialog_71987_Content_41 = {
    Text = "Bạn đã kể cho cô ấy tất cả những gì bạn biết về đóa."
  },
  AvgDialog_71987_Content_43 = {
    Text = "……………"
  },
  AvgDialog_71987_Content_44 = {
    Text = "Dù miệng nói không hay, nhưng trong lòng bạn vẫn rất tôn trọng cô ấy, phải không?"
  },
  AvgDialog_71987_Content_45 = {
    Text = "Hãy để tôi đoán xem, đây chính là lý do bạn đến giờ vẫn chưa động thủ với tôi, phải không?"
  },
  AvgDialog_71987_Content_46 = {
    Text = "Tôi đã mất trí nhớ, nhưng bạn thì không.\nBạn đã có rất nhiều cơ hội, trong khi tôi còn chưa nhận ra danh tính của bạn thì đã tấn công tôi bất ngờ, nhưng bạn không làm gì cả."
  },
  AvgDialog_71987_Content_47 = {
    Text = "Có vẻ như người hướng dẫn của bạn vẫn chưa nói cho bạn biết cách đối xử với kẻ thù tiềm năng."
  },
  AvgDialog_71987_Content_48 = {
    Text = "Tại thời điểm thích hợp, biết đâu tôi sẽ ra tay."
  },
  AvgDialog_71987_Content_49 = {
    Text = "Nhưng không phải bây giờ."
  },
  AvgDialog_71987_Content_5 = {
    Text = "Là thế giới này đang hấp hối."
  },
  AvgDialog_71987_Content_50 = {
    Text = "Chú chó con ngốc nghếch... sớm muộn gì bạn cũng sẽ phải trả giá cho lòng trắc ẩn của mình."
  },
  AvgDialog_71987_Content_52 = {
    Text = "<Shake:í——í ya——>"
  },
  AvgDialog_71987_Content_53 = {
    Text = "Một tiếng thét chói tai xé toạc bầu trời."
  },
  AvgDialog_71987_Content_54 = {
    Text = "Sao vậy?!"
  },
  AvgDialog_71987_Content_55 = {
    Text = "Ở cuối tầm nhìn, hình bóng của Mason lao đến trong dáng vẻ hoảng loạn. Đôi tay cô ấy quờ quạng xé toạc mái tóc rối bời, miệng lảm nhảm những lời không rõ nghĩa, đầy tuyệt vọng."
  },
  AvgDialog_71987_Content_56 = {
    Text = "Sarah…… hãy đi xem bà Sarah……\nĐầu của bà……Đầu của bà!!"
  },
  AvgDialog_71987_Content_6 = {
    Text = "Vì cái chết sắp đến, tất cả sinh linh dùng bản năng để dựa vào, ôm chặt và hòa làm một."
  },
  AvgDialog_71987_Content_7 = {
    Text = "Đóa… Trong thế giới của tôi, bạn đã gây ra lũ lụt, sạt lở núi, rỗng rỗng lan rộng và các thảm họa khác."
  },
  AvgDialog_71987_Content_8 = {
    Text = "Chẳng lẽ đây là do cậu làm sao?"
  },
  AvgDialog_71987_Content_9 = {Text = "Xin lỗi."},
  AvgDialog_71989_Content_1 = {
    Text = "Quả táo có độc"
  },
  AvgDialog_71989_Content_10 = {
    Text = "……………"
  },
  AvgDialog_71989_Content_11 = {
    Text = "Sự im lặng kéo dài giữa các người vẫn kéo dài. Bạn cảm thấy họng mình nghèn nghẹn, không biết phải nói gì."
  },
  AvgDialog_71989_Content_12 = {Text = "Hít sâu"},
  AvgDialog_71989_Content_13 = {
    Text = "Đại học gần nhất với \"Đại học Misag\" là một trường đại học khác, cũng tập trung nghiên cứu về sinh vật dị chủng."
  },
  AvgDialog_71989_Content_14 = {
    Text = "Chỉ là nghiên cứu của họ cổ kính và chính thống hơn, công việc của các điều tra viên chủ yếu tập trung vào nghiên cứu khảo cổ, khảo sát thực địa và biên soạn văn bản huyền học, quy mô nhân viên chiến đấu ít hơn nhiều so với Đại học Misaque."
  },
  AvgDialog_71989_Content_15 = {
    Text = "Trường đại học này... có tên là \"Đại học Miskatonic\"."
  },
  AvgDialog_71989_Content_16 = {
    Text = "Không có Người Giữ Gìn, không có lõi bạc, \"Đại học Miskatonic\" của thế giới này tự nhiên không có điều kiện để tuyển dụng đóa."
  },
  AvgDialog_71989_Content_17 = {
    Text = "Thật đáng tiếc, tôi không còn nhớ cuộc hủy diệt mà Jenkin đã nói, e rằng toàn bộ ký ức sau đó đều đã mất do vụ nổ."
  },
  AvgDialog_71989_Content_18 = {
    Text = "Còn về việc bạn muốn trở lại thế giới ban đầu… tôi có một số suy nghĩ."
  },
  AvgDialog_71989_Content_19 = {
    Text = "Bà Daphne từng nói với bạn rằng nơi đây không phải là giấc mơ của Tovarva, vậy nên việc biết được sự thật về thế giới hiện tại có thể giúp ích trong việc xây dựng liên kết với các thế giới chiều khác."
  },
  AvgDialog_71989_Content_2 = {
    Text = "Bạn đang một mình trên sân thượng, thở không khí đêm trong lành."
  },
  AvgDialog_71989_Content_20 = {
    Text = "Đây là một con đường dài hơn và phần lớn hiệu quả——rốt cuộc, trước khi mất trí nhớ, tôi đã từng chuyển đổi thành công sang nhiều chiều, và tôi cùng với suy nghĩ của mình nên duy trì được sự nhất quán."
  },
  AvgDialog_71989_Content_21 = {
    Text = "Còn về con đường tắt, để tôi suy nghĩ kỹ rồi sẽ nói với bạn……"
  },
  AvgDialog_71989_Content_22 = {
    Text = "Tuy nhiên, còn có một điều bạn nên cân nhắc thật kỹ."
  },
  AvgDialog_71989_Content_23 = {
    Text = "Việc khám xét trại tế bần này hoàn toàn không liên quan đến việc bạn trở về thế giới ban đầu."
  },
  AvgDialog_71989_Content_24 = {
    Text = "Bây giờ bạn đang tập trung vào những chuyện vặt vãnh. Đến ngày đó, liệu bạn có thực sự buông bỏ tất cả ở đây và trở về cuộc sống cũ một cách thanh thản không?"
  },
  AvgDialog_71989_Content_25 = {
    Text = "Bạn có thể từ từ suy nghĩ về vấn đề này. Bây giờ, có những thứ quan trọng hơn cần phải đối mặt.\nBạn nhìn về phía đó—"
  },
  AvgDialog_71989_Content_26 = {
    Text = "Ánh sáng di động như những ngôi sao nhỏ xuất hiện trong bóng tối, lướt qua đêm tối với tiếng động nhẹ nhàng và mỏng manh."
  },
  AvgDialog_71989_Content_27 = {
    Text = "Là dị cấu thể rỗng!"
  },
  AvgDialog_71989_Content_28 = {
    Text = "Những dị cấu thể rỗng rỗng bị bạn đuổi đi vào ban ngày, giờ đây ùa đến thành đàn, chúng chen chúc, xô đẩy một cách bồn chồn, thậm chí còn leo lên người nhau và cắn xé."
  },
  AvgDialog_71989_Content_29 = {
    Text = "Mục tiêu của họ……, rất rõ ràng, chính là tháp đồng hồ."
  },
  AvgDialog_71989_Content_3 = {
    Text = "Dù thành phố hoang tàn bị bao phủ bởi khói bụi, nhưng trên sân thượng cao vẫn có thể nhìn thấy những ngôi sao sáng lấp lánh, mang lại chút an ủi ngắn ngủi."
  },
  AvgDialog_71989_Content_30 = {
    Text = "Họ đang nhắm vào chúng ta."
  },
  AvgDialog_71989_Content_31 = {
    Text = "Đối đầu!"
  },
  AvgDialog_71989_Content_4 = {
    Text = "Hủy diệt·đóa… Tại sao bạn ở thế giới này không chọn gia nhập Đại học Misaque?"
  },
  AvgDialog_71989_Content_5 = {
    Text = "Bạn hiểu lầm về thế giới này, đồ ngốc nhỏ bé."
  },
  AvgDialog_71989_Content_6 = {
    Text = "Ánh sao rơi trên các khớp cầu của đóa, phản chiếu ra màu kim loại khác thường, không giống con người."
  },
  AvgDialog_71989_Content_7 = {
    Text = "Bạn nghĩ rằng sự khác biệt giữa các chiều chỉ nằm ở biểu hiện của sự rỗng rỗng và trải nghiệm cá nhân sao? Đó là một sai lầm lớn."
  },
  AvgDialog_71989_Content_8 = {
    Text = "Theo như tôi biết, trong chiều này, hoàn toàn không tồn tại cái gọi là \"Đại học Misaque\"."
  },
  AvgDialog_71990_Content_1 = {
    Text = "Câu trả lời có thể"
  },
  AvgDialog_71990_Content_10 = {
    Text = "Dậy đi, dậy đi, hai kẻ lười biếng."
  },
  AvgDialog_71990_Content_11 = {
    Text = "Chị gái bảo tôi gọi các bạn đến chỗ dì Sara."
  },
  AvgDialog_71990_Content_12 = {
    Text = "Các người bước vào phòng riêng của nhà thờ, Mason đang chăm sóc Sara đang ngủ yên trên giường bệnh, ánh lửa vàng nhạt từ lò sưởi làm ấm áp đôi má cô ấy."
  },
  AvgDialog_71990_Content_13 = {
    Text = "Lễ tế Salvador đứng bên cửa sổ, chầm chậm ngắm nhìn cảnh sắc bên ngoài, như một bức tượng im lìm."
  },
  AvgDialog_71990_Content_14 = {
    Text = "Sara trong giấc mơ thốt lên những lời lẩm bẩm đau đớn, các người đang chuẩn bị lại gần, Mason đặt ngón tay lên môi và thì thầm \"shh\", sau đó lấy ra một chiếc khăn tay trắng lau chùi."
  },
  AvgDialog_71990_Content_15 = {
    Text = "Mọi người hãy theo tôi."
  },
  AvgDialog_71990_Content_16 = {
    Text = "Bệnh của bà Sara phức tạp hơn tôi nghĩ."
  },
  AvgDialog_71990_Content_17 = {
    Text = "Không tìm ra nguyên nhân sao?"
  },
  AvgDialog_71990_Content_18 = {
    Text = "Không, ngược lại, tôi đã có một số ý niệm.\nChỉ là......"
  },
  AvgDialog_71990_Content_19 = {
    Text = "Tôi nghĩ rằng các bạn đều rất quen thuộc với nguyên lý hình thành \"thân thể được đánh thức\", vì vậy tôi sẽ không giải thích chi tiết."
  },
  AvgDialog_71990_Content_2 = {
    Text = "Biển đang gọi bạn..."
  },
  AvgDialog_71990_Content_20 = {
    Text = "Năng lượng ý chí cao cấp trong cơ thể bà Sara đang ở trong một cuộc xung đột gay gắt với ý chí cao cấp duy trì linh hồn của bà."
  },
  AvgDialog_71990_Content_21 = {
    Text = "Nếu tách bỏ bạc tâm được cấy vào đầu của bà Sara, bà sẽ mất ý thức; nếu không dựa vào lực lượng từ giấc mơ, thân thể của bà sẽ hóa thành tro bụi như bao người khác."
  },
  AvgDialog_71990_Content_22 = {
    Text = "Thật không may, tôi không thể chữa lành cô ấy bằng sức mạnh của cha thần.\nBất kể ý chí cấp cao nào cuối cùng chiến thắng...... Cuộc sống của quý cô Sarah khó có thể duy trì."
  },
  AvgDialog_71990_Content_23 = {
    Text = "Tôi đã hiểu, cô ấy không thể tránh khỏi cái chết."
  },
  AvgDialog_71990_Content_24 = {
    Text = "Hoặc từ bỏ sức sống, hoặc tiếp tục sống trong đau khổ… không có lựa chọn nào khác sao?"
  },
  AvgDialog_71990_Content_25 = {
    Text = "Salvador lắc đầu, mái tóc trắng hơi lộn xộn quét qua áo giáo chủ, phát ra tiếng sột soạt."
  },
  AvgDialog_71990_Content_26 = {
    Text = "Melt·đóa vọng hướng về bạn, đáy mắt lộ ra nụ cười chiến thắng không phù hợp, tựa hồ đang khoe khoang: \"Bạn xem, tôi đã nói đúng rồi phải không?\""
  },
  AvgDialog_71990_Content_27 = {Text = "Ho, ho…"},
  AvgDialog_71990_Content_28 = {
    Text = "Tiếng ho dữ dội vọng ra từ nơi u tối, trên khuôn mặt Sara đang chịu đựng đau khổ, những vết nứt màu bạc trắng trở nên hung ác hơn."
  },
  AvgDialog_71990_Content_29 = {
    Text = "Tôi nghe thấy rồi… là %player%… {Male=anh ấy,Female=cô ấy} có ở đây không?"
  },
  AvgDialog_71990_Content_3 = {
    Text = "Đó là biển đen tối, dưới ánh sáng của các vì sao, phản chiếu đan xen những tia sáng xanh vàng mờ ảo và u ám."
  },
  AvgDialog_71990_Content_30 = {
    Text = "Cô ấy, đang gọi tôi sao?"
  },
  AvgDialog_71990_Content_31 = {
    Text = "Còn ai vào đây nữa? Chúng ta có ai khác tên là %player% không?"
  },
  AvgDialog_71990_Content_32 = {
    Text = "Bạn tiến lại gần giường của Sarah, Mason đã nâng Sarah dậy ngồi.\nSarah thở hổn hển, một lúc lâu mới miễn cưỡng ổn định cơ thể, ngẩng đầu nhìn bạn nở một nụ cười miễn cưỡng."
  },
  AvgDialog_71990_Content_33 = {
    Text = "Vị thiện nhân này… có thể nhờ bạn một việc được không?"
  },
  AvgDialog_71990_Content_34 = {
    Text = "Mời bạn nói."
  },
  AvgDialog_71990_Content_35 = {
    Text = "Tôi có thể nhận ra, bạn là một người hiểu biết rộng."
  },
  AvgDialog_71990_Content_36 = {
    Text = "Có thể xin anh giao những món trang sức này cho ông Rogers để dùng làm khoản bù đắp chi phí sinh hoạt của Ai Jī Sī trước khi cô ấy độc lập không?"
  },
  AvgDialog_71990_Content_37 = {
    Text = "Tôi biết, có lẽ tôi sẽ không còn được chứng kiến cô ấy trưởng thành… Ông Rogers hào phóng, có lẽ cũng chẳng thiếu thốn gì mấy."
  },
  AvgDialog_71990_Content_38 = {
    Text = "Nhưng với những món trang sức này, cô ấy ít nhất không hoàn toàn sống nhờ vào người khác…… đứa trẻ đó từ nhỏ đã bị mẹ ruột bỏ rơi, tôi muốn cô ấy biết rằng chị Sara không bỏ rơi cô ấy……"
  },
  AvgDialog_71990_Content_39 = {
    Text = "Rồi sau đó, hãy nói với cô ấy rằng khi cô ấy lớn lên, mỗi năm nhớ đặt một bó hoa trước mộ của Tiyug và Willy nhỏ... Những đứa trẻ còn quá nhỏ, chắc chắn sẽ rất cô đơn và cần sự tưởng nhớ."
  },
  AvgDialog_71990_Content_4 = {
    Text = "Đó là giấc mơ dài u tối của người ngủ sâu, bóng tối và sự tĩnh lặng bao trùm, với ngôi sao đen lơ lửng phía trên."
  },
  AvgDialog_71990_Content_40 = {
    Text = "Còn bạn, Sara?"
  },
  AvgDialog_71990_Content_41 = {
    Text = "Yên tâm đi, tôi sẽ không dễ dàng từ bỏ. Trước khi ngày đó đến, tôi sẽ chiến đấu để sống sót.\nCho dù chỉ còn một tia hy vọng… tôi vẫn muốn gặp lại những đứa trẻ đó một lần nữa."
  },
  AvgDialog_71990_Content_42 = {
    Text = "Trên đường phố London hoang vắng, bạn thở dài một hơi dài.\nDù con đường phủ đầy bụi bẩn, cũng không thể bằng không khí nặng nề xoay quanh Sarah."
  },
  AvgDialog_71990_Content_43 = {
    Text = "Nóng chảy · đóa đi bên cạnh bạn, giữ khoảng cách nửa bước so với bạn."
  },
  AvgDialog_71990_Content_44 = {
    Text = "Đóa. Hôm nay, tôi có thể trả lời câu hỏi của bạn rồi."
  },
  AvgDialog_71990_Content_45 = {
    Text = "Hãy để tôi nghe những lời ngụy biện của bạn."
  },
  AvgDialog_71990_Content_46 = {
    Text = "Bạn có biết không? Trong mắt bạn, Sara đã là người sắp chết. Nỗi lưu luyến của cô ấy đối với thế giới này đã chẳng còn ý nghĩa gì."
  },
  AvgDialog_71990_Content_47 = {
    Text = "Nhưng thực tế không phải vậy. Cô ấy vẫn còn lo lắng cho những đứa trẻ bị đưa đi."
  },
  AvgDialog_71990_Content_48 = {
    Text = "Đây là con người bình thường, và nỗi lo của con người bình thường."
  },
  AvgDialog_71990_Content_49 = {
    Text = "Sự kết thúc và cái chết mà bạn đẩy tới chỉ là tước đi hy vọng cuối cùng của họ mà thôi."
  },
  AvgDialog_71990_Content_5 = {
    Text = "Cuộn quanh, xung đột, vặn vẹo, xé rách, giãy dụa – những xúc chi đan xen và đấu tranh lẫn nhau."
  },
  AvgDialog_71990_Content_50 = {
    Text = "Nhưng hy vọng chỉ là ảo ảnh mơ hồ, nỗi đau hiện tại mới là điều thực sự."
  },
  AvgDialog_71990_Content_51 = {
    Text = "Dù cho sống trong ảo ảnh, vẫn có nhiều người sẵn sàng chịu đựng nỗi đau hiện tại vì hy vọng."
  },
  AvgDialog_71990_Content_52 = {
    Text = "Đây chính là sự bền bỉ của con người."
  },
  AvgDialog_71990_Content_53 = {
    Text = "Bạn nói rằng bạn không hiểu mục đích của Chiến dịch Salvador, nhưng tôi có thể hiểu."
  },
  AvgDialog_71990_Content_54 = {
    Text = "Hành động của Salvador chỉ tuân theo một nguyên tắc, đó là để mọi người \"bình đẳng sống\"."
  },
  AvgDialog_71990_Content_55 = {
    Text = "Trong mắt anh ta, cuộc sống không phải là sự cân nhắc, cũng không phải là con số. Anh ta nhìn thấy những con người khao khát được sống."
  },
  AvgDialog_71990_Content_56 = {
    Text = "Chỉ cần \"sống sót\", thì tương lai vẫn còn, vẫn có khả năng."
  },
  AvgDialog_71990_Content_57 = {
    Text = "\"khả năng\" phải không?..."
  },
  AvgDialog_71990_Content_58 = {
    Text = "Melt·đóa suy nghĩ một lúc, sau đó dường như nhớ ra điều gì đó, phát ra một tiếng hừ lạnh lùng."
  },
  AvgDialog_71990_Content_59 = {
    Text = "Hừ, nếu đã vậy, hãy theo tôi."
  },
  AvgDialog_71990_Content_6 = {
    Text = "Một bên gào thét: Ta chắc chắn sẽ nuốt chửng cái bình chứa ngon lành, nguồn của cảm hứng và trí tuệ, vật mang lại sự thông suốt và tư duy, cơ quan của trí tưởng tượng và vọng tưởng."
  },
  AvgDialog_71990_Content_60 = {Text = "Đi đâu?"},
  AvgDialog_71990_Content_61 = {
    Text = "Tận mắt chứng kiến…… đi xác nhận một câu trả lời."
  },
  AvgDialog_71990_Content_62 = {
    Text = "Nhớ gọi con chuột nhỏ đó cùng, chúng ta sẽ có việc cần nhờ đến cô ấy."
  },
  AvgDialog_71990_Content_7 = {
    Text = "Phía bên kia đáp lại: Sự tham lam đã mục nát tự khắc sẽ chìm nghỉm dưới đáy hồ tối tăm, nơi không một ánh sao nào có thể chiếu tới."
  },
  AvgDialog_71990_Content_9 = {
    Text = "……………"
  },
  AvgDialog_71991_Content_1 = {
    Text = "Sự thật"
  },
  AvgDialog_71991_Content_10 = {
    Text = "Đóa tung chân, dễ dàng đá bay dị thể rỗng rỗng đang lao tới."
  },
  AvgDialog_71991_Content_11 = {
    Text = "Đừng dài dòng, nếu khiến tôi thấy chán, tôi sẽ tiêu diệt cả lũ!"
  },
  AvgDialog_71991_Content_13 = {
    Text = "Bạn sẽ kể lại từng sự kiện sau khi gặp Melt·đóa lần đầu, từ việc cứu cô ấy sau tai nạn tuyết lở, đến khi cô ấy sử dụng cơ thể giả của đóa để thoát khỏi sự giam giữ, cho đến khi đưa bạn sang chiều hiện tại……"
  },
  AvgDialog_71991_Content_14 = {
    Text = "Tôi đã hiểu, vậy là bạn đã làm nổ phòng thí nghiệm của tôi, và còn bắt tôi ở đây làm việc không công cho bạn."
  },
  AvgDialog_71991_Content_15 = {
    Text = "Đừng cắt cúp lời, trước đó chính bạn đã hủy diệt chiều của tôi và giam giữ tôi trong một bình chứa não."
  },
  AvgDialog_71991_Content_16 = {
    Text = "Không quan trọng nữa."
  },
  AvgDialog_71991_Content_17 = {
    Text = "Một đầu lâu nứt nẻ với khuôn mặt dữ tợn của một dị thể bán tan rã gừ gừ một tiếng, phun ra chất lỏng đen đặc và phát ra tiếng xì xì rùng mình."
  },
  AvgDialog_71991_Content_18 = {
    Text = "Nhưng điều bạn nói về việc hủy diệt thế giới…"
  },
  AvgDialog_71991_Content_19 = {
    Text = "Chân kẹp đâm thủng đầu của con chuột hoang khổng lồ bị nhiễm rỗng rỗng, phát ra tiếng \"rắc\" khi não bắn tung tóe, nhưng Đóa không màng để ý, chỉ khẽ rung chân kẹp và hất nó xuống."
  },
  AvgDialog_71991_Content_2 = {
    Text = "Đi tìm bọn Tây Khu à? Đừng kể tôi vào. Tôi không hòa hợp với những người đó."
  },
  AvgDialog_71991_Content_20 = {
    Text = "Trong ký ức của tôi, tôi hoàn toàn không có lý do tìm kiếm sự hủy diệt của thế giới."
  },
  AvgDialog_71991_Content_21 = {
    Text = "Trái lại, tôi luôn tìm cách bảo vệ thế giới khỏi nguy cơ xói mòn và vì vậy mà bận rộn không ngừng."
  },
  AvgDialog_71991_Content_22 = {
    Text = "Bạn nghĩ tôi đang lừa bạn ?"
  },
  AvgDialog_71991_Content_23 = {
    Text = "Không, tôi không phủ nhận lời bạn nói. Qua ánh mắt của bạn, tôi thấy rõ sự chân thành."
  },
  AvgDialog_71991_Content_24 = {
    Text = "Điều này chắc chắn có lý do cho sự lựa chọn của tôi, chỉ là hiện tại tôi vẫn không biết gì cả."
  },
  AvgDialog_71991_Content_25 = {
    Text = "Ánh mắt của cô ấy lộ ra một tia hoang mang gần như không thể nhận ra."
  },
  AvgDialog_71991_Content_26 = {
    Text = "Tự xưng là thiên tài, tôi ám ảnh với sự thật đến mức từ bỏ tất cả nền văn minh \"gạo-gậy\"..."
  },
  AvgDialog_71991_Content_27 = {
    Text = "Vì sao lại dễ dàng phản bội sang phe hủy diệt?"
  },
  AvgDialog_71991_Content_28 = {
    Text = "Bạn nhanh nhạy nắm bắt được một từ khóa độc đáo."
  },
  AvgDialog_71991_Content_29 = {
    Text = "\"Mi-Go\" văn minh..."
  },
  AvgDialog_71991_Content_3 = {
    Text = "Nói gì thì nói, tôi phải ở lại để bảo vệ chị gái."
  },
  AvgDialog_71991_Content_30 = {
    Text = "Trong ghi chép của Misaque, nền văn minh nguồn của bạn được gọi là Ale Meses…"
  },
  AvgDialog_71991_Content_31 = {
    Text = "Ale Meses, nấm bay… cái biệt danh này cũng không tồi."
  },
  AvgDialog_71991_Content_32 = {
    Text = "Tuy nhiên, trong thế giới không phải là cà đa sác, chúng ta không cần phải tránh né tất cả những gì liên quan đến ánh mắt của Ngài."
  },
  AvgDialog_71991_Content_33 = {
    Text = "Không phải thế giới của cà đa sác.."
  },
  AvgDialog_71991_Content_34 = {
    Text = "Có thể bạn còn nhiều thắc mắc, nhưng chuyện phiếm đến đây là vừa đủ. Nếu còn nói thêm, chúng ta sẽ không kịp đến nhà thờ trước khi trời tối."
  },
  AvgDialog_71991_Content_4 = {
    Text = "Có phải cái đầu lớn hồng nhạt kia bảo vệ bạn là đủ rồi không?"
  },
  AvgDialog_71991_Content_6 = {
    Text = "Tóm lại, cuối cùng chỉ còn hai chúng ta phụ trách nhiệm vụ đột vây."
  },
  AvgDialog_71991_Content_7 = {
    Text = "Mục tiêu là loại bỏ dị biến thể bị hòa tan dưới tháp chuông, đi đến thánh đường từ thiện ở khu Tây và yêu cầu sự hỗ trợ của Salvador."
  },
  AvgDialog_71991_Content_8 = {
    Text = "Hãy nhân cơ hội này, kể cho tôi nghe tất cả những điều bạn biết về tôi trước khi tôi mất trí nhớ, rõ ràng và đầy đủ."
  },
  AvgDialog_71991_Content_9 = {
    Text = "Bạn gọi môi trường này là \"tận dụng cơ hội\", chẳng phải quá nhẹ nhàng hay sao?!"
  },
  AvgDialog_71992_Content_1 = {
    Text = "Trong cơn mưa"
  },
  AvgDialog_71992_Content_10 = {
    Text = "Cô ấy cũng không đưa dữ liệu thí nghiệm cho tôi."
  },
  AvgDialog_71992_Content_100 = {
    Text = "Bạn nhấn vào huy hiệu, một tiếng động nhẹ nhàng vang lên, báo hiệu rằng liên lạc đã được kết nối."
  },
  AvgDialog_71992_Content_101 = {
    Text = "Ê ê, liên kết ổn định không?"
  },
  AvgDialog_71992_Content_102 = {
    Text = "Tan chảy·đóa, bạn…"
  },
  AvgDialog_71992_Content_103 = {
    Text = "Hãy biết ơn sâu sắc."
  },
  AvgDialog_71992_Content_104 = {
    Text = "Để bạn, chó con đáng thương bị ướt mưa, không cảm thấy quá cô đơn, trong chuyến hành trình sắp tới, khi cần sự hỗ trợ, bạn có thể liên lạc với tôi qua chiếc máy liên lạc này."
  },
  AvgDialog_71992_Content_105 = {
    Text = "Hãy bắt đầu hành trình."
  },
  AvgDialog_71992_Content_106 = {
    Text = "Lần này…… sự hủy diệt là người bạn đồng hành của bạn."
  },
  AvgDialog_71992_Content_11 = {
    Text = "Đúng như vậy."
  },
  AvgDialog_71992_Content_12 = {
    Text = "Bạn có nhớ không, lúc đầu tôi chưa cung cấp cho bạn \"con đường tắt\" này để trở lại phòng thí nghiệm?"
  },
  AvgDialog_71992_Content_13 = {
    Text = "Vì chọn con đường tắt, nên phải trả giá cho điều đó."
  },
  AvgDialog_71992_Content_14 = {
    Text = "Chỉ cần xác nhận con \"đường tắt\" này, tôi chắc chắn sẽ bước lên con đường phải đi, buộc mình trở lại thành người theo đuổi sự hủy diệt."
  },
  AvgDialog_71992_Content_15 = {
    Text = "Và cuộc đối đầu với \"bản thân\"... nghe đến bây giờ vẫn rất ngu ngốc, không xứng với danh hiệu \"thiên tài\" liều lĩnh."
  },
  AvgDialog_71992_Content_16 = {
    Text = "Nhưng nếu tôi đã đọc báo cáo này, có lẽ sẽ không đứng bên bạn kiên định như thế."
  },
  AvgDialog_71992_Content_17 = {
    Text = "Tóm lại, bản thảo này giao cho bạn."
  },
  AvgDialog_71992_Content_18 = {
    Text = "Hãy đánh giá trạng thái tinh thần của bạn trước khi đọc."
  },
  AvgDialog_71992_Content_19 = {
    Text = "Bạn lấy lại bình tĩnh, mở rộng bản thảo có viền vàng ố."
  },
  AvgDialog_71992_Content_2 = {
    Text = "Ba ngày sau"
  },
  AvgDialog_71992_Content_20 = {
    Text = "\"Nghiên cứu về sự phối hợp chuyển động của mắt trong Toghuva-po\""
  },
  AvgDialog_71992_Content_21 = {
    Text = "Mục tiêu thí nghiệm:\nThông qua phương pháp định lượng và định tính, quan sát và ghi chép phản ứng của Tohuwabohu đối với mục tiêu linh hồn cao trong tầm nhìn, xác thực quy luật theo dõi chuyển động của các mục tiêu linh hồn cao.\nThí nghiệm này nhằm làm sáng tỏ đặc điểm thị giác của Tohuwabohu và cơ chế phản ứng của nó đối với các mục tiêu linh hồn cụ thể."
  },
  AvgDialog_71992_Content_22 = {
    Text = "Bối cảnh thí nghiệm:\nTheo tài liệu lịch sử và ghi chép thí nghiệm trước đây(xem \"Nghiên cứu nguyên nhân của hiện tượng phân rã\"), cái nhìn của Tohuwabohu có thể gây ra hiện tượng phân rã, nhưng nguyên lý bắt mục tiêu của Tohuwabohu vẫn chưa được làm sáng tỏ.\nNghiên cứu nguyên lý chuyển động đồng bộ của cái nhìn Tohuwabohu có thể giúp chúng ta tìm kiếm cách tồn tại của thế giới hiện tại tốt hơn."
  },
  AvgDialog_71992_Content_23 = {
    Text = "Vật liệu thí nghiệm:\n1. 7 loại vật liệu linh hồn với độ mạnh khác nhau mỗi loại 1 phần;\n2. Thiết bị và nhiên liệu xuyên không gian 9 phần;\n3. Bảng ghi chép dữ liệu thí nghiệm"
  },
  AvgDialog_71992_Content_24 = {
    Text = "Phương pháp thí nghiệm:\n1. Thiết lập môi trường thí nghiệm: Lọc không gian có biến động chỉ số linh hồn tương đối ổn định và gần nhau;\n2. Quy trình thí nghiệm:\n① Lần lượt đưa vật liệu thí nghiệm có chỉ số linh hồn khác nhau vào các không gian.\n② Thâm nhập vào tổ chức chống đối phân rã địa phương, thường là Đại học Mythag, thu thập dữ liệu tần suất bùng nổ phân rã của từng không gian.\n③ Sử dụng bạc linh hồn thấp để truyền dữ liệu đến cơ thể nhân tạo số 279.\n④ Sắp xếp dữ liệu và tiến hành phân tích."
  },
  AvgDialog_71992_Content_26 = {
    Text = "Trong báo cáo thứ hai, việc luân phiên đưa các vật liệu thí nghiệm vào từng chiều đã chuyển thành việc kích hoạt bảy cơ thể nhân tạo để tiến hành đồng thời."
  },
  AvgDialog_71992_Content_27 = {
    Text = "Trong báo cáo thứ ba, giá trị của những nguyên liệu mang tính linh thiêng đã có sự thay đổi."
  },
  AvgDialog_71992_Content_29 = {
    Text = "Bản thảo cuối cùng, chữ viết trở nên rất lộn xộn."
  },
  AvgDialog_71992_Content_3 = {
    Text = "Tôi đã tìm hiểu tất cả các ghi chú còn lại hiện tại, tôi xin lỗi phải thông báo cho bạn hai điều.\nĐầu tiên, tấm bảng đá mà B-68 nói tới đã biến mất."
  },
  AvgDialog_71992_Content_30 = {
    Text = "Không có ý nghĩa.\nTôi đang khám phá một kết quả vô nghĩa. \nSinh vật linh tinh bản thân đã là mục tiêu bắt giữ của Ngài, những sinh vật có chỉ mục gnostic lớn hơn 21 sẽ bị sự chú ý của Ngài thu hút và ảnh hưởng đến những sinh tồn khác xung quanh.\nSự rò rỉ của báo cáo này cuối cùng chỉ dẫn đến những kết cục khủng khiếp hơn: đo đạc chỉ mục gnostic, sàng lọc, bắt giữ và truy sát."
  },
  AvgDialog_71992_Content_31 = {
    Text = "Điều đáng sợ hơn, không chỉ con người có thể phát hiện chỉ mục gnostic — nhiều loài sinh vật biển trong toàn bộ quần thể có chỉ mục gnostic cao hơn 21.\nTrừ khi san phẳng toàn bộ vùng biển... nhưng đó cũng là một cái kết không ai sống sót."
  },
  AvgDialog_71992_Content_32 = {
    Text = "Mọi giải pháp đều là ảo vọng, Ánh mắt của Ngài vĩnh cửu giáng lâm."
  },
  AvgDialog_71992_Content_33 = {
    Text = "Không ai có thể được cứu rỗi."
  },
  AvgDialog_71992_Content_34 = {
    Text = "Sự tồn tại ngắn ngủi của các ngươi không phải là kết quả của sự hy sinh cá nhân của ngươi, cũng không phải là do lòng từ bi nhất thời của hắn, mà chỉ đơn giản là vì hắn có chút tò mò thoáng qua đối với những phân mảnh của mình mà thôi."
  },
  AvgDialog_71992_Content_35 = {
    Text = "Anh ta nín thở, dồn sự chú ý vào những mảnh vỡ của mình và quên mất việc thở trong khoảnh khắc đó…"
  },
  AvgDialog_71992_Content_36 = {
    Text = "Bạn cứ nghĩ rằng nguy cơ đã kết thúc, câu chuyện cũng đã đến hồi kết, hoàng tử và công chúa sống một cuộc đời hạnh phúc mãi mãi về sau."
  },
  AvgDialog_71992_Content_37 = {
    Text = "Ngu ngốc và buồn cười! Thật là ngu ngốc và buồn cười!"
  },
  AvgDialog_71992_Content_38 = {
    Text = "Bạn hoàn toàn không hiểu tôi đã biết gì! Tất cả những điều này đều là——"
  },
  AvgDialog_71992_Content_39 = {
    Text = "Bạn tỉnh dậy từ việc đọc báo cáo thí nghiệm, nhận ra mình đã ra mồ hôi lạnh đầm đìa."
  },
  AvgDialog_71992_Content_4 = {
    Text = "Thứ hai, mặc dù tôi đã phát hiện ra phương pháp mà tôi đã sử dụng để nhảy đến chiều không gian của bạn vào thời điểm đó, nhưng nó không thể áp dụng cho bạn."
  },
  AvgDialog_71992_Content_40 = {
    Text = "Đóa Meltdown, người từng kiêu ngạo không thểmột đời trước mặt bạn, thực chất chỉ là một nhà nghiên cứu cẩn trọng của Misaque."
  },
  AvgDialog_71992_Content_41 = {
    Text = "Chỉ là cô ấy đã sớm nhìn thấu bí mật của sự rỗng rỗng và sự thật tàn nhẫn không thể tránh khỏi."
  },
  AvgDialog_71992_Content_42 = {
    Text = "Sự hy sinh anh dũng của bạn không thể đảm bảo hòa bình và thịnh vượng lâu dài cho thế giới."
  },
  AvgDialog_71992_Content_43 = {
    Text = "Cuộc chiến của các người chưa kết thúc, cần cho Misaque và Ramona hiểu rõ sự thật này——"
  },
  AvgDialog_71992_Content_44 = {
    Text = "Bạn phải trở về."
  },
  AvgDialog_71992_Content_45 = {
    Text = "Ngày tiễn biệt, mưa phùn nhẹ."
  },
  AvgDialog_71992_Content_46 = {
    Text = "Các khoảnh khắc quan trọng trong cuộc đời bạn dường như luôn đi kèm với cơn mưa phùn nhẹ nhàng."
  },
  AvgDialog_71992_Content_47 = {
    Text = "Trong ngày Akutê mở mắt, buổi lễ trao chìa khóa, hay ngày quyết định trở thành người bảo vệ cánh cửa…"
  },
  AvgDialog_71992_Content_48 = {
    Text = "Mỗi đêm mưa tĩnh lặng và thanh bình, bạn đều lo lắng cuộc đời mình có thể bất ngờ đón nhận một bước ngoặt mới."
  },
  AvgDialog_71992_Content_49 = {
    Text = "Bạn nhớ lại lời từ biệt với Meltdown·đóa."
  },
  AvgDialog_71992_Content_5 = {
    Text = "Nói một cách đơn giản, sự tương đồng cao giữa các nghĩa thể đã khiến việc chuyển đổi ý thức có thể thực hiện, nhưng trong thế giới đó không còn thân thể đủ phù hợp với bạn."
  },
  AvgDialog_71992_Content_50 = {
    Text = "Tôi sẽ ở lại trong phòng thí nghiệm. Dừng lại không phải là câu trả lời, có lẽ một ngày nào đó tôi sẽ lặp lại cùng một sự điên rồ."
  },
  AvgDialog_71992_Content_51 = {
    Text = "Nhưng, trước khi đạt đến sự thật tuyệt đối, dù cận kề ô nhiễm hủy diệt, tôi cũng phải tiếp tục nghiên cứu của mình bằng mọi giá."
  },
  AvgDialog_71992_Content_52 = {
    Text = "Đây mới giống như búp bê mà tôi biết... \nKhông, vẫn có chút gì đó khác biệt."
  },
  AvgDialog_71992_Content_53 = {
    Text = "Các bạn có nỗi ám ảnh bề ngoài khác biệt hoàn toàn, nhưng bản chất thì hoàn toàn giống nhau."
  },
  AvgDialog_71992_Content_54 = {
    Text = "Nhưng ít nhất, bây giờ cô ấy bớt điên cuồng và đáng sợ hơn so với trước đây."
  },
  AvgDialog_71992_Content_55 = {
    Text = "Chiếc ghim ngực này, cô ấy bảo tôi đưa cho bạn. Tôi sẽ gắn nó lên áo cho bạn."
  },
  AvgDialog_71992_Content_56 = {
    Text = "Wenkel đính một chiếc huy hiệu lên ngực của bạn."
  },
  AvgDialog_71992_Content_57 = {
    Text = "Wenkel… Dọc đường đi, bạn đã giúp đỡ tôi rất nhiều. Vậy mà tôi thậm chí còn chưa kịp bày tỏ lòng biết ơn của mình."
  },
  AvgDialog_71992_Content_58 = {
    Text = "Cảm ơn bạn, Wenkel. Cảm ơn bạn đã trở thành người bạn đầu tiên của tôi ở đây."
  },
  AvgDialog_71992_Content_59 = {
    Text = "Không cần khách sáo như vậy, tôi đã nghe đóa kể nhiều về bạn rồi. Khi tôi không thể đối thoại với bạn, bạn cũng đã biết đến một phiên bản khác của tôi rồi, phải không?"
  },
  AvgDialog_71992_Content_6 = {
    Text = "Còn một cách khác là thông qua não bộ và tái tạo thân thể, nhưng điều này cần dữ liệu phổ tần của ý thức bạn. Báo cáo thí nghiệm liên quan đã bị thất lạc."
  },
  AvgDialog_71992_Content_60 = {
    Text = "Dù tôi vẫn rất sợ hãi……\nNhưng trong vô thức có một giọng nói nói rằng, bạn sẽ mang đến ánh sáng cho tôi, cho thế giới này."
  },
  AvgDialog_71992_Content_61 = {
    Text = "Nhìn bên kia, đám đông tiễn đưa đã đến."
  },
  AvgDialog_71992_Content_63 = {
    Text = "Không đi, tôi không đi cảm ơn gã đó! \nChính tôi đã cứu mạng {Male=anh ấy,Female=cô ấy}, khi đào gã đó ra từ đống đá vụn!"
  },
  AvgDialog_71992_Content_64 = {
    Text = "Lắng nghe, Jenkin."
  },
  AvgDialog_71992_Content_65 = {
    Text = "Cảm ơn bạn đã giúp em gái tôi… Xin lỗi, tôi và Jenkin không có nhiều \"tài sản\".\nDải ruy băng này, hãy để tôi chuyển cho bạn như một kỷ niệm."
  },
  AvgDialog_71992_Content_66 = {
    Text = "Cô ấy buộc một dải lụa đỏ tươi vào cổ tay bạn."
  },
  AvgDialog_71992_Content_67 = {
    Text = "Chị gái!"
  },
  AvgDialog_71992_Content_68 = {
    Text = "Tôi không thể nhận…"
  },
  AvgDialog_71992_Content_69 = {
    Text = "Không cần từ chối, tôi biết rằng ngài và bà Đóa Nhĩ đã cung cấp cho đền thánh một lượng lớn tài nguyên bạc tâm, đủ để Giám mục Salvador có thể duy trì trong một thời gian rất dài."
  },
  AvgDialog_71992_Content_7 = {
    Text = "Có cách nào lấy lại được không?"
  },
  AvgDialog_71992_Content_70 = {
    Text = "Tôi có thể thấy ánh sáng của linh hồn bạn, như ánh lửa lay động, mặc dù còn chưa vững chắc, nhưng rực rỡ và dịu dàng."
  },
  AvgDialog_71992_Content_71 = {
    Text = "Lễ tế Salvador… Nếu tôi tìm thấy cách giải quyết cuộc khủng hoảng, tôi sẽ vội vàng đến đền thánh ngay."
  },
  AvgDialog_71992_Content_72 = {
    Text = "Tôi tin tưởng bạn, sứ giả mang sắc trắng u sầu. Một ngày nào đó, bạn sẽ mang đến sự cứu rỗi và hy vọng cho những người đang chịu khổ đau trong đền thánh."
  },
  AvgDialog_71992_Content_74 = {
    Text = "Tạm biệt mọi người, bạn hít một hơi sâu không khí mát mẻ của những giọt mưa.\nMột góc phố, bóng dáng đột ngột xuất hiện trong tầm mắt đã thu hút sự chú ý của bạn."
  },
  AvgDialog_71992_Content_75 = {Text = "!"},
  AvgDialog_71992_Content_76 = {
    Text = "Ông kia, xin vui lòng đợi một chút!"
  },
  AvgDialog_71992_Content_77 = {
    Text = "Áo choàng khẽ lay động, người đàn ông tóc vàng dường như đang cố tránh né sự truy đuổi của bạn, bất ngờ tăng tốc bước chân."
  },
  AvgDialog_71992_Content_78 = {
    Text = "……William, có phải là cậu không…… William!"
  },
  AvgDialog_71992_Content_79 = {
    Text = "Bạn không kịp suy nghĩ nhiều, bước chân từ đi nhanh tăng tốc lên chạy hết tốc lực, hình bóng của từng con phố liên tiếp lướt qua trước mắt."
  },
  AvgDialog_71992_Content_8 = {
    Text = "Có, nhưng cũng có những rủi ro không thể chấp nhận được — tôi phải mạo hiểm đồng bộ hóa tư duy của mình với phiên bản đầy đủ của Meltdown·đóa."
  },
  AvgDialog_71992_Content_81 = {
    Text = "……………"
  },
  AvgDialog_71992_Content_82 = {Text = "Hà, hà.."},
  AvgDialog_71992_Content_83 = {
    Text = "Oxy loãng không đủ để đáp ứng nhu cầu thiếu oxy của phổi, bạn hít thở gấp, dòng máu lưu thông giúp não bộ khôi phục một phần khả năng suy nghĩ."
  },
  AvgDialog_71992_Content_84 = {
    Text = "……Trời lúc nào tối xuống?"
  },
  AvgDialog_71992_Content_85 = {
    Text = "Phố Southwark……số 44……"
  },
  AvgDialog_71992_Content_86 = {
    Text = "Lần trước, vào thời khắc này, bên cạnh bạn là người đồng đội quan trọng nhất."
  },
  AvgDialog_71992_Content_87 = {
    Text = "Đại lộ Southwark nằm ở Tây Khu.\nCó vẻ như lần này, chúng ta có thể tận mắt chứng kiến phong cách của điều tra viên nổi tiếng William."
  },
  AvgDialog_71992_Content_88 = {
    Text = "Ông ấy đã ra quân rồi…"
  },
  AvgDialog_71992_Content_89 = {
    Text = "Nhưng bây giờ, bên cạnh bạn chẳng còn ai."
  },
  AvgDialog_71992_Content_9 = {
    Text = "Nói cách khác, tôi sẽ trở thành nguồn gốc đối địch với bạn."
  },
  AvgDialog_71992_Content_90 = {
    Text = "Đây là hành trình đối đầu với sự rỗng rỗng."
  },
  AvgDialog_71992_Content_91 = {
    Text = "Người giữ bí mật, bạn là đặc biệt. Vì vậy, bạn không nên dừng lại ở đây."
  },
  AvgDialog_71992_Content_92 = {
    Text = "Chúng ta phải cứu giúp, phải thay đổi. \nNhưng, dù cuối cùng chẳng đạt được gì…"
  },
  AvgDialog_71992_Content_93 = {
    Text = "Trước khi đêm sâu kia đến, khi mọi thứ đều bị lãng quên, hãy dùng đôi mắt của bạn để chứng kiến và giữ gìn ký ức về mọi điều đã xảy ra."
  },
  AvgDialog_71992_Content_94 = {
    Text = "Tôi sẽ làm được.\nRamona, chờ tôi trở lại."
  },
  AvgDialog_71992_Content_95 = {
    Text = "Sau khi lấy lực lượng từ ký ức để hỗ trợ tâm hồn, bạn đã sẵn sàng đối mặt với hành trình cô đơn này."
  },
  AvgDialog_71992_Content_96 = {
    Text = "Tiến lên."
  },
  AvgDialog_71992_Content_97 = {
    Text = "Nguyện Chìa Khóa Bạc soi sáng con đường phía trước."
  },
  AvgDialog_71992_Content_98 = {
    Text = "Drip, drip——"
  },
  AvgDialog_71992_Content_99 = {
    Text = "Meltdown·đóa chế tạo, chiếc ghim cài ngực mà Wenkel đeo cho bạn ở ngực bỗng nhiên kêu vang lên."
  },
  AvgDialog_71993_Content_1 = {
    Text = "Người rỗng"
  },
  AvgDialog_71993_Content_10 = {
    Text = "……Thần Cha, xin ban cho những người gặp nạn sự an bình và giải thoát, xoa dịu những linh hồn đau khổ."
  },
  AvgDialog_71993_Content_11 = {
    Text = "Nguyện đôi tay chữa lành của bạn đến với những người chịu đau khổ, nguyện ánh sáng của sự tồn tại của bạn xua tan nỗi sợ hãi tối tăm bao trùm linh hồn chúng tôi."
  },
  AvgDialog_71993_Content_12 = {
    Text = "Ho, ho! ——"
  },
  AvgDialog_71993_Content_13 = {
    Text = "Thân thể của bạn gần như trong suốt rồi."
  },
  AvgDialog_71993_Content_14 = {
    Text = "Yu Li-ét… Đấng Tối Cao sẽ bao dung mọi tội lỗi, nhưng trước khi bạn có chút hối hận về việc thực hiện nghi lễ dị giáo, việc xuất hiện tại đền thánh có lẽ không phải là điều phù hợp."
  },
  AvgDialog_71993_Content_15 = {
    Text = "Cuối cùng vẫn không thể nhìn rõ thực tế sao? Dù là \"phúc lành\" hay \"bảo hộ\", tất cả những gì bạn làm chỉ là đang đốt cháy chính mình."
  },
  AvgDialog_71993_Content_16 = {
    Text = "Thần cha của ngươi không thể làm cho đôi mắt ngươi sáng lại, cũng không thể chữa khỏi bệnh tật trên thân thể ngươi."
  },
  AvgDialog_71993_Content_17 = {
    Text = "Nếu tiếp tục như vậy, cậu sẽ ngã xuống trước những người yếu đuối đang ở trong nhà thờ kia đấy."
  },
  AvgDialog_71993_Content_18 = {
    Text = "Hãy đi cùng tôi, tôi sẽ tìm cách chữa trị cho bạn."
  },
  AvgDialog_71993_Content_19 = {
    Text = "Nếu tôi rời khỏi đền thánh, tất cả bệnh nhân ở đây sẽ bị nuốt chửng. Thần không nỡ lòng thấy con dân của Người phải chịu kiếp nạn này."
  },
  AvgDialog_71993_Content_2 = {
    Text = "Trước đền thánh cứu thế"
  },
  AvgDialog_71993_Content_20 = {
    Text = "Dù có gắng gượng thêm mười ngày nửa tháng, sau khi linh tính của bạn cạn kiệt, họ cũng chỉ có thể tự tìm đường sống."
  },
  AvgDialog_71993_Content_21 = {
    Text = "Và phần lớn trong số họ… xin hãy hiểu cho tôi, họ thậm chí không thể rời khỏi phòng của mình."
  },
  AvgDialog_71993_Content_22 = {
    Text = "Yu Li-ét với đôi mắt cuồng nhiệt nhìn chằm chằm vào Salvador, thấy anh lặng im tay đặt lên áo choàng giáo sĩ, cô nở một nụ cười rực rỡ nhưng đầy giả tạo."
  },
  AvgDialog_71993_Content_23 = {
    Text = "Thà rằng chọn nơi đây làm bãi tha ma mới cũng tốt, được an nghỉ trong vòng tay của thần linh, há chẳng phải là một sự trở về đầy thành kính sao?"
  },
  AvgDialog_71993_Content_24 = {
    Text = "Mở mắt ra mà xem, cả thành phố đã sụp đổ, những việc bạn làm chỉ như giọt nước trong đại dương mà thôi."
  },
  AvgDialog_71993_Content_25 = {
    Text = "Thần Cha ban cho mỗi người cơ hội bình đẳng, họ cứ sống thêm một ngày thì khả năng được cứu càng lớn."
  },
  AvgDialog_71993_Content_26 = {
    Text = "Sứ giả nhợt nhạt vẫn chưa đến, nhưng sự cứu chuộc cho thế gian vẫn còn hy vọng."
  },
  AvgDialog_71993_Content_27 = {
    Text = "Đừng đùa nữa, thưa Đức Giám mục! <Yellow:《kinh điển》> chỉ toàn là những lời nói dối hoang đường!"
  },
  AvgDialog_71993_Content_28 = {
    Text = "Thời kỳ cuối cùng đã đến, không ai có thể cứu vãn thế giới này!"
  },
  AvgDialog_71993_Content_29 = {
    Text = "Nếu bạn vẫn cứng đầu không tỉnh ngộ, tôi buộc phải áp dụng biện pháp quyết liệt."
  },
  AvgDialog_71993_Content_3 = {
    Text = "Bạn có chắc đây chính là nơi trú ẩn bạn đang tìm kiếm?"
  },
  AvgDialog_71993_Content_30 = {
    Text = "Từ cửa sổ hoa văn của nhà thờ, từ dưới ghế dài, từ sau cánh cửa, lặng lẽ xuất hiện vài dáng người cao lớn của đám tín đồ cầm đèn."
  },
  AvgDialog_71993_Content_31 = {
    Text = "Giám mục Salvador!"
  },
  AvgDialog_71993_Content_32 = {
    Text = "Hình bóng của cậu thiếu niên lao vào cửa đền thánh, theo sau là hai bóng dáng bị ánh sáng ban mai kéo dài, chậm rãi quan sát xung quanh và tiến bước."
  },
  AvgDialog_71993_Content_33 = {
    Text = "Trong cuộc đối mặt đó, ánh mắt của bạn đã xuyên qua những tín đồ ánh sáng đền thờ, nhìn thẳng vào Salvador.\nÁnh sáng cửa ra đã bao phủ khuôn mặt anh một lớp ánh sáng dịu dàng và thiêng liêng, bạn cảm thấy ánh mắt của anh dưới băng quấn đang chạm vào bạn."
  },
  AvgDialog_71993_Content_34 = {
    Text = "Anh cúi đầu, khóe môi nhếch lên một độ cong khó nhận thấy, đưa tay chạm vào vị trí trái tim, lời cầu nguyện trầm ấm mang đầy lòng trắc ẩn và sự ấm áp."
  },
  AvgDialog_71993_Content_35 = {
    Text = "\"Sẽ có bóng tối vô biên bao trùm thế giới, và linh hồn mang ánh sáng ấm áp nhưng mỏng manh sẽ trở thành sứ giả của hy vọng. {Male=anh ấy,Female=cô ấy} sẽ thắp lên ngọn lửa trắng thuần khiết, soi sáng con đường phía trước.\""
  },
  AvgDialog_71993_Content_36 = {
    Text = "Tôi đã cảm nhận được nhiệt độ của linh hồn bạn… sứ giả tái nhợt."
  },
  AvgDialog_71993_Content_38 = {
    Text = "Tôi còn nghĩ chúng tôi đến đây để xin giúp đỡ. Không phải là muốn tôi thấy chuyện bất bình thì ra tay giúp đỡ chứ."
  },
  AvgDialog_71993_Content_39 = {
    Text = "Yu Li-ét…"
  },
  AvgDialog_71993_Content_4 = {
    Text = "Tình cảnh ở đây rất giống với tháp chuông của trại tế bần. Dù không thể nói là y hệt, nhưng ít nhất cũng rất tương đồng…"
  },
  AvgDialog_71993_Content_40 = {
    Text = "Ồ? Bạn biết tôi?"
  },
  AvgDialog_71993_Content_41 = {
    Text = "Tôi chưa từng thấy mặt bạn. Nhưng có vẻ như, ở đây không còn đủ thời gian và không gian để chúng ta ngồi xuống tự giới thiệu."
  },
  AvgDialog_71993_Content_42 = {
    Text = "Không… cô ấy không phải là đối tượng có thể đàm phán… Chuẩn bị chiến đấu."
  },
  AvgDialog_71993_Content_43 = {
    Text = "Xem ra anh cũng khá hiểu phong cách của tôi. Nếu vậy, tôi có chút hứng thú muốn hỏi về nguồn của anh."
  },
  AvgDialog_71993_Content_5 = {
    Text = "Một lượng lớn thể dị biến rỗng đã bao vây toàn bộ nhà thờ……"
  },
  AvgDialog_71993_Content_6 = {
    Text = "Đợi chút, cái phía trước là…"
  },
  AvgDialog_71993_Content_7 = {
    Text = "Dừng lại! Cấm cản đường hiệp sĩ!"
  },
  AvgDialog_71993_Content_8 = {
    Text = "Hình dáng nhỏ bé mở rộng lá chắn màu đen, hướng về phía các bạn."
  },
  AvgDialog_71993_Content_9 = {
    Text = "Các người! Có phải các người là người sống sót không? Nhanh vào đây với tôi!"
  },
  AvgDialog_71994_Content_1 = {
    Text = "Khoảng không gian ý thức hoàn toàn sụp đổ, khói bụi ảo ảnh rơi từng lớp, hiện ra trước mặt các người vẫn là phòng thí nghiệm ban đầu."
  },
  AvgDialog_71994_Content_2 = {
    Text = "Tại sao không chịu tiếp nhận? Có thể chôn vùi trong khe hở của chiều, mãi mãi không cần phải chịu sự thanh tẩy từ ánh mắt của \"Ngài\"."
  },
  AvgDialog_71994_Content_3 = {
    Text = "Đây là vinh dự như thế nào, ân huệ như thế nào!"
  },
  AvgDialog_71994_Content_4 = {
    Text = "Tiếc thay, tiếc thay, bây giờ chỉ còn lại tôi phải tự tay… để thành phố lạnh lẽo này, đã bị xóa sổ…"
  },
  AvgDialog_71994_Content_5 = {
    Text = "Trở thành nơi chôn vùi các ngươi!"
  },
  AvgDialog_71995_Content_1 = {
    Text = "Không gian hỗn loạn đi kèm với những đường nét méo mó, trong chớp mắt đã nuốt chửng toàn bộ phòng thí nghiệm."
  },
  AvgDialog_71995_Content_2 = {
    Text = "Ánh sáng mất kiểm soát trải ra trước mặt các bạn, một đàn thú không thể nhận diện bị nhấn chìm trong bóng tối bao vây hai người các bạn."
  },
  AvgDialog_71995_Content_3 = {
    Text = "Chào mừng đến với ruộng thí nghiệm của tôi, địa điểm tàn sát của tôi."
  },
  AvgDialog_71995_Content_4 = {
    Text = "Lên nào, các con yêu quý. Hãy cho những kẻ không biết điều này một bài học."
  },
  AvgDialog_71996_Content_10 = {
    Text = "Tôi không còn nghi ngờ gì nữa, đây chính là phòng thí nghiệm của tôi."
  },
  AvgDialog_71996_Content_11 = {
    Text = "Còn nhớ không? Tôi đã từng nói với bạn rằng chúng ta có thể đi \"đường tắt\"."
  },
  AvgDialog_71996_Content_12 = {
    Text = "Đường tắt đó chính là \"đánh cắp\"."
  },
  AvgDialog_71996_Content_13 = {
    Text = "Trộm cắp?"
  },
  AvgDialog_71996_Content_14 = {
    Text = "Đánh cắp.\nĐánh cắp thành quả nghiên cứu của \"tôi\"."
  },
  AvgDialog_71996_Content_15 = {
    Text = "Tôi không biết vụ nổ mà bạn gây ra có quy mô như thế nào, nhưng tôi có thói quen lưu trữ một cách cẩn trọng các kết quả nghiên cứu quan trọng."
  },
  AvgDialog_71996_Content_16 = {
    Text = "Chỉ cần khả năng chui tường và lục lọi của con chuột nhỏ này đạt đến mức không gì có thể cản nổi, nó có thể đào ra các bản ghi từ đống đổ nát, từ đó rút ngắn đáng kể thời gian nghiên cứu tiếp theo của tôi."
  },
  AvgDialog_71996_Content_17 = {
    Text = "Được rồi, dọn dẹp chướng ngại vật trên đường đến di tích phòng thí nghiệm."
  },
  AvgDialog_71996_Content_2 = {
    Text = "Này, người Tây Khu, sáng sớm đã kéo tôi ra khỏi giấc mơ đẹp, các người định đưa tôi đi đâu?"
  },
  AvgDialog_71996_Content_3 = {
    Text = "Tôi đang ngủ ngon lành, mơ thấy mình biến thành một con chuột nhỏ, đi trên cây cầu treo, xung quanh đầy mùi thơm ngậy dễ chịu, rất nhanh mũi tôi sắp chạm vào miếng phô mai ngon nhất rồi——"
  },
  AvgDialog_71996_Content_4 = {
    Text = "Rầm một cái, bạn dùng gối đánh thức tôi dậy rồi."
  },
  AvgDialog_71996_Content_5 = {
    Text = "May mắn là đã gọi bạn dậy. Đó là một trong những loại bẫy chuột phổ biến và hiệu quả nhất mà bạn mơ thấy."
  },
  AvgDialog_71996_Content_6 = {
    Text = "Dưới cầu khỉ là một thùng nước cao hơn một mét, mùi hương bạn ngửi thấy là mùi được thoa lên các bình chứa trong suốt và trên cầu khỉ dưới chân."
  },
  AvgDialog_71996_Content_7 = {
    Text = "Chỉ cần bạn vừa đặt chân lên, sẽ ngay lập tức trượt chân rơi vào vực thẳm không thể cứu vãn."
  },
  AvgDialog_71996_Content_8 = {
    Text = "Muốn làm một con chuột tự do tự tại, bạn còn phải thông minh hơn nữa."
  },
  AvgDialog_71996_Content_9 = {
    Text = "Đóa, mục tiêu của chúng ta là…?"
  },
  AvgDialog_71997_Content_1 = {
    Text = "Vào khoảnh khắc dị thể rỗng tan biến với tiếng kêu thê lương, bốn người vừa chiến đấu bên bạn quay lại mỉm cười."
  },
  AvgDialog_71997_Content_10 = {
    Text = "Có thể, nhưng liên kết vượt qua chiều không gian đủ để đè bẹp thân thể này của bạn.\nTrong trường hợp không cần thiết, tôi không khuyên bạn nên làm như vậy."
  },
  AvgDialog_71997_Content_11 = {
    Text = "Bạn cố gắng tập trung hồi tưởng, nhưng trong tâm trí vẫn chưa hình thành được hình dáng, bánh răng tư duy đã hỏng hóc và ngừng lại."
  },
  AvgDialog_71997_Content_12 = {
    Text = "Mi mắt bạn nặng như khối chì, cảm giác ngạt thở như sương mù dày đặc bao trùm tâm trí."
  },
  AvgDialog_71997_Content_13 = {
    Text = "Đi theo tôi về phòng thí nghiệm, để chữa lành vết thương trên người bạn.\nNếu Dor phát hiện, tôi sẽ nói là do tôi làm."
  },
  AvgDialog_71997_Content_14 = {
    Text = "Đóa, mặc dù vậy, tôi có thể cảm nhận được rằng cô ấy về bản chất là một người trong sáng. Kỹ thuật chuyển dịch của cô ấy cũng rất tinh xảo, vượt xa phần lớn người trên hành tinh này."
  },
  AvgDialog_71997_Content_15 = {
    Text = "Bạn nhớ lại những hành động của Melt·đóa trong thế giới ban đầu, khó có thể tán thành."
  },
  AvgDialog_71997_Content_16 = {
    Text = "Nhưng tranh luận về đúng sai của Nhiệt Hủy·đóa với Wenkel hiện tại không có ý nghĩa. Điều quan trọng hơn là hiểu rõ thế giới này đã xảy ra điều gì, và làm cách nào để trở lại thế giới ban đầu."
  },
  AvgDialog_71997_Content_17 = {
    Text = "Chúng ta…… quay lại đi? Bên ngoài thực sự rất nguy hiểm……"
  },
  AvgDialog_71997_Content_18 = {
    Text = "Tay cô ấy đang khẽ siết chặt góc áo của bạn."
  },
  AvgDialog_71997_Content_19 = {
    Text = "Bạn nhìn về phía chân trời xa xăm, nơi vầng mặt trời tối tăm mờ ảo trong làn khói bụi, in ra một viền hình tròn mỏng manh, tựa như con ngươi héo úa đang lộ ra."
  },
  AvgDialog_71997_Content_2 = {
    Text = "Rồi bóng dáng dần dần mờ đi."
  },
  AvgDialog_71997_Content_20 = {
    Text = "Tôi sẽ đi theo bạn. Tôi có vấn đề muốn hỏi Đoã Nhĩ."
  },
  AvgDialog_71997_Content_3 = {
    Text = "Ngay sau đó, khuôn mặt lo lắng của Wenkel xuất hiện trước mặt bạn."
  },
  AvgDialog_71997_Content_4 = {
    Text = "Hà, hà... mệt quá, mệt chết tôi rồi."
  },
  AvgDialog_71997_Content_5 = {
    Text = "Không, đừng chạy lung tung… bên ngoài, rất nguy hiểm ."
  },
  AvgDialog_71997_Content_6 = {
    Text = "Bạn nhìn quanh bốn phía, xác nhận rằng hình bóng đã hoàn toàn biến mất, và mức độ mệt mỏi sau trận chiến còn cao hơn trước."
  },
  AvgDialog_71997_Content_7 = {Text = "Họ…"},
  AvgDialog_71997_Content_8 = {
    Text = "Là sự phản chiếu từ không gian ý thức của bạn. Tuy nhiên, theo như đóa nói, không gian ý thức của bạn đã bao gồm tất cả các thế giới chiều."
  },
  AvgDialog_71997_Content_9 = {
    Text = "Còn có thể gặp lại họ không?"
  },
  AvgDialog_71998_Content_2 = {
    Text = "Trời đất rung chuyển, trên bàn thí nghiệm gần tay liên tục lăn xuống các bình thủy tinh và ống nghiệm, tạo nên làn khói huyền ảo trên mặt đất."
  },
  AvgDialog_71998_Content_3 = {
    Text = "Sau đó, bàn thí nghiệm và kệ hóa chất liên tiếp đổ xuống, đồng hồ quả lắc treo tường cùng những món đồ trang trí cũng lung lay như sắp đổ."
  },
  AvgDialog_71998_Content_4 = {
    Text = "Động đất?!"
  },
  AvgDialog_71998_Content_5 = {
    Text = "Cái cứ điểm này cũng không trụ được nữa sao?"
  },
  AvgDialog_71998_Content_6 = {
    Text = "Xem ra tôi phải bị chôn ở đây cùng với chó con của Misaque. Có vui không? Hãy vẫy đuôi lên nào! Đây là vinh dự đặc biệt mà bạn hiếm khi được hưởng."
  },
  AvgDialog_71998_Content_7 = {
    Text = "Trước khi bạn trả lời, thế giới chìm vào bóng tối sụp đổ."
  },
  AvgDialog_71999_Content_1 = {
    Text = "Con đường chưa đi"
  },
  AvgDialog_71999_Content_10 = {
    Text = "Tùy thuộc vào những gì bạn đã làm trong khoảng thời gian này."
  },
  AvgDialog_71999_Content_11 = {
    Text = "Đang làm gì vậy? Tất nhiên là tiếp tục sự nghiệp vĩ đại của bạn, sự nghiệp vĩ đại của chúng ta, sự nghiệp thúc đẩy kết thúc!"
  },
  AvgDialog_71999_Content_12 = {
    Text = "Hãy đến đây, thân yêu, hãy chia sẻ niềm vui với tôi!\nTrong khoảng thời gian bạn rời đi, tôi đã đưa toàn bộ Kadath của sáu chiều không gian đến tận cùng!"
  },
  AvgDialog_71999_Content_13 = {
    Text = "Bạn và đóa cạnh nhìn nhau."
  },
  AvgDialog_71999_Content_14 = {
    Text = "Xem ra chúng ta không thể làm bạn được."
  },
  AvgDialog_71999_Content_15 = {
    Text = "Tiếc thay, tiếc thay! Thậm chí chính tôi cũng không thể hiểu được mong muốn của bản thân!"
  },
  AvgDialog_71999_Content_16 = {
    Text = "Vừa mới còn say sưa biểu diễn trên sân khấu opera, cô ấy đột nhiên dừng lại, ánh mắt nóng bỏng dường như muốn xuyên thấu bạn và Đóa bị Nóng Chảy bên cạnh."
  },
  AvgDialog_71999_Content_17 = {
    Text = "Chắc hẳn, bạn đã quên mọi thứ trên tấm bảng đá rồi phải không?"
  },
  AvgDialog_71999_Content_18 = {
    Text = "Sự im lặng của các người trở thành một lời đáp sâu sắc đối với sự thách thức từ những kẻ cuồng ngạo."
  },
  AvgDialog_71999_Content_19 = {
    Text = "Quả nhiên, quả nhiên! Vậy thì tốt, hãy coi đây là một cuộc diễn tập, cho con đường hủy diệt cuối cùng sẽ được tiết lộ!"
  },
  AvgDialog_71999_Content_2 = {
    Text = "\"Tôi\" cơ thể cải tiến của tôi có chế độ khởi động lại là, nếu bất kỳ cơ thể cải tiến nào mất liên lạc với não trung ương quá 24 giờ, cơ thể cải tiến dự phòng tiếp theo sẽ tự động khởi động."
  },
  AvgDialog_71999_Content_20 = {
    Text = "Bạn có biết không? Trong lòng tôi đang rực cháy một khao khát."
  },
  AvgDialog_71999_Content_21 = {
    Text = "Tôi khát khao truyền đạt cho thế gian tất cả những gì tấm bảng đá đã dạy tôi, tôi khát khao để họ nhận ra sự phi lý trong những điều họ đang theo đuổi."
  },
  AvgDialog_71999_Content_22 = {
    Text = "Không ai biết mình nhận được mọi thứ vì lý do gì, cũng không ai quan tâm đến số phận tất yếu của thế giới."
  },
  AvgDialog_71999_Content_23 = {
    Text = "Sự hủy diệt của thế giới đang cận kề, sức sống của mỗi người đều có thể kết thúc vào ngày mai, sự tồn tại của họ sẽ bị bóng đen tiêu thụ, mà những kẻ tầm thường lại cứ làm ngơ và không hay biết!"
  },
  AvgDialog_71999_Content_24 = {
    Text = "Và tôi đã thấy! Tôi đã thấy!"
  },
  AvgDialog_71999_Content_25 = {
    Text = "Dáng vẻ của cô ta càng thêm điên cuồng, càng thô to đập xuống mặt đất, tiếng giẫm đạp rùng rợn xuyên qua sàn gỗ gây sởn gai ốc."
  },
  AvgDialog_71999_Content_26 = {
    Text = "Vì vậy, dưới hình thức của cái chết, tôi ban tặng sự phi lý tương đương cho những kẻ tầm thường vàtê dại, trao cho họ quyền được nhận ra."
  },
  AvgDialog_71999_Content_27 = {
    Text = "Tôi trao cho họ bộ giáp đủ để chống lại lửa và điện, sau đó dùng chân kẹp sắc nhọn đâm thủng ngực họ"
  },
  AvgDialog_71999_Content_28 = {
    Text = "Tôi đã tặng hàng nghìn máy khai thác động đất cho người đi đường, những kẻ tham lam mù quáng tranh giành lãnh thổ khai thác, sự cộng hưởng gây ra động đất còn nhiều hơn cả số lần tôi tự tay kích nổ."
  },
  AvgDialog_71999_Content_29 = {
    Text = "Tôi sẽ nhét các ngươi, những kẻ gầm gừ, vào trong hòm chứa não, để các ngươi chỉ có thể ngồi bất động và héo hon, chứng kiến sự kinh hoàng đến."
  },
  AvgDialog_71999_Content_3 = {
    Text = "Vì vậy, sau sự cố tại phòng thí nghiệm, tôi đã ngất xỉu, cơ thể mới B-68 đã được khởi động.\nVà cơ thể này đã mất đi một phần ký ức, là một món đồ phế thải lẽ ra đã bị vứt bỏ."
  },
  AvgDialog_71999_Content_30 = {
    Text = "Đây chính là 「lựa chọn」 của 「tôi」 sao?"
  },
  AvgDialog_71999_Content_31 = {
    Text = "Quả thật quá yếu đuối. Tôi đã nghĩ rằng sự tồn tại liên kết với nguồn gốc có thể thông hiểu nhiều trí tuệ hơn, không ngờ bẫy của khoa học lại dẫn bạn đến con đường hoang đường tận cùng."
  },
  AvgDialog_71999_Content_32 = {
    Text = "Bạn có biết giá trị của bộ giáp sinh học không? Dù là ngọn lửa hay điện cũng không thể xuyên thủng, mặc nó đủ cho chúng ta bước vào tầng magma để khám phá bí ẩn sâu trong lòng đất."
  },
  AvgDialog_71999_Content_33 = {
    Text = "Máy khai thác động đất…… có thể thâm nhập vào lớp địa chất và khai thác bạc tâm bằng rung động tốc độ cao."
  },
  AvgDialog_71999_Content_34 = {
    Text = "Còn về bình chứa não bộ… Đó là để bảo quản những não bộ vô giá và kiến thức, suy nghĩ mà nó chứa đựng, không phải để tùy tiện chứa đựng những thứ rác rưởi."
  },
  AvgDialog_71999_Content_35 = {
    Text = "Hãy sử dụng họ chỉ để giải trí, giống như gã đó, thiếu hiểu biết và phung phí một cách đáng tiếc."
  },
  AvgDialog_71999_Content_36 = {
    Text = "Bạn đã chìm đắm trong một loại điên rồ khác quá lâu, một \"tôi\" khác."
  },
  AvgDialog_71999_Content_37 = {
    Text = "Con người vốn đã mở đường hướng tới tương lai trong quá trình tìm kiếm, nhưng ngươi lại tùy tiện cắt đứt mọi khả năng và hy vọng."
  },
  AvgDialog_71999_Content_38 = {
    Text = "Không có khả năng, cũng không có hy vọng!"
  },
  AvgDialog_71999_Content_39 = {
    Text = "Tất cả câu trả lời đều bị nhấn chìm trong bóng tối vĩnh cửu, tất cả các chiều tương tự hoặc khác biệt chỉ dẫn đến một kết cục duy nhất!"
  },
  AvgDialog_71999_Content_4 = {
    Text = "Nói cách khác, \"Melt·đóa\" trước mặt chúng ta mới là \"tôi\" hoàn chỉnh hơn."
  },
  AvgDialog_71999_Content_40 = {
    Text = "%player%. Hy vọng chỉ như liều thuốc độc khiến con người thêm đau khổ. Chỉ khi mọi thứ bị hủy diệt hoàn toàn và nhanh chóng, tất cả mới có thể thực sự được giải thoát."
  },
  AvgDialog_71999_Content_41 = {
    Text = "Càng sắc bén lấp lánh ánh kim lạnh giá được giơ cao, chỉ một tích tắc nữa thôi sẽ xuyên thủng sọ bạn."
  },
  AvgDialog_71999_Content_42 = {
    Text = "Vì bạn không muốn từ bỏ hy vọng thô kệch đó…"
  },
  AvgDialog_71999_Content_43 = {
    Text = "Hãy chuẩn bị đón nhận cái chết hoàn hảo và tàn nhẫn mà tôi dành cho các ngươi!"
  },
  AvgDialog_71999_Content_5 = {
    Text = "Bạn rất thông minh, không hổ là \"tôi\", B-67."
  },
  AvgDialog_71999_Content_6 = {
    Text = "Đồ giả đã bị loại bỏ cùng với chó con chạy trốn này trở lại phòng thí nghiệm, chắc chắn không phải là để tìm tôi nói chuyện cũ chứ?"
  },
  AvgDialog_71999_Content_7 = {
    Text = "Nếu tôi nói số hiệu của tôi đứng trước bạn, vậy phòng thí nghiệm này lẽ ra thuộc về tôi, chắc chắn bạn sẽ không đồng ý."
  },
  AvgDialog_71999_Content_8 = {
    Text = "Nhưng giữa chúng ta vẫn có thể đạt được hòa bình."
  },
  AvgDialog_71999_Content_9 = {
    Text = "Vậy, bạn có muốn tham gia cùng tôi không?"
  },
  AvgDialog_72000_Content_1 = {
    Text = "Cậu quả nhiên có vấn đề, sao mà nói không hợp là động thủ ngay vậy!!"
  },
  AvgDialog_72000_Content_10 = {
    Text = "Cô ấy cũng giống như chị gái, được đưa đi chữa bệnh bởi cậu thiếu gia giàu có mang theo một con rối kỳ quái."
  },
  AvgDialog_72000_Content_11 = {
    Text = "Tôi cũng đã nói với cô Clementine, nhưng cô Clementine nói rằng cậu chủ đã sắp xếp cho cô ấy tham gia một liệu pháp nghỉ dưỡng cao cấp, tạm thời chưa thể quay lại."
  },
  AvgDialog_72000_Content_12 = {
    Text = "Vậy… cô Sara, còn Diana thì sao?"
  },
  AvgDialog_72000_Content_13 = {
    Text = "Không biết. Trong viện tế bần đầy rẫy quái vật, không ai dám lại gần."
  },
  AvgDialog_72000_Content_14 = {
    Text = "Vâng, khi tôi được cô Clementine đưa từ khu vực phía Tây về, tôi phát hiện ra rằng quái vật ở khu vực phía Đông nhiều hơn rất nhiều so với khu vực phía Tây…"
  },
  AvgDialog_72000_Content_15 = {
    Text = "Trong viện tế bần càng thế."
  },
  AvgDialog_72000_Content_16 = {
    Text = "Hình ảnh của hai người hiện ra trước mắt bạn. Sara với dáng điệu khom lưng, nụ cười nhiệt tình; Ai Jī Sī rụt rè, không dám bộc lộ suy nghĩ."
  },
  AvgDialog_72000_Content_17 = {
    Text = "Sáng mai, tôi sẽ đi điều tra nhà tế bần."
  },
  AvgDialog_72000_Content_2 = {
    Text = "Máison có thể cảm nhận được, hai người đều là người tốt… làm ơn đừng làm khó nhau nữa được không?"
  },
  AvgDialog_72000_Content_3 = {
    Text = "Không, xem ra hai người này không thể cho tôi yên ổn sống ở đây được…"
  },
  AvgDialog_72000_Content_4 = {
    Text = "Vì vậy, tôi vẫn nên ra ngoài tạm lánh đi một thời gian."
  },
  AvgDialog_72000_Content_5 = {
    Text = "Cô ấy miệng nói rời đi, nhưng đột ngột tiến đến gần bạn, thì thầm bên tai."
  },
  AvgDialog_72000_Content_6 = {
    Text = "Còn gặp lại, mắt không có tròng."
  },
  AvgDialog_72000_Content_7 = {
    Text = "(Vì tình hình của Hiệp hội Điêu khắc gia và Rogers vẫn như trước, vậy nên...)"
  },
  AvgDialog_72000_Content_8 = {
    Text = "Jenkin, anh biết Ai Jī Sī ở đâu không?"
  },
  AvgDialog_72000_Content_9 = {
    Text = "Bạn còn nhớ Ai Jī Sī không?"
  },
  AvgDialog_72001_Content_1 = {
    Text = "(mắt trừng mồm há hốc)"
  },
  AvgDialog_72001_Content_11 = {
    Text = "Bạn đã đẩy cửa ra."
  },
  AvgDialog_72001_Content_12 = {
    Text = "Xuất hiện trước mặt bạn là căn hầm quen thuộc, nhưng không có thợ làm kẹo, không có nhà điêu khắc, cũng không có bàn thí nghiệm."
  },
  AvgDialog_72001_Content_13 = {
    Text = "Có một người phụ nữ đầu bù tóc rối, gầy đến mức lộ rõ từng chiếc xương."
  },
  AvgDialog_72001_Content_14 = {Text = "...ai.."},
  AvgDialog_72001_Content_15 = {
    Text = "Giọng nói khàn khàn, yếu ớt, như thể đang chịu đựng một cơn đau dữ dội.\nNhững ngón tay gầy guộc cố gắng lê lết trên mặt đất, kéo theo thân thể yếu ớt tiến lại gần các bạn."
  },
  AvgDialog_72001_Content_16 = {
    Text = "Là… con người……"
  },
  AvgDialog_72001_Content_17 = {Text = "Sara!"},
  AvgDialog_72001_Content_18 = {
    Text = "Uống từ từ, còn nhiều nước, không sao cả."
  },
  AvgDialog_72001_Content_19 = {Text = "Phì, phì"},
  AvgDialog_72001_Content_2 = {
    Text = "Bạn đã tiêu diệt hết tất cả những con quái vật đó?"
  },
  AvgDialog_72001_Content_20 = {
    Text = "Bạn đã ẩn náu trong hầm bao lâu?"
  },
  AvgDialog_72001_Content_21 = {
    Text = "Không đếm xuể……dù sao, cũng đã vượt quá hai mươi ngày."
  },
  AvgDialog_72001_Content_22 = {
    Text = "Đôi khi, tôi nghe thấy một giọng nói lẩm bẩm kỳ quái, đầu đau đến mức không thể chịu đựng được, thậm chí cảm thấy nó giống như sắp vỡ tung ra từ bên trong…"
  },
  AvgDialog_72001_Content_23 = {
    Text = "Khi tỉnh lại, đã không biết mất ý thức bao lâu……"
  },
  AvgDialog_72001_Content_24 = {
    Text = "Không có thức ăn, cũng không có nước…… Tôi luôn cảm thấy mình sắp chết.\nNhưng, chỉ cần nghĩ tới những đứa trẻ còn đang đợi tôi……"
  },
  AvgDialog_72001_Content_25 = {
    Text = "Sau hơn hai mươi ngày không ăn không uống mà vẫn còn sống, bạn không nghĩ rằng mình đang sống nhờ tình yêu thương vô bờ dành cho những đứa trẻ sao?"
  },
  AvgDialog_72001_Content_26 = {
    Text = "Bạn đang nói gì mà mỉa mai thế!"
  },
  AvgDialog_72001_Content_27 = {
    Text = "Xin lỗi nếu có gì không phải, các bạn, các bạn nên nhận thức được……"
  },
  AvgDialog_72001_Content_28 = {
    Text = "Bà Sara trước mắt các người đã không còn là con người bình thường nữa… Cô ấy là một thân thể được đánh thức chưa hoàn chỉnh."
  },
  AvgDialog_72001_Content_29 = {
    Text = "Đúng vậy, chỉ số gnostic của cô ấy dao động liên tiếp, không thể duy trì trên 21.\nNguyên lý vẫn chưa rõ, nhưng rõ ràng không phải là người đánh thức ổn định."
  },
  AvgDialog_72001_Content_3 = {
    Text = "Từ nay trở đi, bạn có thể tự do di chuyển trong trại tế bần."
  },
  AvgDialog_72001_Content_30 = {
    Text = "Và rõ ràng, thân thể của cô ấy sẽ không thể chịu đựng nổi sự chấn động từ bạc tâm bên trong nữa."
  },
  AvgDialog_72001_Content_31 = {
    Text = "Rất tiếc, nhưng cô ấy có lẽ sẽ không được gặp các con của mình nữa."
  },
  AvgDialog_72001_Content_32 = {
    Text = "Sự hủy diệt · đóa nụ cười giống như một tảng đá lớn, đè nặng lên ngực các người. \nKhông ai trả lời, sự im lặng trong không khí của nhà tế bần tạo nên một khoảng trống kéo dài."
  },
  AvgDialog_72001_Content_4 = {
    Text = "Nếu thấy người bị thương bên ngoài, hãy để họ nghỉ ngơi ở đây."
  },
  AvgDialog_72001_Content_5 = {
    Text = "Tôi sẽ đi xem hầm một chút.\nBạn hãy đừng lại gần."
  },
  AvgDialog_72001_Content_6 = {
    Text = "Bạn đứng trước cửa tầng hầm, thở một hơi thật sâu."
  },
  AvgDialog_72001_Content_7 = {
    Text = "Những ký ức trong quá khứ chạy qua trước mắt như cuộn phim."
  },
  AvgDialog_72002_Content_1 = {
    Text = "Ép cô ta lại!"
  },
  AvgDialog_72002_Content_10 = {
    Text = "Lời khuyên cô ấy đưa ra là từ đáy lòng, chân thành và đáng tin cậy."
  },
  AvgDialog_72002_Content_11 = {
    Text = "Cô Yu Li-ét thật sự lo lắng về thân thể của ngài, ngài thực sự không nên sử dụng \"phước lành\" nữa!"
  },
  AvgDialog_72002_Content_12 = {
    Text = "Ở giữa đám đông, Sara ôm đầu co ro trên mặt đất, thân thể không ngừng run rẩy vì cố gắng nhẫn nại cơn đau dữ dội, các khớp ngón tay đã trắng bệch vì siết chặt."
  },
  AvgDialog_72002_Content_13 = {
    Text = "Sophia đứng chắn trước Salvador, người đang hơi còng lưng, dùng thân hình mỏng manh của mình để tách biệt anh ta và Sara."
  },
  AvgDialog_72002_Content_14 = {
    Text = "Sophia, hãy nhường đường đi."
  },
  AvgDialog_72002_Content_15 = {
    Text = "Nếu cô ấy đã đến đây để cầu xin sự giúp đỡ của tôi, thì ánh sáng của Cha thần sẽ xua tan bóng tối của đau khổ cho cô ấy."
  },
  AvgDialog_72002_Content_16 = {
    Text = "Bóng dáng gầy guộc phủ phục bên giường bệnh của Sara, những đường vân màu xanh nhạt dần ôm trọn người phụ nữ đang khóc than vào lòng. Người phụ nữ dần ngừng đau đớn, và trong ánh sáng xanh dịu nhẹ, cô chìm vào giấc ngủ yên bình như một đứa trẻ sơ sinh."
  },
  AvgDialog_72002_Content_17 = {
    Text = "Salvador ho dữ dội, một vệt máu đỏ thẫm trượt xuống khóe miệng. Ông bình thản lau đi."
  },
  AvgDialog_72002_Content_18 = {
    Text = "Bạn xem bạn này! Tôi sẽ đỡ bạn đi nghỉ ngay!"
  },
  AvgDialog_72002_Content_19 = {
    Text = "Mục tiễn hai người dần xa, Rong Huỷ · đóa lạnh lùng bật ra một tiếng cười nhạo."
  },
  AvgDialog_72002_Content_2 = {
    Text = "Bạc tâm trong đầu Sara dần dần tối đi, nhưng vẫn bùng phát sức mạnh khổng lồ vượt qua người thường, vùng vẫy mạnh mẽ, ánh mắt lộ rõ vẻ điên rồ."
  },
  AvgDialog_72002_Content_20 = {
    Text = "Đóa ơi... bạn đang cười gì vậy?"
  },
  AvgDialog_72002_Content_21 = {
    Text = "Mỉa mai vị linh mục, tất nhiên."
  },
  AvgDialog_72002_Content_22 = {
    Text = "Logic của anh ta quả thực có phải nực cười không?\nĐáng ra anh ta đã từ bỏ cái đống hỗn độn này rồi."
  },
  AvgDialog_72002_Content_23 = {
    Text = "Nếu bảo vệ người này, về sau có thể cứu được nhiều người hơn."
  },
  AvgDialog_72002_Content_24 = {
    Text = "Nhưng anh ta thà hy sinh đến hơi thở cuối cùng, cũng quyết tâm giữ cho nhà thờ này không bị xâm phạm, bảo vệ những con chiên yếu đuối đang đối mặt với cái chết."
  },
  AvgDialog_72002_Content_25 = {
    Text = "Sử dụng lý thuyết \"số người nhiều hơn số người ít\"để hỗ trợ ý tưởng của mình, nhưng giờ đây hành động của anh ta lại đi ngược lại với quyết định trước đây."
  },
  AvgDialog_72002_Content_26 = {
    Text = "Cứu một người, nhưng lại làm giảm cơ hội sống sót của mọi người trong nhà thờ, cách suy nghĩ của con người \"thánh nhân\" hoàn toàn thiếu đi cơ sở lý tính."
  },
  AvgDialog_72002_Content_27 = {
    Text = "Nếu là bạn, bạn sẽ xử lý thế nào, đóa?"
  },
  AvgDialog_72002_Content_28 = {
    Text = "Sống lay lắt trong một thế giới không chấp nhận, chờ đợi ngày giải thoát có thể không bao giờ đến."
  },
  AvgDialog_72002_Content_29 = {
    Text = "Tôi sẽ chấm dứt nỗi đau của họ, và của tất cả mọi người."
  },
  AvgDialog_72002_Content_3 = {
    Text = "Mấy người trông như nhân viên y tế cao lớn tiến lại từ hai bên, ép buộc cô ta bằng dây thừng và buộc chặt vào giường."
  },
  AvgDialog_72002_Content_4 = {
    Text = "Xin mọi người đừng như vậy, hãy giao mọi việc cho tôi. Cha thần sẽ chữa lành linh hồn cô ấy đang lạc lối trong đau khổ."
  },
  AvgDialog_72002_Content_5 = {
    Text = "Salvador kéo vạt áo trên cánh tay lên, những vết sẹo lớn nhỏ, sâu cạn khác nhau phủ kín cánh tay già nua và vững chắc của ông. Nhìn vào chúng, người ta không khỏi rùng mình."
  },
  AvgDialog_72002_Content_6 = {
    Text = "Anh ta cắt cổ tay mình, những giọt máu rơi xuống sàn nhà thờ, dần tạo thành hình dạng pháp trận."
  },
  AvgDialog_72002_Content_7 = {
    Text = "Quý ngài Salvador!!"
  },
  AvgDialog_72002_Content_8 = {
    Text = "Một cô gái lao ra khỏi đám đông, dùng băng trắng quấn lên vết thương trên cổ tay của Salvador."
  },
  AvgDialog_72002_Content_9 = {
    Text = "Thưa Đức Giám mục, tôi không biết cô Yu Li-ét trong mắt ngài là kẻ xấu xa tột độ như thế nào, nhưng tôi có thể nhìn thấu những dục vọng thật sự của con người."
  },
  AvgDialog_72003_Content_1 = {
    Text = "Không được, số lượng quá nhiều, cứ tiếp tục như thế này, chỉ bằng vài người chúng ta thì không thể ngăn cản được, tháp chuông sẽ thất thủ!"
  },
  AvgDialog_72003_Content_10 = {
    Text = "Người phụ nữ đó."
  },
  AvgDialog_72003_Content_11 = {
    Text = "Quái vật đang nhắm vào người phụ nữ đó!"
  },
  AvgDialog_72003_Content_12 = {
    Text = "Bạn nghe thấy tiếng gào thét đầy đau đớn từ trong tháp chuông vọng ra, khàn khàn, tan vỡ, đã trải qua nhiều đau đớn. Trong khoảnh khắc tiếng hét xâm nhập vào tai, bạn dường như bị đặt mình trong tuyệt vọng tột cùng, đủ để khiến tâm trí rối loạn."
  },
  AvgDialog_72003_Content_13 = {
    Text = "Lúc đó, Sara cũng đã phát ra tiếng gầm như vậy trước khi đầu cô nổ tung vì cảm thấy tội lỗi ——"
  },
  AvgDialog_72003_Content_14 = {
    Text = "Cẩn thận Sara!"
  },
  AvgDialog_72003_Content_15 = {
    Text = "Bạn xông vào phòng, hình dáng của nữ tu sĩ co ro trong bóng mờ."
  },
  AvgDialog_72003_Content_16 = {
    Text = "Cô ta quỳ sụp xuống đất, kinh hoàng ôm chặt lấy vai mình, từ đỉnh đầu đến cằm xuất hiện một đường máu mảnh dài, máu đỏ thẫm không ngừng nhỏ xuống khiến cô ta trông vô cùng gớm ghiếc và đáng sợ."
  },
  AvgDialog_72003_Content_17 = {
    Text = "Bạn do dự."
  },
  AvgDialog_72003_Content_18 = {
    Text = "Người sắp mất kiểm soát trước mắt vẫn là Sara sao? Bạn nên đối xử với cô ấy như một quái vật hay như một con người?"
  },
  AvgDialog_72003_Content_19 = {
    Text = "Không thể chứa đựng ngay cả lực lượng của một chút bạc tâm, cảm thấy đau đớn cũng là điều dễ hiểu."
  },
  AvgDialog_72003_Content_2 = {
    Text = "Một thân hình nhỏ nhắn nhanh chóng lao về phía các bạn, lọn tóc trên trán tán loạn, rõ ràng là vừa mới giật mình tỉnh dậy từ giấc ngủ."
  },
  AvgDialog_72003_Content_20 = {
    Text = "Mol Hủy · đóa hoàn toàn không ngại ngần đến trước mặt Sara, đưa tay nhẹ nhàng vuốt ve vết sáng mờ trên trán Sara, sau đó lấy ra một chai thuốc nhỏ, bôi lên chỗ xương trắng lóe lên từ vết nứt trên da."
  },
  AvgDialog_72003_Content_21 = {
    Text = "Ánh sáng của bạc tâm dần dần tối đi."
  },
  AvgDialog_72003_Content_22 = {
    Text = "Chỉ có thể tạm thời áp chế, cho dù để bệnh tình phát triển hay cố gắng rút ra bạc tâm, thân thể cô đều không thể chịu đựng được."
  },
  AvgDialog_72003_Content_23 = {
    Text = "Có lẽ các bạn biết ai đó hoặc thực thể nào đó giỏi về làm sạch linh hồn không?"
  },
  AvgDialog_72003_Content_25 = {
    Text = "……………"
  },
  AvgDialog_72003_Content_27 = {
    Text = "Quá khứ xa xôi, trong đám đông ồn ào.\nSalvador giơ tay lên, máu chảy từ cơ thể anh ta, tuôn ra xung quanh, dòng chảy không ngừng hướng về bảng đá."
  },
  AvgDialog_72003_Content_28 = {
    Text = "Ánh sáng màu xanh lại chảy dọc theo các đường vân, sáng tối luân phiên, như thể đang thở."
  },
  AvgDialog_72003_Content_29 = {
    Text = "Đấng Cha Tạo Hóa, Đấng tạo hóa nhân từ, xin hãy lắng nghe lời cầu nguyện của con."
  },
  AvgDialog_72003_Content_3 = {
    Text = "%player%! Điều này rốt cuộc là sao? Trước đây chưa bao giờ có nhiều quái vật như vậy!"
  },
  AvgDialog_72003_Content_30 = {
    Text = "Màu xanh dịu nhẹ tỏa ra từ tấm bảng đá, lan rộng về bốn phía với những rễ cây dày đặc. Chúng xuyên qua đám đông, làn gió mát lạnh đã thổi bay mùi máu tanh còn sót lại, chỉ để lại hương thơm thanh nhã phảng phất."
  },
  AvgDialog_72003_Content_31 = {
    Text = "Những người đứng chậm rãi ngồi xuống."
  },
  AvgDialog_72003_Content_32 = {
    Text = "Những người đang ngồi mở to miệng, ngây người nhìn cảnh tượng diệu kỳ trước mắt."
  },
  AvgDialog_72003_Content_33 = {
    Text = "Những người mất ý thức, cũng như ngừng thở, đều từ từ mở mắt trong làn gió nhẹ."
  },
  AvgDialog_72003_Content_34 = {
    Text = "Hãy xóa đi nỗi đau của họ, xoa dịu tâm hồn của họ."
  },
  AvgDialog_72003_Content_35 = {
    Text = "Ánh mắt của mọi người trở nên trống rỗng, thân thể càng thêm thả lỏng. Sự hoảng loạn và sợ hãi tan biến, thay vào đó là một cảm giác thoải mái và bình yên."
  },
  AvgDialog_72003_Content_36 = {
    Text = "Hãy để họ không còn phải chịu khổ đau và ban phúc lành cho họ."
  },
  AvgDialog_72003_Content_37 = {
    Text = "Ánh sáng như thủy triều tràn ra xung quanh, tất cả mọi người đều nhắm mắt lại, giống như đang hòa mình vào sự tĩnh lặng."
  },
  AvgDialog_72003_Content_39 = {
    Text = "Sự chữa lành của Salvador thật sự yên bình và điềm tĩnh, đủ để tạo nên một không gian an tâm hoàn toàn giữa thực tại đầy biến động."
  },
  AvgDialog_72003_Content_4 = {
    Text = "Nhìn động tác của quái vật kìa mọi người!"
  },
  AvgDialog_72003_Content_40 = {
    Text = "Tôi không chắc liệu thế giới này có còn tồn tại điều gì đó giống như thế giới mà tôi biết… nhưng tôi hy vọng họ tồn tại."
  },
  AvgDialog_72003_Content_41 = {
    Text = "Chủ giáo của Đại đền thánh Cứu thế, Salvador."
  },
  AvgDialog_72003_Content_42 = {
    Text = "Sáng mai, chúng ta sẽ khởi hành phá vây."
  },
  AvgDialog_72003_Content_5 = {
    Text = "Họ cùng ngẩng đầu lên, ánh mắt vô thần hướng về phía tháp đồng hồ, như đàn sói hoang dã cất tiếng tru dài vào đêm trăng đỏ thẫm."
  },
  AvgDialog_72003_Content_6 = {
    Text = "Có điều gì đó trên tháp đồng hồ thu hút họ."
  },
  AvgDialog_72003_Content_7 = {
    Text = "Bạn nhớ lại những sinh thể dị biến rỗng rỗng lảng vảng ở hành lang hầm, chúng cũng đang khao khát điều gì đó, vì vậy tụ tập ở đó."
  },
  AvgDialog_72003_Content_9 = {
    Text = "Hôm nay đến tháp chuông…"
  },
  AvgDialog_72004_Content_1 = {
    Text = "Những nốt nhạc của Mizou"
  },
  AvgDialog_72004_Content_10 = {
    Text = "Thế giới bên ngoài có vui không, chú chó con của tôi?"
  },
  AvgDialog_72004_Content_11 = {
    Text = "Bạn muốn đáp trả sự khiêu khích của cô ấy, nhưng cảm giác buồn ngủ như thủy triều ập đến, cuốn đi tất cả ý chí của bạn.\nBạn bị mệt mỏi cuốn đi, ngất đi trước khi cô ấy nói câu tiếp theo."
  },
  AvgDialog_72004_Content_12 = {
    Text = "Tiếng điện yếu ớt của didi, tiếng thở nhẹ nhàng của ai đó."
  },
  AvgDialog_72004_Content_13 = {
    Text = "Bạn mở mắt ra, chỉ thấy mình đang nằm trên một chiếc giường gấp nhỏ, Wenkel đang ngủ yên bên cạnh giường của bạn."
  },
  AvgDialog_72004_Content_14 = {Text = "Ừ?"},
  AvgDialog_72004_Content_15 = {
    Text = "Cô ấy xoa xoa đôi mắt còn ngái ngủ, chậm chạp gỡ tấm chăn mỏng trên người ra."
  },
  AvgDialog_72004_Content_16 = {
    Text = "Bạn cần nghỉ ngơi thêm một lát nữa, một loại thuốc an thần sẽ khiến thân thể bạn cảm thấy mệt mỏi bất thường."
  },
  AvgDialog_72004_Content_17 = {
    Text = "Bạn nhấc tay lên, quả nhiên cảm thấy cánh tay trên đau nhức, yếu ớt."
  },
  AvgDialog_72004_Content_18 = {
    Text = "Chờ đến khi bệnh của bạn khỏi hẳn, chúng ta sẽ thương lượng dần với đóa, để bạn ra ngoài dạo chơi được không? Bệnh nhân luôn cần không khí tươi mới."
  },
  AvgDialog_72004_Content_19 = {
    Text = "Ngoài ra, bạn đã không ăn uống trong một thời gian dài, dù đã bổ sung chất dinh dưỡng, hệ tiêu hóa cũng cần nạp thức ăn để duy trì hoạt động khỏe mạnh…"
  },
  AvgDialog_72004_Content_2 = {
    Text = "Đoàng đoàng, đoàng đoàng.\nChân của Búp bê gõ vào bàn thí nghiệm."
  },
  AvgDialog_72004_Content_20 = {
    Text = "Tôi đã ngủ bao lâu?"
  },
  AvgDialog_72004_Content_21 = {
    Text = "Mặc dù thời gian đối với bạn đã mất đi ý nghĩa, nhưng bạn cần phải nắm vững trạng thái thân thể của mình."
  },
  AvgDialog_72004_Content_22 = {
    Text = "Tôi xem xem… 46 giờ 15 phút…"
  },
  AvgDialog_72004_Content_23 = {
    Text = "Chỉ trong hai ngày, vẫn trong phạm vi chấp nhận được."
  },
  AvgDialog_72004_Content_24 = {
    Text = "Muốn rời đi sao? Rất tiếc, tôi không thể cho phép."
  },
  AvgDialog_72004_Content_25 = {
    Text = "Rời khỏi phòng thí nghiệm này, có quá nhiều kẻ xấu đang dòm ngó bạn, con cừu non."
  },
  AvgDialog_72004_Content_26 = {
    Text = "Đóa nói đúng rồi…… ở lại đây…… là để bảo vệ bạn……"
  },
  AvgDialog_72004_Content_27 = {
    Text = "Tôi không cần ai bảo vệ."
  },
  AvgDialog_72004_Content_28 = {
    Text = "Vậy thì hãy để tôi xem."
  },
  AvgDialog_72004_Content_29 = {
    Text = "Chú chó con của Misaque, rời xa \"Ngài\" hỗ trợ, còn lại bao nhiêu bản lĩnh!"
  },
  AvgDialog_72004_Content_3 = {
    Text = "Thành thật mà nói, tôi không thích đề xuất của bạn."
  },
  AvgDialog_72004_Content_4 = {
    Text = "Chính như tôi không thích đĩa than đen trong tay bạn —— âm nhạc rất hay, nhưng việc ghi tên chung cho các tác phẩm cá nhân chẳng khác nào xúc phạm đến người sáng tạo, giống như việc chia một chiếc bánh sinh nhật để phân chia."
  },
  AvgDialog_72004_Content_5 = {
    Text = "Tôi hứa sẽ thay bạn lẻn vào Misaque và kích nổ hồ đen, chỉ có vậy mà thôi."
  },
  AvgDialog_72004_Content_6 = {
    Text = "Ý thức của %player% là tôi đã đánh thức từ chiều không gian đó và cấy vào não trong bình. Nói cách khác, anh ta giống như chú chó mà tôi nuôi dưỡng riêng."
  },
  AvgDialog_72004_Content_7 = {
    Text = "Giờ bạn muốn chia sẻ, muốn tôi giao ra bộ não của ngài ấy hoặc chia sẻ kết quả nghiên cứu, tôi chỉ có thể nói rằng, thỏa thuận của chúng ta không bao gồm phần này."
  },
  AvgDialog_72004_Content_8 = {
    Text = "Tôi sẽ không đồng ý với đề nghị của bạn, trừ khi bạn phá hủy phòng thí nghiệm này và chịu đựng cơn thịnh nộ mà tôi sẽ trút lên bạn. Nếu không, câu trả lời của tôi sẽ mãi mãi là \"ảo tưởng viển vông\"."
  },
  AvgDialog_72004_Content_9 = {
    Text = "Rã rệu · đóa có vẻ đã kết thúc liên lạc, hướng về phía bạn trong trạng thái bị thương nặng và được Wenkel dìu đỡ."
  },
  AvgDialog_72005_Content_1 = {
    Text = "Sau khi bạn nhắc nhở, tôi mới nhận ra rằng một số quái vật Rỗng ở đây dường như khác so với những quái vật trong chiều mà tôi đang ở."
  },
  AvgDialog_72005_Content_10 = {
    Text = "Họ hô vang:\nÔm lấy tôi."
  },
  AvgDialog_72005_Content_11 = {
    Text = "Họ hô vang:\nGiết tôi."
  },
  AvgDialog_72005_Content_12 = {
    Text = "Họ hô vang:\nHãy để tôi trở thành bạn, và bạn trở thành tôi."
  },
  AvgDialog_72005_Content_13 = {
    Text = "Hãy để linh tính nhỏ bé của chúng ta dâng trào thành biển triều u ám vạn cổ, với tư thái cấm kỵ và điên cuồng, hòa hợp rối ren, và không bao giờ tách rời."
  },
  AvgDialog_72005_Content_14 = {
    Text = "À à——"
  },
  AvgDialog_72005_Content_15 = {
    Text = "Bạn gầm lên và quỳ sụp xuống đất, không kiềm chế được, đưa tay ra phía trước."
  },
  AvgDialog_72005_Content_16 = {Text = "Ai——"},
  AvgDialog_72005_Content_17 = {
    Text = "Ai đến——"
  },
  AvgDialog_72005_Content_18 = {
    Text = "Có nghe thấy không?"
  },
  AvgDialog_72005_Content_19 = {
    Text = "Phải… hòa hợp…"
  },
  AvgDialog_72005_Content_2 = {
    Text = "Ừ, họ chỉ xuất hiện sau khi sự hủy diệt đó xảy ra."
  },
  AvgDialog_72005_Content_20 = {
    Text = "Bạn đã nghe thấy âm thanh giống như những gì các sinh vật biến dị đã nghe."
  },
  AvgDialog_72005_Content_21 = {
    Text = "Giọng của đóa chỉ có sự lạnh lùng vô cơ, so với cô ấy, những tiếng gọi kia lại mang theo nhiệt độ của nỗi đau."
  },
  AvgDialog_72005_Content_22 = {
    Text = "Bạn hãy bình tâm lại và cố gắng nắm bắt nó. Linh tính trong bạc tâm quá mỏng manh, thiết bị không thể phát hiện dao động của chúng. Chỉ có bạn mới có thể làm được việc này."
  },
  AvgDialog_72005_Content_23 = {
    Text = "Tiếng trống tay mờ ảo từ một nơi xa xôi không rõ, trước mắt hiện ra lối đi khuất không thấy ánh sáng."
  },
  AvgDialog_72005_Content_24 = {
    Text = "Bùn lầy ô uế và đá chạm khắc hoa văn trong sương mù phân cực thay đổi khôn lường, hình bóng méo mó tựa như quỷ mị không thể hiểu."
  },
  AvgDialog_72005_Content_25 = {
    Text = "Đông đông, đông đông."
  },
  AvgDialog_72005_Content_26 = {
    Text = "Tiếng trống tay càng lúc càng gấp gáp, bạn cúi đầu nhìn xuống, mặt nước đen ngòm đã bao phủ mắt cá chân bạn, đẩy mạnh bạn bước vào chuyến hành trình tới giấc mơ tối tăm."
  },
  AvgDialog_72005_Content_27 = {
    Text = "Bạn hít sâu, làm dịu đầu óc choáng váng, cố gắng giữ thăng bằng, nhẹ nhàng bước đi trong làn nước đặc quánh, từ từ tiến về phía trước…"
  },
  AvgDialog_72005_Content_28 = {
    Text = "Miệng bạn khô khan, như bị tro tàn lấp đầy."
  },
  AvgDialog_72005_Content_29 = {
    Text = "Họ được sinh ra từ tro tàn, ôm lấy và hòa nhập nhau…"
  },
  AvgDialog_72005_Content_3 = {
    Text = "Tôi đã từng lấy mẫu và tiến hành kiểm tra với số lượng lớn, lúc đầu chẳng có chút manh mối nào, sau khi cải tiến quy trình phức tạp mới rút ra được kết luận."
  },
  AvgDialog_72005_Content_30 = {
    Text = "Giữa hơi thở, khói bụi vô tận chôn vùi bạn sâu, bạn gắng gượng mở mắt, cùng với muôn loài ngẩng đầu nhìn xuyên qua lớp bụi mù dày đặc."
  },
  AvgDialog_72005_Content_31 = {
    Text = "Họ khao khát…"
  },
  AvgDialog_72005_Content_32 = {
    Text = "Xa xôi, trên bầu trời nhợt nhạt, mặt trời mờ treo cao."
  },
  AvgDialog_72005_Content_33 = {
    Text = "Mặt trời đen treo lơ lửng trên bầu trời, giống như một còng kinh cổ xưa bị lãng quên, lặng lẽ nhìn xuống vùng đất này, nơi ác mộng xoáy tròn và chìm trong sương xám."
  },
  AvgDialog_72005_Content_34 = {
    Text = "Ánh sáng không thể xuyên thấu qua nó, trái lại bị nó nuốt chửng. Đường viền phảng phất những gợn sóng tự do như đang dệt nên một nghi lễ vĩnh cửu, tuyên bố một kết thúc không thể đảo ngược và không thể diễn tả."
  },
  AvgDialog_72005_Content_35 = {
    Text = "Đã thực sự đến hồi kết."
  },
  AvgDialog_72005_Content_4 = {
    Text = "Kết luận là?"
  },
  AvgDialog_72005_Content_5 = {
    Text = "Trong những dị thể rỗng rỗng này, có chứa bạc tâm từ không chỉ một sinh mệnh."
  },
  AvgDialog_72005_Content_6 = {
    Text = "Thông thường, quy trình tinh luyện bạc tâm không phân biệt nguồn gốc. Đối với bạc tâm có linh tính thấp dùng làm nhiên liệu, điều này càng đúng."
  },
  AvgDialog_72005_Content_7 = {
    Text = "Bạn chạm vào bạc tâm, những giấc mơ hỗn loạn như dòng triều lạnh giá nuốt chửng bạn."
  },
  AvgDialog_72005_Content_8 = {
    Text = "Hai cánh tay tàn phế, quấn chặt vào nhau.\nHọ từng yêu nhau như thế, nên đã giao phó cho nhau."
  },
  AvgDialog_72005_Content_9 = {
    Text = "Giao phó xương thịt, linh hồn và thịt, xé rách tóc.\nTrung thành với khát vọng, trung thành với sự khao khát, trung thành với sự hoảng sợ và đau khổ của sự chia ly."
  },
  AvgDialog_72006_Content_1 = {
    Text = "Giấc mơ trong bình"
  },
  AvgDialog_72006_Content_10 = {
    Text = "Chào mừng đến với căn cứ bí mật của tôi, người du lịch từ thế giới số 317, luồng linh thức của vị \"ý chí vô thượng\"... một chú chó con tội nghiệp bị rơi xuống nước."
  },
  AvgDialog_72006_Content_11 = {
    Text = "Hãy nói cho tôi biết, thế giới của bạn đã bị hủy diệt rồi sao?"
  },
  AvgDialog_72006_Content_13 = {
    Text = "Thật không hổ danh là việc làm của \"tôi\"."
  },
  AvgDialog_72006_Content_14 = {
    Text = "Đúng như bạn nghĩ, \"tôi\" trong thế giới của bạn được \"tôi\" này gửi đến thời gian và không gian của bạn thông qua khả năng du hành giữa các chiều."
  },
  AvgDialog_72006_Content_15 = {
    Text = "Làm phần thưởng, cô ấy đã gửi cho tôi một quà tặng thú vị... \"ý thức\" của bạn."
  },
  AvgDialog_72006_Content_16 = {
    Text = "……………"
  },
  AvgDialog_72006_Content_17 = {
    Text = "Muốn gặp gỡ con người hiện tại của bạn không?"
  },
  AvgDialog_72006_Content_18 = {
    Text = "Nụ cười của cô ấy mạnh mẽ, như một bông hoa cẩm chướng đen tự do nở rộ."
  },
  AvgDialog_72006_Content_19 = {
    Text = "Wenkel, mang một chiếc gương toàn thân đến đây."
  },
  AvgDialog_72006_Content_2 = {
    Text = "Bật máy hát lên. Từ trái sang phải, tấm đĩa có bìa đen thứ ba trên kệ sách."
  },
  AvgDialog_72006_Content_20 = {
    Text = "Hãy để \"khách\" của chúng ta nhìn kỹ xem họ hiện tại trông như thế nào..."
  },
  AvgDialog_72006_Content_21 = {
    Text = "Không cần mắt, sử dụng tín hiệu ánh sáng và điện để mô phỏng thần kinh thị giác."
  },
  AvgDialog_72006_Content_22 = {
    Text = "Không cần dây thanh âm, sử dụng rung động cơ học và chất lỏng để thay thế các cơ quan phát ra và nhận âm thanh."
  },
  AvgDialog_72006_Content_23 = {
    Text = "Người suy nghĩ hoàn hảo, não trong bình……"
  },
  AvgDialog_72006_Content_24 = {
    Text = "Đây chính là ngươi, vĩ đại \"ý chí vô thượng\"!"
  },
  AvgDialog_72006_Content_25 = {
    Text = "Gương đứng phản chiếu hình bóng của \"bạn\", như thể vừa được tách ra từ não bộ, với sắc hồng nhạt khó nhìn trực diện. Những nếp gấp và rãnh trên bề mặt trông giống như những dãy núi bị biến dạng."
  },
  AvgDialog_72006_Content_26 = {
    Text = "Dung dịch dinh dưỡng chứa những bong bóng khí nhỏ nhả ra tiếng sôi nhẹ, như thể đang thì thầm về một bí mật khó lòng diễn tả, khiến \"tư duy\" vốn đã hỗn loạn của bạn trở nên căng thẳng bất thường."
  },
  AvgDialog_72006_Content_27 = {
    Text = "Meltdown·đóa cười như điên. \nWenkel đứng sau lưng cô, cắn móng tay lo lắng."
  },
  AvgDialog_72006_Content_28 = {
    Text = "Tôi,  tôi có thể rời đi được không?"
  },
  AvgDialog_72006_Content_29 = {
    Text = "Không… giúp tôi tiếp tục các bước thí nghiệm. Đây là sổ tay hướng dẫn."
  },
  AvgDialog_72006_Content_3 = {
    Text = "Bổ sung thêm 21mg bạc tâm vào lò phản ứng. Sử dụng loại đã qua hai lần tinh luyện, linh tính bị tiêu trừ càng triệt để càng tốt."
  },
  AvgDialog_72006_Content_30 = {
    Text = "Melt·đóa nhấn dừng máy hát, rời đi một cách tự tin. Trong phòng thí nghiệm trống trải, chỉ còn lại Wenkel và bạn nhìn nhau bối rối."
  },
  AvgDialog_72006_Content_31 = {
    Text = "Bước thực nghiệm, quy trình thực nghiệm……"
  },
  AvgDialog_72006_Content_32 = {
    Text = "Cô ấy dường như mới nhận ra lời dặn dò của Đóa, quay người lại và lật vội quyển sổ tay mà Đóa để lại. Tình cảnh này, nói đúng hơn là cô ấy không đọc được nửa chữ, chứ không phải đọc mười dòng một lúc."
  },
  AvgDialog_72006_Content_33 = {
    Text = "Này, này. Bạn có nghe thấy tôi nói không ?"
  },
  AvgDialog_72006_Content_34 = {
    Text = "Không nghe thấy, không nghe thấy, tôi không nghe thấy gì cả……"
  },
  AvgDialog_72006_Content_35 = {
    Text = "Bạn là… Wenkel phải không?"
  },
  AvgDialog_72006_Content_36 = {
    Text = "Bạn, bạn làm sao mà biết…"
  },
  AvgDialog_72006_Content_37 = {
    Text = "Không cần sợ hãi, Wenkel. Chúng ta từng là đồng đội chiến đấu cùng nhau."
  },
  AvgDialog_72006_Content_38 = {
    Text = "Bạn cố gắng an ủi cô ấy. Bạn biết rõ, Wenkel trong trạng thái thần kinh không thể giao tiếp hiệu quả."
  },
  AvgDialog_72006_Content_39 = {
    Text = "Bạn... tôi.."
  },
  AvgDialog_72006_Content_4 = {
    Text = "Sản phẩm thí nghiệm hôm nay…… sắp hoàn thành."
  },
  AvgDialog_72006_Content_40 = {
    Text = "Cô cắn móng tay, ánh mắt chạy qua chạy lại, đầy bất an, như một con thú non đầy sợ hãi bị dồn ép vào góc."
  },
  AvgDialog_72006_Content_41 = {
    Text = "Hãy bình tĩnh lại. Làm ơn cho tôi biết, tại sao tôi lại ở đây không?"
  },
  AvgDialog_72006_Content_42 = {
    Text = "Đây, này…"
  },
  AvgDialog_72006_Content_43 = {
    Text = "Bạn kiên nhẫn chờ đợi cảm xúc của cô ấy trở nên bình tĩnh.\nMất một lúc, cô ấy dường như cuối cùng đã quyết định."
  },
  AvgDialog_72006_Content_44 = {
    Text = "Ngày đó, 'Đóa' đột nhiên gửi thông tin liên lạc…"
  },
  AvgDialog_72006_Content_45 = {
    Text = "Wenkel, chuẩn bị sẵn máy nhận và bình não dự phòng."
  },
  AvgDialog_72006_Content_46 = {
    Text = "Tôi đã bắt được một tín hiệu điện bất thường, dải tần hiển thị tương tự với ý thức của Tovarva."
  },
  AvgDialog_72006_Content_47 = {
    Text = "Người đó về lý thuyết đã tự khóa mình bên trong \"cửa\", không biết làm sao tín hiệu này vẫn còn tồn tại."
  },
  AvgDialog_72006_Content_48 = {
    Text = "Tóm lại, chuẩn bị ngay để nhận công việc!"
  },
  AvgDialog_72006_Content_49 = {
    Text = "Tóm lại, ý thức của bạn đã được chiếu vào thùng não này và vẫn sống sót."
  },
  AvgDialog_72006_Content_5 = {
    Text = "Bạn có cảm nhận được tôi không?"
  },
  AvgDialog_72006_Content_50 = {
    Text = "Cụ thể nguồn, có lẽ chỉ có đóa biết."
  },
  AvgDialog_72006_Content_51 = {
    Text = "Thực sự mà nói, việc kích hoạt ý thức của bạn đã khiến chúng tôi mất ngủ suốt một tháng liền. Đóa chắc là đã đi ngủ rồi, dù có là cơ thể giả lập, tinh thần cũng không thể chịu đựng thêm được nữa."
  },
  AvgDialog_72006_Content_52 = {
    Text = "Nghe có vẻ như, trước khi tôi chuyển đi, bạn đã hỗ trợ đóa hoàn thành thí nghiệm rồi."
  },
  AvgDialog_72006_Content_53 = {
    Text = "Bạn có biết cô ấy đang làm gì không?"
  },
  AvgDialog_72006_Content_54 = {
    Text = "Wenkel rùng mình vì căng thẳng."
  },
  AvgDialog_72006_Content_55 = {
    Text = "Tôi, tôi chỉ đang làm một số… nghiên cứu khoa học đi đầu…"
  },
  AvgDialog_72006_Content_56 = {
    Text = "Về việc nhảy vọt không gian-thời gian, chuyển dịch ý thức… nhằm giúp tôi nhanh chóng quay lại quê hương hành tinh…"
  },
  AvgDialog_72006_Content_57 = {
    Text = "Bạn thở dài, dù bạn cũng không biết rõ tiếng thở dài có thể truyền đến tai cô ấy hay không."
  },
  AvgDialog_72006_Content_58 = {
    Text = "Biện minh đã chứng tỏ rằng anh biết mình đang làm gì rồi, Wenkel."
  },
  AvgDialog_72006_Content_59 = {
    Text = "Wenkel, vì bạn, vì tôi, và vì rất nhiều người có thể bị thương do Meltdown·đóa."
  },
  AvgDialog_72006_Content_60 = {
    Text = "Bạn có thể giúp tôi một việc được không?"
  },
  AvgDialog_72006_Content_61 = {
    Text = "Tôi, tôi có thể nghe xem."
  },
  AvgDialog_72006_Content_62 = {
    Text = "Bạn có biết làm thế nào để tôi khôi phục khả năng hành động bình thường không?"
  },
  AvgDialog_72006_Content_63 = {
    Text = "Wenkel dùng sức lắc đầu!"
  },
  AvgDialog_72006_Content_64 = {
    Text = "Kỹ thuật điều khiển búp bê không phải sở trường của tôi, và tất cả các bộ phận cơ thể nhân tạo đều bị đóa cấy một lớp khóa, chỉ có cô ấy mới có thể điều khiển chúng."
  },
  AvgDialog_72006_Content_65 = {
    Text = "Bạn phải tìm phương pháp khác.\nCó lẽ nên liên lạc với các người đánh thức khác, cầu cứu họ...?"
  },
  AvgDialog_72006_Content_66 = {
    Text = "Nếu tôi không nhầm, dãy phía sau bạn là kho bạc tâm của Rong Hỏa · Đóa, đúng không?"
  },
  AvgDialog_72006_Content_67 = {
    Text = "Lọ đựng, nhãn mác, các loại đồng hồ đo được sắp xếp gọn gàng, hoàn toàn phù hợp với thói quen làm việc của đóa."
  },
  AvgDialog_72006_Content_68 = {
    Text = "Lấy một từ kho bạc tâm……"
  },
  AvgDialog_72006_Content_69 = {
    Text = "Hình ảnh của Ramona, đóa, Orci và lơ-tan liên tục hiện lên trong đầu bạn."
  },
  AvgDialog_72006_Content_7 = {
    Text = "Đừng do dự. Hãy dùng cách \"nói chuyện\" bình thường của bạn. Thiết bị sẽ bắt tín hiệu mô phỏng mà bạn phát ra và chuyển đổi thành tín hiệu sóng âm."
  },
  AvgDialog_72006_Content_70 = {
    Text = "Bà Daphne đã trao cho tôi bạc tâm."
  },
  AvgDialog_72006_Content_71 = {
    Text = "Thấy Wenkel do dự, bạn đã dứt khoát tăng thêm trọng lượng."
  },
  AvgDialog_72006_Content_72 = {
    Text = "Wenkel, bây giờ, bể não mà tôi đang kết nối là nguồn sáng duy nhất trong phòng này. Nếu bạn không đồng ý với yêu cầu nhỏ này của tôi, tôi sẽ tự tắt ngay lập tức."
  },
  AvgDialog_72006_Content_73 = {
    Text = "Bạn cần ít nhất 3 giây để đi tới công tắc và khởi động đèn chiếu sáng, cố gắng nghĩ xem làm thế nào để sống sót qua 3 giây khó khăn này nhé."
  },
  AvgDialog_72006_Content_74 = {
    Text = "Tôi đếm ngược 3 số——"
  },
  AvgDialog_72006_Content_76 = {
    Text = "Bạn thử điều khiển chất lỏng huỳnh quang trong bình chứa nhấp nháy."
  },
  AvgDialog_72006_Content_77 = {
    Text = "Vào giây phút đầu tiên bóng tối đến, Wenkel đã hét toáng lên."
  },
  AvgDialog_72006_Content_78 = {
    Text = "Đừng——Tôi hứa với cậu, tôi sẽ lấy ngay cho cậu!!"
  },
  AvgDialog_72006_Content_79 = {
    Text = "Cô ấy quay người tìm kiếm trong tủ thuốc bên cạnh bàn thí nghiệm. Sau vài giây, một viên bạc cuốn quanh làn khói tím mờ ảo được cô ấy đặt trong lòng bàn tay, nhẹ nhàng nâng lên trước mặt bạn."
  },
  AvgDialog_72006_Content_8 = {
    Text = "Bạn thử phát âm theo lời dặn của cô ấy. Không cảm nhận được sự rung động phản hồi từ cổ họng, nhưng cô ấy nở một nụ cười kỳ quái đầy suy tư."
  },
  AvgDialog_72006_Content_80 = {Text = "Này…"},
  AvgDialog_72006_Content_81 = {
    Text = "Bạn nhìn chằm chằm vào chiếc kim loại bạc đó, cố gắng cảm ứng cộng hưởng với nó.\nBạn không chắc mình với tư cách là Não trong lọ có thể thực hiện được… nhưng bạn không còn lựa chọn nào khác, đành phải thử."
  },
  AvgDialog_72006_Content_82 = {
    Text = "Sương tím dâng lên."
  },
  AvgDialog_72006_Content_83 = {
    Text = "Giá cả rõ ràng, không gian dối… Cửa hàng Đào Đen Đá có thể giúp gì cho bạn?"
  },
  AvgDialog_72006_Content_9 = {
    Text = "Bạn hỏi tôi đây là nơi nào?"
  },
  AvgDialog_72007_Content_1 = {Text = "Hô."},
  AvgDialog_72007_Content_2 = {
    Text = "Thôi, có những phát triển vượt quá mong đợi, thôi, để lần sau tôi quay lại vậy."
  },
  AvgDialog_72007_Content_3 = {
    Text = "Tuy nhiên, Đức Giám mục Salvador, tôi đã để ý rằng…trong trận chiến vừa rồi, ngài không hề ra tay, phải không?"
  },
  AvgDialog_72007_Content_4 = {
    Text = "Đèn nến đã lung lay sắp đổ, hu, chỉ cần một chút gió thổi qua là sẽ tắt ngấm."
  },
  AvgDialog_72007_Content_5 = {
    Text = "Một con chó khổng lồ lao đến, đầu méo mó vâng lời cúi xuống, trông hoàn toàn tuân lệnh Yu Li-ét."
  },
  AvgDialog_72007_Content_6 = {
    Text = "Yu Li-ét nhẹ nhàng lật người lên, tựa vào vai chú chó khổng lồ."
  },
  AvgDialog_72007_Content_7 = {
    Text = "Đi thôi, người yêu.\nBảo trọng nhé, Giám mục Salvador."
  },
  AvgDialog_72007_Content_8 = {
    Text = "Cơn gió đó...sẽ đến rất nhanh."
  },
  AvgDialog_72008_Content_1 = {
    Text = "Này, vị linh mục ở nhà thờ, chúng tôi đã đưa bệnh nhân đến đây!"
  },
  AvgDialog_72008_Content_10 = {
    Text = "Khi não của cô ấy bị ăn mòn hoàn toàn……"
  },
  AvgDialog_72008_Content_11 = {
    Text = "Cha Salvador cúi đầu, vẽ dấu thánh giá để cầu nguyện trên ngực mình."
  },
  AvgDialog_72008_Content_12 = {
    Text = "Ngày mai, tôi sẽ cố gắng tách lực lượng này ra khỏi cơ thể cô ấy."
  },
  AvgDialog_72008_Content_13 = {
    Text = "Sara, cô có thể kể cho chúng tôi nghe, vết sẹo trên đầu cô là do đâu không?"
  },
  AvgDialog_72008_Content_14 = {
    Text = "Ngày đó.."
  },
  AvgDialog_72008_Content_15 = {
    Text = "Cô bé đẩy tấm nệm mỏng, lách qua những đứa trẻ đang ngủ say bên cạnh, trong đêm đông đi chân trần, chập chững bước về phía sân mờ tối."
  },
  AvgDialog_72008_Content_16 = {
    Text = "Ai Jī Sī, Ai Jī Sī……?"
  },
  AvgDialog_72008_Content_17 = {
    Text = "Tôi đã đuổi theo, muốn nhắc nhở cô ấy đi giày.\nNhưng cô ấy hoàn toàn không để ý đến tôi."
  },
  AvgDialog_72008_Content_18 = {
    Text = "Tôi chạy theo cô ấy mãi, cuối cùng đã đuổi kịp cô ấy ở cửa nhà thương nghèo."
  },
  AvgDialog_72008_Content_19 = {
    Text = "Tôi giữ vai cô ấy, xoay người cô ấy lại để đối mặt với tôi…"
  },
  AvgDialog_72008_Content_2 = {
    Text = "Jenkin đã vội vàng chạy vào đền thánh cứu thế trước tất cả mọi người."
  },
  AvgDialog_72008_Content_20 = {
    Text = "Tôi chỉ nhìn thấy.."
  },
  AvgDialog_72008_Content_21 = {
    Text = "Đôi mắt trống rỗng"
  },
  AvgDialog_72008_Content_23 = {
    Text = "Vào lúc đó, có một bàn tay nhẹ nhàng gác lên vai phải của tôi."
  },
  AvgDialog_72008_Content_24 = {
    Text = "Tôi hồi hộp quay đầu lại, lòng đầy lo lắng…"
  },
  AvgDialog_72008_Content_25 = {
    Text = "Đó là một người phụ nữ có bề mặt như đá, cầm một con dao nhỏ."
  },
  AvgDialog_72008_Content_26 = {
    Text = "Ngón trỏ của cô ấy khẽ chạm vào bờ môi trắng bệch, thì thầm dặn dò."
  },
  AvgDialog_72008_Content_27 = {
    Text = "Suỵt, đừng làm phiền những đứa con của \"Ngài\"."
  },
  AvgDialog_72008_Content_29 = {
    Text = "Sau đó, tôi không nhớ rõ nữa."
  },
  AvgDialog_72008_Content_3 = {
    Text = "Xin mọi người giữ yên lặng, trong đền thánh còn có nhiều bệnh nhân, họ có thể không chịu nổi tiếng ồn quá mức."
  },
  AvgDialog_72008_Content_30 = {
    Text = "Vết sẹo trên trán tôi, ban đầu do ông Rogers nhờ bác sĩ chữa trị cho tôi và để lại."
  },
  AvgDialog_72008_Content_31 = {
    Text = "Từ đó trở đi, bắt đầu xuất hiện một loại ánh kim màu bạc…… Tuy nhiên, nó không gây đau cũng không ngứa, và không ảnh hưởng đến cuộc sống."
  },
  AvgDialog_72008_Content_32 = {
    Text = "Thì ra anh đã tránh được thảm họa hòa hợp với thiên tai đó."
  },
  AvgDialog_72008_Content_33 = {
    Text = "Có người đã cấy vào cơ thể bạn một bạc tâm có hoạt tính cao, ép chỉ số Nos của bạn tăng lên trên mức chuẩn."
  },
  AvgDialog_72008_Content_34 = {
    Text = "Tương tự như 24, các thí nghiệm cấy ghép hoặc ngưng tụ bạc tâm trong cơ thể con người…"
  },
  AvgDialog_72008_Content_35 = {
    Text = "Đáng tiếc, mọi món quà đều có giá phải trả. Nỗi đau mà bạn đang gánh chịu hiện nay, phần lớn cũng liên quan đến sự sống được duy trì một cách cưỡng chế."
  },
  AvgDialog_72008_Content_36 = {
    Text = "Vị thánh cha thanh cao kia có thể cứu bạn khỏi hoạn nạn… hãy cùng chờ xem kết quả."
  },
  AvgDialog_72008_Content_4 = {
    Text = "Người bác sĩ chữa bệnh rất giỏi đó có phải là bạn không?\nỪm, trông có vẻ không giống những người mặc áo khoác trắng ở viện trợ."
  },
  AvgDialog_72008_Content_5 = {
    Text = "Tôi không phải bác sĩ, chỉ là \"Người ban phước\".\nXin hãy đưa bệnh nhân vào phòng của thư ký, rất xin lỗi các vị hãy đi cùng tôi."
  },
  AvgDialog_72008_Content_6 = {
    Text = "Ánh sáng xanh nhạt lưu chuyển quanh cơ thể Sara, mang theo ánh sáng ấm áp cùng sự chăm sóc ân cần và sâu sắc dành cho sự sống."
  },
  AvgDialog_72008_Content_7 = {
    Text = "Thời gian trôi qua từng phút, từng giây, ánh sáng nhạt trong lòng bàn tay Salvador không hề suy giảm, chỉ là anh khẽ cau mày, trên khuôn mặt thoáng hiện một nỗi bất lực và ưu tư khó nhận ra."
  },
  AvgDialog_72008_Content_8 = {
    Text = "Trước đó, tôi chưa bao giờ thấy được dấu hiệu bệnh tật như vậy.\nNói đơn giản, trong cơ thể cô ấy có một loại sức mạnh bất thường."
  },
  AvgDialog_72008_Content_9 = {
    Text = "Loài lực lượng đó có một dục vọng bất thường đối với việc ăn não… Cô ấy đã kiềm chế dục vọng đó bằng chính ý chí của mình, nhưng lực lượng đó đã bắt đầu ăn não của chính cô."
  },
  AvgDialog_72009_Content_1 = {Text = "Thoát"},
  AvgDialog_72009_Content_10 = {
    Text = "Cái giá phải trả là gì?"
  },
  AvgDialog_72009_Content_11 = {
    Text = "Yêu cầu đầu tiên của Người Giữ Gìn trong thế giới mới chỉ có thể được tặng như một món quà long trọng, làm sao có thể đòi hỏi đổi lại?"
  },
  AvgDialog_72009_Content_12 = {
    Text = "Chỉ là…… nếu bạn muốn bày tỏ lòng biết ơn thì……"
  },
  AvgDialog_72009_Content_13 = {
    Text = "Hãy mang đầu của người đó đến cho ta."
  },
  AvgDialog_72009_Content_14 = {
    Text = "Ý thức của bạn chìm vào một mảng hỗn loạn. Khi mở mắt ra lần nữa, bên cạnh là một Wenkel đang run rẩy không ngừng."
  },
  AvgDialog_72009_Content_15 = {
    Text = "Bạn……bạn……đột nhiên từ khoảng không rơi xuống thân thể……"
  },
  AvgDialog_72009_Content_16 = {
    Text = "Làm thế nào để rời khỏi đây?"
  },
  AvgDialog_72009_Content_17 = {
    Text = "Bỏ qua những lời thì thầm run rẩy của cô ấy, bạn đi thẳng vào vấn đề và đặt câu hỏi."
  },
  AvgDialog_72009_Content_18 = {
    Text = "Không, bạn không thể đi… Nếu, nếu bạn trốn thoát… đóa chắc chắn, chắc chắn sẽ…"
  },
  AvgDialog_72009_Content_19 = {
    Text = "Còng kinh của cô ấy bị nỗi sợ hãi chi phối mà mở rộng, giọng nói cầu xin run lên trong tuyệt vọng."
  },
  AvgDialog_72009_Content_2 = {
    Text = "Rất tiếc, tôi cũng muốn tìm cách đưa bạn trở lại chiều ban đầu, nhưng chiều bạn đang ở dường như không kết nối với lớp dưới cùng của cà đa sác…"
  },
  AvgDialog_72009_Content_20 = {
    Text = "Hãy yên tâm, tôi chỉ đi ra ngoài xem một chút."
  },
  AvgDialog_72009_Content_21 = {
    Text = "Không... thật sự không được.."
  },
  AvgDialog_72009_Content_22 = {
    Text = "Bạn đã phớt lờ lời cầu xin của cô ấy, gõ nhẹ cánh cửa sắt khi đóa rời đi. Trên cửa không có tay cầm hay ổ khóa."
  },
  AvgDialog_72009_Content_23 = {
    Text = "Làm thế nào để mở cánh cửa này?"
  },
  AvgDialog_72009_Content_24 = {
    Text = "Wenkel lùi lại vài bước, áp sát vào bàn thí nghiệm."
  },
  AvgDialog_72009_Content_25 = {
    Text = "Tôi, tôi không biết…"
  },
  AvgDialog_72009_Content_26 = {
    Text = "Tôi thật sự chỉ đi ra ngoài xem thôi. Đóa cứ để tôi xử lý."
  },
  AvgDialog_72009_Content_27 = {
    Text = "Chìa khóa hoặc thiết bị mở cửa chắc chắn ở trên bàn thí nghiệm phía sau lưng bạn rồi? Hành động che giấu của bạn đã phơi bày điểm này."
  },
  AvgDialog_72009_Content_28 = {
    Text = "Không, không phải vậy! Tôi chỉ là quá sợ hãi…"
  },
  AvgDialog_72009_Content_29 = {
    Text = "Đóa không thể dự đoán được sự trốn thoát của bạn, không cần quá đề phòng não trong bình, lối ra vào này chắc hẳn cũng không quá khó tìm."
  },
  AvgDialog_72009_Content_3 = {
    Text = "Nói cách khác, nơi đó không nằm trong vô số giấc mơ của Tohuwabo."
  },
  AvgDialog_72009_Content_30 = {
    Text = "Bạn quét mắt qua bàn thí nghiệm, ánh mắt lướt qua những tiêu đề luận văn phức tạp."
  },
  AvgDialog_72009_Content_31 = {
    Text = "\"Mô hình lan truyền hiện tượng ăn mòn khu vực Lê Mô Va Xi\",\"Sự kiềm chế giữa lõi bạc và sự khuếch tán ăn mòn\","
  },
  AvgDialog_72009_Content_32 = {
    Text = "\"Nghiên cứu về sự phối hợp chuyển động của mắt trong Toghuva-po\",\"Ứng dụng phương pháp ổn định ý thức trong chuyển dịch chiều không gian\"..."
  },
  AvgDialog_72009_Content_33 = {
    Text = "Tại một góc của bàn thí nghiệm, bạn phát hiện một công tắc đơn giản với thiết kế thô sơ có tay cầm màu đỏ. Bạn nhẹ nhàng kéo nó, và nghe thấy tiếng bánh răng vận hành."
  },
  AvgDialog_72009_Content_34 = {
    Text = "Cạch cạch cạch, cánh cửa sắt rỉ sét mở ra tự động dưới sự điều khiển của cơ cấu máy móc."
  },
  AvgDialog_72009_Content_35 = {
    Text = "Đợi, đợi đã——"
  },
  AvgDialog_72009_Content_36 = {
    Text = "Bạn đã bỏ qua lời gọi của cô ấy, bước lớn ra khỏi cánh cửa sắt ——"
  },
  AvgDialog_72009_Content_37 = {
    Text = "Một làn sương mù lớn màu chì xám, giống như một con quái vật vô hình và đầy uy lực, bao phủ toàn bộ thành phố trong bóng tối dày đặc."
  },
  AvgDialog_72009_Content_38 = {
    Text = "Số lượng tầng lầu dao động liên tục, như những bàn tay và chân nhọn hoắt bọc trong lớp da cứng cáp, chỉ lộ ra một góc từ đám sương mù."
  },
  AvgDialog_72009_Content_39 = {Text = "Ho, ho…"},
  AvgDialog_72009_Content_4 = {
    Text = "Thậm chí tôi cũng không thể dễ dàng di chuyển giữa hai thế giới khác chiều."
  },
  AvgDialog_72009_Content_40 = {
    Text = "Không có ai cả. Nhìn khắp nơi cũng không thấy ai."
  },
  AvgDialog_72009_Content_41 = {
    Text = "Bạn đang vất vả tiến lên trên đường phố."
  },
  AvgDialog_72009_Content_42 = {
    Text = "Quẹo qua ba con phố, mới vô tình bắt gặp hình dáng người trong sương mù dày đặc."
  },
  AvgDialog_72009_Content_43 = {
    Text = "Người phía trước——"
  },
  AvgDialog_72009_Content_44 = {
    Text = "Hình dáng xoay người về phía bạn, rồi đột ngột tiến gần, cái bóng đen khổng lồ vặn vẹo đột ngột dán sát vào khuôn mặt bạn.\nAdrenalin đột ngột tăng vọt, nhịp tim vang như trống."
  },
  AvgDialog_72009_Content_45 = {
    Text = "Xoạt——"
  },
  AvgDialog_72009_Content_46 = {
    Text = "Bạn không có vũ khí, Ramona cũng không ở bên cạnh, đừng nói đến những người bạn đồng hành."
  },
  AvgDialog_72009_Content_47 = {
    Text = "Thể dị biến phun ra một khối bùn đen, chất lỏng đặc và dính phủ lên trán bạn, độ ẩm và mùi hôi thối theo đường thái dương chảy xuống."
  },
  AvgDialog_72009_Content_48 = {
    Text = "Tiếp theo là một cú đánh mạnh."
  },
  AvgDialog_72009_Content_5 = {
    Text = "Thế thì… tôi ít nhất cần một thân thể có thể tự do hành động ở đây."
  },
  AvgDialog_72009_Content_50 = {Text = "Ho——"},
  AvgDialog_72009_Content_51 = {
    Text = "Bạn cảm thấy thân thể như bay lên, mắt lóa lên những ngôi sao vàng, sau đó một cú đá quay từ bên hông làm thay đổi hướng, mang lại nỗi đau như bị hàng ngàn mũi tên xuyên qua trái tim."
  },
  AvgDialog_72009_Content_52 = {
    Text = "Bạn va đập mạnh vào bức tường cứng rắn, cơn đau dữ dội khiến bạn cảm nhận rõ vài chiếc xương sườn dường như đã bị gãy."
  },
  AvgDialog_72009_Content_53 = {
    Text = "(Có ai có thể... cứu tôi với...)"
  },
  AvgDialog_72009_Content_54 = {
    Text = "Ho, ho phì, đợi, đợi một chút ——"
  },
  AvgDialog_72009_Content_55 = {
    Text = "Trong làn khói bụi, Wenkel lảo đảo chạy tới từ góc phố phía sau bạn."
  },
  AvgDialog_72009_Content_56 = {
    Text = "Lấy cái này, rồi, rồi hãy đi!"
  },
  AvgDialog_72009_Content_57 = {
    Text = "Dòng cong màu bạc vạch ngang qua bầu trời bị ô nhiễm bởi bụi bẩn, xuyên qua bầy quái vật vây quanh bạn, rơi xuống bên cạnh tay bạn."
  },
  AvgDialog_72009_Content_58 = {
    Text = "Một chìa khóa bạc. Không đánh số."
  },
  AvgDialog_72009_Content_59 = {
    Text = "Bạn đưa tay ra chạm, nhưng nước mắt tự nhiên khiến tầm nhìn của bạn trở nên mờ ảo, cơn đau khắp cơ thể khiến đầu ngón tay rung lên không kiểm soát."
  },
  AvgDialog_72009_Content_6 = {
    Text = "Bạn không thể di chuyển giữa hai thế giới…… nhưng sử dụng tài nguyên trong thế giới này là khả thi, phải không?"
  },
  AvgDialog_72009_Content_60 = {
    Text = "Còn thiếu... một chút.."
  },
  AvgDialog_72009_Content_61 = {
    Text = "Kẹp——"
  },
  AvgDialog_72009_Content_62 = {
    Text = "Xúc tu của quái vật dẫm mạnh lên lưng bạn, vết thương đã rách toạc phun máu tứ phía."
  },
  AvgDialog_72009_Content_63 = {
    Text = "Nhưng cũng chính vào khoảnh khắc này, ngón tay bạn chạm nhẹ vào ánh sáng."
  },
  AvgDialog_72009_Content_64 = {
    Text = "Hồi tưởng! Dùng sức để hồi tưởng!"
  },
  AvgDialog_72009_Content_65 = {
    Text = "Đóa nói, thần thức của ngươi bao hàm cả thế giới, chỉ cần hồi tưởng lại, chìa khóa bạc có thể kích phát lực lượng của ký ức!"
  },
  AvgDialog_72009_Content_66 = {
    Text = "Ánh sáng trắng dịu dàng dần dần bao phủ tầm nhìn của bạn, bốn dáng hình quen thuộc xuất hiện trước mắt bạn như ảo giác."
  },
  AvgDialog_72009_Content_67 = {
    Text = "Người giữ bí mật! Thật sự là ngươi sao?"
  },
  AvgDialog_72009_Content_68 = {
    Text = "Mấy ngày không gặp đã bị thân thể bị ăn mòn đánh thành như vậy, khóa huấn luyện thể thuật của Misaque vẫn còn thiếu tinh thần tự lập."
  },
  AvgDialog_72009_Content_69 = {
    Text = "Dường như, đây không phải lúc để kể chuyện cũ."
  },
  AvgDialog_72009_Content_7 = {
    Text = "Không hổ là Người Giữ Gìn cuối cùng của Misaque, yêu cầu đưa ra vẫn gây khó dễ như vậy."
  },
  AvgDialog_72009_Content_70 = {
    Text = "Orci, chiến đấu vì chúa công !"
  },
  AvgDialog_72009_Content_71 = {
    Text = "Chiến đấu nào!"
  },
  AvgDialog_72009_Content_72 = {
    Text = "Để tiến lên một lần nữa."
  },
  AvgDialog_72009_Content_8 = {
    Text = "Làm không được à?"
  },
  AvgDialog_72009_Content_9 = {
    Text = "Tất nhiên là không. Tiệm nhỏ của Đào Đen Đá chắc chắn sẽ thực hiện được ước nguyện của bạn."
  },
  AvgDialog_72010_Content_1 = {
    Text = "Này, người Tây Khu, tôi có đang hoa mắt không?"
  },
  AvgDialog_72010_Content_10 = {
    Text = "Đầu tiên, có thể hoàn thành thiết kế và xây dựng công trình trong thời gian ngắn, khả năng kỹ thuật của người xây dựng thật sự ấn tượng."
  },
  AvgDialog_72010_Content_11 = {
    Text = "Thứ hai, người thiết kế chắc chắn phải am hiểu cấu trúc và chi tiết thiết kế của toàn bộ phòng thí nghiệm, từng sống lâu dài trong phòng thí nghiệm…"
  },
  AvgDialog_72010_Content_12 = {
    Text = "Như vậy suy đoán, người này nên là——"
  },
  AvgDialog_72010_Content_13 = {
    Text = "Ơ, ơ, %player%, sao bạn lại về rồi, nhanh, tranh thủ trước khi cô ấy phát hiện……"
  },
  AvgDialog_72010_Content_14 = {
    Text = "Wenkel xuất hiện từ góc quẹo, cầm thiết bị sức tính toán trong tay, vẻ mặt kinh ngạc khi chào bạn."
  },
  AvgDialog_72010_Content_15 = {
    Text = "Sau đó, ánh mắt của cô ấy hướng về phía bóng tối sau lưng bạn."
  },
  AvgDialog_72010_Content_16 = {
    Text = "Đồng tử của cô ấy co lại một cách đột ngột, vẻ mặt chuyển sang kinh hoàng, thiết bị trong tay rơi xuống đất với tiếng động lớn, các linh kiện kim loại bay tán loạn, phát ra âm thanh vang dội."
  },
  AvgDialog_72010_Content_17 = {
    Text = "Xin lỗi xin lỗi xin lỗi xin lỗi!! đóa, tôi không biết em ở đây, tôi không có ý định… xin lỗi xin lỗi xin lỗi!"
  },
  AvgDialog_72010_Content_18 = {
    Text = "Còn một điều cần phải nhắc nhở bạn——"
  },
  AvgDialog_72010_Content_19 = {
    Text = "Người xây dựng này nắm giữ tất cả các thiết bị hủy diệt có số lượng lớn và khổng lồ trong phòng thí nghiệm của tôi."
  },
  AvgDialog_72010_Content_2 = {
    Text = "Không... không có."
  },
  AvgDialog_72010_Content_20 = {
    Text = "Và có quyền hạn ngang bằng với tôi——"
  },
  AvgDialog_72010_Content_21 = {
    Text = "Bạn nói đúng chứ?"
  },
  AvgDialog_72010_Content_22 = {
    Text = "Cuối hành lang, từ từ bước ra một hình bóng giống hệt nhau.\nHai người nhìn nhau qua toàn bộ phòng thí nghiệm, như thể đang nhìn vào hình ảnh phản chiếu của chính mình trong một chiếc gương khổng lồ."
  },
  AvgDialog_72010_Content_23 = {
    Text = "\"một cái khác\" Meltdown·đóa."
  },
  AvgDialog_72010_Content_3 = {
    Text = "Phòng thí nghiệm từng sụp đổ thành đống đá vẫn giữ nguyên hình dạng xuất hiện ở góc đường, bạn chà mắt nhiều lần, xác nhận đây không phải ảo giác."
  },
  AvgDialog_72010_Content_4 = {
    Text = "Tôi có một giả thuyết. Chuột con, bạn hãy ở bên ngoài."
  },
  AvgDialog_72010_Content_5 = {
    Text = "Dùng đến tôi thì kéo tôi ra khỏi giường, không cần tôi nữa thì đuổi tôi đi, đâu có chuyện tốt như vậy!"
  },
  AvgDialog_72010_Content_6 = {
    Text = "Jenkin, ngoan. Em còn phải chăm sóc chị Mason thân mến nữa, chúng ta sẽ ra ngay đây."
  },
  AvgDialog_72010_Content_7 = {
    Text = "Nhưng không đơn giản như vậy.\nNói chung, chúng ta hãy cẩn thận đi vào nhé."
  },
  AvgDialog_72010_Content_8 = {
    Text = "Đã nửa tháng kể từ khi bạn tỉnh lại trong phòng thí nghiệm này, nhưng cảnh tượng trước mắt bạn hoàn toàn giống như khi bạn vừa tỉnh dậy."
  },
  AvgDialog_72010_Content_9 = {
    Text = "Có thể khôi phục hoàn toàn các công trình bị hỏng hóc hoàn toàn, điều này chứng tỏ người xây dựng có hai khả năng quan trọng."
  },
  AvgDialog_72011_Content_1 = {
    Text = "Chúng ta đã đánh mất"
  },
  AvgDialog_72011_Content_10 = {
    Text = "Rít… rít…"
  },
  AvgDialog_72011_Content_11 = {
    Text = "Chú chuột nhỏ lắc đầu, như thể đang phủ nhận câu hỏi của Jenkin."
  },
  AvgDialog_72011_Content_12 = {Text = "Jenkin!"},
  AvgDialog_72011_Content_13 = {
    Text = "Bạn ôm chầm lấy Jenkin."
  },
  AvgDialog_72011_Content_14 = {
    Text = "Thân thể gầy yếu của cô ấy bị bạn siết chặt trong vòng tay, nhỏ bé, chỉ chút xíu, nhưng lại ấm áp, mang theo sức sống, qua lớp xương sườn mỏng manh truyền đến nhịp tim an ủi."
  },
  AvgDialog_72011_Content_15 = {
    Text = "Làm gì vậy!! điên rồi à?! buông tôi ra!"
  },
  AvgDialog_72011_Content_16 = {
    Text = "Chưa đợi bạn và Jenkin giải thích, bên cạnh truyền đến tiếng rên khẽ."
  },
  AvgDialog_72011_Content_17 = {
    Text = "Ừ……ừ……"
  },
  AvgDialog_72011_Content_18 = {
    Text = "Tôi có đang ngủ không…… Không thể ngủ thêm…… Còn 20 bình đun cần làm, dung môi chế phẩm còn phải dự trữ 120 lít……"
  },
  AvgDialog_72011_Content_19 = {
    Text = "Đây là đâu?!\nCác bạn là ai?!"
  },
  AvgDialog_72011_Content_2 = {
    Text = "Ánh sáng trước mắt vừa xa lạ vừa quen thuộc."
  },
  AvgDialog_72011_Content_21 = {
    Text = "……………"
  },
  AvgDialog_72011_Content_22 = {
    Text = "Vậy, Jenkin, anh thực sự không thấy người thứ ba sao? Một nhà nghiên cứu tóc đỏ ngắn, hay giật mình…"
  },
  AvgDialog_72011_Content_23 = {
    Text = "Tôi sợ rằng điều này không lành mạnh, câu nói đó là gì nhỉ, tiết ai thuận biến, mong linh hồn cô ấy được an nghỉ?"
  },
  AvgDialog_72011_Content_24 = {
    Text = "Chuột nhỏ đeo mũ trùm đầu làm cử chỉ nhún vai."
  },
  AvgDialog_72011_Content_25 = {
    Text = "Nơi hai kẻ từ khu Tây bị đào lên, nói đúng hơn là một đống đá nhỏ chứ không phải phế tích."
  },
  AvgDialog_72011_Content_26 = {
    Text = "Nếu không phải brun đã kéo tôi và nói rằng có thứ gì đó bên trong, tôi mới lười đi lục lọi."
  },
  AvgDialog_72011_Content_27 = {
    Text = "Rồi… đóa, bạn đã hoàn toàn quên mất thí nghiệm độc ác của mình sao?"
  },
  AvgDialog_72011_Content_28 = {
    Text = "Mặc dù tôi thấy cáo buộc của bạn hoàn toàn vô lý, nhưng tôi phải nhắc nhở rằng, dùng quan niệm thiện ác của con người để đánh giá hành động của tôi là không hề phù hợp."
  },
  AvgDialog_72011_Content_29 = {
    Text = "Tôi không biết giữa các bạn có gì mâu thuẫn, nhưng, thì, đây có bánh mì."
  },
  AvgDialog_72011_Content_3 = {
    Text = "Này, người này có vẻ đã tỉnh."
  },
  AvgDialog_72011_Content_30 = {
    Text = "Nếu khát thì bên kia có nước, ừ, còn có một ít trà đen, và một đống đồ cao cấp mà tôi không nhận ra."
  },
  AvgDialog_72011_Content_31 = {
    Text = "Bạn… đã làm giàu rồi?"
  },
  AvgDialog_72011_Content_32 = {
    Text = "Gì lộn xộn vậy! Bạn không biết sao!"
  },
  AvgDialog_72011_Content_33 = {
    Text = "Sau đêm hôm đó, khi mọi người đều có những giấc mơ kỳ quái, phần lớn mọi người đã biến mất, bên ngoài đầy quái vật."
  },
  AvgDialog_72011_Content_34 = {
    Text = "May mắn thay, vì không còn ai, nên bánh mì miễn phí khắp nơi."
  },
  AvgDialog_72011_Content_35 = {
    Text = "Bạn... sao lại đến đây?"
  },
  AvgDialog_72011_Content_36 = {
    Text = "Bạn nhìn quanh, trong không gian nhỏ của tháp chuông có năm sáu giường tầng được bố trí gọn gàng."
  },
  AvgDialog_72011_Content_37 = {
    Text = "Tôi vốn chẳng muốn đến, chuột nhỏ sống trên phố vẫn rất vui vẻ. Chỉ có điều vào buổi tối, mấy kẻ ồn ào thật sự khiến người ta bực mình."
  },
  AvgDialog_72011_Content_38 = {
    Text = "Khi trèo lên cao để trốn, tôi đã tìm thấy nơi này. Phải leo thang, quái vật không thể lên được."
  },
  AvgDialog_72011_Content_39 = {
    Text = "Thật đáng tiếc, tôi phát hiện ra quá muộn, đã bị người khác chiếm mất rồi, đa số đều là những người bị thương hoặc có vấn đề về tâm lý."
  },
  AvgDialog_72011_Content_4 = {
    Text = "Một cái đầu nhỏ hiện ra trong tầm mắt của bạn."
  },
  AvgDialog_72011_Content_40 = {
    Text = "Có một cô chị tốt bụng cũng chuẩn bị cho tôi một chiếc giường, câu nói đó là \"Không làm thì phí mà làm thì có sao đâu?\""
  },
  AvgDialog_72011_Content_41 = {
    Text = "Jenkin, có khách đến không?"
  },
  AvgDialog_72011_Content_42 = {
    Text = "Hơi thở của bạn khựng lại."
  },
  AvgDialog_72011_Content_43 = {
    Text = "Ồ, xin lỗi, tiếp đãi không chu đáo, tôi sẽ đi pha trà cho các bạn ngay."
  },
  AvgDialog_72011_Content_44 = {
    Text = "Chị gái! Họ có tay có chân, không cần chị chăm sóc."
  },
  AvgDialog_72011_Content_45 = {
    Text = "Đúng rồi, đây là chị gái của tôi, Mason, cô ấy hiện đang trông có vẻ kỳ lạ, nhưng nếu các người dám coi cô ấy là quái vật, tôi sẽ không để các người yên đâu!"
  },
  AvgDialog_72011_Content_47 = {
    Text = "Có chuyện gì với bạn vậy? Tình cảm sâu đậm giữa chị em, bạn lần đầu tiên thấy à?"
  },
  AvgDialog_72011_Content_48 = {
    Text = "Gì mà chị em, mắt cậu có vấn đề à!? Tôi là con gái, con gái!"
  },
  AvgDialog_72011_Content_49 = {
    Text = "Mọi thứ đã trở lại, giống như khi bạn gặp cô ấy lần đầu.\nBạn đã lau nước mắt ở góc mắt."
  },
  AvgDialog_72011_Content_5 = {
    Text = "Nếu đã tỉnh thì đi tắm đi, ngay cả chuột ở London cũng không chịu nổi bụi bẩn trên người bạn nữa."
  },
  AvgDialog_72011_Content_50 = {
    Text = "Xin lỗi, tôi đã không giữ được bình tĩnh, chỉ là không ngờ lại gặp lại các bạn…"
  },
  AvgDialog_72011_Content_51 = {
    Text = "Lại nữa? Vị {Male=ngài,Female=cô} này, chúng ta đã từng gặp nhau chưa? Rất xin lỗi, sau khi chữa trị, tôi có rất nhiều ký ức bị rối loạn…"
  },
  AvgDialog_72011_Content_52 = {
    Text = "Không, điều đó không quan trọng… Biết các người còn sống thì tốt rồi…"
  },
  AvgDialog_72011_Content_54 = {
    Text = "……………"
  },
  AvgDialog_72011_Content_55 = {
    Text = "Tôi không biết chị ấy dùng cách gì, tóm lại tôi đã kể chuyện về chị gái cho cô ấy nghe, và cô ấy đã giúp tôi đưa chị gái về."
  },
  AvgDialog_72011_Content_56 = {
    Text = "Chị gái…… mặc dù đôi khi có vẻ lo lắng và sụp đổ, nhưng khi ở trạng thái tốt, chị vẫn rất dịu dàng và tốt bụng, rất tốt với tôi và những người khác……"
  },
  AvgDialog_72011_Content_57 = {
    Text = "Bạn nói về chị lớn đó... cô ấy tên là gì?"
  },
  AvgDialog_72011_Content_58 = {
    Text = "Ể, tôi vừa mới không nói sao?"
  },
  AvgDialog_72011_Content_59 = {
    Text = "Clementine, tên là Clementine."
  },
  AvgDialog_72011_Content_6 = {
    Text = "Chít chít!"
  },
  AvgDialog_72011_Content_60 = {Text = "!"},
  AvgDialog_72011_Content_62 = {
    Text = "Vậy, nếu mối quan hệ giữa cô ấy và Rogers như tôi dự đoán… liệu có phải Clementine đã cứu Mason khỏi Hiệp hội Điêu khắc gia không?"
  },
  AvgDialog_72011_Content_63 = {
    Text = "Hội điêu khắc, những con bọ sống sót một cách hèn nhát sao?\nBị lẫn lộn với những gã đó, dù không phải giường bọ, bọ ve, cũng sẽ là những thứ bẩn thỉu như đỉa, ruồi bò."
  },
  AvgDialog_72011_Content_64 = {
    Text = "Bạn đã vội vàng đưa ra phát ngôn như vậy, thật sự có chút thiếu lịch sự đấy, cô gái nhỏ đáng yêu ạ."
  },
  AvgDialog_72011_Content_65 = {
    Text = "Người phụ nữ mặc áo trắng lặng lẽ và nhẹ nhàng xuất hiện phía sau bạn."
  },
  AvgDialog_72011_Content_66 = {
    Text = "Một tiếng vo ve chui vào đầu bạn, cảnh tượng trước mắt bị bóp méo."
  },
  AvgDialog_72011_Content_67 = {
    Text = "Các người còn bị tôi lục lọi từ đống đổ nát hỗn độn, rồi vất vả mang lên đỉnh tháp chuông này, lo sợ rằng các người sẽ bị những con quái vật phun bùn đen nuốt chửng còn sống…"
  },
  AvgDialog_72011_Content_68 = {
    Text = "Đền ơn báo oán thì không tốt chút nào, phải không các bạn?"
  },
  AvgDialog_72011_Content_69 = {
    Text = "Tiếng chuông cảnh báo trong lòng bạn vang lên, bạn quay người đối mặt với cô ấy, chiếc chìa khóa bạc giương cao ánh sáng triệu hồi.\nTrước khi bạn ra tay, một bóng hình nhỏ bất ngờ lao ra, chắn trước người phụ nữ trong bộ đồ trắng."
  },
  AvgDialog_72011_Content_7 = {
    Text = "Triển…… kim……"
  },
  AvgDialog_72011_Content_70 = {
    Text = "Cô Clementine là ân nhân của tôi và chị gái, không được phép các người làm hại cô ấy!"
  },
  AvgDialog_72011_Content_8 = {Text = "?！"},
  AvgDialog_72011_Content_9 = {
    Text = "Cậu này, cậu biết tôi từ đâu vậy? Mặt tôi có viết tên à, Brun?"
  },
  AvgDialog_72012_Content_1 = {
    Text = "Giấc mơ sâu"
  },
  AvgDialog_72012_Content_10 = {
    Text = "Bạn lại bắt đầu nói những lời kỳ lạ mà tôi không hiểu."
  },
  AvgDialog_72012_Content_11 = {
    Text = "Không sao cả, những điều này vốn không phải là những thứ mà trẻ em nên gánh vác."
  },
  AvgDialog_72012_Content_12 = {
    Text = "Chị gái, em còn có một việc cần hỏi chị."
  },
  AvgDialog_72012_Content_13 = {
    Text = "Bệnh của cô Sara không thể chữa khỏi, phải không?"
  },
  AvgDialog_72012_Content_14 = {
    Text = "Clementine vuốt ve sau gáy của Jenkin."
  },
  AvgDialog_72012_Content_15 = {
    Text = "Nếu %player% hỏi, hãy trả lời {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_72012_Content_16 = {
    Text = "\"Ở đáy giấc mơ sâu thẳm, người không muốn chìm vào giấc mơ sẽ cho bạn câu trả lời.\""
  },
  AvgDialog_72012_Content_17 = {
    Text = "Tôi đi đây, Jenkin."
  },
  AvgDialog_72012_Content_18 = {
    Text = "Cô ấy thanh thoát nhảy xuống bậc thang của tháp đồng hồ, đôi cánh ánh sáng trong suốt từ từ mở ra sau lưng cô."
  },
  AvgDialog_72012_Content_19 = {
    Text = "Nguyện gió này nâng chúng ta, đến giấc mơ vĩnh cửu sâu thẳm."
  },
  AvgDialog_72012_Content_2 = {
    Text = "Ai ở đó…?!"
  },
  AvgDialog_72012_Content_21 = {
    Text = "Cô Sara, chúng ta cần chuẩn bị xuất phát đến Đền Thánh Cứu Thế."
  },
  AvgDialog_72012_Content_22 = {
    Text = "Có thể không rời khỏi đây không? Tôi sợ khi các bé trở về sẽ không tìm thấy tôi…"
  },
  AvgDialog_72012_Content_23 = {
    Text = "Được rồi… nhưng trước đó, có thể đưa tôi đến văn phòng viện trưởng một lần nữa không?"
  },
  AvgDialog_72012_Content_24 = {
    Text = "Tôi có một số thứ, muốn lấy lên…"
  },
  AvgDialog_72012_Content_25 = {
    Text = "Có thật không, văn phòng của bạn gần đây đầy đống đồ lớn đó!"
  },
  AvgDialog_72012_Content_26 = {
    Text = "Mặc dù tôi rất muốn phủ nhận ý nghĩa vô bổ của việc các vị theo đuổi vật chất trong thế giới này, nhưng nói chung lại, việc các vị đi đâu không quan trọng với tôi."
  },
  AvgDialog_72012_Content_27 = {
    Text = "Một phiếu ủng hộ, một phiếu phản đối, một phiếu trung lập.\nBa ánh mắt đều đổ dồn vào bạn."
  },
  AvgDialog_72012_Content_28 = {
    Text = "Đi thôi, cứ xem thử rồi tính tiếp."
  },
  AvgDialog_72012_Content_29 = {
    Text = "Sara gắng gượng giữ thăng bằng, lảo đảo bước tới bàn làm việc. Cô loạng choạng rồi ngã dựa vào cạnh bàn, cố gắng hổn hển lấy lại hơi thở."
  },
  AvgDialog_72012_Content_3 = {
    Text = "Đừng lo, Jenkin, là tôi."
  },
  AvgDialog_72012_Content_30 = {Text = "Đây."},
  AvgDialog_72012_Content_31 = {
    Text = "Một tiếng \"xoạt\" vang lên, ngăn kéo gỗ được kéo ra vội vàng, những chiếc vòng tay bạc và vàng cũ kỹ, ghim ngực, nhẫn... vung vãi khắp nơi một cách lộn xộn."
  },
  AvgDialog_72012_Content_32 = {
    Text = "Sara nằm trên mặt đất, cố gắng thu thập chúng lại từng cái một."
  },
  AvgDialog_72012_Content_33 = {
    Text = "Đến lúc này rồi, thu thập những thứ này còn có ý nghĩa gì, người ngoài kia đã…… hức hức hức!"
  },
  AvgDialog_72012_Content_34 = {
    Text = "Phá hủy · đóa một tay kéo Jenkin, nhét một vật chứa não kỳ lạ vào miệng cô ấy."
  },
  AvgDialog_72012_Content_35 = {
    Text = "Đừng nói lúc không cần thiết, đừng xen vào nhiều quá."
  },
  AvgDialog_72012_Content_36 = {
    Text = "Ừ, ừ... Ha!"
  },
  AvgDialog_72012_Content_37 = {
    Text = "Cô ấy vật lộn để lấy dị vật ra, thở gấp."
  },
  AvgDialog_72012_Content_38 = {
    Text = "Này, dù muốn tôi im miệng thì cũng hãy đưa cho tôi thứ ngon hơn đi! Thứ này vị như một con sên nhầy nhụa, thật kinh tởm!"
  },
  AvgDialog_72012_Content_39 = {
    Text = "Xin lỗi, quên rằng bạn không có chức năng tắt các cảm biến khứu giác và vị giác."
  },
  AvgDialog_72012_Content_4 = {
    Text = "Chị Clementine!"
  },
  AvgDialog_72012_Content_40 = {
    Text = "Được rồi, tôi không thích thường xuyên đứng yên một chỗ."
  },
  AvgDialog_72012_Content_41 = {
    Text = "Đồ vật đã lấy hết rồi chứ? Nếu đã lấy hết rồi thì chúng ta đi nhà thờ nhé."
  },
  AvgDialog_72012_Content_42 = {
    Text = "Những kẻ thành thạo chiến đấu, hãy mở đường!"
  },
  AvgDialog_72012_Content_5 = {
    Text = "Cô gái trẻ vui vẻ lao tới."
  },
  AvgDialog_72012_Content_6 = {
    Text = "Chào Jenkin, chị đến đây để tạm biệt em."
  },
  AvgDialog_72012_Content_7 = {
    Text = "Tại sao? Tại sao phải đi? Nếu là vì gã phương Tây kia, tôi sẽ bảo Brun đuổi {Male=anh ấy,Female=cô ấy} đi!"
  },
  AvgDialog_72012_Content_8 = {
    Text = "Dù sao {Male=anh ấy,Female=cô ấy} trông hoàn toàn có thể tự xử lý những con quái vật."
  },
  AvgDialog_72012_Content_9 = {
    Text = "Không, đương nhiên không phải… Chỉ là tôi nghe thấy tiếng gió trong giấc mơ."
  },
  AvgDialog_72013_Content_1 = {
    Text = "Người thân thiện và dũng cảm"
  },
  AvgDialog_72013_Content_10 = {
    Text = "Brun quay người lại, nhảy lên vai bạn, dùng chiếc mũi nhỏ nhọn của mình khẽ chạm vào má bạn và hít nhẹ."
  },
  AvgDialog_72013_Content_11 = {
    Text = "Chuột can đảm.."
  },
  AvgDialog_72013_Content_12 = {
    Text = "Vuốt ve đầu nó"
  },
  AvgDialog_72013_Content_13 = {
    Text = "Bạn nhẹ nhàng vuốt ve đầu nhỏ của nó, và nó ngước lên nhìn bạn và đáp lại."
  },
  AvgDialog_72013_Content_14 = {
    Text = "Trong ký ức, đây là lần đầu tiên bạn và người đó gần gũi như vậy."
  },
  AvgDialog_72013_Content_15 = {
    Text = "Nhìn thẳng vào nó"
  },
  AvgDialog_72013_Content_16 = {
    Text = "Nó kêu lên một tiếng rít, quay mặt đi, lạch cạch chui vào mũ của Jenkin, ló nửa đầu ra nhìn bạn một cách thận trọng."
  },
  AvgDialog_72013_Content_17 = {
    Text = "Đi qua hành lang phía trước, đó là vị trí của tầng hầm."
  },
  AvgDialog_72013_Content_18 = {
    Text = "Jenkin và Brun thì thầm."
  },
  AvgDialog_72013_Content_19 = {
    Text = "Chít chít, chít chít!"
  },
  AvgDialog_72013_Content_2 = {
    Text = "Khói bụi ở đây chưa lên tới mắt cá chân.\nNâu nhảy qua nhảy lại trong đó, để lại những cái bẫy nhỏ."
  },
  AvgDialog_72013_Content_20 = {
    Text = "Nó nói gì?"
  },
  AvgDialog_72013_Content_21 = {
    Text = "Hừm. Tôi hỏi nó tại sao lại thân thiết với bạn như vậy, Brun nói rằng bạn là một người vô hại."
  },
  AvgDialog_72013_Content_22 = {
    Text = "Linh cảm của động vật luôn rất chính xác."
  },
  AvgDialog_72013_Content_23 = {
    Text = "Ít nói nhảm, ai biết được bạn đã dùng thủ đoạn gì."
  },
  AvgDialog_72013_Content_24 = {
    Text = "Jenkin mím môi một cách khó chịu, nhưng trong khoảnh khắc tiếp theo, mắt anh ta tròn xoe vì ngạc nhiên."
  },
  AvgDialog_72013_Content_25 = {
    Text = "Cẩn thận!"
  },
  AvgDialog_72013_Content_26 = {
    Text = "Jenkin kéo bạn một cái, dòng chất lỏng phun ra trượt qua má bạn, rơi lên bức tường hành lang, mùi hôi thối lan tỏa khắp không gian, khiến người ta suýt nữa nôn ra dịch dạ dày."
  },
  AvgDialog_72013_Content_27 = {
    Text = "Những thân thể bị ăn mòn rỗng rỗng tụ tập lại, phát ra những tiếng kêu bi thương trên con đường trước mặt các bạn."
  },
  AvgDialog_72013_Content_28 = {
    Text = "Chẹp, con đường mà bạn dẫn này quá hẹp, không thể vòng qua được."
  },
  AvgDialog_72013_Content_29 = {
    Text = "Bạn đã sống sót kiểu này à?"
  },
  AvgDialog_72013_Content_3 = {
    Text = "Thật sự phải tìm kiếm gì đó… Sachiko giả ư?"
  },
  AvgDialog_72013_Content_30 = {
    Text = "Tất nhiên."
  },
  AvgDialog_72013_Content_31 = {
    Text = "Đây không đủ rộng… Chúng ta hãy dẫn những sinh vật biến dị này ra sân đi."
  },
  AvgDialog_72013_Content_4 = {
    Text = "Là người sống sót."
  },
  AvgDialog_72013_Content_5 = {
    Text = "Tôi đã lục soát khắp viện tế bần, ở đây chẳng có ai bình thường cả."
  },
  AvgDialog_72013_Content_6 = {
    Text = "Không…… còn một nơi nữa."
  },
  AvgDialog_72013_Content_7 = {
    Text = "Hình ảnh tầng hầm hiện lên trước mắt bạn."
  },
  AvgDialog_72013_Content_8 = {
    Text = "Nhà điêu khắc yên lặng, Sơn, cô ấy có còn ở đó để thực hiện những tác phẩm điêu khắc vô lý không?"
  },
  AvgDialog_72013_Content_9 = {
    Text = "Brun, chờ tôi!"
  },
  AvgDialog_73775_Content_1 = {
    Text = "……Ramona."
