  AvgDialog_73782_Content_30 = {Text = "!!!"},
  AvgDialog_73782_Content_31 = {
    Text = "Bạn bất ngờ kinh hoàng, đưa tay chạm vào đằng sau đầu nhỏ William.\nỞ đó, ẩm ướt và nóng hổi, như đang chuẩn bị cho điều gì đó."
