  },
  AvgDialog_73782_Content_36 = {
    Text = "Tiểu William không thể nhịn được mà sờ vào sau gáy, nơi đó máu không ngừng trào ra làm ướt tay anh, khiến anh cảm thấy đau đớn không thể chịu đựng được."
