  AvgDialog_73782_Content_43 = {
    Text = "Tiếng gọi từ thế giới khác như sấm sét, khiến bạn đứng khựng lại. Trong khoảnh khắc bạn ngẩn người, cậu bé William đã chạy ra ngoài và đóng sầm cửa phòng."
