  AvgDialog_73782_Content_49 = {
    Text = "Như bạn nói, điều quan trọng là tương lai, và đó cũng là điều chúng ta hướng tới."
  },
  AvgDialog_73782_Content_5 = {
    Text = "Không cần an ủi tôi… Trong viện điều dưỡng này, sẽ không có nơi nào an toàn."
  },
  AvgDialog_73782_Content_50 = {
    Text = "Thì quay lại. Đợi tôi dẫn dụ Clementine đi, tôi sẽ trở lại tìm cậu, chúng ta…"
  },
  AvgDialog_73782_Content_51 = {
    Text = "Chúng ta hãy cùng nhau giải quyết nơi này, rời đi cùng nhau, và tạo nên một tương lai tươi sáng."
  },
  AvgDialog_73782_Content_52 = {
    Text = "Bạn đang lẩn tránh vấn đề, %player%. Chúng ta đang ở trên địa bàn của Clementine, và cô ấy sẽ không dễ dàng để chúng ta rời đi."
