  AvgDialog_73782_Content_55 = {
    Text = "Nhỏ William nghẹn ngào một chút, dùng tay che mắt——những kỷ niệm thoáng qua dần dần hiện lên trong tâm trí cậu."
  },
  AvgDialog_73782_Content_56 = {
    Text = "Thế giới này đang bốc cháy, %player%, còn tôi, trong những ký ức còn lại, đã tận mắt chứng kiến nó bốc cháy."
  },
  AvgDialog_73782_Content_57 = {
    Text = "Tiểu Bill, kẻ dọn đường trên con phố bẩn thỉu và hôi hám nhất London, chỉ cần một phần tư xu là có thể chạy suốt một cây số không ngừng nghỉ để gửi một tờ giấy nhắn."
  },
  AvgDialog_73782_Content_58 = {
    Text = "Nisa Smith, con gái của công nhân giặt là, mới chỉ 11 tuổi, để phụ giúp gia đình, ngoài việc làm công việc gọi dậy, cô còn nhặt rác, bán diêm, làm tất cả những công việc có thể kiếm tiền."
  },
  AvgDialog_73782_Content_59 = {
    Text = "Còn có Henry, lái xe ngựa công cộng, làm việc từ 4 giờ sáng đến nửa đêm, một lần làm việc 20 giờ, ước nguyện chỉ là được ăn một con ngỗng nướng hoàn chỉnh vào Giáng sinh."
  },
  AvgDialog_73782_Content_60 = {
    Text = "Còn rất nhiều người tôi có thể gọi tên và nhớ mặt, họ……đều biến mất……"
