  AvgDialog_73782_Content_61 = {
    Text = "Nhưng có lẽ những người ở đây vẫn còn hy vọng. Khi khám phá viện dưỡng lão trước đó, tôi đã thấy nhiều bệnh nhân vừa mới vào đây, họ khao khát rời khỏi nơi này và mong muốn sống tiếp."
  },
  AvgDialog_73782_Content_62 = {
    Text = "Thế giới này đang cháy\nNhững người đang sống chỉ là củi, thoáng chốc đã biến mất"
  },
  AvgDialog_73782_Content_63 = {
    Text = "Nhưng thế giới không nên như vậy ——"
  },
  AvgDialog_73782_Content_64 = {
    Text = "Những người cười, những người giận dữ, những người buồn, những người đầy kỳ vọng...\nTất cả đều đã tàn lụi, không còn tồn tại"
  },
  AvgDialog_73782_Content_65 = {
    Text = "Những người đó không nên biến mất dễ dàng như vậy, sự tồn tại của họ không nên bị xóa bỏ một cách dễ dàng…"
