  AvgDialog_73783_Content_77 = {
    Text = "%player%,bạn không cần phải phân biệt giữa con người và sâu bọ, bạn chỉ cần giữ vững những gì bạn muốn theo đuổi."
  },
  AvgDialog_73783_Content_78 = {
    Text = "Ví dụ, sự nhận thức bản thân và linh hồn của con người."
  },
  AvgDialog_73783_Content_8 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} không phải là kẻ phản bội, anh ấy/cô ấy là bạn của tôi."
  },
  AvgDialog_73783_Content_80 = {
    Text = "… bạn tại sao lại giúp tôi? Tôi muốn nói là, chúng ta mới vừa gặp nhau, và thái độ của tôi…"
  },
  AvgDialog_73783_Content_81 = {
    Text = "Bởi vì, tôi cũng đang kiên trì với những điều tôi muốn theo đuổi."
  },
  AvgDialog_73783_Content_82 = {
    Text = "Chỉ có hai chúng ta ở đây, và tôi luôn mong có một người bạn."
  },
  AvgDialog_73783_Content_83 = {
    Text = "Con người dù tàn nhẫn, nhưng cũng có mặt chân thành và tốt bụng, sẽ giúp đỡ và hỗ trợ nhau, cùng vượt qua khó khăn, đón chào bình minh tươi sáng và tương lai tốt đẹp."
  },
  AvgDialog_73783_Content_84 = {
    Text = "Và đây, chính là bằng chứng —— bằng chứng về sự giúp đỡ lẫn nhau và lòng nhân ái của chúng ta."
  },
  AvgDialog_73783_Content_85 = {
    Text = "Con côn trùng đang chờ đợi để phá kén, đã nằm gọn trong lòng bàn tay bạn."
  },
  AvgDialog_73783_Content_87 = {
    Text = "……Cảm ơn."
  },
  AvgDialog_73783_Content_88 = {
    Text = "Bạn nhìn vào con côn trùng, rồi im lặng."
  },
  AvgDialog_73783_Content_89 = {
    Text = "Khi bạn định nói gì đó, Clementine bỗng nhiên ngẩng đầu lên."
  },
  AvgDialog_73783_Content_9 = {
    Text = "\"Một Clemantine khác nắm lấy Oliver, sau đó Oliver ngẩng đầu một cách không tự nhiên, dường như rơi vào trạng thái treo, vài giây sau mới phản ứng lại.\""
  },
  AvgDialog_73783_Content_90 = {Text = "!!!"},
  AvgDialog_73783_Content_91 = {
    Text = "Cô ấy đã phát hiện ra tôi. Tôi phải trốn đi!"
