  AvgDialog_73783_Content_98 = {
    Text = "Không, bây giờ không có thời gian để nghĩ đến việc này, quan trọng nhất là tìm chìa khóa bạc."
  },
  AvgDialog_73783_Content_99 = {
    Text = "Đêm khuya, khi mọi người đều đã ngủ, lực giám sát sẽ yếu nhất. Lúc đó, tôi sẽ dùng tinh thần để truy tìm chìa khóa bạc."
