  AvgDialog_73784_Content_11 = {
    Text = "Tôi cảm thấy."
  },
  AvgDialog_73784_Content_12 = {
    Text = "Nói thật, tôi rất tò mò không biết con sâu thứ hai rơi vào lưới là ai."
  },
  AvgDialog_73784_Content_13 = {
    Text = "Ánh sáng lặng lẽ bừng sáng, chiếu rọi nụ cười tò mò và hiếu kỳ của Klémentin."
  },
  AvgDialog_73784_Content_14 = {Text = "Dù ai..."},
  AvgDialog_73784_Content_15 = {
    Text = "Tôi rất hoan nghênh."
  },
  AvgDialog_73784_Content_16 = {
    Text = "Tiếng kêu của côn trùng vang khắp nơi."
  },
  AvgDialog_73784_Content_17 = {
    Text = "Tiếng rít kỳ quái gây ra sự ghê tởm sinh lý lan tỏa trong huyết quản, trong gân mạch của bạn, theo dòng máu tuôn chảy, len lỏi vào não bộ của bạn."
  },
  AvgDialog_73784_Content_18 = {
    Text = "Nó đang khuấy động não bạn, nó đang phá hủy não bạn, nó đang —— tái tạo não bạn."
  },
  AvgDialog_73784_Content_19 = {
    Text = "……kiểm tra thông tin, kiểm tra thông tin."
  },
  AvgDialog_73784_Content_2 = {
    Text = "Đôi mắt"
  },
  AvgDialog_73784_Content_20 = {
    Text = "Có thể nghe thấy giọng của tôi không?"
  },
  AvgDialog_73784_Content_21 = {
    Text = "……có thể."
  },
  AvgDialog_73784_Content_22 = {
    Text = "Bạn thở sâu, nhịn cơn đau đầu, buộc mình tỉnh táo.\nCuối cùng, tiếng kêu ghê tởm của côn trùng đã biến mất."
  },
  AvgDialog_73784_Content_23 = {
    Text = "Bạn thấy mình đang đứng trong một tòa nhà giống như một trung tâm chăm sóc sức khỏe, hành lang tĩnh lặng và rộng rãi với vô số cánh cửa hai bên, kéo dài đến bóng tối ở xa."
  },
  AvgDialog_73784_Content_24 = {
    Text = "Một viện dưỡng lão? Tại sao tôi lại ở đây……"
  },
  AvgDialog_73784_Content_25 = {
    Text = "Bạn đang hỏi tôi? Có lẽ tôi nên tìm cơ hội kiểm tra thân thể của bạn, xem thử mô-đun ký ức của bạn có vận hành bình thường không."
  },
  AvgDialog_73784_Content_26 = {
    Text = "…Có lẽ tôi không có mô-đun ký ức nào."
  },
  AvgDialog_73784_Content_27 = {
    Text = "Điều đó không quan trọng. Điều quan trọng là bạn có tìm thấy William không?"
  },
  AvgDialog_73784_Content_28 = {
    Text = "<Yellow:Uy Liêm>……Đúng, tôi đến tìm <Yellow:Uy Liêm>."
  },
  AvgDialog_73784_Content_29 = {
    Text = "Xem ra hiện tại chưa có gì tiến triển."
  },
  AvgDialog_73784_Content_3 = {
    Text = "Trong căn phòng tối tăm và kỳ bí, vô số đôi mắt đang nhìn chằm chằm vào người sống sót duy nhất.\nLúc này, có tiếng bước chân vang lên, người sống sót thứ hai xuất hiện."
  },
  AvgDialog_73784_Content_30 = {
    Text = "Dựa theo huy hiệu của Misaque, việc chế tạo thiết bị liên lạc để bạn hành động riêng lẻ là lựa chọn đúng đắn."
