  AvgDialog_73784_Content_31 = {
    Text = "Bộ thông tin? Tôi thấy chắc là bộ giám sát mới đúng."
  },
  AvgDialog_73784_Content_32 = {
    Text = "Đều như nhau. Bạn là thành quả thí nghiệm quan trọng của tôi, phải luôn nằm trong tầm kiểm soát của tôi."
  },
  AvgDialog_73784_Content_33 = {
    Text = "Thực tế, nếu không phải bắt buộc phải xây lại phòng thí nghiệm, và bạn nhất định muốn đi tìm William, tôi sẽ không để bạn rời khỏi tầm mắt của tôi."
  },
  AvgDialog_73784_Content_34 = {
    Text = "Tôi còn có thể nói gì… cảm ơn vì sự ủng hộ của bạn?"
  },
  AvgDialog_73784_Content_35 = {
    Text = "Không cần cảm ơn, nếu cần gì thì cứ liên hệ với tôi nhé."
  },
  AvgDialog_73784_Content_36 = {
    Text = "Tôi vẫn có thể dành thời gian để chăm sóc chó con của mình."
  },
  AvgDialog_73784_Content_37 = {
    Text = "Sau đó, liên lạc hoàn toàn bị cắt đứt, bốn phía lại yên tĩnh."
  },
  AvgDialog_73784_Content_38 = {
    Text = "……thôi, cứ nghĩ cách tìm William đã."
  },
  AvgDialog_73784_Content_39 = {
    Text = "Lúc đầu, tôi nhìn thấy bóng dáng giống William, sau đó đuổi theo anh ta vào rừng…"
