  AvgDialog_73784_Content_5 = {
    Text = "Ánh sáng có thể kích thích lý trí của con người, trong lúc tận hưởng thời gian, tôi vô tình kích hoạt những điều này."
  },
  AvgDialog_73784_Content_50 = {
