  },
  AvgDialog_73784_Content_51 = {
    Text = "Đoàng đoàng đoàng——\nVừa lúc đó, một bác sĩ đeo khẩu trang đi qua gần đó."
  },
  AvgDialog_73784_Content_52 = {
