  },
  AvgDialog_73784_Content_6 = {
    Text = "Hơn nữa, bóng tối sẽ khiến những nỗi đau và tuyệt vọng trong ký ức trở nên ngon lành hơn."
  },
  AvgDialog_73784_Content_60 = {
