  AvgDialog_73784_Content_65 = {
    Text = "@3 giữ lại @2"
  },
  AvgDialog_73784_Content_66 = {
    Text = "Trong tiếng kêu gào phỉ báng này, thêm nhiều bác sĩ xuất hiện, kéo bạn mạnh mẽ vào phòng gần nhất."
  },
  AvgDialog_73784_Content_68 = {
    Text = "Bạn không dám hành động khinh suất——vô số chân giáp xác đâm xuyên qua hai cánh tay của bạn, thậm chí làm vỡ xương cánh tay."
  },
  AvgDialog_73784_Content_69 = {
