  AvgDialog_73784_Content_73 = {
    Text = "<Shake:lăn……>"
  },
  AvgDialog_73784_Content_74 = {
    Text = "Bạn nén đau đớn để chạm vào chìa khóa bạc. Giờ đây, trong cơn đau tột độ và ý thức mơ hồ, bạn cần nó trợ giúp."
  },
  AvgDialog_73784_Content_75 = {
