  },
  AvgDialog_73784_Content_77 = {
    Text = "Bóng tối ngày càng tiến sát, những râu côn trùng đã liếm nhớp nháp lên đỉnh đầu của bạn."
  },
  AvgDialog_73784_Content_78 = {
    Text = "Đầu bạn đột nhiên nhói đau, như thể có thứ gì đó xuyên qua lớp vỏ não, chạm tới tận sâu bên trong, và khoan thủng linh hồn."
