  AvgDialog_73787_Content_104 = {
    Text = "Ngươi nói cái gì?"
  },
  AvgDialog_73787_Content_105 = {
    Text = "Hãy chạy ngay… Chúng ta đã bị người đứng đầu thực sự của viện dưỡng lão phát hiện rồi…"
  },
  AvgDialog_73787_Content_106 = {
    Text = "William nhỏ không nghe thấy giọng của bạn, vì ngay khoảnh khắc đó, hành lang không thấy điểm cuối vang lên tiếng đập mạnh liên tiếp."
  },
  AvgDialog_73787_Content_107 = {
    Text = "Đó là âm thanh của trăm ngàn cánh cửa mở ra. Đó cũng là tiếng động của viện dưỡng lão thức dậy, chuẩn bị nuốt chửng những kẻ phản nghịch."
  },
  AvgDialog_73787_Content_108 = {
    Text = "Một hồi chuông báo động chói tai vang lên, mở ra khung cảnh điên cuồng truy đuổi và chạy trốn."
  },
  AvgDialog_73787_Content_11 = {
    Text = "Đúng, bạn chỉ khiến họ mất ký ức, trở thành một tờ giấy trắng. Giống như Vilhelm."
  },
  AvgDialog_73787_Content_12 = {Text = "!!!"},
  AvgDialog_73787_Content_13 = {
    Text = "Nhưng thật đáng tiếc, sau khi tách khỏi họ, ký ức về sự hiện diện của họ chính là tất cả của tôi."
  },
  AvgDialog_73787_Content_14 = {
    Text = "Bạn ép mình bỏ qua cơn đau trong đầu, đưa tay về phía ngực ——"
  },
  AvgDialog_73787_Content_15 = {
    Text = "Rã nở·đóa, bạn có đang nghe không?"
