  AvgDialog_73787_Content_16 = {
    Text = "Tôi ở đây. Vẫn luôn ở đây."
  },
  AvgDialog_73787_Content_17 = {
    Text = "Vậy thì được, chuẩn bị kích hoạt chức năng đó."
  },
  AvgDialog_73787_Content_18 = {
    Text = "……Tôi nghĩ bạn sẽ không biết về chức năng đó."
  },
  AvgDialog_73787_Content_19 = {
    Text = "Thực ra, tôi biết rồi. Tôi đã lén lút xem bản thiết kế của bạn."
  },
  AvgDialog_73787_Content_2 = {
    Text = "Có lẽ chúng ta có thể tăng cường độ chữa trị lên một chút? Tôi còn hẹn, đang vội."
  },
  AvgDialog_73787_Content_20 = {
    Text = "Bàn tay bạn lướt qua chìa khóa bạc, đặt nó lên huy hiệu Misaque của bản sao đóa đã bị tan chảy, rồi ném về phía cửa."
