  AvgDialog_73787_Content_22 = {
    Text = "……Hừ."
  },
  AvgDialog_73787_Content_23 = {
    Text = "Tách tách, huy hiệu giả của Misaque phát ra dòng điện nhẹ khi bay theo đường parabol về phía Herbert."
  },
  AvgDialog_73787_Content_24 = {
    Text = "Hừ, chỉ là sự cố gắng vô vọng của kẻ sắp chết mà thôi."
  },
  AvgDialog_73787_Content_25 = {
    Text = "Herbert lùi lại một bước, nhưng huy hiệu vẫn còn ngay giữa trán, trán của một con mèo."
  },
  AvgDialog_73787_Content_26 = {
    Text = "Meo—— !!!"
  },
  AvgDialog_73787_Content_27 = {
    Text = "Dưới sự kích thích của dòng điện, con mèo hét lên và nhảy múa, chạy quanh phòng."
  },
  AvgDialog_73787_Content_28 = {
    Text = "Ga-la-tê! Các người đang làm gì vậy, còn không mau bắt nó lại."
  },
  AvgDialog_73787_Content_29 = {
    Text = "Không không, đừng thô bạo như vậy, hãy nhẹ nhàng một chút, nó là thú cưng yêu quý nhất của tôi ——"
  },
  AvgDialog_73787_Content_3 = {
    Text = "Herbert đứng ở cửa mỉm cười, lập tức, những cuộc tấn công của những người đã được cải tạo trở nên mãnh liệt."
  },
  AvgDialog_73787_Content_30 = {
    Text = "Có thể nói, hiện trường hỗn loạn như một nồi cháo, và đây chính là điều bạn cần."
  },
  AvgDialog_73787_Content_31 = {
    Text = "Dù trong trường hợp này, Herbert, anh cũng không vào căn phòng này. Có vẻ như giả thuyết của tôi là đúng rồi."
  },
  AvgDialog_73787_Content_32 = {Text = "……?"},
  AvgDialog_73787_Content_33 = {
    Text = "Đây là viện điều dưỡng tâm hồn, vì vậy bệnh nhân có phòng riêng tâm hồn, do đó bác sĩ có thể tự do ra vào bất kỳ phòng nào."
  },
  AvgDialog_73787_Content_34 = {
    Text = "Tôi và William là bệnh nhân, họ được coi là bác sĩ, nhưng bạn, Herbert —— bạn chỉ là chính mình."
  },
  AvgDialog_73787_Content_35 = {
    Text = "Vậy thì sao? Tôi không cần bất kỳ sự chữa trị nào."
  },
  AvgDialog_73787_Content_36 = {
    Text = "Điều này không chắc chắn—— William, làm đi."
  },
  AvgDialog_73787_Content_37 = {
    Text = "Nhận rồi~"
  },
  AvgDialog_73787_Content_38 = {
    Text = "William nhỏ len lén đến cửa và mỉm cười, rồi đẩy Herbert đang mất tập trung vào trong phòng."
  },
  AvgDialog_73787_Content_39 = {Text = "!!!"},
  AvgDialog_73787_Content_4 = {
    Text = "Không thể kéo dài thêm nữa. Chúng ta chỉ có hai người, còn hắn có cả một viện điều dưỡng trợ giúp."
  },
  AvgDialog_73787_Content_40 = {
    Text = "Khi Herbert bước vào phòng, bạn cảm nhận được tiếng vo ve quen thuộc —— dù là não bộ của bạn hay căn phòng này, đều đang vo ve."
  },
  AvgDialog_73787_Content_41 = {
    Text = "Cảnh trong phòng liên tục tan chảy, liên tục ngưng tụ, như thể bối rối không biết phản chiếu tâm hồn ai, khiến người ta cảm thấy choáng váng."
  },
  AvgDialog_73787_Content_42 = {
    Text = "%player%,lẹ ra đi, tôi muốn đóng cửa rồi!"
  },
  AvgDialog_73787_Content_43 = {
    Text = "William nhỏ đang đưa tay về phía bạn ở ngoài cửa, cùng lúc đó, một bàn tay khác cũng đưa về phía bạn ——"
  },
  AvgDialog_73787_Content_44 = {
    Text = "Tôi đã nói rằng mình có hẹn. Có lẽ, bạn thích hợp hơn tôi để ở lại đây."
  },
  AvgDialog_73787_Content_45 = {
    Text = "Tay đó từ phía sau ôm lấy cổ bạn, bắt đầu siết chặt, dùng sức, bạn không thể kiểm soát được mà ngã ra sau, quơ tay loạn xạ."
  },
  AvgDialog_73787_Content_46 = {
    Text = "Trong sự hoảng loạn, bạn dường như đã chạm vào thứ gì đó——"
  },
  AvgDialog_73787_Content_47 = {
    Text = "Khi ý thức ngày càng mơ hồ, bạn bị cuốn vào ký ức của ai đó."
  },
  AvgDialog_73787_Content_48 = {
    Text = "Tôi nghĩ rằng, sau khi hoàn thành tất cả các nhiệm vụ, tôi xứng đáng có một kỳ nghỉ tuyệt vời."
  },
  AvgDialog_73787_Content_49 = {
    Text = "Bạn nói đúng, Herbert, viện điều dưỡng là một sự lựa chọn không tồi."
  },
  AvgDialog_73787_Content_5 = {
    Text = "Phải tìm cách tấn công kẻ lạ mặt đứng ở cửa. Anh ta mới là chìa khóa."
  },
  AvgDialog_73787_Content_50 = {
    Text = "Thịt tôi đã no nê, nhưng tâm hồn tôi vẫn đang đói khát."
  },
  AvgDialog_73787_Content_51 = {
    Text = "Cố gắng chịu đựng... %player%, tôi sẽ bắt được.."
  },
  AvgDialog_73787_Content_52 = {
    Text = "Dường như có ai đó đang la hét, nhưng bạn không nghe rõ ."
  },
  AvgDialog_73787_Content_53 = {
    Text = "Trong đầu bạn như một cơn lốc màu sắc không ngừng xoay chuyển, tràn ngập những mảnh ký ức đan xen."
  },
  AvgDialog_73787_Content_54 = {
    Text = "Nhà thương này rất quan trọng đối với tôi, cực kỳ quan trọng, vậy nên Herbert, hãy cho tôi một lý do."
  },
  AvgDialog_73787_Content_55 = {
    Text = "Nếu không——tôi có thể mời bạn vào đây, cũng có thể mời bạn ra ngoài."
  },
  AvgDialog_73787_Content_56 = {
    Text = "Đây là một mắt xích trong kế hoạch, Clementine."
  },
  AvgDialog_73787_Content_57 = {
    Text = "Tôi biết bạn đang tiến hành những thí nghiệm quan trọng, nhưng tôi muốn nói rằng, mục tiêu của chúng ta không mâu thuẫn."
  },
  AvgDialog_73787_Content_58 = {
    Text = "Nếu chỉ có lý do này, có lẽ bạn sẽ không thuyết phục được tôi."
  },
  AvgDialog_73787_Content_59 = {
    Text = "Bạn cần lễ vật, rất nhiều lễ vật, và %player% rõ ràng phù hợp điều kiện, đúng không?"
  },
  AvgDialog_73787_Content_6 = {
    Text = "Quyết định thông minh, nhưng chỉ quyết định thôi thì chưa đủ để làm gì cả."
  },
  AvgDialog_73787_Content_60 = {
    Text = "Hơn nữa, bạn luôn rất quan tâm đến %player%, đây là một cơ hội, một cơ hội để lại gần và quan sát {Male=anh ấy,Female=cô ấy}."
  },
  AvgDialog_73787_Content_61 = {
    Text = "Tôi đã bắt được bạn!"
  },
  AvgDialog_73787_Content_62 = {Text = "Ugh…"},
  AvgDialog_73787_Content_63 = {
    Text = "Cẩn thận với răng của cậu, chúng không nên chạm vào cánh tay tôi."
  },
  AvgDialog_73787_Content_65 = {
    Text = "……………"
  },
  AvgDialog_73787_Content_66 = {
    Text = "Trong phòng khám tâm lý quen thuộc, Clementine im lặng, điều này khiến bạn cảm thấy lạ lẫm, dù đã quen với nhiều loại ký ức khác nhau."
  },
  AvgDialog_73787_Content_67 = {
    Text = "Lần ký ức này thật kỳ lạ.."
