  AvgDialog_73789_Content_1 = {
    Text = "Thí nghiệm tái cấu trúc nhận thức"
  },
  AvgDialog_73789_Content_10 = {
    Text = "Bạn ghim con quái vật vô nhân tính vào tường, dùng cánh tay bóp chặt cổ hắn."
  },
  AvgDialog_73789_Content_11 = {
    Text = "Câm miệng lại. Tôi hỏi, bạn trả lời."
  },
  AvgDialog_73789_Content_12 = {
    Text = "%player%, bạn có thể hỏi tôi bất kỳ điều gì bạn muốn, tôi rất sẵn lòng giải đáp cho bạn."
  },
  AvgDialog_73789_Content_13 = {
    Text = "Lúc này, bạn mới phát hiện ra rằng còn có người thứ ba ở đây."
  },
  AvgDialog_73789_Content_14 = {
    Text = "Clementine… Tôi đã thất bại sao? Vẫn còn ở trong bệnh viện?!"
