  },
  AvgDialog_73795_Content_15 = {
    Text = "Liệu có phải đang khiến bạn cảm thấy mâu thuẫn với nhận thức của chính mình, hay là đang khiến không gian tâm hồn này sụp đổ?"
  },
  AvgDialog_73795_Content_16 = {
    Text = "Bạn vẫn đầy tinh thần tò mò như vậy, tôi rất đánh giá cao. Chỉ có điều, thật tiếc, thời gian đã hết, nghi thức phải bắt đầu."
  },
  AvgDialog_73795_Content_17 = {
    Text = "Vào khoảnh khắc tiếp theo, Clementine khởi động bàn thờ, và bàn thờ, đầy cảm giác phi nhân loại, lập tức phát sáng."
  },
  AvgDialog_73795_Content_18 = {
    Text = "Sau đó, một loại kinh hoàng vô hình mang theo tiếng rít quái dị từ từ giáng xuống."
  },
  AvgDialog_73795_Content_19 = {
    Text = "Cảm giác trôi nổi quen thuộc lại đến, bạn cảm thấy cái gì đó đang biến mất —\nMột loại sinh mệnh vô danh đang vắt kiệt sự tồn tại của bạn, khiến bạn dần không còn giống chính mình."
  },
  AvgDialog_73795_Content_2 = {
    Text = "Lần nữa mở mắt, tầm nhìn của bạn bị chiếm đầy bởi một bàn thờ lạ lùng và kỳ bí."
  },
  AvgDialog_73795_Content_20 = {
    Text = "Đây là một sự thay đổi vô hình, nhưng bạn rõ ràng cảm nhận được sự sụp đổ của chính mình. Giống như một cỗ máy, một bánh răng tiếp theo một bánh răng khác bị xoắn vặn, chuyển hóa, biến dạng, cho đến khi hoàn toàn trở thành một con sâu."
  },
  AvgDialog_73795_Content_21 = {
    Text = "Nhưng con người không phải là máy móc."
  },
  AvgDialog_73795_Content_22 = {
    Text = "Trong ánh sáng đầy đau đớn, bạn nhìn những bóng dáng đang chìm sâu vào giấc ngủ — họ có thể chỉ là những người bình thường trong thế giới này, nhưng sức sống của họ, mỗi một người đều vô cùng quý giá."
  },
  AvgDialog_73795_Content_23 = {
    Text = "Sau khi vào viện điều dưỡng này, tôi luôn ở trong trạng thái bị động, bị động chia tay với William, bị động mất chìa khóa bạc, bị động nhìn một Clemence khác chết đi."
