  AvgDialog_73795_Content_24 = {
    Text = "Vì tôi mang trên mình sức sống của người khác, vì tôi sợ bản thân mắc sai lầm, dẫn đến hậu quả không thể khắc phục. Nhưng giờ đây, tôi mới nhận ra rằng sự do dự có thể khiến tôi mất đi nhiều hơn."
  },
  AvgDialog_73795_Content_25 = {
    Text = "Vì vậy, lần trước tôi không phản kháng. Bởi vì tôi phải ở đây, trong cái gọi là nghi lễ sự sống, đưa ra quyết đoán."
  },
  AvgDialog_73795_Content_26 = {
    Text = "Đưa ra quyết định? Tại sao phải tiếp tục đấu tranh? Trở thành đồng tộc của ta chẳng phải là điều tốt sao?"
  },
  AvgDialog_73795_Content_27 = {
    Text = "Thế giới không chỉ có nơi này, không chỉ có Trái Đất, mà còn có vũ trụ bao la. Hãy vượt qua sự yếu đuối của con người và hướng tới một vũ trụ vĩ đại và sâu thẳm hơn."
  },
  AvgDialog_73795_Content_28 = {
    Text = "Bạn nhắm mắt lại, thả lỏng ý thức để truy tìm đồ vật đã mất trên ngực —— không giữ lại gì, không e ngại điều gì."
  },
  AvgDialog_73795_Content_29 = {
    Text = "Con người thật sự yếu đuối, nhưng yếu đuối không có nghĩa là không kiên cường, không dũng cảm, không vĩ đại. Khi bản chất con người tỏa ánh sáng, ngay cả bóng tối sâu thẳm nhất cũng có thể được chiếu sáng."
  },
  AvgDialog_73795_Content_3 = {
    Text = "Bạn bị trói trên bàn thờ, cùng nhiều người đang chìm trong giấc ngủ, làm của lễ để đón chào nghi thức."
  },
  AvgDialog_73795_Content_30 = {
    Text = "Và ánh sáng của nhân tính, là lý trí, là đạo đức, là thiện lương, là chân thành, là vô tư, và quan trọng nhất, đó là lòng dũng cảm."
  },
  AvgDialog_73795_Content_31 = {
    Text = "Những ánh sáng này sẽ giúp mọi người hỗ trợ nhau, vượt qua khó khăn và chào đón bình minh tươi sáng cùng tương lai rạng rỡ."
  },
  AvgDialog_73795_Content_32 = {
    Text = "Đau đớn tột độ trong ý thức, tiếp theo là da thịt rỉ máu và nứt nẻ, nhưng bạn không dừng lại. Bạn đã hạ quyết tâm."
  },
  AvgDialog_73795_Content_33 = {
    Text = "Trả lời lời kêu gọi của tôi, chìa khóa bạc. Để cứu mọi người ."
