  AvgDialog_74778_Content_56 = {
    Text = "Dù tôi vẫn rất sợ hãi……\nNhưng trong vô thức có một giọng nói nói rằng, bạn sẽ mang đến ánh sáng cho tôi, cho thế giới này."
