  },
  AvgDialog_74779_Content_11 = {
    Text = "Thứ hai, người thiết kế chắc chắn phải am hiểu cấu trúc và chi tiết thiết kế của toàn bộ phòng thí nghiệm, từng sống lâu dài trong phòng thí nghiệm…"
