  AvgDialog_75907_Content_39 = {
    Text = "Do Liên Kết chiều hiện tại phụ thuộc vào bạc tâm được phóng vào mặt phẳng của đối phương, nên chỉ cần thu hồi bạc tâm đóng vai trò điểm neo là có thể làm suy yếu mối liên hệ giữa hai không gian."
  },
  AvgDialog_75907_Content_4 = {
    Text = "<Yellow:%player%>, bạn có thời gian bây giờ không?"
