  },
  AvgDialog_75907_Content_46 = {
    Text = "<Yellow:%player%> là đối tác của tôi, người bảo vệ bí mật của Misaque, không phải là một bậc thầy thẻ bài, {Male=anh ấy,Female=cô ấy} sẽ không đi đâu với bạn."
