  },
  AvgDialog_75915_Content_12 = {
    Text = "Như họ tin tưởng tôi, tôi… cũng tin tưởng vào thân thể được đánh thức của mình."
  },
  AvgDialog_75915_Content_13 = {
    Text = "Dù họ đã ngã xuống, nhưng tia hy vọng của chiến thắng mà họ mang lại đã sớm chiếu sáng con đường phía trước của tôi."
  },
  AvgDialog_75915_Content_14 = {
    Text = "<Big:<Yellow:lượt của tôi>! vẽ thẻ!!!>"
  },
  AvgDialog_75915_Content_15 = {
    Text = "(Chuyện gì vậy!! Cảm giác không ổn này!)"
  },
  AvgDialog_75915_Content_16 = {
    Text = "Bộ bài của bạn dường như phát ra ánh sáng chói lọi, một sức ép vô hình bao trùm cả sân, tất cả mọi người có mặt đều nín thở, căng thẳng chờ đợi hành động tiếp theo của bạn."
  },
  AvgDialog_75915_Content_17 = {
    Text = "Ignađis đã mất đi sự bình tĩnh vừa rồi, cô ấy có thể cảm nhận rõ ràng rằng, thẻ bài trong tay bạn mang trong mình lực lượng để chấm dứt tất cả điều này."
  },
  AvgDialog_75915_Content_18 = {
    Text = "……phương trình chiến thắng, đã hoàn thành."
  },
  AvgDialog_75915_Content_19 = {
    Text = "Nhìn vào lá bài cuối cùng trong tay, khóe miệng bạn hiện lên nụ cười vừa bí ẩn vừa tự tin."
  },
  AvgDialog_75915_Content_2 = {
    Text = "Sau một cuộc chiến đấu khốc liệt, tình hình hiện tại đối với bạn cực kỳ bất lợi."
  },
  AvgDialog_75915_Content_20 = {
    Text = "Ramona, sử dụng lưỡi dao Misaque."
  },
  AvgDialog_75915_Content_21 = {
    Text = "Lưỡi kiếm trong tay Ramona vung ra, ánh bạc lướt qua chiến trường, khắc lên người địch những vết thương mới."
  },
  AvgDialog_75915_Content_22 = {
    Text = "Kỹ năng mô phỏng lưỡi dao của Misaque, gây sát thương lên toàn bộ kẻ địch."
  },
  AvgDialog_75915_Content_23 = {
    Text = "Kích hoạt cơn thịnh nộ bùng phát! Sử dụng trí tuệ vô tận của bạn để khám phá thế giới đi, Ramona!"
  },
  AvgDialog_75915_Content_24 = {
    Text = "Ánh sáng lấp lánh trên người Ramona, khí thế của cô gái một lần nữa dâng lên, năng lượng đã cạn kiệt nay lại trở nên dồi dào."
  },
  AvgDialog_75915_Content_25 = {
    Text = "Kích hoạt lá bài thứ hai của Lưỡi gươm Misaque, cũng như lá bài thứ hai của Giả lập Diễn giải!"
  },
  AvgDialog_75915_Content_26 = {
    Text = "Sau bốn lần cuốn phăng chiến trường, mặc dù các nhân vật của Ignađis vẫn đứng vững, nhưng thể lực đã gần cạn kiệt."
  },
  AvgDialog_75915_Content_27 = {
    Text = "Ồ! Không ngờ bạn còn có lá bài như vậy… Có phải là cùng loại với Maxwell không…"
  },
  AvgDialog_75915_Content_28 = {
    Text = "Bây giờ, hai lá bài Lưỡi Dao Misaque đã được sử dụng sau khi giảm phí. Bộ bài của bạn vừa trải qua lần xáo trộn thứ ba."
  },
  AvgDialog_75915_Content_29 = {
    Text = "Vì vậy, phí hiện tại của bạn không đủ để đánh ra Lưỡi Dao Misaque thứ ba chưa được giảm phí, kết quả cuối cùng vẫn là tôi thắng!"
  },
  AvgDialog_75915_Content_3 = {
    Text = "Dù trạng thái của đối phương bị áp chế, nhưng lúc này trên sân của bạn chỉ còn lại Ramona, trong khi đối phương có nguồn lực dồi dào, đang chờ thời cơ."
  },
  AvgDialog_75915_Content_30 = {
    Text = "Vâng, phí hiện tại của tôi thực sự không đủ để đánh ra lá thứ ba của Misaque Blade. Tuy nhiên, nhờ bạn nhanh chóng đánh ngã các thân thể được đánh thức khác."
  },
  AvgDialog_75915_Content_31 = {
    Text = "Sau khi thân thể được đánh thức bị tiêu diệt, bộ bài sẽ không còn xuất hiện các thẻ bài của thân thể được đánh thức đó. Vì vậy, tôi chắc chắn sẽ rút được những thẻ bài mà tôi cần."
  },
  AvgDialog_75915_Content_32 = {
    Text = "Kích hoạt hai thẻ Tư Duy Hiệu Quả, khôi phục sức tính toán lên 6 điểm!"
  },
  AvgDialog_75915_Content_33 = {Text = "Gì vậy!"},
  AvgDialog_75915_Content_34 = {
    Text = "Tiếp nhận đi, lá bài cuối cùng của ta! Ramona, sử dụng lưỡi dao Misaque, chặt đứt mọi thứ cản đường chúng ta —— tất cả đều bị cắt ngang!"
  },
  AvgDialog_75915_Content_35 = {
    Text = "Cô gái trẻ nhảy múa nhẹ nhàng trên chiến trường, lưỡi kiếm Misaque cuối cùng xé toạc bầu trời."
  },
  AvgDialog_75915_Content_36 = {
    Text = "Thân thể được đánh thức của Ignađis không thể chịu nổi cú đánh chí mạng này và đã sụp đổ trong ánh bạc."
  },
  AvgDialog_75915_Content_37 = {
    Text = "Nhìn bốn ngôi mộ từ từ dựng đứng, Ignađis cảm thấy đầu óc trống rỗng. Cô không thể ngờ rằng mình, người vừa còn nắm giữ lợi thế áp đảo, lại có thể thất bại vì điều này."
  },
  AvgDialog_75915_Content_38 = {Text = "Ừm……"},
  AvgDialog_75915_Content_39 = {
    Text = "Tôi đã thắng, Ignadis."
  },
  AvgDialog_75915_Content_4 = {
    Text = "Ignađis mỉm cười nhìn bạn, toàn thân cô ấy toát lên vẻ thoải mái đến lạ kỳ, dường như chiến thắng đã nằm gọn trong tay cô ấy."
  },
  AvgDialog_75915_Content_40 = {
    Text = "Lâu sau, Ignađis mới lấy lại tinh thần sau thất bại, cô ấy thở dài và trở lại vẻ vui vẻ, sôi nổi như trước."
  },
  AvgDialog_75915_Content_41 = {
    Text = "……đúng vậy, tôi thua rồi, hì hì, bạn thật sự rất mạnh, đây là lần đầu tiên tôi thất bại trong cuộc đấu Bài Vạn Tượng."
  },
  AvgDialog_75915_Content_42 = {
    Text = "Quá khen rồi, có lẽ là do mối liên kết giữa tôi và các thân thể được đánh thức mạnh hơn."
  },
  AvgDialog_75915_Content_43 = {
    Text = "Tôi có thể cảm nhận được, trong trận đấu vừa qua bạn chưa quen thuộc với quy tắc của đối đầu pha."
  },
  AvgDialog_75915_Content_44 = {
    Text = "Sức sống của thân thể được đánh thức và giá trị của thẻ bài có sự khác biệt rõ rệt so với Bài Vạn Tượng, nếu thêm vài ván nữa, tôi thực sự không có tự tin để đánh bại bạn."
  },
  AvgDialog_75915_Content_45 = {
    Text = "Không được nói về bản thân như thế! Thắng là thắng, không cần phải an ủi tôi như vậy đâu."
  },
  AvgDialog_75915_Content_46 = {
    Text = "Này, nếu bạn tự hạ thấp mình như thế, chẳng phải là nói rằng tôi thua bạn bây giờ còn yếu hơn sao? Không ổn rồi!"
  },
  AvgDialog_75915_Content_47 = {
    Text = "Được rồi, theo như thỏa thuận, tôi sẽ khôi phục không gian này và sẽ không gây phiền phức cho các bạn nữa."
  },
  AvgDialog_75915_Content_48 = {
    Text = "Mặc dù……rất không cam lòng, hành trình của mình lại kết thúc như thế này. Rõ ràng còn muốn đấu bài với nhiều cao thủ hơn, muốn cho nhiều người biết đến Bài Vạn Tượng…"
  },
  AvgDialog_75915_Content_49 = {
    Text = "Tuy nhiên, ở cuối hành trình, có thể đối đầu với bạn như vậy thật sự khiến tôi rất hài lòng!"
  },
  AvgDialog_75915_Content_5 = {
    Text = "Bây giờ trên sân của bạn chỉ còn một người, trong khi các nhân vật của tôi dù tình trạng không tốt nhưng đều còn sống."
  },
  AvgDialog_75915_Content_50 = {
    Text = "Mắt Ignađis hơi đỏ, nhưng cô ấy cố gắng nặn ra một nụ cười."
  },
  AvgDialog_75915_Content_51 = {
    Text = "Có thể nói… là chuyện gì vậy, được không?"
  },
  AvgDialog_75915_Content_52 = {
    Text = "Bây giờ ấn tượng của bạn đối với tôi... không giống như người sẽ làm những việc bỏ qua nguyện vọng của người khác."
  },
  AvgDialog_75915_Content_53 = {
    Text = "Ignađis nhăn mũi, nói với vẻ mặt phức tạp."
  },
  AvgDialog_75915_Content_54 = {
    Text = "Thế giới của tôi từng trải qua một cuộc đại chiến, các anh hùng đã đấu tranh dũng cảm và cứu thế giới khỏi tay ma thần."
  },
  AvgDialog_75915_Content_55 = {
    Text = "Tôi là một trong những người đã trải qua cuộc chiến đó, muốn những huyền thoại về các anh hùng không bị lãng quên. Vì vậy, tôi đã tạo ra Bài Vạn Tượng và đồng thời thành lập quán rượu Vạn Tượng."
  },
  AvgDialog_75915_Content_56 = {
    Text = "Để nhiều người hơn biết đến câu chuyện của họ, quán rượu Vạn Tượng thường trú một cổng dịch chuyển liên kết với các thế giới khác, cho phép khách từ các thế giới khác đến quán rượu."
  },
  AvgDialog_75915_Content_57 = {
    Text = "Tôi tổ chức cuộc thi thẻ kỳ diệu, hy vọng bằng cách này truyền bá câu chuyện của đại lục Heppland. Như vậy những người, những điều đó mới có thể không bao giờ bị lãng quên."
  },
  AvgDialog_75915_Content_58 = {
    Text = "Đáng tiếc thay, việc kết nối các thế giới khác nhau đòi hỏi tiêu thụ rất nhiều tinh thể… Kết quả cuối cùng là, cả quán rượu đều lỗ vốn, không thể hoạt động lâu…"
  },
  AvgDialog_75915_Content_59 = {
    Text = "Tôi, Liyah, Betty... chúng tôi... chúng tôi thực sự, rất nhớ mỗi vị khách của quán rượu, mỗi vị đại sư thẻ bài."
  },
  AvgDialog_75915_Content_6 = {
    Text = "Bộ bài trong tay tôi đã sẵn sàng với các thành phần tiêu diệt, chỉ cần đến lượt tiếp theo, tôi có thể kết thúc trận đấu này theo kế hoạch đã định!"
  },
  AvgDialog_75915_Content_60 = {
    Text = "Nếu có thể, tôi muốn tiếp tục kinh doanh quán rượu Vạn Tượng mãi mãi, mãi."
  },
  AvgDialog_75915_Content_61 = {
    Text = "Không gian này là nỗ lực cuối cùng của tôi trước khi tinh thể cạn kiệt… Tôi muốn thử tìm một nơi khác có thể chứa quán rượu… nhưng vẫn không tìm được"
  },
  AvgDialog_75915_Content_62 = {
    Text = "Nói đến chuyện này, hồi đó có một con chó hôi thối đã hứa với tôi sẽ xây lại quán rượu, nhưng một ngày nọ nó đột nhiên nói có việc, biến thành một con mèo đen và chạy mất! Nếu một ngày nào đó tôi gặp lại nó, nhất định phải cho nó biết tay!"
  },
  AvgDialog_75915_Content_63 = {
    Text = "Có thể chính vì lý do này, tôi càng ngày càng cảm thấy bất an và phiền não, cuối cùng trở thành như khi gặp các bạn lần đầu… Thật xin lỗi, đã gây rắc rối cho mọi người!"
  },
  AvgDialog_75915_Content_64 = {
    Text = "Ignađis đặt hai tay vào nhau, cúi người xin lỗi các bạn."
  },
  AvgDialog_75915_Content_65 = {
    Text = "Bây giờ tinh thể đã cạn kiệt, tôi không còn sức lực để tiếp tục khám phá các không gian khác nữa, vì vậy, chuyến hành trình tùy hứng của tôi sẽ dừng lại tại đây. Để bù đắp, xin hãy nhất định nhận lấy cái này!"
  },
  AvgDialog_75915_Content_66 = {
    Text = "Ignatis lấy ra một viên pha lê lấp lánh, nhét vào tay bạn."
  },
  AvgDialog_75915_Content_67 = {
    Text = "Đây là… lệnh khóa?"
  },
  AvgDialog_75915_Content_68 = {
    Text = "Đây là viên tinh thể sáng cuối cùng của tôi, bây giờ tôi cũng không cần dùng đến nó nữa, không bằng tặng cho <Yellow:%player%> bạn để lưu niệm."
  },
  AvgDialog_75915_Content_69 = {
    Text = "Dường như do ảnh hưởng của sự cảm ứng bạc tâm trong quá trình đối đầu pha, cấu trúc khái niệm của nó đã trải qua một sự thay đổi đơn hướng không thể đảo ngược. Về bản chất, thông tin biểu hiện của nó có nhiều điểm tương đồng với lệnh khóa."
  },
  AvgDialog_75915_Content_7 = {
    Text = "Bạn đã không còn cơ hội nào nữa! Hãy đến đây, người nắm giữ sức mạnh thẻ bài của Misaque, để tôi chứng kiến những khoảnh khắc cuối cùng của bạn!"
  },
  AvgDialog_75915_Content_70 = {
    Text = "Nếu không có gì ngoài ý muốn, vật phẩm này hiện có thể được xem như một lệnh khóa. Hãy cầm lấy nó, <Yellow:%player%>."
  },
  AvgDialog_75915_Content_71 = {
    Text = "Cảm ơn bạn, Ignađis, tôi sẽ sử dụng nó thật tốt."
  },
  AvgDialog_75915_Content_72 = {
    Text = "Xì xì, nếu có thể giúp bạn thì thật tốt. Tuy nhiên… nhưng tôi đây có một yêu cầu nho nhỏ!"
  },
  AvgDialog_75915_Content_73 = {
    Text = "Ignađis khẽ nức nở, nói nhỏ với bạn."
  },
  AvgDialog_75915_Content_74 = {
    Text = "Hy vọng khi bạn nhìn thấy nó, có thể nhớ đến chúng ta một chút… thôi được không?"
  },
  AvgDialog_75915_Content_75 = {
    Text = "Tôi sẽ không quên các bạn, cô chủ."
  },
  AvgDialog_75915_Content_76 = {
    Text = "Không biết tại sao, tôi có cảm giác rằng có lẽ thật sự có một mối liên hệ đặc biệt giữa cô chủ và không gian này, dẫn đến sự bất thường trong dao động pha, khiến chúng ta có thể gặp nhau."
  },
  AvgDialog_75915_Content_77 = {
    Text = "Dù không biết liệu sau này còn có cơ hội gặp lại hay không, nhưng dù sao đi nữa tôi cũng sẽ không bao giờ quên, đã từng trong một trận đối đầu pha, gặp được một đối thủ đặc biệt, nghe kể một câu chuyện đặc biệt."
  },
  AvgDialog_75915_Content_78 = {
    Text = "Có anh nói vậy là em đã thỏa mãn rồi! Thời gian sắp đến lúc, cả không gian này cũng sắp khôi phục lại, và em cũng phải đi rồi."
  },
  AvgDialog_75915_Content_79 = {
    Text = "Bạn nhất định phải bảo vệ những thứ bạn muốn bảo vệ! Tuyệt đối đừng để kẻ xấu cướp chúng khỏi tay bạn!"
  },
  AvgDialog_75915_Content_8 = {
    Text = "Đúng……trên sân của tôi chỉ còn lại Ramona là thân thể được đánh thức duy nhất, trong khi tất cả các thân thể được đánh thức của đối thủ vẫn còn nguyên vẹn. \nTrong tình huống này, mạng sống của tôi đã như ngọn nến trong gió."
  },
  AvgDialog_75915_Content_80 = {
    Text = "Tôi sẽ, với tư cách là Người Giữ Gìn của Misaque, tôi sẽ dùng tính mạng của mình để bảo vệ tất cả điều này."
  },
  AvgDialog_75915_Content_81 = {
    Text = "Tạm biệt, <Yellow:%player%>! Ôi... Tôi sẽ nhớ bạn khi trở về! Mặc dù... thật sự rất không cam lòng... tôi rất muốn ở lại... nhưng không thể làm phiền bạn bè!"
  },
  AvgDialog_75915_Content_82 = {
    Text = "Cố lên, <Yellow:%player%>! Nhất định phải thắng! Tôi sẽ cầu nguyện cho các bạn ở đại lục Hepland!"
  },
  AvgDialog_75915_Content_83 = {
    Text = "Ư ư ư… ư a a a a a!!! Tạm biệt! Tôi sẽ rất nhớ mọi người!!!"
  },
  AvgDialog_75915_Content_84 = {
    Text = "Khi không gian dần dần phục hồi, Ignatia không thể kiềm chế được nữa và khóc lớn lên. Bạn thấy cô ấy vừa lau nước mắt, vừa vẫy tay từ biệt các bạn."
  },
  AvgDialog_75915_Content_85 = {
    Text = "Ánh sáng mạnh mẽ chiếu rọi khắp không gian. Khi bạn mở mắt ra lần nữa, cả không gian đã trở lại như hình dạng quen thuộc, giống như là mọi thứ chỉ là một giấc mơ."
  },
  AvgDialog_75915_Content_86 = {
    Text = "Chỉ có mật lệnh phát ra ánh sáng mờ mờ trong tay, chứng minh rằng cô ấy đã từng có câu chuyện với lục địa Heppland."
  },
  AvgDialog_75915_Content_88 = {
    Text = "Ramona, cô nói, nếu chúng ta thất bại, liệu có ai còn nhớ tới chúng ta không?"
  },
  AvgDialog_75915_Content_89 = {
    Text = "Tôi có thể nhớ những người đã biến mất do rỗng rỗng, nhưng nếu… nếu tôi biến mất, liệu còn ai đó sẽ nhớ đến tôi, nhớ về tất cả những gì chúng tôi đã từng có?"
  },
  AvgDialog_75915_Content_9 = {
    Text = "(Cái gì vậy, sao cảm thấy có chút... không đúng?)"
