  AvgDialog_75915_Content_90 = {Text = "Ừm……"},
  AvgDialog_75915_Content_91 = {
    Text = "Tôi không biết."
  },
  AvgDialog_75915_Content_92 = {
    Text = "Chủ đề này quá nặng nề và xa xôi, tôi không thể đưa ra lời hứa của mình ở đây, Thủ Mật Nhân."
  },
  AvgDialog_75915_Content_93 = {
    Text = "Nhưng câu trả lời tôi có thể đưa ra là……"
  },
  AvgDialog_75915_Content_94 = {
    Text = "Tôi sẽ ở bên bạn đến giây phút cuối cùng, dù là tương lai tươi đẹp hay kết thúc tan vỡ, luôn bên bạn."
  },
  AvgDialog_75915_Content_95 = {
    Text = "Dù cho Ngày Phán Xét cuối cùng thực sự đến và hủy diệt thế giới, tôi cũng sẽ dùng hết sức lực để khắc ghi bạn vào từng viên gạch trong điện thờ ký ức sâu thẳm nhất, cho đến khi sự im lặng vĩnh cửu nuốt chửng tôi."
  },
  AvgDialog_75915_Content_96 = {
    Text = "Trong giấc ngủ sâu trong bóng tối vô tận, tôi sẽ mãi ở bên bạn."
  },
  AvgDialog_75915_Content_97 = {
    Text = "Không cần phải đặt quá nhiều áp lực lên bản thân, <Yellow:%player%>. \nDù sao, con đường dưới chân chúng ta hiện tại vẫn còn thấy ánh sáng hy vọng."
  },
  AvgDialog_75915_Content_98 = {
    Text = "Như bạn vừa nói—— \"Tôi tin vào thân thể được đánh thức của mình\", tôi cũng hoàn toàn tin rằng Người Giữ Gìn của tôi có thể cứu thế giới, không chút nghi ngờ."
  },
  AvgDialog_75915_Content_99 = {
    Text = "Ramona! Đúng rồi! Dữ liệu thí nghiệm thu thập được như thế nào?"
  },
  AvgDialog_76411_Content_1 = {
    Text = "Clementine, khuôn mặt của bạn…"
  },
  AvgDialog_76411_Content_10 = {
    Text = "Biến mất…… hả."
  },
  AvgDialog_76411_Content_11 = {
    Text = "Clementine khẽ cười một tiếng.\nMá cô đỏ như máu, cô đang lấy tay che trái tim, cả cơ thể run rẩy nhẹ."
  },
  AvgDialog_76411_Content_12 = {
    Text = "Không, tôi không muốn nó biến mất. Cái này…… cái này……"
  },
  AvgDialog_76411_Content_13 = {
    Text = "Dường như không biết nên mô tả cảm giác này như thế nào, cô ấy tiến lại gần bạn một bước — nhưng lại ngã xuống lòng bạn vì kiệt sức."
  },
  AvgDialog_76411_Content_14 = {
    Text = "……Tôi thấy lần tư vấn tâm lý này không cần thiết phải tạm hoãn trước."
  },
  AvgDialog_76411_Content_15 = {
    Text = "Clementine, hãy nghỉ ngơi cho tốt, lần sau tôi sẽ đến thăm…"
  },
  AvgDialog_76411_Content_16 = {
    Text = "Bạn vội vàng đỡ Clementine ngồi lên ghế, chuẩn bị rời đi, nhưng cô ấy lại nắm chặt tay bạn."
  },
  AvgDialog_76411_Content_17 = {
    Text = "Cái tay đó ấm áp, nóng hơn bình thường, như ngọn lửa thiêu đốt làn da bạn, lại như chiếc lồng giam giữ chặt chẽ bạn."
  },
  AvgDialog_76411_Content_18 = {
    Text = "Tôi nghĩ chỉ có đau khổ và tuyệt vọng mới có thể ngọt ngào như vậy, nhưng thực ra, khát vọng bản thân cũng mang lại sự ngọt ngào."
  },
  AvgDialog_76411_Content_19 = {
    Text = "Và bạn, chính là nguồn ngọt ngào này, %player%."
  },
  AvgDialog_76411_Content_2 = {
    Text = "Bạn nhìn vào Clementine đang ngồi đối diện, chuẩn bị thực hiện liệu pháp tâm lý cho bạn, chỉ cảm thấy mặt cô ấy ngày càng đỏ."
  },
  AvgDialog_76411_Content_20 = {
    Text = "Nụ cười của Clementine ngày càng sâu hơn, tập trung nhìn vào bạn, và bạn không thể nhúc nhích."
  },
  AvgDialog_76411_Content_21 = {
    Text = "Khung cảnh xung quanh trở nên mờ ảo, những cánh hoa không biết từ đâu bay đến rơi rụng, rơi trước mặt bạn và Clementine."
  },
  AvgDialog_76411_Content_22 = {
    Text = "……Tôi lại bị bạn kéo vào thế giới tâm linh?"
  },
  AvgDialog_76411_Content_23 = {
    Text = "Tất nhiên. Cảm giác mà vỏ bọc mang lại cuối cùng vẫn hạn chế, thế giới của tâm hồn mới là điều cuối cùng để cảm nhận."
  },
  AvgDialog_76411_Content_24 = {
    Text = "Đến đây, lại gần một chút—tư vấn tâm lý không thể dừng lại giữa chừng."
  },
  AvgDialog_76411_Content_25 = {
    Text = "Trong thế giới tâm linh không có bất kỳ trở ngại nào, thoát khỏi mọi quy tắc, hãy để tôi từ từ thưởng thức món ngon hiếm có này."
  },
  AvgDialog_76411_Content_3 = {
    Text = "Phải chăng tôi mắc cảm lạnh? Nhưng người đánh thức cũng có thể cảm lạnh sao..."
  },
  AvgDialog_76411_Content_4 = {
    Text = "Bạn không thể không giơ tay chạm vào trán của Clementine, và theo hành động này, Clementine nhìn bạn với ánh mắt dịu dàng hơn thường lệ."
  },
  AvgDialog_76411_Content_5 = {
    Text = "Đôi mắt của cô ấy không biết từ bao giờ đã nhuốm nước, hai gò má ửng hồng, đang thở hổn hển."
  },
  AvgDialog_76411_Content_6 = {
    Text = "Chờ chút, đây không phải là cảm cúm, mà là ảnh hưởng của Sông thiêng..."
  },
  AvgDialog_76411_Content_7 = {
    Text = "Ý của bạn là, tôi như vậy là do ảnh hưởng của Sông thiêng?"
  },
  AvgDialog_76411_Content_8 = {
    Text = "Đúng vậy, dưới ảnh hưởng của mạch Sông thiêng, người đánh thức sẽ... cough... xuất hiện một số bất thường."
  },
  AvgDialog_76411_Content_9 = {
    Text = "Nhưng đừng lo lắng, những điều bất thường này sẽ nhanh chóng biến mất."
  },
  AvgDialog_78099_Content_1 = {
    Text = "Không chịu nổi nữa rồi sao? Cũng phải, để cho ngươi đối kháng với một \"ta\" khác, quả thật là như con dế muốn cản xe."
  },
  AvgDialog_78099_Content_10 = {
    Text = "Bạn cảm thấy áp lực xung quanh mình giảm đi đôi chút, đầu ngón tay bị tê liệt cũng dần dần khôi phục lại cảm giác."
  },
  AvgDialog_78099_Content_11 = {
    Text = "Chó con của Misaque, sau đó sẽ xem màn trình diễn của bạn?"
