  AvgDialog_78099_Content_4 = {
    Text = "Không, tôi giống bạn, không phải kiểu người hay ra tay nghĩa hiệp."
  },
  AvgDialog_78099_Content_5 = {
    Text = "Tuy nhiên, tôi không thể ngồi yên nhìn người đã cướp đi danh tính, phòng thí nghiệm và chó con của tôi tuyên truyền những lý tưởng mong manh trước mặt tôi."
  },
  AvgDialog_78099_Content_6 = {
    Text = "Thế giới sẽ trở thành như thế nào, thế giới cần phải trở thành như thế nào…… chờ đến khi tôi hiểu rõ sự thật mà bạn lải nhải, tôi sẽ là người định nghĩa lại."
  },
  AvgDialog_78099_Content_7 = {
    Text = "Trước đó, chó con của Misaque đã hỗ trợ tôi rất nhiều."
  },
  AvgDialog_78099_Content_8 = {
    Text = "Tiếp theo, tôi sẽ sử dụng sự cộng hưởng của cơ thể cải tiến để khiến B-68 và tôi cùng rơi vào trạng thái tê liệt ngắn hạn, giải phóng bạn ra……"
  },
  AvgDialog_78099_Content_9 = {
    Text = "Một âm thanh điện tử nghèn nghẹt làm não bạn ong ong, hai thân thể nhân tạo giống nhau đồng thời quỳ gối máy móc."
  },
  AvgDialog_78100_Content_1 = {
