  AvgDialog_78100_Content_8 = {
    Text = "Hố sâu đen tối vĩnh cửu sẽ bao dung sự ngông cuồng khi các ngươi dám thách thức tận thế, than khóc dưới sự giám sát của Ngài đi!"
  },
  AvgDialog_78940_Content_1 = {
    Text = "Bài ca của người dẫn đường"
