  AvgDialog_78940_Content_10 = {
    Text = "Máu không biết từ cơ thể ai chảy ra, bạn chỉ có thể thấy nó rỉ ra, nhuộm đỏ những vũng nước trên boong tàu."
  },
  AvgDialog_78940_Content_11 = {
    Text = "Tất cả mọi người đều điên rồi… chúng ta phải trốn đi."
