  },
  AvgDialog_78940_Content_17 = {
    Text = "Nói linh tinh, rõ ràng là thuyền trưởng đã dẫn dụ quái vật biển. Hơn nữa, Kperchant đã bị cách ly, hoàn toàn"
  },
  AvgDialog_78940_Content_18 = {
