  AvgDialog_78940_Content_2 = {
    Text = "Giữa cơn mưa tê tái và tuyệt vọng, mọi người có một khoảnh khắc im lặng, nhưng sự im lặng đó nhanh chóng bị những tiếng hét phá vỡ—"
  },
  AvgDialog_78940_Content_20 = {
    Text = "Việc tàu Nothdrius chìm xuống thực sự là sự thiếu sót của tôi, với tư cách là hoa tiêu của con tàu này, tôi, tôi sẽ không trốn tránh trách nhiệm của mình."
  },
  AvgDialog_78940_Content_21 = {
