  AvgDialog_78940_Content_31 = {
    Text = "Ngay khi Ké Perchant sắp bị bóng tối nuốt chửng hoàn toàn, bạn đã kịp nắm lấy cánh tay của cô ấy."
  },
  AvgDialog_78940_Content_32 = {
