  AvgDialog_78940_Content_48 = {
    Text = "Vì khoảng cách quá xa, bạn không thể nhìn rõ hình dáng của nó, nhưng thân hình khổng lồ đó, ngay cả trong bóng tối cũng khó mà bỏ qua."
