  },
  AvgDialog_78940_Content_73 = {
    Text = "Copperchant nắm chặt lá cờ, tiến về phía cột buồm giữa cơn bão. Cột buồm đã gãy, radio đã bị hỏng, lá cờ tín hiệu treo lủng lẳng cũng đã biến mất, nhưng không sao—"
