  AvgDialog_78940_Content_79 = {
    Text = "Sấm chớp lóe lên, như đang gầm thét trên đầu, nhưng cô ấy đắm chìm trong ký ức vui vẻ và tiếp tục leo lên cao hơn về phía cột buồm."
  },
  AvgDialog_78940_Content_8 = {
    Text = "Tất cả đều là lỗi của các người, tất cả đều là lỗi của các người!<Red:Tất cả hãy chết đi!>"
