  AvgDialog_78940_Content_85 = {
    Text = "Báo cáo, theo quy định, cờ H nên treo trên đỉnh nóc lái, nhưng hiện tại không có nóc lái, vì vậy tôi yêu cầu treo nó lên bản thân."
  },
  AvgDialog_78940_Content_86 = {
    Text = "Cô ấy báo cáo với không khí, khoác lá cờ lên người.\nMáu nhuộm đỏ lá cờ, nhưng cô ấy không thấy, trong mắt cô chỉ có sấm sét tích tụ không ngừng trên đỉnh đầu——"
