  AvgDialog_78941_Content_3 = {
    Text = "Mưa nhẹ rơi trong bầu trời đêm, tầng mây thấp trông kỳ lạ và khẩn trương như thể đang chuẩn bị gì đó."
  },
  AvgDialog_78941_Content_30 = {
