  },
  AvgDialog_78943_Content_29 = {
    Text = "Hình bóng đó vừa nói vừa lùi lại, để chăm sóc cho một bệnh nhân khác. Cuối cùng, bạn đã nhìn thấy rõ đối phương."
  },
  AvgDialog_78943_Content_3 = {
    Text = "Thuyền trưởng, xin hãy tha cho K…"
