  AvgDialog_78943_Content_30 = {
    Text = "Kheper Sanga!?"
  },
  AvgDialog_78943_Content_31 = {
    Text = "Là tôi. Thủy thủ Kevin... đã qua đời, hiện tại chỉ có tôi là thuyền viên còn lại có thể phục vụ."
  },
  AvgDialog_78943_Content_32 = {
    Text = "Còn cần giúp đỡ gì nữa không, vị hành khách này?"
  },
  AvgDialog_78943_Content_33 = {
    Text = "\"Hành khách\" cái danh xưng này làm bạn ngay lập tức nhận ra, bạn vẫn đang ở trong giấc mơ, chỉ không hiểu sao lại liên kết với ý thức của Cope Sanga, trải nghiệm quá khứ của cô ấy."
  },
  AvgDialog_78943_Content_34 = {
