  AvgDialog_78943_Content_40 = {
    Text = "Các thuyền viên thô lỗ xô đẩy đám đông, sau khi thất bại thì cầm vũ khí tấn công bệnh nhân, đó là những giáo dài làm bằng tấm gỗ, lẽ ra không nên xuất hiện trong chuyến đi này."
  },
  AvgDialog_78943_Content_41 = {
    Text = "Trong giây tiếp theo, tiếng la hét vang lên khắp kho hàng, làm nhớ lại cái chết của thuyền trưởng John và tất cả những gì đã nghe thấy trước khi ngất xỉu."
  },
  AvgDialog_78943_Content_42 = {
