  AvgDialog_78943_Content_43 = {Text = "……!!!"},
  AvgDialog_78943_Content_44 = {
    Text = "Trong khi nói, những người thủy thủ đã đến gần cửa, họ đá mạnh vào những bệnh nhân bám chặt vào khung cửa, và đóng cửa lại thật mạnh."
  },
  AvgDialog_78943_Content_45 = {
