  AvgDialog_78943_Content_68 = {
    Text = "Mọi người hãy nghe tôi nói một câu. Hiện tại, điều các bạn cần nhất là thức ăn, thuốc men và một nơi an toàn, hãy cố gắng bảo đảm sự sống còn của bản thân và những người bị thương."
