  AvgDialog_80319_Content_1 = {
    Text = "Người giữ gìn, Mythag đã đồng ý yêu cầu chiến đấu trợ giúp của bạn, hãy nhấn vào <Blue:Góc dưới bên trái> của bảng điều khiển, để kích hoạt quyền tự động chiến đấu."
  },
  AvgDialog_80319_Content_2 = {
    Text = "Chú ý, công nghệ này vẫn đang trong giai đoạn phát triển, vì vậy <Blue: không có hiệu lực khi đối mặt với kẻ địch mạnh và trong tình huống đặc biệt>."
  },
  AvgDialog_80319_Content_3 = {
    Text = "Bây giờ, tiếp tục trận chiến đi. Chức năng trợ giúp chiến đấu sẽ duy trì cho đến khi điều tra này kết thúc, bạn có thể bật và tắt bất cứ lúc nào."
