  AvgDialog_80448_Content_2 = {
    Text = "Ramona tuyệt đối sẽ không gây thương tôi."
  },
  AvgDialog_80448_Content_3 = {
    Text = "Tất nhiên không phải. Đây chỉ là hình ảnh ảo mà tôi vừa hiện ra sau khi xem qua ký ức của bạn."
  },
  AvgDialog_80448_Content_4 = {
    Text = "Tính chất của cô ấy, tôi đã nói cho bạn rồi, tiếp theo, tùy cách bạn chọn——"
  },
  AvgDialog_80448_Content_5 = {
    Text = "Lý tính, hay cảm tính, %player%, hãy cho tôi biết câu trả lời của bạn."
