  AvgDialog_80449_Content_4 = {
    Text = "Có lẽ William chính là người ngoài hoặc kẻ lạ mặt, cần phải nghĩ cách đến khu Tây."
  },
  AvgDialog_80977_Content_1 = {
    Text = "Đứa trẻ ngoan, có thể kiên trì đến đây đã rất tuyệt, tiếp theo, bạn có thể nghỉ ngơi."
