  AvgDialog_80977_Content_11 = {
    Text = "Tôi đã nghe thấy tiếng gọi của bạn, vì vậy tôi đã đến."
  },
  AvgDialog_80977_Content_12 = {
    Text = "Gọi? À, tôi hiểu rồi, tôi đã khuếch tán sự kéo của bạc, có lẽ ánh sáng nhỏ này không có nghĩa lý gì với vũ trụ."
  },
  AvgDialog_80977_Content_13 = {
    Text = "Đối với bạn, người luôn tìm kiếm hơi thở của %player%, đúng là ánh mặt trời mà bạn khao khát từ lâu."
  },
  AvgDialog_80977_Content_14 = {
    Text = "Nhưng có lẽ %player% không mong muốn gặp bạn, hoặc nói cách khác, là hình dạng của bạn?"
  },
  AvgDialog_80977_Content_15 = {
    Text = "Vòng lặp Ramona, bạn đừng nghe cô ta nói linh tinh, tôi……"
