  AvgDialog_80977_Content_16 = {
    Text = "Tôi hiểu. Tôi không phải là cô ấy, và không bao giờ có thể trở thành cô ấy, nhưng dù sao, cô ấy cũng giống như tôi, đúng không?"
  },
  AvgDialog_80977_Content_17 = {
    Text = "Màu sắc sâu thẳm nhất của tôi và cô ấy, với lòng kiên trì của bạn đối với %player%, thì thật giống nhau."
  },
  AvgDialog_80977_Content_19 = {
