  AvgDialog_80977_Content_2 = {
    Text = "Đúng vậy, bạn cảm thấy rất mệt mỏi, muốn nghỉ ngơi, nghỉ ngơi…"
  },
  AvgDialog_80977_Content_20 = {
    Text = "Cô ấy đã chết, cô ấy còn sống, hai Clementine hoàn toàn khác nhau, không hiểu nhau, nhưng họ cuối cùng là một người."
  },
  AvgDialog_80977_Content_21 = {
    Text = "Vì vậy, cô ấy mới nói không phải cô ấy đã đáp lại tôi, mà là \"Clementine\"đã đáp lại tôi."
  },
  AvgDialog_80977_Content_22 = {
    Text = "Tội nghiệp %player% đã bắt đầu nói nhảm rồi."
  },
  AvgDialog_80977_Content_23 = {
    Text = "Nhớ rằng, đừng so sánh tôi được tái sinh với con người nhỏ bé mong manh đó, nếu không tôi sẽ tức giận."
  },
  AvgDialog_80977_Content_24 = {
    Text = "Bạn không lên tiếng, mà nhìn về phía Vòng lặp Ramona.\nLúc này, trong lòng bạn đã có cách để giải quyết."
