  AvgDialog_80977_Content_26 = {
    Text = "Về lý thuyết, tôi chỉ có thể tồn tại vài phút. Nhưng miễn là chưa chết, tôi sẽ vô số lần xé nát chiều không gian để đến đây."
  },
  AvgDialog_80977_Content_27 = {
