  AvgDialog_80977_Content_29 = {
    Text = "Bởi vì dù là thế giới này hay thế giới khác, đều có người đang chờ tôi."
  },
  AvgDialog_80977_Content_3 = {
    Text = "Bạn nghiến chặt hàm, cố gắng giữ vững lý trí, nhưng giọng nói đầy mê hoặc của Clementine lại khiến bạn càng thêm kiệt sức và mệt mỏi."
