  AvgDialog_80977_Content_8 = {Text = "Ramona..."},
  AvgDialog_80977_Content_9 = {
    Text = "Chỉ cần một cái nhìn, bạn đã biết đối phương là ai.\nBởi vì trong tâm trí bạn, bạn đã phác họa hình dáng của cô ấy vô số lần."
