  AvgDialog_80978_Content_10 = {
    Text = "Sự hiện hữu tỏa sáng ánh sáng vũ trụ ấy khóa chặt ánh mắt vào bạn, nhẹ nhàng rung chuyển cánh, chào đón thời khắc chuyển mình."
  },
  AvgDialog_80978_Content_11 = {
    Text = "Bạn cảm thấy sợ hãi một cách bản năng, nhưng dù sợ hãi đến đâu, cũng không thể khiến bạn lùi lại dù chỉ một bước."
