  AvgDialog_80978_Content_12 = {
    Text = "... Ramona, William và\"Clemantine\"， hãy nhìn tôi, cùng chiến đấu nào!"
  },
  AvgDialog_80978_Content_2 = {
    Text = "Tôi thật sự muốn mổ não bạn ra, kĩ lưỡng xem từng nếp gấp, từng sợi dây thần kinh, ở đó chắc chắn ẩn chứa những đau khổ ngon nhất..."
