  AvgDialog_8229_Content_3 = {
    Text = "Giáo chủ Salvador... là.."
  },
  AvgDialog_8229_Content_30 = {
    Text = "Sau đó, anh ta tiếp cận chị gái tôi, khiến gia đình tôi tan nát."
  },
  AvgDialog_8229_Content_31 = {
    Text = "……tôi thực sự có trách nhiệm về cái chết của họ. \nNếu tôi cẩn thận hơn, kịp thời đưa Ét-và trở lại con đường đúng đắn, bạn sẽ không phải chịu khổ như vậy."
  },
  AvgDialog_8229_Content_32 = {
    Text = "Nếu điều này có thể xoa dịu cơn giận của bạn, an ủi trái tim bạn, thì hãy xét xử tôi đi. \nNhưng đừng để hận thù làm mờ lý trí, gây đau khổ không đáng có cho người vô tội."
