  AvgDialog_8229_Content_35 = {
    Text = "Bạn có tư cách gì để đưa ra sự tha thứ, có tư cách gì để cho những kẻ rác rưởi \"cơ hội để sửa chữa\"?"
  },
  AvgDialog_8229_Content_36 = {
    Text = "<Yellow:đèn lồng> nói không sai, giáo khu dung túng kẻ tội lỗi chỉ khiến cái ác lan tràn. Muốn người khác không phải chịu khổ như tôi, muốn mọi người đều sống trong hạnh phúc……"
  },
  AvgDialog_8229_Content_37 = {
    Text = "Cô ấy hướng một chiếc gương cầm tay có hình dạng kỳ lạ về phía bầu trời, và ánh nắng mặt trời rơi vào đó chuyển sang màu đỏ thẫm."
