  AvgDialog_8229_Content_39 = {
    Text = "Mặt trời biến mất trong không trung. Trời tối sầm lại nhanh chóng, mặt trăng màu máu xuất hiện bất ngờ, chiếm lấy hơn nửa bầu trời."
  },
  AvgDialog_8229_Content_4 = {
    Text = "Các ký tự trên bảng đá nhấp nháy đều đặn như hơi thở, nhiều ánh sáng xanh hơn giống như rễ của một cây khổng lồ lan tỏa ra mọi hướng."
  },
  AvgDialog_8229_Content_40 = {
    Text = "Ánh trăng đỏ thẫm chiếu xuống mặt đất, nhuộm mọi thứ thành màu đỏ chói mắt."
  },
  AvgDialog_8229_Content_41 = {
    Text = "Hỡi những kẻ tội lỗi, hãy cắt xẻo thịt da các ngươi, để cho tội lỗi của các ngươi chảy ra ——"
  },
  AvgDialog_8229_Content_42 = {
    Text = "Những người đang đánh nhau đột nhiên quay đầu, dùng dao và răng xé rách da thịt của chính mình."
  },
  AvgDialog_8229_Content_43 = {
    Text = "Chào mừng đến với thiên đường vô tội của những người tạo hình bằng bạc thuần khiết!"
  },
  AvgDialog_8229_Content_45 = {
    Text = "Ánh sáng đỏ phản chiếu trên mặt kính chớp nháy dữ dội, tiếng thét thảm thiết và kêu gào đau đớn vang lên cùng với máu chảy khắp quảng trường, giống như địa ngục trần gian."
  },
  AvgDialog_8229_Content_5 = {
    Text = "Vô số thương và cái chết, những tiếng khóc than và kêu gào, đều được xoa dịu trong diệu kỳ đột ngột này."
  },
  AvgDialog_8229_Content_6 = {
    Text = "Mùi hương của đền thánh nhẹ nhàng lướt qua mũi bạn, thanh thoát, mơ hồ, như thể chưa từng tồn tại, nhưng lại hoàn toàn che giấu đi mùi tanh của máu."
