  AvgDialog_8231_Content_104 = {
    Text = "Mùi máu tanh kích thích lỗ mũi của bạn, ánh sáng xanh xuất hiện ở rìa tầm nhìn của bạn, dần dần xua tan làn sương trắng trước mắt bạn."
  },
  AvgDialog_8231_Content_105 = {
    Text = "Những lời lẩm bẩm khó hiểu dần dần xa dần, thay vào đó là tiếng ồn ào của con người——có người hét lên, có người rên rỉ, có người thì thầm cầu nguyện bên cạnh bạn."
  },
  AvgDialog_8231_Content_106 = {
    Text = "Thần Cha nhân từ, xin hãy thức tỉnh \"lửa trắng\"đang chìm ngủ, để {Male=anh ấy,Female=cô ấy} có thể tiếp tục dẫn dắt chúng con soi sáng con đường phía trước."
  },
  AvgDialog_8231_Content_107 = {
    Text = "Bóng tối có hình dạng rõ ràng bao phủ trước mặt bạn, bạn dần mở mắt."
  },
  AvgDialog_8231_Content_108 = {
    Text = "Những người điên cuồng, máu me lan tràn, tiếng kêu thê thảm hỗn loạn và đầy sợ hãi… Tất cả mọi thứ đều bị cách ly sau tấm bảng đá khổng lồ."
  },
  AvgDialog_8231_Content_109 = {
    Text = "Mỗi bảng đá đều được khắc những rune phức tạp, trên mỗi rune đều có ánh sáng xanh lưu chuyển, giống như dòng sông Ngân Hà bị thu nhỏ vô số lần."
