  AvgDialog_8231_Content_110 = {
    Text = "Một tia ánh sáng xanh chảy dọc theo cánh tay của Salvador đến bạn, và khi nó đến, cơn đau đầu của bạn dần biến mất."
  },
  AvgDialog_8231_Content_111 = {
    Text = "Salvador……Giám mục?"
