  AvgDialog_8231_Content_12 = {
    Text = "Ể? à, đó là… chuyện cách đây mười năm, lúc đó tôi vẫn còn là một đứa trẻ, cùng mẹ và <Yellow:chị gái> đến thăm vị giám mục mới nhậm chức."
  },
  AvgDialog_8231_Content_13 = {
    Text = "Ông thường xuyên đến viện từ thiện mà gia đình tôi hỗ trợ để giúp đỡ, và chúng tôi cũng dần dần quen biết ông. \n Đức Giám mục có một trái tim nhân hậu, đầy lòng khoan dung và yêu thương đối với mọi thứ, tôi rất kính trọng ông."
  },
  AvgDialog_8231_Content_14 = {
    Text = "Vậy nên bạn mới làm nhân viên văn phòng ở đền thánh sao?"
  },
  AvgDialog_8231_Content_15 = {
    Text = "Tôi thực sự muốn giúp đỡ nhiều người hơn, nhưng… nếu không phải vì chuyện đó xảy ra, tôi… chắc hẳn đã không như bây giờ."
  },
  AvgDialog_8231_Content_16 = {
    Text = "Quý ngài Giám mục, quý ngài Giám mục!"
