  AvgDialog_8231_Content_18 = {
    Text = "Thưa Đức Giám mục, chuyện không tốt rồi, chị tôi, chị tôi——xin ngài mau đến đây, van xin ngài mau đến đây!"
  },
  AvgDialog_8231_Content_19 = {
    Text = "Cô ấy đã ngủ. \n Tuy nhiên, trong những ngày này cần chú ý để cô ấy nghỉ ngơi thật tốt và ăn những thực phẩm bổ dưỡng."
  },
  AvgDialog_8231_Content_2 = {
    Text = "Đây là cái cuối cùng."
  },
  AvgDialog_8231_Content_20 = {
    Text = "Vâng, tôi sẽ làm, cảm ơn ngài, Đức Giám mục, thật sự cảm ơn ngài…"
  },
  AvgDialog_8231_Content_21 = {
    Text = "Vết thương trên cổ tay cô rất sâu, sát tới gân và xương. Cô ấy… đã xảy ra chuyện gì?"
  },
  AvgDialog_8231_Content_22 = {
    Text = "Quý bà thanh lịch mở miệng, khuôn mặt vốn đã không còn trẻ càng thêm già nua."
  },
  AvgDialog_8231_Content_23 = {
    Text = "Ô, ngài Giám mục, tôi thật không biết bắt đầu từ đâu… Con gái tôi, Olivia đáng thương của tôi…"
  },
  AvgDialog_8231_Content_24 = {
    Text = "Là <Blue:Edward Bailey>, Đức Giám mục. Họa sĩ trên đường Carlisle."
  },
  AvgDialog_8231_Content_25 = {
    Text = "Anh ấy nói rằng anh ấy biết một thương nhân Yagro đang chuẩn bị mở một trung tâm nghệ thuật ở Lentiennam, và họ đã chuẩn bị mọi thứ, chỉ thiếu một đối tác có uy tín địa phương để làm mặt tiền."
  },
  AvgDialog_8231_Content_26 = {
    Text = "Olivia đã ký tất cả các thỏa thuận, thuê, vay, thế chấp… mọi thứ. Lúc tôi và mẹ nhận ra, mọi chuyện đã quá muộn. Chúng tôi…"
  },
  AvgDialog_8231_Content_27 = {
    Text = "Ngân hàng đã gửi đến thông điệp cuối cùng hôm nay, nói rằng họ sẽ thu hồi ngôi nhà vào ngày mai. \nOlivia đã thấy thông điệp đó, cô ấy... không thể chịu đựng được nữa."
  },
  AvgDialog_8231_Content_28 = {
    Text = "Bà chủ khóc thút thít, khăn tay đã sớm bị nước mắt làm ướt. Salvador hơi nghiêng người, dường như nhìn về phía cánh cửa đóng kín."
  },
  AvgDialog_8231_Content_29 = {
    Text = "Con của tôi, tôi sợ rằng có một yêu cầu khó nói."
  },
  AvgDialog_8231_Content_3 = {
    Text = "Bạn và Sophia đã nhẹ nhàng chuyển cảnh sát đến phía sau các thùng gỗ, tạm thời tránh được ánh mắt của đám người bạo loạn."
  },
  AvgDialog_8231_Content_30 = {
    Text = "Quý ngài Giám mục?"
  },
  AvgDialog_8231_Content_31 = {
    Text = "Bà Foster, người phụ trách các công việc hàng ngày của đền thánh, gần đây đã bị ốm và cần nghỉ ngơi. Còn tôi thì không giỏi trong những việc này, thực sự rất bối rối, không biết bạn có muốn tạm thời đảm nhận vai trò quản lý công việc của đền thánh không?"
  },
  AvgDialog_8231_Content_32 = {
    Text = "Quý ngài Giám mục… tôi,"
  },
  AvgDialog_8231_Content_33 = {
    Text = "Tất nhiên, nhân viên cần chuyển đến đền thánh để ở. \nMặc dù không quá thuận tiện, nhưng chúng tôi luôn có nhiều phòng trống. Đủ chỗ để đón tiếp bạn và gia đình."
  },
  AvgDialog_8231_Content_34 = {
    Text = "Bạn có thể giúp tôi việc này được không?"
  },
  AvgDialog_8231_Content_35 = {
    Text = "Tất nhiên…! Tôi, tôi tất nhiên sẵn lòng giúp đỡ!\nCảm ơn ngài, Đức Giám mục, thật sự, cảm ơn ngài…"
  },
  AvgDialog_8231_Content_36 = {
    Text = "Olivia luôn cảm thấy tự trách, sau phiên tòa, cô ấy đã bị ảnh hưởng rất lớn. \nSau đó, trong lúc tôi và mẹ không để ý, cô ấy đã chạy đến cầu."
  },
  AvgDialog_8231_Content_37 = {
    Text = "Chúng tôi tìm thấy cô ấy sau hai ngày. Cô ấy…\nMẹ đã tan nát cõi lòng, và không lâu sau đó, bà cũng trở về bên cha thần."
  },
  AvgDialog_8231_Content_38 = {
    Text = "Sophia quay mặt sang một bên. Bạn thấy cô ấy đưa tay lên lau mặt, khi đặt xuống thì đầu ngón tay còn đọng lại chút vết nước."
  },
  AvgDialog_8231_Content_39 = {
    Text = "Tuy nhiên, mọi thứ đã qua rồi."
  },
  AvgDialog_8231_Content_4 = {
    Text = "Chúng ta trốn ở đây, Orci có tìm thấy không?"
  },
  AvgDialog_8231_Content_40 = {
    Text = "Nhờ sự dẫn dắt của <Yellow:Ngài>, tội lỗi đen tối cuối cùng sẽ tan biến, và chúng ta cũng sẽ đón chào bình minh."
  },
  AvgDialog_8231_Content_41 = {
    Text = "Tiếng chân gấp gáp nhanh chóng tiến đến gần các bạn, Sophia căng thẳng hẳn lên. Bạn giơ tay ra hiệu cho cô ấy đừng quá lo lắng, sau đó cẩn thận thò đầu ra."
  },
  AvgDialog_8231_Content_42 = {
    Text = "Chúa công!"
  },
  AvgDialog_8231_Content_43 = {
    Text = "Shhh. \n Giám mục Salvador? Ông có sao không?"
  },
  AvgDialog_8231_Content_44 = {
    Text = "Orci là một đứa trẻ rất đáng tin cậy. Nhờ cậu ấy mà tôi mới giữ được mạng sống đến tận bây giờ."
  },
  AvgDialog_8231_Content_45 = {
    Text = "Đây không phải là đồng phục của hội nghị thẩm tra sao, còn có cảnh sát. Họ đang làm gì vậy?"
  },
  AvgDialog_8231_Content_46 = {
    Text = "Chúng tôi cũng không biết… họ giống như đang ngủ, không thể tỉnh lại."
  },
  AvgDialog_8231_Content_47 = {
    Text = "Sau đền thánh là nơi cư trú của các chức sắc tôn giáo, tôi đã khóa lại cẩn thận khi rời đi vào buổi sáng, vào lúc này không nên có ai ở đó."
  },
  AvgDialog_8231_Content_48 = {
    Text = "Hãy tranh thủ lúc những người kia còn yên lặng, nhanh chóng rút lui đến đền thánh. Tăng viện sẽ đến rất nhanh. \nLại phải làm phiền ngài giúp một tay, Đức Giám mục."
  },
  AvgDialog_8231_Content_49 = {
    Text = "Không vấn đề gì, tôi chính là người đến để giúp đỡ các bạn."
  },
  AvgDialog_8231_Content_5 = {
    Text = "Tôi và anh ấy có… bạn cứ coi đó là sự ăn ý đi. \nAnh ấy sẽ đến."
  },
  AvgDialog_8231_Content_50 = {
    Text = "Các bạn di chuyển khó khăn trong đám đông. Orci thỉnh thoảng phải buông người đang nửa đỡ nửa kéo để đối phó với những kẻ bạo động tấn công, và trên khuôn mặt còn non nớt của cậu ấy dần lộ rõ vẻ mệt mỏi."
  },
  AvgDialog_8231_Content_51 = {
    Text = "Mặt của Đức Giám mục Salvador cũng dính bụi, mái tóc dài bị mồ hôi làm ướt dính vào hai bên má, trông có phần tiều tụy."
  },
  AvgDialog_8231_Content_52 = {
    Text = "Sự kiện diễn ra quá đột ngột, tình hình xấu đi kỳ quái. Xem xét các ghi chép của Misaque về tan chảy, chưa từng thấy dị biến nào kỳ lạ đến vậy."
  },
  AvgDialog_8231_Content_53 = {
    Text = "Biến dị……Trong ấn tượng của bạn, cùng với những hiện tượng bất thường của những người này, còn có một thứ khác xuất hiện."
  },
  AvgDialog_8231_Content_54 = {
    Text = "Orci, trên đường đến đây, có để ý thấy ánh sáng kỳ lạ không?"
  },
  AvgDialog_8231_Content_55 = {
    Text = "Ánh sáng?"
  },
  AvgDialog_8231_Content_56 = {
    Text = "Rất chói mắt, giống như thứ gì đó phản xạ ra. \nTôi đã nhìn thấy vài lần, và mỗi khi tia sáng đó xuất hiện, hành vi của mọi người đều bị kích động mạnh mẽ."
  },
  AvgDialog_8231_Content_57 = {
    Text = "Người tức giận càng thêm tức giận, những người muốn trở thành số một —— có thể nói là ghen tị —— họ càng khao khát giữ vững vị trí số một."
  },
  AvgDialog_8231_Content_58 = {
    Text = "Thêm những người đột nhiên cảm thấy buồn ngủ, tôi nghi ngờ——"
  },
  AvgDialog_8231_Content_59 = {
    Text = "Cơn đau dữ dội đột ngột lan từ sau đầu bạn. \nĐồng tử của Orci co lại mạnh mẽ dưới ánh sáng chói chang, anh ta há miệng ra, dường như định nói gì đó."
  },
  AvgDialog_8231_Content_6 = {
    Text = "Sophia gật đầu, thận trọng quan sát xung quanh quảng trường."
  },
  AvgDialog_8231_Content_60 = {
    Text = "Giây tiếp theo, trước mắt bạn là một màu trắng như tuyết."
  },
  AvgDialog_8231_Content_61 = {
    Text = "Ánh sáng từ phía sau bạn chiếu đến, bao trùm mọi thứ. Tiếng vo ve chói tai nuốt chửng tất cả, theo sau là một tiếng thì thầm mơ hồ, một cảm giác thôi thúc mạnh mẽ."
  },
  AvgDialog_8231_Content_62 = {
    Text = "Ngủ đi, %player%."
  },
  AvgDialog_8231_Content_63 = {
    Text = "Choáng váng ập đến."
  },
  AvgDialog_8231_Content_64 = {
    Text = "Bạn luôn nên ngủ sâu."
  },
  AvgDialog_8231_Content_65 = {
    Text = "Trong một vùng trắng mờ mịt, bạn thậm chí đã mất khả năng phân biệt trái phải, trên dưới."
  },
  AvgDialog_8231_Content_66 = {
    Text = "Chỉ khi bạn chìm vào giấc ngủ, thế giới mới có thể @4"
  },
  AvgDialog_8231_Content_67 = {
    Text = "Thấy Người Giữ Gìn sắp ngã, Salvador vội vàng tiến lên đỡ lấy."
  },
  AvgDialog_8231_Content_68 = {
    Text = "Chúa công!"
  },
  AvgDialog_8231_Content_69 = {
    Text = "Chiến binh nhỏ lại vội vàng và hoảng loạn, liên tục giằng co giữa việc bỏ rơi người đang đỡ và trách nhiệm bảo vệ người dân. \nSalvador dùng tay kiểm tra hơi thở của Người Giữ Gìn, sau đó gật đầu với Orci một cách nhẹ nhàng để trấn an."
  },
  AvgDialog_8231_Content_7 = {
    Text = "Không biết Đức Giám mục giờ ra sao rồi…"
  },
  AvgDialog_8231_Content_70 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} không sao, có lẽ chỉ là quá mệt mỏi."
  },
  AvgDialog_8231_Content_71 = {
    Text = "Mệt……có phải giống như những người này không."
  },
  AvgDialog_8231_Content_72 = {
    Text = "Tất cả những người vừa mới còn gào thét chửi rủa, vật lộn với nhau thậm chí tự hành hạ bản thân, không biết từ bao giờ đã dừng lại. Họ có ánh mắt vô hồn và trống rỗng, giống như những con búp bê cơ khí bị mắc kẹt trong trạng thái ngừng hoạt động."
  },
  AvgDialog_8231_Content_73 = {
    Text = "Cả quảng trường ít nhất cũng có hàng trăm người, nhưng không phát ra một chút âm thanh nào. Dưới bầu trời dần tối sầm, như thể một bầy hồn ma lạc lối."
  },
  AvgDialog_8231_Content_74 = {
    Text = "Salvador quay đầu lại, nhìn về hướng ánh sáng chói lóa. \nPhía sau anh, Sophia đang kèm đỡ cảnh sát với vẻ mặt căng thẳng."
  },
  AvgDialog_8231_Content_75 = {
    Text = "Đều tại tôi, không chú ý đến trạng thái của chủ quân... nếu cô Ramona ở đây.."
  },
  AvgDialog_8231_Content_76 = {
    Text = "Bạn đã làm rất tuyệt, con của tôi. \nNếu không có sự bảo vệ của bạn, có lẽ chúng ta đã bị thương trong đền thánh rồi."
  },
  AvgDialog_8231_Content_77 = {
    Text = "Nhưng chúa công.."
  },
  AvgDialog_8231_Content_78 = {
    Text = "{Male=Anh ấy,Female=Cô ấy} như vậy có lẽ là do ảnh hưởng của điều gì đó, không phải lỗi của bạn. \n Đi nào, hãy cố gắng thêm một chút, vẫn cần đến sự giúp đỡ của bạn, Tiểu Kỵ Sĩ."
  },
  AvgDialog_8231_Content_79 = {
    Text = "Tôi, tôi biết rồi. Tôi sẽ cố gắng!"
  },
  AvgDialog_8231_Content_8 = {
    Text = "Tôi và Orci đã tách ra trước khi anh ấy đi tìm giám mục, chắc là họ sẽ ổn."
  },
  AvgDialog_8231_Content_80 = {
    Text = "Thấy cậu bé tỉnh táo lại, Salvador chuyển sự chú ý trở lại. Người giữ bí mật nhắm mắt thở nhẹ, dường như đang trong một cuộc đấu tranh nội tâm nào đó."
  },
  AvgDialog_8231_Content_81 = {
    Text = "Lợi dụng động tác điều chỉnh tư thế, bàn tay đeo găng đen áp lên trán của người trẻ tuổi."
  },
  AvgDialog_8231_Content_82 = {
    Text = "Thần Cha đầy lòng thương xót, hãy ban xuống cho con dân của Người ân điển vô biên…"
  },
  AvgDialog_8231_Content_83 = {
    Text = "Ánh sáng xanh lờ mờ từ kẽ ngón tay của anh ấy tỏa ra, chưa kịp thu hút sự chú ý của ai thì đã bị che giấu dưới chiếc áo choàng rộng lớn."
  },
  AvgDialog_8231_Content_84 = {
    Text = "Người giữ bí mật động đậy tay, %hisorher% lông mày nhíu lại, miệng thốt lên vài câu lẩm bẩm khó nghe rõ."
  },
  AvgDialog_8231_Content_85 = {
    Text = "Không thể… ngủ…"
  },
  AvgDialog_8231_Content_86 = {
    Text = "Orci đi ở đầu hàng người, Salvador dùng mỗi tay đỡ một người, một mình gánh vác thân thể của hai người mất ý thức."
  },
  AvgDialog_8231_Content_87 = {
    Text = "Chim bay vỗ cánh lướt qua trên cao, ở đâu đó, chuông gió treo lơ lửng bị gió thổi động, phát ra âm thanh đều đều."
  },
  AvgDialog_8231_Content_88 = {
    Text = "……đói……"
  },
  AvgDialog_8231_Content_89 = {Text = "……?"},
  AvgDialog_8231_Content_9 = {
    Text = "Như vậy.."
  },
  AvgDialog_8231_Content_90 = {
    Text = "Đói quá…"
  },
  AvgDialog_8231_Content_91 = {
    Text = "Quý ngài Giám mục, ngài có nghe thấy không…"
  },
  AvgDialog_8231_Content_92 = {
    Text = "Salvador dừng lại."
  },
  AvgDialog_8231_Content_93 = {
    Text = "Trước mặt họ, một người đàn ông vốn đứng im bỗng nhiên hít mũi và đưa tay về phía người bên cạnh."
  },
  AvgDialog_8231_Content_94 = {
    Text = "Thịt, nhiều thịt…… tôi thật sự rất đói……<Big:đói quá……!>"
  },
  AvgDialog_8231_Content_95 = {
    Text = "Máu ấm phun ra trên mặt đất, mùi tanh ngọt trong chốc lát đã thức tỉnh tất cả những ác quỷ đang yên nghỉ."
  },
  AvgDialog_8231_Content_96 = {
    Text = "Cho tôi thịt, tôi muốn ăn thịt!"
  },
  AvgDialog_8231_Content_97 = {
    Text = "<BigShake:à——!>"
  },
  AvgDialog_8231_Content_98 = {
    Text = "Tiếng kêu thê thảm và âm thanh ướt át khi da thịt bị xé toạc đã lấp đầy quảng trường vốn yên tĩnh, Orci vội vàng giơ cây giáo lên, đẩy lùi những người lao vào tấn công."
  },
  AvgDialog_8231_Content_99 = {
    Text = "Quý ngài Giám mục! Chúng ta phải nhanh nào!"
  },
  AvgDialog_8232_Content_10 = {
    Text = "Sự phán xét đang đến, chỉ có những linh hồn tinh khiết mới được vào cõi tịnh vô tội."
  },
  AvgDialog_8232_Content_11 = {
    Text = "<Red:ước chúc ngọn đèn luôn sáng>."
  },
  AvgDialog_8232_Content_12 = {
    Text = "Khu đền thánh Lentiennam\nĐại Thánh Đường Cha Trời Cứu Thế"
  },
  AvgDialog_8232_Content_13 = {
    Text = "Ánh nắng hiếm hoi xua tan hơi nước bao trùm Lentiennam, những đám mây nhỏ điểm xuyết trên bầu trời xanh, tạo ra những bóng râm thoáng qua, mang lại chút mát mẻ tức thì cho người dưới kia."
  },
  AvgDialog_8232_Content_14 = {
    Text = "Dải ruy băng và cờ từ đền thánh kéo dài ra khắp nơi, được nối với các ngôi nhà xung quanh thông qua các cột cờ đỡ. Biểu ngữ lớn nhất được treo giữa các tháp của đền thánh, trên đó có viết \"Ngày bán hàng từ thiện\"."
  },
  AvgDialog_8232_Content_15 = {
    Text = "Dưới mái hiên xếp chồng, cánh cửa gỗ nặng nề mở ra phía trong, tạo điều kiện cho những người tham gia xong nghi lễ cầu phước rời khỏi đền thánh yên tĩnh và tham gia vào chợ sôi động náo nhiệt."
  },
  AvgDialog_8232_Content_16 = {
    Text = "Hôm nay tôi thực sự rất cảm ơn cô <Blue:Tiểu thư Sophia>."
  },
  AvgDialog_8232_Content_17 = {
    Text = "Bạn và Orci đi sau cùng trong đám đông, viên chức đền thánh tên là Sophia đi bên cạnh, mỉm cười nói chuyện với các bạn."
  },
  AvgDialog_8232_Content_18 = {
    Text = "Đúng vậy, nếu không phải là bạn, chúng ta có lẽ còn không thể vào được cửa đền thánh."
  },
  AvgDialog_8232_Content_19 = {
    Text = "<Blue:Giám mục Salvador> chủ trì nghi lễ, mọi người đều rất nhiệt tình, tôi chỉ là chuẩn bị kỹ hơn mà thôi."
  },
  AvgDialog_8232_Content_2 = {
    Text = "Hối cải"
  },
  AvgDialog_8232_Content_20 = {
    Text = "Lần sau khi các bạn đến, tôi sẽ lén giữ chỗ cho các bạn, để các bạn khỏi lo lắng."
  },
  AvgDialog_8232_Content_21 = {
    Text = "Điều này, như vậy có được không? Đối với những người khác liệu có công bằng không,.."
  },
  AvgDialog_8232_Content_22 = {
    Text = "Người đó rất quan trọng với bạn phải không? Người mà bạn đã cầu nguyện cho."
  },
  AvgDialog_8232_Content_23 = {
    Text = "Ánh mắt của Orci lơ đãng, dường như đã liếc nhìn bạn một cái, sau đó gật đầu thật sâu."
  },
  AvgDialog_8232_Content_24 = {
    Text = "Thế thì, hãy để điều này trở thành bí mật giữa chúng ta, được không? \nMột đứa trẻ chân thành và mộ đạo như con, chắc chắn Đấng Tối Cao cũng rất vui lòng ban cho một số ưu đãi."
