  AvgDialog_8232_Content_26 = {Text = "?！"},
  AvgDialog_8232_Content_27 = {
    Text = "Một tiếng thét chói tai ngắt quãng cuộc đối thoại của các bạn, những người nghe thấy cũng dừng lại, nhìn về hướng phát ra âm thanh."
