  AvgDialog_8232_Content_40 = {
    Text = "Tôi đã lừa dối họ, lừa dối tất cả họ! Tôi có tội, tôi đê tiện! \nHãy trừng phạt tôi, làm tôi chảy máu, tẩy rửa tội lỗi của tôi, xin hãy trừng phạt tôi!!"
  },
  AvgDialog_8232_Content_41 = {
    Text = "Đừng động, người điên! \n Cảnh sát đâu? Có ai gọi cảnh sát chưa?"
  },
  AvgDialog_8232_Content_42 = {
    Text = "Cảnh sát? Không, không... họ chỉ sẽ giam tôi lại, không cho tôi hình phạt thực sự, <Yellow:ngày phán xét> đang đến, <Yellow:đất thánh vô tội> sẽ đến, nếu không <Red:thanh tẩy> ngay bây giờ thì sẽ quá muộn!"
