  AvgDialog_8232_Content_43 = {
    Text = "Hãy buông tôi ra, buông tôi ra!"
  },
  AvgDialog_8232_Content_44 = {
    Text = "Anh ta ngẩng phắt đầu lên, cắn vào tay người đàn ông trung niên đang túm chặt mình."
  },
  AvgDialog_8232_Content_45 = {Text = "A!"},
  AvgDialog_8232_Content_46 = {
    Text = "Người đàn ông buông lỏng tay, người trẻ tuổi liền quay người lao vào đám người xem."
  },
  AvgDialog_8232_Content_47 = {
    Text = "Orci vội vàng đưa cây thương dài ra quét ngã người trẻ tuổi. Người này ngã sấp xuống đất, bạn nhân cơ hội khóa chặt hai tay anh ta ra sau lưng và ghì chặt anh ta xuống mặt đất."
