  AvgDialog_8232_Content_5 = {
    Text = "Tôi là tội nhân."
  },
  AvgDialog_8232_Content_50 = {
    Text = "Giọng nói trầm ổn vang lên phía sau bạn, những tiếng bàn tán xung quanh dần dần nhỏ lại. Cuối cùng, chúng hoàn toàn im bặt. Mọi người tự động nhường đường để vị giám mục mặc áo choàng dài màu đen có thể đi qua thuận lợi."
  },
  AvgDialog_8232_Content_51 = {
    Text = "Giám mục Salvador bịt mắt nhưng vẫn đi đến chỗ các người một cách chính xác như thể có thể nhìn thấy. Sophia với vẻ mặt đầy ưu tư đi theo sau."
  },
  AvgDialog_8232_Content_52 = {
    Text = "Sophia……<Big:Sophia!>"
  },
  AvgDialog_8232_Content_53 = {
    Text = "Người trẻ tuổi đột nhiên trở nên kích động, anh ta dùng lực lượng vượt ngoài sự dự đoán của bạn để thoát khỏi sự kiềm chế của bạn, đến trước mặt Sophia——"
