  AvgDialog_8232_Content_55 = {
    Text = "Rồi đột ngột quỳ sụp xuống."
  },
  AvgDialog_8232_Content_56 = {
    Text = "Sophia, Sophia, tôi biết tôi đã sai rồi Sophia, xin hãy thanh tẩy tôi!"
