  AvgDialog_8232_Content_57 = {
    Text = "Yêu, Ê-đu-ard…?"
  },
  AvgDialog_8232_Content_58 = {
    Text = "Là tôi, là tôi! Tôi không nên lừa dối <Yellow:chị gái của bạn>, tôi hối hận, tôi thực sự hối hận!"
  },
  AvgDialog_8232_Content_59 = {
    Text = "Anh ta vừa khóc, vừa bò bằng đầu gối về phía trước, liên tục cúi đầu trước Sophia với một tư thế rất gượng gạo."
  },
  AvgDialog_8232_Content_6 = {
    Text = "Bạn đã phạm phải tội gì ?"
  },
  AvgDialog_8232_Content_60 = {
    Text = "Quỷ đã che mờ đôi mắt tôi, làm ô uế linh hồn tôi, xin hãy đánh đập tôi, thanh tẩy tôi! \n<Yellow:Phán xét> sẽ đến, tôi không muốn bị <Yellow:vùng đất vô tội> từ chối ở bên ngoài!"
