  },
  AvgDialog_8232_Content_73 = {
    Text = "Tôi sẽ ở lại đây một lúc nữa, xem có ai bị Edward dọa sợ hoặc làm bị thương cần giúp đỡ không."
  },
  AvgDialog_8232_Content_74 = {
    Text = "Bạn gật đầu, định quay đi thì ở rìa tầm mắt lại lóe lên ánh sáng giống như vừa rồi."
  },
  AvgDialog_8232_Content_75 = {Text = "?"},
  AvgDialog_8232_Content_76 = {
    Text = "Còn khỏe không, %player%? \nnếu thân thể không khỏe, tôi có thể làm một mình."
