  AvgDialog_8232_Content_9 = {
    Text = "Tôi nên sám hối với những người tôi đã hại, tôi nên sám hối với thần minh. \n Tôi nên chịu hình phạt roi, nên chảy máu cho đến khi tội lỗi đen tối chảy ra, để đạt được<Red:lọc sạch>."
