  AvgDialog_8236_Content_38 = {
    Text = "Tố Phi Á……"
  },
  AvgDialog_8236_Content_39 = {
    Text = "Giọng của Salvador trở nên yếu ớt, thân thể của anh ta rõ ràng đã trở nên trong suốt hơn một chút."
  },
  AvgDialog_8236_Content_4 = {
    Text = "Mùi tanh đã hoàn toàn nhấn chìm hương thơm quanh các người. Dưới ánh đỏ, máu bắn tung tóe trông như mực đen, những kẻ điên cuồng khuôn mặt dữ tợn, tựa như quỷ dữ."
  },
  AvgDialog_8236_Content_40 = {
    Text = "Lực lượng của anh ấy đang suy yếu nhanh chóng, nhưng anh ấy không thể dừng lại, một khi anh ấy dừng lại, những người xung quanh đang tự hành hạ điên cuồng sẽ chết hẳn."
  },
  AvgDialog_8236_Content_41 = {
    Text = "Làm sao đây, làm sao đây? \n Bạn nhìn quanh bốn phía, cuối cùng, ánh mắt bạn dừng lại ở chiếc gương của Sophia."
  },
  AvgDialog_8236_Content_42 = {
    Text = "Orci, tôi sẽ đi phân tán sự chú ý của cô ta, còn bạn hãy nhân cơ hội đó giật lấy gương của cô ta."
  },
  AvgDialog_8236_Content_43 = {
    Text = "Nhưng——"
  },
  AvgDialog_8236_Content_44 = {
    Text = "Tôi có thể tự chăm sóc bản thân. Đức Giám mục không còn cho chúng ta nhiều thời gian nữa, nhanh lên!"
  },
  AvgDialog_8236_Content_45 = {Text = "Đúng!"},
  AvgDialog_8236_Content_5 = {
    Text = "Trong dòng máu và sự tàn sát vô tận, chỉ có váy của Sophia vẫn còn sạch sẽ. Cô lau đi những giọt máu văng lên mặt và bật cười ha hả."
  },
  AvgDialog_8236_Content_6 = {
    Text = "Hãy chảy đi, chảy ra tội lỗi trong thân thể các người! Chảy ra máu của bóng tối!"
  },
  AvgDialog_8236_Content_7 = {
    Text = "Hãy sám hối, tội nhân! Trước khi người cầm đèn nghiêm khắc đưa ra phán quyết, hãy thanh tẩy linh hồn bẩn thỉu của các ngươi!"
  },
  AvgDialog_8236_Content_8 = {
    Text = "Chiếc gương cầm tay không ngừng nhấp nháy, ánh sáng đỏ tươi làm đau mắt bạn, thậm chí xuyên qua đôi mắt, đi thẳng vào đầu óc và tinh thần của bạn."
  },
  AvgDialog_8236_Content_9 = {
    Text = "Bạn vô thức ôm lấy đầu, ngón tay cắm sâu vào tóc. Tiếng ù tai lại chiếm lấy toàn bộ giác quan của bạn, một giọng nói thì thầm trong đầu bạn, giọng điệu và âm sắc ấy vừa xa lạ vừa quen thuộc."
  },
  AvgDialog_8238_Content_1 = {
    Text = "Do cơn thịnh nộ điên cuồng"
  },
  AvgDialog_8238_Content_10 = {
    Text = "Tốt rồi, các cậu, <Yellow:kẻ lừa đảo> đã tự đưa đến cửa rồi!"
  },
  AvgDialog_8238_Content_11 = {
    Text = "Đánh chúng, đánh chúng!"
  },
  AvgDialog_8238_Content_12 = {
    Text = "Đây, đây là nơi thánh của Đấng Cha Trời, không thể thực hiện bạo lực!"
  },
  AvgDialog_8238_Content_13 = {
    Text = "Đừng cản chúng tôi! Sophia, lẽ nào cô đã quên những việc anh ta làm với gia đình cô rồi sao?"
  },
  AvgDialog_8238_Content_14 = {
    Text = "Chúng tôi đang trả thù cho bạn, cho cô bé bất hạnh Milly!"
  },
  AvgDialog_8238_Content_15 = {
    Text = "Một viên đá bay qua đầu Sofia và đập vào chiếc ghế dài không xa các bạn."
  },
  AvgDialog_8238_Content_16 = {
    Text = "Đánh chết hắn, đánh chết hắn!"
