  AvgDialog_8238_Content_19 = {
    Text = "Một vật thể bay vút lên cao, ánh sáng phản chiếu làm chói mắt bạn. Bạn định bảo Sophia lùi lại thì chợt nghe tiếng kêu kinh ngạc của Salvador từ phía sau."
  },
  AvgDialog_8238_Content_2 = {
