  AvgDialog_8238_Content_20 = {
    Text = "Edward? Edward!"
  },
  AvgDialog_8238_Content_21 = {
    Text = "Người vừa mới mất ý thức không biết khi nào đã tỉnh lại, người trẻ tuổi đột ngột đẩy mạnh bạn ra, rồi nhanh chóng lao đến trước đám đông."
  },
  AvgDialog_8238_Content_22 = {
    Text = "Giết tôi đi, giết tôi đi!"
