  AvgDialog_8238_Content_25 = {
    Text = "Có thể quy định ——"
  },
  AvgDialog_8238_Content_26 = {
    Text = "Không được tiết lộ sự tồn tại của thân thể được đánh thức, điều này đương nhiên bạn biết. \nBạn nhìn về đám đông phát điên, cắn chặt răng."
  },
  AvgDialog_8238_Content_27 = {
    Text = "Tôi sẽ tìm cách giải quyết, cứu người là ưu tiên hàng đầu! Hành động nhanh lên!"
  },
  AvgDialog_8238_Content_28 = {
    Text = "Tôi hiểu rồi. \n Các vị, xin lỗi!"
  },
  AvgDialog_8238_Content_29 = {
    Text = "Đầu súng kim loại va chạm vào sàn đá tạo ra tia lửa, rào cản đen tối biến mất trong nháy mắt, biến thành một lực vô hình, đẩy mạnh về phía trước và buộc những người xung quanh phải lùi lại vài bước."
