  },
  AvgDialog_8238_Content_38 = {
    Text = "Các vị, tôi hiểu sự tức giận của các bạn, nhưng bạo lực chưa bao giờ là cách giải quyết đúng."
  },
  AvgDialog_8238_Content_39 = {
    Text = "\"Các ngươi không nên gây hại cho nhau, vì các ngươi mang dòng máu của ta, là anh em chị em với nhau.\"\nĐừng quên lời dạy của Cha Trời."
  },
  AvgDialog_8238_Content_4 = {
