  AvgDialog_8238_Content_9 = {
    Text = "Vậy thì giúp anh ta làm gì? Các người có phải là đồng bọn không?"
  },
  AvgDialog_8239_Content_1 = {
    Text = "Sophia đã mất hình dạng con người nhảy lên cao, nó duỗi dài móng vuốt, hướng về Salvador đang quỳ sau tấm bảng đá vồ tới."
  },
  AvgDialog_8239_Content_10 = {
    Text = "Những xúc tu tụ lại trên đỉnh đầu, tấm gương dính máu đông đặc đứng giữa, giống như một con mắt quái dị. Chú chó đầu người gào thét rồi lao vào tấn công bạn."
  },
  AvgDialog_8239_Content_11 = {
    Text = "Móng vuốt lao tới trong gió, mùi máu tanh nồng và hơi thối rữa tràn ngập khoang mũi của bạn. Bạn không kịp phản ứng, không thể nhúc nhích, tai chỉ còn vang lên tiếng kêu kinh hoàng của Orci."
