  AvgDialog_8239_Content_13 = {
    Text = "Hình bóng màu đen chắn giữa bạn và con quái vật khổng lồ, một bàn tay vuốt xuyên qua thân thể của giám mục, chỉ còn cách một chút nữa là chạm đến mặt bạn."
  },
  AvgDialog_8239_Content_14 = {
    Text = "Cái bảng đá đổ xuống với tiếng động lớn, ánh sáng xanh bao quanh nhấp nháy, gần như sẽ tắt."
  },
  AvgDialog_8239_Content_15 = {
    Text = "Tay chân rút ra, máu tươi tuôn ra lập tức tụ thành một vũng trên mặt đất. Salvador chao đảo hai lần, cuối cùng không thể chịu đựng được nữa, quỳ xuống đất."
