  },
  AvgDialog_8239_Content_3 = {
    Text = "Chiếc giáo dài bắn ra từ mặt đất xuyên thủng chi thể khô khốc, máu tối màu rơi xuống như mưa. Bạn đưa tay che chắn nhưng không dám rời mắt."
