  AvgDialog_8240_Content_18 = {
    Text = "Xương gãy, thịt máu bị xé rách, thân thể của Sophia bị xoắn vặn và thay đổi trước mặt các người. Đôi tay kéo dài một cách dị thường, vuốt nhọn thay thế cho năm ngón tay, chân sau gập lại, đầu ngón chân như chân sau của loài chó đạp trong vũng máu."
  },
  AvgDialog_8240_Content_19 = {
