  },
  AvgDialog_8254_Content_14 = {
    Text = "Salvador quỳ giữa các bảng đá, vẫn đang cố gắng duy trì sự hoạt động của chúng. \nAnh ta ngẩng đầu lên nhìn bạn, hai dòng máu chảy ra từ dưới băng trắng."
  },
  AvgDialog_8254_Content_15 = {
    Text = "Thưa chủ nhân, giám mục đang làm sao vậy?"
  },
  AvgDialog_8254_Content_16 = {
    Text = "Đó có lẽ là do sức mạnh tinh thần của người liên kết không đủ, nhưng sự bất ổn nghiêm trọng đến vậy… tôi chưa từng chứng kiến."
  },
  AvgDialog_8254_Content_17 = {
    Text = "Liên kết của tôi... là... vị giám mục tiền nhiệm ở đây... tôi không thể... làm phiền ông ấy thêm nữa.."
  },
  AvgDialog_8254_Content_18 = {
    Text = "Sứ giả nhợt nhạt… xin… xin hãy…"
  },
  AvgDialog_8254_Content_19 = {
    Text = "Anh run rẩy đưa tay lên, nhẹ nhàng đặt trên vai bạn. \nNhưng bạn hầu như không cảm nhận được trọng lượng của anh ấy."
  },
  AvgDialog_8254_Content_2 = {
    Text = "Những mảnh vỡ của gương bạc rơi như sao băng, và cùng với chúng, mặt trăng đỏ rực đầy vết nứt trên bầu trời dần tan biến."
  },
  AvgDialog_8254_Content_20 = {
    Text = "Anh ta đang nhanh chóng tan biến, trừ khi——"
  },
  AvgDialog_8254_Content_21 = {
    Text = "Bạn nắm lấy tay của Salvador và nhắm mắt lại."
  },
  AvgDialog_8254_Content_22 = {
    Text = "Tối tăm.\nTối tăm thật yên bình, như một vòng tay, lại như một giấc ngủ sâu."
  },
  AvgDialog_8254_Content_23 = {
    Text = "Những đốm sáng rực rỡ hiện lên trong tâm trí bạn: người dân xung quanh đầy hoảng loạn, còn Orci thì kiên định."
  },
  AvgDialog_8254_Content_24 = {
    Text = "Còn có một thứ phát ra ánh sáng xanh nhạt, hầu như không thể nhìn thấy, chính là ngôi sao thứ hai mà bạn đã thấy trước đó —— cũng chính là Salvador."
  },
  AvgDialog_8254_Content_25 = {
    Text = "Bạn tiến gần lại và nghe thấy tiếng trò chuyện mông lung."
  },
  AvgDialog_8254_Content_26 = {
    Text = "Gia đình tôi luôn cố gắng xóa bỏ khổ đau, truyền bá ơn huệ của Đấng Tạo Hóa, tại sao lại rơi vào tình cảnh này?"
  },
  AvgDialog_8254_Content_27 = {
    Text = "Im lặng đi! Không được phép xúc phạm cha tôi như vậy, ông ấy không phải là người như thế!"
  },
  AvgDialog_8254_Content_28 = {
    Text = "Thưa Đức Giám mục, tại sao thế giới luôn đầy rẫy đau khổ?"
  },
  AvgDialog_8254_Content_29 = {
    Text = "Nếu trên thế giới không có tội nhân, liệu…… những người như chị gái và mẹ tôi có còn bị người khác hại nữa không?"
  },
  AvgDialog_8254_Content_3 = {
    Text = "Một tiếng thét bi thảm vang lên, quái vật ngã xuống đất. Thân thể khổng lồ nhanh chóng tan chảy thành một vũng máu sẫm màu, chỉ còn lại một hình người nằm sấp trên mặt đất."
  },
  AvgDialog_8254_Content_30 = {
    Text = "Có phải sẽ thoát khỏi khổ nạn và sống hạnh phúc mãi mãi không?"
  },
  AvgDialog_8254_Content_31 = {
    Text = "Đây là trách nhiệm của tôi."
  },
  AvgDialog_8254_Content_32 = {
    Text = "Hình bóng của Salvador hiện lên bên cạnh bạn."
  },
  AvgDialog_8254_Content_33 = {
    Text = "Kí ức liên tục chuyển đổi trước mặt các bạn, anh ta trông không có biểu cảm gì, nhưng bạn có thể cảm nhận được một chút nỗi buồn."
  },
  AvgDialog_8254_Content_34 = {
    Text = "Tôi luôn biết rằng, trong lòng cô ấy vẫn luôn chất chứa oán hận. Tôi nghĩ cô ấy sẽ buông bỏ, nhưng kết quả chỉ là để cho lòng hận ngày càng tích tụ."
  },
  AvgDialog_8254_Content_35 = {
    Text = "Ông nói rằng ngày đó chính là ngài đã cứu ông, phải không, Đức Giám mục Salvador? Nhưng tại sao? \n Ông ta đã làm nhiều điều xấu, lừa dối nhiều người, vậy tại sao ngài vẫn giúp đỡ ông ta?"
  },
  AvgDialog_8254_Content_36 = {
    Text = "Lần thứ hai? Ai có thể cho gia đình tôi một cơ hội nữa, ai có thể cho chị gái và mẹ tôi một cơ hội nữa?"
  },
  AvgDialog_8254_Content_37 = {
    Text = "Họ đã chết, Đức Giám mục Salvador, họ đã trở về vòng tay của Cha Thiên Chúa, chỉ còn lại tôi…"
  },
  AvgDialog_8254_Content_38 = {
    Text = "Chỉ còn lại tôi…"
  },
  AvgDialog_8254_Content_39 = {
    Text = "Thượng đế thương xót, cho tôi một cơ hội để tái sinh sức sống. Tôi nên làm tốt hơn, nhưng giờ đây lại vấp ngã như trước đây."
  },
  AvgDialog_8254_Content_4 = {
    Text = "Mặt trăng máu tan đi, ánh nắng lại rọi xuống mặt đất, chiếu sáng người nằm trong vũng máu. \nXôphia ngây ngốc nhìn lên bầu trời, miệng vẫn thì thầm."
  },
  AvgDialog_8254_Content_40 = {
    Text = "Những tên trộm, cờ bạc, nghiện ngập, họ đến đây không phải để tìm sự tha thứ và cơ hội, mà là sự an ủi cho bản thân! Một cái cớ để tiếp tục làm điều xấu!"
  },
  AvgDialog_8254_Content_41 = {
    Text = "Tội nhân không biết hối cải, sẽ không hối cải. Sự khoan dung vô tận chỉ khiến người thiện thất vọng, kẻ ác hoành hành."
  },
  AvgDialog_8254_Content_42 = {
    Text = "Như vậy, cậu không cứu được ai cả."
  },
  AvgDialog_8254_Content_43 = {
    Text = "Tôi tha thứ cho họ, mang lại sự an ủi cho họ, như tôi đã tha thứ cho mọi người và mang lại sự an ủi cho mọi người. \nChúng ta đều được hưởng tình yêu của Đấng Tối Cao, đồng thời có quyền mắc lỗi và quay trở lại con đường đúng đắn."
  },
  AvgDialog_8254_Content_44 = {
    Text = "Khổ là điều Cha thần không muốn thấy, khổ là điều Cha thần hy vọng xóa bỏ, và cũng là trách nhiệm của ta, với tư cách Đại diện của Người, phải xóa bỏ."
  },
  AvgDialog_8254_Content_45 = {
    Text = "Nỗi khổ mà tôi gây ra, phải do chính tôi bù đắp."
  },
  AvgDialog_8254_Content_46 = {
    Text = "Anh ta đưa tay lên vẫy nhẹ, những ký ức đã phai màu như gợn sóng nước từ từ tan biến. Chúng tụ lại thành từng điểm sáng, tượng trưng cho tinh thần của anh."
  },
  AvgDialog_8254_Content_47 = {
    Text = "Anh ấy quay sang bạn, đưa ánh sáng mà anh ấy đang nâng niu trong lòng bàn tay đến trước mặt bạn."
  },
  AvgDialog_8254_Content_48 = {
    Text = "Hãy giúp tôi, sứ giả của sự tinh khiết. \nGiúp tôi xóa bỏ nỗi khổ của họ, để họ có thể yên bình đi hết con đường còn lại."
  },
  AvgDialog_8254_Content_49 = {
    Text = "Hạt ánh sáng"
  },
  AvgDialog_8254_Content_5 = {
    Text = "<Yellow:Êve> thưa bà…… con đã làm bà thất vọng, làm <Yellow:Người cầm đèn> thất vọng……\nCon không thể thanh tẩy được họ, cũng không thể rửa sạch tội lỗi……"
  },
  AvgDialog_8254_Content_50 = {
    Text = "Ánh sáng màu xanh trước mặt bạn lay động nhẹ nhàng như sợi tơ nhện, một đầu liên kết với một tinh thần già nhưng hiền từ, đầu kia thì chìm sâu vào điểm sáng trước mặt bạn."
  },
  AvgDialog_8254_Content_51 = {
    Text = "Bạn cẩn thận cắt đứt sợi dây mảnh, nhuộm nó bằng màu của bạn."
  },
  AvgDialog_8254_Content_52 = {
    Text = "Màu trắng nhẹ nhàng lan theo sợi chỉ vào trong, vào trong, đốm sáng dần hiện lên, từ từ xua tan bóng tối."
  },
  AvgDialog_8254_Content_53 = {
    Text = "Cảm ơn cậu."
  },
  AvgDialog_8254_Content_6 = {
    Text = "Người cầm đèn…người được đúc bằng bạc tinh khiết…xin hãy…"
  },
  AvgDialog_8254_Content_7 = {
    Text = "Cô hít một hơi, và không bao giờ thở ra được nữa."
  },
  AvgDialog_8254_Content_8 = {
    Text = "Cả quảng trường một mảnh hỗn độn —— những người bị quái vật gây thương tích nằm trên mặt đất, không ít đã mất sức sống, còn lại đang rên rỉ trong đau đớn, không hiểu tại sao mình lại trở thành như hiện tại."
  },
  AvgDialog_8254_Content_9 = {
    Text = "Uh... đầu tôi đau quá.."
  },
  AvgDialog_8256_Content_1 = {
    Text = "Bạn ném chiếc vali ra để chặn ngay cú vuốt đang lao tới. Thấy một đòn không trúng, con chó mặt người gầm gừ dữ dội với các bạn, rồi bật nhảy ngược lại và biến mất vào trong đám đông."
  },
  AvgDialog_8256_Content_2 = {
    Text = "Hướng đó… là Giám mục Salvador!"
  },
  AvgDialog_84130_Content_1 = {
    Text = "Trong bóng tối ngủ sâu, đột ngột có ánh sáng truyền đến."
  },
  AvgDialog_84130_Content_10 = {
    Text = "Khoan đã, mọi thứ chưa tệ đến mức đó..."
  },
  AvgDialog_84130_Content_11 = {
    Text = "Bạn tiến một bước về phía Kephrasat."
  },
  AvgDialog_84130_Content_12 = {
    Text = "Đừng lại đây! Những tia sét này sẽ gây tổn thương đến……"
  },
  AvgDialog_84130_Content_13 = {Text = "Đây…"},
  AvgDialog_84130_Content_14 = {
    Text = "Như bạn đã đoán, những tia sấm chớp đó không tấn công bạn, mà ngược lại, khi bạn tiến lại gần lại dịu bớt, có xu hướng ổn định."
  },
  AvgDialog_84130_Content_15 = {
    Text = "Tại sao……"
  },
  AvgDialog_84130_Content_16 = {
    Text = "Có vẻ tôi đã đoán không sai. Đây không phải là mất kiểm soát, mà là... ảnh hưởng của mạch thánh hà."
  },
  AvgDialog_84130_Content_17 = {
    Text = "Ảnh hưởng của mạch đất Thánh hà? Tôi đã nghe qua một số điều, nguyên lý của nó có lẽ tương tự như thuỷ triều ảnh hưởng đến cảm xúc của con người."
  },
  AvgDialog_84130_Content_18 = {
    Text = "Nói chung, những ảnh hưởng này sẽ rõ ràng nhất ở giai đoạn đầu, nhưng khi thích nghi dần sẽ yếu đi, vì vậy——"
  },
  AvgDialog_84130_Content_19 = {
    Text = "Cope Sanga bỗng nhiên nắm lấy tay bạn, đặt lên ngực của @2 cô ấy."
  },
  AvgDialog_84130_Content_2 = {
    Text = "Ánh sáng này càng lúc càng gần, càng lúc càng sáng, kèm theo âm thanh xì xèo của dòng điện."
  },
  AvgDialog_84130_Content_20 = {
    Text = "<Shake:!!!>"
  },
  AvgDialog_84130_Content_21 = {
    Text = "Tại sao ngài lại lùi lại? Là người giữ gìn, không phải việc chăm sóc người đánh thức là trách nhiệm của ngài sao?"
  },
  AvgDialog_84130_Content_22 = {
    Text = "Nhưng... điều này... không giống như..."
  },
  AvgDialog_84130_Content_23 = {
    Text = "Bạn không ngừng lùi lại, Kephrasat thì từng bước tiến tới gần."
  },
  AvgDialog_84130_Content_24 = {
    Text = "Biểu hiện của cô ấy vẫn như trước, nghiêm túc và đáng tin, nhưng khoảnh khắc này lại tràn đầy sự cứng rắn và kiên quyết."
  },
  AvgDialog_84130_Content_25 = {
    Text = "Thực hiện trách nhiệm của bạn, người giữ gìn."
  },
  AvgDialog_84130_Content_26 = {
    Text = "Tôi càng nhanh chóng thích nghi với ảnh hưởng của mạch nước Sông thiêng, trách nhiệm của bạn cũng sẽ sớm kết thúc."
  },
  AvgDialog_84130_Content_3 = {
    Text = "Có phải là điện bị cháy!?"
