  AvgDialog_84130_Content_6 = {
    Text = "Xin lỗi, người giữ gìn... Tôi đã uống hơn mười chai thuốc màu để ngủ, nhưng vẫn không thể chợp mắt."
  },
  AvgDialog_84130_Content_7 = {
    Text = "@2 trong đêm nay hoạt động đặc biệt, khiến ngọn lửa St. Elmo của tôi bắt đầu mất kiểm soát."
  },
  AvgDialog_84130_Content_8 = {
    Text = "Kheper Sanga nói và ấn tay lên ngực @2, nhưng thật vô ích, chỉ thấy @2 tiếp tục nhấp nháy dòng điện, càng lúc càng rực rỡ."
  },
  AvgDialog_84130_Content_9 = {
    Text = "Tôi hiểu rằng mất kiểm soát sẽ gây ra hậu quả gì, vì vậy người giữ gìn, hãy đánh ngất tôi đi, phải luôn có thể…"
  },
  AvgDialog_84354_Content_1 = {
    Text = "Người giữ gìn, khi gặp phải sát thương chí mạng, có thể kích hoạt khả năng kháng cự. Như bây giờ đây."
  },
  AvgDialog_84354_Content_2 = {
    Text = "Đó là khi người đánh thức dùng sức mạnh của mình để bùng nổ khi thân thể đang bên bờ gãy đổ. Nó có thể giúp bạn miễn nhiễm với sát thương chí mạng, và giữ lại 1 điểm cuộc sống."
  },
  AvgDialog_84354_Content_3 = {
    Text = "<Blue: Sau khi thành công, độ khó kích hoạt kháng cự sẽ không ngừng tăng lên.> Tôi phải nhắc nhở bạn, thay vì dựa vào vận may, hãy nắm giữ số phận trong tay."
  },
  AvgDialog_84354_Content_4 = {
    Text = "Tiếp tục tiến về phía trước, người giữ gìn. Đừng sợ hãi, bất kể con đường phía trước ra sao, tôi sẽ mãi mãi bên bạn."
  },
  AvgDialog_89068_Content_1 = {
    Text = "Hô……hô……"
  },
  AvgDialog_89068_Content_10 = {
    Text = "Khi những màu sắc đó được tiêm vào, bức tranh của Pickman bắt đầu run rẩy, như thể đó là một con thú khốn khổ đang vật lộn."
  },
  AvgDialog_89068_Content_11 = {
    Text = "Cuộc đấu tranh ngày càng mạnh mẽ, những sinh vật đáng sợ hơn bạn vừa mới gặp trào ra từ những bức tranh của ông."
  },
  AvgDialog_89068_Content_12 = {
    Text = "Những cái này là......"
  },
  AvgDialog_89068_Content_13 = {
    Text = "Khả năng của bạn vẫn thật ấn tượng, Pikman."
  },
  AvgDialog_89068_Content_14 = {
    Text = "Nhưng người xúc phạm xác chết, xúc phạm nghệ thuật chính là bạn."
  },
  AvgDialog_89068_Content_15 = {
    Text = "Tôi trân trọng tài năng của bạn, sẵn lòng cho bạn một cơ hội để nhận tội. Tôi không nỡ giết một họa sĩ xuất sắc."
  },
  AvgDialog_89068_Content_16 = {
    Text = "Nhưng không có cách nào. Vương quốc của tôi không thể chứa đựng những kẻ xúc phạm đến người đã khuất. Ăn cắp xác chết, giết hại những người vô tội, tội lỗi không thể thoát."
  },
  AvgDialog_89068_Content_17 = {
    Text = "Nếu bạn không muốn thừa nhận tội lỗi, hôm nay, tôi sẽ nhân danh chủ nhân của thành phố lăng mộ, ban cho bạn cái chết."
  },
  AvgDialog_89068_Content_18 = {
    Text = "Sương dày đặc từ Dullesain tỏa ra, bao trùm toàn bộ phòng tranh."
  },
  AvgDialog_89068_Content_19 = {
    Text = "Dù không phải là mục tiêu của Dolosein, bạn cũng cảm nhận được sự lạnh giá thấu xương trong sương mù dày đặc này."
  },
  AvgDialog_89068_Content_2 = {
    Text = "Bỏ cuộc đi, Pikeman, ngươi không phải là đối thủ của ta."
  },
  AvgDialog_89068_Content_20 = {
    Text = "Những con quái vật chảy ra từ bức tranh của Pikman, động tác cũng trở nên chậm chạp trong sương mù lạnh giá này."
  },
  AvgDialog_89068_Content_21 = {
    Text = "Những gì bạn nói, tôi không hiểu một chữ nào… cái gì là xúc phạm xác chết, cái gì là vi phạm pháp luật…"
  },
  AvgDialog_89068_Content_22 = {
    Text = "Những xác chết này, chẳng phải chính bạn đã bảo tôi tìm đến sao?"
  },
  AvgDialog_89068_Content_23 = {
    Text = "Bạn nói… gì?"
  },
  AvgDialog_89068_Content_24 = {
    Text = "Sương lạnh dừng lại, Pikman cũng ngừng chuyển động của những con quái vật. Dursein nhíu mày, đối diện với Pikman."
  },
  AvgDialog_89068_Content_25 = {
    Text = "Bạn đã cử người đến nói với tôi, rằng buổi tiệc tế linh lần này rất quan trọng, cần sáng tạo một tác phẩm lớn để thể hiện khung cảnh hoành tráng của buổi tiệc tế linh."
  },
  AvgDialog_89068_Content_26 = {
    Text = "Anh ta đã cho tôi một số địa chỉ, nói rằng đã chuẩn bị rất nhiều xác chết cho tôi mượn tạm thời, để tôi dùng làm người mẫu."
  },
  AvgDialog_89068_Content_27 = {
    Text = "\"Vũ điệu vạn linh\"! Tôi đã muốn sáng tác một tác phẩm khổng lồ như vậy từ lâu rồi! Một cơ hội hoàn hảo, tôi chẳng nghĩ ngợi gì đã đồng ý ngay lập tức. Sao, giờ bạn muốn rút lại lời nói sao?"
  },
  AvgDialog_89068_Content_28 = {
    Text = "Lấy xác chết làm mẫu, tại sao phải lấy đi bạc của họ?"
  },
  AvgDialog_89068_Content_29 = {
    Text = "Những lõi bạc đó không phải là thứ bạn muốn sao? Sau khi lấy thi thể, lõi bạc đều đã gửi cho bạn. Tôi biết bạn muốn mấy lõi bạc đó để làm gì……"
  },
  AvgDialog_89068_Content_3 = {
    Text = "Lính gác, hãy dẫn hắn đi."
  },
  AvgDialog_89068_Content_30 = {
    Text = "……Vậy, cô bé đó thì sao? Tại sao lại giết cô ấy?"
  },
  AvgDialog_89068_Content_31 = {
    Text = "Bôi nhọ! Tôi không phải là một nghệ sĩ biến thái, tác phẩm lần này cũng không cần cô làm người mẫu, tôi giết cô làm gì?"
  },
  AvgDialog_89068_Content_32 = {
    Text = "Tôi đã đi lấy xác của cô ấy, và cô ấy đã đuổi tôi đi. Tôi sợ cô ấy truyền tin khắp nơi, gây rắc rối cho cả tôi và bạn, nên đã để cô ấy ngủ một giấc."
  },
  AvgDialog_89068_Content_33 = {
    Text = "Ý ngươi là... cô ấy đã chết?"
  },
  AvgDialog_89068_Content_34 = {
    Text = "……Người đã bắt ngài thu thập xác chết để vẽ là ai?"
  },
  AvgDialog_89068_Content_35 = {
    Text = "Chỉ là một gã lính trong tòa lâu đài của ngài, tôi cũng không nhớ rõ vẻ ngoài của hắn. Hắn không có gì đặc sắc, cũng không có tính đại diện, không phù hợp để sáng tác những bức tranh mang tính sáng tạo..."
  },
  AvgDialog_89068_Content_36 = {
    Text = "Đèng——đèng——đèng——"
  },
  AvgDialog_89068_Content_37 = {Text = "Ừ——"},
  AvgDialog_89068_Content_38 = {
    Text = "Tiếng chuông vang vọng như sấm sét trên bầu trời Thành phố Xác Chôn. Cảm giác lạnh lẽo nhẹ nhàng mà bạn đã cảm nhận kể từ khi bước vào Thành phố Xác Chôn dường như tan biến dần theo âm thanh của chuông..."
  },
  AvgDialog_89068_Content_39 = {
    Text = "Có vẻ như có điều gì đó đã tấn công Durseyn. Hắn ôm chặt trái tim, một dòng máu đỏ tươi từ khóe miệng chảy ra."
  },
  AvgDialog_89068_Content_4 = {Text = "Đúng!"},
  AvgDialog_89068_Content_40 = {
    Text = "Không, không tốt rồi! Thánh chủ!"
  },
  AvgDialog_89068_Content_41 = {
    Text = "Sương lạnh của thành phố chôn cất... đã biến mất..."
  },
  AvgDialog_89068_Content_42 = {
    Text = "Đỗ Lê Sa Yên ngẩng đầu nhìn ra ngoài cửa sổ. Đám sương mù vốn mờ mịt, dần dần tan biến theo tiếng chuông ngân vang. Nghĩa trang mà bạn thấy khi vào thành phố Táng Tích, mơ hồ hiện lên giữa không trung của thành phố này."
  },
  AvgDialog_89068_Content_43 = {
    Text = "Thành phố và nghĩa địa, như một khối xếp hình được ghép lại một cách ngẫu hứng, một cách kỳ quái chồng chất lên nhau."
  },
  AvgDialog_89068_Content_44 = {
    Text = "Đây là… xảy ra chuyện gì vậy?"
  },
  AvgDialog_89068_Content_45 = {
    Text = "Sương lạnh che phủ nghĩa trang, bảo vệ thành phố chôn cất trong giấc mơ, đó là một ký hiệu gọi là\"Mộng Ảo Vân\"."
  },
  AvgDialog_89068_Content_46 = {
    Text = "Tôi đã cất giữ ấn ký quan trọng này tại vương phủ, nhưng bây giờ… ấn ký đã bị phá hủy."
  },
  AvgDialog_89068_Content_47 = {
    Text = "Thành phố này đã hoàn toàn lộ diện trước thế giới này… ha, tôi nghĩ rằng, những kẻ xâm lược sắp sửa xuất hiện rồi."
  },
  AvgDialog_89068_Content_48 = {
    Text = "Giọng nói của Dullesain có chút khàn khàn. Hắn không còn để ý đến máu ở khóe miệng, im lặng nhìn về tòa dinh thự hùng vĩ, đang bập bồng."
  },
  AvgDialog_89068_Content_49 = {
    Text = "Một số thứ quý giá lâu dài cùng với những phù ấn đã bị hủy hoại, đôi tay của anh ấy run rẩy nhẹ vì sức ép."
  },
  AvgDialog_89068_Content_5 = {
    Text = "Nhìn thấy quân sĩ đi về phía mình, Pikman khó khăn lắm mới đứng dậy được."
  },
  AvgDialog_89068_Content_50 = {
    Text = "Bạn ngạc nhiên nhìn khuôn mặt của Dule'n. Trên đó không có sự bất ngờ do những sự kiện bất ngờ xảy ra, không có sự tức giận bởi bị phản bội. Đó là một gương mặt mệt mỏi thuộc về một bậc quân vương."
  },
  AvgDialog_89068_Content_51 = {
    Text = "Sương mù quấn quanh anh như những con rắn độc, gửi đến những thực thể sắp bị tuyên án tử hình một sự tưởng nhớ lạnh lùng."
  },
  AvgDialog_89068_Content_52 = {
    Text = "……Ai đã làm vậy?"
  },
  AvgDialog_89068_Content_53 = {
    Text = "Người duy nhất có thể làm được những điều này, chỉ có một người, thưa ngài người giữ gìn."
  },
  AvgDialog_89068_Content_54 = {
    Text = "Đi nào, chúng ta trở về dinh thự. Tôi muốn hỏi anh ấy trực tiếp về tất cả những điều này, rằng lý do nào khiến anh ta muốn hủy diệt thành phố xác chết."
  },
  AvgDialog_89068_Content_6 = {
    Text = "Các bạn cái bọn….. không thể tha thứ! Nghệ thuật của tôi, tuyệt đối không cho phép các bạn xúc phạm!"
  },
  AvgDialog_89068_Content_7 = {
    Text = "Pikman nhắm mắt lại, hít một hơi thật sâu. Những sắc màu xoay quanh anh như dòng chảy hội tụ trên bức tranh."
  },
  AvgDialog_89068_Content_8 = {
    Text = "Tác phẩm của tôi, những di vật hoàn mỹ của tôi, tôi đã ban cho các bạn sự sống và sức mạnh... Hãy cùng nhau hoàn thành một nghệ thuật của sự sống..."
  },
  AvgDialog_89068_Content_9 = {
    Text = "Nhìn kìa, những tác phẩm nghệ thuật đó!"
  },
  AvgDialog_89069_Content_1 = {
    Text = "Khụ khụ……"
  },
  AvgDialog_89069_Content_10 = {
    Text = "Tin tức từ đây, tôi đã gửi đi. Rất nhanh, họ sẽ hồi sinh được vợ tôi……"
  },
  AvgDialog_89069_Content_11 = {
    Text = "Dù sao đi nữa, bạn cũng không thể cứu thành phố Thiên táng. Là tôi thắng, ngài Dullsaint."
  },
  AvgDialog_89069_Content_12 = {
    Text = "Bạn bây giờ không còn sức phản kháng, bạn không lo lắng tôi sẽ ăn thịt đến chết xác bạn và vợ bạn sao?"
  },
  AvgDialog_89069_Content_13 = {
    Text = "Làm như vậy, chỉ có ý nghĩa là phát tiết cơn giận."
  },
  AvgDialog_89069_Content_14 = {
    Text = "Ngài thường nói, sự tức giận là biểu hiện của sự bất lực, một người quý phái không nên để sự tức giận xâm chiếm tâm trí của mình."
  },
  AvgDialog_89069_Content_15 = {
    Text = "Ngài là người quý phái nhất mà tôi từng thấy, thưa ngài. Vì vậy, ngài sẽ không làm như vậy. Ngài sẽ lịch sự để tôi ra đi, lịch sự chấp nhận thất bại của mình, lịch sự, nhìn tôi đạt được mong muốn duy nhất của mình."
  },
  AvgDialog_89069_Content_16 = {
    Text = "Franz mỉm cười với Dulcain. Trong suốt nhiều năm gắn bó, anh tin rằng mình là người hiểu Dulcain nhất, thậm chí còn hiểu hơn cả chính Dulcain."
  },
  AvgDialog_89069_Content_17 = {
    Text = "Du Lệ Sai Y cơ thể hơi run, thở dài một cách sâu sắc."
  },
  AvgDialog_89069_Content_18 = {
    Text = "Mất đi một người bạn hiểu rõ tôi như vậy, là một điều đáng tiếc. Nhưng hiểu biết của bạn về tôi vẫn chưa đủ, Fran."
  },
  AvgDialog_89069_Content_19 = {
    Text = "Tôi thực sự sẽ không làm gì với bạn. Nhưng thật không may, bạn không thể thắng."
  },
  AvgDialog_89069_Content_2 = {
    Text = "Franz không để ý đến dòng máu chảy ra từ khóe miệng, cẩn thận phủi đi những mảnh vụn và bụi bẩn dính trên thi thể vợ, ánh mắt phức tạp nhìn về phía các bạn."
  },
  AvgDialog_89069_Content_20 = {
    Text = "Thánh chủ!"
  },
  AvgDialog_89069_Content_21 = {
    Text = "Dullesain vẫy tay về phía lính. Lính tiến lại gần Dullesain thì thầm vài câu, ông nhẹ nhàng gật đầu."
  },
  AvgDialog_89069_Content_22 = {
    Text = "Các chiến binh của tôi đã nói với tôi rằng buổi họp của lễ hội Hy sinh linh hồn đang ở thời điểm sôi động nhất."
  },
  AvgDialog_89069_Content_23 = {
    Text = "Đi nào, Ngài Người giữ gìn. Tôi nghĩ, bây giờ chúng ta có chút thời gian, có thể thưởng thức cảnh đẹp của thành phố Ngục Đá rồi."
  },
  AvgDialog_89069_Content_24 = {
    Text = "Từ ánh mắt thương hại của lão quản gia, Dulles đã thu hồi lại và quay lưng đi ra ngoài lâu đài."
  },
  AvgDialog_89069_Content_3 = {
    Text = "Cách thức triệu hồi sinh vật từ ký ức để chiến đấu, tôi chưa từng nghe qua. Khả năng của vị khách này thật khó tin."
  },
  AvgDialog_89069_Content_4 = {
    Text = "Du Lệ Sai Y, theo ngài nhiều năm, tôi phát hiện ra rằng, tôi dường như chưa bao giờ hiểu rõ ngài."
  },
  AvgDialog_89069_Content_5 = {
    Text = "Sức mạnh của ngài, mạnh mẽ hơn tôi tưởng."
  },
  AvgDialog_89069_Content_6 = {
    Text = "Kết thúc rồi, Fran."
  },
  AvgDialog_89069_Content_7 = {
    Text = "Trận chiến này có lẽ định sẵn kết thúc với sự thất bại của tôi... nhưng cuộc chiến này, mới chỉ bắt đầu."
  },
  AvgDialog_89069_Content_8 = {
    Text = "Lão quản gia cố gắng ngẩng đầu, nhìn thẳng vào đôi mắt của Dursein."
  },
  AvgDialog_89069_Content_9 = {
    Text = "Thành phố di hài đã xuất hiện trên thế giới, quân địch xâm lấn sắp đến. Bạn không có đủ thời gian để sửa chữa Biểu chú."
  },
  AvgDialog_89070_Content_1 = {
    Text = "Sau khi xử lý xong những cơ thể phân rã đó, bạn ném hai thây ma đang ngất xỉu vào quan tài, đậy nắp quan tài lại, mùi thối của cơ thể và bụi mang theo bào tử nấm khiến bạn cảm thấy buồn nôn."
  },
  AvgDialog_89070_Content_10 = {
    Text = "Sương lạnh dày đặc vừa rồi đã hoàn toàn biến mất với tốc độ mà mắt thường có thể nhìn thấy. Cùng với nó, những ngôi mộ vô cùng rộng lớn và mảnh đất dưới chân cũng biến mất."
  },
  AvgDialog_89070_Content_11 = {
    Text = "Tại nơi từng chồng chất mồ mả, dưới chân bạn, một thành phố huy hoàng như Londinium bỗng nhiên mọc lên."
  },
  AvgDialog_89070_Content_12 = {
    Text = "Một tòa lâu đài cổ kính đồ sộ vươn mình giữa trung tâm thành phố, bề mặt phủ đầy những góc cạnh không đều và vết nứt, như một chiếc xương nhọn, thô ráp."
  },
  AvgDialog_89070_Content_13 = {
    Text = "Ánh trăng và sương mù phủ lên lâu đài như một lớp voan nhẹ, mùi hôi thối gây buồn nôn và hơi thở của xác thối trong nghĩa trang, ngưng đọng như thể có hình thể trong thành phố này."
  },
  AvgDialog_89070_Content_14 = {
    Text = "Vương thành của thi thể…… lại ẩn giấu trong giấc mơ……"
  },
  AvgDialog_89070_Content_15 = {
    Text = "Nguyên liệu mới đã đến!"
  },
  AvgDialog_89070_Content_16 = {
    Text = "Đặt ở đây là được, kiểm tra xong, chúng ta sẽ ngay lập tức gửi cho Thánh chủ."
  },
  AvgDialog_89070_Content_17 = {
    Text = "Một đội thây ma khác đang khiêng quan tài đến cổng lâu đài. Bạn đứng trên tháp chuông ẩn mình, nhìn xa về cổng lâu đài."
  },
  AvgDialog_89070_Content_18 = {
    Text = "Có vẻ như, nơi này chính là chốn cư ngụ của Thánh Chủ mà họ nói đến. Nếu muốn biết bí mật của vương thành này, không nơi nào thích hợp hơn ở đây."
  },
  AvgDialog_89070_Content_19 = {
    Text = "Bạn vỗ nhẹ vào chiếc quan tài bên cạnh, lặng lẽ đi xuống tháp chuông, trong màn đêm xa lạ này, lén lút hướng về lâu đài nguy hiểm đó."
  },
  AvgDialog_89070_Content_2 = {
    Text = "Hừ... thật sự nên để Búp bê cho ta thêm một bình hương liệu."
  },
  AvgDialog_89070_Content_3 = {
    Text = "Những gì họ vừa nói về \"kêu chuông\", có lẽ chính là thứ này..."
  },
  AvgDialog_89070_Content_4 = {
    Text = "Bạn nhìn chiếc đồng hồ cô đơn đang treo lơ lửng trên đống đổ nát của tháp chuông. Cơ thể đồng hồ lớn ấy đã trở thành một sân nhảy hoang vắng trong những năm tháng dài, nơi mà gỉ sét và địa y vui chơi."
  },
  AvgDialog_89070_Content_5 = {
    Text = "Bạn cầm cái búa đá tìm được từ xác xác sống, xem xét những hoa văn phức tạp như những chiếc gai và chiếc răng trên nó."
  },
  AvgDialog_89070_Content_6 = {Text = "Đinh —"},
  AvgDialog_89070_Content_7 = {
    Text = "Búa đá bất ngờ rơi xuống thân chuông. Một âm thanh nấc nghẹn vang lên trong nghĩa trang vô tận này."
  },
  AvgDialog_89070_Content_8 = {
    Text = "Ngay khi âm thanh vang lên, bạn không thể cưỡng lại mà bị cuốn vào một giấc mơ. Trong giấc mơ, sương lạnh trở nên dày đặc, nuốt chửng tất cả những gì trong tầm nhìn của bạn, ngay cả đôi bàn tay bạn cũng khó có thể nhìn thấy."
  },
  AvgDialog_89070_Content_9 = {
    Text = "Cái này...... cái này là!! ......"
  },
  AvgDialog_89071_Content_1 = {
    Text = "Lưỡi dao khổng lồ xoay tròn bay ra, đâm sâu vào trong cát sỏi. Goliath khó khăn lắm mới chịu đựng được cú va chạm mạnh mẽ, lùi lại vài bước."
  },
  AvgDialog_89071_Content_10 = {
    Text = "Tôi đã nói, sức mạnh, thời gian, đều đứng về phía tôi..."
  },
  AvgDialog_89071_Content_11 = {
    Text = "Tôi đã chơi với các bạn đủ lâu rồi. Những việc tiếp theo, giao cho họ."
  },
  AvgDialog_89071_Content_12 = {
    Text = "Khi Goliath phát biểu xong, một ánh sáng đỏ chói mắt từ vòng pháp trận sau lưng anh ta xuất hiện."
  },
  AvgDialog_89071_Content_13 = {
    Text = "Những người lính trên tường thành nghe thấy tiếng khóc của đại dương. Hàng ngàn xác của thủy thủ đang phân hủy nổi lên, từ các vết thương xuất hiện những xúc tu sáng phát quang, như những sợi chỉ mùi hôi được điều khiển bởi một thợ may vô hình đang khâu lại với nhau."
  },
  AvgDialog_89071_Content_14 = {
    Text = "Một sinh vật trẻ bị cắt đứt nửa thân trên nối với đuôi của một quái thú biển, một tín đồ với đầu vỡ nát bị nhét vào ngực rất nhiều trái tim vẫn đang đập."
  },
  AvgDialog_89071_Content_15 = {
    Text = "Tôi rất quan tâm đến bạn và khả năng của bạn, người lạ. Rất tiếc, bạn đã từ chối lời đề nghị của tôi."
  },
  AvgDialog_89071_Content_16 = {
    Text = "Tôi sẽ rất hứng thú nghe những bí mật của bạn — nếu bạn sống sót."
  },
  AvgDialog_89071_Content_17 = {
    Text = "Goliath mang theo thanh kiếm lớn, quay lưng bỏ đi, không nhìn một lần nào vào những Thủy thủ đã chết."
  },
  AvgDialog_89071_Content_18 = {
    Text = "Khi anh ta bước tới, dưới đáy biển vang lên những chấn động ầm ầm, tất cả các linh hồn đang giao chiến đột nhiên cứng đờ."
  },
  AvgDialog_89071_Content_19 = {
    Text = "Áo của Dullesain rách thành những vết mạng nhện, qua làn sương lạnh vỡ vụn, hắn thấy những cái hố biển sâu hàng km đang chuyển động — một sinh vật nào đó phủ đầy hải quỳ và xích tàu đắm, đang được cuộc hiến tế của thủy thủ gọi dậy."
  },
  AvgDialog_89071_Content_2 = {
    Text = "Anh lau sạch máu nơi khóe miệng, đôi mắt như thú dữ nhìn chằm chằm vào các bạn."
  },
  AvgDialog_89071_Content_20 = {
    Text = "Bạc trên boong dường như nghe thấy một mệnh lệnh nào đó, mạnh mẽ rung lên. Ánh sáng bạc hòa vào vòng tròn ma thuật, liên kết với máu, tiêm vào xác của từng thủy thủ."
  },
  AvgDialog_89071_Content_21 = {
    Text = "Âm thanh xào xạc của đất từ dưới chân bạn vang lên, bạn ngẩng đầu lên, thấy một xác thủy thủ đang từ từ di chuyển trên mặt đất, dường như đang bị một lực vô hình kéo đi."
  },
  AvgDialog_89071_Content_22 = {
    Text = "Xác chết này đang di chuyển… xác chết mà bạn điều khiển trông có vẻ có ý thức riêng, nhưng nhìn chung, chúng vẫn chỉ là xác chết…"
  },
  AvgDialog_89071_Content_23 = {
    Text = "Bạn nói không sai, tôi điều khiển những linh hồn của người chết qua việc giao tiếp với họ, trong khi những Thủy thủ đang sử dụng cấm thuật của Thành phố Đồ Cổ."
  },
  AvgDialog_89071_Content_24 = {
    Text = "Họ thông qua bạc, trao cho những xác chết sức mạnh, rồi..."
  },
  AvgDialog_89071_Content_25 = {
    Text = "Dưới tác động của ánh sáng, thi thể của các Thủy thủ bắt đầu di chuyển về hướng Thầy tu Thủy thủ, như một dòng thủy triều mục rữa."
  },
  AvgDialog_89071_Content_26 = {
    Text = "Sợi chỉ bạc và đỏ xuyên qua thân xác và các chi, như một thợ dệt vụng về, đang khâu một con búp bê kỳ quái và khổng lồ."
  },
  AvgDialog_89071_Content_27 = {Text = "Ừ——"},
  AvgDialog_89071_Content_28 = {
    Text = "Mặt đất... đang rung chuyển..."
  },
  AvgDialog_89071_Content_29 = {
    Text = "Giọng nói trầm thấp vang lên từ bờ biển. Người thợ dệt của Aequor đã hoàn thành tác phẩm của mình."
  },
  AvgDialog_89071_Content_3 = {
    Text = "Thể chất tốt, thường thì sẽ rất cứng nếu sử dụng làm nguyên liệu, nhưng chỉ cần xử lý một chút, chắc chắn sẽ biến thành một món đại tiệc rất ngon miệng……"
  },
  AvgDialog_89071_Content_30 = {
    Text = "Khi tiếng kêu răng xương cuối cùng phát ra, một thể hiện biến dạng như núi đứng vững giữa chiến trường."
  },
  AvgDialog_89071_Content_31 = {
    Text = "Quái vật khổng lồ này được ghép lại từ hàng ngàn thi thể, bề mặt được bao phủ bởi lớp vảy ngọc trai không ngừng sinh sôi."
  },
  AvgDialog_89071_Content_32 = {
    Text = "Hàng chục cánh tay dài ngắn khác nhau, đầu mút vừa có càng kẹp sinh vật biển vừa có bàn tay người, đầu chính là khuôn mặt tế sư với ngọn lửa hồn trắng bệch đang cháy rực và nụ cười mãn nguyện."
  },
  AvgDialog_89071_Content_33 = {
    Text = "Ánh sáng tím dần dần biến mất, quái thú từ trung tâm vòng tròn ma thuật đứng dậy chầm chậm. Dây thanh âm làm từ xương phát ra tiếng rên rỉ trầm đục."
  },
  AvgDialog_89071_Content_34 = {
    Text = "Xác chết chưa được khâu nối liên tục rơi từ cơ thể của sinh vật khổng lồ, đôi mắt vô hồn nhắm chặt, nắm chặt lưỡi dao dưới ánh sáng mờ ảo, tiến về cổng thành phố hỏa táng."
  },
  AvgDialog_89071_Content_35 = {
    Text = "Rầm——"
  },
  AvgDialog_89071_Content_36 = {
    Text = "Vật khổng lồ bước đi, dẫm nát những linh hồn bé nhỏ dưới chân. Đôi mắt được tạo thành từ xác chết tức giận mở lớn nhìn về phía các bạn, dây thanh âm được khâu bằng xương cốt rung động, phát ra tiếng rên rĩ chói tai."
  },
  AvgDialog_89071_Content_37 = {
    Text = "Quy y... Ngài!"
  },
  AvgDialog_89071_Content_4 = {
    Text = "Dul Alain vừa nói vừa vẫy tay. Sương mù đen vô tận xung quanh đột ngột co lại về phía Goliath, nhưng không như Dul Alain dự đoán, Goliath không bị nuốt chửng."
  },
  AvgDialog_89071_Content_5 = {
    Text = "Goliath dẫm lên sỏi, bất ngờ lùi lại, tốc độ do sức mạnh không thể tưởng tượng mang lại đã giúp hắn tránh được cuộc tấn công từ Doulcain."
  },
  AvgDialog_89071_Content_6 = {
    Text = "……Cuộc chiến vừa rồi, còn xa mới đến giới hạn của ngài."
  },
  AvgDialog_89071_Content_7 = {
    Text = "Hừ... ta thừa nhận, so với những nhà vua yếu đuối chết dưới lưỡi dao này, ngươi thực sự xứng đáng là một bậc thống trị."
  },
  AvgDialog_89071_Content_8 = {
    Text = "Tuy nhiên, để đánh bại tôi, không phải là điều dễ dàng."
  },
  AvgDialog_89071_Content_9 = {
    Text = "Goliath phủi bụi trên người, liếc nhìn về phía sau, cười lắc đầu."
  },
  AvgDialog_89072_Content_1 = {
    Text = "Cứ giao chỗ này cho tôi, Đại Nhân Goliath."
