  AvgDialog_89073_Content_102 = {
    Text = "Đỗ Lê Sa Yên nhìn thấy mặt trăng sắp biến mất giữa những tòa nhà, cười một cách thoải mái."
  },
  AvgDialog_89073_Content_103 = {
    Text = "Sau khi Phù chú Mộng Mị được phục hồi, thành phố Tử Thi sẽ lại biến mất khỏi thế giới này."
  },
  AvgDialog_89073_Content_104 = {
    Text = "Vương quốc của tôi thuộc về một chiều không gian khác, tôi sẽ sửa đổi nó với điểm neo của thế giới này."
  },
  AvgDialog_89073_Content_105 = {
