  AvgDialog_89073_Content_106 = {
    Text = "Anh ấy giơ tay ra, nhẹ nhàng vỗ vai bạn."
  },
  AvgDialog_89073_Content_107 = {
    Text = "Đợi tôi sắp xếp cho dân chúng xong, tôi sẽ nghĩ cách giúp ông. Tôi nghĩ rằng, chúng ta nhất định còn có cơ hội cùng nhau sát cánh."
