  AvgDialog_89073_Content_109 = {
    Text = "Tạm biệt, Đỗ Lê Sa Yên."
  },
  AvgDialog_89073_Content_11 = {
    Text = "Dù trăng tròn đã rời xa, chỉ cần kết nối với linh hồn vẫn còn, mỗi ngày đều có thể là lễ hội thờ cúng."
