  AvgDialog_89073_Content_110 = {
    Text = "Âm thanh của còi xa văng vẳng trên mặt biển tĩnh lặng."
  },
  AvgDialog_89073_Content_111 = {
    Text = "Tàu thuyền dần xa bờ. Những công trình lộng lẫy của thành phố di hài dần biến mất trong sương mù, cho đến khi một lần bạn chớp mắt, chúng hoàn toàn không còn, như thể chưa từng hiện hữu, chỉ còn lại một nghĩa trang mới với vô số bia mộ."
  },
  AvgDialog_89073_Content_112 = {
    Text = "Bạn quay lưng lại, đứng trên boong tàu, cảm nhận hơi gió ấm áp và ẩm ướt từ biển thổi vào mặt, cảm nhận ánh nắng ban mai sáng rực trên gương mặt, hướng về vương quốc đã thất lạc mà bạn đã nghe đến vô số lần."
  },
  AvgDialog_89073_Content_12 = {
    Text = "Còn về vết thương... lời của lương y, nghe một nửa là đủ."
  },
  AvgDialog_89073_Content_13 = {
    Text = "So với sự bảo vệ của tôi, thần dân của Thành phố Mộ cần hơn là nghệ thuật nấu ăn của tôi."
  },
  AvgDialog_89073_Content_14 = {
    Text = "Du Lệ Sai Y nhìn những xác sống bắt đầu nhảy múa cùng với các hồn ma trong sàn nhảy, chia sẻ những xác chết trên bàn, nở một nụ cười thỏa mãn."
