  AvgDialog_89073_Content_15 = {
    Text = "……Ngài thật biết khen bản thân."
  },
  AvgDialog_89073_Content_16 = {
    Text = "Thật tiếc khi mang theo thương tích, không thể hoàn thành tất cả các món ăn. Tuy nhiên, ta đã tốn rất nhiều công sức để chuẩn bị một món chính xuất sắc."
  },
  AvgDialog_89073_Content_17 = {
    Text = "Tôi thường không muốn tự khen mình, nhưng hãy tin tôi, thưa Ngài người giữ gìn, đây chắc chắn là món ngon mà bạn chưa bao giờ thấy trong đời."
  },
  AvgDialog_89073_Content_18 = {
    Text = "Đỗ Lê Sa Yên mở nắp đĩa thức ăn lộng lẫy đó. Một hương thơm thịnh soạn bay vào mũi bạn."
  },
  AvgDialog_89073_Content_19 = {
    Text = "Xác của thầy tu Thủy thủ nằm yên tĩnh trong đĩa ăn, toàn thân được trang trí bằng những san hô lấp lánh, bên trong lồng ngực bị vỡ là những thực vật biển tinh xảo, khiến toàn bộ xác thể trở nên uy nghi và nghiêm trang."
  },
  AvgDialog_89073_Content_2 = {
    Text = "Mười hai tiếng chuông từ nơi xa vọng lại, ánh trăng khuyết sáng rực rỡ chiếu qua những đám mây mỏng và chiếu vào đôi mắt bạn."
  },
  AvgDialog_89073_Content_20 = {
    Text = "Không thiên vị mà xem, đây là một đối thủ đáng kính, xứng đáng được hưởng vinh dự là món chính."
  },
  AvgDialog_89073_Content_21 = {
    Text = "Bạn biết rằng, thi thể của anh ấy đã bị phá hủy không thể cứu vãn, để phục hồi dáng vẻ của anh ấy, tôi đã tốn không ít công sức."
  },
  AvgDialog_89073_Content_22 = {
    Text = "So với động vật trên cạn, thịt của người sâu biển mềm hơn, đây là đặc điểm nổi bật nhất của họ, để giữ nguyên hương vị cốt lõi này, tôi đã dùng mỡ xác đã được xử lý bằng gia vị đặc biệt để hầm chậm."
  },
  AvgDialog_89073_Content_23 = {
    Text = "Ngoài ra, cũng muốn cảm ơn sự giúp đỡ của ngươi. Như ta đã nói trước đó, việc khử mùi tanh của người sâu biển là đặc biệt quan trọng, đây là kinh nghiệm quý báu mà ta thu được sau vô số lần thực hành."
  },
  AvgDialog_89073_Content_24 = {
    Text = "Di ngôn của bạn tôi vẫn còn nhớ như in…… dù bạn nói gì, tôi sẽ không ăn xác."
  },
  AvgDialog_89073_Content_25 = {
    Text = "Ái chao...sẽ có một ngày, bạn sẽ cảm thấy tiếc nuối cho cuộc đời cằn cỗi của mình."
  },
  AvgDialog_89073_Content_26 = {
    Text = "Du Lệ Sai Y tiếc nuối lắc đầu."
  },
  AvgDialog_89073_Content_27 = {
    Text = "Nhanh chóng tận hưởng lễ hội của bạn đi. Sau lễ hội, đừng quên điều mà bạn đã hứa với tôi."
  },
  AvgDialog_89073_Content_28 = {
    Text = "Xin hãy yên tâm, ngài người giữ gìn, vua xác thịt không bao giờ phản bội lời thề."
  },
  AvgDialog_89073_Content_29 = {
    Text = "Món chính này, chính là để dành cho bạn, để thực hiện lời hứa này."
  },
  AvgDialog_89073_Content_3 = {
