  },
  AvgDialog_89073_Content_30 = {
    Text = "Nhìn vào ánh mắt nghi ngờ của bạn, Dulles cắt một miếng từ xác của thầy tu Thủy thủ, đặt vào đĩa của mình."
  },
  AvgDialog_89073_Content_31 = {
