  AvgDialog_89085_Content_47 = {
    Text = "Đỗ Lê Sa Yên ngẩng mặt lên, như thể muốn hiến mình cho mặt trăng."
  },
  AvgDialog_89085_Content_48 = {
    Text = "Sương mù hùng vĩ từ cơ thể anh ta chảy vào từng ngôi mộ, ánh sáng tím tỏa sáng dưới lòng đất của thành phố chôn cất."
  },
  AvgDialog_89085_Content_49 = {
    Text = "Bùa chú của Dullesain tạo ra tiếng vang của mặt đất, những ngôi mộ ở bãi bờ biển nổ tung liên tục, vô số thi thể thối rữa bò ra từ bùn."
  },
  AvgDialog_89085_Content_5 = {
    Text = "Những tiên phong đã có tin tức mới chưa?"
