  AvgDialog_89085_Content_50 = {
    Text = "Những chiến binh linh hồn đã ngủ yên hàng thế kỷ, ánh sáng tím nhảy múa trong hốc mắt, giữa các hàm răng phát ra tiếng gầm như giấy nhám ma sát."
  },
  AvgDialog_89085_Content_51 = {
    Text = "Đỗ Lê Sa Yên mở miệng, lộ ra những chiếc răng nhọn, với nụ cười giống như thú hoang, nhìn vào những con mồi từ sâu biển."
  },
  AvgDialog_89085_Content_52 = {
    Text = "Hãy tận hưởng đêm này, thần dân của tôi——Lễ hội thờ cúng linh hồn, bắt đầu tiệc ăn!"
  },
  AvgDialog_89085_Content_6 = {
    Text = "Báo cáo với ngài, các tín đồ tiền trạm đã gửi tin, kế hoạch diễn ra rất suôn sẻ."
  },
  AvgDialog_89085_Content_7 = {
    Text = "Nhưng mà, sự hiện diện của tàu tuần tra ở khu vực bờ biển dạo này rõ ràng đã gia tăng. Những kẻ ngoại đạo trong Thành phố Đám tang dường như đã nhận ra điều gì đó."
