  AvgDialog_89085_Content_8 = {
    Text = "Phù ấn bị phá hủy, cộng thêm lễ hội thờ cúng linh hồn sắp đến, nếu thành phố Thiên Tàn không có động tĩnh gì, thì đó sẽ không bình thường."
