  AvgDialog_89086_Content_12 = {
    Text = "Đối với một vị quân vương, niềm vui lớn nhất chắc chắn là thấy thần dân sống yên ổn."
  },
  AvgDialog_89086_Content_13 = {
    Text = "Dành chút thời gian để thưởng thức cuộc sống của họ, như thể tận hưởng một món ăn ngon mà mình đã chuẩn bị công phu."
