  AvgDialog_89086_Content_15 = {
    Text = "Tất nhiên là không. Những kẻ xâm nhập đó, giờ mới vừa kết thúc cuộc thảo luận của họ."
  },
  AvgDialog_89086_Content_16 = {
    Text = "Một phần đã rời khỏi Thành phố Quách, thông báo cho lãnh đạo của họ. Còn một phần khác, hiện đang tiến gần về phía chúng ta, chuẩn bị tấn công chúng ta rồi."
