  AvgDialog_89086_Content_18 = {
    Text = "Bạn vừa mới đến không lâu, đúng lúc có thể trải nghiệm một cách tốt hơn tại chợ trong khoảng thời gian này."
  },
  AvgDialog_89086_Content_19 = {
    Text = "Cửa hàng hộp nhớ có lẽ khá phù hợp với bạn. Ngay cả khi không phải là xác thịt, chỉ cần ăn một ít chuyển não, bạn vẫn có thể trải nghiệm một đoạn ký ức thuộc về người khác, rất phù hợp với bạn là một du khách."
