  AvgDialog_89086_Content_23 = {
    Text = "Ah, cảm ơn vì lời khen. Thư giãn... như thể đang ngủ trong một cái quan tài gỗ sồi tốt nhất trong ba trăm năm. Tôi thích từ này."
  },
  AvgDialog_89086_Content_24 = {
    Text = "Tiền đội của kẻ xâm nhập vẫn chưa vào thành phố Di thể đã bị các bạn theo dõi. Sau khi họ vào thành, mọi động tĩnh đều nằm trong tầm kiểm soát của các bạn."
