  AvgDialog_89086_Content_32 = {
    Text = "Xin đừng nhìn tôi bằng ánh mắt đó, ngài người giữ gìn. Những gì tôi đã hứa tự nhiên sẽ được thực hiện. Nhưng bây giờ tôi thực sự bất lực."
