  AvgDialog_89086_Content_35 = {
    Text = "Nếu đã như vậy, tôi có thể chờ. Nhưng tôi nói trước, không quan trọng bạn đang chống lại thế lực nào, việc đó là giữa các bạn, không liên quan đến tôi…"
  },
  AvgDialog_89086_Content_36 = {
    Text = "Một làn sóng năng lượng linh hồn ẩn bí không thoát khỏi tâm trí bạn. Bạn cảnh giác dừng lại, nghiêm túc cảm nhận."
  },
  AvgDialog_89086_Content_37 = {
    Text = "Một vài cá thể khác biệt rõ ràng với thây ma đang ẩn mình sau đám đông trong chợ, từ nhiều hướng đang tiến lại gần bạn."
  },
  AvgDialog_89086_Content_38 = {
    Text = "Đỗ Lê Sa Yên trao đổi ánh mắt với bạn, dùng ngón tay gõ nhịp trên bàn vài lần. Một tên lính gác ở bên cạnh nhận được lệnh, lặng lẽ biến mất ở góc phố."
