  },
  AvgDialog_89086_Content_46 = {
    Text = "Bạn đột ngột ngẩng đầu nhìn về phía Dulehsain. Anh ta mỉm cười đặt ly xuống. Cùng lúc đó, một chục bóng người từ trong đám đông lao ra, rút vũ khí về phía các bạn."
