  AvgDialog_89087_Content_11 = {Text = "?!!!"},
  AvgDialog_89087_Content_12 = {
    Text = "Một bản nhạc mới đầy nhịp điệu đột ngột vang lên. Dulesin lùi lại một bước, tuyên bố sự khởi đầu của điệu nhảy này."
