  },
  AvgDialog_89087_Content_51 = {
    Text = "Lão quản gia đi qua một bên sàn nhảy, ghé sát tai Dursein thì thầm vài câu."
  },
  AvgDialog_89087_Content_52 = {
    Text = "Du Lệ Sai Y vẫn mang nụ cười ôn hòa, nhưng đôi mắt của hắn đã lóe lên một ánh sáng lạnh lẽo đáng sợ."
  },
  AvgDialog_89087_Content_53 = {
    Text = "Người bạn trộm mộ này, thật biết chọn thời điểm. Trên bàn ăn ngày mai, có lẽ lại có thêm một món ngon."
  },
  AvgDialog_89087_Content_6 = {
    Text = "Cảm ơn sự hiện diện của ngài, người giữ gìn. Tôi nghĩ rằng, giữa chúng ta có nhiều hiểu lầm. Thực ra tôi rất quan tâm đến cơ thể của bạn... nhưng hãy yên tâm, tôi sẽ không động đến nó một chút nào. Ít nhất, không phải bây giờ."
  },
  AvgDialog_89087_Content_7 = {
    Text = "Tôi đến với bạn không phải để nghe điều này......"
  },
  AvgDialog_89087_Content_8 = {
    Text = "Vậy, để bạn không còn cảm thấy thù địch với vùng đất này, cũng như với tôi nữa……"
  },
  AvgDialog_89087_Content_9 = {
    Text = "Một tay anh ấy để sau lưng, tay kia nhẹ nâng lên, ra hiệu mời bạn như trong vũ điệu."
  },
  AvgDialog_89088_Content_1 = {
    Text = "Những xác xác thịt bị giết chết gục xuống đất, biến thành một vũng dịch lỏng, bên trong hoàn toàn trống rỗng."
  },
  AvgDialog_89088_Content_10 = {
    Text = "Du Lệ Sai Y tiến tới bên cô gái, ôm cô vào lòng, đầu ngón tay nhẹ nhàng vuốt qua tóc cô."
  },
  AvgDialog_89088_Content_100 = {
    Text = "Hắn dường như quên hết mọi thứ về nguyên liệu và kỹ thuật nấu nướng. Hắn ăn rất chậm, rất cẩn thận, trang nghiêm, nhẹ nhàng, dùng tất cả nhiệt huyết của mình để ăn xác của cô bé."
  },
  AvgDialog_89088_Content_101 = {
    Text = "Những câu chuyện bình thường đó hiện lên trong tâm trí của anh. Anh đã chứng kiến gia đình này từ thịnh vượng đến suy tàn, chứng kiến nỗi buồn vui của họ trải qua nhiều thế hệ, chứng kiến kết thúc của họ trước lễ hội cúng linh hồn."
  },
  AvgDialog_89088_Content_102 = {
    Text = "Họ đáng lẽ nên biến mất trong dòng sông lịch sử, nhưng giờ đây, hắn sẽ với danh nghĩa vua xác sống ghi nhớ họ."
  },
  AvgDialog_89088_Content_103 = {
    Text = "Cảm ơn bạn...... vua của chúng ta......"
  },
  AvgDialog_89088_Content_104 = {
    Text = "Ánh trăng chiếu sáng linh hồn mỉm cười của cô gái, như ánh sáng chiếu qua một tấm màn tinh khiết.\nNgay giây tiếp theo, màn che trong căn phòng vỡ vụn thành từng điểm sáng, linh hồn bé nhỏ theo gió mà tan biến."
  },
  AvgDialog_89088_Content_105 = {
    Text = "Khói tím mang nỗi buồn mạnh mẽ, từ mắt Dullesain tỏa ra, quấn quanh vị trí mà cô gái biến mất, an ủi và tiễn đưa."
  },
  AvgDialog_89088_Content_106 = {
    Text = "Hắn nhai, nuốt. Những ngón tay dài và sắc bén của hắn sâu vào sàn gỗ, từ từ trượt đi. Mỗi lần nhai, nhiệt độ trong mắt hắn giảm đi một phần."
  },
  AvgDialog_89088_Content_107 = {
    Text = "Báo cáo thánh chủ, vị trí của kẻ trộm mộ đã được tìm thấy..."
  },
  AvgDialog_89088_Content_108 = {Text = "Pa——"},
  AvgDialog_89088_Content_109 = {
    Text = "Mảnh gỗ cuối cùng không chịu nổi cơn giận của Vua Thịt Sống, đột ngột bị gãy trong những vết sẹo ghê rợn."
  },
  AvgDialog_89088_Content_11 = {
    Text = "Quân thần của tôi, người thân của tôi, xin đừng vội vàng đến với vùng đất của những người đã khuất."
  },
  AvgDialog_89088_Content_110 = {
    Text = "Bữa ăn dài dằng dặc đã kết thúc. Dullesain nhẹ nhàng lau đi máu trên khóe miệng, ngẩng cao đôi mắt lạnh giá như băng, im lặng bước ra cửa."
  },
  AvgDialog_89088_Content_12 = {
    Text = "Nhân danh vua xác sống, dưới ánh sáng thuần khiết của mặt trăng, tôi gọi bạn, gọi bạn trở về."
  },
  AvgDialog_89088_Content_13 = {
    Text = "Vui lòng cho tôi biết, tất cả những điều bạn muốn nói với tôi…"
  },
  AvgDialog_89088_Content_14 = {
    Text = "Ánh sáng xung quanh dần tối lại. Ánh trăng như hội tụ trên tay Dulcain, qua đầu ngón tay của hắn, rót vào thân thể cô gái nhỏ."
  },
  AvgDialog_89088_Content_15 = {
    Text = "Rất nhanh, một thực thể từ ánh trăng hội tụ nhẹ nhàng bay lên từ cơ thể cô bé, chồng lên thể xác."
  },
  AvgDialog_89088_Content_16 = {
    Text = "Cô ấy nhìn cơ thể đã chết của mình, ngôi nhà lộn xộn, và những chiếc đầu rải rác trên đất mà không thể tin nổi."
  },
  AvgDialog_89088_Content_17 = {
    Text = "Tôi... đã chết?..."
  },
  AvgDialog_89088_Content_18 = {
    Text = "Bố… Mẹ… Thật xin lỗi…"
  },
  AvgDialog_89088_Content_19 = {
    Text = "Không sao đâu, con à. Tất cả những gì con phải chịu đựng sẽ có người trả lại cho con."
  },
  AvgDialog_89088_Content_2 = {
    Text = "Không có Bạc..."
  },
  AvgDialog_89088_Content_20 = {
    Text = "Cô bé ngước đôi mắt buồn nhìn về phía người đàn ông trước mặt."
  },
  AvgDialog_89088_Content_21 = {
    Text = "Mẹ nói, vua Dulsain của chúng ta có thể nói chuyện với những người đã chết..."
  },
  AvgDialog_89088_Content_22 = {
    Text = "Bạn... có phải là vua của chúng ta không?"
  },
  AvgDialog_89088_Content_23 = {
    Text = "Đúng vậy. Tôi là chủ nhân của thành phố chôn xác. Bạn bè của các bạn..."
  },
  AvgDialog_89088_Content_24 = {
    Text = "Vui lòng cho tôi biết chuyện gì đã xảy ra?"
  },
  AvgDialog_89088_Content_25 = {
    Text = "Bố mẹ đã nói, trong lễ hội thờ cúng linh hồn, tôi phải ăn họ, để sống thay cho họ…"
  },
  AvgDialog_89088_Content_26 = {
    Text = "Tôi đã làm sạch chúng, đặt lên bàn ăn, rồi... một người đã xâm nhập vào nhà tôi..."
  },
  AvgDialog_89088_Content_27 = {
    Text = "Một người như thế nào?"
  },
  AvgDialog_89088_Content_28 = {
    Text = "Một... họa sĩ..."
  },
  AvgDialog_89088_Content_29 = {
    Text = "Ánh trăng thoát ra từ đầu cô, tạo thành một bóng mờ mơ hồ trong không khí, rồi tan biến. Dullesin nhìn vào hình bóng đó, hơi thở trở nên nặng nề."
  },
  AvgDialog_89088_Content_3 = {
    Text = "Những xác chết này đã bị ai đó đánh cắp bạc, vì vậy chúng đã biến thành quái vật biến dạng?"
  },
  AvgDialog_89088_Content_30 = {
    Text = "Nhưng hắn vẫn duy trì giọng nói ôn hòa, dường như sợ rằng nếu âm thanh quá lớn, sẽ làm kinh động đến linh hồn của cô bé ăn xác chết."
  },
  AvgDialog_89088_Content_31 = {
    Text = "Ông đến đây để làm gì?"
  },
  AvgDialog_89088_Content_32 = {
    Text = "Anh ta nói, hãy giao cơ thể của cha mẹ tôi cho anh ta..."
  },
  AvgDialog_89088_Content_33 = {
    Text = "Đó là điều mà bố mẹ đã để lại cho tôi... Tôi không thể cho anh ấy..."
  },
  AvgDialog_89088_Content_34 = {
    Text = "Rồi sao nữa?"
  },
  AvgDialog_89088_Content_35 = {
    Text = "Anh ta nói không thể để ai biết đã có người đến đây... Anh ta đã cho tôi xem một bức tranh..."
  },
  AvgDialog_89088_Content_36 = {
    Text = "Nhìn bức tranh đó, tôi đã ngủ thiếp đi… khi tôi thức dậy lần nữa, thì… thấy các bạn…"
  },
  AvgDialog_89088_Content_37 = {
    Text = "Cô ấy quay đầu, nhìn vào đầu của cha mẹ, giọng nói ngây thơ run rẩy nhẹ nhàng cùng với linh hồn gầy yếu."
  },
  AvgDialog_89088_Content_38 = {
    Text = "Bạc của bố mẹ đã biến mất… Tôi không bảo vệ được họ… Đây là mong ước cuối cùng của họ, tôi đã không…"
  },
  AvgDialog_89088_Content_39 = {
    Text = "Cướp bóc vào nhà dân, không phải lỗi của người dân. Nạn nhân vô tội, không cần tự trách."
  },
  AvgDialog_89088_Content_4 = {
    Text = "Dullesain không đáp, lưng tay đưa ra phía trước. Đến bên ngoài căn nhà trong vùng đất hoang này."
  },
  AvgDialog_89088_Content_40 = {
    Text = "Nhưng, ước muốn của cha mẹ…"
  },
  AvgDialog_89088_Content_41 = {
    Text = "Nguyện vọng của họ, tôi sẽ hoàn thành cho họ."
  },
  AvgDialog_89088_Content_42 = {
    Text = "Bạn? Nhưng bạn là vua của thành phố Thiên táng..."
  },
  AvgDialog_89088_Content_43 = {
    Text = "Chính vì tôi là chủ nhân của Thành phố Táng Xác, các bạn sống ở đây nhưng lại bị bọn cướp hãm hại. Đây là lỗi của tôi, phải do tôi giải quyết."
  },
  AvgDialog_89088_Content_44 = {
    Text = "Bạn có điều gì mong ước không? Xin hãy cho tôi biết."
  },
  AvgDialog_89088_Content_45 = {
    Text = "Tôi……tôi muốn cầu xin bạn……hãy ăn tôi, cùng cả cha mẹ của tôi……"
  },
  AvgDialog_89088_Content_46 = {
    Text = "Cô gái nhỏ ngẩng đầu nhìn Dullesain."
  },
  AvgDialog_89088_Content_47 = {
    Text = "Bố mẹ đã chết rồi. Tất cả người thân, đều đã chết… Họ để lại ký ức cho tôi. Nhưng, tôi cũng đã chết."
  },
  AvgDialog_89088_Content_48 = {
    Text = "Thưa Đỗ Lê Sa Yên, ngài là chủ nhân của thành phố Táng Tích…… có thể nhờ ngài, giúp chúng tôi lấy lại Bạc, để chúng tôi giữ lại ký ức này không?"
  },
  AvgDialog_89088_Content_5 = {
    Text = "Thánh chủ, đây chính là……"
  },
  AvgDialog_89088_Content_50 = {
    Text = "Ánh trăng. Nỗi đau. Cuộc sống trôi qua. Lời cầu khẩn mong manh."
  },
  AvgDialog_89088_Content_51 = {
    Text = "Mọi thứ quen thuộc lại tái hiện trước mắt, như ngày cô chia tay anh."
  },
  AvgDialog_89088_Content_52 = {Text = "Selene!!"},
  AvgDialog_89088_Content_53 = {
    Text = "Anh trai... bạn... đã trở về rồi..."
  },
  AvgDialog_89088_Content_54 = {
    Text = "Ông chạy vội đến bên giường bệnh. Cô gái lúc đó linh hoạt như sơn ca, nay chỉ còn lại thân hình và gương mặt héo mòn."
  },
  AvgDialog_89088_Content_55 = {
    Text = "Cha tôi…"
  },
  AvgDialog_89088_Content_56 = {
    Text = "Phân rã đã mang đi hắn, cách đây một tháng... thân thể của hắn đã không còn, ký ức hắn để lại cũng bắt đầu phai nhạt trong phân rã..."
  },
  AvgDialog_89088_Content_57 = {
    Text = "Bạn vừa mới trở thành vua của thành phố này, bạn còn nhiều việc phải làm. Cha ơi, không muốn quấy rầy bạn, cũng…… không mong bạn xử lý xác chết của ông……"
  },
  AvgDialog_89088_Content_58 = {
    Text = "Đừng nghĩ về những điều này nữa, Selene. Sự phân rã trên người bạn đã đến mức nào rồi? Tôi biết một bác sĩ rất có tiếng, có lẽ ông ấy có thể..."
  },
  AvgDialog_89088_Content_59 = {
    Text = "Bạn vẫn như lúc nhỏ, mỗi khi nói dối, đều nhìn về phía ánh trăng ở bên ngoài, anh trai."
  },
  AvgDialog_89088_Content_6 = {
    Text = "Đỗ Lê Sa Yên đưa tay lên, ngăn cản anh ta, đi vào trong nhà."
  },
  AvgDialog_89088_Content_60 = {
    Text = "Selene......"
  },
  AvgDialog_89088_Content_61 = {
    Text = "Adam vì đau buồn mà cổ họng căng lên. Dullesai nắm chặt cánh tay đầy lỗ hổng đen của em gái."
  },
  AvgDialog_89088_Content_62 = {
    Text = "Anh trai, có một chuyện, tôi muốn nhờ bạn..."
  },
  AvgDialog_89088_Content_63 = {
    Text = "Có chuyện gì, hãy nói cho tôi biết. Tôi nhất định sẽ làm được!"
  },
  AvgDialog_89088_Content_64 = {
    Text = "Sau khi tôi chết, bạn có thể... ăn thịt tôi không?"
  },
  AvgDialog_89088_Content_65 = {
    Text = "Thời gian trên người Du Lệ Sai Y dường như ngừng lại. Hắn trợn mắt nhìn, không thể tin vào mắt mình khi nhìn thấy em gái mình."
  },
  AvgDialog_89088_Content_66 = {
    Text = "Bạn…… bạn nói gì?"
  },
  AvgDialog_89088_Content_67 = {
    Text = "Bạn luôn muốn làm như vậy, phải không? Lúc còn nhỏ bạn đã nói với tôi muốn thử hương vị của huyết thống, nói rằng nó chắc chắn ngon hơn bất kỳ thứ gì bạn đã ăn. Của cha, của mẹ, của tôi..."
  },
  AvgDialog_89088_Content_68 = {
    Text = "Nhưng bạn không có điều đó, anh trai. Dù bị cha đầu độc và tái sinh có được cuộc sống và quyền lực bất tử, bạn cũng không làm vậy..."
  },
  AvgDialog_89088_Content_69 = {
    Text = "Selene...... nhưng...... bạn chưa thực sự chấp nhận điều này...... tại sao phải......"
  },
  AvgDialog_89088_Content_7 = {
    Text = "Trong ngôi nhà cũ kỹ, bàn ghế vỡ vụn nằm rải rác khắp nơi, hai cái đĩa cũ nát rơi vỡ trên mặt đất. Một cặp vợ chồng ăn xác bị phân rã, đầu họ từ đĩa lăn xuống."
  },
  AvgDialog_89088_Content_70 = {
    Text = "Vào sinh nhật 5 tuổi của tôi, bạn lần đầu tiên đưa tôi lén lút đi ra nghĩa trang, đào những ngôi mộ. Bạn nói với tôi rằng bạn không phải phạm tội, mà đang thực hiện một thẩm mỹ mà người khác không thể hiểu."
  },
  AvgDialog_89088_Content_71 = {
    Text = "Bạn muốn tìm một xác chết hoàn hảo để tặng cho tôi… Tôi sợ đến nỗi không dám nhìn bạn, nhưng vẫn nghe lời bạn, nhìn về hướng gió."
  },
  AvgDialog_89088_Content_72 = {
    Text = "Như cha, như tất cả mọi người khác, tôi chỉ là một người bình thường… tôi không thể hiểu những điều vượt ra ngoài nhận thức của mình, không thể hiểu những lời nói về ẩm thực của bạn."
  },
  AvgDialog_89088_Content_73 = {
    Text = "Nhưng tôi tin tưởng bạn, anh trai."
  },
  AvgDialog_89088_Content_74 = {
    Text = "Giọng Selene hơi run rẩy. Cô nắm chặt tay Duleqain."
  },
  AvgDialog_89088_Content_75 = {
    Text = "Tôi không muốn chết, huynh trưởng……tôi không muốn chết một cách vô nghĩa, không có dấu vết gì……"
  },
  AvgDialog_89088_Content_76 = {
    Text = "Phân rã sẽ mang đi mọi thứ. Nhưng nếu bạn có thể nuốt chửng tôi... thì có lẽ hương vị đó sẽ là ký ức mà phân rã cũng không thể xóa nhòa?"
  },
  AvgDialog_89088_Content_77 = {
    Text = "Selene mỉm cười nhìn Duleqain, vỗ về mu bàn tay của Duleqain một cách an ủi."
  },
  AvgDialog_89088_Content_78 = {
    Text = "Cha tôi đã nói với tôi, bạn là một kẻ dị thường, là một kẻ hủy hoại của gia đình… Từ nhỏ đến lớn, bạn luôn là người tốt nhất với tôi, nhưng tôi càng ngày càng không dám lại gần bạn…"
  },
  AvgDialog_89088_Content_79 = {
    Text = "Trong những năm qua, bạn đã rất cô đơn, phải không, anh trai?"
  },
  AvgDialog_89088_Content_8 = {
    Text = "Giữa những vật phẩm lộn xộn này, một cô gái xác sống mặc áo rách nát nằm trong vũng máu, đã không còn thở nữa."
  },
  AvgDialog_89088_Content_80 = {
    Text = "Ông là vua cai trị mảnh đất này. Ông đã từng đối diện với các thần linh cao ngất và những kẻ thù tàn bạo, nhưng giờ đây, ông phát hiện ra mình không có can đảm để nhìn thẳng vào đôi mắt của em gái mình."
  },
  AvgDialog_89088_Content_81 = {
    Text = "Xin lỗi... Lẽ ra, tôi nên là người hiểu bạn nhất..."
  },
  AvgDialog_89088_Content_82 = {
    Text = "Trước đây tôi đã không thể làm được, bây giờ, cuối cùng tôi đã có cơ hội này."
  },
  AvgDialog_89088_Content_83 = {
    Text = "Selene ngẩng đầu, nhìn Duleqain một cách nghiêm túc. Một giọt nước mắt lăn xuống từ đôi mắt mỉm cười của cô, như giọt sương cuối cùng trước ánh sáng bình minh."
  },
  AvgDialog_89088_Content_84 = {
    Text = "Du Lệ Sai Y, vua của thành bang... Tôi cầu xin ngài, hãy ăn thịt tôi. Tôi cầu xin ngài, mang theo ký ức của tôi, mang theo linh hồn của tôi, sống chung với nhau."
  },
  AvgDialog_89088_Content_85 = {
    Text = "Khi tôi còn sống, tôi không thể ở bên cạnh bạn. Sau khi tôi ra đi, tôi cầu xin bạn, anh trai... xin hãy để tôi luôn ở trong ký ức của bạn nhé."
  },
  AvgDialog_89088_Content_87 = {
    Text = "Một ký ức của một người thân. Một câu chuyện của một hoàng tộc thành phố. Một đoạn lịch sử nặng nề tráng lệ."
  },
  AvgDialog_89088_Content_88 = {
    Text = "Một ký ức của một người bình dân. Một câu chuyện của một gia đình bình thường. Một chú thích có thể có hoặc không."
  },
  AvgDialog_89088_Content_89 = {
    Text = "Đối với nhà vua của thành phố hỏa táng, chúng không nên và cũng sẽ không có bất kỳ sự khác biệt nào."
  },
  AvgDialog_89088_Content_9 = {
    Text = "Thời gian chết của cô ấy là cách đây hai giờ. Chúng tôi đã kiểm tra, trong ba xác chết này, không có viên bạc nào."
  },
  AvgDialog_89088_Content_90 = {
    Text = "Đỗ Lê Sa Yên thu lại vẻ mặt không tôn kính của mình, vuốt tóc cô bé, solemnly gật đầu về phía cô."
  },
  AvgDialog_89088_Content_91 = {
    Text = "Tôi hứa với bạn rằng...... tôi sẽ lấy lại Bạc của các bạn. Tôi sẽ giúp các bạn giữ gìn những Ký ức đó, cho đến ngày linh hồn tôi tiêu vong."
  },
  AvgDialog_89088_Content_92 = {
    Text = "Cô gái nhỏ mỉm cười rạng rỡ. Xác của cô nằm trong lòng Dullesain, máu đang gần cạn tràn đầy cơ thể anh."
  },
  AvgDialog_89088_Content_93 = {
    Text = "Đừng lo lắng, đứa trẻ… tôi sẽ nhẹ nhàng, rất nhẹ nhàng…"
  },
  AvgDialog_89088_Content_94 = {
    Text = "Dullesain hít một hơi thật sâu, nghiêm trang cúi đầu, cắn vào cổ của cô bé."
  },
  AvgDialog_89088_Content_95 = {
    Text = "Có lẽ vì sợ hãi những chiếc răng sắc nhọn, hoặc có lẽ vì sự mơ hồ sẽ biến mất, linh hồn của cô ấy đã run rẩy nhẹ, giống như ngày Selene chết."
  },
  AvgDialog_89088_Content_96 = {
    Text = "Du Lệ Sai Y nhẹ nhàng vuốt ve đầu cô. Dưới sự vuốt ve dịu dàng đó, linh hồn của cô trở nên bình tĩnh, lặng lẽ nhìn Du Lệ Sai Y, cũng nhìn về phía chính mình."
  },
  AvgDialog_89088_Content_97 = {
    Text = "Linh hồn bất lực, hãy nhìn lần cuối… Tất cả những gì bạn trân quý sẽ tồn tại dưới ánh trăng…"
  },
  AvgDialog_89088_Content_98 = {
    Text = "Nhân danh ánh trăng, nhân danh thành phố Mausoleum, tôi sẽ tặng cho bạn sự ghi nhớ, tôi sẽ tặng cho bạn sự kết thúc..."
  },
  AvgDialog_89088_Content_99 = {
    Text = "Răng nhọn đâm vào da thịt, tách rời xương thịt. Một miếng thịt bị anh ta cắn đi, nhai, nuốt chửng."
  },
  AvgDialog_89089_Content_1 = {
    Text = "Ngay bên kia!"
  },
  AvgDialog_89089_Content_10 = {
    Text = "Ông tiến lại gần bạn một cách bình thản, bao quanh bạn và quay vòng. Đôi mắt tím đánh giá bạn, lỗ mũi phập phồng, hít sâu mùi hương tỏa ra từ người bạn."
  },
  AvgDialog_89089_Content_11 = {
    Text = "Cái cổ thật duyên dáng, hơi thở thật thơm ngon... Nếu chỉ nhẹ nhàng cắn một cái thì tiếng kêu thống khổ và cảm giác tinh tế sẽ như thế nào, thật là thú vị..."
  },
  AvgDialog_89089_Content_12 = {
    Text = "Bạn cảnh giác lùi lại, chìa khóa bạc trong tay phát ra ánh sáng lấp lánh. Dulehsain mỉm cười, không tiếp tục gần lại bạn nữa."
  },
  AvgDialog_89089_Content_13 = {
    Text = "Vừa nãy ngửi thấy mùi của bạn trong bếp, cảm thấy rất, rất quen thuộc. Bộ đồ này của bạn thì không dễ gặp."
  },
  AvgDialog_89089_Content_14 = {
    Text = "Có vẻ như, ngài và vị khách chính đêm nay, nhất định có nhiều mối quan hệ. Không bằng cứ ở lại, yến tiệc đêm nay sắp bắt đầu, tôi nghĩ, ở đây chắc chắn sẽ có nhiều thứ mà ngài quan tâm."
  },
  AvgDialog_89089_Content_15 = {
    Text = "Về xác chết đó, tôi chắc chắn sẽ điều tra rõ ràng… nhưng không phải bây giờ. Xin lỗi đã làm phiền."
  },
  AvgDialog_89089_Content_16 = {
    Text = "Khi Durlesain lên tiếng, bạn đã gắng hết sức tập trung sức mạnh linh hồn của mình vào chiếc chìa khóa bạc, những người đánh thức trong ý thức của bạn đã sẵn sàng."
  },
  AvgDialog_89089_Content_17 = {
    Text = "Bạn đã từng nhìn thẳng vào Toho Wabo, bạn rất thành thạo với sức mạnh của người đánh thức. Bạn tự tin rằng ngay cả người đàn ông đứng trước mình, người có sức mạnh điều khiển toàn bộ thành phố, bạn cũng có thể lao ra với một đòn tấn công."
  },
  AvgDialog_89089_Content_18 = {
    Text = "Hửm—điều này... đây là..."
  },
  AvgDialog_89089_Content_19 = {
    Text = "Chưa kịp để bạn cầm chìa khóa bạc, một cơn buồn ngủ mãnh liệt tràn lên trong đầu bạn. Bạn quay đầu lại. Không biết từ khi nào, một làn sương mù bao trùm quanh bạn, như những con chó săn đói khát đã cắn nuốt tất cả sức lực của bạn."
  },
  AvgDialog_89089_Content_2 = {
    Text = "Điểm yếu của vòng phòng thủ đã bị phá vỡ, những người lính bảo vệ xung quanh vẫn chưa đến nơi. Bạn vượt qua những người lính bị đánh gục, lao về phía cánh cửa bên của tòa lâu đài."
  },
  AvgDialog_89089_Content_20 = {
    Text = "Sự chú ý của bạn hoàn toàn tập trung vào Dullesain trước mặt, người quản gia già mà bạn đã bỏ qua, đó là sai lầm chết người của bạn."
  },
  AvgDialog_89089_Content_21 = {
    Text = "Bạn không còn sức lực nữa, nhắm mắt lại và ngã xuống."
  },
  AvgDialog_89089_Content_22 = {
    Text = "Ái chao, tôi đã nói với bạn bao nhiêu lần rồi, ông Fran, đừng đối xử với khách của chúng ta kiểu thô bạo như vậy. Đổ xuống đất như vậy, sẽ làm hư hại đến thịt rất nhiều."
  },
  AvgDialog_89089_Content_23 = {
    Text = "Đưa {Male=anh ấy,Female=cô ấy} đi nghỉ ngơi nhé. Cẩn thận, đừng để {Male=anh ấy,Female=cô ấy} bị thương. Một chỗ cũng không được."
  },
  AvgDialog_89089_Content_24 = {
    Text = "Vâng, thưa ngài."
  },
  AvgDialog_89089_Content_25 = {
    Text = "Du Lệ Sai Y tiến lại gần bạn, hít một hơi thật sâu, nhắm mắt lại với vẻ hài lòng."
  },
  AvgDialog_89089_Content_26 = {
    Text = "Ah... tôi chưa bao giờ ngửi thấy một mùi hương trong trẻo và tuyệt vời như vậy trên thế gian này, bạn thật là bất ngờ. Xin hãy yên tâm, vị {Male=ngài,Female=cô} này..."
  },
  AvgDialog_89089_Content_27 = {
    Text = "Du Lệ Sai Y nhẹ nhàng tách tay bạn ra, dùng ngón cái và ngón giữa nhặt lên chìa khóa bạc của bạn, mê mẩn ngắm nhìn."
  },
  AvgDialog_89089_Content_28 = {
    Text = "Tại bữa tiệc tối nay, bạn chắc chắn sẽ là \"khách\" quý giá nhất của tôi."
  },
  AvgDialog_89089_Content_3 = {
    Text = "Sao bạn có thể đối xử thô bạo với khách của chúng ta như vậy, ông Fran?"
  },
  AvgDialog_89089_Content_4 = {
    Text = "Một làn sương lạnh bỗng xuất hiện, Dullesai không biết tự lúc nào đã có mặt tại cổng, chắn đường đi của bạn. Anh ta lắc lắc ngón tay, khiến những xác sống muốn tiến lên thu lại vũ khí."
  },
  AvgDialog_89089_Content_5 = {
    Text = "Ánh mắt vây quanh bởi sương mù tím đang đánh giá bạn, như một đầu bếp đang cân nhắc nguyên liệu của mình."
  },
  AvgDialog_89089_Content_6 = {
    Text = "Thành phố di hài nổi tiếng với lối sống hiếu khách, không thể thiếu lịch sự với khách."
  },
  AvgDialog_89089_Content_7 = {
    Text = "Thế à, vậy bây giờ tôi muốn rời đi, bạn sẽ cho tôi đi?"
  },
  AvgDialog_89089_Content_8 = {
    Text = "Đây là lời gì vậy. Bạn là khách, đến và đi dĩ nhiên là tự do của khách."
  },
  AvgDialog_89089_Content_9 = {
    Text = "Nhưng mà… khách đến lâu đài của tôi, chắc hẳn có việc gì cần làm. Bây giờ chưa hoàn thành công việc đã phải ra về, điều này không đúng với cách tiếp đãi của chúng tôi."
  },
  AvgDialog_89874_Content_1 = {
    Text = "Bạn theo Sanga đến một ngôi nhà, thấy hình bóng quen thuộc. \n Rõ ràng, bạn lại gặp một người bạn cũ."
  },
  AvgDialog_89874_Content_10 = {
    Text = "Nhưng, người giữ gìn, bạn biết quy tắc. Tôi đã tặng một \"quà tặng\" miễn phí một lần rồi."
  },
  AvgDialog_89874_Content_11 = {
    Text = "Tất nhiên. \"Giá cả hợp lý, không lừa đảo người già và trẻ nhỏ.\""
  },
  AvgDialog_89874_Content_12 = {
    Text = "Đúng vậy, vì vậy, lần này \"giá\" cũng rất đơn giản. Tôi chỉ cần—"
  },
  AvgDialog_89874_Content_13 = {
    Text = "Trong trạng thái hôn mê của linh hồn, bạn đã thấy sự kinh hoàng đang cuồn cuộn phía sau Hoa thuỷ tiên."
