  },
  AvgDialog_89874_Content_19 = {
    Text = "<Yellow:Một tổ chức nào đó vì mục đích ác độc đã hy sinh Saelephys>，mà bạn không biết họ là ai, thậm chí không biết họ có bao nhiêu người - bạn hoàn toàn không biết gì."
