  AvgDialog_89874_Content_9 = {
    Text = "Hừm, điều này đơn giản hơn rất nhiều so với những yêu cầu khó chịu trước đây của bạn."
  },
  AvgDialog_89875_Content_1 = {
    Text = "Dù Salvador đã cố gắng hết sức, nhưng chất nhờn đen cứ tiếp tục lan rộng, hoàn toàn nuốt chửng con lừa đó."
  },
  AvgDialog_89875_Content_10 = {
    Text = "Theo nghiên cứu của tôi, một nơi không thể tự dưng xảy ra hiện tượng <Yellow: bất thường về linh hồn> như vậy."
