  AvgDialog_89875_Content_13 = {
    Text = "Vài ngày trước, tôi nhận được cuộc cầu cứu của Quỹ, đến đây để điều tra."
  },
  AvgDialog_89875_Content_14 = {
    Text = "Khi đó, vẫn còn hai người sống sót. Tôi thấy tận mắt... họ chịu đựng đau khổ, biến thành quái vật, nhưng không thể làm gì."
