  AvgDialog_90537_Content_16 = {
    Text = "Tôi sẽ không hối hận."
  },
  AvgDialog_90537_Content_17 = {
    Text = "Castor lẩm bẩm quỳ xuống, cảm thấy cơ thể đang từ từ hòa tan dưới tác dụng của nghi thức thắp đèn."
  },
  AvgDialog_90537_Content_18 = {
    Text = "Lúc này, trong cơ thể anh ấy xuất hiện một cơn xoáy, đang nhanh chóng nuốt chửng cuộc sống của anh ấy, dẫn anh đến kết thúc tàn lụi."
  },
  AvgDialog_90537_Content_19 = {
    Text = "Không biết vì sao, đoạn cành đó không xuyên qua bụng của anh mà mọc lên, chỉ đang đơn thuần nuốt chửng, khiến từng chút lông vũ, biên giới da thịt của anh trở nên kỳ quái mờ ảo."
  },
  AvgDialog_90537_Content_2 = {
    Text = "Đã nghĩ xong cách ứng phó với người phụ nữ khó khăn đó chưa, cô chim nhỏ, nếu các bạn thất bại, tôi e rằng sẽ không còn sức mạnh dư thừa để cứu bạn."
  },
  AvgDialog_90537_Content_20 = {
    Text = "Lần này anh ấy hoàn toàn mở lòng, không còn kiềm chế nỗi đau, anh muốn dùng sự giải thoát này để đổi lấy tự do cho em trai mình."
  },
  AvgDialog_90537_Content_21 = {Text = "!!!"},
  AvgDialog_90537_Content_22 = {
    Text = "Không xa đó, Juliette phát hiện ra sự kỳ lạ của Castor, bóng hình của cô vừa động, liền bị một nhành cây xuất hiện một cách đột ngột chặn lại."
  },
  AvgDialog_90537_Content_23 = {
    Text = "Cái cây nhỏ vốn đã chết ấy bỗng nhiên hồi sinh trở lại, và Thais đang ngủ say cũng mở mắt và mỉm cười nhìn cô."
  },
  AvgDialog_90537_Content_24 = {
    Text = "Bạn có muốn đi qua không? Nhưng không dễ dàng đâu, đối thủ của bạn là tôi."
