  },
  AvgDialog_90537_Content_3 = {
    Text = "Vậy, tôi sẽ không thất bại, tôi sẽ không cho phép kết thúc như vậy xảy ra lần nữa...... Tôi muốn yêu cầu bạn, cho tôi một cách chắc chắn để tôi có thể chết."
  },
  AvgDialog_90537_Content_30 = {
