  },
  AvgDialog_90537_Content_44 = {
    Text = "Thân thể ông bỗng nhiên sụp đổ như cát, biến thành những điểm ánh sáng lấp lánh, phiêu đãng trong không trung."
  },
  AvgDialog_90537_Content_45 = {
    Text = "Trong nước mắt mờ mịt của tầm nhìn, Pollux tuyệt vọng nắm chặt, ôm lấy những điểm sáng đó, cảm thấy có một điều gì đó quan trọng nhất trong cuộc sống đã biến mất trong khoảnh khắc đó."
