  AvgDialog_90537_Content_46 = {
    Text = "Vòng tròn ma thuật trên mặt đất ngày càng sáng hơn vẫn đang vận hành một cách vô ích, chỉ hòa quyện những ánh sáng phát quang vào cơ thể của Polyxus."
  },
  AvgDialog_90537_Content_47 = {Text = "……!!!"},
  AvgDialog_90537_Content_48 = {
    Text = "Ký ức dâng lên như sóng cuộn tràn ngập Polyxus, như thể cánh cửa định mệnh đột nhiên mở ra, hai linh hồn xuất phát từ một thể gặp lại nhau."
  },
  AvgDialog_90537_Content_49 = {
    Text = "Cuộc sống suốt ngày chỉ tay chỉ trỏ ấy như bong bóng giả dối lùi lại, tan biến."
  },
  AvgDialog_90537_Content_5 = {
    Text = "Đúng vậy, tôi tin rằng bạn nhất định có sức mạnh như vậy, bất kể Juliette muốn lợi dụng Thánh Tử để làm gì, cô ấy chắc chắn cần hai Thánh Tử cùng tồn tại."
