  AvgDialog_90537_Content_57 = {
    Text = "Sau khi bị tách ra, Polux không chịu đựng cùng một hình phạt tàn nhẫn, sau khi vết thương ở cánh lành lại, anh bắt đầu học thần học về chiếc đèn dưới sự chỉ dẫn của Juliette."
  },
  AvgDialog_90537_Content_58 = {
    Text = "Lần nữa mơ thấy Castor, Pollux bất ngờ tỉnh dậy giữa đêm khuya."
  },
  AvgDialog_90537_Content_59 = {
    Text = "Hả... Đáng ghét, đầu tôi đau quá... cái gì mà thể ngộ kinh văn, người phụ nữ đó chắc chắn đã làm gì đó với tôi, hình ảnh người anh trai trong đầu, tại sao lại mờ nhạt đi..."
