  },
  AvgDialog_90538_Content_100 = {
    Text = "Như thể quay trở lại cảnh tượng lúc vừa mới ra đời, một hình bóng mới sinh co lại, từ đằng sau Polydeuces từ từ hình thành và thoát ra, hoàn thành một vòng đời lần nữa."
  },
  AvgDialog_90538_Content_101 = {
    Text = "Đôi cánh hư ảo đó cũng theo sự rời khỏi của linh hồn đó mà thoát khỏi cơ thể Polycus, trở về với chủ nhân thật sự của nó."
