  AvgDialog_90538_Content_105 = {
    Text = "Castor nhìn xung quanh trong tâm trí rối loạn, cố gắng làm rõ những bí ẩn của sự sống và cái chết, trên mặt anh hòa trộn giữa hoang mang, vui mừng, lo lắng, chỉ có điều không có chút oán hận nào."
