  AvgDialog_90538_Content_106 = {
    Text = "Trong nụ cười không thể nhịn được của Pollux, Castor cũng bất ngờ lộ ra một nụ cười đoàn tụ."
  },
  AvgDialog_90538_Content_107 = {
    Text = "Trên bầu trời xa xăm sáng sủa, một bầy chim trắng hót vang bay qua, trên mảnh đất bao la, hai linh hồn lâu ngày gặp lại nhìn nhau."
  },
  AvgDialog_90538_Content_108 = {
    Text = "Họ là anh em, là đôi chim sinh đôi, là những người bạn duy nhất, là tù nhân cùng bị định mệnh xét xử."
