  AvgDialog_90538_Content_109 = {
    Text = "Ít nhất lần này, sẽ không có gì có thể khiến họ xa cách."
  },
  AvgDialog_90538_Content_11 = {
    Text = "Như thể đã mất đi nguyên liệu quan trọng nhất, mặt đất đầy rẫy những chú văn mang máu đã mờ đi, áp lực khiến mọi thứ ngưng đọng trong không khí cũng đột nhiên giãn ra."
  },
  AvgDialog_90538_Content_12 = {
    Text = "Các tín đồ đang thì thào bối rối nhìn quanh, những người bảo vệ ngọn đèn đi cùng Juliette để chiến đấu với Thais cũng lo lắng nhìn về phía giáo chủ của họ."
  },
  AvgDialog_90538_Content_13 = {
    Text = "Kiểm soát hắn, khởi động lại nghi thức!"
  },
  AvgDialog_90538_Content_14 = {
    Text = "Juliette với gương mặt âm u, bên cạnh đàn chó khổng lồ càng điên cuồng xé, né tránh, liên tục va chạm với bóng dáng của những cành cây đang xoay chuyển."
  },
  AvgDialog_90538_Content_15 = {
    Text = "Một đám côn trùng bảo vệ như châu chấu lao tới, tiêu hao sức mạnh đã yếu ớt của Thais, nhiều tín đồ hơn đã tiến gần tới trung tâm nghi thức, giơ cao những chiếc đèn chao đảo."
  },
  AvgDialog_90538_Content_16 = {
    Text = "Nguyện bạn chú ý, nguyện bạn thương xót……"
  },
  AvgDialog_90538_Content_17 = {
    Text = "Một ánh sáng từ những lời chú thuật nổi lên, những cơn đau như sự trừng phạt đã từng khắc sâu nỗi sợ hãi vào xương thịt của cặp song sinh."
  },
  AvgDialog_90538_Content_18 = {
    Text = "Đừng mở miệng... các bạn là những con sâu bẩn thỉu..."
  },
  AvgDialog_90538_Content_19 = {
    Text = "Bolyx đứng yên ở giữa vòng tròn ma thuật, yên lặng nhắm mắt, chỉ có trái tim thánh ở ngực phát ra ánh sáng rực rỡ hơn."
  },
  AvgDialog_90538_Content_2 = {
    Text = "Một điệp khúc ký ức trong tâm trí của Polux hồi tưởng lại, anh ấy ngồi gục trên đất, khóc nức nở nhìn vào vòng tay trống rỗng."
  },
  AvgDialog_90538_Content_20 = {
    Text = "Ông cất giữ cẩn thận chiếc lông vũ, rồi ngẩng đầu nhìn những người từng tôn kính ông, giờ đây lại nhốt ông trong cũi."
  },
  AvgDialog_90538_Content_21 = {
    Text = "Cho tôi…<Shake:<Big:Biến đi!!>>"
  },
  AvgDialog_90538_Content_22 = {
    Text = "Tất cả cảm xúc phức tạp khó nói này trong lúc này trở thành thù hận và cơn giận dữ ngập trời, một ánh sáng chói lòa từ trái tim thánh trembled вибух ra."
  },
  AvgDialog_90538_Content_23 = {
    Text = "Bầu trời mờ tối bỗng chốc sáng lên thành một bạch đêm, phước lành vốn dịu dàng giờ đây như lời cầu nguyện của giáo đồ, hoàn toàn thanh tẩy tội lỗi của mọi người."
  },
  AvgDialog_90538_Content_24 = {
    Text = "Những vết thương phân rã ẩn dưới chiếc áo choàng bỗng nở rộng, hoại tử, bốc hơi thành sương mù đen, những bóng hình không kịp kêu gào đã ngã xuống."
  },
  AvgDialog_90538_Content_25 = {
    Text = "Boluque đi qua những xác chết biến dạng, anh nhẹ nhàng rút cây gậy vừa mới giữ chặt hắn ra rồi vứt đi."
  },
  AvgDialog_90538_Content_26 = {
    Text = "Trong khoảnh khắc tiếp theo, bàn tay nhợt nhạt đó xuất hiện trước Thais, nhẹ nhàng đặt lên đầu một con chó khổng lồ."
  },
  AvgDialog_90538_Content_27 = {
    Text = "Khi một tiếng thét chuyển tông vang lên, con chó khổng lồ bay ra ngoài, đổ mạnh xuống chân Juliette."
  },
  AvgDialog_90538_Content_28 = {
    Text = "Thais, người gần như đã kiệt sức, nhìn về hai người đối diện, im lặng để chiến trường lại cho những người thực sự cần nó."
  },
  AvgDialog_90538_Content_29 = {
    Text = "A, đứa trẻ ngoan nhất của tôi, đã lâu rồi chưa thấy ánh mắt như thế này của bạn, có phải bạn đang nhớ lại tất cả những gì mình đã làm không?"
  },
  AvgDialog_90538_Content_3 = {
    Text = "Hóa ra, tôi đã quên bạn lâu đến vậy..."
  },
  AvgDialog_90538_Content_30 = {
    Text = "<Big:<Shake:Ngọc, Li, Ai, Tê!!!>>"
  },
  AvgDialog_90538_Content_31 = {
    Text = "Tất cả nỗi đau và khổ cực mà bạn đã áp đặt lên chúng tôi..."
  },
  AvgDialog_90538_Content_32 = {
    Text = "Tôi muốn bạn hôm nay…<Big:<Red:<Shake:Tất cả hãy trả lại!!!>>>"
  },
  AvgDialog_90538_Content_33 = {
    Text = "Cơn thù hận và cơn giận dữ dữ dội đã thổi bùng trái tim thánh, Polux lật tay, một đôi bàn tay khổng lồ đen kịt cuốn theo chất lỏng phân rã mạnh mẽ đập xuống Juliette."
  },
  AvgDialog_90538_Content_34 = {
    Text = "Ái chao, sau nhiều năm được hưởng đặc quyền và vinh dự của thánh nhân, có phải nên đổ mọi lỗi lầm này lên đầu tôi không?"
  },
  AvgDialog_90538_Content_35 = {
    Text = "Biết đâu sau khi quên đi quá khứ, cái lộ ra lại là bản chất thật sự của bạn. Những điều đã làm tổn thương anh trai của bạn, chính là do bạn tự tay làm đấy nhé?"
  },
  AvgDialog_90538_Content_36 = {
    Text = "Bạn nghĩ rằng đến lúc này, tôi vẫn có thể bị bạn mê hoặc sao?"
  },
  AvgDialog_90538_Content_37 = {
    Text = "Juliette, ngươi vẫn như trước, ……kiêu ngạo và ngu ngốc."
  },
  AvgDialog_90538_Content_38 = {
    Text = "Hài, tôi đã luôn bao dung với các bạn, tha thứ cho sự bất kính của các bạn nhiều lần, chăm sóc cho sinh mạng của các bạn đến ngày hôm nay."
  },
  AvgDialog_90538_Content_39 = {
    Text = "Tính mạng? Tính mạng của chúng ta, thậm chí số phận chỉ là công cụ bạn lợi dụng."
  },
  AvgDialog_90538_Content_4 = {
    Text = "Những tổn thương, hiểu lầm, phản bội, hối hận, tội lỗi, đau đớn, mọi lời nói đều không thể truyền đến tai những người thua thiệt nữa."
  },
  AvgDialog_90538_Content_40 = {
    Text = "Những gì bạn đã làm...Trong đó không có linh hồn của những kẻ đã chết vô tội bị chôn vùi sâu?"
  },
  AvgDialog_90538_Content_41 = {
    Text = "Đôi tay bạn sinh ra để\"tẩy rửa thế giới\", nhưng lại bị dính bẩn bởi những tội lỗi bẩn thỉu và không thể rửa sạch trên đời này."
  },
  AvgDialog_90538_Content_42 = {
    Text = "Tôi sẽ đại diện cho tất cả những sinh linh phải gánh chịu bi kịch đau thương vì khát vọng biến dạng của bạn, để bạn ở đây, <Big:<Red:Nợ máu phải trả bằng máu!!!>>"
  },
  AvgDialog_90538_Content_43 = {
    Text = "Sức mạnh của hai người vang dội, hòa tan và máu me tung tóe, sự báo thù thỏa mãn của Polux đã chờ đợi quá lâu."
  },
  AvgDialog_90538_Content_44 = {
    Text = "Cơn giận bất lực thật đáng thương, với thân hình yếu đuối và ngu dốt cố gắng nắm bắt vận mệnh, vốn đã định sẵn là một bi kịch."
  },
  AvgDialog_90538_Content_45 = {
    Text = "Có lẽ phản bội mới là điều bạn giỏi nhất, ban đầu bạn đã phản bội giáo hội, sau đó bạn đã phản bội anh trai của bạn, giờ bạn lại một lần nữa chọn phản bội tôi."
  },
  AvgDialog_90538_Content_46 = {
    Text = "Nhưng đừng quên, năng lực, kiến thức của bạn, đến cả cuộc sống của bạn, tất cả đều là tôi ban cho, bạn lấy gì để phản bội tôi đây?"
  },
  AvgDialog_90538_Content_47 = {
    Text = "Hơn nữa, bạn thật sự nghĩ rằng mình đã đạt được tự do rồi sao?"
  },
  AvgDialog_90538_Content_48 = {
    Text = "Nụ cười trên đôi mắt màu tím của Juliette càng thêm nồng nàn, môi cô khẽ mở, không thành tiếng niệm một câu thần chú nào đó."
  },
  AvgDialog_90538_Content_5 = {
    Text = "Hóa ra những giọt nước mắt chảy ra khi tự tay làm tổn thương đối phương không phải là tiếc thương cho cái chết của thỏ và cáo, mà là những tiếng khóc từ tận đáy lòng."
  },
  AvgDialog_90538_Content_50 = {Text = "Ừ——"},
  AvgDialog_90538_Content_51 = {
    Text = "Một sợi dây buộc chặt bấy lâu nay ẩn mình dưới xương thịt bỗng nổi lên, ác độc siết chặt trái tim nhân tạo kia."
  },
  AvgDialog_90538_Content_52 = {
    Text = "Khi những câu chú tím lấp lánh, ánh sáng rực rỡ như ban ngày đột ngột biến mất, Bolyx nhăn mặt lại đau đớn, quỳ gối xuống."
  },
  AvgDialog_90538_Content_53 = {
    Text = "Yu Li-ét…"
  },
  AvgDialog_90538_Content_54 = {
    Text = "<Shake:Juliette！！！>"
  },
  AvgDialog_90538_Content_55 = {
    Text = "Trong tiếng cười lạnh lẽo không ngoài dự đoán, Polux như đỡ lấy viên đá lớn, thẳng lưng lên, anh rút phần lông màu đen từ trong ngực ra, rồi mạnh tay cắm vào ngực mình."
  },
  AvgDialog_90538_Content_56 = {
    Text = "Dù trả giá bằng bất cứ điều gì, tôi nhất định phải giết bạn... chỉ một trái tim thôi, trả lại cho bạn là được!"
  },
  AvgDialog_90538_Content_57 = {
    Text = "Khi ngón tay của anh ta chạm vào trái tim đen đó, một lực đẩy nhẹ nhàng giữ anh ta lại bên ngoài."
  },
  AvgDialog_90538_Content_58 = {Text = "!!!"},
  AvgDialog_90538_Content_59 = {
    Text = "Phần sức mạnh vừa được hòa vào cơ thể như thể mọc ra linh hồn, trong những câu chú như gai, trái tim đen tối ấy gợn lên những làn sóng như thủy triều."
  },
  AvgDialog_90538_Content_6 = {
    Text = "Xin lỗi, anh."
  },
  AvgDialog_90538_Content_60 = {
    Text = "Ánh sáng trắng và đen chồng chéo nhau, khi những câu thần chú nứt vỡ từng chút một, một đôi cánh đen khổng lồ đột ngột mở ra sau lưng Polux."
  },
  AvgDialog_90538_Content_61 = {
    Text = "Đại ca……"
  },
  AvgDialog_90538_Content_62 = {
    Text = "Dưới ánh sáng rực rỡ, thiên thần mang đôi cánh lơ lửng giữa không trung, như một sứ giả trang nghiêm của Thiên Chúa, thực hiện phán quyết từ thần."
  },
  AvgDialog_90538_Content_63 = {
    Text = "Ô? Đây quả là một sự kết hợp mà tôi chưa từng nghĩ đến, bây giờ tôi càng tò mò hơn, linh hồn của bạn có còn thu hút sự đến của những người cầm đèn không?"
  },
  AvgDialog_90538_Content_64 = {
    Text = "Đã có Tín tâm như vậy, sao không dâng hiến bản thân cho Người mang đèn? Lại phải nhờ vào chúng tôi, những \"linh hồn hèn mọn\" theo lời bạn?"
  },
  AvgDialog_90538_Content_65 = {
    Text = "Có phải linh hồn của bạn quá bẩn thỉu, không thể nhận được sự cứu rỗi cao cả từ người nắm đèn?"
  },
  AvgDialog_90538_Content_66 = {
    Text = "Đứa trẻ sắc sảo, trước khi rửa sạch tội lỗi, mọi người đều có sứ mệnh của riêng mình, những gì thầy đã dạy cho bạn, có phải bạn đã quên hết rồi không?"
  },
  AvgDialog_90538_Content_67 = {
    Text = "Nói chuyện ngông cuồng, thật không thể hiểu được!"
  },
  AvgDialog_90538_Content_68 = {
    Text = "Kẻ phản bội thánh thiện và kẻ bất kính cuồng tín va chạm mạnh mẽ với nhau, những bàn tay đen kịt cuồn cuộn, đôi mắt chó đỏ tươi và chiếc răng trắng như tuyết xé rách và tái tổ hợp lẫn nhau."
  },
  AvgDialog_90538_Content_69 = {
    Text = "Dần dần, những con chó khổng lồ của Juliette đã bắt đầu vô hồn. Bàn tay khổng lồ chảy đầy \"máu thần\" nâng cao, đập vỡ đầu của chó săn xuống đất."
  },
  AvgDialog_90538_Content_7 = {
    Text = "Tôi đến muộn."
  },
  AvgDialog_90538_Content_70 = {Text = "Tch……"},
  AvgDialog_90538_Content_71 = {
    Text = "Để tôi trở lại nơi vô tội của bạn!!"
  },
  AvgDialog_90538_Content_72 = {
    Text = "Cơn cuồng phong cuốn lấy Phân rã, bùng nổ thành một cơn lốc đen, mạnh mẽ cuốn Juliette lên cao, rồi lại đập xuống mặt đất."
  },
  AvgDialog_90538_Content_73 = {
    Text = "Phụt khạc..."
  },
  AvgDialog_90538_Content_74 = {
    Text = "Hô… hô… chuẩn bị chết đi…"
  },
  AvgDialog_90538_Content_75 = {
    Text = "Hà hà, sức mạnh vĩ đại như vậy, cũng đến từ sự sáng tạo của tôi..."
  },
  AvgDialog_90538_Content_76 = {
    Text = "Bạn tất nhiên có thể đánh bại tôi, nhưng, bạn có thực sự có sức mạnh để chống lại toàn bộ giáo hội không?"
  },
  AvgDialog_90538_Content_77 = {
    Text = "Không có Thais kìm hãm, Juliette lúc này sẽ toàn tâm toàn ý thu hồi hạt giống cây đó."
  },
  AvgDialog_90538_Content_78 = {
    Text = "Khi sắc mặt của cô ta trở nên nhợt nhạt hơn, cái cây méo mó, như một đứa trẻ khóc thét, đã trở về hình dáng ban đầu, biến thành một hạt giống đen kịt, lặng lẽ tan biến trong cát vàng và dòng suối."
  },
  AvgDialog_90538_Content_79 = {
    Text = "Đèn canh và tín đồ vây kín xung quanh, những phép thuật lộn xộn rơi xuống như mưa, sức mạnh mà Thais chống đỡ cũng rõ ràng trở nên kiệt quệ."
  },
  AvgDialog_90538_Content_8 = {
    Text = "Một chiếc lông vũ quen thuộc từ nơi Kastor đã tan biến từ từ rơi xuống, đó là báu vật mà Kastor quý trọng nhất, ngay cả chính mình cũng không được động vào."
  },
  AvgDialog_90538_Content_80 = {
    Text = "Nhiều tín đồ như ruồi muỗi dũng cảm lao đến, không ngần ngại dùng mạng sống làm củi để chặn lại họ."
  },
  AvgDialog_90538_Content_81 = {
    Text = "……Cuộc sống của bạn, một ngày nào đó tôi sẽ tự tay đến lấy."
  },
  AvgDialog_90538_Content_82 = {
    Text = "Đôi cánh mệt mỏi ấy do dự một chút, cuối cùng đã quay lại cứu Thais yếu ớt ra khỏi vòng vây, vỗ cánh bay lên bầu trời cao."
  },
  AvgDialog_90538_Content_83 = {
    Text = "Tất cả Đèn vệ, tìm dấu vết của hắn, những kẻ phản bội giáo hội phải nhận sự trừng phạt thích đáng."
  },
  AvgDialog_90538_Content_84 = {
    Text = "Ái chao ái chao, tại sao phải tận diệt như vậy, tiểu thư Juliette, một thánh nhân cô đơn thì đã trở nên vô dụng lắm rồi nhỉ."
  },
  AvgDialog_90538_Content_85 = {
    Text = "Màn kịch này đã hạ màn, nếu không cam tâm, hãy chuẩn bị thật kỹ cho màn kịch tiếp theo."
  },
  AvgDialog_90538_Content_86 = {
    Text = "Dưới ánh nắng chói chang, biển cát vàng rực rỡ chậm rãi di chuyển theo gió, những đụn cát vô tận dường như không thay đổi, chỉ là những người bước lên đây hôm nay không còn là những người lữ hành của hôm qua."
  },
  AvgDialog_90538_Content_87 = {
    Text = "Trong cuộc chiến kiệt sức, Pollux ngã ngắt trên đồi cát, hắn vô cảm vuốt ve đôi cánh vừa mới mọc lại, dùng cánh ôm chặt lấy thân thể mình, mệt mỏi co lại thành một cái kén."
  },
  AvgDialog_90538_Content_88 = {
    Text = "Mặc dù không biết lai lịch của bạn, nhưng có lẽ Castor đã nhận được sự giúp đỡ của bạn suốt dọc đường, cảm ơn."
  },
  AvgDialog_90538_Content_89 = {
    Text = "Sức mạnh của tôi chỉ đủ để đưa bạn đến đây, nhà thờ ánh sáng có lẽ vẫn sẽ truy đuổi tôi, nếu không còn việc gì khác tôi có thể giúp, vậy chúng ta tạm biệt ở đây nhé."
  },
  AvgDialog_90538_Content_9 = {
    Text = "Boluque cuối cùng đã hiểu được nguồn gốc thật sự của chiếc lông vũ này, anh cúi người nhặt nó lên, nhẹ nhàng áp vào ngực mình."
  },
  AvgDialog_90538_Content_90 = {
    Text = "Mệnh lệnh đuổi khách quá thẳng thắn không hề làm phật lòng Thais, cô mỉm cười, từ từ bước trên cát vàng đến trước mặt Polyx."
  },
  AvgDialog_90538_Content_91 = {
    Text = "Tôi đã làm xong điều tôi cần làm, thực sự không còn gì cần phiền phức bạn nữa, nhưng......"
  },
  AvgDialog_90538_Content_92 = {
    Text = "Ngón tay Thais nhẹ nhàng mở ra những chiếc lông vũ đang che kín Boluque, trong ánh mắt ngạc nhiên của Boluque, điểm lên trái tim của hắn."
  },
  AvgDialog_90538_Content_93 = {
    Text = "Thực sự tôi còn một việc có thể giúp bạn."
  },
  AvgDialog_90538_Content_94 = {
    Text = "Một chút ánh sáng mềm mại chảy từ đầu ngón tay của Thais lên trái tim đó."
  },
  AvgDialog_90538_Content_95 = {
    Text = "Giống như một sinh mệnh khác được đánh thức, vô số mảnh vụn bạc trong Polux đang dần tụ lại, ngưng tụ thành một viên đá sáu cạnh, màu bạc."
  },
  AvgDialog_90538_Content_96 = {
    Text = "Đừng có vẻ mặt đau khổ như vậy, tiểu bàng, tôi đã nói rồi, số phận của các bạn đã sớm gắn kết với nhau, trong ốc đảo của sự sống, các bạn nhất định sẽ gặp lại lần nữa."
  },
  AvgDialog_90538_Content_97 = {
    Text = "Khi ánh sáng bạc lóe lên như nhịp thở, Polux không thể tin được đặt tay lên ngực, một âm thanh quen thuộc đột nhiên vang lên từ trái tim đen tối đó."
  },
  AvgDialog_90538_Content_98 = {Text = "……Hmm."},
  AvgDialog_90538_Content_99 = {
    Text = "Trong nháy mắt, đôi cánh sau lưng Polux rung rinh, như đôi cánh của một con bướm vừa mới sinh trong lúc phá kén."
  },
  AvgDialog_90539_Content_1 = {
    Text = "Cán cân nghiêng"
  },
  AvgDialog_90539_Content_10 = {
    Text = "Đôi mắt thường độ lượng của Juliette giờ tràn ngập hơi lạnh lạ lẫm, Polux biết rằng, anh không có chỗ để từ chối."
  },
  AvgDialog_90539_Content_100 = {
    Text = "<Big:<Shake:Nguyện đèn luôn sáng! Nguyện đèn luôn sáng!>>"
  },
  AvgDialog_90539_Content_101 = {
    Text = "Trong tiếng hò reo vang dội, Castor ngẩng đầu lên, đối diện với ánh mắt nhìn xuống của Juliette, lộ ra một nụ cười chưa từng khuất phục."
  },
  AvgDialog_90539_Content_102 = {
    Text = "Tất cả sức mạnh của mọi người đã được kết nối ở đây rồi, đã đến lúc rồi..."
  },
  AvgDialog_90539_Content_103 = {
    Text = "Giây tiếp theo, anh ta sẽ đặt tay lên bụng đang chảy máu của mình, vận dụng tất cả sức mạnh để kích hoạt cành cây đang ngủ yên trong cơ thể, chờ đợi nảy mầm."
  },
  AvgDialog_90539_Content_104 = {
    Text = "Tôi đã hứa, tôi nhất định sẽ dẫn bạn đến một tương lai tự do......"
  },
  AvgDialog_90539_Content_11 = {
    Text = "Tôi……tôi có thể."
  },
  AvgDialog_90539_Content_12 = {
    Text = "Rất tốt, vậy thì đi đi, thực hiện việc thanh tẩy này, đi xét xử tội ác của hắn, tất cả đều vì sự giáng sinh của người cầm đèn, cầu mong ánh đèn luôn sáng."
  },
  AvgDialog_90539_Content_13 = {
    Text = "<Shake:Nguyện ngọn đèn... mãi mãi tỏa sáng.>"
  },
  AvgDialog_90539_Content_14 = {
    Text = "Ánh mắt tĩnh lặng và nặng nề của các tín đồ đều đổ dồn về phía Polyxus, anh ta miễn cưỡng thẳng lưng, đi chầm chậm đến trước mặt Castor."
  },
  AvgDialog_90539_Content_15 = {
    Text = "Castor bị xích giữ chặt chân tay, cố nâng đầu, lộ ra vẻ bình tĩnh không bất ngờ."
  },
  AvgDialog_90539_Content_16 = {
    Text = "Một con dao găm... Cô muốn bạn thực hiện hình phạt cho kẻ phản bội, phải không?"
  },
  AvgDialog_90539_Content_17 = {
    Text = "Sự nhiệt thành, cảm thấy tội lỗi, và một nỗi sợ hãi không rõ nguồn gốc, những cảm xúc mâu thuẫn khiến Polyx không biết nên thể hiện trạng thái nào."
  },
  AvgDialog_90539_Content_18 = {
    Text = "Ông hít một hơi thật sâu, rửa sạch tay trong cái chậu bạc do người hầu bên cạnh đem đến, thì thầm với Castor."
  },
  AvgDialog_90539_Content_19 = {
    Text = "Điều này cũng vì lợi ích của bạn, nếu có thể thanh tẩy linh hồn bạn, bạn sẽ vẫn còn..."
  },
  AvgDialog_90539_Content_2 = {
    Text = "Boluque ngạc nhiên nhìn vào con dao găm sáng bạc toàn thân."
  },
  AvgDialog_90539_Content_20 = {
    Text = "Hà… không cần phải nói nữa, hãy hành động đi, Polycus."
  },
  AvgDialog_90539_Content_21 = {
    Text = "Khi bạn đã trải qua những đau khổ đó, tôi đã luôn cảm thấy hối tiếc vì không thể thay bạn gánh chịu, có lẽ đó là số phận cho tôi bù đắp cho những gì tôi đã thiếu nợ bạn..."
  },
  AvgDialog_90539_Content_22 = {
    Text = "Lại đến nữa, bạn đang nói nhảm gì vậy?!"
  },
  AvgDialog_90539_Content_23 = {
    Text = "Quả thật... ngu ngốc không thể tả. Quả nhiên, những gì ngài giáo chủ nói không sai, bạn thật sự nên được thanh tẩy một cách nghiêm túc..."
  },
  AvgDialog_90539_Content_24 = {
    Text = "Boluque có phần thần kinh thuyết phục chính mình, anh giơ cao con dao găm tỏa ra ánh sáng lạnh, lớn tiếng niệm thần chú cầu nguyện."
  },
  AvgDialog_90539_Content_25 = {
    Text = "Tôi cầu xin lòng thương xót của người cầm đèn, cầu xin sự chú ý của bạn, cầu xin bạn rửa sạch tội lỗi của người này bằng máu thần thánh."
  },
  AvgDialog_90539_Content_26 = {
    Text = "Tôi sẽ khắc thánh hành của ngài lên bốn chi của kẻ tội lỗi, để cầu ngài điều chỉnh bước đi lạc lối của hắn.\n\"Ngài cầm ngọn nến bất diệt, đi trên đất tối tăm...\""
  },
  AvgDialog_90539_Content_27 = {
    Text = "Trong âm thanh lặp đi lặp lại của hàng ngàn tín đồ, Pollux đứng nghiêm trước Castor, hai đôi mắt giống nhau nhìn chằm chằm vào nhau, tất cả những lời chưa kịp nói đều tan biến trong khoảnh khắc ánh máu lóe lên."
  },
  AvgDialog_90539_Content_28 = {Text = "Ừ——"},
  AvgDialog_90539_Content_29 = {
    Text = "Mũi dao cắt vào da, để lại một vết máu uốn lượn, bắt đầu từ vai của Castor, lang thang và khắc họa, gây ra những cơn run rẩy đau đớn."
  },
  AvgDialog_90539_Content_3 = {
    Text = "Nó thon thả và duyên dáng, khắc họa những lời văn phức tạp, như một vật thánh thiện, được nhẹ nhàng trao cho đôi tay cứng đờ của Polux."
  },
  AvgDialog_90539_Content_30 = {
    Text = "\"Ngài nhìn thấy tội ác tràn ngập, rơi nước mắt buồn thương, nên Ngài đã cắt đứt thịt, rơi xuống máu đen...\""
  },
  AvgDialog_90539_Content_31 = {
    Text = "\"Máu Ngài xóa đi tội ác, giúp triệu triệu tội nhân được giải thoát khỏi linh hồn...\""
  },
  AvgDialog_90539_Content_32 = {
    Text = "Dây xích căng thẳng vang lên lách cách, tay cầm dao của Pauluk cũng run rẩy một cách nhẹ nhàng."
  },
  AvgDialog_90539_Content_33 = {
    Text = "Nhân lúc hành động để che giấu, hắn tiến lại gần tai Castor, tức giận vì hắn làm chưa đủ tốt mà thuyết phục."
  },
  AvgDialog_90539_Content_34 = {
    Text = "Hãy xưng tội đi, chỉ cần bạn thành tâm xưng tội, chứng minh sự sùng kính của bạn, ngài Giáo chủ sẽ tha thứ cho bạn!"
  },
  AvgDialog_90539_Content_35 = {
    Text = "Không... bạn không hiểu người phụ nữ đó, cũng không hiểu cô ấy muốn gì, cô ấy sẽ không dừng tay đâu, cứ tiếp tục đi..."
  },
  AvgDialog_90539_Content_36 = {
    Text = "Bạn! Kẻ điên không thể cứu vãn! Đây chính là việc bạn tự gây ra, vì vậy đừng trách tôi……"
  },
  AvgDialog_90539_Content_37 = {
    Text = "Ôi vị nắm đèn nhân từ, tôi sẽ khắc ghi lòng từ bi của ngài lên lưng kẻ tội lỗi, cầu xin ngài rửa sạch mọi ác trong xương hắn."
  },
  AvgDialog_90539_Content_38 = {
    Text = "Khắc sâu ngày càng nhanh hơn, Boluque đã đến phía sau Castor, tránh khỏi đôi cánh mà hắn từng ghen tị và an tâm, khắc bùa chú từ cổ xuống dưới."
  },
  AvgDialog_90539_Content_39 = {
    Text = "\"Nhưng thế giới vẫn chìm trong bóng tối vô tận, vì vậy Ngài đã dùng ánh sáng đó, thắp sáng thân thể của mình...\""
  },
  AvgDialog_90539_Content_4 = {
    Text = "Thưa giáo chủ... đây là gì?"
  },
  AvgDialog_90539_Content_40 = {
    Text = "\"Ánh sáng rực rỡ bật lên từ thân thể của Ngài, thịt và xương của Ngài kết lại thành bạc tinh khiết trong lửa, Ngài lại tách thịt và xương bạc ra, ân tặng cho những người chính trực trên thế gian, để trả lại tội lỗi của họ.\""
  },
  AvgDialog_90539_Content_41 = {
    Text = "Boluque nhìn lưng Castor hơi cong lên, nghe thấy hơi thở ngày càng đau đớn của anh, từ trước đến nay chưa từng ghét bỏ sự ngoan cố của mình như bây giờ."
  },
  AvgDialog_90539_Content_42 = {
    Text = "(Rõ ràng tất cả những điều này đều do anh ta tự tìm đến, nhưng tại sao tôi vẫn thấy hỗn loạn như vậy, bối rối như vậy?)"
  },
  AvgDialog_90539_Content_43 = {
    Text = "Boluque thậm chí có chút không dám quay lại trước mặt Castor, không dám nhìn vào biểu cảm của anh hiện tại."
  },
  AvgDialog_90539_Content_44 = {
    Text = "……Bây giờ, với tội lỗi đầy mình, tôi sẽ cầu xin lòng thương xót của nhà thờ ánh sáng cho bạn, tôi sẽ hướng ánh nhìn của Ngài vào tâm hồn bạn."
  },
  AvgDialog_90539_Content_45 = {
    Text = "Thế nhưng, khi anh ta trở lại trước mặt Castor lần nữa, cái nhìn anh thấy chỉ là một đôi mắt đau buồn, không hề oán trách."
  },
  AvgDialog_90539_Content_46 = {
    Text = "……Đừng nhìn tôi như vậy."
  },
  AvgDialog_90539_Content_47 = {
    Text = "Một cơn giận đột ngột nuốt chửng Polyx, tất cả nỗi đau, căm ghét, và sự bất lực như thể chực chờ vồ lấy anh ta, khiến anh ta không thể hiểu, không thể đáp lại."
  },
  AvgDialog_90539_Content_48 = {
    Text = "Thế nhưng, dưới ánh mắt đầy u sầu ấy, Castor còn nỗ lực nở một nụ cười."
  },
  AvgDialog_90539_Content_49 = {
    Text = "Đừng sợ, Polyclus…"
  },
  AvgDialog_90539_Content_5 = {
    Text = "Đây là dụng cụ đặc biệt chuẩn bị cho nghi lễ thanh tẩy này."
  },
  AvgDialog_90539_Content_50 = {
    Text = "Câm miệng, câm miệng! Tôi đã nói rồi, tôi ghét khi bạn nhìn tôi như vậy!"
  },
  AvgDialog_90539_Content_51 = {
    Text = "Đầu ngón tay trắng bệch của Boluque siết chặt con dao găm, mũi dao bạc đột ngột cắm mạnh vào cơ thể."
  },
  AvgDialog_90539_Content_52 = {
    Text = "Những giọt máu nóng hổi bắn lên khuôn mặt giận dữ của Polux, dính vào khóe mắt như một giọt nước mắt đỏ thắm."
  },
  AvgDialog_90539_Content_53 = {Text = "Ừm——"},
  AvgDialog_90539_Content_54 = {
    Text = "Tại sao bạn luôn như vậy? Tại sao phải làm những việc ngu ngốc như thế? Bây giờ tại sao bạn lại... không ghét tôi?"
  },
  AvgDialog_90539_Content_55 = {
    Text = "Đây chính là số phận của chúng ta, Polyx, nếu những nỗi đau này là do bạn mang lại, thì cũng tốt..."
  },
  AvgDialog_90539_Content_56 = {
    Text = "Đủ rồi, tội nhân kia, hãy hoàn toàn ăn năn với người giữ đèn đi!"
  },
  AvgDialog_90539_Content_57 = {
    Text = "\"Giờ đây linh hồn Ngài đã trở lại miền đất vô tội, nhưng ánh mắt Ngài vẫn thiện lương nhìn thế gian này, ban máu, thịt, xương cho thế nhân, để tiếp dẫn những linh hồn vô tội đến miền đất sạch sẽ, chia sẻ với Ngài vương quốc thuần khiết.\""
  },
  AvgDialog_90539_Content_58 = {
    Text = "Bạn phải trực diện với tội ác sâu nhất của mình, làm rõ nỗi đau và sự hối hận của bạn, tôi sẽ thay Ngài ban phước… và xét xử."
  },
  AvgDialog_90539_Content_59 = {
    Text = "Khi câu thần chú cuối cùng rơi xuống ngực, một cơn hoa mắt khó cưỡng mờ mịt tầm nhìn vì cơn đau đớn của Castor."
  },
  AvgDialog_90539_Content_6 = {
    Text = "Bạn phải dùng nó để khắc câu thần chú thánh thiện lên máu thịt của Castor, cầu nguyện sự chú ý và tha thứ của người cầm đèn, để tội lỗi của hắn được giải phóng từ sâu trong linh hồn."
  },
  AvgDialog_90539_Content_60 = {
    Text = "(Cuối cùng cũng sắp kết thúc rồi sao, đây là... ảo mộng do nghi thức mang lại sao? Đối diện với tội ác... tội ác của tôi sao...)"
  },
  AvgDialog_90539_Content_61 = {
    Text = "Hiệu quả của nghi thức cải tạo rất tốt, phương hướng của chúng ta không có vấn đề, từ hôm nay trở đi, mỗi tuần sẽ tiến hành nghi thức cải tạo cho thánh tử Polyxus, cố gắng hoàn thành \"trái tim thánh\" sớm nhất có thể."
  },
  AvgDialog_90539_Content_62 = {
    Text = "Đau quá... Anh ơi... ngực đau quá..."
  },
  AvgDialog_90539_Content_63 = {
    Text = "Boluque! Anh thế nào... tôi phải làm gì, anh chảy rất nhiều máu, rất nhiều, tại sao không cầm máu được..."
  },
  AvgDialog_90539_Content_64 = {
    Text = "Được, rất tốt, những chú chim hướng về bầu trời, câu chuyện cảm động biết bao, nếu những thứ vô dụng này gây trở ngại thì thôi bỏ đi vậy."
  },
  AvgDialog_90539_Content_65 = {
    Text = "Gì... đợi đã! Ngài Giáo Chủ! Xin hãy cân nhắc thêm! Polycus chỉ muốn nhìn thế giới bên ngoài, hắn chỉ quá đau khổ..."
  },
  AvgDialog_90539_Content_66 = {
    Text = "Là tôi, là tôi đã tấn công lính canh đèn, nếu có trừng phạt thì hãy trừng phạt tôi đi! Không… không!"
  },
  AvgDialog_90539_Content_67 = {
    Text = "Cái lồng giam không nhìn thấy ánh sáng, lông vũ phân tán, máu đầy vô tận, và nỗi đau sâu sắc không thể tiêu tan trong mắt của em trai."
  },
  AvgDialog_90539_Content_68 = {
    Text = "Trong hàng ngàn ngày đêm, những nỗi hối tiếc bất lực như những lưỡi dao đâm vào linh hồn của Kastor, đó là sức mạnh để anh ta tiến bước, nhưng cũng là tội lỗi của sự nhút nhát."
  },
  AvgDialog_90539_Content_69 = {
    Text = "Bạn đã nhìn rõ tội ác trong lòng mình, hãy ăn năn với người giữ đèn để cầu xin sự tha thứ của Ngài."
  },
  AvgDialog_90539_Content_7 = {
    Text = "Khắc ghi? Nhưng điều này không giống quy trình của nghi thức ban phước..."
  },
  AvgDialog_90539_Content_70 = {
    Text = "Đau quá, đau quá, anh ơi, tại sao không cứu em..."
  },
  AvgDialog_90539_Content_71 = {
    Text = "<Shake:Không... không... Polux...>"
  },
  AvgDialog_90539_Content_72 = {
    Text = "……Bạn đang gọi tôi?"
  },
  AvgDialog_90539_Content_73 = {
    Text = "Tại sao bạn không làm gì cả? Tại sao không cứu tôi?!"
  },
  AvgDialog_90539_Content_74 = {
    Text = "<Shake:Do anh trai quá yếu ớt, quá vô dụng... tôi...>"
  },
  AvgDialog_90539_Content_75 = {
    Text = "Không, đừng cúi đầu, anh à, hãy kiên trì, vì tự do."
  },
  AvgDialog_90539_Content_76 = {
    Text = "Được, tôi sẽ, tôi sẽ..."
  },
  AvgDialog_90539_Content_77 = {
    Text = "Mong muốn của bạn, mong muốn của chúng ta, tôi sẽ... kiên trì đến cùng."
  },
  AvgDialog_90539_Content_78 = {
    Text = "Boluque nhìn Castor với vẻ mặt dần dần thanh thản và bình yên, nén xuống sự tò mò về tiếng gọi vừa rồi, anh quay người cung kính báo cáo với Juliette."
  },
  AvgDialog_90539_Content_79 = {
    Text = "Giáo chủ đại nhân, nghi thức đã hoàn thành, tôi sẽ dẫn Kastor đi băng bó trước…"
  },
  AvgDialog_90539_Content_8 = {
    Text = "Chắc chắn đây không phải là nghi lễ ban phước, bạn có nghĩ rằng chúng tôi cần phải tử tế đến vậy với những kẻ phản bội không trung thành không?"
  },
  AvgDialog_90539_Content_80 = {
    Text = "Không cần đâu, tiếp theo, mới là khởi đầu thực sự của nghi lễ, bạn hãy ở đây cùng Castor, hoàn thành sứ mệnh cuối cùng của Thánh Tử, hiến dâng tất cả cho người cầm đèn nhé."
  },
  AvgDialog_90539_Content_81 = {
    Text = "Juliette vẫn giữ nụ cười không thay đổi của mình, như thể ném một chiếc lá vô dụng, không quan tâm đến ánh nhìn kinh ngạc của Polux."
  },
  AvgDialog_90539_Content_82 = {
    Text = "Đèn vệ quanh ngay lập tức tiến lên, cắm những cái đèn dài vào hai Thánh nhân, tạo thành một vòng tam giác phát sáng."
  },
  AvgDialog_90539_Content_83 = {
    Text = "……Gì cơ? Tôi? Thưa ngài giáo chủ, linh hồn tôi tuyệt đối rất thành kính! Không cần thực hiện nghi thức thanh tẩy!"
  },
  AvgDialog_90539_Content_84 = {
    Text = "Boluque vòng vòng, nhưng không thể vượt qua ranh giới của vòng tròn ma thuật."
  },
  AvgDialog_90539_Content_85 = {
    Text = "Hà hà… đây không bao giờ là một nghi thức thanh tẩy cả."
  },
  AvgDialog_90539_Content_86 = {
    Text = "Castor, người ban đầu ngã gục trong vũng máu, không biết đã tỉnh dậy từ khi nào, đang vật lộn để đứng dậy, nghểnh ngẩng lưng thẳng."
  },
  AvgDialog_90539_Content_87 = {
    Text = "Boluque, em trai yêu quý của tôi, đừng sợ..."
  },
  AvgDialog_90539_Content_88 = {
    Text = "Bạn đang nói gì, bạn hoàn toàn điên rồ rồi sao?"
  },
  AvgDialog_90539_Content_89 = {
    Text = "Boluque hoảng loạn nhìn quanh, chỉ thấy những tín đồ cuồng nhiệt và lãnh đạm xung quanh, để lộ ra những ánh mắt lạnh lùng quen thuộc."
  },
  AvgDialog_90539_Content_9 = {
    Text = "Hay là… bạn không nỡ, không thể thực hiện nghĩa vụ của thánh tử?"
  },
  AvgDialog_90539_Content_90 = {
    Text = "Dưới âm thanh trì chí kêu gọi lần nữa, từng lưỡi dao xé rách da thịt, vô số tín đồ đã nhỏ máu xuống chân mình."
  },
  AvgDialog_90539_Content_91 = {
    Text = "Một vòng tròn ma thuật đã được chôn sâu trong lòng đất phát sáng một ánh sáng mờ, cây khổng lồ ở giữa vòng cùng với những con quái vật đã bị sương mù đen nuốt chửng."
  },
  AvgDialog_90539_Content_92 = {
    Text = "Máu thịt và cành cây giống như sáp dầu, tan chảy và nhỏ giọt, từ từ tụ lại thành một đầm lầy phân rã."
  },
  AvgDialog_90539_Content_93 = {
    Text = "Xin hãy nhận những lễ vật này, người cầm đèn vĩ đại. Chúng tôi sẽ thanh tẩy những kẻ tội đồ này, trả lại máu thần thánh của ngài, và cầu mong ngài giáng thế nơi trần gian này!"
  },
  AvgDialog_90539_Content_94 = {
    Text = "Vòng tròn ma thuật như một cái miệng khổng lồ đang thở, tỏa ra ánh sáng ngày càng mạnh mẽ."
  },
  AvgDialog_90539_Content_95 = {
    Text = "Ừm… có chuyện gì vậy, ngực tôi nóng quá…"
  },
  AvgDialog_90539_Content_96 = {
    Text = "Hả... Thì ra lời nguyền được dùng ở đây..."
  },
  AvgDialog_90539_Content_97 = {
    Text = "Những câu chú vừa khắc lên người Castor, cùng với trái tim thánh đã trải qua cải cách của Polydeuces, phát sáng đồng thời với những ký tự trên mặt đất."
  },
  AvgDialog_90539_Content_98 = {
    Text = "Khi vô số hy sinh không thể cứu vãn biến mất, một cảm giác vĩ đại và kinh khủng, khiến linh hồn rung động dần dần trở nên đậm đặc."
  },
  AvgDialog_90539_Content_99 = {
    Text = "Ánh nắng, mây, gió đều ngừng lại như hóa đá — nghi thức giáng thần thực sự đã bắt đầu. Nghi thức khổng lồ tham lam nuốt chửng linh hồn của hai lễ vật, muốn bóp méo, hòa nhập linh hồn của họ."
  },
  AvgDialog_90540_Content_1 = {Text = "Chim đôi"},
  AvgDialog_90540_Content_10 = {Text = "Boluque!"},
  AvgDialog_90540_Content_11 = {
    Text = "Người anh trai lo lắng bước lên một bước, cố gắng duỗi tay ra để chính xác bắt lấy cậu, nhưng chàng trai đã đánh giá thấp lực rơi xuống và đánh giá quá cao sức mạnh của mình."
  },
  AvgDialog_90540_Content_12 = {
    Text = "Một tiếng \"bùng\", hai cậu bé ngã nhào xuống đất với tư thế hỗn độn, làm bùng lên lớp bụi mỏng trong kho."
  },
  AvgDialog_90540_Content_13 = {
    Text = "Ái chao, đau đau đau...quyển sách đó đâu? Có rơi vỡ không?"
  },
  AvgDialog_90540_Content_14 = {
    Text = "Boluque ôm lấy mông, nghiến răng ngồi dậy, lập tức lao tới kiểm tra những cuốn sách rơi bên cạnh - may mà đây là một quyển sách chất lượng cao được bao bọc đẹp đẽ."
  },
  AvgDialog_90540_Content_15 = {
    Text = "Bạn không hề quan tâm xem tôi có bị bạn ném hỏng không."
  },
  AvgDialog_90540_Content_16 = {
    Text = "Ánh mắt trẻ con của Castor chu môi, khá là ủy khuất tiến lại gần, hai đứa trẻ chụm đầu lại, hoàn toàn bị bìa cuốn sách lớn với những hoa văn lộng lẫy được thêu bằng chỉ vàng thu hút."
  },
  AvgDialog_90540_Content_17 = {
    Text = "Tôi biết bạn chắc chắn là mạnh nhất, anh trai tôi sao có thể bị đánh bại bởi vấn đề nhỏ này chứ..."
  },
  AvgDialog_90540_Content_18 = {
    Text = "Boluque cười khúc khích, nhưng do đôi mắt vẫn không rời khỏi bìa sách, những lời an ủi chân thành trước đây giờ trở nên hời hợt, nhưng Castor lúc này rõ ràng cũng không để ý đến điều đó."
  },
  AvgDialog_90540_Content_19 = {
    Text = "Hoa văn đẹp quá, đây có phải được vẽ bằng vàng không? Quyển sách này nhất định rất quý giá."
  },
  AvgDialog_90540_Content_2 = {
    Text = "Anh ơi, anh ơi!"
  },
  AvgDialog_90540_Content_20 = {
    Text = "Khi tín đồ đó dâng lễ vật đã nói rằng cái này gọi là……bản sao chép tay? Polycus, bạn có biết bản sao chép tay là gì không?"
  },
  AvgDialog_90540_Content_21 = {
    Text = "Hai chúng tôi ngày nào cũng ở bên nhau, làm sao tôi biết những thứ bạn không biết! Nhưng, mở ra xem thì biết thôi."
  },
  AvgDialog_90540_Content_22 = {
    Text = "Cũng thế, giáo hội quy định chúng ta chỉ có thể đọc sách trong kho sách của người cầm đèn, lặp đi lặp lại chỉ là những thứ đó, nội dung mỗi cuốn đều gần giống nhau..."
  },
  AvgDialog_90540_Content_23 = {
    Text = "Đối với hai đứa trẻ chưa từng bước ra khỏi Nhà thờ ánh sáng, quyển sách ngoại lai này chỉ nằm yên ở đây, như thể nó là cuốn sách ma thuật kỳ diệu nhất trong tưởng tượng của trẻ con, luôn thu hút trái tim chúng."
  },
  AvgDialog_90540_Content_24 = {Text = "A……"},
  AvgDialog_90540_Content_26 = {
    Text = "Bầu trời sao, cánh đồng, đại dương, sa mạc, trên đồng tuyết cũng có hoa nở; quân vương, kẻ hầu, hiệp sĩ và công chúa, kẻ quái ác cũng sẽ gục ngã dưới thanh kiếm của kẻ chính nghĩa…"
  },
  AvgDialog_90540_Content_27 = {
    Text = "Đây là một cuốn từ điển tổng hợp nhiều ghi chép và câu chuyện từ thời trung cổ, các hình ảnh được vẽ bằng nhiều màu sắc quý giá như một chiếc kính vạn hoa phản ánh lại thế giới mà họ chưa từng biết đến."
  },
  AvgDialog_90540_Content_28 = {
    Text = "Bò... ừm..."
  },
  AvgDialog_90540_Content_29 = {
    Text = "Trong dư âm ngạc nhiên, hai thiếu niên vẫn không nói một lời nào."
  },
  AvgDialog_90540_Content_3 = {
    Text = "Mệt quá, cơ thể nặng quá... Đây là... mơ?"
  },
  AvgDialog_90540_Content_30 = {
    Text = "Castor mở miệng, có quá nhiều câu hỏi muốn hỏi, nhưng không biết hỏi từ đâu, anh như một đứa trẻ đang tập nói, đầy sự vô tri và lúng túng với thế giới."
  },
  AvgDialog_90540_Content_31 = {
    Text = "Đi, chúng ta quay về, cuốn sách này nhất định phải giữ cẩn thận. Cuốn sách dày như vậy, chúng ta xem một ít mỗi tối...... không đến một tháng là sẽ xem xong!"
  },
  AvgDialog_90540_Content_32 = {
    Text = "Cuốn sách dày nặng bị đóng lại với một tiếng \"bịch\" trong ánh mắt không nỡ, hai anh em nhìn nhau, đều nhận thấy ánh sáng phấn khích trong mắt nhau."
  },
  AvgDialog_90540_Content_33 = {
    Text = "Dưới đây, hãy mở cuốn sách tới trang hai mươi sáu, hôm nay tôi sẽ dạy hai vị thánh tử học cách phát hiện tội lỗi, xét xử tội lỗi."
  },
  AvgDialog_90540_Content_34 = {
    Text = "Trong một lớp học yên tĩnh, âm thanh của Albino viết giải thích kinh văn trên bảng vang vọng."
  },
  AvgDialog_90540_Content_35 = {
    Text = "Bề ngoài ngoan ngoãn tán thành chính là Polycus, khi Albino quay đầu lại, hắn đã nháy mắt nghiêng đầu, chỉ cho Castor thủ ngữ bí mật mà hai người bọn họ phát minh ra."
  },
  AvgDialog_90540_Content_36 = {
    Text = "(Hôm nay còn đọc câu chuyện về hiệp sĩ và công chúa thế nào, lần này tôi sẽ đóng vai hiệp sĩ, còn bạn sẽ đóng vai quái vật.)"
  },
  AvgDialog_90540_Content_37 = {
    Text = "(À, nhưng tôi đã xem câu chuyện đó mười hai lần rồi.)"
  },
  AvgDialog_90540_Content_38 = {
    Text = "(Vậy thì bạn nói xem xem bài nào? Trang nào mà chúng ta không xem ít nhất sáu bảy lần, bài đó đã là đẹp nhất rồi!)"
  },
  AvgDialog_90540_Content_39 = {
    Text = "(Bạn cũng nói đúng... nhưng tôi không muốn đóng vai quái vật.)"
  },
  AvgDialog_90540_Content_4 = {
    Text = "Anh ơi! Ngài Casstorl Thánh Nhân! Lại đang ngẩn người gì nữa đấy? Nhanh giúp tôi di chuyển cái thang qua bên trái một chút!"
  },
  AvgDialog_90540_Content_40 = {
    Text = "(Anh trai đáng ghét! Thôi thì, tôi cũng hơi chán rồi, nếu không... chúng ta tự biên một câu chuyện thì sao?)"
  },
  AvgDialog_90540_Content_41 = {
    Text = "(Cách viết câu chuyện thế nào? Tôi không thể nghĩ ra...)"
  },
  AvgDialog_90540_Content_42 = {
    Text = "(Ngốc quá, đã xem nhiều câu chuyện về hiệp sĩ như vậy, sao không bắt chước viết một cuộc phiêu lưu hiệp sĩ mới chứ!)"
  },
  AvgDialog_90540_Content_43 = {
    Text = "Sự giao tiếp không âm thanh giữa hai người diễn ra nhanh chóng giữa những ngón tay đang bay múa, cho đến khi một bóng đổ bất chợt nằm trước mặt Castor, không kịp thu tay lại."
  },
  AvgDialog_90540_Content_44 = {
    Text = "Bạn làm gì vậy? Hai vị thánh, có vẻ như không đang chăm chú nghe giảng nhỉ? Thật làm tôi cảm thấy buồn một chút khi thấy mình nghiêm túc trong lớp học như vậy."
  },
  AvgDialog_90540_Content_45 = {
    Text = "Ông Albino, tôi..."
  },
  AvgDialog_90540_Content_46 = {
    Text = "Xin lỗi, thưa ngài, tay của Castor hình như đã bị trật, tôi vừa định giúp anh ấy xem thử, chúng tôi đã sai, chúng tôi sẽ chú ý lắng nghe."
  },
  AvgDialog_90540_Content_47 = {
    Text = "……Thì ra là vậy, quả thật có thể hiểu được."
  },
  AvgDialog_90540_Content_48 = {
    Text = "Ánh mắt mà chứa đầy nụ cười đó nhẹ nhàng quét qua gương mặt của cả hai người, rồi tùy ý bỏ qua chuyện này, như thể cái bóng lạnh lẽo trong đôi mắt rắn vừa rồi chỉ là một trò đùa thoáng qua."
  },
  AvgDialog_90540_Content_49 = {
    Text = "À, các thánh tử, có một việc mà ngài giáo chủ đã bảo tôi chuyển đến các bạn, gần đây giáo hội có phát hiện mới, cần các bạn đi đến bàn thờ một chuyến sau giờ học."
  },
  AvgDialog_90540_Content_5 = {
    Text = "Ồ, tốt, ở bên này sao?"
  },
  AvgDialog_90540_Content_51 = {
    Text = "Đau đớn, đau đớn không thể tưởng tượng nổi, là cơn đau như thể linh hồn đang bị xé nát."
  },
  AvgDialog_90540_Content_52 = {
    Text = "Boluque khi được giáo chủ trọng chọn làm người mang \"Trái Tim Thánh\", còn tưởng đây là một vinh dự đặc biệt."
  },
  AvgDialog_90540_Content_53 = {
    Text = "Thế nhưng, khi anh ta bị cố định trên bàn thờ, mắt nhìn thấy ngực mình bị mổ xẻ, nụ cười lãnh đạm nhưng hài lòng của giáo chủ bên cạnh khiến anh lập tức hiểu ——"
  },
  AvgDialog_90540_Content_54 = {
    Text = "Gọi là Thánh Tử, cũng không khác gì một con cừu để lễ tế cho thần mà thôi."
  },
  AvgDialog_90540_Content_55 = {
    Text = "<Shake:Hả... hả... đau quá... anh trai...>"
  },
  AvgDialog_90540_Content_56 = {
    Text = "Boluque! Ngực anh... sao lại..."
  },
  AvgDialog_90540_Content_57 = {
    Text = "Bolyxus nhức nhói toàn thân, nắm chặt tay Kastor đang đỡ mình, ngẩng đầu lên, hiện ra một nụ cười bi thảm đến tê tái."
  },
  AvgDialog_90540_Content_58 = {
    Text = "<Shake:Đây chính là nghi thức cải biến mà giáo chủ nói... đây chính là số phận của chúng ta.>"
  },
  AvgDialog_90540_Content_6 = {
    Text = "Đủ rồi, đủ rồi! Chỉ cần quay lại một chút thôi, tôi đã thấy cuốn sách đó rồi! Này——"
  },
  AvgDialog_90540_Content_60 = {
    Text = "Thì giao cho đây nhé, anh trai, sau này tôi tự làm lễ cải tạo được rồi... bạn chỉ cần đứng đây chờ tôi, chỉ làm mình khó xử."
  },
  AvgDialog_90540_Content_61 = {
    Text = "Tôi……tôi đã hỏi qua giáo chủ, bà ấy nói thể chất của tôi không có linh tính bằng bạn, không thể thay thế bạn để cải tạo."
  },
  AvgDialog_90540_Content_62 = {
    Text = "Tôi nên làm gì đây, Polux, tôi không thể làm gì ngoài việc chờ đợi bạn ở đây......"
  },
  AvgDialog_90540_Content_63 = {
    Text = "Đáp lại ánh mắt gần như sắp khóc của Castor, chỉ có sự im lặng kéo dài."
  },
  AvgDialog_90540_Content_64 = {
    Text = "Như vậy cũng tốt, anh trai, ít nhất chúng ta không phải chịu đựng hai phần đau khổ."
  },
  AvgDialog_90540_Content_65 = {
    Text = "Đừng buồn, hồi nhỏ khi tôi trộm đồ ăn, lén lút vẽ trên sách, luôn là anh trai thay tôi chịu phạt vì sự bướng bỉnh của tôi, lần này, để tôi thay anh trai nhé."
  },
  AvgDialog_90540_Content_66 = {
    Text = "Ba lần, năm lần, mười một lần."
  },
  AvgDialog_90540_Content_67 = {
    Text = "Castor không còn nhớ nổi đã chờ đợi bao nhiêu lần dài dằng dặc ở cổng bàn thờ, nghi thức cải cách hàng tuần khiến người em trai mà ngày nào cũng nghĩ cách mang vui vẻ cho hai người trở nên ngày càng trầm lặng."
  },
  AvgDialog_90540_Content_69 = {
    Text = "Âm thanh bước chân loạng choạng của Boluque vừa vang lên, Castor lập tức tiến đến."
  },
  AvgDialog_90540_Content_7 = {
    Text = "Cậu bé Polux đứng trên giá gỗ trong kho, hắn nhón chân, đôi cánh còn non trên lưng không ngừng vỗ, cuối cùng đã nhảy mạnh, kéo một cuốn sách bìa cứng dày ra khỏi kệ."
  },
  AvgDialog_90540_Content_70 = {
    Text = "Bạn thế nào? Đau lắm phải không? Tôi sẽ hỗ trợ bạn về. — Những lời vô nghĩa đó cuối cùng đã bị nuốt ngược lại, chỉ có không khí im lìm và đông cứng bao quanh hai người."
  },
  AvgDialog_90540_Content_71 = {
    Text = "(Tôi thật sự không có ích gì... ngay cả không thể nói ra...)"
  },
  AvgDialog_90540_Content_72 = {
    Text = "Castor cảm thấy một điều gì đó nặng nề dị thường đang đè nặng lên cả hai, khiến họ không thể thở nổi."
  },
  AvgDialog_90540_Content_73 = {
    Text = "(Không thể tiếp tục như vậy nữa, nếu cứ như thế này... Poluxus chắc chắn sẽ...)"
  },
  AvgDialog_90540_Content_74 = {
    Text = "Boluque lặng lẽ ngồi trên giường trong cung điện, nhìn người bên cạnh vừa muốn nói lại thôi, dường như còn lo lắng và đau khổ hơn cả chính mình."
  },
  AvgDialog_90540_Content_75 = {
    Text = "Ngồi một chút đi, anh trai."
  },
  AvgDialog_90540_Content_76 = {
    Text = "Ngày mai tôi sẽ lại đi xin ý kiến giáo chủ, để tôi thay bạn thực hiện chỉnh sửa nhé."
  },
  AvgDialog_90540_Content_77 = {
    Text = "Vậy có gì khác biệt? Huống hồ bạn đã cầu xin cô ấy ba lần, lần trước còn bị cô phạt nặng, giờ lưng bạn vẫn còn lưu lại vết sẹo từ trận đánh bằng roi phải không?"
  },
  AvgDialog_90540_Content_78 = {
    Text = "Nhưng, bạn..."
  },
  AvgDialog_90540_Content_79 = {Text = "Anh ơi."},
  AvgDialog_90540_Content_8 = {
    Text = "Tìm được rồi! Tôi đã nói chắc chắn ở đây mà... ôi ôi——"
  },
  AvgDialog_90540_Content_80 = {
    Text = "Boluque đã ngăn Castor không cho tiếp tục, ánh mắt trống rỗng của anh uể oải rơi xuống góc giường, rơi vào quyển sổ tay mà hai người đã quý trọng."
  },
  AvgDialog_90540_Content_81 = {
    Text = "Bạn muốn tự do phải không?"
  },
  AvgDialog_90540_Content_82 = {
    Text = "Cái gì là... tự do?"
  },
  AvgDialog_90540_Content_83 = {
    Text = "Bạn muốn… xem thế giới bên ngoài sao? Như cách mà cuốn sao chép đã nói."
  },
  AvgDialog_90540_Content_84 = {
    Text = "Boluque nhặt quyển sổ tay, nhẹ nhàng vuốt ve bìa sách cũ, ánh mắt của anh như nhìn Castor, lại như nhìn vào một nơi rất xa xăm."
  },
  AvgDialog_90540_Content_85 = {
    Text = "Castor đứng ngây tại chỗ, trong một khoảnh khắc hiểu được tất cả những gì em trai muốn nói. Đó là những lời lẽ kỳ quặc, cứng nhắc, nhút nhát mà chính mình vĩnh viễn không thể tưởng tượng nổi."
  },
  AvgDialog_90540_Content_86 = {
    Text = "Ông sẽ phản bội giáo hội nuôi dưỡng hai người, xé rách máu thịt ra khỏi cái ổ tội ác nơi họ sinh ra, lớn lên, để thoát khỏi mọi thứ mà hai người từ nhỏ đã quen thuộc."
  },
  AvgDialog_90540_Content_87 = {
    Text = "Castor nuốt nước bọt, nắm chặt tay lại."
  },
  AvgDialog_90540_Content_88 = {
    Text = "Nếu điều đó có thể khiến bạn không còn đau khổ... Tôi muốn."
  },
  AvgDialog_90540_Content_9 = {
    Text = "Nụ cười đắc ý trên mặt Boluque chưa kịp ngơi qua hai giây, đã mất thăng bằng và ngã ngược xuống từ chiếc thang."
  },
  AvgDialog_90541_Content_1 = {Text = "Cúng bái"},
  AvgDialog_90541_Content_10 = {
    Text = "Còn ở ngôi làng nhỏ trong sa mạc đó, vị giáo chủ nói rằng cần tổ chức lễ nghi tại đây, để thanh tẩy tội lỗi trong linh hồn bạn."
  },
  AvgDialog_90541_Content_11 = {
    Text = "Nghi lễ? Ở đây? Tại sao?"
  },
  AvgDialog_90541_Content_12 = {
    Text = "Làm sao tôi biết được? Đây là quyết định của giáo chủ, trong thành phố này có quá nhiều quái vật ghê tởm, máu thần chảy tràn khắp nơi, đã đến lúc phải thanh tẩy cho người giữ đèn rồi."
  },
  AvgDialog_90541_Content_13 = {
    Text = "<Small: Không, không đúng, đây chắc chắn không phải là nghi thức thanh lọc……>"
  },
  AvgDialog_90541_Content_14 = {
    Text = "Bạn lại đang thì thào gì? Chỉ có vị giáo chủ thì dường như vẫn bắt được người phụ nữ đó trong thị trấn, nghe nói cô ta đã ngất xỉu dưới một cái cây quái dị, gần như hòa vào cây, thật kỳ dị."
  },
  AvgDialog_90541_Content_15 = {
    Text = "Thái Ỷ Ti?"
  },
  AvgDialog_90541_Content_16 = {
    Text = "Castor ngay lập tức nhận ra mức độ nghiêm trọng của sự việc, nếu ngay cả sức mạnh của Thais cũng bị liên quan, thì điều này chắc chắn không chỉ đơn giản là hình phạt cho kẻ tội lỗi."
  },
  AvgDialog_90541_Content_17 = {
    Text = "Nghe tôi nói, Polyxus, tôi biết bạn không thể tin mọi điều tôi nói, hãy coi đó là nỗi sợ của tôi, hãy coi đó là lời cầu cứu của tôi……"
  },
  AvgDialog_90541_Content_18 = {
    Text = "Castor loạng choạng duỗi tay bị trói, gấp gáp nắm lấy tay áo của Polydeuces."
  },
  AvgDialog_90541_Content_19 = {
    Text = "Rời khỏi đây! Dù chỉ một mình bạn cũng được!"
  },
  AvgDialog_90541_Content_2 = {
    Text = "Khi Castor mở mắt lần nữa, anh tưởng rằng mình sẽ trở lại cái hố tội lỗi sâu thẳm của nhà thờ, nhưng không ngờ rằng những gì anh thấy vẫn chỉ là bài trí của ngôi nhà trong sa mạc."
  },
  AvgDialog_90541_Content_20 = {
    Text = "Đây không phải là vinh quang của thánh tử! Họ chỉ sẽ lại một lần nữa làm tổn thương bạn, giống như lúc trước xẻng ngực bạn, kéo lấy đôi cánh bạn…"
  },
  AvgDialog_90541_Content_21 = {
    Text = "Đủ rồi! Tôi thật sự không hiểu, tại sao bạn cứ mãi bôi nhọ nhà thờ, Thánh Tâm và đôi cánh của tôi vốn đã như vậy, có ai từng làm tổn thương tôi đâu?"
  },
  AvgDialog_90541_Content_22 = {
    Text = "Còn về bạn, thực sự là nhát gan, tôi có thể hiểu rằng cuộc sống của bạn quá đơn điệu mà cô đơn, không muốn gánh vác trọng trách lớn lao này."
  },
  AvgDialog_90541_Content_23 = {
    Text = "Nhưng bạn không nên dao động niềm tin của một người thành kính."
  },
  AvgDialog_90541_Content_24 = {
    Text = "Lần này Boluque không đẩy Castor ra, anh nắm chặt cổ áo của Castor, đôi mắt giận dữ lại chảy ra những giọt đau đớn như có thực."
  },
  AvgDialog_90541_Content_25 = {
    Text = "Đừng còn cứng đầu chống lại thầy giáo nữa, có được trở lại cuộc sống bình yên như trước không?"
  },
  AvgDialog_90541_Content_26 = {
    Text = "<Small:Cuộc sống trước đây...>"
  },
  AvgDialog_90541_Content_27 = {
    Text = "Castor cười bi thảm, cúi đầu ủ rũ, cuối cùng đã nhận ra nỗi kinh hoàng của hình phạt quên lãng này, cũng cuối cùng nhận ra, bản thân và em trai đã không thể thoát khỏi số phận bi thảm này nữa."
  },
  AvgDialog_90541_Content_28 = {Text = "Bạn…"},
  AvgDialog_90541_Content_29 = {
    Text = "Boluque nhìn Castor bỗng im bặt, còn muốn nói gì đó, thì đột nhiên nghe tiếng bước chân của đèn vệ vọng lại từ cửa."
  },
  AvgDialog_90541_Content_3 = {
    Text = "Giống như những sự phản bội vừa trải qua đều chỉ là một giấc mơ, anh ta ngỡ ngàng muốn đứng dậy, nhưng đã bị tiếng xích từ trên người kéo trở lại thực tại, vết thương ở ngực cũng bắt đầu đau nhức."
  },
  AvgDialog_90541_Content_30 = {
    Text = "Giáo chủ đã ra lệnh, nghi thức đã chuẩn bị xong, dẫn tội nhân đến địa điểm tiến hành nghi thức."
  },
  AvgDialog_90541_Content_31 = {
    Text = "Khi Thais và hạt giống đó chìm vào giấc ngủ, chỉ trong một đêm, tất cả những giả dạng giả tạo ở Koreni đã như ảo ảnh tan biến, trong đống đổ nát chỉ còn lại sự tĩnh lặng."
  },
  AvgDialog_90541_Content_32 = {
    Text = "Cây cối lớn vươn ra như những móng vuốt đứng giữa thị trấn, khắp nơi chỉ còn lại dấu vết tàn phá điên cuồng của cành cây."
  },
  AvgDialog_90541_Content_33 = {
    Text = "Một đám mây đen bất hảo phủ lên nơi này, phủ lên xác chết đã chết của thành phố này từ lâu."
  },
  AvgDialog_90541_Content_34 = {Text = "Uống..."},
  AvgDialog_90541_Content_35 = {
    Text = "Không biết đã trải qua trận chiến và thanh trừng thế nào, hàng triệu cư dân hóa quái đang chen chúc trong một trận pháp khổng lồ và kỳ quái, giơ tay đầy thứ phân rã như những con gia súc chờ bị mổ."
  },
  AvgDialog_90541_Content_36 = {
    Text = "Giữa vòng vây của những tín đồ, bên trong cái cây khô cằn to lớn đó, chính là Thais đang ngủ say, được bọc bởi thân cây."
  },
  AvgDialog_90541_Content_37 = {
    Text = "……Quả thật."
  },
  AvgDialog_90541_Content_38 = {
    Text = "Khi Juliette xuất hiện, một dòng ánh nhìn cuồng nhiệt và yên tĩnh ngay lập tức tập trung lại."
  },
  AvgDialog_90541_Content_39 = {
    Text = "Cuối cùng, những nỗ lực nhiều năm của chúng ta sắp chào đón thời khắc cuối cùng."
  },
  AvgDialog_90541_Content_4 = {
    Text = "Đã tỉnh dậy? Đừng cử động lung tung, thầy tu vừa mới chữa lành vết thương cho bạn."
  },
  AvgDialog_90541_Content_40 = {
    Text = "Ban đầu chúng tôi chỉ đến để truy bắt kẻ tội lỗi, nhưng người giữ đèn luôn dẫn dắt tín đồ của Ngài, thành phố tội lỗi này chính là cơ hội Ngài đã ban cho chúng tôi."
  },
  AvgDialog_90541_Content_41 = {
    Text = "Máu của Ngài chảy nơi này, ánh mắt Ngài chắc chắn sẽ dõi theo nơi này, chờ đợi chúng ta thanh tẩy tội lỗi, gọi Ngài đến."
  },
  AvgDialog_90541_Content_42 = {
    Text = "Những người hầu của người cầm đèn, những người chính nghĩa, những người theo ánh sáng, hãy chuẩn bị dâng lên lòng thành kính của bạn cho người cầm đèn vĩ đại! Chào đón miền đất vô tội!"
  },
  AvgDialog_90541_Content_43 = {
    Text = "Bây giờ, hãy mời thánh tử của chúng ta lên đây nào."
  },
  AvgDialog_90541_Content_44 = {Text = "Ho.."},
  AvgDialog_90541_Content_45 = {
    Text = "Castor bị đèn vệ kéo thô bạo, Polydeuces hơi nhíu mày, nhưng chỉ đành không nhìn qua bên, kính cẩn chào."
  },
  AvgDialog_90541_Content_46 = {
    Text = "Thưa giáo chủ."
  },
  AvgDialog_90541_Content_47 = {
    Text = "Làm rất tốt, Polydeuces, bạn đã không phụ sự vinh quang của Đấng Thánh. Tiếp theo, đã đến lúc thanh tẩy linh hồn không tôn trọng người cầm đèn này."
  },
  AvgDialog_90541_Content_48 = {
    Text = "……Đúng vậy, nhưng Castor hiện tại bị thương khá nặng, có lẽ không thể thực hiện nghi thức, liệu tôi có thể..."
  },
  AvgDialog_90541_Content_49 = {
    Text = "Không sao đâu, không sao đâu, thanh tẩy tội ác chính là sứ mệnh mà bạn quen thuộc nhất, đúng không? Đến đây, cầm lấy cái này."
  },
  AvgDialog_90541_Content_5 = {
    Text = "Castor nhìn thấy Polux ngồi không xa, trong căn phòng rộng lớn chỉ có mình hắn canh giữ ở đây, Polux định nói gì đó nhưng lại nhanh chóng rút lại ánh mắt tiếp xúc."
  },
  AvgDialog_90541_Content_50 = {
    Text = "Juliette vẫn mỉm cười đầy yêu thương, quay người lại, lấy một con dao nhọn, sáng bóng từ tay một thị vệ bên cạnh, đưa cho Polux."
  },
  AvgDialog_90541_Content_6 = {
    Text = "Chúng tôi đang ở…… đâu vậy?"
  },
  AvgDialog_90541_Content_7 = {
    Text = "Ngoài giọng nói khàn khàn, Castor ngạc nhiên nhận ra vết thương ở ngực đã ngừng chảy máu hoàn toàn, đang ở trạng thái khép cứng."
  },
  AvgDialog_90541_Content_8 = {
    Text = "Hắn nhớ lại khoảng thời gian \"chữa trị\" đen tối không ánh sáng đã qua trong vực tội lỗi, không khỏi cười khổ."
  },
  AvgDialog_90541_Content_9 = {
    Text = "(Thì ra nhà thờ tinh thông pháp chữa lành như vậy...)"
  },
  AvgDialog_91726_Content_1 = {
    Text = "Nô lệ và chủ nô"
  },
  AvgDialog_91726_Content_10 = {
    Text = "Chết đi! Chết đi! Bất kỳ bài tập nào, bất kỳ đại học nào cũng đi chết đi!"
  },
  AvgDialog_91726_Content_11 = {
    Text = "Tuy nhiên, việc cắn xé vô ích không làm giảm bớt công việc chưa hoàn thành nửa phần nào, thậm chí còn khiến cô, người đã bị nhốt trong ký túc xá lâu ngày, cảm thấy một chút đói."
  },
  AvgDialog_91726_Content_12 = {
    Text = "Vì một lần nữa đã làm hỏng đồ dùng sinh hoạt trong ký túc xá, Agrippa đã cướp nhà của Aigis hôm qua, và đã đánh nhau với Jenkin, người nghe thấy tiếng đã đến."
  },
  AvgDialog_91726_Content_13 = {
    Text = "Cuối cùng đã nhận được hình phạt sao chép gấp đôi và bị cấm ba ngày."
  },
  AvgDialog_91726_Content_14 = {
    Text = "Thịt nướng, cánh gà, khoai tây chiên, súp borscht, và bánh mì bơ giòn giòn……"
  },
  AvgDialog_91726_Content_15 = {
    Text = "Agrippa nhớ lại phần duy nhất cô yêu thích trong ngôi trường này - những món ăn ngon miễn phí tại nhà ăn, cuối cùng lắc đầu, đập bàn đứng dậy."
  },
  AvgDialog_91726_Content_16 = {
    Text = "Đi chết đi, sao lại nhốt tôi, tôi muốn đi đâu thì đi đâu!"
  },
  AvgDialog_91726_Content_17 = {
    Text = "Nhân lúc đêm khuya tĩnh lặng, cô lén lén mở cửa phòng, phát hiện xung quanh không có ai, sau đó quyết tâm thâm nhập vào bếp."
  },
  AvgDialog_91726_Content_18 = {
    Text = "Không biết bây giờ bếp còn lại những gì... Ủa? Có người à? Một tên keo kiệt Mythag, ngay cả bếp cũng phải cử người canh gác sao?"
  },
  AvgDialog_91726_Content_19 = {
    Text = "Áo giáp Aigiss gần như co lại sau góc tường khi nghe thấy Agrippa lèm bèm, cô thò nửa cái đầu ra, cẩn thận nhìn vào bóng dáng ở cửa tối om."
  },
  AvgDialog_91726_Content_2 = {
    Text = "Do đặc tính vật lý của bạc, điều tra viên nên chú ý khi sử dụng sản phẩm mảnh bạc… những điều sau sẽ được nêu ra……"
  },
  AvgDialog_91726_Content_20 = {
    Text = "Đó là... bóng lưng quen thuộc, mái tóc lòa xòa như chổi lau này... Uvhash?!"
  },
  AvgDialog_91726_Content_21 = {
    Text = "Cảm giác căng thẳng bất ngờ bị phát hiện tan biến, Agrippa chống hông nhảy ra khỏi góc, lớn tiếng chỉ trích một cách chủ động."
  },
  AvgDialog_91726_Content_22 = {
    Text = "Ha, tôi tưởng ai, hóa ra là nô lệ của tôi!"
  },
  AvgDialog_91726_Content_23 = {
    Text = "Sao, nửa đêm ở đây lén lút để ăn cắp phải không? Quả nhiên không thể từ bỏ bản chất thấp hèn của nô lệ!"
  },
  AvgDialog_91726_Content_24 = {Text = "Hả?!"},
  AvgDialog_91726_Content_25 = {
    Text = "Uvhash đã phát hiện ra cô từ lâu, không ngẩng đầu lên, tiếp tục cúi đầu trước cửa, tập trung làm gì đó."
  },
  AvgDialog_91726_Content_26 = {
    Text = "Bạn đến đây giữa đêm, có phải được nhà hàng thuê đến làm việc không?"
  },
  AvgDialog_91726_Content_27 = {
    Text = "Ngươi! Ai cho phép ngươi nói chuyện như vậy với chủ nhân!?"
  },
  AvgDialog_91726_Content_28 = {
    Text = "Đừng tưởng rằng việc ngươi đã giết ta trước đây có thể khiến ngươi chiếm ưu thế mãi mãi, đó là vì ý chí cao quý của chính ta…"
  },
  AvgDialog_91726_Content_29 = {
    Text = "Này! Nhìn tôi này, cậu đang làm gì vậy, sao không để ý..."
  },
  AvgDialog_91726_Content_3 = {
    Text = "Đủ điểm … vài …"
  },
  AvgDialog_91726_Content_30 = {
    Text = "Im miệng!"
  },
  AvgDialog_91726_Content_31 = {
    Text = "Uvhash gầm lên một tiếng giận dữ, làm Agrippa đang gần đó sợ hết hồn."
  },
  AvgDialog_91726_Content_32 = {
    Text = "Hét cái gì?! Cậu điên à... Hử? Tại sao lại có nhiều ổ khóa như vậy trên cửa?"
  },
  AvgDialog_91726_Content_33 = {
    Text = "Trên cánh cửa nhỏ không mấy chú ý ở bếp sau, treo chất chồng một loạt ổ khóa, như thể chủ bếp đang phòng vệ một tên trộm quen thuộc nào đó."
  },
  AvgDialog_91726_Content_34 = {
    Text = "Tôi nói sao cậu cứ ngồi mãi ở cửa, hóa ra là không vào được hahaha!! Có khi nào cậu đến để ăn trộm, bị người ta phát hiện không!"
  },
  AvgDialog_91726_Content_35 = {
    Text = "Không có hàng ngày, thường thì chỉ cách hai ngày một lần."
  },
  AvgDialog_91726_Content_36 = {
    Text = "Điều này khác gì với hàng ngày! Da mặt ngươi thật dày, thật nên để Búp bê cũng trừng phạt ngươi thật nghiêm!"
  },
  AvgDialog_91726_Content_37 = {
    Text = "Uvhash, người đã hoàn toàn phớt lờ Agrippa khi bắt đầu vật lộn với cái khóa, tự mình cảm thấy chán nản, giậm chân và định quay đi."
  },
  AvgDialog_91726_Content_38 = {
    Text = "Tuy nhiên, cảm giác trống rỗng trong bụng lại nổi lên một lần nữa."
  },
  AvgDialog_91726_Content_39 = {
    Text = "Cô nghĩ đến việc phải quay lại đối mặt với những bản sao vô tận, nhưng vẫn quyết định ở lại với cái nô lệ mà cô ghét cho đến khi tốt hơn."
  },
  AvgDialog_91726_Content_4 = {
    Text = "Bùng một tiếng, đầu Agrippa cái một đâm xuống bàn học trong ký túc, để lại một vết đỏ rõ ràng."
  },
  AvgDialog_91726_Content_40 = {
    Text = "Đã ngu lắm rồi, tránh ra! Chẳng qua chỉ là một vài ổ khóa, làm sao để mở từ bên trong, không thể giật ra được……"
  },
  AvgDialog_91726_Content_41 = {
    Text = "Chưa kịp cho Agrippa dùng những cái chân mảnh mai để đâm khóa, Uvhash đột nhiên lớn tiếng quát, liền giật cả xâu ổ khóa đó, cùng với tay nắm cửa đã bị giật ra."
  },
  AvgDialog_91726_Content_42 = {
    Text = "……đứt đoạn."
  },
  AvgDialog_91726_Content_43 = {
    Text = "Uvhash thò tay vào lỗ lớn trên cửa, dễ dàng mở khóa từ bên trong, đá cửa ra, và bước đi nhanh chóng vào bếp."
  },
  AvgDialog_91726_Content_44 = {
    Text = "Tên nô lệ thô bạo…… Ê, chờ tôi với!"
  },
  AvgDialog_91726_Content_45 = {
    Text = "Ôi, không ngờ ở đây lại có nhiều đồ ăn như vậy, không trách gì mà cậu lại đến đây ăn trộm mỗi ngày."
  },
  AvgDialog_91726_Content_46 = {
    Text = "Agrippa, người chưa từng bước vào bếp trong hai kiếp, đang hứng khởi chạy nhảy bên cạnh những thùng chứa thực phẩm và rau củ trong bếp."
  },
  AvgDialog_91726_Content_47 = {
    Text = "Tôi nhận ra, cái này là cà chua, cái này là cà rốt, nhà hàng luôn trộn chúng vào đĩa thịt, không muốn cũng không được."
  },
  AvgDialog_91726_Content_48 = {
    Text = "Quả dưa lớn này là gì? Lớn hơn cả đầu ta, thôi kệ… nhìn là biết không ngon."
  },
  AvgDialog_91726_Content_49 = {
    Text = "Sao toàn là rau củ không thú vị thế này, họ giấu thịt nướng ở đâu rồi... Uvhash? Lại nghịch cái gì nữa vậy?"
  },
  AvgDialog_91726_Content_5 = {
    Text = "Đau quá! @2, tại sao tôi phải sao chép những cuốn sách ngu ngốc này ở đây!"
  },
  AvgDialog_91726_Content_50 = {
    Text = "Hmph, cô gái ngốc nghếch."
  },
  AvgDialog_91726_Content_51 = {
    Text = "Uvhash, người vừa vượt qua được chốt bếp, đang vui vẻ, nhanh chóng mở khóa yếu ớt trên tủ làm lạnh, vẫy tay chào Agrippa."
  },
  AvgDialog_91726_Content_52 = {
    Text = "Khi cả hai cái đầu đều chụm lại trước tủ lạnh, giống như mở ra cánh cửa thế giới mới, Uvhash tự hào kéo mạnh cửa tủ ra."
  },
  AvgDialog_91726_Content_53 = {
    Text = "Đây là… thịt nướng núi lửa!!"
  },
  AvgDialog_91726_Content_54 = {
    Text = "Thịt không thấy trôi nổi gọn gàng trong góc của tủ lạnh, tại khu vực đông lạnh vẫn có một đĩa thịt đã được nấu chín nằm yên giữa, tỏa ra hương liệu quyến rũ."
  },
  AvgDialog_91726_Content_55 = {
    Text = "<Small:Ừ? Hôm nay lại có nhiều đồ thừa như vậy, trước đây chỉ có thịt sống…>"
  },
  AvgDialog_91726_Content_56 = {
    Text = "Thấy một đĩa đầy thịt, Uvhash cũng ngây người, chưa kịp suy nghĩ, Agrippa mắt sáng rực lập tức đưa đĩa thịt lên."
  },
  AvgDialog_91726_Content_57 = {
    Text = "Còn chờ gì nữa, nô lệ, nhanh chóng đốt một đống lửa để hâm nóng chúng!"
  },
  AvgDialog_91726_Content_58 = {
    Text = "Uvhash vừa định khinh thường trình bày kiến thức về lò nướng của mình, thì ánh mắt anh bất chợt nhìn thấy một cái nút kỳ lạ trên chỗ để đĩa đang dần sáng lên."
  },
  AvgDialog_91726_Content_59 = {Text = "Hả?"},
  AvgDialog_91726_Content_6 = {
    Text = "Agrippa ôm đầu tỉnh giấc, nhăn nhó nhìn những lỗi sai nguệch ngoạc trên cuốn sổ."
  },
  AvgDialog_91726_Content_60 = {
    Text = "Chỉ trong nháy mắt, sàn nhà nơi hai người đứng trước tủ lạnh bỗng nhiên tách ra, mở ra một cái lỗ đen ngòm bên dưới."
  },
  AvgDialog_91726_Content_61 = {Text = "Hả——"},
  AvgDialog_91726_Content_62 = {
    Text = "Món thịt nướng thơm ngon chưa kịp giữ chặt đã trượt khỏi tay của Agrippa."
  },
  AvgDialog_91726_Content_63 = {
    Text = "Hai người một cái bị rơi xuống đáy hố, chỉ nghe thấy tiếng \"bùng\" khi sàn nhà trên đầu nhanh chóng đóng lại. \nChỉ còn lại hai đôi mắt mở lớn im lặng nhìn nhau trong bóng tối."
  },
  AvgDialog_91726_Content_7 = {
    Text = "Hai từ viết sai \"đạt yêu cầu\" lại khiến cô nhớ về cái nhìn khinh thường của búp bê và những hình phạt chép bài đáng ghét này - đúng vậy, cô một lần nữa giành được thành tích tốt đơn vị ở kỳ thi."
  },
  AvgDialog_91726_Content_8 = {
    Text = "Đủ điểm, đủ điểm, lại đủ điểm, không đủ điểm thì sao? Tôi không phục vụ nữa!"
  },
  AvgDialog_91726_Content_9 = {
    Text = "Agrippa cáu kỉnh cầm cuốn sổ muốn xé nó, nhớ đến những phương pháp tra tấn của búp bê, cuối cùng ngừng lại trong cay đắng, căm phẫn nhét góc sách vào miệng và cắn mạnh."
  },
  AvgDialog_91727_Content_1 = {
    Text = "Sức mạnh của Rome"
  },
  AvgDialog_91727_Content_10 = {
    Text = "Danh dự của tôi, lòng tự trọng của tôi, tất cả đều đã hủy hoại! Có thể tôi sẽ còn bị phạt giam lâu hơn và phải sao chép nhiều hơn……"
  },
  AvgDialog_91727_Content_11 = {
    Text = "Nhưng tôi vẫn chưa ăn gì cả! Tôi thậm chí chưa ăn một lá rau nào cả!!"
  },
  AvgDialog_91727_Content_12 = {
    Text = "Trong cơn phàn nàn không hồi kết của Agrippa, Uvhash đã thử nhiều thủ đoạn tấn công khác nhau."
  },
  AvgDialog_91727_Content_13 = {
    Text = "Tuy nhiên, hai mảnh sàn vừa khít không hề có một khe hở nào, như thể đã được đổ lại."
  },
  AvgDialog_91727_Content_14 = {
    Text = "Agrippa hồi tưởng lại những ngày sống ở Mythag, nhớ về những cuốn sách học đầy kiến thức mà cô không hiểu."
  },
  AvgDialog_91727_Content_15 = {
    Text = "Còn những tòa nhà, phong tục, dụng cụ đã hoàn toàn thay đổi, chế độ nô lệ đã biến mất và cuộc sống độc lập bị ép buộc."
  },
  AvgDialog_91727_Content_16 = {
    Text = "Cuộc sống được xem là điều hiển nhiên đã biến thành một vòng lặp gây rắc rối, bị phạt, lại gây rắc rối, trong quá trình đó đầy rẫy tiếng thở dài, chê bai và thậm chí là thù địch từ người khác."
  },
  AvgDialog_91727_Content_17 = {
    Text = "Quy luật của thế giới đã bị lật đổ trong một đêm, nàng cố gắng giữ gìn phẩm giá của một chủ nhân nô lệ, nhưng chỉ cảm thấy sự không thích ứng tiếp diễn một lần nữa."
  },
  AvgDialog_91727_Content_18 = {
    Text = "Giống như một con cá dạt vào bờ trên một bãi biển của quá khứ, không thể đuổi kịp những làn sóng mới."
  },
  AvgDialog_91727_Content_19 = {
    Text = "Vào lúc này, cảm giác đói khát ảo diệu, đã lâu chưa được ăn uống, lại bao trùm lấy cô."
  },
  AvgDialog_91727_Content_2 = {
    Text = "Dưới một cú đòn mạnh mẽ của Uvhash, sàn nhà phía trên đầu hai người vẫn vững như bàn thạch, thậm chí phát ra những đường vân bạc một cách uyển chuyển."
  },
  AvgDialog_91727_Content_20 = {
    Text = "Sự trống rỗng mang đến cho cô không phải là nỗi đau cần thiết cho sự sống còn, mà là nỗi ấm ức vĩ đại do mất đi tất cả."
  },
  AvgDialog_91727_Content_21 = {
    Text = "Tôi chỉ muốn ăn một miếng thịt……"
  },
  AvgDialog_91727_Content_22 = {
    Text = "Con cái được cử đi khám phá cũng trở về tay không, Agrippa ngã quỵ ôm đầu gối, cuộn tròn lại trong tuyệt vọng."
  },
  AvgDialog_91727_Content_23 = {
    Text = "Rome đã sụp đổ, cuộc đời tôi cũng đã sụp đổ. Thế giới của chúng ta chẳng còn chút bụi nào, tất cả đều bị cái thời đại chết tiệt này nuốt chửng."
  },
  AvgDialog_91727_Content_24 = {
    Text = "Tôi đã đủ rồi! Tôi đã đủ với cuộc sống như vậy, đủ với cái nơi quái quỷ này, nơi này không thuộc về tôi, cũng không thuộc về bạn."
  },
  AvgDialog_91727_Content_25 = {
    Text = "Uvhash! Chúng ta không còn thể quay lại Roma nữa! Nơi vàng óng ánh, ngập tràn lửa, hoa và tiếng hoan hô, không thể trở lại nữa!"
  },
  AvgDialog_91727_Content_26 = {
    Text = "Uvhash vốn đã ngồi không quan tâm ở góc phòng, chuẩn bị chờ cho đến khi trời sáng, nhưng bị tiếng ồn của Agrippa làm cho đau tai."
  },
  AvgDialog_91727_Content_27 = {
    Text = "Hắn đã mạnh tay ngoáy tai, nhíu mày ngắt lời Agrippa."
  },
  AvgDialog_91727_Content_28 = {
    Text = "Ôi, ồn ào quá, thì sao chứ?"
  },
  AvgDialog_91727_Content_29 = {
    Text = "……Cái gì?"
  },
  AvgDialog_91727_Content_3 = {
    Text = "……Hừ."
  },
  AvgDialog_91727_Content_30 = {
    Text = "Quay lại thì sao chứ?"
  },
  AvgDialog_91727_Content_31 = {
    Text = "Agrippa ngẩng đầu không thể tin, xỉ vả Uvhash."
  },
  AvgDialog_91727_Content_32 = {
    Text = "Thật ra ta vẫn nghĩ ngươi là một chiến binh, Uvhash, lòng dũng cảm của ngươi đâu? Lời thề giết chóc của ngươi đâu?"
  },
  AvgDialog_91727_Content_33 = {
    Text = "Ngươi thực sự đã yêu cuộc sống bị người khác quản lý mỗi ngày như thế, hoàn toàn biến thành một kẻ nhát gan sao!"
  },
  AvgDialog_91727_Content_34 = {Text = "Hứ..."},
  AvgDialog_91727_Content_35 = {
    Text = "Ngươi cười gì? Ngươi đã thừa nhận rồi, không nói được gì nữa sao!"
  },
  AvgDialog_91727_Content_36 = {
    Text = "Không, ta vẫn thích giết chóc, nhưng ta đã hiểu được lợi ích lớn nhất ở đây, mà Rome cũng không thể mang lại cho ta."
  },
  AvgDialog_91727_Content_37 = {Text = "?！"},
  AvgDialog_91727_Content_38 = {
    Text = "Agrippa trợn mắt, dùng ánh mắt căm giận hận kẻ phản bội nhìn chằm chằm vào anh ta."
  },
  AvgDialog_91727_Content_39 = {
    Text = "Tại Roma, mọi người luôn buông thả bản thân, nghe theo khát vọng, bất kể là bạn, tôi, nhà vua hay thậm chí nô lệ."
  },
  AvgDialog_91727_Content_4 = {
    Text = "Cái gì? Đã xảy ra chuyện gì? Sao lại có một cái hố lớn ở đây?"
  },
  AvgDialog_91727_Content_40 = {
    Text = "Tôi có thể giết sạch tất cả kẻ thù cho vị vua tham lam trong một đêm, nhưng sau đó, tôi bị giam dưới đất một nghìn năm."
  },
  AvgDialog_91727_Content_41 = {
    Text = "Một nghìn năm sau, tôi lại đón chào bữa tiệc mới, và sau đó tôi chết, cũng vì đói khát phóng túng."
  },
  AvgDialog_91727_Content_42 = {
    Text = "Những người ở đây không giống nhau, họ tôn thờ một thứ gọi là lý trí, họ rối rắm, kìm nén, thiếu nam tính."
  },
  AvgDialog_91727_Content_43 = {
    Text = "Tôi cũng ghét những quy tắc lộn xộn như bạn - tôi không biết tại sao họ lại đặt ra nhiều quy định cho chính họ như vậy?"
  },
  AvgDialog_91727_Content_44 = {
    Text = "Ngươi phải biết rằng họ hoàn toàn không thể kiểm soát được ta, chỉ cần ta muốn, ta có thể ra ngoài gây náo loạn bất cứ lúc nào, giết chóc một cách đã đời."
  },
  AvgDialog_91727_Content_45 = {
    Text = "Mythag… Những kẻ này cho tôi dòng máu bất tận, sự giết chóc không bao giờ thiếu kẻ thù…"
  },
  AvgDialog_91727_Content_46 = {
    Text = "Dù giờ đây chúng ta bị giam ở đây, khi ánh nắng đầu tiên của sáng mai chiếu vào ký túc xá của những kẻ này, họ sẽ phát hiện ra tôi không còn ở đây."
  },
  AvgDialog_91727_Content_47 = {
    Text = "Rồi họ sẽ hoảng sợ, quay cuồng như những con kiến trên chảo nóng, cho đến khi ngoan ngoãn mở cái cửa chết tiệt này ra."
  },
  AvgDialog_91727_Content_48 = {
    Text = "Thế giới được cho là thời đại mới này không thể làm gì được chúng ta, phải không?"
  },
  AvgDialog_91727_Content_49 = {
    Text = "Biểu hiện vốn giận dữ của Agrippa dần trở nên ngớ ngẩn, cô nhìn vào Uvhash thả lỏng dựa vào góc, đột nhiên hiểu được \"an ninh\" quý giá mà nơi này mang lại cho cô."
  },
  AvgDialog_91727_Content_5 = {
    Text = "Tôi hiểu rồi... bẫy! Là cái bẫy hèn hạ! Chính là miếng thịt đó! Uvhash! Chắc chắn là để nhắm vào anh!!"
  },
  AvgDialog_91727_Content_50 = {
    Text = "Cô nhớ rằng mỗi khi đêm đến, cô đã có thể yên tâm nhắm mắt lại, không cần lo lắng về bất kỳ sự phản bội nào."
  },
  AvgDialog_91727_Content_51 = {
    Text = "Những quá khứ giống như cơn ác mộng từng giữ cô lại trong mê cung, đã lâu lắm rồi cô không nghĩ đến nữa."
  },
  AvgDialog_91727_Content_52 = {
    Text = "Tuy nhiên, khi nhìn thấy vẻ kiêu ngạo và tự phụ của kẻ nô lệ đó, cô vẫn cảm thấy một cơn ngứa ngáy trong răng."
  },
  AvgDialog_91727_Content_53 = {
    Text = "Cái gì mà luyên thuyên, không phải là ngươi đã phản bội Rome, yêu thích cuộc sống làm nô lệ cho chủ mới sao?"
  },
  AvgDialog_91727_Content_54 = {
    Text = "Nô lệ, vũ khí... ai quan tâm chứ? Chúng cho tôi máu, cho tôi một nguồn máu vô tận!"
  },
  AvgDialog_91727_Content_55 = {
    Text = "Còn về quy tắc của ngươi… đã sớm giống như Roma, chôn vùi nhiều năm rồi."
  },
  AvgDialog_91727_Content_56 = {
    Text = "Dù giờ có trở lại Roma, những quái vật như cậu cũng sẽ ngay lập tức bị truy quét, nhìn vậy mà cậu còn phải cảm ơn nơi này nữa."
  },
  AvgDialog_91727_Content_57 = {
    Text = "Ngươi! Ta đã hiểu, ngươi thực sự đã trở thành một kẻ hèn nhát!"
  },
  AvgDialog_91727_Content_58 = {
    Text = "Ngươi sợ rằng cuộc sống bị người ta sử dụng và vứt bỏ, chỉ muốn trở thành một con chó cưng được người chăm sóc thôi sao!"
  },
  AvgDialog_91727_Content_59 = {
    Text = "Sợ hãi? Tôi chưa bao giờ sợ hãi, cũng không hề hối hận."
  },
  AvgDialog_91727_Content_6 = {
    Text = "Agrippa muốn cãi nhau, khi thấy tấn công của Uvhash hoàn toàn vô hiệu, cô càng la hét chửi bới."
  },
  AvgDialog_91727_Content_60 = {
    Text = "Tôi chỉ không giống như một thằng ngu nào đó, nhất định phải giữ cái lòng tự trọng rách nát của mình, cố gắng chống lại cuộc sống mới mà thôi."
  },
  AvgDialog_91727_Content_61 = {
    Text = "Ngươi nói ai là kẻ ngu ngốc?!"
  },
  AvgDialog_91727_Content_62 = {
    Text = "Agrippa phẫn nộ tóc dựng đứng, từng mảng từng mảng trứng thịt trắng chui ra khỏi cơ thể, những đôi chân điên cuồng đập lên sàn, cuối cùng không chịu đựng được nhảy xổ vào Uvhash."
  },
  AvgDialog_91727_Content_63 = {
    Text = "Tên nô lệ hèn hạ, ngươi sẽ phải trả giá cho sự bất kính của ngươi!"
  },
  AvgDialog_91727_Content_64 = {
    Text = "Sao, cậu muốn bị tôi hút khô máu một lần nữa à?"
  },
  AvgDialog_91727_Content_65 = {Text = "Uvhash!!!"},
  AvgDialog_91727_Content_66 = {
    Text = "Trong không gian chật hẹp, độc tố và máu bay lượn, chân tay va chạm, hai người không chút hình tượng đánh nhau túi bụi, không ai chịu thua."
  },
  AvgDialog_91727_Content_67 = {
    Text = "Ngay khi họ bắt đầu hành động, không biết đòn tấn công nào đã phát huy tác dụng, cánh cửa trên đầu sáng lên ánh sáng bạc yếu ớt đột nhiên chớp một cái."
  },
  AvgDialog_91727_Content_68 = {
    Text = "Chờ đã…… cái bảng cửa này vừa rồi có phải đã sáng lên một cái không?"
  },
  AvgDialog_91727_Content_69 = {
    Text = "Agrippa đột nhiên dừng tay ngẩng lên nhìn, Uvhash không kịp dừng lại đâm sầm vào, đập mạnh vào tấm cửa vẫn bất động."
  },
  AvgDialog_91727_Content_7 = {
    Text = "Nô lệ hôi hám! Đồ vô dụng! Đều là lỗi của ngươi! Bây giờ thì tốt rồi, ngay cả tôi cũng phải bị ngươi kéo theo gặp xui!"
  },
  AvgDialog_91727_Content_70 = {Text = "Hả?!"},
  AvgDialog_91727_Content_71 = {
    Text = "Agrippa đẩy Uvhash ra cản, bò lên tấm cửa nghiên cứu kỹ, bỗng thấy thứ gì đó quen thuộc trong những hoa văn lấp lánh bạc."
  },
  AvgDialog_91727_Content_72 = {
    Text = "Những đường nét này… giống như mạch điều khiển của cơ quan bạc mà ta vừa ghi chép lại?"
  },
  AvgDialog_91727_Content_73 = {
    Text = "Cái gì gà cái hươu?"
  },
  AvgDialog_91727_Content_74 = {
    Text = "Những nội dung vừa bị phạt chép lại ùa vào đầu, trước mặt những học sinh kém hơn, Kiến thức nghèo nàn của Agrippa cuối cùng cũng có cơ hội khoe khoang."
  },
  AvgDialog_91727_Content_75 = {
    Text = "Nói cũng vô ích, dù sao thì loại cơ quan này lấy bạc làm cốt lõi, vì tính chất gì gì đó của bạc, lõi của nó thường không xa vị trí của cơ quan."
  },
  AvgDialog_91727_Content_76 = {
    Text = "Và những cấu trúc cốt lõi này rất tinh vi, chắc chắn là vừa rồi đã vô tình trúng vào vị trí của cốt lõi, nên cánh cửa mới có phản ứng."
  },
  AvgDialog_91727_Content_77 = {
    Text = "Chỉ cần chúng ta tạo ra đủ rung động vào vị trí trung tâm, chúng ta có thể phá hủy cơ quan trên cánh cửa!"
  },
  AvgDialog_91727_Content_78 = {
    Text = "Nghe không hiểu, tóm lại là phải đánh thật mạnh cái thứ gì đó đúng không? Nó ở đâu?"
  },
  AvgDialog_91727_Content_79 = {
    Text = "Tôi xem nào…… Theo chức năng của cơ chế này, hướng đi của vòng lặp ở đây nên là bên này…… Không không không, bên này?"
  },
  AvgDialog_91727_Content_8 = {
    Text = "Sáng mai sẽ có người mở cái bẫy chết tiệt này, nói rằng: \"Nhìn xem chúng ta đã bắt được gì, hai thằng ngốc! Chính là các cậu, những người đã ăn cắp đồ ăn trong bếp.\""
  },
  AvgDialog_91727_Content_80 = {
    Text = "Ờ... có lẽ nó được giấu ở đây bức tường này?"
  },
  AvgDialog_91727_Content_81 = {
    Text = "Thôi, những kỳ thi này tôi chưa bao giờ qua, lần này nhất định lại sai."
  },
  AvgDialog_91727_Content_82 = {
    Text = "Agrippa buồn bã cúi đầu, điều cô ngạc nhiên là, nô lệ trước mắt không lợi dụng cơ hội cười nhạo cô, mà chỉ gật đầu nghiêm túc."
  },
  AvgDialog_91727_Content_83 = {
    Text = "Có vẻ như bạn cũng đã thay đổi nhiều ở đây."
  },
  AvgDialog_91727_Content_84 = {
    Text = "Uvhash quay lại, như thể đang đối diện với đối thủ mạnh nhất, chăm chú nhìn vào điểm mờ ảo trên tường."
  },
  AvgDialog_91727_Content_85 = {
    Text = "Giống như vị thần chiến tranh trở lại từ chiến trường xưa, những ngọn giáo nhuốm máu tụ lại xung quanh anh, phát ra ánh sáng đỏ tươi trong bóng tối."
  },
  AvgDialog_91727_Content_86 = {
    Text = "Hãy để người trong bếp này thấy sức mạnh của chiến binh mạnh nhất La Mã!"
  },
  AvgDialog_91727_Content_87 = {
    Text = "Kèm theo những tiếng cười điên dại, một đòn đánh toàn lực của chiến binh chính xác đánh vào điểm đó, trong một tiếng \"cách\" yếu ớt, cánh cửa không thể phá hủy trên đầu cuối cùng đã mờ tối đi."
  },
  AvgDialog_91727_Content_88 = {
    Text = "Ánh sáng bạc mờ nhạt vừa lóe lên đã biến mất, Agrippa ngạc nhiên ngẩng đầu, cười vui vẻ."
  },
  AvgDialog_91727_Content_89 = {
    Text = "Thành công rồi! Công nghệ mảnh bạc gì, chỉ là một cái bếp, không phải đã bị tôi chinh phục rồi sao!"
  },
  AvgDialog_91727_Content_9 = {
    Text = "Rồi tên của chúng ta sẽ được treo trên bảng thông báo, bị toàn bộ Mythag chế giễu, cười nhạo rằng chúng ta là hai con chuột ngu ngốc."
  },
  AvgDialog_91727_Content_90 = {
    Text = "Cô ấy và Uvhash nhìn vào mắt nhau, đồng loạt hừ một tiếng, cùng nhau đập mạnh cánh cửa bị lỗi bung ra."
  },
  AvgDialog_91727_Content_91 = {
    Text = "Tên nô lệ không biết cảm ơn, thức ăn ở đây lẽ ra phải do ta thưởng thức trước tiên!"
  },
  AvgDialog_91727_Content_92 = {
    Text = "Nếu không có tôi, bạn có mở được cái cửa đó không? Dĩ nhiên, ai chộp được trước thì là của người đó."
  },
  AvgDialog_91727_Content_93 = {
    Text = "Trong cuộc giằng co và xô xát, hai người đã một lần nữa đổ hết thức ăn thịt trong bếp, rồi oang oang bỏ đi."
  },
  AvgDialog_91727_Content_94 = {
    Text = "Cuối cùng, tên của họ vẫn không xuất hiện trên bảng thông báo của trường, vinh quang thuộc về Rome đã được bảo vệ vào đêm nay."
  },
  AvgDialog_91727_Content_95 = {
    Text = "Thật đáng mừng, nơi này lại một lần nữa bị sức mạnh của Rome chinh phục thành công."
  },
  AvgDialog_91727_Content_96 = {
    Text = "Chỉ có đầu bếp trưởng vào ngày hôm sau tự tin bước vào bếp, phát ra một tiếng gầm thét vang dội khắp trường."
  },
  AvgDialog_94610_Content_1 = {
    Text = "Rút lui đi, Caecus."
  },
  AvgDialog_94610_Content_2 = {
    Text = "Người phương xa, hãy thể hiện tài năng thật sự của bạn. Hãy cho tôi xem, bạn thực sự còn giấu kín những bí mật gì!"
  },
  AvgDialog_94611_Content_1 = {
    Text = "Ngài Người Giữ Gìn, tôi chỉ muốn cùng ngài múa một điệu mà thôi, tại sao lại thái quá như vậy?"
  },
  AvgDialog_94611_Content_2 = {
    Text = "Tôi không biết bạn biết gì, cũng không muốn biết……"
  },
  AvgDialog_94611_Content_3 = {
    Text = "Dù chết ở đây... Tôi nhất định sẽ báo thù cho đàn anh William!"
  },
  AvgDialog_94641_Content_1 = {
    Text = "Qua tính toán, Tay hiện tại chưa ở trong khoảng tối ưu. Lệnh đề xuất: Kích hoạt giao thức <Yellow:\"Sự diệt vong\">, thu thập Cảm hứng."
  },
  AvgDialog_94642_Content_1 = {
    Text = "Ừm ừm, còn có <Yellow:tư thế Sóng Gẩm>, có thể khiến xúc tu đánh đau hơn rất nhiều, và tất cả các đòn tấn công chủ động đều sẽ gây thêm một lần thương bổ sung cho xúc tu nữa đấy. Mau dùng tư thế Sóng Gẩm, đánh đuổi hết bọn xấu đi!"
  },
  AvgDialog_94643_Content_1 = {
    Text = "Nhấp vào biểu tượng Cõi phía trên chúng tôi là có thể chuyển đổi <Yellow:tư thế> của xúc tu. Kẻ thù này hung dữ lắm, hãy chuyển sang <Yellow:tư thế Biển Lặng> giỏi phòng thủ, bảo vệ mọi người!"
  },
  AvgDialog_94644_Content_1 = {
    Text = "Thấy cái biểu tượng tròn tròn đó chưa? Đây là <Yellow:Lò nung đỏ thẫm>, chỉ cần nhẹ nhàng nhấp vào nó, năng lượng tích lũy sẽ được chuyển hóa hoàn toàn thành Sinh lực đấy."
  },
  AvgDialog_94644_Content_2 = {
    Text = "Bây giờ……hãy dùng sự trợ giúp nhỏ bé này để chống lại những đòn tấn công đáng sợ kia nhé."
  },
  AvgDialog_94645_Content_1 = {
    Text = "<Yellow:Xúc tu> cũng giống như những người bạn đồng hành của Ô Ryta, sẽ ngày càng tăng thêm đấy. Khi không chuyển đổi tư thế, cuối vòng sẽ tự động tạo ra 1 xúc tu mới, hay lắm phải không~"
  },
  AvgDialog_94646_Content_1 = {
    Text = "Xác nhận điều kiện kích hoạt hoàn tất! Lập tức bước vào <Yellow:Vòng Siêu Chiều>, các thẻ bài trong <Yellow:Khoảng không gian siêu việt> sẽ được thu hồi lại. Theo tính toán, đây là thời điểm tốt nhất để phát động đợt tấn công liên tiếp."
  },
  AvgDialog_94653_Content_1 = {
    Text = "Giữa đêm khuya, một tiếng gõ cửa điên cuồng và hoảng hốt bỗng làm bạn tỉnh dậy."
  },
  AvgDialog_94653_Content_10 = {
    Text = "Bạn vội vàng đưa tay ra để đỡ, nhưng mồ hôi trơn trượt khiến cánh tay nóng bỏng ấy tuột khỏi tay bạn, Poluxes khụy xuống đất, vô lực tựa vào cạnh giường."
  },
  AvgDialog_94653_Content_11 = {
    Text = "Thật là không lịch sự, để bạn thấy một hình ảnh khó coi như vậy..."
  },
  AvgDialog_94653_Content_12 = {
    Text = "Mặt bạn...<Small: đỏ rực, không thể nhầm lẫn, nhất định là...>"
  },
  AvgDialog_94653_Content_13 = {
    Text = "Ân nhân, em trai tôi rốt cuộc làm sao? Từ tối nay, ngực cậu ấy như ngày một nóng lên."
  },
  AvgDialog_94653_Content_14 = {
    Text = "Boluque cũng nâng mắt từ dưới đất lên, trong nỗi đau đớn chờ đợi phán quyết của mình."
  },
  AvgDialog_94653_Content_15 = {
    Text = "Hai đôi mắt tin tưởng nhìn chằm chằm vào bạn, làm bạn một lúc không biết phải nói gì để giải thích."
  },
  AvgDialog_94653_Content_16 = {
    Text = "Ông, ừm… có thể nói là bệnh tật, có thể do cơ thể đặc biệt của Thánh Tâm mà bệnh nặng hơn."
  },
  AvgDialog_94653_Content_17 = {
    Text = "Có phải tội lỗi mà tôi đã phạm phải đã dẫn đến sự trừng phạt? Linh hồn của tôi đã không thể cứu vãn…"
  },
  AvgDialog_94653_Content_18 = {
    Text = "Boluque tự giễu cười một tiếng, ngực anh lên xuống, mồ hôi làm tóc anh dính vào da, cảm giác nóng bức khiến anh rơi vào trạng thái mong manh và bi quan."
  },
  AvgDialog_94653_Content_19 = {
    Text = "Không không không, thật ra cái này là... ờ, nói chung không phải lỗi của bạn, là do ảnh hưởng từ yếu tố bên ngoài, chỉ cần một thời gian nữa sẽ ổn thôi! Thật đấy!"
  },
  AvgDialog_94653_Content_2 = {
    Text = "Bạn nhớ về một số kỷ niệm không mấy tốt đẹp, không mở cửa ngay lập tức, mà cẩn thận đến gần tấm cửa."
  },
  AvgDialog_94653_Content_20 = {
    Text = "Bạn hứa hẹn chắc chắn, cúi xuống định nâng Polyxus dậy từ mặt đất."
  },
  AvgDialog_94653_Content_21 = {
    Text = "Sự an ủi tử tế như vậy, linh hồn của bạn vẫn sáng chói như vậy, thậm chí có một hơi... ngọt ngào? Khiến người ta muốn..."
  },
  AvgDialog_94653_Content_22 = {
    Text = "Khi tiếp xúc cơ thể, hơi thở của Pauluk phả vào da bạn, miệng anh ta mở ra, như thể muốn liếm vào cổ họng đang cuộn của bạn."
  },
  AvgDialog_94653_Content_23 = {
    Text = "Không, sao tôi có thể có suy nghĩ bất kính như vậy... chỉ khi ở bên cạnh bạn, nỗi đau của tôi như được giảm bớt đôi chút..."
  },
  AvgDialog_94653_Content_24 = {
    Text = "Boluque ngay lập tức quay mặt đi một cách kiềm chế, anh nhíu mày thì thầm, dường như đã nhận ra điều gì đó."
  },
  AvgDialog_94653_Content_25 = {
    Text = "Ân nhân, thật sự không có cách nào chữa khỏi cho cậu ấy sao?"
  },
  AvgDialog_94653_Content_26 = {
    Text = "Tôi……thôi được, cũng được, nhưng trong khoảng thời gian này không được có ai trong phòng, Castor, tối nay anh cứ nghỉ trong phòng tôi đi."
  },
  AvgDialog_94653_Content_27 = {
    Text = "Tôi đã hiểu, vậy xin giao phó cho ân nhân."
  },
  AvgDialog_94653_Content_28 = {
    Text = "Trong cái gật đầu nhẹ nhàng của Pollux, Castor cuối cùng lo lắng đóng cửa phòng lại."
  },
  AvgDialog_94653_Content_29 = {
    Text = "Có phải có phương pháp điều trị tàn nhẫn nào khiến Castor phải rời đi không? Xin hãy yên tâm mà hành động, tôi có thể chịu đựng bất kỳ cơn đau nào."
  },
  AvgDialog_94653_Content_3 = {Text = "Ai?"},
  AvgDialog_94653_Content_30 = {
    Text = "Không, tôi đâu phải Juliette, bạn không cần phải chịu đau đớn nữa, điều này chỉ... sẽ khiến bạn... có chút xấu hổ."
  },
  AvgDialog_94653_Content_31 = {
    Text = "Vậy, tôi nên làm gì đây?"
  },
  AvgDialog_94653_Content_32 = {
    Text = "Trong câu trả lời của bạn, Polyxus đã tìm thấy câu trả lời mà anh ta muốn, anh ta hiểu rằng khát vọng trong lòng mình đã được bạn biết đến và hứa hẹn."
  },
  AvgDialog_94653_Content_33 = {
    Text = "Ông nắm lấy tay của bạn, áp vào má mình, và trong sự đồng ý của bạn, từ từ tiến sát lại, đặt trán nóng bỏng lên trán bạn."
  },
  AvgDialog_94653_Content_34 = {
    Text = "Đôi mắt thất thần đó nhìn chằm chằm vào bạn, như tín đồ chân thành ngắm nhìn Thượng Đế của mình."
  },
  AvgDialog_94653_Content_35 = {
    Text = "Xin hãy hướng dẫn tôi, ánh đèn của tôi…"
  },
  AvgDialog_94653_Content_4 = {
    Text = "Ân nhân, xin hãy xem em trai tôi, cậu ấy, cậu ấy..."
  },
  AvgDialog_94653_Content_5 = {
    Text = "Boluque? Anh ấy gặp chuyện gì vậy?"
  },
  AvgDialog_94653_Content_6 = {
    Text = "Bạn nhanh chóng theo sau Castor đến phòng, thấy một hình bóng đang rúc mình trên một trong hai chiếc giường, phát ra những tiếng rên rĩ, ga trải giường và chăn đều bị vặn biến dạng trong sự tra tấn kéo dài."
  },
  AvgDialog_94653_Content_7 = {
    Text = "Nghe thấy tiếng các bạn mở cửa không, Polycus từ cơn mơ tỉnh dậy, vất vả đứng dậy từ giường."
  },
  AvgDialog_94653_Content_8 = {
    Text = "Ha...là ngài đã đến..."
  },
  AvgDialog_94653_Content_9 = {
    Text = "Hành động đơn giản như vậy cũng khiến Polukse khó nhọc thở dốc, hình dáng của anh ta lảo đảo như sắp ngã."
  },
  AvgDialog_95381_Content_1 = {
    Text = "Đêm đã khuya, bạn nằm trên giường, nhìn đồng hồ tích tắc trôi qua, lâm vào trạng thái mơ màng không làm gì."
  },
  AvgDialog_95381_Content_10 = {
    Text = "Bùng bùng bùng! Bùng bùng bùng!"
  },
  AvgDialog_95381_Content_11 = {
    Text = "Tới rồi tới rồi... Kai, Katie Kula?!"
  },
  AvgDialog_95381_Content_12 = {
    Text = "Người đứng trước mặt bạn là Katie Gula say rượu, cô ấy đẩy mở cánh cửa phòng bạn đang nửa mở, rồi nhanh chóng khóa lại."
  },
  AvgDialog_95381_Content_13 = {
    Text = "K-Katie Gula? Bạn có ổn không?"
  },
  AvgDialog_95381_Content_14 = {
    Text = "Tình trạng của Katie Gula dường như không ổn, toàn thân cô tỏa ra một loại khát vọng được gọi là bản năng nguyên thủy nhất của sinh vật."
  },
  AvgDialog_95381_Content_15 = {
    Text = "Giống như bị một con thú mạnh mẽ chăm chú nhìn chằm chằm, trong lòng bạn dâng lên cảm giác nguy hiểm mãnh liệt, cảnh báo bạn nhanh chóng rời khỏi đây."
  },
  AvgDialog_95381_Content_16 = {
    Text = "Còn tôi ư? Tôi đương nhiên rất tốt, không có vấn đề gì."
  },
  AvgDialog_95381_Content_17 = {
    Text = "Kaitigula vừa nới lại dây buộc tóc phía sau đầu, vừa bước đi chậm rãi về phía bạn trong đôi ủng cao. Bạn chỉ còn cách lùi lại không ngừng, cố gắng giữ khoảng cách an toàn."
  },
  AvgDialog_95381_Content_18 = {
    Text = "Ừm, tôi đi lấy cho bạn một ít thuốc giải rượu nhé?"
  },
  AvgDialog_95381_Content_19 = {
    Text = "Bạn đã định dùng lý do này để rời khỏi đây, nhưng không ngờ Katie Gula nhanh chóng nắm lấy tay phải của bạn, một cách cuồng loạn, thô bạo và vô lễ."
  },
  AvgDialog_95381_Content_2 = {
    Text = "Nếu là ngày bình thường, giờ này bạn đã bỏ bộ quần áo đầy bụi bẩn, đưa thân thể mệt mỏi vào giấc ngủ."
  },
  AvgDialog_95381_Content_20 = {
    Text = "Không cần đâu, nhóc nhỏ, có một số việc, quá tỉnh táo lại trở nên tẻ nhạt, phải không?"
  },
  AvgDialog_95381_Content_21 = {
    Text = "Không còn cách nào khác, bạn buộc phải lùi lại, nhưng không gian dành cho bạn có vẻ không còn nhiều."
  },
  AvgDialog_95381_Content_22 = {
    Text = "Biết không, nhóc, tôi luôn có một nỗi tiếc nuối, đó là lần trước không uống được rượu của bạn."
  },
  AvgDialog_95381_Content_23 = {
    Text = "Nhưng lần này... sẽ không như vậy."
  },
  AvgDialog_95381_Content_24 = {
    Text = "Ái chao? Bạn làm sao nhớ được lúc đó..."
  },
  AvgDialog_95381_Content_25 = {
    Text = "Dù ký ức có mờ nhạt, nhưng nó vẫn tồn tại."
  },
  AvgDialog_95381_Content_26 = {
    Text = "Đừng quên tôi là Katie Gula, sự không bao giờ quên, ừ, ít nhất là khi cần thì là sự không bao giờ quên."
  },
  AvgDialog_95381_Content_27 = {
    Text = "Kaitigula đẩy bạn đến bên giường, tùy tiện tháo áo khoác, theo đó cúi người đè lên bạn, những sợi tóc rơi xuống lướt qua làn da bạn."
  },
  AvgDialog_95381_Content_28 = {
    Text = "Bạn mở mắt, bối rối nằm trên giường, mặc cho hơi thở mằn mặn hòa trộn mùi rượu ngọt ngào vương vấn trên gò má."
  },
  AvgDialog_95381_Content_29 = {
    Text = "Ánh mắt của Katie Gula chứa đựng sự châm chọc, khuôn mặt ngày càng gần bạn."
  },
  AvgDialog_95381_Content_3 = {
    Text = "Nhưng nhờ sự kiện, sự bận rộn và mệt mỏi đã không làm phiền bạn trong ngày này."
  },
  AvgDialog_95381_Content_30 = {
    Text = "Đầu mũi của cô chạm vào đầu mũi bạn, nhẹ nhàng ngửi hương thơm trong hơi thở bạn."
  },
  AvgDialog_95381_Content_31 = {
    Text = "Đôi môi ấm nóng đó áp vào môi bạn, lơ lửng giữa chừng, phát ra một tiếng cười nhẹ. Rồi cô bắt đầu ma sát đôi môi bạn qua khe hở nhỏ bé này."
  },
  AvgDialog_95381_Content_32 = {
    Text = "Lần này hãy để tôi, thưởng thức hương vị độc quyền của bạn nhé..."
  },
  AvgDialog_95381_Content_33 = {
    Text = "Cô bé đáng yêu."
  },
  AvgDialog_95381_Content_4 = {
    Text = "Vì vậy bạn vẫn có năng lượng để cầm cuốn tiểu thuyết đã để ở đầu giường lâu nay, \"nghiên cứu\" chút về làn sóng văn học hiện tại."
  },
  AvgDialog_95381_Content_5 = {
    Text = "Bùng bùng bùng! Bùng bùng bùng!"
  },
  AvgDialog_95381_Content_6 = {
    Text = "Đột nhiên, một tiếng gõ cửa dồn dập cắt ngang kế hoạch đọc sách của bạn."
  },
  AvgDialog_95381_Content_7 = {
    Text = "Đến rồi! Chờ một chút!"
  },
  AvgDialog_95381_Content_8 = {
    Text = "Bạn để lại đánh dấu trong cuốn sách chưa lấy ra là \"Súng lục và mật ong\", rời khỏi chiếc giường ấm cúng, hướng về cửa ra."
  },
  AvgDialog_95381_Content_9 = {
    Text = "(Muộn như vậy, không biết là ai nhỉ?)"
  },
  AvgDialog_95473_Content_1 = {
    Text = "Kẻ đứng sau âm mưu"
  },
  AvgDialog_95473_Content_10 = {
    Text = "Chém gió còn thích hơn những thứ trước kia nhiều."
  },
  AvgDialog_95473_Content_11 = {
    Text = "Giảm đi một nửa, địa điểm tiếp theo… hãy chọn nơi này nhé."
  },
  AvgDialog_95473_Content_12 = {
    Text = "……Lần thứ 8 kích thích, kẻ thù giảm còn 1/14"
  },
  AvgDialog_95473_Content_13 = {
    Text = "……Lần thứ 13 kích thích, kẻ thù giảm còn 1/25"
  },
  AvgDialog_95473_Content_14 = {
    Text = "……Lần thứ 27 kích thích, kẻ thù giảm còn 1/138"
  },
  AvgDialog_95473_Content_15 = {
    Text = "Cuối cùng đã đến lần nào."
  },
  AvgDialog_95473_Content_16 = {
    Text = "Kaitigura dừng lại, đếm số kẻ thù còn lại."
  },
  AvgDialog_95473_Content_17 = {
    Text = "Một, hai, ba... vẫn còn năm con."
  },
  AvgDialog_95473_Content_18 = {
    Text = "Đến đây đi, Gerald, đã chạy trốn lâu như vậy..."
  },
  AvgDialog_95473_Content_19 = {
    Text = "Cũng đã đến lúc phát tiết một chút rồi!!"
  },
  AvgDialog_95473_Content_2 = {
    Text = "Hống——"
  },
  AvgDialog_95473_Content_20 = {
    Text = "<Shake:<Big:Chết đi! Quái vật bẩn thỉu!>>"
  },
  AvgDialog_95473_Content_21 = {
    Text = "<Shake:Gầm！！！！>"
  },
  AvgDialog_95473_Content_22 = {
    Text = "Rầm rầm rầm——"
  },
  AvgDialog_95473_Content_23 = {
    Text = "Phú——Phú——"
  },
  AvgDialog_95473_Content_24 = {
    Text = "Cheng——Cheng——"
  },
  AvgDialog_95473_Content_25 = {
    Text = "Cạch——"
  },
  AvgDialog_95473_Content_26 = {Text = "Phú——"},
  AvgDialog_95473_Content_27 = {
    Text = "Aaa aaa aaa aaa aaa aaa——"
  },
  AvgDialog_95473_Content_28 = {Text = "Thụp."},
  AvgDialog_95473_Content_29 = {
    Text = "Thật khó nghe, Gerard, còn anh thế nào?"
  },
  AvgDialog_95473_Content_3 = {
    Text = "Cạch! Cạch! Cạch!"
  },
  AvgDialog_95473_Content_30 = {
    Text = "Hô… hô… đã giải quyết xong."
  },
  AvgDialog_95473_Content_31 = {
    Text = "Rất tốt, nhưng trước khi gặp lại họ, chúng ta sẽ đi đến một nơi trước."
  },
  AvgDialog_95473_Content_32 = {Text = "Đâu?"},
  AvgDialog_95473_Content_33 = {
    Text = "Ngôi đền đó, trung tâm của nghi thức, nếu tôi không đoán sai thì đúng là vậy."
  },
  AvgDialog_95473_Content_34 = {
    Text = "Có người đang chờ chúng ta."
  },
  AvgDialog_95473_Content_35 = {
    Text = "Bên trong đền thờ, máu và xác chết đã biến mất không còn dấu vết, như thể chưa từng có gì xảy ra."
  },
  AvgDialog_95473_Content_36 = {
    Text = "Aiya, đã quay trở lại, không thể lặng lẽ đi sao?"
  },
  AvgDialog_95473_Content_37 = {
    Text = "Như vậy tôi có thể để các bạn khi sắp thấy ánh sáng..."
  },
  AvgDialog_95473_Content_38 = {
    Text = "Trải nghiệm cảnh tượng rơi vào địa ngục đó."
  },
  AvgDialog_95473_Content_39 = {Text = "(!!!)"},
  AvgDialog_95473_Content_4 = {
    Text = "Không sao, vứt bỏ một số thứ, như kế hoạch đã định."
  },
  AvgDialog_95473_Content_40 = {
    Text = "Một bóng hình đã quen thuộc xuất hiện trước mặt, bộ lễ phục biểu tượng, nụ cười giả tạo và bông hồng đỏ nở rộ trong tay."
  },
  AvgDialog_95473_Content_41 = {
    Text = "(Sao lại thấy được anh ấy ở đây...)"
  },
  AvgDialog_95473_Content_42 = {
    Text = "Đã lâu không gặp, xin cho phép tôi giới thiệu bản thân một cách chính thức với bà Ketigula."
  },
  AvgDialog_95473_Content_43 = {
    Text = "Bạn có thể gọi tôi là——"
  },
  AvgDialog_95473_Content_45 = {
    Text = "Không biết cái kết này, có khiến quý cô Kettigula hài lòng không nhỉ?"
  },
  AvgDialog_95473_Content_46 = {
    Text = "Tôi đến để đánh giá sao?"
  },
  AvgDialog_95473_Content_47 = {
    Text = "Caligula cười, kèm theo ba phần khinh miệt."
  },
  AvgDialog_95473_Content_48 = {
    Text = "Câu chuyện này thật nhàm chán, chẳng có gì thú vị cả."
  },
  AvgDialog_95473_Content_49 = {
    Text = "Giống như một ông lão lạc hậu không theo kịp thời đại, chỉ biết bắt chước những tác phẩm đã từng của mình rồi tự mãn, lớn tiếng ca ngợi những thứ đã cũ kỹ."
  },
  AvgDialog_95473_Content_5 = {
    Text = "Đến đây, quái vật, đối thủ của các người ở đây!"
  },
  AvgDialog_95473_Content_50 = {
    Text = "Thực ra, anh ta đã mất đi cảm hứng và sáng tạo từ lâu, chỉ có thể như một con chó vô gia cư, chìm đắm trong những ảo tưởng của chính mình."
  },
  AvgDialog_95473_Content_51 = {
    Text = "Thú vị, đây là lần đầu tiên tôi bị người ta nói thành chó nhà thất bại."
  },
  AvgDialog_95473_Content_52 = {
    Text = "N không tức giận, mà còn hỏi ý kiến của Kaitigura."
  },
  AvgDialog_95473_Content_53 = {
    Text = "Nói cho tôi biết, trong màn kịch này có chỗ nào lộ ra kẽ hở?"
  },
  AvgDialog_95473_Content_54 = {
    Text = "Caligula xoay súng trong tay, ánh mắt đảo một vòng khắp nơi, cuối cùng dừng lại trên người N."
  },
  AvgDialog_95473_Content_55 = {
    Text = "Quá chính xác, hiểu không."
  },
  AvgDialog_95473_Content_56 = {
    Text = "Con đường tối tăm, cánh cổng... ngay cả độ sâu của hành lang cũng không sai một chút. Khi tôi bước vào sảnh và quét mắt nhìn, tôi đã hiểu ra thực tế này."
  },
  AvgDialog_95473_Content_57 = {
    Text = "Đây là một màn kịch tự biên tự diễn, chỉ có vậy thôi."
  },
  AvgDialog_95473_Content_58 = {
    Text = "Thì ra là như vậy! Tôi đã hiểu rồi! Đừng lo, lần sau tôi sẽ đãi bạn với kịch bản chân thực hơn."
  },
  AvgDialog_95473_Content_59 = {
    Text = "Ah! Gần như quên mất!"
  },
  AvgDialog_95473_Content_6 = {Text = "Gào!!!"},
  AvgDialog_95473_Content_60 = {
    Text = "N kịch tính vỗ đầu, diễn tả như thể mình vừa nhớ ra điều gì đó."
  },
  AvgDialog_95473_Content_61 = {
    Text = "Ngài đã—không còn cơ hội nào nữa."
  },
  AvgDialog_95473_Content_62 = {
    Text = "Kaitigura cười lạnh lùng, lờ đi những lời nói đầy ác ý của đối phương, đưa tay chỉ vào N."
  },
  AvgDialog_95473_Content_63 = {
    Text = "Tôi có một câu hỏi, tại sao bạn lại tự biên tự diễn vở kịch này."
  },
  AvgDialog_95473_Content_64 = {
    Text = "Tôi không thấy bất kỳ logic nào trong hành động của bạn, bạn rốt cuộc muốn lấy gì từ tôi?"
  },
  AvgDialog_95473_Content_65 = {
    Text = "Câu hỏi của bà thật kỳ lạ, bà Caligula."
  },
  AvgDialog_95473_Content_66 = {
    Text = "Tại sao tôi nhất định phải... có được điều gì đó?"
  },
  AvgDialog_95473_Content_67 = {
    Text = "Không thể chỉ đơn giản là muốn xem biểu cảm của con người trong tình huống này sao?"
  },
  AvgDialog_95473_Content_68 = {
    Text = "Ồ tất nhiên, đừng hiểu lầm, tôi chỉ đưa ra ví dụ, thực ra tôi không có ý nghĩ như vậy."
  },
  AvgDialog_95473_Content_69 = {
    Text = "……Ý bạn là, bạn chỉ đơn giản nghĩ rằng làm như vậy rất thú vị?"
  },
  AvgDialog_95473_Content_7 = {
    Text = "Hống——"
  },
  AvgDialog_95473_Content_70 = {
    Text = "Ồ! Câu trả lời này khá hay, tôi thích câu trả lời này."
  },
  AvgDialog_95473_Content_71 = {
    Text = "Mặc dù không chính xác, nhưng đúng là rất gần."
  },
  AvgDialog_95473_Content_72 = {
    Text = "Cứ tiếp tục đoán xem? Biết đâu lại đoán đúng thì sao?"
  },
  AvgDialog_95473_Content_73 = {
    Text = "……Ý bạn là, Theodore và Amy, chỉ vì một phút bốc đồng của bạn đã mất mạng một cách vô ích?"
  },
  AvgDialog_95473_Content_74 = {
    Text = "Xin đừng nói như vậy, thưa quý cô Katiegula."
  },
  AvgDialog_95473_Content_75 = {
    Text = "Họ trong tay có mạng sống, làm sao có thể nói là bỏ đi vô ích?"
  },
  AvgDialog_95473_Content_76 = {
    Text = "Bọn bạo lực, thủ lĩnh, tà giáo bị họ giết, mạng sống của họ không phải là mạng sống sao?"
  },
  AvgDialog_95473_Content_77 = {
    Text = "Và bạn cũng đã nói với họ từ sớm rằng, nếu họ theo bạn, thì hãy chuẩn bị sẵn sàng cho việc bị giết phải không?"
  },
  AvgDialog_95473_Content_78 = {
    Text = "Thực tế đó là những gì tôi đã nói, nhưng nếu bạn đã biết điều này, chắc bạn cũng đã biết câu tiếp theo của tôi rồi chứ."
  },
  AvgDialog_95473_Content_79 = {
    Text = "Kaitigura nở nụ cười cực kỳ nguy hiểm và điên loạn, ánh mắt lạnh lẽo đầy sát khí."
