  AvgDialog_95473_Content_8 = {
    Text = "Phú——Phú——"
  },
  AvgDialog_95473_Content_80 = {
    Text = "\"Nhưng khi các bạn bị giết, tôi sẽ tự mình trả thù cho các bạn.\""
