  AvgDialog_95474_Content_1 = {
    Text = "Mặt trời đen"
  },
  AvgDialog_95474_Content_10 = {
    Text = "Caligula không cố ép, cô cũng hiểu rõ tình trạng sức khỏe của mình hiện tại tệ như thế nào."
