  AvgDialog_95474_Content_100 = {Text = "Ừm……"},
  AvgDialog_95474_Content_101 = {
    Text = "Mặt trời đen treo lơ lửng, màu đen và trắng nguyên thủy tự do tô vẽ thế giới."
  },
  AvgDialog_95474_Content_102 = {
    Text = "Thế giới đang khóc lóc, đang cười, liên tục biến dạng trong sự hỗn loạn vui vẻ."
  },
  AvgDialog_95474_Content_103 = {
    Text = "Gạch đá hóa thành cát sỏi, lễ vật tan thành cành khô, những bức điêu khắc vĩ đại không thể quan sát và có mặt ở mọi nơi..."
