  AvgDialog_95474_Content_105 = {
    Text = "……………"
  },
  AvgDialog_95474_Content_106 = {
    Text = "Cát vàng bay lên thay thế cho đen trắng méo mó, nhưng không có một âm thanh nào phát ra."
  },
  AvgDialog_95474_Content_107 = {
    Text = "Giống như khi các bạn đến, vùng sa mạc này vẫn yên tĩnh vô cùng."
  },
  AvgDialog_95474_Content_108 = {
    Text = "Nó như một người khổng lồ mở mắt, lặng lẽ quan sát mọi thứ ở đây."
  },
  AvgDialog_95474_Content_109 = {
    Text = "Nó không muốn gây ra bất kỳ sự hỗn loạn hay ồn ào nào, nó chỉ đứng đây, bình thản kể lại sự tĩnh lặng và tàn lụi của cái chết."
  },
  AvgDialog_95474_Content_11 = {
    Text = "Nếu là tình huống bình thường, với sức mạnh mà đối phương thể hiện, đã từ lâu tiêu tan trong mưa đạn rồi."
  },
  AvgDialog_95474_Content_110 = {
    Text = "Mặt trời đen vẫn cao trên trời, những hạt tối đen xoay quanh như nụ cười nâng lên của N."
  },
  AvgDialog_95474_Content_111 = {
    Text = "Đến đây, trò chơi bắt đầu rồi."
  },
  AvgDialog_95474_Content_112 = {
    Text = "Giọng nói của N vang lên từ bốn phía, bạn không thể phân biệt hắn ở đâu, như thể cả thế giới đều là hình hài của hắn."
  },
  AvgDialog_95474_Content_113 = {
    Text = "Mỗi hạt cát, mỗi giọt nước, mỗi làn gió đều đang lan tỏa ác ý vô biên đến bạn."
  },
  AvgDialog_95474_Content_114 = {
    Text = "Các vị, hãy tìm cách làm vui lòng tôi đi!"
  },
  AvgDialog_95474_Content_115 = {
    Text = "Tôi sẽ ban thưởng cho người làm hài lòng tôi, đến lúc đó bạn sẽ vượt ra khỏi mọi phiền não, cùng tôi tận hưởng niềm vui vô tận này!"
