  AvgDialog_95474_Content_118 = {
    Text = "Tiếng cười điên cuồng của N vang vọng trong đầu bạn, nỗi đau đớn từ cú sốc tinh thần khiến bạn đau đầu không chịu nổi."
  },
  AvgDialog_95474_Content_119 = {
    Text = "Không chỉ mình bạn đâu, Lucius, Tika, Ismael, Theodore..."
