  AvgDialog_95474_Content_120 = {
    Text = "Tất cả mọi người đều ôm đầu, cố gắng chịu đựng cơn đau như thể linh hồn bị xé nát."
  },
  AvgDialog_95474_Content_121 = {
    Text = "Đủ rồi..."
  },
  AvgDialog_95474_Content_122 = {
