  },
  AvgDialog_95474_Content_123 = {
    Text = "Tôi nói...... đủ rồi!"
  },
  AvgDialog_95474_Content_124 = {Text = "!"},
  AvgDialog_95474_Content_125 = {
    Text = "Lời quát nạt của Caetigula xua tan những tiếng cười loạn ngẫu trong đầu bạn, bạn chưa từng cảm thấy thế giới yên tĩnh đẹp đẽ như vậy."
