  AvgDialog_95474_Content_126 = {
    Text = "Bạn nói trò chơi này, tôi đã chấp nhận."
  },
  AvgDialog_95474_Content_127 = {
    Text = "Mặc dù cố gắng giữ vững tinh thần, nhưng nhìn thấy Caligula vẫn giữ được nụ cười đầy tự tin, bạn không khỏi thở phào nhẹ nhõm."
  },
  AvgDialog_95474_Content_128 = {
