  },
  AvgDialog_95474_Content_129 = {
    Text = "Tôi sẽ thắng trò chơi này, rồi đưa mọi người trở về."
  },
  AvgDialog_95474_Content_13 = {
    Text = "Còn nhớ những con chuột chỉ có thể trốn trong cống không?"
