  AvgDialog_95474_Content_130 = {
    Text = "Tới lúc đó……chúng ta sẽ làm sạch mọi mối hận mới cũ……"
  },
  AvgDialog_95474_Content_14 = {
    Text = "Nếu họ may mắn, bây giờ có lẽ họ đã trốn thoát."
