  AvgDialog_95474_Content_15 = {
    Text = "Đương nhiên, tất cả đều nhờ vào quý cô Katie Gula của chúng ta, không tiếc để bản thân trở nên tồi tệ cũng để chặn tôi lại."
  },
  AvgDialog_95474_Content_16 = {
    Text = "Tiếng bước chân thấp thoáng của N ngày càng gần, như một tảng đá khổng lồ từ từ đè nặng lên tâm trí."
  },
  AvgDialog_95474_Content_17 = {
