  AvgDialog_95474_Content_21 = {
    Text = "Hahaha, đúng rồi, tôi thực sự hèn hạ và gian trá, nhưng mà, vậy thì sao?"
  },
  AvgDialog_95474_Content_22 = {
    Text = "Thật đáng tiếc, thật đáng tiếc, quý cô Katigula vĩ đại của chúng ta sắp chết trong tay một kẻ ti tiện như tôi đây~"
  },
  AvgDialog_95474_Content_23 = {
    Text = "Tôi sẽ không để bạn tổn thương chị cả."
