  AvgDialog_95474_Content_25 = {
    Text = "Đạn dược còn lại không nhiều, chiến đấu cận chiến của bạn không giỏi, mà lần trốn chạy vừa rồi đã làm tốn hết sức lực."
  },
  AvgDialog_95474_Content_26 = {
