  AvgDialog_95474_Content_32 = {Text = "!?"},
  AvgDialog_95474_Content_33 = {Text = "Cái gì?"},
  AvgDialog_95474_Content_34 = {Text = "……Ồ?"},
  AvgDialog_95474_Content_35 = {
    Text = "N nhìn vào lỗ hổng trên bụng, đó là dấu vết của việc bị đạn lớn bắn thẳng vào. Bên trong hiện ra là tổ chức người thật sự, không phải là khí màu đen."
