  AvgDialog_95474_Content_77 = {
    Text = "Thi thể của N đứng lên bằng cách hoàn toàn trái ngược với sinh lý học của con người, với các chi gấp ngược đuổi quanh vài vòng trước khi quay về vị trí liên kết."
