  AvgDialog_95476_Content_48 = {
    Text = "Đi từ từ nhé, tôi sẽ nghỉ một chút!"
  },
  AvgDialog_95476_Content_49 = {
    Text = "Không có thời gian trả lời Lucius, bạn đưa tay ra hiệu cho anh ấy biết mình đã biết."
  },
  AvgDialog_95476_Content_5 = {
    Text = "Cảm giác từ vai khiến bạn nhanh chóng rời khỏi giấc ngủ nửa tỉnh nửa mê, bạn phản xạ đưa tay tìm kiếm vũ khí có sẵn."
  },
  AvgDialog_95476_Content_50 = {
    Text = "Chị cả! Đã sửa xong, bạn có muốn xem không?"
  },
  AvgDialog_95476_Content_51 = {
    Text = "Bạn vào một căn lều giống hệt như vậy, Katie Gula đang yên lặng kiểm tra bản đồ."
  },
  AvgDialog_95476_Content_52 = {
    Text = "Nhanh hơn so với dự đoán, lát nữa tôi sẽ đi xem."
