  AvgDialog_95476_Content_54 = {
    Text = "Katie Gula nhìn vào vật bạn chỉ tay, liền đưa nó cho bạn."
  },
  AvgDialog_95476_Content_55 = {
    Text = "Bạn có muốn xem mục tiêu và cấu trúc nội bộ của chúng tôi vào tối nay không?"
  },
  AvgDialog_95476_Content_56 = {
    Text = "Bạn lướt qua một cái nhìn, cái tên trên đó ngay lập tức thu hút sự chú ý của bạn."
  },
  AvgDialog_95476_Content_57 = {
    Text = "(Giáo hội đèn... tại sao lại có giáo hội đèn ở đây?)"
  },
  AvgDialog_95476_Content_58 = {
    Text = "(Địa điểm chúng ta đến tối nay có liên quan đến nhà thờ ánh sáng không? Có một cảm giác không tốt...)"
  },
  AvgDialog_95476_Content_59 = {
    Text = "Ừ? Sao vậy?"
  },
  AvgDialog_95476_Content_6 = {
    Text = "Này này này! Gerald, bạn đang làm gì vậy!"
  },
  AvgDialog_95476_Content_60 = {
    Text = "Khi thấy bạn có phần ngẩn người, Katie nhìn bạn với vẻ nghi ngờ."
