  AvgDialog_95476_Content_64 = {
    Text = "Không, chỉ là cảm thấy có chút âm u... và chị lớn, liệu lần hành động này có quá thuận lợi không."
  },
  AvgDialog_95476_Content_65 = {
    Text = "Ngày hôm sau vụ sát hại Theodor và Amy, chị cả, bạn đã nhận được thông tin từ phía đối phương."
  },
  AvgDialog_95476_Content_66 = {
    Text = "Và trong ba ngày chúng tôi xuất phát, không chỉ thông tin không có vấn đề gì, mà suốt đường đi cũng thông suốt, tôi lo..."
