  AvgDialog_95476_Content_69 = {
    Text = "Chưa kịp nói hết lời, Katycula đứng dậy, nhẹ nhàng vỗ vai bạn."
  },
  AvgDialog_95476_Content_7 = {
    Text = "Quay một vòng quanh, bạn nhận ra nơi này hoàn toàn khác xa với ký ức của mình."
