  AvgDialog_95476_Content_74 = {
    Text = "Chỉ cần thỏa hiệp một lần, mấy gã khác sẽ lao vào như những con linh cẩu ngửi thấy mùi máu."
  },
  AvgDialog_95476_Content_75 = {
