  AvgDialog_95476_Content_77 = {
    Text = "……Tôi hiểu rồi."
  },
  AvgDialog_95476_Content_78 = {
    Text = "Thấy bạn đầy lo lắng và bất an, Katie nhẹ nhàng mỉm cười, đập mạnh vào bạn một cái."
  },
  AvgDialog_95476_Content_79 = {Text = "Sợ!"},
  AvgDialog_95476_Content_8 = {
    Text = "Nếu trí nhớ của bạn chưa bị ai đó can thiệp, thì 30 phút trước bạn còn ở trước bàn làm việc nhỏ nhắn xinh xắn của mình, xử lý những báo cáo kỳ quái."
