  AvgDialog_95476_Content_80 = {
    Text = "Thư giãn chút đi, đừng quá căng thẳng."
  },
  AvgDialog_95476_Content_81 = {
    Text = "Trước đây cuộc chiến hỗn loạn ở Katars, Bi kịch tay áo, lần nào cũng không nguy hiểm hơn cái này? Chúng ta không phải vẫn vượt qua sao?"
