  AvgDialog_95476_Content_83 = {
    Text = "Nhìn vào ánh mắt của Katie, bạn vội vã xua tay."
  },
  AvgDialog_95476_Content_84 = {
    Text = "Sao có thể như vậy! Làm sao tôi có thể bỏ chạy giữa chừng!"
  },
  AvgDialog_95476_Content_85 = {
    Text = "Được thôi, đây mới là điều tốt! Đừng nghĩ quá nhiều, có tôi ở đây, mọi người chắc chắn sẽ không sao."
