  AvgDialog_95476_Content_86 = {
    Text = "Dù ta đã thất hứa rồi……"
  },
  AvgDialog_95476_Content_87 = {
    Text = "Nhưng những người còn lại, tôi chắc chắn... sẽ mang về đầy đủ."
