  AvgDialog_95476_Content_88 = {
    Text = "Chị cả..."
  },
  AvgDialog_95476_Content_89 = {
    Text = "Không khí hiện trường đột nhiên trở nên nặng nề, nỗi buồn mất đi đồng đội lan rộng trong trái tim bạn."
  },
  AvgDialog_95476_Content_9 = {
    Text = "Chứ không phải ăn cát trong cái lều không biết ở đâu ấy."
  },
  AvgDialog_95476_Content_90 = {
    Text = "Chị cả nói đúng! Chỉ cần nghe theo chị, chắc chắn không có vấn đề gì!"
  },
  AvgDialog_95476_Content_91 = {
    Text = "Để có thể giúp Katyura thoát khỏi cảm giác tự trách này, bạn đã cưỡng ép nở một nụ cười, cố gắng làm cho bầu không khí trở lại sôi động."
  },
  AvgDialog_95476_Content_92 = {
    Text = "Thôi không nói nữa, nghỉ ngơi trước đã."
