  AvgDialog_95476_Content_93 = {
    Text = "Rất tốt, vậy tôi sẽ không quấy rầy chị nữa."
  },
  AvgDialog_95476_Content_94 = {
    Text = "Bạn lợi dụng cơ hội rời khỏi nơi ở của Katioula, bên trong lều lại trở về với sự tĩnh lặng."
  },
  AvgDialog_95476_Content_95 = {
    Text = "Rủi ro à……Gerard nói đúng, hành động lần này quá thuận lợi…"
  },
  AvgDialog_95476_Content_96 = {
    Text = "……Đây là toàn bộ thông tin mà tôi biết, chắc hẳn ngài đã hiểu tình hình rồi chứ?"
