  AvgDialog_95476_Content_97 = {
    Text = "Ý bạn là, có một nhóm người gọi là\"Nhà thờ ánh sáng đền thờ\"đã giết người của tôi chỉ vì một thứ nhỏ bé? Khiến người của tôi phải chết?"
