  AvgDialog_95476_Content_98 = {
    Text = "Tất nhiên, có thể bạn không hiểu họ đủ, nhưng dưới bất kỳ góc độ nào, họ đều được coi là một băng đảng thú vật đã thực hiện nhiều chuyện xấu xa."
