  AvgDialog_95477_Content_12 = {
    Text = "Caetigula bắn một phát vào đống xương trắng bên cạnh, viên đạn bật ra khỏi bộ xương thối rữa mà không để lại dấu vết nào."
  },
  AvgDialog_95477_Content_13 = {
    Text = "(Tài nguyên trên người mọi người không còn nhiều, phải nhanh chóng tìm nguồn nước và nơi ở có thể sử dụng.)"
  },
  AvgDialog_95477_Content_14 = {
    Text = "(Tối thiểu phải tìm một chỗ có thể tránh mặt trời để nghỉ ngơi một chút.)"
