  AvgDialog_95477_Content_44 = {
    Text = "Giọng của Caligula lộ vẻ đau buồn và quyết tâm, ngón cái bên phải cô chậm rãi đẩy đầu búa."
  },
  AvgDialog_95477_Content_45 = {
    Text = "Nếu bạn làm như vậy với tôi, thì tôi có thể tha cho bạn một lần."
  },
  AvgDialog_95477_Content_46 = {
    Text = "Nhưng bạn nên biết rằng, điều tôi không thể tha thứ nhất là, bạn cố gắng để máu của người quan trọng nhất tôi dính lên đầu dao."
  },
  AvgDialog_95477_Content_47 = {
    Text = "Xin lỗi, Theodore, mặc dù cuộc tái ngộ thật ngắn ngủi."
