  AvgDialog_95477_Content_54 = {
    Text = "Tôi không có hứng thú với con rối do bạn nặn ra, thực tế nếu không phải nó có một khuôn mặt Theodore, tôi đã bắn nổ đầu nó từ lâu rồi."
