  },
  AvgDialog_95477_Content_57 = {
    Text = "Chỉ cần giết chị gái của các bạn, cũng có thể rời khỏi đây!"
  },
  AvgDialog_95477_Content_58 = {
    Text = "Kaitigura hoàn toàn lờ đi sự khiêu khích của N, suy nghĩ về hướng đi tiếp theo."
  },
  AvgDialog_95477_Content_59 = {
    Text = "Tiếp tục lên đường, ít nhất hãy tìm một nơi nghỉ ngơi trước đã."
  },
  AvgDialog_95477_Content_6 = {
    Text = "Nhưng không cái nào sử dụng được, không phải điêu khắc, không phải ảo ảnh, chỉ đơn giản là... không thể dùng."
