  AvgDialog_95477_Content_63 = {Text = "Hừm."},
  AvgDialog_95477_Content_64 = {
    Text = "Hành động của Lucius khiến mọi người cười lớn trở lại, tiếng cười trống rỗng hòa cùng với cái lạnh của đêm, lại một cách kỳ quặc tạo ra cảm giác thư thái."
