    Text = "Cảm giác đau nhói từ cánh tay phát ra. Nanh sắc của Dulerxain đâm thủng da thịt của bạn, lấy đi một miếng caro nhỏ bằng cách nhẹ nhàng nhất."
  },
  AvgDialog_97173_Content_46 = {
    Text = "Khi Durlesain nuốt lấy thịt và máu, trong không gian tinh thần của bạn, một điểm sáng rực rỡ lóe lên. Điểm sáng nhanh chóng lan rộng, che khuất tất cả các giác quan thực tại của bạn."
  },
  AvgDialog_97173_Content_47 = {
    Text = "Bạn cảm thấy cơ thể mình dần hòa nhập với Dule'n. Hình ảnh từ sâu trong tâm trí Dule'n dần dần chiếm lĩnh bộ não của bạn, hiện ra trước mắt……"
  },
  AvgDialog_97173_Content_48 = {
    Text = "Hội trường cung điện hoàng gia được trang trí rộn ràng không một bóng người, tất cả ánh sáng rực rỡ đều bị dập tắt."
  },
  AvgDialog_97173_Content_49 = {
    Text = "Ánh trăng qua cửa sổ của đại sảnh, giống như ánh trăng của thành phố hỏa táng tối nay, rơi trên mặt Dulecain."
  },
  AvgDialog_97173_Content_5 = {
    Text = "Chúng tôi đối mặt với ánh mắt thèm muốn của thế gian, phải làm những việc như vậy, chúng tôi không có sự lựa chọn.\nHơn nữa, kế hoạch của chúng tôi vẫn chưa đến mức thất bại."
  },
  AvgDialog_97173_Content_50 = {
    Text = "Giữa bàn ăn được trang trí tỉ mỉ, xác chết của Celeine đầy D-vết mặc lễ phục, mang theo nụ cười, chờ đợi một đám tang thuộc về nàng."
  },
  AvgDialog_97173_Content_51 = {
    Text = "Tôi đã hứa với bạn, Selene. Chào mừng...... chào mừng bạn đến với bữa tiệc thuộc về bạn."
  },
  AvgDialog_97173_Content_52 = {
