  },
  AvgDialog_97173_Content_61 = {
    Text = "Bàn tay Dullesain chìa ra giữa không trung. Những ngón tay bao quanh bởi làn sương đen chạm vào những ngón tay ảo ảnh ở giữa không trung, vào khoảnh khắc ngón tay chạm nhau, vô số ký ức không thuộc về hắn ùa về."
  },
  AvgDialog_97173_Content_62 = {
    Text = "Hắn thấy khi mình dẫn em gái đi mời xác chết trong nghĩa trang, Selene nhỏ bé run rẩy sợ hãi sau lưng hắn."
  },
  AvgDialog_97173_Content_63 = {
    Text = "Hắn thấy khi mình bị đuổi ra khỏi vương phủ vì thói quen ăn thịt xác chết, Selene đau buồn nhìn theo bóng dáng mình."
  },
  AvgDialog_97173_Content_64 = {
    Text = "Hắn thấy mình bị gia tộc ghét bỏ, uống ly rượu độc của cha, Selene đau khổ khóc sau cánh cửa đóng chặt."
  },
  AvgDialog_97173_Content_65 = {
    Text = "Hắn thấy ngày mình tái sinh đăng quang, giọt nước mắt hạnh phúc tự hào của Selene…"
  },
  AvgDialog_97173_Content_67 = {
