  AvgDialog_97173_Content_80 = {
    Text = "Sự giao tiếp với linh hồn, truyền thống của thành phố hỏa táng, tất cả bắt đầu từ ngày đó."
  },
  AvgDialog_97173_Content_81 = {
    Text = "Xin hãy cho tôi mượn sức mạnh của bạn, Kính thưa Quý vị Giữ Bí Mật. Tất cả ký ức nơi đây, sẽ do chúng ta gìn giữ và truyền thừa."
  },
  AvgDialog_97173_Content_82 = {
    Text = "……Đây là lời thề mà tôi đã hứa với Selene, cũng là với chính mình."
  },
  AvgDialog_97173_Content_83 = {
    Text = "Ngươi gật đầu mạnh mẽ, sức mạnh tinh thần tập trung vào điểm sáng. Dullesyne bất ngờ mở mắt, ký hiệu trong tay hắn nở ra như hoa."
