  AvgDialog_97173_Content_84 = {
    Text = "Huy hiệu Màn đêm mờ mịt đã được khởi động, vô số sợi dây mong manh từ mặt đất và lòng đất, từ sinh linh đến linh hồn không còn, lan tỏa ra ngoài, kết nối với Dullesain."
  },
  AvgDialog_97173_Content_85 = {
