  AvgDialog_97209_Content_26 = {
    Text = "Bạn không thể nhắm mắt, hai tay bắt đầu run rẩy. Giấc mơ này thật đẹp, khiến bạn không thể nào không muốn chìm đắm, nhưng quá nhiều thứ khiến bạn không thể không giữ tỉnh táo."
  },
  AvgDialog_97209_Content_27 = {
    Text = "Chúng là trách nhiệm bạn gánh vác, là vô số sinh mệnh chờ đợi được cứu rỗi, là khao khát trở về \"thế giới đó\", là sự thật điên loạn của vũ trụ đang dần dẫn đến hủy diệt, là……"
