  AvgDialog_97209_Content_35 = {
    Text = "Tôi chỉ hy vọng rằng, sự lựa chọn bạn đưa ra xuất phát từ những khao khát chân thực của bạn..."
  },
  AvgDialog_97209_Content_36 = {
    Text = "Hình bóng của Clementine hoàn toàn biến mất trong tầm nhìn của bạn, thay thế cô là một cánh đồng hoa."
