  },
  AvgDialog_97275_Content_5 = {
    Text = "Bản năng của bạn mách bảo rằng đây là thế giới cây nhân của bạn."
  },
  AvgDialog_97275_Content_6 = {
    Text = "Có vẻ như bạn đã phát hiện ra……"
  },
  AvgDialog_97275_Content_7 = {
    Text = "Bạn muốn tạo ra giấc mơ thuộc về mình, chắc chắn cần đến \"cốt lõi\" của riêng bạn. Hoặc có thể nói, nó chính là cốt lõi thực sự của giấc mơ này."
  },
  AvgDialog_97275_Content_8 = {
    Text = "Cùng với lời nói này, Clementine xuất hiện, đứng trước mặt bạn."
  },
  AvgDialog_97275_Content_9 = {
    Text = "Bạn vô thức nắm chặt chìa khóa bạc, khiến Clementine thở dài."
  },
  AvgDialog_97320_Content_1 = {
    Text = "Trở về quê hương"
  },
  AvgDialog_97320_Content_10 = {
    Text = "Bạn để mình rơi vào một cách vô tận, chìm vào bóng tối sâu hơn."
  },
  AvgDialog_97320_Content_11 = {
    Text = "Nhưng không sao. Chỉ cần tôi không muốn tỉnh dậy, thì giấc mơ này…"
  },
  AvgDialog_97320_Content_12 = {
    Text = "Sẽ không kết thúc."
  },
  AvgDialog_97320_Content_13 = {
    Text = "Nhưng âm thanh chuông khó chịu lại xuất hiện, thỉnh thoảng lẫn lộn với những âm thanh mờ mịt."
  },
  AvgDialog_97320_Content_14 = {
    Text = "……đến……bù……giác……"
  },
  AvgDialog_97320_Content_15 = {
    Text = "Có phải là Mythag không? Chờ đã, giọng nói này có vẻ như……"
  },
  AvgDialog_97320_Content_16 = {Text = "Czort!"},
  AvgDialog_97320_Content_17 = {
    Text = "Bạn mở to mắt, từ bóng tối hướng về ánh sáng, nhìn thế giới một lần nữa."
  },
  AvgDialog_97320_Content_18 = {
    Text = "Người đứng trước bạn thực sự là Czort, khung cảnh trước mặt cũng thực sự thuộc về Mythag.\nVết tích đen tối của quá trình phân rã trên bia mộ đã biến mất, và có thêm những người không quen biết."
  },
  AvgDialog_97320_Content_19 = {
    Text = "Nhiều thiếu niên, mặc đồng phục mới của Mythag, phân tán quanh nghĩa trang, với vẻ mặt trẻ trung nhưng nghiêm túc, chăm chú lắng nghe bài phát biểu của Czort."
  },
  AvgDialog_97320_Content_2 = {
    Text = "Trong bóng tối sâu thẳm, tiếng chuông vang lên.\nNặng nề, nghiêm túc, mang theo một ý nghĩa hối thúc nào đó."
  },
  AvgDialog_97320_Content_20 = {
    Text = "Cảnh tượng này quá quen thuộc, khiến bạn ngay lập tức nhớ lại những điều đã qua —"
  },
  AvgDialog_97320_Content_21 = {
    Text = "Đừng để phân tâm trong một nghi lễ quan trọng như vậy, <Yellow:Người Giữ Gìn>, người tiếp theo sẽ được trao chìa khóa bạc."
  },
  AvgDialog_97320_Content_22 = {
    Text = "Đặt mộ bia của chính mình, để chứng minh quyết tâm chúng ta đã <Yellow:đối đầu với rỗng rỗng> hiến dâng sức sống — đây không chỉ là truyền thống của Misaque, mà còn là dấu hiệu chúng ta kết thúc giai đoạn học tiền khoa và trở thành điều tra viên chính thức."
  },
  AvgDialog_97320_Content_23 = {
    Text = "Hồi ức hiện rõ trong tâm trí bạn, chồng lên hình ảnh hiện tại, khiến bạn có ảo giác thời gian như quay ngược lại. Nhưng lý trí còn sót lại đã đánh thức bạn."
  },
  AvgDialog_97320_Content_24 = {
    Text = "Bởi vì trong nghĩa trang trước mắt, chỉ thiếu hình bóng của Ramona.\nBởi vì lời nói của Czort, bạn hoàn toàn không thể hiểu."
  },
  AvgDialog_97320_Content_25 = {
    Text = "… Đại học Misaque là người tiên phong trong cuộc chiến chống lại sự xói mòn, là đường phòng thủ quan trọng bảo vệ tương lai của nhân loại."
  },
  AvgDialog_97320_Content_26 = {
    Text = "Trong ba trăm năm qua, Đại học Misag đã âm thầm bảo vệ cuộc sống bình yên của loài người khỏi hậu quả của rỗng rỗng, trả giá đắt."
  },
  AvgDialog_97320_Content_27 = {
    Text = "Nghĩa trang này, <Red: đã từng> là nơi chúng ta chuẩn bị sẵn để trở về, cũng là sự giác ngộ mà học sinh và thầy giáo Mythag đã hy sinh mạng sống vì sự tồn tại của nhân loại."
  },
  AvgDialog_97320_Content_28 = {
    Text = "Mọi thứ đều giống như trong quá khứ, mọi thứ lại khác biệt với quá khứ.\nBởi vì bạn đã nghe thấy từ \"【<Red:Đã từng>】\"."
  },
  AvgDialog_97320_Content_29 = {
    Text = "Vào ngày mà việc phân rã đã <Red:biến mất>, những bất ngờ, điên cuồng và cái chết đã trở thành lịch sử, và nơi này cũng trở thành chứng nhân cho hy sinh của các tổ tiên."
  },
  AvgDialog_97320_Content_3 = {
    Text = "Nhưng bạn không muốn tỉnh dậy.\nKý ức của bạn vẫn dừng lại ở khoảnh khắc cuối cùng bên bờ biển—"
  },
  AvgDialog_97320_Content_30 = {
    Text = "Mặc dù Mythag không còn chiến đấu vì sự tồn tại của nhân loại, nhưng vẫn cố gắng vì sự tiếp diễn của nền văn minh nhân loại."
  },
  AvgDialog_97320_Content_31 = {
    Text = "Vì vậy, hãy trân trọng cuộc sống của các bạn, tận hưởng cuộc sống của các bạn, đừng quên cuộc sống hôm nay của các bạn là đổi lấy bằng nhiều sinh mạng của những người khác."
  },
  AvgDialog_97320_Content_32 = {
    Text = "Bây giờ, lễ khai giảng chính thức bắt đầu, mời các thầy cô từ các khoa phát chìa khóa bạc cho sinh viên mới."
  },
  AvgDialog_97320_Content_33 = {
    Text = "Vì vậy, chìa khóa bạc rơi vào tay của những tân binh tại Mythag."
  },
  AvgDialog_97320_Content_34 = {
    Text = "Bạn nhìn họ mỉm cười nắm giữ chìa khóa bạc, nhìn những khuôn mặt trẻ trung đầy kỳ vọng và khát khao về tương lai, lòng bạn ngổn ngang trăm mối."
  },
  AvgDialog_97320_Content_35 = {
    Text = "Nhưng điều thực sự đập tan phòng tuyến tâm lý của bạn là một câu nói của Czort—"
  },
  AvgDialog_97320_Content_36 = {
    Text = "Những chiếc chìa khóa bạc này không còn có sức mạnh đặc biệt nữa, thời đại của các điều tra viên cũng đã qua, nhưng chúng ta vẫn sẽ tiến về phía trước."
  },
  AvgDialog_97320_Content_37 = {Text = "……!!!"},
  AvgDialog_97320_Content_38 = {
    Text = "Phân rã biến mất, chìa khóa bạc mất đi sức mạnh, điều tra viên cũng không còn, rốt cuộc đã xảy ra chuyện gì vậy!?"
  },
  AvgDialog_97320_Content_39 = {
    Text = "Tại lễ tốt nghiệp đang diễn ra, Czort rõ ràng không thể trả lời bạn."
  },
  AvgDialog_97320_Content_4 = {
    Text = "Dưới ánh nắng rực rỡ, những người đánh thức chơi bóng chuyền trên bãi biển, bạn nhận máy ảnh từ 24 và ghi lại khoảnh khắc vui vẻ tuyệt vời thành vĩnh cửu."
  },
  AvgDialog_97320_Content_40 = {
    Text = "Có vẻ như mọi thứ chỉ có thể dựa vào chính mình. Hãy đi dạo xung quanh trước rồi hãy tìm hiểu tình hình……"
  },
  AvgDialog_97320_Content_41 = {
    Text = "Bạn thở dài thật sâu, lặng lẽ rút lui khỏi lễ nhập học."
  },
  AvgDialog_97320_Content_42 = {
    Text = "Kiến trúc của Mythag không khác gì những ngày trước, nhưng khắp nơi đều thấy dải băng chào đón, những tiếng cười của đám đông đi qua và âm nhạc vui vẻ xung quanh, khiến nó khác biệt trong ký ức."
  },
  AvgDialog_97320_Content_43 = {
    Text = "Thực tế ở Mythag luôn nghiêm túc và nặng nề, đầy cái chết và nỗi đau khó nói."
  },
  AvgDialog_97320_Content_44 = {
    Text = "Nhưng cái Mythag trong giấc mơ này…"
  },
  AvgDialog_97320_Content_45 = {
    Text = "Có thể trong thế giới không có phân rã, Mythag thực sự là như vậy…"
  },
  AvgDialog_97320_Content_46 = {
    Text = "Nhưng thực tế không có nếu, bạn chỉ có thể nhìn xung quanh trong tâm trạng phức tạp, cố gắng tìm kiếm manh mối.\nThật không may, âm nhạc liên tục xung quanh đã ảnh hưởng đến suy nghĩ của bạn."
  },
  AvgDialog_97320_Content_47 = {
    Text = "Phong cách âm nhạc này có vẻ quen thuộc... Đúng vậy, đó là Hameln."
  },
  AvgDialog_97320_Content_48 = {
    Text = "Có lẽ tôi có thể hỏi anh ta rốt cuộc đã xảy ra chuyện gì..."
  },
  AvgDialog_97320_Content_49 = {
    Text = "Khi bạn theo tiếng đến phòng âm nhạc, nhạc đã dừng lại.\nCửa phòng mở rộng, lộ ra Hameln đang luyện tập."
  },
  AvgDialog_97320_Content_5 = {
    Text = "Rồi thì……"
  },
  AvgDialog_97320_Content_50 = {Text = "%player%?"},
  AvgDialog_97320_Content_51 = {
    Text = "Bạn đến quá sớm. Buổi biểu diễn vẫn chưa hoàn hảo, tôi cần luyện tập nhiều hơn."
  },
  AvgDialog_97320_Content_52 = {
    Text = "Không, tôi không phải vì điều này mà đến đây."
  },
  AvgDialog_97320_Content_53 = {
    Text = "Hả? Có chuyện gì quan trọng hơn âm nhạc không?"
  },
  AvgDialog_97320_Content_54 = {
    Text = "Bạn hít một hơi thật sâu, sắc mặt bất giác trở nên nghiêm túc, hỏi câu hỏi quan trọng nhất."
  },
  AvgDialog_97320_Content_55 = {
    Text = "Phân rã đã biến mất như thế nào?"
  },
  AvgDialog_97320_Content_56 = {
    Text = "Giống như màn trình diễn cuối cùng cũng có ngày hạ màn. Phần biểu diễn của nó đã kết thúc, chỉ thế thôi."
  },
  AvgDialog_97320_Content_57 = {
    Text = "Câu trả lời như dự đoán, nhưng câu trả lời mơ hồ này cũng khiến bạn nhẹ nhõm.\nKhông ai hiểu bản chất phân rã hơn bạn."
  },
  AvgDialog_97320_Content_58 = {
    Text = "Có vẻ như đây đúng là một \"giấc mơ\" khác, chỉ là \"giấc mơ\" này có vẻ điên loạn và tuyệt vọng hơn..."
  },
  AvgDialog_97320_Content_59 = {
    Text = "Giấc mơ? Bạn đang nói gì vậy…"
  },
  AvgDialog_97320_Content_6 = {
    Text = "Mặt trời đen tối rơi xuống, cuốn theo những làn sóng trắng vỡ vụn, và cũng sẽ làm bốc hơi mọi vẻ đẹp, chỉ để lại bạn một mình, rơi vào bóng tối vô tận."
  },
  AvgDialog_97320_Content_60 = {
    Text = "Không sao cả. Tôi muốn biết sau khi phân rã biến mất, các người đánh thức đều đi đâu?"
  },
  AvgDialog_97320_Content_61 = {
    Text = "Đây là một câu hỏi, hay một yêu cầu?"
  },
  AvgDialog_97320_Content_62 = {
    Text = "……một yêu cầu."
  },
  AvgDialog_97320_Content_63 = {
    Text = "Tôi cần phải nhìn thấy những người đánh thức đó bằng đôi mắt của mình. Tôi có rất nhiều điều cần xác nhận."
  },
  AvgDialog_97320_Content_64 = {
    Text = "……đã hiểu."
  },
  AvgDialog_97320_Content_65 = {
    Text = "Hameln thu gọn gậy chỉ huy vào hộp, bước đi với bước chân thanh lịch đến trước cửa, làm một động tác \"mời\"."
  },
  AvgDialog_97320_Content_66 = {
    Text = "Đi theo tôi nào."
  },
  AvgDialog_97320_Content_7 = {
    Text = "Nếu không có \"Mặt trời đen rơi\" cuối cùng này, tất cả những trải nghiệm bên bãi biển sẽ hoàn hảo."
  },
  AvgDialog_97320_Content_8 = {
    Text = "Nhưng tại sao, đó chỉ là một giấc mơ nhỉ?"
  },
  AvgDialog_97320_Content_9 = {
    Text = "……………"
  },
  AvgDialog_97931_Content_1 = {
    Text = "Trong vũng đen nơi những chiếc lông bạc tung ra, bạn rơi vào cuộc chiến khó khăn, bị chất phân rã màu đen liên tục nuốt chửng."
  },
  AvgDialog_97931_Content_10 = {
    Text = "Tawil! Vừa rồi đã xảy ra chuyện gì!?"
  },
  AvgDialog_97931_Content_11 = {
    Text = "Bởi vì sự tồn tại của tôi khiến nơi đây trở nên không ổn định, sẽ quá mức phản chiếu cảm xúc và kinh nghiệm của bạn, làm cho chúng trở nên cực điểm."
  },
  AvgDialog_97931_Content_12 = {
    Text = "Vì vậy đã - chiếu rọi? Chờ đã, điều này không giống như những gì bạn sẽ nói, mà là..."
  },
  AvgDialog_97931_Content_13 = {
    Text = "Bạn nhìn về phía Tawil, xác nhận suy đoán của mình, và Tawil gật đầu, đưa ra phản hồi xác nhận."
  },
  AvgDialog_97931_Content_14 = {
    Text = "Tôi nghĩ, bạn chắc chắn đã đoán ra người đứng sau điều này."
  },
  AvgDialog_97931_Content_15 = {
    Text = "<Shake: Tại sao cô ấy lại làm như vậy?>"
  },
  AvgDialog_97931_Content_16 = {
    Text = "Có lẽ, điều này cần bạn tự mình hỏi. Những gì tôi có thể làm, chỉ là đem lại cho bạn chút ánh sáng."
  },
  AvgDialog_97931_Content_17 = {
    Text = "Vậy có nghĩa là, bạn biết kế hoạch của cô ấy nhưng không ngăn cản, chỉ đang đợi tôi ở đây?"
  },
  AvgDialog_97931_Content_18 = {
    Text = "Biểu hiện của Tawil đã thay đổi trong khoảnh khắc, có thể là một cảm xúc gọi là bối rối, hoặc có thể chỉ là một chút lạc lối."
  },
  AvgDialog_97931_Content_19 = {
    Text = "Bạn không biết, nó dừng lại quá ngắn ngủi."
  },
  AvgDialog_97931_Content_2 = {
    Text = "<Shake: Tawil……>"
  },
  AvgDialog_97931_Content_20 = {
    Text = "Tôi đã chứng kiến và thay đổi vô số người và thế giới, nhưng những trải nghiệm trong quá khứ đã dạy tôi rằng, đối với một tồn tại như tôi, đứng nhìn là sự lựa chọn tốt nhất."
  },
  AvgDialog_97931_Content_21 = {
    Text = "Đặc biệt là đối với bạn, biến số duy nhất, câu trả lời của sự bắt đầu và kết thúc."
  },
  AvgDialog_97931_Content_22 = {
    Text = "……tôi đã hiểu. Nhưng tại sao……"
  },
  AvgDialog_97931_Content_23 = {
    Text = "Bạn do dự một lúc, hỏi ra thắc mắc lâu nay chất chứa trong lòng."
  },
  AvgDialog_97931_Content_24 = {
    Text = "Tại sao những giấc mơ này… lại đẹp đến vậy?"
  },
  AvgDialog_97931_Content_25 = {
    Text = "Điều này cần bạn tự hỏi chính mình, %player%. Bạn thực sự khao khát điều gì?"
  },
  AvgDialog_97931_Content_26 = {
    Text = "Bởi vì thế giới này, về bản chất mà nói, chỉ là sự đáp lại sự khao khát trong tâm bạn.\nĐó cũng là lý do tôi không ngăn cản."
  },
  AvgDialog_97931_Content_27 = {
    Text = "Phản hồi cho những gì tôi khao khát trong lòng!?"
  },
  AvgDialog_97931_Content_28 = {
    Text = "Bạn đứng như trời trồng."
  },
  AvgDialog_97931_Content_29 = {
    Text = "Bạn đã tưởng tượng qua vô vàn câu trả lời, nhưng không có bất kỳ một câu nào hướng về chính bạn, hướng về khao khát chân chính trong nội tâm bạn."
  },
  AvgDialog_97931_Content_3 = {
    Text = "Đáp lại vẫn là tiếng gọi ồm ồm như gào thét như than thở."
  },
  AvgDialog_97931_Content_30 = {
    Text = "Nhưng mọi thứ đều định sẵn như vậy, phải không?\nBởi vì lý do bạn chiến đấu, luôn đơn giản như vậy —"
  },
  AvgDialog_97931_Content_31 = {
    Text = "Bạn không muốn thấy lại những bi kịch do \"phân rã\" gây ra"
  },
  AvgDialog_97931_Content_32 = {
    Text = "Bạn khao khát mỗi người đánh thức, mỗi người còn tồn tại trên thế gian, đều nhận được \"hạnh phúc\""
  },
  AvgDialog_97931_Content_33 = {
    Text = "<Shake: Thật là một…… ý tưởng lớn đến bất khả thi, đặc biệt trong thế giới này……>"
  },
  AvgDialog_97931_Content_34 = {
    Text = "<Shake: Tôi đã biết từ đầu, ngay từ ngày trở thành người giữ gìn Mythag, tôi đã biết……>"
  },
  AvgDialog_97931_Content_35 = {
    Text = "Khu mộ này, là nơi chúng tôi đã chuẩn bị từ trước để trở về, cũng là sự giác ngộ của thầy trò Misaque hiến dâng sức sống cho sự tồn tại của nhân loại."
  },
  AvgDialog_97931_Content_36 = {
    Text = "……Tôi nghĩ, trong số các tân sinh viên, không ai có thể hiểu rõ hơn các bạn về ý nghĩa sâu sắc và sự nặng nề của những lời này."
  },
  AvgDialog_97931_Content_37 = {
    Text = "Các sự kiện liên quan đến sự hòa tan luôn đi kèm với sự cố, điên rồ và cái chết, đây là những trải nghiệm không thể tránh khỏi trên con đường của chúng ta."
  },
  AvgDialog_97931_Content_38 = {
    Text = "Cái chết, tuyệt vọng, điên loạn, chỉ là những điều thường nhật trong cuộc sống ở thế giới này, và trong những điều bình thường như vậy, không có chỗ cho hạnh phúc..."
  },
  AvgDialog_97931_Content_39 = {
    Text = "<Shake: Tôi biết, tôi chỉ là…… chỉ là……>"
  },
  AvgDialog_97931_Content_4 = {
    Text = "Trong tiếng gọi này, chất lỏng phân rã màu đen nuốt chửng cánh tay bạn, nuốt chửng cổ bạn, cuối cùng nuốt chửng tất cả của bạn."
  },
  AvgDialog_97931_Content_40 = {
    Text = "Chỉ là trong sâu thẳm tâm hồn\nkhông cam tâm từ bỏ giấc mơ về thứ được gọi là \"hạnh phúc\"……"
  },
  AvgDialog_97931_Content_41 = {
    Text = "Điều này là bình thường, theo đuổi hạnh phúc là bản năng của con người."
  },
  AvgDialog_97931_Content_42 = {
    Text = "Tawil lặng lẽ quan sát bạn, ánh sáng từ xa phản chiếu lên gương mặt cô ấy, khiến bạn không nhìn rõ biểu hiện của cô ấy."
  },
  AvgDialog_97931_Content_43 = {
    Text = "Tôi không phủ nhận cảm xúc này dựa trên bản năng, tôi chỉ muốn nhắc bạn rằng, lý trí, thực ra cũng là một bản năng."
  },
  AvgDialog_97931_Content_44 = {
    Text = "Giống như bạn đến đây tìm tôi, như bạn tỉnh dậy từ giấc mơ khao khát trong tim vì trách nhiệm."
  },
  AvgDialog_97931_Content_45 = {
    Text = "Đối với thời gian vô hạn, kết quả do cảm tính và lý trí gây ra, đều đi đến cùng một đích, nhưng với từng cá nhân, có thể lại mang ý nghĩa khác nhau."
  },
  AvgDialog_97931_Content_46 = {
    Text = "Tawil nhẹ nhàng nâng tay lên, như thể muốn chạm vào bạn, nhưng cuối cùng chỉ kìm nén nhắm mắt lại."
  },
  AvgDialog_97931_Content_47 = {
    Text = "Tôi chỉ hy vọng rằng, bất kể dựa trên bản năng nào, hành động của bạn đều có thể thực hiện được những nguyên tắc và ý chí của chính mình."
  },
  AvgDialog_97931_Content_48 = {
    Text = "Bởi vì, lý tưởng và ý chí của bạn, chính là 'tương lai của thế giới'."
  },
  AvgDialog_97931_Content_49 = {
    Text = "Sau đó, Tawil mở mắt, và bạn thấy chính mình trong đôi mắt xanh trẻ thơ của cô ấy."
  },
  AvgDialog_97931_Content_5 = {
    Text = "Bạn không thể thở, cũng không thể nói ra câu \"tại sao\" trong lòng, chỉ có thể bị đen tối vô hạn nhấn chìm, không ngừng chìm xuống."
  },
  AvgDialog_97931_Content_50 = {
    Text = "Bạn nghĩ rằng mình sẽ đau buồn khóc lóc, hoặc l hesitating struggle, nhưng bạn không như vậy.\nBiểu hiện của bạn bình tĩnh, kiên định, như thể đã chuẩn bị cho sự hy sinh."
  },
  AvgDialog_97931_Content_51 = {
    Text = "Có vẻ như, Người giữ gìn, bạn đã đưa ra quyết định."
  },
  AvgDialog_97931_Content_52 = {
    Text = "Bạn chỉ lặng lẽ nhìn về phía Tawil, với giọng điệu kiên định và bình tĩnh."
  },
  AvgDialog_97931_Content_53 = {
    Text = "Hãy đưa tôi rời khỏi đây, dẫn tôi đi gặp cô ấy."
  },
  AvgDialog_97931_Content_54 = {
    Text = "Dù giấc mơ đẹp đến đâu, cũng đến lúc phải tỉnh dậy."
  },
  AvgDialog_97931_Content_55 = {
    Text = "Vì vậy, sáu cánh của Tawil thực sự mở ra, tạo ra một cơn gió, trong gió đó, những cánh bay bạc tung bay, che khuất tầm nhìn của bạn."
  },
  AvgDialog_97931_Content_56 = {
    Text = "Người giữ gìn, câu trả lời ban đầu và kết thúc, hãy hành động theo lý tưởng và ý chí của mình."
  },
  AvgDialog_97931_Content_57 = {
    Text = "Trước sự hỗn loạn và điều chưa biết, dựa vào cảm xúc hay lý trí, đều là những con đường không thể chỉ trích."
  },
  AvgDialog_97931_Content_58 = {
    Text = "Khi đôi cánh bạc biến mất, bạn lại trở về Mythag.\nChỉ là lần này, Mythag và trước đây hoàn toàn khác, nó quá vắng vẻ."
  },
  AvgDialog_97931_Content_59 = {
    Text = "Không có một sự tái sinh đầy hy vọng nào, không có hoạt động hội hè vui vẻ nào, chỉ có sự trống trải, chỉ có sự cô đơn, và bên trong sự trống trải và cô đơn vô tận đó là Clementine."
  },
  AvgDialog_97931_Content_6 = {
    Text = "Ngay lúc đó, một tiếng thở dài vang lên bên tai bạn, và sau đó trước mắt bỗng chốc trở thành một màu trắng tinh khiết."
  },
  AvgDialog_97931_Content_60 = {
    Text = "Cô ấy quả thực đã đưa bạn đến đây."
  },
  AvgDialog_97931_Content_61 = {
    Text = "Clementine nhìn bạn, đứng yên lặng tại chỗ.\nCô đã chờ đợi ở đây một thời gian dài."
  },
  AvgDialog_97931_Content_62 = {
    Text = "Người giữ gìn, tôi nên vui mừng vì bạn thông minh như vậy, phát hiện ra sự thật một cách nhanh chóng, hay nên buồn vì mọi việc tôi đã làm đều trở thành vô nghĩa?"
  },
  AvgDialog_97931_Content_63 = {
    Text = "Dù bạn nghĩ thế nào, tôi cũng phải thành thật, và hy vọng bạn tin tưởng —"
  },
  AvgDialog_97931_Content_64 = {
    Text = "Tất cả những gì tôi đã làm, đều vì bạn."
  },
  AvgDialog_97931_Content_7 = {
    Text = "Khi đôi mắt của bạn thích nghi với ánh sáng, cuối cùng bạn có thể nhìn thấy, bạn đã thấy Tawil.\nTawil thật sự."
  },
  AvgDialog_97931_Content_9 = {
    Text = "Tawil đứng yên trước mặt bạn, vẻ mặt thương xót nhìn bạn."
  },
  AvgDialog_97988_Content_1 = {
    Text = "Mặt trời không bao giờ tắt từ xưa đến nay"
  },
  AvgDialog_97988_Content_10 = {
    Text = "Rõ ràng trong khi Lucius kể chuyện, bạn vẫn đang suy nghĩ cách làm cho đoạn hành trình nguy hiểm đó sống động và hài hước để kể cho mọi người."
  },
  AvgDialog_97988_Content_100 = {
    Text = "Tôi phải công nhận, tôi chưa bao giờ nghĩ rằng trò chơi này sẽ kết thúc theo cách thú vị như vậy!"
  },
  AvgDialog_97988_Content_101 = {
    Text = "Đây là một trong những món quà tốt nhất mà tôi đã nhận được!"
  },
  AvgDialog_97988_Content_102 = {
    Text = "Cậu chưa bao giờ thấy N kích động như vậy, lúc này anh ta phấn khích như một đứa trẻ nhìn thấy món đồ chơi yêu thích."
  },
  AvgDialog_97988_Content_103 = {
    Text = "Thần bóng tối không ngần ngại bộc lộ tất cả nhiệt huyết, chào đón mặt trời rực cháy quay trở lại trước mắt."
  },
  AvgDialog_97988_Content_104 = {
    Text = "Có lẽ không cần mang theo một cái? Thôi, điều này không quan trọng!"
  },
  AvgDialog_97988_Content_105 = {
    Text = "Chìa khóa lúc này là, hãy để chúng ta bước lên sân khấu được dệt nên bởi số phận này, bắt đầu buổi lễ thuộc về những tối cao!"
  },
  AvgDialog_97988_Content_106 = {
    Text = "Nói xong rồi à?"
  },
  AvgDialog_97988_Content_107 = {Text = "!?"},
  AvgDialog_97988_Content_108 = {
    Text = "Kaitigula nhặt hai khẩu súng rơi trên đất, phủ bụi trên đó."
  },
  AvgDialog_97988_Content_109 = {
    Text = "Tôi đã nói, tôi sẽ ban cho bạn, cái chết vĩnh hằng."
  },
  AvgDialog_97988_Content_11 = {
    Text = "Tôi……không còn nhớ gì cả."
  },
  AvgDialog_97988_Content_110 = {
    Text = "Nhiệt độ của nòng súng nhanh chóng tăng lên, phát ra tiếng gầm gừ một cách vô tội vạ."
  },
  AvgDialog_97988_Content_111 = {
    Text = "Kaitigura nâng súng lên, nhằm thẳng vào hỗn loạn đen tối trên trời."
  },
  AvgDialog_97988_Content_112 = {
    Text = "Thật ồn ào, đến giờ này rồi vẫn lải nhải không ngừng."
  },
  AvgDialog_97988_Content_113 = {
    Text = "<Shake:Tôi đã bắt đầu từ sự tái sinh từng phút, từng giây... đều chịu đựng khát vọng xé tan bạn ra thành mảnh vỡ!>"
  },
  AvgDialog_97988_Content_114 = {
    Text = "Dưới ánh lửa màu hổ phách, nụ cười điên cuồng của Kaitigula trở nên vô cùng nguy hiểm."
  },
  AvgDialog_97988_Content_115 = {
    Text = "Nụ cười này mang theo sự tức giận tột cùng, đủ sức làm vỡ tan cơn giận của thần."
  },
  AvgDialog_97988_Content_116 = {
    Text = "Lý do tôi giữ bạn đến bây giờ chính là để trả lại những lời xả rác đó."
  },
  AvgDialog_97988_Content_117 = {
    Text = "Kết quả bạn lại dám lật ngược thế cờ, thật làm người ta... không hài lòng!"
  },
  AvgDialog_97988_Content_118 = {
    Text = "Ngọn lửa màu hổ phách bốc lên, đẩy bóng tối đến góc tối tăm nhất."
  },
  AvgDialog_97988_Content_119 = {
    Text = "Chỉ là sóng giết chóc do cô ấy phát ra cũng đủ khiến bạn cảm nhận được nỗi sợ hãi vô biên từ sâu trong linh hồn."
  },
  AvgDialog_97988_Content_12 = {
    Text = "Bạn cúi đầu tìm ly rượu, định đưa ly cho Katioula."
  },
  AvgDialog_97988_Content_120 = {
    Text = "Đó là nỗi sợ hãi cuối cùng chắc chắn phải đến, đã được khắc vào sâu nhất và nguyên thủy nhất trong mọi vật tạo hóa——<Big:<Red:Chết>>."
  },
  AvgDialog_97988_Content_121 = {
    Text = "Nghe này, tôi không quan tâm đến số phận gì cả, cũng chẳng muốn dính dáng đến những thứ đó."
  },
  AvgDialog_97988_Content_122 = {
    Text = "Tôi chỉ biết rằng, ngươi là con hoang của gia đình tôi"
  },
  AvgDialog_97988_Content_123 = {
    Text = "<Shake:<Big:<Bold:<Red:Đã đến lúc ngã xuống!>>>>"
  },
  AvgDialog_97988_Content_124 = {
    Text = "Ánh lửa dữ dội bắn ra từ nòng súng, sau đó, bóng tối hoàn toàn biến mất."
  },
  AvgDialog_97988_Content_125 = {
    Text = "Ánh lửa mạnh mẽ phóng ra từ miệng súng, sau đó, bóng tối biến mất."
  },
  AvgDialog_97988_Content_126 = {
    Text = "Ánh sáng làm tan chảy mọi thứ bao phủ đất trời, như ngày cực điểm không tưng bừng liên tục thiêu đốt thế giới."
  },
  AvgDialog_97988_Content_127 = {
    Text = "Ngọn lửa màu hổ phách rơi xuống, mang lại sự hủy diệt và cái chết bình đẳng cho mọi thứ."
  },
  AvgDialog_97988_Content_128 = {
    Text = "N dường như muốn nói điều gì đó, nhưng cuối cùng lại không phát ra âm thanh nào."
  },
  AvgDialog_97988_Content_129 = {
    Text = "N dường như muốn nói điều gì đó, nhưng cuối cùng lại không phát ra âm thanh nào."
  },
  AvgDialog_97988_Content_13 = {
    Text = "A... thì ra... rượu đã hết rồi sao."
  },
  AvgDialog_97988_Content_130 = {
    Text = "Bởi vì trước mặt mặt trời thật sự, âm thanh cũng đã bị tan chảy."
  },
  AvgDialog_97988_Content_131 = {
    Text = "Thần đen tối vỡ vụn, khí đen che trời hoàn toàn biến mất, chôn vùi tất cả, biển cát biến thành ảo ảnh."
  },
  AvgDialog_97988_Content_132 = {
    Text = "Thần đen tối vỡ vụn, khí đen che trời hoàn toàn biến mất, chôn vùi tất cả, biển cát biến thành ảo ảnh."
  },
  AvgDialog_97988_Content_133 = {
    Text = "Các bạn lại trở về trong đền thờ, như thể mọi thứ chưa từng xảy ra."
  },
  AvgDialog_97988_Content_134 = {
    Text = "Ừm ahhhhhh—!"
  },
  AvgDialog_97988_Content_135 = {
    Text = "Trên khuôn mặt tối om của N hiếm khi xuất hiện chút vết nứt, bạn chưa bao giờ thấy hắn ở trong tình trạng bối rối như vậy."
  },
  AvgDialog_97988_Content_136 = {
    Text = "Có lẽ kêu gào mới thực sự phù hợp với bạn, phải không?"
  },
  AvgDialog_97988_Content_137 = {
    Text = "Nếu lần gặp tới bạn vẫn có màn biểu diễn tuyệt vời như vậy, tôi không ngại để bạn chết sảng khoái hơn một chút."
  },
  AvgDialog_97988_Content_138 = {
    Text = "Hô… hô… không vấn đề gì, lần sau gặp lại, tôi sẽ cho bạn một màn biểu diễn thú vị hơn."
  },
  AvgDialog_97988_Content_139 = {
    Text = "Đã điều chỉnh lại hơi thở một chút, N lại ra vẻ cái nụ cười bạn ghét."
  },
  AvgDialog_97988_Content_14 = {
    Text = "Lúc này bạn mới nhận ra, ly đã hoàn toàn rỗng không."
  },
  AvgDialog_97988_Content_140 = {
    Text = "Hôm nay tôi rất vui, mọi thứ xảy ra hôm nay đều nằm ngoài sự mong đợi của tôi!"
  },
  AvgDialog_97988_Content_141 = {
    Text = "Nhưng một buổi biểu diễn tuyệt vời cuối cùng cũng cần phải hạ màn, nào, hãy giết tôi! Hãy cho buổi diễn xuất lôi cuốn này một kết thúc hoàn hảo nhất!"
  },
  AvgDialog_97988_Content_142 = {
    Text = "Tất nhiên, tôi sẽ giết bạn, rồi tìm ra hình thể dơ bẩn không biết đang trốn ở đâu của bạn."
  },
  AvgDialog_97988_Content_143 = {
    Text = "Dù bạn trốn ở góc nào của vũ trụ, tôi sẽ tìm thấy bạn và ban cho bạn cái chết đau đớn nhất."
  },
  AvgDialog_97988_Content_144 = {
    Text = "Bây giờ, hãy để mọi thứ này, cháy trong địa ngục!"
  },
  AvgDialog_97988_Content_146 = {
    Text = "Cảm giác ra sao? Cơ thể mới sinh còn thích nghi được không?"
  },
  AvgDialog_97988_Content_147 = {
    Text = "Một vài tiếng vo ve vang lên trong không khí, lúc này bạn mới cảm thấy cơ thể mình có điều khác thường."
  },
  AvgDialog_97988_Content_148 = {
    Text = "Khi Katie Gura trở thành người đánh thức, thân thể của Gerard dường như cũng đã xảy ra một số thay đổi."
  },
  AvgDialog_97988_Content_149 = {
    Text = "Ngọn lửa màu hổ phách thay thế thịt máu, tạo thành một thân thể mới."
  },
  AvgDialog_97988_Content_15 = {
    Text = "Xem ra phải đến lần sau mới có thể.........."
  },
  AvgDialog_97988_Content_150 = {
    Text = "Theo một cách nào đó, các bạn đã được tái sinh, thậm chí có thể nói là bước vào điều kỳ diệu."
  },
  AvgDialog_97988_Content_151 = {
    Text = "Nhưng ở một nghĩa khác, các bạn cũng đã mất đi tất cả những gì của con người."
  },
  AvgDialog_97988_Content_152 = {
    Text = "Thật sao? Lucius, bạn thấy rất ổn? Nào, biểu diễn cho tôi một cú lộn ngược."
  },
  AvgDialog_97988_Content_153 = {
    Text = "Âm thanh vo ve trong không khí càng to hơn, dường như đang ngầm phản đối."
  },
  AvgDialog_97988_Content_154 = {
    Text = "Ô? Trông có vẻ tinh thần tốt đấy, những người khác đâu?"
  },
  AvgDialog_97988_Content_155 = {
    Text = "Nhiều âm thanh vo ve từ các nguồn khác nhau vang lên, bạn có thể cảm nhận được họ đang báo cáo an toàn cho Katygula."
  },
  AvgDialog_97988_Content_156 = {
    Text = "Hình như mọi người đều thích nghi với thân thể mới, tốt rồi, vậy chúng ta hãy bắt đầu nào."
  },
  AvgDialog_97988_Content_157 = {
    Text = "Bắt đầu săn lùng... biến chúng ta thành kẻ chủ mưu như vậy."
  },
  AvgDialog_97988_Content_159 = {
    Text = "Khục...khục...bạn là ai?"
  },
  AvgDialog_97988_Content_16 = {
    Text = "(Có chuyện gì thế? Tại sao tôi không thể nói được...?)"
  },
  AvgDialog_97988_Content_160 = {
    Text = "Nhà điều tra yếu ớt nằm xuống đất, máu từ đồng phục Mythag từ từ thấm ra."
  },
  AvgDialog_97988_Content_161 = {
    Text = "Tôi là ai không quan trọng, quan trọng là tôi rất đánh giá cao hành động của bạn trong việc làm bẩn ổ của đám thú vật đó."
  },
  AvgDialog_97988_Content_162 = {
    Text = "Có cần giúp đỡ gì không?"
  },
  AvgDialog_97988_Content_163 = {
    Text = "Điều tra viên ngẩng đầu, trong hốc mắt sâu thẳm là một đôi mắt vô cùng mệt mỏi, đôi môi nhợt nhạt vì mất máu quá nhiều."
  },
  AvgDialog_97988_Content_164 = {
    Text = "Sau khi nhận thấy những dấu hiệu lạ trên cơ thể Katie, anh nhanh chóng xác định trước mặt mình là một người đánh thức."
  },
  AvgDialog_97988_Content_165 = {
    Text = "Hắn cắn môi, dường như đã quyết định điều gì, từ từ và run rẩy đưa tay vào túi áo."
  },
  AvgDialog_97988_Content_166 = {
    Text = "Rắc rối… Bạn hãy chuyển cái này cho Đại học mythag…"
  },
  AvgDialog_97988_Content_167 = {
    Text = "Anh ta sự dụng đến hệ lực cuối cùng để đưa phong bì dính máu cho Caligula, nhưng chưa kịp Caligula nhận lấy, tay phải đã buông vô lực xuống."
  },
  AvgDialog_97988_Content_168 = {
    Text = "Đại học Mythag? Có chút ấn tượng."
  },
  AvgDialog_97988_Content_169 = {
    Text = "Kaitigula nhặt lá thư lên, mở phong bì và xem sơ lược nội dung trên thư."
  },
  AvgDialog_97988_Content_17 = {
    Text = "……Ngủ ngon nhé, Gerard."
  },
  AvgDialog_97988_Content_170 = {
    Text = "……Thú vị, được thôi, tôi sẽ giúp việc này."
  },
  AvgDialog_97988_Content_171 = {
    Text = "Đi thôi, các chàng trai và cô gái, hãy cho chúng ta một chuyến đi đến Mythag."
  },
  AvgDialog_97988_Content_172 = {
    Text = "Ở đó chắc chắn sẽ gặp một người rất thú vị."
  },
  AvgDialog_97988_Content_174 = {
    Text = "Ký ức của giấc mơ dừng lại ở đây, bạn thấy một cái tên rất quen thuộc trong cái nhìn cuối cùng."
  },
  AvgDialog_97988_Content_175 = {
    Text = "………… Người yêu quý của bạn, Dexter."
  },
  AvgDialog_97988_Content_18 = {
    Text = "Kaitigula giơ tay ra, do dự một hồi, vẫn từ từ hạ tay xuống."
  },
  AvgDialog_97988_Content_19 = {
    Text = "(Thì ra, là\"tôi\"đã chết rồi sao.)"
  },
  AvgDialog_97988_Content_2 = {
    Text = "Gerald, anh thì sao?"
  },
  AvgDialog_97988_Content_20 = {
    Text = "Cơ thể của Jerard đã tan chảy thành một chất lỏng đen không rõ ràng, chỉ còn hai con mắt lăn xuống và đang lặng lẽ dõi theo Caligula."
  },
  AvgDialog_97988_Content_21 = {
    Text = "Ý thức của bạn đã rời khỏi thân thể của Gerard, những ký ức liên quan cũng nhanh chóng bay hơi, như giọt nước dưới cái nóng gay gắt."
  },
  AvgDialog_97988_Content_22 = {
    Text = "Chỉ trong chớp mắt, bạn đã quên hết mọi điều về họ."
  },
  AvgDialog_97988_Content_23 = {
    Text = "Ngoại trừ câu chuyện cuối cùng về sự trả thù này."
  },
  AvgDialog_97988_Content_24 = {
    Text = "Được rồi, ra đi, tôi biết bạn đang nhìn."
  },
  AvgDialog_97988_Content_25 = {
    Text = "Cảm giác thế nào?"
  },
  AvgDialog_97988_Content_26 = {
    Text = "Tâm trạng tốt, còn bạn thì sao? Cảm giác tự tay giết chết người thân?"
  },
  AvgDialog_97988_Content_27 = {
    Text = "Lời nói của N vừa dứt, mọi thứ bên cạnh Katie Gura biến mất không còn dấu vết, giấc mơ đẹp tan biến, hiện thực tàn khốc bắt đầu vung tay với móng vuốt sắc bén."
  },
  AvgDialog_97988_Content_28 = {
    Text = "Kaitigula dường như đã biết tất cả những điều này, chỉ lặng lẽ quan sát xác chết của mọi người."
  },
  AvgDialog_97988_Content_29 = {
    Text = "Tôi đã tưởng rằng mọi người vẫn còn một cái xác hoàn chỉnh, hóa ra cảm giác mất mát lúc đó… là như vậy."
  },
  AvgDialog_97988_Content_3 = {
    Text = "Trên cồn cát vàng, chỉ còn lại bạn và Katie Gula, vào lúc này bạn cuối cùng đã nhìn rõ dung mạo dưới bóng đen của họ."
  },
  AvgDialog_97988_Content_30 = {
    Text = "Hiện tại tâm trạng của tôi... hơi tệ."
  },
  AvgDialog_97988_Content_31 = {
    Text = "Chỉ đến mức này thôi sao? Không nên hét lên đau đớn không kiềm chế, đòi tôi trả lại mọi người cho bạn?"
  },
  AvgDialog_97988_Content_32 = {
    Text = "Đừng giả vờ nữa, hơi ghê tởm một chút."
  },
  AvgDialog_97988_Content_33 = {Text = "Ừm?"},
  AvgDialog_97988_Content_34 = {
    Text = "Kaitigula ghét bỏ nhăn mày, ngẩng đầu nhìn về phía mặt trời đã biến thành N."
  },
  AvgDialog_97988_Content_35 = {
    Text = "Bạn hoàn toàn không quan tâm đến phản ứng của tôi, cũng không quan tâm đến kết cục của câu chuyện, bạn chẳng quan tâm đến điều gì cả."
  },
  AvgDialog_97988_Content_36 = {
    Text = "Hiện tại, nơi này chẳng còn khán giả nào, không cần tiếp tục diễn vở kịch tồi tệ này nữa."
  },
  AvgDialog_97988_Content_37 = {
    Text = "Cởi bỏ lớp giả dối của ngươi đi, Hỗn loạn… đứa con của quái vật."
  },
  AvgDialog_97988_Content_38 = {
    Text = "……………"
  },
  AvgDialog_97988_Content_39 = {
    Text = "Giọng nói của N đã im lặng lâu, bạn thậm chí có thể cảm nhận được khuôn mặt mang nụ cười vĩnh cửu của hắn hiếm khi xuất hiện vẻ bàng hoàng."
  },
  AvgDialog_97988_Content_4 = {
    Text = "Chi và thân thể biến dạng, cả người biến thành quái vật méo mó, chỉ còn lại cái đầu có hình dáng con người."
  },
  AvgDialog_97988_Content_40 = {
    Text = "Sau đó, thế giới đã cười."
  },
  AvgDialog_97988_Content_41 = {
    Text = "Hahaha! Hahaha! Hahaha! Hahaha! Hahaha! Hahaha!"
  },
  AvgDialog_97988_Content_42 = {
    Text = "Chính xác! Chính xác!! Thực ra tôi không quan tâm gì cả!"
  },
  AvgDialog_97988_Content_43 = {
    Text = "Dù là bạn, hay là các bạn, hay là tất cả những điều này, tôi cũng không quan tâm!"
  },
  AvgDialog_97988_Content_44 = {
    Text = "Chúng chỉ là một đạo cụ trên sân khấu này, một bối cảnh, một trang trí!"
  },
  AvgDialog_97988_Content_45 = {
    Text = "Tốt lắm, tốt lắm, trong khoảng thời gian dài này, bạn là người đầu tiên thật sự làm tôi vui vẻ bằng sức lực của chính mình!"
  },
  AvgDialog_97988_Content_46 = {
    Text = "Nói đi, bạn muốn gì? Như một phần thưởng để làm vui lòng tôi, tôi có thể biến bất kỳ mong ước nào của bạn thành hiện thực!"
  },
  AvgDialog_97988_Content_47 = {
    Text = "Dù có làm cho tất cả những điều này chưa bao giờ xảy ra, tôi cũng có thể hào phóng ban tặng cho bạn!"
  },
  AvgDialog_97988_Content_48 = {
    Text = "Bởi vì kết thúc thực sự không quan trọng, bạn chỉ hưởng thụ cảm giác này."
  },
  AvgDialog_97988_Content_49 = {
    Text = "Đúng·hoàn·toàn·chính·xác！Kết thúc như thế nào tôi hoàn toàn không quan tâm, tôi chỉ muốn... cảm giác được thưởng thức bất ngờ này!"
  },
  AvgDialog_97988_Content_5 = {
    Text = "Louis biến dị nặng nhất, quai hàm đã bắt đầu mở ra thành ba phần, từ đó vươn ra ba xúc tu dài đầy răng sắc."
  },
  AvgDialog_97988_Content_50 = {
    Text = "Thế giới vẫn đang cười vui, mỗi hạt cát, mỗi giọt nước, mỗi làn gió, đều đang cười vui từ tận đáy lòng."
  },
  AvgDialog_97988_Content_51 = {
    Text = "Kaitigula cúi đầu không nói, như thể thế giới này không liên quan đến cô."
  },
  AvgDialog_97988_Content_52 = {
    Text = "…………Thực ra, từ khi bước vào đây, tôi đã biết cách để giải quyết."
  },
  AvgDialog_97988_Content_53 = {
    Text = "Khi mặt trời đen tối đó mọc lên, cảm giác như sự khai sáng không ngừng nói cho tôi biết tôi cần phải làm gì."
  },
  AvgDialog_97988_Content_54 = {
    Text = "Mỗi tiếng súng vang lên, tôi cảm thấy trong người có thêm thứ gì đó không thể diễn tả."
  },
  AvgDialog_97988_Content_55 = {
    Text = "Nhưng tôi thực sự không muốn sử dụng phương pháp này."
  },
  AvgDialog_97988_Content_56 = {
    Text = "Tôi đã từng dẫn dắt mọi người vượt qua khó khăn, lần này tôi cũng muốn dẫn dắt mọi người sống với tư cách con người."
  },
  AvgDialog_97988_Content_57 = {
    Text = "Nhưng... tôi đã sai."
  },
  AvgDialog_97988_Content_58 = {
    Text = "Tôi lẽ ra nên hiểu rằng, có những điều không chỉ dựa vào niềm tin và ý chí là có thể làm được."
  },
  AvgDialog_97988_Content_59 = {
    Text = "Kaitigula nâng khẩu súng trong tay, đồng thời nhằm vào xác của chính mình và Gerard."
  },
  AvgDialog_97988_Content_6 = {
    Text = "Mỗi con quái vật đều có một lỗ đạn trên đầu, một phát chí mạng chính xác."
  },
  AvgDialog_97988_Content_60 = {
    Text = "Giữa súng dài và súng ngắn, được nạp hai viên đạn cuối cùng."
  },
  AvgDialog_97988_Content_61 = {
    Text = "Trò chơi này bạn đã thắng, N."
  },
  AvgDialog_97988_Content_62 = {
    Text = "Bạn đã thắng một cách hoàn toàn, tôi thua rồi, thua đến trắng tay."
  },
  AvgDialog_97988_Content_63 = {
    Text = "Kaitigula ngẩng đầu nhìn, nhìn về mặt trời đen đầy nụ cười."
  },
  AvgDialog_97988_Content_64 = {
    Text = "Nhưng tôi sẽ đưa mọi người về nhà, dù bằng cách nào."
  },
  AvgDialog_97988_Content_65 = {
    Text = "Và tôi sẽ ban cho bạn cái chết vĩnh viễn."
  },
  AvgDialog_97988_Content_66 = {
    Text = "Bùng————"
  },
  AvgDialog_97988_Content_67 = {
    Text = "……………"
  },
  AvgDialog_97988_Content_68 = {
    Text = "Hai tiếng súng vang lên cùng lúc, nòng súng phun ra vòng khói tròn, biến mất trong cát vàng."
  },
  AvgDialog_97988_Content_69 = {
    Text = "Nhưng nếu để ý kỹ, sẽ thấy trong vòng khói dường như có chút màu hổ phách."
  },
  AvgDialog_97988_Content_7 = {
    Text = "Bạn nhìn vào cơ thể đang tan chảy thành hình, khẽ cười và lắc đầu."
  },
  AvgDialog_97988_Content_70 = {
    Text = "……………"
  },
  AvgDialog_97988_Content_71 = {
    Text = "Ừm... được rồi, tôi rất mong chờ."
  },
  AvgDialog_97988_Content_72 = {
    Text = "Vậy trước khi cái chết vĩnh cửu đến, có lẽ nên đến đó tìm chút vui vẻ?"
  },
  AvgDialog_97988_Content_73 = {
    Text = "Dưới sự trêu chọc không mảy may quan tâm của N, thế giới lại chìm vào yên tĩnh, kẻ giật dây bắt đầu lập kế hoạch cho trò giải trí tiếp theo."
  },
  AvgDialog_97988_Content_74 = {
    Text = "Mọi thứ đều bình thường, giống như chuyến tàu chạy ổn định trên đường ray, sẽ không dừng lại vì sự ra đi của bất kỳ ai."
  },
  AvgDialog_97988_Content_75 = {
    Text = "Ôi! Hình như trước đây tôi có nghe kể về một câu chuyện thú vị ở Aran, không bằng đi xem thử nhé."
  },
  AvgDialog_97988_Content_76 = {
    Text = "Tốt lắm, cứ như vậy đi. Quý ông N thanh lịch nên chuẩn bị chuyển cảnh rồi."
  },
  AvgDialog_97988_Content_77 = {
    Text = "Mặt trời đen tối dần dần biến mất, lớp khí đen dày đặc bắt đầu tan biến, chuẩn bị đến rạp hát tiếp theo…"
  },
  AvgDialog_97988_Content_78 = {
    Text = "Thì đã đi như vậy sao? Điều này không phải là việc của một người lịch sự, thưa ông N của chúng tôi."
  },
  AvgDialog_97988_Content_79 = {Text = "?！"},
  AvgDialog_97988_Content_8 = {
    Text = "Có thể tôi cũng không thể rồi, chị gái."
  },
  AvgDialog_97988_Content_80 = {
    Text = "Hơi thở đen lại một lần nữa dâng trào, nhưng lần này không như trước đây vô tư bay loạn, mà là tập hợp bên cạnh mặt trời đen như chuẩn bị đối đầu với kẻ thù lớn."
  },
  AvgDialog_97988_Content_81 = {
    Text = "Cuộc gặp gỡ đầu tiên với bạn cũ lại cảnh giác như vậy."
  },
  AvgDialog_97988_Content_82 = {
    Text = "Nhưng tôi không chờ đợi một chút nào, không thể chờ đợi thêm mà đã đến ngay."
  },
  AvgDialog_97988_Content_83 = {
    Text = "Ngọn lửa màu hổ phách bùng cháy trên cơ thể Katie Gula, đứng lên bằng cách này dường như hoàn toàn trái ngược với cách thức sinh học của con người."
  },
  AvgDialog_97988_Content_84 = {
    Text = "Ngọn lửa này rực rỡ và nóng hổi, xé rách thân thể của Caitigula một cách vặn vẹo, tạo ra những vết nứt chói mắt."
  },
  AvgDialog_97988_Content_85 = {
    Text = "Chúng háo hức muốn xuống thế gian, đốt cháy mọi thứ thành tro."
  },
  AvgDialog_97988_Content_86 = {
    Text = "Có muốn cùng tôi nhảy một điệu không? Người bẩn thỉu N?"
  },
  AvgDialog_97988_Content_87 = {
    Text = "Ngọn lửa của Katygula đứng vững trên mặt đất, như một mặt trời thực sự."
  },
  AvgDialog_97988_Content_88 = {
    Text = "Khói đen che kín bầu trời đang bất an rung động, giọng nói nghiêm túc của N vang lên từ trên không trung."
  },
  AvgDialog_97988_Content_89 = {
    Text = "Bạn là… gì?"
  },
  AvgDialog_97988_Content_9 = {
    Text = "Không nói ra ký ức của Gerard trong đầu, bởi vì bạn nhận ra mình đã không thể nhớ được nữa."
  },
  AvgDialog_97988_Content_90 = {
    Text = "Hỏi đã hơi muộn rồi, tôi đã hỏi câu này trước khi bạn mời."
  },
  AvgDialog_97988_Content_91 = {
    Text = "Bây giờ bạn nên nói rằng — \"Chạy đi\"."
  },
  AvgDialog_97988_Content_92 = {
    Text = "Sức mạnh này... tại sao... sức mạnh này..."
  },
  AvgDialog_97988_Content_93 = {
    Text = "Có khi nào… à! Tôi đã hiểu rồi!"
  },
  AvgDialog_97988_Content_94 = {
    Text = "Sau một chút bối rối ngắn ngủi, N đột nhiên hô lớn trong sự phát giác."
  },
  AvgDialog_97988_Content_95 = {
    Text = "Hóa ra là như vậy! Tôi đã hiểu! Bạn thực sự đã được gã đó chọn rồi!"
  },
  AvgDialog_97988_Content_96 = {
    Text = "Thú vị nhỉ! Thật thú vị! Lại còn có chuyện này xảy ra!"
  },
  AvgDialog_97988_Content_97 = {
    Text = "Hơi thở đen biến thành khuôn mặt bất biến của N, các thần thánh trên bầu trời hiện ra với nụ cười rực rỡ nhất."
