  AvgDialog_97988_Content_98 = {
    Text = "Mặt trời đen hùng vĩ giờ đây trong miệng quỷ dữ, dường như nhỏ bé như vậy. Niềm vui tự thân cuối cùng cũng lột bỏ mọi che đậy, thể hiện sức mạnh thực sự của nó cho thế giới."
  },
  AvgDialog_97988_Content_99 = {
    Text = "Đến đây! Đến đây! Hãy để chúng ta chiến đấu với nhau! Đây là giao điểm của số phận!"
