  AvgDialog_98098_Content_24 = {
    Text = "Tôi đã quan sát kỹ trận đấu của bạn, nói thế nào nhỉ..."
  },
  AvgDialog_98098_Content_25 = {
    Text = "Hành động của bạn quả thật rất dũng cảm, nhưng bạn quá độc đoán, bóng chuyền là hợp tác, là trò chơi nhiều người."
  },
  AvgDialog_98098_Content_26 = {
    Text = "Hợp tác? Tất nhiên tôi sẽ, nhưng có một số thời điểm, với tư cách là chị cả, bạn không thể dễ dàng giao nhiệm vụ cho những người cấp dưới."
  },
  AvgDialog_98098_Content_27 = {
    Text = "Nhưng họ không phải là thuộc hạ của bạn."
  },
  AvgDialog_98098_Content_28 = {
    Text = "Tất nhiên, họ không bằng đàn em của tôi, nhưng đã là đội trưởng, tôi sẽ đảm nhận trách nhiệm chăm sóc những gánh nặng."
  },
  AvgDialog_98098_Content_29 = {
    Text = "Nhưng bóng chuyền..."
  },
  AvgDialog_98098_Content_3 = {
    Text = "Còn Jenkin nữa, để Nâu nhảy múa làm ảnh hưởng đến đối thủ cũng là phạm quy đấy nhé♡"
  },
  AvgDialog_98098_Content_30 = {
    Text = "Không có cái gì mà \"nhưng\" — Lời của bạn quá nhiều rồi."
  },
  AvgDialog_98098_Content_31 = {
    Text = "Pandia, khi nào trận đấu tiếp theo bắt đầu?"
  },
  AvgDialog_98098_Content_32 = {
    Text = "Ôi, đã không thể chờ đợi nữa sao? Vậy thì hãy bỏ qua thời gian chờ đợi tẻ nhạt, đi thẳng vào vấn đề ♡"
  },
  AvgDialog_98098_Content_33 = {
    Text = "Trận bán kết bóng chuyền bãi biển sắp bắt đầu!"
  },
  AvgDialog_98098_Content_4 = {
    Text = "Tại sao lại như vậy? Bạn chỉ nói không được sử dụng khả năng, Nâu là bạn tôi, không vi phạm quy tắc!"
  },
  AvgDialog_98098_Content_5 = {
    Text = "Không có chỗ cho việc mặc cả, những đứa trẻ không ngoan sẽ bị trừng phạt đấy♡"
  },
  AvgDialog_98098_Content_6 = {
    Text = "Hừ, thật phiền phức, vậy Leigh đâu? Cô ấy cố ý dùng mặt nhận bóng có tính là vi phạm không!?"
  },
  AvgDialog_98098_Content_7 = {
    Text = "Ôi~ Tôi vi phạm quy định à? Vậy thì Pandia, bạn sẽ trừng phạt tôi chứ? Hoặc, %player% sẽ trừng phạt tôi?"
  },
  AvgDialog_98098_Content_8 = {
    Text = "Tất cả đều được nhé, hãy cố gắng... cố gắng hơn nữa..."
  },
  AvgDialog_98099_Content_1 = {
    Text = "Cuộc đấu văn minh"
  },
  AvgDialog_98099_Content_10 = {
    Text = "Cô ấy không nói sai. An toàn của bạn còn quan trọng hơn \"người trong quả cầu lửa\"."
  },
  AvgDialog_98099_Content_11 = {
    Text = "Được thôi, việc do thám sẽ giao cho bạn, mọi người còn lại hãy giữ cảnh giác."
  },
  AvgDialog_98099_Content_12 = {
    Text = "Ngoài ra Tulu, làm ơn dùng nước biển để rửa bóng lửa, giảm nhiệt độ bóng lửa, tránh làm tổn thương Vòng lặp Ramona."
  },
  AvgDialog_98099_Content_13 = {
    Text = "Đúng là chỉ có bạn dám ra lệnh cho tôi như vậy."
  },
  AvgDialog_98099_Content_14 = {
    Text = "Nước biển bị thao túng chảy qua mặt đất cháy của nắng lặn, không ngừng bốc hơi thêm nhiều sương mù, Vòng lặp Ramona từ từ tiến vào trong màn sương dày đặc."
  },
  AvgDialog_98099_Content_15 = {
    Text = "Rất nhanh, trong sương mù truyền đến tiếng của Vòng lặp Ramona."
  },
  AvgDialog_98099_Content_16 = {
    Text = "Tất cả đều an toàn, có thể qua đây."
  },
  AvgDialog_98099_Content_17 = {
    Text = "Nghe thấy giọng nói bình yên của Vòng lặp Ramona, tâm tư bạn cuối cùng cũng thả lỏng, dẫn dắt mọi người đi tới."
  },
  AvgDialog_98099_Content_18 = {
    Text = "Lúc này, quả cầu lửa không còn nóng như lúc bắt đầu, những ngọn lửa thưa thớt dường như sắp tắt đi, bạn có thể nhìn rõ hình bóng người đang ngủ bên trong—— mái tóc vàng như mặt trời đang cháy rực."
  },
  AvgDialog_98099_Content_19 = {
    Text = "Khí trường mạnh mẽ quá, khi ngủ còn có khí thế không giận mà uy nghiêm... trong tay cô ấy là hai khẩu súng?"
  },
  AvgDialog_98099_Content_2 = {
    Text = "Sau một thời gian dài, làn sương trắng đặc quánh mới từ từ tan đi, mơ hồ hiện ra hình dáng của mặt trời rực rỡ."
  },
  AvgDialog_98099_Content_20 = {
    Text = "Có vẻ như đây là một người đánh thức rất mạnh mẽ."
  },
  AvgDialog_98099_Content_21 = {
    Text = "Ai mà mạnh miệng như vậy, chính cô ta khiến chúng ta cảm thấy nóng nực đến vậy? Để tôi xem thử."
  },
  AvgDialog_98099_Content_22 = {
    Text = "\"Thức tỉnh trong quả cầu lửa\" rõ ràng đã thu hút sự chú ý của tất cả mọi người, mọi người không khỏi tụ lại, xôn xao bàn tán."
  },
  AvgDialog_98099_Content_23 = {
    Text = "Ah... người mạnh mẽ hơn, lại càng muốn thấy cô quỳ dưới cái roi nhỏ ngọt ngào~"
  },
  AvgDialog_98099_Content_24 = {
    Text = "Điều quan trọng nhất hiện nay không phải là xác định cô ấy là kẻ thù hay bạn bè sao?"
  },
  AvgDialog_98099_Content_25 = {
    Text = "Tôi không có thói quen nuông chiều những đứa trẻ không nghe lời."
  },
  AvgDialog_98099_Content_26 = {
    Text = "Dù thế nào, tôi cũng sẽ bảo vệ tốt cho chủ nhân!"
  },
  AvgDialog_98099_Content_27 = {
    Text = "Thật tuyệt vời? Vậy tôi nhất định phải đánh nhau với cô ấy rồi."
  },
  AvgDialog_98099_Content_28 = {
    Text = "Ồn ào quá, là địch hay là bạn thì làm ơn đánh thức cô ấy lên đi có phải không? Tulu, hãy dập tắt ngọn lửa."
  },
  AvgDialog_98099_Content_29 = {
    Text = "Tại sao tôi phải nghe theo mệnh lệnh của ngươi?"
  },
  AvgDialog_98099_Content_3 = {
    Text = "Quả cầu lửa đó vẫn đang cháy như một sinh vật sống, và ở trung tâm của nó, một bóng hình người đang lung lay kỳ quái."
  },
  AvgDialog_98099_Content_30 = {
    Text = "Khi thấy bầu không khí trở nên căng thẳng, bạn vội vàng chen vào giữa vài người, mở miệng làm dịu bầu không khí."
  },
  AvgDialog_98099_Content_31 = {
    Text = "Ah, được rồi, điều này, Tulu, làm phiền bạn."
  },
  AvgDialog_98099_Content_32 = {
    Text = "Tulu vẫn im lặng, nhưng dòng nước trên mặt biển đã thay đổi, xoáy tròn lao về phía quả cầu lửa, dập tắt ngọn lửa cuối cùng."
  },
  AvgDialog_98099_Content_33 = {
    Text = "Cuối cùng, nước biển mặn đã chạm tới bóng người đang chìm trong giấc ngủ, một đôi mắt vàng từ từ mở ra."
  },
  AvgDialog_98099_Content_35 = {
    Text = "Cậu bước về phía trước, công khai danh tính của mình, nở một nụ cười thiện chí."
  },
  AvgDialog_98099_Content_36 = {
    Text = "Xin chào, tôi là người giữ gìn %player%."
  },
  AvgDialog_98099_Content_37 = {
    Text = "Nếu bạn chưa nghe qua cái tên \"người giữ gìn\", bạn có thể hiểu đơn giản là \"bạn của người đánh thức\"."
  },
  AvgDialog_98099_Content_38 = {
    Text = "Phải không? Bạn của người đánh thức?"
  },
  AvgDialog_98099_Content_39 = {
    Text = "Người phụ nữ đứng dậy từ mặt trời đã tắt, chậm rãi tiến về phía bạn, khẩu súng ngắn quay một vòng trong tay cô, gọn gàng nằm trong tay cô."
  },
  AvgDialog_98099_Content_4 = {
    Text = "Hình như ở trong đó có người!?"
  },
  AvgDialog_98099_Content_40 = {
    Text = "Nghe có vẻ không tệ, nhưng, tôi không cần bạn bè."
  },
  AvgDialog_98099_Content_41 = {
    Text = "Với một tiếng cười lạnh lẽo, nòng súng ngắn lạnh giá dừng lại trên trán bạn."
  },
  AvgDialog_98099_Content_42 = {Text = "%player%!"},
  AvgDialog_98099_Content_43 = {
    Text = "Mũi dao của Vòng lặp Ramona ngay lập tức dừng lại trước cổ của đối phương, những người đánh thức khác cũng đều nhăn mặt, sức mạnh tỏa ra, tạo nên không khí nặng nề đầy áp lực."
  },
  AvgDialog_98099_Content_44 = {
    Text = "Làm ơn để súng của bạn ra xa. Tôi không thích khi người khác đe dọa cún con của tôi."
  },
  AvgDialog_98099_Content_45 = {
    Text = "Chó con của bạn? Ha ha ha ha…"
  },
  AvgDialog_98099_Content_46 = {
    Text = "Cô gái tóc vàng cười ngả nghiêng, tay còn lại nắm lấy súng trường, một tay nạp đạn, hướng về phía trái tim bạn."
  },
  AvgDialog_98099_Content_47 = {
    Text = "Xin lỗi, tôi cũng không thích - bị người khác đe dọa."
  },
  AvgDialog_98099_Content_49 = {
    Text = "Bạn im lặng giơ tay ra, ra hiệu cho mọi người thư giãn."
  },
  AvgDialog_98099_Content_5 = {
    Text = "Cậu không thể không tiến về phía quả cầu lửa, nhưng rất nhanh, một hình bóng đã chặn cậu lại."
  },
  AvgDialog_98099_Content_50 = {
    Text = "Nhưng, %player%..."
  },
  AvgDialog_98099_Content_51 = {
    Text = "Ramona, hãy tin tôi. Là một người giữ gìn, tôi có khả năng giải quyết vấn đề."
  },
  AvgDialog_98099_Content_52 = {
    Text = "……Được rồi."
  },
  AvgDialog_98099_Content_53 = {
    Text = "Vòng lặp Ramona thu hồi thanh kiếm dài, những người đánh thức khác cũng thực hiện theo chỉ dẫn của bạn, ngay cả Búp bê hủy cũng giữ im lặng."
  },
  AvgDialog_98099_Content_54 = {
    Text = "Gặp bạn một câu nói đã khiến mọi người thay đổi, người phụ nữ tóc vàng hơi ngạc nhiên, rất nhanh sau đó mỉm cười thú vị."
  },
  AvgDialog_98099_Content_55 = {
    Text = "Người giữ gìn %player%... Thú vị thật."
  },
  AvgDialog_98099_Content_56 = {
    Text = "Nói đi, bạn chuẩn bị làm cách nào để\"giải quyết\" tôi? Nhớ chú ý đến lời nói của mình, vì tôi bất cẩn có thể sẽ run tay—"
  },
  AvgDialog_98099_Content_57 = {
    Text = "Mặc dù nói vậy nhưng tay cô ấy rất ổn định—nhưng hãy tin rằng chỉ cần bạn nói sai một câu, hai khẩu súng đó có thể ngay lập tức bắn vào đầu và tim của bạn."
  },
  AvgDialog_98099_Content_59 = {
    Text = "Tôi sẽ không \"giải quyết\" bạn. Vì bạn không phải là \"vấn đề\"."
  },
  AvgDialog_98099_Content_6 = {
    Text = "%player%， nguy hiểm, để tôi dẫn đường trước nhé."
  },
  AvgDialog_98099_Content_60 = {
    Text = "Ôi? Thú vị thật, rất ít người có thể nói ra những lời như vậy dưới sự kềm kẹp của súng tôi, tôi cứ nghĩ mọi người đều cho rằng tôi là một trận cuồng loạn."
  },
  AvgDialog_98099_Content_61 = {
    Text = "Khóe miệng cô ấy vẫn nở nụ cười tươi, nhưng ánh mắt lại đầy sát khí lạnh lẽo. Trong khoảnh khắc đó, nhiều người đã trở thành kẻ thù của cô ấy lướt qua tâm trí, tất nhiên, tất cả họ đều đã chết dưới hai khẩu súng này."
  },
  AvgDialog_98099_Content_62 = {
    Text = "Bạn im lặng nhìn cô ấy, cảm nhận được sát khí của cô ấy, nhưng không hề hoảng hốt."
  },
  AvgDialog_98099_Content_63 = {
    Text = "Cậu sẽ không giết tôi. Tôi không cảm nhận được hơi thở ác độc nào từ linh hồn cậu, cậu không phải là loại người giết người bừa bãi."
  },
  AvgDialog_98099_Content_64 = {
    Text = "Đương nhiên, để tôi giết người là rất đắt. Thêm vào đó, bạn có thể sai khiến bao nhiêu Người đánh thức như vậy—"
  },
  AvgDialog_98099_Content_65 = {
    Text = "Ánh mắt cô ấy lướt qua những người đánh thức xung quanh, cười lớn và vác khẩu súng dài trên vai."
  },
  AvgDialog_98099_Content_66 = {
    Text = "Nhưng nếu tha cho bạn, tôi cũng sẽ không vui."
  },
  AvgDialog_98099_Content_67 = {
    Text = "Tôi là người không thích bị thiệt thòi, làm thức dậy tôi khi đang ngủ, bạn phải trả giá."
  },
  AvgDialog_98099_Content_68 = {
    Text = "Cho tôi nhắc một câu, ngay cả khi không có %player%、bạn vẫn sẽ tỉnh lại."
  },
  AvgDialog_98099_Content_69 = {
    Text = "Bạn hạ xuống vị trí gần bờ biển, nước biển cuối cùng sẽ dập tắt quả cầu lửa."
  },
  AvgDialog_98099_Content_7 = {
    Text = "Nhưng mà……"
  },
  AvgDialog_98099_Content_70 = {
    Text = "Ôi, ôi, một cô gái lý trí, tôi hiểu mà, đó là lý do tôi không nổ súng ngay lập tức——"
  },
  AvgDialog_98099_Content_71 = {
    Text = "Cô gái tóc vàng nói và quay cổ tay, cùng lúc đó, mũi súng ngắn đang ép vào trán bạn cũng di chuyển theo chuyển động của cô."
  },
  AvgDialog_98099_Content_72 = {
    Text = "Nhưng việc bị đánh thức và việc tỉnh dậy chủ động, luôn luôn khác nhau. Bạn biết đó, khi người ta không ngủ đủ giấc, sẽ luôn có một cơn lửa vô danh ở ngực, tôi bây giờ cảm thấy có chút... khó mà bình tĩnh."
  },
  AvgDialog_98099_Content_73 = {
    Text = "Vậy thì chúng ta hãy chơi một trận, xả bớt cơn bực tức khi thức dậy của bạn."
  },
  AvgDialog_98099_Content_74 = {
    Text = "Thật đúng với sở thích của tôi!"
  },
  AvgDialog_98099_Content_75 = {
    Text = "Người phụ nữ cười ngạo nghễ, một khẩu súng nhắm vào những người đánh thức với vẻ mặt không thiện, thấy rõ đại chiến sắp nổ."
  },
  AvgDialog_98099_Content_76 = {
    Text = "Nhưng không phải dùng súng của bạn, mà là đấu bằng trò chơi bóng chuyền bãi biển."
