  AvgDialog_98099_Content_78 = {
    Text = "Bạn nói gì? Cậu bé, cậu đang đùa tôi à?"
  },
  AvgDialog_98099_Content_79 = {
    Text = "Tất cả các người đánh thức đều nhìn về phía bạn, ngạc nhiên vì lời đề xuất của bạn. Còn bạn, bình tĩnh và thậm chí còn có chút hồi tưởng."
  },
  AvgDialog_98099_Content_8 = {
    Text = "Vòng lặp Ramona nắm lấy tay bạn, ánh mắt kiên định."
  },
  AvgDialog_98099_Content_80 = {
    Text = "Dù thế nào, mọi người đến đây để nghỉ mát bên bờ biển, một kỳ nghỉ tuyệt vời làm sao có thể xảy ra những cảnh tượng thô lỗ như vậy?"
  },
  AvgDialog_98099_Content_81 = {
    Text = "Vậy nên nếu bạn không hài lòng, muốn đánh nhau, chúng ta hãy phân chia thắng bại trong trận đấu này."
