  AvgDialog_98099_Content_85 = {
    Text = "Đôi mắt vàng của người phụ nữ nhìn chằm chằm vào bạn vài giây, ngay khi bạn nghĩ rằng cô ấy sẽ nổi giận, cô ấy bỗng nhiên cười và thu súng lại."
  },
  AvgDialog_98099_Content_86 = {
