  AvgDialog_98100_Content_38 = {
    Text = "Tôi sẽ không trốn tránh trách nhiệm của mình, nhưng thưa Ngài, Ngài mới là trọng tài của chúng ta... xin hãy ra lệnh cho chúng tôi!"
