  AvgDialog_98101_Content_16 = {
    Text = "Được thôi..."
  },
  AvgDialog_98101_Content_17 = {
    Text = "Katie Gura ôm lấy cánh tay, thở dài, quay đầu nhìn bạn, biểu hiện không còn phấn khởi, mà ngược lại mang theo một chút bối rối."
