  AvgDialog_98101_Content_26 = {
    Text = "Trên sân đấu, mỗi người đều có trách nhiệm và cơ hội của riêng mình, không ai là \"lãnh đạo\" hay \"tiểu đệ\" mãi mãi."
  },
  AvgDialog_98101_Content_28 = {
    Text = "Có thể bạn nói đúng, đây chỉ là một cuộc thi, chứ không phải… cuộc sống."
  },
  AvgDialog_98101_Content_29 = {
