  AvgDialog_98101_Content_3 = {
    Text = "Bãi biển ban đêm không khác gì ban ngày, chỉ là trong màn đêm, mặt biển trở nên sâu thẳm và cô đơn hơn."
  },
  AvgDialog_98101_Content_30 = {
    Text = "……Bạn có thể cho tôi biết về quá khứ của bạn không? Là một người bạn, tôi muốn giúp bạn."
