  AvgDialog_98101_Content_31 = {
    Text = "Bạn bè ư? Nếu bạn không ở đây, mà ở quê nhà tôi và nói câu này, tôi chỉ nghĩ bạn điên rồi, hoặc tôi điên rồi."
