  AvgDialog_98101_Content_32 = {
    Text = "Trong thị trấn nơi tôi sinh ra, một mạng sống còn không đáng giá bằng một túi lương thực, những người như bạn và tôi gặp nhau ngẫu nhiên..."
  },
  AvgDialog_98101_Content_33 = {
    Text = "Nói như vậy, thú dữ có thể nuốt chửng tất cả chỉ để no bụng, bao gồm cả cha mẹ ruột. Còn người đói thì còn kinh khủng hơn cả thú dữ."
