  AvgDialog_98101_Content_34 = {
    Text = "Kaitigura dừng tay mân mê khẩu súng ngắn, vẻ mặt lạnh lùng, ngón trỏ vô thức đặt trên cò."
  },
  AvgDialog_98101_Content_35 = {
    Text = "Nhưng đây không phải quê hương của bạn, bạn cũng có khả năng bảo vệ bản thân."
  },
  AvgDialog_98101_Content_36 = {
    Text = "Đương nhiên, chỉ cần tôi muốn, tôi có thể giết hết những lãnh chúa tham lam đó. Nhưng, tôi không chỉ là tôi, hiểu chứ?"
