  AvgDialog_98101_Content_52 = {Text = "……!!!"},
  AvgDialog_98101_Content_53 = {
    Text = "Vòng lặp Ramona, Ryker, Clementine, đều là những người đánh thức mạnh mẽ như bạn, họ không cần sự bảo vệ từ trên cao, mà là sự ngang hàng, tôn trọng và lòng tin giữa các đồng đội."
  },
  AvgDialog_98101_Content_54 = {
    Text = "Nhưng so với những điều này, còn một điều quan trọng hơn."
