  AvgDialog_98101_Content_6 = {
    Text = "Nỗi buồn và nghi hoặc bị áp chế bởi sự nhộn nhịp ban ngày lại nổi lên."
  },
  AvgDialog_98101_Content_61 = {
    Text = "Bạn có vui không… Tôi chưa bao giờ nghĩ đến câu hỏi này trước đây."
  },
  AvgDialog_98101_Content_62 = {
    Text = "Caetigula thu lại khẩu súng ngắn, ngẩng đầu, lặng lẽ nhìn bầu trời đêm."
  },
  AvgDialog_98101_Content_63 = {
    Text = "Bạn không nói lời nào, cũng ngẩng đầu nhìn lên bầu trời xa xăm như nhung lam."
