  AvgDialog_98101_Content_64 = {
    Text = "Bầu trời đêm bên bờ biển đầy những vì sao, chúng lặng lẽ lắng nghe những tâm sự của các bạn, phát ra ánh sáng từ xa xôi, ánh sáng của hàng ngàn năm trước."
  },
  AvgDialog_98101_Content_65 = {Text = "Phù…"},
  AvgDialog_98101_Content_66 = {
    Text = "Caetigula thở dài một hơi, đứng lên từ giã bạn."
  },
  AvgDialog_98101_Content_67 = {
    Text = "Lời bạn nói, tôi sẽ xem xét."
  },
  AvgDialog_98101_Content_68 = {
    Text = "Khi bạn quay đầu lại để vẫy tay, Katie Gura đã biến mất khỏi tầm nhìn của bạn, chỉ có một cơn gió ấm áp lướt qua bên cạnh, bạn không khỏi lắc đầu cười nhẹ."
  },
  AvgDialog_98101_Content_69 = {
    Text = "Quả thật, kiểu chia tay của đại ca băng đảng nhỉ..."
  },
  AvgDialog_98101_Content_7 = {
    Text = "Tất cả những điều này đều không phải là \"thực tế\"… Tôi hiểu."
  },
  AvgDialog_98101_Content_70 = {
    Text = "Nói xong, bạn thở phào nhẹ nhõm, chậm rãi trở về phòng.\nÂm thanh sóng vẫn như cũ, lần này cho dù là bạn hay Katygula, đều rơi vào giấc ngủ sâu."
  },
  AvgDialog_98101_Content_8 = {
    Text = "Không phải là \"thực sự\"? Ý nghĩa là gì?"
  },
  AvgDialog_98101_Content_9 = {
    Text = "Giọng nói quen thuộc vang lên bên cạnh bạn, bạn quay đầu lại, một mái tóc vàng như ngọn lửa đang bay trong gió đêm."
  },
  AvgDialog_98102_Content_1 = {
    Text = "Bóng chuyền chạm nhẹ vào lưới, rơi xuống mặt đất, nhưng đã bị Ryker chặn lại, phản công lại."
  },
  AvgDialog_98102_Content_10 = {
    Text = "Sân bóng một lần nữa sôi động, giữa những âm thanh phá rách dày đặc, bóng chuyền bay ra khỏi sân với những vệt sáng mờ ảo."
  },
  AvgDialog_98102_Content_11 = {
    Text = "Dù cấm sử dụng khả năng, những người đánh thức vẫn thắp sáng sức mạnh cơ thể của họ, tốc độ chuyền bóng của cả hai bên ngày càng nhanh, bình luận của Pandia cũng không khỏi tăng tốc."
  },
  AvgDialog_98102_Content_12 = {
    Text = "Phản công! Đã bị chặn lại! Bóng được chuyền cho Clementine, lại bị chặn."
  },
  AvgDialog_98102_Content_13 = {
    Text = "Ốc xà cừ và 24 đều muốn nhận bóng, kết quả cả hai đều do dự trong khi nhường nhau, bóng chuyền đã — rơi xuống ngay lúc này!"
  },
  AvgDialog_98102_Content_14 = {
    Text = "Đội Kaitigura ghi điểm!"
  },
  AvgDialog_98102_Content_15 = {
    Text = "Phòng thủ của Ryker hoàn hảo không tì vết! Một đường chuyền đẹp"
  },
  AvgDialog_98102_Content_16 = {
