  },
  AvgDialog_98102_Content_21 = {
    Text = "Đáng ghét, tốc độ đánh bóng của cả hai bên quá nhanh, bình luận viên đã không theo kịp nhịp độ của họ rồi!"
  },
  AvgDialog_98102_Content_22 = {
    Text = "Pandia chống hông dừng lại để giải thích, mọi người đều tập trung nhìn chằm chằm vào sân bóng, chờ đợi cú phát bóng quyết định thắng thua."
  },
  AvgDialog_98102_Content_23 = {
