  AvgDialog_98102_Content_24 = {Text = "Caligula!"},
  AvgDialog_98102_Content_25 = {
    Text = "Giống như trận đấu lần trước, Katie Gula đã nhảy lên cao, cánh tay duỗi dài cố gắng chặn bóng chuyền."
